CatQuestExtendedVoicePack.quests = {
    [2] = { d = 17.5, v = "narrator", n = { x = 184 }, c = { x = { { 0.00, "Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы." }, { 8.07, "Сенани Громосерд на заставе Расщеплённого Древа несомненно пожелает увидеть этот трофей – доказательство ваших деяний." } } }, t = { d = 29.3, g = 1, v = "tauren-female", n = { m = 302, f = 303 }, c = { m = { { 0.00, "Очень впечатляет... коготь Острокогтя непросто добыть!" }, { 4.40, "Тебе везёт в охоте!" }, { 5.99, "Острокоготь давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщеплённого Древа." }, { 15.45, "Несомненно, скоро разойдётся весть, что именно ты прикончил чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!" } }, f = { { 0.00, "Очень впечатляет... коготь Острокогтя непросто добыть!" }, { 4.48, "Тебе везёт в охоте!" }, { 6.09, "Острокоготь давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщеплённого Древа." }, { 15.71, "Несомненно, скоро разойдётся весть, что именно ты прикончила чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!" } } } } },
    [5] = { d = 19.8, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев!" }, { 6.45, "Страшно хочется нормальной еды, и я за неё хорошо заплачу." }, { 10.64, "Устрой мне пир, и не пожалеешь." }, { 12.83, "Говорят, что шеф-повар Груаль в таверне \"Алый ворон\" делает превосходные тёмные пирожки с крабами..." } } }, t = { d = 4.9, v = "human-male", n = { x = 44 }, c = { x = { { 0.00, "Значит, тебе нужны пирожки с крабами?" }, { 3.23, "Что ж, могу испечь..." } } } } },
    [6] = { d = 22.2, g = 1, v = "human-male", n = { m = 267, f = 267 }, c = { m = { { 0.00, "Гаррик Тихокрад – головорез, который уже много недель не даёт покоя нашим крестьянам и торговцам." }, { 6.73, "Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом." }, { 12.73, "Принесёшь мне голову этого негодяя – получишь награду!" }, { 16.43, "Но будь осторожен." }, { 17.67, "Гаррик собрал разбойничью шайку." }, { 19.95, "До него непросто будет добраться." } }, f = { { 0.00, "Гаррик Тихокрад – головорез, который уже много недель не даёт покоя нашим крестьянам и торговцам." }, { 6.73, "Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом." }, { 12.73, "Принесёшь мне голову этого негодяя – получишь награду!" }, { 16.43, "Но будь осторожна." }, { 17.67, "Гаррик собрал разбойничью шайку." }, { 19.95, "До него непросто будет добраться." } } }, t = { d = 7.6, g = 1, v = "human-male", n = { m = 70, f = 72 }, c = { m = { { 0.00, "Ха!" }, { 0.31, "Ты его прикончил!" }, { 1.84, "Ты оказал большую услугу Элвину и заслуживаешь хорошей награды!" } }, f = { { 0.00, "Ха!" }, { 0.32, "Ты его прикончила!" }, { 2.00, "Ты оказала большую услугу Элвину и заслуживаешь хорошей награды!" } } } } },
    [7] = { d = 16.0, v = "human-male", n = { x = 186 }, c = { x = { { 0.00, "Первое твоё задание, – это зачистка." }, { 2.64, "Северные леса наводнили кобольды." }, { 5.08, "Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь." }, { 10.10, "Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья." } } }, t = { d = 13.5, v = "human-male", n = { x = 140 }, c = { x = { { 0.00, "Славная работа." }, { 1.26, "Эти кобольды – воры и трусы, но когда их много, они становятся опасны." }, { 6.83, "А людям Штормграда лишняя угроза не нужна." }, { 10.18, "Примите мою благодарность за хорошую работу." } } } } },
    [8] = { d = 35.1, g = 1, v = "scourge-male#83", n = { m = 389, f = 389 }, c = { m = { { 0.00, "Эй, приятель!" }, { 0.95, "Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками!" }, { 7.56, "У меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-её-там." }, { 14.10, "Неважно, какая у неё там фамилия!" }, { 16.45, "Да и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире." }, { 24.57, "Ты и сам сможешь там отдохнуть, если захочешь." }, { 27.81, "По крайней мере, ты должен туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу." } }, f = { { 0.00, "Эй, подруга!" }, { 0.91, "Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками!" }, { 7.64, "У меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-её-там." }, { 14.30, "Неважно, какая у неё там фамилия!" }, { 16.69, "Да и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире." }, { 24.98, "Ты и сама сможешь там отдохнуть, если захочешь." }, { 28.41, "По крайней мере, ты должна туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу." } } }, t = { d = 37.6, g = 1, v = "scourge-female#80", n = { m = 355, f = 356 }, c = { m = { { 0.00, "Ого!" }, { 0.46, "Письмо?" }, { 1.14, "Отличная новость!" }, { 2.66, "Я давно жду весточки от моей старушки-матери из Могильника." }, { 7.67, "Она настоящая святая – моя мать." }, { 10.48, "Как она там поживает..." }, { 12.46, "Что?" }, { 12.84, "Слишком фальшивлю?" }, { 14.43, "Не купился?" }, { 15.42, "Ну так отстань... тебе абсолютно не обязательно знать, от кого это письмо." }, { 21.65, "Давай, давай, иди отсюда!" }, { 23.93, "Возвращайся, когда будет что потратить... бродяга." }, { 28.18, "И вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости." } }, f = { { 0.00, "Ого!" }, { 0.45, "Письмо?" }, { 1.13, "Отличная новость!" }, { 2.64, "Я давно жду весточки от моей старушки-матери из Могильника." }, { 7.62, "Она настоящая святая – моя мать." }, { 10.42, "Как она там поживает..." }, { 12.38, "Что?" }, { 12.76, "Слишком фальшивлю?" }, { 14.34, "Не купилась?" }, { 15.40, "Ну так отстань... тебе абсолютно не обязательно знать, от кого это письмо." }, { 21.59, "Давай, давай, иди отсюда!" }, { 23.86, "Возвращайся, когда будет что потратить... бродяга." }, { 28.08, "И вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости." } } } } },
    [9] = { d = 29.6, v = "human-male", n = { x = 328 }, c = { x = { { 0.00, "Взгляните, во что превратилось это место!" }, { 2.97, "Когда-то эти земли населяли честные крестьяне." }, { 6.39, "Но проклятые воры выжили отсюда всех." }, { 9.10, "Только не меня!" }, { 10.26, "Однако угодья захватили големы – дозорные полей." }, { 13.81, "Если вы готовы поработать, я попросил бы вас пойти и убить двадцать таких големов." }, { 19.74, "Возвращайтесь за оплатой, когда всё будет сделано." }, { 23.36, "Когда расправитесь с теми, что обитают на моём поле, зачистите поля и моих соседей тоже." } } }, t = { d = 8.7, v = "human-male", n = { x = 94 }, c = { x = { { 0.00, "Отличная работа, дружище." }, { 2.03, "Вы полностью отработали свою плату." }, { 4.82, "Кто знает, может быть, Западный Край снова расцветёт." } } } } },
    [10] = { d = 32.3, v = "goblin-male", n = { x = 346 }, c = { x = { { 0.00, "Ох, это ужасно!" }, { 1.23, "Я послал моего лучшего помощника, младшего геодезиста Холстомера в пустыню, на юго-восток отсюда." }, { 8.64, "Именно там располагается Зияющая бездна." }, { 11.71, "Вот, а теперь он пропал, и в последнем докладе шла речь о странных насекомых." }, { 17.43, "Неужели они наводнили уже два основных района пустыни?" }, { 21.65, "Прошу тебя, доберись до Зияющей бездны и поищи там Холстомера!" }, { 26.41, "Его... или хотя бы оборудование." }, { 28.93, "Боюсь, больше от бедняги ничего и не осталось." } } }, t = { d = 25.7, v = "goblin-male", n = { x = 292 }, c = { x = { { 0.00, "Юный Холстомер был хорошим гоблином." }, { 2.67, "Будем надеяться, что его кончина не напрасна, и собранные перед смертью сведения не пропали даром." }, { 9.85, "Похоже, от этих жуков надо ждать неприятностей." }, { 13.30, "Они слишком хитры, но все исследования указывают на то, что эти твари находятся под влиянием третьей стороны!" }, { 21.19, "Коли так, беда грозит не только Прибамбасску, но и всей пустыне!" } } } } },
    [11] = { d = 31.6, v = "human-male", n = { x = 393 }, c = { x = { { 0.00, "На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях." }, { 7.63, "К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться." }, { 15.87, "Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов." }, { 20.86, "Армия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой." }, { 26.27, "В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов." } } }, t = { d = 4.8, v = "human-male", n = { x = 50 }, c = { x = { { 0.00, "О, вижу, ты слов на ветер не бросаешь!" }, { 2.93, "Прими нашу благодарность." } } } } },
    [12] = { d = 39.4, v = "human-male", n = { x = 478 }, c = { x = { { 0.00, "У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир." }, { 6.18, "К сожалению, приходится это делать путём кровопролития." }, { 9.88, "Один из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику." }, { 18.24, "У меня есть сообщения, что звероловов Братства замечали около Рудника Янго к северо-западу отсюда, а также неподалёку от фермы Мольсена и тыквенной фермы Хмуроброва." }, { 29.32, "Если ты хочешь присоединиться к ополчению, убей пятнадцать звероловов и пятнадцать контрабандистов из Братства Справедливости, а затем возвращайся ко мне." } } }, t = { d = 7.8, v = "human-male", n = { x = 94 }, c = { x = { { 0.00, "Отличная работа." }, { 1.18, "Мой разведчик был свидетелем твоих доблестных деяний." }, { 4.85, "Пока что с тобой очень приятно иметь дело." } } } } },
    [13] = { d = 30.7, g = 1, v = "human-male", n = { m = 370, f = 371 }, c = { m = { { 0.00, "Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона." }, { 8.57, "Народное ополчение не потерпит этого." }, { 11.12, "Разберись с этим немедленно, и пусть весь Западный Край узнает о силе Света." }, { 16.22, "Прииск на Золотом Берегу находится неподалёку от побережья, к западу от башни." }, { 21.44, "В качестве следующего этапа твоего обучения я хочу, чтобы ты убил пятнадцать погромщиков и пятнадцать мошенников из Братства Справедливости." } }, f = { { 0.00, "Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона." }, { 8.48, "Народное ополчение не потерпит этого." }, { 11.01, "Разберись с этим немедленно, и пусть весь Западный Край узнает о силе Света." }, { 16.06, "Прииск на Золотом Берегу находится неподалёку от побережья, к западу от башни." }, { 21.24, "В качестве следующего этапа твоего обучения я хочу, чтобы ты убила пятнадцать погромщиков и пятнадцать мошенников из Братства Справедливости." } } }, t = { d = 5.6, v = "human-male", n = { x = 73 }, c = { x = { { 0.00, "Ваша значимость для народного ополчения была подкреплена вашими смелыми действиями." } } } } },
    [14] = { d = 23.6, v = "human-male", n = { x = 288 }, c = { x = { { 0.00, "Некоторые члены Братства Справедливости от нас ускользнули." }, { 4.05, "Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края." }, { 14.15, "Мы считаем, что они скрываются в Холмах Разбойничьих Кинжалов, замышляя новые бесчинства." }, { 20.31, "Убей этих негодяев от имени народного ополчения." } } }, t = { d = 22.6, v = "human-male", n = { x = 256 }, c = { x = { { 0.00, "Я покинул разорённые земли Лордерона, вернувшись на свою родину... и застал её в столь же ужасном состоянии." }, { 7.77, "Но для Западного Края ещё есть надежда." }, { 10.60, "Проявленная тобой доблесть доказала, что ты с честью служишь нашему делу." }, { 15.99, "С огромной гордостью я принимаю тебя в ряды народного ополчения." }, { 20.73, "Да воссияет над тобой Свет!" } } } } },
    [15] = { d = 21.1, v = "human-male", n = { x = 261 }, c = { x = { { 0.00, "Мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали." }, { 6.29, "Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда." }, { 11.80, "Отправляйся к шахте и уничтожь их." }, { 14.07, "Насколько нам известно, кобольдов там много..." }, { 17.13, "Убей-ка десяток, посмотри, сколько ещё осталось, и доложи мне." } } }, t = { d = 14.2, g = 1, v = "human-male", n = { m = 158, f = 159 }, c = { m = { { 0.00, "Меня тревожат сообщения о кобольдах на нашем руднике." }, { 3.75, "К добру это не приведёт." }, { 5.44, "Вот, это твоя награда." }, { 7.07, "Когда будешь готов, приходи ко мне." }, { 9.57, "Буду рад, если ты согласишься предпринять ещё одну вылазку..." } }, f = { { 0.00, "Меня тревожат сообщения о кобольдах на нашем руднике." }, { 3.87, "К добру это не приведёт." }, { 5.61, "Вот, это твоя награда." }, { 7.28, "Когда будешь готова, приходи ко мне." }, { 9.92, "Буду рад, если ты согласишься предпринять ещё одну вылазку..." } } } } },
    [16] = { t = { d = 4.2, v = "human-male#50", n = { x = 43 }, c = { x = { { 0.00, "Благодарю!" }, { 0.89, "Решишь ещё со мной поторговаться – заходи." } } } } },
    [17] = { d = 37.4, v = "dwarf-male", n = { x = 432 }, c = { x = { { 0.00, "Мне рассказали о недавно открытом растении, грибе-малиновике." }, { 4.48, "Этот гриб растёт целыми колониями на раскопках Ульдамана, в самой глубине." }, { 9.80, "Наверное, встречается ещё где-то, но мне известно только одно место." }, { 14.72, "Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься." }, { 21.39, "Отыщи эти грибы и принеси мне дюжину." }, { 24.18, "Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнёшь." }, { 30.39, "Если выполнишь моё поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!" } } }, t = { d = 23.1, g = 1, v = "dwarf-male", n = { m = 264, f = 265 }, c = { m = { { 0.00, "Молодец, ты снова показал, на что способен!" }, { 3.02, "Эти грибы мне очень пригодятся для исследований!" }, { 6.41, "А теперь, как я и обещал, можешь насладиться вкусом одного из моих восстановительных составов из личных запасов..." }, { 14.33, "Если ты тоже увлекаешься алхимией, мы можем вдобавок поговорить и о других делах." }, { 20.05, "В любом случае, благодарю за помощь!" } }, f = { { 0.00, "Молодец, ты снова показала, на что способна!" }, { 3.16, "Эти грибы мне очень пригодятся для исследований!" }, { 6.64, "А теперь, как я и обещал, можешь насладиться вкусом одного из моих восстановительных составов из личных запасов..." }, { 14.76, "Если ты тоже увлекаешься алхимией, мы можем вдобавок поговорить и о других делах." }, { 20.62, "В любом случае, благодарю за помощь!" } } } } },
    [18] = { d = 17.7, v = "human-male", n = { x = 194 }, c = { x = { { 0.00, "Тут возле Североземья недавно новая воровская шайка завелась." }, { 4.64, "Зовут себя Братством Справедливости." }, { 7.40, "Видели их за рекой, на востоке." }, { 9.75, "Не знаю, что у них на уме, но наверняка ничего хорошего!" }, { 13.93, "Принеси мне их банданы, и в награду получишь оружие." } } }, t = { d = 6.3, g = 1, v = "human-male", n = { m = 63, f = 64 }, c = { m = { { 0.00, "Ага, вижу, ты вернулся не с пустыми руками." }, { 3.52, "Армия Штормграда ценит твою помощь." } }, f = { { 0.00, "Ага, вижу, ты вернулась не с пустыми руками." }, { 3.56, "Армия Штормграда ценит твою помощь." } } } } },
    [19] = { d = 15.7, v = "human-male", n = { x = 182 }, c = { x = { { 0.00, "Вестники и отступники из клана Чёрной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи." }, { 8.89, "Их предводитель – орк по имени Тарил'зун." }, { 11.80, "Он уже натворил достаточно дел." }, { 14.07, "Принеси мне его голову!" } } }, t = { d = 8.9, v = "human-male", n = { x = 88 }, c = { x = { { 0.00, "Тарил'зун был жестоким и коварным орком." }, { 3.28, "Ты молодчина – я знаю, справиться с ним было нелегко." }, { 7.58, "Вот твоя награда." } } } } },
    [20] = { d = 32.0, v = "human-male", n = { x = 385 }, c = { x = { { 0.00, "К нам явились орки Чёрной Горы из Пылающих степей и захватили крепость Каменной Стражи." }, { 5.95, "Они грабят области к северу от Озёр, и жители тех земель бежали в город, набились в него, словно сельди в бочку." }, { 13.68, "Помоги Приозёрью избавиться от этой угрозы." }, { 16.62, "Перебей орков Чёрной Горы и принеси в доказательство десять иззубренных топоров." }, { 22.08, "Хотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья." }, { 29.32, "Если встретишь их – убивай без колебаний." } } }, t = { d = 4.9, v = "human-male", n = { x = 44 }, c = { x = { { 0.00, "Что ж, чем меньше орков, тем лучше." }, { 3.07, "Большое тебе спасибо." } } } } },
    [21] = { d = 17.8, v = "human-male", n = { x = 226 }, c = { x = { { 0.00, "Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку." }, { 6.84, "Возвращайся на рудник и помоги очистить его от кобольдов." }, { 10.72, "Время дорого." }, { 11.68, "Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье." } } }, t = { d = 13.1, g = 1, v = "human-male", n = { m = 154, f = 155 }, c = { m = { { 0.00, "Ты снова заслужил мою похвалу и благодарность армии Штормграда." }, { 4.48, "В руднике ещё достаточно кобольдов, но я отправлю других новобранцев бороться с ними." }, { 10.40, "Для тебя имеются другие поручения." } }, f = { { 0.00, "Ты снова заслужила мою похвалу и благодарность армии Штормграда." }, { 4.66, "В руднике ещё достаточно кобольдов, но я отправлю других новобранцев бороться с ними." }, { 10.74, "Для тебя имеются другие поручения." } } } } },
    [22] = { d = 16.5, v = "human-female#47", n = { x = 155 }, c = { x = { { 0.00, "Лук очищен." }, { 0.99, "Чеснок раздавлен." }, { 2.51, "Розмарин измельчён." }, { 4.10, "Основа выпечена." }, { 5.55, "Укроп нарезан." }, { 6.84, "Соус вымешан до гладкости." }, { 9.12, "Всё, что мне ещё нужно для моего знаменитого пирога – это восемь кусков печени жутеклыка!" } } }, t = { d = 14.6, g = 1, v = "human-female#47", n = { x = 158 }, c = { m = { { 0.00, "Замечательные куски!" }, { 1.48, "Большое тебе спасибо!" }, { 3.08, "Мы с фермером Сальденом устроим сегодня настоящий праздник." }, { 7.31, "А это – для тебя, за труды." }, { 9.30, "У тебя ведь не было мысли, что герой вроде тебя останется без угощения, а?" } }, f = { { 0.00, "Замечательные куски!" }, { 1.48, "Большое тебе спасибо!" }, { 3.09, "Мы с фермером Сальденом устроим сегодня настоящий праздник." }, { 7.33, "А это – для тебя, за труды." }, { 9.32, "У тебя ведь не было мысли, что героиня вроде тебя останется без угощения, а?" } } } } },
    [23] = { d = 24.3, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Вот лапа могучего медведя Топтыжня – ваш трофей этого этапа охоты." }, { 5.70, "На лапе есть маленький знак – месяц." }, { 8.74, "Смысл этого знака покрыт тайной." }, { 11.55, "Эту лапу надо отнести Сенани Громосерд на заставу Расщеплённого Древа, чтобы доказать, что вы одолели могучую тварь, тем самым завершив этот этап охоты." } } }, t = { d = 31.0, g = 1, v = "tauren-female", n = { x = 282 }, c = { m = { { 0.00, "О, лапа Топтыжня!" }, { 1.52, "Твои навыки меня впечатлили, герой." }, { 4.64, "Говорят, он многих убил." }, { 6.77, "Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу." }, { 15.43, "Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях." }, { 23.11, "Убить такую тварь – истинное испытание воли и решимости." }, { 27.90, "Твои предки гордились бы тобой!" } }, f = { { 0.00, "О, лапа Топтыжня!" }, { 1.54, "Твои навыки меня впечатлили, героиня." }, { 4.85, "Говорят, он многих убил." }, { 7.01, "Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу." }, { 15.79, "Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях." }, { 23.57, "Убить такую тварь – истинное испытание воли и решимости." }, { 28.42, "Твои предки гордились бы тобой!" } } } } },
    [24] = { d = 20.6, v = "narrator", n = { x = 210 }, c = { x = { { 0.00, "Некогда стремительный Тенумбра лежит у ваших ног." }, { 4.07, "Вы победили." }, { 5.10, "Голова убитого ночного саблезуба – достойный трофей этой схватки в ходе охоты." }, { 11.69, "Сенани Громосерд на заставе Расщеплённого Древа захочет увидеть ваш трофей и наградить вас за этот этап охоты." } } }, t = { d = 27.3, v = "tauren-female", n = { x = 276 }, c = { x = { { 0.00, "Победа на охоте в Ясеневом лесу!" }, { 2.74, "Отлично!" }, { 3.48, "Голова Тенумбры, вне всякого сомнения, – достойный трофей столь впечатляющей схватки." }, { 10.43, "Дикий нрав Тенумбры был хорошо известен на заставе." }, { 14.64, "Из-за этого чудовища любое путешествие от Зорамского взморья на запад, особенно пешком, было рискованным." }, { 23.37, "Благодаря тебе этой угрозы больше не существует." } } } } },
    [25] = { d = 35.3, g = 1, v = "orc-male", n = { m = 377, f = 378 }, c = { m = { { 0.00, "Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя?" }, { 6.80, "Сообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на всё, что только подойдёт поближе... то есть, на всё, что на дороге." }, { 20.19, "Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса." }, { 32.85, "Ну, готов принести пользу?" } }, f = { { 0.00, "Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя?" }, { 6.89, "Сообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на всё, что только подойдёт поближе... то есть, на всё, что на дороге." }, { 20.48, "Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса." }, { 33.31, "Ну, готова принести пользу?" } } }, t = { d = 26.6, g = 1, v = "orc-male", n = { m = 280, f = 281 }, c = { m = { { 0.00, "Да я слышал, как что-то пролетело по озеру подобно пыльной буре Степей." }, { 5.47, "По звуку мы сможем найти пригодный наблюдательный пункт, чтобы присматривать за нашими друзьями из Альянса." }, { 13.54, "Да, только если будем сидеть тихо..." }, { 16.41, "Похоже, от тебя тут больше толку не будет – сообщение между здешними местами и Каменным Когтем налажено." }, { 24.42, "Возьми вот это – заслужил." } }, f = { { 0.00, "Да я слышал, как что-то пролетело по озеру подобно пыльной буре Степей." }, { 5.51, "По звуку мы сможем найти пригодный наблюдательный пункт, чтобы присматривать за нашими друзьями из Альянса." }, { 13.63, "Да, только если будем сидеть тихо..." }, { 16.52, "Похоже, от тебя тут больше толку не будет – сообщение между здешними местами и К