    [28] = { d = 37.4, v = "nightelf-male#54", n = { x = 423 }, c = { x = { { 0.00, "Вот твоё первое испытание – исследуй глубины озера Элуны и найди безделушку святилища." }, { 6.36, "Она быстро разрушается, так что не медля отнеси её к святилищу Ремулоса." }, { 11.66, "Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны." }, { 21.14, "На всё испытание тебе даётся ограниченное количество времени, и возможно, тебе придётся соревноваться с другими друидами, которые тоже ищут безделушки." }, { 32.14, "Быстрота ума и ловкость тела помогут тебе добиться успеха." }, { 36.58, "Удачи тебе." } } }, t = { d = 30.5, g = 1, v = "nightelf-female#52", n = { m = 321, f = 322 }, c = { m = { { 0.00, "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера!" }, { 4.98, "Хвалю тебя, мой юный друг." }, { 7.02, "Как я уже сказала, моё имя Таджарри." }, { 9.81, "Мой долг и привилегия – оберегать Лунную поляну и, в особенности, это святилище." }, { 15.81, "Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело." }, { 25.08, "Использовав здесь безделушку, ты отдал дань уважения этому месту." } }, f = { { 0.00, "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера!" }, { 5.07, "Хвалю тебя, мой юный друг." }, { 7.15, "Как я уже сказала, моё имя Таджарри." }, { 10.00, "Мой долг и привилегия – оберегать Лунную поляну и, в особенности, это святилище." }, { 16.11, "Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело." }, { 25.56, "Использовав здесь безделушку, ты отдала дань уважения этому месту." } } } } },
