    [30] = { d = 32.2, v = "nightelf-female#52", n = { x = 403 }, c = { x = { { 0.00, "Вот твоё второе испытание – тебе понадобятся две половинки подвески Морского Льва." }, { 5.43, "Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва." }, { 16.00, "Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика." }, { 21.07, "Поговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить." }, { 28.86, "Сделав это, отнеси подвеску Дендриту Блеску Звёзд." } } }, t = { d = 31.3, g = 1, v = "nightelf-male#54", n = { m = 323, f = 323 }, c = { m = { { 0.00, "Ты прошёл испытание Морского Льва." }, { 2.71, "Прими мои поздравления." }, { 4.69, "Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой." }, { 15.61, "Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва." }, { 24.03, "Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." } }, f = { { 0.00, "Ты прошла испытание Морского Льва." }, { 2.70, "Прими мои поздравления." }, { 4.62, "Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой." }, { 15.20, "Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва." }, { 23.38, "Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." } } } } },
    [31] = { d = 30.2, g = 1, v = "nightelf-male#54", n = { m = 312, f = 314 }, c = { m = { { 0.00, "Ты завершил обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик." }, { 8.60, "Теперь возвращайся к своему наставнику, Тюраку Руническому Тотему в Громовой Утёс." }, { 15.12, "Покажи ему свою подвеску и докажи, что ты готов усвоить его уроки." }, { 20.57, "Он завершит твоё обучение, благодаря которому ты станешь единым с водой." }, { 26.30, "Доброго тебе пути, юный друид." }, { 28.88, "Мы ещё встретимся." } }, f = { { 0.00, "Ты завершила обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик." }, { 8.42, "Теперь возвращайся к своему наставнику, Тюраку Руническому Тотему в Громовой Утёс." }, { 14.76, "Покажи ему свою подвеску и докажи, что ты готова усвоить его уроки." }, { 20.12, "Он завершит твоё обучение, благодаря которому ты станешь единой с водой." }, { 25.69, "Доброго тебе пути, юный друид." }, { 28.20, "Мы ещё встретимся." } } }, t = { d = 26.6, g = 1, v = "tauren-male#67", n = { m = 249, f = 250 }, c = { m = { { 0.00, "Великолепно." }, { 1.12, "Твои предки могут гордиться твоими успехами!" }, { 5.20, "Ты готов принять водный облик, и я с радостью научу тебя этому." }, { 10.96, "Прими также эту вещицу в знак признания твоих успехов в двух испытаниях." }, { 17.44, "Надеюсь, тебе будет приятно присоединить её к своему снаряжению защитника Природы и хранителя равновесия." } }, f = { { 0.00, "Великолепно." }, { 1.08, "Твои предки могут гордиться твоими успехами!" }, { 5.00, "Ты готова принять водный облик, и я с радостью научу тебя этому." }, { 10.61, "Прими также эту вещицу в знак признания твоих успехов в двух испытаниях." }, { 16.84, "Надеюсь, тебе будет приятно присоединить её к своему снаряжению защитника Природы и хранителя равновесия." } } } } },
    [32] = { d = 30.5, v = "goblin-male", n = { x = 346 }, c = { x = { { 0.00, "Вот твой отчёт." }, { 1.04, "Прошу тебя, отнеси его кому-нибудь, сведущему в такого рода вопросах." }, { 6.15, "Я слышал про учёного-тролля по имени Зилзибин Барабанный Бой." }, { 10.49, "Он посвятил много времени изучению форм жизни, встречающихся лишь в Азероте; он и историк заодно!" }, { 17.42, "Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к нему." }, { 24.60, "Нам любая помощь не помешает." }, { 26.74, "Его дом находится во втором ряду Волока в Оргриммаре." } } }, t = { d = 34.6, v = "troll-male#77", n = { x = 348 }, c = { x = { { 0.00, "Что до твоего отчёта... да, я уже встречался с этими тварями." }, { 4.88, "Рудознатец правильно поступил, отправив это письмо и тебя ко мне." }, { 10.19, "Эти существа мигом пожрут всю пустыню Танарис; они представляют собой одну из величайших опасностей, с которой только можно столкнуться." }, { 21.32, "Знакомься – это силитиды." }, { 23.43, "Так зовутся странные насекомые, которые служат величайшему злу, грозящему и Орде, и Альянсу." }, { 30.86, "Жаль, что нам не хватило ума понять это раньше." } } } } },
    [33] = { d = 18.9, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Ненавижу этих мерзких лесных волков!" }, { 2.63, "Но я бы не прочь полакомиться бифштексами из волчатины..." }, { 6.45, "Принеси мне жёсткой волчатины, и в обмен я предложу тебе что-нибудь полезное." }, { 11.76, "Убей несколько лесных волков и молодых волков, что водятся в североземских лесах, и принеси мне их мясо." } } }, t = { d = 9.1, g = 1, v = "human-male", n = { m = 94, f = 95 }, c = { m = { { 0.00, "Ну, ты на славу постарался!" }, { 2.11, "Прямо не терпится поджарить волчатинки..." }, { 5.34, "У меня есть кое-что интересное для тебя – выбирай!" } }, f = { { 0.00, "Ну, ты на славу постаралась!" }, { 2.14, "Прямо не терпится поджарить волчатинки..." }, { 5.32, "У меня есть кое-что интересное для тебя – выбирай!" } } } } },
    [34] = { d = 27.4, v = "human-female#47", n = { x = 316 }, c = { x = { { 0.00, "Мой сад снова разграблен и вытоптан." }, { 2.52, "И я знаю, кто это сделал!" }, { 4.36, "Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом." }, { 8.90, "Теперь мне долго не удастся посадить нарциссы." }, { 12.18, "Они загублены!" }, { 13.26, "И во всём виноват мерзкий кабан." }, { 15.53, "Положи конец этому паразиту!" }, { 17.61, "Принеси мне его клык, и я с удовольствием вознагражу тебя." }, { 21.65, "Говорят, он пасётся в полях на юго-западе от Озёр, но порой заходит и сюда, в мой сад." } } }, t = { d = 10.1, g = 1, v = "human-female#47", n = { m = 107, f = 108 }, c = { m = { { 0.00, "Наконец-то моему саду ничего не грозит!" }, { 3.17, "Спасибо тебе, ты оказал мне большую услугу." }, { 6.63, "Теперь мой сад расцветёт с небывалой пышностью!" } }, f = { { 0.00, "Наконец-то моему саду ничего не грозит!" }, { 3.08, "Спасибо тебе, ты оказала мне большую услугу." }, { 6.50, "Теперь мой сад расцветёт с небывалой пышностью!" } } } } },
    [35] = { d = 16.5, v = "human-male", n = { x = 206 }, c = { x = { { 0.00, "Если ты думаешь, что слухи о мурлоках могут оказаться правдой, отправляйся к восточному мосту Элвиннского леса и поговори со стражником Томасом." }, { 9.57, "Он уже неделю несёт стражу у моста и должен знать, что там происходит на самом деле." }, { 15.13, "Принеси мне его отчёт." } } }, t = { d = 13.0, v = "human-male", n = { x = 142 }, c = { x = { { 0.00, "Да, это правда: мурлоки поселились в реках и на их берегах в восточной части леса." }, { 5.99, "Мы не знаем, почему они пришли сюда, но их следует остерегаться: они агрессивны и довольно умны." } } } } },
    [36] = { d = 24.0, v = "human-female", n = { x = 280 }, c = { x = { { 0.00, "Никогда я не думала, что наступит день, когда я покину ферму." }, { 4.26, "Но поля кишат разбойниками, и для нас теперь тут слишком опасно." }, { 8.72, "Как только фермер Хмуробров починит повозку, мы отправимся в путь." }, { 13.29, "Может быть, ты окажешь мне услугу?" }, { 15.68, "Я напишу рецепт похлёбки Западного Края, а ты отнесёшь его Сальме Сальден вон на ту ферму – она сразу за развилкой дороги." } } }, t = { d = 18.1, v = "human-female#47", n = { x = 206 }, c = { x = { { 0.00, "Эта Верна всегда была такой милой девушкой." }, { 3.22, "Нам будет её не хватать здесь, в Западном Крае, но, только между нами, в душе она – городская жительница, и Штормград – местечко как раз для неё." }, { 13.28, "Ладно, хватит сплетничать!" }, { 15.17, "Начнём же готовить похлёбку Западного Края!" } } } } },
    [37] = { d = 20.2, v = "human-male", n = { x = 230 }, c = { x = { { 0.00, "Несколько дней назад мы отправили на обследование берегов реки двух наших стражей, Рольфа и Малакаи; ни один из них до сих пор не вернулся." }, { 9.80, "Чтобы составить полный отчёт, мне нужно выяснить, что с ними случилось." }, { 14.89, "Отправляйся на север вдоль реки и разыщи стражей... или хотя бы их останки." } } }, t = { d = 8.0, v = "narrator", n = { x = 81 }, c = { x = { { 0.00, "Хотя на трупе мало что осталось, рядом с ним оказался медальон с надписью \"Камень пехотинца Малакаи\"." } } } } },
    [38] = { d = 12.9, v = "human-female#47", n = { x = 129 }, c = { x = { { 0.00, "Помоги мне сварить похлёбку Западного Края!" }, { 3.40, "Мне нужны для неё следующие ингредиенты:" }, { 6.52, "Три куска жилистого мяса стервятника" }, { 9.42, "Три рыла жутеклыка" }, { 10.91, "Три глаза мурлока" }, { 12.32, "Три окры" } } }, t = { d = 18.2, v = "human-female#47", n = { x = 203 }, c = { x = { { 0.00, "Окра отлично загустит бульон!" }, { 2.31, "А теперь мы просто добавим жилистого мяса стервятника, несколько глаз мурлока и эти вкуснейшие рыла жутеклыка." }, { 10.65, "И вот всё готово!" }, { 11.94, "За оказанную помощь, я предлагаю тебе отведать первую порцию похлёбки Западного Края." } } } } },
    [39] = { d = 14.2, v = "human-male", n = { x = 171 }, c = { x = { { 0.00, "Нужно сообщить маршалу Дугхану о смерти Малакаи и Рольфа." }, { 3.92, "Наши войска на востоке Элвиннского леса не смогут справиться с мурлоками." }, { 8.87, "Я знаю, лишних солдат у нас нет, но, может, Дугхан пришлёт хоть какую-то помощь..." } } }, t = { d = 16.1, v = "human-male", n = { x = 173 }, c = { x = { { 0.00, "Да, вести невесёлые..." }, { 1.58, "Людей у нас и так немного, а теперь, когда мурлоки прикончили Рольфа и Малакаи, будет и вовсе несладко." }, { 9.13, "Если положение не изменится к лучшему, боюсь, к концу недели бои будут идти уже в Златоземье..." } } } } },
    [40] = { d = 23.7, v = "human-male", n = { x = 299 }, c = { x = { { 0.00, "В Элвиннском лесу появилась новая напасть." }, { 2.84, "Мурлоки поднялись вверх по рекам в восточной части леса, они распугивают рыбу и нападают на мирных жителей." }, { 9.95, "Я предупреждал маршала Дугхана, но его больше беспокоит нашествие гноллов и бандитов." }, { 15.58, "Мурлоков он вообще не принимает в расчёт." }, { 18.25, "Я прошу тебя, поговори с Дугханом и постарайся убедить его послать отряд на восток!" } } }, t = { d = 19.1, v = "human-male", n = { x = 213 }, c = { x = { { 0.00, "Да, верно, я говорил с Реми." }, { 2.10, "Поверь, я очень высоко ценю его как торговца, но все отчёты о появлении мурлоков на востоке крайне недостоверны." }, { 10.26, "Я понимаю твою тревогу, но пока не будут получены надёжные сведения о мурлоках, никаких войск на восток я посылать не стану." } } } } },
    [45] = { d = 15.6, v = "narrator", n = { x = 166 }, c = { x = { { 0.00, "При осмотре местности были обнаружены запутанные следы, ведущие на восток вдоль берега Озера Каменных Столбов." }, { 8.81, "В отдалении видно поселение мурлоков." }, { 11.81, "Возможно, именно здесь и окончил свой путь Рольф..." } } }, t = { d = 5.8, v = "narrator", n = { x = 59 }, c = { x = { { 0.00, "На шее трупа вы находите медальон с надписью \"Пехотинец Рольф Хартфорд\"." } } } } },
    [46] = { d = 21.0, v = "human-male", n = { x = 234 }, c = { x = { { 0.00, "Армия Штормграда назначила награду за мурлоков – скрытней и добытчиков." }, { 5.21, "Убей их и принеси мне их плавники: армия хорошо за это заплатит." }, { 9.97, "Мурлоки построили селение на Озере Каменных Столбов – это к северу отсюда; ещё одно селение расположено на юге – там, где русло реки разделяется надвое." } } }, t = { d = 14.2, v = "human-male", n = { x = 160 }, c = { x = { { 0.00, "Что у нас тут?" }, { 0.98, "Плавники?" }, { 1.71, "Отлично!" }, { 2.36, "Маршал Дугхан обеспокоен мурлоками, поселившимися на востоке леса." }, { 7.22, "Он будет рад узнать, что ситуация под контролем." }, { 10.70, "Твоя помощь в этом деле была просто неоценимой." } } } } },
    [47] = { d = 17.2, v = "human-male", n = { x = 194 }, c = { x = { { 0.00, "Кобольды в этих местах иногда носят с собой Золотую пыль." }, { 4.10, "Достань мне этой пыли, и я дам за неё лучшую цену в городе!" }, { 8.26, "Лучшую цену в городе!" }, { 9.84, "Кобольдов можно найти на юге, на руднике Подземных глубин, или на северо-востоке, рядом с Яшмовой шахтой." } } }, t = { d = 9.9, v = "human-male", n = { x = 99 }, c = { x = { { 0.00, "Благодарю за пыль." }, { 1.43, "Вот твои деньги..." }, { 2.93, "А вот и маленький подарочек от моих друзей." }, { 6.36, "Возможно, он тебе пригодится..." }, { 8.86, "Да, пригодится." } } } } },
    [48] = { d = 13.8, v = "dwarf-male", n = { x = 129 }, c = { x = { { 0.00, "Где-то в южных краях, там, где вьётся лоза" }, { 3.63, "Есть колодец с водой, что чиста как слеза." }, { 7.27, "Бьёт священной воды одинокий ручей," }, { 10.36, "Будь же другом, скорей, отправляйся за ней!" } } }, t = { d = 2.2, v = "dwarf-male", n = { x = 7 }, c = { x = { { 0.00, "И-ик!" }, { 1.04, "Хо-хо!" } } } } },
    [49] = { d = 12.8, v = "dwarf-male", n = { x = 124 }, c = { x = { { 0.00, "Как прекрасна янтарная россыпь зерна!" }, { 3.22, "Словно жаром костра пропиталась она." }, { 6.44, "Чтобы вышел наш пенный напиток хорош," }, { 9.74, "Ты ячмень мне добудь, кукурузу и рожь." } } }, t = { d = 2.0, v = "dwarf-male", n = { x = 7 }, c = { x = { { 0.00, "И-ик!" }, { 1.00, "Хо-хо!" } } } } },
    [50] = { d = 12.6, v = "dwarf-male", n = { x = 124 }, c = { x = { { 0.00, "Прочь дремота и лень!" }, { 1.74, "Встану я поутру," }, { 3.18, "Замешаю зерно и в сусло разотру," }, { 5.98, "Сплавить куб перегонный - и будет добро!" }, { 9.39, "Только истинных свойств подойдёт серебро." } } }, t = { d = 2.2, v = "dwarf-male", n = { x = 7 }, c = { x = { { 0.00, "И-ик!" }, { 1.00, "Хо-хо!" } } } } },
    [51] = { d = 12.6, v = "dwarf-male", n = { x = 135 }, c = { x = { { 0.00, "Хочешь, друг мой, на брагу взглянуть? - так и быть!" }, { 3.80, "Нам осталось лишь только её процедить." }, { 6.70, "Ветвь смоковницы даст нам немного угля," }, { 9.67, "Будет хмельный напиток светлей янтаря!" } } }, t = { d = 2.0, v = "dwarf-male", n = { x = 7 }, c = { x = { { 0.00, "И-ик!" }, { 1.00, "Хо-хо!" } } } } },
    [52] = { d = 11.4, v = "human-male", n = { x = 137 }, c = { x = { { 0.00, "Приветствую." }, { 0.89, "Чем дальше от Златоземья, тем агрессивнее становятся дикие звери: на Лесопилку Восточной долины постоянно нападают волки и медведи." }, { 10.16, "Хочешь нам помочь?" } } }, t = { d = 11.4, v = "human-male", n = { x = 116 }, c = { x = { { 0.00, "Я так тебе благодарен!.." }, { 1.80, "Похоже, в этом лесу поселилось что-то, что гонит зверей прямо на нас." }, { 6.98, "Что бы там ни было, хотел бы я, чтобы оно не покидало леса..." } } } } },
    [53] = { d = 11.4, v = "dwarf-male", n = { x = 112 }, c = { x = { { 0.00, "Вот медовая брага готова вполне," }, { 2.80, "Словно солнце играет в её глубине!" }, { 5.76, "Но покуда не взялись мы пить допьяна," }, { 8.87, "Бочка из обожжённого дуба нужна!" } } }, t = { d = 13.2, v = "dwarf-male", n = { x = 114 }, c = { x = { { 0.00, "Углём отфильтровано, вызрело в бочке," }, { 3.49, "Восторг, упоение в каждом глоточке." }, { 6.90, "Поднимем же тост за тебя, за меня" }, { 10.05, "И за сладкий напиток цвета янтаря!" } } } } },
