    [55] = { d = 24.9, g = 1, v = "human-male", n = { m = 281, f = 283 }, c = { m = { { 0.00, "Морбент Скверн прячется в своём доме на вершине холма на востоке, рядом с кладбищем Вороньего холма." }, { 7.23, "Пора положить конец его бесчинствам в наших землях…" }, { 11.08, "Примени против него Проклятье Морбента, оно обратит в прах всю его защитную магию." }, { 17.14, "Убей его." }, { 17.92, "Убей негодяя и избавь нас от его гнусных козней." }, { 21.51, "Стань орудием возмездия, герой Сумеречного леса." } }, f = { { 0.00, "Морбент Скверн прячется в своём доме на вершине холма на востоке, рядом с кладбищем Вороньего холма." }, { 7.15, "Пора положить конец его бесчинствам в наших землях…" }, { 10.95, "Примени против него Проклятье Морбента, оно обратит в прах всю его защитную магию." }, { 16.94, "Убей его." }, { 17.71, "Убей негодяя и избавь нас от его гнусных козней." }, { 21.26, "Стань орудием возмездия, героиня Сумеречного леса." } } }, t = { d = 21.0, g = 1, v = "human-male", n = { m = 228, f = 229 }, c = { m = { { 0.00, "Морбент Скверн убит." }, { 1.54, "Тёмные всадники по-прежнему топчут наши земли, но всё же мы одержали победу, хотя и неполную." }, { 8.44, "Я надеялся на это вопреки всему." }, { 10.92, "Ты совершил невозможное, и легенды о тебе будут ходить по всему Сумеречному лесу." }, { 17.02, "Ступай." }, { 17.62, "Быть может, судьба вновь приведёт тебя ко мне..." } }, f = { { 0.00, "Морбент Скверн убит." }, { 1.52, "Тёмные всадники по-прежнему топчут наши земли, но всё же мы одержали победу, хотя и неполную." }, { 8.35, "Я надеялся на это вопреки всему." }, { 10.80, "Ты совершила невозможное, и легенды о тебе будут ходить по всему Сумеречному лесу." }, { 16.90, "Ступай." }, { 17.50, "Быть может, судьба вновь приведёт тебя ко мне..." } } } } },
