    [57] = { d = 20.4, v = "human-female#47", n = { x = 239 }, c = { x = { { 0.00, "Я получила сведения о появлении нежити в наших лесах!" }, { 3.57, "Если ты не боишься, отправляйся на кладбище Вороньего холма и убей пятнадцать скелетов-губителей и пятнадцать ужасных скелетов." }, { 11.97, "Также говорят, что скелеты появились и к югу от Темнолесья, на Безмятежном кладбище." }, { 17.50, "Мы должны изгнать нежить из Сумеречного леса!" } } }, t = { d = 5.6, g = 1, v = "human-female#47", n = { m = 66, f = 67 }, c = { m = { { 0.00, "Народ Темнолесья благодарит тебя." }, { 2.51, "Ты доказал свою преданность Ночному дозору." } }, f = { { 0.00, "Народ Темнолесья благодарит тебя." }, { 2.48, "Ты доказала свою преданность Ночному дозору." } } } } },
    [58] = { d = 16.3, v = "human-female#47", n = { x = 213 }, c = { x = { { 0.00, "Обстановка на Вороньем холме не улучшилась." }, { 2.77, "Безопасность Темнолесья – в твоих руках." }, { 5.37, "У нас не хватает стражей для обеспечения безопасности города." }, { 9.24, "Придётся тебе снова отправиться на Вороний холм и уничтожить двадцать распространителей чумы в восточном мавзолее." } } }, t = { d = 11.0, v = "human-female#47", n = { x = 117 }, c = { x = { { 0.00, "Я благодарю тебя, от лица народа Темнолесья и от себя, как главы Ночного дозора, за храбрость и преданность общему делу." }, { 9.25, "Да озарит Свет твой путь!" } } } } },
    [59] = { d = 27.1, v = "human-male", n = { x = 334 }, c = { x = { { 0.00, "Твои хитроумие и доблесть должны быть вознаграждены." }, { 3.54, "Я приготовил для тебя знак: он пригодится для какой-нибудь части доспехов." }, { 8.48, "Отнеси его Саре Тимберлейн на Лесопилку Восточной долины: она изготовит для тебя броню, или что там тебе будет нужно." }, { 16.59, "Мне хотелось бы надеяться, что новые доспехи помогут тебе, в защите Элвиннского леса от врагов." }, { 23.05, "Лесозаготовки находятся к востоку от сторожевого поста Томаса." } } }, t = { d = 10.6, g = 1, v = "human-female#45", n = { x = 100 }, c = { m = { { 0.00, "Ага, вот и знак!" }, { 1.28, "Благодарю." }, { 2.13, "Можешь выбрать любой доспех, какой тебе нужен." }, { 5.96, "Желаю удачи, герой!" }, { 7.59, "Надеюсь, новый доспех тебе пригодится." } }, f = { { 0.00, "Ага, вот и знак!" }, { 1.27, "Благодарю." }, { 2.12, "Можешь выбрать любой доспех, какой тебе нужен." }, { 5.92, "Желаю удачи, героиня!" }, { 7.69, "Надеюсь, новый доспех тебе пригодится." } } } } },
    [60] = { d = 30.5, g = 1, v = "human-male", n = { m = 354, f = 359 }, c = { m = { { 0.00, "Приветствую тебя, добрый путник!" }, { 2.25, "Не найдётся ли у тебя свободной минутки?" }, { 4.93, "Мы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи." }, { 10.53, "Воск нужен, понимаешь?" }, { 12.05, "Я вот и думаю: может, ты мне поможешь?" }, { 14.61, "Свечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке..." }, { 26.11, "Может, прогуляешься туда и раздобудешь для меня свечи?" } }, f = { { 0.00, "Приветствую тебя, прекрасная госпожа!" }, { 2.60, "Не найдётся ли у тебя свободной минутки?" }, { 5.32, "Мы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи." }, { 11.01, "Воск нужен, понимаешь?" }, { 12.56, "Я вот и думаю: может, ты мне поможешь?" }, { 15.16, "Свечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке..." }, { 26.85, "Может, прогуляешься туда и раздобудешь для меня свечи?" } } }, t = { d = 5.8, v = "human-male", n = { x = 51 }, c = { x = { { 0.00, "Ну что, пришлось попотеть?" }, { 2.32, "Спасибо за свечи!" }, { 3.92, "А вот и твоя награда..." } } } } },
    [61] = { d = 18.5, v = "human-male", n = { x = 218 }, c = { x = { { 0.00, "В Штормграде мой брат Морган ждёт посылки со свечами." }, { 3.60, "У меня нет времени съездить туда самому, но если ты окажешь нам эту услугу, Морган хорошо тебе заплатит." }, { 10.92, "Вот, я тут упаковал свечи." }, { 12.73, "А Моргана найти несложно, он работает в Торговом квартале Штормграда, в аптеке Песта." } } }, t = { d = 10.4, v = "human-male", n = { x = 123 }, c = { x = { { 0.00, "Вот плата за услугу..." }, { 1.54, "Кстати, можешь тут пока осмотреться: уверен, у нас наверняка найдётся какое-нибудь зелье или безделушка, которые тебе пригодятся..." } } } } },
    [62] = { d = 22.1, v = "human-male", n = { x = 261 }, c = { x = { { 0.00, "Рудник в Североземье – не единственная головная боль." }, { 3.71, "До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды." }, { 10.44, "Нужно исследовать рудник и подтвердить эти известия или опровергнуть их." }, { 15.63, "Я буду ждать отчёта." }, { 17.04, "Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур." } } }, t = { d = 13.5, v = "human-male", n = { x = 137 }, c = { x = { { 0.00, "Скверные вести." }, { 1.26, "И что дальше?" }, { 2.30, "Может, драконы?!" }, { 3.63, "Похоже, придётся усилить охрану рудника." }, { 6.77, "Спасибо тебе." }, { 7.88, "И подожди, не уходи... возможно, у меня найдётся для тебя ещё одно задание." } } } } },
    [63] = { d = 33.5, v = "tauren-female#71", n = { x = 365 }, c = { x = { { 0.00, "На побережье Серебряного Бора, к западу от Гробницы, находится святилище, осквернённое чумой." }, { 7.05, "Духи перестали разговаривать с нашим народом, и тебе предстоит победить воплощение воды и очистить купель." }, { 15.28, "Возьми браслеты элементалей и остатки зелья Брин и помести их в жаровню." }, { 20.81, "Этот ритуал позволит призвать чистого духа, с которым можно будет поговорить." }, { 26.89, "Принеси мне доказательство того, что моё задание выполнено, и в награду я дам тебе тотем." } } }, t = { d = 13.4, v = "narrator", n = { x = 143 }, c = { x = { { 0.00, "Вы помещаете браслеты в жаровню и выливаете в огонь оставшиеся капли зелья Брин." }, { 6.30, "Пламя потрескивает, а вы начинаете проговаривать простые слова, которым вас обучила Ислен..." } } } } },
    [64] = { d = 30.2, v = "human-male", n = { x = 340 }, c = { x = { { 0.00, "Это было ужасно!" }, { 1.25, "Верна разбудила меня, когда услышала гвалт в поле." }, { 4.82, "Поля были полны хулиганья." }, { 6.76, "Мы бежали в спешке, и я забыл взять с собой карманные часы." }, { 10.89, "Папаша Верны подарил мне эти часы в день нашей с ней свадьбы, и мне прямо нехорошо от мысли, что ими могли завладеть те воры." }, { 19.66, "Я оставил часы в доме, в платяном шкафу." }, { 22.54, "Ищи тыквенную ферму к западу отсюда – ты её не пропустишь." }, { 26.61, "Если вернёшь мне мои часы, я буду очень признателен!" } } }, t = { d = 11.4, g = 1, v = "human-male", n = { m = 130, f = 129 }, c = { m = { { 0.00, "Мои часы!" }, { 0.77, "Благодарю тебя, любезный господин!" }, { 3.28, "Мы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности." } }, f = { { 0.00, "Мои часы!" }, { 0.78, "Благодарю тебя, любезная госпожа!" }, { 3.24, "Мы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности." } } } } },
    [65] = { d = 27.8, g = 1, v = "human-male", n = { m = 333, f = 335 }, c = { m = { { 0.00, "Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовёт себя Братством Справедливости." }, { 7.82, "Мне нужно, чтобы ты проник в эту бандитскую шайку." }, { 11.35, "Нам нужно узнать, кто её главарь, и где они прячутся." }, { 15.01, "В деревне Приозёрье, в таверне, обитает некий Вилли, который мне кое-чем обязан." }, { 20.54, "Отправляйся в деревню Приозёрье, что расположена в Красногорье, к востоку от Элвиннского леса, и всё разузнай." } }, f = { { 0.00, "Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовёт себя Братством Справедливости." }, { 7.69, "Мне нужно, чтобы ты проникла в эту бандитскую шайку." }, { 11.30, "Нам нужно узнать, кто её главарь, и где они прячутся." }, { 14.90, "В деревне Приозёрье, в таверне, обитает некий Вилли, который мне кое-чем обязан." }, { 20.33, "Отправляйся в деревню Приозёрье, что расположена в Красногорье, к востоку от Элвиннского леса, и всё разузнай." } } }, t = { d = 5.2, v = "human-male#50", n = { x = 47 }, c = { x = { { 0.00, "Так значит, тебя послал Камнегрив?" }, { 3.03, "Что ж, я перед ним в долгу." } } } } },
    [66] = { d = 28.6, v = "human-female#45", n = { x = 314 }, c = { x = { { 0.00, "Вчера ночью меня охватил беспричинный ужас." }, { 3.39, "Я почувствовала, что моя внучка Алисса оказалась в страшной опасности." }, { 8.67, "Я разложила карты... и со стола на меня взглянула Смерть." }, { 12.93, "Погрузившись в длительный и тяжкий транс, я сумела разгадать эту тёмную тайну." }, { 18.75, "Мне открылось имя: Сталван." }, { 20.85, "Отыщи клерка в городской Ратуше и постарайся побольше разузнать об этом Сталване." }, { 27.02, "Я опасаюсь за всех нас." } } }, t = { d = 3.0, v = "human-male", n = { x = 23 }, c = { x = { { 0.00, "А, так тебя послала мадам Ева..." } } } } },
    [67] = { d = 23.5, v = "human-male", n = { x = 237 }, c = { x = { { 0.00, "Сталван, значит?" }, { 1.30, "Дай-ка погляжу в журнал." }, { 3.22, "Сталван..." }, { 4.04, "Сталван..." }, { 4.86, "Ну-ка..." }, { 5.54, "А, вот он!" }, { 6.30, "У меня есть запись о некоем господине Сталване Мистмантле." }, { 10.74, "Последний адрес – Лунореченская школа." }, { 14.11, "Но это было так давно!" }, { 15.89, "Окажи любезность, дай знать, если выяснишь что-либо об этом типе." }, { 20.88, "Записи должны содержаться в порядке." } } }, t = { d = 3.4, v = "narrator", n = { x = 32 }, c = { x = { { 0.00, "Старый сундук со скрипом открывается..." } } } } },
    [68] = { d = 4.5, v = "narrator", n = { x = 49 }, c = { x = { { 0.00, "Вы находите в старом сундуке пыльное неотосланное письмо." } } }, t = { d = 10.1, v = "human-male", n = { x = 105 }, c = { x = { { 0.00, "Занятно." }, { 0.70, "Значит, этот тип всё же побывал в Луноречье." }, { 4.11, "Странно, что письмо так и не доставили." }, { 7.10, "Тем не менее я обновлю записи в журнале." } } } } },
    [69] = { d = 15.4, v = "human-male", n = { x = 172 }, c = { x = { { 0.00, "Боже мой!" }, { 0.72, "Сразу и не заметил." }, { 2.17, "В журнале, точно под первым адресом Сталвана, написан ещё один адрес, частично вычеркнутый." }, { 8.87, "Похоже, он направлялся в таверну \"Гордость льва\" в Златоземье." }, { 13.34, "Можешь поискать сведения там." } } }, t = { d = 2.5, v = "human-male", n = { x = 18 }, c = { x = { { 0.00, "Сталван?" }, { 1.02, "Знакомое имя." } } } } },
    [70] = { d = 29.0, v = "human-male", n = { x = 316 }, c = { x = { { 0.00, "Имя Сталван мне знакомо." }, { 1.87, "А, вспомнил." }, { 2.80, "Много лет назад ненастной ночью в трактир явился гонец, искавший убежища от непогоды." }, { 9.21, "Около полуночи этот человек, бледный от страха, сбежал вниз по лестнице в пижаме и исчез." }, { 15.89, "Второпях он оставил письма в сундуке на втором этаже." }, { 19.89, "За ними он так и не вернулся." }, { 22.03, "Осталось одно, от этого Сталвана." }, { 24.57, "Адресовано оно в район каналов Штормграда." }, { 27.77, "Можешь прочитать." } } }, t = { d = 3.8, g = 1, v = "human-male#50", n = { m = 41, f = 42 }, c = { m = { { 0.00, "А ты не робкого десятка, раз решился доставить это." } }, f = { { 0.00, "А ты не робкого десятка, раз решилась доставить это." } } } } },
    [71] = { d = 9.9, v = "narrator", n = { x = 102 }, c = { x = { { 0.00, "Теперь, когда вы нашли оба медальона, отнесите их к мосту и отдайте стражнику Томасу: он должен узнать о смерти обоих стражей." } } }, t = { d = 7.3, v = "human-male", n = { x = 74 }, c = { x = { { 0.00, "Увы, мои худшие опасения подтвердились." }, { 3.22, "Мурлоки – это угроза, с которой придётся считаться..." } } } } },
    [72] = { d = 27.4, v = "human-male#50", n = { x = 321 }, c = { x = { { 0.00, "Мой отец был сторожем в этом поместье задолго до меня." }, { 3.85, "Ему-то и пришлось вытирать кровь после того убийства." }, { 7.63, "Но это к делу не относится." }, { 9.59, "Последние деньги треста Кременника давно иссякли." }, { 13.12, "А теперь и последние семейные ценности отправляются прямиком на аукцион." }, { 18.17, "Проклятые сборщики налогов!.." }, { 20.25, "Пожалуй, если ты хочешь узнать побольше, можешь порыться в этом барахле." }, { 25.42, "Кто знает, что тебе попадётся." } } }, t = { d = 3.5, v = "narrator", n = { x = 30 }, c = { x = { { 0.00, "Вы медленно снимаете крышку с ящика..." } } } } },
    [74] = { d = 17.4, v = "narrator", n = { x = 175 }, c = { x = { { 0.00, "Внутри ящика вы находите много разных вещей: пыльные фамильные ценности, портрет, несколько охотничьих трофеев и старые книги." }, { 10.54, "Уже на самом дне, под глиняной вазой, вам попадается страница, вырванная из дневника." } } }, t = { d = 10.5, v = "human-male", n = { x = 102 }, c = { x = { { 0.00, "Я едва разбираю буквы, но почерк напоминает мне о..." }, { 4.31, "Да, я видел что-то подобное до того, как моё зрение окончательно испортилось." } } } } },
    [75] = { d = 25.9, v = "human-male", n = { x = 308 }, c = { x = { { 0.00, "Когда я только приехал сюда, в сундуке на втором этаже лежала кипа пергаментов." }, { 5.49, "Как-то раз я их просмотрел, но потом зрение стало не то, и я махнул на них рукой." }, { 10.92, "Окажи любезность слепому старику, поищи в сундуке наверху что-нибудь, что сможет помочь тебе разузнать о Сталване." }, { 18.74, "Мне кажется, там была выцветшая страница с интересными записями." }, { 23.07, "Принеси её мне, и я помогу тебе по мере сил." } } }, t = { d = 1.2, v = "human-male", n = { x = 6 }, c = { x = { { 0.00, "Это она!" } } } } },
    [76] = { d = 21.6, v = "human-male", n = { x = 258 }, c = { x = { { 0.00, "Благодаря тебе мы знаем, что рудник Подземных глубин заполонили кобольды." }, { 5.06, "Но нам нужен разведчик, чтобы выяснить, что творится в Яшмовой шахте." }, { 9.82, "Отправляйся туда и доложи мне, если обнаружишь кобольдов." }, { 13.77, "Иди на восток по дороге, пока не доберёшься до Башни Азоры, оттуда поверни на север, и у подножия гор отыщешь шахту." } } }, t = { d = 11.8, v = "human-male", n = { x = 116 }, c = { x = { { 0.00, "Кобольды в Яшмовой шахте?" }, { 2.08, "Так это правда?" }, { 3.37, "Проклятье!" }, { 4.23, "Дела идут всё хуже и хуже!" }, { 6.46, "Конечно, я благодарен тебе за информацию, но лучше бы мы ошибались..." } } } } },
    [77] = { d = 36.9, v = "bloodelf-male", n = { x = 436 }, c = { x = { { 0.00, "Я понял, про какую тару говорил Дран Дрофферс, у меня такая есть." }, { 4.42, "Я помогу тебе разлить \"Медовую зыбь\" по бутылкам, чтобы этот грубиян, отец Мальтона, остался доволен." }, { 11.31, "Но, разумеется, не бесплатно – взамен я хочу две бутылки \"Зыби\" для себя." }, { 16.21, "Бутылки можно найти в ящиках на заброшенной базе Орды у Осклизлой скалы." }, { 21.17, "Достать их будет нелегко, потому что в руинах кишмя кишат слизнюки и пиявки, и, говорят, у них там есть какой-то предводитель, что-то вроде верховного слизнюка." }, { 31.88, "Но другого способа нет – придётся тебе идти на базу и искать полные бутылки." } } }, t = { d = 26.2, v = "bloodelf-male", n = { x = 281 }, c = { x = { { 0.00, "Отличная работа." }, { 1.27, "Я очень рад, что напиток не испортился – нет ничего хуже на вкус, чем негодная медовуха." }, { 7.77, "Погоди минутку, магии нужно время, чтобы подействовать на этот ценный груз." }, { 13.46, "Хотя, на самом деле, никакой магии тут нет – я всего лишь перелью эту \"Медовую зыбь\" в новые бутылки, и тогда этот напиток превратится в величайшее сокровище!" }, { 25.25, "Ну вот, готово!" } } } } },
    [78] = { d = 15.5, v = "human-male", n = { x = 189 }, c = { x = { { 0.00, "Я знаю, кто мог бы тебе помочь." }, { 2.09, "Когда я служил в страже Штормграда, мы порой пропускали по стаканчику в темнолесской таверне \"Алый ворон\"." }, { 9.13, "Её хозяин Смиттс всегда был знатоком преданий." }, { 12.18, "Покажи ему эту страницу, посмотрим, что он скажет." } } }, t = { d = 3.4, v = "human-male#50", n = { x = 29 }, c = { x = { { 0.00, "Клянусь Светом!" }, { 1.48, "Я узнаю этот почерк!" } } } } },
    [79] = { d = 27.9, v = "human-male#50", n = { x = 351 }, c = { x = { { 0.00, "Я много лет следил за легендами, ходящими об этом Сталване." }, { 3.97, "Когда несколько лет назад нескольких заезжих аристократов нашли мёртвыми, мы с Хаггардом решили расследовать это дело." }, { 11.84, "Я отыскал несколько заляпанных грязью страниц, но мы так и не нашли связи между ними и этим лесным сумасшедшим." }, { 19.29, "Найденные тобой улики подтверждают его вину." }, { 22.35, "Немедленно отнеси эту страницу командиру Чернодрев и расскажи ей о добытых сведениях!" } } }, t = { d = 4.3, g = 1, v = "human-female#47", n = { m = 32, f = 33 }, c = { m = { { 0.00, "Надо же, ты оказался настоящим сыщиком, герой." } }, f = { { 0.00, "Надо же, ты оказалась настоящим сыщиком, героиня." } } } } },
    [80] = { d = 19.3, v = "human-female#47", n = { x = 233 }, c = { x = { { 0.00, "Я давно присматриваюсь к этому Сталвану." }, { 2.77, "Но если эта страница написана той же самой рукой, то его вина несомненно доказана." }, { 8.51, "За долгие годы службы клерк Далтри стал настоящим экспертом по различению почерков." }, { 14.18, "Покажи ему эту страницу, проверь, совпадает ли почерк с росписью в журнале." } } }, t = { d = 4.8, v = "human-male", n = { x = 56 }, c = { x = { { 0.00, "Несомненно!" }, { 0.86, "Почерк на этой странице совпадает с подписью в журнале." } } } } },
    [81] = { d = 29.8, v = "bloodelf-male", n = { x = 349 }, c = { x = { { 0.00, "Я позаботился о том, чтобы ничего не пропало – ни медовуха из бочонка, ни лишние бутылки." }, { 6.11, "Не то чтобы я так уж тепло относился к Драну, но нет ничего хуже, чем когда пропадает выпивка!" }, { 12.58, "Вот, держи." }, { 13.39, "Доставь этот бочонок Драну Дрофферсу в его забегаловку в Оргриммаре." }, { 18.19, "Да, и пожалуйста, не забудь передать привет Мальтону." }, { 21.87, "Скажи, что если он соскучится по отличной выпивке и великолепным собутыльникам, то мы будем в восторге от его визита." } } }, t = { d = 28.0, v = "orc-male", n = { x = 262 }, c = { x = { { 0.00, "Ну-ка, ну-ка, надо ещё посмотреть, что там в этом бочонке!" }, { 4.88, "Да, похоже, всё цело." }, { 6.68, "Ну, вот твоя плата за доставку." }, { 9.31, "Я выручу впятеро больше, когда продам её у себя в таверне!" }, { 14.27, "Хы-хы!" }, { 14.87, "Ну, а эти лишние бутылки \"Медовой зыби\" из Внутренних земель прибережём для особых случаев." }, { 22.45, "Надо попробовать смешать её с шампанским." }, { 25.90, "Назовём это... медованским!" } } } } },
    [82] = { d = 26.0, v = "goblin-male", n = { x = 274 }, c = { x = { { 0.00, "Все эти сообщения о жуках... нам известно, что они опустошают пруды в Ядовитом улье." }, { 6.55, "А НЕИЗВЕСТНО нам... всё остальное." }, { 9.13, "Для начала надо узнать, кто наш враг!" }, { 11.99, "Ступай в Ядовитый улей и добудь пять частей тел проклятущих насекомых Сентипаар." }, { 18.20, "Отнеси их алхимику Пестычинсу, пусть повозится." }, { 21.83, "Если уж он возьмётся за работу, скоро мы обо всём узнаем!" } } }, t = { d = 24.3, v = "goblin-male#108", n = { x = 282 }, c = { x = { { 0.00, "Неплохая работа – я немедленно примусь за анализ этих частей!" }, { 4.40, "Сразу скажу одно – таких насекомых я ещё не видел." }, { 8.03, "Такое впечатление, что ими управляет какая-то чуждая сила." }, { 12.23, "Немедленно поговори с Рудознатцем; ситуация серьёзная, ему без сомнений понадобится твоя помощь!" }, { 18.98, "Не знаю точно, но скорее всего речь снова пойдёт о насекомых пустыни Танарис!" } } } } },
    [83] = { d = 20.4, v = "human-female#45", n = { x = 242 }, c = { x = { { 0.00, "В Североземье Братство Справедливости носит маски из холстины; в Элвиннском лесу они предпочитают лён, который мог бы принести мне гораздо большую пользу... и прибыль." }, { 11.63, "Принеси мне красные повязки, а я сделаю из них кое-что полезное для тебя." }, { 16.75, "Лагеря братства разбросаны по всему Элвиннскому лесу." } } }, t = { d = 5.2, v = "human-female#45", n = { x = 45 }, c = { x = { { 0.00, "Отличные повязки, даром что ткань грубовата..." }, { 4.27, "Вот, держи!" } } } } },
    [84] = { d = 6.6, v = "human-female", n = { x = 66 }, c = { x = { { 0.00, "Вот, держи." }, { 0.92, "Отдай этот пирог Билли, да не забудь сказать, что я желаю ему подавиться!" } } }, t = { d = 6.9, v = "child-male", n = { x = 53 }, c = { x = { { 0.00, "М-м, вкуснятина!" }, { 1.65, "Пирог что надо!" }, { 3.30, "Похоже, ко мне возвращается память..." } } } } },
    [85] = { d = 18.2, v = "human-female", n = { x = 210 }, c = { x = { { 0.00, "Я потеряла ожерелье." }, { 1.46, "Сдаётся мне, его стащил этот беспризорник Билли Маклур!" }, { 5.40, "Вечно он шастает по виноградникам, как крыса какая-то!" }, { 9.22, "Если решишь его искать, то сходи на виноградники, это к востоку отсюда." }, { 14.36, "Пожалуйста, разыщи моё ожерелье, порадуй старуху-вдову!" } } }, t = { d = 16.2, v = "child-male", n = { x = 174 }, c = { x = { { 0.00, "Чего-чего она там потеряла?" }, { 2.07, "Какое такое ожерелье?" }, { 3.69, "Не брал я его, даже в глаза не видел, и вообще я не вор какой-нибудь!" }, { 8.61, "Может, я и знаю, кто мог это сделать..." }, { 11.45, "Вот только вспоминать на голодный желудок сложно, в голове мутится." } } } } },
    [86] = { d = 20.1, v = "child-male", n = { x = 227 }, c = { x = { { 0.00, "Может, если бы я получил пирог, то смог бы вспомнить, у кого сейчас это твоё ожерелье." }, { 6.12, "Кстати..." }, { 6.83, "Говорят, у тётушки Бернис получаются отличные пироги со свининой." }, { 11.42, "Я вот что думаю: принеси ей кабаньего мяса – около ферм кабанов ошивается видимо-невидимо – и попроси испечь для тебя пирог." } } }, t = { d = 7.4, v = "human-female", n = { x = 86 }, c = { x = { { 0.00, "Хоть мясо и жёстковато, его можно потушить на медленном огне и приготовить отличную начинку для пирога!" } } } } },
    [87] = { d = 26.2, v = "child-male", n = { x = 272 }, c = { x = { { 0.00, "Я играл около рудника Подземных глубин и, похоже, уронил..." }, { 4.54, "М-м..." }, { 5.02, "В смысле, я там видел ожерелье этой самой дамы." }, { 8.68, "Представления не имею, как оно туда попало; я тут ни при чём!" }, { 13.22, "В общем, короче, я видел, как здоровенный кобольд с золотыми зубами схватил ожерелье и скрылся в руднике." }, { 21.15, "Если отыщешь этого кобольда, найдёшь и ожерелье, точно тебе говорю!" } } }, t = { d = 16.2, v = "human-female", n = { x = 152 }, c = { x = { { 0.00, "Моё ожерелье!" }, { 1.11, "Оно нашлось!" }, { 2.23, "О, дорогуша, спасибо, спасибо!" }, { 4.75, "Вот, держи." }, { 5.71, "Это принадлежало моему мужу; \"счастливая вещица\" – он всегда так говорил." }, { 11.79, "Если бы только он взял это с собой в последний поход!.." } } } } },
    [88] = { d = 35.8, v = "human-female#47", n = { x = 430 }, c = { x = { { 0.00, "У семейства Бреквеллов имеется свинья." }, { 2.62, "Не простая, а призовая, по кличке – ты только представь себе! – Принцесса." }, { 7.61, "И эта громадная гора сала то и дело пробирается на мой огород!" }, { 11.87, "Чтобы пожирать мои овощи!" }, { 13.70, "Так вот, прежде чем эта скотина доберётся до полей... словом, Принцесса должна умереть!" }, { 19.54, "Принеси мне её ошейник в доказательство того, что это свершилось, а взамен получишь кое-что полезное." }, { 26.36, "Принцессу держат на тыквенной ферме Бреквеллов: это к востоку от фермы Маклуров." }, { 31.84, "Разберись с ней прежде, чем она проголодается и вернётся сюда!" } } }, t = { d = 12.3, v = "human-female#47", n = { x = 140 }, c = { x = { { 0.00, "Счастье-то какое!" }, { 1.28, "Эта хавронья была такой громадной, что в один присест сожрала бы весь наш урожай!" }, { 7.09, "Я так тебе благодарна!" }, { 8.69, "Взгляни: что-нибудь из этого тебе, надеюсь, подойдёт?" } } } } },
    [89] = { d = 24.1, v = "human-male", n = { x = 285 }, c = { x = { { 0.00, "Из-за последнего нашествия орков нам пришлось переплавить весь металл на пули, мечи и доспехи." }, { 6.49, "Мы посылали в Штормград за новыми поставками, но отряд гноллов Красногорья разграбил обоз и сбежал в холмы за Приозёрьем." }, { 14.77, "Нам не хватает материалов на ремонт моста." }, { 17.67, "Если ты принесёшь мне пять железных пик и пять железных клёпок, я прикажу тебя наградить." }, { 23.60, "За дело!" } } }, t = { d = 6.4, v = "human-male", n = { x = 69 }, c = { x = { { 0.00, "Отличная работа." }, { 1.35, "Мы можем продолжить восстановление моста." }, { 4.63, "Ещё немного, и закончим." } } } } },
    [90] = { d = 25.5, v = "human-male", n = { x = 304 }, c = { x = { { 0.00, "Моё коронное блюдо – пряные котлеты из волчатины!" }, { 3.35, "Разумеется, я могу тебе их пожарить, но для этого мне понадобятся кое-какие продукты." }, { 9.14, "Раздобудь десять постных волчьих боков." }, { 11.89, "В лесу волков полно, и добыть мясо будет несложно." }, { 15.42, "Кстати, тебе ещё повезло – буквально на днях мне пришёл очередной груз травяных приправ Штормграда, так что от тебя мне понадобится только сама волчатина." } } }, t = { d = 6.2, v = "human-male", n = { x = 68 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.38, "Наслаждайся вкуснятиной – приправленной котлетой из волчатины!" } } } } },
    [91] = { d = 30.7, v = "human-male", n = { x = 342 }, c = { x = { { 0.00, "В восточных предгорьях нашего края обосновался враг Штормграда." }, { 4.70, "С помощью тайной магии этот негодяй по имени Моргант сеет ужас и страдания в нашем городе и окрестностях." }, { 12.68, "Он прибрал под свою руку гноллов из стаи Темношкуров, и они исполняют его повеления." }, { 19.06, "Согласно Закону Озёр, пособничество врагу королевства карается смертью." }, { 24.36, "Гноллов следует уничтожить!" }, { 26.44, "Принеси мне десять подвесок Темношкуров и получишь награду." } } }, t = { d = 10.1, v = "human-male", n = { x = 132 }, c = { x = { { 0.00, "Суд Озёр благодарит тебя за помощь правосудию." }, { 3.10, "Помогая претворить в жизнь законы Королевства, ты способствуешь установлению справедливости в наших землях." } } } } },
    [92] = { d = 26.0, v = "human-female#47", n = { x = 324 }, c = { x = { { 0.00, "Я бы с радостью сделала для тебя гуляш по-красногорски, но есть небольшое затруднение." }, { 5.78, "Во время недавнего вторжения орков мне пришлось кормить целый отряд солдат Штормграда, и все кладовые опустели..." }, { 13.44, "Хотя если ты снабдишь меня всеми необходимыми продуктами, я уж расстараюсь!" }, { 18.54, "Принеси мне пять кусков жёсткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса." } } }, t = { d = 7.6, v = "human-female#47", n = { x = 66 }, c = { x = { { 0.00, "Молодец." }, { 0.83, "И какие отличные куски!" }, { 3.06, "А вот и моё коронное блюдо – гуляш по-красногорски." } } } } },
    [93] = { d = 25.5, v = "human-male", n = { x = 286 }, c = { x = { { 0.00, "Открою тебе тайну: тёмные пирожки с \"крабами\" делаются из паучьих лапок!" }, { 5.28, "Понимаю, эта новость может быть для тебя неприятной, но пирожки получаются вкусные и ароматные – отличная закуска!" }, { 13.55, "Принеси мне липкие паучьи лапки, и я испеку для тебя пирожочки." }, { 18.17, "Говорят, что лучшие лапки у ядовитых кругопрядов." }, { 21.76, "Они плетут паутины на севере, между холмами и рекой." } } }, t = { d = 17.0, v = "human-male", n = { x = 186 }, c = { x = { { 0.00, "О, отличные лапки!" }, { 1.38, "Дай-ка я замариную их особым составом, – не подсматривай! – потом хорошенько подрумяню на сковородке…" }, { 8.68, "И хотя тёмные пирожки с крабами – моё коронное блюдо и рецептом я делиться не готов, вот тебе рецепт блюда не хуже." } } } } },
    [94] = { d = 36.9, v = "human-male", n = { x = 419 }, c = { x = { { 0.00, "Мой соперник Моргант – волшебник, наделённый великой силой, но лишённый сердечной доброты." }, { 6.37, "Он обосновался в башне Илгалара, что в Красногорье." }, { 10.07, "Я нашёл способ следить за ним при помощи Ока Азоры." }, { 13.77, "Однако Око не даёт возможности проникнуть в его мысли." }, { 17.73, "Для такого дела мне потребуется помощь." }, { 20.59, "Если ты согласишься помогать мне, возьми амулет Азоры и отнеси его к башне Илгалара." }, { 26.76, "Амулет нужно положить под статую льва рядом с башней." }, { 30.66, "Если это будет сделано, то с помощью силы Азоры я смогу проникнуть в замыслы Морганта." } } }, t = { d = 21.4, g = 1, v = "human-male", n = { m = 226, f = 226 }, c = { m = { { 0.00, "*Вы кладёте амулет Азоры в углубление, и он словно бы врастает в камень.*" }, { 6.18, "*Вы слышите голос Теокрита:*" }, { 8.48, "Прими мою благодарность, юный путник." }, { 11.16, "Отныне ты сможешь говорить со мной посредством этого амулета." }, { 15.41, "После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание." } }, f = { { 0.00, "*Вы кладёте амулет Азоры в углубление, и он словно бы врастает в камень.*" }, { 6.24, "*Вы слышите голос Теокрита:*" }, { 8.56, "Прими мою благодарность, юная путница." }, { 11.28, "Отныне ты сможешь говорить со мной посредством этого амулета." }, { 15.47, "После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание." } } } } },
    [95] = { d = 33.2, v = "human-male", n = { x = 409 }, c = { x = { { 0.00, "Раньше я работал на одной из ферм на юго-востоке... а потом тёмные всадники спустились с перевала Мёртвого Ветра и перебили всю мою семью, пока я был в отлучке!" }, { 10.46, "Вернувшись, я увидел неподалёку от амбара неясную фигуру человека, который что-то закапывал." }, { 16.52, "Он успел сбежать от меня, а задерживаться я не мог, потому что преследовал тёмных всадников." }, { 22.46, "Так я и не узнал, что там спрятано." }, { 24.72, "Если ты можешь выяснить, что закопал в землю этот незнакомец, я буду очень признателен." }, { 30.55, "Поищи возле старого пня, рядом с амбаром." } } }, t = { d = 9.3, v = "narrator", n = { x = 89 }, c = { x = { { 0.00, "Вы находите кучу торопливо накиданной земли." }, { 3.71, "Похоже, кто-то хотел что-то спрятать... а времени у него не хватало." } } } } },
    [96] = { d = 16.0, v = "elemental-water", n = { x = 113 }, c = { x = { { 0.00, "Возьми осколок." }, { 1.72, "Возьми его и даруй жизнь." }, { 4.50, "Даруй жизнь и пойми." }, { 6.70, "Пойми, что вода – это жизнь..." }, { 9.95, "А порча – конец жизни." }, { 12.44, "Оберегай и даруй жизнь силой воды." } } }, t = { d = 36.2, v = "tauren-female#71", n = { x = 369 }, c = { x = { { 0.00, "А вот и доказательство твоих свершений, как я и просила." }, { 4.35, "Я рада, что могу первой поздравить тебя с успехом и вручить тебе этот..." }, { 10.20, "Тотем воды." }, { 11.20, "Пусть он служит тебе верой и правдой." }, { 14.20, "Удачи!" }, { 14.77, "Следующее испытание ожидает тебя нескоро, поэтому учись хорошенько." }, { 20.19, "Чистая вода не только вдыхает новую жизнь в раненых, но может также оказывать и другие эффекты." }, { 27.82, "Когда найдёшь время, поговори с наставником шаманов." }, { 31.96, "Может быть, у него найдутся для тебя новые заклинания." } } } } },
    [97] = { d = 6.4, v = "human-male", n = { x = 78 }, c = { x = { { 0.00, "Немедленно сообщи командиру Чернодрев, что почерки совпадают!" }, { 4.50, "Её подозрения подтвердились!" } } }, t = { d = 3.2, v = "human-female#47", n = { x = 24 }, c = { x = { { 0.00, "Я так и знала!" }, { 1.54, "Отличная работа!" } } } } },
    [98] = { d = 36.9, g = 1, v = "human-female#47", n = { x = 435 }, c = { m = { { 0.00, "Сталван Мистмантл вёл порочную жизнь." }, { 2.58, "От его руки погибли многие невинные люди." }, { 5.60, "Несомненно, он виновен в бесчисленных преступлениях, а теперь угрожает и нашему Темнолесью." }, { 11.90, "Лишь Свету известно, что за гнусные злодеяния он готовит." }, { 15.87, "Ступай в его дом к северу от города, герой, и покончи со Сталваном раз и навсегда." }, { 21.60, "Приведя мой приговор в исполнение, отправляйся к мадам Еве и покажи ей его фамильное кольцо." }, { 28.08, "В конце концов именно её предчувствие позволило нам раскрыть это тёмное преступление." }, { 34.00, "Благодаря ей в Темнолесье стало безопаснее." } }, f = { { 0.00, "Сталван Мистмантл вёл порочную жизнь." }, { 2.54, "От его руки погибли многие невинные люди." }, { 5.52, "Несомненно, он виновен в бесчисленных преступлениях, а теперь угрожает и нашему Темнолесью." }, { 11.73, "Лишь Свету известно, что за гнусные злодеяния он готовит." }, { 15.64, "Ступай в его дом к северу от города, героиня, и покончи со Сталваном раз и навсегда." }, { 21.41, "Приведя мой приговор в исполнение, отправляйся к мадам Еве и покажи ей его фамильное кольцо." }, { 27.81, "В конце концов именно её предчувствие позволило нам раскрыть это тёмное преступление." }, { 33.64, "Благодаря ей в Темнолесье стало безопаснее." } } }, t = { d = 19.4, g = 1, v = "human-female#45", n = { m = 193, f = 193 }, c = { m = { { 0.00, "Знаю, Сталван мёртв." }, { 1.65, "Я ощутила волну надежды, пробежавшую по осквернённому лесу." }, { 6.32, "Сумеречный лес раз и навсегда освободился от кровожадной твари." }, { 11.28, "Мою радость омрачает лишь мысль о тех, кто пал жертвой этого чудовища." }, { 16.81, "А ты отважен и хитёр, герой." } }, f = { { 0.00, "Знаю, Сталван мёртв." }, { 1.68, "Я ощутила волну надежды, пробежавшую по осквернённому лесу." }, { 6.43, "Сумеречный лес раз и навсегда освободился от кровожадной твари." }, { 11.48, "Мою радость омрачает лишь мысль о тех, кто пал жертвой этого чудовища." }, { 17.11, "А ты отважна и хитра, героиня." } } } } },
    [99] = { d = 52.5, v = "scourge-male#82", n = { x = 501 }, c = { x = { { 0.00, "По мере того, как растёт моё понимание магии Аругала, растёт и моё презрение к этому злосчастному глупцу." }, { 9.13, "Я уже почти закончил исследование его так называемого \"лекарственного зелья\"." }, { 15.96, "У меня будет полная информация, когда я узнаю, какие чары служат причиной странностей, происходящих в деревне Погребальных Костров." }, { 27.63, "Днём живущие там крестьяне выглядят по-человечески." }, { 32.08, "Но когда солнце заходит, деревенский люд превращается в воргенов Лунного Гнева." }, { 39.06, "Мне нужно извлечь энергию из заколдованных кандалов, надетых на крестьян Аругалом." }, { 46.29, "Принеси мне шесть заколдованных кандалов из деревни Погребальных Костров." } } }, t = { d = 13.2, g = 1, v = "scourge-male#82", n = { m = 123, f = 125 }, c = { m = { { 0.00, "Твоя настойчивость весьма похвальна." }, { 3.32, "С помощью информации, которую ты помог мне собрать, Аругал падёт, и вся его безрассудная магия развеется." }, { 12.71, "Браво." } }, f = { { 0.00, "Твоя настойчивость весьма похвальна." }, { 3.26, "С помощью информации, которую ты помогла мне собрать, Аругал падёт, и вся его безрассудная магия развеется." }, { 12.64, "Браво." } } } } },
    [100] = { d = 15.0, v = "narrator", n = { x = 150 }, c = { x = { { 0.00, "Отзвучали последние слова заклятья, и вас ослепляет вспышка света." }, { 5.65, "Звуки капель, падающих на пламя, стихают, и вас переполняет радость: ведь осквернённые духи вокруг вас уничтожены." } } }, t = { d = 11.0, v = "elemental-water", n = { x = 87 }, c = { x = { { 0.00, "Спасибо тебе." }, { 1.55, "Спасибо шаманам." }, { 3.38, "Порча отступает, но жизнь продолжает увядать." }, { 8.22, "Пусть шаманы охраняют жизнь." } } } } },
    [101] = { d = 29.0, g = 1, v = "human-female#45", n = { m = 309, f = 309 }, c = { m = { { 0.00, "По лесу расползается тление и порча, и все мы вынуждены позаботиться о самозащите." }, { 5.74, "Ветер несёт мне вести о великой опасности, поджидающей тебя в ближайшем будущем." }, { 11.42, "Если ты желаешь оградить себя от неё, благородный герой, принеси мне десять клыков вурдалаков, десять пальцев скелетов и пять фиалов паучьего яда." }, { 21.81, "Тогда я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя." } }, f = { { 0.00, "По лесу расползается тление и порча, и все мы вынуждены позаботиться о самозащите." }, { 5.88, "Ветер несёт мне вести о великой опасности, поджидающей тебя в ближайшем будущем." }, { 11.69, "Если ты желаешь оградить себя от неё, благородная героиня, принеси мне десять клыков вурдалаков, десять пальцев скелетов и пять фиалов паучьего яда." }, { 22.46, "Тогда я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя." } } }, t = { d = 22.7, g = 1, v = "human-female#45", n = { m = 242, f = 243 }, c = { m = { { 0.00, "Ты поступил мудро." }, { 1.39, "Этот тотем Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами." }, { 7.60, "Если тебе будет что-то угрожать, возьми тотем в руку – и его магическая аура защитит тебя." }, { 14.47, "Не теряй мужества, прекрасный герой." }, { 17.18, "Тебе оно понадобится, ибо я чувствую – грядёт немало кровопролитных сражений." } }, f = { { 0.00, "Ты поступила мудро." }, { 1.44, "Этот тотем Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами." }, { 7.57, "Если тебе будет что-то угрожать, возьми тотем в руку – и его магическая аура защитит тебя." }, { 14.36, "Не теряй мужества, прекрасная героиня." }, { 17.17, "Тебе оно понадобится, ибо я чувствую – грядёт немало кровопролитных сражений." } } } } },
    [102] = { d = 33.4, v = "human-male#50", n = { x = 395 }, c = { x = { { 0.00, "Штормград отвернулся от нас." }, { 1.91, "Злобный ветер несчастий носится по равнинам Западного Края." }, { 6.04, "Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь." }, { 11.70, "Мы, бывшие фермеры, намерены постоять за себя." }, { 14.90, "Твоё задание, если ты за него возьмёшься, будет состоять в том, чтобы патрулировать луга Западного Края." }, { 21.99, "Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мёртвых копей." }, { 28.33, "Принеси мне восемь лап гноллов, и я вознагражу тебя за проявленное мужество." } } }, t = { d = 16.1, v = "human-male#50", n = { x = 199 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.11, "Если на стороне народного ополчения будут такие смельчаки, как ты, Западный Край сможет когда-нибудь вновь стать процветающей житницей, какой был когда-то." }, { 11.55, "Пожалуйста, прими эту награду в знак признательности за твои усилия." } } } } },
    [103] = { d = 32.9, v = "creature/grayson", n = { x = 391 }, c = { x = { { 0.00, "Ночь, когда погибла семья смотрителя маяка, была ужасной." }, { 4.08, "Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вёл нападавших." }, { 10.04, "Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам – моя забота." }, { 19.96, "Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи." }, { 25.68, "Помогите мне поддержать огонь факела – принесите пять фляг масла, собрав их с сельскохозяйственных големов." } } }, t = { d = 20.1, g = 1, v = "creature/grayson", n = { m = 220, f = 220 }, c = { m = { { 0.00, "Хвала тебе, смелый герой." }, { 1.93, "Рифы побережья Западного Края будут освещены благодаря твоим трудам." }, { 6.96, "Множество жизней будет спасено, пока горит факел." }, { 10.63, "Меня постигла бессмысленная смерть на этом самом побережье." }, { 14.88, "Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы." } }, f = { { 0.00, "Хвала тебе, смелая героиня." }, { 2.08, "Рифы побережья Западного Края будут освещены благодаря твоим трудам." }, { 7.15, "Множество жизней будет спасено, пока горит факел." }, { 10.86, "Меня постигла бессмысленная смерть на этом самом побережье." }, { 15.15, "Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы." } } } } },
    [104] = { d = 35.4, v = "creature/grayson", n = { x = 401 }, c = { x = { { 0.00, "Когда моя жизнь оборвалась на скалах, я и понятия не имел, что уготовано мне на том свете." }, { 6.38, "Маяк той ночью не светил, поскольку Старый Мрачноглаз перепугал семью смотрителя, и они убежали." }, { 13.34, "Потом они вернулись и вновь зажгли пламя, но Мрачноглаз заставил более слабых духом мурлоков атаковать маяк вместе с ним." }, { 22.10, "Во второй раз семье смотрителя не повезло, и вся она погибла у меня на глазах." }, { 27.71, "Убейте Старого Мрачноглаза, если увидите его на берегу, принесите мне одну из его чешуй, и я вознагражу вас." } } }, t = { d = 21.3, v = "creature/grayson", n = { x = 224 }, c = { x = { { 0.00, "Итак, это злобное чудовище, Мрачноглаз, мертво." }, { 3.79, "Хорошая работа." }, { 5.06, "Вы своими руками прервали одну жизнь, но, возможно, тем самым спасли множество других." }, { 11.80, "Великое море, само по себе исполненное угрозы, станет этой ночью чуточку безопаснее благодаря вашему героическому деянию." } } } } },
    [105] = { d = 33.5, v = "scourge-male", n = { x = 304 }, c = { x = { { 0.00, "Увы, пришло время напасть на Андорал и изгнать оттуда лича!" }, { 5.61, "Злобный Араж Призыватель обосновался в самом сердце руин." }, { 10.98, "Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы." }, { 22.62, "Без многочисленных помощников тебе нечего и думать одержать над ним верх." }, { 29.22, "Убей Аража и принеси мне его кристалл-талисман!" } } }, t = { d = 25.8, g = 1, v = "scourge-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Свершилось!" }, { 1.23, "Араж... этот лич наконец-то пал!" }, { 4.62, "Сегодня ты оказал огромную услугу Орде." }, { 8.87, "Храбрость и упорство – спутники подлинного героизма." }, { 14.34, "Прошу тебя, прими это в залог нашей благодарности." }, { 19.82, "Пусть все знают, что благодаря тебе Орда одержала победу!" } }, f = { { 0.00, "Свершилось!" }, { 1.23, "Араж... этот лич наконец-то пал!" }, { 4.64, "Сегодня ты оказала огромную услугу Орде." }, { 8.99, "Храбрость и упорство – спутники подлинного героизма." }, { 14.47, "Прошу тебя, прими это в залог нашей благодарности." }, { 19.96, "Пусть все знают, что благодаря тебе Орда одержала победу!" } } } } },
    [106] = { d = 22.6, v = "human-female", n = { x = 247 }, c = { x = { { 0.00, "За что мне это наказание?" }, { 1.80, "Моё сердце отдано Томми Джо Стоунфилду, я жить без него не могу, но наши родители – заклятые враги!" }, { 8.88, "Я не только встретиться – даже взглянуть на него не могу!" }, { 12.99, "Пожалуйста, отнеси Томми Джо это письмо." }, { 15.95, "Он обычно бывает у реки к западу от фермы Стоунфилдов, а сама ферма – тоже к западу отсюда..." } } }, t = { d = 4.7, v = "human-male", n = { x = 45 }, c = { x = { { 0.00, "Я больше не могу жить в разлуке с ней!" }, { 3.15, "Я должен увидеть её!" } } } } },
    [107] = { d = 14.2, v = "human-female#45", n = { x = 155 }, c = { x = { { 0.00, "Бьюсь об заклад, у Вильяма Песта найдётся зелье, которое поможет соединить наших юных влюблённых!" }, { 7.29, "Вот, держи: отнесёшь эту записку Вильяму." }, { 10.42, "Найдёшь его в Златоземье, в таверне \"Гордость льва\"." } } }, t = { d = 15.8, v = "human-male", n = { x = 141 }, c = { x = { { 0.00, "У меня просто сердце разрывается, как подумаю об этих бедных детках, Мейбелл и Томми Джо." }, { 7.62, "Ах, молодость..." }, { 8.99, "Весна..." }, { 9.75, "Любовь..." }, { 10.59, "Думаю, я смогу им чем-нибудь помочь." }, { 13.71, "Погоди-ка, дай подумать..." } } } } },
    [109] = { d = 22.1, g = 1, v = "human-male", n = { x = 249 }, c = { m = { { 0.00, "Похоже, герой, тебе довелось побывать не в одном бою..." }, { 3.92, "Думаю, тебе стоит явиться с докладом к Гриану Камнегриву." }, { 7.96, "Он возглавляет ополчение, защищающее фермерские земли Западного Края." }, { 12.75, "Думаю, твоя помощь ему не помешает." }, { 15.30, "Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края." } }, f = { { 0.00, "Похоже, героиня, тебе довелось побывать не в одном бою..." }, { 4.03, "Думаю, тебе стоит явиться с докладом к Гриану Камнегриву." }, { 8.07, "Он возглавляет ополчение, защищающее фермерские земли Западного Края." }, { 12.85, "Думаю, твоя помощь ему не помешает." }, { 15.39, "Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края." } } }, t = { d = 16.5, v = "human-male", n = { x = 189 }, c = { x = { { 0.00, "А, так это мой друг тебя сюда отправил?" }, { 2.80, "С его стороны это большая любезность." }, { 5.54, "Что ж..." }, { 6.11, "Монархия Штормграда больше не поддерживает нас." }, { 9.43, "Остаётся полагаться на ополчение." }, { 11.72, "Если ты хочешь сражаться за свободу вместе с нами, я буду рад этому." } } } } },
    [110] = { d = 24.2, v = "goblin-male", n = { x = 265 }, c = { x = { { 0.00, "Мне понадобится время на изучение оборудования Холстомера... и на приведение в порядок его дел." }, { 7.24, "Ох, печёнкой чую, не последняя это потеря, проклятые жуки ещё покажут нам, где раки зимуют!" }, { 13.91, "Поговори, пожалуйста, с алхимиком Пестычинсом, узнай, как проходят исследования частей насекомых." }, { 21.34, "Если всё готово, принеси мне результаты." } } }, t = { d = 19.8, v = "goblin-male#108", n = { x = 205 }, c = { x = { { 0.00, "Да, результаты готовы." }, { 1.81, "Они, мягко говоря, неприятные." }, { 4.35, "К сожалению, наши подозрения подтвердились, и насекомых контролирует неведомая сила." }, { 11.08, "И не только неведомая, но и злобная." }, { 13.98, "Этих насекомых превратили в настоящих опустошителей." }, { 18.18, "Я такого ещё не видел!" } } } } },
    [111] = { d = 10.6, v = "human-male", n = { x = 119 }, c = { x = { { 0.00, "Прошу тебя, поговори с моей бабулей." }, { 2.56, "Если кто и может сделать так, чтобы мы с Мейбелл были вместе, так это она." }, { 7.67, "Бабуля сейчас дома – это к востоку отсюда..." } } }, t = { d = 12.3, v = "human-female#45", n = { x = 119 }, c = { x = { { 0.00, "Пока наши семьи враждуют, у Томми Джо и Мейбелл вряд ли есть шансы; но, может, мы дадим им возможность хоть немного побыть вместе." }, { 10.50, "Хм..." }, { 10.94, "Что бы придумать..." } } } } },
    [112] = { d = 25.4, v = "human-male", n = { x = 310 }, c = { x = { { 0.00, "Да, я могу приготовить для Мейбелл напиток невидимости, чтобы она могла убежать с Виноградников Маклура к своему Томми Джо." }, { 8.32, "Но для этого мне нужен хрустальный фукус." }, { 11.12, "Эти водоросли растут в океане, и мурлокам иногда удаётся добыть их." }, { 15.68, "Может, у тех, что живут на берегах Хрустального озера, найдётся нужный компонент." }, { 21.08, "А озеро найти просто: нужно только пойти на восток от Златоземья." } } }, t = { d = 9.1, v = "human-male", n = { x = 75 }, c = { x = { { 0.00, "Ага, вот и фукус!" }, { 1.72, "Отлично, просто отлично!" }, { 4.13, "А теперь погоди минутку: сейчас напиток будет готов." } } } } },
    [113] = { d = 28.4, v = "goblin-male#108", n = { x = 346 }, c = { x = { { 0.00, "Старший геодезист Рудознатец должен немедленно увидеть мой отчёт." }, { 4.41, "Более того... его должны увидеть все, кто умеет читать." }, { 8.27, "Серьёзная опасность грозит не только Танарису и Прибамбасску, но если сидеть, сложа руки, то и всему южному Калимдору." }, { 16.29, "Да что там, всему Азероту – эти твари не собираются останавливаться." }, { 20.89, "Пусть Рудознатец сделает копию моего отчёта, распространи её среди всех своих союзников." }, { 26.83, "Пусть все узнают об этом!" } } }, t = { d = 25.1, v = "goblin-male", n = { x = 290 }, c = { x = { { 0.00, "Спасибо за доставку отчёта, младший геодезист." }, { 3.30, "Вот плата за верную службу Водной компании Прибамбасска." }, { 7.37, "Хотя я не слишком люблю делиться информацией задарма с теми, кто мог бы заплатить за неё звонкой монетой, но Пестычинса я знаю много лет." }, { 17.12, "Если он советует рассказать о нашествии насекомых всем и каждому, да будет так." }, { 22.74, "Подожди немного, и я сделаю копию." } } } } },
    [114] = { d = 8.0, v = "human-male", n = { x = 98 }, c = { x = { { 0.00, "Отнеси этот напиток невидимости юной Мейбелл." }, { 3.18, "Его действия хватит на то, чтобы девушка успела встретиться с Томми Джо." } } }, t = { d = 17.7, v = "human-female", n = { x = 205 }, c = { x = { { 0.00, "Мне так стыдно, что приходится обманывать свою семью..." }, { 3.88, "Но я не могу отказаться от Томми!" }, { 6.24, "Благодарю тебя." }, { 7.38, "Как только подвернётся случай, я выпью этот напиток и найду способ пробраться к моему любимому." }, { 14.13, "А в дополнение к словам благодарности прими вот это." } } } } },
    [115] = { d = 25.9, v = "human-male", n = { x = 308 }, c = { x = { { 0.00, "Орки из клана Чёрной Горы позвали на помощь чародеев, а те принесли с собой источники тёмной силы – полуночные сферы." }, { 8.14, "Чародеи наносят чувствительные удары по защитникам Красногорья, и мы должны как можно скорее лишить их столь мощного оружия." }, { 16.79, "Добудь для меня полуночные сферы." }, { 19.17, "Ты найдёшь их у чародеев Чёрной Горы." }, { 21.68, "Я придумаю, как избавиться от Сфер, чтобы мир стал лучше и чище!" } } }, t = { d = 4.6, v = "human-male", n = { x = 52 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.25, "Я немедленно прикажу уничтожить эту мерзость." } } } } },
    [116] = { d = 27.0, v = "human-male", n = { x = 307 }, c = { x = { { 0.00, "Я в безвыходном положении." }, { 1.86, "Бутылки опустели, а новые поставки так и не пришли." }, { 5.52, "Ох уж эти проклятущие орки." }, { 7.51, "Может, ты мне поможешь?" }, { 9.18, "Забери бочонок \"Мерло\" в Штормграде, бутылку самогона в Темнолесье, бурдюк со сладким ромом в Златоземье и бочонок громоварского у Мрачнобуха." }, { 19.27, "Он сейчас в южной части Западного края, в лагере у холмов Кинжалов." }, { 24.15, "Принеси это всё мне, и я тебя вознагражу." } } }, t = { d = 18.1, v = "human-male", n = { x = 215 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.21, "Я представляю, сколько дорог тебе пришлось исходить, чтобы принести мне такое количество первосортных напитков." }, { 9.07, "Завсегдатаи трактира будут счастливы!" }, { 11.74, "Моя жена неплохая рукодельница." }, { 14.02, "Прошу, прими плащ, сшитый ею, в знак моей признательности." } } } } },
    [117] = { d = 12.0, v = "dwarf-male", n = { x = 121 }, c = { x = { { 0.00, "Торопись, мой друг, и иди побыстрей," }, { 2.81, "Чтоб нашего пойла отведать скорей." }, { 5.55, "Оно ближе к пиву – не спутаешь с кашей," }, { 8.71, "Но нужен нам хмель, чтоб сварить пойло наше." } } }, t = { d = 11.8, v = "dwarf-male", n = { x = 106 }, c = { x = { { 0.00, "Хмель, и ячмень, и дрожжи, и солод -" }, { 3.02, "От вкуса кидает то в жар, то в холод." }, { 6.11, "Не надо просить и не надо молить," }, { 8.97, "Ведь можно себе из бочонка налить!" } } } } },
    [118] = { d = 15.0, v = "human-male#50", n = { x = 186 }, c = { x = { { 0.00, "Я потратил так много железа на доспехи и оружие для стражников Штормграда, что теперь его не хватает даже на подковы для лошадей!" }, { 8.61, "Отнеси эту записку кузнецу Аргусу в Златоземье, я хочу попросить его прислать мне партию подков." } } }, t = { d = 2.8, v = "human-male#50", n = { x = 31 }, c = { x = { { 0.00, "Так старому Вернеру нужны подковы, да?!" } } } } },
    [119] = { d = 14.0, v = "human-male#50", n = { x = 154 }, c = { x = { { 0.00, "Ладно, так и быть, пошлю ему пятьдесят подков…" }, { 3.28, "Вот они, уже упакованы, осталось только доставить!" }, { 6.88, "Передай Вернеру, что с ним приятно иметь дело." }, { 10.17, "Пусть не забудет прочитать записку, прикреплённую к ящику!" } } }, t = { d = 11.6, g = 1, v = "human-male#50", n = { m = 96, f = 98 }, c = { m = { { 0.00, "Спасибо, ты здорово мне помог." }, { 2.76, "Что это?" }, { 3.57, "Аргус приложил к ящику записку..." }, { 6.65, "Что?!" }, { 7.14, "Аргус хочет ПЛАТЫ?" }, { 8.92, "Пф!" }, { 9.25, "Ладно, спасибо за помощь." } }, f = { { 0.00, "Спасибо, ты здорово мне помогла." }, { 2.92, "Что это?" }, { 3.73, "Аргус приложил к ящику записку..." }, { 6.81, "Что?!" }, { 7.30, "Аргус хочет ПЛАТЫ?" }, { 9.08, "Пф!" }, { 9.41, "Ладно, спасибо за помощь." } } } } },
    [120] = { d = 19.6, g = 1, v = "human-male", n = { x = 218 }, c = { m = { { 0.00, "Тяжёлые настали времена, герой." }, { 2.28, "Город в непрерывной осаде." }, { 4.24, "Если из Штормграда не пришлют подкрепление, нам не выстоять." }, { 8.54, "Я доверяю тебе важнейшее письмо." }, { 10.95, "Отнеси его в Штормград генералу Маркусу Джонатану." }, { 14.66, "И поскорее возвращайся с вестями – неважно, добрыми или злыми." }, { 19.22, "Спеши!" } }, f = { { 0.00, "Тяжёлые настали времена, героиня." }, { 2.39, "Город в непрерывной осаде." }, { 4.32, "Если из Штормграда не пришлют подкрепление, нам не выстоять." }, { 8.58, "Я доверяю тебе важнейшее письмо." }, { 10.96, "Отнеси его в Штормград генералу Маркусу Джонатану." }, { 14.64, "И поскорее возвращайся с вестями – неважно, добрыми или злыми." }, { 19.15, "Спеши!" } } }, t = { d = 18.3, g = 1, v = "human-male", n = { x = 209 }, c = { m = { { 0.00, "Вольно, герой." }, { 1.07, "Чиновник Соломон – благородный человек." }, { 3.84, "Его слова много для меня значат." }, { 6.23, "Я поговорю с королём и объясню ему ситуацию." }, { 9.32, "Заверьте доброго судью, что он получит поддержку армии Штормграда." }, { 13.98, "Я вышлю подкрепление, как только получу приказ Его Величества." } }, f = { { 0.00, "Вольно, героиня." }, { 1.19, "Чиновник Соломон – благородный человек." }, { 3.96, "Его слова много для меня значат." }, { 6.34, "Я поговорю с королём и объясню ему ситуацию." }, { 9.42, "Заверьте доброго судью, что он получит поддержку армии Штормграда." }, { 14.07, "Я вышлю подкрепление, как только получу приказ Его Величества." } } } } },
    [121] = { d = 7.6, g = 1, v = "human-male", n = { m = 76, f = 78 }, c = { m = { { 0.00, "Пока я жду ответа от короля, хочу, чтобы ты отнёс это письмо мировому судье Соломону." }, { 6.47, "Свободен, герой!" } }, f = { { 0.00, "Пока я жду ответа от короля, хочу, чтобы ты отнесла это письмо мировому судье Соломону." }, { 6.39, "Свободна, героиня!" } } }, t = { d = 16.4, g = 1, v = "human-male", n = { x = 155 }, c = { m = { { 0.00, "Благодарю тебя, герой." }, { 1.88, "В знак признательности Озёр и Штормграда прими эти деньги." }, { 6.52, "Хотя, признаться, смысл этого письма туманен." }, { 10.21, "Что-то неладно в нашем королевстве." }, { 13.11, "Боюсь, это не конец, а начало войны." } }, f = { { 0.00, "Благодарю тебя, героиня." }, { 2.06, "В знак признательности Озёр и Штормграда прими эти деньги." }, { 6.77, "Хотя, признаться, смысл этого письма туманен." }, { 10.52, "Что-то неладно в нашем королевстве." }, { 13.46, "Боюсь, это не конец, а начало войны." } } } } },
    [122] = { d = 24.0, v = "human-male#50", n = { x = 277 }, c = { x = { { 0.00, "В обмен на подковы Аргус из Златоземья просит брюшную чешую чёрных дракончиков." }, { 5.55, "Если ты добудешь мне шесть лоскутов чешуи, я смогу расплатиться с Аргусом..." }, { 10.84, "И для тебя что-нибудь сделаю." }, { 12.92, "Чёрных дракончиков можно отыскать к югу от Озёр, но им не сидится на одном месте." }, { 18.53, "Проще всего высматривать их, направляясь по другим делам, и охотиться по случаю." } } }, t = { d = 3.7, v = "human-male#50", n = { x = 39 }, c = { x = { { 0.00, "Спасибо!" }, { 0.70, "Теперь я смогу расплатиться с Аргусом..." } } } } },
    [123] = { d = 29.3, v = "narrator", n = { x = 308 }, c = { x = { { 0.00, "На этом листке – расписание поставок золота из рудников в Элвиннском лесу." }, { 5.91, "Поставки расписаны по дням и часам, а в качестве получателя указан некий \"Вымогатель\"." }, { 12.68, "Судя по всему, Вымогатель обосновался неподалёку от тыквенного поля Бреквеллов в восточной части Элвиннского леса." }, { 21.66, "Похоже, это важные сведения." }, { 24.02, "Было бы неплохо сообщить их маршалу Дугхану: он сейчас в Златоземье." } } }, t = { d = 11.2, v = "human-male", n = { x = 116 }, c = { x = { { 0.00, "Хм..." }, { 0.41, "Я слышал об этом \"Вымогателе\", вот только не знаю, на кого он работает." }, { 5.81, "Должен тебя поблагодарить: расписание поможет нам разгадать эту тайну..." } } } } },
    [124] = { d = 15.5, v = "human-male#50", n = { x = 187 }, c = { x = { { 0.00, "Будто нам одних орков мало!" }, { 1.96, "А теперь вдоль хребта рядом с моими стойлами шастают громилы и мистики гноллов и при случае воруют лошадей…" }, { 9.35, "Если ты сможешь избавить меня от этих проходимцев, мы с лошадьми будем весьма признательны." } } }, t = { d = 1.8, v = "human-male#50", n = { x = 21 }, c = { x = { { 0.00, "Благодарю тебя за помощь!" } } } } },
    [125] = { d = 23.2, v = "human-male", n = { x = 261 }, c = { x = { { 0.00, "Мне не помешала бы помощь." }, { 1.88, "Наш город в осаде, и достать припасы и оборудование всё труднее." }, { 6.50, "Мои инструменты везли из Златоземья в фургоне, но мост был уничтожен." }, { 11.44, "Мы перегрузили их в лодку, но тут орки пробили её снарядом из катапульты!" }, { 16.64, "И вот невезенье, ящик опустился на самое дно озера." }, { 20.34, "Достань его, и я щедро вознагражу тебя." } } }, t = { d = 4.9, v = "human-male", n = { x = 55 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.29, "Я уж и не надеялся вновь увидеть свои инструменты." } } } } },
    [126] = { d = 23.6, v = "human-male#50", n = { x = 265 }, c = { x = { { 0.00, "Гноллы по-прежнему здесь." }, { 1.82, "Я слышу, как они завывают, охотясь в холмах над Приозёрьем." }, { 6.05, "И один из них воет громче других – это Изувой, их вождь." }, { 10.15, "Стоит его прикончить, и вся стая разбежится!" }, { 13.40, "Убей его и принеси в доказательство отрубленную лапу." }, { 17.30, "Соблюдай осторожность, этот гнолл заслуженно возглавляет целую стаю." }, { 22.25, "Он совсем не прост..." } } }, t = { d = 10.2, v = "human-male#50", n = { x = 125 }, c = { x = { { 0.00, "И снова благодарю тебя за помощь." }, { 2.29, "Штормград еле-еле справляется с орками, у них не хватает солдат, чтобы защищать Красногорье от напастей вроде гноллов." } } } } },
    [127] = { d = 17.2, g = 1, v = "human-male", n = { m = 181, f = 182 }, c = { m = { { 0.00, "Озеро Безмолвия славится пятнистой рыбой-луной." }, { 3.62, "На неё всегда есть спрос..." }, { 5.57, "А мой запас подходит к концу!" }, { 7.78, "Принеси мне штук десять рыбин, и я хорошо за них заплачу." }, { 12.01, "Если ты сам не умеешь удить, то..." }, { 14.56, "Попытайся отнять рыбу у мурлоков!" } }, f = { { 0.00, "Озеро Безмолвия славится пятнистой рыбой-луной." }, { 3.65, "На неё всегда есть спрос..." }, { 5.60, "А мой запас подходит к концу!" }, { 7.83, "Принеси мне штук десять рыбин, и я хорошо за них заплачу." }, { 12.08, "Если ты сама не умеешь удить, то..." }, { 14.78, "Попытайся отнять рыбу у мурлоков!" } } }, t = { d = 3.8, v = "human-male", n = { x = 38 }, c = { x = { { 0.00, "Иметь с тобой дело – одно удовольствие, дружище!" } } } } },
    [128] = { d = 28.6, v = "human-male", n = { x = 326 }, c = { x = { { 0.00, "Мы должны уничтожить клан Чёрной Горы." }, { 2.67, "Враг вторгся в наши земли." }, { 4.58, "Эти горы по праву принадлежат королю Штормграда." }, { 8.08, "До нас дошли сведения, что главы всех видов войск клана называются воителями." }, { 13.49, "Их можно отыскать в северном лагере, к западу от дороги, ведущей в Пылающие степи." }, { 19.35, "Мировой судья Соломон распорядился перебить этих гнусных тварей." }, { 23.99, "Убей пятнадцать воителей из клана Чёрной Горы и возвращайся ко мне." } } }, t = { d = 8.0, g = 1, v = "human-male", n = { m = 76, f = 78 }, c = { m = { { 0.00, "Вижу, ты доблестно сражался с кланом Чёрной Горы, герой." }, { 4.49, "Ты оказал нашему городу неоценимую услугу." } }, f = { { 0.00, "Вижу, ты доблестно сражалась с кланом Чёрной Горы, героиня." }, { 4.68, "Ты оказала нашему городу неоценимую услугу." } } } } },
    [129] = { d = 20.1, v = "human-female", n = { x = 242 }, c = { x = { { 0.00, "Можешь оказать мне услугу?" }, { 1.82, "Я приготовила обед для стражника Паркера, но он ушёл на дежурство..." }, { 6.32, "Он-то может постоять за себя, но простой горожанке вроде меня не стоит соваться в те края." }, { 12.51, "Если ты отнесёшь ему обед, я бесплатно тебя накормлю!" }, { 16.15, "Паркер патрулирует участок дороги, ведущей в Сумеречный лес." } } }, t = { d = 8.0, v = "human-male", n = { x = 80 }, c = { x = { { 0.00, "Спасибо, вкусно и сытно покушать я люблю." }, { 3.55, "Хранить Приозёрье от нападений орков и гноллов нелегко!" } } } } },
    [130] = { d = 15.1, v = "human-male", n = { x = 176 }, c = { x = { { 0.00, "Если ты всё равно идёшь к Дарси, не отнесёшь ли ей от меня цветы?" }, { 4.39, "Букетик можно приобрести у травницы в Приозёрье, в западной части города." }, { 9.39, "Только когда будешь покупать цветы… не говори травнице Марти, от кого они и кому..." } } }, t = { d = 15.1, g = 1, v = "human-female#47", n = { m = 162, f = 162 }, c = { m = { { 0.00, "Тебе нужен букет цветов?" }, { 1.92, "Ты вроде бы у нас недавно... уже нашёл даму сердца?" }, { 5.68, "Понимаю, мне не следует совать нос не в своё дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена." } }, f = { { 0.00, "Тебе нужен букет цветов?" }, { 1.89, "Ты вроде бы у нас недавно... уже нашла даму сердца?" }, { 5.66, "Понимаю, мне не следует совать нос не в своё дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена." } } } } },
    [131] = { d = 5.1, v = "human-female#47", n = { x = 47 }, c = { x = { { 0.00, "Вот и букет." }, { 1.09, "Я выбрала для тебя нарциссы." }, { 3.57, "Мои любимые цветы!" } } }, t = { d = 21.1, g = 1, v = "human-female", n = { m = 220, f = 222 }, c = { m = { { 0.00, "Какая прелесть!" }, { 1.17, "Надо поскорее поставить их в воду!" }, { 3.70, "Но... это любимые цветы Марти." }, { 5.97, "Неужели Паркер послал тебя за букетом к этой ревнивой мегере?" }, { 10.51, "Ты ведь не сказал, для кого они?" }, { 12.84, "Иначе не удивлюсь, если она их отравила." }, { 15.83, "Нет-нет, ты ни в чём не виноват." }, { 18.10, "Большое спасибо!" }, { 19.33, "А вот и твой обед." } }, f = { { 0.00, "Какая прелесть!" }, { 1.20, "Надо поскорее поставить их в воду!" }, { 3.79, "Но... это любимые цветы Марти." }, { 6.11, "Неужели Паркер послал тебя за букетом к этой ревнивой мегере?" }, { 10.77, "Ты ведь не сказала, для кого они?" }, { 13.23, "Иначе не удивлюсь, если она их отравила." }, { 16.28, "Нет-нет, ты ни в чём не виновата." }, { 18.67, "Большое спасибо!" }, { 19.94, "А вот и твой обед." } } } } },
    [132] = { d = 20.9, v = "human-male#50", n = { x = 247 }, c = { x = { { 0.00, "То, о чём я хочу вам рассказать, может стоить мне жизни." }, { 3.87, "Бандиты из Братства Справедливости замышляют что-то крупномасштабное." }, { 8.61, "Последнее, что я слышал, – что они действуют заодно со всякими гноллами, кобольдами и даже гоблинами." }, { 15.60, "Отнеси эту записку Камнегриву." }, { 17.78, "В ней разъясняется всё, что я знаю на эту тему." } } }, t = { d = 9.5, v = "human-male", n = { x = 99 }, c = { x = { { 0.00, "Эх!.." }, { 0.42, "Надо было сгноить этого мошенника, когда у меня был шанс." }, { 4.94, "Но эта информация действительно очень важна." }, { 8.42, "Хорошая работа." } } } } },
    [133] = { d = 29.2, v = "human-male", n = { x = 362 }, c = { x = { { 0.00, "Я живу вдали от города, никто меня не защищает, и даже странно, как это меня до сих пор не сожрали вурдалаки и мертвяки!" }, { 7.91, "Только вчера несколько костеглодов ломились ко мне в дом!.." }, { 11.75, "Я хочу сделать особую фигурку – что-то вроде пугала для этой нежити." }, { 16.35, "Для этого мне понадобится несколько рёбер вурдалаков." }, { 19.78, "Их можно добыть, убивая плотоядов, костеглодов, мозгоедов, гнилую нежить и распространителей чумы." }, { 26.21, "Принеси мне рёбра, и я дам тебе несколько монет." } } }, t = { d = 3.8, v = "human-male", n = { x = 29 }, c = { x = { { 0.00, "О, спасибо." }, { 1.25, "Это наверняка сработает!" } } } } },
    [134] = { d = 22.5, v = "human-male", n = { x = 259 }, c = { x = { { 0.00, "Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров!" }, { 5.86, "Я сбежал, бросив свой ящик с ценными инструментами и травами." }, { 10.10, "Прогнав меня, они вернулись к своему кургану в южной части Сумеречного леса." }, { 15.52, "Думаю, они оставили мой ящик неподалёку от кургана." }, { 19.07, "Прошу тебя, верни мне ящик, без него я как без рук." } } }, t = { d = 9.9, v = "human-male", n = { x = 88 }, c = { x = { { 0.00, "Хвала Нек... то есть ТЕБЕ!" }, { 2.34, "Ты более чем заслуживаешь награды." }, { 5.40, "Ага!" }, { 5.89, "Как я счастлив!" }, { 7.26, "Впереди много радостных ночей!" } } } } },
    [135] = { d = 27.6, v = "human-male", n = { x = 316 }, c = { x = { { 0.00, "Интересно, что имел в виду Вилли, когда упомянул о Каменщиках." }, { 4.46, "Оговорился или проговорился?" }, { 6.51, "Могут ли разбойники из Братства Справедливости быть связаны с Каменщиками?" }, { 11.67, "Только один человек должен знать наверняка: Матиас Шоу, глава ШРУ." }, { 16.77, "Покажите ему записку Вилли и посмотрите, сможет ли он пролить свет на эту тайну." }, { 22.51, "Если вам не сразу удастся найти Шоу, поищите в Казармах в Старом городе." } } }, t = { d = 4.2, v = "human-male", n = { x = 48 }, c = { x = { { 0.00, "Это дело может оказаться сложнее, чем полагает Камнегрив." } } } } },
    [136] = { d = 37.8, v = "narrator", n = { x = 369 }, c = { x = { { 0.00, "Если ты читаешь это – значится, старина капитан Сандерс уже покоится на дне." }, { 6.44, "Так что моё сокровище теперь может стать твоим, главное – следуй подсказкам." }, { 12.74, "Сначала найди мой сундучок." }, { 15.06, "Его, должно быть, уже наполовину песком занесло, а находится он на западном побережье Западного Края рядом с обломками корабля." }, { 25.70, "Обломков-то там много, но ржавый якорь на берегу – только один." }, { 31.02, "Найди этот якорь, и ты найдёшь мой сундучок." }, { 34.69, "Загляни внутрь за следующей подсказкой." } } }, t = { d = 15.7, v = "narrator", n = { x = 145 }, c = { x = { { 0.00, "Сундучок медленно, со скрипом, открывается." }, { 3.78, "Кажется, ничего в нём нет, кроме песка и воды." }, { 7.88, "Постойте-ка!" }, { 8.98, "Проворно выползает маленький крабик, а в клешнях у него – следующая подсказка!" } } } } },
    [138] = { d = 19.0, v = "narrator", n = { x = 185 }, c = { x = { { 0.00, "Ключ к поиску сокровища таков: \"Отличная работа, приятель!" }, { 4.80, "Теперь тебе идти на восток." }, { 7.16, "На восток в холмы, на восток к дороге." }, { 10.33, "Ищи на обочине дороги развалины старого очага." }, { 14.24, "Там найдёшь старую бочку, в которой и будет следующий ключ\"." } } }, t = { d = 4.1, g = 1, v = "narrator", n = { m = 34, f = 35 }, c = { m = { { 0.00, "Отличная работа, охотник за сокровищами!" } }, f = { { 0.00, "Отличная работа, охотница за сокровищами!" } } } } },
    [139] = { d = 24.5, v = "narrator", n = { x = 243 }, c = { x = { { 0.00, "Обыскивая бочку, вы обнаруживаете ещё один кусок пергамента." }, { 4.94, "На нём написано: \"А теперь от этой бочки поверни к северу." }, { 9.74, "Прямо, как ворон летит, иди, пока не наткнёшься на пустой кувшин рядом с одинокой ветряной мельницей на прибрежных утёсах." }, { 19.69, "Осмотри кувшин внимательно – может, и найдёшь то, что ищешь\"." } } }, t = { d = 4.5, g = 1, v = "narrator", n = { m = 38, f = 42 }, c = { m = { { 0.00, "Ты на пути к главному призу, искатель сокровищ!" } }, f = { { 0.00, "Ты на пути к главному призу, искательница сокровищ!" } } } } },
    [140] = { d = 35.2, g = 1, v = "narrator", n = { m = 344, f = 345 }, c = { m = { { 0.00, "Конечно же, глубоко внутри старого кувшина лежит ещё одна подсказка к поиску сокровища Сандерса." }, { 7.83, "Чернила кое-где расплылись, а бумага отдаёт виски, но кое-что вам удалось разобрать: \"Раз уж ты нашёл мой старый кувшин из-под виски, значит, ты близко подобрался к сокровищу!" }, { 21.75, "Иди от бутылки на запад и спустись к берегу." }, { 25.38, "Доберёшься до воды – не останавливайся!" }, { 28.42, "Плыви, пока не найдёшь остров, где и находится мой сундук с сокровищем!\"" } }, f = { { 0.00, "Конечно же, глубоко внутри старого кувшина лежит ещё одна подсказка к поиску сокровища Сандерса." }, { 8.07, "Чернила кое-где расплылись, а бумага отдаёт виски, но кое-что вам удалось разобрать: \"Раз уж ты нашла мой старый кувшин из-под виски, значит, ты близко подобралась к сокровищу!" }, { 22.57, "Иди от бутылки на запад и спустись к берегу." }, { 26.31, "Доберёшься до воды – не останавливайся!" }, { 29.45, "Плыви, пока не найдёшь остров, где и находится мой сундук с сокровищем!\"" } } }, t = { d = 10.6, v = "narrator", n = { x = 103 }, c = { x = { { 0.00, "Петли на крышке старого сундука заржавели, но поддаются." }, { 4.97, "Вы с усилием открываете сундук и забираете сокровище." }, { 9.62, "Поздравляем!" } } } } },
    [141] = { d = 28.5, v = "human-male", n = { x = 375 }, c = { x = { { 0.00, "Гильдию каменщиков возглавлял человек по имени Эдвин ван Клиф." }, { 3.96, "Именно он занимался восстановлением Штормграда после разорения его орками во время Первой войны." }, { 10.15, "Должно быть, ван Клиф и его люди остались недовольны тем, как с ними обошёлся король, когда восстановление города было завершено." }, { 18.29, "Это могло бы объяснить пару вещей." }, { 20.59, "Я тут расписал всё более подробно для вашего начальства в Западном Крае." }, { 25.18, "Сразу же отправляйтесь туда и передайте ему документ!" } } }, t = { d = 13.8, v = "human-male", n = { x = 174 }, c = { x = { { 0.00, "Эдвин ван Клиф..." }, { 1.14, "Мне хорошо известно это имя." }, { 3.13, "Обидно думать, что этот трудолюбивый и талантливый человек мог превратиться в такого мерзавца." }, { 9.40, "Мне понадобятся дополнительные доказательства, чтобы я поверил в это." } } } } },
    [142] = { d = 22.8, g = 1, v = "human-male", n = { x = 271 }, c = { m = { { 0.00, "Нам нужно выяснить местонахождение Убежища Братства Справедливости." }, { 4.56, "Путник, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и Рудником Янго видели вестника из Братства Справедливости." }, { 14.78, "Я хочу, чтобы вы его поймали." }, { 16.87, "Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено." } }, f = { { 0.00, "Нам нужно выяснить местонахождение Убежища Братства Справедливости." }, { 4.58, "Путница, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и Рудником Янго видели вестника из Братства Справедливости." }, { 14.90, "Я хочу, чтобы вы его поймали." }, { 17.01, "Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено." } } }, t = { d = 28.6, v = "human-male", n = { x = 357 }, c = { x = { { 0.00, "Вот явное доказательство того, что ими верховодит ван Клиф." }, { 3.89, "Теперь всё, что нам нужно узнать, – это где прячутся бандиты братства." }, { 8.56, "Нам тут немного повезло, пока вас не было." }, { 11.37, "Мы поймали вора, пытавшегося украсть повозку Сальдена." }, { 15.02, "Он пообещал навести нас на убежище бандитов в обмен на жизнь." }, { 19.03, "Я прошу вас защитить его, чтобы предатель братства мог указать, где находится убежище." }, { 24.77, "Возвращайтесь ко мне, когда выясните местонахождение убежища." } } } } },
    [143] = { d = 29.0, v = "human-male", n = { x = 365 }, c = { x = { { 0.00, "Что-то странное происходит в армии Штормграда, подкрепления всё нет и нет." }, { 4.81, "К сожалению, мы не можем позволить себе ждать." }, { 7.84, "Нельзя же сидеть сложа руки и не пытаться позвать соседей на помощь, пока доблестные воины Приозёрья погибают один за другим." }, { 16.15, "Говорят, в Западном Крае создано народное ополчение." }, { 19.66, "Отнеси мою просьбу о помощи его предводителю, Гриану Камнегриву." }, { 23.99, "Может быть, его люди помогут нам продержаться до подхода королевских отрядов." } } }, t = { d = 4.2, g = 1, v = "human-male", n = { m = 44, f = 46 }, c = { m = { { 0.00, "Добрый вестник, ты хорошо послужил своему господину." } }, f = { { 0.00, "Добрая вестница, ты хорошо послужила своему господину." } } } } },
    [144] = { d = 24.3, g = 1, v = "human-male", n = { x = 280 }, c = { m = { { 0.00, "Меня очень огорчило письмо мирового судьи Соломона." }, { 3.70, "К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас." }, { 10.16, "Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы." }, { 16.25, "Отнеси мой ответ в Красногорье, герой, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов." } }, f = { { 0.00, "Меня очень огорчило письмо мирового судьи Соломона." }, { 3.67, "К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас." }, { 10.08, "Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы." }, { 16.11, "Отнеси мой ответ в Красногорье, героиня, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов." } } }, t = { d = 23.0, g = 1, v = "human-male", n = { m = 255, f = 256 }, c = { m = { { 0.00, "Что сказать, вести недобрые." }, { 2.04, "Я и не подозревал, что у Камнегрива трудности, схожие с нашими." }, { 6.43, "Что же отвлекает армию Штормграда от защиты её собственных земель?" }, { 11.07, "Впрочем, зря я об этом говорю вслух." }, { 13.62, "Вот, вестник." }, { 14.57, "Прими эти монеты в знак благодарности за верную службу городу." }, { 19.03, "Быть может, скоро ты мне снова понадобишься." } }, f = { { 0.00, "Что сказать, вести недобрые." }, { 2.13, "Я и не подозревал, что у Камнегрива трудности, схожие с нашими." }, { 6.71, "Что же отвлекает армию Штормграда от защиты её собственных земель?" }, { 11.56, "Впрочем, зря я об этом говорю вслух." }, { 14.22, "Вот, вестница." }, { 15.28, "Прими эти монеты в знак благодарности за верную службу городу." }, { 19.93, "Быть может, скоро ты мне снова понадобишься." } } } } },
    [145] = { d = 21.3, v = "human-male", n = { x = 257 }, c = { x = { { 0.00, "И снова мне нужна твоя помощь." }, { 2.16, "Я написал письмо лорду Чернодреву, прося его прислать нам на помощь обученных бойцов Ночного дозора на защиту Озёр." }, { 10.12, "Надо как можно скорее доставить моё послание." }, { 13.27, "Действуй осторожно." }, { 14.63, "Лорд Чернодрев – мэр города Темнолесья, расположенного в сердце Сумеречного леса." }, { 20.13, "Не сходи с дороги." } } }, t = { d = 4.4, v = "human-male", n = { x = 47 }, c = { x = { { 0.00, "Благодарю за проделанный путь." }, { 2.35, "Эти вести и вправду важны." } } } } },
    [146] = { d = 25.8, v = "human-male", n = { x = 311 }, c = { x = { { 0.00, "Не знай я мирового судью Соломона лично, решил бы, что он сошёл с ума." }, { 4.70, "Послать в Приозёрье Ночной дозор, потому что Штормград отказал в помощи?" }, { 9.58, "Мы и создали его, когда земли наводнила нечистая магия, а Штормград бросил нас на произвол судьбы." }, { 16.28, "Если я пошлю в Приозёрье Ночной дозор, то наш город падёт, едва лишь Дозор доберётся до края леса." }, { 22.87, "Отнеси мой ответ своему господину в Приозёрье." } } }, t = { d = 20.8, g = 1, v = "human-male", n = { x = 226 }, c = { m = { { 0.00, "Во имя Света!" }, { 1.03, "Армия Штормграда отступила из Западного Края." }, { 4.32, "И Дозор не сможет защищать Темнолесье?" }, { 7.10, "Здесь таится предательство." }, { 9.03, "Как же так?" }, { 9.80, "О, я забыл отблагодарить тебя за услуги, герой." }, { 13.22, "Прими вот эту плату." }, { 14.77, "А теперь извини меня." }, { 16.38, "Что-то творится в Штормграде, и я должен докопаться до сути." } }, f = { { 0.00, "Во имя Света!" }, { 1.04, "Армия Штормграда отступила из Западного Края." }, { 4.34, "И Дозор не сможет защищать Темнолесье?" }, { 7.13, "Здесь таится предательство." }, { 9.08, "Как же так?" }, { 9.86, "О, я забыл отблагодарить тебя за услуги, героиня." }, { 13.42, "Прими вот эту плату." }, { 14.98, "А теперь извини меня." }, { 16.60, "Что-то творится в Штормграде, и я должен докопаться до сути." } } } } },
    [147] = { d = 22.6, v = "human-male", n = { x = 287 }, c = { x = { { 0.00, "Если Вымогатель забирает золото с наших рудников, значит, он обворовывает королевство!" }, { 5.68, "Он должен предстать перед судом – а мне понадобится то кольцо, которое упоминалось в записке." }, { 11.77, "Возможно, оно поможет нам узнать, на кого работает этот Вымогатель..." }, { 16.39, "Здесь написано, что Вымогатель скрывается на тыквенном поле Бреквеллов." }, { 21.00, "Попробуй поискать его там." } } }, t = { d = 29.0, v = "human-male", n = { x = 319 }, c = { x = { { 0.00, "Так тебе удалось его найти?" }, { 2.12, "Отлично, просто прекрасно!" }, { 4.10, "Больше он ничего не будет \"вымогать\" на Элвиннских шахтах!" }, { 8.40, "А это кольцо..." }, { 9.59, "О, очень интересно!" }, { 11.05, "Это кольцо древнего братства Каменщиков Штормграда." }, { 14.88, "С чего бы это мелкому воришке носить кольцо гильдии?" }, { 18.85, "И как вышло, что Братство Справедливости добывает золото на наших рудниках?" }, { 24.34, "Непростые вопросы, верно?" }, { 26.26, "Надеюсь, когда-нибудь мы узнаем ответ." } } } } },
    [148] = { d = 20.8, g = 1, v = "human-male", n = { m = 238, f = 240 }, c = { m = { { 0.00, "Как же быть несчастному старику?.." }, { 2.38, "Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб..." }, { 8.18, "Мне не добраться до цели." }, { 9.99, "Не мог бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос?" }, { 15.40, "Её можно приобрести у мадам Евы, которая живёт на центральной площади города." } }, f = { { 0.00, "Как же быть несчастному старику?.." }, { 2.35, "Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб..." }, { 8.08, "Мне не добраться до цели." }, { 9.86, "Не могла бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос?" }, { 15.39, "Её можно приобрести у мадам Евы, которая живёт на центральной площади города." } } }, t = { d = 11.0, v = "human-female#45", n = { x = 106 }, c = { x = { { 0.00, "А, так тебе нужна нить из призрачных волос?" }, { 3.56, "Боюсь, мои запасы иссякли, но я могу сделать ещё..." }, { 7.85, "Если ты принесёшь мне призрачные волосы." } } } } },
    [149] = { d = 23.2, g = 1, v = "human-female#45", n = { m = 261, f = 261 }, c = { m = { { 0.00, "На старой ферме, в холмах к югу от Темнолесья, живёт несчастное привидение по имени Слепая Мэри." }, { 7.03, "Возьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы." }, { 12.29, "Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити." }, { 18.80, "Будь осторожен, рядом с домом бродит множество тёмных тварей." } }, f = { { 0.00, "На старой ферме, в холмах к югу от Темнолесья, живёт несчастное привидение по имени Слепая Мэри." }, { 7.03, "Возьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы." }, { 12.29, "Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити." }, { 18.80, "Будь осторожна, рядом с домом бродит множество тёмных тварей." } } }, t = { d = 16.6, v = "creature/banshee", n = { x = 127 }, c = { x = { { 0.00, "Что это?" }, { 0.94, "Гребень?" }, { 1.88, "Какая прелесть!" }, { 3.57, "И он спокойно скользит по моим волосам, хотя они давно сбились в ужасный слипшийся колтун." }, { 13.15, "Ах, мне бы в зеркало посмотреться..." } } } } },
    [150] = { d = 17.3, v = "human-male", n = { x = 214 }, c = { x = { { 0.00, "Мурлоки начинают нас беспокоить." }, { 2.15, "Всё больше мурлокских рыбаков селится вдоль побережья Озера Безмолвия и вовсю ловит рыбу!" }, { 8.11, "Надо изгнать их, пока они не опустошили всё озеро!" }, { 11.51, "Убей побольше мурлоков!" }, { 13.12, "Принеси мне восемь их плавников, и я найду, чем тебе отплатить..." } } }, t = { d = 10.1, v = "human-male", n = { x = 104 }, c = { x = { { 0.00, "Молодец." }, { 0.69, "Надеюсь, тебе не слишком солоно пришлось." }, { 3.91, "Странно, что они ушли так далеко от моря." }, { 7.14, "Хотелось бы знать, отчего они сбежали..." } } } } },
    [151] = { d = 33.2, g = 1, v = "human-female", n = { m = 416, f = 417 }, c = { m = { { 0.00, "Бедная старая Савраска!" }, { 1.58, "Несчастная лошадка так устала от непосильного труда и бесчисленных лишений..." }, { 6.57, "Я её покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге." }, { 12.73, "Я была бы вам очень благодарна, сэр, если бы вы могли принести ей несколько горстей овса с окрестных полей." }, { 19.72, "Уверена, что вы найдёте овёс на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях." }, { 28.99, "К юго-западу отсюда расположено несколько фермерских хозяйств." } }, f = { { 0.00, "Бедная старая Савраска!" }, { 1.59, "Несчастная лошадка так устала от непосильного труда и бесчисленных лишений..." }, { 6.60, "Я её покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге." }, { 12.78, "Я была бы вам очень благодарна, леди, если бы вы могли принести ей несколько горстей овса с окрестных полей." }, { 19.91, "Уверена, что вы найдёте овёс на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях." }, { 29.22, "К юго-западу отсюда расположено несколько фермерских хозяйств." } } }, t = { d = 5.8, v = "human-female", n = { x = 59 }, c = { x = { { 0.00, "Огромное тебе спасибо!" }, { 1.97, "Бедная старая Савраска будет просто счастлива!" } } } } },
    [152] = { d = 27.8, g = 1, v = "creature/grayson", n = { m = 308, f = 309 }, c = { m = { { 0.00, "Ты, должно быть, видел все эти обломки кораблей вдоль побережья." }, { 4.43, "Великое море и в самом деле очень сурово." }, { 7.42, "Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности." }, { 15.83, "На сегодняшний день мурлоки являются большой проблемой..." }, { 19.76, "Разберись с ними – убей семь волноловов, семь воинов, семь оракулов и семь береговиков, – и награда будет ждать тебя." } }, f = { { 0.00, "Ты, должно быть, видела все эти обломки кораблей вдоль побережья." }, { 4.50, "Великое море и в самом деле очень сурово." }, { 7.51, "Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности." }, { 15.95, "На сегодняшний день мурлоки являются большой проблемой..." }, { 19.89, "Разберись с ними – убей семь волноловов, семь воинов, семь оракулов и семь береговиков, – и награда будет ждать тебя." } } }, t = { d = 9.0, v = "creature/grayson", n = { x = 99 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.23, "У тебя отличные боевые навыки!" }, { 3.63, "Благодаря тебе побережье Западного Края стало более безопасным местом." } } } } },
    [153] = { d = 18.6, v = "human-male", n = { x = 229 }, c = { x = { { 0.00, "В Братстве Справедливости идёт постоянная кипучая деятельность." }, { 4.11, "Я уже долго слежу за их передвижениями." }, { 6.74, "Между прочим, я заметил, что многих бандитов можно опознать по красным кожаным банданам." }, { 12.64, "Принесите мне пятнадцать таких бандан, и я позабочусь о том, чтобы вы получили вознаграждение." } } }, t = { d = 6.5, v = "human-male", n = { x = 75 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.16, "Пожалуйста, примите один из этих предметов в качестве оплаты за ваши труды." } } } } },
    [154] = { d = 9.0, v = "creature/banshee", n = { x = 76 }, c = { x = { { 0.00, "НЕТ!" }, { 0.42, "Убери его, убери от меня этот гребень!" }, { 4.22, "Я чудовище, меня больше никто не назовёт прекрасной!" } } }, t = { d = 10.2, v = "human-female#45", n = { x = 112 }, c = { x = { { 0.00, "Ну, из этого выйдет целая катушка нити из призрачных волос, да ещё и останется несколько прядей." }, { 7.12, "Прими эти монеты в уплату за лишние пряди." } } } } },
    [155] = { d = 26.8, g = 1, v = "human-male", n = { m = 329, f = 329 }, c = { m = { { 0.00, "Так Камнегрив считает, что такой слабый герой сможет меня защитить?" }, { 4.42, "А ведь придётся." }, { 5.41, "Возьми-ка с собой пару-тройку друзей." }, { 7.91, "Ты же знаешь, что делать, да?" }, { 9.77, "Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости." }, { 14.60, "Держись ко мне поближе." }, { 16.12, "Бандиты братства охотятся за моей головой." }, { 18.91, "Если нас увидят вместе, они попытаются меня убить." }, { 22.28, "Дай мне знать, когда ты и друзья, которых ты соберёшь, будут готовы идти." } }, f = { { 0.00, "Так Камнегрив считает, что такая слабая героиня сможет меня защитить?" }, { 4.52, "А ведь придётся." }, { 5.50, "Возьми-ка с собой пару-тройку друзей." }, { 7.99, "Ты же знаешь, что делать, да?" }, { 9.85, "Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости." }, { 14.66, "Держись ко мне поближе." }, { 16.16, "Бандиты братства охотятся за моей головой." }, { 18.94, "Если нас увидят вместе, они попытаются меня убить." }, { 22.30, "Дай мне знать, когда ты и друзья, которых ты соберёшь, будут готовы идти." } } }, t = { d = 6.7, g = 1, v = "human-male", n = { m = 55, f = 56 }, c = { m = { { 0.00, "Великолепно, сэр путник!" }, { 1.96, "Теперь, когда мы знаем, где прячется ван Клиф, – он наш!" } }, f = { { 0.00, "Великолепно, леди путница!" }, { 2.27, "Теперь, когда мы знаем, где прячется ван Клиф, – он наш!" } } } } },
    [156] = { d = 26.0, v = "human-male#50", n = { x = 301 }, c = { x = { { 0.00, "Если ты принесёшь мне несколько цветков гнили, я сделаю для тебя сок зомби." }, { 5.33, "Цветки гнили растут в самых странных местах." }, { 8.61, "Например, в черепах ужасных скелетов и скелетов-губителей... хотя я лично туда не заглядывал!" }, { 15.29, "Кладбище Вороньего холма и Безмятежное кладбище кишмя кишат этими скелетами." }, { 20.81, "Заодно ты и нас от них избавишь." }, { 23.06, "Темнолесье будет тебе весьма признательно." } } }, t = { d = 21.0, g = 1, v = "human-male#50", n = { m = 249, f = 250 }, c = { m = { { 0.00, "Отлично, ты сумел добыть цветки гнили." }, { 2.81, "А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов." }, { 9.63, "Ночной дозор охраняет покой Темнолесья, и им нелегко приходится." }, { 14.22, "Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех." } }, f = { { 0.00, "Отлично, ты сумела добыть цветки гнили." }, { 2.86, "А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов." }, { 9.66, "Ночной дозор охраняет покой Темнолесья, и им нелегко приходится." }, { 14.24, "Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех." } } } } },
    [157] = { d = 9.2, v = "human-female#45", n = { x = 103 }, c = { x = { { 0.00, "Вот тебе нитки." }, { 1.21, "Им можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы." } } }, t = { d = 8.8, g = 1, v = "human-male", n = { m = 82, f = 82 }, c = { m = { { 0.00, "Великолепно!" }, { 1.06, "Она прекрасно подойдёт…" }, { 3.03, "Вот, дражайший путник, прими это в уплату за благороднейший поступок." } }, f = { { 0.00, "Великолепно!" }, { 1.06, "Она прекрасно подойдёт…" }, { 3.04, "Вот, дражайшая путница, прими это в уплату за благороднейший поступок." } } } } },
    [158] = { d = 15.4, v = "human-male", n = { x = 175 }, c = { x = { { 0.00, "Мне нужна бутылка особого напитка – сока зомби." }, { 3.53, "У хозяина темнолесской таверны \"Алый ворон\" Смиттса наверняка найдётся лишняя бутылочка." }, { 9.94, "Торопись." }, { 10.66, "Ночи стоят холодные, и мне не терпится снова наполнить жилы огнём." } } }, t = { d = 7.6, v = "human-male#50", n = { x = 76 }, c = { x = { { 0.00, "Значит, тебе нужен сок зомби?" }, { 2.37, "Хм... это довольно крепкий напиток, обычно его у меня не заказывают." } } } } },
    [159] = { d = 6.4, g = 1, v = "human-male#50", n = { m = 63, f = 63 }, c = { m = { { 0.00, "А вот и сок зомби…" }, { 1.51, "Будь с ним осторожен." }, { 3.24, "Он такой крепкий, что мёртвого поднимет!" } }, f = { { 0.00, "А вот и сок зомби…" }, { 1.49, "Будь с ним осторожна." }, { 3.20, "Он такой крепкий, что мёртвого поднимет!" } } }, t = { d = 10.6, v = "human-male", n = { x = 101 }, c = { x = { { 0.00, "Тысяча благодарностей." }, { 1.91, "Твоя глу... то есть твоя доброта согрела сердце старика!" }, { 6.74, "Вот, друг, прими это в знак моей благодарности." } } } } },
    [160] = { d = 15.1, g = 1, v = "human-male", n = { m = 152, f = 153 }, c = { m = { { 0.00, "Отнеси эту записку Элло Чернодреву, мэру Темнолесья." }, { 4.16, "Мы с ним старые друзья..." }, { 6.11, "И когда он прочитает это и узнает, что ты для меня сделал... не сомневаюсь, он будет счастлив не меньше меня!" }, { 14.51, "Ха-ха-ха!" } }, f = { { 0.00, "Отнеси эту записку Элло Чернодреву, мэру Темнолесья." }, { 4.10, "Мы с ним старые друзья..." }, { 6.02, "И когда он прочитает это и узнает, что ты для меня сделала... не сомневаюсь, он будет счастлив не меньше меня!" }, { 14.36, "Ха-ха-ха!" } } }, t = { d = 7.4, v = "human-male", n = { x = 73 }, c = { x = { { 0.00, "*Элло рассматривает письмо...*" }, { 2.40, "Что это за язык?" }, { 3.68, "Похоже, какой-то древний..." }, { 5.76, "Не могу его прочитать." } } } } },
    [161] = { d = 26.4, v = "dwarf-male", n = { x = 311 }, c = { x = { { 0.00, "Если мои подозрения верны, то это взрывчатый порошок." }, { 3.85, "Его следует показать специалистам, чтобы выяснить, с чем именно мы имеем дело." }, { 9.39, "Ашлана Камнехмыла направили в полк, охраняющий Дун Модр и мост Тандола." }, { 14.25, "Путь предстоит нелёгкий и опасный." }, { 16.58, "Пройди через врата Альгаза, по дороге, ведущей через Болотину, и отыщи Камнехмыла в Дун Модре." }, { 23.26, "Советую не сходить с дороги и не задерживаться." } } }, t = { d = 3.5, v = "dwarf-male", n = { x = 32 }, c = { x = { { 0.00, "Да, старина Плотина не зря беспокоится." } } } } },
    [162] = { d = 28.6, v = "goblin-male", n = { x = 332 }, c = { x = { { 0.00, "Прошу тебя, отнеси этот отчёт кому-нибудь, сведущему в такого рода вопросах." }, { 5.37, "Я слышал про одну ночную эльфийку по имени Грацина Сила Духа." }, { 9.74, "Она посвятила много времени изучению форм жизни, встречающихся лишь в Азероте; она и историк заодно!" }, { 16.73, "Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к ней." }, { 23.54, "Нам любая помощь не помешает." }, { 25.60, "Говорят, она сейчас в храме Луны в Дарнассе." } } }, t = { d = 32.7, v = "nightelf-female#52", n = { x = 356 }, c = { x = { { 0.00, "Что до твоего отчёта... мы, ночные эльфы, знаем, о каком ужасе идёт речь." }, { 5.39, "Рудознатец правильно поступил, отправив свой отчёт и тебя ко мне." }, { 10.17, "Эти существа мигом пожрут всю пустыню Танарис; они представляют собой одну из величайших опасностей, с которой только можно столкнуться." }, { 20.47, "Знакомься – это силитиды." }, { 22.43, "Так зовутся странные насекомые, которые служат величайшему злу, грозящему и Орде, и Альянсу." }, { 29.30, "Жаль, что нам не хватило ума понять это раньше." } } } } },
    [163] = { d = 21.3, v = "human-female#45", n = { x = 232 }, c = { x = { { 0.00, "Что-то неладно на Вороньем холме." }, { 2.47, "Калор клянётся, что он заметил кого-то – или что-то – в одном из домов." }, { 7.62, "Две ночи подряд он видел крадущиеся тени, а на третью – свет в одном из окон." }, { 13.22, "Если тебя и в самом деле беспокоит безопасность Темнолесья, выясни, что за чудовище скрывается на Вороньем холме." } } }, t = { d = 14.4, v = "human-male", n = { x = 132 }, c = { x = { { 0.00, "Нет!" }, { 0.38, "Прошу, не убивай меня!" }, { 2.33, "Это всего лишь я..." }, { 3.98, "Трясунчик!" }, { 4.88, "Они повсюду..." }, { 6.15, "Мне не скрыться!" }, { 7.50, "Чудовища на Вороньем холме?" }, { 9.83, "Н-н-нет... не может быть." }, { 11.85, "Всего лишь безвредный Трясунчик." } } } } },
    [164] = { d = 15.7, v = "human-female#45", n = { x = 172 }, c = { x = { { 0.00, "Ты знаешь Свена?" }, { 1.27, "Вот кто настоящий служитель Света!" }, { 3.81, "Он и его последователи стоят лагерем в северо-западной части Сумеречного леса." }, { 9.68, "Увы, их так мало, что некого отправить за припасами в город." }, { 14.16, "Не поможешь ли ты ему?" } } }, t = { d = 7.4, v = "human-male", n = { x = 83 }, c = { x = { { 0.00, "Припасы нам очень пригодятся." }, { 2.22, "Семья Кэрвинов не оставляет нас без помощи." }, { 5.44, "Вот, прими награду за труды." } } } } },
    [165] = { d = 16.0, v = "human-female#45", n = { x = 185 }, c = { x = { { 0.00, "Одно время в город частенько приходил старик и покупал припасы, но в последнее время я его не видела." }, { 7.16, "Он живёт в хижине рядом с кладбищем Вороньего холма, если я верно запомнила." }, { 12.50, "Не навестишь ли ты его?" }, { 14.13, "Вдруг с ним что-то случилось?" } } }, t = { d = 14.2, v = "human-male", n = { x = 139 }, c = { x = { { 0.00, "Илана Кэрвин?" }, { 1.14, "Хе-хе, да, разумеется, Кэрвин." }, { 3.56, "Нет, со мной всё в порядке, но мне трудновато ходить в город." }, { 8.26, "Дороги нынче опасные, а я не молодею." }, { 11.25, "Может, ты окажешь старику пару услуг?" } } } } },
    [166] = { d = 19.7, v = "human-male", n = { x = 234 }, c = { x = { { 0.00, "Осталось одно, последнее задание." }, { 2.40, "Эдвин ван Клиф должен умереть." }, { 4.55, "Хотя меня печалит сам факт вынесения человеку смертного приговора, для всего народа Западного Края будет гораздо лучше, если ван Клиф упокоится навечно." }, { 15.28, "Принесите мне голову этого негодяя, когда с ним будет покончено." } } }, t = { d = 19.8, g = 1, v = "human-male", n = { m = 227, f = 228 }, c = { m = { { 0.00, "Вы проявили удивительную храбрость." }, { 2.62, "Народное ополчение благодарит вас за службу народу Западного Края." }, { 7.60, "Смерть ван Клифа станет началом конца для Братства Справедливости." }, { 12.51, "Надеюсь, недалёк тот прекрасный день, когда мир вновь снизойдёт на эту честную землю." }, { 18.70, "Честь имею, сэр!" } }, f = { { 0.00, "Вы проявили удивительную храбрость." }, { 2.62, "Народное ополчение благодарит вас за службу народу Западного Края." }, { 7.58, "Смерть ван Клифа станет началом конца для Братства Справедливости." }, { 12.48, "Надеюсь, недалёк тот прекрасный день, когда мир вновь снизойдёт на эту честную землю." }, { 18.65, "Честь имею, леди!" } } } } },
    [167] = { d = 30.0, v = "dwarf-male", n = { x = 334 }, c = { x = { { 0.00, "Мы находились в обширных шахтах Западного Края, скрытых глубоко под землями Луноречья." }, { 6.28, "Понятия не имею, откуда явились эти мерзкие вороватые вонючки." }, { 10.92, "Так или иначе – туннель обрушился на нас." }, { 13.93, "Мне удалось выбраться, но остальные... о них я ничего не знаю." }, { 18.37, "Вдруг тебе повезёт больше, чем мне?" }, { 20.86, "Я ищу своего брата." }, { 22.36, "Он всегда носил значок Лиги Исследователей." }, { 25.57, "Если ты не найдёшь брата, постарайся найти хотя бы его значок." } } }, t = { d = 10.5, v = "dwarf-male", n = { x = 100 }, c = { x = { { 0.00, "Мои подозрения оправдались." }, { 2.41, "Бедный мой брат..." }, { 3.96, "Что ж, благодарю." }, { 5.44, "Определённость лучше загадок, даже если она лишает надежды." } } } } },
    [168] = { d = 18.6, v = "dwarf-male", n = { x = 224 }, c = { x = { { 0.00, "Многие из моих друзей погибли в тот роковой день, когда обрушился штрек." }, { 4.94, "Если тебя как-нибудь занесёт в ту шахту в Луноречье, пожалуйста, постарайся добыть что-то, что поможет их опознать." }, { 12.79, "А если найдёшь их карточки Союза шахтёров, принеси их мне, я отправлю их семьям погибших." } } }, t = { d = 10.2, v = "dwarf-male", n = { x = 111 }, c = { x = { { 0.00, "Спасибо тебе." }, { 1.12, "Твоя помощь в посмертном успокоении жертв этой чудовищной трагедии была неоценимой." }, { 7.64, "Их семьи будут тебе признательны." } } } } },
    [169] = { d = 32.5, v = "narrator", n = { x = 357 }, c = { x = { { 0.00, "Розыск!" }, { 0.63, "Гат'Илзогг, вождь клана Чёрной Горы, разыскивается за нападение на крепость Каменной Стражи и набеги на окрестности Приозёрья." }, { 10.27, "Гат'Илзогг крайне опасен." }, { 12.31, "По последним сведениям, он находится в недавно захваченной крепости и замышляет новые преступления против Королевства." }, { 21.45, "Нашествие орков должно быть остановлено любой ценой." }, { 25.60, "Храбрец, доставивший голову Гат'Илзогга мировому судье Соломону, будет щедро вознаграждён." } } }, t = { d = 13.8, v = "human-male", n = { x = 149 }, c = { x = { { 0.00, "Великолепная работа!" }, { 1.58, "Гат'Илзогг вёл своих громил в бой, и они убивали ни в чём не повинных людей." }, { 7.37, "Мы отомстили ему." }, { 8.74, "Это первый шаг на пути возвращения крепости королевству Штормграда!" } } } } },
    [170] = { d = 35.9, g = 1, v = "dwarf-male", n = { m = 392, f = 392 }, c = { m = { { 0.00, "Надеюсь, ты оказался здесь не случайно, герой." }, { 3.27, "Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес." }, { 9.37, "Я слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались." }, { 15.79, "Говорят, их полно в горах на юго-востоке и возле замёрзшего озера." }, { 20.53, "Так ведь и это ещё не всё!" }, { 22.33, "Недавно они напали на наш лагерь на западе и разгромили его!" }, { 26.70, "Нам и так воинов не хватает, а тут ещё эти гады..." }, { 30.22, "Послушай, приятель, может, ты нам поможешь?" }, { 33.30, "Боюсь, иначе нам троггов не одолеть..." } }, f = { { 0.00, "Надеюсь, ты оказалась здесь не случайно, героиня." }, { 3.41, "Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес." }, { 9.40, "Я слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались." }, { 15.71, "Говорят, их полно в горах на юго-востоке и возле замёрзшего озера." }, { 20.38, "Так ведь и это ещё не всё!" }, { 22.14, "Недавно они напали на наш лагерь на западе и разгромили его!" }, { 26.43, "Нам и так воинов не хватает, а тут ещё эти гады..." }, { 29.90, "Послушай, подруга, может, ты нам поможешь?" }, { 32.87, "Боюсь, иначе нам троггов не одолеть..." } } }, t = { d = 15.5, v = "dwarf-male", n = { x = 164 }, c = { x = { { 0.00, "Если повсюду происходит то же, что и здесь, у нас, то, клянусь бородой Магни, нас ждёт большая беда!" }, { 7.52, "Остаётся надеяться, что король и Совет придумают, что делать с этими проклятыми троггами, иначе нам конец." } } } } },
    [171] = { d = 27.0, g = 1, v = "child-male", n = { m = 285, f = 287 }, c = { m = { { 0.00, "Ты был очень добр ко мне." }, { 1.85, "Я и представить не мог, что Детская неделя пройдёт так весело." }, { 6.44, "Спасибо." }, { 7.12, "Я не хочу печалиться из-за собственной судьбы – предки всегда говорили мне, что я должен быть выше всех несчастий." }, { 15.75, "Знаешь, когда я вырасту, я хочу стать героем... как ты." }, { 19.93, "Как ни жаль, мне пора домой." }, { 22.05, "Давай вернёмся, и я расскажу нашей попечительнице, что ты лучше всех!" } }, f = { { 0.00, "Ты была очень добра ко мне." }, { 2.01, "Я и представить не мог, что Детская неделя пройдёт так весело." }, { 6.35, "Спасибо." }, { 7.00, "Я не хочу печалиться из-за собственной судьбы – предки всегда говорили мне, что я должен быть выше всех несчастий." }, { 15.16, "Знаешь, когда я вырасту, я хочу стать героем... как ты." }, { 19.12, "Как ни жаль, мне пора домой." }, { 21.12, "Давай вернёмся, и я расскажу нашей попечительнице, что ты лучше всех!" } } }, t = { d = 23.8, g = 1, v = "human-female", n = { m = 260, f = 261 }, c = { m = { { 0.00, "Да благословят тебя небеса." }, { 2.01, "Ты сделал для Рэндиса больше, чем сделали бы для него многие другие." }, { 6.95, "Спасибо тебе – ты яркая звезда на небосводе Альянса." }, { 10.78, "Прошу, если найдёшь время, навещай нас." }, { 13.64, "Я знаю, Рэндис будет рад, как и я." }, { 16.11, "Рэндису было с тобой так весело." }, { 18.51, "Он хочет подарить тебе одного из своих любимых питомцев – на память о нём." } }, f = { { 0.00, "Да благословят тебя небеса." }, { 1.95, "Ты сделала для Рэндиса больше, чем сделали бы для него многие другие." }, { 6.81, "Спасибо тебе – ты яркая звезда на небосводе Альянса." }, { 10.53, "Прошу, если найдёшь время, навещай нас." }, { 13.30, "Я знаю, Рэндис будет рад, как и я." }, { 15.70, "Рэндису было с тобой так весело." }, { 18.03, "Он хочет подарить тебе одного из своих любимых питомцев – на память о нём." } } } } },
    [172] = { d = 28.8, v = "orc-female#57", n = { x = 316 }, c = { x = { { 0.00, "Ты хочешь помочь сиротам?" }, { 1.93, "Да благословят тебя боги!" }, { 3.86, "Что бы мы без тебя делали!" }, { 5.79, "Вот, возьми этот свисток." }, { 7.72, "Действовать он будет недолго – до конца Детской недели." }, { 11.84, "Свистнув в него, ты сможешь поговорить с сиротой, за которым ты обещаешь присматривать." }, { 18.23, "Свистни ещё раз, и ты отпустишь ребёнка восвояси." }, { 21.76, "Прошу тебя, пользуйся свистком почаще, не забывай своего подопечного!" }, { 26.95, "Для детей это так важно..." } } }, t = { d = 24.7, g = 1, v = "child-male", n = { m = 288, f = 292 }, c = { m = { { 0.00, "Заг-заг!" }, { 0.62, "Меня зовут Грент." }, { 1.85, "Ты теперь мой опекун, да?" }, { 3.58, "Ты ищешь приключений, совсем как мои мама с папой!" }, { 7.11, "Наша попечительница говорит, что они с честью погибли в бою!" }, { 11.31, "Я так рад с тобой познакомиться!" }, { 13.47, "А мы теперь будем всё делать вместе?" }, { 16.01, "Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь всё равно как старший брат." }, { 23.92, "Вот здорово!" } }, f = { { 0.00, "Заг-заг!" }, { 0.61, "Меня зовут Грент." }, { 1.83, "Ты теперь моя опекунша, да?" }, { 3.73, "Ты ищешь приключений, совсем как мои мама с папой!" }, { 7.21, "Наша попечительница говорит, что они с честью погибли в бою!" }, { 11.36, "Я так рад с тобой познакомиться!" }, { 13.50, "А мы теперь будем всё делать вместе?" }, { 16.00, "Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь всё равно как старшая сестра." }, { 24.01, "Вот здорово!" } } } } },
    [173] = { d = 32.6, g = 1, v = "human-male", n = { m = 377, f = 378 }, c = { m = { { 0.00, "На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом." }, { 5.77, "Благодаря нашим усилиям народ Темнолесья живёт в безопасности." }, { 10.15, "Ты считаешь, что достоин вступить в наши ряды?" }, { 13.44, "Когда-то я был таким же, как ты." }, { 15.66, "Меня раздражало самодовольство Дозора, и я стал соратником мастера Кэрвина." }, { 20.93, "Если ты хочешь показать, на что способен, то слова тебе не помощники." }, { 25.81, "Выступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду." } }, f = { { 0.00, "На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом." }, { 5.75, "Благодаря нашим усилиям народ Темнолесья живёт в безопасности." }, { 10.10, "Ты считаешь, что достойна вступить в наши ряды?" }, { 13.45, "Когда-то я был таким же, как ты." }, { 15.66, "Меня раздражало самодовольство Дозора, и я стал соратником мастера Кэрвина." }, { 20.90, "Если ты хочешь показать, на что способна, то слова тебе не помощники." }, { 25.76, "Выступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду." } } }, t = { d = 22.2, g = 1, v = "human-male", n = { m = 249, f = 249 }, c = { m = { { 0.00, "Твои успехи впечатляют." }, { 1.78, "Похоже, ты на многое способен." }, { 4.01, "Пожалуй, твоим талантам следует найти более достойное применение." }, { 8.88, "Впрочем, вот что интересно..." }, { 10.99, "Воргены появились словно из ниоткуда." }, { 13.75, "Но, с другой стороны, в наши границы вторглось такое количество странных существ, что это не самая большая проблема." } }, f = { { 0.00, "Твои успехи впечатляют." }, { 1.75, "Похоже, ты на многое способна." }, { 3.96, "Пожалуй, твоим талантам следует найти более достойное применение." }, { 8.76, "Впрочем, вот что интересно..." }, { 10.83, "Воргены появились словно из ниоткуда." }, { 13.55, "Но, с другой стороны, в наши границы вторглось такое количество странных существ, что это не самая большая проблема." } } } } },
    [174] = { d = 20.2, v = "human-male", n = { x = 245 }, c = { x = { { 0.00, "Один мой друг, гном по имени Ког, обещал мне помочь создать устройство, которое позволит изучать звёзды." }, { 7.10, "Уверен, что есть и иные объяснения творящемуся в лесу, чем магическое вмешательство." }, { 12.83, "Принеси мне бронзовую трубку, изготовленную искусным инженером." }, { 17.19, "Согласно чертежам Кога, это шаг номер один." } } }, t = { d = 3.8, v = "human-male", n = { x = 36 }, c = { x = { { 0.00, "Великолепно!" }, { 1.14, "Первый шаг мы сделали успешно!" } } } } },
    [175] = { d = 20.0, v = "human-male", n = { x = 230 }, c = { x = { { 0.00, "Согласно чертежам Кога, мне нужно отыскать способ отражать свет." }, { 4.58, "Помнится, есть у нас одна особа по имени Мэри, которая вечно таскает с собой зеркальце." }, { 10.80, "Может быть, ты отыщешь её и она одолжит нам свою отражающую поверхность?" }, { 15.89, "Кажется, она когда-то жила в южной части Сумеречного леса." } } }, t = { d = 4.2, v = "creature/banshee", n = { x = 33 }, c = { x = { { 0.00, "Всё верно, у меня некогда было зеркальце." } } } } },
    [176] = { d = 24.3, v = "narrator", n = { x = 266 }, c = { x = { { 0.00, "Разыскивается: Дробитель" }, { 1.90, "В юго-западной части Элвиннского леса поселился могучий гнолл по прозванию Дробитель." }, { 8.60, "Несмотря на все усилия, поймать его так и не удалось." }, { 12.76, "Армия Штормграда назначила за этого гнолла щедрую награду." }, { 17.42, "Чтобы получить её, необходимо представить маршалу Дугхану доказательства смерти Дробителя." } } }, t = { d = 13.1, v = "human-male", n = { x = 139 }, c = { x = { { 0.00, "Ха!" }, { 0.27, "Отличная работа!" }, { 1.53, "А я уже было думал, что никому не под силу совладать с этим чудовищем!" }, { 6.80, "Вот твоя награда, а с ней прими и мою благодарность: этот гнолл у нас уже вот где сидел!" } } } } },
    [177] = { d = 27.4, v = "creature/banshee", n = { x = 223 }, c = { x = { { 0.00, "Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье." }, { 8.78, "После этого я зашвырнула стекляшку за амбар." }, { 13.35, "Одно время там бродил Невменяемый Вурдалак." }, { 17.84, "Может быть, он утащил моё зеркальце." }, { 21.49, "Говорят, что теперь эта тварь живёт на Безмятежном кладбище." } } }, t = { d = 5.5, v = "human-male", n = { x = 52 }, c = { x = { { 0.00, "Шедеврально!" }, { 1.17, "Это непременно сработает." }, { 3.59, "Я глубоко признателен!" } } } } },
    [178] = { d = 29.2, v = "human-male", n = { x = 319 }, c = { x = { { 0.00, "*До вас доносится бесплотный голос...*" }, { 3.20, "Не пугайся." }, { 4.06, "Я Теокрит, верховный маг башни Азоры в Элвиннском лесу." }, { 8.19, "При помощи этой подвески гноллы из стаи Темношкуров общаются со своим повелителем Моргантом." }, { 15.04, "Я потратил много времени на то, чтобы тоже научиться вещать через эти подвески." }, { 21.03, "Если ты слышишь моё сообщение, значит заклинание сработало." }, { 25.42, "Принеси мне эту подвеску, и я щедро вознагражу тебя." } } }, t = { d = 25.7, v = "human-male", n = { x = 323 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.07, "Я передал это сообщение через подвески Темношкуров несколько недель назад и полагал, что заклинание не сработало." }, { 8.57, "Оказывается, в конечном итоге оно достигло по меньшей мере некоторых из них." }, { 13.62, "Хочется верить, что рано или поздно я научусь посылать таким образом боевые заклинания и обездвиживать тех гноллов, которые носят эти подвески." }, { 23.20, "К сожалению, до этого ещё очень далеко." } } } } },
    [179] = { d = 33.7, v = "dwarf-male", n = { x = 330 }, c = { x = { { 0.00, "Ну-ка, ну-ка, что тут у нас?.." }, { 2.32, "Холодновато в наших краях, верно?" }, { 4.98, "Готов спорить, у тебя всё время мёрзнут руки." }, { 8.56, "Ну, угадал?" }, { 9.48, "Я скажу, что тебе нужно: пара хороших тёплых перчаток." }, { 13.76, "Ну да, душа у меня добрая, так что замёрзнуть я тебе не дам." }, { 18.32, "Только вот есть одно условие." }, { 20.64, "Принеси мне волчьего мяса – и мы, считай, в расчёте." }, { 24.64, "Справедливо, как думаешь?" }, { 26.60, "Мне – мясо, а уж я-то позабочусь о том, чтобы у тебя пальцы больше не мёрзли." }, { 32.57, "Ну, что скажешь?" } } }, t = { d = 11.3, v = "dwarf-male", n = { x = 106 }, c = { x = { { 0.00, "О!" }, { 0.22, "Прекрасно!" }, { 1.11, "Волчье мясо – это то, что надо!.." }, { 3.91, "Не беспокойся, свою часть сделки я выполню честно." }, { 8.04, "Вот, посмотри, что из этого тебе подойдёт." } } } } },
    [180] = { d = 23.0, v = "narrator", n = { x = 264 }, c = { x = { { 0.00, "Разыскивается: лейтенант Фангор" }, { 2.38, "Глава гнолльской стаи Темношкуров, соратник Морганта, врага Города и Королевства." }, { 8.56, "По приказу чиновника Соломона подлый предатель Штормграда приговаривается к смерти." }, { 14.82, "Тот, кто приведёт приговор в исполнение, должен в доказательство принести лапу Фангора мировому судье Соломону." } } }, t = { d = 10.2, g = 1, v = "human-male", n = { m = 107, f = 107 }, c = { m = { { 0.00, "Значит, злобный лейтенант Фангор мёртв?" }, { 3.09, "Прекрасно." }, { 3.93, "Ты удивительно храбрый герой." }, { 6.24, "Городской совет Приозёрья благодарит тебя за помощь." } }, f = { { 0.00, "Значит, злобный лейтенант Фангор мёртв?" }, { 2.97, "Прекрасно." }, { 3.78, "Ты удивительно храбрая героиня." }, { 6.15, "Городской совет Приозёрья благодарит тебя за помощь." } } } } },
    [181] = { d = 21.9, v = "human-male", n = { x = 245 }, c = { x = { { 0.00, "Для завершения работы не хватает только одного предмета." }, { 4.16, "Согласно чертежам Кога, нам нужна линза." }, { 7.20, "Единственную подходящую линзу в наших краях будет нелегко достать." }, { 12.16, "В кургане на юге Сумеречного леса живёт огр по имени Ззарк'Вул." }, { 16.78, "Если сможешь, принеси мне его монокль, и я использую его вместо линзы!" } } }, t = { d = 7.4, v = "human-male", n = { x = 79 }, c = { x = { { 0.00, "Наконец-то!" }, { 0.92, "Устройство для изучения звёзд готово!" }, { 3.83, "Спасибо тебе." }, { 4.97, "Я могу продолжить исследования..." } } } } },
    [182] = { d = 31.2, v = "dwarf-male", n = { x = 383 }, c = { x = { { 0.00, "Нас с моим братом Сениром отправили в Дун Морог, чтобы разведать, действительно ли там объявились тролли, и насколько серьёзна эта угроза." }, { 9.06, "Совету хватает хлопот с троггами, лишние проблемы им ни к чему." }, { 13.29, "Насколько я видел, тролли здесь не слишком хорошо закрепились; в основном они живут в южной пещере." }, { 19.90, "Как по мне, тут и армия не нужна: несколько крепких бойцов вполне управятся." }, { 24.90, "Может, и ты решишь поучаствовать в этом деле?" }, { 27.94, "Не за так, конечно: у меня есть что тебе предложить." } } }, t = { d = 13.9, v = "dwarf-male", n = { x = 163 }, c = { x = { { 0.00, "Проклятые тролли!" }, { 1.39, "Да не озарит их Извечный Свет!" }, { 3.67, "Эти негодяи ввалились ко мне ночью и украли мои записи!" }, { 9.36, "У меня хватило ума не доверять этому негодному подмастерь..." } } } } },
    [183] = { d = 27.3, v = "dwarf-male", n = { x = 313 }, c = { x = { { 0.00, "Нет ничего лучше охоты на диких вепрей, верно?" }, { 3.31, "Правда, здесь, в Холодной долине, их расплодилось столько, что весь интерес пропадает." }, { 9.18, "Их и загонять не надо – они злые, как демоны, и сами бросаются прямо на охотника." }, { 14.87, "Я бы даже сказал, что этих злобных свиней так много, что и охотиться-то стало опасно..." }, { 20.93, "Короче говоря, я буду благодарен, если ты поможешь мне прикончить хотя бы нескольких кабанов." } } }, t = { d = 9.7, v = "dwarf-male", n = { x = 77 }, c = { x = { { 0.00, "Отлично, просто отлично!" }, { 2.44, "Теперь я могу спокойно отдох..." }, { 5.58, "М-м..." }, { 6.19, "Заняться охотой." }, { 7.84, "Благодарю за помощь." } } } } },
    [184] = { d = 36.6, v = "narrator", n = { x = 408 }, c = { x = { { 0.00, "Вот бумага, дающая право на расширение фермерских владений в Западном Крае." }, { 5.60, "Она подписана Теодором Хмуробровом и его женой, Верной Хмуробров." }, { 10.53, "На обороте документа торопливо нацарапаны слова:" }, { 14.13, "\"Мы нажали на Хмуроброва и получили от него нужную бумагу." }, { 18.46, "Если тебе захочется заполучить один из участков, она тебе пригодится." }, { 23.72, "С Хмуробровами проблем не предвидится: я видел, как они покидают Западный Край, у них как раз телега сломалась.\"" }, { 31.86, "Наверное, Хмуробровы были бы рады получить этот документ назад..." } } }, t = { d = 19.0, v = "human-male", n = { x = 219 }, c = { x = { { 0.00, "Ты представить не можешь, как мы тебе благодарны!" }, { 3.39, "Конечно, сейчас в этих краях приличным людям не место, но, может, времена переменятся, и тогда нам нужно будет предъявить эту бумагу на право владения землёй." }, { 14.48, "Конечно, многого я предложить не могу, но возьми хотя бы вот это..." } } } } },
    [185] = { d = 17.1, v = "human-female#47", n = { x = 212 }, c = { x = { { 0.00, "Когда я была маленькой девочкой, отец научил меня искусству охоты на тигров." }, { 5.31, "Молодых зверей гораздо проще выслеживать и убивать." }, { 8.84, "Поэтому начнём с простого." }, { 10.61, "Молодые тигры часто забредают к лагерю экспедиции." }, { 14.09, "Постарайся выследить и убить несколько зверей." } } }, t = { d = 2.9, v = "human-female#47", n = { x = 30 }, c = { x = { { 0.00, "Неплохо." }, { 0.72, "Пора тебе двигаться дальше." } } } } },
    [186] = { d = 9.8, g = 1, v = "human-female#47", n = { x = 105 }, c = { m = { { 0.00, "А ты учишься, герой." }, { 1.54, "Посмотрим, как ты справишься со взрослыми кошками." }, { 5.23, "На сей раз тебе предстоит убить десять тигров Тернистой долины." } }, f = { { 0.00, "А ты учишься, героиня." }, { 1.65, "Посмотрим, как ты справишься со взрослыми кошками." }, { 5.29, "На сей раз тебе предстоит убить десять тигров Тернистой долины." } } }, t = { d = 3.4, g = 1, v = "human-female#47", n = { x = 26 }, c = { m = { { 0.00, "Впечатляюще, герой." }, { 1.76, "Ты делаешь успехи." } }, f = { { 0.00, "Впечатляюще, героиня." }, { 1.83, "Ты делаешь успехи." } } } } },
    [187] = { d = 21.1, g = 1, v = "human-female#47", n = { m = 257, f = 258 }, c = { m = { { 0.00, "Поднимем ставки." }, { 1.17, "Докажи, что сможешь убить десять старых тигров Тернистой долины." }, { 5.69, "Справишься – и я признаю, что ты готов к последнему испытанию, после которого я объявлю тебя великим охотником на тигров в присутствии мастера Эрнестуэя." }, { 16.13, "Старые тигры Тернистой долины неуловимы для врага и безжалостны в схватке." } }, f = { { 0.00, "Поднимем ставки." }, { 1.15, "Докажи, что сможешь убить десять старых тигров Тернистой долины." }, { 5.58, "Справишься – и я признаю, что ты готова к последнему испытанию, после которого я объявлю тебя великим охотником на тигров в присутствии мастера Эрнестуэя." }, { 15.90, "Старые тигры Тернистой долины неуловимы для врага и безжалостны в схватке." } } }, t = { d = 4.3, g = 1, v = "human-female#47", n = { m = 34, f = 35 }, c = { m = { { 0.00, "Очень, очень неплохо." }, { 2.20, "Думаю, ты почти готов." } }, f = { { 0.00, "Очень, очень неплохо." }, { 2.16, "Думаю, ты почти готова." } } } } },
    [188] = { d = 20.6, g = 1, v = "human-female#47", n = { m = 232, f = 231 }, c = { m = { { 0.00, "Вот твоё последнее испытание." }, { 2.05, "Мы уже много недель выслеживаем эту хитрую тигрицу, прозванную Син'Далл." }, { 7.31, "Интересно, сможешь ли ты сделать то, что не удавалось ни одному герою – выследить и убить Син'Далл." }, { 14.29, "Принеси мне её лапу в доказательство своего подвига." }, { 18.01, "Даже выследить её – непростая задача." } }, f = { { 0.00, "Вот твоё последнее испытание." }, { 2.04, "Мы уже много недель выслеживаем эту хитрую тигрицу, прозванную Син'Далл." }, { 7.28, "Интересно, сможешь ли ты сделать то, что не удавалось ни одной героине – выследить и убить Син'Далл." }, { 14.31, "Принеси мне её лапу в доказательство своего подвига." }, { 18.02, "Даже выследить её – непростая задача." } } }, t = { d = 5.0, v = "human-female#47", n = { x = 48 }, c = { x = { { 0.00, "Впечатляюще, должна сказать!" }, { 2.52, "Ты великий Охотник на тигров!" } } } } },
    [189] = { d = 33.2, v = "goblin-male", n = { x = 354 }, c = { x = { { 0.00, "Проклятые тролли!" }, { 1.34, "Они постоянно убивают наших агентов!" }, { 4.17, "Я потерял в стычках с ними лучших своих бойцов." }, { 7.80, "Цена операции всё растёт и растёт!" }, { 10.29, "Как я объясню это барону Ревилгазу?" }, { 12.98, "Решительные действия нас спасут..." }, { 15.53, "Думай, Кебок..." }, { 16.74, "Тебя назначили на эту должность не за безделье..." }, { 20.44, "Придумал!" }, { 21.18, "Ты... как тебя там?" }, { 22.59, "Ты ведь мне поможешь?" }, { 24.14, "А уж я заплачу!" }, { 25.28, "Предлагаю сделку... ты принесёшь мне уши пятнадцати троллей из племени Кровавого Скальпа, а я дам тебе денег." } } }, t = { d = 17.4, v = "goblin-male", n = { x = 162 }, c = { x = { { 0.00, "Отлично, отлично." }, { 1.78, "Это временно решит проблему…" }, { 4.64, "*Он принимается бормотать себе что-то под нос насчёт огромных издержек…*" }, { 9.84, "Что?" }, { 10.23, "Ты всё ещё здесь?" }, { 11.64, "Награда?" }, { 12.43, "А, да..." }, { 13.13, "Разумеется, бери... этого должно с лихвой хватить." } } } } },
    [190] = { d = 15.0, v = "human-male", n = { x = 179 }, c = { x = { { 0.00, "Если ты хочешь отправиться на охоту вместе с нами под предводительством Хеминга, докажи, что умеешь выслеживать пантер." }, { 8.17, "Не бойся, начнём с простого." }, { 10.09, "Для примера убей десять молодых пантер." }, { 12.87, "Выследить их – только полдела..." } } }, t = { d = 1.4, v = "human-male", n = { x = 12 }, c = { x = { { 0.00, "Доброе начало!" } } } } },
    [191] = { d = 15.9, g = 1, v = "human-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "А теперь задача потруднее." }, { 1.81, "Если ты хочешь доказать, что достоин общаться с настоящими охотниками, убей десять пантер." }, { 7.90, "С этими ребятами не так легко справиться, они посильнее молодых зверей, с которыми тебе приходилось сталкиваться прежде." } }, f = { { 0.00, "А теперь задача потруднее." }, { 1.81, "Если ты хочешь доказать, что достойна общаться с настоящими охотниками, убей десять пантер." }, { 7.97, "С этими ребятами не так легко справиться, они посильнее молодых зверей, с которыми тебе приходилось сталкиваться прежде." } } }, t = { d = 1.4, v = "human-male", n = { x = 11 }, c = { x = { { 0.00, "Великолепно!" } } } } },
    [192] = { d = 17.1, v = "human-male", n = { x = 201 }, c = { x = { { 0.00, "Усложняем задание." }, { 1.33, "Настоящий охотник сможет одолеть даже тенебрюхих пантер, самых опасных в Тернистой долине." }, { 7.81, "Докажи, что сможешь прикончить десять таких тварей." }, { 11.49, "Если тебе покажется, что их трудно выслеживать, попробуй для начала убить одну..." } } }, t = { d = 1.3, v = "human-male", n = { x = 7 }, c = { x = { { 0.00, "Молодец!" } } } } },
    [193] = { d = 12.7, g = 1, v = "human-male", n = { m = 128, f = 129 }, c = { m = { { 0.00, "Тебе почти удалось доказать, что ты великий охотник на пантер." }, { 4.80, "И всё же остаётся одна пантера по имени Баг'тира." }, { 8.50, "Добудь её клык, и моё уважение тебе обеспечено!" } }, f = { { 0.00, "Тебе почти удалось доказать, что ты великая охотница на пантер." }, { 5.16, "И всё же остаётся одна пантера по имени Баг'тира." }, { 9.09, "Добудь её клык, и моё уважение тебе обеспечено!" } } }, t = { d = 6.6, g = 1, v = "human-male", n = { m = 45, f = 45 }, c = { m = { { 0.00, "Итак, великая Баг'тира мертва!" }, { 3.23, "Браво." }, { 3.97, "Ты и правда могучий герой!" } }, f = { { 0.00, "Итак, великая Баг'тира мертва!" }, { 3.18, "Браво." }, { 3.90, "Ты и правда могучая героиня!" } } } } },
    [194] = { d = 17.6, g = 1, v = "dwarf-male", n = { m = 194, f = 194 }, c = { m = { { 0.00, "Значит, ты считаешь себя превосходным охотником?" }, { 3.47, "Проверим." }, { 4.18, "Ступай в джунгли и подстрели десять ящеров Тернистой долины." }, { 8.55, "Посмотрим, как ты справишься с крупной дичью." }, { 11.77, "И нет, я не скажу, где их искать!" }, { 14.08, "Первая половина испытания – поиски зверя." } }, f = { { 0.00, "Значит, ты считаешь себя превосходной охотницей?" }, { 3.60, "Проверим." }, { 4.34, "Ступай в джунгли и подстрели десять ящеров Тернистой долины." }, { 8.87, "Посмотрим, как ты справишься с крупной дичью." }, { 12.21, "И нет, я не скажу, где их искать!" }, { 14.61, "Первая половина испытания – поиски зверя." } } }, t = { d = 1.9, v = "dwarf-male", n = { x = 14 }, c = { x = { { 0.00, "Неплохо, старина!" } } } } },
    [195] = { d = 12.6, v = "dwarf-male", n = { x = 131 }, c = { x = { { 0.00, "А теперь я задам тебе задачку, посмотрим, придётся ли она тебе по вкусу." }, { 5.72, "Отправляйся в джунгли и добудь десять ящеров-кнутохвостов." }, { 10.32, "Увидим, хватит ли тебе пороху!" } } }, t = { d = 5.0, v = "dwarf-male", n = { x = 49 }, c = { x = { { 0.00, "Именно так и появляются трофеи над камином!" }, { 3.72, "Неплохая охота!" } } } } },
    [196] = { d = 20.9, v = "dwarf-male", n = { x = 234 }, c = { x = { { 0.00, "Посмотрим, как ты справишься со следующим испытанием." }, { 3.87, "Здесь живут хитрые ящеры, мы зовём их тропическими ловцами." }, { 8.21, "Их гораздо труднее выследить и убить, чем другие виды, с которыми тебе пришлось столкнуться." }, { 15.09, "Убей десять тропических ловцов, и я подскажу тебе, где ждёт самая лучшая охота." } } }, t = { d = 6.1, v = "dwarf-male", n = { x = 47 }, c = { x = { { 0.00, "Хо-хо!!!" }, { 0.91, "У нас есть настоящий убийца ящеров!" }, { 4.44, "Неплохо, старина!" } } } } },
    [197] = { d = 21.8, v = "dwarf-male", n = { x = 234 }, c = { x = { { 0.00, "Ну, раз ты ходишь в джунгли как к себе домой, дай-ка я расскажу тебе о свирепом ящере, которого даже мне не удалось убить." }, { 9.11, "Ажек называет этого хитрого ящера Тетис." }, { 12.26, "Если ты хочешь показать подлинное мастерство, убей Тетис и принеси мне его коготь." }, { 18.49, "Этот подвиг не удался ещё ни одному охотнику!" } } }, t = { d = 5.0, g = 1, v = "dwarf-male", n = { m = 33, f = 33 }, c = { m = { { 0.00, "Великий путник, убийца ящеров!" }, { 3.05, "Неплохо звучит, а?" } }, f = { { 0.00, "Великая путница, убийца ящеров!" }, { 3.29, "Неплохо звучит, а?" } } } } },
    [198] = { d = 37.8, v = "goblin-male", n = { x = 446 }, c = { x = { { 0.00, "Хммм." }, { 0.37, "У меня и правда есть для тебя дело." }, { 2.85, "Лейтенант Дорен и его последователи там, на севере, регулярно получают от нас поставки еды и оборудования." }, { 10.11, "Пришло время доставить очередную партию, а, учитывая нападения троллей, никто не хочет за это браться." }, { 17.25, "Лагерь Дорена располагается на северо-западе от дороги у входа в Тернистую долину из Сумеречного леса." }, { 24.32, "Отнеси эту посылку рядовому Торсену, а если его нет в лагере, значит, он дежурит на юге от него." }, { 31.08, "Он займётся этими припасами." }, { 33.00, "Учти, если ты провалишь задание, придётся тебе возместить мои затраты." } } }, t = { d = 13.8, v = "human-male", n = { x = 151 }, c = { x = { { 0.00, "Эти мины помогут нам защититься от этого зверя, Курцена, и его людей." }, { 5.09, "Спасибо за доставку." }, { 6.57, "Если тебе нужна работа, может быть, я смогу помочь тебе." }, { 10.76, "И тебе не придётся иметь дело с гоблинами, а?" } } } } },
    [199] = { d = 4.0, v = "narrator", n = { x = 38 }, c = { x = { { 0.00, "Вы берёте образец странно пахнущего порошка." } } }, t = { d = 3.4, v = "dwarf-male", n = { x = 30 }, c = { x = { { 0.00, "Это тревожная находка, мягко говоря!" } } } } },
    [200] = { d = 33.4, v = "human-male", n = { x = 399 }, c = { x = { { 0.00, "Если Курцену известна тайна Торсена, значит, в наши ряды затесался шпион." }, { 5.20, "Необходимо выяснить, откуда просочилась информация!" }, { 8.73, "Связным Торсена в лагере Курцена был букмекер Герод." }, { 12.39, "Герод работает снабженцем у Курцена, и знает всё о его лагере." }, { 16.72, "Если удастся добыть его записи, быть может, мы узнаем, как накрыли Торсена." }, { 21.98, "Когда мы служили в войсках Курцена, кабинет букмекера располагался на верхнем этаже единственного двухэтажного дома в лагере." }, { 30.59, "Скорее всего, его записи по-прежнему там." } } }, t = { d = 9.9, v = "narrator", n = { x = 102 }, c = { x = { { 0.00, "Вы находите записи букмекера Герода." }, { 3.01, "Среди них: список поставок в лагерь, запросы от полковника Курцена и различные письма." } } } } },
    [201] = { d = 29.0, v = "goblin-male", n = { x = 327 }, c = { x = { { 0.00, "Мне сообщили о группе охотников, разбивших лагерь вверх по реке от рудника Торговой компании возле озера Назферити." }, { 8.32, "Я бы не придал этому значения, но говорят, будто один из тамошних охотников – сам Хеминг Эрнестуэй." }, { 15.46, "Мне не верится, но у него настолько высокие связи, если ты понимаешь о чём я, что лучше заранее обезопасить себя." }, { 23.58, "Почему бы тебе не заглянуть в этот лагерь и не разузнать, что они замышляют?" } } }, t = { d = 14.0, v = "goblin-male", n = { x = 133 }, c = { x = { { 0.00, "Хмм, значит у меня были точные сведения, как обычно." }, { 4.49, "Любопытно." }, { 5.40, "Кажется, они не представляют для нас опасности, но быть может, им нужны наши превосходные товары." }, { 13.55, "Хммм..." } } } } },
    [202] = { d = 27.3, g = 1, v = "human-male", n = { m = 314, f = 315 }, c = { m = { { 0.00, "И снова ты показал нам, на что способен." }, { 2.73, "Кажется, талантов у тебя не меньше, чем у самого Курцена!" }, { 6.71, "Это может спасти нас, горстку повстанцев... если ты сможешь выступить против Курцена и одержать над ним верх!" }, { 14.23, "Он управляет своими людьми из глубин Схрона." }, { 17.33, "Ступай в эту пещеру, пробейся сквозь ряды её защитников, и одолей Курцена и его ближайших приспешников." }, { 24.48, "Прощай." }, { 25.03, "Ты – наша последняя надежда." } }, f = { { 0.00, "И снова ты показала нам, на что способна." }, { 2.83, "Кажется, талантов у тебя не меньше, чем у самого Курцена!" }, { 6.86, "Это может спасти нас, горстку повстанцев... если ты сможешь выступить против Курцена и одержать над ним верх!" }, { 14.47, "Он управляет своими людьми из глубин Схрона." }, { 17.61, "Ступай в эту пещеру, пробейся сквозь ряды её защитников, и одолей Курцена и его ближайших приспешников." }, { 24.84, "Прощай." }, { 25.41, "Ты – наша последняя надежда." } } }, t = { d = 20.2, g = 1, v = "human-male", n = { m = 215, f = 217 }, c = { m = { { 0.00, "Я не смел верить вестям, но ты несёшь нам доказательство того, что..." }, { 5.03, "Курцен и его главные сторонники повержены." }, { 8.30, "Ты спас нас всех!" }, { 9.52, "Джунгли полны различных угроз, но никто не мог сравниться с жестоким и умным Курценом." }, { 16.05, "Теперь, когда его нет, мы можем вздохнуть спокойнее." } }, f = { { 0.00, "Я не смел верить вестям, но ты несёшь нам доказательство того, что..." }, { 5.06, "Курцен и его главные сторонники повержены." }, { 8.35, "Ты спасла нас всех!" }, { 9.78, "Джунгли полны различных угроз, но никто не мог сравниться с жестоким и умным Курценом." }, { 16.35, "Теперь, когда его нет, мы можем вздохнуть спокойнее." } } } } },
    [203] = { d = 19.0, v = "human-female#47", n = { x = 244 }, c = { x = { { 0.00, "Мы решительно проигрываем полковнику Курцену." }, { 2.93, "Он не только блестящий тактик – его войска превосходят нас в численности в десять раз!" }, { 8.50, "Чтобы выжить, нам придётся прибегнуть к его же подлой тактике." }, { 12.55, "Проберись в лагерь на востоке и убей как можно больше его бойцов." }, { 16.89, "И скройся до прибытия подкрепления." } } }, t = { d = 11.0, v = "human-female#47", n = { x = 122 }, c = { x = { { 0.00, "Отлично." }, { 0.66, "Потеря опытных бойцов вынудит его ослабить натиск на наш лагерь." }, { 5.46, "А ты не боишься быть на нашей стороне, зная, какие силы выступают против нас??" } } } } },
    [204] = { d = 26.3, v = "human-female#47", n = { x = 343 }, c = { x = { { 0.00, "Чтобы получить шанс выстоять против Курцена, нам необходимо лишить его лекарей." }, { 5.12, "Он собрал немало целителей, которые лечат его войска зельями из джунглей и травят наших бойцов экстрактами ядовитого папоротника." }, { 13.46, "Нам и самим нужны эти составы, чтобы изучить их и создать свои собственные." }, { 18.35, "Обыщи посёлок Курцена – лекарства находятся у его целителей и партизан, а экстракты скорее всего хранятся в ящиках с припасами." } } }, t = { d = 8.3, v = "human-female#47", n = { x = 107 }, c = { x = { { 0.00, "Молодец." }, { 0.61, "Эти лекарства помогут нам выжить и сохранить боеспособность." }, { 4.69, "А при помощи экстракта мы создадим собственные снадобья." } } } } },
    [205] = { d = 15.2, v = "human-male", n = { x = 191 }, c = { x = { { 0.00, "Пока я изучаю принесённые тобой прорисовки, собери для меня принадлежности злой магии троллей." }, { 6.33, "Тебе придётся проникнуть в земли племени Дробителей Черепов, второго племени на далёком юге, и добыть фетиши у их знахарей и мистиков." } } }, t = { d = 7.3, v = "human-male", n = { x = 67 }, c = { x = { { 0.00, "Спасибо." }, { 0.77, "Я изучу эти фетиши и пойму, они ли причина того, что Курцен обратился ко злу." } } } } },
    [206] = { d = 32.1, v = "human-male", n = { x = 350 }, c = { x = { { 0.00, "Хотя Курцен и мёртв, зло, соблазнившее его, живёт!" }, { 3.66, "Вот что мне удалось выяснить: огрский маг – Май'Зот – живёт в огрском кургане в восточных горах Тернистой долины." }, { 11.92, "Говорят, что он пользуется магией, овладевающей разумом, и я не сомневаюсь, что Май'Зот виноват в падении Курцена." }, { 20.24, "Пока он жив, зло будет расползаться, и может даже появиться второй Курцен." }, { 25.77, "Убей его и принеси мне его Око Разума, артефакт, позволяющий ему творить тёмные дела." } } }, t = { d = 16.5, v = "human-male", n = { x = 174 }, c = { x = { { 0.00, "Ага!" }, { 0.41, "Тебе удалось убить его!" }, { 2.32, "На стороне добра действуют великие силы!" }, { 5.45, "Да не ослабеет твоя рука!" }, { 7.43, "Я исследую Око Разума и попытаюсь придумать, как пользоваться им во благо." }, { 13.02, "Если это невозможно... его следует уничтожить." } } } } },
    [207] = { d = 34.5, v = "human-male", n = { x = 416 }, c = { x = { { 0.00, "Когда-то полковник Курцен был великим и благородным человеком – я хочу выяснить, что заставило его свернуть с пути истинного!" }, { 8.53, "Должно быть, он находится под воздействием магии троллей." }, { 12.40, "Надо изучить древние легенды, чтобы убедиться в этом." }, { 16.14, "В руинах тролльских городов в Тернистой долине спрятаны четыре таблички." }, { 21.12, "Мне необходимо их добыть и прочесть!" }, { 23.57, "Перерисуй с них все отметки и принеси рисунки мне." }, { 26.95, "Первая табличка находится в Руинах Бал'лал, вторая – на Коварном рифе, а третья и четвёртая – в Руинах Зул'Кунды." } } }, t = { d = 9.0, v = "human-male", n = { x = 97 }, c = { x = { { 0.00, "Спасибо." }, { 0.70, "Я изучу твои рисунки и попытаюсь выяснить, есть ли связь между троллями и злом, одолевшим полковника Курцена." } } } } },
    [208] = { d = 32.3, g = 1, v = "dwarf-male", n = { m = 349, f = 350 }, c = { m = { { 0.00, "Ты достоин занять место среди нас." }, { 2.60, "И на полях битвы в Лордероне, и в глубоких джунглях, мне редко приходилось видеть столь умелое обращение с оружием." }, { 11.06, "Тебе удалось убить свирепую Син'Далл, неуловимую Баг'тиру и коварного Тетиса." }, { 16.52, "Осталось одно – добыть голову короля Бангалаша." }, { 20.74, "Давненько я точу зуб на этого белого тигра и оказался здесь именно ради него." }, { 26.53, "Убей короля Бангалаша, и мы признаем, что тебе нет равных в искусстве охоты." } }, f = { { 0.00, "Ты достойна занять место среди нас." }, { 2.64, "И на полях битвы в Лордероне, и в глубоких джунглях, мне редко приходилось видеть столь умелое обращение с оружием." }, { 11.02, "Тебе удалось убить свирепую Син'Далл, неуловимую Баг'тиру и коварного Тетиса." }, { 16.40, "Осталось одно – добыть голову короля Бангалаша." }, { 20.61, "Давненько я точу зуб на этого белого тигра и оказался здесь именно ради него." }, { 26.35, "Убей короля Бангалаша, и мы признаем, что тебе нет равных в искусстве охоты." } } }, t = { d = 19.6, g = 1, v = "dwarf-male", n = { m = 192, f = 193 }, c = { m = { { 0.00, "Отлично сработано!" }, { 1.58, "Здорово!" }, { 2.33, "Поздравляю, ты преуспел там, где другие потерпели поражение." }, { 7.29, "Видеть тебя в рядах нашего охотничьего отряда – это честь для меня." }, { 12.99, "Отныне никто не усомнится в твоём искусстве охотника и следопыта." }, { 18.40, "Ура тебе!" }, { 19.30, "Ура!" } }, f = { { 0.00, "Отлично сработано!" }, { 1.53, "Здорово!" }, { 2.26, "Поздравляю, ты преуспела там, где другие потерпели поражение." }, { 7.15, "Видеть тебя в рядах нашего охотничьего отряда – это честь для меня." }, { 12.70, "Отныне никто не усомнится в твоём искусстве охотника и следопыта." }, { 17.96, "Ура тебе!" }, { 18.83, "Ура!" } } } } },
    [209] = { d = 30.7, v = "goblin-male", n = { x = 351 }, c = { x = { { 0.00, "Убивать тигров и добывать их клыки на экспорт в южные моря – трудно и дорого." }, { 5.67, "К счастью, мы придумали способ обрабатывать простые рого-подобные предметы и изготавливать неотличимые подделки." }, { 13.74, "Лучше всего, как ни смешно, подходят клыки троллей из племени Дробителей Черепов." }, { 19.67, "Ш-ш-ш, спокойно, чем меньше знает покупатель, тем крепче он спит, верно?" }, { 24.81, "Принеси мне побольше таких клыков, чтобы мы могли подготовить ежемесячную поставку!" } } }, t = { d = 16.4, g = 1, v = "goblin-male", n = { m = 158, f = 160 }, c = { m = { { 0.00, "А, хорошо, хорошо!" }, { 1.57, "Хотя ты мог бы получше счистить..." }, { 4.42, "Ну, неважно, неважно что." }, { 6.52, "Спасибо, благодаря тебе у нас возрастёт производительность и доходы!" }, { 12.06, "Хорошо, хорошо, а теперь перейдём к следующему делу..." } }, f = { { 0.00, "А, хорошо, хорошо!" }, { 1.54, "Хотя ты могла бы получше счистить..." }, { 4.56, "Ну, неважно, неважно что." }, { 6.62, "Спасибо, благодаря тебе у нас возрастёт производительность и доходы!" }, { 12.06, "Хорошо, хорошо, а теперь перейдём к следующему делу..." } } } } },
    [210] = { d = 19.9, v = "human-male", n = { x = 228 }, c = { x = { { 0.00, "Готовка по большей части лежит на мне." }, { 2.69, "И она доставляла мне много хлопот, пока я не купил механический горшок у одного гоблина в Пиратской бухте." }, { 10.12, "Это чудо какое-то!" }, { 11.50, "Он сэкономил мне много часов..." }, { 13.69, "Пока не сломался!" }, { 14.94, "Может, ты отнесёшь его назад к продавцу, в ремонт?" }, { 18.44, "Продавца зовут Кразек." } } }, t = { d = 28.4, v = "goblin-male", n = { x = 299 }, c = { x = { { 0.00, "А, вижу, разбитый горшок Кразека!" }, { 2.62, "Отличное устройство, но иногда выходят из строя пружины или шестерни." }, { 8.07, "Посмотрим, что случилось с этой штукой…" }, { 11.10, "Ага!" }, { 11.52, "Заржавел паровой агрегат, полетел сальник, а у надувателя отломились зубья." }, { 17.31, "Странно, как тут умудрялись хотя бы варить репу!" }, { 21.03, "Могу ли я это починить?" }, { 22.89, "Разумеется!" }, { 23.79, "Но не за бесплатно." }, { 25.24, "Бесплатный бывает только сыр в мышеловке..." } } } } },
    [211] = { d = 26.7, v = "human-male#50", n = { x = 304 }, c = { x = { { 0.00, "Увы, пришло время напасть на Андорал и изгнать оттуда лича!" }, { 4.48, "Злобный Араж Призыватель обосновался в самом сердце руин." }, { 8.76, "Его охраняют многочисленные воины Плети, рассеянные по всему центру бывшего города, а самого Аража охраняют сильнейшие бойцы." }, { 18.04, "Без многочисленных помощников тебе нечего и думать одержать над ним верх." }, { 23.31, "Убей Аража и принеси мне его кристалл-талисман!" } } }, t = { d = 19.8, g = 1, v = "human-male#50", n = { m = 201, f = 202 }, c = { m = { { 0.00, "Свершилось!" }, { 0.94, "Араж... этот лич наконец-то пал!" }, { 3.55, "Сегодня ты оказал огромную услугу Альянсу." }, { 7.03, "Храбрость и упорство – спутники подлинного героизма." }, { 11.23, "Прошу тебя, прими это в знак нашей благодарности." }, { 15.28, "Пусть все знают, что благодаря тебе Альянс одержал победу!" } }, f = { { 0.00, "Свершилось!" }, { 0.93, "Араж... этот лич наконец-то пал!" }, { 3.49, "Сегодня ты оказала огромную услугу Альянсу." }, { 6.99, "Храбрость и упорство – спутники подлинного героизма." }, { 11.12, "Прошу тебя, прими это в знак нашей благодарности." }, { 15.12, "Пусть все знают, что благодаря тебе Альянс одержал победу!" } } } } },
    [212] = { d = 34.4, v = "human-male", n = { x = 427 }, c = { x = { { 0.00, "Одно из моих коронных блюд – мороженый василиск под соусом винегрет из лайма." }, { 5.23, "Проблема лишь в том, что..." }, { 6.99, "Это мясо не подлежит хранению, а ведь я должен приготовить это блюдо сегодня вечером – на день рождения одного благородного господина!" }, { 16.05, "Если сможете, принесите мне охлаждённый окорок только что убитого ледоглазого василиска, а я организую специально для вас царскую трапезу!" }, { 25.24, "Ледоглазые василиски обитают в дюнах на северо-западе Тернистой долины, так что путь вам предстоит неблизкий." }, { 32.53, "И не задерживайтесь по дороге!" } } }, t = { d = 12.2, v = "human-male", n = { x = 136 }, c = { x = { { 0.00, "О, вот это окорочок!" }, { 1.54, "Большое, просто огромное спасибо!" }, { 4.08, "А теперь попрошу меня простить, мне нужно быстренько нарубить мясо, замариновать его и сервировать для банкета." } } } } },
    [213] = { d = 36.6, v = "goblin-male", n = { x = 437 }, c = { x = { { 0.00, "Он слишком далеко зашёл!" }, { 1.71, "Мало того, что этот Гелриз теснит управляющих, назначенных торговыми олигархами, теперь он попытался обвести вокруг пальца знаменитейшего пирата!" }, { 11.97, "Ревилгаз заявил, что не потерпит такого, и велел любым способом решить проблему." }, { 17.66, "Любым способом?" }, { 18.80, "Я выбираю кражу." }, { 20.01, "Геологов Торговой компании, работающих рядом с озером Назферити, заинтересовали странные синие кристаллы, найденные в руднике." }, { 28.87, "Принеси мне образцы этих камней, и меня не волнует, что тебе придётся сделать с геологами для выполнения задания." } } }, t = { d = 14.3, v = "goblin-male", n = { x = 176 }, c = { x = { { 0.00, "Любопытно." }, { 0.75, "Огранка кристаллов говорит только о том, что они собираются пользоваться ими в качестве горючего или катализатора." }, { 8.70, "Большего сказать я не могу." }, { 10.64, "Образцы необходимо показать старшему химику Хихиканту." } } } } },
    [214] = { d = 34.6, v = "human-female#45", n = { x = 420 }, c = { x = { { 0.00, "Не секрет, что красные банданы являются отличительным знаком бандитов из Братства Справедливости." }, { 6.55, "Но мы узнали, что материал, из которого они изготовлены, указывает на ранг члена братства." }, { 12.61, "Я рассказываю вам об этом, потому что хочу, чтобы вы устранили как можно больше бандитов высокого ранга." }, { 19.71, "Обладающих наивысшим рангом, без сомнения, можно найти в тайном убежище ван Клифа." }, { 25.34, "Когда справитесь с заданием, принесите мне десять красных шёлковых бандан в доказательство их смерти – и будете вознаграждены." }, { 33.78, "Желаю удачи." } } }, t = { d = 11.7, v = "human-female#45", n = { x = 122 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.35, "От имени народного ополчения я благодарю вас за ваши усилия." }, { 6.09, "Вскоре с помощью таких смельчаков, как вы, мы вернём эту землю её народу." } } } } },
    [215] = { d = 31.0, g = 1, v = "human-male", n = { m = 354, f = 357 }, c = { m = { { 0.00, "Спасибо, что спас меня." }, { 1.63, "Понимаю, как это выглядит... но позволь мне объяснить." }, { 5.39, "Лейтенант Дорен поручил мне снова завербоваться к Курцену, чтобы следить за его солдатами и предоставлять столь необходимые сведения повстанцам." }, { 15.35, "Ты видел, чем обернулась для меня попытка проникнуть в лагерь Курцена." }, { 20.23, "Я думал, что это - мой шанс..." }, { 22.30, "Ещё раз спасибо за спасение." }, { 24.24, "Это была тайная миссия, никому о ней не говори." }, { 27.63, "Но лейтенант Дорен может всё объяснить." } }, f = { { 0.00, "Спасибо, что спасла меня." }, { 1.85, "Понимаю, как это выглядит... но позволь мне объяснить." }, { 5.68, "Лейтенант Дорен поручил мне снова завербоваться к Курцену, чтобы следить за его солдатами и предоставлять столь необходимые сведения повстанцам." }, { 15.82, "Ты видела, чем обернулась для меня попытка проникнуть в лагерь Курцена." }, { 20.85, "Я думал, что это - мой шанс..." }, { 22.96, "Ещё раз спасибо за спасение." }, { 24.93, "Это была тайная миссия, никому о ней не говори." }, { 28.38, "Но лейтенант Дорен может всё объяснить." } } }, t = { d = 30.7, v = "human-male", n = { x = 342 }, c = { x = { { 0.00, "Да, Торсен сказал тебе правду." }, { 2.28, "Только помалкивай об этом." }, { 4.24, "Одно время мы, повстанцы, были слепо преданы полковнику Курцену." }, { 9.01, "Но сейчас он перешёл на сторону зла, и наша верность обратилась в ненависть." }, { 14.42, "Если кто-нибудь узнает, что рядовой Торсен имел дело с людьми Курцена, однажды утром мы можем найти его с перерезанным горлом." }, { 23.75, "Насколько мне известно, о задании Торсена знала только сержант Йохва и я." }, { 29.10, "И кто-то ещё." }, { 30.08, "Предатель." } } } } },
    [216] = { d = 35.1, v = "orc-male", n = { x = 390 }, c = { x = { { 0.00, "Эти фурболги Колючего Меха мешают нашему продвижению!" }, { 4.11, "Деревня Колючего Меха, что лежит на востоке, преграждает нам путь к заставе Расщеплённого Древа." }, { 11.19, "Это на дороге, что идёт в обход деревни Астранаар." }, { 14.97, "Если мы не будем её контролировать, Альянс получит дополнительный путь для вторжения." }, { 21.24, "Мы должны заткнуть эту дыру!" }, { 23.47, "Иди в деревню Колючего Меха да устрой фурболгам прореживание." }, { 28.12, "Выполнишь задачу – получишь награду, но важнее будет то, что ты выполнишь свой долг перед Ордой!" } } }, t = { d = 24.2, g = 1, v = "orc-male", n = { m = 227, f = 228 }, c = { m = { { 0.00, "Отлично, герой, отлично!" }, { 2.13, "Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что ещё одна дорога расчищена от сил Альянса." }, { 14.48, "Теперь завоевание Ясеневого леса Ордой пойдёт полным ходом!" }, { 19.58, "Ты заслужил свою награду, герой!" }, { 22.40, "Честь и слава тебе!" } }, f = { { 0.00, "Отлично, героиня, отлично!" }, { 2.29, "Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что ещё одна дорога расчищена от сил Альянса." }, { 14.64, "Теперь завоевание Ясеневого леса Ордой пойдёт полным ходом!" }, { 19.74, "Ты заслужила свою награду, герой!" }, { 22.64, "Честь и слава тебе!" } } } } },
    [217] = { d = 29.7, g = 1, v = "dwarf-male", n = { m = 331, f = 332 }, c = { m = { { 0.00, "Наши разведчики обнаружили предводителя троггов." }, { 3.59, "Похоже, этих тварей привёл к озеру Лок Модан их вождь по имени Громаг." }, { 8.77, "Его хорошо охраняют." }, { 10.36, "Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят." }, { 15.28, "Если ты уверен в своих силах, можешь возглавить операцию по ликвидации Громага и его громил." }, { 22.19, "Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю." } }, f = { { 0.00, "Наши разведчики обнаружили предводителя троггов." }, { 3.56, "Похоже, этих тварей привёл к озеру Лок Модан их вождь по имени Громаг." }, { 8.70, "Его хорошо охраняют." }, { 10.28, "Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят." }, { 15.16, "Если ты уверена в своих силах, можешь возглавить операцию по ликвидации Громага и его громил." }, { 22.08, "Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю." } } }, t = { d = 9.4, g = 1, v = "dwarf-male", n = { m = 94, f = 95 }, c = { m = { { 0.00, "Превосходно!" }, { 1.06, "Ты вернул надежду Лок Модану." }, { 3.55, "Громаг мёртв, и у нас появилась надежда изгнать троггов из наших земель." } }, f = { { 0.00, "Превосходно!" }, { 1.04, "Ты вернула надежду Лок Модану." }, { 3.57, "Громаг мёртв, и у нас появилась надежда изгнать троггов из наших земель." } } } } },
    [218] = { d = 19.0, v = "dwarf-male", n = { x = 214 }, c = { x = { { 0.00, "Мои записи!" }, { 0.90, "Они уволокли в свою мерзкую пещеру мои записи!" }, { 4.38, "Здоровенный громила, весь разрисованный с головы до ног..." }, { 8.43, "Жаль, я не смог разглядеть его получше!" }, { 11.20, "Послушай, тебе ведь уже приходилось иметь дело с троллями?" }, { 15.45, "Может, ты сумеешь вернуть мои драгоценные записи?.." } } }, t = { d = 22.5, v = "dwarf-male", n = { x = 244 }, c = { x = { { 0.00, "Великолепно!" }, { 0.94, "Словами не передать, как я благодарен!" }, { 3.75, "Мои записи, наконец-то!.." }, { 5.69, "Да к тому же, похоже, троллей Холодной долины удалось-таки обуздать, так что больше беспокоиться не о чем." }, { 13.46, "Кстати, послушай: я скоро закончу своё донесение – так, может, ты поработаешь курьером и доставишь его моему братцу Сениру?" } } } } },
    [219] = { d = 23.8, v = "human-male", n = { x = 244 }, c = { x = { { 0.00, "Наконец-то, сторонники Альянса!" }, { 2.39, "Помогите..." }, { 3.28, "Пожалуйста..." }, { 4.30, "Последнее, что я помню – как орки окружили наш отряд." }, { 8.33, "Меня ударили по затылку, и в глазах потемнело." }, { 11.89, "А теперь я пленник в этой пещере." }, { 14.48, "Спасите меня, я тяжело ранен." }, { 16.80, "Мне понадобится помощь, чтобы добраться до города..." }, { 20.77, "Пожалуйста..." }, { 21.79, "Вы моя последняя надежда..." } } }, t = { d = 12.2, g = 1, v = "human-male", n = { m = 149, f = 150 }, c = { m = { { 0.00, "Ты отлично послужил Королевству, герой." }, { 2.59, "Благодарю тебя за помощь капралу Кеешану." }, { 5.35, "Одному ему не удалось бы сбежать от орков Чёрной Горы." }, { 8.94, "Подобная храбрость заслуживает великой награды." } }, f = { { 0.00, "Ты отлично послужила Королевству, героиня." }, { 2.80, "Благодарю тебя за помощь капралу Кеешану." }, { 5.59, "Одному ему не удалось бы сбежать от орков Чёрной Горы." }, { 9.23, "Подобная храбрость заслуживает великой награды." } } } } },
    [220] = { d = 14.3, v = "orc-female", n = { x = 147 }, c = { x = { { 0.00, "Прежде чем дать тебе в награду следующий тотем, Ислен поручит тебе ещё одно задание." }, { 6.71, "Для этого понадобится фиал с водой, который я дала тебе." }, { 11.22, "Ступай, поговори с ней." }, { 13.06, "Мы ещё встретимся." } } }, t = { d = 29.4, v = "tauren-female#71", n = { x = 290 }, c = { x = { { 0.00, "А, фиал с водой, созданной и благословлённой Брин и добытой тобой, ни больше ни меньше." }, { 7.01, "Жидкость в этом фиале необходима для создания сапты, но годится и для других целей." }, { 13.87, "При помощи этой сапты ты сможешь разглядеть водных духов в святилище в Серебряном бору, к югу от Подгорода." }, { 22.73, "Что же до оставшихся капель... о них я расскажу тебе потом." }, { 27.53, "Не боишься долгого пути?" } } } } },
