    [222] = { d = 19.2, v = "human-male", n = { x = 219 }, c = { x = { { 0.00, "Твои прежние достижения наводят меня на мысль, что ты можешь схватиться с сильнейшими из воргенов, наводнивших наши леса." }, { 8.73, "Самыми опасными из всех оказались Ярые Клыки и нечистые воргены." }, { 13.42, "Они живут рядом с пещерами и в руднике на юге." }, { 16.87, "Зарево их костров видно издалека." } } }, t = { d = 14.6, g = 1, v = "human-male", n = { m = 174, f = 174 }, c = { m = { { 0.00, "Честно говоря, я не верил, что ты справишься с этой задачей, но ты воистину могучий герой." }, { 5.98, "Более того, если ты хочешь официально присоединиться к борьбе мастера Кэрвина, я с радостью напишу тебе рекомендательное письмо." } }, f = { { 0.00, "Честно говоря, я не верил, что ты справишься с этой задачей, но ты воистину могучая героиня." }, { 6.12, "Более того, если ты хочешь официально присоединиться к борьбе мастера Кэрвина, я с радостью напишу тебе рекомендательное письмо." } } } } },
