    [224] = { d = 32.7, g = 1, v = "dwarf-male", n = { m = 354, f = 358 }, c = { m = { { 0.00, "Мы должны защитить озеро Лок!" }, { 2.19, "Множество королевских солдат проливает кровь в далёких землях, а наш родной край в опасности." }, { 8.89, "Трогги полезли изо всех щелей!" }, { 11.21, "Нашествие троггов грозит безопасности Стальгорна." }, { 14.86, "Пора истребить мерзких мутантов!" }, { 17.31, "Нам нужна твоя помощь, отважный искатель приключений." }, { 21.29, "Ступай и устрани нависшую над нами угрозу." }, { 24.48, "Убей десять троггов из племени Камнедробов и десять разведчиков из племени Камнедробов и возвращайся." } }, f = { { 0.00, "Мы должны защитить озеро Лок!" }, { 2.24, "Множество королевских солдат проливает кровь в далёких землях, а наш родной край в опасности." }, { 9.08, "Трогги полезли изо всех щелей!" }, { 11.45, "Нашествие троггов грозит безопасности Стальгорна." }, { 15.18, "Пора истребить мерзких мутантов!" }, { 17.69, "Нам нужна твоя помощь, отважная искательница приключений." }, { 22.02, "Ступай и устрани нависшую над нами угрозу." }, { 25.28, "Убей десять троггов из племени Камнедробов и десять разведчиков из племени Камнедробов и возвращайся." } } }, t = { d = 23.7, g = 1, v = "dwarf-male", n = { m = 268, f = 270 }, c = { m = { { 0.00, "Молодчина!" }, { 0.77, "Ты проявил немалое мужество на поле боя." }, { 3.72, "Побольше таких, как ты, и мы победим троггов." }, { 6.92, "Ты славно послужил королю Магни." }, { 9.29, "Если тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером." }, { 15.32, "Капитан дал ему непростое задание." }, { 17.82, "Уверен, ему понадобится помощь." }, { 20.12, "Поговори с Булыжным Карьером, он сейчас в башне." } }, f = { { 0.00, "Молодчина!" }, { 0.77, "Ты проявила немалое мужество на поле боя." }, { 3.80, "Побольше таких, как ты, и мы победим троггов." }, { 7.02, "Ты славно послужила королю Магни." }, { 9.47, "Если тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером." }