    [225] = { d = 13.4, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Надпись на древнем могильном камне гласит:" }, { 3.38, "МОРГАН ЛАДИМОР" }, { 4.57, "При внимательном рассмотрении вы замечаете, что могилу недавно раскапывали, и большая часть земли насыпана заново..." } } }, t = { d = 21.5, v = "human-male", n = { x = 218 }, c = { x = { { 0.00, "Морган Ладимор?" }, { 1.24, "А-а-а, да, разумеется." }, { 2.96, "У него долгая и печальная история." }, { 5.64, "Я знал его до того, как он ушёл на войну, но с тех пор ни разу не видел." }, { 11.01, "Он был добрым и благородным человеком, но окончил свою жизнь плохо." }, { 16.10, "Подожди-ка, я дам тебе вещь, которая поведает его историю лучше, чем я..." } } } } },
    [226] = { d = 27.9, v = "human-male", n = { x = 323 }, c = { x = { { 0.00, "Нас со Свеном ждут трудные времена, учитывая, что на востоке поселился Некромант." }, { 5.60, "Мы здесь совсем одни, приходится самим добывать себе еду." }, { 9.69, "Такое впечатление, что всякий раз, как я возвращаюсь в лагерь, неся добычу, за мной увязываются лютые волки." }, { 17.18, "Что и говорить, жить здесь опасно!" }, { 19.51, "Но если ты избавишь нас хотя бы от части волков, нам станет полегче." }, { 24.29, "Они живут на севере и на востоке отсюда, возле реки." } } }, t = { d = 16.1, g = 1, v = "human-male", n = { m = 179, f = 180 }, c = { m = { { 0.00, "О, хорошо." }, { 0.80, "Ты здорово проредил волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном." }, { 9.31, "Вот, возьми в награду взрывпакеты." }, { 11.84, "Их делают в городе, и Свену недавно выделили целую партию." } }, f = { { 0.00, "О, хорошо." }, { 0.79, "Ты здорово проредила волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном." }, { 9.25, "Вот, возьми в награду взрывпакеты." }, { 11.74, "Их делают в городе, и Свену недавно выделили целую партию." } } } } },
    [227] = { d = 12.6, v = "human-male", n = { x = 138 }, c = { x = { { 0.00, "*Он роется на полках и вытаскивает книгу в кожаном переплёте.*" }, { 4.57, "Если хочешь узнать побольше, спроси Альтею, она занималась... проблемами... возникшими с ним в последнее время." } } }, t = { d = 35.1, g = 1, v = "human-female#47", n = { m = 386, f = 389 }, c = { m = { { 0.00, "Морган Ладимор?" }, { 1.17, "Никогда о нём не слышала..." }, { 3.11, "А, ты о Мор'Ладиме!" }, { 4.47, "Ты не знаешь его историю?" }, { 6.35, "Что ж, я объясню тебе вкратце." }, { 8.55, "По Сумеречному лесу бродит неупокоенный мертвец, зовущий себя Мор'Ладимом." }, { 13.92, "Судя по всему, это восставшее из могилы тело Моргана Ладимора, о котором ты, кажется, уже слышал." }, { 21.04, "Он доставил нам массу неприятностей – начиная от нападения на патрульных и заканчивая убийствами простых людей." }, { 28.88, "*Она смеривает вас взглядом.*" }, { 31.52, "Кажется, ты смог бы помочь ему упокоиться с миром." } }, f = { { 0.00, "Морган Ладимор?" }, { 1.17, "Никогда о нём не слышала..." }, { 3.12, "А, ты о Мор'Ладиме!" }, { 4.48, "Ты не знаешь его историю?" }, { 6.37, "Что ж, я объясню тебе вкратце." }, { 8.58, "По Сумеречному лесу бродит неупокоенный мертвец, зовущий себя Мор'Ладимом." }, { 13.97, "Судя по всему, это восставшее из могилы тело Моргана Ладимора, о котором ты, кажется, уже слышала." }, { 21.18, "Он доставил нам массу неприятностей – начиная от нападения на патрульных и заканчивая убийствами простых людей." }, { 29.04, "*Она смеривает вас взглядом.*" }, { 31.60, "Кажется, ты смогла бы помочь ему упокоиться с миром." } } } } },
    [228] = { d = 12.3, v = "human-female#47", n = { x = 135 }, c = { x = { { 0.00, "Разведчики сообщают, что Мор'Ладим бродит по кладбищу." }, { 3.90, "Мы похоронили его за домом на холме, знаешь, где это?" }, { 7.79, "Больше я тебе ничем помочь не могу..." }, { 10.58, "Разве что пожелать удачи." } } }, t = { d = 11.0, g = 1, v = "human-female#47", n = { m = 103, f = 104 }, c = { m = { { 0.00, "Ты убил его?" }, { 1.13, "Это великий подвиг!" }, { 2.86, "Прими благодарность от имени народа Темнолесья и Ночного дозора." }, { 8.26, "Ах, да..." }, { 9.02, "Осталось ещё одно дело..." } }, f = { { 0.00, "Ты убила его?" }, { 1.18, "Это великий подвиг!" }, { 2.87, "Прими благодарность от имени народа Темнолесья и Ночного дозора." }, { 8.16, "Ах, да..." }, { 8.90, "Осталось ещё одно дело..." } } } } },
    [229] = { d = 19.1, v = "human-female#47", n = { x = 212 }, c = { x = { { 0.00, "Надо было предупредить тебя раньше…" }, { 2.63, "Как бы тебе сказать…" }, { 4.11, "Морган думал, что у него погибла вся семья, но его дочь, Сара Ладимор, жива и служит в Ночном дозоре." }, { 11.43, "Её всегда беспокоили... обстоятельства... связанные с гибелью её отца." }, { 16.37, "Быть может, ты сообщишь ей о случившемся." } } }, t = { d = 11.7, v = "human-female#45", n = { x = 91 }, c = { x = { { 0.00, "Да?" }, { 0.66, "Мой отец…" }, { 2.32, "*Она опускает глаза.*" }, { 4.64, "Жаль... что я не могу ничего для него сделать..." }, { 8.34, "Ах, если бы я поговорила с ним до того, как..." } } } } },
    [230] = { d = 12.2, v = "narrator", n = { x = 121 }, c = { x = { { 0.00, "Порывшись в груде земли, вы находите небольшую книгу, перепачканную грязью." }, { 6.43, "На ней нет заглавия, зато в ней содержатся сведения, необходимые Свену." } } }, t = { d = 13.5, v = "human-male", n = { x = 145 }, c = { x = { { 0.00, "*Свен прочитывает несколько страниц и захлопывает книгу.*" }, { 4.40, "Этот таинственный незнакомец – свидетель смерти моей семьи!" }, { 8.97, "У меня столько вопросов к этому человеку..." }, { 12.31, "Узнать бы, кто он!" } } } } },
    [231] = { d = 16.9, v = "human-female#45", n = { x = 157 }, c = { x = { { 0.00, "Возьми это кольцо и отнеси на его могилу." }, { 3.37, "Может быть... может быть, он поймёт, что я жива и никто не винит его в случившемся." }, { 9.68, "*Со слезами на глазах она снимает кольцо с правой руки и отдаёт вам.*" }, { 15.04, "И... спасибо." } } }, t = { d = 29.4, g = 1, v = "human-male", n = { x = 258 }, c = { m = { { 0.00, "*В шорохе ветра слышится призрачный голос...*" }, { 4.24, "Что это?.." }, { 5.10, "Сара?" }, { 5.60, "Неужели она жива?" }, { 7.10, "Камень с сердца…" }, { 8.46, "Путник." }, { 9.10, "Возьми мой меч, Принцип." }, { 11.03, "Моя душа упокоилась, и он более мне не нужен." }, { 14.67, "Он был выкован во имя добра, а я оказался не достоин владеть им." }, { 19.75, "Быть может, ты сможешь нести Свет вместо меня." }, { 23.46, "И сохрани кольцо." }, { 24.89, "Я больше не достоин его." }, { 26.89, "Лиз, любовь моя..." } }, f = { { 0.00, "*В шорохе ветра слышится призрачный голос...*" }, { 4.16, "Что это?.." }, { 5.06, "Сара?" }, { 5.58, "Неужели она жива?" }, { 7.15, "Камень с сердца…" }, { 8.57, "Путница." }, { 9.32, "Возьми мой меч, Принцип." }, { 11.34, "Моя душа упокоилась, и он более мне не нужен." }, { 15.15, "Он был выкован во имя добра, а я оказался не достоин владеть им." }, { 20.46, "Быть может, ты сможешь нести Свет вместо меня." }, { 24.35, "И сохрани кольцо." }, { 25.85, "Я больше не достоин его." }, { 27.94, "Лиз, любовь моя..." } } } } },
    [232] = { d = 42.0, v = "scourge-female", n = { x = 386 }, c = { x = { { 0.00, "Королевскому фармацевтическому обществу нужна твоя помощь." }, { 5.16, "Слушай внимательно, поскольку, если мой план удастся, мы оба окажемся в выгодном положении." }, { 13.18, "Согласна, аптекарь Чанн... немного тронутый... но его исследования приносят свои плоды, если попадают в руки к умному человеку." }, { 24.45, "К счастью, я как раз из таких." }, { 27.07, "Отнеси этот заказ Алессандро Лусе, хозяину \"Тысячи мелочей Синей Луны\", он даст тебе набор для полевых испытаний." }, { 37.24, "Принеси его мне, и я расскажу тебе подробнее о задании." } } }, t = { d = 11.8, v = "scourge-male", n = { x = 112 }, c = { x = { { 0.00, "А, так Зинг нужен набор для полевых испытаний?" }, { 3.97, "Жаль, что она не решилась осчастливить меня своим визитом." }, { 9.04, "Ладно, сейчас я подготовлю набор." } } } } },
    [233] = { d = 16.6, g = 1, v = "dwarf-male", n = { m = 176, f = 178 }, c = { m = { { 0.00, "Не думаю, что ты горишь желанием мне помочь, парень, но у меня тут целая куча писем, а времени на доставку нет." }, { 8.12, "Это всё для Талина Остроглаза." }, { 10.36, "Его лагерь – у замёрзшего озера, к западу отсюда." }, { 13.99, "Ну что, может, доставишь ему почту?" } }, f = { { 0.00, "Не думаю, что ты горишь желанием мне помочь, красотка, но у меня тут целая куча писем, а времени на доставку нет." }, { 8.22, "Это всё для Талина Остроглаза." }, { 10.46, "Его лагерь – у замёрзшего озера, к западу отсюда." }, { 14.07, "Ну что, может, доставишь ему почту?" } } }, t = { d = 12.6, v = "dwarf-male", n = { x = 126 }, c = { x = { { 0.00, "Благодарю тебя, я уже давно ждал этих писем..." }, { 3.72, "Конечно, они не все для меня." }, { 6.04, "Вот это, скажем, для Грелина Белоборода." }, { 9.20, "Он тут неподалёку живёт, может, зайдёшь к нему?" } } } } },
    [234] = { d = 10.0, v = "dwarf-male", n = { x = 111 }, c = { x = { { 0.00, "Если мне память не изменяет, лагерь Грелина находится дальше по дороге, на юго-восток отсюда." }, { 6.96, "Не сомневаюсь, он будет рад этому посланию." } } }, t = { d = 15.7, v = "dwarf-male", n = { x = 180 }, c = { x = { { 0.00, "Как здорово!" }, { 0.90, "Я уже давно не получал весточки из Стальгорна." }, { 4.18, "Письма моей матушки всегда согревают мне душу." }, { 7.59, "Кстати, и тебе не помешало бы почитать что-нибудь дельное." }, { 11.77, "Вон, возьми любое руководство, которых у нас тут навалом." } } } } },
    [235] = { d = 33.9, v = "orc-male", n = { x = 333 }, c = { x = { { 0.00, "Внимание, молодые герои!" }, { 2.12, "Вас ждут дикие чащи Ясеневого леса!" }, { 5.14, "Орде удалось закрепиться в землях к северу от Степей." }, { 9.67, "И два наших форпоста – застава Расщеплённого Древа и застава Зорамского взморья – бьются во славу Орды!" }, { 18.28, "Те, кто жаждет подвигов, могут отправиться туда." }, { 22.36, "Запомните: Сенани Громосерд находится на заставе Расщеплённого Древа, к северу от Степей." }, { 29.77, "Она ждёт желающих принять участие в большой охоте!" } } }, t = { d = 30.3, g = 1, v = "tauren-female", n = { m = 307, f = 306 }, c = { m = { { 0.00, "Добро пожаловать на новое пограничье." }, { 2.97, "Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя." }, { 11.11, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 18.53, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 23.48, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } }, f = { { 0.00, "Добро пожаловать на новое пограничье." }, { 3.01, "Ясеневый лес – край неограниченных возможностей, где юной героине вроде тебя выпадает шанс показать себя." }, { 11.33, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 18.86, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 23.88, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } } } } },
    [237] = { d = 27.7, g = 1, v = "dwarf-male", n = { x = 305 }, c = { m = { { 0.00, "Горный пехотинец Кремневик превозносит тебя до небес, герой." }, { 4.37, "Поэтому я хочу доверить тебе очень важное задание." }, { 8.09, "Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны." }, { 14.32, "Отправляйся в южные холмы и убей десять головоломов из племени Камнедробов и десять ясновидцев из племени Камнедробов." }, { 22.73, "Это поможет нам выиграть время." }, { 25.05, "Когда выполнишь задание, возвращайся." } }, f = { { 0.00, "Горный пехотинец Кремневик превозносит тебя до небес, героиня." }, { 4.49, "Поэтому я хочу доверить тебе очень важное задание." }, { 8.21, "Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны." }, { 14.42, "Отправляйся в южные холмы и убей десять головоломов из племени Камнедробов и десять ясновидцев из племени Камнедробов." }, { 22.82, "Это поможет нам выиграть время." }, { 25.13, "Когда выполнишь задание, возвращайся." } } }, t = { d = 31.5, g = 1, v = "dwarf-male", n = { m = 338, f = 339 }, c = { m = { { 0.00, "Ты прекрасно справился с заданием, герой!" }, { 3.08, "Сам король может гордиться тобой." }, { 5.63, "К сожалению, обещанное подкрепление так и не подошло." }, { 9.52, "Фронт обагрен кровью воинов Альянса." }, { 12.27, "Вести о потерях наполняют горечью моё сердце..." }, { 15.82, "Так пусть же эти жертвы будут не напрасны!" }, { 18.97, "Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу." }, { 24.13, "Поговори с горным пехотинцем Стеноломом, он даст тебе новое задание." }, { 29.23, "Ты нужен нам как никогда." } }, f = { { 0.00, "Ты прекрасно справилась с заданием, героиня!" }, { 3.32, "Сам король может гордиться тобой." }, { 5.90, "К сожалению, обещанное подкрепление так и не подошло." }, { 9.83, "Фронт обагрен кровью воинов Альянса." }, { 12.61, "Вести о потерях наполняют горечью моё сердце..." }, { 16.21, "Так пусть же эти жертвы будут не напрасны!" }