    [238] = { d = 22.7, v = "scourge-male", n = { x = 220 }, c = { x = { { 0.00, "Я подготовил набор." }, { 1.66, "Не сомневаюсь, аптекарю Зинг не терпится его получить." }, { 6.19, "Отнеси посылку как можно скорее и сообщи ей, что я запишу стоимость набора на счёт Общества." }, { 13.89, "Кроме того, передай ей мой пламенный привет." }, { 17.67, "Ну же, не стой как истукан." }, { 19.86, "Простым курьерам не ведом отдых, а?" } } }, t = { d = 24.1, v = "scourge-female", n = { x = 239 }, c = { x = { { 0.00, "Хорошо – приятно работать с теми, кто старается не тратить моё время попусту." }, { 6.37, "Когда я закончу с набором, ты сможешь двинуться в путь." }, { 10.89, "Набор пригодится для сбора необходимых данных." }, { 14.75, "Я попытаюсь закончить побыстрее." }, { 17.42, "А пока ждёшь, можешь обдумать, что возьмёшь с собой в пустыню." }, { 22.46, "Да, именно в пустыню." } } } } },
    [239] = { d = 28.3, v = "human-male", n = { x = 359 }, c = { x = { { 0.00, "Гарнизон западной границы докладывает об усилении активности гноллов и грабителей." }, { 5.30, "Они просят, чтобы мы прислали подкрепление из Штормграда..." }, { 9.15, "Но у нас не хватает людей!" }, { 10.84, "Твоя помощь не была бы лишней." }, { 12.88, "Поговори с заместителем судьи Рейнером: он сейчас находится в гарнизоне у Западного ручья." }, { 18.71, "Рейнер скажет тебе, что делать." }, { 20.80, "Гарнизон расположен к западу отсюда: иди по дороге, а потом, когда перейдёшь через речушку по мосту, сверни направо." } } }, t = { d = 14.0, v = "human-male", n = { x = 134 }, c = { x = { { 0.00, "Тебя что, маршал Дугхан сюда послал?" }, { 3.11, "Ну..." }, { 3.56, "Ты, конечно, не солдат, но маршалу я доверяю." }, { 7.26, "У нас тут сложилась, скажем так, напряжённая ситуация." }, { 11.56, "Надеюсь, ты сумеешь нам помочь." } } } } },
    [240] = { d = 3.2, v = "human-male", n = { x = 28 }, c = { x = { { 0.00, "А вот и пирожки с \"крабами\" а-ля Груал!" } } }, t = { d = 5.6, v = "human-male", n = { x = 48 }, c = { x = { { 0.00, "Ага!" }, { 0.47, "Спасибо." }, { 1.26, "Как раз то, что нужно." }, { 3.16, "А вот и твоя плата за услугу!" } } } } },
    [243] = { d = 37.0, v = "scourge-female", n = { x = 376 }, c = { x = { { 0.00, "Ты отправишься в пустыню Танарис изучать состав тканей василисков, скорпидов и гиен." }, { 7.02, "Добудь образцы тканей и проверь их при помощи этого набора; подозреваю, что не все окажутся удачными." }, { 15.38, "Мне нужно по восемь образцов каждого вида." }, { 18.97, "Кроме того, у гоблинов Прибамбасска есть источники энергии, необходимые для работы изменённого набора." }, { 27.33, "Поговори с главным инженером Чепухастером и добудь у него источник энергии." }, { 33.60, "Без образцов ткани можешь не возвращаться." } } }, t = { d = 30.0, g = 1, v = "goblin-male", n = { x = 322 }, c = { m = { { 0.00, "А, наши источники энергии сорок семь одиннадцать эф-тэ-зэ!" }, { 4.32, "Обычно мы пользуемся ими для электрификации колодцев, но БЛАГОДАРЯ ПРОКЛЯТЫМ КОЧЕВНИКАМ энергии у нас в избытке." }, { 12.51, "Не вопрос, я могу добыть тебе источник энергии, для каких бы гнусных научных целей он тебе ни понадобился." }, { 20.42, "А, думаешь, я ни о чём не догадался?" }, { 23.01, "Как бы не так." }, { 24.01, "Но это тебе дорого обойдётся, герой." }, { 26.74, "В Прибамбасске ничто не достаётся даром." } }, f = { { 0.00, "А, наши источники энергии сорок семь одиннадцать эф-тэ-зэ!" }, { 4.37, "Обычно мы пользуемся ими для электрификации колодцев, но БЛАГОДАРЯ ПРОКЛЯТЫМ КОЧЕВНИКАМ энергии у нас в избытке." }, { 12.65, "Не вопрос, я могу добыть тебе источник энергии, для каких бы гнусных научных целей он тебе ни понадобился." }, { 20.66, "А, думаешь, я ни о чём не догадался?" }, { 23.28, "Как бы не так." }, { 24.29, "Но это тебе дорого обойдётся, героиня." }, { 27.19, "В Прибамбасске ничто не достаётся даром." } } } } },
