    [245] = { d = 26.7, g = 1, v = "human-male", n = { m = 302, f = 303 }, c = { m = { { 0.00, "Привет тебе, герой." }, { 1.42, "Наверное, ты видел пауков на западной границе?" }, { 4.64, "Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья." }, { 11.63, "Мне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться." }, { 17.39, "Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов." }, { 24.07, "Мой тебе совет: остерегайся их яда." } }, f = { { 0.00, "Привет тебе, героиня." }, { 1.55, "Наверное, ты видела пауков на западной границе?" }, { 4.85, "Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья." }, { 11.88, "Мне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться." }, { 17.66, "Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов." }, { 24.37, "Мой тебе совет: остерегайся их яда." } } }, t = { d = 13.4, g = 1, v = "human-male", n = { m = 137, f = 138 }, c = { m = { { 0.00, "А!" }, { 0.22, "Ты вернулся." }, { 1.22, "И на первый взгляд – в целости и сохранности." }, { 4.75, "Разумеется, Ночной дозор весьма тебе признателен." }, { 8.77, "Я обещал вознаградить тебя, и обещание своё выполняю." }, { 13.02, "Держи." } }, f = { { 0.00, "А!" }, { 0.21, "Ты вернулась." }, { 1.28, "И на первый взгляд – в целости и сохранности." }, { 4.76, "Разумеется, Ночной дозор весьма тебе признателен." }, { 8.75, "Я обещал вознаградить тебя, и обещание своё выполняю." }, { 12.94, "Держи." } } } } },
    [246] = { d = 21.7, v = "human-male", n = { x = 253 }, c = { x = { { 0.00, "У нас нет лишних людей, но с гноллами, о которых ты говоришь, надо что-то делать." }, { 5.52, "Поищи их в южной части Красногорья." }, { 8.03, "Убей, кого сможешь, и сообщи мне об их общем числе и степени угрозы, которую они представляют для города." }, { 15.26, "Гноллы стоят лагерем вдоль южной дороги." }, { 18.08, "Сделай это ради армии Штормграда, и получишь награду." } } }, t = { d = 27.8, g = 1, v = "human-male", n = { m = 302, f = 303 }, c = { m = { { 0.00, "*Заместитель судьи Фелдон слушает ваш отчёт.*" }, { 3.84, "Значит, там собралось немало гноллов, и, судя по всему, они весьма сильны." }, { 9.29, "Должно быть, тебе нелегко было собрать эти сведения." }, { 13.18, "Что ж, мы благодарим тебя за помощь." }, { 15.78, "Если ты ещё не беседовал с маршалом Маррисом и мировым судьёй Соломоном, непременно обратись к ним." }, { 22.78, "Дела у нас идут всё хуже; не сомневаюсь, эти двое найдут тебе работу." } }, f = { { 0.00, "*Заместитель судьи Фелдон слушает ваш отчёт.*" }, { 3.84, "Значит, там собралось немало гноллов, и, судя по всему, они весьма сильны." }, { 9.26, "Должно быть, тебе нелегко было собрать эти сведения." }, { 13.12, "Что ж, мы благодарим тебя за помощь." }, { 15.70, "Если ты ещё не беседовала с маршалом Маррисом и мировым судьёй Соломоном, непременно обратись к ним." }, { 22.73, "Дела у нас идут всё хуже; не сомневаюсь, эти двое найдут тебе работу." } } } } },
    [247] = { t = { d = 29.4, g = 1, v = "tauren-female", n = { m = 275, f = 280 }, c = { m = { { 0.00, "Ты убил всех трёх зверей Охоты в Ясеневом лесу." }, { 4.08, "Ты принёс мне достаточно доказательств их гибели – в твоей силе и упорстве нет никаких сомнений." }, { 12.17, "В твоих жилах течёт кровь охотника, и ты достоин похвалы!" }, { 17.02, "Прими эту безделушку в знак признания твоих славных подвигов, что ты совершил сегодня в Ясеневом лесу во имя Орды." }, { 26.87, "Да хранят тебя предки!" } }, f = { { 0.00, "Ты убила всех трёх зверей Охоты в Ясеневом лесу." }, { 4.18, "Ты принесла мне достаточно доказательств их гибели – в твоей силе и упорстве нет никаких сомнений." }, { 12.55, "В твоих жилах течёт кровь охотника, и ты достойна похвалы!" }, { 17.51, "Прими эту безделушку в знак признания твоих славных подвигов, что ты совершила сегодня в Ясеневом лесу во имя Орды." }, { 27.50, "Да хранят тебя предки!" } } } } },
    [248] = { d = 25.0, v = "human-male", n = { x = 298 }, c = { x = { { 0.00, "Я наблюдал за башней Илгалара и понял, что Моргант враждует с орками крепости Каменной Стражи." }, { 6.50, "Не знаю, что за этим кроется, но ты можешь помочь мне приоткрыть завесу тайны." }, { 11.88, "Возьми ещё один амулет Азоры и отнеси его на вершину уцелевшей башни рядом с крепостью." }, { 18.00, "Отыщи подходящее место для амулета и спрячь его там." }, { 21.59, "Для этой цели прекрасно подойдёт сундук или кувшин." } } }, t = { d = 9.0, v = "narrator", n = { x = 101 }, c = { x = { { 0.00, "Это подходящий сосуд для амулета Азоры." }, { 3.13, "Он позволит Теокриту проникнуть в помыслы обитателей крепости Каменной Стражи." } } } } },
    [249] = { d = 29.4, g = 1, v = "human-male", n = { m = 316, f = 316 }, c = { m = { { 0.00, "Ценой долгих усилий я раскрыл планы Морганта." }, { 3.44, "Он ищет Косу Элуны... и быть может, уже отыскал её!" }, { 7.27, "Коли так, то скоро Красногорье, а следом и всё королевство Штормграда почувствует его тёмную мощь." }, { 14.40, "Я не готов выступить против Морганта, но, боюсь, терять время нельзя." }, { 19.55, "Ты должен войти в башню Илгалара и бросить ему вызов." }, { 23.58, "Одолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет." } }, f = { { 0.00, "Ценой долгих усилий я раскрыл планы Морганта." }, { 3.46, "Он ищет Косу Элуны... и быть может, уже отыскал её!" }, { 7.33, "Коли так, то скоро Красногорье, а следом и всё королевство Штормграда почувствует его тёмную мощь." }, { 14.52, "Я не готов выступить против Морганта, но, боюсь, терять время нельзя." }, { 19.72, "Ты должна войти в башню Илгалара и бросить ему вызов." }, { 23.78, "Одолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет." } } }, t = { d = 21.4, g = 1, v = "human-male", n = { m = 225, f = 226 }, c = { m = { { 0.00, "Ты сделал великое дело." }, { 1.90, "Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности." }, { 7.62, "Смиренно прошу принять эту награду." }, { 10.51, "Я пожелал бы тебе мира, выпади нам жить в мирные времена." }, { 15.02, "Вместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях." } }, f = { { 0.00, "Ты сделала великое дело." }, { 1.92, "Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности." }, { 7.49, "Смиренно прошу принять эту награду." }, { 10.31, "Я пожелал бы тебе мира, выпади нам жить в мирные времена." }, { 14.71, "Вместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях." } } } } },
    [250] = { d = 28.9, g = 1, v = "dwarf-male", n = { m = 351, f = 351 }, c = { m = { { 0.00, "Хвала небесам, что хоть кого-то волнует наша дамба." }, { 3.60, "Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра!" }, { 8.39, "Не сомневаюсь, следующей целью Чёрного Железа станет именно Дамба." }, { 12.99, "Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора." }, { 18.95, "Потому-то ты мне и нужен." }, { 20.69, "Я заметил сапёров из клана Чёрного Железа неподалёку от восточной части дамбы." }, { 25.98, "Разведай обстановку и возвращайся с уликами." } }, f = { { 0.00, "Хвала небесам, что хоть кого-то волнует наша дамба." }, { 3.57, "Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра!" }, { 8.32, "Не сомневаюсь, следующей целью Чёрного Железа станет именно Дамба." }, { 12.88, "Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора." }, { 18.80, "Потому-то ты мне и нужна." }, { 20.52, "Я заметил сапёров из клана Чёрного Железа неподалёку от восточной части дамбы." }, { 25.76, "Разведай обстановку и возвращайся с уликами." } } }, t = { d = 4.7, v = "narrator", n = { x = 52 }, c = { x = { { 0.00, "В подозрительной бочке содержится странно пахнущий порошок." } } } } },
    [251] = { d = 10.2, v = "human-male", n = { x = 112 }, c = { x = { { 0.00, "Отнесите записку Шире Фон-Инди." }, { 2.40, "Он знает множество языков и не чужд древним искусствам – если кто и может перевести это послание, то это он." } } }, t = { d = 2.9, v = "narrator", n = { x = 31 }, c = { x = { { 0.00, "Шира принимается за перевод записки..." } } } } },
    [252] = { d = 14.9, v = "human-male", n = { x = 165 }, c = { x = { { 0.00, "О небо!" }, { 0.58, "Если то, о чём сказано в этой записке – правда, то Аберкромби сделал нечто... невообразимое." }, { 7.13, "Отнеси-ка переведённую записку Элло." }, { 9.70, "И поторопись, поскольку я боюсь, что это чудовище уже ковыляет к городу..." } } }, t = { d = 16.0, g = 1, v = "human-male", n = { m = 153, f = 156 }, c = { m = { { 0.00, "*Элло читает письмо... и бледнеет на глазах.*" }, { 4.06, "*Затем он поднимает на вас взгляд.*" }, { 6.96, "Хотя ты помогал Аберкромби по доброте душевной, именно ты обрёк наш город на гибель." }, { 13.52, "*Элло погружается в раздумья...*" } }, f = { { 0.00, "*Элло читает письмо... и бледнеет на глазах.*" }, { 4.11, "*Затем он поднимает на вас взгляд.*" }, { 7.04, "Хотя ты помогала Аберкромби по доброте душевной, именно ты обрекла наш город на гибель." }, { 13.68, "*Элло погружается в раздумья...*" } } } } },
    [253] = { d = 41.0, v = "human-male", n = { x = 453 }, c = { x = { { 0.00, "Бальзамировщиком в наших краях давно пугают детей." }, { 3.80, "Когда-то он был добрым алхимиком, но смерть любимой жены Элизы лишила его рассудка." }, { 10.01, "Чтобы вернуть её к жизни, он прибег к тёмной магии и даже вложил в грудь мёртвой супруги собственное сердце." }, { 17.95, "Это оживило Элизу... но её сразило проклятие – она возжелала человеческой плоти, и Бальзамировщику пришлось закопать её обратно." }, { 27.43, "Всё его могущество заключено в сердце." }, { 30.30, "Отыщи могилу Элизы, извлеки из неё сердце и принеси его мне, пока оно бьётся." }, { 36.10, "Если тебе удастся выполнить это, то сила Бальзамировщика иссякнет." } } }, t = { d = 13.4, g = 1, v = "human-male", n = { m = 147, f = 148 }, c = { m = { { 0.00, "Получилось!" }, { 0.91, "Магия этого сердца защитит нас от зла Бальзамировщика и послужит могущественным талисманом Темнолесью." }, { 8.75, "Ты совершил подвиг во имя нашего народа." }, { 11.97, "Мы тебя не забудем." } }, f = { { 0.00, "Получилось!" }, { 0.91, "Магия этого сердца защитит нас от зла Бальзамировщика и послужит могущественным талисманом Темнолесью." }, { 8.76, "Ты совершила подвиг во имя нашего народа." }, { 12.05, "Мы тебя не забудем." } } } } },
    [254] = { t = { d = 16.2, v = "narrator", n = { x = 158 }, c = { x = { { 0.00, "Вы разгребаете рыхлую землю на могиле... и натыкаетесь на остатки гроба." }, { 6.13, "Из гроба доносится скрежет когтистых пальцев и лязг гнилых зубов..." }, { 11.87, "Откроете гроб, чтобы забрать сердце Бальзамировщика?" } } } } },
    [255] = { d = 30.6, g = 1, v = "dwarf-male", n = { x = 341 }, c = { m = { { 0.00, "Пройдёт два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да ещё два месяца они будут до нас добираться!" }, { 9.15, "И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности." }, { 15.71, "Похоже, у меня нет выбора." }, { 17.60, "Придётся искать наёмников." }, { 19.37, "Как насчёт тебя?" }, { 20.51, "На первый взгляд ты подходишь, герой." }, { 23.09, "На северном берегу озера разбила лагерь группа огров." }, { 26.94, "Может быть, ты избавишь наш город от опасности?" } }, f = { { 0.00, "Пройдёт два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да ещё два месяца они будут до нас добираться!" }, { 9.26, "И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности." }, { 15.89, "Похоже, у меня нет выбора." }, { 17.81, "Придётся искать наёмников." }, { 19.60, "Как насчёт тебя?" }, { 20.75, "На первый взгляд ты подходишь, героиня." }, { 23.49, "На северном берегу озера разбила лагерь группа огров." }, { 27.38, "Может быть, ты избавишь наш город от опасности?" } } }, t = { d = 10.5, v = "dwarf-male", n = { x = 116 }, c = { x = { { 0.00, "Прекрасные новости!" }, { 1.52, "Я и народ Телсамара глубоко признательны тебе." }, { 5.11, "Ведь если нам удастся разобраться с ограми, мы сможем заняться троггами." } } } } },
    [256] = { d = 26.2, v = "narrator", n = { x = 297 }, c = { x = { { 0.00, "По приказу магистрата Телсамара:" }, { 2.43, "Чок'сул, обвиняемый в организации нападений на город Телсамар, Каменную дамбу и раскоп, приговаривается к смерти любым из возможных способов." }, { 12.98, "Вознаграждение получит тот, кто предоставит в Магистрат доказательства смерти Чок'сула." }, { 19.41, "В последний раз обвиняемого видели в лагере огров в северо-восточной части озера Лок Модан." } } }, t = { d = 20.2, g = 1, v = "dwarf-male", n = { m = 165, f = 166 }, c = { m = { { 0.00, "Ой!" }, { 0.34, "Что это?" }, { 1.18, "И зачем ты притащил её…" }, { 3.37, "Боги!.." }, { 4.13, "Это она?" }, { 5.06, "Ну, разрази меня гром, неужели это голова проклятого огра?" }, { 10.63, "Вот это улов!" }, { 11.98, "Что ж, награда и благодарность от имени всего народа Телсамара достаются тебе по праву!" } }, f = { { 0.00, "Ой!" }, { 0.34, "Что это?" }, { 1.19, "И зачем ты притащила её…" }, { 3.47, "Боги!.." }, { 4.23, "Это она?" }, { 5.17, "Ну, разрази меня гром, неужели это голова проклятого огра?" }, { 10.76, "Вот это улов!" }, { 12.11, "Что ж, награда и благодарность от имени всего народа Телсамара достаются тебе по праву!" } } } } },
    [257] = { d = 30.2, v = "human-male", n = { x = 350 }, c = { x = { { 0.00, "Думаешь тягаться с Дэрилом Смелым?" }, { 2.45, "Не советую!" }, { 3.26, "Разумеется, отговаривать тебя я не буду." }, { 6.09, "Вот испытание, которое тебе явно не по силам." }, { 9.29, "Не огорчайся, если ничего не выйдет." }, { 11.86, "Неподалёку от озера Лок Модан свила гнёзда стая канюков." }, { 15.75, "Почему бы не подстрелить несколько тварей?" }, { 18.70, "Знаешь что, если ты справишься с моим заданием за пятнадцать минут, я отдам тебе свой лук или ружьё." }, { 25.60, "*Он с презрением осматривает вас.*" }, { 28.24, "Всё равно тебе нечего терять." } } }, t = { d = 25.0, v = "human-male", n = { x = 272 }, c = { x = { { 0.00, "Что?" }, { 0.33, "Получилось?!" }, { 1.24, "Послушай добрый совет, пусть успех не кружит тебе голову." }, { 5.48, "Я хочу сказать, любой безусый паренёк с луком справился бы с такими... небольшими существами." }, { 12.20, "Надеюсь, тебе не слишком нравится убивать канюков, м-м-м?" }, { 16.38, "Не хотелось бы, чтобы они стали исчезающим видом." }, { 20.03, "Что ж, э-э-э..." }, { 21.14, "Пусть не говорят, что Дэрил Смелый не держит своё слово." } } } } },
    [258] = { d = 29.9, g = 1, v = "human-male", n = { m = 348, f = 348 }, c = { m = { { 0.00, "Батькович, да?" }, { 0.97, "Вижу, ты лопаешься от гордости за выполненное задание, а?" }, { 4.81, "Я же говорил, что это легко." }, { 6.75, "А вот попробуй поохотиться на кабанов." }, { 9.31, "Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее." }, { 14.48, "На сей раз даю тебе двенадцать минут." }, { 17.03, "Не расстраивайся, если ничего не выйдет." }, { 19.77, "Я тебе рубаху с собственного плеча отдам, если ты справишься!" }, { 23.97, "Я не рассказывал, как получил свой знаменитый шрам?" }, { 27.31, "Нет?" }, { 27.62, "Это было два года назад..." } }, f = { { 0.00, "Батьковна, да?" }, { 0.99, "Вижу, ты лопаешься от гордости за выполненное задание, а?" }, { 4.90, "Я же говорил, что это легко." }, { 6.88, "А вот попробуй поохотиться на кабанов." }, { 9.48, "Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее." }, { 14.75, "На сей раз даю тебе двенадцать минут." }, { 17.36, "Не расстраивайся, если ничего не выйдет." }, { 20.14, "Я тебе рубаху с собственного плеча отдам, если ты справишься!" }, { 24.42, "Я не рассказывал, как получил свой знаменитый шрам?" }, { 27.83, "Нет?" }, { 28.14, "Это было два года назад..." } } }, t = { d = 23.7, g = 1, v = "human-male", n = { m = 237, f = 238 }, c = { m = { { 0.00, "Похоже, тебе несладко пришлось." }, { 2.57, "Видно, кабаны задали тебе изрядную трёпку, да?" }, { 6.28, "Не беспокойся, я никому не расскажу о твоём поражении." }, { 10.49, "Тебе и без досужих болтунов тяжело." }, { 13.34, "О!" }, { 13.56, "Ты умудрился убить кабанов?" }, { 15.77, "Я... что ж... хочу сказать, ничего удивительного!" }, { 19.62, "Любой ребёнок смог бы..." }, { 21.48, "Обещание?" }, { 22.26, "Какое ещё обещание?" } }, f = { { 0.00, "Похоже, тебе несладко пришлось." }, { 2.55, "Видно, кабаны задали тебе изрядную трёпку, да?" }, { 6.24, "Не беспокойся, я никому не расскажу о твоём поражении." }, { 10.42, "Тебе