    [261] = { d = 33.0, v = "human-male", n = { x = 355 }, c = { x = { { 0.00, "Буду откровенен." }, { 1.29, "Мы ведём войну с нечистью." }, { 3.25, "Это зло, уничтожающее наш народ и оскверняющее нашу землю." }, { 7.65, "Нежить нужно остановить, пока это возможно, иначе весь мир погрузится во мрак." }, { 13.55, "Мы поклялись сражаться до последней капли крови, не щадя ни жизни, ни души." }, { 19.24, "Ты с нами?" }, { 20.05, "Тогда яви своё мужество и докажи свою доблесть: убей опустошителей-отрёкшихся, бродящих по Пустошам на юге, в Долине Костей." }, { 29.39, "Сделай это, и братство Алого ордена примет тебя." } } }, t = { d = 13.9, v = "human-male", n = { x = 156 }, c = { x = { { 0.00, "Тебе удалось доказать свою решимость." }, { 2.79, "Братство Алого ордена благодарит тебя." }, { 5.64, "Если тебя не страшит то, что ради правого дела приходится убивать, причём часто и много, тогда тебе с нами по пути." } } } } },
    [262] = { d = 24.0, g = 1, v = "human-male", n = { m = 250, f = 251 }, c = { m = { { 0.00, "Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья!" }, { 5.50, "Прошу тебя, помоги мне." }, { 7.28, "Ты не раз творил настоящие чудеса." }, { 9.80, "Выясни, кто это был." }, { 11.32, "Мне нужно узнать его тайны!" }, { 13.44, "Я рассказал тебе всё, что мог, но возьми эту книгу, обнаруженную на ферме." }, { 18.87, "Может быть, кто-то в городе опознает её, и мы выясним имя владельца?" } }, f = { { 0.00, "Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья!" }, { 5.54, "Прошу тебя, помоги мне." }, { 7.34, "Ты не раз творила настоящие чудеса." }, { 9.94, "Выясни, кто это был." }, { 11.47, "Мне нужно узнать его тайны!" }, { 13.61, "Я рассказал тебе всё, что мог, но возьми эту книгу, обнаруженную на ферме." }, { 19.08, "Может быть, кто-то в городе опознает её, и мы выясним имя владельца?" } } }, t = { d = 17.0, v = "human-female#45", n = { x = 164 }, c = { x = { { 0.00, "Хмм..." }, { 0.51, "Кто-то совсем недавно держал эту книгу в руках." }, { 4.52, "Этот человек одержим жаждой мести." }, { 7.43, "Но увы, следы на ней, по крайней мере следы первого владельца, едва различимы." }, { 13.84, "Я могу сказать одно: он не из Темнолесья." } } } } },
    [263] = { d = 29.8, g = 1, v = "dwarf-male", n = { m = 320, f = 322 }, c = { m = { { 0.00, "Горные пехотинцы уверяют, что ты силён и отважен." }, { 3.46, "Нам нужен путник вроде тебя." }, { 5.57, "Мы никак не можем справиться с троггами." }, { 8.46, "Всех бойцов отозвали на фронт, и мы остались без защиты." }, { 12.37, "Но раз среди нас появился закалённый в боях герой, то может быть, нам удастся выстоять." }, { 18.45, "Убей десять шаманов из племени Камнедробов и десять костегрызов из племени Камнедробов." }, { 24.67, "Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов." } }, f = { { 0.00, "Горные пехотинцы уверяют, что ты сильна и отважна." }, { 3.57, "Нам нужна путница вроде тебя." }, { 5.74, "Мы никак не можем справиться с троггами." }, { 8.61, "Всех бойцов отозвали на фронт, и мы остались без защиты." }, { 12.50, "Но раз среди нас появилась закалённая в боях героиня, то может быть, нам удастся выстоять." }, { 18.75, "Убей десять шаманов из племени Камнедробов и десять костегрызов из племени Камнедробов." }, { 24.93, "Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов." } } }, t = { d = 17.8, g = 1, v = "dwarf-male", n = { m = 196, f = 198 }, c = { m = { { 0.00, "Я сразу понял, что Стальгорн будет тобой гордиться." }, { 3.86, "Ты славно послужил королю Магни." }, { 6.32, "Теперь, доказав, что ты верный защитник Королевства, можешь поговорить с капитаном." }, { 12.45, "Может быть, он посвятит тебя в наши более насущные проблемы." }, { 16.97, "Хвала тебе." } }, f = { { 0.00, "Я сразу понял, что Стальгорн будет тобой гордиться." }, { 3.80, "Ты славно послужила королю Магни." }, { 6.29, "Теперь, доказав, что ты верная защитница Королевства, можешь поговорить с капитаном." }, { 12.38, "Может быть, он посвятит тебя в наши более насущные проблемы." }, { 16.83, "Хвала тебе." } } } } },
    [264] = { d = 44.5, v = "scourge-female", n = { x = 358 }, c = { x = { { 0.00, "Гад такой!" }, { 1.04, "Бросил меня ради своего клятого похода!" }, { 5.05, "Понимаете ли, \"Свет превыше всего, ибо он единственная наша защита от нежити!\"" }, { 12.62, "А как же дети?!" }, { 14.10, "А я?!" }, { 14.62, "Много ночей я терпеливо ждала его... я всегда была второй после его чёртового долга!" }, { 22.98, "И посмотрите, теперь на плоды борьбы за \"справедливость\"!" }, { 28.46, "Он мёртв, а на меня обрушилось всё то, чему он пытался помешать!" }, { 34.55, "Возьмите этот хлам и положите на его могилу в Гробнице." }, { 39.95, "Мне не нужен больше этот мусор... и он сам тоже!" } } }, t = { d = 27.8, v = "narrator", n = { x = 277 }, c = { x = { { 0.00, "Вы кладёте дешёвую безделушку на могилу, и драгоценный камень в ней заметно тускнеет." }, { 6.98, "Когда вы поднимаетесь, чтобы уйти, вы смотрите на подвеску – она лежит, тусклая и мёртвая, в руках вырезанного на надгробной плите изображения." }, { 18.96, "Ваши мысли прерывает порыв холодного ветра, пронёсшегося по Гробнице." }, { 24.81, "На мгновение всё вокруг вас замирает." } } } } },
    [265] = { d = 15.0, v = "human-female#45", n = { x = 174 }, c = { x = { { 0.00, "Вот твоя книга, желаю удачи в расследовании." }, { 3.11, "Если ты расспросишь других горожан, они могут рассказать тебе что-нибудь ценное." }, { 8.76, "Я же скажу одно: хотя автор этой книги не из нашего города, тетрадь для неё он купил здесь." } } }, t = { d = 12.5, v = "human-male", n = { x = 135 }, c = { x = { { 0.00, "Ах, да." }, { 0.53, "Я продал эту тетрадь одному сомнительному типу." }, { 4.14, "Он не представился, но явно нервничал, дёргался, то и дело оглядывался через плечо." }, { 10.22, "Надеюсь, что смог тебе помочь..." } } } } },
    [266] = { d = 11.8, v = "human-male", n = { x = 138 }, c = { x = { { 0.00, "Вот твоя книга, желаю удачи в расследовании." }, { 3.12, "Советую заглянуть в таверну." }, { 5.12, "Если человек, о котором ты говоришь, останавливался у нас в городе, скорее всего его кто-то видел." } } }, t = { d = 24.6, v = "human-male#50", n = { x = 268 }, c = { x = { { 0.00, "Ах да, эту книгу я помню." }, { 1.88, "Её владелец снимал комнату на несколько дней и вечерами засиживался в баре, всё писал." }, { 8.02, "Город он покинул в спешке, бормоча под нос, что его преследует... что-то." }, { 13.27, "В последний раз я видел его на дороге, ведущей на запад." }, { 17.34, "Кажется, он собирался искать новое укрытие." }, { 20.51, "Первое, что ему встретится на западе, – это Вороний холм..." } } } } },
    [267] = { d = 31.4, g = 1, v = "dwarf-male", n = { m = 351, f = 352 }, c = { m = { { 0.00, "Герой, не знаю, слышал ли ты о новой угрозе, нависшей над землями дворфов." }, { 5.19, "Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов." }, { 10.51, "Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов." }, { 17.13, "И всё же необходимо усилить натиск на троггов, заселивших холмы." }, { 21.57, "Если это задание тебе по плечу, проведи вылазку в их стан." }, { 25.70, "Принеси в доказательство своих свершений восемь каменных зубов троггов." } }, f = { { 0.00, "Героиня, не знаю, слышала ли ты о новой угрозе, нависшей над землями дворфов." }, { 5.50, "Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов." }, { 10.93, "Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов." }, { 17.71, "И всё же необходимо усилить натиск на троггов, заселивших холмы." }, { 22.25, "Если это задание тебе по плечу, проведи вылазку в их стан." }, { 26.47, "Принеси в доказательство своих свершений восемь каменных зубов троггов." } } }, t = { d = 10.5, g = 1, v = "dwarf-male", n = { m = 106, f = 107 }, c = { m = { { 0.00, "Отличная работа." }, { 1.39, "Ты оказал всем дворфам великую услугу, защищая наши земли." }, { 6.23, "Сам король Магни Бронзобород может гордиться тобой!" } }, f = { { 0.00, "Отличная работа." }, { 1.40, "Ты оказала всем дворфам великую услугу, защищая наши земли." }, { 6.35, "Сам король Магни Бронзобород может гордиться тобой!" } } } } },
    [268] = { d = 24.5, v = "human-male", n = { x = 300 }, c = { x = { { 0.00, "Я лишь наполовину успел закончить книгу, найденную тобой." }, { 3.91, "Мне пришлось оставить её на ферме Свена во время поспешного бегства…" }, { 8.55, "Вот." }, { 8.86, "Отнеси Свену все мои записи." }, { 10.87, "Здесь подробно рассказывается о случившемся на ферме." }, { 14.42, "Хотя единственным моим сокровищем в последние несколько недель были только эти записи, я охотно расстанусь с ними, лишь бы не вставать на пути Свена!" } } }, t = { d = 13.0, v = "human-male", n = { x = 153 }, c = { x = { { 0.00, "Записи многое проясняют." }, { 1.79, "Теперь мне ясно, что следует искать тёмных всадников!" }, { 5.57, "Я встречал их в Сумеречном лесу и видел, как они говорят с чародеем Морбентом Скверном у Покинутой усадьбы." } } } } },
    [269] = { d = 25.5, v = "human-male", n = { x = 308 }, c = { x = { { 0.00, "Отправляйся в Штормград и поговори с епископом Фартингом в Соборе Света." }, { 4.92, "Отдай ему записи Трясунчика и сообщи, что собираешься бросить вызов Морбенту Скверну." }, { 10.83, "Хоть Штормград и бросил Темнолесье на произвол судьбы, Фартинг – добрая душа и мудрый человек." }, { 17.29, "Он поможет тебе спасти нас." }, { 19.20, "Тебя ждёт много опасностей..." }, { 21.23, "Однако поспеши." }, { 22.34, "С каждым часом в Сумеречном лесу сгущается тьма." } } }, t = { d = 28.5, v = "human-male", n = { x = 341 }, c = { x = { { 0.00, "*Епископ изучает записи...*" }, { 2.56, "Зло нашло лазейку в и без того обложенный со всех сторон Сумеречный лес." }, { 7.35, "Хвала Свету, что отыскался герой вроде тебя." }, { 10.44, "Но прежде чем смело двинуться навстречу испытаниям, тебе следует хорошо подготовиться..." }, { 16.38, "Некромант Морбент Скверн всегда был необычайно силён, а чтобы стать неуязвимым, наложил на себя могучие чары." }, { 23.65, "Тебе не одолеть его без оружия, способного пробиться сквозь эти преграды." } } } } },
    [270] = { d = 38.6, v = "human-male", n = { x = 482 }, c = { x = { { 0.00, "Много лет назад Третья флотилия Кул-Тираса затонула у берегов Болотины, огромной топи к северу от дворфийского королевства Стальгорна." }, { 9.06, "Одно из судов было нагружено светлой сталью." }, { 12.16, "Этот металл представляет для нас большую ценность, поскольку изготовленное из него оружие и доспехи разят врагов силой святой истины." }, { 21.21, "Если вы собираетесь противостоять Морбенту Скверну, вам именно такое оружие и понадобится." }, { 27.29, "Отправляйтесь в Гавань Менетилов и переговорите с моим коллегой-дворфом по имени Глорин Стальной Лоб." }, { 34.10, "Если утерянный груз ещё можно найти – он сообразит, где нужно искать." } } }, t = { d = 23.6, g = 1, v = "dwarf-male", n = { m = 263, f = 265 }, c = { m = { { 0.00, "Светлая сталь – и впрямь драгоценный металл, но всё говорит за то, что задание у тебя не из лёгких." }, { 6.95, "Ты проделал длинный путь, братишка." }, { 9.51, "Если тебе сильно повезёт, ты можешь найти то, что ищешь." }, { 13.64, "А если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь." } }, f = { { 0.00, "Светлая сталь – и впрямь драгоценный металл, но всё говорит за то, что задание у тебя не из лёгких." }, { 6.77, "Ты проделала длинный путь, сестрёнка." }, { 9.32, "Если тебе сильно повезёт, ты можешь найти то, что ищешь." }, { 13.35, "А если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь." } } } } },
    [271] = { d = 35.1, v = "bloodelf-female", n = { x = 394 }, c = { x = { { 0.00, "Не хочешь отплатить Его Смелости?" }, { 2.52, "Вынуждена признать, что Дэрил в самом деле многое умеет." }, { 6.76, "Год назад весь Приют странников охотился на огромного медведя, но ни одному смельчаку не посчастливилось его одолеть." }, { 15.31, "Тогда Дэрил решил выступить против зверя сам." }, { 18.76, "Разумеется, он ничего не добился, да ещё и получил этот уродливый шрам над глазом." }, { 24.73, "Убей медведя, и не сомневаюсь, что даже Дэрил ненадолго лишится дара речи." }, { 30.29, "Старину Черношкура можно отыскать в логове в холмах над Телсамаром." } } }, t = { d = 20.7, v = "human-male", n = { x = 184 }, c = { x = { { 0.00, "Э... что это?" }, { 1.42, "Судя по всему, медвежья голова." }, { 4.72, "*Он невольно проводит пальцем по старому шраму.*" }, { 8.40, "Что ж, интересная добыча." }, { 10.80, "Не тот ли самый медведь..." }, { 13.20, "*Он умолкает и начинает заметно дрожать.*" }, { 16.80, "О, скорее убери её!" }, { 18.29, "Убери отсюда эту страшную штуку!" } } } } },
    [272] = { d = 32.6, v = "nightelf-female#52", n = { x = 403 }, c = { x = { { 0.00, "Вот твоё второе испытание – тебе понадобятся две половинки подвески Морского Льва." }, { 5.50, "Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва." }, { 16.20, "Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика." }, { 21.33, "Поговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить." }, { 29.22, "Сделав это, отнеси подвеску Дендриту Блеску Звёзд." } } }, t = { d = 30.5, g = 1, v = "nightelf-male#54", n = { m = 323, f = 323 }, c = { m = { { 0.00, "Ты прошёл испытание Морского Льва." }, { 2.64, "Прими мои поздравления." }, { 4.57, "Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой." }, { 15.21, "Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва." }, { 23.42, "Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." } }, f = { { 0.00, "Ты прошла испытание Морского Льва." }, { 2.69, "Прими мои поздравления." }, { 4.59, "Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой." }, { 15.12, "Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва." }, { 23.25, "Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." } } } } },
    [273] = { d = 20.0, v = "dwarf-male", n = { x = 229 }, c = { x = { { 0.00, "Ещё не поздно, ты можешь поискать Хальдора." }, { 3.00, "Вряд ли он ушёл далеко; Миран и Сайан – крепкие ребята, но под грузом бочек ходят не слишком быстро." }, { 9.95, "Они пошли к раскопу обычной дорогой – на юг от города, вдоль берега озера." }, { 15.14, "Найти их будет несложно, если они ещё не добрались до места назначения." } } }, t = { d = 17.0, v = "dwarf-male", n = { x = 172 }, c = { x = { { 0.00, "Хм, жалкой засаде Чёрного Железа не помешать мне доставить товар!" }, { 5.05, "Но Сайан..." }, { 5.96, "Никогда бы не подумал, что он сторонник этих предателей." }, { 10.31, "Я с ним почти год работаю... должно быть, что-то упустил." }, { 14.73, "Ладно, подумаю об этом позже." } } } } },
    [274] = { d = 29.2, v = "dwarf-male", n = { x = 329 }, c = { x = { { 0.00, "Это не простой взрывчатый порошок." }, { 2.59, "Только взгляни на эти крошечные серебристые кристаллы." }, { 6.64, "А характерный запах!" }, { 8.17, "Ясно, как день – это сефорий." }, { 10.36, "Сам по себе он безобиден, но, намокнув, может взорвать весь Стальгорн!" }, { 15.47, "Химическую реакцию можно нейтрализовать, смешав четыре компонента: паучий яд, толчёный кристалл Могроша, слезу кроколиска и нейтрализующий коллоид." }, { 26.23, "Расскажи об этом Плотине, пока не поздно!" } } }, t = { d = 4.4, v = "dwarf-male", n = { x = 36 }, c = { x = { { 0.00, "Нейтрализующий коллоид?" }, { 2.43, "Для сефория?" }, { 3.73, "О небо!" } } } } },
    [275] = { d = 23.4, v = "creature/ancient", n = { x = 204 }, c = { x = { { 0.00, "Болотину лихорадит, и я не знаю почему." }, { 3.71, "Трясинные ползуны набирают силу." }, { 6.83, "Это болезненные, гнойные нарывы на теле земли!" }, { 11.30, "И чтобы исцелить её, нужно загнать трясинных ползунов обратно в болота, откуда они вылезли." }, { 19.98, "Ползуны водятся у водоёмов в Болотине." } } }, t = { d = 10.4, v = "creature/ancient", n = { x = 82 }, c = { x = { { 0.00, "Скоро раны на теле земли затянутся, и лихорадка спадёт." }, { 5.71, "Я благодарю тебя и вручаю небольшой подарок..." } } } } },
    [276] = { d = 35.4, v = "creature/ancient", n = { x = 320 }, c = { x = { { 0.00, "Многие годы гноллы из стаи Мохошкуров мирно жили в Болотине, но теперь их поголовье увеличилось." }, { 8.52, "Они вытаптывают наши прекрасные луга и вырубают лес на дрова!" }, { 13.97, "Чтобы спасти природу нашего края, придётся истребить часть гноллов." }, { 19.89, "Убей пятнадцать гноллов из стаи Мохошкуров и десять полукровок из стаи Мохошкуров." }, { 27.15, "Они водятся на юге, возле дворфийских Врат Альгаза." }, { 31.73, "Когда справишься с заданием, вернись ко мне." } } }, t = { d = 14.7, g = 1, v = "creature/ancient", n = { x = 116 }, c = { m = { { 0.00, "Теперь наши земли спасены!" }, { 2.60, "Признаться, раньше я с недоверием относился к вашему брату... но твой подвиг, герой, заставил меня задуматься." }, { 12.82, "Спасибо тебе!" } }, f = { { 0.00, "Теперь наши земли спасены!" }, { 2.70, "Признаться, раньше я с недоверием относился к вашему брату... но твой подвиг, героиня, заставил меня задуматься." }, { 13.49, "Спасибо тебе!" } } } } },
    [277] = { d = 20.9, v = "creature/ancient", n = { x = 201 }, c = { x = { { 0.00, "Гноллы из стаи Мохошкуров вырубают деревья Болотины и жгут древесину, греясь у костров." }, { 7.45, "Я этого не потерплю!" }, { 9.21, "Отбери у гноллов их кремни, которыми они высекают огонь." }, { 14.13, "Кремни есть у всего клана, кроме мелких гноллов и полукровок из стаи Мохошкуров." } } }, t = { d = 12.6, v = "creature/ancient", n = { x = 99 }, c = { x = { { 0.00, "Спасибо." }, { 0.93, "Я раскрошу их в порошок и выброшу в море, и их уже никогда не используют для того, чтобы жечь живую древесную плоть." } } } } },
    [278] = { d = 29.8, v = "dwarf-male", n = { x = 360 }, c = { x = { { 0.00, "Немедленно принимайся за сбор материалов для нейтрализации взрывчатки." }, { 4.77, "Паучий яд ты найдёшь у пауков у озера Лок Модан." }, { 8.10, "Слезу кроколиска можно отыскать там же." }, { 10.87, "А вот заполучить кристалл Могроша будет нелегко." }, { 14.26, "Такие кристаллы добывают огры, живущие к северо-востоку отсюда, но и у огров они водятся нечасто." }, { 21.17, "Мы должны разминировать творение Чёрного Железа!" }, { 24.50, "Как только соберёшь все материалы, сразу же возвращайся, и я подготовлю состав." } } }, t = { d = 1.6, v = "dwarf-male", n = { x = 9 }, c = { x = { { 0.00, "Наконец-то!" } } } } },
    [279] = { d = 39.5, v = "human-male", n = { x = 476 }, c = { x = { { 0.00, "Мурлоки выходят из морских глубин и строят свои поселения на побережье." }, { 4.87, "Они нападают на наших рыбаков и торговцев, и это уже переходит всякие границы." }, { 10.28, "Их надо остановить." }, { 11.62, "Один из этих мурлоков, Жрун, придумал устраивать засады на наших купцов на дорогах." }, { 17.28, "На мурлоков из племени Синежабрых нет никакой управы." }, { 20.86, "Творят, что хотят, а потом прячутся в ближайших поселениях, и всё – их уже не достать." }, { 26.64, "Наши торговцы в опасности, и мы готовы хорошо заплатить тому, кто возьмётся их защищать." }, { 32.54, "Жрун промышляет в речном заливе к северу отсюда." }, { 35.83, "Принеси мне его голову, а заодно перебей его сородичей." } } }, t = { d = 6.0, g = 1, v = "human-male", n = { m = 63, f = 64 }, c = { m = { { 0.00, "Отлично!" }, { 0.70, "Вот твои деньги, ты честно их заработал, выполнив все обязательства." } }, f = { { 0.00, "Отлично!" }, { 0.72, "Вот твои деньги, ты честно их заработала, выполнив все обязательства." } } } } },
    [280] = { d = 26.8, v = "dwarf-male", n = { x = 320 }, c = { x = { { 0.00, "Я только сегодня видел мятежников Чёрного Железа, которые тащили к Дамбе большую бочку." }, { 5.96, "И рядом со мной не было ни одного горного пехотинца, поэтому никто их не остановил!" }, { 11.55, "Боюсь, они заложили сефорий у основания Дамбы, и она того и гляди взлетит на воздух!" }, { 17.39, "Дай-ка я смешаю все компоненты." }, { 19.52, "Вот, у меня получилась нейтрализующая смесь." }, { 22.44, "Скорее, возьми смесь и залей её в бочку, пока не поздно." }, { 26.27, "Торопись!" } } }, t = { d = 5.8, v = "narrator", n = { x = 59 }, c = { x = { { 0.00, "Вы вливаете нейтрализующую смесь, и из бочки доносится слабое шипение." } } } } },
    [281] = { d = 28.4, v = "human-male", n = { x = 321 }, c = { x = { { 0.00, "Не так давно мурлоки напали на торговый корабль \"Слепая принцесса\"." }, { 4.83, "Корабль удалось спасти, но эти подлые твари растащили почти весь груз, в том числе и одну очень ценную вещь, статуэтку Теренаса Менетила." }, { 14.69, "Её надо вернуть во что бы то ни стало." }, { 17.40, "Обыщи поселение мурлоков на побережье." }, { 20.17, "Ищи сундуки, ящики, бочки – всё, что может быть связано с украденным грузом." }, { 25.64, "Найди статуэтку Менетила и верни её мне." } } }, t = { d = 23.8, v = "narrator", n = { x = 228 }, c = { x = { { 0.00, "Сундук отсырел, он весь исцарапан – это явно следы от когтей." }, { 5.31, "Вы открываете сундук." }, { 7.15, "Внутри – размокшая гнилая солома." }, { 10.08, "Можно предположить, что здесь спрятана некая ценная вещь, требующая бережного обращения." }, { 17.54, "Вы разгребаете солому..." }, { 19.61, "...и находите несколько бутылок из красного стекла." } } } } },
    [282] = { d = 37.0, v = "dwarf-male", n = { x = 431 }, c = { x = { { 0.00, "Я собирался послать своего ученика к брату Сениру с отчётом, но парень он не слишком надёжный, а мне нужен кто-то, на кого действительно можно положиться." }, { 10.54, "Ну, то есть, конечно, если ты не будешь возражать." }, { 13.97, "Хм-м." }, { 14.34, "Чтобы добраться до Караноса, тебе придётся пройти по тоннелю." }, { 18.58, "Перед тем как зайти в тоннель, заскочи к горному пехотинцу Талосу и поговори с ним – в тоннеле полным-полно троггов." }, { 26.63, "Сначала тебе нужно вернуться по дороге к Старой Наковальне, а потом направиться на восток." }, { 32.92, "Рядом с тоннелем Талос и стоит – найти его будет несложно." } } }, t = { d = 12.2, v = "dwarf-male", n = { x = 122 }, c = { x = { { 0.00, "Хм." }, { 0.28, "Ну что ж, если Белобород послал тебя в Дун Морог по важному делу, то не мне тебя останавливать, верно?" }, { 8.19, "С другой стороны, пару советов-то я могу тебе дать..." } } } } },
    [283] = { d = 2.3, v = "narrator", n = { x = 18 }, c = { x = { { 0.00, "Бочка негромко шипит." } } }, t = { d = 19.3, g = 1, v = "dwarf-male", n = { m = 194, f = 196 }, c = { m = { { 0.00, "Огромное спасибо!" }, { 1.41, "Ты спас Каменную дамбу." }, { 3.24, "Без твоей помощи террористы Чёрного Железа непременно разрушили бы это знаменитое сооружение." }, { 10.50, "Королевство и Альянс гордятся тобой, отважный герой!" }, { 14.65, "Дамба снова в безопасности... по крайней мере, пока..." } }, f = { { 0.00, "Огромное спасибо!" }, { 1.42, "Ты спасла Каменную дамбу." }, { 3.47, "Без твоей помощи террористы Чёрного Железа непременно разрушили бы это знаменитое сооружение." }, { 10.78, "Королевство и Альянс гордятся тобой, отважная героиня!" }, { 15.11, "Дамба снова в безопасности... по крайней мере, пока..." } } } } },
    [284] = { d = 12.9, v = "narrator", n = { x = 144 }, c = { x = { { 0.00, "Вы обыскиваете всё поселение мурлоков в этом районе, но статуэтки Менетила здесь нет." }, { 6.34, "Может быть, стоит проверить ближайшие несколько жилищ к северу и северо-востоку отсюда?" } } }, t = { d = 11.0, v = "narrator", n = { x = 96 }, c = { x = { { 0.00, "Эту бочку, похоже, никто не трогал." }, { 3.30, "Вы открываете её..." }, { 5.00, "Запах валит вас с ног." }, { 7.01, "Сыр слегка заплесневел, но он вполне съедобен!" } } } } },
    [285] = { d = 14.6, v = "narrator", n = { x = 140 }, c = { x = { { 0.00, "Вы обыскиваете ещё несколько жилищ мурлоков." }, { 3.70, "Вот досада – опять ничего!" }, { 5.96, "...Но вы уверены, что всё получится." }, { 8.90, "Статуэтка Менетила наверняка где-то здесь, в одном из жилищ к северу." } } }, t = { d = 4.2, v = "narrator", n = { x = 41 }, c = { x = { { 0.00, "Бочка наполовину утоплена в грязи и мокрой траве..." } } } } },
    [286] = { d = 22.1, v = "narrator", n = { x = 228 }, c = { x = { { 0.00, "Вы достаёте бочку из грязи, открываете её и видите серебряную статуэтку, укрытую соломой." }, { 7.19, "Фигурка изображает юного длинноволосого паладина с воздетым над головою молотом." }, { 13.72, "Это, должно быть, и есть статуэтка Менетила!" }, { 17.32, "Теперь вам надо вернуть её Карлу Борану в Гавань Менетилов." } } }, t = { d = 20.5, g = 1, v = "human-male", n = { m = 240, f = 241 }, c = { m = { { 0.00, "Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз." }, { 6.65, "Ты сослужил нам хорошую службу и получишь обещанную награду." }, { 10.77, "Радостно сознавать, что в этом мире ещё есть надёжные люди, на которых можно положиться, и особенно – в такое тяжёлое и неспокойное время." } }, f = { { 0.00, "Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз." }, { 6.81, "Ты сослужила нам хорошую службу и получишь обещанную награду." }, { 11.10, "Радостно сознавать, что в этом мире ещё есть надёжные люди, на которых можно положиться, и особенно – в такое тяжёлое и неспокойное время." } } } } },
    [287] = { d = 34.3, v = "dwarf-male", n = { x = 401 }, c = { x = { { 0.00, "Я не успеваю с донесением, и твоя помощь, мне бы пригодилась." }, { 4.25, "Я сумел узнать, где засели тролли, но их там было столько, что я побоялся лезть туда." }, { 10.22, "Вот что мне нужно..." }, { 11.61, "Спустись в пещеру, порыскай там, прибей пару-другую троллей и возвращайся ко мне." }, { 17.33, "Отправляйся из Караноса по северной дороге." }, { 20.37, "Когда перейдёшь через мост, следуй на запад по замёрзшей реке, пока не доберёшься до Заледеневшего озера." }, { 27.61, "На западном берегу обнаружишь Посёлок Пивоваров." }, { 30.97, "Форт Мерзлогривов находится к юго-западу от него." } } }, t = { d = 20.5, v = "dwarf-male", n = { x = 206 }, c = { x = { { 0.00, "А!" }, { 0.20, "Я так и думал, что тебе будет несложно найти это место, ведь мои указания были предельно чётки..." }, { 7.49, "Дай-ка мне закончить донесение." }, { 9.76, "*Он приносит бумагу и что-то быстро на ней пишет.*" }, { 13.68, "Вот!" }, { 14.04, "Ха-ха, теперь это совсем забавно..." }, { 17.01, "Думаю, ты не откажешься помочь мне ещё разок?" } } } } },
    [288] = { d = 31.8, v = "human-male#50", n = { x = 356 }, c = { x = { { 0.00, "Когда-то я был первым помощником на \"Владычице\", линейном корабле кул-тирасской Третьей флотилии." }, { 6.98, "Обречённой флотилии..." }, { 8.55, "Во время последнего плавания на нас напали красные драконы." }, { 12.85, "А ими правили орки!" }, { 14.35, "У нас не было ни единого шанса спастись от драконьего огня, и все корабли были сожжены и потоплены у побережья." }, { 22.38, "Я один уцелел в этом кошмаре." }, { 24.60, "Ох, как же раскалывается голова!" }, { 26.88, "Погоди, сейчас я выпью чего-нибудь, немного приду в себя и продолжу." } } }, t = { d = 5.4, v = "human-male#50", n = { x = 47 }, c = { x = { { 0.00, "Вот!" }, { 0.41, "И голова не болит, и язык развязался." }, { 3.82, "Спасибо, приятель!" } } } } },
    [289] = { d = 37.0, v = "human-male#50", n = { x = 438 }, c = { x = { { 0.00, "*Приободрившись, Фитсиммонс продолжает рассказывать...*" }, { 3.84, "Я единственный уцелевший из всех матросов злополучной Кул-Тирасской Третьей флотилии, погибшей у северного побережья." }, { 11.97, "И хотя я последний из команды, чьё сердце бьётся и кто ещё дышит, я не единственный, кто ещё бродит по земле!" }, { 19.46, "На одном из наших кораблей хранилось великое, ужасное сокровище, и его потусторонняя зловещая сила держит души моих собратьев и не даёт им покинуть гниющие остовы кораблей." }, { 31.64, "Если ты сможешь их освободить, тогда, может быть, они избавятся от проклятия." } } }, t = { d = 4.6, v = "human-male#50", n = { x = 55 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.18, "И прими благодарность моих несчастных собратьев." } } } } },
    [290] = { d = 34.7, v = "human-male#50", n = { x = 387 }, c = { x = { { 0.00, "Чтобы избавиться от проклятия и освободить моих верных товарищей, нужно найти и очистить эту... проклятую штуковину... спрятанную на моём корабле!" }, { 10.42, "Не знаю, что это такое, знаю только, что эта штука хранится в корабельном сейфе, а ключ от сейфа – у капитана Халиндора." }, { 19.04, "Старина капитан снится мне до сих пор." }, { 21.74, "Я знаю, он сейчас на \"Отважном\" – нашем несчастном корабле." }, { 25.99, "Постарайся добыть ключ от сейфа, открой его и возьми эту вещь." }, { 30.49, "Потом отнеси её в город и отдай жрецу Глорину Стальному Лбу." } } }, t = { d = 4.5, v = "narrator", n = { x = 44 }, c = { x = { { 0.00, "Ключ насквозь проржавел, но замок открылся без труда." } } } } },
    [291] = { d = 33.3, g = 1, v = "dwarf-male", n = { m = 380, f = 382 }, c = { m = { { 0.00, "Замечательно!" }, { 0.94, "Отнеси моё донесение сенатору Бэрину Краснокамню." }, { 4.37, "Он мрачный тип, постарайся не заразиться от него унынием." }, { 8.30, "Ты найдёшь его в Стальгорне, в палате, где король Магни вершит суд." }, { 12.92, "Что?" }, { 13.23, "Не знаешь дороги в Стальгорн?" }, { 15.29, "От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы." }, { 24.22, "Кстати, будь добр, не говори о том, как ты мне помогал." }, { 27.90, "Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица." } }, f = { { 0.00, "Замечательно!" }, { 0.94, "Отнеси моё донесение сенатору Бэрину Краснокамню." }, { 4.40, "Он мрачный тип, постарайся не заразиться от него унынием." }, { 8.36, "Ты найдёшь его в Стальгорне, в палате, где король Магни вершит суд." }, { 13.00, "Что?" }, { 13.32, "Не знаешь дороги в Стальгорн?" }, { 15.39, "От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы." }, { 24.38, "Кстати, будь добра, не говори о том, как ты мне помогала." }, { 28.27, "Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица." } } }, t = { d = 18.9, v = "dwarf-male", n = { x = 191 }, c = { x = { { 0.00, "*Он быстро просматривает донесение.*" }, { 2.64, "По приказу КОРОЛЯ!?" }, { 4.19, "Магни совсем спятил!" }, { 5.89, "И ещё этот проклятый Белобород..." }, { 8.50, "Значит, взял дела в свои руки?" }, { 10.98, "Сенат этому не обрадуется, вовсе не обрадуется." }, { 14.72, "Что, ты ещё здесь?" }, { 16.06, "Иди отсюда, пока я охрану не вызвал!" } } } } },
    [292] = { d = 23.4, v = "narrator", n = { x = 223 }, c = { x = { { 0.00, "Внутри сундука лежит тёмный шар, источающий зловещее свечение." }, { 5.48, "Это и есть то сокровище, о котором говорил Фитсиммонс: проклятое Око Палета." }, { 12.24, "Отнесите проклятое Око Палета дворфийскому жрецу Глорину Стальному Лбу в Гавань Менетилов." }, { 20.26, "Попросите его снять проклятие с Ока." } } }, t = { d = 21.5, g = 1, v = "dwarf-male", n = { m = 221, f = 221 }, c = { m = { { 0.00, "Око Палета?" }, { 0.96, "Поразительно!" }, { 1.98, "Хмм... с ним явно что-то не так." }, { 4.37, "Говоришь, ты нашёл его среди обломков судна?" }, { 7.79, "Это многое объясняет!" }, { 9.50, "Но как же Око попало на корабль Третьей флотилии?.." }, { 13.39, "Неудивительно, что этот Фитсиммонс так перепугался." }, { 17.21, "Проклятое Око Палета кого угодно выбьет из колеи." } }, f = { { 0.00, "Око Палета?" }, { 0.98, "Поразительно!" }, { 2.03, "Хмм... с ним явно что-то не так." }, { 4.47, "Говоришь, ты нашла его среди обломков судна?" }, { 8.04, "Это многое объясняет!" }, { 9.79, "Но как же Око попало на корабль Третьей флотилии?.." }, { 13.77, "Неудивительно, что этот Фитсиммонс так перепугался." }, { 17.69, "Проклятое Око Палета кого угодно выбьет из колеи." } } } } },
    [293] = { d = 21.2, v = "dwarf-male", n = { x = 228 }, c = { x = { { 0.00, "Я не могу снять проклятие с Ока Палета." }, { 3.01, "Это людское творение, и поэтому тебе следует направиться в Штормград." }, { 8.35, "Найди того, кто сумеет тебе помочь." }, { 11.15, "Обратись к архиепископу Бенедикту." }, { 13.75, "Он главный в Соборе Света Штормграда, и сможет дать тебе наставления." }, { 19.02, "Надеюсь, у тебя всё получится." } } }, t = { d = 23.7, v = "human-male#170", n = { x = 214 }, c = { x = { { 0.00, "Это Око Палета." }, { 1.50, "Определённо, оно видело много скорбей и печалей... может быть, стало свидетелем некоей ужасной, поистине ужасной трагедии." }, { 12.24, "Сейчас я очищу его, ибо Очи созданы для того, чтобы сиять ярким светом, и их сила становится опасной, если они запятнаны порчей." } } } } },
    [294] = { d = 28.2, v = "dwarf-male", n = { x = 314 }, c = { x = { { 0.00, "Придётся признать, что положение отчаянное." }, { 3.07, "Когда мы раскопали эти кости, ящеры немедленно атаковали нас." }, { 7.58, "Многие из братьев были разорваны на месте, а мы с Меррин и бедолагой геологом оказались в ловушке здесь, наверху." }, { 15.75, "Помоги очистить Болотину от ящеров." }, { 18.37, "Крапчатые ящеры и крапчатые крикуны водятся к западу от этого утёса." }, { 23.34, "Убей по десять тварей каждого вида." }, { 26.02, "Это будет началом моей мести." } } }, t = { d = 10.4, v = "dwarf-male", n = { x = 111 }, c = { x = { { 0.00, "Я понимаю, что убийство – грязная и опасная работа." }, { 3.80, "Но если бы я не поклялся остаться рядом с геологом и Меррин, я бы и сам отправился с тобой." } } } } },
    [295] = { d = 10.5, v = "dwarf-male", n = { x = 109 }, c = { x = { { 0.00, "Пора нанести им сокрушительный удар." }, { 2.85, "Внизу бродят стаи крапчатых смертехватов и крапчатых острозубов." }, { 7.85, "Убей по десять гадов каждого вида!" } } }, t = { d = 3.3, g = 1, v = "dwarf-male", n = { m = 30, f = 32 }, c = { m = { { 0.00, "Ты не представляешь, как ты мне помог!" } }, f = { { 0.00, "Ты не представляешь, как ты мне помогла!" } } } } },
    [296] = { d = 33.8, v = "dwarf-male", n = { x = 372 }, c = { x = { { 0.00, "Пока тебя не было, я заметил, что среди этих тварей есть один выдающийся экземпляр." }, { 6.29, "Он крупнее остальных и отличается особой свирепостью." }, { 10.23, "Могу поклясться, что он – их вожак, это он привёл их сюда и подначил разорить шахту." }, { 16.45, "Сослужи мне последнюю службу." }, { 18.66, "Зарлозуба надо предать правосудию." }, { 21.27, "А если принять во внимание тяжесть его преступлений, правосудие здесь может быть только одно: смерть на месте!" }, { 29.43, "Убей его и в доказательство принеси мне один из его когтей." } } }, t = { d = 21.7, g = 1, v = "dwarf-male", n = { m = 239, f = 241 }, c = { m = { { 0.00, "Спасибо." }, { 0.67, "Мы не забудем того, что ты сделал для нас." }, { 3.73, "Сколько ни в чём не повинных дворфов полегло в этой злосчастной шахте – а ведь они просто трудились на своих местах." }, { 12.31, "Но ты отомстил за наших безвинно погибших братьев, и теперь ящеры дважды подумают, прежде чем нападать на владения короля Магни." } }, f = { { 0.00, "Спасибо." }, { 0.66, "Мы не забудем того, что ты сделала для нас." }, { 3.77, "Сколько ни в чём не повинных дворфов полегло в этой злосчастной шахте – а ведь они просто трудились на своих местах." }, { 12.30, "Но ты отомстила за наших безвинно погибших братьев, и теперь ящеры дважды подумают, прежде чем нападать на владения короля Магни." } } } } },
    [297] = { d = 27.2, v = "dwarf-male", n = { x = 312 }, c = { x = { { 0.00, "Незадолго до появления в раскопе троггов мы обнаружили множество странных резных идолов." }, { 6.34, "Изучить их мы не успели, потому что вскоре после этого трогги вытеснили нас из развалин!" }, { 12.67, "А идолы оказывают на этих тварей странное воздействие – превращают их в берсерков!" }, { 18.55, "Отбей идолов у троггов и принеси мне – я хочу их изучить." }, { 22.69, "Идолов ты найдёшь у троггов – а их в раскопе более чем достаточно." } } }, t = { d = 11.9, g = 1, v = "dwarf-male", n = { m = 121, f = 123 }, c = { m = { { 0.00, "Ты добыл их!" }, { 0.96, "Хвалю!" }, { 1.50, "И хотя там полно троггов-берсерков, ты, кажется, не сильно пострадал." }, { 6.76, "Я буду с интересом следить за твоей судьбой..." }, { 10.31, "Ты подаёшь надежды." } }, f = { { 0.00, "Ты добыла их!" }, { 1.04, "Хвалю!" }, { 1.60, "И хотя там полно троггов-берсерков, ты, кажется, не сильно пострадала." }, { 7.01, "Я буду с интересом следить за твоей судьбой..." }, { 10.61, "Ты подаёшь надежды." } } } } },
    [298] = { d = 15.6, v = "dwarf-male", n = { x = 173 }, c = { x = { { 0.00, "Мне нужно отправить в Телсамар отчёт о ходе работ и запрос на получение нового груза пороха!" }, { 6.96, "Вот мой отчёт." }, { 7.98, "Отнеси его Джерну Шлеморогу, он наш представитель в Телсамаре." }, { 12.64, "Задание не сложное, но достаточно важное." } } }, t = { d = 20.2, v = "dwarf-male", n = { x = 205 }, c = { x = { { 0.00, "Ха!" }, { 0.28, "У Железняка проблемы с троггами." }, { 2.82, "Интересно, порох ему нужен для продолжения раскопок или для войны с этими тварями..." }, { 9.52, "Так или иначе, он будет потрачен не зря!" }, { 12.69, "Но вот что странно, несколько недель назад я послал ему немало пороха." }, { 18.27, "Интересно, куда он делся." } } } } },
    [299] = { d = 45.0, g = 1, v = "dwarf-male", n = { m = 474, f = 475 }, c = { m = { { 0.00, "Перед самым вторжением я обнаружил скрижаль с письменами, именуемую скрижалью Гоаз." }, { 6.41, "Несколько кусков отломилось, и в четырёх местах текст обрывается." }, { 11.31, "Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\"." }, { 16.41, "Боюсь, у нас мало времени." }, { 18.48, "Я уже слишком стар, чтобы сражаться с этими тварями в раскопе." }, { 23.31, "Но ты молод и полон сил." }, { 25.17, "Обыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру." }, { 31.72, "Ищи среди древних артефактов или там, где почва разрыхлена." }, { 36.34, "Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!" } }, f = { { 0.00, "Перед самым вторжением я обнаружил скрижаль с письменами, именуемую скрижалью Гоаз." }, { 6.41, "Несколько кусков отломилось, и в четырёх местах текст обрывается." }, { 11.31, "Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\"." }, { 16.42, "Боюсь, у нас мало времени." }, { 18.49, "Я уже слишком стар, чтобы сражаться с этими тварями в раскопе." }, { 23.31, "Но ты молода и полна сил." }, { 25.24, "Обыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру." }, { 31.80, "Ищи среди древних артефактов или там, где почва разрыхлена." }, { 36.42, "Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!" } } }, t = { d = 20.6, g = 1, v = "dwarf-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Итак, скрижаль Гоаз восстановлена!" }, { 2.93, "Ты хорошо потрудился." }, { 4.73, "Будем надеяться, теперь я сумею расшифровать письмена титанов." }, { 9.98, "Я уже разбираю новые слова!" }, { 12.38, "Э... тут написано: \"Древние боги... томятся в цепях под землёй\"." }, { 17.64, "Похоже, грядут грандиозные перемены." } }, f = { { 0.00, "Итак, скрижаль Гоаз восстановлена!" }, { 2.88, "Ты хорошо потрудилась." }, { 4.73, "Будем надеяться, теперь я сумею расшифровать письмена титанов." }, { 9.90, "Я уже разбираю новые слова!" }, { 12.27, "Э... тут написано: \"Древние боги... томятся в цепях под землёй\"." }, { 17.44, "Похоже, грядут грандиозные перемены." } } } } },
    [301] = { d = 26.7, v = "dwarf-male", n = { x = 325 }, c = { x = { { 0.00, "Мы не можем выдать Сталекруту новую партию взрывчатого порошка без одобрения Стальгорна." }, { 6.09, "Тебе придётся отнести его отчёт в штаб-квартиру Лиги Исследователей." }, { 10.76, "Вот он." }, { 11.25, "Отдай его геологу Грозовой Вершине, да не забудь сразу отскочить в сторону." }, { 16.54, "Грозовая Вершина – горячая голова." }, { 18.97, "Его совсем не порадуют новости о медленном продвижении работ." }, { 23.26, "Грозовую Вершину можно найти в Зале исследователей." } } }, t = { d = 11.3, v = "dwarf-male", n = { x = 110 }, c = { x = { { 0.00, "Проклятый Железняк!" }, { 1.61, "Я послал ему целый воз пороха ещё неделю назад, но он не потрудился упомянуть об этом в отчёте." }, { 9.31, "Так... куда делся порох?!" } } } } },
    [302] = { d = 25.5, g = 1, v = "dwarf-male", n = { m = 292, f = 293 }, c = { m = { { 0.00, "Если Сталекруту нужен порох, то, именем короля Магни, он его получит!" }, { 5.08, "Я уже отправил вестника в Телсамар с соответствующим приказом Джерну Шлеморогу." }, { 10.74, "Он подготовит груз пороха и прочих припасов для Сталекрута." }, { 14.92, "И ещё одно: я хочу, чтобы ты лично проследил за доставкой груза." }, { 19.55, "Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба." } }, f = { { 0.00, "Если Сталекруту нужен порох, то, именем короля Магни, он его получит!" }, { 5.04, "Я уже отправил вестника в Телсамар с соответствующим приказом Джерну Шлеморогу." }, { 10.65, "Он подготовит груз пороха и прочих припасов для Сталекрута." }, { 14.79, "И ещё одно: я хочу, чтобы ты лично проследила за доставкой груза." }, { 19.45, "Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба." } } }, t = { d = 18.0, g = 1, v = "dwarf-male", n = { m = 186, f = 187 }, c = { m = { { 0.00, "Что?" }, { 0.33, "Грозовая Вершина хочет, чтобы ты лично проследил за доставкой груза к Железняку?" }, { 6.36, "Я... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли." }, { 13.66, "Вы чуть-чуть разминулись, я отправил их совсем недавно." } }, f = { { 0.00, "Что?" }, { 0.34, "Грозовая Вершина хочет, чтобы ты лично проследила за доставкой груза к Железняку?" }, { 6.55, "Я... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли." }, { 13.99, "Вы чуть-чуть разминулись, я отправил их совсем недавно." } } } } },
    [303] = { d = 38.1, v = "dwarf-male", n = { x = 419 }, c = { x = { { 0.00, "Война свирепствует повсюду: и в наших краях, и в чужих землях тоже." }, { 4.87, "Пока наши могучие воины не щадят своих жизней, сражаясь во имя Альянса вдали от дома, на наших собственных землях бесчинствуют дворфы Чёрного Железа." }, { 15.62, "Они разрушили один из мостов Тандола, потом пал и Дун Модр." }, { 19.85, "Тебе нужно собрать добровольцев и сдержать натиск врагов." }, { 24.01, "Если сумеешь убить пятнадцать дворфов Чёрного Железа, пять проходчиков, пять саботажников и пять подрывников, тогда, может быть, мы и продержимся до подхода подкрепления." }, { 35.86, "И поторопись!" }, { 36.82, "У нас мало времени." } } }, t = { d = 19.7, g = 1, v = "dwarf-male", n = { m = 203, f = 205 }, c = { m = { { 0.00, "Ты всё сделал как надо, герой." }, { 2.27, "Ты доказал свою доблесть и преданность королю Магни, за что тебе честь и хвала!" }, { 8.15, "Боевой дух Чёрного Железа подорван, и у нас появилась возможность выгнать их с нашей земли навсегда... если этот треклятый резерв всё-таки подойдёт..." } }, f = { { 0.00, "Ты всё сделала как надо, героиня." }, { 2.53, "Ты доказала свою доблесть и преданность королю Магни, за что тебе честь и хвала!" }, { 8.62, "Боевой дух Чёрного Железа подорван, и у нас появилась возможность выгнать их с нашей земли навсегда... если этот треклятый резерв всё-таки подойдёт..." } } } } },
    [304] = { d = 38.4, g = 1, v = "dwarf-male", n = { x = 405 }, c = { m = { { 0.00, "Сколько наших полегло в битве при Дун Модре!" }, { 3.31, "Мой родной брат погиб, когда обрушился западный мост Тандола." }, { 7.82, "Да, дворфы Чёрного Железа – те ещё бестии." }, { 10.87, "Чёртово племя, шайка головорезов." }, { 13.32, "Рогго сумел разузнать, что их предводитель в Болотине – некий чернокнижник по имени Балгарас Нечистый." }, { 20.81, "Трус и мерзавец, каких поискать." }, { 23.19, "Посылает на битву своих солдат, а сам прячется у себя в лагере на Зловещем холме, к юго-востоку отсюда." }, { 30.81, "Разыщи этого подлого слизняка, убей его, принеси мне его ухо, и получишь награду, герой." } }, f = { { 0.00, "Сколько наших полегло в битве при Дун Модре!" }, { 3.39, "Мой родной брат погиб, когда обрушился западный мост Тандола." }, { 8.01, "Да, дворфы Чёрного Железа – те ещё бестии." }, { 11.13, "Чёртово племя, шайка головорезов." }, { 13.64, "Рогго сумел разузнать, что их предводитель в Болотине – некий чернокнижник по имени Балгарас Нечистый." }, { 21.31, "Трус и мерзавец, каких поискать." }, { 23.75, "Посылает на битву своих солдат, а сам прячется у себя в лагере на Зловещем холме, к юго-востоку отсюда." }, { 31.56, "Разыщи этого подлого слизняка, убей его, принеси мне его ухо, и получишь награду, героиня." } } }, t = { d = 26.1, g = 1, v = "dwarf-male", n = { m = 284, f = 285 }, c = { m = { { 0.00, "Ну, вот и всё." }, { 0.99, "Балгарас Нечистый мёртв." }, { 2.78, "И хотя смерть мерзавца не воскресит наших безвинно погибших братьев, тем, кто уцелел, будет гораздо спокойнее." }, { 10.84, "Теперь, когда Балгараса нет, мы без труда справимся с Чёрным Железом." }, { 15.87, "Хотя надо поторопиться." }, { 17.65, "Истребить этих гадов под корень, пока у них не появился новый предводитель!" }, { 23.21, "Ты сослужил нам добрую службу, герой." } }, f = { { 0.00, "Ну, вот и всё." }, { 0.99, "Балгарас Нечистый мёртв." }, { 2.78, "И хотя смерть мерзавца не воскресит наших безвинно погибших братьев, тем, кто уцелел, будет гораздо спокойнее." }, { 10.86, "Теперь, когда Балгараса нет, мы без труда справимся с Чёрным Железом." }, { 15.89, "Хотя надо поторопиться." }, { 17.68, "Истребить этих гадов под корень, пока у них не появился новый предводитель!" }, { 23.25, "Ты сослужила нам добрую службу, героиня." } } } } },
    [305] = { d = 33.0, v = "dwarf-male", n = { x = 382 }, c = { x = { { 0.00, "Знаешь... как-то мне неспокойно на сердце." }, { 2.97, "Моя благоверная Меррин работает в изыскательской группе на раскопе Вельгара." }, { 8.35, "Писала мне каждую неделю весь прошлый месяц." }, { 11.52, "А теперь вдруг пропала." }, { 13.17, "Уже две недели ни слуху, ни духу." }, { 15.57, "Наверняка что-то случилось!" }, { 17.53, "Длинная Коса обещал, что, если я вскорости не получу никаких известий, он пришлёт мне разведчика, который проверит, что стало с экспедицией." }, { 27.28, "Как я понимаю, ты и есть этот разведчик." }, { 30.07, "Разыщи Меррин на раскопе к востоку отсюда!" } } }, t = { d = 3.0, g = 1, v = "dwarf-female#33", n = { m = 20, f = 20 }, c = { m = { { 0.00, "Слава богам, ты нас нашёл!" } }, f = { { 0.00, "Слава богам, ты нас нашла!" } } } } },
    [306] = { d = 41.6, v = "dwarf-female#33", n = { x = 453 }, c = { x = { { 0.00, "Это было ужасно!" }, { 1.34, "Мы обнаружили несколько очень редких артефактов." }, { 4.94, "Пока мы занимались раскопками, нам всё чаще и чаще начали попадаться огромные кости." }, { 11.22, "Всё случилось внезапно." }, { 12.96, "На нас напали крапчатые ящеры, их было значительно больше, чем нас." }, { 17.90, "Почти все наши погибли в неравной схватке." }, { 21.11, "Остались только мы трое." }, { 22.98, "Ормер – он такой храбрый, настоящий герой, – спас меня и проспектора, он прикрывал нас, пока мы бежали в укрытие." }, { 31.33, "А теперь мы в ловушке, и вся наша работа пропала!" }, { 35.00, "Вот, отнеси эту записку моему дорогому Таррелу." }, { 38.61, "Я ему всё написала подробно." }, { 40.74, "Он разберётся." } } }, t = { d = 14.6, v = "dwarf-male", n = { x = 157 }, c = { x = { { 0.00, "Какая ужасная новость!" }, { 1.77, "Это счастье, что уцелели хотя бы трое." }, { 4.77, "Когда же закончится эта череда злоключений?!" }, { 8.17, "Когда же наконец подданные короля Магни забудут, что значит жить в постоянном страхе?!" } } } } },
    [307] = { d = 31.3, v = "dwarf-male", n = { x = 374 }, c = { x = { { 0.00, "Рудник у Серебряного ручейка давно выработан." }, { 3.19, "Лига рудокопов превратила его в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на дворфийские инструменты!" }, { 12.21, "Рано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в шахту не спустились воины и не разнесли всё к демонам." }, { 22.10, "Задача твоя не из простых – помощники тебе не помешают." }, { 25.98, "Оборудование находится в ящиках Лиги рудокопов, разбросанных по всему руднику." } } }, t = { d = 8.6, v = "dwarf-male", n = { x = 96 }, c = { x = { { 0.00, "Там много кобольдов?" }, { 1.53, "Жду не дождусь приказа очистить от них рудник." }, { 4.92, "Как подумаю, что они там хозяйничают, аж киплю весь!" } } } } },
    [308] = { t = { d = 2.9, v = "dwarf-male", n = { x = 20 }, c = { x = { { 0.00, "Это мне?" }, { 1.06, "Ты мой спаситель!" } } } } },
    [309] = { d = 13.8, v = "dwarf-male", n = { x = 142 }, c = { x = { { 0.00, "Что ж, в путь?" }, { 1.07, "Для начала надо доставить Сталекруту порох." }, { 4.57, "Вес немалый, а здесь небезопасно – кто знает, что ещё замышляют дворфы Чёрного Железа." }, { 11.20, "С тобой мне будет куда спокойнее." } } }, t = { d = 23.4, v = "dwarf-male", n = { x = 255 }, c = { x = { { 0.00, "О, слава Свету, вот мой порох." }, { 2.36, "Но новости и верно тревожные." }, { 4.65, "Только подумать, что находятся сторонники Чёрного Железа, способные снабдить их первосортными материалами для выполнения гнусных замыслов." }, { 15.12, "Но над этим пусть поломает голову кто-нибудь другой и не сегодня." }, { 20.11, "А я найду этому пороху отличное применение." } } } } },
    [310] = { d = 31.8, v = "dwarf-female", n = { x = 346 }, c = { x = { { 0.00, "Не могу не признать, эти Громовары делают славные напитки." }, { 4.40, "Но они должны понять, что не только у них это хорошо получается!" }, { 9.20, "Может, ты поможешь преподать им урок..." }, { 12.13, "Вот, возьми-ка этот бочонок жгучего пива Ячменоваров." }, { 16.13, "Проберись в подвал \"Громоварки\" в Караносе и подмени один бочонок их громового эля." }, { 22.32, "И посмотрим, не скажут ли их заказчики, что моё пиво лучше, чем Громоваров!" }, { 27.79, "Если бочонки охраняются, тебе придётся отвлечь стражу..." } } }, t = { d = 7.6, v = "narrator", n = { x = 84 }, c = { x = { { 0.00, "Вы быстро ставите бочонок жгучего пива Ячменоваров, что дала вам Марлетта, среди бочек громового эля." } } } } },
    [311] = { d = 9.8, v = "narrator", n = { x = 112 }, c = { x = { { 0.00, "Подсунув бочонок жгучего пива Марлетты в подвал \"Громоварки\" в Караносе, вы хватаете бочонок громового эля в качестве доказательства..." } } }, t = { d = 14.2, v = "dwarf-female", n = { x = 154 }, c = { x = { { 0.00, "Неплохо!" }, { 0.68, "Тебе, небось, нелегко было проскользнуть мимо их охраны?" }, { 5.05, "Да всё равно – прими мою благодарность, и если когда-нибудь тебе понадобится крепкое пивко с огоньком, вспомни Ячменоваров!" } } } } },
    [312] = { d = 29.4, v = "dwarf-male", n = { x = 339 }, c = { x = { { 0.00, "У меня был месячный запас вяленой солонины на зиму." }, { 3.58, "Я запер его в ларь, чтобы медведи не добрались." }, { 6.86, "Но пока я охотился на оленей, этот изверг, Старый Ледобород, уволок мой мясной ларь!" }, { 12.66, "Он не смог, однако, взломать ториевый замок." }, { 15.69, "Но я же с голоду помру, если не верну своё мясо!" }, { 19.02, "Ты вроде посильнее меня будешь." }, { 21.24, "Может, сумеешь вернуть мой запас?" }, { 23.59, "Нога моя совсем плоха – мне не суметь быстро забраться в пещеру и утащить оттуда ларь." } } }, t = { d = 8.0, v = "dwarf-male", n = { x = 79 }, c = { x = { { 0.00, "Какая же ты добрая душа!" }, { 2.06, "Благодаря твоей отваге я не подохну с голоду, когда начнутся зимние бури." } } } } },
    [313] = { d = 31.5, g = 1, v = "dwarf-male", n = { m = 338, f = 338 }, c = { m = { { 0.00, "Управлять осадным орудием не каждому по плечу." }, { 3.53, "Тут нужна железная хватка и стальные нервы!" }, { 6.85, "К счастью, у меня есть и то, и другое!" }, { 9.70, "А у тебя?" }, { 10.44, "Кишка-то не тонка?" }, { 11.87, "Хочешь показать мне, на что ты способен?" }, { 14.85, "Ладно..." }, { 15.53, "Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее." }, { 20.41, "Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса?" }, { 26.72, "Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!" } }, f = { { 0.00, "Управлять осадным орудием не каждому по плечу." }, { 3.45, "Тут нужна железная хватка и стальные нервы!" }, { 6.69, "К счастью, у меня есть и то, и другое!" }, { 9.48, "А у тебя?" }, { 10.20, "Кишка-то не тонка?" }, { 11.60, "Хочешь показать мне, на что ты способна?" }, { 14.51, "Ладно..." }, { 15.17, "Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее." }, { 19.95, "Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса?" }, { 26.11, "Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!" } } }, t = { d = 8.6, g = 1, v = "dwarf-male", n = { x = 70 }, c = { m = { { 0.00, "О, эти гривы мне очень пригодятся!" }, { 3.03, "Ты крепкий орешек, герой, бьюсь об заклад, я о тебе ещё услышу!" } }, f = { { 0.00, "О, эти гривы мне очень пригодятся!" }, { 3.06, "Ты крепкий орешек, героиня, бьюсь об заклад, я о тебе ещё услышу!" } } } } },
    [314] = { d = 34.4, v = "dwarf-female#34", n = { x = 360 }, c = { x = { { 0.00, "Мы услышали шум среди ночи." }, { 2.19, "Поутру не досчитались в отаре двух баранов." }, { 5.59, "Эта подлая тварь Вагаш покушается на наше единственное добро!" }, { 10.48, "Поскольку большая часть армии короля Магни сражается в дальних краях за дело Альянса, некому приструнить этого Вагаша." }, { 19.90, "Может, тебе достанет отваги найти эту тварь и прикончить?" }, { 24.50, "Принеси мне его клык, и я тебя награжу." }, { 27.61, "Вагаш рыщет как раз вон над тем выгоном, но предупреждаю: это смертельно опасная тварюга." } } }, t = { d = 15.5, v = "dwarf-female#34", n = { x = 145 }, c = { x = { { 0.00, "Отлично!" }, { 0.78, "Верон будет так рад этой доброй вести!" }, { 4.19, "Убить Вагаша – дело непростое." }, { 6.91, "Сдаётся мне, настанет день – и ты будешь сражаться вместе с воинами короля Магни на передовой Альянса!" } } } } },
    [315] = { d = 39.6, v = "dwarf-male", n = { x = 444 }, c = { x = { { 0.00, "Я тут по делу, а дело моё – создать самый лучший портер!" }, { 4.11, "Я знаю, я смогу – пивоварение у меня в крови." }, { 7.44, "Просто надо составить правильный рецепт..." }, { 10.57, "Тролльское племя Мерзлогривов высоко в восточных холмах выращивает одну травку, звездолист называется." }, { 18.01, "Они используют её в странных ритуалах своего племени." }, { 21.93, "Нам, дворфам, она не особо нужна, но у неё неповторимый вкус..." }, { 26.43, "И я хочу поэкспериментировать с ней при варении пива!" }, { 30.22, "Добудь мне немного звездолиста – его можно \"отнять\" у ясновидцев племени Мерзлогривов или стянуть из тролльских корзинок с травами." } } }, t = { d = 9.8, v = "dwarf-male", n = { x = 102 }, c = { x = { { 0.00, "Великолепно!" }, { 0.98, "Прямо не терпится испробовать эту травку в одном из моих рецептов." }, { 6.21, "Думаю, вот в этом она особенно хорошо пойдёт..." } } } } },
    [317] = { d = 27.5, v = "dwarf-male", n = { x = 316 }, c = { x = { { 0.00, "Я веду подготовку к выполнению боевого задания Осадной бригады." }, { 4.46, "Дело будет долгим, и мне нужно укомплектовать мой паровик провизией на месяц." }, { 9.87, "Так что пока ребята из Стальной Решётки работают с моим танком, не отправишься ли ты на охоту?" }, { 16.35, "Мне нужен мех, чтобы сделать кровать, и кабанина для еды." }, { 20.37, "Кабаны – на мясо, медведи – на мех..." }, { 22.95, "Этих животных можно найти в снежных полях к югу от Серой берлоги." } } }, t = { d = 5.4, g = 1, v = "dwarf-male", n = { m = 48, f = 49 }, c = { m = { { 0.00, "Клянусь бородой Магни, ты славно поохотился!" }, { 3.94, "Спасибо тебе." } }, f = { { 0.00, "Клянусь бородой Магни, ты славно поохотилась!" }, { 4.20, "Спасибо тебе." } } } } },
    [318] = { d = 36.2, v = "dwarf-male", n = { x = 401 }, c = { x = { { 0.00, "Регольд Ячменовар не боится экспериментировать со своим варевом." }, { 4.64, "Продукт эксперимента порой хорош на вкус, а порой нет, а иногда... самого крепкого дворфа уложит в стельку." }, { 12.41, "Регольд живёт в Посёлке Пивоваров, к западу от Караноса, и один из его напитков, \"Вечное сияние\", – как раз то, что мне надо." }, { 21.30, "Он согреет меня в пути." }, { 23.06, "И... этот благословенный напиток горит так, что я могу залить его в топку паровика – и будет такой силовой импульс!" }, { 31.49, "Эта тактическая уловка помогала мне выбираться из многих переделок." } } }, t = { d = 4.3, v = "dwarf-male", n = { x = 34 }, c = { x = { { 0.00, "Толстопузу нужно \"Вечное сияние\"?" }, { 3.41, "Ну, ладно." } } } } },
    [319] = { d = 27.5, g = 1, v = "dwarf-male", n = { m = 309, f = 312 }, c = { m = { { 0.00, "У меня есть бочонок \"Вечного сияния\", но... не мог бы ты оказать мне услугу?" }, { 5.27, "Посёлку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг." }, { 11.55, "Иногда они подходят слишком близко..." }, { 14.28, "Мы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты взял это зверьё на себя, у нас было бы больше времени на ремесло и пивоварение." } }, f = { { 0.00, "У меня есть бочонок \"Вечного сияния\", но... не могла бы ты оказать мне услугу?" }, { 5.35, "Посёлку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг." }, { 11.50, "Иногда они подходят слишком близко..." }, { 14.18, "Мы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты взяла это зверьё на себя, у нас было бы больше времени на ремесло и пивоварение." } } }, t = { d = 6.7, v = "dwarf-male", n = { x = 70 }, c = { x = { { 0.00, "Спасибо тебе." }, { 1.16, "Славно будет заняться ремеслом без этого рыка да хрюканья за околицей!" } } } } },
    [320] = { d = 5.1, v = "dwarf-male", n = { x = 44 }, c = { x = { { 0.00, "Вот твоя бочка \"Вечного сияния\"." }, { 3.01, "И спасибо тебе за охоту." } } }, t = { d = 5.5, v = "dwarf-male", n = { x = 44 }, c = { x = { { 0.00, "Ух ты!" }, { 0.60, "Пожалуй, открою-ка я его прямо сейчас да попробую..." } } } } },
    [321] = { d = 37.6, v = "dwarf-male", n = { x = 448 }, c = { x = { { 0.00, "Эти обломки погибших кораблей – останки Кул-Тирасской Третьей флотилии, сожжённой и потопленной красными драконами во время последней Великой войны." }, { 10.32, "Флотилия вышла из Лордерона, и с ней шёл эльфийский боевой корабль – \"Орлик\"." }, { 15.66, "Он вёз груз светлостали и присоединился к Третьей флотилии, ища покровительства и защиты." }, { 21.77, "По иронии судьбы, он был потоплен теми же драконами, от которых пытался спастись..." }, { 27.55, "Ладно, краткий исторический экскурс будем считать завершённым." }, { 31.89, "\"Орлик\" затонул к югу от Гавани Менетилов." }, { 34.91, "Если найдёшь светлосталь, принеси её мне." } } }, t = { d = 26.4, v = "narrator", n = { x = 255 }, c = { x = { { 0.00, "Сундук весь размок, его обшивка сломана." }, { 3.50, "На стенках внутри и снаружи видны глубокие следы когтей... как будто в нём шарились мурлоки и унесли все сокровища." }, { 13.24, "Но в самом дальнем углу завалялся один-единственный слиток светлостали." }, { 19.33, "К несчастью, этого мало." }, { 21.46, "Для того чтобы выковать достойное оружие, вам нужно больше." } } } } },
    [322] = { d = 22.2, g = 1, v = "dwarf-male", n = { m = 234, f = 234 }, c = { m = { { 0.00, "В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали." }, { 5.16, "Зовут его Гриманд Элмор." }, { 7.16, "Металл, который ты нашёл, я упакую в сундук." }, { 10.53, "Отнеси его Гриманду и расскажи ему свою историю." }, { 14.38, "Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!" } }, f = { { 0.00, "В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали." }, { 5.16, "Зовут его Гриманд Элмор." }, { 7.16, "Металл, который ты нашла, я упакую в сундук." }, { 10.60, "Отнеси его Гриманду и расскажи ему свою историю." }, { 14.46, "Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!" } } }, t = { d = 21.3, v = "dwarf-male", n = { x = 240 }, c = { x = { { 0.00, "Да, занятный рассказ." }, { 1.54, "И светлосталь!" }, { 2.57, "Я уже много лет не работал с этим материалом." }, { 5.85, "Для меня это будет великая честь." }, { 8.30, "А когда всё закончится, ты непременно зайди ко мне и расскажи о своей битве с некромантом." }, { 14.67, "Но не будем опережать события." }, { 16.86, "Первым делом – оружие, которым ты сокрушишь Морбента Скверна..." } } } } },
    [323] = { d = 18.8, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Морбент Скверн – могущественный некромант и союзник тёмных всадников." }, { 4.69, "Я не могу послать тебя на битву с ним, не испытав прежде твою силу." }, { 9.44, "Храбрость твою я не подвергаю сомнению, но если ты в самом деле хочешь выступить против некроманта, сразись сначала с его приспешниками." } } }, t = { d = 8.6, v = "human-male", n = { x = 94 }, c = { x = { { 0.00, "Без сомнения, в бою тебе нет равных." }, { 2.81, "Благодаря твоей решимости мы сможем положить конец деяниям Морбента Скверна!" } } } } },
    [324] = { d = 13.4, v = "narrator", n = { x = 150 }, c = { x = { { 0.00, "Вы забрали слиток светлостали из отсыревшего сундука, но похоже, что остальные слитки растащили мурлоки." }, { 7.93, "Найдите мурлоков-налётчиков у остова \"Орлика\" и отберите у них светлосталь." } } }, t = { d = 5.5, v = "dwarf-male", n = { x = 42 }, c = { x = { { 0.00, "Ага, вот и материал!" }, { 1.98, "Ну что, пора бы пустить его в дело, а?" } } } } },
    [325] = { d = 8.2, g = 1, v = "dwarf-male", n = { x = 66 }, c = { m = { { 0.00, "Вот оружие против твоего врага." }, { 2.91, "Путник, иди и сражайся." }, { 5.09, "Удачи тебе, возвращайся со славой!" } }, f = { { 0.00, "Вот оружие против твоего врага." }, { 2.94, "Путница, иди и сражайся." }, { 5.22, "Удачи тебе, возвращайся со славой!" } } }, t = { d = 7.8, v = "human-male", n = { x = 70 }, c = { x = { { 0.00, "О, это именно то, что сразит Морбента Скверна!" }, { 4.08, "Отлично!" }, { 4.86, "Готовься." }, { 5.72, "Скверн теперь – не жилец." } } } } },
    [328] = { d = 27.3, v = "narrator", n = { x = 287 }, c = { x = { { 0.00, "Хотя в записях нет ни слова о рядовом Торсене, в кожаном переплёте одной из книг Герода обнаруживается маленький латунный ключ." }, { 10.03, "Повнимательнее изучив записи, вы находите упоминания \"надёжного сейфа\"." }, { 15.67, "Этот сейф спрятан внутри Схрона, системы пещер позади посёлка Курцена." }, { 21.37, "Если найти его, быть может, удастся разрешить загадку обнаружения Торсена." } } }, t = { d = 7.8, v = "narrator", n = { x = 74 }, c = { x = { { 0.00, "Открыв сейф, вы понимаете, что именно здесь Герод хранил самые ценные монеты и прочие вещи." } } } } },
    [329] = { d = 27.3, v = "narrator", n = { x = 263 }, c = { x = { { 0.00, "Среди ценностей в сундуке оказывается грязная, торопливо написанная записка." }, { 6.46, "Это сведения о рядовом Торсене – где он патрулирует, с кем он говорит и как проводит время среди повстанцев." }, { 15.50, "Записка подписана лишь одной буквой – М." }, { 18.92, "Ясно одно, её автор очень близко знаком с Торсеном, а это значит, что предатель – среди повстанцев." } } }, t = { d = 5.2, v = "human-male", n = { x = 57 }, c = { x = { { 0.00, "Спасибо." }, { 0.71, "Эта записка позволит нам вычислить и уничтожить предателя!" } } } } },
    [330] = { d = 20.5, v = "human-male", n = { x = 233 }, c = { x = { { 0.00, "Принесённая тобой записка подписана просто \"-М\"..." }, { 3.50, "Не пойму, что это значит." }, { 5.35, "Но... в записке также говорится, что этот человек дежурил вместе с Торсеном на прошлой неделе." }, { 12.03, "Значит, он и есть предатель!" }, { 14.00, "Иди к капралу Сетману." }, { 15.66, "Он занимается составлением расписания и скажет, кто дежурил с Торсеном." } } }, t = { d = 12.2, v = "human-male#50", n = { x = 115 }, c = { x = { { 0.00, "А, да, я могу узнать." }, { 1.80, "Посмотрим... на прошлой неделе…" }, { 4.43, "..." }, { 4.73, "Да, с Торсеном дежурил рядовой Мерль." }, { 7.81, "Всю прошлую неделю у них совпадало расписание дежурств." } } } } },
    [331] = { d = 5.0, v = "human-male#50", n = { x = 67 }, c = { x = { { 0.00, "Не просил ли лейтенант Дорен доложить ему о собранной информации по дежурствам?" } } }, t = { d = 15.7, v = "human-male", n = { x = 177 }, c = { x = { { 0.00, "Мне больно слышать, что нас предал Мерль." }, { 2.87, "Он был храбрым солдатом, и мне казалось, что верным." }, { 6.51, "С другой стороны, хорошо, что мы его нашли – с таким шпионом в наших рядах... мы недолго продержались бы против полковника Курцена." } } } } },
    [332] = { d = 18.2, v = "human-male", n = { x = 218 }, c = { x = { { 0.00, "Если тебя интересует вино, так лучшее вино в Штормграде продаёт семейство Галлина!" }, { 5.69, "Это недалеко – в Торговом квартале, неподалёку от городских каналов." }, { 10.34, "Возьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого \"Пино нуар\"." }, { 17.45, "Не пожалеешь!" } } }, t = { d = 11.4, g = 1, v = "human-female#111", n = { m = 116, f = 117 }, c = { m = { { 0.00, "Вы знакомы с Ренато?" }, { 1.60, "В таком случае - только для вас, мсье..." }, { 4.65, "Бутылка нашего особого \"Пино нуар\"!" }, { 7.49, "Такого вы не попробуете больше нигде во всём Азероте!" } }, f = { { 0.00, "Вы знакомы с Ренато?" }, { 1.57, "В таком случае - только для вас, мадам..." }, { 4.70, "Бутылка нашего особого \"Пино нуар\"!" }, { 7.49, "Такого вы не попробуете больше нигде во всём Азероте!" } } } } },
    [333] = { d = 23.9, v = "human-male", n = { x = 275 }, c = { x = { { 0.00, "Кажется, мы уже встречались." }, { 2.05, "Наверное, насчёт покупки брони и походной одежды." }, { 5.58, "Кстати, ожидается суровая зима..." }, { 8.02, "А сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду." }, { 13.35, "Мне нужна ещё одна партия от нашего поставщика." }, { 16.75, "Если ты отнесёшь это послание Реме Шнайдер в ателье \"Канал\", моя признательность будет весьма велика." } } }, t = { d = 23.6, v = "human-female", n = { x = 257 }, c = { x = { { 0.00, "Говорят, бизнес Харлана пошёл в гору." }, { 2.81, "Хорошие новости, хотя… хотелось бы мне знать, для чего вдруг понадобилось столько брони." }, { 9.30, "Неужели где-то поблизости скоро случится война?" }, { 12.91, "Благородные господа ничего не говорят нам об этом!" }, { 16.66, "Ну что ж, спасибо тебе за помощь." }, { 19.13, "Вот твоя плата, и я надеюсь, что с заказом Харлана всё хорошо." } } } } },
    [334] = { d = 28.6, g = 1, v = "human-female", n = { x = 330 }, c = { m = { { 0.00, "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов." }, { 4.55, "Он сегодня торопился, а потому забыл иголки и ножницы." }, { 8.31, "Конечно, герой вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать..." }, { 17.36, "Прошу вас!" }, { 18.10, "Отнесите моему сыну его швейные принадлежности!" }, { 21.42, "Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов." } }, f = { { 0.00, "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов." }, { 4.55, "Он сегодня торопился, а потому забыл иголки и ножницы." }, { 8.30, "Конечно, героиня вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать..." }, { 17.45, "Прошу вас!" }, { 18.19, "Отнесите моему сыну его швейные принадлежности!" }, { 21.51, "Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов." } } }, t = { d = 14.3, v = "child-male", n = { x = 141 }, c = { x = { { 0.00, "Ох, вот незадача!" }, { 1.36, "А я так надеялся, что забытые инструменты помогут мне увильнуть от работы." }, { 7.16, "А теперь всё-таки придётся помочь Ларсону с шитьём..." }, { 11.25, "Ну, ладно: делу – время, потехе – час..." } } } } },
    [335] = { d = 29.3, v = "human-male#50", n = { x = 371 }, c = { x = { { 0.00, "Лорд Вишлок наделал немалого переполоху среди Благородных домов." }, { 4.31, "Он прознал о наших делах и теперь собирается добиться полного расследования." }, { 9.39, "У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь." }, { 15.97, "Есть один цветочек под названием \"слеза Тиллоа\", он растёт в садах Сталвана поблизости от Темнолесья." }, { 22.60, "Ещё мне понадобится мускусный корень, который можно найти только у подножия Каменной дамбы в Болотине." } } }, t = { d = 3.2, v = "human-male#50", n = { x = 25 }, c = { x = { { 0.00, "Отлично!" }, { 0.89, "Это ровно то, что нужно!" } } } } },
    [336] = { d = 35.8, v = "human-male#50", n = { x = 413 }, c = { x = { { 0.00, "У лорда Вишлока, как у всех людей, есть свои маленькие слабости." }, { 4.52, "Например, он совсем не дурак выпить." }, { 7.13, "Удивительное лицемерие!" }, { 8.78, "Старый ханжа целыми днями сражается с заведениями вроде нашего, а ночи напролёт проводит наверху, да ещё и не платит по счёту." }, { 17.63, "Ну, посмотрим, как ему понравится придуманный мной специально для него напиток: портер \"Чёрный Коготь\"!" }, { 24.83, "С ног сбивает – точно тебе говорю!" }, { 27.31, "Отнеси ему это пойло и посмотри, придётся ли оно лорду по вкусу." }, { 31.96, "Старый хмырь наверняка шатается вокруг Зала просителей." } } }, t = { d = 7.6, v = "human-male", n = { x = 80 }, c = { x = { { 0.00, "Спасибо за чудесный портер!" }, { 2.16, "Вот, возьми пару монет." }, { 4.05, "А теперь иди прочь и не мешай мне дегустировать!" } } } } },
    [337] = { d = 19.8, v = "narrator", n = { x = 198 }, c = { x = { { 0.00, "Хотя обложка книги исцарапана и заляпана грязью, на корешке всё ещё можно прочитать заглавие – \"История Штормграда\"." }, { 9.37, "Открыв её, вы видите на первой странице печать библиотеки Штормграда." }, { 14.97, "Похоже, кто-то взял почитать эту книгу, да так и не вернул..." } } }, t = { d = 18.2, g = 1, v = "human-male", n = { m = 211, f = 210 }, c = { m = { { 0.00, "О небо!" }, { 0.58, "Этой книги не видели на полках со времён восстановления Штормграда." }, { 5.33, "Конечно, её придётся реставрировать, она в плохом состоянии, но я с радостью помещу её в нашу коллекцию редких книг." }, { 13.49, "Благодарю вас, господин." }, { 15.22, "Прошу, примите плату за возвращение книги!" } }, f = { { 0.00, "О небо!" }, { 0.56, "Этой книги не видели на полках со времён восстановления Штормграда." }, { 5.19, "Конечно, её придётся реставрировать, она в плохом состоянии, но я с радостью помещу её в нашу коллекцию редких книг." }, { 13.12, "Благодарю вас, госпожа." }, { 14.74, "Прошу, примите плату за возвращение книги!" } } } } },
    [338] = { d = 27.2, v = "dwarf-male", n = { x = 316 }, c = { x = { { 0.00, "Господин Эрнестуэй так расстроится, когда узнает об этом!" }, { 4.11, "Он доверил мне гранки романа \"Зелёные холмы Тернистой долины\"." }, { 8.54, "Всё шло хорошо, но по лагерю пронёсся сильный порыв ветра и разметал страницы!" }, { 14.06, "Большую часть мне удалось собрать, но многие страницы унесло в джунгли." }, { 19.13, "Найди все страницы, и мы снова соберём четыре главы." }, { 22.85, "Я сам всё разложу!" }, { 24.13, "Когда соберёшь все четыре главы, возвращайся." } } }, t = { d = 11.0, g = 1, v = "dwarf-male", n = { m = 113, f = 114 }, c = { m = { { 0.00, "Ты избавил меня от многих хлопот." }, { 2.76, "Не знаю, как и благодарить тебя." }, { 5.38, "Вскоре книги господина Эрнестуэя появятся в библиотеках по всему свету!" } }, f = { { 0.00, "Ты избавила меня от многих хлопот." }, { 2.76, "Не знаю, как и благодарить тебя." }, { 5.30, "Вскоре книги господина Эрнестуэя появятся в библиотеках по всему свету!" } } } } },
    [339] = { d = 19.9, v = "dwarf-male", n = { x = 215 }, c = { x = { { 0.00, "Первая глава была необычайно интересной." }, { 3.16, "Мастер Эрнестуэй предваряет рассказ знакомством со своими товарищами по охоте, в том числе и со мной!" }, { 10.79, "Но речь не об этом." }, { 12.23, "Посмотрим, каких страниц не хватает." }, { 15.05, "Кажется, страницы один, четыре, шесть и восемь всё ещё в джунглях!" } } }, t = { d = 3.7, v = "dwarf-male", n = { x = 27 }, c = { x = { { 0.00, "Наконец-то!" }, { 1.32, "Глава первая собрана!" } } } } },
    [340] = { d = 17.4, v = "dwarf-male", n = { x = 207 }, c = { x = { { 0.00, "Вторая глава представляла собой сплошные увлекательные рассказы про охоту на пантер и тигров." }, { 6.67, "Так и хочется самому себе наподдать за то, что упустил страницы!" }, { 11.22, "Мне удалось собрать почти всё, кроме десятой, одиннадцатой, четырнадцатой и шестнадцатой." } } }, t = { d = 3.9, g = 1, v = "dwarf-male", n = { m = 34, f = 33 }, c = { m = { { 0.00, "Вторая глава полностью собрана!" }, { 3.14, "Молодец!" } }, f = { { 0.00, "Вторая глава полностью собрана!" }, { 3.27, "Умница!" } } } } },
    [341] = { d = 22.6, v = "dwarf-male", n = { x = 245 }, c = { x = { { 0.00, "Глава третья была моей любимой." }, { 2.55, "В ней рассказывается о том, как сэр Эрлгедин и леди Руак впервые подстрелили зверя из дворфийского ружья." }, { 10.49, "А какое захватывающее у неё окончание!" }, { 13.39, "Похоже, нам недостаёт страниц восемнадцать, двадцать, двадцать один и двадцать четыре." }, { 19.95, "Они должны быть где-то неподалёку..." } } }, t = { d = 5.3, v = "dwarf-male", n = { x = 44 }, c = { x = { { 0.00, "Уф!" }, { 0.35, "Отличная работа." }, { 1.99, "Теперь у нас есть вся третья глава!" } } } } },
    [342] = { d = 16.2, v = "dwarf-male", n = { x = 170 }, c = { x = { { 0.00, "А, глава четвёртая, захватывающий финал!" }, { 3.05, "И как она закончилась!" }, { 4.79, "Нам не хватает всего лишь трёх страниц этой главы." }, { 8.68, "А именно – двадцать пять, двадцать шесть и двадцать семь." }, { 12.98, "Стоит найти их – и последняя глава готова." } } }, t = { d = 3.8, v = "dwarf-male", n = { x = 31 }, c = { x = { { 0.00, "Великолепно!" }, { 1.38, "Глава четвёртая готова!" } } } } },
    [343] = { d = 29.8, v = "human-male", n = { x = 368 }, c = { x = { { 0.00, "Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, \"Как закалялось железо\"." }, { 10.07, "Копия этой книги должна быть в Королевской библиотеке Крепости Штормграда." }, { 15.10, "Не могли бы вы заказать её для меня?" }, { 17.53, "Да осенит вас благодать Света!" }, { 19.59, "Королевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев." }, { 27.05, "Поговорите с ним, он принесёт для вас книгу." } } }, t = { d = 11.0, v = "human-male", n = { x = 127 }, c = { x = { { 0.00, "Металлургия?" }, { 0.89, "Да, конечно, у нас много книг по данной отрасли знаний, и мы будем рады помочь брату Кристофу в подготовке лекции!" }, { 8.96, "Какая же книга его интересует?" } } } } },
    [344] = { d = 33.8, v = "human-male", n = { x = 384 }, c = { x = { { 0.00, "\"Как закалялось железо\"?" }, { 1.73, "Конечно, я знаю такую книгу." }, { 3.85, "Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном." }, { 9.89, "Он много времени провёл в горах Каз Модана, добывая руду." }, { 14.00, "Отличный парень!" }, { 15.23, "Но о чём это я?" }, { 16.32, "Ах, да..." }, { 16.96, "\"Как закалялось железо\"!" }, { 18.69, "Боюсь, что книга отправилась в Аббатство Североземья." }, { 22.48, "Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с неё копию для своей коллекции." }, { 28.97, "Уж сколько тому месяцев минуло..." }, { 31.41, "Интересно, почему он её задерживает." } } }, t = { d = 11.6, v = "human-male", n = { x = 121 }, c = { x = { { 0.00, "Коллега Сноп потерял свою книгу?" }, { 2.59, "Мда, неловко вышло..." }, { 4.27, "Книга действительно у меня, но я не закончил её переписывать, так что мне пока что нужен оригинал!" } } } } },
    [345] = { d = 32.8, v = "human-male", n = { x = 378 }, c = { x = { { 0.00, "Я как раз собирался закончить свою работу над копией \"Как закалялось железо\", но..." }, { 5.81, "Я пользуюсь только чернилами своего собственного изготовления." }, { 10.22, "Они не текут, не выцветают и очень быстро сохнут." }, { 13.79, "Увы, высыхают они тоже слишком быстро!" }, { 16.66, "Последняя моя бутылка чернил никуда не годится, а я ещё не успел закончить работу… и сделать ещё чернил я не могу!" }, { 24.77, "Для изготовления чернил мне нужна ретбанская руда из Красногорья." }, { 29.43, "Штейгер Ослоу из Приозёрья – мой верный поставщик…" } } }, t = { d = 12.9, g = 1, v = "human-male", n = { m = 144, f = 145 }, c = { m = { { 0.00, "Чего тебе надо?" }, { 1.19, "Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозёрье латаем после нападения орков." }, { 9.18, "Если тебе сдалась ретбанская руда, добудь её сам!" } }, f = { { 0.00, "Чего тебе надо?" }, { 1.21, "Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозёрье латаем после нападения орков." }, { 9.32, "Если тебе сдалась ретбанская руда, добудь её сама!" } } } } },
    [346] = { d = 10.4, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Я закончил перепись и могу вернуть оригинал \"Как закалялось железо\"." }, { 4.70, "Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку." } } }, t = { d = 5.7, v = "human-male", n = { x = 48 }, c = { x = { { 0.00, "Это она!" }, { 0.95, "Спасибо!" }, { 1.81, "Да пребудет над тобой вечный сияющий Свет!" } } } } },
    [347] = { d = 37.8, v = "human-male", n = { x = 440 }, c = { x = { { 0.00, "Ретбанская руда получила своё название по имени первооткрывателя, Барта Ретбана." }, { 5.68, "Выплавленный металл мягче железа, но руда имеет приятный тёмный цвет, и многие переписчики используют её для изготовления чернил." }, { 14.75, "Добыть руду можно в пещерах Ретбана к северу отсюда." }, { 18.58, "К сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли." }, { 25.15, "Скажу тебе ещё вот что..." }, { 26.94, "Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду." }, { 34.05, "Так что если тебе нужна руда... ты знаешь, как добыть её." } } }, t = { d = 9.3, v = "human-male", n = { x = 104 }, c = { x = { { 0.00, "О, благодарю!" }, { 1.00, "Я наконец-то смогу приготовить чернила и закончить свою работу над копией \"Как закалялось железо\"!" }, { 8.23, "Благодарю тебя!" } } } } },
    [348] = { d = 27.8, v = "goblin-male", n = { x = 227 }, c = { x = { { 0.00, "Плохо..." }, { 0.77, "Мне..." }, { 1.30, "Т-т-т-ак п-п-лохо." }, { 2.84, "П-подцепил..." }, { 3.99, "Лихорадку Тернистой Д-долины... смертельный вирус…" }, { 8.28, "...единственное лекарство... это... съесть сердце М-м-м-мок-ка Д-дикаря... неуловимой белой гориллы…" }, { 16.72, "...знахарь Унбагва... только он может п-п-призвать..." }, { 21.25, "...ищи его в с-с-скрытой пещере на южном мысу..." }, { 25.47, "...спеши... умираю... умру..." } } }, t = { d = 10.0, v = "goblin-male", n = { x = 82 }, c = { x = { { 0.00, "...сила возвращается..." }, { 2.15, "Где я?" }, { 2.73, "В Пиратской бухте?" }, { 4.46, "Ох!" }, { 4.79, "Мне снился странный сон…" }, { 7.02, "...слабость не полностью прошла..." } } } } },
    [349] = { t = { d = 15.4, v = "troll-male#77", n = { x = 139 }, c = { x = { { 0.00, "Знахарь Унбагва любить клык горилла!" }, { 3.37, "Моя будет говорить с духи." }, { 5.91, "Пусть придёт Мокк Дикарь." }, { 8.13, "Твоя защищать знахарь Унбагва от других горилл-зверей, или никакой Мокк не быть!" } } } } },
    [350] = { d = 34.2, v = "human-male", n = { x = 418 }, c = { x = { { 0.00, "Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара..." }, { 6.75, "Теперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твоё свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара." }, { 23.55, "Ему, в сущности, наплевать на закон." }, { 26.04, "Тебе понадобится помощь." }, { 27.75, "Я, увы, оказать её не могу, но знаю того, кто может нам помочь." }, { 32.07, "Найди Триаса в Торговом квартале." } } }, t = { d = 18.7, v = "human-male#50", n = { x = 201 }, c = { x = { { 0.00, "Опять Шоу?!" }, { 0.94, "Совести у него нет!.." }, { 2.54, "Братство Справедливости, говорите?" }, { 5.08, "Да вы просто мешок с хорошими новостями!" }, { 8.10, "Скажите ещё, что Смертокрыл воскрес и напал на город..." }, { 12.18, "Ну, ладно, выкладывайте всё по порядку." }, { 15.05, "И не пропускайте ни единой детали." }, { 17.60, "Я хочу знать всё." } } } } },
    [351] = { d = 28.7, v = "narrator", n = { x = 301 }, c = { x = { { 0.00, "Вы находите какой-то странный яйцевидный металлический предмет." }, { 4.97, "Повозившись с кнопками, вы пробуждаете яйцо, и оно превращается в гномский робот!" }, { 11.35, "Изнутри доносится голос." }, { 13.34, "\"Меня зовут Карлс, и мой автономный робот потерялся!" }, { 17.45, "За его находку полагается награда!" }, { 20.22, "Прошу, отнесите этот маяк к роботу." }, { 23.13, "Я уже вычислил координаты." }, { 25.25, "Он сломался возле Зияющей бездны в Танарисе.\"" } } }, t = { d = 28.6, v = "gnome-male", n = { x = 287 }, c = { x = { { 0.00, "*Вы помещаете яйцо... аварийный маяк... внутрь цыплёнка... робота.*" }, { 5.59, "*Изнутри робота доносится жужжание и скрип – он пытается встать.*" }, { 11.03, "*Когда робот оживает, изнутри доносится голос Карлса:*" }, { 15.68, "\"По крайней мере, КПХ семнадцать тэ-эн работает, но нуждается в серьёзном ремонте!" }, { 21.58, "Он слишком тяжёлый, чтобы унести отсюда... впрочем, у меня есть идея." }, { 26.62, "Не хотите присмотреть за ним?\"" } } } } },
    [353] = { d = 30.9, v = "dwarf-male", n = { x = 380 }, c = { x = { { 0.00, "Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утончёнными вкусами." }, { 6.36, "Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие." }, { 14.70, "Заказ выполнен, но Грингер служит далеко отсюда, в Лок Модане." }, { 19.02, "Если вы собираетесь на север, не возьмётесь ли доставить груз?" }, { 23.16, "По моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане." } } }, t = { d = 15.4, v = "dwarf-male", n = { x = 166 }, c = { x = { { 0.00, "Ага!" }, { 0.41, "Так Гриманд всё-таки закончил мой топор!" }, { 3.39, "Мне уже не терпится опробовать его на троггах и кобольдах!" }, { 7.79, "Благодарю." }, { 8.60, "Эта посылка проделала такой долгий путь..." }, { 11.85, "Вот, примите это в благодарность за ваши услуги." } } } } },
    [354] = { d = 39.0, v = "scourge-male#82", n = { x = 355 }, c = { x = { { 0.00, "Семья Агамондов была самой преуспевающей в Тирисфальских лесах." }, { 5.74, "Я работал на их мельницах... ещё до чумы." }, { 9.38, "Когда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону." }, { 20.69, "А мы были дураками, но дураками преданными..." }, { 24.73, "Из-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!" }, { 30.88, "Сослужи Отрёкшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки." } } }, t = { d = 22.1, g = 1, v = "scourge-male#82", n = { m = 190, f = 192 }, c = { m = { { 0.00, "Месть сладка, не правда ли?" }, { 2.55, "Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их?" }, { 9.93, "Надеюсь, что да." }, { 11.46, "Надеюсь, они почувствовали страх, прежде чем упокоились навсегда." }, { 17.58, "Конечно, глупо на это надеяться, но тем не менее." } }, f = { { 0.00, "Месть сладка, не правда ли?" }, { 2.43, "Ты заметила хоть какие-то признаки свободной воли в Агамондах, когда убивала их?" }, { 9.63, "Надеюсь, что да." }, { 11.09, "Надеюсь, они почувствовали страх, прежде чем упокоились навсегда." }, { 16.91, "Конечно, глупо на это надеяться, но тем не менее." } } } } },
    [355] = { d = 23.8, g = 1, v = "scourge-male#82", n = { m = 230, f = 233 }, c = { m = { { 0.00, "Ты принёс мне останки Агамондов и утолил мою жажду мести." }, { 4.87, "Но мельницы этой проклятой семейки всё ещё представляют собой угрозу не только для меня, но и для всех Отрёкшихся." }, { 14.31, "Я рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично." } }, f = { { 0.00, "Ты принесла мне останки Агамондов и утолила мою жажду мести." }, { 5.23, "Но мельницы этой проклятой семейки всё ещё представляют собой угрозу не только для меня, но и для всех Отрёкшихся." }, { 14.77, "Я рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично." } } }, t = { d = 10.2, v = "scourge-male#82", n = { x = 106 }, c = { x = { { 0.00, "Колман хорошо отзывался о тебе, и рассказал о твоём успешном походе на мельницы Агамондов." }, { 7.27, "Отрёкшимся ещё раз нужна твоя помощь..." } } } } },
    [356] = { d = 41.2, v = "scourge-female", n = { x = 378 }, c = { x = { { 0.00, "Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них." }, { 11.20, "Наш успех на Бастионе зависит от битвы на один фронт: мы не можем допустить атаки с тыла и уж конечно не можем лишить наших защитников линии поставки припасов." }, { 25.67, "Помоги Бастиону." }, { 27.22, "Отправляйся на восток и убей любого приспешника Плети, которого встретишь." }, { 34.00, "Особое внимание обрати на ферму Балнира на востоке – там настоящее гнездо Плети." } } }, t = { d = 12.5, v = "scourge-female", n = { x = 117 }, c = { x = { { 0.00, "Очень хорошо." }, { 1.29, "Благодаря вашим усилиям Плеть ещё долго не осмелится сунуться сюда." }, { 7.33, "Я отправлю лестный отзыв моему начальнику, палачу Зуганду." } } } } },
    [357] = { d = 45.8, v = "scourge-male#82", n = { x = 405 }, c = { x = { { 0.00, "На острове посреди озера Ясноводного, что к северу отсюда, обитает лич." }, { 6.55, "Сам он - свободный Отрёкшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится." }, { 22.71, "Но раз он Отрёкшийся, он понадобится Королеве." }, { 26.77, "А если он ещё и специалист в некромантии, то его умения нам... весьма пригодятся." }, { 34.15, "Чтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний." }, { 41.28, "Прокрадись в его лагерь, достань её, и принеси мне." } } }, t = { d = 42.2, g = 1, v = "scourge-male#82", n = { m = 380, f = 381 }, c = { m = { { 0.00, "Прекрасно." }, { 1.15, "Я изучу эту книгу и узнаю многое об этом личе." }, { 6.34, "Ты сослужил королеве добрую службу." }, { 10.08, "*Бетор открывает книгу и внимательно смотрит на её сияющие страницы…*" }, { 15.76, "Невероятно!" }, { 16.77, "Добытая тобой книга принадлежит не кому иному, как Гюнтеру Чародею!" }, { 22.69, "Гюнтер и при жизни был искусным некромантом." }, { 26.50, "До нашествия Плети мы были добрыми товарищами и братьями по оружию." }, { 32.34, "Судя по книге, после смерти он достиг ещё большего могущества." }, { 37.79, "Его искусство могло бы нам очень пригодиться." } }, f = { { 0.00, "Прекрасно." }, { 1.16, "Я изучу эту книгу и узнаю многое об этом личе." }, { 6.38, "Ты сослужила королеве добрую службу." }, { 10.24, "*Бетор открывает книгу и внимательно смотрит на её сияющие страницы…*" }, { 16.00, "Невероятно!" }, { 17.02, "Добытая тобой книга принадлежит не кому иному, как Гюнтеру Чародею!" }, { 22.95, "Гюнтер и при жизни был искусным некромантом." }, { 26.77, "До нашествия Плети мы были добрыми товарищами и братьями по оружию." }, { 32.63, "Судя по книге, после смерти он достиг ещё большего могущества." }, { 38.10, "Его искусство могло бы нам очень пригодиться." } } } } },
    [358] = { d = 40.3, v = "scourge-male#82", n = { x = 403 }, c = { x = { { 0.00, "Братские могилы к юго-западу от фермы Гаррена были вырыты, чтобы справиться с... внушительным количеством смертей в Тирисфале после прихода Чумы." }, { 12.08, "Тела в этих могилах ещё не превратились в нежить, но теперь Плеть подослала гноллов-Гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии." }, { 25.49, "Это недопустимо!" }, { 26.91, "У тебя будет два задания: перебить гноллов-Гнилошкуров возле братских могил и фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь." } } }, t = { d = 33.6, g = 1, v = "scourge-male#82", n = { m = 312, f = 314 }, c = { m = { { 0.00, "Отличная работа!" }, { 1.50, "Если силы Плети решили, что могут направлять этих мертвецов на нас, то они жестоко ошиблись." }, { 9.70, "Что же касается жидкости, которую ты собрал с рабов Гнилошкуров, её изучат наши аптекари." }, { 17.51, "Возможно, они откроют какой-то секрет, который поможет нам в войне." }, { 23.51, "Словом, ты отлично справился." }, { 26.11, "Но война продолжается, и у тебя будет ещё много шансов проявить себя перед Отрёкшимися." } }, f = { { 0.00, "Отличная работа!" }, { 1.44, "Если силы Плети решили, что могут направлять этих мертвецов на нас, то они жестоко ошиблись." }, { 9.31, "Что же касается жидкости, которую ты собрала с рабов Гнилошкуров, её изучат наши аптекари." }, { 16.88, "Возможно, они откроют какой-то секрет, который поможет нам в войне." }, { 22.64, "Словом, ты отлично справилась." }, { 25.21, "Но война продолжается, и у тебя будет ещё много шансов проявить себя перед Отрёкшимися." } } } } },
    [359] = { d = 31.0, v = "scourge-male#82", n = { x = 305 }, c = { x = { { 0.00, "Мне нужен свежий отчёт с восточной базы наших стражей смерти." }, { 5.11, "Я хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль." }, { 10.89, "На границе с Чумными землями нужно постоянно смотреть в оба!" }, { 15.93, "Нельзя, чтобы Плеть устроила здесь ещё одну крепость." }, { 20.30, "Иди по дороге на юг, а на развилке сверни на восток, к базе." }, { 25.27, "Поговори со стражем смерти Линнеей, у неё есть вся нужная мне информация." } } }, t = { d = 16.2, v = "scourge-female", n = { x = 147 }, c = { x = { { 0.00, "Севрену нужен отчёт?" }, { 1.87, "Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них всё же проникает время от времени." }, { 10.96, "Плеть видели к востоку от нашей базы, возле фермы Балнира." } } } } },
    [360] = { d = 18.2, v = "scourge-female", n = { x = 171 }, c = { x = { { 0.00, "Теперь возвращайся к мировому судье Севрену с той информацией, что я дала вам." }, { 6.70, "Он очень ждёт её, так что поспеши." }, { 9.59, "А если встретишь по пути приспешников Плети – немедленно убей их!" }, { 15.28, "Нечего им шастать по нашим землям." } } }, t = { d = 14.2, v = "scourge-male#82", n = { x = 134 }, c = { x = { { 0.00, "Неприятно слышать, что Плеть просачивается через Бастион." }, { 4.98, "Король-лич и его слуги не собираются сдаваться." }, { 9.18, "Но и мы не уступим." }, { 10.84, "Мы не позволим ему захватить нас снова!" } } } } },
    [361] = { d = 11.4, v = "narrator", n = { x = 108 }, c = { x = { { 0.00, "Это письмо, написанное Турманом, старшим сыном Грегора Агамонда." }, { 5.61, "Оно адресовано Иветте Фартинг, но, похоже, так до неё и не добралось..." } } }, t = { d = 46.6, v = "scourge-female#80", n = { x = 384 }, c = { x = { { 0.00, "О... мой бедный Турман!" }, { 2.25, "Я ведь просила его уйти с этих мельниц со мной и моим отцом, но его преданность семье оказалась сильнее..." }, { 12.55, "Так я и знала!" }, { 13.93, "Я знала, что Брэнд желает ему зла!" }, { 17.22, "Будь прокляты эти Чума и Плеть!" }, { 20.16, "*Лицо Иветты разглаживается и холодеет.*" }, { 24.32, "Но стенания – удел слабых." }, { 26.82, "Я Отрёкшаяся, у меня есть свои цели, и любовь не входит в их число." }, { 32.98, "Спасибо за то, что принесли мне письмо от некогда любимого человека, теперь я хотя бы знаю, что с ним сталось." }, { 43.06, "Но та жизнь для меня окончена." }, { 45.81, "Навсегда." } } } } },
    [362] = { d = 42.9, v = "scourge-male#82", n = { x = 416 }, c = { x = { { 0.00, "Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно." }, { 8.43, "Турман был высоким и учтивым, а его младший брат – слабым и острым на язык." }, { 14.75, "Когда мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых." }, { 24.23, "На дороге, ведущей к мельницам Агамондов, до сих пор можно услышать его безумное бормотание." }, { 31.90, "Я собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина." }, { 39.20, "Найди его, уничтожь и принеси мне его кости." } } }, t = { d = 23.9, v = "scourge-male#82", n = { x = 206 }, c = { x = { { 0.00, "Спасибо." }, { 0.83, "Кости Девлина станут отличным украшением для моего плаща." }, { 6.23, "Если что-то может согреть моё холодное сердце, то это мысль о том, что Агамондов больше нет." }, { 14.70, "Они предали меня и мою семью, когда пришла Чума – а теперь я клянусь, что растопчу их кости ногами!" } } } } },
    [363] = { d = 25.0, g = 1, v = "scourge-male#83", n = { m = 265, f = 268 }, c = { m = { { 0.00, "Ты вовремя пришёл в себя." }, { 1.88, "Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи." }, { 10.56, "Меня зовут Мордо, я смотритель склепа Могильника." }, { 14.32, "А ты больше не раб Короля-лича." }, { 16.68, "Поговори с жрецом Тьмы Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать." } }, f = { { 0.00, "Ты вовремя пришла в себя." }, { 1.97, "Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи." }, { 10.72, "Меня зовут Мордо, я смотритель склепа Могильника." }, { 14.52, "А ты больше не рабыня Короля-лича." }, { 17.17, "Поговори с жрецом Тьмы Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать." } } }, t = { d = 38.8, v = "scourge-male#82", n = { x = 345 }, c = { x = { { 0.00, "А, ещё один живой мертвец!" }, { 2.42, "Должно быть, это настоящий шок – очнуться в склепе, в котором тебя встречает лишь холод... и Мордо." }, { 11.29, "Я всё это читаю по твоему лицу." }, { 14.20, "Позволь мне объяснить тебе наше... эээ... положение." }, { 18.96, "Нас освободила из-под контроля Короля-лича наша новая предводительница, Леди Сильвана." }, { 26.78, "Тёмная Госпожа руководит нами в войне против ненавистной армии Плети и цепляющихся за эту землю людей, преследующих нас, словно ищейки." } } } } },
    [364] = { d = 33.0, v = "scourge-male#82", n = { x = 302 }, c = { x = { { 0.00, "Мы, Отрёкшиеся, ведём войну против армии Плети, ведомой Королём-личом: против поднятых некромантией войск нежити, против злобных зверей севера и истерзанных призраков." }, { 15.00, "Северную часть деревни оккупировали безмозглые твари Плети, их нужно уничтожить." }, { 22.30, "Сокруши их, не давая пощады, пусть они и были прежде нашими братьями и сёстрами." }, { 29.60, "Падшие – всего лишь рабы Короля-лича." } } }, t = { d = 16.2, v = "scourge-male#82", n = { x = 158 }, c = { x = { { 0.00, "Жаль, что нельзя привлечь Плеть на нашу сторону, её несметные полчища пришлись бы как нельзя кстати в предстоящих битвах." }, { 10.38, "Но так как договориться с ними нельзя, нам остаётся лишь уничтожить их." } } } } },
    [365] = { d = 36.1, g = 1, v = "scourge-male", n = { m = 323, f = 323 }, c = { m = { { 0.00, "Кто это тут?" }, { 1.13, "Новенький, да ещё и герой?" }, { 3.48, "Если хочешь проявить себя перед Тёмной Госпожой, придётся следовать обычаям Отрёкшихся." }, { 11.24, "К западу отсюда есть ферма." }, { 13.75, "Люди растекаются по этой земле, как плесень по трупу." }, { 18.61, "К тому же Алый орден постоянно ходит дозором возле своей башни." }, { 24.51, "Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв." }, { 31.23, "Как наберёшь десяток, отнеси их аптекарю Юхану в Брилл." } }, f = { { 0.00, "Кто это тут?" }, { 1.13, "Новенькая, да ещё и героиня?" }, { 3.64, "Если хочешь проявить себя перед Тёмной Госпожой, придётся следовать обычаям Отрёкшихся." }, { 11.41, "К западу отсюда есть ферма." }, { 13.91, "Люди растекаются по этой земле, как плесень по трупу." }, { 18.77, "К тому же Алый орден постоянно ходит дозором возле своей башни." }, { 24.67, "Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв." }, { 31.39, "Как наберёшь десяток, отнеси их аптекарю Юхану в Брилл." } } }, t = { d = 9.4, g = 1, v = "scourge-male#82", n = { m = 80, f = 83 }, c = { m = { { 0.00, "Ты хорошо справился с заданием, герой, и тем самым доказал, что достоин примкнуть к армии Тёмной Госпожи." } }, f = { { 0.00, "Ты хорошо справилась с заданием, героиня, и тем самым доказала, что достойна примкнуть к армии Тёмной Госпожи." } } } } },
    [366] = { d = 41.0, v = "scourge-male#82", n = { x = 380 }, c = { x = { { 0.00, "Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана." }, { 12.23, "Мы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамёна Короля-лича." }, { 22.15, "Я рад, что он остался свободным." }, { 24.86, "Мы должны привлечь его на свою сторону." }, { 28.34, "Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича." }, { 36.32, "Надеюсь, что, убедившись в этом, он станет одним из нас." } } }, t = { d = 18.9, g = 1, v = "scourge-male#82", n = { m = 140, f = 141 }, c = { m = { { 0.00, "Моя книга?!" }, { 1.17, "Так это ты украл её!" }, { 3.09, "Но... что это за новые чары на ней..." }, { 6.50, "Бетор?" }, { 7.17, "Он в Лордероне?" }, { 8.59, "Если он всё ещё \"жив\", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича..." } }, f = { { 0.00, "Моя книга?!" }, { 1.24, "Так это ты украла её!" }, { 3.37, "Но... что это за новые чары на ней..." }, { 7.00, "Бетор?" }, { 7.71, "Он в Лордероне?" }, { 9.21, "Если он всё ещё \"жив\", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича..." } } } } },
    [367] = { d = 36.5, v = "scourge-male#82", n = { x = 353 }, c = { x = { { 0.00, "Леди Сильвана обратилась к Королевскому фармацевтическому обществу." }, { 5.71, "Тёмная Госпожа считает, что наши знания и новейшая магия помогут найти ключ к свержению Артаса." }, { 13.88, "Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни на Азероте – с целью уничтожения всей армии Артаса." }, { 24.14, "В своих изысканиях я обнаружил, что для этого потребуется кровь животных." }, { 30.31, "Принеси мне пять склянок крови псов тьмы, чтобы я мог провести эксперимент." } } }, t = { d = 4.6, g = 1, v = "scourge-male#82", n = { m = 40, f = 41 }, c = { m = { { 0.00, "Ты хорошо справился." }, { 2.05, "Благодарю тебя за старание." } }, f = { { 0.00, "Ты хорошо справилась." }, { 2.06, "Благодарю тебя за старание." } } } } },
    [368] = { d = 29.5, g = 1, v = "scourge-male#82", n = { m = 291, f = 292 }, c = { m = { { 0.00, "Пока ты собирал для меня образцы, я провёл исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты." }, { 11.91, "Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее." }, { 20.16, "Мне потребуется пять чешуек мурлоков из племени Злобного Плавника." }, { 25.63, "Их можно найти на берегу к северу или к западу." } }, f = { { 0.00, "Пока ты собирала для меня образцы, я провёл исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты." }, { 11.96, "Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее." }, { 20.18, "Мне потребуется пять чешуек мурлоков из племени Злобного Плавника." }, { 25.64, "Их можно найти на берегу к северу или к западу." } } }, t = { d = 5.6, v = "scourge-male#82", n = { x = 43 }, c = { x = { { 0.00, "Отличная чешуя." }, { 1.73, "Именно то, что мне нужно для микстуры." } } } } },
    [369] = { d = 36.5, v = "scourge-male#82", n = { x = 389 }, c = { x = { { 0.00, "Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней." }, { 11.95, "Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов." }, { 18.53, "Принесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент." }, { 25.46, "Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом." }, { 31.11, "Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах." } } }, t = { d = 14.6, v = "scourge-male#82", n = { x = 115 }, c = { x = { { 0.00, "Да, этот яд великолепно подойдёт!" }, { 3.40, "Я уже добавил всё остальное в мой состав и вскипятил его." }, { 9.45, "Наконец-то я испытаю эту смертельно опасную смесь!" } } } } },
    [370] = { d = 24.5, v = "scourge-male", n = { x = 252 }, c = { x = { { 0.00, "В документах палача Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях." }, { 9.05, "Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми." }, { 18.03, "Убей Перрина, трёх ревнителей и трёх миссионеров, а потом доложи мне о своём успехе." } } }, t = { d = 10.5, g = 1, v = "scourge-male", n = { x = 80 }, c = { m = { { 0.00, "Тёмная Госпожа, без сомнения, обрадуется смерти капитана Перрина." }, { 6.79, "Вы хорошо исполнили свой долг, герой." } }, f = { { 0.00, "Тёмная Госпожа, без сомнения, обрадуется смерти капитана Перрина." }, { 6.57, "Вы хорошо исполнили свой долг, героиня." } } } } },
    [371] = { d = 27.4, v = "scourge-male", n = { x = 256 }, c = { x = { { 0.00, "У нас до сих пор война, а Алый орден набирает силу." }, { 4.48, "В отчёте палача Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ фермы Балнира." }, { 19.42, "Убей Вакона и пять келейников из Алого ордена – это должно нанести ордену сокрушающий удар!" } } }, t = { d = 9.4, v = "scourge-male", n = { x = 91 }, c = { x = { { 0.00, "Смерть капитана Вакона значительно замедлит продвижение Алого ордена по Тирисфалю." }, { 7.34, "Но есть и другие угрозы." } } } } },
    [372] = { d = 24.8, v = "scourge-male", n = { x = 229 }, c = { x = { { 0.00, "Алый орден совершает набеги из своей разрушенной башни в северном Тирисфале, за могилой Фаола." }, { 8.56, "Согласно нашей информации, отвечает за эти набеги жестокий капитан Мелраш." }, { 15.35, "Я даю вам особенное и очень важное задание – убить Мелраша и двух его телохранителей во имя Тёмной Госпожи." } } }, t = { d = 15.6, g = 1, v = "scourge-male", n = { x = 142 }, c = { m = { { 0.00, "Вы отлично справились, герой." }, { 2.60, "Чем больше на стороне Отрёкшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса." }, { 12.05, "У меня хорошие предчувствия на ваш счёт." } }, f = { { 0.00, "Вы отлично справились, героиня." }, { 2.77, "Чем больше на стороне Отрёкшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса." }, { 12.27, "У меня хорошие предчувствия на ваш счёт." } } } } },
    [373] = { d = 19.9, v = "narrator", n = { x = 202 }, c = { x = { { 0.00, "Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо." }, { 7.35, "Адрес таков: \"Баросу Алекстону, главному архитектору Штормграда, в Ратуше на Соборной Площади\"." }, { 15.15, "Оно кажется написанным совсем недавно, и печать ещё свежая…" } } }, t = { d = 34.5, v = "human-male", n = { x = 372 }, c = { x = { { 0.00, "Эдвин ван Клиф, говорите?" }, { 1.79, "Я бы скорее ждал письма от своей покойной бабушки..." }, { 5.50, "Так это вы его убили?" }, { 7.10, "Извините, конечно, но я сильно удивлён." }, { 9.85, "В молодые годы он был просто непревзойдённым бойцом." }, { 13.49, "Ну, дайте-ка взглянуть, что он мне там написал после стольких лет..." }, { 18.16, "*Барос рассматривает письмо.*" }, { 20.32, "Эх, Эдвин… годы не изменили тебя ни на каплю." }, { 23.88, "Всё такой же идеалист и романтик." }, { 26.46, "Представляете, ему было всё равно, кому мстить." }, { 30.16, "Месть попросту поглотила его." }, { 32.47, "Но, кажется, я его понимаю…" } } } } },
    [374] = { d = 40.5, g = 1, v = "scourge-male", n = { x = 365 }, c = { m = { { 0.00, "Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена." }, { 6.87, "Тирисфальские леса так и кишат ими." }, { 10.10, "Вариматрас, подручный Тёмной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стёрто с лица земли." }, { 21.65, "Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден." }, { 29.41, "Помоги нам истребить их, герой." }, { 32.24, "Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Тёмной Госпоже." } }, f = { { 0.00, "Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена." }, { 6.48, "Тирисфальские леса так и кишат ими." }, { 9.52, "Вариматрас, подручный Тёмной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стёрто с лица земли." }, { 20.42, "Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден." }, { 27.73, "Помоги нам истребить их, героиня." }, { 30.55, "Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Тёмной Госпоже." } } }, t = { d = 7.0, g = 1, v = "scourge-male", n = { x = 57 }, c = { m = { { 0.00, "Вариматрас будет гордиться тобой." }, { 3.22, "Ты отлично служишь своим лидерам, герой." } }, f = { { 0.00, "Вариматрас будет гордиться тобой." }, { 3.08, "Ты отлично служишь своим лидерам, героиня." } } } } },
    [375] = { d = 43.3, v = "scourge-female#80", n = { x = 341 }, c = { x = { { 0.00, "Так холодно..." }, { 1.46, "Чума Нежити расползается по моим венам, как клубок ледяных змей, и скоро я впаду в беспамятство." }, { 11.23, "Но никакой злой рок не помешает мне нести службу нашей Тёмной Госпоже." }, { 18.26, "Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны." }, { 26.02, "Теперь мои руки дрожат от холода." }, { 29.58, "Если ты принесёшь мне пять шкурок сумеречницы и грубую нить, я сошью себе одеяло." }, { 37.70, "Помоги мне, чтобы я могла и дальше служить нашему делу." } } }, t = { d = 8.1, v = "scourge-female#80", n = { x = 69 }, c = { x = { { 0.00, "Спасибо за заботу." }, { 1.82, "Надеюсь, когда-нибудь слух о твоей храбрости дойдёт и до Сильваны..." } } } } },
    [376] = { d = 46.5, g = 1, v = "scourge-female#80", n = { m = 446, f = 447 }, c = { m = { { 0.00, "В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться." }, { 12.07, "Похоже, и ты будешь записан к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю." }, { 21.87, "В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь." }, { 31.08, "У меня заканчиваются запасы лап и крыльев, и если ты принесёшь мне немного, я найду для тебя какой-нибудь доспех." }, { 40.15, "К югу отсюда волков-падальщиков и летучих мышей предостаточно." } }, f = { { 0.00, "В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться." }, { 12.41, "Похоже, и ты будешь записана к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю." }, { 22.57, "В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь." }, { 32.04, "У меня заканчиваются запасы лап и крыльев, и если ты принесёшь мне немного, я найду для тебя какой-нибудь доспех." }, { 41.37, "К югу отсюда волков-падальщиков и летучих мышей предостаточно." } } }, t = { d = 9.8, v = "scourge-female#80", n = { x = 83 }, c = { x = { { 0.00, "Спасибо." }, { 0.85, "Держи этот доспех." }, { 2.71, "Надеюсь, тебе он послужит лучше, чем тому бедолаге, что носил его последним…" } } } } },
    [377] = { d = 30.2, v = "human-male", n = { x = 385 }, c = { x = { { 0.00, "Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева." }, { 16.39, "Вард продавал тела с кладбища Морбенту Скверну." }, { 19.51, "Подобное преступление карается смертью." }, { 22.11, "И всё же Штормград объявил Варда своим пленником." }, { 25.35, "Убей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу." } } }, t = { d = 24.2, g = 1, v = "human-male", n = { m = 286, f = 288 }, c = { m = { { 0.00, "Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества?" }, { 6.10, "Чем меньше швали, тем лучше, я так считаю." }, { 8.99, "Хвала тебе, друг мой!" }, { 10.47, "Ты не только утешил семьи покойных, ты преподал наглядный урок продажным бюрократам из Благородных домов." }, { 18.39, "Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании." } }, f = { { 0.00, "Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества?" }, { 6.06, "Чем меньше швали, тем лучше, я так считаю." }, { 8.94, "Хвала тебе, друг мой!" }, { 10.41, "Ты не только утешила семьи покойных, ты преподала наглядный урок продажным бюрократам из Благородных домов." }, { 17.70, "Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании." } } } } },
    [378] = { d = 38.0, g = 1, v = "dwarf-male", n = { m = 415, f = 416 }, c = { m = { { 0.00, "Ты доказал свою преданность королю Магни, герой." }, { 3.53, "И ты, так же как я, ненавидишь мерзавцев Чёрного Железа всем сердцем." }, { 8.28, "Я бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длинной Косой." }, { 14.57, "Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола." }, { 22.66, "А это значит, что Кам виноват в гибели брата Длинной Косы." }, { 26.90, "Пока что Кама Гневливого держат в тюрьме Штормграда." }, { 30.68, "Но такие, как он, не достойны того, чтобы жить." }, { 34.02, "Убей его." }, { 34.79, "Ради Грима!" }, { 35.69, "Принеси мне его голову!" } }, f = { { 0.00, "Ты доказала свою преданность королю Магни, героиня." }, { 3.78, "И ты, так же как я, ненавидишь мерзавцев Чёрного Железа всем сердцем." }, { 8.59, "Я бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длинной Косой." }, { 14.97, "Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола." }, { 23.17, "А это значит, что Кам виноват в гибели брата Длинной Косы." }, { 27.47, "Пока что Кама Гневливого держат в тюрьме Штормграда." }, { 31.31, "Но такие, как он, не достойны того, чтобы жить." }, { 34.70, "Убей его." }, { 35.48, "Ради Грима!" }, { 36.39, "Принеси мне его голову!" } } }, t = { d = 31.3, g = 1, v = "dwarf-male", n = { m = 334, f = 335 }, c = { m = { { 0.00, "Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть?" }, { 7.04, "Хорошо." }, { 7.64, "С этими негодяями из клана Чёрного Железа только так и надо." }, { 12.18, "Отлично потрудился, герой." }, { 14.21, "Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемом войнами." }, { 24.02, "Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан." }, { 29.23, "Брат Длинной Косы отомщён." } }, f = { { 0.00, "Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть?" }, { 7.04, "Хорошо." }, { 7.65, "С этими негодяями из клана Чёрного Железа только так и надо." }, { 12.19, "Отлично потрудилась, героиня." }, { 14.43, "Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемом войнами." }, { 24.25, "Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан." }, { 29.46, "Брат Длинной Косы отомщён." } } } } },
    [379] = { d = 23.4, v = "goblin-male", n = { x = 233 }, c = { x = { { 0.00, "Тебе нужен источник силы." }, { 1.96, "Могу помочь." }, { 2.95, "Что я хочу взамен?" }, { 4.32, "Пить!" }, { 4.71, "Принеси мне пять бурдюков с водой Скитальцев Пустыни, и я дам тебе источник энергии четыре тысячи семьсот одиннадцать-ФТЗ." }, { 13.55, "Знаешь, где взять эти меха?" }, { 15.58, "Попробуй попросить их у кочевников Скитальцев Пустыни к востоку отсюда!" }, { 20.76, "Потом расскажешь, что из этого вышло." } } }, t = { d = 30.4, v = "goblin-male", n = { x = 336 }, c = { x = { { 0.00, "Отлично, вот тебе источник энергии." }, { 2.62, "Честно говоря, он создан совсем не для исследовательского набора вроде этого, поэтому у тебя будет не так уж много времени, а потом все данные кирдыкнутся!" }, { 13.87, "Как только соберёшь всё, что нужно, принеси эту штуковину мне, чтобы я отключил её как надо." }, { 20.47, "У тебя не больше двух часов на всё про всё." }, { 23.55, "Если ты не успеешь, я, конечно, продам тебе ещё один источник энергии." }, { 28.71, "Ключевое слово – продам!" } } } } },
    [380] = { d = 38.0, v = "scourge-male", n = { x = 388 }, c = { x = { { 0.00, "Одна из наших самых серьёзных проблем – это добыча природных ресурсов, необходимых для выживания." }, { 7.76, "Золота было очень мало даже во времена расцвета Альянса." }, { 12.43, "К северо-западу отсюда есть золотой рудник, но он весь кишит пауками." }, { 17.96, "Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари." }, { 26.37, "У меня не так много рабочих рук для этой задачи, так что придётся действовать постепенно." }, { 33.34, "Отправляйся туда – может быть, ты сможешь чем-то помочь нам." } } }, t = { d = 21.0, g = 1, v = "scourge-male", n = { m = 200, f = 201 }, c = { m = { { 0.00, "Ну что же, для начала неплохо." }, { 2.58, "Очистка всей территории займёт несколько недель или даже месяцев." }, { 8.29, "А после этого, нам придётся пойти туда с факелами, чтобы сжечь паутину." }, { 14.47, "Ты отлично справился, я уверен, что подыщу для тебя ещё какую-нибудь работёнку." } }, f = { { 0.00, "Ну что же, для начала неплохо." }, { 2.54, "Очистка всей территории займёт несколько недель или даже месяцев." }, { 8.17, "А после этого, нам придётся пойти туда с факелами, чтобы сжечь паутину." }, { 14.25, "Ты отлично справилась, я уверен, что подыщу для тебя ещё какую-нибудь работёнку." } } } } },
    [381] = { d = 46.1, g = 1, v = "scourge-male", n = { m = 459, f = 459 }, c = { m = { { 0.00, "Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям." }, { 11.09, "Теперь мы можем позаботиться и о других делах." }, { 14.96, "Мои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда." }, { 22.86, "Алый орден – достойная презрения организация, ведущая охоту на нас." }, { 28.44, "Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет." }, { 38.12, "Мы должны первыми нанести удар!" }, { 40.80, "Будь осторожен, нечестивое рвение делает их опасными противниками." } }, f = { { 0.00, "Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям." }, { 11.00, "Теперь мы можем позаботиться и о других делах." }, { 14.84, "Мои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда." }, { 22.66, "Алый орден – достойная презрения организация, ведущая охоту на нас." }, { 28.19, "Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет." }, { 37.79, "Мы должны первыми нанести удар!" }, { 40.45, "Будь осторожна, нечестивое рвение делает их опасными противниками." } } }, t = { d = 13.0, v = "scourge-male", n = { x = 115 }, c = { x = { { 0.00, "Если б только они послушались доводов разума, а?" }, { 4.51, "Может быть, мы могли бы уговорить их всё серьёзно обсудить..." }, { 9.92, "Как же!" }, { 10.58, "Идиоты, ослеплённые светом..." } } } } },
    [382] = { d = 33.8, v = "scourge-male", n = { x = 329 }, c = { x = { { 0.00, "В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из их монастыря к Могильнику." }, { 10.11, "Судя по этим сообщениям, гонец несёт важную информацию." }, { 14.85, "Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить!" }, { 21.67, "А ты, наиболее квалифицированная особа, которую я могу послать на это задание." }, { 28.33, "Найди гонца и принеси мне информацию, которую тебе удастся найти." } } }, t = { d = 36.6, g = 1, v = "scourge-male", n = { m = 270, f = 270 }, c = { m = { { 0.00, "Хмм..." }, { 0.78, "Ну-ка, посмотрим, что ты там нашёл..." }, { 5.12, "*Аррен пробегает глазами документы, принесённые вами.*" }, { 9.20, "Новости об их успехах в борьбе с нами..." }, { 12.81, "Ценности не имеют." }, { 14.50, "Донесения разведки..." }, { 16.42, "Новые приказы..." }, { 17.95, "\"Продолжайте организацию лагеря около разрушенного города...\" Ничего такого, о чём мы не знали бы..." }, { 26.77, "А это ещё что?" }, { 28.06, "Карта местонахождения некоторых полевых командиров и агентов!" }, { 33.51, "Это можно будет использовать." } }, f = { { 0.00, "Хмм..." }, { 0.92, "Ну-ка, посмотрим, что ты там нашла..." }, { 6.16, "*Аррен пробегает глазами документы, принесённые вами.*" }, { 10.16, "Новости об их успехах в борьбе с нами..." }, { 13.71, "Ценности не имеют." }, { 15.36, "Донесения разведки..." }, { 17.25, "Новые приказы..." }, { 18.75, "\"Продолжайте организацию лагеря около разрушенного города...\" Ничего такого, о чём мы не знали бы..." }, { 27.42, "А это ещё что?" }, { 28.68, "Карта местонахождения некоторых полевых командиров и агентов!" }, { 34.04, "Это можно будет использовать." } } } } },
    [383] = { d = 42.9, g = 1, v = "scourge-male", n = { m = 417, f = 419 }, c = { m = { { 0.00, "Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл." }, { 5.03, "Обладая этой информацией, он сможет нанести решающий удар по Алому ордену." }, { 10.90, "Ты сильно помог нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдётся более серьёзная работа." }, { 23.41, "Иди по дороге из Могильника на север." }, { 26.35, "Вскоре после того, как дойдёшь до Тирисфаля, наткнёшься на перекрёсток." }, { 31.66, "Сверни на восток и продолжай идти в том же направлении." }, { 35.93, "По дороге как раз и будет поместье \"Остывший очаг\"." } }, f = { { 0.00, "Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл." }, { 5.41, "Обладая этой информацией, он сможет нанести решающий удар по Алому ордену." }, { 11.72, "Ты сильно помогла нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдётся более серьёзная работа." }, { 25.31, "Иди по дороге из Могильника на север." }, { 28.46, "Вскоре после того, как дойдёшь до Тирисфаля, наткнёшься на перекрёсток." }, { 34.17, "Сверни на восток и продолжай идти в том же направлении." }, { 38.75, "По дороге как раз и будет поместье \"Остывший очаг\"." } } }, t = { d = 22.6, g = 1, v = "scourge-male", n = { m = 188, f = 189 }, c = { m = { { 0.00, "О, прекрасно!" }, { 1.34, "Ты отлично потрудился, добывая эту информацию." }, { 5.97, "Хмм..." }, { 6.59, "Имена офицеров в Тирисфальских лесах…" }, { 10.34, "Представь, какой удар мы можем нанести по боевому духу этих фанатиков, если убьём всех их лидеров одним стремительным ударом." } }, f = { { 0.00, "О, прекрасно!" }, { 1.28, "Ты отлично потрудилась, добывая эту информацию." }, { 5.80, "Хмм..." }, { 6.40, "Имена офицеров в Тирисфальских лесах…" }, { 9.98, "Представь, какой удар мы можем нанести по боевому духу этих фанатиков, если убьём всех их лидеров одним стремительным ударом." } } } } },
    [384] = { d = 29.3, v = "dwarf-male", n = { x = 340 }, c = { x = { { 0.00, "Завсегдатаи моей таверны больше всего любят кабаньи рёбрышки в пиве!" }, { 4.89, "Беда в том, что местный охотник, который снабжал меня кабанятиной, теперь завербован в королевскую армию, чтобы помочь Альянсу." }, { 13.92, "Может, ты мне поможешь?" }, { 15.57, "Если принесёшь мне шесть рёбер скального вепря и \"Болтливое пиво\" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых рёбрышек в пиве, не говоря уж о дармовой порции!" }, { 28.15, "Вся соль – в пиве!" } } }, t = { d = 10.8, v = "dwarf-male", n = { x = 107 }, c = { x = { { 0.00, "Сварено пиво, разлито по кружкам," }, { 2.85, "Эй, не деритесь, друзья и подружки!" }, { 5.78, "Каждому выделим по половине" }, { 8.10, "Вкуснейшей порции рёбрышек в пиве!" } } } } },
    [385] = { d = 33.1, v = "dwarf-male", n = { x = 386 }, c = { x = { { 0.00, "Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков." }, { 5.50, "Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса." }, { 13.88, "Мы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок." }, { 24.76, "Но если хочешь отправиться на охоту, я не стану тебя отговаривать." }, { 29.49, "Это действительно незабываемо." }, { 31.66, "Я и сам в своё время..." } } }, t = { d = 5.3, g = 1, v = "dwarf-male", n = { m = 47, f = 48 }, c = { m = { { 0.00, "Ты отлично поохотился." }, { 2.10, "За хорошую работу и платят хорошо!" } }, f = { { 0.00, "Ты отлично поохотилась." }, { 2.15, "За хорошую работу и платят хорошо!" } } } } },
    [386] = { d = 33.5, v = "human-male", n = { x = 399 }, c = { x = { { 0.00, "Таргорр Ужасный служил под началом Гат'Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью." }, { 8.70, "По его прихоти отважных бойцов Королевства подвергали страшным пыткам." }, { 13.68, "Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни." }, { 19.16, "Но происходит что-то странное." }, { 21.31, "Один из знатных людей запретил его казнить." }, { 24.46, "Уверен, дело нечисто." }, { 26.04, "Положи конец Таргорру Ужасному." }, { 28.30, "Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства." } } }, t = { d = 15.5, v = "human-male", n = { x = 173 }, c = { x = { { 0.00, "Наконец-то Таргорр Ужасный получил по заслугам." }, { 3.56, "Я рад, что злодей угодил в лапы Смерти." }, { 6.52, "Молодец." }, { 7.19, "Иной раз подлинное правосудие можно отыскать лишь за стенами залов суда, вдали от замутнённого взора политиканов." } } } } },
    [387] = { d = 25.8, v = "human-male", n = { x = 302 }, c = { x = { { 0.00, "Бунт должен быть подавлен!" }, { 1.83, "И ты мне в этом поможешь." }, { 3.60, "Если станет известно, что в тюрьме случился бунт, я потеряю работу." }, { 8.33, "Это исключительная подлость!" }, { 10.35, "Самое важное сейчас – немедленно взять тюрьму под контроль." }, { 14.52, "Ради безопасности Штормграда." }, { 16.61, "Наказание за бунт в тюрьме – смертная казнь." }, { 19.64, "Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдёт в норму." } } }, t = { d = 10.1, g = 1, v = "human-male", n = { m = 115, f = 117 }, c = { m = { { 0.00, "Ты отлично проявил себя в тюрьме." }, { 2.44, "Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработал, и я тебе очень благодарен." } }, f = { { 0.00, "Ты отлично проявила себя в тюрьме." }, { 2.48, "Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработала, и я тебе очень благодарен." } } } } },
    [388] = { d = 35.9, v = "human-female#47", n = { x = 389 }, c = { x = { { 0.00, "Кровь моя стынет в жилах от ужасного горя..." }, { 3.25, "Мой внук Мак… он был такой чудесный мальчик." }, { 6.37, "Всего четырнадцать лет." }, { 8.06, "Когда армия ушла на фронт, он счёл, что должен защитить город." }, { 12.54, "Он был охранником в тюрьме, куда прибыла партия заключённых из Братства Справедливости." }, { 18.71, "Мак наказал некоторых заключённых за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды." }, { 27.49, "За это он получил нож в спину." }, { 29.70, "Я хочу мести." }, { 30.74, "Принесите мне десять этих проклятых шерстяных бандан." }, { 34.64, "Они цвета крови..." } } }, t = { d = 15.4, v = "human-female#47", n = { x = 157 }, c = { x = { { 0.00, "Значит, из-за этих жалких тряпиц они убили моего Мака..." }, { 4.57, "Ужасная, нелепая смерть!.." }, { 6.58, "Увы, мне не дано изменить прошлое." }, { 9.28, "Но я благодарна вам, за то что вам удалось воздать по заслугам убийцам моего внука." } } } } },
    [389] = { d = 30.7, v = "human-male", n = { x = 377 }, c = { x = { { 0.00, "Ван Клиф и я были членами гильдии каменщиков." }, { 3.07, "Это мы восстанавливали Штормград после войны." }, { 6.21, "Когда мы закончили работу, вельможи отказались платить нам за неё." }, { 10.70, "Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии." }, { 19.98, "Он поднял мятеж и покинул город, поклявшись отомстить." }, { 23.73, "Его лейтенант, Базиль Тредд, много знает о планах своего командира." }, { 28.40, "Базиль содержится в плену в тюрьме." } } }, t = { d = 16.6, v = "human-male", n = { x = 188 }, c = { x = { { 0.00, "Чего, во имя Света, тебе надо?" }, { 2.20, "Не видишь, тут и без тебя проблем хватает?" }, { 5.08, "Базиль Тредд?!" }, { 6.06, "Какое тебе дело до этого мерзавца?" }, { 8.51, "Или ты – из его поганых кровавых соратничков?" }, { 11.64, "Не будь у меня тут все камеры заняты, я бы тебя точно засунул в одну из них!" } } } } },
    [391] = { d = 22.0, v = "human-male", n = { x = 228 }, c = { x = { { 0.00, "Скажу тебе сразу: я тебе ни капли не доверяю." }, { 3.53, "Но в нынешней ситуации это не особо важно." }, { 6.79, "Что от тебя требуется: иди и поговори с Треддом." }, { 10.46, "Если ты и вправду на нашей стороне, убей его и принеси мне его голову." }, { 15.90, "А если ты на их стороне и не вернёшься вовремя, то будешь долго, долго гнить заживо…" } } }, t = { d = 22.2, v = "human-male", n = { x = 245 }, c = { x = { { 0.00, "Без Тредда бунтовщики станут куда более управляемыми." }, { 3.90, "Посмотрим..." }, { 4.82, "Должен сказать, я уже через полчаса решил, что больше тебя не увижу… но, надо признать, я в тебе ошибся." }, { 12.49, "Думаю, тебе не удалось из него ничего вытянуть..." }, { 16.14, "А вот я знаю пару вещей насчёт деятельности Тредда, которые тебя могут заинтересовать." } } } } },
    [392] = { d = 30.7, v = "human-male", n = { x = 352 }, c = { x = { { 0.00, "Во время первого года заключения Тредда никто его не навещал." }, { 4.46, "Мне казалось, что братство отказалось от него, поскольку он стал бесполезен." }, { 9.76, "Но пару месяцев назад его стали постоянно навещать – раз, два в неделю." }, { 14.86, "Посетитель был весьма странный." }, { 17.09, "Такой тихий тип." }, { 18.30, "У меня возникли подозрения, но все его документы были в полном порядке." }, { 23.40, "Согласно документам, звали его Мелик; вот его описание." }, { 27.42, "Не думаю, что он ещё когда-нибудь придёт к Тредду." } } }, t = { d = 19.6, v = "human-male", n = { x = 213 }, c = { x = { { 0.00, "Мелик?" }, { 0.53, "Нет, это имя мне незнакомо и даже ни на какие мысли не наводит." }, { 5.22, "Это может быть кто угодно!" }, { 7.20, "Бывший каменщик, один из членов Братства Справедливости..." }, { 11.49, "Хотя если он тесно связан с ними, как предполагает Телуотер, кто-нибудь может опознать его." }, { 18.29, "Мне нужно подумать." } } } } },
    [393] = { d = 25.9, v = "human-male", n = { x = 274 }, c = { x = { { 0.00, "Знаете ли, мне так ничего и не пришло в голову." }, { 3.35, "Но есть один человек, который может вам помочь, – так уж вышло, что он мне кое-чем обязан... впрочем, не будем об этом." }, { 11.81, "Матиас Шоу из ШРУ – его можно найти в казармах Старого города." }, { 16.71, "Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки." }, { 22.77, "Если кто-то и знает, о ком речь, то только он." } } }, t = { d = 31.9, v = "human-male", n = { x = 361 }, c = { x = { { 0.00, "Что это?" }, { 0.64, "Да, думаю, что знаю этого человека, но его зовут вовсе не Мелик." }, { 5.33, "Наёмные убийцы носят много масок, зовутся множеством имён и забывают их, как только они становятся не нужны." }, { 13.04, "Этот человек также известен под именем Марзон; вероятно, это его очередной псевдоним." }, { 19.28, "В общем, он – наёмный убийца, и я о нём довольно много знаю." }, { 23.52, "Марзон сейчас работает на Грегора Лесковара – человека с репутацией, дурной даже для коррумпированного лорда Штормграда." } } } } },
    [394] = { d = 25.4, v = "human-male#50", n = { x = 297 }, c = { x = { { 0.00, "Найдите Шоу в Старом городе." }, { 2.05, "Дайте ему знать, что с Лесковаром покончено, и о вашей причастности к заговору лордов против города." }, { 8.96, "Я думаю, он будет рад, что среди горожан Штормграда есть ещё герои." }, { 13.56, "Думаю, он отправит вас на встречу с принцем или другим лордом." }, { 17.91, "Только не зазнавайтесь." }, { 19.53, "Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны." } } }, t = { d = 22.5, g = 1, v = "human-male", n = { m = 227, f = 229 }, c = { m = { { 0.00, "Значит, мёртв?" }, { 1.23, "Ты скор на расправу." }, { 2.92, "Не хотел бы я стать твоим врагом." }, { 5.68, "*Смеётся и кладёт руку вам на плечо.*" }, { 8.88, "Не прими за осуждение." }, { 10.49, "Я же глава наёмных убийц, как я могу осуждать тебя за чистое убийство?" }, { 15.53, "По правде сказать, ты оказал людям Штормграда огромную услугу, и я благодарю тебя за это." } }, f = { { 0.00, "Значит, мёртв?" }, { 1.28, "Ты скора на расправу." }, { 3.20, "Не хотел бы я стать твоим врагом." }, { 6.08, "*Смеётся и кладёт руку вам на плечо.*" }, { 9.44, "Не прими за осуждение." }, { 11.06, "Я же глава наёмных убийц, как я могу осуждать тебя за чистое убийство?" }, { 16.10, "По правде сказать, ты оказала людям Штормграда огромную услугу, и я благодарю тебя за это." } } } } },
    [395] = { d = 30.6, v = "human-male", n = { x = 326 }, c = { x = { { 0.00, "Ах, да..." }, { 0.67, "Пока тебя не было, приходил Алекстон, хотел с тобой поговорить." }, { 5.51, "Должно быть, это касалось Братства Справедливости." }, { 9.28, "Позволь дать тебе совет: на твоём месте я бы по первой просьбе рассказал обо всём произошедшем в подробностях – обо всём, кроме того, что Лесковара сразила именно твоя рука." }, { 22.05, "Можешь мне верить – я на таких вещах собаку съел." }, { 25.75, "А что касается Триаса... ну, не говори о нём." }, { 29.04, "Никогда." }, { 29.71, "Если сможешь." } } }, t = { d = 14.9, v = "human-male", n = { x = 171 }, c = { x = { { 0.00, "Приятно тебя видеть снова." }, { 1.98, "Мне довелось услышать о недавней кончине лорда Грегора Лесковара." }, { 6.65, "Значит, твоя миссия оказалась успешной." }, { 9.53, "Я щедро награжу тебя за спасение и меня, и многих прочих от мести ван Клифа." } } } } },
    [396] = { d = 20.1, v = "human-male", n = { x = 251 }, c = { x = { { 0.00, "Я готовлю донесение для короля." }, { 2.14, "Надеюсь, ты сумеешь преподнести его величеству всё в лучшем виде." }, { 6.60, "Не переживай так, король обязательно оценит твоё благородное служение народу Штормграда и достойно наградит тебя." }, { 14.23, "Срок твоей аудиенции близок, так что поторопись, чтобы не опоздать в Крепость Штормграда." } } }, t = { d = 22.5, g = 1, v = "human-female#45", n = { x = 268 }, c = { m = { { 0.00, "Я щедро награжу вас за службу Штормграду." }, { 2.85, "Если ван Клиф преуспел в своих махинациях, то у нас ещё будет немало трудностей." }, { 8.31, "Этого мы должны избежать." }, { 10.10, "Возьмите этот жетон в знак королевской благосклонности, герой." }, { 14.38, "Сожалею, что король не смог вручить его вам лично, но он сейчас занят на дипломатических переговорах и ещё не освободился." } }, f = { { 0.00, "Я щедро награжу вас за службу Штормграду." }, { 2.84, "Если ван Клиф преуспел в своих махинациях, то у нас ещё будет немало трудностей." }, { 8.26, "Этого мы должны избежать." }, { 10.05, "Возьмите этот жетон в знак королевской благосклонности, героиня." }, { 14.42, "Сожалею, что король не смог вручить его вам лично, но он сейчас занят на дипломатических переговорах и ещё не освободился." } } } } },
    [397] = { d = 15.8, g = 1, v = "human-male#50", n = { m = 179, f = 181 }, c = { m = { { 0.00, "Я слышал, что Лорд Вишлок в восторге от напитка." }, { 3.47, "Ты нам здорово помог." }, { 5.04, "Теперь чернокнижники Штормграда смогут заниматься своим делом без помех." }, { 10.33, "За свою службу ты получишь достойный подарок." }, { 13.67, "Поговори с Згги, моим слугой." } }, f = { { 0.00, "Я слышал, что Лорд Вишлок в восторге от напитка." }, { 3.45, "Ты нам здорово помогла." }, { 5.15, "Теперь чернокнижники Штормграда смогут заниматься своим делом без помех." }, { 10.43, "За свою службу ты получишь достойный подарок." }, { 13.75, "Поговори с Згги, моим слугой." } } }, t = { d = 8.6, v = "goblin-male", n = { x = 86 }, c = { x = { { 0.00, "Хозяин дал подарок для тебя." }, { 2.28, "Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина." } } } } },
    [398] = { d = 31.6, v = "narrator", n = { x = 320 }, c = { x = { { 0.00, "Разыскивается: Червеглаз!" }, { 2.07, "Ужасное даже по меркам гноллов чудовище – Червеглаз – приговорён к смерти за его преступления против Отрёкшихся." }, { 11.18, "Этот гнусный злодей воровал трупы для армии Короля-лича." }, { 15.99, "Червеглаза видели близ Фермы Гаррена, к северу от Брилла." }, { 20.73, "Город Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить палачу Зуганду его лапу." }, { 29.61, "Милосердие – удел слабых." } } }, t = { d = 14.6, v = "scourge-male", n = { x = 134 }, c = { x = { { 0.00, "Наконец-то Червеглаз получил по заслугам." }, { 3.83, "Пусть твой поступок запомнится всем, кто захочет навредить нашему народу!" }, { 10.48, "Благодарю тебя от имени всего города Брилла." } } } } },
    [399] = { d = 33.5, v = "human-male", n = { x = 388 }, c = { x = { { 0.00, "С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность." }, { 5.77, "Говорят, нельзя вернуться в прошлое – и это верно." }, { 9.34, "Дважды верно, если говорить обо мне – ведь мой родной дом был разграблен ворами и сожжён." }, { 15.48, "Я спросил у отца о судьбе некоторых моих вещей, например, о моём первом компасе." }, { 21.13, "Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме." }, { 27.08, "Поместье Алекстона расположено к западу от Сторожевого холма." }, { 31.34, "Может быть, ты найдёшь мой компас?" } } }, t = { d = 15.6, v = "human-male", n = { x = 187 }, c = { x = { { 0.00, "Благодарю вас!" }, { 0.98, "Совершенно бесполезная вещь, не считая воспоминаний..." }, { 4.61, "Нет слов, как я благодарен за то, что принесли мне этот предмет; вам, конечно, трудно понять цену памяти о Западном Крае." }, { 12.79, "Возьмите это в знак моей признательности..." } } } } },
    [400] = { d = 37.6, v = "dwarf-male", n = { x = 461 }, c = { x = { { 0.00, "Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам!" }, { 6.26, "Но своего инструмента он не жалеет." }, { 8.63, "Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые!" }, { 16.59, "Мы только что выполнили его очередной заказ." }, { 19.63, "Если ты его доставишь, я уверен, мастер заплатит тебе за труды." }, { 24.01, "Ты сможешь найти Сталежара к северо-востоку от Караноса." }, { 27.83, "Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работёнка подвернётся." } } }, t = { d = 18.3, g = 1, v = "dwarf-male", n = { m = 206, f = 210 }, c = { m = { { 0.00, "У тебя мои инструменты?" }, { 1.71, "Отлично, парень, отлично!" }, { 3.54, "Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца." }, { 12.65, "Славно, что ты принёс мне эти инструменты." }, { 15.56, "Вот, возьми эти деньги; спасибо!" } }, f = { { 0.00, "У тебя мои инструменты?" }, { 1.73, "Отлично, девчушка, отлично!" }, { 3.72, "Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца." }, { 12.95, "Славно, что ты принесла мне эти инструменты." }, { 16.09, "Вот, возьми эти деньги; спасибо!" } } } } },
    [401] = { d = 5.8, v = "human-male", n = { x = 72 }, c = { x = { { 0.00, "Я почти закончил работу над переводом записки." }, { 3.13, "Она будет готова через несколько минут." } } }, t = { d = 10.1, v = "human-male", n = { x = 77 }, c = { x = { { 0.00, "Ну вот." }, { 1.00, "Готово…" }, { 2.00, "*Вокруг воцаряется душная тишина, словно на лес опустился тёмный тяжёлый полог...*" } } } } },
    [403] = { t = { d = 6.7, v = "narrator", n = { x = 67 }, c = { x = { { 0.00, "Этот бочонок эля охраняет Ярвен Громовар." }, { 3.51, "Пока он в подвале, до бочек не добраться." } } } } },
    [404] = { d = 25.4, v = "scourge-male", n = { x = 231 }, c = { x = { { 0.00, "Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста." }, { 9.32, "Отправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли." }, { 17.26, "Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти." } } }, t = { d = 7.6, v = "scourge-male", n = { x = 66 }, c = { x = { { 0.00, "Отличная работа." }, { 1.64, "Жаль, я не видел, как ты расправляешься с этими гнусными тварями!" } } } } },
    [405] = { d = 39.0, g = 1, v = "scourge-male#82", n = { x = 361 }, c = { m = { { 0.00, "Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью." }, { 12.81, "Ты, как раз подходишь для этого." }, { 15.54, "Отнеси эти приказы Бетору, а он расскажет, в чём состоит твоя миссия." }, { 21.63, "Деталей я не знаю, могу сказать лишь то, что речь пойдёт о вербовке заблудшего лича." }, { 28.81, "Это очень опасное дело." }, { 31.00, "Приготовься как следует, герой." }, { 33.73, "Не подведи нас." }, { 35.06, "Бетора можно найти в квартале Магов Подгорода." } }, f = { { 0.00, "Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью." }, { 12.55, "Ты, как раз подходишь для этого." }, { 15.22, "Отнеси эти приказы Бетору, а он расскажет, в чём состоит твоя миссия." }, { 21.19, "Деталей я не знаю, могу сказать лишь то, что речь пойдёт о вербовке заблудшего лича." }, { 28.23, "Это очень опасное дело." }, { 30.37, "Приготовься как следует, героиня." }, { 33.20, "Не подведи нас." }, { 34.50, "Бетора можно найти в квартале Магов Подгорода." } } }, t = { d = 16.7, v = "scourge-male#82", n = { x = 128 }, c = { x = { { 0.00, "А, так тебя прислал мировой судья Севрен." }, { 4.29, "Тогда да, дело у нас с тобой очень важное." }, { 8.67, "Уверен, Севрен выбрал того, кто справится с моим заданием, но… ладно, посмотрим." } } } } },
    [407] = { d = 37.4, v = "scourge-male#82", n = { x = 366 }, c = { x = { { 0.00, "Безвредные тыковки, да?" }, { 1.93, "Это только так кажется." }, { 3.93, "Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития." }, { 14.23, "Чуть-чуть смекалки, и простая тыква превратится в шпиона Тёмной Госпожи." }, { 20.17, "С помощью моей последней формулы эта тыква станет лакомым блюдом." }, { 25.73, "Вот недавно мы поймали ещё одного ревнителя из Алого ордена, сейчас он сидит в погребе таверны \"Петля Висельника\"." }, { 35.14, "Иди, отнеси ему эту тыкву." } } }, t = { d = 5.9, v = "human-male", n = { x = 48 }, c = { x = { { 0.00, "Благословенный Свет!" }, { 2.06, "Наконец-то еда!" }, { 3.75, "Сладенькая тыквочка..." } } } } },
    [408] = { d = 33.6, g = 1, v = "scourge-male#82", n = { m = 351, f = 351 }, c = { m = { { 0.00, "Мельницы Агамондов превратились в крепость Плети." }, { 4.01, "Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом." }, { 15.16, "С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас." }, { 22.82, "Ты не должен допустить этого." }, { 25.22, "Отправляйся в склеп Агамондов и убей их неупокоенных предков." }, { 30.11, "А заодно принеси мне череп капитана Даргола." } }, f = { { 0.00, "Мельницы Агамондов превратились в крепость Плети." }, { 3.98, "Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом." }, { 15.06, "С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас." }, { 22.66, "Ты не должна допустить этого." }, { 25.04, "Отправляйся в склеп Агамондов и убей их неупокоенных предков." }, { 29.89, "А заодно принеси мне череп капитана Даргола." } } }, t = { d = 16.6, v = "scourge-male#82", n = { x = 150 }, c = { x = { { 0.00, "Твои действия нанесли Плети ощутимый удар!" }, { 4.02, "И твоя победа не будет забыта ни Отрёкшимися, ни врагами." }, { 9.18, "Продолжай бороться вместе с нами, и когда-нибудь мы изгоним Короля-лича из Азерота!" } } } } },
    [409] = { d = 38.6, g = 1, v = "scourge-male#82", n = { m = 342, f = 342 }, c = { m = { { 0.00, "Ты говоришь, что неподвластен воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают." }, { 9.96, "Но прежде чем я поверю тебе, ты должен доказать то, что являешься врагом Плети." }, { 17.09, "На южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара." }, { 27.62, "Возьми из этого ящика манящую свечу, зажги её на алтаре, и Лилит пробудится." }, { 34.59, "Убей её, и я поверю, что ты – враг Короля-лича." } }, f = { { 0.00, "Ты говоришь, что неподвластна воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают." }, { 9.78, "Но прежде чем я поверю тебе, ты должна доказать то, что являешься врагом Плети." }, { 16.77, "На южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара." }, { 27.11, "Возьми из этого ящика манящую свечу, зажги её на алтаре, и Лилит пробудится." }, { 33.95, "Убей её, и я поверю, что ты – враг Короля-лича." } } }, t = { d = 20.9, g = 1, v = "scourge-male#82", n = { m = 174, f = 176 }, c = { m = { { 0.00, "Невероятно!" }, { 1.12, "Ты убил Лилит Нефару и тем самым доказал, что являешься врагом Плети!" }, { 7.85, "Я думал, что я – единственный из нежити, обладающий свободой воли, но теперь вижу, что есть и другие, кто не поддался влиянию Короля-лича." } }, f = { { 0.00, "Невероятно!" }, { 1.12, "Ты убила Лилит Нефару и тем самым доказала, что являешься врагом Плети!" }, { 7.99, "Я думал, что я – единственный из нежити, обладающий свободой воли, но теперь вижу, что есть и другие, кто не поддался влиянию Короля-лича." } } } } },
    [410] = { t = { d = 4.6, v = "narrator", n = { x = 39 }, c = { x = { { 0.00, "Вы ставите на стол Манящую свечу и зажигаете её..." } } } } },
    [411] = { d = 11.8, v = "scourge-male#82", n = { x = 107 }, c = { x = { { 0.00, "Отнеси этот самоцвет Пустоты моему старому товарищу Бетору." }, { 5.48, "С его помощью мы сможем общаться, а мне очень многое надо ему сказать." } } }, t = { d = 10.2, g = 1, v = "scourge-male#82", n = { m = 90, f = 91 }, c = { m = { { 0.00, "Ты убедил его присоединиться к нам!" }, { 3.25, "Это огромная радость для всех Отрёкшихся." }, { 7.00, "Я доложу об этом Тёмной Госпоже." } }, f = { { 0.00, "Ты убедила его присоединиться к нам!" }, { 3.41, "Это огромная радость для всех Отрёкшихся." }, { 7.25, "Я доложу об этом Тёмной Госпоже." } } } } },
    [412] = { d = 34.6, v = "gnome-male", n = { x = 440 }, c = { x = { { 0.00, "При дальнейшем анализе гномреганской ситуации оказалось, что нам не только не удалось извести троггов, но мы случайно превратили большую часть представителей нашей расы в ужасающих, безмозглых, злобных лепрогномов!" }, { 14.22, "Мы с Оззи намерены направить в обратную сторону ужасный эффект лепры при помощи нашего последнего изобретения – перенаправлятора." }, { 22.91, "Эта машина почти закончена, но нам чрезвычайно нужны зубцы рестабилизации и гиромеханические шестерни." }, { 29.78, "Добудь их у лепрогномов, которые обитают около Гномрегана, и принеси нам!" } } }, t = { d = 17.8, v = "gnome-male", n = { x = 234 }, c = { x = { { 0.00, "Эти гиромеханические шестерни и зубцы рестабилизации прекрасно подходят к чертежу Оззи для устройства Перенаправления." }, { 7.87, "Как только я залью гидросмазку во внутренние клапаны сгорания, подкручу кривохраповик и повышу вязкость электрогуммигеля, раса гномов будет возрождена." } } } } },
    [413] = { d = 24.7, v = "dwarf-male", n = { x = 292 }, c = { x = { { 0.00, "Хотелось бы мне, чтобы мой братец Велларт попробовал свежего \"Мерцающего портера\"." }, { 5.63, "Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан." }, { 13.11, "Может, он и не такой пивовар, как остальные Ячменовары, но своё пиво он любит, и я знаю, что это тоже ему понравится." }, { 21.15, "Не отнесёшь ему вот этот бочонок \"Мерцающего портера\"?" } } }, t = { d = 5.8, v = "dwarf-male", n = { x = 92 }, c = { x = { { 0.00, "Ох-х." }, { 1.03, "Аж искры из глаз!" }, { 2.53, "Кажется, я даже в темноте видеть могу!" } } } } },
    [414] = { d = 33.6, v = "dwarf-male", n = { x = 377 }, c = { x = { { 0.00, "Я бы и ещё отхлебнул \"Мерцающего портера\" с пивоварни моего братца – забористое же пойло!" }, { 6.22, "Но я хочу, чтобы мой приятель-пехотинец попробовал его." }, { 10.16, "Зовут парня Кэдрелл, и он обычно патрулирует дорогу через Телсамар в Лок Модане." }, { 15.90, "Чтобы добраться до Телсамара, иди на юго-восток через туннель, затем на развилке возьми на северо-восток." }, { 23.79, "И по той дороге иди прямо до Телсамара." }, { 27.01, "Отдай горному пехотинцу Кэдреллу этот бочонок \"Мерцающего портера\", и посмотрим, что он скажет!" } } }, t = { d = 11.7, v = "dwarf-male", n = { x = 99 }, c = { x = { { 0.00, "Ну-с, попробуем..." }, { 1.70, "Клянусь бородой Магни!" }, { 3.92, "Аж голова кругом пошла!" }, { 6.22, "И в теле лёгкость необыкновенная." }, { 9.29, "Сейчас полечу, как птичка!" } } } } },
    [415] = { d = 17.7, g = 1, v = "dwarf-male", n = { m = 208, f = 210 }, c = { m = { { 0.00, "Регольд Ячменовар, что живёт в Посёлке Пивоваров, спрашивал про тебя." }, { 4.64, "Он хочет поговорить с тобой про своё новое пиво..." }, { 8.11, "Сказал вроде, что ты ему помог." }, { 10.33, "Можешь самолично вернуться в Посёлок Пивоваров и спросить, что ему надо." }, { 15.28, "Может, тебя дармовая выпивка ждёт..." } }, f = { { 0.00, "Регольд Ячменовар, что живёт в Посёлке Пивоваров, спрашивал про тебя." }, { 4.61, "Он хочет поговорить с тобой про своё новое пиво..." }, { 8.05, "Сказал вроде, что ты ему помогла." }, { 10.39, "Можешь самолично вернуться в Посёлок Пивоваров и спросить, что ему надо." }, { 15.30, "Может, тебя дармовая выпивка ждёт..." } } }, t = { d = 13.0, g = 1, v = "dwarf-male", n = { m = 146, f = 148 }, c = { m = { { 0.00, "Помнишь тот звездолист, что ты принёс мне?" }, { 2.89, "Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно!" }, { 10.52, "Вот, попробуй и скажи, как пошло..." } }, f = { { 0.00, "Помнишь тот звездолист, что ты принесла мне?" }, { 3.03, "Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно!" }, { 10.56, "Вот, попробуй и скажи, как пошло..." } } } } },
    [416] = { d = 25.1, v = "dwarf-male", n = { x = 292 }, c = { x = { { 0.00, "К западу отсюда началось настоящее нашествие." }, { 3.37, "Эти крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю!" }, { 12.37, "Их необходимо истребить." }, { 14.15, "Перебей их как можно больше, принеси в доказательство уши и получишь награду." }, { 19.84, "Кобольды-туннельщики поселились к западу от Телсамара вдоль горных склонов." } } }, t = { d = 8.5, v = "dwarf-male", n = { x = 79 }, c = { x = { { 0.00, "Фу!" }, { 0.31, "Когда я просил принести уши, я не подозревал, что они так дурно пахнут!" }, { 6.42, "Прими награду." }, { 7.72, "Молодчина." } } } } },
    [417] = { d = 26.6, v = "narrator", n = { x = 261 }, c = { x = { { 0.00, "Хилдельв пишет в своём журнале, что подвергся нападению Паршивого Когтя, \"огромного медведя-ледолапа\"." }, { 8.58, "Он отогнал тварь, но та успела страшно изранить его." }, { 12.98, "Судя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его." }, { 19.96, "В журнале Хилдельв записал своё последнее пожелание:" }, { 24.37, "\"Отомстить Паршивому Когтю.\"" } } }, t = { d = 12.8, v = "dwarf-male", n = { x = 139 }, c = { x = { { 0.00, "Злая весть." }, { 0.89, "Хилдельв был хорошим другом." }, { 3.07, "Жаль, что не довелось мне с тобой пойти на этого Паршивого Когтя!" }, { 7.97, "Спасибо тебе." }, { 9.06, "Пилоты Осадной бригады Стальгорна тебя не забудут." } } } } },
    [418] = { d = 31.3, g = 1, v = "dwarf-female#95", n = { m = 331, f = 332 }, c = { m = { { 0.00, "Едоки в Телсамаре не переводятся – ещё бы, детей полным-полно, после трудового дня работники ужинать хотят." }, { 8.07, "Мы славимся кровяными колбасками..." }, { 10.72, "Но ты ведь их ещё не пробовал?" }, { 12.89, "Нет?" }, { 13.23, "Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение." }, { 20.62, "Мне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты." }, { 26.73, "Добудь всё это, а уж Видра сготовит всё в лучшем виде!" } }, f = { { 0.00, "Едоки в Телсамаре не переводятся – ещё бы, детей полным-полно, после трудового дня работники ужинать хотят." }, { 8.20, "Мы славимся кровяными колбасками..." }, { 10.89, "Но ты ведь их ещё не пробовала?" }, { 13.16, "Нет?" }, { 13.51, "Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение." }, { 21.02, "Мне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты." }, { 27.22, "Добудь всё это, а уж Видра сготовит всё в лучшем виде!" } } }, t = { d = 15.0, v = "dwarf-female#95", n = { x = 169 }, c = { x = { { 0.00, "Поверь, со стороны готовка выглядит куда сложнее, чем на деле, но..." }, { 4.80, "Хоть я и не встречала никого, кому бы захотелось научиться делать колбаски, но на всякий случай рецептик я тебе всё же дам." }, { 13.33, "Бери!" }, { 13.78, "Ешь, пока рот свеж!" } } } } },
    [419] = { d = 33.4, v = "dwarf-male", n = { x = 381 }, c = { x = { { 0.00, "Мой друг и напарник, пилот Осадного орудия Мори Хилдельв, пропал в этих холмах." }, { 5.64, "Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его танк на крутой холм и он сломался!" }, { 15.26, "Хилдельв, по-прежнему уверенный, что руда в тех горах есть, оставил меня охранять наши танки, а сам пошёл дальше пешком." }, { 23.69, "Прошло уже несколько дней, а я слышал ночью какой-то звериный вой в холмах." }, { 29.01, "Мори – парень-кремень, но мне тревожно." }, { 31.79, "Прошу тебя, найди его." } } }, t = { d = 25.0, v = "narrator", n = { x = 260 }, c = { x = { { 0.00, "Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками." }, { 7.27, "В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва." }, { 13.88, "Труп одет во всё ещё превосходно сохранившийся жилет бригадира." }, { 18.95, "Эта мрачная сцена показывает, где встретил свой конец пилот Осадной машины." } } } } },
    [420] = { d = 28.3, v = "dwarf-male", n = { x = 343 }, c = { x = { { 0.00, "Трогги, поселившиеся в тоннелях, крайне враждебны: они без раздумий нападают на любого, кто только осмелится туда сунуться." }, { 8.27, "С другой стороны, что-то мне подсказывает, что у тебя хватит сил и умения, чтобы с ними справиться." }, { 14.91, "Если тебе хочется побеседовать с Сениром, то его можно отыскать в Караносе." }, { 20.05, "А добраться туда и вовсе просто: пройдёшь весь тоннель насквозь, а дальше шагай себе по дороге до самого до города Караноса." } } }, t = { d = 33.1, v = "dwarf-male", n = { x = 343 }, c = { x = { { 0.00, "А что это у нас тут такое?" }, { 1.96, "О, донесение от моего братца!" }, { 4.19, "Хм-м..." }, { 4.73, "Говорил я ему, нечего поминать королевское имя всуе, да только станет он меня слушать!" }, { 11.36, "С другой стороны, кое-кому в Совете не мешает попортить кровь." }, { 16.09, "Ха!" }, { 16.36, "Как бы то ни было, думаю, мне нужно и своё донесение отправить в Стальгорн." }, { 21.84, "Как-то запоздал я с этим делом." }, { 24.27, "Всё этот проклятый холод!" }, { 26.24, "Слушай, если тебе это интересно, у меня скоро может найтись для тебя кое-какая работёнка..." } } } } },
    [421] = { d = 41.3, v = "scourge-male#82", n = { x = 403 }, c = { x = { { 0.00, "Леди Сильвана поручила Вариматрасу завоевать земли людей и дворфов к югу." }, { 6.23, "Но этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Тёмного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора." }, { 21.39, "Мне нужен кто-то, искушённый в воинском деле, чтобы разрубить узел, завязанный Аругалом." }, { 28.75, "Убейте пять белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу." }, { 34.98, "Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом." } } }, t = { d = 12.8, g = 1, v = "scourge-male#82", n = { x = 121 }, c = { m = { { 0.00, "Вы сослужили мне хорошую службу, герой." }, { 3.39, "Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала." } }, f = { { 0.00, "Вы сослужили мне хорошую службу, героиня." }, { 3.51, "Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала." } } } } },
    [422] = { d = 45.2, v = "scourge-male#82", n = { x = 450 }, c = { x = { { 0.00, "Для меня загадка, каким образом Аругал вообще был принят в Кирин Тор." }, { 5.83, "Его знания касательно применения заклинаний были просто мыльным пузырём." }, { 11.88, "Сейчас важно точно выяснить, какую магию применил Аругал, чтобы я мог использовать её против него и обеспечить владычество Тёмной Госпожи в Серебряном бору." }, { 24.88, "Вначале Аругал останавливался на пшеничной ферме, что к северу от моста." }, { 30.86, "Один из стражей смерти сообщил о том, что видел какие-то книги с заклинаниями, но не сумел их заполучить." }, { 39.53, "Добудьте для меня ту из этих книг, которая называется \"Зелье Аругала\"." } } }, t = { d = 14.1, g = 1, v = "scourge-male#82", n = { x = 117 }, c = { m = { { 0.00, "Да, это именно та книга, которую я искал, герой." }, { 4.72, "Если ваша приверженность делу Тёмной Госпожи не ослабела, вас ждёт неплохое будущее среди Отрёкшихся." } }, f = { { 0.00, "Да, это именно та книга, которую я искал, героиня." }, { 4.72, "Если ваша приверженность делу Тёмной Госпожи не ослабела, вас ждёт неплохое будущее среди Отрёкшихся." } } } } },
    [423] = { d = 47.8, v = "scourge-male#82", n = { x = 477 }, c = { x = { { 0.00, "Изучив деятельность Аругала, я понял, что мои наихудшие подозрения верны." }, { 6.23, "Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин Тор в самый трудный час." }, { 17.54, "Идиоты!" }, { 18.23, "Для усиления своей никудышной магии Аругал использовал заколдованные предметы." }, { 24.83, "В первую очередь я должен изучить эти предметы." }, { 28.93, "Отправляйтесь в путь и убивайте обжор Лунной Ярости и тёмных духов Лунной Ярости, пока не наберёте достаточного для моих исследований количества их заколдованных наручей." }, { 43.06, "Эти злобные создания обитают к северу и к востоку отсюда." } } }, t = { d = 17.7, g = 1, v = "scourge-male#82", n = { x = 168 }, c = { m = { { 0.00, "Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала." }, { 7.36, "Вероятно, мне следовало поручить вам добыть больше наручей." }, { 12.32, "Тем не менее, вы отменно проявили себя, собирая эти, герой." } }, f = { { 0.00, "Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала." }, { 7.50, "Вероятно, мне следовало поручить вам добыть больше наручей." }, { 12.55, "Тем не менее, вы отменно проявили себя, собирая эти, героиня." } } } } },
    [424] = { d = 40.7, v = "scourge-male#82", n = { x = 403 }, c = { x = { { 0.00, "Мне потребуется больше времени на раскрытие тёмных тайн чар Аругала, чем я думал." }, { 6.71, "Но тем временем мне нужно, чтобы вы помогли разрешить одну небольшую проблему, которую обнаружили наши разведчики." }, { 16.40, "Похоже, Аругал распространил свою магию на Серебряный рудник, находящийся в холмах к юго-востоку отсюда." }, { 25.32, "Этот рудник стал бы ценным ресурсом для Вариматраса." }, { 29.74, "Я хочу, чтобы вы снесли голову с плеч поражённому скверной старшине рудника Мрачнону Белёсому." }, { 37.60, "После его смерти рудник будет нашим." } } }, t = { d = 11.6, v = "scourge-male#82", n = { x = 113 }, c = { x = { { 0.00, "Великолепно." }, { 1.11, "Рудник обеспечит нас отменными ресурсами для наших сил по мере нашего продвижения по Серебряному бору и далее по Азероту." } } } } },
    [425] = { d = 42.8, v = "scourge-female", n = { x = 450 }, c = { x = { { 0.00, "Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком." }, { 10.17, "Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый." }, { 18.79, "Нам удалось уйти от Ивара, но он успел как следует приложить Квинна." }, { 24.16, "Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги." }, { 33.06, "Убейте Ивара, чтобы Квинн мог спокойно поправляться." }, { 37.16, "Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность." } } }, t = { d = 10.6, v = "scourge-female", n = { x = 92 }, c = { x = { { 0.00, "О, спасибо." }, { 1.12, "Я очень благодарна вам." }, { 3.37, "Я упомяну ваше имя в отчёте, который направлю своему вышестоящему начальству." } } } } },
    [426] = { d = 35.7, v = "scourge-male", n = { x = 375 }, c = { x = { { 0.00, "Плеть пытается основать базу на мельницах Агамондов." }, { 4.20, "Если им это удастся, они продолжат свои нападения в Тирисфале." }, { 9.34, "Поступил приказ уничтожить всю Плеть на мельницах." }, { 13.32, "Отправляйся туда и собери зазубренные рёбра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей." }, { 24.97, "Чтобы добраться до мельниц, иди по дороге на запад." }, { 29.17, "После того как перейдёшь мост, поверни на север, и скоро увидишь ветряные мельницы." } } }, t = { d = 12.4, v = "scourge-male", n = { x = 110 }, c = { x = { { 0.00, "Твои старания не прошли даром!" }, { 2.95, "Я не буду благодарить тебя за исполнение долга, но стражи смерти Тирисфаля навсегда запомнят твоё имя!" } } } } },
    [427] = { d = 41.5, g = 1, v = "scourge-male", n = { m = 383, f = 383 }, c = { m = { { 0.00, "Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом." }, { 9.12, "Теперь мы знаем расположение всех их баз в Тирисфальских лесах." }, { 14.42, "Но у стражей смерти есть заботы и поважнее: армия Короля-лича растёт с каждой ночью." }, { 21.62, "Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом." }, { 29.06, "Докажи мне, что способен служить Тёмной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей десять воинов из Алого ордена." } }, f = { { 0.00, "Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом." }, { 9.34, "Теперь мы знаем расположение всех их баз в Тирисфальских лесах." }, { 14.76, "Но у стражей смерти есть заботы и поважнее: армия Короля-лича растёт с каждой ночью." }, { 22.13, "Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом." }, { 29.75, "Докажи мне, что способна служить Тёмной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей десять воинов из Алого ордена." } } }, t = { d = 6.2, g = 1, v = "scourge-male", n = { x = 46 }, c = { m = { { 0.00, "Замечательно, герой." }, { 2.03, "Ваши боевые умения не вызывают сомнений." } }, f = { { 0.00, "Замечательно, героиня." }, { 2.26, "Ваши боевые умения не вызывают сомнений." } } } } },
    [428] = { d = 29.2, v = "scourge-male", n = { x = 303 }, c = { x = { { 0.00, "Пару недель назад двое наших стражей смерти – Ран и Квинн Йорик, ушли на разведывательное задание в северный Серебряный бор." }, { 9.74, "С тех пор от них не было никаких известий." }, { 12.98, "Они могли стать жертвами Плети, но даже если это так, мне нужно подтверждение." }, { 19.19, "Найдите этих стражей смерти." }, { 21.52, "Их первой целью была разведка на полях в северной части Серебряного бора." }, { 27.38, "Начните свои поиски там." } } }, t = { d = 5.9, v = "scourge-female", n = { x = 37 }, c = { x = { { 0.00, "Вы нашли нас!" }, { 1.55, "Ещё чуть-чуть – и было бы уже поздно..." } } } } },
    [429] = { d = 37.9, v = "scourge-female", n = { x = 341 }, c = { x = { { 0.00, "Моего брата Квинна серьёзно ранил вурдалак Ивар Нечистый." }, { 5.38, "Боюсь, без алхимической помощи он теперь не исцелится." }, { 10.35, "Я мало что понимаю в лекарском искусстве, но знаю, что наши аптекари умеют варить целительные зелья из обесцвеченных сердец воргов." }, { 22.44, "Добудь такие сердца и отнеси их аптекарю Ренферрелу в гробницу к югу отсюда." }, { 29.56, "Потом возвращайся с зельем." }, { 32.12, "Множество воргов водится на пути к Саду Мальдена, что к востоку." } } }, t = { d = 18.8, v = "scourge-male#82", n = { x = 154 }, c = { x = { { 0.00, "*Ренферрел берёт у вас сердца.*" }, { 2.80, "Меня тревожит известие о том, что наши стражи смерти потерпели неудачу в своей миссии." }, { 11.51, "Будем надеяться, что таких неудач будет немного." }, { 16.45, "Я сейчас дам тебе зелье." } } } } },
    [430] = { d = 10.7, v = "scourge-male#82", n = { x = 102 }, c = { x = { { 0.00, "Вот зелье, которое должно помочь Квинну Йорику поправиться." }, { 5.13, "А теперь, простите, мне нужно продолжить одно очень важное дело..." } } }, t = { d = 7.4, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Квинн забирает у вас зелье и выпивает его." }, { 3.57, "Некоторое время проходит в напряжённом молчании." } } } } },
    [431] = { t = { d = 3.8, v = "narrator", n = { x = 36 }, c = { x = { { 0.00, "Ты берёшь одну из свечей и кладёшь её в сумку." } } } } },
    [432] = { d = 33.0, v = "dwarf-male", n = { x = 331 }, c = { x = { { 0.00, "Эти проклятые Светом трогги перевернули всё моё рабочее место!" }, { 5.04, "Ты только глянь, ещё одну бочку пороха разворотили!" }, { 9.14, "Ох, прямо руки чешутся спуститься к ним да головы поотрывать!" }, { 14.04, "Всех бы поубивал!" }, { 15.40, "Но здоровье не позволяет, да ещё это потрясение и злость..." }, { 20.01, "Они ничего мне не оставили!" }, { 22.24, "Я бы сам их перебил, да рука уже не так тверда!" }, { 25.99, "Иди в карьер и перебей грязных тварей!" }, { 29.15, "Я заплачу!" }, { 30.02, "Ты только задай им шороху, перебей их!" } } }, t = { d = 8.5, v = "dwarf-male", n = { x = 73 }, c = { x = { { 0.00, "Ох, на душе полегчало..." }, { 2.22, "Но я не успокоюсь, пока все трогги не будут уничтожены!" }, { 7.24, "Все до единого!" } } } } },
    [433] = { d = 31.9, v = "dwarf-male", n = { x = 379 }, c = { x = { { 0.00, "Будучи членом Сената и Лиги Исследователей, я взял на себя заботу об искоренении троггской заразы, наводнившей наши земли." }, { 8.52, "Они ни за что ни про что разнесли карьер Гол'Болар." }, { 12.02, "Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и выгоняя горняков из шахт." }, { 19.29, "У нас нет выбора, кроме как истребить их как можно больше, отстроиться заново и вернуться к работе." }, { 26.11, "Если вы поможете мне разобраться с троггами, я с радостью возмещу вам затраты времени." } } }, t = { d = 16.6, v = "dwarf-male", n = { x = 210 }, c = { x = { { 0.00, "Это только начало." }, { 1.34, "Надеюсь, мы сможем воспользоваться преимуществом, и выделим небольшой контингент горных пехотинцев для защиты этого района." }, { 9.60, "Тогда мы сможем начать восстановление инфраструктуры и вернуть горняков к работе." }, { 15.06, "Спасибо тебе за помощь." } } } } },
    [434] = { d = 31.9, g = 1, v = "gnome-male", n = { m = 406, f = 407 }, c = { m = { { 0.00, "Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару." }, { 5.35, "Гвардия пропустит его без особых проблем." }, { 8.12, "Пока ты собирал для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром." }, { 15.29, "Я даже подкинул ему пару ложных слухов." }, { 18.00, "Лесковар отпустит свою охрану и будет дожидаться Марзона в саду." }, { 22.29, "Начинай действовать, как только они заведут разговор о Братстве Справедливости." }, { 27.47, "Убей обоих до возвращения гвардейцев!" }, { 29.94, "После этого поговори с Триасом." } }, f = { { 0.00, "Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару." }, { 5.33, "Гвардия пропустит его без особых проблем." }, { 8.08, "Пока ты собирала для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром." }, { 15.29, "Я даже подкинул ему пару ложных слухов." }, { 17.98, "Лесковар отпустит свою охрану и будет дожидаться Марзона в саду." }, { 22.26, "Начинай действовать, как только они заведут разговор о Братстве Справедливости." }, { 27.41, "Убей обоих до возвращения гвардейцев!" }, { 29.87, "После этого поговори с Триасом." } } }, t = { d = 16.2, g = 1, v = "human-male#50", n = { x = 179 }, c = { m = { { 0.00, "Сделано?" }, { 0.65, "Отлично." }, { 1.30, "Путник, благодарю вас за посильное участие." }, { 4.44, "Вы оказали Штормграду не одну услугу." }, { 7.17, "С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса." }, { 13.76, "Постарайтесь ни во что не вляпаться." } }, f = { { 0.00, "Сделано?" }, { 0.64, "Отлично." }, { 1.29, "Путница, благодарю вас за посильное участие." }, { 4.44, "Вы оказали Штормграду не одну услугу." }, { 7.14, "С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса." }, { 13.64, "Постарайтесь ни во что не вляпаться." } } } } },
    [435] = { d = 34.2, v = "scourge-male", n = { x = 332 }, c = { x = { { 0.00, "Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери." }, { 8.47, "Должно быть, они невероятно голодны, раз смогли счесть меня пищей." }, { 13.92, "Я должен доложиться своей коллеге, стражу смерти Ран Йорик." }, { 18.85, "Но чтобы добраться до Ран, мне нужна помощь против этих волков." }, { 24.08, "Пожалуйста, проводите меня!" }, { 26.37, "Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья..." } } }, t = { d = 11.9, v = "scourge-female", n = { x = 111 }, c = { x = { { 0.00, "Спасибо за помощь." }, { 1.68, "Я боялась, что Эрланда погубили опасности Серебряного бора." }, { 6.96, "Но я вижу, что благодаря вашей помощи этого не произошло." } } } } },
    [436] = { d = 34.7, v = "dwarf-male", n = { x = 419 }, c = { x = { { 0.00, "Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера." }, { 5.13, "В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов!" }, { 11.81, "Сталекрут – надёжный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать." }, { 20.71, "Отправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу." }, { 25.16, "Он ведёт отчётность по раскопкам и сможет объяснить, чем вызвана задержка." }, { 30.10, "Чтобы отыскать раскопки, обогни озеро с юга и направляйся на восток." } } }, t = { d = 11.4, v = "dwarf-male", n = { x = 124 }, c = { x = { { 0.00, "Значит, Джерн хочет узнать, чем вызвана задержка?" }, { 3.77, "Железняк как раз пишет подробный отчёт о своих последних достижениях, но я буду краток." }, { 10.35, "Дело в троггах!" } } } } },
    [437] = { d = 40.9, v = "scourge-male", n = { x = 435 }, c = { x = { { 0.00, "Первые отчёты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мёртвом поле." }, { 11.47, "Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство." }, { 22.31, "Мы хотим уничтожить Плеть Ночи." }, { 24.77, "Отправляйтесь на Мёртвое поле и атакуйте Гнилошкуров." }, { 28.85, "Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и её." }, { 34.56, "Сущность банши обратится в прах." }, { 37.09, "Принесите мне этот прах в доказательство её смерти." } } }, t = { d = 21.0, v = "scourge-male", n = { x = 198 }, c = { x = { { 0.00, "Я слышал о вашем успешном набеге на гноллов-гнилошкуров, а эта сущность является доказательством смерти банши Плеть Ночи." }, { 11.01, "Сегодня Король-лич потерял ещё одного прислужника." }, { 15.58, "Вы становитесь ещё более ценным союзником в глазах Отрёкшихся." } } } } },
    [438] = { d = 23.9, v = "scourge-male", n = { x = 244 }, c = { x = { { 0.00, "Мы обнаружили ещё одно место, где угнездилась Плеть: это старая переправа." }, { 6.13, "Переправа находится к востоку от Гробницы, и её патрулируют многочисленные гноллы-гнилошкуры и различная нежить." }, { 15.33, "Полагаю, Плеть захватила это место неспроста." }, { 19.14, "Отправляйтесь к старой переправе и выясните, в чём там дело." } } }, t = { d = 15.6, v = "narrator", n = { x = 164 }, c = { x = { { 0.00, "В лодке находится куча спелёнутых мёртвых тел." }, { 3.47, "А если смотреть на восток через озеро Лордамер, то напротив видна пристань на острове Фенриса." }, { 11.22, "Должно быть, разгадку этой тайны стоит искать на острове." } } } } },
    [439] = { d = 16.8, v = "narrator", n = { x = 155 }, c = { x = { { 0.00, "Из кучи трупов торчит обнажённая рука." }, { 3.39, "Это рука женщины – тронутая чумой, но относительно свежая." }, { 8.60, "На пальце надето кольцо." }, { 10.81, "Вы снимаете кольцо и, осмотрев его, обнаруживаете гравировку:" }, { 16.17, "\"Делии\"." } } }, t = { d = 17.4, v = "scourge-male", n = { x = 163 }, c = { x = { { 0.00, "Говорите, это кольцо было надето на палец недавно погибшей женщины?" }, { 6.00, "Видимо, тело было поднято из общей могилы в Тирисфале, не иначе." }, { 11.68, "Должно быть, гноллы-гнилошкуры таскают эти трупы на остров Фенриса!" } } } } },
    [440] = { d = 31.2, v = "scourge-male", n = { x = 292 }, c = { x = { { 0.00, "Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьёй Севреном в Брилле." }, { 10.65, "У него должны быть записи о недавних смертях и, если повезёт, он сможет выяснить, кто такая Делия." }, { 18.89, "Но я бы на это не рассчитывал." }, { 21.38, "Тот, кто подарил ей кольцо, вероятно, уже мёртв." }, { 25.39, "Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии." } } }, t = { d = 25.0, v = "scourge-male#82", n = { x = 240 }, c = { x = { { 0.00, "Некая Делия жила в Брилле не так давно." }, { 3.39, "Она была похоронена в общей могиле, но, если верить вашим словам, её тело, должно быть, похитили гноллы из стаи Гнилошкуров и утащили в Серебряный бор." }, { 16.14, "Стая Гнилошкуров, как и вся Плеть, должна быть уничтожена." }, { 20.90, "Я верю, что ты предпримешь к этому надлежащие шаги." } } } } },
    [441] = { d = 16.8, v = "scourge-male#82", n = { x = 169 }, c = { x = { { 0.00, "У Делии был муж по имени Роли, проживающий ныне в Подгороде." }, { 4.90, "Если кольцо действительно принадлежало Делии, которая жила здесь, в Брилле, то Роли узнает его." }, { 12.71, "Найти Роли вы можете в Торговом квартале Подгорода." } } }, t = { d = 28.2, v = "scourge-male", n = { x = 233 }, c = { x = { { 0.00, "Да, это вещица моей жены." }, { 2.65, "Её постигла та же участь, что и всех, кому не удалось пережить эти суровые времена." }, { 10.76, "Меня не трогает её смерть, как не трогает и ваш рассказ о похищении её тела." }, { 18.09, "Подобные чувства давно остыли во мне." }, { 21.79, "Но желание всё ещё клокочет в моём мёртвом сердце." }, { 26.56, "Желание отомстить." } } } } },
    [442] = { d = 28.2, g = 1, v = "scourge-male", n = { m = 245, f = 249 }, c = { m = { { 0.00, "А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса." }, { 8.68, "Ты снова должен добраться до острова и уничтожить Тула Когтя Ворона." }, { 15.17, "Мне нужна его голова!" }, { 17.28, "Я посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача." }, { 25.63, "Ты должен выйти победителем!" } }, f = { { 0.00, "А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса." }, { 8.56, "Ты снова должна добраться до острова и уничтожить Тула Когтя Ворона." }, { 14.95, "Мне нужна его голова!" }, { 17.03, "Я посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача." }, { 25.25, "Ты должна выйти победительницей!" } } }, t = { d = 22.1, v = "scourge-male", n = { x = 208 }, c = { x = { { 0.00, "Смерть Тула Когтя Ворона – значимое событие." }, { 4.04, "Ренферрел рассказывает, что потоки энергии, которые вы высвободили при уничтожении Тула, ощущались аж до Гробницы." }, { 14.15, "Твои действия получили большой резонанс у Отрёкшихся." }, { 18.92, "Твоя ценность в наших глазах растёт." } } } } },
    [443] = { d = 30.3, v = "scourge-male", n = { x = 320 }, c = { x = { { 0.00, "Прежде чем мы совершим нападение на остров Фенриса, мы должны понять, кто стоит за Гнилошкурами." }, { 7.60, "Наши аптекари считают, что их особенности связаны со странной жидкостью, текущей по их жилам." }, { 14.98, "Отправляйся на остров Фенриса, к востоку от старой переправы, и собери лимфу гноллов-гнилошкуров, которых вы там встретите." }, { 24.74, "Образцы нужны аптекарю Ренферрелу, который стоит неподалёку от Гробницы." } } }, t = { d = 13.0, v = "scourge-male#82", n = { x = 108 }, c = { x = { { 0.00, "Отлично." }, { 0.84, "Эта лимфа поможет нам понять природу гноллов-гнилошкуров, а также сможет показать нам, в чём их слабость..." }, { 10.85, "...если она у них есть..." } } } } },
    [444] = { d = 38.9, g = 1, v = "scourge-male#82", n = { m = 360, f = 362 }, c = { m = { { 0.00, "Я выпарил лимфу, которую ты принёс мне, и разложил её на основные компоненты." }, { 6.37, "Мои выводы ещё не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией." }, { 17.15, "Пока я продолжу её изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород." }, { 25.04, "Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров." }, { 32.40, "Иди же." }, { 33.08, "Бетора ты найдёшь в Квартале Магов Подгорода." } }, f = { { 0.00, "Я выпарил лимфу, которую ты принесла мне, и разложил её на основные компоненты." }, { 6.95, "Мои выводы ещё не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией." }, { 18.28, "Пока я продолжу её изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород." }, { 26.59, "Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров." }, { 34.33, "Иди же." }, { 35.05, "Бетора ты найдёшь в Квартале Магов Подгорода." } } }, t = { d = 15.1, v = "scourge-male#82", n = { x = 151 }, c = { x = { { 0.00, "Эта субстанция наполнена могучими заклинаниями, с некоторыми из которых я не сталкивался вот уже долгое время..." }, { 9.62, "Секундочку – мне придётся воспользоваться проясняющим заклинанием..." } } } } },
    [445] = { d = 41.9, g = 1, v = "scourge-male#82", n = { m = 393, f = 395 }, c = { m = { { 0.00, "Время – это непозволительная роскошь для тех, кто служит леди Сильване." }, { 5.97, "Ты это, конечно, уже и сам понял." }, { 8.84, "Я состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Тёмная Госпожа." }, { 26.52, "Отнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору." }, { 35.21, "Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад." } }, f = { { 0.00, "Время – это непозволительная роскошь для тех, кто служит леди Сильване." }, { 6.11, "Ты это, конечно, уже и сама поняла." }, { 9.28, "Я состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Тёмная Госпожа." }, { 27.38, "Отнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору." }, { 36.28, "Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад." } } }, t = { d = 31.0, g = 1, v = "scourge-male#82", n = { m = 305, f = 305 }, c = { m = { { 0.00, "А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований!" }, { 6.16, "Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и из Тирисфальских лесов." }, { 16.19, "Кстати, надо бы поскорей отправить те образцы в Некрополь..." }, { 21.16, "Но прошу простить мою болтливость." }, { 24.06, "Задержись в Серебряном бору чуть подольше, такой герой, как ты, всегда нам пригодится." } }, f = { { 0.00, "А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований!" }, { 5.66, "Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и из Тирисфальских лесов." }, { 14.87, "Кстати, надо бы поскорей отправить те образцы в Некрополь..." }, { 19.43, "Но прошу простить мою болтливость." }, { 22.09, "Задержись в Серебряном бору чуть подольше, такая героиня, как ты, всегда нам пригодится." } } } } },
    [446] = { d = 40.9, v = "scourge-male#82", n = { x = 411 }, c = { x = { { 0.00, "Эта лимфа была создана моим давним коллегой, Тулом Когтем Ворона." }, { 5.56, "До великой войны он был молодым и многообещающим магом, но когда вошёл в силу Король-лич, Тул предал своих братьев и перешёл на сторону Плети." }, { 16.97, "Я и не думал, что он всё ещё жив, и уж тем более – что он возглавляет набеги Гнилошкуров на нас!" }, { 24.43, "Я знаю многие из его заклинаний и могу помочь сварить зелье для того, чтобы им противостоять." }, { 32.11, "Отнеси этот свиток обратно к аптекарю Ренферрелу." }, { 36.21, "Там содержатся заклятья, необходимые для изготовления зелья." } } }, t = { d = 20.1, v = "scourge-male#82", n = { x = 202 }, c = { x = { { 0.00, "Этот свиток весь пронизан могущественной магией." }, { 4.02, "Я никогда не использовал таких сил в зельях... это будет сильнодействующая микстура, и она должна сослужить тебе хорошую службу, если ты решишься атаковать Тула в его крепости на острове Фенриса." } } } } },
    [447] = { d = 39.0, v = "scourge-male#82", n = { x = 400 }, c = { x = { { 0.00, "Силы Артаса неисчислимы." }, { 2.09, "Но с Новой чумой мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми." }, { 9.39, "Мои исследования показали, что паучья кровь в соединении с токсином, извлечённым из сердца бешеного медведя, даёт смертельно опасный эликсир." }, { 20.86, "Собери необходимые субстанции с пауков из Струящейся Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору." }, { 31.07, "Принеси реагенты в Подгород мастеру-аптекарю Фаранеллу из Королевского фармацевтического общества." } } }, t = { d = 13.8, v = "scourge-male", n = { x = 147 }, c = { x = { { 0.00, "Аптекарь Ренферрел правильно сделал, что послал вас ко мне." }, { 4.74, "Эти образцы действительно будут весьма полезны." }, { 8.67, "Я немедленно начну изучать их отравляющие и инфицирующие свойства." } } } } },
    [448] = { d = 11.1, v = "scourge-male#82", n = { x = 126 }, c = { x = { { 0.00, "Прежде чем вы нападёте на остров Фенриса, доложитесь верховному палачу Хадрику." }, { 5.98, "У него может быть дополнительная информация о том, что вам понадобится." } } }, t = { d = 17.2, v = "scourge-male", n = { x = 179 }, c = { x = { { 0.00, "Если то, что говорит Бетор, – правда, то Тул Коготь Ворона представляет собой силу, с которой нужно разобраться, причём разобраться срочно." }, { 10.91, "В качестве помощи можете подобрать себе что-нибудь из нашего здешнего арсенала..." } } } } },
    [449] = { d = 15.7, v = "scourge-female", n = { x = 165 }, c = { x = { { 0.00, "Хотя раны Квинна заживают, я хотела бы доставить наш отчёт верховному палачу Хадрику как можно скорее." }, { 8.36, "В нём содержится информация, которая жизненно важна для захвата Серебряного бора Отрёкшимися." } } }, t = { d = 21.0, v = "scourge-male", n = { x = 202 }, c = { x = { { 0.00, "Я не ожидал ни такого количества Плети, с каким мы столкнулись в Серебряном бору, ни проблем, которые возникли перед стражами смерти в ходе разведывательной операции." }, { 14.50, "Ваша помощь нашим стражам смерти просто неоценима." }, { 19.07, "Вы заслуживаете похвалы." } } } } },
    [450] = { d = 41.8, v = "scourge-male", n = { x = 424 }, c = { x = { { 0.00, "Вы можете ещё послужить Королевскому фармацевтическому обществу." }, { 5.13, "Когда Аругал навёл на лес свою никчёмную магию, он наложил проклятие на одного из наших самых многообещающих сотрудников, аптекаря Берарда." }, { 16.35, "Ставший безвольным слугой Аругала, теперь Берард для нас бесполезен." }, { 21.93, "Но его находки могут быть ценными." }, { 24.79, "Он изучал древнюю чуму, давным-давно погубившую всякую жизнь в озере Лордамер." }, { 32.67, "Раздобудьте записи Берарда из его кабинета в таверне деревни Погребальных Костров и принесите аптекарю Ренферрелу." } } }, t = { d = 10.6, v = "scourge-male#82", n = { x = 101 }, c = { x = { { 0.00, "Записи аптекаря Берарда!" }, { 2.18, "В смелости вам не откажешь." }, { 4.51, "Теперь давайте посмотрим, чем занимался Берард прежде, чем сошёл с ума..." } } } } },
    [451] = { d = 40.6, v = "scourge-male#82", n = { x = 425 }, c = { x = { { 0.00, "Согласно записям Берарда, мох озёрных тихоходов и озёрных ползунов может оказаться полезным для решения нашей задачи по изготовлению новой отравы." }, { 11.34, "Эти твари обитают на островах на озере Лордамер на востоке." }, { 17.19, "Он также упоминает об очень редкой субстанции – твёрдой опухоли, обнаруженной им у мурлока из племени Злобного Плавника." }, { 26.49, "Очевидно, эта опухоль столь редка, что Берарду удалось раздобыть лишь одну." }, { 32.41, "Соберите образцы моха, а также редкую твёрдую опухоль и отнесите их мастеру-аптекарю Фаранеллу в Подгород." } } }, t = { d = 30.1, v = "scourge-male", n = { x = 301 }, c = { x = { { 0.00, "Потеря Берарда – серьёзный удар для Королевского фармацевтического общества." }, { 6.37, "Но благодаря вашим стараниям и усердным исследованиям аптекаря Ренферрела разработки Берарда по-прежнему будут полезны делу Тёмной Госпожи." }, { 18.19, "Мы находимся на пороге чего-то великого." }, { 21.64, "Если бы вы не были столь искусны в военном деле, я пригласил бы вас вступить в члены нашего Общества." } } } } },
    [452] = { d = 42.8, v = "scourge-female", n = { x = 422 }, c = { x = { { 0.00, "Вы очень вовремя добрались сюда!" }, { 2.83, "Совет деревни Погребальных Костров вернётся в любой момент." }, { 7.89, "Аругалу же есть чем заняться в крепости." }, { 11.26, "Он использует совет как марионеток, чтобы держать лишённых разума и воли приспешников в деревне под своим полным контролем." }, { 21.67, "Но я уверена, что без руководства совета деревни Погребальных Костров сыновья Аругала взбунтовались бы против своего хозяина." }, { 32.24, "Я не могу справиться со всем этим в одиночку." }, { 36.07, "Мне нужна ваша помощь." }, { 38.06, "Вместе мы сможем погубить совет, на благо леди Сильваны." } } }, t = { d = 21.0, v = "scourge-female", n = { x = 189 }, c = { x = { { 0.00, "Вы бились достойно настоящего последователя Тёмной Госпожи." }, { 5.49, "Теперь, когда члены Совета мертвы, может быть, мы сможем восстановить контроль над этой деревней раз и навсегда и выбить Аругала из крепости Тёмного Клыка." }, { 20.03, "Честь имею!" } } } } },
    [453] = { d = 8.6, v = "human-male#50", n = { x = 95 }, c = { x = { { 0.00, "Удачи." }, { 0.54, "Надеюсь, ты найдёшь этого парня, причём живым." }, { 3.95, "Сбежав за пределы Темнолесья, он мог пасть жертвой диких зверей." } } }, t = { d = 10.7, g = 1, v = "human-male", n = { m = 112, f = 113 }, c = { m = { { 0.00, "Да, автор этой книги – я." }, { 2.79, "Сумел-таки отыскать меня?" }, { 4.98, "Но если ты прочитаешь мои записи, то узнаешь только половину истории!" } }, f = { { 0.00, "Да, автор этой книги – я." }, { 2.67, "Сумела-таки отыскать меня?" }, { 4.84, "Но если ты прочитаешь мои записи, то узнаешь только половину истории!" } } } } },
    [454] = { d = 17.4, v = "dwarf-male", n = { x = 198 }, c = { x = { { 0.00, "До этого... случая мы всё время таскали туда-сюда бочки с порохом." }, { 4.83, "Теперь придётся поделить работу: Миран понесёт часть бочек, а я присмотрю за остальными." }, { 11.00, "Мне не хочется отпускать Мирана одного." }, { 13.84, "Когда он соберётся в путь, проводи, пожалуйста, его." } } }, t = { d = 16.7, g = 1, v = "dwarf-male", n = { x = 186 }, c = { m = { { 0.00, "Добрый день, герой." }, { 1.35, "Ты проводишь меня до раскопа?" }, { 3.39, "Отлично..." }, { 4.12, "После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Чёрного Железа." }, { 10.10, "Я почти готов, осталось только кое-что проверить." }, { 13.54, "Когда ты соберёшься в путь, скажи мне об этом." } }, f = { { 0.00, "Добрый день, героиня." }, { 1.49, "Ты проводишь меня до раскопа?" }, { 3.53, "Отлично..." }, { 4.28, "После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Чёрного Железа." }, { 10.29, "Я почти готов, осталось только кое-что проверить." }, { 13.76, "Когда ты соберёшься в путь, скажи мне об этом." } } } } },
    [455] = { d = 39.2, v = "dwarf-male", n = { x = 458 }, c = { x = { { 0.00, "Орки из клана Драконьей Пасти бесчинствуют по всей Болотине." }, { 4.25, "А сейчас они двинулись на Дун Альгаз!" }, { 6.92, "Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине." }, { 16.37, "Попытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь!" }, { 22.59, "Чем больше, тем лучше!" }, { 24.18, "Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов." }, { 28.49, "Найти Менетилов несложно: пройдёшь через Дун Альгаз, потом – по дороге на север, а на развилке свернёшь на запад." }, { 36.36, "Мы очень надеемся на тебя." }, { 38.26, "Не подведи нас." } } }, t = { d = 21.5, v = "dwarf-male", n = { x = 240 }, c = { x = { { 0.00, "Да, нехорошие новости!" }, { 1.64, "Как я понимаю, орки Драконьей Пасти всерьёз вознамерились двинуться на Альгаз." }, { 7.27, "Обычно они сидят у себя на холмах и никуда не суются." }, { 11.26, "Что их сподвигло идти на Альгаз?" }, { 13.61, "Для меня это загадка..." }, { 15.38, "Спасибо." }, { 16.04, "Может быть, нам понадобится твоя помощь, когда мы пойдём разбираться с орками." } } } } },
    [456] = { d = 36.4, g = 1, v = "nightelf-male#54", n = { m = 358, f = 358 }, c = { m = { { 0.00, "Мои приветствия." }, { 1.40, "Я – Опекун Илталайн." }, { 3.09, "Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия." }, { 8.90, "Весенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают." }, { 18.40, "К несчастью, ночные саблезубы и щетинистые вепри слишком расплодились." }, { 24.13, "Тенистая долина не может их прокормить." }, { 27.37, "Юный герой, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия." } }, f = { { 0.00, "Мои приветствия." }, { 1.42, "Я – Опекун Илталайн." }, { 3.14, "Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия." }, { 9.05, "Весенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают." }, { 18.69, "К несчастью, ночные саблезубы и щетинистые вепри слишком расплодились." }, { 24.52, "Тенистая долина не может их прокормить." }, { 27.81, "Юная героиня, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия." } } }, t = { d = 2.9, g = 1, v = "nightelf-male#54", n = { m = 24, f = 25 }, c = { m = { { 0.00, "Ты хорошо исполнил свой долг." } }, f = { { 0.00, "Ты хорошо исполнила свой долг." } } } } },
    [457] = { d = 30.0, v = "nightelf-male#54", n = { x = 321 }, c = { x = { { 0.00, "Сокращение численности молодых особей, обитающих в Тенистой долине – это неплохо для начала, однако нужно выполнить ещё некоторую работу." }, { 10.65, "Лесные ресурсы истощатся слишком быстро, если не решить эту проблему." }, { 16.15, "Охота на диких зверей – это зло, необходимое для блага всех тех, кто обитает в этих землях." }, { 23.19, "Отправляйся в лес и убивай облезлых ночных саблезубов и щетинистых вепрей ради равновесия." } } }, t = { d = 11.4, g = 1, v = "nightelf-male#54", n = { x = 103 }, c = { m = { { 0.00, "Твои дела доказывают твою преданность природе." }, { 4.07, "Поверь, герой, несмотря на твою юность уже заметно, что тебя ждёт блестящее будущее." } }, f = { { 0.00, "Твои дела доказывают твою преданность природе." }, { 4.07, "Поверь, героиня, несмотря на твою юность уже заметно, что тебя ждёт блестящее будущее." } } } } },
    [458] = { d = 30.7, g = 1, v = "nightelf-male#55", n = { x = 322 }, c = { m = { { 0.00, "Какая отрада, что ты здесь, герой." }, { 2.58, "Шёпот лесных духов донёс до моего слуха странные вести." }, { 6.79, "Таинственная защитница леса, Тариндрелла, вернулась в Тенистую долину." }, { 12.09, "Много лет эту дриаду не видели в лесах Калимдора." }, { 15.89, "Что-то определённо не так, если она вновь появилась в этих землях." }, { 20.85, "Найди Тариндреллу и узнай, что привело её в наши рощи." }, { 24.99, "Кто-то из Стражей сообщил о том, что её видели к юго-западу от Альдрассила." } }, f = { { 0.00, "Какая отрада, что ты здесь, героиня." }, { 2.73, "Шёпот лесных духов донёс до моего слуха странные вести." }, { 6.95, "Таинственная защитница леса, Тариндрелла, вернулась в Тенистую долину." }, { 12.27, "Много лет эту дриаду не видели в лесах Калимдора." }, { 16.08, "Что-то определённо не так, если она вновь появилась в этих землях." }, { 21.06, "Найди Тариндреллу и узнай, что привело её в наши рощи." }, { 25.21, "Кто-то из Стражей сообщил о том, что её видели к юго-западу от Альдрассила." } } }, t = { d = 19.6, g = 1, v = "creature/dryad", n = { m = 178, f = 179 }, c = { m = { { 0.00, "Я вижу, тебе удалось найти меня, юный путник!" }, { 4.12, "Друид Мелитар мудро поступил, отправив тебя сюда." }, { 8.55, "Тебе ещё многому нужно научиться." }, { 11.51, "Я так понимаю, ваш народ любит книги." }, { 14.78, "Можешь взять одну из них, чтобы углубить свои познания." } }, f = { { 0.00, "Я вижу, тебе удалось найти меня, юная путница!" }, { 4.27, "Друид Мелитар мудро поступил, отправив тебя сюда." }, { 8.70, "Тебе ещё многому нужно научиться." }, { 11.66, "Я так понимаю, ваш народ любит книги." }, { 14.93, "Можешь взять одну из них, чтобы углубить свои познания." } } } } },
    [459] = { d = 34.8, v = "creature/dryad", n = { x = 352 }, c = { x = { { 0.00, "Непонятное зло затаилось в лесу Тельдрассила." }, { 3.69, "Взгляни на холмы, где некогда обитали мирные фурболги." }, { 8.20, "Они покинули свои дома и объединились в племя Кривой Сосны." }, { 13.23, "Лишь порча, вызванная зловещим мхом Скверны, могла быть причиной подобного изменения." }, { 20.17, "Грелли и греллиды кишат в округе, представляя собой угрозу для жителей Тенистой долины." }, { 27.42, "Напади на этих бесов, и узнай, действительно ли они подпали под чары зловещего мха Скверны." } } }, t = { d = 30.2, g = 1, v = "creature/dryad", n = { x = 289 }, c = { m = { { 0.00, "Твоё служение обитателям Тенистой долины достойно награды." }, { 4.99, "Однако мои опасения подтвердились." }, { 7.98, "Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь." }, { 20.03, "Герой, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру." }, { 26.78, "Он, как и мы, печётся о благополучии леса." } }, f = { { 0.00, "Твоё служение обитателям Тенистой долины достойно награды." }, { 4.99, "Однако мои опасения подтвердились." }, { 7.98, "Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь." }, { 20.03, "Героиня, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру." }, { 26.94, "Он, как и мы, печётся о благополучии леса." } } } } },
    [460] = { d = 50.6, g = 1, v = "scourge-male", n = { m = 451, f = 452 }, c = { m = { { 0.00, "На вид ты не похож на гнилошкура." }, { 2.91, "Это хорошо." }, { 4.04, "А то я уже потерял надежду..." }, { 6.71, "Меня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула." }, { 13.43, "Он использовал свою магию для \"защиты\" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти." }, { 27.50, "А после создания этих проклятых гнилошкурых гноллов Тул обезглавил меня... и отдал гноллам мою голову в качестве игрушки!" }, { 38.51, "Пожалуйста, воссоедини меня с телом." }, { 41.82, "Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле." } }, f = { { 0.00, "На вид ты не похожа на гнилошкура." }, { 2.97, "Это хорошо." }, { 4.10, "А то я уже потерял надежду..." }, { 6.75, "Меня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула." }, { 13.42, "Он использовал свою магию для \"защиты\" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти." }, { 27.41, "А после создания этих проклятых гнилошкурых гноллов Тул обезглавил меня... и отдал гноллам мою голову в качестве игрушки!" }, { 38.34, "Пожалуйста, воссоедини меня с телом." }, { 41.64, "Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле." } } }, t = { d = 8.2, v = "scourge-male", n = { x = 67 }, c = { x = { { 0.00, "Спасибо." }, { 0.89, "Я опасался, что гноллы изуродовали моё тело." }, { 5.28, "Приятно узнать, что это не так." } } } } },
    [461] = { d = 31.7, v = "scourge-male", n = { x = 274 }, c = { x = { { 0.00, "Я знаю об одной тайной нише в крепости, где хранится дорогой сердцу Тула и его давних коллег предмет." }, { 9.54, "В ней также лежит нечто, что вы можете счесть полезным для себя." }, { 15.42, "Возьмите меня туда!" }, { 17.33, "Углубление в стене находится в юго-западной башне крепости, позади пыльной полки." }, { 24.96, "Возьмите моё тело, а сапоги оставьте здесь." }, { 28.94, "Они мне всё равно не по ноге..." } } }, t = { d = 25.1, v = "scourge-male", n = { x = 213 }, c = { x = { { 0.00, "Вот мы и на месте, здесь открыто." }, { 3.02, "Оставьте меня здесь." }, { 4.96, "Лучшие дни моей жизни я провёл в этой крепости, и мысль об упокоении в этих стенах умиротворяет меня." }, { 14.36, "Хорошенько закройте нишу – я не хочу, чтобы эти гнилошкуры нашли меня." }, { 21.08, "Ах, да, и возьмите вот это." }, { 23.60, "Вы это заслужили." } } } } },
    [463] = { d = 37.4, g = 1, v = "human-male#50", n = { m = 445, f = 446 }, c = { m = { { 0.00, "Ты ведь слышал рассказы о Зелёном Страже?" }, { 2.71, "Я даже подозреваю, что ты и разыскать его хочешь." }, { 6.03, "Если так, то скажу тебе, что это чистое безумие!" }, { 9.34, "Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим." }, { 15.43, "Он живёт на болотах, к востоку от развилки на дороге, ведущей в Дун Модр." }, { 20.20, "Рыщет там на пару с кроколисками... и прочими тварями." }, { 23.81, "Оставь-ка свои денежки мне – покойникам они всё равно не нужны." }, { 28.10, "Да и Зелёный Дядя может обломать зуб о твои золотые, когда будет перекусывать тебя надвое..." }, { 34.30, "Ты ведь не хочешь, чтобы бедняга потом мучился?" } }, f = { { 0.00, "Ты ведь слышала рассказы о Зелёном Страже?" }, { 2.70, "Я даже подозреваю, что ты и разыскать его хочешь." }, { 5.92, "Если так, то скажу тебе, что это чистое безумие!" }, { 9.15, "Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим." }, { 15.07, "Он живёт на болотах, к востоку от развилки на дороге, ведущей в Дун Модр." }, { 19.71, "Рыщет там на пару с кроколисками... и прочими тварями." }, { 23.23, "Оставь-ка свои денежки мне – покойникам они всё равно не нужны." }, { 27.39, "Да и Зелёный Дядя может обломать зуб о твои золотые, когда будет перекусывать тебя надвое..." }, { 33.43, "Ты ведь не хочешь, чтобы бедняга потом мучился?" } } }, t = { d = 27.8, g = 1, v = "creature/ancient", n = { m = 221, f = 221 }, c = { m = { { 0.00, "Что это за букашка ко мне пожаловала?" }, { 3.53, "Корни и папоротники говорят, что ты пришёл с добрым умыслом..." }, { 9.40, "Меня по-разному называют, но не на всякое имя я откликаюсь." }, { 15.08, "Зови меня Ретиль." }, { 16.89, "А теперь внемли..." }, { 18.70, "Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их." } }, f = { { 0.00, "Что это за букашка ко мне пожаловала?" }, { 3.68, "Корни и папоротники говорят, что ты пришла с добрым умыслом..." }, { 9.88, "Меня по-разному называют, но не на всякое имя я откликаюсь." }, { 15.80, "Зови меня Ретиль." }, { 17.69, "А теперь внемли..." }, { 19.57, "Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их." } } } } },
    [464] = { d = 33.1, v = "dwarf-male", n = { x = 371 }, c = { x = { { 0.00, "К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен." }, { 7.98, "Драконы припомнили им всё, гнали бывших хозяев аж до самого Грим Батола." }, { 13.31, "Затем орки скрылись в горах к востоку от Раскопок Вельгара." }, { 17.76, "Отсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила." }, { 25.02, "Напади на этот лагерь, внеси панику в ряды орков." }, { 28.81, "В доказательство содеянного принеси мне боевые знамёна клана." } } }, t = { d = 34.1, v = "dwarf-male", n = { x = 360 }, c = { x = { { 0.00, "Отличная работа." }, { 1.31, "Ныне клан Драконьей Пасти уж не тот, что в былые времена, когда оркам служили драконы." }, { 7.94, "Но всё равно они опасные противники." }, { 10.77, "Кланом Драконьей Пасти руководит Нек'рош, сын Некросса – бывшего главы клана." }, { 16.77, "Некросс владел могущественными заклинаниями, с помощью которых он управлял красными драконами." }, { 23.95, "Но когда его силы иссякли... ну, ты уже знаешь эту историю." }, { 28.64, "Некросс погиб, а его сын поклялся отомстить драконам, убившим его отца." } } } } },
    [465] = { d = 27.8, v = "dwarf-male", n = { x = 324 }, c = { x = { { 0.00, "Клан Драконьей Пасти собирается напасть раньше, чем мы предполагали." }, { 4.78, "Нек'рош построил катапульты и планирует взять Менетил в осаду!" }, { 9.18, "А у нас тем временем вовсю идёт битва при Дун Альгазе и подкрепления ждать неоткуда!" }, { 14.98, "Уничтожь катапульты." }, { 16.45, "Они стоят в лагере Драконьей Пасти." }, { 19.06, "Возьми вот этот трут." }, { 20.59, "Пробейся к катапультам и подожги их." }, { 23.14, "После этого найди и убей Нек'роша." }, { 25.69, "Этот паршивец уже своё отжил..." } } }, t = { d = 9.2, v = "narrator", n = { x = 94 }, c = { x = { { 0.00, "Вы подносите трут к катапульте и высекаете искру..." }, { 4.23, "Пламя охватывает катапульту и мигом перекидывается на другие!" } } } } },
    [466] = { d = 37.0, v = "dwarf-male", n = { x = 422 }, c = { x = { { 0.00, "Я слышал о редком виде руды – огневите." }, { 2.84, "Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза." }, { 7.51, "Огневит очень неустойчив – чуть что, сразу взрывается." }, { 11.29, "Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек!" }, { 18.61, "Раздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах." }, { 26.31, "Ах да, чтобы добыть руду, тебе нужны познания в горном деле." }, { 30.67, "Если у тебя нет необходимых знаний, то... отправь в шахту кого-нибудь из знакомых рудокопов!" } } }, t = { d = 12.7, v = "dwarf-male", n = { x = 145 }, c = { x = { { 0.00, "Как раз столько, сколько нужно для экспериментов!" }, { 3.56, "Молодец, я в тебя верил!" }, { 5.41, "Тут же отправлю материал на изучение." }, { 8.12, "Надеюсь, что мой доброволец хотя бы до первых результатов доживёт!" } } } } },
    [467] = { d = 25.4, v = "dwarf-male", n = { x = 276 }, c = { x = { { 0.00, "Пилот Камнекожец любит свою осадную машину, как и все пилоты осадных машин!" }, { 5.62, "И он всегда рад найти новый способ повысить огневую мощь своих орудий." }, { 10.84, "До него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет её." }, { 16.26, "И если тебе уже не терпится взяться за это дело, то найди Камнекожца в посёлке Сталежара в Дун Мороге и спроси, чего он хочет." } } }, t = { d = 7.7, g = 1, v = "dwarf-male", n = { m = 72, f = 72 }, c = { m = { { 0.00, "Привет." }, { 0.61, "Ты тут по моему делу, да?" }, { 2.51, "Приятно видеть, как молодой герой рвётся на поиски приключений!" } }, f = { { 0.00, "Привет." }, { 0.65, "Ты тут по моему делу, да?" }, { 2.66, "Приятно видеть, как молодая героиня рвётся на поиски приключений!" } } } } },
    [468] = { d = 18.9, v = "dwarf-male", n = { x = 223 }, c = { x = { { 0.00, "Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину!" }, { 5.75, "Если желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите с горным пехотинцем Рокхаром в Дун Альгаз." }, { 15.29, "Это к северу отсюда, по дороге за сторожевой башней." } } }, t = { d = 12.4, g = 1, v = "dwarf-male", n = { x = 133 }, c = { m = { { 0.00, "Привет, герой!" }, { 1.10, "Желаешь отправиться с нами в разведку?" }, { 3.90, "Отлично!" }, { 4.55, "Надеюсь, у тебя есть всё необходимое снаряжение, потому что эта \"разведка\" может обернуться и кое-чем похуже..." } }, f = { { 0.00, "Привет, героиня!" }, { 1.21, "Желаешь отправиться с нами в разведку?" }, { 3.96, "Отлично!" }, { 4.60, "Надеюсь, у тебя есть всё необходимое снаряжение, потому что эта \"разведка\" может обернуться и кое-чем похуже..." } } } } },
    [469] = { d = 29.1, g = 1, v = "dwarf-male", n = { m = 323, f = 330 }, c = { m = { { 0.00, "Привет тебе, странник!" }, { 1.66, "Не лежит ли твой путь в сторону Менетила?" }, { 4.55, "Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт." }, { 10.50, "Прелестный городок!" }, { 11.91, "Ну а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана." }, { 21.26, "Я бы и сам отнёс их, но дома последнее время то свара, то скандал." }, { 25.87, "Не хочу попадаться жене на глаза." } }, f = { { 0.00, "Привет тебе, путешественница!" }, { 2.15, "Не лежит ли твой путь в сторону Менетила?" }, { 5.08, "Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт." }, { 11.15, "Прелестный городок!" }, { 12.58, "Ну а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана." }, { 22.10, "Я бы и сам отнёс их, но дома последнее время то свара, то скандал." }, { 26.79, "Не хочу попадаться жене на глаза." } } }, t = { d = 16.0, v = "human-male", n = { x = 170 }, c = { x = { { 0.00, "Хмм, да это же от Эйнара, да?" }, { 2.10, "Не вижу его уж который день, а шкуры присылает исправно." }, { 6.24, "Опять поцапался со своей благоверной, к бабке не ходи!" }, { 10.24, "Надо бы подослать жену к Сиде – поговорить, чтобы та не выживала мужа из дому..." } } } } },
    [470] = { d = 34.7, g = 1, v = "dwarf-female#34", n = { m = 360, f = 361 }, c = { m = { { 0.00, "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз всё было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки!" }, { 10.56, "Я так растерялась..." }, { 12.09, "Я бросила в одного из них сумку, но он взял и засосал её!" }, { 16.39, "Мне едва хватило времени, чтобы сбежать." }, { 19.59, "А в сумке-то мои вещи!" }, { 21.39, "Я даже не знаю, какой из этих гадов её сожрал – они все одинаковые!" }, { 26.67, "Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра." }, { 32.44, "Спасибо, что согласился помочь!" } }, f = { { 0.00, "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз всё было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки!" }, { 10.00, "Я так растерялась..." }, { 11.45, "Я бросила в одного из них сумку, но он взял и засосал её!" }, { 15.53, "Мне едва хватило времени, чтобы сбежать." }, { 18.56, "А в сумке-то мои вещи!" }, { 20.27, "Я даже не знаю, какой из этих гадов её сожрал – они все одинаковые!" }, { 25.27, "Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра." }, { 30.74, "Спасибо, что согласилась помочь!" } } }, t = { d = 18.5, v = "dwarf-female#34", n = { x = 182 }, c = { x = { { 0.00, "Спасибо большущее!" }, { 1.84, "Я-то боялась, что её больше не вернуть!" }, { 5.60, "*Она вытряхивает из склизкой сумки содержимое и собирает мелочь в кучку.*" }, { 11.04, "Хм, чего-то я здесь самого нужного и не вижу... посмотри, может, тебе что-нибудь отсюда пригодится." } } } } },
    [471] = { d = 30.6, v = "human-male", n = { x = 379 }, c = { x = { { 0.00, "Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков." }, { 5.44, "Он не вернулся обратно, и я отправился на поиски..." }, { 8.79, "Скажем так: зрелище было не для слабонервных." }, { 11.77, "Лекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит!" }, { 16.97, "Если у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником." }, { 26.00, "Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков." } } }, t = { d = 18.2, g = 1, v = "human-male", n = { m = 188, f = 189 }, c = { m = { { 0.00, "Хмм... не думаю, что ты захочешь наняться ко мне в помощники, так ведь?" }, { 5.04, "Хе-хе-хе!" }, { 5.77, "Да шучу я." }, { 6.57, "Староват ты для этого, да и заметно, что у тебя на роду совсем другое написано." }, { 12.40, "Благодарю тебя за помощь." }, { 14.33, "Шкуры отменные – как раз подойдут мне для работы!" } }, f = { { 0.00, "Хмм... не думаю, что ты захочешь наняться ко мне в помощники, так ведь?" }, { 5.16, "Хе-хе-хе!" }, { 5.90, "Да шучу я." }, { 6.72, "Старовата ты для этого, да и заметно, что у тебя на роду совсем другое написано." }, { 12.76, "Благодарю тебя за помощь." }, { 14.72, "Шкуры отменные – как раз подойдут мне для работы!" } } } } },
    [472] = { d = 36.6, g = 1, v = "dwarf-male", n = { x = 376 }, c = { m = { { 0.00, "Дворфы Чёрного Железа захватили Дун Модр!" }, { 2.95, "Я тяжело ранен, герой." }, { 4.65, "Почти все мои однополчане погибли!" }, { 7.20, "Подонки из клана Чёрного Железа набросились на нас, не успели мы оправиться после взрыва." }, { 13.62, "Наш командир, Длинная Коса, протрубил сигнал к отступлению." }, { 17.94, "Во время бегства мне в спину попал топорик." }, { 21.15, "Я потерял сознание..." }, { 22.72, "Очнулся уже в Менетиле, но меня волнует судьба остальных солдат." }, { 27.50, "Надежда умирает последней..." }, { 29.59, "Может быть, Длинная Коса тоже спасся!" }, { 32.41, "Иди в Дун Модр и отыщи его, путник!" } }, f = { { 0.00, "Дворфы Чёрного Железа захватили Дун Модр!" }, { 3.08, "Я тяжело ранен, героиня." }, { 4.99, "Почти все мои однополчане погибли!" }, { 7.66, "Подонки из клана Чёрного Железа набросились на нас, не успели мы оправиться после взрыва." }, { 14.36, "Наш командир, Длинная Коса, протрубил сигнал к отступлению." }, { 18.87, "Во время бегства мне в спину попал топорик." }, { 22.22, "Я потерял сознание..." }, { 23.86, "Очнулся уже в Менетиле, но меня волнует судьба остальных солдат." }, { 28.86, "Надежда умирает последней..." }, { 31.04, "Может быть, Длинная Коса тоже спасся!" }, { 33.98, "Иди в Дун Модр и отыщи его, путница!" } } }, t = { d = 28.1, g = 1, v = "dwarf-male", n = { m = 296, f = 298 }, c = { m = { { 0.00, "Какие новости из Менетила принёс нам добрый герой?" }, { 3.88, "Так-так-так, вот ты какой!" }, { 5.90, "Приятно познакомиться." }, { 7.63, "Что ж, весть добрая." }, { 9.16, "Слава Свету, что молодой Харло выжил." }, { 12.14, "Ранение у него было очень тяжёлое, и нам пришлось отправить его в город на единственном уцелевшем скакуне." }, { 20.32, "Однако в целом ситуация безнадёжная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания." } }, f = { { 0.00, "Какие новости из Менетила принесла нам добрая героиня?" }, { 4.17, "Так-так-так, вот ты какая!" }, { 6.15, "Приятно познакомиться." }, { 7.86, "Что ж, весть добрая." }, { 9.36, "Слава Свету, что молодой Харло выжил." }, { 12.30, "Ранение у него было очень тяжёлое, и нам пришлось отправить его в город на единственном уцелевшем скакуне." }, { 20.36, "Однако в целом ситуация безнадёжная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания." } } } } },
    [473] = { d = 15.3, v = "dwarf-male", n = { x = 177 }, c = { x = { { 0.00, "Орки из клана Драконьей Пасти совсем озверели." }, { 3.34, "Им уже мало одного Альгаза." }, { 5.35, "Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков." }, { 12.90, "Он сейчас в крепости, в зале Войны." } } }, t = { d = 12.1, g = 1, v = "dwarf-male", n = { m = 126, f = 126 }, c = { m = { { 0.00, "Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе." }, { 6.52, "Ты – достойный герой." }, { 8.13, "Нам такие нужны." }, { 9.41, "И у меня уже есть для тебя поручение." } }, f = { { 0.00, "Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе." }, { 6.32, "Ты – достойная героиня." }, { 8.01, "Нам такие нужны." }, { 9.25, "И у меня уже есть для тебя поручение." } } } } },
    [474] = { d = 5.0, v = "narrator", n = { x = 45 }, c = { x = { { 0.00, "Катапульты сожжены." }, { 1.79, "Теперь найди и убей вождя Нек'роша." } } }, t = { d = 19.1, g = 1, v = "dwarf-male", n = { m = 193, f = 195 }, c = { m = { { 0.00, "Чистая работа." }, { 1.19, "Ты нанёс сокрушительный удар оркам из клана Драконьей Пасти." }, { 5.90, "Они ещё не скоро оправятся от него." }, { 8.71, "К тому же их катапульты больше не угрожают Гавани Менетилов." }, { 13.42, "Ты – достойный герой, а Стальгорн не забывает о героях!" }, { 17.71, "Вот твоя награда." } }, f = { { 0.00, "Чистая работа." }, { 1.18, "Ты нанесла сокрушительный удар оркам из клана Драконьей Пасти." }, { 6.05, "Они ещё не скоро оправятся от него." }, { 8.83, "К тому же их катапульты больше не угрожают Гавани Менетилов." }, { 13.50, "Ты – достойная героиня, а Стальгорн не забывает о героях!" }, { 17.88, "Вот твоя награда." } } } } },
    [475] = { d = 30.0, v = "nightelf-male#55", n = { x = 339 }, c = { x = { { 0.00, "Ветер тревоги веет над лесом." }, { 2.24, "Гэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен'этиль." }, { 9.15, "Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе." }, { 15.14, "Но вести от Гэроласа что-то задерживаются, и я начинаю волноваться." }, { 20.01, "Отправляйся на восток в Деревню Звёздного Ветра – мне нужен отчёт Гэроласа, дабы я был спокоен, узнав, что мои братья и сёстры спят спокойно." } } }, t = { d = 7.0, v = "nightelf-male", n = { x = 65 }, c = { x = { { 0.00, "Хвала лесным духам, ты здесь!" }, { 2.67, "Я знал, что Атридас забеспокоится и пришлёт помощь." } } } } },
    [476] = { d = 35.3, g = 1, v = "nightelf-male", n = { m = 387, f = 387 }, c = { m = { { 0.00, "Племя Кривой Сосны поражено порчей!" }, { 2.75, "Эти некогда мирные фурболги обратились против покровителей леса." }, { 7.65, "Они подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звёздного Ветра." }, { 15.50, "Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны." }, { 20.40, "Я слишком изранен, чтобы донести до Атридаса эти страшные вести." }, { 25.30, "Теперь это придётся сделать тебе, юный герой." }, { 28.78, "Остаётся только надеяться, что безумные фурболги Кривой Сосны ещё не уничтожили Бен'этиль!" } }, f = { { 0.00, "Племя Кривой Сосны поражено порчей!" }, { 2.72, "Эти некогда мирные фурболги обратились против покровителей леса." }, { 7.55, "Они подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звёздного Ветра." }, { 15.30, "Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны." }, { 20.14, "Я слишком изранен, чтобы донести до Атридаса эти страшные вести." }, { 24.97, "Теперь это придётся сделать тебе, юная героиня." }, { 28.55, "Остаётся только надеяться, что безумные фурболги Кривой Сосны ещё не уничтожили Бен'этиль!" } } }, t = { d = 4.0, v = "nightelf-male#55", n = { x = 37 }, c = { x = { { 0.00, "Клянусь звёздами!" }, { 1.65, "Воистину тревожные вести!" } } } } },
    [477] = { d = 44.3, v = "scourge-male", n = { x = 463 }, c = { x = { { 0.00, "Как вы, должно быть, знаете, в деревне Янтарная Мельница окопалась враждебная группа людей." }, { 7.35, "Она держится там в основном за счёт поддержки, которую они получают от волшебников Даларана." }, { 14.78, "Я не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной Мельницы, показывает, что она имеет немаленькое значение." }, { 28.17, "Они отправляют повозкой из Хилсбрада сундуки." }, { 31.88, "Многое из привезённого складируется в небольшом лагере к северу от деревни Погребальных Костров." }, { 39.52, "Раздобудьте содержимое одного такого сундука и принесите мне." } } }, t = { d = 23.7, v = "narrator", n = { x = 261 }, c = { x = { { 0.00, "С любопытством открыв крышку ящика, вы находите в нём множество тщательно упакованных предметов." }, { 7.43, "На самом верху лежит связка пожелтевших от времени карт, на которых, судя по всему, изображены Серебряный бор и другие области западного Лордерона." }, { 18.85, "Под картами обнаруживается подвеска таинственно-волшебного вида." } } } } },
    [478] = { d = 5.0, v = "narrator", n = { x = 58 }, c = { x = { { 0.00, "Вы быстро вытаскиваете подвеску из сундука и кладёте крышку на место." } } }, t = { d = 19.8, v = "scourge-male", n = { x = 173 }, c = { x = { { 0.00, "Карты и эта... эта подвеска?" }, { 2.81, "Интересно." }, { 3.83, "Очевидно, что волшебники Даларана почему-то интересуются Янтарной мельницей, но их цель по-прежнему остаётся неизвестной." }, { 14.98, "Может быть, Далар сможет выяснить, что они там ищут." } } } } },
    [479] = { d = 26.4, v = "scourge-male", n = { x = 252 }, c = { x = { { 0.00, "Далар пытается выяснить, каков источник магической силы этих волшебников." }, { 6.43, "А пока что нам нужно замедлить их прогресс любым путём..." }, { 11.30, "Маги, окудники и заступники, несомненно, носят такие подвески." }, { 16.72, "Добудьте их." }, { 17.81, "Чтобы добраться до Янтарной Мельницы, идите на юг по главной дороге, а на развилке сверните на восток." } } }, t = { d = 15.4, v = "scourge-male", n = { x = 159 }, c = { x = { { 0.00, "Далар выяснил, что несмотря на замедление, процесс плетения чар зашёл уже далеко." }, { 6.72, "Некий очень могущественный волшебник направляет магическую энергию." }, { 12.31, "Его нужно как можно скорее остановить." } } } } },
    [480] = { d = 29.0, v = "scourge-male", n = { x = 277 }, c = { x = { { 0.00, "Верховный маг огромной силы отвечает за реактивацию энергетического узла." }, { 6.26, "Они уже далеко зашли, так что единственный способ их остановить – это убить его." }, { 13.29, "Это будет тяжело – безусловно, его защищают многочисленные маги и охранники." }, { 19.93, "Вам надо пойти и разобраться с ним, быстро." }, { 23.64, "Когда он будет мёртв, принесите мне его посох." }, { 27.65, "Идите немедленно." } } }, t = { d = 25.8, v = "scourge-male", n = { x = 262 }, c = { x = { { 0.00, "Магия волшебников рассеивается, и энергетические узлы вновь засыпают." }, { 5.76, "Ваши усилия оказались плодотворными, и мы сумели нанести нашим врагам и могучим волшебникам Даларана серьёзный удар." }, { 15.54, "Однако нужно не терять бдительности – ведь источник энергии находится совсем близко..." }, { 22.81, "Нужно разрабатывать планы на будущее." } } } } },
    [481] = { d = 8.7, v = "scourge-male", n = { x = 88 }, c = { x = { { 0.00, "Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников." } } }, t = { d = 30.4, v = "scourge-male#82", n = { x = 303 }, c = { x = { { 0.00, "Интересно – похоже, новые махинации Кирин-Тора." }, { 4.04, "Это могущественный артефакт." }, { 6.48, "Такие часто использовали могучие волшебники Кирин-Тора для передачи магической энергии." }, { 13.87, "То, что они так много таких вещиц доставляют в Янтарную Мельницу, указывает на то, что затевается что-то серьёзное." }, { 23.47, "Посмотрим, сумею ли я проникнуть сквозь защиту и поточнее разузнать об их намерениях." } } } } },
    [482] = { d = 42.0, v = "scourge-male#82", n = { x = 444 }, c = { x = { { 0.00, "Конечно!" }, { 0.72, "Как же я мог забыть?" }, { 2.29, "Янтарная Мельница была одним из мест, отмеченных магами Кирин Тора, и примечательна тем, что на территории деревни находится спящий энергетический узел." }, { 14.31, "Волшебники, должно быть, планируют реактивировать узел и использовать его энергию для какой-то более серьёзной цели." }, { 23.47, "Мы не можем позволить этому случиться..." }, { 26.69, "Чтобы активировать энергии этого места, понадобится много сил, и мы можем осложнить им задачу, стащив у волшебников подвески." }, { 36.64, "Передайте эту информацию Алистеру, он спланирует дальнейшие действия." } } }, t = { d = 17.4, v = "scourge-male", n = { x = 172 }, c = { x = { { 0.00, "Вы принесли тревожные вести." }, { 2.38, "Если Далар прав – а у меня нет оснований думать иначе – мы должны действовать быстро." }, { 9.47, "Мне нужно выработать совместно с ним план нашей атаки." }, { 13.94, "А тем временем нужно замедлить их прогресс." } } } } },
    [483] = { d = 34.7, v = "nightelf-male#55", n = { x = 390 }, c = { x = { { 0.00, "Захватчиков Кривой Сосны видели в обители Бен'этиль на западе, они крушили там всё подряд." }, { 6.62, "Спящие друиды никогда не смогут выйти из Изумрудного Сна – они даже не понимают, в какую западню угодили, – если мы только им не поможем." }, { 16.65, "Тонкий ритуал спячки нельзя нарушить без реликвий Пробуждения." }, { 21.23, "Отправляйся в обитель и найди талисман Когтя Ворона, Чёрное перо, Небесный сапфир и руну Размещения." }, { 28.57, "Друиды хранят их в священных ларцах." }, { 31.26, "Принеси их мне, и я подготовлю ритуал пробуждения." } } }, t = { d = 6.1, g = 1, v = "nightelf-male#55", n = { m = 45, f = 45 }, c = { m = { { 0.00, "Тебе удалось это сделать, юный герой!" }, { 3.62, "Славно!" }, { 4.36, "И как раз вовремя." } }, f = { { 0.00, "Тебе удалось это сделать, юная героиня!" }, { 3.83, "Славно!" }, { 4.58, "И как раз вовремя." } } } } },
    [484] = { d = 29.1, g = 1, v = "human-male", n = { m = 338, f = 340 }, c = { m = { { 0.00, "Ты, наверное, слышал обо мне." }, { 2.10, "Я Джеймс Халлоран, кожевник." }, { 4.08, "Выделанные мною кроколисковые шкуры расходятся по всему миру!" }, { 8.48, "Уже встречался с Эйнаром?" }, { 10.33, "Он – один из охотников, приносящих мне шкуры." }, { 13.52, "В последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков." }, { 20.47, "Учитывая обстоятельства, я готов заплатить высокую цену за стопку шкур." }, { 25.50, "Молодые кроколиски обитают в водах прямо за городом." } }, f = { { 0.00, "Ты, наверное, слышала обо мне." }, { 2.14, "Я Джеймс Халлоран, кожевник." }, { 4.09, "Выделанные мною кроколисковые шкуры расходятся по всему миру!" }, { 8.44, "Уже встречалась с Эйнаром?" }, { 10.32, "Он – один из охотников, приносящих мне шкуры." }, { 13.47, "В последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков." }, { 20.33, "Учитывая обстоятельства, я готов заплатить высокую цену за стопку шкур." }, { 25.31, "Молодые кроколиски обитают в водах прямо за городом." } } }, t = { d = 12.6, v = "human-male", n = { x = 122 }, c = { x = { { 0.00, "Отлично, превосходно!" }, { 1.80, "Прекрасные шкуры!" }, { 3.29, "Надо немедленно замочить их... но перед этим я хотел бы попросить тебя ещё об одной услуге." }, { 10.92, "Думаю, ты справишься." } } } } },
    [485] = { d = 33.4, v = "narrator", n = { x = 365 }, c = { x = { { 0.00, "Вы обнаружили странный металлический предмет яйцевидной формы." }, { 4.75, "Когда вы нажали на какую-то кнопку, яйцо вдруг ожило, открылось и превратилось в непонятный механизм, который проскрежетал механическим голосом:" }, { 15.69, "\"Меня зовут Карлс Пропеллерз, и мой автономный робот повреждён." }, { 20.44, "Просьба найти робота, вставить в него этот маяк, а потом вернуть мне за вознаграждение\"." }, { 27.25, "\"Я вычислил координаты робота – он разбился в верховье реки близ Осклизлой скалы\"." } } }, t = { d = 30.2, v = "gnome-male", n = { x = 307 }, c = { x = { { 0.00, "*Вы помещаете яйцевидный аварийный маяк в механического цыплёнка.*" }, { 5.01, "*С гудением и жужжанием робот поднимается на ноги, после чего из его механических внутренностей слышится голос Карлса:*" }, { 14.32, "\"Что ж, по крайней мере, КПХ-девять/эйч-эл работает, но ему требуется капитальный ремонт!" }, { 21.23, "Он тяжёлый, и нести его ты не сможешь, но вообще у меня есть одна мысль..." }, { 26.94, "Не хочешь ли присмотреть за ним ещё немного?\"" } } } } },
    [486] = { d = 32.5, v = "nightelf-male#55", n = { x = 370 }, c = { x = { { 0.00, "Настало время спасти друидов-воронов." }, { 2.79, "Если сейчас мы потерпим неудачу, их сон станет вечным." }, { 6.75, "Я подготовлю реликвии Пробуждения и совершу обряд." }, { 10.38, "Но чтобы у меня всё получилось, тварь, виновная в их злоключениях, должна быть уничтожена." }, { 16.73, "Только тогда ритуал может быть выполнен." }, { 19.72, "Это Урсал Изверг разрушил дело наших братьев, и теперь он должен заплатить за свои злодеяния ради их освобождения." }, { 28.08, "Отправляйся в Лагерь у Кривой Сосны на юго-западе и убей его." } } }, t = { d = 18.2, g = 1, v = "nightelf-male#55", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Ты проявил себя как весьма достойный и способный герой." }, { 3.99, "Человек, следующий путём чести столь же неустанно, как ты, обязательно обретёт великую славу в этом мире." }, { 11.38, "Да будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия." } }, f = { { 0.00, "Ты проявила себя как весьма достойная и способная героиня." }, { 4.28, "Человек, следующий путём чести столь же неустанно, как ты, обязательно обретёт великую славу в этом мире." }, { 11.86, "Да будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия." } } } } },
    [487] = { d = 35.5, g = 1, v = "nightelf-female#51", n = { x = 405 }, c = { m = { { 0.00, "Дорогу в Дарнасс нужно охранять." }, { 2.36, "Путники, направляющиеся из Доланаара в Дарнасс, рассказывают о варварских нападениях поражённых порчей фурболгов из племени Кривой Сосны." }, { 11.91, "Каждый день из Дарнасса и в Дарнасс поступают грузы и важные сообщения." }, { 16.94, "Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам." }, { 22.42, "Возьмись же за оружие во имя священного леса, герой." }, { 26.17, "Их логово находится где-то под этим наблюдательным пунктом." }, { 30.38, "Убей шесть душителей из племени Кривой Сосны и возвращайся ко мне." } }, f = { { 0.00, "Дорогу в Дарнасс нужно охранять." }, { 2.39, "Путники, направляющиеся из Доланаара в Дарнасс, рассказывают о варварских нападениях поражённых порчей фурболгов из племени Кривой Сосны." }, { 12.08, "Каждый день из Дарнасса и в Дарнасс поступают грузы и важные сообщения." }, { 17.19, "Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам." }, { 22.74, "Возьмись же за оружие во имя священного леса, героиня." }, { 26.68, "Их логово находится где-то под этим наблюдательным пунктом." }, { 30.95, "Убей шесть душителей из племени Кривой Сосны и возвращайся ко мне." } } }, t = { d = 10.3, g = 1, v = "nightelf-female#51", n = { m = 100, f = 101 }, c = { m = { { 0.00, "Ты славно послужил доброму народу Доланаара и Дарнасса, отважный герой." }, { 5.99, "От имени всех часовых Тельдрассила воздаю тебе хвалу." } }, f = { { 0.00, "Ты славно послужила доброму народу Доланаара и Дарнасса, отважная героиня." }, { 6.03, "От имени всех часовых Тельдрассила воздаю тебе хвалу." } } } } },
    [488] = { d = 39.1, g = 1, v = "creature/satyr", n = { m = 334, f = 337 }, c = { m = { { 0.00, "Вижу, ты работёнку ищешь?" }, { 2.25, "Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце наивному юнцу... вроде тебя." }, { 11.49, "Видишь ли, я могу осчастливить тебя такими вещицами, что тебе и не снились." }, { 18.24, "Но за это ты кое-что мне принесёшь." }, { 21.29, "Мне часто бывают нужны определённые... ингредиенты." }, { 25.79, "Принеси три клыка ночного саблезуба, три пера островной совы и три мотка паутины чащобного тенётника." }, { 34.78, "И пусть это всё останется между нами, герой." } }, f = { { 0.00, "Вижу, ты работёнку ищешь?" }, { 2.25, "Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце наивной девчушке... вроде тебя." }, { 11.75, "Видишь ли, я могу осчастливить тебя такими вещицами, что тебе и не снились." }, { 18.51, "Но за это ты кое-что мне принесёшь." }, { 21.57, "Мне часто бывают нужны определённые... ингредиенты." }, { 26.08, "Принеси три клыка ночного саблезуба, три пера островной совы и три мотка паутины чащобного тенётника." }, { 35.09, "И пусть это всё останется между нами, героиня." } } }, t = { d = 22.2, g = 1, v = "creature/satyr", n = { x = 172 }, c = { m = { { 0.00, "Ха-ха!" }, { 0.72, "Хорошая работёнка!" }, { 2.52, "Кто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать герой?" }, { 10.26, "Я даже мечтать об этом не мог!" }, { 13.32, "Но раз уж так вышло..." }, { 15.48, "Наш милый мир полон неожиданностей." }, { 18.99, "Обманули дурака на четыре кулака!" } }, f = { { 0.00, "Ха-ха!" }, { 0.71, "Хорошая работёнка!" }, { 2.50, "Кто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать героиня?" }, { 10.36, "Я даже мечтать об этом не мог!" }, { 13.39, "Но раз уж так вышло..." }, { 15.53, "Наш милый мир полон неожиданностей." }, { 19.02, "Обманули дурака на четыре кулака!" } } } } },
    [489] = { d = 35.3, g = 1, v = "nightelf-female#51", n = { m = 382, f = 384 }, c = { m = { { 0.00, "Совет Леса узнал, что ты помог Зенну Грязному Копыту!" }, { 4.05, "Этот сатир – враг леса!" }, { 5.85, "И ты, как герой, должен бы понимать, что оскверняешь лес, убивая созданий Природы!" }, { 11.83, "Ты должен искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу!" }, { 18.41, "Преподай Грязному Копыту урок – и заслужишь прощение." }, { 22.40, "Есть такие шишки Скверны – это семена, падающие с деревьев." }, { 26.85, "Они испускают зелёный дым." }, { 28.78, "Скорми несколько штук Грязному Копыту." }, { 31.64, "Он подумает, что ему предлагают что-то вкусненькое." } }, f = { { 0.00, "Совет Леса узнал, что ты помогла Зенну Грязному Копыту!" }, { 4.09, "Этот сатир – враг леса!" }, { 5.84, "И ты, как героиня, должна бы понимать, что оскверняешь лес, убивая созданий Природы!" }, { 11.82, "Ты должна искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу!" }, { 18.24, "Преподай Грязному Копыту урок – и заслужишь прощение." }, { 22.14, "Есть такие шишки Скверны – это семена, падающие с деревьев." }, { 26.49, "Они испускают зелёный дым." }, { 28.37, "Скорми несколько штук Грязному Копыту." }, { 31.16, "Он подумает, что ему предлагают что-то вкусненькое." } } }, t = { d = 5.8, v = "creature/satyr", n = { x = 43 }, c = { x = { { 0.00, "Ну что ты за лапочка!" }, { 2.31, "Я знал, что ты мне ещё пригодишься!" } } } } },
    [490] = { d = 30.6, v = "nightelf-female", n = { x = 368 }, c = { x = { { 0.00, "По приказу часовых я назначаю награду за головы фурболгов из племени Кривой Сосны." }, { 5.69, "Это враги леса." }, { 6.87, "Скверна лишила их рассудка, и теперь они угрожают нашему народу и лесным жителям." }, { 12.57, "Мы отблагодарим всякого, кто защитит Тельдрассил от этой напасти." }, { 17.02, "Только принеси их клыки в качестве доказательства." }, { 20.49, "Больше всего фурболгов собралось в лощине Бен'этиль на западе от Доланаара и с южной стороны от дороги, а также в деревне Звёздного Ветра на востоке." } } }, t = { d = 3.4, g = 1, v = "nightelf-female", n = { m = 35, f = 36 }, c = { m = { { 0.00, "Ты хорошо послужил нам, и получишь награду." } }, f = { { 0.00, "Ты хорошо послужила нам, и получишь награду." } } } } },
    [491] = { d = 37.4, v = "scourge-male", n = { x = 344 }, c = { x = { { 0.00, "Тул как-то рассказывал мне, что давным-давно он вместе с двумя товарищами создал магический жезл, сплетя его из трёх принадлежащих им ученических жезлов." }, { 13.38, "Он был символом их дружбы, и, хотя Тул презрел её, с жезлом он расстаться не мог и не желал отдавать его другим." }, { 23.18, "Поэтому он выкрал жезл и спрятал его в крепости Фенриса." }, { 28.20, "Вот." }, { 28.60, "Отнесите жезл Бетору Ледострелу, одному из прежних друзей Тула." }, { 34.25, "Я уверен, он будет рад его получить." } } }, t = { d = 28.9, v = "scourge-male#82", n = { x = 252 }, c = { x = { { 0.00, "..." }, { 0.32, "Что это?!" }, { 1.21, "У Тула был наш Сплетённый жезл?" }, { 3.86, "Я думал, он пропал, когда наша дружба пошла прахом, и Тул примкнул к Королю-личу!" }, { 11.26, "Должно быть, он не обращался к силе жезла, потому что если бы он сделал это, я бы почувствовал." }, { 19.71, "И хорошо, что Тул не использовал жезл..." }, { 23.17, "Это удивительная находка." }, { 25.50, "Я признателен за неё, и вознагражу тебя." } } } } },
    [492] = { d = 29.6, v = "scourge-male#82", n = { x = 296 }, c = { x = { { 0.00, "Страж смерти сообщил, что недавно был захвачен ещё один дворф-горный пехотинец." }, { 6.55, "Стражи смерти обычно сажают пленных в погреб таверны \"Петля Висельника\", где им оказывается \"достойный приём\"." }, { 15.74, "Почему бы вам не пойти и не угостить пленника специальным напитком, который я приготовил?" }, { 23.13, "В нём есть небольшая примесь того, что Тёмная Госпожа готовит для всего Азерота." } } }, t = { d = 7.1, v = "dwarf-male", n = { x = 68 }, c = { x = { { 0.00, "Ах, наконец-то питьё!" }, { 1.69, "Хоть это и не \"Болтливое пиво\", но я рад хоть чем-то промочить горло." } } } } },
    [493] = { d = 43.3, v = "scourge-male#82", n = { x = 462 }, c = { x = { { 0.00, "Тёмная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало Новую чуму." }, { 8.41, "Мы упорно трудимся и добились значительного прогресса." }, { 12.73, "Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества." }, { 22.65, "Поэтому я хотел бы, чтобы вы доставили мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада." }, { 34.87, "Путь туда неблизкий." }, { 36.53, "Направляйтесь на юг и держитесь поближе к дорогам." }, { 40.48, "Строго следуйте дорожным указателям!" } } }, t = { d = 10.3, v = "scourge-male", n = { x = 88 }, c = { x = { { 0.00, "А, отлично." }, { 1.14, "Я в высшей степени уважаю аптекаря Ренферрела." }, { 5.68, "Сгораю от нетерпения начать изучение его работы." } } } } },
    [494] = { d = 34.8, g = 1, v = "scourge-female", n = { x = 325 }, c = { m = { { 0.00, "Молчи и слушай, герой." }, { 2.04, "Меня направили сюда для наблюдения за городом Хилсбрадом." }, { 7.07, "У меня разведывательная миссия." }, { 9.82, "А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен." }, { 17.28, "Скажи, что страж смерти Леш передала следующие слова:" }, { 21.92, "\"Крик ворона на западе манит.\"" }, { 24.59, "Ступай по дороге на восток и обращай внимание на знаки." }, { 29.46, "Торопись!" }, { 30.32, "Ступай в Мельницу Таррен со всей возможной скоростью!" } }, f = { { 0.00, "Молчи и слушай, героиня." }, { 2.14, "Меня направили сюда для наблюдения за городом Хилсбрадом." }, { 7.03, "У меня разведывательная миссия." }, { 9.70, "А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен." }, { 16.96, "Скажи, что страж смерти Леш передала следующие слова:" }, { 21.47, "\"Крик ворона на западе манит.\"" }, { 24.07, "Ступай по дороге на восток и обращай внимание на знаки." }, { 28.81, "Торопись!" }, { 29.65, "Ступай в Мельницу Таррен со всей возможной скоростью!" } } }, t = { d = 14.4, v = "scourge-female", n = { x = 121 }, c = { x = { { 0.00, "Крик ворона на западе манит?" }, { 2.88, "Отличные новости!" }, { 4.68, "Пора напасть на Хилсбрад." }, { 7.28, "Мы сможем воплотить наш план уничтожения жизни." }, { 11.96, "Вариматрас будет доволен." } } } } },
    [495] = { d = 49.0, v = "creature/banshee", n = { x = 453 }, c = { x = { { 0.00, "Муг'тола и его отряд огров отправили в долину Альтерака за короной Воли для леди Сильваны." }, { 8.32, "К сожалению, вместо того чтобы принести её королеве, этот идиот решил её примерить... наверное, огры не могут устоять перед блестящими побрякушками." }, { 21.87, "Его необдуманный поступок привёл к неприятным последствиям." }, { 27.17, "Корона Воли позволила Муг'толу воспротивиться заклинанию подчинения, наложенному на него леди Сильваной." }, { 36.64, "Тёмная Госпожа хочет, чтобы это стало уроком для остальных." }, { 42.10, "Отправляйся на мельницу Таррен в Хилсбраде и поговори с лейтенантом Мелизарой." } } }, t = { d = 14.0, v = "creature/banshee", n = { x = 126 }, c = { x = { { 0.00, "Тебя прислала Шарлиндра?" }, { 2.28, "Ну хорошо." }, { 3.26, "Вскоре ты поймёшь, что я не терплю пустой болтовни." }, { 7.81, "Муг'тол – наглец, и с ним мы разберёмся быстро, тщательно и безжалостно." } } } } },
    [496] = { d = 42.4, v = "scourge-male", n = { x = 391 }, c = { x = { { 0.00, "Ах, ещё один мерзкий день на мельнице Таррен." }, { 3.98, "От этого чистого воздуха у меня сразу портится настроение." }, { 9.25, "Чем скорее мы заразим здешних людей, тем лучше." }, { 13.47, "Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило." }, { 24.71, "Если ты хочешь принести пользу, добудь для меня следующее: десять языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника." }, { 37.46, "Медведи и пауки-охотники живут рядом с мельницей Таррен." } } }, t = { d = 10.0, g = 1, v = "scourge-male", n = { m = 87, f = 88 }, c = { m = { { 0.00, "Отличные компоненты." }, { 2.02, "Что ж, ты умудрился внести хоть немного радости в мой тоскливый день." }, { 8.59, "Благодарю тебя." } }, f = { { 0.00, "Отличные компоненты." }, { 1.95, "Что ж, ты умудрилась внести хоть немного радости в мой тоскливый день." }, { 8.40, "Благодарю тебя." } } } } },
    [498] = { d = 32.4, v = "orc-male#60", n = { x = 359 }, c = { x = { { 0.00, "Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат." }, { 8.98, "Мы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей." }, { 15.18, "Мы бились изо всех сил, но они сильно превосходили нас числом." }, { 19.74, "В конце концов нескольких из нас взяли в плен, но мне удалось сбежать." }, { 24.82, "Дарнхольд находится на юго-востоке отсюда, по ту сторону реки." }, { 29.44, "Там держат Друлла и Тог'тара, освободи их." } } }, t = { d = 22.9, v = "orc-male#60", n = { x = 232 }, c = { x = { { 0.00, "Значит, люди собирались поработить наших воинов?" }, { 3.89, "Мы ещё им покажем!" }, { 5.30, "Похоже, они захватили Гол'дира, нашего вождя, и держат его в другом месте." }, { 11.30, "Его тоже необходимо отыскать и спасти." }, { 14.41, "Впрочем, пока неизвестно, где он…" }, { 17.03, "Когда у нас появится хоть какая-то зацепка, я немедленно скажу об этом тебе." } } } } },
    [499] = { d = 33.9, v = "scourge-male", n = { x = 280 }, c = { x = { { 0.00, "Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания." }, { 9.75, "Вот, готово!" }, { 11.03, "Ах, ничто не доставляет столько радости в этих проклятых холмах, как принесение страдания в мир." }, { 20.69, "Посмотрим, достигнут ли желанный эффект." }, { 24.79, "Дай попробовать моему помощнику Ампи то, что Тёмная Госпожа готовит людям и созданиям Плети." } } }, t = { d = 0.9, v = "narrator", n = { x = 4 }, c = { x = { { 0.00, "Квак!" } } } } },
    [500] = { d = 30.8, v = "human-male#50", n = { x = 381 }, c = { x = { { 0.00, "Огры из клана Раздробленного Хребта раскопали курган в Альтеракских горах, неподалёку от разрушенного города." }, { 7.18, "Разведчики доносят, что они и сами руины захватили." }, { 10.65, "Мы не дадим им там вольготно расположиться; если они решат, что хорошо устроились, то следующим шагом спустятся с холмов и окажутся прямо рядом с нами!" }, { 20.71, "Ступай на север, в Альтеракские горы и убей побольше огров." }, { 24.72, "Принеси мне грязные бабки – кости, которые они таскают с собой, и получишь неплохую награду." } } }, t = { d = 10.0, v = "human-male#50", n = { x = 122 }, c = { x = { { 0.00, "Отлично." }, { 0.60, "Должно быть, тебе пришлось зарубить целые полчища, чтобы набрать столько бабок." }, { 5.96, "Теперь они к нам не сунутся." }, { 7.87, "По крайней мере, некоторое время." } } } } },
    [501] = { d = 40.0, v = "scourge-male", n = { x = 350 }, c = { x = { { 0.00, "О..." }, { 0.42, "Луга Хилсбрада полны цветов, воздух свеж и приятен." }, { 5.30, "Меня от этого просто тошнит!" }, { 8.08, "Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесёт в мир заслуженную смерть!" }, { 17.51, "Но как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Тёмной Госпожи." }, { 25.01, "Помоги мне!" }, { 26.10, "В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти." }, { 36.04, "Принеси мне немного крови, и мы повеселимся." } } }, t = { d = 2.2, v = "scourge-male", n = { x = 14 }, c = { x = { { 0.00, "Отличная работа." } } } } },
    [502] = { d = 39.5, v = "scourge-male", n = { x = 317 }, c = { x = { { 0.00, "Ах, ничто так не радует, как запах свежей крови в предгорьях!" }, { 6.12, "Смешаем капелюшку этого и щепотку того, и пойдёт веселье!" }, { 11.88, "Из этой крови я сделаю эликсир Боли." }, { 15.66, "Если мои вычисления верны, то этот состав порадует леди Сильвану." }, { 22.41, "Надо его испытать." }, { 24.39, "Отнеси этот эликсир на самую северную ферму Хилсбрадских полей, что на юго-западе." }, { 32.76, "Посмотрим, как моё \"угощение\" понравится собачке фермера Рея, Стэнли." } } }, t = { d = 5.2, v = "narrator", n = { x = 54 }, c = { x = { { 0.00, "Вы наливаете немного эликсира в ладонь и протягиваете её Стэнли." } } } } },
    [503] = { d = 14.1, v = "orc-male#60", n = { x = 157 }, c = { x = { { 0.00, "Судя по добытым тобой документам, Гол'дира держат на большой базе Синдиката, расположенной на севере, вероятно, в Альтеракских горах." }, { 9.79, "Он уж очень давно томится там в плену, пора освободить его." } } }, t = { d = 25.7, v = "orc-male", n = { x = 266 }, c = { x = { { 0.00, "Спасибо." }, { 0.71, "По приказу Вождя я вёл экспедицию из Дуротара, но, как видишь, наши планы несколько нарушились." }, { 8.16, "Меня держали в плену в этом городе, заставляя работать – таскать тяжести и копать…" }, { 14.76, "Впрочем, неважно, что мне пришлось вынести." }, { 18.17, "Куда важнее сведения, которые тебе необходимо доставить тем, кто сейчас возглавляет нашу группу." } } } } },
    [504] = { d = 19.4, g = 1, v = "human-male#50", n = { m = 232, f = 233 }, c = { m = { { 0.00, "Ты уже померился силой с ограми Раздробленного Хребта, а теперь я хочу нанести им настоящий удар…" }, { 6.71, "Ступай в руины Альтерака и отыщи там наёмников из клана Раздробленного Хребта." }, { 12.00, "Убей побольше этих тварей – только так им можно показать, что лучше держаться подальше от земель Альянса." } }, f = { { 0.00, "Ты уже померилась силой с ограми Раздробленного Хребта, а теперь я хочу нанести им настоящий удар…" }, { 6.83, "Ступай в руины Альтерака и отыщи там наёмников из клана Раздробленного Хребта." }, { 12.17, "Убей побольше этих тварей – только так им можно показать, что лучше держаться подальше от земель Альянса." } } }, t = { d = 17.4, g = 1, v = "human-male#50", n = { m = 190, f = 191 }, c = { m = { { 0.00, "Очень хорошо." }, { 1.08, "Вот награда." }, { 2.03, "Кстати, охотясь на огров ты видел город Альтерак." }, { 5.81, "Как он выглядит?" }, { 7.03, "Боюсь, что скверно." }, { 8.52, "Огры не славятся своей чистоплотностью." }, { 11.49, "К счастью, благодаря твоим усилиям они будут держаться подальше от Южнобережья." } }, f = { { 0.00, "Очень хорошо." }, { 1.06, "Вот награда." }, { 1.99, "Кстати, охотясь на огров ты видела город Альтерак." }, { 5.78, "Как он выглядит?" }, { 6.97, "Боюсь, что скверно." }, { 8.43, "Огры не славятся своей чистоплотностью." }, { 11.36, "К счастью, благодаря твоим усилиям они будут держаться подальше от Южнобережья." } } } } },
    [505] = { d = 26.2, v = "human-male", n = { x = 329 }, c = { x = { { 0.00, "Меня недавно назначили чиновником в Южнобережье." }, { 3.28, "Моего предшественника убили, и виновников так и не нашли." }, { 7.11, "Впрочем, расследование показало, что скорее всего их нанял Синдикат – группа воров под командованием злодеев-дворян, бывшей знати павшего королевства Альтерак." }, { 17.86, "Лагерь Синдиката расположен на севере от занимаемой Ордой мельницы Таррен." }, { 22.90, "Убей всех членов Синдиката, которых встретишь там." } } }, t = { d = 21.2, v = "human-male", n = { x = 243 }, c = { x = { { 0.00, "Спасибо." }, { 0.64, "Хотя, быть может, они всё ещё шныряют неподалёку, будем надеяться, что некоторые из убитых воров и бандитов принимали участие в убийстве прежнего чиновника." }, { 11.70, "Но даже если и нет, Синдикат – позор этой земли и человеческой расы." }, { 16.65, "Смерть этих бандитов и воров – добрая весть для всего Южнобережья." } } } } },
    [506] = { d = 36.5, v = "orc-male", n = { x = 372 }, c = { x = { { 0.00, "День или два назад ко мне пришёл главарь этого Синдиката." }, { 4.51, "Его звали Алиден Перенольд, и он нарёк себя лордом этих земель." }, { 9.66, "Он доверил мне свои планы о порабощении орков, выступивших против него, как и планировал его отец и учитель, ненавистный Блэкмур." }, { 19.96, "Куда важнее то, что он привёл с собой свою любовницу, девочку-тростинку по имени Элиза." }, { 26.90, "У неё на шее висело ожерелье, которое жаждет заполучить Вождь." }, { 31.84, "Теперь ступай." }, { 33.05, "Я выберусь сам, когда улажу здесь свои дела." } } }, t = { d = 18.7, v = "orc-male#60", n = { x = 164 }, c = { x = { { 0.00, "Надо же, какие наглецы эти люди!" }, { 3.13, "Мы покажем им, что орки не сдаются!" }, { 6.35, "Отныне это будет нашей целью наравне с тем украшением, которое стремится заполучить наш Вождь." }, { 15.01, "Похоже, одной цели без другой не достичь." } } } } },
    [507] = { d = 16.9, v = "orc-male#60", n = { x = 167 }, c = { x = { { 0.00, "Очевидно, что Перенольда необходимо убить, избавив мир от его гнусной сущности." }, { 6.38, "Его поместье расположено к северу отсюда, на берегах озера Лордамер." }, { 12.75, "Твой долг, добыть медальон для Вождя и вернуться сюда." } } }, t = { d = 9.7, v = "human-female", n = { x = 100 }, c = { x = { { 0.00, "Нет, прошу вас, не убивайте меня!" }, { 2.54, "Я не хотела причинять зло вашему народу, он взял меня против воли!" }, { 7.63, "Пожалуйста..." }, { 8.66, "Пощадите меня!" } } } } },
    [508] = { d = 9.0, v = "human-female", n = { x = 90 }, c = { x = { { 0.00, "Ожерелье?" }, { 0.75, "Конечно же, можешь его забрать..." }, { 3.33, "Да, забирай!" }, { 4.28, "Мне не нужны воспоминания о нём..." }, { 6.80, "Просто оставь меня в покое..." } } }, t = { d = 17.9, g = 1, v = "orc-male#60", n = { m = 181, f = 182 }, c = { m = { { 0.00, "Странно, что вождь пошёл на такие затраты ради этой мелочи." }, { 4.73, "Я не всегда понимаю его мотивы, но я последую за ним, каковы бы ни были его приказы." }, { 11.47, "Ты отлично поработал, и я не сомневаюсь, что вождь будет рад услышать о твоём успехе." } }, f = { { 0.00, "Странно, что вождь пошёл на такие затраты ради этой мелочи." }, { 4.65, "Я не всегда понимаю его мотивы, но я последую за ним, каковы бы ни были его приказы." }, { 11.28, "Ты отлично поработала, и я не сомневаюсь, что вождь будет рад услышать о твоём успехе." } } } } },
    [509] = { d = 39.1, v = "scourge-male", n = { x = 357 }, c = { x = { { 0.00, "Новый день, новый эликсир." }, { 2.40, "Если бы я тут командовал, я бы позволил Плети и жалким людишкам сцепиться между собой." }, { 10.10, "Им и так нравится убивать друг друга." }, { 13.39, "Увы, Тёмная Госпожа хочет ускорить процесс, так почему бы не скрасить унылые дни распространением смерти и болезней по стране." }, { 24.53, "Вот мой план: иди-ка ты во Владение Нетандера на юге от мельницы Таррен и на востоке от реки и Южнобережья." }, { 33.91, "Принеси мне шесть цветков Грязного Рыла для нового эликсира." } } }, t = { d = 9.0, v = "scourge-male", n = { x = 74 }, c = { x = { { 0.00, "А, отвратительная вонь цветков Грязного Рыла." }, { 4.61, "Хоть для чего-то эти грязные гноллы годятся." } } } } },
    [510] = { d = 27.8, v = "narrator", n = { x = 291 }, c = { x = { { 0.00, "Среди документов вы находите список необходимых припасов." }, { 4.52, "В их число входят самые простые вещи (еда, оружие, одежда) и несколько необычные (маски, масло, яд)." }, { 12.51, "Впрочем, более всего привлекает внимание срочность запроса – согласно документу, доставить всё необходимое следует как можно скорее, чтобы \"выполнить важную миссию, нацеленную против Южнобережья\"." } } }, t = { d = 12.7, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "*Малеб изучает документы.*" }, { 2.40, "Дурные вести." }, { 3.42, "Судя по сведениям, содержащимся в этих документах, и последним действиям Синдиката, эта банда головорезов объявила войну Южнобережью." } } } } },
    [511] = { d = 3.2, v = "narrator", n = { x = 29 }, c = { x = { { 0.00, "Одно из писем на столе зашифровано." } } }, t = { d = 11.4, v = "human-male", n = { x = 107 }, c = { x = { { 0.00, "Что это?" }, { 0.73, "Минуточку..." }, { 1.75, "Дай-ка взглянуть поближе." }, { 3.86, "..." }, { 4.15, "Хм, никогда не встречался с таким шифром, но, признаться, в этой области я не очень сведущ." } } } } },
    [512] = { d = 32.2, v = "human-male", n = { x = 414 }, c = { x = { { 0.00, "Боюсь, что главари Синдиката жаждут гибели Южнобережья." }, { 3.66, "Мы должны нанести удар первыми, пока они не успели воплотить свои планы." }, { 8.55, "Отправляйся в руины Странбрада, в северной части Альтеракских гор." }, { 12.86, "Мы полагаем, что именно там находится штаб-квартира Синдиката." }, { 16.87, "Нам известно, что эту шайку головорезов возглавляет бывшая знать Альтерака." }, { 21.76, "Дворяне скрываются среди прочих посланников Синдиката, но отличить их можно по перстням-печаткам." }, { 28.13, "Разумеется, прежде необходимо их убить." }, { 30.73, "Принеси мне эти перстни." } } }, t = { d = 9.8, g = 1, v = "human-male", n = { m = 117, f = 118 }, c = { m = { { 0.00, "Лишившись знатных предводителей, Синдикат утратит волю к действию, превратившись в обычную банду разбойников." }, { 7.82, "Ты хорошо послужил Альянсу." } }, f = { { 0.00, "Лишившись знатных предводителей, Синдикат утратит волю к действию, превратившись в обычную банду разбойников." }, { 7.83, "Ты хорошо послужила Альянсу." } } } } },
    [513] = { d = 35.3, g = 1, v = "scourge-male", n = { m = 319, f = 321 }, c = { m = { { 0.00, "Я уже решил, что ещё один день пройдёт без капли радости, но тут ты принёс мне цветки Грязного Рыла." }, { 8.90, "Для начала я смешаю их и сделаю отличный состав." }, { 13.31, "Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода." }, { 19.60, "Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнётся!" }, { 26.79, "Вот возьми этот состав Грязного Рыла и немедленно отнеси его мастеру-аптекарю Фаранеллу." } }, f = { { 0.00, "Я уже решил, что ещё один день пройдёт без капли радости, но тут ты принесла мне цветки Грязного Рыла." }, { 9.21, "Для начала я смешаю их и сделаю отличный состав." }, { 13.65, "Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода." }, { 19.98, "Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнётся!" }, { 27.22, "Вот возьми этот состав Грязного Рыла и немедленно отнеси его мастеру-аптекарю Фаранеллу." } } }, t = { d = 27.4, g = 1, v = "scourge-male", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Тебя послал аптекарь Лидон?" }, { 2.49, "Что ж ты сразу не сказал!" }, { 4.66, "Невзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников." }, { 12.83, "Он прислал состав Грязного Рыла, какой умница!" }, { 16.95, "Я знаю, что замышляет наш друг из Хилсбрада." }, { 20.68, "И мне нравится ход его мысли." }, { 23.24, "Тёмная Госпожа порадуется наступлению новой чумы." } }, f = { { 0.00, "Тебя послал аптекарь Лидон?" }, { 2.47, "Что ж ты сразу не сказала!" }, { 4.71, "Невзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников." }, { 12.83, "Он прислал состав Грязного Рыла, какой умница!" }, { 16.93, "Я знаю, что замышляет наш друг из Хилсбрада." }, { 20.64, "И мне нравится ход его мысли." }, { 23.19, "Тёмная Госпожа порадуется наступлению новой чумы." } } } } },
    [514] = { d = 19.1, v = "human-male", n = { x = 244 }, c = { x = { { 0.00, "У меня есть коллега из Стальгорна, который может расшифровать это письмо." }, { 4.73, "Ступай в Библиотеку в Зале Исследователей Стальгорна и поговори с геологом Грозовой Вершиной." }, { 10.67, "Скажи ему, что тебя прислал я и покажи письмо." }, { 13.72, "Если кто и может прочитать это во всех землях к северу от пика Чёрной горы, то это он." } } }, t = { d = 4.8, v = "dwarf-male", n = { x = 33 }, c = { x = { { 0.00, "А, шифровка!" }, { 1.39, "Да, тут я спец." }, { 2.99, "Дай-ка взглянуть…" } } } } },
    [515] = { d = 36.4, v = "scourge-male", n = { x = 384 }, c = { x = { { 0.00, "Смесь из грибов Грязного Рыла?" }, { 2.42, "Гениально!" }, { 3.27, "Почему я об этом не подумал?" }, { 5.55, "Дай-ка добавлю в этот жуткий состав свой коллоид разложения." }, { 10.38, "Чтобы активировать заражающие элементы смеси, Лидону понадобится крепкое зелье тролльей крови, а также чешуя наги Пронзающего Гребня и глаза мурлоков из племени Рваного Плавника с южного побережья Хилсбрада." }, { 26.88, "Когда принесёшь ему все реагенты, он сам поймёт, что делать." }, { 31.50, "Ох, как же мне не терпится узнать о результатах его эксперимента!" } } }, t = { d = 14.0, v = "scourge-male", n = { x = 112 }, c = { x = { { 0.00, "У меня даже голова закружилась от возбуждения!" }, { 4.82, "Какой эксперимент!" }, { 6.76, "Ты мне очень помог." }, { 8.80, "Мы будем сеять болезнь и смерть по всем этим землям!" } } } } },
    [516] = { d = 39.8, v = "scourge-male", n = { x = 423 }, c = { x = { { 0.00, "Я получил сообщение, что группа нежити спряталась и готовит атаку против нас." }, { 6.10, "Вооружённые этой информацией, мы можем повернуть всё другой стороной и напасть первыми, подавив их планы в самом зародыше." }, { 15.67, "К сожалению, моя информация весьма обрывочная." }, { 19.35, "Говорят, они скрываются в месте, называемом Погибель Берена." }, { 24.17, "Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками." }, { 34.45, "Я доверяю вашей изобретательности." }, { 37.15, "Отыщите их и нанесите им поражение." } } }, t = { d = 12.6, v = "scourge-male", n = { x = 129 }, c = { x = { { 0.00, "Если наши разведчики и агенты продолжат предоставлять столь же ценную информацию, как эта, мы в мгновение ока очистим наши земли от армии Плети Короля-лича." } } } } },
    [517] = { d = 30.2, v = "scourge-male", n = { x = 274 }, c = { x = { { 0.00, "Пришло время испытать новый эликсир." }, { 3.40, "Но зачем же тратить хорошую, очень заразную болезнь на простых лягушек и собак?" }, { 10.62, "Давай устроим настоящее веселье во имя леди Сильваны." }, { 15.57, "Ступай в Дун Гарок." }, { 17.35, "Знаешь, это казармы, где вечно шныряют эти дворфики." }, { 22.21, "Укради у них бочонок землекопского крепкого." }, { 26.19, "Получив эту бочку, я устрою весёлую вечеринку!" } } }, t = { d = 4.7, v = "scourge-male", n = { x = 34 }, c = { x = { { 0.00, "Наконец-то!" }, { 1.39, "Теперь мы готовы действовать!" } } } } },
    [518] = { d = 17.7, v = "creature/banshee", n = { x = 152 }, c = { x = { { 0.00, "Муг'тол и огры Раздробленного Хребта захватили руины Альтерака." }, { 6.12, "Наказать их всерьёз будет нелегко, если не проредить сначала ряды огров." }, { 13.10, "А уж потом мы продолжим." }, { 15.43, "Ясно?" }, { 16.04, "Отлично." }, { 16.90, "Выполняй." } } }, t = { d = 13.1, v = "creature/banshee", n = { x = 108 }, c = { x = { { 0.00, "Снег стал алым от крови огров, но мы не должны останавливаться, пока не втопчем дух и тело огров Раздробленного Хребта в грязь и снег." } } } } },
    [519] = { d = 18.6, v = "creature/banshee", n = { x = 158 }, c = { x = { { 0.00, "Тарг, Навозер и Гломмус – лейтенанты Муг'Тола." }, { 4.38, "Они верны ему, хотя кто там разберёт, что вынуждает огров быть верными." }, { 11.16, "Принеси мне их головы, и нам останется отрубить башку Муг'Толу вместе с короной." } } }, t = { d = 18.2, v = "creature/banshee", n = { x = 164 }, c = { x = { { 0.00, "...а я-то думала, что для начала огры зверски воняют." }, { 4.82, "Когда ты принесёшь мне голову Муг'Тола, я прикажу отнести её вместе с этими на пики Альтерака." }, { 13.18, "Неплохой памятник тем, кто идёт против воли Тёмной Госпожи." } } } } },
    [520] = { d = 28.8, v = "creature/banshee", n = { x = 261 }, c = { x = { { 0.00, "Лейтенанты Муг'Тола мертвы, и нам остаётся только убить его самого и забрать корону Воли." }, { 8.14, "Нет сомнений, ему не захочется с ней расставаться." }, { 12.61, "Скорее всего, он ждёт тебя, учитывая... уменьшение числа его товарищей." }, { 19.12, "Отыщи Муг'Тола и принеси мне его голову вместе с короной." }, { 24.41, "Положим конец сопротивлению Раздробленного Хребта." } } }, t = { d = 16.0, g = 1, v = "creature/banshee", n = { m = 141, f = 142 }, c = { m = { { 0.00, "Ты с честью выполнил свой долг." }, { 2.91, "Голова Муг'Тола украсит высочайшую вершину среди руин Альтерака, и стражи смерти сотрут с лица земли остатки клана Раздробленного Хребта." } }, f = { { 0.00, "Ты с честью выполнила свой долг." }, { 2.86, "Голова Муг'Тола украсит высочайшую вершину среди руин Альтерака, и стражи смерти сотрут с лица земли остатки клана Раздробленного Хребта." } } } } },
    [521] = { d = 15.7, v = "creature/banshee", n = { x = 148 }, c = { x = { { 0.00, "Остаётся отнести корону Воли Шарлиндре в Подгород." }, { 4.43, "Она уж передаст её леди Сильване." }, { 7.44, "Но даже не думай воспользоваться ей в личных целях." }, { 11.96, "Пусть тебе послужит уроком судьба Муг'Тола." } } }, t = { d = 25.8, v = "creature/banshee", n = { x = 212 }, c = { x = { { 0.00, "Так значит, этой реликвией воспользовался огр, чтобы не исполнять волю Тёмной Госпожи…" }, { 8.53, "Странно, когда в такой небольшой вещи заключается великая сила." }, { 14.99, "Которая попала в такие неуклюжие руки." }, { 18.94, "Молодец." }, { 19.84, "Я отнесу корону леди Сильване и доложу ей о твоих подвигах." } } } } },
    [522] = { d = 8.7, v = "narrator", n = { x = 97 }, c = { x = { { 0.00, "Это контракт на убийство мирового судьи Генри Малеба." }, { 4.19, "Он был опечатан красным воском с характерным оттиском кольца." } } }, t = { d = 11.3, v = "human-male", n = { x = 119 }, c = { x = { { 0.00, "*Малеб изучает контракт.*" }, { 2.08, "Теперь мне понятна подоплёка последнего нападения на Южнобережье." }, { 6.28, "Наверное, Синдикат хочет добраться до меня, как и до моего предшественника!" } } } } },
    [523] = { d = 23.3, v = "human-male", n = { x = 280 }, c = { x = { { 0.00, "Добытый тобой контракт был подписан бароном Вардусом, дворянином из бывшего королевства Альтерака, прославившимся холодным сердцем и необычайной жестокостью." }, { 10.86, "Неудивительно, что за этим стоял барон." }, { 13.63, "Отыщи его." }, { 14.44, "Отыщи и сверши над ним суд." }, { 16.33, "Должно быть, он прячется в одном из убежищ Синдиката – руинах Странбрада или долине на севере оттуда." } } }, t = { d = 5.4, g = 1, v = "human-male", n = { m = 55, f = 57 }, c = { m = { { 0.00, "Спасибо." }, { 0.70, "У меня на душе полегчало, когда ты вышиб дух из этого злодея!" } }, f = { { 0.00, "Спасибо." }, { 0.69, "У меня на душе полегчало, когда ты вышибла дух из этого злодея!" } } } } },
    [524] = { d = 34.7, v = "scourge-male", n = { x = 341 }, c = { x = { { 0.00, "За соседней дверью стражи смерти держат нескольких заложников-фермеров." }, { 6.15, "Верховный палач Дарталия подозревает, что среди них скрывается один из военных-стратегов." }, { 13.75, "Очевидно, его нашли мёртвым в Чумных землях." }, { 17.59, "Дарталия всегда заботится обо мне и решила передать пленников мне в руки." }, { 23.89, "Пора устроить этим фермерам вечеринку." }, { 27.27, "Ох, повеселимся!" }, { 28.65, "Поставь гниющий бочонок на ковёр у них в комнате." }, { 32.80, "Чумной напиток для всех!" } } }, t = { d = 3.8, v = "narrator", n = { x = 37 }, c = { x = { { 0.00, "Вы ставите гниющий бочонок на пыльный ковёр." } } } } },
    [525] = { d = 20.6, v = "dwarf-male", n = { x = 243 }, c = { x = { { 0.00, "Я расшифровал письмо, но не знаю, что с ним дальше делать." }, { 3.92, "Вы нашли его у воров в предгорьях Альтерака?" }, { 6.98, "Очень странно..." }, { 8.15, "Надо доставить это письмо магистрату Южнобережья." }, { 11.58, "Хотя письмо и зашифровано, это ближайший город к горам Альтерака, и если назревает какая-то опасность, то они должны об этом узнать." } } }, t = { d = 17.0, v = "human-male", n = { x = 178 }, c = { x = { { 0.00, "*Малеб читает письмо.*" }, { 2.08, "Это расшифровка письма, найденного вами в лагере Синдиката?" }, { 6.20, "Оно написано не вором, и даже не альтеракским аристократом." }, { 10.27, "Похоже, у Синдиката есть связи с другими силами, и мне страшно подумать, что это за силы могут быть." } } } } },
    [526] = { d = 13.0, g = 1, v = "dwarf-male", n = { m = 143, f = 143 }, c = { m = { { 0.00, "Ты нашёл только один слиток светлостали – этого не хватит, чтобы выковать что-нибудь стоящее." }, { 6.98, "Вернись и поищи ещё слитки." }, { 9.07, "Думается, их растащили мурлоки, разграбившие корабль." } }, f = { { 0.00, "Ты нашла только один слиток светлостали – этого не хватит, чтобы выковать что-нибудь стоящее." }, { 6.84, "Вернись и поищи ещё слитки." }, { 8.86, "Думается, их растащили мурлоки, разграбившие корабль." } } }, t = { d = 5.7, g = 1, v = "dwarf-male", n = { m = 58, f = 58 }, c = { m = { { 0.00, "А, ты нашёл их!" }, { 1.17, "Теперь давай эту светосталь скуём во что-нибудь полезное?" } }, f = { { 0.00, "А, ты нашла их!" }, { 1.22, "Теперь давай эту светосталь скуём во что-нибудь полезное?" } } } } },
