    [530] = { d = 29.9, v = "scourge-male", n = { x = 251 }, c = { x = { { 0.00, "Когда-то Валдред был моим лучшим другом, а потом убил мою жену." }, { 6.31, "Горевать я уже не способен, но до сих пор жажду мести." }, { 11.50, "Если ты убьёшь Валдреда и принесёшь мне его проклятые руки, я тебя награжу." }, { 18.67, "По последним слухам, он был у Стены Седогрива в южном Серебряном бору." }, { 25.42, "Небось, пытается сбежать в королевство Гильнеас." } } }, t = { d = 27.9, g = 1, v = "scourge-male", n = { m = 216, f = 218 }, c = { m = { { 0.00, "А, хорошо." }, { 1.06, "Этими руками была убита моя жена, Делия." }, { 5.31, "С тех пор я думал только о мести, и вот ты стал моим оружием." }, { 11.25, "Возьми кольцо, которое вернул мне ранее." }, { 15.32, "Делия так давно умерла, что я не нуждаюсь в этой безделушке." }, { 21.25, "Лучше я оставлю себе эти руки в память о предательстве друга." } }, f = { { 0.00, "А, хорошо." }, { 1.08, "Этими руками была убита моя жена, Делия." }, { 5.38, "С тех пор я думал только о мести, и вот ты стала моим оружием." }, { 11.58, "Возьми кольцо, которое вернула мне ранее." }, { 15.79, "Делия так давно умерла, что я не нуждаюсь в этой безделушке." }, { 21.81, "Лучше я оставлю себе эти руки в память о предательстве друга." } } } } },
    [531] = { d = 13.9, v = "human-male", n = { x = 136 }, c = { x = { { 0.00, "Ради всего святого!" }, { 1.67, "Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично!" }, { 8.27, "Скорее убери её отсюда!" }, { 10.23, "Никому здесь не нужны твои страхолюдные трофеи!" } } }, t = { d = 13.8, g = 1, v = "bloodelf-female", n = { m = 150, f = 153 }, c = { m = { { 0.00, "Спасибо, что помог мне выполнить мой маленький план." }, { 3.92, "Я много месяцев жаждала проучить этого надутого самовлюблённого мальчишку, а теперь нам это удалось!" }, { 11.56, "Вот, возьми, ты это заслужил." } }, f = { { 0.00, "Спасибо, что помогла мне выполнить мой маленький план." }, { 4.05, "Я много месяцев жаждала проучить этого надутого самовлюблённого мальчишку, а теперь нам это удалось!" }, { 11.66, "Вот, возьми, ты это заслужила." } } } } },
    [532] = { d = 39.8, v = "scourge-female", n = { x = 369 }, c = { x = { { 0.00, "В Хилсбраде царит паника." }, { 2.34, "Думаю, он скоро падёт." }, { 4.35, "Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки." }, { 13.55, "Невзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия." }, { 21.37, "Мы должны уничтожить их главу, чиновника Бернсайда, и весь городской совет." }, { 28.06, "Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление." }, { 34.76, "И раз уж на то пошло, укради и городскую книгу регистрации." } } }, t = { d = 7.1, g = 1, v = "scourge-female", n = { x = 58 }, c = { m = { { 0.00, "Вести о твоих победах в Хилсбраде быстро разносятся." }, { 4.89, "Отличная работа, герой." } }, f = { { 0.00, "Вести о твоих победах в Хилсбраде быстро разносятся." }, { 4.88, "Отличная работа, героиня." } } } } },
    [533] = { d = 18.0, v = "orc-male#60", n = { x = 194 }, c = { x = { { 0.00, "Наконец-то до нас дошли сведения о местопребывании Гол'дира." }, { 4.61, "Люди постоянно меняли места его заключения, но мы смогли сузить область поиска до большого лагеря Синдиката на севере отсюда." }, { 14.45, "Ступай туда, и заполучи все доступные сведения." } } }, t = { d = 13.1, v = "orc-male#60", n = { x = 141 }, c = { x = { { 0.00, "Наконец-то мы знаем, где держат Гол'дира." }, { 3.16, "В лагере неподалёку отсюда." }, { 5.23, "Будем надеяться, что на сей раз они не успеют подготовиться, как в прошлый раз, когда нас застали врасплох." } } } } },
    [535] = { d = 16.1, g = 1, v = "human-male#50", n = { m = 155, f = 157 }, c = { m = { { 0.00, "Гр-рр..." }, { 0.64, "Ранен, умираю... и враг передо мной." }, { 3.48, "Не сомневаюсь, ты всё равно убьёшь меня, но если бы ты принёс мне немного эля из Южнобережья – вы ведь такое тоже пьёте? – я расскажу тебе то, что ты хочешь знать." } }, f = { { 0.00, "Гр-рр..." }, { 0.64, "Ранен, умираю... и враг передо мной." }, { 3.49, "Не сомневаюсь, ты всё равно убьёшь меня, но если бы ты принесла мне немного эля из Южнобережья – вы ведь такое тоже пьёте? – я расскажу тебе то, что ты хочешь знать." } } }, t = { d = 15.3, v = "human-male#50", n = { x = 156 }, c = { x = { { 0.00, "Принимая во внимание мою неминуемую смерть – думаю, могу с уверенностью сказать, что это самый вкусный напиток в моей жизни..." }, { 9.45, "Вот, возьми – когда я помру, мне это всё равно не понадобится." }, { 13.80, "Ну, слушай!" } } } } },
    [536] = { d = 25.7, v = "human-male#50", n = { x = 300 }, c = { x = { { 0.00, "Меня перевели в Южнобережье из городской стражи Штормграда." }, { 4.10, "Непонятно, как тут вообще люди живут..." }, { 6.83, "А как воняет со стороны пристани и днём и ночью!" }, { 10.12, "Да ещё старый Редпат на мою голову..." }, { 12.72, "Он хочет, чтобы я занялся мурлоками." }, { 15.27, "Ха!" }, { 15.52, "Я едва могу заставить себя подойти к этим рыбам-переросткам на Западном побережье." }, { 21.29, "Если ты разберёшься с ними вместо меня, я буду очень признателен." } } }, t = { d = 15.1, v = "human-male#50", n = { x = 157 }, c = { x = { { 0.00, "Надеюсь, этого хватит, чтобы убедить Крассена, что я – ха! – выполняю его приказы и избавляю Южнобережье от страшной и ужасной угрозы, жутких мурлоков!" }, { 11.82, "Нет ничего страшнее ярости рыбы-переростка!" } } } } },
    [537] = { d = 29.0, v = "human-male", n = { x = 329 }, c = { x = { { 0.00, "Это письмо от существа, называющего себя Нагазом, членом сообщества Недремлющего Аргуса." }, { 6.46, "Не знаю, что это за Аргус, но если он в союзе с Синдикатом, то представляет собой угрозу." }, { 12.92, "Отыщи Нагаза и упомянутых в письме тёмных магов Недремлющего Аргуса." }, { 17.88, "Найди их и убей." }, { 19.12, "Ищи их в Высокогорье, на севере от Странбрада, где позиции Синдиката сильнее всего." }, { 25.12, "Если повезёт, ты найдёшь там послов Недремлющего Аргуса." } } }, t = { d = 18.0, g = 1, v = "human-male", n = { m = 201, f = 200 }, c = { m = { { 0.00, "Молодец." }, { 0.65, "Не хотелось бы, чтобы Недремлющий Аргус присоединился к Синдикату." }, { 5.40, "Хотя тебе и удалось убить их главаря в этих землях, ясно, что Нагаз был чьим-то слугой." }, { 11.84, "Похоже, Недремлющий Аргус пустил корни по всему нашему континенту." }, { 16.71, "Или по всему миру." } }, f = { { 0.00, "Умница." }, { 0.57, "Не хотелось бы, чтобы Недремлющий Аргус присоединился к Синдикату." }, { 5.21, "Хотя тебе и удалось убить их главаря в этих землях, ясно, что Нагаз был чьим-то слугой." }, { 11.50, "Похоже, Недремлющий Аргус пустил корни по всему нашему континенту." }, { 16.27, "Или по всему миру." } } } } },
    [538] = { d = 34.8, v = "human-male", n = { x = 433 }, c = { x = { { 0.00, "Доброго дня вам." }, { 1.09, "Если вы не против долгого путешествия, то у меня для вас найдётся задание, которое поможет пополнить библиотеку Штормграда." }, { 9.25, "Вместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека." }, { 15.17, "Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний!" }, { 20.43, "Мы должны восстановить всё, что можем." }, { 22.97, "Южнобережье – ближайший к руинам Альтерака город." }, { 26.30, "Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом." }, { 30.47, "Он направит вас к руинам, может быть, там вы сумеете найти книги..." } } }, t = { d = 19.4, v = "human-male", n = { x = 232 }, c = { x = { { 0.00, "Да, конечно, я помню Милтона." }, { 2.06, "Такой типичный книжный червь, будь он здоров..." }, { 5.30, "И он совершенно прав." }, { 6.73, "Руины Альтерака по-прежнему полны драгоценных документов, которые находятся под угрозой исчезновения!" }, { 13.71, "Теперь-то в Альтераке обитают огры, а их совершенно не волнуют памятники культуры..." } } } } },
    [539] = { d = 35.4, v = "scourge-female", n = { x = 341 }, c = { x = { { 0.00, "Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса." }, { 7.47, "Более того, львиную долю руды, идущей на вооружение Альянса, добывают именно там." }, { 14.56, "Хотя мы нанесли решительный удар по городу Хилсбраду, Альянс изо всех сил защищает свой рудник." }, { 22.73, "Рудник расположен на юге от Хилсбрада." }, { 26.04, "Ступай туда и убей штейгера, человека по имени Бондс." }, { 30.67, "Убей и его горняков." }, { 32.52, "Альянс надолго запомнит этот урок." } } }, t = { d = 9.0, v = "scourge-female", n = { x = 87 }, c = { x = { { 0.00, "Тёмная Госпожа будет рада услышать, что у неё появился новый рудник, который поможет вооружить её бойцов." } } } } },
    [540] = { d = 30.6, v = "human-male", n = { x = 358 }, c = { x = { { 0.00, "Мерзкие огры поселились в руинах Альтерака, и мне дурно при мысли, что они делают с драгоценными книгами из библиотеки." }, { 8.24, "Спаси всё, что можно!" }, { 9.73, "Ступай в руины Альтерака и поищи там манускрипты, украденные ограми." }, { 14.48, "Собери всё, что сможешь и принеси мне." }, { 17.10, "Больше всего меня интересует одна книга – \"Рука Гри'лека\"." }, { 21.28, "В ней содержится древняя мудрость троллей, о которой я жажду узнать, а последняя копия этой книги находилась именно в руинах Альтерака." } } }, t = { d = 6.5, v = "human-male", n = { x = 57 }, c = { x = { { 0.00, "А, вот они!" }, { 1.05, "Великолепно!" }, { 2.19, "Я немедленно примусь за изучение \"Руки Гри'лека\"." } } } } },
    [541] = { d = 42.7, g = 1, v = "scourge-female", n = { x = 375 }, c = { m = { { 0.00, "Дворфы пришли на помощь людям?" }, { 2.81, "Проклятые мелкие твари!" }, { 4.98, "Что ж, испытаем силу так называемого Альянса." }, { 8.99, "Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев." }, { 16.22, "Мы отлично знаем, где скрывается их цитадель в этих краях." }, { 21.44, "Они построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина." }, { 30.29, "Это местечко зовётся Дун Гарок." }, { 33.10, "Последняя цель этой битвы – осадить Дун Гарок, герой." }, { 37.92, "Глава дворфов, капитан Железная Гора, должен умереть." } }, f = { { 0.00, "Дворфы пришли на помощь людям?" }, { 2.78, "Проклятые мелкие твари!" }, { 4.93, "Что ж, испытаем силу так называемого Альянса." }, { 8.91, "Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев." }, { 16.07, "Мы отлично знаем, где скрывается их цитадель в этих краях." }, { 21.24, "Они построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина." }, { 28.95, "Это местечко зовётся Дун Гарок." }, { 31.74, "Последняя цель этой битвы – осадить Дун Гарок, героиня." }, { 36.67, "Глава дворфов, капитан Железная Гора, должен умереть." } } }, t = { d = 5.6, v = "scourge-female", n = { x = 45 }, c = { x = { { 0.00, "Твои подвиги на поле битвы достойны высочайшей хвалы." } } } } },
    [542] = { d = 19.0, v = "human-male", n = { x = 239 }, c = { x = { { 0.00, "Мне понадобится время на изучение \"Руки Гри'лека\", хотя я не сомневаюсь, что Милтону не терпится вернуть книги в коллекцию Штормграда." }, { 8.79, "Вот книги, добытые тобой в руинах Альтерака." }, { 11.76, "Они уже упакованы и каталогизированы." }, { 14.25, "Отнеси их Милтону Снопу в Штормград, он несомненно будет тебе признателен." } } }, t = { d = 16.6, v = "human-male", n = { x = 183 }, c = { x = { { 0.00, "О небо!" }, { 0.62, "Глазам своим не верю!" }, { 2.34, "Неужели они пережили падение Альтерака?" }, { 5.44, "И всех этих огров!" }, { 6.88, "Спасибо." }, { 7.57, "Огромное спасибо!" }, { 8.94, "Вы помогли нам сохранить человеческие знания, и прибавили великолепия Королевской библиотеке Штормграда." } } } } },
    [543] = { d = 29.4, v = "human-male", n = { x = 344 }, c = { x = { { 0.00, "Тиара Перенольда – старая семейная реликвия одного из древнейших семейств Альтерака, входившего в правящие круги до падения королевства." }, { 9.53, "Говорят, что её изготовили мастера Стальгорна, украсив лучшими изумрудами." }, { 14.47, "Когда Альтерак пал, тиара была утеряна, хотя поговаривали, что огрский маг Грел'борг Скряга нашёл её и теперь пытается разыскать на руинах Альтерака другие сокровища." }, { 27.11, "Мы надеемся, что вы отыщете тиару." } } }, t = { d = 16.6, v = "human-male", n = { x = 186 }, c = { x = { { 0.00, "О, чудесно." }, { 0.86, "Конечно, тиару нужно почистить, но вы, прямо-таки превзошли сами себя." }, { 6.10, "Я велю привести тиару в порядок и немедленно помещу её в нашу сокровищницу." }, { 11.67, "Примите мою благодарность за пополнение коллекции семейных реликвий." } } } } },
    [544] = { d = 42.6, v = "scourge-male#82", n = { x = 399 }, c = { x = { { 0.00, "Я прибыл в Мельницу Таррен с исследовательскими целями, а пришлось разрешать кризис." }, { 7.33, "Видишь ли, четверо Отрёкшихся несколько месяцев назад бежали из Подгорода." }, { 13.79, "Они предали своих братьев, но что ещё хуже... они украли кое-что у Тёмной Госпожи." }, { 21.04, "Эти воры вломились в надёжное хранилище и похитили четыре артефакта, необходимых нашим аптекарям для исследований." }, { 30.97, "Сильвана жаждет вернуть эти артефакты." }, { 34.43, "Воры бежали из Подгорода в Даларан, и волшебники спрятали их в Лордамерских выселках." } } }, t = { d = 12.5, g = 1, v = "scourge-male#82", n = { m = 111, f = 112 }, c = { m = { { 0.00, "Ты оказал Отрёкшимся огромную услугу." }, { 3.41, "Нам очень не хватало этих артефактов." }, { 6.91, "Хорошо, что Кеган и другие предатели получили по заслугам." } }, f = { { 0.00, "Ты оказала Отрёкшимся огромную услугу." }, { 3.56, "Нам очень не хватало этих артефактов." }, { 7.13, "Хорошо, что Кеган и другие предатели получили по заслугам." } } } } },
    [545] = { d = 45.5, v = "scourge-male#82", n = { x = 473 }, c = { x = { { 0.00, "Волшебники Даларана создали вокруг сердца своего города огромный магический купол." }, { 6.81, "Некоторые говорят, что он призван защитить город от опасностей, которыми полнятся наши дни, другие же уверяют, будто волшебники захотели работать и строить планы в тишине и покое." }, { 21.37, "Мне лично наплевать, зачем соорудили этот купол." }, { 25.40, "Меня интересуют развалины на окраинах города, где могут быть спрятаны ценные магические предметы." }, { 33.30, "К сожалению, все окрестности патрулируют волшебники и порабощённые ими элементали." }, { 39.82, "Итак, напади на них и возвращайся, когда существенно сократишь их число." } } }, t = { d = 8.4, v = "scourge-male#82", n = { x = 80 }, c = { x = { { 0.00, "Замечательно." }, { 1.21, "Теперь в руинах можно спокойно поискать артефакты, если быть осторожным." }, { 7.75, "Спасибо." } } } } },
    [546] = { d = 41.1, v = "scourge-male", n = { x = 351 }, c = { x = { { 0.00, "Я слышал, что Дарталия призвала тебя в строй, чтобы выступить против людей Хилсбрада." }, { 7.99, "Как я завидую…" }, { 9.33, "Пока ты там развлекаешься – убиваешь людей, грабишь города, запугиваешь невинных – я торчу здесь, на страже мельницы Таррен." }, { 20.85, "Может, ты смилостивишься над старым стражем смерти?" }, { 25.65, "Видишь, я собираю коллекцию человеческих черепов, а тебе предстоит убить немало смертных." }, { 34.06, "Набери в ходе битвы тридцать черепов, принеси мне, и я тебе хорошо заплачу." } } }, t = { d = 7.8, v = "scourge-male", n = { x = 53 }, c = { x = { { 0.00, "Превосходные черепа!" }, { 2.54, "И какие красивые!" }, { 4.75, "Вот тебе обещанная плата!" } } } } },
    [547] = { d = 37.0, v = "scourge-male", n = { x = 353 }, c = { x = { { 0.00, "Верховный палач Дарталия послала меня наблюдать за Дун Гароком издалека." }, { 6.17, "Я разбил лагерь подальше от дворфов." }, { 9.30, "Но пришло утро, мне нужно было вскипятить воду, и я пошёл за дровами." }, { 15.17, "Вернувшись, я обнаружил, что мои вещи пропали." }, { 19.13, "Очевидно, ко мне заглянули дворфийские разведчики из Дун Гарока и украли их." }, { 25.46, "Мне нужен мой меч!" }, { 26.98, "Если ты сможешь вернуть его, я буду очень признателен." }, { 31.71, "Там так много дворфов... будет нелегко понять, кто же из них вор." } } }, t = { d = 9.8, g = 1, v = "scourge-male", n = { m = 71, f = 71 }, c = { m = { { 0.00, "Ты нашёл его!" }, { 1.52, "Ах, как приятно чувствовать в руке знакомую рукоять." }, { 7.38, "Премного благодарен!" } }, f = { { 0.00, "Ты нашла его!" }, { 1.65, "Ах, как приятно чувствовать в руке знакомую рукоять." }, { 7.65, "Премного благодарен!" } } } } },
    [549] = { d = 25.6, v = "narrator", n = { x = 289 }, c = { x = { { 0.00, "По приказу леди Сильваны все члены организации, именуемой Синдикат, приговариваются к смертной казни." }, { 7.67, "Всех пленных казнят." }, { 9.24, "В настоящий момент организация собирает силы в руинах крепости Дарнхольд на юго-востоке от мельницы Таррен." }, { 17.46, "Всем, предоставившим доказательства своих подвигов верховному палачу Дарталии, будет дарована щедрая награда." } } }, t = { d = 8.2, g = 1, v = "scourge-female", n = { x = 65 }, c = { m = { { 0.00, "Великолепно, герой." }, { 1.93, "Такими темпами мы мигом очистим эти земли от синдикатской швали." } }, f = { { 0.00, "Великолепно, героиня." }, { 1.96, "Такими темпами мы мигом очистим эти земли от синдикатской швали." } } } } },
    [550] = { d = 20.5, g = 1, v = "scourge-female", n = { m = 205, f = 206 }, c = { m = { { 0.00, "Поскольку ты проявил немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм." }, { 11.08, "Пусть его прочитает высшее командование." }, { 14.41, "Отнеси моё письмо Вариматрасу в Подгород." }, { 17.81, "Можешь гордиться собой, герой." } }, f = { { 0.00, "Поскольку ты проявила немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм." }, { 11.17, "Пусть его прочитает высшее командование." }, { 14.50, "Отнеси моё письмо Вариматрасу в Подгород." }, { 17.90, "Можешь гордиться собой, героиня." } } }, t = { d = 36.5, g = 1, v = "named/2425", n = { m = 371, f = 372 }, c = { m = { { 0.00, "Так это ты знаменитый герой, нанёсший сокрушительный удар по силам Альянса в Предгорьях Хилсбрада?" }, { 7.77, "Вести о твоих славных подвигах дошли до Подгорода." }, { 11.87, "Если ты и впредь будешь проявлять подобный героизм, то тебя ожидает великое будущее в рядах бойцов Тёмной Госпожи." }, { 21.01, "Хотя наша главная проблема – наступление с севера Плети Короля-лича, человеческий вопрос тоже не решён и мешает строить планы битвы." }, { 31.74, "Однако ты сумел доказать, что люди могут пасть." }, { 35.55, "И они падут." } }, f = { { 0.00, "Так это ты знаменитая героиня, нанёсшая сокрушительный удар по силам Альянса в Предгорьях Хилсбрада?" }, { 7.80, "Вести о твоих славных подвигах дошли до Подгорода." }, { 11.84, "Если ты и впредь будешь проявлять подобный героизм, то тебя ожидает великое будущее в рядах бойцов Тёмной Госпожи." }, { 20.85, "Хотя наша главная проблема – наступление с севера Плети Короля-лича, человеческий вопрос тоже не решён и мешает строить планы битвы." }, { 31.42, "Однако ты сумела доказать, что люди могут пасть." }, { 35.25, "И они падут." } } } } },
    [551] = { d = 12.2, v = "narrator", n = { x = 126 }, c = { x = { { 0.00, "На этот пергамент наложено заклинание, из-за чего надписи на нём невозможно расшифровать." }, { 7.26, "Вы можете разобрать только одно слово вверху страницы:" }, { 11.80, "Нагаз" } } }, t = { d = 11.9, v = "human-male", n = { x = 145 }, c = { x = { { 0.00, "Опять зашифрованные записки?" }, { 1.98, "Хотел бы я уметь разгадывать шифры, чтобы разобрать все странные фрагменты записей, что доходят к нам из Альтерака." }, { 9.84, "Но боюсь, мне не хватает знаний." } } } } },
    [552] = { d = 35.4, v = "scourge-male#82", n = { x = 363 }, c = { x = { { 0.00, "Мастер Гелькулар почти завершил превращение в лича, когда его ритуальное логово в холмах обнаружила разъярённая толпа людей и зверски убила его." }, { 11.96, "Хуже того, они похоронили моего учителя на кладбище Южнобережья." }, { 17.35, "Немыслимое неуважение к великому волшебнику." }, { 20.97, "Я его ученик, и хочу отомстить ненавистному городу." }, { 25.25, "Первым делом нам понадобится жезл Гелькулара." }, { 28.94, "Его ритуальное логово захватили йети." }, { 32.12, "Жезл несомненно находится у одного из них." } } }, t = { d = 3.8, g = 1, v = "scourge-male#82", n = { m = 21, f = 21 }, c = { m = { { 0.00, "Ты нашёл его!" }, { 2.10, "Великолепно!" } }, f = { { 0.00, "Ты нашла его!" }, { 2.03, "Великолепно!" } } } } },
    [553] = { d = 40.1, v = "scourge-male#82", n = { x = 368 }, c = { x = { { 0.00, "Вот, возьми Гелькуларов жезл." }, { 2.65, "Он тебе понадобится." }, { 4.55, "Гелькулар создал для своего заклятья три церемониальных погребальных костра." }, { 11.51, "Пламя Азеля и пламя Вераза находятся в Пещерах предгорий." }, { 16.89, "Пламя Узеля находится в пещере выше по склону, в северной части гор." }, { 23.27, "Гелькуларов жезл необходимо зарядить в каждом из этих костров." }, { 28.98, "Завершив ритуал, вонзи жезл в гробницу Гелькулара в Южнобережье, надёжно охраняемом человеческом городе на юге." }, { 39.08, "Мы отомстим!" } } }, t = { d = 3.3, v = "narrator", n = { x = 31 }, c = { x = { { 0.00, "Из-под земли доносится глухой грохот." } } } } },
    [554] = { d = 22.1, v = "human-male", n = { x = 286 }, c = { x = { { 0.00, "Геолог Грозовая Вершина – мастер дешифрования и декодирования." }, { 4.02, "Если ты отнесёшь найденный пергамент ему, то при удачном стечении обстоятельств он сможет его прочитать." }, { 10.73, "В настоящий момент Грозовая Вершина работает в штаб-квартире Геологов в Стальгорне." }, { 16.04, "Если увидишь его, сообщи о нашем разговоре – в последнее время я много работы на него свалил." } } }, t = { d = 12.2, v = "dwarf-male", n = { x = 135 }, c = { x = { { 0.00, "Мудрое решение." }, { 1.17, "Всё равно я не верю, что у других учёных хватит умения, чтобы перевести этот свиток." }, { 7.30, "А если он окажется интересным, не бойся – я непременно пошлю за тобой." } } } } },
    [555] = { d = 33.1, v = "human-male", n = { x = 397 }, c = { x = { { 0.00, "Ты скоро поймёшь, что в Южнобережье готовят лучше, чем во всех землях к северу от Штормграда!" }, { 6.20, "Скажем, возьмём мой секретный рецепт черепахового супа." }, { 9.95, "Иногда ко мне захаживают из самого Темнолесья, чтобы насладиться миской-другой." }, { 15.35, "Правда, в последнее время, мне не удавалось его сварить." }, { 19.14, "Я бы сам пошёл к озеру Лордамер у Даларана и поохотился на тамошних хрустогрызов, но это слишком опасно." }, { 26.91, "Если ты принесёшь мне черепашьего мяса и смягчающих пряностей, я мигом сварю этой вкуснятины." } } }, t = { d = 7.1, v = "human-male", n = { x = 70 }, c = { x = { { 0.00, "Все будут в восторге – здесь снова подают нежный черепаховый суп шеф-повара Джессена!" } } } } },
    [556] = { d = 31.8, v = "scourge-male#83", n = { x = 352 }, c = { x = { { 0.00, "Волшебники Даларана славятся своей связью с элементалями, могущественными созданиями из других измерений, которыми они управляют при помощи магических талисманов." }, { 12.48, "Волхв Сиянье Бездны хотел бы изучить эти талисманы." }, { 16.52, "Ступай на земли даларанских волшебников на западе от Хилсбрада и собери несколько талисманов." }, { 23.70, "Такие талисманы носят многие жители Даларана, но я советую поискать их в выселках." }, { 30.11, "Это гораздо безопаснее." } } }, t = { d = 13.1, v = "scourge-male#83", n = { x = 137 }, c = { x = { { 0.00, "Отличные талисманы." }, { 1.59, "Хотя, кажется, из них немного выдохлась магия, оно и к лучшему." }, { 6.71, "Пусть для начала наш колдун поэкспериментирует на менее активных образцах." }, { 12.55, "Спасибо." } } } } },
    [557] = { d = 21.9, v = "scourge-male#83", n = { x = 228 }, c = { x = { { 0.00, "Пока что колдун изучает каменные талисманы, но вскоре ему понадобится и другая часть – браслеты, связующие Стихии." }, { 9.04, "Элементали носят их на запястье, что заставляет их выполнять волю мага." }, { 14.67, "Убей побольше духов в руинах Даларана и собери с них браслеты Земли, и колдун будет доволен." } } }, t = { d = 21.0, v = "scourge-male#83", n = { x = 193 }, c = { x = { { 0.00, "Тебе удалось их найти." }, { 2.04, "Надеюсь, элементали, с которых сняты эти браслеты не очень сопротивлялись?" }, { 8.56, "Хм..." }, { 9.03, "После смерти у меня атрофировалось не только сердце, но и чувство юмора заодно." }, { 16.02, "Что ж, спасибо." }, { 17.35, "Служа колдуну, служишь и Тёмной Госпоже, да." } } } } },
    [558] = { d = 28.7, g = 1, v = "child-male", n = { m = 311, f = 316 }, c = { m = { { 0.00, "Говорят, что леди Джайна Праудмур из Терамора – одна из величайших героинь Альянса." }, { 6.34, "Когда я вырасту, я тоже хочу стать героем Альянса!" }, { 9.98, "Ты знаком с Джайной?" }, { 11.46, "Окажи мне услугу!" }, { 12.73, "Возьми у неё автограф!" }, { 14.33, "Я не знаю, как её попросить, у неё нет времени для таких, как я... другое дело ты!" }, { 20.03, "Ты такой же искатель приключений, как и она!" }, { 23.16, "Готов поспорить, что тебе получить у неё автограф – раз плюнуть!" }, { 27.70, "Пожалуйста!" } }, f = { { 0.00, "Говорят, что леди Джайна Праудмур из Терамора – одна из величайших героинь Альянса." }, { 6.42, "Когда я вырасту, я тоже хочу стать героем Альянса!" }, { 10.04, "Ты знакома с Джайной?" }, { 11.57, "Окажи мне услугу!" }, { 12.84, "Возьми у неё автограф!" }, { 14.43, "Я не знаю, как её попросить, у неё нет времени для таких, как я... другое дело ты!" }, { 20.09, "Ты такая же искательница приключений, как и она!" }, { 23.46, "Готов поспорить, что тебе получить у неё автограф – раз плюнуть!" }, { 27.98, "Пожалуйста!" } } }, t = { d = 21.7, g = 1, v = "child-male", n = { m = 193, f = 195 }, c = { m = { { 0.00, "УХ ТЫ!" }, { 0.53, "Ты достал мне автограф леди Джайны!" }, { 3.58, "Огромное спасибо!" }, { 5.11, "И ух ты... она написала здесь личное послание – мне!" }, { 9.46, "Я знал, что она классная, и, может, однажды я сам её поблагодарю... когда стану героем Альянса!" }, { 17.46, "Ты лучше всех." }, { 18.68, "Спасибо, что ты так добр ко мне." } }, f = { { 0.00, "УХ ТЫ!" }, { 0.54, "Ты достала мне автограф леди Джайны!" }, { 3.72, "Огромное спасибо!" }, { 5.27, "И ух ты... она написала здесь личное послание – мне!" }, { 9.68, "Я знал, что она классная, и, может, однажды я сам её поблагодарю... когда стану героем Альянса!" }, { 17.81, "Ты лучше всех." }, { 19.05, "Спасибо, что ты так добра ко мне." } } } } },
    [559] = { d = 16.0, g = 1, v = "human-male#50", n = { m = 180, f = 181 }, c = { m = { { 0.00, "Ты не поверишь, Крассена не устроили все убитые нами – не скромничай, ты тоже приложил к этому руку." }, { 6.97, "Теперь он хочет от меня доказательств их смерти." }, { 10.09, "Чтобы я отрубил холодные склизские мурлочьи головы и принёс пред его очи!" } }, f = { { 0.00, "Ты не поверишь, Крассена не устроили все убитые нами – не скромничай, ты тоже приложила к этому руку." }, { 7.11, "Теперь он хочет от меня доказательств их смерти." }, { 10.28, "Чтобы я отрубил холодные склизские мурлочьи головы и принёс пред его очи!" } } }, t = { d = 18.2, v = "human-male#50", n = { x = 195 }, c = { x = { { 0.00, "Ох, во имя Света!" }, { 1.33, "С них же течёт на землю какая-то дрянь." }, { 4.12, "Я к ним не притронусь!" }, { 5.71, "Рыбу ещё можно терпеть, но если у неё вырастают ноги и она ходит взад-вперёд..." }, { 11.55, "Я рыбы уже несколько недель не ел, и поверь мне, в Южнобережье это означает жизнь впроголодь." } } } } },
    [560] = { d = 8.4, v = "human-male#50", n = { x = 87 }, c = { x = { { 0.00, "Знаешь, мне даже прикасаться к этим головам не хочется..." }, { 4.31, "Раз уж они у тебя, отнеси их Крассену от моего имени, а?" } } }, t = { d = 9.6, g = 1, v = "human-male#50", n = { m = 108, f = 110 }, c = { m = { { 0.00, "Так ты мальчик на посылках у Фаррена?" }, { 2.68, "Если ты помог ему добыть эти головы, большое тебе спасибо." }, { 7.12, "Южнобережье нуждается в защитниках." } }, f = { { 0.00, "Так ты девочка на посылках у Фаррена?" }, { 2.66, "Если ты помогла ему добыть эти головы, большое тебе спасибо." }, { 7.21, "Южнобережье нуждается в защитниках." } } } } },
    [561] = { d = 11.4, v = "human-male#50", n = { x = 143 }, c = { x = { { 0.00, "Пожалуйста, сообщи лейтенанту Оринелю, что я хотел бы, чтобы он занялся нагами, заселившими Восточное побережье." }, { 7.51, "Когда он добьётся результатов, пусть лично доложит о них мне." } } }, t = { d = 10.1, v = "human-male#50", n = { x = 97 }, c = { x = { { 0.00, "Наги, значит." }, { 1.19, "Похоже, Редпат получил те же сведения, что и я..." }, { 5.19, "Ха!" }, { 5.49, "Он не сможет возвыситься благодаря мне." }, { 8.68, "Позволь объяснить." } } } } },
    [562] = { d = 28.5, v = "human-male#50", n = { x = 339 }, c = { x = { { 0.00, "Мой бывший наставник из городской стражи Штормграда послал мне сообщение, что верховное командование Альянса обеспокоено появлением наг." }, { 9.25, "По слухам, тот, кто хорошо проявит себя в этой области, получит повышение – или, по крайней мере, новое назначение." }, { 17.26, "Есть одна проблема... я не могу справиться с нагами." }, { 20.86, "Разумеется, прекратить пьяную драку или скрутить воинственного вора я могу, но наги мне не по зубам." }, { 27.81, "Помоги мне!" } } }, t = { d = 10.6, v = "human-male#50", n = { x = 125 }, c = { x = { { 0.00, "Разобравшись с нагами в Южнобережье, я могу не сомневаться в новом назначении." }, { 5.38, "Я вернусь обратно в Штормград..." }, { 7.64, "И больше не увижу этот забытый Светом порт." } } } } },
    [563] = { d = 20.2, v = "human-male#50", n = { x = 239 }, c = { x = { { 0.00, "Мне будет легко добиться, чтобы моё донесение прочитали." }, { 3.94, "Новый капитан стражи, майор Самуэльсон, был моим учителем ещё в Штормграде." }, { 9.18, "Ему не составит труда перевести меня обратно в столицу." }, { 13.12, "Но придётся попросить тебя отнести моё донесение ему..." }, { 16.93, "Главное, чтобы старина Крассен ничего не узнал." } } }, t = { d = 14.3, g = 1, v = "human-male", n = { m = 156, f = 158 }, c = { m = { { 0.00, "Что такое?" }, { 0.83, "А..." }, { 1.17, "Значит, мой внимательный ученик занялся проблемой наг Южнобережья." }, { 6.20, "Спасибо, что принёс это мне, я непременно приму это во внимание, пересматривая назначения в следующем месяце." } }, f = { { 0.00, "Что такое?" }, { 0.82, "А..." }, { 1.15, "Значит, мой внимательный ученик занялся проблемой наг Южнобережья." }, { 6.11, "Спасибо, что принесла это мне, я непременно приму это во внимание, пересматривая назначения в следующем месяце." } } } } },
    [564] = { d = 25.0, v = "human-male", n = { x = 285 }, c = { x = { { 0.00, "Ничто не злит меня так, как потеря отличных коней." }, { 3.60, "И поверь, эти назойливые мертвяки, синдикатские бандюги и прочие ни на что не годные негодяи, лишили нас множества лошадок." }, { 12.36, "Но я готов поклясться могилой моего прадедушки, что главный враг коней – горные львы Альтерака." }, { 19.12, "Вечно осложняют мою жизнь!" }, { 21.05, "Ты считаешь себя героем?" }, { 22.85, "Тогда пойди, разберись с ними!" } } }, t = { d = 8.9, v = "human-male", n = { x = 108 }, c = { x = { { 0.00, "Отличные новости!" }, { 1.23, "Надо было сразу же найти нормального героя войны, чтобы он разобрался со зверюгами." }, { 7.00, "Твой папка гордился бы тобой." } } } } },
    [565] = { d = 35.3, g = 1, v = "human-male", n = { m = 342, f = 342 }, c = { m = { { 0.00, "Я, великий Бартоло, сделаю для тебя знаменитый во всём Альянсе, да и во всём мире, плащ из меха йети!" }, { 8.04, "Обыщи весь белый свет, и нигде прекрасней нет!" }, { 11.73, "Что, что я слышу, маленький герой?" }, { 14.48, "\"Бартоло, твои плащи лучше всех!\" Да, да!" }, { 17.81, "Мне не раз это говорили." }, { 19.76, "Бартоло нужен рулон шерсти, плащ жителя холмов от искусного кожевника, тонкая нить и мех йети, конечно!" }, { 28.09, "Принеси мне все составляющие, и ты станешь счастливым обладателем одного из моих плащей!" } }, f = { { 0.00, "Я, великий Бартоло, сделаю для тебя знаменитый во всём Альянсе, да и во всём мире, плащ из меха йети!" }, { 8.08, "Обыщи весь белый свет, и нигде прекрасней нет!" }, { 11.79, "Что, что я слышу, маленькая героиня?" }, { 14.70, "\"Бартоло, твои плащи лучше всех!\" Да, да!" }, { 18.04, "Мне не раз это говорили." }, { 20.01, "Бартоло нужен рулон шерсти, плащ жителя холмов от искусного кожевника, тонкая нить и мех йети, конечно!" }, { 28.38, "Принеси мне все составляющие, и ты станешь счастливым обладателем одного из моих плащей!" } } }, t = { d = 12.9, v = "human-male", n = { x = 129 }, c = { x = { { 0.00, "Пришло время для колдовской работы Бартоло!" }, { 3.57, "Мне не нужен ни посох волшебника, ни жезл мага." }, { 7.35, "Ведь я, великий Бартоло, творю чудеса при помощи простой иглы и нити!" } } } } },
    [566] = { d = 32.4, v = "narrator", n = { x = 384 }, c = { x = { { 0.00, "По приказу верховного палача Дарталии, человек по имени барон Вардус разыскивается по обвинению в многочисленных преступлениях против Отрёкшихся." }, { 10.63, "Вардус является высокопоставленным членом преступной организации Синдикат." }, { 16.11, "В последний раз его видели в Высокогорье Альтеракских гор, к северу от мельницы Таррен." }, { 22.52, "Он приговаривается к смертной казни." }, { 25.20, "Для получения награды необходимо предоставить доказательства его гибели верховному палачу Дарталии." } } }, t = { d = 10.6, v = "scourge-female", n = { x = 93 }, c = { x = { { 0.00, "Ты отлично работаешь." }, { 2.06, "Барон Вардус мёртв, и число главарей Синдиката стало меньше." }, { 7.89, "Недолго им осталось лютовать." } } } } },
    [567] = { d = 43.4, v = "narrator", n = { x = 462 }, c = { x = { { 0.00, "Внимание: вооружены и очень опасны!" }, { 2.89, "Следующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:" }, { 11.62, "Клерк Гораций Белоконь." }, { 13.49, "Разыскивается за убийство стража смерти Томма." }, { 17.25, "Горожанин Вилкс." }, { 18.54, "Разыскивается за убийство аптекаря Эли." }, { 21.72, "Шахтёр Хакетт." }, { 22.87, "Разыскивается за убийство стража смерти Фрая." }, { 26.55, "Фермерша Калаба." }, { 27.93, "Разыскивается за нападение из засады на караван с припасами из Подгорода." }, { 33.70, "Все перечисленные преступники скрываются, и найти их нелегко." }, { 38.53, "Награда будет выдана при предъявлении доказательств их смерти." } } }, t = { d = 3.8, g = 1, v = "scourge-female", n = { x = 29 }, c = { m = { { 0.00, "Да ты неплохой охотник за головами, герой." } }, f = { { 0.00, "Да ты неплохой охотник за головами, героиня." } } } } },
    [568] = { d = 30.4, g = 1, v = "orc-male#60", n = { m = 308, f = 309 }, c = { m = { { 0.00, "Тром'ка, герой!" }, { 1.27, "Ты на удивление вовремя оказался в Гром'голе." }, { 4.81, "Как командир лагеря Вождя, я обязан защищать всех сторонников Орды в этих джунглях." }, { 11.38, "Наша цель – обеспечить бесперебойное снабжение Каменора, а некоторые обитатели здешних мест нам мешают." }, { 19.36, "Я поручаю тебе сократить численность ящеров рядом с Гром'голом." }, { 24.38, "Добившись заметных успехов, возвращайся, и я дам тебе новое задание." } }, f = { { 0.00, "Тром'ка, героиня!" }, { 1.44, "Ты на удивление вовремя оказалась в Гром'голе." }, { 5.12, "Как командир лагеря Вождя, я обязан защищать всех сторонников Орды в этих джунглях." }, { 11.82, "Наша цель – обеспечить бесперебойное снабжение Каменора, а некоторые обитатели здешних мест нам мешают." }, { 19.96, "Я поручаю тебе сократить численность ящеров рядом с Гром'голом." }, { 25.08, "Добившись заметных успехов, возвращайся, и я дам тебе новое задание." } } }, t = { d = 3.8, g = 1, v = "orc-male#60", n = { m = 25, f = 26 }, c = { m = { { 0.00, "Ты исполнил свой долг с честью, герой." } }, f = { { 0.00, "Ты исполнила свой долг с честью, героиня." } } } } },
    [569] = { d = 32.4, v = "orc-male#60", n = { x = 351 }, c = { x = { { 0.00, "Отправляясь в джунгли, мы не собирались воевать с местными племенами." }, { 5.27, "Главное – снабжение Каменора." }, { 7.56, "Увы, возник ряд сложностей." }, { 9.72, "Местные огры заняли руины Мизжа на юго-востоке от Гром'гола." }, { 14.50, "Невзирая на многочисленные предупреждения, они продолжают нападать на наши караваны." }, { 20.96, "Я приказываю тебе разобраться с этими упёртыми ограми." }, { 25.12, "Отправляйся в развалины и попытайся выбить их оттуда." }, { 29.22, "По крайней мере, преподай им хороший урок." } } }, t = { d = 3.8, g = 1, v = "orc-male#60", n = { m = 29, f = 30 }, c = { m = { { 0.00, "Отлично." }, { 0.96, "Ты с честью послужил вождю." } }, f = { { 0.00, "Отлично." }, { 0.96, "Ты с честью послужила вождю." } } } } },
    [570] = { d = 35.0, g = 1, v = "orc-male", n = { m = 335, f = 335 }, c = { m = { { 0.00, "Орда должна узнать о силе магии джунглей и подчинить её себе." }, { 5.27, "Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями." }, { 11.75, "Я сделаю для тебя особую вещь, отважный герой." }, { 15.67, "Принеси мне когти тенебрюхих пантер и клык тигрицы." }, { 19.96, "Учти, что клык должен быть безупречно ровным." }, { 23.73, "Эти твари разгуливают по всем джунглям, но тебе не придётся далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке." } }, f = { { 0.00, "Орда должна узнать о силе магии джунглей и подчинить её себе." }, { 5.29, "Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями." }, { 11.78, "Я сделаю для тебя особую вещь, отважная героиня." }, { 15.86, "Принеси мне когти тенебрюхих пантер и клык тигрицы." }, { 20.17, "Учти, что клык должен быть безупречно ровным." }, { 23.94, "Эти твари разгуливают по всем джунглям, но тебе не придётся далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке." } } }, t = { d = 11.2, v = "orc-male", n = { x = 102 }, c = { x = { { 0.00, "Ты превосходно знаешь джунгли." }, { 2.80, "Отличная добыча!" }, { 4.36, "Я возблагодарю духов за то, что они пожертвовали таких зверей на благо Орды." } } } } },
    [571] = { d = 33.9, v = "orc-male", n = { x = 355 }, c = { x = { { 0.00, "Следующий компонент будет нелегко найти." }, { 3.28, "Чтобы связать перья, когти и чистый клык, мне понадобится волшебный шнурок." }, { 9.27, "Нам подойдёт лишь сухожилие старой гориллы." }, { 12.62, "Его можно добыть только у старых горилл из Мглистой долины." }, { 17.46, "Они кормятся к востоку от Пиратской Бухты." }, { 20.88, "Только сухожилие должно быть в идеальном состоянии." }, { 24.95, "Быть может, тебе понадобится убить нескольких зверей, чтобы понять, что именно мне нужно, но результат того стоит." } } }, t = { d = 5.2, v = "orc-male", n = { x = 44 }, c = { x = { { 0.00, "Превосходное сухожилие." }, { 2.41, "Твои усилия скоро окупятся." } } } } },
    [572] = { d = 32.8, v = "orc-male", n = { x = 350 }, c = { x = { { 0.00, "То, что тебе удалось добыть у зверей из семейства кошачьих – лишь первое, что требуется для создания могущественного зачарованного предмета." }, { 10.64, "Меж тем украшения джунглей, усиленные при помощи моих ритуалов, неплохо послужат тебе в деле помощи Орде и Вождю." }, { 19.46, "Теперь же собери для меня перья тропических ловцов." }, { 23.50, "Эти твари как правило прикрепляют перья на лапы." }, { 27.32, "На юге от Гром'гола, недалеко от большой арены, есть такое племя ящеров." } } }, t = { d = 3.9, v = "orc-male", n = { x = 34 }, c = { x = { { 0.00, "Великолепно." }, { 1.30, "Я немедленно их подготовлю." } } } } },
    [573] = { d = 37.2, v = "orc-male", n = { x = 374 }, c = { x = { { 0.00, "Остаётся лишь одно составляющее, и я смогу наложить чары на колье." }, { 5.51, "К югу отсюда, близко от западного побережья, высоко над утёсами, располагается Святой источник." }, { 13.43, "Он вызывает множество конфликтов среди религиозных учёных." }, { 18.26, "Все расы Азерота утверждают, что воды освящены именно для их народа." }, { 24.00, "Вот моё последнее поручение: принеси мне воду Святого источника." }, { 29.36, "Соблюдай осторожность." }, { 31.24, "Сейчас его окрестности захватили наги." }, { 34.56, "С ними тоже следует разобраться." } } }, t = { d = 11.9, g = 1, v = "orc-male", n = { m = 106, f = 108 }, c = { m = { { 0.00, "Ты принёс мне воду Святого источника, и я могу наложить чары на церемониальное колье." }, { 7.42, "Носи его с гордостью, во имя Вождя и мощи Орды." } }, f = { { 0.00, "Ты принесла мне воду Святого источника, и я могу наложить чары на церемониальное колье." }, { 7.71, "Носи его с гордостью, во имя Вождя и мощи Орды." } } } } },
    [574] = { d = 32.5, v = "human-female#47", n = { x = 403 }, c = { x = { { 0.00, "Теперь, после сокращения численности регулярных войск Курцена, тебе придётся вступить в схватку с его особыми отрядами." }, { 8.00, "Они либо выбираются в лес и убивают наших солдат, либо отсиживаются позади посёлка Курцена, в пещере, называемой Схрон." }, { 16.01, "Я знакома со многими воинами Курцена, и все они отличаются прекрасной подготовкой, верностью и жестокостью." }, { 23.16, "Задание непростое." }, { 24.44, "Если ты сможешь их одолеть, доложи об этом лейтенанту Дорену, моему командиру." }, { 29.77, "Он захочет услышать об этом из первых уст." } } }, t = { d = 17.3, v = "human-male", n = { x = 196 }, c = { x = { { 0.00, "Сержант Йохва поверила в твои способности, а я поверил ей." }, { 4.18, "Мы и надеяться не могли на подобный удар по силам Курцена." }, { 8.36, "Я боялся, что мы, повстанцы, совсем одни, и не сможем справиться с гениальным полковником." }, { 14.72, "Быть может, теперь у нас есть надежда." } } } } },
    [575] = { d = 35.7, v = "goblin-male", n = { x = 386 }, c = { x = { { 0.00, "\"Лучший мастер-кожевник Южных морей и старого и нового мира.\" Вот как меня называют!" }, { 6.40, "Меня!" }, { 6.87, "Дриззлика!" }, { 7.68, "Лучшим коже..." }, { 8.82, "Кхе-кхе." }, { 9.50, "Короче." }, { 10.10, "Мои товары славятся по всему свету как наилучшие по мнению всех экспертов!" }, { 15.69, "Я только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину его любимых превосходных сапог." }, { 24.11, "Не скрою, это самая популярная модель." }, { 27.07, "Чтобы приступить к раскройке, мне нужны шкуры кроколисков." }, { 31.45, "Их можно добыть у реки в северной части Тернистой долины." } } }, t = { d = 16.9, v = "goblin-male", n = { x = 182 }, c = { x = { { 0.00, "Эти шкуры отлично подойдут." }, { 2.14, "Качество не слишком важно, учитывая, что они идут на внутреннюю отделку сапог, главное, чтобы носить было удобно." }, { 10.68, "Если шкуры жестковаты, я вымочу их в тигриной крови." }, { 14.62, "Вот они, секреты мастерства, да?" } } } } },
    [576] = { d = 27.0, v = "human-male", n = { x = 315 }, c = { x = { { 0.00, "Стой!" }, { 0.37, "Кто идёт?" }, { 0.99, "Аррр, кому я нужен без волшебного глаза." }, { 3.79, "Мало того, что я лишился зрения в бою!" }, { 6.52, "Но тогда мне свезло, и один волшебник зачаровал для меня особый стеклянный глаз, и я снова мог видеть." }, { 13.53, "А вчера на меня по дороге накинулись пираты Кровавого Паруса и отобрали у меня глаз!" }, { 19.36, "Кажется, эти типы чувствуют себя в Пиратской бухте как дома." }, { 23.64, "Не поможешь старому морскому волку вернуть зрение?" } } }, t = { d = 11.4, g = 1, v = "human-male", n = { m = 96, f = 96 }, c = { m = { { 0.00, "Лопни моя селезёнка!" }, { 1.88, "Разрази меня гром!" }, { 3.60, "Ты нашёл мой прекрасный глаз!" }, { 6.13, "Проверим, годится ли он по-прежнему." }, { 9.40, "Хо!" }, { 9.73, "Я вижу, вижу!!!" } }, f = { { 0.00, "Лопни моя селезёнка!" }, { 1.92, "Разрази меня гром!" }, { 3.67, "Ты нашла мой прекрасный глаз!" }, { 6.35, "Проверим, годится ли он по-прежнему." }, { 9.69, "Хо!" }, { 10.02, "Я вижу, вижу!!!" } } } } },
    [577] = { d = 22.5, v = "goblin-male", n = { x = 235 }, c = { x = { { 0.00, "Что ж, я раскроил основу сапог, получается превосходно, но на подбой шкур не хватит." }, { 6.31, "\"Что же делать, Дриззлик?\" – спросишь ты." }, { 9.39, "К счастью, ты говоришь со мной, и я скажу тебе, как мы поступим!" }, { 14.19, "Подбой всё равно никто не видит, поэтому мы используем более толстую и дешёвую шкуру кроков с озера Назферити." } } }, t = { d = 16.3, v = "goblin-male", n = { x = 168 }, c = { x = { { 0.00, "Мои сапоги не хуже колбасы." }, { 2.28, "Выглядят отлично, на вкус прекрасны." }, { 5.13, "Я говорю, что внутри сверхкачественное мясо и приправы, и вы едите их с удовольствием." }, { 11.84, "Так куда приятнее – и вкуснее – если не заглядывать внутрь." } } } } },
    [578] = { d = 28.1, v = "goblin-male#180", n = { x = 296 }, c = { x = { { 0.00, "Если правду говорят о гоблине-маге и элементалях воды, живущих на острове, значит я могу заполучить Камень Приливов!" }, { 8.95, "Найди этот остров..." }, { 10.59, "И выясни, что происходит." }, { 12.51, "И если ты хочешь узнать подробнее о Камне Приливов, отнеси эту записку в библиотеку Штормграда, они найдут тебе книгу, в которой я впервые прочитал эту легенду." }, { 24.88, "Неужели Газбан в самом деле нашёл Камень?.." } } }, t = { d = 15.7, v = "goblin-male#180", n = { x = 150 }, c = { x = { { 0.00, "Значит, легенды не лгут!" }, { 2.04, "Немыслимо!" }, { 2.94, "Теперь надо отыскать способ одолеть проклятье Камня Приливов, если мы хотим найти его." }, { 10.41, "Проклятья – дело магов." }, { 12.44, "Значит, надо обратиться к одному из них." } } } } },
    [579] = { t = { d = 2.0, v = "human-male", n = { x = 23 }, c = { x = { { 0.00, "Какая книга вас интересует?" } } } } },
    [580] = { d = 38.0, v = "gnome-male", n = { x = 425 }, c = { x = { { 0.00, "На подходе к Отвесным скалам, как раз в тот момент, когда старые добрые Внутренние земли показались на горизонте, нас настигла жуткая буря." }, { 9.99, "Мы думали – всё, нам каюк, море нас проглотит." }, { 13.30, "Но старый Алкач знает, что такое жидкая храбрость!" }, { 17.00, "У кэпа был ящик портвейна \"Пупелливербос\", который мы взяли трофеем у одного пирата по пути в Штормград." }, { 24.52, "В общем, когда с Внутренних земель налетел шторм, я налёг на грог." }, { 29.19, "И тут шхуну захлестнула большая волна и смыла бутылки за борт." }, { 33.67, "Кэп всыплет мне по первое число, если ты не поможешь их найти." } } }, t = { d = 14.9, g = 1, v = "gnome-male", n = { m = 148, f = 151 }, c = { m = { { 0.00, "Лопни моя селезёнка!" }, { 1.64, "Ты нашёл грог кэпа!" }, { 3.14, "Я по гроб жизни тебе обязан, друг." }, { 5.86, "Похоже, снаружи разыгрался шторм." }, { 8.50, "Пока он не пройдёт, я согрею нутро грогом из одной из этих славных бутылочек..." } }, f = { { 0.00, "Лопни моя селезёнка!" }, { 1.63, "Ты нашла грог кэпа!" }, { 3.19, "Я по гроб жизни тебе обязан, подруга." }, { 6.17, "Похоже, снаружи разыгрался шторм." }, { 8.79, "Пока он не пройдёт, я согрею нутро грогом из одной из этих славных бутылочек..." } } } } },
    [581] = { d = 37.4, v = "troll-male", n = { x = 385 }, c = { x = { { 0.00, "Нас постиг злой рок." }, { 1.56, "И коснулось это младшего сына моего вождя." }, { 5.04, "Как у нас и заведено, мы отдали его на воспитание племени Гурубаши в Зул'Гурубе, но после того, как племя Чёрного Копья последовало за орком Траллом, бедняга Йеннику оказался потерян для нас." }, { 19.93, "Меня прислали в Тернистую долину из далёкого Оргриммара на поиски сына вождя." }, { 26.03, "Я думаю, он в руках племени Кровавого Скальпа." }, { 29.72, "Если ты хочешь помочь мне, напади на них." }, { 32.98, "Они живут к северу отсюда." }, { 35.18, "Собери их клыки и принеси мне." } } }, t = { d = 12.7, v = "troll-male", n = { x = 115 }, c = { x = { { 0.00, "Отличные клыки." }, { 1.46, "Значит, у тебя хватило сил на сражение с племенем Кровавого Скальпа." }, { 7.62, "И это очень хорошо, потому что охота далеко не закончена." } } } } },
    [582] = { d = 33.7, v = "troll-male", n = { x = 366 }, c = { x = { { 0.00, "Мы должны узнать, мёртв ли Йеннику." }, { 2.66, "Убей как можно больше охотников за головами из клана Кровавого Скальпа и забери у них сушёные головы." }, { 10.30, "Набери как можно больше голов, и я осмотрю их, чтобы убедиться, что среди них нет головы Йеннику." }, { 17.66, "Если племя Кровавого Скальпа убило Йеннику, да падёт шестисотлетнее проклятье на душу их предводителя, Ган'зулаха!" }, { 26.26, "Ступай." }, { 26.87, "Охотников за головами можно найти в Руинах Зуулдая и Зул'Кунды, в северной части побережья." } } }, t = { d = 8.5, v = "troll-male", n = { x = 82 }, c = { x = { { 0.00, "Спасибо." }, { 0.76, "Я осмотрю эти головы и узнаю, пал ли бедняга Йеннику под ударом топора охотника за головами." } } } } },
    [583] = { d = 30.6, g = 1, v = "dwarf-male", n = { x = 329 }, c = { m = { { 0.00, "Добро пожаловать в Тернистую долину!" }, { 2.64, "Быть может, ты не знаешь об этом, но этот дворф – единственный и неповторимый Хеминг Эрнестуэй, прославленный герой Альянса и великий охотник на крупную дичь." }, { 13.79, "Он не слишком жалует гостей, но на твою долю, кажется, выпало немало приключений, герой?" }, { 20.16, "Хеминг и сам многое повидал – может, вы с ним найдёте общий язык." }, { 24.80, "Ступай, поговори с ним." }, { 26.48, "Вдруг он научит тебя охотничьим хитростям." } }, f = { { 0.00, "Добро пожаловать в Тернистую долину!" }, { 2.74, "Быть может, ты не знаешь об этом, но этот дворф – единственный и неповторимый Хеминг Эрнестуэй, прославленный герой Альянса и великий охотник на крупную дичь." }, { 14.29, "Он не слишком жалует гостей, но на твою долю, кажется, выпало немало приключений, героиня?" }, { 21.03, "Хеминг и сам многое повидал – может, вы с ним найдёте общий язык." }, { 25.83, "Ступай, поговори с ним." }, { 27.57, "Вдруг он научит тебя охотничьим хитростям." } } }, t = { d = 31.7, g = 1, v = "dwarf-male", n = { m = 332, f = 333 }, c = { m = { { 0.00, "Приятно познакомиться." }, { 1.71, "Давно в наши края не забредал герой." }, { 4.58, "Я здесь с одной-единственной целью – поймать крупного и хитрого зверя." }, { 9.90, "Раз ты, так сказать, личность героическая, может, захочешь принять участие в охоте?" }, { 16.19, "Впрочем, сначала покажи, на что способен." }, { 19.33, "Я научу тебя охотиться на ящеров." }, { 21.92, "Ажек – на тигров." }, { 23.29, "А сэр Эрлгедин – мастер выслеживать пантер." }, { 26.57, "Покажи нам своё искусство, и сможешь принять участие в большой охоте." } }, f = { { 0.00, "Приятно познакомиться." }, { 1.69, "Давно в наши края не забредала героиня." }, { 4.74, "Я здесь с одной-единственной целью – поймать крупного и хитрого зверя." }, { 10.02, "Раз ты, так сказать, личность героическая, может, захочешь принять участие в охоте?" }, { 16.