    [584] = { d = 39.3, v = "troll-male", n = { x = 398 }, c = { x = { { 0.00, "Я не нашёл Йеннику среди голов, хвала Великому Змею за это." }, { 4.80, "Но мы не сильно продвинулись в наших поисках." }, { 8.39, "Необходимо выяснить правду, и, боюсь, она известна лишь вождю племени Кровавого Скальпа и его знахарю." }, { 16.63, "Они враги племени Чёрного Копья, и просто так говорить не будут, поэтому мы должны вырвать правду из их мёртвых губ!" }, { 25.81, "Принеси мне головы Ган'зулаха и Неззилока Зловещего и помести их в этот котёл." }, { 31.98, "Эти тролли живут в глубине руин Зул'Кунды." }, { 35.49, "Принеси их головы... а уж говорить мы их заставим." } } }, t = { d = 4.1, v = "narrator", n = { x = 40 }, c = { x = { { 0.00, "Вы кладёте в котёл головы Ган'зулаха и Неззилока..." } } } } },
    [585] = { d = 38.8, g = 1, v = "troll-male", n = { m = 331, f = 333 }, c = { m = { { 0.00, "*Голова Неззилока начинает говорить.*" }, { 3.28, "Это правда." }, { 4.36, "Я знаю, куда увели дитя племени Чёрного Копья." }, { 8.44, "Ты одолел меня и связал мой дух, но я всё равно не буду говорить даром!" }, { 14.53, "Племя Кровавого Скальпа враждует с племенем Дробителей Черепов." }, { 20.00, "Чтобы добиться от меня ответа, укради три трофейных черепа у племени Дробителей Черепов и положи их к нам, чтобы мой дух обрёл рабов в Пустоте." }, { 32.18, "Один череп возьми в Балиа'ма, другой – в Зиата'джаи, а последний – в Зулмамбве." } }, f = { { 0.00, "*Голова Неззилока начинает говорить.*" }, { 3.12, "Это правда." }, { 4.20, "Я знаю, куда увели дитя племени Чёрного Копья." }, { 8.28, "Ты одолела меня и связала мой дух, но я всё равно не буду говорить даром!" }, { 14.53, "Племя Кровавого Скальпа враждует с племенем Дробителей Черепов." }, { 20.00, "Чтобы добиться от меня ответа, укради три трофейных черепа у племени Дробителей Черепов и положи их к нам, чтобы мой дух обрёл рабов в Пустоте." }, { 32.18, "Один череп возьми в Балиа'ма, другой – в Зиата'джаи, а последний – в Зулмамбве." } } }, t = { d = 15.4, g = 1, v = "troll-male", n = { m = 123, f = 125 }, c = { m = { { 0.00, "Да." }, { 0.35, "Ты сослужил мне добрую службу." }, { 3.31, "Когда мой дух освободится, я войду в Пустоту и обрету трёх отличных слуг!" }, { 10.29, "Ты – гордость своего клана, герой, и умилостивил меня." } }, f = { { 0.00, "Да." }, { 0.34, "Ты сослужила мне добрую службу." }, { 3.33, "Когда мой дух освободится, я войду в Пустоту и обрету трёх отличных слуг!" }, { 10.15, "Ты – гордость своего клана, героиня, и умилостивила меня." } } } } },
    [586] = { d = 42.2, g = 1, v = "troll-male", n = { m = 372, f = 373 }, c = { m = { { 0.00, "*Голова Ган'зулаха начинает говорить.*" }, { 3.28, "Будь ты проклят!" }, { 4.69, "И будь прокляты твои предки!!!" }, { 7.35, "Лишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что:" }, { 15.50, "Отправляйся в сердце владений Дробителей Черепов на востоке." }, { 20.17, "Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому." }, { 28.12, "Ха!" }, { 28.44, "Принеси мне его разбитую броню, если сможешь!" }, { 32.51, "Да оторвёт он у тебя руки и ноги и бросит медленно гнить." }, { 37.44, "Да станешь ты добычей падальщиков!" } }, f = { { 0.00, "*Голова Ган'зулаха начинает говорить.*" }, { 3.12, "Будь ты проклята!" }, { 4.68, "И будь прокляты твои предки!!!" }, { 7.48, "Лишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что:" }, { 16.05, "Отправляйся в сердце владений Дробителей Черепов на востоке." }, { 21.39, "Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому." }, { 29.19, "Ха!" }, { 29.52, "Принеси мне его разбитую броню, если сможешь!" }, { 33.80, "Да оторвёт он у тебя руки и ноги и бросит медленно гнить." }, { 38.99, "Да станешь ты добычей падальщиков!" } } }, t = { d = 22.5, g = 1, v = "troll-male", n = { m = 193, f = 194 }, c = { m = { { 0.00, "Мне не хочется верить тебе, но увы, ты несомненно выполнил моё задание." }, { 6.63, "Теперь, когда Анатек пал, гнев мой поостыл." }, { 10.65, "Твоя сила приведёт тебя к великим свершениям." }, { 14.93, "Но однажды..." }, { 16.19, "Мы встретимся в Пустоте, и снова померяемся силой." }, { 20.88, "Я буду ждать тебя." } }, f = { { 0.00, "Мне не хочется верить тебе, но увы, ты несомненно выполнила моё задание." }, { 6.49, "Теперь, когда Анатек пал, гнев мой поостыл." }, { 10.39, "Твоя сила приведёт тебя к великим свершениям." }, { 14.53, "Но однажды..." }, { 15.75, "Мы встретимся в Пустоте, и с