    [587] = { d = 33.8, g = 1, v = "dwarf-male", n = { m = 366, f = 366 }, c = { m = { { 0.00, "Ах, жизнь моряцкая!" }, { 1.41, "Не скажу, что она хороша, но это моя жизнь." }, { 4.70, "Пришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку." }, { 11.02, "Вредные привычки, но что за пират без пороков, а?" }, { 14.64, "Только представь, как я был разочарован, узнав, что местный травник распродал весь товар." }, { 21.23, "Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса." }, { 27.20, "Готов поспорить, что бесстрашный герой вроде тебя сможет убедить их поделиться товаром, а?" } }, f = { { 0.00, "Ах, жизнь моряцкая!" }, { 1.37, "Не скажу, что она хороша, но это моя жизнь." }, { 4.56, "Пришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку." }, { 10.69, "Вредные привычки, но что за пират без пороков, а?" }, { 14.21, "Только представь, как я был разочарован, узнав, что местный травник распродал весь товар." }, { 20.59, "Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса." }, { 26.39, "Готов поспорить, что бесстрашная героиня вроде тебя сможет убедить их поделиться товаром, а?" } } }, t = { d = 6.8, v = "dwarf-male", n = { x = 67 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.36, "И я даже в море отплыть не успел!" }, { 4.08, "Не знаю даже, как тебя благодарить." } } } } },
    [588] = { d = 38.7, g = 1, v = "troll-male", n = { m = 330, f = 331 }, c = { m = { { 0.00, "*Неззилок говорит.*" }, { 1.92, "Ты сумел угодить и мне, и вождю, и я скажу тебе то, что ты хочешь знать…" }, { 8.16, "Юный Йеннику навеки потерян для своего клана." }, { 12.27, "Его забрал к себе знахарь Занзил Отверженный." }, { 16.37, "Теперь Занзил полностью подчинил себе его тело и душу, и лишь сильнейшая магия может освободить его." }, { 25.37, "Ты такой магией не владеешь, герой." }, { 28.53, "Быть может, племя Чёрного Копья, ваши союзники, могло бы подарить надежду на спасение Йеннику." }, { 36.82, "Но лично я сомневаюсь." } }, f = { { 0.00, "*Неззилок говорит.*" }, { 1.76, "Ты сумела угодить и мне, и вождю, и я скажу тебе то, что ты хочешь знать…" }, { 8.08, "Юный Йеннику навеки потерян для своего клана." }, { 12.18, "Его забрал к себе знахарь Занзил Отверженный." }, { 16.29, "Теперь Занзил полностью подчинил себе его тело и душу, и лишь сильнейшая магия может освободить его." }, { 25.30, "Ты такой магией не владеешь, героиня." }, { 28.61, "Быть может, племя Чёрного Копья, ваши союзники, могло бы подарить надежду на спасение Йеннику." }, { 36.90, "Но лично я сомневаюсь." } } }, t = { d = 16.9, v = "troll-male#77", n = { x = 158 }, c = { x = { { 0.00, "Занзил Отверженный??" }, { 1.79, "Если Йеннику и правда попал в руки этого тролля, могущественного и злого знахаря, то надежды почти нет." }, { 10.81, "Почти." }, { 11.44, "Не больше букашечки." }, { 13.23, "Но малая надежда лучше, чем совсем никакой." } } } } },
    [589] = { d = 37.5, v = "troll-male#77", n = { x = 406 }, c = { x = { { 0.00, "Легенды повествуют о драгоценном камне, сокрытом в самом сердце Тернистой долины." }, { 6.24, "Мы зовём его Оком Разума, и он хранит в себе великую мощь." }, { 10.70, "Если добыть этот камень, быть может, удастся вернуть Йеннику из тьмы." }, { 16.06, "Я попрошу духов джунглей помочь нам в поисках Ока Разума." }, { 20.52, "Тем временем отправляйся в рудник Хрустальной шахты на юго-востоке отсюда и добудь пульсирующие синие осколки из железозубых василисков." }, { 30.88, "Осколки встречаются очень редко, но без их магии мы не сможем подчинить себе Око Разума." } } }, t = { d = 15.6, v = "troll-male#77", n = { x = 133 }, c = { x = { { 0.00, "Молодец." }, { 0.80, "Эти осколки правильной формы, и я уже слышу их голос." }, { 5.71, "Пока тебя не было, я говорил с духами джунглей." }, { 10.05, "Теперь я знаю, где находится Око Разума…" }, { 13.75, "...И кто его охраняет." } } } } },
    [590] = { d = 14.5, g = 1, v = "scourge-male#83", n = { m = 111, f = 111 }, c = { m = { { 0.00, "Что?" }, { 0.44, "ЧТО?!" }, { 0.97, "Денег хочешь?" }, { 2.38, "Не должен я тебе никаких денег." }, { 5.56, "Письмо?" }, { 6.35, "Какое письмо?" }, { 7.77, "Может, ещё и подерёмся?" }, { 9.97, "Ну, приятель, давай!" }, { 12.00, "Вот ещё, деньги я должен..." } }, f = { { 0.00, "Что?" }, { 0.44, "ЧТО?!" }, { 0.96, "Денег хочешь?" }, { 2.36, "Не должен я тебе никаких денег." }, { 5.50, "Письмо?" }, { 6.28, "Какое письмо?" }, { 7.68, "Может, ещё и подерёмся?" }, { 9.86, "Ну, подружка, давай!" }, { 11.87, "Вот ещё, деньги я должен..." } } }, t = { d = 18.8, g = 1, v = "scourge-male#83", n = { m = 163, f = 164 }, c = { m = { { 0.00, "Невероятно!" }, { 1.08, "Какое мастерство!" }, { 2.73, "А я-то думал, ты будешь лёгкой добычей." }, { 6.38, "Да, хорошенько ты меня отделал." }, { 9.27, "Вот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать." } }, f = { { 0.00, "Невероятно!" }, { 1.04, "Какое мастерство!" }, { 2.64, "А я-то думал, ты будешь лёгкой добычей." }, { 6.16, "Да, хорошенько ты меня отделала." }, { 9.04, "Вот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать." } } } } },
    [591] = { d = 30.4, v = "troll-male#77", n = { x = 295 }, c = { x = { { 0.00, "Око Разума находится у огра-мага на востоке отсюда, в глубине холма Мош'Огг." }, { 6.36, "Этого мага зовут Май'Зот, и я помню его с тех пор, как племя Чёрного Копья обитало в Тернистой долине." }, { 14.69, "Он жесток и силён." }, { 16.15, "А если у него есть Око Разума, тем могущественней его магия." }, { 21.12, "Вступи в бой с Май'Зотом и отними у него Око Разума." }, { 25.44, "Задание опасное, но лишь так мы можем надеяться спасти Йеннику." } } }, t = { d = 31.8, g = 1, v = "troll-male#77", n = { m = 311, f = 313 }, c = { m = { { 0.00, "Тебе удалось добыть Око?" }, { 2.10, "Твою силу должно воспевать в легендах!" }, { 5.29, "Кроме того, добывая око ты одолел Май'Зота и отправил его в Пустоту." }, { 10.95, "Вот почему духи молчали о нём." }, { 13.41, "Хорошо, что он покинул мир плоти и крови, но боюсь, что теперь, в царстве духов он снова захватит власть." }, { 21.83, "Впрочем, об этом будем беспокоиться в другой раз." }, { 25.81, "А теперь я проведу ритуал, чтобы приспособить Око Разума для наших нужд..." } }, f = { { 0.00, "Тебе удалось добыть Око?" }, { 2.10, "Твою силу должно воспевать в легендах!" }, { 5.30, "Кроме того, добывая око ты одолела Май'Зота и отправила его в Пустоту." }, { 11.10, "Вот почему духи молчали о нём." }, { 13.57, "Хорошо, что он покинул мир плоти и крови, но боюсь, что теперь, в царстве духов он снова захватит власть." }, { 21.98, "Впрочем, об этом будем беспокоиться в другой раз." }, { 25.97, "А теперь я проведу ритуал, чтобы приспособить Око Разума для наших нужд..." } } } } },
    [592] = { d = 23.0, v = "troll-male#77", n = { x = 246 }, c = { x = { { 0.00, "Я превратил Око Разума в самоцвет Души." }, { 3.11, "Он послужит двоякой цели: оглуши при его помощи Йеннику, а затем помести самоцвет ему на голову, чтобы поймать его душу." }, { 12.60, "Потом отнеси камень Нимбойе." }, { 14.88, "Йеннику живёт у Занзила Отверженного, в руинах Абораза на Хрустальном взморье далёкого мыса Тернистой долины." } } }, t = { d = 18.0, g = 1, v = "troll-male", n = { m = 171, f = 173 }, c = { m = { { 0.00, "Победа!" }, { 0.70, "Ты освободил Йеннику от воли Занзила и выполнил задание, которое я считал безнадёжным." }, { 8.07, "Наше племя будет воспевать твоё имя, и мы на каменных плитах напишем повесть о тебе, чтобы она никогда не забылась." } }, f = { { 0.00, "Победа!" }, { 0.69, "Ты освободила Йеннику от воли Занзила и выполнила задание, которое я считал безнадёжным." }, { 8.16, "Наше племя будет воспевать твоё имя, и мы на каменных плитах напишем повесть о тебе, чтобы она никогда не забылась." } } } } },
    [593] = { t = { d = 12.2, v = "narrator", n = { x = 119 }, c = { x = { { 0.00, "Вы прикасаетесь к его лбу самоцветом Души." }, { 3.64, "Он вздрагивает, когда волшебный предмет всасывает его разум, оставляя лишь тело, бездушную оболочку." } } } } },
    [594] = { d = 32.4, v = "narrator", n = { x = 311 }, c = { x = { { 0.00, "Записка написана красивым почерком." }, { 3.01, "В ней значится:" }, { 4.29, "Любому, кто может мне помочь." }, { 6.77, "Прошу тебя, не оставь меня в нужде." }, { 9.85, "Великий Небогрив держит меня в плену на острове в Южных морях." }, { 15.19, "По ночам я смотрю на чужие звёзды, полускрытые листвой деревьев, но в самую хорошую погоду на северо-западе я вижу Дикое взморье и большие корабли на юго-западе." }, { 28.72, "Молю тебя, мой будущий спаситель, помоги мне." } } }, t = { d = 2.8, g = 1, v = "tauren-female", n = { m = 27, f = 28 }, c = { m = { { 0.00, "Ты явился, чтобы освободить меня?" } }, f = { { 0.00, "Ты явилась, чтобы освободить меня?" } } } } },
    [595] = { d = 35.4, g = 1, v = "goblin-male", n = { m = 416, f = 416 }, c = { m = { { 0.00, "Ты не прочь подзаработать, а, приятель?" }, { 2.58, "Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Разбойникам Черноводья, но не гнать же тебя в шею!" }, { 10.94, "Мы только что бросили якорь в Пиратской бухте, и уже прослышали, что наши соперники – гнусные, подлые пираты Кровавого Паруса – пустили корни в южной части Тернистой долины." }, { 22.87, "Все мои ребята слишком увлеклись грогом и девками!" }, { 26.38, "А мне нужен разведчик." }, { 27.91, "Осмотри залив на севере от Пиратской бухты рядом с Гибельным берегом и расскажи мне, что там творится." } }, f = { { 0.00, "Ты не прочь подзаработать, а, подружка?" }, { 2.63, "Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Разбойникам Черноводья, но не гнать же тебя в шею!" }, { 11.15, "Мы только что бросили якорь в Пиратской бухте, и уже прослышали, что наши соперники – гнусные, подлые пираты Кровавого Паруса – пустили корни в южной части Тернистой долины." }, { 23.29, "Все мои ребята слишком увлеклись грогом и девками!" }, { 26.86, "А мне нужен разведчик." }, { 28.43, "Осмотри залив на севере от Пиратской бухты рядом с Гибельным берегом и расскажи мне, что там творится." } } }, t = { d = 6.9, v = "narrator", n = { x = 74 }, c = { x = { { 0.00, "На крышке бочки лежит карта, на которой торопливо нацарапана пара слов, и несколько монет." } } } } },
    [596] = { d = 30.0, v = "troll-male#77", n = { x = 311 }, c = { x = { { 0.00, "Меня послали в Гром'гол на помощь Нимбойе, но..." }, { 3.74, "У меня здесь свои дела." }, { 5.61, "Племя Кровавого Скальпа – наш заклятый враг." }, { 9.01, "Трофеи, собранные с врагов, дают власть над ними." }, { 12.82, "Ты можешь помочь нашему племени, открыв охоту на врага." }, { 17.19, "Племя Кровавого Скальпа живёт на севере отсюда." }, { 20.86, "Убей побольше троллей этого племени и забери у них ожерелья Кровавых костей." }, { 26.82, "Собери как можно больше, и я награжу тебя." } } }, t = { d = 13.0, v = "troll-male#77", n = { x = 103 }, c = { x = { { 0.00, "А, замечательно." }, { 1.61, "Я сварю их, высосу из них силу и сотру в порошок, и дух наших врагов ослабеет!" }, { 9.38, "Вот." }, { 9.83, "Возьми это в знак благодарности." } } } } },
    [597] = { d = 19.5, v = "narrator", n = { x = 206 }, c = { x = { { 0.00, "На карте Пиратской бухты нарисован красный крестик именно там, где вы стоите." }, { 6.02, "Ниже имеется подпись:" }, { 7.77, "\"Разбейте здесь лагерь и сидите тихо." }, { 10.71, "Не нападайте, пока не получите сигнал с южного командного поста." }, { 15.75, "Если заметите кого постороннего, сразу убивайте.\"" } } }, t = { d = 5.4, g = 1, v = "goblin-male", n = { m = 44, f = 45 }, c = { m = { { 0.00, "Конечно, я помню тебя, герой." }, { 2.39, "Вижу, ты уже вернулся из разведки..." } }, f = { { 0.00, "Конечно, я помню тебя, героиня." }, { 2.54, "Вижу, ты уже вернулась из разведки..." } } } } },
    [598] = { d = 33.0, g = 1, v = "troll-male#77", n = { m = 345, f = 347 }, c = { m = { { 0.00, "Раз ты принёс трофеи от племени Кровавого Скальпа, у меня есть для тебя другое задание." }, { 6.80, "На юго-востоке живёт племя Дробителей Черепов, и мы воевали с ними много лет." }, { 12.89, "Хотя племя Чёрного Копья давно не живёт в Тернистой долине, мы не забыли раздоров с Дробителями Черепов." }, { 21.03, "Так что начни на них охоту." }, { 23.16, "Собери побольше ожерельев расколотых костей и принеси их мне." }, { 27.97, "Помоги нам, и заслужишь признательность племени Чёрного Копья." } }, f = { { 0.00, "Раз ты принесла трофеи от племени Кровавого Скальпа, у меня есть для тебя другое задание." }, { 7.03, "На юго-востоке живёт племя Дробителей Черепов, и мы воевали с ними много лет." }, { 13.14, "Хотя племя Чёрного Копья давно не живёт в Тернистой долине, мы не забыли раздоров с Дробителями Черепов." }, { 21.32, "Так что начни на них охоту." }, { 23.45, "Собери побольше ожерельев расколотых костей и принеси их мне." }, { 28.28, "Помоги нам, и заслужишь признательность племени Чёрного Копья." } } }, t = { d = 14.6, v = "troll-male#77", n = { x = 148 }, c = { x = { { 0.00, "Велика твоя сила, раз тебе удалось заполучить эти ожерелья." }, { 5.05, "Клан Дробителей Черепов пал под твоими ударами, как молодые ростки под тяжёлыми шагами василиска!" }, { 12.93, "Хвала твоим деяниям." } } } } },
    [599] = { d = 21.5, v = "goblin-male", n = { x = 258 }, c = { x = { { 0.00, "Лопни моя селезёнка!" }, { 1.41, "Значит, пираты Кровавого Паруса собираются напасть на Пиратскую бухту?" }, { 6.24, "Вот наглость-то!" }, { 7.34, "Этот город испокон века был в руках Пиратов Черноводья!" }, { 11.20, "Значит, дела обстоят хуже, чем я думал." }, { 13.95, "Немедленно расскажи об этом командиру флота Морскому Рогу!" }, { 17.99, "Этот старый морской волк шатается где-то по городу..." } } }, t = { d = 19.3, g = 1, v = "tauren-male", n = { m = 200, f = 201 }, c = { m = { { 0.00, "Пираты Кровавого Паруса собираются напасть на Пиратскую бухту?" }, { 4.94, "С тем же успехом они могут сразу сброситься с Отвесных скал." }, { 9.68, "И всё же ты оказал моему флоту большую услугу, передав мне эти сведения." }, { 15.40, "Прими благодарность Разбойников Черноводья." } }, f = { { 0.00, "Пираты Кровавого Паруса собираются напасть на Пиратскую бухту?" }, { 5.09, "С тем же успехом они могут сразу сброситься с Отвесных скал." }, { 9.97, "И всё же ты оказала моему флоту большую услугу, передав мне эти сведения." }, { 15.94, "Прими благодарность Разбойников Черноводья." } } } } },
    [600] = { d = 32.8, v = "goblin-male", n = { x = 397 }, c = { x = { { 0.00, "Торговая Компания ведёт операции в Тернистой долине, которые не дают трудолюбивым гоблинам вроде меня честно зарабатывать деньги!" }, { 8.95, "Пожалуйста, помоги мне!" }, { 10.57, "Торговая Компания обосновалась возле Хрустальной шахты к северу отсюда." }, { 15.54, "Внутрь они проникнуть не могут из-за злобных василисков, но всё равно умудряются добывать Поющие кристаллы в ближайших холмах." }, { 24.24, "Отбери у них эти кристаллы, показав тем самым, что джунгли им не принадлежат." }, { 29.52, "И... э... принеси в доказательство сами кристаллы!" } } }, t = { d = 15.0, g = 1, v = "goblin-male", n = { m = 137, f = 138 }, c = { m = { { 0.00, "Отлично!" }, { 0.75, "Чудесно!" }, { 1.49, "Я за них много выручу!!!" }, { 3.51, "Торговая Компания сунулась не в те джунгли, а?" }, { 7.32, "Нам всем станет лучше, если они уберутся отсюда, верно?" }, { 12.03, "Спасибо." }, { 12.77, "Ты сделал доброе дело." } }, f = { { 0.00, "Отлично!" }, { 0.77, "Чудесно!" }, { 1.54, "Я за них много выручу!!!" }, { 3.61, "Торговая Компания сунулась не в те джунгли, а?" }, { 7.52, "Нам всем станет лучше, если они уберутся отсюда, верно?" }, { 12.36, "Спасибо." }, { 13.12, "Ты сделала доброе дело." } } } } },
    [601] = { d = 26.3, v = "goblin-male#180", n = { x = 302 }, c = { x = { { 0.00, "Элементалей воды несомненно призвал Газбан, гоблин-волшебник, который нашёл Камень Приливов, если верить слухам." }, { 8.27, "Мы знаем, что обретший этот камень оказывается проклят, и с тех пор то существует, то нет..." }, { 14.84, "Быть может, удастся снять проклятье." }, { 17.47, "Один даларанский маг может исследовать следы магии на браслетах элементалей." }, { 23.05, "Отправляйся на остров и принеси несколько штук." } } }, t = { d = 26.6, v = "goblin-male#180", n = { x = 290 }, c = { x = { { 0.00, "Я не могу определить навскидку, какие из этих браслетов подойдут, но хотя бы один должен сгодиться." }, { 7.38, "Отнеси их в Даларан, пусть на них посмотрит маг." }, { 10.83, "Не могу же я, в самом деле, уехать из Пиратской бухты ради какого-то старого мага?" }, { 17.02, "Не то, чтобы я беспокоился, что кто-то попытается занять моё место и стать новым бароном." }, { 23.53, "Никто не посмеет встать на пути у Ревилгаза." } } } } },
    [602] = { d = 33.4, v = "goblin-male#180", n = { x = 374 }, c = { x = { { 0.00, "Насколько я знаю, маги Даларана заняты восстановлением своего разрушенного города." }, { 6.14, "Несомненно, один из них найдёт время посмотреть на браслеты." }, { 10.55, "Я знаю про магов одно – они не смогут устоять перед возможностью разгадать запутанную магическую головоломку." }, { 18.69, "Возьми сумку с браслетами элементалей воды и узнай, не прольют ли они свет на проклятье Камня." }, { 25.70, "Лучше всего обратиться к верховному магу Ансарему Руноплёту." }, { 30.17, "Я уже имел с ним дело, и его знания велики." } } }, t = { d = 20.0, v = "human-male", n = { x = 230 }, c = { x = { { 0.00, "Камень Приливов?" }, { 1.20, "Очень интересно." }, { 2.40, "Быть может, вас это удивит – несколько лет назад я написал книгу, посвящённую легендам империи Гурубаши." }, { 9.66, "Я знаю об этом камне довольно много." }, { 12.31, "По крайней мере, на одном из этих браслетов я вижу остатки магии, которые явно поддаются анализу." }, { 19.26, "Посмотрим..." } } } } },
    [603] = { d = 31.1, v = "human-male", n = { x = 350 }, c = { x = { { 0.00, "Маг, который владеет Камнем, может умножить его силу при помощи некой точки фокуса... вроде алтаря." }, { 7.30, "Чтобы не допустить этого, необходим предмет равной силы." }, { 11.43, "Как ни странно, я знаю одну очень подходящую вещь: древний кинжал, ещё одну из тролльских реликвий." }, { 18.54, "Только есть... небольшая проблема." }, { 20.99, "Я нашёл этот кинжал, странствуя по Тернистой долине, и отдал его своей своевольной дочери, которая сбежала в Пиратскую бухту и стала пираткой." } } }, t = { d = 20.6, v = "human-female#47", n = { x = 250 }, c = { x = { { 0.00, "Мой кинжал?" }, { 0.78, "Ты издеваешься?" }, { 1.81, "Ты хочешь услышать, как я превратилась из лучшего бойца на ножах в Пиратской бухте в посмешище для всех пиратов?" }, { 9.21, "Я проиграла схватку с одним из пиратов Кровавого Паруса – они редкие мерзавцы! – и он забрал мой кинжал в качестве трофея." }, { 17.39, "Одним острым языком славу бойца не поддержишь..." } } } } },
    [604] = { d = 28.3, v = "tauren-male", n = { x = 272 }, c = { x = { { 0.00, "Кразз высоко ценит твою преданность Разбойникам Черноводья." }, { 5.16, "Я доверяю тебе задание, очень важное для нашего флота." }, { 10.01, "Проникни на так называемый южный командный пост, который пираты Кровавого Паруса основали на Диком взморье." }, { 19.32, "Разграбь весь лагерь и принеси мне их карты и записи приказов." }, { 24.72, "Так мы выясним, что замышляют эти ублюдки." } } }, t = { d = 12.8, v = "tauren-male", n = { x = 105 }, c = { x = { { 0.00, "Отлично." }, { 0.88, "Теперь, когда их планы нам известны, это лишь вопрос времени." }, { 6.97, "Подумать только, эти глупцы бросили якорь недалеко от мыса." } } } } },
    [605] = { d = 33.9, v = "goblin-male", n = { x = 406 }, c = { x = { { 0.00, "Поющие кристаллы добывают только в Тернистой долине, и некоторые покупатели готовы немало за них отсыпать." }, { 7.43, "Кому их толкнуть, мне ясно, но проклятая Торговая Компания не даёт собирать кристаллы честным предпринимателям вроде меня." }, { 15.93, "Я хочу тебя нанять." }, { 17.38, "Василиски Тернистой долины питаются этими кристаллами." }, { 21.22, "Благодаря им у них прочная шкура, и иногда из неё можно добыть качественные кристаллы." }, { 27.20, "Годится шкура любого василиска, но на северном побережье, южнее Зул'Кунды, они не такие свирепые." } } }, t = { d = 8.0, v = "goblin-male", n = { x = 61 }, c = { x = { { 0.00, "Ага!" }, { 0.52, "Отличные осколки." }, { 2.23, "То, что надо!" }, { 3.52, "Вот твоя доля, и... с тобой приятно иметь дело." } } } } },
    [606] = { d = 33.5, v = "human-male#50", n = { x = 403 }, c = { x = { { 0.00, "Вот кого я терпеть не могу, так это тех, кто не отдаёт карточные долги!" }, { 4.74, "Мне задолжали несколько партнёров по игре." }, { 7.53, "Не поможешь собрать с них мзду?" }, { 9.60, "Во-первых, есть Филипп \"Трусишка\", который вечно торчит у причала." }, { 14.10, "Он проиграл мне кругленькую сумму на прошлой неделе, и я хочу её получить!" }, { 19.08, "Только для этого надо его хорошенько припугнуть." }, { 22.42, "Ступай, поохоться на старых горилл из Мглистой долины." }, { 26.19, "Набери из них потрохов и отнеси Трусишке." }, { 28.98, "Только не говори, что они обезьяньи, пусть в штаны со страху наложит!" } } }, t = { d = 7.4, v = "human-male", n = { x = 64 }, c = { x = { { 0.00, "Ох!" }, { 0.32, "Откуда у вас это?" }, { 1.94, "Нет, не говорите." }, { 3.48, "Я не хочу знать!" }, { 4.93, "Кто вас прислал?" }, { 6.39, "Морской волк?" } } } } },
    [607] = { d = 15.6, v = "human-male", n = { x = 174 }, c = { x = { { 0.00, "Вот, возьмите этот кошель и отнесите его Морскому Волку." }, { 4.06, "И передайте, что я собирался ему заплатить!" }, { 7.11, "Клянусь!!!" }, { 7.87, "Я всего лишь немного перебрал и заблудился по пути, и... знаете, как бывает." }, { 13.20, "Он поймёт – не нужно применять силу!" } } }, t = { d = 16.2, g = 1, v = "human-male#50", n = { m = 172, f = 173 }, c = { m = { { 0.00, "Хе-хе, отличная работа!" }, { 1.80, "И как, сильно Трусишка перетрусил, когда ты показал ему потроха?" }, { 6.58, "Ха!" }, { 6.85, "Я читаю его как раскрытую книгу!" }, { 9.31, "Играя с ним в карты, нельзя не выиграть!" }, { 12.30, "Спасибо за помощь." }, { 13.70, "Пришёл твой черёд получить плату..." } }, f = { { 0.00, "Хе-хе, отличная работа!" }, { 1.81, "И как, сильно Трусишка перетрусил, когда ты показала ему потроха?" }, { 6.69, "Ха!" }, { 6.96, "Я читаю его как раскрытую книгу!" }, { 9.43, "Играя с ним в карты, нельзя не выиграть!" }, { 12.44, "Спасибо за помощь." }, { 13.85, "Пришёл твой черёд получить плату..." } } } } },
    [608] = { d = 39.3, g = 1, v = "tauren-male", n = { x = 383 }, c = { m = { { 0.00, "Ну и наглец этот Фираллон!" }, { 2.17, "Он бы и Озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот!" }, { 9.25, "Пираты Кровавого Паруса поплатятся за свою беспечность." }, { 13.73, "Теперь мы знаем все их планы и нападём первыми." }, { 17.48, "Хотя зачем посылать целый флот, если хватит отряда отважных искателей приключений?" }, { 24.20, "Путник, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров." }, { 34.53, "Весь флот отправится на дно следом за ними..." } }, f = { { 0.00, "Ну и наглец этот Фираллон!" }, { 2.14, "Он бы и Озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот!" }, { 9.28, "Пираты Кровавого Паруса поплатятся за свою беспечность." }, { 13.79, "Теперь мы знаем все их планы и нападём первыми." }, { 17.58, "Хотя зачем посылать целый флот, если хватит отряда отважных искателей приключений?" }, { 24.36, "Путница, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров." }, { 35.83, "Весь флот отправится на дно следом за ними..." } } }, t = { d = 7.4, v = "tauren-male", n = { x = 55 }, c = { x = { { 0.00, "Ах, что за великий день для Разбойников Черноводья!" }, { 5.53, "Трижды ура тебе!" } } } } },
    [609] = { d = 34.1, v = "human-male#50", n = { x = 382 }, c = { x = { { 0.00, "Список сокращается, но должники всё ещё остались." }, { 3.45, "Далее идут Моури \"Деревянная Нога\" Вилкинс, Джон-Джон Ворон и Чаки \"Недотёпа\"." }, { 9.07, "Эти паршивые собаки просрочили платежи на много месяцев, я-то думал, они поэтому из города сбежали!" }, { 16.28, "Потом, правда, мне сказали, что их прокляли и заколдовали, и они бродят по развалинам в джунглях." }, { 23.11, "Но меня их судьба не волнует – мне бы своё вернуть!" }, { 26.69, "Их видели на северо-востоке отсюда, в руинах Абораза и руинах Жубуваля." }, { 31.80, "Отыщи их и забери у них мои вещи." } } }, t = { d = 20.3, v = "human-male#50", n = { x = 211 }, c = { x = { { 0.00, "Отлично!" }, { 0.68, "За это я выручу кругленькую сумму, особенно за то, что спрятано внутри ноги Моури!" }, { 6.91, "Спасибо!" }, { 7.59, "Надеюсь, эти трое усвоили урок: никогда не ставь на кон то, что не можешь отдать." }, { 13.69, "Может быть, они поняли это слишком поздно..." }, { 17.15, "Но надо было думать, с кем садишься играть." } } } } },
    [610] = { d = 25.2, v = "human-female#47", n = { x = 307 }, c = { x = { { 0.00, "Так тебя прислал мой ОТЕЦ?" }, { 1.75, "Я думала, старик давно махнул на меня рукой." }, { 4.73, "Это он виноват, что я сбежала." }, { 6.71, "С чего он взял, что я только и мечтаю о скучной жизни среди заплесневелых книг и седых, горбатых и надутых магов!" }, { 14.01, "Если тебе нужен мой кинжал, можешь отобрать его у \"Красавчика\" Дункана, одного из пиратов Кровавого Паруса." }, { 21.08, "Приставь ему нож к спине, и он с радостью отдаст тебе мой клинок." } } }, t = { d = 11.7, v = "human-female#47", n = { x = 138 }, c = { x = { { 0.00, "Тебе удалось одолеть Дункана?" }, { 2.08, "Значит, ты не совсем салага, как кажется с первого взгляда." }, { 6.12, "Пожалуй, это означает и то, что мне не стоит в ближайшее время вызывать тебя на бой!" } } } } },
    [611] = { d = 19.8, g = 1, v = "human-female#47", n = { m = 256, f = 258 }, c = { m = { { 0.00, "Значит, ты ищешь какой-то алтарь?" }, { 2.16, "Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты спрашивал." }, { 11.65, "Посмотри там." }, { 12.51, "Ты вернул мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!" } }, f = { { 0.00, "Значит, ты ищешь какой-то алтарь?" }, { 2.16, "Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты спрашивала." }, { 11.69, "Посмотри там." }, { 12.54, "Ты вернула мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!" } } }, t = { d = 14.2, v = "goblin-male#180", n = { x = 151 }, c = { x = { { 0.00, "Поразительно!" }, { 1.10, "Камень Приливов!" }, { 2.48, "Он займёт достойное место в моей коллекции древних артефактов троллей." }, { 8.18, "Видишь, создаётся впечатление, что это и есть окаменевший прилив?" }, { 13.37, "Великолепно!" } } } } },
    [613] = { d = 30.6, v = "human-male#50", n = { x = 359 }, c = { x = { { 0.00, "Проклятье!" }, { 0.73, "Этот Моури поставил на свою ногу замок, и я не могу её открыть!" }, { 5.10, "Его сокровища внутри, и именно их он мне должен!" }, { 8.37, "Мне необходим ключ, чтобы вскрыть этот замок." }, { 11.41, "Моури нередко играл в кости с ограми Мош'Огг у них на холме на северо-востоке." }, { 16.75, "Он успел рассказать мне, что ему пришлось спасаться бегством после прошлой игры, потому что больно много выиграл." }, { 24.45, "Может быть, его ключ у огров." }, { 26.45, "Но если так, придётся убить целую толпу, чтобы его отыскать..." } } }, t = { d = 8.5, g = 1, v = "human-male#50", n = { m = 72, f = 75 }, c = { m = { { 0.00, "Ты нашёл его!" }, { 1.25, "Тысяча благодарностей." }, { 3.33, "Ты мне так помог!" }, { 4.91, "Вот, возьми – ты заработал это сполна!" } }, f = { { 0.00, "Ты нашла его!" }, { 1.30, "Тысяча благодарностей." }, { 3.34, "Ты мне так помогла!" }, { 5.05, "Вот, возьми – ты заработала это сполна!" } } } } },
    [614] = { d = 35.4, v = "human-male", n = { x = 396 }, c = { x = { { 0.00, "Когда-то у меня был корабль, на котором я ходил до самого Кабестана в Калимдоре, и репутация у меня была безупречная." }, { 8.49, "Пока…" }, { 8.95, "Пока не появились проклятые морские великаны!" }, { 12.28, "Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую бухту." }, { 19.07, "А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая." }, { 26.05, "Наглец!" }, { 26.64, "Говорят, Горлаш бродит по берегу к востоку отсюда." }, { 30.36, "Найди его и верни мой сундук!" }, { 32.58, "Благодарность моя не будет знать предела." } } } , t = { d = 12.4, v = "CatQuest Extended", c = { x = {} } }},
    [615] = { d = 37.5, v = "human-male", n = { x = 430 }, c = { x = { { 0.00, "После того как эти проклятые великаны уничтожили мой корабль, я купил ещё один." }, { 5.58, "Назвал его \"Месть Смоттса\", запасся продовольствием, нанял команду и отправился на поиски этих злодеев." }, { 12.78, "Найти-то я их нашёл, но... они снова мне надавали по шее." }, { 16.73, "\"Месть Смоттса\" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку." }, { 23.19, "У другого великана, Неголаша, моя сабля." }, { 26.07, "Сразись с Неголашем и принеси мне мою саблю!" }, { 29.20, "Можешь поговорить с Салагой, поваром с \"Мести Смоттса\", который выжил в последней битве." }, { 35.41, "Он поможет тебе найти великана." } } } },
    [616] = { d = 27.2, v = "goblin-male", n = { x = 317 }, c = { x = { { 0.00, "Барон Ревилгаз велел мне не упускать слухов о странных событиях и местах в округе Пиратской бухты и всей Тернистой долины." }, { 8.79, "Обычно я не придаю большого значения историям про призраков и прочую чушь, но моряки в таверне говорили об острове элементалей недалеко от побережья." }, { 19.39, "Мол, там духи Воды и сумасшедший призрак гоблина." }, { 22.95, "Если тебе встретится Ревилгаз, перескажешь ему эту историю?" } } }, t = { d = 18.6, v = "goblin-male#180", n = { x = 186 }, c = { x = { { 0.00, "Интересно." }, { 0.88, "Кажется, я недавно читал книгу, в которой говорилось о чём-то в этом духе…" }, { 6.97, "А, разумеется, легенды троллей." }, { 9.54, "Если Кразек говорит правду, то вскоре к моей коллекции древних артефактов и реликвий добавится Камень Приливов." } } } } },
    [617] = { d = 24.3, v = "human-male#50", n = { x = 278 }, c = { x = { { 0.00, "Ищешь работу?" }, { 1.02, "Если ты не боишься трудностей, могу тебе предложить одно дельце." }, { 5.67, "У меня есть дружбан, Грой, который зашибает бешеные деньги, продавая то, что наги называют стеблями акириса." }, { 13.31, "Это очень ценная морская водоросль." }, { 15.93, "Он за неё отлично платит." }, { 17.71, "Притащи мне десять стеблей этой травки, и мы сторгуемся." }, { 21.72, "Наги живут на берегу к северу отсюда." } } }, t = { d = 9.7, g = 1, v = "human-male#50", n = { m = 111, f = 110 }, c = { m = { { 0.00, "Молодец." }, { 0.62, "Не так уж трудно было добыть десять стеблей акириса, а?" }, { 4.43, "Я вполне сочувствую нагам, но каждый как-то должен зарабатывать на жизнь." } }, f = { { 0.00, "Умница." }, { 0.58, "Не так уж трудно было добыть десять стеблей акириса, а?" }, { 4.59, "Я вполне сочувствую нагам, но каждый как-то должен зарабатывать на жизнь." } } } } },
    [618] = { d = 34.9, v = "goblin-male", n = { x = 381 }, c = { x = { { 0.00, "Неголаш – великан-обжора." }, { 1.92, "Когда они уничтожили наш корабль, Неголаш бросился прямиком на кухню." }, { 7.10, "В отличие от его товарищей, команда его не очень интересовала." }, { 11.74, "Ему хотелось вина... и жареных крылышек канюка." }, { 15.32, "Это моё коронное блюдо, рецепт я привёз из самих Бесплодных земель!" }, { 20.30, "Если ты хочешь приманить великана, добудь вина и кучу крылышек канюка." }, { 25.61, "Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда." }, { 30.98, "Когда Неголаш почует запах еды, он непременно явится!" } } }, t = { d = 16.2, g = 1, v = "human-male", n = { m = 178, f = 180 }, c = { m = { { 0.00, "Ты забрал саблю у Неголаша!" }, { 2.05, "Я не верил, что мне повезёт!" }, { 4.04, "Встретив тебя, моя удача вернулась, без сомнения!" }, { 7.76, "Спасибо!" }, { 8.42, "И если я когда-нибудь заполучу новый корабль, и ты захочешь прокатиться, то ты будешь на нём почётным гостем." } }, f = { { 0.00, "Ты забрала саблю у Неголаша!" }, { 2.10, "Я не верил, что мне повезёт!" }, { 4.08, "Встретив тебя, моя удача вернулась, без сомнения!" }, { 7.76, "Спасибо!" }, { 8.42, "И если я когда-нибудь заполучу новый корабль, и ты захочешь прокатиться, то ты будешь на нём почётной гостьей." } } } } },
    [619] = { t = { d = 3.2, v = "narrator", n = { x = 30 }, c = { x = { { 0.00, "Вы нагружаете лодку едой и выпивкой..." } } } } },
    [620] = { d = 4.0, v = "narrator", n = { x = 36 }, c = { x = { { 0.00, "Вдоль каймы кушака вышита монограмма «Гэ Ша»." } } } },
    [621] = { d = 32.6, v = "goblin-male", n = { x = 388 }, c = { x = { { 0.00, "Занзил Отверженный и его приспешники живут в руинах Жубуваля и Абораза, на северо-востоке от Пиратской бухты." }, { 7.69, "Его изгнали из племени." }, { 9.39, "Почему?" }, { 9.96, "Ну…" }, { 10.21, "Занзил научился подчинять себе разум других, и его страшатся собственные командиры." }, { 16.14, "Он заставляет своих приспешников принимать смесь из тропических растений, которые подавляют их волю и укрепляют тела." }, { 24.27, "Эта смесь пригодилась бы и другим, желающим подчинить себе других." }, { 28.94, "Принеси мне образцы этой смеси, я найду им применение." } } }, t = { d = 6.2, v = "goblin-male", n = { x = 46 }, c = { x = { { 0.00, "А, отлично!" }, { 1.19, "Вот твоя плата." }, { 2.84, "И ещё немного сверх... за молчание." } } } } },
    [622] = { d = 19.1, v = "goblin-male", n = { x = 193 }, c = { x = { { 0.00, "Пока тебя не было, я починил твой горшок и даже приделал к нему свисток." }, { 5.79, "Больше того, смотри!" }, { 7.48, "На дне появился новый нож, который запросто рубит кости!" }, { 11.93, "Да-да, теперь этот горшок – настоящая радость повара!" }, { 16.24, "Не сомневаюсь, владелец будет доволен." } } }, t = { d = 17.2, v = "human-male", n = { x = 193 }, c = { x = { { 0.00, "Готово!" }, { 0.58, "Чудесно, я могу готовить обед!" }, { 2.85, "Большое спасибо." }, { 4.08, "Надеюсь, в Пиратской бухте с тобой ничего не случилось." }, { 8.09, "Там всякое бывает..." }, { 9.58, "Говорят, иногда гоблины утаскивают пьяных моряков на галеры, приковывают цепями и увозят неизвестно куда..." } } } } },
    [623] = { d = 28.6, g = 1, v = "human-male#50", n = { m = 340, f = 340 }, c = { m = { { 0.00, "Раз уж ты здесь, я тебе вот что скажу." }, { 2.52, "Пока тебя не было, я получил послание от Гроя." }, { 5.77, "Его очень порадовала последняя поставка, и клиент немедленно захотел получить ещё акириса." }, { 11.97, "Я собираюсь в Терамор не раньше, чем через неделю, но если ты не против двинуть в путь прямо сейчас, почему бы тебе не отвезти товар?" }, { 21.05, "Хочешь поприключаться?" }, { 22.58, "Ты знаешь, где находятся Пылевые топи?" }, { 25.22, "Только будь осторожен, в Тераморе может быть опасно." } }, f = { { 0.00, "Раз уж ты здесь, я тебе вот что скажу." }, { 2.47, "Пока тебя не было, я получил послание от Гроя." }, { 5.66, "Его очень порадовала последняя поставка, и клиент немедленно захотел получить ещё акириса." }, { 11.73, "Я собираюсь в Терамор не раньше, чем через неделю, но если ты не против двинуть в путь прямо сейчас, почему бы тебе не отвезти товар?" }, { 20.64, "Хочешь поприключаться?" }, { 22.14, "Ты знаешь, где находятся Пылевые топи?" }, { 24.73, "Только будь осторожна, в Тераморе может быть опасно." } } }, t = { d = 29.1, g = 1, v = "human-male", n = { x = 295 }, c = { m = { { 0.00, "Что?!" }, { 0.39, "Мне некогда с тобой трепаться, герой." }, { 3.16, "Если ты собираешься попусту тратить моё время, лучше сразу убирайся." }, { 8.22, "Что?" }, { 8.55, "Тебя прислал Блоудс, да?" }, { 10.32, "*Капер Грой внимательно рассматривает свёрток.*" }, { 13.76, "Неплохо, неплохо." }, { 15.24, "Ещё один свёрток – и клиент будет счастлив." }, { 18.78, "Думаю, следующий вопрос будет про деньги, а?" }, { 22.47, "Ну разумеется!" }, { 23.65, "Вот, бери монеты и совет в придачу: убирайся-ка подобру-поздорову." } }, f = { { 0.00, "Что?!" }, { 0.41, "Мне некогда с тобой трепаться, героиня." }, { 3.42, "Если ты собираешься попусту тратить моё время, лучше сразу убирайся." }, { 8.69, "Что?" }, { 9.03, "Тебя прислал Блоудс, да?" }, { 10.88, "*Капер Грой внимательно рассматривает свёрток.*" }, { 14.24, "Неплохо, неплохо." }, { 15.68, "Ещё один свёрток – и клиент будет счастлив." }, { 19.13, "Думаю, следующий вопрос будет про деньги, а?" }, { 22.72, "Ну разумеется!" }, { 23.87, "Вот, бери монеты и совет в придачу: убирайся-ка подобру-поздорову." } } } } },
    [624] = { d = 17.4, v = "narrator", n = { x = 164 }, c = { x = { { 0.00, "Есть мост, изукрашен резьбою, красивый на нём узор" }, { 4.28, "К востоку от Мёртвого Ветра и к югу от Красногорья" }, { 8.64, "Под ним тебя ждёт подсказка ль, улика ль – как назовёшь." }, { 13.32, "И будет на Болоте Печали лежать, пока не найдёшь." } } }, t = { d = 3.7, v = "narrator", n = { x = 38 }, c = { x = { { 0.00, "Намокший пергамент даёт вам новую подсказку..." } } } } },
    [625] = { d = 19.8, v = "narrator", n = { x = 174 }, c = { x = { { 0.00, "Калимдор далёкий ждёт тебя давно," }, { 3.01, "Где надеждам к сроку сбыться не дано." }, { 6.42, "Ты в Степях почуешь вкус пыли на губах," }, { 10.00, "Ну а в топях пылевых – лишь печаль и страх." }, { 13.82, "Но на юго-запад путь тебя манит," }, { 16.83, "Мрак пещеры тайну для тебя хранит." } } }, t = { d = 3.1, v = "narrator", n = { x = 29 }, c = { x = { { 0.00, "Вы находите заплесневелый свиток." } } } } },
    [626] = { d = 26.0, v = "narrator", n = { x = 220 }, c = { x = { { 0.00, "Спеши же в славный Лордерон!" }, { 2.74, "Давно тебя он ждёт." }, { 4.62, "Там с мором, гибелью и тьмой сражается народ." }, { 8.89, "Пусть не страшит тебя война и битвы шум и гам –" }, { 13.34, "Зато задание своё исполнить сможешь там." }, { 17.19, "Вот берег Внутренних земель, где шумный водопад," }, { 21.80, "Там, там под водами его тебя ждёт дивный клад!" } } }, t = { d = 3.4, v = "narrator", n = { x = 32 }, c = { x = { { 0.00, "Вы открываете сундук и обнаруживаете..." } } } } },
    [627] = { d = 35.4, v = "goblin-male", n = { x = 386 }, c = { x = { { 0.00, "В Теснине Сухоусов – далеко на севере, в нагорье Арати – есть пещера." }, { 5.02, "Там добывают редкие полезные ископаемые – кровавые камни." }, { 9.19, "Да, они там не лучшего качества, но даже самые плохие кровавые камни высоко ценятся... теми, кто знает что с ними делать." }, { 18.05, "Я – знаю." }, { 18.76, "Я починю твой разбитый горшок, но пока я работаю над ним, принеси мне образцы кровавого камня." }, { 25.54, "Если ты принесёшь их достаточно, я награжу тебя." }, { 28.99, "Ах, да, если ты не умеешь добывать полезные ископаемые... попроси кого-нибудь помочь тебе!" } } }, t = { d = 6.2, g = 1, v = "goblin-male", n = { m = 48, f = 49 }, c = { m = { { 0.00, "А, великолепно!" }, { 1.48, "Ты оказал мне большую услугу." }, { 4.35, "Вот твоя плата..." } }, f = { { 0.00, "А, великолепно!" }, { 1.52, "Ты оказала мне большую услугу." }, { 4.55, "Вот твоя плата..." } } } } },
    [628] = { d = 29.0, v = "goblin-male", n = { x = 356 }, c = { x = { { 0.00, "Подбой готов, осталось сделать верхний слой." }, { 3.07, "На него идут только наилучшие шкуры взрослых кроколисков." }, { 7.06, "Они крепче и представляют собой лучшую основу для узоров, которыми славится линия превосходных сапог." }, { 14.06, "Хотя найти эту ценную шкуру нелегко, мне подходит лишь шкура старого солоноводного кроколиска." }, { 20.57, "Эти твари выходят лишь на защиту молоди, поэтому может понадобиться убить несколько молодых зверей, чтобы выманить нужного." } } }, t = { d = 20.6, v = "goblin-male", n = { x = 223 }, c = { x = { { 0.00, "Здорово!" }, { 0.67, "Благодаря твоей помощи я выполню этот заказ и отправлю его директору Ридлвоксу на следующем корабле в Нижнюю шахту." }, { 9.38, "Быстрее, чем обещал!" }, { 10.92, "Я сделал лишнюю пару, возьми её за работу." }, { 14.14, "Всё за счёт Дриззлика." }, { 15.75, "И помни, если нужны тебе сапоги, к Дриззлику ты поскорей прибеги!" } } } } },
    [629] = { d = 38.0, v = "troll-male#77", n = { x = 437 }, c = { x = { { 0.00, "Давным-давно сильное землетрясение погрузило древний город троллей в воды Гибельного берега к северо-западу отсюда." }, { 8.36, "Мы зовём это место Коварным рифом, потому что в развалинах поселились мурлоки, которые нападают на всех, кто осмелится приблизиться." }, { 17.83, "Среди руин есть древняя табличка, повествующая о древнем герое троллей, Гри'леке." }, { 23.78, "Это сказание священно в племени Чёрного Копья, и хотя сама табличка слишком велика и её не унесёшь, я хочу получить хотя бы осколок, чтобы поместить его в святилище в нашем новом городе, Оргриммаре." } } }, t = { d = 17.3, v = "troll-male#77", n = { x = 166 }, c = { x = { { 0.00, "Хорошо." }, { 0.69, "Когда я вернусь в Оргриммар, этот осколок будет помещён в священное место." }, { 7.04, "Он будет напоминать нам о силе и чести Гри'лека." }, { 11.17, "Спасибо." }, { 11.93, "Твои деяния говорят о крепнущей дружбе с племенем Чёрного Копья." } } } } },
    [630] = { d = 32.1, v = "tauren-female", n = { x = 334 }, c = { x = { { 0.00, "Ты и те, кого ты сможешь позвать мне на помощь – моя последняя надежда." }, { 5.45, "Меня держит в плену великий Король Мукла." }, { 8.76, "Он повелевает зверями на этом острове, и они держат меня здесь помимо моей воли на этой цепи." }, { 16.08, "Если ты сможешь убить моего мучителя и отыскать ключ к кандалам, я буду навеки у тебя в долгу." }, { 23.40, "Я часто слышу шаги Короля Муклы на юго-восточной стороне острова." }, { 28.57, "Соблюдай осторожность, справиться с ним нелегко." } } }, t = { d = 16.5, g = 1, v = "tauren-female", n = { m = 157, f = 159 }, c = { m = { { 0.00, "Ты спас меня от великого бесчестья." }, { 3.02, "Будь это в моей власти, я приняла бы тебя в своё племя." }, { 7.82, "Пока же я могу лишь вручить тебе этот залог моей благодарности за проявленное мужество и благородство." } }, f = { { 0.00, "Ты спасла меня от великого бесчестья." }, { 3.11, "Будь это в моей власти, я приняла бы тебя в своё племя." }, { 7.71, "Пока же я могу лишь вручить тебе этот залог моей благодарности за проявленное мужество и благородство." } } } } },
    [631] = { d = 40.0, v = "dwarf-male", n = { x = 467 }, c = { x = { { 0.00, "Я помню, как горы содрогнулись от ужаснейшего взрыва." }, { 3.73, "Неслабо рвануло, скажу я тебе!" }, { 5.94, "На мосту Тандола погибли лучшие из наших солдат." }, { 9.42, "Длинная Коса говорит, что дворфы Чёрного Железа ещё заплатят нам за всё до конца этой войны." }, { 15.87, "Но сейчас у нас отчаянное положение, подкрепления всё нет и нет." }, { 20.23, "Длинная Коса отправил Ржавого Засова на разведку к восточному мосту – посмотреть, можно ли защитить мост теми силами, которые сейчас у нас есть." }, { 30.34, "Прошло уже несколько дней." }, { 32.24, "Мы не можем отправить солдат на поиски – Дун Модр осаждён..." }, { 36.35, "Быть может, ты согласишься поискать нашего разведчика?" } } }, t = { d = 7.9, v = "narrator", n = { x = 72 }, c = { x = { { 0.00, "Вы натыкаетесь на труп дворфа." }, { 2.72, "На шлеме отчётливо видна надпись: \"Эбенезер Ржавый Засов\"." } } } } },
    [632] = { d = 14.6, v = "narrator", n = { x = 156 }, c = { x = { { 0.00, "Кажется, бедняга Ржавый Засов попал в засаду дворфов Чёрного Железа." }, { 5.48, "Возле его остывшего тела лежит клочок пергамента." }, { 9.53, "Расскажите Рагу Каменщику о случившемся и передайте ему пергамент." } } }, t = { d = 4.4, v = "dwarf-male", n = { x = 29 }, c = { x = { { 0.00, "Какой ужас..." }, { 1.67, "Бедный, бедный Эбенезер." } } } } },
    [633] = { d = 31.8, g = 1, v = "dwarf-male", n = { m = 347, f = 348 }, c = { m = { { 0.00, "Во имя Света, только не это!" }, { 2.21, "Бедняга Ржавый Засов." }, { 3.89, "Ты меня опечалил." }, { 5.23, "Но его жертва будет не напрасной!" }, { 7.78, "В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал спрятать запас взрывчатки сразу за мостом Тандола, в нагорье Арати." }, { 18.98, "Если эта взрывчатка попадёт на мост, мы лишимся главного пути снабжения с севера!" }, { 25.01, "Тайник нужно уничтожить!" }, { 26.89, "Возвращайся ко мне, когда справишься." }, { 29.64, "Ты – наша единственная надежда." } }, f = { { 0.00, "Во имя Света, только не это!" }, { 2.20, "Бедняга Ржавый Засов." }, { 3.87, "Ты меня опечалила." }, { 5.27, "Но его жертва будет не напрасной!" }, { 7.81, "В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал спрятать запас взрывчатки сразу за мостом Тандола, в нагорье Арати." }, { 18.96, "Если эта взрывчатка попадёт на мост, мы лишимся главного пути снабжения с севера!" }, { 24.96, "Тайник нужно уничтожить!" }, { 26.83, "Возвращайся ко мне, когда справишься." }, { 29.57, "Ты – наша единственная надежда." } } }, t = { d = 10.1, g = 1, v = "dwarf-male", n = { m = 108, f = 110 }, c = { m = { { 0.00, "Мост спасён!" }, { 0.88, "Ты помог не только мне и королю Магни, но и всему народу Каз Модана!" }, { 6.05, "Теперь нужно продержаться до прибытия подкрепления..." } }, f = { { 0.00, "Мост спасён!" }, { 0.89, "Ты помогла не только мне и королю Магни, но и всему народу Каз Модана!" }, { 6.21, "Теперь нужно продержаться до прибытия подкрепления..." } } } } },
    [634] = { d = 25.6, g = 1, v = "dwarf-male", n = { x = 293 }, c = { m = { { 0.00, "Я попрошу тебя о ещё одном одолжении, герой." }, { 3.13, "Мы ожидаем подкрепление из Стальгорна." }, { 5.76, "Рогго принёс сведения о лагере воинов Альянса к северу отсюда." }, { 10.15, "Они расположились на нагорье Арати, возле Опорного пункта." }, { 14.28, "Отправься туда и отыщи капитана Ниалс." }, { 17.04, "Спроси у очаровательного капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола." } }, f = { { 0.00, "Я попрошу тебя о ещё одном одолжении, героиня." }, { 3.31, "Мы ожидаем подкрепление из Стальгорна." }, { 5.99, "Рогго принёс сведения о лагере воинов Альянса к северу отсюда." }, { 10.45, "Они расположились на нагорье Арати, возле Опорного пункта." }, { 14.66, "Отправься туда и отыщи капитана Ниалс." }, { 17.46, "Спроси у очаровательного капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола." } } }, t = { d = 30.0, v = "human-female#47", n = { x = 344 }, c = { x = { { 0.00, "Передай мои соболезнования Длинной Косе и его солдатам." }, { 4.07, "Я искренне опечалена вестью о трагедии на мосту Тандола и падении Дун Модра..." }, { 9.68, "Но знайте, что и Стромгард пал!" }, { 11.88, "Именно поэтому мы сейчас стоим у Опорного пункта." }, { 15.49, "Впереди – битва за наш великий город." }, { 18.20, "Долг и честь не позволяют мне покинуть нагорье до тех пор, пока над Стромгардом не взовьётся гордое знамя нашего короля!" }, { 26.59, "Придётся Длинной Косе обходиться своими силами..." } } } } },
    [635] = { d = 20.0, v = "narrator", n = { x = 193 }, c = { x = { { 0.00, "Осколок пульсирует у вас в руках…" }, { 2.77, "Вам кажется, что он молит о чём-то, пытается передать послание того, кто нуждается в вашей помощи." }, { 10.86, "Вам является видение – в северных горах Арати из земли торчит сияющий кристалл." }, { 17.61, "Вас так и тянет к этому месту." } } }, t = { d = 4.6, v = "narrator", n = { x = 46 }, c = { x = { { 0.00, "Кристалл пульсирует, будто в него заключена живая сила." } } } } },
    [636] = { d = 26.0, g = 1, v = "narrator", n = { m = 261, f = 264 }, c = { m = { { 0.00, "В этой книге рассказывается об элементальной принцессе Мизраэли и о её заточении глубоко под Нагорьем Арати." }, { 8.60, "Ещё в ней говорится о тайном скоплении кристаллов в нагорье." }, { 13.37, "Эти кристаллы, Осколки Мизраэли, – окно в темницу принцессы." }, { 18.29, "Если бы отважная душа нашла Осколки Мизраэли, то, быть может, он смог бы поговорить с ней..." } }, f = { { 0.00, "В этой книге рассказывается об элементальной принцессе Мизраэли и о её заточении глубоко под Нагорьем Арати." }, { 8.67, "Ещё в ней говорится о тайном скоплении кристаллов в нагорье." }, { 13.48, "Эти кристаллы, Осколки Мизраэли, – окно в темницу принцессы." }, { 18.43, "Если бы отважная душа нашла Осколки Мизраэли, то, быть может, она смогла бы поговорить с ней..." } } } },
    [637] = { d = 20.0, v = "narrator", n = { x = 210 }, c = { x = { { 0.00, "Промокший и потрёпанный конверт разваливается в руках, и в ладонях остаётся письмо на нескольких страницах." }, { 8.44, "Каждая буковка выведена с удивительной аккуратностью." }, { 12.73, "Письмо адресовано некой миссис Саре Баллу из Стальгорна." }, { 17.39, "Оно начинается: \"Дорогая Сара...\"" } } }, t = { d = 8.2, g = 1, v = "dwarf-female#33", n = { m = 80, f = 81 }, c = { m = { { 0.00, "Неужели ты видел моего Салли подо льдом?" }, { 3.12, "Прошу, скажи, что это не так!" }, { 5.36, "Дай-ка я прочитаю, что он написал..." } }, f = { { 0.00, "Неужели ты видела моего Салли подо льдом?" }, { 3.25, "Прошу, скажи, что это не так!" }, { 5.54, "Дай-ка я прочитаю, что он написал..." } } } } },
    [638] = { d = 24.8, v = "troll-male", n = { x = 286 }, c = { x = { { 0.00, "Торас Троллебой мёртв, а Стромгард разрушен." }, { 3.17, "Вол'джин велел мне приложить все усилия, чтобы вырвать легендарный меч Трол'калар из рук людей." }, { 9.98, "Тогда мы сможем воспользоваться им в грядущих битвах с троллями Зул'Гуруба." }, { 15.36, "Зенгу, один из наших опытных охотников, отправился в Павший Молот в северо-восточной части нагорья Арати, чтобы проследить за этим." } } }, t = { d = 9.7, g = 1, v = "troll-male", n = { x = 88 }, c = { m = { { 0.00, "Как дела, герой?" }, { 1.37, "Вол'джин дал нам непростое задание, и если ты хочешь предложить свою помощь, мы с радостью её примем." } }, f = { { 0.00, "Как дела, героиня?" }, { 1.81, "Вол'джин дал нам непростое задание, и если ты хочешь предложить свою помощь, мы с радостью её примем." } } } } },
    [639] = { d = 39.9, v = "troll-male", n = { x = 424 }, c = { x = { { 0.00, "В древние времена тролли воевали с Араторской империей и нашим самым могучим противником, лордом Игнеусом Стромским по прозвищу Троллебой." }, { 10.73, "Он бросался в бой с мечом Трол'каларом в руке – \"убийцей троллей\", на их древнем наречии." }, { 18.20, "Но теперь сыновья Троллебоя ослабели, а цитадель их разрушена." }, { 23.00, "Меч защищён несколькими печатями, которые были распределены между выжившими защитниками Стромгарда, и мы должны их отыскать." }, { 32.48, "Первую из печатей захватил Синдикат, должно быть, она находится у одного из их людей в Стромгарде." } } }, t = { d = 10.6, v = "troll-male", n = { x = 108 }, c = { x = { { 0.00, "Отлично, дружище." }, { 1.48, "Это хорошее начало для сбора всех печатей, которые нам понадобятся, чтобы извлечь Трол'калар из могилы Троллебоя." } } } } },
    [640] = { d = 31.6, v = "troll-male", n = { x = 372 }, c = { x = { { 0.00, "Могила Тораса Троллебоя защищена тремя печатями, первую из которых вы уже раздобыли у Синдиката." }, { 6.98, "Остальные две достать будет сложнее, поскольку ими владеет гораздо более сильное ополчение Стромгарда." }, { 14.42, "Печать Торадина была разделена на пять частей сыном Тораса Галеном, а потом он распределил эти фрагменты между стромгардскими защитниками." }, { 24.37, "Соберите фрагменты и принесите их Тор'гану, троллю-шаману, – он сможет восстановить целостность печати." } } }, t = { d = 13.8, v = "troll-male#77", n = { x = 142 }, c = { x = { { 0.00, "А, так вам нужно воссоздать печать!" }, { 2.77, "Это будет не слишком сложно... все фрагменты на месте, а магическую структуру будет легко преобразовать." }, { 11.00, "Пожалуй, вам бы лучше закрыть глаза." } } } } },
    [641] = { d = 14.6, v = "troll-male#77", n = { x = 152 }, c = { x = { { 0.00, "Восстановление прошло без сучка и задоринки." }, { 3.57, "Теперь печать можно использовать, чтобы отпереть могилу Троллебоя." }, { 9.03, "Верните печать Зенгу." }, { 10.85, "Несомненно, у него найдутся ещё для вас задания." } } }, t = { d = 18.2, v = "troll-male", n = { x = 187 }, c = { x = { { 0.00, "Мы на полпути к тому, чтобы извлечь Трол'калар из могилы Троллебоя." }, { 5.35, "Мы не вполне уверены в том, где находится третья печать, поскольку владеющие ею, похоже, много передвигаются по нагорью Арати." }, { 15.33, "Но я верю, что вам удастся её отыскать." } } } } },
    [642] = { d = 39.4, v = "creature/myzrael", n = { x = 366 }, c = { x = { { 0.00, "Меня зовут Мизраэль." }, { 1.88, "Я принцесса духов земли, и мои пленители – гиганты – поймали меня в ловушку глубоко под нагорьем Арати." }, { 10.96, "С миром на поверхности я могу говорить только при помощи этих кристаллов." }, { 17.37, "Пожалуйста, помоги мне." }, { 19.41, "У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в Теснине Сухоусов, к востоку отсюда." }, { 30.75, "Чтобы объединить их силу, нужно отобрать у кобольдов крупицы Мощи Мизраэли." }, { 37.41, "Прошу тебя, помоги мне!" } } }, t = { d = 11.8, v = "creature/myzrael", n = { x = 95 }, c = { x = { { 0.00, "Ах, тебе удалось активировать те кристаллы." }, { 4.21, "Я уже чувствую, что начинаю приходить в себя!" }, { 8.68, "Но, увы, до свободы ещё далеко..." } } } } },
    [643] = { d = 30.2, v = "troll-male", n = { x = 329 }, c = { x = { { 0.00, "Хотя принц едва ли может похвастаться властью над Стромгардом, не говоря уж обо всём нагорье Арати, тем не менее он разъезжает с остатками своей кавалерии по всей области." }, { 12.57, "Я не могу сказать, зачем он это делает, но кто поймёт, как мыслят эти люди?" }, { 18.21, "Какова бы ни была причина, более важно то, что он отдал одну из своих печатей лейтенанту Храброзову, командиру кавалерии." }, { 27.28, "Найдите его и принесите мне эту печать." } } }, t = { d = 14.8, v = "troll-male", n = { x = 170 }, c = { x = { { 0.00, "Потеря командира кавалерийского отряда станет серьёзным ударом для стромгардских защитников." }, { 6.62, "К тому же – что ещё лучше – это значит, что нам осталось найти лишь одну печать, чтобы заполучить себе Трол'калар." } } } } },
    [644] = { d = 22.2, v = "troll-male", n = { x = 235 }, c = { x = { { 0.00, "Последняя из печатей, необходимых, чтобы отпереть могилу Тораса Троллебоя, хранится у его сына." }, { 7.46, "Он обитает в Стромгарде, в часовне, в том районе, что контролируется ополчением." }, { 13.53, "У принца Галена хорошая охрана, да и сам он боец не промах, так что это задание может оказаться наиболее сложным." } } }, t = { d = 18.2, g = 1, v = "troll-male", n = { x = 171 }, c = { m = { { 0.00, "Удачный денёк, герой." }, { 1.79, "Кровь рода Троллебоев больше не будет беспокоить мой народ, и печати, необходимые для извлечения Трол'калара, теперь у нас в руках." }, { 12.54, "Скоро, очень скоро мы ударим по ненавистным троллям Зул'Гуруба." } }, f = { { 0.00, "Удачный денёк, героиня." }, { 1.98, "Кровь рода Троллебоев больше не будет беспокоить мой народ, и печати, необходимые для извлечения Трол'калара, теперь у нас в руках." }, { 12.92, "Скоро, очень скоро мы ударим по ненавистным троллям Зул'Гуруба." } } } } },
    [645] = { d = 21.1, v = "troll-male", n = { x = 228 }, c = { x = { { 0.00, "Что это?" }, { 0.70, "Когда четыре печати оказались вместе, они соединились, образовав единую печать." }, { 7.02, "Нет сомнений, что она сможет разбить охранные заклинания, наложенные на могилу Троллебоя." }, { 13.97, "Останки Троллебоя захоронены в святилище позади часовни в Стромгарде." }, { 19.37, "Принесите же Трол'калар." } } }, t = { d = 14.9, v = "narrator", n = { x = 159 }, c = { x = { { 0.00, "При совмещении линий на верхней стороне могилы Троллебоя с сияющими линиями печати Игнеуса вспышка света поглощает печать, и легендарный меч Трол'калар освобождается из каменных объятий." } } } } },
    [646] = { d = 7.3, v = "narrator", n = { x = 65 }, c = { x = { { 0.00, "Медленно угасает свет." }, { 2.16, "Меч Трол'калар, упрятанный в каменные ножны, освобождён." } } }, t = { d = 24.5, v = "troll-male", n = { x = 246 }, c = { x = { { 0.00, "Поколениями силы Штрома и Аратора истребляли троллей." }, { 4.40, "Теперь их величайшее оружие – в наших руках." }, { 8.06, "Больше мы не будем топтаться на месте во влажных лесах Зул'Гуруба." }, { 13.49, "Вы оказали нам серьёзную помощь, и тролли Чёрного Копья в долгу перед вами." }, { 19.57, "Я позабочусь о том, чтобы меч был доставлен Нимбойе в Гром'гол." } } } } },
    [647] = { d = 29.5, v = "dwarf-male", n = { x = 326 }, c = { x = { { 0.00, "Ох, и хлебнул я вчера самогона!" }, { 2.32, "Знай Длиннокос, что я отрубился на посту, он оторвал бы мне голову." }, { 7.17, "Башка раскалывается, жуть." }, { 9.09, "И в ушах гремит, будто осадные орудия вокруг грохочут." }, { 13.21, "Ой-ой, а времени сколько!" }, { 15.13, "Я обещал мастеру-пивовару Бочкопузу из Южнобережья вернуть должок своим самогоном." }, { 21.24, "А осталось до истечения срока действия долга всего пятнадцать минут!" }, { 26.35, "Отнеси ему самогон, будь другом!" }, { 28.80, "И поскорее!" } } }, t = { d = 12.6, v = "dwarf-male", n = { x = 127 }, c = { x = { { 0.00, "Ах, ничто не греет так, как глоток самогона Туманника Маккрила!" }, { 5.06, "А я-то думал, что этот паразит опять просрочит платёж." }, { 9.47, "Спасибо, дружище!" }, { 10.91, "Огромное тебе спасибо!" } } } } },
    [648] = { d = 36.7, v = "gnome-male", n = { x = 441 }, c = { x = { { 0.00, "*Из динамика снова слышится искажённый помехами голос гнома:*" }, { 4.56, "\"Мне необходимо перегнать Ка-Пэ-Ха семнадцать Тэ-Эн в просторное и безопасное место, чтобы провести длительную процедуру взлёта." }, { 13.14, "Маскировка у него встроенная, но мне нужно время, чтобы снова её наладить." }, { 18.19, "Проводите робота оттуда, где он сейчас, ну, скажем, к Пещерам Времени!" }, { 22.93, "Это самое подходящее место, и там достаточно просторно, чтобы подготовить аппарат к новому полёту." }, { 29.56, "Доставьте его в порт в целости, а потом приходите ко мне в Пиратскую бухту!" }, { 34.61, "Оглторп Обнотикус, конец связи!\"" } } }, t = { d = 27.7, v = "gnome-male", n = { x = 319 }, c = { x = { { 0.00, "А, так это вы великий спаситель Ка-Пэ-Ха семнадцать Тэ-Эн!" }, { 4.20, "У меня просто слов нет, настолько я вам благодарен!" }, { 7.81, "Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок!" }, { 20.01, "Прошу вас, выбирайте любую из этих готовых моделей." }, { 23.76, "Ещё раз спасибо вам!" }, { 25.18, "Мы с моими роботами – ваши должники!" } } } } },
    [649] = { d = 33.4, v = "orc-male", n = { x = 339 }, c = { x = { { 0.00, "Хочу я поручить тебе одно дельце." }, { 2.76, "Если ты любишь добрую медовуху, как и я, оно тебе понравится." }, { 7.64, "Медовуха!" }, { 8.41, "Это напиток, балда!" }, { 10.04, "На заброшенной заставе Орды хранится запас \"Медовой зыби\" Внутренних земель." }, { 16.12, "Такого славного пойла нынче больше не делают!" }, { 19.80, "Один из этих балбесов, дружков Мальтона, знает туда дорогу." }, { 24.60, "Сходи к нему, принеси бочонок медовухи и ещё пару бутылок мне лично." }, { 30.05, "Поговори с Мальтоном, он тебе всё расскажет." } } }, t = { d = 32.7, v = "orc-male", n = { x = 287 }, c = { x = { { 0.00, "А, это насчёт медовухи, которая нужна папаше?" }, { 4.04, "Он собирается торговать ею в таверне." }, { 7.37, "За настоящую \"Медовую зыбь\" можно выручить много денег..." }, { 12.44, "Я знаю того, кто может её добыть." }, { 15.45, "Он живёт во Внутренних землях." }, { 18.06, "Но вот какая штука: он того... эльф он." }, { 21.47, "Высший." }, { 22.18, "Но ты не бойся, он хороший высший эльф, он не из Альянса." }, { 27.10, "То есть он хороший, как выпьет." }, { 29.79, "А это дело он любит." }, { 31.69, "Очень любит." } } } } },
    [650] = { d = 33.4, v = "orc-male", n = { x = 350 }, c = { x = { { 0.00, "Отправляйся к эльфу по имени Гилверадин Ловчий Солнца." }, { 4.27, "Он так разбирается в винах, что умеет по запаху определить не только сорт вина, но и какого оно урожая!" }, { 12.24, "Он может прислать медовуху." }, { 14.41, "Шесть бутылок на продажу, две отцу... а может, и больше – он не откажется!" }, { 20.08, "В общем, забери медовуху и возвращайся сюда." }, { 23.58, "Гилверадин живёт неподалёку от пристанища Высших эльфов во Внутренних землях." }, { 29.45, "С эльфами этими лучше не связываться, уж поверь мне!" } } }, t = { d = 24.0, v = "bloodelf-male", n = { x = 278 }, c = { x = { { 0.00, "А, ты знаешь Мальтона?" }, { 1.61, "Он мой старинный собутыльник!" }, { 3.66, "Понимаешь, я нашёл средство, преодолевающее все искусственные границы и условности." }, { 9.44, "Это – выпивка!" }, { 10.53, "Если бы разумные существа выпивали, вместо того чтобы воевать, мир сделался бы куда лучше и чище." }, { 17.59, "Впрочем, боюсь, ты здесь не затем, чтобы слушать лекции о благословенных свойствах алкоголя." } } } } },
    [651] = { d = 32.6, v = "creature/myzrael", n = { x = 304 }, c = { x = { { 0.00, "Четыре связывающих камня разбросаны по нагорью Арати." }, { 4.69, "Эти камни пригвоздили меня к земле." }, { 7.89, "Чтобы оковы исчезли, нужно снять замок с самого мощного из них – с Внутреннего связывающего камня." }, { 16.40, "А чтобы это сделать, придётся собрать ключи с остальных трёх камней." }, { 22.33, "Эти камни охраняют стражи, но если у тебя хватит ума – или удачи, – тебе удастся найти возможность их нейтрализовать." } } }, t = { d = 17.6, g = 1, v = "creature/myzrael", n = { m = 126, f = 133 }, c = { m = { { 0.00, "*Голос Мизраэли доносится из камня.*" }, { 3.28, "Ты смог это сделать!" }, { 5.35, "Ты открыл замки!" }, { 7.06, "Я чувствую, как спадают мои оковы, и свобода всё ближе." }, { 12.65, "Ты мой благородный спаситель, герой путник!" } }, f = { { 0.00, "*Голос Мизраэли доносится из камня.*" }, { 3.20, "Ты смогла это сделать!" }, { 5.51, "Ты открыла замки!" }, { 7.29, "Я чувствую, как спадают мои оковы, и свобода всё ближе." }, { 12.79, "Ты моя благородная спасительница, героиня путница!" } } } } },
    [652] = { d = 44.2, g = 1, v = "creature/myzrael", n = { m = 395, f = 397 }, c = { m = { { 0.00, "Открыв замки связывающих камней, ты освободил меня от большей части моих оков, но кое-что ещё удерживает меня." }, { 10.14, "Это ключ-камень, который ты видишь среди других камней круга." }, { 15.86, "А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук." }, { 22.98, "Ты должен заполучить у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и использовать его для открытия ключ-камня." }, { 35.16, "Ты так много сделал, чтобы мне помочь..." }, { 38.84, "Ещё немножко... и моя благодарность потрясёт все земные устои!" } }, f = { { 0.00, "Открыв замки связывающих камней, ты освободила меня от большей части моих оков, но кое-что ещё удерживает меня." }, { 10.04, "Это ключ-камень, который ты видишь среди других камней круга." }, { 15.66, "А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук." }, { 22.64, "Ты должна заполучить у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и использовать его для открытия ключ-камня." }, { 34.61, "Ты так много сделала, чтобы мне помочь..." }, { 38.30, "Ещё немножко... и моя благодарность потрясёт все земные устои!" } } }, t = { d = 6.2, v = "narrator", n = { x = 54 }, c = { x = { { 0.00, "Вы вставляете жезл в ключ-камень." }, { 3.04, "Земля под вами начинает дрожать..." } } } } },
    [653] = { d = 47.6, g = 1, v = "creature/myzrael", n = { m = 459, f = 460 }, c = { m = { { 0.00, "*Говорит Мизраэль.*" }, { 1.84, "Свободна!" }, { 2.67, "Я СВОБОДНА!" }, { 3.64, "Я могу теперь набирать силу, скрывшись от моих пленителей." }, { 8.60, "Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы." }, { 18.07, "Но в должный час я пойду против гигантов, и они ещё пожалеют о том, что отняли у меня свободу!" }, { 25.89, "Вы благородный союзник." }, { 27.84, "Через некоторое время мне вновь понадобится ваша помощь." }, { 32.58, "Когда я буду готова, нужно, чтобы вы призвали меня на поверхность." }, { 38.21, "Поговорите с Герриком Костохватом." }, { 41.07, "Он обитает в Стальгорне, в Заброшенном гроте." }, { 44.82, "Он знает, как меня можно призвать." } }, f = { { 0.00, "*Говорит Мизраэль.*" }, { 1.84, "Свободна!" }, { 2.66, "Я СВОБОДНА!" }, { 3.64, "Я могу теперь набирать силу, скрывшись от моих пленителей." }, { 8.58, "Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы." }, { 18.02, "Но в должный час я пойду против гигантов, и они ещё пожалеют о том, что отняли у меня свободу!" }, { 25.81, "Вы благородная союзница." }, { 27.83, "Через некоторое время мне вновь понадобится ваша помощь." }, { 32.55, "Когда я буду готова, нужно, чтобы вы призвали меня на поверхность." }, { 38.16, "Поговорите с Герриком Костохватом." }, { 41.01, "Он обитает в Стальгорне, в Заброшенном гроте." }, { 44.75, "Он знает, как меня можно призвать." } } }, t = { d = 9.4, g = 1, v = "dwarf-male", n = { x = 86 }, c = { m = { { 0.00, "Госпожа сказала мне о вашем приходе, герой." }, { 3.55, "Приветствую вас в моём обиталище – ведь вы, как и я, служите высшей цели." } }, f = { { 0.00, "Госпожа сказала мне о вашем приходе, героиня." }, { 3.73, "Приветствую вас в моём обиталище – ведь вы, как и я, служите высшей цели." } } } } },
    [654] = { d = 19.9, v = "narrator", n = { x = 233 }, c = { x = { { 0.00, "Вы подключаете источник энергии, и набор для полевых испытаний начинает светиться и вибрировать." }, { 6.93, "Похоже, он работает как надо." }, { 9.08, "По словам главного инженера Чепухастера, теперь у вас есть время собрать нужные данные в пустыне Танарис." }, { 16.73, "Выполнив задание, возвращайтесь к Чепухастеру." } } }, t = { d = 10.0, v = "goblin-male", n = { x = 114 }, c = { x = { { 0.00, "Ну ладно, на удаление источника энергии мне понадобится пара секунд." }, { 4.97, "После этого можешь делать всё, что захочешь, не боясь потерять данные." } } } } },
    [655] = { d = 38.1, v = "orc-male#60", n = { x = 350 }, c = { x = { { 0.00, "Воспоминания по-прежнему ярки, как будто это было вчера..." }, { 5.12, "Так много лет без надежды, прикованный к этому ужасному месту деревом и сталью." }, { 11.94, "И вот наконец появился вождь." }, { 14.43, "Молот Рока в своих полуночных доспехах, высоко поднят его боевой молот." }, { 20.79, "Это было... слишком ужасно... что удар труса мог сразить нашего величайшего героя." }, { 28.00, "Враг наскочил сзади и пронзил его копьём..." }, { 31.72, "Я упал на колени." }, { 33.27, "Какая могла быть надежда?" }, { 35.52, "Какая ещё может быть надежда..." } } }, t = { d = 31.0, v = "troll-male#77", n = { x = 322 }, c = { x = { { 0.00, "А, вы говорите о Гор'муле." }, { 2.04, "Да, судя по вашим словам, похоже, он так и не оправился от смерти Молота Рока." }, { 8.17, "Гор'муль был пленником здесь, когда Тралл и Оргрим вели битву за освобождение лагеря, но когда затряслась земля и наши братья сбежали, его оставили там." }, { 20.07, "Лишённый малейшего проблеска надежды, он скитался, затерянный, в одиночестве, пока мы не вернулись сюда, чтобы вновь поселиться в Павшем Молоте." } } } } },
    [656] = { d = 40.5, v = "dwarf-male", n = { x = 475 }, c = { x = { { 0.00, "Вы должны нанести поражение Мизраэли прежде, чем она обретёт полную силу." }, { 5.16, "Если вы этого не сделаете, то, как только она наберёт достаточно сил, она кинется на своих пленителей!" }, { 12.26, "Есть такие, кто считает, что может её контролировать, но если её можно контролировать, с чего было гигантам с самого начала заковывать её в цепи?" }, { 22.32, "Потрясающая логика, да?" }, { 23.96, "Чтобы сразить Мизраэль, призовите её у её кристаллов, где вы в первый раз говорили с ней." }, { 30.06, "Нанесите ей поражение и заберите её мистические оковы, а потом подсоедините их к кристаллам Мизраэли." }, { 37.04, "Сделайте так – и она вновь будет поймана в ловушку." } } }, t = { d = 25.6, v = "narrator", n = { x = 277 }, c = { x = { { 0.00, "Когда мистические оковы охватывают кристаллы, из подземных глубин раздаётся нечеловеческий вой, переходящий в рык." }, { 8.75, "Кристаллы Мизраэли больше не излучают тепла и чувства безопасности, как это было раньше." }, { 15.73, "Теперь они пульсируют неприкрытой угрозой... как если бы существо внизу, под ними, исходило злобой, направленной на поверхность." } } } } },
    [657] = { d = 36.2, v = "human-female#47", n = { x = 456 }, c = { x = { { 0.00, "*Кви начинает просматривать папку.*" }, { 2.72, "Это в самом деле интересно!" }, { 4.57, "Похоже, аптекарь Йорель проводил здесь, на ферме Го'Шека, какие-то смертельно опасные эксперименты." }, { 10.92, "Я не знаю точно, какое это имеет отношение к Хилсбраду, но Фину не понравится, если мы проигнорируем такое дело." }, { 18.19, "Мы тут столкнулись с орками в ваше отсутствие, и теперь я не настолько хорошо себя чувствую, чтобы отправиться на помощь к Кинелори." }, { 26.62, "Но если вы не против, проводите её к ферме, где она собирается выкрасть результаты исследований, которые Йорель так и не отослал пока на Мельницу Таррен." } } }, t = { d = 18.2, v = "nightelf-female#52", n = { x = 209 }, c = { x = { { 0.00, "Если это успокоит Фина, я уничтожу каждого из Отрёкшихся поодиночке." }, { 4.81, "Он столько сделал для нас с тех пор, как началась чума." }, { 8.61, "Мы и не надеялись, что когда-нибудь у нас снова будут друзья или семья." }, { 13.62, "Когда будете готовы, дайте мне знать." }, { 16.28, "Мы тотчас же двинемся в путь." } } } } },
    [658] = { d = 32.9, v = "human-female#47", n = { x = 407 }, c = { x = { { 0.00, "Так вас Фин послал узнать, как мы тут?" }, { 2.42, "Неудивительно – он слишком много беспокоится." }, { 5.38, "Мы уже много дней наблюдаем за этой фермой, и Кин уверяет, что недавно видела гонца, выходящего из вон того маленького домика с южной стороны." }, { 14.71, "Она любительница поболтать, но я всегда доверяю её ощущениям, когда мы бываем в опасных местах." }, { 20.97, "А вы часом не следопыт, а?" }, { 22.68, "Мы думаем, что гонец может относить записки в деревню Мельница Таррен." }, { 27.35, "Если бы мы могли заполучить эти документы, это пролило бы свет на события в Хилсбраде." } } }, t = { d = 3.8, v = "human-female#47", n = { x = 31 }, c = { x = { { 0.00, "Отлично!" }, { 0.87, "Посмотрим, о чём тут идёт речь..." } } } } },
    [659] = { d = 35.8, v = "human-male", n = { x = 452 }, c = { x = { { 0.00, "Приветствую, приятно познакомиться." }, { 2.34, "Я руковожу группой смельчаков, расследующих странные происшествия в этом районе." }, { 7.68, "Моим родственникам в Хилсбраде недавно пришлось избавиться от своей собаки Стэнли, потому что животное таинственным образом выросло до невообразимых размеров и стало кидаться на каждого прохожего." }, { 20.71, "Я уверен, что тут замешана нежить, и мы ищем доказательства." }, { 24.67, "Две моих спутницы, Кви и Кинелори, отправились к ферме Го'Шека, что находится на Нагорье Арати, и давно не подавали о себе вестей." }, { 33.32, "Найдёте их?" }, { 34.04, "А то я начинаю беспокоиться." } } }, t = { d = 9.0, v = "human-female#47", n = { x = 117 }, c = { x = { { 0.00, "Постарайся быть как можно незаметнее, путник." }, { 2.88, "Оркам не слишком нравится, когда за ними шпионят, а их тут больше, чем видно невооружённым глазом." } } } } },
    [660] = { d = 4.2, v = "nightelf-female#52", n = { x = 34 }, c = { x = { { 0.00, "Ладно." }, { 0.68, "Если вы готовы, то и я тоже." }, { 3.39, "Попробуем?" } } }, t = { d = 12.6, v = "human-female#47", n = { x = 139 }, c = { x = { { 0.00, "Вы оказали нам огромную услугу." }, { 2.34, "Благодарю вас." }, { 3.41, "Надеюсь, Кин не доставила вам слишком много хлопот." }, { 7.22, "Она очень дружелюбна, но может быть и смертельно опасной, если вы её враг." } } } } },
    [661] = { d = 25.0, v = "human-female#47", n = { x = 325 }, c = { x = { { 0.00, "После ночной гулянки в таверне Кинелори выглядела похуже, чем сейчас." }, { 4.50, "Видно, вы неплохо её защищали." }, { 6.47, "То, что она принесла с фермы, должно как минимум дать Фину представление о том, что происходит здесь, в Арати." }, { 13.40, "Для того чтобы удостовериться, что после вашей атаки не последует ответного удара, мы здесь ненадолго задержимся." }, { 20.62, "Вы не откажетесь отправиться обратно в Южнобережье и поговорить с Фином?" } } }, t = { d = 32.9, v = "human-male", n = { x = 364 }, c = { x = { { 0.00, "Итак, эти две баламутки в конечном счёте – в полном порядке?" }, { 4.39, "Ха-ха, рад слышать." }, { 5.83, "Благодарю вас за вести об их местонахождении и состоянии – меня в высшей степени радует, что они ещё живы; обе они – мои близкие подруги и незаменимые спутницы в путешествиях." }, { 18.54, "Но... более важна моя благодарность за вашу помощь." }, { 22.34, "Вот, примите это вместе с благодарностью от всей нашей группы." }, { 26.87, "Если посчастливится, мы выясним, что затевают Отрёкшиеся, и положим конец их замыслам." } } } } },
    [662] = { d = 36.9, v = "goblin-male", n = { x = 418 }, c = { x = { { 0.00, "О'Брин повёл корабли в бухту." }, { 2.11, "Мы были уверены, что именно здесь будет найдено сокровище." }, { 6.27, "\"Вестник\" причалил нормально, но когда \"Девичья Блажь\" и \"Дух Серебряного бора\" приблизились к берегу, вода начала быстро понижаться." }, { 15.67, "Страннейшая вещь, я такого в жизни не видал!" }, { 18.80, "Те два корабля налетели на что-то... нечто вроде храма в рифе." }, { 23.28, "Оба быстро затонули – это была настоящая трагедия." }, { 26.98, "Нужно найти судовые журналы и карты обоих кораблей, прежде чем мы отчалим." }, { 32.36, "Мы не можем оставить эту информацию доступной для любопытных глаз!" } } }, t = { d = 8.7, v = "goblin-male", n = { x = 102 }, c = { x = { { 0.00, "Известие о том, что теперь эти сведения в безопасности, немного успокоит наше начальство в Пиратской бухте." }, { 7.70, "Хорошая работа." } } } } },
    [663] = { d = 41.4, g = 1, v = "named/2766", n = { x = 422 }, c = { m = { { 0.00, "Ой, кого видит Лоло!" }, { 1.70, "Это ж крошка-герой!" }, { 3.32, "Лоло всегда начеку!" }, { 4.95, "Добро пожаловать в бухту Фальдира." }, { 7.71, "Капитан О'Брин сказал, что мы задержимся тут лишь на несколько часов." }, { 13.09, "Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую бухту." }, { 20.87, "Но Лоло думает, мы тут надолго засели." }, { 23.91, "Из нашей эскадры мы потеряли два корабля." }, { 27.16, "Беднягу \"Дух Серебряного бора\" и несчастную \"Девичью Блажь\"." }, { 31.83, "На дне морском они теперь!" }, { 33.95, "Лоло думает, вам бы переговорить с капитаном О'Брином, если вы тут и дальше слоняться собираетесь." } }, f = { { 0.00, "Ой, кого видит Лоло!" }, { 1.68, "Это ж крошка-героиня!" }, { 3.43, "Лоло всегда начеку!" }, { 5.05, "Добро пожаловать в бухту Фальдира." }, { 7.78, "Капитан О'Брин сказал, что мы задержимся тут лишь на несколько часов." }, { 13.11, "Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую бухту." }, { 20.82, "Но Лоло думает, мы тут надолго засели." }, { 23.83, "Из нашей эскадры мы потеряли два корабля." }, { 27.05, "Беднягу \"Дух Серебряного бора\" и несчастную \"Девичью Блажь\"." }, { 31.68, "На дне морском они теперь!" }, { 33.78, "Лоло думает, вам бы переговорить с капитаном О'Брином, если вы тут и дальше слоняться собираетесь." } } }, t = { d = 37.4, v = "human-male", n = { x = 440 }, c = { x = { { 0.00, "Хей, дружище." }, { 0.92, "Ну и жуть же была." }, { 2.15, "Морской Рог отнимет у меня корабль, если проведает, что тут произошло." }, { 6.93, "Одна из этих хитрых профессорских штучек указала на то, что поблизости от этой бухты лежит давно утерянный клад." }, { 14.59, "Я привёл \"Вестник\" к берегу, чтобы причалить, и сигнализировал \"Духу Серебряного бора\" и \"Девичьей Блажи\", чтобы они сделали то же самое." }, { 23.91, "А потом вдруг море загрохотало." }, { 26.06, "Вода понизилась, и оба корабля разбились, врезавшись в риф." }, { 30.10, "Но это был не просто риф." }, { 31.82, "Что-то было там, внизу..." }, { 33.60, "Помогите моей команде, и получите неплохое вознаграждение." } } } } },
    [664] = { d = 42.1, v = "dwarf-male", n = { x = 423 }, c = { x = { { 0.00, "Ох, жизнь – ужасная штука." }, { 2.08, "Я должен бы покоиться в водяной могиле, а не сидеть здесь у огня, наслаждаясь свежим воздухом." }, { 9.54, "Команда не жалела сил, чтобы спасти мою прекрасную \"Девичью Блажь\"." }, { 14.91, "Да упокоятся ребята в мире, благословенны их сердца." }, { 19.07, "О'Брину удалось выбраться на берег, а нам не повезло." }, { 23.30, "Море просто опрокинулось на нас, клянусь вам." }, { 26.89, "Вот мы плывём – и вот следующая волна обрушивается на нас." }, { 31.33, "А эти твари!" }, { 32.41, "Они убили всех, кто выжил." }, { 34.56, "Подлое нагово отродье." }, { 36.42, "Я вырубился и пришёл в себя уже здесь." }, { 39.44, "Я жажду их мерзкой холодной крови!" } } }, t = { d = 11.5, v = "dwarf-male", n = { x = 120 }, c = { x = { { 0.00, "Славно потрудились." }, { 1.58, "Эти твари получили по заслугам." }, { 4.15, "Хотя ничто не вернёт мне мой корабль и мою команду, смерть этих наг даёт хоть какое-то утешение." } } } } },
    [665] = { d = 36.5, v = "gnome-male", n = { x = 432 }, c = { x = { { 0.00, "Теперь, когда мы настоящие полноценные разбойники Черноводья, мы должны помочь мистеру О'Брину разыскать пропавшее эльфийское сокровище." }, { 9.58, "Почти невозможно найти драгоценные камни в море без посторонней помощи." }, { 14.66, "Доктор сконструировал специальные очки, которые должны помочь." }, { 19.11, "Ему нужно зарядить эти очки энергией, извлечённой из заколдованного камня в пещере, расположенной выше по холму." }, { 27.04, "Но эта пещера проклята!" }, { 28.75, "Когда мы подошли к ней, на нас напали." }, { 31.42, "Защитите меня, и я смогу вытянуть энергию из камня и направить её в очки." } } }, t = { d = 4.6, v = "gnome-male", n = { x = 43 }, c = { x = { { 0.00, "Теперь очки работают превосходно!" }, { 3.15, "Отличная работа." } } } } },
    [666] = { d = 36.1, v = "gnome-male", n = { x = 401 }, c = { x = { { 0.00, "Сокровища так долго лежали на дне морском, что покрылись известковым налётом, превратившись в большой камень." }, { 7.81, "Но сила, влитая в эти очки, позволит вам легко определить их местонахождение." }, { 13.45, "Маленькая гномья ловкость делает большие дела!" }, { 16.93, "Возьмите эти очки Ловца сокровищ, посмотрите, может, вам удастся собрать какие-то из утерянных сокровищ для капитана О'Брина." }, { 26.12, "Я бы и сам поплыл туда, но... эм... ну, у меня есть серьёзные научные задачи, требующие срочного решения на надёжной, сухой земле... да... вот." } } }, t = { d = 8.4, v = "gnome-male", n = { x = 89 }, c = { x = { { 0.00, "Великолепно!" }, { 1.01, "Капитан будет очень доволен!" }, { 3.38, "Погодите, вот ещё весть долетит до флотовладельца Морского Рога!.." } } } } },
    [667] = { d = 33.4, v = "human-male", n = { x = 381 }, c = { x = { { 0.00, "Это плохо." }, { 0.82, "Похоже, клан Пронзающего Гребня готовится к нападению." }, { 4.58, "Наги известны своей жестокостью в бою." }, { 7.34, "Они не остановятся, пока я не умру." }, { 9.85, "Не то чтобы я ценил свою жизнь выше, чем жизни членов команды, но вы должны помочь защитить меня." }, { 16.69, "Я единственный, кто знает морские пути, – команда просто не сможет вернуться в Пиратскую бухту без меня." }, { 23.97, "Наги придут с моря." }, { 25.41, "Мне нужно, чтобы вы оставались здесь, со мной, чтобы отразить их атаку." }, { 30.30, "Займите место у пушки и оттесните их." }, { 32.94, "Готовы?" } } }, t = { d = 19.3, g = 1, v = "human-male", n = { x = 216 }, c = { m = { { 0.00, "Мы пережили их атаку!" }, { 1.52, "Без вас, нам бы это не удалось." }, { 3.67, "Мы отчалим, как только поднимется прилив." }, { 6.58, "Если бы вы не были столь многообещающей героической личностью, я предложил бы вам место в своей команде." }, { 13.79, "Но, конечно, вас ждёт рыбка покрупнее." }, { 16.45, "Несмотря на то, что вы всего лишь путник..." } }, f = { { 0.00, "Мы пережили их атаку!" }, { 1.51, "Без вас, нам бы это не удалось." }, { 3.66, "Мы отчалим, как только поднимется прилив." }, { 6.56, "Если бы вы не были столь многообещающей героической личностью, я предложил бы вам место в своей команде." }, { 13.75, "Но, конечно, вас ждёт рыбка покрупнее." }, { 16.40, "Несмотря на то, что вы всего лишь путница..." } } } } },
    [668] = { d = 23.1, v = "gnome-male", n = { x = 283 }, c = { x = { { 0.00, "Не будем заставлять капитана О'Брина ждать." }, { 2.95, "Он захочет первым увидеть эти драгоценности." }, { 6.03, "В конце концов, для того мы и здесь!" }, { 8.49, "А через несколько недель сотрудничества с этими пиратами мы с профессором поняли, что на нашем здоровье самым пагубным образом может сказаться, если нас застанут придерживающими их сокровища." }, { 21.48, "Вот, отнесите всё О'Брину." } } }, t = { d = 9.0, v = "human-male", n = { x = 100 }, c = { x = { { 0.00, "Так, значит, коротышки в конце концов оказались полезными?" }, { 4.33, "Я знал, что мы этих мальчиков-с-пальчик не напрасно взяли с собой!" } } } } },
    [669] = { d = 33.5, v = "human-male", n = { x = 414 }, c = { x = { { 0.00, "Командир флота Морской Рог захочет сразу же услышать о нашей находке." }, { 4.70, "Но, как видите, мы пока не в том положении, чтобы сняться отсюда." }, { 9.03, "Не только прилив очень низок, но ещё и эти проклятые твари, которым мы помешали, бдительно следят за нашими передвижениями." }, { 17.28, "Вы оказали бы большую услугу Разбойникам Черноводья, если бы смогли сообщить командиру флота Морскому Рогу в Пиратскую бухту, что мы отыскали сокровища и работаем над тем, чтобы достать ещё." }, { 29.93, "А этот образчик отвезите ему в качестве доказательства." } } }, t = { d = 8.7, v = "tauren-male", n = { x = 76 }, c = { x = { { 0.00, "А, узнаю старого доброго Мураша О'Брина!" }, { 3.86, "Я знал, что это подходящий капитан для такого задания!" } } } } },
    [670] = { d = 32.0, v = "tauren-male", n = { x = 326 }, c = { x = { { 0.00, "Слушайте, у вас лицо искателя приключений." }, { 3.47, "Мой флот застрял в Пиратской бухте, пока мы не загрузимся." }, { 8.20, "Там, да и не только там, творятся тёмные делишки, а мне нужно доставить кое-какую секретную корреспонденцию Мурашу О'Брину, пришвартовавшемуся к побережью Арати." }, { 21.21, "Могу ли я доверить вам доставку этого сообщения в целости и сохранности и надеяться на вашу готовность хранить это задание в секрете?" } } }, t = { d = 7.0, v = "human-male", n = { x = 82 }, c = { x = { { 0.00, "Спасибо, что проделали такой долгий и опасный путь." }, { 3.79, "Благодарю вас от имени разбойников Черноводья." } } } } },
    [671] = { d = 43.9, v = "troll-male#77", n = { x = 485 }, c = { x = { { 0.00, "Я почувствовал что-то странное в воздухе... ощущение, будоражащее мою кровь." }, { 5.71, "У меня возникли подозрения." }, { 7.82, "Я твёрдо решил найти источник беспокойства и обнаружил на западе, у Северного поместья, остаточные следы призыва демона." }, { 16.87, "Когда я приблизился, кровь буквально вскипела, и ярость разгорелась во мне." }, { 22.44, "На земле я заметил амулет из кровавого камня, какими пользуются, вызывая демона." }, { 28.56, "Однако магическая сила найденного мной камня была уже полностью исчерпана." }, { 34.28, "Мне нужен для изучения другой образец, но я не рискую возвращаться в поместье." }, { 40.12, "Можете ли вы принести мне оттуда несколько амулетов?" } } }, t = { d = 13.8, v = "troll-male#77", n = { x = 153 }, c = { x = { { 0.00, "Выявление истинных намерений Синдиката отнимет у меня некоторое время, но их очевидное сотрудничество с тёмными демоническими силами меня беспокоит." }, { 11.52, "Я расскажу вам, когда разузнаю." } } } } },
    [672] = { d = 37.0, v = "troll-male#77", n = { x = 380 }, c = { x = { { 0.00, "Мы пытались успокоить его, развеселить, рассказывать ему истории о нашем огромном городе Оргриммаре на Калимдоре, но его ничто не трогало." }, { 11.01, "Истории о нашем молодом вожде, Тралле, который носит доспехи и молот Оргрима... но, быть может..." }, { 18.81, "Может быть!" }, { 19.74, "Демонстрация нашей новообретённой шаманской магии могла бы дать ему луч надежды." }, { 26.03, "Попробовать стоит!" }, { 27.54, "Мы могли бы сделать для него маленькую вещицу, да..." }, { 31.68, "Принесите мне несколько глаз раптора, и я посмотрю, что можно сделать." } } }, t = { d = 8.5, v = "troll-male#77", n = { x = 76 }, c = { x = { { 0.00, "Отлично." }, { 0.81, "Духи ящеров, от которых взяты эти глаза, предоставят носящему этот амулет свою силу." } } } } },
    [673] = { d = 36.6, v = "troll-male#77", n = { x = 415 }, c = { x = { { 0.00, "У меня нет сомнений, что в стенах Стромгарда засел могущественный чернокнижник." }, { 5.87, "Время от времени, используя обладающую магической энергией реликвию, этот чернокнижник призывал в больших количествах ужасных демонов." }, { 15.93, "Мы должны отнять у него этот источник энергии." }, { 19.51, "Найдите чернокнижника и убейте его." }, { 22.21, "Принесите мне магический объект, который найдёте при нём, чем бы он ни оказался." }, { 28.01, "Я предприму шаги по разрушению реликвии и прослежу, чтобы её мощь больше не использовалась для осквернения этой земли." } } }, t = { d = 19.0, v = "troll-male#77", n = { x = 183 }, c = { x = { { 0.00, "Мои бессонные ночи наконец сменятся спокойным сном, когда я разрушу эту сферу." }, { 6.92, "Спасибо вам." }, { 8.01, "Это леденящее напоминание о той ужасной власти, которую демоны имели над орками, прежде чем Адский Крик освободил их от проклятья." } } } } },
    [674] = { d = 11.0, v = "troll-male#77", n = { x = 104 }, c = { x = { { 0.00, "Вот, отнесите этот амулет Гор'мулю и посмотрите, пробудит ли сила ящера в нём тот боевой огонь, который некогда пылал в его крови." } } }, t = { d = 10.6, v = "orc-male#60", n = { x = 110 }, c = { x = { { 0.00, "Что это?" }, { 0.72, "Отполированный кусок кости..." }, { 3.11, "Что мне пользы от полированной косточки?" }, { 6.30, "Разве безделушка способна вернуть Орде её былую славу?" } } } } },
    [675] = { d = 18.8, v = "orc-male#60", n = { x = 191 }, c = { x = { { 0.00, "*Гор'муль бросает амулет на землю.*" }, { 2.72, "Вас Тор'ган послал, да?" }, { 4.52, "Тьфу..." }, { 5.07, "Никак не могу понять, почему он жалеет меня." }, { 8.59, "В сострадании мне было отказано, когда мне не позволили умереть вместе с моим вождём во время боя." }, { 16.12, "Жестокий удар судьбы настиг меня..." } } }, t = { d = 16.3, v = "troll-male#77", n = { x = 168 }, c = { x = { { 0.00, "Вижу, что не сработало." }, { 1.88, "Тем не менее я чувствую, что демонстрация силы шаманов может помочь Гор'мулю вернуть веру в себя." }, { 9.75, "Сила амулета была недостаточно велика, чтобы показать ему нашу новообретённую мощь." } } } } },
    [676] = { d = 38.7, g = 1, v = "scourge-male", n = { m = 318, f = 318 }, c = { m = { { 0.00, "Слабаки..." }, { 1.04, "Все они слабаки." }, { 2.70, "А ты, герой, куда смотришь?" }, { 5.39, "Думаешь, особенный?" }, { 7.31, "Проверим?" }, { 8.26, "На форт Павший Молот напали враги." }, { 11.66, "Если не помочь нашим, им не устоять." }, { 15.22, "Впрочем, не спеши." }, { 17.05, "Прежде надо испытать твоё искусство." }, { 20.62, "На северо-востоке от Стромгарда в Арати есть курган, который заселило огрское племя Тяжёлого Кулака." }, { 30.27, "Когда одолеешь тамошних огров и мародёров, доложи об этом Драму Жёлчному в Павшем Молоте." } }, f = { { 0.00, "Слабаки..." }, { 1.02, "Все они слабаки." }, { 2.64, "А ты, героиня, куда смотришь?" }, { 5.44, "Думаешь, особенная?" }, { 7.31, "Проверим?" }, { 8.24, "На форт Павший Молот напали враги." }, { 11.56, "Если не помочь нашим, им не устоять." }, { 15.04, "Впрочем, не спеши." }, { 16.83, "Прежде надо испытать твоё искусство." }, { 20.31, "На северо-востоке от Стромгарда в Арати есть курган, который заселило огрское племя Тяжёлого Кулака." }, { 29.75, "Когда одолеешь тамошних огров и мародёров, доложи об этом Драму Жёлчному в Павшем Молоте." } } }, t = { d = 31.3, v = "orc-male#60", n = { x = 307 }, c = { x = { { 0.00, "Значит, ты думаешь, что тебе хватит сил помочь Павшему Молоту?" }, { 5.08, "Да будет так." }, { 6.17, "Сальный послал тебя в огрский курган или в надежде, что ты там погибнешь, или полагая, что сможешь помочь нам." }, { 15.10, "Так или иначе, ты здесь, а мне нужны солдаты." }, { 18.73, "Натиск на наш форт не ослабевает." }, { 21.34, "Если ты собираешься остаться в Павшем Молоте, то отдохни, а потом приходи ко мне." }, { 27.88, "Чего-чего, а сражений на твою долю хватит." } } } } },
    [677] = { d = 39.8, v = "orc-male#60", n = { x = 393 }, c = { x = { { 0.00, "Тролли племени Сухокожих и огры клана Тяжёлого Кулака с нагорья Арати стакнулись, чтобы выжить нас с этой земли, но мы не собираемся уступать ни им, ни кому угодно другому." }, { 13.99, "Мы убьём их и покажем, что и мы здесь – у себя дома." }, { 18.09, "Тролли позорно бежали от нас; огры сожрали бы нас и спали бы на наших шкурах, если бы мы им позволили, – этим тварям не должно жить." }, { 28.79, "Мы начнём атаковать троллей Сухокожих к югу отсюда." }, { 32.96, "Убивай их пачками и возвращайся только тогда, когда их поселения будут залиты кровью." } } }, t = { d = 9.6, v = "orc-male#60", n = { x = 81 }, c = { x = { { 0.00, "Я вижу боевые отметины на твоих доспехах, и пот струится по твоему лбу." }, { 6.77, "Неплохо, в самом деле неплохо." } } } } },
    [678] = { d = 39.6, v = "orc-male#60", n = { x = 412 }, c = { x = { { 0.00, "Твоя сила очевидна." }, { 1.62, "Теперь посмотрим, как ты справишься с настоящим врагом." }, { 5.90, "У клана Тяжёлого Кулака есть логово к юго-западу отсюда по направлению к дворфийскому мосту, и, если я не ошибаюсь, их молотобойцы и маги должны стать для тебя более серьёзным испытанием – по крайней мере, для нас они таковым являются по сию пору." }, { 24.93, "Убей столько огров, сколько сможешь, и возвращайся ко мне во плоти, если добьёшься успеха, или в виде призрака, если потерпишь неудачу." }, { 35.54, "В любом случае я воздам хвалу твоей стойкости в бою." } } }, t = { d = 6.1, v = "orc-male#60", n = { x = 53 }, c = { x = { { 0.00, "Ты не слабее кодо, а твоя готовность к битве достойна восхищения." } } } } },
    [679] = { d = 31.5, v = "orc-male#60", n = { x = 311 }, c = { x = { { 0.00, "Зверю вот-вот отрубят голову... и всё же для решающего удара требуется огромная сила." }, { 7.13, "Уверен, именно ты можешь помочь нам нанести этот последний мощный удар." }, { 13.21, "Руководящие этими атаками устроили своё логово прямо в руинах Стромгарда – вот яркий пример человеческой слабости..." }, { 22.89, "Найди и убей вождей клана Тяжёлого Кулака и их прислужников-шаманов, пытающихся выжить нас с этих земель." } } }, t = { d = 10.1, v = "orc-male#60", n = { x = 98 }, c = { x = { { 0.00, "Твой народ может гордиться тобой." }, { 2.92, "Угроза сильно уменьшилась, и я уверен, что мы начнём процветать здесь, на этом нагорье." } } } } },
    [680] = { d = 38.9, g = 1, v = "orc-female", n = { x = 396 }, c = { m = { { 0.00, "Вы отлично служите моему мужу, герой, но он не знает, почему Павший Молот подвергается атакам." }, { 7.11, "Ор'Калар – пешка в руках Муг'Тола в Стромгарде – яро ненавидит моего мужа и ничего так не желает, как его смерти – за то, что тот нанёс ему поражение много лет назад." }, { 20.64, "Мои гадатели сообщают, что Ор'Калар устроил для мужа ловушку, поэтому я скрыла от него, что огр объявился в этих землях." }, { 29.63, "Мой муж ринется сломя голову, если узнает о местонахождении огра, а я хотела бы попросить вашей помощи в убийстве этой твари." } }, f = { { 0.00, "Вы отлично служите моему мужу, героиня, но он не знает, почему Павший Молот подвергается атакам." }, { 7.26, "Ор'Калар – пешка в руках Муг'Тола в Стромгарде – яро ненавидит моего мужа и ничего так не желает, как его смерти – за то, что тот нанёс ему поражение много лет назад." }, { 19.64, "Мои гадатели сообщают, что Ор'Калар устроил для мужа ловушку, поэтому я скрыла от него, что огр объявился в этих землях." }, { 28.65, "Мой муж ринется сломя голову, если узнает о местонахождении огра, а я хотела бы попросить вашей помощи в убийстве этой твари." } } }, t = { d = 16.5, v = "orc-female", n = { x = 173 }, c = { x = { { 0.00, "Вы оказали мне огромную услугу." }, { 2.52, "Знайте, что жизнь моего мужа и безопасность Павшего Молота ещё на некоторое время защищены благодаря вашим деяниям." }, { 11.74, "Пожалуйста, примите это в качестве награды за вашу смелость." } } } } },
    [681] = { d = 34.1, v = "human-female#47", n = { x = 426 }, c = { x = { { 0.00, "Мы ведём войну за Стромгард и терпим в ней поражение." }, { 3.43, "Мы делим наш некогда великий город с ограми и Синдикатом, каждая группировка бьётся с другой, и конца этому не видно." }, { 11.11, "Но наши силы иссякают, в то время как силы наших врагов – растут." }, { 15.48, "Нам нужна помощь из Южнобережья, но есть проблемы с доставкой припасов, поскольку Синдикат контролирует территорию между нами." }, { 23.70, "Иди на базу Синдиката в Северном поместье и перебей там всех." }, { 27.72, "Тогда, может быть, давление на наши транспортные пути ослабеет, и доставлять припасы станет проще." } } }, t = { d = 10.1, v = "human-female#47", n = { x = 115 }, c = { x = { { 0.00, "Очень хорошо." }, { 1.06, "Со смертью этих членов Синдиката нам должно стать полегче получать припасы из Южнобережья." }, { 7.70, "Быть может, у нас ещё есть надежда." } } } } },
    [682] = { d = 30.1, v = "human-female#47", n = { x = 406 }, c = { x = { { 0.00, "Синдикат в Стромгарде воюет с силами нашего ополчения." }, { 3.44, "Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев." }, { 16.63, "Мы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!" }, { 24.30, "Отправляйтесь в район Стромгарда, контролируемый Синдикатом, и отберите у их бойцов наши знаки." } } }, t = { d = 12.0, v = "human-female#47", n = { x = 146 }, c = { x = { { 0.00, "Спасибо вам." }, { 0.85, "Мы известим семьи этих погибших солдат о том, что они пали в бою." }, { 5.37, "Это будут печальные вести, и всё же лучше знать о судьбе любимых людей, чем томиться неизвестностью." } } } } },
    [683] = { d = 20.5, g = 1, v = "dwarf-female#33", n = { m = 233, f = 230 }, c = { m = { { 0.00, "У меня есть к вам маленькая просьба." }, { 2.64, "Возьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода." }, { 10.84, "Это небольшой труд для такого, как ты, славного героя." }, { 14.81, "Мне в моём горе сейчас трудно будет предстать перед королём." }, { 19.24, "Ты понимаешь меня." } }, f = { { 0.00, "У меня есть к вам маленькая просьба." }, { 2.62, "Возьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода." }, { 10.73, "Это небольшой труд для такой, как ты, славной девы." }, { 14.47, "Мне в моём горе сейчас трудно будет предстать перед королём." }, { 18.85, "Ты понимаешь меня." } } }, t = { d = 3.1, v = "dwarf-male#177", n = { x = 29 }, c = { x = { { 0.00, "Подождите минутку, я прочту письмо..." } } } } },
    [684] = { d = 25.7, v = "narrator", n = { x = 279 }, c = { x = { { 0.00, "Назначена награда за голову Марез Клобук, высокопоставленной советницы и агента Синдиката." }, { 7.10, "В последний раз её видели на контролируемой Синдикатом территории Стромгарда." }, { 13.06, "Награду можно будет получить у капитана Ниалс." }, { 16.82, "Предупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами." }, { 23.77, "Вооружена и очень опасна!" } } }, t = { d = 19.5, v = "human-female#47", n = { x = 235 }, c = { x = { { 0.00, "Вы справились с Марез Клобук?" }, { 2.03, "Отличная работа." }, { 3.21, "В самом деле отличная!" }, { 4.81, "Марез была серьёзной угрозой стромгардским защитникам, и ходят слухи, что она служила посредницей между Синдикатом и какими-то другими, тёмными силами." }, { 15.10, "Мы рады узнать, что она больше не будет строить козни против нас." } } } } },
    [685] = { d = 32.7, v = "narrator", n = { x = 360 }, c = { x = { { 0.00, "Ополчение Стромгарда уведомляет о назначении награды за головы лорда Соколиного Шлема и его телохранителя Отто." }, { 8.62, "Соколиный Шлем руководит деятельностью Синдиката на нагорье Арати, и его смерть внесла бы большую сумятицу." }, { 16.82, "Его телохранитель Отто, хотя и не является стратегической целью, представляет собой опасного противника, на счету которого – смерть десятков наших воинов." }, { 28.70, "Награды за их головы можно получить у капитана Ниалс." } } }, t = { d = 7.1, v = "human-female#47", n = { x = 65 }, c = { x = { { 0.00, "Лорд Соколиный Шлем и Отто?" }, { 2.43, "Отлично!" }, { 3.24, "Вот ваша награда." }, { 4.85, "Я с радостью выплачиваю её." } } } } },
    [686] = { d = 42.9, g = 1, v = "dwarf-male#177", n = { x = 419 }, c = { m = { { 0.00, "Вряд ли добрые дворфские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа." }, { 10.96, "Гибель её мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе." }, { 19.82, "Мне не под силу вернуть её супруга из Круговерти Пустоты, но я могу хотя бы почтить его память." }, { 27.52, "Я намерен заказать главному каменотёсу Стальгорна Мраморщику памятник в честь Салли Баллу." }, { 34.71, "Отправляйтесь к нему сейчас же и передайте мои слова, герой." }, { 39.65, "Вы будете моим вестником." } }, f = { { 0.00, "Вряд ли добрые дворфские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа." }, { 11.26, "Гибель её мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе." }, { 20.36, "Мне не под силу вернуть её супруга из Круговерти Пустоты, но я могу хотя бы почтить его память." }, { 28.27, "Я намерен заказать главному каменотёсу Стальгорна Мраморщику памятник в честь Салли Баллу." }, { 35.65, "Отправляйтесь к нему сейчас же и передайте мои слова, героиня." }, { 40.87, "Вы будете моим вестником." } } }, t = { d = 7.8, v = "dwarf-male", n = { x = 75 }, c = { x = { { 0.00, "Значит, вас послал лично король Магни Бронзобород?" }, { 4.34, "Подумать только!" }, { 5.78, "Стало быть, дело важное!" } } } } },
    [687] = { d = 26.2, v = "dwarf-male", n = { x = 285 }, c = { x = { { 0.00, "Тельдарин Заблудший некогда был членом нашего ордена Сумеречного Молота." }, { 5.48, "Однако он сошёл с ума и отверг наше учение." }, { 8.80, "Перед побегом он украл свиток Мизраэли!" }, { 11.84, "Мы не смогли поймать его, но ходят слухи, что он совсем спятил и прячется в Бесплодных землях." }, { 18.94, "Чтобы переманить на нашу сторону Госпожу, необходимо найти свиток." }, { 24.02, "А для этого – найти Тельдарина." } } }, npc = { [2787] = { d = 27.4, v = "orc-male", n = { x = 285 }, c = { x = { { 0.00, "Тельдарин Заблудший некогда был членом нашего ордена Сумеречного Молота." }, { 5.73, "Однако он сошёл с ума и отверг наше учение." }, { 9.20, "Перед побегом он украл свиток Мизраэли!" }, { 12.38, "Мы не смогли поймать его, но ходят слухи, что он совсем спятил и прячется в Бесплодных землях." }, { 19.81, "Чтобы переманить на нашу сторону Госпожу, необходимо найти свиток." }, { 25.11, "А для этого – найти Тельдарина." } } } } }, t = { d = 15.5, v = "dwarf-male", n = { x = 142 }, c = { x = { { 0.00, "Привет." }, { 0.68, "Привет, привет, привет, привет, привет, ПРИВЕТ!" }, { 4.77, "Прости..." }, { 5.60, "Хотя нет, ничуть мне не жаль!" }, { 8.02, "Не груби мне!" }, { 9.16, "О нет, это бред сумасшедшего." }, { 11.58, "Но иногда моё единственное утешение – в безумии." } } } } },
    [688] = { d = 44.8, g = 1, v = "creature/myzrael", n = { m = 423, f = 424 }, c = { m = { { 0.00, "*Говорит Мизраэль.*" }, { 1.84, "Свободна!" }, { 2.65, "Я СВОБОДНА!" }, { 3.62, "Я могу теперь набирать силу, скрывшись от моих пленителей." }, { 8.50, "Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы." }, { 17.83, "Но в должный час я пойду против гигантов, и они ещё пожалеют о том, что отняли у меня свободу!" }, { 25.53, "Вы благородный союзник." }, { 27.46, "Через некоторое время мне вновь понадобится ваша помощь." }, { 32.12, "Когда я буду готова, нужно, чтобы вы призвали меня на поверхность." }, { 37.68, "Поговорите с Заруком в Павшем Молоте." }, { 40.79, "Он знает, как меня можно призвать." } }, f = { { 0.00, "*Говорит Мизраэль.*" }, { 1.92, "Свободна!" }, { 2.76, "Я СВОБОДНА!" }, { 3.74, "Я могу теперь набирать силу, скрывшись от моих пленителей." }, { 8.76, "Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы." }, { 18.34, "Но в должный час я пойду против гигантов, и они ещё пожалеют о том, что отняли у меня свободу!" }, { 26.25, "Вы благородная союзница." }, { 28.30, "Через некоторое время мне вновь понадобится ваша помощь." }, { 33.09, "Когда я буду готова, нужно, чтобы вы призвали меня на поверхность." }, { 38.80, "Поговорите с Заруком в Павшем Молоте." }, { 41.99, "Он знает, как меня можно призвать." } } }, t = { d = 11.0, g = 1, v = "orc-male", n = { x = 106 }, c = { m = { { 0.00, "Добро пожаловать, герой." }, { 2.00, "Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть её на поверхность, нам нужно многое обсудить." } }, f = { { 0.00, "Добро пожаловать, героиня." }, { 2.18, "Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть её на поверхность, нам нужно многое обсудить." } } } } },
    [689] = { d = 30.0, v = "dwarf-male", n = { x = 356 }, c = { x = { { 0.00, "Значит, наш добрый король решил построить памятник в честь солдата по имени Салли Баллу?" }, { 6.23, "И вы говорите, что бедный парень погиб на мосту Тандола?" }, { 10.19, "Эх, будет ли когда-нибудь мир в Азероте?" }, { 12.96, "Как бы то ни было, любое поручение нашего государя – дело первостепенной важности." }, { 18.69, "Чтобы возвести действительно впечатляющий памятник на века, мне нужен самый лучший камень." }, { 25.05, "Отправляйся на Холм Дарроу в Хилсбрад и привези мне альтеракского гранита." } } }, t = { d = 6.4, v = "dwarf-male", n = { x = 63 }, c = { x = { { 0.00, "Замечательно!" }, { 1.10, "Лучше, чем я представить мог!" }, { 3.46, "А воображение у меня, между прочим..." } } } } },
    [690] = { d = 30.2, v = "human-male", n = { x = 385 }, c = { x = { { 0.00, "Приветствую вас." }, { 1.06, "Вы похожи на искателя приключений, а у меня как раз есть задание, требующее склонности к авантюрам." }, { 7.39, "Верховный маг Трелан, мой первый наставник, не так давно бежал из Стромгарда, что на нагорье Арати, и просил меня помочь ему вернуть несколько предметов, которые он там оставил." }, { 18.88, "Город был осаждён, и Трелан попытался защитить Башню Аратора, но потерпел неудачу." }, { 24.22, "У меня на нагорье есть агенты, но они просили дополнительной помощи." }, { 28.68, "Вы согласитесь мне помочь?" } } }, t = { d = 13.7, v = "dwarf-male", n = { x = 147 }, c = { x = { { 0.00, "Так вас, значится, Малин прислал?" }, { 2.51, "А мне без разницы, пусть хоть сам Мурадин восстанет из мёртвых и умчит вас отсюда на драконе..." }, { 9.42, "Я занят!" }, { 10.10, "Если вам что-нибудь нужно, обратитесь к Кретьену." } } } } },
    [691] = { d = 26.5, v = "human-male", n = { x = 310 }, c = { x = { { 0.00, "Верховный маг Малин послал нас со Скуэрто собирать для него реагенты." }, { 4.82, "Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда вы здесь, думаю, моя проблема решена." }, { 12.90, "Вот что мне нужно: клыки троллей из племени Сухокожих, лекарские сумки клана Сухокожих и нож тёмного охотника." }, { 20.48, "Не могли бы вы добыть это всё для меня?" }, { 23.24, "Племя Сухокожих обитает к юго-востоку от Арати." } } }, t = { d = 28.2, v = "human-male", n = { x = 352 }, c = { x = { { 0.00, "Невероятно!" }, { 0.78, "Теперь я понимаю, почему Малин попросил вас присоединиться к нам – вы отлично потрудились!" }, { 6.68, "Такими темпами мы со Скуэрто очень скоро двинемся обратно в Штормград!" }, { 11.39, "Я уверен, что мой спутник-дворф вернулся с разведки из Крепости Тяжёлого Кулака; пообщайтесь с ним, когда будет время." }, { 19.08, "По нему заметно, что он затеял с ограми потасовку." }, { 22.42, "Впрочем, не говорите ему об этом: он очень чувствителен к критике его навыков разведчика." } } } } },
    [692] = { d = 41.7, v = "dwarf-male", n = { x = 444 }, c = { x = { { 0.00, "Свиток Мизраэли..." }, { 1.40, "Свиток Мизраэли?!" }, { 2.74, "Нет, уверяю вас, не стоит даже думать о нём!" }, { 6.00, "Его магия может вытащить Мизраэль на поверхность, и если вы это сделаете, нам грозит беда!" }, { 12.81, "Или... может быть, уже слишком поздно." }, { 15.74, "Может быть, она уже свободна." }, { 18.01, "Может быть, она уже собирается с силами, прежде чем обрушиться на нас." }, { 23.21, "Если так, свиток вам НЕПРЕМЕННО ПОНАДОБИТСЯ!" }, { 26.48, "...как ужасно, что он уничтожен." }, { 28.82, "Спятившие элементали похитили его и разорвали на клочки, а теперь дерутся за них." }, { 34.82, "Но если бы вам удалось собрать эти фрагменты, может быть, нам удалось бы восстановить свиток..." } } }, t = { d = 13.3, v = "dwarf-male", n = { x = 145 }, c = { x = { { 0.00, "А, вы их нашли!" }, { 1.12, "Отличная работа!" }, { 2.37, "Это, может, единственный наш шанс противостоять злу, которое несёт Мизраэль!" }, { 7.83, "Дайте-ка я найду мой степлер – посмотрим, смогу ли я соединить эти клочки..." } } } } },
    [693] = { d = 33.3, v = "dwarf-male", n = { x = 401 }, c = { x = { { 0.00, "Здорово." }, { 0.61, "Я выяснил, где оказалась первая вещь Трелана: Коргреш держит её в Зале Тяжёлого Кулака." }, { 6.43, "И судя по тому, как он кидался в своих потоками льда, чтобы заставить их держать строй, он, должно быть, уже близко подошёл к пониманию того, как использовать мощь жезла на полную катушку." }, { 18.92, "Чтобы добраться до Зала Тяжёлого Кулака, нужно идти на юг отсюда, а затем на восток от моста Тандола." }, { 25.78, "Найдите этого огра и отберите у него жезл." }, { 28.69, "А за время вашего отсутствия я соображу, что нам делать со Стромгардом." } } }, t = { d = 18.6, v = "dwarf-male", n = { x = 206 }, c = { x = { { 0.00, "Блестяще." }, { 0.73, "Один предмет найден, и, по моему списку, осталось ещё три." }, { 5.08, "Все они находятся в Стромгарде." }, { 7.42, "Передохните и восстановите силы – следующий этап моего плана потребует немного больше времени и усилий." }, { 15.17, "Возвращайтесь ко мне, плотно покушав и отдохнув." } } } } },
    [694] = { d = 36.9, v = "dwarf-male", n = { x = 446 }, c = { x = { { 0.00, "Все отдохнули?" }, { 0.98, "Вот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде." }, { 6.02, "Необходимо активировать защитные возможности башни, если вы хотите иметь хоть малейший шанс выстоять против них." }, { 13.63, "Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман клана Тяжёлого Кулака." }, { 21.12, "Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти." }, { 27.20, "Добудьте один из самоцветов и принесите его Кретьену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи." } } }, t = { d = 10.6, v = "human-male", n = { x = 114 }, c = { x = { { 0.00, "Вы меня просто поражаете." }, { 2.03, "Снова отличная работа." }, { 3.85, "Минутку, я применю подходящее заклинание, чтобы заколдовать самоцвет, и всё будет готово." } } } } },
    [695] = { d = 23.0, v = "human-male", n = { x = 286 }, c = { x = { { 0.00, "Вот." }, { 0.30, "Самоцвет нужно только прижать к одному из пьедесталов у основания башни, чтобы активировать её защитные силы." }, { 7.60, "Используйте его, когда будете готовы войти в башню и искать остальные принадлежащие Трелану предметы." }, { 14.42, "Удачи вам." }, { 15.14, "Я буду ждать вашего возвращения в лагере." }, { 17.89, "Ах да, перед уходом поговорите со Скуэрто: он расскажет вам обо всём, что нужно." } } }, t = { d = 5.7, v = "dwarf-male", n = { x = 54 }, c = { x = { { 0.00, "Хорошо, хорошо." }, { 1.36, "Если нас ничего больше не держит, может быть, начнём?" } } } } },
    [696] = { d = 30.5, g = 1, v = "dwarf-male", n = { m = 332, f = 332 }, c = { m = { { 0.00, "Вот что тебе нужно найти: талисман Трелана, сферу Трелана да угольный агат Трелана." }, { 6.23, "Все эти три предмета должны быть в сундуках в башне, и ты спокойненько откроешь эти сундуки; главное – берегись огров." }, { 14.90, "Защитники башни не будут ими заниматься; придётся тебе своё оружие держать наготове." }, { 21.13, "Эти огры сообразят, что ты там и пытаешься обокрасть их – ясное дело, они решат задать тебе взбучку." }, { 28.61, "Будь осторожен – и удачи!" } }, f = { { 0.00, "Вот что тебе нужно найти: талисман Трелана, сферу Трелана да угольный агат Трелана." }, { 6.26, "Все эти три предмета должны быть в сундуках в башне, и ты спокойненько откроешь эти сундуки; главное – берегись огров." }, { 14.98, "Защитники башни не будут ими заниматься; придётся тебе своё оружие держать наготове." }, { 21.24, "Эти огры сообразят, что ты там и пытаешься обокрасть их – ясное дело, они решат задать тебе взбучку." }, { 28.76, "Будь осторожна – и удачи!" } } }, t = { d = 10.7, v = "dwarf-male", n = { x = 115 }, c = { x = { { 0.00, "Никого лучше Малин и найти не мог в помощь нам." }, { 3.69, "Потрясающая работа!" }, { 5.23, "Он будет рад увидеть, каким ошеломляющим успехом увенчалась наша миссия." } } } } },
    [697] = { d = 12.6, v = "dwarf-male", n = { x = 141 }, c = { x = { { 0.00, "Отвезите это письмо обратно в Штормград и скажите Малину, что мы с Кретьеном скоро будем дома." }, { 6.95, "Он хорошо вознаградит вас за помощь нам, в этом-то я не сомневаюсь." }, { 11.74, "Доброго пути!" } } }, t = { d = 22.6, v = "human-male", n = { x = 235 }, c = { x = { { 0.00, "*Верховный маг Малин вскрывает письмо, и глаза его расширяются.*" }, { 5.76, "Светом клянусь, вам удалось!" }, { 7.94, "Трелан будет очень доволен." }, { 10.12, "Я уверен, Кретьен и Скуэрто так же, как и я, радуются своему предстоящему возвращению в Штормград." }, { 17.40, "Благодарю вас." }, { 18.49, "Пожалуйста, примите это как помощь в ваших странствиях." } } } } },
    [698] = { d = 32.1, g = 1, v = "orc-male", n = { m = 341, f = 343 }, c = { m = { { 0.00, "Я стараюсь добыть припасы для нашего поста на побережье, к востоку отсюда." }, { 5.75, "Ток'Кар делает, что может, но после несения караульной службы и приготовления пищи для солдат, времени у него остаётся немного." }, { 15.52, "Они любят мясо острозубов, но у меня до сих пор не было возможности отправить им новую партию." }, { 22.80, "Ты не мог бы помочь?" }, { 24.32, "Молодые острозубые кроколиски не так вкусны, как взрослые особи, так что дай им ещё год-другой подрасти." } }, f = { { 0.00, "Я стараюсь добыть припасы для нашего поста на побережье, к востоку отсюда." }, { 5.73, "Ток'Кар делает, что может, но после несения караульной службы и приготовления пищи для солдат, времени у него остаётся немного." }, { 15.46, "Они любят мясо острозубов, но у меня до сих пор не было возможности отправить им новую партию." }, { 22.71, "Ты не могла бы помочь?" }, { 24.43, "Молодые острозубые кроколиски не так вкусны, как взрослые особи, так что дай им ещё год-другой подрасти." } } }, t = { d = 16.0, v = "orc-male#60", n = { x = 130 }, c = { x = { { 0.00, "Прекрасно!" }, { 1.06, "Свежее мясо к ужину!" }, { 3.18, "Спасибо." }, { 4.06, "Нынешний вечерок будет куда приятнее прошлого – мы наедимся досыта." }, { 10.78, "Пускай Дар – орк на морду ужасный, зато добрый внутри." } } } } },
    [699] = { d = 32.8, v = "orc-male#60", n = { x = 357 }, c = { x = { { 0.00, "Мурлоки на побережье представляют опасность, поэтому нас послали сюда отразить эту угрозу Каменору или, если силы врага окажутся слишком велики, поднять тревогу." }, { 12.57, "Отдыхать нам особо некогда, и мы не откажемся от твоей помощи." }, { 17.34, "Из когтей острозубого крепкохвата выходит неплохое оружие, если выделать их должным образом." }, { 24.45, "Раздобудь немного для нас, и ты получишь оружие нашей работы в благодарность за свежее мясо и хорошую компанию." } } }, t = { d = 18.5, g = 1, v = "orc-male#60", n = { m = 199, f = 199 }, c = { m = { { 0.00, "Рад видеть тебя живым и здоровым." }, { 2.54, "Эти когти нам весьма пригодятся, ведь чем больше оружия у нас будет в момент атаки, тем лучше." }, { 9.55, "Начну работу над твоим экземпляром как можно скорее, много времени это не займёт, я уже наловчился его изготавливать." } }, f = { { 0.00, "Рад видеть тебя живой и здоровой." }, { 2.58, "Эти когти нам весьма пригодятся, ведь чем больше оружия у нас будет в момент атаки, тем лучше." }, { 9.72, "Начну работу над твоим экземпляром как можно скорее, много времени это не займёт, я уже наловчился его изготавливать." } } } } },
    [700] = { d = 18.3, v = "dwarf-male", n = { x = 205 }, c = { x = { { 0.00, "Ах, какой прекрасный камень доставляют из Лордерона!" }, { 3.80, "Как жаль, что этот край лежит в разрухе." }, { 6.68, "Но памятник получился весьма хорош!" }, { 9.30, "Думаю, король будет очень им доволен." }, { 12.11, "Теперь же, будьте добры, пошлите государю весть, что памятник выполнен, как он и просил." } } }, t = { d = 25.7, v = "dwarf-male#177", n = { x = 227 }, c = { x = { { 0.00, "Гранит – такая малость по сравнению с жизнью достойного дворфа." }, { 5.98, "Но ни один дворф в этом мире не вечен." }, { 9.60, "Будем надеяться, что этот мемориал станет напоминанием будущим поколениям великого Азерота." }, { 18.18, "Мы никогда не забудем, что за них отдали жизнь отважные солдаты вроде Салли Баллу." } } } } },
    [701] = { d = 23.8, v = "troll-male#77", n = { x = 266 }, c = { x = { { 0.00, "При наличии дополнительных компонентов я смогу изготовить предмет, который наделит Гор'муля коварством ящера!" }, { 8.18, "Когда сила ящера проникнет в Гор'муля, он узнает о нашем новом могуществе, и спящий в его душе воин снова пробудится!" }, { 17.16, "Для того чтобы создать предмет и соответствующее заклинание, мне потребуются сердца ящеров." } } }, t = { d = 11.2, v = "troll-male#77", n = { x = 96 }, c = { x = { { 0.00, "Да, эти отлично подойдут." }, { 2.41, "Я перенесу силу и дух ящеров в эту сферу." }, { 6.30, "Она наделит Гор'муля огненной силой и разумом ящеров." } } } } },
    [702] = { d = 27.0, v = "troll-male#77", n = { x = 277 }, c = { x = { { 0.00, "Возьмите эту сферу и используйте её энергию, чтобы дух ящера вселился в Гор'муля." }, { 6.62, "Уверен, это взбодрит его дух и откроет новые горизонты жизни." }, { 11.71, "Когда он вернётся в нормальное состояние, мы сможем разъяснить ему, в каком положении находится нынче Орда, и тогда в наших непрекращающихся войнах мы сможем получить поддержку великого воина." } } }, t = { d = 7.2, v = "orc-male#60", n = { x = 59 }, c = { x = { { 0.00, "По крайней мере, на сей раз – что-то интересное." }, { 4.49, "Оно излучает странную силу..." } } } } },
    [703] = { d = 26.9, v = "goblin-male#108", n = { x = 272 }, c = { x = { { 0.00, "О, жареные крылышки канюка, я их просто обожаю!" }, { 3.73, "Такие нежные, сочные, с густым соусом, ммм..." }, { 7.32, "Стоит только почуять запах, просто слюнки текут!" }, { 11.26, "Я прекрасно их готовлю – пальчики оближешь, как раз собирался сварганить их сегодня на ужин, но..." }, { 18.79, "У меня есть всё, кроме основного ингредиента – крылышек!" }, { 23.16, "Добудешь мне крылышек – может, поделюсь рецептом!" } } }, t = { d = 7.5, v = "goblin-male#108", n = { x = 84 }, c = { x = { { 0.00, "О, я примусь за готовку прямо сейчас!" }, { 2.82, "А вот тебе и рецепт, вдруг тоже придёт настроение покулинарничать." } } } } },
    [704] = { d = 27.7, v = "dwarf-male", n = { x = 320 }, c = { x = { { 0.00, "Последний рапорт от Эгмонда был весьма тревожен, а теперь, когда он мёртв, – тем более!" }, { 6.15, "Он сообщил, что его землекопы обнаружили некие \"древние погребальные урны\" на раскопках близ Ульдамана." }, { 13.46, "Боюсь, эта находка привлекла внимание троггов, так же как и идолы, найденные мною здесь." }, { 19.75, "Мне нужно получить эти урны для исследований." }, { 23.02, "Отправляйся к раскопкам Ульдамана, собери урны и возвращайся ко мне." } } }, t = { d = 18.7, g = 1, v = "dwarf-male", n = { m = 190, f = 191 }, c = { m = { { 0.00, "Отличная работа!" }, { 1.38, "Упорный труд и толика удачи помогут нам выяснить, как связаны трогги с этими древними артефактами." }, { 9.29, "Сегодня ты оказал геологам неоценимую помощь!" }, { 12.99, "Твои усилия не будут забыты." }, { 15.39, "Как и бедняга Эгмонд, вечная ему память..." } }, f = { { 0.00, "Отличная работа!" }, { 1.36, "Упорный труд и толика удачи помогут нам выяснить, как связаны трогги с этими древними артефактами." }, { 9.14, "Сегодня ты оказала геологам неоценимую помощь!" }, { 12.85, "Твои усилия не будут забыты." }, { 15.20, "Как и бедняга Эгмонд, вечная ему память..." } } } } },
    [705] = { d = 40.8, v = "goblin-male#108", n = { x = 472 }, c = { x = { { 0.00, "Бесплодные земли – неприятное местечко, кишащее коварными хищниками и стервятниками." }, { 6.03, "Жуткое, жуткое местечко, особенно для маленького гоблина." }, { 10.17, "Чтобы выжить, приходится постоянно изворачиваться." }, { 13.80, "У меня есть секрет изготовления световых бомб." }, { 17.10, "Я использую их, чтобы отпугивать хищников." }, { 20.15, "Сейчас у меня заканчивается запас ингредиентов, а именно: порошок синего жемчуга." }, { 26.04, "Добудь мне его, и вознаграждение не заставит себя ждать." }, { 30.06, "Надеюсь, обувь у тебя прочная?" }, { 32.33, "Синий жемчуг можно найти в раковинах моллюсков на Коварном рифе." }, { 37.06, "Да-да, на том самом Коварном рифе в Тернистой долине!" } } }, t = { d = 11.0, v = "goblin-male#108", n = { x = 100 }, c = { x = { { 0.00, "Отличный жемчуг!" }, { 1.48, "Теперь надо смолоть его в порошок, смешать тут кое с чем..." }, { 6.69, "Ну, берегитесь, стервятники!" }, { 9.10, "Я припас для вас бомбы!" } } } } },
    [706] = { d = 37.0, v = "dwarf-male", n = { x = 451 }, c = { x = { { 0.00, "В бытность мою учеником Феранора Железной Лапы, я перенял у него технику усиления оружия с помощью наложения огненных чар." }, { 8.49, "Слыхал, Феранор нынче работает в кузне при охотничьем отряде в Лордероне." }, { 13.56, "Не буду пока забивать тебе голову подробностями, скажу только, что для наведения чар требуется очень редкий ингредиент – кровь из ещё бьющегося сердца детёныша чёрного дракона." }, { 25.52, "Мне надо занять себя чем-то в ожидании распоряжений из Стальгорна, так что если принесёшь мне сердце, я продемонстрирую тебе своё умение." }, { 34.81, "Драконов найдёшь в долине Летлор." } } }, t = { d = 7.9, v = "dwarf-male", n = { x = 83 }, c = { x = { { 0.00, "О, это прекрасно подойдёт!" }, { 2.04, "Сейчас я немного поработаю над твоим оружием." }, { 5.61, "И оно будет разить без пощады!" } } } } },
    [707] = { d = 16.2, v = "dwarf-male", n = { x = 196 }, c = { x = { { 0.00, "Я получил отчёт геолога Сталекрута о ходе раскопок в Лок Модане." }, { 4.46, "Ему нужен курьер для осуществления контроля за другими нашими земляными работами." }, { 10.17, "Больше ничего сказать не могу, но если желаешь ноги поразмять, отправляйся к Сталекруту." } } }, t = { d = 7.0, v = "dwarf-male", n = { x = 70 }, c = { x = { { 0.00, "Значит, тебя послал Грозовая Вершина, да?" }, { 3.31, "Хорошо." }, { 3.94, "У меня есть для тебя важное поручение..." } } } } },
    [708] = { d = 20.9, v = "narrator", n = { x = 225 }, c = { x = { { 0.00, "Поверхность этого металлического чёрного ящика изъедена ржавчиной, как будто его погружали в кислоту – похоже, он долго пролежал в желудке гигантского кондора." }, { 12.26, "На днище ящика выбит какой-то символ и надпись под ним: \"Орудие номер девятнадцать – Осадная бригада Стальгорна\"." } } } },
    [709] = { d = 37.8, v = "dwarf-male", n = { x = 387 }, c = { x = { { 0.00, "О небеса милосердные!" }, { 1.64, "Сама судьба стучится в двери!" }, { 3.97, "Помяните моё слово!" }, { 5.48, "Рок!" }, { 5.82, "Фатум!" }, { 6.37, "Нет, я не могу более ничего сказать..." }, { 9.31, "Не могу поминать их имён, чтобы они не услышали меня!" }, { 13.42, "Но если нам удастся хотя бы узнать о них больше..." }, { 17.25, "Может, мы сможем противостоять им!" }, { 19.85, "Может быть..." }, { 20.88, "Иди в Ульдаман – проклятье, я всё же произнёс это!" }, { 24.64, "Найди табличку... табличку Рьюнэха." }, { 27.38, "Да, найди её!" }, { 28.41, "Не заставляй меня повторять!" }, { 30.60, "Она там, в глубине, в древнем сундуке, более древнем, чем любая доселе найденная работа дворфов." } } }, t = { d = 6.7, v = "dwarf-male", n = { x = 60 }, c = { x = { { 0.00, "О, судьба милосердна к нам!" }, { 2.49, "Благодарю тебя!" }, { 3.98, "Возможно, нам удастся спастись!" } } } } },
    [710] = { d = 30.4, v = "gnome-male", n = { x = 401 }, c = { x = { { 0.00, "Здесь, в Бесплодных землях, мне пришлось приостановить работу над моим последним изобретением – оковами Стихий." }, { 6.98, "Когда они будут закончены, то позволят вызывать ещё более мощных элементалей и управлять ими." }, { 12.98, "Чтобы продолжить работу, мне нужны маленькие осколки камня, чтобы опробовать на них некоторые новые заклинания и механизмы." }, { 20.82, "Маленькие осколки камня, которые можно собрать с младших каменных элементалей, как раз подойдут." }, { 26.93, "Они водятся к западу отсюда, сбегай-ка туда быстренько." } } }, t = { d = 26.1, v = "gnome-male", n = { x = 264 }, c = { x = { { 0.00, "О, вот это пойдёт!" }, { 1.49, "Спасибо!.." }, { 2.39, "Хмм..." }, { 2.91, "На выходе получается ощутимо больше песка, чем я предполагал." }, { 7.98, "Надо бы изменить коэффициент трения." }, { 11.04, "Хотя, нет!" }, { 11.94, "Величина трения будет пренебрежимо мала, если использовать масло льда!" }, { 17.76, "*Чуть слышно бормоча себе под нос, Лотвил опирается подбородком на сплетённые пальцы и погружается в раздумья...*" } } } } },
    [711] = { d = 30.6, g = 1, v = "gnome-male", n = { m = 367, f = 370 }, c = { m = { { 0.00, "Ты уже проявил себя более способным, чем все мои ученики вместе взятые." }, { 4.94, "Теперь мне потребуется сила твоих мускулов." }, { 7.92, "У каменных элементалей при должной осторожности можно найти большие каменные глыбы." }, { 13.59, "Они достаточно велики и твёрды, чтобы отколоть от них куски, удобные для исследования." }, { 19.38, "Ты найдёшь их у подножия гор к западу или юго-востоку отсюда." }, { 23.52, "Можешь не торопиться, я пока займусь исследованием более мелких кусочков, которые ты принёс мне." } }, f = { { 0.00, "Ты уже проявила себя более способной, чем все мои ученики вместе взятые." }, { 5.09, "Теперь мне потребуется сила твоих мускулов." }, { 8.13, "У каменных элементалей при должной осторожности можно найти большие каменные глыбы." }, { 13.90, "Они достаточно велики и твёрды, чтобы отколоть от них куски, удобные для исследования." }, { 19.80, "Ты найдёшь их у подножия гор к западу или юго-востоку отсюда." }, { 24.02, "Можешь не торопиться, я пока займусь исследованием более мелких кусочков, которые ты принесла мне." } } }, t = { d = 7.3, v = "gnome-male", n = { x = 76 }, c = { x = { { 0.00, "Я просто диву даюсь!" }, { 1.70, "Я думал, что только полудюжине тауренов под силу донести столько камней!" } } } } },
    [712] = { d = 29.6, g = 1, v = "gnome-male", n = { m = 343, f = 345 }, c = { m = { { 0.00, "Мне нужно, чтобы ты принёс мне ещё кое-что – браслеты каменных элементалей." }, { 5.25, "Полагаю, с помощью этих браслетов можно оценить прочность моих кандалов." }, { 10.50, "В магическом кристалле я видел нескольких каменных элементалей к юго-западу отсюда." }, { 16.45, "Недалеко от них я заметил ещё и нескольких огров." }, { 19.90, "Принеси-ка мне пять браслетов, чтобы было с запасом." }, { 23.62, "Мой Серво славится умением перепутывать все реагенты и результаты исследований." } }, f = { { 0.00, "Мне нужно, чтобы ты принесла мне ещё кое-что – браслеты каменных элементалей." }, { 5.51, "Полагаю, с помощью этих браслетов можно оценить прочность моих кандалов." }, { 10.82, "В магическом кристалле я видел нескольких каменных элементалей к юго-западу отсюда." }, { 16.85, "Недалеко от них я заметил ещё и нескольких огров." }, { 20.35, "Принеси-ка мне пять браслетов, чтобы было с запасом." }, { 24.11, "Мой Серво славится умением перепутывать все реагенты и результаты исследований." } } }, t = { d = 16.6, g = 1, v = "gnome-male", n = { m = 189, f = 190 }, c = { m = { { 0.00, "А ты никогда не задумывался о карьере лаборанта?" }, { 3.43, "Нет?" }, { 3.75, "Честное слово, я не представляю, как смогу тут управиться, когда ты уйдёшь." }, { 9.05, "У меня прежде никогда не было ученика, сочетающего в себе острый ум, любознательность и физическую силу!" } }, f = { { 0.00, "А ты никогда не задумывалась о карьере лаборанта?" }, { 3.51, "Нет?" }, { 3.83, "Честное слово, я не представляю, как смогу тут управиться, когда ты уйдёшь." }, { 9.17, "У меня прежде никогда не было ученика, сочетающего в себе острый ум, любознательность и физическую силу!" } } } } },
    [713] = { d = 39.2, v = "gnome-male", n = { x = 473 }, c = { x = { { 0.00, "Послушай, я расскажу тебе о масле льда – это лучшее средство для того, чтобы уберечь мотор или механизмы от перегрева." }, { 8.18, "Его охлаждающая способность просто потрясает, а его долговечность в качестве смазочного материала просто не имеет равных." }, { 16.47, "И это ещё не всё: оно позволяет сохранять чары на магических предметах." }, { 21.33, "Мне нужен сосуд этого масла, чтобы усилить магический потенциал кандалов моей работы и сделать их достаточно мощными, чтобы вызванный нами дух не прикончил нас на месте." }, { 32.95, "Брокин, мой друг-гоблин, научит тебя, как изготовить масло." }, { 37.01, "Ты найдёшь его в долине Альтерака." } } }, t = { d = 17.8, v = "gnome-male", n = { x = 203 }, c = { x = { { 0.00, "Великолепно!" }, { 0.90, "Оно послужит прекрасным охлаждающим компонентом для браслетов!" }, { 5.35, "И если эти чары падут раньше, чем через сто лет, клянусь, я просто отпишу всё моё имущество Серво!" }, { 12.44, "Все маги лиги будут изумлены, когда я закончу работу!" }, { 16.37, "Потерпи, и ты увидишь!" } } } } },
    [714] = { d = 30.6, g = 1, v = "gnome-male", n = { m = 328, f = 329 }, c = { m = { { 0.00, "Ты справился со своей работой выше всяких похвал." }, { 4.00, "*Мысли Лотвила явно витают где-то в его экспериментах.*" }, { 8.56, "Будешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростёртыми..." }, { 14.88, "Оп-ля!" }, { 15.40, "Лови-лови, скорей!" }, { 16.84, "Да, спасибо." }, { 17.75, "А сейчас мне нужна всего лишь одна малость." }, { 20.94, "Довольно маленькая штуковина, но очень важная: гирохронатом." }, { 25.31, "Если сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент." } }, f = { { 0.00, "Ты справилась со своей работой выше всяких похвал." }, { 4.00, "*Мысли Лотвила явно витают где-то в его экспериментах.*" }, { 8.48, "Будешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростёртыми..." }, { 14.78, "Оп-ля!" }, { 15.30, "Лови-лови, скорей!" }, { 16.73, "Да, спасибо." }, { 17.64, "А сейчас мне нужна всего лишь одна малость." }, { 20.82, "Довольно маленькая штуковина, но очень важная: гирохронатом." }, { 25.17, "Если сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент." } } }, t = { d = 25.8, v = "gnome-male", n = { x = 240 }, c = { x = { { 0.00, "ОГО!" }, { 1.28, "*Лотвил выхватывает у вас гирохронатом.*" }, { 4.24, "Отлично!" }, { 4.95, "Мы почти у цели!" }, { 6.29, "Нет, в самом деле!" }, { 7.77, "Это же мой самый приоритетный проект!" }, { 10.74, "Дай-ка я засуну эту штуку в положенное ей место, и ты увидишь плоды моих – наших! – трудов!" }, { 18.01, "Сейчас, надо только немного подождать... пару секунд... или минут... или часов..." }, { 24.58, "Ладно, разберёмся." } } } } },
    [715] = { d = 39.4, g = 1, v = "gnome-male", n = { m = 460, f = 461 }, c = { m = { { 0.00, "Полагаю, все задачи, поставленные перед тобой Лотвилом, вскоре покажутся тебе очень простыми по сравнению с тем, что ждёт впереди." }, { 8.82, "С другой стороны, ты доказал свою приверженность наукам, которые так чтит Лотвил." }, { 14.33, "Не поможешь ли ты, в таком случае, и мне?" }, { 17.09, "Мне необходимо лечебное зелье и зелье невидимости." }, { 20.52, "Похоже, и то, и другое может мне вскоре понадобиться, если Лотвил продолжит в том же духе." }, { 26.64, "Взамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвила." }, { 32.03, "Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях." } }, f = { { 0.00, "Полагаю, все задачи, поставленные перед тобой Лотвилом, вскоре покажутся тебе очень простыми по сравнению с тем, что ждёт впереди." }, { 9.10, "С другой стороны, ты доказала свою приверженность наукам, которые так чтит Лотвил." }, { 14.85, "Не поможешь ли ты, в таком случае, и мне?" }, { 17.70, "Мне необходимо лечебное зелье и зелье невидимости." }, { 21.24, "Похоже, и то, и другое может мне вскоре понадобиться, если Лотвил продолжит в том же духе." }, { 27.56, "Взамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвила." }, { 33.12, "Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях." } } }, t = { d = 7.4, v = "gnome-male", n = { x = 78 }, c = { x = { { 0.00, "УРА!" }, { 0.42, "То есть, я хотел сказать, спасибо!" }, { 3.09, "Это мне понадобится для путешествия по Бесплодным землям." } } } } },
    [716] = { d = 31.8, g = 1, v = "gnome-male", n = { m = 373, f = 375 }, c = { m = { { 0.00, "Я знаю, каким скупым бывает Лотвил, поэтому хочу сам вознаградить тебя за труды." }, { 5.80, "Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение..." }, { 12.87, "Я собрал все неиспользованные камни, которые ты принёс и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся." }, { 22.11, "Разумеется, они будут магическими." }, { 24.59, "Но мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу." } }, f = { { 0.00, "Я знаю, каким скупым бывает Лотвил, поэтому хочу сам вознаградить тебя за труды." }, { 5.56, "Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение..." }, { 12.34, "Я собрал все неиспользованные камни, которые ты принесла и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся." }, { 21.39, "Разумеется, они будут магическими." }, { 23.77, "Но мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу." } } }, t = { d = 3.2, v = "gnome-male", n = { x = 28 }, c = { x = { { 0.00, "А вот и твои браслеты." }, { 1.95, "Ну-ка, примерь!" } } } } },
    [717] = { d = 31.4, v = "bloodelf-male", n = { x = 375 }, c = { x = { { 0.00, "Сейчас уже очевидно, что мы не можем быть уверены, что Чернохлыст и Гематус заключены в Летлоре надёжно." }, { 7.07, "Там обосновались чёрные драконы, кроме того, этим ограм удалось завладеть знаком Земли – а это значит, что требуются куда более серьёзные меры." }, { 17.00, "Драконье узилище заперто тремя рунными камнями, которые можно заполучить только с помощью знака Земли." }, { 24.20, "Камни нужны, чтобы сломать печать на узилище." }, { 27.42, "Сломай печать и сделай так, чтобы драконы упокоились навек." } } }, t = { d = 10.0, v = "bloodelf-male", n = { x = 120 }, c = { x = { { 0.00, "Кирин Тор больше не будет беспокоиться по поводу грозных пленников Летлора." }, { 5.26, "Я сообщу об этом своему господину." }, { 7.70, "Красус, несомненно, будет доволен." } } } } },
    [718] = { d = 30.1, g = 1, v = "dwarf-male", n = { m = 310, f = 312 }, c = { m = { { 0.00, "В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами." }, { 6.52, "Местные огры из лагеря Кош набросились на них, как стервятники на падаль." }, { 11.79, "Хотя воняют огры не лучше... чем падаль, я имею в виду." }, { 15.94, "В общем, они растащили все наши обозы с оружием и прочим скарбом и..." }, { 21.07, "Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды..." }, { 27.39, "Не мог бы ты нам помочь?" } }, f = { { 0.00, "В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами." }, { 6.72, "Местные огры из лагеря Кош набросились на них, как стервятники на падаль." }, { 12.16, "Хотя воняют огры не лучше... чем падаль, я имею в виду." }, { 16.44, "В общем, они растащили все наши обозы с оружием и прочим скарбом и..." }, { 21.74, "Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды..." }, { 28.26, "Не могла бы ты нам помочь?" } } }, t = { d = 11.1, v = "dwarf-male", n = { x = 102 }, c = { x = { { 0.00, "О, благодарю тебя!" }, { 1.62, "Мы тут, надо сказать, уж было песок есть подумывали." }, { 6.10, "Ну да это дело прошлое." }, { 8.19, "Сегодня будем пировать, как короли!" } } } } },
    [719] = { d = 30.3, g = 1, v = "dwarf-male", n = { m = 339, f = 339 }, c = { m = { { 0.00, "Будь осторожен!" }, { 1.11, "Повсюду шныряют дворфы Чёрного Железа – видимо, из клана Кузни Теней." }, { 6.22, "Они только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа." }, { 13.23, "Я едва ноги унёс." }, { 14.54, "Раскоп прямо к северу отсюда." }, { 16.77, "Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку." }, { 23.52, "Как думаешь – сумеешь помочь?" }, { 25.68, "Наверняка кто-нибудь из этих гадов Чёрного Железа спёр мою кирку!" } }, f = { { 0.00, "Будь осторожна!" }, { 1.08, "Повсюду шныряют дворфы Чёрного Железа – видимо, из клана Кузни Теней." }, { 6.03, "Они только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа." }, { 12.82, "Я едва ноги унёс." }, { 14.09, "Раскоп прямо к северу отсюда." }, { 16.24, "Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку." }, { 22.78, "Как думаешь – сумеешь помочь?" }, { 24.87, "Наверняка кто-нибудь из этих гадов Чёрного Железа спёр мою кирку!" } } }, t = { d = 7.0, g = 1, v = "dwarf-male", n = { m = 60, f = 62 }, c = { m = { { 0.00, "Ты спас меня, герой." }, { 1.80, "Рад, что нашёлся кто-то, способный преподать Кузне Теней урок." } }, f = { { 0.00, "Ты спасла меня, героиня." }, { 2.03, "Рад, что нашёлся кто-то, способный преподать Кузне Теней урок." } } } } },
    [720] = { d = 9.0, v = "narrator", n = { x = 50 }, c = { x = { { 0.00, "Куском мела на карте нацарапаны слова." }, { 3.43, "\"Рейдол, они уводят меня в Ульдаман." }, { 6.70, "Пришли помощь!" }, { 8.03, "-Тяжелоступ\"" } } }, t = { d = 3.4, v = "dwarf-male", n = { x = 25 }, c = { x = { { 0.00, "Тяжелоступ жив?!" }, { 1.78, "Какое счастье!" } } } } },
    [721] = { d = 34.4, v = "dwarf-male", n = { x = 424 }, c = { x = { { 0.00, "Ты сможешь разыскать его?" }, { 1.75, "Ты разыщешь Тяжелоступа?" }, { 3.38, "Проклятые дворфы из Кузни Теней схватили его, чтобы выпытать, что он знает о раскопках поселения титанов." }, { 10.49, "Если это случится, весь Стальгорн будет в большой опасности!" }, { 14.53, "Дворфы Чёрного Железа уже давно разыскивают способы сотворения могущественных големов." }, { 20.31, "Конечно, такова была цель и Тяжелоступа, но это только для того, чтобы остановить Чёрное Железо!" }, { 26.76, "Возможно, они сохранят ему жизнь, пока не вытянут из него все секреты." }, { 31.53, "Поспеши, быть может, его ещё удастся спасти!" } } }, t = { d = 12.0, g = 1, v = "dwarf-male", n = { x = 100 }, c = { m = { { 0.00, "О, я так ослабел..." }, { 1.69, "Подойди ко мне, герой?" }, { 4.43, "Тебя прислал Рейдол?" }, { 6.36, "Клянусь Мурадином, парень вовсе не так туп, как кажется." } }, f = { { 0.00, "О, я так ослабел..." }, { 1.65, "Подойди ко мне, героиня?" }, { 4.47, "Тебя прислал Рейдол?" }, { 6.35, "Клянусь Мурадином, парень вовсе не так туп, как кажется." } } } } },
    [722] = { d = 37.2, g = 1, v = "dwarf-male", n = { m = 362, f = 363 }, c = { m = { { 0.00, "Тебе не занимать смелости, раз ты явился за мной в Ульдаман, герой." }, { 5.17, "Если в самом деле хочешь помочь старику Тяжелоступу..." }, { 9.50, "..." }, { 10.41, "Найди мне мой амулет." }, { 12.09, "Это Чернотень..." }, { 13.41, "Его забрал Магреган Чернотень." }, { 15.95, "Он здесь, в развалинах, я знаю..." }, { 18.47, "Этот амулет приведёт их..." }, { 20.49, "прямо к свиткам, если их не остановить..." }, { 24.33, "Всё в твоих руках!" }, { 25.80, "Пожалуйста... верни амулет." }, { 27.97, "Если свитки попадут к ним в лапы, Чёрное Железо сможет создавать ещё более мощных големов." }, { 35.02, "Я знаю, я это нутром чую!" } }, f = { { 0.00, "Тебе не занимать смелости, раз ты явилась за мной в Ульдаман, героиня." }, { 5.37, "Если в самом деле хочешь помочь старику Тяжелоступу..." }, { 9.70, "..." }, { 10.61, "Найди мне мой амулет." }, { 12.28, "Это Чернотень..." }, { 13.61, "Его забрал Магреган Чернотень." }, { 16.18, "Он здесь, в развалинах, я знаю..." }, { 18.69, "Этот амулет приведёт их..." }, { 20.71, "прямо к свиткам, если их не остановить..." }, { 24.55, "Всё в твоих руках!" }, { 26.02, "Пожалуйста... верни амулет." }, { 28.18, "Если свитки попадут к ним в лапы, Чёрное Железо сможет создавать ещё более мощных големов." }, { 35.23, "Я знаю, я это нутром чую!" } } }, t = { d = 7.7, v = "dwarf-male", n = { x = 36 }, c = { x = { { 0.00, "Ха!" }, { 0.38, "Я знал, что ты справишься!" }, { 3.89, "Отличная работа." } } } } },
    [723] = { d = 22.6, v = "dwarf-male", n = { x = 178 }, c = { x = { { 0.00, "Найди Рейдола!" }, { 2.52, "Передай ему мой амулет..." }, { 4.66, "Он знает, что делать." }, { 7.10, "Он знает, я искал истоки происхождения нашего народа," }, { 12.21, "знает и то, что целью моей жизни было остановить клан Кузни Теней." }, { 18.43, "Нельзя позволить, чтобы они нашли свитки..." } } }, t = { d = 16.4, v = "dwarf-male", n = { x = 173 }, c = { x = { { 0.00, "Амулет Тяжелоступа!" }, { 1.50, "Если раньше в моём сердце ещё теплилась надежда, что он жив, то теперь ничто не снимет с моей души этот камень." }, { 9.94, "Этот амулет – дело всей его жизни." }, { 12.67, "Нельзя допустить, чтобы его смерть была напрасной!" } } } } },
    [724] = { d = 24.6, v = "dwarf-male", n = { x = 282 }, c = { x = { { 0.00, "К кому же обратиться за советом..." }, { 2.41, "Историк Карник!" }, { 3.56, "Конечно!" }, { 4.19, "Он сейчас в Стальгорне – он точно сможет помочь!" }, { 7.63, "Он искал потерянные артефакты вместе с Тяжелоступом в Ульдамане." }, { 12.14, "Полагаю, в Кузне Теней прознали, что эти двое располагают тайными сведениями." }, { 17.67, "Сообщи Карнику о том, как погиб Тяжелоступ, и передай ему амулет – а он расскажет, что делать дальше." } } }, t = { d = 24.1, g = 1, v = "dwarf-male", n = { m = 258, f = 259 }, c = { m = { { 0.00, "О, а вот это совсем другой разговор!" }, { 2.76, "Возможно, ты ещё не осознал всей серьёзности происходящего, ведь так?" }, { 7.66, "Смерть Тяжелоступа глубоко меня печалит, но раз он отправил тебя сюда со своим амулетом, значит, понимал, что поставлено на карту." }, { 17.34, "Мы оплачем Тяжелоступа позже." }, { 19.56, "Сейчас я объясню тебе, почему этот амулет так важен." } }, f = { { 0.00, "О, а вот это совсем другой разговор!" }, { 2.82, "Возможно, ты ещё не осознала всей серьёзности происходящего, ведь так?" }, { 7.92, "Смерть Тяжелоступа глубоко меня печалит, но раз он отправил тебя сюда со своим амулетом, значит, понимал, что поставлено на карту." }, { 17.83, "Мы оплачем Тяжелоступа позже." }, { 20.10, "Сейчас я объясню тебе, почему этот амулет так важен." } } } } },
    [725] = { d = 25.6, g = 1, v = "dwarf-male", n = { m = 301, f = 302 }, c = { m = { { 0.00, "Беги, найди советника Белграма как можно скорее." }, { 3.44, "Расскажи ему, что видел, и спроси, что нам делать дальше." }, { 7.44, "Отдашь ему эту записку, я изложил в ней всё как можно подробней." }, { 11.93, "А я пока побеседую с духом Тяжелоступа." }, { 14.68, "Возможно, ему известно нечто, что сможет помочь нам пресечь безумные действия прихвостней Кузни Теней в Бесплодных землях." }, { 23.24, "Теперь нам остаётся только молиться." } }, f = { { 0.00, "Беги, найди советника Белграма как можно скорее." }, { 3.37, "Расскажи ему, что видела, и спроси, что нам делать дальше." }, { 7.36, "Отдашь ему эту записку, я изложил в ней всё как можно подробней." }, { 11.78, "А я пока побеседую с духом Тяжелоступа." }, { 14.48, "Возможно, ему известно нечто, что сможет помочь нам пресечь безумные действия прихвостней Кузни Теней в Бесплодных землях." }, { 22.89, "Теперь нам остаётся только молиться." } } }, t = { d = 12.1, v = "dwarf-male", n = { x = 68 }, c = { x = { { 0.00, "А, весточка от историка Карника." }, { 2.75, "Прекрасно." }, { 3.67, "Для него у меня всегда найдётся минутка." }, { 7.04, "*Советник Белграм разворачивает записку и погружается в чтение.*" } } } } },
    [726] = { d = 20.6, v = "dwarf-male", n = { x = 225 }, c = { x = { { 0.00, "*Когда советник Белграм дочитывает письмо до конца, его глаза в ужасе расширяются*" }, { 6.64, "Это дурные вести..." }, { 8.16, "Пожалуйста, вернись к историку Карнику и извести его именем короля, что он должен действовать быстро и рассудительно." }, { 16.74, "Он должен остановить Кузню Теней в Бесплодных землях." } } }, t = { d = 16.1, v = "dwarf-male", n = { x = 173 }, c = { x = { { 0.00, "Ты действуешь по этому делу с поспешностью, которая сделала бы честь и королю!" }, { 5.74, "Хорошо." }, { 6.34, "Я знаю, что делать с Кузней Теней." }, { 8.95, "Их силы в Ульдамане будут рассеяны, если мы поразим их в самое сердце – ударим по крепости Ангор." } } } } },
    [727] = { d = 32.4, v = "dwarf-male", n = { x = 337 }, c = { x = { { 0.00, "Эта табличка говорит о многом." }, { 2.38, "И всё же этого недостаточно!" }, { 4.49, "Есть книга – древняя книга Йагина." }, { 7.15, "Те, от кого я бежал..." }, { 8.85, "Они хранят эту книгу, и самые мудрые из них изучают её." }, { 13.14, "Она содержит обширные знания, и в ней можно найти ключ к спасению!" }, { 18.18, "Отправляйся к Геррику Костохвату." }, { 20.70, "Ты найдёшь его в лавке в Стальгорне, в Заброшенном гроте." }, { 24.99, "Покажешь ему эту печать, и он примет тебя за своего." }, { 29.08, "Попроси у него книгу Йагина и принеси её мне." } } }, t = { d = 5.4, g = 1, v = "dwarf-male", n = { m = 42, f = 44 }, c = { m = { { 0.00, "О, рад видеть тебя, брат." }, { 2.39, "И хвала обитающим в глубинах." } }, f = { { 0.00, "О, рад видеть тебя, сестра." }, { 2.72, "И хвала обитающим в глубинах." } } } } },
    [728] = { d = 30.6, v = "dwarf-male", n = { x = 314 }, c = { x = { { 0.00, "Эта табличка говорит о многом." }, { 2.41, "И всё же этого недостаточно!" }, { 4.55, "Есть книга – древняя книга Йагина." }, { 7.23, "Те, от кого я бежал..." }, { 8.95, "Они хранят эту книгу, и самые мудрые из них изучают её." }, { 13.29, "Она содержит обширные знания, и в ней можно найти ключ к спасению!" }, { 18.39, "Отправляйся к хранителю Бел'дугуру в Подгород, что в Лордероне." }, { 23.14, "Покажешь ему эту печать, и он примет тебя за своего." }, { 27.28, "Попроси у него книгу Йагина и принеси её мне." } } }, t = { d = 21.9, g = 1, v = "scourge-male", n = { m = 182, f = 182 }, c = { m = { { 0.00, "Не выставляй напоказ наши знаки, герой." }, { 3.76, "Многие на этом свете сомневаются в праведности наших дел." }, { 9.10, "И многие из них сделали бы всё возможное, чтобы уничтожить нас!" }, { 14.86, "Ты должен всегда сохранять бдительность, осторожность и терпение..." } }, f = { { 0.00, "Не выставляй напоказ наши знаки, героиня." }, { 4.09, "Многие на этом свете сомневаются в праведности наших дел." }, { 9.65, "И многие из них сделали бы всё возможное, чтобы уничтожить нас!" }, { 15.65, "Ты должна всегда сохранять бдительность, осторожность и терпение..." } } } } },
    [729] = { d = 40.3, v = "dwarf-female#33", n = { x = 447 }, c = { x = { { 0.00, "Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера." }, { 9.10, "В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера." }, { 14.31, "Но геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего." }, { 20.07, "Мы обнаружили признаки некогда крупного поселения." }, { 23.81, "Из-под земли выскочили ужасные големы и заполонили весь раскоп." }, { 28.56, "Но Сомнамбулер, казалось, так ничего и не заметил." }, { 32.24, "Я побежала обратно в Аубердин за помощью." }, { 35.32, "Прошу тебя, отправляйся на юг и посмотри, всё ли в порядке с геологом!" } } }, t = { d = 35.7, g = 1, v = "dwarf-male", n = { m = 372, f = 373 }, c = { m = { { 0.00, "Это ты, Холли?" }, { 1.12, "Мне нужна помощь, надо подолбить этот камень." }, { 4.54, "Передай-ка мне мою щётку для камня – мне кажется, я тут что-то вижу." }, { 9.47, "Ой, да ты не Холли!" }, { 10.85, "Вряд ли ты видел мою щётку для камня..." }, { 13.67, "А, забудь об этом!" }, { 15.05, "Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашёл." }, { 20.11, "Куда же делась Холли?" }, { 21.76, "Так много нужно сделать!" }, { 23.60, "И где ж эта таинственная окаменелость... и моя щётка... и Холли..." }, { 28.33, "И ты кто будешь... правда, это неважно, если ты хочешь помочь." }, { 32.93, "Дай знать, когда сможешь начать поиски." } }, f = { { 0.00, "Это ты, Холли?" }, { 1.10, "Мне нужна помощь, надо подолбить этот камень." }, { 4.45, "Передай-ка мне мою щётку для камня – мне кажется, я тут что-то вижу." }, { 9.28, "Ой, да ты не Холли!" }, { 10.63, "Вряд ли ты видела мою щётку для камня..." }, { 13.47, "А, забудь об этом!" }, { 14.82, "Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашёл." }, { 19.78, "Куда же делась Холли?" }, { 21.39, "Так много нужно сделать!" }, { 23.20, "И где ж эта таинственная окаменелость... и моя 