    [730] = { d = 35.8, g = 1, v = "dwarf-male", n = { m = 420, f = 422 }, c = { m = { { 0.00, "Как приятно видеть героя, который интересуется великими археологическими чудесами нашего мира!" }, { 6.61, "Часто наши друзья из Альянса считают нашу работу чем-то вроде развлечения." }, { 11.96, "Но многие не понимают, что недавние открытия в Каз Модане доказали: великая и могущественная сила угрожает всему Азероту – от Лордерона до Калимдора." }, { 22.28, "Меня очень беспокоит судьба группы, которую я отправил на Тёмные берега." }, { 27.38, "От них уже несколько недель ни слова." }, { 30.02, "Отправляйся в Аубердин и узнай, где они предположительно могут находиться." } }, f = { { 0.00, "Как приятно видеть героиню, которая интересуется великими археологическими чудесами нашего мира!" }, { 6.85, "Часто наши друзья из Альянса считают нашу работу чем-то вроде развлечения." }, { 12.29, "Но многие не понимают, что недавние открытия в Каз Модане доказали: великая и могущественная сила угрожает всему Азероту – от Лордерона до Калимдора." }, { 22.78, "Меня очень беспокоит судьба группы, которую я отправил на Тёмные берега." }, { 27.97, "От них уже несколько недель ни слова." }, { 30.66, "Отправляйся в Аубердин и узнай, где они предположительно могут находиться." } } }, t = { d = 4.2, v = "dwarf-female#33", n = { x = 46 }, c = { x = { { 0.00, "Как же здорово, что главный археолог Седоус прислал вас..." } } } } },
    [731] = { d = 33.3, g = 1, v = "dwarf-male", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Итак, Холли..." }, { 1.11, "А, да, верно, ты же не Холли." }, { 3.21, "А где Холли?" }, { 4.12, "Ай, ладно, это к делу не относится." }, { 6.74, "Мы должны найти эту щётку для камня... то есть я имею в виду таинственную окаменелость!" }, { 13.03, "Мы должны найти эту окаменелость." }, { 15.51, "Лига исследователей в Дарнассе захочет узнать, чем я тут занимаюсь." }, { 20.36, "Дай мне знать, когда будешь готов, и начнём поиски этой щётки... ну, то есть окаменелости!" }, { 26.71, "Мы найдём какой-нибудь документ, чтобы в Лиге остались довольны." }, { 31.35, "Так что, готов?" } }, f = { { 0.00, "Итак, Холли..." }, { 1.14, "А, да, верно, ты же не Холли." }, { 3.29, "А где Холли?" }, { 4.23, "Ай, ладно, это к делу не относится." }, { 6.91, "Мы должны найти эту щётку для камня... то есть я имею в виду таинственную окаменелость!" }, { 13.36, "Мы должны найти эту окаменелость." }, { 15.91, "Лига исследователей в Дарнассе захочет узнать, чем я тут занимаюсь." }, { 20.88, "Дай мне знать, когда будешь готова, и начнём поиски этой щётки... ну, то есть окаменелости!" }, { 27.45, "Мы найдём какой-нибудь документ, чтобы в Лиге остались довольны." }, { 32.22, "Так что, готова?" } } }, t = { d = 13.6, v = "dwarf-female#33", n = { x = 146 }, c = { x = { { 0.00, "Слава звёздам, геолог Сомнамбулер в безопасности!" }, { 3.75, "Я же говорила тебе, какой он рассеянный." }, { 6.87, "Не могу поверить, что он твёрдо хочет остаться там, где рядом повсюду рыщут жуткие твари!" } } } } },
    [732] = { d = 33.2, g = 1, v = "bloodelf-male", n = { m = 400, f = 401 }, c = { m = { { 0.00, "Сигрун сказал, что ты оказал ему неоценимую помощь." }, { 3.51, "Возможно, мне она тоже понадобится." }, { 5.94, "Меня прислал сюда мой господин, Красус из Кирин Тора, чтобы прекратить беспорядки в низине Летлор." }, { 12.66, "Я не имею права разглашать поставленные передо мной задачи, но можешь не сомневаться – они имеют самое первостепенное значение." }, { 21.21, "Шайка бродячих огров, которых видели близ лагеря Бофф, украла предмет, именуемый знаком Земли." }, { 27.63, "Мне необходимо вернуть этот предмет." }, { 30.11, "Принеси его мне, и я расскажу тебе больше." } }, f = { { 0.00, "Сигрун сказал, что ты оказала ему неоценимую помощь." }, { 3.60, "Возможно, мне она тоже понадобится." }, { 6.05, "Меня прислал сюда мой господин, Красус из Кирин Тора, чтобы прекратить беспорядки в низине Летлор." }, { 12.82, "Я не имею права разглашать поставленные передо мной задачи, но можешь не сомневаться – они имеют самое первостепенное значение." }, { 21.43, "Шайка бродячих огров, которых видели близ лагеря Бофф, украла предмет, именуемый знаком Земли." }, { 27.91, "Мне необходимо вернуть этот предмет." }, { 30.41, "Принеси его мне, и я расскажу тебе больше." } } }, t = { d = 15.9, g = 1, v = "bloodelf-male", n = { m = 181, f = 183 }, c = { m = { { 0.00, "Ты принёс знак, – это очень хорошая весть!" }, { 3.07, "Знак Земли был создан дворфами Чёрного Железа из Крепости Ангор, чтобы заключить в узилище двух беспощадных драконов-помощников Смертокрыла – близнецов Чернохлыста и Гематуса." } }, f = { { 0.00, "Ты принесла знак, – это очень хорошая весть!" }, { 3.27, "Знак Земли был создан дворфами Чёрного Железа из Крепости Ангор, чтобы заключить в узилище двух беспощадных драконов-помощников Смертокрыла – близнецов Чернохлыста и Гематуса." } } } } },
    [733] = { d = 35.3, v = "dwarf-male", n = { x = 415 }, c = { x = { { 0.00, "Да, туго нам придётся, если мы не сможем раздобыть материалов для возведения простейших укреплений и других нужд." }, { 7.81, "Заметил я, что у огров в этих землях полно металлолома." }, { 11.74, "Возможно, легенды об осадных машинах, применявшихся в Бесплодных землях, не так уж далеки от истины..." }, { 18.85, "В общем, проспектор очень беспокоится за состояние нашего маленького лагеря, так что надо приниматься за работу как можно скорее." }, { 27.93, "Главный лагерь огров расположен рядом с Гротом Гнилобрюхих, к западу отсюда." }, { 33.39, "Учти – расстояние приличное!" } } }, t = { d = 11.0, v = "dwarf-male", n = { x = 116 }, c = { x = { { 0.00, "Спасибо!" }, { 0.70, "Думаю, это поможет нам дотянуть до распоряжения из Стальгорна или Лиги Исследователей." }, { 7.46, "Эх, добыть бы теперь соли для закалки оружия..." } } } } },
    [734] = { d = 11.0, v = "gnome-male", n = { x = 108 }, c = { x = { { 0.00, "Прекрасно, прекрасно..." }, { 2.80, "*Лотвил на секунду отрывает взгляд от кандалов*" }, { 6.16, "Сбегай-ка к Люсьену." }, { 7.72, "Мне нужен зубец номер пять." }, { 9.82, "Принеси его мне." } } }, t = { d = 5.1, v = "gnome-male", n = { x = 41 }, c = { x = { { 0.00, "Зубец номер пять, значит?" }, { 2.47, "Да, добром это не кончится..." } } } } },
    [735] = { d = 26.5, v = "dwarf-male", n = { x = 288 }, c = { x = { { 0.00, "Книга Йагина, да?" }, { 1.33, "Вы хотите написать в ней новую главу о нас?" }, { 4.52, "Ну да, не мне спрашивать." }, { 6.31, "Я помогу вам – у меня как раз есть дополнительный экземпляр." }, { 10.62, "Мы ведь должны друг другу помогать, не так ли?" }, { 13.94, "Только так мы добьёмся успеха." }, { 16.14, "Мне нужны три предмета силы." }, { 18.26, "Принесите их мне – и получите книгу." }, { 20.92, "Названий предметов я вам не скажу – нас могут подслушивать." }, { 25.23, "Но я их вам напишу." } } }, t = { d = 11.1, g = 1, v = "dwarf-male", n = { x = 109 }, c = { m = { { 0.00, "На вас можно положиться, герой." }, { 2.48, "Воистину, вам предстоит вписать новую главу в книгу нашего ордена, и я уверен, что это будут славные страницы." } }, f = { { 0.00, "На вас можно положиться, героиня." }, { 2.59, "Воистину, вам предстоит вписать новую главу в книгу нашего ордена, и я уверен, что это будут славные страницы." } } } } },
    [736] = { d = 36.0, g = 1, v = "scourge-male", n = { m = 317, f = 320 }, c = { m = { { 0.00, "Тебе нужна книга Йагина?" }, { 2.26, "Планируешь собрать своё стадо?" }, { 4.92, "Ну, разумеется... и я с удовольствием помогу тебе, брат." }, { 9.68, "Взамен я также попрошу тебя о помощи." }, { 13.03, "Мне нужны три предмета силы." }, { 15.53, "Принеси их – и книга будет твоей." }, { 18.49, "Назвать вслух эти предметы я не могу, но запишу их." }, { 22.94, "Добудь мне всё, что я укажу в списке." }, { 26.14, "Если справишься с этим, значит, ты действительно достоин начать новую главу в истории нашего ордена." } }, f = { { 0.00, "Тебе нужна книга Йагина?" }, { 2.31, "Планируешь собрать своё стадо?" }, { 5.03, "Ну, разумеется... и я с удовольствием помогу тебе, сестра." }, { 10.14, "Взамен я также попрошу тебя о помощи." }, { 13.57, "Мне нужны три предмета силы." }, { 16.12, "Принеси их – и книга будет твоей." }, { 19.16, "Назвать вслух эти предметы я не могу, но запишу их." }, { 23.71, "Добудь мне всё, что я укажу в списке." }, { 26.98, "Если справишься с этим, значит, ты действительно достойна начать новую главу в истории нашего ордена." } } }, t = { d = 13.7, g = 1, v = "scourge-male", n = { m = 115, f = 117 }, c = { m = { { 0.00, "Поразительно!" }, { 1.29, "Ты обладаешь или великим искусством, или удачей, иначе тебе не удалось бы добыть эти реликвии." }, { 10.49, "Так или иначе, ты очень помог нам." } }, f = { { 0.00, "Поразительно!" }, { 1.27, "Ты обладаешь или великим искусством, или удачей, иначе тебе не удалось бы добыть эти реликвии." }, { 10.30, "Так или иначе, ты очень помогла нам." } } } } },
    [737] = { d = 15.8, v = "dwarf-male", n = { x = 160 }, c = { x = { { 0.00, "У меня есть для тебя книга." }, { 2.23, "Думаю, не стоит говорить, что с ней нужно обращаться очень бережно." }, { 7.64, "И непременно держать подальше от рук врагов." }, { 11.17, "В этой книге содержится много секретов..." }, { 14.55, "Опасных секретов!" } } }, npc = { [2934] = { d = 19.4, v = "scourge-male", n = { x = 160 }, c = { x = { { 0.00, "У меня есть для тебя книга." }, { 2.74, "Думаю, не стоит говорить, что с ней нужно обращаться очень бережно." }, { 9.36, "И непременно держать подальше от рук врагов." }, { 13.69, "В этой книге содержится много секретов..." }, { 17.84, "Опасных секретов!" } } } } }, t = { d = 28.4, v = "dwarf-male", n = { x = 302 }, c = { x = { { 0.00, "Вот она!" }, { 0.68, "О, проблеск надежды!" }, { 2.23, "Быть может, твои труды принесли нам спасение!" }, { 5.68, "Тебе нужно поставить памятник!" }, { 8.05, "Воздвигнуть святилище!" }, { 9.74, "Славить твоё имя в сказаниях, пока у детей твоих детей не родятся правнуки!" }, { 15.49, "Если только..." }, { 16.64, "Если только ОНИ ещё не вырвались на свободу." }, { 20.02, "Потому что если это случится, можешь забыть о детях." }, { 24.08, "Если ОНИ вырвались на свободу, мы все пойдём на корм червям." } } } } },
    [738] = { d = 21.1, v = "dwarf-male", n = { x = 237 }, c = { x = { { 0.00, "Проспектор Эгмонд вёл раскопки в Бесплодных землях, на юго-западе." }, { 4.73, "Я говорю \"вёл\", потому что, к несчастью, от него нет вестей уже не одну неделю." }, { 10.34, "Его нужно найти." }, { 11.62, "В последний раз его видели на самом южном раскопе Бесплодных земель – он расположен за Крепостью Ангор." }, { 18.97, "Думаю, стоит начать поиски там." } } }, t = { d = 7.0, v = "narrator", n = { x = 70 }, c = { x = { { 0.00, "Должно быть, этот скелет принадлежит Эгмонду." }, { 3.86, "Его кости изломаны и выбелены солнцем." } } } } },
    [739] = { d = 19.5, v = "narrator", n = { x = 178 }, c = { x = { { 0.00, "Следы Эгмонда тянутся с запада." }, { 2.86, "Судя по кровавым следам на камнях и песке, дворф полз на коленях." }, { 8.57, "И здесь он умер." }, { 10.00, "Под правой рукой мертвеца еле виднеется слово, нацарапанное на куске песчаника." }, { 17.06, "\"Мурдалок,\" – гласит надпись." } } }, t = { d = 11.1, v = "dwarf-male", n = { x = 117 }, c = { x = { { 0.00, "Это горькая весть!" }, { 1.49, "Он был силён и славно управлялся с молотом." }, { 4.82, "Не сомневаюсь, прежде чем он пал от лап троггов, он уничтожил не одну мерзкую тварь." } } } } },
    [741] = { d = 15.7, v = "dwarf-female#33", n = { x = 188 }, c = { x = { { 0.00, "Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнасс?" }, { 6.24, "Мне не хотелось бы уезжать с Тёмных берегов без него." }, { 9.97, "Вот, отвезите эту таинственную окаменелость главному археологу Седоусу в Дарнасс." } } }, t = { d = 5.2, v = "dwarf-male", n = { x = 50 }, c = { x = { { 0.00, "Ух ты!" }, { 0.56, "Только геолог Сомнамбулер мог сделать такое открытие!" } } } } },
    [742] = { d = 35.4, v = "tauren-male", n = { x = 333 }, c = { x = { { 0.00, "Внимание, молодые герои!" }, { 2.21, "Вас ждут дикие чащи Ясеневого леса!" }, { 5.36, "Орде удалось закрепиться в землях к северу от Степей." }, { 10.08, "И два наших форпоста – застава Расщеплённого Древа и застава Зорамского взморья – бьются во славу Орды!" }, { 19.06, "Те, кто жаждет подвигов, могут отправиться туда." }, { 23.31, "Запомните: Сенани Громосерд находится на заставе Расщеплённого Древа, к северу от Степей." }, { 31.03, "Она ждёт желающих принять участие в большой охоте!" } } }, t = { d = 30.9, g = 1, v = "tauren-female", n = { m = 307, f = 306 }, c = { m = { { 0.00, "Добро пожаловать на новое пограничье." }, { 3.07, "Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя." }, { 11.46, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 19.13, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 24.24, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } }, f = { { 0.00, "Добро пожаловать на новое пограничье." }, { 3.05, "Ясеневый лес – край неограниченных возможностей, где юной героине вроде тебя выпадает шанс показать себя." }, { 11.48, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 19.10, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 24.19, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } } } } },
    [743] = { d = 33.4, g = 1, v = "tauren-male", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Спасибо, что выбрал время поговорить со мной." }, { 4.01, "Я Руул, воин и учитель." }, { 6.18, "Пришло время пройти испытания и покинуть Мулгор." }, { 10.59, "Если ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке." }, { 19.57, "Они гнездятся вдоль гребня гор в стороне от дороги." }, { 24.14, "Эти гарпии – вечные враги тауренов Мулгора." }, { 28.15, "По схватке с ними мы будем судить о твоей силе." } }, f = { { 0.00, "Спасибо, что выбрала время поговорить со мной." }, { 4.21, "Я Руул, воин и учитель." }, { 6.44, "Пришло время пройти испытания и покинуть Мулгор." }, { 10.98, "Если ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке." }, { 20.23, "Они гнездятся вдоль гребня гор в стороне от дороги." }, { 24.94, "Эти гарпии – вечные враги тауренов Мулгора." }, { 29.06, "По схватке с ними мы будем судить о твоей силе." } } }, t = { d = 6.7, g = 1, v = "tauren-male", n = { m = 53, f = 54 }, c = { m = { { 0.00, "Молодец." }, { 0.89, "Похоже, ты готов двинуться дальше." }, { 4.35, "Попутного тебе ветра!" } }, f = { { 0.00, "Молодец." }, { 0.92, "Похоже, ты готова двинуться дальше." }, { 4.59, "Попутного тебе ветра!" } } } } },
    [744] = { d = 40.0, v = "tauren-male#68", n = { x = 404 }, c = { x = { { 0.00, "Вскоре мой брат предстанет перед вождём Кровавым Копытом, и мне выпала большая честь сделать для него головной убор." }, { 9.13, "Мне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски." }, { 18.04, "Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом?" }, { 25.10, "Перья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утёса." }, { 33.59, "Мне нужно всего-то шесть лазурных и шесть бронзовых перьев, чтобы закончить работу." } } }, t = { d = 11.4, v = "tauren-male#68", n = { x = 120 }, c = { x = { { 0.00, "Спасибо за помощь." }, { 1.49, "Моё участие в церемонии в честь моего брата почти закончено." }, { 6.26, "От меня требуется только подарить ему этот убор и быть свидетелем." } } } } },
    [745] = { d = 38.6, v = "creature/baine", n = { x = 381 }, c = { x = { { 0.00, "Нашей земле причиняют боль раздоры её обитателей." }, { 4.16, "Я надеюсь, что тебе не суждено видеть столько войн, сколько выпало мне." }, { 10.13, "И всё же я вынужден просить тебя вступить в бой." }, { 14.14, "Благодаря этому ты поймёшь, что малая угроза, если не искоренить её, со временем разрастается." }, { 21.93, "Гноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе." }, { 28.20, "Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора." }, { 36.06, "Слова бессильны остановить их." } } }, t = { d = 22.5, g = 1, v = "creature/baine", n = { m = 192, f = 194 }, c = { m = { { 0.00, "Хорошо, что ты отнёсся к моему заданию со всей серьёзностью." }, { 5.57, "Очень важно уважать землю и её обитателей." }, { 9.76, "Жизнь и смерть – это вечный цикл..." }, { 13.07, "Необходимость." }, { 14.46, "Одно не может существовать без другого." }, { 18.29, "Обдумай это хорошенько и никогда не забывай." } }, f = { { 0.00, "Хорошо, что ты отнеслась к моему заданию со всей серьёзностью." }, { 5.77, "Очень важно уважать землю и её обитателей." }, { 9.90, "Жизнь и смерть – это вечный цикл..." }, { 13.17, "Необходимость." }, { 14.55, "Одно не может существовать без другого." }, { 18.34, "Обдумай это хорошенько и никогда не забывай." } } } } },
    [746] = { d = 30.2, v = "creature/baine", n = { x = 288 }, c = { x = { { 0.00, "К северо-западу отсюда дворфы готовятся к раскопкам." }, { 4.56, "Они думают, что тайны скрыты глубоко в земле, и это правда, но у неё надо учиться, а не осквернять бесконечными ямами." }, { 14.77, "Собери инструменты дворфов, уничтожь их и принеси мне." }, { 19.41, "Ломать инструменты можно в кузнице, которая есть в Громовом Утёсе, но подойдёт любая, даже та, что находится в дворфийском лагере." } } }, t = { d = 13.2, v = "creature/baine", n = { x = 108 }, c = { x = { { 0.00, "Спасибо." }, { 0.87, "Звери Мулгора успокоятся." }, { 3.41, "И, если будет на то воля духов, дворфы познают, что бурение земли – не лучший путь к обретению знаний." } } } } },
    [747] = { d = 49.3, g = 1, v = "tauren-male", n = { m = 471, f = 472 }, c = { m = { { 0.00, "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем." }, { 8.95, "Возможно, вскоре тебя позовут в Громовой Утёс." }, { 13.00, "Но прежде чем это случится, тебе придётся доказать моему отцу, вождю Соколиному Ветру, что ты достоин этой чести." }, { 22.89, "На плато Красного Облака предметом особой гордости является охотничье мастерство." }, { 29.97, "Таурены охотятся ради выживания и для забавы." }, { 33.94, "Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды." }, { 41.73, "Покажи, на что ты способен, – поохоться на равнинных долгоногов и принеси мяса в деревню." } }, f = { { 0.00, "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем." }, { 8.72, "Возможно, вскоре тебя позовут в Громовой Утёс." }, { 12.67, "Но прежде чем это случится, тебе придётся доказать моему отцу, вождю Соколиному Ветру, что ты достойна этой чести." }, { 22.37, "На плато Красного Облака предметом особой гордости является охотничье мастерство." }, { 29.28, "Таурены охотятся ради выживания и для забавы." }, { 33.14, "Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды." }, { 40.73, "Покажи, на что ты способна, – поохоться на равнинных долгоногов и принеси мяса в деревню." } } }, t = { d = 7.0, v = "tauren-male", n = { x = 58 }, c = { x = { { 0.00, "Таурены Нараче благодарят тебя." }, { 3.29, "Я уверен, ты достигнешь больших высот." } } } } },
    [748] = { d = 28.3, v = "tauren-male#68", n = { x = 276 }, c = { x = { { 0.00, "Гоблины и их прислужники отравили наши священные колодцы!" }, { 4.94, "Это недопустимо." }, { 6.40, "Для очищения колодцев придётся создать тотемы, а ты пойдёшь с ними к колодцам и проведёшь очищающие ритуалы." }, { 15.43, "Начнём мы с колодца Заиндевевшего Копыта." }, { 18.91, "Земля сама поможет нам." }, { 20.99, "Принеси мне лапы койотов и когти взрослых долгоногов." }, { 25.62, "Эти звери живут на юго-западе." } } }, t = { d = 6.6, v = "tauren-male#68", n = { x = 53 }, c = { x = { { 0.00, "Молодец." }, { 0.94, "Я вплету силу принесённых тобой вещей в тотем Очищения." } } } } },
    [749] = { d = 38.5, v = "tauren-male", n = { x = 391 }, c = { x = { { 0.00, "Несколько дней назад мы наткнулись на охраняемый караван Торговой компании, следовавший вдоль северного берега озера Каменного Быка." }, { 10.87, "В предыдущей битве мы потеряли двоих, поэтому на сей раз мы напали без промедления и уничтожили караван." }, { 19.35, "Мы бросили их ящики с припасами, полагая, что наши факелы уничтожат всё ценное, но учитывая, что возле сожжённых телег видели мародёров Торговой компании, похоже, мы ошиблись." }, { 33.65, "Быть может, ты сходишь к каравану и посмотришь, что в ящиках?" } } }, t = { d = 13.4, v = "narrator", n = { x = 155 }, c = { x = { { 0.00, "Все стороны ящика опечатаны знаками рудникового отдела Торговой Компании." }, { 5.57, "Сбоку прикреплены пометки, что содержимое должно быть обработано на одном из центральных заводов компании." } } } } },
    [750] = { d = 29.7, v = "tauren-male", n = { x = 294 }, c = { x = { { 0.00, "Любой искушённый в охоте таурен понимает, что её смысл не заключается в убийстве любой подвернувшейся добычи." }, { 9.17, "Живущие на равнине звери обеспечивают нас всем необходимым для выживания." }, { 15.34, "Ты произведёшь впечатление на старейшин, если принесёшь им несколько шкур горных пум – они у нас очень высоко ценятся!" }, { 25.21, "Нашим детям нужна одежда, да и шатры пора подлатать." } } }, t = { d = 10.2, v = "tauren-male", n = { x = 94 }, c = { x = { { 0.00, "Таурены из Нараче благодарят тебя за твои дары." }, { 4.15, "Твоё охотничье искусство будет высоко цениться в Громовом Утёсе." } } } } },
    [751] = { d = 20.7, v = "narrator", n = { x = 225 }, c = { x = { { 0.00, "Приоткрыв крышку, вы видите плотно упакованную руду и минералы – новое свидетельство деятельности Торговой компании в Мулгоре." }, { 9.80, "Поверх руды и минералов лежит пачка бумаг." }, { 13.24, "Со стороны восточных предгорий доносятся звуки работы и к небу поднимается дым от больших костров." } } }, t = { d = 12.6, v = "tauren-male", n = { x = 123 }, c = { x = { { 0.00, "Похоже, Торговая Компания в самом деле замыслила лишить нас всех природных ресурсов." }, { 7.34, "Хорошо знать это наверняка, пожалуй, пришло время действовать." } } } } },
    [752] = { d = 25.6, v = "tauren-male#67", n = { x = 250 }, c = { x = { { 0.00, "Все члены племени живут вместе в мире и гармонии." }, { 4.19, "Мы преданы друг другу и отвечаем друг за друга." }, { 8.09, "Я обращаюсь к тебе со скромной просьбой." }, { 11.45, "Моя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче." }, { 17.97, "С тех пор прошло довольно много времени." }, { 21.34, "Не поищешь ли ты её, пока я занимаюсь делами племени?" } } }, t = { d = 17.3, g = 1, v = "tauren-female", n = { m = 165, f = 166 }, c = { m = { { 0.00, "Ты проделал такой путь, только чтобы оказать услугу старушке?" }, { 5.09, "Да, похоже, ты чтишь традиции нашего народа." }, { 8.70, "Вот, возьми себе одно из этих учебных пособий – из него ты узнаешь, как ещё можно помочь сообществу." } }, f = { { 0.00, "Ты проделала такой путь, только чтобы оказать услугу старушке?" }, { 5.61, "Да, похоже, ты чтишь традиции нашего народа." }, { 9.22, "Вот, возьми себе одно из этих учебных пособий – из него ты узнаешь, как ещё можно помочь сообществу." } } } } },
    [753] = { d = 31.8, g = 1, v = "tauren-female", n = { m = 302, f = 302 }, c = { m = { { 0.00, "В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше." }, { 7.27, "Я ещё могу принести пользу своему племени – просто иногда мне требуется чуть больше времени." }, { 14.98, "Думаю, ты достойный герой." }, { 17.23, "Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче." }, { 23.97, "Помни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин." } }, f = { { 0.00, "В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше." }, { 7.00, "Я ещё могу принести пользу своему племени – просто иногда мне требуется чуть больше времени." }, { 14.43, "Думаю, ты достойная героиня." }, { 16.73, "Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче." }, { 23.23, "Помни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин." } } }, t = { d = 20.6, g = 1, v = "tauren-male#67", n = { m = 212, f = 214 }, c = { m = { { 0.00, "Ты принёс мне этот кувшин по просьбе Великой матери Соколиный Ветер." }, { 5.45, "Твоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придёт день, когда мы будем гордиться тобой в Громовом Утёсе." } }, f = { { 0.00, "Ты принесла мне этот кувшин по просьбе Великой матери Соколиный Ветер." }, { 5.80, "Твоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придёт день, когда мы будем гордиться тобой в Громовом Утёсе." } } } } },
    [754] = { d = 22.2, v = "tauren-male#68", n = { x = 215 }, c = { x = { { 0.00, "Я создал тотем для очищения колодца Заиндевевшего Копыта." }, { 4.86, "Отнеси его туда и произведи ритуал очищения." }, { 8.73, "Колодец находится на юго-востоке, и его охраняют мерзкие гоблины!" }, { 14.35, "Дело непростое, но кому-то придётся его сделать, иначе мы не сможем брать там воду." }, { 21.33, "Удачи тебе." } } }, t = { d = 13.2, g = 1, v = "tauren-male#68", n = { m = 119, f = 120 }, c = { m = { { 0.00, "До меня только что дошли вести о твоём деянии – звери уже спешат к колодцу на водопой." }, { 7.34, "Ты оказал большую услугу нашему краю." }, { 10.60, "И всему народу тауренов." } }, f = { { 0.00, "До меня только что дошли вести о твоём деянии – звери уже спешат к колодцу на водопой." }, { 7.67, "Ты оказала большую услугу нашему краю." }, { 11.15, "И всему народу тауренов." } } } } },
    [755] = { d = 38.1, g = 1, v = "tauren-male#67", n = { m = 343, f = 343 }, c = { m = { { 0.00, "Твоя готовность выполнить скромную просьбу таурена из Нараче и твоё желание обрести новые знания весьма похвальны." }, { 10.35, "Не сомневаюсь, придёт день, и тебя, герой, назовут одним из величайших." }, { 16.66, "Но сначала ты должен пройти три обряда Матери-Земли." }, { 21.43, "Первым испытанием будет Обряд Силы." }, { 24.74, "Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер." }, { 32.66, "Обиталище провидца сокрыто в холмах к югу от Лагеря Нараче." } }, f = { { 0.00, "Твоя готовность выполнить скромную просьбу таурена из Нараче и твоё желание обрести новые знания весьма похвальны." }, { 10.35, "Не сомневаюсь, придёт день, и тебя, героиня, назовут одной из величайших." }, { 16.82, "Но сначала ты должна пройти три обряда Матери-Земли." }, { 21.59, "Первым испытанием будет Обряд Силы." }, { 24.90, "Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер." }, { 32.82, "Обиталище провидца сокрыто в холмах к югу от Лагеря Нараче." } } }, t = { d = 8.2, v = "tauren-male#68", n = { x = 85 }, c = { x = { { 0.00, "Тебя прислал вождь Соколиный Ветер?" }, { 2.89, "Обряды Матери-Земли гораздо сложнее, чем кажутся на первый взгляд..." } } } } },
    [756] = { d = 19.9, v = "tauren-male#68", n = { x = 195 }, c = { x = { { 0.00, "Для создания Тотема очищения колодца Громового Рога тебе понадобятся когти хищников мулгорских равнин." }, { 8.91, "Придётся тебе убить несколько охотников прерий и пум плоскогорья и принести мне их когти." }, { 16.59, "Живут эти звери на востоке и на западе." } } }, t = { d = 15.7, v = "tauren-male#68", n = { x = 155 }, c = { x = { { 0.00, "Спасибо." }, { 0.76, "Чтобы создать следующий тотем, нужен предмет, в котором заключена природная чистота охотящегося зверя." }, { 9.52, "Гоблинам не понять разницу между захватом земли и жизнью в гармонии с ней." } } } } },
    [757] = { d = 40.6, g = 1, v = "tauren-male#68", n = { m = 396, f = 396 }, c = { m = { { 0.00, "Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утёса." }, { 8.65, "Сначала ты должен пройти обряд Силы." }, { 11.86, "Чтобы выдержать это испытание, ты должен доказать свою храбрость, убивая врагов племени." }, { 19.52, "Воины клана Вздыбленная Щетина из Ежевичной лощины вторгаются в земли нашего племени." }, { 26.86, "Они нападают на наших охотников и грабят деревню по ночам." }, { 31.92, "Покажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства." } }, f = { { 0.00, "Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утёса." }, { 8.61, "Сначала ты должна пройти обряд Силы." }, { 11.82, "Чтобы выдержать это испытание, ты должна доказать свою храбрость, убивая врагов племени." }, { 19.44, "Воины клана Вздыбленная Щетина из Ежевичной лощины вторгаются в земли нашего племени." }, { 26.76, "Они нападают на наших охотников и грабят деревню по ночам." }, { 31.79, "Покажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства." } } }, t = { d = 6.5, g = 1, v = "tauren-male#67", n = { m = 52, f = 52 }, c = { m = { { 0.00, "Ты прошёл первый из обрядов Матери-Земли." }, { 4.31, "Племя гордится тобой!" } }, f = { { 0.00, "Ты прошла первый из обрядов Матери-Земли." }, { 4.18, "Племя гордится тобой!" } } } } },
    [758] = { d = 17.8, v = "tauren-male#68", n = { x = 175 }, c = { x = { { 0.00, "Тотем готов." }, { 1.13, "Тебе остаётся лишь провести ритуал очищения." }, { 4.84, "Ступай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью тотема очищения." }, { 13.01, "После этого возвращайся ко мне." }, { 15.65, "И да пребудут с тобой духи." } } }, t = { d = 12.1, v = "tauren-male#68", n = { x = 120 }, c = { x = { { 0.00, "Предки клана Громового Рога явились ко мне во сне и восхваляли тебя за очищение их колодца." }, { 7.68, "Они просили передать тебе это в знак признательности…" } } } } },
    [759] = { d = 23.0, v = "tauren-male#68", n = { x = 224 }, c = { x = { { 0.00, "Тебе осталось очистить лишь один колодец, названный в честь племени Буйногривых." }, { 6.90, "Для этого тебе понадобятся зубы лютого хищника, могучего волка прерий." }, { 13.11, "Ступай на север, убей его и возвращайся." }, { 16.68, "Могучие волки прерий водятся неподалёку от славного города Громового Утёса." } } }, t = { d = 11.7, v = "tauren-male#68", n = { x = 106 }, c = { x = { { 0.00, "Замечательно." }, { 1.24, "Увы, нашей земле приходится приносить в жертву своих детей..." }, { 7.04, "Моё сердце исполнено печали и гордости одновременно." } } } } },
    [760] = { d = 27.8, g = 1, v = "tauren-male#68", n = { m = 264, f = 265 }, c = { m = { { 0.00, "Духи говорят, что ты успешно очистил колодцы Заиндевевшего Копыта и Громового Рога, юный герой." }, { 7.98, "Тотем Буйногривых готов, и ты можешь приступить к выполнению последнего задания." }, { 14.63, "Колодец Буйногривых расположен на севере от Громового Утёса." }, { 19.55, "Проведи ритуал!" }, { 20.89, "Избавь нашу землю от гоблинского яда!" }, { 24.10, "Пусть вода вновь станет чистой." } }, f = { { 0.00, "Духи говорят, что ты успешно очистила колодцы Заиндевевшего Копыта и Громового Рога, юная героиня." }, { 8.53, "Тотем Буйногривых готов, и ты можешь приступить к выполнению последнего задания." }, { 15.43, "Колодец Буйногривых расположен на севере от Громового Утёса." }, { 20.55, "Проведи ритуал!" }, { 21.95, "Избавь нашу землю от гоблинского яда!" }, { 25.28, "Пусть вода вновь станет чистой." } } }, t = { d = 17.9, g = 1, v = "tauren-male#68", n = { m = 154, f = 155 }, c = { m = { { 0.00, "Ты справился!" }, { 1.29, "Наши колодцы снова чисты, а земля исцелена." }, { 5.60, "Деревня Кровавого Копыта признательна тебе." }, { 9.82, "Пусть ветер шепчет о твоих подвигах сотни лет, а воды Мулгора остаются чистыми навек." } }, f = { { 0.00, "Ты справилась!" }, { 1.37, "Наши колодцы снова чисты, а земля исцелена." }, { 5.63, "Деревня Кровавого Копыта признательна тебе." }, { 9.81, "Пусть ветер шепчет о твоих подвигах сотни лет, а воды Мулгора остаются чистыми навек." } } } } },
    [761] = { d = 37.3, v = "tauren-male", n = { x = 336 }, c = { x = { { 0.00, "Перепелятники – хитрые птицы." }, { 2.68, "Их нелегко найти и убить." }, { 5.04, "Связка перьев перепелятника – всё равно что медаль для охотника, говорящая о его уме и решимости." }, { 13.81, "Если ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников." }, { 22.01, "Принеси мне их перья, и прославь свой клан этой победой." }, { 27.05, "Перепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта." } } }, t = { d = 12.1, g = 1, v = "tauren-male", n = { m = 100, f = 101 }, c = { m = { { 0.00, "Я знаю, набрать достаточно перьев было нелегко." }, { 4.72, "Но тем самым ты показал, на что способен." }, { 8.66, "Хорошо, что ты живёшь у нас в деревне." } }, f = { { 0.00, "Я знаю, набрать достаточно перьев было нелегко." }, { 4.69, "Но тем самым ты показала, на что способна." }, { 8.69, "Хорошо, что ты живёшь у нас в деревне." } } } } },
    [762] = { d = 32.4, v = "dwarf-male", n = { x = 400 }, c = { x = { { 0.00, "Посол Инфернус был отправлен в Крепость Ангор самим Рагнаросом, чтобы надзирать за поисками потерянных артефактов Кузней Теней в Ульдамане." }, { 9.53, "Нам и без того было непросто, а теперь я даже боюсь предположить, сколько артефактов они смогут найти и использовать против Стальгорна!" }, { 18.76, "Задача проста!" }, { 19.81, "Возвращайся в Бесплодные земли и уничтожь посла Инфернуса." }, { 23.81, "Как только ты выполнишь это задание, возвращайся к советнику Белграму с доказательством своего успеха." }, { 30.76, "Теперь всё в твоих руках!" } } }, t = { d = 23.0, v = "dwarf-male", n = { x = 279 }, c = { x = { { 0.00, "Твоя преданность Стальгорну и народу дворфов не будет забыта." }, { 4.28, "Благодарю тебя за помощь." }, { 6.07, "Я извещу историка Карника о твоих успехах письмом и отправлю рабочих в Бесплодные земли, чтобы они возобновили работы на раскопках как можно скорее." }, { 16.36, "Ещё раз благодарю тебя." }, { 17.98, "Прежде чем ты уйдёшь, выполни ещё одну просьбу от имени короля Бронзоборода." } } } } },
    [763] = { d = 41.6, g = 1, v = "tauren-male#67", n = { m = 406, f = 406 }, c = { m = { { 0.00, "Чтобы продолжить прохождение обрядов Матери-Земли, ты должен пройти ещё два испытания." }, { 7.33, "Тебе бы не помешало поднабраться опыта." }, { 10.69, "Отправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна." }, { 18.32, "Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утёса." }, { 26.11, "Отнеси этот тотем Бейну." }, { 28.32, "Он узнает мою руку в этой резьбе и поможет тебе в твоём путешествии." }, { 34.20, "Следуй по дороге из Лагеря Нараче, да поспеши." }, { 38.17, "И не уходи далеко от дороги – заблудишься!" } }, f = { { 0.00, "Чтобы продолжить прохождение обрядов Матери-Земли, ты должна пройти ещё два испытания." }, { 7.23, "Тебе бы не помешало поднабраться опыта." }, { 10.54, "Отправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна." }, { 18.07, "Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утёса." }, { 25.76, "Отнеси этот тотем Бейну." }, { 27.94, "Он узнает мою руку в этой резьбе и поможет тебе в твоём путешествии." }, { 33.74, "Следуй по дороге из Лагеря Нараче, да поспеши." }, { 37.66, "И не уходи далеко от дороги – заблудишься!" } } }, t = { d = 11.5, g = 1, v = "creature/baine", n = { x = 83 }, c = { m = { { 0.00, "О, весточка от моего старого друга, вождя Соколиного Ветра!" }, { 5.92, "Смотри-ка, он пишет мне, что ты герой особой породы!" } }, f = { { 0.00, "О, весточка от моего старого друга, вождя Соколиного Ветра!" }, { 6.17, "Смотри-ка, он пишет мне, что ты героиня особой породы!" } } } } },
    [764] = { d = 33.7, v = "tauren-male", n = { x = 325 }, c = { x = { { 0.00, "Теперь понятно, почему в Мулгоре появилось много сотрудников и оборудования Торговой компании." }, { 8.13, "Эти гоблины..." }, { 9.45, "Компания слишком быстро растёт, не жди добра." }, { 13.32, "Как говорят, гоблинам палец в рот не клади." }, { 17.03, "Маленькие жадины." }, { 18.58, "К несчастью для их деловых операций, таурены не согласны терпеть их присутствие в своих землях." }, { 26.71, "Ступай в их рудник на северо-востоке от разграбленного каравана и преподай им урок." } } }, t = { d = 16.5, v = "tauren-male", n = { x = 168 }, c = { x = { { 0.00, "Думаю, такой намёк невозможно не понять, а?" }, { 3.58, "Торговая Компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые." } } } } },
    [765] = { d = 36.3, g = 1, v = "tauren-male", n = { m = 392, f = 393 }, c = { m = { { 0.00, "Согласно документам, которые ты отыскал в караване, Торговая компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить." }, { 13.77, "Мне тошно слышать, на какую низость они готовы пойти ради достижения цели." }, { 19.65, "Я хочу уничтожить того, кто разработал эти планы." }, { 23.53, "Его зовут бригадир Шумовик, он сейчас в руднике Торговой компании на востоке от разграбленного каравана." }, { 31.56, "Принеси мне его планшет, посмотрим, нет ли в нём чего полезного." } }, f = { { 0.00, "Согласно документам, которые ты отыскала в караване, Торговая компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить." }, { 13.42, "Мне тошно слышать, на какую низость они готовы пойти ради достижения цели." }, { 19.12, "Я хочу уничтожить того, кто разработал эти планы." }, { 22.88, "Его зовут бригадир Шумовик, он сейчас в руднике Торговой компании на востоке от разграбленного каравана." }, { 30.66, "Принеси мне его планшет, посмотрим, нет ли в нём чего полезного." } } }, t = { d = 15.2, v = "tauren-male", n = { x = 159 }, c = { x = { { 0.00, "Ярость немного отступила при вести о гибели злодея Шумовика." }, { 4.90, "Я пороюсь в его личных вещах, посмотрю, нет ли там дополнительных сведений о ближайших планах Торговой Компании." }, { 13.84, "Спасибо за помощь." } } } } },
    [766] = { d = 39.7, v = "tauren-male#68", n = { x = 406 }, c = { x = { { 0.00, "Дедушка рассказывал мне истории о столкновениях с долгоногом Маззраначем." }, { 5.80, "О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах." }, { 12.48, "И вот ирония судьбы – он встретился мне во время странствий по равнинам и здорово укусил меня за плечо." }, { 20.75, "Мой дед ничуть не преувеличил, описывая это жуткое создание." }, { 25.61, "Теперь мне нужны редкие части животных, чтобы вылечить воспалённую рану: сердце койота, бедро пумы, чешуя равнинного долгонога и потроха перепелятника." }, { 37.87, "Торопись, время не ждёт." } } }, t = { d = 23.4, g = 1, v = "tauren-male#68", n = { m = 218, f = 218 }, c = { m = { { 0.00, "А, спасибо." }, { 1.01, "Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня." }, { 9.45, "Я обязан тебе жизнью." }, { 11.39, "Но пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть…" }, { 18.75, "Будь осторожен во время своих странствий." } }, f = { { 0.00, "А, спасибо." }, { 1.07, "Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня." }, { 10.00, "Я обязан тебе жизнью." }, { 12.05, "Но пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть…" }, { 19.83, "Будь осторожна во время своих странствий." } } } } },
    [767] = { d = 23.8, v = "creature/baine", n = { x = 227 }, c = { x = { { 0.00, "Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утёса." }, { 9.31, "Наш народ твёрдо усвоил, что кормящая нас земля – священна." }, { 14.45, "Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождём деревни, Зарельманом Две Луны." } } }, t = { d = 10.1, g = 1, v = "tauren-male#67", n = { x = 81 }, c = { m = { { 0.00, "Я предчувствовал, что ты придёшь ко мне, герой." }, { 4.21, "Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли." } }, f = { { 0.00, "Я предчувствовал, что ты придёшь ко мне, героиня." }, { 4.44, "Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли." } } } } },
    [768] = { d = 29.3, g = 1, v = "tauren-male", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Привет тебе, юноша." }, { 1.87, "У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться." }, { 10.71, "Да принесёшь ты честь своему клану!" }, { 13.80, "Я работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утёса." }, { 21.51, "Если принесёшь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью." } }, f = { { 0.00, "Привет тебе, девица." }, { 2.04, "У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться." }, { 11.29, "Да принесёшь ты честь своему клану!" }, { 14.51, "Я работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утёса." }, { 22.57, "Если принесёшь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью." } } }, t = { d = 9.0, v = "tauren-male", n = { x = 63 }, c = { x = { { 0.00, "Ах, какая кожа!" }, { 1.83, "Из неё выйдут отличные товары." }, { 5.28, "Вот." }, { 5.79, "Возьми в знак благодарности..." } } } } },
    [769] = { d = 22.3, v = "tauren-male", n = { x = 198 }, c = { x = { { 0.00, "Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем." }, { 6.95, "Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы." }, { 18.48, "И тогда я поделюсь с тобой своими знаниями." } } }, t = { d = 10.4, v = "tauren-male", n = { x = 92 }, c = { x = { { 0.00, "Добро." }, { 0.69, "Спасибо." }, { 1.55, "Моё сердце распирает от гордости, когда я вижу молодёжь, взыскующую мастерства в кожевничестве!" } } } } },
    [770] = { d = 18.2, v = "narrator", n = { x = 192 }, c = { x = { { 0.00, "На потрёпанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом." }, { 10.53, "Может быть, следует рассказать кому-нибудь в Деревне Кровавого Копыта о кончине Призрачного Воя..." } } }, t = { d = 34.2, g = 1, v = "tauren-male", n = { m = 291, f = 294 }, c = { m = { { 0.00, "Глазам своим стариковским не верю!" }, { 3.26, "Тебе удалось одолеть Призрачного Воя?" }, { 6.86, "Ты вырос в моих глазах, юный герой." }, { 10.30, "Оказывается, ты превосходный охотник!" }, { 13.73, "Позволь предложить тебе кое-что." }, { 16.83, "Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь моё оружие." }, { 24.36, "Пусть оно не знает промаха и дарует тебе славу." }, { 28.88, "Будем надеяться, что дух Призрачного Воя упокоился с миром." } }, f = { { 0.00, "Глазам своим стариковским не верю!" }, { 3.22, "Тебе удалось одолеть Призрачного Воя?" }, { 6.77, "Ты выросла в моих глазах, юная героиня." }, { 10.48, "Оказывается, ты превосходная охотница!" }, { 13.94, "Позволь предложить тебе кое-что." }, { 17.00, "Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь моё оружие." }, { 24.42, "Пусть оно не знает промаха и дарует тебе славу." }, { 28.88, "Будем надеяться, что дух Призрачного Воя упокоился с миром." } } } } },
    [771] = { d = 36.3, v = "tauren-male#67", n = { x = 347 }, c = { x = { { 0.00, "Чтобы пройти обряд Прозрения, тебе придётся собрать некоторые реагенты для создания воды Провидцев." }, { 8.65, "Мне понадобятся камни, которых полно вокруг источников Мулгора." }, { 14.19, "Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли." }, { 20.42, "В этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение." }, { 30.24, "Следуй за ним, и оно приведёт тебя к следующему этапу священного обряда." } } }, t = { d = 10.7, g = 1, v = "tauren-male#67", n = { m = 109, f = 110 }, c = { m = { { 0.00, "Вижу, ты научился собирать дань с нашей священной земли." }, { 4.73, "Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев." } }, f = { { 0.00, "Вижу, ты научилась собирать дань с нашей священной земли." }, { 4.70, "Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев." } } } } },
    [772] = { d = 17.1, v = "tauren-male#67", n = { x = 154 }, c = { x = { { 0.00, "Я вручаю тебе воду Провидцев." }, { 2.75, "Выпей её перед костром племени." }, { 5.65, "Когда священные воды вольются в тебя, из огня навстречу тебе шагнёт видение." }, { 12.60, "После этого следуй за ним навстречу своей судьбе..." } } }, t = { d = 5.3, g = 1, v = "tauren-male#68", n = { m = 36, f = 36 }, c = { m = { { 0.00, "Не бойся, герой." }, { 1.76, "Ты успешно прошёл Обряд прозрения." } }, f = { { 0.00, "Не бойся, героиня." }, { 1.88, "Ты успешно прошла Обряд прозрения." } } } } },
    [773] = { d = 28.2, g = 1, v = "tauren-male#68", n = { m = 263, f = 263 }, c = { m = { { 0.00, "Чтобы завоевать признание старейшин Громового Утёса, тебе следует пройти Обряд мудрости." }, { 7.85, "Ты уже прошёл Обряд прозрения, и духи Красных скал благословят тебя силой предков." }, { 15.15, "Лишь те, кто испили воды Провидцев, могут обрести это благословение." }, { 21.18, "Ступай на восток от Громового Утёса, к Красным скалам, и отыщи там дух предков." } }, f = { { 0.00, "Чтобы завоевать признание старейшин Громового Утёса, тебе следует пройти Обряд мудрости." }, { 7.90, "Ты уже прошла Обряд прозрения, и духи Красных скал благословят тебя силой предков." }, { 15.32, "Лишь те, кто испили воды Провидцев, могут обрести это благословение." }, { 21.38, "Ступай на восток от Громового Утёса, к Красным скалам, и отыщи там дух предков." } } }, t = { d = 31.2, g = 1, v = "tauren-male", n = { m = 242, f = 243 }, c = { m = { { 0.00, "Ты приложил много стараний, чтобы пройти обряды Матери-Земли." }, { 6.46, "Мы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утёс." }, { 15.96, "Итак, я передаю тебе почётную обязанность хранить его от бед." }, { 22.24, "Ты прошёл Обряд мудрости, юный герой." }, { 26.11, "Отныне ты можешь с гордостью войти в Громовой Утёс." } }, f = { { 0.00, "Ты приложила много стараний, чтобы пройти обряды Матери-Земли." }, { 6.03, "Мы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утёс." }, { 14.77, "Итак, я передаю тебе почётную обязанность хранить его от бед." }, { 20.55, "Ты прошла Обряд мудрости, юная героиня." }, { 24.37, "Отныне ты можешь с гордостью войти в Громовой Утёс." } } } } },
