    [776] = { d = 30.2, g = 1, v = "named/3057", n = { m = 273, f = 274 }, c = { m = { { 0.00, "Ты прошёл обряды Матери-Земли и заслужил достойное место среди жителей Громового Утёса." }, { 10.46, "Чтобы сохранить это таким трудом заработанное место, тебе придётся и дальше служить своему народу." }, { 18.06, "Мы охотники." }, { 19.01, "Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея." }, { 23.19, "Выследи и убей его, проявив своё искусство охотника, и принеси мне рог Арра'чеи." } }, f = { { 0.00, "Ты прошла обряды Матери-Земли и заслужила достойное место среди жителей Громового Утёса." }, { 10.93, "Чтобы сохранить это таким трудом заработанное место, тебе придётся и дальше служить своему народу." }, { 18.75, "Мы охотники." }, { 19.74, "Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея." }, { 24.04, "Выследи и убей его, проявив своё искусство охотника, и принеси мне рог Арра'чеи." } } }, t = { d = 11.5, g = 1, v = "named/3057", n = { m = 88, f = 89 }, c = { m = { { 0.00, "Отлично!" }, { 4.09, "Добрая охота." }, { 5.08, "Я пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо." }, { 9.11, "Ты оказал своему народу услугу." } }, f = { { 0.00, "Отлично!" }, { 4.18, "Добрая охота." }, { 5.20, "Я пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо." }, { 9.32, "Ты оказала своему народу услугу." } } } } },
    [777] = { d = 6.8, v = "gnome-male", n = { x = 62 }, c = { x = { { 0.00, "Ну, теперь за дело!" }, { 1.68, "Я буду здесь... в укрытии." }, { 3.90, "Если хочешь, можешь присоединиться." } } }, t = { d = 9.4, v = "gnome-male", n = { x = 85 }, c = { x = { { 0.00, "Ага, прекрасно!" }, { 1.57, "Отойди-ка в сторонку и наблюдай, как вершится история!" }, { 6.72, "*Лотвил вновь погружается в работу.*" } } } } },
    [778] = { d = 18.9, g = 1, v = "gnome-male", n = { m = 189, f = 194 }, c = { m = { { 0.00, "Ха!" }, { 0.29, "Сделано!" }, { 1.03, "Люсьен, Серво, время пришло!" }, { 3.46, "Ты готов стать свидетелем запуска в эксплуатацию совершенной смеси алхимии, инженерной науки и древних тайн?" }, { 12.22, "Сейчас я призову могущественного элементаля." }, { 15.82, "Это величайший день для всех нас!" } }, f = { { 0.00, "Ха!" }, { 0.29, "Сделано!" }, { 1.03, "Люсьен, Серво, время пришло!" }, { 3.46, "Ты готова стать свидетельницей запуска в эксплуатацию совершенной смеси алхимии, инженерной науки и древних тайн?" }, { 12.83, "Сейчас я призову могущественного элементаля." }, { 16.43, "Это величайший день для всех нас!" } } }, t = { d = 14.0, v = "gnome-male", n = { x = 141 }, c = { x = { { 0.00, "Спасибо!" }, { 0.71, "Ну и денёк!" }, { 1.56, "Не думал я, что так получится." }, { 3.89, "Хорошо, что с помощью магии мне удалось загнать тварь туда, откуда она появилась..." }, { 10.47, "Вот, это миллионная доля моей благодарности..." } } } } },
    [779] = { t = { d = 8.1, v = "narrator", n = { x = 88 }, c = { x = { { 0.00, "Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась." } } } } },
    [780] = { d = 25.1, v = "tauren-male", n = { x = 239 }, c = { x = { { 0.00, "Боевые вепри из Ежевичной лощины, что к востоку отсюда, вторгаются в охотничьи угодья нашего племени." }, { 8.84, "Их натаскивают свинобразы из племени Дыбогривов, наши заклятые враги." }, { 14.87, "Пойди и покажи гнусным тварям, кто хозяин в этих землях!" }, { 19.88, "Мы сварим из их боков и рыл славную похлёбку для наших детишек!" } } }, t = { d = 11.4, v = "tauren-male", n = { x = 98 }, c = { x = { { 0.00, "Прекрасно!" }, { 1.09, "Мы сварим отличную похлёбку, а для проклятых дыбогривов потеря нескольких боевых вепрей послужит уроком." } } } } },
    [781] = { d = 13.8, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения клана Дыбогривов на Лагерь Нараче." }, { 9.51, "Вождь Соколиный Ветер непременно должен об этом узнать!" } } }, t = { d = 15.2, g = 1, v = "tauren-male#67", n = { m = 149, f = 151 }, c = { m = { { 0.00, "Это действительно тревожные вести!" }, { 3.04, "Но с этой информацией мы сможем призвать наших братьев из Деревни Кровавого Копыта, чтобы остановить нападение." }, { 12.71, "Ты спас жизни многих тауренов." } }, f = { { 0.00, "Это действительно тревожные вести!" }, { 2.95, "Но с этой информацией мы сможем призвать наших братьев из Деревни Кровавого Копыта, чтобы остановить нападение." }, { 12.32, "Ты спасла жизни многих тауренов." } } } } },
    [782] = { d = 37.0, v = "orc-male#60", n = { x = 400 }, c = { x = { { 0.00, "От союзника Орды времён Второй войны, дракона Смертокрыла мы знаем, что два его лейтенанта, Чернохлыст и Гематус, были заточены в долине Летлор." }, { 11.06, "Чтобы отстоять честь Орды и не допустить предательства, мы должны заставить замолчать наших растленных бывших союзников!" }, { 20.25, "Мы наняли Тогруна и его шайку огров-наёмников, чтобы они помогли нам получить знак Земли – ключ, необходимый, чтобы открыть драконье узилище." }, { 31.11, "Но Тогрун предал нас, забрав знак себе." }, { 34.15, "Отправляйся в лагерь Бофф и отбери знак!" } } }, t = { d = 28.9, v = "orc-male#60", n = { x = 297 }, c = { x = { { 0.00, "Теперь, когда от Тогруна остался лишь голый скелет, обглоданный стервятниками и выбеленный солнцем и ветром, огры, лишённые главаря, рассеются по пустыне." }, { 12.43, "Так малая победа принесла с собой великую!" }, { 15.94, "Знак Земли снова у нас, и мы сможем отомкнуть узилище чёрных драконов в долине Летлор." }, { 22.89, "Мы спасём их от уготованного им вечного заключения, хоть и на верную погибель!" } } } } },
    [783] = { d = 32.1, g = 1, v = "human-male", n = { m = 383, f = 385 }, c = { m = { { 0.00, "Надеюсь, ты готов к подвигам, герой, поскольку для тебя есть дело здесь, в Североземье." }, { 5.64, "И я имею в виду не мирные сельские заботы." }, { 8.47, "Стража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится." }, { 17.52, "И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких." }, { 22.75, "Если ты готов откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом." }, { 28.57, "Он здесь, в аббатстве у меня за спиной." } }, f = { { 0.00, "Надеюсь, ты готова к подвигам, героиня, поскольку для тебя есть дело здесь, в Североземье." }, { 5.98, "И я имею в виду не мирные сельские заботы." }, { 8.89, "Стража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится." }, { 18.20, "И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких." }, { 23.58, "Если ты готова откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом." }, { 29.62, "Он здесь, в аббатстве у меня за спиной." } } }, t = { d = 23.8, v = "human-male", n = { x = 260 }, c = { x = { { 0.00, "Отлично." }, { 0.66, "Ещё один доброволец." }, { 2.19, "В эти дни у нас много таких, как ты." }, { 4.85, "Надеюсь, нам хватит бойцов." }, { 6.91, "Землям людей угрожают внешние враги, потому большая часть наших сил направлена к рубежам." }, { 13.55, "И из-за этого бандитские шайки вольготно чувствуют себя в наших землях." }, { 18.93, "Нам приходится воевать на много фронтов..." }, { 22.05, "Готовься к долгой войне." } } } } },
    [784] = { d = 37.5, v = "orc-male#60", n = { x = 410 }, c = { x = { { 0.00, "Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда." }, { 13.58, "Вторжение людей удалось отбить, крепость Тирагард пала." }, { 17.90, "Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость." }, { 24.83, "Нашей родине снова грозит опасность!" }, { 27.72, "Эти люди совершенно не чтут договоров!" }, { 30.67, "Покажи свою доблесть." }, { 32.38, "Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей." } } }, t = { d = 10.5, g = 1, v = "orc-male#60", n = { x = 96 }, c = { m = { { 0.00, "Твоя отвага скоро станет известна всем, герой!" }, { 3.78, "Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара." } }, f = { { 0.00, "Твоя отвага скоро станет известна всем, героиня!" }, { 4.15, "Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара." } } } } },
    [785] = { d = 38.8, v = "orc-male#60", n = { x = 405 }, c = { x = { { 0.00, "Тралл – весьма мудрый и благородный лидер." }, { 3.33, "Его навыки дипломата могут сравниться лишь с его отвагой на поле брани." }, { 9.06, "Тролли из племени Чёрного Копья оказались бесценными союзниками для всего орочьего рода." }, { 16.01, "И мы, из верности и чести, заключили с ними договор о взаимной обороне." }, { 21.60, "И вот вождь приказал удостовериться, что нашим друзьям в деревне Сен'джин ничто не угрожает." }, { 28.68, "Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы." }, { 35.27, "Разыщи Лара и спроси, не нужна ли ему помощь." } } } },
    [786] = { d = 33.8, g = 1, v = "troll-male#78", n = { m = 368, f = 369 }, c = { m = { { 0.00, "Говори потише, герой!" }, { 1.64, "Кентавры из племени Колкар совсем близко, вон там, к западу от Утёса Колкара." }, { 7.23, "Прошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!" }, { 21.24, "Нельзя допустить, чтобы они это сделали!" }, { 24.33, "Достаточно ли ты храбр, чтобы напасть на Утёс Колкара и уничтожить их планы?" }, { 29.79, "Я заметил, что они хранятся у трёх лидеров кентавров." } }, f = { { 0.00, "Говори потише, героиня!" }, { 1.77, "Кентавры из племени Колкар совсем близко, вон там, к западу от Утёса Колкара." }, { 7.36, "Прошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!" }, { 21.36, "Нельзя допустить, чтобы они это сделали!" }, { 24.44, "Достаточно ли ты храбра, чтобы напасть на Утёс Колкара и уничтожить их планы?" }, { 30.03, "Я заметил, что они хранятся у трёх лидеров кентавров." } } }, t = { d = 25.8, g = 1, v = "troll-male#78", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть." }, { 5.70, "Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь." }, { 12.04, "И так же верно, как то, что в пустыне Танариса есть песок, – прежде чем эти смутные времена закончатся, прольётся ещё немало крови." }, { 22.11, "Ты хорошо послужил своему народу, герой." } }, f = { { 0.00, "Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть." }, { 5.80, "Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь." }, { 12.24, "И так же верно, как то, что в пустыне Танариса есть песок, – прежде чем эти смутные времена закончатся, прольётся ещё немало крови." }, { 22.4