    [787] = { d = 34.9, g = 1, v = "orc-male#60", n = { x = 342 }, c = { m = { { 0.00, "Тром'ка, герой!" }, { 1.26, "Меня зовут Эйтригг." }, { 2.86, "Тралл поручил мне следить за обучением рекрутов." }, { 6.57, "Орда уже не такая, как раньше." }, { 9.01, "Некогда я оставил её: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти." }, { 17.67, "Во время изгнания я попал в плен к людям, но вождь меня спас." }, { 22.35, "Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов." }, { 28.36, "Я выслушал его – и вернулся." }, { 30.60, "Горнек скажет тебе, что делать дальше." } }, f = { { 0.00, "Тром'ка, героиня!" }, { 1.45, "Меня зовут Эйтригг." }, { 3.11, "Тралл поручил мне следить за обучением рекрутов." }, { 6.95, "Орда уже не такая, как раньше." }, { 9.48, "Некогда я оставил её: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти." }, { 18.46, "Во время изгнания я попал в плен к людям, но вождь меня спас." }, { 23.31, "Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов." }, { 29.53, "Я выслушал его – и вернулся." }, { 31.85, "Горнек скажет тебе, что делать дальше." } } }, t = { d = 17.6, v = "orc-male#60", n = { x = 178 }, c = { x = { { 0.00, "Ещё один из новобранцев Эйтригга, хм?" }, { 2.95, "В каком плачевном положении мы оказались, если это лучшее, что может произвести Орда." }, { 9.85, "Неважно." }, { 10.56, "К тому времени, когда мы решим, что вы готовы покинуть Долину, вы будете гордиться собой." } } } } },
    [788] = { d = 19.3, g = 1, v = "orc-male#60", n = { m = 198, f = 200 }, c = { m = { { 0.00, "Вот тебе первое поручение, чтобы ты набрался опыта и показал себя." }, { 5.28, "Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему." }, { 13.09, "Пожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда." } }, f = { { 0.00, "Вот тебе первое поручение, чтобы ты набралась опыта и показала себя." }, { 5.31, "Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему." }, { 12.98, "Пожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда." } } }, t = { d = 20.1, g = 1, v = "orc-male#60", n = { m = 200, f = 201 }, c = { m = { { 0.00, "Ну что ж, неплохо." }, { 1.50, "Но не задирай носа: грядут бои с куда более серьёзными врагами." }, { 6.84, "Однако ты показал себя достойным бойцом." }, { 10.30, "В следующем испытании тебе придётся встретиться с более опасным противником, так что дополнительная защита не помешает." } }, f = { { 0.00, "Ну что ж, неплохо." }, { 1.51, "Но не задирай носа: грядут бои с куда более серьёзными врагами." }, { 6.87, "Однако ты показала себя достойным бойцом." }, { 10.42, "В следующем испытании тебе придётся встретиться с более опасным противником, так что дополнительная защита не помешает." } } } } },
    [789] = { d = 30.6, v = "orc-male#60", n = { x = 305 }, c = { x = { { 0.00, "Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков." }, { 6.31, "К северо-западу отсюда водится множество этих членистоногих." }, { 11.35, "Принеси мне десять их хвостов, чтобы доказать свою воинскую доблесть." }, { 17.14, "Из яда жал скорпионов можно изготовить противоядие." }, { 21.37, "Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя..." }, { 27.97, "Но тебе-то оно не понадобится, а?" } } }, t = { d = 22.6, g = 1, v = "orc-male#60", n = { m = 209, f = 210 }, c = { m = { { 0.00, "Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним!" }, { 8.56, "В бою победа или поражение зависят от многого." }, { 12.68, "Ну что ж!" }, { 13.46, "Я научил тебя всему, чему мог." }, { 16.18, "Ты оказался хорошим учеником." }, { 18.75, "Я буду с интересом следить за твоей карьерой." } }, f = { { 0.00, "Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним!" }, { 8.41, "В бою победа или поражение зависят от многого." }, { 12.46, "Ну что ж!" }, { 13.22, "Я научил тебя всему, чему мог." }, { 15.90, "Ты оказалась хорошим учеником." }, { 18.50, "Я буду с интересом следить за твоей карьерой." } } } } },
    [790] = { d = 32.1, g = 1, v = "troll-male", n = { x = 291 }, c = { m = { { 0.00, "Герой!" }, { 0.60, "А я уж думаю, помру тут, никто и не узнает..." }, { 4.37, "Я охотился в долине на скорпидов, и попался мне один, особенно злобный." }, { 10.32, "Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу." }, { 17.77, "А вот жало застигло меня врасплох." }, { 20.71, "Оно вонзилось мне в грудь, хлынула кровь..." }, { 24.25, "Прошу тебя, смой с меня позор!" }, { 26.89, "Убей этого скорпида!" }, { 28.70, "Я сражался с ним на плато, к югу отсюда..." } }, f = { { 0.00, "Героиня!" }, { 0.75, "А я уж думаю, помру тут, никто и не узнает..." }, { 4.50, "Я охотился в долине на скорпидов, и попался мне один, особенно злобный." }, { 10.42, "Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу." }, { 17.84, "А вот жало застигло меня врасплох." }, { 20.77, "Оно вонзилось мне в грудь, хлынула кровь..." }, { 24.29, "Прошу тебя, смой с меня позор!" }, { 26.91, "Убей этого скорпида!" }, { 28.71, "Я сражался с ним на плато, к югу отсюда..." } } }, t = { d = 17.3, v = "troll-male", n = { x = 155 }, c = { x = { { 0.00, "Да, убить его мне не удалось, но ранил я его серьёзно." }, { 4.80, "Пожалуй, мне есть чем гордиться." }, { 7.60, "И это единственное, что утешает меня перед смертью." }, { 12.24, "Как подумаю, как мало я сделал в жизни, такая злость берёт!" } } } } },
    [791] = { d = 39.8, v = "orc-male#60", n = { x = 393 }, c = { x = { { 0.00, "Старость сделала меня бесполезным в бою." }, { 3.33, "Теперь я служу Орде иным путём." }, { 5.94, "Я сижу здесь, на вышине, и смотрю, не появятся ли враги." }, { 10.43, "Но по мере того, как наши силы растут, мне всё реже и реже приходится трубить в сигнальный рог." }, { 18.11, "А чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину." }, { 28.26, "Я могу сделать тебе сумку для пожитков." }, { 31.52, "Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров." } } }, t = { d = 11.2, v = "orc-male#60", n = { x = 92 }, c = { x = { { 0.00, "Отлично!" }, { 0.90, "Такая сумка пригодится любому хорошему бойцу." }, { 5.55, "Я отдаю честь твоей силе и решимости умереть во имя Орды!" } } } } },
    [792] = { d = 34.1, g = 1, v = "orc-female", n = { x = 339 }, c = { m = { { 0.00, "Что ж, герой, надеюсь, у нас ты многому научишься." }, { 3.90, "Меня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не всё ладно!" }, { 10.77, "В долине Испытаний обосновался клан Пылающего Клинка." }, { 14.95, "Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос." }, { 23.10, "Итак, вот твоё первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне." } }, f = { { 0.00, "Что ж, героиня, надеюсь, у нас ты многому научишься." }, { 4.11, "Меня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не всё ладно!" }, { 11.10, "В долине Испытаний обосновался клан Пылающего Клинка." }, { 15.35, "Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос." }, { 23.64, "Итак, вот твоё первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне." } } }, t = { d = 13.3, v = "orc-female", n = { x = 126 }, c = { x = { { 0.00, "Спасибо тебе!" }, { 1.26, "Да, злобные фамильяры для воинов клана Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предсказывает тебе великие дела!" } } } } },
    [793] = { d = 34.9, g = 1, v = "orc-male#60", n = { m = 349, f = 349 }, c = { m = { { 0.00, "Печать Земли удерживают три рунных камня, сокрытые в долине Летлор." }, { 5.59, "Один спрятан в алмазном столпе, другой – в опаловом, третий – в аметистовом." }, { 11.85, "С помощью знака Земли ты сможешь извлечь рунные камни и разрушить печать Земли." }, { 18.47, "Но будь осторожен, Чернохлыст и Гематус очень опасны." }, { 22.82, "Ты должен убить их и принести мне их наручники." }, { 26.64, "Долина расположена к востоку от Бесплодных земель." }, { 30.76, "Не теряй бдительности – в низине множество драконов!" } }, f = { { 0.00, "Печать Земли удерживают три рунных камня, сокрытые в долине Летлор." }, { 5.54, "Один спрятан в алмазном столпе, другой – в опаловом, третий – в аметистовом." }, { 11.74, "С помощью знака Земли ты сможешь извлечь рунные камни и разрушить печать Земли." }, { 18.30, "Но будь осторожна, Чернохлыст и Гематус очень опасны." }, { 22.61, "Ты должна убить их и принести мне их наручники." }, { 26.40, "Долина расположена к востоку от Бесплодных земель." }, { 30.48, "Не теряй бдительности – в низине множество драконов!" } } }, t = { d = 18.9, v = "orc-male#60", n = { x = 187 }, c = { x = { { 0.00, "Чёрные драконы вступают в союз с отступниками – орками Чёрной Горы." }, { 5.48, "И тех, и других должно вернуть в лоно Орды или уничтожить." }, { 10.37, "Теперь, когда мы покончили с Гематусом и Чернохлыстом, мы можем обратить взор на запад, на пик Чёрной Горы." } } } } },
    [794] = { d = 35.2, v = "orc-female", n = { x = 373 }, c = { x = { { 0.00, "С помощью ворожбы я узнала, что в глубине грота Пылающего Клинка находится мощный магический предмет." }, { 7.88, "Его стерегут звери и чёрная магия." }, { 10.60, "Этот предмет – медальон Пылающего Клинка." }, { 13.87, "Твоя очередная задача – найти его и отнять у ковена." }, { 18.06, "Но берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамильяры, с которыми тебе уже доводилось встречаться!" }, { 31.72, "Ступай." }, { 32.35, "Грот находится к северо-западу отсюда." } } }, t = { d = 17.6, v = "orc-female", n = { x = 176 }, c = { x = { { 0.00, "Он у тебя!" }, { 0.88, "Молодец!" }, { 1.61, "Теперь у нас есть возможность вытеснить приспешников Пылающего Клинка из Долины Испытаний." }, { 8.88, "Но, боюсь, этот грот – не единственный их оплот в наших землях." }, { 14.01, "Так что эта встреча с ними была не последней." } } } } },
    [795] = { t = { d = 8.2, v = "narrator", n = { x = 88 }, c = { x = { { 0.00, "Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась." } } } } },
    [804] = { d = 18.2, g = 1, v = "troll-male", n = { m = 177, f = 178 }, c = { m = { { 0.00, "То, что ты сделал ради меня, заставило меня воспрянуть духом." }, { 5.07, "Я ещё повоюю!" }, { 6.18, "Но пока что мне не добраться до Логова без посторонней помощи." }, { 11.18, "Прошу тебя, сходи в Логово, расскажи Горнеку, что я здесь." }, { 15.96, "Может, он сумеет мне помочь." } }, f = { { 0.00, "То, что ты сделала ради меня, заставило меня воспрянуть духом." }, { 4.99, "Я ещё повоюю!" }, { 6.06, "Но пока что мне не добраться до Логова без посторонней помощи." }, { 10.91, "Прошу тебя, сходи в Логово, расскажи Горнеку, что я здесь." }, { 15.55, "Может, он сумеет мне помочь." } } }, t = { d = 29.3, v = "orc-male#60", n = { x = 300 }, c = { x = { { 0.00, "Судя по твоему описанию, этим скорпионом был не кто иной, как Саркот!" }, { 5.51, "Неудивительно, что Хана'зуа с ним не справился." }, { 9.17, "Не тревожься о нём, помощь уже в пути." }, { 12.25, "Однако, нужно сказать, я тебя зауважал." }, { 15.47, "Неужели тебе действительно удалось одолеть Саркота?" }, { 19.62, "Это немалый подвиг, тебе есть чем гордиться." }, { 23.20, "А твоя готовность сражаться по просьбе незнакомца тем более делает тебе честь." } } } } },
    [805] = { d = 39.2, v = "orc-female", n = { x = 414 }, c = { x = { { 0.00, "Твои испытания в борьбе с Пылающим Клинком подошли к концу... по крайней мере тут, в нашей Долине." }, { 7.49, "Но я прошу тебя отнести известие о том, что ты теперь знаешь." }, { 12.12, "Ступай в тролльскую деревню Сен'джин, отыщи там мастера Гадрина." }, { 16.95, "Отправляйся на восток, на развилке поверни направо." }, { 20.83, "Расскажи Гадрину о чернокнижниках из клана Пылающего Клинка и о том, что они уже проникли в долину Испытаний." }, { 29.07, "Узнай, не видно ли их в Сен'джине." }, { 31.59, "Ступай, и не медли в пути!" }, { 33.63, "Боюсь, появление Пылающего Клинка в долине – это только первая ласточка..." } } }, t = { d = 22.3, v = "troll-male#77", n = { x = 200 }, c = { x = { { 0.00, "Хм..." }, { 0.47, "Как это всё не вовремя!" }, { 2.51, "Нет, у нас в Сен'джине Пылающего Клинка пока не видно, однако на побережье, на островах Эха, обосновалось иное зло." }, { 12.37, "Орки – друзья племени Чёрного Копья." }, { 15.59, "Верные друзья." }, { 16.92, "Мы хотели бы помочь оркам, но... сейчас нам самим нужна помощь!" } } } } },
    [806] = { d = 35.0, v = "orc-male", n = { x = 376 }, c = { x = { { 0.00, "Нельзя допустить, чтобы Пылающий Клинок закрепился в Дуротаре!" }, { 4.95, "Нужно уничтожить этих чернокнижников, прежде чем распространяемое ими зло расползётся по нашей земле!" }, { 12.79, "Я провёл расследование и выяснил, что один из чернокнижников из клана Пылающего Клинка, гоблин по имени Пшикс Черношквал, обосновался на Громовом хребте к северо-западу отсюда." }, { 26.43, "Там он и его приспешники сеют хаос!" }, { 29.25, "Найди Пшикса, убей его и принеси мне его коготь в качестве доказательства." } } }, t = { d = 10.4, g = 1, v = "orc-male", n = { m = 92, f = 93 }, c = { m = { { 0.00, "Ага!" }, { 0.49, "Ты его убил!" }, { 1.72, "Твой клан может гордиться тобой." }, { 4.67, "Благодаря тебе в Дуротаре стало одним приспешником зла меньше." } }, f = { { 0.00, "Ага!" }, { 0.49, "Ты его убила!" }, { 1.80, "Твой клан может гордиться тобой." }, { 4.75, "Благодаря тебе в Дуротаре стало одним приспешником зла меньше." } } } } },
    [808] = { d = 41.3, v = "troll-male#77", n = { x = 402 }, c = { x = { { 0.00, "Я слышу голос моего брата, Миншины." }, { 3.03, "Он взывает ко мне из снов." }, { 5.11, "Его захватил в плен Залазан, чернокнижник с островов Эха на востоке." }, { 10.73, "И теперь Миншина мёртв." }, { 12.65, "Но смерть не принесла ему свободы!" }, { 15.46, "Залазан заточил дух Миншины внутри его собственного черепа." }, { 20.42, "В снах я вижу его рядом с другими черепами, в магическом кругу на самом большом из островов Эха." }, { 28.41, "Пока его душа находится в этом месте, она обречена на вечные страдания." }, { 34.48, "Прошу тебя, отыщи этот круг и похить череп Миншины." }, { 38.84, "Принеси его мне." }, { 40.25, "Освободи его!" } } }, t = { d = 6.9, v = "troll-male#77", n = { x = 61 }, c = { x = { { 0.00, "Спасибо!" }, { 0.84, "Тебе удалось спасти Миншину!" }, { 3.61, "Дух моего брата избавлен от рабства!" } } } } },
    [809] = { d = 44.0, v = "orc-male", n = { x = 472 }, c = { x = { { 0.00, "Со времён последней великой войны, когда Пылающий Легион потерпел поражение, я ищу источники демонической порчи, что воздействует на общество орков." }, { 11.59, "И принесённый тобой ошейник подтверждает мои опасения!" }, { 15.82, "Он принадлежит Пылающему Клинку, культу, объединённому вокруг предмета, который наделён демонической силой." }, { 24.09, "Этот предмет называется Демоново Семя, и находится он в Степях, на вершине Багрового Тумана." }, { 31.36, "Его необходимо уничтожить!" }, { 33.48, "Отправляйся на Дальнюю заставу на границе Степей, к западу, и поговори с моим помощником, Ак'Зелотом." }, { 41.40, "Он скажет тебе, что делать дальше." } } }, t = { d = 12.7, v = "orc-male", n = { x = 111 }, c = { x = { { 0.00, "Вот как?" }, { 0.72, "Нииру хочет, чтобы Демоново семя было уничтожено?" }, { 5.31, "Странно…" }, { 6.12, "Что ж, хорошо." }, { 7.41, "Если такова его воля, я расскажу тебе, как уничтожить семя." } } } } },
    [812] = { d = 29.0, v = "troll-male", n = { x = 285 }, c = { x = { { 0.00, "А..." }, { 0.36, "Ты как нельзя вовремя!" }, { 2.19, "Надеюсь на твоё проворство." }, { 4.38, "Я сражался с несколькими ядохвостами, и один из них смог меня ужалить." }, { 10.00, "Я чувствую, как слабею с каждой секундой..." }, { 13.50, "Боюсь, мне осталось не больше часа." }, { 16.42, "Мне срочно нужна твоя помощь!" }, { 18.90, "Кор'гхан из Оргриммара умеет изготовлять противоядие." }, { 23.21, "Найди его..." }, { 24.30, "Быстрее!" }, { 25.03, "Долго мне не протянуть." }, { 26.93, "Ищи его в расселине Теней." } } }, t = { d = 25.8, g = 1, v = "troll-male", n = { m = 275, f = 277 }, c = { m = { { 0.00, "Ты спас мне жизнь!" }, { 1.24, "Спасибо тебе." }, { 2.29, "Прошу тебя, возьми эту вещь." }, { 4.45, "Денег за неё не выручишь, но, надеюсь, она пригодится тебе в странствиях." }, { 9.74, "Судя по тому, что ты говоришь, мне она пригодится нескоро." }, { 13.99, "Кор'гхан подвергнет меня ещё множеству своих ритуалов, пока я не сумею показать, на что способен." }, { 21.05, "Снова охотиться на вепрей, собирать хвосты скорпидов..." } }, f = { { 0.00, "Ты спасла мне жизнь!" }, { 1.47, "Спасибо тебе." }, { 2.54, "Прошу тебя, возьми эту вещь." }, { 4.74, "Денег за неё не выручишь, но, надеюсь, она пригодится тебе в странствиях." }, { 10.14, "Судя по тому, что ты говоришь, мне она пригодится нескоро." }, { 14.48, "Кор'гхан подвергнет меня ещё множеству своих ритуалов, пока я не сумею показать, на что способен." }, { 21.69, "Снова охотиться на вепрей, собирать хвосты скорпидов..." } } } } },
    [813] = { d = 26.8, v = "troll-male#78", n = { x = 289 }, c = { x = { { 0.00, "Ядохвосты – одни из опаснейших скорпидов в Дуротаре!" }, { 3.98, "Со стороны Ринага было очень глупо охотиться на них, не имея при себе противоядия." }, { 10.29, "Впрочем, сейчас его вразумлять уже поздно." }, { 13.65, "Принеси мне несколько ядовитых желёз ядохвоста от любых ядохвостов, каких найдёшь у входа в Оргриммар, и я сделаю ему противоядие." }, { 23.45, "Торопись!" }, { 24.21, "Одному из наших нужна твоя помощь!" } } }, t = { d = 5.4, v = "troll-male#78", n = { x = 55 }, c = { x = { { 0.00, "Вот противоядие." }, { 1.34, "Отнеси его поскорее Ринагу, да смотри, осторожнее!" } } } } },
    [815] = { d = 31.9, v = "orc-male", n = { x = 345 }, c = { x = { { 0.00, "Ба!" }, { 0.27, "А я и позабыл, что надо готовить завтрак." }, { 3.36, "Слушай, сбегай-ка, раздобудь мне по-быстрому несколько яиц кнутохвостов, как минимум три штуки." }, { 10.42, "Имей в виду, кровопалые кнутохвосты – твари свирепые и вполне могут убить, защищая свою кладку." }, { 17.68, "Иногда они зарывают яйца слишком глубоко, чтобы их можно было беспрепятственно раздобыть, но если ты отправишься на острова Эха, к юго-востоку от деревни Сен'джин, там эти яйца лежат повсюду." } } }, t = { d = 10.9, v = "orc-male", n = { x = 97 }, c = { x = { { 0.00, "Ну, может, ты и слабак, но уж ловкости и проворства тебе не занимать!" }, { 6.08, "На вот, возьми за труды и проваливай." }, { 9.36, "Мне готовить надо!" } } } } },
    [816] = { d = 40.8, v = "orc-female#57", n = { x = 441 }, c = { x = { { 0.00, "Прошу тебя, может, хоть ты сумеешь мне помочь?" }, { 3.50, "Мой сын, Крон, несколько дней тому назад отправился на охоту и до сих пор не вернулся!" }, { 9.75, "Он ушёл на запад, в Степи, охотиться на кроколисков у реки Строптивой." }, { 14.93, "Я опасаюсь худшего…" }, { 16.41, "Крон могуч, но гордость и упрямство всегда доводили его до беды." }, { 21.25, "Я попросила его не охотиться на кроколисков, потому что они злобны и коварны!" }, { 27.03, "А он рассвирепел и хлопнул дверью." }, { 29.58, "Если не сумеешь отыскать его – узнай хотя бы, что с ним случилось... даже если тебе придётся заглянуть в брюхо каждому кроколиску на берегах Строптивой!" } } }, t = { d = 24.9, v = "orc-female#57", n = { x = 240 }, c = { x = { { 0.00, "Ох, сыночек... милый мой сыночек…" }, { 2.66, "Что ж, я не знала судьбы своего сына и потому терзалась понапрасну." }, { 8.06, "Теперь же я хоть смогу его оплакать…" }, { 11.01, "Спасибо тебе." }, { 12.16, "Прошу тебя, возьми этот плащ." }, { 14.60, "Я-то собиралась подарить его Крону, когда он вернётся с добычей..." }, { 19.92, "А теперь, зная, что он погиб, я даже не смогу смотреть на него." } } } } },
    [817] = { d = 32.8, v = "troll-male#78", n = { x = 317 }, c = { x = { { 0.00, "У нас в большом ходу шкуры дуротарского тигра." }, { 3.82, "Чего только из них не делают!" }, { 6.24, "И одеяла, и доспехи, и шатры." }, { 8.66, "Вот почему мы охотимся на этих животных, но не истребляем их." }, { 13.58, "В общем, пришла пора в очередной раз сократить поголовье." }, { 18.27, "Наши потребности растут, и запасов не хватает." }, { 22.09, "Мне нужны новые шкуры." }, { 24.00, "Принеси мне четыре шкуры дуротарских тигров, и получишь награду." }, { 29.28, "Эти кошки водятся на островах к югу отсюда." } } }, t = { d = 10.6, v = "troll-male#78", n = { x = 109 }, c = { x = { { 0.00, "Молодец!" }, { 0.72, "Благодаря твоей помощи наш народ не останется без доспехов и не будет страдать от холода, когда наступит зима." }, { 9.56, "Спасибо тебе." } } } } },
    [818] = { d = 40.3, g = 1, v = "troll-male", n = { m = 390, f = 391 }, c = { m = { { 0.00, "Да, глаза меня порой подводят, но всё же пока я вижу достаточно отчётливо." }, { 5.96, "И всё чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда." }, { 15.18, "И я не беру учеников." }, { 16.92, "Нет нынче достойных ни среди троллей, ни среди орков." }, { 21.28, "Что?" }, { 21.64, "Ты достоин?" }, { 22.59, "Ну да, конечно..." }, { 23.97, "Это ты так думаешь." }, { 25.57, "Мне нужны кое-какие компоненты." }, { 28.18, "Сумеешь ли ты их добыть?" }, { 30.14, "Мне нужны невредимые глаза макрур и слизь крабов, которые водятся к югу отсюда." }, { 36.61, "Вот принеси мне их, потом поговорим." } }, f = { { 0.00, "Да, глаза меня порой подводят, но всё же пока я вижу достаточно отчётливо." }, { 6.09, "И всё чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда." }, { 15.52, "И я не беру учеников." }, { 17.30, "Нет нынче достойных ни среди троллей, ни среди орков." }, { 21.76, "Что?" }, { 22.13, "Ты достойна?" }, { 23.17, "Ну да, конечно..." }, { 24.58, "Это ты так думаешь." }, { 26.22, "Мне нужны кое-какие компоненты." }, { 28.89, "Сумеешь ли ты их добыть?" }, { 30.89, "Мне нужны невредимые глаза макрур и слизь крабов, которые водятся к югу отсюда." }, { 37.50, "Вот принеси мне их, потом поговорим." } } }, t = { d = 3.2, v = "troll-male", n = { x = 23 }, c = { x = { { 0.00, "Отличная работа!" }, { 2.01, "Ты молодец!" } } } } },
    [819] = { d = 9.6, v = "narrator", n = { x = 89 }, c = { x = { { 0.00, "Маленькая табличка на торце одной из бочек гласит:" }, { 4.31, "\"Чэнь Буйный Портер –" }, { 6.13, "Да будет ваш дух горяч, а кружка – полной.\"" } } }, t = { d = 17.4, g = 1, v = "orc-male", n = { m = 157, f = 159 }, c = { m = { { 0.00, "Ну, я…" }, { 0.57, "Это был один из бочонков Чэня Буйного Портера." }, { 4.84, "Давным-давно он путешествовал вместе с Рексаром." }, { 9.12, "Я не видел его и не слышал о нём с незапамятных времён." }, { 13.97, "Спасибо, что ты принёс мне этот бочонок." } }, f = { { 0.00, "Ну, я…" }, { 0.54, "Это был один из бочонков Чэня Буйного Портера." }, { 4.60, "Давным-давно он путешествовал вместе с Рексаром." }, { 8.67, "Я не видел его и не слышал о нём с незапамятных времён." }, { 13.27, "Спасибо, что ты принесла мне этот бочонок." } } } } },
    [821] = { d = 28.9, v = "orc-male", n = { x = 284 }, c = { x = { { 0.00, "Хочешь попробовать напиток, придуманный Чэнем?" }, { 3.78, "Ах, до чего же хорош!" }, { 5.53, "Чэнь передал рецепт моему наставнику, ну а он – мне." }, { 9.68, "Только для него понадобится несколько компонентов." }, { 13.75, "Но он того стоит!" }, { 15.21, "Принеси мне пять клыков равнинного льва, пять почек долгонога и один рог рокочущей ящерицы." }, { 22.48, "Из них выйдет прекрасный портер." }, { 25.10, "Все эти составляющие нетрудно отыскать в Степях." } } }, t = { d = 15.8, v = "orc-male", n = { x = 146 }, c = { x = { { 0.00, "Ха-ха..." }, { 0.78, "Вот уж не думал, что снова сварю этот напиток!" }, { 4.86, "Прямо ностальгия охватила." }, { 7.21, "Сразу вспомнилось, как я наварил троггского пойла." }, { 11.61, "Спасибо." }, { 12.39, "От воспоминаний даже на душе посветлело." } } } } },
    [822] = { d = 29.1, v = "orc-male", n = { x = 270 }, c = { x = { { 0.00, "Отличный напиток, а?" }, { 1.77, "Я научился у Чэня ещё одному рецепту." }, { 4.99, "Хочешь узнать?" }, { 6.30, "Много времени он не отнимает, а в жизни пригодится." }, { 10.68, "Принеси мне пять грозовых желёз любых грозошкуров, одну слюнную железу грозового змея от больших грозовых змеев и печень кодо от любого из кодо Степей." }, { 23.67, "Вставляет – не то слово." }, { 25.74, "Это эль трогга, о котором я уже говорил." } } }, t = { d = 10.2, v = "orc-male", n = { x = 88 }, c = { x = { { 0.00, "Ха-ха!" }, { 0.66, "Я знал, что ты не откажешься от этого напитка." }, { 4.75, "Приходи, я ещё тебе сварю." }, { 7.21, "Главное – приноси всё необходимое." } } } } },
    [823] = { d = 37.7, g = 1, v = "troll-male#77", n = { m = 380, f = 381 }, c = { m = { { 0.00, "У нас, в деревне Сен'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала." }, { 7.06, "Так что спасибо тебе." }, { 8.80, "Однако принесённые тобой вести о Пылающем Клинке сулят неприятности всем." }, { 14.70, "В Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок." }, { 25.54, "Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты узнал в долине Испытаний." }, { 32.89, "Ему нужно это знать." }, { 34.63, "Колючий Холм находится к северу отсюда." } }, f = { { 0.00, "У нас, в деревне Сен'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала." }, { 6.91, "Так что спасибо тебе." }, { 8.62, "Однако принесённые тобой вести о Пылающем Клинке сулят неприятности всем." }, { 14.39, "В Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок." }, { 25.00, "Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты узнала в долине Испытаний." }, { 32.27, "Ему нужно это знать." }, { 33.98, "Колючий Холм находится к северу отсюда." } } }, t = { d = 5.9, v = "orc-male", n = { x = 49 }, c = { x = { { 0.00, "Да?" }, { 0.34, "Тебе есть, о чём доложить?" }, { 2.83, "Ну так рассказывай, чего ты ждёшь?!" } } } } },
    [824] = { d = 30.2, v = "orc-male", n = { x = 315 }, c = { x = { { 0.00, "Служители Земли – сообщество шаманов, посвятивших себя изучению и охране Стихий." }, { 6.24, "Они забыли о безумных древних богах, древних легендах и преданиях больше, чем большинство учёных вообще знало." }, { 14.77, "Повезло тебе, что я знаю кое-кого из Служителей Земли тут, в Ясеневом лесу." }, { 20.67, "Иди в форт Зорам'гар на Зорамское взморье и покажи Дже'неу Санкри свою находку." }, { 26.84, "Если кто и поймёт, что это за шар, так это он." } } }, t = { d = 32.6, g = 1, v = "troll-male", n = { m = 329, f = 331 }, c = { m = { { 0.00, "Этот шар... волнует он меня." }, { 2.27, "Многие из наиболее могучих элементалей черпают силу и энергию при помощи таких устройств." }, { 9.36, "Найти такую штуку неповреждённой – одно дело, а вот настолько осквернённой – совсем другое." }, { 16.46, "Я прослежу, чтобы этот шар как следует изучили Служители Земли." }, { 21.49, "Возможно, мы сумеем положить конец такому осквернению Стихий." }, { 26.39, "Прошу – прими это в награду за то, что принёс нам этот шар для изучения." } }, f = { { 0.00, "Этот шар... волнует он меня." }, { 2.31, "Многие из наиболее могучих элементалей черпают силу и энергию при помощи таких устройств." }, { 9.53, "Найти такую штуку неповреждённой – одно дело, а вот настолько осквернённой – совсем другое." }, { 16.76, "Я прослежу, чтобы этот шар как следует изучили Служители Земли." }, { 21.89, "Возможно, мы сумеем положить конец такому осквернению Стихий." }, { 26.87, "Прошу – прими это в награду за то, что принесла нам этот шар для изучения." } } } } },
    [825] = { d = 32.2, v = "orc-male#60", n = { x = 350 }, c = { x = { { 0.00, "Один из моих лучших разведчиков принёс сообщение, что обломки кораблей Праудмура всё ещё плавают около побережья Дуротара, к востоку от крепости Тирагард." }, { 11.83, "Ни для кого не секрет, что люди, будучи в союзе с этими маленькими уродцами, гномами, неплохо овладели механикой." }, { 20.45, "Нам нужно знать всё о нашем предполагаемом противнике!" }, { 24.48, "К тому же, эти знания пригодятся и нашему народу." }, { 28.31, "Сплавай к обломкам, и добудь мне инструменты Альянса." } } }, t = { d = 10.9, g = 1, v = "orc-male#60", n = { m = 107, f = 108 }, c = { m = { { 0.00, "Ты успешно выполнил поручение, герой." }, { 2.93, "Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном." }, { 9.69, "Молодец!" } }, f = { { 0.00, "Ты успешно выполнила поручение, героиня." }, { 3.27, "Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном." }, { 10.31, "Молодец!" } } } } },
    [826] = { d = 32.2, v = "troll-male#77", n = { x = 333 }, c = { x = { { 0.00, "Знахарь Залазан живёт на островах Эха на востоке." }, { 3.93, "Эти острова мы когда-то называли родиной…" }, { 7.29, "А теперь он оттуда посылает троллей на материк, досаждая нашему народу и переманивая на свою сторону всё новых приспешников." }, { 17.16, "Его нужно остановить!" }, { 18.94, "Уничтожь Залазана и его слуг – бывших троллей из племени Чёрного Копья, ныне потерянных для нас!" }, { 26.52, "Принеси мне его голову – и я буду знать, что владычеству зла пришёл конец." } } }, t = { d = 20.2, v = "troll-male#77", n = { x = 192 }, c = { x = { { 0.00, "Залазана больше нет, наше племя снова может спать спокойно!" }, { 5.12, "Спасибо." }, { 5.88, "Племя Чёрного Копья многим тебе обязано." }, { 9.39, "Если тебя мучает какой-нибудь недуг, обратись к моему помощнику, Бом'бею, который находится позади меня." }, { 18.41, "Он силён в магии вуду…" } } } } },
    [827] = { d = 36.4, v = "orc-male", n = { x = 381 }, c = { x = { { 0.00, "Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как скала Черепа." }, { 6.75, "Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками." }, { 14.22, "Я подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами." }, { 21.40, "Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников." }, { 27.50, "Ступай к скале Черепа и отбери у фанатиков, которых там найдёшь, их ошейники." }, { 33.61, "Принеси их мне, и я раскрою их тайну!" } } }, t = { d = 8.1, v = "orc-male", n = { x = 61 }, c = { x = { { 0.00, "Отлично!" }, { 0.96, "В этих ошейниках и таится секрет Пылающего Клинка." }, { 6.43, "И я его раскрою!" } } } } },
    [828] = { d = 37.7, v = "orc-male", n = { x = 392 }, c = { x = { { 0.00, "Один из наших шаманов, Маргоз, многое знает о клане Пылающего Клинка." }, { 5.52, "Как-то он рассказывал о пещере, которая называется скала Черепа, в горах у самого Оргриммара." }, { 12.80, "Там окопалась большая шайка сектантов из клана Пылающего Клинка." }, { 17.83, "Прежде чем отправиться к скале Черепа, поговори с Маргозом." }, { 22.45, "Он мудр, и к его советам стоит прислушиваться." }, { 26.01, "Ты найдёшь его на северо-востоке, между побережьем и Сухой лощиной." }, { 31.26, "Следуй его советам, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!" } } }, t = { d = 15.1, g = 1, v = "orc-male", n = { m = 132, f = 132 }, c = { m = { { 0.00, "Здравствуй." }, { 1.05, "До меня дошли слухи о твоём появлении и о твоих подвигах в Дуротаре." }, { 7.20, "Ты – многообещающий герой." }, { 9.54, "Не сворачивай с этого пути, и великое будущее будет ждать тебя!" } }, f = { { 0.00, "Здравствуй." }, { 1.02, "До меня дошли слухи о твоём появлении и о твоих подвигах в Дуротаре." }, { 6.97, "Ты – многообещающая героиня." }, { 9.40, "Не сворачивай с этого пути, и великое будущее будет ждать тебя!" } } } } },
    [829] = { d = 42.7, v = "orc-male", n = { x = 456 }, c = { x = { { 0.00, "Принесённые тобой обжигающие ошейники – это мощные инструменты демонов." }, { 5.52, "И распознать их происхождение мне, как шаману, не под силу." }, { 10.00, "Нужно, чтобы на них взглянул чернокнижник." }, { 13.29, "Отнеси один обжигающий ошейник Нииру Огненному Клинку." }, { 17.62, "Он искусный чернокнижник, но утверждает, что использует свою силу лишь затем, чтобы вредить демонам, а ещё говорит, что его оккультные исследования идут на пользу Орде." }, { 30.63, "Правда это или нет, а его помощь нам ещё может понадобиться в борьбе с последователями демонов в Дуротаре." }, { 38.88, "Нииру можно найти в Оргриммаре, в Расселине Теней." } } }, t = { d = 8.9, v = "orc-male", n = { x = 80 }, c = { x = { { 0.00, "О!" }, { 0.23, "Откуда у тебя это?" }, { 1.90, "Тебя прислал ко мне славный Маргоз из Колючего Холма, верно?" }, { 7.06, "Ну-ка, дай взглянуть..." } } } } },
    [830] = { d = 18.1, v = "narrator", n = { x = 187 }, c = { x = { { 0.00, "Вы открываете потрёпанный и выгоревший конверт и обнаруживаете документ официального вида." }, { 6.97, "На нём – печать адмирала Праудмура." }, { 9.97, "Похоже, это что-то важное." }, { 12.20, "Может быть, Га'току, командиру Колючего Холма, эта информация пригодится..." } } }, t = { d = 6.6, g = 1, v = "orc-male#60", n = { m = 57, f = 59 }, c = { m = { { 0.00, "Ничего хорошего это не предвещает..." }, { 3.28, "Очень хорошо, что ты принёс это мне." } }, f = { { 0.00, "Ничего хорошего это не предвещает..." }, { 3.28, "Очень хорошо, что ты принесла это мне." } } } } },
    [831] = { d = 41.8, v = "orc-male#60", n = { x = 444 }, c = { x = { { 0.00, "Людям верить нельзя." }, { 1.62, "Мы сражались плечом к плечу с ними, но в глубине души знали, что рано или поздно они нас предадут." }, { 9.10, "Адмирал Праудмур был убит, но этого оказалось недостаточно, чтобы остановить предательство." }, { 16.86, "Этот подлый человечишка успел изложить свои планы на бумаге, прежде чем встретил заслуженную смерть." }, { 24.41, "Его наследие не пропадёт даже со смертью Бенедикта." }, { 28.26, "Кто знает, когда следующая волна людей Праудмура обрушится на наши берега?" }, { 34.57, "Эти приказы нужно немедленно доставить в Оргриммар, Назгрелу!" }, { 39.22, "Ты найдёшь его в зале приёмов Тралла." } } }, t = { d = 15.7, g = 1, v = "orc-male", n = { m = 145, f = 146 }, c = { m = { { 0.00, "О, сколько раз я умолял вождя не доверять людям!" }, { 4.03, "Однако тут речь не о личной гордости." }, { 7.09, "Ты достойно послужил Орде, герой." }, { 9.92, "А теперь извини, мне нужно немедленно поговорить об этом с Траллом!" } }, f = { { 0.00, "О, сколько раз я умолял вождя не доверять людям!" }, { 4.05, "Однако тут речь не о личной гордости." }, { 7.13, "Ты достойно послужила Орде, героиня." }, { 10.21, "А теперь извини, мне нужно немедленно поговорить об этом с Траллом!" } } } } },
    [832] = { d = 27.2, g = 1, v = "narrator", n = { m = 240, f = 240 }, c = { m = { { 0.00, "Слова из амулета плавно перетекают в ваш разум." }, { 3.64, "Газз'уз!" }, { 4.33, "Газз'уз, докладывай!" }, { 5.91, "О том, что ты нашёл в Скале Черепа, уже стало известно." }, { 10.10, "Готовься к нападению!" }, { 11.75, "Говори, Газз'уз!" }, { 13.06, "Говори, или я позабочусь о том, чтобы о твоём присутствии стало известно Нииру Огненному Клинку, а уж он-то тебя не пощадит!" }, { 22.54, "С Нииру тебе лучше не связываться..." }, { 25.36, "Газз'уз, ты меня слышишь?" } }, f = { { 0.00, "Слова из амулета плавно перетекают в ваш разум." }, { 3.55, "Газз'уз!" }, { 4.22, "Газз'уз, докладывай!" }, { 5.76, "О том, что ты нашла в Скале Черепа, уже стало известно." }, { 9.91, "Готовься к нападению!" }, { 11.51, "Говори, Газз'уз!" }, { 12.78, "Говори, или я позабочусь о том, чтобы о твоём присутствии стало известно Нииру Огненному Клинку, а уж он-то тебя не пощадит!" }, { 22.02, "С Нииру тебе лучше не связываться..." }, { 24.77, "Газз'уз, ты меня слышишь?" } } }, t = { d = 40.1, g = 1, v = "orc-male", n = { m = 349, f = 351 }, c = { m = { { 0.00, "*Нииру разглядывает Око Пылающей Тени.*" }, { 3.92, "Любопытно." }, { 4.83, "Так ты говоришь, голос упоминал моё имя?" }, { 8.24, "Я, конечно, известен как непримиримый враг противников нашего вождя, но всё же странно, что голос назвал именно меня." }, { 18.02, "Тем более странно, что название секты, у членов которой ты нашёл этот амулет, так похоже на мою фамилию." }, { 26.82, "Надо изучить эту подвеску." }, { 29.17, "Изучить и поразмыслить над тем, что значит это сообщение." }, { 33.94, "Спасибо, что сообщил мне об этом." }, { 36.75, "Ты оказал своему народу серьёзную услугу." } }, f = { { 0.00, "*Нииру разглядывает Око Пылающей Тени.*" }, { 3.92, "Любопытно." }, { 4.81, "Так ты говоришь, голос упоминал моё имя?" }, { 8.16, "Я, конечно, известен как непримиримый враг противников нашего вождя, но всё же странно, что голос назвал именно меня." }, { 17.75, "Тем более странно, что название секты, у членов которой ты нашла этот амулет, так похоже на мою фамилию." }, { 26.45, "Надо изучить эту подвеску." }, { 28.75, "Изучить и поразмыслить над тем, что значит это сообщение." }, { 33.44, "Спасибо, что сообщила мне об этом." }, { 36.26, "Ты оказала своему народу серьёзную услугу." } } } } },
    [833] = { d = 39.6, g = 1, v = "tauren-male#67", n = { x = 331 }, c = { m = { { 0.00, "Лишь самых доблестных тауренов хоронят в Красных скалах, на нашем священном кладбище." }, { 8.10, "Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утёс, и тем, кто отдал свои жизни на благо племени и вождей." }, { 20.90, "Похоже, теперь на эту священную землю пала тень." }, { 25.59, "Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их." }, { 34.89, "Против них поможет только сила, герой." } }, f = { { 0.00, "Лишь самых доблестных тауренов хоронят в Красных скалах, на нашем священном кладбище." }, { 8.30, "Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утёс, и тем, кто отдал свои жизни на благо племени и вождей." }, { 21.41, "Похоже, теперь на эту священную землю пала тень." }, { 26.22, "Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их." }, { 35.75, "Против них поможет только сила, героиня." } } }, t = { d = 10.1, g = 1, v = "tauren-male#67", n = { m = 90, f = 91 }, c = { m = { { 0.00, "Молодец." }, { 0.77, "Ты проучил племя Дыбогривов." }, { 3.25, "Теперь они дважды подумают, прежде чем осквернять святые для нас места." } }, f = { { 0.00, "Молодец." }, { 0.83, "Ты проучила племя Дыбогривов." }, { 3.58, "Теперь они дважды подумают, прежде чем осквернять святые для нас места." } } } } },
    [834] = { d = 35.1, v = "goblin-male", n = { x = 388 }, c = { x = { { 0.00, "Я – Резлак, один из ребят Газлоу." }, { 2.41, "Шеф послал меня на помощь оркам в Дуротаре." }, { 5.53, "Всё бы хорошо, если бы не проблемы с караванами." }, { 8.90, "Точнее, с охраной караванов." }, { 10.93, "Как ты думаешь, можно ли работать, когда караваны всё время грабят?" }, { 15.69, "Последний караван – они мне клялись, что он-то уж точно дойдёт! – перехватили гарпии Пыльного Ветра в... как же его..." }, { 23.95, "Каньоне Колючего Ветра!" }, { 25.67, "А мне этот груз позарез нужен, я без него как без рук!" }, { 29.42, "Ступай по большому каньону на юг, там будет расселина, идущая с запада на восток..." } } }, t = { d = 10.7, v = "goblin-male", n = { x = 104 }, c = { x = { { 0.00, "О, то что надо!" }, { 1.26, "Наши припасы!" }, { 2.44, "Замечательно." }, { 3.55, "Я смогу снова взяться за работу, как только найду кого-нибудь, кто донесёт мне эти мешки." } } } } },
    [835] = { d = 32.1, v = "goblin-male", n = { x = 351 }, c = { x = { { 0.00, "Газлоу мне как-то сказал: \"Резлак, запомни одну вещь: если хочешь, чтобы что-то было сделано хорошо, сделай это сам\"." }, { 8.82, "Мы не можем и дальше терять караваны." }, { 11.60, "Я вынужден взять дело в собственные руки." }, { 14.65, "Сухая лощина находится в восточной части Каньона Колючего Ветра." }, { 19.49, "Если перебить всех тамошних гарпий, дороги станут безопасными." }, { 24.14, "Разумеется, Газлоу учил меня и другому: \"За соответствующую плату тебе сделают что угодно\"." }, { 30.90, "Ну что, возьмёшься?" } } }, t = { d = 25.3, v = "goblin-male", n = { x = 293 }, c = { x = { { 0.00, "Ну всё, теперь нашим караванам больше ничто не угрожает!" }, { 4.03, "Наконец-то я вздохну свободно." }, { 6.21, "Твоя помощь пришлась как нельзя вовремя: со следующим караваном мне должны прислать партию занятных безделушек!" }, { 14.15, "Ты, своё дело знаешь." }, { 15.69, "Обратись к моему шефу в Кабестане." }, { 18.19, "У него наверняка найдётся для тебя работёнка." }, { 21.33, "Ах да, не беспокойся, разумеется, я тебе заплачу за труды!" } } } } },
    [836] = { d = 33.4, v = "gnome-male", n = { x = 375 }, c = { x = { { 0.00, "*Из робота снова раздаётся голос гнома:*" }, { 3.28, "\"Нужно вывести КПХ-девять/эйч-эл на открытое и безопасное место, чтобы он мог взять нужный разбег и взлететь." }, { 10.82, "У него есть система маскировки, но она, похоже, повреждена, поэтому вам придётся проводить цыплёнка до... ну, скажем, до побережья за Обзорными скалами!" }, { 21.19, "Местность там тихая и открытая, так что разбежаться он сумеет\"." }, { 25.52, "\"Пожалуйста, проводите робота на берег, а потом загляните ко мне в Пиратскую бухту." }, { 31.30, "Карлс Пропеллерз, конец связи\"." } } }, t = { d = 25.0, g = 1, v = "gnome-male", n = { m = 259, f = 262 }, c = { m = { { 0.00, "О, да ты просто спас моего робота КПХ-девять/эйч-эл!" }, { 3.76, "Я прям даже не знаю, как тебя благодарить!" }, { 6.86, "Моих автономных роботов ещё совершенствовать и совершенствовать, но ты избавил меня от многих лишних часов работы, а также от расходов!" }, { 16.68, "Пожалуйста, выбери себе что-нибудь в награду." }, { 20.05, "Спасибо тебе ещё раз, я и мои роботы навеки у тебя в долгу." } }, f = { { 0.00, "О, да ты просто спасла моего робота КПХ-девять/эйч-эл!" }, { 4.03, "Я прям даже не знаю, как тебя благодарить!" }, { 7.19, "Моих автономных роботов ещё совершенствовать и совершенствовать, но ты избавила меня от многих лишних часов работы, а также от расходов!" }, { 17.26, "Пожалуйста, выбери себе что-нибудь в награду." }, { 20.69, "Спасибо тебе ещё раз, я и мои роботы навеки у тебя в долгу." } } } } },
    [837] = { d = 37.7, v = "orc-male#60", n = { x = 382 }, c = { x = { { 0.00, "Когда мы поселились здесь, свинобразы Иглогривых владели большей частью этих земель и оказались сущей напастью!" }, { 9.06, "Большую их часть нам мало-помалу удалось вытеснить, но в некоторых районах они окопались прочно." }, { 16.87, "Однако, с нас довольно!" }, { 18.77, "Ради нашей безопасности мы не можем больше терпеть присутствие Иглогривых в наших землях." }, { 26.07, "Их лагеря – к западу отсюда." }, { 28.41, "Они часто прячутся в зарослях колючек." }, { 31.62, "Сегодня мы вытесним их из Дуротара – а завтра, глядишь, и из всего Калимдора!" } } }, t = { d = 17.2, v = "orc-male#60", n = { x = 165 }, c = { x = { { 0.00, "Я расскажу всем, что Иглогривы прогнаны со своих обжитых мест, и что их жилища надо сжечь." }, { 7.98, "Теперь, когда племя Иглогривых изгнано из Дуротара, границы нашей новой родины станут значительно безопаснее." } } } } },
    [838] = { d = 38.2, g = 1, v = "scourge-male", n = { m = 371, f = 372 }, c = { m = { { 0.00, "На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью Плети." }, { 8.60, "В её недрах наши враги спокойно проводят исследования, делаясь всё сильнее." }, { 14.99, "Путь преграждают двери, и без подходящего ключа внутрь не войти." }, { 20.31, "Аптекарь Дитерс многое знает о Некроситете и придумал, как достать ключ." }, { 26.40, "Ты зарекомендовал себя как человека с большими способностями, поэтому я доверяю тебе это задание." }, { 34.61, "Обсуди подробности с аптекарем." } }, f = { { 0.00, "На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью Плети." }, { 8.84, "В её недрах наши враги спокойно проводят исследования, делаясь всё сильнее." }, { 15.41, "Путь преграждают двери, и без подходящего ключа внутрь не войти." }, { 20.88, "Аптекарь Дитерс многое знает о Некроситете и придумал, как достать ключ." }, { 27.14, "Ты зарекомендовала себя как человека с большими способностями, поэтому я доверяю тебе это задание." }, { 35.66, "Обсуди подробности с аптекарем." } } }, t = { d = 29.4, g = 1, v = "scourge-male#82", n = { x = 251 }, c = { m = { { 0.00, "Да, герой." }, { 0.95, "Верховный палач упоминал, что тебе можно доверить тайну ключа." }, { 6.60, "В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ, позволяющий отомкнуть двери в любой момент." }, { 20.52, "Дело, как всегда, будет непростым." }, { 23.63, "Но судя по всему, тебя такими словами не напугать." } }, f = { { 0.00, "Да, героиня." }, { 1.16, "Верховный палач упоминал, что тебе можно доверить тайну ключа." }, { 7.05, "В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ, позволяющий отомкнуть двери в любой момент." }, { 21.56, "Дело, как всегда, будет непростым." }, { 24.80, "Но судя по всему, тебя такими словами не