    [840] = { d = 19.0, g = 1, v = "orc-male", n = { m = 179, f = 181 }, c = { m = { { 0.00, "Хм, слабаком тебя не назовёшь…" }, { 2.49, "Послушай, моему приятелю Каргалу нужны новобранцы для службы в Степях." }, { 8.45, "Ты ведь хочешь принести пользу Орде?" }, { 11.55, "Ну вот, это твой шанс." }, { 13.36, "Передай Каргалу это письмо о найме – возможно, он его подпишет." } }, f = { { 0.00, "Хм, слабенькой тебя не назовёшь…" }, { 2.67, "Послушай, моему приятелю Каргалу нужны новобранцы для службы в Степях." }, { 8.68, "Ты ведь хочешь принести пользу Орде?" }, { 11.80, "Ну вот, это твой шанс." }, { 13.63, "Передай Каргалу это письмо о найме – возможно, он его подпишет." } } }, t = { d = 14.8, v = "orc-male#60", n = { x = 130 }, c = { x = { { 0.00, "А, так тебя Такрин прислал?" }, { 2.49, "Он отличный разведчик, не знаю даже, что бы я без него делал…" }, { 7.96, "Письмо-то я подпишу, но на самом деле воины нам нужны не здесь, а в Перекрёстке." } } } } },
