    [842] = { d = 23.7, g = 1, v = "orc-male#60", n = { m = 242, f = 242 }, c = { m = { { 0.00, "Отнеси это подписанное письмо о найме в Перекрёсток." }, { 4.17, "Там всем заправляет – Сергра Чёрный Шип, лопни её шкура!" }, { 8.56, "Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое." }, { 15.90, "Тралл уверен, что она замечательная, но мне что-то так не кажется." }, { 21.08, "Так что разбирайся сам, парень..." } }, f = { { 0.00, "Отнеси это подписанное письмо о найме в Перекрёсток." }, { 4.19, "Там всем заправляет – Сергра Чёрный Шип, лопни её шкура!" }, { 8.59, "Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое." }, { 15.96, "Тралл уверен, что она замечательная, но мне что-то так не кажется." }, { 21.16, "Так что разбирайся сама, детка..." } } }, t = { d = 29.4, g = 1, v = "orc-female", n = { m = 275, f = 212 }, c = { m = { { 0.00, "Ладно." }, { 0.61, "Не хочешь есть свой хлеб в Орде даром?" }, { 3.80, "Что ж, дел у нас предостаточно." }, { 6.31, "Просто слушай внимательно и делай, что тебе скажут." }, { 10.73, "Имей в виду, я по глазам вижу, что у тебя на уме." }, { 14.99, "Наглости я не спущу!" }, { 16.74, "Тралл самолично заявил, что в Орде женщины во всём будут наравне с вами, мужиками." }, { 23.66, "Только попробуй проявить ко мне неуважение – узнаешь, почём фунт лиха!" } }, f = { { 0.00, "Ладно." }, { 0.56, "Не хочешь есть свой хлеб в Орде даром?" }, { 3.48, "Что ж, дел у нас предостаточно." }, { 5.78, "Просто слушай внимательно и делай, что тебе скажут." }, { 9.82, "Очень приятно видеть тебя здесь." }, { 12.39, "Тралл будет рад узнать, что всё больше таких девушек, как мы с тобой, стремятся сделать карьеру в Степях." } } } } },
    [843] = { d = 40.1, v = "tauren-male", n = { x = 370 }, c = { x = { { 0.00, "Ныне я брожу по дорогам родного края в одиночестве." }, { 4.70, "Дворфы Бейл Модана не чтят моих границ." }, { 8.26, "Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы." }, { 18.30, "Земли, некогда приютившие и питавшие моё племя, захвачены вредоносными дворфами." }, { 25.50, "Все попытки решить дело миром провалились." }, { 29.39, "Пришло время для решительных действий." }, { 32.87, "Выгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря." } } }, t = { d = 19.1, v = "tauren-male", n = { x = 172 }, c = { x = { { 0.00, "Хазгорм заслужил свою судьбу." }, { 2.77, "Мне нисколько его не жаль." }, { 5.13, "Он явился в наши края незванным." }, { 8.14, "Быть может, его смерть послужит предостережением тем, кто пытается нарушить наш покой." }, { 15.78, "Дай-ка я изучу записи этого дворфа..." } } } } },
    [844] = { d = 14.9, v = "orc-female", n = { x = 164 }, c = { x = { { 0.00, "Первое задание будет совсем простым." }, { 2.88, "Равнинные долгоноги, живущие к востоку отсюда, разоряют наши продовольственные склады – просто сил уже нет!" }, { 11.05, "Перебей несколько долгоногов и принеси мне их клювы." } } }, t = { d = 12.5, g = 1, v = "orc-female", n = { m = 135, f = 136 }, c = { m = { { 0.00, "Хорошо." }, { 0.62, "Долгоногов перебили, и нам будет проще доставлять продовольствие." }, { 5.56, "Надеюсь, и ты кое-чему научился, потому что следующая дичь не такая смирная, как долгоноги..." } }, f = { { 0.00, "Хорошо." }, { 0.61, "Долгоногов перебили, и нам будет проще доставлять продовольствие." }, { 5.46, "Надеюсь, и ты кое-чему научилась, потому что следующая дичь не такая смирная, как долгоноги..." } } } } },
    [845] = { d = 25.3, v = "orc-female", n = { x = 262 }, c = { x = { { 0.00, "Хотя жевры – не самые страшные звери в Степях, они посильнее равнинных долгоногов." }, { 6.52, "Не беспокойся, в своё время тебе и покрупнее дичь достанется, но пока тебе ещё надо малость поточить зубки." }, { 14.85, "Поохоться на жевр на севере и на юге и собери их копыта." }, { 19.27, "Принеси их мне, и, быть может, в следующий раз мы дадим тебе задание посерьёзнее." } } }, t = { d = 14.6, g = 1, v = "orc-female", n = { m = 141, f = 142 }, c = { m = { { 0.00, "Неплохо." }, { 0.76, "У жевр сильные ноги." }, { 2.50, "Одного меткого удара достаточно, чтобы отшвырнуть таурена в сторону!" }, { 8.35, "Похоже, в тебе тоже силы хватает." }, { 11.31, "Ну что, готов пройти настоящее испытание?" } }, f = { { 0.00, "Неплохо." }, { 0.75, "У жевр сильные ноги." }, { 2.49, "Одного меткого удара достаточно, чтобы отшвырнуть таурена в сторону!" }, { 8.30, "Похоже, в тебе тоже силы хватает." }, { 11.25, "Ну что, готова пройти настоящее испытание?" } } } } },
    [846] = { d = 37.3, v = "tauren-male", n = { x = 381 }, c = { x = { { 0.00, "Очевидно, что шахтёры не могут обойтись без взрывчатки и шумных землеройных машин." }, { 6.71, "Мы думаем, что скоро туда направят нового старшину." }, { 11.04, "Пусть проклятые дворфы отведают собственного угощения." }, { 15.51, "Согласно схемам, если смешать нитроглицерин с древесной сердцевиной и натриевой селитрой, получится взрывной заряд." }, { 25.06, "Все компоненты есть у ружейников, солдат и офицеров из Крепости." }, { 30.28, "Собери всё необходимое и принеси мне." }, { 33.33, "Я создам заряд, который дворфы не скоро забудут!" } } }, t = { d = 9.4, g = 1, v = "tauren-male", n = { m = 64, f = 65 }, c = { m = { { 0.00, "Вижу, ты зря времени не терял, герой." }, { 3.96, "Очень скоро дворфов ожидает неприятный сюрприз!" } }, f = { { 0.00, "Вижу, ты зря времени не теряла, героиня." }, { 4.33, "Очень скоро дворфов ожидает неприятный сюрприз!" } } } } },
    [847] = { d = 17.8, v = "orc-male#60", n = { x = 162 }, c = { x = { { 0.00, "Эта... эта сила..." }, { 1.67, "Это и есть мощь шаманов, которую Тор'Ган пытался мне показать?" }, { 6.91, "Должен сказать, весьма интересно." }, { 9.80, "Скажите Тор'Гану, что он меня убедил... на данный момент." }, { 14.65, "Я выслушаю то, что он хочет мне сказать." } } }, t = { d = 11.0, v = "troll-male#77", n = { x = 115 }, c = { x = { { 0.00, "Когда чары спадут, я поговорю с Гор'мулем." }, { 3.36, "Благодарю вас за помощь в возвращении Гор'муля к жизни." }, { 7.62, "Я не сомневаюсь, что и он очень благодарен вам." } } } } },
    [848] = { d = 29.0, v = "scourge-male", n = { x = 242 }, c = { x = { { 0.00, "Оазисы Степей таят в себе тайну." }, { 3.36, "В их водах разлита энергия жизни, питающая и укрепляющая растения и животных." }, { 10.98, "И меняющая их." }, { 12.40, "Неподалёку от этих оазисов растёт вид грибов, чьи споры мы, аптекари Лордерона, используем при создании снадобий." }, { 23.29, "Принеси мне эти споры – и благодарность наша будет велика." } } }, t = { d = 12.6, v = "scourge-male", n = { x = 91 }, c = { x = { { 0.00, "Ах, да." }, { 0.84, "Прекрасный материал." }, { 3.27, "Действенный." }, { 4.74, "Я из Отрёкшихся, а мы исполняем свои обещания." }, { 10.01, "Вот твоё вознаграждение." } } } } },
    [849] = { d = 38.2, v = "tauren-male", n = { x = 343 }, c = { x = { { 0.00, "Изучив схемы Хазгорма, можно без труда создать взрывчатку." }, { 5.34, "Ну вот, готово." }, { 6.71, "А теперь, я дам тебе особое задание." }, { 10.02, "Возьми взрывчатку и подорви летающую машину в Бейл Модане." }, { 15.28, "Эта машина не просто играет ключевую роль в снабжении раскопок, она служит и для военных целей." }, { 23.93, "И что ещё важнее – она воплощение мощи дворфов и оскорбление памяти моего племени." }, { 31.37, "Выполни это задание, и я буду гордиться тобой!" }, { 35.65, "Ну и награду ты тоже получишь." } } }, t = { d = 11.0, v = "tauren-male", n = { x = 106 }, c = { x = { { 0.00, "Отличная работа." }, { 1.55, "В Громовом Утёсе тебя будут чтить как защитника священных земель тауренов и поборника исчезнувшего племени." } } } } },
    [850] = { d = 35.3, v = "orc-male#60", n = { x = 383 }, c = { x = { { 0.00, "Сотни лет кентавры вставали на пути тауренов." }, { 3.56, "В последнее время клан Колкар начал всерьёз грозить безопасности Степей." }, { 9.15, "Раньше им мешала побеждать их собственная неорганизованность, но недавно среди них появились новые вожди." }, { 17.26, "Они создали из своих сородичей войско." }, { 20.34, "Чтобы сохранить наши земли, мы должны убить вождей кентавров." }, { 25.23, "Принеси мне голову Барака Кодобоя." }, { 27.95, "Он живёт в лагере неподалёку от Забытых прудов на севере." }, { 32.29, "Когда одержишь над ним верх, возвращайся." } } }, t = { d = 15.6, v = "orc-male#60", n = { x = 141 }, c = { x = { { 0.00, "Молодец." }, { 0.80, "Кентавры – примитивные и грубые создания, но некоторым из них была дарована мудрость и умение вести в бой." }, { 10.16, "Они-то опаснее прочих." }, { 12.24, "Барак таким и был." }, { 13.92, "Хорошо, что он мёртв." } } } } },
    [851] = { d = 32.3, v = "orc-male#60", n = { x = 340 }, c = { x = { { 0.00, "Кентавр Верог Дервиш бродит по Степям, и найти его будет нелегко." }, { 5.19, "Живёт же он в командном шатре кентавров, в Застывшем оазисе на юго-востоке." }, { 10.94, "Быть может, удастся заманить его туда." }, { 13.98, "Отправляйся в Застывший оазис и напади на кентавров рядом с командным шатром." }, { 19.94, "Это опасно, но если убить достаточно кентавров, кто-нибудь поднимет тревогу и явится Верог." }, { 27.07, "Принеси мне его голову, и я помещу её рядом с головой Барака Кодобоя." } } }, t = { d = 17.0, g = 1, v = "orc-male#60", n = { m = 171, f = 172 }, c = { m = { { 0.00, "Замечательно." }, { 1.14, "Видно, ты взбаламутил кентавров – стражи заметили необычную активность неподалёку от Застывшего оазиса." }, { 9.69, "Наверное, это твоя работа." }, { 12.04, "Можешь гордиться своим подвигом." }, { 14.84, "Ты необыкновенно отважен." } }, f = { { 0.00, "Замечательно." }, { 1.14, "Видно, ты взбаламутила кентавров – стражи заметили необычную активность неподалёку от Застывшего оазиса." }, { 9.81, "Наверное, это твоя работа." }, { 12.17, "Можешь гордиться своим подвигом." }, { 14.99, "Ты необыкновенно отважна." } } } } },
    [852] = { d = 27.3, g = 1, v = "orc-male#60", n = { m = 255, f = 257 }, c = { m = { { 0.00, "Хэрзул Кровавая Отметина – глава кентаврского клана Колкар в Степях." }, { 5.76, "Он свиреп, жесток и хитёр." }, { 7.93, "Одолев его, ты нанесёшь серьёзный урон всем Колкар, а значит, они станут меньше угрожать нам." }, { 15.63, "Итак, убей его." }, { 17.05, "Принеси мне его голову, как принёс головы Барака и Верога." }, { 21.91, "Он управляет своим народом из Цветущего оазиса на юге." } }, f = { { 0.00, "Хэрзул Кровавая Отметина – глава кентаврского клана Колкар в Степях." }, { 5.92, "Он свиреп, жесток и хитёр." }, { 8.15, "Одолев его, ты нанесёшь серьёзный урон всем Колкар, а значит, они станут меньше угрожать нам." }, { 16.06, "Итак, убей его." }, { 17.52, "Принеси мне его голову, как принесла головы Барака и Верога." }, { 22.75, "Он управляет своим народом из Цветущего оазиса на юге." } } }, t = { d = 14.9, g = 1, v = "orc-male#60", n = { m = 147, f = 148 }, c = { m = { { 0.00, "Хвала тебе." }, { 1.04, "Хотя кентаврам не хватает дисциплины, чтобы обрушить свою ярость на врагов, как орки, они всё равно свирепые противники." }, { 11.03, "Одержав над ними верх, ты доказал свою доблесть." } }, f = { { 0.00, "Хвала тебе." }, { 0.99, "Хотя кентаврам не хватает дисциплины, чтобы обрушить свою ярость на врагов, как орки, они всё равно свирепые противники." }, { 10.57, "Одержав над ними верх, ты доказала свою доблесть." } } } } },
    [853] = { d = 39.7, v = "scourge-male", n = { x = 395 }, c = { x = { { 0.00, "Я сделал эмульсию из принесённых тобой спор, и теперь мне нужно доставить её моей коллеге, аптекарю Заме." }, { 8.67, "Если ты отнесёшь ей мою посылку, она предложит тебе на выбор что-нибудь из своего запаса алхимических товаров." }, { 17.86, "Она живёт в Прудах Видений, пещере, расположенной ниже обиталища шаманов Громового Утёса." }, { 25.26, "Путь к этой пещере хорошо скрыт, но начинается он на Вершине Духов." }, { 30.79, "Поспеши." }, { 31.54, "Эмульсия хранится не очень долго, потому надо вскрыть и использовать её до того, как она испортится." } } }, t = { d = 15.7, g = 1, v = "scourge-female", n = { m = 128, f = 129 }, c = { m = { { 0.00, "А, споры, которые Хелбрим собрал в Степях." }, { 4.07, "Он заручился твоей помощью при сборе?" }, { 7.63, "Хорошо." }, { 8.39, "Эмульсия не успела испортиться, видать, ты время зря не тратил." }, { 14.32, "Молодец, герой." } }, f = { { 0.00, "А, споры, которые Хелбрим собрал в Степях." }, { 4.00, "Он заручился твоей помощью при сборе?" }, { 7.50, "Хорошо." }, { 8.26, "Эмульсия не успела испортиться, видать, ты время зря не тратила." }, { 14.18, "Молодец, героиня." } } } } },
    [854] = { d = 34.0, g = 1, v = "tauren-male#68", n = { m = 298, f = 299 }, c = { m = { { 0.00, "Я знал, что ты придёшь, юный герой." }, { 3.00, "Хотя, пожалуй, ты уже не так юн." }, { 5.84, "Думаю, тебе пора двинуться вглубь этих земель." }, { 10.02, "Я чую, что тебе предстоят великие свершения." }, { 13.96, "Ступай в Перекрёсток." }, { 15.77, "Наша судьба тесно связана с судьбой орков, а им нужна помощь." }, { 21.30, "Иди по дороге на восток, а потом сверни на север, к Перекрёстку." }, { 26.90, "Отыщи Торка в стенах города, ибо с ним пребывает благословение Матери-Земли." } }, f = { { 0.00, "Я знал, что ты придёшь, юная героиня." }, { 3.17, "Хотя, пожалуй, ты уже не так юна." }, { 6.18, "Думаю, тебе пора двинуться вглубь этих земель." }, { 10.38, "Я чую, что тебе предстоят великие свершения." }, { 14.35, "Ступай в Перекрёсток." }, { 16.17, "Наша судьба тесно связана с судьбой орков, а им нужна помощь." }, { 21.72, "Иди по дороге на восток, а потом сверни на север, к Перекрёстку." }, { 27.34, "Отыщи Торка в стенах города, ибо с ним пребывает благословение Матери-Земли." } } }, t = { d = 7.4, v = "orc-male#60", n = { x = 70 }, c = { x = { { 0.00, "Я рад, что нам на помощь прибыли союзники из самого Громового Утёса." }, { 5.98, "Добро пожаловать!" } } } } },
    [855] = { d = 19.7, v = "orc-male#60", n = { x = 203 }, c = { x = { { 0.00, "Клан Колкар угрожает завоеваниям Орды в Степях." }, { 3.79, "Мы должны сократить численность их войск." }, { 7.02, "В связи с этим у меня есть для тебя задание." }, { 10.60, "Отправляйся в земли Колкар, перебей их воинов и принеси мне их наручи." }, { 16.18, "Возвращайся с трофеями, и Орда тебя наградит." } } }, t = { d = 19.0, v = "orc-male#60", n = { x = 185 }, c = { x = { { 0.00, "Неплохо." }, { 0.75, "Уверен, тебе удалось вселить страх в выживших кентавров." }, { 5.47, "Если Колкар не полные идиоты, теперь они успокоятся и прекратят наступление." }, { 11.92, "К сожалению, вряд ли им на это хватит ума." }, { 15.44, "Что весьма плохо." }, { 16.94, "Плохо для них, разумеется." } } } } },
    [857] = { d = 39.4, v = "dwarf-male", n = { x = 393 }, c = { x = { { 0.00, "Она была у меня в руках!" }, { 2.06, "В этих самых руках!" }, { 3.70, "И я хочу вернуть её!" }, { 5.33, "Вернуть, говорю!" }, { 6.68, "Её откопали эти грязные землекопы... и как она была прекрасна." }, { 11.66, "Её назвали слеза Лун." }, { 13.36, "Первое серьёзное открытие в Бейл Модане." }, { 16.49, "Она должна достаться мне!" }, { 18.55, "Мне, говорю!" }, { 19.55, "Генерал Двукосса позавидовал силе, которую она мне давала, и запер её в Крепости." }, { 26.01, "Сказал, что эта вещь проклята." }, { 28.43, "Дурак!" }, { 29.00, "Её хотели заполучить и другие, мне пришлось их остановить." }, { 33.55, "А этот ублюдок Двукосса прогнал меня." }, { 36.61, "А я хочу её вернуть." }, { 38.24, "Вернуть, говорю!" } } }, t = { d = 4.5, v = "dwarf-male", n = { x = 36 }, c = { x = { { 0.00, "Наконец-то сила снова со мной!" }, { 3.04, "Со мной, говорю!" } } } } },
    [858] = { d = 25.4, v = "goblin-male", n = { x = 316 }, c = { x = { { 0.00, "Тебя случайно не Пароклапан прислал?" }, { 2.41, "У меня проблемы." }, { 3.53, "Я запрыгнул внутрь, не подумав, что для запуска резака нужен ключ." }, { 7.76, "Один из операторов спросил меня, всё ли в порядке, и я впал в панику!" }, { 12.23, "Вместо того чтобы сказать, что я потерял ключ, я заявил, что резак неисправен." }, { 17.35, "Надо поскорее выбираться отсюда!" }, { 19.52, "Поднимись в комнату управления на вышке, у бригадира должен быть ключ от резака." }, { 24.70, "Выручи меня!" } } }, t = { d = 25.8, v = "goblin-male", n = { x = 253 }, c = { x = { { 0.00, "Ага, похоже, ключ подходит." }, { 2.28, "Ну-ка, знаю ли я, как управлять этой штуковиной…" }, { 6.24, "Хм..." }, { 6.68, "Управление вращением..." }, { 8.59, "Этот рычаг отвечает за скорость и равновесие..." }, { 12.48, "Управление манипулятором." }, { 14.53, "Ну и ну!" }, { 15.19, "Поверить не могу, что Торговая Компания создала устройство, которое настолько лучше нашего." }, { 22.68, "Надо доставить этот резак в Кабестан!" } } } } },
    [860] = { d = 39.9, v = "tauren-male#68", n = { x = 372 }, c = { x = { { 0.00, "Ежели хочешь вступить на путь охотника, то тогда тебе надо идти в Степи." }, { 6.42, "Тамошние твари упрямы и яростны." }, { 9.32, "Охотясь там, ты многому научишься, и дух твой окрепнет." }, { 14.01, "Поговори с Сергрой Чёрный Шип." }, { 16.59, "Она будет первой твоей наставницей в Степях." }, { 20.59, "Сергра сейчас в Перекрёстке." }, { 23.01, "Чтобы туда добраться, иди на восток от Деревни Кровавого Копыта прямиком в Степи, затем на развилке сверни на север." }, { 33.27, "И по дороге держи ухо востро – Степи весьма опасны для неопытных и беспечных." } } }, t = { d = 22.8, v = "orc-female", n = { x = 222 }, c = { x = { { 0.00, "Хочешь охотиться в Степях?" }, { 2.26, "Глаза у тебя горячие и молодые." }, { 4.97, "Они ещё не окосели от выслеживания добычи на тутошних пыльных равнинах." }, { 10.91, "Но ты не бойся." }, { 12.19, "Мы закалим твоё тело и дух!" }, { 14.45, "И растолкуем, что охота – не просто выслеживание и добыча." }, { 19.27, "Готовься." }, { 20.10, "Твой путь начинается прямо сейчас." } } } } },
    [861] = { d = 41.8, g = 1, v = "tauren-male", n = { m = 371, f = 369 }, c = { m = { { 0.00, "Вижу, ты любишь путешествовать." }, { 2.83, "Когда-то и меня обуревала жажда странствий…" }, { 6.79, "Странствий и охоты." }, { 8.56, "Ведь охота – первая доблесть таурена." }, { 11.96, "Если ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги." }, { 21.81, "Он живёт в Громовом Утёсе, на Вершине Охотников." }, { 26.01, "Чтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья." }, { 33.20, "Эти звери сильны и хитры – подходящая добыча для молодого героя, избравшего путь охотника." } }, f = { { 0.00, "Вижу, ты любишь путешествовать." }, { 2.87, "Когда-то и меня обуревала жажда странствий…" }, { 6.88, "Странствий и охоты." }, { 8.68, "Ведь охота – первая доблесть таурена." }, { 12.12, "Если ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги." }, { 22.11, "Он живёт в Громовом Утёсе, на Вершине Охотников." }, { 26.36, "Чтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья." }, { 33.65, "Эти звери сильны и хитры – подходящая добыча для молодой героини, избравшей путь охотника." } } }, t = { d = 27.8, v = "tauren-male#68", n = { x = 237 }, c = { x = { { 0.00, "Скорн Белое Облако – мудрый таурен." }, { 3.33, "Он посвятил охоте много лет, и хотя уже слаб телом, дух его по-прежнему бодр." }, { 10.50, "Мы высоко чтим его." }, { 12.33, "Если тебя и правда прислал Скорн, то он разглядел в тебе будущего охотника." }, { 19.34, "Добыть же эти когти было непросто, я знаю." }, { 23.42, "Быть может, тебе пора вступить на избранный путь." } } } } },
