    [864] = { d = 28.2, v = "goblin-male", n = { x = 300 }, c = { x = { { 0.00, "Ну вот, источник энергии извлечён, и твои данные сохранились." }, { 5.19, "Что ж, счастливого пути и всё такое." }, { 8.29, "Надеюсь, зловещий научный эксперимент удался." }, { 12.16, "*Гоблин отворачивается от вас и погружается в дела Водной компании Прибамбасска.*" }, { 18.17, "*Вы кладёте запечатанный набор для испытаний в надёжное место и готовитесь отбыть в Подгород.*" }, { 25.07, "*Вас и запечатанный набор ждёт аптекарь Зинг.*" } } }, t = { d = 27.4, g = 1, v = "scourge-female", n = { m = 241, f = 241 }, c = { m = { { 0.00, "Я немедленно займусь анализом данных." }, { 3.48, "Быть может, безумие Чанна обернётся моей гениальностью." }, { 8.54, "Что до тебя..." }, { 9.86, "Ты мне полезен, а я хорошо обращаюсь с полезными существами." }, { 15.33, "Прими эту вещь, эти монетки, а в придачу к ним – мою благодарность." }, { 21.55, "Заглядывай время от времени – думаю, что мы ещё поработаем вместе." } }, f = { { 0.00, "Я немедленно займусь анализом данных." }, { 3.37, "Быть может, безумие Чанна обернётся моей гениальностью." }, { 8.26, "Что до тебя..." }, { 9.55, "Ты мне полезна, а я хорошо обращаюсь с полезными существами." }, { 14.84, "Прими эту вещь, эти монетки, а в придачу к ним – мою благодарность." }, { 20.86, "Заглядывай время от времени – думаю, что мы ещё поработаем вместе." } } } } },
    [865] = { d = 25.8, v = "goblin-male", n = { x = 268 }, c = { x = { { 0.00, "Ящеры Степей умнее, чем прочие." }, { 2.50, "Мне кажется, весь ум в рогах!" }, { 4.73, "Если так, эти рога можно стереть в порошок и сделать из них \"умный напиток\"." }, { 10.70, "Я мог бы продавать его за баснословные деньги!" }, { 14.25, "Ты можешь мне помочь." }, { 15.91, "Принеси мне целые рога ящерочешуйчатых смертехватов." }, { 19.94, "Они живут в южной части Степей и на севере, рядом с границей Ясеневого леса." } } }, t = { d = 7.3, v = "goblin-male", n = { x = 67 }, c = { x = { { 0.00, "Здорово, тебе удалось их добыть!" }, { 2.87, "Остаётся стереть рога в порошок, смешать с вином и..." } } } } },
    [866] = { d = 26.8, v = "goblin-male", n = { x = 310 }, c = { x = { { 0.00, "Таких трав, как в Степях, нет нигде." }, { 2.51, "Свойства у них по большей части те же, но вода оазисов оказывает на них особое влияние, и они всё же отличаются от подобных им, хоть и не сильно." }, { 12.44, "Я хочу выяснить, в чём же состоит разница... и нельзя ли ей воспользоваться!" }, { 17.65, "Если ты владеешь искусством травничества, собери для меня образцы корней растений Степей, и я сравню их с травами из других регионов." } } }, t = { d = 19.0, g = 1, v = "goblin-male", n = { m = 188, f = 188 }, c = { m = { { 0.00, "Да-да, замечательно!" }, { 1.65, "Из этих корней я выращу травы и смогу изучить их." }, { 5.67, "Надеюсь отыскать в них новые свойства." }, { 8.75, "Скрытые ценные свойства..." }, { 10.91, "И не беспокойся – ты узнаешь об этом первым." }, { 14.42, "Потому что в таком случае мне понадобится много корней!" } }, f = { { 0.00, "Да-да, замечательно!" }, { 1.67, "Из этих корней я выращу травы и смогу изучить их." }, { 5.74, "Надеюсь отыскать в них новые свойства." }, { 8.87, "Скрытые ценные свойства..." }, { 11.05, "И не беспокойся – ты узнаешь об этом первой." }, { 14.61, "Потому что в таком случае мне понадобится много корней!" } } } } },
    [867] = { d = 34.0, v = "orc-male", n = { x = 348 }, c = { x = { { 0.00, "Нет сил терпеть нападения на наши караваны со съестными припасами." }, { 5.36, "Пора сократить число проклятых гарпий, перерезав горло десятку-другому." }, { 11.31, "Я пробрался к их гнёздам и выяснил, кто есть кто." }, { 15.13, "Начать надо с низов, а потом постепенно пробиваться наверх." }, { 20.05, "Для начала займись гарпиями и разбойницами из стаи Зачарованного Крыла, поселившимися на северо-западе, и принеси мне восемь когтей Зачарованного Крыла." }, { 32.39, "Будет уже неплохо..." } } }, t = { d = 10.7, v = "orc-male", n = { x = 100 }, c = { x = { { 0.00, "Прекрасные когти." }, { 1.64, "Чудные." }, { 2.37, "Отличная работа." }, { 3.93, "Надеюсь, в ближайшем будущем мне снова доведётся полюбоваться на твою работу." } } } } },
    [868] = { d = 33.8, v = "troll-male#78", n = { x = 376 }, c = { x = { { 0.00, "Эй." }, { 0.27, "Меня отправили в Перекрёсток присматривать за этими землями и сообщать начальству в Оргриммаре, что тут творится." }, { 8.48, "В частности, мне велено наблюдать за насекомовидными тварями на юге в Полях Великанов." }, { 14.82, "Нам о них почти ничего не известно, а я хотел бы узнать о них побольше." }, { 20.02, "Кажется, они умнее обычных животных." }, { 22.83, "Возьми вспарывающий коготь и принеси несколько яиц этих тварей из их курганов, но будь осторожнее: они нападут на тебя, если заметят, что ты творишь." } } }, t = { d = 4.6, v = "troll-male#78", n = { x = 36 }, c = { x = { { 0.00, "Порадовал ты меня." }, { 1.87, "Молодец." }, { 2.77, "Вот твоя награда..." } } } } },
    [869] = { d = 30.4, v = "orc-male", n = { x = 291 }, c = { x = { { 0.00, "Недавно из сторожевой башни был похищен груз серебра." }, { 4.47, "Он предназначался в уплату стражам Перекрёстка, и его необходимо вернуть." }, { 10.54, "Самое странное... одного из воров мы поймали с поличным." }, { 15.32, "И... это оказался ящер!" }, { 17.36, "Немыслимо!" }, { 18.27, "Не знаю, зачем ящерам серебро." }, { 20.93, "Мне всё равно: главное, чтобы у нас не воровали." }, { 24.95, "Пусть сдохнут!" }, { 26.16, "Отправляйся на охоту в Степи." }, { 28.66, "Принеси мне их головы!" } } }, t = { d = 7.0, g = 1, v = "orc-male", n = { m = 48, f = 48 }, c = { m = { { 0.00, "Тебе удалось избавить нас от ящеров!" }, { 3.59, "Спасибо." }, { 4.47, "Ты – достойный герой." } }, f = { { 0.00, "Тебе удалось избавить нас от ящеров!" }, { 3.80, "Спасибо." }, { 4.72, "Ты – достойная героиня." } } } } },
    [870] = { d = 47.9, v = "tauren-male", n = { x = 415 }, c = { x = { { 0.00, "Давным-давно Степи были цветущим садом, полным жизни." }, { 5.23, "Но этих земель коснулась карающая десница войны и катаклизма, обратив их в высохшую пустыню." }, { 14.06, "Это наполняет моё сердце грустью, но так уж получилось." }, { 19.29, "Впрочем, в последние годы в Степях образовалось несколько новых оазисов, а в них появилась жизнь." }, { 28.46, "Мы, друиды, чувствуем, что из глубины к поверхности рвётся какая-то сила." }, { 35.31, "Мы должны обнаружить её источник." }, { 38.49, "Отправляйся к Забытым прудам, к северу от Перекрёстка." }, { 43.54, "Отыщи в воде источник силы и возвращайся сюда." } } }, t = { d = 17.0, g = 1, v = "tauren-male", n = { m = 144, f = 144 }, c = { m = { { 0.00, "Там есть расселина, из которой выходят пузырьки газа?" }, { 5.08, "Странно." }, { 5.94, "Может быть, это и есть ответ на наши вопросы, но уверенности нет." }, { 12.13, "Впрочем, хоть какая-то зацепка." }, { 15.14, "Спасибо, что нашёл её." } }, f = { { 0.00, "Там есть расселина, из которой выходят пузырьки газа?" }, { 4.98, "Странно." }, { 5.82, "Может быть, это и есть ответ на наши вопросы, но уверенности нет." }, { 11.90, "Впрочем, хоть какая-то зацепка." }, { 14.85, "Спасибо, что нашла её." } } } } },
    [871] = { d = 35.8, v = "orc-male#60", n = { x = 378 }, c = { x = { { 0.00, "Все свинобразы – наши враги." }, { 2.23, "Просто одни из них причиняют нам больше неприятностей, чем другие." }, { 7.32, "Клан Иглогривых в последнее время нередко нападает на наши караваны из Дуротара, и терпеть это нет больше сил." }, { 15.83, "Мои разведчики ищут главарей, но тем временем чем больший урон мы нанесём этим свиньям, тем лучше." }, { 23.44, "Ступай на северо-восток, по направлению к Дуротару." }, { 27.41, "Ты легко отыщешь их логова среди огромных колючих побегов, исходящих из земли." }, { 33.55, "Отыщи их и убей, кого сможешь." } } }, t = { d = 7.8, v = "orc-male#60", n = { x = 67 }, c = { x = { { 0.00, "Отличная работа." }, { 1.71, "Мерзавцы-иглогривы наконец-то научатся считаться с мощью Орды." } } } } },
    [872] = { d = 32.2, v = "orc-male#60", n = { x = 349 }, c = { x = { { 0.00, "Один из разведчиков своими глазами видел нападение на караван из Дуротара." }, { 5.79, "Естественно, виноваты свинобразы из племени Иглогривых." }, { 10.05, "Возглавляет нападения Криниг Грознорыл." }, { 13.12, "Его видели на северо-востоке отсюда, южнее дороги на Дуротар." }, { 18.01, "Пока Криниг жив, покоя не будет." }, { 20.59, "Но чтобы окончательно прекратить разбой, надо как следует унизить мерзких иглогривов." }, { 27.22, "Убей Кринига Грознорыла и его приспешников и принеси мне его клык." } } }, t = { d = 8.6, v = "orc-male#60", n = { x = 82 }, c = { x = { { 0.00, "Молодец." }, { 0.80, "Криниг мёртв, и число нападений на караваны сократится." }, { 5.68, "Твой народ должен гордиться тобой." } } } } },
    [873] = { d = 37.8, g = 1, v = "tauren-female", n = { m = 328, f = 329 }, c = { m = { { 0.00, "Великий Иша Авак – повелитель этих вод." }, { 3.66, "Велика его сила, несокрушима гордость." }, { 7.24, "Народ побережья страшится его, ибо он поглотил многих из их числа." }, { 13.35, "Но я не боюсь его." }, { 15.05, "Я благодарна провидению за то, что он есть." }, { 18.80, "Бросить ему вызов – высокая честь, ибо он достойный противник." }, { 24.49, "Если ты готов, плыви на поиски Иши Авака, Рока Глубин." }, { 29.62, "Его дух содержится в сердце, и услышав, как оно бьётся, можно узнать многое о своей судьбе." } }, f = { { 0.00, "Великий Иша Авак – повелитель этих вод." }, { 3.58, "Велика его сила, несокрушима гордость." }, { 7.09, "Народ побережья страшится его, ибо он поглотил многих из их числа." }, { 13.06, "Но я не боюсь его." }, { 14.74, "Я благодарна провидению за то, что он есть." }, { 18.40, "Бросить ему вызов – высокая честь, ибо он достойный противник." }, { 23.98, "Если ты готова, плыви на поиски Иши Авака, Рока Глубин." }, { 29.07, "Его дух содержится в сердце, и услышав, как оно бьётся, можно узнать многое о своей судьбе." } } }, t = { d = 12.1, v = "tauren-female", n = { x = 94 }, c = { x = { { 0.00, "Теперь вы с Ишей Аваком едины." }, { 3.20, "Его дух живёт в тебе." }, { 5.39, "Он таится в твоих глазах…" }, { 8.05, "Глазах, которые однажды научатся видеть." } } } } },
    [874] = { d = 31.3, g = 1, v = "tauren-male#67", n = { m = 269, f = 270 }, c = { m = { { 0.00, "Ты поохотился на многих зверей Степей." }, { 3.50, "Дух твой твёрд." }, { 4.81, "Но охотник должен быть готов ко всему, его не смутит никакой путь." }, { 10.84, "Горы и болота не испугают его." }, { 13.69, "И даже море." }, { 14.92, "Найди мою сестру, Марен." }, { 17.28, "Она охотится на огромных водных тварей на побережье и многому научит тебя." }, { 24.13, "Ищи её с осторожностью, потому что побережье Степей захвачено людьми." } }, f = { { 0.00, "Ты поохотилась на многих зверей Степей." }, { 3.70, "Дух твой твёрд." }, { 5.04, "Но охотник должен быть готов ко всему, его не смутит никакой путь." }, { 11.27, "Горы и болота не испугают его." }, { 14.21, "И даже море." }, { 15.47, "Найди мою сестру, Марен." }, { 17.91, "Она охотится на огромных водных тварей на побережье и многому научит тебя." }, { 24.97, "Ищи её с осторожностью, потому что побережье Степей захвачено людьми." } } }, t = { d = 13.7, g = 1, v = "tauren-female", n = { m = 136, f = 137 }, c = { m = { { 0.00, "Тебя прислал мой брат?" }, { 1.84, "Должно быть, ты произвёл на него впечатление." }, { 5.44, "А если тебя зауважал Джорн, то и я буду уважать." }, { 9.41, "Желаешь ли ты сделать следующий шаг на пути охотника?" } }, f = { { 0.00, "Тебя прислал мой брат?" }, { 1.83, "Должно быть, ты произвела на него впечатление." }, { 5.56, "А если тебя зауважал Джорн, то и я буду уважать." }, { 9.51, "Желаешь ли ты сделать следующий шаг на пути охотника?" } } } } },
    [875] = { d = 35.0, g = 1, v = "orc-male", n = { m = 355, f = 356 }, c = { m = { { 0.00, "Ха-ха-ха." }, { 0.80, "Ещё захотелось?" }, { 2.04, "Отлично, приятно слышать." }, { 4.16, "На сей раз я хочу, чтобы ты убил несколько лейтенантов гарпий в Сухих холмах." }, { 10.44, "Лейтенантами бывают только душегубки из стаи Зачарованного Крыла." }, { 15.77, "Их можно отличить от других по характерным кольцам." }, { 19.93, "Неприятные твари, да ещё и приспешников их там полно." }, { 24.17, "Убей шестерых и нанеси мощный удар по этому бабьему царству." }, { 29.21, "И пусть подыхают долго и мучительно." }, { 32.13, "Это научит их не связываться с Ордой." } }, f = { { 0.00, "Ха-ха-ха." }, { 0.80, "Ещё захотелось?" }, { 2.04, "Отлично, приятно слышать." }, { 4.14, "На сей раз я хочу, чтобы ты убила несколько лейтенантов гарпий в Сухих холмах." }, { 10.47, "Лейтенантами бывают только душегубки из стаи Зачарованного Крыла." }, { 15.78, "Их можно отличить от других по характерным кольцам." }, { 19.92, "Неприятные твари, да ещё и приспешников их там полно." }, { 24.14, "Убей шестерых и нанеси мощный удар по этому бабьему царству." }, { 29.15, "И пусть подыхают долго и мучительно." }, { 32.06, "Это научит их не связываться с Ордой." } } }, t = { d = 6.6, v = "orc-male", n = { x = 62 }, c = { x = { { 0.00, "Прекрасная работа, дружище." }, { 2.51, "Думаю, ты достигнешь высокого положения в Орде." } } } } },
    [876] = { d = 35.0, g = 1, v = "orc-male", n = { m = 373, f = 374 }, c = { m = { { 0.00, "Ты так хорошо справился с лейтенантами и приспешниками, что я хочу дать тебе ещё одно поручение." }, { 7.38, "Серена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар." }, { 15.31, "Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры." }, { 21.99, "Перережь ей горло и принеси мне её голову." }, { 25.29, "Я хочу прибить её на переднюю телегу следующего каравана..." }, { 29.92, "Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас." } }, f = { { 0.00, "Ты так хорошо справилась с лейтенантами и приспешниками, что я хочу дать тебе ещё одно поручение." }, { 7.31, "Серена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар." }, { 15.11, "Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры." }, { 21.66, "Перережь ей горло и принеси мне её голову." }, { 24.90, "Я хочу прибить её на переднюю телегу следующего каравана..." }, { 29.46, "Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас." } } }, t = { d = 17.8, v = "orc-male", n = { x = 164 }, c = { x = { { 0.00, "ХА!" }, { 0.32, "Молодец!" }, { 1.11, "Отличная работа..." }, { 2.76, "Я не был уверен, что ты справишься с заданием, но, оказывается, ты головорез, каких поискать." }, { 10.74, "Ещё раз спасибо за избавление от нашествия гарпий." }, { 15.08, "Вот награда, используй её с умом." } } } } },
    [877] = { d = 32.1, v = "tauren-male", n = { x = 286 }, c = { x = { { 0.00, "Быть может, и в других оазисах Степей есть расселины вроде той, что тебе удалось обнаружить в Забытых прудах?" }, { 9.80, "Коли так, скорее всего именно эти расселины – источник жизни оазисов." }, { 16.20, "Надо проверить." }, { 17.66, "Вот, возьми эти семена." }, { 19.85, "Сейчас они мёртвые и бесплодные." }, { 22.76, "Отнеси их в Застывший оазис на юго-востоке." }, { 26.73, "Если там есть расселина, помести в неё семена... и понаблюдай." } } }, t = { d = 15.8, v = "tauren-male", n = { x = 143 }, c = { x = { { 0.00, "Удивительное открытие!" }, { 2.07, "Я дал тебе иссохшие, мёртвые семена." }, { 5.39, "Значит, то, что таится в этих оазисах, создаёт жизнь из ничего!" }, { 11.11, "Необходимо исследовать это явление повнимательнее..." } } } } },
    [878] = { d = 41.4, v = "named/3430", n = { x = 358 }, c = { x = { { 0.98, "Отомсти моим врагам." }, { 4.42, "Помоги Кривозубу и Иглогривым, ослабив племя Дыбогривов." }, { 9.83, "Оба племени духовно связаны с землёй и её мощью." }, { 15.56, "Она дарует нам силу, необходимую для всего... и прежде всего – для войны." }, { 21.73, "Если ты в самом деле хочешь узнать, кто причинил Торку и Орде так много страданий, помоги Кривозубу!" }, { 30.24, "Напади на духовных вождей Дыбогривов на севере; подорви их мощь, чтобы Иглогривые одолели своих соперников и покорили Степи." } } }, t = { d = 31.8, g = 1, v = "named/3430", n = { x = 254 }, c = { m = { { 0.60, "Да-да..." }, { 1.40, "Меня должна переполнять радость, ведь племя Дыбогривов испытало ту же боль, что и мой народ, герой." }, { 10.10, "Но нет, радости нет места." }, { 12.41, "Ты помогаешь своим, и они чтят тебя." }, { 15.68, "Кривозуб помогает своим – и что же?" }, { 18.79, "Они отвернулись от него." }, { 21.03, "Его забыли, оставили гнить в клетке!" }, { 24.30, "Я помогал им даже из-за решётки, но никто не пришёл мне на помощь!" } }, f = { { 0.63, "Да-да..." }, { 1.44, "Меня должна переполнять радость, ведь племя Дыбогривов испытало ту же боль, что и мой народ, героиня." }, { 10.46, "Но нет, радости нет места." }, { 12.82, "Ты помогаешь своим, и они чтят тебя." }, { 16.16, "Кривозуб помогает своим – и что же?" }, { 19.33, "Они отвернулись от него." }, { 21.60, "Его забыли, оставили гнить в клетке!" }, { 24.94, "Я помогал им даже из-за решётки, но никто не пришёл мне на помощь!" } } } } },
    [879] = { d = 45.9, g = 1, v = "named/3430", n = { x = 386 }, c = { m = { { 0.51, "Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, герой." }, { 8.11, "Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрёстке и в большей части Степей воцарится мир..." }, { 19.45, "по крайней мере, племя Иглогривых не будет на вас нападать." }, { 24.23, "Имена этих главарей – Нак, Куз и Лок Оркобой." }, { 28.37, "Они укрылись на юге Степей." }, { 31.02, "Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем –" }, { 40.42, "воин." }, { 41.03, "Убей их, герой, как они убили меня." } }, f = { { 0.51, "Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, героиня." }, { 8.43, "Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрёстке и в большей части Степей воцарится мир..." }, { 19.05, "по крайней мере, племя Иглогривых не будет на вас нападать." }, { 23.67, "Имена этих главарей – Нак, Куз и Лок Оркобой." }, { 27.80, "Они укрылись на юге Степей." }, { 30.45, "Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем –" }, { 39.82, "воин." }, { 40.47, "Убей их, героиня, как они убили меня." } } }, t = { d = 17.6, g = 1, v = "named/3430", n = { x = 139 }, c = { m = { { 0.51, "Дело сделано." }, { 1.69, "Кривозуб считает, уж лучше так." }, { 5.55, "Надо было убедиться" }, { 8.81, "что я мёртв, а не бросать меня здесь, во всеми забытой клетке." }, { 13.50, "Тебе осталось лишь одно дело, герой." } }, f = { { 0.51, "Дело сделано." }, { 1.66, "Кривозуб считает, уж лучше так." }, { 5.47, "Надо было убедиться" }, { 8.73, "что я мёртв, а не бросать меня здесь, во всеми забытой клетке." }, { 13.38, "Тебе осталось лишь одно дело, героиня." } } } } },
    [880] = { d = 29.4, v = "tauren-male", n = { x = 265 }, c = { x = { { 0.00, "Ты рассказываешь невероятные вещи." }, { 3.19, "Источник свойств этих оазисов явно сторонний." }, { 7.46, "Или, быть может, вообще потусторонний." }, { 11.07, "Я хочу узнать, какое влияние расселины оказывают на зверей, приходящих на водопой." }, { 18.79, "Убей несколько оазисных хрустогрызов в Цветущем и Застывшем оазисах." }, { 25.16, "Принеси мне их панцири, и я их пристально изучу." } } }, t = { d = 20.1, v = "tauren-male", n = { x = 175 }, c = { x = { { 0.00, "Спасибо." }, { 0.83, "Изучая обитателей различных мест, узнаешь немало о самих местах." }, { 6.78, "Посмотрим, о чём нам поведают панцири." }, { 10.25, "Прошу тебя, прими благодарность за помощь..." }, { 14.38, "Быть может, эти монеты тебе не помешают." }, { 18.18, "Мне они уже не нужны." } } } } },
    [881] = { d = 42.0, v = "orc-female", n = { x = 450 }, c = { x = { { 0.00, "Ичияки, Белый Туман на языке тауренов, король кошачьих саванны." }, { 4.97, "Он подкрадывается к жертвам так незаметно, что его уподобили белому туману, стелющемуся над землёй." }, { 12.44, "Убивает он одним ударом – жертва не успевает ни испугаться, ни ощутить боли." }, { 18.31, "Таурены говорят, что он воплощает собой милосердие и смерть." }, { 22.87, "Ты узнаешь это на своём опыте, потому что я отправляю тебя охотиться на Ичияки." }, { 28.95, "Его логово располагается на северо-востоке от Перекрёстка, среди костей огромного кодо." }, { 35.65, "Ступай." }, { 36.28, "Добравшись до логова, протруби в этот рог." }, { 39.52, "Протруби в рог, и он явится на зов." } } }, t = { d = 19.7, g = 1, v = "orc-female", n = { x = 191 }, c = { m = { { 0.00, "Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой." }, { 9.12, "Он научит тебя обретать силу в хитрости, а честь в милосердии." }, { 14.11, "Перед тобой долгий путь, герой." }, { 16.71, "Хочется верить, что ты далеко пойдёшь." } }, f = { { 0.00, "Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой." }, { 9.09, "Он научит тебя обретать силу в хитрости, а честь в милосердии." }, { 14.06, "Перед тобой долгий путь, героиня." }, { 16.80, "Хочется верить, что ты далеко пойдёшь." } } } } },
    [882] = { d = 46.3, g = 1, v = "tauren-male#67", n = { m = 400, f = 401 }, c = { m = { { 0.00, "Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей." }, { 7.30, "Он охотится не ради еды и не для удовольствия." }, { 11.58, "Охота – его страсть." }, { 13.51, "Он убивает потому, что сам убийца по природе." }, { 17.70, "Именно о его природе тебе и предстоит узнать многое, ибо твой путь теперь поведёт тебя по когтистым следам Ишамухала." }, { 28.70, "Начинай охоту." }, { 30.12, "Убей его излюбленную добычу – жевру – и принеси её тушу к мёртвому дереву на северо-западе от Кабестана." }, { 39.86, "Ишамухал почует тушу и явится на её запах." }, { 43.88, "Будь готов к его появлению." } }, f = { { 0.00, "Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей." }, { 7.21, "Он охотится не ради еды и не для удовольствия." }, { 11.44, "Охота – его страсть." }, { 13.34, "Он убивает потому, что сам убийца по природе." }, { 17.49, "Именно о его природе тебе и предстоит узнать многое, ибо твой путь теперь поведёт тебя по когтистым следам Ишамухала." }, { 28.35, "Начинай охоту." }, { 29.76, "Убей его излюбленную добычу – жевру – и принеси её тушу к мёртвому дереву на северо-западе от Кабестана." }, { 39.37, "Ишамухал почует тушу и явится на её запах." }, { 43.35, "Будь готова к его появлению." } } }, t = { d = 19.9, v = "tauren-male#67", n = { x = 136 }, c = { x = { { 0.00, "Клык – всего лишь символ, но символ очень важных вещей." }, { 6.49, "Теперь в тебе есть сила Ишамухала." }, { 10.58, "Пользуйся ей, но соблюдай умеренность." }, { 14.97, "Отныне это твоя ноша." }, { 17.70, "И это великая честь." } } } } },
    [883] = { d = 4.6, v = "narrator", n = { x = 38 }, c = { x = { { 0.00, "Копыто Лакота'мани – символ силы великого кодо." } } }, t = { d = 21.6, v = "tauren-male#67", n = { x = 193 }, c = { x = { { 0.00, "Лакота'мани на нашем языке означает \"Землекрушитель\", ибо шаги его громоподобны." }, { 7.42, "Теперь он пребывает с тобой, к тебе перешло всё его мужество." }, { 13.11, "Отныне ты не побоишься встретиться с любой опасностью." }, { 18.05, "Верь в себя." }, { 19.21, "Верь в себя, Землекрушитель." } } } } },
    [884] = { d = 4.1, v = "narrator", n = { x = 36 }, c = { x = { { 0.00, "При касании от хвоста Оватанки летят искры." } } }, t = { d = 27.0, g = 1, v = "tauren-male#67", n = { m = 253, f = 254 }, c = { m = { { 0.00, "Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о её стремительности не стоит судить по размеру." }, { 10.95, "Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой." }, { 20.19, "Ныне её неутомимость передалась тебе." }, { 23.45, "Теперь ты не отстал бы от Оватанки." } }, f = { { 0.00, "Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о её стремительности не стоит судить по размеру." }, { 11.18, "Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой." }, { 20.62, "Ныне её неутомимость передалась тебе." }, { 23.95, "Теперь ты не отстала бы от Оватанки." } } } } },
    [885] = { d = 3.0, v = "narrator", n = { x = 28 }, c = { x = { { 0.00, "Пера Ваште Пауни больно касаться." } } }, t = { d = 48.9, g = 1, v = "tauren-male#67", n = { m = 424, f = 427 }, c = { m = { { 0.00, "Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок." }, { 9.51, "Но смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое..." }, { 18.59, "Или оба сразу." }, { 20.11, "Боль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой." }, { 29.95, "Внутренние терзания же – следствие сожалений." }, { 34.15, "Впрочем, я вижу, что ты справился с этими искушениями и познал, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу." }, { 47.36, "Ты многое познал." } }, f = { { 0.00, "Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок." }, { 9.26, "Но смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое..." }, { 18.10, "Или оба сразу." }, { 19.58, "Боль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой." }, { 29.16, "Внутренние терзания же – следствие сожалений." }, { 33.26, "Впрочем, я вижу, что ты справилась с этими искушениями и познала, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу." }, { 46.28, "Ты многое познала." } } } } },
    [886] = { d = 36.3, v = "creature/hamuul", n = { x = 365 }, c = { x = { { 0.00, "Друиды Громового Утёса ощущают странную силу, просачивающуюся в Степи к востоку от Мулгора." }, { 7.37, "Мы отправили найти источник этой силы Тонгу Рунического Тотема, но, похоже, ему нужна помощь." }, { 15.10, "Отправляйся в Степи и поговори с Тонгой." }, { 18.38, "Он будет в Перекрёстке." }, { 20.21, "Иди туда по дороге на восток от Деревни Кровавого Копыта." }, { 24.95, "Как попадёшь в Степи, сверни на развилке на север." }, { 28.96, "И продолжай идти, пока не упрёшься в Перекрёсток." }, { 32.83, "С дороги не сходи, ибо Степи – край суровый." } } }, t = { d = 17.9, g = 1, v = "tauren-male", n = { m = 148, f = 148 }, c = { m = { { 0.00, "Мои собратья в Громовом Утёсе мудро поступили, прислав тебя сюда, юный герой." }, { 7.41, "Ибо тайну Степей мне в одиночку не раскрыть." }, { 11.62, "Будем надеяться, что с твоей помощью мы найдём ответ на наш вопрос." } }, f = { { 0.00, "Мои собратья в Громовом Утёсе мудро поступили, прислав тебя сюда, юная героиня." }, { 7.61, "Ибо тайну Степей мне в одиночку не раскрыть." }, { 11.83, "Будем надеяться, что с твоей помощью мы найдём ответ на наш вопрос." } } } } },
    [887] = { d = 29.1, v = "named/3391", n = { x = 337 }, c = { x = { { 0.00, "Жаль, что вице-адмиралу Греззлику не удалось добиться безопасности в наших водах для торговых кораблей." }, { 7.27, "В торговый флот вложено столько денег, что я просто зверею, когда пираты как нечего делать нападают на мои корабли и похищают товары!" }, { 16.77, "Говорят, что флибустьеры Южных морей разбили лагерь к югу отсюда." }, { 21.49, "Они мне как бельмо на глазу, и если ими не хочет заняться Греззлик, может быть, ты поможешь избавиться от них?" } } }, t = { d = 13.3, v = "named/3391", n = { x = 143 }, c = { x = { { 0.00, "Молодец, малыш." }, { 1.23, "Побольше таких подвигов, и у меня станет одной проблемой меньше." }, { 6.20, "Хочется верить, что они решат перенести свой лагерь." }, { 10.22, "Остаётся одно – вернуть украденные товары!" } } } } },
    [888] = { d = 26.6, v = "named/3391", n = { x = 312 }, c = { x = { { 0.00, "Хоть я и хотел бы вернуть все товары, думаю, это невозможно." }, { 4.13, "Но некоторые из них мне очень нужны!" }, { 6.60, "Как видишь, моя обсерватория почти готова, но ей не хватает двух малых линз." }, { 11.78, "Первая из них прибыла с караваном из Дуротара, но вторую везли на корабле, который ограбили пираты." }, { 18.56, "Кроме того, до меня так и не дошла партия сапог от Дриззлика из Пиратской бухты!" }, { 24.11, "Ступай в пиратский лагерь и поищи их." } } }, t = { d = 13.0, v = "named/3391", n = { x = 132 }, c = { x = { { 0.00, "Я так рад, что вернул своё добро!" }, { 2.61, "Спасибо за помощь." }, { 4.13, "Знаешь, мне пригодились бы помощники вроде тебя." }, { 8.05, "Если понадобится работа, не забывай, что Газлоу неплохо платит!" } } } } },
    [889] = { t = { d = 12.9, g = 1, v = "named/3430", n = { x = 89 }, c = { m = { { 0.65, "Хорошо." }, { 1.41, "Да ведёт тебя дух Агамаггана, герой." }, { 4.77, "Возвращайся, если захочешь вновь соприкоснуться с магией Агамаггана." } }, f = { { 0.51, "Хорошо." }, { 1.31, "Да ведёт тебя дух Агамаггана, героиня." }, { 5.04, "Возвращайся, если захочешь вновь соприкоснуться с магией Агамаггана." } } } } },
    [890] = { d = 20.0, v = "named/3391", n = { x = 238 }, c = { x = { { 0.00, "Я уже сто лет жду последнего заказа из Пиратской бухты!" }, { 3.91, "Наверняка его перехватили флибустьеры, но на всякий случай сходи в порт и спроси у Головокружилкинса, вдруг товары без моего ведома отнесли на склад?" }, { 14.37, "Вот, отнеси мою учётную книжку Головокружилкинсу, пусть сверит со своими записями." } } }, t = { d = 12.7, v = "goblin-male", n = { x = 138 }, c = { x = { { 0.00, "А, так тебя прислал Газлоу?" }, { 2.00, "Минутку, дай-ка я загляну в свои записи, надо убедиться, что я не отправил товар Газлоу куда-то не туда." }, { 9.57, "Небось, он ждёт поставку сапог от Дриззлика..." } } } } },
    [891] = { d = 30.2, v = "bloodelf-male", n = { x = 376 }, c = { x = { { 0.00, "Вот и ещё один мой корабль захватили рьяные людишки из крепости Северной Стражи!" }, { 5.43, "Пора разобраться с этими мерзавцами." }, { 7.93, "Их паранойя перешла все мыслимые границы." }, { 10.74, "Эти безрассудные любители спускать курок стреляют во всё, что движется." }, { 15.56, "Отправляйся на юг вдоль Торгового побережья, найди их крепость и брось вызов их силе." }, { 21.23, "Принеси в доказательство собственных подвигов медали их солдат." }, { 25.50, "И во имя моего флота, убей капитана Гордостанную и её рьяных канониров!" } } }, t = { d = 10.0, v = "bloodelf-male", n = { x = 103 }, c = { x = { { 0.00, "Ах, какая жалость, праведные пушки Альянса умолкли." }, { 4.12, "Ты получишь награду за помощь." }, { 6.53, "Как бы теперь выручить тела наших погибших..." } } } } },
    [892] = { d = 17.8, v = "goblin-male", n = { x = 190 }, c = { x = { { 0.00, "У меня в записях всё в порядке." }, { 2.25, "Ступай к Газлоу и скажи, что ему не повезло." }, { 5.45, "Не удивлюсь, если его товары прибрали к рукам пираты." }, { 9.37, "Я ничем не могу ему помочь." }, { 11.42, "А, да..." }, { 12.00, "Скажи, что у меня есть для него кое-что из Нижней шахты, пусть приходит и забирает." } } }, t = { d = 16.4, v = "named/3391", n = { x = 173 }, c = { x = { { 0.00, "Вот непруха..." }, { 1.09, "Наверняка это корсары..." }, { 2.98, "Дыбоволос тут ни при чём, я уверен, он не стал бы так меня обманывать." }, { 8.07, "В конце концов, он получает деньги за доставку." }, { 11.66, "Похоже, мне придётся вернуть себе кое-какие товары." }, { 15.60, "Что скажешь?" } } } } },
    [893] = { d = 25.9, v = "orc-male", n = { x = 279 }, c = { x = { { 0.00, "Хотя говорят, что у свинобразов племени Иглогривых за Полями Великанов нет искусных кузнецов, они научились делать серьёзное оружие." }, { 10.18, "Мне хотелось бы получить несколько образцов, чтобы изучить их технику работы." }, { 16.17, "Если ты стремишься к подвигам во славу Орды, добудь для меня их оружие." }, { 21.75, "Мне понадобятся кинжал, жезл и щит." }, { 24.40, "Этого вполне хватит!" } } }, t = { d = 19.2, v = "orc-male", n = { x = 171 }, c = { x = { { 0.00, "Прекрасные, прекрасные образцы." }, { 2.90, "Свинобразы куда более умелый народ, чем мне казалось." }, { 7.86, "Вот, возьми это и убирайся." }, { 10.43, "Мне надо получше изучить это оружие." }, { 13.90, "Похоже, мы недооценивали врага, а такие ошибки недопустимы." } } } } },
    [894] = { d = 33.5, v = "goblin-male", n = { x = 401 }, c = { x = { { 0.00, "Торговая Компания устроила к северу отсюда, в юго-западной части Нефтяного болота, небольшой исследовательский центр." }, { 8.12, "Я не очень хорошо представляю, чем они занимаются, но до меня дошли сведения, что они проводят эксперименты со штукой под названием \"самофланж\"." }, { 18.05, "Что ещё за самофланж?" }, { 19.49, "Как бы то ни было, я хочу исследовать его, а значит, мне надо его заполучить." }, { 24.86, "Мне удалось достать копию их руководства пользователя." }, { 28.60, "Почитай его, там наверняка написано, как вытащить самофланж из терминала." } } }, t = { d = 21.3, v = "narrator", n = { x = 237 }, c = { x = { { 0.00, "На панели управления в беспорядке разбросаны кнопки, рычаги и мигающие лампочки." }, { 6.13, "Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны с первого по третий открыты." }, { 15.39, "В нижнем правом углу панели управления имеется небольшая замочная скважина." } } } } },
    [895] = { d = 18.6, v = "narrator", n = { x = 217 }, c = { x = { { 0.00, "РОЗЫСК!" }, { 0.60, "Разыскивается Барон Дольноберег, капитан \"Безрассудной\"." }, { 4.73, "Капитан Дольноберег из Гильнеаса водит корабли корсаров Южного моря." }, { 9.86, "Он разыскивается по обвинению в пиратских нападениях." }, { 13.72, "Предоставленные останки должны быть пригодны для опознания!" }, { 18.05, "- Газлоу." } } }, t = { d = 21.8, v = "named/3391", n = { x = 224 }, c = { x = { { 0.00, "А!" }, { 0.21, "Вот какое у тебя дело." }, { 2.04, "Знаешь, я однажды видел \"Безрассудную\" в открытом море." }, { 6.39, "Впечатляющий корабль." }, { 8.08, "Или судно?" }, { 8.99, "Эти моряки так придираются к словам!" }, { 11.87, "В общем, она так скользила по водной глади, что дух захватывало." }, { 16.85, "Я рад, что её проклятый капитан перестанет тревожить мои корабли." } } } } },
    [896] = { d = 28.3, v = "goblin-male", n = { x = 348 }, c = { x = { { 0.00, "Хозяин причала в таком оживлённом порту, как Кабестан, держит руку на пульсе происходящего." }, { 6.23, "Я в курсе всего товарообмена между нашим городом и Пиратской бухтой." }, { 10.98, "Последние слухи касаются Каменного карьера, принадлежащего Торговой Компании, что на северо-востоке от Нефтяного болота." }, { 19.19, "Один из шахтёров нашёл изумруд размером с твой кулак." }, { 22.77, "Я знаю несколько покупателей на такой товар и готов поделиться с тобой комиссией." } } }, t = { d = 18.9, v = "goblin-male", n = { x = 177 }, c = { x = { { 0.00, "Только посмотри, какой он огромный!" }, { 3.05, "Теперь мы разбогатеем!" }, { 4.95, "Ну-ка, судя по расценкам на драгоценные камни, я могу прикинуть твою долю..." }, { 11.50, "Пятьдесят процентов, будь спок!" }, { 14.09, "Посчитаем..." }, { 15.15, "Да, примерно так." }, { 16.60, "С тобой приятно иметь дело." } } } } },
    [897] = { d = 7.0, v = "narrator", n = { x = 73 }, c = { x = { { 0.00, "Это странное, похожее на насекомое существо выглядит так, будто попало в Степи случайно." } } }, t = { d = 22.6, v = "tauren-male#67", n = { x = 195 }, c = { x = { { 0.00, "Не могу ничего сказать о природе этого зверя, ведь духа его и след простыл." }, { 7.13, "Но ты верно говоришь, он не из Степей." }, { 10.65, "Боюсь, наш народ ожидают испытания…" }, { 14.00, "А пока готовься к худшему." }, { 16.52, "Будем надеяться, что со временем мы разгадаем тайну этого существа." } } } } },
    [898] = { d = 33.9, v = "bloodelf-male", n = { x = 404 }, c = { x = { { 0.00, "Наконец-то!" }, { 0.81, "Кто-то пришёл мне на помощь!" }, { 2.72, "Поверить не могу, что тебе удалось пройти мимо стражей." }, { 6.63, "Фанатики из Терамора совсем спятили." }, { 9.17, "Они потопили наш корабль и меня, единственного выжившего, взяли в плен." }, { 14.06, "Меня назвали врагом и угрозой безопасности Альянса." }, { 17.65, "Я!" }, { 17.84, "Угроза великому и могучему Альянсу?" }, { 20.31, "Я был матросом на грузовом судне, возившем самогон из Кабестана в Пиратскую бухту." }, { 25.95, "Довольно болтать." }, { 27.19, "Ты ведь поможешь мне вернуться в Кабестан?" }, { 30.04, "Скажи, когда решишь тронуться в путь, и мы совершим побег." } } }, t = { d = 8.1, g = 1, v = "bloodelf-male", n = { m = 91, f = 92 }, c = { m = { { 0.00, "Подумать только, мы полагали, что Огненный Цветок давно погиб!" }, { 4.72, "Ты заслужил уважение всех Тало'данских каперов." } }, f = { { 0.00, "Подумать только, мы полагали, что Огненный Цветок давно погиб!" }, { 4.68, "Ты заслужила уважение всех Тало'данских каперов." } } } } },
    [899] = { d = 37.3, g = 1, v = "orc-male#60", n = { m = 337, f = 339 }, c = { m = { { 0.00, "Быть может, тебе знакома мука неопределённости, а может, и нет." }, { 5.39, "Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ." }, { 13.05, "Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть." }, { 20.87, "Быть может, мне стоило идти не на север к Перекрёстку, а в Таурахо." }, { 26.57, "Ты, герой, мог бы мне помочь." }, { 29.08, "Убей их." }, { 29.86, "Убей как можно больше тварей." }, { 32.51, "Принеси мне их клыки, и мы вместе попируем на их могилах." } }, f = { { 0.00, "Быть может, тебе знакома мука неопределённости, а может, и нет." }, { 5.21, "Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ." }, { 12.61, "Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть." }, { 20.17, "Быть может, мне стоило идти не на север к Перекрёстку, а в Таурахо." }, { 25.68, "Ты, героиня, могла бы мне помочь." }, { 28.47, "Убей их." }, { 29.23, "Убей как можно больше тварей." }, { 31.80, "Принеси мне их клыки, и мы вместе попируем на их могилах." } } }, t = { d = 15.6, g = 1, v = "orc-male#60", n = { m = 135, f = 137 }, c = { m = { { 0.00, "Герой, ты отнёсся к моему заданию серьёзно, спасибо тебе за это." }, { 5.51, "Хотя жажда мести не утолена, я могу хотя бы улыбаться при мысли о том, что и иглогривы испытали ту же боль, что и я." } }, f = { { 0.00, "Героиня, ты отнеслась к моему заданию серьёзно, спасибо тебе за это." }, { 5.90, "Хотя жажда мести не утолена, я могу хотя бы улыбаться при мысли о том, что и иглогривы испытали ту же боль, что и я." } } } } },
    [900] = { d = 9.7, v = "narrator", n = { x = 113 }, c = { x = { { 0.00, "В настоящий момент открыты три контрольных клапана." }, { 3.65, "Судя по надписям на панели управления, их надо закрыть, прежде чем выключать прибор." } } }, t = { d = 15.5, v = "narrator", n = { x = 168 }, c = { x = { { 0.00, "Лампочки, относящиеся к трём управляющим клапанам, медленно гаснут." }, { 5.27, "Зелёный огонёк становится жёлтым, и теперь можно повернуть рычажок, выключающий прибор." }, { 12.03, "Клапаны закрыты, и терминал можно отключить." } } } } },
    [901] = { d = 11.0, v = "narrator", n = { x = 117 }, c = { x = { { 0.00, "Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала." }, { 6.89, "Всё бы хорошо, но чтобы отпереть терминал, нужен ключ." } } }, t = { d = 10.4, v = "narrator", n = { x = 115 }, c = { x = { { 0.00, "Повернув ключ в замке, вы открываете панель управления." }, { 4.20, "В верхней части терминала гаснет красная лампочка." }, { 8.13, "Теперь он полностью обесточен." } } } } },
    [902] = { d = 21.0, v = "narrator", n = { x = 219 }, c = { x = { { 0.00, "Под панелью управления оказывается мешанина проводов, ламп и прочих загадочных механических объектов – кажется, большая часть там вообще не нужна." }, { 11.53, "Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж." }, { 17.00, "Одного рывка хватает, чтобы вытащить его из паза." } } }, t = { d = 15.3, v = "goblin-male", n = { x = 147 }, c = { x = { { 0.00, "Это..." }, { 0.56, "Э..." }, { 0.92, "Любопытно..." }, { 1.90, "Да." }, { 2.18, "Я пошлю его в Союз ремонтников Нижней шахты." }, { 5.78, "Не сомневаюсь, что эту штуку исследуют и поймут, для чего она нужна." }, { 11.20, "Впрочем, сначала надо самому посмотреть что к чему..." } } } } },
    [903] = { d = 23.6, v = "orc-female", n = { x = 234 }, c = { x = { { 0.00, "Пришло время поохотиться на тех, кто может постоять за себя." }, { 5.00, "Хищники саванны, живущие в Степях – сильные звери." }, { 9.26, "Сильные, могучие, хитрые и опасные." }, { 12.25, "Их можно найти в высокой траве на юго-западе от Перекрёстка." }, { 17.26, "Соблюдай осторожность, иначе можешь неожиданно превратиться из охотника в дичь." } } }, t = { d = 12.6, g = 1, v = "orc-female", n = { m = 121, f = 123 }, c = { m = { { 0.00, "А, вижу, ты времени даром не терял, а прятался в траве, выслеживая хищников." }, { 6.36, "Как ты думаешь, пришло ли время встретиться лицом к лицу с сильнейшим из них?" } }, f = { { 0.00, "А, вижу, ты времени даром не теряла, а пряталась в траве, выслеживая хищников." }, { 6.31, "Как ты думаешь, пришло ли время встретиться лицом к лицу с сильнейшим из них?" } } } } },
    [905] = { d = 25.4, v = "orc-female", n = { x = 239 }, c = { x = { { 0.00, "Что ж, теперь твоя задача усложняется." }, { 3.34, "Сначала тебе надо победить свою добычу, а потом отыскать её логово." }, { 9.31, "Я предлагаю поохотиться на яркочешуйчатых ящеров, живущих на юге." }, { 14.89, "Убей их и забери перья." }, { 16.99, "Отнеси перья в их гнёзда на юго-западе от Застывшего оазиса." }, { 22.18, "Покажи их сородичам, что ты не боишься!" } } }, t = { d = 18.0, g = 1, v = "orc-female", n = { m = 183, f = 187 }, c = { m = { { 0.00, "Значит, ты побывал возле гнёзд и поместил в них перья?" }, { 4.24, "На это требуется немало мужества." }, { 6.92, "Ты чувствуешь, что стал сильнее?" }, { 9.39, "Выглядишь ты куда крепче, чем в тот миг, когда явился сюда в первый раз." }, { 15.04, "Думаю, Степи сыграли в этом свою роль." } }, f = { { 0.00, "Значит, ты побывала возле гнёзд и поместила в них перья?" }, { 4.29, "На это требуется немало мужества." }, { 6.93, "Ты чувствуешь, что стала сильнее?" }, { 9.49, "Выглядишь ты куда крепче, чем в тот миг, когда явилась сюда в первый раз." }, { 15.10, "Думаю, Степи сыграли в этом свою роль." } } } } },
    [906] = { d = 31.4, g = 1, v = "named/3430", n = { x = 276 }, c = { m = { { 0.98, "Отнеси голову Лока Торку на Перекрёсток, герой." }, { 6.42, "Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в" }, { 15.12, "таких вещах." }, { 16.15, "Но я не сомневаюсь, что он наградит тебя за совершённый подвиг." }, { 21.89, "Пока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана." }, { 29.23, "Пока же прощай." } }, f = { { 0.35, "Отнеси голову Лока Торку на Перекрёсток, героиня." }, { 5.79, "Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в" }, { 14.65, "таких вещах." }, { 15.71, "Но я не сомневаюсь, что он наградит тебя за совершённый подвиг." }, { 21.58, "Пока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана." }, { 28.99, "Пока же прощай." } } }, t = { d = 24.2, v = "orc-male#60", n = { x = 239 }, c = { x = { { 0.00, "Тебе удалось найти главаря племени Иглогривых и собственноручно убить его?" }, { 6.34, "Поразительно." }, { 7.48, "У меня нет слов, но это не значит, что я не благодарен тебе." }, { 12.46, "Жители Перекрёстка должны уважать твою силу." }, { 16.24, "Должен признать, я считал, что возглавляет налёты на наши обозы другой свинобраз." }, { 23.04, "Ещё раз спасибо." } } } } },
    [907] = { d = 27.0, v = "tauren-male#67", n = { x = 244 }, c = { x = { { 0.00, "Пришло время выступить против рокочущих ящериц." }, { 4.42, "Они столь огромны, что земля дрожит под их шагами." }, { 9.01, "Сражаясь с ними, соблюдай осторожность: один неверный шаг – и они стопчут тебя." }, { 16.31, "Ящерицы живут в южной части Степей." }, { 19.67, "Их называют грозорылами, грозошкурами и громоголовами." }, { 24.50, "Возвращайся ко мне с победой." } } }, t = { d = 9.5, g = 1, v = "tauren-male#67", n = { m = 88, f = 90 }, c = { m = { { 0.00, "Я рад, что ты принёс доказательство своего торжества." }, { 4.64, "И особенно здорово, что у тебя все кости остались целы." } }, f = { { 0.00, "Я рад, что ты принесла доказательство своего торжества." }, { 4.64, "И особенно здорово, что у тебя все кости остались целы." } } } } },
    [908] = { d = 41.5, v = "narrator", n = { x = 439 }, c = { x = { { 0.00, "Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины." }, { 7.02, "Их присутствие приведёт лишь к тому, что Стихии озлобятся на нас." }, { 11.98, "Если это так и оставить, то они захватят эти места навсегда." }, { 16.87, "Ступай в Непроглядную Пучину и найди в руинах глубинный камень." }, { 21.90, "Он должен быть где-то поблизости в воде." }, { 25.09, "В нём находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий." }, { 34.87, "Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!" } } } },
    [909] = { d = 31.2, v = "narrator", n = { x = 322 }, c = { x = { { 0.00, "Сражённый элементаль воды оставил после себя странную сферу." }, { 4.91, "Вы предполагаете, что этот предмет каким-то образом подпитывал тварь энергией." }, { 11.12, "Внутри сферы плещется грязная на вид жидкость." }, { 14.88, "Сама сфера вроде бы не поддаётся никаким физическим воздействиям." }, { 20.08, "Если кто и сможет понять, что это за штука, то это Дже'неу Санкри из Служителей Земли." }, { 27.09, "Он находится в форте Орды Зорам'гар в Ясеневом лесу." } } } },
    [910] = { d = 28.7, v = "child-male", n = { x = 306 }, c = { x = { { 0.00, "Я слышал, что между Кабестаном и Пиратской бухтой плавают огромные корабли!" }, { 5.71, "Вот бы мне поплавать по океану и принять участие в морских боях." }, { 10.53, "Может быть, когда я вырасту, я стану великим моряком Орды!" }, { 15.01, "Да!" }, { 15.28, "Пожалуйста, своди меня в Кабестан, посмотреть на порт." }, { 19.36, "Обещаю, я не свалюсь в воду и буду хорошо себя вести – мне бы посмотреть на корабли и вдохнуть запах солёной морской воды!" }, { 28.60, "Да!" } } }, t = { d = 16.2, g = 1, v = "child-male", n = { m = 136, f = 137 }, c = { m = { { 0.00, "Ух ты, океан ОГРОМНЫЙ!" }, { 2.03, "А ещё там куча чаек и всякого такого – шумно и суетливо, как я и думал." }, { 8.44, "И пираты рядом – вот здорово!" }, { 11.12, "Спасибо, что сводил меня в Кабестан." }, { 14.45, "Это было так круто!" } }, f = { { 0.00, "Ух ты, океан ОГРОМНЫЙ!" }, { 1.99, "А ещё там куча чаек и всякого такого – шумно и суетливо, как я и думал." }, { 8.28, "И пираты рядом – вот здорово!" }, { 10.91, "Спасибо, что сводила меня в Кабестан." }, { 14.25, "Это было так круто!" } } } } },
    [911] = { d = 27.4, v = "child-male", n = { x = 311 }, c = { x = { { 0.00, "Говорят, что Ясеневый лес – это новое пограничье, а врата к нему – Застава Мор'шан." }, { 6.00, "Здорово быть первооткрывателем, добывать всё необходимое из первозданного леса!" }, { 11.56, "Говорят, что именно там будут греметь битвы между Ордой и Альянсом." }, { 16.46, "Вот бы мне попасть туда!" }, { 18.21, "Отведи меня к заставе Мор'шан, посмотреть на новое пограничье!" }, { 22.73, "Я хочу посмотреть, как Орда выгонит оттуда вонючих ночных эльфов!" } } }, t = { d = 18.7, g = 1, v = "child-male", n = { m = 175, f = 177 }, c = { m = { { 0.00, "Ух ты, Ясеневый лес – вот где настоящие приключения!" }, { 4.06, "А ты сражался в Ясеневом лесу?" }, { 6.52, "Когда я вырасту и стану героем, я приду в Ясеневый лес и буду сражаться во славу Орды!" }, { 13.55, "Спасибо, что отвёл меня на пограничье." }, { 16.59, "Ты лучше всех!" } }, f = { { 0.00, "Ух ты, Ясеневый лес – вот где настоящие приключения!" }, { 4.26, "А ты сражалась в Ясеневом лесу?" }, { 6.93, "Когда я вырасту и стану героем, я приду в Ясеневый лес и буду сражаться во славу Орды!" }, { 14.31, "Спасибо, что отвела меня на пограничье." }, { 17.66, "Ты лучше всех!" } } } } },
    [913] = { d = 19.0, g = 1, v = "tauren-male#67", n = { m = 156, f = 157 }, c = { m = { { 0.00, "Грозовой змей – лютый зверь." }, { 2.69, "И всё же ты уже готов бросить ему вызов." }, { 6.68, "Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты." }, { 13.61, "Выполни моё задание, и твоё обучение подойдёт к концу." } }, f = { { 0.00, "Грозовой змей – лютый зверь." }, { 2.73, "И всё же ты уже готова бросить ему вызов." }, { 6.88, "Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты." }, { 13.93, "Выполни моё задание, и твоё обучение подойдёт к концу." } } }, t = { d = 24.3, g = 1, v = "tauren-male#67", n = { m = 207, f = 208 }, c = { m = { { 0.00, "Тебе есть чем гордиться, ведь ты одолел всех врагов, явив силу, мужество и честь." }, { 7.60, "Не останавливайся, следуй дальше по своему пути." }, { 12.21, "Более того, жизнь настоящего охотника – постоянная борьба." }, { 17.76, "Ступай же с высоко поднятой головой по избранному тобой пути." }, { 23.65, "Пора." } }, f = { { 0.00, "Тебе есть чем гордиться, ведь ты одолела всех врагов, явив силу, мужество и честь." }, { 7.73, "Не останавливайся, следуй дальше по своему пути." }, { 12.37, "Более того, жизнь настоящего охотника – постоянная борьба." }, { 17.96, "Ступай же с высоко поднятой головой по избранному тобой пути." }, { 23.88, "Пора." } } } } },
    [914] = { d = 37.9, v = "tauren-female", n = { x = 383 }, c = { x = { { 0.00, "Друиды в Пещерах Стенаний, Друиды Клыка поражены порчей." }, { 4.71, "Когда-то они были частью ордена друидов давшего обет исцелить Степи, но теперь они хотят перекроить эти земли в соответствии со своими извращёнными мечтаниями." }, { 17.90, "У Друидов Клыка четыре предводителя и каждый обладает Камнем Сновидения." }, { 23.86, "Даже теперь их лица преследуют меня в кошмарах." }, { 27.84, "Убей предводителей друидов, принеси мне их камни и в Степях снова воцарится мир." }, { 34.39, "Иди, и разыщи их укрытия в Пещерах Стенаний." } } }, t = { d = 16.9, g = 1, v = "tauren-female", n = { m = 148, f = 152 }, c = { m = { { 0.00, "Ты сделал это." }, { 1.39, "Ты убил друидов Клыка, теперь мои сны свободны от их присутствия." }, { 7.34, "Ты спас Степи, и я благодарю тебя от своего имени, от имени друидов Громового Утёса и от имени этой земли." } }, f = { { 0.00, "Ты сделала это." }, { 1.44, "Ты убила друидов Клыка, теперь мои сны свободны от их присутствия." }, { 7.36, "Ты спасла Степи, и я благодарю тебя от своего имени, от имени друидов Громового Утёса и от имени этой земли." } } } } },
    [915] = { d = 29.5, v = "child-male", n = { x = 334 }, c = { x = { { 0.00, "МОРОЖЕНОЕ!" }, { 0.78, "Пожалуйста, пожалуйста, пожалуйста, добудь для меня немного мороженого!!!" }, { 6.06, "Я больше всего люблю клубничное, а самое лучшее клубничное мороженое делают Тигуле и Форор!" }, { 12.78, "Это моё самое любимое мороженое на свете!" }, { 15.84, "Я пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе!" }, { 25.17, "Пожалуйста!" }, { 26.01, "Пожалуйста-препожалуйста!" }, { 27.77, "Преогромное пожалуйста!!!!" } } }, t = { d = 13.3, v = "child-male", n = { x = 128 }, c = { x = { { 0.00, "Ммммммммм!" }, { 0.83, "Обожаю их клубничное мороженое!" }, { 3.45, "Если Тигуле и Форор что-то и умеют, так это делать мороженое!" }, { 8.71, "Огромное спасибо, – это самое лучшее угощение на свете!" } } } } },
    [916] = { d = 39.2, v = "nightelf-male#55", n = { x = 439 }, c = { x = { { 0.00, "Я пришёл в Тенистую долину, чтобы наблюдать за чащобными тенётниками, обитающими в Паучьем логове." }, { 7.04, "Они – родичи более мелких разновидностей пауков." }, { 10.66, "Полагаю, что Древо Жизни оказало на них сильное воздействие..." }, { 15.20, "Я хотел бы получить несколько вещей, чтобы изучить их и подтвердить свои догадки." }, { 21.19, "Для начала мне понадобится немного их яда." }, { 24.28, "Добудь ядовитые железы у пауков-тенётников в Паучьем логове и вокруг него, к северу отсюда." }, { 30.99, "После этого я смогу изучить эти образцы и понять, есть ли у этого яда сходство с ядом их более мелких сородичей." } } }, t = { d = 13.9, v = "nightelf-male#55", n = { x = 153 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.19, "Когда я вернусь в Дарнасс, я первым же делом сравню образцы яда из этих желёз с ядами других пауков." }, { 8.65, "Полагаю, что некоторые свойства яда связаны с ростом нового Древа Жизни." } } } } },
    [917] = { d = 32.1, v = "nightelf-male#55", n = { x = 378 }, c = { x = { { 0.00, "Теперь, когда у меня есть паучий яд, мне хотелось бы получить для изучения живой образец." }, { 6.10, "Не волнуйся, я не могу просить тебя поймать гигантского паука живьём." }, { 10.84, "Да и мне самому вряд ли удалось бы справиться с таким \"образцом\"!" }, { 15.22, "Но если ты принесёшь яйцо, из которого ещё не вылупился паучок, то получить образец будет куда легче, не говоря уж о том, чтобы содержать." }, { 24.58, "В глубинах Паучьего логова должно быть гнездо." }, { 27.79, "Прошу тебя, найди его, возьми оттуда яйцо паука и принеси мне." } } }, t = { d = 14.9, v = "nightelf-male#55", n = { x = 153 }, c = { x = { { 0.00, "О, отлично." }, { 0.92, "Я отправлю яйцо и яд в Дарнасс, а потом и сам вернусь туда, когда мои изыскания здесь будут завершены." }, { 8.96, "Я многого ожидаю от этих образцов." }, { 11.71, "Твоя помощь оказалась поистине бесценной." } } } } },
    [918] = { d = 28.9, g = 1, v = "nightelf-male#59", n = { m = 342, f = 344 }, c = { m = { { 0.00, "Древесники Тельдрассила – духи Природы." }, { 2.68, "Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе." }, { 9.49, "Потому меня очень тревожит, что древесники становятся такими озлобленными." }, { 14.54, "Мне кажется, что дело в почве." }, { 16.61, "Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников." }, { 23.48, "Не мог бы ты собрать для меня этих саженцев вокруг озера Аль'Амет?" } }, f = { { 0.00, "Древесники Тельдрассила – духи Природы." }, { 2.76, "Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе." }, { 9.78, "Потому меня очень тревожит, что древесники становятся такими озлобленными." }, { 14.98, "Мне кажется, что дело в почве." }, { 17.11, "Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников." }, { 24.20, "Не могла бы ты собрать для меня этих саженцев вокруг озера Аль'Амет?" } } }, t = { d = 14.3, g = 1, v = "nightelf-male#59", n = { m = 157, f = 158 }, c = { m = { { 0.00, "Ты их добыл." }, { 0.96, "Славно!" }, { 1.57, "Я посажу их в специально подготовленную почву." }, { 5.05, "Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных." }, { 11.47, "Может, позже ты ещё увидишь результаты!" } }, f = { { 0.00, "Ты их добыла." }, { 1.01, "Славно!" }, { 1.61, "Я посажу их в специально подготовленную почву." }, { 5.04, "Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных." }, { 11.35, "Может, позже ты ещё увидишь результаты!" } } } } },
    [919] = { d = 21.8, v = "nightelf-male#59", n = { x = 258 }, c = { x = { { 0.00, "Вокруг вод озера Аль'Амет прорастают маленькие древесники." }, { 4.11, "Боюсь, им уже не помочь, нам придётся выдернуть их из земли прежде, чем они станут слишком большими и начнут приносить беды." }, { 12.82, "Когда будешь бродить вокруг озера, выдергивай каждый росток древесника, что попадётся тебе по дороге." }, { 19.96, "Помоги очистить нашу землю!" } } }, t = { d = 13.6, v = "nightelf-male#59", n = { x = 148 }, c = { x = { { 0.00, "Как много!" }, { 0.83, "Они распространяются с ужасающей скоростью." }, { 4.15, "Надеюсь, мне удастся разгадать, что же за порча поразила их." }, { 8.71, "Благодарю за помощь." }, { 10.29, "Этот край благодаря твоим усилиям стал чище." } } } } },
    [920] = { d = 14.1, g = 1, v = "nightelf-male#55", n = { x = 146 }, c = { m = { { 0.00, "Ты путник, не так ли?" }, { 1.54, "До меня доходили слухи, что тебя искал Тенарон." }, { 5.16, "Ты отыщешь его в самой верхней комнате на вершине Альдрассила." }, { 9.85, "Хоть мы и живём долго, не стоит заставлять Тенарона ждать." } }, f = { { 0.00, "Ты путница, не так ли?" }, { 1.62, "До меня доходили слухи, что тебя искал Тенарон." }, { 5.26, "Ты отыщешь его в самой верхней комнате на вершине Альдрассила." }, { 9.98, "Хоть мы и живём долго, не стоит заставлять Тенарона ждать." } } }, t = { d = 8.4, v = "nightelf-male#54", n = { x = 90 }, c = { x = { { 0.00, "А." }, { 0.20, "Я надеялся, что ты быстро откликнешься на мой призыв." }, { 4.14, "У меня есть важное задание, которое я хочу поручить тебе." } } } } },
    [921] = { d = 38.6, v = "nightelf-male#54", n = { x = 406 }, c = { x = { { 0.00, "Пришло время тебе отправиться на поиски своей судьбы." }, { 4.29, "Но чтобы подготовиться к встрече с миром за пределами наших зачарованных лесов, тебе нужно больше узнать о нашей недавней истории." }, { 14.57, "Многое изменилось для нашего народа со времён битвы за гору Хиджал." }, { 19.85, "Нордрассил ныне – лишь бледная тень того, чем он некогда был, его сила ушла на то, чтобы одолеть Архимонда и отбросить прочь Пылающий Легион..." }, { 30.98, "Тебе нужно исполнить важное поручение." }, { 34.07, "Принеси мне воды из лунного колодца к северу от Альдрассила." } } }, t = { d = 18.7, v = "nightelf-male#54", n = { x = 209 }, c = { x = { { 0.00, "Тебе уже довелось услышать первую часть истории о последствиях битвы за гору Хиджал, однако ещё многое нужно рассказать, и выполнение задания, данного мной тебе, будет продолжаться на протяжении всего твоего путешествия через Тельдрассил в Дарнасс." } } } } },
    [922] = { d = 33.7, g = 1, v = "nightelf-male#59", n = { m = 394, f = 398 }, c = { m = { { 0.00, "Не мог бы ты доставить один из тех ростков, что ты принёс мне, моему другу, Релиану Зелёному Костру?" }, { 6.71, "Он друид из Дарнасса." }, { 8.20, "Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками." }, { 13.91, "У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом." }, { 19.81, "Благодарю тебя." }, { 20.93, "Твоя помощь просто неоценима." }, { 23.04, "Надеюсь, что однажды ты увидишь плоды моих трудов." }, { 26.58, "Релиана обычно можно найти на какой-нибудь из дорожек анклава Кенария в Дарнассе, он любит там гулять." } }, f = { { 0.00, "Не могла бы ты доставить один из тех ростков, что ты принесла мне, моему другу, Релиану Зелёному Костру?" }, { 7.04, "Он друид из Дарнасса." }, { 8.52, "Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками." }, { 14.20, "У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом." }, { 20.06, "Благодарю тебя." }, { 21.17, "Твоя помощь просто неоценима." }, { 23.27, "Надеюсь, что однажды ты увидишь плоды моих трудов." }, { 26.79, "Релиана обычно можно найти на какой-нибудь из дорожек анклава Кенария в Дарнассе, он любит там гулять." } } }, t = { d = 28.6, v = "nightelf-male#55", n = { x = 340 }, c = { x = { { 0.00, "А, росток древесника?" }, { 1.49, "Я хотел попытаться сам вырастить древесника, чтобы помочь Деналану в его изысканиях." }, { 7.33, "К сожалению, я выяснил, что множество древесников поражено порчей, и ростки таких существ также наследуют её от родителей." }, { 15.72, "И не в моих силах это исправить." }, { 18.02, "У Деналана великий талант работать со всем, что растёт." }, { 21.74, "Если кто и найдёт исцеление для будущих древесников, то это он." }, { 26.03, "Возможно, он – наша последняя надежда." } } } } },
    [923] = { d = 29.5, v = "nightelf-male#55", n = { x = 335 }, c = { x = { { 0.00, "Древесники становятся всё более злобными." }, { 3.03, "Мы пытаемся найти источник этой беды, но пока... чтобы уберечь Тельдрассил, нам приходится уничтожать древесников, которым уже не поможешь." }, { 13.22, "Те, что бродят вокруг Родникового озера на севере, поражены порчей сильнее всего." }, { 19.21, "Их надо уничтожить!" }, { 20.65, "Уничтожь всех древесников, которых там найдёшь, и собери растущие на них мшистые опухоли." }, { 27.03, "Принеси их мне, чтобы я мог их сжечь." } } }, t = { d = 13.3, v = "nightelf-male#55", n = { x = 136 }, c = { x = { { 0.00, "Хорошая работа!" }, { 1.28, "Эти опухоли - симптом болезни древесников." }, { 4.69, "Они наполнены ядом, от которого мы должны очистить наши новые земли." }, { 10.23, "Я уничтожу эти опухоли." }, { 12.15, "Благодарю тебя." } } } } },
    [924] = { d = 36.3, v = "orc-male", n = { x = 383 }, c = { x = { { 0.00, "Демоново семя – страшное оружие Пылающего Легиона." }, { 4.02, "Оно хранится в пещере на Вершине Багрового Тумана, над демоническим алтарём Огня." }, { 10.37, "Я подготовил камни силы, которые разорвут связь Семени с Легионом." }, { 15.59, "Возьми камень со стола и возложи его на алтарь Огня на Вершине Багрового Тумана." }, { 22.01, "Отправляйся на запад, а на развилке сверни на север." }, { 26.10, "Вершина окажется по левую руку от тебя." }, { 29.28, "Безопаснее всего подниматься по северному склону." }, { 33.16, "Торопись: сила камня постепенно иссякает." } } }, t = { d = 33.7, v = "orc-male", n = { x = 318 }, c = { x = { { 0.00, "Твоя цель достигнута." }, { 1.85, "Тебе удалось уничтожить Демоново семя, как велел Нииру." }, { 6.69, "Но это ещё не конец…" }, { 8.46, "После уничтожения Демонова семени по всему астралу пошли волны небывалой силы." }, { 15.30, "Их почувствовал не только я." }, { 17.69, "Об этом узнают те, чью игрушку мы сломали…" }, { 21.30, "Впрочем, невзирая на грядущие испытания, я хочу вручить тебе кое-что." }, { 27.30, "Нииру велел дать это в уплату и поблагодарить тебя." }, { 31.76, "Итак, я благодарю тебя." } } } } },
    [925] = { d = 29.3, g = 1, v = "child-male", n = { m = 309, f = 314 }, c = { m = { { 0.00, "Говорят, что Кэрн Кровавое Копыто – один из величайших героев Орды." }, { 4.88, "Когда я вырасту, я тоже хочу стать героем Орды!" }, { 8.40, "Ты знаком с Кэрном?" }, { 9.83, "Окажи мне услугу!" }, { 11.13, "Возьми у него отпечаток копыта!" }, { 13.47, "Я не знаю, как его попросить, у него нет времени на таких, как я... другое дело ты!" }, { 19.46, "Ты такой же искатель приключений, как и он!" }, { 22.52, "Готов поспорить, что тебе получить у него отпечаток копыта – раз плюнуть!" }, { 27.86, "Пожалуйста!" } }, f = { { 0.00, "Говорят, что Кэрн Кровавое Копыто – один из величайших героев Орды." }, { 4.95, "Когда я вырасту, я тоже хочу стать героем Орды!" }, { 8.51, "Ты знакома с Кэрном?" }, { 10.03, "Окажи мне услугу!" }, { 11.35, "Возьми у него отпечаток копыта!" }, { 13.72, "Я не знаю, как его попросить, у него нет времени на таких, как я... другое дело ты!" }, { 19.79, "Ты такая же искательница приключений, как и он!" }, { 23.16, "Готов поспорить, что тебе получить у него отпечаток копыта – раз плюнуть!" }, { 28.57, "Пожалуйста!" } } }, t = { d = 22.3, g = 1, v = "child-male", n = { m = 198, f = 200 }, c = { m = { { 0.00, "УХ ТЫ!" }, { 0.55, "Ты достал мне отпечаток копыта Кэрна!" }, { 3.82, "Огромное спасибо!" }, { 5.38, "И ух ты... он написал здесь личное послание – мне!" }, { 9.60, "Я знал, что он классный, точно знал!" }, { 12.64, "Может, однажды я сам его поблагодарю... когда стану героем Орды!" }, { 18.34, "Ты лучше всех." }, { 19.59, "Спасибо, что ты так добр ко мне." } }, f = { { 0.00, "УХ ТЫ!" }, { 0.55, "Ты достала мне отпечаток копыта Кэрна!" }, { 3.90, "Огромное спасибо!" }, { 5.46, "И ух ты... он написал здесь личное послание – мне!" }, { 9.68, "Я знал, что он классный, точно знал!" }, { 12.72, "Может, однажды я сам его поблагодарю... когда стану героем Орды!" }, { 18.42, "Ты лучше всех." }, { 19.67, "Спасибо, что ты так добра ко мне." } } } } },
    [926] = { t = { d = 13.0, v = "narrator", n = { x = 133 }, c = { x = { { 0.00, "Эти камни исполнены магической энергии, но в каждом из них есть умышленный изъян." }, { 6.45, "Они не слишком стабильные, и если взять их со стола, они быстро поглотят сами себя." } } } } },
    [927] = { d = 16.3, v = "narrator", n = { x = 163 }, c = { x = { { 0.00, "Сердце Черномшеца Злосмрадного поросло тёмным маслянистым мхом." }, { 5.17, "Понять, что это сердце, можно лишь по тому, что оно медленно и ритмично пульсирует..." }, { 12.28, "Даже сейчас." }, { 13.40, "Возможно, это заинтересует Деналана." } } }, t = { d = 13.9, g = 1, v = "nightelf-male#59", n = { m = 147, f = 149 }, c = { m = { { 0.00, "...Это ещё что такое?" }, { 1.59, "Сердце древесника?" }, { 2.98, "Оно всё поросло вонючим мхом!" }, { 5.17, "Хорошо, что ты принёс его мне." }, { 7.36, "Я исследую это сердце и, если удача повернётся ко мне лицом, выясню, что это за мох на нём." } }, f = { { 0.00, "...Это ещё что такое?" }, { 1.58, "Сердце древесника?" }, { 2.96, "Оно всё поросло вонючим мхом!" }, { 5.13, "Хорошо, что ты принесла его мне." }, { 7.49, "Я исследую это сердце и, если удача повернётся ко мне лицом, выясню, что это за мох на нём." } } } } },
    [928] = { d = 38.4, g = 1, v = "nightelf-male#54", n = { m = 389, f = 391 }, c = { m = { { 0.00, "Я мог бы поведать тебе ещё многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь." }, { 7.47, "Коритрас Лунный Гнев ждёт тебя." }, { 9.98, "Я перелил воду из фиала, принесённого тобой, в этот сосуд, чтобы ты отнёс его Коритрасу." }, { 17.01, "Ты найдёшь Коритраса у лунного колодца в Доланааре." }, { 21.03, "Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернёт на запад, следуй по пути, мощенному булыжниками." }, { 31.30, "И советую тебе не сходить с дороги, – в последнее время в лесу появились опасные существа." } }, f = { { 0.00, "Я мог бы поведать тебе ещё многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь." }, { 7.35, "Коритрас Лунный Гнев ждёт тебя." }, { 9.82, "Я перелил воду из фиала, принесённого тобой, в этот сосуд, чтобы ты отнесла его Коритрасу." }, { 16.96, "Ты найдёшь Коритраса у лунного колодца в Доланааре." }, { 20.91, "Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернёт на запад, следуй по пути, мощенному булыжниками." }, { 31.02, "И советую тебе не сходить с дороги, – в последнее время в лесу появились опасные существа." } } }, t = { d = 15.3, v = "nightelf-male#54", n = { x = 131 }, c = { x = { { 0.00, "А, понятно." }, { 1.06, "Тебя послал Тенарон." }, { 3.02, "Ну что ж, похоже, нам о многом нужно поговорить, многое сделать – но времени мало." }, { 10.46, "Думаю, лучше не медлить и приступить к делу сейчас же." } } } } },
    [929] = { d = 36.0, v = "nightelf-male#54", n = { x = 407 }, c = { x = { { 0.00, "Сначала позволь поведать тебе, какая стоит перед тобой задача." }, { 4.73, "Друиды Дарнасса пользуются водой из лунных колодцев Тельдрассила, и временами их колодцы надо пополнять." }, { 12.35, "При помощи этих специально изготовленных фиалов ты сможешь набирать воду из лунных колодцев." }, { 19.12, "Отнеси этот сосуд к лунному колодцу у деревни Звёздного Ветра на востоке и набери из него немного воды, а затем возвращайся ко мне." }, { 28.71, "Когда ты выполнишь это задание, я продолжу свой рассказ с момента, на котором его прервал Тенарон..." } } }, t = { d = 22.7, v = "nightelf-male#54", n = { x = 219 }, c = { x = { { 0.00, "После битвы за гору Хиджал мы не знали, что делать дальше." }, { 4.98, "Нордрассил дымился, опалённый огнём, и наше бессмертие – сама сущность нашего бытия! – было утрачено." }, { 13.44, "Именно в эту пору испытаний Предатель вырвался из заточения и исчез Шан'до Ярость Бури." }, { 20.91, "Настали тёмные времена." } } } } },
    [930] = { d = 9.3, v = "narrator", n = { x = 96 }, c = { x = { { 0.00, "Под ветками этого светящегося растения висит большой круглый плод." }, { 5.50, "Вы уверены, что Деналану захочется его изучить." } } }, t = { d = 20.8, g = 1, v = "nightelf-male#59", n = { m = 222, f = 222 }, c = { m = { { 0.00, "Ты нашёл его на Тельдрассиле?" }, { 2.14, "Как интересно..." }, { 3.35, "Такой необычный плод." }, { 4.95, "Может, семена занесло издалека?" }, { 7.36, "Может, даже из Азерота!" }, { 9.17, "И что-то в нём есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила." }, { 15.73, "Спасибо тебе." }, { 16.80, "Теперь извини, мне нужно попристальнее его поизучать..." } }, f = { { 0.00, "Ты нашла его на Тельдрассиле?" }, { 2.17, "Как интересно..." }, { 3.35, "Такой необычный плод." }, { 4.93, "Может, семена занесло издалека?" }, { 7.29, "Может, даже из Азерота!" }, { 9.06, "И что-то в нём есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила." }, { 15.50, "Спасибо тебе." }, { 16.55, "Теперь извини, мне нужно попристальнее его поизучать..." } } } } },
    [931] = { d = 12.8, v = "narrator", n = { x = 133 }, c = { x = { { 0.00, "Росток этого дерева мерцает в сумраке леса, распространяя вокруг себя изменчивое, пульсирующее свечение." }, { 8.66, "Наверное, Деналана интересует именно такой образец." } } }, t = { d = 21.0, g = 1, v = "nightelf-male#59", n = { m = 232, f = 232 }, c = { m = { { 0.00, "Где ты это нашёл?" }, { 1.24, "Я не видел таких растений с тех пор, как жил на Болоте Печали." }, { 5.67, "А это было много десятилетий назад!" }, { 8.34, "Удивительно, как он попал в Тельдрассил." }, { 11.20, "Да ещё вырос до такой величины!" }, { 13.48, "Спасибо тебе." }, { 14.53, "Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком..." } }, f = { { 0.00, "Где ты это нашла?" }, { 1.30, "Я не видел таких растений с тех пор, как жил на Болоте Печали." }, { 5.71, "А это было много десятилетий назад!" }, { 8.38, "Удивительно, как он попал в Тельдрассил." }, { 11.23, "Да ещё вырос до такой величины!" }, { 13.51, "Спасибо тебе." }, { 14.55, "Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком..." } } } } },
    [932] = { d = 29.4, v = "nightelf-male#54", n = { x = 305 }, c = { x = { { 0.00, "Должен предупредить тебя, что это должно остаться только между нами." }, { 5.38, "Сатиры и так уже причиняют нам немало неприятностей, а этот уж слишком близко к нашему дому рыщет." }, { 12.96, "Его зовут лорд Меленас." }, { 14.82, "Он живёт по соседству, в Пещере Бесов, где собрал шайку греллей-воинов." }, { 20.27, "Его сердце чернее ночи, а замыслы – омерзительны." }, { 24.13, "Найди его в пещере, прямо к северу отсюда, и принеси мне его голову!" } } }, t = { d = 8.2, v = "nightelf-male#54", n = { x = 84 }, c = { x = { { 0.00, "Теперь, когда лорд Меленас упокоился навек, я могу заняться и другими делами." }, { 6.29, "Прими мою благодарность." } } } } },
    [933] = { d = 21.1, v = "nightelf-male#54", n = { x = 237 }, c = { x = { { 0.00, "К юго-востоку от входа в Дарнасс, на берегу прудов Арлитриэна есть ещё один лунный колодец." }, { 6.82, "Стражам трудно наблюдать за этими местами из-за всё учащающихся нападений и всё большей злобности фурболгов из племени Кривой Сосны." }, { 16.65, "Будь начеку во время поисков колодца и держи оружие наготове." } } }, t = { d = 32.3, v = "nightelf-male#54", n = { x = 330 }, c = { x = { { 0.00, "Шан'до Ярость Бури так и не вернулся, и новостей про него до сих пор не поступало." }, { 6.43, "Друиды были в смятении." }, { 8.36, "После пропажи Малфуриона верховный друид Фэндрал Олений Шлем взял на себя руководство друидами, убедив Круг Древних на Тёмных Берегах, что нашему народу пора снова заполучить былую мощь и бессмертие." }, { 24.85, "С одобрения Круга Олений Шлем и самые могучие друиды вырастили Тельдрассил, новое Древо Жизни." } } } } },
    [934] = { d = 35.9, v = "nightelf-male#54", n = { x = 390 }, c = { x = { { 0.00, "Но не всё было ладно с Тельдрассилом." }, { 2.81, "Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие." }, { 11.02, "Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила." }, { 17.59, "Однако, пока я об этом говорить не буду." }, { 20.74, "Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула." }, { 26.97, "Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев." }, { 32.92, "Набери воды из него и возвращайся ко мне." } } }, t = { d = 35.9, v = "nightelf-male#54", n = { x = 389 }, c = { x = { { 0.00, "Находиться в присутствии Древа-оракула... это всё равно что увидеть воплощённую мудрость." }, { 6.93, "Позволь мне продолжить..." }, { 8.91, "Тельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена." }, { 19.24, "Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности." }, { 25.89, "Алекстраза также отказала Оленьему Шлему, а без её благословения рост Тельдрассила стал непредсказуем, и в нём обнаружились изъяны..." } } } } },
    [935] = { d = 34.7, g = 1, v = "nightelf-male#54", n = { m = 359, f = 360 }, c = { m = { { 0.00, "Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном." }, { 7.89, "Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников." }, { 15.36, "Могу только надеяться, что верховный друид быстро найдёт то, что ищет." }, { 20.71, "Я наполню все принесённые тобой фиалы, чтобы ты доставил их в Дарнасс." }, { 28.13, "Отнеси их к Фэндралу Оленьему Шлему, ты найдёшь его в роще друидов." } }, f = { { 0.00, "Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном." }, { 8.14, "Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников." }, { 15.85, "Могу только надеяться, что верховный друид быстро найдёт то, что ищет." }, { 21.36, "Я наполню все принесённые тобой фиалы, чтобы ты доставила их в Дарнасс." }, { 28.93, "Отнеси их к Фэндралу Оленьему Шлему, ты найдёшь его в роще друидов." } } }, t = { d = 23.8, v = "named/3516", n = { x = 247 }, c = { x = { { 0.00, "О, да, это та вода, о которой я просил." }, { 2.97, "Тенарон и Коритрас улучили минутку передать её... хотя гонца, может, и не самого надёжного выбрали... хм-м." }, { 10.94, "Однако теперь я могу вернуться к работе." }, { 14.05, "Бремя бед Тельдрассила тяжким гнётом лежит на моих плечах." }, { 18.44, "Но скоро я избавлюсь от этого ярма." }, { 21.14, "Вот, возьми." }, { 22.08, "Может, тебе пригодится." } } } } },
    [936] = { d = 26.7, g = 1, v = "orc-female#124", n = { x = 297 }, c = { m = { { 0.00, "Извини, герой, можно тебя на минутку?" }, { 2.82, "Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании." }, { 12.01, "Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем." }, { 18.84, "Если тебя это интересует, отправляйся в Громовой Утёс на Вершину Старейшин и поговори с самим Хамуулом." } }, f = { { 0.00, "Извини, героиня, можно тебя на минутку?" }, { 2.99, "Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании." }, { 12.30, "Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем." }, { 19.22, "Если тебя это интересует, отправляйся в Громовой Утёс на Вершину Старейшин и поговори с самим Хамуулом." } } }, t = { d = 21.3, g = 1, v = "creature/hamuul", n = { x = 208 }, c = { m = { { 0.00, "Привет тебе, герой!" }, { 1.61, "Рад, что ты хочешь помочь нам в наших исследованиях." }, { 5.61, "Дел у нас много, и я оказал бы тебе дурную услугу, если бы не предупредил, что работа опасная." }, { 12.90, "Надеюсь, тебя это не отпугнёт..." }, { 15.43, "Впрочем, судя по твоему виду, тебе не впервой встречаться с опасностями." } }, f = { { 0.00, "Привет тебе, героиня!" }, { 1.77, "Рад, что ты хочешь помочь нам в наших исследованиях." }, { 5.80, "Дел у нас много, и я оказал бы тебе дурную услугу, если бы не предупредил, что работа опасная." }, { 13.16, "Надеюсь, тебя это не отпугнёт..." }, { 15.70, "Впрочем, судя по твоему виду, тебе не впервой встречаться с опасностями." } } } } },
    [937] = { d = 24.6, v = "nightelf-female#52", n = { x = 316 }, c = { x = { { 0.00, "Меня отправили сюда с небольшим отрядом Часовых для защиты древа-оракула от гарпий, что устроили себе гнёзда по всей поляне." }, { 7.96, "Мы стараемся потихоньку вытеснить их отсюда." }, { 10.79, "Когда древо-оракул попыталось послать гонца в Дарнасс, на него напала стая гарпий и растерзала." }, { 17.02, "Если ты считаешь, что это задание тебе по плечу, иди к их гнездовью и принеси их пояса в доказательство своего подвига." } } }, t = { d = 8.5, g = 1, v = "nightelf-female#52", n = { m = 86, f = 88 }, c = { m = { { 0.00, "Спасибо, ты мне очень помог." }, { 2.18, "Давай я осмотрю эти пояса – посмотрим, укажут ли они на причину агрессии гарпий." } }, f = { { 0.00, "Спасибо, ты мне очень помогла." }, { 2.43, "Давай я осмотрю эти пояса – посмотрим, укажут ли они на причину агрессии гарпий." } } } } },
    [938] = { d = 22.6, v = "narrator", n = { x = 227 }, c = { x = { { 0.00, "Мех самки саблезуба имеет характерный серый цвет, сливающийся с фоном окружающего леса." }, { 7.09, "Вы видите, что она сильно пострадала: глубокие рваные раны видны на её спине и брюхе." }, { 14.10, "Она смотрит на вас, и в её голубых глазах читается глубокая мудрость." }, { 19.72, "Похоже, она хочет следовать за вами." } } }, t = { d = 15.7, v = "nightelf-female#52", n = { x = 178 }, c = { x = { { 0.00, "О, благодарю тебя!" }, { 1.33, "Я так боялась, что уж больше не увижу мою Туманну, скорбела всем сердцем о её гибели, о том, что навек разлучилась с моей верной спутницей..." }, { 11.14, "Я в неоплатном долгу перед тобой!" }, { 13.54, "Прими мою вечную благодарность." } } } } },
    [939] = { d = 37.0, v = "narrator", n = { x = 402 }, c = { x = { { 0.00, "Вы рассматриваете простую деревянную флейту, которую подобрали, сразив Ксаварика." }, { 6.28, "Узловатое дерево кажется твёрдым, но когда вы вертите её в руках, все спирали и полоски на флейте вдруг начинают вращаться и двигаться." }, { 16.60, "Вас внезапно охватывает нехорошее ощущение..." }, { 20.09, "Вы встряхиваетесь, уверенные, что это просто игра воображения." }, { 24.90, "Но, возможно, у других сатиров найдётся разгадка тайны вашей находки." }, { 30.27, "Отнесите её друиду Эридане Грусти Ветра, которая живёт в южной части Осквернённого леса." } } }, t = { d = 6.0, v = "nightelf-female", n = { x = 64 }, c = { x = { { 0.00, "Я чувствую страдания Древних..." }, { 2.39, "Держать в руках эти предметы почти невыносимо..." } } } } },
    [940] = { d = 27.4, v = "nightelf-female#52", n = { x = 326 }, c = { x = { { 0.00, "Шум леса донёс до меня весть о твоих подвигах." }, { 3.18, "Когда я ощутила, что гарпии покинули свои гнездовья, великий покой распространился по лесу и его обитатели снова ощутили себя в безопасности." }, { 13.04, "Я боялась посылать очередное сообщение верховному друиду, но теперь я знаю, что ты доставишь его ему в целости и сохранности." }, { 21.72, "Передай ему письмо и знай, что лес будет охранять тебя по дороге в каменные джунгли." } } }, t = { d = 25.8, g = 1, v = "named/3516", n = { m = 288, f = 289 }, c = { m = { { 0.00, "Я-то думал, почему Древо-оракул так долго не связывается со мной..." }, { 4.84, "Сдаётся мне, что как только мы решаем одну проблему, немедленно возникает другая, ещё более сложная." }, { 11.95, "Боюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернём себе бессмертие." }, { 18.66, "Тем не менее, ты славно справился с заданием Древа-оракула, и за усердие тебе положена награда." } }, f = { { 0.00, "Я-то думал, почему Древо-оракул так долго не связывается со мной..." }, { 4.84, "Сдаётся мне, что как только мы решаем одну проблему, немедленно возникает другая, ещё более сложная." }, { 11.95, "Боюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернём себе бессмертие." }, { 18.66, "Тем не менее, ты славно справилась с заданием Древа-оракула, и за усердие тебе положена награда." } } } } },
    [941] = { d = 13.5, v = "nightelf-male#59", n = { x = 155 }, c = { x = { { 0.00, "Я удалил этот смрадный мох с сердца, но оно всё ещё остаётся запятнанным..." }, { 5.29, "Попытайся посадить его в мою кадку." }, { 7.93, "Она наполнена плодородной землёй, которая может очистить и исцелить это сердце." } } }, t = { d = 15.4, v = "narrator", n = { x = 149 }, c = { x = { { 0.00, "Вы сажаете сердце в кадку, и оно быстро в неё зарывается!" }, { 4.73, "Через несколько секунд оно снова выкапывается из земли – уже очищенное." }, { 10.71, "Оно тихонько пульсирует... и вам хочется взять его в руки." } } } } },
    [942] = { d = 37.0, v = "dwarf-male", n = { x = 460 }, c = { x = { { 0.00, "Эта окаменелость поразительно похожа на другую, которую я однажды видел в Стальгорне." }, { 5.78, "Геолог по имени Бутылопуз приносил её на ежегодную конференцию Лиги Исследователей." }, { 11.38, "Он был уверен, что в этой окаменелости скрыта мощь, которую можно каким-то образом высвободить." }, { 17.77, "Последнее, что я слышал, что Бутылопуз обосновался в таверне \"Большая вода\" и ждёт, чтобы его сопроводили к раскопу Вельгара." }, { 26.17, "Найдите его и покажите ему окаменелость, найденную Сомнамбулером." }, { 30.61, "Может быть, он сумеет раскрыть секреты прошлого." }, { 33.89, "Корабль в Гавань Менетилов отходит из Аубердина." } } }, t = { d = 8.9, v = "dwarf-male", n = { x = 89 }, c = { x = { { 0.00, "О боги!" }, { 0.69, "Так вы говорите, эта вещь происходит из далёких земель Калимдора?" }, { 6.13, "Поразительно!" }, { 7.28, "Просто поразительно!" } } } } },
    [943] = { d = 29.8, v = "dwarf-male", n = { x = 353 }, c = { x = { { 0.00, "Геолог Вельгар, который сейчас находится на раскопе в Болотине, держит окаменелость у себя." }, { 6.29, "Когда я обнаружил камень Релу, то был уверен, что это ключ к тайне окаменелости." }, { 11.78, "Пока я шёл по дороге к Вельгару, на меня напали ящеры, и реликвия пропала." }, { 16.89, "Не знаю, какая из крапчатых тварей проглотила её, но если вам удастся её вернуть, я смогу высвободить силу этих артефактов." }, { 25.34, "Принесите мне и камень Релу, и окаменелость, хранящуюся у Вельгара." } } }, t = { d = 7.7, v = "dwarf-male", n = { x = 92 }, c = { x = { { 0.00, "Великолепно!" }, { 0.90, "Теперь посмотрим, смогу ли я использовать камень, чтобы распознать силы, скрытые в окаменелостях." } } } } },
    [944] = { d = 48.2, v = "creature/ancient", n = { x = 385 }, c = { x = { { 0.00, "Очень странно, что наги появились здесь, на Тёмных берегах." }, { 5.94, "Но ещё страннее – клан Сумеречного Молота." }, { 10.14, "Они поклоняются старым, очень старым богам этой земли." }, { 15.90, "Богам, давным-давно низвергнутым." }, { 19.37, "Меч Властителя, что к югу отсюда, – место, где пал один из этих древних богов." }, { 27.32, "Пойди туда и поищи других культистов Сумеречного Молота." }, { 33.16, "Возьми этот фиал виденья." }, { 35.91, "Используй его для создания гадальной чаши, когда разведаешь всё у Меча Властителя." }, { 44.31, "Посредством этой чаши поговори со мной." } } }, t = { d = 23.2, g = 1, v = "creature/ancient", n = { m = 185, f = 186 }, c = { m = { { 0.00, "Так ты обнаружил клан Сумеречного Молота у Меча Властителя?" }, { 5.62, "Плохо." }, { 6.31, "Древний бог, пронзённый мечом, давно мёртв, но это не значит, что исчезли и остатки его могущества." }, { 15.72, "Должно быть, клан Сумеречного Молота пытается найти его силу." } }, f = { { 0.00, "Так ты обнаружила клан Сумеречного Молота у Меча Властителя?" }, { 6.10, "Плохо." }, { 6.84, "Древний бог, пронзённый мечом, давно мёртв, но это не значит, что исчезли и остатки его могущества." }, { 16.91, "Должно быть, клан Сумеречного Молота пытается найти его силу." } } } } },
    [945] = { d = 24.4, v = "creature/dryad", n = { x = 227 }, c = { x = { { 0.00, "Помогите!" }, { 0.82, "Я бродила у Меча Властителя, как вдруг меня окружили эти жуткие культисты." }, { 7.04, "Счастье, что я умею отлично прятаться!" }, { 10.27, "Можете помочь мне отсюда выбраться?" }, { 13.26, "И ещё, мне нужно будет сообщить моей сестре Тересиль, что я в порядке." }, { 19.96, "Она в Ясеневом лесу, к югу отсюда, у святилища Эссины." } } }, t = { d = 20.8, v = "creature/dryad", n = { x = 182 }, c = { x = { { 0.00, "Моя сестра была – где?" }, { 2.08, "Тирелин любит бродить по всяким местам, но всё-таки!" }, { 6.72, "Это же очень далеко, да и Меч Властителя – вовсе не безопасное место..." }, { 13.04, "Ну, спасибо вам." }, { 14.48, "С вашей стороны было очень любезно сообщить мне, что с ней всё в порядке." } } } } },
    [947] = { d = 35.2, v = "nightelf-male#54", n = { x = 393 }, c = { x = { { 0.00, "Я тут составляю одно зелье, для которого нужны редкие грибы, растущие в одной-единственной пещере." }, { 7.29, "Пещера эта находится за водопадом Скалистый, к востоку и чуть севернее в горах." }, { 13.13, "Я бы и сам туда пошёл, но в Роще Древних мне порекомендовали держаться подальше от того места." }, { 19.96, "Наши почтенные союзники чувствуют, что в этой пещере таится какое-то незнакомое зло." }, { 26.19, "Прошу вас, соберите для меня эти грибы." }, { 29.18, "А в процессе заодно приглядитесь: может быть, вы сможете подтвердить опасения Дерев." } } }, t = { d = 16.7, v = "nightelf-male#54", n = { x = 169 }, c = { x = { { 0.00, "Большое вам спасибо." }, { 1.67, "Это отличные экземпляры!" }, { 3.71, "Кстати, когда вы были у водопада Скалистый, заметили ли что-нибудь, что могло подтвердить опасения Дерев?" }, { 12.22, "Дерева мудры, но я надеялся, что на сей раз они ошибаются." } } } } },
    [948] = { d = 23.0, v = "nightelf-male#54", n = { x = 227 }, c = { x = { { 0.00, "Ону, Древо Мудрости из Рощи Древних, знает о вашем путешествии к Скалистому водопаду и хочет поговорить с вами." }, { 9.09, "Роща расположена к югу отсюда, у подножья гор." }, { 12.86, "Дерева терпеливы и мудры." }, { 14.97, "Но если Ону ищет вашего совета касательно того, что вы видели у водопадов, то, боюсь, дело срочное." } } }, t = { d = 6.8, v = "creature/ancient", n = { x = 39 }, c = { x = { { 0.00, "Ты здесь." }, { 1.19, "Хорошо." }, { 2.25, "Нам есть... что обсудить." }, { 5.46, "Тебе и мне." } } } } },
    [949] = { d = 23.4, v = "creature/ancient", n = { x = 214 }, c = { x = { { 0.00, "Что замышляет клан Сумеречного Молота у Меча Властителя, неизвестно." }, { 6.08, "Но наверняка что-то недоброе." }, { 8.76, "Обыщите их лагерь у Меча Властителя..." }, { 12.25, "Ищите то, что может помочь нам понять их намерения." }, { 16.87, "Ведь мы должны узнать об их целях раньше, чем они выработают план действий." } } }, t = { d = 5.5, v = "narrator", n = { x = 57 }, c = { x = { { 0.00, "Книга написана от руки на древнем языке и прекрасно иллюстрирована." } } } } },
    [950] = { d = 22.2, v = "narrator", n = { x = 254 }, c = { x = { { 0.00, "Вглядываясь в сумеречный фолиант, можно сойти с ума." }, { 3.88, "Буквы начинают плыть и плясать перед глазами даже после мельком брошенного взгляда, и некогда прекрасный орнамент принимает гротескные формы." }, { 14.28, "Вырвать одну страницу с безумными каракулями – вот и всё, что вам удаётся сделать, пока вы не потеряли сознание." } } }, t = { d = 19.4, v = "creature/ancient", n = { x = 181 }, c = { x = { { 0.00, "Неизученная первобытная магия окружает этот пергамент с письменами." }, { 6.26, "Я чувствую, что над ним потрудились древние силы." }, { 10.76, "Будем надеяться, мы сумеем раскрыть цель деятельности клана Сумеречного Молота на Тёмном Берегу." } } } } },
    [951] = { d = 48.2, g = 1, v = "creature/ancient", n = { m = 444, f = 445 }, c = { m = { { 0.00, "Пергамент, который ты обнаружил близ Меча Властителя, – страница древнего текста... написанная эльфами!" }, { 8.63, "Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев." }, { 25.05, "Направляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии." }, { 35.72, "Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов." } }, f = { { 0.00, "Пергамент, который ты обнаружила близ Меча Властителя, – страница древнего текста... написанная эльфами!" }, { 9.39, "Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев." }, { 27.10, "Направляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии." }, { 38.61, "Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов." } } }, t = { d = 25.7, v = "creature/ancient", n = { x = 221 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.55, "Эти реликвии относятся к поре расцвета Матистры." }, { 6.27, "Этот некогда могучий оплот эльфов давно разрушен, но остатки магии ещё попадаются в руинах." }, { 15.11, "Будем надеяться, что нам удастся раскрыть тайны этого места раньше, чем это сделают наши враги." }, { 24.39, "Будь настороже." } } } } },
    [952] = { d = 25.6, v = "named/3516", n = { x = 306 }, c = { x = { { 0.00, "Если уж у тебя нашлось время передать письмо для Древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Тёмный Берег, прямо к югу от Аубердина." }, { 12.30, "Ты наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать." }, { 18.81, "Отнеси это Ону, Древу Мудрости." }, { 21.04, "Он ждёт от меня вести, точно так же, как я ждал вести с Поляны Оракула." } } }, t = { d = 16.0, v = "creature/ancient", n = { x = 110 }, c = { x = { { 0.00, "А." }, { 0.31, "Спасибо." }, { 1.33, "Тем не менее, это странно." }, { 4.40, "Верховный друид всегда так торопится." }, { 8.71, "Лес знает, что всему своё время." }, { 12.39, "Шан'до Ярость Бури это понимал." } } } } },
    [953] = { d = 35.2, v = "nightelf-female#52", n = { x = 433 }, c = { x = { { 0.00, "К востоку отсюда находятся руины Амет'Арана." }, { 3.03, "Сейчас их населяют неупокоенные духи высокорождённых, некогда живших в его стенах, но когда-то Амет'Аран был местом, где слуги Азшары свободно практиковались в своей могучей магии." }, { 15.09, "Меня послали исследовать эти руины, и я наткнулась на две большие таблички, на которых была неразборчиво начертана история Амет'Арана и его падения." }, { 25.10, "Пока я пыталась прочесть руны, на меня напали призраки, и я сбежала." }, { 29.76, "Пожалуйста, если можете, отправляйтесь в руины и расшифруйте таблички вместо меня." } } }, t = { d = 22.4, v = "nightelf-female#52", n = { x = 265 }, c = { x = { { 0.00, "У нас очень немного записей, относящихся ко времени Войны Древних, а особенно – к периоду разрушения Источника Вечности." }, { 8.42, "Что неудивительно, если вспомнить о том, какие ужасные события и катаклизмы тогда происходили." }, { 15.01, "Спасибо вам." }, { 15.89, "С вашей помощью моя работа здесь окончена, и я смогу представить Кругу Древних полный доклад." } } } } },
    [954] = { d = 38.8, v = "nightelf-male#54", n = { x = 415 }, c = { x = { { 0.00, "Руины Башал'Арана, расположенные к востоку отсюда, населены демоническими служителями зла." }, { 7.00, "Злые духи и сатиры, обосновавшиеся там, питаются магическими энергиями Башал'Арана, и силы их растут от постоянной подпитки энергией." }, { 17.39, "Но при этом я заметил, что к одному святилищу они не приближаются." }, { 22.55, "На западной стороне руин, на вершине небольшого утёса, распространяется странное синее свечение..." }, { 30.19, "Там и должно быть объяснение нежеланию демонов приближаться к этому месту." }, { 35.98, "Я хотел бы, чтобы вы его исследовали." } } }, t = { d = 35.9, g = 1, v = "nightelf-male", n = { m = 358, f = 358 }, c = { m = { { 0.00, "Ахх..." }, { 0.48, "Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезный герой?" }, { 8.83, "На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение..." }, { 23.11, "Но, прошу вас, пусть мой грубый язык не заставит вас уйти." }, { 27.46, "Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания." } }, f = { { 0.00, "Ахх..." }, { 0.50, "Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезная героиня?" }, { 9.37, "На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение..." }, { 24.28, "Но, прошу вас, пусть мой грубый язык не заставит вас уйти." }, { 28.83, "Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания." } } } } },
    [955] = { d = 39.0, g = 1, v = "nightelf-male", n = { m = 395, f = 397 }, c = { m = { { 0.00, "Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения." }, { 9.06, "Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук." }, { 19.74, "Хотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты помог мне найти то, что держит меня здесь." }, { 31.20, "Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на её след." } }, f = { { 0.00, "Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения." }, { 9.15, "Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук." }, { 19.95, "Хотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты помогла мне найти то, что держит меня здесь." }, { 31.68, "Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на её след." } } }, t = { d = 20.3, v = "nightelf-male", n = { x = 180 }, c = { x = { { 0.00, "И правда..." }, { 1.00, "Грелли Башал'Арана не владеют тем, что я ищу..." }, { 4.98, "Однако недавно они были в контакте с этим." }, { 8.74, "Недавно..." }, { 9.66, "Я имею в виду по меркам твоего времени, не моего." }, { 13.96, "Для меня \"недавно\" простирается глубоко в прошлое, почти что в другую эру..." } } } } },
    [956] = { d = 29.3, v = "nightelf-male", n = { x = 289 }, c = { x = { { 0.00, "Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, подозреваю, я знаю, в чём дело." }, { 10.01, "Несомненно, эта печать находится во владении сатира, предводительствующего ими." }, { 16.48, "Я убеждён, что моя догадка верна." }, { 19.21, "Она наверняка у одного из сатиров." }, { 22.08, "Если ты сможешь её добыть, то ты почти откроешь дверь моей темницы." }, { 27.59, "Мне не сдержать слёз..." } } }, t = { d = 14.3, v = "nightelf-male", n = { x = 152 }, c = { x = { { 0.00, "Мне трудно поверить, что вещь, которую я сейчас держу в руках, так долго держала меня самого..." }, { 7.17, "Не будем тратить времени." }, { 9.13, "Когда печать будет уничтожена, я снова вольно смогу бродить по лесам." } } } } },
    [957] = { d = 21.2, v = "nightelf-male", n = { x = 219 }, c = { x = { { 0.00, "Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорождённых." }, { 8.51, "В Амет'Аране – точно таких же руинах к югу отсюда – до сих пор горит древний синий огонь." }, { 15.61, "В этом огне печать может быть уничтожена." }, { 18.94, "Будь осторожнее в тех руинах..." } } }, t = { d = 33.6, v = "nightelf-male", n = { x = 335 }, c = { x = { { 0.00, "Я свободен!" }, { 0.97, "Я могу собственными глазами видеть, какие изменения произошли с нашим миром..." }, { 7.56, "Я узнаю только отдельные фрагменты." }, { 10.55, "Подумать только, что когда я в последний раз гулял на свободе, ещё существовал Источник и высокорождённые держали совет с Азшарой, нашей любимой королевой." }, { 23.28, "Я чувствую, что мой тюремщик, мой бывший хозяин, Атрикус, ещё жив..." }, { 28.82, "Моё осознание безнадёжности вскоре сменится мыслями о мести." } } } } },
    [958] = { d = 37.8, g = 1, v = "nightelf-male#54", n = { x = 404 }, c = { m = { { 0.00, "Вот задание, которое я вам поручаю, герой." }, { 3.25, "Видели ли вы руины Амет'Арана?" }, { 5.60, "Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда." }, { 11.76, "Когда-то Амет'Аран служил домом для многих могущественных высокорождённых, а теперь это – памятник разрушению, к которому привели их магические забавы." }, { 23.25, "Мне говорили часовые, что духи высокорождённых по-прежнему обитают там и что они используют свои древние магические приспособления." }, { 33.15, "Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить." } }, f = { { 0.00, "Вот задание, которое я вам поручаю, героиня." }, { 3.38, "Видели ли вы руины Амет'Арана?" }, { 5.72, "Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда." }, { 11.86, "Когда-то Амет'Аран служил домом для многих могущественных высокорождённых, а теперь это – памятник разрушению, к которому привели их магические забавы." }, { 23.30, "Мне говорили часовые, что духи высокорождённых по-прежнему обитают там и что они используют свои древние магические приспособления." }, { 33.16, "Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить." } } }, t = { d = 17.5, v = "nightelf-male#54", n = { x = 177 }, c = { x = { { 0.00, "Хотя это, безусловно, лишь игра моего воображения, я чувствую себя так, будто бы ощущаю в этих реликвиях ядовитое дыхание магии высокорождённых." }, { 11.88, "Я их уничтожу, чтобы давно уснувшее зло больше никогда не пробудилось." } } } } },
    [959] = { d = 35.2, v = "goblin-male", n = { x = 394 }, c = { x = { { 0.00, "Ой!" }, { 0.26, "Как видишь, у меня сегодня приключилась неприятность!" }, { 4.15, "Утром из Пиратской бухты пришла поставка." }, { 7.25, "И какая!" }, { 7.91, "Никогда не видел столько ящиков." }, { 10.35, "Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало." }, { 15.36, "В конце концов всё рухнуло на землю." }, { 18.07, "Не успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна девяностодевятилетней выдержки и бросился наутёк." }, { 27.50, "Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок." }, { 31.98, "Может, тебе хватит пороху, чтобы найти его?" } } }, t = { d = 9.1, v = "goblin-male", n = { x = 92 }, c = { x = { { 0.00, "Великолепно!" }, { 1.03, "И ведь меня едва не уволили!" }, { 3.39, "Теперь надо поскорее отнести подарок Газлоу." }, { 7.14, "Спасибо." }, { 7.88, "Отличная работа!" } } } } },
    [960] = { t = { d = 25.4, g = 1, v = "creature/ancient", n = { m = 206, f = 208 }, c = { m = { { 0.00, "Я размышляю над твоим заданием." }, { 3.07, "Размышляю о том, зачем здесь появились Сумеречный Молот и наги." }, { 9.20, "Когда будешь готов, используй фиал виденья, чтобы создать гадальную чашу." }, { 16.57, "Затем свяжись со мной через неё." }, { 19.72, "Если ты потерял свой фиал виденья, вот тебе другой." } }, f = { { 0.00, "Я размышляю над твоим заданием." }, { 3.14, "Размышляю о том, зачем здесь появились Сумеречный Молот и наги." }, { 9.41, "Когда будешь готова, используй фиал виденья, чтобы создать гадальную чашу." }, { 17.02, "Затем свяжись со мной через неё." }, { 20.24, "Если ты потеряла свой фиал виденья, вот тебе другой." } } } } },
    [961] = { t = { d = 21.0, v = "creature/ancient", n = { x = 191 }, c = { x = { { 0.00, "Появление культистов Сумеречного Молота тревожит меня." }, { 4.90, "Я должен поразмыслить над их намерениями..." }, { 8.67, "Когда узнаешь больше, поговори со мной через гадальную чашу." }, { 14.13, "Если тебе нужен фиал виденья, чтобы создать чашу, то... вот, возьми ещё один." } } } } },
    [962] = { d = 42.3, v = "scourge-female", n = { x = 389 }, c = { x = { { 0.00, "Королевское фармацевтическое общество из великого Подгорода Лордерона направило меня сюда с очень необычной целью." }, { 10.40, "Возможно, вы сумеете помочь мне, а, стало быть, и Тёмной Госпоже в трудах на благо Отрёкшихся." }, { 18.74, "Не так давно я изучала редкий образец флоры под названием змеецвет." }, { 24.88, "Я уверена, что в большом количестве это растение таит в себе великие возможности." }, { 32.33, "Увы, змеецвет можно найти только в самых тёмных закоулках Пещер Стенаний, опасной системе подземелий в Степях." } } }, t = { d = 5.6, v = "scourge-female", n = { x = 43 }, c = { x = { { 0.00, "Ах, замечательные экземпляры!" }, { 3.30, "Вы хорошо поработали." } } } } },
    [963] = { d = 32.0, v = "nightelf-male#59", n = { x = 347 }, c = { x = { { 0.00, "После битв за Источник Вечности я узнал, что Амет'Аран разрушен, жители его погибли – в том числе и моя возлюбленная Анайя." }, { 9.21, "Я никогда не думал, что и через тысячи лет воспоминания об Анайе будут тревожить мои сны." }, { 15.87, "Бродя в помрачении рассудка по лесам на Тёмном Берегу, я очутился в руинах Амет'Арана... где и увидел неупокоенный дух моей любимой." }, { 25.62, "Её нужно освободить, но у меня просто рука не поднимается." }, { 30.00, "Нужно уничтожить её призрак." } } }, t = { d = 15.0, v = "nightelf-male#59", n = { x = 160 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.20, "Может быть, было бы лучше... если бы я сам это сделал." }, { 5.26, "Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную." }, { 11.59, "Пожалуйста, оставь меня наедине с моим горем..." } } } } },
    [964] = { d = 35.4, v = "scourge-male#82", n = { x = 356 }, c = { x = { { 0.00, "Чтобы отомкнуть двери Некроситета, необходим Костяной ключ." }, { 4.90, "Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме." }, { 14.71, "Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой." }, { 24.00, "Но не будем отвлекаться, для начала нам понадобятся фрагменты скелетов." }, { 29.79, "Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи." } } }, t = { d = 34.6, v = "scourge-male#82", n = { x = 310 }, c = { x = { { 0.00, "Отличные образцы!" }, { 1.62, "Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придётся рано или поздно пройти." }, { 14.52, "Теперь придётся отыскать подходящую форму для отливки." }, { 19.39, "Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей." }, { 28.47, "Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает." } } } } },
    [965] = { d = 30.8, g = 1, v = "nightelf-female#52", n = { m = 367, f = 369 }, c = { m = { { 0.00, "Привет тебе, юный герой." }, { 1.74, "Меня зовут Элисса Звёздный Ветер, и моя задача – защищать Аубердин от всякого вреда." }, { 7.45, "С этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда." }, { 16.94, "Но он уже давно должен был вернуться." }, { 19.47, "Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью." }, { 24.03, "Я была бы тебе очень благодарна, если бы ты смог найти его и удостовериться, что с ним всё в порядке." } }, f = { { 0.00, "Привет тебе, юная героиня." }, { 1.86, "Меня зовут Элисса Звёздный Ветер, и моя задача – защищать Аубердин от всякого вреда." }, { 7.56, "С этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда." }, { 17.03, "Но он уже давно должен был вернуться." }, { 19.55, "Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью." }, { 24.10, "Я была бы тебе очень благодарна, если бы ты смогла найти его и удостовериться, что с ним всё в порядке." } } }, t = { d = 8.4, v = "nightelf-male#55", n = { x = 87 }, c = { x = { { 0.00, "Тебя прислала Элисса?" }, { 1.77, "Это хорошо." }, { 2.76, "У меня есть для неё тревожные вести, но не было возможности передать их ей." } } } } },
    [966] = { d = 36.2, v = "nightelf-male#55", n = { x = 441 }, c = { x = { { 0.00, "Группа чернокнижников обосновалась вокруг и внутри башни." }, { 3.94, "Я хотел было вернуться в Аубердин и доложить Элиссе раньше, но побоялся, что могу что-то пропустить, пока буду отсутствовать." }, { 12.56, "Делгрен подозревал, что подобная компания может собираться у башни, но не знал, зачем." }, { 18.41, "Несколько обрывков свитков пергамента, которые носят с собой чернокнижники, попали в мои руки, но мне нужно знать больше, чтобы разгадать эту головоломку." }, { 28.99, "Однако я предостерегаю вас от попытки вторгнуться в саму башню: чернокнижники, засевшие там, гораздо сильнее!" } } }, t = { d = 23.1, v = "nightelf-male#55", n = { x = 279 }, c = { x = { { 0.00, "Большое спасибо." }, { 1.17, "Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников..." }, { 6.94, "Хмм..." }, { 7.37, "Клан Тёмной Нити..." }, { 8.65, "Никогда раньше не слышал о такой группе." }, { 11.48, "Пока у нас нет никаких сведений об их истории, практически невозможно сказать, в чём могут заключаться их планы." }, { 19.03, "Больше нельзя тянуть." }, { 20.56, "Нужно немедленно предупредить Делгрена." } } } } },
    [967] = { d = 28.3, v = "nightelf-male#55", n = { x = 319 }, c = { x = { { 0.00, "Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от сил демонов и нежити." }, { 8.94, "Он многое поведал мне о Божественном Свете и воинском искусстве." }, { 13.60, "Делгрен должен немедленно узнать о деятельности клана." }, { 17.61, "Вы найдёте его далеко на юге отсюда, на Заставе Мейстры в Ясеневом лесу." }, { 22.93, "Поторопитесь – я боюсь, что угроза клана Тёмной Нити растёт с каждым часом." } } }, t = { d = 30.9, g = 1, v = "human-male", n = { m = 354, f = 355 }, c = { m = { { 0.00, "Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простого посланца, не так ли?" }, { 6.72, "Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадёт мне в руки." }, { 13.11, "Посмотрим, что он там пишет..." }, { 15.25, "Да, это тревожные новости." }, { 17.18, "Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их." }, { 22.87, "Вначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников." } }, f = { { 0.00, "Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простой посланницы, не так ли?" }, { 6.77, "Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадёт мне в руки." }, { 13.15, "Посмотрим, что он там пишет..." }, { 15.28, "Да, это тревожные новости." }, { 17.21, "Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их." }, { 22.89, "Вначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников." } } } } },
    [968] = { d = 41.5, v = "narrator", n = { x = 411 }, c = { x = { { 0.00, "Хотя книга ужасно истрёпана и исцарапана, её название на обложке всё же можно разобрать:" }, { 7.47, "\"Подземные Силы\"." }, { 9.01, "В книге перечисляются непроизносимые имена со зловещими титулами, способами почитания и предпочтительными жертвоприношениями..." }, { 19.64, "И среди этих жертвоприношений числятся живые разумные создания." }, { 25.11, "На внутренней стороне обложки написано: \"Руны и Жребии Костохвата, Заброшенный грот, Стальгорн." }, { 33.20, "Владелец: Геррик Костохват\"." }, { 35.67, "Если Костохват торгует подобными книгами, может быть, он выкупит эту?" } } }, t = { d = 33.9, g = 1, v = "dwarf-male", n = { m = 321, f = 324 }, c = { m = { { 0.00, "А, экземпляр \"Подземных сил\"." }, { 2.33, "Интересный текст, да уж." }, { 4.22, "А кое-кто найдёт его и полезным тоже..." }, { 7.43, "Но эта книга в ужасном состоянии." }, { 10.19, "И поглядите-ка!" }, { 11.43, "Заметки на полях – почти на каждой странице!" }, { 15.07, "Хм..." }, { 15.51, "Я помню этот экземпляр." }, { 17.47, "Я продал его Болгару в прошлом году." }, { 20.53, "Вы его... его друг?" }, { 22.13, "Да, должно быть, так." }, { 23.81, "У вас в глазах такой же огонь горит!" }, { 26.79, "Ну, по определению, друг Болгара – мой друг." }, { 30.21, "А мы должны поддерживать близких людей, правда?" } }, f = { { 0.00, "А, экземпляр \"Подземных сил\"." }, { 2.27, "Интересный текст, да уж." }, { 4.12, "А кое-кто найдёт его и полезным тоже..." }, { 7.24, "Но эта книга в ужасном состоянии." }, { 9.94, "И поглядите-ка!" }, { 11.15, "Заметки на полях – почти на каждой странице!" }, { 14.70, "Хм..." }, { 15.12, "Я помню этот экземпляр." }, { 17.04, "Я продал его Болгару в прошлом году." }, { 20.02, "Вы его... его подруга?" }, { 21.87, "Да, должно быть, так." }, { 23.50, "У вас в глазах такой же огонь горит!" }, { 26.41, "Ну, по определению, друг Болгара – мой друг." }, { 29.75, "А мы должны поддерживать близких людей, правда?" } } } } },
    [969] = { d = 31.3, g = 1, v = "troll-female#73", n = { m = 325, f = 326 }, c = { m = { { 0.00, "Ах, одного взгляда на тебя достаточно, чтобы сказать: ты захочешь себе счастливый оберег." }, { 7.00, "Мау'ари всегда всё знает!" }, { 9.03, "На юг пойди – найдёшь ущелье, а в нём гигантов, сделанных из кусков льда." }, { 14.56, "Кристаллы можно отобрать у гигантов, но можешь собирать их и сам в ущелье." }, { 20.30, "Эти кристаллы имеют отличную отражающую способность." }, { 24.43, "Принеси мне четыре кристалла великанов Ледяного Молота, и счастливый оберег станет твоим." } }, f = { { 0.00, "Ах, одного взгляда на тебя достаточно, чтобы сказать: ты захочешь себе счастливый оберег." }, { 6.97, "Мау'ари всегда всё знает!" }, { 8.99, "На юг пойди – найдёшь ущелье, а в нём гигантов, сделанных из кусков льда." }, { 14.50, "Кристаллы можно отобрать у гигантов, но можешь собирать их и сама в ущелье." }, { 20.35, "Эти кристаллы имеют отличную отражающую способность." }, { 24.46, "Принеси мне четыре кристалла великанов Ледяного Молота, и счастливый оберег станет твоим." } } }, t = { d = 5.4, v = "troll-female#73", n = { x = 41 }, c = { x = { { 0.00, "О да… сейчас я сделаю для тебя этот оберег." }, { 4.51, "Погоди-ка!" } } } } },
    [970] = { d = 25.0, v = "human-male", n = { x = 275 }, c = { x = { { 0.00, "Письмо Балтула приводит меня в ужас." }, { 2.73, "Этот клан Тёмной Нити – сущее бельмо у меня на глазу, и его надо устранить!" }, { 8.26, "Мне приходилось иметь дело с мерзавцами из Тёмной Нити к северо-востоку отсюда в Ордил'Аране." }, { 14.97, "У одного из них есть самоцвет Души, в котором, как я думаю, заключается секрет силы клана." }, { 21.48, "Принеси его мне, а уж я сумею разгадать его тайну." } } }, t = { d = 7.8, v = "human-male", n = { x = 75 }, c = { x = { { 0.00, "Хмм, этот самоцвет Души наполнен какой-то тёмной магией." }, { 4.70, "Давай-ка посмотрим, что в нём таится..." } } } } },
    [971] = { d = 37.8, v = "dwarf-male", n = { x = 394 }, c = { x = { { 0.00, "Насколько вам известно, я собираю знания." }, { 3.21, "Древние знания." }, { 4.46, "Могучие знания." }, { 5.71, "Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят." }, { 11.01, "Ходят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине Ясеневого леса." }, { 19.16, "Некогда там жили эльфы, но они давно уже мертвы." }, { 23.07, "Эльфы эти обладали великим знанием, до того как их город превратился в руины." }, { 29.13, "Найдите манускрипт в Непроглядной Пучине." }, { 32.33, "Сделайте это, и я не забуду вашей услуги." }, { 35.61, "Даже после... скончания дней." } } }, t = { d = 22.1, v = "dwarf-male", n = { x = 238 }, c = { x = { { 0.00, "Вы нашли манускрипт!" }, { 1.60, "Что за радостный день!" }, { 3.28, "Мы сделаем с него копии и распространим, и древнее знание Лоргалиса станет достоянием наших братьев и сестёр!" }, { 11.71, "Вы даже не понимаете, какую услугу нам оказали." }, { 15.40, "Но я надеюсь, что этот дар покажет вам всю глубину нашей признательности нашим союзникам." } } } } },
    [972] = { t = { d = 7.9, v = "tauren-female#71", n = { x = 73 }, c = { x = { { 0.00, "Возьми сапту воды и найди осквернённый водоём в Серебряном бору." }, { 5.68, "Я очень верю в твои силы." } } } } },
    [973] = { d = 20.2, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Илкруд Магтрулл." }, { 1.25, "Да, я знаю о нём." }, { 2.50, "Это могучий орочий чернокнижник, который поселился в Святилище Огненной Расщелины, месте великого зла на юго-западе Ясеневого леса." }, { 12.17, "Доныне он был не более чем досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться." } } }, t = { d = 10.2, g = 1, v = "human-male", n = { m = 110, f = 112 }, c = { m = { { 0.00, "Сегодня ты сделал большое дело." }, { 2.51, "Гордись – ты сразил могущественного чернокнижника." }, { 6.33, "А теперь посмотрим, что сказано в записях Илкруда." } }, f = { { 0.00, "Сегодня ты сделала большое дело." }, { 2.58, "Гордись – ты сразила могущественного чернокнижника." }, { 6.48, "А теперь посмотрим, что сказано в записях Илкруда." } } } } },
    [974] = { d = 31.1, v = "goblin-male", n = { x = 379 }, c = { x = { { 0.00, "Эти горячие источники всегда были для меня загадкой!" }, { 3.71, "Откуда берётся жар?" }, { 5.00, "Если учесть, что источники расположены совсем недалеко от Вулкана Огненного Венца, можно предположить, что их подогревает вулкан." }, { 13.84, "Я разработал термометр, чтобы измерять температуру вулкана, и теперь хочу выяснить, в какой точке она наиболее высока." }, { 22.06, "Термометр даёт результаты по шкале Кракленгейта." }, { 25.33, "Вот, держи, отправляйся на хребет и выясни, где там точка с самой высокой температурой!" } } }, t = { d = 14.7, v = "goblin-male", n = { x = 158 }, c = { x = { { 0.00, "Да, корреляция температур вулкана и горячих источников очевидна." }, { 5.08, "Конечно, надо бы ещё раз проверить правильность уравнений, однако создаётся впечатление, что расстояние и температура..." }, { 14.37, "Хмм..." } } } } },
    [975] = { d = 28.9, v = "troll-female#73", n = { x = 321 }, c = { x = { { 0.00, "А теперь, прежде чем я дам тебе этот вот оберег, объясню, как им пользоваться." }, { 5.50, "Если он у тебя с собой, окажется, что определённые предметы будут в добыче с тех созданий, с которыми ты бой вести будешь." }, { 14.06, "А если нет, то и предметов не найдёшь." }, { 16.69, "Понятно?" }, { 17.32, "Ты узнаешь их по имени – они называются э'ко." }, { 20.59, "Если найдёшь такие – приноси Мау'ари, она поможет тебе найти им применение." }, { 26.02, "Постой-ка тут, пока я твой оберег доделаю." } } }, t = { d = 10.3, g = 1, v = "troll-female#73", n = { m = 118, f = 118 }, c = { m = { { 0.00, "Вот и готово." }, { 0.94, "Помни, ты должен носить его с собой." }, { 3.58, "Почему бы тебе не отправиться обратно на природу из города и не посмотреть, что ты там обнаружишь?" } }, f = { { 0.00, "Вот и готово." }, { 0.96, "Помни, ты должна носить его с собой." }, { 3.64, "Почему бы тебе не отправиться обратно на природу из города и не посмотреть, что ты там обнаружишь?" } } } } },
    [976] = { d = 23.3, v = "human-male", n = { x = 280 }, c = { x = { { 0.00, "Делгрен попросил меня доставить письма и припасы часовому Звёздный Ветер в Аубердин, но мне очень не хочется ехать в одиночку." }, { 8.47, "В лесу опасные враги, а я не хочу, чтобы эти припасы и информация попали не в те руки." }, { 14.34, "Если ты с остальными согласитесь охранять меня, то я смогу уехать прямо сейчас." }, { 19.73, "Под вашей защитой я точно доставлю всё это в Аубердин." } } }, t = { d = 12.2, g = 1, v = "human-male", n = { m = 144, f = 145 }, c = { m = { { 0.00, "Ты сегодня славно поработал, герой." }, { 2.46, "То, что мы отослали в Аубердин, срочно необходимо для отражения тёмной угрозы, наводнившей лес." }, { 8.78, "Прими это вместе с моей сердечной благодарностью." } }, f = { { 0.00, "Ты сегодня славно поработала, героиня." }, { 2.62, "То, что мы отослали в Аубердин, срочно необходимо для отражения тёмной угрозы, наводнившей лес." }, { 8.89, "Прими это вместе с моей сердечной благодарностью." } } } } },
    [977] = { d = 31.3, v = "goblin-female#63", n = { x = 323 }, c = { x = { { 0.00, "Теперь, когда мне есть чем прикрыть механические движущиеся части, мне нужна только одна вещь." }, { 7.18, "Ну, точнее, две." }, { 8.43, "Два рога!" }, { 9.19, "Самые большие рога – у патриархов и матриархов клана, так что, естественно, именно их-то я и хочу." }, { 16.72, "Эта разновидность йети обитает в пещере к юго-востоку отсюда." }, { 21.55, "Их там очень много, ты без труда их отыщешь." }, { 24.94, "Помни, я хочу самые красивые рога – пожалуйста, не приноси ни побитых, ни сломанных!" } } }, t = { d = 8.1, v = "goblin-female#63", n = { x = 88 }, c = { x = { { 0.00, "Просто не могу дождаться, чтобы скорее показать своим друзьям!" }, { 4.79, "Погоди секунду, пока я прикреплю рога…" }, { 7.76, "Класс!" } } } } },
    [978] = { d = 35.0, v = "nightelf-male#55", n = { x = 387 }, c = { x = { { 0.00, "Перья диких совухов из Внутренних земель, кажется, содержат следы магии." }, { 5.50, "Эти силы… непохоже, что создания способны их контролировать, больше похоже на то, что магия просто является частью их сущности." }, { 14.97, "За время моих исследований я слыхал, что большая популяция диких совухов населяет заснеженные земли Зимних Ключей." }, { 23.56, "Вдруг у этих существ есть те же свойства?" }, { 26.58, "Пожалуйста, помоги мне найти ответ." }, { 29.27, "Отправляйся в Зимние Ключи, собери выпавшие перья и возвращайся с ними ко мне." } } }, t = { d = 4.6, v = "nightelf-male#55", n = { x = 45 }, c = { x = { { 0.00, "Теперь я могу сравнить перья между собой…" }, { 3.65, "Посмотрим-ка…" } } } } },
    [979] = { d = 25.3, g = 1, v = "nightelf-male#55", n = { m = 287, f = 288 }, c = { m = { { 0.00, "Да-да, на эти перья, похоже, наложены точно такие же чары, как и те, что я прежде заметил…" }, { 6.39, "Поскольку я совершенно не уверен в том, что именно мы нашли, я очень хочу, чтобы ты продолжил поиск ответов." }, { 13.98, "Моя коллега недавно отправилась в Зимние Ключи изучать там диких совухов в их естественной среде обитания." }, { 21.50, "Может, ты нагонишь её и выяснишь, что ей удалось узнать?" } }, f = { { 0.00, "Да-да, на эти перья, похоже, наложены точно такие же чары, как и те, что я прежде заметил…" }, { 6.31, "Поскольку я совершенно не уверен в том, что именно мы нашли, я очень хочу, чтобы ты продолжила поиск ответов." }, { 13.87, "Моя коллега недавно отправилась в Зимние Ключи изучать там диких совухов в их естественной среде обитания." }, { 21.31, "Может, ты нагонишь её и выяснишь, что ей удалось узнать?" } } }, t = { d = 8.9, v = "nightelf-female#53", n = { x = 96 }, c = { x = { { 0.00, "Привет!" }, { 0.62, "Вас прислал Эрелас??" }, { 2.19, "Здорово, я как раз собиралась отправиться в пещеры, и я отнюдь не возражаю против компании." } } } } },
    [980] = { d = 30.2, v = "goblin-male", n = { x = 331 }, c = { x = { { 0.00, "Слыхал я, что существуют и другие горячие источники – в местечке Зимние Ключи, далеко к северу отсюда." }, { 7.60, "И вот в чём загвоздка – в тех местах нет никаких вулканов!" }, { 11.79, "Очень любопытно..." }, { 13.19, "Что ж, тут можно сделать лишь одно – отправиться в Зимние Ключи и поговорить с моей тамошней приятельницей." }, { 21.06, "Её зовут Донова Снегонора, она живёт прямо рядом с источниками." }, { 25.79, "Ну, счастливой дороги!" }, { 27.45, "Ещё раз спасибо за помощь с термометром." } } }, t = { d = 4.3, v = "dwarf-female#34", n = { x = 34 }, c = { x = { { 0.00, "Здравствуй!" }, { 1.24, "Да, Кракл был совершенно прав..." } } } } },
    [981] = { d = 15.9, v = "nightelf-male#55", n = { x = 168 }, c = { x = { { 0.00, "За всю проделанную вами работу вы заслужили хорошую награду." }, { 4.81, "Возвращайтесь к Делгрену и скажите ему, что Атрикус Нарассин лежит, сражённый вашей рукой, а клан Тёмной Нити сокрушён, и остатки его рассеяны." } } }, t = { d = 13.3, v = "human-male", n = { x = 143 }, c = { x = { { 0.00, "Я знал, что вы возьмётесь за это задание." }, { 3.01, "Я чувствую, вас ждут великие дела и что вам суждено исцелить многие недуги, что терзают наши земли." }, { 10.55, "Примите моё благословение, и этот дар." } } } } },
    [982] = { d = 37.0, g = 1, v = "dwarf-male#99", n = { m = 418, f = 419 }, c = { m = { { 0.00, "У побережья Тёмного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\"." }, { 9.16, "Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина." }, { 18.82, "Теперь корабли лежат на дне океана, став добычей мурлоков." }, { 22.93, "Оба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках." }, { 30.51, "Я хотел бы, чтобы ты добыл их для нас; это много значило бы для членов команды." } }, f = { { 0.00, "У побережья Тёмного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\"." }, { 9.41, "Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина." }, { 19.33, "Теперь корабли лежат на дне океана, став добычей мурлоков." }, { 23.55, "Оба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках." }, { 31.33, "Я хотел бы, чтобы ты добыла их для нас; это много значило бы для членов команды." } } }, t = { d = 19.1, g = 1, v = "dwarf-male#99", n = { m = 215, f = 217 }, c = { m = { { 0.00, "Вы оказали нам огромную услугу, юноша." }, { 2.88, "Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход." }, { 8.23, "Что же касается вас, прошу вас принять это." }, { 11.44, "Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости." } }, f = { { 0.00, "Вы оказали нам огромную услугу, девушка." }, { 2.96, "Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход." }, { 8.24, "Что же касается вас, прошу вас принять это." }, { 11.40, "Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости." } } } } },
    [983] = { d = 39.7, g = 1, v = "goblin-male", n = { m = 417, f = 418 }, c = { m = { { 0.00, "Слушай!" }, { 0.58, "Помоги мне с моим последним изобретением, Жужжалкой." }, { 4.33, "С её помощью можно общаться на расстоянии!" }, { 7.37, "Может быть, ты уже видел их – такие ящики с рычагами." }, { 11.24, "С ними одна проблема – за ними нужен постоянный уход." }, { 15.18, "У каждой из них есть своя проблема, но я нашёл хитрое решение." }, { 19.58, "Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины." }, { 27.27, "Сейчас неисправна Жужжалка восемьсот двадцать семь." }, { 30.95, "Она находится чуть южнее Аубердина, совсем рядом с ним." }, { 34.95, "Чтобы её починить, нужно шесть ножек краба." }, { 38.12, "Я заплачу..." } }, f = { { 0.00, "Слушай!" }, { 0.58, "Помоги мне с моим последним изобретением, Жужжалкой." }, { 4.33, "С её помощью можно общаться на расстоянии!" }, { 7.22, "Может быть, ты уже видела их – такие ящики с рычагами." }, { 12.09, "С ними одна проблема – за ними нужен постоянный уход." }, { 16.03, "У каждой из них есть своя проблема, но я нашёл хитрое решение." }, { 20.43, "Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины." }, { 28.12, "Сейчас неисправна Жужжалка восемьсот двадцать семь." }, { 31.80, "Она находится чуть южнее Аубердина, совсем рядом с ним." }, { 35.80, "Чтобы её починить, нужно шесть ножек краба." }, { 38.97, "Я заплачу..." } } }, t = { d = 31.1, g = 1, v = "gnome-male", n = { m = 302, f = 303 }, c = { m = { { 0.00, "*Когда вы кладёте ножки крабов в приёмник машины, то слышите, как шестерни начинают их перемалывать.*" }, { 7.46, "*По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли своё место.*" }, { 13.67, "*Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины.*" }, { 19.88, "\"Алло!" }, { 20.57, "Уфф..." }, { 21.18, "Алло!" }, { 21.78, "Ты её починил!" }, { 23.16, "Кстати, это Бацбах." }, { 25.15, "Спасибо большое..." }, { 26.97, "Эй, не откажешься починить ещё одну машинку?\"" } }, f = { { 0.00, "*Когда вы кладёте ножки крабов в приёмник машины, то слышите, как шестерни начинают их перемалывать.*" }, { 7.61, "*По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли своё место.*" }, { 13.94, "*Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины.*" }, { 20.28, "\"Алло!" }, { 20.93, "Уфф..." }, { 21.50, "Алло!" }, { 22.07, "Ты её починила!" }, { 23.46, "Кстати, это Бацбах." }, { 25.33, "Спасибо большое..." }, { 27.05, "Эй, не откажешься починить ещё одну машинку?\"" } } } } },
    [984] = { d = 32.3, v = "nightelf-male#54", n = { x = 356 }, c = { x = { { 0.00, "Некоторые из моих собратьев спаслись от порабощённых порчей фурболгов в Тельдрассиле, а я пообещал остановить злодеяния, пока кровь не полилась рекой... или не произошло чего-то ещё хуже." }, { 13.95, "Я уже вижу признаки присутствия скверны на Тёмных берегах, но она ещё не так распространилась." }, { 20.96, "Я думаю, было бы логично продолжить исследования фурболгов." }, { 25.46, "Может быть, ты найдёшь один из их лагерей, а затем вернёшься ко мне, если увидишь следы порчи?" } } }, t = { d = 10.6, v = "nightelf-male#54", n = { x = 116 }, c = { x = { { 0.00, "Это и вправду ужасные новости." }, { 2.48, "Поскольку фурболги находятся так близко к Аубердину, нам придётся приготовиться к неизбежному." }, { 9.72, "Спасибо вам." } } } } },
    [985] = { d = 35.4, v = "nightelf-male#54", n = { x = 399 }, c = { x = { { 0.00, "Вы уже поднаторели в разведке на вражеских территориях." }, { 4.10, "Но способны ли вы не только следить за врагами, но и биться с ними?" }, { 9.06, "Не все искатели приключений предпочитают честную битву лицом к лицу искусству скрытности и уклонения." }, { 16.58, "Если вы считаете, что готовы к сражению, то наибольшую угрозу нашему народу представляют сейчас фурболги в лагере к югу от Аубердина." }, { 26.52, "Вы найдёте там фурболгов Чернолесья." }, { 29.14, "Убейте восемь следопытов и пять заклинателей ветра, а потом возвращайтесь сюда, ко мне." } } }, t = { d = 19.5, v = "nightelf-male#54", n = { x = 197 }, c = { x = { { 0.00, "Смойте кровь с ваших доспехов, и не мучайтесь из-за содеянного." }, { 5.20, "Вместо этого вознесите благодарность судьбе." }, { 8.91, "Вы уменьшили угрозу нашему народу здесь, в Аубердине, даже если весь Тёмный Берег пока ещё находится в опасности из-за Мха Скверны." } } } } },
    [986] = { d = 41.0, v = "nightelf-male#54", n = { x = 455 }, c = { x = { { 0.00, "Ваше мастерство уже один раз сослужило мне хорошую службу в сложной ситуации." }, { 5.86, "Могу ли я вновь возложить на вас задачу помочь Мрачнокогтю и его хозяину Волкору?" }, { 11.93, "Я могу сделать для вас волшебный плащ, который позволит вам беспрепятственно ходить вблизи враждебных существ Тёмного Берега, пока вы будете искать Волкора." }, { 23.52, "Для изготовления плаща, чтобы хватило материала, мне нужно пять прекрасных шкур лунопарда, снятых со взрослых самцов или матриархов." }, { 33.36, "Этих кошек можно найти около Петляющей реки, к югу отсюда, или ещё дальше на юг, близ Ясеневого леса." } } }, t = { d = 26.6, v = "nightelf-male#54", n = { x = 282 }, c = { x = { { 0.00, "Эти шкуры отлично подойдут." }, { 2.25, "Я немедленно приступаю к работе над плащом." }, { 5.63, "Дайте мне немного времени, а затем возвращайтесь." }, { 9.49, "Да, ещё кое-что: после того как вы задействуете чары, наложенные на плащ, вы будете ограничены в своём взаимодействии с другими лицами." }, { 19.83, "Если сможете, ограничьтесь только разговорами." }, { 23.49, "Всё, что сверх этого, может развеять чары." } } } } },
    [990] = { d = 18.8, v = "nightelf-female#52", n = { x = 228 }, c = { x = { { 0.00, "Моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу." }, { 5.73, "Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни." }, { 11.82, "Отправляйся отсюда на юг и держись дороги – ты легко найдёшь путь, если будешь держаться этого направления." } } }, t = { d = 17.9, g = 1, v = "nightelf-female#52", n = { x = 214 }, c = { m = { { 0.00, "А, герой с Тёмного Берега." }, { 1.72, "Хорошо, что Селарин прислала тебя так быстро." }, { 4.74, "Прости, что тебе пришлось так спешить." }, { 7.29, "Но с твоей помощью мы, возможно, сможем исправить положение." }, { 11.26, "Я бы начала с разговоров с другими жителями Астранаара." }, { 14.87, "Многим наверняка понадобится твоя помощь." } }, f = { { 0.00, "А, героиня с Тёмного Берега." }, { 1.87, "Хорошо, что Селарин прислала тебя так быстро." }, { 4.94, "Прости, что тебе пришлось так спешить." }, { 7.53, "Но с твоей помощью мы, возможно, сможем исправить положение." }, { 11.56, "Я бы начала с разговоров с другими жителями Астранаара." }, { 15.23, "Многим наверняка понадобится твоя помощь." } } } } },
    [991] = { d = 34.0, v = "nightelf-female#52", n = { x = 411 }, c = { x = { { 0.00, "Один мой старый друг тоже помогает часовым здесь, в Ясеневом лесу, но он ещё не вернулся." }, { 5.96, "Он думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником." }, { 16.19, "Прежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла." }, { 21.36, "Он также говорил, что камень может находиться в святилище на озере Фалатим у подножия западных гор." }, { 28.06, "Камень хранился там до того, как святилище было разрушено." }, { 32.01, "Найди моего друга, пожалуйста." } } }, t = { d = 13.8, v = "narrator", n = { x = 143 }, c = { x = { { 0.00, "Покрытое ранами тело Терониса лежит на острове." }, { 3.93, "По какой-то непонятной причине мурлоки бросили его здесь." }, { 8.60, "Глубокие резаные раны явно оставлены оружием и когтями мурлоков." } } } } },
    [992] = { d = 31.6, v = "goblin-male", n = { x = 374 }, c = { x = { { 0.00, "У нас, в Водной компании Прибамбасска, образовалась вакансия на должность младшего геодезиста на временную работу." }, { 8.00, "Интересуешься?" }, { 9.02, "Кочевники захватили все наши колодцы, приходится искать альтернативные источники воды!" }, { 15.17, "В пустыне есть вода, надо только её отыскать!" }, { 18.43, "Возьми это устройство для поиска воды и принеси мне пробу из пруда возле Заставы Скорбных Песков." }, { 25.47, "Правда, это место на виду у троллей." }, { 28.16, "Когда закончишь, принеси мне включённое устройство!" } } }, t = { d = 26.0, v = "goblin-male", n = { x = 291 }, c = { x = { { 0.00, "Что такое?" }, { 0.78, "На тебя напали какие-то мерзкие ползучие твари?" }, { 4.28, "Ох, плохо это для Водной компании Прибамбасска, ох плохо…" }, { 8.43, "Надо было раньше тебя предупредить насчёт этих кошмарных насекомых, которые, кажется, выпивают всю воду в пустыне." }, { 16.74, "Сначала я не придал им значения." }, { 19.07, "Нам хватает проблем и с кочевниками, и мы решили, что это тоже их происки." }, { 24.39, "Теперь мы знаем правду!" } } } } },
    [993] = { d = 35.2, g = 1, v = "nightelf-male#54", n = { m = 373, f = 374 }, c = { m = { { 0.00, "Плащ готов." }, { 0.86, "Пришло время найти Волкора." }, { 2.96, "Я могу только надеяться, что мы успеем." }, { 5.86, "Магия, скрытая в плаще, если её пробудить, продержится недолго: может быть, минут пять." }, { 12.25, "Сам решай, когда использовать: я бы предложил подождать, пока не найдёшь Мрачнокогтя." }, { 18.38, "Если то, что он сказал мне – правда, ты найдёшь его хозяина в пещере к югу отсюда." }, { 24.37, "Мрачнокоготь будет ждать тебя у дороги." }, { 27.27, "Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину." } }, f = { { 0.00, "Плащ готов." }, { 0.88, "Пришло время найти Волкора." }, { 3.04, "Я могу только надеяться, что мы успеем." }, { 6.00, "Магия, скрытая в плаще, если её пробудить, продержится недолго: может быть, минут пять." }, { 12.55, "Сама решай, когда использовать: я бы предложил подождать, пока не найдёшь Мрачнокогтя." }, { 18.96, "Если то, что он сказал мне – правда, ты найдёшь его хозяина в пещере к югу отсюда." }, { 25.09, "Мрачнокоготь будет ждать тебя у дороги." }, { 28.06, "Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину." } } }, t = { d = 17.0, v = "nightelf-male#55", n = { x = 168 }, c = { x = { { 0.00, "Чудесно!" }, { 0.70, "Терентис прислал мне помощь!" }, { 2.96, "О, посмотри-ка, ещё и плащ..." }, { 5.14, "Кхе-кхе..." }, { 5.99, "Ох..." }, { 6.41, "Больно." }, { 7.04, "Спасибо." }, { 7.75, "Фурболги ранили меня, прежде чем я сумел от них улизнуть." }, { 12.25, "Дай мне ещё минутку, и я буду в состоянии разговаривать дальше." } } } } },
    [994] = { d = 17.7, v = "nightelf-male#55", n = { x = 227 }, c = { x = { { 0.00, "Ладно, силой так силой." }, { 1.57, "Давайте убираться отсюда, как только вы будете готовы." }, { 5.11, "Мы пробьёмся к дороге – Мрачнокоготь должен всё ещё ждать." }, { 8.71, "А там мы уже сможем разделиться." }, { 10.80, "Терентис сразу же захочет услышать ваш рассказ, поэтому вы направитесь в Аубердин, когда мы отсюда выберемся." } } }, t = { d = 12.6, g = 1, v = "nightelf-male#54", n = { m = 139, f = 139 }, c = { m = { { 0.00, "Рад видеть вас живым и здоровым." }, { 2.39, "Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." } }, f = { { 0.00, "Рад видеть вас живой и здоровой." }, { 2.45, "Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." } } } } },
    [995] = { d = 17.8, v = "nightelf-male#55", n = { x = 198 }, c = { x = { { 0.00, "Ну, ладно..." }, { 0.91, "Если вы уверены, попробуем выскользнуть отсюда." }, { 4.38, "Мы уйдём, как только вы будете готовы." }, { 7.12, "Не забудьте после бегства отсюда вернуться к Терентису в Аубердин." }, { 11.96, "А я туда отправлюсь сам по себе, потому что, вероятно, буду двигаться быстрее вас." } } }, t = { d = 12.8, g = 1, v = "nightelf-male#54", n = { m = 139, f = 139 }, c = { m = { { 0.00, "Рад видеть вас живым и здоровым." }, { 2.42, "Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." } }, f = { { 0.00, "Рад видеть вас живой и здоровой." }, { 2.48, "Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." } } } } },
    [996] = { t = { d = 13.6, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений." }, { 6.77, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [997] = { d = 25.0, g = 1, v = "nightelf-female#51", n = { m = 276, f = 278 }, c = { m = { { 0.00, "Так ты идёшь на юг?" }, { 1.31, "К озеру Аль'Амет?" }, { 2.94, "Если да, то не выполнишь ли ты одну мою просьбу..." }, { 6.62, "Мой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты." }, { 16.28, "Ему нужна редкая земля из Дарнасса, но её доставили в Доланаар с опозданием – только что." }, { 22.79, "Не мог бы ты отнести ему эту землю?" } }, f = { { 0.00, "Так ты идёшь на юг?" }, { 1.27, "К озеру Аль'Амет?" }, { 2.54, "Если да, то не выполнишь ли ты одну мою просьбу..." }, { 6.10, "Мой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты." }, { 15.44, "Ему нужна редкая земля из Дарнасса, но её доставили в Доланаар с опозданием – только что." }, { 21.73, "Не могла бы ты отнести ему эту землю?" } } }, t = { d = 12.0, g = 1, v = "nightelf-male#59", n = { m = 106, f = 106 }, c = { m = { { 0.00, "Наконец-то!" }, { 0.94, "Я уже давно жду эту редкую землю." }, { 3.75, "Надеюсь, она ещё свежая..." }, { 5.92, "Спасибо тебе за доставку." }, { 8.01, "Ты – герой, не жалеющий времени на благие дела!" } }, f = { { 0.00, "Наконец-то!" }, { 0.95, "Я уже давно жду эту редкую землю." }, { 3.81, "Надеюсь, она ещё свежая..." }, { 6.00, "Спасибо тебе за доставку." }, { 8.13, "Ты – героиня, не жалеющая времени на благие дела!" } } } } },
    [998] = { t = { d = 13.3, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений." }, { 6.61, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [1000] = { d = 39.8, v = "tauren-male", n = { x = 414 }, c = { x = { { 0.00, "Внимание, герои!" }, { 1.43, "Круг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора – запретных диких краёв, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска!" }, { 18.00, "Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!" }, { 25.08, "Все заинтересованные лица да обращаются в Круг Кенария!" }, { 29.60, "За дополнительной информацией обращайтесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утёса!" } } }, t = { d = 34.2, g = 1, v = "creature/hamuul", n = { x = 301 }, c = { m = { { 0.00, "Здравствуй, герой." }, { 1.72, "Я рад, что героям, подобным тебе, небезразлична судьба природы." }, { 7.44, "Слава о твоих великих деяниях летела впереди тебя, и тебе здесь рады." }, { 13.89, "Узрев тебя, я исполнился уверенности, что Круг Кенария обретёт нужную ему помощь." }, { 21.25, "Наши связи с Кругом Кенария Лунной поляны превыше расовых и политических предрассудков." }, { 29.25, "Помни это, трудясь во славу Круга, и будет тебе благо." } }, f = { { 0.00, "Здравствуй, героиня." }, { 1.85, "Я рад, что героям, подобным тебе, небезразлична судьба природы." }, { 7.49, "Слава о твоих великих деяниях летела впереди тебя, и тебе здесь рады." }, { 13.86, "Узрев тебя, я исполнился уверенности, что Круг Кенария обретёт нужную ему помощь." }, { 21.11, "Наши связи с Кругом Кенария Лунной поляны превыше расовых и политических предрассудков." }, { 29.00, "Помни это, трудясь во славу Круга, и будет тебе благо." } } } } },
    [1001] = { d = 33.9, v = "gnome-male", n = { x = 334 }, c = { x = { { 0.00, "*Тоненький голосок пробивается откуда-то из глубины машины.*" }, { 4.32, "\"Бацбах у аппарата!" }, { 5.81, "Следующая Жужжалка находится к северу от Аубердина, прямо на берегу." }, { 10.98, "Итак, номер той Жужжалки – четыреста одиннадцать, и для её починки нужно три глаза крепкозуба." }, { 18.04, "Эти твари водятся недалеко от берега!" }, { 20.96, "Крепкозубы Тёмного Берега..." }, { 23.07, "Извини..." }, { 24.49, "Как и в прошлый раз, когда поместишь в Жужжалку то, что нужно, она выдаст тебе награду." }, { 31.08, "Что?" }, { 32.10, "Не, со мной всё в порядке!\"" } } }, t = { d = 27.4, g = 1, v = "gnome-male", n = { m = 259, f = 260 }, c = { m = { { 0.00, "*Жужжалка оживает вскоре после того, как вы помещаете в неё глаза крепкозуба.*" }, { 6.02, "*После коротких помех вы слышите знакомый голосок.*" }, { 9.92, "\"Вино из крабов лучше всего...\"" }, { 12.50, "\"Что?" }, { 13.64, "О, ты уже её починил!" }, { 15.36, "Ух, какой ты быстрый." }, { 17.08, "Так что, согласишься починить ещё одну?\"" }, { 20.16, "*Вы уверены, что слышите, как жидкость льётся в ёмкость, а затем – звучные глотки.*" } }, f = { { 0.00, "*Жужжалка оживает вскоре после того, как вы помещаете в неё глаза крепкозуба.*" }, { 6.22, "*После коротких помех вы слышите знакомый голосок.*" }, { 10.24, "\"Вино из крабов лучше всего...\"" }, { 12.94, "\"Что?" }, { 14.14, "О, ты уже её починила!" }, { 16.02, "Ух, какая ты быстрая." }, { 17.81, "Так что, согласишься починить ещё одну?\"" }, { 21.04, "*Вы уверены, что слышите, как жидкость льётся в ёмкость, а затем – звучные глотки.*" } } } } },
    [1002] = { d = 28.4, v = "gnome-male", n = { x = 266 }, c = { x = { { 0.00, "*Жужжалка издаёт треск статических помех, и вы слышите голос Бацбаха.*" }, { 5.92, "\"Следующая жужжалка – номер триста двадцать три." }, { 9.66, "Она к северу от Аубердина, но... а где же эль?" }, { 13.13, "Что?" }, { 13.48, "О, она стоит на дороге, так что ты легко её найдёшь около моста\"." }, { 18.40, "*Бацбах что-то неразборчиво бормочет, а потом вы слышите отчётливый звук глотка.*" }, { 24.76, "\"В эту нужно положить клыки лунопардов... шесть\"." } } }, t = { d = 18.3, g = 1, v = "gnome-male", n = { m = 166, f = 167 }, c = { m = { { 0.00, "*Неожиданно Жужжалка начинает работать, и вы отчётливо слышите, как клыки перемалываются внутри машины в муку.*" }, { 8.56, "\"Так что, ты это сделал!" }, { 10.83, "Отличные новости..." }, { 12.69, "И что же... ты не уходишь?" }, { 15.05, "А!" }, { 15.30, "Может, хочешь ещё поработать?\"" } }, f = { { 0.00, "*Неожиданно Жужжалка начинает работать, и вы отчётливо слышите, как клыки перемалываются внутри машины в муку.*" }, { 8.88, "\"Так что, ты это сделала!" }, { 11.22, "Отличные новости..." }, { 13.06, "И что же... ты не уходишь?" }, { 15.39, "А!" }, { 15.64, "Может, хочешь ещё поработать?\"" } } } } },
    [1003] = { d = 42.2, v = "gnome-male", n = { x = 388 }, c = { x = { { 0.00, "*Сквозь булькающий шум и звуки капающей жидкости, исходящие от машины, вы слышите неверный голос Бацбаха.*" }, { 8.88, "\"Следующий далеко на юг по дороге." }, { 11.43, "Найти должно быть нетрудно... сразу рядом на обочине... возле ограждения." }, { 16.93, "Думаю, я спрятал его в каких-то кустах..." }, { 20.09, "Кусты..." }, { 20.76, "Хи-хи..." }, { 21.43, "Да, Жужжалка пятьсот двадцать пять снимет седые скальпы с этих седых колючешёрстных медведей." }, { 28.34, "Боже мой, что за пойло." }, { 30.08, "Гнусные..." }, { 30.89, "Хи-хи-хи...\"" }, { 31.76, "*Вы слышите звуки жадных глотков, и машина выключается.*" }, { 36.91, "*Затем, совершенно неожиданно, вновь оживает.*" }, { 40.96, "\"Четыре!\"" } } }, t = { d = 31.2, v = "gnome-male", n = { x = 369 }, c = { x = { { 0.00, "Так ты что, положил скальпы внутрь?" }, { 2.36, "Хорошо..." }, { 3.04, "Что?" }, { 3.35, "Ага, я соображаю, что могу разговаривать с тобой и без материалов в машине." }, { 8.50, "Но я правду говорил, когда сказал, что они сломались!" }, { 12.23, "Смотри, кроме средств коммуникации эти жужжалки ещё варят и дистиллируют отличное питьё." }, { 18.25, "Прости за обман, но Ночные эльфы не одобряют торговли моими напитками в своих городах." }, { 24.27, "Я оставлю нечто особенное в этом ящике, чтобы показать мою благодарность за твои усилия." }, { 30.47, "Наслаждайся!" } } } } },
    [1004] = { d = 31.0, v = "scourge-male#83", n = { x = 346 }, c = { x = { { 0.00, "Внимание, герои!" }, { 1.33, "Круг Кенария ищет отважных, которые помогут исследовать новое пограничье Калимдора!" }, { 7.87, "К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши." }, { 14.05, "Круг нуждается в доблестных помощниках!" }, { 17.06, "Все заинтересованные лица могут обращаться в Круг Кенария." }, { 21.56, "Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утёса." } } }, t = { d = 33.3, g = 1, v = "creature/hamuul", n = { x = 332 }, c = { m = { { 0.00, "Здравствуй, герой!" }, { 1.55, "Приятно видеть, что таким, как ты, небезразлично благополучие природы." }, { 7.22, "Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады." }, { 12.81, "Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается." }, { 20.10, "Наша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий." }, { 27.39, "Помни это, когда будешь действовать от имени Круга, – и добьёшься успеха." } }, f = { { 0.00, "Здравствуй, героиня!" }, { 1.67, "Приятно видеть, что таким, как ты, небезразлично благополучие природы." }, { 7.26, "Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады." }, { 12.78, "Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается." }, { 19.97, "Наша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий." }, { 27.16, "Помни это, когда будешь действовать от имени Круга, – и добьёшься успеха." } } } } },
    [1007] = { d = 34.0, v = "nightelf-male#59", n = { x = 395 }, c = { x = { { 0.00, "Я хотел бы дать тебе поручение." }, { 2.17, "Я на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги, выныривая из воды и вцепляясь в меня когтями!" }, { 11.77, "Я убежал, унеся с собой всё, что смог, и чего хватило лишь вот на этот жалкий лагерь." }, { 17.60, "Но когда я добрался до берега и побежал... я потерял одну дорогую мне вещь." }, { 22.74, "Прошу тебя, найди место засады – это на побережье к северу – и отыщи древнюю статуэтку." }, { 28.88, "Именно из-за неё я отважился подвергнуть себя опасностям Зорамского взморья." } } }, t = { d = 10.6, g = 1, v = "nightelf-male#59", n = { m = 106, f = 106 }, c = { m = { { 0.00, "Ты её нашёл!" }, { 0.97, "Спасибо тебе!" }, { 2.16, "Древний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них." } }, f = { { 0.00, "Ты её нашла!" }, { 1.04, "Спасибо тебе!" }, { 2.22, "Древний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них." } } } } },
    [1008] = { d = 30.2, v = "nightelf-female#52", n = { x = 355 }, c = { x = { { 0.00, "По нашему северо-западному побережью, известному как Зорамское взморье, расползается зло." }, { 6.21, "Там покоятся руины злосчастного города Зорам, разрушенного при Расколе и поглощённого морем." }, { 12.62, "Для ночных эльфов он был утрачен на много веков." }, { 16.04, "Утрачен и почти забыт." }, { 17.69, "Теперь туда вернулись наги, и мы не знаем, почему." }, { 21.30, "Но причина не так важна – мы должны перебить этих тварей и загнать их обратно в глубины!" }, { 27.51, "Возвращайся, когда выполнишь поручение." } } }, t = { d = 18.8, v = "nightelf-female#52", n = { x = 201 }, c = { x = { { 0.00, "Отлично." }, { 0.68, "Твои деяния против наг на Зорамском взморье достойны похвалы." }, { 5.37, "Я знаю, что задание выполнить было нелегко, ибо сила и коварство наг прекрасно известны ночным эльфам." }, { 13.18, "Мы это знаем, ибо у нас одна история." }, { 16.10, "Но эту историю я вспоминать не желаю." } } } } },
    [1009] = { d = 30.1, v = "nightelf-male#59", n = { x = 343 }, c = { x = { { 0.00, "Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не найти ключа к этому древнему замку." }, { 7.85, "Этим ключом является кольцо – кольцо Зорама." }, { 11.13, "Оно принадлежало правителям этого города до того, как волны Раскола поглотили его." }, { 17.11, "Долгие годы кольцо считалось утраченным, пока наги недавно не нашли его." }, { 22.44, "Их предводительница, Руузель, живёт на острове на северной окраине Зорама." }, { 27.65, "Прошу тебя, добудь мне это кольцо!" } } }, t = { d = 9.9, g = 1, v = "nightelf-male#59", n = { m = 95, f = 97 }, c = { m = { { 0.00, "Ты добыл кольцо!" }, { 1.40, "Спасибо тебе." }, { 2.57, "Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты сделал сегодня." } }, f = { { 0.00, "Ты добыла кольцо!" }, { 1.45, "Спасибо тебе." }, { 2.61, "Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты сделала сегодня." } } } } },
    [1010] = { d = 34.4, v = "nightelf-male#54", n = { x = 356 }, c = { x = { { 0.00, "Есть одна травка, что росла некогда в древних руинах Убежища Батрана на севере." }, { 6.33, "Звалась эта травка Батранов волос и славилась тем, что лечила болезни души." }, { 12.37, "В этой деревне болеет ребёнок, и сдаётся мне, что это болезнь не телесная." }, { 18.13, "Не сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос?" }, { 23.32, "Мне он может понадобиться, чтобы вылечить ребёнка." }, { 27.23, "Убежище Батрана лежит к северу от заставы Мейстры и прямо к югу от границы с Тёмным Берегом." } } }, t = { d = 17.0, g = 1, v = "nightelf-male#54", n = { m = 153, f = 155 }, c = { m = { { 0.00, "Ах, ты принёс эту травку!" }, { 2.24, "Теперь я сварю лекарство для ребёнка, и будем молиться, чтобы отвар подействовал." }, { 9.44, "И..." }, { 9.84, "В Убежище Батрана – Отрёкшиеся?" }, { 12.56, "Очень тревожная весть." }, { 14.56, "Поистине, очень тревожная..." } }, f = { { 0.00, "Ах, ты принесла эту травку!" }, { 2.37, "Теперь я сварю лекарство для ребёнка, и будем молиться, чтобы отвар подействовал." }, { 9.23, "И..." }, { 9.61, "В Убежище Батрана – Отрёкшиеся?" }, { 12.21, "Очень тревожная весть." }, { 14.11, "Поистине, очень тревожная..." } } } } },
    [1011] = { d = 34.5, v = "nightelf-male#54", n = { x = 335 }, c = { x = { { 0.00, "Отрёкшиеся, нежить из Орды, проникли в Ясеневый лес, и рыщут среди развалин и курганов." }, { 7.10, "Мы уверены, что их цель – распространить чуму по землям ночных эльфов." }, { 12.80, "Мы должны убедиться в этом!" }, { 15.10, "Отрёкшиеся разбили лагерь к югу отсюда, рядом с Обителью Дор'Данил, где они готовят яды и заразу и разливают их по бутылкам." }, { 25.31, "Проложи себе путь в этот лагерь и укради бутыль с заразой." }, { 30.19, "Принеси её сюда." }, { 31.60, "Я исследую её и узнаю, для чего она." } } }, t = { d = 7.7, v = "nightelf-male#54", n = { x = 79 }, c = { x = { { 0.00, "Очень хорошо." }, { 1.19, "Теперь, когда я проанализирую содержимое бутыли, станут понятны цели Отрёкшихся!" } } } } },
    [1012] = { d = 35.6, g = 1, v = "nightelf-male#54", n = { m = 346, f = 346 }, c = { m = { { 0.00, "Когда я боролся с ядами Отрёкшихся, мне было видение." }, { 4.37, "Я узрел друидов Обители Дор'Данил, они были отравлены... убиты нежитью!" }, { 10.37, "Теперь они стали блуждающими духами, разлучёнными с телами и обезумевшими от этого." }, { 17.18, "Чтобы души этих друидов обрели покой, ты должен войти в Обитель Дор'Данил и уничтожить её некогда могучих предводителей – Таниэля Тёмный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца." }, { 32.37, "Сделай это и возвращайся ко мне." } }, f = { { 0.00, "Когда я боролся с ядами Отрёкшихся, мне было видение." }, { 4.46, "Я узрел друидов Обители Дор'Данил, они были отравлены... убиты нежитью!" }, { 10.58, "Теперь они стали блуждающими духами, разлучёнными с телами и обезумевшими от этого." }, { 17.54, "Чтобы души этих друидов обрели покой, ты должна войти в Обитель Дор'Данил и уничтожить её некогда могучих предводителей – Таниэля Тёмный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца." }, { 33.03, "Сделай это и возвращайся ко мне." } } }, t = { d = 21.0, g = 1, v = "nightelf-male#54", n = { m = 200, f = 202 }, c = { m = { { 0.00, "Я ощутил, как утихает боль Обители Дор'Данил, и понял, что ты выполнил свою задачу." }, { 6.83, "Тяжёлое дело выпало тебе, ибо духи, которых ты уничтожил, всего лишь жертвы злобы Отрёкшихся." }, { 14.55, "Но с их погибелью, будем надеяться, и другие безумные духи обретут покой." } }, f = { { 0.00, "Я ощутил, как утихает боль Обители Дор'Данил, и понял, что ты выполнила свою задачу." }, { 7.04, "Тяжёлое дело выпало тебе, ибо духи, которых ты уничтожила, всего лишь жертвы злобы Отрёкшихся." }, { 14.99, "Но с их погибелью, будем надеяться, и другие безумные духи обретут покой." } } } } },
    [1013] = { d = 31.8, v = "scourge-male", n = { x = 281 }, c = { x = { { 0.00, "В крепости Тёмного Клыка хранится книга – книга Ура, я хочу видеть её в своей коллекции." }, { 8.19, "Ур был великим магом Даларана до того, как оказался в рядах Плети, и его труды по иным мирам представляют большой интерес... для некоторых Отрёкшихся." }, { 21.91, "Отправляйся в крепость Тёмного Клыка и найди книгу." }, { 26.63, "Принеси мне её, и я сообщу о твоих заслугах Тёмной Госпоже." } } }, t = { d = 30.2, v = "scourge-male", n = { x = 263 }, c = { x = { { 0.00, "Прекрасно." }, { 1.01, "Эта книга будет прекрасным дополнением моей коллекции трудов Ура." }, { 7.33, "Знания его были велики, однако совесть не давала ему обрести настоящую силу." }, { 14.74, "Именно поэтому он не смог противостоять Плети." }, { 19.04, "Мы, Отрёкшиеся, не можем позволить себе роскошь быть слабыми – ведь тогда нам не выжить..." }, { 27.29, "И уж тем более не обрести власть." } } } } },
    [1014] = { d = 35.3, v = "scourge-male#82", n = { x = 339 }, c = { x = { { 0.00, "Аругал по-прежнему сидит в крепости Тёмного Клыка." }, { 4.39, "Мы не можем считать Серебряный бор стратегическим оплотом Тёмной Госпожи до тех пор, пока Аругал жив." }, { 13.01, "Я позабочусь о том, чтобы искоренить его магию." }, { 17.17, "Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам." }, { 23.91, "Отправляйтесь в крепость Тёмного Клыка и положите конец скверным деяниям Аругала раз и навсегда." }, { 32.22, "И принесите мне голову этого злодея!" } } }, t = { d = 13.6, v = "scourge-male#82", n = { x = 117 }, c = { x = { { 0.00, "Наконец-то Серебряный бор избавлен от злодеяний Аругала." }, { 5.65, "Вы сослужили огромную службу Тёмной Госпоже." }, { 10.12, "Ваша стойкость будет вознаграждена." } } } } },
    [1015] = { d = 25.9, v = "human-male", n = { x = 303 }, c = { x = { { 0.00, "Внимание, герои!" }, { 1.24, "Круг Кенария ищет смельчаков, готовых исследовать окраины Калимдора!" }, { 6.22, "Забытые пустоши, полные неизвестных опасностей, лежат к западу от Танариса и Прибамбасска." }, { 12.77, "Круг Кенария призывает храбрых героев изучить эти земли." }, { 16.96, "Все желающие должны пройти собеседование в Круге Кенария." }, { 21.15, "Обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнассе!" } } }, t = { d = 31.9, g = 1, v = "named/3516", n = { x = 353 }, c = { m = { { 0.00, "С чего вы решили, что я собираюсь тратить время на таких, как вы, герой?" }, { 5.00, "Хотя погодите..." }, { 6.18, "Дайте мне разобраться с моими повседневными обязанностями, и тогда, может быть, у меня для вас найдётся пара минут." }, { 14.06, "Нет, ну разумеется, благо Дарнасса, да что там – Тельдрассила! – это такая ерунда по сравнению с вашим желанием получить новую побрякушку..." }, { 23.68, "Эти недоумки из Лунной поляны, с их призывом на помощь, тратят моё время – не представляю, как выдержу всё это?!" } }, f = { { 0.00, "С чего вы решили, что я собираюсь тратить время на таких, как вы, героиня?" }, { 5.21, "Хотя погодите..." }, { 6.41, "Дайте мне разобраться с моими повседневными обязанностями, и тогда, может быть, у меня для вас найдётся пара минут." }, { 14.41, "Нет, ну разумеется, благо Дарнасса, да что там – Тельдрассила! – это такая ерунда по сравнению с вашим желанием получить новую побрякушку..." }, { 24.19, "Эти недоумки из Лунной поляны, с их призывом на помощь, тратят моё время – не представляю, как выдержу всё это?!" } } } } },
    [1016] = { d = 30.6, v = "nightelf-female#52", n = { x = 407 }, c = { x = { { 0.00, "Возьми этот гадальный свиток – он поможет определить создателя этих элементалей." }, { 5.15, "Но тебе понадобится кое-что взять у этих духов для фокусировки магии свитка – их браслеты прекрасно подойдут." }, { 12.08, "Хватит нескольких неповреждённых браслетов с этих существ." }, { 15.75, "Другие для наших целей бесполезны, но зато у торговцев за них можно кое-что выручить, если пожелаешь продать." }, { 22.74, "Как только ты добудешь неповреждённые браслеты, попытайся использовать свиток." }, { 27.60, "Возвращайся ко мне с результатами, и мы продолжим." } } }, t = { d = 26.2, v = "nightelf-female#52", n = { x = 332 }, c = { x = { { 0.00, "Хорошая работа, это даст нам информацию, необходимую для того, чтобы раскрыть преступника." }, { 5.98, "Ты не против помочь нам схватить мага, который наполнил наши пруды порчеными элементалями?" }, { 12.02, "У меня сердце сжимается при виде осквернённого Ясеневого леса и других мест, и я просто сгораю от нетерпения схватить волшебника, который так старается ещё сильнее навредить этому краю." }, { 24.23, "Мы заставим его за всё ответить." } } } } },
    [1017] = { d = 34.8, v = "nightelf-female#52", n = { x = 429 }, c = { x = { { 0.00, "Есть только один маг из нежити в Степях, способный наслать порчу на стольких элементалей воды." }, { 6.39, "И он единственный, кому хватит дури попытаться это сделать." }, { 10.47, "Сарилус Грязнорождённый, наверное, сидит на вершине Вершины Багрового Тумана, да смеётся надо мной." }, { 17.04, "Тебе придётся проникнуть на вражескую территорию и уничтожить этого мерзавца." }, { 22.22, "Мне надоела его бестолковость, и надо показать ему, что бывает с теми, кто донимает часовых." }, { 28.49, "Уничтожь его и принеси мне его голову." }, { 31.17, "Но соблюдай осторожность, Орда может подкараулить тебя." } } }, t = { d = 16.4, v = "nightelf-female#52", n = { x = 168 }, c = { x = { { 0.00, "Теперь эта мерзкая ухмылка навсегда стёрта с его лица." }, { 4.31, "Славное, воистину славное дело." }, { 6.81, "Возьми – это Свет Элуны, испей его, когда будет казаться, что всему конец, и смерть неминуема." }, { 14.19, "Он спасёт тебя по воле Богини." } } } } },
    [1018] = { d = 32.8, v = "orc-male", n = { x = 354 }, c = { x = { { 0.00, "Внимание, герои!" }, { 1.38, "Круг Кенария ищет отважных, которые помогут исследовать обширное новое пограничье Калимдора!" }, { 8.87, "К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши." }, { 15.28, "Круг нуждается в доблестных помощниках!" }, { 18.40, "Все заинтересованные лица могут обращаться в Круг Кенария." }, { 23.06, "Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утёса." } } }, t = { d = 33.4, g = 1, v = "creature/hamuul", n = { x = 332 }, c = { m = { { 0.00, "Здравствуй, герой!" }, { 1.55, "Приятно видеть, что таким, как ты, небезразлично благополучие природы." }, { 7.23, "Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады." }, { 12.84, "Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается." }, { 20.15, "Наша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий." }, { 27.46, "Помни это, когда будешь действовать от имени Круга, – и добьёшься успеха." } }, f = { { 0.00, "Здравствуй, героиня!" }, { 1.67, "Приятно видеть, что таким, как ты, небезразлично благополучие природы." }, { 7.28, "Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады." }, { 12.81, "Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается." }, { 20.02, "Наша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий." }, { 27.22, "Помни это, когда будешь действовать от имени Круга, – и добьёшься успеха." } } } } },
    [1019] = { d = 33.0, v = "dwarf-male", n = { x = 388 }, c = { x = { { 0.00, "Внимание, герои!" }, { 1.26, "Круг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора – запретных диких краёв, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска!" }, { 15.82, "Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!" }, { 22.05, "Все заинтересованные лица да обращаются в Круг Кенария!" }, { 26.02, "За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнассе!" } } }, t = { d = 29.2, g = 1, v = "named/3516", n = { m = 332, f = 333 }, c = { m = { { 0.00, "С чего ты решил, что я буду утруждать себя беседой с таким, как ты, герой?" }, { 5.24, "Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу!" }, { 11.55, "Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идёт с важностью поиска этой пустяковины для твоей коллекции!" }, { 20.57, "Сначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я ещё и это сносить должен?" } }, f = { { 0.00, "С чего ты решила, что я буду утруждать себя беседой с такой, как ты, героиня?" }, { 5.24, "Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу!" }, { 11.34, "Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идёт с важностью поиска этой пустяковины для твоей коллекции!" }, { 20.06, "Сначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я ещё и это сносить должен?" } } } } },
    [1020] = { d = 15.7, v = "nightelf-male#54", n = { x = 166 }, c = { x = { { 0.00, "Я изготовил лекарство, которое, надеюсь, поможет больному ребёнку." }, { 5.11, "Отнеси его в Астранаар отцу ребёнка, Пельтуру Белой Луне." }, { 9.67, "Чтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток." } } }, t = { d = 10.8, v = "nightelf-male#54", n = { x = 112 }, c = { x = { { 0.00, "Это от Орендила?" }, { 1.33, "Он славен знанием трав и лекарским искусством." }, { 4.88, "Это лекарство вселяет в меня надежду, которой прежде у меня почти не было..." } } } } },
    [1021] = { d = 26.6, g = 1, v = "named/3901", n = { m = 257, f = 257 }, c = { m = { { 0.00, "Послушай, я не знаю, кто ты, но мне нужна помощь." }, { 3.96, "Мои сёстры отправились отнять у одного сатира Ветвь Кенария." }, { 8.88, "Они сказали, что скоро вернутся, но уже целых два дня прошло!" }, { 13.95, "Ты должен найти их!" }, { 15.56, "Они искали развалины храма ночных эльфов в Ксавиане на северо-западе." }, { 21.36, "Не знаю, что и думать." }, { 23.20, "Найди Анилию, это она повела их на поиски." } }, f = { { 0.00, "Послушай, я не знаю, кто ты, но мне нужна помощь." }, { 3.94, "Мои сёстры отправились отнять у одного сатира Ветвь Кенария." }, { 8.83, "Они сказали, что скоро вернутся, но уже целых два дня прошло!" }, { 13.86, "Ты должна найти их!" }, { 15.47, "Они искали развалины храма ночных эльфов в Ксавиане на северо-западе." }, { 21.23, "Не знаю, что и думать." }, { 23.06, "Найди Анилию, это она повела их на поиски." } } }, t = { d = 4.9, v = "narrator", n = { x = 41 }, c = { x = { { 0.00, "Судя по зияющей в боку ране, Анилия на грани смерти." } } } } },
    [1022] = { d = 31.2, v = "nightelf-female#52", n = { x = 388 }, c = { x = { { 0.00, "Хотя мы затратили много средств и сил на то, чтобы вытеснить остатки демонов из Осквернённого леса на север, успехи наши невелики." }, { 8.77, "Нам удалось не допустить большую часть демонов в Ясеневый лес." }, { 12.94, "На севере, у границы Осквернённого леса, разрушенное святилище Мел'Тандрис захватили загадочные волколюди." }, { 20.06, "Из-за их пронзительных воплей это место называют теперь Воющей Долиной." }, { 25.02, "Фолиант Мел'Тандрис, что хранится в святилище, может пролить свет на появление там волколюдей." } } }, t = { d = 19.7, v = "nightelf-female#52", n = { x = 238 }, c = { x = { { 0.00, "Фолиант Мел'Тандрис действует странным образом." }, { 3.22, "События, которые он записывает, события, которые он показывает..." }, { 7.60, "Никто толком не понимает, почему он делает то, что делает." }, { 11.55, "Тем не менее, понятно, что предмет, который получила жрица Песнь Звёзд – эта коса Элуны – требует дальнейшего исследования." } } } } },
    [1023] = { d = 20.1, v = "narrator", n = { x = 205 }, c = { x = { { 0.00, "Осматривая вещи Терониса, вы находите дневник, который всё ещё в неплохом состоянии." }, { 6.77, "Вы берёте дневник и оставляете труп Терониса." }, { 10.33, "Остаётся только найти камень, который искал Теронис." }, { 14.63, "Раэна говорила, что он где-то здесь." }, { 17.54, "Возможно, его забрали мурлоки..." } } }, t = { d = 22.6, v = "nightelf-female#52", n = { x = 259 }, c = { x = { { 0.00, "Это ужасно." }, { 0.88, "Теронис мёртв?!" }, { 1.94, "Мы оплачем его, когда придёт пора, но сейчас надо сосредоточить усилия на другом." }, { 7.64, "Я отправлю часовых за телом Терониса как можно скорее." }, { 11.45, "У тебя дневник Терониса и камень, который он искал." }, { 15.08, "Как думаешь – ты сумеешь завершить его дело?" }, { 18.21, "Моя душа успокоится, если я буду знать, что он погиб не напрасно." } } } } },
    [1024] = { d = 34.3, g = 1, v = "nightelf-female#52", n = { m = 423, f = 424 }, c = { m = { { 0.00, "Тебе придётся провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла." }, { 11.27, "Я бы начала поиск от лунного колодца к востоку от озера Ирис." }, { 15.32, "Когда будешь готов, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя." }, { 22.43, "Дриада Шаэлдрин будет тебе лучшим, чем я, проводником." }, { 26.01, "Найди её." }, { 26.66, "Возьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл." } }, f = { { 0.00, "Тебе придётся провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла." }, { 11.47, "Я бы начала поиск от лунного колодца к востоку от озера Ирис." }, { 15.59, "Когда будешь готова, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя." }, { 22.87, "Дриада Шаэлдрин будет тебе лучшим, чем я, проводником." }, { 26.52, "Найди её." }, { 27.17, "Возьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл." } } }, t = { d = 7.8, v = "named/3916", n = { x = 66 }, c = { x = { { 0.00, "О, так тебя послала Раэна?" }, { 2.48, "Тогда это и правда серьёзное дело." }, { 5.69, "Чем я могу тебе помочь?" } } } } },
    [1025] = { d = 32.8, g = 1, v = "nightelf-female#52", n = { m = 396, f = 396 }, c = { m = { { 0.00, "Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе ещё одно поручение, прежде чем ты отправишься к лунному колодцу." }, { 10.36, "На дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников." }, { 17.67, "Их извращённый разум питается страхом, а кровожадность утоляется кровью невинных жертв." }, { 23.46, "Помоги часовым защитить эти края, отплати этим чудовищам их же монетой." }, { 28.40, "Думаю, их лагерь находится к югу от дороги... будь осторожен." } }, f = { { 0.00, "Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе ещё одно поручение, прежде чем ты отправишься к лунному колодцу." }, { 10.49, "На дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников." }, { 17.89, "Их извращённый разум питается страхом, а кровожадность утоляется кровью невинных жертв." }, { 23.75, "Помоги часовым защитить эти края, отплати этим чудовищам их же монетой." }, { 28.75, "Думаю, их лагерь находится к югу от дороги... будь осторожна." } } }, t = { d = 2.6, v = "nightelf-female#52", n = { x = 24 }, c = { x = { { 0.00, "Славная работа." }, { 1.48, "Спасибо тебе." } } } } },
    [1026] = { d = 42.3, v = "named/3916", n = { x = 418 }, c = { x = { { 0.00, "Хотелось бы мне, чтобы у тебя были более хорошие новости." }, { 4.75, "Раэна права, я знаю о творении Дартола и древнях этих краёв – или знала прежде." }, { 11.33, "Они теперь все осквернены, их природа искажена." }, { 15.21, "Если твоя цель – найти ещё один фрагмент жезла, то тебе придётся найти ключ, чтобы отпереть сундук, в котором он лежит." }, { 24.93, "Деревянный ключ – на одном из древней к северу отсюда, близ Осквернённого леса." }, { 31.22, "Как только добудешь его, ищи небольшую лощинку к западу от дороги близ границы Осквернённого леса..." }, { 39.33, "Сундук должен быть спрятан где-то там." } } }, t = { d = 2.6, v = "named/3916", n = { x = 22 }, c = { x = { { 0.00, "Я рада твоему возвращению." } } } } },
    [1027] = { d = 34.0, v = "named/3916", n = { x = 352 }, c = { x = { { 0.00, "Последний фрагмент жезла был отдан на хранение друидам Дор'Данила." }, { 5.12, "Я понятия не имею, где они его спрятали." }, { 8.30, "Сожалею, что больше ничем не могу тебе помочь." }, { 11.96, "Могу только сказать, что тебе следует идти по дороге, что ведёт в Степи." }, { 17.56, "Друиды скрывались к востоку от этой дороги, но они тебе уже не помогут – недавно их перебили... мне не очень хочется об этом думать." }, { 27.79, "Когда найдёшь последний фрагмент, принеси его мне, и я помогу тебе воссоздать жезл." } } }, t = { d = 9.9, g = 1, v = "named/3916", n = { m = 89, f = 89 }, c = { m = { { 0.00, "Ты нашёл последний фрагмент?" }, { 2.46, "Тебе очень повезло..." }, { 4.44, "И Раэне тоже." }, { 5.71, "Как понимаю, нам надо попытаться собрать его, да?" } }, f = { { 0.00, "Ты нашла последний фрагмент?" }, { 2.46, "Тебе очень повезло..." }, { 4.38, "И Раэне тоже." }, { 5.61, "Как понимаю, нам надо попытаться собрать его, да?" } } } } },
    [1028] = { d = 38.4, v = "named/3916", n = { x = 384 }, c = { x = { { 0.00, "Вот собранный жезл." }, { 1.53, "Восстановить его было просто..." }, { 4.15, "Труднее будет найти святилище, в котором жезл можно будет наполнить силой." }, { 10.26, "Но при твоих целеустремлённости и усердии, после всех твоих достижений тебе не слишком трудно будет его найти." }, { 19.13, "Ступай на юго-восток – там очень мало торных дорог, так что будь осторожнее – и посматривай на север." }, { 27.28, "Святилище скрыто в горах, что окружают эту долину." }, { 31.42, "Как только ты окажешься там, положи жезл в святилище... а остальное сделает магия." }, { 37.97, "Хе-хе." } } }, t = { d = 7.2, v = "narrator", n = { x = 71 }, c = { x = { { 0.00, "Когда свечение угасает, вы видите в купели святилища заново наполненный чарами жезл." } } } } },
    [1029] = { d = 9.9, v = "named/3916", n = { x = 93 }, c = { x = { { 0.00, "Советую тебе найти Раэну и сказать ей, что жезл воссоздан." }, { 4.96, "Я уверена, она знает, куда тебе направиться дальше." }, { 9.47, "Удачи." } } }, t = { d = 11.0, g = 1, v = "nightelf-female#52", n = { m = 137, f = 138 }, c = { m = { { 0.00, "Ты собрал жезл, который отправил тебя искать Теронис?" }, { 3.47, "Это приятно слышать." }, { 4.85, "Теронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели." } }, f = { { 0.00, "Ты собрала жезл, который отправил тебя искать Теронис?" }, { 3.61, "Это приятно слышать." }, { 5.03, "Теронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели." } } } } },
    [1030] = { d = 32.6, v = "nightelf-female#52", n = { x = 400 }, c = { x = { { 0.00, "Увы, не могу сказать, что у него было на уме." }, { 3.06, "Если он сказал правду о силе жезла, то тогда ты сможешь принимать тот или иной образ." }, { 8.78, "Какой – не знаю." }, { 9.90, "Может, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным фурболгам, но даже не затронутые порчей существа убили бы его, не будь он осторожен." }, { 21.15, "Дартол, превращённый при помощи жезла, должен был бы поговорить с фурболгом, не подпавшим под порчу Мха Скверны." }, { 28.34, "На мой взгляд, надо начать поиски к юго-востоку от озера Мистраль." } } }, t = { d = 38.8, v = "creature/furbolg", n = { x = 318 }, c = { x = { { 0.58, "Да-да... ты мой сородич, но ты здоровый." }, { 4.01, "Пока ещё чистый." }, { 5.49, "Не знаю, как уж тебе удалось избежать тех злодеяний, что ночные эльфы обрушили на наш народ, но я рад, что больше я не одинок." }, { 16.23, "Нынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами." }, { 25.04, "Это они с нами такое сделали..." }, { 27.92, "Они виноваты в том, что меня изгнали из племени." }, { 32.12, "По ночам я по-прежнему вижу костры в темноте." } } } } },
    [1031] = { d = 26.0, v = "narrator", n = { x = 234 }, c = { x = { { 0.00, "Анилия кладёт руки вам на плечи и привлекает вас к себе." }, { 5.01, "Задыхаясь, она показывает на находящуюся на севере арку, затем глаза её закрываются, и из последних сил она шепчет: \"Он забрал её..." }, { 16.47, "Гелтарис...\" И в душе вы понимаете, что Анилия умирает, жаждая, чтобы Ветвь Кенария была возвращена дриадам." } } }, t = { d = 12.0, v = "named/3901", n = { x = 103 }, c = { x = { { 0.00, "Анилия умерла?" }, { 1.42, "Нет, этого не может быть!" }, { 3.75, "Кажется, только вчера мы вместе бегали и играли в лесах!" }, { 9.08, "Счастливые дни теперь миновали..." } } } } },
    [1032] = { d = 23.3, v = "named/3901", n = { x = 206 }, c = { x = { { 0.00, "Поверить не могу – Анилии нет!" }, { 2.68, "Как часто мы вместе резвились в лесах..." }, { 6.23, "Я почти ощущаю... печаль." }, { 8.52, "Я знаю, от чего мне станет лучше." }, { 11.52, "Пожалуйста, убей сатиров, что отняли у меня Анилию!" }, { 16.10, "Принеси мне их рога в доказательство своего деяния, и я буду навек тебе благодарна." } } }, t = { d = 7.4, g = 1, v = "named/3901", n = { m = 54, f = 54 }, c = { m = { { 0.00, "Спасибо тебе, добрый герой." }, { 2.72, "Душа моей сестры возрадуется твоим деяниям." } }, f = { { 0.00, "Спасибо тебе, добрая героиня." }, { 3.05, "Душа моей сестры возрадуется твоим деяниям." } } } } },
    [1033] = { d = 37.7, v = "nightelf-male#54", n = { x = 415 }, c = { x = { { 0.00, "Я надеялся, что лекарство Орендила спасёт Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери." }, { 9.24, "Мы должны найти более мощное средство!" }, { 12.11, "К счастью, Орендил говорил мне, какие ещё он попытается применить лекарства, если первое не поможет." }, { 19.34, "Слеза Элуны – это такой камень, который можно найти только в одном месте – на острове в озере Ирис к востоку от Астранаара." }, { 28.45, "Орендил сказал, что этот камень снимает порчу... прошу тебя, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!" } } }, t = { d = 10.2, g = 1, v = "nightelf-male#54", n = { m = 76, f = 76 }, c = { m = { { 0.00, "О, ты нашёл её!" }, { 1.46, "Я опущу Слезу в отвар и буду молиться, чтобы он помог ей." }, { 7.41, "Спасибо тебе!" }, { 8.87, "Спасибо тебе!" } }, f = { { 0.00, "О, ты нашла её!" }, { 1.55, "Я опущу Слезу в отвар и буду молиться, чтобы он помог ей." }, { 7.49, "Спасибо тебе!" }, { 8.95, "Спасибо тебе!" } } } } },
    [1034] = { d = 30.4, v = "nightelf-male#54", n = { x = 298 }, c = { x = { { 0.00, "Слеза Элуны немного облегчила страдания моей дочери." }, { 4.43, "Кошмары стали реже её мучить, хвала богине." }, { 8.12, "Но... лихорадка всё ещё сжигает её." }, { 10.92, "Орендил рассказал мне о морозной пыли, которую находят среди руин Звёздной Пыли." }, { 17.56, "Может, она усмирит лихорадку Релары." }, { 20.66, "Собери немного этой пыли, прошу тебя, и принеси её мне." }, { 25.31, "Руины Звёздной Пыли находятся на юге." }, { 28.41, "Да ускорит твой шаг Элуна!" } } }, t = { d = 12.2, g = 1, v = "nightelf-male#54", n = { m = 117, f = 119 }, c = { m = { { 0.00, "Ты принёс пыль!" }, { 1.19, "Я сделаю из неё припарки – они должны унять лихорадку Релары." }, { 6.34, "Ещё раз спасибо тебе." }, { 8.12, "Без твоей помощи моё дитя несомненно умерло бы." } }, f = { { 0.00, "Ты принесла пыль!" }, { 1.42, "Я сделаю из неё припарки – они должны унять лихорадку Релары." }, { 6.57, "Ещё раз спасибо тебе." }, { 8.36, "Без твоей помощи моё дитя несомненно умерло бы." } } } } },
    [1035] = { d = 32.8, g = 1, v = "nightelf-male#54", n = { m = 333, f = 333 }, c = { m = { { 0.00, "Лихорадка Релары прошла, но она ещё очень слаба." }, { 3.90, "Я не верю, что только время вернёт ей былую силу." }, { 7.79, "Мне кажется, тут нужна мощь лунного камня." }, { 11.13, "Мы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники." }, { 19.49, "Их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их." }, { 26.15, "Ты должен отнять лунные камни у Оракула." }, { 29.41, "И, боюсь, для этого тебе придётся его убить." } }, f = { { 0.00, "Лихорадка Релары прошла, но она ещё очень слаба." }, { 3.85, "Я не верю, что только время вернёт ей былую силу." }, { 7.70, "Мне кажется, тут нужна мощь лунного камня." }, { 10.99, "Мы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники." }, { 19.25, "Их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их." }, { 25.83, "Ты должна отнять лунные камни у Оракула." }, { 29.05, "И, боюсь, для этого тебе придётся его убить." } } }, t = { d = 19.5, g = 1, v = "nightelf-male#54", n = { m = 172, f = 175 }, c = { m = { { 0.00, "О, ты спас мою дочь!" }, { 1.75, "Я знаю, что сила лунного камня вернёт моей дочери силы!" }, { 6.74, "Мне никогда не отблагодарить тебя за всё, что ты для меня сделал, но... пожалуйста, возьми вот это." }, { 15.31, "После Релары это самое дорогое, что есть у меня." } }, f = { { 0.00, "О, ты спасла мою дочь!" }, { 1.90, "Я знаю, что сила лунного камня вернёт моей дочери силы!" }, { 6.70, "Мне никогда не отблагодарить тебя за всё, что ты для меня сделала, но... пожалуйста, возьми вот это." }, { 15.01, "После Релары это самое дорогое, что есть у меня." } } } } },
    [1036] = { d = 25.4, v = "human-male", n = { x = 295 }, c = { x = { { 0.00, "Да, я слышал про тебя." }, { 1.54, "Говорят, что ты не друг Пиратской бухте – как и мы, пираты Кровавого Паруса." }, { 6.64, "Командир флота Фираллон ищет здоровых и крепких воинов, чтобы послать их на особое задание." }, { 12.98, "Звучит заманчиво?" }, { 14.21, "Тогда отправляйся на \"Багровый Парус\" и поговори с ним." }, { 17.96, "Он в одной из кают." }, { 19.31, "Корабль на стоянке на Диком берегу к востоку отсюда, рядом с \"Буруном\" и \"Госпожой Удачей\"." } } }, t = { d = 15.9, v = "human-male", n = { x = 160 }, c = { x = { { 0.00, "Суши вёсла, сухопутная крыса." }, { 2.41, "Слыхал я, ты из тех, кто не прочь провернуть тёмное дельце." }, { 7.01, "Что ж, коли ты не друг Пиратской бухте, то у пиратов Кровавого Паруса для тебя найдётся особое местечко." }, { 15.34, "Аррррр..." } } } } },
    [1037] = { d = 34.1, v = "nightelf-female#52", n = { x = 386 }, c = { x = { { 0.00, "Велинда Песнь Звёзд была моей предшественницей здесь, в Ясеневом лесу." }, { 4.92, "Поначалу казалось, что она держит под контролем ситуацию в Осквернённом лесу, но понемногу её усилия стали сходить на нет." }, { 13.49, "И однажды она просто исчезла." }, { 15.67, "Меня послали сюда продолжить её труды." }, { 18.46, "Однако, боюсь, я ничего не знаю об этой жрице." }, { 22.34, "Возможно, Тин'тель Танец Клинка, одна из командиров часовых, знает подробности её исчезновения, о которых не знаю я." }, { 30.84, "Наверняка она поймёт значение такой информации." } } }, t = { d = 13.6, v = "nightelf-female#52", n = { x = 162 }, c = { x = { { 0.00, "Велинда Песнь Звёзд?" }, { 1.39, "То, что эта жрица пропала некоторое время назад, известно всем." }, { 5.86, "Что касается событий, окружавших её исчезновение..." }, { 9.39, "Чтобы поделиться такой информацией, мне нужна веская причина." } } } } },
    [1038] = { d = 29.4, g = 1, v = "nightelf-female#52", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Значит, это ты вычитал в фолианте Мел'Тандрис?" }, { 3.13, "Думаю, ничего страшного не будет, если ты осмотришь её вещи." }, { 7.23, "Этот ключ позволит тебе отпереть сундук, в котором она держала свои пожитки в казарме часовых." }, { 13.80, "Она вела дневник, и если что-то можно узнать, то только из него." }, { 18.25, "Должна тебе сказать, что часовые считают, что у неё была причина уйти, и ждут её возвращения в любой момент." }, { 25.48, "Эта жрица многими своими делами заслужила наше доверие." } }, f = { { 0.00, "Значит, это ты вычитала в фолианте Мел'Тандрис?" }, { 3.21, "Думаю, ничего страшного не будет, если ты осмотришь её вещи." }, { 7.33, "Этот ключ позволит тебе отпереть сундук, в котором она держала свои пожитки в казарме часовых." }, { 13.94, "Она вела дневник, и если что-то можно узнать, то только из него." }, { 18.43, "Должна тебе сказать, что часовые считают, что у неё была причина уйти, и ждут её возвращения в любой момент." }, { 25.70, "Эта жрица многими своими делами заслужила наше доверие." } } }, t = { d = 17.1, g = 1, v = "nightelf-female#52", n = { m = 210, f = 211 }, c = { m = { { 0.00, "Похоже, что исчезновение Велинды – не столь безобидное дело, как казалось поначалу." }, { 5.31, "Но я всё равно не могу поверить, что она плохо кончила." }, { 8.93, "Может, нам лучше будет найти её?" }, { 11.09, "Раз уж ты проявил живой интерес к этому делу, то я была бы рада заручиться твоей поддержкой." } }, f = { { 0.00, "Похоже, что исчезновение Велинды – не столь безобидное дело, как казалось поначалу." }, { 5.34, "Но я всё равно не могу поверить, что она плохо кончила." }, { 8.98, "Может, нам лучше будет найти её?" }, { 11.15, "Раз уж ты проявила живой интерес к этому делу, то я была бы рада заручиться твоей поддержкой." } } } } },
    [1039] = { d = 29.0, v = "nightelf-female#52", n = { x = 362 }, c = { x = { { 0.00, "Кабестан – единственный порт в Степях." }, { 2.47, "Скорее всего, Велинда нашла там торговое судно, которое шло в бухту Черноводья в Азероте." }, { 8.36, "Мы ограничили сделки с гоблинами, которые руководят портом, но смотритель пристани наверняка знает, какие пассажиры взошли на борт, а какие сошли на берег." }, { 18.50, "Следуй по дороге на юго-восток через Ясеневый лес, и попадёшь в Степи." }, { 23.09, "Смотри по сторонам, эти края патрулируют солдаты Орды." }, { 26.74, "Но в порту ты будешь в безопасности." } } }, t = { d = 14.8, v = "goblin-male", n = { x = 167 }, c = { x = { { 0.00, "Вот как?" }, { 0.58, "Должен сказать, твоих сородичей тут у нас нечасто увидишь." }, { 4.79, "Кого-то ищешь, да?" }, { 6.15, "Минуточку, сейчас гляну в своих учётных списках." }, { 9.64, "Через порт проходит куча народу, так что подожди минутку, сделай милость." } } } } },
    [1040] = { d = 34.8, v = "goblin-male", n = { x = 401 }, c = { x = { { 0.00, "А, наконец-то, нашёл." }, { 1.46, "Надо было сразу сказать, что она проезжала здесь давно." }, { 5.44, "Посмотрим." }, { 6.20, "Велинда." }, { 6.84, "Оплатила проезд до Пиратской бухты на \"Чёрной Скопе\"." }, { 10.57, "Никаких дополнительных пометок нет – значит, она благополучно добралась до места назначения." }, { 17.03, "Больше ничем я помочь не могу, хотя она спрашивала, какие средства передвижения есть по ту сторону моря, и я упомянул Раззгота, водящего караваны из Пиратской бухты." }, { 28.68, "Быть может, Велинда отправилась с ним." }, { 31.34, "Ну всё, давай, иди." }, { 32.73, "Не весь же день с тобой болтать." } } }, t = { d = 12.2, g = 1, v = "goblin-male", n = { m = 139, f = 141 }, c = { m = { { 0.00, "Да?" }, { 0.25, "Не похоже, чтобы ты хотел отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратился." }, { 11.61, "Я угадал?" } }, f = { { 0.00, "Да?" }, { 0.25, "Не похоже, чтобы ты хотела отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратилась." }, { 11.62, "Я угадал?" } } } } },
    [1041] = { d = 32.1, v = "goblin-male", n = { x = 351 }, c = { x = { { 0.00, "Оказывается, я ошибался насчёт тебя, а я это не часто признаю." }, { 4.63, "Оказывается, я помню эту Велинду." }, { 7.18, "Не каждый день жрица ночных эльфов желает отправиться в путь со старым грязным – но превосходным для транспортировки товаров – караваном вроде моего." }, { 18.19, "По пути на север мы разделились, и она направилась в Темнолесье." }, { 22.96, "Тамошний клерк ведёт записи." }, { 25.04, "Может, он знает что полезное." }, { 27.26, "Осторожнее в джунглях, они даже в лучшие времена – опасное место." } } }, t = { d = 17.5, v = "human-male", n = { x = 189 }, c = { x = { { 0.00, "В последние годы случилось много странного, и я стараюсь вести записи про всех чужаков." }, { 6.49, "Никогда не узнаешь, что пригодится..." }, { 9.23, "Хотя когда эти записи оказываются нужны, добра не жди..." }, { 13.52, "Нет, про вашу Велинду я не хочу сказать ничего дурного." } } } } },
    [1042] = { d = 30.6, v = "human-male", n = { x = 342 }, c = { x = { { 0.00, "Нет, у меня не сохранилось записей о пребывании Велинды Песни Звёзд в Темнолесье..." }, { 5.85, "Хотя, прошу прощения за прямоту, не могу представить, чтобы жрица ночных эльфов снимала комнату в гостинице, если ты понимаешь, о чём я." }, { 15.62, "А вот о волко-людях я слышал, и не раз." }, { 18.38, "Только недавно Калор явился в город, неся целую связку их голов." }, { 23.14, "Он работает на Кэрвинов." }, { 24.87, "Они охотятся на демонов и прочих чудовищ." }, { 27.89, "Поговори с Джонатаном, он глава их дома." } } }, t = { d = 20.8, v = "human-male#50", n = { x = 218 }, c = { x = { { 0.00, "Тёмные настали времена." }, { 1.83, "Каждая ветвь в лесу нашёптывает дурные вести, зло таится под каждым камнем." }, { 7.69, "И в такую пору незнакомец приходит в мой дом и задаёт вопросы про воргенов..." }, { 13.61, "Прощения за свои подозрения я просить не буду, зато потребую ответить на них." }, { 19.68, "И получу ответ." } } } } },
    [1043] = { d = 30.3, g = 1, v = "human-male#50", n = { m = 357, f = 358 }, c = { m = { { 0.00, "Кажется, ты говоришь правду..." }, { 2.08, "Я не до конца понимаю твои мотивы, но если ты готов избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться." }, { 11.31, "Важен результат." }, { 12.47, "Воргены захватили рудник на юге." }, { 14.73, "Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника." }, { 20.73, "Ступай по своим делам, но если найдёшь что-нибудь важное, расскажи об этом мне." }, { 26.11, "Мы готовы принять любую помощь в нашей войне с силами зла." } }, f = { { 0.00, "Кажется, ты говоришь правду..." }, { 2.10, "Я не до конца понимаю твои мотивы, но если ты готова избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться." }, { 11.47, "Важен результат." }, { 12.64, "Воргены захватили рудник на юге." }, { 14.92, "Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника." }, { 20.97, "Ступай по своим делам, но если найдёшь что-нибудь важное, расскажи об этом мне." }, { 26.39, "Мы готовы принять любую помощь в нашей войне с силами зла." } } }, t = { d = 18.8, g = 1, v = "human-male#50", n = { x = 231 }, c = { m = { { 0.00, "Интересные вещи ты рассказываешь, герой." }, { 2.64, "Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить её раз и навсегда, мы делаем всё, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу." }, { 14.89, "Я уже велел Калору уделить этому первоочередное внимание." } }, f = { { 0.00, "Интересные вещи ты рассказываешь, героиня." }, { 2.77, "Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить её раз и навсегда, мы делаем всё, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу." }, { 15.10, "Я уже велел Калору уделить этому первоочередное внимание." } } } } },
    [1044] = { d = 21.3, g = 1, v = "human-male#50", n = { m = 243, f = 244 }, c = { m = { { 0.00, "Мы разберёмся с воргенами, не беспокойся." }, { 2.83, "Искореним зло, которое твоя подруга невольно принесла в наши леса." }, { 7.66, "Мы не в обиде на неё." }, { 9.14, "Странные вещи творятся в наши времена, и тьма не ведает пощады." }, { 13.70, "Не буду тебя задерживать." }, { 15.57, "Уверен, многие захотят узнать о том, что ты обнаружил в рудниках Сумеречного леса." } }, f = { { 0.00, "Мы разберёмся с воргенами, не беспокойся." }, { 2.82, "Искореним зло, которое твоя подруга невольно принесла в наши леса." }, { 7.63, "Мы не в обиде на неё." }, { 9.11, "Странные вещи творятся в наши времена, и тьма не ведает пощады." }, { 13.66, "Не буду тебя задерживать." }, { 15.52, "Уверен, многие захотят узнать о том, что ты обнаружила в рудниках Сумеречного леса." } } }, t = { d = 22.2, v = "nightelf-female#52", n = { x = 271 }, c = { x = { { 0.00, "Так вот какова судьба Велинды?" }, { 2.06, "Верховная жрица огорчится, услышав об этом – они очень дружили до исчезновения Велинды." }, { 7.98, "И всё же Коса Элуны несомненно была дарована Велинде нашей богиней, и очень плохо, что этот священный предмет попал в недобрые руки." }, { 17.00, "Впрочем, это отдельный разговор." }, { 19.24, "Я премного благодарна тебе за твои достижения." } } } } },
    [1045] = { d = 44.7, v = "creature/furbolg", n = { x = 380 }, c = { x = { { 0.56, "Ночные эльфы стары, как время, но их надменность разрушает их собственный мир." }, { 7.28, "А теперь ещё и наши жизни." }, { 9.62, "Но это уже никак не получится контролировать..." }, { 13.75, "Я много в чём могу обвинять эльфов, но мы всё равно отвечаем за свои деяния." }, { 20.39, "Даже не подвергнувшись порче, мы способны творить великое зло." }, { 25.77, "Рэн Кровавый Клык – такое зло." }, { 28.35, "Жаждущий мощи, алчный... порча только сделала его сильнее." }, { 33.58, "Меня сжигает ненависть к эльфам, но я не хочу зла их детям, так что мы сами должны обуздать своих." } } }, t = { d = 26.4, v = "creature/furbolg", n = { x = 232 }, c = { x = { { 0.56, "Хорошая работа." }, { 1.88, "Лес всё ещё осквернён, но мы по крайней мере знаем, что сделали хоть немного для того, чтобы вернуть его прежнюю красоту." }, { 11.61, "Если пожелаешь снова вернуться ко мне, я буду рад обществу сородича." }, { 17.17, "Удачи тебе." }, { 18.20, "Возможно, наши племена снова встретятся в не столь жестокие времена." } } } } },
    [1046] = { d = 11.6, v = "creature/furbolg", n = { x = 77 }, c = { x = { { 0.43, "Возвращайся в своё племя и поведай им о нашей победе." }, { 5.50, "Покажи им свой трофей и насладись славой..." } } }, t = { d = 25.8, v = "nightelf-female#52", n = { x = 288 }, c = { x = { { 0.00, "Значит, вот он – череп самого лютого фурболга в Ясеневом лесу?" }, { 4.54, "Я более чем довольна твоими способностями." }, { 7.59, "Не знаю даже, как часовым отблагодарить тебя." }, { 10.90, "Надеюсь, в будущем мы снова сможем положиться на тебя, чтобы помочь нашему народу." }, { 16.94, "Я положу этот череп и жезл Дартола на почётное место, чтобы все их увидели." }, { 22.32, "Теронис гордился бы тобой." }, { 24.27, "Ещё раз спасибо тебе." } } } } },
    [1047] = { d = 32.2, v = "nightelf-female#53", n = { x = 388 }, c = { x = { { 0.00, "Внимание, герои!" }, { 1.23, "Круг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора – запретных диких краёв, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска!" }, { 15.44, "Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!" }, { 21.51, "Все заинтересованные лица да обращаются в Круг Кенария!" }, { 25.39, "За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнассе!" } } }, t = { d = 29.0, g = 1, v = "named/3516", n = { m = 332, f = 333 }, c = { m = { { 0.00, "С чего ты решил, что я буду утруждать себя беседой с таким, как ты, герой?" }, { 5.09, "Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу!" }, { 11.23, "Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идёт с важностью поиска этой пустяковины для твоей коллекции!" }, { 20.01, "Сначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я ещё и это сносить должен?" } }, f = { { 0.00, "С чего ты решила, что я буду утруждать себя беседой с таким, как ты, героиня?" }, { 5.35, "Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу!" }, { 11.57, "Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идёт с важностью поиска этой пустяковины для твоей коллекции!" }, { 20.46, "Сначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я ещё и это сносить должен?" } } } } },
    [1048] = { d = 27.0, g = 1, v = "named/2425", n = { x = 280 }, c = { m = { { 0.00, "Хотя Тёмную Госпожу больше всего тревожит продвижение Короля-лича на север, моё дело – заботиться о более насущных проблемах." }, { 10.01, "И главная из них – человечишки, зовущие себя Алым орденом." }, { 14.66, "Тирисфальские луга кишмя кишат маленькими алыми муравьишками." }, { 19.60, "Отправляйся в монастырь, герой, и избавь нас от Верховного инквизитора Вайтмейн и её подчинённых." } }, f = { { 0.00, "Хотя Тёмную Госпожу больше всего тревожит продвижение Короля-лича на север, моё дело – заботиться о более насущных проблемах." }, { 9.87, "И главная из них – человечишки, зовущие себя Алым орденом." }, { 14.46, "Тирисфальские луга кишмя кишат маленькими алыми муравьишками." }, { 19.32, "Отправляйся в монастырь, героиня, и избавь нас от Верховного инквизитора Вайтмейн и её подчинённых." } } }, t = { d = 12.5, g = 1, v = "named/2425", n = { m = 113, f = 114 }, c = { m = { { 0.00, "Ты сослужил Тёмной Госпоже отличную службу, герой." }, { 4.39, "Это задание было не из лёгких." }, { 7.06, "Я не забуду о твоей преданности Отрёкшимся и стойкости в битве." } }, f = { { 0.00, "Ты сослужила Тёмной Госпоже отличную службу, героиня." }, { 4.60, "Это задание было не из лёгких." }, { 7.26, "Я не забуду о твоей преданности Отрёкшимся и стойкости в битве." } } } } },
    [1049] = { d = 40.8, v = "tauren-male#68", n = { x = 430 }, c = { x = { { 0.00, "Намерения Служителей Земли относительно наших поражённых болезнью братьев чисты." }, { 6.42, "Но кому ведомы замыслы тех, кто нашёптывает всякое Совету Старейшин?" }, { 11.82, "У Отрёкшихся, с которыми мы ныне в союзе, вся история полна лжи." }, { 16.87, "Слишком мы поторопились с союзом." }, { 19.54, "Пожалуй, Кэрну стоило прислушаться к предупреждениям из Оргриммара." }, { 24.87, "В недрах Монастыря Алого ордена находится \"Компендиум павших\", который стерегут безумные фанатики-люди." }, { 33.24, "В том, что они творят, сквозит безумие, однако их исследования могут оказаться для нас полезными." } } }, t = { d = 14.2, g = 1, v = "tauren-male#68", n = { m = 137, f = 138 }, c = { m = { { 0.00, "\"Компендиум павших\"!" }, { 1.78, "А я уж начал было сомневаться в том, что он вообще существует!" }, { 7.04, "Ты сослужил добрую службу тауренам Громового Утёса." }, { 11.46, "Твоя преданность не будет забыта." } }, f = { { 0.00, "\"Компендиум павших\"!" }, { 1.76, "А я уж начал было сомневаться в том, что он вообще существует!" }, { 6.97, "Ты сослужила добрую службу тауренам Громового Утёса." }, { 11.41, "Твоя преданность не будет забыта." } } } } },
    [1050] = { d = 34.2, v = "dwarf-female#34", n = { x = 373 }, c = { x = { { 0.00, "Будущее неотвратимо!" }, { 1.56, "Мы стремимся к нему подобно тому, как дождевые капли стремятся к Великому морю." }, { 7.61, "Но, изучая прошедшее, мы узнаём, что ждёт нас в грядущем, и готовимся к встрече с неведомым." }, { 14.33, "Прежде чем великие беды обрушились на Лордерон, в Тирисфальских лесах находился оплот знаний." }, { 21.40, "Ходят слухи, что в библиотеке старого монастыря хранится книга под названием \"Мифология Титанов\"." }, { 28.74, "Принеси её мне – и, возможно, вместе мы сможем заглянуть в тайны прошлого!" } } }, t = { d = 18.5, g = 1, v = "dwarf-female#34", n = { m = 176, f = 178 }, c = { m = { { 0.00, "Ты спас священный текст!" }, { 2.00, "Твоё путешествие было долгим, а уж добыть такую книгу было несомненно трудно." }, { 8.69, "Но дворфы Стальгорна от твоего успеха получат огромную выгоду." }, { 14.08, "Спасибо тебе, от лица всей Лиги Исследователей." } }, f = { { 0.00, "Ты спасла священный текст!" }, { 2.26, "Твоё путешествие было долгим, а уж добыть такую книгу было несомненно трудно." }, { 9.05, "Но дворфы Стальгорна от твоего успеха получат огромную выгоду." }, { 14.50, "Спасибо тебе, от лица всей Лиги Исследователей." } } } } },
    [1051] = { d = 56.1, g = 1, v = "scourge-male", n = { m = 456, f = 459 }, c = { m = { { 0.00, "Моя воля свободна, и всё же я не могу более служить Тёмной Госпоже." }, { 6.51, "Я чувствую, что время, отпущенное мне в Азероте, подходит к концу." }, { 12.84, "Жизненные силы покидают меня." }, { 15.79, "Дознаватель Вишас всему виной!" }, { 18.82, "Он пытал меня много недель!" }, { 21.60, "Мало того, он отобрал у меня обручальное кольцо и нацепил его на палец своей жене!" }, { 29.76, "Чудовище!" }, { 30.71, "Я жажду мести!" }, { 32.18, "Этот глупец похвалялся своей прекрасной женой Нэнси, что живёт у озера Лордамер." }, { 40.61, "Я хочу, чтобы ты отыскал её и вытряс из неё душу вместе с моим кольцом!" }, { 47.55, "Верни кольцо моей жене Монике, она живёт в Мельнице Таррен." }, { 53.45, "Исполни мою последнюю волю." } }, f = { { 0.00, "Моя воля свободна, и всё же я не могу более служить Тёмной Госпоже." }, { 6.29, "Я чувствую, что время, отпущенное мне в Азероте, подходит к концу." }, { 12.41, "Жизненные силы покидают меня." }, { 15.26, "Дознаватель Вишас всему виной!" }, { 18.20, "Он пытал меня много недель!" }, { 20.88, "Мало того, он отобрал у меня обручальное кольцо и нацепил его на палец своей жене!" }, { 28.76, "Чудовище!" }, { 29.69, "Я жажду мести!" }, { 31.11, "Этот глупец похвалялся своей прекрасной женой Нэнси, что живёт у озера Лордамер." }, { 39.38, "Я хочу, чтобы ты отыскала её и вытрясла из неё душу вместе с моим кольцом!" }, { 46.34, "Верни кольцо моей жене Монике, она живёт в Мельнице Таррен." }, { 52.04, "Исполни мою последнюю волю." } } }, t = { d = 24.6, v = "scourge-female", n = { x = 201 }, c = { x = { { 0.00, "Нелёгкой была участь Воррела..." }, { 3.08, "А каким добрым супругом он мне был..." }, { 6.69, "Будь прокляты эти мерзкие люди!" }, { 9.85, "Никогда нам более не быть вместе." }, { 13.11, "По крайней мере, я найду утешение в свершённой тобой мести." }, { 18.91, "Благодарю тебя." }, { 20.50, "А теперь оставь меня наедине с моим горем." } } } } },
    [1052] = { d = 30.6, v = "human-male", n = { x = 365 }, c = { x = { { 0.00, "Мы, рыцари Алого ордена, заявляем свои права на укрепления от Дольного Очага до Тирисфальских лесов." }, { 7.17, "Мы гордимся нашей борьбой за чистоту Лордерона!" }, { 10.56, "Вы подтвердили свою репутацию, сражаясь против нежити в Пустошах." }, { 15.23, "Но настоящая угроза исходит из Лордерона." }, { 18.18, "Отправляйтесь в Восточные королевства, в город Южнобережье." }, { 22.34, "Отнесите письмо с моими рекомендациями и печатью рыцарю Ролею Благочестивому." }, { 27.84, "Он проводит вас в Монастырь Алого ордена." } } }, t = { d = 5.2, v = "human-male#50", n = { x = 48 }, c = { x = { { 0.00, "Брат Антон по-прежнему проповедует идеи Алого ордена?" }, { 4.66, "О-ох..." } } } } },
    [1053] = { d = 35.4, v = "human-male#50", n = { x = 400 }, c = { x = { { 0.00, "Я всегда служил Алому ордену, гордился им и почитал служение за честь." }, { 5.15, "Мне было чем гордиться, ведь мы спасали Азерот от нежити." }, { 9.31, "Но после некоторого времени, проведённого в монастыре Тирисфальских лесов, я понял, что не ведал об истинных намерениях высшей иерархии ордена." }, { 19.67, "Каждого, кто не принадлежит к ордену, они считают зачумлёнными." }, { 24.23, "Невинных мужчин и женщин подвергают пыткам, полагая их нечистыми." }, { 29.05, "Во имя Света, Алый орден должен быть сокрушён." }, { 32.48, "И вам, по силам покончить с этим безумием." } } }, t = { d = 17.1, g = 1, v = "human-male#50", n = { x = 194 }, c = { m = { { 0.00, "Хотя путь Света не приемлет убийств и кровопролитий, но в подобных случаях кровавая жертва служит благу королевства и всего мира." }, { 9.38, "Ваши деяния в монастыре помогли спасти множество невинных жизней." }, { 14.20, "Путник, я восхищаюсь вашей решительностью." } }, f = { { 0.00, "Хотя путь Света не приемлет убийств и кровопролитий, но в подобных случаях кровавая жертва служит благу королевства и всего мира." }, { 9.17, "Ваши деяния в монастыре помогли спасти множество невинных жизней." }, { 13.89, "Путница, я восхищаюсь вашей решительностью." } } } } },
    [1054] = { d = 28.6, v = "nightelf-female#52", n = { x = 346 }, c = { x = { { 0.00, "Прямо к северу от Астранаара живут фурболги Колючего Меха." }, { 4.02, "Мои разведчики доносят, что в последние несколько месяцев они чрезвычайно умножились числом." }, { 10.31, "Если они слишком расплодятся, то могут набраться наглости напасть на Астранаар!" }, { 15.73, "Убей их, сколько сможешь, главное – принеси мне череп их предводителя в знак того, что их усилия напрасны... пока." }, { 23.42, "Я останусь в Астранааре и буду ждать вестей от тебя." }, { 26.95, "Да пребудет с тобой Элуна." } } }, t = { d = 7.8, v = "nightelf-female#52", n = { x = 91 }, c = { x = { { 0.00, "Славная работа." }, { 1.13, "Эти фурболги постоянно угрожают нам." }, { 3.69, "По счастью, теперь они некоторое время будут сидеть тихо." } } } } },
    [1055] = { d = 6.3, v = "narrator", n = { x = 62 }, c = { x = { { 0.00, "Воссозданный жезл у вас в руках." }, { 2.73, "Шаэлдрин захочет услышать о ваших успехах." } } }, t = { d = 3.5, v = "named/3916", n = { x = 26 }, c = { x = { { 0.00, "У тебя получилось!" }, { 2.22, "Великолепно!" } } } } },
    [1056] = { d = 36.3, g = 1, v = "nightelf-male#54", n = { m = 359, f = 359 }, c = { m = { { 0.00, "Лесные духи говорят мне, что ты отважен и лёгок на подъём." }, { 4.57, "На юге, неподалёку от озера Мистраль, находится туннель, именуемый Туннель Когтя." }, { 11.10, "Через этот туннель ты попадёшь в место, называемое Утёс Ветрорезов, в Когтистых горах." }, { 18.00, "Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберёшься до Пика Каменного Когтя." }, { 29.25, "Там ждёт хранитель Албагорм." }, { 31.50, "Выслушай его просьбу, герой." }, { 33.90, "Путешествие будет опасным." } }, f = { { 0.00, "Лесные духи говорят мне, что ты отважна и легка на подъём." }, { 4.67, "На юге, неподалёку от озера Мистраль, находится туннель, именуемый Туннель Когтя." }, { 11.23, "Через этот туннель ты попадёшь в место, называемое Утёс Ветрорезов, в Когтистых горах." }, { 18.16, "Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберёшься до Пика Каменного Когтя." }, { 29.47, "Там ждёт хранитель Албагорм." }, { 31.73, "Выслушай его просьбу, героиня." }, { 34.28, "Путешествие будет опасным." } } }, t = { d = 6.1, v = "creature/keeper", n = { x = 44 }, c = { x = { { 0.00, "Наконец-то!" }, { 1.29, "Вижу, Фальдреас прислушался к духам лесов..." } } } } },
    [1057] = { d = 41.8, v = "creature/keeper", n = { x = 432 }, c = { x = { { 0.00, "Несомненно, будучи защитником лесных духов, можешь догадаться, почему я так встревожен." }, { 7.06, "Чтобы достигнуть этого пика, тебе пришлось пройти через горы, и, конечно же, от глаз твоих не ускользнуло искажение, постигшее эту землю." }, { 18.26, "Алчность привела к уничтожению священных холмов." }, { 22.19, "Обугленная долина на юге сожжена механической армией жадных промышленников." }, { 28.31, "Хуже того, клан Смертельной Ярости, вторгшийся на эти земли, отказывается пропустить нас – а ведь мы могли бы начать восстановление тех краёв!" }, { 39.58, "Изгони прочь злобных гарпий!" } } }, t = { d = 10.6, v = "creature/keeper", n = { x = 107 }, c = { x = { { 0.00, "Теперь, когда клан Смертельной Ярости понёс большие потери, вероятно, и начнётся истинная работа по восстановлению этих земель..." } } } } },
    [1058] = { d = 44.4, v = "troll-male", n = { x = 429 }, c = { x = { { 0.00, "Я в восхищении!" }, { 1.29, "Три маленьких клетки для трёх маленьких эльфов." }, { 5.24, "Ну-с, что бы нам сделать с нашими дорогими друзьями-древолюбами?" }, { 10.55, "Что ж, дадим им попробовать... как бы это они сказали... лесной магии!" }, { 16.47, "Мне нужна добрая порция слизи Каменного Когтя." }, { 20.49, "Принеси мне несколько сумеречных усиков этих ужасных кошек." }, { 25.58, "И конечно же, потребуется множество глаз бегового оленя – глаз всегда не хватает!" }, { 32.34, "Да, и ещё, последнее, чуть не забыл: драгоценную чешуйку волшебного дракончика." }, { 38.86, "Живо в Каменный Коготь, чтобы я мог сварить немножко лесной магии!" } } }, t = { d = 11.2, v = "troll-male", n = { x = 104 }, c = { x = { { 0.00, "О, как счастливы будут эти маленькие лесные нимфы!" }, { 4.59, "Мы заставим их почувствовать себя как дома при помощи этого особого отвара!" } } } } },
    [1059] = { d = 41.9, v = "creature/keeper", n = { x = 433 }, c = { x = { { 0.00, "Мы одержали победу над кланом Смертельной Ярости." }, { 3.97, "Но они скоро соберут силы и вернутся, если не предпринять решительные действия." }, { 10.39, "Далеко на юге Степей находится земля, известная как Тысяча Игл." }, { 15.52, "Если идти на запад Тысячи Игл до тех пор, пока не достигнешь границ густого леса Фералас, то встретишь друида по имени Фалфиндер Хранитель Дорог." }, { 27.21, "Этот сильный и мудрый друид способен призвать великих лесных духов, которые помогут в восстановлении Обугленной долины." }, { 36.88, "Поведай ему о нашей беде!" }, { 39.04, "Отправляйся на его поиски немедленно!" } } }, t = { d = 14.3, v = "nightelf-male#54", n = { x = 165 }, c = { x = { { 0.00, "Хранитель Албагорм поступил мудро, прислав тебя со срочным известием." }, { 5.08, "Будем надеяться, что мы успеем призвать помощь, и что эта помощь из великого леса прибудет в Обугленную долину не слишком поздно." } } } } },
    [1060] = { d = 32.0, g = 1, v = "orc-male", n = { m = 312, f = 313 }, c = { m = { { 0.00, "Ты сделал мне много добра." }, { 2.21, "Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что ещё." }, { 8.26, "Гарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе." }, { 16.67, "Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин'Зилу." }, { 24.12, "Он будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится." }, { 30.83, "Занятное место." } }, f = { { 0.00, "Ты сделала мне много добра." }, { 2.24, "Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что ещё." }, { 8.17, "Гарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе." }, { 16.41, "Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин'Зилу." }, { 23.71, "Он будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится." }, { 30.29, "Занятное место." } } }, t = { d = 20.7, v = "troll-male", n = { x = 192 }, c = { x = { { 0.00, "А, письмо от Дарсока." }, { 1.84, "Давно от него не было вестей." }, { 4.45, "Значит, последняя из Кровавых Перьев мертва?" }, { 8.29, "Отличные вести." }, { 9.67, "Я хорошо помню, как мой друг Рохан пошёл убивать её старшую сестру с этим психом из Мок'Натала." }, { 17.73, "Да, тогда я был молод, как ты сейчас." } } } } },
    [1061] = { d = 35.7, v = "orc-male", n = { x = 361 }, c = { x = { { 0.00, "Духи Когтистых гор разгневаны: гоблины и их приспешники разоряют и выжигают земли." }, { 6.64, "Земля возопила, и те, кто способен слышать – услышали." }, { 11.02, "В Когтистые горы отправилась Сирит Камнеломм, многообещающий шаман Орды." }, { 16.93, "Она сообщает, что гоблины вырубили много леса, и просит о помощи." }, { 22.33, "Отправляйся в Когтистые горы, найди там Сирит." }, { 26.13, "Чтобы туда добраться, ступай от Перекрёстка в Степях по дороге на запад." }, { 31.97, "Сирит стоит лагерем близ Долины Высокого леса." } } }, t = { d = 7.9, g = 1, v = "orc-female", n = { x = 66 }, c = { m = { { 0.00, "А, герой!" }, { 0.87, "Очень кстати." }, { 2.14, "Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!" } }, f = { { 0.00, "А, героиня!" }, { 1.04, "Очень кстати." }, { 2.32, "Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!" } } } } },
    [1062] = { d = 37.7, v = "orc-female", n = { x = 393 }, c = { x = { { 0.00, "Торговая Компания, которой управляют гоблины, вторглась в Когтистые горы." }, { 5.77, "Они валят деревья, выжигают большие участки леса." }, { 9.77, "Духи этих земель вне себя от боли и ярости." }, { 13.29, "Мы должны остановить Торговую Компанию!" }, { 16.38, "Отправляйся на северо-запад, за Долину Высокого леса, к Утёсу Ветрорезов." }, { 22.08, "Ты найдёшь гоблинов и их прислужников за работой – покажи же им, что Орда не позволит разорять Когтистые горы." }, { 30.52, "Поговори с ними на том языке, который они лучше всего понимают..." }, { 35.72, "На языке беспощадной силы!" } } }, t = { d = 17.8, v = "orc-female", n = { x = 188 }, c = { x = { { 0.00, "Это подлинно отважное деяние." }, { 2.43, "Вероятно, в конце концов нам понадобится мудрость тауренских старейшин, чтобы успокоить духов Каменного Когтя, но..." }, { 11.63, "Первый шаг в верном направлении сделан – Торговая Компания лишилась работников." } } } } },
    [1063] = { d = 37.7, v = "orc-female", n = { x = 414 }, c = { x = { { 0.00, "Чтобы узнать, как окончательно успокоить духов Когтистых гор, нам нужно посоветоваться со старейшинами тауренов." }, { 8.28, "Я мало знаю о том, кто предводительствует тауренами, но одно имя мне известно: Магата." }, { 14.67, "Я слышала, что она очень стара и много знает." }, { 18.17, "Если кто из тауренов и может оказать нам помощь касательно духов, то это она." }, { 24.03, "Магата живёт в главном городе тауренов Громовом Утёсе, на Вершине Старейшин – это северо-восточная вершина города." }, { 32.58, "Поговори с Магатой и расскажи ей о том, что творится в Когтистых горах." } } }, t = { d = 3.8, v = "named/4046", n = { x = 29 }, c = { x = { { 0.00, "Я приветствую тебя." }, { 2.16, "Ты ищешь совета?" } } } } },
    [1064] = { d = 37.4, v = "named/4046", n = { x = 390 }, c = { x = { { 0.00, "Таурены в сродстве с этой землёй, и мне больно слышать о том, что творится в Каменном Когте." }, { 7.14, "Но я боюсь, что для исцеления этой земли нам прежде придётся справиться с той заразой, что терзает нас самих." }, { 15.55, "Разве не удача, что Отрёкшиеся теперь с нами?" }, { 19.08, "Они много знают о заразных болезнях." }, { 22.05, "Я уверена, что они смогут помочь нам и тем укрепят доверие между нашими народами." }, { 28.48, "Поговори с аптекаршей Замой." }, { 30.74, "Она – учёная и представитель Отрёкшихся." }, { 33.78, "Ты найдёшь её у Прудов Видений под Уступом Духов." } } }, t = { d = 14.6, v = "scourge-female", n = { x = 138 }, c = { x = { { 0.00, "Магата прислала о тебе весточку." }, { 2.88, "Хотя сердце моё уже и не бьётся, оно всё же разрывается от горя по духам Каменного Когтя." }, { 10.59, "Отрёкшиеся готовы помочь всем, чем только можно." } } } } },
    [1065] = { d = 48.4, v = "scourge-female", n = { x = 464 }, c = { x = { { 0.00, "Нам придётся прибегнуть к чрезвычайным мерам, чтобы избавить Каменный Коготь от Торговой Компании." }, { 8.27, "Но только без кровопролития." }, { 10.65, "У одного моего коллеги может найтись то, что нам как раз для этого случая и нужно." }, { 17.62, "Его зовут Лидон, он живёт в городе Мельница Таррен в предгорьях Хилсбрада, в далёком краю Лордерон." }, { 26.04, "Чтобы добраться до Хилсбрада, отправляйся на дирижабле в нашу столицу, Подгород." }, { 32.86, "Оттуда иди на север, в Тирисфальские леса, затем на юго-запад, в Серебряный бор, и дальше на юг, в Хилсбрад." }, { 41.97, "Найди Лидона и передай ему эту записку." }, { 45.49, "Там написано, что нам от него нужно." } } }, t = { d = 12.7, v = "scourge-male", n = { x = 90 }, c = { x = { { 0.00, "Записка от Замы?" }, { 1.90, "Наверняка её сильно прижало, раз пишет в такую даль." }, { 7.70, "Посмотрим..." }, { 9.10, "Замечательно!" }, { 10.60, "Я знаю, что ей надо!" } } } } },
    [1066] = { d = 41.4, v = "scourge-male", n = { x = 347 }, c = { x = { { 0.00, "Я создам яд, который остудит пыл Торговой Компании." }, { 5.02, "Они станут слабыми и покорными." }, { 8.18, "Это же решит проблемы Орды в Каменном Когте, да?" }, { 13.02, "Но для создания отравы мне понадобится кровь невинных, а её нелегко найти." }, { 20.15, "К счастью, Синдикат, группа грабителей, насчитывает в своих рядах несколько тёмных магов... а они собирают кровь невинных для своих нечистых целей." }, { 34.49, "Тёмных магов Синдиката можно найти в крепости Дарнхольд на юго-востоке." } } }, t = { d = 18.3, v = "scourge-male", n = { x = 181 }, c = { x = { { 0.00, "Очень хорошо!" }, { 1.17, "Надеюсь, Синдикат не причинил тебе особых проблем?" }, { 5.33, "Как я и говорил, кровь невинных не так уж легко добыть." }, { 9.71, "Нам повезло, что трудную часть работы взяли на себя маги Синдиката." }, { 15.19, "А теперь подожди, я создам мой состав..." } } } } },
    [1067] = { d = 28.3, v = "scourge-male", n = { x = 281 }, c = { x = { { 0.00, "Вот отрава." }, { 1.00, "Если воспользоваться ей против Торговой Компании, результаты должны оказаться весьма благоприятными – возможно, удастся добиться даже распространения новой заразы." }, { 14.93, "Мне не терпится испытать свою работу в деле!" }, { 18.78, "Впрочем, прежде отнеси её аптекарю Заме." }, { 22.32, "Она должна придумать наиболее эффективный способ использования отравы." } } }, t = { d = 10.6, v = "scourge-female", n = { x = 92 }, c = { x = { { 0.00, "Отрава от аптекаря Лидона?" }, { 2.53, "Замечательно." }, { 3.80, "Если я знаю Лидона, она очень хорошо подействует на Торговую Компанию..." } } } } },
    [1068] = { d = 42.3, v = "orc-female", n = { x = 447 }, c = { x = { { 0.00, "Есть связь между духовной магией шаманов и природной магией друидов." }, { 5.30, "Именно поэтому мы, шаманы, можем слышать мольбы духов Каменного Когтя." }, { 10.88, "Я могу разобрать не всё, что они шепчут, однако одно послание - одно видение - было чётким..." }, { 18.13, "В этом видении я узрела на Утёсе Ветрорезов, на северо-западе Долины Высокого леса, две человекоподобные машины, которые валили деревья с невероятной скоростью." }, { 30.47, "Этих металлических тварей нужно остановить!" }, { 33.89, "В явленном мне видении я заметила, что машины эти отмечены странными символами:" }, { 40.03, "Икс-тэ четыре и икс-тэ девять." } } }, t = { d = 22.7, v = "orc-female", n = { x = 238 }, c = { x = { { 0.00, "Уничтожение машин икс-тэ четыре и икс-тэ девять успокоило многих духов Каменного Когтя." }, { 6.95, "Будем надеяться, что после потери этих машин Торговая Компания покинет эти горы." }, { 13.40, "Ибо если этого не произойдёт, то бедствия, постигшие эти земли, могут оказаться бледной тенью того, что ждёт нас впереди." } } } } },
    [1069] = { d = 33.2, v = "goblin-male", n = { x = 349 }, c = { x = { { 0.00, "В Пиратской бухте фантастический спрос на омлеты из паучьих яиц!" }, { 4.90, "Проблема в том... что яиц в Бухте нет." }, { 7.80, "Я чую прибыль!" }, { 8.98, "На Утёсе Ветрорезов и в Сиширском каньоне, в Когтистых горах на северо-западе, живут моховые пауки." }, { 16.57, "Принеси мне их яйца, и я неплохо заплачу!" }, { 19.75, "На Утёсе Ветрорезов паучьи кладки можно найти под оставшимися деревьями." }, { 25.27, "В Сиширском каньоне... хм, если у тебя слабый желудок, можешь собирать яйца только на Утёсе Ветрорезов..." } } }, t = { d = 11.4, g = 1, v = "goblin-male", n = { m = 111, f = 113 }, c = { m = { { 0.00, "Ты принёс мне яйца!" }, { 1.55, "Спасибо!" }, { 2.29, "Я пошлю их Дыбоволосу, и он переправит мой товар в Пиратскую бухту!" }, { 7.75, "Вот твоя доля." }, { 9.00, "Без тебя мне бы не справиться." } }, f = { { 0.00, "Ты принесла мне яйца!" }, { 1.75, "Спасибо!" }, { 2.48, "Я пошлю их Дыбоволосу, и он переправит мой товар в Пиратскую бухту!" }, { 7.87, "Вот твоя доля." }, { 9.11, "Без тебя мне бы не справиться." } } } } },
    [1070] = { d = 31.7, v = "nightelf-female#52", n = { x = 384 }, c = { x = { { 0.00, "Привет тебе." }, { 0.90, "Судя по виду, ты много путешествуешь." }, { 3.44, "Тебе приходилось бывать в Когтистых горах?" }, { 6.33, "Эта земля опустошена Торговой компанией и прочими врагами ночных эльфов." }, { 11.27, "Недавно часовой Волкопас послала туда мою подругу Каэлу Копьё Тени, чтобы она узнала, что происходит в тех землях, однако до сих пор от неё нет вестей." }, { 21.39, "Я ещё беспокоюсь и потому, что Альянс отправил вместе с ней гнома-мага... это, несомненно, повод для тревоги." }, { 28.69, "Может быть, ты найдёшь её и пошлёшь весточку мне?" } } }, t = { d = 15.4, v = "nightelf-female#52", n = { x = 170 }, c = { x = { { 0.00, "А, так ты здесь по просьбе Тары из Ясеневого леса... я так скучаю по ней, по моей родине, по друзьям." }, { 7.14, "Должно быть, ей хорошо среди часовых, раз прочие дела передаёт путникам." }, { 12.34, "Я горжусь за неё." }, { 13.57, "Рада познакомиться с тобой." } } } } },
    [1071] = { d = 36.4, v = "gnome-male", n = { x = 405 }, c = { x = { { 0.00, "Понимаешь ли, я состою в Просвещённой Ассамблее Чародейства, Алхимии и Технических Наук, и моя цель... нет, мой ДОЛГ! – показать ночным эльфам, что единение магии, реактивов и механизмов поможет спасти их леса." }, { 15.16, "Однако это тяжёлая война, а гоблины, похоже, плодятся, словно кролики." }, { 20.39, "У меня даже нет времени воплотить в жизнь свои новые изобретения!" }, { 25.22, "Мне нужно время для планирования и организации." }, { 28.67, "Но для этого мне потребуется твоя помощь – сдерживать натиск гоблинов у Утёса Ветрорезов к востоку отсюда..." } } }, t = { d = 32.6, v = "gnome-male", n = { x = 384 }, c = { x = { { 0.00, "Спасибо тебе за помощь." }, { 1.68, "Да и вернуться тебе удалось как раз вовремя." }, { 4.72, "Кажется, я выработал идеальный план... взрывчатка." }, { 8.13, "Нет, это не сам план, это его часть." }, { 10.61, "Понимаешь ли, я использую сильные взрывчатые вещества – не волнуйся, они далеко не так опасны, как считается – для того, чтобы припугнуть гоблинов." }, { 20.66, "Я смогу как следует нагнать на них страху, разместив в ключевых местах на границах горной местности заряды, однако в ближайшие несколько дней мне может не хватить материалов..." } } } } },
    [1072] = { d = 36.3, v = "gnome-male", n = { x = 432 }, c = { x = { { 0.00, "Устройство, о котором я думаю – моя самая продвинутая версия на сегодняшний день." }, { 5.58, "Но мне нужно особое зелье, чтобы это устройство заработало." }, { 9.74, "Я думаю, нам нужно добыть хороший состав, поскольку эта миссия может стать для тебя последней." }, { 16.31, "А для этого нам нужно мощное взрывчатое вещество: нитромирглицероний." }, { 21.02, "Единственный, кто может создать эн-гэ пять, это мой старый приятель – Ломак Демонтирс." }, { 26.97, "Поищи его в Городе Механиков." }, { 29.08, "Если уговоришь его сделать для нас немного эн-гэ пять, то я начну работать над размещением своих устройств." } } }, t = { d = 7.5, v = "gnome-male", n = { x = 58 }, c = { x = { { 0.00, "А-а-а..." }, { 0.84, "Тебя послал Гаксим, вот как?" }, { 3.51, "А откуда мне знать, что ты не врёшь?" }, { 6.68, "Ась?" }, { 7.10, "Ась?.." } } } } },
    [1073] = { d = 34.1, v = "gnome-male", n = { x = 407 }, c = { x = { { 0.00, "Ха-ха-ха!.." }, { 0.79, "Тебе нужен нитромирглицероний, чтобы остановить гоблинов, уничтожающих лес?!" }, { 5.86, "Мне всё равно, знаешь ты Гаксима или нет... я дам тебе этот состав, чтобы посмотреть, как кого-нибудь разнесёт на мелкие кусочки: или тебя, или гоблинов." }, { 16.14, "Но есть проблемка: у меня кончились химикалии." }, { 19.23, "Но вот что я тебе скажу: принесёшь мне нужные зелья, и я прямо сразу же смешаю для тебя составчик." }, { 25.76, "По крайней мере, ты докажешь, что кое-что понимаешь в алхимии, прежде, чем я передам тебе образец своего величайшего творения." } } }, t = { d = 12.2, v = "gnome-male", n = { x = 117 }, c = { x = { { 0.00, "Вот это подойдёт." }, { 1.38, "Не знай я тебя, я бы сказал, что ты кое-что понимаешь в алхимии..." }, { 6.59, "Ладненько, ладненько... в мире есть не только мечи и колдовство, верно?" } } } } },
    [1074] = { d = 13.1, v = "gnome-male", n = { x = 135 }, c = { x = { { 0.00, "Ну вот тебе, держи." }, { 1.48, "Тока поосторожней... это летучая смесь." }, { 4.44, "Если Гаксим тебе и вправду друг, передай ему от меня привет." }, { 9.09, "А если нет – взлетишь на воздух, вот будет тебе потеха." } } }, t = { d = 16.3, v = "gnome-male", n = { x = 162 }, c = { x = { { 0.00, "Дело сделано, и сделано отлично." }, { 2.70, "Эн-гэ пять незаменимый компонент для поджига повозок с динамитом." }, { 7.94, "Что?" }, { 8.31, "Да, динамит... целыми повозками." }, { 10.93, "Это идеальный отвлекающий манёвр, я тебе скажу... подожди и увидишь." } } } } },
    [1075] = { d = 36.3, g = 1, v = "gnome-male", n = { m = 412, f = 413 }, c = { m = { { 0.00, "Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, ещё не объяснил этого?" }, { 7.62, "Ну так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошёл почти без твоего участия." }, { 15.55, "Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвётся эн-гэ пять." }, { 22.56, "Но мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен." }, { 28.88, "Ты сможешь отыскать его там в квартале магов." }, { 32.04, "Он человек, так что будь внимателен, не ошибись." } }, f = { { 0.00, "Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, ещё не объяснил этого?" }, { 7.87, "Ну так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошёл почти без твоего участия." }, { 16.06, "Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвётся эн-гэ пять." }, { 23.29, "Но мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен." }, { 29.81, "Ты сможешь отыскать его там в квартале магов." }, { 33.07, "Он человек, так что будь внимательна, не ошибись." } } }, t = { d = 7.4, v = "human-male", n = { x = 76 }, c = { x = { { 0.00, "Да, вот то заклинание, которое тебе нужно – оно позволит производить взрывы на расстоянии... хмм." } } } } },
    [1076] = { d = 31.6, v = "human-male", n = { x = 372 }, c = { x = { { 0.00, "А, кажется, я понял." }, { 1.42, "Заклинание послания... полагаю, именно этого эффекта он хочет добиться." }, { 6.38, "Мне нужно создать свиток с запечатлённым на нём заклинанием." }, { 10.41, "Для этого мне нужен прах Пыледемона." }, { 13.24, "Пока я собираю остальные компоненты, почему бы тебе не отправиться в Западный Край и не найти там одно из этих мерзких существ?" }, { 21.98, "Они опасны, но я уверен, что ты со всем справишься, если желаешь участвовать в одном из экспериментов Гаксима." }, { 29.47, "Когда ты вернёшься, я буду здесь." } } }, t = { d = 4.4, v = "human-male", n = { x = 49 }, c = { x = { { 0.00, "Подожди несколько секунд, и нужный тебе свиток будет готов." } } } } },
    [1077] = { d = 11.4, v = "human-male", n = { x = 129 }, c = { x = { { 0.00, "Вот." }, { 0.32, "Это то, что нужно." }, { 1.64, "Когда в следующий раз увидишь Гаксима, передай ему от меня привет." }, { 6.38, "Хотелось бы мне узнать, как закончится эта история." }, { 9.99, "Всего тебе хорошего." } } }, t = { d = 19.4, v = "gnome-male", n = { x = 229 }, c = { x = { { 0.00, "Великолепно!" }, { 0.92, "Славная работа." }, { 2.10, "Это заклинание вместе с эн-гэ пять даст идеальную дистанционную взрывчатку." }, { 7.53, "У нас получится прекрасный отвлекающий манёвр, и ты прокрадешься и сопрёшь документы и инженерные планы Торговой Компании." }, { 16.18, "Тогда они не смогут вырубать леса так быстро." } } } } },
    [1078] = { d = 39.1, v = "human-male", n = { x = 455 }, c = { x = { { 0.00, "Путешественники постоянно спрашивают меня о Когтистых горах." }, { 4.26, "Похоже, все ищут там приключений, причём самых разных: кому-то нужны виверны, кому-то – элементали, а у кого-то дела с Торговой компанией." }, { 13.98, "В Обугленной долине, прячущейся среди пиков Когтистых гор, некогда обитали особые виды василисков: их чешуя, размолотая в порошок, была прекрасным реактивом для некоторых заклинаний, созданных мною." }, { 27.95, "Если эти василиски ещё живут там, мне надо заполучить хотя бы несколько чешуек." }, { 33.61, "Если не очень торопишься, удели на это немного времени, я хорошо заплачу тебе." } } }, t = { d = 6.3, v = "human-male", n = { x = 67 }, c = { x = { { 0.00, "Великолепно." }, { 0.97, "Спасибо тебе огромное." }, { 2.78, "Может быть, и я когда-нибудь смогу помочь тебе." } } } } },
    [1079] = { d = 29.2, v = "gnome-male", n = { x = 348 }, c = { x = { { 0.00, "Так вот, смотри и слушай внимательно." }, { 2.59, "Все устройства доделаны и готовы к использованию." }, { 5.99, "Возьми эти листы – здесь всё объясняется про детонаторы, взрывчатку и про то, как их разместить." }, { 12.56, "Помни, успех твоей миссии не зависит от того, сколько разрушений ты сможешь причинить." }, { 18.68, "План \"Альфа\" увенчается успехом в том случае, если ты принесёшь технические чертежи Торговой компании, находящиеся на лесопилке к югу от Скалистого Озера." } } }, t = { d = 14.0, v = "gnome-male", n = { x = 159 }, c = { x = { { 0.00, "Просто великолепно!" }, { 1.45, "Это сильный удар по Торговой Компании." }, { 4.36, "Мы сможем узнать уязвимые места их машин, а также использовать их разработки для наших собственных целей." }, { 12.10, "Поистине, это великий день." } } } } },
    [1080] = { d = 17.4, v = "gnome-male", n = { x = 206 }, c = { x = { { 0.00, "План Бета – почти то же, что и план Альфа." }, { 2.79, "Мы проводим отвлекающий манёвр, а потом похищаем их драгоценные письма." }, { 7.52, "Главное – получить письма... помни это." }, { 10.25, "На листках, которые я дал тебе, сказано, где поместить взрывчатку." }, { 14.67, "Не погибни и вернись с добытыми письмами..." } } }, t = { d = 9.4, v = "gnome-male", n = { x = 93 }, c = { x = { { 0.00, "Великолепно!" }, { 1.07, "Каэла и часовые будут счастливы." }, { 3.88, "При твоих умениях да моих творениях нас никто и ничто не остановит!" } } } } },
    [1081] = { d = 21.5, v = "nightelf-female#52", n = { x = 272 }, c = { x = { { 0.00, "Я уверена, что Тиранда Шелест Ветра лично хотела бы поблагодарить тебя за участие в этой миссии." }, { 6.32, "Может быть, это и незаметно с первого взгляда, но деяния, совершённые с твоей помощью, способны помочь нам закрепиться в Когтистых горах." }, { 15.16, "Если хочешь и далее помогать нам в борьбе, отправляйся на встречу с Тирандой в храм Луны в Дарнассе." } } }, t = { d = 18.2, g = 1, v = "nightelf-female#173", n = { m = 174, f = 175 }, c = { m = { { 0.00, "Приветствую тебя." }, { 1.51, "Мне доводилось и прежде слышать твоё имя, и я рада видеть, что, невзирая на твою молодость, ты уже избрал свой путь." }, { 11.20, "Ты окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе." } }, f = { { 0.00, "Приветствую тебя." }, { 1.45, "Мне доводилось и прежде слышать твоё имя, и я рада видеть, что, невзирая на твою молодость, ты уже избрала свой путь." }, { 10.84, "Ты окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе." } } } } },
    [1082] = { d = 21.4, v = "nightelf-female#52", n = { x = 255 }, c = { x = { { 0.00, "Твоя помощь здесь оказалась поистине бесценной." }, { 3.33, "Часовые Ясеневого леса вознаградят тебя, если ты уведомишь их, что я и Гаксим живы." }, { 9.16, "Скажи им, что мы трудимся над тем, чтобы остановить Торговую компанию и исцелить эти земли." }, { 15.50, "Найди в Астранааре Тару Тенисил, она обрадуется твоему возвращению и хорошим новостям." } } }, t = { d = 11.0, g = 1, v = "nightelf-female#52", n = { m = 113, f = 114 }, c = { m = { { 0.00, "Благодарю тебя." }, { 1.26, "Ты сослужил Стражам хорошую службу." }, { 4.05, "Я рада узнать, что Каэла... и даже Гаксим живы и здоровы." }, { 8.59, "Ты заслуживаешь нашего уважения." } }, f = { { 0.00, "Благодарю тебя." }, { 1.26, "Ты сослужила Стражам хорошую службу." }, { 4.13, "Я рада узнать, что Каэла... и даже Гаксим живы и здоровы." }, { 8.67, "Ты заслуживаешь нашего уважения." } } } } },
    [1083] = { d = 38.3, v = "nightelf-female#52", n = { x = 458 }, c = { x = { { 0.00, "Не могу сказать точно, что Торговая компания сделала с Долиной, однако ясно, что обитающие там существа взяли над ними верх." }, { 8.60, "Представители Торговой компании подожгли лес, они использовали свои убийственные изобретения для того, чтобы как можно сильнее опустошить Долину." }, { 18.64, "Но в невежестве своём они также освободили нечто иное: пылающих духов, элементалей огня, камня и ярости." }, { 25.93, "И этой земле никогда не узреть улыбку Элуны, пока эти существа бродят на свободе." }, { 31.73, "Принеси мне их дымящиеся угли, дабы доказать, что тебе удалось сократить число разъярённых духов." } } }, t = { d = 6.5, v = "nightelf-female#52", n = { x = 63 }, c = { x = { { 0.00, "Останки нашего врага... твоя сила сослужила нам добрую службу." }, { 5.29, "Благодарю тебя." } } } } },
    [1084] = { d = 31.6, v = "nightelf-female#52", n = { x = 393 }, c = { x = { { 0.00, "Мне кажется очевидным, что защитники долины – древни – вели какие-то дела с Торговой компанией, прежде чем их оттеснили прочь." }, { 8.17, "К несчастью, даже эти некогда великие охранители ныне впали в нечестие." }, { 12.93, "Гаксим полагает, что их падение каким-то образом связано с оружием, которое гоблины использовали во время отступления." }, { 20.63, "Я сказала ему, что возьму образец из тела раненого древня и отдам на изучение, чтобы понять, правда ли это." }, { 27.74, "Принеси мне немного шрапнели, чтобы гном мог дать мне ответ..." } } }, t = { d = 10.2, v = "nightelf-female#52", n = { x = 122 }, c = { x = { { 0.00, "Спасибо." }, { 0.62, "Этого должно быть более чем достаточно, чтобы Гаксим выяснил, каким образом скверна пала на древней." }, { 7.65, "Я немедленно передам ему этот образец." } } } } },
    [1085] = { d = 30.5, v = "nightelf-female#52", n = { x = 376 }, c = { x = { { 0.00, "Положение здесь, в Каменном Когте, явно не способствует совместной работе ночного эльфа и гнома." }, { 6.41, "Торговая компания опустошила эти земли, и большая часть моего времени уходит на то, чтобы положить предел уничтожению." }, { 14.32, "Не суди Гаксима преждевременно; он понимает, что нам с ним необходимо трудиться вместе." }, { 20.01, "Если ты хочешь помочь нам, то для начала поговори с Гаксимом." }, { 24.09, "Извини, что пока не могу отослать тебя обратно к Таре с хорошими новостями." }, { 29.18, "Может быть, вскоре..." } } }, t = { d = 32.8, v = "gnome-male", n = { x = 355 }, c = { x = { { 0.00, "Предательская... предательская и опасная, вот какова эта земля." }, { 4.67, "Но я тут для того, чтобы показать ночным эльфам, что ежели призвать на помощь старое доброе инженерное дело и чуточку магии, то так будет вернее." }, { 15.47, "Видишь ли, если убрать магию совсем, то ночным эльфам это никак не поможет – они без неё не могут." }, { 22.88, "И мир без неё не может." }, { 24.54, "А вот если подкрепить магию инженерным делом да алхимией, то так оно будет правильнее." }, { 30.95, "Возможностей просто масса." } } } } },
    [1086] = { d = 40.4, v = "scourge-female", n = { x = 368 }, c = { x = { { 0.00, "Отрава готова." }, { 1.40, "Остаётся только её доставить адресату." }, { 4.87, "И это придётся сделать тебе." }, { 7.52, "У Торговой Компании есть средства доставки сообщений и лёгкого груза от штаб-квартиры до Когтистых гор." }, { 16.77, "Скорее всего, это маленький аэропорт, подходящий не для дирижабля, а для ветролёта." }, { 24.29, "Обыщи все области Когтистых гор, находящиеся под контролем Торговой Компании, и найди этот аэропорт, если он существует." }, { 35.28, "Как найдёшь, помести туда отраву." }, { 38.33, "Положишь – беги оттуда." } } }, t = { d = 33.2, g = 1, v = "scourge-female", n = { m = 294, f = 295 }, c = { m = { { 0.00, "Ты нашёл аэропорт?" }, { 1.68, "Молодец!" }, { 2.52, "Отличный сюрприз ждал гоблинов!" }, { 5.46, "Будем надеяться, что яд доберётся до их штаб-квартиры." }, { 10.34, "Ты оказал своему народу неоценимую услугу, и пусть тебя не мучает совесть из-за отравления Торговой Компании." }, { 20.59, "Они ещё не того заслуживают." }, { 23.28, "И вот какой мудрости союзникам Отрёкшихся стоит поучиться:" }, { 28.66, "Не бойся тёмных дорог... если они ведут к победе." } }, f = { { 0.00, "Ты нашла аэропорт?" }, { 1.73, "Молодец!" }, { 2.56, "Отличный сюрприз ждал гоблинов!" }, { 5.45, "Будем надеяться, что яд доберётся до их штаб-квартиры." }, { 10.24, "Ты оказала своему народу неоценимую услугу, и пусть тебя не мучает совесть из-за отравления Торговой Компании." }, { 20.41, "Они ещё не того заслуживают." }, { 23.05, "И вот какой мудрости союзникам Отрёкшихся стоит поучиться:" }, { 28.34, "Не бойся тёмных дорог... если они ведут к победе." } } } } },
    [1087] = { d = 36.8, v = "bloodelf-female", n = { x = 426 }, c = { x = { { 0.00, "Ты и представить себе не можешь, как я ненавижу эти омерзительные земли!" }, { 5.06, "Отродья Кенария и кальдорайские друиды, обитающие на этом пике, используют свою жалкую силу, чтобы подавить поток магии, даже так далеко на юг от их гнусного обиталища... их драгоценных лесов." }, { 18.60, "Я так хочу вернуться в Джеденар и купаться в потоках магии, но мой господин не позволяет мне вернуться, пока моя работа здесь не будет завершена." }, { 28.72, "Не сомневаюсь, что ты любишь ночных эльфов и их союзников не больше, чем я." }, { 33.91, "Помоги мне, и мы оба внакладе не останемся." } } }, t = { d = 19.8, v = "bloodelf-female", n = { x = 185 }, c = { x = { { 0.00, "Я уже это чувствую... да... прекрасная мощь... струящийся поток." }, { 5.40, "Как же глупы кальдораи, что отвергают дары этого мира, не дают магии свободно, словно песня, струиться по жилам." }, { 14.98, "Как же скучна и бесцветна жизнь без этого огненного потока!" } } } } },
    [1088] = { d = 38.2, v = "bloodelf-female", n = { x = 377 }, c = { x = { { 0.00, "Они думали, что могут остановить течение магии." }, { 3.85, "Но они ошиблись." }, { 5.21, "Они думали, что смогут спрятать Хорданиуса – но я заполучу его голову!" }, { 10.84, "Магия даёт мне способность видеть истину." }, { 14.13, "Да... вот он где." }, { 15.41, "Скрещение путей..." }, { 16.91, "На вершине великого древа в Ясеневом лесу." }, { 20.33, "Название..." }, { 21.26, "Приют в Ночных Лесах." }, { 23.04, "Один из старших сыновей лесного бога." }, { 26.11, "Они унесли его прочь с этого пика прежде, чем я смогла найти его, однако его время на исходе." }, { 33.75, "Принеси мне его голову, и я поделюсь с тобой могуществом." } } }, t = { d = 19.4, v = "bloodelf-female", n = { x = 189 }, c = { x = { { 0.00, "Некогда, давным-давно, я знала Хорданиуса." }, { 3.53, "Он был горд, как и все его сородичи, и ставил себя даже над высокорождёнными." }, { 9.65, "Однако теперь ему трудно так же высоко держать голову, не так ли?" }, { 15.02, "Я обещала тебе награду, и ты её получишь." }, { 18.41, "Слушай меня!" } } } } },
    [1089] = { d = 36.6, v = "bloodelf-female", n = { x = 428 }, c = { x = { { 0.00, "В Пещере Когтей друиды построили Логово Когтя, где хранят множество могущественных предметов." }, { 6.73, "Они продумали сложный план, чтобы не дать этим предметам попасть в чужие руки." }, { 12.43, "К счастью, мне удалось... вытянуть некоторые подробности из одного из них." }, { 17.67, "В маленьком светильнике у входа в пещеру ты найдёшь спрятанный там Ключ Хранителя Врат – с его помощью ты сможешь отворить тайники, расположенные вокруг логова." }, { 29.00, "А предметы из этих тайников помогут тебе открыть сокровищницу, размещённую в одном из центральных помещений." } } }, t = { d = 7.8, v = "narrator", n = { x = 88 }, c = { x = { { 0.00, "Когда три ключа вошли каждый в своё отверстие, посреди мерцающего сияния появились несколько предметов." } } } } },
    [1090] = { d = 36.2, v = "goblin-male", n = { x = 427 }, c = { x = { { 0.00, "Знаешь, когда-то я был второй по важности персоной во всём этом деле." }, { 4.76, "Всё изменилось, когда главным стал Геренцо." }, { 7.72, "Уволил моего начальника Зиза Физзикса, а меня послал работать в копях." }, { 12.66, "Но Зиз велел мне оставаться здесь и собирать сведения." }, { 16.31, "Его новое начальство хорошо заплатит нам, если мы узнаем, что планирует Геренцо." }, { 21.87, "В любом случае, я точно знаю, что Геренцо приказал добыть как можно больше этой золотисто-зелёной руды." }, { 29.03, "Я могу раздобыть образец, а ты передашь его Зизу." }, { 32.49, "Но пока я этим занимаюсь, следи, не покажется ли стража." } } }, t = { d = 13.9, v = "goblin-male", n = { x = 157 }, c = { x = { { 0.00, "Спасибо." }, { 0.65, "Тут выдалось несколько опасных моментов, да и мы, наверное, были не слишком-то внимательны." }, { 7.10, "Но важно то, что у нас теперь есть образец руды, и мы должны как можно скорее доставить его Зизу." } } } } },
    [1091] = { d = 14.3, v = "gnome-male", n = { x = 158 }, c = { x = { { 0.00, "Отнеси эти письма Каэле." }, { 1.89, "Уверен, что она захочет это узнать." }, { 4.56, "По крайней мере, часовые точно захотят." }, { 7.49, "И обязательно расскажи ей о наших успехах и о том, что мы не добились бы ничего без чуточки магии." } } }, t = { d = 5.5, v = "nightelf-female#52", n = { x = 64 }, c = { x = { { 0.00, "Это действительно интересно." }, { 2.16, "Вы с Гаксимом всё сделали правильно." }, { 4.86, "Благодарю." } } } } },
    [1092] = { d = 31.8, v = "goblin-male", n = { x = 392 }, c = { x = { { 0.00, "Полагаю, мне тоже нужно убираться отсюда." }, { 2.85, "Не пройдёт много времени, как слухи о том, что произошло здесь, распространятся достаточно высоко, и вряд ли меня в следующий раз встретят там с добром да лаской." }, { 13.44, "Мне нужно выбраться наружу и встретиться с Зизом." }, { 16.77, "Надеюсь, он мне подыщет новую работёнку!" }, { 19.43, "Я попытаюсь тут слегка подчистить за собой, но тебе придётся доставить образец руды Зизу немедля." }, { 25.97, "Он говорил мне, что разбил свой лагерь где-то на западном склоне Утёса Ветрорезов." }, { 31.42, "Удачи!" } } }, t = { d = 17.6, v = "goblin-male", n = { x = 192 }, c = { x = { { 0.00, "А, я так и знал, что правильно сделал, когда сказал Пузнику остаться." }, { 4.96, "Я уверен, что инженеры в Нижней шахте захотят на это взглянуть." }, { 9.59, "Конечно, я собираюсь прихранить кусочек для себя, но если они чего-то не узнают, то это им и не повредит, верно?" } } } } },
    [1093] = { d = 35.1, v = "goblin-male", n = { x = 401 }, c = { x = { { 0.00, "Ну, Торговая Компания и наломала дров!" }, { 2.65, "О чём они только думали?" }, { 4.42, "Гоблинская компания нанимает гнома!" }, { 6.94, "К счастью для меня, Пароклапан всегда может узнать гения с первого взгляда." }, { 12.30, "Он нанял меня сразу же, как меня выгнали оттуда!" }, { 15.77, "Мне сказали, что компания строит какие-то огромные лесорубные машины, и Клапан хочет, чтобы я украл для него чертежи." }, { 24.03, "К несчастью, Геренцо – вот ведь злобный гном! – хочет меня убить... может быть, ты вместо меня украдёшь чертежи?" }, { 31.79, "Они должны быть у кого-то из операторов компании." } } }, t = { d = 16.5, v = "goblin-male", n = { x = 164 }, c = { x = { { 0.00, "Эй, это то, что я думаю?" }, { 1.89, "Отлично!" }, { 2.60, "Ну-с, посмотрим... и как мне понимать эту ерунду?.. и чем только думают эти гномы?" }, { 8.98, "Удивительно, что они хотя бы колесо сумели соорудить, не говоря уж об этих их обожаемых ветролётах." } } } } },
    [1094] = { d = 23.7, v = "goblin-male", n = { x = 267 }, c = { x = { { 0.00, "В этом конверте – все сведения, которые я смог собрать до того, как меня выпнули за дверь..." }, { 6.30, "Внутренние документы Торговой Компании, кое-какие руководства, технические бумажки..." }, { 12.22, "О, и, конечно, чертежи \"Супер-потрошителя шесть тысяч\"." }, { 16.03, "Пароклапан обосновался в Кабестане в Степях." }, { 19.08, "Тебе не доставит труда разыскать его, это такой мелкий зелёный тип." } } }, t = { d = 21.0, v = "goblin-male", n = { x = 234 }, c = { x = { { 0.00, "Физзик, да?" }, { 0.82, "Не то, чтоб я ему верил, но, кажется, это правильные сведения." }, { 5.20, "Что б я ни отдал, лишь бы Торговая Компания убралась подальше!" }, { 9.51, "Хотя они притащили с собой кое-какие хорошие машины... не буду отрицать, что от их изобретений есть польза, когда эти изобретения применяем мы, а не кто-то другой..." } } } } },
    [1095] = { d = 30.1, v = "goblin-male", n = { x = 346 }, c = { x = { { 0.00, "В Нижней шахте было много разговоров про этого гнома, нанятого Торговой Компанией." }, { 6.03, "Торговые олигархи не одобряют, что Раздунк связался с Геренцо." }, { 10.51, "Ридлвокс велел мне позаботиться об этой проблеме, и я не сомневаюсь, что это указание от одного из олигархов." }, { 18.29, "Разумеется, директор мне об этом не говорил." }, { 21.47, "Скажем так, у меня такое подозрение." }, { 24.13, "Как бы то ни было, Геренцо необходимо устранить, и Физзику придётся хорошо поработать." } } }, t = { d = 24.5, v = "goblin-male", n = { x = 275 }, c = { x = { { 0.00, "Убрать Геренцо?" }, { 1.17, "Я только за!" }, { 2.07, "Гномы вообще неприятный народ, но, судя по всему, этот Геренцо хуже других." }, { 7.65, "Он был одним из главных инженеров Гномрегана и работал над тайным проектом – каким именно, нам так и не удалось узнать, хоть мы и пытались пробраться в Дун Морог." }, { 19.12, "В докладах говорилось, что этот тайный проект буквально взорвался им в лицо." } } } } },
    [1096] = { d = 37.1, v = "goblin-male", n = { x = 419 }, c = { x = { { 0.00, "Один раз я встречал Геренцо и, скажу тебе, видок у него отвратнее некуда." }, { 5.39, "Такое впечатление, что его плоть гниёт и отпадает, части его тела заменены металлическими деталями и механизмами." }, { 13.50, "К северо-востоку отсюда, высоко над Скалистым озером, вблизи водяного колеса находится пункт, откуда Геренцо наблюдает за всей местностью." }, { 23.44, "Я не смог бы найти дорогу наверх, не говоря уж о том, чтобы справиться с Геренцо..." }, { 29.34, "Но тебе, кажется, это вполне под силу." }, { 32.20, "Если ты убьёшь его по моей просьбе, то получишь щедрое вознаграждение!" } } }, t = { d = 31.2, v = "goblin-male", n = { x = 353 }, c = { x = { { 0.00, "Взгляни на эту штуковину... только гном мог с такой управляться." }, { 4.55, "Не понимаю только, зачем отрезать руку и заменять её этой штукой, если можно просто сохранить обе руки и приделать третью!" }, { 13.46, "Гномы, я тебе скажу..." }, { 15.13, "Геренцо, по крайней мере, если и не мёртв, то неисправен." }, { 19.17, "Надеюсь, этого доказательства будет достаточно, и Пароклапан даст мне назначение в одну из мастерских Союза ремонтников в Прибамбасске или, может быть, даже в Нижней шахте." } } } } },
    [1097] = { d = 31.0, g = 1, v = "human-male#50", n = { m = 381, f = 381 }, c = { m = { { 0.00, "Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза." }, { 4.96, "Думаю, он хочет отправить посылку домой, на север." }, { 8.41, "Ты мне кажешься опытным путешественником..." }, { 11.25, "Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами." }, { 23.17, "Гриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов." }, { 28.56, "Это в северо-восточной части города." } }, f = { { 0.00, "Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза." }, { 4.91, "Думаю, он хочет отправить посылку домой, на север." }, { 8.32, "Ты мне кажешься опытной путешественницей..." }, { 11.14, "Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами." }, { 22.94, "Гриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов." }, { 28.26, "Это в северо-восточной части города." } } }, t = { d = 3.6, v = "dwarf-male", n = { x = 35 }, c = { x = { { 0.00, "Ты поможешь мне с доставкой?" }, { 2.54, "Замечательно!" } } } } },
    [1098] = { d = 33.4, v = "scourge-male", n = { x = 317 }, c = { x = { { 0.00, "Готовясь к нападению на крепость Тёмного Клыка, мы отправили на разведку двух стражей смерти." }, { 7.99, "Они не возвращаются вот уже много дней, но без их отчёта нам не организовать успешного нападения!" }, { 16.21, "Итак, вот твоё задание." }, { 18.25, "Отправляйся в крепость Тёмного Клыка на юге и найди стражей смерти Адаманта и Винсента." }, { 25.84, "Найди их и помоги им, если сможешь." }, { 28.98, "Это очень опасное и важное задание." }, { 32.19, "Не подведи нас." } } }, t = { d = 17.9, v = "narrator", n = { x = 171 }, c = { x = { { 0.00, "Перед вами лежит израненное тело Винсента." }, { 3.74, "Страж смерти Адамант написал отчёт Хадреку..." }, { 7.55, "Но что бы ни хотел добавить к его словам Винсент, он унёс это с собой в могилу." }, { 14.26, "В мёртвой руке зажата небольшая безделушка..." } } } } },
    [1100] = { d = 4.7, v = "narrator", n = { x = 51 }, c = { x = { { 0.00, "Вы медленно открываете потрёпанный дневник Хенрига Хмурня..." } } }, t = { d = 6.9, v = "nightelf-male#54", n = { x = 72 }, c = { x = { { 0.00, "Говорите, что нашли этот дневник у мёртвого дворфа?" }, { 3.97, "Дайте мне на минутку, хочу взглянуть..." } } } } },
    [1101] = { d = 29.5, v = "nightelf-male#54", n = { x = 293 }, c = { x = { { 0.00, "Бедный Гералат!" }, { 1.32, "И этот дворф..." }, { 2.57, "Хмурень." }, { 3.31, "Каким он был храбрецом!" }, { 5.21, "Нельзя, чтобы их усилия пропали даром." }, { 8.45, "Эта карга..." }, { 9.55, "Чарлга Остробок... нужно её убить." }, { 12.41, "Разумеется, поход в лабиринты Иглошкурых будет опасным, а за помощью в Дарнасс посылать некогда." }, { 20.27, "Так что тебе, придётся собрать отряд самостоятельно." }, { 24.46, "Принеси мне медальон Чарлги Остробок в доказательство её смерти." } } }, t = { d = 29.6, v = "nightelf-male#54", n = { x = 310 }, c = { x = { { 0.00, "Наконец-то старая карга умерла." }, { 2.58, "Это отличная новость!" }, { 4.37, "В наше опасное время всегда приятно встретить такого храбреца, как ты." }, { 10.04, "Теперь, когда прислужники Остробок мертвы, мы сможем продолжить наши исследования той области." }, { 17.56, "Возможно, теперь мы сможем узнать, почему место упокоения Агамаггана подверглось такому осквернению." }, { 25.59, "Однако, боюсь, здесь не обошлось без предательства..." } } } } },
    [1102] = { d = 38.6, v = "tauren-male#67", n = { x = 351 }, c = { x = { { 0.00, "Кэрн – благородный вождь, объединивший наш народ здесь, в Громовом Утёсе." }, { 6.44, "Но я не могу так легко простить тех, кто изгнал нас с земель наших предков." }, { 13.29, "Мой народ много десятилетий прожил в южных Степях." }, { 18.00, "Те края для нас священны." }, { 20.31, "Но нас изгнали многочисленные враги." }, { 23.61, "Месть ждёт старую ведьму Чарлгу Остробок, которая повелевает нечестивым воинством в Лабиринтах Иглошкурых." }, { 33.27, "Принеси мне сердце этой ведьмы, и я смогу спокойно умереть." } } }, t = { d = 23.0, g = 1, v = "tauren-male#67", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Теперь мерзкое племя Иглошкурых на себе испытает страдания моего народа!" }, { 7.05, "Пусть это будет им уроком." }, { 9.63, "Изгнание целого народа из священной земли – этот грех заслуживает самой жестокой кары!" }, { 17.97, "Благодарю тебя, за то, что откликнулся на мою просьбу." } }, f = { { 0.00, "Теперь мерзкое племя Иглошкурых на себе испытает страдания моего народа!" }, { 7.02, "Пусть это будет им уроком." }, { 9.59, "Изгнание целого народа из священной земли – этот грех заслуживает самой жестокой кары!" }, { 17.90, "Благодарю тебя, за то, что откликнулась на мою просьбу." } } } } },
    [1103] = { d = 32.9, g = 1, v = "troll-male#77", n = { m = 323, f = 327 }, c = { m = { { 0.00, "Привет, братан!" }, { 1.24, "Ты тута, чтобы очистить воду и доказать Ислен, что не лыком шит?" }, { 6.21, "Я тока что прикончил осквернённого духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню." }, { 14.63, "А эт што?" }, { 15.32, "А-а-а." }, { 15.87, "Тьев понимает, бывает непруха." }, { 18.22, "Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух." }, { 23.95, "Принеси мне сапту воды от Ислен, покажи, что готов к новому заходу, а я уж приготовлю тебе, чё нужно." } }, f = { { 0.00, "Привет, сеструха!" }, { 1.42, "Ты тута, чтобы очистить воду и доказать Ислен, что не лыком шита?" }, { 6.68, "Я тока что прикончил осквернённого духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню." }, { 15.34, "А эт што?" }, { 16.05, "А-а-а." }, { 16.62, "Тьев понимает, бывает непруха." }, { 19.04, "Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух." }, { 24.93, "Принеси мне сапту воды от Ислен, покажи, что готова к новому заходу, а я уж приготовлю тебе, чё нужно." } } }, t = { d = 22.9, g = 1, v = "troll-male#77", n = { m = 220, f = 223 }, c = { m = { { 0.00, "А-а-а, так ты готов..." }, { 1.81, "Тогда я кину свои вещички в жаровню, и ты тоже сможешь потолковать с духом." }, { 7.96, "И не боись, что не разглядишь мир духов с этой саптой... старый Тьев знает пару фокусов про то, как работает магия сапты." }, { 17.67, "Пошли, спустимся вместе к святилищу и потолкуем с духами, братан." } }, f = { { 0.00, "А-а-а, так ты готова..." }, { 1.87, "Тогда я кину свои вещички в жаровню, и ты тоже сможешь потолковать с духом." }, { 7.99, "И не боись, что не разглядишь мир духов с этой саптой... старый Тьев знает пару фокусов про то, как работает магия сапты." }, { 17.63, "Пошли, спустимся вместе к святилищу и потолкуем с духами, сеструха." } } } } },
    [1104] = { d = 31.8, v = "gnome-male", n = { x = 334 }, c = { x = { { 0.00, "Я нарисовал уже столько чертежей нового болида!" }, { 3.71, "И все их надо непременно воплотить!" }, { 6.40, "Я разрабатываю новое топливо, которое будет гореть жарко-жарко-прежарко!" }, { 12.04, "Пока что у меня не получается, но, кажется, я знаю, что мне может помочь..." }, { 17.75, "У скорпидов с Мерцающей равнины совершенно особый яд, в нём чрезвычайно много солей." }, { 24.15, "Он уникален!" }, { 25.11, "Как раз он-то мне и нужен." }, { 27.10, "Принеси мне их яда и поверь: тогда наши болиды просто взлетят!" } } }, t = { d = 12.2, v = "gnome-male", n = { x = 111 }, c = { x = { { 0.00, "Отлично!" }, { 0.78, "Этот яд как раз подойдёт!" }, { 2.90, "Спасибо!" }, { 3.69, "Теперь надо его вскипятить, добавить скиппер-отомер и нега-катализатор и..." }, { 10.36, "Чёрт!" }, { 10.83, "Где мои записи?!" } } } } },
    [1105] = { d = 28.0, v = "gnome-male", n = { x = 325 }, c = { x = { { 0.00, "Мой брат составляет новое топливо для болида." }, { 3.11, "Он в этом деле просто гений!" }, { 5.17, "Правда, боюсь, его новое гениальное топливо разъест всю машину..." }, { 9.78, "Поэтому я хочу укрепить топливные баки." }, { 12.58, "Здесь, на равнинах, живут черепахи с очень прочными панцирями." }, { 16.87, "Из них-то я и хочу сделать это покрытие – оно должно выдержать топливо моего брата." }, { 22.79, "Ну как, не желаешь ли взяться за эту работу и принести мне несколько панцирей?" } } }, t = { d = 10.0, v = "gnome-male", n = { x = 96 }, c = { x = { { 0.00, "Панцири!" }, { 0.73, "Спасибо!" }, { 1.45, "Ого, да они ещё твёрже, чем я думал!" }, { 4.35, "Вот примусь с ними работать – так, поди, целый ящик инструментов погну!" } } } } },
    [1106] = { d = 39.1, v = "gnome-male", n = { x = 431 }, c = { x = { { 0.00, "Я разрабатываю новый двигатель, с которым мой болид помчится быстрее ветра!" }, { 5.52, "Помчится так, что даже сможет взлететь!" }, { 8.40, "Осталось мне сделать поршни, которые выдержат очень, очень высокое давление." }, { 14.05, "Все мои испытания провалились потому, что я не смог сделать достаточно крепких поршней!" }, { 20.36, "Но есть тот, кто может мне помочь." }, { 22.78, "Его зовут Мартек Изгой." }, { 24.62, "Он отличный кузнец и знает о металлах больше других." }, { 28.50, "Вот, отвези ему это письмо, я знаю, он поможет мне!" }, { 32.31, "Правда, живёт он далеко – в Азероте, в Бесплодных землях, в одном лагере с гоблином!" }, { 38.41, "Найди его!" } } }, t = { d = 24.7, v = "orc-male", n = { x = 231 }, c = { x = { { 0.00, "Тебя прислал Пшикс?" }, { 1.65, "Это всё меняет!" }, { 3.00, "Разумеется, я помогу тебе." }, { 5.24, "Пшикс и его брат – одни из немногих, кто не желает мне смерти." }, { 10.34, "Значит, Пшикс хочет сделать поршни, да?" }, { 13.64, "Да такие сильные, чтобы выдержали всё, что он задумал, а зная Пшикса, могу точно сказать, что его новый болид – это вулкан на колёсах!" } } } } },
    [1107] = { d = 35.9, v = "gnome-male", n = { x = 424 }, c = { x = { { 0.00, "Наш болид – это самая быстрая машина на равнинах!" }, { 3.51, "Она такая быстрая, что... я боюсь, что от трения её разнесёт на куски." }, { 8.33, "Чтобы этого не произошло, мне нужен материал для покрытия движущихся частей машины." }, { 14.15, "Он должен быть твёрдым, но не хрупким, и выдерживать соляную коррозию, иначе на Мерцающей равнине он долго не протянет." }, { 22.29, "Слышали когда-нибудь про Коварный риф?" }, { 24.92, "Это у побережья Тернистой долины." }, { 27.30, "Там обитает племя мурлоков под названием Соляная Чешуя, и их хвостовые плавники как нельзя лучше подойдут для моего материала." } } }, t = { d = 14.0, v = "gnome-male", n = { x = 172 }, c = { x = { { 0.00, "Спасибо!" }, { 0.60, "Осталось размолоть их, добавить кое-какие ингредиенты, и всё будет готово." }, { 5.62, "Тогда, по крайней мере, болид не пострадает от своей собственной скорости." }, { 10.64, "Ещё бы он от какого-нибудь препятствия не пострадал..." } } } } },
    [1108] = { d = 42.6, v = "orc-male", n = { x = 468 }, c = { x = { { 0.00, "Я здесь не только потому, что хочу держаться ото всех подальше." }, { 4.79, "В Бесплодных землях очень много металла, но добыть его сумеет не всякий." }, { 10.41, "Этот металл называется индарилий, и говорят, что он обладает удивительной сопротивляемостью к температуре и механическим воздействиям." }, { 20.40, "Как раз то, что нужно Пшиксу для его машины." }, { 23.76, "Но я должен всё проверить." }, { 25.74, "Принесите мне немного индарилия, а я исследую его свойства." }, { 30.26, "Настоящая индарилиевая руда залегает глубоко в шахтах Ульдамана, но трогги из племени Каменного Свода иногда тоже носят с собой обломки индарилия." }, { 41.49, "Принесите их мне." } } }, t = { d = 5.6, v = "orc-male", n = { x = 42 }, c = { x = { { 0.00, "Да, то, что нужно." }, { 1.83, "Положу их в горн и посмотрю, что будет." } } } } },
    [1109] = { d = 46.3, g = 1, v = "scourge-male", n = { m = 435, f = 436 }, c = { m = { { 0.00, "Как видишь, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты." }, { 8.09, "Поскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами." }, { 16.42, "Работы полно, а времени в обрез!" }, { 19.30, "Судя по виду, ты немало странствовал." }, { 22.56, "Не поможешь мне?" }, { 23.96, "Нам очень нужно редкое вещество." }, { 26.84, "Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых." }, { 39.37, "Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу..." } }, f = { { 0.00, "Как видишь, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты." }, { 8.26, "Поскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами." }, { 16.76, "Работы полно, а времени в обрез!" }, { 19.70, "Судя по виду, ты немало странствовала." }, { 23.12, "Не поможешь мне?" }, { 24.55, "Нам очень нужно редкое вещество." }, { 27.49, "Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых." }, { 40.28, "Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу..." } } }, t = { d = 4.0, v = "scourge-male", n = { x = 29 }, c = { x = { { 0.00, "Превосходно!" }, { 1.46, "Этого нам и не хватало." } } } } },
    [1110] = { d = 25.0, v = "dwarf-male", n = { x = 279 }, c = { x = { { 0.00, "Хе-хе, да тут такие гонки бывают, как же без происшествий!" }, { 4.23, "Вы только оглянитесь – все Мерцающие равнины просто усыпаны обломками разбитых болидов." }, { 10.64, "И за все эти детали гномы и гоблины могут хорошенько заплатить." }, { 15.33, "Они вечно ищут, какую бы ещё рухлядь привинтить на свои тачки." }, { 20.02, "Ступайте и принесите мне побольше деталей, а я вам хорошенько заплачу." } } }, t = { d = 25.5, v = "dwarf-male", n = { x = 250 }, c = { x = { { 0.00, "Ого, вы только посмотрите!" }, { 2.16, "Кое-что хорошее в этой горе металлолома ещё есть." }, { 6.11, "Наверняка я смогу продать это за кругленькую сумму." }, { 10.28, "А... это что, оторванное ухо?" }, { 12.66, "Ой!" }, { 12.94, "Не хотел бы я быть на месте того пилота." }, { 16.18, "Спасибо." }, { 16.90, "Вот ваша плата." }, { 18.19, "И ещё бесплатный совет..." }, { 20.21, "Если хорошенько поискать, на чужой беде всегда можно нагреть руки." } } } } },
    [1111] = { d = 27.4, v = "dwarf-male", n = { x = 323 }, c = { x = { { 0.00, "Моя работа – выполнять запросы покупателей, а гномы заказали у меня набор деталей." }, { 5.82, "Эти детали ещё неделю назад прибыли в Кабестан, но я всё никак туда не выберусь." }, { 11.45, "Может, ты туда смотаешься?" }, { 13.32, "Вот, надо будет найти управляющего пристанью Головокружилкинса и отдать ему этот заказ." }, { 19.45, "Если выполнишь моё поручение, я смогу доверить тебе и другие поручения." }, { 24.46, "Разумеется, твой труд будет достойно оплачен." } } }, t = { d = 10.2, v = "goblin-male", n = { x = 101 }, c = { x = { { 0.00, "Ах, да!" }, { 0.57, "Детали для Крейвела." }, { 2.20, "Хорошо, что за ними пришли!" }, { 4.41, "Этот хлам валяется тут уже давно, я даже начал бояться, что он проржавеет!" } } } } },
    [1112] = { d = 10.3, v = "goblin-male", n = { x = 106 }, c = { x = { { 0.00, "Вот посылка для Крейвела." }, { 1.99, "И когда отнесёте, скажите ему... что если ему нужны ещё особые заказы, то придётся заплатить по всем счетам!" } } }, t = { d = 7.0, v = "dwarf-male", n = { x = 54 }, c = { x = { { 0.00, "Ура, детали!" }, { 1.29, "Надо отнести их гномам." }, { 3.60, "Но сначала..." }, { 4.89, "Вынем оттуда кое-что..." } } } } },
    [1113] = { d = 43.0, v = "scourge-male", n = { x = 416 }, c = { x = { { 0.00, "Зачем мне редкий вид гуано, спросишь ты." }, { 3.50, "Отвечаю." }, { 4.28, "Я хочу выяснить в ходе эксперимента, какое воздействие окажут друг на друга два диаметрально противоположных химических вещества, особенно если оба смешать с токсичным реагентом, чтобы результаты были... погаже." }, { 22.49, "В северо-восточной части Тирисфальских лесов располагается Монастырь Алого ордена." }, { 29.65, "В его стенах и за их пределами живут безумные последователи Алого ордена." }, { 36.04, "Убей их и принеси мне их ревностные сердца." }, { 39.77, "Наше варево будет поистине ужасающим." } } }, t = { d = 6.6, g = 1, v = "scourge-male", n = { m = 46, f = 47 }, c = { m = { { 0.00, "Сколько же на тебе кровищи!" }, { 2.94, "Я вижу, ты неплохо потрудился!" } }, f = { { 0.00, "Сколько же на тебе кровищи!" }, { 3.17, "Я вижу, ты неплохо потрудилась!" } } } } },
    [1114] = { d = 19.5, v = "dwarf-male", n = { x = 220 }, c = { x = { { 0.00, "Ну вот, у меня есть всё, что нужно." }, { 2.44, "Осталось только отнести эти детали Пшиксу Медноштифу." }, { 6.36, "Он уже давно их ждёт – полагаю, он даже не заметит отсутствие одной маленькой детальки." }, { 12.60, "Не стоит даже упоминать, что я её забрал." }, { 15.55, "Эта деталька совсем маленькая и ненужная." }, { 18.57, "Правда-правда." } } }, t = { d = 7.1, v = "gnome-male", n = { x = 65 }, c = { x = { { 0.00, "Вот они!" }, { 0.81, "Мои гидромеханизмы и усилительные болты!" }, { 4.45, "То, что нужно." }, { 5.74, "Большое спасибо!" } } } } },
    [1115] = { d = 34.5, v = "dwarf-male", n = { x = 385 }, c = { x = { { 0.00, "Ну вот, гномам услугу оказали, пора и гоблинам помочь!" }, { 3.94, "Говорят, что гоблинского пилота, Назза Парового Котла, раньше звали не так." }, { 9.37, "Интересно, почему он сменил имя?" }, { 11.76, "Наверное, это секрет, и, скорее всего, он дорожит этим секретом." }, { 16.47, "Если кто и знает правду, то только Кразек из Пиратской бухты, на южном мысу Тернистой долины." }, { 23.26, "Поговорите с Кразеком и разузнайте у него про нашего пилота-гоблина." }, { 28.16, "Если вам удастся добыть у него ценную информацию, то мы все сможем извлечь из неё прибыль." } } }, t = { d = 13.6, v = "goblin-male", n = { x = 132 }, c = { x = { { 0.00, "Хотите узнать про Назза Парового Котла?" }, { 3.27, "Вроде это гонщик с Мерцающей равнины?" }, { 6.40, "Да, я могу кое-что разузнать про него, но это будет нелегко." }, { 11.35, "И не сразу." }, { 12.30, "И не за бесплатно." } } } } },
    [1116] = { d = 34.2, v = "goblin-male", n = { x = 351 }, c = { x = { { 0.00, "Вытащить информацию из Назза – дело непростое." }, { 3.63, "Очень непростое." }, { 4.95, "Но, раз уж вы ради этого приехали аж с Мерцающей равнины, то... не хотите ли попутешествовать ещё немного?" }, { 12.97, "Собрали бы для меня кое-что, пока я буду связываться со своими источниками, а?" }, { 19.04, "Хм..." }, { 19.46, "Что бы вам такое поручить?" }, { 21.48, "А, вот: сонная пыль с дракончиков из Болота Печали." }, { 25.38, "Да, сонная пыль – это именно то, что мне нужно." }, { 29.01, "Принесите мне её, а я взамен поделюсь с вами необходимой информацией." } } }, t = { d = 9.8, v = "goblin-male", n = { x = 78 }, c = { x = { { 0.00, "Вот это да!" }, { 1.13, "Вы нашли сонную пыль!" }, { 3.22, "Ну, и как там, на болотах?" }, { 5.66, "Говорят, горячей еды днём с огнём не сыщешь!" } } } } },
    [1117] = { d = 26.9, v = "goblin-male", n = { x = 304 }, c = { x = { { 0.00, "Мне пришлось кое-кому оказать услугу, кое-кому подарить бутылку редкого эльфийского вина, а кое-что даже разузнать самостоятельно!" }, { 9.67, "Однако я добыл вам всю необходимую информацию." }, { 13.02, "Вот, я написал тут несколько интересных фактов касательно Назза Парового Котла." }, { 18.81, "Делайте с ними что хотите, а для меня эта информация слишком опасна." }, { 23.87, "И не говорите никому, откуда вы её достали!" } } }, t = { d = 18.9, v = "dwarf-male", n = { x = 206 }, c = { x = { { 0.00, "Так-так!" }, { 0.70, "Интересно..." }, { 1.67, "Очень интересно." }, { 3.00, "Хех, возможно, мне придётся поздороваться с гоблинским пилотом при следующей встрече." }, { 9.41, "Эта информация многого стоит." }, { 11.78, "Думаю, Назз согласится раскошелиться за то, чтобы его секрет не стал достоянием общественности." } } } } },
    [1118] = { d = 36.3, g = 1, v = "dwarf-male", n = { m = 379, f = 380 }, c = { m = { { 0.00, "Ты – хороший герой, ты сможешь выполнить это задание и не болтать о нём налево-направо." }, { 6.38, "Я разрабатываю новый план." }, { 8.29, "Он довольно рискованный, но если всё получится, то мы озолотимся!" }, { 12.97, "А ты как раз отлично сможешь мне помочь." }, { 15.86, "Для начала тебе надо вернуться в Пиратскую бухту." }, { 19.55, "Прости, дорогой путник." }, { 21.32, "Я знаю, что ты уже был там по моему поручению, но в этот раз тебе надо будет поговорить с Шиззи Пуззыриксом." }, { 29.22, "Отдай ему это письмо, а если он попросит помочь, то не откажи ему." }, { 34.22, "Поверь, оно того стоит." } }, f = { { 0.00, "Ты – хорошая героиня, ты сможешь выполнить это задание и не болтать о нём налево-направо." }, { 6.53, "Я разрабатываю новый план." }, { 8.44, "Он довольно рискованный, но если всё получится, то мы озолотимся!" }, { 13.12, "А ты как раз отлично сможешь мне помочь." }, { 16.02, "Для начала тебе надо вернуться в Пиратскую бухту." }, { 19.72, "Прости, дорогая путница." }, { 21.56, "Я знаю, что ты уже была там по моему поручению, но в этот раз тебе надо будет поговорить с Шиззи Пуззыриксом." }, { 29.61, "Отдай ему это письмо, а если он попросит помочь, то не откажи ему." }, { 34.62, "Поверь, оно того стоит." } } }, t = { d = 18.6, v = "goblin-male", n = { x = 189 }, c = { x = { { 0.00, "Понятно." }, { 0.70, "Крейвел придумал очень хитрую схему." }, { 3.62, "Он очень умён – в этом ему не откажешь." }, { 6.68, "Значит, вам нужно что-то, от чего мутится рассудок, так?" }, { 11.06, "Что-то сильнодействующее..." }, { 13.15, "Думаю, можно использовать смеси, которыми Занзил кормит своих зомби..." } } } } },
    [1119] = { d = 25.1, v = "goblin-male", n = { x = 291 }, c = { x = { { 0.00, "Я понял, как смешать смесь Занзила с пивом, чтобы получилось убойное пойло – \"Дурацкое крепкое\"!" }, { 6.71, "Наверное, это именно то, что нужно Крейвелу." }, { 9.84, "Отнесите ему, пусть попробует." }, { 11.97, "Расскажете потом, как всё прошло!" }, { 14.29, "Кстати, эту брагу надо употребить как можно скорее – смесь Занзила оказывает на пивную закваску не очень хороший эффект, так что оно очень скоро выдохнется." } } }, t = { d = 12.8, v = "dwarf-male", n = { x = 129 }, c = { x = { { 0.00, "Отлично!" }, { 0.74, "Гранк здорово помог нам!" }, { 2.72, "Обязательно отблагодарю его при встрече." }, { 6.04, "И вам спасибо." }, { 7.21, "Вы сделали большое дело, и оба мы заработаем на этом огромные деньги." } } } } },
    [1120] = { d = 13.9, v = "dwarf-male", n = { x = 175 }, c = { x = { { 0.00, "Надо напоить \"Дурацким Крепким\" одну из команд на пит-стопах." }, { 4.04, "Хочешь посмотреть, как оно подействует на гномов?" }, { 7.26, "Тогда возьми эль и передай его начальнику гномского гаража." }, { 11.19, "И поторопись – эта бурда быстро выдыхается." } } }, t = { d = 11.4, v = "gnome-male", n = { x = 121 }, c = { x = { { 0.00, "Крепкое пиво?" }, { 1.05, "Как мило!" }, { 1.78, "Спасибо большое!" }, { 3.03, "Перед гонкой, конечно, пить не стоит, но..." }, { 6.19, "Самую чуточку ребятам не повредит." }, { 8.76, "Да и не такое уж оно крепкое, так ведь?" } } } } },
    [1121] = { d = 13.8, v = "dwarf-male", n = { x = 179 }, c = { x = { { 0.00, "Надо напоить \"Дурацким Крепким\" одну из команд на пит-стопах." }, { 3.93, "Хочешь посмотреть, как оно подействует на гоблинов?" }, { 7.18, "Тогда возьми эль и передай его начальнику гоблинского гаража." }, { 11.11, "И поторопись – эта бурда быстро выдыхается." } } }, t = { d = 6.6, v = "goblin-male", n = { x = 53 }, c = { x = { { 0.00, "Что это?" }, { 0.86, "Ах, выпивка?" }, { 2.07, "Ну что ж, стаканчик-другой никогда не повредит..." } } } } },
    [1122] = { d = 25.7, v = "dwarf-male", n = { x = 298 }, c = { x = { { 0.00, "\"Дурацкое Крепкое\" отлично сработало!" }, { 2.66, "Я сделал ставку на следующую гонку и... надеюсь, команда, которую вы напоили, хорошенько раздолбала свою машину!" }, { 10.60, "У меня ещё одно задание для вас: отнесите эту записку обратно Шиззи Пуззыриксу в Пиратскую бухту." }, { 17.51, "Наверняка он захочет узнать, что эксперимент удался." }, { 21.19, "Надо будет заказать у него ещё этой выпивки для следующих гонок!" } } }, t = { d = 12.1, v = "goblin-male", n = { x = 130 }, c = { x = { { 0.00, "Здесь сказано, что задумка с \"Дурацким Крепким\" удалась." }, { 4.28, "Отличная новость!" }, { 5.67, "Если вам вдруг потребуется ещё, дайте знать, и я отправлю вас добыть ещё смеси Занзила." } } } } },
    [1123] = { d = 39.4, g = 1, v = "creature/hamuul", n = { m = 382, f = 383 }, c = { m = { { 0.00, "Для этого мажордом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи." }, { 6.97, "Нужно обследовать обширные пустоши к западу от Танариса и Ун'Горо." }, { 12.64, "Он живёт в Ночной Гавани, главном поселении Лунной поляны." }, { 17.62, "Я хочу, чтобы ты понимал всю важность твоего присутствия там." }, { 22.82, "Между ночными эльфами Дарнасса и Кругом Кенария Лунной поляны существуют трения." }, { 29.79, "Но ты будь выше расовых предрассудков и прибегай к мудрости предков при общении с Кругом." }, { 37.30, "Да пребудет с тобой удача." } }, f = { { 0.00, "Для этого мажордом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи." }, { 6.83, "Нужно обследовать обширные пустоши к западу от Танариса и Ун'Горо." }, { 12.38, "Он живёт в Ночной Гавани, главном поселении Лунной поляны." }, { 17.26, "Я хочу, чтобы ты понимала всю важность твоего присутствия там." }, { 22.44, "Между ночными эльфами Дарнасса и Кругом Кенария Лунной поляны существуют трения." }, { 29.27, "Но ты будь выше расовых предрассудков и прибегай к мудрости предков при общении с Кругом." }, { 36.62, "Да пребудет с тобой удача." } } }, t = { d = 26.6, v = "nightelf-male#59", n = { x = 310 }, c = { x = { { 0.00, "Я Рабин Сатурна." }, { 1.24, "От лица хранителя Ремула и всех обитателей сего священного места приветствую тебя." }, { 7.25, "Я ценю твою заинтересованность и горячую готовность помочь Кругу Кенария." }, { 12.60, "Таурены не раз показывали стойкую приверженность принципам Кенария, и благодаря им Орда может пользоваться безопасностью Лунной поляны." }, { 22.33, "Ведь благо Азерота – наша общая цель." }, { 25.07, "Здесь ты среди друзей." } } } } },
    [1124] = { d = 38.2, v = "nightelf-male#59", n = { x = 418 }, c = { x = { { 0.00, "К западу от Кратера Ун'Горо, за северо-западным гребнем, лежит суровый пустынный край – Силитус." }, { 7.16, "Немногие помнят, что там в древности развернулась война между ночными эльфами и злобной, чужеродной силой." }, { 15.05, "Зло было повержено и заключено в оковы, но мы подозреваем, что сейчас некие силы хотят пробудить этот... невыразимый ужас." }, { 24.14, "Найди Лайо Звёздный Всполох, одного из наших разведчиков в Силитусе." }, { 29.22, "Ищи его в Покое Доблестных, последнем приюте павших в этих пустынных краях." }, { 34.98, "Передай ему это письмо, и он доверится тебе." } } }, t = { d = 29.6, v = "nightelf-male#54", n = { x = 298 }, c = { x = { { 0.00, "Так тебя послал Рабин?" }, { 1.85, "Что же, чувствуй себя как дома... если хоть кто-то может назвать домом этот богами забытый край." }, { 9.56, "Во времена великих бед меня ещё не было среди живых, но в этих краях есть места, которые наяву рисуют жуткую картину позабытого прошлого." }, { 20.55, "С твоей помощью Круг Кенария, может быть, покончит с угрозой, которая, как мы думали, исчезла много поколений назад." } } } } },
    [1125] = { d = 32.0, v = "nightelf-male#54", n = { x = 319 }, c = { x = { { 0.00, "На юго-западе находится очень грустное место – деревня Южного Ветра." }, { 5.73, "Именно с неё мы и начнём." }, { 7.71, "Судя по всему, некогда она была базой ночных эльфов для военных действий в Силитусе." }, { 14.76, "Её давным-давно захватили силитиды." }, { 17.69, "Страшно представить, что там творилось в момент захвата..." }, { 22.39, "По руинам бесцельно бродят духи павших друидов и стражниц." }, { 27.23, "Исследуй эти края и освободи страдающие души, как подобает." } } }, t = { d = 26.2, v = "nightelf-male#54", n = { x = 278 }, c = { x = { { 0.00, "Я подозревал, что немалую роль в гибели деревни сыграл огромный улей в башне неподалёку." }, { 6.79, "Похоже, проделанная тобой работа подтверждает мои подозрения; улей представляет опасность для всей нашей деятельности." }, { 15.95, "Благодарю тебя за милость, оказанную душам павших." }, { 19.94, "Я знаю, как нелегко это сделать." }, { 22.53, "И всё же я хочу вновь воззвать к тебе о помощи..." } } } } },
    [1126] = { d = 34.2, v = "nightelf-male#54", n = { x = 359 }, c = { x = { { 0.00, "Пора заняться ульем в деревне Южного Ветра, и мне кажется, я знаю, как это лучше сделать." }, { 6.99, "Я знаю по опыту, что ульи силитидов очень чувствительны к окружающей среде; этим объясняются их нападения при звуках призрачного воя." }, { 17.22, "Средоточие силы силитидов – башня, та самая, вокруг которой вьются осы." }, { 22.83, "Ступай к этой башне и пробуди весь улей." }, { 26.01, "Доложи обо всём, что удастся узнать, но соблюдай осторожность!" }, { 30.71, "Если попадётся что-нибудь полезное, неси сюда." } } }, t = { d = 34.0, v = "nightelf-male#54", n = { x = 334 }, c = { x = { { 0.00, "Что за..." }, { 0.73, "Что это?" }, { 1.45, "Оно имеет форму... ящика?" }, { 3.63, "А дрянью-то как заросло..." }, { 5.73, "Стой, здесь видна часть того, что внутри." }, { 8.99, "Неужели под всей этой гадостью скрывается книга?" }, { 12.91, "Кажется, тебе удалось найти кое-что интересное… по крайней мере, хочется на это надеяться." }, { 20.30, "Может быть, это дневник или журнал, оставшийся с древних времён, лежавший в целости и сохранности под покровом хитиновой скорлупы." }, { 30.74, "Кажется, я знаю способ выяснить, что это." } } } } },
    [1127] = { d = 10.5, v = "goblin-male", n = { x = 110 }, c = { x = { { 0.00, "Говорите, вам нужно \"Дурацкое Крепкое\", да?" }, { 3.29, "Хотите снова отправиться на гонки?" }, { 5.97, "Ну ладно, принесите мне ещё смеси Занзила, и я наварю вам ещё." } } }, t = { d = 7.0, v = "goblin-male", n = { x = 58 }, c = { x = { { 0.00, "Очень хорошо!" }, { 1.36, "Вот твоя плата." }, { 2.88, "И вот ещё кое-что... за твою осмотрительность." } } } } },
    [1130] = { d = 16.3, v = "tauren-male#67", n = { x = 153 }, c = { x = { { 0.00, "Мелор Каменное Копыто узнал о ваших подвигах и наметил для вас путь." }, { 6.02, "Если вы хотите пройти его, отправляйтесь в Громовой Утёс и поговорите с Мелором." }, { 13.07, "Его можно найти на Вершине Охотников." } } }, t = { d = 10.8, g = 1, v = "tauren-male#68", n = { m = 75, f = 75 }, c = { m = { { 0.00, "Итак, вы пришли..." }, { 1.85, "Значит, вы готовы к путешествию через дальние земли?" }, { 7.05, "Раз так, юный герой, то слушайте..." } }, f = { { 0.00, "Итак, вы пришли..." }, { 1.90, "Значит, вы готовы к путешествию через дальние земли?" }, { 7.25, "Раз так, юная героиня, то слушайте..." } } } } },
    [1131] = { d = 44.5, v = "tauren-male#68", n = { x = 394 }, c = { x = { { 0.00, "Иногда мы охотимся ради еды." }, { 2.68, "Иногда – ради чести." }, { 4.63, "А иногда мы охотимся для того, чтобы усвоить уроки Матери-Земли." }, { 10.57, "Но охота, на которую я хочу отправить вас, не имеет с этими вещами ничего общего." }, { 17.97, "Вам нужно будет убить существо, не подчиняющееся божественной воле Матери-Земли." }, { 25.29, "Гиена по кличке Сталезуб бродит по Тысяче Игл, к югу от Степей." }, { 31.06, "К этой зверюге прибиваются другие гиены, и вместе они держат всех остальных более мирных животных в страхе." }, { 40.90, "Найдите Сталезуба." }, { 42.61, "Найдите и убейте его." } } }, t = { d = 8.9, v = "tauren-male#68", n = { x = 69 }, c = { x = { { 0.00, "Убив Сталезуба, вы избавили Тысячу Игл от страшной напасти." }, { 6.16, "И это, ваш урок на сегодня." } } } } },
    [1132] = { d = 33.9, g = 1, v = "human-male", n = { x = 390 }, c = { m = { { 0.00, "О, как я хочу снова вернуться на море!" }, { 2.74, "Почувствовать поцелуй ветра, покачаться на волнах, как в детстве на руках у моей милой мамы!" }, { 9.31, "Как же вам повезло, герой, вы ещё можете оказаться на морском берегу!" }, { 14.16, "Это моя работа – рассказывать всем неутомимым искателям приключений Калимдора о море." }, { 20.22, "Если хотите, садитесь на корабль и плывите в прелестный порт Аубердин." }, { 25.20, "Там поговорите с моей коллегой, эльфийкой по имени Фиора Длинноушка." }, { 30.05, "Она отправит вас в незабываемое путешествие по Калимдору!" } }, f = { { 0.00, "О, как я хочу снова вернуться на море!" }, { 2.73, "Почувствовать поцелуй ветра, покачаться на волнах, как в детстве на руках у моей милой мамы!" }, { 9.26, "Как же вам повезло, героиня, вы ещё можете оказаться на морском берегу!" }, { 14.20, "Это моя работа – рассказывать всем неутомимым искателям приключений Калимдора о море." }, { 20.23, "Если хотите, садитесь на корабль и плывите в прелестный порт Аубердин." }, { 25.17, "Там поговорите с моей коллегой, эльфийкой по имени Фиора Длинноушка." }, { 29.99, "Она отправит вас в незабываемое путешествие по Калимдору!" } } }, t = { d = 12.4, v = "bloodelf-female", n = { x = 129 }, c = { x = { { 0.00, "Добрый день!" }, { 0.98, "Вы приплыли из Гавани Менетилов по поручению мистера Флинта?" }, { 5.68, "О, мистер Флинт разбирается в людях!" }, { 8.48, "Если он послал вас сюда – значит, здесь ваше место." } } } } },
    [1133] = { d = 20.1, v = "bloodelf-female", n = { x = 239 }, c = { x = { { 0.00, "Если вы только что прибыли по морю из Менетила, отправляйтесь прямиком в Астранаар." }, { 5.78, "Уверена, такому преданному члену Альянса найдётся чем заняться в городе." }, { 10.80, "Поговорите там с Шиндрелл Огненный Всполох и предложите ей свои услуги." }, { 15.76, "Не стоит говорить ей, кто вас прислал." }, { 18.40, "Шиндрелл меня не знает..." } } }, t = { d = 9.3, v = "nightelf-female#52", n = { x = 106 }, c = { x = { { 0.00, "Вы здесь, чтобы предложить свою помощь Альянсу?" }, { 3.42, "Война уже добралась до этих мест, хотя Ясеневый лес всё так же хранит свою красоту." } } } } },
    [1134] = { d = 33.8, v = "nightelf-female#52", n = { x = 402 }, c = { x = { { 0.00, "Между нами и Ордой война не объявлена, однако мир между нами очень хрупок." }, { 5.29, "Мы часто обнаруживаем, что среди нас тайно действуют их агенты." }, { 9.65, "Об одной такой операции мы узнали из скрытых источников в Тераморе." }, { 14.31, "Эти источники утверждают, что орки собирают яд славнокрылов поблизости от Мутного озера в Когтистых горах, на юге." }, { 22.22, "А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса!" }, { 28.57, "Если это правда, мы обязаны остановить их." }, { 31.55, "Мы должны лишить их источника яда." } } }, t = { d = 22.8, v = "nightelf-female#52", n = { x = 283 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.08, "Мне не хотелось отправлять тебя убивать этих созданий, которые, возможно, не по своей воле помогали нашим врагам, однако это был мой долг." }, { 10.33, "Быть может, друг мой, твоё сердце оплакивает славнокрылов, которых тебе пришлось убить, однако пусть тебе принесёт утешение то, что твои союзники больше не будут погибать от яда славнокрылов." } } } } },
    [1135] = { d = 29.1, v = "bloodelf-female", n = { x = 308 }, c = { x = { { 0.00, "Как вы уже знаете, орки часто приручают виверн в качестве ездовых животных." }, { 5.87, "Но мало кто знает о том, что яд виверны порой может быть ценнее самого животного." }, { 12.08, "Так что, если желаете немного поохотиться, то у меня есть для вас работа." }, { 17.60, "В Тысяче Игл – это к западу отсюда – есть место под названием Скальное гнездовье." }, { 23.82, "Там живут виверны, яд которых очень силён и чрезвычайно высоко ценится." } } }, t = { d = 12.2, v = "bloodelf-female", n = { x = 131 }, c = { x = { { 0.00, "О-о-о, некоторые чуть ли не лопаются от яда!" }, { 3.34, "Такие обычно собирают с очень юных виверн или с плодовитых самок." }, { 8.44, "Наверное, нелегко вам пришлось в Скальном гнездовье!" } } } } },
    [1136] = { d = 43.7, g = 1, v = "tauren-male#68", n = { m = 435, f = 436 }, c = { m = { { 0.00, "Настало время тебе отправиться в далёкие земли." }, { 3.91, "Ты готов к этому путешествию." }, { 6.35, "Тебе поручается убить Ледочрева – йети, живущего в Альтеракских горах." }, { 12.17, "Он отлично маскируется, его белая шкура сливается со снегами его горного обиталища." }, { 19.11, "Увидеть его можно лишь изредка." }, { 21.77, "Но я расскажу тебе, как приманить такое существо, как этот йети." }, { 27.08, "Вот, возьми этот свиток: на нём я написал, как привлечь Ледочрева." }, { 32.46, "А теперь ступай." }, { 33.87, "Путь предстоит долгий, впереди тебя ждут испытания." }, { 38.07, "Задание будет выполнено, когда ты вернёшься ко мне с гривой Ледочрева." } }, f = { { 0.00, "Настало время тебе отправиться в далёкие земли." }, { 3.83, "Ты готова к этому путешествию." }, { 6.29, "Тебе поручается убить Ледочрева – йети, живущего в Альтеракских горах." }, { 12.00, "Он отлично маскируется, его белая шкура сливается со снегами его горного обиталища." }, { 18.80, "Увидеть его можно лишь изредка." }, { 21.40, "Но я расскажу тебе, как приманить такое существо, как этот йети." }, { 26.61, "Вот, возьми этот свиток: на нём я написал, как привлечь Ледочрева." }, { 31.89, "А теперь ступай." }, { 33.26, "Путь предстоит долгий, впереди тебя ждут испытания." }, { 37.38, "Задание будет выполнено, когда ты вернёшься ко мне с гривой Ледочрева." } } }, t = { d = 23.4, v = "tauren-male#68", n = { x = 213 }, c = { x = { { 0.00, "Для того, чтобы найти и сразить Ледочрева, нужно обладать силой и смекалкой." }, { 6.90, "Оба эти качества у тебя есть." }, { 9.63, "Твой путь привёл тебя в долины Тысячи Игл и в высокие горы Альтерака." }, { 15.73, "Однажды он проведёт тебя по всем странам матери-земли – ведь именно таков путь охотника." } } } } },
    [1137] = { d = 37.0, v = "orc-male", n = { x = 392 }, c = { x = { { 0.00, "Индарилий обладает невероятной сопротивляемостью нагреву!" }, { 4.46, "Наверняка он подойдёт для поршней Пшикса." }, { 7.65, "Но ему потребуется настоящая индарилиевая руда, а не эти пластинки..." }, { 13.10, "Эту руду нужно добывать в глубине Ульдамана, на северной границе Бесплодных земель, – там её навалом." }, { 21.11, "Передавайте Пшиксу Медноштифу привет и скажите ему всё, о чём я поведал вам." }, { 27.05, "Счастливого пути." }, { 28.47, "Думаю, мы с вами ещё увидимся: как только Пшикс прознает про индарилий, он как пить дать отправит вас в Ульдаман." } } }, t = { d = 7.8, g = 1, v = "gnome-male", n = { m = 78, f = 79 }, c = { m = { { 0.00, "Ты вернулся!" }, { 0.97, "Ты нашёл Мартека?" }, { 2.28, "Вы с ним поговорили?" }, { 3.80, "Что он сказал?" }, { 4.91, "Он поможет?" }, { 5.80, "Говори-говори-говори!!!" } }, f = { { 0.00, "Ты вернулась!" }, { 1.05, "Ты нашла Мартека?" }, { 2.45, "Вы с ним поговорили?" }, { 3.99, "Что он сказал?" }, { 5.11, "Он поможет?" }, { 6.02, "Говори-говори-говори!!!" } } } } },
    [1138] = { d = 42.0, v = "dwarf-male#100", n = { x = 417 }, c = { x = { { 0.00, "Мне нравятся крабы." }, { 1.60, "Крабы – это деликатесные дары моря!" }, { 4.57, "Их можно печь, жарить на гриле, варить, делать из них бульон." }, { 9.50, "Ещё их можно жарить на сковороде, во фритюре и просто жарить." }, { 14.44, "Есть крабовый салат, крабовый суп, краб тушёный, краб перчёный, краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый десерт." }, { 25.03, "Вот и... ну, и всё." }, { 26.48, "Я здесь сейчас рыбу ужу, потому охотиться на сочных крабов мне некогда." }, { 32.29, "Можешь извлечь кусочки отличного мяса из рифовых крабов и покрытых илом крабов." }, { 38.82, "Их можно печь, жарить на гриле, варить..." } } }, t = { d = 21.0, v = "dwarf-male#100", n = { x = 234 }, c = { x = { { 0.00, "Да-а-а, эти кусочки отличного крабьего мяса – как раз то, что мне нужно." }, { 5.05, "Спасибо!" }, { 5.69, "Вот, это я обнаружил как-то, когда рыбачил, и мне оно без надобности." }, { 10.55, "Может быть, ты сможешь как-то это использовать?" }, { 13.90, "В деликатесные блюда из крабов это уж точно не положишь." }, { 17.88, "Я ведь уже рассказывал тебе о крабах, правда?" } } } } },
    [1139] = { d = 33.8, v = "dwarf-male", n = { x = 393 }, c = { x = { { 0.00, "Мы смогли сдержать клан Кузни Теней, отрезав их силы от пика Чёрной горы, но задание Тяжелоступа ещё не выполнено." }, { 8.08, "Его смерть не должна быть напрасной." }, { 10.64, "Он мечтал найти табличку Воли: камень, на котором высекли магические письмена сами титаны, чтобы вдохнуть жизнь в созданных ими существ, – по крайней мере, так гласят легенды." }, { 23.21, "Мы должны заполучить табличку Воли прежде, чем до неё доберётся клан Кузня Теней." }, { 28.92, "Возвращайся в Ульдаман, найди табличку и принеси её мне незамедлительно." } } }, t = { d = 21.7, g = 1, v = "dwarf-male", n = { m = 178, f = 180 }, c = { m = { { 0.00, "*При виде таблички советник Белграм изумлённо качает головой*" }, { 5.12, "Это поразительно!" }, { 6.41, "Я прослежу, чтобы табличка была доставлена королевским магам как можно скорее." }, { 12.10, "Они непременно пожелают проверить, что в легендах истина, а что ложь." }, { 17.02, "Ты помог нашему народу более, чем я смел надеяться!" } }, f = { { 0.00, "*При виде таблички советник Белграм изумлённо качает головой*" }, { 5.04, "Это поразительно!" }, { 6.42, "Я прослежу, чтобы табличка была доставлена королевским магам как можно скорее." }, { 12.50, "Они непременно пожелают проверить, что в легендах истина, а что ложь." }, { 17.75, "Ты помогла нашему народу более, чем я смел надеяться!" } } } } },
    [1140] = { d = 31.3, g = 1, v = "human-male", n = { m = 375, f = 375 }, c = { m = { { 0.00, "Орочьи письмена немногим лучше детских каракулей." }, { 3.46, "Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов." }, { 11.81, "Из каракулей Илкруда можно понять, что у Атрикуса ещё оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса." }, { 24.80, "Поосторожнее там, от вида кровавых храмов сатиров содрогнётся даже такой закалённый герой, как ты." } }, f = { { 0.00, "Орочьи письмена немногим лучше детских каракулей." }, { 3.44, "Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов." }, { 11.74, "Из каракулей Илкруда можно понять, что у Атрикуса ещё оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса." }, { 24.64, "Поосторожнее там, от вида кровавых храмов сатиров содрогнётся даже такая закалённая героиня, как ты." } } }, t = { d = 19.2, v = "human-male", n = { x = 228 }, c = { x = { { 0.00, "Возможно, мы слишком долго терпели сатиров в этом лесу." }, { 3.94, "Я поговорю с Элиссой насчёт этого, когда в другой раз поеду в Аубердин." }, { 8.89, "Тем не менее, раз самоцветы души уничтожены, сила Атрикуса сильно уменьшится." }, { 14.27, "Мы должны воспользоваться этой возможностью и уничтожить его и его культ." } } } } },
    [1141] = { d = 35.8, v = "dwarf-male#100", n = { x = 385 }, c = { x = { { 0.00, "Мне нравится рыбачить." }, { 1.68, "Семья Блумп славится своими рыбаками." }, { 4.51, "Меня зовут Груббер Блумп." }, { 6.46, "Я рыбак." }, { 7.13, "Есть одна рыбка, которую я хотел бы поймать в этих водах – местная разновидность окуня." }, { 13.72, "Я раньше ходил на окуня на лодке, но с тех пор как побережье оккупировали эти противные мурлоки, ни одна лодка в море не выходит." }, { 23.33, "Боюсь, они и окуней всех съедят." }, { 25.82, "Слушай, хочешь помочь мне наловить окуней?" }, { 29.05, "Я б тебе от чистого сердца подарил фамильную удочку семьи Блумп!" }, { 33.89, "Это очень хорошая удочка!" } } }, t = { d = 24.0, g = 1, v = "dwarf-male#100", n = { m = 265, f = 267 }, c = { m = { { 0.00, "Какие отличные окуни!" }, { 1.65, "Большое спасибо за помощь!" }, { 3.62, "Ты как минимум такой же хороший рыбак, как моя драгоценная родственница Граун Блумп." }, { 9.74, "У неё, правда, растёт борода и от неё несёт чем-то странным, но это для неё не причина перестать рыбачить." }, { 17.31, "Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп." } }, f = { { 0.00, "Какие отличные окуни!" }, { 1.69, "Большое спасибо за помощь!" }, { 3.71, "Ты как минимум такая же хорошая рыбачка, как моя драгоценная родственница Граун Блумп." }, { 10.12, "У неё, правда, растёт борода и от неё несёт чем-то странным, но это для неё не причина перестать рыбачить." }, { 17.87, "Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп." } } } } },
    [1142] = { d = 29.9, v = "nightelf-male", n = { x = 254 }, c = { x = { { 0.00, "Мне недолго осталось жить... о, я так слаб..." }, { 3.78, "Хмурен... храбрый дворф, он отправился... предупредить Фалфиндера..." }, { 9.61, "Но прежде, чем я умру..." }, { 11.73, "Пожалуйста, верни моей жене её подвеску... её украл один из этих негодяев..." }, { 18.50, "Подвеска связывает нас... это очень важно..." }, { 22.44, "Пожалуйста, верни подвеску моей Трешале... в Дарнасс..." }, { 27.32, "И расскажи ей... о моей смерти." } } }, t = { d = 21.3, g = 1, v = "nightelf-female#53", n = { m = 197, f = 198 }, c = { m = { { 0.00, "О нет!" }, { 0.53, "Не может быть!" }, { 1.74, "О, я не верю!" }, { 2.87, "О, жестокий мир!" }, { 4.23, "Мне предстоит весь век нести в сердце горе..." }, { 8.00, "Я не позволю делу Гералата погибнуть вместе с ним!" }, { 12.23, "Благодарю тебя за то, что ты проделал этот опасный путь." }, { 16.91, "Но теперь оставь меня." }, { 18.87, "Я оплачу мужа в одиночестве..." } }, f = { { 0.00, "О нет!" }, { 0.52, "Не может быть!" }, { 1.70, "О, я не верю!" }, { 2.82, "О, жестокий мир!" }, { 4.15, "Мне предстоит весь век нести в сердце горе..." }, { 7.85, "Я не позволю делу Гералата погибнуть вместе с ним!" }, { 12.00, "Благодарю тебя за то, что ты проделала этот опасный путь." }, { 16.67, "Но теперь оставь меня." }, { 18.60, "Я оплачу мужа в одиночестве..." } } } } },
    [1143] = { d = 20.1, v = "nightelf-male#55", n = { x = 224 }, c = { x = { { 0.00, "Понятно." }, { 0.65, "Ну если то, о чём ты говоришь, – правда, то сейчас самое время нанести удар." }, { 6.20, "Я уверен, что Атрикус обосновался на самом верху башни." }, { 10.24, "Однако будь начеку, его окружает множество сильных чернокнижников, гораздо более опасных, чем те, с кем тебе доводилось встречаться ранее." } } }, t = { d = 16.0, v = "nightelf-male#55", n = { x = 176 }, c = { x = { { 0.00, "Я надеюсь, что после смерти Атрикуса демонические силы в этом районе отступят." }, { 5.95, "Я не сомневаюсь, что они перегруппируются и вернутся, но тогда мы будем ещё лучше подготовлены, чтобы встретить эту угрозу лицом к лицу." } } } } },
    [1144] = { d = 27.2, v = "goblin-male", n = { x = 290 }, c = { x = { { 0.00, "Наконец-то, помощь пришла!" }, { 2.05, "Ты не представляешь, как долго я уже здесь торчу!" }, { 5.74, "Видишь ли, я предприниматель." }, { 7.93, "Как говорится, всегда ищу выгоду." }, { 10.53, "Вот, прослышал, что Мебок Миззрикс даёт хорошую цену за растущий здесь корень синелиста." }, { 17.16, "Ну я и подумал, что на этом можно обтяпать неплохие денежки." }, { 21.74, "Как видишь, жестоко ошибался!" }, { 24.00, "Вытащи меня отсюда, я тебе хорошо заплачу!" } } }, t = { d = 7.0, v = "goblin-male", n = { x = 54 }, c = { x = { { 0.00, "Уф... спасибо, дружище!" }, { 2.37, "А вот и обещанная награда – за мной не заржавеет!" } } } } },
    [1145] = { d = 38.2, v = "troll-male#78", n = { x = 429 }, c = { x = { { 0.00, "Многие путешественники, приходившие в Перекрёсток, помогали мне собирать яйца на Полях Великанов, а потом рассказывали, какие страшные твари там живут." }, { 11.14, "Мне хватило этих рассказов, чтобы убедиться в том, что мой хозяин недооценил этих насекомых, и что на самом деле они гораздо опаснее." }, { 21.07, "Мне нужен кто-то, кто отправится в Оргриммар и встретится там с Белгромом Каменной Булавой." }, { 27.78, "Это очень серьёзное дело, которое можно поручить только ответственному посыльному." }, { 33.96, "Белгрома почти всегда можно найти у цехового дома воинов." } } }, t = { d = 9.8, v = "orc-male#60", n = { x = 93 }, c = { x = { { 0.00, "А, записка от Коррана." }, { 1.91, "Он служит уже давно и очень преданно." }, { 5.19, "Я как раз собирался узнать, как у него дела в Перекрёстке." } } } } },
    [1146] = { d = 39.4, v = "orc-male#60", n = { x = 421 }, c = { x = { { 0.00, "Значит, Корран пришёл к похожему заключению относительно этих насекомых: они представляют собой гораздо большую угрозу, чем мы думали." }, { 10.48, "Несколько дней назад из Тысячи Игл ко мне вернулся полумёртвый охотник." }, { 15.89, "Его с отрядом отправили на Мерцающую равнину, чтобы выгнать оттуда бригаду дворфов-археологов, но во время боя на месте раскопок появились эти насекомые и чуть было не положили весь отряд." }, { 30.66, "Главным у них был Моктар Крин, и сейчас они разбили лагерь на границе Мерцающей равнины." }, { 37.55, "Отнесите ему это письмо." } } }, t = { d = 34.6, v = "orc-male#60", n = { x = 361 }, c = { x = { { 0.00, "Не обращайте внимания на это грохочущее эхо." }, { 3.54, "Это всего лишь гонка гномов и гоблинов на Равнинах – они носятся на кошмарных машинах, созданных по всем правилам так называемой \"науки\"." }, { 14.31, "Однако в Тысяче Игл есть куда более серьёзные опасности, одна из которых недавно унесла жизни большей части моего отряда." }, { 23.94, "Но мы останемся здесь до тех пор, пока не получим известие от Белгрома из Оргриммара." }, { 30.46, "До этого мы будем держать позицию и стоять на страже." } } } } },
    [1147] = { d = 32.7, v = "orc-male#60", n = { x = 345 }, c = { x = { { 0.00, "Хмм." }, { 0.34, "Значит, Белгром считает этих монстров опасными и хочет, чтобы их загнали в те глубины, из которых они некогда выползли." }, { 9.54, "Ему, значит, недостаточно того, что мы убили всех дворфов из Лиги Исследователей – надо посылать полумёртвый отряд в новый бой!" }, { 19.14, "Сами мы не справимся, по крайней мере в таком состоянии." }, { 23.47, "Карьер находится к югу отсюда, и дворфов там, скорее всего, больше нет." }, { 28.96, "Не хочешь ли помочь нам своим клинком или посохом?" } } }, t = { d = 26.5, g = 1, v = "orc-male#60", n = { m = 270, f = 273 }, c = { m = { { 0.00, "Ха!" }, { 0.28, "Эта лимфа, которой ты покрыт с ног до головы, только красит тебя!" }, { 5.49, "Хотя воняешь ты так, что аж глаза режет..." }, { 8.80, "Не подходи слишком близко к кодо, а то они сбегут или набросятся на тебя." }, { 14.65, "Думаю, мои товарищи согласятся принять этот запах за убедительное доказательство того, что ты помог нам справиться с этими мерзкими насекомыми." }, { 25.85, "Спасибо." } }, f = { { 0.00, "Ха!" }, { 0.28, "Эта лимфа, которой ты покрыта с ног до головы, только красит тебя!" }, { 5.54, "Хотя воняешь ты так, что аж глаза режет..." }, { 8.83, "Не подходи слишком близко к кодо, а то они сбегут или набросятся на тебя." }, { 14.65, "Думаю, мои товарищи согласятся принять этот запах за убедительное доказательство того, что ты помогла нам справиться с этими мерзкими насекомыми." }, { 25.63, "Спасибо." } } } } },
    [1148] = { d = 37.5, v = "narrator", n = { x = 404 }, c = { x = { { 0.00, "Вы тщательно осматриваете панцирь." }, { 2.66, "Повращав его в руках, вы видите, что полоски хитинового покрытия переплетены совершенно неповторимым образом, что делает панцирь невероятно прочным." }, { 14.14, "Вы никогда в жизни не видели ничего подобного." }, { 17.78, "Вы осматриваете останки дальше и понимаете, что эти существа очень сильны и высокоразвиты." }, { 24.79, "Ещё раз взглянув на эти останки, вы думаете, что Коррану было бы интересно обследовать этих существ поподробнее." }, { 33.47, "Это помогло бы ему понять, кто они и откуда взялись." } } }, t = { d = 34.1, v = "troll-male#78", n = { x = 376 }, c = { x = { { 0.00, "О, так вы недавно виделись с Моктаром?" }, { 2.75, "Он всегда заботился обо мне." }, { 4.85, "Жаль слышать, что он тратит своё время на то, чтобы присматривать за своей группой, вместо того чтобы самому участвовать в бою..." }, { 14.23, "Но, думаю, ему нравится убивать членов Лиги Исследователей." }, { 18.62, "Хорошо, что вы принесли мне эти образцы." }, { 21.57, "Мы собрали и другие яйца насекомых на Полях Великанов, так что теперь у меня есть хороший материал для изучения." }, { 29.70, "Скоро я смогу узнать, что это за насекомые и чего они хотят." } } } } },
    [1149] = { d = 44.5, g = 1, v = "tauren-male#68", n = { m = 394, f = 394 }, c = { m = { { 0.00, "Итак, ты нашёл меня – или, возможно, тебя привела сама судьба?" }, { 5.85, "Это неважно." }, { 7.08, "Теперь ты здесь, и перед тобой лежит новый путь." }, { 11.53, "Личность складывается из многих граней: души, тела и разума." }, { 17.13, "Некоторые из этих аспектов определяются культурными традициями, о наличии других мы можем только догадываться." }, { 27.18, "Если согласишься, я испытаю некоторые присущие тебе качества." }, { 32.86, "Если ты пройдёшь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты." }, { 41.02, "Первое испытание – это испытание веры." } }, f = { { 0.00, "Итак, ты нашла меня – или, возможно, тебя привела сама судьба?" }, { 5.72, "Это неважно." }, { 6.91, "Теперь ты здесь, и перед тобой лежит новый путь." }, { 11.20, "Личность складывается из многих граней: души, тела и разума." }, { 16.60, "Некоторые из этих аспектов определяются культурными традициями, о наличии других мы можем только догадываться." }, { 26.28, "Если согласишься, я испытаю некоторые присущие тебе качества." }, { 31.76, "Если ты пройдёшь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты." }, { 39.63, "Первое испытание – это испытание веры." } } }, t = { d = 22.8, g = 1, v = "tauren-male#68", n = { m = 212, f = 215 }, c = { m = { { 0.00, "Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой." }, { 7.21, "Ты поверил в себя, хотя и не был уверен, что выживешь." }, { 11.86, "Твой разум открыт, и твой дух готов встретить всё, что ждёт впереди." }, { 17.59, "Если желаешь, можешь приступить к следующему испытанию." } }, f = { { 0.00, "Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой." }, { 7.29, "Ты поверила в себя, хотя и не была уверена, что выживешь." }, { 12.30, "Твой разум открыт, и твой дух готов встретить всё, что ждёт впереди." }, { 18.10, "Если желаешь, можешь приступить к следующему испытанию." } } } } },
    [1150] = { d = 42.5, v = "tauren-male#68", n = { x = 412 }, c = { x = { { 0.00, "Хорошо, что ты не теряешь смелости несмотря ни на что." }, { 4.45, "Твоя вера крепка, и теперь настало время испытать твою силу." }, { 9.73, "Сначала тебе надо пройти испытание выносливости." }, { 13.88, "Отправляйся в Логово Легкопёрых – оно к западу от Заставы Вольного Ветра." }, { 20.00, "Проберись в самое сердце логова и уничтожь там все запасы еды." }, { 25.28, "К тому времени местные гарпии будут в ярости, и если ты останешься в живых, с тобой прилетит сразиться их предводительница – Гренка Кровавый Визг." }, { 37.50, "Убей её и принеси мне её коготь, чтобы пройти это испытание." } } }, t = { d = 24.2, g = 1, v = "tauren-male#68", n = { m = 218, f = 220 }, c = { m = { { 0.00, "Гренка была очень сильна даже для такого героя как ты." }, { 4.85, "Сегодня ты можешь по праву гордиться собой." }, { 8.68, "Во время испытания веры ты показал силу своего духа, а сегодня подтвердил, что физически ты готов к битве." }, { 17.98, "Гарпии Лёгкого Пера мертвы, и теперь настало время нового испытания." } }, f = { { 0.00, "Гренка была очень сильна даже для такой героини как ты." }, { 4.93, "Сегодня ты можешь по праву гордиться собой." }, { 8.76, "Во время испытания веры ты показала силу своего духа, а сегодня подтвердила, что физически ты готова к битве." }, { 18.30, "Гарпии Лёгкого Пера мертвы, и теперь настало время нового испытания." } } } } },
    [1151] = { d = 41.0, v = "tauren-male#68", n = { x = 400 }, c = { x = { { 0.00, "Во времена Древних богов элементалей можно было встретить повсюду." }, { 5.61, "Они поклонялись Древним богам, а боги своей силой поддерживали связь духов с этим миром." }, { 13.08, "Когда же Древние боги были изгнаны, элементали тоже покинули этот мир и теперь являются сюда только по зову могущественных магов." }, { 24.00, "Но есть и исключения." }, { 25.72, "Некоторые духи были достаточно сильны для того, чтобы остаться в этом мире, и одного из них зовут Рок'Алим." }, { 34.77, "Для того чтобы испытать свою силу, найди в Тысяче Игл Рок'Алима и убей его." } } }, t = { d = 12.5, v = "tauren-male#68", n = { x = 115 }, c = { x = { { 0.00, "Испытание силы пройдено." }, { 2.30, "Вы показали свою силу и храбрость и теперь готовы к последнему испытанию, после которого эти ритуалы завершатся." } } } } },
    [1152] = { d = 33.9, g = 1, v = "tauren-male#68", n = { m = 315, f = 316 }, c = { m = { { 0.00, "Твои испытания почти закончились, но проверку знаний проводить буду не я." }, { 6.47, "Тебе придётся посетить другие места и усвоить там новые уроки." }, { 11.99, "Если ты готов, найди Брауга Тусклый Дух – это очень мудрый шаман." }, { 17.91, "Внимательно выслушай его и выполни всё, что он скажет." }, { 22.64, "Брауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес." }, { 29.50, "И будь осторожен, ночные эльфы могут помешать тебе." } }, f = { { 0.00, "Твои испытания почти закончились, но проверку знаний проводить буду не я." }, { 6.30, "Тебе придётся посетить другие места и усвоить там новые уроки." }, { 11.68, "Если ты готова, найди Брауга Тусклый Дух – это очень мудрый шаман." }, { 17.52, "Внимательно выслушай его и выполни всё, что он скажет." }, { 22.13, "Брауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес." }, { 28.82, "И будь осторожна, ночные эльфы могут помешать тебе." } } }, t = { d = 33.9, v = "tauren-male#68", n = { x = 322 }, c = { x = { { 0.00, "Гоблины терзают землю, ночные эльфы унижают младшие расы, а дни и ночи тем временем становятся всё холоднее и холоднее." }, { 10.28, "Отрёкшиеся и орки – не единственные, кого нужно винить за конфликты, возникшие на землях Калимдора и Лордерона." }, { 19.70, "Многие разумные расы причинили миру немало боли." }, { 24.03, "Дорн знает об этом, и он отправил вас ко мне, потому что вы тоже способны это понять." }, { 31.30, "Сейчас вы стоите перед Браугом." } } } } },
    [1153] = { d = 40.2, g = 1, v = "orc-male", n = { x = 403 }, c = { m = { { 0.00, "Раньше, герой, вы часто помогали мне в разных делах." }, { 4.17, "Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью." }, { 10.67, "По закону чести, я должен рассказать вождю обо всём, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи." }, { 20.56, "Недавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл." }, { 28.20, "Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать." }, { 36.46, "А он мне очень нужен для исследования!" } }, f = { { 0.00, "Раньше, героиня, вы часто помогали мне в разных делах." }, { 4.39, "Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью." }, { 11.01, "По закону чести, я должен рассказать вождю обо всём, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи." }, { 21.09, "Недавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл." }, { 28.87, "Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать." }, { 37.29, "А он мне очень нужен для исследования!" } } }, t = { d = 25.6, g = 1, v = "orc-male", n = { x = 258 }, c = { m = { { 0.00, "Хороший образец." }, { 1.34, "Очень хороший." }, { 2.55, "Вы замечательно справились с заданием, и эти путешественники больше не смогут задирать передо мной нос." }, { 10.55, "Я немедленно начну работать с ней, и если руда окажется достаточно прочной, я изготовлю из неё оружие и отправлю вождю, чтобы он посмотрел на наши успехи." }, { 22.65, "Я не забуду вашей помощи, герой." } }, f = { { 0.00, "Хороший образец." }, { 1.36, "Очень хороший." }, { 2.58, "Вы замечательно справились с заданием, и эти путешественники больше не смогут задирать передо мной нос." }, { 10.69, "Я немедленно начну работать с ней, и если руда окажется достаточно прочной, я