    [1154] = { d = 41.4, g = 1, v = "tauren-male#68", n = { m = 364, f = 364 }, c = { m = { { 0.00, "Ты прошёл испытание Дорна и хочешь пройти следующее?" }, { 4.55, "Что ж, хорошо." }, { 5.80, "Но все предыдущие испытания были детскими играми." }, { 10.12, "Физическую силу испытать легко – то ли дело сила разума!" }, { 15.13, "Ладно, объясню попроще: найди книгу, которую я назову, изучи её и ответь на мой вопрос по её содержимому." }, { 24.31, "Ты спросишь, что за книга?" }, { 26.58, "Она называется \"Наследие Аспектов\"." }, { 29.72, "Её можно найти в глубине обители Дор'Данил, это в южном Ясеневом лесу." }, { 35.99, "Книгу охраняют мёртвые друиды и их убийцы." } }, f = { { 0.00, "Ты прошла испытание Дорна и хочешь пройти следующее?" }, { 4.84, "Что ж, хорошо." }, { 6.15, "Но все предыдущие испытания были детскими играми." }, { 10.67, "Физическую силу испытать легко – то ли дело сила разума!" }, { 15.92, "Ладно, объясню попроще: найди книгу, которую я назову, изучи её и ответь на мой вопрос по её содержимому." }, { 25.52, "Ты спросишь, что за книга?" }, { 27.90, "Она называется \"Наследие Аспектов\"." }, { 31.18, "Её можно найти в глубине обители Дор'Данил, это в южном Ясеневом лесу." }, { 37.75, "Книгу охраняют мёртвые друиды и их убийцы." } } }, t = { d = 15.8, g = 1, v = "tauren-male#68", n = { m = 151, f = 153 }, c = { m = { { 0.00, "Это та самая книга, о которой я говорил." }, { 3.39, "Полагаю, тебе известен ответ на мой вопрос – если только ты не поленился изучить книгу." }, { 10.61, "Как только будешь готов, обратись ко мне, и я задам тебе вопрос." } }, f = { { 0.00, "Это та самая книга, о которой я говорил." }, { 3.24, "Полагаю, тебе известен ответ на мой вопрос – если только ты не поленилась изучить книгу." }, { 10.21, "Как только будешь готова, обратись ко мне, и я задам тебе вопрос." } } } } },
    [1159] = { d = 34.8, g = 1, v = "tauren-male#68", n = { m = 346, f = 347 }, c = { m = { { 0.00, "Отличная работа." }, { 1.34, "Ты прошёл первую часть испытания знаний, но ещё один вопрос остался без ответа." }, { 7.47, "Правда, задавать его буду не я." }, { 10.00, "Поговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей." }, { 19.02, "Он до сих пор стремится к просвещению, но уже по-другому." }, { 23.39, "Он даст тебе задание, и только потом задаст вопрос – но до сих пор ты справлялся хорошо, и, я уверен, трудностей у тебя не возникнет." } }, f = { { 0.00, "Отличная работа." }, { 1.38, "Ты прошла первую часть испытания знаний, но ещё один вопрос остался без ответа." }, { 7.79, "Правда, задавать его буду не я." }, { 10.41, "Поговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей." }, { 19.73, "Он до сих пор стремится к просвещению, но уже по-другому." }, { 24.25, "Он даст тебе задание, и только потом задаст вопрос – но до сих пор ты справлялась хорошо, и, я уверен, трудностей у тебя не возникнет." } } }, t = { d = 26.4, g = 1, v = "scourge-male#83", n = { m = 239, f = 242 }, c = { m = { { 0.00, "Тебя прислал Брауг?" }, { 2.42, "Невероятно." }, { 3.68, "*Парквел критически осматривает вас.*" }, { 6.64, "Справился в Дор'Даниле, прошёл испытание веры и совладал с могущественным элементалем?" }, { 13.60, "Ха!" }, { 13.89, "Да ты, наверное, наслушался разговоров в таверне и теперь нагло врёшь мне!" }, { 19.89, "Думаешь, что сможешь пройти моё испытание?" }, { 23.37, "Ну что ж, хорошо..." }, { 24.92, "Герой." } }, f = { { 0.00, "Тебя прислал Брауг?" }, { 2.47, "Невероятно." }, { 3.76, "*Парквел критически осматривает вас.*" }, { 6.72, "Справилась в Дор'Даниле, прошла испытание веры и совладала с могущественным элементалем?" }, { 14.09, "Ха!" }, { 14.40, "Да ты, наверное, наслушалась разговоров в таверне и теперь нагло врёшь мне!" }, { 20.63, "Думаешь,