    [1160] = { d = 32.4, v = "scourge-male#83", n = { x = 336 }, c = { x = { { 0.00, "Я скажу тебе, что искать, и даже задам вопрос, но не потому, что тебе хочется проявить себя." }, { 7.31, "Знания гораздо важнее силы." }, { 9.56, "Даже если кто-то силой превосходит тебя, твои знания о мире могут оказаться куда полезнее." }, { 16.87, "Отправляйся в монастырь на севере Тирисфальских лесов." }, { 21.09, "В их библиотеке есть книга под названием \"Истоки угрозы нежити\" – по ней ныне обезумевшие паладины учатся истреблять моих собратьев." }, { 31.36, "Принеси её мне." } } }, t = { d = 25.4, g = 1, v = "scourge-male#83", n = { m = 233, f = 236 }, c = { m = { { 0.00, "Это та самая книга, которую я велел тебе найти." }, { 4.64, "*Парквел нежно проводит рукой по обложке, разглядывая её.*" }, { 9.84, "Значит, ты хочешь, чтобы я задал тебе вопрос, чтобы ты мог доказать, что твой дух так же силён, как и тело?" }, { 18.49, "Если ты хорошо изучил книгу, то я задам тебе вопрос, и с испытаниями будет покончено." } }, f = { { 0.00, "Это та самая книга, которую я велел тебе найти." }, { 4.32, "*Парквел нежно проводит рукой по обложке, разглядывая её.*" }, { 9.12, "Значит, ты хочешь, чтобы я задал тебе вопрос, чтобы ты могла доказать, что твой дух так же силён, как и тело?" }, { 17.70, "Если ты хорошо изучила книгу, то я задам тебе вопрос, и с испытаниями будет покончено." } } } } },
    [1164] = { d = 43.2, v = "scourge-female", n = { x = 331 }, c = { x = { { 0.00, "Воровка!" }, { 0.94, "Свинья!" }, { 1.78, "Кената всё ещё жива, её семья живёт и процветает, а я страдаю." }, { 8.15, "Вот уж действительно Отрёкшаяся!" }, { 11.34, "Всю мою семью забрала чума." }, { 14.33, "Всё наше имение тоже разорили во время войны." }, { 19.20, "И теперь она и её мерзкие дети имели наглость похитить у меня последние ценные вещи." }, { 28.20, "Сами вещи мне уже не нужны." }, { 31.20, "Теперь я жажду мести!" }, { 33.54, "Убей этих проходимцев!" }, { 35.97, "Ступай в усадьбу Дабири в Арати, на северо-востоке от Опорного пункта." } } }, t = { d = 24.9, g = 1, v = "scourge-female", n = { m = 206, f = 207 }, c = { m = { { 0.00, "Ты стоишь передо мной, словно посланник Мести, и я склоняюсь в знак признательности." }, { 8.11, "Жирная корова мертва, и я, зная, что её потомки не будут топтать землю Азерота, могу потратить силы на что-нибудь более разумное." }, { 20.90, "Надеюсь, прикончив их, ты ограбил усадьбу?" } }, f = { { 0.00, "Ты стоишь передо мной, словно посланник Мести, и я склоняюсь в знак признательности." }, { 7.80, "Жирная корова мертва, и я, зная, что её потомки не будут топтать землю Азерота, могу потратить силы на что-нибудь более разумное." }, { 20.09, "Надеюсь, прикончив их, ты ограбила усадьбу?" } } } } },
    [1166] = { d = 47.8, g = 1, v = "named/4500", n = { m = 427, f = 427 }, c = { m = { { 0.00, "Твоя кланяться властитель Мок'Морокк!" }, { 3.37, "Рексар назначить меня правителем клана Каменного Молота!" }, { 8.49, "Моя хороший вождь!" }, { 10.18, "Моя бережёт свой клан!" }, { 12.10, "Большие драконы прилетать и жечь наш старый дом." }, { 16.35, "Моя – умный огр!" }, { 17.87, "Моя найти здесь новый дом для свой клан." }, { 21.40, "Бросать старый дом так быстро, что забыть моя вещи." }, { 26.04, "Маленький герой, ты идти и приносить моя вещи." }, { 30.29, "Идти на юг и приносить мой вкусный грог, мой табак и мой сейф." }, { 35.66, "Я благодарить твоя, когда твоя сделать это." }, { 39.67, "Твоя искать в Обители Пламени и в руинах Деревни Каменного Молота." }, { 45.68, "Они быть там, моя уверен." } }, f = { { 0.00, "Твоя кланяться властитель Мок'Морокк!" }, { 3.23, "Рексар назначить меня правителем клана Каменного Молота!" }, { 8.15, "Моя хороший вождь!" }, { 9.77, "Моя бережёт свой клан!" }, { 11.62, "Большие драконы прилетать и жечь наш старый дом." }, { 15.69, "Моя – умный огр!" }, { 17.16, "Моя найти здесь новый дом для свой клан." }, { 20.54, "Бросать старый дом так быстро, что забыть моя вещи." }, { 25.00, "Маленькая героиня, ты идти и приносить моя вещи." }, { 29.23, "Идти на юг и приносить мой вкусный грог, мой табак и мой сейф." }, { 34.39, "Я благодарить твоя, когда твоя сделать это." }, { 38.24, "Твоя искать в Обители Пламени и в руинах Деревни Каменного Молота." }, { 44.01, "Они быть там, моя уверен." } } }, t = { d = 6.4, g = 1, v = "named/4500", n = { m = 49, f = 49 }, c = { m = { { 0.00, "Хороший герой." }, { 1.38, "Моя скучать по этим вещам." }, { 3.89, "Моя теперь дружить с твоя." } }, f = { { 0.00, "Хорошая героиня." }, { 1.54, "Моя скучать по этим вещам." }, { 4.05, "Моя теперь дружить с твоя." } } } } },
    [1167] = { d = 10.4, v = "human-male", n = { x = 137 }, c = { x = { { 0.00, "Прежде чем встретиться с Атрикусом, разумно было бы тебе посоветоваться с Балтулом." }, { 5.29, "Не сомневаюсь, что он неусыпно следил за башней и может знать о недавних событиях." } } }, t = { d = 25.5, g = 1, v = "nightelf-male#55", n = { m = 278, f = 279 }, c = { m = { { 0.00, "А, приятно снова свидеться!" }, { 2.06, "Тут такие странные вещи творились, так что хорошо, что ты снова тут появился!" }, { 7.71, "Очень странные вещи." }, { 9.31, "Всё казалось как обычно – ну, насколько тут вообще всё может быть обычно – и вдруг на верхнем этаже башни как полыхнёт!" }, { 17.89, "Потом начались вопли." }, { 19.55, "Вопли раскалывали воздух, а в землю порой били молнии." }, { 23.67, "Что всё это может значить?" } }, f = { { 0.00, "А, приятно снова свидеться!" }, { 2.04, "Тут такие странные вещи творились, так что хорошо, что ты снова тут появилась!" }, { 7.69, "Очень странные вещи." }, { 9.26, "Всё казалось как обычно – ну, насколько тут вообще всё может быть обычно – и вдруг на верхнем этаже башни как полыхнёт!" }, { 17.74, "Потом начались вопли." }, { 19.38, "Вопли раскалывали воздух, а в землю порой били молнии." }, { 23.45, "Что всё это может значить?" } } } } },
    [1168] = { d = 37.0, v = "named/4502", n = { x = 342 }, c = { x = { { 0.00, "Мок'Морокк получил власть от Рексара." }, { 3.23, "Но он больше любил власть, чем огров." }, { 6.46, "Чёрные драконы убили много огров." }, { 9.46, "Убили жену Тхарга." }, { 11.19, "Мок'Морокк велел нам бежать." }, { 13.71, "Заставил прийти сюда." }, { 15.68, "Огры должны биться." }, { 17.50, "Ограм плохо бегать." }, { 19.31, "Мок'Морокк думает только о Мок'Морокке." }, { 22.78, "Мой дом в руинах Деревни Каменного Молота." }, { 26.48, "Мне нравится там на юге." }, { 28.61, "Здесь не наш дом." }, { 30.03, "Помоги ограм победить войско чёрного дракона." }, { 34.05, "Мы хотим отомстить." }, { 35.78, "Мы хотим домой." } } }, t = { d = 8.2, g = 1, v = "named/4502", n = { m = 57, f = 58 }, c = { m = { { 0.00, "Ты убил многих из войска Чёрного дракона." }, { 4.20, "Ты – отважный герой!" }, { 6.30, "Тхарг счастлив!" } }, f = { { 0.00, "Ты убила многих из войска Чёрного дракона." }, { 4.40, "Ты – отважная героиня!" }, { 6.74, "Тхарг счастлив!" } } } } },
    [1169] = { d = 33.4, g = 1, v = "named/4501", n = { m = 355, f = 356 }, c = { m = { { 0.00, "Пока этот трусливый глупец Мок'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает у него власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас." }, { 16.32, "Почему ты так озадаченно смотришь на меня?" }, { 19.52, "Думал, я буду говорить как неотёсанный чурбан только потому, что я – огр?" }, { 24.96, "Но к делу." }, { 25.78, "Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла." } }, f = { { 0.00, "Пока этот трусливый глупец Мок'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает у него власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас." }, { 16.45, "Почему ты так озадаченно смотришь на меня?" }, { 19.67, "Думала, я буду говорить как неотёсанный чурбан только потому, что я – огр?" }, { 25.22, "Но к делу." }, { 26.04, "Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла." } } }, t = { d = 12.2, v = "named/4501", n = { x = 130 }, c = { x = { { 0.00, "Рискованное было дельце, добывать все эти сердца и языки, а?" }, { 4.68, "Теперь я проникну в глубины тайн, чтобы выяснить, откуда на наш прежний дом свалилась такая напасть." } } } } },
    [1170] = { d = 21.0, v = "named/4501", n = { x = 224 }, c = { x = { { 0.00, "Деревня Каменный Молот была захвачена выводком Ониксии." }, { 4.46, "Но почему дочь великого дракона Смертокрыла вторглась в наши земли?" }, { 9.78, "Вот что тревожнее всего!" }, { 11.69, "Неужели только для того, чтобы уничтожить небольшое поселение огров?" }, { 17.14, "Предупреди Мок'Морокка." }, { 18.99, "Нельзя сидеть сложа руки!" } } }, t = { d = 7.9, v = "named/4500", n = { x = 78 }, c = { x = { { 0.00, "Почему ты говорить с моя про драконы?" }, { 3.11, "Моя не любить драконы." }, { 5.04, "Моя не хотеть здесь никакие драконы." } } } } },
    [1171] = { d = 8.5, v = "named/4500", n = { x = 80 }, c = { x = { { 0.00, "Твоя уходить." }, { 1.27, "Твоя идти и сказать Драз'Зилбу, мы оставаться здесь." }, { 5.87, "Здесь нет никакой чёрный дракон." } } }, t = { d = 23.2, v = "named/4501", n = { x = 235 }, c = { x = { { 0.00, "Жалкий трус!" }, { 1.00, "Мок'Морокк выказывал силу, пока нашим вождём был Рексар." }, { 5.51, "Но после его ухода Мок'Морокк начал сам стремиться к власти." }, { 10.38, "Он предпочитал требовать, вместо того чтобы руководить." }, { 14.82, "Он не заботится о своих подданных, а наоборот хочет, чтобы мы заботились о нём." }, { 21.05, "С этим надо что-то делать!" } } } } },
    [1172] = { d = 33.2, v = "named/4501", n = { x = 346 }, c = { x = { { 0.00, "Выводок Ониксии расползся по всей Земле Драконов." }, { 3.93, "Нельзя допустить, чтобы и остальные её отродья вылупились на свет!" }, { 9.14, "Поспеши в Драконьи топи на юге Пылевых топей." }, { 12.85, "Наверняка она устроила там своё логово." }, { 16.00, "Найди яйца злой драконихи и уничтожь их!" }, { 19.21, "Мы никогда не вернём себе деревню Каменного Молота, если вокруг будут продолжать плодиться драконы." }, { 27.14, "А что касается Мок'Морокка... касательно этого червя у меня есть особые планы." } } }, t = { d = 34.0, v = "named/4501", n = { x = 328 }, c = { x = { { 0.00, "Прекрасно!" }, { 0.90, "Теперь Ониксия не скоро отложит очередную кладку." }, { 5.13, "Благодарю тебя, от имени моего народа." }, { 8.44, "Я уже о многом просил тебя, но, может, ты окажешь последнюю услугу клану Каменного Молота." }, { 16.14, "Мок'Морокк не достоин править нами." }, { 19.15, "Тхарг стал бы отличным вождём, но он стар и изранен." }, { 23.30, "Изгони силой из этих мест Мок'Морокка." }, { 26.54, "Только тогда мы сможем избрать нового вождя, который отведёт нас на родину, в южные земли." } } } } },
    [1173] = { d = 10.6, g = 1, v = "named/4500", n = { m = 100, f = 100 }, c = { m = { { 0.00, "Ты осмеливаешься вызвать на поединок властителя Мок'Морокка?" }, { 4.94, "Ха!" }, { 5.24, "Моя раздавить жалкий герой!" }, { 7.63, "Приготовишься к трёпке – скажи мне." } }, f = { { 0.00, "Ты осмеливаешься вызвать на поединок властителя Мок'Морокка?" }, { 4.98, "Ха!" }, { 5.28, "Моя раздавить жалкая героиня!" }, { 7.85, "Приготовишься к трёпке – скажи мне." } } }, t = { d = 17.8, g = 1, v = "named/4501", n = { m = 178, f = 179 }, c = { m = { { 0.00, "Эта трусливая туша, Мок'Морокк, сбежал как испуганный младенец при виде розги." }, { 6.46, "Ты оказал нам огромную услугу." }, { 8.96, "Теперь мой народ может выбрать себе нового лидера, того, кто поможет восстановить наши жилища и защитить их." } }, f = { { 0.00, "Эта трусливая туша, Мок'Морокк, сбежал как испуганный младенец при виде розги." }, { 6.17, "Ты оказала нам огромную услугу." }, { 8.63, "Теперь мой народ может выбрать себе нового лидера, того, кто поможет восстановить наши жилища и защитить их." } } } } },
    [1175] = { d = 26.7, v = "tauren-male#68", n = { x = 301 }, c = { x = { { 0.00, "После того как гоблинский болид \"Красный Гром\" столкнулся с василиском, Кронкрайдер нанял меня присматривать за трассой." }, { 8.84, "Не знаю, что жрут местные животные, но они вырастают просто огромными, и нужно постоянно отпугивать их, чтобы они не забредали на трек во время гонки." }, { 19.88, "Знаете, что?" }, { 20.81, "Если желаете немного заработать, ступайте и избавьте нас от нескольких василисков." } } }, t = { d = 9.7, v = "tauren-male#68", n = { x = 99 }, c = { x = { { 0.00, "Надеюсь, вы не убивали василисков прямо на трассе?" }, { 4.14, "Здесь тела разлагаются очень долго, а лопатой их убирать замучаешься." } } } } },
    [1176] = { d = 28.3, v = "goblin-male", n = { x = 329 }, c = { x = { { 0.00, "На гонках имеет значение абсолютно всё!" }, { 2.79, "Будь то малейшее изменение мощности, небольшое ослабление колец натяжения или уменьшение веса болида – любую мелочь надо принимать в расчёт." }, { 12.67, "Мы используем в своих болидах кости стервятников – они очень крепкие и лёгкие." }, { 18.18, "К тому же их очень легко найти." }, { 20.46, "Уж чего-чего – а стервятников на Мерцающей равнине хватает." }, { 24.65, "Принеси мне немного костей, и я хорошо заплачу тебе." } } }, t = { d = 5.0, v = "goblin-male", n = { x = 44 }, c = { x = { { 0.00, "Отлично!" }, { 0.85, "Моя команда сейчас же начнёт работу!" }, { 4.35, "Спасибо." } } } } },
    [1177] = { d = 12.1, v = "named/4503", n = { x = 92 }, c = { x = { { 0.00, "Моя – большой огр." }, { 1.89, "Моя голодный." }, { 3.33, "Твоя идти ловить рыба." }, { 5.76, "Твоя принести Дробу еда." }, { 8.38, "Твоя кормить Дроб, или Дроб есть твоя." } } }, t = { d = 4.9, v = "named/4503", n = { x = 37 }, c = { x = { { 0.00, "Моя любить рыбья голова!" }, { 2.66, "Моя пока твоя не есть." } } } } },
    [1178] = { d = 37.3, v = "goblin-male", n = { x = 413 }, c = { x = { { 0.00, "Наша гоночная команда – это гордость всей расы гоблинов!" }, { 4.21, "Вы удивитесь, узнав, что за личности в той или иной мере покровительствуют нашей команде." }, { 10.72, "Знаете Газлоу?" }, { 11.84, "Он собирает для нас детали по всему миру, а однажды даже сам приезжал поработать над одной из наших машин!" }, { 19.60, "Несколько недель назад он пообещал прислать новый топливный регулятор, но посылка пока не пришла." }, { 26.77, "Странно, обычно Газлоу держит своё слово..." }, { 29.99, "Может, вы не прочь съездить в Кабестан и спросить у него?" }, { 34.14, "Я бы не настаивал, но эти гномы нас догоняют!" } } }, t = { d = 22.0, v = "named/3391", n = { x = 250 }, c = { x = { { 0.00, "Вас прислал Поззик?" }, { 1.40, "Когда-то ведь он был одним из самых уважаемых механиков в Нижней шахте, но потом уволился и занялся гонками." }, { 9.01, "Первое, что он сделал, придя в команду, – разработал две новых модели двигателей." }, { 14.72, "Дела Союза ремонтников могут пострадать без Поззика, но ему уже нет до этого дела..." }, { 20.75, "Гонки для него всё!" } } } } },
    [1179] = { d = 33.4, v = "dwarf-male", n = { x = 378 }, c = { x = { { 0.00, "Вы когда-нибудь слышали о Мерцающей равнине?" }, { 3.09, "Это огромное соляное плато в Калимдоре, южнее каньона Тысяча Игл." }, { 7.76, "Это отличное место для гонок, потому что поверхность там совершенно... ну... равнинная!" }, { 13.82, "Там живёт парочка гномов – мои друзья, они строят новый болид, и говорят, он жуть какой быстрый!" }, { 20.63, "Настолько быстрый, что их пилоты то и дело разбиваются и калечатся..." }, { 25.43, "Они заказали у меня несколько защитных шлемов, но у меня дела, и я не могу их отвезти." }, { 31.55, "Может быть, вы мне поможете?" } } }, t = { d = 8.4, v = "gnome-male", n = { x = 80 }, c = { x = { { 0.00, "Ага!" }, { 0.44, "Длиннобородый прислал с вами наши шлемы!" }, { 3.83, "Ур-р-а-а-а!" }, { 4.79, "Осталось уговорить пилота сесть в наш болид..." } } } } },
    [1180] = { d = 25.8, v = "named/3391", n = { x = 294 }, c = { x = { { 0.00, "Вернёмся к делу." }, { 1.15, "Я обещал Поззику привезти новый топливный регулятор, но так и не получил его." }, { 6.67, "Ревилгаз из Пиратской бухты сказал, что выслал его, но, похоже, он куда-то улетучился." }, { 12.83, "Коли так, ничего не попишешь, но по меньшей мере мы можем выяснить, отправляли его или нет." }, { 19.38, "Поговори с управляющим пристанью Подгребаем по ту сторону моря, пусть заглянет в свои записи." } } }, t = { d = 13.3, v = "goblin-male", n = { x = 152 }, c = { x = { { 0.00, "Поставки в Кабестан?" }, { 1.48, "Дай-ка я загляну в записи…" }, { 3.40, "Нет, последний груз, отправленный в Кабестан, если не считать оборудования и припасов, – это сапоги от Дриззлика." }, { 11.37, "Никаких запчастей для гонок." } } } } },
    [1181] = { d = 15.0, v = "goblin-male", n = { x = 171 }, c = { x = { { 0.00, "Боюсь, тут я помочь уже не в силах." }, { 2.56, "Если ты хочешь узнать подробности, поговори с самим бароном." }, { 6.92, "Никто не знает дела Ревилгаза лучше самого Ревилгаза." }, { 10.83, "Он сейчас на верхнем этаже таверны на другой стороне залива." } } }, t = { d = 12.4, v = "goblin-male#180", n = { x = 119 }, c = { x = { { 0.00, "А, разумеется, я понимаю, о чём ты." }, { 2.89, "Нет, помочь не могу." }, { 4.64, "Мои наёмники должны были добыть чертежи топливного регулятора, но вернулись с пустыми руками." } } } } },
    [1182] = { d = 28.6, v = "goblin-male#180", n = { x = 336 }, c = { x = { { 0.00, "Видишь ли, резаки Торговой Компании возле озера Назферити (в северной части Тернистой долины) оборудовали новой моделью топливного регулятора." }, { 9.94, "Я подумал, что Поззик мог бы воспользоваться им, узнай мы, как он устроен." }, { 14.95, "К сожалению, Коззл, тамошний штейгер, оказался несколько умнее, чем я полагал." }, { 20.32, "Может быть, тебе больше повезёт, и удастся получить чертежи." }, { 24.51, "Я знаю, что он хранит их в доме, но скорее всего под замком." } } }, t = { d = 12.2, v = "goblin-male#180", n = { x = 132 }, c = { x = { { 0.00, "А теперь, дай-ка я срисую чертежи для личного пользования, а эти отвези Поззику." }, { 6.02, "Не хотелось бы, чтобы он подумал, будто один из спонсоров оставил его без поддержки." } } } } },
    [1183] = { d = 13.1, v = "goblin-male#180", n = { x = 136 }, c = { x = { { 0.00, "Всё должно быть готово." }, { 1.86, "Передай Поззику мои наилучшие пожелания и скажи, что если ему что понадобится, стоит только попросить." }, { 10.06, "Буду ждать вестей о его новых рекордах!" } } }, t = { d = 14.6, v = "goblin-male", n = { x = 173 }, c = { x = { { 0.00, "Я надеялся, что он прибудет в готовом виде, зато теперь у нас есть уникальная возможность усовершенствовать конструкцию на этапе сборки." }, { 9.66, "Спасибо." }, { 10.31, "Я нарисую план улучшенного регулятора, сделаю его и установлю." } } } } },
    [1184] = { d = 14.9, v = "troll-male#78", n = { x = 149 }, c = { x = { { 0.00, "Вернитесь к Белгрому в Оргриммар и скажите, что Моктар в Тысяче Игл сделает всё, что от него требуется." }, { 8.29, "А ещё скажите, что я постоянно учусь и набираюсь знаний." }, { 12.83, "Он будет рад это услышать." } } }, t = { d = 30.4, g = 1, v = "orc-male#60", n = { x = 307 }, c = { m = { { 0.00, "Я очень ценю ваши усилия, герой." }, { 2.67, "Вождю будет приятно услышать о том, как вы стараетесь для нас." }, { 7.46, "О, разумеется, я назову ему ваше имя!" }, { 10.49, "Он часто говорит со мной и высоко ценит моё мнение." }, { 14.50, "А теперь ступайте, у меня ещё много дел." }, { 17.67, "И если вдруг вы встретитесь с Корраном, и он расскажет вам что-нибудь ещё об этих существах – сразу возвращайтесь ко мне." }, { 26.89, "К этой угрозе нельзя относиться легкомысленно." } }, f = { { 0.00, "Я очень ценю ваши усилия, героиня." }, { 2.68, "Вождю будет приятно услышать о том, как вы стараетесь для нас." }, { 7.23, "О, разумеется, я назову ему ваше имя!" }, { 10.11, "Он часто говорит со мной и высоко ценит моё мнение." }, { 13.92, "А теперь ступайте, у меня ещё много дел." }, { 16.94, "И если вдруг вы встретитесь с Корраном, и он расскажет вам что-нибудь ещё об этих существах – сразу возвращайтесь ко мне." }, { 25.71, "К этой угрозе нельзя относиться легкомысленно." } } } } },
    [1185] = { t = { d = 31.0, g = 1, v = "human-male", n = { m = 305, f = 305 }, c = { m = { { 0.00, "Эй, да это снова ты!" }, { 1.64, "Ну, то есть ты – в смысле!" }, { 3.63, "Да-да, именно ты!" }, { 5.05, "Так, начну-ка сначала!" }, { 6.83, "Та вещь, которую ты нашёл в Силитусе, – это и правда книга." }, { 11.46, "Дневник, написанный на очень древнем наречии языка, который мы сейчас называем дарнасским." }, { 18.65, "На это уйдёт время, но я изучу его очень тщательно." }, { 22.78, "Я подумал, тебе стоит знать: твоя находка чрезвычайно ценна для Круга." }, { 28.41, "Хозяйка логова просто в восторге!" } }, f = { { 0.00, "Эй, да это снова ты!" }, { 1.59, "Ну, то есть ты – в смысле!" }, { 3.53, "Да-да, именно ты!" }, { 4.91, "Так, начну-ка сначала!" }, { 6.64, "Та вещь, которую ты нашла в Силитусе, – это и правда книга." }, { 11.21, "Дневник, написанный на очень древнем наречии языка, который мы сейчас называем дарнасским." }, { 18.20, "На это уйдёт время, но я изучу его очень тщательно." }, { 22.21, "Я подумал, тебе стоит знать: твоя находка чрезвычайно ценна для Круга." }, { 27.68, "Хозяйка логова просто в восторге!" } } } } },
    [1186] = { d = 23.4, v = "goblin-male", n = { x = 279 }, c = { x = { { 0.00, "Мне сейчас нужно приспособить этот новый регулятор топлива на один из наших болидов, но если вы хотите ещё немного помочь нашей команде, поговорите с Раззериком." }, { 11.05, "Это наш пилот, – гм, наш восемнадцатый пилот, если точнее, – и он тоже любит вносить в болид всяческие усовершенствования." }, { 19.34, "Он, правда, малость двинутый, так что не удивляйтесь, если что." } } }, t = { d = 12.8, v = "goblin-male", n = { x = 139 }, c = { x = { { 0.00, "Это ведь вы помогали Поззику, правда?" }, { 2.77, "Когда-то я тоже бегал по пит-лейну и выполнял мелкие поручения механиков." }, { 8.19, "А теперь – взгляните на меня!" }, { 10.37, "Я – лучший пилот команды гоблинов!" } } } } },
    [1187] = { d = 34.2, v = "goblin-male", n = { x = 382 }, c = { x = { { 0.00, "Поззик – отличный механик, это я знаю, но он боится просто прибавить мощности и вырваться вперёд!" }, { 7.06, "А вот я не боюсь." }, { 8.30, "После того как он закончит работать с болидом, я внесу кое-какие изменения от себя: немного ослаблю ограничители, сниму кое-какие детальки с корпуса и добавлю побольше топлива!" }, { 21.24, "Я заказал сефориевый ускоритель у Шрива." }, { 24.18, "Он работает в Гизмориуме, в Прибамбасске, но дирижабль, на котором летел мой ускоритель, разбился в Пылевых топях!" }, { 32.35, "А мне он нужен, как воздух!" } } }, t = { d = 12.8, v = "goblin-male", n = { x = 137 }, c = { x = { { 0.00, "Ты только глянь на эту красотищу!" }, { 2.56, "Пятнадцать фунтов чистой сефориевой силы!" }, { 5.82, "Как только я прицеплю это к своему болиду, он понесётся так, что я обгоню гномов на два круга!" } } } } },
    [1188] = { d = 19.2, v = "goblin-male", n = { x = 220 }, c = { x = { { 0.00, "Постойте-ка, что это?" }, { 1.56, "Шрив оставил включённым режим безопасности." }, { 4.62, "Но это же ограничит мощность, которую я смогу выжать из этого ускорителя!" }, { 9.97, "Говорил же я ему, чтобы отключил!" }, { 12.44, "Плохо, плохо." }, { 13.48, "Вам придётся отнести это в Гизмориум Прибамбасска и заставить Шрива всё отключить!" } } }, t = { d = 20.4, v = "goblin-male", n = { x = 263 }, c = { x = { { 0.00, "Только Раззерик мог по одному взгляду определить, что я поставил сюда предохранитель." }, { 5.63, "Этот ускоритель почти полностью состоит из взрывчатого сефория." }, { 9.88, "Я модифицировал его так, что его мощность будет увеличиваться по мере использования, но Раззерик ведь не успокоится, пока не взорвётся вместе со своим драндулетом!" } } } } },
    [1189] = { d = 18.6, v = "goblin-male", n = { x = 222 }, c = { x = { { 0.00, "Вот, я сделал то, что просил Раззерик." }, { 2.59, "Но скажите ему, чтобы он действовал как можно осторожнее: если он допустит хотя бы малейшую ошибку, болид не покатится вперёд, а превратится в кучку пепла на треке." }, { 13.83, "А нам бы совсем не хотелось искать потом девятнадцатого по счёту пилота!" } } }, t = { d = 10.0, v = "goblin-male", n = { x = 111 }, c = { x = { { 0.00, "Так-то лучше!" }, { 1.04, "Вот бы увидеть рожи гномов, когда я стартую на этой малышке!" }, { 5.46, "Жалко, что я буду так занят установлением нового рекорда трассы!" } } } } },
    [1190] = { d = 25.0, v = "goblin-male", n = { x = 305 }, c = { x = { { 0.00, "Братья Медноштиф изобрели новый материал для изготовления машин – это единственное разумное объяснение." }, { 7.13, "Их машины ездят быстрее прежнего, но их внешний вид и все остальные параметры ничуть не изменились." }, { 13.88, "Мы точно знаем, что Риззл Медноштиф никогда не расстаётся с чертежами своего изобретения." }, { 19.90, "Я скажу Замеку, чтобы устроил диверсию, – тогда ты сможешь выкрасть планы." } } }, t = { d = 6.7, v = "narrator", n = { x = 79 }, c = { x = { { 0.00, "Свиток испещрён торопливыми пометками и рисунками, касающимися переработки какого-то сырья." } } } } },
    [1191] = { t = { d = 0.9, v = "goblin-male", n = { x = 6 }, c = { x = { { 0.00, "Вперёд!" } } } } },
    [1192] = { t = { d = 7.2, v = "goblin-male", n = { x = 82 }, c = { x = { { 0.00, "Замечательно!" }, { 1.05, "Моя команда немедленно начнёт работу с необходимыми деталями для следующей гонки!" } } } } },
    [1193] = { t = { d = 17.8, v = "narrator", n = { x = 197 }, c = { x = { { 0.00, "Ториевое устройство беспрепятственно встаёт на место, создавая канал, в который нужно влить масло льда." }, { 7.76, "Как только последние капли масла падают в канал, западня готова к работе." }, { 13.46, "И горе неосторожному огру, который подойдёт слишком близко!" } } } } },
    [1194] = { d = 23.6, v = "narrator", n = { x = 266 }, c = { x = { { 0.00, "В чертежах Риззла описывается процесс переработки индарилиевой руды." }, { 5.16, "Из его каракулей можно понять, что эта руда добывается в недрах Ульдамана в Бесплодных землях." }, { 12.35, "Остальные записи посвящены жаростойкости индарилия." }, { 16.22, "Пачка бумаг придавлена каким-то камнем – скорее всего, это и есть необработанная индарилиевая руда." } } }, t = { d = 21.5, v = "goblin-male", n = { x = 236 }, c = { x = { { 0.00, "Индарилий?" }, { 0.82, "Интересно..." }, { 1.77, "Если он действительно способен выдерживать такой жар, то мне понятно, почему гномы в последнее время так прибавили." }, { 10.43, "Большое спасибо за этот образец, он мне очень пригодится." }, { 14.79, "Я проведу с ним кое-какие испытания, но для настоящего дела мне потребуется гораздо больше." } } } } },
    [1195] = { d = 35.2, v = "tauren-male#68", n = { x = 372 }, c = { x = { { 0.00, "Кентавры племени Галак в Тысяче Игл хранят один предмет, сохранившийся ещё со времён сотворения кентавров." }, { 8.14, "Нам бы хотелось его получить, но для этого нужен фиал воды из одного из лунных колодцев ночных эльфов." }, { 16.14, "Чтобы набрать воды, тебе надо сначала добыть один из фиалов дриад, что живут близ Приюта в Ночных Лесах в сердце Ясеневого леса." }, { 26.30, "Лунный колодец есть у западного берега реки Фалфаррен, к югу от главной дороги, у которой ты сможешь наполнить фиал." } } }, t = { d = 9.7, v = "tauren-male#68", n = { x = 83 }, c = { x = { { 0.00, "Хорошо." }, { 0.73, "Это как раз то, что просил Рау." }, { 3.58, "Ты можешь отнести ему фиал?" }, { 6.18, "Тебе понравится в Иглах, честное слово!" } } } } },
    [1196] = { d = 18.3, v = "tauren-male#68", n = { x = 193 }, c = { x = { { 0.00, "Отнеси наполненный фиал Рау Скальному Бегуну на Заставу Вольного Ветра на юго-востоке Тысячи Игл." }, { 7.81, "Туда ты можешь добраться на Великом подъёмнике, что возле южного обрыва Степей." }, { 14.07, "Не удивлюсь, если ты и в дальнейшем будешь нам помогать." } } }, t = { d = 17.8, v = "tauren-male#68", n = { x = 176 }, c = { x = { { 0.00, "Хм, да, этот фиал очень пригодится для наших целей." }, { 4.40, "Поскольку дриады и кентавры происходят от одного корня, вода лунных колодцев поможет нам пробить брешь в стене неугасимого огня, что окружает реликвию кентавров." } } } } },
    [1197] = { d = 33.7, g = 1, v = "tauren-male#68", n = { m = 358, f = 360 }, c = { m = { { 0.00, "Водой, которую ты принёс, можно будет затушить пламя, охраняющее реликвию кентавров." }, { 6.61, "Однако оно погаснет лишь ненадолго, так что тебе придётся поспешить." }, { 11.89, "Утёс Треснувшего Копыта – крепость кентавров – находится к северу отсюда." }, { 17.58, "Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утёса." }, { 23.21, "Будь осторожен – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность." } }, f = { { 0.00, "Водой, которую ты принесла, можно будет затушить пламя, охраняющее реликвию кентавров." }, { 6.72, "Однако оно погаснет лишь ненадолго, так что тебе придётся поспешить." }, { 11.91, "Утёс Треснувшего Копыта – крепость кентавров – находится к северу отсюда." }, { 17.52, "Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утёса." }, { 23.05, "Будь осторожна – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность." } } }, t = { d = 16.6, v = "tauren-male#68", n = { x = 159 }, c = { x = { { 0.00, "От этого копыта исходит странная энергия..." }, { 3.79, "Не сомневаюсь, что при его изучении мы узнаем много нового о кентаврах." }, { 9.91, "Благодарю вас." }, { 11.14, "Я немедленно приступлю к разгадке тайны, которую вы принесли мне." } } } } },
    [1198] = { d = 33.5, v = "nightelf-male#55", n = { x = 397 }, c = { x = { { 0.00, "В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса." }, { 8.24, "Я должен собрать как можно больше сведений для Серебряного Рассвета, чтобы мы могли понять, где и когда нужна наша помощь." }, { 16.93, "Уже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине." }, { 23.84, "Страж Талрид из ордена Серебряного Рассвета до сих пор не вернулся." }, { 28.46, "Другие мои разведчики заняты насущными делами." }, { 31.82, "Помоги мне найти Талрида." } } }, t = { d = 8.6, v = "nightelf-male#54", n = { x = 95 }, c = { x = { { 0.00, "Хорошо, что Рассветный дозорный Шедласс прислал вас." }, { 4.08, "В этом испоганенном месте и правда затевается коварный план." } } } } },
    [1199] = { d = 36.6, v = "nightelf-male#54", n = { x = 417 }, c = { x = { { 0.00, "Черпая силу из старинных обрядов, посвящённых Древним Богам Хаоса, Сумеречный Молот пытается вернуть своих тёмных покровителей и распространить смерть и ужас по всему миру." }, { 12.69, "Мы думаем, что Сумеречный Молот в союзе с нагами, и теперь они накапливают силы в Непроглядной Пучине на побережье Ясеневого леса." }, { 22.37, "Что бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться." }, { 28.71, "Объяви же войну Молоту и вернись с доказательствами своих подвигов!" }, { 33.72, "Твои труды будут достойно вознаграждены." } } }, t = { d = 10.6, v = "nightelf-male#54", n = { x = 99 }, c = { x = { { 0.00, "Нет сомнений – в тебе течёт отважная и благородная кровь." }, { 5.07, "Серебряный Рассвет благодарит тебя за содействие силам добра." } } } } },
    [1200] = { d = 36.8, v = "nightelf-male#54", n = { x = 371 }, c = { x = { { 0.00, "Силы оставили меня." }, { 1.67, "Мне необходима твоя помощь!" }, { 3.93, "В давние времена на этом месте был храм Элуны." }, { 7.71, "К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный Лунный колодец." }, { 17.39, "Аку'май, слуга Древнего бога, поднялся из глубин." }, { 21.46, "Сектанты Сумеречного Молота объединились с нагами в борьбе за эти земли." }, { 27.35, "Сектанты, ведомые Келрисом, приносят Аку'май невинные жертвы." }, { 32.37, "Убей Келриса и принеси его голову Сельгорму в Дарнасс." } } }, t = { d = 22.4, g = 1, v = "human-male", n = { m = 243, f = 246 }, c = { m = { { 0.00, "Келрису много раз удавалось ускользнуть от нас." }, { 3.63, "Мне кажется, он стоял за всем злом, происходящим в этих землях." }, { 8.28, "Положив конец его власти, ты спас жизнь многих." }, { 11.85, "Во имя Света!" }, { 12.93, "Нет прощенья тем, кто приносит невинные жертвы Древнему Богу!" }, { 17.52, "Ты совершил великий подвиг." }, { 19.60, "Серебряный Рассвет этого не забудет." } }, f = { { 0.00, "Келрису много раз удавалось ускользнуть от нас." }, { 3.57, "Мне кажется, он стоял за всем злом, происходящим в этих землях." }, { 8.21, "Положив конец его власти, ты спасла жизнь многих." }, { 11.98, "Во имя Света!" }, { 13.06, "Нет прощенья тем, кто приносит невинные жертвы Древнему Богу!" }, { 17.63, "Ты совершила великий подвиг." }, { 19.79, "Серебряный Рассвет этого не забудет." } } } } },
    [1201] = { d = 37.3, v = "orc-male", n = { x = 420 }, c = { x = { { 0.00, "Орда с Альянсом сейчас находятся в состоянии шаткого перемирия." }, { 4.69, "Тайные операции предпринимаются обеими сторонами, и наша обязанность – убедиться что Орда выйдет из них победителем!" }, { 13.16, "Сейчас у нас есть шанс это сделать." }, { 15.74, "Агенты Альянса заняли позицию к востоку от Деревни Гиблотопь." }, { 20.30, "Они следят за деревней и докладывают о наших действиях в районе Терамора." }, { 25.72, "Мы не станем этого терпеть." }, { 27.77, "Твоя задача выследить этих шпионов и убить их." }, { 31.28, "Этим мы ясно дадим понять их начальству, что не допустим шпионить у себя под носом." } } }, t = { d = 9.0, v = "orc-male", n = { x = 78 }, c = { x = { { 0.00, "Отличная работа." }, { 1.68, "Их шпионы хитроумны, но недостаточно, чтобы спастись от всевидящих глаз Орды." } } } } },
    [1202] = { d = 28.0, v = "orc-male", n = { x = 280 }, c = { x = { { 0.00, "Мы посылали двоих разведчиков украсть бумаги с корабля в одном из тераморских доков." }, { 6.84, "Они добыли их, но были обнаружены, и им пришлось выбросить добычу в море." }, { 12.80, "Одному из них удалось сбежать, но поднять документы со дна он не смог." }, { 18.33, "Теперь я поручаю эту задачу тебе." }, { 21.17, "Бумаги лежат в сундучке, на дне моря возле тераморских доков." }, { 26.19, "Найди их, и принеси мне." } } }, t = { d = 6.8, g = 1, v = "orc-male", n = { m = 55, f = 56 }, c = { m = { { 0.00, "Браво." }, { 0.69, "Это было нелегко, но документы, которые ты добыл – весьма ценны." } }, f = { { 0.00, "Браво." }, { 0.66, "Это было нелегко, но документы, которые ты добыла – весьма ценны." } } } } },
    [1203] = { d = 26.0, v = "human-male", n = { x = 292 }, c = { x = { { 0.00, "Мне предстоит жестокая рубка." }, { 2.09, "С кем, я тебе сказать не могу, но вот то, что мне для этого просто необходим добрый клинок, это к гадалке не ходи." }, { 10.09, "Некоторые называют его палашом лунной стали, а я зову пляшущий клинок." }, { 15.17, "Поможешь мне, а?" }, { 16.31, "Может, где в городе найдёшь, а может, кузнец какой согласится его сделать." }, { 21.57, "Главное, поторопись, то что я собираюсь рубить, ждать не станет..." } } }, t = { d = 16.6, v = "human-male", n = { x = 150 }, c = { x = { { 0.00, "Это хороший клинок..." }, { 1.87, "Он хорошо танцует, – стал быть, это – хороший танцующий клинок!" }, { 7.12, "Спасибо-спасибо-спасибо!!!" }, { 9.37, "Таак." }, { 9.89, "Теперь я его испробую..." }, { 11.99, "Позже." }, { 12.59, "Я испробую его позже." }, { 14.47, "Но всё равно спасибо тебе!" } } } } },
    [1204] = { d = 36.3, g = 1, v = "human-male", n = { x = 408 }, c = { m = { { 0.00, "Я тут работаю над новым блюдом, оно будет называться \"Суп из илистой черепахи с жучками\"." }, { 6.34, "Мне всё ещё не хватает основных ингредиентов, но я не уверен, что перенесу ещё одну прогулку по Пылевым топям." }, { 14.03, "Путник, ты не окажешь мне услугу?" }, { 16.41, "Прежде всего, мне нужны языки илистых черепах." }, { 19.80, "Они водятся на побережье, в основном вокруг залива." }, { 23.52, "Но мне не всякие языки сгодятся – я слышал, что у некоторых из этих черепах языки раздвоены." }, { 30.06, "Вот они-то и обладают тем непередаваемым вкусом, которым я хочу порадовать своих клиентов." } }, f = { { 0.00, "Я тут работаю над новым блюдом, оно будет называться \"Суп из илистой черепахи с жучками\"." }, { 6.08, "Мне всё ещё не хватает основных ингредиентов, но я не уверен, что перенесу ещё одну прогулку по Пылевым топям." }, { 13.46, "Путница, ты не окажешь мне услугу?" }, { 15.79, "Прежде всего, мне нужны языки илистых черепах." }, { 19.05, "Они водятся на побережье, в основном вокруг залива." }, { 22.61, "Но мне не всякие языки сгодятся – я слышал, что у некоторых из этих черепах языки раздвоены." }, { 28.88, "Вот они-то и обладают тем непередаваемым вкусом, которым я хочу порадовать своих клиентов." } } }, t = { d = 15.5, v = "human-male", n = { x = 185 }, c = { x = { { 0.00, "Отлично!" }, { 0.63, "Благодарю тебя!" }, { 1.77, "Теперь надо подумать, как именно приготовить эти языки, чтобы наилучшим образом подчеркнуть их изысканный вкус." }, { 9.59, "Наконец-то у меня есть блюдо, достойное завсегдатаев \"Синего отшельника\" в Штормграде." } } } } },
    [1205] = { d = 26.9, g = 1, v = "tauren-male#68", n = { m = 255, f = 255 }, c = { m = { { 0.00, "Зыбун – старый кроколиск из Пылевых топей." }, { 3.63, "Ему давно уже пора сдохнуть." }, { 6.20, "Скрипя старыми костями он волочёт свою огромную тушу по болоту." }, { 11.58, "Хотя он всё ещё движется с силой и скоростью молодого животного, его неугасимый пламенный дух уже износил своё дряхлое тело." }, { 22.02, "Ты должен освободить его от этой боли." }, { 25.35, "Дай ему покой." } }, f = { { 0.00, "Зыбун – старый кроколиск из Пылевых топей." }, { 3.69, "Ему давно уже пора сдохнуть." }, { 6.30, "Скрипя старыми костями он волочёт свою огромную тушу по болоту." }, { 11.75, "Хотя он всё ещё движется с силой и скоростью молодого животного, его неугасимый пламенный дух уже износил своё дряхлое тело." }, { 22.35, "Ты должна освободить его от этой боли." }, { 25.73, "Дай ему покой." } } }, t = { d = 9.8, v = "tauren-male#68", n = { x = 85 }, c = { x = { { 0.00, "Отлично." }, { 0.86, "Я уверен – это было нелёгкое испытание, но я рад, что мучения кроколиска наконец-то прекратились." } } } } },
    [1206] = { d = 29.2, v = "human-male", n = { x = 308 }, c = { x = { { 0.00, "Глазной сок очень вкусный, жаль только что большинство живых существ имеет всего по два глаза." }, { 7.22, "Но вот у пауков их уже больше, гораздо больше." }, { 10.79, "А сок из глаз пауков Мглистой пещеры обладает особенным мягким вкусом." }, { 16.15, "Целёхонькие паучьи глазки... прям уже чую их на языке." }, { 20.28, "Эти пауки водятся в пещере к западу отсюда." }, { 23.71, "Вот как ты думаешь, это пауки были названы по своей пещере или наоборот?" } } }, t = { d = 21.6, g = 1, v = "human-male", n = { m = 191, f = 193 }, c = { m = { { 0.00, "Ты принёс вкусные глазки..." }, { 2.35, "Паучьи глаза чисты как слеза." }, { 5.01, "Их едят, а они глядят…" }, { 7.04, "Вот те, что глядят, съешь последними, а то на болотах-то другой компании и нет." }, { 13.70, "Привет, глазки мои маленькие, привет!" }, { 17.06, "На вкус лучше курочки, с солью, с приправками..." }, { 21.21, "Ммм..." } }, f = { { 0.00, "Ты принесла вкусные глазки..." }, { 2.43, "Паучьи глаза чисты как слеза." }, { 4.94, "Их едят, а они глядят…" }, { 6.86, "Вот те, что глядят, съешь последними, а то на болотах-то другой компании и нет." }, { 13.12, "Привет, глазки мои маленькие, привет!" }, { 16.29, "На вкус лучше курочки, с солью, с приправками..." }, { 20.20, "Ммм..." } } } } },
    [1218] = { d = 16.6, v = "human-male", n = { x = 166 }, c = { x = { { 0.00, "Люблю болотную кухню." }, { 1.82, "Жареные лягушачьи лапки и всё такое..." }, { 4.96, "И чтобы готовить, мне нужны специи." }, { 7.88, "Ароматные специи." }, { 9.34, "Тогда я смогу сделать славное жаркое, да и тебя угостить." }, { 14.09, "Ты как насчёт тушёной лягушатинки?" } } }, t = { d = 5.1, v = "human-male", n = { x = 42 }, c = { x = { { 0.00, "Ага, вот и специи." }, { 1.85, "Вот теперь жабятина вполне готова." } } } } },
    [1219] = { d = 15.8, v = "narrator", n = { x = 150 }, c = { x = { { 0.00, "Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку." }, { 7.19, "А в трубке находился заляпанный грязью пергамент." }, { 11.44, "Донесение написано на орочьем..." }, { 14.22, "И по виду важное..." } } }, t = { d = 6.2, v = "human-male#50", n = { x = 42 }, c = { x = { { 0.00, "Хм..." }, { 0.58, "Я не силён в орочьем, но это похоже... на отчёт шпиона!" } } } } },
    [1220] = { d = 17.9, v = "human-male#50", n = { x = 211 }, c = { x = { { 0.00, "Капитан Ваймс должен увидеть найденное тобой орочье донесение." }, { 4.44, "Он знает орочий язык, лучше, чем кто-либо из нас, и он должен быть осведомлён о том, что вблизи Терамора рыщут шпионы Орды." }, { 12.99, "Ты найдёшь капитана в казармах в северо-восточной части острова Терамор." } } }, t = { d = 8.6, v = "human-male", n = { x = 95 }, c = { x = { { 0.00, "Донесение орочьего шпиона!" }, { 1.95, "Как тебе удалось его раздобыть?" }, { 4.29, "Впрочем, неважно, – давай-ка посмотрим, о чём там говорится..." } } } } },
    [1221] = { d = 32.8, v = "goblin-male", n = { x = 360 }, c = { x = { { 0.00, "Корень синелиста – признанный деликатес в любом уголке мира!" }, { 4.58, "Но растёт он только здесь, в Степях, глубоко под землёй в Лабиринтах Иглошкурых." }, { 10.38, "К тому же клубни так сложно найти, если не знать точно где искать!" }, { 15.36, "Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землёй." }, { 21.96, "Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!" }, { 27.29, "Задачка, конечно, непростая, но если принесёшь мне корней, я хорошо заплачу." } } }, t = { d = 9.1, v = "goblin-male", n = { x = 89 }, c = { x = { { 0.00, "Прекрасно!" }, { 0.92, "О, я загоню их перекупщикам за очень хорошую цену!" }, { 5.21, "Спасибо за работу." }, { 6.82, "Ты вполне надёжный поставщик!" } } } } },
    [1222] = { d = 31.0, g = 1, v = "human-male", n = { m = 357, f = 358 }, c = { m = { { 0.00, "Ура!" }, { 0.35, "Наконец-то нашёлся кто-то, кто не хочет меня съесть!" }, { 3.69, "Не могу отбиться от тутошнего зверья, а ты, парень, как раз мне в этом и поможешь." }, { 8.96, "Повар Морган Штерн составляет рецепт нового блюда, и он послал меня сюда на поиски листьев болотного боба." }, { 15.99, "Он, похоже, думает, что они вкусные." }, { 18.39, "Как бы то ни было, пока я искал эти самые листья... меня окружили!" }, { 22.79, "Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать эти бобы!" } }, f = { { 0.00, "Ура!" }, { 0.37, "Наконец-то нашёлся кто-то, кто не хочет меня съесть!" }, { 3.84, "Не могу отбиться от тутошнего зверья, а ты, подруга, как раз мне в этом и поможешь." }, { 9.39, "Повар Морган Штерн составляет рецепт нового блюда, и он послал меня сюда на поиски листьев болотного боба." }, { 16.71, "Он, похоже, думает, что они вкусные." }, { 19.21, "Как бы то ни было, пока я искал эти самые листья... меня окружили!" }, { 23.78, "Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать эти бобы!" } } }, t = { d = 17.7, v = "human-male", n = { x = 226 }, c = { x = { { 0.00, "Мистер Игнац не так давно приносил листья болотного боба, и он рассказал мне, что вы помогли ему выбраться из весьма затруднительной ситуации." }, { 9.20, "Благодарю вас." }, { 10.14, "Я попрошу своего дядю принять вас по-королевски, когда вы в следующий раз окажетесь в \"Синем отшельнике\", в Штормграде." } } } } },
    [1238] = { d = 25.3, v = "narrator", n = { x = 264 }, c = { x = { { 0.00, "Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку." }, { 6.76, "А в трубке находился заляпанный грязью пергамент." }, { 10.75, "Это донесение шпиона, который провёл многие недели в Тераморе." }, { 15.84, "Расшифровав его, мы выяснили, что это донесение должно быть доставлено командиру орков-разведчиков в Деревню Гиблотопь." } } }, t = { d = 17.4, v = "orc-male", n = { x = 167 }, c = { x = { { 0.00, "Отлично." }, { 0.76, "Наш агент Марг Ночной Соглядатай был отправлен на разведку в Терамор." }, { 6.52, "Это его последний рапорт и, видимо, уже окончательно последний – судя по твоим словам, я боюсь, Марг навсегда остался в болотах..." } } } } },
    [1239] = { d = 10.8, v = "narrator", n = { x = 101 }, c = { x = { { 0.00, "Стоило копнуть чуть глубже, и из земли показалась отрубленная голова орка." }, { 6.40, "На его лице застыл оскал, а в тёмных глазах – вызов." } } }, t = { d = 20.6, v = "orc-male", n = { x = 198 }, c = { x = { { 0.00, "Это голова Марга Ночного Соглядатая!" }, { 3.05, "Этого-то я и боялся." }, { 4.72, "Посмотри на эту рану у него на шее, – как думаешь, это какое-то оружие, или он пал от клыков и когтей какого-то зверя?" }, { 14.39, "Мы должны выяснить это." }, { 16.35, "Выяснить, не является ли его смерть делом рук Альянса." } } } } },
    [1240] = { d = 24.2, v = "orc-male", n = { x = 259 }, c = { x = { { 0.00, "Мы должны выяснить обстоятельства смерти Марга!" }, { 3.68, "И единственный способ это сделать, – воспользоваться магией троллей." }, { 8.96, "Отнеси голову Марга Кин'вилаю в лагерь Гром'гол в Тернистой долине." }, { 14.24, "Кин'вилай – самый могущественный из знахарей племени Чёрного Копья, если кто-то и сможет вызвать дух Ночного Соглядатая – то это он." } } }, t = { d = 12.4, v = "troll-male#77", n = { x = 110 }, c = { x = { { 0.00, "Да, теперь я вижу." }, { 1.65, "Дух Марга застрял в нашем мире, потому что его задание не было завершено." }, { 8.16, "Ну что ж, давай поговорим с этим сердитым орком..." } } } } },
    [1241] = { d = 34.8, v = "human-male", n = { x = 416 }, c = { x = { { 0.00, "Некоторое время назад один из наших дипломатов был отправлен в Терамор для встречи с Джайной Праудмур." }, { 7.38, "Он не вернулся." }, { 8.43, "Я подозреваю, что к этому приложило руку Братство Справедливости, но уверенности у меня пока что нет." }, { 15.31, "Пока что нам удаётся скрывать факт исчезновения дипломата, но так продолжаться не может." }, { 21.19, "Агенты королевской службы рыщут по городам, но я хочу задействовать и свои связи." }, { 26.83, "В Аллее Героев вы найдёте моего старого друга, его зовут Йорген." }, { 31.35, "Передайте ему эту записку и во всём его слушайтесь." } } }, t = { d = 22.0, v = "human-male#50", n = { x = 226 }, c = { x = { { 0.00, "Хм-м..." }, { 1.28, "*Йорген смотрит на вас, прищурившись.*" }, { 4.40, "Хорошо." }, { 5.00, "Придётся вам помочь, хоть и не очень-то хочется." }, { 8.47, "Долг есть долг." }, { 9.54, "И запомните одну простую вещь: вы знаете куда больше, чем уместно в вашем случае." }, { 15.61, "Храните наши маленькие секреты и не болтайте по тавернам о том, что обнаружите." }, { 21.41, "Ясно вам?" } } } } },
    [1242] = { d = 22.4, v = "human-male#50", n = { x = 248 }, c = { x = { { 0.00, "Возьмите записку для Иллинга Триаса." }, { 2.74, "Ничего ему не рассказывайте, просто ведите себя вежливо и дождитесь ответа; не волнуйтесь, Триас ответит." }, { 10.64, "Ещё раз напоминаю вам: дело серьёзное, так что держите рот на замке." }, { 15.52, "Триаса вы найдёте в его магазине в Торговом квартале; магазин называется \"Сыры Триаса\"." }, { 22.01, "Удачи!" } } }, t = { d = 18.4, v = "human-male#50", n = { x = 185 }, c = { x = { { 0.00, "Извините, письмо мне?" }, { 1.67, "О... не так уж часто мне приходится получать что-то, кроме ящиков и бочонков, я ведь занят делом." }, { 9.14, "Ну, давайте посмотрим, что там." }, { 11.44, "*Открывая письмо, Иллинг смотрит на вас.*" }, { 15.04, "Вы выглядите возбуждённо, с вами всё в порядке?" } } } } },
    [1243] = { d = 34.8, v = "human-male#50", n = { x = 428 }, c = { x = { { 0.00, "Йорген, ах ты старый мерзавец..." }, { 2.17, "Ну и что со всем этим делать?" }, { 4.10, "Ладно, я разберусь..." }, { 5.55, "Да чтоб ему в Круговерть Пустоты угодить раньше времени!" }, { 9.35, "Ну что, займёмся делом?" }, { 10.86, "Я задействую все свои контакты, но вам придётся побегать." }, { 14.60, "Отправляйтесь в поселение Темнолесье, которое находится в Сумеречном лесу, и найдите там дозорного Бакуса; он обычно патрулирует северную дорогу за городской стеной." }, { 25.59, "Просто скажите ему, что Братство Справедливости опять зашевелилось, а вы присматриваете за ним по моей просьбе – и он вам поможет, чем сможет." } } }, t = { d = 16.2, v = "human-male", n = { x = 191 }, c = { x = { { 0.00, "Вас послал Триас, да?" }, { 1.46, "Другое дело..." }, { 2.49, "Можете гонять чудовищ, сколько вам заблагорассудится." }, { 6.08, "Уверен, что для вас это не составит особого труда, какой бы ужас ни вылез на вас из сумерек..." }, { 12.41, "Так чего же желает мой дорогой друг в этот пасмурный день?" } } } } },
    [1244] = { d = 28.2, v = "human-male", n = { x = 332 }, c = { x = { { 0.00, "Опять братство?!" }, { 1.17, "Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой." }, { 7.54, "Кстати, сейчас я вспомнил, что последнюю пару недель их агенты так и кишат вокруг участка Эддла." }, { 14.21, "Это подозрительно – должно быть, назревает какая-то крупная заварушка." }, { 19.03, "Не хотите порыскать там и установить, в чём же дело?" }, { 22.55, "Ферма находится к югу от дороги из Западного Края как раз на входе в Сумеречный лес." } } }, t = { d = 19.6, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Вы вернулись, не вляпавшись ни в какие неприятности." }, { 3.70, "Это само по себе достижение, не правда ли?" }, { 6.82, "Ну, покажите, что принесли?" }, { 8.77, "Да, очень похоже на официальные документы Братства Справедливости." }, { 13.51, "Но это может быть и подделкой, которую вам подсунули, чтобы одурачить и сбить со следа." } } } } },
    [1245] = { d = 26.6, v = "human-male", n = { x = 297 }, c = { x = { { 0.00, "О-ох, для обычной попытки ввести в заблуждение это слишком сложно." }, { 4.77, "Отнесите этот документ Триасу, пусть поразмыслит над ним." }, { 8.77, "И никому больше об этом не говорите." }, { 11.38, "Кажется, это дело ни мне, ни ему не по плечу." }, { 14.62, "Ну, посмотрим..." }, { 15.77, "И, пожалуйста, никому не говорите, что я вам помог." }, { 19.33, "Если моё начальство поймёт, что я о чём-то узнал и не поделился с ними, они могут меня запросто повесить." } } }, t = { d = 15.0, v = "human-male#50", n = { x = 148 }, c = { x = { { 0.00, "Да-а... весьма интересно." }, { 2.06, "Йорген и Делавей молодцы, что навели меня на это." }, { 6.03, "Кажется, Братство Справедливости всерьёз взялось за воплощение своих планов." }, { 11.99, "Хм, а это что?" }, { 13.12, "\"Кулак\"?" }, { 13.83, "Знакомое имя..." } } } } },
    [1246] = { d = 32.2, v = "human-male#50", n = { x = 383 }, c = { x = { { 0.00, "Вот что я об этом думаю..." }, { 1.74, "Дашель..." }, { 2.39, "Какой-то Дашель..." }, { 3.65, "Как его фамилия?" }, { 4.79, "Кулак!" }, { 5.27, "Дашель Каменный Кулак!" }, { 6.82, "В некоторых кругах его зовут просто Кулак, наверняка потому, что он не дурак подраться..." }, { 12.81, "Его можно найти в Старом городе, прямо в центре." }, { 16.16, "Поговорите с ним." }, { 17.30, "Если понадобится, используйте меч или любой подручный тяжёлый предмет, чтобы урезонить его, и не сомневайтесь." }, { 24.60, "Если он так завязан в заговоре, как можно заключить по этим бумагам, то не расстанется с информацией по доброй воле..." } } }, t = { d = 6.2, v = "dwarf-male", n = { x = 63 }, c = { x = { { 0.00, "Что?!" }, { 0.43, "Мои дела тебя не касаются, ясно?" }, { 3.12, "Проваливай, нечего тебе здесь вынюхивать!" } } } } },
    [1247] = { d = 24.0, v = "dwarf-male", n = { x = 258 }, c = { x = { { 0.00, "Ну... м-м... да..." }, { 1.25, "Я кое-что знаю о встрече на участке Эддла." }, { 4.41, "Она произошла несколько недель назад." }, { 7.24, "Меня туда не приглашали, моё участие закончилось с провалом плана А, проклятие этим окаянным приключенцам..." }, { 15.13, "Парень, с которым связан план Б, пришёл из Менетила." }, { 18.88, "Его зовут Пронырой." }, { 20.40, "Это всё, что мне удалось узнать из запасного плана." } } }, t = { d = 27.0, v = "human-male#50", n = { x = 320 }, c = { x = { { 0.00, "О, приятно видеть вас в живых." }, { 2.07, "Значит, с Дашелем всё прошло хорошо?" }, { 4.56, "Я тут ещё раз перечитал их планы, и хотя в тексте не упоминается имя дипломата, которого они преследовали, речь идёт о плане Б, который вступил в действие после провала первой попытки захватить его." }, { 17.86, "Этот Проныра, о котором упомянул Дашель, кажется, не имеет другого имени – непонятно, кто он; но нам хотя бы известно, что он из Менетила." } } } } },
    [1248] = { d = 33.3, v = "human-male#50", n = { x = 411 }, c = { x = { { 0.00, "Один из моих знакомых переехал в Болотину, в портовый город Менетил." }, { 4.60, "Думаю, что он поможет вам, если вы передадите ему привет и скажете, что работаете на меня." }, { 10.58, "Зовут его Михаил; перед отъездом он говорил, что хочет стать барменом." }, { 15.30, "Поговорите с ним, найдите этого Проныру и попробуйте разузнать ещё что-нибудь насчёт похищенного дипломата." }, { 22.30, "Мы должны узнать, где его держат или хотя бы имя похищенного." }, { 26.48, "Увы, в декларации ничего не говорится о том, что похитители собираются сделать с пленником после захвата." } } }, t = { d = 23.3, g = 1, v = "human-male", n = { m = 239, f = 239 }, c = { m = { { 0.00, "Привет-привет, дорогой путник." }, { 2.36, "Рады вас видеть." }, { 3.65, "Не желаете ли эля?" }, { 5.06, "Или баранины?" }, { 6.14, "Скажите, чего бы вам хотелось, и я постараюсь выполнить все ваши пожелания." }, { 11.75, "Меня зовут Михаил, я буду рад услужить вам." }, { 15.06, "Э?" }, { 15.26, "Что это?" }, { 15.93, "Триас?" }, { 16.47, "Прошу вас, говорите потише." }, { 18.57, "Моим посетителям не обязательно слышать, о чём мы с вами говорим." } }, f = { { 0.00, "Привет-привет, дорогая путница." }, { 2.41, "Рады вас видеть." }, { 3.68, "Не желаете ли эля?" }, { 5.08, "Или баранины?" }, { 6.15, "Скажите, чего бы вам хотелось, и я постараюсь выполнить все ваши пожелания." }, { 11.70, "Меня зовут Михаил, я буду рад услужить вам." }, { 14.98, "Э?" }, { 15.18, "Что это?" }, { 15.85, "Триас?" }, { 16.38, "Прошу вас, говорите потише." }, { 18.45, "Моим посетителям не обязательно слышать, о чём мы с вами говорим." } } } } },
    [1249] = { d = 32.8, v = "human-male", n = { x = 373 }, c = { x = { { 0.00, "Значит, вас послал Иллинг?" }, { 1.95, "О, это повод десятикратно умножить моё гостеприимство!" }, { 5.86, "Просите всего, чего пожелаете, постараюсь выполнить любую вашу просьбу!" }, { 11.13, "Хм-м, Проныра, говорите?" }, { 12.89, "Не скажу, что мне знакомо это имя, но постараюсь что-нибудь разведать..." }, { 18.10, "Не оборачивайтесь прямо сейчас, но вон тот господин около двери слишком внимательно смотрит на нас и прислушивается к нашему разговору." }, { 27.74, "На вашем месте я бы попробовал изловить его прежде, чем он уйдёт отсюда." } } }, t = { d = 33.0, v = "human-male", n = { x = 396 }, c = { x = { { 0.00, "Поймали его, да?" }, { 1.15, "Отлично!" }, { 1.76, "Знаете, а ведь это и есть тот самый Проныра!" }, { 4.72, "Я и сам удивился." }, { 5.87, "Да, не думал я, что буду так скучать по всяким тайным расследованиям и азартным погоням." }, { 11.75, "Верно говорят: сколько волка ни корми..." }, { 14.53, "Только не обмолвитесь про это Иллингу – он наверняка потащит меня обратно в Штормград, узнав, что я затосковал по былым денькам." }, { 23.13, "Хорошо, что мне удалось оказать вам хотя бы небольшую услугу во время вашего пребывания в Менетиле." }, { 29.79, "Если ещё что-нибудь понадобится, просто попросите." } } } } },
    [1250] = { d = 35.4, v = "human-male#50", n = { x = 407 }, c = { x = { { 0.00, "Братство Справедливости не столько мне платит, чтобы за них умирать." }, { 4.59, "Они похитили короля." }, { 6.05, "Да, настоящего короля Штормграда, а не какого-то там дипломата." }, { 10.27, "Он направлялся в Терамор, чтобы побеседовать с Джайной Праудмур, это большая тайна и дело тоже нешуточное." }, { 18.52, "Но дело не только в Братстве." }, { 20.53, "Они работают с кем-то ещё – думаю, понимали, что им это не по зубам." }, { 25.18, "В мои задачи входило только взять их человека на борт королевского корабля, когда он стоял у пристани." }, { 32.09, "Парня звали Хендел, клянусь, это всё, что я знаю!" } } }, t = { d = 32.4, v = "human-male", n = { x = 372 }, c = { x = { { 0.00, "КОРОЛЬ?!" }, { 0.61, "В смысле... король?" }, { 1.96, "Настоящий король?" }, { 3.19, "Вы шутите?" }, { 3.93, "Вы же не имеете в виду, что вы разыскиваете похитителей короля?!" }, { 8.23, "Я даже не в курсе, что он пропал." }, { 10.50, "Теперь ясно, почему сейчас в Штормграде всем заправляет его сын." }, { 14.92, "Я прямо сейчас напишу Иллингу." }, { 17.07, "Он должен знать, что вы встали на след." }, { 19.65, "Мне и в голову не приходило, что Джан может предать наш Штормград за деньги, пусть и немалые." }, { 25.85, "Даже у вора должна быть честь!" }, { 27.94, "Теперь главное – найти этого Хендела – думаю, тут я могу помочь..." } } } } },
    [1251] = { d = 13.2, v = "narrator", n = { x = 126 }, c = { x = { { 0.00, "Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остове камина – только это и осталось от таверны \"Последний привал\"." }, { 11.96, "Щит можно снять." } } }, t = { d = 15.3, v = "orc-male", n = { x = 162 }, c = { x = { { 0.00, "Люди всегда отличались странными вкусами в области украшательства." }, { 5.31, "Но на кой вешать над камином простой металлический щит?" }, { 9.62, "Может, его повесили туда те, кто спалил таверну?" }, { 13.57, "Предупреждение?" }, { 14.79, "Угроза?" } } } } },
    [1252] = { d = 15.4, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Солнечный зайчик блеснул в глаза из-под обломков." }, { 4.12, "Вы достаёте из-под мусора бляху с золотым якорем на белой эмали – символом Терамора." }, { 11.03, "Под якорем выбито имя владельца: \"Лейтенант Павал Рит\"." } } }, t = { d = 17.0, v = "human-male", n = { x = 180 }, c = { x = { { 0.00, "День, когда мне приносят бляхи погибших стражей, светлым не назовёшь." }, { 5.06, "Иногда они гибнут в битве, и мне приходится сообщать об их участи семье и близким..." }, { 11.32, "Иногда мы так и не знаем, что с ними сталось." }, { 14.66, "А иногда знаем, и это ещё хуже..." } } } } },
    [1253] = { d = 13.1, v = "narrator", n = { x = 128 }, c = { x = { { 0.00, "Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остатках камина – только это и осталось от таверны \"Последний привал\"." }, { 11.90, "Щит можно снять." } } }, t = { d = 8.6, v = "human-male", n = { x = 84 }, c = { x = { { 0.00, "Хмм..." }, { 0.52, "Я в устройстве оружия и доспехов не разбираюсь, я ими пользуюсь." }, { 5.76, "Щит как щит, разве что огнём опалило." } } } } },
    [1258] = { d = 31.8, v = "human-male", n = { x = 352 }, c = { x = { { 0.00, "Ещё один компонент моего нового рецепта – клешни гигантского краба." }, { 4.95, "К сожалению, те, которые водятся в Пылевых топях, – грязнокрабы, не годятся..." }, { 10.55, "Зато те, что живут на Болоте Печали, – в самый раз!" }, { 14.27, "Оболочка клешни – важный элемент украшения блюда, поэтому они мне нужны целые и непоцарапанные." }, { 21.24, "К сожалению, у краба всего две клешни, а то и одна, а мне для моих кулинарных экспериментов их нужно гораздо больше." }, { 29.57, "Так что насчёт небольшой прогулки?" } } }, t = { d = 13.2, v = "human-male", n = { x = 138 }, c = { x = { { 0.00, "Прекрасные экземпляры." }, { 1.78, "На самих клешнях ни царапинки, а мясо как и положено, розовое и нежное." }, { 7.39, "У вас несомненный талант к этому делу!" }, { 10.44, "Не задумывались о карьере шеф-повара?" } } } } },
    [1259] = { d = 16.6, v = "human-male", n = { x = 201 }, c = { x = { { 0.00, "Лейтенант Павал Рит?" }, { 1.43, "Не припоминаю такого имени." }, { 3.37, "Лучше всего вам будет поговорить с адъютантом Тезораном." }, { 7.30, "У него хранятся все записи о тераморских стражниках – от их имён до предпочитаемого вооружения." }, { 13.73, "Уж он-то расскажет вам об этом Павале Рите." } } }, t = { d = 7.3, v = "human-male#50", n = { x = 84 }, c = { x = { { 0.00, "Здравствуй." }, { 0.82, "Так тебе нужна информация об одном из нас?" }, { 3.81, "Как его бишь, Рит?" }, { 5.08, "Сейчас проверю по своим записям." } } } } },
    [1260] = { d = 29.1, g = 1, v = "human-male", n = { m = 348, f = 348 }, c = { m = { { 0.00, "Я составляю новое меню для ресторана." }, { 2.58, "Сельская кухня с болотным душком." }, { 4.92, "Думаю, посетителям \"Синего отшельника\" понравится!" }, { 8.36, "Я послал своего племянника Моргана в Терамор, город на краю Пылевых топей." }, { 13.52, "Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи." }, { 19.18, "Долог путь до Терамора, и для меня тяжеловат." }, { 22.25, "Но я думаю, что такой молодой герой с радостью ухватится за возможность совершить подобное путешествие." } }, f = { { 0.00, "Я составляю новое меню для ресторана." }, { 2.53, "Сельская кухня с болотным душком." }, { 4.82, "Думаю, посетителям \"Синего отшельника\" понравится!" }, { 8.19, "Я послал своего племянника Моргана в Терамор, город на краю Пылевых топей." }, { 13.25, "Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи." }, { 18.79, "Долог путь до Терамора, и для меня тяжеловат." }, { 21.80, "Но я думаю, что такая молодая героиня с радостью ухватится за возможность совершить подобное путешествие." } } }, t = { d = 11.8, v = "human-male", n = { x = 125 }, c = { x = { { 0.00, "А!" }, { 0.21, "Так вас послал мой дядя?" }, { 2.07, "Ну что ж, я тут собирал для него рецепты и добился определённых успехов, но мне нужна помощь." }, { 9.03, "Надеюсь, вы не боитесь ноги промочить?" } } } } },
    [1261] = { d = 42.4, g = 1, v = "orc-male", n = { m = 414, f = 414 }, c = { m = { { 0.00, "Ах ты, проклятый грязнокраб!" }, { 2.31, "Ты меня не достанешь!" }, { 4.09, "Ой, да я ж покойник!" }, { 5.73, "Видать, он всё-таки достал меня." }, { 8.41, "А как же моя миссия?!" }, { 10.19, "Ты, должен закончить её." }, { 12.20, "Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора." }, { 17.93, "На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить." }, { 27.82, "Той ночью я пробрался в лагерь и украл эту подвеску." }, { 32.21, "Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня!" }, { 38.76, "Ты должен найти эту тварь и вернуть подвеску." } }, f = { { 0.00, "Ах ты, проклятый грязнокраб!" }, { 2.29, "Ты меня не достанешь!" }, { 4.07, "Ой, да я ж покойник!" }, { 5.70, "Видать, он всё-таки достал меня." }, { 8.36, "А как же моя миссия?!" }, { 10.13, "Ты, должна закончить её." }, { 12.13, "Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора." }, { 17.83, "На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить." }, { 27.67, "Той ночью я пробрался в лагерь и украл эту подвеску." }, { 32.03, "Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня!" }, { 38.54, "Ты должна найти эту тварь и вернуть подвеску." } } }, t = { d = 15.4, g = 1, v = "orc-male", n = { m = 143, f = 144 }, c = { m = { { 0.00, "Эта подвеска была на солдате Штормграда??" }, { 3.50, "Благодарю тебя, за то, что раскрыл загадку смерти Марга." }, { 8.20, "Но эта подвеска..." }, { 9.76, "Это новая загадка." }, { 11.40, "И, возможно, она несёт угрозу и Орде и Альянсу." } }, f = { { 0.00, "Эта подвеска была на солдате Штормграда??" }, { 3.54, "Благодарю тебя, за то, что раскрыла загадку смерти Марга." }, { 8.36, "Но эта подвеска..." }, { 9.94, "Это новая загадка." }, { 11.60, "И, возможно, она несёт угрозу и Орде и Альянсу." } } } } },
    [1262] = { d = 33.8, v = "orc-male", n = { x = 367 }, c = { x = { { 0.00, "Странно, что подвеска, украденная Маргом, была у простого солдата." }, { 5.03, "Возможно её владелец маскировался, или, что вероятнее, солдаты сами её стащили." }, { 11.01, "Что бы там ни было, эта подвеска принадлежала лицу благородного происхождения, и мы должны найти её хозяина, если хотим разрешить эту загадку." }, { 21.74, "Отнеси эту подвеску Зору Одинокое Дерево в Оргриммар." }, { 25.89, "Он хорошо разбирается в интригах Альянса и, возможно, он в курсе, если эта подвеска известна в Штормграде." } } }, t = { d = 19.1, v = "orc-male", n = { x = 190 }, c = { x = { { 0.00, "Эта подвеска сделана удивительно тонкой и искусной работы." }, { 4.97, "Мне такое не нужно, но многие люди головы бы не пожалели за такую драгоценность." }, { 11.67, "Я изучу эту подвеску повнимательнее." }, { 14.76, "Будем надеяться что в своё время мы всё про неё узнаем." } } } } },
    [1264] = { d = 33.4, v = "human-male", n = { x = 389 }, c = { x = { { 0.00, "В начале каждого месяца стражи бухты Кул-Тираса получают жалованье и отправляются прочь из Терамора в отпуск." }, { 7.62, "Многие из них приходят сюда – выпить, гульнуть, пообщаться с женщинами." }, { 12.60, "Одна из таких компаний регулярно приходит в эту таверну." }, { 16.63, "Мне кажется, что и этот Хендел был среди них." }, { 19.77, "Командир Самаул из Терамора может вам помочь в поисках Хендела, если тот до сих пор там." }, { 25.88, "Самаул всецело верен леди Джайне, но если вы упомянете при нём имя Иллинга, он должен стать... посговорчивее." } } }, t = { d = 30.5, v = "human-male#50", n = { x = 343 }, c = { x = { { 0.00, "Рад встрече." }, { 0.91, "Я – командир Самаул, командую войсками леди Джайны Праудмур здесь, в Тераморе." }, { 6.79, "Хотя я немного занят, вы можете задавать мне любые вопросы, которые вас интересуют." }, { 12.82, "Не сочтите за повод для обиды, но я попрошу вас высказаться по возможности лаконично." }, { 18.84, "Надеюсь, что вы проявите должную осторожность, если соберётесь за пределы города." }, { 24.61, "Там, снаружи – огры, орки и мурлоки, а в южной части болота обитают чёрные драконы." } } } } },
    [1265] = { d = 29.4, v = "human-male#50", n = { x = 346 }, c = { x = { { 0.00, "Хендел?" }, { 0.55, "Да, я его знаю, но почему вас интересуют мои солдаты?" }, { 4.23, "Иллинг отправил вас разыскать его?" }, { 6.61, "Звучит как-то странно." }, { 8.21, "Иллинг не послал бы вас ко мне, если бы всё было в порядке." }, { 12.19, "Вы можете хранить свои секреты сколько угодно, только имейте в виду: мой долг – охранять эти земли." }, { 19.05, "Если ваша деятельность может нарушить порядок, лучше сообщите заранее." }, { 23.95, "Думаю, что Хендела вы найдёте в первой по счёту от Терамора башне." }, { 28.36, "Будьте осторожны." } } }, t = { d = 22.2, v = "human-male", n = { x = 253 }, c = { x = { { 0.00, "Человека, известного вам как Хендел, здесь нет." }, { 3.15, "Всё остальное, что можно узнать от леди Праудмур, я думаю, вы уже знаете." }, { 8.90, "Она просила меня найти вас и оказать вам помощь в расследовании." }, { 13.34, "Если вы готовы принять мои услуги, я сообщу вам, где можно найти рядового Хендела." }, { 19.08, "Вдвоём мы сможем предать его в руки правосудия." } } } } },
    [1266] = { d = 27.1, v = "human-male", n = { x = 327 }, c = { x = { { 0.00, "Рядовой Хендел находится к западу отсюда, в составе гвардии, охраняющей тераморских разведчиков во время отдыха." }, { 7.49, "Они следят за базой Орды, деревней Гиблотопь, и высматривают всё, что может угрожать нашим границам." }, { 14.20, "Вы найдёте его без труда, просто поищите в палатках у дороги." }, { 18.27, "У меня есть и другие дела, но я догоню вас так быстро, как смогу." }, { 22.59, "При необходимости вы сможете найти меня в башне леди Праудмур." } } }, t = { d = 22.5, v = "human-male", n = { x = 263 }, c = { x = { { 0.00, "Добрый день." }, { 0.88, "Это опасное место для горожанина." }, { 3.27, "Если вы цените свою жизнь, не стоит находиться здесь слишком долго." }, { 7.98, "Задавайте вопросы быстро, попробую вам помочь." }, { 11.25, "Только смотрите по сторонам, не покажутся ли огры." }, { 14.77, "По слухам, поблизости база Орды." }, { 17.09, "Разведчики пытаются найти её, но это дело небыстрое." }, { 20.80, "Мы ещё не добились успеха." } } } } },
    [1267] = { t = { d = 33.8, v = "human-female#167", n = { x = 399 }, c = { x = { { 0.00, "Сначала позвольте вас, поблагодарить за всё, что вы уже сделали." }, { 4.51, "Вы оказали неоценимую услугу моим людям и всем обитателям Штормграда." }, { 9.48, "Жаль, что наше знакомство не состоялось при более благоприятных обстоятельствах." }, { 15.09, "Надеюсь, вы понимаете, что я не имею возможности публично выразить вам свою признательность, но знайте, что она поистине безгранична..." }, { 24.63, "Во время следующего визита в Терамор разыщите меня, и я постараюсь держать вас в курсе событий." }, { 31.47, "Позвольте ещё раз поблагодарить вас." } } } } },
    [1268] = { d = 13.4, v = "narrator", n = { x = 138 }, c = { x = { { 0.00, "Цепочка следов уходит от всё ещё дымящегося остова таверны \"Последний привал\"." }, { 6.32, "В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчётливо." } } }, t = { d = 26.9, v = "orc-male", n = { x = 240 }, c = { x = { { 0.00, "Следы копыт..." }, { 1.31, "Это может быть иглогрив, или даже кентавр." }, { 5.08, "То, что они пришли в Степи, что-то да значит, и, сдаётся мне, они вполне способны сжечь таверну." }, { 13.25, "К тому же кто бы это ни был, они не только сожгли здание, жена и детёныш владельца были убиты." }, { 21.34, "Плохо дело..." }, { 22.57, "Ладно, я пошлю Кагоро посмотреть куда ведут следы." } } } } },
    [1269] = { d = 15.4, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Солнечный зайчик блеснул в глаза из-под обломков." }, { 4.10, "Вы достаёте из-под мусора бляху с золотым якорем на белой эмали – символом Терамора." }, { 10.98, "Под якорем выбито имя владельца: \"Лейтенант Павал Рит\"." } } }, t = { d = 20.6, v = "orc-male", n = { x = 206 }, c = { x = { { 0.00, "Я знаю этого человека, Павала Рита." }, { 3.02, "Жалкий даже по меркам собственного племени." }, { 6.63, "Покинул своих товарищей и теперь скрывается в лесу." }, { 10.91, "Я послал Огрона выследить его." }, { 13.49, "Некоторые подозревают, что он крал припасы." }, { 16.95, "Я видел что Огрон направляется на юго-восток." } } } } },
    [1270] = { d = 35.9, g = 1, v = "human-male", n = { m = 424, f = 425 }, c = { m = { { 0.00, "Ура!" }, { 0.36, "Наконец-то нашёлся кто-то, кто не хочет меня съесть!" }, { 3.81, "Не могу отбиться от тутошнего зверья, а ты, парень как раз мне в этом и поможешь." }, { 9.18, "Гоблину из Кабестана по кличке Мебок Миззрикс нужны листья болотного боба для зелья или ещё какой надобности, – меня это, честно говоря, не колышет: он неплохо платит, а я неплохо знаю болота, потому и впрягся." }, { 23.44, "Вот только не успел я ещё найти эти листья, как меня уже окружили." }, { 27.97, "Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать для Мебока эти листья." } }, f = { { 0.00, "Ура!" }, { 0.36, "Наконец-то нашёлся кто-то, кто не хочет меня съесть!" }, { 3.77, "Не могу отбиться от тутошнего зверья, а ты, подруга как раз мне в этом и поможешь." }, { 9.16, "Гоблину из Кабестана по кличке Мебок Миззрикс нужны листья болотного боба для зелья или ещё какой надобности, – меня это, честно говоря, не колышет: он неплохо платит, а я неплохо знаю болота, потому и впрягся." }, { 23.30, "Вот только не успел я ещё найти эти листья, как меня уже окружили." }, { 27.79, "Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать для Мебока эти листья." } } }, t = { d = 17.0, g = 1, v = "goblin-male", n = { m = 195, f = 197 }, c = { m = { { 0.00, "Вонючка недавно приносил тут мне травки, и он рассказал, что ты помог ему выпутаться из мерзкой ситуации." }, { 7.39, "Хорошая работа!" }, { 8.54, "Друг Вонючки и мой друг." }, { 10.19, "Перед тем как вернуться обратно на болота, он просил передать тебе это, если мы вдруг увидимся." } }, f = { { 0.00, "Вонючка недавно приносил тут мне травки, и он рассказал, что ты помогла ему выпутаться из мерзкой ситуации." }, { 7.53, "Хорошая работа!" }, { 8.68, "Друг Вонючки и мой друг." }, { 10.34, "Перед тем как вернуться обратно на болота, он просил передать тебе это, если мы вдруг увидимся." } } } } },
    [1271] = { t = { d = 16.2, g = 1, v = "human-male", n = { m = 177, f = 180 }, c = { m = { { 0.00, "Мой племянник говорит, что ты помог ему с исследованиями в Пылевых топях и выручил его помощника из передряги." }, { 8.09, "Что ж, мы, Штерны, держимся друг за друга и не забываем друзей!" }, { 12.66, "Так что мой руки, – мы закатываем пир в твою честь!" } }, f = { { 0.00, "Мой племянник говорит, что ты помогла ему с исследованиями в Пылевых топях и выручила его помощника из передряги." }, { 8.19, "Что ж, мы, Штерны, держимся друг за друга и не забываем друзей!" }, { 12.70, "Так что мой руки, – мы закатываем пир в твою честь!" } } } } },
    [1273] = { d = 17.4, v = "named/4983", n = { x = 168 }, c = { x = { { 0.00, "Это было непросто, но я всё-таки нашёл этот Рит." }, { 3.92, "Неплохо он прятаться..." }, { 5.84, "Для человек." }, { 6.87, "Огрон боится, что человек свихнуться, – слишком много времени на болоте." }, { 12.86, "Твоя идти с Огрон и спрашивать человека всё, что хотеть." } } }, t = { d = 18.4, v = "orc-male", n = { x = 183 }, c = { x = { { 0.00, "Пфф." }, { 0.37, "Это хорошо, что Рит больше не будет прятаться на болоте, но это плохо, что люди такие хрупкие существа, что могут помереть от одной маленькой стрелы." }, { 12.56, "Сдаётся мне, что мы зашли в тупик и нужно поискать разгадку где-нибудь ещё." } } } } },
    [1274] = { d = 23.0, g = 1, v = "child-male", n = { m = 272, f = 274 }, c = { m = { { 0.00, "Простите, сэр." }, { 1.01, "Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства." }, { 10.26, "Если вы без лишнего шума проберётесь в Крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь." }, { 18.32, "Прошу вас, храните это в тайне, ибо всё это дело большой важности." } }, f = { { 0.00, "Простите, мадам." }, { 1.16, "Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства." }, { 10.11, "Если вы без лишнего шума проберётесь в Крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь." }, { 17.91, "Прошу вас, храните это в тайне, ибо всё это дело большой важности." } } }, t = { d = 23.9, v = "human-male", n = { x = 272 }, c = { x = { { 0.00, "Здравствуйте." }, { 0.97, "Я – епископ Делавей." }, { 2.45, "Дайте-ка, я угадаю, почему вы здесь!" }, { 5.03, "Наверняка потому, что откликнулись на просьбу юного Томаса, который предложил вам оказать мне услугу." }, { 12.26, "Он всегда стремится помочь мне." }, { 14.52, "Боюсь, я ещё не успел всё сформулировать, так что простите мне некоторую невнятность изложения..." }, { 21.29, "И, прошу вас, храните всё это в тайне." } } } } },
    [1275] = { d = 36.5, v = "nightelf-male#54", n = { x = 375 }, c = { x = { { 0.00, "Безрассудные эльфы крови попали в западню демонической магии." }, { 4.97, "Разве они не видели, что случилось с нагами и сатирами Калимдора?" }, { 10.22, "Я боюсь, что эльфы крови могут претерпеть такую же трансформацию." }, { 15.47, "Азерот не может позволить себе породить ещё одну расу злобных монстров." }, { 21.30, "Я хотел бы изучить ствол мозга сатиров и нагов, чтобы понять, на что обрекают себя эльфы крови." }, { 29.00, "И сатиров, и нагов вы найдёте в Непроглядной Пучине, на побережье Ясеневого леса." }, { 35.41, "Путь неблизкий." } } }, t = { d = 20.5, v = "nightelf-male#54", n = { x = 195 }, c = { x = { { 0.00, "Вы проделали долгий путь и, несомненно, столкнулись с огромной опасностью." }, { 6.21, "Ваши действия были самоотверженными." }, { 9.36, "Ваша помощь – на благо всему Азероту." }, { 12.66, "Я благодарю вас, за всё, что вы сделали." }, { 15.96, "А теперь прошу меня простить, но мне нужно работать..." } } } } },
    [1276] = { d = 31.4, v = "orc-male", n = { x = 316 }, c = { x = { { 0.00, "А, вспомнил!" }, { 1.01, "Мозарн – знаменитый кузнец из Громового Утёса." }, { 4.67, "Я же помню, что слышал это имя прежде!" }, { 7.83, "Если мне не изменяет память, Служители Земли в благодарность наградили меня доспехами его работы." }, { 15.65, "Отличная работа." }, { 17.02, "Возможно, он расскажет тебе больше о щите, вышедшем из его рук." }, { 22.11, "Я не уверен, что эта информация важна, но, поскольку мы так и не знаем ничего о Рите, пренебрегать ей было бы неразумно." } } }, t = { d = 15.7, g = 1, v = "tauren-male#68", n = { m = 136, f = 137 }, c = { m = { { 0.00, "Да, ты прав." }, { 1.03, "Это моя работа." }, { 2.53, "Правда, боюсь, что это всё, что я могу тебе рассказать о нём." }, { 7.92, "Из моих рук вышло столько щитов и прочего оружия, что вряд ли я смог бы запомнить их все." } }, f = { { 0.00, "Да, ты права." }, { 1.19, "Это моя работа." }, { 2.71, "Правда, боюсь, что это всё, что я могу тебе рассказать о нём." }, { 8.12, "Из моих рук вышло столько щитов и прочего оружия, что вряд ли я смог бы запомнить их все." } } } } },
    [1282] = { d = 17.1, v = "human-male#50", n = { x = 197 }, c = { x = { { 0.00, "Ничего не могу с собой поделать, мне так жаль старину Джима..." }, { 4.28, "Он не всегда был таким..." }, { 6.02, "Когда-то он держал таверну на болотах, дивное было местечко." }, { 10.25, "Слушай, я не в настроении говорить об этом." }, { 13.23, "Если тебе нужна информация, поговори с капитаном Ваймсом." } } }, t = { d = 40.5, v = "human-male", n = { x = 481 }, c = { x = { { 0.00, "Настоящее его имя – Джеймс Хьяль." }, { 2.32, "Он открыл таверну на краю Степей, хотел сделать уютное местечко для отдыха путешественников." }, { 8.76, "Может, он слишком многого хотел, но некоторое время дела в таверне шли хорошо." }, { 14.27, "Потом мы потеряли контроль за дорогами через болота, и здесь стали шататься огры, а Джеймс был слишком упрям, он не захотел бросить своё детище ради безопасности." }, { 25.48, "Теперь таверна \"Последний привал\" сгорела до основания." }, { 29.36, "Мы пытались разобраться, но особых успехов не достигли, поэтому твою помощь примем с благодарностью." }, { 36.30, "Если хочешь помочь – посмотри, вдруг что найдёшь на развалинах." } } } } },
    [1284] = { d = 13.4, v = "narrator", n = { x = 138 }, c = { x = { { 0.00, "Цепочка следов уходит от всё ещё дымящегося остова таверны \"Последний привал\"." }, { 6.29, "В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчётливо." } } }, t = { d = 16.8, v = "human-male", n = { x = 204 }, c = { x = { { 0.00, "Следы копыт, говоришь?" }, { 1.58, "В последнее время в этих краях зашевелились кентавры." }, { 5.24, "Наши разведчики во время вылазки в Степи заметили несколько их лагерей и поселений." }, { 10.91, "Я пошлю одного из наших охотников, Фальграна Гастила, посмотреть, куда ведут эти следы." } } } } },
    [1285] = { d = 22.6, v = "human-male#50", n = { x = 238 }, c = { x = { { 0.00, "Реддон..." }, { 0.75, "Редпат..." }, { 1.50, "А!" }, { 1.70, "Вот он!" }, { 2.24, "Лейтенант Павал Рит." }, { 3.81, "Вступил в ряды тераморской стражи вместе с остальными новобранцами, которые пришли из-за моря вместе с леди Праудмур." }, { 13.23, "Зачислен в морские пехотинцы Кул Тираса в возрасте шестнадцати лет." }, { 18.26, "Отличная служба, поощрения..." }, { 20.50, "Числится пропавшим без вести." } } }, t = { d = 17.9, v = "human-male", n = { x = 216 }, c = { x = { { 0.00, "Пропал без вести?" }, { 1.22, "В переводе с языка Тезорана, это значит – предатель." }, { 4.84, "Не сомневаюсь, что это один из тех глупцов, слепо преданных адмиралу Даэлину и готовых ради него предать собственную страну." }, { 13.35, "Забавно, правда?" }, { 14.51, "Дезертиры обвиняют нас в предательстве дела Альянса." } } } } },
    [1286] = { d = 28.5, v = "human-male", n = { x = 337 }, c = { x = { { 0.00, "Удержаться здесь, на болотах, было нелегко." }, { 3.01, "Но мы, со всей своей решимостью и отвагой, смогли возвести несколько оборонительных сторожевых башен в округе." }, { 10.61, "По последним донесениям наших разведчиков, группа дезертиров засела в Разрушенной башне, к юго-востоку от таверны." }, { 18.58, "За главного у них, кажется, Балос Хакен." }, { 21.40, "Посмотрим, может удастся получить от него какие-то сведения." }, { 25.67, "Но будь с ним осторожнее, он – тёртый вояка." } } }, t = { d = 5.2, v = "human-male", n = { x = 56 }, c = { x = { { 0.00, "Тебя Ваймс прислал?" }, { 1.51, "Вечно он спихивает на других всю грязную работу..." } } } } },
    [1287] = { d = 22.8, v = "human-male", n = { x = 284 }, c = { x = { { 0.00, "Рит?" }, { 0.29, "Этот трус?" }, { 0.99, "Мы вышвырнули его из лагеря, потому что он настаивал на налёте на деревню огров Гиблотопь, чтобы пограбить их запасы." }, { 8.54, "Нас не так много, чтобы рассчитывать справиться с этими безмозглыми тварями." }, { 13.46, "Он настолько часто зарывался, что мы решили, что с нас хватит, и прогнали его." }, { 18.49, "Вот, я помог тебе, почему бы теперь тебе не забыть о нашей встрече?" } } }, t = { d = 12.6, v = "human-male", n = { x = 151 }, c = { x = { { 0.00, "Я пошлю лейтенанта Келдвелла поговорить с дезертирами из Разрушенной башни." }, { 5.14, "Вдобавок, я попрошу его поискать Рита." }, { 7.87, "Болота не так уж велики и непроходимы, так что я уверен, он его отыщет." } } } } },
    [1288] = { d = 20.6, v = "human-male", n = { x = 240 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.11, "Для любителя просто отличная." }, { 3.15, "Леди Праудмур просила, чтобы я держал её в курсе, но я некоторое время не имел возможности с ней пообщаться." }, { 10.89, "Я собирался отправить ей рапорт позже, – но мне кажется уместным вместо этого послать к ней тебя." }, { 17.57, "Ты куда лучше меня ответишь на все её вопросы." } } } },
    [1301] = { d = 27.2, v = "human-male", n = { x = 319 }, c = { x = { { 0.00, "Перед тем, как перебраться сюда, в \"Синий Отшельник\", я обучался у одного из лучших поваров, которых я когда-либо встречал." }, { 8.30, "Его звали Джеймс Хьяль, и всё чего я добился в этой жизни, это только благодаря ему." }, { 14.10, "Интересно, как-то он там сейчас?" }, { 16.29, "Он вместе со своим братом Винсентом работал в таверне, в Гавани Менетилов, но я давно о нём ничего не слышал." }, { 23.68, "Если вдруг ненароком встретишь его, кланяйся от меня." } } }, t = { d = 13.4, v = "human-male", n = { x = 155 }, c = { x = { { 0.00, "Джеймс?" }, { 0.51, "Так он ещё когда уехал отсюда." }, { 2.65, "Волна патриотизма накрыла, наверное." }, { 5.24, "Можно понять." }, { 6.25, "Многие после всего этого безумия, творящегося в Лордероне, последовали за Джайной Праудмур за море." } } } } },
    [1302] = { d = 27.0, v = "human-male", n = { x = 296 }, c = { x = { { 0.00, "Мой брат Джеймс ушёл за море с леди Праудмур." }, { 3.38, "Последнее, что я слышал, было то, что по окончании боёв он открыл там таверну." }, { 8.83, "Но, где бы он ни находился, я уверен, что дела у него идут хорошо." }, { 13.51, "Он ведь, знаете ли, великолепный повар." }, { 16.27, "Я некоторое время не имел о нём известий – видать, с гостиницей было много хлопот – но я уверен, что клерк в Тераморе сможет указать вам, где его искать." } } }, t = { d = 14.2, v = "human-male", n = { x = 142 }, c = { x = { { 0.00, "Джеймс Хьяль, Джеймс Хьяль..." }, { 2.13, "Что-то знакомое..." }, { 3.61, "А, точно!" }, { 4.39, "Случай с \"Последним привалом\"." }, { 6.80, "Если ты хоть что-то об этом знаешь, то пойди и расскажи капитану Ваймсу." }, { 12.54, "Он ведёт расследование." } } } } },
    [1318] = { d = 48.5, v = "creature/ogre", n = { x = 473 }, c = { x = { { 0.00, "Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а?" }, { 10.49, "Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спёр его у одного из королей!" }, { 24.21, "А вещица-то была ценная: латная рукавица Мощи Гордока!" }, { 28.75, "И в старых байках говорится, что воротить её сможет только настоящий король Гордок." }, { 35.58, "А ещё говорится, что паскудный эльф до сих пор шляется где-то тут." }, { 40.78, "Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!" }, { 47.46, "Йар, я покажу!" } } } },
    [1319] = { d = 13.7, v = "human-male", n = { x = 134 }, c = { x = { { 0.00, "Увы, но я не смогу помочь тебе." }, { 2.53, "Впрочем, я знаю, кто сможет." }, { 4.77, "Каз Дваждыдвац – один из лучших наших кузнецов." }, { 8.49, "Его можно найти на кузне." }, { 10.60, "Покажи ему щит и послушай, что он скажет." } } }, t = { d = 10.2, v = "gnome-male", n = { x = 103 }, c = { x = { { 0.00, "Хмм..." }, { 0.48, "Интересная железяка." }, { 2.06, "Это точно не моя работа, и я не знаю ни одного кузнеца по эту сторону моря, из чьих рук она могла бы выйти." } } } } },
    [1320] = { d = 18.4, v = "gnome-male", n = { x = 215 }, c = { x = { { 0.00, "Чуть было не просмотрел..." }, { 1.77, "Кожаный ремень на тыльной стороне щита сгорел, но, сдаётся мне, он был приспособлен под крупную руку." }, { 8.54, "Скорее всего, тауренскую." }, { 10.31, "Вот, в общем, и всё, что я могу тебе сказать." }, { 13.36, "Передай капитану Ваймсу, что я сожалею, но больше ничем не могу ему помочь." } } }, t = { d = 11.0, v = "human-male", n = { x = 138 }, c = { x = { { 0.00, "Узнать удалось немного, но и это сгодится." }, { 2.92, "Будем надеяться, что вскоре прояснятся остальные части этой головоломки, и мы сможем увидеть полную картину произошедшего." } } } } },
    [1321] = { d = 14.8, v = "orc-male", n = { x = 144 }, c = { x = { { 0.00, "Хмм..." }, { 0.50, "Я не вижу в этом щите ничего необычного." }, { 3.79, "Нужно попросить До'гола, нашего кузнеца, взглянуть на него." }, { 8.58, "Может быть, До'гол сможет рассказать нам больше, хотя я бы не надеялся на это..." } } }, t = { d = 10.9, v = "named/5087", n = { x = 89 }, c = { x = { { 0.00, "Хороший щит." }, { 1.18, "Крепкий, тяжёлый, хороший..." }, { 3.79, "Но До'голу он не нужен." }, { 5.99, "До'гол делает щиты, а не покупает их." }, { 9.53, "Теперь понятно?" } } } } },
    [1322] = { d = 22.1, v = "named/5087", n = { x = 206 }, c = { x = { { 0.00, "Хммм..." }, { 0.62, "Тут, на ободе щита, оказывается, есть надпись, но прочитать её трудно, она почти вся обгорела." }, { 8.71, "Мне нужна кислота, чтобы отчистить её." }, { 12.05, "Яд пауков-темножвалов, обитающих в топях, подойдёт." }, { 16.41, "Принеси мне немного их ядовитых желёз, и я смогу отчистить этот щит." } } }, t = { d = 9.5, v = "named/5087", n = { x = 88 }, c = { x = { { 0.00, "Я не люблю слишком больших пауков – их не раздавишь." }, { 4.56, "Спасибо." }, { 5.35, "Теперь я вскрою железы и залью их содержимым щит…" } } } } },
    [1323] = { d = 19.2, v = "named/5087", n = { x = 164 }, c = { x = { { 0.00, "Сдаётся мне, что с кислотой я переборщил." }, { 3.74, "Теперь осторожно потрём щит…" }, { 6.37, "Хмм." }, { 6.79, "Прочесть сложновато, но, похоже, тут написано имя: Мозарн." }, { 12.32, "Никогда о таком не слышал." }, { 14.86, "Надо спросить Крога, он знаком с кучей народу." } } }, t = { d = 15.0, v = "orc-male", n = { x = 139 }, c = { x = { { 0.00, "Мозарн?" }, { 0.69, "Звучит знакомо..." }, { 2.21, "Но поручиться не могу." }, { 4.12, "Может быть вспомню попозже." }, { 6.49, "Скорее всего, это имя не имеет значения." }, { 10.08, "Щит мог попасть туда откуда угодно и с какой угодно целью." } } } } },
    [1324] = { d = 13.6, v = "human-male", n = { x = 165 }, c = { x = { { 0.00, "Что?!" }, { 0.36, "Вы приходите сюда, обвиняете меня в пособничестве Братству Справедливости и думаете, что я буду стоять столбом, пока вы меня оскорбляете?!" }, { 9.67, "Что-то мне подсказывает, что вы давно на это напрашивались..." } } }, t = { d = 16.8, v = "human-male", n = { x = 203 }, c = { x = { { 0.00, "Уверяю вас, что мы все огорчены текущими событиями, но просим позволить забрать его назад в Терамор, чтобы задать несколько вопросов." }, { 9.04, "Это поможет в поисках короля." }, { 11.12, "Леди Праудмур отблагодарит вас за помощь." }, { 14.22, "Обратитесь к ней при первой возможности." } } } } },
    [1338] = { d = 35.8, v = "dwarf-male", n = { x = 406 }, c = { x = { { 0.00, "Есть один дворф-бронник, чья работа меня глубоко восхищает." }, { 4.27, "Его зовут Фьюрен Длиннобород, и такого искусника ещё поискать." }, { 8.80, "Мне нужен новый щит, и я хотел бы сделать заказ у него!" }, { 12.81, "Проблема в том... что он живёт далеко на юге, в Квартале Дворфов в Штормграде." }, { 18.32, "В человеческих землях!" }, { 19.93, "Представления не имею, зачем он поселился так далеко от Стальгорна." }, { 24.72, "Должно быть, люди платят немалую мзду, лишь бы удержать его у себя!" }, { 29.58, "Если ты любишь путешествовать и не прочь подзаработать, может, передашь мой заказ Фьюрену?" } } }, t = { d = 16.0, v = "dwarf-male", n = { x = 163 }, c = { x = { { 0.00, "А, заказ от дворфа Грозовой Вершины." }, { 3.00, "Это гордый клан, славный крепкими, сильными дворфами." }, { 7.38, "И их богатством." }, { 8.70, "Большое спасибо." }, { 10.09, "Я сегодня же вечером займусь щитом для горного пехотинца Грозовой Вершины." } } } } },
    [1339] = { d = 18.2, g = 1, v = "dwarf-male", n = { x = 206 }, c = { m = { { 0.00, "Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие." }, { 8.47, "Сможет ли герой вроде тебя справиться с его поручением?" }, { 12.55, "Если ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне." } }, f = { { 0.00, "Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие." }, { 8.30, "Сможет ли героиня вроде тебя справиться с его поручением?" }, { 12.42, "Если ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне." } } }, t = { d = 13.2, v = "dwarf-male", n = { x = 139 }, c = { x = { { 0.00, "Верно." }, { 0.57, "У меня есть одно дельце, но самому мне недосуг – не могу покинуть пост." }, { 6.21, "Путь неблизкий, придётся поработать ногами." }, { 9.57, "Зато отличная возможность поискать приключений!" } } } } },
    [1358] = { d = 34.3, v = "scourge-female", n = { x = 381 }, c = { x = { { 0.00, "Мой коллега на Калимдоре, аптекарь Хелбрим, исследует воздействие лордеронских ядов на тамошних зверей." }, { 7.81, "Он наверняка хотел бы иметь препарат из волчьего сердца, что мне прислал Ренферрел." }, { 14.12, "Хелбрим обосновался в Степях, в деревне под названием Перекрёсток." }, { 19.05, "Чтобы до него добраться, вам нужно будет на дирижабле добраться до орочьей столицы Оргриммара, а потом пешком проследовать на юг, в Дуротар." }, { 29.67, "Направляйтесь на запад, в Степи, и вскоре дойдёте до Перекрёстка." } } }, t = { d = 18.5, v = "scourge-male", n = { x = 176 }, c = { x = { { 0.00, "А, очень хорошо." }, { 1.51, "Если первые результаты верны, токсические свойства этих сердец могут серьёзно продвинуть нас в наших представлениях о ядах." }, { 12.37, "Это долгожданная посылка." }, { 14.67, "Ваша награда за неё – совершенно заслуженная." } } } } },
    [1359] = { d = 34.2, v = "scourge-male#82", n = { x = 347 }, c = { x = { { 0.00, "Волчьи сердца, которые вы собрали, обладают качеством, невиданным доселе в подобных образцах." }, { 7.71, "Это сила яда, которая должна быть смертельной даже для тех самых волков, в груди которых бьются эти сердца!" }, { 16.75, "Это просто невероятно, и мы должны продолжить исследование." }, { 21.64, "Я сохранил несколько полученных препаратов." }, { 25.20, "Отнесите их моей коллеге, аптекарю Зинг." }, { 28.54, "Её можно найти в главном представительстве нашего Общества в Подгороде." } } }, t = { d = 18.2, v = "scourge-female", n = { x = 174 }, c = { x = { { 0.00, "Ах да, препараты сердец, о которых говорил Ренферрел." }, { 4.74, "Я хочу поскорее начать экспериментировать с ними..." }, { 9.32, "Обнаружение новых форм ядов всегда вызывает живейший интерес в Королевском фармацевтическом обществе." } } } } },
    [1360] = { d = 32.4, v = "dwarf-male", n = { x = 374 }, c = { x = { { 0.00, "Я неплохо зарабатывал горнорабочим на ульдаманском раскопе в Бесплодных землях, пока не появились эти клятые трогги." }, { 8.10, "Я едва сумел спасти свою шкуру, но в суматохе потерял самое дорогое, что у меня было." }, { 14.20, "Уверен, что трогги не добрались до моего сокровища, поскольку оно в сундуке, но сундук-то в самой их гуще." }, { 21.61, "Если ты принесёшь его мне, то не поскуплюсь ни на деньги, ни на хвалу!" }, { 26.39, "Сундучок с моим именем находится в конце Северного зала." }, { 30.41, "Вот туда тебе и надо попасть." } } }, t = { d = 16.8, v = "dwarf-male", n = { x = 180 }, c = { x = { { 0.00, "Ах, я снова счастлив!" }, { 1.67, "Спасибо тебе огромное." }, { 3.47, "Может, кому из дворфов дороже всего блеск металла, а кому – сверкание драгоценных камней, но Крепкорук без своей драгоценной пивной кружки вряд ли может считаться Крепкоруком!" } } } } },
    [1361] = { d = 24.4, v = "orc-male", n = { x = 257 }, c = { x = { { 0.00, "Регтар Врата Смерти, воин Орды, набирает агентов для похода в земли Пустошей." }, { 6.17, "Любой желающий может поговорить с ним и попробовать записаться в отряд." }, { 11.71, "Найти Регтара можно в Степях, в одном из укрытий к западу от Перекрёстка." }, { 17.40, "Не следует забывать, что в Пустошах не затихают битвы, поэтому без оружия там нечего делать." } } }, t = { d = 13.0, g = 1, v = "orc-male#60", n = { m = 139, f = 141 }, c = { m = { { 0.00, "Да, я набираю добровольцев." }, { 2.10, "Тех, кто готов отправиться в Пустоши и сражаться с кентаврами." }, { 6.87, "Я изложу ситуацию вкратце, чтобы ты скорее мог приступить к выполнению задания." } }, f = { { 0.00, "Да, я набираю добровольцев." }, { 2.07, "Тех, кто готов отправиться в Пустоши и сражаться с кентаврами." }, { 6.76, "Я изложу ситуацию вкратце, чтобы ты скорее могла приступить к выполнению задания." } } } } },
    [1362] = { d = 41.0, v = "orc-male#60", n = { x = 411 }, c = { x = { { 0.00, "Кентавры из клана Колкар изначально жили в Пустошах, но теперь они всё чаще появляются в Степях." }, { 7.92, "Это известный факт, и Орда послала своих агентов разбираться с ними." }, { 13.56, "Однако же пока клан Колкар силён в Пустошах, эти кентавры всегда будут для нас угрозой." }, { 20.67, "Думаю, пора от них избавиться." }, { 23.16, "Главное – безопасность!" }, { 25.07, "Поговори с Фелгуром Бью-Двоих: ты его найдёшь на Заставе Скитающихся Духов в Пустошах." }, { 32.03, "Его отправили туда для сбора информации о кентаврах." }, { 36.36, "Думаю, он лучше всех знает, как справиться с кланом Колкар." } } }, t = { d = 22.0, g = 1, v = "orc-male#60", n = { m = 207, f = 208 }, c = { m = { { 0.00, "Тебя Регтар сюда прислал?" }, { 2.21, "Значит, ты и будешь решать проблему кентавров?" }, { 6.05, "Что ж, хорошо." }, { 7.23, "Надеюсь, ты успел отдохнуть." }, { 9.59, "Не знаю уж, удастся нам разобраться с этими тварями, или нет, но за то, что это будет долгая и тяжкая драка, могу ручаться." }, { 19.70, "Присядь и послушай меня..." } }, f = { { 0.00, "Тебя Регтар сюда прислал?" }, { 2.23, "Значит, ты и будешь решать проблему кентавров?" }, { 6.10, "Что ж, хорошо." }, { 7.29, "Надеюсь, ты успела отдохнуть." }, { 9.74, "Не знаю уж, удастся нам разобраться с этими тварями, или нет, но за то, что это будет долгая и тяжкая драка, могу ручаться." }, { 19.92, "Присядь и послушай меня..." } } } } },
    [1363] = { d = 31.6, v = "human-male", n = { x = 407 }, c = { x = { { 0.00, "Я слежу за тем, чтобы все фолианты и свитки в библиотеке Академии Тайных Наук и Искусств постоянно находились под присмотром." }, { 8.14, "Кто знает, сколько глупостей может натворить непосвящённый, заполучив тайные трактаты по магии?" }, { 14.34, "Например, на прошлой неделе мой помощник Деллис допустил одну оплошность..." }, { 19.29, "Он неплохой работник и хорошо ориентируется в пределах библиотеки, но совершенно теряется, стоит ему выйти за ворота Штормграда..." }, { 27.79, "Пожалуйста, помогите Деллису разобраться с его затруднением." } } }, t = { d = 3.0, v = "human-male", n = { x = 28 }, c = { x = { { 0.00, "Да не виноват я!" }, { 1.40, "Клянусь, не виноват!" } } } } },
    [1364] = { d = 34.7, v = "human-male", n = { x = 416 }, c = { x = { { 0.00, "Указания мастера Мазена были совсем простыми: доставить важное сочинение дозорному Махару Ба в Крепость Стражей Пустоты." }, { 8.30, "Но мне раньше не доводилось бывать в Выжженных землях!" }, { 11.99, "Путешествие было просто ужасным..." }, { 14.39, "Неподалёку от Болота Печали я свернул куда-то не туда и оказался окружён жуткими тварями, похожими на растения." }, { 21.89, "Они напали на меня, и я сбежал." }, { 24.10, "Представьте себе, при этом я потерял сочинение!" }, { 27.36, "Думаю, его забрала одна из этих тварей." }, { 30.19, "Не могу ли я попросить вас найти документ и доставить его Махару Ба?" } } }, t = { d = 28.9, v = "human-male", n = { x = 391 }, c = { x = { { 0.00, "Какое счастье!" }, { 0.95, "До сего момента я считал, что мой запрос на \"Рассуждения Кадгара о пространственной сходимости\", который я отправлял в Академию Тайных Наук и Искусств, был отклонён мастером Мазеном." }, { 12.05, "Он, должно быть, просто потонул в запросах, поскольку в последнее время происходит множество странных событий." }, { 18.86, "Теперь прошу меня простить – мне пора приступить к исследованиям." }, { 22.93, "Понимаете, сама возможность прикоснуться к творению величайшего Кадгара повергает меня в трепет..." } } } } },
    [1365] = { d = 41.8, v = "orc-male#60", n = { x = 433 }, c = { x = { { 0.00, "Племя Колкар – не единственные кентавры в Пустошах." }, { 4.02, "На этих пустынных равнинах поселилось множество племён, ведущих друг с другом бесконечную войну." }, { 11.50, "Наше счастье, что они дерутся между собой: кентавры сильны и яростны в битве, и, если бы они объединились, нам тяжело было бы выстоять против них." }, { 23.07, "Мы должны покончить с ними прежде, чем они объединятся." }, { 27.45, "Твоё первое задание – расколоть племя Колкар." }, { 31.04, "Для этого нужно убить их предводителя Дез'хепа." }, { 34.78, "Деревня клана Колкар находится к северо-востоку отсюда." }, { 39.23, "Иди, и да пребудет с тобой удача." } } }, t = { d = 21.7, v = "orc-male#60", n = { x = 208 }, c = { x = { { 0.00, "Отлично." }, { 0.78, "Быстрый и точный удар по клану Колкар стал весьма эффектной демонстрацией силы, а сила – это именно то, что кентавры понимают лучше всего." }, { 12.82, "Смерть вождя клана Колкар не только расколет клан, но и станет предостережением для всех прочих кентавров." } } } } },
    [1366] = { d = 26.9, v = "orc-male#60", n = { x = 253 }, c = { x = { { 0.00, "Тебе удалось устрашить кентавров; теперь пришло время пустить им кровь." }, { 6.31, "Странствуя по Пустошам, охоться на кентавров." }, { 10.25, "Их клан меня не волнует: просто убей их и принеси мне уши." }, { 15.37, "Пригоршни ушей!" }, { 16.79, "Чем меньше кентавров, тем слабее их решимость: пусть навсегда расстанутся с мыслью завоевать эти земли!" }, { 25.78, "Доброй охоты." } } }, t = { d = 16.6, g = 1, v = "orc-male#60", n = { m = 144, f = 145 }, c = { m = { { 0.00, "Теперь-то кентавры навсегда запомнят твоё имя!" }, { 4.20, "Уверен, они уважают и страшатся тебя." }, { 7.68, "Уверен, благодаря тебе они не забудут и того знамени, под которым ты вступал в бой." }, { 15.19, "Знамя Орды!" } }, f = { { 0.00, "Теперь-то кентавры навсегда запомнят твоё имя!" }, { 4.28, "Уверен, они уважают и страшатся тебя." }, { 7.83, "Уверен, благодаря тебе они не забудут и того знамени, под которым ты вступала в бой." }, { 15.57, "Знамя Орды!" } } } } },
    [1367] = { d = 34.9, v = "tauren-female", n = { x = 372 }, c = { x = { { 0.00, "Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть." }, { 6.54, "Мы заключим союз с одним из племён, и так найдём способ одолеть всех остальных." }, { 12.59, "Если ты решишь заключить союз с племенем Маграм, уничтожь их кровных врагов – племя Гелкис." }, { 19.84, "Так ты завоюешь уважение племени Маграм." }, { 23.00, "Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Варугом." }, { 29.33, "Ты найдёшь его на окраине деревни Маграм в юго-восточной части Пустошей." } } }, t = { d = 19.0, g = 1, v = "named/5398", n = { m = 174, f = 175 }, c = { m = { { 0.00, "Кентавры племени Гелкис кричат от ужаса, заслышав твоё имя." }, { 5.06, "Они страшатся и ненавидят тебя." }, { 7.77, "Ненавидят так же, как племя Маграм!" }, { 10.72, "Может, ты и не слабее нас." }, { 12.90, "Может, ты даже достоин того, чтобы мы с тобой говорили." }, { 17.66, "Посмотрим..." } }, f = { { 0.00, "Кентавры племени Гелкис кричат от ужаса, заслышав твоё имя." }, { 5.17, "Они страшатся и ненавидят тебя." }, { 7.94, "Ненавидят так же, как племя Маграм!" }, { 10.95, "Может, ты и не слабее нас." }, { 13.18, "Может, ты даже достойна того, чтобы мы с тобой говорили." }, { 18.12, "Посмотрим..." } } } } },
    [1368] = { d = 35.4, v = "tauren-female", n = { x = 373 }, c = { x = { { 0.00, "Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть." }, { 6.61, "Мы заключим союз с одним из племён, и так найдём способ одолеть всех остальных." }, { 12.71, "Если ты решишь заключить союз с племенем Гелкис, уничтожь их кровных врагов – племя Маграм." }, { 20.03, "Так ты завоюешь уважение племени Гелкис." }, { 23.22, "Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Утой Мудрой." }, { 29.97, "Ты найдёшь её на окраине деревни Гелкис в юго-западной части Пустошей." } } }, t = { d = 16.9, g = 1, v = "named/5397", n = { m = 147, f = 148 }, c = { m = { { 0.00, "Земля говорит со мной, земля говорит, что ты убил многих из племени Маграм." }, { 6.62, "Это хорошо." }, { 7.73, "Если хочешь быть другом племени Гелкис, слушай." }, { 11.99, "Я буду говорить с тобой." }, { 14.19, "У меня есть для тебя дело." } }, f = { { 0.00, "Земля говорит со мной, земля говорит, что ты убила многих из племени Маграм." }, { 6.86, "Это хорошо." }, { 8.00, "Если хочешь быть другом племени Гелкис, слушай." }, { 12.36, "Я буду говорить с тобой." }, { 14.62, "У меня есть для тебя дело." } } } } },
    [1369] = { d = 29.8, v = "named/5398", n = { x = 275 }, c = { x = { { 0.00, "Племя Гелкис считает, что нас защищает матерь кентавров Терадрас." }, { 5.79, "Они глупы." }, { 6.83, "Кентавров никто не защищает." }, { 9.36, "Маграм не нужна защита!" }, { 11.51, "Мы сильнее всех!" }, { 12.94, "Пусть племя Гелкис поймёт, насколько они глупы." }, { 17.14, "Отправляйся в их деревню, прямиком к пещере." }, { 21.03, "В этой пещере они хранят кристаллы – слёзы Терадрас." }, { 25.71, "Уничтожь эти кристаллы!" }, { 27.86, "Принеси мне их осколки!" } } }, t = { d = 19.1, g = 1, v = "named/5398", n = { m = 162, f = 163 }, c = { m = { { 0.00, "Ага!" }, { 0.48, "Вот они, Слёзы!" }, { 1.85, "Теперь племя Гелкис поймёт, что Терадрас не защитит их." }, { 6.75, "Она не станет плакать, когда мы сокрушим их!" }, { 10.77, "Маграм будут править здесь!" }, { 13.26, "Ты хорошо сделал, выбрав нашу сторону." }, { 16.79, "Мы – самые сильные." } }, f = { { 0.00, "Ага!" }, { 0.50, "Вот они, Слёзы!" }, { 1.91, "Теперь племя Гелкис поймёт, что Терадрас не защитит их." }, { 6.98, "Она не станет плакать, когда мы сокрушим их!" }, { 11.14, "Маграм будут править здесь!" }, { 13.71, "Ты хорошо сделала, выбрав нашу сторону." }, { 17.45, "Мы – самые сильные." } } } } },
    [1370] = { d = 25.7, v = "named/5397", n = { x = 229 }, c = { x = { { 0.00, "Когда мы не воюем, то охотимся, чтобы добыть мяса." }, { 4.62, "Мясо даёт нам силу." }, { 6.40, "Сытый воюет лучше голодного." }, { 9.07, "Сытый сильнее." }, { 10.45, "Сытый победит." }, { 11.83, "Племя Маграм поступает так же." }, { 14.58, "Они запасают мясо, чтобы воевать дольше." }, { 18.39, "Если нападёшь на их деревню на востоке и заберёшь их припасы, Маграм станут слабыми." } } }, t = { d = 18.4, g = 1, v = "named/5397", n = { m = 151, f = 152 }, c = { m = { { 0.00, "Хорошо." }, { 0.74, "Я слышу, как урчит в брюхе у голодных Маграм!" }, { 4.96, "Слышу это даже здесь!" }, { 7.02, "Я отдам это мясо племени Гелкис." }, { 10.16, "Мы будем воевать много дней без отдыха." }, { 13.79, "То, что ты сделал, хорошо для племени Гелкис." } }, f = { { 0.00, "Хорошо." }, { 0.77, "Я слышу, как урчит в брюхе у голодных Маграм!" }, { 5.11, "Слышу это даже здесь!" }, { 7.24, "Я отдам это мясо племени Гелкис." }, { 10.47, "Мы будем воевать много дней без отдыха." }, { 14.22, "То, что ты сделала, хорошо для племени Гелкис." } } } } },
    [1371] = { d = 47.0, v = "named/5398", n = { x = 465 }, c = { x = { { 0.00, "Давным-давно один маленький гном пришёл в Пустоши со своей тележкой, запряжённой лошадью и нагруженной множеством странных вещей." }, { 10.45, "Занятных вещей." }, { 11.78, "Некоторые горели разноцветным огнём." }, { 14.74, "Некоторые двигались, не будучи при этом живыми." }, { 18.67, "Я убил этого маленького гнома, но перед этим... он заставил меня посмеяться." }, { 25.04, "Я оставил себе одну вещицу с его тележки – ту, которая понравилась мне больше всего." }, { 32.08, "Это был деревянный человек, который махал на меня руками, пока я не ударил его, да так, что тот сломался." }, { 40.74, "Я хочу нового деревянного человека!" }, { 43.71, "Доставай его, где хочешь, но принеси мне!" } } }, t = { d = 8.2, v = "named/5398", n = { x = 72 }, c = { x = { { 0.00, "Да!" }, { 0.33, "Именно такой человек у меня и был!" }, { 3.51, "Он снова будет двигаться." }, { 5.87, "Снова будет веселить меня!" } } } } },
    [1372] = { d = 40.3, v = "scourge-male", n = { x = 380 }, c = { x = { { 0.00, "По приказу Вариматраса нашу экспедицию направили на изучение нижнего Азерота." }, { 6.62, "Отправившись на разведку, я заметил лазутчика, подобравшегося к Приюту Бродяги." }, { 13.31, "Не успел я скрутить его, как некоторые наши орочьи... братья... захватили его и уволокли в Каменор, крепость на Болоте Печали." }, { 24.16, "Я хочу... помочь... нашим братьям-оркам." }, { 27.70, "Они не заметили наш лагерь, но я всё равно собираюсь оказать им услугу." }, { 33.78, "Фаустин поможет тебе сделать... сыворотку правды для нашего друга в Каменоре." } } }, t = { d = 33.9, v = "scourge-male#82", n = { x = 317 }, c = { x = { { 0.00, "Зредус как раз перед твоим приходом рассказал мне об этом любопытном маленьком лазутчике." }, { 7.65, "Это и правда проблема." }, { 9.66, "Нам вовсе не нужен нахал, вынюхивающий, что да как." }, { 13.99, "Уверен, орки Каменора с интересом выслушают его." }, { 18.24, "Поскольку они, хм, наши союзники, мы должны помочь им добыть информацию от этого человека." }, { 26.04, "Помоги мне, – и мы доставим в Каменор сыворотку правды." }, { 30.75, "За Орду!" }, { 31.53, "Э-э... я правильно выразился?" } } } } },
    [1373] = { d = 46.6, v = "named/5397", n = { x = 425 }, c = { x = { { 0.00, "Тебе ещё предстоит свершить многое." }, { 3.19, "Война племён Гелкис и Маграм тебя не затронет: в это время ты будешь далеко отсюда." }, { 10.68, "Земля раскрывает множество тайн тем, кто умеет слушать её; и одна из них – тайна красного кристалла, который называют дренейским аметистом." }, { 22.88, "Это камень нездешнего происхождения; он из тех земель, где горы парят в небе, где правят демоны..." }, { 31.57, "Принеси мне осколок дренейского аметиста: о, с ним сила моей магии возрастёт во много раз!.." }, { 39.62, "Осколок можно отыскать на Болоте Печали: его хранит один из Заблудших, Онгеку." } } }, t = { d = 25.2, v = "named/5397", n = { x = 212 }, c = { x = { { 0.00, "О да, это и есть тот осколок, о котором шептала мне земля..." }, { 5.60, "Я ощущаю его магическую силу – ту силу, которую я направлю против врагов племени Гелкис." }, { 14.08, "Тебе удалось исполнить ещё одно наше задание." }, { 18.49, "Возможно, со временем племя Гелкис сможет по праву считать тебя другом." } } } } },
    [1374] = { d = 14.4, v = "named/5397", n = { x = 128 }, c = { x = { { 0.00, "Земля говорит со мной." }, { 2.06, "Земля знает, что племя Маграм утратило былую силу." }, { 6.83, "Пришло время покончить с их вождём!" }, { 10.04, "Принеси мне голову Джехна, вождя племени Маграм!" } } }, t = { d = 19.7, v = "named/5397", n = { x = 173 }, c = { x = { { 0.00, "Вождь Джехн был силён, но глуп." }, { 2.75, "Он полагал, что наделён великой силой, но забыл, что магия Земли могущественнее любого смертного." }, { 11.94, "Лишившись вождя, племя Маграм впадёт в ничтожество, и племя Гелкис восторжествует!" } } } } },
    [1375] = { d = 18.0, v = "named/5398", n = { x = 154 }, c = { x = { { 0.00, "Ты помогаешь племени Маграм." }, { 2.64, "Это хорошо." }, { 3.80, "Ты мне нравишься." }, { 5.37, "А теперь пойди и убей вождя племени Гелкис!" }, { 9.49, "Вождь Шак – мне нужна его голова!" }, { 12.55, "Я хочу видеть его голову, я буду смотреть на неё и смеяться!" } } }, t = { d = 11.8, v = "named/5398", n = { x = 105 }, c = { x = { { 0.00, "Вождь Шак мёртв!" }, { 1.42, "Я насажу его голову на пику, чтобы любоваться ею каждый день!" }, { 7.25, "Пусть мёртвые глаза Шака видят мощь племени Маграм!" } } } } },
    [1380] = { d = 55.4, g = 1, v = "named/5397", n = { m = 513, f = 515 }, c = { m = { { 0.00, "Ты помог нам справиться с племенем Маграм; теперь помоги нам одолеть племя Мародин!" }, { 6.99, "Убей их предводителя!" }, { 8.79, "Убей Храту!" }, { 9.85, "Чтобы вызвать его на бой, ты должен протрубить в боевой рог племени Мародин; а рог этот ты найдёшь, поднявшись на высокий утёс в Долине Копий." }, { 21.57, "Только запомни: чтобы протрубить в рог, тебе нужно разыскать мундштук, а это нелегко, потому что найти такие мундштуки можно только у кентавров, пользующихся особым доверием племени..." }, { 37.06, "О чём это я?" }, { 38.11, "Ах, да: когда ты протрубишь в рог, кентавры явятся на бой, и тебе придётся убивать их, пока не доберёшься до самого Храты." }, { 48.03, "А у вождя Храты есть фрагмент... некоего ключа." }, { 52.02, "Принеси его мне..." } }, f = { { 0.00, "Ты помогла нам справиться с племенем Маграм; теперь помоги нам одолеть племя Мародин!" }, { 7.38, "Убей их предводителя!" }, { 9.24, "Убей Храту!" }, { 10.33, "Чтобы вызвать его на бой, ты должна протрубить в боевой рог племени Мародин; а рог этот ты найдёшь, поднявшись на высокий утёс в Долине Копий." }, { 22.44, "Только запомни: чтобы протрубить в рог, тебе нужно разыскать мундштук, а это нелегко, потому что найти такие мундштуки можно только у кентавров, пользующихся особым доверием племени..." }, { 38.44, "О чём это я?" }, { 39.52, "Ах, да: когда ты протрубишь в рог, кентавры явятся на бой, и тебе придётся убивать их, пока не доберёшься до самого Храты." }, { 49.77, "А у вождя Храты есть фрагмент... некоего ключа." }, { 53.89, "Принеси его мне..." } } }, t = { d = 17.2, v = "named/5397", n = { x = 140 }, c = { x = { { 0.00, "Он мёртв!" }, { 0.89, "Вождь Храта мёртв!" }, { 2.66, "Теперь племя Мародин падёт!" }, { 5.41, "И когда этой землёй станет править племя Гелкис – клянусь, мы не забудем тебя." }, { 13.20, "Духи земли будут вечно славить твоё имя!" } } } } },
    [1381] = { d = 47.0, g = 1, v = "named/5398", n = { m = 453, f = 453 }, c = { m = { { 0.00, "Вождь племени Гелкис мёртв; пришёл черёд племени Мародин!" }, { 4.60, "Убей их вождя, Храту!" }, { 6.45, "Его не так просто отыскать, нет..." }, { 9.27, "Чтобы вызвать его на бой, ты должен протрубить в боевой рог клана Мародин; а рог этот ты найдёшь, поднявшись на высокий утёс в Долине Копий." }, { 20.69, "Только запомни: чтобы протрубить в рог, тебе нужно убить кентавра из племени Мародин и забрать у него мундштук." }, { 29.95, "И вот когда ты протрубишь в рог, кентавры явятся на бой, и тебе придётся убивать их, пока не доберёшься до самого Храты." }, { 39.59, "А у Храты есть фрагмент ключа." }, { 42.11, "Он нужен мне, этот фрагмент." }, { 44.48, "Принеси его." }, { 45.60, "Принеси мне." } }, f = { { 0.00, "Вождь племени Гелкис мёртв; пришёл черёд племени Мародин!" }, { 4.64, "Убей их вождя, Храту!" }, { 6.52, "Его не так просто отыскать, нет..." }, { 9.36, "Чтобы вызвать его на бой, ты должна протрубить в боевой рог клана Мародин; а рог этот ты найдёшь, поднявшись на высокий утёс в Долине Копий." }, { 20.90, "Только запомни: чтобы протрубить в рог, тебе нужно убить кентавра из племени Мародин и забрать у него мундштук." }, { 30.26, "И вот когда ты протрубишь в рог, кентавры явятся на бой, и тебе придётся убивать их, пока не доберёшься до самого Храты." }, { 40.00, "А у Храты есть фрагмент ключа." }, { 42.55, "Он нужен мне, этот фрагмент." }, { 44.94, "Принеси его." }, { 46.07, "Принеси мне." } } }, t = { d = 17.7, v = "named/5398", n = { x = 157 }, c = { x = { { 0.00, "Вождь Храта мёртв!" }, { 1.63, "Теперь Маграм – сильнейшее из племён!" }, { 4.97, "Мы сокрушим всех!" }, { 6.52, "Мы будем править в Пустошах!" }, { 9.12, "Мы не забудем тебя, и в тот час, когда сотни будут гибнуть под нашими копытами, мы пощадим тебя." } } } } },
    [1382] = { d = 33.2, v = "human-male", n = { x = 389 }, c = { x = { { 0.00, "На наше счастье, племена кентавров постоянно враждуют." }, { 3.79, "Если бы они объединились, никто не сумел бы их остановить." }, { 7.84, "Да, нам сильно повезло – и мы должны обратить это везение себе на пользу." }, { 12.94, "Племя Гелкис ведёт жестокую войну с племенем Маграм." }, { 16.61, "Если мы атакуем поселение Маграм, то, возможно, сумеем заключить союз с племенем Гелкис." }, { 22.77, "В юго-западной части Пустошей, неподалёку от лагерей племени Гелкис, ты сможешь найти Уту Мудрую." }, { 29.55, "Возможно, поговорив с ней, ты сумеешь заключить союз..." } } }, t = { d = 17.0, v = "named/5397", n = { x = 150 }, c = { x = { { 0.00, "В племени Гелкис говорят о тебе." }, { 2.95, "Твои руки в крови проклятых Маграм." }, { 6.21, "Это хорошо." }, { 7.33, "Я буду говорить с тобой." }, { 9.56, "Скажи, что ты можешь сделать для племени Гелкис – и что племя может сделать для тебя." } } } } },
    [1383] = { d = 43.6, v = "scourge-male#82", n = { x = 397 }, c = { x = { { 0.00, "Я знаю подходящую сыворотку." }, { 2.63, "Она обойдётся с правдой именно так, как с ней следует обходиться." }, { 8.46, "Чтобы сделать её, мне понадобится несколько сердец пантер Тени из болота." }, { 15.19, "Кроме того, мне нужен мох хозяина болота, обитающего неподалёку." }, { 21.02, "Не сомневаюсь, что ты сумеешь уговорить его поделиться с тобой." }, { 26.77, "И последнее, что необходимо мне для составления сыворотки, это опухоль странника глубин из отдалённых Пустошей." }, { 36.70, "Эти гиганты редко болеют, а опухоли у них появляются ещё реже." }, { 42.45, "А теперь иди!" } } }, t = { d = 16.8, v = "scourge-male#82", n = { x = 135 }, c = { x = { { 0.00, "Великолепно!" }, { 1.19, "И как раз вовремя." }, { 2.89, "Судя по тому, что говорит Зредус, лазутчик оправился от ран и готов к допросу." }, { 10.30, "Погоди, сейчас я приготовлю отра... то есть сыворотку правды." } } } } },
    [1384] = { d = 35.4, v = "named/5397", n = { x = 320 }, c = { x = { { 0.00, "Кентавры из племени Колкар полагают, что сильны в магии." }, { 4.95, "Они ничего не понимают в магии!" }, { 7.78, "Они не распознают её, даже если их носом в магию ткнуть!.." }, { 12.89, "Кто-то должен доказать им, что в отношении магии они просто дети неразумные." }, { 19.65, "Думаю, этим кем-то будешь ты." }, { 22.32, "Отправляйся в деревню Колкар, что на северо-востоке отсюда." }, { 27.42, "Отними у кентавров их обереги и принеси их мне." }, { 31.51, "Я брошу их в огонь, и это согреет мне сердце." } } }, t = { d = 18.7, g = 1, v = "named/5397", n = { m = 156, f = 158 }, c = { m = { { 0.00, "Ты сделал доброе дело для племени Гелкис." }, { 4.03, "Клан Колкар слаб, он обречён и сгинет." }, { 7.55, "Их жалкая магия не поможет им." }, { 10.47, "Ты показал им это – и страх сделает их ещё слабее!" }, { 15.19, "В этих землях слабаки долго не живут." } }, f = { { 0.00, "Ты сделала доброе дело для племени Гелкис." }, { 4.08, "Клан Колкар слаб, он обречён и сгинет." }, { 7.57, "Их жалкая магия не поможет им." }, { 10.46, "Ты показала им это – и страх сделает их ещё слабее!" }, { 15.23, "В этих землях слабаки долго не живут." } } } } },
    [1385] = { d = 41.7, v = "human-male", n = { x = 491 }, c = { x = { { 0.00, "Пустоши – земля, пожираемая огнём войны." }, { 2.84, "Кентавры враждуют между собой; мы страшимся того, что победившее племя пойдёт войной на наши крепости и разрушит их." }, { 10.99, "Мы не можем этого допустить." }, { 13.01, "Мы должны научиться побеждать кентавров, а для этого нам придётся заключить союз с одним из их племён." }, { 20.03, "Племя Маграм издревле враждует с племенем Гелкис." }, { 23.57, "Если ты начнёшь войну с племенем Гелкис, возможно, племя Маграм задумается о том, что неплохо бы иметь такого воина на своей стороне." }, { 32.92, "Завоюй расположение племени Маграм, а затем отправляйся в деревню племени в юго-восточной части Пустошей и поговори с Варугом." } } }, t = { d = 13.4, v = "named/5398", n = { x = 133 }, c = { x = { { 0.00, "Многие из племени Гелкис пали от твоей руки." }, { 3.71, "Мне это нравится." }, { 5.16, "Может, ты сумеешь сделать что-то ещё, что мне понравится." }, { 9.73, "Может, ты сумеешь стать другом племени Маграм." } } } } },
    [1386] = { d = 18.7, v = "named/5398", n = { x = 162 }, c = { x = { { 0.00, "Клан Колкар полагает, что он силён; мы смеёмся над ними – и убиваем их со смехом!" }, { 7.05, "Ты тоже их убиваешь." }, { 8.91, "Покажи, что умеешь убивать их не хуже, чем мы." }, { 13.05, "Клан Колкар должен умереть." }, { 15.56, "Иди на север." }, { 16.86, "Убей их." }, { 17.67, "Убей их всех!" } } }, t = { d = 11.8, g = 1, v = "named/5398", n = { m = 108, f = 110 }, c = { m = { { 0.00, "Теперь клан Колкар страшится тебя." }, { 3.04, "Скажи, ты смеялся, когда убивал их?" }, { 6.15, "Когда убиваешь, надо смеяться, тогда враги увидят, что они слабы." } }, f = { { 0.00, "Теперь клан Колкар страшится тебя." }, { 2.98, "Скажи, ты смеялась, когда убивала их?" }, { 6.19, "Когда убиваешь, надо смеяться, тогда враги увидят, что они слабы." } } } } },
    [1387] = { d = 36.1, v = "human-male#50", n = { x = 390 }, c = { x = { { 0.00, "Раса кентавров состоит из множества кланов." }, { 3.30, "У каждого из них – свой вождь и свои законы, но есть одна черта, которая объединяет их всех: жестокость." }, { 10.91, "Если мы хотим обрести мир, нам следует изгнать кентавров из этих земель." }, { 16.36, "Тебе предстоит исполнить это нелёгкое задание." }, { 19.86, "В своих странствиях по Пустошам ты будешь убивать кентавров и собирать их уши." }, { 25.72, "Чем больше ушей, тем лучше." }, { 27.81, "Принеси их мне." }, { 28.95, "Если, ты исполнишь это во славу и во имя Альянса, мы будем на шаг ближе к завершению этой войны." } } }, t = { d = 15.2, v = "human-male#50", n = { x = 138 }, c = { x = { { 0.00, "Ах, уши..." }, { 0.93, "Уши!" }, { 1.40, "Что ж, прекрасно." }, { 2.87, "Бесспорно, услуги, оказанные тобой Альянсу, весьма велики." }, { 7.99, "Поверь, та кровь, что была пролита тобой в Пустошах, поможет спасти множество жизней." } } } } },
    [1388] = { d = 13.7, v = "scourge-male#82", n = { x = 113 }, c = { x = { { 0.00, "Всё прошло точно по плану." }, { 2.61, "Теперь отнеси эту сыворотку правды стражу смерти Зредусу, и он покажет, как ею... правильно воспользоваться." }, { 13.15, "Ха-ха!" } } }, t = { d = 11.2, g = 1, v = "scourge-male", n = { m = 89, f = 91 }, c = { m = { { 0.00, "Я знал, что старина Фаустин что-нибудь придумает!" }, { 4.80, "Ты ему очень помог, я даже не сомневаюсь." }, { 8.97, "А теперь к делу, верно?" } }, f = { { 0.00, "Я знал, что старина Фаустин что-нибудь придумает!" }, { 4.55, "Ты ему очень помогла, я даже не сомневаюсь." }, { 8.69, "А теперь к делу, верно?" } } } } },
    [1389] = { d = 40.4, v = "creature/lostone", n = { x = 390 }, c = { x = { { 0.00, "Заблудшие, живущие в Болотном пристанище, на вид ничем от нас не отличаются, но на самом деле это чудовища... лишившиеся рассудка в пути до Азерота." }, { 12.29, "Когда-то они были нашими братьями." }, { 15.30, "Теперь они живут в Болотном пристанище, к востоку отсюда, захватывая и убивая любого, кто попадётся под руку." }, { 24.42, "Сейчас они украли одну из наших святынь – кристаллы дренейского аметиста." }, { 30.68, "У нас не хватает сил ворваться в Святилище и вернуть себе нашу реликвию, но без неё... мы тоже вскоре утратим свой путь." } } }, t = { d = 3.9, v = "creature/lostone", n = { x = 31 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.64, "Мы перед тобой в долгу." } } } } },
    [1391] = { d = 28.9, v = "scourge-male", n = { x = 279 }, c = { x = { { 0.00, "Мы должны действовать тайно." }, { 2.44, "В конце концов ты же не можешь войти и заставить этого олуха выпить состав Фаустина?" }, { 9.68, "Но от выпивки ни один человек не откажется." }, { 13.34, "Я возьму сыворотку Фаустина и замешаю её в эль." }, { 17.30, "Сомнений нет, бедняга без колебаний выпьет предложенную бурду." }, { 22.56, "Спеши в Каменор на Болото Печали." }, { 25.45, "И никому не рассказывай о нашем задании..." } } }, t = { d = 10.8, g = 1, v = "human-male#50", n = { m = 129, f = 131 }, c = { m = { { 0.00, "Ты принёс мне попить?" }, { 1.38, "Как мило с твоей стороны." }, { 3.13, "Мне не давали даже губы смочить вот уже несколько дней." }, { 6.85, "Позволь мне утолить жажду, и я расскажу обо всём, что узнал..." } }, f = { { 0.00, "Ты принесла мне попить?" }, { 1.54, "Как мило с твоей стороны." }, { 3.25, "Мне не давали даже губы смочить вот уже несколько дней." }, { 6.92, "Позволь мне утолить жажду, и я расскажу обо всём, что узнал..." } } } } },
    [1392] = { d = 10.2, v = "narrator", n = { x = 113 }, c = { x = { { 0.00, "Нобору много месяцев не давал житья дренеям Прибежища, и его дубина стала символом жестокости, которую они претерпели от рук Заблудших." } } }, t = { d = 27.4, g = 1, v = "creature/lostone", n = { m = 270, f = 272 }, c = { m = { { 0.00, "Ты добыл оружие ужасного Нобору?" }, { 2.69, "Так значит он мёртв?" }, { 4.28, "Это праздник для всего Убежища!" }, { 6.89, "Нобору и его банда многие годы терроризировали нас, бродя по болотам и убивая любого дренея, который попадался на пути." }, { 16.62, "Он ставил под угрозу само наше выживание, но нам не хватало сил справиться с ним самостоятельно." }, { 24.24, "Ты оказал нам большую услугу." } }, f = { { 0.00, "Ты добыла оружие ужасного Нобору?" }, { 2.84, "Так значит он мёртв?" }, { 4.49, "Это праздник для всего Убежища!" }, { 7.18, "Нобору и его банда многие годы терроризировали нас, бродя по болотам и убивая любого дренея, который попадался на пути." }, { 17.20, "Он ставил под угрозу само наше выживание, но нам не хватало сил справиться с ним самостоятельно." }, { 25.05, "Ты оказала нам большую услугу." } } } } },
    [1393] = { d = 19.1, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Помогите!" }, { 0.67, "Эти твари хотят меня съесть!" }, { 2.68, "Если ты поможешь мне выбраться отсюда, то получишь великое сокровище!" }, { 7.38, "Оно лежит в моём лагере, в болотах к северу от Каменора, но только я знаю, как открыть сейф, в котором оно находится." }, { 15.30, "Если ты поможешь мне, я научу тебя, как открыть этот сейф." } } }, t = { d = 17.1, v = "narrator", n = { x = 180 }, c = { x = { { 0.00, "Замочная скважина этого сейфа залита чёрной смолой." }, { 4.07, "Открыть его невозможно." }, { 5.97, "Но Гален рассказал вам о секретном замке на днище сейфа..." }, { 10.53, "..." }, { 10.81, "Быстро осмотрев сейф, вы находите задвижку." }, { 14.18, "Задвижка отодвинута, и сейф открывается." } } } } },
    [1394] = { d = 29.8, g = 1, v = "scourge-male#83", n = { m = 280, f = 283 }, c = { m = { { 0.00, "Ты хорошо справился." }, { 1.79, "Ты прошёл все мои испытания и те, что были до этого." }, { 6.22, "Возвращайся к Дорну в Тысячу Игл." }, { 9.09, "Он непременно заметит перемены, произошедшие с твоим телом, разумом и духом, и поймёт, что твои усилия достойны награды." }, { 19.43, "Всегда храни в себе ту гармонию, которой ты достиг в этих испытаниях, и тогда в будущем Дорн сможет испытать тебя ещё раз." } }, f = { { 0.00, "Ты хорошо справилась." }, { 1.79, "Ты прошла все мои испытания и те, что были до этого." }, { 6.10, "Возвращайся к Дорну в Тысячу Игл." }, { 8.86, "Он непременно заметит перемены, произошедшие с твоим телом, разумом и духом, и поймёт, что твои усилия достойны награды." }, { 18.76, "Всегда храни в себе ту гармонию, которой ты достигла в этих испытаниях, и тогда в будущем Дорн сможет испытать тебя ещё раз." } } }, t = { d = 23.8, g = 1, v = "tauren-male#68", n = { m = 201, f = 204 }, c = { m = { { 0.00, "А." }, { 0.26, "Давненько ты не заглядывал в мой дом." }, { 3.66, "Кажется, прошло уже много лун с тех пор, как ты сделал первый шаг на своём пути." }, { 11.15, "А теперь ты вернулся намного сильнее, чем раньше..." }, { 16.01, "И намного мудрее." }, { 17.71, "Это хорошо." }, { 18.90, "И тебе полагается достойная награда за все испытания." } }, f = { { 0.00, "А." }, { 0.25, "Давненько ты не заглядывала в мой дом." }, { 3.66, "Кажется, прошло уже много лун с тех пор, как ты сделала первый шаг на своём пути." }, { 11.05, "А теперь ты вернулась намного сильнее, чем раньше..." }, { 15.87, "И намного мудрее." }, { 17.54, "Это хорошо." }, { 18.70, "И тебе полагается достойная награда за все испытания." } } } } },
    [1395] = { d = 36.5, v = "human-male", n = { x = 445 }, c = { x = { { 0.00, "Этот ящик с камнями силы нужно доставить в Крепость Стражей Пустоты, в Выжженные земли." }, { 6.04, "Их сила будет сохраняться не так-то долго, так что мы не можем отправить их следующим караваном." }, { 12.51, "Тебе следует отнести их как можно скорее." }, { 15.38, "Отдай их интенданту Лунгерцу в Крепости Стражей Пустоты." }, { 19.23, "Чтобы достичь крепости, тебе следует направиться на восток через Перевал Мёртвого Ветра, затем далее через Болото Печали, потом свернуть на юг через Выжженные земли." }, { 30.58, "Однако осторожнее." }, { 31.86, "Твой путь проляжет через опасные земли, но цель должна быть достигнута." } } }, t = { d = 9.1, v = "human-male", n = { x = 84 }, c = { x = { { 0.00, "О, камни силы!" }, { 1.33, "Маги будут рады увидеть их!" }, { 3.82, "Большое спасибо." }, { 5.30, "Я знаю, что твой путь из Темнолесья был нелёгок." } } } } },
    [1396] = { d = 19.0, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Мой караван направлялся к восточному побережью, но до места так и не добрался." }, { 5.42, "Заблудшие атаковали нас, перебив стражу и уничтожив припасы." }, { 9.69, "Выжить удалось только мне." }, { 11.60, "Я обещал сохранить оставшиеся товары, но вокруг полно чудовищ." }, { 16.06, "Прошу тебя, помоги мне защитить мой лагерь!" } } }, t = { d = 6.4, v = "human-male", n = { x = 66 }, c = { x = { { 0.00, "Судя по звукам, твари убрались." }, { 2.48, "Благодарю тебя." }, { 3.72, "Теперь-то, надеюсь, они не вернутся!" } } } } },
    [1398] = { d = 28.1, v = "human-male", n = { x = 319 }, c = { x = { { 0.00, "Я – твой должник." }, { 1.22, "В твоей груди бьётся великодушное сердце." }, { 4.18, "А теперь – смею ли ещё раз попросить тебя о помощи?" }, { 7.84, "Чтобы добраться до Стражей Пустоты, я должен починить эту повозку, а для этого мне необходимо дерево." }, { 15.11, "Сухое, прямое дерево, а не те рыхлые и скрюченные кусты, которые растут на болотах." }, { 21.09, "Отправляйся на восточное побережье, поищи там плавник, хорошо просушенный солнцем и принеси его мне." } } }, t = { d = 4.5, v = "human-male", n = { x = 39 }, c = { x = { { 0.00, "Дерево лёгкое, но крепкое." }, { 2.50, "Спасибо, это подойдёт." } } } } },
    [1418] = { d = 26.0, g = 1, v = "orc-male", n = { x = 278 }, c = { m = { { 0.00, "Бесплодные земли суровы." }, { 1.94, "Они примыкают к территории Альянса возле озера Лок Модан, потому сообщение между Каменором и форпостом Каргата часто оказывается перерезанным." }, { 12.97, "Путник, у тебя есть шанс проявить себя." }, { 16.02, "Отправляйся в Бесплодные земли и поговори с Никой Алый Шрам, главой разведчиков Каргатского форпоста, а затем принеси мне её доклад." } }, f = { { 0.00, "Бесплодные земли суровы." }, { 1.91, "Они примыкают к территории Альянса возле озера Лок Модан, потому сообщение между Каменором и форпостом Каргата часто оказывается перерезанным." }, { 12.78, "Путница, у тебя есть шанс проявить себя." }, { 15.85, "Отправляйся в Бесплодные земли и поговори с Никой Алый Шрам, главой разведчиков Каргатского форпоста, а затем принеси мне её доклад." } } }, t = { d = 20.5, v = "orc-female#57", n = { x = 200 }, c = { x = { { 0.00, "Хелгруму нужен доклад, а?" }, { 2.14, "Я посылала гонца в Каменор около трёх дней назад." }, { 6.19, "Он что, не добрался?" }, { 7.81, "Если в Каменоре нет моего донесения, сдаётся мне, гонец сгинул." }, { 12.97, "Будем надеяться, что следующий, кого я пошлю, будет лучше подготовлен, ну или более удачлив." } } } } },
    [1419] = { d = 31.3, g = 1, v = "orc-female#57", n = { x = 299 }, c = { m = { { 0.00, "Ну и как тебе Бесплодные земли, герой?" }, { 3.23, "Жара, пылища, стаи всяких тварей?" }, { 6.17, "У тебя есть шанс прочувствовать все прелести этих земель ещё лучше." }, { 11.73, "Скальные койоты – наглые твари." }, { 14.44, "Наглые настолько, что пробираются в Каргат и воруют наши припасы." }, { 19.93, "Помоги нам избавиться от них!" }, { 22.34, "Принеси мне их челюсти, если ты соберёшь достаточно много, я поверю, что ты и вправду знаешь Бесплодные земли." } }, f = { { 0.00, "Ну и как тебе Бесплодные земли, героиня?" }, { 3.22, "Жара, пылища, стаи всяких тварей?" }, { 6.01, "У тебя есть шанс прочувствовать все прелести этих земель ещё лучше." }, { 11.31, "Скальные койоты – наглые твари." }, { 13.89, "Наглые настолько, что пробираются в Каргат и воруют наши припасы." }, { 19.12, "Помоги нам избавиться от них!" }, { 21.41, "Принеси мне их челюсти, если ты соберёшь достаточно много, я поверю, что ты и вправду знаешь Бесплодные земли." } } }, t = { d = 16.3, v = "orc-female#57", n = { x = 164 }, c = { x = { { 0.00, "Впечатляющий набор челюстей." }, { 2.37, "Теперь-то эти койоты поостерегутся подбираться к нашим припасам." }, { 7.72, "Отлично!" }, { 8.46, "Койоты из Бесплодных земель – не такая уж лёгкая добыча." }, { 13.06, "Теперь я уверена – ты сможешь тут выжить." } } } } },
    [1420] = { d = 11.0, v = "orc-female#57", n = { x = 111 }, c = { x = { { 0.00, "Я написала новое донесение для Хелгрума из Каменора, отнеси его ему." }, { 5.45, "И если ты считаешь себя гонцом – не сбейся с пути и не попадись врагам!" } } }, t = { d = 12.3, v = "orc-male", n = { x = 111 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.46, "Из донесения Ники я понял, что Альянс озабочен собственными проблемами, и, может статься, что кое-какие враги у нас общие." } } } } },
    [1421] = { d = 23.8, g = 1, v = "human-male", n = { x = 279 }, c = { m = { { 0.00, "Я был оглушён во время атаки Заблудших, но, прежде чем потерять сознание, я видел, как одну из наших повозок угоняли к Болотному пристанищу, поселению Заблудших на севере." }, { 11.73, "В этой повозке находился сундук с наиболее ценными реактивами, предназначающимися для магов Крепости Стражей Пустоты." }, { 19.85, "Путник, найди сундук, добудь эти реактивы и верни их мне." } }, f = { { 0.00, "Я был оглушён во время атаки Заблудших, но, прежде чем потерять сознание, я видел, как одну из наших повозок угоняли к Болотному пристанищу, поселению Заблудших на севере." }, { 11.55, "В этой повозке находился сундук с наиболее ценными реактивами, предназначающимися для магов Крепости Стражей Пустоты." }, { 19.53, "Путница, найди сундук, добудь эти реактивы и верни их мне." } } }, t = { d = 16.7, v = "human-male", n = { x = 197 }, c = { x = { { 0.00, "Браво!" }, { 0.51, "С этими реактивами волшебники Крепости Стражей Пустоты смогут продолжить работу." }, { 6.28, "Я не знаю, чем они там занимаются, знаю только, что это связано с Тёмным порталом в Бесплодных землях и напрямую касается безопасности всего Альянса." } } } } },
    [1422] = { d = 16.5, v = "orc-male#60", n = { x = 200 }, c = { x = { { 0.00, "Пока я буду работать над твоим оружием, почему бы тебе не поговорить с Катором?" }, { 5.40, "Он говорил, что ему нужна помощь с патрулированием побережья, и тебе бы лучше поддерживать боевую форму, а не напиваться с теми недоделками, что торчат в нашем лагере." } } }, t = { d = 10.3, g = 1, v = "orc-male#60", n = { x = 97 }, c = { m = { { 0.00, "Помолчи немного, герой." }, { 2.05, "Даже сквозь глухой рокот моря всё ещё слышно отвратительное бульканье, заменяющее рыболюдям речь." } }, f = { { 0.00, "Помолчи немного, героиня." }, { 2.23, "Даже сквозь глухой рокот моря всё ещё слышно отвратительное бульканье, заменяющее рыболюдям речь." } } } } },
    [1423] = { d = 12.5, v = "narrator", n = { x = 115 }, c = { x = { { 0.00, "Этот бочонок мал, зато прочен." }, { 2.84, "Его швы залиты жёлтым пахучим воском, а на торце выдавлены слова:" }, { 8.75, "ИНТЕНДАНТ ЛУНГЕРЦ" }, { 10.37, "КРЕПОСТЬ СТРАЖЕЙ ПУСТОТЫ" } } }, t = { d = 8.2, v = "human-male", n = { x = 87 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.27, "На пути из Темнолесья теряется так много провизии." }, { 5.21, "Как хорошо, что кое-что удаётся вернуть." } } } } },
    [1424] = { d = 35.9, v = "orc-male", n = { x = 377 }, c = { x = { { 0.00, "Вождь послал нас разузнать, что творится в Храме Атал'Хаккара." }, { 4.85, "Тролли Атал'ай – племя тёмных заклинателей, известных тем, что используют запретную магию." }, { 11.90, "Можешь себе представить, как мы были поражены, когда узнали что храм затоплен." }, { 18.11, "Теперь его сторожат зелёные драконы, которые утверждают, что они защитники Азерота." }, { 24.74, "Мы должны выяснить, что произошло." }, { 27.45, "Исследуй окрестности озера Слёз и собери артефакты Атал'ай." }, { 32.15, "С их помощью я смогу собрать всю картину воедино." } } }, t = { d = 6.1, g = 1, v = "orc-male", n = { x = 50 }, c = { m = { { 0.00, "Твоё усердие в поисках артефактов Аталаи достойно похвалы, герой." } }, f = { { 0.00, "Твоё усердие в поисках артефактов Аталаи достойно похвалы, героиня." } } } } },
    [1425] = { d = 29.3, v = "human-male", n = { x = 358 }, c = { x = { { 0.00, "Пока я чиню эту повозку, выполни для меня ещё одно, последнее задание." }, { 4.80, "Я собрал наиболее важные припасы, уцелевшие после набегов огров." }, { 9.19, "Доставь их в Крепость Стражей Пустоты." }, { 11.77, "Она выстроена в холмах, на севере Выжженных земель, для наблюдения за Тёмным порталом." }, { 17.47, "Добраться туда можно по восточной дороге." }, { 20.29, "Когда она разветвится, сверни на юг к Выжженным землям, а потом налево на следующей развилке." }, { 26.54, "Не сходи с дороги, и не теряй бдительности." } } }, t = { d = 12.7, v = "human-male", n = { x = 138 }, c = { x = { { 0.00, "Что?" }, { 0.34, "Груз из каравана Биггса?" }, { 2.14, "Мы думали, он пропал вместе с караваном." }, { 5.16, "Спасибо." }, { 5.83, "Надеюсь там кристаллы Азоры, этот реактив, нам крайне необходим, а наш запас подходит к концу." } } } } },
    [1426] = { d = 32.3, g = 1, v = "orc-male#60", n = { x = 304 }, c = { m = { { 0.00, "Мне не нравится ни море, ни твари, что лезут из его глубин." }, { 5.05, "Море могущественно, но слепо, бесчувственно и жестоко." }, { 9.65, "С какой радостью я истреблял бы этих рыболюдей сотнями, будь у меня возможность." }, { 16.47, "Но мне принесёт и некоторую радость зрелище их гибели от рук тех, кто выполняет волю Орды." }, { 23.97, "От твоих рук, герой." }, { 25.73, "Скольких ты сможешь убить?" }, { 28.03, "Хочешь ли рискнуть и сразиться с сильнейшими из них?" } }, f = { { 0.00, "Мне не нравится ни море, ни твари, что лезут из его глубин." }, { 5.04, "Море могущественно, но слепо, бесчувственно и жестоко." }, { 9.63, "С какой радостью я истреблял бы этих рыболюдей сотнями, будь у меня возможность." }, { 16.43, "Но мне принесёт и некоторую радость зрелище их гибели от рук тех, кто выполняет волю Орды." }, { 23.92, "От твоих рук, героиня." }, { 25.83, "Скольких ты сможешь убить?" }, { 28.12, "Хочешь ли рискнуть и сразиться с сильнейшими из них?" } } }, t = { d = 37.7, g = 1, v = "orc-male#60", n = { m = 356, f = 358 }, c = { m = { { 0.00, "Море безбрежно и безжалостно, но ты запятнал его кровью его собственных порождений." }, { 6.72, "Рыболюди знают, что такое боль." }, { 9.24, "Их тупость заставит их сплотить ряды после того разгрома, который ты им учинил, и это хорошо." }, { 16.83, "Пусть их булькающие крики заглушают шум моря по ночам." }, { 21.16, "А я буду улыбаться каждый раз как услышу, что кто-то из них замолк." }, { 26.50, "Возвращайся ко мне, если вдруг захочется поубивать ещё рыболюдей." }, { 32.74, "Я с удовольствием тебя вознагражу за это." } }, f = { { 0.00, "Море безбрежно и безжалостно, но ты запятнала его кровью его собственных порождений." }, { 7.12, "Рыболюди знают, что такое боль." }, { 9.77, "Их тупость заставит их сплотить ряды после того разгрома, который ты им учинила, и это хорошо." }, { 17.79, "Пусть их булькающие крики заглушают шум моря по ночам."