    [1429] = { d = 35.4, g = 1, v = "orc-male", n = { m = 370, f = 371 }, c = { m = { { 0.00, "Пока ты сражался с опасностями озера Слёз, один из моих разведчиков вернулся со свитком из сушёного мяса с кровавыми письменами." }, { 10.12, "Мне кажется это официальный приговор жрецу племени Атал'ай." }, { 14.92, "Этот жрец был приговорён племенем к участи худшей, чем смерть, – он был изгнан на север во Внутренние земли, жить среди троллей племени Сухокожих." }, { 26.33, "Я соберу эти артефакты, а тебе предстоит найти изгнанника и выяснить их назначение." }, { 33.00, "После этого возвращайся ко мне." } }, f = { { 0.00, "Пока ты сражалась с опасностями озера Слёз, один из моих разведчиков вернулся со свитком из сушёного мяса с кровавыми письменами." }, { 10.05, "Мне кажется это официальный приговор жрецу племени Атал'ай." }, { 14.79, "Этот жрец был приговорён племенем к участи худшей, чем смерть, – он был изгнан на север во Внутренние земли, жить среди троллей племени Сухокожих." }, { 26.05, "Я соберу эти артефакты, а тебе предстоит найти изгнанника и выяснить их назначение." }, { 32.63, "После этого возвращайся ко мне." } } }, t = { d = 17.5, g = 1, v = "troll-male#77", n = { m = 175, f = 177 }, c = { m = { { 0.00, "Ты принёс мне артефакты призыва Атал'ай?" }, { 3.28, "Я вижу, Джаммал'ан Пророк ведёт своих последователей из Чертога Крови навстречу выбранному ими року." }, { 11.63, "Интересно, вернулся ли Хаккар в свой храм?" }, { 15.06, "Встретили ли они свою судьбу?" } }, f = { { 0.00, "Ты принесла мне артефакты призыва Атал'ай?" }, { 3.48, "Я вижу, Джаммал'ан Пророк ведёт своих последователей из Чертога Крови навстречу выбранному ими року." }, { 11.76, "Интересно, вернулся ли Хаккар в свой храм?" }, { 15.16, "Встретили ли они свою судьбу?" } } } } },
    [1430] = { d = 27.3, v = "orc-male", n = { x = 294 }, c = { x = { { 0.00, "Среди моих покупателей крайне высок спрос на сочное крабье мясо, особенно мясо чудовищного краба." }, { 7.62, "Если ты планируешь направиться на побережье, то можешь ещё и с выгодой прогуляться туда, если ты принесёшь мне несколько крабьих ног, чтобы я переправил их в Оргриммар." }, { 20.29, "Побережье находится к востоку отсюда, а крабы там просто кишат, что на берегу, что под водой." } } }, t = { d = 14.9, v = "orc-male", n = { x = 140 }, c = { x = { { 0.00, "О!" }, { 0.24, "Замечательно, я жду не дождусь, когда попробую это мясо, должным образом приготовленное на открытом огне." }, { 9.45, "Возьми с собой в дорогу малую толику, вкус просто несравненный!" } } } } },
    [1431] = { d = 34.0, g = 1, v = "orc-male", n = { x = 331 }, c = { m = { { 0.00, "Слушай внимательно, герой." }, { 2.15, "Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное." }, { 9.40, "Мы – народ гордый, и война с людьми истощила даже терпение Тралла." }, { 14.78, "Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего." }, { 21.03, "В то же время он тонкий дипломат." }, { 23.68, "Он умеет обращаться с людьми." }, { 26.05, "Если тебе это интересно, поговори с Кельдраном." }, { 29.92, "Его лачуга стоит у западного входа в город." } }, f = { { 0.00, "Слушай внимательно, героиня." }, { 2.33, "Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное." }, { 9.69, "Мы – народ гордый, и война с людьми истощила даже терпение Тралла." }, { 15.15, "Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего." }, { 21.48, "В то же время он тонкий дипломат." }, { 24.18, "Он умеет обращаться с людьми." }, { 26.58, "Если тебе это интересно, поговори с Кельдраном." }, { 30.51, "Его лачуга стоит у западного входа в город." } } }, t = { d = 39.4, g = 1, v = "orc-male", n = { x = 370 }, c = { m = { { 0.00, "Патанни, герой!" }, { 1.35, "Меня зовут Кельдран, я изучаю магию... и другие тайные искусства." }, { 6.92, "Дело, по поводу которого ты здесь, требует большей тонкости, чем те, которыми тебе приходилось заниматься раньше." }, { 16.33, "Однако это не значит, что ты не можешь нам помочь." }, { 20.55, "Пожалуйста, устраивайся поудобнее." }, { 23.41, "Я расскажу тебе, зачем вождю понадобилась моя... и твоя помощь." }, { 28.83, "Всё начинается со впечатления." }, { 31.31, "Какой себя видит Орда." }, { 33.34, "Какими видят нас наши союзники." }, { 36.05, "И, главное, какими нас видят наши враги." } }, f = { { 0.00, "Патанни, героиня!" }, { 1.49, "Меня зовут Кельдран, я изучаю магию... и другие тайные искусства." }, { 6.99, "Дело, по поводу которого ты здесь, требует б