    [1432] = { d = 35.3, v = "orc-male", n = { x = 368 }, c = { x = { { 0.00, "Альянс всё расширяет свои владения в Калимдоре." }, { 3.72, "Из-за этого может сложиться впечатление, что Орда вступает в союз с Пылающим Легионом." }, { 10.52, "Вождь не может этого допустить." }, { 12.98, "И я, с его благословения, буду отвечать за их изгнание." }, { 17.26, "У меня есть свои агенты в Пустошах, на Заставе Скитающихся Духов – это к северу от большого Кладбища кодо." }, { 25.61, "Ступай на юг от Обугленной долины в Когтистых горах, и увидишь заставу." }, { 31.15, "Когда прибудешь туда, разыщи Такату Стального Клинка." } } }, t = { d = 34.0, g = 1, v = "orc-male#60", n = { x = 335 }, c = { m = { { 0.00, "Приветствую, герой!" }, { 1.61, "У тебя есть вести из Оргриммара?" }, { 4.24, "Это хорошо." }, { 5.27, "В здешних краях всё провоняло демонами – сильнее, чем кентавровым навозом." }, { 11.26, "Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться." }, { 18.21, "Получается, что мы вроде как помогаем кентаврам." }, { 22.09, "Это мне не по нутру, но всё это на благо Орды, так что я выполняю свой долг перед вождём, даже если ради этого приходится поддерживать чернокнижников." } }, f = { { 0.00, "Приветствую, героиня!" }, { 1.74, "У тебя есть вести из Оргриммара?" }, { 4.34, "Это хорошо." }, { 5.35, "В здешних краях всё провоняло демонами – сильнее, чем кентавровым навозом." }, { 11.28, "Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться." }, { 18.15, "Получается, что мы вроде как помогаем кентаврам." }, { 21.98, "Это мне не по нутру, но всё это на благо Орды, так что я выполняю свой долг перед вождём, даже если ради этого приходится поддерживать чернокнижников." } } } } },
    [1433] = { d = 29.8, v = "orc-male#60", n = { x = 324 }, c = { x = { { 0.00, "Чернокнижники из клана Пылающего Клинка преданы злу до мозга костей." }, { 5.20, "Души их осквернены, и единственный способ их остановить – это уничтожить." }, { 10.75, "Кельдран отправил со мной Маурина, потому что он знает многое о Пылающем Клинке и разбирается в уловках чернокнижников." }, { 19.72, "Он борется с Клинком, а на мою долю остаются прочие козни демонов тут, в Пустошах." }, { 26.02, "Поговори с Маурином, он посвятит тебя в свои планы." } } }, t = { d = 29.2, g = 1, v = "scourge-male#82", n = { x = 255 }, c = { m = { { 0.00, "Ах, да!" }, { 0.65, "Нам всегда пригодится помощь тех, кто предан вождю." }, { 5.29, "Меня зовут Маурин." }, { 7.08, "Я здесь по просьбе Кельдрана и нашего юного вождя, Тралла." }, { 12.36, "Мальчику нужна помощь в борьбе против врагов, угрожающих его власти." }, { 18.71, "Подойди-ка поближе, герой." }, { 21.15, "Я изложу тебе свои планы касательно ликвидации этого гнойного нарыва, Пылающего Клинка." } }, f = { { 0.00, "Ах, да!" }, { 0.65, "Нам всегда пригодится помощь тех, кто предан вождю." }, { 5.29, "Меня зовут Маурин." }, { 7.08, "Я здесь по просьбе Кельдрана и нашего юного вождя, Тралла." }, { 12.36, "Мальчику нужна помощь в борьбе против врагов, угрожающих его власти." }, { 18.71, "Подойди-ка поближе, героиня." }, { 21.31, "Я изложу тебе свои планы касательно ликвидации этого гнойного нарыва, Пылающего Клинка." } } } } },
    [1434] = { d = 33.2, v = "orc-male#60", n = { x = 327 }, c = { x = { { 0.00, "Влияние демонов возникает не на пустом месте." }, { 3.73, "Нужен какой-то изъян, который позволяет злу войти в тебя." }, { 8.48, "Может быть, слабость духа, или излишнее стремление к власти, или жажда мести..." }, { 15.07, "Когда мы поддаёмся боли, то позволяем злу взять над нами верх – такому злу, как сатиры." }, { 21.94, "Они связаны с Пылающим Клинком, и Тралл хочет, чтобы их перебили." }, { 27.28, "Разыщи их на северо-востоке и возвращайся ко мне, когда сумеешь их изгнать." } } }, t = { d = 15.4, g = 1, v = "orc-male#60", n = { m = 146, f = 147 }, c = { m = { { 0.00, "Молодец, герой!" }, { 1.34, "В тебе есть доблесть и преданность делу." }, { 4.67, "Когда мы покончим с нашими делами в Пустошах, вождь непременно узнает о том, что ты помогал нам выполнять его волю." }, { 14.10, "Благодарю тебя!" } }, f = { { 0.00, "Молодец, героиня!" }, { 1.47, "В тебе есть доблесть и преданность делу." }, { 4.78, "Когда мы покончим с нашими делами в Пустошах, вождь непременно узнает о том, что ты помогала нам выполнять его волю." }, { 14.19, "Благодарю тебя!" } } } } },
    [1435] = { d = 40.2, v = "scourge-male#82", n = { x = 359 }, c = { x = { { 0.00, "Этих жалких тварей лучше всего предать смерти." }, { 4.49, "Но, когда имеешь дело с теми, кто присягнул тьме, недостаточно просто убивать." }, { 11.72, "Возьми этот самоцвет." }, { 13.80, "Приведи его в действие, когда один из негодяев из клана Пылающего Клинка будет близок к смерти." }, { 22.78, "Заклятие вытянет осквернённый дух из жертвы, и у тебя в руках окажется одушевлённый самоцвет." }, { 31.18, "Принеси мне эти одушевлённые самоцветы, я с ними разберусь." }, { 36.58, "Ступай же, и постарайся избегнуть смерти!" } } }, t = { d = 25.6, g = 1, v = "scourge-male#82", n = { m = 237, f = 238 }, c = { m = { { 0.00, "А, ты вернулся с победой!" }, { 2.11, "Это хорошо." }, { 3.17, "Давай сюда самоцветы, я их спрячу в надёжное место…" }, { 7.48, "У меня больше нет для тебя поручений, герой." }, { 11.25, "Отдохнёшь – поговори с Такатой." }, { 13.82, "Возможно, у него найдётся для тебя дело – а может, он попросит тебя вернуться в Оргриммар и сообщить Кельдрану, как идут дела у нас в Пустошах." } }, f = { { 0.00, "А, ты вернулась с победой!" }, { 2.11, "Это хорошо." }, { 3.13, "Давай сюда самоцветы, я их спрячу в надёжное место…" }, { 7.28, "У меня больше нет для тебя поручений, героиня." }, { 11.06, "Отдохнёшь – поговори с Такатой." }, { 13.54, "Возможно, у него найдётся для тебя дело – а может, он попросит тебя вернуться в Оргриммар и сообщить Кельдрану, как идут дела у нас в Пустошах." } } } } },
    [1436] = { d = 24.2, v = "orc-male#60", n = { x = 257 }, c = { x = { { 0.00, "Дела идут на лад." }, { 1.40, "Быть может, если мы продолжим одерживать победы над демонами и их приспешниками, вождь разрешит нам вернуться домой ещё до начала следующего сезона." }, { 12.76, "Возвращайся к Кельдрану и расскажи, чего нам удалось добиться." }, { 17.59, "Уверен, он вознаградит тебя за труды." }, { 20.54, "Он будет горд, узнав, что вождь ценит его усилия." } } }, t = { d = 26.2, g = 1, v = "orc-male", n = { m = 268, f = 270 }, c = { m = { { 0.00, "Тебе удалось добиться успеха, да ещё какого!" }, { 3.61, "Спасибо тебе." }, { 4.77, "Благодарю тебя за труды, за потраченное время и за то, что ты с пониманием отнёсся к моей просьбе." }, { 12.50, "Тралл стремится к миру между Ордой и Альянсом и потому заботится, чтобы мы выглядели достойно в глазах противника." }, { 21.68, "Не следует провоцировать новые конфликты." }, { 25.00, "Я твой должник!" } }, f = { { 0.00, "Тебе удалось добиться успеха, да ещё какого!" }, { 3.61, "Спасибо тебе." }, { 4.76, "Благодарю тебя за труды, за потраченное время и за то, что ты с пониманием отнеслась к моей просьбе." }, { 12.69, "Тралл стремится к миру между Ордой и Альянсом и потому заботится, чтобы мы выглядели достойно в глазах противника." }, { 21.85, "Не следует провоцировать новые конфликты." }, { 25.17, "Я твой должник!" } } } } },
    [1437] = { d = 35.4, v = "nightelf-male#55", n = { x = 405 }, c = { x = { { 0.00, "Приветствую тебя." }, { 1.28, "Я – Валарриэль." }, { 2.38, "Я прибыл сюда, чтобы установить местопребывание двух пропавших торговцев из почтенной дарнасской семьи – дома Малем." }, { 10.66, "Глава дома опасается самого худшего; я обязан выяснить всё, что могу, о его пропавших детях." }, { 17.34, "Правда, поиски Тираниса и Далинды я ещё не начал, но надеюсь, что не задержусь здесь надолго." }, { 23.89, "Последнее, что мне довелось слышать о них – то, что несколько недель назад они миновали Когтистые горы." }, { 31.22, "Если найдёшь их повозку, прошу тебя, немедленно дай мне знать." } } }, t = { d = 22.8, v = "narrator", n = { x = 231 }, c = { x = { { 0.00, "Судя по виду повозки, она подверглась воздействию как грубой силы, так и чар." }, { 6.04, "Похоже, битва была короткой, и у одной из сторон не было никаких шансов – не было даже возможности отразить удар." }, { 15.02, "Ни трупов, ни следов крови нигде не видно." }, { 18.39, "Кто бы ни напал на торговцев, действовал он весьма умело..." } } } } },
    [1438] = { d = 36.2, g = 1, v = "nightelf-male#55", n = { m = 402, f = 404 }, c = { m = { { 0.00, "Постарайся разыскать Далинду и Тираниса." }, { 2.92, "Начни поиски с той самой крепости, о которой ты говорил, а я пока что свяжусь с Дарнассом и изложу ситуацию." }, { 10.69, "Что бы ты ни обнаружил, немедленно дай мне знать." }, { 14.06, "Я хотел ещё кое-что сказать тебе." }, { 16.52, "Дело в том, что моё начальство весьма обеспокоено действиями Тираниса и причинами, которые заставили его отправиться сюда." }, { 25.27, "Чрезвычайно важно найти Далинду и доставить её домой." }, { 29.16, "Целой и невредимой, по возможности." }, { 31.69, "А вот Тираниса следовало бы сначала... проверить." } }, f = { { 0.00, "Постарайся разыскать Далинду и Тираниса." }, { 3.00, "Начни поиски с той самой крепости, о которой ты говорила, а я пока что свяжусь с Дарнассом и изложу ситуацию." }, { 11.08, "Что бы ты ни обнаружила, немедленно дай мне знать." }, { 14.62, "Я хотел ещё кое-что сказать тебе." }, { 17.16, "Дело в том, что моё начальство весьма обеспокоено действиями Тираниса и причинами, которые заставили его отправиться сюда." }, { 26.17, "Чрезвычайно важно найти Далинду и доставить её домой." }, { 30.18, "Целой и невредимой, по возможности." }, { 32.78, "А вот Тираниса следовало бы сначала... проверить." } } }, t = { d = 37.4, g = 1, v = "nightelf-female#52", n = { x = 437 }, c = { m = { { 0.00, "Благодарение Элуне, хоть кто-то пришёл на помощь!" }, { 3.22, "Прошу тебя, герой, помоги мне." }, { 5.31, "Орки Пылающего Клинка схватили меня и моего брата Тираниса и притащили сюда." }, { 10.51, "Мне кажется, они собираются принести меня в жертву своим хозяевам-демонам!.." }, { 15.64, "Я знала, что наше путешествие в Пустоши – это ошибка, но Тиранис так настаивал... в последнее время он особенно увлёкся потаёнными знаниями, хотя многим это не нравилось." }, { 26.81, "Он решил отправиться в эти края именно после того, как узнал, что здесь появляются демоны..." }, { 32.96, "Боюсь, с ним случилось что-то скверное... очень скверное!" } }, f = { { 0.00, "Благодарение Элуне, хоть кто-то пришёл на помощь!" }, { 3.28, "Прошу тебя, героиня, помоги мне." }, { 5.53, "Орки Пылающего Клинка схватили меня и моего брата Тираниса и притащили сюда." }, { 10.82, "Мне кажется, они собираются принести меня в жертву своим хозяевам-демонам!.." }, { 16.05, "Я знала, что наше путешествие в Пустоши – это ошибка, но Тиранис так настаивал... в последнее время он особенно увлёкся потаёнными знаниями, хотя многим это не нравилось." }, { 27.43, "Он решил отправиться в эти края именно после того, как узнал, что здесь появляются демоны..." }, { 33.69, "Боюсь, с ним случилось что-то скверное... очень скверное!" } } } } },
    [1439] = { d = 32.1, v = "nightelf-female#52", n = { x = 371 }, c = { x = { { 0.00, "Орки перебили нашу охрану и слуг, а потом приволокли нас сюда." }, { 4.22, "Ты представить себе не можешь, что с ними сделали!" }, { 7.59, "Я думала, нас тоже прикончат на месте – но, как выяснилось, у орков были на нас другие планы." }, { 13.79, "Тиранис пытался поговорить с ними." }, { 16.14, "Наверное, он думал, что его знания тайных искусств произведут на орков впечатление." }, { 21.74, "Не знаю уж, почему." }, { 23.07, "Прошу тебя, помоги!" }, { 24.45, "Я не могу уйти, пока не узнаю, что случилось с моим братом." }, { 28.49, "Найди его – или хотя бы узнай о его судьбе." }, { 31.56, "Умоляю!.." } } }, t = { d = 31.4, g = 1, v = "nightelf-female#52", n = { m = 360, f = 362 }, c = { m = { { 0.00, "Это ужасно!.." }, { 0.98, "Но, полагаю, у тебя не было другого выхода." }, { 3.97, "Если бы не ты, его всё равно убили бы..." }, { 6.71, "Наверное, я должна поблагодарить тебя." }, { 9.33, "Прости, если это звучит не слишком искренне: думаю, ты понимаешь, почему." }, { 14.40, "Теперь, когда я знаю, какая судьба постигла моего несчастного брата, думаю, пора бежать отсюда." }, { 21.05, "Если ты ещё не передумал, я с радостью воспользуюсь твоей помощью и покину это страшное место." }, { 27.46, "Когда будешь готов, скажи мне: мы тут же отправимся в путь." } }, f = { { 0.00, "Это ужасно!.." }, { 0.97, "Но, полагаю, у тебя не было другого выхода." }, { 3.96, "Если бы не ты, его всё равно убили бы..." }, { 6.70, "Наверное, я должна поблагодарить тебя." }, { 9.32, "Прости, если это звучит не слишком искренне: думаю, ты понимаешь, почему." }, { 14.38, "Теперь, когда я знаю, какая судьба постигла моего несчастного брата, думаю, пора бежать отсюда." }, { 21.02, "Если ты ещё не передумала, я с радостью воспользуюсь твоей помощью и покину это страшное место." }, { 27.48, "Когда будешь готова, скажи мне: мы тут же отправимся в путь." } } } } },
    [1440] = { d = 14.9, g = 1, v = "nightelf-female#52", n = { m = 153, f = 155 }, c = { m = { { 0.00, "Итак, время пришло?.." }, { 1.63, "Ценю твои усилия и благодарю тебя за всё, что ты сделал для меня и моей семьи." }, { 7.36, "Что ж, если ты готов, то и мне тут больше нечего делать." }, { 11.40, "Отправимся в путь по первому твоему слову." } }, f = { { 0.00, "Итак, время пришло?.." }, { 1.68, "Ценю твои усилия и благодарю тебя за всё, что ты сделала для меня и моей семьи." }, { 7.65, "Что ж, если ты готова, то и мне тут больше нечего делать." }, { 11.87, "Отправимся в путь по первому твоему слову." } } }, t = { d = 31.8, v = "nightelf-male#55", n = { x = 397 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.06, "Далинда благополучно добралась до Высоты Найджела и чувствует себя гораздо лучше, чем я смел надеяться." }, { 7.76, "Я даже не надеялся на столь благополучный исход!" }, { 10.88, "То, что ей удалось добраться сюда своими силами – добрый знак." }, { 14.93, "Надеюсь, с тобой тоже всё в порядке?.." }, { 17.46, "Мне жаль, что Тиранис не вернулся; однако всё, что с ним произошло, было плодом его собственных решений." }, { 24.16, "Далинде придётся с этим смириться – и, к тому же, разбираться с последствиями его действий, когда она вернётся в Дарнасс." } } } } },
    [1442] = { d = 40.9, g = 1, v = "nightelf-male#54", n = { m = 407, f = 406 }, c = { m = { { 0.00, "День добрый." }, { 1.00, "Чем могу помочь идущему путём Света?" }, { 3.93, "Ах да, кузнец Стилвелл... давно не виделись." }, { 7.44, "Я хорошо его помню, хотя давно о нём не слышал." }, { 11.30, "Он никогда не казался мне злодеем, поэтому остаётся думать, что его стремление получить самоцвет Кора благородно." }, { 20.24, "Если вам и правда нужен самоцвет, то придётся направиться на северо-запад Ясеневого леса." }, { 27.32, "Там, среди древних развалин, вы обнаружите Непроглядную Пучину." }, { 32.33, "В их недрах таятся наги, и они до сих пор используют такие самоцветы." }, { 37.83, "Не ходите туда в одиночку, герой." } }, f = { { 0.00, "День добрый." }, { 1.01, "Чем могу помочь идущей путём Света?" }, { 3.90, "Ах да, кузнец Стилвелл... давно не виделись." }, { 7.44, "Я хорошо его помню, хотя давно о нём не слышал." }, { 11.34, "Он никогда не казался мне злодеем, поэтому остаётся думать, что его стремление получить самоцвет Кора благородно." }, { 20.37, "Если вам и правда нужен самоцвет, то придётся направиться на северо-запад Ясеневого леса." }, { 27.52, "Там, среди древних развалин, вы обнаружите Непроглядную Пучину." }, { 32.58, "В их недрах таятся наги, и они до сих пор используют такие самоцветы." }, { 38.14, "Не ходите туда в одиночку, героиня." } } }, t = { d = 29.8, g = 1, v = "nightelf-male#54", n = { x = 277 }, c = { m = { { 0.00, "Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой." }, { 16.83, "Пусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале." }, { 23.59, "Я надеюсь, вы понимаете, что делаете, герой, ибо в руках у вас не игрушка." } }, f = { { 0.00, "Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой." }, { 16.88, "Пусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале." }, { 23.66, "Я надеюсь, вы понимаете, что делаете, героиня, ибо в руках у вас не игрушка." } } } } },
    [1444] = { d = 32.6, v = "troll-male#77", n = { x = 371 }, c = { x = { { 0.00, "Джаммал'ан Пророк приговорил меня к изгнанию из Храма Атал'Хаккара." }, { 4.93, "Некогда я считал верховного жреца достойным главой храма." }, { 9.19, "Его непоколебимая вера в своё пророчество может привести к гибели Атал'ай, если уже не привела." }, { 16.22, "Но стоило мне высказать мои сомнения, я был заклеймён как еретик и изгнан из храма." }, { 22.20, "Принесённые тобой артефакты безопасны..." }, { 25.09, "Но если Джаммал'ан нашёл нужный для ритуала призыва фетиш, то всему миру угрожает смертельная опасность." } } }, t = { d = 10.1, g = 1, v = "orc-male", n = { x = 103 }, c = { m = { { 0.00, "Давно мы с тобой не виделись, герой." }, { 2.85, "Надеюсь, твоё путешествие было удачным." }, { 5.92, "Что тебе поведал изгнанник-Атал'ай во Внутренних землях?" } }, f = { { 0.00, "Давно мы с тобой не виделись, героиня." }, { 2.95, "Надеюсь, твоё путешествие было удачным." }, { 5.97, "Что тебе поведал изгнанник-Атал'ай во Внутренних землях?" } } } } },
    [1445] = { d = 37.8, v = "orc-male", n = { x = 396 }, c = { x = { { 0.00, "Так он говорил о пророчестве Джаммал'ана?" }, { 3.18, "Духовный вождь Атал'ай верит, что когда однажды, Хаккар вернётся в Азерот из Пустоты, он дарует племени бессмертие." }, { 12.14, "По мне дураком надо быть, чтобы раньше срока вызывать светопреставление." }, { 17.79, "Но ты говоришь, этот изгой упоминал о зачарованных амулетах?" }, { 22.52, "А вот это уже напрямую меня касается." }, { 25.56, "Если среди них окажется ключ к ритуалу Атал'ай, который и привёл ко всей этой заварухе, мы должны понять его тайную силу." }, { 35.09, "Отправляйся в Храм и добудь амулеты!" } } }, t = { d = 10.2, g = 1, v = "orc-male", n = { m = 87, f = 88 }, c = { m = { { 0.00, "Отважный герой, ты доказал, что являешься одним из лучших воинов Орды." }, { 6.47, "Теперь-то мы разберёмся с этими амулетами!" } }, f = { { 0.00, "Отважная героиня, ты доказала, что являешься одним из лучших воинов Орды." }, { 6.61, "Теперь-то мы разберёмся с этими амулетами!" } } } } },
    [1446] = { d = 44.2, v = "troll-male#77", n = { x = 444 }, c = { x = { { 0.00, "Мои товарищи из клана Сухокожих не любят, когда чужаки приходят к ним домой." }, { 6.18, "Я?" }, { 6.39, "А у меня и дома-то нет." }, { 8.26, "Я жил в племени Атал'ай на Болоте Печали, но был изгнан оттуда." }, { 13.29, "У нашего духовного лидера по имени Джаммал'ан, было, как он сам говорил, \"видение\"." }, { 19.89, "Он решил, что если призвать бога Хаккара, то он дарует Атал'ай бессмертие." }, { 25.85, "Я настоятельно рекомендовал ему проявить осторожность, потому что это \"видение\" могло быть всего лишь манипуляцией, обманом!" }, { 35.69, "Я хочу отомстить за своё изгнание." }, { 38.42, "Принесите мне голову Джаммал'ана." }, { 41.08, "Может быть, тогда мой народ освободится!" } } }, t = { d = 17.9, g = 1, v = "troll-male#77", n = { m = 192, f = 193 }, c = { m = { { 0.00, "Джаммал'ан безоговорочно верил своим бредовым видениям, и именно из-за них мой народ постигла такая страшная судьба." }, { 8.93, "Спасибо, что отомстил за моё изгнание." }, { 11.82, "Я глубоко скорблю по своему народу." }, { 14.56, "У меня нет дома, в который я мог бы вернуться." } }, f = { { 0.00, "Джаммал'ан безоговорочно верил своим бредовым видениям, и именно из-за них мой народ постигла такая страшная судьба." }, { 8.70, "Спасибо, что отомстила за моё изгнание." }, { 11.58, "Я глубоко скорблю по своему народу." }, { 14.25, "У меня нет дома, в который я мог бы вернуться." } } } } },
    [1447] = { d = 12.6, v = "dwarf-male", n = { x = 119 }, c = { x = { { 0.00, "В Штормград приходили многие твои коллеги, были среди них умные, были и круглые дураки, но подобных тебе нет, не было и не надо..." }, { 10.80, "Чего ты от меня хочешь?" } } }, t = { d = 4.5, v = "dwarf-male", n = { x = 42 }, c = { x = { { 0.00, "У тебя явно была причина прийти ко мне." }, { 3.36, "Так в чём дело?" } } } } },
    [1448] = { d = 38.1, g = 1, v = "dwarf-male", n = { x = 391 }, c = { m = { { 0.00, "Когда-то я был так же молод и полон сил, как вы, герой." }, { 4.05, "Теперь я стар и не могу больше странствовать по миру." }, { 8.04, "О, сколько я всего повидал!" }, { 10.14, "Но была одна загадка, которая до сих пор волнует меня." }, { 14.26, "Во время моего последнего путешествия Лига Исследователей направила меня на поиски Храма Атал'Хаккара." }, { 21.96, "Говорили, что он расположен где-то на Болоте Печали." }, { 25.88, "Поскольку я уже был стар и немощен, то облетел эти земли на грифоне, но ничего не нашёл." }, { 32.43, "Не поможете ли старому дворфу?" }, { 34.73, "Может быть, вам повезёт больше?" } }, f = { { 0.00, "Когда-то я был так же молод и полон сил, как вы, героиня." }, { 4.31, "Теперь я стар и не могу больше странствовать по миру." }, { 8.41, "О, сколько я всего повидал!" }, { 10.57, "Но была одна загадка, которая до сих пор волнует меня." }, { 14.81, "Во время моего последнего путешествия Лига Исследователей направила меня на поиски Храма Атал'Хаккара." }, { 22.73, "Говорили, что он расположен где-то на Болоте Печали." }, { 26.76, "Поскольку я уже был стар и немощен, то облетел эти земли на грифоне, но ничего не нашёл." }, { 33.50, "Не поможете ли старому дворфу?" }, { 35.87, "Может быть, вам повезёт больше?" } } }, t = { d = 12.7, g = 1, v = "dwarf-male", n = { x = 125 }, c = { m = { { 0.00, "Храм Атал'Хаккара скрыт в глубинах озера Слёз?" }, { 3.50, "И охраняется зелёными драконами?" }, { 5.95, "Это чудесное открытие, герой!" }, { 8.33, "Очевидно, что-то ужасное случилось с этим храмом..." } }, f = { { 0.00, "Храм Атал'Хаккара скрыт в глубинах озера Слёз?" }, { 3.60, "И охраняется зелёными драконами?" }, { 6.11, "Это чудесное открытие, героиня!" }, { 8.70, "Очевидно, что-то ужасное случилось с этим храмом..." } } } } },
    [1449] = { d = 35.7, v = "dwarf-male", n = { x = 397 }, c = { x = { { 0.00, "Как я уже говорил, я пытался обнаружить храм, осматривая окрестности с высоты." }, { 5.65, "Строго говоря, я был не один..." }, { 7.95, "Я нанял грифона в небезызвестном питомнике на Заоблачном Пике во Внутренних землях." }, { 14.00, "Птицей управлял один из лучших пилотов, но в воздухе он выпал из седла и свалился в болото..." }, { 20.84, "Моя старая дырявая память не сохранила его имени, но хозяин питомника должен понять, о ком идёт речь." }, { 28.27, "Отправляйтесь туда и найдите Фалстада Громового Молота." }, { 32.34, "Хорошо бы узнать, что случилось с тем пилотом..." } } }, t = { d = 15.9, g = 1, v = "creature/falstad", n = { m = 146, f = 147 }, c = { m = { { 0.00, "Чего тебе, парень?" }, { 1.58, "Не видишь – и без тебя забот хватает?" }, { 4.58, "Чем болтаться тут без толку, лучше займись делом, герой." }, { 9.10, "Что-что случилось..." }, { 10.75, "Тролли лезут из всех щелей, вот что!" }, { 13.61, "Ну говори уже, с чем пришёл." } }, f = { { 0.00, "Чего тебе, девушка?" }, { 1.64, "Не видишь – и без тебя забот хватает?" }, { 4.64, "Чем болтаться тут без толку, лучше займись делом, героиня." }, { 9.29, "Что-что случилось..." }, { 10.93, "Тролли лезут из всех щелей, вот что!" }, { 13.79, "Ну говори уже, с чем пришла." } } } } },
    [1450] = { d = 28.6, g = 1, v = "creature/falstad", n = { m = 284, f = 284 }, c = { m = { { 0.00, "Так, значит, ты тот парень, которого наняли эти старые развалины из Лиги Исследователей?" }, { 6.74, "Так, слушай меня, герой." }, { 8.66, "Я понятия не имею, кто у них там развлекался, летая над Азеротом!" }, { 13.55, "Я что, похож на Разящего Когтя?" }, { 15.95, "Похож?" }, { 16.50, "Если тебя интересуют грифоны, так поговори с укротителем!" }, { 20.91, "Если я увижу тебя без дела, то завалю по уши настоящей работой." }, { 25.86, "Давай-давай, топай отсюда." } }, f = { { 0.00, "Так, значит, ты та девчонка, которую наняли эти старые развалины из Лиги Исследователей?" }, { 6.90, "Так, слушай меня, героиня." }, { 9.01, "Я понятия не имею, кто у них там развлекался, летая над Азеротом!" }, { 14.01, "Я что, похож на Разящего Когтя?" }, { 16.47, "Похож?" }, { 17.03, "Если тебя интересуют грифоны, так поговори с укротителем!" }, { 21.54, "Если я увижу тебя без дела, то завалю по уши настоящей работой." }, { 26.61, "Давай-давай, топай отсюда." } } }, t = { d = 26.7, v = "dwarf-male", n = { x = 288 }, c = { x = { { 0.00, "Да, конечно, я прекрасно помню о том, как послал одного из пилотов отвезти Брохана Бочкопуза." }, { 7.13, "Лиге Исследователей всегда найдётся место в моём сердце." }, { 11.43, "Мой отец участвовал в экспедиции первой исследовательской команды, обнаружившей Ульдаман." }, { 18.21, "С Броханом я отправил своего лучшего пилота по имени Рапсод Землекоп." }, { 23.61, "Ах, что за наездник это был!" }, { 25.76, "Ну, до поры..." } } } } },
    [1451] = { d = 34.5, v = "dwarf-male", n = { x = 380 }, c = { x = { { 0.00, "Рапсод всегда любил поддать лишнего." }, { 2.68, "Не поймите меня неправильно: мы, дворфы этого питомника, все любим порой принять на грудь пинту-другую доброго эля." }, { 11.87, "Но старина Землекоп любил это дело больше, чем грифоны любят летать – порой ужас что получалось." }, { 18.84, "Никто не умел летать так, как Рапсод..." }, { 21.65, "Авария с этим вашим приятелем Броханом была только первым звоночком." }, { 26.63, "После этого Землекоп покатился под горку, пришлось его уволить." }, { 31.23, "Говорят, он открыл пивнушку к востоку отсюда..." } } }, t = { d = 16.2, v = "dwarf-male", n = { x = 149 }, c = { x = { { 0.00, "И-ик!" }, { 0.52, "Я ж прям на вас смотрю, чего это вас так мотыляет из стороны в сторону?" }, { 6.33, "У меня аж морская болезнь начинается, ха-ха!" }, { 10.06, "И-ик!" }, { 10.58, "О!" }, { 10.81, "Чувствуете, дорогуша?" }, { 12.59, "Земля так и ходит ходуном." }, { 14.83, "Надо выпить!" }, { 15.95, "Ик-к!" } } } } },
    [1452] = { d = 37.3, v = "dwarf-male", n = { x = 375 }, c = { x = { { 0.00, "Ик!" }, { 0.27, "Вас послал этот старый пень Брохан?" }, { 3.16, "Как вспомню ту историю, так..." }, { 5.54, "И-ик!" }, { 6.05, "Чтобы рассказать, что там со мной случилось над этим болотом, понадобится выпить капельку для храбрости." }, { 13.88, "Полный ужас, вы не поверите!" }, { 16.20, "Ик!" }, { 16.48, "Вот что я скажу – притащите-ка мне индри... гринди... эн-гре-де-ен-ты для калимдорского коктейля, и вы обо всём услышите!" }, { 25.72, "Значится, что нужно мне..." }, { 27.81, "Потроха руха из Танариса, печень гроддока, печень железномеха из Фераласа..." }, { 33.95, "Да." }, { 34.24, "Калимдорский коктейль развяжет мне язык!" } } }, t = { d = 21.0, v = "dwarf-male", n = { x = 215 }, c = { x = { { 0.00, "Как я погляжу, у вас этих потрошков полные карманы!" }, { 3.97, "И какая беда принесла вас из Калимдора-то?" }, { 7.18, "Сейчас подождите, я сделаю вытяжку, и тогда уж расскажу всё, что вы пожелаете." }, { 13.17, "Ик!" }, { 13.45, "Меня дрожь пробирает, когда вспоминаю это клятое болото." }, { 17.90, "Ик!" }, { 18.18, "Сейчас, сейчас, почти готово дело..." } } } } },
    [1453] = { d = 28.1, v = "dwarf-male", n = { x = 338 }, c = { x = { { 0.00, "Надо сделать одну работу в Пустошах." }, { 2.57, "Это жуткое место, опоганенное кентаврами и прочими грязными тварями." }, { 7.27, "Но если ты ищешь честную работёнку на неделю, то отправляйся туда, найди Крелдига Унгора и скажи, что это я тебя прислал." }, { 15.52, "Ты найдёшь его на Высоте Найджела – он прячется в укромном лагере в горах северных Пустошей." }, { 21.75, "Держись к востоку от выхода из Когтистых гор." }, { 24.80, "Будь начеку, иначе можешь проскочить мимо лагеря." } } }, t = { d = 28.4, g = 1, v = "dwarf-male", n = { m = 308, f = 309 }, c = { m = { { 0.00, "Рад видеть, что у Горной корпорации нет недостатка ни в работе, ни в искателях приключений, готовых прийти на помощь." }, { 8.45, "Я – Крелдиг." }, { 9.38, "Это хорошо, что ты взялся помочь Горной корпорации." }, { 13.21, "В эти дни все что-то ищут – кто фамильные драгоценности потерял, кто магический предмет, кто любимых." }, { 20.54, "Да мало ли что." }, { 21.66, "Но если за дело берётся Горная корпорация, то по сходной цене она найдёт всё что угодно." } }, f = { { 0.00, "Рад видеть, что у Горной корпорации нет недостатка ни в работе, ни в искателях приключений, готовых прийти на помощь." }, { 8.58, "Я – Крелдиг." }, { 9.52, "Это хорошо, что ты взялась помочь Горной корпорации." }, { 13.47, "В эти дни все что-то ищут – кто фамильные драгоценности потерял, кто магический предмет, кто любимых." }, { 20.91, "Да мало ли что." }, { 22.05, "Но если за дело берётся Горная корпорация, то по сходной цене она найдёт всё что угодно." } } } } },
    [1454] = { d = 35.3, v = "dwarf-male", n = { x = 423 }, c = { x = { { 0.00, "Моё первое задание касается мага Карнитола – это какой-то тип из благородных, живёт в Штормграде." }, { 6.58, "Говорит, на его корабль напали морские великаны, и было это всё у северо-западного берега Пустошей." }, { 13.47, "Вместе со слугами этот тип попытался вытащить на берег один из самых ценных сундуков, но когда великаны набросились на них толпой, почёл за благо телепортировать себя и своих слуг куда подальше, а сундук, натурально, бросил." }, { 28.72, "Так вот, Карнитол хочет, чтобы мы нашли его сундук со всем содержимым и доставили ему в Штормград." } } }, t = { d = 14.2, v = "narrator", n = { x = 136 }, c = { x = { { 0.00, "Похоже, сундук вовсе не пострадал от морской воды..." }, { 4.45, "Однако он взломан." }, { 6.03, "Если тут и были магические охранные ловушки, то они явно успели сработать: края сундука обожжены." } } } } },
    [1455] = { d = 30.6, v = "narrator", n = { x = 279 }, c = { x = { { 0.00, "Любопытно, кто – или что – всё же открыло этот сундук?.." }, { 4.90, "Судя по длинным глубоким царапинам на боках и крышке, это был не человек и не великан..." }, { 12.64, "Непохоже также, чтобы отметины оставил меч или кинжал." }, { 17.53, "Кроме всего прочего, сундук пуст." }, { 20.53, "Абсолютно и непоправимо пуст." }, { 23.06, "Делать нечего: остаётся только закрыть сундук и уйти." }, { 27.80, "Крелдиг будет крайне разочарован." } } }, t = { d = 20.6, g = 1, v = "dwarf-male", n = { m = 213, f = 214 }, c = { m = { { 0.00, "Ну-с, с возвращением на Высоту Найджела." }, { 3.00, "Расскажи-ка, что тебе удалось обнаружить..." }, { 6.26, "Как?!" }, { 6.67, "Ничего?.." }, { 7.42, "Ну, дорогуша, из ничего и не выйдет ничего: боюсь, за пустой сундук никто платить не станет." }, { 14.43, "Расскажи-ка мне побольше об этих самых отметинах... царапинах, которые ты заметил." } }, f = { { 0.00, "Ну-с, с возвращением на Высоту Найджела." }, { 3.00, "Расскажи-ка, что тебе удалось обнаружить..." }, { 6.27, "Как?!" }, { 6.68, "Ничего?.." }, { 7.42, "Ну, дорогуша, из ничего и не выйдет ничего: боюсь, за пустой сундук никто платить не станет." }, { 14.44, "Расскажи-ка мне побольше об этих самых отметинах... царапинах, которые ты заметила." } } } } },
    [1456] = { d = 40.9, v = "dwarf-male", n = { x = 454 }, c = { x = { { 0.00, "Любопытно, очень любопытно..." }, { 2.16, "Что ж, может, для нас ещё не всё потеряно." }, { 5.11, "Если идти по тому же берегу на север, в сторону острова Раназьяр, там будут развалины построек ночных эльфов." }, { 13.17, "Понятное дело, развалины эти теперь под водой; к тому же, там поселились наги из клана Скользящего Плавника." }, { 21.10, "Сдаётся мне, эти наги замешаны в истории с сундуком." }, { 24.90, "Если разведчики нагов решились зайти так далеко на юг, значит, по всей видимости, они очень сильны." }, { 32.18, "Так что пожитки Карнитола, как мне кажется, надо поискать у сильнейших среди нагов: приливных охотников или морских ведьм." } } }, t = { d = 17.2, g = 1, v = "dwarf-male", n = { m = 189, f = 190 }, c = { m = { { 0.00, "Просто роскошно!" }, { 1.28, "Тебе удалось найти пожитки Карнитола!" }, { 4.19, "От этих проклятущих нагов вечно одни проблемы." }, { 7.76, "Я бы предпочёл с Ордой воевать, чем с ними связываться, честно тебе говорю." }, { 13.37, "Поверь, ты оказал Горной корпорации огромную услугу!" } }, f = { { 0.00, "Просто роскошно!" }, { 1.27, "Тебе удалось найти пожитки Карнитола!" }, { 4.15, "От этих проклятущих нагов вечно одни проблемы." }, { 7.70, "Я бы предпочёл с Ордой воевать, чем с ними связываться, честно тебе говорю." }, { 13.25, "Поверь, ты оказала Горной корпорации огромную услугу!" } } } } },
    [1457] = { d = 26.6, v = "dwarf-male", n = { x = 306 }, c = { x = { { 0.00, "Послушай, доставь-ка вещички Карнитола Ройттену в Стальгорн: он тебе неплохо заплатит." }, { 6.12, "Только ты с ним поосторожнее, не то ты ему понравишься сверх всякой меры и он решит тебя взять к нам, как это называется, на полную ставку!" }, { 15.82, "Нет, я ничего не говорю; ты молодчина!" }, { 18.49, "Только будь поосторожнее на обратном пути и поторапливайся: Карнитол – не самый терпеливый тип... зато платит от души!" } } }, t = { d = 35.8, g = 1, v = "dwarf-male", n = { m = 366, f = 367 }, c = { m = { { 0.00, "Ах да, Карнитол..." }, { 1.36, "Точно, было у него такое дело в Пустошах." }, { 4.61, "Великолепно!" }, { 5.56, "Итак, сундук уничтожен, но всё его содержимое тут, да?" }, { 9.64, "Что ж, поверим ему на слово, поверим..." }, { 12.62, "Тут какое дело?" }, { 13.84, "Если ко мне возникнут какие-то претензии, я всегда могу послать жалобщиков куда подальше." }, { 20.63, "Они же от нас чего хотят? – правильно, чтобы мы нашли их вещи." }, { 25.38, "Мы и находим, а уж сохранность и внешний вид находок – это второй вопрос." }, { 30.87, "Прекрасная работа!" }, { 32.30, "Давай-ка посмотрим, что ты на этом заработал..." } }, f = { { 0.00, "Ах да, Карнитол..." }, { 1.36, "Точно, было у него такое дело в Пустошах." }, { 4.63, "Великолепно!" }, { 5.58, "Итак, сундук уничтожен, но всё его содержимое тут, да?" }, { 9.66, "Что ж, поверим ему на слово, поверим..." }, { 12.65, "Тут какое дело?" }, { 13.88, "Если ко мне возникнут какие-то претензии, я всегда могу послать жалобщиков куда подальше." }, { 20.68, "Они же от нас чего хотят? – правильно, чтобы мы нашли их вещи." }, { 25.44, "Мы и находим, а уж сохранность и внешний вид находок – это второй вопрос." }, { 30.95, "Прекрасная работа!" }, { 32.38, "Давай-ка посмотрим, что ты на этом заработала..." } } } } },
    [1458] = { d = 31.9, v = "dwarf-male", n = { x = 385 }, c = { x = { { 0.00, "Одна из моих задач здесь – подбор реактивов для Скрытного Кудесника, гномского мага из Караноса." }, { 6.39, "Ройттен-то, небось, думает, что это – раз плюнуть, коли уж мы всё равно тут торчим, а дело-то не из простых, да и рук не хватает..." }, { 14.87, "Первые несколько реактивов добыть не так уж сложно, а я готов заплатить неплохие деньги тому, кто мне поможет." }, { 22.15, "Мне нужны рога и когти сатиров Ярой Ненависти: они тут недалеко обитают, на востоке." }, { 27.82, "Ты мне их сначала принеси, а потом мы займёмся остальным списком." } } }, t = { d = 19.8, v = "dwarf-male", n = { x = 214 }, c = { x = { { 0.00, "Отлично, отлично!" }, { 1.31, "Не то чтобы я был уверен в качестве этой дряни, но ежели этому Скрытному типу нужны были какие-то особые рога и когти, надо было мне об этом раньше сказать, а теперь уж пусть забирает, что дают, я так себе думаю." }, { 16.85, "Ну что, посмотрим, что там дальше по списку?" } } } } },
    [1459] = { d = 34.6, v = "dwarf-male", n = { x = 370 }, c = { x = { { 0.00, "А следующее по списку Скрытного Кудесника у нас..." }, { 3.64, "Погоди-ка..." }, { 4.57, "А, да, вот оно." }, { 5.70, "Ну, не то чтобы это было большой редкостью, но тут наш дорогой друг сподобился дать подобные разъяснения." }, { 13.31, "Ему понадобился яд скорпиона и шкура кодо." }, { 16.49, "А вот тут вот, меленькими буковками, видишь? – тут написано, что яд-то может быть от любого скорпиона, а шкура ему нужна непременно со старого кодо, но ни в коем случае не с умирающего или дряхлого." }, { 30.93, "Ох уж эти мне маги... вечно у них какие-то заскоки." } } }, t = { d = 25.4, v = "dwarf-male", n = { x = 295 }, c = { x = { { 0.00, "Твоя помощь просто неоценима." }, { 2.17, "Благодаря тебе я проведу в этих проклятущих Пустошах вдвое меньше времени." }, { 7.55, "Ещё немного, и можно будет отправиться в Стальгорн: отдых мне не помешает..." }, { 12.86, "Когда мы покончим с этим списком и я вернусь домой, непременно загляни ко мне: я тебе поставлю пару пинт доброго эля!" }, { 21.23, "А пока что давай займёмся остальными реактивами, договорились?" } } } } },
    [1462] = { t = { d = 5.0, v = "tauren-female", n = { x = 35 }, c = { x = { { 0.00, "Возьми это и помни – этот предмет священный." } } } } },
    [1463] = { t = { d = 8.6, v = "troll-male#77", n = { x = 79 }, c = { x = { { 0.00, "Я даю тебе её со спокойной душой." }, { 3.13, "Твоя доблесть мне известна." }, { 5.68, "Однако же впредь будь поосторожнее!" } } } } },
    [1464] = { t = { d = 6.1, v = "troll-male#77", n = { x = 51 }, c = { x = { { 0.00, "Пусть огонь неугасимо пылает в твоём сердце!" }, { 4.44, "Стихии ждут тебя." } } } } },
    [1465] = { d = 30.5, v = "narrator", n = { x = 314 }, c = { x = { { 0.00, "При осмотре повозки удаётся найти подвеску, а также следы, ведущие на юг – туда, где над фортом поднимается лёгкий дымок, заставляющий думать не о пожаре и горящих домах, а об очаге или костре, на котором готовится пища." }, { 17.11, "Должно быть, если Малемы ещё живы, их увели в том направлении." }, { 21.97, "Валарриэль непременно должен увидеть подвеску – и об этих признаках жизни на юге ему тоже нужно рассказать..." } } }, t = { d = 40.2, g = 1, v = "nightelf-male#55", n = { m = 443, f = 444 }, c = { m = { { 0.00, "Я в ярости!" }, { 0.79, "Подумать только, какой провал!.." }, { 3.06, "И ведь этих двоих предупреждали, что здесь крайне опасно." }, { 6.91, "А теперь они оба пропали..." }, { 8.86, "И хорошо, если живы." }, { 10.33, "Говоришь, ты видел следы, ведущие к ближнему форту?.." }, { 14.00, "Что ж, возможно, у нас всё ещё есть шанс..." }, { 16.75, "Местные жители говорят, что в этой крепости обосновались орки Пылающего Клинка – те, что служат демонам." }, { 23.84, "Я вовсе не хочу сказать, что вся Орда придерживается подобных верований – но это сейчас неважно, а важно то, что эти орки непременно убьют тебя, если увидят, что ты пытаешься что-то разведать неподалёку от их форта." } }, f = { { 0.00, "Я в ярости!" }, { 0.83, "Подумать только, какой провал!.." }, { 3.20, "И ведь этих двоих предупреждали, что здесь крайне опасно." }, { 7.24, "А теперь они оба пропали..." }, { 9.29, "И хорошо, если живы." }, { 10.83, "Говоришь, ты видела следы, ведущие к ближнему форту?.." }, { 14.74, "Что ж, возможно, у нас всё ещё есть шанс..." }, { 17.62, "Местные жители говорят, что в этой крепости обосновались орки Пылающего Клинка – те, что служат демонам." }, { 25.05, "Я вовсе не хочу сказать, что вся Орда придерживается подобных верований – но это сейчас неважно, а важно то, что эти орки непременно убьют тебя, если увидят, что ты пытаешься что-то разведать неподалёку от их форта." } } } } },
    [1466] = { d = 41.2, v = "dwarf-male", n = { x = 421 }, c = { x = { { 0.00, "Это последнее в списке." }, { 1.87, "Врать не буду, задание не из приятных; к тому же оно наверняка займёт у тебя больше времени, чем предыдущие." }, { 10.10, "Ну ладно, хватит болтать." }, { 12.10, "Вот гляди: Скрытный Кудесник тут пишет, что ему нужны десять мозгов – от пожирателей маны, охотников на магов или лей-охотников... ещё десять крыльев Пустоты, от любой Девы, Сестры или Колдуньи Пустоты... и ещё... десять склянок крови Тюремщика Судеб, от лорда или капитана – не важно." }, { 34.09, "Простенькое такое заданьице, точно?" }, { 36.85, "Слушай, я тебе вот что скажу: если ты откажешься, я пойму." } } }, t = { d = 16.2, g = 1, v = "dwarf-male", n = { m = 163, f = 165 }, c = { m = { { 0.00, "Честно говоря, не думал, что тебе это удастся." }, { 3.64, "Ты – это что-то!" }, { 4.94, "Надо же, и демонов покромсал для чокнутого мага, и живым вернулся!" }, { 10.03, "Вот это класс!" }, { 11.12, "Как вернусь в Стальгорн, лично расскажу о тебе старине Ройттену!" } }, f = { { 0.00, "Честно говоря, не думал, что тебе это удастся." }, { 3.68, "Ты – это что-то!" }, { 5.00, "Надо же, и демонов покромсала для чокнутого мага, и живой вернулась!" }, { 10.28, "Вот это класс!" }, { 11.39, "Как вернусь в Стальгорн, лично расскажу о тебе старине Ройттену!" } } } } },
    [1467] = { d = 23.6, v = "dwarf-male", n = { x = 282 }, c = { x = { { 0.00, "Хочешь плату получить?" }, { 1.60, "Так за этим тебе придётся вернуться в Стальгорн и потолковать со стариной Ройттеном." }, { 7.24, "Думаю, он будет рад отделаться, наконец, от коробки Кудесника." }, { 11.47, "Отдашь ему вот это, и получишь свою награду." }, { 14.60, "Да ты не беспокойся: когда я вернусь, то всяко замолвлю за тебя словечко." }, { 19.57, "Мне тоже не больно-то хочется торчать в этих самых Пустошах." } } }, t = { d = 22.1, g = 1, v = "dwarf-male", n = { x = 233 }, c = { m = { { 0.00, "О, а вот и посылка для Скрытного Кудесника, прямиком из Пустошей!" }, { 4.81, "Прекрасно!" }, { 5.62, "Ценю твою работу, герой: к тому же, тебе удалось уложиться в срок." }, { 10.71, "Приятно было с тобой работать." }, { 13.08, "Вот тут твоя плата." }, { 14.57, "И пусть все знают, что Горная корпорация всегда оплачивает услуги своих работников по высшему разряду!" } }, f = { { 0.00, "О, а вот и посылка для Скрытного Кудесника, прямиком из Пустошей!" }, { 4.73, "Прекрасно!" }, { 5.53, "Ценю твою работу, героиня: к тому же, тебе удалось уложиться в срок." }, { 10.66, "Приятно было с тобой работать." }, { 12.99, "Вот тут твоя плата." }, { 14.46, "И пусть все знают, что Горная корпорация всегда оплачивает услуги своих работников по высшему разряду!" } } } } },
    [1468] = { d = 28.3, g = 1, v = "human-female", n = { m = 331, f = 333 }, c = { m = { { 0.00, "Можешь ли ты помочь нам позаботиться о сиротах?" }, { 3.27, "Благословен будь, друг: помощь твоя во время Детской недели неоценима." }, { 8.17, "Возьми этот свисток." }, { 9.68, "Ты сможешь использовать его только во время Детской недели." }, { 13.89, "Свистни в него – и сможешь поговорить с ребёнком, о котором будешь заботиться." }, { 19.30, "Свистни ещё раз – ребёнок уйдёт." }, { 21.43, "Всё очень просто: используй свисток и заботься о ребёнке." }, { 25.39, "Любой сирота будет рад встрече с тобой." } }, f = { { 0.00, "Можешь ли ты помочь нам позаботиться о сиротах?" }, { 3.27, "Благословенна будь, дева: помощь твоя во время Детской недели неоценима." }, { 8.35, "Возьми этот свисток." }, { 9.86, "Ты сможешь использовать его только во время Детской недели." }, { 14.07, "Свистни в него – и сможешь поговорить с ребёнком, о котором будешь заботиться." }, { 19.47, "Свистни ещё раз – ребёнок уйдёт." }, { 21.60, "Всё очень просто: используй свисток и заботься о ребёнке." }, { 25.56, "Любой сирота будет рад встрече с тобой." } } }, t = { d = 22.6, g = 1, v = "child-male", n = { m = 233, f = 233 }, c = { m = { { 0.00, "Э... ну, привет." }, { 1.19, "Меня зовут Рандис, ты будешь за мной присматривать, да?" }, { 5.22, "А ты – искатель приключений?" }, { 7.26, "Мама и папа тоже были такими." }, { 9.57, "Значит, ты меня поймёшь!" }, { 11.36, "Давай играть!" }, { 12.41, "Воспитатели мне сказали, что ты мне будешь вроде старшего брата." }, { 17.10, "Это здорово!" }, { 18.09, "Если бы у меня были настоящие братишки и сестрёнки..." } }, f = { { 0.00, "Э... ну, привет." }, { 1.23, "Меня зовут Рандис, ты будешь за мной присматривать, да?" }, { 5.39, "А ты – искатель приключений?" }, { 7.50, "Мама и папа тоже были такими." }, { 9.89, "Значит, ты меня поймёшь!" }, { 11.73, "Давай играть!" }, { 12.82, "Воспитатели мне сказали, что ты мне будешь вроде старшей сестры." }, { 17.66, "Это здорово!" }, { 18.68, "Если бы у меня были настоящие братишки и сестрёнки..." } } } } },
    [1469] = { d = 40.7, v = "dwarf-male", n = { x = 416 }, c = { x = { { 0.00, "Перед тем как лететь, я выпил полный бочонок портера." }, { 4.17, "Ик!" }, { 4.45, "Что это был за полёт!" }, { 6.05, "Я нёсся по воздуху, а Брохан болтался за моей спиной, но храма мы не видели." }, { 11.89, "Ик!" }, { 12.16, "И не нашли бы мы его никогда, если бы я не нагрузился так, что сверзился из седла." }, { 18.42, "Упал в воду, пошёл прямо на дно." }, { 20.92, "А тут, откуда ни возьмись, целое стадо отвратительных троллей!" }, { 25.72, "Конечно, я постарался убраться оттуда как можно быстрее." }, { 30.10, "Еле выбрался, однако прихватил с собой вот этот сувенир." }, { 34.54, "Держите, отнесёте его Брохану и расскажете, что храм этот его – там, под водой." }, { 40.59, "Ик!" } } }, t = { d = 16.1, v = "dwarf-male", n = { x = 144 }, c = { x = { { 0.00, "Рапсод Землекоп!" }, { 1.45, "Точно!" }, { 2.07, "Как я мог забыть такое имя?" }, { 4.44, "Так он всё это время знал о том, что храм затонул?" }, { 8.57, "Что ж, это точно сэкономит вам время." }, { 11.43, "Но предмет, сделанный Атал'ай..." }, { 14.79, "Вот это находка!" } } } } },
    [1470] = { d = 45.9, v = "scourge-female#80", n = { x = 368 }, c = { x = { { 0.00, "Приветствую тебя, дитя." }, { 2.48, "Вижу, ты только вступаешь на пути чернокнижия, мощь его не даётся тебе пока." }, { 10.28, "Я чувствую, как велико твоё желание учиться." }, { 14.78, "Да, ты будешь учиться." }, { 17.08, "В невежестве нет силы." }, { 19.37, "Знание – вот залог нашего могущества." }, { 23.23, "Знания позволяют нам контролировать хаотическую магию и тварей Бездны, склоняя их к своей воле." }, { 32.96, "Я покажу тебе, как подчинять себе слугу, но сначала принеси мне три черепа скелетов-костетрясов, бродящих близ покинутой кузницы." } } }, t = { d = 36.7, g = 1, v = "scourge-female#80", n = { m = 348, f = 349 }, c = { m = { { 0.00, "Хотя ты ещё не прошёл испытаний и находишься в самом начале ученичества, ты доказал, что силы у тебя достаточно, чтобы суметь призвать беса и подчинить его своей воле." }, { 14.53, "Пусть тебя не обманывают его небольшие размеры." }, { 18.67, "Физической силы ему не хватает, зато хватит магического могущества и разума, чтобы хорошо служить тебе." }, { 27.81, "Слушай меня внимательно, потому что повторять я не буду, и тогда придётся всё осваивать самостоятельно." } }, f = { { 0.00, "Хотя ты ещё не прошла испытаний и находишься в самом начале ученичества, ты доказала, что силы у тебя достаточно, чтобы суметь призвать беса и подчинить его своей воле." }, { 14.72, "Пусть тебя не обманывают его небольшие размеры." }, { 18.87, "Физической силы ему не хватает, зато хватит магического могущества и разума, чтобы хорошо служить тебе." }, { 28.03, "Слушай меня внимательно, потому что повторять я не буду, и тогда придётся всё осваивать самостоятельно." } } } } },
    [1471] = { d = 31.0, g = 1, v = "scourge-male#82", n = { m = 282, f = 283 }, c = { m = { { 0.00, "Ты наверняка уже видел круг призыва." }, { 3.27, "Только в его пределы ты можешь вызвать демона Бездны." }, { 8.14, "При помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии." }, { 15.48, "Подчинённый демон Бездны будет неразрывно связан с тобой." }, { 20.59, "Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва." }, { 26.81, "Ты сможешь пользоваться им, когда захочешь." } }, f = { { 0.00, "Ты наверняка уже видела круг призыва." }, { 3.40, "Только в его пределы ты можешь вызвать демона Бездны." }, { 8.35, "При помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии." }, { 15.80, "Подчинённый демон Бездны будет неразрывно связан с тобой." }, { 20.99, "Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва." }, { 27.31, "Ты сможешь пользоваться им, когда захочешь." } } }, t = { d = 16.6, g = 1, v = "scourge-male#82", n = { m = 141, f = 142 }, c = { m = { { 0.00, "Великолепная работа." }, { 1.98, "Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны." }, { 8.59, "Ты сможешь обратить силу, которую недавно испытал на себе, против своих врагов." } }, f = { { 0.00, "Великолепная работа." }, { 2.01, "Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны." }, { 8.76, "Ты сможешь обратить силу, которую недавно испытала на себе, против своих врагов." } } } } },
    [1472] = { d = 42.6, v = "scourge-male#82", n = { x = 402 }, c = { x = { { 0.00, "Сайаады – пожиратели душ, разбивающие сердца и вводящие в искушение." }, { 5.92, "Существа, исполненные зла и изощрённой хитрости." }, { 10.03, "Сказания из уст что праведников, что грешников говорят одно: их женщин называют суккубами, а мужчин – инкубами." }, { 19.66, "Просто так их в наш мир не выманишь." }, { 22.74, "Сайаад не сможет устоять перед сердцами добрых и любящих смертных." }, { 28.66, "Когда он явится в Азерот, можно побороть его и подчинить себе." }, { 34.27, "Ступай в храм и поговори с моим помощником Годриком Фарсаном." }, { 39.64, "Он поможет тебе подобрать приманку." } } }, t = { d = 16.5, g = 1, v = "scourge-male#83", n = { x = 159 }, c = { m = { { 0.00, "Тебя прислал Карендин?" }, { 1.93, "Говоришь, ты путник?" }, { 3.64, "Не думай, что я просто беспомощный слепец." }, { 7.13, "Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением." } }, f = { { 0.00, "Тебя прислал Карендин?" }, { 1.92, "Говоришь, ты путница?" }, { 3.70, "Не думай, что я просто беспомощный слепец." }, { 7.17, "Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением." } } } } },
    [1473] = { d = 36.8, g = 1, v = "scourge-male#82", n = { m = 327, f = 328 }, c = { m = { { 0.00, "Похоже, ты готов призвать демона Бездны." }, { 3.77, "Эти твари появляются из Круговерти Пустоты, лежащей за пределами мира." }, { 10.24, "Если ты не сможешь подчинить себе вызванного демона, он разорвёт тебя на части." }, { 17.46, "Первого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре." }, { 25.16, "К сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда." }, { 33.19, "Принеси книгу, и я наделю тебя знаниями." } }, f = { { 0.00, "Похоже, ты готова призвать демона Бездны." }, { 3.72, "Эти твари появляются из Круговерти Пустоты, лежащей за пределами мира." }, { 9.97, "Если ты не сможешь подчинить себе вызванного демона, он разорвёт тебя на части." }, { 16.93, "Первого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре." }, { 24.37, "К сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда." }, { 32.12, "Принеси книгу, и я наделю тебя знаниями." } } }, t = { d = 19.9, v = "scourge-male#82", n = { x = 166 }, c = { x = { { 0.00, "А, великолепно." }, { 1.52, "Вероятно, Перрин не догадывался, какие знания скрывает в себе этот фолиант." }, { 9.11, "Мы больше не допустим хищения книги." }, { 12.77, "Смотри: вот схема заклинания, объясняющая, как следует направлять энергию." } } } } },
    [1474] = { d = 30.3, v = "scourge-male#82", n = { x = 282 }, c = { x = { { 0.00, "При помощи этих сердец наложи заклинание на круг призыва, чтобы открыть дверь в наш мир для суккуба." }, { 8.64, "Твои силы возросли, и они понадобятся тебе, чтобы одолеть демоницу." }, { 14.69, "Остерегайся её чар, даже сила воли может не защитить от них." }, { 19.95, "Если ты победишь, суккуб вернётся в Бездну, а я научу тебя заклинанию, которое позволит тебе вызывать её в любой момент." } } }, t = { d = 24.3, g = 1, v = "scourge-male#82", n = { m = 218, f = 219 }, c = { m = { { 0.00, "И снова ты справился с заданием." }, { 2.89, "Давно мне не встречались чернокнижники с такими задатками." }, { 8.03, "Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям." }, { 17.42, "А теперь я хочу научить тебя заклинанию призыва личного суккуба." } }, f = { { 0.00, "И снова ты справилась с заданием." }, { 3.11, "Давно мне не встречались чернокнижники с такими задатками." }, { 8.50, "Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям." }, { 18.34, "А теперь я хочу научить тебя заклинанию призыва личного суккуба." } } } } },
    [1475] = { d = 29.1, v = "dwarf-male", n = { x = 316 }, c = { x = { { 0.00, "Храм Атал'Хаккара посвящён древнему божеству Хаккару Свежевателю Душ." }, { 5.12, "Храм охраняет злобное племя троллей Атал'ай, и он, если верить слухам, неприступен." }, { 11.46, "Теперь, когда он затонул, добывать в нём артефакты стало ещё сложнее." }, { 16.71, "Но это именно то, о чём я вас прошу." }, { 19.44, "Помогите мне собрать целые таблички Атал'ай." }, { 22.86, "Принесите их мне, и я вернусь в Лигу Исследователей героем." }, { 27.29, "Вместе мы добьёмся успеха!" } } }, t = { d = 15.0, v = "dwarf-male", n = { x = 162 }, c = { x = { { 0.00, "Таблички Атал'ай!" }, { 1.37, "Благодарю!" }, { 2.20, "Когда я доставлю их в Лигу Исследователей, наши имена войдут в историю." }, { 7.69, "Вы помогли старому дворфу выполнить его последнее задание, и я бесконечно признателен вам за это!" } } } } },
    [1476] = { d = 39.3, v = "scourge-male#83", n = { x = 381 }, c = { x = { { 0.00, "Чтобы поймать суккуба, нужно чистое сердце." }, { 3.81, "Но разве остались среди смертных непорочные сердца?" }, { 8.22, "После долгих поисков и расспросов мне удалось найти только двоих." }, { 13.86, "Первый из них – Далин Искусник." }, { 16.52, "Он посвятил свою жизнь заботе о лордеронских беженцах, которых отказалась принять родня у Стены Седогрива." }, { 25.50, "Вторая – Корма Виллард." }, { 27.56, "Она скорбит об утраченной дружбе и бродит по Болотине в поисках подруги." }, { 33.73, "Принеси их сердца Карендину." }, { 36.16, "Но сначала я покажу тебе твои жертвы." } } }, t = { d = 17.8, v = "scourge-male#82", n = { x = 155 }, c = { x = { { 0.00, "А с виду доброе сердце ничем не отличается от любого другого, да?" }, { 6.09, "Может быть, мы просто... по-другому смотрим на мир." }, { 10.75, "Но эти сердца прекрасно подойдут." }, { 13.92, "Не сомневаюсь, их чистота привлечёт суккуба." } } } } },
    [1477] = { d = 32.8, v = "human-male", n = { x = 407 }, c = { x = { { 0.00, "Наши маги проводят исследования в Крепости Стражей Пустоты, в Выжженных землях – исследования, жизненно важные для понимания Тёмного портала." }, { 9.52, "Они почти постоянно требуют поставок, однако доставлять что бы то ни было в крепость крайне сложно." }, { 16.29, "Мы просим твоей помощи в обеспечении прибытия поставок в Крепость Стражей Пустоты." }, { 21.90, "Сдай рапорт начальнику стражи Соригелу в Темнолесье и сделай то, о чём он попросит." }, { 27.45, "Но это задание приведёт тебя во враждебные земли." }, { 30.81, "Приготовься к любым опасностям." } } }, t = { d = 5.6, v = "human-male", n = { x = 54 }, c = { x = { { 0.00, "Тебя послал Андромах?" }, { 1.82, "Очень хорошо." }, { 2.99, "У меня для тебя важное задание..." } } } } },
    [1478] = { d = 21.5, v = "scourge-male#83", n = { x = 240 }, c = { x = { { 0.00, "А!" }, { 0.20, "Я только что получил новости от Карендина Халгара – он хочет поговорить с вами насчёт дальнейшего обучения." }, { 8.24, "Можете гордиться собой!" }, { 10.08, "Не каждый день мастер Халгар решает самолично проинструктировать юного чернокнижника." }, { 16.49, "Его можно найти в Квартале Магов Подгорода, возле Храма Проклятых." } } }, t = { d = 15.0, v = "scourge-male#82", n = { x = 128 }, c = { x = { { 0.00, "Хорошо, я вижу, Агерон нашёл вас." }, { 3.14, "Давайте не будем тратить время на болтовню и церемонии, а сразу же перейдём к вашему обучению." }, { 11.98, "Вам ещё очень много надо узнать." } } } } },
    [1479] = { d = 25.0, v = "child-male", n = { x = 275 }, c = { x = { { 0.00, "Я слышал, что Ночные эльфы устроили банк прямо внутри дерева, которое похоже на медведя!" }, { 6.56, "Круто!" }, { 7.09, "Ночные эльфы очень милые, а как они любят природу!" }, { 10.94, "Но медведи это совсем здорово!" }, { 13.26, "Своди меня посмотреть на древо-медведя в Дарнасс!" }, { 16.97, "Пожалуйста!" }, { 17.83, "Мы можем доплыть дотуда на корабле, много времени это не займёт." }, { 22.60, "Пожалуйста, пожалуйста, пожалуйста!" } } }, t = { d = 19.5, g = 1, v = "child-male", n = { m = 190, f = 192 }, c = { m = { { 0.00, "Ух ты, Купина Вечности ещё круче, чем я представлял!" }, { 3.99, "Я не думал, что она такая большая, а она огромная!" }, { 7.98, "А ты видел птицу у неё на верхушке?!" }, { 10.78, "Интересно, как они сделали, чтобы ветви так выглядели!" }, { 15.05, "Спасибо, что сводил меня в Дарнасс." }, { 17.85, "Ты просто чудо!" } }, f = { { 0.00, "Ух ты, Купина Вечности ещё круче, чем я представлял!" }, { 4.08, "Я не думал, что она такая большая, а она огромная!" }, { 8.15, "А ты видела птицу у неё на верхушке?!" }, { 11.09, "Интересно, как они сделали, чтобы ветви так выглядели!" }, { 15.45, "Спасибо, что сводила меня в Дарнасс." }, { 18.38, "Ты просто чудо!" } } } } },
    [1480] = { d = 24.1, v = "narrator", n = { x = 245 }, c = { x = { { 0.00, "Эта рваная кожа пахнет гнилью, и она на удивление мягкая и гибкая для такого сухого и хрупкого на вид материала." }, { 9.06, "Если её развернуть, на ней видны красные письмена на непонятном наречии." }, { 14.81, "А внизу – очень отчётливый отдельный символ, должно быть, подпись." }, { 20.06, "Может быть, Маурин сумеет объяснить, что это такое?" } } }, t = { d = 21.0, v = "scourge-male#82", n = { x = 159 }, c = { x = { { 0.00, "Да, это действительно чужой язык, и весьма древний." }, { 5.45, "Он отчасти напоминает эредан, но отличия несомненны." }, { 10.90, "Если не ошибаюсь, это нечто вроде договора..." }, { 15.78, "Да, вот этот символ – подпись демона: лорд Азреток." } } } } },
    [1481] = { d = 42.6, v = "scourge-male#82", n = { x = 410 }, c = { x = { { 0.00, "Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты." }, { 7.02, "Однако, если он действительно так могуществен, мне понадобятся предметы, собранные со смертельно опасных тварей..." }, { 16.76, "Но ты действуешь от имени вождя, так что, не сомневаюсь, возьмёшься за это." }, { 23.08, "Прежде всего мне придётся снять заклятия, которые защищают его от соглядатаев." }, { 29.78, "Для этого нужен скальп сатира, но не первого попавшегося, а тенелова из племени Ярой Ненависти." }, { 37.96, "Ищи их в древних развалинах на северо-востоке Пустошей." } } }, t = { d = 27.0, g = 1, v = "scourge-male#82", n = { x = 241 }, c = { m = { { 0.00, "Что, герой, тенеловы тебя не убили?" }, { 3.21, "Неплохо, очень неплохо." }, { 5.38, "Да, этот скальп мне подходит." }, { 7.94, "Пока тебя не было, мне удалось собрать остальные необходимые реагенты." }, { 14.28, "Я почти готов." }, { 15.65, "Мне необходима только точка приложения заклинания – тот предмет, в котором мы увидим повелителя демонов и место, где он находится." } }, f = { { 0.00, "Что, героиня, тенеловы тебя не убили?" }, { 3.35, "Неплохо, очень неплохо." }, { 5.50, "Да, этот скальп мне подходит." }, { 8.06, "Пока тебя не было, мне удалось собрать остальные необходимые реагенты." }, { 14.36, "Я почти готов." }, { 15.71, "Мне необходима только точка приложения заклинания – тот предмет, в котором мы увидим повелителя демонов и место, где он находится." } } } } },
    [1482] = { d = 34.2, v = "scourge-male#82", n = { x = 336 }, c = { x = { { 0.00, "Кристалл оракула нам подойдёт." }, { 2.54, "Их делают наги для своих оракулов." }, { 5.55, "К северо-западу отсюда, на побережье, есть обширный коралловый риф, где поселились наги." }, { 13.03, "Там можно найти и оракулов." }, { 15.42, "Но Скользящий Плавник смертельно опасен и встретит тебя отнюдь не с распростёртыми объятиями." }, { 23.29, "Так что смотри, осторожнее, и постарайся убраться оттуда побыстрее." }, { 29.00, "А когда вернёшься, мы попробуем отыскать этого лорда Азретока." } } }, t = { d = 21.0, g = 1, v = "scourge-male#82", n = { x = 167 }, c = { m = { { 0.00, "Драгоценный кристалл оракула!" }, { 3.01, "Безупречный... великолепный…" }, { 5.83, "Что ж, начнём немедленно." }, { 8.29, "Нам следует отыскать этого повелителя демонов." }, { 13.02, "Отступи на шаг, герой, и давай посмотрим, как выглядит Азреток и где его искать." } }, f = { { 0.00, "Драгоценный кристалл оракула!" }, { 2.96, "Безупречный... великолепный…" }, { 5.74, "Что ж, начнём немедленно." }, { 8.15, "Нам следует отыскать этого повелителя демонов." }, { 12.81, "Отступи на шаг, героиня, и давай посмотрим, как выглядит Азреток и где его искать." } } } } },
    [1483] = { d = 32.0, v = "goblin-male", n = { x = 385 }, c = { x = { { 0.00, "Торговая Компания переманила лучшие гоблинские умы, но порой у нас появляется возможность вернуть своё." }, { 7.14, "Некоторое время назад подразделение Торговой Компании в Когтистых горах приняло на работу Геренцо Терминатрикса – гнома!" }, { 15.54, "Это так ошарашило другого инженера, Зиза Физзикса, что он умолял меня найти ему новую работу в Союзе ремонтников." }, { 23.56, "Я дал ему несколько заданий, но ему может понадобиться помощь." }, { 27.94, "Не навестишь его?" }, { 29.20, "Он живёт у западного края Утёса Ветрорезов." } } }, t = { d = 18.8, v = "goblin-male", n = { x = 200 }, c = { x = { { 0.00, "Я думал, что начальство Торговой Компании – настоящие тираны, но потом я познакомился с Пароклапаном, он хуже их всех!" }, { 8.58, "Ха!" }, { 8.84, "И всё же это лучше, чем сидеть без работы..." }, { 12.10, "Или, хуже того, работать с этим Геренцо." }, { 15.22, "Если ты хочешь мне помочь, дело для тебя найдётся." } } } } },
    [1484] = { d = 25.4, v = "scourge-male#82", n = { x = 252 }, c = { x = { { 0.00, "Это существо куда опаснее, чем мне казалось!" }, { 3.68, "Неудивительно, что Таката сомневается, что мне удастся его одолеть." }, { 9.12, "Он будет оскорблён, если не сообщить ему о том, что случилось." }, { 14.12, "Поговори с мечником, скажи, что хочешь убить демона, если он разрешит, но особо не настаивай." }, { 21.77, "Пусть думает, будто это его собственная идея." } } }, t = { d = 29.1, v = "orc-male#60", n = { x = 292 }, c = { x = { { 0.00, "Да, я видел, что только что произошло между Маурином и повелителем демонов!" }, { 6.06, "Похоже, это существо, даже в видении, обладает куда большим могуществом, чем мой соратник-чернокнижник." }, { 14.45, "Сумеет ли он одолеть этого монстра?" }, { 17.37, "Лучше бы я занялся этим сам..." }, { 19.86, "Но вождю я нужен здесь." }, { 21.75, "Я опозорю свой клан, если оставлю свои здешние обязанности и отправлюсь добывать себе славу." } } } } },
    [1485] = { d = 33.5, v = "orc-male", n = { x = 354 }, c = { x = { { 0.00, "Чернокнижники, бывшие здесь до нас, внушили Орде недоверие к нам." }, { 5.08, "Нас терпят, но недолюбливают." }, { 7.36, "Однако это не заставило чернокнижников сплотиться." }, { 11.37, "Многие предпочитают жить и заниматься магией в уединении." }, { 15.87, "Я не буду принуждать тебя избрать тот или иной путь, а всего лишь помогу тебе сделать очередной шаг." }, { 23.88, "Но прежде чем я научу тебя искусству призывания, принеси мне шесть голов злобных фамильяров из той пещеры на северо-востоке." } } }, t = { d = 16.6, v = "orc-male", n = { x = 168 }, c = { x = { { 0.00, "Во время обучения ты научишься вызывать самых разных существ." }, { 4.95, "Все они по-своему полезны, даже если на первый взгляд это не очевидно." }, { 10.62, "Пусть малый рост беса тебя не смущает." }, { 13.71, "Ты уже знаешь, как опасны они бывают." } } } } },
    [1486] = { d = 37.7, v = "tauren-male", n = { x = 377 }, c = { x = { { 0.00, "Пока Наралекс погружался в свои кошмары всё глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные." }, { 9.93, "Эти искажённые существа наделены странными, потусторонними силами." }, { 15.37, "В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре." }, { 24.78, "Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее." }, { 30.37, "Если эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искажённых шкур." } } }, t = { d = 7.7, v = "tauren-male", n = { x = 74 }, c = { x = { { 0.00, "Твои услуги не останутся незамеченными, протеже." }, { 4.28, "Спасибо тебе за твою неоценимую помощь." } } } } },
    [1487] = { d = 31.3, v = "nightelf-female", n = { x = 379 }, c = { x = { { 0.00, "Цели у Наралекса были самые благие." }, { 2.52, "Наш лидер стремился впасть в Изумрудный сон, и вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись." }, { 11.44, "Но что-то пошло не так." }, { 13.04, "Мечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры." }, { 18.02, "В то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей." }, { 28.41, "Отправляйся туда, и уничтожь порченое семя." } } }, t = { d = 12.3, v = "nightelf-female", n = { x = 141 }, c = { x = { { 0.00, "Как послушница Наралекса я не могу не отметить твоей храбрости." }, { 4.45, "Твоя помощь – это всего лишь первый шаг в очищении Степей от порчи." }, { 9.28, "Благодарю тебя, и да пребудет с тобой удача." } } } } },
    [1488] = { d = 30.5, v = "orc-male#60", n = { x = 322 }, c = { x = { { 0.00, "Я ничего не знаю об этом лорде Азретоке, однако согласен с Маурином: его следует остановить, особенно если он пытается подчинить себе Пылающий Клинок." }, { 11.87, "Твоё стремление служить вождю уже не требует доказательств, и я готов доверить тебе собрать отряд, чтобы убить Азретока и его слугу чернокнижника." }, { 23.39, "Когда будете готовы выступать, отправляйтесь на юг, а покончите с ними – возвращайтесь ко мне." } } }, t = { d = 20.6, v = "orc-male#60", n = { x = 194 }, c = { x = { { 0.00, "Эта победа очень важна для нас." }, { 2.80, "Все мы радуемся вашему успеху." }, { 5.45, "Теперь я думаю, что наше будущее не так беспросветно, как мне казалось." }, { 11.53, "Демоны будут повержены, Пылающий Клинок потерпит крах, и в один прекрасный день у нас снова будет свой дом!" } } } } },
    [1489] = { d = 41.0, g = 1, v = "tauren-male", n = { m = 381, f = 383 }, c = { m = { { 0.00, "На раковинах, что ты мне принёс, присутствует порча, которой я никогда раньше не видел." }, { 7.47, "Я уверен, что причины её возникновения кроются в воде оазиса, и я уже предчувствую, чем это грозит этим землям." }, { 17.22, "Источник этой порчи в Пещерах Стенаний, но прежде чем отправиться туда, поговори с Хамуулом Руническим Тотемом, старшим друидом." }, { 28.46, "Я послал ему весточку о том, что творится в Степях." }, { 32.94, "Он мудр и сможет дать тебе дельный совет." }, { 36.56, "Найдёшь его в Громовом Утёсе, на Вершине Старейшин." } }, f = { { 0.00, "На раковинах, что ты мне принесла, присутствует порча, которой я никогда раньше не видел." }, { 7.71, "Я уверен, что причины её возникновения кроются в воде оазиса, и я уже предчувствую, чем это грозит этим землям." }, { 17.45, "Источник этой порчи в Пещерах Стенаний, но прежде чем отправиться туда, поговори с Хамуулом Руническим Тотемом, старшим друидом." }, { 28.70, "Я послал ему весточку о том, что творится в Степях." }, { 33.18, "Он мудр и сможет дать тебе дельный совет." }, { 36.80, "Найдёшь его в Громовом Утёсе, на Вершине Старейшин." } } }, t = { d = 11.4, v = "creature/hamuul", n = { x = 108 }, c = { x = { { 0.00, "Приветствую тебя, добро пожаловать." }, { 3.09, "И лучше бы тебе собрать всю волю в кулак, потому что дело, порученное тебе, будет крайне нелёгким." } } } } },
    [1490] = { d = 40.6, v = "creature/hamuul", n = { x = 372 }, c = { x = { { 0.00, "Я вошёл в сновидения и увидел там орден друидов, обитающих в Пещерах Стенаний." }, { 6.85, "Когда-то их цели были благородными." }, { 10.04, "Но теперь они отклонились от первоначального пути и стали слугами порчи просачивающейся из Степей." }, { 18.73, "Я уже стар, и мои силы не бесконечны." }, { 22.07, "Я не мог дольше оставаться в сновидениях, хотя и хотел узнать больше об этих друидах." }, { 29.64, "Но Нара молода и сильна духом, и она осталась там, когда я вынужден был уйти." }, { 36.58, "Поговори с ней, ты найдёшь её в дальней палатке." } } }, t = { d = 17.5, g = 1, v = "tauren-female", n = { m = 146, f = 146 }, c = { m = { { 0.00, "Всё верно, я знаю о друидах из Пещер Стенаний." }, { 4.53, "Я видела их исковерканные, покрытые чешуёй лица." }, { 9.15, "Я знаю об их злодеяниях, и самое главное, мне известны их планы." }, { 15.33, "Ты должен остановить их." } }, f = { { 0.00, "Всё верно, я знаю о друидах из Пещер Стенаний." }, { 4.39, "Я видела их исковерканные, покрытые чешуёй лица." }, { 8.86, "Я знаю об их злодеяниях, и самое главное, мне известны их планы." }, { 14.85, "Ты должна остановить их." } } } } },
    [1491] = { d = 36.2, v = "goblin-male", n = { x = 418 }, c = { x = { { 0.00, "Ладно, рога ящеров не подошли." }, { 2.27, "Ничего страшного, с первого раза никому не удаётся разбогатеть." }, { 6.81, "Кроме того, мне удалось придумать кое-что получше!" }, { 10.51, "Существует вещество, именуемое воющей субстанцией, и мне кажется, именно из-за него в Степях такие странные растения и животные." }, { 19.78, "Принеси мне немного субстанции, и я попробую добавить её в напиток!" }, { 24.58, "Насколько я знаю, это вещество накапливается в эктоплазматических существах в Пещерах Стенаний на западе." }, { 32.10, "Убей несколько существ из пещер и собери из них субстанцию." } } }, t = { d = 13.4, g = 1, v = "goblin-male", n = { m = 124, f = 126 }, c = { m = { { 0.00, "Здорово, ты принёс её!" }, { 1.84, "Не терпится опробовать напиток." }, { 4.53, "Я знаю, он принесёт мне много денег!" }, { 7.60, "Спасибо." }, { 8.37, "Вот тебе деньги, и, разбогатев, я пришлю тебе ещё, клянусь!" } }, f = { { 0.00, "Здорово, ты принесла её!" }, { 2.05, "Не терпится опробовать напиток." }, { 4.71, "Я знаю, он принесёт мне много денег!" }, { 7.75, "Спасибо." }, { 8.50, "Вот тебе деньги, и, разбогатев, я пришлю тебе ещё, клянусь!" } } } } },
    [1492] = { d = 24.6, g = 1, v = "scourge-male", n = { m = 261, f = 263 }, c = { m = { { 0.00, "Мне нужно послать ящик зелий, реактивов и прочего своим партнёрам из Старого Света." }, { 6.40, "У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл." }, { 12.94, "Не мог бы ты отнести ящик управляющему пристанью Головокружилкинсу?" }, { 17.97, "А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья." } }, f = { { 0.00, "Мне нужно послать ящик зелий, реактивов и прочего своим партнёрам из Старого Света." }, { 6.47, "У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл." }, { 13.09, "Не могла бы ты отнести ящик управляющему пристанью Головокружилкинсу?" }, { 18.38, "А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья." } } }, t = { d = 15.4, g = 1, v = "goblin-male", n = { x = 156 }, c = { m = { { 0.00, "Небольшой ящик." }, { 1.20, "Да, пожалуй, для него найдётся место на корабле." }, { 4.72, "Он отплывет в ближайший прилив, это достаточно скоро?" }, { 8.71, "Великолепно." }, { 9.64, "Надо только записать его в мой регистр." }, { 12.63, "Ну вот, всё готово." }, { 14.03, "Пока, герой." } }, f = { { 0.00, "Небольшой ящик." }, { 1.22, "Да, пожалуй, для него найдётся место на корабле." }, { 4.83, "Он отплывет в ближайший прилив, это достаточно скоро?" }, { 8.91, "Великолепно." }, { 9.86, "Надо только записать его в мой регистр." }, { 12.92, "Ну вот, всё готово." }, { 14.35, "Пока, героиня." } } } } },
    [1498] = { d = 35.0, v = "orc-male#60", n = { x = 329 }, c = { x = { { 0.00, "Одна из основных задач воина... защита." }, { 3.47, "Мы – щит Орды, заслоняющий собой наших более слабых братьев." }, { 8.70, "Если ты хочешь вступить в наши ряды, докажи мне, что не струсишь." }, { 14.32, "Ступай в Дуротар, на Громовой хребет, где живут бурешкуры и рокочущие ящерицы." }, { 21.02, "Поохоться на них, докажи, что ты сильнее их!" }, { 24.80, "Выстой против них и принеси мне в доказательство побольше оплавленных чешуек." }, { 31.34, "Как только принесёшь, я возьмусь тебя учить." } } }, t = { d = 21.2, g = 1, v = "orc-male#60", n = { m = 203, f = 205 }, c = { m = { { 0.00, "А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкий парень." }, { 7.20, "А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости." }, { 16.79, "Учись хорошенько." }, { 18.34, "Вскоре тебе предстоит новый урок." } }, f = { { 0.00, "А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкая девчонка." }, { 7.24, "А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости." }, { 16.70, "Учись хорошенько." }, { 18.22, "Вскоре тебе предстоит новый урок." } } } } },
    [1499] = { d = 21.0, g = 1, v = "orc-male", n = { m = 232, f = 233 }, c = { m = { { 0.00, "Зурита часто посылает таких новичков, как ты, приструнить этих тварей." }, { 5.23, "Тебе уже доводилось сражаться с коварными фамильярами." }, { 9.27, "Думаю, тебе не помешает набраться опыта, помогая Зурите." }, { 13.51, "Не забудь ей сказать, что ты помогал разобраться с бесами – возможно, у неё найдётся для тебя награда." } }, f = { { 0.00, "Зурита часто посылает таких новичков, как ты, приструнить этих тварей." }, { 5.28, "Тебе уже доводилось сражаться с коварными фамильярами." }, { 9.35, "Думаю, тебе не помешает набраться опыта, помогая Зурите." }, { 13.63, "Не забудь ей сказать, что ты помогала разобраться с бесами – возможно, у неё найдётся для тебя награда." } } }, t = { d = 12.9, v = "orc-female", n = { x = 117 }, c = { x = { { 0.00, "Молодец!" }, { 0.83, "Да, злобные фамильяры для воинов Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предсказывает тебе великие дела!" } } } } },
    [1501] = { d = 31.0, v = "orc-male", n = { x = 318 }, c = { x = { { 0.00, "Чернокнижников осталось так мало..." }, { 2.80, "Мы многим рискуем, но наш риск оправдан!" }, { 5.95, "Если ты хочешь принести пользу Орде и вождю, пора тебе научиться новому заклинанию призыва." }, { 13.41, "Для начала добудь табличку Верги." }, { 16.13, "Чернокнижники из клана Пылающего Клинка похитили её и хранят у себя в логове, под скалой Черепа к востоку от города." }, { 25.38, "После этого я покажу тебе руны, необходимые для призыва демона Бездны." } } }, t = { d = 14.0, v = "orc-male", n = { x = 143 }, c = { x = { { 0.00, "Молодец." }, { 0.73, "Надеюсь, во время твоего визита в логово чернокнижники из клана Пылающего Клинка сильно пострадали?" }, { 8.83, "Они причинили немало вреда вождю, да и нам, чернокнижникам, тоже." } } } } },
    [1502] = { d = 28.6, v = "orc-male#60", n = { x = 284 }, c = { x = { { 0.00, "Воину пристало владеть хорошим оружием." }, { 3.32, "Самое лучшее оружие делает орк по имени Тун'грим Огневзор." }, { 8.19, "Это отшельник, который живёт на вершине холма к востоку от Перекрёстка." }, { 13.95, "Если тебе нужно оружие, воин, отправляйся к Тун'гриму." }, { 18.53, "Чтобы добраться до его жилища, дойди до Перекрёстка и сверни на восток, в сторону холмов." }, { 25.84, "Он разбил лагерь на самой вершине." } } }, t = { d = 17.3, g = 1, v = "orc-male#60", n = { m = 153, f = 154 }, c = { m = { { 0.00, "Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу." }, { 8.05, "Например, тебе что-то от меня нужно." }, { 11.36, "И раз ты добрался до моего жилища, то я могу предположить, что именно." } }, f = { { 0.00, "Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу." }, { 7.94, "Например, тебе что-то от меня нужно." }, { 11.21, "И раз ты добралась до моего жилища, то я могу предположить, что именно." } } } } },
    [1503] = { d = 36.1, v = "orc-male#60", n = { x = 361 }, c = { x = { { 0.00, "Я дам тебе оружие, но прежде помоги мне." }, { 3.26, "Несколько дней назад с северо-запада на меня напало племя Иглогривых." }, { 8.91, "Биться со мной они побоялись, но зная, какое у меня плохое зрение, одни отвлекли меня своим пофыркиванием, а другие ограбили мой лагерь!" }, { 20.00, "Трусы!" }, { 20.58, "Они украли железный сундук, в котором лежали стальные слитки." }, { 25.65, "Если ты сможешь вернуть их, я дам тебе нужное оружие." }, { 30.00, "Найди мой сундук в одном из лагерей иглогривов и принеси мне стальные слитки." } } }, t = { d = 15.5, v = "orc-male#60", n = { x = 147 }, c = { x = { { 0.00, "Вот они!" }, { 0.76, "И все мои слиточки на месте, что и неудивительно." }, { 4.87, "Откуда иглогривым знать, что делать с такой отличной сталью." }, { 9.97, "Спасибо." }, { 10.73, "Вот твоя награда." }, { 12.25, "Пусть она служит тебе верой и правдой." } } } } },
    [1504] = { d = 29.4, v = "orc-male", n = { x = 310 }, c = { x = { { 0.00, "Посмотри на табличку Верги." }, { 2.18, "Изображённые на ней знаки понадобятся тебе для призыва." }, { 6.41, "Отнеси это в круг в шатре Нииру Огненного Клинка на другом конце пещеры." }, { 12.18, "Там ты сможешь вызвать демона Бездны." }, { 15.14, "Тебе нужно будет одолеть его любыми физическими и магическими средствами." }, { 20.99, "А после этого возвращайся ко мне со знаками призыва, и я покажу тебе, как подчинить это существо своей воле." } } }, t = { d = 22.7, v = "orc-male", n = { x = 218 }, c = { x = { { 0.00, "Молодец!" }, { 0.76, "Я покажу тебе, как вызывать демона Бездны, подобного тому, которого тебе только что пришлось одолеть." }, { 9.46, "Знай, мы на тебя очень рассчитываем, и пока что ты оправдываешь все наши надежды!" }, { 16.24, "Однако пусть успех не кружит тебе голову." }, { 19.83, "Впереди куда более сложные задачи!" } } } } },
    [1505] = { d = 29.7, v = "tauren-male#67", n = { x = 273 }, c = { x = { { 0.00, "Орда чтит своих воинов, потому что никто не сомневается в их силе." }, { 6.03, "Но истинному величию чуждо самодовольство." }, { 9.87, "Никогда не упускай случая поучиться новому." }, { 13.86, "Отыщи Уззека." }, { 15.17, "Он прошёл через много сражений и теперь обучает молодых воинов боевым приёмам." }, { 22.26, "Он живёт на юге от Дальней заставы, орочьего гарнизона на границе Степей и Дуротара." } } }, npc = { [3169] = { d = 27.8, v = "orc-male#60", n = { x = 273 }, c = { x = { { 0.00, "Орда чтит своих воинов, потому что никто не сомневается в их силе." }, { 5.66, "Но истинному величию чуждо самодовольство." }, { 9.26, "Никогда не упускай случая поучиться новому." }, { 13.00, "Отыщи Уззека." }, { 14.23, "Он прошёл через много сражений и теперь обучает молодых воинов боевым приёмам." }, { 20.88, "Он живёт на юге от Дальней заставы, орочьего гарнизона на границе Степей и Дуротара." } } } }, [3354] = { d = 27.6, v = "orc-male#60", n = { x = 273 }, c = { x = { { 0.00, "Орда чтит своих воинов, потому что никто не сомневается в их силе." }, { 5.61, "Но истинному величию чуждо самодовольство." }, { 9.18, "Никогда не упускай случая поучиться новому." }, { 12.89, "Отыщи Уззека." }, { 14.11, "Он прошёл через много сражений и теперь обучает молодых воинов боевым приёмам." }, { 20.70, "Он живёт на юге от Дальней заставы, орочьего гарнизона на границе Степей и Дуротара." } } } } }, t = { d = 3.4, g = 1, v = "orc-male#60", n = { m = 26, f = 28 }, c = { m = { { 0.00, "Привет, юноша." }, { 1.59, "Ты учиться пришёл?" } }, f = { { 0.00, "Привет, девушка." }, { 1.64, "Ты учиться пришла?" } } } } },
    [1506] = { d = 23.3, g = 1, v = "orc-male", n = { x = 220 }, c = { m = { { 0.00, "Эй, ты!" }, { 0.58, "Ты ведь путник, верно?" }, { 2.39, "Надеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Ган'рул." }, { 10.22, "Ты найдёшь его среди старших чернокнижников в расселине Теней." }, { 15.22, "Насколько я знаю Ган'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое." } }, f = { { 0.00, "Эй, ты!" }, { 0.59, "Ты ведь путница, верно?" }, { 2.49, "Надеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Ган'рул." }, { 10.40, "Ты найдёшь его среди старших чернокнижников в расселине Теней." }, { 15.45, "Насколько я знаю Ган'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое." } } }, t = { d = 14.0, v = "orc-male", n = { x = 142 }, c = { x = { { 0.00, "Ага, хорошо." }, { 1.07, "Я опасался, что Офек не сумеет с тобой связаться." }, { 4.98, "Тебе пора продолжить своё обучение на чернокнижника." }, { 9.10, "Все прочие дела пока отложи." }, { 11.45, "Надеюсь, с этим проблем не будет?" } } } } },
    [1507] = { d = 33.8, v = "orc-male", n = { x = 338 }, c = { x = { { 0.00, "Пора тебе научиться новому колдовству." }, { 3.22, "Ты научишься вызывать суккуба, демона в женском обличье." }, { 7.82, "Это существо способно зачаровывать и подчинять себе слабых духом." }, { 13.23, "Но не бойся!" }, { 14.25, "Я уверен, тебя ей не одолеть." }, { 16.66, "Чтобы приманить суккуба, нужен предмет, в котором воплощена искренняя любовь и преданность." }, { 24.12, "Тебе нужно найти такую вещь." }, { 26.53, "Где?" }, { 26.90, "Ну, потолкуй с Казулом." }, { 28.80, "Чего не знает этот старый чернокнижник, того и знать не стоит." } } }, t = { d = 12.8, g = 1, v = "orc-male", n = { x = 101 }, c = { m = { { 0.00, "Хм..." }, { 0.53, "Путник." }, { 1.31, "Ты ещё новичок, но я чую в тебе большие способности." }, { 6.40, "У тебя врождённый дар к чернокнижию." }, { 9.81, "Такими вещами не разбрасываются." } }, f = { { 0.00, "Хм..." }, { 0.52, "Путница." }, { 1.38, "Ты ещё новичок, но я чую в тебе большие способности." }, { 6.36, "У тебя врождённый дар к чернокнижию." }, { 9.71, "Такими вещами не разбрасываются." } } } } },
    [1508] = { d = 25.8, v = "orc-male", n = { x = 238 }, c = { x = { { 0.00, "Раз Ган'рул отправил тебя ко мне, тебе, должно быть, нужно вызвать суккуба, женщину из рода сайаадов, и ты ищешь приманку…" }, { 10.62, "Хмм..." }, { 11.16, "Если ты, согласишься довериться слепому поводырю, то слушай." }, { 16.40, "Среди утёсов Оргриммара, к западу от башни Крыла Ветра, живёт Занкайя." }, { 22.48, "Она ждёт возвращения мужа." }, { 24.83, "Ступай к ней." } } }, t = { d = 8.6, v = "orc-female", n = { x = 97 }, c = { x = { { 0.00, "У тебя есть весточка от Дограна?" }, { 2.27, "Он должен был вернуться уже несколько дней тому назад, а о нём до сих пор ни слуху, ни духу..." } } } } },
    [1509] = { d = 34.0, v = "orc-female", n = { x = 352 }, c = { x = { { 0.00, "Моего супруга, Дограна, не так давно отправили служить в Перекрёсток." }, { 5.25, "Это было повышение по службе, он так гордился…" }, { 8.85, "Мне, конечно, было грустно, но ему я этого не показывала." }, { 13.27, "Грустно и тревожно." }, { 14.79, "Степи – не Оргриммар, это опасное место, и я боялась худшего…" }, { 19.49, "Он должен был вернуться неделю назад, а от него до сих пор нет никаких вестей!" }, { 25.44, "Может, ты сходишь в Перекрёсток, разузнаешь о нём?" }, { 29.17, "Он служил вместе с Газрогом, и Газрог, наверное, до сих пор там..." } } }, t = { d = 15.0, v = "orc-male", n = { x = 128 }, c = { x = { { 0.00, "Занкайя?" }, { 0.81, "Жена Дограна, да?" }, { 2.44, "Слышать-то я о нём слышал, но это не те новости, которые стоит ей передавать." }, { 9.35, "Да нет, не убили его." }, { 11.30, "Но он ранен и сейчас в плену у иглогривов." } } } } },
    [1510] = { d = 29.8, v = "orc-male", n = { x = 336 }, c = { x = { { 0.00, "Он был в Лагере Таурахо, где мы пытались извести иглогривов." }, { 4.34, "Он повёл нескольких рубак на одно из их стойбищ, и там его тяжело ранили." }, { 9.67, "Остальные вернулись и попытались его выручить." }, { 13.09, "Но он был в плохом состоянии, раны загноились, и ребята побоялись его трогать." }, { 18.81, "Они отправили сюда послание, просили троллей из Малака'джина у Когтистых гор прислать целительное зелье." }, { 26.43, "Мы послали за зельем, но гонец пока не вернулся." } } }, t = { d = 15.7, v = "troll-male#78", n = { x = 164 }, c = { x = { { 0.00, "Орк?" }, { 0.35, "Надеюсь, ты не за тем, другим?" }, { 2.64, "А то он добрался не очень... благополучно." }, { 5.83, "Общение с гоблинами не довело его до добра." }, { 9.23, "Он успел сказать, что приехал за целительным зельем, но больше ничего вразумительного." } } } } },
    [1511] = { d = 26.2, v = "troll-male#78", n = { x = 271 }, c = { x = { { 0.00, "Я так и думал, что за зельем явится кто-нибудь ещё!" }, { 3.84, "Вот оно, бери." }, { 5.00, "Имей в виду, сразу всё ему не давай, пусть выпьет половину!" }, { 9.60, "Этого ему хватит, чтобы передвигаться." }, { 12.61, "А иначе он истечёт кровью." }, { 14.60, "На следующее утро пусть выпьет вторую половину." }, { 18.23, "Отнеси это Логмару в Лагерь Таурахо." }, { 21.11, "Судя по тому, что сказал мне первый гонец, Логмар знает, где Догран." } } }, t = { d = 11.7, v = "orc-male#60", n = { x = 116 }, c = { x = { { 0.00, "О, как нельзя более кстати!" }, { 2.21, "А то Догран уже умирает там, в плену." }, { 5.20, "Это нужно доставить ему немедленно." }, { 8.13, "Но большинство моих рубак сейчас на задании..." } } } } },
    [1512] = { d = 20.3, v = "orc-male", n = { x = 213 }, c = { x = { { 0.00, "Занкайя молода и красива." }, { 1.98, "Зачем ей калека?" }, { 3.27, "Несправедливо это будет." }, { 5.19, "Оставь меня." }, { 6.21, "Спасибо тебе." }, { 7.30, "Я предпочёл бы умереть в славной битве, а не влачить это жалкое существование." }, { 13.17, "И прошу тебя, не говори об этом моей супруге..." }, { 16.85, "Не хочу, чтобы она чувствовала себя виноватой." } } }, t = { d = 15.5, v = "orc-male", n = { x = 124 }, c = { x = { { 0.00, "Ну, если ты говоришь, что этого достаточно, я тебе верю." }, { 5.52, "Дай-ка я её оботру..." }, { 7.63, "Да, вот такая, блестящая и чистенькая, она будет куда соблазнительней для суккуба." } } } } },
    [1513] = { d = 25.7, v = "orc-male", n = { x = 259 }, c = { x = { { 0.00, "Отнеси это к кругу призыва в шатре Нииру." }, { 3.56, "Вызови гнусного суккуба и покажи ему, кто здесь хозяин." }, { 8.17, "Я верю в силу твоей магии." }, { 10.47, "Но всё же будь осторожнее: гордость и самоуверенность погубили немало многообещающих чернокнижников." }, { 18.48, "Когда подчинишь суккуба, верни подвеску мне." }, { 22.20, "Нужно будет сообщить Занкайе о случившемся." } } }, t = { d = 36.3, v = "orc-male", n = { x = 370 }, c = { x = { { 0.00, "Получилось!" }, { 0.94, "Впрочем, я ничего другого и не ждал, ведь ты – мой лучший ученик." }, { 6.10, "Теперь я с радостью покажу тебе, как вызывать усмирённого суккуба." }, { 11.41, "Ступай, тебе многому нужно научиться." }, { 14.53, "Я рассчитываю, что к нашей следующей встрече ты уже по-настоящему подчинишь своего суккуба." }, { 21.87, "С печальной историей Дограна и Занкайи разберутся те, кто постарше тебя." }, { 27.68, "Но ты её не забывай: она послужит хорошей защитой от хитростей тёмного демона, который явился к тебе сегодня." } } } } },
    [1514] = { t = { d = 13.5, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений." }, { 6.73, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [1515] = { d = 26.0, v = "orc-male#60", n = { x = 249 }, c = { x = { { 0.00, "Ну, раз уж ты здесь и хочешь завершить своё дело, останавливать тебя я не буду." }, { 6.32, "Но своих воинов я с тобой отпустить не смогу, ступай в одиночку." }, { 11.61, "Дограна держат в лагере иглогривов, к северу отсюда." }, { 15.94, "Ищи две хижины, стоящие рядом." }, { 18.51, "Иглогривы его стерегут – если, конечно, его ещё не убили, или он не умер от ран." }, { 25.12, "Удачи тебе!" } } }, t = { d = 13.7, v = "orc-male", n = { x = 116 }, c = { x = { { 0.00, "Тьфу, гадость…" }, { 1.35, "Однако сил у меня прибавляется." }, { 4.31, "Пожалуй, я теперь смогу уковылять отсюда..." }, { 8.44, "Однако похоже, что ногу мне придётся отнять." }, { 12.58, "И руку тоже." } } } } },
    [1516] = { d = 36.7, g = 1, v = "troll-male#77", n = { m = 337, f = 339 }, c = { m = { { 0.00, "Что ж, герой, пора!" }, { 1.64, "Ты набрался сил, твой дух стоек, как сама Земля." }, { 5.60, "А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости." }, { 12.75, "Стихия земли будет управлять твоей судьбой, станет частью тебя." }, { 18.20, "Готов ли ты?" }, { 19.24, "Тебе придётся предстать перед самой Землёй." }, { 22.82, "И тогда ты увидишь многое, что ведомо лишь шаманам." }, { 27.08, "Разыщи на севере ловцов скверны и добудь два их копыта." }, { 31.70, "А потом возвращайся ко мне, и мы обсудим твоё будущее." } }, f = { { 0.00, "Что ж, героиня, пора!" }, { 1.81, "Ты набралась сил, твой дух стоек, как сама Земля." }, { 5.89, "А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости." }, { 13.12, "Стихия земли будет управлять твоей судьбой, станет частью тебя." }, { 18.63, "Готова ли ты?" }, { 19.76, "Тебе придётся предстать перед самой Землёй." }, { 23.39, "И тогда ты увидишь многое, что ведомо лишь шаманам." }, { 27.69, "Разыщи на севере ловцов скверны и добудь два их копыта." }, { 32.37, "А потом возвращайся ко мне, и мы обсудим твоё будущее." } } }, t = { d = 30.4, g = 1, v = "troll-male#77", n = { m = 285, f = 286 }, c = { m = { { 0.00, "Великолепно!" }, { 1.08, "Твой успех доказывает: ты действительно готов." }, { 5.02, "Среди стихий именно Земля – основа всего сущего." }, { 9.34, "Это твоя сила, твоя выносливость и твоё терпение." }, { 13.66, "Земля защитит тебя, если ты будешь относиться к ней с должным почтением." }, { 19.91, "Но и Земля, как все прочие стихии, может быть своенравной." }, { 24.84, "Теперь я сделаю для тебя сапту." }, { 27.62, "Прими её – и постигнешь свой путь!" } }, f = { { 0.00, "Великолепно!" }, { 1.08, "Твой успех доказывает: ты действительно готова." }, { 5.09, "Среди стихий именно Земля – основа всего сущего." }, { 9.41, "Это твоя сила, твоя выносливость и твоё терпение." }, { 13.74, "Земля защитит тебя, если ты будешь относиться к ней с должным почтением." }, { 19.99, "Но и Земля, как все прочие стихии, может быть своенравной." }, { 24.92, "Теперь я сделаю для тебя сапту." }, { 27.70, "Прими её – и постигнешь свой путь!" } } } } },
    [1517] = { d = 37.0, v = "troll-male#77", n = { x = 361 }, c = { x = { { 0.00, "Сапта – это напиток, который связывает душу со стихией." }, { 4.65, "Сама магия растворена в нём." }, { 7.01, "И сильные духом благодаря ему способны зреть стихии, которых никто более не видит." }, { 13.87, "Твой дух будет связан со стихией сапты." }, { 17.12, "Лишь немногие избранные шаманы знают рецепт этого напитка." }, { 21.99, "Запомни: сапту можно пить лишь в священном месте, и нигде более!" }, { 27.30, "Отыщи Священный Камень к юго-западу отсюда." }, { 30.99, "Он находится в конце Потайной тропы." }, { 34.01, "Выпей там сапту, а дальше... увидишь!" } } }, t = { d = 49.0, g = 1, v = "elemental-earth", n = { m = 405, f = 406 }, c = { m = { { 0.00, "Ах..." }, { 0.52, "Путник..." }, { 1.48, "Земля ликует от того, что ты пришёл сюда." }, { 5.50, "Теперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности." }, { 20.42, "Для прохождения этого обряда довольно было смиренно предстать перед землёй." }, { 27.75, "Но другие обряды потребуют более активных действий." }, { 32.81, "Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий." }, { 40.15, "Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." } }, f = { { 0.00, "Ах..." }, { 0.52, "Путница..." }, { 1.57, "Земля ликует от того, что ты пришла сюда." }, { 5.66, "Теперь ты связана с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности." }, { 20.64, "Для прохождения этого обряда довольно было смиренно предстать перед землёй." }, { 27.96, "Но другие обряды потребуют более активных действий." }, { 33.01, "Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий." }, { 40.32, "Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." } } } } },
    [1518] = { d = 42.3, g = 1, v = "elemental-earth", n = { m = 352, f = 353 }, c = { m = { { 0.00, "Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались." }, { 11.86, "Он создаст тотем для тебя, и этот камушек будет сердцем тотема." }, { 18.23, "Он невелик, но со временем ты поймёшь, что размер не имеет значения." }, { 24.78, "Иногда малое оказывается долговечнее большого." }, { 29.39, "Будь терпелив." }, { 30.80, "Оставайся сильным." }, { 32.66, "И ищи мудрости." }, { 34.26, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } }, f = { { 0.00, "Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались." }, { 11.52, "Он создаст тотем для тебя, и этот камушек будет сердцем тотема." }, { 17.72, "Он невелик, но со временем ты поймёшь, что размер не имеет значения." }, { 24.08, "Иногда малое оказывается долговечнее большого." }, { 28.55, "Будь терпелива." }, { 30.01, "Оставайся сильной." }, { 31.82, "И ищи мудрости." }, { 33.37, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } } }, t = { d = 28.1, g = 1, v = "troll-male#77", n = { m = 293, f = 294 }, c = { m = { { 0.00, "Великолепно!" }, { 1.00, "Тотем, который я создам для тебя, – не просто символ нового статуса." }, { 6.49, "Он обладает тайными возможностями." }, { 9.20, "Его можно использовать для сосредоточения заклинаний Земли." }, { 13.90, "Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно." }, { 20.53, "Наставники скажут тебе, когда ты будешь готов к новым знаниям." }, { 25.59, "А пока возьми этот тотем Земли." } }, f = { { 0.00, "Великолепно!" }, { 0.98, "Тотем, который я создам для тебя, – не просто символ нового статуса." }, { 6.36, "Он обладает тайными возможностями." }, { 9.02, "Его можно использовать для сосредоточения заклинаний Земли." }, { 13.63, "Чем больше мудрост