    [1519] = { d = 43.8, g = 1, v = "tauren-female", n = { m = 399, f = 401 }, c = { m = { { 0.00, "Время настало, юный герой." }, { 2.45, "Тело твоё возмужало, а дух закалился, как сама земля." }, { 7.12, "Я вижу, ты обрёл мудрость." }, { 9.42, "Земля ведёт и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой." }, { 17.25, "Но тебе придётся пройти испытания." }, { 20.26, "Если ты готов, твоему взору откроется то, о чём известно лишь нашему народу." }, { 26.98, "Найди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах." }, { 37.51, "Возвращайся ко мне, когда соберёшь достаточно мази для изготовления зелья." } }, f = { { 0.00, "Время настало, юная героиня." }, { 2.47, "Тело твоё возмужало, а дух закалился, как сама земля." }, { 6.87, "Я вижу, ты обрела мудрость." }, { 9.19, "Земля ведёт и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой." }, { 16.58, "Но тебе придётся пройти испытания." }, { 19.42, "Если ты готова, твоему взору откроется то, о чём известно лишь нашему народу." }, { 25.85, "Найди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах." }, { 35.78, "Возвращайся ко мне, когда соберёшь достаточно мази для изготовления зелья." } } }, t = { d = 36.7, g = 1, v = "tauren-female", n = { m = 328, f = 330 }, c = { m = { { 0.00, "Отлично." }, { 0.79, "Ты вернулся – а значит, готов к следующему шагу." }, { 5.06, "Стихия земли – это основа всех вещей." }, { 8.47, "Это твоя сила, твоя выносливость и твоё терпение." }, { 12.90, "Мать-Земля защитит тебя, но к ней должно относиться с уважением." }, { 18.52, "Она – основа жизни, и следуя её законам, ты приумножишь мудрость." }, { 24.29, "Никогда не забывай тайны, которые она разделит с тобой." }, { 29.28, "Теперь я приготовлю для тебя сапту земли, которая откроет перед тобой новые пути." } }, f = { { 0.00, "Отлично." }, { 0.79, "Ты вернулась – а значит