    [1524] = { d = 41.4, g = 1, v = "orc-male", n = { m = 403, f = 404 }, c = { m = { { 0.00, "У тебя достаточно сил, чтобы управлять тотемом огня, но это ещё не значит, что ты готов к этому." }, { 7.95, "Вдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране." }, { 18.20, "Отыщи путь на вершину, и найдёшь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени." }, { 27.63, "Отнеси ему этот факел – это знак, что ты пытаешься приручить огонь." }, { 33.28, "Верни мне этот факел зажжённым от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотем огня." } }, f = { { 0.00, "У тебя достаточно сил, чтобы управлять тотемом огня, но это ещё не значит, что ты готова к этому." }, { 7.84, "Вдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране." }, { 17.85, "Отыщи путь на вершину, и найдёшь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени." }, { 27.07, "Отнеси ему этот факел – это знак, что ты пытаешься приручить огонь." }, { 32.58, "Верни мне этот факел зажжённым от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотем огня." } } }, t = { d = 31.8, v = "troll-male#77", n = { x = 309 }, c = { x = { { 0.00, "А, я ошибся!" }, { 1.05, "Прошу прощения." }, { 2.40, "Я не знал, что у тебя с собой этот факел." }, { 5.86, "Очень рад познакомиться." }, { 7.89, "Сюда забредает немало путешественников, которые ищут клады или охотятся на невиданных зверей, и мне приходится прогонять их из этого святилища, которое кажется пустым." }, { 21.86, "Но мы-то с тобой знаем истину, не так ли?" }, { 25.31, "Это святилище скрывает от несведущих великую тайну." }, { 29.67, "Для нас эта тайна священна!" } } } } },
    [1525] = { d = 44.2, v = "troll-male#77", n = { x = 460 }, c = { x = { { 0.00, "Но ты ведь здесь не затем, чтобы выслушивать лекции по истории, верно?" }, { 5.43, "Тебе нужно Неугасимое Пламя и тотем Огня!" }, { 8.82, "Первый шаг – это создать сапту, чтобы связать тебя со стихией огня." }, { 14.26, "Я могу изготовить тебе сапту, но для этого нужны две вещи." }, { 18.91, "Во-первых – огненная смола, распространённое вещество, которое обычно носят при себе заклинатели Иглогривых в восточных Степях." }, { 28.79, "А вот второй компонент добыть куда сложнее: это мешочек с реактивами, какие носят чернокнижники из клана Пылающего Клинка." }, { 38.46, "Их можно отыскать в пещере над ущельями к северо-востоку от Колючего Холма." } } }, t = { d = 37.0, v = "troll-male#77", n = { x = 368 }, c = { x = { { 0.00, "Это как раз то, что надо." }, { 2.09, "Огонь – это не просто хаос и разрушение." }, { 5.53, "Запомни это хорошенько!" }, { 7.54, "Огонь – это ещё и жизнь, и творение!" }, { 10.53, "Всё в мире взаимосвязано подобным же образом." }, { 14.27, "Противоборствующие силы противостоят друг другу, но при этом не могут существовать поодиночке." }, { 21.96, "Они взаимно уничтожаются, но придают друг другу смысл." }, { 26.44, "Помни об этом!" }, { 27.71, "Одновременное использование различных видов магии говорит не только о подлинном искусстве, но и о большой мудрости." } } } } },
    [1526] = { d = 34.5, g = 1, v = "troll-male#77", n = { m = 364, f = 365 }, c = { m = { { 0.00, "Сапта огня готова." }, { 1.45, "Пришло тебе время встретиться лицом к лицу со стихией пламени!" }, { 6.14, "Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление." }, { 12.35, "Оно не нападёт на тебя, пока ты не будешь готов к этому, однако оно поймёт, что ты его видишь." }, { 19.29, "Постарайся поразить его как можно быстрее, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберёт!" }, { 27.02, "Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел." } }, f = { { 0.00, "Сапта огня готова." }, { 1.50, "Пришло тебе время встретиться лицом к лицу со стихией пламени!" }, { 6.35, "Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление." }, { 12.77, "Оно не нападёт на тебя, пока ты не будешь готова к этому, однако оно поймёт, что ты его видишь." }, { 20.01, "Постарайся поразить его как можно быстрее, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберёт!" }, { 28.00, "Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел." } } }, t = { d = 17.8, v = "narrator", n = { x = 174 }, c = { x = { { 0.00, "Когда вы бросаете уголёк в жаровню, в чаше вспыхивает жаркое белое пламя." }, { 6.20, "Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьётся пламя." }, { 13.46, "Вы опускаете факел в чашу, и он мгновенно вспыхивает." } } } } },
    [1527] = { d = 21.4, v = "narrator", n = { x = 211 }, c = { x = { { 0.00, "Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Дуротар." }, { 8.19, "Вас охватывает восторг." }, { 10.18, "Пламя факела рвётся и трепещет на ветру." }, { 13.63, "И вот вы начинаете спускаться обратно по тропе, ведущей в Степи, возвращаясь к Краналу Фиссу." } } }, t = { d = 20.8, v = "orc-male", n = { x = 200 }, c = { x = { { 0.00, "Твой дух пылает ярче любого факела!" }, { 3.04, "Тебе есть чем гордиться." }, { 5.09, "Не сходи с избранного пути, и стихии будут повиноваться тебе, а наши собратья станут искать у тебя советов и наставлений." }, { 15.41, "Позволь мне первым поздравить тебя и вручить тебе новый тотем..." } } } } },
    [1528] = { d = 31.9, g = 1, v = "troll-male#77", n = { m = 301, f = 304 }, c = { m = { { 0.00, "Вода – твоё будущее, дружище." }, { 2.48, "Вижу, ты уже покорил огонь и, кажись, готов поговорить с Ислен." }, { 7.91, "Ислен живёт на побережье ентих Степей." }, { 11.14, "Топай на юг, вдоль реки Строптивая, не промахнёшься – ищи нехилую акулу!" }, { 17.09, "Ислен – великая повелительница духов, и она научит тебя сути воды... если ты готов." }, { 24.24, "Ты её запростяк найдёшь, только на юг слишком далеко не заходи: Ислен живёт рядом с Кабестаном." } }, f = { { 0.00, "Вода – твоё будущее, дружище." }, { 2.43, "Вижу, ты уже покорила огонь и, кажись, готова поговорить с Ислен." }, { 7.88, "Ислен живёт на побережье ентих Степей." }, { 11.05, "Топай на юг, вдоль реки Строптивая, не промахнёшься – ищи нехилую акулу!" }, { 16.86, "Ислен – великая повелительница духов, и она научит тебя сути воды... если ты готова." }, { 23.93, "Ты её запростяк найдёшь, только на юг слишком далеко не заходи: Ислен живёт рядом с Кабестаном." } } }, t = { d = 19.6, v = "tauren-female#71", n = { x = 174 }, c = { x = { { 0.00, "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды." }, { 11.49, "Путь твой был долог, и сила духа позволит тебе пройти ещё дальше." }, { 17.35, "Но первый шаг делать тебе." } } } } },
