    [1530] = { d = 32.1, g = 1, v = "tauren-female#71", n = { m = 304, f = 304 }, c = { m = { { 0.00, "Первым делом ты должен понять, что вода означает возрождение." }, { 5.32, "Вода течёт, разрушает и очищает всё сущее." }, { 8.95, "Ты увидишь, что вода – великий целитель, но только чистая вода." }, { 14.42, "Познав, что осквернённая вода разрушает всё кругом, ты поймёшь и то, как вода важна для мироздания." }, { 22.67, "Если же ты хочешь получить сапту воды, отыщи Брин в южной части Степей." }, { 28.92, "На её дом постоянно нападают иглогривы." } }, f = { { 0.00, "Первым делом ты должна понять, что вода означает возрождение." }, { 5.27, "Вода течёт, разрушает и очищает всё сущее." }, { 8.86, "Ты увидишь, что вода – великий целитель, но только чистая вода." }, { 14.28, "Познав, что осквернённая вода разрушает всё кругом, ты поймёшь и то, как вода важна для мироздания." }, { 22.45, "Если же ты хочешь получить сапту воды, отыщи Брин в южной части Степей." }, { 28.63, "На её дом постоянно нападают иглогривы." } } }, t = { d = 31.1, g = 1, v = "orc-female", n = { m = 334, f = 335 }, c = { m = { { 0.00, "Да?" }, { 0.27, "М-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредёт в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты?" }, { 11.61, "У всех нас свои причины действовать так или иначе." }, { 15.46, "У меня другой вопрос – что заставило простого героя отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие?" }, { 26.87, "Готова поспорить, что мы оба знаем ответ на этот вопрос." } }, f = { { 0.00, "Да?" }, { 0.27, "М-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредёт в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты?" }, { 11.44, "У всех нас свои причины действовать так или иначе." }, { 15.23, "У меня другой вопрос – что заставило простую героиню отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие?" }, { 26.54, "Готова поспорить, что мы оба знаем ответ на этот вопрос." } } } } },
    [1531] = { d = 31.4, g = 1, v = "troll-male#77", n = { m = 320, f = 321 }, c = { m = { { 0.00, "Ты делаешь успехи, дружище." }, { 2.16, "Я верю, что ты достоин тотема воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл." }, { 10.19, "Отнесись к ней с уважением, и она расскажет, как получить тотем." }, { 15.14, "Иди на юг, через Степи, а когда попадёшь в Тысячу Игл, сверни на восток." }, { 20.72, "Пратта прячется в пещере вместе со своим парнем." }, { 24.56, "Ха-ха!" }, { 25.12, "Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится." } }, f = { { 0.00, "Ты делаешь успехи, дружище." }, { 2.18, "Я верю, что ты достойна тотема воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл." }, { 10.34, "Отнесись к ней с уважением, и она расскажет, как получить тотем." }, { 15.33, "Иди на юг, через Степи, а когда попадёшь в Тысячу Игл, сверни на восток." }, { 20.96, "Пратта прячется в пещере вместе со своим парнем." }, { 24.83, "Ха-ха!" }, { 25.39, "Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится." } } }, t = { d = 13.7, g = 1, v = "tauren-female#71", n = { m = 143, f = 144 }, c = { m = { { 0.00, "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха." }, { 7.84, "Возьми этот тотем." }, { 9.43, "Возвращайся, когда будешь готов продолжить обучение." } }, f = { { 0.00, "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха." }, { 7.89, "Возьми этот тотем." }, { 9.49, "Возвращайся, когда будешь готова продолжить обучение." } } } } },
    [1532] = { d = 37.4, g = 1, v = "tauren-male#68", n = { m = 348, f = 347 }, c = { m = { { 0.00, "Все ветра Калимдора спешат к тебе навстречу, и скоро ты займёшь достойное место среди наших самых выдающихся братьев." }, { 10.32, "Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждёт великое будущее." }, { 17.02, "Дух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своём пути." }, { 25.61, "Отправляйся на самый юг Степей, в Тысячу Игл." }, { 29.55, "Там, на востоке, ты найдёшь Пратту Заклинательницу Туч, и она продолжит твоё обучение." } }, f = { { 0.00, "Все ветра Калимдора спешат к тебе навстречу, и скоро ты займёшь достойное место среди наших самых выдающихся сестёр." }, { 10.41, "Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждёт великое будущее." }, { 17.27, "Дух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своём пути." }, { 26.06, "Отправляйся на самый юг Степей, в Тысячу Игл." }, { 30.10, "Там, на востоке, ты найдёшь Пратту Заклинательницу Туч, и она продолжит твоё обучение." } } }, t = { d = 13.5, g = 1, v = "tauren-female#71", n = { m = 143, f = 144 }, c = { m = { { 0.00, "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха." }, { 7.70, "Возьми этот тотем." }, { 9.26, "Возвращайся, когда будешь готов продолжить обучение." } }, f = { { 0.00, "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха." }, { 7.80, "Возьми этот тотем." }, { 9.38, "Возвращайся, когда будешь готова продолжить обучение." } } } } },
    [1534] = { d = 32.8, v = "orc-female", n = { x = 347 }, c = { x = { { 0.00, "Возьми этот бурдюк и ступай в густой лес, который ночные эльфы зовут Ясеневым." }, { 6.23, "Он находится далеко на севере от Степей." }, { 9.37, "Добравшись до леса, отправляйся в его западную часть." }, { 13.50, "Возле гряды, отделяющей Когтистые горы от Ясеневого леса, за озером Мистраль, располагается священное место, руины Звёздной Пыли." }, { 23.58, "В центре озера, на островке, есть маленький фонтан." }, { 27.56, "Прежде чем возвращаться к Ислен, принеси мне воду из этого источника." } } }, t = { d = 24.6, v = "orc-female", n = { x = 245 }, c = { x = { { 0.00, "Чудесно." }, { 0.73, "Теперь у меня есть все три пробы воды, и я могу наполнить фиал чистейшей водой, которую только способно найти живое существо." }, { 11.04, "Она понадобится тебе на следующем этапе." }, { 14.41, "Я рада, что среди избравших наш путь есть такие, как ты." }, { 18.87, "Все шаманы гордятся тобой, и я надеюсь вскоре услышать о твоих подвигах." } } } } },
    [1535] = { d = 31.9, v = "orc-female", n = { x = 325 }, c = { x = { { 0.00, "Чтобы обрести понимание и получить от меня сапту, тебе предстоит отыскать чистейшую воду." }, { 7.31, "Принося мне образцы, обращай внимание на окружающий мир – какие существа зависят от этой воды и охраняют её." }, { 16.00, "Как она влияет на леса и пустыни." }, { 18.75, "Ты увидишь, как влага, дающая жизнь сущему, вынуждает различных существ отнимать эту жизнь у других." }, { 26.79, "Начнём с малого: ниже моего домика есть пруд с драгоценной влагой." } } }, t = { d = 27.7, v = "orc-female", n = { x = 292 }, c = { x = { { 0.00, "Я предполагала, что если ты возьмёшься набирать воду, кровопролития не избежать." }, { 6.15, "Жаль, что иглогривы не понимают, что все живые существа связаны между собой, а жадность лишь усиливает боль и страдания их собственного народа." }, { 17.16, "О, сколь многого они достигли бы, забыв о спорах и объединившись." }, { 22.25, "Да, для них это плохо, но для других обитателей Степей – скорее хорошо." } } } } },
    [1536] = { d = 35.1, v = "orc-female", n = { x = 396 }, c = { x = { { 0.00, "Давным-давно мы с несколькими спутниками отправились в предгорья Хилсбрада." }, { 5.47, "Нам пришлось отбиваться от навязчивых людей, поселившихся в тех краях, и в итоге мы оказались в городке, захваченном Отрёкшимися, – Мельнице Таррен." }, { 16.20, "И удивительное дело – в центре города обнаружился маленький источник свежей родниковой воды." }, { 23.07, "Не думаю, что поражённые чумой жители города осознают его ценность – это малый луч света в царстве тьмы." }, { 30.80, "Набери воду из этого источника в этот бурдюк и принеси мне." } } }, t = { d = 15.2, v = "orc-female", n = { x = 150 }, c = { x = { { 0.00, "Хорошо." }, { 0.68, "Ты изо всех сил стараешься выполнить порученные тебе задания и добиваешься успеха." }, { 7.53, "Ещё одна проба воды, и я смогу создать реактив, необходимый для сапты." }, { 13.47, "Ислен будет довольна." } } } } },
    [1558] = { d = 32.7, v = "child-male", n = { x = 349 }, c = { x = { { 0.00, "В Стальгорне живут все дворфы и гномы." }, { 2.88, "Рядом есть местечко, которое зовётся озером Лок Модан, и именно там дворфы отгрохали ЗДОРОВЕННУЮ дамбу." }, { 10.51, "Говорят, это одна из самых больших построек в мире." }, { 14.15, "Во как!" }, { 15.25, "Пожалуйста, своди меня к озеру Лок Модан, посмотреть на дамбу!" }, { 19.94, "Как она называется?" }, { 21.41, "Кажется, Каминная дамба?" }, { 23.29, "Нет, камин – это что-то не то." }, { 25.56, "В общем, она большая." }, { 27.24, "И на огромный водопад хочется посмотреть." }, { 30.32, "Обещаю, я не буду к нему наклоняться!" } } }, t = { d = 24.5, g = 1, v = "child-male", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Ух ты!" }, { 0.50, "Она ещё БОЛЬШЕ, чем я думал!" }, { 2.79, "Я собственного голоса не слышу из-за грохота воды!" }, { 6.86, "Эй, а вода там не закончится?" }, { 9.15, "Ой, а что будет, если дамба рухнет!" }, { 12.01, "Вот это было бы страшно!" }, { 14.01, "Спасибо, что показал мне дамбу." }, { 16.51, "Это было очень мило с твоей стороны." }, { 19.59, "Я же говорил, что не буду сильно перевешиваться через край!" } }, f = { { 0.00, "Ух ты!" }, { 0.51, "Она ещё БОЛЬШЕ, чем я думал!" }, { 2.83, "Я собственного голоса не слышу из-за грохота воды!" }, { 6.96, "Эй, а вода там не закончится?" }, { 9.27, "Ой, а что будет, если дамба рухнет!" }, { 12.17, "Вот это было бы страшно!" }, { 14.20, "Спасибо, что показала мне дамбу." }, { 16.81, "Это было очень мило с твоей стороны." }, { 19.92, "Я же говорил, что не буду сильно перевешиваться через край!" } } } } },
    [1559] = { t = { d = 11.7, g = 1, v = "goblin-male#108", n = { m = 115, f = 116 }, c = { m = { { 0.00, "Так ты, значит, инженер?" }, { 1.97, "Что ж, за то, что ты добыл мне жемчужины, вот тебе секрет изготовления световых бомб." }, { 8.69, "Удачи, и постарайся не ослепить себя!" } }, f = { { 0.00, "Так ты, значит, инженер?" }, { 1.97, "Что ж, за то, что ты добыла мне жемчужины, вот тебе секрет изготовления световых бомб." }, { 8.77, "Удачи, и постарайся не ослепить себя!" } } } } },
    [1560] = { d = 18.0, v = "creature/tooga", n = { x = 113 }, c = { x = { { 0.00, "Я заблудился!" }, { 1.66, "Моя жена, Торта, отправила меня за обедом, но я не туда свернул." }, { 9.75, "Отведи меня обратно к Торте!" }, { 13.41, "Она ждёт меня на юге от Порта Картеля." } } }, t = { d = 11.8, v = "creature/torta", n = { x = 69 }, c = { x = { { 0.00, "Он что, сам не смог найти дорогу?" }, { 4.24, "Как обычно." }, { 5.77, "Да, видно тебе надо дать что-нибудь за труды..." } } } } },
    [1578] = { d = 32.2, v = "dwarf-male", n = { x = 400 }, c = { x = { { 0.00, "Горная пехота озера Лок Модан без передышки сражается с троггами!" }, { 4.38, "Им нужен постоянный подвоз новых доспехов и оружия, иначе с троггами не справиться." }, { 9.97, "Мой коллега Торвальд как раз и поехал туда – за тем чтобы у солдат было доброе снаряжение." }, { 15.97, "Так что если бы вы могли изготовить несколько медных топоров и плетёных поясов и доставить их Торвальду, он был бы очень вам благодарен." }, { 24.86, "Он даже может поделиться с вами своими знаниями." }, { 28.16, "Торвальда вы найдёте в южной сторожевой башне озера Лок Модан." } } }, t = { d = 14.0, g = 1, v = "dwarf-male", n = { m = 146, f = 146 }, c = { m = { { 0.00, "Ох, прости!" }, { 0.91, "Я и не понял, что ты пришёл помочь в деле вооружения наших войск." }, { 5.86, "Изготовленные тобой вещи очень нам помогут!" }, { 9.27, "Вот чертежи кое-каких доспехов." }, { 11.78, "Надеюсь, они тебе пригодятся." } }, f = { { 0.00, "Ох, прости!" }, { 0.87, "Я и не понял, что ты пришла помочь в деле вооружения наших войск." }, { 5.66, "Изготовленные тобой вещи очень нам помогут!" }, { 8.92, "Вот чертежи кое-каких доспехов." }, { 11.32, "Надеюсь, они тебе пригодятся." } } } } },
    [1579] = { d = 28.5, v = "goblin-male", n = { x = 315 }, c = { x = { { 0.00, "Я прибыл в Аубердин в поисках тишины и покоя." }, { 3.36, "Я хочу заниматься своими изобретениями там, где царит покой, потому что после ночных попоек мне совсем не нравится гомон Стальгорна!" }, { 12.99, "Так что я отправился на корабле в Аубердин... и по дороге слегка перебрал." }, { 18.34, "Я уронил за борт мой ящик с суперразъёмами!" }, { 21.37, "Точно не знаю, где я их потерял, но если ты попытаешься выловить их в океане, может, тебе повезёт..." } } }, t = { d = 7.8, g = 1, v = "goblin-male", n = { m = 72, f = 72 }, c = { m = { { 0.00, "Ах, не могу поверить, что тебе удалось их найти!" }, { 3.64, "Должно быть, ты самый везучий герой на Калимдоре!" } }, f = { { 0.00, "Ах, не могу поверить, что тебе удалось их найти!" }, { 3.64, "Должно быть, ты самая везучая героиня на Калимдоре!" } } } } },
    [1580] = { d = 37.4, v = "goblin-male", n = { x = 415 }, c = { x = { { 0.00, "Мы знаем, что тебе везёт, но... насколько сильно везёт?" }, { 3.97, "Однажды ночью я бродил по дорогам Тёмного Берега." }, { 7.61, "Я искал речку или озеро, пригодные для испытания моей самодвижущейся и взрывающейся подсадной утки и, думаю, был слегка пьян... поскольку потерял сознание и пришёл в себя в Аубердине спустя несколько часов." }, { 22.70, "Мои волосы были опалены, а сумка с электропеллерами исчезла!" }, { 27.20, "Должно быть, я уронил её в воду!" }, { 29.58, "Мне нужны эти электропеллеры!" }, { 31.76, "Может быть, тебе удастся выловить их из какого-нибудь водоёма на Тёмном Берегу?.." } } }, t = { d = 14.6, g = 1, v = "goblin-male", n = { m = 136, f = 138 }, c = { m = { { 0.00, "Глазам не верю!" }, { 1.28, "Ты их нашёл!" }, { 2.20, "Ты лучший рыбак на моей памяти!" }, { 4.76, "Спасибо тебе." }, { 5.89, "И вот, возьми это." }, { 7.39, "Хотя ты, наверное, в этом и не нуждаешься, оно послужит тебе подспорьем при ужении." } }, f = { { 0.00, "Глазам не верю!" }, { 1.28, "Ты их нашла!" }, { 2.41, "Ты лучшая рыбачка на моей памяти!" }, { 5.48, "Спасибо тебе." }, { 6.61, "И вот, возьми это." }, { 8.11, "Хотя ты, наверное, в этом и не нуждаешься, оно послужит тебе подспорьем при ужении." } } } } },
    [1581] = { d = 21.8, v = "nightelf-female#51", n = { x = 270 }, c = { x = { { 0.00, "Наша лавочка трав и алхимических снадобий процветает, но мой муж проводит столько времени за изготовлением эликсиров, что почти забыл про личную жизнь!" }, { 10.01, "Ты нам не поможешь?" }, { 11.28, "Если ты привезёшь мне партию уже готовых эликсиров, я охотно куплю их у тебя." }, { 16.50, "У меня есть некоторые редкие травы, которые могут оказаться полезными для тебя." } } }, t = { d = 12.0, g = 1, v = "nightelf-female#51", n = { m = 134, f = 135 }, c = { m = { { 0.00, "Прекрасные снадобья!" }, { 1.53, "Ты проявил исключительную щепетильность, что очень важно для алхимика!" }, { 6.65, "Вот твои травы, я только-только их собрала." }, { 9.91, "Пусть они тебе пригодятся!" } }, f = { { 0.00, "Прекрасные снадобья!" }, { 1.55, "Ты проявила исключительную щепетильность, что очень важно для алхимика!" }, { 6.82, "Вот твои травы, я только-только их собрала." }, { 10.12, "Пусть они тебе пригодятся!" } } } } },
    [1582] = { d = 22.2, v = "nightelf-female#53", n = { x = 262 }, c = { x = { { 0.00, "У нас, жителей Дарнасса, в особенности у ремесленников, работы невпроворот." }, { 5.27, "Молодым искателям приключений неймётся испытать себя во всякой глухомани, так что нам постоянно нужен подвоз материалов." }, { 13.77, "Если ты поможешь мне выполнить заказ на кожаные изделия, я, может, научу тебя более совершенной технике работы с кожей." } } }, t = { d = 13.4, v = "nightelf-female#53", n = { x = 132 }, c = { x = { { 0.00, "Да, славные изделия." }, { 1.71, "У тебя искусные руки и острый глаз." }, { 4.68, "Из тебя может получиться неплохой кожевник." }, { 8.32, "Слушай." }, { 8.99, "Давай-ка я покажу тебе выкройку жилета Лунного сияния." } } } } },
    [1598] = { d = 38.8, g = 1, v = "human-female#47", n = { m = 453, f = 455 }, c = { m = { { 0.00, "Ах, это ты!" }, { 0.79, "Это ведь о тебе мне говорили, верно?" }, { 3.29, "Надеюсь, ты точно уверен, что желаешь стать чернокнижником, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего." }, { 12.42, "Я буду тебя обучать, но сначала я должна убедиться, что ты достаточно силён." }, { 17.54, "В здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости." }, { 24.05, "Почему меня это волнует?" }, { 25.82, "А потому, что он стянул из аббатства кое-какие важные книги." }, { 29.96, "Одну из них я сама хотела бы иметь." }, { 32.39, "Братство прячет эту книгу – \"Силы Бездны\" – в своём шатре на виноградниках." }, { 37.51, "Принеси её мне." } }, f = { { 0.00, "Ах, это ты!" }, { 0.80, "Это ведь о тебе мне говорили, верно?" }, { 3.31, "Надеюсь, ты точно уверена, что желаешь стать чернокнижницей, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего." }, { 12.55, "Я буду тебя обучать, но сначала я должна убедиться, что ты достаточно сильна." }, { 17.82, "В здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости." }, { 24.37, "Почему меня это волнует?" }, { 26.14, "А потому, что он стянул из аббатства кое-какие важные книги." }, { 30.31, "Одну из них я сама хотела бы иметь." }, { 32.76, "Братство прячет эту книгу – \"Силы Бездны\" – в своём шатре на виноградниках." }, { 37.90, "Принеси её мне." } } }, t = { d = 19.6, g = 1, v = "human-female#47", n = { m = 241, f = 242 }, c = { m = { { 0.00, "Замечательно..." }, { 1.01, "Мне никогда не удавалось добраться до этой книги, её держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг." }, { 10.74, "Ладно, ты отлично потрудился, и я уверена, что ты сумеешь справиться со своим собственным бесом." }, { 17.03, "Пора показать тебе, как его вызывать!" } }, f = { { 0.00, "Замечательно..." }, { 1.01, "Мне никогда не удавалось добраться до этой книги, её держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг." }, { 10.79, "Ладно, ты отлично потрудилась, и я уверена, что ты сумеешь справиться со своим собственным бесом." }, { 17.18, "Пора показать тебе, как его вызывать!" } } } } },
    [1599] = { d = 43.4, v = "gnome-male", n = { x = 506 }, c = { x = { { 0.00, "Тут все шепчутся о каком-то новом чернокнижнике; наверное, это ты и есть." }, { 5.04, "Должно быть, ты вызываешь кое у кого сильную симпатию, раз меня попросили отвлечься от моих изысканий и посвятить некоторое время занятиям с тобой." }, { 15.38, "Не беспокойся: я не ставлю это тебе в вину." }, { 18.47, "Что ж, самое простое из заклинаний призыва позволяет вызвать беса." }, { 23.14, "Однако, прежде чем я преподам тебе этот урок, мне хотелось бы получить доказательства того, что у тебя достаточно как физической, так и магической силы..." }, { 33.86, "Принеси мне три оберега из перьев." }, { 36.25, "Ты получишь их, если расправишься с новобранцами племени Мерзлогривов в пещере, что к юго-западу отсюда." } } }, t = { d = 39.8, v = "gnome-male", n = { x = 456 }, c = { x = { { 0.00, "Прекрасно, прекрасно!" }, { 1.52, "В самом деле, неплохая работа." }, { 3.74, "Возможно, те, кто тебя рекомендовал, и не ошиблись..." }, { 7.41, "Впрочем, это не мне решать." }, { 9.37, "Поживём – увидим." }, { 10.58, "Будем надеяться, что первый же вызванный бес не вырвет тебе сердце и не сожрёт внутренности – думаю, подобное могло бы серьёзно повредить твоей карьере." }, { 21.16, "Пока у меня есть основания полагать, что в качестве чернокнижника ты сумеешь прожить хотя бы несколько месяцев." }, { 28.95, "Кстати, хотел дать тебе совет по поводу бесов." }, { 32.30, "Запомни, размер – ещё не главное: даже самый глупый таурен знает, что бесы наделены весьма сильной магией." } } } } },
    [1618] = { d = 22.1, v = "dwarf-male", n = { x = 239 }, c = { x = { { 0.00, "Не только мы, дворфы, сражаемся денно и нощно – люди, наши союзники, тоже не прохлаждаются!" }, { 6.93, "На Красногорье время от времени устраивают налёты орки Чёрной Горы, а снаряжения туда всегда мало поставляется." }, { 15.36, "Если ты им поможешь, то местный кузнец Вернер Осгуд наверняка научит тебя паре хитростей." } } }, t = { d = 22.6, v = "human-male#50", n = { x = 271 }, c = { x = { { 0.00, "Спасибо." }, { 0.62, "Это чрезвычайно мне поможет." }, { 2.59, "Орки Чёрной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск." }, { 15.98, "То, что ты принёс, даст мне хоть небольшую передышку." }, { 19.43, "И у меня будет время кое-чему тебя научить..." } } } } },
    [1638] = { d = 19.0, v = "human-female#47", n = { x = 226 }, c = { x = { { 0.00, "Ты в самом деле неплохой воин, но лет тебе мало, и ещё многому придётся научиться." }, { 5.57, "Поговори с Гарри Берлгардом – обычно он сидит в \"Свинье и Свистке\", в Старом городе Штормграда." }, { 12.06, "Гарри опытный боец и неплохой учитель." }, { 14.75, "Он покажет тебе несколько приёмов, глядишь, и подольше проживёшь." } } }, t = { d = 12.2, g = 1, v = "human-male", n = { m = 121, f = 121 }, c = { m = { { 0.00, "О-хо!" }, { 0.50, "Выпей со мной." }, { 1.65, "С первого взгляда ты кажешься крепким, посмотрим, что с тобой сделает несколько кружек крепкого пива!" }, { 9.74, "Или..." }, { 10.31, "А, да ты поучиться хочешь?" } }, f = { { 0.00, "О-хо!" }, { 0.50, "Выпей со мной." }, { 1.65, "С первого взгляда ты кажешься крепкой, посмотрим, что с тобой сделает несколько кружек крепкого пива!" }, { 9.74, "Или..." }, { 10.31, "А, да ты поучиться хочешь?" } } } } },
    [1639] = { d = 17.3, g = 1, v = "human-male", n = { m = 181, f = 182 }, c = { m = { { 0.00, "Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься." }, { 6.21, "Видишь, в конце бара стоит выпивка?" }, { 8.98, "Бартлби тоже видишь?" }, { 10.61, "Добудь эту кружку." }, { 12.09, "Ха, если ты знаком с ним, то догадаешься, что так просто он её не отдаст." } }, f = { { 0.00, "Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься." }, { 6.10, "Видишь, в конце бара стоит выпивка?" }, { 8.83, "Бартлби тоже видишь?" }, { 10.42, "Добудь эту кружку." }, { 11.88, "Ха, если ты знакома с ним, то догадаешься, что так просто он её не отдаст." } } }, t = { d = 7.8, g = 1, v = "human-male#50", n = { m = 79, f = 79 }, c = { m = { { 0.00, "Эй, красавчик!" }, { 1.11, "Что таким как ты делать в \"Свинье и свистке\"?" }, { 4.58, "Осторожнее, неровен час, ноготь сломаешь..." } }, f = { { 0.00, "Эй, красавица!" }, { 1.11, "Что таким как ты делать в \"Свинье и свистке\"?" }, { 4.58, "Осторожнее, неровен час, ноготь сломаешь..." } } } } },
    [1640] = { d = 5.7, g = 1, v = "human-male#50", n = { m = 58, f = 59 }, c = { m = { { 0.00, "Что ты хочешь?" }, { 1.11, "Да ты спятил!" }, { 2.15, "Эту кружку ты получишь только через мой труп..." } }, f = { { 0.00, "Что ты хочешь?" }, { 1.10, "Да ты спятила!" }, { 2.19, "Эту кружку ты получишь только через мой труп..." } } }, t = { d = 3.0, v = "human-male#50", n = { x = 35 }, c = { x = { { 0.00, "А ты крепче, чем кажешься с первого взгляда." } } } } },
    [1641] = { t = { d = 34.5, v = "human-male", n = { x = 375 }, c = { x = { { 0.00, "Здесь, в Штормграде, я – наставник паладинов." }, { 3.29, "Я – тот, кто ведёт их стезёй добродетели к Истинному Свету, дабы они защищали Азерот от нашествия нежити и иных бедствий." }, { 12.21, "И для тебя пришло время сделать первый шаг на пути праведности." }, { 16.98, "Если ты решишься принять этот путь, я дам тебе Фолиант Божественности." }, { 22.21, "Изучая его, ты узнаешь кое-что о Свете и о том, чего от тебя ожидают." }, { 27.45, "Постигнув мудрость, заключённую в этой книге, ты откроешь в себе новые, удивительные способности." } } } } },
    [1642] = { d = 42.8, v = "narrator", n = { x = 425 }, c = { x = { { 0.00, "Во всех своих деяниях паладин должен быть достоин того Света, которому мы служим и который дарует нам силу." }, { 8.93, "Для таких, как мы, стремление к божественности не означает желания стать богами: мы лишь стремимся творить добро." }, { 18.09, "Ныне наступили тяжёлые времена: мы избраны для того, чтобы сражаться со злом и повергнуть его." }, { 25.83, "Однако помни: не борьба со злом отличает нас от прочих жителей Азерота." }, { 31.71, "Сострадание, терпение, отвага и помощь ближним – для паладина всё это значит не меньше, чем искусство воина." }, { 40.65, "Никогда не забывай об этом!" } } }, t = { d = 36.5, v = "human-male", n = { x = 411 }, c = { x = { { 0.00, "И снова рад приветствовать тебя." }, { 2.37, "Как идёт изучение Фолианта Божественности?" }, { 5.39, "Помни: тебе предстоит пройти испытание." }, { 8.35, "Каждого из нас ждёт множество свершений – как в городе, так и в иных землях." }, { 13.81, "Всегда есть люди, нуждающиеся в помощи, сострадании и понимании, всегда есть враждебные твари, которых необходимо уничтожать во благо людей." }, { 24.00, "Докажи, что ты можешь помогать своим ближним – в особенности тем, кому меньше повезло в жизни." }, { 30.91, "Тем самым ты докажешь, что твои помыслы чисты и что ты воистину служишь Свету." } } } } },
    [1643] = { d = 29.8, v = "human-male", n = { x = 334 }, c = { x = { { 0.00, "Итак, твоя задача – найти в Штормграде того, кто нуждается в помощи." }, { 4.88, "Того, кто чист сердцем и помыслами." }, { 7.35, "Возможно, это тот, кто сам помогает другим." }, { 10.39, "Возможно – тот, кто нуждается в наставнике." }, { 13.37, "Как бы то ни было, намерения того, кого ты ищешь, будут благородны, и он во всём будет полагаться на тебя." }, { 20.78, "Ты возвратишься ко мне, когда исполнишь это задание, и мы поговорим о твоём пути – а равно и о том, что значит быть паладином Света." } } }, t = { d = 31.7, g = 1, v = "human-female", n = { m = 341, f = 341 }, c = { m = { { 0.00, "О, привет, дорогой." }, { 1.44, "Что, всё ищешь приключений?" }, { 3.41, "Я так рада, что у тебя всё в порядке!" }, { 6.09, "Я?" }, { 6.29, "А что я?" }, { 6.88, "Ну, с учётом обстоятельств, у меня тоже дела идут неплохо..." }, { 11.26, "Правда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать?" }, { 20.89, "Но ничего, мы справимся." }, { 22.66, "Под \"нами\" я имею в виду себя и своего мужа, конечно." }, { 26.65, "Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей..." } }, f = { { 0.00, "О, привет, милашка." }, { 1.43, "Что, всё ищешь приключений?" }, { 3.37, "Я так рада, что у тебя всё в порядке!" }, { 6.03, "Я?" }, { 6.22, "А что я?" }, { 6.81, "Ну, с учётом обстоятельств, у меня тоже дела идут неплохо..." }, { 11.15, "Правда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать?" }, { 20.68, "Но ничего, мы справимся." }, { 22.43, "Под \"нами\" я имею в виду себя и своего мужа, конечно." }, { 26.38, "Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей..." } } } } },
    [1644] = { d = 30.2, v = "human-female", n = { x = 336 }, c = { x = { { 0.00, "Да будут благословенны эти несчастные!" }, { 2.82, "Многие из них потеряли родных во время набегов нежити..." }, { 6.94, "Мой муж Джон помогает мне доставать ткань, чтобы я могла шить сироткам одежду, но увы, на это у меня не хватает времени, ведь их нужно сначала накормить и дать им кров." }, { 18.93, "Что?" }, { 19.25, "Правда?" }, { 19.84, "Ты хочешь мне помочь?" }, { 21.41, "Благодарение Вечному Свету!" }, { 23.44, "Благодарю тебя!" }, { 24.62, "Если бы у меня был лён на одёжки малышам, их жизнь стала бы хоть немного легче..." } } }, t = { d = 21.0, v = "human-female", n = { x = 227 }, c = { x = { { 0.00, "Ах, благодарю, благодарю тебя!" }, { 2.32, "Детишки так рады будут, да и у меня будет побольше времени на них." }, { 7.38, "Надеюсь, теперь Джон сможет возвратиться поскорее." }, { 11.20, "Прими мою искреннюю признательность." }, { 14.00, "Я всегда верила, что в сердцах людей есть место милосердию." }, { 18.51, "Да пребудет с тобой Извечный Свет." } } } } },
    [1645] = { t = { d = 31.0, v = "dwarf-female#33", n = { x = 323 }, c = { x = { { 0.00, "Рада знакомству." }, { 1.33, "Я наставляю паладинов на путь высшей добродетели — тех, кто посвящает себя Свету и защищает Азерот от Плети и прочих угроз." }, { 10.89, "Пришло время и тебе сделать первый шаг к истинной добродетели." }, { 15.80, "Если ты согласишься, я дам тебе Книгу Божественности." }, { 19.94, "Изучая её, ты кое-что узнаешь о Свете и о том, чего от тебя ждут." }, { 25.00, "Если ты постигнешь её и тебе хватит сил, то обретёшь более могучие способности." } } } } },
    [1646] = { d = 40.3, v = "narrator", n = { x = 407 }, c = { x = { { 0.00, "Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы." }, { 7.62, "Стремление к божественности для нас не означает стремления стать божеством – мы стремимся к добру во всех деяниях наших." }, { 17.24, "Хотя в эти тяжёлые времена мы призваны сокрушать зло, тебе всегда следует помнить: лишь помогая другим, ты выделяешься среди других обитателей Азерота." }, { 29.67, "Сочувствие, терпение, отвага – все эти достоинства значат для паладина не меньше, чем сила в сражении." }, { 38.03, "Усвой же это и помни всегда." } } }, t = { d = 31.3, g = 1, v = "dwarf-female#33", n = { m = 322, f = 323 }, c = { m = { { 0.00, "С возвращением." }, { 1.20, "Надеюсь, ты нашёл время на прочтение книги?" }, { 4.57, "Тогда ты должен быть готов к испытанию." }, { 7.67, "Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить." }, { 21.95, "Доказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света." } }, f = { { 0.00, "С возвращением." }, { 1.21, "Надеюсь, ты нашла время на прочтение книги?" }, { 4.69, "Тогда ты должна быть готова к испытанию." }, { 7.89, "Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить." }, { 22.33, "Доказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света." } } } } },
    [1647] = { d = 34.3, v = "dwarf-female#33", n = { x = 388 }, c = { x = { { 0.00, "Твоя задача, найти в Стальгорне кого-нибудь, кто нуждается в помощи." }, { 4.93, "Того, кто чист душой и помыслами." }, { 7.33, "Может быть, того, кто сам помогает другим." }, { 10.38, "Того, кто нуждается в совете." }, { 12.53, "Кто бы то ни был, у него должны быть благородные стремления и он должен полагаться на твою доброту." }, { 19.54, "Сделай это и по выполнении возвращайся ко мне." }, { 22.85, "Тогда мы ещё поговорим о твоём пути и о том, что значит быть паладином Света." }, { 28.30, "Я останусь в храме до твоего возвращения." }, { 31.28, "Моё наставничество нужно и другим паладинам." } } }, t = { d = 22.2, g = 1, v = "human-male", n = { m = 232, f = 234 }, c = { m = { { 0.00, "Сиротский приют Шторм... о, простите, я вовсе не хотел кричать на вас, сударь." }, { 5.87, "Меня зовут Джон Тернер." }, { 7.71, "Как поживаете?" }, { 8.81, "Рад, искренне рад слышать, что у вас всё хорошо." }, { 12.35, "А у меня был трудный день, я тоскую по жене, но такова цена, которую приходится платить, чтобы накормить голодные рты и одеть нагих." } }, f = { { 0.00, "Сиротский приют Шторм... о, простите, я вовсе не хотел кричать на вас, сударыня." }, { 5.97, "Меня зовут Джон Тернер." }, { 7.80, "Как поживаете?" }, { 8.89, "Рад, искренне рад слышать, что у вас всё хорошо." }, { 12.42, "А у меня был трудный день, я тоскую по жене, но такова цена, которую приходится платить, чтобы накормить голодные рты и одеть нагих." } } } } },
    [1648] = { d = 29.2, v = "human-male", n = { x = 380 }, c = { x = { { 0.00, "Мы с женой держим в Штормграде сиротский приют, по большей части для детей, потерявших родителей во время нападений Плети в последние десять лет." }, { 9.30, "Я приезжаю в Стальгорн примерно раз в месяц и занимаюсь сбором средств у здешних горожан, а также прошу помощи у различных организаций." }, { 17.90, "Нынешняя поездка была мучительно медленной и не слишком продуктивной." }, { 22.35, "Если бы мне удалось добыть ещё немного льняной ткани для одежды, я бы смог, наконец, отправить посылку домой." } } }, t = { d = 28.3, v = "human-male", n = { x = 313 }, c = { x = { { 0.00, "Это так прекрасно с вашей стороны." }, { 2.54, "Снова большое вам спасибо." }, { 4.50, "Вы благородный человек, что так помогли мне." }, { 7.63, "Неудивительно, что вы избрали путь Света." }, { 10.57, "Хотел бы я, чтобы был какой-либо способ отплатить вам за всё, что вы сделали... что?" }, { 16.51, "Это наименьшее что вы могли сделать?" }, { 19.18, "Видите?" }, { 19.77, "Это как раз то, о чём я говорю, вы благородны до самого конца." }, { 24.21, "Берегите себя, и да охранит вас Свет в ваших путешествиях." } } } } },
    [1649] = { d = 37.5, v = "narrator", n = { x = 383 }, c = { x = { { 0.00, "Отвага и сопутствующие ей достоинства подобны драгоценным металлам." }, { 5.45, "Нужно беречь их, когда находишь, ибо цена их велика, но также необходимо копить и приумножать их." }, { 13.47, "Тогда они образуют крепчайший сплав, зачастую выдерживающий даже самые сильные удары." }, { 20.53, "Твои сила, вера и храбрость должны быть испытаны." }, { 24.65, "Тебе надлежит научиться хранить веру в любых обстоятельствах и понять, что с помощью сил Света ты сможешь преодолеть те препятствия, которые не по силам другим." } } }, t = { d = 28.6, v = "human-male", n = { x = 342 }, c = { x = { { 0.00, "Ты просишь испытать твою отвагу?" }, { 2.32, "Прекрасно!" }, { 3.07, "Для тебя в городе и в окрестностях найдётся немало заданий." }, { 7.13, "Нам как раз нужен кто-нибудь с твоими способностями." }, { 10.70, "Это испытание не будет лёгким!" }, { 12.83, "Оно, как и многое в нашей профессии, может привести к гибели." }, { 17.14, "Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли паладин служить правому делу." }, { 25.53, "Чувствуешь ли ты в себе готовность к испытанию?" } } } } },
    [1650] = { d = 32.4, v = "human-male", n = { x = 377 }, c = { x = { { 0.00, "Отлично!" }, { 0.64, "Отсутствие сомнений говорит о твоей готовности к испытаниям." }, { 4.92, "Да будет так!" }, { 5.88, "В самом конце Долгого Берега стоит небольшой домик с окнами на океан." }, { 10.93, "Там живёт чета Стилвеллов." }, { 12.79, "Джордан – великолепный кузнец, и сейчас он собирается в Стальгорн, чтобы навестить дворфов." }, { 19.31, "Но его жена Дафна остаётся дома одна, без защиты..." }, { 23.02, "Донесения говорят, что Братство Справедливости захватило почти весь край." }, { 28.13, "Дафне может понадобиться защита от злодеев." }, { 31.27, "Отправляйся туда." } } }, t = { d = 29.8, v = "human-female#45", n = { x = 345 }, c = { x = { { 0.00, "Здравствуй." }, { 0.81, "Я полагаю, что со всем этим оружием в руках ты хочешь либо захватить мои земли, либо Церковь наконец-то послала мне защитника на время поездки Джордана." }, { 11.47, "Позволь представиться: я – Дафна Стилвелл." }, { 14.42, "Очень приятно!" }, { 15.48, "Твоё прибытие очень кстати: с восхода солнца я уже прикончила с полдюжины этих мерзавцев." }, { 21.75, "До этого они не особо торопились, но сейчас они наверняка заметили тебя, а значит, будут здесь с минуты на минуту..." } } } } },
    [1651] = { d = 22.6, v = "human-female#45", n = { x = 248 }, c = { x = { { 0.00, "Бьюсь об заклад, они скоро вернутся – так что приготовься." }, { 4.17, "В доме есть пистолет, я возьму его и при необходимости помогу тебе, но лучше рассчитывай только на свои силы." }, { 12.11, "Не знаю, сколько их будет, но уверена, что больше, чем в прошлый раз." }, { 17.06, "Моли Свет благословить тебя, потому что…" }, { 19.99, "Слышишь?" }, { 20.64, "Они идут!" }, { 21.42, "Укроемся за домом!" } } }, t = { d = 15.0, v = "human-female#45", n = { x = 179 }, c = { x = { { 0.00, "Мы победили!" }, { 0.87, "Благодарю тебя за помощь." }, { 2.67, "Это было просто великолепно!" }, { 4.72, "Я и не думала, что паладин может справиться с таким количеством врагов зараз." }, { 10.07, "Твоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня..." } } } } },
    [1652] = { d = 17.4, v = "human-female#45", n = { x = 194 }, c = { x = { { 0.00, "Прошу, возвращайся к Даториану и передай ему, что теперь со мной всё в порядке – благодаря тебе и Церкви." }, { 7.55, "Он пошлёт весть в Стальгорн, чтобы мой Джордан не волновался за меня." }, { 12.43, "Ох, как я соскучилась по своему мужу!" }, { 15.10, "Жду не дождусь его возвращения..." } } }, t = { d = 22.6, v = "human-male", n = { x = 265 }, c = { x = { { 0.00, "Вот мы и встретились снова." }, { 1.88, "Я вижу, что дух твой бодр." }, { 3.63, "Дом четы Стилвеллов теперь в безопасности, а из твоего рассказа ясно, что ему теперь ещё долго ничего не будет угрожать." }, { 12.01, "Отлично!" }, { 12.63, "Дафна и Джордан немало помогли Церкви." }, { 15.39, "Отправить тебя на их защиту – весьма скромная ответная услуга." }, { 19.76, "Ты получишь награду за проявленную отвагу." } } } } },
    [1653] = { d = 31.0, v = "human-male", n = { x = 399 }, c = { x = { { 0.00, "Вообще я не сомневаюсь, что Джордан захочет лично отблагодарить тебя, и раз уж мне надо сообщить ему, что его жена в безопасности, то, думаю, лучше всего тебя посланником и отправить." }, { 11.68, "Джордан был паладином Света, до того как приверженность отцовскому ремеслу увлекла его на другой путь, – а потому он хорошо знает наш образ жизни и считается одним из самых надёжных наших приверженцев." }, { 24.45, "Он должен ещё быть в Стальгорне – он любит работать днём за воротами, там где с гор тянет холодным воздухом." } } }, t = { d = 37.8, v = "human-male", n = { x = 412 }, c = { x = { { 0.00, "Добрый день." }, { 0.92, "Вижу, ты служишь Свету?" }, { 2.69, "Что это?" }, { 3.35, "Тебя послал Даториан?!" }, { 5.06, "Моя жена, как она?" }, { 6.51, "Я так и знал – стоит уехать, сразу беды нагрянут." }, { 10.12, "Скажи мне, она... о, хвала Свету." }, { 12.62, "Я так счастлив, что она в безопасности." }, { 15.44, "Это Братство Справедливости было опасным ещё до нынешних своих налётов, но теперь уж королевские советники не смогут этой угрозы отрицать." }, { 25.50, "Что ещё велел передать Даториан?" }, { 27.86, "Именно ты и назначен был оберегать мою жену?" }, { 31.15, "Тогда ещё раз прими мою благодарность." }, { 33.98, "Не могу придумать лучшего испытания доблести, чем это." } } } } },
    [1654] = { d = 34.2, g = 1, v = "human-male", n = { x = 399 }, c = { m = { { 0.00, "Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар." }, { 4.70, "Пойми меня правильно, всё будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода." }, { 14.89, "Я скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света." }, { 22.49, "Но тебе придётся добыть необходимые для ковки предметы." }, { 26.26, "Я уже набросал список, так что остаётся только, чтобы некто отважный и искусный принёс их мне." }, { 32.62, "Что скажешь, герой?" } }, f = { { 0.00, "Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар." }, { 4.72, "Пойми меня правильно, всё будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода." }, { 14.98, "Я скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света." }, { 22.62, "Но тебе придётся добыть необходимые для ковки предметы." }, { 26.41, "Я уже набросал список, так что остаётся только, чтобы некто отважный и искусный принёс их мне." }, { 32.81, "Что скажешь, героиня?" } } }, t = { d = 23.8, g = 1, v = "human-male", n = { m = 275, f = 276 }, c = { m = { { 0.00, "Великолепно!" }, { 0.88, "Ты добыл всё необходимое." }, { 2.65, "Теперь я легко изготовлю для тебя великолепное оружие!" }, { 6.51, "Я и так собирался когда-нибудь его выковать, просто не было возможности достать всё необходимое." }, { 13.21, "Спасибо тебе." }, { 14.22, "Как же приятно снова держать в руке молот моих отцов... и самоцвет Кора – я и не думал, что когда-нибудь увижу его собственными глазами!" } }, f = { { 0.00, "Великолепно!" }, { 0.89, "Ты добыла всё необходимое." }, { 2.72, "Теперь я легко изготовлю для тебя великолепное оружие!" }, { 6.58, "Я и так собирался когда-нибудь его выковать, просто не было возможности достать всё необходимое." }, { 13.28, "Спасибо тебе." }, { 14.29, "Как же приятно снова держать в руке молот моих отцов... и самоцвет Кора – я и не думал, что когда-нибудь увижу его собственными глазами!" } } } } },
    [1655] = { d = 32.2, g = 1, v = "dwarf-male", n = { m = 333, f = 335 }, c = { m = { { 0.00, "Ох, и испугал ты меня, парень!" }, { 2.28, "Не видишь, что я в размышлениях?" }, { 4.62, "Это что ещё?" }, { 5.56, "Поставка Джордану..." }, { 7.10, "Стальгорн." }, { 7.90, "А, да, я понял, о чём речь." }, { 9.85, "Мо'грошские огры ограбили меня, и нет у меня руды для старого друга." }, { 15.00, "Караван шёл сюда из Болотины и попал в засаду." }, { 18.48, "Охранник, что уцелел, помер пару дней назад – целитель не поспел вовремя." }, { 23.98, "Если хочешь найти эту партию руды, то придётся тебе двинуться на северо-восток, за озеро Лок." }, { 30.94, "Она где-то там." } }, f = { { 0.00, "Ох, и испугала ты меня, дамочка!" }, { 2.42, "Не видишь, что я в размышлениях?" }, { 4.77, "Это что ещё?" }, { 5.71, "Поставка Джордану..." }, { 7.26, "Стальгорн." }, { 8.06, "А, да, я понял, о чём речь." }, { 10.01, "Мо'грошские огры ограбили меня, и нет у меня руды для старого друга." }, { 15.19, "Караван шёл сюда из Болотины и попал в засаду." }, { 18.68, "Охранник, что уцелел, помер пару дней назад – целитель не поспел вовремя." }, { 24.19, "Если хочешь найти эту партию руды, то придётся тебе двинуться на северо-восток, за озеро Лок." }, { 31.18, "Она где-то там." } } }, t = { d = 24.5, g = 1, v = "dwarf-male", n = { x = 248 }, c = { m = { { 0.00, "Ну-ну, надо же!" }, { 1.21, "Знал бы я, что ты и правда прямо туда и пойдёшь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести." }, { 10.16, "Но ведь ты тут не за тем, чтобы за меня работу делать, верно?" }, { 14.67, "А сделка есть сделка." }, { 16.28, "Джордан хотел получить свою руду, и он её получит." }, { 20.12, "Передай ему приветик от меня, и доброй тебе дороги, герой." } }, f = { { 0.00, "Ну-ну, надо же!" }, { 1.18, "Знал бы я, что ты и правда прямо туда и пойдёшь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести." }, { 9.91, "Но ведь ты тут не за тем, чтобы за меня работу делать, верно?" }