    [1656] = { d = 30.3, v = "tauren-female#72", n = { x = 318 }, c = { x = { { 0.00, "Умоляю, помоги мне!" }, { 1.49, "У меня ещё есть дело здесь, на плато - я прохожу обряд Силы, - а мой отец требует, чтобы я срочно доставила эти меха в таверну в деревне Кровавого Копыта!" }, { 13.11, "Как же мне выполнить сразу обе задачи - завершить ритуал и отнести меха?!" }, { 18.65, "Не отнесёшь ли ты их вместо меня?" }, { 21.08, "Таверна - такое милое и уютное местечко, там есть всё, чего может пожелать притомившийся путник." }, { 28.31, "Даю слово, тебе понравится!" } } }, t = { d = 29.6, v = "tauren-male#132", n = { x = 258 }, c = { x = { { 0.00, "О, а вот и мои меха!" }, { 1.93, "Благодарю вас." }, { 3.27, "Вы доставили их даже быстрее, чем я ожидал." }, { 7.29, "Они послужат отличными одеялами для моих постояльцев." }, { 12.32, "Прошу вас, гостите в таверне, сколько пожелаете." }, { 16.85, "Наши двери всегда открыты, и мы рады каждому." }, { 21.21, "Не стоит недооценивать значение полноценного отдыха - особенно если впереди дальняя дорога." } } } } },
    [1657] = { d = 31.5, v = "scourge-female#79", n = { x = 336 }, c = { x = { { 0.00, "Сделайте ваш праздник Тыквовина незабываемым... насолив нашим врагам на Южнобережье!" }, { 6.60, "Возьмите специально собранную бомбу-вонючку – она наполнена невероятно зловонным веществом, запах которого не вынесет ни одно тупое животное, включая людей." }, { 19.03, "Вам нужно будет бросить её в самый центр Южнобережья, так что готовьтесь к драке с Альянсом!" }, { 26.20, "А когда сделаете этот шаг к нашему освобождению, возвращайтесь ко мне!" } } }, t = { d = 25.0, g = 1, v = "scourge-female#79", n = { m = 240, f = 241 }, c = { m = { { 0.00, "А, отлично сработано!" }, { 1.86, "Надеюсь, Альянс задохнётся от нашего зловонного подарка – так же, как мы задыхались под ярмом рабства у Плети!" }, { 11.13, "Ты остался верен духу Тыквовина, и за это я тебя приветствую." }, { 16.46, "А в награду позволь поделиться с тобой праздничными сладостями Тыквовина." }, { 22.72, "Думаю, они тебе понравятся!" } }, f = { { 0.00, "А, отлично сработано!" }, { 1.85, "Надеюсь, Альянс задохнётся от нашего зловонного подарка – так же, как мы задыхались под ярмом рабства у Плети!" }, { 11.10, "Ты осталась верна духу Тыквовина, и за это я тебя приветствую." }, { 16.49, "А в награду позволь поделиться с тобой праздничными сладостями Тыквовина." }, { 22.73, "Думаю, они тебе понравятся!" } } } } },
    [1658] = { d = 29.0, v = "human-male#50", n = { x = 348 }, c = { x = { { 0.00, "Мне нужны храбрецы, готовые отправиться в Тирисфальские луга на фестиваль Плетёного человека." }, { 6.34, "Не скрою, это очень опасно." }, { 8.33, "Стража на фестивале будет особенно бдительна и свирепа." }, { 12.19, "И всё же надо выяснить, велик ли в этом году фестиваль, и сколько бед Отрёкшиеся причинят нам во время Тыквовина." }, { 19.90, "Если тебе хватит пороху, ступай в Тирисфаль и разведай, что да как." }, { 24.64, "Я прослежу, чтобы тебе хорошо заплатили за принесённую информацию." } } }, t = { d = 28.1, v = "human-male#50", n = { x = 339 }, c = { x = { { 0.00, "Отличная работа." }, { 1.19, "Фестиваль Плетёного человека так и будет доставлять хлопоты, пока мерзким Отрёкшимся позволено бродить по руинам Лордерона." }, { 9.68, "И это вовсе НЕ достойная дань памяти некогда гордому королевству, уж поверь мне..." }, { 15.40, "Вот тебе немного монет на починку снаряжения, а в честь праздника я положил ещё и сладостей." }, { 21.75, "Счастливого Тыквовина – постараемся, чтобы здесь, в Южнобережье, он прошёл как можно спокойнее." } } } } },
    [1661] = { d = 26.5, g = 1, v = "human-male", n = { m = 287, f = 288 }, c = { m = { { 0.00, "Приветствую тебя!" }, { 1.31, "Я несказанно рад тому, что могу называть тебя Братом: твоё посвящение – радость для всех нас." }, { 8.02, "Пришло время вручить тебе великий дар." }, { 10.91, "Но знай: сейчас я даю его тебе, не требуя ничего взамен; но потом настанет час, когда всем паладинам придётся немало потрудиться для того, чтобы получить его." }, { 22.48, "Приходи в любое время – я отдам тебе твой подарок." } }, f = { { 0.00, "Приветствую тебя!" }, { 1.33, "Я несказанно рад тому, что могу называть тебя Сестрой: твоё посвящение – радость для всех нас." }, { 8.19, "Пришло время вручить тебе великий дар." }, { 11.12, "Но знай: сейчас я даю его тебе, не требуя ничего взамен; но потом настанет час, когда всем паладинам придётся немало потрудиться для того, чтобы получить его." }, { 22.83, "Приходи в любое время – я отдам тебе твой подарок." } } }, t = { d = 3.4, v = "human-male", n = { x = 30 }, c = { x = { { 0.00, "Поздравляю!" }, { 1.09, "Да пребудет с тобой Свет!" } } } } },
    [1665] = { d = 6.6, v = "human-male#50", n = { x = 48 }, c = { x = { { 0.00, "Ладно, бери мою кружку." }, { 2.41, "Стой!" }, { 2.93, "Дай-ка я хотя бы допью..." }, { 5.43, "Ну вот." }, { 6.12, "Бери." } } }, t = { d = 9.2, v = "human-male", n = { x = 90 }, c = { x = { { 0.00, "А вот и кружка!" }, { 1.24, "Да уж, он не хотел с ней расставаться, но ты умеешь настоять на своём." }, { 6.72, "Молодец." }, { 7.45, "Приступим к обучению..." } } } } },
    [1666] = { d = 23.4, g = 1, v = "human-male", n = { m = 275, f = 276 }, c = { m = { { 0.00, "Ты освоил несколько новых приёмов, но без хорошего оружия тебе не обойтись." }, { 5.08, "Думаю, тебе мог бы помочь маршал Хаггард." }, { 7.95, "Он живёт в своём поместье в Элвиннском лесу, возле лесопилки Восточной долины." }, { 13.21, "Он ушёл в отставку, но за время службы собрал недурную коллекцию оружия." }, { 18.11, "Скажи, что тебя прислал я, и если повезёт, он поделится лишним оружием." } }, f = { { 0.00, "Ты освоила несколько новых приёмов, но без хорошего оружия тебе не обойтись." }, { 5.27, "Думаю, тебе мог бы помочь маршал Хаггард." }, { 8.22, "Он живёт в своём поместье в Элвиннском лесу, возле лесопилки Восточной долины." }, { 13.61, "Он ушёл в отставку, но за время службы собрал недурную коллекцию оружия." }, { 18.63, "Скажи, что тебя прислал я, и если повезёт, он поделится лишним оружием." } } }, t = { d = 9.4, g = 1, v = "human-male", n = { m = 86, f = 87 }, c = { m = { { 0.00, "Кто это?" }, { 0.75, "Берлгард, это ты?" }, { 2.25, "Подойди поближе." }, { 3.67, "Глаза у меня уже не те." }, { 5.69, "Ты так подкрался, что я принял тебя за гнолла!" } }, f = { { 0.00, "Кто это?" }, { 0.74, "Берлгард, это ты?" }, { 2.23, "Подойди поближе." }, { 3.64, "Глаза у меня уже не те." }, { 5.65, "Ты так подкралась, что я принял тебя за гнолла!" } } } } },
    [1667] = { d = 35.2, v = "human-male", n = { x = 396 }, c = { x = { { 0.00, "Тебя ведь прислал Берлгард?" }, { 1.99, "Да, у меня есть запасное оружие, но сначала я хочу дать тебе задание…" }, { 6.93, "Некоторое время назад меня обманул злодей из Братства Справедливости, Джек Мертвозуб." }, { 13.02, "Он пришёл в темноте, одетый в гербовую накидку Штормграда, и я принял его за маршала Дугхана." }, { 19.63, "Джек сказал, что ему нужен мой старый знак маршала, и я, не раздумывая, отдал его... а потом он захохотал и сбежал, прежде, чем я успел его схватить!" }, { 30.21, "Верни мне мой знак!" }, { 31.56, "Джек Мертвозуб наверняка прячет его в лагере на юге." } } }, t = { d = 22.6, v = "human-male", n = { x = 282 }, c = { x = { { 0.00, "Ура, мой знак у тебя!" }, { 1.44, "Я боялся, что лишился его навсегда, а шваль из Братства Справедливости получила возможность изображать из себя представителей власти." }, { 10.19, "Тебе же удалось предотвратить невиданный разгул преступности." }, { 14.27, "Вот моё оружие, которое лежит без дела с тех времён, как я был маршалом." }, { 18.94, "Я его регулярно чистил, и оно в отличной форме, выбирай!" } } } } },
    [1678] = { d = 24.6, g = 1, v = "dwarf-male", n = { m = 272, f = 273 }, c = { m = { { 0.00, "Хорошему воину пристало быть стойким." }, { 2.75, "Я научу тебя новым приёмам, но прежде докажи, что сможешь справиться с серьёзными противниками." }, { 9.58, "Веджрек – один из самых сильных троллей в наших краях." }, { 13.64, "Ему-то ты и бросишь вызов." }, { 15.61, "Он живёт в хижине в предгорьях, чуть южнее форта Мерзлогривов." }, { 20.07, "Принеси мне голову Веджрека, и я поверю, что ты не лыком шит." } }, f = { { 0.00, "Хорошему воину пристало быть стойким." }, { 2.78, "Я научу тебя новым приёмам, но прежде докажи, что сможешь справиться с серьёзными противниками." }, { 9.65, "Веджрек – один из самых сильных троллей в наших краях." }, { 13.75, "Ему-то ты и бросишь вызов." }, { 15.73, "Он живёт в хижине в предгорьях, чуть южнее форта Мерзлогривов." }, { 20.23, "Принеси мне голову Веджрека, и я поверю, что ты не лыком шита." } } }, t = { d = 21.5, g = 1, v = "dwarf-male", n = { m = 205, f = 206 }, c = { m = { { 0.00, "Ну и урод же был этот Веджрек, а?" }, { 2.57, "Отличная работа!" }, { 3.88, "У тебя есть всё, что нужно." }, { 5.96, "А теперь начнём твой урок..." }, { 8.11, "Ты, может, и не знал, но крепкая защита — жизненно важна для героя." }, { 13.25, "Она позволяет ему стоять на ногах там, где другие пали бы, — а именно этого и ждут от тебя твои союзники." } }, f = { { 0.00, "Ну и урод же был этот Веджрек, а?" }, { 2.56, "Отличная работа!" }, { 3.88, "У тебя есть всё, что нужно." }, { 5.95, "А теперь начнём твой урок..." }, { 8.10, "Ты, может, и не знала, но крепкая защита — жизненно важна для героини." }, { 13.50, "Она позволяет ему стоять на ногах там, где другие пали бы, — а именно этого и ждут от тебя твои союзники." } } } } },
