    [1680] = { d = 13.0, g = 1, v = "dwarf-male", n = { m = 147, f = 148 }, c = { m = { { 0.00, "Ты уже освоил несколько приёмов, пора заняться твоим оружием." }, { 4.55, "Поговори с Тормусом Подземной Кузней." }, { 7.32, "Он скуёт тебе оружие по вкусу." }, { 9.56, "Тормус живёт здесь, в Стальгорне, в Великой Кузне." } }, f = { { 0.00, "Ты уже освоила несколько приёмов, пора заняться твоим оружием." }, { 4.54, "Поговори с Тормусом Подземной Кузней." }, { 7.26, "Он скуёт тебе оружие по вкусу." }, { 9.46, "Тормус живёт здесь, в Стальгорне, в Великой Кузне." } } }, t = { d = 15.4, v = "dwarf-male", n = { x = 150 }, c = { x = { { 0.00, "Тебя прислал Марен?" }, { 1.68, "Да, я могу сковать тебе превосходное оружие..." }, { 5.49, "Но услуга за услугу." }, { 7.17, "Не бойся." }, { 7.98, "Конечно, задание будет опасным, ты можешь погибнуть, но разве не к этому стремятся все воины?" } } } } },
    [1681] = { d = 34.0, v = "dwarf-male", n = { x = 365 }, c = { x = { { 0.00, "У моего наставника, Стурги Сталекрута, была мастерская на юге от озера Хельмово Ложе в восточной части Дун Морога." }, { 8.81, "Он был лучшим учителем кузнечного дела." }, { 11.84, "Но однажды ученики принесли ему странную руду." }, { 15.49, "Мастер Сталекрут назвал её мрачной рудой и с радостью с ней работал, но увы, вскоре на них напал отряд дворфов Чёрного Железа." }, { 25.13, "Они поубивали всех!" }, { 26.64, "Ступай в мастерскую Сталекрута, и отомсти за смерть моего учителя." }, { 31.67, "И принеси мне груз мрачной руды." } } }, t = { d = 18.4, g = 1, v = "dwarf-male", n = { m = 197, f = 198 }, c = { m = { { 0.00, "Ты нашёл её!" }, { 0.90, "Молодец!" }, { 1.59, "Надеюсь, что в ходе поисков ты убил целую толпу дворфов Чёрного Железа." }, { 7.10, "Боюсь, нам придётся столкнуться с ними не только в мастерской Сталекрута." }, { 12.62, "Впрочем, спасибо за руду." }, { 14.62, "Я с радостью поработаю с ней и исследую её свойства." } }, f = { { 0.00, "Ты нашла её!" }, { 0.95, "Молодец!" }, { 1.64, "Надеюсь, что в ходе поисков ты убила целую толпу дворфов Чёрного Железа." }, { 7.16, "Боюсь, нам придётся столкнуться с ними не только в мастерской Сталекрута." }, { 12.61, "Впрочем, спасибо за руду." }, { 14.58, "Я с радостью поработаю с ней и исследую её свойства." } } } } },
    [1682] = { t = { d = 9.0, g = 1, v = "dwarf-male", n = { m = 88, f = 90 }, c = { m = { { 0.00, "Вот оружие, прямо с наковальни, выкованное из новой мрачной руды, которую ты мне принёс!" }, { 7.30, "Пожалуйста, выбирай!" } }, f = { { 0.00, "Вот оружие, прямо с наковальни, выкованное из новой мрачной руды, которую ты мне принесла!" }, { 7.48, "Пожалуйста, выбирай!" } } } } },
    [1683] = { d = 29.2, v = "nightelf-female#52", n = { x = 332 }, c = { x = { { 0.00, "Прежде чем браться за твоё обучение, я хочу испытать твою храбрость." }, { 4.86, "Сатир Ворлус Подлое Копыто обнаружил один из наших лунных колодцев, тот, что на юго-востоке от обители Бен'этиль." }, { 12.98, "Он плещется в его светлых водах, оскверняя их своим присутствием." }, { 17.64, "Отыщи Ворлуса и убей его." }, { 19.56, "В доказательство принеси мне его рог, и я возьмусь учить тебя." }, { 23.97, "Отыскать дорогу к колодцу очень трудно, но тот, кто ищет, тот всегда найдёт." } } }, t = { d = 13.6, v = "nightelf-female#52", n = { x = 157 }, c = { x = { { 0.00, "Спасибо тебе." }, { 1.02, "Приятно знать, что Ворлус мёртв, а наш колодец снова чист, и не менее приятно видеть молодых воинов, которые хотят очистить наш любимый Тельдрассил от порчи." }, { 12.08, "Приступим к обучению..." } } } } },
    [1684] = { d = 13.9, v = "nightelf-female#51", n = { x = 144 }, c = { x = { { 0.00, "Приветствую тебя, воин." }, { 1.90, "Ты растёшь над собой, но профессия воина не так проста, как кажется." }, { 7.11, "Тебе нужен хороший учитель." }, { 9.36, "В Дарнассе, на террасе Воинов, живёт Эланария." }, { 12.94, "Поучись у неё." } } }, t = { d = 10.1, v = "nightelf-female#52", n = { x = 114 }, c = { x = { { 0.00, "Приветствую тебя." }, { 1.29, "В Дарнассе говорят, что ты подаёшь надежды." }, { 4.34, "Впрочем, скоро мы узнаем, хватит ли тебе силы воли, чтобы следовать путём воина." } } } } },
    [1685] = { d = 28.8, v = "human-male#50", n = { x = 335 }, c = { x = { { 0.00, "И вот так всегда." }, { 1.17, "Я разыскивал тебя весь день, но так и не смог найти; а сейчас, когда я вовсе этого не ожидал, ты появляешься как из-под земли." }, { 9.65, "Я уже и так слишком много времени потратил на твои поиски, так что буду краток." }, { 15.12, "Наставник Гакин призывает тебя для дополнительных занятий – и, думаю, тебе стоит поторопиться." }, { 21.57, "Ты найдёшь его в подвале таверны \"Забитый ягнёнок\"." }, { 25.01, "К слову сказать, не стоит много болтать об этом месте..." } } }, t = { d = 17.8, v = "human-male#50", n = { x = 209 }, c = { x = { { 0.00, "Наконец-то ты здесь." }, { 1.37, "Мне следовало послать за тобой кого-нибудь более расторопного, чем Ремен." }, { 6.42, "Ну, неважно." }, { 7.30, "Когда у тебя было последнее занятие?" }, { 9.92, "Слишком давно, слишком..." }, { 11.73, "А ты знаешь, что у плохо обученного чернокнижника мало шансов сохранить голову на плечах?" } } } } },
    [1686] = { d = 36.3, g = 1, v = "nightelf-female#52", n = { m = 423, f = 424 }, c = { m = { { 0.00, "Ты многому научился." }, { 1.44, "Пора создать для тебя настоящее оружие." }, { 4.25, "Оружие воина." }, { 5.25, "Тебе придётся отправиться за ним на Тёмный берег." }, { 8.56, "Давным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой." }, { 17.92, "Для начала тебе придётся одержать верх над стражем элунита, тенью Элуры." }, { 22.92, "Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза." }, { 31.10, "Победи её, забери у неё медальон и собери со дна ящики с элунитом." } }, f = { { 0.00, "Ты многому научилась." }, { 1.53, "Пора создать для тебя настоящее оружие." }, { 4.40, "Оружие воина." }, { 5.42, "Тебе придётся отправиться за ним на Тёмный берег." }, { 8.80, "Давным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой." }, { 18.36, "Для начала тебе придётся одержать верх над стражем элунита, тенью Элуры." }, { 23.46, "Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза." }, { 31.81, "Победи её, забери у неё медальон и собери со дна ящики с элунитом." } } }, t = { d = 9.2, v = "nightelf-female#52", n = { x = 94 }, c = { x = { { 0.00, "Да, отваги тебе не занимать." }, { 2.30, "Тень Элуры наконец-то обрела покой, а из добытого элунита тебе скуют прекрасное оружие." } } } } },
    [1687] = { d = 26.2, v = "child-male", n = { x = 307 }, c = { x = { { 0.00, "Попечительницы сирот рассказывают нам сказки на ночь." }, { 3.70, "Иногда даже про привидений." }, { 5.67, "Это особенно КРУТО!" }, { 7.14, "Мне запомнилась история про призрак, живущий в маяке Западного Края." }, { 11.98, "Говорят, он был капитаном пиратского корабля, но корабль захватили другие пираты." }, { 17.72, "Правда, интересно?" }, { 19.05, "Отведи меня к этому маяку!" }, { 21.03, "Я хочу посмотреть на призрак капитана!" }, { 23.77, "Обещаю не отходить от тебя ни на шаг!" } } }, t = { d = 24.6, g = 1, v = "child-male", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Надо же, настоящий призрак!" }, { 2.14, "Потрясающе – мне не терпится рассказать ребятам из приюта." }, { 6.57, "Капитан Грейсон..." }, { 8.02, "И выглядел точно как пират!" }, { 10.16, "Когда я вырасту, я тоже стану пиратом-призраком!" }, { 13.96, "Спасибо, что сводил меня в Западный Край, я знаю, что вокруг полно всякой жути." }, { 20.11, "Надеюсь, я не очень усложнил тебе жизнь." }, { 23.22, "Ты просто чудо!" } }, f = { { 0.00, "Надо же, настоящий призрак!" }, { 2.16, "Потрясающе – мне не терпится рассказать ребятам из приюта." }, { 6.63, "Капитан Грейсон..." }, { 8.10, "И выглядел точно как пират!" }, { 10.27, "Когда я вырасту, я тоже стану пиратом-призраком!" }, { 14.11, "Спасибо, что сводила меня в Западный Край, я знаю, что вокруг полно всякой жути." }, { 20.39, "Надеюсь, я не очень усложнил тебе жизнь." }, { 23.53, "Ты просто чудо!" } } } } },
    [1688] = { d = 41.0, v = "human-male#50", n = { x = 473 }, c = { x = { { 0.00, "У меня была ученица по имени Сурена Каледон." }, { 3.24, "Помню, она стояла как раз там, где сейчас стоишь ты…" }, { 6.92, "Просила меня научить её искусству чернокнижия, и таланта ей было не занимать." }, { 12.37, "А ещё она была молода и довольно миловидна." }, { 15.48, "Если бы я видел тогда, что это за вероломная дрянь!" }, { 19.10, "Распутная девка сбежала с одним из членов Братства Справедливости по имени Эрлан Драджмур." }, { 25.51, "Об этой потере я нисколько не сожалею, однако колье Кровавого камня, которое я подарил ей, мне всё ещё нужно." }, { 33.19, "Её жизнь для меня больше ничего не значит." }, { 36.17, "Ты найдёшь девку на тыквенной ферме Бреквеллов." }, { 39.47, "Верни мне моё имущество!" } } }, t = { d = 15.0, v = "human-male#50", n = { x = 173 }, c = { x = { { 0.00, "Сурена была талантлива, но не настолько, чтобы овладеть чарами самостоятельно." }, { 5.57, "Печально видеть, как погибают молодые и талантливые, но иногда без этого нельзя." }, { 11.28, "Надеюсь, усилия, вложенные в тебя, прахом не пойдут..." } } } } },
    [1689] = { d = 30.4, g = 1, v = "human-male#50", n = { m = 344, f = 345 }, c = { m = { { 0.00, "Вернув моё колье и одолев Сурену, ты доказал, что не уступаешь ей в таланте." }, { 5.51, "Поэтому я уверен, что тебе не помешает обучение." }, { 9.05, "Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше." }, { 15.86, "Я научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоём распоряжении." }, { 27.66, "Используй магию колье в кругу призыва." } }, f = { { 0.00, "Вернув моё колье и одолев Сурену, ты доказала, что не уступаешь ей в таланте." }, { 5.40, "Поэтому я уверен, что тебе не помешает обучение." }, { 8.83, "Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше." }, { 15.44, "Я научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоём распоряжении." }, { 26.87, "Используй магию колье в кругу призыва." } } }, t = { d = 18.4, v = "human-male#50", n = { x = 206 }, c = { x = { { 0.00, "Тебе удалось даже больше, чем я ожидал." }, { 2.93, "На это я и надеялся." }, { 4.42, "Теперь ты можешь научиться управлять покорённым тобой демоном." }, { 8.91, "Он станет твоим помощником в предстоящих испытаниях." }, { 12.69, "Сейчас мне нечему больше учить тебя, но я уверен, что мы с тобой, ещё увидимся..." } } } } },
    [1690] = { d = 30.9, v = "goblin-male", n = { x = 361 }, c = { x = { { 0.00, "Эй, ты!" }, { 0.50, "Пора оказать услугу Водной компании Прибамбасска." }, { 4.03, "Кочевники Скитальцев Пустыни захватили почти все колодцы пустыни Танарис!" }, { 9.20, "Без них у нас мигом закончится вода." }, { 11.72, "Если ты хочешь заслужить нашу признательность, расправься с этими варварами!" }, { 17.08, "Ступай на восток и прикончи десять бандитов и десять воров из шайки Скитальцев Пустыни, а на обратном пути доложись мне." }, { 25.52, "Никому не миновать расправы... или как там говорится..." }, { 29.37, "А, неважно, иди себе!" } } }, t = { d = 21.0, g = 1, v = "goblin-male", n = { m = 250, f = 252 }, c = { m = { { 0.00, "Ну, вот это называется эффективность!" }, { 2.60, "Ты помог нам сократить число кочевников, и мы начинаем подумывать о том, чтобы отбить наши колодцы." }, { 9.57, "Водная компания Прибамбасска благодарит тебя за помощь, но мы ещё не разобрались с этими проклятыми кочевниками." }, { 17.36, "Слушай внимательно – вот что нам понадобится теперь..." } }, f = { { 0.00, "Ну, вот это называется эффективность!" }, { 2.59, "Ты помогла нам сократить число кочевников, и мы начинаем подумывать о том, чтобы отбить наши колодцы." }, { 9.67, "Водная компания Прибамбасска благодарит тебя за помощь, но мы ещё не разобрались с этими проклятыми кочевниками." }, { 17.45, "Слушай внимательно – вот что нам понадобится теперь..." } } } } },
    [1691] = { d = 29.2, g = 1, v = "goblin-male", n = { m = 325, f = 326 }, c = { m = { { 0.00, "Теперь тебе придётся схватиться с кочевниками посильнее." }, { 4.10, "Ты неплохо поработал, но если отбивать у этих гадов наши колодцы, лучше бы противников было поменьше!" }, { 11.63, "На сей раз выступи против разбойников, убийц и тёмных магов." }, { 15.99, "Их можно найти на востоке и юго-востоке отсюда." }, { 19.55, "Не буду тебе лгать – справиться с ними нелегко." }, { 23.06, "Зато в случае успеха мы очень скоро сможем вернуть себе принадлежащее нам по праву!" } }, f = { { 0.00, "Теперь тебе придётся схватиться с кочевниками посильнее." }, { 4.10, "Ты неплохо поработала, но если отбивать у этих гадов наши колодцы, лучше бы противников было поменьше!" }, { 11.70, "На сей раз выступи против разбойников, убийц и тёмных магов." }, { 16.06, "Их можно найти на востоке и юго-востоке отсюда." }, { 19.63, "Не буду тебе лгать – справиться с ними нелегко." }, { 23.13, "Зато в случае успеха мы очень скоро сможем вернуть себе принадлежащее нам по праву!" } } }, t = { d = 17.8, g = 1, v = "goblin-male", n = { m = 214, f = 215 }, c = { m = { { 0.00, "Первоклассная работа…" }, { 1.52, "Первоклассная!" }, { 2.53, "Число кочевников сократилось настолько, что мы можем бросить им вызов!" }, { 7.46, "Ты уже поговорил с оператором крана Тормозиллером?" }, { 11.01, "Он предлагает награду за меха с водой, которые могли тебе попасться во время битвы с кочевниками!" } }, f = { { 0.00, "Первоклассная работа…" }, { 1.47, "Первоклассная!" }, { 2.44, "Число кочевников сократилось настолько, что мы можем бросить им вызов!" }, { 7.21, "Ты уже поговорила с оператором крана Тормозиллером?" }, { 10.69, "Он предлагает награду за меха с водой, которые могли тебе попасться во время битвы с кочевниками!" } } } } },
    [1692] = { d = 10.9, v = "nightelf-female#52", n = { x = 131 }, c = { x = { { 0.00, "Я сложила собранный тобой элунит в сундук." }, { 2.91, "Отнеси его кузнецу Матилю, мы сделаем из него элунитовое оружие." }, { 7.33, "Матиль на юге отсюда, на другой стороне этого здания." } } }, t = { d = 14.6, v = "nightelf-male#59", n = { x = 153 }, c = { x = { { 0.00, "А, элунитовая руда." }, { 1.54, "Работать с этим металлом – одно удовольствие, ведь он благословлён самой богиней Элуной." }, { 8.34, "Выковать элунитовое оружие – великая честь." }, { 11.70, "Подожди, я сейчас примусь за работу..." } } } } },
    [1693] = { t = { d = 13.4, g = 1, v = "nightelf-male#59", n = { m = 144, f = 146 }, c = { m = { { 0.00, "Я выковал это оружие из элунита, который ты мне принёс." }, { 4.00, "Прошу, возьми то, что подходит тебе больше всего." }, { 7.68, "И я должен поблагодарить тебя." }, { 9.91, "Работать с элунитом — и честь, и удовольствие." } }, f = { { 0.00, "Я выковал это оружие из элунита, который ты мне принесла." }, { 4.24, "Прошу, возьми то, что подходит тебе больше всего." }, { 7.94, "И я должен поблагодарить тебя." }, { 10.20, "Работать с элунитом — и честь, и удовольствие." } } } } },
    [1698] = { d = 11.3, v = "dwarf-male", n = { x = 121 }, c = { x = { { 0.00, "Йорус Ячменовар бросил вызов всем воинам Альянса." }, { 3.95, "Он ждёт в таверне Приозёрья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание." } } }, npc = { [5479] = { d = 10.7, v = "human-male", n = { x = 121 }, c = { x = { { 0.00, "Йорус Ячменовар бросил вызов всем воинам Альянса." }, { 3.76, "Он ждёт в таверне Приозёрья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание." } } } } }, t = { d = 12.2, v = "dwarf-male", n = { x = 110 }, c = { x = { { 0.00, "Ха!" }, { 0.30, "Значит, до тебя дошли вести о моём вызове, а?" }, { 4.16, "Что ж, садись и слушай." }, { 6.12, "Пей и наслаждайся..." }, { 7.78, "Может быть, это твоя последняя выпивка в этой жизни." } } } } },
    [1699] = { d = 36.2, g = 1, v = "dwarf-male", n = { m = 399, f = 400 }, c = { m = { { 0.00, "Я называю моё испытание Ретбанским вызовом." }, { 3.25, "Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться." }, { 10.82, "Элементарно!" }, { 11.76, "Есть, правда, несколько \"но\"…" }, { 13.93, "Вернуться тебе придётся в течение часа." }, { 16.90, "Там полно красногорских гноллов." }, { 19.68, "Перед тем, как тронуться в путь, тебе придётся глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменоваров!" }, { 28.80, "Что скажешь?" }, { 29.75, "Пещеры Ретбана находятся в холмах на севере от Приозёрья." }, { 34.01, "Ты готов принять Ретбанский вызов?" } }, f = { { 0.00, "Я называю моё испытание Ретбанским вызовом." }, { 3.22, "Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться." }, { 10.73, "Элементарно!" }, { 11.66, "Есть, правда, несколько \"но\"…" }, { 13.81, "Вернуться тебе придётся в течение часа." }, { 16.76, "Там полно красногорских гноллов." }, { 19.43, "Перед тем, как тронуться в путь, тебе придётся глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменоваров!" }, { 28.48, "Что скажешь?" }, { 29.42, "Пещеры Ретбана находятся в холмах на севере от Приозёрья." }, { 33.65, "Ты готова принять Ретбанский вызов?" } } }, t = { d = 4.5, g = 1, v = "dwarf-male", n = { m = 31, f = 32 }, c = { m = { { 0.00, "Ты справился!" }, { 1.55, "Молодец!" }, { 2.59, "Трижды ура тебе!" } }, f = { { 0.00, "Ты справилась!" }, { 1.54, "Молодец!" }, { 2.50, "Трижды ура тебе!" } } } } },
    [1700] = { d = 16.0, v = "dwarf-male", n = { x = 185 }, c = { x = { { 0.00, "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Гриманду Элмору." }, { 7.21, "Он живёт здесь, в Квартале Дворфов, в оружейном магазине." }, { 11.17, "Он гордится своим искусством, и совсем не обрадуется моему открытию..." } } }, t = { d = 13.4, v = "dwarf-male", n = { x = 108 }, c = { x = { { 0.00, "Это написал Фьюрен?" }, { 1.88, "Как он смел!" }, { 2.95, "Да я его всему сам научил!" }, { 5.41, "Яйца курицу не учат!" }, { 7.37, "Нахал!" }, { 8.03, "Хм-м-м..." }, { 8.85, "Но в этих записях что-то есть..." }, { 11.80, "Надо попробовать..." } } } } },
    [1701] = { d = 24.9, v = "dwarf-male", n = { x = 264 }, c = { x = { { 0.00, "Ну вот, я дал тебе отличный щит, но это ещё не всё." }, { 3.82, "Я знаю секрет изготовления очень прочного доспеха." }, { 7.79, "Это нелегко, и мне потребуются редкие материалы, но если тебе не лень за ними поохотиться, доспех получится несравненный." }, { 17.10, "Что скажешь?" }, { 18.08, "Если ты не боишься трудностей, я выдам тебе список необходимых материалов и где их искать." } } }, t = { d = 9.8, v = "dwarf-male", n = { x = 99 }, c = { x = { { 0.00, "Тебе удалось добыть всё необходимое?" }, { 2.97, "Вот это да!" }, { 3.91, "Я опасался, что химеры слопают тебя с потрохами!" }, { 7.82, "Что ж, займёмся доспехами..." } } } } },
    [1702] = { d = 27.3, g = 1, v = "dwarf-male", n = { m = 295, f = 296 }, c = { m = { { 0.00, "Да, приняв Ретбанский вызов, ты показал, на что способен." }, { 4.27, "Я своё слово держу." }, { 5.76, "Ты получишь обещанную награду…" }, { 8.06, "Только она в Штормграде." }, { 9.96, "Поговори с моим другом, Фьюреном Длиннобородом." }, { 13.54, "Он живёт в Квартале Дворфов." }, { 15.64, "Его щиты славятся во всей округе, а мне он должен услугу." }, { 19.98, "Вот, отнеси Фьюрену этот бочонок жгучего пива Ячменоваров и попроси взамен щит." }, { 26.01, "Он плохого не даст." } }, f = { { 0.00, "Да, приняв Ретбанский вызов, ты показала, на что способна." }, { 4.30, "Я своё слово держу." }, { 5.78, "Ты получишь обещанную награду…" }, { 8.06, "Только она в Штормграде." }, { 9.94, "Поговори с моим другом, Фьюреном Длиннобородом." }, { 13.50, "Он живёт в Квартале Дворфов." }, { 15.58, "Его щиты славятся во всей округе, а мне он должен услугу." }, { 19.88, "Вот, отнеси Фьюрену этот бочонок жгучего пива Ячменоваров и попроси взамен щит." }, { 25.86, "Он плохого не даст." } } }, t = { d = 12.4, v = "dwarf-male", n = { x = 112 }, c = { x = { { 0.00, "А, жгучее пиво Ячменоваров." }, { 2.40, "Отличный напиток!" }, { 3.95, "Значит, ты от Йоруса, а?" }, { 6.05, "Конечно я дам тебе щит, да ещё какой!" }, { 9.22, "Такого нигде не найти, честное слово!" } } } } },
    [1703] = { d = 13.8, v = "dwarf-male", n = { x = 157 }, c = { x = { { 0.00, "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Матилю." }, { 6.63, "Он живёт довольно далеко, в Дарнассе, но несомненно будет рад, если я поделюсь с ним своими открытиями." } } }, t = { d = 12.2, v = "nightelf-male#59", n = { x = 135 }, c = { x = { { 0.00, "Это интересно, очень интересно." }, { 2.42, "Мой коллега Фьюрен, сделал грандиозное открытие." }, { 6.05, "Спасибо." }, { 6.73, "Это будет честью для меня, применять новые технологии к моим разработкам." } } } } },
    [1704] = { d = 14.8, v = "dwarf-male", n = { x = 161 }, c = { x = { { 0.00, "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Клацморту Гайкокруту." }, { 7.98, "Он живёт в Стальгорне, и когда услышит о моём открытии..." }, { 12.17, "Он бороду себе выдернет от восторга!" } } }, t = { d = 19.3, v = "gnome-male", n = { x = 195 }, c = { x = { { 0.00, "Ну и ну!" }, { 0.65, "Поразительные записи мне прислали!" }, { 3.41, "Больше того..." }, { 4.64, "Они ошеломляющие и невероятные, я едва на ногах стою от восторга!" }, { 9.93, "Фьюрен совершил прорыв в кузнечном деле!" }, { 13.27, "Да-да, самый настоящий прорыв!" }, { 15.81, "Мне не терпится испробовать новую технологию!" } } } } },
    [1705] = { d = 31.8, v = "dwarf-male", n = { x = 360 }, c = { x = { { 0.00, "Может, этот Фьюрен и совершил открытие, но мне надо проверить, так ли это." }, { 5.36, "Попробую-ка я сделать такие доспехи." }, { 8.01, "Если ты поможешь добыть все материалы, можешь забрать доспех себе." }, { 12.86, "Мне понадобится горящая кровь и горящий камень." }, { 16.22, "Единственное место, где можно добыть эти материалы – Сумеречный лес." }, { 21.13, "Горящая кровь есть у воргенов из стаи Ночной Погибели из пещеры Роланда, а горящий камень хранит у себя их главарь, Кишкодёр." }, { 30.05, "И не мешкай, во имя Света." } } }, t = { d = 4.9, v = "dwarf-male", n = { x = 48 }, c = { x = { { 0.00, "Недурно!" }, { 0.72, "А теперь, прошу прощения, мне тоже надо поработать..." } } } } },
    [1706] = { t = { d = 16.1, g = 1, v = "dwarf-male", n = { m = 171, f = 172 }, c = { m = { { 0.00, "Глазам своим не верю!" }, { 1.68, "Метод Фурена сработал, и эти доспехи выдержат колоссальные нагрузки." }, { 6.86, "Вот, держи." }, { 7.74, "И спасибо тебе." }, { 8.95, "Я бы не поверил в открытие Фурена, если бы ты не собрал материалы, чтобы я мог сам его проверить." } }, f = { { 0.00, "Глазам своим не верю!" }, { 1.68, "Метод Фурена сработал, и эти доспехи выдержат колоссальные нагрузки." }, { 6.87, "Вот, держи." }, { 7.74, "И спасибо тебе." }, { 8.96, "Я бы не поверил в открытие Фурена, если бы ты не собрала материалы, чтобы я мог сам его проверить." } } } } },
    [1707] = { d = 29.1, v = "goblin-male", n = { x = 326 }, c = { x = { { 0.00, "Привет тебе." }, { 0.98, "Меня зовут Живец, и у меня есть для тебя важная работа!" }, { 5.07, "Ура!" }, { 5.46, "Я опытный оператор крана, и ничто не порадует меня так, как бурдюки с водой Скитальцев Пустыни, которые могут попасться тебе в пустыне, у кочевников." }, { 16.26, "Всё равно это наша вода – мерзкие кочевники её украли!" }, { 20.29, "Водная компания Прибамбасска предлагает в награду полевой набор за каждые пять бурдюков." }, { 26.66, "А главное, ты поможешь Прибамбасску!" } } }, t = { d = 12.0, v = "goblin-male", n = { x = 138 }, c = { x = { { 0.00, "Великолепно!" }, { 0.91, "Чем больше мехов с водой нам удастся добыть, тем ниже вероятность катастрофы!" }, { 6.53, "Можешь таскать их сотнями, и за каждые пять будешь получать всё ту же награду." } } } } },
    [1708] = { d = 29.2, g = 1, v = "gnome-male", n = { m = 334, f = 336 }, c = { m = { { 0.00, "Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах." }, { 5.22, "Раз ты помог Фьюрену, а он мне, я разрешу тебе забрать их себе!" }, { 9.68, "Чтобы довести работу до конца, мне необходим особый коралл, выжженный." }, { 14.72, "Он растёт лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине." }, { 19.88, "Принеси мне побольше таких кораллов, и я примусь за работу." }, { 24.08, "И поторапливайся, у меня руки чешутся, так хочется взяться за дело." } }, f = { { 0.00, "Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах." }, { 5.29, "Раз ты помогла Фьюрену, а он мне, я разрешу тебе забрать их себе!" }, { 9.93, "Чтобы довести работу до конца, мне необходим особый коралл, выжженный." }, { 15.03, "Он растёт лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине." }, { 20.25, "Принеси мне побольше таких кораллов, и я примусь за работу." }, { 24.51, "И поторапливайся, у меня руки чешутся, так хочется взяться за дело." } } }, t = { d = 18.4, g = 1, v = "gnome-male", n = { m = 177, f = 176 }, c = { m = { { 0.00, "Вот, то что нужно!" }, { 1.51, "Молодец!" }, { 2.27, "А теперь дай-ка я их расплавлю и расплющу." }, { 5.83, "Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет!" }, { 12.50, "Ну-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!" } }, f = { { 0.00, "Вот, то что нужно!" }, { 1.51, "Умница!" }, { 2.20, "А теперь дай-ка я их расплавлю и расплющу." }, { 5.75, "Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет!" }, { 12.42, "Ну-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!" } } } } },
    [1709] = { t = { d = 12.7, v = "gnome-male", n = { x = 127 }, c = { x = { { 0.00, "Вот твои доспехи." }, { 1.47, "Метод Фурена сработал блестяще!" }, { 4.12, "Идеально!" }, { 4.93, "Просто изумительно!" }, { 6.55, "Да по ним хоть осадная машина проедет — они тут же вернут себе прежнюю форму!" } } } } },
    [1710] = { d = 29.1, v = "nightelf-male#59", n = { x = 348 }, c = { x = { { 0.00, "Мой коллега, Фьюрен Длиннобород, совершил многообещающее открытие." }, { 4.67, "Я хотел бы испытать его на новых доспехах, мне кажется, результат превзойдёт все ожидания." }, { 11.01, "Не поможешь?" }, { 11.91, "Если ты принесёшь мне все необходимые материалы, я и для тебя сделаю такие доспехи." }, { 17.74, "Мне понадобится высохшая на солнце скорлупа яиц виверн Скального Гнездовья из Тысячи Игл." }, { 24.08, "Скорлупу можно найти под их гнёздами." }, { 26.70, "Как наберёшь достаточно, возвращайся." } } }, t = { d = 6.2, v = "nightelf-male#59", n = { x = 63 }, c = { x = { { 0.00, "Ах, спасибо тебе!" }, { 1.49, "Это прекрасно подойдёт!" }, { 3.42, "Я начну создавать броню немедленно." } } } } },
    [1711] = { t = { d = 15.9, v = "nightelf-male#59", n = { x = 179 }, c = { x = { { 0.00, "Я закончил работу над твоими доспехами и вполне доволен." }, { 4.15, "Новые методы Фурена идеально сочетаются с моими, и я уверен, что эти доспехи окажутся весьма прочными." }, { 11.72, "Спасибо." }, { 12.38, "Пусть они хорошо послужат тебе в грядущих битвах." } } } } },
    [1712] = { d = 37.1, v = "troll-male#77", n = { x = 369 }, c = { x = { { 0.00, "Я давно наблюдаю за этими местами, в надежде дожить до падения великого Циклониана." }, { 6.81, "Увы, мне до сих пор не встретился герой, готовый схватиться с повелителем ветра." }, { 13.25, "Может быть, этим героем окажешься ты?" }, { 16.33, "Докажи, что ты великий воин – собери все предметы, необходимые для призыва Циклониана." }, { 23.29, "Тогда, быть может, тебе удастся одолеть его и завладеть сердцем Вихря." }, { 29.14, "Если это свершится, я вложу силу сердца в оружие и вручу его тебе." }, { 34.78, "Вот список нужных компонентов." } } }, t = { d = 14.4, g = 1, v = "troll-male#77", n = { m = 147, f = 148 }, c = { m = { { 0.00, "Ты сумел собрать всё необходимое для заклинания призыва, доказав тем самым свою силу и ловкость." }, { 7.83, "Но следующий шаг будет гораздо опаснее." }, { 11.04, "Будем надеяться, что сила тебя не покинет." } }, f = { { 0.00, "Ты сумела собрать всё необходимое для заклинания призыва, доказав тем самым свою силу и ловкость." }, { 7.86, "Но следующий шаг будет гораздо опаснее." }, { 11.06, "Будем надеяться, что сила тебя не покинет." } } } } },
    [1713] = { d = 19.4, g = 1, v = "troll-male#77", n = { m = 195, f = 196 }, c = { m = { { 0.00, "Я готов провести ритуал призыва Циклониана." }, { 3.57, "Потом тебе предстоит победить его и забрать у него из груди сердце Вихря." }, { 9.68, "После этого я создам оружие, которое вберёт в себя силу Циклониана." }, { 15.22, "Итак, готов ли ты выступить против повелителя ветра?" } }, f = { { 0.00, "Я готов провести ритуал призыва Циклониана." }, { 3.51, "Потом тебе предстоит победить его и забрать у него из груди сердце Вихря." }, { 9.53, "После этого я создам оружие, которое вберёт в себя силу Циклониана." }, { 14.97, "Итак, готова ли ты выступить против повелителя ветра?" } } }, t = { d = 6.5, g = 1, v = "troll-male#77", n = { m = 51, f = 52 }, c = { m = { { 0.00, "Ты справился!" }, { 1.39, "Циклониан повержен, а у тебя в руках сердце Вихря!" } }, f = { { 0.00, "Ты справилась!" }, { 1.44, "Циклониан повержен, а у тебя в руках сердце Вихря!" } } } } },
    [1714] = { t = { d = 13.1, v = "narrator", n = { x = 125 }, c = { x = { { 0.00, "Обереги медленно опускаются на дно котла…" }, { 3.68, "Из глубины поднимается большой пузырь воздуха, лопается и…" }, { 8.88, "... на поверхности оказывается оплавленный камень." } } } } },
    [1715] = { d = 29.9, v = "gnome-male", n = { x = 366 }, c = { x = { { 0.00, "Хмм." }, { 0.31, "В прежние времена все чернокнижники Каз Модан обучались под присмотром мастеров Гномрегана, но теперь, когда все мы вынуждены ютиться в этой крысиной норе под названием Стальгорн и Магни решил не спускать с нас глаз, нам приходится отсылать наших новичков на обучение в Штормград." }, { 19.00, "По счастью, Гакин не растяпа, так что ты всё равно узнаешь всё, что тебе надо, но я просто киплю!" }, { 25.54, "Короче, ты найдёшь Гакина в подвале \"Забитого ягнёнка\" в Штормграде." } } }, t = { d = 16.4, v = "human-male#50", n = { x = 206 }, c = { x = { { 0.00, "Так тебя послал Зловещая Отвёртка?" }, { 2.24, "Нет, пора бы уже этим стальгорнским растяпам как-то разобраться с ситуацией." }, { 7.27, "Штормград не резиновый, и наставников тут сколько есть, и не больше." }, { 11.64, "Если сюда повалит народ, то рано или поздно мы привлечём к себе внимание." } } } } },
    [1716] = { d = 28.9, v = "human-male#50", n = { x = 324 }, c = { x = { { 0.00, "Сайаады – пожиратели душ, подавляющие волю и вводящие в искушение." }, { 4.83, "Порождение чистого зла." }, { 6.55, "В легкомысленных историях этих демонов называют суккубами, если речь о женщинах, и инкубами, если это мужчины." }, { 14.68, "Примани демона символом любви, победи его – и он будет тебе служить." }, { 19.84, "Но найти подходящий символ непросто." }, { 22.55, "Поговори с Такаром Провидцем." }, { 24.73, "Ты найдёшь его в калимдорских Степях возле лагеря Таурахо." } } }, t = { d = 12.6, v = "human-male#50", n = { x = 138 }, c = { x = { { 0.00, "Как вы добрались?" }, { 1.24, "Вы проделали долгий путь, чтобы поговорить со мной." }, { 4.89, "Но не бойтесь: я знаю, зачем Гакин прислал вас." }, { 8.35, "Это было мудро с его стороны, потому что я могу вам помочь." } } } } },
    [1717] = { d = 13.9, g = 1, v = "gnome-male", n = { m = 181, f = 182 }, c = { m = { { 0.00, "Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать." }, { 4.65, "Ты давненько уже не проходил очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде." }, { 12.75, "Он будет тебя ждать." } }, f = { { 0.00, "Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать." }, { 4.58, "Ты давненько уже не проходила очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде." }, { 12.61, "Он будет тебя ждать." } } }, t = { d = 14.2, v = "human-male#50", n = { x = 165 }, c = { x = { { 0.00, "Хорошо, что кто-то, наконец, поймал тебя." }, { 2.88, "Я уже опасался худшего." }, { 4.53, "В тебя вложено слишком много и было бы жалко тебя потерять." }, { 8.69, "Мы ещё поговорим на эту тему позднее." }, { 11.26, "Твоя тренировка более важна в данный момент." } } } } },
    [1718] = { d = 39.5, v = "scourge-male", n = { x = 395 }, c = { x = { { 0.00, "Ты становишься недурным воином." }, { 2.64, "Пришло время помериться силой с братьями по оружию." }, { 7.01, "Недалеко от побережья Степей, к югу от Кабестана, есть остров." }, { 12.22, "Он называется Островом Битв." }, { 14.56, "Это место встречи воинов." }, { 16.82, "Место встречи и дружеских схваток." }, { 19.76, "Поговори со старшим воином острова, Кланноком Маклеодом." }, { 24.51, "Если он сочтёт тебя достойным дальнейшего обучения, то поможет тебе сделать очередной шаг на пути воина." }, { 33.26, "До Острова Битв можно добраться по песчаной отмели вдоль Торгового побережья." } } }, npc = { [3041] = { d = 41.1, v = "tauren-male#67", n = { x = 395 }, c = { x = { { 0.00, "Ты становишься недурным воином." }, { 2.74, "Пришло время помериться силой с братьями по оружию." }, { 7.28, "Недалеко от побережья Степей, к югу от Кабестана, есть остров." }, { 12.69, "Он называется Островом Битв." }, { 15.12, "Это место встречи воинов." }, { 17.47, "Место встречи и дружеских схваток." }, { 20.52, "Поговори со старшим воином острова, Кланноком Маклеодом." }, { 25.46, "Если он сочтёт тебя достойным дальнейшего обучения, то поможет тебе сделать очередной шаг на пути воина." }, { 34.54, "До Острова Битв можно добраться по песчаной отмели вдоль Торгового побережья." } } } }, [3354] = { d = 36.0, v = "orc-male#60", n = { x = 395 }, c = { x = { { 0.00, "Ты становишься недурным воином." }, { 2.40, "Пришло время помериться силой с братьями по оружию." }, { 6.38, "Недалеко от побережья Степей, к югу от Кабестана, есть остров." }, { 11.11, "Он называется Островом Битв." }, { 13.23, "Это место встречи воинов." }, { 15.29, "Место встречи и дружеских схваток." }, { 17.97, "Поговори со старшим воином острова, Кланноком Маклеодом." }, { 22.29, "Если он сочтёт тебя достойным дальнейшего обучения, то поможет тебе сделать очередной шаг на пути воина." }, { 30.24, "До Острова Битв можно добраться по песчаной отмел