    [1719] = { d = 29.0, g = 1, v = "human-male#50", n = { m = 327, f = 328 }, c = { m = { { 0.00, "Если ты хочешь учиться у меня, тебе придётся пройти испытание, Побоище." }, { 5.27, "Через него проходят все молодые воины, вообразившие себя великими." }, { 10.21, "А величие надо доказывать." }, { 12.18, "Для начала пройди сквозь ту толпу и встань на решётку." }, { 16.00, "Это будет знак Пруттику Плоскоголову, что ты готов." }, { 19.76, "Он сразу пошлёт тебе поединщика." }, { 22.13, "Когда ты одолеешь всех, он позовёт Большого Билла." }, { 25.75, "Убей его и вернись ко мне за отведённое время." } }, f = { { 0.00, "Если ты хочешь учиться у меня, тебе придётся пройти испытание, Побоище." }, { 5.13, "Через него проходят все молодые воины, вообразившие себя великими." }, { 9.93, "А величие надо доказывать." }, { 11.85, "Для начала пройди сквозь ту толпу и встань на решётку." }, { 15.57, "Это будет знак Пруттику Плоскоголову, что ты готова." }, { 19.29, "Он сразу пошлёт тебе поединщика." }, { 21.59, "Когда ты одолеешь всех, он позовёт Большого Билла." }, { 25.12, "Убей его и вернись ко мне за отведённое время." } } }, t = { d = 7.4, g = 1, v = "human-male#50", n = { m = 67, f = 67 }, c = { m = { { 0.00, "Молодец." }, { 0.79, "Ты прошёл испытание Побоищем!" }, { 3.32, "Ты могучий воин, и учить тебя – великая честь..." } }, f = { { 0.00, "Молодец." }, { 0.77, "Ты прошла испытание Побоищем!" }, { 3.33, "Ты могучий воин, и учить тебя – великая честь..." } } } } },
    [1738] = { d = 32.2, v = "human-male#50", n = { x = 362 }, c = { x = { { 0.00, "Готовясь к твоему приходу, я на скорую руку оглядел весь мир, проник взглядом сквозь пелену времени и нашёл то, что тебе нужно." }, { 9.25, "Во время Войны Древних двое влюблённых вместе пали в битве." }, { 13.68, "Там, где перестали биться их сердца, выросло дерево, известное как сердцедрево – символ их бессмертной любви." }, { 21.60, "Этого должно быть достаточно, чтобы привлечь суккуба." }, { 25.57, "Руины Ордил'Арана, где растёт сердцедрево, находятся в северо-западной части Ясеневого леса." } } }, t = { d = 14.3, v = "human-male#50", n = { x = 157 }, c = { x = { { 0.00, "Да, сердцедрево нам подойдёт." }, { 2.08, "Дай-ка я немного обработаю древесину..." }, { 5.02, "Такар – настоящий кладезь премудростей; с таким не пропадёшь, правда?" }, { 10.11, "Если б я только мог убедить его вернуться к цивилизации..." } } } } },
    [1739] = { d = 22.4, v = "human-male#50", n = { x = 268 }, c = { x = { { 0.00, "С помощью сердцевины сердцедрева ты сможешь открыть портал и призвать суккуба в круг призыва." }, { 6.50, "Круг находится в подвале." }, { 8.27, "Не забывай об осторожности, суккубы подчиняли себе и самых стойких заклинателей." }, { 13.89, "После того как вызовешь демона и вернёшь его обратно в Бездну, возвращайся ко мне и я научу тебя, как обращаться с суккубом." } } }, t = { d = 13.6, v = "human-male#50", n = { x = 157 }, c = { x = { { 0.00, "Неплохо, неплохо..." }, { 1.41, "Я не ошибся, когда решил обучать тебя." }, { 4.24, "Твои успехи меня не разочаровывают." }, { 6.81, "Пора научить тебя обращению с только что подчинённым суккубом." }, { 11.24, "Только не забывай про осторожность!" } } } } },
    [1740] = { d = 34.8, v = "human-male#50", n = { x = 399 }, c = { x = { { 0.00, "Когда демоны Легиона попадают в немилость, их души заключают в сферы и раздают магам и чернокнижникам." }, { 7.42, "Многих из них носили на Азероте их слуги." }, { 10.41, "Даже расколотые на части, эти сферы хранят в себе силу демонов, заключённых внутри." }, { 16.53, "Шар Соран'рука был расколот надвое." }, { 19.07, "Одну из частей раздробили на ещё более мелкие фрагменты послушники Сумеречного Молота в Непроглядной Пучине." }, { 26.88, "А другая, большая часть, досталась волшебнику из крепости Тёмного Клыка." }, { 32.02, "Найди их, и я смогу воссоздать этот шар." } } }, t = { d = 25.0, g = 1, v = "human-male#50", n = { m = 277, f = 278 }, c = { m = { { 0.00, "Да..." }, { 0.39, "Этот шар не так уж сильно раскололи, и передо мной почти все осколки." }, { 5.35, "Воссоздать их, сделав Соран'рука единым целым, несложно." }, { 10.09, "Я посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона." }, { 15.05, "Ты оказал мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору." } }, f = { { 0.00, "Да..." }, { 0.40, "Этот шар не так уж сильно раскололи, и передо мной почти все осколки." }, { 5.42, "Воссоздать их, сделав Соран'рука единым целым, несложно." }, { 9.58, "Я посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона." }, { 14.60, "Ты оказала мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору." } } } } },
    [1758] = { d = 31.0, v = "human-male#50", n = { x = 380 }, c = { x = { { 0.00, "Простой круг призыва не поможет тебе вызвать на бой охотника скверны." }, { 4.79, "Я и трое моих послушников поможем тебе создать магические круги." }, { 9.33, "Тебе также понадобится фолиант Заговора, который мы давно утратили." }, { 14.06, "Его написала первая группа чернокнижников, умудрившихся вызвать охотника скверны без посторонней помощи." }, { 21.27, "С этим тебе поможет Кром Крепкорук." }, { 23.76, "Теперь он странствующий чернокнижник и целыми днями сидит в библиотеке Стальгорна, собирая древние тексты." } } }, t = { d = 14.9, v = "dwarf-male", n = { x = 140 }, c = { x = { { 0.00, "Фолиант Заговора?" }, { 1.50, "Хм-м..." }, { 2.09, "Знакомое название." }, { 3.67, "Я его никогда не видел – а уж поверьте, я помню все прочитанные книги." }, { 9.50, "Хм…" }, { 9.80, "А, да!" }, { 10.32, "Я видел ссылки на этот фолиант в библиотечных каталогах." } } } } },
    [1778] = { d = 10.6, g = 1, v = "human-male", n = { x = 117 }, c = { m = { { 0.00, "Я намереваюсь скоро вернуться домой." }, { 2.61, "Надеюсь, у Стефани в Штормграде дела идут хорошо." }, { 6.17, "Не терпится снова увидеться с ней." }, { 8.59, "До следующей встречи, герой." } }, f = { { 0.00, "Я намереваюсь скоро вернуться домой." }, { 2.62, "Надеюсь, у Стефани в Штормграде дела идут хорошо." }, { 6.19, "Не терпится снова увидеться с ней." }, { 8.61, "До следующей встречи, героиня." } } }, t = { d = 24.8, g = 1, v = "dwarf-female#33", n = { m = 238, f = 246 }, c = { m = { { 0.00, "Итак, ты быстро вернулся, а?" }, { 2.31, "И чего же ты достиг за это время?" }, { 5.06, "Итак, ты помог достойному делу?" }, { 7.66, "Возможно ты уже заслужил уважение граждан Азерота." }, { 11.78, "Скажи мне кому ты помог – и я скажу кто ты…" }, { 15.25, "Удивительно, ты действительно следуешь пути Света." }, { 19.29, "Такая жертва будет обязательно вознаграждена в своё время." } }, f = { { 0.00, "Итак, ты быстро вернулась, а?" }, { 2.42, "И чего же ты достигла за это время?" }, { 5.36, "Итак, ты помогла достойному делу?" }, { 8.15, "Возможно ты уже заслужила уважение граждан Азерота." }, { 12.40, "Скажи мне кому ты помогла – и я скажу кто ты…" }, { 16.07, "Удивительно, ты действительно следуешь пути Света." }, { 20.18, "Такая жертва будет обязательно вознаграждена в своё время." } } } } },
    [1779] = { d = 34.0, g = 1, v = "dwarf-female#33", n = { m = 356, f = 363 }, c = { m = { { 0.00, "Я хочу, чтобы ты взял это." }, { 2.06, "Это называется знак Жизни." }, { 4.11, "Ты показал своё милосердие и терпение, а теперь я хочу, чтобы ты проявил себя не только как воин, но и как целитель." }, { 12.89, "Мой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Чёрного Железа." }, { 19.75, "Он едва ноги унёс – сейчас лечит свои раны у одного из наших жрецов." }, { 25.10, "Возьми Символ и поговори с ним." }, { 27.50, "Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор." }, { 32.23, "Да пребудет с тобой Свет." } }, f = { { 0.00, "Я хочу, чтобы ты взяла это." }, { 2.16, "Это называется знак Жизни." }, { 4.18, "Ты показала своё милосердие и терпение, а теперь я хочу, чтобы ты проявила себя не только как воин, но и как целительница." }, { 13.23, "Мой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Чёрного Железа." }, { 19.98, "Он едва ноги унёс – сейчас лечит свои раны у одного из наших жрецов." }, { 25.24, "Возьми Символ и поговори с ним." }, { 27.60, "Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор." }, { 32.26, "Да пребудет с тобой Свет." } } }, t = { d = 26.6, g = 1, v = "dwarf-male", n = { x = 298 }, c = { m = { { 0.00, "Доброго тебе здравия, герой." }, { 2.68, "Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона." }, { 7.26, "Так что сила твоего знака Жизни пока мне не нужна." }, { 10.89, "Значит, моя жёнушка тебя послала потолковать со мной, да?" }, { 14.90, "Славно, славно." }, { 16.05, "У меня найдётся времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя." } }, f = { { 0.00, "Доброго тебе здравия, героиня." }, { 2.80, "Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона." }, { 7.38, "Так что сила твоего знака Жизни пока мне не нужна." }, { 11.00, "Значит, моя жёнушка тебя послала потолковать со мной, да?" }, { 15.00, "Славно, славно." }, { 16.15, "У меня найдётся времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя." } } } } },
    [1780] = { d = 16.6, g = 1, v = "human-female", n = { m = 182, f = 183 }, c = { m = { { 0.00, "Я сегодня же отнесу это детям." }, { 2.26, "Ты можешь не тревожиться, герой." }, { 4.59, "Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения доказал, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается." }, { 15.59, "Доброго пути!" } }, f = { { 0.00, "Я сегодня же отнесу это детям." }, { 2.25, "Ты можешь не тревожиться, героиня." }, { 4.69, "Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения доказала, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается." }, { 15.68, "Доброго пути!" } } }, t = { d = 36.1, v = "human-male", n = { x = 429 }, c = { x = { { 0.00, "Ты уже здесь?" }, { 0.94, "Однако, странствия заняли у тебя не так много времени, как я полагал." }, { 5.76, "И что же тебе удалось свершить за время, проведённое вдали от Храма?" }, { 10.45, "Может быть, тебе довелось сражаться за справедливость?" }, { 14.20, "Или удалось постичь смысл милосердия?" }, { 16.83, "Или помочь кому-либо из нуждающихся жителей Азерота?" }, { 20.52, "Расскажи мне всё..." }, { 21.83, "Что ж, это производит впечатление." }, { 24.21, "Поверь, это поистине поступки того, кто следует путём Света и ставит благо других выше своего собственного." }, { 31.78, "Рано или поздно такое самопожертвование всегда вознаграждается." } } } } },
    [1781] = { d = 35.1, v = "human-male", n = { x = 416 }, c = { x = { { 0.00, "Прими этот знак Жизни." }, { 1.62, "Тебе удалось обрести милосердие и терпение: пришло время узнать, хватит ли у тебя сил, чтобы воспользоваться одним из величайших даров Света." }, { 11.44, "Мой друг Газин недавно вернулся из Элвиннского леса с острова Героев, где он едва не расстался с жизнью после стычки с магами Братства Справедливости." }, { 21.77, "Сейчас он у алтаря: надеюсь, служителям удастся исцелить его раны." }, { 26.43, "Возьми этот Символ и поговори с Газином." }, { 29.29, "Если сумеешь помочь ему, мы продолжим нашу беседу." }, { 32.90, "Да пребудет с тобой извечный Свет!" } } }, t = { d = 31.1, g = 1, v = "dwarf-male", n = { x = 330 }, c = { m = { { 0.00, "Я рад встрече с тобой, герой." }, { 2.73, "Не обращай внимания на мои раны: добрые служители Света смогут обо всём позаботиться." }, { 8.91, "Сила знака Жизни, который ты держишь в руках, мне без надобности... по крайней мере пока." }, { 15.41, "Значит, Даториан послал тебя поговорить со мной, да?" }, { 19.18, "Что ж, это правильно." }, { 20.74, "Я тебе расскажу, что случилось со мной и моим другом Хензом." }, { 25.10, "Если нам повезёт и тебе хватит сил и умения, ты ещё сможешь всех нас спасти..." } }, f = { { 0.00, "Я рад встрече с тобой, героиня." }, { 2.91, "Не обращай внимания на мои раны: добрые служители Света смогут обо всём позаботиться." }, { 9.19, "Сила знака Жизни, который ты держишь в руках, мне без надобности... по крайней мере пока." }, { 15.80, "Значит, Даториан послал тебя поговорить со мной, да?" }, { 19.63, "Что ж, это правильно." }, { 21.22, "Я тебе расскажу, что случилось со мной и моим другом Хензом." }, { 25.65, "Если нам повезёт и тебе хватит сил и умения, ты ещё сможешь всех нас спасти..." } } } } },
    [1782] = { t = { d = 26.6, g = 1, v = "dwarf-male", n = { m = 280, f = 284 }, c = { m = { { 0.00, "Вот твои доспехи." }, { 1.33, "Они выдержат самый яростный натиск, или я не Фьюрен Длиннобород!" }, { 6.17, "И я должен тебя поблагодарить." }, { 8.42, "Работая с материалами, которые ты принёс, я многому научился." }, { 12.86, "Думаю, когда-нибудь я совершу ещё одно открытие!" }, { 16.44, "Я отправлю то, что узнал, другим кузнецам Альянса." }, { 20.15, "Скажу им, что ты мне очень помог, – может, и они захотят отплатить тебе тем же." } }, f = { { 0.00, "Вот твои доспехи." }, { 1.35, "Они выдержат самый яростный натиск, или я не Фьюрен Длиннобород!" }, { 6.26, "И я должен тебя поблагодарить." }, { 8.54, "Работая с материалами, которые ты принесла, я многому научился." }, { 13.25, "Думаю, когда-нибудь я совершу ещё одно открытие!" }, { 16.89, "Я отправлю то, что узнал, другим кузнецам Альянса." }, { 20.65, "Скажу им, что ты мне очень помогла, – может, и они захотят отплатить тебе тем же." } } } } },
    [1783] = { d = 33.6, v = "dwarf-male", n = { x = 395 }, c = { x = { { 0.00, "Мы выслеживали дворфов Чёрного Железа, что окопались к югу от озера Хельмово Ложе." }, { 5.71, "Мы знали, что они затевают недоброе, потому мы с Нармом решили подобраться поближе, чтобы посмотреть, как их капитан раздаёт приказы своим воинам." }, { 15.87, "Мы с Нармом воспользовались случаем и пристукнули нескольких, но они оказались крепче, чем мы думали, и набросились на нас толпой." }, { 24.77, "Нарм велел мне бежать за помощью, и вот я здесь." }, { 28.04, "Нарму нужна помощь." }, { 29.48, "И я не успокоюсь, пока он её не получит." }, { 32.24, "Ты ведь поможешь ему?" } } }, t = { d = 29.0, g = 1, v = "dwarf-male", n = { m = 329, f = 332 }, c = { m = { { 0.00, "Не знаю, как мне отблагодарить тебя, брат!" }, { 2.87, "Видать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни." }, { 8.29, "Да, это правда, я пал в бою с дворфами Чёрного Железа, пытаясь получить одну из их бумаг." }, { 14.47, "Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появился." }, { 21.58, "То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже." } }, f = { { 0.00, "Не знаю, как мне отблагодарить тебя, сестра!" }, { 3.08, "Видать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни." }, { 8.55, "Да, это правда, я пал в бою с дворфами Чёрного Железа, пытаясь получить одну из их бумаг." }, { 14.77, "Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появилась." }, { 22.00, "То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже." } } } } },
    [1784] = { d = 30.7, v = "dwarf-male", n = { x = 385 }, c = { x = { { 0.00, "Прежде чем я пал в бою, мы с Майридоном почти одолели одного из соглядатаев из клана Чёрного Железа возле того небольшого домика." }, { 8.39, "Мы видели, как их капитан раздавал им бумаги с приказами, и хотели убить его и забрать эти бумаги." }, { 14.84, "Кое-кто в совете Стальгорна до сих пор не верит в присутствие дворфов Чёрного Железа в Дун Морог." }, { 21.06, "Захватив одну из этих бумаг, мы не только получим доказательства их вылазок, но и поймём, что они затевают." }, { 27.98, "Добудь один из приказов и отнеси Майридону." } } }, t = { d = 18.7, g = 1, v = "dwarf-male", n = { m = 201, f = 203 }, c = { m = { { 0.00, "Ха-ха!" }, { 0.53, "Тебе удалось!" }, { 1.60, "Ты спас Нарма и нашёл доказательство, которое нужно моей жене, чтобы показать его в совете." }, { 8.40, "Ты просто единственное благословение Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены." }, { 16.53, "Прими снова мою благодарность." } }, f = { { 0.00, "Ха-ха!" }, { 0.51, "Тебе удалось!" }, { 1.54, "Ты спасла Нарма и нашла доказательство, которое нужно моей жене, чтобы показать его в совете." }, { 8.33, "Ты просто единственное благословение Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены." }, { 16.14, "Прими снова мою благодарность." } } } } },
    [1785] = { d = 19.8, g = 1, v = "dwarf-male", n = { m = 199, f = 199 }, c = { m = { { 0.00, "Вижу, моя жёнушка прямо пышет гордостью." }, { 3.11, "Я бы на твоём месте поскакал прямо к ней." }, { 6.16, "Сдаётся, она хочет перекинуться с тобой парой слов." }, { 10.01, "Да хранит тебя Свет, славный герой." }, { 12.72, "Я буду искать тебя на поле боя против Плети и клана Чёрного Железа, когда придёт пора." } }, f = { { 0.00, "Вижу, моя жёнушка прямо пышет гордостью." }, { 3.19, "Я бы на твоём месте поскакал прямо к ней." }, { 6.32, "Сдаётся, она хочет перекинуться с тобой парой слов." }, { 10.27, "Да хранит тебя Свет, славная героиня." }, { 13.19, "Я буду искать тебя на поле боя против Плети и клана Чёрного Железа, когда придёт пора." } } }, t = { d = 31.0, g = 1, v = "dwarf-female#33", n = { m = 336, f = 338 }, c = { m = { { 0.00, "Сегодня ты оказал большую услугу Стальгорну." }, { 3.33, "Я горда, что ты среди нас, и если ты готов, я хотела бы благословить тебя этим свитком." }, { 9.80, "Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни." }, { 20.40, "Я научу тебя возрождать к жизни твоих соратников." }, { 24.13, "Используй это умение мудро, и прими благодарность от меня, моего мужа и всего Стальгорна." } }, f = { { 0.00, "Сегодня ты оказала большую услугу Стальгорну." }, { 3.42, "Я горда, что ты среди нас, и если ты готова, я хотела бы благословить тебя этим свитком." }, { 9.99, "Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни." }, { 20.66, "Я научу тебя возрождать к жизни твоих соратников." }, { 24.41, "Используй это умение мудро, и прими благодарность от меня, моего мужа и всего Стальгорна." } } } } },
    [1786] = { d = 38.6, v = "dwarf-male", n = { x = 467 }, c = { x = { { 0.00, "Мы с Хензом добрались до острова Героев – он находится посреди Озера Каменных Столбов, в северо-восточной части Элвиннского леса." }, { 8.73, "Мы слышали, что Братство Справедливости проникло в наши земли, и должны предоставить доказательства этого вторжения королевским советникам." }, { 18.00, "Мы засекли двоих из этих подонков, когда они просматривали кое-какие документы, и напали на них." }, { 24.54, "Увы, магов было больше, и нас заставили отступить." }, { 27.99, "Хенз прикрывал меня, и мне удалось бежать... проклятый глупец, отвагу проявить решил!.." }, { 33.87, "И вот он там так и остался." }, { 35.63, "Хенз, я имею в виду." }, { 37.02, "Может, ты сумеешь помочь?" } } }, t = { d = 31.8, g = 1, v = "dwarf-male", n = { m = 366, f = 368 }, c = { m = { { 0.00, "Прими мою благодарность, брат." }, { 2.12, "В твоих руках я вижу знак Жизни – тебя послал Даториан или Газин." }, { 6.81, "Мы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи." }, { 12.99, "Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побеждён..." }, { 20.93, "Но тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, можешь мне поверить." }, { 28.55, "Это свидетельство крепости твоей веры..." } }, f = { { 0.00, "Прими мою благодарность, сестра." }, { 2.33, "В твоих руках я вижу знак Жизни – тебя послал Даториан или Газин." }, { 7.06, "Мы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи." }, { 13.30, "Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побеждён..." }, { 21.31, "Но тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, можешь мне поверить." }, { 29.00, "Это свидетельство крепости твоей веры..." } } } } },
    [1787] = { d = 31.3, v = "dwarf-male", n = { x = 371 }, c = { x = { { 0.00, "У нас ещё будет время поговорить о Символе." }, { 2.92, "Сейчас важнее заполучить те бумаги, которые мы видели у Братства Справедливости." }, { 8.33, "Если бумаги будут у нас, мы сможем доказать, что братство проникло в Элвиннский лес – а может, и узнать что-нибудь о его планах." }, { 16.96, "Увы, навряд ли я сейчас могу считаться воином." }, { 20.18, "Сможешь ли ты пойти в бой в одиночку?" }, { 22.67, "Сумеешь ли ты добыть то, что нам так необходимо?" }, { 25.83, "Если это тебе удастся, отнеси бумаги Газину и сообщи ему, что со мной всё хорошо." } } }, t = { d = 9.8, v = "dwarf-male", n = { x = 88 }, c = { x = { { 0.00, "Великолепно!" }, { 1.17, "Тебе удалось спасти Хенза и выполнить задание." }, { 5.59, "Теперь я знаю: воистину, Свет озаряет твой путь!" } } } } },
    [1788] = { d = 20.2, v = "dwarf-male", n = { x = 232 }, c = { x = { { 0.00, "После того как Даториан ознакомится с этими бумагами, я передам их королевским советникам; однако прежде тебе стоит поговорить с Даторианом." }, { 10.09, "Думаю, он тоже хотел бы поблагодарить тебя." }, { 13.26, "Твоя помощь поистине неоценима." }, { 15.58, "Надеюсь, это не последняя наша встреча." }, { 18.49, "Я горжусь нашей дружбой." } } }, t = { d = 31.5, g = 1, v = "human-male", n = { m = 358, f = 360 }, c = { m = { { 0.00, "Что ж, полагаю, ты можешь гордиться своими свершениями." }, { 3.86, "Скажу больше: ты можешь также гордиться своими способностями." }, { 8.22, "Далеко не каждый может использовать силу, которой наделён знак Жизни." }, { 13.09, "Если в твоих силах призвать исцеляющую силу Света, ты достоин того, чтобы принять величайший дар паладинов, – дар воскрешения." }, { 22.01, "Ты сможешь возвращать к жизни павших спутников так же, как вернул к жизни Хенза." }, { 27.64, "Горний Свет озарил тебя, открой же ему душу." } }, f = { { 0.00, "Что ж, полагаю, ты можешь гордиться своими свершениями." }, { 3.94, "Скажу больше: ты можешь также гордиться своими способностями." }, { 8.40, "Далеко не каждый может использовать силу, которой наделён знак Жизни." }, { 13.38, "Если в твоих силах призвать исцеляющую силу Света, ты достойна того, чтобы принять величайший дар паладинов, – дар воскрешения." }, { 22.55, "Ты сможешь возвращать к жизни павших спутников так же, как вернула к жизни Хенза." }, { 28.37, "Горний Свет озарил тебя, открой же ему душу." } } } } },
    [1789] = { t = { d = 14.1, g = 1, v = "dwarf-female#33", n = { m = 139, f = 140 }, c = { m = { { 0.00, "Если, использовав Знак Жизни, ты не сможешь помочь Нарму, возвращайся ко мне, и я дам тебе другой." }, { 7.41, "И мне, и моему мужу очень важно, чтобы ты вернулся с победой." }, { 12.15, "Прошу, поторопись." } }, f = { { 0.00, "Если, использовав Знак Жизни, ты не сможешь помочь Нарму, возвращайся ко мне, и я дам тебе другой." }, { 7.14, "И мне, и моему мужу очень важно, чтобы ты вернулась с победой." }, { 12.81, "Прошу, поторопись." } } } } },
    [1790] = { t = { d = 23.5, g = 1, v = "human-male", n = { m = 262, f = 263 }, c = { m = { { 0.00, "Поторопись: если ты не справишься, на кону окажется не одна жизнь." }, { 4.51, "Если по какой-то причине тебе не удастся помочь Газину и Хензу, вернись ко мне, и я дам тебе ещё один Знак Жизни." }, { 12.28, "Но не принимай мою помощь за простую милость: ты должен доказать, что достоин, как и любой другой герой, а постоянные неудачи потом могут сказаться на тебе." } }, f = { { 0.00, "Поторопись: если ты не справишься, на кону окажется не одна жизнь." }, { 4.51, "Если по какой-то причине тебе не удастся помочь Газину и Хензу, вернись ко мне, и я дам тебе ещё один Знак Жизни." }, { 12.28, "Но не принимай мою помощь за простую милость: ты должна доказать, что достойна, как и любой другой героиня, а постоянные неудачи потом могут сказаться на тебе." } } } } },
    [1791] = { d = 28.2, g = 1, v = "human-male#50", n = { m = 341, f = 342 }, c = { m = { { 0.00, "Что ж, ты освоил стойку берсерка, теперь нужно подобрать тебе оружие." }, { 4.77, "Поговори с Бат'ра Ветростражем, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями." }, { 12.67, "Он опытный оружейник и могущественный шаман." }, { 15.67, "Если ты захочешь встретиться с Бат'ра, отправляйся к реке, что течёт вдоль восточного края мельницы Таррен." }, { 22.90, "Иди вдоль неё на север – Бат'ра разбил лагерь рядом с руинами на берегу реки." } }, f = { { 0.00, "Что ж, ты освоила стойку берсерка, теперь нужно подобрать тебе оружие." }, { 4.80, "Поговори с Бат'ра Ветростражем, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями." }, { 12.63, "Он опытный оружейник и могущественный шаман." }, { 15.61, "Если ты захочешь встретиться с Бат'ра, отправляйся к реке, что течёт вдоль восточного края мельницы Таррен." }, { 22.78, "Иди вдоль неё на север – Бат'ра разбил лагерь рядом с руинами на берегу реки." } } }, t = { d = 12.4, g = 1, v = "troll-male#77", n = { m = 111, f = 111 }, c = { m = { { 0.00, "Тебе пришлось проделать долгий путь, юный воин." }, { 3.92, "Как у тебя горят глаза!" }, { 5.88, "Тебе ведь нужно мощное оружие?" }, { 8.42, "Я помогу тебе... в обмен на твою помощь." } }, f = { { 0.00, "Тебе пришлось проделать долгий путь, юная воин." }, { 4.19, "Как у тебя горят глаза!" }, { 6.28, "Тебе ведь нужно мощное оружие?" }, { 8.99, "Я помогу тебе... в обмен на твою помощь." } } } } },
    [1792] = { t = { d = 11.5, v = "troll-male#77", n = { x = 102 }, c = { x = { { 0.00, "Сердце смерча у меня, и я готов поместить его в оружие, которое ты выберешь." }, { 6.74, "Выбирай оружие, и знай: его сила – это сила Циклониана." } } } } },
    [1793] = { t = { d = 33.0, v = "human-male", n = { x = 360 }, c = { x = { { 0.00, "Уже ясно, что Свет с тобой, но времена становятся всё опаснее, и важно знать, какая сила скрыта под твоей плотью." }, { 8.34, "Когда демоны, драконы или иное зло ступят на твою землю, твоя стойкость подвергнется испытанию." }, { 15.49, "Хватит ли тебе сил?" }, { 16.95, "Отвага в любых обстоятельствах – такая же неотъемлемая часть пути паладина, как Свет, доспехи и оружие." }, { 24.43, "Защищать слабых и не терять веры – вот ещё два урока, которые тебе предстоит усвоить, пока ты учишься в Соборе Света." } } } } },
    [1794] = { t = { d = 32.2, v = "dwarf-male", n = { x = 340 }, c = { x = { { 0.00, "Уже доказано, что Свет с тобой, но времена становятся всё опаснее, и важно знать, какая сила скрыта под плотью." }, { 8.35, "Когда демоны, драконы или иное зло ступят на твои земли, твоя стойкость подвергнется испытанию." }, { 15.68, "Хватит ли тебе сил?" }, { 17.17, "Отвага в любой ситуации — такая же часть пути паладина, как Свет, доспехи и оружие." }, { 23.42, "Защищать слабых и не терять веры — вот ещё два урока, которые тебе предстоит усвоить, пока ты учишься в Соборе Света." } } } } },
    [1795] = { d = 24.1, g = 1, v = "human-male#50", n = { m = 265, f = 266 }, c = { m = { { 0.00, "Если ты готов, давай приступим." }, { 2.39, "Начну с объяснений." }, { 3.84, "Сначала мы создадим основной круг призыва." }, { 6.96, "После этого мои послушники создадут больший круг при помощи жезлов направления." }, { 12.85, "Затем ты прочтёшь заклинание из фолианта Заговора, и на зов явится охотник Скверны." }, { 18.88, "Будь осторожен." }, { 20.01, "Охотник Скверны – сильный враг, не теряй головы." } }, f = { { 0.00, "Если ты готова, давай приступим." }, { 2.51, "Начну с объяснений." }, { 4.00, "Сначала мы создадим основной круг призыва." }, { 7.19, "После этого мои послушники создадут больший круг при помощи жезлов направления." }, { 13.23, "Затем ты прочтёшь заклинание из фолианта Заговора, и на зов явится охотник Скверны." }, { 19.41, "Будь осторожна." }, { 20.56, "Охотник Скверны – сильный враг, не теряй головы." } } }, t = { d = 10.3, v = "human-male#50", n = { x = 116 }, c = { x = { { 0.00, "Впечатляюще." }, { 0.95, "Когда я сражался с охотником скверны, то едва выжил." }, { 4.93, "Предчувствую, что ты станешь одним из сильнейших чернокнижников нашей эры." } } } } },
    [1796] = { d = 31.7, v = "human-female#47", n = { x = 367 }, c = { x = { { 0.00, "Первым делом я помогу тебе создать одеяние." }, { 3.16, "Ты принесёшь мне несколько необходимых составляющих, а уж работать над ними будем вместе." }, { 9.30, "В итоге, если ты справишься, разумеется, ты получишь первый из многих предметов, которые одарят тебя могуществом и помогут в борьбе против сил Тьмы." }, { 19.68, "Для начала тебе нужны одеяния Аркана." }, { 22.40, "Их может сшить портной или их можно купить... ещё лучше сделать их самому, но это сложно." }, { 28.72, "Короче, для начала принеси мне эти одеяния." } } }, t = { d = 20.6, v = "human-female#47", n = { x = 243 }, c = { x = { { 0.00, "То, что нужно." }, { 0.99, "В основе всех волшебных предметов должна лежать вещь высокого качества." }, { 5.91, "Чем больше усилий и искусства вложить в предмет, тем легче напитать его магией." }, { 11.44, "Редкие и дорогие составляющие также лучше держат магию." }, { 15.36, "Не жалей об утрате этого одеяния: когда мы закончим, оно станет куда лучше." } } } } },
    [1798] = { d = 17.5, v = "human-male#50", n = { x = 218 }, c = { x = { { 0.00, "Пришло время научить тебя вызывать охотника скверны." }, { 3.60, "Здесь у меня нет ни реагентов, ни предметов, необходимых для обучения, так что придётся тебе найти другого учителя – Страхада Фарсана." }, { 12.37, "Он проживает в гоблинском порту Кабестане." }, { 15.20, "Я извещу его о том, что ты появишься." } } }, t = { d = 15.0, v = "human-male#50", n = { x = 151 }, c = { x = { { 0.00, "Ах да, конечно." }, { 1.18, "Наше новое чудо." }, { 2.58, "Но, боюсь, настоящее чудо вряд ли успеет стать легендой при жизни." }, { 7.66, "Впрочем, неважно – ты здесь для того, чтобы пройти обучение, а не слушать, как я шучу сам с собой." } } } } },
    [1799] = { d = 29.0, v = "human-female#47", n = { x = 351 }, c = { x = { { 0.00, "Отлично, приступим." }, { 1.35, "Первым делом ступай внутрь и поговори с моими послушниками." }, { 5.40, "Тебе предстоит избрать свой путь – они объяснят подробнее." }, { 9.39, "Потом придётся отправиться в Пустоши и отыскать сферу Подземного огня у одного из чернокнижников Поля Маннорок." }, { 16.95, "Именно эту сферу необходимо очистить при помощи мага по имени Табета в южной части Пылевых топей." }, { 23.76, "Она поможет тебе ради меня." }, { 25.79, "И не возвращайся, пока не выполнишь оба задания." } } }, t = { d = 15.7, v = "human-female#45", n = { x = 154 }, c = { x = { { 0.00, "А, так тебя послала Менара." }, { 2.21, "Ну, хорошо..." }, { 3.28, "Располагайся, чувствуй себя как дома." }, { 6.28, "Впрочем, ты, должно быть, спешишь?" }, { 8.99, "Быть может, ищешь утраченную силу?" }, { 11.77, "Может, я ошибаюсь, и скверна всё же коснулась тебя." } } } } },
    [1800] = { d = 32.3, v = "child-male", n = { x = 355 }, c = { x = { { 0.00, "Если мы хорошо себя ведём, то попечительницы сирот рассказывают нам на ночь сказки про славные сражения и про мирные времена." }, { 9.25, "В одной из легенд говорилось о том, как пал Лордерон и как злобный Артас отнял жизнь у собственного отца, чтобы захватить трон." }, { 18.63, "Бесчестный человек!" }, { 20.11, "Когда я вырасту и стану великим воином Орды, мной будет править лишь закон чести, а не зло!" }, { 27.00, "Покажи мне его тронный зал!" }, { 29.09, "Он находится как раз перед входом в Подгород." } } }, t = { d = 23.3, g = 1, v = "child-male", n = { m = 237, f = 238 }, c = { m = { { 0.00, "Этот тронный зал такой страшный!" }, { 2.60, "Хоть он и пустой, чувствуется, что там случилось великое зло." }, { 7.23, "Я разозлился... но мне стало и грустно." }, { 10.24, "Теперь я понимаю, почему попечительницы рассказывают нам такие истории: я никогда так не предам свой народ!" }, { 18.52, "Спасибо, что сводил меня в тронный зал." }, { 21.61, "Я многое узнал." } }, f = { { 0.00, "Этот тронный зал такой страшный!" }, { 2.65, "Хоть он и пустой, чувствуется, что там случилось великое зло." }, { 7.38, "Я разозлился... но мне стало и грустно." }, { 10.46, "Теперь я понимаю, почему попечительницы рассказывают нам такие истории: я никогда так не предам свой народ!" }, { 18.92, "Спасибо, что сводила меня в тронный зал." }, { 22.14, "Я многое узнал." } } } } },
    [1801] = { d = 29.4, v = "human-male#50", n = { x = 364 }, c = { x = { { 0.00, "Простой круг призыва не поможет тебе вызвать на бой охотника Скверны." }, { 4.68, "Я и трое моих послушников поможем тебе создать магические круги." }, { 9.12, "Тебе также понадобится фолиант Заговора, который мы давно утратили." }, { 13.75, "Его написала первая группа чернокнижников, умудрившихся вызвать охотника Скверны без посторонней помощи." }, { 20.80, "С этим тебе поможет Йорах Аннисон." }, { 23.24, "Он работает в Подгороде картографом, но всё равно знает о древних текстах куда больше моего." } } }, t = { d = 22.2, v = "scourge-male#83", n = { x = 196 }, c = { x = { { 0.00, "Картография!" }, { 1.17, "Картинки, далёкие от реальности." }, { 4.10, "Они мне не нужны." }, { 5.77, "Книги – повествование, описание!" }, { 8.78, "В них и только в них следует искать правду." }, { 12.79, "Я обменял бы все свои карты на одну книгу о возвышении некромантии или сагу о торжестве Тёмной Госпожи." } } } } },
    [1802] = { d = 39.2, v = "dwarf-male", n = { x = 448 }, c = { x = { { 0.00, "Он был утрачен, но есть кое-какие соображения насчёт того, где он может находиться сейчас." }, { 6.37, "С него сделали только одну копию и отнеслись к ней совершенно по-варварски: большая часть книги была вырвана из переплёта." }, { 15.07, "Ходят слухи, что она каким-то образом попала в руки одного кентавра из Тысячи Игл." }, { 21.06, "Остальное было утрачено в прибрежных краях к западу от Южнобережья, откуда книгу должны были переправить морем в Гавань Менетилов." }, { 30.46, "Судно так и не прибыло." }, { 32.13, "А за мои сведения я попрошу одно: когда найдёшь книгу, дай мне заглянуть в неё хотя бы одним глазком." } } }, t = { d = 17.2, v = "dwarf-male", n = { x = 199 }, c = { x = { { 0.00, "С ума сойти!" }, { 0.96, "Теперь я один из немногих, что сумел хоть мельком заглянуть в неё." }, { 5.65, "Не терпится повнимательнее изучить этот текст." }, { 8.93, "Какой великий день!" }, { 10.34, "Позволь мне ещё раз заглянуть в неё прежде, чем уйдёшь." }, { 14.13, "Уверен, что Страхад охотно пришлёт мне копию." } } } } },
    [1803] = { d = 36.1, v = "scourge-male#83", n = { x = 373 }, c = { x = { { 0.00, "А!" }, { 0.21, "Вижу, наши вкусы сходятся." }, { 2.42, "Поиски фолианта Заговора – достойное занятие." }, { 6.05, "Знаешь ли ты, что он некогда хранился в стенах Лордерона?" }, { 10.53, "Правда, эти варвары поглумились над ним, вырвали больше половины страниц." }, { 16.37, "Кто мог совершить такую мерзость?" }, { 19.01, "Итак, половина потеряна, хотя говорят, будто она попала в руки кентавров из Тысячи Игл." }, { 26.05, "Остальную часть должны были перевезти в Стальгорн, но она потерялась при перевозке где-то на берегу озера к западу от Южнобережья." } } }, t = { d = 14.7, g = 1, v = "scourge-male#83", n = { m = 121, f = 121 }, c = { m = { { 0.00, "Так-так-так!" }, { 1.20, "Что это у нас?" }, { 2.57, "Невероятно." }, { 3.68, "Я был уверен, что это невозможно, но вот я держу в руках фолиант Заговора." }, { 10.70, "Позволь мне полистать его, пока ты не ушёл." } }, f = { { 0.00, "Так-так-так!" }, { 1.20, "Что это у нас?" }, { 2.57, "Невероятно." }, { 3.68, "Я был уверен, что это невозможно, но вот я держу в руках фолиант Заговора." }, { 10.69, "Позволь мне полистать его, пока ты не ушла." } } } } },
    [1804] = { d = 32.5, g = 1, v = "dwarf-male", n = { m = 368, f = 368 }, c = { m = { { 0.00, "Как же не хочется его выпускать из рук!" }, { 2.72, "Но ты его нашёл и, конечно же, свершишь при его помощи куда более важные дела." }, { 8.30, "Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию." }, { 13.87, "Пока тебя не было, он прислал для тебя письмо." }, { 17.23, "Он пишет, что для призыва духов необходимо достать три жезла направления." }, { 22.36, "Он-то не знает, где их искать, но зато я знаю!" }, { 25.66, "Последний раз их использовали орки клана Драконьей Пасти в Болотине." }, { 30.47, "Я бы поискал у их заклинателей!" } }, f = { { 0.00, "Как же не хочется его выпускать из рук!" }, { 2.68, "Но ты его нашла и, конечно же, свершишь при его помощи куда более важные дела." }, { 8.22, "Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию." }, { 13.70, "Пока тебя не было, он прислал для тебя письмо." }, { 17.01, "Он пишет, что для призыва духов необходимо достать три жезла направления." }, { 22.05, "Он-то не знает, где их искать, но зато я знаю!" }, { 25.29, "Последний раз их использовали орки клана Драконьей Пасти в Болотине." }, { 30.02, "Я бы поискал у их заклинателей!" } } }, t = { d = 10.6, v = "human-male#50", n = { x = 129 }, c = { x = { { 0.00, "Отлично!" }, { 0.64, "Фолиант Заговора и три практически нетронутых жезла направления." }, { 5.22, "Забавно выходит." }, { 6.45, "Давно молодые чернокнижники не приручали охотников Скверны." } } } } },
    [1805] = { d = 35.0, g = 1, v = "scourge-male#83", n = { m = 383, f = 384 }, c = { m = { { 0.00, "Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет." }, { 7.00, "Выбор здесь небогат – большинство книг посвящено географии, и я всё до дыр зачитал." }, { 13.11, "Надеюсь, Страхад пришлёт мне копию." }, { 15.76, "Кстати, он прислал весточку, пока тебя не было." }, { 19.43, "Чтобы выполнить очередную задачу, тебе понадобится три жезла направления." }, { 25.00, "В благодарность за то, что ты дал мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине." } }, f = { { 0.00, "Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет." }, { 6.76, "Выбор здесь небогат – большинство книг посвящено географии, и я всё до дыр зачитал." }, { 12.67, "Надеюсь, Страхад пришлёт мне копию." }, { 15.23, "Кстати, он прислал весточку, пока тебя не было." }, { 18.78, "Чтобы выполнить очередную задачу, тебе понадобится три жезла направления." }, { 24.16, "В благодарность за то, что ты дала мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине." } } }, t = { d = 10.6, v = "human-male#50", n = { x = 129 }, c = { x = { { 0.00, "Отлично!" }, { 0.64, "Фолиант Заговора и три практически нетронутых жезла направления." }, { 5.22, "Забавно выходит." }, { 6.45, "Давно молодые чернокнижники не приручали охотников Скверны." } } } } },
    [1806] = { d = 25.4, g = 1, v = "human-male", n = { m = 284, f = 285 }, c = { m = { { 0.00, "Почему бы нам не пойти прямо в кузню и не начать работу?" }, { 4.00, "Я уже ждал тебя и подготовился, так что времени это много не займёт." }, { 8.75, "Когда всё будет закончено, ты будешь гораздо лучше подготовлен к защите дела Света, уж за это я ручаюсь." }, { 16.18, "Не утаю, я даже немного завидую твоим деяниям." }, { 19.54, "Но осознание того, что я по-своему помогу тебе, и немало помогу, всё же радует меня." } }, f = { { 0.00, "Почему бы нам не пойти прямо в кузню и не начать работу?" }, { 3.97, "Я уже ждал тебя и подготовился, так что времени это много не займёт." }, { 8.71, "Когда всё будет закончено, ты будешь гораздо лучше подготовлена к защите дела Света, уж за это я ручаюсь." }, { 16.15, "Не утаю, я даже немного завидую твоим деяниям." }, { 19.49, "Но осознание того, что я по-своему помогу тебе, и немало помогу, всё же радует меня." } } }, t = { d = 22.2, v = "human-male", n = { x = 221 }, c = { x = { { 0.00, "Вот оно." }, { 0.70, "Оружие, достойное защитника Света вроде тебя." }, { 4.35, "Я дал ему имя в честь великого дворфского паладина, моего друга." }, { 9.40, "Его звали Вериган..." }, { 11.08, "Бош Вериган." }, { 12.07, "Прошу, прими его в благодарность от меня и моей жены." }, { 16.35, "Мы очень обязаны тебе." }, { 18.17, "Мир станет лучше, если по земле ходят такие, как ты!" } } } } },
    [1818] = { d = 20.6, v = "scourge-male", n = { x = 199 }, c = { x = { { 0.00, "Мне сказали, что у стража смерти Диллинджера есть работа для таких, как ты." }, { 6.34, "Если ты хочешь доказать свою ценность Тёмной Госпоже, немедленно отправляйся к нему." }, { 13.61, "Страж смерти Диллинджер стоит на посту в западном конце Брилла, рядом с кладбищем." } } }, t = { d = 13.2, v = "scourge-male", n = { x = 115 }, c = { x = { { 0.00, "Ты хочешь получить задание?" }, { 2.59, "Отлично." }, { 3.42, "У меня есть одно." }, { 5.09, "Довольно важное." }, { 6.68, "Заодно и свою силу нам покажешь..." }, { 9.94, "И решимость защищать дело Отрёкшихся." } } } } },
    [1819] = { d = 42.5, g = 1, v = "scourge-male", n = { m = 391, f = 392 }, c = { m = { { 0.00, "Когда Тирисфальские леса наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению." }, { 9.50, "Он обладал свободной волей и звал себя Улаг Колун." }, { 14.05, "Впрочем, несмотря на свободу воли, его подчинил себе Король-лич." }, { 19.88, "Мы надеялись избавить Улага от чар, но не смогли." }, { 24.19, "Довольно ему томиться в темнице плоти." }, { 27.71, "Освободи его." }, { 28.99, "Для этого его придётся убить." }, { 31.62, "Воспользуйся переключателем в мавзолее к северу отсюда." }, { 36.49, "Это позволит снять с Улага магические путы." }, { 40.40, "Сними их и... будь готов!" } }, f = { { 0.00, "Когда Тирисфальские леса наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению." }, { 9.41, "Он обладал свободной волей и звал себя Улаг Колун." }, { 13.92, "Впрочем, несмотря на свободу воли, его подчинил себе Король-лич." }, { 19.70, "Мы надеялись избавить Улага от чар, но не смогли." }, { 23.97, "Довольно ему томиться в темнице плоти." }, { 27.45, "Освободи его." }, { 28.71, "Для этого его придётся убить." }, { 31.32, "Воспользуйся переключателем в мавзолее к северу отсюда." }, { 36.15, "Это позволит снять с Улага магические путы." }, { 40.03, "Сними их и... будь готова!" } } }, t = { d = 16.1, v = "scourge-male", n = { x = 148 }, c = { x = { { 0.00, "Молодец." }, { 0.83, "Улаг был серьёзным сторонником Плети." }, { 4.25, "Тебе удалось доказать стражам смерти и через них Тёмной Госпоже, что ты опытный и умелый воин и заслуживаешь дальнейшего обучения." } } } } },
    [1820] = { d = 18.4, v = "scourge-male", n = { x = 187 }, c = { x = { { 0.00, "Тебе удалось услужить Тёмной Госпоже, пришло время услужить одному из её подданных." }, { 6.87, "Колману Фартингу нужен воин, который сможет отомстить врагам Отрёкшихся." }, { 12.86, "Колман сидит в таверне \"Петля висельника\", в восточной части Брилла." } } }, t = { d = 18.6, v = "scourge-male#82", n = { x = 143 }, c = { x = { { 0.00, "Да, это правда." }, { 1.73, "Мне нужна помощь закалённого воина." }, { 5.47, "Средств у меня немного, зато ты послужишь не только мне, но и делу Отрёкшихся." }, { 13.63, "Так что если ты справишься, наградой будет почёт." } } } } },
    [1821] = { d = 33.8, v = "scourge-male#82", n = { x = 303 }, c = { x = { { 0.00, "При жизни я служил семье Агамондов, и именно из-за них и умер!" }, { 5.78, "Поделом им, они стали теперь безмозглыми прислужниками Короля-лича." }, { 12.05, "Мне же хочется лишить их остатков чести." }, { 15.76, "Ступай в Семейную усыпальницу Агамондов и принеси их фамильное оружие: меч, топор, кинжал и палицу." }, { 24.84, "Склеп находится севернее мельниц Агамондов." }, { 28.81, "Его стерегут бойцы Плети и сами неупокоенные Агамонды." } } }, t = { d = 12.2, v = "scourge-male#82", n = { x = 91 }, c = { x = { { 0.00, "А!" }, { 0.29, "Вот оно!" }, { 1.27, "Итак, проклятые земли Агамондов лишены остатков чести и памяти." }, { 8.32, "Отныне семьи воистину не существует!" } } } } },
    [1822] = { t = { d = 22.5, g = 1, v = "scourge-male#82", n = { m = 193, f = 194 }, c = { m = { { 0.00, "Три клинка из тех, что ты мне вернул, я оставлю себе — на память о моей боли и утрате." }, { 7.54, "Но прошу тебя, выбери из фамильных реликвий ту, что тебе больше по душе, и оставь её себе." }, { 15.57, "Пусть она послужит тебе лучше, чем своим проклятым прежним владельцам." } }, f = { { 0.00, "Три клинка из тех, что ты мне вернула, я оставлю себе — на память о моей боли и утрате." }, { 7.88, "Но прошу тебя, выбери из фамильных реликвий ту, что тебе больше по душе, и оставь её себе." }, { 16.16, "Пусть она послужит тебе лучше, чем своим проклятым прежним владельцам." } } } } },
    [1823] = { d = 20.6, v = "tauren-male#67", n = { x = 163 }, c = { x = { { 0.00, "Ты уже опытный воин, и имя твоё на слуху у многих." }, { 5.09, "Может быть, ты хочешь пройти испытание Руги Тотема Гнева?" }, { 10.90, "Коли так, отправляйся в Лагерь Таурахо, в Степи." }, { 15.73, "Он ждёт всех воинов, что готовы принять его вызов." } } }, npc = { [3354] = { d = 18.6, v = "orc-male#60", n = { x = 163 }, c = { x = { { 0.00, "Ты уже опытный воин, и имя твоё на слуху у многих." }, { 4.60, "Может быть, ты хочешь пройти испытание Руги Тотема Гнева?" }, { 9.84, "Коли так, отправляйся в Лагерь Таурахо, в Степи." }, { 14.20, "Он ждёт всех воинов, что готовы принять его вызов." } } } }, [4595] = { d = 19.7, v = "scourge-male", n = { x = 163 }, c = { x = { { 0.00, "Ты уже опытный воин, и имя твоё на слуху у многих." }, { 4.88, "Может быть, ты хочешь пройти испытание Руги Тотема Гнева?" }, { 10.44, "Коли так, отправляйся в Лагерь Таурахо, в Степи." }, { 15.06, "Он ждёт всех воинов, что готовы принять его вызов." } } } } }, t = { d = 2.9, v = "tauren-male", n = { x = 23 }, c = { x = { { 0.00, "Ты хочешь пройти испытание?" } } } } },
    [1824] = { d = 31.3, v = "tauren-male", n = { x = 301 }, c = { x = { { 0.00, "Чтобы пройти это испытание, тебе придётся отправиться на юг, к Полям Великанов." }, { 6.80, "Там ты встретишь полчища ползучих существ, похожих на насекомых." }, { 12.28, "Они явились в Степи незванными, и мне они совсем не нравятся." }, { 17.61, "Принеси их усики." }, { 19.16, "Главное, чтобы они всё ещё дёргались, поэтому тебе придётся поторопиться." }, { 25.34, "Добудь мне усики за отведённое время, и я сочту, что испытание пройдено." } } }, t = { d = 9.8, g = 1, v = "tauren-male", n = { m = 83, f = 83 }, c = { m = { { 0.00, "Отличная работа!" }, { 1.67, "Ты прошёл испытание на Полях Великанов, сделав тем самым ещё один шаг по тропе воина." } }, f = { { 0.00, "Отличная работа!" }, { 1.59, "Ты прошла испытание на Полях Великанов, сделав тем самым ещё один шаг по тропе воина." } } } } },
    [1825] = { d = 19.4, v = "tauren-male", n = { x = 203 }, c = { x = { { 0.00, "Слухи о твоих доблестных подвигах во славу Орды дошли до знаменитого орочьего кузнеца, Тун'грима Огневзора." }, { 8.51, "Он хотел бы сделать для тебя доспехи, но тебе надо как можно скорее с ним встретиться." }, { 15.32, "Тун'грим живёт на востоке от Перекрёстка, что в Степях." } } }, t = { d = 6.2, g = 1, v = "orc-male#60", n = { m = 48, f = 48 }, c = { m = { { 0.00, "Да, ты пришёл." }, { 1.46, "Отлично, нам с тобой многое придётся обсудить." } }, f = { { 0.00, "Да, ты пришла." }, { 1.53, "Отлично, нам с тобой многое придётся обсудить." } } } } },
    [1838] = { d = 33.3, v = "orc-male#60", n = { x = 334 }, c = { x = { { 0.00, "Я наслышан о твоей силе и доблести и хочу сделать для тебя броню, которая охранит тебя в бесчисленных сражениях." }, { 9.24, "Впрочем, создание такой брони – само по себе подвиг." }, { 13.64, "Мне понадобится твоя помощь, а также помощь других кузнецов Орды." }, { 19.06, "Возьми этот список." }, { 20.75, "Я составлял его не одну ночь, напряжённо вглядываясь в пергамент почти незрячими глазами." }, { 27.93, "Принеси мне всё перечисленное, и я создам тебе первую часть доспеха." } } }, t = { d = 4.9, g = 1, v = "orc-male#60", n = { m = 37, f = 39 }, c = { m = { { 0.00, "Ты принёс всё, что я просил." }, { 2.76, "Теперь дело за мной..." } }, f = { { 0.00, "Ты принесла всё, что я просил." }, { 2.87, "Теперь дело за мной..." } } } } },
    [1839] = { d = 16.9, v = "orc-male#60", n = { x = 170 }, c = { x = { { 0.00, "Кузнец-тролль по имени Ула'елек готов выковать для тебя рукавицы жестокости." }, { 6.38, "Он живёт в Дуротаре, в деревне Сен'джин, вместе со своими собратьями из племени Чёрного Копья, и с нетерпением ждёт твоего прихода." } } }, t = { d = 17.2, v = "troll-male#77", n = { x = 166 }, c = { x = { { 0.00, "Привет тебе." }, { 1.10, "Старый Тун'грим предупредил меня о твоём приходе, но умолчи он, я не удивился бы твоему появлению." }, { 9.04, "Духи следят за каждым твоим шагом, юный воин, и они говорят, что от твоей руки пало немало врагов." } } } } },
    [1840] = { d = 14.3, v = "orc-male#60", n = { x = 150 }, c = { x = { { 0.00, "Искусство Орма Каменного Копыта пользуется заслуженным уважением." }, { 5.31, "Он и сделает тебе шлем Жестокости." }, { 8.07, "Его можно найти в Громовом Утёсе, рядом с прудом и центральным тотемом города." } } }, t = { d = 7.8, v = "tauren-male", n = { x = 56 }, c = { x = { { 0.00, "Привет тебе, воин." }, { 2.05, "Я Орм." }, { 2.71, "Тун'грим сказал, что тебе нужен шлем." }, { 6.63, "Это правда?" } } } } },
    [1841] = { d = 18.3, v = "orc-male#60", n = { x = 205 }, c = { x = { { 0.00, "Говорят, что при жизни Велора Нители была одним из лучших кузнецов Лордерона." }, { 5.80, "Кажется, она и после смерти не лишилась таланта." }, { 9.47, "Поговори с Велорой, она сделает тебе набедренники Жестокости." }, { 14.07, "Велора трудится в Подгороде Лордерона, в торговом квартале." } } }, t = { d = 18.0, v = "scourge-female", n = { x = 159 }, c = { x = { { 0.00, "Тебе нужны набедренники?" }, { 2.27, "Отлично!" }, { 3.08, "Хм..." }, { 3.57, "Тогда кто из нас будет их делать?" }, { 6.57, "Шутка." }, { 7.22, "Смешно?" }, { 7.95, "Я вот не понимаю..." }, { 9.65, "Чувство юмора я утратила одновременно с обонянием." }, { 14.19, "Примерно в те времена, как перестала дышать." } } } } },
    [1842] = { d = 38.5, v = "troll-male#77", n = { x = 395 }, c = { x = { { 0.00, "Я могу сделать для тебя пару рукавиц Жестокости, напитав их магической силой." }, { 6.29, "Но прежде тебе придётся добыть эту самую силу." }, { 10.13, "В северо-восточной части Ясеневого леса живут сатиры." }, { 14.54, "Их привлекла туда сила леса." }, { 16.93, "Они питаются его первозданной чистотой, искажая и оскверняя её." }, { 22.07, "Сатиров, вобравших в себя особенно много магии Ясеневого леса можно отличить от других по разбухшим, нераздвоенным копытам." }, { 32.05, "В этих копытах содержится великая сила." }, { 35.30, "Они понадобятся мне для создания рукавиц." } } }, t = { d = 8.9, v = "troll-male#77", n = { x = 68 }, c = { x = { { 0.00, "Ага, вот и они!" }, { 1.65, "Сатиры похитили силу Ясеневого леса, а их сила вольётся в моё творение..." } } } } },
    [1843] = { t = { d = 9.6, v = "troll-male#77", n = { x = 78 }, c = { x = { { 0.00, "Спасибо." }, { 0.86, "Эти рукавицы — моя лучшая работа." }, { 4.24, "Возьми их." }, { 5.27, "Нося их, ты приносишь честь мне и моим предкам." } } } } },
    [1844] = { d = 40.7, g = 1, v = "tauren-male", n = { m = 358, f = 359 }, c = { m = { { 0.00, "Я сделаю тебе шлем, но прежде докажи, что достоин его." }, { 5.11, "В юго-западной части Когтистых гор лежит Обугленная долина." }, { 10.64, "Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния." }, { 22.63, "Туда тебе и придётся отправиться." }, { 25.73, "Ступай в Обугленную долину и найди там химеру-матриарха." }, { 31.01, "Избавь её от страданий." }, { 33.19, "Принеси в доказательство её гибели гальванизированный рог, и я сделаю тебе шлем." } }, f = { { 0.00, "Я сделаю тебе шлем, но прежде докажи, что достойна его." }, { 5.24, "В юго-западной части Когтистых гор лежит Обугленная долина." }, { 10.81, "Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния." }, { 22.89, "Туда тебе и придётся отправиться." }, { 26.02, "Ступай в Обугленную долину и найди там химеру-матриарха." }, { 31.34, "Избавь её от страданий." }, { 33.54, "Принеси в доказательство её гибели гальванизированный рог, и я сделаю тебе шлем." } } }, t = { d = 10.7, g = 1, v = "tauren-male", n = { m = 79, f = 80 }, c = { m = { { 0.00, "Что же, задание выполнено." }, { 2.84, "Теперь я не сомневаюсь в твоей решимости и храбрости." }, { 8.60, "Ты заслужил шлем..." } }, f = { { 0.00, "Что же, задание выполнено." }, { 2.87, "Теперь я не сомневаюсь в твоей решимости и храбрости." }, { 8.72, "Ты заслужила шлем..." } } } } },
    [1845] = { t = { d = 14.6, v = "tauren-male", n = { x = 112 }, c = { x = { { 0.00, "Я дарую тебе этот шлем." }, { 2.47, "Великие деяния привели тебя ко мне, и, если на то будет воля Матери-Земли... впереди тебя ждут деяния ещё более великие." } } } } },
    [1846] = { d = 27.5, v = "scourge-female", n = { x = 247 }, c = { x = { { 0.00, "Чтобы создать набедренники Жестокости, мне понадобятся прочные берцовые кости." }, { 7.23, "У орков из клана Драконьей Пасти крепкие ноги." }, { 11.64, "Они-то мне и нужны." }, { 13.47, "Но только самые прочные." }, { 15.80, "Непременно проверь их, прежде чем счесть подходящими." }, { 20.62, "Если ты сможешь сломать их голыми руками, значит, они недостаточно прочные." } } }, t = { d = 15.9, g = 1, v = "scourge-female", n = { m = 123, f = 122 }, c = { m = { { 0.00, "Молодец!" }, { 0.91, "На вид они крепкие." }, { 2.90, "Пожалуй, подойдут." }, { 4.80, "Орки не возражали?" }, { 6.70, "Сильно жаловались?" }, { 8.60, "Опять я пошутила." }, { 10.41, "Ты не смеёшься." }, { 11.86, "Что-то у меня не так с чувством юмора..." } }, f = { { 0.00, "Умница!" }, { 0.83, "На вид они крепкие." }, { 2.85, "Пожалуй, подойдут." }, { 4.78, "Орки не возражали?" }, { 6.71, "Сильно жаловались?" }, { 8.64, "Опять я пошутила." }, { 10.48, "Ты не смеёшься." }, { 11.95, "Что-то у меня не так с чувством юмора..." } } } } },
    [1847] = { t = { d = 20.6, v = "scourge-female", n = { x = 204 }, c = { x = { { 0.00, "Вот твои набедренники." }, { 1.83, "Скажи, как сидят, или если нужно что-то подогнать." }, { 6.07, "Я всегда стараюсь угодить!" }, { 8.27, "По крайней мере, раньше старалась." }, { 11.13, "Теперь мне не особо есть дело до своего ремесла." }, { 15.08, "Но это всё же лучше, чем быть безмозглой прислужницей Плети!" }, { 19.91, "Наверное." } } } } },
    [1848] = { t = { d = 17.2, g = 1, v = "orc-male#60", n = { m = 156, f = 159 }, c = { m = { { 0.00, "Уверен, выполняя моё поручение, ты перенёс немало тягот и пролил немало крови." }, { 7.03, "Вот плод твоих трудов." }, { 9.04, "Носи его с честью, и пусть однажды ты вернёшься сюда с рассказами о том, как он тебе послужил." } }, f = { { 0.00, "Уверен, выполняя моё поручение, ты перенесла немало тягот и пролила немало крови." }, { 6.91, "Вот плод твоих трудов." }, { 8.81, "Носи его с честью, и пусть однажды ты вернёшься сюда с рассказами о том, как он тебе послужил." } } } } },
    [1858] = { d = 26.9, v = "orc-male#60", n = { x = 249 }, c = { x = { { 0.00, "Загляни в сумку Тазана и принеси мне то, что найдёшь внутри." }, { 5.04, "Замок там непростой, так что постарайся раздобыть ключ." }, { 9.62, "На трупе Тазана ключа не было?" }, { 12.30, "Значит, он его кому-то отдал..." }, { 15.05, "Ах, ну да, конечно." }, { 16.65, "У него был помощник, Гамон." }, { 19.02, "Он пьяница, так что ищи его в тавернах." }, { 22.38, "Возможно, тебе удастся потихоньку утащить у него ключ." } } }, t = { d = 16.7, g = 1, v = "orc-male#60", n = { m = 142, f = 143 }, c = { m = { { 0.00, "Так-так, интересно..." }, { 2.03, "Что ж, ты полностью оправдал моё доверие." }, { 5.83, "Отныне можешь считать себя членом клана Изувеченной Длани." }, { 11.48, "И возьми это." }, { 12.83, "Думаю, он тебе очень пригодится в будущем." } }, f = { { 0.00, "Так-так, интересно..." }, { 1.98, "Что ж, ты полностью оправдала моё доверие." }, { 5.77, "Отныне можешь считать себя членом клана Изувеченной Длани." }, { 11.29, "И возьми это." }, { 12.61, "Думаю, он тебе очень пригодится в будущем." } } } } },
    [1859] = { d = 24.6, v = "orc-male", n = { x = 241 }, c = { x = { { 0.00, "Говори тише!" }, { 1.09, "Ну да, я знаю твоё имя." }, { 2.97, "Мне сказали, чтобы я ждал одного орка, и дали описание твоей внешности." }, { 8.77, "Судя по тому, что о тебе рассказывают, ты неплохо держишься в открытом бою, но можешь прибегнуть и к хитрости, верно?" }, { 18.20, "В общем, сходи в Оргриммар, поговори с Терзоком." }, { 22.11, "У него есть для тебя предложение." } } }, t = { d = 12.5, v = "orc-male#60", n = { x = 120 }, c = { x = { { 0.00, "А, это ты!" }, { 0.90, "Очень хорошо, что Каплак сумел тебя перехватить." }, { 5.01, "Нам нужно поговорить кое о чём, не в последнюю очередь – о твоём будущем в Изувеченной Длани." } } } } },
    [1860] = { d = 15.4, v = "human-male", n = { x = 175 }, c = { x = { { 0.00, "У нас, магов, есть одна задача, которая жизненно важна для безопасности Штормграда и Элвиннского леса." }, { 7.34, "Подробности ты можешь узнать у Джиннии Пушки." }, { 10.65, "Она работает в Башне магов, в районе магов в Штормграде." }, { 14.81, "Не мешкай." } } }, t = { d = 14.1, v = "human-female#47", n = { x = 148 }, c = { x = { { 0.00, "Тебя послали мне на подмогу?" }, { 2.18, "Хорошо." }, { 2.79, "Приятно видеть, что молодые маги рады внести свой вклад в общее дело…" }, { 8.10, "Какое дело, спросишь ты?" }, { 10.01, "Вырастешь – узнаешь." }, { 11.57, "Обязательно узнаешь... со временем." } } } } },
    [1861] = { d = 30.8, v = "human-female#47", n = { x = 388 }, c = { x = { { 0.00, "Этот мир пал жертвой магических войн, в результате которых нарушилось течение магической энергии." }, { 6.45, "Мы попытались просчитать дальнейшие последствия, и многие из нас опасаются худшего!" }, { 11.94, "Но об этом мы поговорим позже." }, { 13.99, "Для начала надо собрать все доступные сведения." }, { 17.19, "Возьми этот сосуд, отправляйся к подножию водопада у Зеркального озера, что на юго-западе от Врат Штормграда, и принеси мне пробу тамошней воды." }, { 26.84, "Я хочу исследовать её на предмет заражения тлетворной магией." } } }, t = { d = 20.7, v = "human-female#47", n = { x = 235 }, c = { x = { { 0.00, "Спасибо." }, { 0.64, "Я исследую магические свойства этой воды." }, { 3.64, "Будем надеяться, что их не окажется, а то, неровен час, окажется, что магия повлияла на всех, кто пил много воды из Зеркального озера." }, { 12.95, "Возьми эту сферу или этот посох в знак моей благодарности за услугу." }, { 17.93, "Пускай они служат тебе верой и правдой." } } } } },
    [1878] = { t = { d = 11.9, v = "goblin-male", n = { x = 138 }, c = { x = { { 0.00, "Великолепно!" }, { 0.91, "Чем больше мехов с водой нам удастся добыть, тем ниже вероятность катастрофы!" }, { 6.49, "Можешь таскать их сотнями, и за каждые пять будешь получать всё ту же награду." } } } } },
    [1879] = { d = 19.7, g = 1, v = "gnome-male", n = { m = 222, f = 223 }, c = { m = { { 0.00, "Бинк, моя коллега-гном из Стальгорна, прислала мне весточку." }, { 4.26, "У неё возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет." }, { 11.11, "Ты готов ей помочь?" }, { 12.53, "Если да, то поговори с ней." }, { 14.46, "Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна." } }, f = { { 0.00, "Бинк, моя коллега-гном из Стальгорна, прислала мне весточку." }, { 4.21, "У неё возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет." }, { 10.98, "Ты готова ей помочь?" }, { 12.45, "Если да, то поговори с ней." }, { 14.36, "Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна." } } }, t = { d = 20.0, v = "gnome-female#41", n = { x = 180 }, c = { x = { { 0.00, "О, я вижу в тебе неплохие задатки, да-да!" }, { 3.69, "Но чтобы стать хорошим магом, одних задатков мало." }, { 8.16, "А не слишком хороший маг – плохой маг." }, { 11.45, "А из-за плохих магов и возникают все проблемы!" }, { 15.53, "Ой, кажется, я немного забегаю вперёд." }, { 18.83, "Начнём сначала!" } } } } },
    [1880] = { d = 38.1, v = "gnome-female#41", n = { x = 410 }, c = { x = { { 0.00, "Мы, маги, не просто щёлкаем пальчиками и создаём забавные искорки!" }, { 4.98, "Мы контролируем поток магической энергии, основной ткани мироздания!" }, { 10.23, "Для этого требуется осторожность и решимость." }, { 13.69, "И знания..." }, { 14.59, "Невероятно много знаний!" }, { 16.52, "Одно из моих устройств, маг-тастический гизмонитор, позволяет собирать и хранить множество знаний!" }, { 24.06, "Но увы, он утрачен!" }, { 25.58, "Когда мы бежали из Гномрегана, я оставила его в сундуке в одном из домишек за пределами города." }, { 32.91, "Теперь там кишмя кишат лепрогномы!" }, { 35.60, "Прошу тебя, верни мне гизмонитор!" } } }, t = { d = 25.3, v = "gnome-female#41", n = { x = 251 }, c = { x = { { 0.00, "О, радость!" }, { 0.96, "Создавая гизмонитор, я и не догадывалась, в какую зависимость от него попаду!" }, { 7.20, "Теперь я могу возобновить свои исследования." }, { 10.88, "Спасибо!" }, { 11.61, "Вот, смотри." }, { 12.64, "Это мой первый набор магических инструментов." }, { 16.39, "Они не так блестят, как новые, зато проверены временем." }, { 20.95, "Выбирай любой из них – все они могут тебе пригодиться." } } } } },
    [1881] = { d = 14.1, v = "scourge-male#83", n = { x = 145 }, c = { x = { { 0.00, "У Анастасии Хартвелл есть задание, которое тебе как раз по плечу." }, { 5.28, "Поговори с ней." }, { 6.53, "Она живёт в квартале магов в Подгороде." }, { 9.76, "Готовься выполнить первое задание для магов Отрёкшихся." } } }, t = { d = 8.9, g = 1, v = "scourge-female#79", n = { m = 83, f = 84 }, c = { m = { { 0.00, "Привет тебе." }, { 1.16, "Ты правильно поступил, откликнувшись на мой зов, но ещё правильнее будет меня выслушать..." } }, f = { { 0.00, "Привет тебе." }, { 1.19, "Ты правильно поступила, откликнувшись на мой зов, но ещё правильнее будет меня выслушать..." } } } } },
    [1882] = { d = 35.4, v = "scourge-female#79", n = { x = 314 }, c = { x = { { 0.00, "Чумные земли – гнусное место, творение Короля-лича." }, { 4.87, "Он отравил землю, осквернил и убил всё живое." }, { 9.09, "Хотя в убийственной силе чумы есть что-то привлекательное, мы, маги Отрёкшихся, считаем её неуправляемой и недопустимой." }, { 19.91, "Для начала надо понять, проникла ли она в Тирисфаль." }, { 24.78, "Отправляйся на ферму Балнира в восточной части Тирисфаля." }, { 30.07, "В саду растут цветы – львиный зев." }, { 33.29, "Собери их и возвращайся." } } }, t = { d = 17.7, v = "scourge-female#79", n = { x = 167 }, c = { x = { { 0.00, "Отличные цветы." }, { 1.38, "Я отправлю их на изучение нашим аптекарям." }, { 5.00, "Пусть поищут в них скверну Чумных земель." }, { 8.53, "Молодец." }, { 9.30, "Я предлагаю тебе выбрать награду – сферу или посох." }, { 13.84, "И то, и другое может тебе здорово пригодиться." } } } } },
    [1883] = { d = 18.9, v = "scourge-male", n = { x = 178 }, c = { x = { { 0.00, "Ун'Тува, маг деревни Сен'джин, обнаружил изменения в потоках магической энергии Дуротара и просит тебя о помощи." }, { 9.64, "Поговори с ним и сделай всё, что сможешь." }, { 13.13, "Приди к нему на помощь, и со временем тебе откроются великие тайны." } } }, npc = { [7311] = { d = 16.7, v = "troll-male", n = { x = 178 }, c = { x = { { 0.00, "Ун'Тува, маг деревни Сен'джин, обнаружил изменения в потоках магической энергии Дуротара и просит тебя о помощи." }, { 8.50, "Поговори с ним и сделай всё, что сможешь." }, { 11.61, "Приди к нему на помощь, и со временем тебе откроются великие тайны." } } } } }, t = { d = 9.1, g = 1, v = "troll-male", n = { m = 84, f = 85 }, c = { m = { { 0.00, "Привет тебе." }, { 1.09, "Хвала тебе, ибо ты ответил на мой зов о помощи." }, { 4.94, "Будем надеяться, что ты справишься с заданием..." } }, f = { { 0.00, "Привет тебе." }, { 1.14, "Хвала тебе, ибо ты ответила на мой зов о помощи." }, { 5.25, "Будем надеяться, что ты справишься с заданием..." } } } } },
    [1884] = { d = 31.8, v = "troll-male", n = { x = 342 }, c = { x = { { 0.00, "Оказывается, нормальное течение магической энергии в Дуротаре нарушил чернокнижник Залазан с островов Эха." }, { 8.41, "Для этого он разместил осквернённые фетиши, груды джуджу, среди домов центрального острова Эха." }, { 15.96, "Из-за этого болеет здешнее зверьё, а чернокнижники и пришельцы из преисподней, таящиеся во тьме, набираются силы." }, { 24.79, "Необходимо уничтожить эти груды джуджу, прежде чем наши земли изменятся до неузнаваемости." } } }, t = { d = 17.1, v = "troll-male", n = { x = 168 }, c = { x = { { 0.00, "Я чувствую, что груды джуджу уничтожены." }, { 3.50, "При удаче все труды Залазана пойдут насмарку и в Дуротаре восстановится нормальное течение магической энергии." }, { 13.00, "Твой подвиг во имя Орды достоин всяческой хвалы!" } } } } },
    [1885] = { d = 21.6, v = "scourge-female", n = { x = 214 }, c = { x = { { 0.00, "Вот уж не ожидала вас увидеть после того, как вами заинтересовался сам Каркад." }, { 6.43, "Ничего нельзя сказать наперёд..." }, { 9.12, "В любом случае, вам лучше встретиться с ним, и поскорее." }, { 13.76, "Лучше вам не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него." } } }, t = { d = 11.3, v = "scourge-male#82", n = { x = 92 }, c = { x = { { 0.00, "Хм." }, { 0.36, "Несомненно, вы пришли сюда по первому моему зову, так?" }, { 5.86, "Не ожидал ничего иного от перспективного стража смерти." } } } } },
    [1886] = { d = 35.2, v = "scourge-male#82", n = { x = 359 }, c = { x = { { 0.00, "Чтобы вступить в ряды стражей смерти, элитной охраны лорда Вариматраса, тебе придётся сперва доказать свои способности." }, { 9.65, "Не буду лгать: это задание может окончиться твоей гибелью." }, { 14.40, "Мне нужна помощь в нескольких вопросах." }, { 17.57, "Во-первых, принеси мне личные вещи Астора Хадрена – это вестник, путешествующий между Серебряным бором и Подгородом." }, { 26.93, "Как ты это сделаешь - тебе решать." }, { 29.74, "Пока что это всё, что тебе следует знать." }, { 33.05, "Справишься - узнаешь больше." } } }, t = { d = 14.2, v = "scourge-male#82", n = { x = 130 }, c = { x = { { 0.00, "Неплохо." }, { 0.80, "Первая часть испытания пройдена." }, { 3.70, "Надеюсь, Андрон ничего не узнал о твоих действиях, и ты сможешь убедить его, что ты и есть тот вестник, которого он ждёт." } } } } },
    [1898] = { d = 33.8, v = "scourge-male#82", n = { x = 370 }, c = { x = { { 0.00, "Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал." }, { 6.91, "Мне приходилось встречаться с Андроном, он не настолько умён, чтобы заподозрить неладное." }, { 13.61, "Лорд Вариматрас подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно." }, { 22.44, "Хорошо бы также получить доказательства." }, { 25.55, "Поговори с Андроном и вытяни из него эти сведения." }, { 29.49, "Его можно найти в лавке неподалёку от Района Фармацевтов." } } }, t = { d = 16.6, v = "scourge-male#83", n = { x = 162 }, c = { x = { { 0.00, "Ах да, я ждал тебя." }, { 1.60, "Полагаю, наши общие знакомые довольны переданными сведениями?" }, { 6.84, "Боюсь, тебя спрашивать без толку, вряд ли тебя обременяют лишними знаниями." }, { 13.22, "К чему доверять гонцу слишком много тайн?" } } } } },
    [1899] = { d = 18.8, v = "scourge-male#83", n = { x = 223 }, c = { x = { { 0.00, "Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной." }, { 6.48, "Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочёл бы иметь дело с тобой." } } }, t = { d = 12.3, v = "scourge-male#82", n = { x = 115 }, c = { x = { { 0.00, "Ну и ну, я и не рассчитывал вытянуть столько информации из Андрона." }, { 5.88, "Дай-ка я изучу этот гроссбух повнимательнее и дам тебе следующее задание." } } } } },
    [1918] = { d = 29.2, v = "narrator", n = { x = 306 }, c = { x = { { 0.00, "Из убитого элементаля выпала ярко светящаяся сфера воды." }, { 4.54, "Содержимое шара в лучшем случае отвратительно." }, { 8.22, "Можно с уверенностью сказать, что то, что заразило воды озера Мистраль, находится в этой сфере." }, { 15.74, "Так сразу и не скажешь, кого может заинтересовать эта находка – возможно, подскажет тот, кто послал вас к этому озеру, а именно Масток Райльшип с заставы Расщеплённого Древа." } } }, t = { d = 26.6, g = 1, v = "orc-male", n = { m = 269, f = 270 }, c = { m = { { 0.00, "Ты нашёл какой-то грязный шар с водой и решил принести его мне?" }, { 4.92, "Я кто, по-твоему – представитель Служителей Земли или что?" }, { 9.42, "Вообще-то, у меня появилась кое-какая идея... может, тебе и правда понадобится помощь Служителей Земли." }, { 17.64, "В смысле, если это поможет разрешить ситуацию на озере, то я к твоим услугам." }, { 23.76, "Ты знаешь, кто такие Служители Земли?" } }, f = { { 0.00, "Ты нашла какой-то грязный шар с водой и решила принести его мне?" }, { 4.93, "Я кто, по-твоему – представитель Служителей Земли или что?" }, { 9.31, "Вообще-то, у меня появилась кое-какая идея... может, тебе и правда понадобится помощь Служителей Земли." }, { 17.32, "В смысле, если это поможет разрешить ситуацию на озере, то я к твоим услугам." }, { 23.27, "Ты знаешь, кто такие Служители Земли?" } } } } },
    [1919] = { d = 21.0, g = 1, v = "gnome-male", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Ты набираешься знаний и опыта, юный путник." }, { 3.11, "Ты готов приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?" }, { 9.57, "Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда." }, { 15.15, "У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир." } }, f = { { 0.00, "Ты набираешься знаний и опыта, юная путница." }, { 3.24, "Ты готова приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?" }, { 9.90, "Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда." }, { 15.60, "У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир." } } }, npc = { [328] = { d = 20.0, g = 1, v = "human-male", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Ты набираешься знаний и опыта, юный путник." }, { 3.05, "Ты готов приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?" }, { 9.39, "Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда." }, { 14.86, "У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир." } }, f = { { 0.00, "Ты набираешься знаний и опыта, юная путница." }, { 3.15, "Ты готова приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?" }, { 9.64, "Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда." }, { 15.19, "У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир." } } } } }, t = { d = 8.3, v = "human-female#47", n = { x = 91 }, c = { x = { { 0.00, "У меня есть для тебя задание." }, { 2.15, "Да-да, прямо здесь, в квартале магов." }, { 4.88, "Слушай внимательно, не будем терять время даром." } } } } },
    [1920] = { d = 26.6, v = "human-female#47", n = { x = 347 }, c = { x = { { 0.00, "Сообщают о беспорядках в таверне \"Синий отшельник\", что в квартале магов." }, { 4.71, "Там бродят странные невидимые существа, чувствую, там образовался провал Маны." }, { 9.77, "Отправляйся туда и поймай этих тварей." }, { 12.33, "Чтобы они стали видимыми, воспользуйся заклятьем Проявления, одолей их и посади в шкатулки-духоловки." }, { 18.90, "Как только наберёшь достаточно этих тварей, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием." } } }, t = { d = 11.4, g = 1, v = "human-female#47", n = { m = 127, f = 126 }, c = { m = { { 0.00, "Ну ты молодец!" }, { 1.04, "Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир." }, { 7.75, "Ты приносишь сообществу магов всё больше пользы." } }, f = { { 0.00, "Ну ты умница!" }, { 1.00, "Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир." }, { 7.89, "Ты приносишь сообществу магов всё больше пользы." } } } } },
    [1921] = { d = 34.7, v = "human-female#47", n = { x = 417 }, c = { x = { { 0.00, "За верную службу своим собратьям-магам тебе полагается одеяние волшебника." }, { 5.21, "Его вполне может сшить Уинн Ларсон, если ты принесёшь ей всё необходимое." }, { 10.24, "Само одеяние шьётся из льна, который легко найти, но кроме него понадобятся заряженные самоцветы Расселины, а их добывают исключительно в Руднике у Серебряного ручейка у озера Лок Модан." }, { 22.95, "Горняки дворфов не смогли забрать их, и они лежат в ящиках по всему руднику." }, { 28.29, "Набери льна, добудь самоцветы и принеси их Уинн Ларсон в суконную лавку Ларсона в район магов." } } }, t = { d = 10.7, v = "human-female#111", n = { x = 107 }, c = { x = { { 0.00, "Да, превосходный лён." }, { 1.70, "Из него выйдет отличная ряса." }, { 4.22, "А после того, как я разошью её самоцветами, получится настоящее одеяние для мага!" } } } } },
    [1938] = { d = 33.1, v = "human-male", n = { x = 345 }, c = { x = { { 0.00, "Давным-давно в этой башне жили три мага, и один из них поддался искушению и занялся тёмными искусствами." }, { 8.05, "Его уговаривали отказаться от чёрной магии, но тщетно." }, { 12.26, "И он был изгнан." }, { 13.52, "Новое пристанище изгнанного мага – башня Илгалара в Красногорье." }, { 18.63, "Он унёс с собой ценную книгу – Трактат Ура по тёмной магии." }, { 23.25, "Мы, маги Штормграда, хотим вернуть себе эту книгу." }, { 27.32, "Отправляйся в башню Илгалара, найди этот фолиант в библиотеке и принеси мне." } } }, t = { d = 12.6, v = "human-male", n = { x = 146 }, c = { x = { { 0.00, "Я опасался, что Моргант спрятал книгу где-то ещё или же нашёл способ открыть её и прочесть." }, { 6.36, "Хорошо, что он не успел, и что все печати, наложенные на этот трактат, сохранились в целости." } } } } },
    [1939] = { d = 18.5, v = "gnome-female#41", n = { x = 212 }, c = { x = { { 0.00, "С тобой хочет поговорить верховный колдун Андромат." }, { 3.79, "Он находится на верхнем этаже Башни магов, в квартале магов Штормграда." }, { 9.02, "Обязательно поговори с ним, ведь Андромат – один из самых могущественных магов за пределами Даларана." }, { 16.27, "Его совет стоит десяти других." } } }, npc = { [5497] = { d = 17.4, v = "human-female#47", n = { x = 212 }, c = { x = { { 0.00, "С тобой хочет поговорить верховный колдун Андромат." }, { 3.58, "Он находится на верхнем этаже Башни магов, в квартале магов Штормграда." }, { 8.51, "Обязательно поговори с ним, ведь Андромат – один из самых могущественных магов за пределами Даларана." }, { 15.36, "Его совет стоит десяти других." } } } } }, t = { d = 6.0, v = "human-male", n = { x = 64 }, c = { x = { { 0.00, "Привет тебе." }, { 1.01, "Рад тебя видеть." }, { 2.30, "Надеюсь, у тебя найдётся время выслушать старика..." } } } } },
    [1940] = { d = 33.5, v = "human-male", n = { x = 400 }, c = { x = { { 0.00, "Пожалуй, следует наградить тебя за безупречную службу." }, { 3.80, "Пора тебе обзавестись одеянием, которое пристало носить магу твоего уровня." }, { 9.16, "Если тебе удастся собрать все необходимые материалы, одеяние у тебя будет." }, { 14.40, "Ступай в Сумеречный лес и убей побольше пауков, падальщиков-отшельников." }, { 19.39, "Набери их паутины, только учти, годится лишь самая лучшая." }, { 23.50, "Набрав достаточно паутины, отнеси её Уинн Ларсон, которой принадлежит магазин \"Суконная лавка Ларсона\" в Квартале Магов." }, { 31.92, "Она сошьёт тебе одеяние." } } }, t = { d = 4.1, v = "human-female#111", n = { x = 41 }, c = { x = { { 0.00, "Неплохая паутина." }, { 1.54, "Я немедленно примусь за работу!" } } } } },
    [1941] = { t = { d = 11.2, g = 1, v = "human-female#111", n = { m = 113, f = 114 }, c = { m = { { 0.00, "Вот твоя мантия." }, { 1.30, "Одна из лучших, что я когда-либо делала!" }, { 4.37, "Носи её с гордостью, а когда люди спросят... скажи, что купил её в суконной лавке Ларсона!" } }, f = { { 0.00, "Вот твоя мантия." }, { 1.30, "Одна из лучших, что я когда-либо делала!" }, { 4.38, "Носи её с гордостью, а когда люди спросят... скажи, что купила её в суконной лавке Ларсона!" } } } } },
    [1942] = { t = { d = 18.3, g = 1, v = "human-female#111", n = { m = 189, f = 190 }, c = { m = { { 0.00, "Твоё одеяние готово!" }, { 1.58, "А шёлк, который ты собрал, был такой чудесный... ты ведь не против, что я сделала его чуть покороче, чтобы и мне немного шёлка осталось?" }, { 11.74, "Да шучу я." }, { 12.56, "Сидеть будет отлично — хоть в походе, хоть на званом ужине." }, { 17.10, "Носи на здоровье!" } }, f = { { 0.00, "Твоё одеяние готово!" }, { 1.57, "А шёлк, который ты собрала, был такой чудесный... ты ведь не против, что я сделала его чуть покороче, чтобы и мне немного шёлка осталось?" }, { 11.71, "Да шучу я." }, { 12.53, "Сидеть будет отлично — хоть в походе, хоть на званом ужине." }, { 17.03, "Носи на здоровье!" } } } } },
    [1943] = { d = 7.0, v = "scourge-female#79", n = { x = 64 }, c = { x = { { 0.00, "Магу Дейно нужна твоя помощь." }, { 2.86, "Она живёт в Оргриммаре, в пристанище Темнотерна." } } }, t = { d = 12.2, v = "troll-female", n = { x = 124 }, c = { x = { { 0.00, "Хорошо, что ты здесь." }, { 1.66, "Я хочу дать тебе довольно сложное задание." }, { 5.12, "Оно жизненно важно для всего сообщества магов." }, { 8.93, "Помоги мне, и маги отплатят тебе сторицей." } } } } },
    [1944] = { d = 35.2, v = "troll-female", n = { x = 376 }, c = { x = { { 0.00, "В восточной части Ясеневого леса раскинулся прославленный город Ксавиан." }, { 5.68, "Учёные всех народов слышали легенды о хранимом в нём древнем знании." }, { 10.94, "Говорят, что воды Ксавиана содержат немало магической энергии." }, { 15.85, "Мне нужна проба воды из Ксавиана." }, { 18.52, "Возьми этот сосуд и ступай туда." }, { 21.18, "Набери воды у подножия самого большого водопада и возвращайся ко мне." }, { 26.58, "Соблюдай осторожность – руины древнего города заполонили сатиры, им не нравится, когда в их дела встревают маги." } } }, t = { d = 11.0, v = "troll-female", n = { x = 109 }, c = { x = { { 0.00, "А, отлично." }, { 0.97, "Надеюсь, сатиры Ксавиана тебе не слишком сильно помешали?" }, { 5.82, "Спасибо." }, { 6.56, "Я немедленно займусь изучением пробы воды из Ксавиана." } } } } },
    [1945] = { d = 24.1, v = "troll-female", n = { x = 263 }, c = { x = { { 0.00, "За верную службу тебе полагается новое одеяние, если ты принесёшь все необходимые материалы." }, { 6.94, "Тебе придётся вернуться в Ясеневый лес за локонами волос Смеющихся сестёр – дриад, бродящих возле Приюта в Ночных Лесах." }, { 15.99, "Добыв их волосы, отнеси их Кил'хале, троллю-портному с Перекрёстка, что в Степях." }, { 22.05, "Он-то и сошьёт тебе одеяние." } } }, t = { d = 14.2, v = "troll-male", n = { x = 141 }, c = { x = { { 0.00, "А, из этих волос выйдет отличное одеяние." }, { 3.45, "Жаль, что приходится убивать Смеющихся сестёр ради добычи волос, впрочем, добровольно они их всё равно не отдали бы." }, { 12.85, "Жаль, но не очень." } } } } },
    [1946] = { t = { d = 19.5, v = "troll-male", n = { x = 187 }, c = { x = { { 0.00, "Вот твоё кружево Пустоты." }, { 2.08, "Оно удобное и прочное, и в нём заключена магия волос смеющихся сестёр." }, { 7.87, "Носи на здоровье, а если оно придётся тебе по душе, прошу, скажи об этом Дейно." }, { 14.55, "Она маг, и мне хотелось бы оставаться у неё на хорошем счету..." } } } } },
    [1947] = { d = 25.0, v = "scourge-female#79", n = { x = 250 }, c = { x = { { 0.00, "Пришло время заслужить магический жезл." }, { 3.28, "Для начала поговори с отшельницей из Пылевых топей, человеком по имени Табета." }, { 9.76, "Она живёт в хижине в глубине болота, на западе от Терамора." }, { 14.68, "Её познания велики, и она сможет дать тебе добрый совет." }, { 19.45, "Хижина Табеты находится чуть севернее руин Деревни Каменного Молота." } } }, npc = { [5144] = { d = 23.5, v = "gnome-female#41", n = { x = 250 }, c = { x = { { 0.00, "Пришло время заслужить магический жезл." }, { 3.08, "Для начала поговори с отшельницей из Пылевых топей, человеком по имени Табета." }, { 9.17, "Она живёт в хижине в глубине болота, на западе от Терамора." }, { 13.80, "Её познания велики, и она сможет дать тебе добрый совет." }, { 18.28, "Хижина Табеты находится чуть севернее руин Деревни Каменного Молота." } } } }, [5497] = { d = 21.2, v = "human-female#47", n = { x = 250 }, c = { x = { { 0.00, "Пришло время заслужить магический жезл." }, { 2.78, "Для начала поговори с отшельницей из Пылевых топей, человеком по имени Табета." }, { 8.27, "Она живёт в хижине в глубине болота, на западе от Терамора." }, { 12.44, "Её познания велики, и она сможет дать тебе добрый совет." }, { 16.48, "Хижина Табеты находится чуть севернее руин Деревни Каменного Молота." } } } }, [5885] = { d = 23.1, v = "troll-female", n = { x = 250 }, c = { x = { { 0.00, "Пришло время заслужить магический жезл." }, { 3.03, "Для начала поговори с отшельницей из Пылевых топей, человеком по имени Табета." }, { 9.02, "Она живёт в хижине в глубине болота, на западе от Терамора." }, { 13.56, "Её познания велики, и она сможет дать тебе добрый совет." }, { 17.97, "Хижина Табеты находится чуть севернее руин Деревни Каменного Молота." } } } } }, t = { d = 5.4, v = "human-female#45", n = { x = 57 }, c = { x = { { 0.00, "Тихо!" }, { 0.49, "Не беспокой меня, сейчас очень ответственный момент!" }, { 4.61, "Минуточку..." } } } } },
    [1948] = { d = 25.6, v = "human-female#45", n = { x = 307 }, c = { x = { { 0.00, "Создать жезл мага не так-то просто." }, { 2.48, "Приходится собирать редкие компоненты, да и конструировать его надо так, чтобы он вмещал побольше магической энергии." }, { 10.55, "Собери всё необходимое и принеси мне." }, { 13.10, "Я составила список компонентов и заодно указала, где их искать." }, { 17.91, "Буквально следуй моим указаниям, в противном случае при попытке создать жезл может случиться большая неприятность!" } } }, t = { d = 17.8, g = 1, v = "human-female#45", n = { m = 189, f = 188 }, c = { m = { { 0.00, "Ага!" }, { 0.41, "Тебе удалось найти нефрит и сделать шипастый жезл!" }, { 4.29, "Молодец!" }, { 4.97, "У тебя что, из ушей дым идёт?" }, { 7.15, "Наверное, ты подошёл слишком близко, когда молния била в заготовки." }, { 12.26, "Такое случается." }, { 13.55, "Не расстраивайся, получить удар молнии – хорошая примета!" } }, f = { { 0.00, "Ага!" }, { 0.40, "Тебе удалось найти нефрит и сделать шипастый жезл!" }, { 4.19, "Умница!" }, { 4.79, "У тебя что, из ушей дым идёт?" }, { 6.92, "Наверное, ты подошла слишком близко, когда молния била в заготовки." }, { 11.98, "Такое случается." }, { 13.25, "Не расстраивайся, получить удар молнии – хорошая примета!" } } } } },
    [1949] = { d = 29.0, v = "human-female#45", n = { x = 313 }, c = { x = { { 0.00, "Для создания жезла мне нужно прочитать некоторые разделы одной книги." }, { 5.28, "Называется она \"Ритуалы Силы\", а написал её волхв Тирт." }, { 9.41, "У меня её нет, да и ни в одной библиотеке её не сыскать." }, { 13.54, "Поэтому придётся тебе найти Тирта и взять её у него." }, { 17.47, "Удачи." }, { 18.01, "Когда-то он был великим магом и учёным, но теперь большую часть времени проводит на гоночном поле на Мерцающей равнине, пьёт и играет в азартные игры." } } }, t = { d = 15.0, v = "human-male", n = { x = 160 }, c = { x = { { 0.00, "Что?" }, { 0.34, "Говори громче!" }, { 1.49, "У меня не такой острый слух, как бывало." }, { 4.52, "Надеюсь, ты несёшь мне кружку свежего эля или верные сведения о следующей гонке!" }, { 10.60, "Если нет, проваливай..." }, { 12.35, "А то у меня наготове жезл превращения!" } } } } },
    [1950] = { d = 25.8, v = "human-male", n = { x = 283 }, c = { x = { { 0.00, "Я помогу тебе с книгой, но сначала окажи мне услугу!" }, { 3.85, "Нужная тебе книга заодно и магический сейф." }, { 7.05, "Он открывается особой фразой, и её-то я и забыл!" }, { 10.51, "Обычно мне напоминает помощник, но он куда-то запропал." }, { 14.49, "Если тебе нужна книга, найди моего помощника!" }, { 17.95, "Поспрашивай у зрителей, при удаче кто-то мог его видеть." }, { 22.07, "Притащи его сюда или выбей из него волшебные слова!" } } }, t = { d = 10.3, v = "human-male", n = { x = 99 }, c = { x = { { 0.00, "Ах да, припоминаю…" }, { 1.48, "Я и правда наложил на Джонсона проклятье." }, { 4.87, "Не помню, зачем я это сделал, но так ему и надо, маленькому нахалу!" } } } } },
    [1951] = { d = 22.6, v = "human-male", n = { x = 264 }, c = { x = { { 0.00, "Хм..." }, { 0.37, "Оказывается, книги-то у меня и нет!" }, { 2.79, "Видишь ли, мне пришлось отдать последнюю копию за игорные долги какому-то жрецу..." }, { 8.48, "Одному из Алого ордена." }, { 10.15, "Наверное, он унёс её в монастырь в Тирисфальские леса!" }, { 13.81, "Если тебе так нужна книга, придётся сходить за ней в монастырь." }, { 18.14, "Прости за доставленные неудобства." }, { 20.49, "Я в последнее время сам не свой..." } } }, t = { d = 7.6, v = "human-female#45", n = { x = 82 }, c = { x = { { 0.00, "Вот она!" }, { 0.69, "То что нужно для последнего обряда создания жезла!" }, { 4.53, "Надеюсь, поиски были не слишком сложными?" } } } } },
    [1952] = { d = 3.0, v = "human-female#45", n = { x = 27 }, c = { x = { { 0.00, "Пойду, займусь созданием жезлов." } } }, t = { d = 3.3, v = "human-female#45", n = { x = 28 }, c = { x = { { 0.00, "Ну вот, жезлы готовы." }, { 2.02, "Выбирай любой!" } } } } },
    [1953] = { d = 15.8, v = "scourge-female#79", n = { x = 169 }, c = { x = { { 0.00, "Пришло время поговорить с Табетой... отшельницей из Пылевых топей." }, { 5.31, "Она научит тебя создавать могущественные магические инструменты." }, { 10.47, "Хижина Табеты находится в глубинах Пылевых топей, западнее Терамора." } } }, npc = { [5144] = { d = 15.8, v = "gnome-female#41", n = { x = 169 }, c = { x = { { 0.00, "Пришло время поговорить с Табетой... отшельницей из Пылевых топей." }, { 5.31, "Она научит тебя создавать могущественные магические инструменты." }, { 10.47, "Хижина Табеты находится в глубинах Пылевых топей, западнее Терамора." } } } }, [5497] = { d = 13.2, v = "human-female#47", n = { x = 169 }, c = { x = { { 0.00, "Пришло время поговорить с Табетой... отшельницей из Пылевых топей." }, { 4.43, "Она научит тебя создавать могущественные магические инструменты." }, { 8.73, "Хижина Табеты находится в глубинах Пылевых топей, западнее Терамора." } } } }, [5885] = { d = 14.6, v = "troll-female", n = { x = 169 }, c = { x = { { 0.00, "Пришло время поговорить с Табетой... отшельницей из Пылевых топей." }, { 4.91, "Она научит тебя создавать могущественные магические инструменты." }, { 9.68, "Хижина Табеты находится в глубинах Пылевых топей, западнее Терамора." } } } } }, t = { d = 17.9, v = "human-female#45", n = { x = 159 }, c = { x = { { 0.00, "Ах, да." }, { 0.61, "Тебе нужна сфера или посох?" }, { 3.14, "Ну, хорошо." }, { 4.14, "Я помогу тебе." }, { 5.44, "Впрочем, знай." }, { 6.66, "Это очень опасно и может привести к твоей гибели." }, { 11.03, "Или моей гибели." }, { 12.56, "В общем, кому-то умереть придётся…" }, { 15.47, "Будем надеяться, что не нам, а?" } } } } },
    [1954] = { d = 24.7, v = "human-female#45", n = { x = 288 }, c = { x = { { 0.00, "Первым делом тебе нужно заполучить сферу силы." }, { 3.44, "У чернокнижников из клана Пылающего Клинка очень подходящие сферы..." }, { 8.29, "Жаль, что в каждой из них заключён демон!" }, { 11.09, "Но это поправимо, и очень даже." }, { 13.39, "Отправляйся в Пустоши и отбери сферу подземного огня у призывателя из клана Пылающего Клинка." }, { 20.02, "Призыватели живут на поле Маннорок." }, { 22.57, "Как получишь сферу, возвращайся." } } }, t = { d = 17.1, v = "human-female#45", n = { x = 182 }, c = { x = { { 0.00, "Ага, недурная сфера." }, { 1.64, "Не в том смысле недурная, как охлаждённая вода с соком в жаркий день." }, { 6.78, "Более того, она вовсе НЕ недурная, если посмотреть повнимательнее." }, { 11.92, "Да не вода, сфера!" }, { 13.36, "Сосредоточься!" }, { 14.46, "Иначе с этим заданием не справиться!" } } } } },
    [1955] = { d = 28.7, v = "human-female#45", n = { x = 332 }, c = { x = { { 0.00, "У нас есть сфера призывателя, остаётся изгнать из неё демона." }, { 4.19, "С этим я легко справлюсь." }, { 6.03, "Тебе придётся куда труднее." }, { 7.99, "Как только демон изойдёт из сферы, убей его." }, { 11.16, "Главное – не медлить." }, { 12.69, "Если ты провозишься слишком долго, он вернётся в сферу и нам придётся начать сначала!" }, { 18.59, "Готовься к схватке." }, { 19.98, "Вспомни самые сильные заклинания и держи под рукой зелья." }, { 24.11, "Если у тебя есть друг, можешь позвать его." }, { 27.15, "Сражение будет нелёгким." } } }, t = { d = 28.9, v = "human-female#45", n = { x = 313 }, c = { x = { { 0.00, "Великолепно." }, { 0.96, "Тебе удалось преподать этому демону урок, который он надолго запомнит." }, { 6.42, "Теперь он трижды подумает, прежде чем вновь сунуться в наш мир." }, { 11.13, "Однако если это произойдёт, единственной целью демона будет найти того дерзкого смертного, что одолел его когда-то." }, { 20.01, "Скорее всего, он вернётся с приятелями." }, { 22.95, "Огромными, жуткими приятелями, жаждущими твоей крови." }, { 27.05, "Ну что, тебе уже страшно?" } } } } },
    [1956] = { d = 28.6, v = "human-female#45", n = { x = 318 }, c = { x = { { 0.00, "Демон уничтожен, остаётся завладеть источником энергии." }, { 4.04, "К сожалению, самые лучшие источники энергии – старые, и заполучить их нелегко." }, { 9.81, "Судьба любит над нами подшутить, а?" }, { 12.46, "Итак, тебе придётся отправиться в Ульдаман и победить тамошнего обсидианового часового." }, { 18.83, "Он большой и сильный, а уж какой у него источник энергии!" }, { 23.07, "Удачи тебе." }, { 24.00, "Ну, а если она от тебя отвернётся... приятно было познакомиться." } } }, t = { d = 27.0, g = 1, v = "human-female#45", n = { m = 293, f = 293 }, c = { m = { { 0.00, "Ты сделал это?" }, { 1.10, "Молодец." }, { 1.74, "Я общалась с некоторыми моими коллегами и когда я случайно назвала твоё имя, то они сказали: \"Да, мы его знаем, он не поддаётся стрессу, даже в критических ситуациях\"." }, { 13.64, "Но когда я сказала, что послала тебя в Ульдаман против обсидианового стражника, они не поверили, что ты выполнишь задачу." }, { 22.29, "А я сказала им – вот увидите!" }, { 24.36, "Что ж, мы им показали, не так ли?" } }, f = { { 0.00, "Ты сделала это?" }, { 1.19, "Умница." }, { 1.78, "Я общалась с некоторыми моими коллегами и когда я случайно назвала твоё имя, то они сказали: \"Да, мы её знаем, она не поддаётся стрессу, даже в критических ситуациях\"." }, { 13.92, "Но когда я сказала, что послала тебя в Ульдаман против обсидианового стражника, они не поверили, что ты выполнишь задачу." }, { 22.76, "А я сказала им – вот увидите!" }, { 24.88, "Что ж, мы им показали, не так ли?" } } } } },
    [1957] = { d = 30.8, v = "human-female#45", n = { x = 343 }, c = { x = { { 0.00, "Мы почти закончили, осталось самое опасное." }, { 3.22, "Нужно вдохнуть силу в пустую сферу призывателя." }, { 6.77, "Для этого придётся обуздать энергию провала Маны." }, { 10.38, "Я произнесу заклинание, оно временно создаст нужный нам провал, из которого хлынут твари, волноловы маны." }, { 18.13, "Тебе придётся одолеть их, и тогда я смогу собрать воедино их силу." }, { 23.00, "Твоя задача – убить достаточно волноловов маны, пока провал открыт, а я уж соберу всю энергию в твою сферу." } } }, t = { d = 10.3, g = 1, v = "human-female#45", n = { m = 97, f = 98 }, c = { m = { { 0.00, "Надо же, ты справился!" }, { 1.84, "Я в тебе не сомневалась!" }, { 3.84, "Ну ладно, чуть-чуть сомневалась, даже не чуть-чуть..." }, { 8.19, "Но не так уж сильно." }, { 9.81, "Честно." } }, f = { { 0.00, "Надо же, ты справилась!" }, { 1.83, "Я в тебе не сомневалась!" }, { 3.73, "Ну ладно, чуть-чуть сомневалась, даже не чуть-чуть..." }, { 7.89, "Но не так уж сильно." }, { 9.44, "Честно." } } } } },
    [1958] = { t = { d = 16.9, g = 1, v = "human-female#45", n = { m = 172, f = 173 }, c = { m = { { 0.00, "Ты можешь гордиться собой." }, { 2.05, "Многие маги пали от рук тех созданий, с которыми ты сразился." }, { 6.68, "Небесная сфера готова." }, { 8.46, "А если хочешь, я могу закрепить её на посохе." }, { 11.93, "Решать тебе." }, { 12.96, "Я бы выбрала сферу, но кто я такая, чтобы судить?" } }, f = { { 0.00, "Ты можешь гордиться собой." }, { 2.08, "Многие маги пали от рук тех созданий, с которыми ты сразилась." }, { 6.85, "Небесная сфера готова." }, { 8.65, "А если хочешь, я могу закрепить её на посохе." }, { 12.18, "Решать тебе." }, { 13.22, "Я бы выбрала сферу, но кто я такая, чтобы судить?" } } } } },
    [1959] = { d = 17.1, v = "scourge-male#83", n = { x = 192 }, c = { x = { { 0.00, "Маги Подгорода заметили в городе выплеск магической энергии и обратились к чародеям Орды с просьбой выяснить, что же происходит." }, { 9.69, "Подробности тебе расскажет Анастасия Хартвелл." }, { 13.24, "Поговори с ней, она живёт в Квартале Магов Подгорода." } } }, npc = { [7311] = { d = 16.5, v = "troll-male", n = { x = 192 }, c = { x = { { 0.00, "Маги Подгорода заметили в городе выплеск магической энергии и обратились к чародеям Орды с просьбой выяснить, что же происходит." }, { 9.30, "Подробности тебе расскажет Анастасия Хартвелл." }, { 12.73, "Поговори с ней, она живёт в Квартале Магов Подгорода." } } } } }, t = { d = 16.4, v = "scourge-female#79", n = { x = 155 }, c = { x = { { 0.00, "Это правда." }, { 1.08, "В нашем городе произошёл выплеск магической энергии." }, { 5.54, "Мы не поняли, что именно произошло, и даже к добру это или к худу." }, { 11.32, "Не хватает информации…" }, { 13.25, "Что подводит нас к разговору о задании." } } } } },
    [1960] = { d = 33.6, v = "scourge-female#79", n = { x = 346 }, c = { x = { { 0.00, "В лавке алхимика Алжернона, что в Районе Фармацевтов, происходит что-то странное." }, { 6.68, "Там бродят странные невидимые существа, сотканные из магической энергии." }, { 12.61, "Возьми у меня за спиной шкатулки-духоловки и свиток с нужным заклинанием." }, { 18.69, "Воспользуйся свитком в лавке, подчини этих существ и загони их в шкатулки." }, { 24.85, "Как только наберёшь достаточно, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием." } } }, t = { d = 27.1, v = "scourge-female#79", n = { x = 273 }, c = { x = { { 0.00, "Отлично." }, { 0.75, "Лучшие умы Подгорода займутся изучением невидимых тварей." }, { 5.65, "Мы выясним, откуда они взялись в нашем городе." }, { 9.64, "Если дело в возникновении провала Маны, потребуется определить, случайно он возник или нет." }, { 17.33, "Если не случайно, а в результате действий враждебных сил, нам придётся готовиться к появлению более серьёзных противников." } } } } },
    [1961] = { d = 34.2, v = "scourge-female#79", n = { x = 376 }, c = { x = { { 0.00, "Тебе пора обзавестись первым облачением мага." }, { 3.56, "Одеяние – знак твоего особого положения, свидетельство твоего достоинства." }, { 9.18, "Для создания нужного одеяния тебе понадобятся самоцветы маны от даларанских магов из Серебряного бора." }, { 16.99, "Они верят примерно в то же, во что и мы, поэтому убивать их нехорошо, но раз они не могут противостоять нам, значит жизни они не заслуживают." }, { 27.61, "Отнеси камни и несколько кусков льна Джозефу Грегориану в суконную лавку Квартала Магов." } } }, t = { d = 11.0, v = "scourge-male", n = { x = 106 }, c = { x = { { 0.00, "Отличный материал." }, { 1.61, "Оценить качество самоцветов я не могу, но вскоре мы узнаем, подходят ли они для создания одеяний из чароткани..." } } } } },
    [1962] = { t = { d = 4.2, v = "scourge-male", n = { x = 28 }, c = { x = { { 0.00, "Вот твои одеяния." }, { 2.22, "Носи на здоровье." } } }, npc = { [11049] = { d = 3.7, v = "scourge-female#80", n = { x = 28 }, c = { x = { { 0.00, "Вот твои одеяния." }, { 1.93, "Носи на здоровье." } } } } } } },
    [1963] = { d = 29.2, v = "orc-male#60", n = { x = 293 }, c = { x = { { 0.00, "Вождь слишком хитрит и осторожничает." }, { 3.04, "Он не хочет пускать в ход всю мощь Орды." }, { 6.30, "Изувеченная Длань вернёт Орде былую гордость!" }, { 10.01, "Мы тайно копим силы и исподтишка наносим удары неосторожным врагам." }, { 15.64, "Докажи свою доблесть, выполни моё задание!" }, { 19.20, "Тролль по имени Тазан торгует с пиратами близ Кабестана." }, { 23.79, "У него есть нужные мне сведения." }, { 26.46, "Убей его и принеси мне его сумку." } } }, t = { d = 17.0, v = "orc-male#60", n = { x = 158 }, c = { x = { { 0.00, "Хм." }, { 0.31, "Я, конечно, рад слышать, что Тазана больше нет в живых, однако от запертой сумки проку мало." }, { 8.25, "Нам нужно то, что внутри!" }, { 10.41, "Вот и второе задание для того, кто стремится вступить в клан Изувеченной Длани!" } } } } },
    [1978] = { d = 22.5, g = 1, v = "scourge-male#82", n = { m = 195, f = 196 }, c = { m = { { 0.00, "Синдикат?" }, { 0.93, "Никогда бы не подумал." }, { 3.03, "Низко же пали владыки Альтерака после предательства." }, { 8.00, "Лорд Вариматрас будет доволен, и раз именно ты совершил это открытие – тебе и сообщать о нём." }, { 16.67, "Ах да, как я мог забыть?" }, { 18.86, "Добро пожаловать в ряды стражей смерти." } }, f = { { 0.00, "Синдикат?" }, { 0.91, "Никогда бы не подумал." }, { 2.99, "Низко же пали владыки Альтерака после предательства." }, { 7.88, "Лорд Вариматрас будет доволен, и раз именно ты совершила это открытие – тебе и сообщать о нём." }, { 16.51, "Ах да, как я мог забыть?" }, { 18.67, "Добро пожаловать в ряды стражей смерти." } } }, t = { d = 18.7, v = "named/2425", n = { x = 185 }, c = { x = { { 0.00, "Хм, любопытно." }, { 1.23, "Стражи смерти превосходно справились со своими обязанностями." }, { 6.45, "Судя по всему, ты ждёшь благодарности за свои подвиги." }, { 11.05, "Скоро это станет для тебя привычным делом." }, { 14.81, "Стражам смерти не помешают талантливые новички." } } } } },
    [1998] = { d = 36.8, g = 1, v = "scourge-male#82", n = { m = 360, f = 361 }, c = { m = { { 0.00, "Лорд Вариматрас сообщил мне о грозящей Отрёкшимся опасности, с которой следует немедленно разобраться." }, { 7.86, "Во всём виноват Фенвик Татрос, вождь нежити, поселившейся в Серебряном бору." }, { 13.80, "Я немедленно вспомнил о тебе, и сразу понял, кому следует доверить это задание." }, { 20.17, "Ты не обделён талантами и выполнишь поручение безукоризненно." }, { 24.84, "По последним сведениям от стражей смерти, Татроса видели неподалёку от разрушенной пристани озера Лордамер." } }, f = { { 0.00, "Лорд Вариматрас сообщил мне о грозящей Отрёкшимся опасности, с которой следует немедленно разобраться." }, { 8.31, "Во всём виноват Фенвик Татрос, вождь нежити, поселившейся в Серебряном бору." }, { 14.60, "Я немедленно вспомнил о тебе, и сразу понял, кому следует доверить это задание." }, { 21.34, "Ты не обделена талантами и выполнишь поручение безукоризненно." }, { 26.44, "По последним сведениям от стражей смерти, Татроса видели неподалёку от разрушенной пристани озера Лордамер." } } }, t = { d = 11.8, g = 1, v = "scourge-male#82", n = { m = 95, f = 96 }, c = { m = { { 0.00, "Прекрасно." }, { 1.14, "Ты оказался достойным помощником, а посему настало время продолжить твоё обучение тёмным искусствам." } }, f = { { 0.00, "Прекрасно." }, { 1.16, "Ты оказалась достойным помощником, а посему настало время продолжить твоё обучение тёмным искусствам." } } } } },
    [1999] = { d = 38.5, v = "scourge-male#82", n = { x = 388 }, c = { x = { { 0.00, "Маги братства Кирин-Тора в Янтарной Мельнице хранят важные документы, касающиеся положения дел в Даларане." }, { 8.92, "Эти сведения удалось вытянуть из одного пленника." }, { 13.16, "Лорд Вариматрас поручил стражам смерти добыть эти документы." }, { 18.30, "Честь выполнить это задание выпала тебе." }, { 21.78, "Для задания понадобится кое-какое снаряжение и умение вскрывать замки." }, { 27.75, "Поговори с Эстеллой Джендри, она поставляет нам обмундирование." }, { 33.04, "Попроси у неё набор инструментов, перед тем как отправляться в путь." } } }, t = { d = 15.7, g = 1, v = "scourge-male#82", n = { m = 131, f = 131 }, c = { m = { { 0.00, "Прекрасно." }, { 1.05, "Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал." }, { 8.41, "Вижу, я был прав, положившись на тебя." }, { 12.08, "Поверь, мальчик мой, ты далеко пойдёшь." } }, f = { { 0.00, "Прекрасно." }, { 1.03, "Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал." }, { 8.23, "Вижу, я был прав, положившись на тебя." }, { 11.83, "Поверь, девочка моя, ты далеко пойдёшь." } } } } },
    [2038] = { d = 19.3, v = "gnome-male", n = { x = 222 }, c = { x = { { 0.00, "Мало того, что они вторглись в наши края, эти трогги атаковали меня с ближайшего острова и украли мои инструменты и особую взрывчатку – сорвиголовку Покрышкинса." }, { 11.88, "Без вертолёта и взрывчатки движению не обойтись!" }, { 15.29, "Верни мне инструменты и отыщи сорвиголовку." }, { 18.44, "За Гномреган!" } } }, t = { d = 8.0, g = 1, v = "gnome-male", n = { m = 80, f = 81 }, c = { m = { { 0.00, "Ты оказал движению огромную услугу." }, { 3.02, "Скоро трогги и лепрогномы узнают, что такое воздушная атака!" } }, f = { { 0.00, "Ты оказала движению огромную услугу." }, { 3.04, "Скоро трогги и лепрогномы узнают, что такое воздушная атака!" } } } } },
    [2039] = { d = 18.3, v = "gnome-male", n = { x = 227 }, c = { x = { { 0.00, "Мы потеряли связь с Бинглзом!" }, { 1.93, "Он был отправлен в разведывательный полёт над Гномреганом, и уже неделю от него нет никаких известий." }, { 8.57, "Я знаю только то, что он отправился в разведку и потерпел крушение." }, { 13.03, "Последний раз его видели над озером Лок." }, { 15.75, "Возможно, ты сможешь выяснить, что с ним." } } }, t = { d = 13.8, v = "gnome-male", n = { x = 129 }, c = { x = { { 0.00, "Значит, Гноарн сомневается во мне как в разведчике?" }, { 4.24, "Интересно, почему..." }, { 5.97, "Ладно, не берите в голову, мне нужна ваша помощь!" }, { 10.21, "Нет!" }, { 10.59, "Ваша помощь нужна нашему общему делу!" } } } } },
    [2040] = { d = 29.3, v = "gnome-female", n = { x = 311 }, c = { x = { { 0.00, "Гномреган захватили трогги!" }, { 2.23, "Ситуация крайне тяжёлая, но, быть может, вы сможете помочь." }, { 6.89, "Глубоко под землёй, в Мёртвых копях, находится действующий гоблинский резак." }, { 12.85, "Найдите его и принесите его источник питания." }, { 16.58, "С его помощью мы сможем обеспечить наши автогиробуроройки достаточной энергией, чтобы пробиться через каменные границы Гномрегана и открыть дорогу армии гномов!" } } }, t = { d = 7.2, v = "gnome-female", n = { x = 70 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.49, "Благодаря вам день освобождения Гномрегана приблизился ещё на шаг!" } } } } },
    [2041] = { d = 17.6, v = "gnome-male", n = { x = 197 }, c = { x = { { 0.00, "Возможно..." }, { 0.88, "Возможно, вы поможете нам в битве за Гномреган." }, { 4.39, "В Штормграде вы найдёте командира нашей подземной штурмовой группы, Шони Молшунью." }, { 10.53, "Шони нужна помощь в сооружении автогиробуророек." }, { 14.17, "Вы найдёте её среди дворфов в Штормграде." }, { 17.21, "Удачи." } } }, t = { d = 3.2, v = "gnome-female", n = { x = 39 }, c = { x = { { 0.00, "Вы с известиями от центрального командования?" } } } } },
    [2078] = { d = 17.8, g = 1, v = "gnome-male", n = { m = 201, f = 201 }, c = { m = { { 0.00, "Эй, сухопутное создание, нужно, чтоб ты нашёл моего первого помощника." }, { 4.99, "Берёшь этот ключ, вставляешь ему в башку и ведёшь сюда, чтобы он опять служил своему кэпу." }, { 11.54, "Этим мурлокам и их главарю не шибко понравится, когда ими займётся мой первый помощник!" } }, f = { { 0.00, "Эй, сухопутное создание, нужно, чтоб ты нашла моего первого помощника." }, { 5.06, "Берёшь этот ключ, вставляешь ему в башку и ведёшь сюда, чтобы он опять служил своему кэпу." }, { 11.61, "Этим мурлокам и их главарю не шибко понравится, когда ими займётся мой первый помощник!" } } }, t = { d = 11.0, v = "gnome-male", n = { x = 120 }, c = { x = { { 0.00, "Да-а-а..." }, { 0.70, "А ты, оказывается, больше, чем желторотая собачья акула, крыса ты сухопутная." }, { 6.10, "Кэп тебя, может, даже пустит палубу драить, если так и дальше пойдёт..." } } } } },
    [2098] = { d = 35.4, v = "gnome-male", n = { x = 401 }, c = { x = { { 0.00, "Жизнь пирата нелегка, сухопутное ты создание." }, { 3.25, "Это не только грабежи да пьянки!" }, { 5.66, "Увы, мой корабль затонул совсем рядом с берегом из-за этих мерзких жесткозубов." }, { 11.51, "Первое, что мне нужно, – это чтоб мой первый помощник был в рабочем состоянии!" }, { 17.11, "Когда меня вынесло на берег, ключ от моего первого помощника сломался от удара о скалы, и его части растащили обитающие на Тёмном Берегу звери." }, { 27.52, "Краем глаза я заметил разъярённых крабов, свирепых лесных долгоходов и мурлоков, обшаривающих останки корабля..." } } }, t = { d = 14.5, g = 1, v = "gnome-male", n = { m = 144, f = 145 }, c = { m = { { 0.00, "Ах ты ж, акула собачья!" }, { 1.85, "Тебе удалось всё найти!" }, { 3.76, "Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждёт!" }, { 10.94, "А кстати, ты не видел моего первого помощника?" } }, f = { { 0.00, "Ах ты ж, акула собачья!" }, { 1.84, "Тебе удалось всё найти!" }, { 3.75, "Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждёт!" }, { 10.88, "А кстати, ты не видела моего первого помощника?" } } } } },
    [2118] = { d = 35.8, v = "nightelf-male#59", n = { x = 411 }, c = { x = { { 0.00, "Болезнь расползается по Тёмному Берегу, захватывая сознания и тела всех, до кого добирается." }, { 6.58, "На колючешерстных медведей она подействовала особенно жестоко." }, { 11.55, "Некогда благородные звери стали инструментами разрушения, бешеными и неистовыми." }, { 17.35, "Возможно, у меня есть средство от этой напасти." }, { 20.81, "Отнеси в лес эту ловушку и положи её на землю." }, { 24.19, "Любой бешеный колючешёрстный медведь, попавший в неё, станет на короткий период времени послушным." }, { 31.23, "В таком состоянии он будет следовать за тобой." }, { 34.62, "Приведи его сюда." } } }, t = { d = 4.7, v = "nightelf-male#59", n = { x = 52 }, c = { x = { { 0.00, "Наша работа только начинается." }, { 2.43, "Вы готовы к следующему заданию?" } } } } },
    [2138] = { d = 26.5, v = "nightelf-male#59", n = { x = 309 }, c = { x = { { 0.00, "Как я и боялся, целительное средство не действует." }, { 3.64, "Меня очень печалит, что я вынужден приговаривать к смерти создания природы, но больных колючешёрстных медведей придётся истребить." }, { 13.05, "Возвращайтесь в лес и уничтожьте двадцать бешеных колючешёрстных медведей." }, { 18.35, "Скорее всего, это не остановит зло, но хотя бы ненадолго замедлит наступление заразы на наш лес и его обитателей." } } }, t = { d = 13.2, v = "nightelf-male#59", n = { x = 146 }, c = { x = { { 0.00, "Вы сослужили большую службу Аубердину, но ваша работа на этом не закончена." }, { 5.69, "Отдохните, а затем возвращайтесь ко мне." }, { 8.67, "...И, укрепитесь духом и разумом для дальнейшего кровопролития." } } } } },
    [2139] = { d = 36.0, g = 1, v = "nightelf-male#59", n = { m = 401, f = 403 }, c = { m = { { 0.00, "За выживание нашего народа и безопасность наших земель мы платим высокую цену." }, { 5.69, "Ты пролил кровь слуг природы, сразил множество больных зверей." }, { 10.15, "Народ Аубердина в долгу перед тобой, поскольку боль истерзанного леса немного утихла – пусть и ненадолго." }, { 17.71, "У меня есть для тебя последнее задание, но предупреждаю: тебе снова нужно будет убивать." }, { 24.10, "Надеюсь, это последний раз, когда мне приходится побуждать тебя к этому." }, { 29.34, "В пещере к северо-востоку отсюда близ Башал'Арана живёт мать-медведица." }, { 34.38, "Убей её." } }, f = { { 0.00, "За выживание нашего народа и безопасность наших земель мы платим высокую цену." }, { 5.83, "Ты пролила кровь слуг природы, сразила множество больных зверей." }, { 10.54, "Народ Аубердина в долгу перед тобой, поскольку боль истерзанного леса немного утихла – пусть и ненадолго." }, { 18.30, "У меня есть для тебя последнее задание, но предупреждаю: тебе снова нужно будет убивать." }, { 24.86, "Надеюсь, это последний раз, когда мне приходится побуждать тебя к этому." }, { 30.23, "В пещере к северо-востоку отсюда близ Башал'Арана живёт мать-медведица." }, { 35.40, "Убей её." } } }, t = { d = 27.8, v = "nightelf-male#59", n = { x = 317 }, c = { x = { { 0.00, "Вы с честью и мужеством сражались на благо Аубердина." }, { 3.78, "В наших измученных войной землях смерть и отчаяние стали нормой." }, { 8.40, "Многие уже не пытаются встретить лицом к лицу испытания в нашем новом доме, их выбор – либо скрываться в своих жилищах, либо бежать в более укреплённые и безопасные земли Альянса." }, { 21.30, "Спасибо вам." }, { 22.20, "Может быть, вскоре мы с вами будем плечом к плечу биться против другого врага." } } } } },
    [2158] = { d = 23.4, v = "human-male", n = { x = 269 }, c = { x = { { 0.00, "Каждому путнику рано или поздно нужно отдохнуть и восстановить силы – а для этого нет места лучше, чем таверна \"Гордость льва\"." }, { 8.77, "Там всем заправляет мой лучший друг Фарли." }, { 11.61, "Скажи ему, что ты от меня – может, он даже скидки тебе даст на еду и выпивку." }, { 16.98, "Найти \"Гордость льва\" несложно: нужно просто идти по дороге на юг." }, { 21.54, "Не бойся, с пути не собьёшься!" } } }, t = { d = 12.9, v = "human-male", n = { x = 133 }, c = { x = { { 0.00, "Наш девиз - покой и отдых для всех усталых и продрогших!" }, { 4.16, "Прошу, садись у огня, отдохни с дороги." }, { 7.19, "Хочешь - отведай, чем у нас кормят, да и выпить чего-нибудь тебе не помешает..." } } } } },
    [2159] = { d = 25.2, g = 1, v = "nightelf-male#54", n = { m = 262, f = 262 }, c = { m = { { 0.00, "Привет тебе, юный герой." }, { 1.95, "Не окажешь ли ты мне услугу?" }, { 4.03, "У меня тут свёрток с травами, который надо доставить в Доланаар." }, { 8.81, "Но я ещё не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться." }, { 15.80, "Не отнесёшь ли ты посылку?" }, { 17.68, "Её надо доставить Кельдамиру – хозяину таверны в Доланааре." }, { 22.12, "Таверна стоит у дороги к югу отсюда." } }, f = { { 0.00, "Привет тебе, юная героиня." }, { 2.11, "Не окажешь ли ты мне услугу?" }, { 4.21, "У меня тут свёрток с травами, который надо доставить в Доланаар." }, { 9.04, "Но я ещё не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться." }, { 16.11, "Не отнесёшь ли ты посылку?" }, { 18.01, "Её надо доставить Кельдамиру – хозяину таверны в Доланааре." }, { 22.49, "Таверна стоит у дороги к югу отсюда." } } }, t = { d = 29.8, v = "nightelf-male#121", n = { x = 342 }, c = { x = { { 0.00, "Ах да, травы из Тенистой долины!" }, { 2.29, "Жаль, что Портанниус сам не смог её доставить - нам с ним много что надо обсудить." }, { 7.89, "Но я всё равно рад получить эту посылку и познакомиться с тобой." }, { 12.41, "Покуда ты здесь - чувствуй себя как дома." }, { 15.33, "Герои должны быть крепки телом и духом, так что если выпадает возможность отдохнуть и подлечиться, надо ей пользоваться!" }, { 23.80, "Забота о теле и духе только приблизит тебя к победе!" }, { 27.61, "Так что располагайся поудобнее..." } } } } },
    [2160] = { d = 38.5, v = "gnome-male", n = { x = 453 }, c = { x = { { 0.00, "Похоже, тебе не впервой путешествовать, и трудности в дороге тебя не пугают." }, { 5.20, "Что ж, раз уж ты всё равно собираешься в путь, может, заодно прихватишь и посылочку в Каранос?" }, { 11.45, "Её нужно отдать хозяину таверны." }, { 13.71, "Ты ведь собираешься заглянуть в таверну, верно?" }, { 16.89, "После всего, что тебя ожидает в пути – а ожидает тебя много чего, уж можешь мне поверить, – ты наверняка захочешь отдохнуть и перевести дух." }, { 26.44, "Так вот, я тебя и прошу – передай кое-что помощнику хозяина; его зовут Таннок Молот Стужи." }, { 32.68, "Я сам в одиночку до Караноса не доберусь, а патруля горных пехотинцев ещё ждать и ждать..." } } }, t = { d = 20.3, v = "dwarf-male", n = { x = 231 }, c = { x = { { 0.00, "О, гляди-ка, Ручник Ржавозубчик всё-таки прислал припасы!" }, { 4.07, "Я уж начинал беспокоиться: с тех пор, как тут поселились трогги, из Старой Наковальни вести почти и не доходят." }, { 11.88, "Я тебе очень благодарен, просто словами не передать, как." }, { 16.01, "Ты тут располагайся, будь как дома, дорога-то была не из лёгких!" } } } } },
    [2161] = { d = 46.9, g = 1, v = "orc-male", n = { m = 441, f = 447 }, c = { m = { { 0.00, "Извини..." }, { 0.81, "Ты не мог бы мне помочь?" }, { 2.71, "У меня тут тяжеленная сумка с припасами." }, { 6.01, "Я шёл по дороге, на меня нападали и скорпиды, и пауки, и ещё более страшные твари!" }, { 12.68, "Я нёс припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать." }, { 20.00, "Но оказалось, что припасы им не нужны!" }, { 23.08, "И вот мне придётся тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут..." }, { 31.73, "Не мог бы ты отнести посылку вместо меня?" }, { 35.10, "Я ведь простой батрак, а ты-то – герой!" }, { 38.32, "Ты, небось, ничего не боишься..." }, { 40.96, "Отнеси эту сумку хозяину таверны Гроску." }, { 44.40, "Спасибо тебе большое!" } }, f = { { 0.00, "Извини..." }, { 0.81, "Ты не могла бы мне помочь?" }, { 2.94, "У меня тут тяжеленная сумка с припасами." }, { 6.26, "Я шёл по дороге, на меня нападали и скорпиды, и пауки, и ещё более страшные твари!" }, { 12.95, "Я нёс припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать." }, { 20.31, "Но оказалось, что припасы им не нужны!" }, { 23.41, "И вот мне придётся тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут..." }, { 32.09, "Не могла бы ты отнести посылку вместо меня?" }, { 35.70, "Я ведь простой батрак, а ты-то – героиня!" }, { 39.08, "Ты, небось, ничего не боишься..." }, { 41.73, "Отнеси эту сумку хозяину таверны Гроску." }, { 45.19, "Спасибо тебе большое!" } } }, t = { d = 39.0, g = 1, v = "orc-male", n = { m = 372, f = 375 }, c = { m = { { 0.00, "А-а, это припасы, которые Укор понёс в долину Испытаний!" }, { 4.75, "Что, не пригодились?" }, { 6.38, "Ну да, конечно, они любят морить голодом молодых героев вроде тебя." }, { 12.10, "Говорят, будто это закаляет дух!" }, { 14.84, "Спасибо, что принёс припасы обратно." }, { 17.81, "Пусть пока полежат на полочке..." }, { 20.48, "Погоди, не уходи, дай я тебя сначала чем-нибудь угощу!" }, { 25.01, "И не забудь отдохнуть у нас на постоялом дворе." }, { 28.87, "Конечно, ты отважен и готов горы свернуть, но если не отдохнёшь, силёнок не будет, а это не пойдёт на пользу ни тебе, ни Орде!" } }, f = { { 0.00, "А-а, это припасы, которые Укор понёс в долину Испытаний!" }, { 4.72, "Что, не пригодились?" }, { 6.35, "Ну да, конечно, они любят морить голодом молодых героев вроде тебя." }, { 12.03, "Говорят, будто это закаляет дух!" }, { 14.76, "Спасибо, что принесла припасы обратно." }, { 17.94, "Пусть пока полежат на полочке..." }, { 20.59, "Погоди, не уходи, дай я тебя сначала чем-нибудь угощу!" }, { 25.10, "И не забудь отдохнуть у нас на постоялом дворе." }, { 28.93, "Конечно, ты отважна и готова горы свернуть, но если не отдохнёшь, силёнок не будет, а это не пойдёт на пользу ни тебе, ни Орде!" } } } } },
    [2178] = { d = 35.8, v = "nightelf-female#53", n = { x = 410 }, c = { x = { { 0.00, "Чувствуете этот восхитительный аромат?" }, { 2.78, "Это мой секретный рецепт – свежесваренная похлёбка из долгонога." }, { 7.31, "Настоящий деликатес!" }, { 8.80, "Не хотите ли узнать рецепт?" }, { 10.80, "Но прежде, чем я вас научу готовить это блюдо, вы должны доказать мне, что умеете управляться с долгоногами." }, { 18.50, "Нет, я вовсе не жду, что вы пойдёте, приручите себе одного и приедете ко мне на нём верхом!" }, { 24.84, "Но если бы вы могли убить несколько птиц и принести мне их сочного мяса, это, пожалуй, убедило бы меня показать вам, как же готовится похлёбка из долгонога." } } }, t = { d = 5.4, v = "nightelf-female#53", n = { x = 50 }, c = { x = { { 0.00, "Фантастика!" }, { 1.04, "Попробуйте сами и скажите, что вы думаете об этом!" } } } } },
    [2198] = { d = 39.4, v = "narrator", n = { x = 399 }, c = { x = { { 0.00, "Вы нашли потускневшее ожерелье, хотя даже то, что оно потускнело, не может исказить искусную, даже отчасти магическую работу создателя." }, { 11.05, "Ожерелье было разрушено, поскольку в собранном виде в нём явно не хватает трёх драгоценных камней." }, { 19.02, "На обратной стороне ожерелья – почти стёршаяся печать Стальгорна." }, { 24.29, "Ниже печати – выгравированы три небольших буквы: \"ТдК\"." }, { 28.76, "Если вы хотите восстановить ожерелье, вы будете должны узнать о его происхождении." }, { 35.49, "Возможно, печать и эти буквы помогут вам в этом." } } }, t = { d = 16.3, v = "gnome-male", n = { x = 173 }, c = { x = { { 0.00, "Да, я – тот ювелир, который создал это ожерелье." }, { 3.64, "Но больше ты из меня ничего клещами не вытянешь." }, { 7.29, "За всё надо платить, приятель, и информация не исключение." }, { 11.61, "Если ты хочешь, чтобы я тебе помог, придётся сначала помочь мне." } } } } },
    [2199] = { d = 33.4, g = 1, v = "gnome-male", n = { m = 383, f = 385 }, c = { m = { { 0.00, "Я прославленный в нашем Стальгорне ювелир!" }, { 2.97, "Ну, был прославленным..." }, { 4.61, "У меня сейчас трудные времена, и всё из-за козней конкурента!" }, { 8.96, "Дурная репутация в нашем ремесле приводит к финансовому краху." }, { 13.38, "И в результате моё доброе, но недавно опороченное имя теперь медного гроша не стоит." }, { 19.31, "Я хочу, чтобы ты принёс мне пять серебряных слитков, чтобы я сумел закончить заказ – первый за целую вечность!" }, { 27.01, "Если ты принесёшь мне серебряные слитки, я отвечу на твои вопросы по поводу ожерелья." } }, f = { { 0.00, "Я прославленный в нашем Стальгорне ювелир!" }, { 3.00, "Ну, был прославленным..." }, { 4.66, "У меня сейчас трудные времена, и всё из-за козней конкурента!" }, { 9.06, "Дурная репутация в нашем ремесле приводит к финансовому краху." }, { 13.53, "И в результате моё доброе, но недавно опороченное имя теперь медного гроша не стоит." }, { 19.53, "Я хочу, чтобы ты принесла мне пять серебряных слитков, чтобы я сумел закончить заказ – первый за целую вечность!" }, { 27.51, "Если ты принесёшь мне серебряные слитки, я отвечу на твои вопросы по поводу ожерелья." } } }, t = { d = 37.8, v = "gnome-male", n = { x = 425 }, c = { x = { { 0.00, "Для меня теперь нет дороже друга, и плевать, что скажут другие... шучу, шучу!" }, { 5.51, "Правда, спасибо тебе огромное!" }, { 7.72, "Итак, ожерелье, которое теперь у тебя, – одно из лучших моих творений, но в нём не хватает трёх драгоценных камней, что помогали удерживать в нём магическую силу." }, { 19.05, "Некоторое время назад я сделал его для одного паладина." }, { 23.03, "Он по личному побуждению отправился в поход, дабы выжечь \"злую скверну\" с раскопа в Бесплодных землях, в месте, называемом Ульдаман." }, { 32.33, "В общем... этот паладин погиб в Ульдамане, и это стало началом моих горестей." } } } } },
    [2200] = { d = 34.5, v = "gnome-male", n = { x = 437 }, c = { x = { { 0.00, "Мой конкурент распустил слухи, что моё ожерелье проклято и что оно-то и сгубило паладина." }, { 5.78, "Нечего и говорить, что покупателей на проклятые ювелирные изделия больше не нашлось." }, { 11.26, "Я предлагаю тебе сделку – найди драгоценные камни, и я восстановлю ожерелье, а ты расскажешь всем, что на моих изделиях НЕТ никакого проклятия!" }, { 20.52, "Попытайся найти разгадку гибели паладина в Ульдамане – может, его тело всё ещё там, ведь он последний владел этим ожерельем!" }, { 28.66, "Когда ты найдёшь камни, воспользуйся вот этим – так ты сможешь связаться со мной в Стальгорне." } } }, t = { d = 27.6, v = "narrator", n = { x = 310 }, c = { x = { { 0.00, "В дневнике говорится, что после больших усилий паладин выяснил, где находятся все три камня:" }, { 6.90, "Рубин спрятан дворфами Кузни Теней на ограждённой завалами территории во время сражения с троггами за контроль над Ульдаманом." }, { 16.31, "Топаз трогги спрятали в вазе, под боком у несколько неожиданных поселенцев Ульдамана – дворфов Альянса!" }, { 24.09, "Наконец, сапфир забрал себе старейшина троггов." } } } } },
    [2201] = { d = 30.6, v = "narrator", n = { x = 346 }, c = { x = { { 0.00, "Дневник паладина даёт, скорее всего, единственную подсказку, о том, где искать камни из ожерелья." }, { 7.08, "Если верить записям паладина, то придётся иметь дело с дворфами из клана Кузни Теней и троггами, борющимися за контроль над раскопками в Ульдамане." }, { 17.87, "Вооружившись этим знанием, отнесись к поискам этих камней серьёзно." }, { 22.83, "Когда ты найдёшь камни, сообщи об этом Талвашу через фиал Видения и следуй полученным от него инструкциям." } } }, t = { d = 26.6, g = 1, v = "gnome-male", n = { x = 292 }, c = { m = { { 0.00, "Ух ты!" }, { 0.46, "Да это и вправду три потерянных камня." }, { 3.26, "Отличная работа!" }, { 4.50, "Но, к сожалению, это ещё не всё." }, { 6.79, "Нет, я не пытаюсь тебя надуть, поверь мне, герой." }, { 10.38, "Дело в особенностях создания магической бижутерии – настоящей магической бижутерии от Талваша де Кисселя!" }, { 17.95, "Для того чтобы создать подобную вещь, нужен большой запас магической энергии, которой в этом ожерелье уже не осталось." } }, f = { { 0.00, "Ух ты!" }, { 0.46, "Да это и вправду три потерянных камня." }, { 3.27, "Отличная работа!" }, { 4.51, "Но, к сожалению, это ещё не всё." }, { 6.79, "Нет, я не пытаюсь тебя надуть, поверь мне, героиня." }, { 10.52, "Дело в особенностях создания магической бижутерии – настоящей магической бижутерии от Талваша де Кисселя!" }, { 18.10, "Для того чтобы создать подобную вещь, нужен большой запас магической энергии, которой в этом ожерелье уже не осталось." } } } } },
    [2202] = { d = 40.4, v = "troll-male#77", n = { x = 432 }, c = { x = { { 0.00, "Мне рассказали о недавно открытом растении, грибе-малиновике." }, { 4.76, "Этот гриб растёт целыми колониями на раскопках Ульдамана, в самой глубине." }, { 10.51, "Наверное, встречается ещё где-то, но мне известно только одно место." }, { 15.83, "Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься." }, { 23.04, "Отыщи эти грибы и принеси мне дюжину." }, { 26.05, "Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнёшь." }, { 32.78, "Если выполнишь моё поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!" } } }, t = { d = 25.8, g = 1, v = "troll-male#77", n = { m = 280, f = 280 }, c = { m = { { 0.00, "Молодец, ты снова показал, на что способен!" }, { 3.28, "Эти грибы очень пригодятся для моих исследований!" }, { 7.11, "А теперь, как я и обещал, можешь насладиться вкусом одного из самых действенных восстановительных составов из моих личных запасов..." }, { 17.10, "Если ты тоже увлекаешься алхимией, мы можем вдобавок поговорить о других делах." }, { 23.18, "В любом случае, благодарю за помощь!" } }, f = { { 0.00, "Умница, ты снова показала, на что способна!" }, { 3.28, "Эти грибы очень пригодятся для моих исследований!" }, { 7.11, "А теперь, как я и обещал, можешь насладиться вкусом одного из самых действенных восстановительных составов из моих личных запасов..." }, { 17.10, "Если ты тоже увлекаешься алхимией, мы можем вдобавок поговорить о других делах." }, { 23.18, "В любом случае, благодарю за помощь!" } } } } },
    [2203] = { d = 36.6, g = 1, v = "troll-male#77", n = { m = 362, f = 364 }, c = { m = { { 0.00, "Ты оказал мне неоценимую помощь, герой." }, { 3.22, "Надо бы в награду дать тебе рецепт эликсира, который ты пробовал..." }, { 8.72, "Но прежде я дам тебе ещё одно опасное задание." }, { 12.53, "Вот моя просьба." }, { 13.92, "В этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опалённого дракона-стража." }, { 23.37, "Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность." }, { 29.37, "Когда наполнишь все три, принеси их мне." }, { 32.60, "Добудь мне кровь дракона, и я отдам тебе рецепт." } }, f = { { 0.00, "Ты оказала мне неоценимую помощь, героиня." }, { 3.43, "Надо бы в награду дать тебе рецепт эликсира, который ты пробовала..." }, { 8.98, "Но прежде я дам тебе ещё одно опасное задание." }, { 12.77, "Вот моя просьба." }, { 14.16, "В этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опалённого дракона-стража." }, { 23.58, "Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность." }, { 29.56, "Когда наполнишь все три, принеси их мне." }, { 32.77, "Добудь мне кровь дракона, и я отдам тебе рецепт." } } }, t = { d = 11.3, g = 1, v = "troll-male#77", n = { m = 98, f = 100 }, c = { m = { { 0.00, "Между нами, алхимиками, говоря, ты просто герой!" }, { 4.30, "Вот, возьми этот рецепт." }, { 6.50, "Пусть он принесёт тебе успех и богатство, как и мне!" } }, f = { { 0.00, "Между нами, алхимиками, говоря, ты просто героиня!" }, { 4.63, "Вот, возьми этот рецепт." }, { 6.90, "Пусть он принесёт тебе успех и богатство, как и мне!" } } } } },
    [2204] = { d = 30.1, v = "gnome-male", n = { x = 359 }, c = { x = { { 0.00, "Тебе понадобится немного \"магической силы\" для ожерелья, и Ульдаман – лучшее место, чтобы её раздобыть." }, { 7.17, "Там бегает множество магических созданий." }, { 10.03, "Поймай самое крупное и злобное, вынь из него источник магической силы и принеси его мне." }, { 16.20, "Я уверен, что смогу вплавить его в ожерелье." }, { 19.32, "Без источника силы, ожерелье починить невозможно." }, { 22.74, "Возвращайся ко мне в Стальгорн, когда раздобудешь что-нибудь подходящее и мы быстро наладим для тебя эту вещь." } } }, t = { d = 26.0, v = "gnome-male", n = { x = 272 }, c = { x = { { 0.00, "Отлично! – Я рад видеть и тебя и этот источник силы в целости и сохранности." }, { 5.88, "Теперь, когда драгоценные камни возвращены на своё место, восстановить само ожерелье, займёт не больше минуты..." }, { 14.46, "Как только я это сделаю, оно станет твоим!" }, { 17.85, "Волнуешься, да? просто дрожишь от нетерпения?" }, { 21.31, "Тааак, на чём я в прошлый раз сосредотачивал фокус заклинания..." } } } } },
    [2205] = { d = 25.4, g = 1, v = "human-female#47", n = { m = 295, f = 295 }, c = { m = { { 0.00, "Значок?" }, { 0.54, "А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам." }, { 5.13, "Ты выглядишь так, что Матиас может принять тебя за торговца сыром." }, { 9.60, "Тебя, детка, вряд ли можно счесть настоящим разбойником." }, { 13.34, "Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена." }, { 18.24, "К делу!" }, { 18.78, "Доставь этот пакет Матиасу: возможно, у него тоже найдётся для тебя пара заданий." }, { 24.33, "Не задерживайся!" } }, f = { { 0.00, "Значок?" }, { 0.55, "А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам." }, { 5.16, "Ты выглядишь так, что Матиас может принять тебя за торговку сыром." }, { 9.66, "Тебя, детка, вряд ли можно счесть настоящим разбойником." }, { 13.43, "Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена." }, { 18.35, "К делу!" }, { 18.90, "Доставь этот пакет Матиасу: возможно, у него тоже найдётся для тебя пара заданий." }, { 24.49, "Не задерживайся!" } } }, t = { d = 17.0, v = "human-male", n = { x = 206 }, c = { x = { { 0.00, "Итак, тебе удалось меня отыскать." }, { 2.38, "Глядя на тебя, я бы сказал, что для тебя это было серьёзным испытанием как физических сил, так и умственных способностей." }, { 10.46, "Ну что, попросить Рензика показать тебе, где здесь постоялый двор, или ты сразу приступишь к работе?" } } } } },
    [2206] = { d = 31.5, v = "human-male", n = { x = 389 }, c = { x = { { 0.00, "Наши полевые агенты сообщают о серьёзной активности Братства Справедливости к югу от Златоземья." }, { 6.38, "В этих донесениях указывается, что братство захватило лагерь Джерода и теперь использует его как перевалочный пункт для переправки больших партий контрабанды из Красногорья в Западный Край." }, { 18.90, "Мне нужно, чтобы вы проникли в доки и добыли мне расписание поставок." }, { 23.53, "Скорее всего, портовой начальник носит его при себе." }, { 27.15, "...и кстати, если вас обнаружат – вы никогда не слышали о ШРУ..." } } }, t = { d = 23.9, v = "human-male", n = { x = 267 }, c = { x = { { 0.00, "Я потрясён..." }, { 0.92, "Потрясён, что Керин наконец-то нашла новобранца, из которого действительно может выйти толк." }, { 7.54, "Возьмите этот клинок." }, { 9.18, "Придёт день, когда ШРУ вновь призовёт вас на службу." }, { 13.11, "Совершенствуйте своё мастерство, пусть глаза ваши будут всегда открыты, а клинок – наточен." }, { 19.74, "Вы не заметите нас, но почувствуете, когда мы будем рядом..." } } } } },
    [2218] = { d = 33.1, v = "dwarf-male", n = { x = 359 }, c = { x = { { 0.00, "Ещё одна заблудшая душа, стало быть, ищет наставничества?" }, { 4.35, "Полагаю, ты хочешь найти смысл жизни – смысл твоей жизни." }, { 8.71, "Я тысячу раз видел, как другие герои искали работу." }, { 12.65, "Что же, сегодня тебе повезло." }, { 14.90, "У Хограла найдётся лекарство для твоего недуга." }, { 18.44, "Вот что ты сделаешь: иди по этой дороге до Стальгорна и там зайди в Заброшенный грот." }, { 24.76, "Как окажешься там, найди воровскую гильдию и переговори с Хальфданом Чернобородом." }, { 30.89, "Он укажет тебе путь к спасению." } } }, t = { d = 17.6, g = 1, v = "dwarf-male", n = { m = 191, f = 193 }, c = { m = { { 0.00, "Стало быть, ты считаешь себя настоящим мерзавцем?" }, { 3.76, "Достойным оказаться среди немногих избранных ребят Чёрной Бороды – стать офицером Тайного Круга?" }, { 11.08, "Только настоящий прохвост так высоко себя ценит!" }, { 14.84, "Таких мы и ищем!" }, { 16.14, "Добро пожаловать!" } }, f = { { 0.00, "Стало быть, ты считаешь себя настоящей мерзавкой?" }, { 3.78, "Достойной оказаться среди немногих избранных ребят Чёрной Бороды – стать офицером Тайного Круга?" }, { 11.14, "Только настоящая прохвостка так высоко себя ценит!" }, { 15.07, "Таких мы и ищем!" }, { 16.37, "Добро пожаловать!" } } } } },
    [2238] = { d = 35.6, g = 1, v = "dwarf-male", n = { m = 393, f = 395 }, c = { m = { { 0.00, "Понимаешь, король выгребает из шахты руду и камни." }, { 3.74, "Таких богатств ни один дворф за десять жизней не увидит." }, { 7.87, "У Тайного Круга есть свои жизненные ценности." }, { 11.22, "И эти ценности – драгоценности." }, { 13.51, "Просекаешь?" }, { 14.36, "Теперь сдаётся нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берём свою долю, – ты улавливаешь нить?" }, { 24.01, "Нам надо, чтобы ты переговорил с Онином Макмолотом в Гномрегане и вернулся с ответом." }, { 30.93, "Этот хитрый дворф спрятался среди прокажённых." }, { 34.28, "Так что поосторожнее." } }, f = { { 0.00, "Понимаешь, король выгребает из шахты руду и камни." }, { 3.69, "Таких богатств ни один дворф за десять жизней не увидит." }, { 7.77, "У Тайного Круга есть свои жизненные ценности." }, { 11.07, "И эти ценности – драгоценности." }, { 13.34, "Просекаешь?" }, { 14.18, "Теперь сдаётся нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берём свою долю, – ты улавливаешь нить?" }, { 23.70, "Нам надо, чтобы ты переговорила с Онином Макмолотом в Гномрегане и вернулась с ответом." }, { 29.91, "Этот хитрый дворф спрятался среди прокажённых." }, { 33.22, "Так что поосторожнее." } } }, t = { d = 3.4, v = "dwarf-male", n = { x = 29 }, c = { x = { { 0.00, "Тсссс!" }, { 0.62, "Тише, балда." }, { 1.94, "Нас подслушивают." } } } } },
    [2239] = { d = 31.1, g = 1, v = "dwarf-male", n = { x = 355 }, c = { m = { { 0.00, "Рудник?" }, { 0.56, "Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день." }, { 6.92, "Мои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться." }, { 25.21, "Всё в этом донесении, герой." }, { 27.18, "Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг." } }, f = { { 0.00, "Рудник?" }, { 0.56, "Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день." }, { 6.95, "Мои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться." }, { 23.94, "Всё в этом донесении, героиня." }, { 26.05, "Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг." } } }, t = { d = 21.1, g = 1, v = "dwarf-male", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Большой крюк?" }, { 1.07, "Клянусь собственной бородой!" }, { 3.35, "Ты постарался на славу." }, { 5.20, "Возьми вот этот кинжал и ступай." }, { 7.83, "Круг призовёт тебя снова, когда будет готов третий шаг." }, { 12.18, "Что такое третий шаг?" }, { 14.19, "Да тот, что идёт после второго, а именно – хороший пинок тебе под зад." }, { 20.60, "Хочешь?" } }, f = { { 0.00, "Большой крюк?" }, { 1.06, "Клянусь собственной бородой!" }, { 3.33, "Ты постаралась на славу." }, { 5.25, "Возьми вот этот кинжал и ступай." }, { 7.87, "Круг призовёт тебя снова, когда будет готов третий шаг." }, { 12.09, "Что такое третий шаг?" }, { 14.06, "Да тот, что идёт после второго, а именно – хороший пинок тебе под зад." }, { 20.53, "Хочешь?" } } } } },
    [2240] = { d = 29.6, g = 1, v = "dwarf-male", n = { m = 321, f = 321 }, c = { m = { { 0.00, "Теперь вернёмся к насущным задачам." }, { 2.64, "Тебе предстоит исследовать чертог Хаз'Мула." }, { 5.95, "Проблема в том, что он находится за огромной, запертой дверью!" }, { 10.55, "К счастью, я знаю, как её открыть." }, { 13.12, "Я записал всё в своём дневнике, здесь на столе." }, { 16.56, "Моя группа и я заперты здесь..." }, { 18.93, "Так что ты должен найти для нас чертог Хаз'Мула!" }, { 22.51, "Прочитай мой дневник и отправляйся в чертог." }, { 25.83, "Потом доложи геологу Грозовой Вершине в Стальгорне." } }, f = { { 0.00, "Теперь вернёмся к насущным задачам." }, { 2.62, "Тебе предстоит исследовать чертог Хаз'Мула." }, { 5.90, "Проблема в том, что он находится за огромной, запертой дверью!" }, { 10.46, "К счастью, я знаю, как её открыть." }, { 13.01, "Я записал всё в своём дневнике, здесь на столе." }, { 16.43, "Моя группа и я заперты здесь..." }, { 18.78, "Так что ты должна найти для нас чертог Хаз'Мула!" }, { 22.33, "Прочитай мой дневник и отправляйся в чертог." }, { 25.62, "Потом доложи геологу Грозовой Вершине в Стальгорне." } } }, t = { d = 23.4, v = "dwarf-male", n = { x = 261 }, c = { x = { { 0.00, "Вы видели чертог Хаз'Мула?" }, { 1.98, "Потрясающе!" }, { 2.84, "Бейлог был уверен, что он существовал, но я, честно говоря, сомневался." }, { 7.99, "Спасибо." }, { 8.65, "Теперь то, что вы обнаружили сподвигнет наших лидеров приложить все усилия к тому, чтобы отвоевать Ульдаман." }, { 16.58, "А когда это место снова вернётся под руку Стальгорна, все тайны Чертога Хаз'Мула будут нашими!" } } } } },
    [2241] = { d = 36.0, v = "nightelf-male#55", n = { x = 379 }, c = { x = { { 0.00, "Говорят, что я обезумел от любви." }, { 2.47, "Да, я всё время думаю о Сиарне." }, { 4.80, "Да, мой дом полон рисунков и картин, с которых на меня смотрит Сиарна." }, { 10.00, "Да, я часто целыми днями крошки в рот не беру, не сплю, не пью, а всё плачу о нашей несбывшейся любви." }, { 17.47, "Что в этом плохого?" }, { 18.93, "И вот теперь она отказывается меня видеть." }, { 22.13, "МЕНЯ!" }, { 22.60, "Я пытался письма ей писать, так она не желает ни с кем разговаривать, если только это не разбойник." }, { 29.93, "Не отнесёшь ли ты ей от меня этот цветок?" }, { 32.93, "И не забудь сказать ей, что он от Джаннока." } } }, t = { d = 15.2, g = 1, v = "nightelf-female#52", n = { x = 174 }, c = { m = { { 0.00, "Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать!" }, { 6.67, "Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться..." }, { 12.04, "Не хочешь ли подрядиться на одно дельце, герой?" } }, f = { { 0.00, "Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать!" }, { 6.58, "Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться..." }, { 11.88, "Не хочешь ли подрядиться на одно дельце, героиня?" } } } } },
    [2242] = { d = 27.8, v = "nightelf-female#52", n = { x = 334 }, c = { x = { { 0.00, "Нам кажется, что одно существо могло бы помочь нам понять, что происходит с лесами Тельдрассила." }, { 6.41, "Увы, уговорить это существо может оказаться опасным делом." }, { 10.45, "Это сатир." }, { 11.24, "Он скрывается на ветви на опушке Поляны Оракула." }, { 14.50, "Пока всех, кто подходил к этому сатиру - с угрозами или добрым словом, - постигала мрачная судьба." }, { 21.15, "Может, надо подкрасться к нему незаметно?" }, { 23.99, "Узнай, что у Сетира Древнего в сумках, и возвращайся ко мне." } } }, t = { d = 16.1, g = 1, v = "nightelf-female#52", n = { m = 184, f = 185 }, c = { m = { { 0.00, "Дурные вести." }, { 1.02, "Похоже, что зараза, охватившая леса и реки Тёмного Берега, начинает расползаться и по нашему дому." }, { 7.98, "Ты сослужил добрую службу, но больше ты уже ничем не поможешь." }, { 12.44, "Прими этот клинок в награду за службу Тельдрассилу." } }, f = { { 0.00, "Дурные вести." }, { 1.02, "Похоже, что зараза, охватившая леса и реки Тёмного Берега, начинает расползаться и по нашему дому." }, { 7.98, "Ты сослужила добрую службу, но больше ты уже ничем не поможешь." }, { 12.52, "Прими этот клинок в награду за службу Тельдрассилу." } } } } },
    [2258] = { d = 32.2, g = 1, v = "troll-male#77", n = { m = 375, f = 379 }, c = { m = { { 0.00, "Я хотел бы воспользоваться твоими услугами." }, { 3.10, "Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях." }, { 11.16, "Вот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей." }, { 19.42, "Очевидно, что их можно добыть у самих тварей, но если ты не любитель сражений, можешь попросить о помощи друзей." }, { 27.48, "Я неплохо заплачу, если ты принесёшь мне всё необходимое." }, { 31.48, "Что скажешь?" } }, f = { { 0.00, "Я хотел бы воспользоваться твоими услугами." }, { 3.05, "Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях." }, { 10.99, "Вот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей." }, { 19.12, "Очевидно, что их можно добыть у самих тварей, но если ты не любительница сражений, можешь попросить о помощи друзей." }, { 27.32, "Я неплохо заплачу, если ты принесёшь мне всё необходимое." }, { 31.25, "Что скажешь?" } } }, t = { d = 26.6, g = 1, v = "troll-male#77", n = { m = 265, f = 264 }, c = { m = { { 0.00, "Молодец." }, { 0.72, "Этого мне должно хватить на некоторое время." }, { 4.33, "Вот обещанная плата." }, { 5.98, "Если ты не против получить новое задание, то вот – мне нужны ещё кое-какие реактивы." }, { 12.76, "Некоторые из них можно найти только в глубинах ульдаманского раскопа." }, { 18.31, "Добыть их нелегко, но и плата за помощь будет немалая." }, { 22.71, "Может быть, кое-что получше блестящих монет!" } }, f = { { 0.00, "Умница." }, { 0.66, "Этого мне должно хватить на некоторое время." }, { 4.34, "Вот обещанная плата." }, { 6.04, "Если ты не против получить новое задание, то вот – мне нужны ещё кое-какие реактивы." }, { 12.96, "Некоторые из них можно найти только в глубинах ульдаманского раскопа." }, { 18.62, "Добыть их нелегко, но и плата за помощь будет немалая." }, { 23.11, "Может быть, кое-что получше блестящих монет!" } } } } },
    [2259] = { d = 7.9, v = "nightelf-male#55", n = { x = 85 }, c = { x = { { 0.00, "Не бойся, я не стану посылать тебя к Сиарне." }, { 3.39, "Эрион требует твоего присутствия в Анклаве Кенария." }, { 7.32, "Не медли!" } } }, t = { d = 3.4, g = 1, v = "nightelf-male#55", n = { x = 21 }, c = { m = { { 0.00, "Пора идти дальше, герой, – мир ждёт." } }, f = { { 0.00, "Пора идти дальше, героиня, – мир ждёт." } } } } },
    [2260] = { d = 25.4, v = "nightelf-male#55", n = { x = 284 }, c = { x = { { 0.00, "Весть о ваших деяниях получила широкую огласку." }, { 3.51, "Настолько далеко, что даже разведка Штормграда желает лично побеседовать с вами." }, { 9.48, "Дорога не беспошлинная и небезопасная, но возможность стажироваться в ШРУ – это вам не жук чихнул!" }, { 16.84, "Вас ждёт целый новый мир." }, { 18.69, "Отправляйтесь в Старый город Штормграда и поговорите с Рензиком Ножом в штаб-квартире ШРУ." } } }, t = { d = 11.3, v = "goblin-male", n = { x = 117 }, c = { x = { { 0.00, "Вы откликнулись на призыв ШРУ, и проделали долгий путь от дальних берегов, чтобы вступить в наши ряды." }, { 8.33, "Однако вам многому предстоит научиться." } } } } },
    [2278] = { d = 33.8, g = 1, v = "narrator", n = { m = 347, f = 348 }, c = { m = { { 0.00, "Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения." }, { 12.15, "Когда ты касаешься их, у тебя покалывает пальцы, и перед тобой возникает Каменный Страж." }, { 19.46, "\"Приветствую тебя!" }, { 21.02, "Я – хранитель знаний." }, { 22.81, "Создание земельников было подробно описано и сохранено на Дисках Норганнона.\"" }, { 29.22, "Ты раскрыл сокровищницу никому прежде неизвестных знаний!" } }, f = { { 0.00, "Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения." }, { 11.90, "Когда ты касаешься их, у тебя покалывает пальцы, и перед тобой возникает Каменный Страж." }, { 19.05, "\"Приветствую тебя!" }, { 20.58, "Я – хранитель знаний." }, { 22.33, "Создание земельников было подробно описано и сохранено на Дисках Норганнона.\"" }, { 28.61, "Ты раскрыла сокровищницу никому прежде неизвестных знаний!" } } }, t = { d = 25.4, v = "narrator", n = { x = 257 }, c = { x = { { 0.00, "Прослушав инструкции каменного Стража, ты снова получаешь доступ к Дискам Норганнона, теперь уже зная историю создания земельников, троггов и дворфов." }, { 12.50, "Слабый, краткий гул доносится из глубины дисков." }, { 16.51, "Каменный страж говорит:" }, { 18.45, "\"Теперь Диски синтезировались." }, { 20.98, "Дотронься до них ещё раз, чтобы получить личную копию.\"" } } } } },
    [2279] = { d = 28.6, v = "narrator", n = { x = 303 }, c = { x = { { 0.00, "Ты прикасаешься к Дискам Норганнона, и пальцы снова покалывает." }, { 5.04, "Диски издают странный скрежещущий гул, и твой мешок вдруг становится тяжелее." }, { 11.15, "Внутри ты обнаруживаешь миниатюрную копию Дисков." }, { 15.11, "Несомненно, для увлекающихся историей Азерота, это – неслыханная ценность." }, { 21.01, "Лига Исследователей из Стальгорна как раз из таких." }, { 25.04, "Возможно, они найдут применение этим дискам." } } }, t = { d = 32.6, g = 1, v = "dwarf-male", n = { m = 327, f = 327 }, c = { m = { { 0.00, "Что это у вас там... ох мать моя..." }, { 2.64, "Откуда вы это взяли?" }, { 4.31, "Нет, правда?" }, { 5.28, "Вы кому-нибудь ещё об этом рассказывали?" }, { 8.34, "ПРАВДА?!" }, { 9.03, "Мой дорогой герой, Вы, возможно, только что совершили открытие года в области археологии!" }, { 15.91, "Богов ради!" }, { 16.88, "Кого я пытаюсь надуть, открытие столетия!" }, { 20.15, "Если эти диски – то, о чём я думаю, то они будут тем ключом, который мы так долго искали!" }, { 27.09, "Теперь мы сможем раз и навсегда доказать магическое происхождение дворфов!" } }, f = { { 0.00, "Что это у вас там... ох мать моя..." }, { 2.52, "Откуда вы это взяли?" }, { 4.11, "Нет, правда?" }, { 5.04, "Вы кому-нибудь ещё об этом рассказывали?" }, { 7.96, "ПРАВДА?!" }, { 8.62, "Моя дорогая героиня, Вы, возможно, только что совершили открытие года в области археологии!" }, { 15.39, "Богов ради!" }, { 16.32, "Кого я пытаюсь надуть, открытие столетия!" }, { 19.43, "Если эти диски – то, о чём я думаю, то они будут тем ключом, который мы так долго искали!" }, { 26.07, "Теперь мы сможем раз и навсегда доказать магическое происхождение дворфов!" } } } } },
    [2280] = { d = 30.6, v = "narrator", n = { x = 311 }, c = { x = { { 0.00, "Ты прикасаешься к Дискам Норганнона, и пальцы снова покалывает." }, { 5.23, "Диски издают странный скрежещущий гул, и твой мешок вдруг становится тяжелее." }, { 11.59, "Внутри ты обнаруживаешь миниатюрную копию Дисков." }, { 15.70, "Несомненно, для увлекающихся историей Азерота, это – неслыханная ценность." }, { 21.83, "Мудрецы Громового Утёса, известные всей Орде, как раз из таких." }, { 26.98, "Возможно, они найдут применение этим дискам." } } }, t = { d = 12.9, g = 1, v = "tauren-male#68", n = { m = 108, f = 109 }, c = { m = { { 0.00, "Что это у нас тут?" }, { 1.69, "Невероятно, мой юный друг!" }, { 4.13, "На этих дисках записаны древние и давно утерянные тайны." }, { 9.52, "Ты поступил мудро, принеся их мне." } }, f = { { 0.00, "Что это у нас тут?" }, { 1.72, "Невероятно, мой юный друг!" }, { 4.21, "На этих дисках записаны древние и давно утерянные тайны." }, { 9.70, "Ты поступила мудро, принеся их мне." } } } } },
    [2281] = { d = 21.1, v = "goblin-male", n = { x = 243 }, c = { x = { { 0.00, "Посылать тебя в бой равноценно убийству." }, { 2.89, "Рензику не нужны лишние покойники." }, { 5.40, "Но тебе, бояться нечего: для тебя найдётся не такое опасное дело." }, { 10.09, "Отправляйся в Красногорье и поговори там с Люцием – этот тип связан с ШРУ." }, { 15.68, "Он постоянно отирается у пристани в Приозёрье вместе с остальными бездельниками." } } }, t = { d = 8.9, v = "dwarf-male", n = { x = 89 }, c = { x = { { 0.00, "Что, не слишком-то у тебя ловкие пальчики, верно?" }, { 3.94, "Ну, да не беспокойся: я и не из таких делал отличных разбойников!" } } } } },
    [2282] = { d = 22.5, v = "dwarf-male", n = { x = 237 }, c = { x = { { 0.00, "Я долгие годы обучал молодых воров." }, { 2.85, "В конце концов не всякому плуту от рождения достаётся ловкость и проворство, как у старого Люция." }, { 10.27, "Рядом с дорогой стоит лесопилка Альтера." }, { 13.47, "Я оставил там сундук, а в нём – кое-что важное." }, { 17.08, "Принеси его мне!" }, { 18.40, "Возвращайся с добычей, и получишь Воровской сертификат." } } }, t = { d = 8.8, g = 1, v = "dwarf-male", n = { m = 94, f = 95 }, c = { m = { { 0.00, "Сумел открыть, да?" }, { 1.43, "Неплохая работа." }, { 2.72, "Теперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта." } }, f = { { 0.00, "Сумела открыть, да?" }, { 1.51, "Неплохая работа." }, { 2.82, "Теперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта." } } } } },
    [2283] = { d = 33.0, v = "orc-male", n = { x = 327 }, c = { x = { { 0.00, "У нас есть для тебя работа – если у тебя, конечно, хватит пороху за неё взяться!" }, { 6.49, "В глубине Бесплодных земель есть раскопки Ульдамана." }, { 10.72, "Говорят, недавно там откинул копыта какой-то идиот-паладин." }, { 15.61, "При нём было очень ценное ожерелье с тремя самоцветами: рубином, сапфиром и топазом." }, { 22.47, "Короче, нам нужно это ожерелье, и мы готовы за него заплатить – чистым серебром!" }, { 29.03, "Если оно попорченное – ничего, как-нибудь починим." } } }, t = { d = 26.6, g = 1, v = "orc-male", n = { m = 218, f = 221 }, c = { m = { { 0.00, "О-о, добыча!" }, { 1.24, "Отсюда чую, оно здесь..." }, { 3.55, "Дай-ка взглянуть…" }, { 5.20, "Эй, что это ты нам подсовываешь?" }, { 8.08, "Тут же камней не хватает." }, { 10.39, "Ты что думал, мы не заметим?" }, { 12.95, "Даже Мальтон увидел бы, что камней нету!" }, { 16.74, "Ну, может, это и не ты их спёр..." }, { 19.71, "Но ведь ожерелье без них ничего не стоит!" }, { 23.42, "Не-ет, твоя работа ещё не окончена!" } }, f = { { 0.00, "О-о, добыча!" }, { 1.21, "Отсюда чую, оно здесь..." }, { 3.47, "Дай-ка взглянуть…" }, { 5.09, "Эй, что это ты нам подсовываешь?" }, { 7.91, "Тут же камней не хватает." }, { 10.17, "Ты что думала, мы не заметим?" }, { 12.76, "Даже Мальтон увидел бы, что камней нету!" }, { 16.47, "Ну, может, это и не ты их спёрла..." }, { 19.54, "Но ведь ожерелье без них ничего не стоит!" }, { 23.17, "Не-ет, твоя работа ещё не окончена!" } } } } },
    [2284] = { d = 31.0, v = "orc-male", n = { x = 294 }, c = { x = { { 0.00, "Эти камни наверняка остались где-то в Ульдамане!" }, { 4.02, "Это так же верно, как то, что Мальтон – балбес." }, { 7.81, "Вернись и разыщи их!" }, { 9.49, "Как я уже говорил, если то, что нам рассказывали, правда, в нём были рубин, сапфир и топаз." }, { 16.87, "Найди их и вставь обратно в ожерелье." }, { 19.87, "Где они?" }, { 20.60, "А кто ж их знает?" }, { 21.98, "Может, тебе повезёт отыскать труп того паладина." }, { 25.93, "Может, они до сих пор при нём – если его, конечно, не обчистили." } } }, t = { d = 25.8, v = "narrator", n = { x = 261 }, c = { x = { { 0.00, "Похоже, вам-таки удалось отыскать останки паладина, о которых говорил Дран." }, { 6.20, "Обыскав их, вы находите дневник паладина." }, { 9.60, "Дневник в плохом состоянии, большая часть страниц перепачкана запёкшейся кровью." }, { 16.10, "Но и оставшийся текст – сплошная галиматья." }, { 19.57, "Похоже, это язык людей." }, { 21.64, "Придётся вам найти кого-то, кто сможет это перевести." } } } } },
    [2298] = { d = 30.6, v = "dwarf-male", n = { x = 358 }, c = { x = { { 0.00, "И вот собрались мы уже разрабатывать фазу три, когда вломились несколько болванов Магни, стали нести какую-то чушь насчёт воровства и что они арестуют некоторых членов Тайного Круга." }, { 12.87, "Да только поди возьми старика Чёрную Бороду!" }, { 16.06, "Разборка пошла нешуточная, и каким-то образом всплыло твоё имя!" }, { 20.59, "Хочешь совет?" }, { 21.61, "Бери первого грифона из Стальгорна и дуй в Штормград." }, { 25.37, "Иди в Старый город и там переговори с моим старым приятелем Рензиком Ножом." } } }, t = { d = 4.1, v = "goblin-male", n = { x = 40 }, c = { x = { { 0.00, "Всегда рад видеть в наших рядах ребят Хальфдана!" } } } } },
    [2299] = { d = 10.4, v = "dwarf-male", n = { x = 121 }, c = { x = { { 0.00, "Где тебя носило?" }, { 1.18, "Хальфдан всюду тебя искал." }, { 3.11, "Мы уж подумали, что король забил тебя в кандалы." }, { 6.48, "Дуй в Стальгорн как можно быстрее и поговори с Хальфданом!" } } }, t = { d = 3.1, v = "dwarf-male", n = { x = 29 }, c = { x = { { 0.00, "Говори тише, стража может услышать." } } } } },
    [2300] = { d = 8.3, v = "human-female#47", n = { x = 90 }, c = { x = { { 0.00, "Слушай, рыбка, тебя тут Рензик искал." }, { 2.80, "На твоём месте я не заставляла бы его ждать – всё-таки он правая рука Матиаса..." } } }, t = { d = 5.7, v = "goblin-male", n = { x = 61 }, c = { x = { { 0.00, "Как насчёт того, чтобы приступить к работе?" }, { 3.37, "Или хочешь сначала вздремнуть?" } } } } },
    [2318] = { d = 20.4, v = "narrator", n = { x = 219 }, c = { x = { { 0.00, "Зайдя в окончательный тупик, ты приходишь к выводу, что книгу нужно перевести на понятный тебе язык." }, { 7.62, "В мире наверняка немало тех, кто на это способен, но ближайший такой умелец, скорее всего, найдётся в Каргате, форпосте в Бесплодных Землях." }, { 18.17, "Начать, пожалуй, стоит оттуда." } } }, t = { d = 40.2, g = 1, v = "troll-male#77", n = { m = 403, f = 403 }, c = { m = { { 0.00, "Могучий герой, я знаю зачем Вы здесь, в Бесплодных землях." }, { 4.52, "Я знаю, что Вам нужны мои умения по части языков." }, { 8.42, "Вы – в поисках частей того ожерелья, которое вы нашли в Ульдамане." }, { 13.57, "Удивлены?" }, { 14.33, "Не стоит – знать такие вещи – моя работа." }, { 17.60, "Вместо этого давайте обсудим, что Вы сделаете для того, чтобы перевести дневник." }, { 23.86, "Доверяйте мне – я – единственный, кто может перевести его." }, { 28.31, "Более того, позвольте мне сделать вам предложение получше, чем у Драна Дрофферса, – и вы всё равно сможете довести сделку с ними до конца." }, { 38.96, "Заинтригованы?" } }, f = { { 0.00, "Могучая героиня, я знаю зачем Вы здесь, в Бесплодных землях." }, { 4.67, "Я знаю, что Вам нужны мои умения по части языков." }, { 8.58, "Вы – в поисках частей того ожерелья, которое вы нашли в Ульдамане." }, { 13.74, "Удивлены?" }, { 14.51, "Не стоит – знать такие вещи – моя работа." }, { 17.78, "Вместо этого давайте обсудим, что Вы сделаете для того, чтобы перевести дневник." }, { 24.06, "Доверяйте мне – я – единственный, кто может перевести его." }, { 28.52, "Более того, позвольте мне сделать вам предложение получше, чем у Драна Дрофферса, – и вы всё равно сможете довести сделку с ними до конца." }, { 39.19, "Заинтригованы?" } } } } },
    [2338] = { d = 25.1, v = "troll-male#77", n = { x = 262 }, c = { x = { { 0.00, "Скупщикам Дрофферсу и Сыновьям не хватит умения, чтобы восстановить чары на ожерелье, а вот я могу это сделать." }, { 8.56, "Только дай мне изучить его, чтобы я научился делать подобные." }, { 13.32, "Одолжи мне его на время, а я переведу для тебя дневник." }, { 17.61, "Пока будешь искать камни, я как раз успею изучить ожерелье." }, { 22.23, "Это выгодно нам обоим." }, { 24.03, "Ну, что скажешь?" } } }, t = { d = 25.2, v = "troll-male#77", n = { x = 251 }, c = { x = { { 0.00, "Ты знаешь толк в выгодных сделках – я знал, что на тебя можно положиться." }, { 5.83, "А теперь погоди ещё минутку, я произнесу заклинание, чтобы быстро перевести дневник с человеческого языка на понятный тебе." }, { 15.81, "Я тролль слова, спроси кого хочешь в Орде, и тебе скажут: Джаркалу Замшелому Клыку можно доверять!" }, { 23.90, "Ну-с, приступим..." } } } } },
    [2339] = { d = 35.8, g = 1, v = "troll-male#77", n = { m = 399, f = 400 }, c = { m = { { 0.00, "Вот и перевод, ты можешь сам прочесть его." }, { 3.12, "Там говорится, что рубин спрятан дворфами, топаз спрятали трогги, а сапфир прикарманил трогг по имени Гримлок." }, { 11.21, "Послушай-ка, тебе потребуется источник энергии, чтобы ожерелье вновь заработало." }, { 17.11, "Дран Дрофферс об этом даже не подозревает." }, { 20.23, "Чтобы найти такой источник, отправляйся в Ульдаман, спустись в самую глубину и убей самого могучего конструкта, какого сможешь найти." }, { 30.18, "Уверен, источник энергии будет у него." }, { 33.09, "Как соберёшь всё – возвращайся ко мне!" } }, f = { { 0.00, "Вот и перевод, ты можешь сама прочесть его." }, { 3.26, "Там говорится, что рубин спрятан дворфами, топаз спрятали трогги, а сапфир прикарманил трогг по имени Гримлок." }, { 11.37, "Послушай-ка, тебе потребуется источник энергии, чтобы ожерелье вновь заработало." }, { 17.29, "Дран Дрофферс об этом даже не подозревает." }, { 20.42, "Чтобы найти такой источник, отправляйся в Ульдаман, спустись в самую глубину и убей самого могучего конструкта, какого сможешь найти." }, { 30.40, "Уверен, источник энергии будет у него." }, { 33.33, "Как соберёшь всё – возвращайся ко мне!" } } }, t = { d = 23.2, g = 1, v = "troll-male#77", n = { x = 234 }, c = { m = { { 0.00, "Отлично, герой!" }, { 1.29, "Скоро мы пожнём плоды наших трудов." }, { 4.17, "Я закончил работу над ожерельем и уверен, что теперь смогу создать такое же." }, { 10.27, "Но сначала я использую специальное заклинание, чтобы быстро исследовать эти самоцветы, прежде чем ты унесёшь их и ожерелье в Оргриммар." }, { 20.90, "Это займёт всего пару минут." } }, f = { { 0.00, "Отлично, героиня!" }, { 1.42, "Скоро мы пожнём плоды наших трудов." }, { 4.27, "Я закончил работу над ожерельем и уверен, что теперь смогу создать такое же." }, { 10.32, "Но сначала я использую специальное заклинание, чтобы быстро исследовать эти самоцветы, прежде чем ты унесёшь их и ожерелье в Оргриммар." }, { 20.84, "Это займёт всего пару минут." } } } } },
    [2340] = { d = 34.2, g = 1, v = "troll-male#77", n = { m = 382, f = 383 }, c = { m = { { 0.00, "Ожерелье будет работать, только если самоцветы будут в сродстве с металлом оправы." }, { 6.30, "Этот источник энергии поможет вернуть ожерелью магическую силу..." }, { 11.32, "Надеюсь." }, { 12.00, "Я с удовольствием предоставлю тебе камни, подходящие к ожерелью, если окажется, что источник энергии действительно работает." }, { 21.28, "Отправляйся в Оргриммар и выполни, что обещал скупщикам Дрофферсу и Сыновьям." }, { 26.98, "Никому не сообщай о наших договорённостях, и, возможно, к твоему возвращению я приготовлю сюрприз." } }, f = { { 0.00, "Ожерелье будет работать, только если самоцветы будут в сродстве с металлом оправы." }, { 6.32, "Этот источник энергии поможет вернуть ожерелью магическую силу..." }, { 11.35, "Надеюсь." }, { 12.03, "Я с удовольствием предоставлю тебе камни, подходящие к ожерелью, если окажется, что источник энергии действительно работает." }, { 21.34, "Отправляйся в Оргриммар и выполни, что обещала скупщикам Дрофферсу и Сыновьям." }, { 27.12, "Никому не сообщай о наших договорённостях, и, возможно, к твоему возвращению я приготовлю сюрприз." } } }, t = { d = 29.8, g = 1, v = "orc-male", n = { m = 281, f = 281 }, c = { m = { { 0.00, "Ну, всё в порядке." }, { 1.50, "Я могу оставить себе и мешок?" }, { 4.06, "Спасибо, премного благодарен." }, { 6.54, "И всё же лучший трофей – это ожерелье!" }, { 9.77, "Не строй такую кислую мину, оно было бы тебе не к лицу!" }, { 14.50, "Сделка есть сделка, поэтому вот твоя награда за принесённые трофеи." }, { 20.06, "Что ж, с этим покончено, можешь заглядывать иногда, если понадобится работа." }, { 26.44, "А пока будь любезен, покинь помещение!" } }, f = { { 0.00, "Ну, всё в порядке." }, { 1.52, "Я могу оставить себе и мешок?" }, { 4.10, "Спасибо, премного благодарен." }, { 6.61, "И всё же лучший трофей – это ожерелье!" }, { 9.87, "Не строй такую кислую мину, оно было бы тебе не к лицу!" }, { 14.66, "Сделка есть сделка, поэтому вот твоя награда за принесённые трофеи." }, { 20.28, "Что ж, с этим покончено, можешь заглядывать иногда, если понадобится работа." }, { 26.73, "А пока будь любезна, покинь помещение!" } } } } },
    [2341] = { d = 15.6, v = "narrator", n = { x = 162 }, c = { x = { { 0.00, "Полдела сделано." }, { 1.35, "Дран и Мальтон Дрофферсы уже ссорятся из-за новой добычи." }, { 5.99, "Теперь нужно сходить в Бесплодные земли – возможно, у Джаркала Замшелого Клыка из Каргата найдётся для вас особая награда..." } } }, t = { d = 26.7, v = "troll-male#77", n = { x = 253 }, c = { x = { { 0.00, "Источник силы, полученный от тебя, превзошёл все мои ожидания!" }, { 5.27, "Мне удалось сделать два ожерелья – тебе и мне, – и в нём осталось достаточно энергии, чтобы сделать как минимум ещё три!" }, { 15.27, "Я на этом неплохо наживусь, а семейка Дрофферсов ничего и не узнаёт!" }, { 21.00, "Вот, держи." }, { 21.99, "Я тебе очень благодарен... а это знак моей благодарности!" } } } } },
    [2342] = { d = 37.8, v = "scourge-male#83", n = { x = 404 }, c = { x = { { 0.00, "Гарреттам не пристало мести загоны для летучих мышей такой метлой!" }, { 5.21, "Мерзкая работёнка позволила мне заработать немного денег, и я хочу истратить их на улучшение своего положения." }, { 13.61, "Фамильное \"оружие\" Гарреттов заперто в нашем сундуке в Южном зале Ульдамана." }, { 19.58, "Там наша семья трудилась долгие годы." }, { 22.57, "Без него я застряну тут навеки – в буквальном смысле – и буду мести за проклятыми летучими мышами до скончания веков." }, { 31.59, "Принеси мне наше сокровище!" }, { 33.74, "Помоги вернуть то, что положено мне по праву рождения!" } } }, t = { d = 16.8, v = "scourge-male#83", n = { x = 149 }, c = { x = { { 0.00, "Наконец-то – метла, достойная Гарретта." }, { 3.61, "Не зря я потратил на тебя деньги!" }, { 6.64, "Вы слышите меня, летучие мыши?" }, { 9.51, "Теперь у меня есть истинное оружие семьи Гарреттов!" }, { 14.26, "Трепещите, проклятые пискуны!" } } } } },
    [2359] = { d = 31.8, v = "human-female#47", n = { x = 338 }, c = { x = { { 0.00, "Я за этой башней уже не первую неделю наблюдаю." }, { 3.58, "Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи." }, { 10.07, "Кто такие?" }, { 10.86, "Мы можем только гадать." }, { 12.65, "Одно я тебе скажу: это не люди." }, { 15.10, "Как бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет." }, { 21.59, "А ключ от сундука – у того зомби с шипами." }, { 24.70, "Добудь этот ключ, проберись в башню и выясни, что находится в том сундуке." }, { 30.13, "Находку отнесёшь Матиасу." } } }, t = { d = 34.6, v = "human-male", n = { x = 427 }, c = { x = { { 0.00, "Это объясняет присутствие мертвяков из Братства Справедливости, которых вы с Кеарнен видели рядом с башней." }, { 7.18, "Это может объяснить и вовлечённость Торговой Компании в дела Братства Справедливости и эти странные поставки из Сумеречного леса." }, { 15.81, "Как явствует из этой книги, тролли Занзила в Тернистой долине нашли возможность поднимать мёртвых с помощью зелий... выражаясь точнее – ядов." }, { 25.29, "Вы бесполезны для ШРУ, если у вас нет чёткого представления о ядах, особенно когда рецепт того, как поднимать нежить, почти у нас в руках." } } } } },
    [2360] = { d = 33.4, v = "human-male", n = { x = 400 }, c = { x = { { 0.00, "Произошло то, чего я ожидал." }, { 1.97, "Разведотдел ШРУ сообщает, что Братство Справедливости что-то затевает в Западном Крае." }, { 8.13, "Складывается впечатление, что братство захватило покинутую сторожевую башню Альянса к юго-востоку от Сторожевого Холма и использует её как базу для ввоза контрабанды из Красногорья." }, { 20.45, "Отправляйтесь в Западный Край и свяжитесь с посланницей Кеарнен для подробного доклада." }, { 26.30, "Она там прячется, неподалёку от башни." }, { 28.88, "... и кстати, если вас раскроют – вы никогда не слышали о ШРУ..." } } }, t = { d = 7.7, v = "human-female#47", n = { x = 88 }, c = { x = { { 0.00, "Наконец-то Матиас прислал ещё одного агента мне в помощь." }, { 4.14, "Ну, надеюсь, он готов к вороху неприятных новостей." } } } } },
    [2361] = { t = { d = 20.2, g = 1, v = "gnome-male", n = { m = 219, f = 220 }, c = { m = { { 0.00, "С радостью отдаю тебе это ожерелье, могучий герой." }, { 3.72, "Ты оказал мне неоценимую услугу, и я благодарю тебя за это." }, { 7.96, "Носи его с гордостью и не забывай громко и почаще упоминать, кто его для тебя сделал!" }, { 14.12, "А если заодно скажешь, что оно на самом деле не проклято, будет просто замечательно." } }, f = { { 0.00, "С радостью отдаю тебе это ожерелье, могучая героиня." }, { 3.85, "Ты оказала мне неоценимую услугу, и я благодарю тебя за это." }, { 8.14, "Носи его с гордостью и не забывай громко и почаще упоминать, кто его для тебя сделал!" }, { 14.29, "А если заодно скажешь, что оно на самом деле не проклято, будет просто замечательно." } } } } },
    [2378] = { d = 26.8, g = 1, v = "scourge-male#82", n = { m = 237, f = 238 }, c = { m = { { 0.00, "Ты много сделал для стражей смерти, но пришло время двигаться дальше." }, { 6.18, "У тебя талант к искусству обмана и скрытности, но этот талант ещё следует развить." }, { 13.47, "У стражей смерти есть союзники в Изувеченной Длани." }, { 17.99, "Поищи среди них тех, кто готов помочь нам." }, { 21.72, "Для начала поговори с Шентулом в Оргриммаре." } }, f = { { 0.00, "Ты много сделала для стражей смерти, но пришло время двигаться дальше." }, { 6.57, "У тебя талант к искусству обмана и скрытности, но этот талант ещё следует развить." }, { 14.23, "У стражей смерти есть союзники в Изувеченной Длани." }, { 18.97, "Поищи среди них тех, кто готов помочь нам." }, { 22.89, "Для начала поговори с Шентулом в Оргриммаре." } } }, t = { d = 5.8, v = "troll-male", n = { x = 52 }, c = { x = { { 0.00, "Так вот кого могучие союзники прислали Шентулу..." }, { 4.59, "Не впечатляет…" } } } } },
    [2379] = { d = 17.8, v = "troll-male", n = { x = 208 }, c = { x = { { 0.00, "Одной твоей решимости ещё недостаточно, чтобы преодолеть препятствия, которые ждут впереди." }, { 6.65, "Поговори с Зандо'заном, чтобы начать учиться на агента Изувеченной Длани." }, { 12.05, "Лишь овладев навыками незаметности и коварства, ты сможешь сделать следующий шаг." } } }, t = { d = 5.0, v = "troll-male#78", n = { x = 45 }, c = { x = { { 0.00, "Быть может, Зандо'зан ошибся." }, { 2.73, "Зандо'зан просит прощения." } } } } },
    [2380] = { d = 24.1, v = "orc-male", n = { x = 241 }, c = { x = { { 0.00, "Ты, конечно, далеко ещё не специалист по скрытности и всяким уловкам, однако же тебе есть куда расти." }, { 8.15, "По крайней мере, начальство явно обратило на тебя внимание: сам великий Шентул запомнил твоё имя!" }, { 16.08, "Ступай на север – эта дорога ведёт в Оргриммар." }, { 19.94, "Отыщи там в расселине Теней Шентула и поговори с ним." } } }, t = { d = 15.8, v = "troll-male", n = { x = 168 }, c = { x = { { 0.00, "Очень важно, чтобы Изувеченная Длань сохраняла бдительность перед лицом перемен, которые Тралл намеревается ввести в Орде." }, { 9.93, "Числом тут не возьмёшь – для нас главное незаметность и разнообразные уловки!" } } } } },
    [2381] = { d = 37.3, v = "goblin-male", n = { x = 409 }, c = { x = { { 0.00, "Не хочу тебя пугать, но последние пять воров, которым я поручил похитить сокровище Южного моря, не вернулись." }, { 8.17, "Потом их нашли..." }, { 9.51, "Частично." }, { 10.24, "В южной части побережья пришвартован пиратский корабль, \"Стрела прилива\"." }, { 15.73, "В трюме у него хранится то самое сокровище." }, { 19.01, "На второй палубе устроен пиратский притон, в котором они натаскивают своих воров." }, { 25.17, "Проникни на этот корабль, похить сокровище и принеси его мне." }, { 29.79, "Если тебе надо поднатореть в воровском искусстве, можешь заглянуть в притон, но соблюдай осторожность!" } } }, t = { d = 13.0, g = 1, v = "goblin-male", n = { m = 120, f = 121 }, c = { m = { { 0.00, "Немыслимо!" }, { 0.91, "Невероятно!" }, { 1.90, "Поразительно!" }, { 3.05, "Да ты талант." }, { 4.19, "Или же ты самый везучий парень на свете!" }, { 7.69, "Вот твоя доля." }, { 8.99, "Думаю, ты найдёшь ей лучшее применение, чем я." } }, f = { { 0.00, "Немыслимо!" }, { 0.93, "Невероятно!" }, { 1.93, "Поразительно!" }, { 3.09, "Да ты талант." }, { 4.24, "Или же ты самая везучая девушка на свете!" }, { 7.87, "Вот твоя доля." }, { 9.18, "Думаю, ты найдёшь ей лучшее применение, чем я." } } } } },
    [2382] = { d = 23.3, g = 1, v = "troll-male#78", n = { m = 208, f = 208 }, c = { m = { { 0.00, "Зандо'зан это видел!" }, { 1.79, "Да, день близок!" }, { 3.13, "Смерть Тралла... кинжал в его спине, яд в его кубке..." }, { 7.68, "Но Зандо'зан слишком много болтает." }, { 10.66, "Путник!" }, { 11.33, "У Зандо'зана есть поручение для тебя!" }, { 14.39, "Путник должен отправиться в Кабестан, к востоку от Перекрёстка, и поговорить с Рениксом Презренным." }, { 22.44, "Ступай!" } }, f = { { 0.00, "Зандо'зан это видел!" }, { 1.80, "Да, день близок!" }, { 3.15, "Смерть Тралла... кинжал в его спине, яд в его кубке..." }, { 7.74, "Но Зандо'зан слишком много болтает." }, { 10.74, "Путница!" }, { 11.49, "У Зандо'зана есть поручение для тебя!" }, { 14.57, "Путница должна отправиться в Кабестан, к востоку от Перекрёстка, и поговорить с Рениксом Презренным." }, { 22.76, "Ступай!" } } }, t = { d = 10.5, v = "goblin-male", n = { x = 109 }, c = { x = { { 0.00, "Как, опять?" }, { 0.91, "Предыдущие пятеро, кого прислал ко мне этот чокнутый тролль, пошли на корм акулам." }, { 7.27, "Ну что ж, будем надеяться, что тебе повезёт…" } } } } },
    [2383] = { d = 15.2, v = "orc-male#60", n = { x = 150 }, c = { x = { { 0.00, "А!" }, { 0.21, "Тебе тут пергамент прислали, пока тебя не было." }, { 4.03, "Прочитай, когда время будет." }, { 6.37, "Это, кажется, от Франга, наставника воинов." }, { 9.83, "Он хочет с тобой поговорить." }, { 12.10, "Он обычно сидит в тени у входа в Логово." } } }, t = { d = 24.0, g = 1, v = "orc-male#60", n = { m = 235, f = 236 }, c = { m = { { 0.00, "А-а, да, это я тебе написал..." }, { 2.46, "Я слышал, что ты скоро тут появишься." }, { 5.34, "Рад, что тебе удалось добраться сюда невредимым – будем надеяться, что ты переживёшь и грядущие испытания." }, { 13.50, "Наберёшься сил – приходи ко мне." }, { 15.89, "Я сделаю всё, чтобы из тебя получился настоящий воин." }, { 20.11, "Удачи!" }, { 20.67, "Возвращайся, когда будешь готов." } }, f = { { 0.00, "А-а, да, это я тебе написал..." }, { 2.55, "Я слышал, что ты скоро тут появишься." }, { 5.53, "Рад, что тебе удалось добраться сюда невредимой – будем надеяться, что ты переживёшь и грядущие испытания." }, { 13.97, "Наберёшься сил – приходи ко мне." }, { 16.44, "Я сделаю всё, чтобы из тебя получился настоящий воин." }, { 20.81, "Удачи!" }, { 21.39, "Возвращайся, когда будешь готова." } } } } },
    [2398] = { d = 39.7, g = 1, v = "dwarf-male", n = { m = 450, f = 450 }, c = { m = { { 0.00, "Раскопки в Ульдамане не всегда были захвачены троггами." }, { 3.98, "Изначально мы, дворфы Стальгорна, вели здесь работы, но потом..." }, { 8.54, "Потом появились эти твари." }, { 10.53, "Они прибыли столь быстро и в таком количестве, что дворфы не смогли ничего поделать." }, { 16.57, "Честно говоря, их нападение было настолько внезапным, что многие наши люди могли не успеть вырваться из осады." }, { 24.54, "Боюсь, они по сей день остаются в ловушке в тылу врага." }, { 28.52, "Мой друг Бейлог руководил небольшим отрядом дворфов в глубине раскопа прямо перед нападением троггов." }, { 35.78, "Если он и его ребята живы, то я хочу, чтобы ты нашёл их." } }, f = { { 0.00, "Раскопки в Ульдамане не всегда были захвачены троггами." }, { 3.94, "Изначально мы, дворфы Стальгорна, вели здесь работы, но потом..." }, { 8.44, "Потом появились эти твари." }, { 10.41, "Они прибыли столь быстро и в таком количестве, что дворфы не смогли ничего поделать." }, { 16.38, "Честно говоря, их нападение было настолько внезапным, что многие наши люди могли не успеть вырваться из осады." }, { 24.25, "Боюсь, они по сей день остаются в ловушке в тылу врага." }, { 28.19, "Мой друг Бейлог руководил небольшим отрядом дворфов в глубине раскопа прямо перед нападением троггов." }, { 35.36, "Если он и его ребята живы, то я хочу, чтобы ты нашла их." } } }, t = { d = 19.4, g = 1, v = "dwarf-male", n = { x = 202 }, c = { m = { { 0.00, "Ты как раз вовремя!" }, { 1.37, "Я уже боялся, что проспорю Олафу!" }, { 3.85, "Он бился об заклад, что его борода достанет до колен, прежде чем мы увидим живое лицо, герой." }, { 10.69, "И вот, ты здесь, а бороде Олафа ещё до колен осталась пара дюймов." }, { 15.45, "Спасибо!" }, { 16.11, "Я обязательно поделюсь с тобой выигрышем." } }, f = { { 0.00, "Ты как раз вовремя!" }, { 1.39, "Я уже боялся, что проспорю Олафу!" }, { 3.92, "Он бился об заклад, что его борода достанет до кол