    [2399] = { t = { d = 9.6, v = "narrator", n = { x = 87 }, c = { x = { { 0.00, "Ростки, которые Деналан посадил в своём саду, поднялись и вытянулись." }, { 6.11, "Они трепещут, ожидая, когда их сорвут..." } } } } },
    [2418] = { d = 43.5, v = "goblin-male#108", n = { x = 533 }, c = { x = { { 0.00, "Есть у меня зуб на этих дворфов Кузни Теней!" }, { 3.03, "Пару лет назад они пригласили меня в Крепость Ангор, чтобы я исследовал для них два образца прелюбопытнейших камней, привезённых с ульдаманского раскопа." }, { 13.20, "Я провёл исследования, и вообрази, что это было?" }, { 16.41, "Энергия!" }, { 17.02, "Каждый камень был мощнейшим источником энергии в сжатом, потенцированном виде – нужно только знать, как правильно высвободить её!" }, { 25.61, "Чего только не найдёшь в Ульдамане..." }, { 28.10, "В общем, как только я рассказал об этом дворфам, они вышвырнули меня из крепости и направились в Ульдаман за чудесными камнями." }, { 36.64, "Мне бы такие, знаешь ли, тоже пригодились." }, { 39.48, "Принеси мне несколько обоих видов, и я щедро вознагражу тебя." } } }, t = { d = 15.6, g = 1, v = "goblin-male#108", n = { m = 169, f = 170 }, c = { m = { { 0.00, "Прекрасно, ты принёс их!" }, { 1.77, "Ты самый благонадёжный герой, которого мне приходилось встречать!" }, { 6.61, "Немедленно опробую эти камни на моих последних механизмах!" }, { 11.11, "Нутром чую, с этими камнями можно создать вечный двигатель!" } }, f = { { 0.00, "Прекрасно, ты принесла их!" }, { 1.94, "Ты самая благонадёжная героиня, которую мне приходилось встречать!" }, { 6.77, "Немедленно опробую эти камни на моих последних механизмах!" }, { 11.19, "Нутром чую, с этими камнями можно создать вечный двигатель!" } } } } },
    [2438] = { d = 34.0, g = 1, v = "nightelf-male#54", n = { x = 349 }, c = { m = { { 0.00, "Некогда Гэролас Талветрен, страж друидов обители Бен'этиль, подарил мне изумрудного ловца снов." }, { 7.13, "Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит." }, { 14.93, "Увы, мне не удалось забрать его из моего шкафчика в деревне Звёздного Ветра..." }, { 20.84, "Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там." }, { 28.78, "Может, тебе удастся добыть моего ловца снов, герой?" } }, f = { { 0.00, "Некогда Гэролас Талветрен, страж друидов обители Бен'этиль, подарил мне изумрудного ловца снов." }, { 7.39, "Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит." }, { 15.49, "Увы, мне не удалось забрать его из моего шкафчика в деревне Звёздного Ветра..." }, { 21.62, "Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там." }, { 29.86, "Может, тебе удастся добыть моего ловца снов, героиня?" } } }, t = { d = 10.6, v = "nightelf-male#54", n = { x = 111 }, c = { x = { { 0.00, "Мой изумрудный ловец снов очень много для меня значит." }, { 4.42, "Такие подарки лишь немногим дарят." }, { 7.24, "Прими мою благодарность за его возвращение." } } } } },
    [2439] = { d = 33.8, g = 1, v = "dwarf-male", n = { m = 384, f = 387 }, c = { m = { { 0.00, "Это невероятная находка." }, { 1.83, "Согласно этим дискам, Древние Титаны, или Создатели, имеют отношение к нашему чудесному возникновению!" }, { 9.34, "Нам нужно уделить как можно больше времени их изучению." }, { 13.39, "А вас, мой героический друг, прошу принять этот сертификат и отнести его Дините Каменной Мантии в хранилище." }, { 21.23, "По нему вы получите то, что, на мой взгляд, будет достойной наградой за такую находку!" }, { 27.37, "Когда будете готовы, возвращайтесь ко мне – у Лиги Исследователей ещё много работы для вас!" } }, f = { { 0.00, "Это невероятная находка." }, { 1.80, "Согласно этим дискам, Древние Титаны, или Создатели, имеют отношение к нашему чудесному возникновению!" }, { 9.21, "Нам нужно уделить как можно больше времени их изучению." }, { 13.20, "А вас, моя героическая подруга, прошу принять этот сертификат и отнести его Дините Каменной Мантии в хранилище." }, { 21.25, "По нему вы получите то, что, на мой взгляд, будет достойной наградой за такую находку!" }, { 27.30, "Когда будете готовы, возвращайтесь ко мне – у Лиги Исследователей ещё много работы для вас!" } } }, t = { d = 21.8, v = "dwarf-female#34", n = { x = 217 }, c = { x = { { 0.00, "Ах, сертификат Лиги Исследователей... и весьма ценный, смею заметить." }, { 5.76, "Лига Исследователей даёт мне полномочия предложить вам выбрать себе награду прямо из хранилища." }, { 13.61, "Награда ваша, так что выбирайте – либо пять наилучших целебных зелий, либо пять сильных зелий маны." } } } } },
    [2440] = { d = 36.8, g = 1, v = "tauren-male#68", n = { m = 373, f = 374 }, c = { m = { { 0.00, "Я сосредоточу свои усилия на исследовании этих дисков, и со временем они раскроют мне свою тайну." }, { 7.96, "А тебя я награжу за то, что ты обратил на них моё внимание." }, { 12.63, "Отнеси этот сертификат Бене Заиндевевшее Копыто, наставнице алхимиков в Громовом Утёсе." }, { 19.72, "Она даст тебе один интересный предмет, который наверняка тебе понравится, а ещё она даст тебе выбрать зелье из моих личных запасов." }, { 30.53, "Возвращайся поскорее, ибо я чувствую, что мы стоим на пороге великого открытия." } }, f = { { 0.00, "Я сосредоточу свои усилия на исследовании этих дисков, и со временем они раскроют мне свою тайну." }, { 7.94, "А тебя я награжу за то, что ты обратила на них моё внимание." }, { 12.68, "Отнеси этот сертификат Бене Заиндевевшее Копыто, наставнице алхимиков в Громовом Утёсе." }, { 19.75, "Она даст тебе один интересный предмет, который наверняка тебе понравится, а ещё она даст тебе выбрать зелье из моих личных запасов." }, { 30.54, "Возвращайся поскорее, ибо я чувствую, что мы стоим на пороге великого открытия." } } }, t = { d = 19.3, g = 1, v = "tauren-female#71", n = { m = 180, f = 181 }, c = { m = { { 0.00, "Что же, ты, видать, угодил Ведуну Искателю Истины, принеся ему ту штуку." }, { 6.14, "Так что вдобавок ты получишь в награду зелья из его личного хранилища." }, { 12.05, "Можешь выбрать или пять наилучших целебных зелий, либо пять сильных зелий маны." } }, f = { { 0.00, "Что же, ты, видать, угодила Ведуну Искателю Истины, принеся ему ту штуку." }, { 6.38, "Так что вдобавок ты получишь в награду зелья из его личного хранилища." }, { 12.44, "Можешь выбрать или пять наилучших целебных зелий, либо пять сильных зелий маны." } } } } },
    [2458] = { d = 35.4, v = "troll-male", n = { x = 393 }, c = { x = { { 0.00, "Торговая Компания..." }, { 1.54, "Доводилось тебе слышать про такую?" }, { 4.15, "Мы в течение года пытались внедрить агента в их ряды." }, { 8.16, "Это было непросто, но мы преуспели." }, { 10.84, "Недавно мы получили сведения, что Торговая Компания затевает что-то крупное." }, { 16.52, "Ступай к башне Торговой Компании, которая стоит к северу от Нефтяного болота, и свяжись с нашим тайным агентом, надсмотрщиком Физзулом." }, { 26.62, "Когда найдёшь башню, используй это сигнальное ружьё, потом подойди к Физзулу и покажи ему приветствие Изувеченной Длани." } } }, t = { d = 16.7, v = "dwarf-male", n = { x = 199 }, c = { x = { { 0.00, "Приятно видеть в здешних местах ещё одного агента Изувеченной Длани!" }, { 4.67, "Вот только боюсь, как бы твоих вспышек не заметил кто-то лишний." }, { 9.04, "В следующий раз, когда тебе нужно будет со мной поговорить, дважды свистни в этот свисток, и я пойму, что это свои." } } } } },
    [2459] = { d = 36.8, v = "nightelf-male#54", n = { x = 366 }, c = { x = { { 0.00, "Изумруд..." }, { 0.88, "Он пропал!" }, { 1.75, "Мой ловец снов повреждён!" }, { 3.72, "К северу от деревни Звёздного Ветра засела шайка мистиков из племени Кривой Сосны." }, { 10.44, "Я слышал, что их вожак, Фероситас Пожиратель Снов, носил ожерелье, которое светится зелёным в ночи." }, { 18.40, "Теперь, глядя на своего ловца снов, я уверен, что это он украл мой изумруд..." }, { 24.68, "Он не понимает, что его сила для него бесполезна." }, { 28.70, "Найди этот пропавший драгоценный камень." }, { 32.06, "И раз уж ты здесь, истреби заодно и этих зловредных мистиков." } } }, t = { d = 4.7, v = "nightelf-male#54", n = { x = 44 }, c = { x = { { 0.00, "Теперь я восстановлю своего ловца снов!" }, { 3.58, "Спасибо тебе." } } } } },
    [2460] = { d = 13.5, v = "troll-male", n = { x = 129 }, c = { x = { { 0.00, "Теперь, когда ты – разбойник Изувеченной Длани, тебе следует обучиться особому приветствию." }, { 7.97, "Это знак, по которому мы опознаём своих." }, { 11.41, "Смотри и повторяй за мной." } } }, t = { d = 3.6, g = 1, v = "troll-male", n = { m = 30, f = 29 }, c = { m = { { 0.00, "Молодец!" }, { 0.92, "Теперь мы можем продолжать." } }, f = { { 0.00, "Умница!" }, { 0.85, "Теперь мы можем продолжать." } } } } },
    [2478] = { d = 30.8, g = 1, v = "dwarf-male", n = { m = 334, f = 334 }, c = { m = { { 0.00, "Тебе придётся украсть ключ от башни у штейгера Силиксиза." }, { 4.26, "Смотри не потеряй его: он мне ещё пригодится." }, { 7.63, "Не забудь: яд ослабил всех в этой башне." }, { 10.67, "Покажи, на что ты способен, неси хаос и разрушение в стены башни." }, { 15.60, "Убей всех – жалости тут нет места!" }, { 18.17, "Когда внутри останутся лишь кровавые ошмётки, возьми денежный ящик Галливикса и укради из него запас смеси Занзила." }, { 26.88, "Отнеси голову Галливикса и смесь Шентулу в Оргриммар." } }, f = { { 0.00, "Тебе придётся украсть ключ от башни у штейгера Силиксиза." }, { 4.27, "Смотри не потеряй его: он мне ещё пригодится." }, { 7.65, "Не забудь: яд ослабил всех в этой башне." }, { 10.70, "Покажи, на что ты способна, неси хаос и разрушение в стены башни." }, { 15.64, "Убей всех – жалости тут нет места!" }, { 18.22, "Когда внутри останутся лишь кровавые ошмётки, возьми денежный ящик Галливикса и укради из него запас смеси Занзила." }, { 26.95, "Отнеси голову Галливикса и смесь Шентулу в Оргриммар." } } }, t = { d = 21.0, g = 1, v = "troll-male", n = { m = 200, f = 201 }, c = { m = { { 0.00, "Бедный Физзул, он был прекрасным агентом, одним из лучших." }, { 4.83, "Увы, мы заплатили за победу высокую цену." }, { 8.33, "Да, работа агента Изувеченной Длани опасна." }, { 11.97, "Но ты отлично справился с заданием, герой." }, { 15.47, "Хорошо, что тебе удалось выжить." }, { 18.22, "Ты ведь можешь и дальше служить нам." } }, f = { { 0.00, "Бедный Физзул, он был прекрасным агентом, одним из лучших." }, { 4.73, "Увы, мы заплатили за победу высокую цену." }, { 8.15, "Да, работа агента Изувеченной Длани опасна." }, { 11.71, "Но ты отлично справилась с заданием, героиня." }, { 15.35, "Хорошо, что тебе удалось выжить." }, { 18.04, "Ты ведь можешь и дальше служить нам." } } } } },
    [2479] = { d = 13.5, v = "troll-male", n = { x = 138 }, c = { x = { { 0.00, "Отнеси образчик этой смеси Сержу Хинотту на Мельницу Таррен." }, { 4.79, "Если кто сможет тебя исцелить, так это Серж." }, { 8.26, "Он тебя обучит всему, что связано с ядами, – если, конечно, выживешь." } } }, t = { d = 9.3, g = 1, v = "scourge-male#83", n = { m = 66, f = 66 }, c = { m = { { 0.00, "О, герой, какой ты бледненький!" }, { 3.28, "А чем это от тебя так мерзко благоухает?" }, { 7.49, "Я должен выяснить!" } }, f = { { 0.00, "О, героиня, какая ты бледненькая!" }, { 3.37, "А чем это от тебя так мерзко благоухает?" }, { 7.46, "Я должен выяснить!" } } } } },
    [2480] = { d = 20.7, v = "scourge-male#83", n = { x = 208 }, c = { x = { { 0.00, "Никогда не видел таких отличных результатов действия яда!" }, { 4.68, "Занзил, говоришь?" }, { 6.12, "Не слыхал о таком..." }, { 7.77, "Однако состав он сварил отменный, надо отдать ему должное." }, { 12.60, "Итак, я должен вылечить тебя и научить пользоваться этим ядом?" }, { 17.71, "Дай мне пару минут на изучение токсина." } } }, t = { d = 10.0, v = "scourge-male#83", n = { x = 96 }, c = { x = { { 0.00, "Лекарство готово!" }, { 1.59, "Выпей это противоядие, и наступление безумия остановится." }, { 6.67, "Впрочем, с запахом ничего не поделаешь." } } } } },
    [2498] = { d = 16.2, v = "nightelf-male#55", n = { x = 188 }, c = { x = { { 0.00, "Я только что получил известие, что Деналан с озера Аль'Амет узнал, что могло послужить причиной возникновения опухоли, поражающей древесников." }, { 10.00, "Пожалуйста, поговори с ним и скажи, что тебя прислал я." }, { 13.88, "Торопись, ему нужна наша помощь." } } }, t = { d = 9.5, g = 1, v = "nightelf-male#59", n = { m = 97, f = 97 }, c = { m = { { 0.00, "Ах, так, значит, Релиан послал тебя мне в помощь." }, { 3.74, "Хорошо, что ты так скоро пришёл." }, { 6.13, "Я обнаружил нечто чрезвычайно тревожное!" } }, f = { { 0.00, "Ах, так, значит, Релиан послал тебя мне в помощь." }, { 3.91, "Хорошо, что ты так скоро пришла." }, { 6.47, "Я обнаружил нечто чрезвычайно тревожное!" } } } } },
    [2499] = { d = 34.5, g = 1, v = "nightelf-male#59", n = { m = 370, f = 372 }, c = { m = { { 0.00, "В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль'Амет – дом родной." }, { 11.18, "Я не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражён опухолью, какой я в жизни не видывал..." }, { 20.68, "Она просто гигантская!" }, { 22.43, "Ты и так уже достаточно помог мне в моих трудах, но я попрошу тебя ещё об одной услуге." }, { 28.97, "Найди Дубохмура и сними эту опухоль." }, { 31.80, "Избавь мою землю от источника порчи!" } }, f = { { 0.00, "В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль'Амет – дом родной." }, { 11.01, "Я не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражён опухолью, какой я в жизни не видывал..." }, { 20.36, "Она просто гигантская!" }, { 22.09, "Ты и так уже достаточно помогла мне в моих трудах, но я попрошу тебя ещё об одной услуге." }, { 28.65, "Найди Дубохмура и сними эту опухоль." }, { 31.44, "Избавь мою землю от источника порчи!" } } }, t = { d = 25.3, v = "nightelf-male#59", n = { x = 275 }, c = { x = { { 0.00, "Я так и знал, что ты сумеешь избавить озеро от этой чудовищной твари." }, { 5.15, "Печальная история – Дубохмур некогда был великим вождём своих сородичей... но порча поражает всех подряд – и подлых, и благородных." }, { 14.92, "Величина этой опухоли в дрожь бросает, но я обязан исследовать её, чтобы понять, какая зараза терзает древесников." }, { 23.53, "Прими мою благодарность." } } } } },
    [2500] = { d = 31.7, g = 1, v = "dwarf-male", n = { m = 375, f = 379 }, c = { m = { { 0.00, "Герой, я хотел бы воспользоваться твоими услугами." }, { 3.47, "Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях." }, { 11.21, "Вот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей." }, { 19.13, "Очевидно, что их можно добыть у самих тварей, но если ты не любитель сражений, можешь попросить о помощи друзей." }, { 26.88, "Я неплохо заплачу, если ты принесёшь мне всё необходимое." }, { 30.71, "Что скажешь?" } }, f = { { 0.00, "Героиня, я хотел бы воспользоваться твоими услугами." }, { 3.58, "Я довольно известный алхимик, и мне понадобились кое-какие реактивы, которые можно отыскать в Бесплодных землях." }, { 11.29, "Вот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей." }, { 19.18, "Очевидно, что их можно добыть у самих тварей, но если ты не любительница сражений, можешь попросить о помощи друзей." }, { 27.13, "Я неплохо заплачу, если ты принесёшь мне всё необходимое." }, { 30.96, "Что скажешь?" } } }, t = { d = 22.2, v = "dwarf-male", n = { x = 252 }, c = { x = { { 0.00, "Молодец." }, { 0.65, "Этого мне должно хватить на некоторое время." }, { 3.88, "Вот обещанная плата." }, { 5.37, "Если ты не против получить новое задание, мне нужны ещё кое-какие реактивы." }, { 10.87, "Некоторые из них можно найти только на ульдаманском раскопе." }, { 15.20, "Добыть их нелегко, но и плата за помощь будет немалая." }, { 19.15, "Может быть, кое-что получше блестящих монет!" } } } } },
    [2501] = { d = 31.3, g = 1, v = "dwarf-male", n = { m = 345, f = 347 }, c = { m = { { 0.00, "Ты не раз меня выручал." }, { 1.74, "Я хотел бы дать тебе в награду рецепт зелья, которое ты уже пробовал, но взамен попрошу выполнить опасное поручение." }, { 10.44, "В этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опалённого дракона-стража." }, { 19.07, "Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность." }, { 24.55, "Когда наполнишь все три, принеси их мне." }, { 27.49, "Добудь мне кровь дракона, и я отдам тебе рецепт." } }, f = { { 0.00, "Ты не раз меня выручала." }, { 1.82, "Я хотел бы дать тебе в награду рецепт зелья, которое ты уже пробовала, но взамен попрошу выполнить опасное поручение." }, { 10.63, "В этом сундучке находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опалённого дракона-стража." }, { 19.31, "Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность." }, { 24.83, "Когда наполнишь все три, принеси их мне." }, { 27.79, "Добудь мне кровь дракона, и я отдам тебе рецепт." } } }, t = { d = 10.0, g = 1, v = "dwarf-male", n = { m = 98, f = 100 }, c = { m = { { 0.00, "Между нами, алхимиками, говоря, ты просто герой!" }, { 3.99, "Вот, возьми этот рецепт." }, { 6.01, "Пусть он принесёт тебе успех и богатство, как и мне!" } }, f = { { 0.00, "Между нами, алхимиками, говоря, ты просто героиня!" }, { 4.10, "Вот, возьми этот рецепт." }, { 6.12, "Пусть он принесёт тебе успех и богатство, как и мне!" } } } } },
    [2518] = { d = 35.1, v = "nightelf-female#51", n = { x = 390 }, c = { x = { { 0.00, "Некогда леди Сатра была дорога Элуне." }, { 2.91, "Эта изящная и чистая душой паучиха ткала серебряные свои нити под светом луны, ловя в свои сети вечерний туман." }, { 11.38, "Его серебристые капли обладали великой целительной силой, их хранили в этом храме." }, { 17.53, "Но недавно Сатру постигло безумие." }, { 20.11, "Теперь и её потомство под угрозой." }, { 22.63, "Найди леди Сатру, и положи конец её страданиям." }, { 26.20, "Она обитает у северных границ Тельдрассила, близ Родникового озера." }, { 31.16, "Возьми её серебристые паутинные железы и принеси их мне." } } }, t = { d = 5.8, v = "nightelf-female#51", n = { x = 55 }, c = { x = { { 0.00, "Лес оплакивает леди Сатру, но это надо было сделать." }, { 4.61, "Благодарю тебя." } } } } },
    [2519] = { d = 17.0, g = 1, v = "nightelf-female#53", n = { x = 163 }, c = { m = { { 0.00, "Одному некогда великому существу из нашего леса нужна помощь, герой." }, { 5.41, "Это трудное дело, но его надо сделать." }, { 8.53, "Пожалуйста, разыщи нашу жрицу А'моору, она всё тебе объяснит." }, { 13.39, "Ищи её к юго-востоку отсюда, в Храме Луны." } }, f = { { 0.00, "Одному некогда великому существу из нашего леса нужна помощь, героиня." }, { 5.64, "Это трудное дело, но его надо сделать." }, { 8.81, "Пожалуйста, разыщи нашу жрицу А'моору, она всё тебе объяснит." }, { 13.74, "Ищи её к юго-востоку отсюда, в Храме Луны." } } }, t = { d = 3.3, v = "nightelf-female#51", n = { x = 34 }, c = { x = { { 0.00, "Стало быть, тебя прислала сестра Аквинна?" } } } } },
    [2520] = { d = 25.2, g = 1, v = "nightelf-female#51", n = { m = 272, f = 272 }, c = { m = { { 0.00, "Теперь ты должен закончить дело, порученное тебе." }, { 3.75, "Возьми эти паутинные железы и принеси их в жертву во имя Элуны." }, { 8.56, "Пусть великая паучиха обретёт покой." }, { 11.24, "Внутри этого храма ты найдёшь центральный фонтан." }, { 14.92, "Там ты оставишь жертвоприношение." }, { 17.32, "Святые воды смоют порчу, что повергла Сатру в безумие." }, { 21.47, "Когда закончишь дело, возвращайся ко мне." } }, f = { { 0.00, "Теперь ты должна закончить дело, порученное тебе." }, { 3.87, "Возьми эти паутинные железы и принеси их в жертву во имя Элуны." }, { 8.84, "Пусть великая паучиха обретёт покой." }, { 11.60, "Внутри этого храма ты найдёшь центральный фонтан." }, { 15.40, "Там ты оставишь жертвоприношение." }, { 17.89, "Святые воды смоют порчу, что повергла Сатру в безумие." }, { 22.17, "Когда закончишь дело, возвращайся ко мне." } } }, t = { d = 9.5, g = 1, v = "nightelf-female#51", n = { m = 106, f = 108 }, c = { m = { { 0.00, "Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновлённым духом." }, { 6.47, "Да примет Элуна ту жертву, что ты принёс ей." } }, f = { { 0.00, "Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновлённым духом." }, { 6.33, "Да примет Элуна ту жертву, что ты принесла ей." } } } } },
    [2521] = { d = 47.0, g = 1, v = "creature/lostone", n = { x = 453 }, c = { m = { { 0.00, "Путник, может ли твой ничтожный мозг понять уникальность безупречной сферы из дренейского аметиста?" }, { 8.79, "Некоторые дренеи тратили всю свою жизнь на поиски одного-единственного кристалла – и всё лишь для того, чтобы встретиться с ужасной судьбой, не достигнув своей цели." }, { 21.96, "И вот ты стоишь перед Кум'ишей, знаешь, что требуется Кум'ише." }, { 27.56, "Ты всё ещё желаешь помочь?" }, { 29.68, "Отлично, герой..." }, { 31.15, "В любой момент своего путешествия через эти земли, если ты найдёшь безупречную сферу из дренейского аметиста, верни её мне и я вознагражу тебя так, как тебе не грезилось в самых безумных мечтаниях." } }, f = { { 0.00, "Путница, может ли твой ничтожный мозг понять уникальность безупречной сферы из дренейского аметиста?" }, { 7.92, "Некоторые дренеи тратили всю свою жизнь на поиски одного-единственного кристалла – и всё лишь для того, чтобы встретиться с ужасной судьбой, не достигнув своей цели." }, { 21.31, "И вот ты стоишь перед Кум'ишей, знаешь, что требуется Кум'ише." }, { 26.94, "Ты всё ещё желаешь помочь?" }, { 29.03, "Отлично, героиня..." }, { 30.61, "В любой момент своего путешествия через эти земли, если ты найдёшь безупречную сферу из дренейского аметиста, верни её мне и я вознагражу тебя так, как тебе не грезилось в самых безумных мечтаниях." } } }, t = { d = 12.9, v = "creature/lostone", n = { x = 107 }, c = { x = { { 0.00, "Не обманывают ли меня глаза?" }, { 2.76, "Невозможно!" }, { 3.89, "Откуда..." }, { 4.84, "Каким образом..." }, { 6.48, "Быть может, теперь откроется разлом и мы сможем вернуться на родину." } } } } },
    [2522] = { d = 29.3, g = 1, v = "creature/lostone", n = { x = 287 }, c = { m = { { 0.00, "Хотя заклинание портала ни к чему не привело, я по-прежнему надеюсь, что моя следующая попытка будет успешной." }, { 8.89, "Надежда дренеев столь же сильна, как твоя жадность до безделушек, герой." }, { 14.67, "Возвращайся в те проклятые земли и найди ещё одну безупречную сферу из дренейского аметиста." }, { 22.04, "Ну конечно же, брать или не брать на себя эту задачу – выбираешь только ты" } }, f = { { 0.00, "Хотя заклинание портала ни к чему не привело, я по-прежнему надеюсь, что моя следующая попытка будет успешной." }, { 8.89, "Надежда дренеев столь же сильна, как твоя жадность до безделушек, героиня." }, { 14.82, "Возвращайся в те проклятые земли и найди ещё одну безупречную сферу из дренейского аметиста." }, { 22.20, "Ну конечно же, брать или не брать на себя эту задачу – выбираешь только ты" } } }, t = { d = 20.2, v = "creature/lostone", n = { x = 169 }, c = { x = { { 0.00, "Просто поразительно." }, { 1.95, "Я сомневался, что ты сможешь найти ещё одну сферу, но вот она – пульсирует у меня в руках." }, { 10.41, "Отличная работа!" }, { 12.02, "Если найдёшь ещё – хоть я и считаю это невозможным, – приноси мне, и я снова тебя награжу." } } } } },
    [2523] = { t = { d = 14.0, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений." }, { 7.22, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [2541] = { d = 33.4, v = "nightelf-male", n = { x = 370 }, c = { x = { { 0.00, "Шаман племени Кривой Сосны, который живёт в этих местах, нашёл способ разлучать дух спящего друида с физическим телом." }, { 8.71, "Этот фурболг оживил моё тело и заставил его нападать на любого, кто пытается обследовать обитель Бен'этиль." }, { 16.62, "Теперь мне не выйти из Изумрудного Сна, и я не могу прекратить это!" }, { 21.50, "Помоги мне!" }, { 22.36, "У шамана Кривой Сосны есть при себе странный оберег, который он использует во время ритуала, и я хотел бы исследовать его." }, { 31.33, "Прошу тебя, принеси его мне!" } } }, t = { d = 11.0, v = "nightelf-male", n = { x = 94 }, c = { x = { { 0.00, "Прими мою благодарность." }, { 2.34, "Какая странная вещица..." }, { 4.68, "Я чувствую злую ауру, которую она излучает." }, { 8.86, "Очень мощное заклятие..." } } } } },
    [2561] = { d = 40.3, g = 1, v = "nightelf-male", n = { m = 419, f = 419 }, c = { m = { { 0.00, "Изучив этот оберег, я понял, что надо сделать." }, { 3.71, "Пожалуйста, возьми его и сделай, как я прошу." }, { 7.28, "Тебе придётся собраться с духом и проникнуть в самые глухие закоулки обители Бен'этиль." }, { 14.07, "Там ты найдёшь моё лишённое души тело..." }, { 17.08, "Хотя я и скорблю о том, что мне сейчас придётся поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны." }, { 27.38, "Чтобы я мог сбежать от них, ты должен уничтожить моё физическое тело." }, { 32.70, "Как только это будет сделано, обрати на мой труп силу амулета вуду." }, { 38.02, "После этого возвращайся ко мне." } }, f = { { 0.00, "Изучив этот оберег, я понял, что надо сделать." }, { 3.67, "Пожалуйста, возьми его и сделай, как я прошу." }, { 7.20, "Тебе придётся собраться с духом и проникнуть в самые глухие закоулки обители Бен'этиль." }, { 13.91, "Там ты найдёшь моё лишённое души тело..." }, { 16.88, "Хотя я и скорблю о том, что мне сейчас придётся поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны." }, { 27.05, "Чтобы я мог сбежать от них, ты должна уничтожить моё физическое тело." }, { 32.31, "Как только это будет сделано, обрати на мой труп силу амулета вуду." }, { 37.57, "После этого возвращайся ко мне." } } }, t = { d = 21.3, g = 1, v = "nightelf-male", n = { m = 187, f = 187 }, c = { m = { { 0.00, "Наконец-то я свободен от власти племени Кривой Сосны!" }, { 4.93, "Спасибо тебе." }, { 6.24, "Отныне мой дух обретёт вечный покой в объятиях Изумрудного Сна." }, { 11.91, "Возможно, однажды мы снова встретимся, юный герой." }, { 16.60, "Но пока прими эту награду в знак моей благодарности." } }, f = { { 0.00, "Наконец-то я свободен от власти племени Кривой Сосны!" }, { 4.87, "Спасибо тебе." }, { 6.17, "Отныне мой дух обретёт вечный покой в объятиях Изумрудного Сна." }, { 11.78, "Возможно, однажды мы снова встретимся, юная героиня." }, { 16.57, "Но пока прими эту награду в знак моей благодарности." } } } } },
    [2581] = { d = 30.4, v = "bloodelf-male", n = { x = 349 }, c = { x = { { 0.00, "Хорошо известно, что челюсти гиены невероятно сильны, но чтобы они были способны прокусить три дюйма ториевой стали?" }, { 8.59, "Невозможно, невероятно, и тем не менее я видел это своими глазами." }, { 13.44, "Отправляйся в Выжженные земли и принеси мне три челюсти гиены-ухмыльника." }, { 18.75, "А пока ищешь гиен, высматривай также кабанов и скорпоков: для дополнения к изначальной эссенции требуется также два обожжённых лёгких вепря и одна клешня скорпока." } } }, t = { d = 19.0, v = "bloodelf-male", n = { x = 227 }, c = { x = { { 0.00, "Как самочувствие?" }, { 1.19, "Ты излучаешь ауру гиены-ухмыльника – силу, с которой никто из смертных не сравнится!" }, { 7.10, "К несчастью, из принесённых тобой компонентов я смогу сделать эссенции только на одну таблетку." }, { 13.70, "Если тебе понадобится ещё одна таблетка, мне нужно будет больше компонентов." } } } } },
    [2582] = { d = 30.1, v = "bloodelf-male", n = { x = 358 }, c = { x = { { 0.00, "О, добро пожаловать, давно не виделись." }, { 2.81, "Похоже, тебе понравился эффект крепкого, действенного зелья, извлечённого из гиены-ухмыльника." }, { 9.44, "Однако осторожнее: если непосредственным эффектом является титанический прилив сил, то долгосрочный эффект, сказывающийся на твоём духе и рассудке, может быть опасным." }, { 21.11, "Кстати говоря, тебе нужно ещё зелья?" }, { 23.78, "Тогда принеси мне ещё три челюсти гиены, два обожжённых лёгких вепря и одну клешню скорпока." } } }, t = { d = 12.2, v = "bloodelf-male", n = { x = 138 }, c = { x = { { 0.00, "Вот, возьми!" }, { 0.91, "И помни, что использовать это зелье надо расчётливо." }, { 4.69, "Если понадобится ещё, приходи ко мне после того, как израсходуешь порцию, которую я тебе только что выдал." } } } } },
    [2583] = { d = 35.8, v = "bloodelf-male", n = { x = 420 }, c = { x = { { 0.00, "В этих опалённых землях водятся два вида кабанов: углегривый кабан и зловепрь." }, { 5.57, "Судя по всему, стойкость этих тварей такова, что делает их почти неуязвимыми, поскольку другие животные считают, что вепрей слишком трудно убить, следовательно, на них не стоит даже тратить усилий." }, { 19.66, "Нам нужно провести дальнейшие исследования." }, { 22.73, "Если ты принесёшь мне три обожжённых лёгких вепря, две клешни скорпока и один мозг василиска, я создам отличный эликсир на основе вытяжки из этого материала." }, { 33.68, "И первым делом проверю на тебе!" } } }, t = { d = 8.3, v = "bloodelf-male", n = { x = 90 }, c = { x = { { 0.00, "Дух вепря озаряет твоё существование!" }, { 2.85, "Может быть, ты веришь, что тебе дарована неуязвимость, как и этим тварям?" } } } } },
    [2584] = { d = 33.4, v = "bloodelf-male", n = { x = 382 }, c = { x = { { 0.00, "Когда я впервые выдал тебе этот эликсир, я уже понимал, что одна-две порции не удовлетворят твой аппетит." }, { 7.59, "Даже сейчас я вижу в твоих глазах этот голод." }, { 11.00, "Сей состав имеет одно побочное свойство – он даёт привыкание, которому, похоже, не может сопротивляться даже самая сильная воля." }, { 20.19, "Что ж, пусть так!" }, { 21.35, "Если тебе требуется ещё порция смеси с лёгочной вытяжкой, отправляйся обратно в пустоши и принеси мне три обожжённых лёгких вепря, две клешни скорпока и один мозг василиска." } } }, t = { d = 15.9, v = "bloodelf-male", n = { x = 197 }, c = { x = { { 0.00, "Хочу предупредить тебя, не пытайся смешивать созданные мною составы." }, { 4.81, "Химические свойства состава, недавно принятого тобою, всегда возобладают над предшествующими заклинаниями, таким образом, эффект другого зелья будет сведён на нет." } } } } },
    [2585] = { d = 35.1, v = "bloodelf-male", n = { x = 425 }, c = { x = { { 0.00, "Тебе приходилось видеть их сражение?" }, { 2.48, "Я имею в виду скорпоков." }, { 4.18, "Видеть грациозность и ловкость, с которой они движутся?" }, { 7.94, "Решительность, с которой они наносят удары?" }, { 10.91, "Если бы мы только могли выделить эту ловкость и заключить её в оболочку, мы были бы богаты вне всякого... я хочу сказать... это было бы благо для всего научного сообщества." }, { 22.54, "Помоги мне, и я выделю для тебя порцию настойки." }, { 25.81, "Для того чтобы создать стабильное вещество, мне потребуется три клешни скорпока, две меры потрохов стервятника и одно обожжённое лёгкое вепря." } } }, t = { d = 16.2, v = "bloodelf-male", n = { x = 179 }, c = { x = { { 0.00, "Потрясающе." }, { 0.89, "Анализ этой эссенции был самым сложным." }, { 3.99, "Возьми щепотку этой солевой вытяжки и положи её под язык." }, { 8.46, "Ты испытаешь лёгкое чувство эйфории, после которого наступит состояние невероятной ловкости и быстроты." } } } } },
    [2586] = { d = 17.6, g = 1, v = "bloodelf-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Ты жив!" }, { 0.53, "Это поистине хорошая новость!" }, { 2.76, "Полагаю, тебе нужно ещё скорпоковой настойки?" }, { 6.12, "Отлично, тогда снова ступай в пустоши и не возвращайся, пока не заполучишь три клешни скорпока, две меры потрохов стервятника и одно обожжённое лёгкое вепря." } }, f = { { 0.00, "Ты жива!" }, { 0.66, "Это поистине хорошая новость!" }, { 2.91, "Полагаю, тебе нужно ещё скорпоковой настойки?" }, { 6.29, "Отлично, тогда снова ступай в пустоши и не возвращайся, пока не заполучишь три клешни скорпока, две меры потрохов стервятника и одно обожжённое лёгкое вепря." } } }, t = { d = 14.6, v = "bloodelf-male", n = { x = 177 }, c = { x = { { 0.00, "Отличная работа." }, { 1.19, "Вот одна мера настойки для тебя, а оставшиеся девять будут использованы для моих исследований." }, { 7.73, "В любой момент, когда тебе понадобится скорпоковая настойка, возвращайся ко мне, и мы заключим сделку." } } } } },
    [2601] = { d = 35.6, v = "bloodelf-female", n = { x = 421 }, c = { x = { { 0.00, "Эти пустоши кишат василисками Красного камня." }, { 3.28, "Эти василиски отлично приспособились к местным условиям, их тут больше, чем любых других диких животных." }, { 10.61, "Я наблюдала издали, как они охотятся и ведут свою повседневную жизнь – мыслительный процесс у этих тварей, похоже, куда более сложный, чем у некоторых из тех существ, которых мы называем разумными." }, { 24.38, "Я должна изучить их мозги!" }, { 26.27, "Раздобудь для меня десять их мозгов." }, { 28.86, "Однако для опытов мне понадобятся ещё потроха двух стервятников, которые дадут основу для раствора." } } }, t = { d = 13.0, v = "bloodelf-female", n = { x = 144 }, c = { x = { { 0.00, "Замечательно!" }, { 1.02, "Предлагаю тебе отведать на вкус внутреннюю суть василисков красного камня." }, { 6.62, "Если этот состав тебе понравится, всегда можно сделать ещё... за определённую плату." } } } } },
    [2602] = { d = 17.4, v = "bloodelf-female", n = { x = 190 }, c = { x = { { 0.00, "Твоё сосредоточение ушло так скоро?" }, { 2.75, "Нужно провести ещё больше исследований!" }, { 5.86, "Ах да, цена остаётся прежней." }, { 8.12, "Отправляйся в Выжженные земли и возвращайся ко мне с десятью мозгами тварей Красного Камня и потрохами двух стервятников." } } }, t = { d = 16.2, v = "bloodelf-female", n = { x = 175 }, c = { x = { { 0.00, "Да, да, дай мне минутку, и нужные тебе составы будут готовы к употреблению." }, { 5.71, "Вот, возьми... и помни, что нельзя даже пытаться употреблять эти экспериментальные составы слишком часто." }, { 13.76, "Результат будет катастрофическим." } } } } },
    [2603] = { d = 34.2, g = 1, v = "bloodelf-female", n = { x = 387 }, c = { m = { { 0.00, "В этих опалённых землях смерть воистину крылата, герой." }, { 4.05, "Я много раз наблюдала, как чёрные убийцы и костеглоды пируют на телах павших исследователей – иногда пожирая наиболее отвратительные и разложившиеся останки трупов." }, { 15.99, "Удивительно всё же, как их внутренние органы справляются с заразой, царящей в этих землях?" }, { 22.56, "Помоги мне в моих исследованиях!" }, { 24.95, "Мне нужны потроха!" }, { 26.34, "Понадобятся также две челюсти гиены в качестве основы для состава." }, { 31.25, "Твои усилия будут вознаграждены вдвойне." } }, f = { { 0.00, "В этих опалённых землях смерть воистину крылата, героиня." }, { 4.15, "Я много раз наблюдала, как чёрные убийцы и костеглоды пируют на телах павших исследователей – иногда пожирая наиболее отвратительные и разложившиеся останки трупов." }, { 16.02, "Удивительно всё же, как их внутренние органы справляются с заразой, царящей в этих землях?" }, { 22.55, "Помоги мне в моих исследованиях!" }, { 24.93, "Мне нужны потроха!" }, { 26.31, "Понадобятся также две челюсти гиены в качестве основы для состава." }, { 31.19, "Твои усилия будут вознаграждены вдвойне." } } }, t = { d = 18.2, v = "bloodelf-female", n = { x = 195 }, c = { x = { { 0.00, "Превосходно!" }, { 0.96, "Я немедленно приступаю к работе." }, { 3.43, "Возможно, удастся найти лекарство от множества недугов, существующих в этом мире!" }, { 9.67, "Ах да, твоя награда – конечно, если тебе опять понадобится зелье, возвращайся ко мне, я дам тебе новое поручение." } } } } },
    [2604] = { d = 19.2, v = "bloodelf-female", n = { x = 213 }, c = { x = { { 0.00, "Я вижу, внутреннее пламя угасло." }, { 2.47, "Как по-твоему, длилась ли эта духовная эйфория хотя бы час?" }, { 6.87, "Если ты желаешь получить ещё зелья из потрошков, то изволь снабдить меня сырьём!" }, { 12.81, "Отправляйся обратно." }, { 14.34, "И не возвращайся, пока не наберёшь десять мер потрохов и две челюсти." } } }, t = { d = 18.9, v = "bloodelf-female", n = { x = 234 }, c = { x = { { 0.00, "Возможно, когда-нибудь я смогу выделить активные компоненты этой эссенции и получить куда более эффективный результат." }, { 8.18, "К несчастью, пока тебе придётся довольствоваться тем, что я в состоянии сделать на настоящий момент." }, { 14.93, "Если понадобится ещё зелье из потрошков, возвращайся ко мне." } } } } },
    [2605] = { d = 23.4, v = "goblin-male", n = { x = 238 }, c = { x = { { 0.00, "Слышь, у меня возникла мысль." }, { 2.26, "Я слышал о странных тварях, собирателях росы, живущих на юго-западе..." }, { 7.84, "Говорят, они хранят воду в особых железах." }, { 11.30, "Мне кажется, что из этих желёз я бы сделал напиток, который утолил бы мою жажду!" }, { 17.59, "Ты не поможешь мне?" }, { 19.07, "Поищи кактусовый сад, именно там пасутся собиратели росы." } } }, t = { d = 4.4, v = "goblin-male", n = { x = 32 }, c = { x = { { 0.00, "Чудесно!" }, { 0.95, "Дай мне железу – я хочу выпить её!" } } } } },
    [2606] = { d = 30.8, v = "goblin-male", n = { x = 306 }, c = { x = { { 0.00, "Фу!" }, { 0.28, "Ну и гадость!" }, { 1.32, "Да, идея была неудачная…" }, { 3.26, "Стой, что такое?" }, { 4.51, "О, знаю, ты считаешь, что не стоит отказываться от этой штуки." }, { 9.30, "Ладно." }, { 9.85, "Эээ..." }, { 10.41, "У меня есть идея!" }, { 11.80, "Гениально!" }, { 12.63, "Отнеси эту росу моей подруге Поливалке – она отличный повар." }, { 17.49, "Скажи, что мы тут задумали, пусть придумает, как улучшить вкус." }, { 22.21, "Я хочу сказать, что такая дрянь по крайней мере, должна пробирать до мозга костей..." }, { 28.73, "А пока ей до мозга далеко..." } } }, t = { d = 10.2, v = "goblin-female#63", n = { x = 102 }, c = { x = { { 0.00, "Синь отличный парень, не пойми меня превратно – только немного... эксцентричный, что ли." }, { 6.95, "И разумеется, ему опять нужна моя помощь." } } } } },
    [2607] = { d = 14.7, v = "human-male", n = { x = 154 }, c = { x = { { 0.00, "Похоже, что информации у вас даже больше, чем я ожидал." }, { 4.22, "Как-то странно всё оборачивается." }, { 6.78, "Лекарство?" }, { 7.61, "Хм-м..." }, { 8.16, "Спуститесь в подвал и поговорите с Доком Миксиль-Пиксилем – он, вероятно, сможет помочь." } } }, t = { d = 6.5, v = "gnome-male", n = { x = 74 }, c = { x = { { 0.00, "Как раз вовремя!" }, { 1.20, "Просто положите сыр на стол и проваливайте." }, { 4.35, "Осборн заплатит вам на выходе." } } } } },
    [2608] = { d = 29.9, g = 1, v = "gnome-male", n = { m = 285, f = 284 }, c = { m = { { 0.00, "Ох, вы так выглядите – точь-в-точь мертвец." }, { 3.43, "Поправочка – я видел мертвецов, вы выглядите ещё хуже." }, { 7.80, "Вы, сударь, будете предсмертной отрыжкой самой смерти." }, { 12.25, "Ха!" }, { 12.54, "Слышал, Ноарм?" }, { 13.78, "Запиши-ка это!" }, { 15.02, "Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови." }, { 21.36, "Не беспокойтесь, больно лишь первые... раз пятьдесят или около того..." }, { 27.05, "Ложитесь, и приступим к лечению!" } }, f = { { 0.00, "Ох, вы так выглядите – точь-в-точь мертвец." }, { 3.48, "Поправочка – я видел мертвецов, вы выглядите ещё хуже." }, { 7.93, "Вы, детка, будете предсмертной отрыжкой самой смерти." }, { 12.37, "Ха!" }, { 12.67, "Слышал, Ноарм?" }, { 13.93, "Запиши-ка это!" }, { 15.19, "Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови." }, { 21.63, "Не беспокойтесь, больно лишь первые... раз пятьдесят или около того..." }, { 27.41, "Ложитесь, и приступим к лечению!" } } }, t = { d = 7.4, v = "gnome-male", n = { x = 86 }, c = { x = { { 0.00, "Позвольте, я минутку посовещаюсь со своими коллегами." }, { 3.85, "Доктор Монтгомери, мистер Ноарм, все на консилиум!" } } } } },
    [2609] = { d = 37.4, v = "gnome-male", n = { x = 447 }, c = { x = { { 0.00, "Однозначно." }, { 0.79, "У вас чтотит." }, { 1.70, "К счастью, от чтотита у меня есть средство." }, { 4.62, "И вот что мне понадобится для его изготовления: букетик простых полевых цветов, одна освинцованная колба, одна бронзовая трубка и последнее – но немаловажное! – нитка светлого зеленовато-жёлтого шёлка." }, { 18.00, "Старушка Эмма оставила для меня катушку таких ниток в \"Тончайшей пряже\"." }, { 22.99, "Эту лавку можно найти, если идти вдоль каналов." }, { 26.33, "А теперь поспешите, и постарайтесь ни к кому не прикасаться, пока вас не вылечат." }, { 31.74, "Кстати, доктор Монтгомери сказал, что вам нужно душ принять... это его слова, не мои!" } } }, t = { d = 20.1, v = "gnome-male", n = { x = 201 }, c = { x = { { 0.00, "Что я делаю?" }, { 0.99, "А на что похоже то, что я делаю?" }, { 3.48, "Я продумываю, как вылечить ваш чтотит!" }, { 6.46, "И нечего так возмущённо на меня смотреть!" }, { 9.65, "Ещё несколько секунд..." }, { 11.50, "Готово!" }, { 12.14, "Побрызгайте на себя этим лечебным средством с... эээ... необыкновенным запахом – и вы в полном порядке!" } } } } },
    [2621] = { d = 44.5, v = "orc-male", n = { x = 419 }, c = { x = { { 0.00, "Сожалею." }, { 0.76, "Это всё, что у меня есть." }, { 2.87, "Одно неверное решение, приведшее к массе плохих последствий." }, { 8.02, "Если бы я только дождался тех приказов!" }, { 11.35, "Может быть, там было бы сказано подробно обо всех ужасах, ожидающих нас в этих проклятых землях?" }, { 19.44, "Может быть, нам дали бы другое задание или выслали бы подкрепление?" }, { 25.12, "Но в конечном итоге, это моя вина." }, { 28.14, "Всё это – моя вина." }, { 29.88, "И вот я стою здесь, ожидая приказов." }, { 32.91, "Я должен знать." }, { 34.20, "Я должен знать, каковы эти приказы." }, { 37.22, "Командир-посланник Руаг находится в Каменоре." }, { 41.08, "Найди его и узнай, что стало с приказами." } } }, t = { d = 18.5, v = "orc-male#60", n = { x = 177 }, c = { x = { { 0.00, "Хватка Тралла..." }, { 1.76, "Эта история всё ещё свежа в моей памяти." }, { 5.92, "*Командир Руаг качает головой.*" }, { 8.72, "Ужасная вещь – то, что случилось с этим подразделением." }, { 12.76, "Орда потеряла немало своих лучших солдат, когда этот батальон был уничтожен." } } } } },
    [2622] = { d = 37.8, v = "orc-male#60", n = { x = 388 }, c = { x = { { 0.00, "Приказы?" }, { 0.70, "Зачем тебе понадобились эти приказы?" }, { 3.63, "Что ты подразумеваешь?" }, { 5.31, "Конечно, я передал эти приказы!" }, { 7.82, "Солдаты, с которыми я их послал, попали в засаду и были безжалостно забиты до смерти мурлоками." }, { 15.22, "Выжил только один – если это называется выжить." }, { 19.06, "Он едва может говорить, не может ходить, его приходится кормить через трубку." }, { 25.21, "Если хочешь знать, что случилось с приказами, поговори с Бенгором." }, { 30.31, "Я знаю, он где-то неподалёку... и вот ещё что, следи, куда суёшь свой нос – его ведь и откусить могут." } } }, t = { d = 4.0, v = "orc-male", n = { x = 19 }, c = { x = { { 0.00, "Болот... ный... гово... говорун..." } } } } },
    [2623] = { d = 25.2, v = "orc-male", n = { x = 211 }, c = { x = { { 0.00, "Приказы были отданы командиром-посланником." }, { 4.12, "Мы приняли... приняли приказы." }, { 6.98, "На пути в Выжженные земли – засада." }, { 10.34, "Мурлоки... много мурлоков..." }, { 13.03, "Одного звали Болотный Говорун." }, { 15.98, "Вырвал приказы у меня из рук, ударил копьём мне в голову." }, { 21.27, "Восток... пещера..." }, { 23.04, "*Бенгор теряет сознание.*" } } }, t = { d = 15.1, v = "orc-male", n = { x = 159 }, c = { x = { { 0.00, "Это хуже, чем я ожидал." }, { 1.90, "Девятнадцать моих соратников были бы избавлены от мучений, которым они подвергаются." }, { 8.51, "Если бы я только действовал не столь неразумно!" }, { 12.17, "Помоги им!" }, { 13.02, "Я бессилен что-либо сделать." } } } } },
    [2641] = { d = 34.9, v = "goblin-female#63", n = { x = 372 }, c = { x = { { 0.00, "Когда я была маленькая, у нас в семье готовила моя сестра." }, { 4.46, "Это было ужасно!" }, { 5.82, "Половину её творений я даже в рот взять не могла... пока не отыскала свой \"маленький секрет\"!" }, { 12.71, "Добавь его в любую еду и... получится вкуснятина!" }, { 16.50, "Что за секрет, спросишь ты." }, { 18.53, "Это гриб, называемый фиалковый траган." }, { 21.44, "Если хочешь помочь мне превратить эту дрянь во что-то съедобное, отправляйся во Внутренние земли и поищи там маленькое озерцо." }, { 30.90, "И не забывай, фиалковый траган растёт только под водой." } } }, t = { d = 6.6, v = "goblin-female#63", n = { x = 42 }, c = { x = { { 0.00, "Ага, вот и он!" }, { 1.63, "Отлично выглядит, хоть сейчас..." }, { 5.29, "Ха-ха, шучу!" } } } } },
    [2661] = { d = 6.5, v = "goblin-female#63", n = { x = 56 }, c = { x = { { 0.00, "Вот фиалковый порошок." }, { 2.08, "Отнеси его Синю и скажи ему, что он мой должник!" } } }, t = { d = 6.1, v = "goblin-male", n = { x = 61 }, c = { x = { { 0.00, "Фиалковый порошок, значит?" }, { 2.08, "Дай-ка попробую – хуже всё равно не будет, это ясно!" } } } } },
    [2662] = { d = 10.0, v = "goblin-male", n = { x = 107 }, c = { x = { { 0.00, "А теперь вмешаем этот порошок в росу." }, { 2.99, "Заходи через пару минут... когда я доведу до совершенства великолепный эликсир Гогельмогеля!" } } }, t = { d = 24.2, v = "goblin-male", n = { x = 249 }, c = { x = { { 0.00, "Попробуй!" }, { 0.79, "Невероятно вкусно!!!" }, { 2.45, "Я знал, что у меня всё получится..." }, { 5.18, "Ещё раз спасибо за помощь, только встань в сторонке!" }, { 9.28, "Ты не даёшь прохода будущим покупателям." }, { 12.45, "Я заработаю миллионы на неподражаемом эликсире Гогельмогеля, миллионы!" }, { 17.99, "Что такое?" }, { 18.85, "Поливалка говорит, что я её должник?" }, { 21.73, "Ох, такая шутница эта Поливалка!" } } } } },
    [2681] = { d = 19.0, v = "orc-male", n = { x = 199 }, c = { x = { { 0.00, "Одних лишь твоих сил не хватит, чтобы одолеть Разелиха и его приспешников." }, { 6.03, "Собери подходящую группу искателей приключений и освободи моих подчинённых от вечных мук!" }, { 13.16, "Тебе нужно разбить восемнадцать камней." }, { 16.43, "Сражайся отважно и умри с честью." } } }, t = { d = 15.2, v = "orc-male", n = { x = 128 }, c = { x = { { 0.00, "Тебе это удалось!" }, { 1.84, "Несчастные, истерзанные души наконец-то обретут покой." }, { 7.20, "Но наша работа ещё не завершена." }, { 10.36, "Нам ещё многое нужно обсудить и ещё больше сделать." } } } } },
    [2701] = { d = 11.8, v = "tauren-male", n = { x = 119 }, c = { x = { { 0.00, "Пожалуйста, забери отсюда реликвию древности." }, { 3.75, "Мы больше ни на что не можем использовать её." }, { 7.35, "Может быть, она послужит тебе в борьбе против Легиона." } } }, t = { d = 4.2, v = "narrator", n = { x = 40 }, c = { x = { { 0.00, "Искристый блеск на какое-то время ослепляет вас." } } } } },
    [2702] = { d = 7.4, g = 1, v = "orc-male", n = { m = 59, f = 60 }, c = { m = { { 0.00, "Твои благородство и героизм – высокая честь для меня." }, { 5.23, "Ты оказал честь и им..." } }, f = { { 0.00, "Твои благородство и героизм – высокая честь для меня." }, { 5.23, "Ты оказала честь и им..." } } }, t = { d = 8.2, v = "tauren-male", n = { x = 72 }, c = { x = { { 0.00, "Поистине, ты оказываешь честь нам всем." }, { 3.80, "Одних лишь благодарностей будет недостаточно." } } } } },
    [2721] = { d = 37.4, v = "orc-male", n = { x = 375 }, c = { x = { { 0.00, "Как только завершается одна часть твоих приключений, начинается другая." }, { 5.81, "Один из моих подчинённых пропал без вести – затерялся где-то в Выжженных землях." }, { 12.36, "Я, конечно же, говорю о лейтенанте Кирите." }, { 15.81, "Как я упоминал ранее, мы оба были в плену у Аллистария и подвергались мучениям, но увы несчастному Кириту – его сила воли оказалась недостаточно велика." }, { 28.32, "Из своей клетки я слышал происходящее: крики боли разносились по пещерным залам." }, { 34.94, "С тех пор Кирита и след простыл." } } }, t = { d = 3.2, v = "scourge-male", n = { x = 22 }, c = { x = { { 0.00, "Требор?" }, { 0.95, "Тебя послал Требор?" } } } } },
    [2741] = { t = { d = 16.1, v = "narrator", n = { x = 158 }, c = { x = { { 0.00, "Вы кладёте в машину яйцо гиппогрифа." }, { 3.12, "Раздаётся несколько гудков и странный механический шум." }, { 7.81, "Похоже, яйцеметр взвесил, измерил и упаковал ваше яйцо." }, { 12.73, "Вот это называется быстрое обслуживание!" } } } } },
    [2742] = { d = 24.2, g = 1, v = "troll-male", n = { m = 217, f = 217 }, c = { m = { { 0.00, "Эй, герой!" }, { 0.85, "Рин'джи потерял топор, и его схватили!" }, { 3.98, "Пожалуйста, помоги Рин'джи сбежать." }, { 6.82, "Я знаю, что не каждый герой любит троллей, но я тебя очень прошу!" }, { 12.08, "Мне надо выйти отсюда!" }, { 13.93, "У меня кое-что есть, и очень хорошее, если поможешь мне, я тебе это подарю..." }, { 20.11, "Рин'джи спрятал свой секрет у Отвесных скал." } }, f = { { 0.00, "Эй, героиня!" }, { 1.02, "Рин'джи потерял топор, и его схватили!" }, { 4.21, "Пожалуйста, помоги Рин'джи сбежать." }, { 7.11, "Я знаю, что не каждая героиня любит троллей, но я тебя очень прошу!" }, { 12.63, "Мне надо выйти отсюда!" }, { 14.52, "У меня кое-что есть, и очень хорошее, если поможешь мне, я тебе это подарю..." }, { 20.84, "Рин'джи спрятал свой секрет у Отвесных скал." } } }, t = { d = 10.7, v = "narrator", n = { x = 117 }, c = { x = { { 0.00, "Эта табличка, наверное, и есть тот самый \"секрет\", о котором говорил Рин'джи." }, { 5.77, "Она покрыта странными письменами, которые вам совершенно не знакомы." } } } } },
    [2743] = { d = 44.3, g = 1, v = "scourge-male", n = { x = 426 }, c = { m = { { 0.00, "Не будем тратить слов, герой; моё время здесь ограничено." }, { 4.82, "Тебе следует уничтожить троицу силы, связанную с повелителем демонов Разелихом." }, { 11.64, "Это деяние не настолько просто, как задача по освобождению проклятой души." }, { 17.92, "*Кирит ухмыляется.*" }, { 19.76, "Видишь ли, каждый из прислужников Разелиха носит на шее треть амулета, при помощи которого был создан Разелих." }, { 29.03, "Тот же самый амулет понадобится тебе для призвания сего архидемона." }, { 34.73, "Возвращайся к Требору и поведай ему, что требуется для призвания Разелиха." }, { 40.96, "Он подскажет тебе, что делать дальше." } }, f = { { 0.00, "Не будем тратить слов, героиня; моё время здесь ограничено." }, { 5.18, "Тебе следует уничтожить троицу силы, связанную с повелителем демонов Разелихом." }, { 12.27, "Это деяние не настолько просто, как задача по освобождению проклятой души." }, { 18.80, "*Кирит ухмыляется.*" }, { 20.64, "Видишь ли, каждый из прислужников Разелиха носит на шее треть амулета, при помощи которого был создан Разелих." }, { 29.70, "Тот же самый амулет понадобится тебе для призвания сего архидемона." }, { 35.27, "Возвращайся к Требору и поведай ему, что требуется для призвания Разелиха." }, { 41.36, "Он подскажет тебе, что делать дальше." } } }, t = { d = 6.6, v = "orc-male", n = { x = 74 }, c = { x = { { 0.00, "Повелитель демонов проявляет хитрость почти столь же расчётливую, как и его жестокость." } } } } },
    [2744] = { d = 37.8, v = "orc-male", n = { x = 403 }, c = { x = { { 0.00, "Эта троица находится под покровительством Разелиха." }, { 4.03, "В обмен на их службу Разелих даровал каждому из них почти безграничную власть над Выжженными землями." }, { 11.89, "Кусочки амулета связаны с жизненной силой их владельцев и дают им бессмертие." }, { 17.97, "Пока они остаются в Выжженных землях, их нельзя убить и их жизнь продлится до конца мира." }, { 25.04, "Но есть некто, способный оказать тебе помощь в дальнейшем." }, { 29.64, "Отправляйся в Азшару и найди там охотника на демонов, Лорамуса Многонога." }, { 35.37, "Поиск следует вести на островах." } } }, t = { d = 6.7, v = "nightelf-male#55", n = { x = 69 }, c = { x = { { 0.00, "Я помогу тебе." }, { 1.22, "Однако мне кажется, что ты не совсем понимаешь, против чего сражаешься." } } } } },
    [2745] = { d = 36.6, v = "human-male#50", n = { x = 416 }, c = { x = { { 0.00, "Хм-м, интересная история, причём не из тех, на которые можно наплевать." }, { 4.88, "Да, помочь-то я вам могу, но то, что вам нужно будет сделать, это свершить правосудие... частично незаконным путём, если уж вы хотите довести дело до конца." }, { 15.78, "С Лесковаром и Марзоном нужно разобраться – и быстро." }, { 19.52, "Как думаете, вы на это способны?" }, { 21.81, "Решать вам." }, { 22.63, "Если да, то поскорее отправляйтесь в крепость и найдите там моего старинного друга – гнома по имени Тирион." }, { 30.17, "Он уже пару недель как наблюдает за Лесковаром." }, { 33.53, "Он сможет помочь вам покончить с этим делом." } } }, t = { d = 29.5, v = "gnome-male", n = { x = 331 }, c = { x = { { 0.00, "Какого?!" }, { 0.65, "Не подкрадывайтесь ко мне вот так!" }, { 2.97, "И говорите тише!" }, { 4.20, "На кой вы, спрашивается, во имя Теней, так ко мне подкрадываетесь?" }, { 8.79, "Не видите, что ли – я занят, безмозглое вы создание!" }, { 12.47, "Что вы имеете в виду, спрашивая, что я делаю?" }, { 15.70, "Жду открытия следующего Тёмного портала, а вы что подумали?" }, { 19.84, "Выкладывайте, с чем пришли, и валите отсюда... пока стражники не заметили, что мы тут вдвоём в кустах прячемся." }, { 27.66, "Мне нужно блюсти репутацию." } } } } },
    [2746] = { d = 36.5, v = "gnome-male", n = { x = 419 }, c = { x = { { 0.00, "Триас хочет поторопить события, так?" }, { 2.58, "Ладно, мы это сделаем, но сейчас я не готов." }, { 5.73, "И, кстати, сложную часть я беру на себя, а ручки пачкать будете вы, это понятно?" }, { 11.39, "Отлично." }, { 12.02, "Значит, мне нужно, чтобы вы мне кое-что принесли, чтобы я смог воплотить в жизнь свой план." }, { 18.25, "У меня есть мысль об отличной маскировке, при помощи которой этот робот-шпион пройдёт мимо стражников." }, { 25.36, "Принесите мне немного шёлка и пару яблок." }, { 28.25, "Где достать шёлк – думайте сами, а вот подходящие яблоки есть у Клары в её маленьком хозяйстве сразу за городской чертой." } } }, t = { d = 21.5, v = "gnome-male", n = { x = 258 }, c = { x = { { 0.00, "Это отлично подойдёт." }, { 1.45, "Прекрасная работа." }, { 2.72, "Вся остальная амуниция у меня в сумке..." }, { 5.45, "Слава Свету, у меня есть приятель-портной, сшивший мне шёлковую сумку." }, { 10.16, "А то мне бы уже некуда было рассовывать свои вещи." }, { 13.61, "Прежде чем мой робот-шпион отправится куда надо, давайте обговорим детали, чтобы вы знали, что вам нужно будет делать." } } } } },
    [2747] = { t = { d = 8.2, g = 1, v = "gnome-female", n = { m = 71, f = 74 }, c = { m = { { 0.00, "Значит, ты смог добыть такое яйцо – поразительно!" }, { 4.77, "Сегодня ты совершил настоящий подвиг!" } }, f = { { 0.00, "Значит, ты смогла добыть такое яйцо – поразительно!" }, { 4.83, "Сегодня ты совершила настоящий подвиг!" } } } } },
    [2748] = { t = { d = 10.6, v = "gnome-female", n = { x = 104 }, c = { x = { { 0.00, "Очень хорошо." }, { 1.18, "Скоро я пошлю это яйцо в Дарнасс, надеюсь, из него вскоре вылупится гиппогриф!" }, { 7.76, "Прими это в знак моей благодарности." } } } } },
    [2749] = { t = { d = 17.7, g = 1, v = "gnome-female", n = { m = 170, f = 170 }, c = { m = { { 0.00, "Значит, ты нашёл обычное яйцо?" }, { 2.50, "Пожалуйста, дай его мне..." }, { 4.62, "Будем надеяться на лучшее." }, { 6.83, "Прими эту награду, это всё, что у меня есть." }, { 10.49, "Если снова окажешься в Фераласе, помни, что я всегда готова купить найденные тобой яйца." } }, f = { { 0.00, "Значит, ты нашла обычное яйцо?" }, { 2.52, "Пожалуйста, дай его мне..." }, { 4.61, "Будем надеяться на лучшее." }, { 6.78, "Прими эту награду, это всё, что у меня есть." }, { 10.38, "Если снова окажешься в Фераласе, помни, что я всегда готова купить найденные тобой яйца." } } } } },
    [2750] = { t = { d = 20.3, v = "gnome-female", n = { x = 193 }, c = { x = { { 0.00, "Боюсь, я тебя не порадую." }, { 2.14, "Это яйцо уже не спасти." }, { 4.21, "Я могу забрать его у тебя и поступить с ним, как должно." }, { 8.87, "Не огорчайся, всех нам всё равно не спасти." }, { 12.34, "Если ты снова окажешься в Фераласе, попробуй ещё раз." }, { 16.70, "Принеси ещё одно яйцо для Супер Яйц-О-Матика!" } } } } },
    [2751] = { d = 36.7, v = "orc-male", n = { x = 334 }, c = { x = { { 0.00, "Двадцать поколений Омошей держали в руках этот молот!" }, { 4.93, "Сколько тонн металла мы перековали!" }, { 8.09, "Но, увы, на мне наш род завершится." }, { 11.16, "У меня нет потомства." }, { 13.10, "Я не могу допустить, чтобы тайные чертежи и приёмы Омошей умерли вместе со мной!" }, { 20.30, "Докажи Орокку, что ты годишься в кузнецы." }, { 24.02, "Принеси ему два узорчатых бронзовых боевых браслета, два бронзовых больших меча и два острых когтя." }, { 33.00, "Принеси их Орокку, и мы продолжим обучение." } } }, t = { d = 22.9, v = "orc-male", n = { x = 203 }, c = { x = { { 0.00, "Наш род иссякнет, но, возможно, легенды об Омошах будут жить!" }, { 5.66, "Да, ты настоящий кузнец!" }, { 7.93, "Главная награда для кузнеца – видеть оружие и доспехи своей работы обагрёнными кровью врагов!" }, { 16.71, "Пусть изготовленная тобою кираса ржавеет только от вражеской крови!" } } } } },
    [2752] = { d = 22.6, v = "orc-male", n = { x = 207 }, c = { x = { { 0.00, "У тебя внимательные глаза." }, { 2.44, "Ты вбираешь мудрость Омошей, точно губка!" }, { 6.27, "Три урока дам я тебе." }, { 8.22, "Вернись к наковальне и сделай для Орокка четыре бронзовых боевых топора и четыре бронзовых боевых молота." }, { 17.83, "Лишь тогда узнаешь ты, как изготовить железное оплечье!" } } }, t = { d = 6.3, v = "orc-male", n = { x = 54 }, c = { x = { { 0.00, "Орокк гордится тобой." }, { 2.19, "Вот, читай, как изготовить железное оплечье!" } } } } },
    [2753] = { d = 22.5, v = "orc-male", n = { x = 208 }, c = { x = { { 0.00, "Орокк научит тебя ещё двум вещам." }, { 2.95, "Да, я знаю, тебе тяжело, но надо продолжать – во имя Омошей!" }, { 8.22, "Принеси четыре зелёных железных шлема, четыре пары зелёных железных наручей и две пары зелёных железных поножей – и я научу тебя тому, что будет страшить твоих врагов!" } } }, t = { d = 8.5, v = "orc-male", n = { x = 71 }, c = { x = { { 0.00, "Ты напоминаешь Орокку его деда, Горокка Омоша!" }, { 4.58, "Вот, читай, учись делать железные сапоги." } } } } },
    [2754] = { d = 20.8, v = "orc-male", n = { x = 213 }, c = { x = { { 0.00, "Это последнее, чему научит тебя Орокк." }, { 3.36, "Но прежде принеси Орокку две твёрдые железные кувалды, две пары посеребрённых бронзовых сапог и две пары посеребрённых бронзовых рукавиц." }, { 14.47, "Ты узнаешь, как приятно видеть страх в глазах врагов при одном твоём появлении!" } } }, t = { d = 5.4, v = "orc-male", n = { x = 40 }, c = { x = { { 0.00, "Потрясающе!" }, { 1.33, "Теперь ты знаешь все секреты Омошей!" } } } } },
    [2755] = { d = 18.7, v = "orc-male", n = { x = 159 }, c = { x = { { 0.00, "Нет, Орокк не плачет." }, { 2.46, "Это сажа в глаз попала." }, { 5.12, "*Орокк утирает слезу.*" }, { 7.28, "Остался последний секрет семьи Омошей, которому научит тебя Орокк." }, { 13.28, "Выучи танец радости Омошей, и научишься ковать железный кулак!" } } }, t = { d = 9.8, v = "orc-male", n = { x = 74 }, c = { x = { { 0.00, "*Орокк шумно отдувается.*" }, { 2.56, "Давненько Орокк не плясал танец Радости Омошей!" }, { 7.80, "Ну, смотри и учись!" } } } } },
    [2756] = { d = 36.5, g = 1, v = "orc-male#126", n = { x = 327 }, c = { m = { { 0.00, "В былые легендарные времена Атурк сокрушил бы черепа своих врагов и истёр кости в мелкий порошок!" }, { 8.28, "Но эти дни давно миновали, герой." }, { 11.17, "Вождь требует мира между кланами, и старых врагов мы теперь даже пальцем тронуть не смеем." }, { 18.93, "Даже не верится!" }, { 20.37, "Но такова воля Тралла." }, { 22.35, "Ну, довольно жалоб!" }, { 24.02, "Ты здесь, чтобы учиться – и ты будешь учиться!" }, { 27.90, "Принеси четыре стальные кирасы и четыре стальных латных шлема, и узнаешь вкус войны!" } }, f = { { 0.00, "В былые легендарные времена Атурк сокрушил бы черепа своих врагов и истёр кости в мелкий порошок!" }, { 8.61, "Но эти дни давно миновали, героиня." }, { 11.77, "Вождь требует мира между кланами, и старых врагов мы теперь даже пальцем тронуть не смеем." }, { 19.82, "Даже не верится!" }, { 21.32, "Но такова воля Тралла." }, { 23.37, "Ну, довольно жалоб!" }, { 25.11, "Ты здесь, чтобы учиться – и ты будешь учиться!" }, { 29.14, "Принеси четыре стальные кирасы и четыре стальных латных шлема, и узнаешь вкус войны!" } } }, t = { d = 20.0, v = "orc-male#126", n = { x = 176 }, c = { x = { { 0.00, "Похоже, ты всего лишь очередной покорный прихвостень вождя." }, { 5.43, "Как разочаровывающе." }, { 7.24, "Как же я жажду славной смерти на поле битвы!" }, { 11.36, "А вместо этого торчу здесь и по приказу Тралла учу детишек мастерить." }, { 17.78, "Смотри и учись... дитя..." } } } } },
    [2757] = { d = 26.2, v = "tauren-male", n = { x = 261 }, c = { x = { { 0.00, "Слышь, будешь болтаться здесь – так ничему и не научишься!" }, { 4.55, "Вот я знаю мужика, который знает мужика, который ошивается возле кузницы в Пиратской бухте." }, { 12.00, "Покажи ему этот значок, и он тебе про мифрил всё расскажет!" }, { 16.84, "Чего-чего?" }, { 17.78, "Оставь это грудным младенцам, тебе пора двигаться дальше!" }, { 22.55, "Если тебя это интересует, его звать Макгеван." } } }, t = { d = 6.2, v = "human-male", n = { x = 66 }, c = { x = { { 0.00, "Клянусь задницей Чёрного Копыта!" }, { 2.61, "Наконец хоть кто-то достойный Ордена мифрила!" } } } } },
    [2758] = { d = 32.2, v = "human-male", n = { x = 380 }, c = { x = { { 0.00, "Когда я был примерно в твоём возрасте, дворф по имени Гальван взял меня под свою опеку и обучил меня способам ковки доспехов." }, { 8.70, "Перед своим отъездом в Пиратскую бухту он заставил меня пообещать, что я буду до конца дней своих обучать всех, у кого будет желание и решимость овладеть кузнечным ремеслом." }, { 20.78, "Так я и поступил." }, { 21.97, "Итак, теперь настало твоё время чему-нибудь научиться." }, { 25.79, "Сделай мне шесть пар золотых чешуйчатых наручей – и узнаешь, откуда есть пошло кузнечное дело." } } }, t = { d = 25.9, v = "human-male", n = { x = 262 }, c = { x = { { 0.00, "Отлично!" }, { 0.85, "Слушай и впитывай." }, { 2.63, "Мастерство кузнеца никогда не исходит отсюда!" }, { 6.88, "*Хэнк указывает на молот.*" }, { 9.12, "Мастерство кузнеца никогда не исходит и отсюда!" }, { 13.28, "*Хэнк указывает на наковальню.*" }, { 15.68, "Только отсюда происходит мастерство кузнеца!" }, { 19.12, "*Хэнк указывает себе на сердце.*" }, { 21.76, "Теперь ты знаешь, каково происхождение кузнечного искусства." } } } } },
    [2759] = { d = 21.0, g = 1, v = "human-male", n = { m = 246, f = 247 }, c = { m = { { 0.00, "Хотя Гальван покинул Пиратскую бухту много лет назад, члены ордена по-прежнему остаются в городе, надеясь однажды найти кого-нибудь, достойного внимания мастера." }, { 11.11, "Возьми этот знак и отдай его Макгевану в Пиратской бухте." }, { 15.10, "Если ты действительно с этим справишься, он поймёт, что ты достоин." }, { 19.58, "Я в тебя верю!" } }, f = { { 0.00, "Хотя Гальван покинул Пиратскую бухту много лет назад, члены ордена по-прежнему остаются в городе, надеясь однажды найти кого-нибудь, достойного внимания мастера." }, { 11.33, "Возьми этот знак и отдай его Макгевану в Пиратской бухте." }, { 15.40, "Если ты действительно с этим справишься, он поймёт, что ты достойна." }, { 20.04, "Я в тебя верю!" } } }, t = { d = 6.9, v = "human-male", n = { x = 74 }, c = { x = { { 0.00, "Клянусь гривой Чёрного Копыта – наконец-то появился хоть кто-то, достойный Ордена мифрила!" } } } } },
    [2760] = { d = 25.0, v = "human-male", n = { x = 303 }, c = { x = { { 0.00, "Большинство наших новобранцев так и не добрались до Пиратской бухты." }, { 4.59, "Блеска эмблемы оказывается достаточно, чтобы пробудить алчность даже в самых стойких кузнецах." }, { 11.08, "Дураки, эмблема эта – капля в море по сравнению со стоимостью предметов, которые ты увидишь!" }, { 17.39, "Найди Гальвана Древнего и покажи ему эту булавку." }, { 20.88, "Он живёт далеко на севере, между Зул'Гурубом и холмом Мош'Огг." } } }, t = { d = 8.2, v = "dwarf-male", n = { x = 82 }, c = { x = { { 0.00, "А, прошло много лет, с тех пор, как я в последний раз видел достойных принятия в Орден мифрила." }, { 7.52, "Начнём же!" } } } } },
    [2761] = { d = 26.6, g = 1, v = "dwarf-male", n = { m = 276, f = 276 }, c = { m = { { 0.00, "Многие кузнецы считают, что горное дело и кузнечное ремесло – две разные вещи; но что за кузнец без металла?" }, { 8.53, "Как же, это невозможно!" }, { 10.38, "Опытный кузнец должен быть и опытным горняком." }, { 14.07, "Покажи Гальвану, на что ты способен." }, { 16.91, "Принеси мне сорок слитков железа и сорок слитков мифрила." }, { 21.53, "За это Гальван научит тебя создавать изысканные мифриловые штаны!" } }, f = { { 0.00, "Многие кузнецы считают, что горное дело и кузнечное ремесло – две разные вещи; но что за кузнец без металла?" }, { 8.45, "Как же, это невозможно!" }, { 10.28, "Опытный кузнец должен быть и опытным горняком." }, { 13.94, "Покажи Гальвану, на что ты способна." }, { 16.76, "Принеси мне сорок слитков железа и сорок слитков мифрила." }, { 21.34, "За это Гальван научит тебя создавать изысканные мифриловые штаны!" } } }, t = { d = 9.0, v = "dwarf-male", n = { x = 97 }, c = { x = { { 0.00, "Твои работы безупречны!" }, { 1.89, "Ты начинаешь понимать основы минералогии Гальвана!" }, { 5.82, "Возьми это и научись всему, чему сможешь." } } } } },
    [2762] = { d = 35.3, v = "dwarf-male", n = { x = 369 }, c = { x = { { 0.00, "Говорят, что истинное серебро прочнее мифрила." }, { 3.69, "Гальван не будет спорить с такой оценкой, но вопреки названию, истинное серебро далеко от истины!" }, { 11.43, "Мифрил куда благороднее!" }, { 13.42, "ХА!" }, { 13.70, "И тем не менее, на сей раз тебе придётся найти это обманное серебро." }, { 19.03, "Принеси мне сорок мифриловых слитков и пять слитков истинного серебра." }, { 24.57, "Взамен я научу тебя искусству изготовления изысканных мифриловых перчаток, и что куда важнее, ты узнаешь, что истинное серебро – это лжец." } } }, t = { d = 12.9, v = "dwarf-male", n = { x = 138 }, c = { x = { { 0.00, "Нелегко с ним справиться, а?" }, { 2.09, "Я об истинном серебре." }, { 3.78, "Гальван потратил не меньше десяти лет в горах Альтерака, прежде чем усвоил этот урок." }, { 10.26, "Возьми это и научись, чему сможешь!" } } } } },
    [2763] = { d = 27.0, v = "dwarf-male", n = { x = 311 }, c = { x = { { 0.00, "Для нашего ремесла очень важно научиться добывать драгоценные камни." }, { 5.17, "Немногие камни драгоценнее цитрина." }, { 7.85, "Он во много раз усиливает ту магию, которую мы вкладываем в наши творения." }, { 13.35, "На сей раз мы усилим сорок слитков мифрила четырьмя цитринами." }, { 17.98, "В результате ты получишь лучшее представление о магической гемологии и научишься создавать изысканные мифриловые наплечники." } } }, t = { d = 10.4, v = "dwarf-male", n = { x = 102 }, c = { x = { { 0.00, "Да, от такой красоты взгляда не оторвёшь." }, { 3.39, "Цитрин – великолепный камень." }, { 5.88, "А теперь смотри внимательно, вот чему можно научиться!" } } } } },
    [2764] = { d = 17.7, g = 1, v = "dwarf-male", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Если ты готов покинуть Гальвана, отправляйся в Прибамбасск." }, { 4.36, "Там живёт мой лучший ученик, Трентон Молот Света." }, { 7.99, "Он научит тебя обращению с изысканным мифрилом." }, { 11.49, "Впрочем, можешь остаться здесь и поучиться ещё!" }, { 14.92, "Ах да, Прибамбасск находится в Танарисе!" } }, f = { { 0.00, "Если ты готова покинуть Гальвана, отправляйся в Прибамбасск." }, { 4.37, "Там живёт мой лучший ученик, Трентон Молот Света." }, { 7.95, "Он научит тебя обращению с изысканным мифрилом." }, { 11.41, "Впрочем, можешь остаться здесь и поучиться ещё!" }, { 14.80, "Ах да, Прибамбасск находится в Танарисе!" } } }, t = { d = 8.8, g = 1, v = "nightelf-male#55", n = { m = 91, f = 89 }, c = { m = { { 0.00, "Тебя прислал Гальван Древний?" }, { 2.40, "*Трентон кланяется*" }, { 4.08, "Это большая честь – познакомиться с ещё одним из его учеников!" } }, f = { { 0.00, "Тебя прислал Гальван Древний?" }, { 2.32, "*Трентон кланяется*" }, { 4.00, "Это большая честь – познакомиться с ещё одной из его учениц!" } } } } },
    [2765] = { d = 21.7, g = 1, v = "dwarf-male", n = { m = 253, f = 253 }, c = { m = { { 0.00, "Я с первого взгляда понял, что ты станешь одним из моих лучших учеников!" }, { 5.29, "Ты без колебаний отдал Макгевану вещь, наделённую силой, лишь бы только встретиться со мной." }, { 11.76, "Подобная слепая вера и преданность искусству должна быть вознаграждена." }, { 16.92, "Ты стал настоящим экспертом в кузнечном деле." }, { 20.19, "Насладись же наградой!" } }, f = { { 0.00, "Я с первого взгляда понял, что ты станешь одной из моих лучших учениц!" }, { 5.13, "Ты без колебаний отдала Макгевану вещь, наделённую силой, лишь бы только встретиться со мной." }, { 11.62, "Подобная слепая вера и преданность искусству должна быть вознаграждена." }, { 16.75, "Ты стала настоящим экспертом в кузнечном деле." }, { 20.12, "Насладись же наградой!" } } }, t = { d = 10.7, g = 1, v = "dwarf-male", n = { m = 116, f = 117 }, c = { m = { { 0.00, "Что ж, ты в самом деле заслужил украшение, наделённое большей силой, чем то, которым пришлось пожертвовать на пути сюда." }, { 9.14, "Пользуйся на здоровье." } }, f = { { 0.00, "Что ж, ты в самом деле заслужила украшение, наделённое большей силой, чем то, которым пришлось пожертвовать на пути сюда." }, { 9.08, "Пользуйся на здоровье." } } } } },
    [2766] = { d = 35.7, v = "narrator", n = { x = 377 }, c = { x = { { 0.00, "Перед вами странный металлический предмет яйцевидной формы." }, { 4.76, "Вы понажимали на кнопочки – и внезапно яйцо ожило и раскрылось." }, { 9.74, "Очевидно, это какой-то гномский приборчик!" }, { 13.15, "Из механического яйца раздаётся искажённый разрядами голос:" }, { 17.70, "\"Меня зовут Карлс Пропеллерз." }, { 20.05, "Мой автономный робот попал в аварию!" }, { 22.96, "Обнаруживший его получит награду!" }, { 25.66, "Прошу вас, доставьте этот маячок к роботу!" }, { 29.08, "Я вычислил координаты робота – он находится в пещере рядом с Долиной Свирепого Утёса!\"" } } }, t = { d = 37.7, v = "gnome-male", n = { x = 363 }, c = { x = { { 0.00, "*Вы помещаете яйцо... то есть аварийный маяк... внутрь цыплёнка... то есть автономного робота.*" }, { 7.89, "*Внутри робота слышится гудение и жужжание.*" }, { 11.67, "*Он пытается подняться на ноги.*" }, { 14.35, "*После того как робот оживает, снова слышится голос Карлса, но на этот раз изнутри робота:*" }, { 22.24, "\"Ну что ж, по крайней мере, KKX-22/FE работает." }, { 27.37, "Однако он нуждается в серьёзном ремонте!" }, { 30.38, "Нести его вы не сможете, он слишком тяжёлый..." }, { 33.86, "О!" }, { 34.07, "У меня идея!" }, { 35.09, "Не согласитесь ли вы его проводить?\"" } } } } },
    [2767] = { d = 40.1, v = "gnome-male", n = { x = 449 }, c = { x = { { 0.00, "*Из динамика снова слышится искажённый разрядами голос гнома:*" }, { 4.64, "\"Мне необходимо перегнать KKX-22/FE в просторное и безопасное место, чтобы начать длительную процедуру подготовки к взлёту." }, { 14.50, "У него есть встроенная маскировка, но мне нужно время, чтобы снова её включить." }, { 20.00, "Проводите робота из того места, где вы его обнаружили, в... ну, скажем, в порт на Забытом берегу!" }, { 26.68, "Это самое подходящее место, и там достаточно просторно, чтобы аппарату было где развернуться." }, { 33.17, "Доставьте его в целости, а потом приходите ко мне в Пиратскую бухту!" }, { 37.91, "Оглторп Обнотикус, конец связи!\"" } } }, t = { d = 29.2, v = "gnome-male", n = { x = 326 }, c = { x = { { 0.00, "О, спаситель!" }, { 1.00, "Вы доставили на место KKX-22/FE!" }, { 4.94, "У меня просто слов нет, настолько я вам благодарен!" }, { 8.67, "Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок!" }, { 21.28, "Прошу вас, выбирайте любую из этих готовых моделей." }, { 25.14, "Ещё раз спасибо вам!" }, { 26.61, "Мы с моими роботами – ваши должники!" } } } } },
    [2768] = { d = 35.3, v = "goblin-male", n = { x = 425 }, c = { x = { { 0.00, "Сержант Блай обокрал меня!" }, { 1.83, "Он сказал, что он только одолжит, но он украл мой драгоценный изыскательский стержень!!!" }, { 7.69, "Без этого стержня как я буду знать, где бурить новые скважины под воду??" }, { 12.58, "Найди Блая и принеси мне мой стержень!" }, { 15.21, "Я услышал, что он вынудил свою компашку низкопробных авантюристов идти за сокровищами в Зул'Фаррак, – город, расположенный на западе." }, { 24.12, "Держу пари, там ты его и найдёшь." }, { 26.38, "Надеюсь, что он уже повстречался с троллями, потому что если тебе придётся драться с ним за мой стержень, то схватка выйдет нешуточная." } } }, t = { d = 8.0, g = 1, v = "goblin-male", n = { m = 79, f = 81 }, c = { m = { { 0.00, "Ты сделал это." }, { 1.24, "Пришлось ли тебе убить Блая?" }, { 3.64, "Надеюсь, ты задал ему и его прихвостням хорошую трёпку!" } }, f = { { 0.00, "Ты сделала это." }, { 1.27, "Пришлось ли тебе убить Блая?" }, { 3.61, "Надеюсь, ты задала ему и его прихвостням хорошую трёпку!" } } } } },
    [2769] = { d = 33.8, v = "gnome-male", n = { x = 415 }, c = { x = { { 0.00, "Вы ещё не встречались с братьями Латунный Болт?" }, { 3.12, "Они на Мерцающей равнине в Калимдоре гоняют на своём болиде наперегонки с гоблинами." }, { 8.82, "Обычно они выигрывают, что неудивительно: гоблинские машины взрываются так часто, что едва дотягивают до финишной черты!" }, { 16.96, "Но братья Латунный Болт всё равно постоянно ищут новые способы сделать свою машину ещё более скоростной, и Виззл сказал мне, что ему нужен очень редкий компонент для очередных экспериментов." }, { 29.88, "Похоже, ему надо с этим помочь." }, { 32.14, "Спросите его на этот счёт." } } }, t = { d = 10.1, g = 1, v = "gnome-male", n = { m = 94, f = 94 }, c = { m = { { 0.00, "Так ты хочешь мне помочь?" }, { 2.03, "Отлично!" }, { 2.75, "Мне для эксперимента нужна одна штука, и отважный герой вроде тебя добудет её без труда!" } }, f = { { 0.00, "Так ты хочешь мне помочь?" }, { 2.06, "Отлично!" }, { 2.80, "Мне для эксперимента нужна одна штука, и отважная героиня вроде тебя добудет её без труда!" } } } } },
    [2770] = { d = 33.2, v = "gnome-male", n = { x = 380 }, c = { x = { { 0.00, "В пустыне Танарис есть город троллей – Зул'Фаррак, в глубине которого находится священный бассейн." }, { 7.08, "Из этого бассейна тролли призывают огромное чудовище, Газ'риллу!" }, { 11.77, "Злобная энергия пронизывает это чудовище насквозь, до самых кончиков его чешуи." }, { 17.62, "И именно эту энергию я хочу использовать в своей машине!" }, { 21.78, "Принеси мне наэлектризованную чешую Газ'риллы." }, { 25.09, "Но только помни, что тролли держат способ призывания этого монстра в тайне, и просто так они с ней не расстанутся." } } }, t = { d = 11.7, g = 1, v = "gnome-male", n = { m = 114, f = 115 }, c = { m = { { 0.00, "Ого, да это же чешуя!" }, { 1.77, "Спасибо." }, { 2.48, "Сейчас же начну работать с ней." }, { 4.95, "Так значит, ты видел Газ'риллу?" }, { 7.43, "Эта тварь и правда такая большая, как про неё говорят?" } }, f = { { 0.00, "Ого, да это же чешуя!" }, { 1.78, "Спасибо." }, { 2.49, "Сейчас же начну работать с ней." }, { 4.99, "Так значит, ты видела Газ'риллу?" }, { 7.55, "Эта тварь и правда такая большая, как про неё говорят?" } } } } },
    [2771] = { d = 20.0, v = "nightelf-male#55", n = { x = 206 }, c = { x = { { 0.00, "Похоже, таков был замысел учителя." }, { 2.82, "Меня он научил делать одни предметы, а тебя другие." }, { 7.08, "Учитель мудр!" }, { 8.16, "Мы обучим друг друга!" }, { 9.90, "Научи меня делать мифриловые капюшоны и изысканные мифриловые наплечники, а я покажу тебе, как куётся изысканный мифриловый шлем." } } }, t = { d = 6.5, v = "nightelf-male#55", n = { x = 57 }, c = { x = { { 0.00, "Великолепно!" }, { 1.16, "Даже я говорю, что это отличный результат." }, { 5.15, "Смотри и учись!" } } } } },
    [2772] = { d = 28.6, v = "nightelf-male#55", n = { x = 357 }, c = { x = { { 0.00, "На прошлогодних соревнованиях по кузнечному делу все зрители видели, как трусливый пёс из Торговой компании подставил мне подножку." }, { 8.87, "Им и невдомёк, как я умудрился выиграть соревнования: правильно, благодаря изысканным мифриловым сапогам!" }, { 15.89, "На соревнованиях этого года мне понадобятся изысканные мифриловые штаны, потому что в конкурсе участвует крошшер Торговой компании!" }, { 24.82, "Научи меня делать штаны, а я научу тебя делать сапоги!" } } }, t = { d = 5.5, v = "nightelf-male#55", n = { x = 51 }, c = { x = { { 0.00, "Мир будет у твоих ног!" }, { 2.00, "Пусть все падут ниц перед твоим величием!" } } } } },
    [2773] = { d = 25.2, v = "nightelf-male#55", n = { x = 299 }, c = { x = { { 0.00, "В этих краях меня зовут Мифриловым Парнем." }, { 3.20, "Я продаю изысканный мифрил искателям приключений со всего света." }, { 7.90, "Им и невдомёк, что я не умею делать изысканные мифриловые перчатки." }, { 13.39, "Ш-ш-ш!" }, { 13.85, "Пусть это останется между нами." }, { 16.20, "Научи меня делать такие перчатки, а я взамен покажу тебе последнее, чему обучил меня Гальван: изысканную мифриловую кирасу." } } }, t = { d = 7.9, v = "nightelf-male#55", n = { x = 79 }, c = { x = { { 0.00, "Спасибо за науку." }, { 1.50, "Скоро в твоих руках окажется король изысканного мифрилового доспеха." }, { 7.25, "Смотри!!!" } } } } },
    [2781] = { d = 34.8, v = "narrator", n = { x = 382 }, c = { x = { { 0.00, "РАЗЫСКИВАЕТСЯ: Калиф Жало Скорпида!" }, { 2.84, "Водная компания Прибамбасска предлагает награду за голову Калифа Жало Скорпида, главы Скитальцев Пустыни." }, { 11.20, "Он обвиняется в:" }, { 12.48, "Во-первых, убийстве сотрудников Водной компании Прибамбасска!" }, { 17.30, "Во-вторых, похищении ресурсов Водной компании Прибамбасска!" }, { 21.98, "В-третьих, захвате собственности Водной компании Прибамбасска!" }, { 26.87, "Принесите доказательство гибели Калифа Жало Скорпида главному инженеру Чепухастеру и получите награду!" } } }, t = { d = 19.8, g = 1, v = "goblin-male", n = { m = 209, f = 212 }, c = { m = { { 0.00, "Наконец-то – правосудие свершилось!" }, { 2.77, "Ты нанёс суровый удар подлым кочевникам!" }, { 5.98, "Жало Скорпида мёртв, может быть, это отпугнёт этих надоед от колодцев Прибамбасска!" }, { 12.52, "От лица Водной компании Прибамбасска я вручаю тебе эту награду." }, { 17.64, "Ты оказал нам большую услугу." } }, f = { { 0.00, "Наконец-то – правосудие свершилось!" }, { 2.71, "Ты нанесла суровый удар подлым кочевникам!" }, { 6.05, "Жало Скорпида мёртв, может быть, это отпугнёт этих надоед от колодцев Прибамбасска!" }, { 12.45, "От лица Водной компании Прибамбасска я вручаю тебе эту награду." }, { 17.46, "Ты оказала нам большую услугу." } } } } },
    [2782] = { d = 23.4, v = "narrator", n = { x = 244 }, c = { x = { { 0.00, "Табличка покрыта письменами троллей из племени Сухокожих." }, { 4.60, "Да, секрет Рин'джи и впрямь оказался очень загадочным." }, { 8.92, "Возможно, эта табличка представляет собой немалую ценность, хотя может быть и с точностью до наоборот." }, { 17.12, "Тролль из племени Сухокожих в беде мог пообещать что угодно, лишь бы его спасли..." } } }, t = { d = 5.0, v = "scourge-female#79", n = { x = 36 }, c = { x = { { 0.00, "Хм, какая необычная табличка..." }, { 3.39, "Где вы её взяли?" } } } } },
    [2783] = { d = 27.3, v = "bloodelf-male", n = { x = 319 }, c = { x = { { 0.00, "Мы сражаемся не с тем врагом." }, { 2.03, "Истинная сила этих земель продолжает наращивать свою мощь и численность, пока мы ссоримся с орками из-за сожжённой земли." }, { 10.60, "Продолжим ли мы воевать в этих землях против Орды, только чтобы в один ужасный день быть сметёнными силой Пылающего Легиона?" }, { 19.36, "Это тщетно." }, { 20.25, "Надо отбросить прочь различия, и поговорить с павшим героем Орды." }, { 24.88, "Он знает правду о Выжженных землях." } } }, t = { d = 16.6, v = "orc-male", n = { x = 146 }, c = { x = { { 0.00, "Альянс желает помочь?" }, { 2.05, "Я не думал, что этот день когда-либо наступит вновь." }, { 6.72, "День, когда Альянс будет сражаться плечом к плечу с Ордой против общего врага." }, { 14.02, "Да будет так... мы объединимся." } } } } },
    [2784] = { d = 2.9, g = 1, v = "orc-male", n = { x = 18 }, c = { m = { { 0.00, "Выслушай мою историю, герой." } }, f = { { 0.00, "Выслушай мою историю, героиня." } } }, t = { d = 8.6, v = "orc-male", n = { x = 81 }, c = { x = { { 0.00, "Будучи духом, я бессилен что-либо сделать." }, { 3.81, "Помоги мне." }, { 4.84, "Дай мне возможность снова обрести свою честь." } } } } },
    [2801] = { d = 4.9, v = "orc-male", n = { x = 49 }, c = { x = { { 0.00, "Прежде чем мы продолжим, тебе следует услышать мою историю." } } }, t = { d = 2.7, v = "orc-male", n = { x = 23 }, c = { x = { { 0.00, "Настало время действовать." } } } } },
    [2821] = { d = 32.3, v = "human-male", n = { x = 379 }, c = { x = { { 0.00, "У меня принцип простой: если что делаешь, делай как можно лучше – и никаких компромиссов!" }, { 6.18, "А тот, кто станет говорить, будто качество не имеет значения, того гляди, продаст тебе недвижимость в Дун Мороге с видом на море!" }, { 15.09, "И вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети." }, { 20.53, "Йети – это существа, которые водятся в Фераласе." }, { 23.93, "Особенно много их в Долине Свирепого Утёса." }, { 26.90, "За каждые десять шкур ты получишь одно из моих кожаных изделий." }, { 31.29, "Ну что, по рукам?" } } }, t = { d = 24.2, v = "human-male", n = { x = 263 }, c = { x = { { 0.00, "Ну что, видишь, каковы эти шкуры?" }, { 2.52, "Надо тебе сказать, что после специальной обработки они делаются прочнее железа!" }, { 8.48, "Немногие про это знают, а вот я, с помощью своих особых дубильных составов, смогу делать из них вещи несравненного качества!" }, { 17.62, "Ну да, и всё это – благодаря тебе." }, { 20.13, "Пожалуйста, выбирай себе любое из моих готовых изделий." } } } } },
    [2822] = { d = 39.5, v = "tauren-male#132", n = { x = 360 }, c = { x = { { 0.00, "Я горжусь своим мастерством." }, { 2.54, "Мои вещи сразу видно!" }, { 4.60, "А тот, кто станет говорить, будто качество не имеет значения, пожалуй, захочет убедить тебя и в том, будто земля не хранит тайн!" }, { 15.87, "И вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети." }, { 22.86, "Йети – это существа, которые водятся в Фераласе." }, { 27.22, "Особенно много их к западу отсюда, в Долине Свирепого Утёса." }, { 32.54, "За каждые десять шкур ты получишь одно из моих кожаных изделий." }, { 38.17, "Ну что, по рукам?" } } }, t = { d = 29.3, g = 1, v = "tauren-male#132", n = { m = 273, f = 274 }, c = { m = { { 0.00, "О, отлично!" }, { 1.00, "Надо тебе сказать, что эти шкуры после специальной обработки делаются прочнее железа!" }, { 8.43, "Правда, подобрать состав для дубления не так-то просто, но всё равно, я уверен, что мои вещи, изготовленные из них, будут ещё лучше прежнего." }, { 20.38, "Что до тебя, – ты воистину бесценный помощник!" }, { 24.29, "Пожалуйста, выбирай себе любое из моих готовых изделий." } }, f = { { 0.00, "О, отлично!" }, { 1.00, "Надо тебе сказать, что эти шкуры после специальной обработки делаются прочнее железа!" }, { 8.50, "Правда, подобрать состав для дубления не так-то просто, но всё равно, я уверен, что мои вещи, изготовленные из них, будут ещё лучше прежнего." }, { 20.55, "Что до тебя, – ты воистину бесценная помощница!" }, { 24.57, "Пожалуйста, выбирай себе любое из моих готовых изделий." } } } } },
    [2841] = { d = 33.3, v = "goblin-male", n = { x = 352 }, c = { x = { { 0.00, "О-о, гномьи технологии!" }, { 1.86, "Ещё пару лет назад они использовались в основном в анекдотах." }, { 6.55, "Да уж, времена изменились!" }, { 8.55, "Теперь они выстроили такую машину, которая лучше, чем все наши резаки вместе взятые!" }, { 15.16, "Мне нужны её чертежи!" }, { 16.82, "Увы, эти бумаги хранятся в сейфе Мекжинера Термоштепселя." }, { 21.30, "А хуже всего, что код от сейфа известен только самому Мекжинеру Термоштепселю!" }, { 27.29, "Делай что хочешь, но добудь этот код, открой сейф и достань оттуда эти чертежи!" } } }, t = { d = 19.4, v = "goblin-male", n = { x = 217 }, c = { x = { { 0.00, "Да, я знал, что у тебя всё получится!" }, { 2.69, "А вот Совик всё сомневался…" }, { 4.71, "Ну, теперь, когда чертежи у нас в руках, разобраться в этих гномьих нововведениях – всего лишь вопрос времени." }, { 14.00, "Эти изобретения очень пригодятся нам, гоблинам, для новых моделей резаков!" } } } } },
    [2842] = { d = 27.8, v = "goblin-male#110", n = { x = 334 }, c = { x = { { 0.00, "Как только Керноби сообщил нам о новой гномьей машине, мы со Скути принялись строить \"Транстелепорт-шесть тысяч\" – лучший способ добраться до Гномрегана." }, { 10.39, "Он уже готов." }, { 11.37, "Если хочешь его испытать, ступай в Пиратскую бухту и поговори со Скути у Гнезда Крыльев Ветра." }, { 17.95, "Из Кабестана туда можно добраться на лодке." }, { 20.96, "Нет, разумеется, ты можешь попробовать добраться до Гномрегана через горы Дун Морог, кишащие дворфами!" } } }, t = { d = 17.9, v = "goblin-male", n = { x = 195 }, c = { x = { { 0.00, "Ну, разве она не красавица?" }, { 2.11, "Вершина гоблинских транспортных технологий!" }, { 5.37, "Взрывалась-то всего раз двенадцать, не больше!" }, { 8.83, "Ты не бойся." }, { 9.78, "Больше она не взорвётся, я там всё отладил." }, { 12.97, "Ну, а если тебе не повезёт, ты хотя бы умрёшь быстро и безболезненно!" } } } } },
    [2843] = { d = 26.6, v = "goblin-male", n = { x = 314 }, c = { x = { { 0.00, "Пока импульсный повторитель у тебя с собой, стоит только ступить на площадку, и перенесёшься в Гномреган." }, { 7.31, "Может быть, ощущения будут необычные, но ни одно из них не останется навсегда..." }, { 12.85, "Теперь." }, { 13.41, "Чуть не забыл самое главное – как вернуться назад." }, { 16.94, "Когда ты решишь уносить ноги, поднимись на площадку транстелепорта в Гномрегане!" }, { 22.55, "А теперь я настрою импульсный повторитель на твой рост и вес." } } }, t = { d = 4.3, v = "goblin-male", n = { x = 48 }, c = { x = { { 0.00, "Готово!" }, { 0.61, "Когда соберёшься с духом, просто ступи на площадку." } } } } },
    [2844] = { d = 32.1, v = "elemental-earth", n = { x = 310 }, c = { x = { { 0.00, "Нет от меня никакого толку!" }, { 2.22, "Я должен был стеречь мою маленькую подружку, Шай, а она взяла и убежала!" }, { 8.00, "Я даже не знаю, как это вышло: в последний раз, как я её видел, мы шли через развалины к северу отсюда." }, { 16.15, "Всё было хорошо, а потом я поворачиваюсь, а её нет!" }, { 20.15, "И теперь я даже и не знаю, чего мне делать-то." }, { 23.87, "Что мне делать?" }, { 25.08, "Я так переживаю!" }, { 26.37, "Слушай, а может, ты сходишь её поищешь?" }, { 29.52, "У тебя-то ноги куда резвее моих!" } } }, t = { d = 8.7, g = 1, v = "nightelf-female#53", n = { m = 82, f = 82 }, c = { m = { { 0.00, "Ой, как хорошо, что ты меня нашёл!" }, { 2.78, "По правде говоря, я немножко заблудилась..." }, { 6.39, "Но тут очень красиво, правда?" } }, f = { { 0.00, "Ой, как хорошо, что ты меня нашла!" }, { 2.83, "По правде говоря, я немножко заблудилась..." }, { 6.41, "Но тут очень красиво, правда?" } } } } },
    [2845] = { d = 34.4, v = "nightelf-female#53", n = { x = 371 }, c = { x = { { 0.00, "Не поможешь ли ты мне отыскать моего друга, Камнедробителя?" }, { 4.41, "Он должен был следить за мной..." }, { 6.79, "Но со мной иногда случается, что я ухожу, куда глаза глядят." }, { 11.33, "Вокруг столько интересного, я увлекаюсь, забываю обо всём на свете, и…" }, { 16.56, "Но есть одна вещь, которая обязательно привлекает моё внимание." }, { 21.24, "В этом сундучке хранится колокольчик." }, { 24.10, "Он мне очень дорог." }, { 25.59, "Мне ужасно нравится его звон." }, { 27.83, "Так что, если я вдруг куда-нибудь уйду, позвони в колокольчик, и я тотчас прибегу обратно!" } } }, t = { d = 11.6, v = "elemental-earth", n = { x = 98 }, c = { x = { { 0.00, "Шо?" }, { 0.33, "Так говоришь, этот колокольчик помогает найти Шай, когда она убежала?" }, { 6.79, "Вот это да!" }, { 7.87, "Ну, раз я стольким тебе обязан, на, держи!" } } } } },
    [2846] = { d = 36.9, v = "human-female#45", n = { x = 429 }, c = { x = { { 0.00, "Давным-давно у меня была прекрасная драгоценность, Тиара Глубин." }, { 4.60, "Это была не просто красивая безделушка, она была наделена великой силой, предназначенной для тех, кто умел с ней обращаться." }, { 13.43, "Когда слух о моей тиаре достиг ушей гидроманта Велраты, она решила заполучить её и послала своих подручных выкрасть её у меня!" }, { 22.51, "Я хочу вернуть то, что принадлежит мне." }, { 25.26, "Отправляйтесь в Зул'Фаррак, город троллей в пустыне Танарис, найдите там Велрату и заберите у неё мою тиару." }, { 32.93, "Возвращайтесь ко мне и заслужите мою вечную благодарность." } } }, t = { d = 16.6, g = 1, v = "human-female#45", n = { m = 166, f = 166 }, c = { m = { { 0.00, "Чудно!" }, { 0.57, "Ты нашёл её!" }, { 1.50, "И, что ещё важнее, Велрата её лишилась!" }, { 4.57, "Благодарю тебя." }, { 5.86, "И..." }, { 6.21, "Если я прежде высказывалась несколько резко, не бери в голову." }, { 11.21, "К тем, кто не пытается меня обокрасть, я отношусь гораздо дружелюбнее." } }, f = { { 0.00, "Чудно!" }, { 0.56, "Ты нашла её!" }, { 1.53, "И, что ещё важнее, Велрата её лишилась!" }, { 4.51, "Благодарю тебя." }, { 5.76, "И..." }, { 6.11, "Если я прежде высказывалась несколько резко, не бери в голову." }, { 10.97, "К тем, кто не пытается меня обокрасть, я отношусь гораздо дружелюбнее." } } } } },
    [2847] = { d = 35.3, g = 1, v = "human-male", n = { m = 423, f = 424 }, c = { m = { { 0.00, "Ты уже опытный кожевник." }, { 1.75, "Я владею искусством изготовления того, что весьма пригодилось бы и тебе." }, { 6.76, "Это дикарские кожаные доспехи." }, { 8.95, "В них используется загадочная и непостоянная сила дикого винограда, который можно отыскать в густых зарослях или получить от некоторых существ." }, { 18.90, "Другого подобного доспеха мастер твоего уровня изготовить не в силах." }, { 23.78, "Я научу тебя делать эти доспехи, но для этого тебе придётся потрудиться." }, { 28.85, "Для начала мне нужно просто десять кусков плотной кожи." }, { 32.79, "Принеси её, потом обсудим дальнейшее." } }, f = { { 0.00, "Ты уже опытная кожевница." }, { 1.79, "Я владею искусством изготовления того, что весьма пригодилось бы и тебе." }, { 6.72, "Это дикарские кожаные доспехи." }, { 8.87, "В них используется загадочная и непостоянная сила дикого винограда, который можно отыскать в густых зарослях или получить от некоторых существ." }, { 18.67, "Другого подобного доспеха мастер твоего уровня изготовить не в силах." }, { 23.48, "Я научу тебя делать эти доспехи, но для этого тебе придётся потрудиться." }, { 28.47, "Для начала мне нужно просто десять кусков плотной кожи." }, { 32.35, "Принеси её, потом обсудим дальнейшее." } } }, t = { d = 16.5, g = 1, v = "human-male", n = { m = 190, f = 191 }, c = { m = { { 0.00, "Ну что ж, я рад, что ты теперь у меня в подмастерьях." }, { 3.54, "Ты поступил разумно, избрав ремесло кожевника: когда ты научишься изготовлять дикарские кожаные доспехи, у тебя отбою не будет от тех, кто одевается в кожу." }, { 14.29, "Ну, за работу!" }, { 15.28, "С чего мы начнём?" } }, f = { { 0.00, "Ну что ж, я рад, что ты теперь у меня в подмастерьях." }, { 3.56, "Ты поступила разумно, избрав ремесло кожевника: когда ты научишься изготовлять дикарские кожаные доспехи, у тебя отбою не будет от тех, кто одевается в кожу." }, { 14.44, "Ну, за работу!" }, { 15.44, "С