    [2848] = { d = 26.4, v = "human-male", n = { x = 326 }, c = { x = { { 0.00, "Дикарские кожаные наплечники обеспечивают превосходную защиту как плеч, так и верхней части руки." }, { 6.60, "Как и все дикарские кожаные доспехи, они прошиты диким виноградом, что придаёт им мощные, но непостоянные магические свойства." }, { 15.12, "Для изготовления изделия по этой выкройке мне потребуется шесть наборов для усиления брони из толстой кожи и дикий виноград." }, { 23.58, "Для тебя это не слишком сложное задание..." } } }, t = { d = 19.2, g = 1, v = "human-male", n = { m = 229, f = 230 }, c = { m = { { 0.00, "Да, это хорошие, надёжные наборы для усиления брони." }, { 3.52, "Если я чего требую не только от себя, но и от своих подмастерьев, так это высокого качества!" }, { 9.77, "Ты неплохо потрудился, и заслуживаешь того, чтобы получить эту выкройку." }, { 14.69, "Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне." } }, f = { { 0.00, "Да, это хорошие, надёжные наборы для усиления брони." }, { 3.54, "Если я чего требую не только от себя, но и от своих подмастерьев, так это высокого качества!" }, { 9.82, "Ты неплохо потрудилась, и заслуживаешь того, чтобы получить эту выкройку." }, { 14.83, "Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне." } } } } },
    [2849] = { d = 26.7, v = "human-male", n = { x = 333 }, c = { x = { { 0.00, "Дикарский кожаный жилет – основа любых дикарских кожаных доспехов." }, { 4.63, "Основа жилета переплетена диким виноградом, что даёт максимальную защиту торса и позволяет использовать мощную магию растения." }, { 13.28, "Для изготовления изделия по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикий виноград." }, { 23.40, "Изготовить это непросто, но, думаю, ты справишься." } } }, t = { d = 16.2, v = "human-male", n = { x = 177 }, c = { x = { { 0.00, "Да, неплохие вещицы!" }, { 1.56, "За одно умение и старание, вложенное в них, можно получить несколько лишних серебряных монет." }, { 8.59, "Ну что, мой приказ выполнен, вот и твоя награда." }, { 12.18, "Теперь ты умеешь изготовлять дикарские кожаные жилеты!" } } } } },
    [2850] = { d = 31.8, v = "human-male", n = { x = 394 }, c = { x = { { 0.00, "Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы." }, { 6.94, "Как и во всех дикарских кожаных доспехах, в основу шлема вплетён дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами." }, { 16.63, "Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!" }, { 21.20, "Но для изготовления изделия по этой выкройке мне понадобятся два ночных мундира, две ночные головные повязки и дикий виноград." }, { 29.67, "Принеси это всё, и выкройка твоя!" } } }, t = { d = 16.6, g = 1, v = "human-male", n = { m = 185, f = 186 }, c = { m = { { 0.00, "Да, это Ночное снаряжение – именно то, что я просил тебя принести." }, { 4.85, "Впрочем, от кожевника твоего уровня я другого и не ждал." }, { 8.92, "Ты достоин уметь изготовлять дикарские кожаные шлемы." }, { 12.85, "Вот тебе выкройка." }, { 14.23, "Надеюсь, ты применишь её с пользой." } }, f = { { 0.00, "Да, это Ночное снаряжение – именно то, что я просил тебя принести." }, { 4.74, "Впрочем, от кожевника твоего уровня я другого и не ждал." }, { 8.71, "Ты достойна уметь изготовлять дикарские кожаные шлемы." }, { 12.62, "Вот тебе выкройка." }, { 13.97, "Надеюсь, ты применишь её с пользой." } } } } },
    [2851] = { d = 33.2, v = "human-male", n = { x = 379 }, c = { x = { { 0.00, "Тебе известно уже немало." }, { 1.94, "Однако многое ещё остаётся постичь." }, { 4.46, "Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех." }, { 10.99, "Ноге в них удобно и приятно, и дальний путь в них не так тяжёл." }, { 15.38, "Мягкая же подошва позволяет при необходимости ступать беззвучно." }, { 19.97, "Для их изготовления по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог." }, { 26.75, "И два экземпляра дикого винограда – запомни, два, а не один!" }, { 31.02, "Добудешь всё это – дай мне знать." } } }, t = { d = 9.4, g = 1, v = "human-male", n = { m = 110, f = 111 }, c = { m = { { 0.00, "И снова ты выполняешь непростой заказ с искусством опытного профессионала!" }, { 5.42, "Ты заслужил эту выкройку, равно как и мою благодарность." } }, f = { { 0.00, "И снова ты выполняешь непростой заказ с искусством опытного профессионала!" }, { 5.20, "Ты заслужила эту выкройку, равно как и мою благодарность." } } } } },
    [2852] = { d = 38.6, v = "human-male", n = { x = 461 }, c = { x = { { 0.00, "Ну, теперь, когда с простыми предметами покончено, мы можем перейти к более сложным вещам." }, { 6.33, "Дикарские кожаные поножи – одна из наиболее прочных и надёжных разновидностей кожаного доспеха." }, { 12.92, "Они отлично защищают и живот, и ноги, и прочие важные части тела." }, { 17.62, "А поскольку в них вшит ещё и дикий виноград, дающий дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи." }, { 27.21, "Для изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда." } } }, t = { d = 19.0, v = "human-male", n = { x = 204 }, c = { x = { { 0.00, "Ну что, мой приказ снова выполнен отлично." }, { 3.16, "Может, в один прекрасный день уже я явлюсь к тебе, как ученик к учителю, а?" }, { 8.81, "Вот выкройка поножей, а с ней и моя благодарность." }, { 12.51, "Пусти полученные знания в дело, и пусть твои изделия будут достойны твоих способностей!" } } } } },
    [2853] = { d = 35.0, g = 1, v = "human-male", n = { m = 401, f = 401 }, c = { m = { { 0.00, "Что ж, ты – образец прилежания." }, { 2.11, "Остался только один предмет из дикарских кожаных доспехов, который ты не умеешь изготовлять." }, { 8.50, "Я не стану заставлять тебя трудиться, чтобы его получить: ты и так сполна расплатился за всё." }, { 14.90, "Однако же сам я тебе его дать не могу." }, { 17.57, "Ты получишь награду от моего наставника, того, кто посвятил в тайны нашего ремесла меня самого." }, { 24.21, "Отнеси эту записку Телонису." }, { 26.26, "Он обучает кожевников в Дарнассе." }, { 28.56, "Покажи ему записку, и пусть он приветствует тебя как равного, подобно мне самому." } }, f = { { 0.00, "Что ж, ты – образец прилежания." }, { 2.18, "Остался только один предмет из дикарских кожаных доспехов, который ты не умеешь изготовлять." }, { 8.76, "Я не стану заставлять тебя трудиться, чтобы его получить: ты и так сполна расплатилась за всё." }, { 15.42, "Однако же сам я тебе его дать не могу." }, { 18.17, "Ты получишь награду от моего наставника, того, кто посвятил в тайны нашего ремесла меня самого." }, { 25.01, "Отнеси эту записку Телонису." }, { 27.12, "Он обучает кожевников в Дарнассе." }, { 29.49, "Покажи ему записку, и пусть он приветствует тебя как равную, подобно мне самому." } } }, t = { d = 33.1, v = "nightelf-male", n = { x = 342 }, c = { x = { { 0.00, "А, ты от Пратта!" }, { 1.28, "Он, конечно, человек, но временами напоминает мне нас, ночных эльфов." }, { 6.70, "Он действительно гениальный кожевенник!" }, { 9.76, "И если он тебя так расхваливает, это говорит в твою пользу." }, { 14.53, "Насколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов?" }, { 20.30, "Позволь же, я завершу твоё обучение, дав тебе вот эту выкройку." }, { 25.29, "Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!" } } } } },
