    [2856] = { d = 31.9, v = "tauren-male#132", n = { x = 334 }, c = { x = { { 0.00, "Дикарский кожаный жилет – основа любых дикарских кожаных доспехов." }, { 5.52, "Основа жилета переплетена диким виноградом, что даёт максимальную защиту торса и позволяет использовать мощную магию растения." }, { 15.82, "Для изготовления предмета по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикий виноград." }, { 27.95, "Изготовить это непросто, но, думаю, ты справишься." } } }, t = { d = 21.0, v = "tauren-male#132", n = { x = 175 }, c = { x = { { 0.00, "Да, неплохие вещицы!" }, { 2.03, "Судя по умению и старанию, с какими они изготовлены, ты всерьёз относишься к своему ремеслу." }, { 11.05, "Ну что, мой приказ выполнен, вот и твоя награда." }, { 15.74, "Теперь ты умеешь изготовлять дикарские кожаные жилеты!" } } } } },
    [2857] = { d = 37.5, v = "tauren-male#132", n = { x = 394 }, c = { x = { { 0.00, "Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы." }, { 8.18, "Как и во всех дикарских кожаных доспехах, в основу шлема вплетён дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами." }, { 19.59, "Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!" }, { 24.97, "Но для изготовления изделия по этой выкройке мне понадобятся два ночных мундира, две ночные головные повязки и дикий виноград." }, { 34.95, "Принеси это всё, и выкройка твоя!" } } }, t = { d = 21.8, g = 1, v = "tauren-male#132", n = { m = 189, f = 190 }, c = { m = { { 0.00, "Да, это Ночное снаряжение – именно то, что я просил тебя принести." }, { 6.17, "Впрочем, от кожевника твоего уровня я другого и не ждал." }, { 11.34, "Ты достоин того, чтобы изготовлять дикарские кожаные шлемы." }, { 16.92, "Вот тебе выкройка." }, { 18.67, "Надеюсь, ты применишь её с пользой." } }, f = { { 0.00, "Да, это Ночное снаряжение – именно то, что я просил тебя принести." }, { 5.94, "Впрочем, от кожевника твоего уровня я другого и не ждал." }, { 10.92, "Ты достойна того, чтобы изготовлять дикарские кожаные шлемы." }, { 16.38, "Вот тебе выкройка." }, { 18.07, "Надеюсь, ты применишь её с пользой." } } } } },
    [2858] = { d = 42.8, v = "tauren-male#132", n = { x = 377 }, c = { x = { { 0.00, "Тебе известно уже немало." }, { 2.51, "Однако многое ещё остаётся постичь." }, { 5.78, "Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех." }, { 14.24, "Ноге в них удобно и приятно, и дальний путь в них не так тяжёл." }, { 19.93, "Мягкая же подошва позволяет при необходимости ступать беззвучно." }, { 25.88, "Для изготовления их по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог." }, { 34.67, "И два экземпляра дикого винограда – запомни, два, а не один!" }, { 40.20, "Добудешь всё это – продолжим." } } }, t = { d = 11.8, g = 1, v = "tauren-male#132", n = { m = 110, f = 111 }, c = { m = { { 0.00, "И снова ты выполняешь непростой заказ с искусством опытного профессионала!" }, { 6.74, "Ты заслужил эту выкройку, равно как и мою благодарность." } }, f = { { 0.00, "И снова ты выполняешь непростой заказ с искусством опытного профессионала!" }, { 6.70, "Ты заслужила эту выкройку, равно как и мою благодарность." } } } } },
    [2859] = { d = 38.8, v = "tauren-male#132", n = { x = 399 }, c = { x = { { 0.00, "Ну, теперь мы можем перейти к более сложным вещам." }, { 4.21, "Дикарские кожаные поножи – одна из наиболее прочных и надёжных разновидностей кожаного доспеха." }, { 11.95, "Они отлично защищают ноги." }, { 14.24, "А поскольку в них вшит ещё и дикий виноград, дающий дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи." }, { 25.53, "Для изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда." } } }, t = { d = 23.1, v = "tauren-male#132", n = { x = 204 }, c = { x = { { 0.00, "Ну что, мой приказ снова выполнен отлично." }, { 3.85, "Может, в один прекрасный день уже я явлюсь к тебе, как ученик к учителю, а?" }, { 10.74, "Вот выкройка поножей, а с ней и моя благодарность." }, { 15.25, "Пусти полученные знания в дело, и пусть твои изделия будут достойны твоих способностей!" } } } } },
    [2860] = { d = 47.3, g = 1, v = "tauren-male#132", n = { m = 422, f = 422 }, c = { m = { { 0.00, "Что ж, теперь ты знаешь всё, чему я мог тебя научить." }, { 4.74, "Однако остался ещё один предмет из дикарских кожаных доспехов, выкройки которого у тебя нет." }, { 13.03, "Я не стану заставлять тебя трудиться, чтобы её получить: ты и так сполна расплатился за всё." }, { 21.15, "Однако же отдать тебе его сам я не могу." }, { 24.85, "Ты получишь награду от моей наставницы, той, которая посвятила в тайны нашего ремесла меня самого." }, { 33.69, "Отнеси эту записку Уне." }, { 35.94, "Она обучает кожевников в Громовом Утёсе." }, { 39.56, "Покажи ей записку, и пусть она приветствует тебя как равного, подобно мне самому." } }, f = { { 0.00, "Что ж, теперь ты знаешь всё, чему я мог тебя научить." }, { 4.81, "Однако остался ещё один предмет из дикарских кожаных доспехов, выкройки которого у тебя нет." }, { 13.21, "Я не стану заставлять тебя трудиться, чтобы её получить: ты и так сполна расплатилась за всё." }, { 21.52, "Однако же отдать тебе его сам я не могу." }, { 25.27, "Ты получишь награду от моей наставницы, той, которая посвятила в тайны нашего ремесла меня самого." }, { 34.24, "Отнеси эту записку Уне." }, { 36.52, "Она обучает кожевников в Громовом Утёсе." }, { 40.19, "Покажи ей записку, и пусть она приветствует тебя как равную, подобно мне самому." } } }, t = { d = 35.4, v = "tauren-female#72", n = { x = 362 }, c = { x = { { 0.00, "А, ты от Джангора!" }, { 1.43, "Приятно видеть, что у одного из моих лучших учеников теперь свои ученики…" }, { 7.39, "Джангор – очень талантливый и добросовестный кожевенник." }, { 11.84, "И если он тебя так расхваливает, это говорит в твою пользу." }, { 16.64, "Насколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов?" }, { 22.45, "Позволь же, я завершу твоё обучение, дав тебе вот эту выкройку." }, { 27.48, "Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!" } } } } },
    [2861] = { d = 30.9, v = "scourge-female#79", n = { x = 316 }, c = { x = { { 0.00, "Ходят слухи, что у Табеты, волшебницы, живущей в Пылевых топях, серьёзный зуб на одну песчаную троллиху из Зул'Фаррака." }, { 9.17, "Если ты поговоришь с Табетой, она, конечно, расскажет тебе больше." }, { 14.42, "И захвати с собой друзей." }, { 16.46, "Если она пошлёт тебя в Зул'Фаррак, а, скорее всего, так и будет, то лучше тебе там в одиночку не появляться." }, { 24.86, "Ты найдёшь дом Табеты к западу от Терамора и к северу от руин Каменного Молота." } } }, npc = { [5144] = { d = 30.1, v = "gnome-female#41", n = { x = 316 }, c = { x = { { 0.00, "Ходят слухи, что у Табеты, волшебницы, живущей в Пылевых топях, серьёзный зуб на одну песчаную троллиху из Зул'Фаррака." }, { 8.96, "Если ты поговоришь с Табетой, она, конечно, расскажет тебе больше." }, { 14.09, "И захвати с собой друзей." }, { 16.07, "Если она пошлёт тебя в Зул'Фаррак, а, скорее всего, так и будет, то лучше тебе там в одиночку не появляться." }, { 24.28, "Ты найдёшь дом Табеты к западу от Терамора и к северу от руин Каменного Молота." } } } }, [5497] = { d = 26.1, v = "human-female#47", n = { x = 316 }, c = { x = { { 0.00, "Ходят слухи, что у Табеты, волшебницы, живущей в Пылевых топях, серьёзный зуб на одну песчаную троллиху из Зул'Фаррака." }, { 7.77, "Если ты поговоришь с Табетой, она, конечно, расскажет тебе больше." }, { 12.22, "И захвати с собой друзей." }, { 13.94, "Если она пошлёт тебя в Зул'Фаррак, а, скорее всего, так и будет, то лучше тебе там в одиночку не появляться." }, { 21.06, "Ты найдёшь дом Табеты к западу от Терамора и к северу от руин Каменного Молота." } } } }, [5885] = { d = 28.3, v = "troll-female", n = { x = 316 }, c = { x = { { 0.00, "Ходят слухи, что у Табеты, волшебницы, живущей в Пылевых топях, серьёзный зуб на одну песчаную троллиху из Зул'Фаррака." }, { 8.41, "Если ты поговоришь с Табетой, она, конечно, расскажет тебе больше." }, { 13.23, "И захвати с собой друзей." }, { 15.09, "Если она пошлёт тебя в Зул'Фаррак, а, скорее всего, так и будет, то лучше тебе там в одиночку не появляться." }, { 22.80, "Ты найдёшь дом Табеты к западу от Терамора и к северу от руин Каменного Молота." } } } } }, t = { d = 6.5, v = "human-female#45", n = { x = 57 }, c = { x = { { 0.00, "Да." }, { 0.31, "Верно." }, { 0.94, "У меня большой зуб на эту троллиху." }, { 4.06, "И не один." }, { 5.00, "Хочешь помочь мне?" } } } } },
    [2862] = { d = 38.8, v = "tauren-male", n = { x = 367 }, c = { x = { { 0.00, "О, эти гноллы..." }, { 1.46, "Сказать, что они отравляют нам жизнь – значит ничего не сказать!" }, { 6.93, "Мы здесь постоянно живём под угрозой нападения!" }, { 10.86, "Я не знаю, всегда ли они жили в Фераласе, или пришли сюда откуда-то ещё, но если мы не будем противостоять им достаточно решительно, нам здесь не жить." }, { 23.64, "А в последнее время гноллы совершенно озверели!" }, { 27.72, "Нам необходима твоя помощь, чтобы сократить их численность." }, { 32.80, "Принеси мне десяток их грив, и я щедро вознагражу тебя за труды." }, { 38.26, "Ступай!" } } }, t = { d = 39.2, v = "tauren-male", n = { x = 341 }, c = { x = { { 0.00, "Неплохое начало!" }, { 1.56, "Таких воинов, как ты, ещё поискать!" }, { 4.78, "Я ведь давал такое задание не только тебе." }, { 8.73, "И до тебя немало бойцов сражались с гноллами, и в былые времена наших усилий хватало, чтобы заставить их отступить." }, { 19.35, "Однако в последнее время они упорно прут на север, в наши земли." }, { 25.36, "Гноллы бьются так отчаянно... как будто им некуда отступать!" }, { 30.88, "Однако у меня есть один план." }, { 33.60, "Возможно, он позволит раз и навсегда покончить с этой войной..." } } } } },
    [2863] = { d = 27.8, v = "tauren-male", n = { x = 281 }, c = { x = { { 0.00, "План состоит в том, чтобы одним махом истребить всех предводителей гноллов." }, { 6.08, "Если нам удастся это сделать, в рядах гноллов воцарится хаос." }, { 11.21, "А возможно, до этих блохастых тварей даже дойдёт, что с нами лучше не связываться!" }, { 17.88, "Тебе я поручаю истребить пятерых вожаков гноллов." }, { 21.98, "Только сделать это нужно в течение часа, иначе весь план пойдёт насмарку!" } } }, t = { d = 31.5, g = 1, v = "tauren-male", n = { m = 295, f = 294 }, c = { m = { { 0.00, "Тебе удалось выполнить мою просьбу." }, { 3.00, "Молодец!" }, { 3.73, "Вот, прими эту небольшую награду за свои труды." }, { 7.67, "Теперь, когда число гноллов сократилось, и их вожаки перебиты, эти твари дважды подумают, прежде чем решатся снова напасть на лагерь!" }, { 18.63, "Однако проблемы это не решает..." }, { 21.34, "Гноллы не могли так озвереть безо всякой причины!" }, { 25.43, "И я хочу выяснить, в чём дело, прежде, чем они придут в себя." } }, f = { { 0.00, "Тебе удалось выполнить мою просьбу." }, { 3.12, "Умница!" }, { 3.81, "Вот, прими эту небольшую награду за свои труды." }, { 7.92, "Теперь, когда число гноллов сократилось, и их вожаки перебиты, эти твари дважды подумают, прежде чем решатся снова напасть на лагерь!" }, { 19.34, "Однако проблемы это не решает..." }, { 22.16, "Гноллы не могли так озвереть безо всякой причины!" }, { 26.42, "И я хочу выяснить, в чём дело, прежде, чем они придут в себя." } } } } },
    [2864] = { d = 29.5, v = "goblin-male", n = { x = 349 }, c = { x = { { 0.00, "У моего кузена Тран'река сейчас большие проблемы." }, { 3.72, "Он обещал мне партию панцирей скарабея ещё несколько недель назад, но так и не поставил." }, { 9.49, "Он – мой кузен, так что не хотел бы я посылать кого-то в Прибамбасск, выколачивать из него свои деньги или груз." }, { 17.60, "Можешь поговорить с ним для меня?" }, { 19.80, "Скажи ему, что он должен мне эту поставку ну или придётся отвечать как всем остальным..." }, { 25.57, "Прибамбасск находится на севере пустыни Танарис в Калимдоре." } } }, t = { d = 13.4, g = 1, v = "goblin-male", n = { m = 148, f = 149 }, c = { m = { { 0.00, "Привет!" }, { 0.58, "Так ты общался с моим кузеном Кразеком?" }, { 3.41, "Ну и как он там?" }, { 4.50, "Надеюсь, что в Пиратской бухте к нему хорошо относятся…" }, { 8.49, "Панцири скарабея, говоришь?" }, { 10.48, "Дай мне рассказать тебе одну историю." } }, f = { { 0.00, "Привет!" }, { 0.58, "Так ты общалась с моим кузеном Кразеком?" }, { 3.83, "Ну и как он там?" }, { 4.91, "Надеюсь, что в Пиратской бухте к нему хорошо относятся…" }, { 8.88, "Панцири скарабея, говоришь?" }, { 10.87, "Дай мне рассказать тебе одну историю." } } } } },
    [2865] = { d = 39.3, v = "goblin-male", n = { x = 434 }, c = { x = { { 0.00, "У скарабеев Танариса очень твёрдый панцирь, достаточно твёрдый, чтобы использовать их как строительный материал много для чего." }, { 9.40, "Очень много!" }, { 10.41, "Эти панцири настолько полезная вещь, что ради них скарабеев извели практически под корень." }, { 17.18, "Я знаю, где они ещё водятся, и я поделюсь с тобой, если ты пообещаешь принести мне их панцири, обещаешь?" }, { 24.96, "Так вот." }, { 25.56, "Колония скарабеев находится в Зул'Фарраке." }, { 28.74, "Видимо до троллей ещё не дошло, насколько полезны их панцири." }, { 33.34, "Так что все твои!" }, { 34.63, "Отправляйся в Зул'Фаррак и принеси мне целых панцирей скарабеев." } } }, t = { d = 5.5, g = 1, v = "goblin-male", n = { m = 41, f = 44 }, c = { m = { { 0.00, "Урра!" }, { 0.67, "Ты достал их!" }, { 2.09, "Спасибо, ты мне просто жизнь спас!" } }, f = { { 0.00, "Урра!" }, { 0.63, "Ты достала их!" }, { 2.08, "Спасибо, ты мне просто жизнь спасла!" } } } } },
    [2866] = { d = 33.8, v = "nightelf-female#52", n = { x = 418 }, c = { x = { { 0.00, "К югу от нас находятся руины Соларсаля." }, { 2.64, "Это развалины очень древнего города." }, { 5.17, "Мы уже обследовали руины, но пока не нашли там ничего примечательного и оставили их в покое." }, { 11.30, "Однако не так давно в этих развалинах поселились наги из клана Гребня Ненависти, причём в угрожающих количествах." }, { 18.81, "Поначалу мы решили, что они готовят нападение." }, { 21.94, "Возможно, они его действительно готовят, но нам кажется, что там происходит что-то ещё." }, { 27.71, "Ступай туда, осмотри развалины и обрати внимание на всё, что покажется подозрительным." }, { 33.42, "Удачи!" } } }, t = { d = 29.1, v = "narrator", n = { x = 272 }, c = { x = { { 0.00, "Внимательно изучив беседку, вы обнаруживаете следующее." }, { 4.78, "Во-первых, беседка явно новая, и не похожа на окружающие руины." }, { 10.33, "Во-вторых, столбы беседки исписаны мелкими значками." }, { 14.95, "Значки повторяются, но что это за письмена и что они означают, вам непонятно." }, { 21.61, "Ну и, в-третьих, камень беседки – тёплый на ощупь." }, { 25.91, "Да, всё это, несомненно, подозрительно!" } } } } },
    [2867] = { d = 13.1, v = "narrator", n = { x = 154 }, c = { x = { { 0.00, "Теперь, когда вы обнаружили странную беседку в глубине руин Соларсаля, настало время вернуться в Крепость Оперённой Луны и доложить генералу Шандрисе Оперённой Луне о своём открытии." } } }, t = { d = 28.3, v = "nightelf-female#52", n = { x = 331 }, c = { x = { { 0.00, "С возвращением!" }, { 1.07, "Обнаруженная тобой беседка действительно весьма... подозрительна." }, { 5.60, "Очевидно, что даже если наги и не замышляют нападения, их присутствие не сулит нам ничего хорошего." }, { 12.52, "Ну, как бы то ни было, вот твоя заслуженная награда." }, { 16.11, "Судя по всему, Крепость Оперённой Луны отчаянно нуждается в помощи для борьбы с нагами из клана Гребня Ненависти." }, { 24.04, "Я бы хотела дать тебе ещё одно поручение, если ты не против..." } } } } },
    [2869] = { d = 25.4, v = "nightelf-male#55", n = { x = 292 }, c = { x = { { 0.00, "На данный момент самое разумное – рассчитывать на то, что наги в любом случае попытаются захватить остров." }, { 7.47, "И нам нужно предотвратить эту угрозу, пока не стало поздно." }, { 11.72, "Принеси мне десять штук чешуи Гребня Ненависти." }, { 15.07, "Как их добыть – думаю, ясно?" }, { 17.10, "У тебя будет случай поохотиться на наг, и количество их воинов на острове Сардор уменьшится." }, { 23.56, "И то, и другое нам на пользу!" } } }, t = { d = 22.3, v = "nightelf-male#55", n = { x = 242 }, c = { x = { { 0.00, "Да-да, эта чешуя вполне годится." }, { 2.55, "Думаю, мы отправим её Пратту." }, { 4.76, "Может быть, он сумеет изготовить из неё что-нибудь полезное." }, { 9.19, "А для тебя у меня есть ещё одно задание." }, { 12.21, "Но сначала вот твоя награда за труды." }, { 15.02, "Твоя служба генералу и всей Крепости Оперённой Луны очень ценна перед лицом грозящей нам опасности." } } } } },
    [2870] = { d = 37.7, v = "nightelf-male#55", n = { x = 432 }, c = { x = { { 0.00, "Мы получили новые донесения разведчиков, и теперь неплохо представляем себе, как устроено войско наг." }, { 7.24, "Высшее командование состоит из особ королевской крови." }, { 11.19, "Именно они-то всем и заправляют." }, { 13.51, "Нам стало известно имя одного из самых жестоких нагов, лорда Шалзару." }, { 18.62, "Разведка докладывает, что во время недавних раскопок, которые наги проводили в пещере к югу от основных руин на острове Ужаса, он лично обнаружил некую загадочную реликвию." }, { 31.04, "Его необходимо остановить." }, { 32.98, "Убей его, и принеси мне этот предмет, чтобы мы могли его изучить." } } }, t = { d = 30.6, v = "nightelf-male#55", n = { x = 324 }, c = { x = { { 0.00, "Отлично!" }, { 0.68, "Гибель лорда Шалзару повергнет наг в смятение – надолго, если не навсегда." }, { 6.35, "Так что теперь они представляют значительно меньшую угрозу, чем прежде, и всё это – благодаря тебе!" }, { 13.86, "Вот тебе новая награда из сокровищницы замка." }, { 17.34, "Эта награда заслужена тобой – вся, вплоть до последней монеты!" }, { 22.05, "Добро пожаловать в Крепость Оперённой Луны в любое время, друг мой." }, { 27.10, "Да, и прежде, чем ты уйдёшь... ещё одна просьба..." } } } } },
    [2871] = { d = 24.0, v = "nightelf-male#55", n = { x = 269 }, c = { x = { { 0.00, "Не возьмёшься ли ты доставить эту реликвию моей жене Вестии?" }, { 4.33, "Я был бы тебе очень признателен." }, { 6.65, "Она не только почтенная жрица, но и одна из наиболее сведущих учёных." }, { 11.62, "Я лично не пойму, что это за штука, хоть меня озолоти." }, { 15.56, "Но уж если моя жена в ней не разберётся, значит, не разберётся никто." }, { 20.40, "Она вон там, неподалёку." }, { 22.08, "Занимается, небось." }, { 23.50, "Спасибо!" } } }, t = { d = 34.5, v = "nightelf-female#51", n = { x = 379 }, c = { x = { { 0.00, "Интересно..." }, { 0.90, "Так говоришь, это вещь из руин Соларсаля?" }, { 3.85, "Ну да, Латро прав: мне следовало на это взглянуть..." }, { 7.50, "Такое впечатление, что эта вещь – не оттуда." }, { 10.64, "С другой стороны, на работу наг это тоже не похоже." }, { 14.36, "Далеко не столь чуждое…" }, { 16.03, "Мне потребуется некоторое время на то, чтобы с ней разобраться." }, { 20.45, "А когда я завершу свои исследования, возможно, ты мне снова пригодишься – если ты, конечно, окажешься в это время поблизости." }, { 29.37, "На, возьми это – у нас таких вещиц много, а тебе она, думаю, пригодится!" } } } } },
    [2872] = { d = 26.0, v = "human-male#50", n = { x = 296 }, c = { x = { { 0.00, "Мой давний приятель Столи должен мне особую бутылку рома." }, { 4.07, "Он держит бар в Порту Картеля в Танарисе, и клялся, что ром у него крепче, чем во всей Пиратской бухте." }, { 11.13, "Он даже заявил, что удвоит свой долг мне, если я попробую его напиток и не соглашусь с ним!" }, { 17.39, "Думаю, он потом пожалел о своих словах, потому и не шлёт мне ром." }, { 21.89, "Но я ничего не забываю, поэтому поговори с ним вместо меня..." } } }, t = { d = 9.3, g = 1, v = "human-male", n = { m = 93, f = 94 }, c = { m = { { 0.00, "А, ты уже поговорил с МакКинли!" }, { 2.50, "Он ошибается!" }, { 3.57, "Я вовсе не боюсь угостить его Картельским ромом…" }, { 7.50, "Просто рома у меня нет!" } }, f = { { 0.00, "А, ты уже поговорила с МакКинли!" }, { 2.47, "Он ошибается!" }, { 3.49, "Я вовсе не боюсь угостить его Картельским ромом…" }, { 7.26, "Просто рома у меня нет!" } } } } },
    [2873] = { d = 21.8, v = "human-male", n = { x = 268 }, c = { x = { { 0.00, "Я должен старине МакКинли из Пиратской бухты немного рома." }, { 4.01, "Проблема в том, что ром у меня закончился!" }, { 6.80, "Капитан Куэрго украл последнюю партию и прячет в стенах огороженного пиратского поселения на юге." }, { 13.42, "Если ты отыщешь мою партию рома, я смогу доказать МакКинли, что калимдорская выпивка в сто раз лучше пойла из Пиратской бухты!" } } }, t = { d = 5.4, v = "human-male", n = { x = 58 }, c = { x = { { 0.00, "Здорово, спасибо за помощь!" }, { 2.14, "Теперь я наконец-то выиграю пари у МакКинли." } } } } },
    [2874] = { d = 10.5, v = "human-male", n = { x = 125 }, c = { x = { { 0.00, "Ещё раз спасибо за помощь." }, { 1.84, "Вот тебе бутылка Картельского рома." }, { 4.39, "Отнеси её МакКинли, пора развеять его заблуждения относительно рома из Пиратской бухты." } } }, t = { d = 15.7, v = "human-male#50", n = { x = 150 }, c = { x = { { 0.00, "Попробуем…" }, { 0.93, "Прямо не верится!" }, { 2.48, "Ужасный напиток!" }, { 3.96, "Потрясающий!" }, { 5.05, "Пожалуй, придётся простить Столи долг." }, { 8.31, "Он не обманул меня насчёт Картельского рома." }, { 12.11, "Эта штука густая как соус и жжёт как лава!" } } } } },
    [2875] = { d = 40.9, v = "narrator", n = { x = 467 }, c = { x = { { 0.00, "Злобный пират Андре Огнебородый разыскивается за преступления против Картеля Хитрая Шестерёнка и Прибамбасска." }, { 8.12, "Согласно указу правящего совета, все лица, прочитавшие данный документ, уполномочены применять любые меры при задержании Андре и его пособников." }, { 18.91, "Согласно следующему указу, если Андре скончается или по иным причинам не сможет предстать перед судом, его может представлять его голова." }, { 29.38, "Предоставление упомянутой головы начальнику отдела безопасности Чепухастеру повлечёт за собой заключение весьма выгодного и ответственного контракта." } } }, t = { d = 21.5, v = "goblin-male", n = { x = 235 }, c = { x = { { 0.00, "А, голова Андре." }, { 1.27, "Значит, суд над ним всё-таки состоялся!" }, { 4.08, "Большое спасибо." }, { 5.35, "А теперь распишись тут, и я займусь оплатой твоих услуг." }, { 9.56, "И не беспокойся из-за надписи мелким шрифтом." }, { 12.97, "Ничего страшного там нет, и..." }, { 15.18, "Не думаю, что найдётся такое маленькое увеличительное стекло, всё равно её не прочитаешь." } } } } },
    [2876] = { d = 25.8, v = "narrator", n = { x = 273 }, c = { x = { { 0.00, "В свитке приводится список рейсов между Портом Картеля и Пиратской бухтой." }, { 5.94, "Там перечислены все прошлые и будущие грузы с указанием названий кораблей, везущих их." }, { 12.67, "Напротив некоторых стоит большой крестик, напротив других заметки \"ОТЛИЧНАЯ ДОБЫЧА\" и \"СИЛЬНАЯ ОХРАНА\"." }, { 20.88, "Кое-кто из Порта Картеля очень заинтересуется этим документом." } } }, t = { d = 22.1, g = 1, v = "goblin-male", n = { m = 229, f = 230 }, c = { m = { { 0.00, "Ох, похоже это список рейсов, причём здесь указаны дни и часы отбытия и прибытия!" }, { 6.26, "Если эти сведения попали в руки капитана пиратского корабля, у нас будут большие неприятности!" }, { 13.63, "Ты их у пирата нашёл?" }, { 15.23, "Дурные вести…" }, { 16.35, "Спасибо." }, { 17.04, "Я рад, что ты нашёл этот документ и отправил пирата кормить рыб!" } }, f = { { 0.00, "Ох, похоже это список рейсов, причём здесь указаны дни и часы отбытия и прибытия!" }, { 6.29, "Если эти сведения попали в руки капитана пиратского корабля, у нас будут большие неприятности!" }, { 13.70, "Ты их у пирата нашла?" }, { 15.38, "Дурные вести…" }, { 16.50, "Спасибо." }, { 17.20, "Я рад, что ты нашла этот документ и отправила пирата кормить рыб!" } } } } },
    [2877] = { d = 37.4, v = "dwarf-male", n = { x = 441 }, c = { x = { { 0.00, "Мы, клан Громового Молота, помним прошлое куда лучше, чем наши собратья из Стальгорна." }, { 5.92, "Если вы хотите, чтобы к вам тут хорошо относились, то не должны бояться грязной работы!" }, { 11.91, "Орда забросила одну из своих баз во Внутренних землях, она находится на Осклизлой скале." }, { 18.02, "Сейчас эту базу заполонили слизнюки и пиявки, у нас были на неё планы, но пока там кишат эти твари, мы не можем занять эту позицию." }, { 27.15, "Вот вам, собственно, и работка!" }, { 29.25, "Отправляйтесь туда и убейте по десять зелёных слякочей и нефритовых слизнюков, а потом доложите мне, как всё прошло." }, { 37.09, "Бегом!" } } }, t = { d = 31.3, v = "dwarf-male", n = { x = 328 }, c = { x = { { 0.00, "Нет, подумать только, как вы здорово помогли Громовому Молоту!" }, { 4.73, "Вы отлично работаете, а мы это ценим." }, { 7.61, "Ваша маленькая зачистка куда важнее, чем может показаться на первый взгляд." }, { 13.38, "Осталось ещё истребить слизнюков и пиявок, и тогда мы сможем распространить своё влияние ещё дальше." }, { 20.81, "Новые друзья на Заоблочном Пике – это, конечно, хорошо, но, как говорится, не дружбой единой, так что вот вам ещё кое-что, вдобавок." } } } } },
    [2878] = { t = { d = 13.8, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений." }, { 7.10, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [2879] = { d = 33.8, v = "nightelf-male#55", n = { x = 379 }, c = { x = { { 0.00, "Это, должно быть, посох Равноденствия!" }, { 2.83, "Этот посох, на самом деле, является ключом, которым некогда отмыкали Монолит Равноденствия в Руинах Яростного Ветра, на материке к западу от Сонных Ветвей." }, { 14.29, "Отыщите четыре огня, которые всё ещё пылают среди руин: Самха, Имбел, Бильтан и Лахасса." }, { 20.88, "Добудьте их суть, встаньте перед Монолитом и зарядите посох их силой." }, { 25.95, "Если это действительно посох Равноденствия, вы сумеете отпереть Монолит и достать из него священный артефакт." } } }, t = { d = 21.2, v = "narrator", n = { x = 220 }, c = { x = { { 0.00, "Заряженный посох буквально вырывается из рук." }, { 3.81, "Невероятная мощь отдаётся дрожью во всём теле." }, { 7.63, "Вы касаетесь холодной поверхности Монолита…" }, { 11.29, "Отворяется небольшая дверка, за ней виднеется артефакт." }, { 15.94, "Всё пространство вокруг Монолита Равноденствия озаряется светом." } } } } },
    [2880] = { d = 31.9, v = "dwarf-male", n = { x = 366 }, c = { x = { { 0.00, "Я скажу прямо – мы НЕ принадлежим к Альянсу!" }, { 3.12, "Клан Громового Молота – это независимая организация, и мы относимся хорошо только к тем, кто заслужил это своими делами, а не пустой высокопарной болтовнёй!" }, { 14.02, "Если вы хотите, чтобы вас тут уважали, – докажите, что вы достойны!" }, { 18.74, "В холмах Внутренних земель поселились мерзкие тролли, которые иногда носят племенные ожерелья." }, { 25.50, "Принесите мне пять таких ожерелий, и тогда я, возможно, поверю, что с вами можно иметь дело." } } }, t = { d = 13.0, v = "dwarf-male", n = { x = 134 }, c = { x = { { 0.00, "Вот, о чём я и говорил!" }, { 1.75, "Эти ожерелья доказывают, что вы не боитесь чёрной работы, а клан Громового Молота это ценит." }, { 8.90, "Продолжайте в том же духе, и заслужите наше уважение." } } } } },
    [2881] = { t = { d = 6.9, v = "dwarf-male", n = { x = 70 }, c = { x = { { 0.00, "Чем больше ожерелий, тем меньше троллей во Внутренних землях!" }, { 5.03, "Вы молодец." }, { 6.00, "Так держать!" } } } } },
    [2882] = { d = 27.0, v = "narrator", n = { x = 233 }, c = { x = { { 0.00, "На карте изображена южная часть берега, а ниже имеется элегантная подпись…" }, { 7.03, "Южней Шестерёнки," }, { 8.64, "На юге от дома" }, { 10.09, "Найдёшь ты флаг, мачту и кости – знакомо?" }, { 13.90, "Копай прямо там, если смелости хватит –" }, { 17.71, "За всё тебе злато Куэрго отплатит." }, { 21.02, "Поищешь ты ключ и конечно найдёшь," }, { 24.15, "Но прежде немало крови прольёшь." } } }, t = { d = 4.1, v = "narrator", n = { x = 37 }, c = { x = { { 0.00, "Вас ждут скрытые сокровища капитана Куэрго!" } } } } },
    [2902] = { d = 38.1, v = "tauren-male", n = { x = 381 }, c = { x = { { 0.00, "Гноллы, конечно, умом не блещут, но в последнее время в их деятельности прослеживаются признаки тщательного планирования." }, { 9.82, "Если бы удалось добыть эти планы, возможно, нам было бы проще понять, отчего они так зашевелились в последнее время." }, { 19.49, "Прошу тебя, вернись в лагеря Древолапов и попытайся найти что-нибудь похожее на боевые планы." }, { 27.24, "Наверняка у них есть что-то в этом духе: в последнее время они действуют чересчур согласованно." }, { 35.06, "Отыщи эти планы, и возвращайся ко мне." } } }, t = { d = 29.0, v = "narrator", n = { x = 313 }, c = { x = { { 0.00, "Да, это те самые планы, которые просил отыскать Хадокен Быстрый Странник." }, { 5.80, "Множество стрелок, очевидно, обозначают передвижения войск, однако большая часть этих стрелок направлена не на север, к Лагерю Мохаче, а на юг." }, { 16.76, "В углу карты нарисовано нечто вроде крупного насекомого, окружённого разнообразными значками." }, { 23.95, "Судя по всему, гноллов действительно донимают какие-то насекомые..." } } } } },
    [2903] = { d = 15.1, v = "narrator", n = { x = 160 }, c = { x = { { 0.00, "Теперь, когда планы гноллов добыты, вам остаётся только вернуться с ними в Лагерь Мохаче к Хадокену Быстрому Страннику." }, { 9.40, "Быть может, он или ещё кто-нибудь сумеет разобраться, что замышляют гноллы?" } } }, t = { d = 34.6, v = "tauren-male", n = { x = 279 }, c = { x = { { 0.00, "О, это именно то, что нам нужно!" }, { 3.11, "Я, правда, не мастак разбирать всякие каракули, однако я на своём веку повидал достаточно планов битв, чтобы понять, что творится у гноллов." }, { 16.50, "Похоже, сейчас они ведут войну на два фронта." }, { 20.99, "Один противник – это мы... но, судя по всему, основные их силы брошены на юг." }, { 28.42, "Тут всё не так просто!" }, { 30.49, "Возможно, пора выяснить, с кем же они воюют." } } } } },
    [2904] = { d = 29.7, v = "goblin-male", n = { x = 332 }, c = { x = { { 0.00, "Э-э..." }, { 1.08, "Что случилось?" }, { 2.10, "Последнее, что я помню, это как меня похитили дворфы Чёрного Железа, избили до полусмерти и бросили сюда, к этим омерзительным троггам." }, { 11.66, "Вытащи меня отсюда!" }, { 13.13, "Сделаем так: выведи меня к выходу; если нам удастся выбраться живыми, пойдёшь в Пиратскую бухту и скажешь Скути, что я был в Кабестане и предупредил Оловеня, что дворфы Чёрного Железа тоже как-то связаны с работой над супер-роботом." }, { 29.44, "Идём!" } } }, t = { d = 13.9, g = 1, v = "goblin-male", n = { m = 162, f = 164 }, c = { m = { { 0.00, "Ты достоин награды за то, что вернул Керноби целым и невредимым." }, { 4.73, "Если твой дальнейший путь ведёт в Гномреган, вот это поможет тебе расправиться с никчёмным предателем, Мекжинером Термоштепселем." } }, f = { { 0.00, "Ты достойна награды за то, что вернула Керноби целым и невредимым." }, { 4.82, "Если твой дальнейший путь ведёт в Гномреган, вот это поможет тебе расправиться с никчёмным предателем, Мекжинером Термоштепселем." } } } } },
    [2922] = { d = 39.8, v = "gnome-male", n = { x = 487 }, c = { x = { { 0.00, "Когда пал наш родной город Гномреган, с Техботом, видимо от расстройства, приключилось короткое замыкание." }, { 7.16, "Бедный мой маленький друг!" }, { 8.94, "Он так помогал мне и моим коллегам!" }, { 11.33, "В него встроена куча полезных прибамбасов на все случаи жизни, объём памяти просто огромен, но всё это теперь совершенно бесполезно – его мозг из позитронного стал негатронным!" }, { 23.21, "Все заложенные в него программы теперь работают наоборот." }, { 27.12, "Мой бедный сумасшедший робот теперь бродит по Гномрегану." }, { 31.04, "Может, тебе удастся изловить его и извлечь его ядро памяти." }, { 35.27, "Тогда я смогу разобраться в причинах поломки и, возможно, устраню её." } } }, t = { d = 13.7, v = "gnome-male", n = { x = 130 }, c = { x = { { 0.00, "О, какое счастье!" }, { 1.55, "Спасибо!" }, { 2.32, "Я немедленно начну разбираться с поломкой!" }, { 5.95, "Бедный мой Техбот!" }, { 7.58, "Потерпи, я тебя вылечу." }, { 9.66, "Так, куда же я засунул свой гидропневмогайковёрт..." } } } } },
    [2923] = { d = 24.0, v = "human-male", n = { x = 289 }, c = { x = { { 0.00, "Мехмастер Замыкалец крайне опечален судьбой своего творения – Техбота." }, { 4.92, "Помнится, Техбот был когда-то для гномов весьма полезным инструментом, однако теперь Замыкалец говорит, что он сломан." }, { 13.07, "Очень жаль." }, { 13.88, "Однако, быть может, его ещё возможно починить." }, { 17.11, "Поговори об этом с Мехмастером Замыкальцем в Городе Механиков в Стальгорне." }, { 22.28, "Он будет рад любой помощи." } } }, t = { d = 6.3, v = "gnome-male", n = { x = 56 }, c = { x = { { 0.00, "Да, это правда." }, { 1.44, "Мой Техбот совсем вышел из строя!" }, { 4.48, "Ты сможешь мне помочь?" } } } } },
    [2924] = { d = 30.4, v = "gnome-male", n = { x = 381 }, c = { x = { { 0.00, "Базовый элемент – практически универсальный механизм, широко используемый механиками и кузнецами Гномрегана." }, { 7.23, "Однако в спешке покидая город, никто из нас не догадался прихватить запас этих механизмов с собой." }, { 13.90, "Мне просто необходимо пополнить мои запасы!" }, { 16.88, "Пожалуйста, отправляйся в Гномреган и добудь мне побольше таких механизмов." }, { 21.92, "Думаю, их можно найти в подземельях нашего города – обычно они хранятся в контейнерах-экстраполяторах." }, { 28.84, "Умоляю тебя, поторопись!" } } }, t = { d = 9.2, g = 1, v = "gnome-male", n = { m = 95, f = 97 }, c = { m = { { 0.00, "Прекрасно!" }, { 0.86, "Теперь я могу продолжить свои эксперименты!" }, { 4.38, "Не знаю как благодарить тебя!" }, { 6.75, "Ты спас будущее гномьей науки!" } }, f = { { 0.00, "Прекрасно!" }, { 0.86, "Теперь я могу продолжить свои эксперименты!" }, { 4.35, "Не знаю как благодарить тебя!" }, { 6.71, "Ты спасла будущее гномьей науки!" } } } } },
    [2925] = { d = 31.4, v = "nightelf-male#59", n = { x = 376 }, c = { x = { { 0.00, "Мой друг, гном Клацморт Гайкокрут из Стальгорна, прислал мне письмо, в котором сообщает, что ему необходима помощь." }, { 7.81, "Ему нужно отправиться в Гномреган, некогда величайший город гномов, который был осквернён, и теперь его населяют лишь безумные гномы и их жуткие изобретения." }, { 18.60, "Я не могу покинуть Дарнасс, но душа моя болит за друга." }, { 22.51, "Если ты сможешь помочь ему вместо меня, благодарности моей не будет предела." }, { 27.91, "Ты найдёшь Клацморта в Городе Механиков в Стальгорне." } } }, t = { d = 7.1, g = 1, v = "gnome-male", n = { x = 58 }, c = { m = { { 0.00, "Да!" }, { 0.32, "Да!" }, { 0.65, "Мне очень нужна помощь в Гномрегане!" }, { 3.96, "И герой вроде тебя как раз подойдёт!" } }, f = { { 0.00, "Да!" }, { 0.32, "Да!" }, { 0.64, "Мне очень нужна помощь в Гномрегане!" }, { 3.92, "И героиня вроде тебя как раз подойдёт!" } } } } },
    [2926] = { d = 34.7, v = "gnome-male", n = { x = 407 }, c = { x = { { 0.00, "С самого дня нашего бегства из города, Гноарн думает только о том, как выставить троггов из Гномрегана и очистить город от заражения." }, { 9.25, "У нас с Раззлом есть некоторые идеи на этот счёт, однако похоже, что воплотить их в жизнь сможет только настоящий безумец." }, { 17.87, "Мы ещё не знаем, сработает ли наш замысел – надо всё как следует проверить!" }, { 23.15, "Для этого нам потребуются радиоактивные осадки, оставляемые облучёнными троггами в Гномрегане." }, { 29.71, "Это зелёная светящаяся субстанция." }, { 32.16, "Наполни ею этот фиал и принеси мне!" } } }, t = { d = 14.8, v = "gnome-male", n = { x = 172 }, c = { x = { { 0.00, "Прекрасно!" }, { 0.76, "Теперь пришла пора опробовать нашу новую формулу." }, { 4.39, "Если этот метод сработает, я не только смогу вылечить этого несчастного лепрогнома, но и вернуть свою утраченную шевелюру!" }, { 13.10, "Ну-ка, отойди в сторонку!" } } } } },
    [2927] = { d = 36.9, g = 1, v = "gnome-male", n = { m = 392, f = 394 }, c = { m = { { 0.00, "Вы ведь не думаете, что я всегда был лысым?" }, { 3.15, "Нет, сударь!" }, { 4.08, "Эту трагическую утрату волос вызвала утечка радиации в Гномрегане." }, { 9.10, "До тех пор я был единственным кудрявым гномом во всём Азероте." }, { 13.52, "*Гноарн потрясает в воздухе кулаком.*" }, { 17.04, "Будь прокляты эти проклятые грязные трогги, будь они все прокляты!!!" }, { 21.78, "Может, ещё не поздно." }, { 23.28, "Мы ещё можем исправить дело – я хочу сказать, спасти город!" }, { 27.46, "Поговорите с Оззи Триггервольтом в Караносе." }, { 30.52, "Они со своим партнёром Раззлом как раз пытаются решить эту проблему." } }, f = { { 0.00, "Вы ведь не думаете, что я всегда был лысым?" }, { 3.34, "Нет, сударыня!" }, { 4.47, "Эту трагическую утрату волос вызвала утечка радиации в Гномрегане." }, { 9.80, "До тех пор я был единственным кудрявым гномом во всём Азероте." }, { 14.48, "*Гноарн потрясает в воздухе кулаком.*" }, { 17.84, "Будь прокляты эти проклятые грязные трогги, будь они все прокляты!!!" }, { 22.83, "Может, ещё не поздно." }, { 24.41, "Мы ещё можем исправить дело – я хочу сказать, спасти город!" }, { 28.81, "Поговорите с Оззи Триггервольтом в Караносе." }, { 32.03, "Они со своим партнёром Раззлом как раз пытаются решить эту проблему." } } }, t = { d = 31.4, v = "gnome-male", n = { x = 321 }, c = { x = { { 0.00, "Я думал, что утрата волос нашим выдающимся главой убьёт его, так нет, выжил!" }, { 5.85, "Я стоял рядом с ним, когда тот схватил дозу." }, { 9.29, "И эти замечательные коричневые локоны посыпались на пол прядями!" }, { 14.18, "Клочьями!" }, { 14.93, "Ужас произошедшего только усилился, когда у Гноарна крыша поехала!" }, { 20.09, "Да!" }, { 20.37, "Гноарн, не веря глазам своим, коснулся лысой головы, и во взгляде его загорелась месть!" }, { 27.11, "И тогда он обрушился на троггов!" }, { 29.52, "*Оззи ёжится.*" } } } } },
    [2928] = { d = 34.2, v = "gnome-female", n = { x = 358 }, c = { x = { { 0.00, "Это ужасно." }, { 0.97, "У нас, видно, не хватит запчастей, чтобы собрать всю партию автогиробуророек, которую пора отправить в Дун Морог." }, { 9.65, "Что нам точно нужно – так это детали." }, { 12.57, "И для добычи этих деталей не найти места лучше, чем Гномреган!" }, { 17.43, "Я слышала, что роботы и механизмы, оставшиеся там, бродят по городу как овцы на вольном пастбище." }, { 24.86, "Я хочу от вас, чтобы вы отправились в Гномреган и распотрошили этих роботов на запчасти." }, { 31.60, "Двух дюжин деталей должно хватить." } } }, t = { d = 9.4, v = "gnome-female", n = { x = 97 }, c = { x = { { 0.00, "Это отлично подойдёт." }, { 1.84, "Считайте, что одна автогиробуроройка отремонтирована." }, { 6.29, "Осталось ещё триста девяносто восемь." } } } } },
    [2929] = { d = 33.5, g = 1, v = "gnome-male#178", n = { x = 372 }, c = { m = { { 0.00, "Я доверял Термоштепселю, герой." }, { 2.26, "Никогда я не думал, что он предаст меня и весь гномий род." }, { 6.40, "И ради чего?" }, { 7.37, "Ради власти?" }, { 8.34, "Богатства?" }, { 9.11, "Всё это он и так со временем получил бы." }, { 11.95, "Теперь мы лишились родного дома, а этот безумец остался там править." }, { 16.93, "Король пустого места..." }, { 18.67, "Мы вернём себе Гномреган." }, { 20.48, "Мы не остановимся, пока город снова не станет нашим!" }, { 24.30, "Если ты хочешь присоединиться к нашей борьбе, выполни совсем простое поручение – убей предателя." }, { 31.27, "Уничтожь Мекжинера Термоштепселя." } }, f = { { 0.00, "Я доверял Термоштепселю, героиня." }, { 2.33, "Никогда я не думал, что он предаст меня и весь гномий род." }, { 6.36, "И ради чего?" }, { 7.31, "Ради власти?" }, { 8.25, "Богатства?" }, { 9.01, "Всё это он и так со временем получил бы." }, { 11.78, "Теперь мы лишились родного дома, а этот безумец остался там править." }, { 16.63, "Король пустого места..." }, { 18.33, "Мы вернём себе Гномреган." }, { 20.09, "Мы не остановимся, пока город снова не станет нашим!" }, { 23.81, "Если ты хочешь присоединиться к нашей борьбе, выполни совсем простое поручение – убей предателя." }, { 30.61, "Уничтожь Мекжинера Термоштепселя." } } }, t = { d = 14.1, g = 1, v = "gnome-male#178", n = { x = 171 }, c = { m = { { 0.00, "Я рад, что последнее, что он видел в своей жизни, была твоя стопа, попирающая его преступную голову, герой!" }, { 7.17, "Теперь, когда Термоштепсель мёртв, наши планы по возвращению Гномрегана на шаг приблизились к осуществлению!" } }, f = { { 0.00, "Я рад, что последнее, что он видел в своей жизни, была твоя стопа, попирающая его преступную голову, героиня!" }, { 7.06, "Теперь, когда Термоштепсель мёртв, наши планы по возвращению Гномрегана на шаг приблизились к осуществлению!" } } } } },
    [2930] = { d = 39.0, v = "gnome-male", n = { x = 441 }, c = { x = { { 0.00, "Когда мы бежали из Гномрегана, то оставили там столько данных!" }, { 4.56, "Жизненно важных данных!" }, { 6.34, "Мне нужны данные с призматической перфокарты чрезвычайно секретного терминала матричного перфографа три тысячи пять дэ, что находится в глубинах Гномрегана." }, { 17.57, "Вам нужно добраться до терминала, но сначала надо получить допуск... а для этого надо добраться до терминалов низшего уровня защиты – моделей А, Бэ и Цэ." }, { 28.74, "А для ЭТОГО вам понадобятся перфокарты допуска, начиная с белой... а все перфокарты остались в городе." }, { 36.13, "Это же катастрофа!" }, { 37.52, "Вы можете помочь нам?" } } }, t = { d = 16.1, v = "gnome-male", n = { x = 174 }, c = { x = { { 0.00, "У вас получилось!" }, { 1.34, "Вы нашли призматическую перфокарту и восстановили утраченные данные!" }, { 6.63, "Жизненно, критически, безмерно важные данные, без которых мы просто не смогли бы жить!" }, { 13.34, "Вашу услугу гномы запомнят надолго." } } } } },
    [2931] = { d = 30.4, v = "gnome-male", n = { x = 365 }, c = { x = { { 0.00, "Стальгорнский главный механик Чугунотрубз ищет искателей приключений!" }, { 4.92, "Он собирает отряд для проникновения в Гномреган с целью возвращения данных чрезвычайной важности и секретности." }, { 12.72, "Хотя Чугунотрубз и не состоит в Просвещённой ассамблее чарологии, алхимии и инженерных наук, подобно мне, но он гном толковый, и если он считает это дело важным, то, по моим подсчётам, оно с вероятностью восемьдесят четыре процента важное!" }, { 29.46, "Шансы хорошие!" } } }, t = { d = 7.0, v = "gnome-male", n = { x = 78 }, c = { x = { { 0.00, "Я готовлю миссию в Гномреган для возвращения важных данных." }, { 4.43, "Если вы пришли помочь, то слушайте!" } } } } },
    [2932] = { d = 42.7, v = "troll-male", n = { x = 422 }, c = { x = { { 0.00, "Когда-то тролли из племени Сухокожих были на стороне Орды, но потом они предали Тралла... и это не должно сойти им с рук!" }, { 9.95, "Вот, возьмите мою пику и отправляйтесь во Внутренние земли, это далеко на севере." }, { 16.61, "Сначала найдите Мельницу Таррен – поселение наших союзников, Отрёкшихся, а оттуда идите на северо-восток." }, { 25.17, "Во Внутренних землях убейте двадцать троллей из племени Сухокожих, насадите их черепа на мою пику и воткните её в землю в одной из их деревенек – Хири'вата или Зун'вата." }, { 38.92, "Пусть видят, что за свои действия надо отвечать!" } } }, t = { d = 11.2, v = "troll-male", n = { x = 107 }, c = { x = { { 0.00, "До меня дошли вести о ваших подвигах." }, { 3.39, "Это жестокий поступок, но почётный." }, { 6.47, "Надеюсь, тролли Сухокожих внимут нашему предупреждению." } } } } },
    [2933] = { d = 15.2, v = "narrator", n = { x = 162 }, c = { x = { { 0.00, "В этих бутылках содержится очень сильный зелёный яд." }, { 4.12, "Судя по количеству бутылок в деревне, тролли Сухокожих очень дорожат им." }, { 9.88, "Возможно, аптекарь на Мельнице Таррен тоже заинтересуется этим ядом." } } }, t = { d = 8.9, v = "scourge-male", n = { x = 58 }, c = { x = { { 0.00, "О, что это?" }, { 1.34, "Похоже на яд... яд какого-то паукообразного, да?" }, { 6.69, "Где же вы его взяли?" } } } } },
    [2934] = { d = 28.7, v = "scourge-male", n = { x = 279 }, c = { x = { { 0.00, "Мне нужен свежий образец того яда, что вы приносили мне." }, { 4.81, "Пауки, с которых он был собран, водятся во Внутренних землях – охотьтесь на них, пока вам не удастся добыть неповреждённую ядовитую железу, а потом принесите её мне." }, { 18.56, "Больше всего пауков живёт в тролльем городе Шадра'Алоре." }, { 23.38, "И не задерживайтесь – ядовитая железа нужна мне предельно свежей." } } }, t = { d = 9.3, v = "scourge-male", n = { x = 59 }, c = { x = { { 0.00, "О, замечательно!" }, { 2.11, "Яд свежий и, я уверен, чрезвычайно смертоносный!" }, { 8.31, "Спасибо!" } } } } },
    [2935] = { d = 32.3, v = "scourge-male", n = { x = 306 }, c = { x = { { 0.00, "Яд этих пауков не так силён, как тот, что вы приносили раньше." }, { 5.13, "Наверное, тот яд был от другого паука." }, { 8.35, "Мне нужен свежий образец того яда, а чтобы узнать, откуда он, нужно поговорить с троллем, который много знает о племени Сухокожих – это мастер Гадрин в деревне Сен'джин." }, { 22.90, "Отправляйтесь в Дуротар и поговорите с ним." }, { 26.50, "Он вполне может знать, откуда тролли племени Сухокожих берут этот яд." } } }, t = { d = 9.3, v = "troll-male#77", n = { x = 82 }, c = { x = { { 0.00, "А, так вам нужен свежий яд пауков Сухокожих?" }, { 3.92, "Ну что ж, присядьте... вам не понравится то, что я сейчас скажу." } } } } },
    [2936] = { d = 30.8, v = "troll-male#77", n = { x = 329 }, c = { x = { { 0.00, "Тролли Сухокожих поклоняются паучьей богине, и самый сильный яд берут у неё." }, { 5.87, "Так что если вам нужен этот яд, нужно будет призвать её." }, { 10.22, "Для этого требуется знать её истинное имя – оно начертано на табличке в тролльем городе Зул'Фарраке, это в Танарисе." }, { 19.14, "Табличка находится у гробницы, которую охраняет Тека Мученик." }, { 23.90, "Сразитесь с Текой и прочитайте на табличке имя паучьей богини, а потом возвращайтесь ко мне." } } }, t = { d = 13.4, v = "troll-male#77", n = { x = 133 }, c = { x = { { 0.00, "Элорта но Шадра..." }, { 1.54, "Произносите это имя лишь шёпотом, потому что один его звук повергает духов в смятение." }, { 8.59, "Я напишу его на бумаге и сотворю для вас заклинание призыва." } } } } },
    [2937] = { d = 14.9, v = "troll-male#77", n = { x = 153 }, c = { x = { { 0.00, "Возьмите этот пергамент и прочитайте написанное на нём заклинание около алтаря Шадра'Алора – это в самом сердце владений клана Сухокожих." }, { 11.22, "Это заклинание призовёт Шадру – паучью богиню." } } }, t = { d = 2.6, v = "scourge-male", n = { x = 17 }, c = { x = { { 0.00, "Лучше и быть не могло!" } } } } },
    [2938] = { d = 37.1, v = "scourge-male", n = { x = 370 }, c = { x = { { 0.00, "Этот яд, который вы добыли у паучьего бога Сухокожих, просто поразителен!" }, { 6.06, "Одной капли хватило, чтобы убить почти две дюжины кроликов." }, { 11.09, "Ну, конечно, некоторые из этих кроликов были такие маленькие, что умещались у меня на ладони, так что и организмы их особо не могли сопротивляться токсину..." }, { 23.89, "Но, тем не менее, яд просто убойный!" }, { 26.85, "Я хотел бы отправить образец моему начальнику, аптекарю Фаранеллу в Подгород." }, { 33.21, "Наверняка он захочет испытать его самостоятельно." } } }, t = { d = 24.1, v = "scourge-male", n = { x = 229 }, c = { x = { { 0.00, "Очень хорошо." }, { 1.27, "Лидон говорил, что яд в этом свёртке – самый смертоносный из тех, что ему встречались, и теперь он в срочном порядке ищет способ его применения." }, { 13.86, "Надеюсь, применений ему найдётся немало." }, { 17.43, "Спасибо." }, { 18.22, "Вы оказали Королевскому Фармацевтическому Обществу неоценимую услугу." } } } } },
    [2939] = { d = 37.1, g = 1, v = "nightelf-male#55", n = { x = 406 }, c = { m = { { 0.00, "Руины Фераласа могут быть очень опасны, но зато они способны немало рассказать нам о том, что здесь произошло." }, { 7.65, "Вот, к примеру, несколько дней тому назад, копаясь в развалинах к югу отсюда, я обнаружил одну вещицу." }, { 14.80, "На вид – обычный посох, но меня не покидает ощущение, что посох этот не простой." }, { 20.38, "Мы с Ангелас уже давно корпим над книгами, но так ничего о нём и не узнали." }, { 25.59, "У меня есть коллега в Дарнассе, которая, возможно, сумеет сообщить нам что-нибудь полезное." }, { 31.92, "Путник, быть может, вы сходите к ней и попросите нам помочь?" } }, f = { { 0.00, "Руины Фераласа могут быть очень опасны, но зато они способны немало рассказать нам о том, что здесь произошло." }, { 7.71, "Вот, к примеру, несколько дней тому назад, копаясь в развалинах к югу отсюда, я обнаружил одну вещицу." }, { 14.91, "На вид – обычный посох, но меня не покидает ощущение, что посох этот не простой." }, { 20.53, "Мы с Ангелас уже давно корпим над книгами, но так ничего о нём и не узнали." }, { 25.77, "У меня есть коллега в Дарнассе, которая, возможно, сумеет сообщить нам что-нибудь полезное." }, { 32.15, "Путница, быть может, вы сходите к ней и попросите нам помочь?" } } }, t = { d = 29.4, v = "nightelf-female#51", n = { x = 367 }, c = { x = { { 0.00, "А, так ты от Трояса Лунного Бриза?" }, { 2.26, "Вот вечно он меня донимает: ему всё время кажется, что он обнаружил что-то чрезвычайно важное…" }, { 9.11, "Послушай, я буду говорить откровенно." }, { 11.61, "Троясу каждый раз кажется, будто он нашёл в этих развалинах невесть какую диковинку." }, { 17.20, "На самом же деле всё, что там было ценного, давно уже растащили огры либо гарпии." }, { 22.68, "Ты, конечно, можешь порыться в библиотеке, но не думаю, что ты сумеешь найти что-то, что тебе пригодится." } } } } },
    [2940] = { d = 22.9, v = "narrator", n = { x = 226 }, c = { x = { { 0.00, "Книга выглядит так, как будто её не открывали годами." }, { 4.38, "Переплёт потёрт и запылен, страницы пожелтели..." }, { 8.25, "Тем не менее, проглядев её, вы убеждаетесь, что это именно то, что нужно было Троясу." }, { 15.23, "Вы берёте книгу, но соображаете, что неплохо было бы спросить разрешения прежде, чем её уносить." } } }, t = { d = 11.5, v = "nightelf-female#51", n = { x = 112 }, c = { x = { { 0.00, "Ты хочешь взять \"Историю Фераласа\"?" }, { 2.94, "Дай подумать…" }, { 4.07, "Хорошо, я разрешу тебе позаимствовать эту книгу, если ты сначала окажешь мне одну услугу." } } } } },
    [2941] = { d = 36.4, v = "nightelf-female#51", n = { x = 431 }, c = { x = { { 0.00, "Я в своё время занималась самыми разными предметами, а вот сейчас меня очень интересуют хрустогрызы, которые обитают на побережье Внутренних земель." }, { 10.35, "Мне особенно хочется посмотреть на одного из них: гигантскую черепаху, которую зовут Гаммерита." }, { 16.98, "Я бы отправилась туда сама, но не могу отвлекаться от своих исследований." }, { 22.09, "Добудь мне хотя бы изображение, ладно?" }, { 24.80, "Отнеси это письмо Кургль Поскакушке, которая живёт в Танарисе." }, { 29.16, "Она изобрела для меня машинку, которая может делать картинки." }, { 33.58, "Кажется, Кургль называет это \"снимками\"..." } } }, t = { d = 14.0, g = 1, v = "gnome-female", n = { m = 142, f = 142 }, c = { m = { { 0.00, "А, ты один из студентов Дарин?" }, { 2.37, "Она очень сведущий историк." }, { 4.61, "Тебе повезло, что ты занимаешься под её руководством." }, { 8.65, "Ну, давай я покажу тебе свой супер-хвататель." }, { 12.21, "Он тебе понравится!" } }, f = { { 0.00, "А, ты одна из студенток Дарин?" }, { 2.44, "Она очень сведущий историк." }, { 4.74, "Тебе повезло, что ты занимаешься под её руководством." }, { 8.91, "Ну, давай я покажу тебе свой супер-хвататель." }, { 12.57, "Он тебе понравится!" } } } } },
    [2942] = { d = 7.6, v = "narrator", n = { x = 85 }, c = { x = { { 0.00, "Как только артефакт извлечён из Монолита, вы ощущаете, что энергия посоха Равноденствия идёт на убыль." } } }, t = { d = 22.0, v = "nightelf-male#55", n = { x = 253 }, c = { x = { { 0.00, "Я с самого вашего ухода не отрывался от книги." }, { 3.30, "Так вот: добытый вами камень называется Завтрашний камень." }, { 7.42, "Для чего он нужен, я пока точно не знаю, однако понятно, что пустяковую вещь так прятать не стали бы." }, { 14.53, "Я буду продолжать свои исследования." }, { 17.13, "Надеюсь, что я и в будущем смогу на вас рассчитывать." }, { 20.81, "Спасибо вам за всё!" } } } } },
    [2943] = { d = 7.9, v = "nightelf-female#51", n = { x = 73 }, c = { x = { { 0.00, "Вот книга." }, { 0.93, "Пожалуйста, обращайся с ней бережно!" }, { 4.04, "Ну, ступай." }, { 5.05, "Наверно, Трояс тебя уже заждался." } } }, t = { d = 2.7, v = "nightelf-male#55", n = { x = 16 }, c = { x = { { 0.00, "Книга у вас!" }, { 1.70, "Чудесно!" } } } } },
    [2944] = { d = 24.4, g = 1, v = "gnome-female", n = { m = 256, f = 256 }, c = { m = { { 0.00, "Ты – первый, кто увидит моё новое изобретение!" }, { 3.55, "Тебе нужно только навести его на предмет, который ты хочешь запечатлеть, и нажать на кнопку!" }, { 10.78, "Как там называется то существо из Внутренних земель, которое тебе нужно?" }, { 16.34, "Гаммерита?" }, { 17.18, "На вот, бери и снимай." }, { 18.92, "Я уверена, что Дарин будет в восторге от снимка." }, { 22.67, "Приятного суперхватания!" } }, f = { { 0.00, "Ты – первая, кто увидит моё новое изобретение!" }, { 3.45, "Тебе нужно только навести его на предмет, который ты хочешь запечатлеть, и нажать на кнопку!" }, { 10.50, "Как там называется то существо из Внутренних земель, которое тебе нужно?" }, { 15.92, "Гаммерита?" }, { 16.73, "На вот, бери и снимай." }, { 18.42, "Я уверена, что Дарин будет в восторге от снимка." }, { 22.08, "Приятного суперхватания!" } } }, t = { d = 12.9, v = "nightelf-female#51", n = { x = 116 }, c = { x = { { 0.00, "О да!" }, { 0.47, "Изобретение Кургль оправдало все мои ожидания!" }, { 4.50, "Ты только не зазнавайся, но имей в виду, что я тобой довольна." }, { 9.96, "Так, где же я оставила эту книгу..." } } } } },
    [2945] = { d = 26.8, v = "narrator", n = { x = 280 }, c = { x = { { 0.00, "С тела одного из дворфов Чёрного Железа вы сняли предмет, напоминающий кольцо." }, { 6.15, "Сложно сказать, что это за кольцо, поскольку оно покрыто толстым слоем окаменевшей грязи." }, { 13.30, "Носить его едва ли возможно." }, { 15.63, "Однако вы уверены, что под слоем грязи скрывается драгоценный металл, а может, ещё и самоцвет." }, { 22.99, "Пожалуй, стоит попытаться отчистить всю эту грязь." } } }, t = { d = 32.7, v = "narrator", n = { x = 340 }, c = { x = { { 0.00, "Вы кладёте кольцо в Чистер пять тысяч двести и опускаете в щель серебряную монету." }, { 6.35, "Машина с яростным гудением принимается за работу, скрипя и вибрируя." }, { 11.71, "Сложно представить, что происходит внутри..." }, { 15.17, "Наконец Чистер пять тысяч двести замирает и окошко приёмника со звоном открывается." }, { 21.66, "В нём лежит маленькая аккуратно завёрнутая коробка с красным бантиком." }, { 27.09, "Похоже, Чистер пять тысяч двести также предоставляет подарочную упаковку!" } } } } },
    [2946] = { d = 31.0, v = "dwarf-male", n = { x = 355 }, c = { x = { { 0.00, "Мы хотим, чтобы вы доставили диски, обнаруженные вами, к запечатанным воротам Ульдума." }, { 6.17, "Мы... мы не знаем, что с вами там может случиться." }, { 9.71, "Да, мы знаем, что звучит рискованно." }, { 12.28, "Но может ведь и ничего не случиться?" }, { 14.85, "Может, вам придётся что-то с этими дисками сделать." }, { 18.52, "Возможно, эти диски откроют ворота." }, { 21.15, "Не бойтесь экспериментировать и будьте готовы ко всему." }, { 25.08, "Когда справитесь с заданием, возвращайтесь в Стальгорн." }, { 29.00, "Нам будет что проанализировать!" } } }, t = { d = 32.9, v = "narrator", n = { x = 343 }, c = { x = { { 0.00, "Когда вы прикасаетесь к постаменту, ульдаманские диски в вашем заплечном мешке начинают гудеть и светиться." }, { 8.72, "Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража." }, { 16.77, "\"Приветствую вас." }, { 18.16, "Я – страж входа." }, { 19.48, "Среди дисков доступа не хватает Ульдумских пластин." }, { 23.73, "Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа." }, { 31.13, "Благодарю за внимание\"." } } } } },
    [2947] = { d = 34.0, v = "narrator", n = { x = 325 }, c = { x = { { 0.00, "Открыв коробку, вы видите именно то, что и предполагали – сияющее кольцо!" }, { 6.25, "Вы чувствуете исходящие от него волны магической силы." }, { 10.95, "На внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Стальгорна, а рядом с ним выгравированы инициалы: \"ТдК\"." }, { 21.97, "Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира..." }, { 28.53, "Оставить кольцо себе или вернуть владельцу..." }, { 32.54, "Непростое решение!" } } }, t = { d = 30.2, v = "gnome-male", n = { x = 339 }, c = { x = { { 0.00, "Кольцо, говорите?" }, { 1.28, "Ну конечно, это я его сделал!" }, { 3.47, "До падения Гномрегана у меня была там небольшая мастерская." }, { 7.71, "Видимо, кольцо осталось там, когда пришлось очень быстро давать дёру." }, { 12.72, "Довольно простое кольцо – я сделал таких несколько." }, { 16.44, "Говорите, сняли с дворфа Чёрного Железа?" }, { 19.34, "Занятно, занятно – дело пахнет весьма запутанной интригой..." }, { 23.70, "Возможно, следует дать знать властям, такие вещи не для нашего брата..." }, { 28.78, "Что касается кольца..." } } } } },
    [2948] = { d = 34.9, g = 1, v = "gnome-male", n = { x = 371 }, c = { m = { { 0.00, "Слушайте путник, конечно, это ваше кольцо... но я вам лучшее сделаю!" }, { 5.11, "Дизайн, как я уже сказал, уж очень прост." }, { 8.16, "Теперь я уже намного искуснее, и всего за каких-то тридцать серебряников я вам из него шедевр сделаю!" }, { 15.66, "Ну, чуть побольше тридцати, честно говоря..." }, { 18.91, "Сейчас я в затруднении, все мои запасы материалов иссякли." }, { 23.22, "Если вы принесёте мне слиток серебра и моховой агат, то я нанесу на кольцо решётчатый узор из серебра и агата, и оно станет гораздо более стильным!" }, { 34.03, "Поверьте мне!" } }, f = { { 0.00, "Слушайте путница, конечно, это ваше кольцо... но я вам лучшее сделаю!" }, { 5.12, "Дизайн, как я уже сказал, уж очень прост." }, { 8.14, "Теперь я уже намного искуснее, и всего за каких-то тридцать серебряников я вам из него шедевр сделаю!" }, { 15.55, "Ну, чуть побольше тридцати, честно говоря..." }, { 18.76, "Сейчас я в затруднении, все мои запасы материалов иссякли." }, { 23.03, "Если вы принесёте мне слиток серебра и моховой агат, то я нанесу на кольцо решётчатый узор из серебра и агата, и оно станет гораздо более стильным!" }, { 33.72, "Поверьте мне!" } } }, t = { d = 22.7, v = "gnome-male", n = { x = 244 }, c = { x = { { 0.00, "Ах, именно то, что нужно!" }, { 1.85, "Когда-нибудь, когда я выберусь из этой ямы, в которую так незаслуженно попал, я сделаю для вас, для ВСЕХ лучшие украшения во всём Азероте!" }, { 11.83, "А пока благодарю вас за хлопоты." }, { 14.21, "Обычно я прошу в десять раз больше, чем я взял с вас за кольцо такого качества..." }, { 20.09, "Кстати, о кольцах – вот ваша обновка!" } } } } },
    [2949] = { d = 42.4, v = "narrator", n = { x = 422 }, c = { x = { { 0.00, "Открыв коробку, появившуюся в окошке Чистера пять тысяч двести, вы видите сияющее кольцо!" }, { 7.36, "Надев кольцо на палец, вы чувствуете исходящие от него волны магической силы." }, { 13.77, "На внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Оргриммара, а рядом с ним выгравированы три буквы: \"НОГ\" – это явно начало имени, но даже после чистки прочесть его целиком невозможно." }, { 30.92, "Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира..." }, { 37.18, "Оставить кольцо себе или вернуть владельцу..." }, { 41.01, "Непростое решение!" } } }, t = { d = 35.0, v = "goblin-male", n = { x = 337 }, c = { x = { { 0.00, "Кольцо из Гномрегана?" }, { 1.78, "Очень любопытно..." }, { 3.33, "Нет, его сделал не я." }, { 5.11, "А эта история с Гномреганом... поделом этим болванам." }, { 9.56, "Подумать только, эти ходячие недоразумения вдруг научились делать машины лучше нас..." }, { 16.60, "Что, кольцо было у дворфа Чёрного Железа?" }, { 20.01, "Ещё интереснее..." }, { 21.41, "Возможно, гномы спёрли и подправили чертежи их жутких големов – я бы этому совсем не удивился." }, { 29.12, "Значит, теперь дворфы жаждут мести." }, { 32.16, "Очень любопытно..." }, { 33.71, "Что же о кольце..." } } } } },
    [2950] = { d = 35.8, v = "goblin-male", n = { x = 400 }, c = { x = { { 0.00, "Нет-нет-нет, я не собираюсь утверждать, что это моя работа!" }, { 4.32, "Обычно я такого не делаю." }, { 6.22, "Но твоё сообщение насчёт дворфов Чёрного Железа чрезвычайно полезно." }, { 11.06, "Так и быть, я переделаю для тебя это кольцо, и оно станет куда лучше, чем мог предполагать его создатель." }, { 18.71, "Наверно, это был какой-нибудь гном..." }, { 21.39, "Принеси мне слиток серебра, моховой агат и тридцать серебряных монет – за труды." }, { 27.28, "Я украшу кольцо серебряной решёткой, вправлю в него агат, и это значительно усилит его магические свойства." }, { 35.13, "Интересует?" } } }, t = { d = 12.8, v = "goblin-male", n = { x = 129 }, c = { x = { { 0.00, "Вот оно, твоё кольцо, лучше прежнего." }, { 3.06, "Ещё раз спасибо за сведения об этих дворфах Чёрного Железа." }, { 7.79, "Это объясняет, откуда вдруг у гномов взялись гоблинские идеи..." } } } } },
    [2951] = { d = 31.6, v = "narrator", n = { x = 313 }, c = { x = { { 0.00, "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений." }, { 6.05, "Небольшая табличка, прикреплённая к устройству, гласит: \"Чистер пять тысяч двести\"." }, { 12.17, "Ваши фамильные драгоценности и просто безделушки покрывает пыль веков?" }, { 17.42, "Чистер пять тысяч двести легко справится с этой проблемой!" }, { 21.86, "Опустите в щель приёмника три серебряные монеты и подождите пару минут, пока Чистер пять тысяч двести наводит лоск на ваши украшения." } } }, t = { d = 15.8, v = "narrator", n = { x = 156 }, c = { x = { { 0.00, "Вы кладёте покрытый грязью предмет и три серебряные монеты в Чистер пять тысяч двести, и машина начинает работать, с гудением отскребая въевшуюся грязь." }, { 11.98, "Металлический корпус аппарата скрипит и вибрирует." } } } } },
    [2952] = { t = { d = 36.1, v = "narrator", n = { x = 342 }, c = { x = { { 0.00, "Так же внезапно, как начал, Чистер пять тысяч двести резко останавливается." }, { 5.93, "Из машины раздаётся тихое «дзинь», и её раструб по спирали раскрывается вверх." }, { 11.93, "Внутри Чистера пять тысяч двести лежит маленькая коробочка, перевязанная бантиком." }, { 18.51, "Похоже, очистив предмет от въевшейся грязи, машина ещё и упаковывает его." }, { 24.37, "Даже если она не сработала, по крайней мере, предмет теперь лежит в красивой коробке." }, { 31.30, "Что ж, есть только один способ узнать, очистился он или нет..." } } } } },
    [2953] = { t = { d = 21.6, v = "narrator", n = { x = 207 }, c = { x = { { 0.00, "Чистер пять тысяч двести с яростным гудением принимается за работу." }, { 5.40, "Въевшаяся грязь растворяется под воздействием гномьих чистящих средств." }, { 10.95, "Наконец Чистер пять тысяч двести перестаёт вибрировать." }, { 15.34, "Окошко приёмника со звоном открывается – в нём лежит аккуратно завёрнутая коробка." } } } } },
    [2954] = { d = 30.5, v = "elemental-golem", n = { x = 288 }, c = { x = { { 1.66, "\"Приветствую." }, { 2.82, "Я охраняю вход." }, { 4.13, "Если в вашем наборе дисков нет Ульдумских пластин, вы не сможете посетить комплекс Ульдум.\"" }, { 11.90, "*Должно быть, появление Каменного Стража Норганнона и есть та реакция, на которую рассчитывали те, кто послал вас в пустыню Танарис с платиновыми дисками.*" }, { 23.32, "*Прежде чем продолжить путь, вам предстоит узнать историю Каменного Стража.*" } } }, t = { d = 16.6, v = "narrator", n = { x = 163 }, c = { x = { { 0.00, "В голосе Каменного Стража звучит сила и власть:" }, { 4.05, "\"Когда ты коснёшься пьедестала, диски вернутся к тебе." }, { 8.63, "Получив же Ульдумские пластины и воссоединив их с имеющимися дисками, ты сможешь войти в Ульдум.\"" } } } } },
    [2962] = { d = 31.7, v = "gnome-male", n = { x = 401 }, c = { x = { { 0.00, "Этого образца не только недостаточно для опытов, он ещё и загрязнён." }, { 4.52, "Нам нужно более сильное зелёное свечение." }, { 7.33, "Для наших целей эти трогги явно недостаточно облучены." }, { 11.12, "Вам придётся отправиться в Гномреган и принести некоторое количество радиоактивных образцов прямо с носителей." }, { 18.45, "Я говорю об облучённых слизнюках, шнырюках и ужасниках." }, { 22.11, "Будьте начеку: образцы хранить очень трудно." }, { 25.22, "Возможно, придётся сделать несколько попыток, пока вы не принесёте достаточное количество образцов." } } }, t = { d = 10.2, v = "gnome-male", n = { x = 96 }, c = { x = { { 0.00, "*Оззи рассматривает вас.*" }, { 2.40, "Впечатляюще, у вас не отвалилась ни одна конечность!" }, { 6.74, "Ну-с, посмотрим, на что сгодится эта проба!" } } } } },
    [2963] = { d = 32.6, v = "dwarf-male", n = { x = 382 }, c = { x = { { 0.00, "И снова примите мои поздравления!" }, { 2.47, "Ваша ульдаманская находка привела всю Лигу Исследователей в такое возбуждение!" }, { 8.13, "Лига пыталась разгадать тайны найденных вами миниатюрных платиновых дисков." }, { 13.66, "Ваше неожиданное прибытие сюда, в Зал, даёт мне возможность сказать вам, что мы, похоже, наткнулись на нечто великое!" }, { 21.99, "Историк Карник нашёл важные сведения по поводу истинного происхождения Долины Стражей в пустыне Танарис." }, { 29.53, "Он хочет поговорить с вами как можно скорее!" } } }, t = { d = 26.5, v = "dwarf-male", n = { x = 302 }, c = { x = { { 0.00, "Я счастлив, что вы не оставляете интереса к исследованиям!" }, { 4.14, "Ваши прирождённые талант и отвага помогут нам приоткрыть завесу таких тайн, что мы и надеяться не смели!" }, { 11.64, "Диски Норганнона из Ульдамана служили хранилищем обширных знаний." }, { 16.44, "Вы, так сказать, только чуть копнули." }, { 19.13, "У Создателей, как говорят, в Азероте имелись и другие хранилища." }, { 23.80, "Это подводит нас к проблеме Ульдума..." } } } } },
    [2964] = { d = 28.1, v = "dwarf-male", n = { x = 326 }, c = { x = { { 0.00, "Что сказать… мы зашли в тупик." }, { 2.19, "Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия." }, { 8.81, "Необходимо провести серьёзное исследование и выработать план действий." }, { 13.69, "У меня есть пара идей, и я надеюсь, что вскоре мы наймём тебя и отправим за пластинами." }, { 19.87, "Об этом необходимо сообщить старшему исследователю; он без сомнения пожелает лично поблагодарить тебя за помощь Лиге." } } }, t = { d = 21.4, v = "dwarf-male", n = { x = 252 }, c = { x = { { 0.00, "Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска." }, { 6.65, "Мы зашли настолько далеко благодаря тебе, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум!" }, { 13.62, "Позволь вручить тебе заслуженный гонорар и небольшую премию." }, { 17.81, "Заглядывай к нам время от времени..." }, { 20.27, "Ульдум ждёт тебя!" } } } } },
    [2965] = { d = 34.9, g = 1, v = "tauren-male#68", n = { m = 353, f = 354 }, c = { m = { { 0.00, "Ах, как удачно, что ты снова пришёл ко мне!" }, { 3.38, "Твоя ульдаманская находка вызвала ожесточённые споры среди мудрецов." }, { 8.96, "Я сам только что спорил с друидом, Нарой Буйногривой, когда меня вдруг осенило – её недавние приключения могут быть весьма важны в смысле определения следующего нашего шага в разгадке этой тайны!" }, { 24.90, "Я бы хотел, чтобы ты поговорил с ней о её путешествии в Долину Стражей в пустыне Танарис." }, { 32.10, "Она ждёт тебя на Вершине Старейшин." } }, f = { { 0.00, "Ах, как удачно, что ты снова пришла ко мне!" }, { 3.41, "Твоя ульдаманская находка вызвала ожесточённые споры среди мудрецов." }, { 8.93, "Я сам только что спорил с друидом, Нарой Буйногривой, когда меня вдруг осенило – её недавние приключения могут быть весьма важны в смысле определения следующего нашего шага в разгадке этой тайны!" }, { 24.70, "Я бы хотел, чтобы ты поговорила с ней о её путешествии в Долину Стражей в пустыне Танарис." }, { 31.89, "Она ждёт тебя на Вершине Старейшин." } } }, t = { d = 35.4, g = 1, v = "tauren-female", n = { m = 318, f = 319 }, c = { m = { { 0.00, "В глубине пустыни Танарис есть место, называемое Долиной Стражей." }, { 5.84, "Эти диски, что ты нашёл... в переводе иероглифической надписи на них упоминается место под названием Ульдум." }, { 15.28, "Многие считают, что это миф." }, { 17.84, "Но я-то знаю, что Ульдум существует." }, { 21.12, "Я была там." }, { 22.16, "Ну... хотя бы рядом постояла." }, { 24.80, "Но вот в чём загадка – мы думаем, что есть связь между этими дисками и Ульдумом, потому мы хотим, чтобы ты отправился туда." } }, f = { { 0.00, "В глубине пустыни Танарис есть место, называемое Долиной Стражей." }, { 5.57, "Эти диски, что ты нашла... в переводе иероглифической надписи на них упоминается место под названием Ульдум." }, { 14.64, "Многие считают, что это миф." }, { 17.08, "Но я-то знаю, что Ульдум существует." }, { 2