    [2966] = { d = 36.8, g = 1, v = "tauren-female", n = { m = 367, f = 369 }, c = { m = { { 0.00, "Мы с Ведуном Искателем Истины хотели бы, чтобы ты доставил эти миниатюрные диски к запечатанным воротам Ульдума." }, { 9.09, "Мы... мы не знаем, что может после этого случиться." }, { 13.24, "Да, мы понимаем, это может показаться рискованным." }, { 17.31, "Но может ведь и ничего не случиться?" }, { 20.22, "Может, тебе придётся что-то с этими дисками сделать." }, { 24.51, "Возможно, эти диски откроют ворота." }, { 27.50, "Не бойся испытать их и будь готов ко всему." }, { 30.99, "Узнай, что получится, и возвращайся ко мне." }, { 34.41, "Нам есть много о чём поговорить." } }, f = { { 0.00, "Мы с Ведуном Искателем Истины хотели бы, чтобы ты доставила эти миниатюрные диски к запечатанным воротам Ульдума." }, { 8.83, "Мы... мы не знаем, что может после этого случиться." }, { 12.83, "Да, мы понимаем, это может показаться рискованным." }, { 16.75, "Но может ведь и ничего не случиться?" }, { 19.56, "Может, тебе придётся что-то с этими дисками сделать." }, { 23.69, "Возможно, эти диски откроют ворота." }, { 26.57, "Не бойся испытать их и будь готова ко всему." }, { 30.00, "Узнай, что получится, и возвращайся ко мне." }, { 33.30, "Нам есть много о чём поговорить." } } }, t = { d = 32.5, v = "narrator", n = { x = 343 }, c = { x = { { 0.00, "Когда вы прикасаетесь к постаменту, ульдаманские диски в вашем заплечном мешке начинают гудеть и светиться." }, { 8.61, "Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража." }, { 16.57, "\"Приветствую вас." }, { 17.94, "Я – страж входа." }, { 19.25, "Среди дисков доступа не хватает Ульдумских пластин." }, { 23.44, "Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа." }, { 30.75, "Благодарю за внимание\"." } } } } },
    [2967] = { d = 19.5, v = "narrator", n = { x = 213 }, c = { x = { { 0.00, "Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски." }, { 8.32, "Обретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Громовой Утёс к Наре Буйногривой, сообщить ей о совершённых открытиях." } } }, t = { d = 31.2, v = "tauren-female", n = { x = 315 }, c = { x = { { 0.00, "Тебе не хватило дисков?" }, { 1.99, "Забавно." }, { 2.72, "Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке." }, { 9.64, "Если нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум!" }, { 16.41, "Не знаю, радоваться такой возможности или ужасаться." }, { 20.76, "Быть может, нам придётся пожертвовать всем ради сохранения глубинных тайн земли, грозящих нам всем великими опасностями, хм, в тайне." } } } } },
