    [2969] = { d = 34.0, v = "nightelf-female#52", n = { x = 414 }, c = { x = { { 0.00, "Гнусные таурены из клана Зловещего Тотема ловят лесных дракончиков!" }, { 4.52, "Мы с Джер'Кай понятия не имеем, что они собираются с ними делать, но явно ничего хорошего!" }, { 10.53, "У нас просто не хватит сил, чтобы прорваться в лагерь и освободить пленных дракончиков, но, может быть, с твоей помощью..." }, { 18.50, "Если ты согласишься помочь, и у тебя есть надёжные товарищи, отопри клетку вот этим ключом и выпусти бедных зверушек на волю!" }, { 26.76, "Только постарайся, чтобы все сумели улететь живыми..." }, { 30.33, "Конечно, я тоже буду с тобой!" }, { 32.36, "А Джер'Кай останется здесь." } } }, t = { d = 22.0, g = 1, v = "nightelf-female#52", n = { x = 261 }, c = { m = { { 0.00, "Слава Элуне!" }, { 0.91, "Путник, ты настоящий подарок судьбы!" }, { 3.40, "Нам с Джер'Кай в одиночку никогда бы не удалось спасти бедных дракончиков." }, { 8.37, "Пожалуйста, поговори теперь с Джер'Кай." }, { 11.04, "А мне нужно приготовиться к мести!" }, { 13.35, "Если дракончики на свободе, это ещё не значит, что таурены не наловят новых!" }, { 18.50, "Так что мы с Джер'Кай собираемся перейти в наступление." } }, f = { { 0.00, "Слава Элуне!" }, { 0.90, "Путница, ты настоящий подарок судьбы!" }, { 3.44, "Нам с Джер'Кай в одиночку никогда бы не удалось спасти бедных дракончиков." }, { 8.38, "Пожалуйста, поговори теперь с Джер'Кай." }, { 11.03, "А мне нужно приготовиться к мести!" }, { 13.32, "Если дракончики на свободе, это ещё не значит, что таурены не наловят новых!" }, { 18.44, "Так что мы с Джер'Кай собираемся перейти в наступление." } } } } },
    [2970] = { d = 31.6, g = 1, v = "nightelf-female#51", n = { m = 378, f = 379 }, c = { m = { { 0.00, "Как тебе уже говорила Кайдел, мы с ней собираемся напасть на тауренов из клана Зловещего Тотема." }, { 6.55, "Мы без труда уложим несколько тауренов, не подвергаясь опасности сами, но мы были бы очень рады, если бы и ты присоединился к нам." }, { 15.31, "Тот лагерь, что внизу, тебе известен, но дальше на восток есть ещё несколько." }, { 20.52, "Постарайся причинить тауренам максимальный ущерб." }, { 23.89, "Ну, а после того, как они отведают стрел Кайдел и твоего собственного оружия, мы можем встретиться здесь снова." } }, f = { { 0.00, "Как тебе уже говорила Кайдел, мы с ней собираемся напасть на тауренов из клана Зловещего Тотема." }, { 6.61, "Мы без труда уложим несколько тауренов, не подвергаясь опасности сами, но мы были бы очень рады, если бы и ты присоединилась к нам." }, { 15.50, "Тот лагерь, что внизу, тебе известен, но дальше на восток есть ещё несколько." }, { 20.75, "Постарайся причинить тауренам максимальный ущерб." }, { 24.15, "Ну, а после того, как они отведают стрел Кайдел и твоего собственного оружия, мы можем встретиться здесь снова." } } }, t = { d = 20.6, g = 1, v = "nightelf-female#51", n = { m = 223, f = 223 }, c = { m = { { 0.00, "Да, Кайдел была права насчёт тебя: у тебя талант к этому делу!" }, { 4.66, "Ты – куда более опытный искатель приключений, чем мы обе." }, { 8.86, "Спасибо, что ты с нами!" }, { 10.57, "Этот клан Зловещего Тотема куда опаснее остальных тауренов." }, { 14.97, "Подозреваю, что их боятся даже собственные сородичи!" }, { 18.77, "Впрочем, об этом потом." } }, f = { { 0.00, "Да, Кайдел была права насчёт тебя: у тебя талант к этому делу!" }, { 4.70, "Ты – куда более опытная искатель приключений, чем мы обе." }, { 8.93, "Спасибо, что ты с нами!" }, { 10.65, "Этот клан Зловещего Тотема куда опаснее остальных тауренов." }, { 15.08, "Подозреваю, что их боятся даже собственные сородичи!" }, { 18.92, "Впрочем, об этом потом." }