    [2972] = { d = 29.4, v = "nightelf-female#51", n = { x = 324 }, c = { x = { { 0.00, "Здесь, в глуши, у нас с Кайдел нет особых возможностей тебя вознаградить." }, { 5.32, "Но разумеется, без награды мы тебя не отпустим!" }, { 8.78, "Вот, возьми мой перстень с печаткой." }, { 11.44, "Если когда-нибудь окажешься в ветвях Тельдрассила, зайди в храм в центре Дарнасса." }, { 17.49, "Там ты найдёшь нашу верховную жрицу, Тиранду Шелест Ветра." }, { 21.81, "Кольцо будет для неё знаком, что с нами всё в порядке, и что тебе можно доверять." }, { 27.79, "Мы обе благодарим тебя!" } } }, t = { d = 27.4, g = 1, v = "nightelf-female#173", n = { m = 270, f = 272 }, c = { m = { { 0.00, "Прекрасная история!" }, { 1.61, "Мы очень рады, что ты помог не только драконьему племени, но и одной из наших жриц." }, { 8.34, "Джер'Кай поступила правильно, прислав тебя к нам." }, { 12.37, "Я позабочусь о том, чтобы вернуть ей её кольцо – в Фералас в ближайшее время отправятся наши разведчики." }, { 20.79, "Пусть заодно разведают и это..." }, { 23.35, "Спасибо тебе ещё раз." }, { 25.10, "Чувствуй себя у нас, как дома!" } }, f = { { 0.00, "Прекрасная история!" }, { 1.52, "Мы очень рады, что ты помогла не только драконьему племени, но и одной из наших жриц." }, { 8.03, "Джер'Кай поступила правильно, прислав тебя к нам." }, { 11.83, "Я позабочусь о том, чтобы вернуть ей её кольцо – в Фералас в ближайшее время отправятся наши разведчики." }, { 19.79, "Пусть заодно разведают и это..." }, { 22.22, "Спасибо тебе ещё раз." }, { 23.88, "Чувствуй себя у нас, как дома!" } } } } },
    [2973] = { d = 25.7, g = 1, v = "orc-male#60", n = { x = 271 }, c = { m = { { 0.00, "Приятно познакомиться, герой." }, { 2.24, "Мы с товарищами прибыли сюда, в Фералас, по заданию из Оргриммара." }, { 7.19, "Моя супруга, Коррин, очень любит новые наряды." }, { 10.85, "Я хочу пошить ей новый плащ из прозрачных крылышек лесных дракончиков." }, { 16.15, "Не согласишься ли ты мне помочь?" }, { 18.52, "Те летучие хамелеоны с роскошными крыльями, что мне нужны, водятся к западу от Лагеря Мохаче." } }, f = { { 0.00, "Приятно познакомиться, героиня." }, { 2.39, "Мы с товарищами прибыли сюда, в Фералас, по заданию из Оргриммара." }, { 7.38, "Моя супруга, Коррин, очень любит новые наряды." }, { 11.07, "Я хочу пошить ей новый плащ из прозрачных крылышек лесных дракончиков." }, { 16.40, "Не согласишься ли ты мне помочь?" }, { 18.79, "Те летучие хамелеоны с роскошными крыльями, что мне нужны, водятся к западу от Лагеря Мохаче." } } }, t = { d = 19.4, g = 1, v = "orc-male#60", n = { x = 157 }, c = { m = { { 0.00, "Отлично, герой!" }, { 1.45, "Да, это то, что надо." }, { 3.39, "Этого вполне хватит на плащ для Коррин, а может, и останется!" }, { 8.87, "Спасибо тебе." }, { 10.16, "Ну что, надеюсь, охота была не очень опасной?" }, { 14.28, "А то ведь Фералас ошибок не прощает." }, { 17.50, "Спасибо ещё раз, герой!" } }, f = { { 0.00, "Отлично, героиня!" }, { 1.58, "Да, это то, что надо." }, { 3.48, "Этого вполне хватит на плащ для Коррин, а может, и останется!" }, { 8.85, "Спасибо тебе." }, { 10.12, "Ну что, надеюсь, охота была не очень опасной?" }, { 14.15, "А то ведь Фералас ошибок не прощает." }, { 17.31, "Спасибо ещё раз, героиня!" } } } } },
