    [2975] = { d = 23.4, v = "orc-female#58", n = { x = 246 }, c = { x = { { 0.00, "Присутствие огров из клана Гордунни не может оставаться незамеченным." }, { 5.40, "Оглядись вокруг!" }, { 6.74, "Само их существование уродует эту землю." }, { 9.97, "Необходимо оттеснить их назад, пока они не продвинулись ещё дальше в Фералас." }, { 16.00, "Ступай на север вдоль реки, и увидишь их заставу." }, { 19.86, "Задай им жару!" }, { 21.05, "Пусть видят, что им тут не рады." } } }, t = { d = 6.2, v = "orc-female#58", n = { x = 47 }, c = { x = { { 0.00, "Отлично!" }, { 0.96, "Ещё немного, и эта земля исцелится." }, { 4.79, "Мы не сдадимся!" } } } } },
    [2976] = { d = 30.7, g = 1, v = "orc-male#60", n = { m = 280, f = 282 }, c = { m = { { 0.00, "Чего ещё?" }, { 0.82, "Ах, я говорил о награде?" }, { 2.83, "Ну что ж, поделом мне – пора бы и научиться держать язык за зубами…" }, { 8.35, "Ну, в конце концов, это ты сделал всю работу, тебе и награда полагается." }, { 14.38, "Забирай рога." }, { 15.57, "Я велю упаковать их в ящик." }, { 17.88, "Отыщи на Аллее Чести Белгрома Каменной Булавы." }, { 21.83, "Он расспросит тебя о том, что ты видел, и выдаст заслуженную награду." }, { 27.49, "Пока, герой!" }, { 28.61, "Ещё раз спасибо за всё." } }, f = { { 0.00, "Чего ещё?" }, { 0.82, "Ах, я говорил о награде?" }, { 2.84, "Ну что ж, поделом мне – пора бы и научиться держать язык за зубами…" }, { 8.37, "Ну, в конце концов, это ты сделала всю работу, тебе и награда полагается." }, { 14.50, "Забирай рога." }, { 15.70, "Я велю упаковать их в ящик." }, { 18.02, "Отыщи на Аллее Чести Белгрома Каменной Булавы." }, { 21.98, "Он расспросит тебя о том, что ты видела, и выдаст заслуженную награду." }, { 27.73, "Пока, героиня!" }, { 29.01, "Ещё раз спасибо за всё." } } }, t = { d = 24.2, g = 1, v = "orc-male#60", n = { m = 216, f = 217 }, c = { m = { { 0.00, "Клан Зловещего Тотема?!" }, { 1.96, "Интересно..." }, { 3.02, "Так говоришь, ты наткнулся на них во время охоты в Фераласе?" }, { 8.00, "В самом деле?" }, { 9.20, "Твои новости очень важны для нас, герой." }, { 12.67, "Расскажи всё как было, а я пока отсчитаю твою награду." }, { 17.28, "Да, и пока ты не ушёл: имей в виду, я тебе очень признателен за эту информацию." } }, f = { { 0.00, "Клан Зловещего Тотема?!" }, { 1.97, "Интересно..." }, { 3.03, "Так говоришь, ты наткнулась на них во время охоты в Фераласе?" }, { 8.11, "В самом деле?" }, { 9.32, "Твои новости очень важны для нас, героиня." }, { 12.95, "Расскажи всё как было, а я пока отсчитаю твою награду." }, { 17.57, "Да, и пока ты не ушла: имей в виду, я тебе очень признателен за эту информацию." } } } } },
    [2977] = { d = 18.9, v = "narrator", n = { x = 211 }, c = { x = { { 0.00, "Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски." }, { 8.20, "Обретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Стальгорн и сообщить Лиге Исследователей о совершённых открытиях." } } }, t = { d = 25.4, v = "dwarf-male", n = { x = 279 }, c = { x = { { 0.00, "Тебе не хватило дисков?" }, { 1.78, "Забавно." }, { 2.44, "Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке." }, { 8.64, "Если нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум!" }, { 14.71, "Только представь – у нас появится возможность исследовать место, где трудились Создатели, не роясь в земле!" }, { 22.49, "Хотя землю рыть тоже неплохо... вполне..." } } } } },
