    [2979] = { d = 23.0, v = "orc-female#58", n = { x = 244 }, c = { x = { { 0.00, "Похоже, они готовят какой-то тёмный обряд!" }, { 3.25, "Насколько я понимаю, проводить его будут маги-лорды из клана Гордунни." }, { 8.67, "Отыщи одного из таких магов-лордов, и добудь у него магическую сферу." }, { 14.03, "В такой сфере сокрыта великая мощь, и она поможет нам больше узнать об этом обряде и о магии, которой владеют Гордунни." } } }, t = { d = 7.9, v = "orc-female#58", n = { x = 88 }, c = { x = { { 0.00, "Эта сфера поможет нам получить информацию о Гордунни..." }, { 4.17, "И мы используем эту информацию, чтобы разгромить их!" } } } } },
    [2980] = { d = 37.3, g = 1, v = "orc-female#58", n = { m = 392, f = 393 }, c = { m = { { 0.00, "Теперь, когда ты показал себя настоящим бойцом, я надеюсь, тебе хватит мужества выполнить и следующее задание." }, { 8.66, "Отправляйся в Высокогорные дебри, к юго-западу отсюда." }, { 12.91, "Это земля, которая некогда принадлежала ночным эльфам." }, { 17.24, "Там увидишь заброшенные и разрушенные здания." }, { 20.73, "Когда увидишь среди руин засохшие деревья и осквернённую почву, знай: там и живут Гордунни." }, { 27.78, "Прогони их прочь!" }, { 29.11, "Эти огры куда опаснее тех, с которыми тебе доводилось сталкиваться прежде." }, { 34.97, "Так что будь осторожнее!" } }, f = { { 0.00, "Теперь, когда ты показала себя настоящим бойцом, я надеюсь, тебе хватит мужества выполнить и следующее задание." }, { 8.86, "Отправляйся в Высокогорные дебри, к юго-западу отсюда." }, { 13.19, "Это земля, которая некогда принадлежала ночным эльфам." }, { 17.58, "Там увидишь заброшенные и разрушенные здания." }, { 21.13, "Когда увидишь среди руин засохшие деревья и осквернённую почву, знай: там и живут Гордунни." }, { 28.29, "Прогони их прочь!" }, { 29.63, "Эти огры куда опаснее тех, с которыми тебе доводилось сталкиваться прежде." }, { 35.59, "Так что будь осторожнее!" } } }, t = { d = 4.5, v = "orc-female#58", n = { x = 34 }, c = { x = { { 0.00, "Да, ты воистину надёжный и верный союзник!" } } } } },
    [2981] = { d = 29.6, g = 1, v = "orc-male#60", n = { x = 294 }, c = { m = { { 0.00, "Что, герой, хочешь показать себя?" }, { 2.75, "Фералас для этого самое подходящее место!" }, { 6.15, "Главная сила там – племя огров, именуемое Гордунни, и их становится всё больше и больше." }, { 13.25, "Их надо остановить, пока они не вытеснили из Фераласа нас!" }, { 17.95, "В Лагере Мохаче в Фераласе живёт моя знакомая воительница по имени Рока Орхан." }, { 24.32, "Ступай к ней." }, { 25.41, "Она подробнее расскажет тебе о создавшемся положении." } }, f = { { 0.00, "Что, героиня, хочешь показать себя?" }, { 2.88, "Фералас для этого самое подходящее место!" }, { 6.27, "Главная сила там – племя огров, именуемое Гордунни, и их становится всё больше и больше." }, { 13.33, "Их надо остановить, пока они не вытеснили из Фераласа нас!" }, { 18.01, "В Лагере Мохаче в Фераласе живёт моя знакомая воительница по имени Рока Орхан." }, { 24.35, "Ступай к ней." }, { 25.43, "Она подробнее расскажет тебе о создавшемся положении." } } }, t = { d = 17.3, g = 1, v = "orc-female#58", n = { x = 164 }, c = { m = { { 0.00, "А, тебя прислал Белгром!" }, { 1.99, "Ты как нельзя более вовремя, герой." }, { 4.83, "Я расскажу, что у нас тут творится, а ты уж решай, по зубам ли тебе это..." }, { 10.59, "Хотя если тебя прислал Белгром, значит, сомневаться в твоей доблести не приходится." } }, f = { { 0.00, "А, тебя прислал Белгром!" }, { 1.99, "Ты как нельзя более вовремя, героиня." }, { 4.98, "Я расскажу, что у нас тут творится, а ты уж решай, по зубам ли тебе это..." }, { 10.74, "Хотя если тебя прислал Белгром, значит, сомневаться в твоей доблести не приходится." } } } } },
    [2982] = { d = 33.0, v = "nightelf-female#51", n = { x = 368 }, c = { x = { { 0.00, "Места там опасные, и всё же мы с Троясом исследовали руины в лесах Фераласа." }, { 5.54, "Но в последнее время Трояс ходил в Высокогорные дебри в одиночку." }, { 10.36, "Я серьёзно за него беспокоюсь!" }, { 12.54, "Эти земли захвачены ограми из клана Гордунни, а они не дают спуску тем, кто забредает на их территорию!" }, { 20.12, "Я надеялась, что вы, может быть, согласитесь побывать в развалинах на юго-востоке и перебить часть огров?" }, { 27.71, "Тогда эти места станут не такими опасными." }, { 30.94, "Я вам буду очень признательна!" } } }, t = { d = 5.7, v = "nightelf-female#51", n = { x = 53 }, c = { x = { { 0.00, "О, как я вам благодарна!" }, { 2.00, "Только, пожалуйста, Троясу об этом ни слова!" } } } } },
