    [2987] = { d = 35.8, v = "goblin-male", n = { x = 402 }, c = { x = { { 0.00, "Я только что прибыл сюда, в Фералас." }, { 2.67, "Я слышал, что у огров из клана Гордунни, обитающих в здешних чащобах, попадаются интересные минералы." }, { 9.95, "Неизвестно, к чему они им, но уж, разумеется, по доброй воле они ими делиться не собираются!" }, { 16.65, "Наоборот, норовят спрятать, чтобы бизнесменам вроде меня труднее было до них добраться." }, { 23.03, "Если вы согласитесь помочь, то вот вам моя лопатка." }, { 26.73, "Ступайте в Поселение Гордунни к северу отсюда и накопайте мне образцов кобальта Гордунни." }, { 33.17, "Ищите: где блеснёт синим, там и ройте!" } } }, t = { d = 13.0, v = "goblin-male", n = { x = 142 }, c = { x = { { 0.00, "Отлично!" }, { 0.67, "Захвачу это с собой, когда снова отправлюсь в путь." }, { 4.53, "Я наверняка сумею найти кого-то, кто выложит за эти образцы кругленькую сумму!" }, { 10.39, "Благодарю вас." }, { 11.46, "Вот, возьмите за труды." } } } } },
    [2988] = { d = 18.1, v = "dwarf-male", n = { x = 211 }, c = { x = { { 0.00, "Пропал сын нашего самого лучшего грифона!" }, { 3.01, "Наследник Быстрокрыла, Остроклюв, пропал несколько дней назад, когда охотился вместе с родителями." }, { 10.00, "Я думаю, его похитили тролли!" }, { 12.18, "Помогите нам!" }, { 13.14, "Остроклюва могут держать в клетке в одной из двух деревенек Сухокожих." } } }, t = { d = 12.7, v = "dwarf-male", n = { x = 130 }, c = { x = { { 0.00, "Остроклюва в деревнях нет?" }, { 2.06, "Хм... это плохо." }, { 3.41, "От этого грифона должно было произойти их следующее поколение, и если он погибнет, то наш флот понесёт огромные потери..." } } } } },
    [2989] = { d = 14.0, v = "dwarf-male", n = { x = 152 }, c = { x = { { 0.00, "У троллей племени Сухокожих Остроклюва нет..." }, { 3.40, "Значит, его забрали тролли из клана Порочной Ветви." }, { 7.41, "Поищите детёныша грифона у Алтаря Зула – это на западной границе территории этого клана." } } }, t = { d = 17.7, v = "dwarf-male", n = { x = 192 }, c = { x = { { 0.00, "Остроклюва там не было?" }, { 1.72, "Это плохая, но и хорошая новость..." }, { 4.36, "Хорошо, что его не было на алтаре Зула – там тролли из клана Порочной Ветви совершают свои жертвоприношения." }, { 12.35, "Спасибо за помощь, но, боюсь, вам предстоит ещё одна, более тяжёлая работа." } } } } },
    [2990] = { d = 34.2, v = "dwarf-male", n = { x = 373 }, c = { x = { { 0.00, "Отнесите это перо Тадиусу Мрачной Тени, прорицателю." }, { 4.03, "Он давно ушёл с Заоблачного Пика в поисках тёмных знаний, но в душе он всё ещё с нами, с кланом Громового Молота!" }, { 12.36, "Возможно, он поможет нам разыскать Остроклюва." }, { 15.78, "Это перо нашли в гнезде, где был детёныш грифона, и если вы отдадите его Тадиусу, то он сможет при помощи своего прорицания узнать, где находится сам Остроклюв." }, { 27.67, "Удачи." }, { 28.21, "Тадиуса можно найти в Выжженных землях, в башне магов в Крепости Стражей Пустоты." } } }, t = { d = 15.3, g = 1, v = "dwarf-male", n = { m = 137, f = 137 }, c = { m = { { 0.00, "Ах, да." }, { 0.60, "Это перо грифона, но не обычного, а великого, способного на великие дела..." }, { 6.89, "Если, конечно, он доживёт до зрелого возраста." }, { 10.71, "Хотите найти его?" }, { 12.29, "Что ж, тогда слушайте, храбрый герой." } }, f = { { 0.00, "Ах, да." }, { 0.59, "Это перо грифона, но не обычного, а великого, способного на великие дела..." }, { 6.83, "Если, конечно, он доживёт до зрелого возраста." }, { 10.61, "Хотите найти его?" }, { 12.17, "Что ж, тогда слушайте, храбрая героиня." } } } } },
    [2991] = { d = 22.5, v = "dwarf-male", n = { x = 232 }, c = { x = { { 0.00, "Я найду вам вашего грифона, но вначале вы должны кое-что сделать для меня." }, { 5.85, "В Зул'Фарраке живёт тролль по имени Некрум Кишкожуй, и мне очень-очень нужен его медальон, для изучения." }, { 13.96, "Принесите мне тот медальон, а я найду вам Остроклюва." }, { 18.05, "Зул'Фаррак лежит за океаном, на западе, в пустыне Танарис." } } }, t = { d = 21.0, v = "dwarf-male", n = { x = 222 }, c = { x = { { 0.00, "А, медальон Некрума." }, { 2.25, "Говорят, он дарует троллям удивительное долголетие, но за определённую цену." }, { 7.99, "Надеюсь, мне удастся заполучить силу этого медальона и избежать его... побочных эффектов." }, { 14.91, "Вы оказали мне огромную услугу." }, { 17.33, "Мне осталось лишь выполнить свою часть соглашения." } } } } },
    [2992] = { d = 19.4, v = "dwarf-male", n = { x = 213 }, c = { x = { { 0.00, "Посторонитесь-ка, мне нужно место, чтобы выполнить ритуал прорицания." }, { 5.09, "Я установлю связь между этим пером и его владельцем, а потом попытаюсь найти и самого Остроклюва." }, { 12.30, "Если всё пойдёт по плану, то должно получиться, а если нет..." }, { 16.73, "Вы, на всякий случай, закройте глаза." } } }, t = { d = 5.7, v = "dwarf-male", n = { x = 58 }, c = { x = { { 0.00, "Ритуал прошёл успешно." }, { 1.80, "Я видел Остроклюва и могу сказать, где его найти." } } } } },
    [2993] = { d = 15.0, v = "dwarf-male", n = { x = 161 }, c = { x = { { 0.00, "Остроклюва держат в клетке, на самом верху Джинта'Алора, что во Внутренних землях." }, { 6.19, "Ключ от его клетки находится у коварной жрицы племени Порочной Ветви Ведьмисы." }, { 12.18, "Ну вот, я закончил." }, { 13.61, "Желаю удачи в бою." } } }, t = { d = 10.2, v = "dwarf-male", n = { x = 108 }, c = { x = { { 0.00, "Вы поговорили с Мрачной Тенью?" }, { 2.37, "Что он сказал?" }, { 3.49, "Что?" }, { 3.84, "Остроклюв у троллей Порочной Ветви?" }, { 6.62, "Это немыслимо!" }, { 7.81, "Мы непременно должны его спасти!" } } } } },
    [2994] = { d = 10.9, v = "dwarf-male", n = { x = 126 }, c = { x = { { 0.00, "Мы должны спасти Остроклюва!" }, { 2.13, "Пробейтесь в верхнюю часть Джинта'Алора, отберите ключ у коварной жрицы Ведьмисы, а потом найдите и освободите Остроклюва!" } } }, t = { d = 19.8, v = "dwarf-male", n = { x = 210 }, c = { x = { { 0.00, "Быстрокрыл и Острокоготь минуту назад вернулись вместе со своим детёнышем, и теперь от него не отходят." }, { 7.91, "Ох, как гляну на них, аж слеза прошибает..." }, { 11.17, "Я даже не знаю, чем мы можем отблагодарить вас." }, { 14.78, "Грифоны Заоблачного Пика и их всадники навсегда запомнят ваше имя." } } } } },
    [2995] = { d = 35.4, v = "scourge-female#79", n = { x = 381 }, c = { x = { { 0.00, "Сторожка Кель'Данил – центр сообщения Высших эльфов Внутренних земель." }, { 5.44, "Их посланники пытаются установить отношения с другими расами и делятся с ними сведениями о троллях из племени Сухокожих, обитающих в южной части Внутренних земель." }, { 18.07, "Все документы, связанные с этим, хранятся в сторожке." }, { 22.18, "Мы не хотим, чтобы Высокодолье заключало союзы с другими народами." }, { 27.35, "Уничтожь документы Высокодолья." }, { 29.79, "Есть мнение, что рукописи не горят… у тебя есть шанс проверить, так ли это." } } }, t = { d = 10.5, v = "scourge-female#79", n = { x = 105 }, c = { x = { { 0.00, "Великолепно." }, { 1.07, "Пока эльфы будут восстанавливать утраченную информацию, мы сможем ещё навсегда отрезать их от остального мира…" } } } } },
    [2996] = { d = 25.8, v = "orc-male", n = { x = 238 }, c = { x = { { 0.00, "Я многому тебя научил, теперь тебе нужен новый наставник." }, { 5.09, "Он живёт в Кабестане, его зовут Страхад." }, { 8.56, "Он человек, но он отнюдь не слаб." }, { 11.34, "Он невелик ростом, но силён!" }, { 13.73, "Ты уже можешь вызывать более могущественных существ, и он научит тебя этому." }, { 20.36, "Ступай к нему." }, { 21.67, "Он живёт в Кабестане, над портом, рядом с башней." } } }, t = { d = 17.3, v = "human-male#50", n = { x = 184 }, c = { x = { { 0.00, "Шумный денёк в Кабестане, не так ли?" }, { 2.74, "Обожаю наблюдать за суетой портового города." }, { 6.26, "Столько тайн, столько приключений… и столько неведения." }, { 10.54, "Это что, ненависть я вижу в твоих глазах?" }, { 13.85, "Превосходно." }, { 14.83, "Мы найдём ей достойное применение." } } } } },
    [2997] = { d = 28.0, v = "dwarf-male", n = { x = 329 }, c = { x = { { 0.00, "Привет." }, { 0.55, "Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, посети Стальгорн и поговори с одной из самых почитаемых наших сестёр – Тизой Кузнебой." }, { 13.39, "Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от тебя." }, { 22.67, "Ты можешь найти её на верхнем этаже Зала Тайн, что в Палатах Магии." }, { 27.28, "Удачи тебе." } } }, t = { d = 6.2, v = "dwarf-female#33", n = { x = 61 }, c = { x = { { 0.00, "Привет тебе." }, { 1.13, "Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла." } } } } },
    [2998] = { d = 26.4, g = 1, v = "human-male", n = { m = 312, f = 314 }, c = { m = { { 0.00, "Приветствую тебя, брат мой." }, { 1.84, "Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе." }, { 7.48, "Он считает, что тебе пора пройти некое испытание..." }, { 11.03, "Он вообще весьма неплохо о тебе отзывался, надо сказать." }, { 14.96, "На твоём месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдётся на это время." }, { 22.25, "Ищи его в Соборе Света: там он проводит большую часть времени." } }, f = { { 0.00, "Приветствую тебя, сестра моя." }, { 2.02, "Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе." }, { 7.49, "Он считает, что тебе пора пройти некое испытание..." }, { 10.94, "Он вообще весьма неплохо о тебе отзывался, надо сказать." }, { 14.74, "На твоём месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдётся на это время." }, { 21.82, "Ищи его в Соборе Света: там он проводит большую часть времени." } } }, t = { d = 6.1, v = "human-male", n = { x = 61 }, c = { x = { { 0.00, "Как красив Штормград, не правда ли?.." }, { 2.90, "Твой визит в это время более чем уместен." } } } } },
    [2999] = { d = 22.2, v = "dwarf-male", n = { x = 267 }, c = { x = { { 0.00, "Привет." }, { 0.54, "Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, поднимись наверх и поговори с одной из наших самых почитаемых сестёр – Тизой Кузнебой." }, { 13.17, "Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что от тебя ожидается." } } }, t = { d = 6.2, v = "dwarf-female#33", n = { x = 61 }, c = { x = { { 0.00, "Привет тебе." }, { 1.13, "Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла." } } } } },
    [3000] = { d = 24.6, v = "human-male", n = { x = 299 }, c = { x = { { 0.00, "Привет." }, { 0.54, "Я знаю, что ты рук не покладаешь, помогая жителям Азерота, но когда тебе выпадет свободная минутка, вернись в Стальгорн и поговори с Тизой Кузнебой." }, { 10.35, "Она одна из тех, к кому обращаются самые молодые дворфские паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от всех нас." }, { 20.21, "Ты можешь найти её на верхнем этаже Зала Тайн, что в Палатах Магии." } } }, t = { d = 2.6, v = "dwarf-female#33", n = { x = 27 }, c = { x = { { 0.00, "Приветствую и добро пожаловать." } } } } },
    [3001] = { d = 39.9, v = "scourge-male#82", n = { x = 354 }, c = { x = { { 0.00, "Я многому тебя научил, и теперь тебе нужен новый наставник." }, { 5.53, "Он живёт в Кабестане, его зовут Страхад." }, { 9.19, "Это человек, но отнюдь не слабый." }, { 12.28, "Также у нас нет причин смотреть на него как на потенциального врага... по крайней мере, пока что." }, { 20.98, "Он обладает силой и заслуживает уважения." }, { 24.72, "Я чувствую в тебе готовность призывать более могущественных существ, и он может обучить тебя этому." }, { 33.74, "Ступай к нему." }, { 35.12, "Ты найдёшь его в Кабестане, над портом, рядом с башней." } } }, t = { d = 16.0, v = "human-male#50", n = { x = 166 }, c = { x = { { 0.00, "Всегда жизнь в Кабестане бьёт ключом, не так ли." }, { 3.70, "Ну так, на то он и порт." }, { 5.48, "Столько всяких тайн, столько приключений, столько невежества…" }, { 10.32, "Я вижу ненависть в твоих глазах?" }, { 12.95, "Хорошо, мы найдём ей полезное применение." } } } } },
    [3002] = { d = 17.8, v = "orc-female#58", n = { x = 186 }, c = { x = { { 0.00, "Я, конечно, хорошо знаю своих врагов, и всё же я – только воительница." }, { 5.35, "Я даже приблизительно не представляю, на что способна эта сфера." }, { 10.22, "Но я знаю одного мага в Оргриммаре, который сможет рассказать нам о ней больше." }, { 16.26, "Отнеси сферу к нему!" } } }, t = { d = 7.4, v = "troll-male", n = { x = 54 }, c = { x = { { 0.00, "Да, занятная вещица…" }, { 2.28, "Этот шар весьма могуществен, но и очень опасен!" } } } } },
    [3022] = { d = 22.8, g = 1, v = "gnome-female", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Я вижу, как ты предан сему достойному делу." }, { 3.40, "Да, конечно, ты можешь мне помочь!" }, { 6.04, "Отнеси этот ящик с яйцами Эреласу Янтарному Небу." }, { 10.00, "Он друид, и заботится об этих яйцах, помогает вылупиться маленьким гиппогрифам и обучает их." }, { 17.08, "Его можно найти в Тельдрассиле, в маленькой деревушке Рут'теран на юге." } }, f = { { 0.00, "Я вижу, как ты предана сему достойному делу." }, { 3.72, "Да, конечно, ты можешь мне помочь!" }, { 6.36, "Отнеси этот ящик с яйцами Эреласу Янтарному Небу." }, { 10.32, "Он друид, и заботится об этих яйцах, помогает вылупиться маленьким гиппогрифам и обучает их." }, { 17.40, "Его можно найти в Тельдрассиле, в маленькой деревушке Рут'теран на юге." } } }, t = { d = 16.7, v = "nightelf-male#55", n = { x = 173 }, c = { x = { { 0.00, "Спасибо за помощь." }, { 1.45, "Если бы не мы, гиппогрифы уже вымерли бы." }, { 4.63, "Впрочем, тебе случалось бывать в Фераласе, и ты знаешь не понаслышке, как опустошили землю Гордунни." }, { 12.31, "Что ж, ты видишь, как я занят." }, { 14.59, "Можешь идти." }, { 15.62, "Ещё раз спасибо." } } } } },
    [3042] = { d = 21.0, v = "nightelf-male#55", n = { x = 253 }, c = { x = { { 0.00, "Тролли племени Песчаной Бури в Зул'Фарраке делают состав для закалки из песчаника, и я бы не отказался заполучить себе немного этого состава." }, { 9.86, "Он весьма ценится мастерами, так что если ты принесёшь мне достаточно, то и вознаграждение будет щедрым." }, { 16.96, "Зул'Фаррак находится к северо-западу от Прибамбасска." }, { 20.60, "Удачи!" } } }, t = { d = 9.8, v = "nightelf-male#55", n = { x = 93 }, c = { x = { { 0.00, "Отлично!" }, { 0.76, "Так много и все отборные!" }, { 2.90, "Этот запас я буду расходовать долго…" }, { 6.10, "Благодарю тебя." }, { 7.48, "Прими это в качестве оплаты." } } } } },
    [3062] = { d = 44.5, v = "tauren-male", n = { x = 409 }, c = { x = { { 0.00, "Эдана Коготь Ненависти – царица гарпий из стаи Студёных Ключей, что обитают в руинах к западу отсюда." }, { 8.83, "Эдана – это воплощённое зло." }, { 11.26, "Я слышал, что сердце у неё каменное." }, { 14.38, "Она не ведает иных чувств, кроме ненависти, которую питает ко всему живому." }, { 21.03, "Сразись с Эданой и принеси мне её тёмное сердце!" }, { 25.17, "Я слышал, что гарпии носят при себе рог." }, { 28.69, "Если затрубить в него у камней Когтя Ненависти, в северной части руин, появится царица." }, { 36.43, "Представь, как она удивится, когда обнаружит, что это был зов не её сородичей, но самой смерти!" } } }, t = { d = 12.8, v = "tauren-male", n = { x = 89 }, c = { x = { { 0.00, "Ну, вот теперь я точно знаю, что Эдана мертва!" }, { 5.23, "А это сердце я оставлю себе на память о твоём подвиге." }, { 11.37, "Спасибо тебе!" } } } } },
    [3063] = { d = 44.4, v = "tauren-male", n = { x = 389 }, c = { x = { { 0.00, "В своё время я был закалённым охотником." }, { 3.46, "Не было на свете такого зверя, которого я бы боялся." }, { 8.20, "До тех пор, пока…" }, { 9.73, "Я был один в лесу, точил свой клинок после жаркой битвы, и тут на меня напали из засады!" }, { 17.70, "Меня окружили гарпии, я еле сумел добраться до безопасного места." }, { 23.65, "Я ещё и теперь как наяву слышу их вопли..." }, { 27.43, "И с тех пор я уже никогда не мог стать прежним." }, { 31.53, "В душе у меня кипит ненависть – все эти годы я жажду сквитаться с ними!" }, { 38.05, "Гарпии из стаи Студёных Ключей водятся к западу отсюда." }, { 43.03, "Отомсти за меня." } } }, t = { d = 6.1, v = "tauren-male", n = { x = 47 }, c = { x = { { 0.00, "Спасибо тебе." }, { 1.56, "Ты возвращаешь покой душе старого таурена." } } } } },
    [3065] = { d = 15.4, v = "orc-male#60", n = { x = 150 }, c = { x = { { 0.00, "А!" }, { 0.21, "Тебе тут пергамент прислали, пока тебя не было." }, { 4.07, "Прочитай, когда время будет." }, { 6.43, "Это, кажется, от Франга, наставника воинов." }, { 9.94, "Он хочет с тобой поговорить." }, { 12.22, "Он обычно сидит в тени у входа в Логово." } } }, t = { d = 23.0, g = 1, v = "orc-male#60", n = { m = 227, f = 228 }, c = { m = { { 0.00, "Наша долина – подходящее место, чтобы упражняться в воинских навыках." }, { 5.57, "Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готов продолжать обучение – возвращайся ко мне." }, { 15.14, "Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!" } }, f = { { 0.00, "Наша долина – подходящее место, чтобы упражняться в воинских навыках." }, { 5.67, "Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готова продолжать обучение – возвращайся ко мне." }, { 15.48, "Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!" } } } } },
