    [3100] = { d = 16.6, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.25, "Похоже, что на нём стоит печать Ллана, местного наставника воинов." }, { 9.34, "На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." } } }, t = { d = 23.1, v = "human-male#50", n = { x = 276 }, c = { x = { { 0.00, "Разберись в обстановке, изучи местность и возвращайся, как только тебе потребуется обучение." }, { 6.33, "Я тут в любое время дня и ночи." }, { 8.50, "Рыцари Серебряной Длани постарались, чтобы эти места стали почти безопасными, но если ты поговоришь с горожанами, то, думаю, заметишь, что у всех найдутся проблемы, с которыми без помощи воина не разобраться." }, { 22.77, "Удачи!" } } } } },
    [3101] = { d = 17.4, v = "human-male", n = { x = 235 }, c = { x = { { 0.00, "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.29, "Похоже, что на нём стоит печать брата Самуэля, местного наставника паладинов." }, { 10.09, "На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." } } }, t = { d = 31.0, g = 1, v = "human-male", n = { m = 349, f = 349 }, c = { m = { { 0.00, "Тебе следует усвоить ещё пару вещей." }, { 2.63, "Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно." }, { 9.14, "Отблеск Благодати лежит на тебе – это видят и друзья, и враги." }, { 13.59, "Кроме того, когда ты наберёшься опыта, тебе надо будет овладеть новыми способностями." }, { 19.60, "Вот тут я тебе и пригожусь." }, { 21.48, "Когда ты почувствуешь себя готовым, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать." }, { 29.81, "Удачи тебе, герой!" } }, f = { { 0.00, "Тебе следует усвоить ещё пару вещей." }, { 2.62, "Для многих в этих краях ты станешь примером для подражания, поэтому веди себя соответственно." }, { 9.11, "Отблеск Благодати лежит на тебе – это видят и друзья, и враги." }, { 13.53, "Кроме того, когда ты наберёшься опыта, тебе надо будет овладеть новыми способностями." }, { 19.52, "Вот тут я тебе и пригожусь." }, { 21.39, "Когда ты почувствуешь себя готовой, приходи ко мне, и я научу тебя тому, что тебе, по моему мнению, пора будет узнать." }, { 29.69, "Удачи тебе, героиня!" } } } } },
