    [3103] = { d = 16.9, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.35, "Похоже, что на нём стоит печать Анетты, местной наставницы жрецов." }, { 9.52, "На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." } } }, t = { d = 16.6, v = "human-female#45", n = { x = 178 }, c = { x = { { 0.00, "Как только ты наберёшься опыта, возвращайся ко мне, и я, как сумею, поделюсь с тобой своими знаниями." }, { 7.42, "А пока ступай с милосердием в сердце, и пусть мудрость ведёт тебя." }, { 12.34, "Помни, мир станет лучше, только если мы сами исцелим его." } } } } },
    [3104] = { d = 16.9, v = "human-male", n = { x = 226 }, c = { x = { { 0.00, "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.34, "Похоже, что на нём стоит печать Келдена, местного наставника магов." }, { 9.55, "На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." } } }, t = { d = 24.6, g = 1, v = "human-male", n = { m = 268, f = 270 }, c = { m = { { 0.00, "Ха-ха, я знал, что не ошибусь адресом!" }, { 2.74, "Значит, ты готов принять свою судьбу?" }, { 5.54, "Готов бросить вызов богам и любым другим силам, что встанут на твоём пути к знаниям и могуществу?" }, { 12.65, "Не скрою, тебя будут не только уважать, но и бояться." }, { 16.56, "Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение." }, { 21.90, "Приходи ко мне, когда станешь опытнее." } }, f = { { 0.00, "Ха-ха, я знал, что не ошибусь адресом!" }, { 2.73, "Значит, ты готова принять свою судьбу?" }, { 5.59, "Готова бросить вызов богам и любым другим силам, что встанут на твоём пути к знаниям и могуществу?" }, { 12.75, "Не скрою, тебя будут не только уважать, но и бояться." }, { 16.65, "Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение." }, { 21.99, "Приходи ко мне, когда станешь опытнее." } } } } },
    [3105] = { d = 17.0, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Меня просили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.23, "Похоже, что на нём печать Друзиллы, одной из наших местных наставниц." }, { 9.56, "На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь, в аббатстве." } } }, t = { d = 29.5, g = 1, v = "human-female#47", n = { m = 344, f = 345 }, c = { m = { { 0.00, "Чем могущественнее ты будешь становиться, тем сильнее будет искушение... так что не забывай обуздывать себя." }, { 7.47, "Ладно, скажу тебе прямо: любой, кто занимается тайными искусствами, может пасть." }, { 13.16, "Особенно тот, кто имеет дело с тварями из Круговерти Пустоты." }, { 17.46, "Будь терпелив и благоразумен... но не давай благоразумию подавлять твои амбиции." }, { 23.03, "Как только ты станешь опытнее, возвращайся ко мне, и я открою тебе тайны нашего мастерства." } }, f = { { 0.00, "Чем могущественнее ты будешь становиться, тем сильнее будет искушение... так что не забывай обуздывать себя." }, { 7.51, "Ладно, скажу тебе прямо: любой, кто занимается тайными искусствами, может пасть." }, { 13.24, "Особенно тот, кто имеет дело с тварями из Круговерти Пустоты." }, { 17.57, "Будь терпелива и благоразумна... но не давай благоразумию подавлять твои амбиции." }, { 23.23, "Как только ты станешь опытнее, возвращайся ко мне, и я открою тебе тайны нашего мастерства." } } } } },
    [3106] = { d = 14.9, v = "dwarf-male", n = { x = 164 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну." }, { 5.36, "Изучи её, когда будет время." }, { 7.55, "Думаю, руну прислал Тран, наставник воинов." }, { 10.79, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 29.3, v = "dwarf-male", n = { x = 318 }, c = { x = { { 0.00, "Я думаю, ты это уже знаешь, но на всякий случай скажу: в бою дворфы используют магию вместо ружей." }, { 7.21, "Кое-кто из нас чтит Священный Свет – так же, как и некоторые люди." }, { 11.78, "Ну и, наконец, трогги – о них ты узнаешь позже." }, { 15.13, "А сейчас тебе надо знать одно: я здесь, чтобы тебе помочь." }, { 19.38, "Я буду учить тебя воинскому мастерству." }, { 22.28, "Если захочешь узнать пару новых приёмов, приходи сюда, и мы посмотрим, что я могу для тебя сделать." } } } } },
    [3107] = { d = 14.8, v = "dwarf-male", n = { x = 169 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну." }, { 5.20, "Изучи её, когда будет время." }, { 7.31, "Думаю, руну прислал Бромос, наставник паладинов." }, { 10.84, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 36.1, g = 1, v = "dwarf-male", n = { m = 402, f = 402 }, c = { m = { { 0.00, "Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту." }, { 7.62, "Мы испытываем огромное уважение к традициям ордена." }, { 11.43, "Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение." }, { 18.05, "Думаю, нам обоим придётся немного поработать вместе." }, { 21.92, "Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело." }, { 31.41, "Негоже отправляться в далёкие странствия неподготовленным, верно?" } }, f = { { 0.00, "Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту." }, { 7.37, "Мы испытываем огромное уважение к традициям ордена." }, { 11.05, "Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение." }, { 17.45, "Думаю, нам обоим придётся немного поработать вместе." }, { 21.20, "Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело." }, { 30.37, "Негоже отправляться в далёкие странствия неподготовленной, верно?" } } } } },
    [3108] = { d = 15.4, v = "dwarf-male", n = { x = 169 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну." }, { 5.39, "Изучи её, когда будет время." }, { 7.59, "Думаю, руну прислал Торгас, наставник охотников." }, { 11.25, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 29.5, g = 1, v = "dwarf-male", n = { m = 317, f = 318 }, c = { m = { { 0.00, "Всегда нужно помнить об уважении к тому миру, в котором мы живём." }, { 4.90, "Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна." }, { 16.18, "Я сделаю всё, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя." }, { 24.23, "Когда ты решишь, что готов, приходи ко мне, и мы займёмся твоим обучением." } }, f = { { 0.00, "Всегда нужно помнить об уважении к тому миру, в котором мы живём." }, { 4.82, "Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна." }, { 15.92, "Я сделаю всё, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя." }, { 23.85, "Когда ты решишь, что готова, приходи ко мне, и мы займёмся твоим обучением." } } } } },
    [3109] = { d = 15.1, v = "dwarf-male", n = { x = 170 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну." }, { 5.31, "Изучи её, когда будет время." }, { 7.47, "Думаю, руну прислал Сольм, наставник разбойников." }, { 11.07, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 35.7, g = 1, v = "dwarf-male", n = { m = 396, f = 396 }, c = { m = { { 0.00, "Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласен?" }, { 9.66, "Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад, хитрый приёмчик..." }, { 17.59, "Понимаешь, о чём я?" }, { 18.94, "Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет." }, { 24.63, "Да, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен." }, { 32.75, "Думаю, наша помощь им пригодится." } }, f = { { 0.00, "Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласна?" }, { 9.84, "Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад, хитрый приёмчик..." }, { 17.91, "Понимаешь, о чём я?" }, { 19.28, "Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет." }, { 25.08, "Да, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен." }, { 33.35, "Думаю, наша помощь им пригодится." } } } } },
    [3110] = { d = 15.2, v = "dwarf-male", n = { x = 168 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну." }, { 5.36, "Изучи её, когда будет время." }, { 7.54, "Думаю, руну прислал Брансток, наставник жрецов." }, { 11.11, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 23.8, g = 1, v = "dwarf-male", n = { m = 250, f = 252 }, c = { m = { { 0.00, "Я – тот, кто будет заниматься твоим обучением." }, { 3.43, "Когда будешь готов, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов." }, { 14.14, "Свет на твоей стороне, а с ним и весь Стальгорн..." }, { 17.78, "Эй, ты что разволновался?" }, { 19.60, "Это тебя ни к чему не обязывает... ну, почти ни к чему..." } }, f = { { 0.00, "Я – тот, кто будет заниматься твоим обучением." }, { 3.36, "Когда будешь готова, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов." }, { 13.89, "Свет на твоей стороне, а с ним и весь Стальгорн..." }, { 17.45, "Эй, ты что разволновалась?" }, { 19.29, "Это тебя ни к чему не обязывает... ну, почти ни к чему..." } } } } },
    [3112] = { d = 14.8, v = "dwarf-male", n = { x = 171 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту записку." }, { 5.36, "Прочти её, когда будет время." }, { 7.54, "Думаю, записку прислал Тран, наставник воинов." }, { 10.86, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 27.2, g = 1, v = "dwarf-male", n = { m = 286, f = 287 }, c = { m = { { 0.00, "Да-да, теперь я окончательно понял, чего хотят гномы." }, { 4.09, "И знаешь что?" }, { 5.09, "Даю слово, я сделаю всё возможное, чтобы ты и твои родичи смогли отвоевать свой дом." }, { 11.39, "Да, вот ещё что: когда почувствуешь, что готов к обучению, приходи к старине Трану – я с радостью поделюсь с тобой всем, что знаю." }, { 20.90, "Конечно, не за просто так, но ты можешь не беспокоиться: цена невысока." }, { 26.13, "Ну, до встречи!" } }, f = { { 0.00, "Да-да, теперь я окончательно понял, чего хотят гномы." }, { 4.09, "И знаешь что?" }, { 5.09, "Даю слово, я сделаю всё возможное, чтобы ты и твои родичи смогли отвоевать свой дом." }, { 11.39, "Да, вот ещё что: когда почувствуешь, что готова к обучению, приходи к старине Трану – я с радостью поделюсь с тобой всем, что знаю." }, { 20.98, "Конечно, не за просто так, но ты можешь не беспокоиться: цена невысока." }, { 26.21, "Ну, до встречи!" } } } } },
    [3113] = { d = 15.2, v = "dwarf-male", n = { x = 177 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту записку." }, { 5.37, "Прочти её, когда будет время." }, { 7.54, "Думаю, записку прислал Сольм, наставник разбойников." }, { 11.25, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 35.4, v = "dwarf-male", n = { x = 387 }, c = { x = { { 0.00, "Я стараюсь не привлекать к себе особого внимания, так что если где-то что-то и пропадает, наша репутация от этого не страдает." }, { 9.04, "Если тебе потребуется чему-нибудь подучиться или ещё что, приходи в любое время." }, { 14.85, "Ну, мы ведь с тобой друг друга понимаем?" }, { 17.69, "Мы-то знаем, что бывают времена, когда верить можно только семье... и такие времена сейчас настали, верно?" }, { 25.50, "Гномреган... захвачен, и, думаю, это была не последняя беда, которая на нас свалилась... но мы с тобой всегда прикроем друг другу спину, да?" } } } } },
    [3114] = { d = 14.8, v = "dwarf-male", n = { x = 173 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту записку." }, { 5.30, "Прочти её, когда будет время." }, { 7.44, "Думаю, записку прислал Маррайк, наставник магов." }, { 10.91, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 29.2, v = "gnome-male", n = { x = 311 }, c = { x = { { 0.00, "О, да!" }, { 0.46, "Тайная магия..." }, { 1.63, "Конечно-конечно..." }, { 3.00, "Первое, что тебе следует усвоить, – это очень простой урок: не ищи неприятностей." }, { 9.00, "Поверь, они найдут тебя сами." }, { 11.28, "А если ты сбережёшь несколько монет, то сможешь купить мне кружку эля... или какое-нибудь заклинание для себя." }, { 19.24, "Да, ещё совет: держись подальше от Гномрегана." }, { 22.56, "Пока, думаю, с тебя хватит." }, { 24.65, "Доброго тебе пути!" }, { 26.08, "Захочешь подучиться – приходи в любое время." } } } } },
    [3115] = { d = 22.0, v = "dwarf-male", n = { x = 238 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту записку." }, { 5.67, "Прочти её, когда будет время." }, { 7.97, "Думаю, записку прислал Аламар, наставник чернокнижников." }, { 12.22, "Если представится случай, отыщи его в Старой Наковальне." }, { 16.54, "Да, вот ещё что... будь осторожнее." }, { 19.04, "Таким, как ты, тут не слишком-то доверяют." } } }, t = { d = 31.3, g = 1, v = "gnome-male", n = { m = 307, f = 310 }, c = { m = { { 0.00, "Но всё это не имеет значения." }, { 2.32, "Важно лишь одно — ты узрел свой собственный Святой Свет." }, { 6.67, "Ты понял, откуда приходит истинная сила." }, { 9.90, "Ты осознал, что иметь собственных союзников куда... разумнее." }, { 14.67, "Особенных союзников." }, { 16.29, "Таких, что будут повиноваться до последнего вздоха." }, { 20.29, "И вот тут вступаю я." }, { 21.84, "Я могу обучить тебя основам этих особых сил." }, { 25.42, "Приходи ко мне почаще — и я научу тебя новым заклинаниям." } }, f = { { 0.00, "Но всё это не имеет значения." }, { 2.42, "Важно лишь одно — ты узрела свой собственный Святой Свет." }, { 7.03, "Ты поняла, откуда приходит истинная сила." }, { 10.48, "Ты осознала, что иметь собственных союзников куда... разумнее." }, { 15.53, "Особенных союзников." }, { 17.22, "Таких, что будут повиноваться до последнего вздоха." }, { 21.40, "И вот тут вступаю я." }, { 23.01, "Я могу обучить тебя основам этих особых сил." }, { 26.74, "Приходи ко мне почаще — и я научу тебя новым заклинаниям." } } } } },
    [3116] = { d = 13.1, v = "nightelf-male#54", n = { x = 144 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашей наставницы воинов, Алайссии." }, { 5.39, "Похоже, она хотела бы поговорить с тобой, когда у тебя будет время." }, { 10.57, "Изучи знак и отправляйся к Алайссии." } } }, t = { d = 36.1, v = "nightelf-female#52", n = { x = 435 }, c = { x = { { 0.00, "Вскоре ты увидишь на ветвях нашего дома представителей других рас – но не поддавайся предубеждению." }, { 6.55, "Они здесь приняты как гости." }, { 8.47, "Они помогут нам, когда смогут помочь." }, { 11.05, "Не все они действуют из альтруизма, однако всем им можно в некоторой степени доверять." }, { 16.76, "Но всё это сейчас не в счёт." }, { 18.62, "Мы должны подумать о тебе и о том, как ты сможешь помочь нашему народу." }, { 23.37, "Я здесь именно ради этого." }, { 25.17, "Я буду учить тебя действовать как воин по мере того, как ты будешь обретать силу." }, { 30.69, "Возвращайся ко мне, когда пожелаешь, – и я сделаю всё возможное, чтобы помочь тебе." } } } } },
    [3117] = { d = 12.9, v = "nightelf-male#54", n = { x = 141 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашей наставницы охотников, Аянны." }, { 5.37, "Похоже, она хотела бы поговорить с тобой, когда у тебя будет время." }, { 10.54, "Изучи знак и отправляйся к Аянне." } } }, t = { d = 25.8, v = "nightelf-female#51", n = { x = 291 }, c = { x = { { 0.00, "Когда обретёшь достаточно опыта в Тенистой долине, приходи ко мне – я помогу тебе постичь умения охотника и осознать твои собственные возможности." }, { 10.59, "Это опасные времена, и даже умения твоих питомцев нельзя принимать как должное – в мире существуют вещи куда более опасные, нежели ты можешь вообразить." }, { 21.84, "Да хранит тебя Элуна, я буду ждать твоего возвращения." } } } } },
    [3118] = { d = 13.0, v = "nightelf-male#54", n = { x = 146 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашего наставника разбойников, Фрагуна." }, { 5.59, "Похоже, он хотел бы поговорить с тобой, когда у тебя будет время." }, { 10.46, "Изучи знак и отправляйся к Фрагуну." } } }, t = { d = 33.7, g = 1, v = "nightelf-male#55", n = { m = 384, f = 384 }, c = { m = { { 0.00, "Но до тех пор знай, что в эти трудные времена услуги разбойников востребованы гораздо больше, чем обычно." }, { 7.44, "Мирные отношения с другими расами могут рухнуть в любой момент, к тому же ходят слухи о представителях Орды, ищущих, как бы посеять семена ещё большего недоверия." }, { 19.14, "Помни об этом." }, { 20.24, "По мере того как будешь становиться более опытным и обретать силы, приходи сюда, и я позабочусь о твоём обучении." }, { 28.39, "Тебе важно знать, помимо всего прочего, как обращаться с выбранным оружием." } }, f = { { 0.00, "Но до тех пор знай, что в эти трудные времена услуги разбойников востребованы гораздо больше, чем обычно." }, { 7.05, "Мирные отношения с другими расами могут рухнуть в любой момент, к тому же ходят слухи о представителях Орды, ищущих, как бы посеять семена ещё большего недоверия." }, { 18.15, "Помни об этом." }, { 19.19, "По мере того как будешь становиться более опытной и обретать силы, приходи сюда, и я позабочусь о твоём обучении." }, { 26.91, "Тебе важно знать, помимо всего прочего, как обращаться с выбранным оружием." } } } } },
    [3119] = { d = 13.4, v = "nightelf-male#54", n = { x = 138 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашей наставницы жрецов, Шанды." }, { 5.45, "Похоже, она хотела бы поговорить с тобой, когда у тебя будет время." }, { 10.89, "Изучи знак и отправляйся к Шанде." } } }, t = { d = 20.7, v = "nightelf-female#51", n = { x = 251 }, c = { x = { { 0.00, "Пока что не беспокойся о мире за пределами Тельдрассила – ещё успеешь." }, { 4.52, "Иди теперь и поговори с остальными, живущими в Тенистой долине, – они расскажут тебе о том, что тут происходит." }, { 11.75, "Помогай им в том, в чём сможешь, и в любой момент, когда тебе нужно будет обучение, возвращайся сюда, и я научу тебя всему, что знаю сама." } } } } },
    [3120] = { d = 13.4, v = "nightelf-male#54", n = { x = 144 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашего наставника друидов, Марданта." }, { 5.69, "Похоже, он хотел бы поговорить с тобой, когда у тебя будет время." }, { 10.82, "Изучи знак и отправляйся к Марданту." } } }, t = { d = 27.8, v = "nightelf-male#54", n = { x = 275 }, c = { x = { { 0.00, "Отныне я буду твоим наставником." }, { 2.76, "Мой долг не только научить тебя истолковывать то, что вещают нам духи, но и дать тебе представление о сложностях и тайнах Изумрудного Сна." }, { 13.96, "По мере обучения ты узнаешь больше о нашем сонном трансе." }, { 18.81, "Но пока что приходи ко мне так часто, как сочтёшь нужным, и я обучу тебя всему, следуя традициям ночных эльфов." } } } } },
    [3121] = { d = 29.9, v = "troll-male#77", n = { x = 311 }, c = { x = { { 0.00, "Для начала мне понадобится помощь Нииру Огненного Клинка из Оргриммара!" }, { 5.46, "Он изготовил состав, который нужен мне для... ну, потом увидишь." }, { 10.37, "В общем, ступай в Оргриммар." }, { 12.58, "Да, и захвати с собой вот это." }, { 14.93, "Это мумифицированная голова, которую я обещал Нииру в обмен на его травки." }, { 20.74, "Какой-то злосчастный дворф, с которым я повстречался в лесу..." }, { 25.44, "Думаю, Нииру останется доволен." }, { 27.93, "Ищи его в расселине Теней." } } }, t = { d = 9.7, v = "orc-male", n = { x = 80 }, c = { x = { { 0.00, "О, я давно ждал, когда Узер'и её пришлёт…" }, { 3.85, "А вот и смесь трав, которую я изготовил для его... экспериментов." } } } } },
    [3122] = { d = 8.6, v = "orc-male", n = { x = 74 }, c = { x = { { 0.00, "Вот травы." }, { 0.97, "Отнеси их знахарю Узер'и." }, { 3.31, "И, пожалуйста, передай ему, что сушёная голова – то, что надо." } } }, t = { d = 17.1, v = "troll-male#77", n = { x = 170 }, c = { x = { { 0.00, "Да, это именно то, что мне нужно, чтобы изготовить сосуд уменьшения!" }, { 5.59, "Скоро увидим, так ли могущественны мои последние заклинания, как я рассчитывал!" }, { 11.98, "Так, минутку..." }, { 13.23, "Мне надо совершить ритуал и использовать травы..." } } } } },
    [3123] = { d = 39.3, v = "troll-male#77", n = { x = 397 }, c = { x = { { 0.00, "Это будет испытание – испытание созданного мною ритуала, и твоих способностей тоже." }, { 6.86, "Возьми этот сосуд." }, { 8.47, "С его помощью ты сможешь уменьшать и помещать внутрь него разных существ." }, { 14.46, "Отправляйся во Внутренние земли и отыщи существ, которых называют дикими совухами." }, { 21.18, "Они некогда были питомцами богини Элуны, которую почитают ночные эльфы." }, { 27.16, "Коварные и дикие совухи станут твоей первой добычей." }, { 31.55, "Убей десять и с помощью сосуда уменьшения возьми их души в плен, пока они не успели ускользнуть." } } }, t = { d = 17.0, v = "troll-male#77", n = { x = 184 }, c = { x = { { 0.00, "Дух существа, преданного насильственной смерти, может вырваться на волю и попытаться отомстить." }, { 7.33, "А помещая их в сосуд уменьшения, мы препятствуем духу вырваться на свободу." }, { 13.13, "И теперь мы можем использовать его, как нам угодно!" } } } } },
    [3124] = { d = 32.7, g = 1, v = "troll-male#77", n = { m = 352, f = 353 }, c = { m = { { 0.00, "Ты уже доказал, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения." }, { 6.96, "Теперь я попрошу тебя пленить другое создание." }, { 10.61, "Гиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их твёрды и преданны." }, { 18.19, "Твоя задача – убить десять блеклопёрых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души." }, { 28.18, "Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда." } }, f = { { 0.00, "Ты уже доказала, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения." }, { 6.93, "Теперь я попрошу тебя пленить другое создание." }, { 10.53, "Гиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их твёрды и преданны." }, { 18.00, "Твоя задача – убить десять блеклопёрых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души." }, { 27.85, "Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда." } } }, t = { d = 18.6, v = "troll-male#77", n = { x = 185 }, c = { x = { { 0.00, "Если мы убьём существо и позволим его духу ускользнуть, оно может превратиться в куда более могущественное создание!" }, { 9.65, "И тогда оно будет вечно грозить нам местью." }, { 13.37, "Я поручил тебе опасную работу." }, { 15.97, "Но тебе удалось с ней справиться." } } } } },
    [3125] = { d = 31.5, v = "troll-male#77", n = { x = 325 }, c = { x = { { 0.00, "Теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо." }, { 10.18, "Лесные дракончики, о которых я говорю, были союзниками ночных эльфов." }, { 15.66, "Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа." }, { 22.82, "Убей восемь летучих хамелеонов или радужных дракончиков, и плени их души." }, { 28.65, "Эти существа водятся к западу отсюда." } } }, t = { d = 10.3, v = "troll-male#77", n = { x = 101 }, c = { x = { { 0.00, "Спасибо!" }, { 0.77, "Теперь нам будет доступна сила духа лесных дракончиков." }, { 5.62, "Надеюсь, ты не откажешься поработать на меня ещё немного?" } } } } },
    [3126] = { d = 28.9, v = "troll-male#77", n = { x = 306 }, c = { x = { { 0.00, "Следующей нашей добычей станут бродячие лесные великаны, живые деревья." }, { 5.72, "Ночные эльфы считают древней своими союзниками в борьбе против Орды." }, { 11.23, "Движения древней медлительны, но в качестве защитников они незаменимы!" }, { 16.74, "И вскоре мы сможем использовать их мощь в своих целях." }, { 20.98, "Отыщи трёх бродячих лесных древней, убей их и используй этот сосуд уменьшения, чтобы пленить их души!" } } }, t = { d = 5.3, v = "troll-male#77", n = { x = 48 }, c = { x = { { 0.00, "Спасибо!" }, { 0.81, "Наше собрание уменьшенных существ почти готово..." } } } } },
    [3127] = { d = 32.9, v = "troll-male#77", n = { x = 357 }, c = { x = { { 0.00, "Последнее, что от тебя потребуется – это отправиться на северо-запад и отыскать основного противника." }, { 7.66, "Когда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам." }, { 15.25, "Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами." }, { 23.45, "Я жажду подчинить себе подобную мощь!" }, { 26.33, "Убей семь горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!" } } }, t = { d = 12.0, v = "troll-male#77", n = { x = 137 }, c = { x = { { 0.00, "Только представь себе, какими возможностями мы теперь обладаем!" }, { 4.66, "С теми материалами, которые тебе удалось собрать, я могу сколько угодно уловлять души этих созданий." } } } } },
    [3128] = { d = 37.8, v = "troll-male#77", n = { x = 430 }, c = { x = { { 0.00, "Для выполнения моего замысла мне нужны некоторые материалы..." }, { 4.49, "Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу." }, { 10.30, "Во-первых, расколотый ствол фераласского древня." }, { 13.80, "Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и волшебных драконов на западе." }, { 21.59, "Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа." }, { 28.99, "И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий." } } }, t = { d = 8.0, v = "troll-male#77", n = { x = 70 }, c = { x = { { 0.00, "Отлично!" }, { 0.83, "Всё это, вкупе с духами животных, позволит мне изготовить именно то, что нужно!" } } } } },
    [3129] = { d = 15.6, v = "troll-male#77", n = { x = 158 }, c = { x = { { 0.00, "Вселить дух животного в оружие – процесс непростой!" }, { 4.14, "Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу." }, { 13.07, "Погоди немного, я скоро вернусь." } } }, t = { d = 11.4, v = "troll-male#77", n = { x = 97 }, c = { x = { { 0.00, "Ну что ж, выбирай, что тебе больше по нраву!" }, { 4.00, "В это оружие навечно заточены души могучих созданий." }, { 8.91, "Теперь их сила – твоя сила." } } } } },
    [3130] = { d = 30.4, g = 1, v = "nightelf-female#52", n = { m = 382, f = 383 }, c = { m = { { 0.00, "В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу." }, { 5.06, "Он следит за боевыми приготовлениями наг." }, { 7.71, "Сама же я буду продолжать осуществлять общее наблюдение." }, { 11.42, "Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным." }, { 23.18, "Как бы то ни было, Латроникус тебя ждёт." }, { 25.77, "Пока что ты показал себя молодцом." }, { 28.07, "Продолжай в том же духе!" }, { 29.66, "Можешь идти." } }, f = { { 0.00, "В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу." }, { 4.98, "Он следит за боевыми приготовлениями наг." }, { 7.59, "Сама же я буду продолжать осуществлять общее наблюдение." }, { 11.24, "Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным." }, { 22.84, "Как бы то ни было, Латроникус тебя ждёт." }, { 25.39, "Пока что ты показала себя молодцом." }, { 27.70, "Продолжай в том же духе!" }, { 29.27, "Можешь идти." } } }, t = { d = 25.0, v = "nightelf-male#55", n = { x = 278 }, c = { x = { { 0.00, "Что ж, отлично: я ценю готовность сражаться в тех, с кем имею дело." }, { 4.80, "Генерал Лунное Перо поручила мне подготовить нападение на наг." }, { 9.28, "Мои планы состоят из двух частей: во-первых, мы ослабим их силы и лишим командования, а во-вторых, выясним, что же они делают в этих развалинах." }, { 19.66, "С твоей помощью мы сумеем задать нагам перцу, не ослабляя защиты крепости." } } } } },
    [3141] = { d = 6.6, v = "nightelf-male#55", n = { x = 74 }, c = { x = { { 0.00, "Так ты хочешь вступить в сражение с демонами?" }, { 3.25, "Тебе лучше для начала услышать то, что я скажу." } } }, t = { d = 1.4, v = "nightelf-male#55", n = { x = 10 }, c = { x = { { 0.00, "Да будет так..." } } } } },
    [3161] = { d = 33.4, v = "goblin-male", n = { x = 373 }, c = { x = { { 0.00, "Я учёный, но в душе – кладоискатель!" }, { 2.54, "Давным-давно, когда в этих землях жили тролли, они обожествляли Газ'риллу, огромную гидру, и создали множество украшений в форме её тела." }, { 12.58, "Их вырезали из особого материала, я называю его \"газ'риллий\" в честь богини-гидры." }, { 18.51, "Я и сам ухитрился найти несколько образцов, но для исследований этого не хватает – может, ты мне ещё принесёшь?" }, { 26.33, "Я даже создал детектор, позволяющий мигом обнаружить газ'риллий!" }, { 31.03, "Надень его и приступай к поискам!" } } }, t = { d = 8.2, v = "goblin-male", n = { x = 81 }, c = { x = { { 0.00, "Отлично; как раз то, что нужно для исследований." }, { 3.90, "Огромное спасибо за помощь." }, { 6.22, "Можно, я заберу свой шлем?" } } } } },
    [3181] = { d = 32.4, v = "narrator", n = { x = 338 }, c = { x = { { 0.00, "Гигантский рог испещрён многочисленными сколами и царапинами, кроме того, из него торчит непонятный металлический предмет." }, { 9.76, "Осмотрев рог более внимательно, вы понимаете, что металлический предмет есть не что иное, как обух секиры, сорванный с рукояти." }, { 19.88, "На нём виднеется гравировка:" }, { 22.14, "\"Принадлежит горному пехотинцу Щебеночке\"." }, { 25.56, "Когда вы пытаетесь вытащить обух секиры из рога, он рассыпается на кусочки." }, { 31.68, "Опаньки..." } } }, t = { d = 21.3, g = 1, v = "dwarf-female#33", n = { m = 227, f = 228 }, c = { m = { { 0.00, "Что это у тебя?" }, { 1.23, "Бессовестная подделка, вестимо!" }, { 3.62, "Я встречалась с Марголом один на один, и могу ответственно заявить тебе – рог у него раз в восемь больше, чем вот эта твоя закорючка!" }, { 13.72, "Небось, выдрал её из какого-нибудь несчастного грозорыла в Степях." }, { 18.70, "Нет, милый, ты не обманешь Щебёночку!" } }, f = { { 0.00, "Что это у тебя?" }, { 1.22, "Бессовестная подделка, вестимо!" }, { 3.58, "Я встречалась с Марголом один на один, и могу ответственно заявить тебе – рог у него раз в восемь больше, чем вот эта твоя закорючка!" }, { 13.57, "Небось, выдрала её из какого-нибудь несчастного грозорыла в Степях." }, { 18.57, "Нет, милая, ты не обманешь Щебёночку!" } } } } },
    [3182] = { d = 23.0, v = "dwarf-female#33", n = { x = 242 }, c = { x = { { 0.00, "Ты думаешь, я поверю этим россказням?" }, { 2.82, "Если бы это был настоящий рог, из него до сих пор торчал бы обух моей секиры." }, { 8.60, "Вот что, неси-ка свою подделку куратору Ториусу в Стальгорн." }, { 13.11, "Если он признает, что твои слова – правда, он даст тебе доказательство." }, { 18.42, "Принеси его мне, и я дам тебе ключ к Тлеющему ущелью." }, { 22.38, "Иди, иди!" } } }, t = { d = 14.7, g = 1, v = "dwarf-male", n = { x = 148 }, c = { m = { { 0.00, "Что это?" }, { 0.69, "Я не могу поверить!" }, { 2.22, "Вы понимаете, что это, герой?" }, { 4.52, "Это же рог Маргола Яростеня!" }, { 6.88, "Маргола, причины гибели множества археологов, оказавшихся в Тлеющем ущелье." }, { 12.72, "Можно мне оставить его себе?" } }, f = { { 0.00, "Что это?" }, { 0.69, "Я не могу поверить!" }, { 2.20, "Вы понимаете, что это, героиня?" }, { 4.61, "Это же рог Маргола Яростеня!" }, { 6.81, "Маргола, причины гибели множества археологов, оказавшихся в Тлеющем ущелье." }, { 12.60, "Можно мне оставить его себе?" } } } } },
    [3201] = { d = 29.3, v = "dwarf-male", n = { x = 308 }, c = { x = { { 0.00, "Не может быть, чтобы Щебеночка усомнилась в подлинности рога." }, { 4.67, "Между нами говоря, думаю, она просто ревнует." }, { 8.39, "Я знаю, она хотела убить чудовище сама." }, { 11.61, "Так вам, значит, нужно доказательство." }, { 14.56, "Разумеется, вы принесли музею столь ценный дар, что я почту за честь написать для вас свидетельство." }, { 22.06, "*Куратор Ториус начинает заполнять огромный документ*" }, { 26.06, "Ну вот, можете показать его Щебеночке." } } }, t = { d = 12.6, g = 1, v = "dwarf-female#33", n = { m = 121, f = 125 }, c = { m = { { 0.00, "Не понимаю, как мог такой слабак, как ты, одолеть Маргола, но я хозяйка своего слова." }, { 6.95, "Но если после этого с тобой случится что-то нехорошее, пеняй на себя!" } }, f = { { 0.00, "Не понимаю, как могла такая слабачка, как ты, одолеть Маргола, но я хозяйка своего слова." }, { 7.11, "Но если после этого с тобой случится что-то нехорошее, пеняй на себя!" } } } } },
    [3221] = { d = 15.4, v = "scourge-male", n = { x = 158 }, c = { x = { { 0.00, "Пока вы отсутствовали, помогая нашим стражам смерти, за вами приходил аптекарь Ренферрел." }, { 7.32, "Он не рассказывал мне подробностей, но хотел поговорить с вами о волчьих сердцах, что вы ему передали." } } }, t = { d = 12.0, v = "scourge-male#82", n = { x = 102 }, c = { x = { { 0.00, "О, хорошо, что вы пришли." }, { 2.40, "Касательно тех волчьих сердец, что вы мне ранее принесли – есть один момент, требующий вашего внимания." } } } } },
    [3261] = { d = 13.4, v = "orc-female", n = { x = 138 }, c = { x = { { 0.00, "Вот и закончились наши уроки." }, { 2.42, "Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес." }, { 10.95, "Он станет твоим новым учителем." } } }, t = { d = 8.4, g = 1, v = "tauren-male#67", n = { m = 63, f = 66 }, c = { m = { { 0.00, "Приветствую тебя, юноша." }, { 2.79, "Ты избрал путь охотника?" }, { 5.49, "Замечательно." }, { 6.98, "Начнём с азов." } }, f = { { 0.00, "Приветствую тебя, девушка." }, { 2.78, "Ты избрала путь охотника?" }, { 5.38, "Замечательно." }, { 6.77, "Начнём с азов." } } } } },
    [3281] = { d = 23.5, g = 1, v = "orc-male", n = { m = 230, f = 231 }, c = { m = { { 0.00, "Ящеров-то ты убил, но похищенное серебро необходимо вернуть!" }, { 5.07, "Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров." }, { 10.67, "Скорее всего они утащили похищенное серебро именно туда." }, { 15.58, "Отправляйся в логово мерзких тварей и поищи наше серебро." }, { 20.50, "Как найдёшь – сразу возвращайся ко мне." } }, f = { { 0.00, "Ящеров-то ты убила, но похищенное серебро необходимо вернуть!" }, { 4.97, "Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров." }, { 10.38, "Скорее всего они утащили похищенное серебро именно туда." }, { 15.13, "Отправляйся в логово мерзких тварей и поищи наше серебро." }, { 19.88, "Как найдёшь – сразу возвращайся ко мне." } } }, t = { d = 21.4, v = "orc-male", n = { x = 209 }, c = { x = { { 0.00, "Ага!" }, { 0.45, "Значит, ящеры всё же утащили его в своё логово." }, { 4.38, "Трудно понять, зачем этим тварям серебро." }, { 7.94, "Быть может, в байках об их уме есть зерно правды!" }, { 12.02, "Спасибо." }, { 12.76, "Прими награду за услуги и помни, что стражи перекрёстков получили свою месячную оплату лишь благодаря тебе." } } } } },
    [3301] = { d = 39.6, v = "tauren-male", n = { x = 382 }, c = { x = { { 0.00, "Одна из моих соплеменниц, Муура Рунический Тотем, отправилась в Серебряный бор на помощь нашим союзникам-нежити." }, { 9.65, "Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь." }, { 17.14, "Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу." }, { 24.01, "Возьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор." }, { 30.49, "Она остановилась в Гробнице." }, { 32.96, "При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место." } } }, t = { d = 18.4, v = "tauren-female", n = { x = 183 }, c = { x = { { 0.00, "Что это?" }, { 0.75, "Панцирь светится изнутри, словно в нём по-прежнему теплится жизнь." }, { 6.26, "Удивительно!" }, { 7.32, "Надо изучить его внимательнее." }, { 9.96, "Спасибо." }, { 10.71, "Быть может, в этом панцире сокрыта тайна исцеления бедной израненной земли Серебряного бора." } } } } },
    [3321] = { d = 23.9, g = 1, v = "nightelf-male#55", n = { m = 244, f = 246 }, c = { m = { { 0.00, "Ты много сделал для Ордена." }, { 2.18, "Обычный искатель приключений не выдержал бы такой нагрузки." }, { 6.83, "Ни я, ни Гальван не сомневаемся, что ты стал одним из нас." }, { 11.20, "Поэтому мне кажется, что ты заслуживаешь награды." }, { 15.00, "Сущий пустяк, побрякушку." }, { 17.04, "Может быть, ты знаешь о её свойствах." }, { 19.93, "Должно быть, именно из-за них ты и пришёл к нам." } }, f = { { 0.00, "Ты много сделала для Ордена." }, { 2.27, "Обычный искатель приключений не выдержал бы такой нагрузки." }, { 6.96, "Ни я, ни Гальван не сомневаемся, что ты стала одной из нас." }, { 11.50, "Поэтому мне кажется, что ты заслуживаешь награды." }, { 15.34, "Сущий пустяк, побрякушку." }, { 17.40, "Может быть, ты знаешь о её свойствах." }, { 20.31, "Должно быть, именно из-за них ты и пришла к нам." } } }, t = { d = 4.0, v = "nightelf-male#55", n = { x = 37 }, c = { x = { { 0.00, "Войди же в круг равных, кузнец Ордена Мифрила." } } } } },
    [3341] = { d = 36.4, v = "scourge-male#82", n = { x = 339 }, c = { x = { { 0.00, "В Степях есть уголок, заросший кошмарными колючками." }, { 4.74, "Он называется Курганы Иглошкурых." }, { 7.77, "Хотя с первого взгляда это место не показалось нам опасным, по последним сведениям всё куда серьёзнее…" }, { 17.01, "Живущие в холмах свинобразы поддались злому влиянию Плети." }, { 22.41, "Теперь их действиями руководит лич по имени Амненнар Хладовей." }, { 28.06, "У Амненнара прямая телепатическая связь с Нер'зулом; мы должны прервать её." }, { 34.76, "Да сгинет Хладовей!" } } }, t = { d = 9.4, v = "scourge-male#82", n = { x = 76 }, c = { x = { { 0.00, "Никто не смеет пойти против воли лича." }, { 4.08, "Однако, такая верность может привести лишь к погибели." } } } } },
    [3361] = { d = 43.3, v = "gnome-male", n = { x = 483 }, c = { x = { { 0.00, "Мы изгнали троггов из Гномрегана и уж было собрались праздновать победу, но тут всё пошло наперекосяк!" }, { 7.21, "Только представь: радиация кругом, а гномы – те, кто ещё жив – разбрелись по Дун Морогу..." }, { 13.51, "Я так торопился, что все свои вещи бросил, да и все инструменты в придачу." }, { 18.72, "Вот тролли – те не растерялись: им что радиация, что грибной дождик..." }, { 23.61, "Прибрали всё к рукам: и сундук, и ларец, и даже ведро с винтиками не постеснялись прихватить!" }, { 30.24, "Всё, всё уволокли к себе в лагерь, куда-то к юго-западу от Старой Наковальни..." }, { 35.90, "Путешественник из меня никудышный, так я вот тут подумал: может, ты у них заберёшь мои вещи и вернёшь их мне?" } } }, t = { d = 12.9, v = "gnome-male", n = { x = 121 }, c = { x = { { 0.00, "Ага!" }, { 0.44, "Есть!" }, { 0.88, "Есть!" }, { 1.32, "Тебе удалось найти мои вещи!" }, { 3.81, "Я спасён!.." }, { 4.69, "Вот, держи: это, конечно, сущие пустяки, но должен же я тебя хоть чем-то вознаградить за все испытания." } } } } },
    [3362] = { d = 28.0, g = 1, v = "goblin-male", n = { m = 297, f = 298 }, c = { m = { { 0.00, "Ты когда-нибудь был в долине Кактусов?" }, { 2.81, "Это опасное место." }, { 4.29, "Там такие жуткие твари, я им ни на минуту не верю!" }, { 8.04, "Бугристые шипошкуры и корнеплёты, кажется так они зовутся…" }, { 12.33, "Так или иначе, я хочу попасть в эту долину, но пока там столько шипошкуров, ноги моей там не будет." }, { 19.84, "Вот зачем ты мне нужен – если выкосить часть этих тварей, я могу и решиться на поход." }, { 26.20, "Что скажешь?" }, { 27.14, "Поможешь мне?" } }, f = { { 0.00, "Ты когда-нибудь была в долине Кактусов?" }, { 2.88, "Это опасное место." }, { 4.31, "Там такие жуткие твари, я им ни на минуту не верю!" }, { 7.97, "Бугристые шипошкуры и корнеплёты, кажется так они зовутся…" }, { 12.16, "Так или иначе, я хочу попасть в эту долину, но пока там столько шипошкуров, ноги моей там не будет." }, { 19.48, "Вот зачем ты мне нужна – если выкосить часть этих тварей, я могу и решиться на поход." }, { 25.69, "Что скажешь?" }, { 26.60, "Поможешь мне?" } } }, t = { d = 9.7, g = 1, v = "goblin-male", n = { m = 84, f = 85 }, c = { m = { { 0.00, "Они такие огромные?" }, { 1.92, "Нет, план меняется…" }, { 3.67, "Но ты-то выполнил свою часть сделки, поэтому вот, держи обещанное." } }, f = { { 0.00, "Они такие огромные?" }, { 1.82, "Нет, план меняется…" }, { 3.49, "Но ты-то выполнила свою часть сделки, поэтому вот, держи обещанное." } } } } },
    [3363] = { t = { d = 13.9, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений." }, { 7.18, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [3364] = { d = 41.4, v = "dwarf-male", n = { x = 466 }, c = { x = { { 0.00, "Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину." }, { 11.41, "Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то!" }, { 16.98, "Ты на ногу полегче моего будешь, как я погляжу; вот я и подумал... эта кружка останется горячей ещё минут пять, а Дарнан вовсе не охлаждённую бражку заказывал, – не пиво, чай! – так что отправляйся-ка ты в путь." }, { 31.65, "Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда." }, { 36.97, "Благодарю заранее... и вот ещё что: не забудь вернуть мою кружку!" } } }, t = { d = 9.4, v = "dwarf-male#100", n = { x = 87 }, c = { x = { { 0.00, "Отлично!" }, { 0.73, "Это именно то, что нужно!" }, { 2.85, "Ты погоди пока, эту штуку пить надо, пока не остыла, иначе вкуса того не будет." } } } } },
    [3365] = { d = 17.5, v = "dwarf-male#100", n = { x = 174 }, c = { x = { { 0.00, "Ох, хорошо-то как!" }, { 1.44, "Все эти прохладительные напитки – полная ерунда: в морозный денёк нет ничего лучше глотка горячей бражки!" }, { 9.88, "Даже на душе теплее становится!" }, { 12.48, "Вот, держи; сделай доброе дело, отнеси эту кружку Нори, ладно?" } } }, t = { d = 21.3, v = "dwarf-male", n = { x = 225 }, c = { x = { { 0.00, "Спасибо!" }, { 0.67, "Ты удивишься, если я расскажу тебе, сколько народу забывает сделать самое простое – вернуть назад кружку." }, { 8.64, "А кружки-то, между прочим, на деревьях не растут!" }, { 12.32, "Ну, по крайней мере, в наших краях." }, { 15.00, "Тут у меня есть кое-что для тебя." }, { 17.48, "Я так думаю, усердие нужно вознаграждать, верно ведь?" } } } } },
    [3366] = { d = 23.3, v = "narrator", n = { x = 255 }, c = { x = { { 0.00, "Блестящий осколок ярко-зелёный, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма." }, { 8.22, "Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаёте какое-то беспокойство." }, { 16.03, "Пожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке." } } } },
    [3367] = { d = 12.4, g = 1, v = "dwarf-male", n = { x = 107 }, c = { m = { { 0.00, "Я тяжело ранен, герой." }, { 3.02, "Ужасно кружится голова..." }, { 5.06, "Думаю, у меня внутреннее кровотечение..." }, { 8.23, "Мне нужно добраться обратно в Стальгорн." }, { 11.40, "Помоги мне." } }, f = { { 0.00, "Я тяжело ранен, героиня." }, { 3.19, "Ужасно кружится голова..." }, { 5.25, "Думаю, у меня внутреннее кровотечение..." }, { 8.44, "Мне нужно добраться обратно в Стальгорн." }, { 11.63, "Помоги мне." } } }, t = { d = 3.0, v = "narrator", n = { x = 29 }, c = { x = { { 0.00, "Письмо выронил Дориус, когда падал." } } } } },
    [3368] = { d = 37.7, v = "narrator", n = { x = 360 }, c = { x = { { 0.00, "Брат!" }, { 0.46, "Если ты читаешь эти строки, меня уже нет в живых." }, { 4.83, "Не знаю, кто доставил тебе письмо, но непременно поблагодари и вознагради его." }, { 11.49, "Теперь о камнях: они существуют и сейчас находятся у клана Чёрного Железа." }, { 17.85, "С помощью этих камней их главарь, Латорик Чёрный, удерживает моих соратников по экспедиции в плену." }, { 26.57, "Лишённые рассудка, они день и ночь трудятся над созданием монстра, именуемого Обсидионом." }, { 34.00, "Спаси их, брат." }, { 35.30, "Это моя последняя воля." }, { 37.45, "Дориус." } } }, t = { d = 7.1, v = "dwarf-male", n = { x = 59 }, c = { x = { { 0.00, "*Ториус утирает слёзы.*" }, { 2.16, "Клянусь Светом, его воля будет исполнена." }, { 6.40, "Клянусь!" } } } } },
    [3369] = { d = 27.6, v = "tauren-female#71", n = { x = 280 }, c = { x = { { 0.00, "Этот осколок сам по себе большая загадка; это чистая эссенция Изумрудного Сна." }, { 6.29, "Однако, это осколок не сна, а скорее кошмара." }, { 9.94, "Не хочу тревожить тебя, но лучше будет отдать его кому-то из старших друидов, как только сможешь." }, { 17.81, "Хамуул Рунический Тотем с Вершины Старейшин, вот кого тебе надо найти." }, { 23.53, "Отправляйся на Громовой Утёс, точнее сказать не могу." } } }, t = { d = 30.2, g = 1, v = "creature/hamuul", n = { m = 253, f = 255 }, c = { m = { { 0.00, "Тебя послала Фалла?" }, { 2.05, "Давай-ка, взглянем на этот осколок…" }, { 5.52, "*Хамуул вглядывается в осколок.*" }, { 8.40, "Ох..." }, { 8.90, "Боги…" }, { 9.49, "Спасибо, что принёс это мне." }, { 12.08, "О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться." }, { 21.88, "Запомни, в Изумрудном сне всё не то, чем кажется..." }, { 26.48, "Возможно в будущем мы встретимся вновь." } }, f = { { 0.00, "Тебя послала Фалла?" }, { 2.05, "Давай-ка, взглянем на этот осколок…" }, { 5.52, "*Хамуул вглядывается в осколок.*" }, { 8.40, "Ох..." }, { 8.90, "Боги…" }, { 9.49, "Спасибо, что принесла это мне." }, { 12.35, "О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться." }, { 22.17, "Запомни, в Изумрудном сне всё не то, чем кажется..." }, { 26.79, "Возможно в будущем мы встретимся вновь." } } } } },
    [3370] = { d = 26.7, v = "tauren-female#71", n = { x = 271 }, c = { x = { { 0.00, "Этот осколок сам по себе большая загадка; это чистая эссенция Изумрудного Сна." }, { 6.26, "Однако, это осколок не сна, а скорее кошмара." }, { 9.88, "Не хочу тревожить тебя, но лучше будет отдать его кому-то из старших друидов, как только сможешь." }, { 17.70, "Матренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти." }, { 23.17, "Отправляйся в Дарнасс, точнее сказать не могу." } } }, t = { d = 26.5, g = 1, v = "nightelf-male#59", n = { m = 256, f = 258 }, c = { m = { { 0.00, "Тебя послала Фалла?" }, { 1.75, "Давай-ка, взглянем на этот осколок…" }, { 4.72, "*Матренгил вглядывается в осколок.*" }, { 7.60, "Ох..." }, { 8.04, "Боги…" }, { 8.54, "Спасибо, что принёс это мне." }, { 10.79, "О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться." }, { 19.28, "Запомни, в Изумрудном сне всё не то, чем кажется..." }, { 23.27, "Возможно в будущем мы встретимся вновь." } }, f = { { 0.00, "Тебя послала Фалла?" }, { 1.75, "Давай-ка, взглянем на этот осколок…" }, { 4.72, "*Матренгил вглядывается в осколок.*" }, { 7.44, "Ох..." }, { 7.88, "Боги…" }, { 8.39, "Спасибо, что принесла это мне." }, { 10.88, "О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться." }, { 19.45, "Запомни, в Изумрудном сне всё не то, чем кажется..." }, { 23.48, "Возможно в будущем мы встретимся вновь." } } } } },
    [3371] = { d = 23.7, v = "dwarf-male", n = { x = 245 }, c = { x = { { 0.00, "Теперь в груди моей зияет чёрная дыра – там, где было когда-то сердце..." }, { 5.59, "Я никогда не смогу смириться с гибелью Дориуса." }, { 9.26, "Я сделаю всё, чтобы его последняя воля была исполнена – тех, на ком его кровь, должна настигнуть суровая кара." }, { 17.75, "Возвращайся в Тлеющее ущелье и исполни волю Дориуса – освободи его соратников." } } }, t = { d = 2.6, v = "dwarf-male", n = { x = 25 }, c = { x = { { 0.00, "Оставь меня, спасай остальных!" } } } } },
    [3372] = { d = 26.0, g = 1, v = "dwarf-male", n = { x = 253 }, c = { m = { { 0.00, "Отпусти их, герой." }, { 1.48, "Даже когда их тела совсем обессилеют, власть Сунтары заставляет их достичь цели любой ценой." }, { 8.83, "Всё дело в алтаре Сунтары." }, { 10.94, "Отправляйся на северо-запад, там, в холмах над пещерой..." }, { 15.39, "Сумеречный Молот хранит реликвию." }, { 18.07, "Добудь её и возложи на алтарь Сунтары." }, { 21.04, "*С этими словами умирающий археолог испускает дух*" } }, f = { { 0.00, "Отпусти их, героиня." }, { 1.65, "Даже когда их тела совсем обессилеют, власть Сунтары заставляет их достичь цели любой ценой." }, { 9.11, "Всё дело в алтаре Сунтары." }, { 11.26, "Отправляйся на северо-запад, там, в холмах над пещерой..." }, { 15.78, "Сумеречный Молот хранит реликвию." }, { 18.51, "Добудь её и возложи на алтарь Сунтары." }, { 21.52, "*С этими словами умирающий археолог испускает дух*" } } }, t = { d = 4.4, v = "narrator", n = { x = 47 }, c = { x = { { 0.00, "Вы возлагаете таинственный артефакт на алтарь Сунтары." } } } } },
    [3373] = { d = 40.2, g = 1, v = "narrator", n = { m = 386, f = 386 }, c = { m = { { 0.00, "Вы касаетесь камня и слышите голос, звучащий в вашем сознании." }, { 5.38, "\"Услышь мою мольбу, о смертный." }, { 8.14, "Имя мне Эраникус из народа зелёных драконов." }, { 11.90, "Мои попытки положить конец богохульным деяниям троллей закончились неудачей." }, { 18.51, "Я вдохнул частицу своей души в этот кристалл." }, { 22.50, "Однако я чувствую, что моя связь с Изумрудным Сном теряется, и меня поглощает хаос." }, { 29.57, "Пожалуйста, помести этот кристалл в купель сущности в моём логове – пусть магия очистит моё сознание от скверны и спасёт меня!\"" } }, f = { { 0.00, "Вы касаетесь камня и слышите голос, звучащий в вашем сознании." }, { 5.33, "\"Услышь мою мольбу, о смертная." }, { 8.08, "Имя мне Эраникус из народа зелёных драконов." }, { 11.81, "Мои попытки положить конец богохульным деяниям троллей закончились неудачей." }, { 18.36, "Я вдохнул частицу своей души в этот кристалл." }, { 22.32, "Однако я чувствую, что моя связь с Изумрудным Сном теряется, и меня поглощает хаос." }, { 29.33, "Пожалуйста, помести этот кристалл в купель сущности в моём логове – пусть магия очистит моё сознание от скверны и спасёт меня!\"" } } }, t = { d = 40.4, g = 1, v = "creature/dragon", n = { m = 316, f = 316 }, c = { m = { { 0.00, "*Вы помещаете камень в купель сущности.*" }, { 3.36, "\"Благодарю тебя, смертный, теперь я..." }, { 7.19, "О нет!" }, { 7.82, "Не может быть!" }, { 9.24, "Скверна проклятого бога проникла даже в эту купель!" }, { 14.50, "Умоляю!" }, { 15.30, "Я чувствую, как сознание покидает меня!" }, { 19.22, "БОЛЬНО!" }, { 20.02, "Я чувствую, как мою душу поглощает вечный кошмар!\"" }, { 25.10, "\"Умоляю тебя, смертный, найди одного из зелёных драконов, чтобы он смог прекратить мои мучения!" }, { 34.55, "Помоги мне!" }, { 35.71, "Я обречён на вечную агонию..." }, { 38.56, "Пощади!\"" } }, f = { { 0.00, "*Вы помещаете камень в купель сущности.*" }, { 3.28, "\"Благодарю те