    [3374] = { d = 38.6, v = "narrator", n = { x = 389 }, c = { x = { { 0.00, "Вы приводите в действие Камень клятвы и с его помощью Итар мысленно заговаривает с вами." }, { 7.30, "\"Приняв силу, заключённую в камне Клятвы, ты соглашаешься помочь мне и драконьему выводку Изеры освободить истерзанную душу Эраникуса." }, { 18.22, "Первая из многих жертв, на которую придётся пойти и тебе, и мне – это передать мне камень, в котором заключено то, что осталось от свободной воли Эраникуса." }, { 30.83, "Сделай это, и дальше мы будем действовать вместе, чтобы освободить достойную многих жертв душу.\"" } } }, t = { d = 11.7, g = 1, v = "bloodelf-male", n = { m = 119, f = 120 }, c = { m = { { 0.00, "Выбор сделан, начало положено." }, { 2.51, "Пока, на мой взгляд, ты выбирал верный путь." }, { 5.95, "С нынешнего момента от твоих деяний будет зависеть, будет ли так и впредь." } }, f = { { 0.00, "Выбор сделан, начало положено." }, { 2.41, "Пока, на мой взгляд, ты выбирала верный путь." }, { 5.78, "С нынешнего момента от твоих деяний будет зависеть, будет ли так и впредь." } } } } },
    [3375] = { d = 28.0, g = 1, v = "gnome-male", n = { m = 291, f = 292 }, c = { m = { { 0.00, "Хм... тебе нужен ещё один фиал виденья?" }, { 2.87, "Шутишь?" }, { 3.45, "А куда ты дел прежний?!" }, { 5.11, "У нас и так забот полон рот, герой." }, { 7.59, "Эти фиалы на деревьях не растут!" }, { 9.95, "Хорошо бы, чтобы росли, я тогда пошёл бы да сорвал, потому как другого-то у меня нет!" }, { 15.95, "А чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара." }, { 23.16, "И не спрашивай зачем, просто принеси, я и тебе сделаю новый." } }, f = { { 0.00, "Хм... тебе нужен ещё один фиал виденья?" }, { 2.91, "Шутишь?" }, { 3.49, "А куда ты дела прежний?!" }, { 5.31, "У нас и так забот полон рот, героиня." }, { 7.96, "Эти фиалы на деревьях не растут!" }, { 10.35, "Хорошо бы, чтобы росли, я тогда пошёл бы да сорвал, потому как другого-то у меня нет!" }, { 16.43, "А чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара." }, { 23.75, "И не спрашивай зачем, просто принеси, я и тебе сделаю новый." } } }, t = { d = 31.3, g = 1, v = "gnome-male", n = { m = 352, f = 354 }, c = { m = { { 0.00, "Могучий искатель приключений всё принёс." }, { 2.75, "Слава мне!" }, { 3.50, "Кстати, я соврал – у меня был запасной фиал." }, { 6.62, "Вот." }, { 6.93, "А чего ты ожидал?!" }, { 8.24, "\"Нате-пожалуйста вам другой!" }, { 10.24, "Мне, дураку, делать больше нечего, кроме как задарма раздавать магические устройства связи искателям приключений!\" Но ты не беспокойся, всё, что ты мне дал, пойдёт на изготовление для тебя очередного фиала, когда ты и этот посеешь." }, { 25.98, "Пожалуйста, пусть я ошибусь в тебе – не потеряй ещё и этот, ладно?" } }, f = { { 0.00, "Могучий искатель приключений всё принёс." }, { 2.81, "Слава мне!" }, { 3.58, "Кстати, я соврал – у меня был запасной фиал." }, { 6.77, "Вот." }, { 7.09, "А чего ты ожидала?!" }, { 8.49, "\"Нате-пожалуйста вам другой!" }, { 10.54, "Мне, дураку, делать боль