    [3376] = { d = 34.5, g = 1, v = "tauren-female", n = { m = 337, f = 339 }, c = { m = { { 0.00, "Путник – я слыхала о тебе." }, { 2.17, "Возможно, именно тебе удастся то, что не удалось другим." }, { 6.73, "Мы, таурены, сделали это место своим домом, но это далось нам дорогой ценой." }, { 13.02, "Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами." }, { 24.16, "Я хочу, чтобы ты принёс мне голову их вождя!" }, { 27.70, "Ты найдёшь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда." } }, f = { { 0.00, "Путница – я слыхала о тебе." }, { 2.27, "Возможно, именно тебе удастся то, что не удалось другим." }, { 6.87, "Мы, таурены, сделали это место своим домом, но это далось нам дорогой ценой." }, { 13.22, "Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами." }, { 24.48, "Я хочу, чтобы ты принесла мне голову их вождя!" }, { 28.28, "Ты найдёшь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда." } } }, t = { d = 14.7, g = 1, v = "tauren-female", n = { m = 133, f = 134 }, c = { m = { { 0.00, "Само правосудие сегодня направляло твою руку." }, { 4.07, "Да будет твоё деяние предостережением для всех, кто осмелится угрожать нашему дому!" }, { 11.19, "Ты заслужил эту награду, юный герой." } }, f = { { 0.00, "Само правосудие сегодня направляло твою руку." }, { 4.12, "Да будет твоё деяние предостережением для всех, кто осмелится угрожать нашему дому!" }, { 11.32, "Ты заслужила эту награду, юная героиня." } } } } },
    [3377] = { d = 4.3, g = 1, v = "nightelf-male#54", n = { m = 38, f = 38 }, c = { m = { { 0.00, "Мне нужна твоя помощь, смертный." }, { 3.07, "Выслушай меня!" } }, f = { { 0.00, "Мне нужна твоя помощь, смертная." }, { 3.07, "Выслушай меня!" } } }, t = { d = 7.4, v = "nightelf-male#54", n = { x = 59 }, c = { x = { { 0.00, "Я смирился с тем, что отныне моя судьба – эта клетка, но молитву нужно найти!" } } } } },
    [3378] = { d = 33.5, g = 1, v = "nightelf-male#54", n = { m = 335, f = 335 }, c = { m = { { 0.00, "Ты поможешь мне, смертный?" }, { 2.13, "Ты отыщешь молитву Элуне?" }, { 4.26, "Как я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников." }, { 14.31, "Если ты сможешь отыскать её, отнеси табличку Астарии Ловцу Звёзд в Дарнасс." }, { 20.47, "Пусть я пришёл к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана." }, { 30.23, "А на прощение своих грехов я не надеюсь..." } }, f = { { 0.00, "Ты поможешь мне, смертная?" }, { 2.07, "Ты отыщешь молитву Элуне?" }, { 4.13, "Как я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников." }, { 13.90, "Если ты сможешь отыскать её, отнеси табличку Астарии Ловцу Звёзд в Дарнасс." }, { 19.88, "Пусть я пришёл к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана." }, { 29.36, "А на прощение своих грехов я не надеюсь..." } } }, t = { d = 7.4, g = 1, v = "nightelf-female#51", n = { m = 78, f = 79 }, c = { m = { { 0.00, "Элуна улыбается тебе." }, { 1.79, "Ты возвратил к ней потерянную душу." }, { 4.58, "Прими это в знак нашей благодарности." } }, f = { { 0.00, "Элуна улыбается тебе." }, { 1.77, "Ты возвратила к ней потерянную душу." }, { 4.61, "Прими это в знак нашей благодарности." } } } } },
    [3379] = { d = 25.8, v = "human-female#45", n = { x = 303 }, c = { x = { { 0.00, "Пауки, которые водятся в Тлеющем ущелье, производят бесценный тенешёлк." }, { 5.08, "Как ты знаешь, тенешёлк необходим для нашего ремесла." }, { 8.81, "Не так давно в этих землях появилась шайка браконьеров, бессовестно убивающих пауков в погоне за сиюминутной прибылью." }, { 17.24, "Твоя задача проста: найти их и прикончить." }, { 20.32, "Начни поиски с северных пределов." }, { 22.77, "Если потребуется помощь, обращайся к Пожару." } } }, t = { d = 7.4, v = "human-female#45", n = { x = 82 }, c = { x = { { 0.00, "Отличная работа." }, { 1.26, "Прими это в награду – уверена, подобной работы из тенеткани тебе ещё не встречалось!" } } } } },
    [3380] = { d = 39.4, v = "troll-male#77", n = { x = 417 }, c = { x = { { 0.00, "Этот мир полон беспокойных духов." }, { 2.68, "Среди них есть такие, которые оказались скованы в местах, в которых таится древнее зло, и были поражены скверной." }, { 11.55, "Слыхал я о храме, сокрытом в глубинах болот – он был погружён туда силами, величие которых недоступно сознанию простого смертного." }, { 21.69, "Если хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик." }, { 28.66, "Он облазал многие развалины и останки древних поселений." }, { 33.10, "Слыхал я, что недавно он отправился изучать развалины строений троллей в Танарисе." } } }, t = { d = 10.5, v = "goblin-male", n = { x = 108 }, c = { x = { { 0.00, "О да, я видел затонувший храм собственными глазами." }, { 4.14, "Хочешь узнать о нём побольше?" }, { 6.57, "Уж я сразу узнаю настоящего искателя приключений!" } } } } },
    [3381] = { d = 31.8, g = 1, v = "bloodelf-male", n = { m = 338, f = 340 }, c = { m = { { 0.00, "О, юный герой почтил визитом Саната." }, { 2.74, "О, это прекрасный день!" }, { 4.43, "Я так польщён!" }, { 5.41, "Благодарю тебя..." }, { 6.71, "Надеюсь, ты не столь самонадеян, чтобы принять мой сарказм за чистую монету?" }, { 12.18, "Скажу прямо: ты мне не нравишься." }, { 14.59, "Однако, речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин." }, { 21.62, "Принеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину." }, { 27.42, "Он принимает только тех, кто доказал, что на что-то годен." } }, f = { { 0.00, "О, юная героиня почтила визитом Саната." }, { 2.94, "О, это прекрасный день!" }, { 4.64, "Я так польщён!" }, { 5.63, "Благодарю тебя..." }, { 6.93, "Надеюсь, ты не столь самонадеяна, чтобы принять мой сарказм за чистую монету?" }, { 12.49, "Скажу прямо: ты мне не нравишься." }, { 14.91, "Однако, речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин." }, { 21.98, "Принеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину." }, { 27.80, "Он принимает только тех, кто доказал, что на что-то годен." } } } },
    [3382] = { d = 31.1, g = 1, v = "human-female#47", n = { m = 356, f = 358 }, c = { m = { { 0.00, "Мы плыли вдоль берега, в поисках места, где бросить якорь." }, { 3.93, "Солнце зашло не более часа назад, и тут они на нас напали." }, { 7.92, "Проклятые наги!" }, { 9.00, "Не знаю, что им было нужно, но они явно этого не нашли." }, { 12.81, "Почему я в этом уверена?" }, { 14.50, "Потому что они вернулись!" }, { 16.26, "Я оставила пару своих людей охранять долину, чтобы они предупредили нас в случае атаки." }, { 22.24, "Мне жаль, что ты оказался втянутым в эту заварушку, но увы, ничего уже нельзя сделать." }, { 28.04, "Ты готов биться не на жизнь, а на смерть?" } }, f = { { 0.00, "Мы плыли вдоль берега, в поисках места, где бросить якорь." }, { 3.98, "Солнце зашло не более часа назад, и тут они на нас напали." }, { 8.03, "Проклятые наги!" }, { 9.13, "Не знаю, что им было нужно, но они явно этого не нашли." }, { 12.99, "Почему я в этом уверена?" }, { 14.71, "Потому что они вернулись!" }, { 16.49, "Я оставила пару своих людей охранять долину, чтобы они предупредили нас в случае атаки." }, { 22.56, "Мне жаль, что ты оказалась втянутой в эту заварушку, но увы, ничего уже нельзя сделать." }, { 28.50, "Ты готова биться не на жизнь, а на смерть?" } } }, t = { d = 23.3, v = "human-female#47", n = { x = 266 }, c = { x = { { 0.00, "Победа!" }, { 0.57, "Спасибо тебе!" }, { 1.57, "Уф... это был самый жаркий бой за всю мою жизнь." }, { 4.91, "Не знаю как тебя благодарить!" }, { 6.99, "Как жаль, что так много моих людей погибло в этой схватке." }, { 11.08, "Пожалуйста, поговори с моими пассажирами." }, { 13.98, "Многие прибыли сюда по делу и наверняка кому-то из них понадобится помощь." }, { 19.20, "Возможно, тебе будет это интересно." }, { 21.79, "Ещё раз благодарю тебя!" } } } } },
    [3385] = { d = 34.2, v = "human-female#45", n = { x = 391 }, c = { x = { { 0.00, "Они называют себя Чёрным рынком – шайка головорезов, которые готовы купить, продать и украсть что угодно, если цена будет подходящей." }, { 9.46, "И что ещё хуже, они устроили себе логово в Тлеющем ущелье." }, { 13.62, "Искусный торговец Ковиц – их главарь." }, { 16.27, "У него есть связи с местными дворфами клана Чёрного Железа." }, { 20.44, "Мы должны нанести по ним мощный удар и недвусмысленно дать понять, что здесь им не рады." }, { 26.49, "Убей торговца Ковица и его прихвостня Лязгуна." }, { 30.41, "Принеси мне сумку торговца." }, { 32.37, "Отправляйся в Котёл немедля!" } } }, t = { d = 16.4, g = 1, v = "human-female#45", n = { m = 195, f = 197 }, c = { m = { { 0.00, "Ты нанёс решающий удар по Чёрному рынку." }, { 2.64, "Теперь эти бандиты дважды подумают, прежде чем отправлять сюда кого-то из своих." }, { 8.11, "Я осмотрела сумку – в ней нет ничего полезного." }, { 11.23, "Если тебе приглянется что-то из его барахла, можешь смело оставить себе." } }, f = { { 0.00, "Ты нанесла решающий удар по Чёрному рынку." }, { 2.85, "Теперь эти бандиты дважды подумают, прежде чем отправлять сюда кого-то из своих." }, { 8.36, "Я осмотрела сумку – в ней нет ничего полезного." }, { 11.51, "Если тебе приглянется что-то из его барахла, можешь смело оставить себе." } } } } },
    [3402] = { d = 9.9, g = 1, v = "human-female#45", n = { m = 107, f = 109 }, c = { m = { { 0.00, "Мне нужно, чтобы ты лично донёс весть о кончине Ковица Визглику в Прибамбасск." }, { 5.83, "Он будет так рад, что непременно щедро наградит тебя." } }, f = { { 0.00, "Мне нужно, чтобы ты лично донесла весть о кончине Ковица Визглику в Прибамбасск." }, { 6.05, "Он будет так рад, что непременно щедро наградит тебя." } } }, t = { d = 18.5, v = "goblin-male#110", n = { x = 190 }, c = { x = { { 0.00, "Ковис убит?" }, { 1.02, "О, счастье!" }, { 1.96, "Столько лет этот прохвост творил что хотел, обтяпывал незаконные сделки, устанавливал бессовестно низкие цены, разоряя нас, честных тружеников!" }, { 13.49, "Ты заслуживаешь щедрой награды за этот подвиг!" }, { 17.26, "И ты её получишь!" } } } } },
    [3421] = { t = { d = 10.1, v = "human-male", n = { x = 115 }, c = { x = { { 0.00, "Сейчас я верну тебя в лагерь Саната." }, { 2.62, "Не обращай внимания на его дурные манеры – он груб со всеми, кроме господина." }, { 7.98, "Может, однажды он получит урок." } } } } },
    [3441] = { d = 2.2, g = 1, v = "human-male", n = { m = 20, f = 21 }, c = { m = { { 0.00, "Выслушай меня, странник." } }, f = { { 0.00, "Выслушай меня, странница." } } }, t = { d = 3.5, g = 1, v = "human-male", n = { m = 29, f = 30 }, c = { m = { { 0.00, "Тебе всё ясно, герой?" }, { 1.71, "Ты готов действовать?" } }, f = { { 0.00, "Тебе всё ясно, героиня?" }, { 1.91, "Ты готова действовать?" } } } } },
    [3442] = { d = 30.4, g = 1, v = "human-male", n = { m = 353, f = 354 }, c = { m = { { 0.00, "Ты принял правильное решение." }, { 2.12, "Надо нанести удар по самому уязвимому месту – четырём сторожевым башням." }, { 7.32, "Тебе потребуется особый факел, чтобы поджечь их." }, { 10.84, "Над его изготовлением придётся потрудиться, кроме того, нужно добыть необходимые ингредиенты." }, { 17.45, "Принеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чьё пламя будет неугасимым." }, { 26.37, "Чтобы достать эти ингредиенты, ищи големов и элементалей." } }, f = { { 0.00, "Ты приняла правильное решение." }, { 2.16, "Надо нанести удар по самому уязвимому месту – четырём сторожевым башням." }, { 7.31, "Тебе потребуется особый факел, чтобы поджечь их." }, { 10.80, "Над его изготовлением придётся потрудиться, кроме того, нужно добыть необходимые ингредиенты." }, { 17.34, "Принеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чьё пламя будет неугасимым." }, { 26.17, "Чтобы достать эти ингредиенты, ищи големов и элементалей." } } }, t = { d = 2.6, v = "human-male", n = { x = 22 }, c = { x = { { 0.00, "Прекрасно." }, { 1.06, "Мы почти готовы." } } } } },
    [3443] = { d = 25.8, v = "human-male", n = { x = 315 }, c = { x = { { 0.00, "Чтобы удержать неугасимое пламя факела, нам необходимо создать особое древко и наложить защитные чары." }, { 7.21, "Начнём с древка." }, { 8.34, "В Котловане надсмотрщики и работорговцы из клана Чёрного Железа используют оружие из зачарованного тория – особенно прочного сплава." }, { 17.42, "Если ты принесёшь мне восемь окованных торием кинжалов, я смогу выплавить торий и использовать его для укрепления древка." } } }, t = { d = 19.5, g = 1, v = "human-male", n = { m = 218, f = 219 }, c = { m = { { 0.00, "Отличная работа, я просто поражён!" }, { 2.54, "Ты не задумывался о смене профессии?" }, { 5.22, "Чтобы стать, скажем, детективом?" }, { 7.63, "Ну или старьёвщиком?" }, { 9.10, "Или примкнуть к этим глупеньким гномам, ползающим по побережьям с металлоискателями в поисках сокровищ?" }, { 16.72, "Это ведь наверняка твоё призвание!" } }, f = { { 0.00, "Отличная работа, я просто поражён!" }, { 2.59, "Ты не задумывалась о смене профессии?" }, { 5.38, "Чтобы стать, скажем, детективом?" }, { 7.83, "Ну или старьёвщиком?" }, { 9.32, "Или примкнуть к этим глупеньким гномам, ползающим по побережьям с металлоискателями в поисках сокровищ?" }, { 17.08, "Это ведь наверняка твоё призвание!" } } } } },
    [3444] = { d = 33.4, v = "goblin-male", n = { x = 384 }, c = { x = { { 0.00, "Мне приходилось бывать в преддвериях затонувшего храма." }, { 3.88, "Зло, таящееся в этом жутком месте, окутывает всякого, кто входит туда." }, { 8.90, "Я едва смог выбраться обратно, увязая в липкой грязи, покрывающей пол." }, { 13.86, "Помню, есть там огромный круглый зал со множеством высеченных из камня змей." }, { 19.14, "Не так давно мне попал в руки круглый камень, на котором была высечена подобная змея." }, { 25.24, "Я велел послать его в мою мастерскую в Кабестане." }, { 28.80, "Забери его оттуда, и, возможно, я смогу ответить на твои вопросы." } } }, t = { d = 6.8, v = "goblin-male", n = { x = 59 }, c = { x = { { 0.00, "Да, это тот самый камень." }, { 2.35, "Затонувший храм так и стоит у меня перед глазами..." } } } } },
    [3445] = { d = 29.3, v = "nightelf-female#51", n = { x = 337 }, c = { x = { { 0.00, "Я слышала о месте, что лежит глубоко под землёй, – его низвергли туда силы, могущественнее которых я никогда не видела." }, { 8.33, "Если хочешь больше узнать об этом месте, о Затонувшем храме, отыщи гоблина по имени Марвон Клепальщик." }, { 15.66, "Как и мы с Троясом, он изучил немало древних уголков мира." }, { 19.76, "Говорят, он покинул свой дом в Кабестане и отправился изучать руины троллей в Танарисе." }, { 25.82, "Удачи в поисках – о нём давненько ничего не слышно!" } } }, t = { d = 10.6, v = "goblin-male", n = { x = 108 }, c = { x = { { 0.00, "О да, я видел затонувший храм собственными глазами." }, { 4.20, "Хочешь узнать о нём побольше?" }, { 6.67, "Уж я сразу узнаю настоящего искателя приключений!" } } } } },
    [3446] = { d = 29.6, v = "goblin-male", n = { x = 331 }, c = { x = { { 0.00, "В храме я видел круглый зал с шестью галереями, каждую из которых украшала змея, высеченная из камня." }, { 7.26, "Я всего лишь дотронулся до одной из них и угодил в ловушку!" }, { 11.44, "Произошёл сильнейший взрыв – мне несказанно повезло, что остался цел." }, { 16.19, "Лёжа там, на краю галереи, я заметил ещё одну статую в самом низу зала – что-то вроде алтаря." }, { 22.93, "Алтарь Хаккара, полагаю." }, { 24.73, "Положи на алтарь этот знак – думаю, это поможет открыть его секреты." } } }, t = { d = 13.8, v = "narrator", n = { x = 136 }, c = { x = { { 0.00, "Вы помещаете круглый камень в углубление и слышите негромкий щелчок." }, { 5.66, "Теперь камень на положенном ему месте..." }, { 9.08, "Но что же делать дальше?" }, { 11.09, "Пожалуй, стоит осмотреть алтарь..." } } } } },
    [3447] = { d = 40.3, v = "goblin-male", n = { x = 451 }, c = { x = { { 0.00, "Всё, что я видел в храме, сохранилось в моей памяти лишь урывками, но я постараюсь рассказать тебе всё как можно подробней." }, { 8.84, "Круг статуй, сокрытый в храме – весьма опасное место, но я уверен, что там спрятан ключ к великим сокровищам." }, { 16.70, "Когда я подошёл к главному алтарю, в зале зажглись огни." }, { 20.82, "Если тебе удастся разгадать, что они значат, возможно, сумеешь понять и тайны, которые скрывает эта комната." }, { 28.88, "Однако я должен предупредить тебя." }, { 31.43, "В храме заключено великое зло." }, { 33.66, "Какие бы сокровища там ни скрывались, древние силы будут яростно защищать их от посягательств." } } }, t = { d = 17.5, v = "narrator", n = { x = 158 }, c = { x = { { 0.00, "Глаза идола ярко сияют даже в полумраке, царящем в храме." }, { 5.30, "Кажется, внутри спрятано что-то блестящее." }, { 9.16, "Вы просовываете руку внутрь статуи и хватаете то, что там лежит." }, { 14.79, "Теперь сокровище Аталаи – ваше!" } } } } },
    [3448] = { d = 32.5, v = "dwarf-male", n = { x = 383 }, c = { x = { { 0.00, "Недавно мне доверили задачу исследования Азшары – некогда прекрасного края, который эльфы называли домом." }, { 7.42, "Это было в те времена, когда они занимались магией." }, { 11.13, "Теперь же это место скорее опасно, чем прекрасно, но это не остановит нас." }, { 16.34, "Мы перевернём его по камушку, чтобы разгадать загадки нашего прошлого." }, { 21.25, "Мой товарищ Тимор предложил мне помощь в исследованиях, поскольку это и его самого особенно интересует." }, { 28.47, "У него здесь в городе есть небольшой дом рядом с Залом Тайн." } } }, t = { d = 34.6, v = "dwarf-male", n = { x = 366 }, c = { x = { { 0.00, "Ах, так вас послал Карик?" }, { 1.93, "Я как раз ждал от него известий." }, { 4.34, "Я тут такое узнал об Азшаре..." }, { 6.68, "Я знаю, что ночные эльфы живут невероятно долго, но все порой забывают о некоторых... неприятных событиях в их жизни." }, { 15.63, "Это не критика, всего лишь замечание." }, { 18.53, "Давным-давно там существовали города, возведённые эльфами, которые много знали о магии и других утраченных искусствах." }, { 27.48, "Поскольку я такие вещи изучаю, я начал свои исследования." }, { 31.95, "И открытия мои просто ошеломляющие." } } } } },
    [3449] = { d = 36.1, v = "dwarf-male", n = { x = 415 }, c = { x = { { 0.00, "Некоторые эльфы в старину почитали магию не меньше самой Элуны." }, { 4.67, "Их самые могущественные маги создали руны и таблички, в которых были перечислены законы чародейства и разгадки их открытий." }, { 13.57, "Они, как правило, выставляли их на всеобщее обозрение, чтобы все могли над ними поразмышлять." }, { 20.25, "Я был бы очень рад получить прорисовки этих рун из руин Эльдарата." }, { 24.99, "Чтобы сделать прорисовки, я дам вам готовальню, но найти их должны вы сами." }, { 30.38, "Будьте осторожны, не только лига Исследователей имеет свои интересы в Эльдарате." } } }, t = { d = 17.6, v = "dwarf-male", n = { x = 201 }, c = { x = { { 0.00, "Рад видеть вас в целости и сохранности." }, { 2.71, "Надеюсь, дело оказалось для вас не слишком трудным." }, { 6.29, "Доставлю их Тимору прямо сейчас." }, { 8.62, "Он просто с ума сойдёт от радости." }, { 11.01, "Да выбросьте вы это сигнальное ружьё... оно всё равно вам уже ни к чему, да у меня и другое есть." } } } } },
    [3450] = { d = 35.9, v = "dwarf-male", n = { x = 452 }, c = { x = { { 0.00, "Я хочу, чтобы эти прорисовки были доставлены мне в башню, но вам незачем лично проделывать весь этот путь." }, { 6.93, "Пусть их просто доставят из Азшары по воздуху." }, { 9.92, "У Хиггса Раздувателя Горна есть перед мной должок, к тому же он скоро окажется в тех местах – он назначен патрулировать побережье." }, { 18.32, "Поговорите с ним перед отъездом." }, { 20.44, "Он даст вам сигнальное ружьё, чтобы вы могли подать ему сигнал." }, { 24.55, "Когда добудете прорисовки, отправляйтесь в условленное место и отдайте их ему, чтобы он доставил их в мою башню в целости и сохранности." }, { 33.42, "Он должен быть в ангаре в Палатах Войны." } } }, t = { d = 23.1, v = "dwarf-male", n = { x = 274 }, c = { x = { { 0.00, "Чем могу помочь?" }, { 1.17, "Я как бы занят сейчас – готовлю аппаратик свой к долгому полёту." }, { 5.46, "Я тут зашёл поговорить с водителями танков – мне нужны гривы вендиго, чтобы кабину утеплить, а у них обычно есть." }, { 13.07, "Так что уделить вам могу не больше минуты... один парень только что пошёл в депо Посёлок Сталежара, чтобы посмотреть, найдутся ли у них для меня гривы." } } } } },
    [3451] = { d = 27.0, v = "dwarf-male", n = { x = 270 }, c = { x = { { 0.00, "А, так вас послал Тимор?" }, { 1.91, "Да, есть у меня перед ним должок." }, { 4.53, "Это что?" }, { 5.24, "Ах, поганец!" }, { 6.23, "Ладно, я ему помогу." }, { 7.93, "Значит, вам нужны сигнальное ружьё и условленная точка... да легко." }, { 13.17, "Близ южного мыса Азшары есть небольшой островок, где мы соорудили посадочную площадку." }, { 19.90, "Берёте ружьё и даёте оттуда сигнал." }, { 22.59, "Я вижу сигнал и прилетаю забрать это... ну, что ему надо." } } }, t = { d = 16.9, v = "dwarf-male", n = { x = 205 }, c = { x = { { 0.00, "Вот вам сигнальное ружьё." }, { 1.64, "Когда дадите сигнал, запаситесь терпением – в нём всего два патрона, а мне потребуется несколько минут, чтобы добраться до вас, в зависимости от того, насколько далеко над морем я буду." }, { 14.04, "Выстрелите из ружья – и полюбуйтесь на море." } } } } },
    [3452] = { d = 29.9, v = "human-male", n = { x = 365 }, c = { x = { { 0.00, "Работа над факелом близится к завершению." }, { 2.80, "Не хватает лишь одного компонента." }, { 5.12, "В горах к северо-западу отсюда есть большой лагерь Сумеречного Молота." }, { 9.94, "Говорят, они носят при себе некие символы и идолов в дань уважения своему богу." }, { 15.43, "Полагаю, в этих символах и идолах заключены чары достаточной силы для создания магической брони." }, { 22.01, "Принеси мне знак Рагнароса, и я попытаюсь извлечь из него его магическую силу, чтобы создать защитные чары для факела." } } }, t = { d = 6.3, v = "human-male", n = { x = 70 }, c = { x = { { 0.00, "Символ источает злые чары – именно они и требуются для завершения работы над факелом." } } } } },
    [3453] = { d = 5.3, v = "human-male", n = { x = 61 }, c = { x = { { 0.00, "Мне нужно несколько минут, чтобы сложить вместе все части и наложить чары." } } }, t = { d = 4.8, g = 1, v = "human-male", n = { m = 51, f = 51 }, c = { m = { { 0.00, "Есть ещё одно, последнее задание, которое ты должен выполнить." } }, f = { { 0.00, "Есть ещё одно, последнее задание, которое ты должна выполнить." } } } } },
    [3454] = { d = 4.6, v = "human-male", n = { x = 49 }, c = { x = { { 0.00, "Факел готов и отныне связан со своим владельцем." }, { 3.75, "Возьми его." } } }, t = { d = 7.9, v = "narrator", n = { x = 71 }, c = { x = { { 0.00, "Вы хватаете факел обеими руками и ощущаете исходящие от него волны гнева и ненависти." } } } } },
    [3461] = { d = 30.2, v = "dwarf-male", n = { x = 343 }, c = { x = { { 0.00, "Тимор не оставил мне ничего, чтобы вам заплатить, потому предлагаю вам обсудить награду лично с ним, когда вернётесь в Стальгорн." }, { 8.98, "Я уверен, что он до сих пор у себя в Палатах Магии." }, { 12.55, "Постучитесь и потребуйте щедрой платы, потому как местечко-то не для пикника... это уж точно." }, { 19.11, "Всё же благодарю вас, что вы ему помогли, и желаю удачи." }, { 23.06, "Ой, готовальня мне ни к чему." }, { 25.10, "Почему бы вам просто не отдать её лично Тимору, когда вы с ним встретитесь?" } } }, t = { d = 22.9, v = "dwarf-male", n = { x = 243 }, c = { x = { { 0.00, "Отлично!" }, { 0.69, "Я так рад это слышать." }, { 2.41, "Как мне не терпится вернуться в мою башню и поработать над прорисовками..." }, { 7.97, "Я так завидую вам!" }, { 9.35, "Побывать в Азшаре... думаю, это мечта всех изучающих чародейские науки." }, { 14.85, "Ладно, хотя мы и не говорили о награде, поскольку вы работаете на лигу Исследователей, но вы её заслуживаете." } } } } },
    [3462] = { d = 6.2, v = "human-male", n = { x = 77 }, c = { x = { { 0.00, "Поговори с моим посыльным, оруженосцем Малтрейком." }, { 3.53, "Он объяснит тебе, как использовать факел." } } }, t = { d = 1.9, g = 1, v = "human-male#50", n = { m = 18, f = 19 }, c = { m = { { 0.00, "Ты готов нанести удар?" } }, f = { { 0.00, "Ты готова нанести удар?" } } } } },
    [3463] = { d = 30.4, g = 1, v = "human-male#50", n = { m = 360, f = 360 }, c = { m = { { 0.00, "Слушай меня внимательно." }, { 1.73, "Четыре башни нельзя разрушить, но если поджечь их с помощью факела воздаяния, пламя не угаснет очень долго – и это пламя нельзя будет унять никакими силами." }, { 12.68, "Пока башни горят, ни один страж или караульный не сможет подняться на них – а значит, первая линия обороны противника фактически будет прорвана." }, { 22.65, "Ты должен пробраться в башни и поджечь их с помощью факела воздаяния." }, { 27.41, "И берегись патрульных клана Чёрного Железа!" } }, f = { { 0.00, "Слушай меня внимательно." }, { 1.74, "Четыре башни нельзя разрушить, но если поджечь их с помощью факела воздаяния, пламя не угаснет очень долго – и это пламя нельзя будет унять никакими силами." }, { 12.75, "Пока башни горят, ни один страж или караульный не сможет подняться на них – а значит, первая линия обороны противника фактически будет прорвана." }, { 22.77, "Ты должна пробраться в башни и поджечь их с помощью факела воздаяния." }, { 27.56, "И берегись патрульных клана Чёрного Железа!" } } }, t = { d = 4.0, v = "human-male#50", n = { x = 40 }, c = { x = { { 0.00, "Это великолепно!" }, { 1.46, "Разве не великолепно, господин?" } } } } },
    [3481] = { d = 2.6, v = "narrator", n = { x = 18 }, c = { x = { { 0.00, "Похоже, сундук заперт." } } }, t = { d = 10.6, v = "narrator", n = { x = 106 }, c = { x = { { 0.00, "Замок открывается, как только вы прикасаетесь к нему." }, { 4.42, "Любопытно, сколько же здесь может быть сыра?" }, { 8.10, "Есть только один способ узнать." } } } } },
    [3482] = { d = 3.7, v = "narrator", n = { x = 35 }, c = { x = { { 0.00, "Это версия задания о чёрном ящике для Орды." } } } },
    [3483] = { t = { d = 15.3, v = "dwarf-male", n = { x = 163 }, c = { x = { { 0.00, "А, ещё одна сигнальная ракетница, да?" }, { 2.84, "Это можно." }, { 3.74, "И не забудь: южная оконечность Азшары." }, { 6.71, "Там маленький островок, который превратили в посадочную площадку." }, { 11.69, "Если окажешься в нужном месте, мимо не пройдёшь." } } } } },
    [3501] = { d = 38.7, v = "creature/lostone", n = { x = 404 }, c = { x = { { 0.00, "Быть может, ты никогда не найдёшь безупречную сферу из дренейского аметиста, однако во время скитаний по этим землям тебе, несомненно, удастся обнаружить различные несовершенные фрагменты дренейского аметиста." }, { 17.00, "Хотя сомнительно, что Кум-иша сможет использовать эти несовершенные фрагменты для возвращения домой, эти осколки могут сослужить иную, весьма полезную службу для дренеев." }, { 31.04, "Принеси любой несовершенный фрагмент дренейского аметиста, который найдёшь, и я вознагражу тебя." } } }, t = { d = 14.5, g = 1, v = "creature/lostone", n = { m = 110, f = 110 }, c = { m = { { 0.00, "Ты разочаровываешь меня, герой." }, { 3.05, "Такой большой, а роняет слюни над грудой хлама?" }, { 7.75, "Какое жалкое зрелище!" }, { 9.92, "Забирай свою награду и прочь с глаз моих!" } }, f = { { 0.00, "Ты разочаровываешь меня, героиня." }, { 3.35, "Такая большая, а роняет слюни над грудой хлама?" }, { 8.23, "Какое жалкое зрелище!" }, { 10.49, "Забирай свою награду и прочь с глаз моих!" } } } } },
    [3502] = { d = 34.2, v = "creature/lostone", n = { x = 322 }, c = { x = { { 0.00, "Ну-с, узрев проявление этой ненасытной жадности, я не могу сдержать отвращение." }, { 6.93, "И тем не менее я не намерен долго задерживаться на твоём пристрастии к материальным благам." }, { 14.72, "За каждый несовершенный фрагмент дренейского аметиста, который ты принесёшь, я вознагражу тебя каким-нибудь хламом." }, { 24.63, "Моя груда хлама будет уменьшаться, а твоя – расти." }, { 29.12, "На Дреноре такая ситуация называлась \"все в выигрыше\"." } } }, t = { d = 23.6, g = 1, v = "creature/lostone", n = { m = 180, f = 180 }, c = { m = { { 0.00, "Ты разочаровываешь меня, герой." }, { 3.20, "Такой большой, а роняет слюни над грудой хлама?" }, { 8.14, "Какое жалкое зрелище!" }, { 10.42, "Забирай свою награду и прочь с глаз моих." }, { 14.63, "Знакомые слова?" }, { 16.27, "А как же – я повторяю их тысячу раз на дню." }, { 20.48, "О, как мне отвратителен этот мир!" } }, f = { { 0.00, "Ты разочаровываешь меня, героиня." }, { 3.33, "Такая большая, а роняет слюни над грудой хлама?" }, { 8.20, "Какое жалкое зрелище!" }, { 10.45, "Забирай свою награду и прочь с глаз моих." }, { 14.60, "Знакомые слова?" }, { 16.22, "А как же – я повторяю их тысячу раз на дню." }, { 20.37, "О, как мне отвратителен этот мир!" } } } } },
    [3503] = { t = { d = 27.4, v = "bloodelf-male", n = { x = 310 }, c = { x = { { 0.00, "Было время, когда я мог требовать что угодно от тех, кто искал встречи с моим господином." }, { 6.34, "А теперь тебе достаточно попросить – и я отправлю тебя к нему." }, { 10.82, "Меня это огорчает, но я не обсуждаю его приказы." }, { 14.34, "Мне остаётся лишь потешаться над твоим нелепым нарядом или жалким выражением лица." }, { 20.16, "Но и это мне наскучило..." }, { 21.95, "Даже эта болтовня мне наскучила!" }, { 24.32, "Так ты хочешь видеть моего господина или нет?" } } } } },
    [3504] = { d = 43.4, v = "orc-male#60", n = { x = 422 }, c = { x = { { 0.00, "Предательница и воровка!" }, { 1.97, "Других слов для неё у меня нет!" }, { 4.45, "Наверное, я сделал большую ошибку." }, { 7.30, "Я доверился эльфу крови." }, { 9.35, "Хуже того – я доверился женщине!" }, { 12.05, "Она уверяла, будто в Азшаре хранятся несметные сокровища... могущественные артефакты..." }, { 19.13, "Всё, что нужно, – это отправить с ней нескольких воинов для охраны, и она меня щедро вознаградит." }, { 27.01, "Ну, и кто остался в дураках?" }, { 29.28, "Она их всех перебила!" }, { 31.03, "Я жажду мести." }, { 32.27, "Но посылать туда других воинов я уже не могу." }, { 36.07, "Найди Аг'тора в Храбростане, к северу от лагеря Халдарр." }, { 40.67, "Он тебе скажет, что делать дальше." } } }, t = { d = 27.1, v = "orc-male#60", n = { x = 267 }, c = { x = { { 0.00, "Мы уже многих посылали против неё и её приспешников, но они слишком сильны!" }, { 6.26, "Никто из посланных не вернулся." }, { 8.87, "Наверное, некоторые погибли, но большинство, подозреваю, просто сбежали." }, { 14.83, "Трусы!" }, { 15.43, "Однако теперь, когда прибыло подкрепление, у нас снова появилась надежда." }, { 21.54, "Быть может, мы всё-таки сумеем с ней разобраться." }, { 25.49, "Ну так что, ты с нами?" } } } } },
    [3505] = { d = 35.7, v = "orc-male#60", n = { x = 373 }, c = { x = { { 0.00, "Так я и думал." }, { 1.13, "Мы начнём наступать на её приспешников от южных утёсов северного полуострова Азшары." }, { 7.56, "Убивайте их, не зная пощады – пусть знают, кого предали!" }, { 12.01, "Насчёт её самой пока не тревожьтесь – она проводит большую часть времени, рыская по Азшаре вместе со своими телохранителями." }, { 21.70, "После того как перебьете её работников, стоит отыскать её личный лагерь." }, { 27.42, "Нужно сначала разведать, откуда можно на неё напасть." }, { 31.66, "Может быть, стоит как-нибудь выманить её из лагеря..." } } }, t = { d = 24.3, v = "narrator", n = { x = 258 }, c = { x = { { 0.00, "Вы начинаете листать страницы и обнаруживаете, что одна из них заложена узкой ленточкой чёрного шёлка." }, { 7.99, "Вы пытаетесь разобрать непонятные слова и видите на одной из страниц схему." }, { 14.04, "Присмотревшись, вы понимаете, что кристаллы, круг и некоторые другие компоненты, лежащие на земле, расположены так же, как на рисунке." } } } } },
    [3506] = { d = 35.5, v = "narrator", n = { x = 375 }, c = { x = { { 0.00, "Вы поразмыслили ещё немного, и вам на ум пришло сразу несколько идей, одна из которых заставила улыбнуться: возможно, если вы уничтожите кристаллы, подлая эльфийка, погубившая стольких орков, достаточно разозлится?" }, { 16.94, "Вы продолжаете разбирать текст и рисунки и понимаете, что один из кристаллов связан с создателем круга – прочие же связаны с куда более жуткими тварями." }, { 29.00, "Вы закрываете книгу и начинаете прикидывать, какой из кристаллов следует уничтожить." } } }, t = { d = 13.3, v = "orc-male#60", n = { x = 105 }, c = { x = { { 0.00, "Ага!!!" }, { 0.72, "Невероятно!" }, { 1.88, "Тебе это удалось!" }, { 3.77, "То-то Белгром обрадуется!" }, { 6.37, "Наконец-то души десятков наших воинов упокоятся в мире." }, { 12.02, "Спасибо тебе." } } } } },
    [3507] = { d = 11.8, v = "orc-male#60", n = { x = 113 }, c = { x = { { 0.00, "Вернись в Оргриммар к Белгрому." }, { 2.69, "Он захочет увидеть её голову своими глазами!" }, { 6.54, "Мы там тоже скоро будем." }, { 8.69, "Удачный у нас денёк!" }, { 10.38, "Спасибо за помощь." } } }, t = { d = 38.9, v = "orc-male#60", n = { x = 323 }, c = { x = { { 0.00, "Ха-ха-ха!" }, { 0.98, "Вот и ты, жалкая девчонка!" }, { 3.57, "Я плюю на твои останки!" }, { 5.98, "Спасибо." }, { 6.99, "Я благодарю тебя от всей души!" }, { 10.02, "Это воистину великий день!" }, { 12.70, "Будь это в моей власти, я наградил бы тебя целым королевством!" }, { 18.94, "Но, может быть, ты согласишься на это?" }, { 22.60, "*Белгром смотрит на голову мага, который предал его.*" }, { 26.76, "Ха-ха!" }, { 27.43, "Глупая эльфийка!" }, { 29.02, "Вот что с тобой стало!" }, { 31.12, "В парусиновом мешке, голова отдельно, тело отдельно!" }, { 36.06, "Не надо было предавать Белгрома!" } } } } },
    [3508] = { d = 33.5, v = "nightelf-male#55", n = { x = 389 }, c = { x = { { 0.00, "Тебе свойственна безрассудная храбрость." }, { 2.86, "Это ценное качество твоего рода – слепо кидаться в битву, почти не имея шансов на успех." }, { 9.29, "Я помогу тебе, хотя бы только ради того, чтобы увидеть смерть приспешников Разелиха." }, { 15.34, "Однако для того, чтобы пробиться через охранные чары, окружающие их, требуется время, равно как и использование редких артефактов." }, { 24.56, "Не нарушай тишину, я должен исполнить ритуал просветления." }, { 28.70, "Сведения, которые я получу, помогут мне отковать оружие великой мощи." } } }, t = { d = 2.6, v = "nightelf-male#55", n = { x = 26 }, c = { x = { { 0.00, "Необходимо отыскать имя зверя." } } } } },
    [3509] = { d = 33.5, v = "nightelf-male#55", n = { x = 358 }, c = { x = { { 0.00, "Существует лишь один способ причинить вред повелителю демонов и его приспешникам." }, { 6.24, "Следует выковать оружие силы, несущее его истинное имя." }, { 10.67, "Когда такое оружие будет выковано, демон и все, кем он повелевает, станут уязвимы." }, { 17.04, "В Азшаре обитает меньшее божество: лорд Арккорос." }, { 20.85, "Тебе следует найти его." }, { 22.79, "Однако осторожнее: его слуги не остановятся ни перед чем, чтобы убить тебя, если обнаружат." }, { 29.93, "Несомненно, за такие сведения придётся заплатить." } } }, t = { d = 11.7, g = 1, v = "creature/ancient", n = { m = 112, f = 112 }, c = { m = { { 0.00, "Повелитель демонов?" }, { 1.81, "Быть может, кое-кто сможет помочь тебе этими сведениями; но сначала ты должен помочь кое-кому." } }, f = { { 0.00, "Повелитель демонов?" }, { 1.89, "Быть может, кое-кто сможет помочь тебе этими сведениями; но сначала ты должна помочь кое-кому." } } } } },
    [3510] = { d = 31.7, v = "creature/ancient", n = { x = 245 }, c = { x = { { 0.00, "Она убивает моих детей." }, { 2.58, "Она называет себя повелительницей океанов." }, { 7.02, "Фальшивая богиня, и ничего более." }, { 10.52, "Сокруши её и принеси мне все её головы." }, { 14.49, "За это ты получишь то имя, которое тебе нужно, и кое-что ещё, не менее важное." }, { 22.62, "Она бродит вокруг гнезда..." }, { 25.57, "Она зовётся Хетайра." }, { 27.60, "*Лорд Арккорос указывает на юго-запад.*" }, { 30.88, "Иди!" } } }, t = { d = 4.8, v = "creature/ancient", n = { x = 44 }, c = { x = { { 0.00, "Наконец-то хоть кто-то достойный мудрости Арккороса!" } } } } },
    [3511] = { d = 40.3, v = "creature/ancient", n = { x = 360 }, c = { x = { { 0.00, "Как и обещал, я открою тебе имя Повелителя демонов Разелиха Осквернителя." }, { 7.04, "Однако сначала я должен приготовить кое-что необычайно важное для твоего путешествия." }, { 15.19, "Для создания оружия, которое ты ищешь, необходим состав для закалки." }, { 21.71, "Подожди немного, я выжму кровь из этих голов." }, { 26.00, "*Лорд Арккорос сжимает головы между своими гигантскими ладонями, выдавливая из них кровь.*" }, { 33.20, "Доставь этот состав для закалки Лорамусу вместе с именем зверя: Рах'лих." } } }, t = { d = 9.4, v = "nightelf-male#55", n = { x = 104 }, c = { x = { { 0.00, "Этот состав содержит протравку, необходимую нам для отковки оружия." }, { 5.13, "Остался лишь один, последний шаг к созданию этого оружия." } } } } },
    [3512] = { d = 35.3, v = "bloodelf-male", n = { x = 423 }, c = { x = { { 0.00, "Нашим первым шагом будет разработка способа связаться с Эраникусом через этот камень." }, { 6.05, "Он сейчас находится на зыбкой грани между сном и смертью, в сетях кошмаров." }, { 11.29, "Хотя принесённая тобою сущность сильно поражена порчей, всё ещё есть шанс, что мы дотянемся до Эраникуса." }, { 18.40, "Тебе придётся отправиться далеко на север, и к востоку от Зимних Ключей разыскать нашего смертного союзника, Умбранса Ищущего Духов." }, { 27.56, "Это человек, медиум, говорящий с мёртвыми." }, { 30.50, "Хотя Эраникус и не вполне мёртв, этот человек всё же сможет нам помочь." } } }, t = { d = 28.1, v = "human-male", n = { x = 320 }, c = { x = { { 0.00, "Хорошо, что Итар послал тебя ко мне." }, { 2.57, "Хотя Эраникус и не мёртв в общем смысле этого слова, я смогу поговорить с ним." }, { 8.03, "Но прямо сейчас я не могу помочь тебе..." }, { 10.91, "Я с удовольствием это сделаю, но сначала мне самому нужна помощь того, кто, в отличие от меня, не скован старческой немощью." }, { 19.57, "Мой наиболее ценный гадальный инструмент был у меня украден, и, пока я не заполучу его обратно, я бессилен помочь Эраникусу." } } } } },
    [3513] = { d = 20.5, v = "narrator", n = { x = 196 }, c = { x = { { 0.00, "Свиток официального вида перевязан серебристой лентой." }, { 4.65, "Несомненно, кому-то он был бы весьма интересен, но кому?" }, { 9.37, "На севере, рядом с границей Ясеневого леса, есть застава, и если в свитке идёт речь о ночных эльфах, именно туда его и надо отнести." } } }, t = { d = 3.2, g = 1, v = "orc-male", n = { m = 18, f = 18 }, c = { m = { { 0.00, "Та-ак..." }, { 1.07, "И где ты это нашёл?" } }, f = { { 0.00, "Та-ак..." }, { 1.06, "И где ты это нашла?" } } } } },
    [3514] = { d = 36.4, g = 1, v = "orc-male", n = { m = 360, f = 360 }, c = { m = { { 0.00, "Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Пещеры Когтей на Пике Каменного Когтя." }, { 8.48, "Она уже не встретится с гонцом, у которого ты нашёл этот свиток, хе-хе, но так просто им это не пройдёт." }, { 16.89, "Орда не потерпит такого нахальства." }, { 19.81, "Ступай в Пещеру Когтей." }, { 21.79, "Убей Ринтариэль и покажи это всем." }, { 24.64, "Возьми с собой флаг Орды и установи его в Пещере Когтей у всех на виду." }, { 30.49, "В другой раз они трижды подумают, прежде чем снова соваться в наши земли." } }, f = { { 0.00, "Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Пещеры Когтей на Пике Каменного Когтя." }, { 8.43, "Она уже не встретится с гонцом, у которого ты нашла этот свиток, хе-хе, но так просто им это не пройдёт." }, { 16.85, "Орда не потерпит такого нахальства." }, { 19.76, "Ступай в Пещеру Когтей." }, { 21.72, "Убей Ринтариэль и покажи это всем." }, { 24.55, "Возьми с собой флаг Орды и установи его в Пещере Когтей у всех на виду." }, { 30.36, "В другой раз они трижды подумают, прежде чем снова соваться в наши земли." } } }, t = { d = 20.8, g = 1, v = "orc-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Да ты силён!" }, { 1.00, "Это большое дело – лишить Пещеру Когтей Ринтариэль." }, { 5.53, "Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса." }, { 15.50, "Они подумают дважды, прежде чем снова соваться к нам." }, { 20.11, "Спасибо." } }, f = { { 0.00, "Да ты сильна!" }, { 1.15, "Это большое дело – лишить Пещеру Когтей Ринтариэль." }, { 5.66, "Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса." }, { 15.60, "Они подумают дважды, прежде чем снова соваться к нам." }, { 20.19, "Спасибо." } } } } },
    [3517] = { d = 37.0, v = "orc-female#58", n = { x = 404 }, c = { x = { { 0.00, "Ты знаешь, я, в общем, неплохо устроилась в Азшаре." }, { 3.92, "У наказания Белгрома, обрушившегося на мою голову, есть свои положительные стороны." }, { 10.24, "Я тут полазала по окрестностям и обнаружила просто уйму ценностей, валяющихся без дела." }, { 16.84, "Если интересно, могу рассказать подробнее и даже поделюсь прибылью, если поможешь мне добыть кое-что." }, { 24.68, "В руинах Эльдарата к востоку отсюда сокрыты четыре таблички." }, { 29.35, "Каждая из них носит имя мага высокорождённых." }, { 32.79, "Принеси мне их, и мы поговорим о дальнейшем сотрудничестве." } } }, t = { d = 13.6, g = 1, v = "orc-female#58", n = { m = 125, f = 127 }, c = { m = { { 0.00, "Отлично, ты принёс все таблички, и они в хорошем состоянии." }, { 5.14, "Мы получим за них хорошую цену." }, { 7.91, "Ну, не будем тратить время зря." }, { 10.68, "Пора обменять таблички на денежки!" } }, f = { { 0.00, "Отлично, ты принесла все таблички, и они в хорошем состоянии." }, { 5.01, "Мы получим за них хорошую цену." }, { 7.58, "Ну, не будем тратить время зря." }, { 10.16, "Пора обменять таблички на денежки!" } } } } },
    [3518] = { d = 30.5, v = "orc-female#58", n = { x = 356 }, c = { x = { { 0.00, "Первую табличку нужно отнести таурену по имени Магата." }, { 3.96, "Ты найдёшь её среди старейшин Громового Утёса." }, { 7.16, "Она самая ярая сторонница заключения союза тауренов с Отрёкшимися, ибо считает, что именно таурены и их обычаи могут помочь Отрёкшимся вновь найти путь к обретению человеческой природы." }, { 20.20, "Отнеси ей табличку Бет'Амары." }, { 22.31, "Тауренка считает, что может найти в табличке способ, как помочь Отрёкшимся... ну да, по крайней мере она в это верит." } } }, t = { d = 27.1, v = "named/4046", n = { x = 244 }, c = { x = { { 0.00, "О, наконец-то!" }, { 1.33, "Табличка Бет'Амары!" }, { 3.15, "А я уж гадала, неужели орк не сдержала обещания, или, чего доброго, бедняжка нашла кончину в Азшаре." }, { 12.44, "Я рада, что ей удалось." }, { 14.60, "Бет'Амара был одним из самых могущественных алхимиков высокорождённых." }, { 20.90, "Говорят, что он единственный овладел искусством трансмутации металлов." } } } } },
    [3519] = { d = 18.9, v = "nightelf-male#59", n = { x = 192 }, c = { x = { { 0.00, "Ох... меня сильно покусала паучиха по имени Гитьис Зловещая, когда я обследовал паучиную пещеру." }, { 7.76, "Похоже, я серьёзно отравлен." }, { 9.98, "Помоги мне!" }, { 10.92, "Пожалуйста, дай знать Дирании Серебряному Сиянию." }, { 14.79, "Она сможет помочь мне." }, { 16.66, "Спеши..." }, { 17.38, "Как голова кружится…" } } }, t = { d = 7.9, v = "nightelf-female#52", n = { x = 80 }, c = { x = { { 0.00, "Ох, какая беда, а я-то думала, что это сегодня Иверрона не видно..." }, { 5.24, "Предупреждала же я его насчёт пауков!" } } } } },
    [3520] = { d = 33.8, v = "troll-male#77", n = { x = 346 }, c = { x = { { 0.00, "Мне нужны духи дольных крикунов из Фераласа." }, { 3.59, "Они родственники старого-престарого бога и напрямую связаны с ним." }, { 8.91, "Возьми ежевичный посох и ступай в Фералас." }, { 12.36, "Отыщи в южной и центральной части дольных крикунов и одержи над ними верх." }, { 18.33, "Потом помаши моим посохом над их телами." }, { 21.63, "Таким образом ты выманишь их души." }, { 24.43, "Коснись каждой из душ и собери их сущности." }, { 27.88, "Принеси мне посох и собранные сущности, и я расскажу тебе о том старом боге." } } }, t = { d = 32.9, v = "troll-male#77", n = { x = 326 }, c = { x = { { 0.00, "Молодец." }, { 0.75, "Пожалуй, пришло время рассказать тебе правду…" }, { 4.63, "У троллей существует пророчество о возвращении на землю убитого бога, Хаккара Свежевателя Душ." }, { 12.41, "Некоторые говорят, что пришествие Хаккара принесёт троллям радость и славу, другие же ждут лишь конца всего сущего." }, { 21.90, "Я не верю в этот миф, но не сомневаюсь, что сущность Хаккара таит в себе великую силу, которая не должна попасть в руки недостойных..." } } } } },
    [3521] = { d = 27.9, v = "nightelf-female#52", n = { x = 344 }, c = { x = { { 0.00, "Мы могли бы помочь Иверрону: я знаю противоядие, которое нейтрализует действие яда." }, { 5.59, "Но для него мне нужны некоторые ингредиенты." }, { 8.53, "Мне понадобятся гиацинтовые грибы." }, { 10.82, "Их можно найти под деревьями или добыть у греллей к югу отсюда – похоже, они им по вкусу." }, { 16.88, "Ещё мне нужны лунные лилии, что растут только вокруг прудов." }, { 20.97, "Последний ингредиент добыть сложнее всего." }, { 23.85, "Это лимфа тех самых чащобных тенётников, что отравили Иверрона." } } }, t = { d = 7.4, g = 1, v = "nightelf-female#52", n = { m = 83, f = 84 }, c = { m = { { 0.00, "Хвала Элуне – ты так быстро собрал все ингредиенты!" }, { 3.74, "Подожди минутку, сейчас я приготовлю противоядие." } }, f = { { 0.00, "Хвала Элуне – ты так быстро собрала все ингредиенты!" }, { 3.89, "Подожди минутку, сейчас я приготовлю противоядие." } } } } },
    [3522] = { d = 16.7, v = "nightelf-female#52", n = { x = 202 }, c = { x = { { 0.00, "Противоядие готово." }, { 1.35, "Пожалуйста, проследи, чтобы Иверрон его выпил." }, { 4.60, "И запомни – это важно: противоядие будет обладать своими целебными свойствами в течение пяти минут." }, { 11.47, "Необходимо доставить его до истечения этого времени." }, { 15.08, "Поторопись, во имя Элуны!" } } }, t = { d = 25.4, g = 1, v = "nightelf-male#59", n = { m = 267, f = 268 }, c = { m = { { 0.00, "Что это?" }, { 0.87, "Я знал, что Дирания поможет мне!" }, { 3.84, "*Иверрон выпивает противоядие.*" }, { 6.72, "Я всё время попадаю в переделки, а Дирания постоянно меня из них вытаскивает." }, { 12.14, "Мне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя." }, { 18.65, "Что ж, надеюсь, ты расчистил мне дорогу через этот лес, полный мерзостных чащобных тенётников..." } }, f = { { 0.00, "Что это?" }, { 0.87, "Я знал, что Дирания поможет мне!" }, { 3.84, "*Иверрон выпивает противоядие.*" }, { 6.64, "Я всё время попадаю в переделки, а Дирания постоянно меня из них вытаскивает." }, { 12.14, "Мне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя." }, { 18.73, "Что ж, надеюсь, ты расчистила мне дорогу через этот лес, полный мерзостных чащобных тенётников..." } } } } },
    [3523] = { d = 30.4, g = 1, v = "human-male", n = { m = 350, f = 353 }, c = { m = { { 0.00, "Благодарю, что спас меня!" }, { 1.76, "Имя мне Белнистраз." }, { 3.15, "Не хотелось бы закончить жизнь столь бесславно – быть сожранным одной из омерзительных тварей Плети." }, { 10.01, "Да-да, ты не ослышался, Плеть вступила в союз с местными свинобразами." }, { 14.85, "Послушай... вместо того, чтобы бежать, спасая собственную жизнь, я бы предпочёл вступить с врагом в бой, чтобы защитить невинных." }, { 23.79, "Не желаешь ли ты мне помочь?" }, { 25.74, "Это опасно, но ты явно не из тех, кто пасует перед трудностями." } }, f = { { 0.00, "Благодарю, что спасла меня!" }, { 1.96, "Имя мне Белнистраз." }, { 3.35, "Не хотелось бы закончить жизнь столь бесславно – быть сожранным одной из омерзительных тварей Плети." }, { 10.24, "Да-да, ты не ослышалась, Плеть вступила в союз с местными свинобразами." }, { 15.18, "Послушай... вместо того, чтобы бежать, спасая собственную жизнь, я бы предпочёл вступить с врагом в бой, чтобы защитить невинных." }, { 24.16, "Не желаешь ли ты мне помочь?" }, { 26.12, "Это опасно, но ты явно не из тех, кто пасует перед трудностями." } } }, t = { d = 16.7, v = "human-male", n = { x = 175 }, c = { x = { { 0.00, "Весьма похвально." }, { 1.38, "Я знал, что ты из тех, кто захочет взяться за это непростое и опасное дело." }, { 7.02, "Не скрою, нам предстоит тяжёлая работа." }, { 9.98, "Но мы должны приложить все усилия и справиться с ней." }, { 13.98, "Послушай, я введу тебя в курс дела..." } } } } },
    [3524] = { d = 34.6, v = "nightelf-female#51", n = { x = 391 }, c = { x = { { 0.00, "Громадные морские твари выбрасываются на пески Тёмного Берега и лежат там, пока не умирают." }, { 6.58, "В последнее время останки этих тварей выносит на берег всё чаще и чаще." }, { 11.86, "Меня послали сюда из Храма Луны для расследования ситуации, но наличие мурлоков у береговой линии затрудняет мою задачу." }, { 20.65, "Одни такие останки лежат на юге от Аубердина, совсем рядом, но вокруг очень много злобных мурлоков из клана Серой Мглы." }, { 29.44, "Не могли бы вы сходить туда и принести мне для изучения кости этой твари?" } } }, t = { d = 27.6, v = "nightelf-female#51", n = { x = 351 }, c = { x = { { 0.00, "Я надеюсь, что мурлоки не слишком досаждали вам, пока вы собирали для нас эти кости!" }, { 5.51, "Я непременно следующим же гиппогрифом доставлю их в Дарнасс." }, { 9.42, "Храм Луны снабдил меня некоторыми средствами, которыми я могла бы расплачиваться за помощь; пожалуйста, примите немного денег вместе с нашей благодарностью." }, { 19.68, "Ваш успех побуждает меня предложить вам возможность и дальше оказывать помощь Храму Луны, если вы заинтересованы в этом..." } } } } },
    [3525] = { d = 35.3, g = 1, v = "human-male", n = { m = 432, f = 433 }, c = { m = { { 0.00, "Рядом с входом ты увидишь идола – свинобразы используют его как жертвенный очаг." }, { 5.25, "Эти твари на самом деле пожирают своих пленников из Степей." }, { 9.22, "Я должен разбить идола, чтобы они более никогда не могли его использовать, но мне потребуется твоя помощь." }, { 16.23, "Сопроводи меня к идолу." }, { 17.80, "Там я проведу ритуал, но при этом я даже не смогу говорить с тобой, не говоря уж о том, чтобы самому защитить себя." }, { 25.28, "Тебе придётся держать оборону, пока я буду проводить ритуал." }, { 29.25, "Если меня убьют раньше, чем я закончу, это будет означать крах всех наших планов." }, { 34.62, "Ты готов?" } }, f = { { 0.00, "Рядом с входом ты увидишь идола – свинобразы используют его как жертвенный очаг." }, { 5.27, "Эти твари на самом деле пожирают своих пленников из Степей." }, { 9.25, "Я должен разбить идола, чтобы они более никогда не могли его использовать, но мне потребуется твоя помощь." }, { 16.27, "Сопроводи меня к идолу." }, { 17.86, "Там я проведу ритуал, но при этом я даже не смогу говорить с тобой, не говоря уж о том, чтобы самому защитить себя." }, { 25.35, "Тебе придётся держать оборону, пока я буду проводить ритуал." }, { 29.33, "Если меня убьют раньше, чем я закончу, это будет означать крах всех наших планов." }, { 34.72, "Ты готова?" } } }, t = { d = 32.6, v = "human-male", n = { x = 335 }, c = { x = { { 0.00, "*Белнистраз исчезает, оставив на месте себя пылающее зарево.*" }, { 5.15, "*Вы видите в пламени очертания огромного крылатого красного дракона.*" }, { 10.91, "*Рокочущий голос Белнистраза наполняет ваше сознание.*" }, { 15.36, "\"Я всегда верил в вашу смелость, смертные." }, { 18.70, "Благодаря тебе кровавым делам, вершимым здесь этими тварями, пришёл конец." }, { 24.49, "Моя вера в мужественность смертных созданий сегодня укрепилась." }, { 29.43, "Прими эту награду – она достойна героя.\"" } } } } },
    [3526] = { d = 37.1, v = "scourge-male#83", n = { x = 407 }, c = { x = { { 0.00, "Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской." }, { 7.79, "Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую." }, { 13.06, "Покори же мир с помощью отборной взрывчатки и фантастических механизмов!" }, { 18.60, "Прочитай этот учебник." }, { 20.42, "Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске." }, { 28.15, "Помни: сделав выбор единожды, ты не сможешь передумать." }, { 32.50, "Поэтому хорошо подумай, прежде чем браться за задание Никса." } } }, t = { d = 23.1, g = 1, v = "goblin-male", n = { m = 248, f = 248 }, c = { m = { { 0.00, "Что же, ты нашёл подходящего учителя!" }, { 2.80, "Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган." }, { 10.69, "Требуется острый ум и верная рука (повторяю: ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела." }, { 19.22, "Держи ушки на макушке, тогда чему-нибудь научишься." } }, f = { { 0.00, "Что же, ты нашла подходящего учителя!" }, { 2.82, "Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган." }, { 10.58, "Требуется острый ум и верная рука (повторяю: ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела." }, { 18.96, "Держи ушки на макушке, тогда чему-нибудь научишься." } } } } },
    [3527] = { d = 37.0, v = "troll-male#77", n = { x = 405 }, c = { x = { { 0.00, "Древнее пророчество Мошару повествует о том, как взять в плен сущность бога Хаккара." }, { 6.34, "Пророчество записали на двух табличках и отнесли в тролльский город Зул'Фаррак, что к западу от Прибамбасска." }, { 14.53, "Принеси мне таблички Мошару!" }, { 16.73, "Первая табличка находится у давно умершего тролля Теки Мученика." }, { 21.76, "Говорят, что его истязатели превратились в скарабеев и до сих пор ползают по его святилищу." }, { 28.65, "Вторая табличка – у гидроманта Велраты, рядом со священным озером Газ'риллы." }, { 34.50, "Добудешь таблички – сразу приходи." } } }, t = { d = 11.8, v = "troll-male#77", n = { x = 95 }, c = { x = { { 0.00, "О, замечательно." }, { 1.59, "Я соединю эти таблички и раскрою их секреты." }, { 6.01, "Я давно твой должник." }, { 8.13, "И, боюсь, мой долг будет только расти." } } } } },
    [3528] = { d = 36.2, v = "troll-male#77", n = { x = 348 }, c = { x = { { 0.00, "Пришло время брать в плен сущность аватары Хаккара." }, { 4.38, "Отнеси яйцо Хаккара в святилище Падшего Бога в Затонувшем храме Азерота." }, { 10.67, "Призови силу яйца и разбуди мёртвого бога." }, { 14.36, "Он пошлёт против тебя своих прислужников." }, { 17.89, "Одолей их и нацеди из них крови Хаккари." }, { 21.35, "Угаси при помощи этой крови вечный огонь, в котором заключён дух Хаккара." }, { 27.64, "Когда пламя погаснет, в мир войдёт аватара Хаккара." }, { 32.02, "Победи его и помести его сущность в яйцо Хаккара." } } }, t = { d = 30.7, g = 1, v = "troll-male#77", n = { m = 301, f = 302 }, c = { m = { { 0.00, "Значит, сущность Хаккара заключена в яйцо!" }, { 3.54, "Смотри, как в Яйце пульсирует жизнь!" }, { 6.48, "Неужели мифы о Хаккаре правда?" }, { 9.06, "Не может быть, ведь в таком случае Хаккар может возродиться." }, { 14.00, "Я буду хранить это яйцо как зеницу ока, чтобы оно не попало в недобрые руки." }, { 20.48, "Наша совместная работа подошла к концу." }, { 23.80, "Ты прикоснулся к легенде, быть может, твои подвиги однажды изменят облик нашего мира." } }, f = { { 0.00, "Значит, сущность Хаккара заключена в яйцо!" }, { 3.38, "Смотри, как в Яйце пульсирует жизнь!" }, { 6.20, "Неужели мифы о Хаккаре правда?" }, { 8.67, "Не может быть, ведь в таком случае Хаккар может возродиться." }, { 13.39, "Я буду хранить это яйцо как зеницу ока, чтобы оно не попало в недобрые руки." }, { 19.59, "Наша совместная работа подошла к концу." }, { 22.76, "Ты прикоснулась к легенде, быть может, твои подвиги однажды изменят облик нашего мира." } } } } },
    [3541] = { d = 38.4, g = 1, v = "orc-female#58", n = { m = 395, f = 396 }, c = { m = { { 0.00, "В Оргриммаре есть у меня скупщик краденого." }, { 3.25, "У него притон в Волоке." }, { 5.08, "Этого скользкого типа нелегко найти, если не знать точно где искать." }, { 10.30, "Запомни: искать следует в одном из самых высоких зданий." }, { 14.64, "Только сделай мне одолжение, не ори на весь Калимдор, где он и чем занимается – это было бы... весьма неприятно для нас обоих." }, { 24.00, "Он готов заплатить очень хорошую цену за табличку Джин'яэль." }, { 28.61, "Не знаю, зачем уж она ему сдалась, но видел бы ты, как у него загорелись глаза, когда я упомянула, что знаю, где её найти!" } }, f = { { 0.00, "В Оргриммаре есть у меня скупщик краденого." }, { 3.31, "У него притон в Волоке." }, { 5.17, "Этого скользкого типа нелегко найти, если не знать точно где искать." }, { 10.48, "Запомни: искать следует в одном из самых высоких зданий." }, { 14.90, "Только сделай мне одолжение, не ори на весь Калимдор, где он и чем занимается – это было бы... весьма неприятно для нас обоих." }, { 24.41, "Он готов заплатить очень хорошую цену за табличку Джин'яэль." }, { 29.10, "Не знаю, зачем уж она ему сдалась, но видела бы ты, как у него загорелись глаза, когда я упомянула, что знаю, где её найти!" } } }, t = { d = 22.6, v = "troll-male", n = { x = 187 }, c = { x = { { 0.00, "Ага, Джедига прислала мне посылку..." }, { 3.56, "Великолепно, я ждал её." }, { 5.73, "Да, Джедига славная бабёнка!" }, { 8.41, "Свирепая как волчица... что может быть лучше?" }, { 12.75, "Как я погляжу, табличка в целости и сохранности." }, { 17.35, "А что это значит?" }, { 19.08, "Значит, посыльный получит на магарыч!" } } } } },
    [3542] = { d = 30.9, v = "orc-female#58", n = { x = 357 }, c = { x = { { 0.00, "Теперь ты отправишься к Андрону Ганту." }, { 2.80, "Он обретается в Подгороде, недалеко от Района Фармацевтов." }, { 6.96, "Этот был более многословен, когда я спросила, зачем ему нужна табличка." }, { 12.22, "Маги Подгорода хотят изучить некоторые тайные заклинания высокорождённых." }, { 17.49, "Они считают, что табличка им в этом поможет." }, { 20.74, "Маркри был очень талантлив в чарах призыва различных существ, особенно элементалей." }, { 26.78, "Отнеси ему табличку Маркри и возвращайся за своей долей." } } }, t = { d = 9.2, v = "scourge-male#83", n = { x = 77 }, c = { x = { { 0.00, "Вот, возьми пару монет..." }, { 2.15, "... купи себе новую броню... или шляпу." }, { 6.31, "Ничего не жаль для хороших посыльных!" } } } } },
    [3561] = { d = 39.6, v = "orc-female#58", n = { x = 433 }, c = { x = { { 0.00, "Последнюю табличку надлежит доставить весьма опасному человеку." }, { 4.72, "Можешь не сомневаться, я доверяю ему куда меньше, чем кому-либо из тех, к кому я тебя отправляла." }, { 11.90, "Верховный маг Ксилем живёт в башне в холмах, возвышающихся над Азшарой." }, { 17.08, "Он человек, однако он не похож на людей, которых мне приходилось встречать... или убивать." }, { 23.73, "Он необычайно властен." }, { 25.39, "Я не смею спросить его, что он собирается делать с табличкой." }, { 29.91, "Он сказал мне, что страж его, Санат, поможет мне попасть в его башню, когда я буду готова предстать перед ним." }, { 38.08, "Ищи Саната на севере." } } }, t = { d = 11.5, v = "human-male", n = { x = 107 }, c = { x = { { 0.00, "О, табличка Саэль'Хай... как давно я мечтал изучить её!" }, { 4.69, "Благодарю тебя." }, { 6.07, "Скажи Джедиге, что я доволен работой." }, { 9.30, "Орк заслужила свою награду." } } } } },
    [3562] = { d = 15.4, v = "named/4046", n = { x = 154 }, c = { x = { { 0.00, "Отнеси это послание Джедиге." }, { 2.38, "Скажи ей, что плата будет ждать её здесь, когда она вернётся." }, { 7.21, "И передай, что её работа меня порадовала." }, { 10.53, "Ступай скорее." }, { 11.76, "Скажи своей госпоже, что я буду ждать её здесь." } } }, t = { d = 23.2, v = "orc-female#58", n = { x = 261 }, c = { x = { { 0.00, "А, отлично." }, { 0.85, "Она поступила вполне разумно." }, { 3.06, "По крайней мере по отношению к тебе." }, { 5.73, "Я побаивалась, что она сделает с тобой что-нибудь неприятное, чтобы наказать меня за высокомерие." }, { 12.77, "Она любит, чтобы к ней являлись лично, а не отправляли мальчиков на побегушках." }, { 18.51, "Похоже, она действительно обрадовалась табличке." }, { 22.03, "Что ж, посмотрим." } } } } },
    [3563] = { d = 16.4, v = "troll-male", n = { x = 167 }, c = { x = { { 0.00, "Отнеси это послание Джедиге." }, { 2.34, "Скажи ей, что я доволен её работой." }, { 5.11, "Скажи, чтобы скорее возвращалась в Оргриммар – Джес'римон достойно наградит её." }, { 11.37, "Передай ей это, и, возможно, впредь я буду давать тебе поручения." } } }, t = { d = 19.0, v = "orc-female#58", n = { x = 190 }, c = { x = { { 0.00, "Судя по этому письму, Джес'римон более чем доволен... пожалуй, даже слишком." }, { 6.05, "Может, когда-нибудь я найду время показать ему, как я ценю его ухаживания." }, { 11.95, "Что ж, теперь у меня есть хотя бы одна причина задержаться в Азшаре." }, { 17.29, "Вот, забирай свою долю." } } } } },
    [3564] = { d = 7.0, v = "scourge-male#83", n = { x = 46 }, c = { x = { { 0.00, "Вот" }, { 0.32, "держи" }, { 1.66, "Это для Джедиги." }, { 3.96, "И ты это," }, { 4.83, "заходи, если что!" } } }, t = { d = 26.2, g = 1, v = "orc-female#58", n = { m = 243, f = 246 }, c = { m = { { 0.00, "Отлично... ого, это ещё что!" }, { 2.31, "Ха-ха!" }, { 2.88, "Что ты сказал ему, когда отдавал табличку?" }, { 6.35, "Он заплатил нам едва ли не дважды сверх уговорённого!" }, { 10.46, "Нет, я конечно, не жалуюсь..." }, { 12.76, "Ты сказал ему, что я изменила условия сделки?" }, { 16.44, "Или этот пьянчуга опять шары залил и не соображал, что делает?" }, { 21.56, "Ну, уже неважно." }, { 22.93, "Вот, держи свою долю – с премией!" } }, f = { { 0.00, "Отлично... ого, это ещё что!" }, { 2.35, "Ха-ха!" }, { 2.94, "Что ты сказала ему, когда отдавала табличку?" }, { 6.62, "Он заплатил нам едва ли не дважды сверх уговорённого!" }, { 10.81, "Нет, я конечно, не жалуюсь..." }, { 13.16, "Ты сказала ему, что я изменила условия сделки?" }, { 16.98, "Или этот пьянчуга опять шары залил и не соображал, что делает?" }, { 22.20, "Ну, уже неважно." }, { 23.60, "Вот, держи свою долю – с премией!" } } } } },
    [3565] = { d = 10.2, v = "human-male", n = { x = 86 }, c = { x = { { 0.00, "Что ещё?" }, { 0.78, "Ах да, оплата." }, { 2.17, "Конечно." }, { 3.04, "Вот, возьми и выметайся." }, { 5.38, "Уверен, Джедига ждёт не дождётся твоего возвращения." } } }, t = { d = 18.6, v = "orc-female#58", n = { x = 181 }, c = { x = { { 0.00, "Что, в самом деле не случилось ничего неприятного?" }, { 4.05, "И он отдал тебе деньги не торгуясь?" }, { 6.94, "Ушам не верю..." }, { 8.24, "Я, честно признаться, ожидала какого-то подвоха." }, { 12.14, "Похоже, с ним всё же можно иметь дело." }, { 15.25, "Вот, держи свою награду." }, { 17.27, "Спасибо за помощь." } } } } },
    [3566] = { d = 9.0, v = "dwarf-male", n = { x = 58 }, c = { x = { { 0.00, "Это... была... ловушка..." }, { 2.57, "Прости... меня..." }, { 4.34, "Убей предателя..." }, { 6.12, "Отомсти за нас..." }, { 7.80, "За Ториуса..." } } }, t = { d = 29.2, v = "dwarf-male", n = { x = 299 }, c = { x = { { 0.00, "*Ториус бледнеет.*" }, { 1.60, "Этого не может быть..." }, { 3.58, "Мой единокровный брат!" }, { 5.47, "Неужели он мог это сделать?!" }, { 7.92, "*Лицо Ториуса искажает ярость*" }, { 10.56, "Он предал меня, он предал Стальгорн!" }, { 13.25, "Видимо, влияние Древних Богов ещё сильно в этих землях." }, { 17.50, "Боюсь, если даже мой брат – некогда благородный и уважаемый человек – так легко поддался воле Рагнароса, никто из нас не может чувствовать себя в безопасности!" } } } } },
    [3567] = { t = { d = 12.7, g = 1, v = "nightelf-female#52", n = { x = 143 }, c = { m = { { 0.00, "Хочешь полюбоваться видом с вершины одного из Колоссов-близнецов?" }, { 4.38, "Я могу отправить тебя туда, путник." }, { 6.84, "Только подумай заранее, как будешь спускаться." }, { 9.96, "Путь туда – только в одну сторону." } }, f = { { 0.00, "Хочешь полюбоваться видом с вершины одного из Колоссов-близнецов?" }, { 4.38, "Я могу отправить тебя туда, путница." }, { 7.33, "Только подумай заранее, как будешь спускаться." }, { 10.45, "Путь туда – только в одну сторону." } } } } },
    [3568] = { d = 32.9, v = "scourge-male", n = { x = 315 }, c = { x = { { 0.00, "Видишь эту несчастную тауренку у меня за спиной?" }, { 4.55, "Она недавно побывала в Азшаре." }, { 7.15, "Среди руин Эльдарата она была ранена в бою с нагами." }, { 11.69, "Отбившись от них, она решила отдохнуть на берегу и попила водички из приливной заводи." }, { 18.82, "Теперь её тошнит... помимо всего прочего." }, { 22.32, "Мне нужно выяснить, что она пила." }, { 25.14, "Возьми этот ящик, в нём несколько помеченных фиалов." }, { 29.53, "Наполни их из разных заводей и возвращайся." } } }, t = { d = 31.8, g = 1, v = "scourge-male", n = { m = 243, f = 244 }, c = { m = { { 0.00, "Чудесно." }, { 0.91, "Ты успел вернуться до её гибели." }, { 4.20, "Славно, славно." }, { 5.85, "Значит, пора приступать." }, { 8.41, "Я некоторое время изучал симптомы её болезни, и теперь дело совсем плохо." }, { 15.99, "Удивительно, как она на ногах держится." }, { 20.02, "Её уже три или четыре раза вырвало... запах просто чудесный." }, { 26.32, "Дай-ка я состряпаю что-нибудь для нашей... подруги." } }, f = { { 0.00, "Чудесно." }, { 0.93, "Ты успела вернуться до её гибели." }, { 4.35, "Славно, славно." }, { 6.01, "Значит, пора приступать." }, { 8.60, "Я некоторое время изучал симптомы её болезни, и теперь дело совсем плохо." }, { 16.28, "Удивительно, как она на ногах держится." }, { 20.35, "Её уже три или четыре раза вырвало... запах просто чудесный." }, { 26.74, "Дай-ка я состряпаю что-нибудь для нашей... подруги." } } } } },
    [3569] = { d = 7.4, v = "scourge-male", n = { x = 66 }, c = { x = { { 0.00, "Отнеси эликсир Терсе – вдруг он ей поможет?" }, { 3.80, "Пока она не выпьет его, точно не скажешь." } } }, t = { d = 20.0, v = "tauren-female#72", n = { x = 196 }, c = { x = { { 0.00, "Химик Карабос – само гостеприимство... даже не по себе стало." }, { 5.06, "Но если он говорит, что есть шанс излечиться, выбора нет." }, { 9.60, "Искать другие лекарства нет времени." }, { 12.60, "Ни жрецы, ни шаманы не смогли мне помочь." }, { 15.98, "Будем надеяться, что Мать-земля сохранит мою душу." } } } } },
    [3570] = { t = { d = 14.0, v = "scourge-male", n = { x = 131 }, c = { x = { { 0.00, "Я и не мечтал, что эликсир подействует так быстро." }, { 4.43, "Спасибо." }, { 5.23, "Я немедленно возьмусь за остальные образцы." }, { 9.09, "Уверен, скоро они пригодятся леди Сильване и Отрёкшимся." } } } } },
    [3601] = { d = 43.4, v = "goblin-male#65", n = { x = 459 }, c = { x = { { 0.00, "Ким'джаель оскорблён до глубины души!" }, { 2.81, "Знаешь, что на самом деле Ким'джаель значит для эльфов крови?" }, { 7.55, "Я для них всего лишь букашка!" }, { 9.74, "Маленькое безвредное создание, на которое можно и наступить – не жалко!" }, { 15.17, "Они наняли меня, чтобы я обшарил для них место, где, как они сказали, спрятано сокровище." }, { 22.03, "Ну ты понимаешь, при слове \"сокровище\" я утратил бдительность и купился на их посулы!" }, { 28.41, "Конечно же, они предали меня и даже пытались прикончить!" }, { 32.80, "Никогда нельзя верить мерзким эльфам крови!" }, { 36.23, "Мне удалось уйти живым, но у негодяев осталось всё моё снаряжение!" }, { 41.24, "Пожалуйста, забери его у них!" } } }, t = { d = 17.6, v = "goblin-male#65", n = { x = 153 }, c = { x = { { 0.00, "Ха!" }, { 0.32, "Так им и надо!" }, { 1.58, "Вот это круто!" }, { 2.92, "Теперь-то они знают, что значит предавать своих партнёров!" }, { 8.05, "Особенно гоблинов!" }, { 9.71, "Ну, теперь о твоей награде... я же сказал, значит, заплачу." }, { 14.92, "Вот, держи... может, пригодится." } } } } },
    [3602] = { d = 38.2, v = "nightelf-male#55", n = { x = 453 }, c = { x = { { 0.00, "Древние скальные великаны из южных регионов Азшары для поддержания существования поглощают камни и каменные образования." }, { 8.59, "Продуктом переработки такой \"пищи\" являются чрезвычайно податливые, но при этом необычайно прочные кристаллы, известные как азшарит." }, { 18.03, "На южной гряде находятся целые залежи азшарита, однако его почти никому не удавалось добыть из-за чрезвычайной жестокости великанов." }, { 27.66, "Тебе следует отправиться на юг и раздобыть азшарита столько, чтобы его хватило для создания оружия." }, { 34.83, "Мои гончие скверны помогут в розыске кристаллов." } } }, t = { d = 8.3, v = "nightelf-male#55", n = { x = 91 }, c = { x = { { 0.00, "Твои задачи в Азшаре завершены." }, { 2.52, "Теперь я должен подготовить всё необходимое для следующего шага твоего пути." } } } } },
    [3621] = { d = 30.2, v = "nightelf-male#55", n = { x = 329 }, c = { x = { { 0.00, "Оружие готово к отковке." }, { 1.90, "Тебе следует отнести закалённый азшарит к тому, кто может обуздать энергию скверны." }, { 8.21, "В Тернистой долине живёт такой кузнец." }, { 11.12, "Гальван Древний, глава Ордена Мифрила, создаст оружие по твоему заказу." }, { 16.62, "Ты можешь найти его становище между Зул'Гурубом и холмом Мош'Огг." }, { 21.64, "Пусть решительность и вера помогут тебе пройти это испытание." }, { 26.32, "А если ты погибнешь, знай, что твой Бог тебе улыбается." } } }, t = { d = 14.3, v = "dwarf-male", n = { x = 172 }, c = { x = { { 0.00, "Могу лишь вообразить, через что тебе пришлось пройти, чтобы раздобыть эти материалы." }, { 5.92, "Немногим удавалось вернуться живыми из Азшары, не говоря уж о том, чтобы встретиться лицом к лицу с полубогами и великанами." } } } } },
    [3625] = { d = 24.6, v = "dwarf-male", n = { x = 298 }, c = { x = { { 0.00, "Для создания оружия необходимо время." }, { 2.66, "Вдобавок, ты можешь использовать силу оружия Проклятия Скверны лишь раз в три минуты." }, { 8.61, "Длительность действия, ослабляющего Разелиха Осквернителя и его приспешников, может быть различной." }, { 15.52, "Именно поэтому следует высвобождать силу Проклятия Скверны лишь в нужный момент!" }, { 21.22, "Теперь дай мне время на создание оружия для тебя." } } }, t = { d = 7.9, v = "dwarf-male", n = { x = 85 }, c = { x = { { 0.00, "*Гальван вытирает пот со лба.*" }, { 2.40, "Никогда ещё не существовало более подходящего оружия для убиения демона." } } } } },
    [3626] = { d = 12.6, v = "dwarf-male", n = { x = 145 }, c = { x = { { 0.00, "Час искупления близок." }, { 1.65, "Тебе следует вернуться в Выжженные земли вместе с твоим новообретенным оружием и поговорить с Павшим героем Орды о том, как достичь твоей главной цели." } } }, t = { d = 10.2, v = "orc-male", n = { x = 101 }, c = { x = { { 0.00, "Похоже, сражения закалили тебя." }, { 2.75, "Но достаточно ли в тебе силы и решимости, чтобы противостоять Разелиху и его приспешникам?" } } } } },
    [3627] = { d = 21.8, v = "orc-male", n = { x = 214 }, c = { x = { { 0.00, "Чтобы добраться до Осквернителя, тебе следует сначала уничтожить троицу силы и собрать осколки амулета." }, { 8.68, "Когда у тебя в руках будут все три осколка, возвращайся ко мне, и я скажу, что делать дальше." }, { 16.38, "Иди!" }, { 16.83, "В Выжженные земли!" }, { 18.40, "Севина, Аллистарий и Грол должны погибнуть!" } } }, t = { d = 13.0, v = "orc-male", n = { x = 115 }, c = { x = { { 0.00, "Амулет Разелиха Осквернителя наконец-то собран воедино." }, { 5.09, "Но Разелих чует, что цепь его власти порвана." }, { 9.27, "Он знает, что ты собираешься убить его..." } } } } },
    [3628] = { d = 40.1, v = "orc-male", n = { x = 426 }, c = { x = { { 0.00, "Логово Разелиха находится на вершине самой высокой горы Выжженных земель." }, { 5.83, "Единственный способ достигнуть логова – это использовать телепортирующие руны поблизости от горы." }, { 13.41, "Пока у тебя есть этот амулет, ты свободно можешь переместиться в логово." }, { 19.10, "А достигнув логова, призови зверя." }, { 21.84, "Ключ к этому – твой амулет." }, { 23.94, "Используй его на Алтаре Осквернителя." }, { 26.89, "Если одолеешь Осквернителя, принеси его рог." }, { 30.40, "Он станет символом надежды для всех, кто увидит его – доказательством того, что в этом раздираемом войнами мире ещё есть герои!" } } }, t = { d = 9.1, v = "orc-male", n = { x = 86 }, c = { x = { { 0.00, "Сегодняшний день останется в памяти навеки." }, { 4.05, "Демонический повелитель Выжженных земель наконец-то пал!" } } } } },
    [3629] = { d = 42.3, v = "gnome-male", n = { x = 474 }, c = { x = { { 0.00, "В инженерном деле есть две дисциплины: гномская и гоблинская." }, { 4.40, "Я – честный учитель, и только поэтому упомянул гоблинское инженерное дело." }, { 9.85, "Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер." }, { 21.27, "Почитай этот справочник." }, { 23.10, "Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск." }, { 30.13, "Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого." } } }, t = { d = 23.0, g = 1, v = "goblin-male", n = { m = 249, f = 249 }, c = { m = { { 0.00, "Что же, ты нашёл подходящего учителя!" }, { 2.72, "Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган." }, { 10.42, "Требуется острый ум и верная рука – ключевое слово «верная» – чтобы освоить премудрости гоблинского инженерного дела." }, { 19.34, "Держи ушки на макушке, и чему-нибудь научишься." } }, f = { { 0.00, "Что же, ты нашла подходящего учителя!" }, { 2.80, "Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган." }, { 10.53, "Требуется острый ум и верная рука – ключевое слово «верная» – чтобы освоить премудрости гоблинского инженерного дела." }, { 19.48, "Держи ушки на макушке, и чему-нибудь научишься." } } } } },
    [3630] = { d = 35.0, v = "gnome-male", n = { x = 426 }, c = { x = { { 0.00, "В инженерном деле есть две дисциплины: гномская и гоблинская." }, { 4.18, "Гномское инженерное дело пока что зарекомендовало себя лучшей из двух." }, { 9.06, "В ней речь идёт о конструировании чудесных штучек и приспособлений, которые украшают жизнь!" }, { 15.18, "Почитай этот справочник." }, { 16.93, "Если ты захочешь больше узнать о гномском инженерном деле, то отнеси его мехмастеру Замыкальцу в Стальгорн." }, { 24.42, "Помни – выбор твой не подлежит пересмотру, и изучить другую дисциплину ты не сможешь, так что удостоверься в своём выборе, прежде чем выполнять его задание!" } } }, t = { d = 21.7, g = 1, v = "gnome-male", n = { m = 257, f = 257 }, c = { m = { { 0.00, "А, молодой инженер, заинтересованный в освоении единственно верной школы инженерного дела!" }, { 6.16, "Что ж, дружище, прости мне мою мелодраматичность." }, { 9.48, "Пока ситуация наша остаётся тяжёлой, день всегда кажется светлее, когда встречаешь собрата по ремеслу, откликнувшегося на трубный призыв истинного инженерного дела!" } }, f = { { 0.00, "А, молодая инженер, заинтересованная в освоении единственно верной школы инженерного дела!" }, { 6.51, "Что ж, подруга, прости мне мою мелодраматичность." }, { 10.03, "Пока ситуация наша остаётся тяжёлой, день всегда кажется светлее, когда встречаешь собрата по ремеслу, откликнувшегося на трубный призыв истинного инженерного дела!" } } } } },
    [3631] = { d = 20.6, g = 1, v = "orc-male", n = { m = 187, f = 188 }, c = { m = { { 0.00, "Хммм." }, { 0.46, "Я сказал бы, что ты ещё не готов, но тут не мне решать." }, { 5.01, "Страад думает иначе, а решает он... пока." }, { 8.63, "Он хочет с тобой говорить, причём срочно." }, { 12.17, "Он пока всё ещё в Степях над Кабестаном, в своей маленькой башне со своими учениками." }, { 19.41, "Долго не тяни." } }, f = { { 0.00, "Хммм." }, { 0.46, "Я сказал бы, что ты ещё не готова, но тут не мне решать." }, { 5.04, "Страад думает иначе, а решает он... пока." }, { 8.64, "Он хочет с тобой говорить, причём срочно." }, { 12.15, "Он пока всё ещё в Степях над Кабестаном, в своей маленькой башне со своими учениками." }, { 19.34, "Долго не тяни." } } }, t = { d = 16.1, g = 1, v = "human-male#50", n = { m = 176, f = 177 }, c = { m = { { 0.00, "Значит, ты снова решил пожаловать меня своим визитом." }, { 4.00, "Очень мило с твоей стороны." }, { 6.10, "Мои помощники все гадали – придёшь или нет?" }, { 9.25, "Я говорил им – несомненно, придёт." }, { 11.67, "Когда речь заходит о могуществе, летишь как мотылёк на свечу." } }, f = { { 0.00, "Значит, ты снова решила пожаловать меня своим визитом." }, { 4.09, "Очень мило с твоей стороны." }, { 6.20, "Мои помощники все гадали – придёшь или нет?" }, { 9.37, "Я говорил им – несомненно, придёт." }, { 11.81, "Когда речь заходит о могуществе, летишь как мотылёк на свечу." } } } } },
    [3632] = { d = 39.2, v = "gnome-male", n = { x = 458 }, c = { x = { { 0.00, "На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское." }, { 6.51, "Гномская намного сильнее!" }, { 8.40, "Она занимается конструированием чудесных штучек и устройств, которые делают лучше нашу жизнь!" }, { 15.18, "Прочтите эту инструкцию." }, { 17.00, "Если вы желаете узнать побольше о гномском инженерном деле, отнесите этот справочник мехмастеру Замыкальцу – он здесь, в Стальгорне." }, { 26.51, "Помните: если выберете гномское инженерное дело, то это с концами, другим направлением вы заниматься не сможете, так что подумайте хорошенько, прежде чем выполнить его поручение!" } } }, t = { d = 17.4, g = 1, v = "gnome-male", n = { m = 209, f = 209 }, c = { m = { { 0.00, "А, юный инженер желает изучать единственное истинное направление в инженерном деле!" }, { 6.01, "Простите мне мою горячность, любезный друг." }, { 9.12, "В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!" } }, f = { { 0.00, "А, юная инженер желает изучать единственное истинное направление в инженерном деле!" }, { 6.01, "Простите мне мою горячность, любезный друг." }, { 9.12, "В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!" } } } } },
    [3633] = { d = 36.6, v = "goblin-male#65", n = { x = 407 }, c = { x = { { 0.00, "Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской." }, { 7.69, "Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую." }, { 12.89, "Покори же мир с помощью отборной взрывчатки и фантастических механизмов!" }, { 18.36, "Прочитай этот учебник." }, { 20.16, "Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске." }, { 27.78, "Помни: сделав выбор единожды, ты не сможешь передумать." }, { 32.08, "Поэтому хорошо подумай, прежде чем браться за задание Никса." } } }, t = { d = 23.8, g = 1, v = "goblin-male", n = { m = 249, f = 249 }, c = { m = { { 0.00, "Что же, ты нашёл подходящего учителя!" }, { 2.73, "Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган." }, { 10.46, "Требуется острый ум и верная рука – ключевое слово «верная» – чтобы освоить премудрости гоблинского инженерного дела." }, { 19.41, "Держи ушки на макушке, и чему-нибудь научишься." } }, f = { { 0.00, "Что же, ты нашла подходящего учителя!" }, { 2.90, "Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган." }, { 10.89, "Требуется острый ум и верная рука – ключевое слово «верная» – чтобы освоить премудрости гоблинского инженерного дела." }, { 20.16, "Держи ушки на макушке, и чему-нибудь научишься." } } } } },
    [3634] = { d = 44.7, v = "goblin-male#65", n = { x = 498 }, c = { x = { { 0.00, "На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское." }, { 6.82, "Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле." }, { 14.39, "Оно занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают." }, { 22.43, "Прочти эту инструкцию." }, { 24.21, "Если ты желаешь узнать побольше о гномском инженерном деле, отнеси этот справочник мехмастеру Замыкальцу в Стальгорн." }, { 33.14, "Помни: выбрав гномское инженерное дело, ты не сможешь заниматься другим направлением, так что подумай хорошенько, прежде чем выполнить поручение Замыкальца!" } } }, t = { d = 17.8, g = 1, v = "gnome-male", n = { m = 209, f = 209 }, c = { m = { { 0.00, "А, юный инженер желает изучать единственное истинное направление в инженерном деле!" }, { 6.01, "Простите мне мою горячность, любезный друг." }, { 9.12, "В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!" } }, f = { { 0.00, "А, юная инженер желает изучать единственное истинное направление в инженерном деле!" }, { 6.12, "Простите мне мою горячность, любезный друг." }, { 9.28, "В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!" } } } } },
    [3635] = { d = 45.8, v = "scourge-male#83", n = { x = 494 }, c = { x = { { 0.00, "На высоких уровнях инженерное дело расходится на два направления: гномское и гоблинское." }, { 6.80, "Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле." }, { 14.58, "Гномы занимаются конструированием разных штучек и устройств, которые должны изменить мир, но редко работают." }, { 22.99, "Прочти этот учебник." }, { 24.67, "Если ты хочешь научиться делать металлические пресс-папье, отнеси его Оглторпу Обнотикусу в Пиратскую бухту." }, { 33.15, "Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько, прежде чем выполнить поручение Оглторпа!" } } }, t = { d = 30.2, g = 1, v = "gnome-male", n = { m = 334, f = 335 }, c = { m = { { 0.00, "Значит, тебе захотелось поучиться гномскому инженерному делу?" }, { 4.59, "Что ж, я очень подходящий гном." }, { 6.85, "Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решётку." }, { 16.28, "Мы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней." }, { 25.99, "Если ты – способный ученик, я обучу тебя всему, что знаю." } }, f = { { 0.00, "Значит, тебе захотелось поучиться гномскому инженерному делу?" }, { 4.58, "Что ж, я очень подходящий гном." }, { 6.83, "Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решётку." }, { 16.25, "Мы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней." }, { 25.93, "Если ты – способная ученица, я обучу тебя всему, что знаю." } } } } },
    [3636] = { d = 37.6, v = "human-male#170", n = { x = 364 }, c = { x = { { 0.00, "Плеть постоянно досаждает силам Альянса." }, { 3.49, "Думаю, ты знаешь об этом не хуже меня." }, { 6.90, "В последнее время нам удалось сделать пару интересных находок." }, { 12.33, "В Степях есть жуткие заросли терновника, называемые Курганы Иглошкурых." }, { 18.45, "Сначала казалось, что там обитают только иглогривы, но теперь выясняется, что в этих зарослях гнездятся самые разнообразные чудовища." }, { 29.85, "Управляет ими лич по имени Амненнар Хладовей." }, { 33.80, "Во имя Света!" }, { 35.04, "Изгони зло с холмов Иглошкурых!" } } }, t = { d = 8.7, v = "human-male#170", n = { x = 81 }, c = { x = { { 0.00, "Спасибо." }, { 0.80, "Теперь Плеть подумает дважды, прежде чем выпускать на нас своих гадов." }, { 7.04, "Да хранит тебя Свет!" } } } } },
    [3637] = { d = 45.1, v = "goblin-male#65", n = { x = 494 }, c = { x = { { 0.00, "На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское." }, { 6.90, "Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле." }, { 14.56, "Оно занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают." }, { 22.70, "Прочти этот учебник." }, { 24.36, "Если ты хочешь научиться делать металлические пресс-папье, отнеси его Оглторпу Обнотикусу в Пиратскую бухту." }, { 32.71, "Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько прежде, чем выполнить поручение Оглторпа!" } } }, t = { d = 31.3, g = 1, v = "gnome-male", n = { m = 334, f = 335 }, c = { m = { { 0.00, "Значит, тебе захотелось поучиться гномскому инженерному делу?" }, { 4.62, "Что ж, я очень подходящий гном." }, { 6.90, "Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решётку." }, { 16.41, "Мы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней." }, { 26.19, "Если ты – способный ученик, я обучу тебя всему, что знаю." } }, f = { { 0.00, "Значит, тебе захотелось поучиться гномскому инженерному делу?" }, { 4.75, "Что ж, я очень подходящий гном." }, { 7.08, "Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решётку." }, { 16.85, "Мы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней." }, { 26.89, "Если ты – способная ученица, я обучу тебя всему, что знаю." } } } } },
    [3638] = { d = 41.8, v = "goblin-male", n = { x = 480 }, c = { x = { { 0.00, "Гоблинское инженерное дело нацелено на получение высоких прибылей и огромной взрывной силы!" }, { 6.71, "Наши чертежи позволяют нам создавать мощные бомбы и прочее оружие, и в справочнике, что у тебя в руках, об этом написано." }, { 15.59, "Но этот справочник также содержит древнюю клятву хранить наши чертежи в тайне." }, { 21.45, "Как только ты займёшься гоблинским инженерным делом, то всё." }, { 25.72, "Доступа к гномскому инженерному делу не будет." }, { 29.14, "Если ты по-прежнему хочешь заняться гоблинским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне." }, { 39.67, "Но сначала подумай хорошенько." } } }, t = { d = 22.0, g = 1, v = "goblin-male", n = { m = 269, f = 270 }, c = { m = { { 0.00, "Добро пожаловать в клуб!" }, { 1.71, "Скоро ты получишь доступ к наиболее передовым разработкам во всём Азероте." }, { 6.90, "Теперь, когда ты решил посвятить себя этому искусству, пора познакомиться с гоблинским инженерным делом." }, { 14.30, "С этого мгновения мы будем помогать тебе разрабатывать план предельного раскрытия талантов гоблинского инженера!" } }, f = { { 0.00, "Добро пожаловать в клуб!" }, { 1.65, "Скоро ты получишь доступ к наиболее передовым разработкам во всём Азероте." }, { 6.68, "Теперь, когда ты решила посвятить себя этому искусству, пора познакомиться с гоблинским инженерным делом." }, { 13.91, "С этого мгновения мы будем помогать тебе разрабатывать план предельного раскрытия талантов гоблинского инженера!" } } } } },
    [3639] = { d = 37.6, g = 1, v = "goblin-male", n = { m = 444, f = 445 }, c = { m = { { 0.00, "Как твой наставник, я желаю увидеть образцы твоей работы." }, { 4.14, "Ты опытный инженер, тут вопросов нет." }, { 6.80, "Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гоблинскоориентированную технику для будущих трудов." }, { 15.60, "Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек плотного динамита и пять взрывоопасных овец – и смотри сам не подорвись!" }, { 26.16, "Сдай мне эти предметы, и я выдам твой собственный членский билет гильдии гоблинов-инженеров – он нужен для допуска ко всем наставникам гоблинского инженерного дела!" } }, f = { { 0.00, "Как твой наставник, я желаю увидеть образцы твоей работы." }, { 4.07, "Ты опытный инженер, тут вопросов нет." }, { 6.67, "Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гоблинскоориентированную технику для будущих трудов." }, { 15.32, "Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек плотного динамита и пять взрывоопасных овец – и смотри сама не подорвись!" }, { 25.81, "Сдай мне эти предметы, и я выдам твой собственный членский билет гильдии гоблинов-инженеров – он нужен для допуска ко всем наставникам гоблинского инженерного дела!" } } }, t = { d = 30.1, v = "goblin-male", n = { x = 387 }, c = { x = { { 0.00, "Вот твой первый членский билет гильдии гоблинов-инженеров!" }, { 3.88, "Билет оплачивается вперёд за четырнадцать дней." }, { 6.93, "Через две недели срок действия истечёт." }, { 9.50, "Когда это произойдёт, то для продления заплати очередную пошлину любому наставнику гоблинского инженерного дела." }, { 16.90, "Без билета твоё членство будет временно приостановлено, и ты не будешь иметь доступа к новым чертежам." }, { 23.65, "Это никак не повлияет на уже обретённые знания: если уж стал гоблинским инженером, то это навсегда." } } } } },
    [3640] = { d = 39.0, v = "gnome-male", n = { x = 481 }, c = { x = { { 0.00, "Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам!" }, { 6.16, "Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у вас в руках, об этом написано." }, { 15.09, "Но этот справочник также содержит древнюю клятву хранить наши чертежи в тайне." }, { 20.58, "Как только вы займётесь гномским инженерным делом, то всё." }, { 24.46, "Доступа к гоблинскому инженерному делу не будет." }, { 27.78, "Если вы по-прежнему хотите заняться гномским инженерным делом, подпишите этот документ о пожизненном неразглашении тайн и снова обратитесь ко мне." }, { 37.70, "Хорошенько подумайте." } } }, t = { d = 20.6, v = "gnome-male", n = { x = 269 }, c = { x = { { 0.00, "Добро пожаловать в клуб!" }, { 1.59, "Скоро вы получите доступ к наиболее передовым разработкам во всём Азероте." }, { 6.41, "Теперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела." }, { 13.23, "С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!" } } } } },
    [3641] = { d = 34.0, v = "gnome-male", n = { x = 414 }, c = { x = { { 0.00, "Как ваш наставник, я желаю увидеть образцы вашей работы." }, { 3.96, "Вы опытный инженер, тут вопросов нет." }, { 6.54, "Но я надеюсь проанализировать ваши работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов." }, { 15.15, "Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени." }, { 22.76, "Сдайте мне эти предметы, и я выдам вам ваш собственный членский билет гильдии гномов-инженеров – он нужен для допуска ко всем наставникам гномского инженерного дела!" } } }, t = { d = 30.6, v = "gnome-male", n = { x = 385 }, c = { x = { { 0.00, "Вот ваш первый членский билет гильдии гномов-инженеров!" }, { 3.76, "Билет оплачивается вперёд за четырнадцать дней." }, { 6.86, "Через две недели срок действия истечёт." }, { 9.47, "Когда это произойдёт, вы заплатите очередную пошлину любому наставнику гномской инженерии и получите продление." }, { 16.94, "Без билета ваше членство будет временно приостановлено, и вы не будете иметь доступа к новым чертежам." }, { 23.86, "Это никак не повлияет на уже обретённые вами знания: если уж стал гномским инженером, то это навсегда." } } } } },
