    [3644] = { t = { d = 24.9, v = "goblin-male", n = { x = 321 }, c = { x = { { 0.00, "Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых." }, { 9.60, "Как только ты заплатишь пошлину, то немедленно получишь новый членский билет." }, { 14.76, "Это даст тебе доступ к гоблинским чертежам соответствующих наставников." }, { 19.50, "Билет будет действителен две недели, по истечении которых придётся снова заплатить." } } } } },
    [3645] = { t = { d = 24.3, v = "gnome-male", n = { x = 317 }, c = { x = { { 0.00, "Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых." }, { 9.36, "Как только ты заплатишь пошлину, то немедленно получишь новый членский билет." }, { 14.45, "Это даст тебе доступ к гномским чертежам соответствующих наставников." }, { 19.01, "Билет будет действителен две недели, по истечении которых придётся снова заплатить." } } } } },
    [3646] = { t = { d = 30.2, v = "goblin-male", n = { x = 373 }, c = { x = { { 0.00, "Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых." }, { 9.94, "Как только ты заплатишь пошлину, то немедленно получишь новый членский билет." }, { 15.28, "Это даст тебе доступ к гоблинским чертежам соответствующих наставников." }, { 20.18, "Билет будет действителен две недели, по истечении которых придётся снова заплатить!" }, { 25.89, "Если ты хочешь иметь доступ к чертежам, не просрочивай платежи." } } } } },
    [3647] = { t = { d = 24.1, v = "gnome-male", n = { x = 317 }, c = { x = { { 0.00, "Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых." }, { 9.27, "Как только ты заплатишь пошлину, то немедленно получишь новый членский билет." }, { 14.31, "Это даст тебе доступ к гномским чертежам соответствующих наставников." }, { 18.82, "Билет будет действителен две недели, по истечении которых придётся снова заплатить." } } } } },
    [3661] = { d = 29.8, v = "nightelf-male#55", n = { x = 326 }, c = { x = { { 0.00, "Дикие совухи – очень непредсказуемые существа." }, { 3.49, "Они могут быть мягкими и пушистыми, но если что-то дорогое для них окажется под угрозой, в них проснётся настоящий зверь!" }, { 12.34, "Говорят, что этих животных создала сама Элуна, и я хочу узнать, правда это, или нет." }, { 18.78, "Много диких совухов обитает во Внутренних землях – целые популяции примитивных, злобных существ." }, { 26.02, "Не хочешь отправиться туда и принести мне их перьев?" } } }, t = { d = 23.8, v = "nightelf-male#55", n = { x = 263 }, c = { x = { { 0.00, "Спасибо за перья." }, { 1.35, "Что вам удалось узнать о дикосовухах?" }, { 4.12, "Возможно, эти перья помогут узнать больше и сказать, являются ли они кровожадными монстрами или просто одичавшими питомцами." }, { 13.57, "Надеюсь, когда-нибудь я узнаю правду." }, { 16.41, "Я продолжу свои исследования, а вы, пожалуйста, по истечении некоторого времени зайдите ко мне снова." } } } } },
    [3681] = { d = 22.6, g = 1, v = "dwarf-male", n = { x = 258 }, c = { m = { { 0.00, "Я вынужден прервать твоё путешествие, герой." }, { 3.12, "Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения." }, { 9.55, "Если бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов." }, { 17.31, "Найди Даториана Ралла в Штормграде." }, { 19.85, "Он обучает паладинов в Соборе Света." } }, f = { { 0.00, "Я вынужден прервать твоё путешествие, героиня." }, { 3.26, "Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения." }, { 9.72, "Если бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов." }, { 17.52, "Найди Даториана Ралла в Штормграде." }, { 20.08, "Он обучает паладинов в Соборе Света." } } }, t = { d = 3.0, g = 1, v = "human-male", n = { x = 26 }, c = { m = { { 0.00, "Добро пожаловать в Собор Света, герой." } }, f = { { 0.00, "Добро пожаловать в Собор Света, героиня." } } } } },
    [3701] = { d = 24.1, v = "dwarf-female#34", n = { x = 255 }, c = { x = { { 0.00, "Отправляйтесь в дымящиеся руины Тауриссана в Пылающих степях и соберите как можно больше информации." }, { 7.45, "Говорят, все руины просто усыпаны таинственными реликвиями." }, { 13.34, "Возможно, именно там и стоит начать поиски." }, { 16.68, "Опасайтесь тауриссанских стражей-убийц, что стерегут руины, охраняя все тайны, какие там могут быть." } } }, t = { d = 8.6, v = "dwarf-female#34", n = { x = 78 }, c = { x = { { 0.00, "Ох ты!" }, { 0.60, "Эта информация многое объясняет касательно Тауриссана." }, { 5.81, "Но предстоит узнать ещё больше!" } } } } },
    [3702] = { d = 5.4, v = "dwarf-female#34", n = { x = 58 }, c = { x = { { 0.00, "Не желаете ли услышать краткий обзор истории дворфов Чёрного Железа?" } } }, t = { d = 1.0, v = "dwarf-female#34", n = { x = 9 }, c = { x = { { 0.00, "Продолжим?" } } } } },
    [3721] = { t = { d = 36.2, g = 1, v = "gnome-male", n = { m = 392, f = 396 }, c = { m = { { 0.00, "Ты вернул трёх моих самонаводящихся роботов KKX!" }, { 4.06, "Ты сделал куда больше, чем требовалось, поэтому за всю твою помощь я дам тебе кое-что особенное." }, { 11.05, "Это миниатюрная копия того самого робота, которого ты так хорошо знаешь и любишь, – KKX!" }, { 18.12, "Обычно я никому не доверяю столь потенциально смертоносное устройство, но ты мне по-настоящему помог." }, { 25.32, "К тому же у этого боевые механизмы и система самонаведения отключены." }, { 30.35, "А в остальном это самый настоящий KKX, честное слово!" } }, f = { { 0.00, "Ты вернула трёх моих самонаводящихся роботов KKX!" }, { 4.12, "Ты сделала куда больше, чем требовалось, поэтому за всю твою помощь я дам тебе кое-что особенное." }, { 11.94, "Это миниатюрная копия того самого робота, которого ты так хорошо знаешь и любишь, – KKX!" }, { 19.01, "Обычно я никому не доверяю столь потенциально смертоносное устройство, но ты мне по-настоящему помогла." }, { 26.80, "К тому же у этого боевые механизмы и система самонаведения отключены." }, { 31.83, "А в остальном это самый настоящий KKX, честное слово!" } } } } },
    [3741] = { d = 23.9, v = "child-male", n = { x = 270 }, c = { x = { { 0.00, "Моя подруга Хилари потеряла ожерелье, и мы никак не можем отыскать его." }, { 5.04, "Мы весь день сидели на одном и том же месте, удили рыбу, и уже все кругом обыскали." }, { 11.10, "Наверное, оно упало в воду." }, { 13.10, "Родители не разрешают нам плавать в озере..." }, { 16.15, "Мама говорит, что под водой водятся чудовища, но вы ведь их не боитесь, правда?" }, { 21.56, "Пожалуйста, достаньте нам ожерелье." } } }, t = { d = 9.8, g = 1, v = "child-female", n = { m = 90, f = 89 }, c = { m = { { 0.00, "Спасибо, что достали мне ожерелье, господин герой..." }, { 4.11, "Вы очень добры!" }, { 5.38, "Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?" } }, f = { { 0.00, "Спасибо, что достали мне ожерелье, госпожа героиня..." }, { 4.15, "Вы очень добры!" }, { 5.41, "Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?" } } } } },
    [3761] = { d = 32.5, v = "creature/hamuul", n = { x = 334 }, c = { x = { { 0.00, "Говорят, что почва из Кратера Ун'Горо наделена мощными магическими свойствами." }, { 6.23, "Кругу Кенария нужно много этой почвы для исследований." }, { 10.66, "Ступай в страшные окрестности Ун'Горо и добудь земли побольше." }, { 15.67, "Эта богатая почва порой лежит большими грудами, а иногда её находят у некоторых тварей." }, { 22.76, "Относи землю к Геду – ищи кучки земли и таурена, раздающего команды." }, { 28.34, "Он не злой, просто постарайся его не слишком донимать." } } }, t = { d = 31.1, g = 1, v = "tauren-male", n = { m = 311, f = 312 }, c = { m = { { 0.00, "Ну конечно, рядовой, и не пытайся помогать мне сваливать эту землю в кучу!" }, { 6.06, "Если бы Великие духи этого хотели, то прямо тут и устроили бы чудо, что, не так?!" }, { 12.64, "Верховный друид Рунический Тотем опять хочет с тобой говорить, но чтобы выполнить его очередное поручение, тебе нужно разбираться в травничестве на уровне подмастерья." }, { 26.30, "Но если ты ещё не доучился, он всё равно тебе дельце подберёт." } }, f = { { 0.00, "Ну конечно, рядовая, и не пытайся помогать мне сваливать эту землю в кучу!" }, { 5.90, "Если бы Великие духи этого хотели, то прямо тут и устроили бы чудо, что, не так?!" }, { 12.29, "Верховный друид Рунический Тотем опять хочет с тобой говорить, но чтобы выполнить его очередное поручение, тебе нужно разбираться в травничестве на уровне подмастерья." }, { 25.57, "Но если ты ещё не доучилась, он всё равно тебе дельце подберёт." } } } } },
    [3762] = { d = 27.9, g = 1, v = "tauren-female", n = { x = 297 }, c = { m = { { 0.00, "Извини, герой, можно тебя на минутку?" }, { 2.98, "Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании." }, { 12.67, "Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем." }, { 19.87, "Если тебя это интересует, отправляйся в Громовой Утёс на Вершину Старейшин и поговори с самим Хамуулом." } }, f = { { 0.00, "Извини, героиня, можно тебя на минутку?" }, { 3.13, "Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании." }, { 12.85, "Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем." }, { 20.08, "Если тебя это интересует, отправляйся в Громовой Утёс на Вершину Старейшин и поговори с самим Хамуулом." } } }, t = { d = 23.5, g = 1, v = "creature/hamuul", n = { x = 220 }, c = { m = { { 0.00, "Привет тебе, герой." }, { 1.72, "Я рад, что ты хочешь помочь нам в наших исследованиях." }, { 6.14, "Сделать предстоит многое, и я дурно поступил бы, если бы сказал, что труды наши не сулят опасности." }, { 14.46, "Надеюсь, это тебя не отпугнёт... но, судя по твоему виду, тебе и прежде приходилось сталкиваться с опасностями." } }, f = { { 0.00, "Привет тебе, героиня." }, { 1.82, "Я рад, что ты хочешь помочь нам в наших исследованиях." }, { 6.11, "Сделать предстоит многое, и я дурно поступил бы, если бы сказал, что труды наши не сулят опасности." }, { 14.17, "Надеюсь, это тебя не отпугнёт... но, судя по твоему виду, тебе и прежде приходилось сталкиваться с опасностями." } } } } },
    [3763] = { d = 26.5, g = 1, v = "nightelf-female", n = { x = 327 }, c = { m = { { 0.00, "Простите, герой, не уделите ли вы мне крупицу вашего времени?" }, { 4.05, "Дарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте." }, { 12.69, "Подробностей я не знаю, но могу сказать, что исследованиями руководит не кто иной, как сам верховный друид Фэндрал Олений Шлем." }, { 20.98, "Прошу вас, если вам интересно, поговорите с ним лично в анклаве Кенария в Дарнассе." } }, f = { { 0.00, "Простите, героиня, не уделите ли вы мне крупицу вашего времени?" }, { 4.18, "Дарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте." }, { 12.83, "Подробностей я не знаю, но могу сказать, что исследованиями руководит не кто иной, как сам верховный друид Фэндрал Олений Шлем." }, { 21.13, "Прошу вас, если вам интересно, поговорите с ним лично в анклаве Кенария в Дарнассе." } } }, t = { d = 16.5, g = 1, v = "named/3516", n = { x = 179 }, c = { m = { { 0.00, "Что же, герой... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли." }, { 9.55, "И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду." } }, f = { { 0.00, "Что же, героиня... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли." }, { 9.79, "И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду." } } } } },
    [3764] = { d = 34.1, v = "named/3516", n = { x = 413 }, c = { x = { { 0.00, "Говорят, что почва из Кратера Ун'Горо наделена мощными магическими свойствами." }, { 5.27, "Я хочу знать, насколько эти слухи преувеличены." }, { 8.48, "Ступай в заросший кратер Ун'Горо и добудь хороших образцов земли для наших исследований." }, { 14.48, "Тебе может показаться, что это дело не достойно тебя, но такое поведение не завоюет тебе приязни ни с моей стороны, ни со стороны Круга Кенария." }, { 24.29, "Принеси образцы земли Дженалю, который наверняка сидит без дела вон за тем деревом – ищи кучки земли, и найдёшь его." }, { 32.16, "Снабжением занимается он, не я." } } }, t = { d = 32.0, g = 1, v = "nightelf-male#59", n = { m = 368, f = 368 }, c = { m = { { 0.00, "Наконец-то ты сможешь избавиться от своего драгоценного груза, благородный герой." }, { 5.58, "Тяжкая, наверное, ноша... не легче ноши созерцателя, вроде меня..." }, { 10.24, "Вот гонорар за работу, назначенный самим верховным друидом." }, { 14.33, "Верховный друид Олений Шлем опять хочет видеть тебя, но ты получишь помощь при выполнении следующего его задания, если только будешь разбираться в травознании не хуже подмастерья." }, { 26.74, "Но если даже ты и вовсе не травник, ты всё равно можешь помочь Кругу!" } }, f = { { 0.00, "Наконец-то ты сможешь избавиться от своего драгоценного груза, благородная героиня." }, { 5.79, "Тяжкая, наверное, ноша... не легче ноши созерцателя, вроде меня..." }, { 10.50, "Вот гонорар за работу, назначенный самим верховным друидом." }, { 14.66, "Верховный друид Олений Шлем опять хочет видеть тебя, но ты получишь помощь при выполнении следующего его задания, если только будешь разбираться в травознании не хуже подмастерья." }, { 27.24, "Но если даже ты и вовсе не травник, ты всё равно можешь помочь Кругу!" } } } } },
    [3765] = { d = 28.4, g = 1, v = "nightelf-male#55", n = { x = 306 }, c = { m = { { 0.00, "Штормград – невероятно суматошный город." }, { 3.00, "Я прибыл сюда издалека в поисках помощи." }, { 6.07, "Говорят, отважные искатели приключений нередко бродят по этим улицам." }, { 11.28, "Мой брат Гершала на Тёмном Берегу нуждается в помощи." }, { 15.15, "Он обитает в приморском городке Аубердине." }, { 18.28, "Это путешествие будет долгим и насыщенным." }, { 21.49, "Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, герой." } }, f = { { 0.00, "Штормград – невероятно суматошный город." }, { 3.02, "Я прибыл сюда издалека в поисках помощи." }, { 6.11, "Говорят, отважные искатели приключений нередко бродят по этим улицам." }, { 11.35, "Мой брат Гершала на Тёмном Берегу нуждается в помощи." }, { 15.25, "Он обитает в приморском городке Аубердине." }, { 18.40, "Это путешествие будет долгим и насыщенным." }, { 21.63, "Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, героиня." } } }, t = { d = 9.0, v = "nightelf-male#54", n = { x = 86 }, c = { x = { { 0.00, "О, вас прислал мой брат Аргос?" }, { 2.51, "Должно быть, вы устали от долгого пути." }, { 5.85, "Но нам очень о многом нужно поговорить." } } } } },
    [3781] = { d = 29.7, g = 1, v = "named/3516", n = { m = 340, f = 342 }, c = { m = { { 0.00, "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо." }, { 8.05, "Из этих семян проросло множество редких полезных трав." }, { 11.88, "И одна из них – рассветница, таинственное растение, о котором мы мало что знаем." }, { 17.41, "Я намерен разгадать его тайну." }, { 19.62, "Отнеси это вниз, Матренгилу, и он даст тебе семена, чтобы ты мог начать работу." }, { 25.15, "Если всё израсходуешь, тебе придётся купить у него ещё семян." } }, f = { { 0.00, "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо." }, { 8.10, "Из этих семян проросло множество редких полезных трав." }, { 11.97, "И одна из них – рассветница, таинственное растение, о котором мы мало что знаем." }, { 17.54, "Я намерен разгадать его тайну." }, { 19.76, "Отнеси это вниз, Матренгилу, и он даст тебе семена, чтобы ты могла начать работу." }, { 25.52, "Если всё израсходуешь, тебе придётся купить у него ещё семян." } } }, t = { d = 23.3, v = "nightelf-male#59", n = { x = 270 }, c = { x = { { 0.00, "Да, расписка на двадцать пакетиков семян." }, { 2.98, "Если всё изведёшь, ещё достанем." }, { 5.24, "Хотя производить семена Тарлендриса в большом количестве – дело, увы, недешёвое." }, { 11.00, "Потому Круг Кенария и просит помощи в частичном возмещении стоимости." }, { 15.98, "Те, кто находит рассветницу и приносит нам, видят, что награда верховного друида с лихвой окупает труды." } } } } },
    [3782] = { d = 37.4, g = 1, v = "creature/hamuul", n = { m = 374, f = 376 }, c = { m = { { 0.00, "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо." }, { 9.30, "Из этих семян проросло множество редких полезных трав." }, { 13.73, "И одна из них – рассветница, таинственное растение, о котором мы мало что знаем." }, { 20.13, "Я намерен раскрыть его тайну для Круга." }, { 23.40, "Отнеси эту расписку моей дочери Башане Руническому Тотему, и она даст тебе семена, чтобы ты мог начать работу." }, { 32.48, "Если всё израсходуешь, тебе придётся купить у неё ещё семян." } }, f = { { 0.00, "При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун'Горо." }, { 9.33, "Из этих семян проросло множество редких полезных трав." }, { 13.77, "И одна из них – рассветница, таинственное растение, о котором мы мало что знаем." }, { 20.18, "Я намерен раскрыть его тайну для Круга." }, { 23.46, "Отнеси эту расписку моей дочери Башане Руническому Тотему, и она даст тебе семена, чтобы ты могла начать работу." }, { 32.78, "Если всё израсходуешь, тебе придётся купить у неё ещё семян." } } }, t = { d = 26.2, v = "tauren-female#71", n = { x = 273 }, c = { x = { { 0.00, "Да, расписка на двадцать пакетиков семян." }, { 3.33, "Если всё израсходуешь, у меня есть ещё на продажу." }, { 7.30, "Увы, производить семена Тарлендриса в большом количестве дорого." }, { 12.51, "Потому Круг Кенария и просит помощи в частичном возмещении стоимости." }, { 18.08, "Те, кто находит рассветницу и приносит нам, видят, что награда верховного друида с лихвой окупает труды." } } } } },
    [3783] = { d = 31.6, v = "goblin-female#63", n = { x = 343 }, c = { x = { { 0.00, "У моих друзей всегда замечательные идеи." }, { 3.09, "Я никогда не думала, что смогу сравниться с ними… до сегодняшнего дня!" }, { 8.27, "У меня созрел потрясающий план!" }, { 10.63, "Если обещаешь никому не говорить, я расскажу тебе его по секрету…" }, { 15.60, "Я хочу сделать механического йети!" }, { 18.23, "Мои друзья с ума сойдут, когда увидят, что я смогла смастерить!" }, { 23.07, "Для начала мне понадобится толстый мех йети с холмов Ледополоха." }, { 27.85, "Ты мне поможешь?" }, { 29.06, "Йети водятся к юго-востоку отсюда." } } }, t = { d = 5.6, v = "goblin-female#63", n = { x = 52 }, c = { x = { { 0.00, "Это отличные меха." }, { 1.76, "Это чудесное начало воплощения моего плана!" } } } } },
    [3784] = { d = 30.1, g = 1, v = "scourge-male#82", n = { x = 297 }, c = { m = { { 0.00, "Извини, герой, можно тебя на минутку?" }, { 3.00, "Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании." }, { 12.78, "Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем." }, { 20.04, "Если тебя это интересует, отправляйся в Громовой Утёс на Вершину Старейшин и поговори с самим Хамуулом." } }, f = { { 0.00, "Извини, героиня, можно тебя на минутку?" }, { 3.37, "Кругу Кенария в Громовом Утёсе требуются такие закалённые путешественники, как ты, для участия в чрезвычайно важном исследовании." }, { 13.85, "Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем." }, { 21.63, "Если тебя это интересует, отправляйся в Громовой Утёс на Вершину Старейшин и поговори с самим Хамуулом." } } }, t = { d = 21.0, g = 1, v = "creature/hamuul", n = { x = 216 }, c = { m = { { 0.00, "Приветствую, герой!" }, { 1.51, "Я рад, что тебя заинтересовало наше исследование." }, { 5.21, "Дел очень много, и я обманул бы тебя, сказав, что речь идёт о безопасном задании." }, { 11.31, "Надеюсь, тебя так просто не напугать..." }, { 14.32, "По твоему виду можно предположить, что тебе приходилось сталкиваться с опасностями." } }, f = { { 0.00, "Приветствую, героиня!" }, { 1.67, "Я рад, что тебя заинтересовало наше исследование." }, { 5.43, "Дел очень много, и я обманул бы тебя, сказав, что речь идёт о безопасном задании." }, { 11.63, "Надеюсь, тебя так просто не напугать..." }, { 14.70, "По твоему виду можно предположить, что тебе приходилось сталкиваться с опасностями." } } } } },
    [3785] = { d = 27.4, v = "nightelf-male#59", n = { x = 331 }, c = { x = { { 0.00, "Это сума вечного цветения для семян Тарлендриса." }, { 3.35, "Ещё тебе понадобится почва из Кратера Ун'Горо как удобрение для семян." }, { 8.09, "Когда достанешь всё, что надо, просто используй суму, она позаботится обо всём." }, { 13.45, "Когда у тебя будет достаточно рассветницы, принеси её мне сюда в анклав." }, { 18.37, "И не утруждай верховного друида: он эльф занятой, не стоит отрывать его от дела всякий раз, как кто-то приносит очередную порцию зерна!" } } }, t = { d = 19.0, v = "nightelf-male#59", n = { x = 220 }, c = { x = { { 0.00, "Очень хорошо, я непременно отнесу их лично верховному друиду, когда они ему понадобятся." }, { 6.44, "А пока прими это в знак признательности от Круга Кенария." }, { 10.56, "Нам рассветница нужна всегда." }, { 12.68, "Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить." } } } } },
    [3786] = { d = 29.2, v = "tauren-female#71", n = { x = 320 }, c = { x = { { 0.00, "Вот сума вечного цветения для семян Тарлендриса." }, { 3.63, "Ещё тебе понадобится почва из Кратера Ун'Горо как удобрение для семян." }, { 8.88, "Когда достанешь всё, что надо, просто используй суму, а уж она сама позаботится обо всём." }, { 15.55, "Когда у тебя будет достаточно рассветницы, принеси её мне сюда на Вершину Старейшин." }, { 21.88, "И не утруждай верховного друида – он очень занят исследованиями, да и других забот у него полон рот." } } }, t = { d = 21.4, v = "tauren-female#71", n = { x = 220 }, c = { x = { { 0.00, "Очень хорошо, я непременно отнесу их лично верховному друиду, когда они ему понадобятся." }, { 7.25, "А пока прими это в знак признательности от Круга Кенария." }, { 11.88, "Нам рассветница нужна всегда." }, { 14.27, "Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить." } } } } },
    [3787] = { d = 31.2, g = 1, v = "nightelf-female#53", n = { m = 366, f = 375 }, c = { m = { { 0.00, "Простите, друг мой..." }, { 1.45, "Мой коллега хотел бы поговорить с вами касательно проводимых вами совместно с Кругом Кенария исследований." }, { 8.89, "Он друид, зовут его Квинтис Ночной Костёр, и живёт он в Крепости Оперённой Луны в Фераласе." }, { 15.19, "Он хотел бы посоветоваться с вами насчёт рассветницы... и он очень хотел бы, чтобы этот разговор не дошёл до ушей верховного друида." }, { 24.33, "Если вы заинтересовались, поговорите с Квинтисом; не сомневайтесь, он расскажет вам всё подробно." } }, f = { { 0.00, "Простите, уважаемая госпожа..." }, { 2.12, "Мой коллега хотел бы поговорить с вами касательно проводимых вами совместно с Кругом Кенария исследований." }, { 9.49, "Он друид, зовут его Квинтис Ночной Костёр, и живёт он в Крепости Оперённой Луны в Фераласе." }, { 15.73, "Он хотел бы посоветоваться с вами насчёт рассветницы... и он очень хотел бы, чтобы этот разговор не дошёл до ушей верховного друида." }, { 24.79, "Если вы заинтересовались, поговорите с Квинтисом; не сомневайтесь, он расскажет вам всё подробно." } } }, t = { d = 38.2, g = 1, v = "nightelf-male#54", n = { m = 395, f = 396 }, c = { m = { { 0.00, "Благодарю вас за ваш визит, усталый путник!" }, { 3.29, "Позвольте представиться: я – Квинтис Ночной Костёр, друид и скромный слуга Малфуриона и Круга Кенария." }, { 11.02, "Мои коллеги (генерал Шандриса Оперённая Луна и Протекторат – вы, может быть, о нас слыхали) и я хотели бы поговорить с вами о той работе, которую вы проводите для Фэндрала Оленьего Шлема в Дарнассе." }, { 25.88, "Прежде чем мы пойдём дальше, я хотел бы попросить вас, чтобы этот разговор остался строго между нами." }, { 33.62, "Если вы с этим согласны, мы можем продолжать." } }, f = { { 0.00, "Благодарю вас за ваш визит, усталая путница!" }, { 3.46, "Позвольте представиться: я – Квинтис Ночной Костёр, друид и скромный слуга Малфуриона и Круга Кенария." }, { 11.45, "Мои коллеги (генерал Шандриса Оперённая Луна и Протекторат – вы, может быть, о нас слыхали) и я хотели бы поговорить с вами о той работе, которую вы проводите для Фэндрала Оленьего Шлема в Дарнассе." }, { 26.80, "Прежде чем мы пойдём дальше, я хотел бы попросить вас, чтобы этот разговор остался строго между нами." }, { 34.78, "Если вы с этим согласны, мы можем продолжать." } } } } },
    [3788] = { d = 27.0, v = "nightelf-female", n = { x = 343 }, c = { x = { { 0.00, "Простите, друг мой…" }, { 1.22, "Один мой коллега хотел бы побеседовать с вами об исследованиях, которые вы ведёте в сотрудничестве с Кругом Кенария." }, { 8.59, "Это друид по имени Квинтис Ночной Костёр." }, { 11.32, "Он проживает здесь же, в Крепости Оперённой Луны." }, { 14.40, "Он хотел бы поговорить с вами насчёт рассветницы... а главное, очень просит вас, чтобы эта беседа не дошла до ушей верховного друида." }, { 23.00, "Если вас это интересует, поговорите с ним, и вам всё станет ясно." } } }, t = { d = 37.8, g = 1, v = "nightelf-male#54", n = { m = 406, f = 407 }, c = { m = { { 0.00, "Благодарю вас, что явились ко мне, усталый путник!" }, { 3.67, "Позвольте представиться." }, { 5.46, "Я – Квинтис Ночной Костёр, друид и смиренный служитель Малфуриона и Круга Кенария." }, { 11.53, "Мои коллеги (генерал Шандриса Оперённая Луна и Протекторат – быть может, вы о нас слышали), и я хотели поговорить с вами о работе, которую вы ведёте в Дарнассе по поручению Фэндрала Оленьего Шлема." }, { 25.92, "Но прежде, чем мы продолжим наш разговор, я хотел бы вас попросить, чтобы эта беседа осталась между нами." }, { 33.72, "Если вы не против, то мы можем перейти к делу." } }, f = { { 0.00, "Благодарю вас, что явились ко мне, усталая путница!" }, { 3.81, "Позвольте представиться." }, { 5.64, "Я – Квинтис Ночной Костёр, друид и смиренный служитель Малфуриона и Круга Кенария." }, { 11.82, "Мои коллеги (генерал Шандриса Оперённая Луна и Протекторат – быть может, вы о нас слышали), и я хотели поговорить с вами о работе, которую вы ведёте в Дарнассе по поручению Фэндрала Оленьего Шлема." }, { 26.50, "Но прежде, чем мы продолжим наш разговор, я хотел бы вас попросить, чтобы эта беседа осталась между нами." }, { 34.45, "Если вы не против, то мы можем перейти к делу." } } } } },
    [3789] = { d = 25.4, g = 1, v = "human-female#111", n = { x = 316 }, c = { m = { { 0.00, "Герой, простите, но нельзя ли отвлечь вас на минутку от ваших дел?" }, { 4.31, "Круг Кенария в Дарнассе приглашает искателей приключений для участия в жизненно важном проекте." }, { 10.50, "Я не знаю всех подробностей, собственно, могу сказать только, что верховный друид Фэндрал Олений Шлем рассылает это приглашение." }, { 18.89, "Если вас это интересует, обратитесь к нему напрямую, вы найдёте его в дарнасском анклаве Кенария." } }, f = { { 0.00, "Героиня, простите, но нельзя ли отвлечь вас на минутку от ваших дел?" }, { 4.46, "Круг Кенария в Дарнассе приглашает искателей приключений для участия в жизненно важном проекте." }, { 10.71, "Я не знаю всех подробностей, собственно, могу сказать только, что верховный друид Фэндрал Олений Шлем рассылает это приглашение." }, { 19.15, "Если вас это интересует, обратитесь к нему напрямую, вы найдёте его в дарнасском анклаве Кенария." } } }, t = { d = 16.4, g = 1, v = "named/3516", n = { x = 179 }, c = { m = { { 0.00, "Что же, герой... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли." }, { 9.55, "И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду." } }, f = { { 0.00, "Что же, героиня... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли." }, { 9.75, "И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду." } } } } },
    [3790] = { d = 28.6, g = 1, v = "dwarf-male#100", n = { x = 327 }, c = { m = { { 0.00, "Простите, герой, не уделите ли вы мне крупицу вашего времени?" }, { 4.33, "Дарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте." }, { 13.58, "Подробностей я не знаю, но могу сказать, что исследованиями руководит не кто иной, как сам верховный друид Фэндрал Олений Шлем." }, { 22.44, "Прошу вас, если вам интересно, поговорите с ним лично в анклаве Кенария в Дарнассе." } }, f = { { 0.00, "Простите, героиня, не уделите ли вы мне крупицу вашего времени?" }, { 4.51, "Дарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте." }, { 13.84, "Подробностей я не знаю, но могу сказать, что исследованиями руководит не кто иной, как сам верховный друид Фэндрал Олений Шлем." }, { 22.78, "Прошу вас, если вам интересно, поговорите с ним лично в анклаве Кенария в Дарнассе." } } }, t = { d = 16.9, g = 1, v = "named/3516", n = { x = 179 }, c = { m = { { 0.00, "Что же, герой... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли." }, { 9.79, "И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду." } }, f = { { 0.00, "Что же, героиня... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли." }, { 10.03, "И раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду." } } } } },
    [3791] = { d = 38.5, v = "nightelf-male#54", n = { x = 426 }, c = { x = { { 0.00, "Я буду с вами откровенен." }, { 1.96, "Меня интересует – точнее, тревожит вопрос, почему верховный друид в Дарнассе пользуется именем и возможностями Круга Кенария для того, чтобы добывать огромное количество рассветницы." }, { 15.69, "Я – исследователь, и специализируюсь на проклятиях." }, { 19.42, "И я слышал, что рассветница в соответствующих условиях приобретает те же свойства, что и прочие травы, используемые в примитивных проклятиях." }, { 29.77, "Я хотел бы узнать об этом подробнее." }, { 32.54, "И мне нужна ваша помощь." }, { 34.43, "Принесите мне десять рассветниц, и я буду у вас в долгу!" } } }, t = { d = 33.4, v = "nightelf-male#54", n = { x = 328 }, c = { x = { { 0.00, "Какое... какое странное ощущение вызывают у меня эти растения!" }, { 5.13, "Во имя Элуны, что же затеял Олений Шлем?" }, { 8.38, "Ну, как бы то ни было, спасибо вам за помощь." }, { 11.92, "Вот кое-что... ну, понимаете, за труды." }, { 15.02, "Мои исследования, несомненно, затянутся, и мне потребуется ещё немало такой травы." }, { 21.60, "Раз уж я этим занялся, пожалуй, стоит проверить, пригодна ли рассветница для использования в алхимии." }, { 29.61, "И тем не менее мне не по себе от этих растений..." } } } } },
    [3792] = { t = { d = 30.8, v = "nightelf-male#54", n = { x = 316 }, c = { x = { { 0.00, "Спасибо." }, { 0.71, "Я их пока припрячу." }, { 2.27, "У меня, конечно, нет таких значительных средств, как у Оленьего Шлема, однако я всё же способен вознаградить вас за труды!" }, { 11.69, "Тем более, кто знает, что может случиться, если Олений Шлем будет получать всё больше рассветницы..." }, { 19.55, "Тут что-то нечисто, помяните мои слова!" }, { 22.74, "Не забывайте, что от лишней рассветницы я никогда не откажусь." }, { 27.55, "Приносите по пять штук за раз, и я их возьму." } } } } },
    [3801] = { d = 32.6, v = "dwarf-male", n = { x = 354 }, c = { x = { { 0.00, "Привет тебе." }, { 1.02, "Я Франклорн Искусник." }, { 2.65, "Да, тот самый Франклорн Искусник, который придумал, как тесать камень." }, { 7.96, "За долгие странствия по терзаемому войнами миру тебе несомненно случалось проходить сквозь мои творения или стоять на них." }, { 17.20, "Должно быть, тебе интересно, откуда я здесь и что мне от тебя нужно." }, { 22.30, "Логичные вопросы." }, { 23.66, "Разумеется, мне нужна твоя помощь." }, { 26.32, "В обмен на неё я дарую тебе ключ, открывающий путь в глубины моего проклятого города." } } }, t = { d = 7.3, v = "dwarf-male", n = { x = 78 }, c = { x = { { 0.00, "Жадность ли привела тебя сюда или слепая верность, от твоего предприятия будет благо нам всем." } } } } },
    [3802] = { d = 34.3, v = "dwarf-male", n = { x = 379 }, c = { x = { { 0.00, "Точень Темнострой находится за Кольцом Закона в Зале Ремесла." }, { 4.68, "Убей ничтожную тварь и забери Железного Друга." }, { 8.60, "Отнеси Железного Друга в святилище Тауриссана и помести молот в предначертанное ему место: в руки статуи, воздвигнутой в мою честь." }, { 18.66, "После этого откроется тайное отделение, в котором я спрятал главный ключ." }, { 23.97, "А главное, Железный Друг навеки останется в моих руках." }, { 27.99, "Если они предпримут попытку забрать его, то статуя и молот рассыплются и исчезнут вовек." } } }, t = { d = 12.1, v = "narrator", n = { x = 119 }, c = { x = { { 0.00, "Молот легко встаёт на место, в руку массивного монумента Чёрного Железа." }, { 6.20, "У основания статуи открывается тайное отделение." }, { 10.38, "Внутри оказывается..." } } } } },
    [3803] = { t = { d = 21.6, v = "nightelf-male#59", n = { x = 235 }, c = { x = { { 0.00, "Великолепно!" }, { 0.96, "Верховный друид, несомненно, обрадуется этой рассветнице." }, { 5.33, "Правда, должен признать... даже находиться рядом с ней не особо приятно." }, { 10.87, "Представляю, как тяжело верховному друиду всё время возиться с этой травой!" }, { 16.62, "А это для тебя." }, { 17.85, "Круг Кенария благодарит тебя за безотказную помощь." } } } } },
    [3804] = { t = { d = 31.2, v = "tauren-female#71", n = { x = 325 }, c = { x = { { 0.00, "Великолепно – эта рассветница несомненно поможет нам в будущем!" }, { 4.97, "Мы знаем, что и ночные эльфы проводят подобные исследования трав, хотя непонятно, для чего будут они использовать результаты – если, конечно, что-нибудь найдут." }, { 17.59, "Верховный друид считает, что рассветница будет нам нужна до тех пор, пока мы не узнаем тайну этого растения." }, { 26.10, "А это для тебя." }, { 27.38, "Круг Кенария благодарит тебя за неустанную помощь." } } } } },
    [3821] = { d = 33.8, v = "troll-male#77", n = { x = 366 }, c = { x = { { 0.00, "Больше трёх недель назад Ша'ни была отправлена в Пылающие степи, чтобы исследовать странные ритуалы огров клана Огненного Чрева – что-то эти огры зашевелились в последнее время." }, { 13.41, "Клинозуб сообщил мне, что от её группы с тех пор не было вестей, и что главное сейчас – заняться неотложными делами." }, { 21.92, "Представляешь?!" }, { 23.06, "А речь, между прочим, о моей жене!" }, { 25.67, "Я не вправе оставить свой пост, но я должен знать, что случилось с Ша'ни!" }, { 30.97, "Отправляйся в Пылающие степи и найди её!" } } }, t = { d = 10.6, v = "troll-female#75", n = { x = 120 }, c = { x = { { 0.00, "Бедный мой Талтрак..." }, { 1.56, "А мы ведь хотели уехать во Внутренние земли вместе с родителями, когда закончим службу." }, { 7.85, "Теперь этим мечтам не суждено сбыться!" } } } } },
    [3822] = { d = 36.2, v = "troll-female#75", n = { x = 368 }, c = { x = { { 0.00, "Они захватили весь мой взвод." }, { 2.27, "И всех, кроме меня, убили." }, { 4.40, "Их главарь, Кром'Грул, оставил меня для совершения какого-то обряда." }, { 9.79, "Меня приковали к этому алтарю и жестоко пытали." }, { 13.62, "Через час мучений моё физическое тело умерло." }, { 17.23, "Тогда эта тварь вырвала у меня из носа обручальное кольцо и напялила на свой палец." }, { 23.83, "В жизни не встречала подобного варварства!" }, { 27.16, "Найди Кром'Грула и убей его!" }, { 29.50, "Отнеси моё кольцо Талтраку." }, { 31.70, "И скажи ему, что мы снова встретимся... в следующей жизни." } } }, t = { d = 21.8, v = "troll-male#77", n = { x = 204 }, c = { x = { { 0.00, "*Талтрак опускается на пол.*" }, { 2.40, "Мы собирались уехать во Внутренние земли." }, { 6.05, "Она рассказывала?" }, { 7.64, "Это было её последнее задание." }, { 10.41, "Оно мне не нужно." }, { 12.56, "Оставь его себе или выброси, мне всё равно!" }, { 16.52, "Теперь кольцо ничего для меня не значит." }, { 20.17, "Без неё оно ничто..." } } } } },
    [3823] = { d = 26.8, v = "dwarf-male", n = { x = 274 }, c = { x = { { 0.00, "Мы должны нанести удар первыми!" }, { 2.52, "Буду краток." }, { 3.57, "Огры Огненного Чрева – союзники орков Чёрной Горы в Пылающих степях." }, { 8.96, "Рука об руку они охраняют богатую полезными ископаемыми скалу Молота Ужаса и линии снабжения." }, { 16.38, "Оставь свой след в истории." }, { 18.48, "Смети их охрану и возвращайся ко мне." }, { 21.28, "*Орелиус хватается за воздух, будто кого-то душит.*" }, { 25.20, "Я тебя прибью!" } } }, t = { d = 7.8, v = "dwarf-male", n = { x = 86 }, c = { x = { { 0.00, "Потрясающе, солдат!" }, { 1.47, "Оркам и ограм понадобится несколько минут или даже часов, чтобы оправиться от удара!" } } } } },
    [3824] = { d = 32.3, v = "dwarf-male", n = { x = 322 }, c = { x = { { 0.00, "Говорю же, они колеблются!" }, { 2.15, "Пора нанести решительный удар." }, { 4.65, "Мы должны убить жестокого вождя, Гор'теша." }, { 8.08, "И что ещё важнее, мне нужна его голова для третьей фазы операции против огров Огненного Чрева." }, { 15.66, "И помни, солдат, Гор'теш правит не из скалы Молота Ужаса, но из строения орков Чёрной Горы на западе от неё." }, { 24.25, "Итак, приказы тебе даны ясные." }, { 26.82, "Найди Гор'теша и отруби ему башку." }, { 29.68, "Потом возвращайся ко мне." }, { 31.68, "ЗАТКНИСЬ!" } } }, t = { d = 13.8, v = "dwarf-male", n = { x = 140 }, c = { x = { { 0.00, "Только посмотрите на неё." }, { 2.08, "Какая мерзость!" }, { 3.42, "Когда остатки огров Огненного Чрева увидят этот жирный чайник на вершине собственной скалы, начнётся паника!" } } } } },
    [3825] = { d = 28.2, v = "dwarf-male", n = { x = 310 }, c = { x = { { 0.00, "Осталось только одно задание, солдат." }, { 2.83, "Я позволил себе вольность – нанизал голову Гор'теша на пику." }, { 7.32, "Тебе остаётся отнести её на вершину скалы Молота Ужаса и воткнуть в землю." }, { 12.79, "Стоит только сделать это, как трусливые огры бросятся куда глаза глядят!" }, { 18.26, "Когда ты повеселишься от души, возвращайся ко мне, и я награжу тебя за проделанную работу." }, { 24.72, "*Кажется, Орелиус теряет связь с реальностью.*" } } }, t = { d = 10.2, v = "dwarf-male", n = { x = 102 }, c = { x = { { 0.00, "Отличная работа, солдат!" }, { 2.06, "Поразительная!" }, { 3.24, "Ах, я получу медаль за храбрость, то есть, я хочу сказать, ты получишь недурную награду!" } } } } },
    [3841] = { d = 36.1, g = 1, v = "nightelf-female#52", n = { m = 427, f = 427 }, c = { m = { { 0.00, "О, привет!" }, { 0.73, "Я так рада видеть тебя снова!" }, { 2.81, "Как твоё путешествие в Дарнасс?" }, { 4.89, "А у нас тут приятные новости!" }, { 6.84, "Пока тебя не было, мы сумели многого добиться." }, { 10.08, "Мы даже спасли целую кладку яиц!" }, { 12.40, "К сожалению, самка погибла прежде, чем мы подоспели…" }, { 15.94, "Слушай, хочешь себе такого дракончика?" }, { 18.63, "Детёныши скоро должны вылупиться, и им понадобится хороший папа." }, { 22.97, "Ну, что скажешь?" }, { 24.07, "Если тебя это действительно интересует, возьми одно из яиц и ступай к Квентину, который находится на Мерцающей равнине, возле гоночной трассы." }, { 33.84, "Он тебе скажет, что делать дальше." } }, f = { { 0.00, "О, привет!" }, { 0.72, "Я так рада видеть тебя снова!" }, { 2.77, "Как твоё путешествие в Дарнасс?" }, { 4.81, "А у нас тут приятные новости!" }, { 6.74, "Пока тебя не было, мы сумели многого добиться." }, { 9.92, "Мы даже спасли целую кладку яиц!" }, { 12.21, "К сожалению, самка погибла прежде, чем мы подоспели…" }, { 15.70, "Слушай, хочешь себе такого дракончика?" }, { 18.34, "Детёныши скоро должны вылупиться, и им понадобится хорошая мама." }, { 22.61, "Ну, что скажешь?" }, { 23.69, "Если тебя это действительно интересует, возьми одно из яиц и ступай к Квентину, который находится на Мерцающей равнине, возле гоночной трассы." }, { 33.31, "Он тебе скажет, что делать дальше." } } }, t = { d = 28.6, v = "nightelf-male#59", n = { x = 318 }, c = { x = { { 0.00, "О, яйцо летучего хамелеона!" }, { 2.01, "И вот-вот должно проклюнуться, если я не ошибаюсь." }, { 5.64, "Удивительно, как тебе удалось его добыть, да ещё в таком хорошем состоянии?" }, { 11.08, "В Фераласе в наше время эти животные почти не делают кладок..." }, { 15.68, "Насколько я понимаю, в тамошних лесах развелась уйма браконьеров, которые охотятся на этих прекрасных созданий и убивают их." }, { 24.62, "Какая жалость, не правда ли?" }, { 26.70, "Но откуда у тебя это яйцо?" } } } } },
    [3842] = { d = 32.5, v = "nightelf-male#59", n = { x = 370 }, c = { x = { { 0.00, "Кайдел и Джеркай?" }, { 1.27, "Занятно..." }, { 2.03, "Жаль, что летучие хамелеоны не смогут оценить всё, что эти девушки для них делают." }, { 7.76, "Очень, очень способные девочки…" }, { 10.05, "Так значит, они дали тебе это яйцо в подарок?" }, { 13.42, "Что ж, теперь оно твоё и ты за него отвечаешь." }, { 16.66, "Оно, похоже, вот-вот проклюнется, но нужно ещё позаботиться о том, чтобы детёныш вылупился здоровым." }, { 23.66, "Для заклинания, которое будет защищать яйцо, мне требуется только два эликсира стойкости." }, { 29.95, "Остальные компоненты у меня уже есть." } } }, t = { d = 8.7, v = "nightelf-male#59", n = { x = 90 }, c = { x = { { 0.00, "Великолепно!" }, { 0.98, "Это то, что надо." }, { 2.37, "Сейчас, я смешаю все компоненты, и мы поглядим, как будет себя чувствовать детёныш..." } } } } },
    [3843] = { d = 31.8, v = "nightelf-male#59", n = { x = 384 }, c = { x = { { 0.00, "Великолепный экземпляр!" }, { 1.61, "Если это создание благополучно вылупится на свет, у тебя будет прекрасный, здоровый питомец!" }, { 8.01, "Но если ты рассчитываешь оставить его себе, я бы посоветовал сделать ещё одну вещь." }, { 13.72, "Отправляйся на Заоблачный Пик во Внутренних землях, и поговори там с дворфом по имени Агнар Зверопас." }, { 20.61, "Он большой специалист по дрессировке животных, и объяснит тебе, что нужно делать дальше." }, { 26.69, "Только ступай скорее, яйцо хрупкое и без должного ухода долго не протянет!" } } }, t = { d = 21.4, g = 1, v = "dwarf-male", n = { m = 208, f = 209 }, c = { m = { { 0.00, "Так-так-так..." }, { 1.16, "Таких мелких я даже и не видел." }, { 3.77, "Лесной дракончик, если не ошибаюсь... точнее, летучий хамелеон." }, { 8.91, "Отлично, отлично!" }, { 10.36, "Ну, чтобы этот малыш благополучно выжил и вырос крепким и здоровым, нужно раздобыть для него еды!" }, { 18.33, "Хорошо, что ты вовремя до меня добрался!" } }, f = { { 0.00, "Так-так-так..." }, { 1.14, "Таких мелких я даже и не видел." }, { 3.71, "Лесной дракончик, если не ошибаюсь... точнее, летучий хамелеон." }, { 8.78, "Отлично, отлично!" }, { 10.21, "Ну, чтобы этот малыш благополучно выжил и вырос крепким и здоровым, нужно раздобыть для него еды!" }, { 18.07, "Хорошо, что ты вовремя до меня добралась!" } } } } },
    [3844] = { d = 25.6, v = "narrator", n = { x = 267 }, c = { x = { { 0.00, "На берегу вы видите разбитый плот." }, { 2.73, "Если учесть, что пруд очень мал, непонятно, как мог оказаться в нём плот, да ещё такой побитый непогодой." }, { 10.93, "Хотя, более пристальный взгляд на деревья даёт возможность предположить, что уровень воды здесь не постоянный..." }, { 19.71, "Возможно, если приглядеться повнимательней, можно отыскать ключ к загадке..." } } }, t = { d = 3.5, v = "narrator", n = { x = 33 }, c = { x = { { 0.00, "На дне пруда виднеется какой-то свёрток." } } } } },
    [3845] = { d = 16.9, v = "narrator", n = { x = 183 }, c = { x = { { 0.00, "Вы вытаскиваете сумку на берег, в надежде, что её содержимое укажет вам на то, откуда она могла взяться и кому бы могла принадлежать." }, { 10.13, "В Укрытии Маршалла есть несколько заблудших путников." }, { 14.20, "Возможно, там удастся узнать больше." } } }, t = { d = 4.7, v = "gnome-male", n = { x = 35 }, c = { x = { { 0.00, "О, а вот это, похоже, и в самом деле мне знакомо!" } } } } },
    [3861] = { d = 26.7, v = "narrator", n = { x = 206 }, c = { x = { { 0.00, "\"..." }, { 0.43, "Кудах... кудах..." }, { 2.13, "Куд-кудааааа!" }, { 3.40, "Кудах...кудах-тах-тах..." }, { 5.70, "\"" }, { 5.87, "Курица смотрит на вас и начинает что-то царапать на земле лапой." }, { 12.00, "Вам кажется, что это какое-то слово, но вы не уверены, какое именно." }, { 18.46, "Может..." }, { 19.31, "Саль... де... ан?" }, { 20.84, "Прежде чем вы успеваете спросить, курица уходит по своим делам." } } }, t = { d = 20.2, v = "narrator", n = { x = 206 }, c = { x = { { 0.00, "\"Куд-кудааа!\"" }, { 1.09, "Курица начинает жадно клевать корм, который вы рассыпали перед ней." }, { 6.53, "Через несколько мгновений она испуганно оглядывается по сторонам." }, { 11.83, "Начинает скрести лапой и суетиться." }, { 14.73, "Она что, яйца снести хочет?" }, { 17.05, "Вы думаете, что надо бы заглянуть под неё." } } } } },
    [3881] = { d = 38.8, g = 1, v = "human-male", n = { m = 483, f = 485 }, c = { m = { { 0.00, "Не знаю, какими судьбами ты оказался здесь, но ты для нас желанный гость!" }, { 4.73, "Меня зовут Виллиден Маршал, я здесь с самостоятельной исследовательской экспедицией." }, { 10.23, "Последняя и самая важная наша кампания столкнулась с многочисленными трудностями." }, { 15.61, "Пожалуй, наиболее существенным нашим просчётом было то, что мы недооценили опасность, которую несёт в себе дикая природа Кратера Ун'Горо." }, { 24.64, "Нам пришлось в спешке покинуть наши базовые лагеря в северо-восточной и юго-западной областях кратера, побросав жизненно важные припасы." }, { 33.79, "Ты выглядишь весьма внушительно – не поможешь ли нам вернуть их?" } }, f = { { 0.00, "Не знаю, какими судьбами ты оказалась здесь, но ты для нас желанная гостья!" }, { 5.00, "Меня зовут Виллиден Маршал, я здесь с самостоятельной исследовательской экспедицией." }, { 10.62, "Последняя и самая важная наша кампания столкнулась с многочисленными трудностями." }, { 16.11, "Пожалуй, наиболее существенным нашим просчётом было то, что мы недооценили опасность, которую несёт в себе дикая природа Кратера Ун'Горо." }, { 25.33, "Нам пришлось в спешке покинуть наши базовые лагеря в северо-восточной и юго-западной областях кратера, побросав жизненно важные припасы." }, { 34.67, "Ты выглядишь весьма внушительно – не поможешь ли нам вернуть их?" } } }, t = { d = 22.1, v = "human-male", n = { x = 239 }, c = { x = { { 0.00, "О, ты привёз нам и нашу провизию, и наши инструменты!" }, { 3.94, "Ты не просто спас экспедицию, ты спас нам жизнь!" }, { 7.41, "Теперь-то мы сможем здесь продержаться!" }, { 10.33, "Не знаю, как благодарить тебя!" }, { 12.64, "Хоть мы тут небогаты, без награды ты не останешься." }, { 16.38, "Знай, в экспедиции Маршала у тебя есть друзья, готовые помочь в любую минуту!" } } } } },
    [3882] = { d = 39.4, v = "goblin-male", n = { x = 466 }, c = { x = { { 0.00, "Думаешь, раз в экспедиции Маршала я ответственный за раскопки, то мне страшно нравится копаться в земле?" }, { 7.01, "Нет, я, конечно, мог бы придумать более паршивое занятие, но сейчас что-то ничего не приходит в голову." }, { 14.01, "Мы должны были вести раскопки в местечке под названием Путь Ужаса – неплохое название, не находишь?" }, { 20.77, "Искать, значит, там дохлых стегодонов и деметродонов..." }, { 24.52, "А их там, между прочим, и живых полным-полно!" }, { 27.60, "Вил и Хол, видишь ли, хотят изучать это гиблое место, поэтому мы должны исправно поставлять им кости динозавров." }, { 35.28, "Между нами говоря, живые для этих целей сгодились бы не хуже!" } } }, t = { d = 26.3, g = 1, v = "goblin-male", n = { m = 283, f = 285 }, c = { m = { { 0.00, "Прекрасно, отличные кости, то, что нужно!" }, { 2.98, "А теперь, с твоего позволения..." }, { 5.30, "СПАСИБО, ЧТО ВЫРЫЛ ДЛЯ НАС ЭТИ ДРЕВНЕЙШИЕ КОСТИ И НЕ ОХОТИЛСЯ НА ЖИВОТНЫХ, ЧТО МОГЛО БЫ НАНЕСТИ НЕПОПРАВИМЫЙ УЩЕРБ ОКРУЖАЮЩЕЙ СРЕДЕ!" }, { 15.41, "Так это было или нет – знать не хочу." }, { 18.12, "Пусть так и останется, ладно?" }, { 20.19, "Вот, может, это поможет тебе держать язык за зубами." }, { 24.08, "Лишь бы выбраться отсюда живыми!" } }, f = { { 0.00, "Прекрасно, отличные кости, то, что нужно!" }, { 2.95, "А теперь, с твоего позволения..." }, { 5.26, "СПАСИБО, ЧТО ВЫРЫЛА ДЛЯ НАС ЭТИ ДРЕВНЕЙШИЕ КОСТИ И НЕ ОХОТИЛАСЬ НА ЖИВОТНЫХ, ЧТО МОГЛО БЫ НАНЕСТИ НЕПОПРАВИМЫЙ УЩЕРБ ОКРУЖАЮЩЕЙ СРЕДЕ!" }, { 15.37, "Так это было или нет – знать не хочу." }, { 18.06, "Пусть так и останется, ладно?" }, { 20.11, "Вот, может, это поможет тебе держать язык за зубами." }, { 23.96, "Лишь бы выбраться отсюда живыми!" } } } } },
    [3883] = { d = 31.4, g = 1, v = "human-female", n = { m = 385, f = 385 }, c = { m = { { 0.00, "То, что мы потерпели неудачу, ещё не значит, что исследования надо прекратить!" }, { 5.13, "Мы изучали насекомых Гориши в южной части кратера, прежде чем были вынуждены ретироваться сюда." }, { 11.59, "Их присутствие чуждо для экологии Ун'Горо, и мы должны разобраться почему." }, { 16.54, "В их ульях должны быть инкубаторы для личинок." }, { 19.61, "Эти места можно определить по свисающим гроздьям личинок." }, { 23.54, "Возьми образец стены улья рядом с инкубатором вот в этот фиал и принеси его мне на исследование." }, { 30.05, "Но будь осторожен!" } }, f = { { 0.00, "То, что мы потерпели неудачу, ещё не значит, что исследования надо прекратить!" }, { 5.18, "Мы изучали насекомых Гориши в южной части кратера, прежде чем были вынуждены ретироваться сюда." }, { 11.71, "Их присутствие чуждо для экологии Ун'Горо, и мы должны разобраться почему." }, { 16.70, "В их ульях должны быть инкубаторы для личинок." }, { 19.81, "Эти места можно определить по свисающим гроздьям личинок." }, { 23.78, "Возьми образец стены улья рядом с инкубатором вот в этот фиал и принеси его мне на исследование." }, { 30.36, "Но будь осторожна!" } } }, t = { d = 16.2, g = 1, v = "human-female", n = { m = 175, f = 177 }, c = { m = { { 0.00, "О, прекрасно, ты очень помог мне." }, { 2.55, "Хотелось бы мне дать тебе большую награду, но жизнь на лоне дикой природы накладывает свои ограничения." }, { 10.39, "Однако могу заверить, без твоей помощи наши исследования были бы невозможны." } }, f = { { 0.00, "О, прекрасно, ты очень помогла мне." }, { 2.63, "Хотелось бы мне дать тебе большую награду, но жизнь на лоне дикой природы накладывает свои ограничения." }, { 10.34, "Однако могу заверить, без твоей помощи наши исследования были бы невозможны." } } } } },
    [3884] = { d = 23.4, v = "narrator", n = { x = 257 }, c = { x = { { 0.00, "Вы обнаружили изорванный дневник." }, { 2.48, "Кое-какие страницы ещё можно прочесть, в том числе и форзац, на котором значится имя Виллидена Маршала." }, { 10.25, "Если верить написанному в дневнике, Виллидена можно найти где-то на севере кратера, куда он и его товарищи были вынуждены бежать от диких зверей, напавших на их базовый лагерь." } } }, t = { d = 10.6, g = 1, v = "human-male", n = { m = 118, f = 119 }, c = { m = { { 0.00, "Вы только взгляните на это!" }, { 2.00, "Мой дневник!" }, { 2.91, "Я думал, он утерян навсегда, как и всё, что нам пришлось бросить в базовом лагере." }, { 8.72, "Спасибо, что вернул мне его!" } }, f = { { 0.00, "Вы только взгляните на это!" }, { 1.92, "Мой дневник!" }, { 2.78, "Я думал, он утерян навсегда, как и всё, что нам пришлось бросить в базовом лагере." }, { 8.34, "Спасибо, что вернула мне его!" } } } } },
    [3901] = { d = 31.4, g = 1, v = "scourge-male#82", n = { m = 329, f = 331 }, c = { m = { { 0.00, "Ты уже продемонстрировал свой потенциал в обычных обстоятельствах, а теперь давай посмотрим, как ты будешь действовать под давлением." }, { 10.48, "Скелеты-костетрясы – ещё одни безмозглые приспешники Короля-лича – более серьёзные враги, чем зомби, с которыми ты сталкивался до этого." }, { 21.25, "Я попрошу тебя уменьшить их количество и проявить себя среди Отрёкшихся." }, { 27.03, "Не мешкай!" }, { 27.90, "Когда всё будет сделано – возвращайся ко мне." } }, f = { { 0.00, "Ты уже продемонстрировала свой потенциал в обычных обстоятельствах, а теперь давай посмотрим, как ты будешь действовать под давлением." }, { 10.29, "Скелеты-костетрясы – ещё одни безмозглые приспешники Короля-лича – более серьёзные враги, чем зомби, с которыми ты сталкивалась до этого." }, { 20.86, "Я попрошу тебя уменьшить их количество и проявить себя среди Отрёкшихся." }, { 26.50, "Не мешкай!" }, { 27.35, "Когда всё будет сделано – возвращайся ко мне." } } }, t = { d = 28.6, g = 1, v = "scourge-male#82", n = { m = 230, f = 233 }, c = { m = { { 0.00, "Отличная работа." }, { 1.67, "Ты показал, что достоин свободы, которая была тебе дана." }, { 7.29, "Многие будут ненавидеть тебя за то, кем ты стал, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрёкшихся." }, { 21.78, "Вот, возьми это и ступай своей дорогой." }, { 25.73, "Тебя ждут великие дела, герой." } }, f = { { 0.00, "Отличная работа." }, { 1.64, "Ты показала, что достойна свободы, которая была тебе дана." }, { 7.33, "Многие будут ненавидеть тебя за то, кем ты стала, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрёкшихся." }, { 21.73, "Вот, возьми это и ступай своей дорогой." }, { 25.62, "Тебя ждут великие дела, героиня." } } } } },
    [3902] = { d = 39.7, v = "scourge-male", n = { x = 401 }, c = { x = { { 0.00, "Эй, ты!" }, { 0.58, "Если ищешь, что бы такого сделать полезного, слушай сюда!" }, { 5.26, "Нам нужны свеженькие рекруты, только что из могилы, которых можно направить в Могильник, чтобы они поискали там что-нибудь стоящее из экипировки." }, { 16.85, "Скорее всего, там будут груды ящиков." }, { 19.95, "Мы надеемся, что вскоре поднимутся новые рекруты, а поскольку нам вовсе не надо, чтобы они слонялись тут голыми, надо бы поскорее чем-нибудь поживиться!" }, { 32.12, "А теперь за работу, несчастный ты мешок с костями!" }, { 36.16, "Я не собираюсь платить тем, кто еле двигается." } } }, t = { d = 12.2, v = "scourge-male", n = { x = 103 }, c = { x = { { 0.00, "Отличная работа, я так и думал, что ты не совсем бесполезное существо." }, { 6.46, "А это тебе – одна из лучших вещичек среди тех, что мы собрали." } } } } },
    [3903] = { d = 18.2, g = 1, v = "human-male", n = { m = 197, f = 198 }, c = { m = { { 0.00, "Ты показал себя надёжным героем." }, { 2.35, "Да и тяжёлой работы не боишься, не правда ли?" }, { 5.54, "У меня есть подруга, Милли Осворт." }, { 8.08, "У неё какие-то проблемы." }, { 9.84, "Она вместе со своим фургоном находится по другую сторону аббатства, у стойл." }, { 15.37, "Думаю, ей очень пригодится твоя помощь." } }, f = { { 0.00, "Ты показала себя надёжной героиней." }, { 2.48, "Да и тяжёлой работы не боишься, не правда ли?" }, { 5.60, "У меня есть подруга, Милли Осворт." }, { 8.08, "У неё какие-то проблемы." }, { 9.80, "Она вместе со своим фургоном находится по другую сторону аббатства, у стойл." }, { 15.20, "Думаю, ей очень пригодится твоя помощь." } } }, t = { d = 16.5, v = "human-female", n = { x = 193 }, c = { x = { { 0.00, "О, заместитель судьи Виллем просил тебя поговорить со мной?" }, { 4.09, "Он отважный человек и всегда готов помочь, но дела не дают ему покинуть Аббатство Североземья, да к тому же, боюсь, нынешняя моя проблема ему не по плечу." }, { 14.82, "Возможно, ты мне поможешь." } } } } },
    [3904] = { d = 29.4, v = "human-female", n = { x = 349 }, c = { x = { { 0.00, "Шайка бандитов, это Братство Справедливости, проникла в Виноградники Североземья во время сбора урожая!" }, { 7.13, "Я сообщила об этом стражникам, и они заверили меня, что разберутся с этим делом, но... я боюсь за виноград!" }, { 14.50, "Если мой урожай не украдут грабители, так наши стражники потопчут!" }, { 19.09, "Прошу тебя, помоги мне!" }, { 20.76, "Я собрала большую часть винограда в корзины, но оставила их в виноградниках на юго-востоке." }, { 26.96, "Принеси мне мой виноград, пожалуйста!" } } }, t = { d = 15.5, g = 1, v = "human-female", n = { m = 147, f = 150 }, c = { m = { { 0.00, "Ох, спасибо тебе." }, { 1.46, "Ты спас мой урожай!" }, { 3.00, "И, надеюсь, ты показал этим бандитам, что тут им хозяйничать не позволят!" }, { 8.84, "Может, стражи нам тут нынче и не достаёт, но зато у нас есть такие герои, как ты!" } }, f = { { 0.00, "Ох, спасибо тебе." }, { 1.46, "Ты спасла мой урожай!" }, { 3.22, "И, надеюсь, ты показала этим бандитам, что тут им хозяйничать не позволят!" }, { 9.15, "Может, стражи нам тут нынче и не достаёт, но зато у нас есть такие герои, как ты!" } } } } },
    [3905] = { d = 20.0, v = "human-female", n = { x = 233 }, c = { x = { { 0.00, "Теперь, когда мой урожай спасён, отнеси это уведомление о поставке винограда брату Нилзу." }, { 6.28, "Он ведает съестными припасами в Североземье, и я уверена, что он обрадуется, узнав, что у него будет свежий виноград." }, { 14.37, "Брата Нилза ты найдёшь в аббатстве, в звоннице – он там любит... дегустировать вино." } } }, t = { d = 19.6, v = "human-male", n = { x = 203 }, c = { x = { { 0.00, "Так, что у нас тут..." }, { 1.52, "Хвала Свету!" }, { 2.55, "Виноград Милли спасён!" }, { 4.28, "Когда она сказала мне, что эти бандиты разнесли её виноградники, я чуть не впал в уныние, но моя вера в Свет не дрогнула!" }, { 13.47, "И благодаря твоей отваге теперь у нас есть виноград для вина!" }, { 18.16, "Да хранит тебя Свет!" } } } } },
    [3906] = { d = 31.6, v = "tauren-male", n = { x = 290 }, c = { x = { { 0.00, "Старейшины говорят, духи стихий в последнее время неспокойны." }, { 5.56, "Дворфы Чёрного Железа вызвали в наш мир злобного духа, и теперь он угрожает вечной засухой нашим землям." }, { 14.91, "Мы должны найти причину беспокойства духов." }, { 18.86, "Отправляйся к Чёрной горе, через пропасть Пламени, прямо в карьер." }, { 24.83, "Найди там владыку огня – Подчинителя Пирона – и положи конец его злодеяниям!" } } }, t = { d = 16.5, v = "tauren-male", n = { x = 134 }, c = { x = { { 0.00, "Не может быть..." }, { 1.67, "Не может быть!" }, { 3.16, "Уничтожение Пирона лишь приоткрыло завесу над истинным положением вещей." }, { 10.61, "В глубинах Чёрной горы скрываются ещё более коварные силы." } } } } },
    [3907] = { d = 29.6, v = "tauren-male", n = { x = 257 }, c = { x = { { 0.00, "Я чувствую скверну в воздухе!" }, { 2.74, "Источник её скрывается в глубинах Чёрной горы." }, { 6.98, "Имя его в стонах земли и ветра: лорд Опалитель..." }, { 11.64, "Но это ещё не все: кто-то или что-то повелевает им." }, { 16.38, "Сам он – лишь инструмент в более могущественных руках." }, { 21.28, "Найди его и выясни, где скрывается его повелитель." }, { 26.02, "Возвращайся ко мне, когда всё разузнаешь." } } }, t = { d = 39.4, v = "tauren-male", n = { x = 350 }, c = { x = { { 0.00, "*Громосерд хватает табличку Каринья*" }, { 2.96, "Рагнарос... здесь..." }, { 4.79, "Старейшины были правы, страшась зла, исходящего от Чёрной горы." }, { 10.62, "Могущественный служитель Древних Богов!" }, { 14.29, "В НАШЕМ МИРЕ!" }, { 15.62, "Мы должны оценить наши позиции здесь, в Каргате." }, { 20.12, "Нужно решить, стоит ли остаться и драться или бежать в страхе перед новым Расколом." }, { 28.03, "Лучше больше не приближайся к Чёрной горе." }, { 31.94, "В её глубинах кроется куда более великое зло, чем всё, что встречалось тебе раньше." } } } } },
    [3908] = { d = 31.9, v = "gnome-male", n = { x = 353 }, c = { x = { { 0.00, "Видишь ли, я совершенно не представляю, как здесь оказался – просто тайна, покрытая мраком!" }, { 6.36, "Мне кажется, я вообще ничего не помню..." }, { 9.22, "Эти вещи всё же кажутся мне знакомыми..." }, { 12.09, "Мой меч." }, { 12.66, "Я должен был как-то укрепить его, но совершенно не помню зачем?" }, { 17.18, "Мне жаль, что не могу сказать тебе больше, но я и в самом деле ничего не помню." }, { 22.78, "В любом случае, я знаю куда это отнести – к Донове Снегоноре в Зимние Ключи." }, { 28.31, "Она может закалить меч в местных горячих источниках." } } }, t = { d = 10.6, v = "dwarf-female#34", n = { x = 101 }, c = { x = { { 0.00, "Ну конечно, я могу закалить меч." }, { 2.74, "А пока я работаю, расскажи мне, что так задержало Линкена." }, { 7.60, "Обычно он не забывает о важных вещах." } } } } },
    [3909] = { d = 35.6, v = "dwarf-female#34", n = { x = 356 }, c = { x = { { 0.00, "Что такое?" }, { 0.85, "Линкен ЗАБЫЛ ВСЁ?" }, { 2.26, "Ясно, потеря памяти..." }, { 4.10, "Вот его меч." }, { 5.09, "Он не закончен." }, { 6.29, "Я знаю, кто может закончить его, но..." }, { 9.33, "Поговорить с ним – непростая задача." }, { 12.15, "Однако, я знаю, кто сможет тебе помочь." }, { 15.33, "Не буду вдаваться в подробности прямо сейчас, скажу только, что тебе необходимо любым способом заполучить эликсир Видере." }, { 24.94, "Единственный, кто может помочь тебе в этом – Греган Пивоплюй." }, { 29.82, "Его нелегко отыскать, но говорят, что недавно его видели в лесах Фераласа." } } }, t = { d = 7.9, v = "dwarf-female#34", n = { x = 69 }, c = { x = { { 0.00, "Мне нужна одна склянка эликсира, чтобы проверить, правильный ли это состав..." }, { 7.03, "Да, это он." } } } } },
    [3911] = { d = 47.5, v = "scourge-female#80", n = { x = 438 }, c = { x = { { 0.00, "У меня есть работа для тех, кто не боится сунуться в глубины!" }, { 5.51, "Клан Чёрного Железа научился создавать чрезвычайно мощных големов." }, { 11.51, "Исходя из отчётов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим творениям невероятную разрушительную силу." }, { 25.81, "Подумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют..." }, { 36.42, "Можешь перевернуть город вверх дном, но я должна получить эту сущность." }, { 42.91, "Без неё можешь не возвращаться!" }, { 45.71, "По усердию и награда." } } }, t = { d = 9.0, v = "scourge-female#80", n = { x = 77 }, c = { x = { { 0.00, "Замечательно!" }, { 1.29, "Я немедленно отправлю их курьером в Подгород!" }, { 5.60, "Для вас - оплата, как и было обещано." } } } } },
    [3912] = { d = 35.1, v = "dwarf-female#34", n = { x = 378 }, c = { x = { { 0.00, "Этот эликсир позволит тебе говорить с существами, которые обычно незримы." }, { 5.66, "Возьми эликсир Видере и меч Линкена и отправляйся на кладбище на окраине Прибамбасска в Танарисе." }, { 12.96, "Будешь на месте, выпей эликсир." }, { 15.42, "Результат может показаться тебе неожиданным, но не впадай в панику." }, { 20.53, "В том обличье, которое ты примешь, отправляйся на север, в горы." }, { 25.38, "Тот, кто тебе нужен, скрывается в скалистых ущельях." }, { 29.33, "Его имя Гаэриан." }, { 30.70, "Помни, ты сможешь поговорить с ним только переменив облик..." } } }, t = { d = 2.4, v = "human-male", n = { x = 29 }, c = { x = { { 0.00, "Давненько никто не говорил со мной..." } } } } },
    [3913] = { d = 11.5, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Когда вернёшься на кладбище, увидишь там могильный камень, стоящий особняком." }, { 5.98, "Под ним скрываются многие секреты!" }, { 8.65, "Отодвинь его, и тайны откроются тебе!" } } }, t = { d = 10.6, v = "narrator", n = { x = 115 }, c = { x = { { 0.00, "Камень отодвинут в сторону, под ним находится небольшое углубление." }, { 5.15, "Положив в него меч Линкена, вы понимаете, что меч идеально ложится туда." } } } } },
    [3914] = { d = 9.8, v = "narrator", n = { x = 95 }, c = { x = { { 0.00, "Вокруг меча вспыхивает ослепительно яркое пламя." }, { 4.23, "После того как оно угасло, вы можете снова взять меч." }, { 8.84, "Он изменился!" } } }, t = { d = 8.5, v = "gnome-male", n = { x = 75 }, c = { x = { { 0.00, "Мой меч, он закончен!" }, { 1.81, "Вспомнить бы ещё, на что он мне сдался..." }, { 5.26, "Дай-ка я пока заплачу тебе за работу." } } } } },
    [3921] = { d = 29.1, v = "goblin-male", n = { x = 327 }, c = { x = { { 0.00, "Мне кажется, я сломал самофланж." }, { 2.34, "Это плохо, потому что я успел рассказать о нём нескольким коллегам из Нижней шахты, и они очень заинтригованы." }, { 10.34, "Надо починить его!" }, { 11.77, "Отнеси сломанный самофланж Венаки Бенике, которая живёт на юге от заставы Мор'шан, лагеря Орды между Степями и Ясеневым лесом." }, { 21.01, "Она очень умная и любопытная." }, { 23.22, "Покажи ей самофланж, и я не сомневаюсь, что она не упустит возможности починить его." } } }, t = { d = 17.4, v = "goblin-female#63", n = { x = 159 }, c = { x = { { 0.00, "Что это?" }, { 0.77, "Самофланж, говоришь?" }, { 2.54, "Что такое самофланж?" }, { 4.30, "А..." }, { 4.69, "Посмотри, как он вибрирует, когда берёшь его в руки." }, { 9.14, "А внутри жужжат сложные шестерёнки." }, { 12.14, "Ух ты!" }, { 12.68, "Мне хочется починить его и узнать, что он умеет!" }, { 16.83, "А тебе?" } } } } },
    [3922] = { d = 24.7, v = "goblin-female#63", n = { x = 305 }, c = { x = { { 0.00, "Я готова заняться самофланжем, но для этого мне понадобятся запчасти." }, { 4.68, "У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для работы понадобится целая куча." }, { 12.37, "Проще всего их достать у Нефтяного болота на востоке." }, { 16.06, "Торговая Компания обычно хранит их в вёдрах с инструментами." }, { 20.12, "Ступай туда и поищи эти штуковины, а набрав достаточно, возвращайся." } } }, t = { d = 4.6, g = 1, v = "goblin-female#63", n = { m = 39, f = 41 }, c = { m = { { 0.00, "О, ты принёс их!" }, { 1.29, "Теперь я могу приступить к работе..." } }, f = { { 0.00, "О, ты принесла их!" }, { 1.57, "Теперь я могу приступить к работе..." } } } } },
    [3923] = { d = 32.4, v = "goblin-female#63", n = { x = 371 }, c = { x = { { 0.00, "Увы, у меня ничего не вышло." }, { 2.11, "Я добавила в самофланж несколько новых индикаторов, чтобы проверить его структурную целостность, и согласно им, структурная целостность на нуле." }, { 12.28, "Я могу добавить пару циферблатов и рычаг-другой, но..." }, { 16.18, "Думаю, станет только хуже." }, { 18.16, "Отнеси самофланж Рилли Грязегобу." }, { 20.59, "Он работал на Торговую Компанию, и уж если Рилли не сможет починить эту штуку, то пиши пропало." }, { 27.43, "Он работает в механической мастерской Ногга в Оргриммаре, в Аллее Чести." } } }, t = { d = 13.3, g = 1, v = "goblin-male#65", n = { m = 123, f = 124 }, c = { m = { { 0.00, "Что это?" }, { 0.75, "Надо же, самофланж." }, { 2.41, "Откуда он у тебя?" }, { 3.92, "Неужели ты рыскал по владениям Торговой Компании в Степях?" }, { 8.82, "Интересно, это говорит о смелости или о глупости?" } }, f = { { 0.00, "Что это?" }, { 0.77, "Надо же, самофланж." }, { 2.47, "Откуда он у тебя?" }, { 4.02, "Неужели ты рыскала по владениям Торговой Компании в Степях?" }, { 9.11, "Интересно, это говорит о смелости или о глупости?" } } } } },
    [3924] = { d = 28.5, v = "goblin-male#65", n = { x = 306 }, c = { x = { { 0.00, "Думаю, я смогу починить самофланж, но для этого мне понадобится руководство пользователя." }, { 6.93, "В Торговой Компании у меня был соперник, начальник Медноклин." }, { 11.74, "Он ревностно хранил тайны самофланжа и лишь частицы знания доверял самым надёжным своим сторонникам." }, { 19.58, "Я не входил в число избранных..." }, { 22.13, "Начальник Медноклин работает в северо-восточной части Степей, на Каменном карьере." } } }, t = { d = 18.7, g = 1, v = "goblin-male#65", n = { m = 202, f = 204 }, c = { m = { { 0.00, "Ты принёс руководство!" }, { 1.62, "Мне не терпится узнать, как починить самофланж!" }, { 5.13, "Я говорил с Пароклапаном из Кабестана, и он просил поблагодарить тебя за услуги и вознаградить за них." }, { 12.61, "Я тоже весьма признателен, и если починю-таки эту штуку, сразу тебе сообщу..." } }, f = { { 0.00, "Ты принесла руководство!" }, { 1.83, "Мне не терпится узнать, как починить самофланж!" }, { 5.36, "Я говорил с Пароклапаном из Кабестана, и он просил поблагодарить тебя за услуги и вознаградить за них." }, { 12.90, "Я тоже весьма признателен, и если починю-таки эту штуку, сразу тебе сообщу..." } } } } },
    [3941] = { d = 31.2, v = "gnome-male", n = { x = 350 }, c = { x = { { 0.00, "Думай, голова!" }, { 1.06, "Думай, шапку подарю..." }, { 2.68, "Я помню, что явился сюда с какой-то очень серьёзной целью." }, { 6.74, "Но совсем не помню с какой!" }, { 8.68, "Есть идея!" }, { 9.43, "Вон там, в пещерах живёт гномесса по имени Джей Ди, я помню, она была очень добра ко мне, когда я впервые оказался здесь." }, { 17.73, "Может, она сможет что-то рассказать." }, { 20.35, "Спроси её!" }, { 21.10, "Только осторожней, она всё время возится с этими ужасными светящимися кристаллами, которых полно в этом кратере." }, { 28.97, "Не знаю, зачем уж они ей нужны..." } } }, t = { d = 6.1, v = "gnome-female", n = { x = 56 }, c = { x = { { 0.00, "Стой на месте, не шевелись..." }, { 2.53, "Я испытываю новую комбинацию кристаллов..." } } } } },
    [3942] = { d = 37.8, v = "gnome-female", n = { x = 404 }, c = { x = { { 0.00, "О, Линкен?" }, { 0.81, "Да, смешной парень..." }, { 2.42, "Когда он впервые оказался здесь, бормотал всякую ерунду." }, { 6.64, "Наверное, кто-то как следует двинул бедняге по голове!" }, { 10.73, "Однако кое-что из той чепухи, которую он нёс, крепко засело у меня в памяти." }, { 16.44, "Помню, он говорил, что делает какой-то тотем, и что ему необходимо поговорить с какой-то Эриданой Грустью Ветра... кажется, в месте, называемом Осквернённый лес." }, { 28.31, "Вряд ли он сам сейчас много тебе расскажет." }, { 31.53, "Думаю, если хочешь узнать больше, тебе следует отправиться прямиком к этой Эридане." } } }, t = { d = 3.8, g = 1, v = "nightelf-female", n = { x = 37 }, c = { m = { { 0.00, "Приветствую тебя, герой." }, { 1.69, "Могу ли я чем-то помочь тебе?" } }, f = { { 0.00, "Приветствую тебя, героиня." }, { 1.83, "Могу ли я чем-то помочь тебе?" } } } } },
    [3961] = { d = 22.7, v = "gnome-female", n = { x = 257 }, c = { x = { { 0.00, "Лично я полагаю, что Линкен явился сюда, чтобы избавить нас от Яропламеня..." }, { 5.51, "Он кажется простым парнем, однако он совсем не интересуется моими экспериментами и механизмами, как большинство гномов." }, { 13.99, "Должно быть, в глубине души он истинный воин." }, { 17.29, "Отдай тотем ему." }, { 18.59, "Возможно, это поможет ему вспомнить, зачем он пришёл сюда." } } }, t = { d = 3.5, v = "gnome-male", n = { x = 36 }, c = { x = { { 0.00, "Джей Ди вообще хоть чем-нибудь помогла тебе?" } } } } },
    [3962] = { d = 32.4, g = 1, v = "gnome-male", n = { m = 339, f = 339 }, c = { m = { { 0.00, "Я наконец-то вспомнил..." }, { 1.84, "Я пришёл сюда, чтобы сразиться с Яропламенем!" }, { 5.26, "Это и есть цель моего путешествия!" }, { 7.86, "Но я больше не герой... потому что герой стоит передо мной." }, { 12.37, "Теперь ты должен закончить начатое." }, { 15.10, "Яропламень стережёт артефакт, именуемый Золотым пламенем." }, { 19.41, "В нём кроется сила более мощная, чем что-либо мне известное, поэтому этот артефакт не должен попасть в дурные руки." }, { 28.22, "И мой тебе совет – не ходи один." }, { 30.75, "Один в поле не воин." } }, f = { { 0.00, "Я наконец-то вспомнил..." }, { 1.85, "Я пришёл сюда, чтобы сразиться с Яропламенем!" }, { 5.29, "Это и есть цель моего путешествия!" }, { 7.90, "Но я больше не герой... потому что герой стоит передо мной." }, { 12.43, "Теперь ты должна закончить начатое." }, { 15.18, "Яропламень стережёт артефакт, именуемый Золотым пламенем." }, { 19.50, "В нём кроется сила более мощная, чем что-либо мне известное, поэтому этот артефакт не должен попасть в дурные руки." }, { 28.36, "И мой тебе совет – не ходи одна." }, { 30.90, "Один в поле не воин." } } }, t = { d = 16.9, v = "gnome-male", n = { x = 189 }, c = { x = { { 0.00, "Спасибо." }, { 0.64, "Теперь Золотое пламя будет возвращено на мою родину, где мы сможем защитить его от посягающих на него негодяев." }, { 8.71, "Если бы не ты, я до сих пор не помнил бы, кто я такой и зачем пришёл!" }, { 13.48, "Я хочу отблагодарить тебя!" }, { 15.41, "Бери всё что нравится!" } } } } },
    [3981] = { d = 43.6, g = 1, v = "tauren-male#68", n = { m = 395, f = 395 }, c = { m = { { 0.00, "Бедняга Гаргал..." }, { 1.65, "Он даже не успел ничего понять как – бац! – стрела вонзилась прямо ему в башку..." }, { 9.16, "Он и прежде гением не был, а теперь уж..." }, { 12.88, "*Гэлмав скорбно морщится.*" }, { 15.20, "Когда мы вытащили стрелу, заметили записку, прикрученную к древку." }, { 20.65, "В ней не было ничего, кроме грубо нацарапанной картинки, изображающей, видимо, орка за решёткой, и подписи командира Гор'шака." }, { 30.87, "Если он ещё жив и находится в Глубинах, ты должен отыскать его." }, { 36.02, "Ловушка, говоришь?" }, { 37.57, "Ясное дело, ловушка, дубина копытная!" }, { 40.73, "Потому туда и пойдёшь ты!" } }, f = { { 0.00, "Бедняга Гаргал..." }, { 1.62, "Он даже не успел ничего понять как – бац! – стрела вонзилась прямо ему в башку..." }, { 8.99, "Он и прежде гением не был, а теперь уж..." }, { 12.58, "*Гэлмав скорбно морщится.*" }, { 15.05, "Когда мы вытащили стрелу, заметили записку, прикрученную к древку." }, { 20.27, "В ней не было ничего, кроме грубо нацарапанной картинки, изображающей, видимо, орка за решёткой, и подписи командира Гор'шака." }, { 31.65, "Если он ещё жив и находится в Глубинах, ты должна отыскать его." }, { 36.89, "Ловушка, говоришь?" }, { 38.46, "Ясное дело, ловушка, дубина копытная!" }, { 41.68, "Потому туда и пойдёшь ты!" } } }, t = { d = 11.0, g = 1, v = "orc-male#60", n = { x = 98 }, c = { m = { { 0.00, "У нас мало времени." }, { 1.68, "Слушай внимательно, герой." }, { 3.98, "Сведения, которые я сообщу тебе, совершенно секретны и не подлежат разглашению." } }, f = { { 0.00, "У нас мало времени." }, { 1.72, "Слушай внимательно, героиня." }, { 4.23, "Сведения, которые я сообщу тебе, совершенно секретны и не подлежат разглашению." } } } } },
    [3982] = { d = 34.6, v = "orc-male#60", n = { x = 343 }, c = { x = { { 0.00, "Меня прислал сюда Тралл, и я нахожусь под его покровительством." }, { 4.98, "Неужели ты думаешь, что эти фигляры смогли бы меня поймать?" }, { 9.75, "Я разведчик, и я им поддался специально, чтобы собрать информацию." }, { 14.88, "*Гор'шак понижает голос.*" }, { 17.12, "Император Тауриссан похитил принцессу Стальгорна." }, { 20.99, "Она сейчас здесь, в этом городе!" }, { 23.64, "Надо думать, когда старый Магни об этом узнал, его чуть удар не хватил." }, { 29.44, "*Гор'шак смеётся.*" }, { 31.04, "Тихо!" }, { 31.60, "Слышишь?" }, { 32.40, "Это стражники!" }, { 33.76, "ЗАЩИЩАЙСЯ!" } } }, t = { d = 8.3, v = "orc-male#60", n = { x = 74 }, c = { x = { { 0.00, "На этот раз всё обошлось." }, { 2.28, "Но теперь они поднимут тревогу... и пришлют за тобой ещё стражников." } } } } },
    [4001] = { d = 33.6, v = "orc-male#60", n = { x = 366 }, c = { x = { { 0.00, "Пока что мне не удалось толком поговорить с Караном из темницы напротив." }, { 5.28, "Однако я всё-таки смог убедить его в том, что я – то есть мы – не обидим его и не сделаем ему ничего плохого." }, { 13.14, "Поговори с ним и попробуй узнать о принцессе и её похитителях." }, { 17.63, "Всю информацию, которую удастся собрать, передай вождю." }, { 21.73, "Тралл не хочет, чтобы с принцессой что-то случилось." }, { 25.56, "У него даже есть план, как вернуть её в целости и сохранности в Стальгорн, и Карану всё это уже известно..." }, { 33.35, "Иди!" } } }, t = { d = 19.3, v = "named/thrall", n = { x = 183 }, c = { x = { { 0.00, "Сейчас у Орды есть шанс изменить политическую ситуацию в нашем мире, истерзанном войной." }, { 7.81, "Причём изменить радикально." }, { 10.20, "Раз и навсегда." }, { 11.55, "Слушай внимательно." }, { 13.31, "Постарайся, чтобы всё получилось." }, { 16.25, "Провал в этом деле смерти подобен." } } } } },
    [4002] = { d = 32.3, g = 1, v = "named/thrall", n = { m = 320, f = 321 }, c = { m = { { 0.00, "Принесённые тобой сведения чрезвычайно ценны." }, { 3.84, "Я – вождь, и мой долг – действовать на благо Орды, так, чтобы грядущие поколения не были обречены на безнадёжное прозябание!" }, { 14.13, "И вот нам выпала возможность определить судьбу будущих союзов." }, { 19.42, "Выступив на помощь дворфам, мы значительно укрепим свои взаимоотношения с Восточными королевствами." }, { 27.79, "Вот почему твой долг – вернуться с победой!" }, { 31.40, "Готов ли ты?" } }, f = { { 0.00, "Принесённые тобой сведения чрезвычайно ценны." }, { 3.79, "Я – вождь, и мой долг – действовать на благо Орды, так, чтобы грядущие поколения не были обречены на безнадёжное прозябание!" }, { 13.95, "И вот нам выпала возможность определить судьбу будущих союзов." }, { 19.19, "Выступив на помощь дворфам, мы значительно укрепим свои взаимоотношения с Восточными королевствами." }, { 27.45, "Вот почему твой долг – вернуться с победой!" }, { 31.02, "Готова ли ты?" } } }, t = { d = 3.5, v = "named/thrall", n = { x = 21 }, c = { x = { { 0.00, "Всё." }, { 0.60, "Отныне пути назад нет." } } } } },
    [4003] = { d = 29.0, v = "named/thrall", n = { x = 300 }, c = { x = { { 0.00, "Этот удар, нанесённый дворфам Чёрного Железа, способен потрясти их королевство до основания." }, { 7.33, "Принцесса находится под контролем императора Тауриссана." }, { 11.83, "Чтобы её освободить, необходимо убить императора." }, { 15.83, "Имей в виду, твоя задача вдвойне опасна: пока принцесса находится во власти императора, она нападёт на тебя, не раздумывая." }, { 25.85, "Ни в коем случае не причиняй ей вреда!!!" } } }, t = { d = 2.2, g = 1, v = "dwarf-female", n = { m = 12, f = 13 }, c = { m = { { 0.00, "Что ты наделал!" } }, f = { { 0.00, "Что ты наделала!" } } } } },
    [4004] = { d = 43.2, g = 1, v = "dwarf-female", n = { m = 419, f = 422 }, c = { m = { { 0.00, "Ты убил моего мужа, герой!" }, { 2.59, "Мой ребёнок родится на свет без отца!" }, { 5.84, "*Принцесса Мойра указывает на вас.*" }, { 8.96, "Истинно говорю тебе, это дитя станет следующим королём Стальгорна." }, { 14.45, "И тогда берегись!" }, { 15.92, "Этим преступным деянием ты навлёк на себя проклятие." }, { 20.17, "Возмездие настигнет тебя и твой род." }, { 23.10, "Всех вас будут травить до скончания дней!" }, { 26.32, "*Вы уверены, что принцесса Мойра до сих пор пребывает под действием чар Тауриссана.*" }, { 32.48, "Оставь меня, герой." }, { 34.00, "Поторопись к своему нанимателю." }, { 36.32, "Наверняка он с нетерпением ждёт вестей об исполнении его гнусных замыслов." } }, f = { { 0.00, "Ты убила моего мужа, героиня!" }, { 2.94, "Мой ребёнок родится на свет без отца!" }, { 6.32, "*Принцесса Мойра указывает на вас.*" }, { 9.44, "Истинно говорю тебе, это дитя станет следующим королём Стальгорна." }, { 15.09, "И тогда берегись!" }, { 16.60, "Этим преступным деянием ты навлекла на себя проклятие." }, { 21.19, "Возмездие настигнет тебя и твой род." }, { 24.21, "Всех вас будут травить до скончания дней!" }, { 27.52, "*Вы уверены, что принцесса Мойра до сих пор пребывает под действием чар Тауриссана.*" }, { 33.68, "Оставь меня, героиня." }, { 35.38, "Поторопись к своему нанимателю." }, { 37.77, "Наверняка он с нетерпением ждёт вестей об исполнении его гнусных замыслов." } } }, t = { d = 32.5, g = 1, v = "named/thrall", n = { m = 307, f = 308 }, c = { m = { { 0.00, "*Тралл поражён вашим рассказом.*" }, { 2.60, "*Он явно не ожидал ничего подобного.*" }, { 5.68, "Стало быть, надо ждать новой угрозы." }, { 8.78, "Магни уже немолод, кто знает, сколько ему осталось." }, { 13.24, "А если Магни не станет, дорога к трону Стальгорна будет открыта для ещё не рождённого отпрыска Чёрного Железа." }, { 22.38, "Ты исполнил моё поручение и получишь награду." }, { 26.16, "А теперь оставь