    [4005] = { d = 30.4, g = 1, v = "nightelf-female", n = { m = 366, f = 366 }, c = { m = { { 0.00, "Возьми этот мешок с припасами и отнеси в Танарис." }, { 3.45, "Отправляйся в Бухту Сорванных Парусов и найди круг камней." }, { 7.45, "Разгадка – на самом восточном полуострове..." }, { 10.47, "Встав в этот круг, прочти заклинание из книги Аквора и вызови единственное создание, способное превратить собранные тобой предметы в тотем, с помощью которого можно сразить Яропламеня!" }, { 23.03, "Аквамонтос не любит, когда его будят, но помни, ты должен быть внутри круга, когда будешь читать заклинание!" } }, f = { { 0.00, "Возьми этот мешок с припасами и отнеси в Танарис." }, { 3.37, "Отправляйся в Бухту Сорванных Парусов и найди круг камней." }, { 7.27, "Разгадка – на самом восточном полуострове..." }, { 10.22, "Встав в этот круг, прочти заклинание из книги Аквора и вызови единственное создание, способное превратить собранные тобой предметы в тотем, с помощью которого можно сразить Яропламеня!" }, { 22.49, "Аквамонтос не любит, когда его будят, но помни, ты должна быть внутри круга, когда будешь читать заклинание!" } } }, t = { d = 20.7, v = "gnome-female", n = { x = 223 }, c = { x = { { 0.00, "Яропламень, говоришь..." }, { 1.81, "Да, я знаю, этот могучий элементаль обитает в опалённом центре кратера." }, { 7.33, "Мы все стараемся держаться от этого места подальше – никому не удавалось проникнуть сквозь ауру этого создания." }, { 15.91, "Многие смельчаки нашли свою смерть в расщелинах сердца кратера." } } } } },
    [4021] = { d = 35.9, v = "orc-male#60", n = { x = 383 }, c = { x = { { 0.00, "Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости." }, { 6.60, "Я получил сообщение, что отряд клана Колкар оставил свой дом в Пустошах и прибыл в Степи, движимый местью." }, { 14.70, "Более того, они прямо сейчас подбираются к нам с запада!" }, { 19.10, "Выступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям." }, { 25.83, "Убивай их, пока не появится их вождь, предводитель Кром'зар." }, { 30.37, "Одолей его и принеси в доказательство кусок его знамени." }, { 34.76, "Не подведи меня." } } }, t = { d = 12.5, g = 1, v = "orc-male#60", n = { m = 104, f = 106 }, c = { m = { { 0.00, "Получилось!" }, { 1.15, "Ты победил клан Колкар!" }, { 3.45, "Я непременно сообщу Траллу о твоих подвигах." }, { 7.87, "Можешь гордиться собой, ты – достойный сын Орды." } }, f = { { 0.00, "Получилось!" }, { 1.11, "Ты победила клан Колкар!" }, { 3.42, "Я непременно сообщу Траллу о твоих подвигах." }, { 7.70, "Можешь гордиться собой, ты – достойная дочь Орды." } } } } },
    [4022] = { d = 9.4, g = 1, v = "creature/dragon", n = { m = 64, f = 66 }, c = { m = { { 0.00, "Стая знает о твоей работе в Тлеющем ущелье." }, { 4.45, "Покажи её, герой." }, { 6.23, "Шкуру, кретин безмозглый." } }, f = { { 0.00, "Стая знает о твоей работе в Тлеющем ущелье." }, { 4.67, "Покажи её, героиня." }, { 6.72, "Шкуру, кретинка безмозглая." } } }, t = { d = 9.1, g = 1, v = "creature/dragon", n = { m = 74, f = 74 }, c = { m = { { 0.00, "*Цирус изучает шкуру.*" }, { 2.48, "Ну что ж, тебе удалось доказать, что ты хоть на что-то пригоден, смертный." } }, f = { { 0.00, "*Цирус изучает шкуру.*" }, { 2.32, "Ну что ж, тебе удалось доказать, что ты хоть на что-то пригодна, смертная." } } } } },
