    [4024] = { d = 41.1, v = "creature/dragon", n = { x = 339 }, c = { x = { { 0.00, "Я хочу попробовать обжигающие языки пламени огненной горы." }, { 5.93, "Чтобы сквозь меня текла лава Чёрной горы." }, { 10.15, "Я жажду этого обжигающего тепла." }, { 13.47, "Бейл'Гор живёт в глубинах Чёрной горы." }, { 17.24, "Он воплощение пламени, порождение огня Рагнароса." }, { 22.18, "Убей Бейл'Гора и возьми из его дымящихся останков частицу его внутреннего огня." }, { 30.26, "Чтобы взять, не обжигаясь, этот огонь, воспользуйся драконьей шкурой." }, { 37.17, "Добейся успеха, и награда будет велика." } } }, t = { d = 9.6, v = "creature/dragon", n = { x = 73 }, c = { x = { { 0.00, "*Цирус выхватывает сущность Огня у вас из рук.*" }, { 3.84, "ДА!" }, { 4.29, "Бери награду и убирайся." }, { 7.43, "Долой с глаз моих!" } } } } },
    [4041] = { t = { d = 3.7, v = "dwarf-male", n = { x = 37 }, c = { x = { { 0.00, "Ну что, удалось тебе обойти старого Миблона, а?" } } } } },
    [4061] = { d = 32.6, v = "scourge-female#79", n = { x = 355 }, c = { x = { { 0.00, "Впервые мы увидели эти машины, когда начали набеги в Тлеющее ущелье." }, { 5.40, "Потом выяснилось, что их привозят из Пылающих степей, вероятно, из глубин Чёрной горы." }, { 11.97, "Нам нужна твоя помощь." }, { 13.77, "Для выполнения первого задания отправляйся в Пылающие степи и извлеки осколки элементалей из каменных машин и малых каменных созданий, которых там найдёшь." }, { 25.59, "Когда соберёшь достаточно, возвращайся ко мне, и я попробую разобраться, откуда они происходят." } } }, t = { d = 13.4, v = "scourge-female#79", n = { x = 120 }, c = { x = { { 0.00, "*Теодора раскладывает перед собой осколки и рассматривает их в огромную лупу.*" }, { 5.84, "Прелюбопытно..." }, { 7.58, "На каждом из этих осколков выгравированы... инициалы." } } } } },
    [4062] = { d = 32.5, v = "scourge-female#79", n = { x = 329 }, c = { x = { { 0.00, "Гэ, Эл, А." }, { 0.81, "Эти инициалы выгравированы на осколках элементалей." }, { 4.99, "Под ними выгравирована надпись, видимо, указующая на ранг машины." }, { 10.27, "Механизмы, уничтоженные тобой в Пылающих степях, имели четвёртый ранг." }, { 15.91, "Полагаю, это один из низших рангов." }, { 18.92, "Возьми этот образец осколка и отнеси его Лотвилю Вериатусу в лагерь на востоке." }, { 25.52, "Он учёный, весьма признанный в сферах изучения стихий." }, { 29.92, "Возможно, он поможет нам советом." } } }, t = { d = 4.8, v = "gnome-male", n = { x = 38 }, c = { x = { { 0.00, "*Лотвил неожиданно бледнеет*" }, { 2.72, "Я узнаю эти знаки..." } } } } },
    [4063] = { d = 42.6, v = "gnome-male", n = { x = 495 }, c = { x = { { 0.00, "Неужели это Аргелмах?" }, { 1.57, "Не может быть!" }, { 2.57, "Он же погиб десять лет назад!" }, { 4.64, "Почему я так в этом уверен?" }, { 6.59, "Да потому что это я убил его!" }, { 8.72, "Этот презренный дворф имел маниакальную страсть к извращению моих изобретений – над которыми я, к слову, корпел годами! – и использованию их для своих мерзких делишек." }, { 20.20, "Надо же, самые мерзкие создания всегда самые живучие!" }, { 24.03, "Если это и правда работа Аргелмаха, то он должен быть уничтожен." }, { 28.54, "И мне потребуются образцы его последних творений." }, { 31.99, "Если у меня будут образцы, возможно, я смогу придумать, как подавить восстание." }, { 37.58, "Видимо, Аргелмах теперь в глубинах Чёрной горы под охраной своих творений." } } }, t = { d = 15.6, v = "gnome-male", n = { x = 160 }, c = { x = { { 0.00, "Что это?!" }, { 0.74, "Голова..." }, { 1.48, "Она не из плоти и крови!" }, { 3.37, "Это какое-то создание из чёрного железа!" }, { 6.40, "Аргелмах был ЕЩЁ ОДНОЙ машиной!" }, { 9.12, "Полагаю, в таком случае нам рано праздновать победу – на его место вскоре придёт другой!" } } } } },
    [4081] = { d = 31.5, v = "narrator", n = { x = 372 }, c = { x = { { 0.00, "По приказу полководца Клинозуба, командира каргатского экспедиционного отряда:" }, { 5.70, "Все силы генерала Кузни Гнева в Глубинах Чёрной горы должны быть истреблены." }, { 11.33, "Клан Кузни Гнева – беспощадные убийцы, ответственные за уничтожение сто девятого подразделения каргатского экспедиционного отряда." }, { 20.74, "Необходимо сохранять бдительность." }, { 23.25, "Тот, кто сможет разбить передовые войска генерала Кузни Гнева в Глубинах Чёрной горы, будет представлен к награде." } } }, t = { d = 14.6, v = "orc-male#60", n = { x = 142 }, c = { x = { { 0.00, "Небось, после такого Кузня Гнева в штаны наложил!" }, { 4.28, "Теперь проходи, проходи, солдат." }, { 7.06, "У меня ещё масса дел!" }, { 8.86, "Смотри внимательно на объявления, для тебя может найтись ещё работёнка." } } } } },
    [4082] = { d = 33.3, g = 1, v = "narrator", n = { m = 401, f = 402 }, c = { m = { { 0.00, "Приказ полководца Клинозуба, командира Каргатского экспедиционного корпуса:" }, { 5.43, "Глава разведывательного подразделения Каргатского экспедиционного корпуса, гроссмейстер Лекслорт вернулся с рапортом о месторасположении высокопоставленных чинов Чёрного Железа." }, { 17.99, "В центре города, за закрытыми воротами они обучают своих солдат уничтожать наших собратьев." }, { 24.73, "Отправляйся в Глубины Чёрной горы и уничтожь их!" }, { 28.20, "В случае успешного выполнения задания будешь представлен к награде." } }, f = { { 0.00, "Приказ полководца Клинозуба, командира Каргатского экспедиционного корпуса:" }, { 5.47, "Глава разведывательного подразделения Каргатского экспедиционного корпуса, гроссмейстер Лекслорт вернулся с рапортом о месторасположении высокопоставленных чинов Чёрного Железа." }, { 18.13, "В центре города, за закрытыми воротами они обучают своих солдат уничтожать наших собратьев." }, { 24.92, "Отправляйся в Глубины Чёрной горы и уничтожь их!" }, { 28.42, "В случае успешного выполнения задания будешь представлена к награде." } } }, t = { d = 19.8, v = "orc-male#60", n = { x = 189 }, c = { x = { { 0.00, "Не сомневаюсь, генерал Кузня Гнева теперь... в гневе." }, { 4.56, "Возвращайся ко мне, когда получишь третью награду, и мы приступим к операции \"Смерть Кузне Гнева\"." }, { 12.77, "Пока не буду вдаваться в детали, но могу заверить наперёд, что точно кто-нибудь умрёт!" } } } } },
    [4083] = { t = { d = 4.8, v = "narrator", n = { x = 44 }, c = { x = { { 0.00, "Драгоценные камни беззвучно падают в глубину кубка..." } } } } },
    [4084] = { d = 35.6, v = "nightelf-female", n = { x = 395 }, c = { x = { { 0.00, "Я не знаю, о ком ты говоришь." }, { 2.09, "Однако если твой друг искал меня, я знаю, что ему было нужно." }, { 6.68, "В сердце Кратера Ун'Горо скрывается зло в чистейшей его форме – это элементаль, именуемый Яропламень." }, { 14.08, "Он защищён аурой, разрушить которую не под силу никому..." }, { 18.20, "Никому, кроме обладателя ещё большей силы." }, { 21.34, "Я научу тебя, как справиться с этой задачей." }, { 24.62, "Сначала сделай, что я попрошу." }, { 26.84, "Собери и принеси мне одиннадцать серебристых когтей и одно сердце Железнолесья – ты найдёшь их у созданий Осквернённого леса." } } }, t = { d = 4.2, g = 1, v = "nightelf-female", n = { m = 41, f = 42 }, c = { m = { { 0.00, "Прекрасно." }, { 0.89, "Вижу, ты всегда готов помогать друзьям." } }, f = { { 0.00, "Прекрасно." }, { 0.89, "Вижу, ты всегда готова помогать друзьям." } } } } },
    [4101] = { d = 35.6, v = "nightelf-female", n = { x = 414 }, c = { x = { { 0.00, "Растения дают жизнь Осквернённому лесу, но даже они поражены порчей." }, { 4.76, "Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или кого не знаю." }, { 12.39, "Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!" }, { 16.65, "К северу отсюда лежат пещеры Железнолесья." }, { 19.66, "Тамошние криводревы-элементали поражены порчей так, что исцелить их уже нет надежды." }, { 25.48, "Прошу тебя – принеси мне их застывший сок – его называют кровавым янтарём – чтобы я могла изучить его в надежде спасти другие формы здешней жизни." } } }, t = { d = 32.5, g = 1, v = "nightelf-female", n = { m = 404, f = 406 }, c = { m = { { 0.00, "Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Осквернённый лес." }, { 6.21, "Ты доказал мне, что готов сделать всё для Круга Кенария." }, { 9.94, "Теперь я доверяю тебе." }, { 11.51, "Может показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства." }, { 23.02, "Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов, которые я смогу сделать." }, { 29.53, "Пришла пора исцелить Осквернённый лес." } }, f = { { 0.00, "Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Осквернённый лес." }, { 6.29, "Ты доказала мне, что готова сделать всё для Круга Кенария." }, { 10.20, "Теперь я доверяю тебе." }, { 11.79, "Может показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства." }, { 23.46, "Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов, которые я смогу сделать." }, { 30.06, "Пришла пора исцелить Осквернённый лес." } } } } },
    [4102] = { d = 40.9, v = "tauren-female", n = { x = 410 }, c = { x = { { 0.00, "Растения дают жизнь Осквернённому лесу, но даже они поражены порчей." }, { 5.52, "Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или не знаю." }, { 13.94, "Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!" }, { 18.88, "К северу отсюда лежат пещеры Железнолесья." }, { 22.37, "Тамошние криводревы-элементали поражены порчей так, что исцелить их уже нет надежды." }, { 29.12, "Прошу тебя, принеси мне их застывший сок – его называют кровавым янтарём, – чтобы я могла изучить его в надежде спасти другие формы здешней жизни." } } }, t = { d = 37.0, g = 1, v = "tauren-female", n = { m = 404, f = 406 }, c = { m = { { 0.00, "Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Осквернённый лес." }, { 7.01, "Ты доказал мне, что готов сделать всё для Круга Кенария." }, { 11.24, "Теперь я доверяю тебе." }, { 13.01, "Может показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства." }, { 26.01, "Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов, которые я смогу сделать." }, { 33.37, "Пришла пора исцелить Осквернённый лес." } }, f = { { 0.00, "Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Осквернённый лес." }, { 7.17, "Ты доказала мне, что готова сделать всё для Круга Кенария." }, { 11.63, "Теперь я доверяю тебе." }, { 13.44, "Может показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства." }, { 26.74, "Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов, которые я смогу сделать." }, { 34.26, "Пришла пора исцелить Осквернённый лес." } } } } },
    [4103] = { t = { d = 10.6, v = "nightelf-female", n = { x = 126 }, c = { x = { { 0.00, "Очень хорошо, вот тебе кенарийский бальзам." }, { 3.18, "Ищи в Осквернённом лесу поражённые растения!" }, { 6.30, "Когда найдёшь, исцеляй их при помощи моего целебного бальзама." } } } } },
    [4104] = { t = { d = 14.6, v = "nightelf-female", n = { x = 180 }, c = { x = { { 0.00, "Что же, прекрасно!" }, { 1.24, "Вот тебе кенарийский бальзам." }, { 3.27, "Если при разработках жил металлов в Осквернённом лесу найдёшь ещё порченого купороса, не забудь принести его мне!" }, { 10.87, "Чем больше найдёшь, тем больше бальзама я смогу сделать." } } } } },
    [4105] = { t = { d = 15.5, v = "nightelf-female", n = { x = 185 }, c = { x = { { 0.00, "Отличная работа – всё это после очищения пойдёт на исцеление Осквернённого леса." }, { 5.62, "Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес." }, { 11.69, "Исцеление этого края от порчи не терпит отлагательств!" } } } } },
    [4106] = { t = { d = 9.0, v = "nightelf-female", n = { x = 96 }, c = { x = { { 0.00, "То что нужно!" }, { 1.05, "Вот, бери этот бальзам для исцеления растений и лечи им Осквернённый лес от порчи!" }, { 7.37, "Мы не должны сдаваться!" } } } } },
    [4107] = { t = { d = 16.0, v = "nightelf-female", n = { x = 188 }, c = { x = { { 0.00, "Вот тебе кенарийский бальзам, и за него я прошу только одну порцию малой субстанции Пустоты." }, { 6.46, "Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала." }, { 12.73, "Если тебе понадобится ещё бальзам, ищи меня тут!" } } } } },
    [4108] = { t = { d = 12.4, v = "tauren-female", n = { x = 126 }, c = { x = { { 0.00, "Очень хорошо, вот тебе кенарийский бальзам." }, { 3.71, "Ищи в Осквернённом лесу поражённые растения!" }, { 7.34, "Когда найдёшь, исцеляй их при помощи моего целебного бальзама." } } } } },
    [4109] = { t = { d = 17.8, v = "tauren-female", n = { x = 180 }, c = { x = { { 0.00, "Что же, прекрасно!" }, { 1.51, "Вот тебе кенарийский бальзам." }, { 4.01, "Если при разработках жил металлов в Осквернённом лесу найдёшь ещё порченого купороса, не забудь принести его мне!" }, { 13.31, "Чем больше найдёшь, тем больше бальзама я смогу сделать." } } } } },
    [4110] = { t = { d = 18.2, v = "tauren-female", n = { x = 185 }, c = { x = { { 0.00, "Отличная работа – всё это после очищения пойдёт на исцеление Осквернённого леса." }, { 6.63, "Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес." }, { 13.80, "Исцеление этого края от порчи не терпит отлагательств!" } } } } },
    [4111] = { t = { d = 10.6, v = "tauren-female", n = { x = 96 }, c = { x = { { 0.00, "То что нужно!" }, { 1.24, "Вот, бери этот бальзам для исцеления растений и лечи им Осквернённый лес от порчи!" }, { 8.66, "Мы не должны сдаваться!" } } } } },
    [4112] = { t = { d = 19.2, v = "tauren-female", n = { x = 190 }, c = { x = { { 0.00, "Вот тебе кенарийский бальзам, и за него я прошу только одну порцию простой субстанции Пустоты." }, { 7.83, "Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала." }, { 15.29, "Если тебе понадобится ещё бальзам, ищи меня тут!" } } } } },
    [4113] = { t = { d = 14.2, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений." }, { 7.30, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4114] = { t = { d = 14.0, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений." }, { 7.22, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4115] = { t = { d = 13.3, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений." }, { 6.61, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4116] = { t = { d = 14.2, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений." }, { 7.30, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4117] = { t = { d = 13.4, v = "narrator", n = { x = 148 }, c = { x = { { 0.00, "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений." }, { 6.76, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4118] = { t = { d = 14.2, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений." }, { 7.30, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4119] = { t = { d = 13.7, v = "narrator", n = { x = 154 }, c = { x = { { 0.00, "Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений." }, { 7.16, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4120] = { d = 42.4, v = "tauren-male", n = { x = 385 }, c = { x = { { 0.00, "Я – охотник, и всегда стремлюсь превзойти силой своих противников." }, { 6.09, "Запомни: всегда можно обратить ситуацию в свою пользу, если хорошо знаешь врага." }, { 13.67, "К северу от Ясеневого леса есть место, называемое Осквернённый лес." }, { 19.68, "Тамошние звери запятнаны веществом, которое именуется скверной." }, { 25.52, "Медведи и волки от него совершенно взбесились, но в то же время скверна сделала их сильнее обычного." }, { 34.66, "Ступай." }, { 35.40, "Отправляйся в Осквернённый лес, чтобы встретиться с этими тварями лицом к лицу." } } }, t = { d = 14.1, v = "tauren-male", n = { x = 130 }, c = { x = { { 0.00, "Судя по твоему описанию, эти твари отличаются безоглядной свирепостью…" }, { 6.32, "Оставайся начеку." }, { 7.92, "Тебе стоит как можно больше узнать о порче." }, { 11.92, "Врага нужно знать в лицо!" } } } } },
    [4121] = { d = 15.8, g = 1, v = "orc-male#60", n = { m = 176, f = 176 }, c = { m = { { 0.00, "Ты в самом деле надеешься добраться до точки встречи, держа меня в плену?" }, { 5.55, "Ты и правда рассчитываешь, ворвавшись в крепость Чёрной горы и похитив главную ценность клана, удрать незамеченным?" }, { 14.05, "Да тебя в порошок сотрут!" } }, f = { { 0.00, "Ты в самом деле надеешься добраться до точки встречи, держа меня в плену?" }, { 5.55, "Ты и правда рассчитываешь, ворвавшись в крепость Чёрной горы и похитив главную ценность клана, удрать незамеченной?" }, { 14.05, "Да тебя в порошок сотрут!" } } }, t = { d = 9.8, g = 1, v = "orc-male", n = { m = 85, f = 86 }, c = { m = { { 0.00, "Твой подвиг не пропадёт втуне." }, { 2.69, "Ты заслужил эту награду." }, { 4.97, "Теперь Вождь поведает тебе о последнем задании." } }, f = { { 0.00, "Твой подвиг не пропадёт втуне." }, { 2.85, "Ты заслужила эту награду." }, { 5.35, "Теперь Вождь поведает тебе о последнем задании." } } } } },
    [4122] = { d = 34.1, v = "orc-male", n = { x = 336 }, c = { x = { { 0.00, "Я шёл за ним через Тлеющее ущелье, через горы и Пылающие степи." }, { 5.28, "Предателя поймали на месте преступления, когда тот передавал оркам Чёрной горы сверхсекретную информацию о деятельности нашего отряда." }, { 16.30, "Я говорю о Грарке Лоркрубе." }, { 18.61, "Он теперь в Пылающих степях, под их надёжной охраной – по крайней мере, он сам так думает." }, { 25.90, "Возьми эти оковы." }, { 27.46, "Найди Грарка, надень на него эти оковы и доставь сюда." }, { 32.15, "Награда будет достойной." } } }, t = { d = 7.0, v = "orc-male#60", n = { x = 70 }, c = { x = { { 0.00, "Разве ты не понимаешь, какую силу можно обрести, присоединившись к армии Чёрной горы?" } } } } },
    [4123] = { d = 38.8, v = "goblin-male", n = { x = 442 }, c = { x = { { 0.00, "Сколько лет я ищу этот камень!" }, { 2.23, "Он называется \"сердце горы\"." }, { 4.26, "Размером как раз с твой кулак." }, { 6.36, "Дворфы Чёрного Железа прячут его в своих тайных подвалах." }, { 10.50, "Я пытался его купить, предлагал им хорошую цену, но они не продают!" }, { 15.34, "Придётся забрать его силой, другого способа я не вижу." }, { 19.22, "Тебе надо пробиться на нижний ярус Глубин Чёрной горы, взломать потайной сейф и забрать сердце." }, { 26.03, "Для того чтобы добраться до тайника, тебе придётся сразиться с тамошним стражником." }, { 31.88, "Его зовут Хватка Смерти, и он появится только тогда, когда ты вскроешь все сундуки и сейфы!" }, { 38.43, "Удачи." } } }, t = { d = 9.8, g = 1, v = "goblin-male", n = { m = 96, f = 97 }, c = { m = { { 0.00, "Ты добыл Сердце!" }, { 1.36, "Великолепно!" }, { 2.36, "Оно даже прекраснее, чем мне представлялось!" }, { 5.87, "Прошу тебя, прими это в уплату за свои труды!" } }, f = { { 0.00, "Ты добыла Сердце!" }, { 1.47, "Великолепно!" }, { 2.50, "Оно даже прекраснее, чем мне представлялось!" }, { 6.10, "Прошу тебя, прими это в уплату за свои труды!" } } } } },
    [4124] = { d = 25.0, v = "nightelf-male#55", n = { x = 286 }, c = { x = { { 0.00, "Моему соратнику, Гинро Пылающему Очагу, нужна помощь." }, { 3.87, "Он ищет курьера и пакеты, которые тот вёз." }, { 6.85, "Курьер пропал примерно неделю назад; наши собственные поиски результата не дали." }, { 12.62, "Мы зашли в тупик." }, { 13.88, "Пришлось объявить курьера пропавшим без вести." }, { 17.18, "Если у тебя есть свободное время, пожалуйста, поговори с Гинро." }, { 21.68, "Он должен быть где-то здесь." }, { 23.65, "Возможно, он у себя." } } }, t = { d = 19.2, v = "nightelf-male#55", n = { x = 201 }, c = { x = { { 0.00, "Ты от Латро, я так понимаю?" }, { 2.04, "Я думаю, что дело глухо, но готов принять любую помощь." }, { 6.31, "Должен признаться... я буду рад, когда вопрос решится хоть как-то." }, { 11.34, "Я каждое утро выезжаю в лес разыскивать следы Раскала, и каждый вечер возвращаюсь домой с пустыми руками!" } } } } },
    [4125] = { d = 38.0, v = "nightelf-male#55", n = { x = 433 }, c = { x = { { 0.00, "Прошла примерно неделя с тех пор, как Раскал, курьер, отправился в Таланаар." }, { 5.36, "Фералас он знает, как свои пять пальцев – он был здесь с нами с самого начала, с тех пор, как генерал Оперённая Луна привела сюда экспедиционный корпус." }, { 15.95, "Я знаю, что он собирался взять вёсельную лодку и проплыть вдоль побережья Фераласа, чтобы миновать лагерь Орды." }, { 23.73, "Его лодки я так и не обнаружил – но, возможно, тебе это удастся." }, { 28.32, "Может быть, она спрятана либо потонула." }, { 31.19, "А между тем именно лодка может помочь выяснить, где Раскал." }, { 35.46, "Если найдёшь что-нибудь, дай мне знать." } } }, t = { d = 26.0, v = "narrator", n = { x = 276 }, c = { x = { { 0.00, "Вы обнаружили затонувшую лодку." }, { 2.47, "Сквозь мутноватую воду видны дыры, зияющие в левом борту." }, { 7.07, "Кажется, будто лодка буквально ободрана до своего деревянного остова." }, { 12.58, "Такое впечатление, что лодку пытались перекусить пополам." }, { 17.10, "На правом борту нарисован небольшой герб Крепости Оперённой Луны." }, { 22.19, "В иле, скопившемся на дне лодки, блеснул металл..." } } } } },
    [4126] = { d = 29.8, v = "dwarf-male", n = { x = 339 }, c = { x = { { 0.00, "Подонки Чёрного Железа под предводительством гнусного Харли Пьянодыха украли рецепт нашего лучшего громоварского светлого!" }, { 8.99, "Подлые твари!" }, { 10.06, "Они не достойны такого прекрасного напитка!" }, { 13.32, "У меня есть для тебя работа." }, { 15.45, "Отправляйся в Глубины Чёрной горы в Пылающих степях, уничтожь все бочонки с громоварским светлым, какие сумеешь найти, и забери у мерзавцев наш рецепт!" }, { 26.58, "Переверни все Глубины, но найди этот рецепт!" } } }, t = { d = 14.2, g = 1, v = "dwarf-male", n = { m = 139, f = 142 }, c = { m = { { 0.00, "Рецепт у тебя!" }, { 1.22, "Ты молодец!" }, { 2.15, "Надеюсь, ты задал жару этим подонкам и Харли Пьянодыху?" }, { 6.68, "Так им и надо, мерзавцам!" }, { 8.69, "Наше семейство перед тобой в неоплатном долгу." }, { 12.49, "Ты настоящий герой!" } }, f = { { 0.00, "Рецепт у тебя!" }, { 1.23, "Ты молодец!" }, { 2.17, "Надеюсь, ты задала жару этим подонкам и Харли Пьянодыху?" }, { 6.80, "Так им и надо, мерзавцам!" }, { 8.82, "Наше семейство перед тобой в неоплатном долгу." }, { 12.66, "Ты настоящая героиня!" } } } } },
    [4127] = { d = 25.4, v = "narrator", n = { x = 247 }, c = { x = { { 0.00, "Копаясь в иле, вы нащупываете рукоятку ножа." }, { 3.72, "Похоже, тот, кто плыл на лодке, его потерял." }, { 7.37, "Рядом валяются обломки самой лодки…" }, { 10.42, "Вы берёте нож с собой: Гинро Пылающий Очаг из Крепости Оперённой Луны велел вам принести ему всё, что может помочь разгадать тайну." }, { 21.20, "Однако вас не покидает ощущение, что вы тут не одни..." } } }, t = { d = 20.3, v = "nightelf-male#55", n = { x = 213 }, c = { x = { { 0.00, "Интересно..." }, { 0.96, "Похоже, это нож Раскала." }, { 2.89, "Так говоришь, он валялся на дне, рядом с обломками его лодки?" }, { 7.58, "Ну, может быть, этой находки и недостаточно, чтобы делать какие-то выводы." }, { 13.30, "Но у нас есть один необычный способ узнать побольше…" }, { 17.30, "Доводилось ли тебе слышать о сверхзнании?" } } } } },
    [4128] = { d = 24.5, v = "dwarf-female#33", n = { x = 244 }, c = { x = { { 0.00, "Здравствуй." }, { 0.92, "Ходят слухи, что кто-то украл у Рагнара Громовара его драгоценный эль." }, { 7.04, "Бедолага рвёт и мечет!" }, { 8.81, "Ему нужен отважный и дерзкий наёмник, который возьмётся за это дело." }, { 14.21, "Рагнар готов хорошо заплатить." }, { 16.82, "Если тебе интересно, переговори с ним." }, { 19.88, "Он сейчас в своей \"Громоварке\" в Караносе." }, { 23.21, "Это в Дун Мороге." } } }, t = { d = 20.2, g = 1, v = "dwarf-male", n = { m = 183, f = 184 }, c = { m = { { 0.00, "Да, ты прав, я не просто рассержен." }, { 2.89, "Я в бешенстве!" }, { 4.11, "Меня обокрали!" }, { 5.40, "Эти скоты спёрли наш старый фамильный рецепт!" }, { 9.28, "Да как они только посмели?!" }, { 11.63, "Я и раньше-то их ненавидел... этих поганых дворфов из клана Чёрного Железа!" }, { 17.95, "А теперь... ох, как я зол!" } }, f = { { 0.00, "Да, ты права, я не просто рассержен." }, { 3.07, "Я в бешенстве!" }, { 4.29, "Меня обокрали!" }, { 5.60, "Эти скоты спёрли наш старый фамильный рецепт!" }, { 9.51, "Да как они только посмели?!" }, { 11.89, "Я и раньше-то их ненавидел... этих поганых дворфов из клана Чёрного Железа!" }, { 18.25, "А теперь... ох, как я зол!" } } } } },
    [4129] = { d = 34.2, v = "nightelf-male#55", n = { x = 388 }, c = { x = { { 0.00, "У нас в крепости живёт друид, Квинтис Ночной Костёр, который умеет... много всего." }, { 5.65, "В частности, он владеет сверхзнанием – способностью узнавать на ощупь историю предмета." }, { 11.61, "Не спрашивай, как он это делает – я в этом не разбираюсь, и разбираться не хочу." }, { 17.07, "Я знаю только две вещи: во-первых, я видел, как это работает, а во-вторых, мужик у меня в долгу." }, { 23.77, "Короче, тащи этот ножик к Кинту, в его жилище на дереве, и передай, что должок, который за ним числится, будет уплачен, если он разберётся с этой штукой." } } }, t = { d = 31.8, v = "nightelf-male#54", n = { x = 336 }, c = { x = { { 0.00, "Спасибо." }, { 0.70, "Конечно, сверхзнание точным искусством не назовёшь, с какой стороны ни взгляни, но всё же в былые времена я не раз с его помощью разбирался в ситуациях, которые все прочие сочли безнадёжными." }, { 15.26, "Думаю, если применить его к найденному тобой ножу, оно поможет нам хотя бы отчасти понять, что произошло с Раскалом." }, { 24.42, "Времени это много не займёт, но лёгким и приятным это дело не назовёшь." }, { 29.88, "Так что наберись терпения." } } } } },
    [4130] = { d = 49.1, v = "nightelf-male#54", n = { x = 496 }, c = { x = { { 0.00, "Извини, меня до сих пор немного пошатывает." }, { 3.43, "Как бы то ни было, я сумел увидеть несколько полезных вещей." }, { 8.22, "Раскал вытащил два больших кожаных заплечных мешка из своей лодки и направился прочь от воды." }, { 15.66, "Однако потом вернулся к лодке." }, { 18.16, "Вижу скальпы гноллов... он наткнулся на гноллов – кажется, это тот клан, который называют Древолапами." }, { 26.24, "Он чем-то очень озабочен, даже вроде бы напуган." }, { 30.18, "Раскал настолько поглощён своими мыслями, что не замечает, как у него за спиной материализуются элементали воды." }, { 38.97, "И... и всё." }, { 39.83, "Больше я ничего не увидел." }, { 41.98, "Извини." }, { 42.62, "Мне необходимо отдохнуть." }, { 44.62, "Расскажи Гину о том, что я видел." }, { 47.27, "Ему следует это знать..." } } }, t = { d = 20.8, g = 1, v = "nightelf-male#55", n = { m = 227, f = 228 }, c = { m = { { 0.00, "Спасибо, что рассказал мне о видениях Кинта." }, { 3.18, "Так и быть, в следующий раз, как мы с ним сядем за карты, постараюсь быть к нему подобрее." }, { 9.47, "Ну, в бою Раскал никому не уступит, и гноллы – не те, кто может его обеспокоить, тем более, напугать." }, { 16.73, "Но, может быть, эти новые сведения тебе всё же пригодятся?" } }, f = { { 0.00, "Спасибо, что рассказала мне о видениях Кинта." }, { 3.20, "Так и быть, в следующий раз, как мы с ним сядем за карты, постараюсь быть к нему подобрее." }, { 9.39, "Ну, в бою Раскал никому не уступит, и гноллы – не те, кто может его обеспокоить, тем более, напугать." }, { 16.55, "Но, может быть, эти новые сведения тебе всё же пригодятся?" } } } } },
    [4131] = { d = 36.6, v = "nightelf-male#55", n = { x = 437 }, c = { x = { { 0.00, "Возможно, Раскала сцапали наши \"друзья\" из клана Древолапов, но что-то мне подсказывает, что дело было не так." }, { 7.45, "И всё равно начать лучше всего с их лагерей." }, { 10.51, "Конечно, хотелось бы иметь более отчётливые сведения, но пока что у нас нет ничего, кроме смутного указания на лагеря гноллов." }, { 19.00, "Я знаю, что гноллы хранят у себя награбленное и дерутся из-за добычи." }, { 23.77, "Возможно, они просто наткнулись на заплечные мешки, которые упоминал Кинт." }, { 28.84, "Прежде я не рисковал соваться к гноллам, но теперь, когда у нас есть сведения, полученные от Кинта, попробовать стоит." } } }, t = { d = 8.6, v = "narrator", n = { x = 86 }, c = { x = { { 0.00, "На ближайшем дереве висят два больших кожаных мешка." }, { 4.43, "На обоих виднеется метка Крепости Оперённой Луны..." } } } } },
    [4132] = { d = 26.6, g = 1, v = "orc-male#60", n = { m = 274, f = 275 }, c = { m = { { 0.00, "Ты проделал отличную работу!" }, { 2.37, "Теперь пришло время для последнего задания." }, { 6.01, "Генерал Кузня Гнева, ответственный за атаки Чёрного Железа на сто девятое подразделение Каргатского экспедиционного корпуса и массовые убийства наших солдат, должен понести наказание." }, { 20.99, "Это непростое задание, но в случае успеха труды окупятся сторицей." } }, f = { { 0.00, "Ты проделала отличную работу!" }, { 2.46, "Теперь пришло время для последнего задания." }, { 6.10, "Генерал Кузня Гнева, ответственный за атаки Чёрного Железа на сто девятое подразделение Каргатского экспедиционного корпуса и массовые убийства наших солдат, должен понести наказание." }, { 21.13, "Это непростое задание, но в случае успеха труды окупятся сторицей." } } }, t = { d = 14.5, g = 1, v = "orc-male#60", n = { m = 136, f = 136 }, c = { m = { { 0.00, "Наконец-то!" }, { 1.05, "Злодей понёс наказание!" }, { 3.14, "Ты незаурядный боец." }, { 4.99, "Носи этот медальон как знак своей непоколебимой преданности Орде и Каргатскому экспедиционному корпусу." } }, f = { { 0.00, "Наконец-то!" }, { 1.08, "Злодей понёс наказание!" }, { 3.24, "Ты незаурядный боец." }, { 5.16, "Носи этот медальон как знак своей непоколебимой преданности Орде и Каргатскому экспедиционному корпусу." } } } } },
    [4133] = { d = 23.8, v = "scourge-female", n = { x = 233 }, c = { x = { { 0.00, "Тенемагу Вивиане Лягроб нужна твоя помощь." }, { 3.76, "Она сейчас в Бесплодных землях, на сторожевой заставе Каргат." }, { 9.05, "Там недавно прошёл слух о небезызвестном напитке, сваренном дворфами Чёрного Железа в Глубинах Чёрной горы, – вот она и отправилась проверить." }, { 20.85, "Поговори с Вивианой." }, { 22.61, "Она тебя ждёт." } } }, t = { d = 18.8, g = 1, v = "scourge-female#80", n = { m = 175, f = 175 }, c = { m = { { 0.00, "Спасибо, что ты пришёл." }, { 1.93, "Это место не лишено своеобразного сурового очарования, но ему не хватает утончённости Района Фармацевтов." }, { 10.90, "Впрочем, я позвала тебя не для того, чтобы вести светские беседы." }, { 16.62, "Давай сразу к делу." } }, f = { { 0.00, "Спасибо, что ты пришла." }, { 2.06, "Это место не лишено своеобразного сурового очарования, но ему не хватает утончённости Района Фармацевтов." }, { 11.26, "Впрочем, я позвала тебя не для того, чтобы вести светские беседы." }, { 17.13, "Давай сразу к делу." } } } } },
    [4134] = { d = 47.3, v = "scourge-female#80", n = { x = 446 }, c = { x = { { 0.00, "Ходят слухи, что Харли Пьянодых из клана Чёрного Железа украл рецепт эля." }, { 6.56, "Говорят, этот эль, громоварское светлое, придаёт великую силу и храбрость тому, кто его употребит." }, { 15.18, "Нам хотелось бы изучить состав этого напитка." }, { 19.21, "Может быть, мы найдём и другое применение его удивительным свойствам... подходящее для целей Отрёкшихся." }, { 28.15, "Отправляйся в Глубины Чёрной горы, найди Харли, забери у него рецепт громоварского светлого и принеси его мне." }, { 37.87, "Возможно, тебе придётся выманить Харли из укрытия." }, { 42.30, "Для этого пригрози ему уничтожением его драгоценного эля." } } }, t = { d = 32.4, v = "scourge-female#80", n = { x = 281 }, c = { x = { { 0.00, "Вот и славно." }, { 1.25, "Я отошлю рецепт в Район Фармацевтов." }, { 4.68, "Его там изучат, и со временем мы раскроем его секреты." }, { 9.77, "И, возможно, придёт такой день, когда дворфы Альянса с удивлением обнаружат, что волшебные свойства их тайного напитка против них же и обернулись!" }, { 23.13, "По-моему, это будет забавно." }, { 25.88, "Видимо, смерть как-то странно влияет на чувство юмора... ты не находишь?" } } } } },
    [4135] = { d = 40.2, v = "narrator", n = { x = 437 }, c = { x = { { 0.00, "В рюкзаках находится два предмета: во-первых, посылка, адресованная в Таланаар, а во-вторых – записка, адресованная неизвестно кому." }, { 9.94, "В записке, набросанной торопливым почерком, говорится об обнаружении коварных насекомоподобных существ к югу от лагерей гноллов, в лесах, известных как \"Гудящая Бездна\"." }, { 22.69, "Автор сообщает, что намерен лично проникнуть туда, поскольку речь может идти о серьёзной опасности, грозящей всему Фераласу." }, { 32.15, "Записка подписана \"Раскал из Оперённой Луны\"." }, { 35.58, "Похоже, вам наконец-то удалось выяснить, куда делся Раскал..." } } }, t = { d = 23.3, v = "narrator", n = { x = 270 }, c = { x = { { 0.00, "Вам удалось обнаружить огромный кокон непонятного происхождения." }, { 4.75, "Сам кокон мягкий и слизистый, но изнутри в разных местах выпирает что-то твёрдое." }, { 10.78, "Размеры кокона позволяют предположить, что внутри может находиться гуманоид среднего роста... и сквозь стенки кокона действительно просвечивают очертания фигуры гуманоида!" } } } } },
    [4136] = { d = 40.0, v = "goblin-female#63", n = { x = 423 }, c = { x = { { 0.00, "Мой братец Риббли всегда только и делал, что тянул денежки из семьи и тратил их на какие-то поганые махинации." }, { 8.44, "Похоже, последний его проект оказался поганее прочих, потому что барон Ревилгаз из Пиратской бухты назначил награду за голову бедняжки Риббли." }, { 19.42, "Ты даже не представляешь, как возрадовались все Винтокраны!" }, { 23.81, "Наш малыш Риббли наконец хоть чего-то да стоит!" }, { 27.45, "Но сейчас он скрывается в Глубинах Чёрной горы." }, { 31.02, "Найди его и приведи ко мне!" }, { 33.15, "А если он не пойдёт добром... ну что ж, не пойдёт – и не надо... тогда принеси мне его голову." } } }, t = { d = 25.0, g = 1, v = "goblin-female#63", n = { m = 257, f = 258 }, c = { m = { { 0.00, "Ага!" }, { 0.41, "Ты нашёл его!" }, { 1.45, "И... как я понимаю, мой маленький братец не пожелал возвращаться в семью." }, { 6.98, "Очень жаль." }, { 7.88, "Посмотрела бы я на его рожу, когда он услышал о том, что мы собираемся сдать его Ревилгазу." }, { 14.80, "Спасибо." }, { 15.49, "Ты даже не представляешь, как порадовал всё наше семейство." }, { 19.98, "И Риббли сейчас такой тихий и славный... он никогда таким не был." } }, f = { { 0.00, "Ага!" }, { 0.42, "Ты нашла его!" }, { 1.52, "И... как я понимаю, мой маленький братец не пожелал возвращаться в семью." }, { 7.06, "Очень жаль." }, { 7.96, "Посмотрела бы я на его рожу, когда он услышал о том, что мы собираемся сдать его Ревилгазу." }, { 14.88, "Спасибо." }, { 15.57, "Ты даже не представляешь, как порадовала всё наше семейство." }, { 20.14, "И Риббли сейчас такой тихий и славный... он никогда таким не был." } } } } },
    [4141] = { d = 32.5, g = 1, v = "human-male", n = { m = 392, f = 393 }, c = { m = { { 0.00, "Видишь Лариона вон там?" }, { 1.57, "Это ОН виноват, что мы застряли здесь!" }, { 4.10, "Я говорил ему, что мы идём не туда, но разве он меня слушал?" }, { 8.14, "И представляешь, после этого он ещё и не желает со мной разговаривать!" }, { 12.72, "Ну, пока он не передумает, я позабавлюсь!" }, { 15.44, "Ты заметил здесь таких странных созданий, похожих на цветы?" }, { 19.42, "От них, честно говоря, одни неприятности, но, думаю, если их как следует выдрессировать, они будут слушаться команд." }, { 27.19, "В первую очередь, мне нужны образцы для изучения." }, { 30.51, "Сможешь принести мне несколько?" } }, f = { { 0.00, "Видишь Лариона вон там?" }, { 1.56, "Это ОН виноват, что мы застряли здесь!" }, { 4.09, "Я говорил ему, что мы идём не туда, но разве он меня слушал?" }, { 8.12, "И представляешь, после этого он ещё и не желает со мной разговаривать!" }, { 12.70, "Ну, пока он не передумает, я позабавлюсь!" }, { 15.41, "Ты заметила здесь таких странных созданий, похожих на цветы?" }, { 19.44, "От них, честно говоря, одни неприятности, но, думаю, если их как следует выдрессировать, они будут слушаться команд." }, { 27.20, "В первую очередь, мне нужны образцы для изучения." }, { 30.51, "Сможешь принести мне несколько?" } } }, t = { d = 12.0, v = "human-male", n = { x = 144 }, c = { x = { { 0.00, "Надеюсь, они не доставили тебе забот?" }, { 2.60, "Крайне дикие создания!" }, { 4.17, "Однажды я попытался перепрыгнуть через один такой цветочек, так он напал на меня!" }, { 9.66, "Растения не должны так себя вести..." } } } } },
    [4142] = { d = 28.8, v = "human-male", n = { x = 348 }, c = { x = { { 0.00, "Не знаю, что и сказать тебе." }, { 1.94, "У этих растений, видимо, имеются зачатки разума." }, { 5.28, "Впрочем, я не специалист." }, { 6.98, "Однако знаю, к кому обратиться за действительно профессиональным мнением." }, { 11.89, "Отправляйся в северный Фералас и найди там моего приятеля по имени Греган Пивоплюй." }, { 17.53, "Он на таких вещах собаку съел." }, { 19.60, "Уверен, Греган сможет дать нам действительно дельный совет." }, { 23.60, "Думаю, искать его лучше где-нибудь в лесу – парень никак не городской житель." } } }, t = { d = 9.8, v = "dwarf-male", n = { x = 95 }, c = { x = { { 0.00, "Кровоцвет, говоришь?" }, { 1.68, "Хмм..." }, { 2.19, "В общем, сначала расскажи мне, что собираешься делать, а уж потом я скажу тебе, смогу ли помочь." } } } } },
    [4143] = { d = 35.1, v = "dwarf-male", n = { x = 401 }, c = { x = { { 0.00, "Честно говоря, мне никогда прежде не доводилось видеть подобных растений." }, { 5.27, "Возможно, имеет смысл наведаться в этот кратер..." }, { 8.80, "В любом случае, думаю, что знаю, что именно ищет Майджин." }, { 12.98, "Ему нужен туман Аталаи." }, { 14.77, "Это жуткая субстанция, которую весьма сложно собрать, однако именно этот туман необходим ему, чтобы управлять маленькими монстрами." }, { 24.34, "Тебе нужно найти Храм Атал'Хаккара на Болоте Печали." }, { 28.13, "Туман Аталаи можно собрать с обитающих там глубинных скрытней, мракочервей и слизнюков." }, { 34.36, "Удачи тебе!" } } }, t = { d = 8.1, v = "human-male", n = { x = 92 }, c = { x = { { 0.00, "Признаю, мне очень боязно прикасаться к этой штуке!" }, { 3.79, "Но раз Греган утверждает, что она работает, надо попробовать." } } } } },
    [4144] = { t = { d = 5.0, v = "human-male", n = { x = 50 }, c = { x = { { 0.00, "Ну, приступим!" }, { 1.22, "Уж это привлечёт внимание Лариона, будь уверен!" } } } } },
    [4145] = { d = 31.1, v = "dwarf-male", n = { x = 348 }, c = { x = { { 0.00, "Видишь там Майджина?" }, { 1.48, "Это ОН виноват, что мы потерялись!" }, { 3.92, "Я знал дорогу, но он настоял на том, чтобы пойти \"коротким путём\" и вот!" }, { 8.94, "Мы застряли в этой дыре!" }, { 10.74, "Что ещё хуже, он теперь взялся натравливать на меня этих проклятых паразитов – кровоцветы!" }, { 17.18, "Я так зол, что не собираюсь говорить с ним." }, { 20.14, "А эти паразиты – просто последняя капля!" }, { 23.09, "Думаю, в первую очередь мы перекроем ему снабжение!" }, { 26.83, "Пойди-ка, поохоться на кровоцветы, а потом возвращайся ко мне." } } }, t = { d = 5.0, v = "dwarf-male", n = { x = 44 }, c = { x = { { 0.00, "Спасибо за помощь, однако боюсь, у меня плохие новости..." } } } } },
    [4146] = { d = 32.6, v = "goblin-female", n = { x = 387 }, c = { x = { { 0.00, "Тебе повезло!" }, { 1.00, "Я тут работала над кой-какими собственными изобретениями, пока Марвон в отъезде." }, { 6.53, "И вот моя последняя разработка – антижучиный шокер ближнего действия!" }, { 11.66, "Его надо совсем чуть-чуть поправить, и можно смело использовать против кровоцветов-паразитов." }, { 18.25, "С удовольствием подарю тебе одну из моих тестовых моделей, однако для неё необходимо питание – туман Аталаи." }, { 25.85, "Его можно собрать в Храме Атал'Хаккара с обитающих там трясинных скрытней, мракочервей и слизнюков." } } }, t = { d = 4.5, g = 1, v = "dwarf-male", n = { m = 39, f = 41 }, c = { m = { { 0.00, "Так Марвона там не было?" }, { 2.20, "И что же ты оттуда принёс?" } }, f = { { 0.00, "Так Марвона там не было?" }, { 2.16, "И что же ты оттуда принесла?" } } } } },
    [4147] = { d = 23.1, v = "dwarf-male", n = { x = 277 }, c = { x = { { 0.00, "Мне удалось проследить за Майджином – он и впрямь выращивает эти проклятые растения!" }, { 5.77, "Думаю, единственным решением будет..." }, { 8.40, "Нет, говорить с ним бесполезно, надо готовиться к ответному удару!" }, { 12.98, "Нам потребуется помощь моего друга Марвона, у него мастерская в Кабестане." }, { 18.18, "Уверен, он сможет смастерить какую-нибудь штуковину, которая нам поможет." } } }, t = { d = 8.4, v = "goblin-female", n = { x = 99 }, c = { x = { { 0.00, "Марвона здесь давно нет." }, { 1.72, "Он отправился в Танарис, изучать развалины древних поселений троллей." }, { 6.63, "А зачем он был тебе нужен?" } } } } },
    [4148] = { t = { d = 8.9, v = "dwarf-male", n = { x = 105 }, c = { x = { { 0.00, "Похоже, это устройство прекрасно сработает." }, { 3.16, "Помни, как только заметишь где-нибудь этих паразитов, немедленно используй шокер!" } } } } },
    [4161] = { d = 32.6, g = 1, v = "nightelf-male#59", n = { x = 357 }, c = { m = { { 0.00, "Давным-давно ночные эльфы назывались кальдораями, \"детьми звёзд\"." }, { 4.79, "Изучение прошлого – важный шаг на пути героя, так что слушай внимательно всё, что я расскажу тебе." }, { 11.97, "Кальдораи всегда гордились тем, что живут в гармонии с природой." }, { 16.69, "Это означает, что мы берём у природы только то, что нам необходимо, и воздаём ей сторицей." }, { 23.14, "Это равновесие позволяло нам вершить многое." }, { 26.47, "Ступай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне." } }, f = { { 0.00, "Давным-давно ночные эльфы назывались кальдораями, \"детьми звёзд\"." }, { 4.61, "Изучение прошлого – важный шаг на пути героини, так что слушай внимательно всё, что я расскажу тебе." }, { 11.64, "Кальдораи всегда гордились тем, что живут в гармонии с природой." }, { 16.18, "Это означает, что мы берём у природы только то, что нам необходимо, и воздаём ей сторицей." }, { 22.39, "Это равновесие позволяло нам вершить многое." }, { 25.59, "Ступай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне." } } }, t = { d = 10.5, v = "nightelf-male#59", n = { x = 113 }, c = { x = { { 0.00, "Всегда помни то, что я ныне показал тебе." }, { 3.22, "Ты – часть того равновесия, которое ночные эльфы стремятся поддерживать даже в тревожные времена." } } } } },
    [4181] = { d = 41.2, v = "gnome-male", n = { x = 480 }, c = { x = { { 0.00, "В инженерном деле есть две дисциплины: гномская и гоблинская." }, { 4.23, "Я – честный учитель, и только поэтому вообще упоминаю гоблинское инженерное дело." }, { 9.97, "Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер." }, { 20.96, "Почитай этот справочник." }, { 22.72, "Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск." }, { 29.48, "Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого." } } }, t = { d = 25.9, v = "goblin-male", n = { x = 283 }, c = { x = { { 0.00, "Что же, ты разумно поступаешь, прося у меня наставничества!" }, { 4.48, "Любой дурак может стать экспертом в азах инженерного дела – что прекрасно видно на примере гномов и их радиоактивного Гномрегана." }, { 14.34, "Для овладения гоблинским инженерным делом требуется крепкая соображаловка и твёрдая (повторяю – ТВЁРДАЯ) рука." }, { 22.62, "Держи ушки на макушке, может, что и усвоишь." } } } } },
    [4182] = { d = 30.7, g = 1, v = "nightelf-male#54", n = { m = 333, f = 334 }, c = { m = { { 0.00, "Жизнь в Пылающих степях никогда не бывает спокойной." }, { 3.97, "Только посмотри вокруг!" }, { 5.82, "Мы не знаем, что случилось с этими строениями, но до большого взрыва всё это было частью Красногорья." }, { 13.55, "Но довольно скулить!" }, { 15.13, "У нас есть более насущная проблема." }, { 17.80, "Может быть, ты заметил драконов под этим хребтом." }, { 21.56, "Необходимо вынудить их отступить." }, { 24.09, "Убей как можно больше и возвращайся." }, { 26.90, "Если ты добьёшься успеха, я дам тебе другое задание." } }, f = { { 0.00, "Жизнь в Пылающих степях никогда не бывает спокойной." }, { 3.96, "Только посмотри вокруг!" }, { 5.80, "Мы не знаем, что случилось с этими строениями, но до большого взрыва всё это было частью Красногорья." }, { 13.52, "Но довольно скулить!" }, { 15.09, "У нас есть более насущная проблема." }, { 17.76, "Может быть, ты заметила драконов под этим хребтом." }, { 21.58, "Необходимо вынудить их отступить." }, { 24.11, "Убей как можно больше и возвращайся." }, { 26.91, "Если ты добьёшься успеха, я дам тебе другое задание." } } }, t = { d = 9.0, v = "nightelf-male#54", n = { x = 96 }, c = { x = { { 0.00, "Добрая охота." }, { 1.14, "Ну, раз ты можешь справиться с драконами и их прихвостнями, пора поговорить о более насущных проблемах." } } } } },
    [4183] = { d = 29.7, v = "nightelf-male#54", n = { x = 298 }, c = { x = { { 0.00, "Мы всегда думали, что орки Чёрной Горы такие жестокие от природы." }, { 5.38, "Оказывается, дело обстоит иначе." }, { 8.11, "Да, их и правда ведёт в бой жажда крови и любовь к сражениям, но руководят ими чёрные драконы." }, { 15.70, "Мы подозреваем, что именно они возбуждают в них ярость и злобу." }, { 20.86, "Отнеси это письмо мировому судье Соломону." }, { 24.47, "Он скажет, что делать." }, { 26.24, "*Хелендис протягивает вам запечатанное письмо.*" } } }, t = { d = 5.8, v = "human-male", n = { x = 64 }, c = { x = { { 0.00, "*Мировой судья Соломон распечатывает письмо от Хелендиса и начинает читать.*" } } } } },
    [4184] = { d = 32.5, v = "human-male", n = { x = 376 }, c = { x = { { 0.00, "Дурные вести." }, { 1.04, "Нетрудно прийти в отчаяние, узнав, что твои смертельные враги – всего лишь пешки куда более страшного противника." }, { 9.29, "Приозёрью не пережить натиска орков Чёрной Горы и чёрных драконов." }, { 13.97, "Если падёт Приозёрье, следующим будет Темнолесье, а что потом?" }, { 18.39, "Златоземье?" }, { 19.24, "Сам Штормград?" }, { 20.28, "Немедленно отнеси это сообщение Верховному лорду Болвару Фордрагону в Штормград!" }, { 26.13, "Если мы и этим не добьёмся от столицы помощи, то не добьёмся никакими силами, и всё пропало." } } }, t = { d = 3.0, v = "creature/bolvar", n = { x = 22 }, c = { x = { { 0.00, "Драконы?" }, { 0.98, "Быть того не может!" } } } } },
    [4185] = { d = 31.3, v = "creature/bolvar", n = { x = 349 }, c = { x = { { 0.00, "Грустную картину нарисовал Соломон." }, { 2.69, "Тем не менее, мы не можем позволить себе посылать наши и без того скудные войска на помощь Приозёрью, основываясь только на догадках." }, { 12.56, "Мне понадобится доказательство правоты его заявлений, прежде чем я смогу предпринять какие-то действия." }, { 20.21, "Поговорите с леди Престор." }, { 22.23, "Она женщина учёная и много чего знает о драконах и драконидах." }, { 26.93, "Возможно, она сможет пролить какой-то свет на эту ситуацию." } } }, t = { d = 16.5, v = "creature/bolvar", n = { x = 160 }, c = { x = { { 0.00, "*Болвар подпирает рукой подбородок, как бы глубоко задумавшись.*" }, { 5.12, "В то время как я уважаю позицию леди Престор, я уверен, что для этой дилеммы есть решение, которое могло бы развеять все наши тревоги." } } } } },
    [4186] = { d = 11.9, v = "creature/bolvar", n = { x = 139 }, c = { x = { { 0.00, "Я намерен наделить вас полномочиями представителя, действующего от имени Штормграда." }, { 6.20, "Возвращайтесь к мировому судье Соломону в Приозёрье и передайте ему этот указ." } } }, t = { d = 16.8, v = "human-male", n = { x = 154 }, c = { x = { { 0.00, "Ну, полагаю, могло быть и хуже..." }, { 3.28, "*Мировой судья изучает вас взглядом.*" }, { 6.56, "Похоже, что судьба Озёр ложится теперь на ваши плечи." }, { 10.56, "*Вы замечаете, что мировой судья часто-часто моргает.*" }, { 15.22, "*Кажется, он плачет.*" } } } } },
    [4201] = { d = 44.2, g = 1, v = "succubus-female", n = { m = 472, f = 472 }, c = { m = { { 0.00, "О, терзания и муки неразделённой любви!" }, { 2.99, "Мои чары не действуют на возлюбленного." }, { 6.04, "Рядовой Камнеузл отвергает меня!" }, { 8.61, "Это невыносимо!" }, { 9.86, "Ты должен мне помочь!" }, { 11.53, "Мы, суккубы, хорошо разбираемся в любовных делах, и я могу приготовить волшебное зелье, которое разрушит железную стену вокруг непреклонного сердца Камнеузла." }, { 23.76, "Для того чтобы сварить это зелье, мне нужна трава кровь Грома, серебряные слитки скальных великанов Азшары и вода из источников Голакка в Кратере Ун'Горо." }, { 35.78, "Воду можешь набрать в этот сосуд." }, { 38.48, "Прошу тебя, помоги моей бедной истерзанной душе обрести радость и счастье!" } }, f = { { 0.00, "О, терзания и муки неразделённой любви!" }, { 2.95, "Мои чары не действуют на возлюбленного." }, { 5.98, "Рядовой Камнеузл отвергает меня!" }, { 8.52, "Это невыносимо!" }, { 9.76, "Ты должна мне помочь!" }, { 11.41, "Мы, суккубы, хорошо разбираемся в любовных делах, и я могу приготовить волшебное зелье, которое разрушит железную стену вокруг непреклонного сердца Камнеузла." }, { 23.50, "Для того чтобы сварить это зелье, мне нужна трава кровь Грома, серебряные слитки скальных великанов Азшары и вода из источников Голакка в Кратере Ун'Горо." }, { 35.39, "Воду можешь набрать в этот сосуд." }, { 38.07, "Прошу тебя, помоги моей бедной истерзанной душе обрести радость и счастье!" } } }, t = { d = 11.9, g = 1, v = "succubus-female", n = { m = 108, f = 110 }, c = { m = { { 0.00, "Ты всё принёс!" }, { 1.18, "Теперь я смогу приготовить волшебный напиток, и Камнеузл воспылает ко мне любовью!" }, { 8.36, "Спасибо." }, { 9.15, "Ты – истинный рыцарь любви!" } }, f = { { 0.00, "Ты всё принесла!" }, { 1.45, "Теперь я смогу приготовить волшебный напиток, и Камнеузл воспылает ко мне любовью!" }, { 8.78, "Спасибо." }, { 9.58, "Ты – истинный рыцарь любви!" } } } } },
    [4221] = { t = { d = 13.8, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений." }, { 6.85, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4222] = { t = { d = 13.4, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений." }, { 6.69, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4223] = { d = 9.0, g = 1, v = "human-male", n = { m = 116, f = 116 }, c = { m = { { 0.00, "Возвращайся в Пылающие степи." }, { 2.85, "Как представитель Штормграда ты должен предстать перед маршалом Максвеллом." }, { 8.63, "Удачи." } }, f = { { 0.00, "Возвращайся в Пылающие степи." }, { 2.70, "Как представитель Штормграда ты должна предстать перед маршалом Максвеллом." }, { 8.18, "Удачи." } } }, t = { d = 1.6, v = "human-male", n = { x = 0 }, c = { x = { { 0.00, "Ха-ха-ха!" } } } } },
    [4224] = { d = 30.5, g = 1, v = "human-male", n = { m = 390, f = 390 }, c = { m = { { 0.00, "Что?" }, { 0.29, "Думаешь, ты первый?" }, { 1.58, "Сколько же ещё мы должны потерять солдат прежде, чем Штормград начнёт шевелиться?" }, { 6.78, "Мы собрали целую кучу разведданных касательно угрозы со стороны клана Чёрной горы до того, как потеряли нашего командира, маршала Виндзора." }, { 15.84, "С ним пропала и вся наша бесценная информация." }, { 18.82, "Нам просто необходимы эти документы." }, { 21.21, "Поговори с Джоном-Оборванцем." }, { 23.14, "Он был при Виндзоре, когда на них налетел рейд клана Чёрной горы." }, { 27.29, "Последний раз его видели в пещере к северу отсюда." } }, f = { { 0.00, "Что?" }, { 0.29, "Думаешь, ты первая?" }, { 1.57, "Сколько же ещё мы должны потерять солдат прежде, чем Штормград начнёт шевелиться?" }, { 6.74, "Мы собрали целую кучу разведданных касательно угрозы со стороны клана Чёрной горы до того, как потеряли нашего командира, маршала Виндзора." }, { 15.75, "С ним пропала и вся наша бесценная информация." }, { 18.72, "Нам просто необходимы эти документы." }, { 21.10, "Поговори с Джоном-Оборванцем." }, { 23.02, "Он был при Виндзоре, когда на них налетел рейд клана Чёрной горы." }, { 27.14, "Последний раз его видели в пещере к северу отсюда." } } }, t = { d = 4.1, v = "human-male", n = { x = 41 }, c = { x = { { 0.00, "Я мог бы тебя предупредить, но разве это интересно?" } } } } },
    [4241] = { d = 16.8, v = "human-male", n = { x = 191 }, c = { x = { { 0.00, "Значит, этот жалкий трус говорит, что Виндзор жив?" }, { 3.72, "Готовься, тебе предстоит отправиться на его поиски." }, { 7.58, "Если Виндзор жив, спаси его." }, { 9.77, "Если мёртв – принеси мне доказательства его гибели." }, { 13.56, "Тебе, наверное, надоело это слышать?" } } }, t = { d = 2.3, v = "human-male#50", n = { x = 13 }, c = { x = { { 0.00, "Где он!" }, { 0.91, "Я убью его!" } } } } },
    [4242] = { d = 33.7, v = "human-male#50", n = { x = 377 }, c = { x = { { 0.00, "Болвар – жалкий дурак." }, { 1.66, "Я собирал все его драгоценные \"доказательства\" только для того, чтобы засунуть их ему же в глотку." }, { 8.59, "Недоумок!" }, { 9.29, "Слепой идиот!" }, { 10.31, "Доказательство стоит в двух шагах от него, а он ушами хлопает." }, { 14.70, "Что касается собранных мною сведений – вся информация утрачена, причём безвозвратно." }, { 20.56, "Если я всё-таки найду Железогубитель и выберусь из этого лабиринта, я первым делом отправлюсь в Штормград и вломлю ему молотом промеж глаз, этому подлому змею." }, { 32.84, "Оставь меня." } } }, t = { d = 19.0, g = 1, v = "human-male", n = { m = 197, f = 198 }, c = { m = { { 0.00, "Вполне очевидно, что он повредился рассудком." }, { 3.36, "*Максвелл скорбно склоняет голову.*" }, { 6.08, "Печально, когда благородный и доблестный воин превращается в невменяемого идиота." }, { 12.38, "Как я понимаю, мы зашли в тупик..." }, { 15.04, "Но ты хорошо потрудился." }, { 16.93, "И получишь награду." } }, f = { { 0.00, "Вполне очевидно, что он повредился рассудком." }, { 3.36, "*Максвелл скорбно склоняет голову.*" }, { 6.32, "Печально, когда благородный и доблестный воин превращается в невменяемого идиота." }, { 12.67, "Как я понимаю, мы зашли в тупик..." }, { 15.35, "Но ты хорошо потрудилась." }, { 17.32, "И получишь награду." } } } } },
    [4243] = { d = 41.4, g = 1, v = "dwarf-female", n = { m = 468, f = 469 }, c = { m = { { 0.00, "Увы, что-то случилось с одним из моих величайших изобретений." }, { 4.43, "Ты ведь видел моих механических белок?" }, { 7.18, "Так вот, чтобы подобраться поближе к обезьянам, обитающим в Кратере Ун'Горо, я создала механическую обезьяну, которая должна была смешаться со стаей." }, { 17.77, "Я назвала её Чи-Та три." }, { 19.44, "Её глаза были сделаны из магических кристаллов, так что я могла видеть всё, что видит она." }, { 25.85, "Она успела добраться до Пещеры Лишайников – это логово обезьян к востоку отсюда – и там я потеряла с ней контакт." }, { 33.93, "Последним, что я видела, был вожак стаи, который подбежал поздороваться с ней." }, { 39.45, "Ты поможешь мне разыскать её?" } }, f = { { 0.00, "Увы, что-то случилось с одним из моих величайших изобретений." }, { 4.36, "Ты ведь видела моих механических белок?" }, { 7.14, "Так вот, чтобы подобраться поближе к обезьянам, обитающим в Кратере Ун'Горо, я создала механическую обезьяну, которая должна была смешаться со стаей." }, { 17.57, "Я назвала её Чи-Та три." }, { 19.21, "Её глаза были сделаны из магических кристаллов, так что я могла видеть всё, что видит она." }, { 25.53, "Она успела добраться до Пещеры Лишайников – это логово обезьян к востоку отсюда – и там я потеряла с ней контакт." }, { 33.49, "Последним, что я видела, был вожак стаи, который подбежал поздороваться с ней." }, { 38.92, "Ты поможешь мне разыскать её?" } } }, t = { d = 16.4, v = "narrator", n = { x = 158 }, c = { x = { { 0.00, "Осмотрев Чи-Та три, вы обнаруживаете две глубоких вмятины в творении инженерного искусства Карны." }, { 8.16, "Одна вмятина украшает плечо робота, другая зияет на голове." }, { 13.35, "Похоже, энергии в машине не осталось." } } } } },
    [4244] = { d = 19.9, v = "narrator", n = { x = 207 }, c = { x = { { 0.00, "Внимательно осмотрев робота, вы замечаете отодвигающуюся панель, над которой значится: \"Заменить мифриловую обшивку, затем выключить и включить питание\"." }, { 12.34, "Сомнительно, что такую серьёзную поломку можно устранить так легко..." }, { 17.88, "Не попробуешь – не узнаешь." } } }, t = { d = 15.9, v = "narrator", n = { x = 181 }, c = { x = { { 0.00, "Вы снова отодвигаете панель на спине Чи-Та три и осторожно вынимаете обгоревшую мифриловую обшивку, заменяя её новой." }, { 8.52, "Если действительно считать, что это и была основная причина поломки, то осталось лишь включить питание." } } } } },
    [4245] = { d = 21.8, v = "narrator", n = { x = 238 }, c = { x = { { 0.00, "Установив тумблер в положение \"выключено\", вы оглядываетесь, чтобы удостовериться, что всё готово к тому, чтобы доставить Чи-Та три назад к Карне Сомнамбулер." }, { 11.77, "Убедившись, что горилл поблизости нет, вы собираетесь включить робота." }, { 16.98, "Это ваш последний шанс." }, { 18.74, "Вы уверены, что хотите сделать именно это?" } } }, t = { d = 15.8, v = "dwarf-female", n = { x = 135 }, c = { x = { { 0.00, "Ах, тебе удалось, какое счастье!" }, { 3.07, "Спасибо!" }, { 3.90, "О, моя бедняжечка!" }, { 5.64, "Как тебе досталось!" }, { 7.46, "Ничего, я починю тебя, будешь как новенькая!" }, { 11.61, "Ещё раз благодарю тебя, твоя помощь неоценима." } } } } },
    [4261] = { d = 51.4, v = "creature/ancient", n = { x = 385 }, c = { x = { { 0.00, "Осквернённый лес был некогда местом мирным и безмятежным..." }, { 6.08, "Пока сюда не пришёл Легион." }, { 9.02, "Эти инферналы, разрушения, хаос..." }, { 12.72, "Череп Гул'дана сделал так, что ничто не смогло уберечься от порчи." }, { 19.75, "Даже сейчас, будучи духом, я ощущаю себя в ловушке, ощущаю страдания этого края." }, { 28.48, "Помоги мне найти путь домой." }, { 31.52, "Прошу тебя, пообещай, что ты уведёшь древний дух отсюда, туда, где я, наконец, обрету покой." }, { 41.20, "Как только я освобожусь, найди Кайнета Штиля, друида, что живёт в Лесной Песне, к востоку отсюда." } } }, t = { d = 14.0, v = "nightelf-male#54", n = { x = 127 }, c = { x = { { 0.00, "Да." }, { 0.34, "Осквернённый лес пережил много горестей." }, { 4.02, "Спасибо тебе за всё." }, { 5.95, "Однажды мы очистим Осквернённый лес от скверны, и каждое доброе дело приближает этот миг." } } } } },
    [4262] = { d = 29.8, v = "gnome-female#41", n = { x = 346 }, c = { x = { { 0.00, "Последние пять магов, которые отправились на разведку к Чёрной горе, вернулись довольно хрустящими и с перманентной завивкой – или хуже того." }, { 10.32, "*Джалинда берёт с земли щепотку пепла и пускает по ветру.*" }, { 14.80, "А больше всего неприятностей нам причиняет один тип, подчинитель Пирон." }, { 19.82, "Необходимо остановить этого элементаля, чтобы наша экспедиция могла пробраться в глубины Чёрной горы." }, { 27.00, "Он охраняет вход в каменоломни Чёрной горы." } } }, t = { d = 3.0, v = "gnome-female#41", n = { x = 14 }, c = { x = { { 0.00, "Опалитель?" }, { 1.69, "О, небо…" } } } } },
    [4263] = { d = 27.8, g = 1, v = "gnome-female#41", n = { m = 308, f = 309 }, c = { m = { { 0.00, "Ты уверен, что Пирон сказал перед смертью \"Опалитель\"?" }, { 4.23, "Ведь лорд Опалитель – прислужник Рагнароса!" }, { 8.73, "О небо, небо..." }, { 9.98, "Что же нам делать?" }, { 11.36, "Как ты думаешь, справишься с ещё одним заданием?" }, { 15.03, "Мне больше некого послать!" }, { 17.11, "Нам никогда не одолеть врагов, если Опалитель будет и дальше воскрешать Пирона из пепла." }, { 23.97, "Тебе придётся отыскать и уничтожить лорда Опалителя!" } }, f = { { 0.00, "Ты уверена, что Пирон сказал перед смертью \"Опалитель\"?" }, { 4.24, "Ведь лорд Опалитель – прислужник Рагнароса!" }, { 8.68, "О небо, небо..." }, { 9.91, "Что же нам делать?" }, { 11.27, "Как ты думаешь, справишься с ещё одним заданием?" }, { 14.89, "Мне больше некого послать!" }, { 16.94, "Нам никогда не одолеть врагов, если Опалитель будет и дальше воскрешать Пирона из пепла." }, { 23.71, "Тебе придётся отыскать и уничтожить лорда Опалителя!" } } }, t = { d = 10.5, g = 1, v = "gnome-female#41", n = { m = 97, f = 98 }, c = { m = { { 0.00, "О небо!" }, { 0.73, "Ты уверен, что Опалитель сказал перед смертью \"Рагнарос\"?" }, { 5.84, "*Джалинда протягивает вам что-то и морщит лоб в раздумье.*" } }, f = { { 0.00, "О небо!" }, { 0.74, "Ты уверена, что Опалитель сказал перед смертью \"Рагнарос\"?" }, { 6.00, "*Джалинда протягивает вам что-то и морщит лоб в раздумье.*" } } } } },
    [4264] = { d = 31.6, v = "narrator", n = { x = 307 }, c = { x = { { 0.00, "Лист помят и испачкан, и текст почти не читается, но вам всё-таки удалось разобрать несколько фраз:" }, { 7.69, "\"...по иронии судьбы..." }, { 9.56, "...упадок распавшегося Альянса..." }, { 12.21, "...если бы не усердие генерала Кузни Гнева, мы никогда не сумели бы найти ключ к шифру..." }, { 19.33, "...Аргелмах почти завершил расшифровку записок Виндзора." }, { 24.05, "Наш владыка восстанет из бездны и сокрушит всех, кто остался..." }, { 28.84, "Император Дагран Тауриссан\"." } } }, t = { d = 2.6, v = "human-male#50", n = { x = 26 }, c = { x = { { 0.00, "*Маршал Виндзор читает записку.*" } } } } },
    [4265] = { d = 36.8, v = "narrator", n = { x = 348 }, c = { x = { { 0.00, "Когда вы прикасаетесь к кокону, он немного раскрывается, и вы видите внутри ночного эльфа, который, как ни странно, всё ещё жив, и даже, кажется, цел и невредим, только в глубоком обмороке." }, { 15.39, "Когда вы вытаскиваете его из кокона, он шевелится и приходит в себя." }, { 21.04, "\"Слава Элуне!" }, { 22.23, "Я спасён!" }, { 22.98, "Спасибо тебе, друг." }, { 24.61, "Я..." }, { 24.98, "Меня зовут Раскал." }, { 26.62, "Эти жуки парализовали меня, и очнулся я уже в коконе." }, { 31.15, "Тебя из крепости прислали, да?\"" }, { 33.76, "Похоже, вы нашли пропавшего курьера..." } } }, t = { d = 28.6, g = 1, v = "nightelf-male#55", n = { m = 294, f = 296 }, c = { m = { { 0.00, "С возвращением!" }, { 1.19, "Раскал не так давно явился ко мне и сообщил обо всём, что произошло." }, { 6.39, "Я... да что там, вся наша крепость не знает, как тебя благодарить за твои подвиги." }, { 12.71, "Раскал погиб бы, если бы не твоя своевременная помощь." }, { 16.99, "А ведь ты помогаешь нам не ради платы, как какой-нибудь наёмник!" }, { 21.84, "Ты – подлинный герой." }, { 23.52, "Знай, что отныне Гинро Пылающий Очаг – твой друг до скончания веков!" } }, f = { { 0.00, "С возвращением!" }, { 1.17, "Раскал не так давно явился ко мне и сообщил обо всём, что произошло." }, { 6.25, "Я... да что там, вся наша крепость не знает, как тебя благодарить за твои подвиги." }, { 12.44, "Раскал погиб бы, если бы не твоя своевременная помощь." }, { 16.63, "А ведь ты помогаешь нам не ради платы, как какой-нибудь наёмник!" }, { 21.37, "Ты – подлинная героиня." }, { 23.16, "Знай, что отныне Гинро Пылающий Очаг – твой друг до скончания веков!" } } } } },
    [4266] = { d = 29.4, g = 1, v = "nightelf-male#55", n = { m = 342, f = 343 }, c = { m = { { 0.00, "Генерал Шандриса Оперённая Луна хотела бы поговорить с тобой лично." }, { 4.67, "Несомненно, она хочет поблагодарить тебя за всё, что ты сделал для крепости, но, насколько я знаю, она также хотела бы поговорить с тобой о тех насекомоподобных тварях, которых вы с Раскалом видели в южном Фераласе." }, { 19.41, "Сообщения об этих насекомых, которых именуют Цуккаш, звучат... скажем так: устрашающе." }, { 25.38, "Генерал Оперённая Луна ждёт тебя в главном здании." } }, f = { { 0.00, "Генерал Шандриса Оперённая Луна хотела бы поговорить с тобой лично." }, { 4.77, "Несомненно, она хочет поблагодарить тебя за всё, что ты сделала для крепости, но, насколько я знаю, она также хотела бы поговорить с тобой о тех насекомоподобных тварях, которых вы с Раскалом видели в южном Фераласе." }, { 19.91, "Сообщения об этих насекомых, которых именуют Цуккаш, звучат... скажем так: устрашающе." }, { 26.02, "Генерал Оперённая Луна ждёт тебя в главном здании." } } }, t = { d = 28.3, v = "nightelf-female#52", n = { x = 318 }, c = { x = { { 0.00, "Я от души благодарю тебя за всю оказанную тобой помощь." }, { 3.95, "Твоя отвага перед лицом превосходящих сил противника достойна награды в тысячу раз большей." }, { 10.44, "Тем не менее, я надеюсь, что ты примешь в дар от всей крепости хотя бы это." }, { 15.66, "А теперь, если можно... я хотела бы попросить тебя ещё об одной услуге." }, { 20.75, "Сейчас, когда здесь, в Фераласе, обнаружен улей Цуккаш, думаю, это задание следует поручить именно тебе..." } } } } },
    [4267] = { d = 30.6, v = "nightelf-female#52", n = { x = 360 }, c = { x = { { 0.00, "Я доверяю тебе копию отчёта Раскала о вторжении в юго-восточный Фералас." }, { 5.04, "Полный доклад будет отправлен на хранение в Дарнасс, а эту копию отнеси, пожалуйста, представителю Протектората." }, { 12.81, "Её зовут Грацина Сила Духа; это жрица, которая живёт в храме Луны в Дарнассе." }, { 18.28, "Она обладает обширными познаниями о подобных существах, так что, если она ознакомится с этим докладом, это пойдёт на пользу всем нам." }, { 27.42, "Можешь идти." }, { 28.36, "Удачи тебе, и да хранит нас Элуна!" } } }, t = { d = 35.7, v = "nightelf-female#52", n = { x = 421 }, c = { x = { { 0.00, "Нам, ночным эльфам, немало известно об ужасах, описанных в этом докладе." }, { 5.03, "Шандриса поступила мудро, отправив ко мне доклад – и тебя с ним." }, { 9.44, "Эти твари стремительно заполонят весь Фералас." }, { 12.66, "Можно сказать, что это одна из самых страшных опасностей, какие нам когда-либо грозили!" }, { 18.75, "Насекомые, с которыми столкнулись вы с курьером, называются силитидами." }, { 23.59, "Они – всего лишь орудие одной из величайших угроз, с какими встречались как Альянс, так и Орда." }, { 30.17, "Молюсь, чтобы у нас хватило решимости разгромить их прежде, чем они уничтожат нас!" } } } } },
    [4281] = { d = 24.1, v = "narrator", n = { x = 262 }, c = { x = { { 0.00, "Свёрток, который вы нашли в лагере гноллов-древолапов, следовало доставить в небольшой путевой лагерь Таланаар на юго-востоке Фераласа." }, { 10.35, "Неизвестно, какая судьба постигла курьера, однако свёрток так и остался недоставленным!" }, { 16.98, "Осмотрев пакет, вы видите на нём имя \"Хранитель дорог Фалфиндел\"." }, { 22.02, "Возможно, это имя адресата?" } } }, t = { d = 31.7, g = 1, v = "nightelf-male#54", n = { m = 317, f = 319 }, c = { m = { { 0.00, "Слава Элуне!" }, { 1.08, "Наконец-то пришла посылка из Крепости Оперённой Луны!" }, { 5.31, "Но раз её принёс ты, значит, с нашим курьером, Раскалом, что-то случилось?" }, { 11.11, "Надеюсь, что всё уладится..." }, { 13.33, "Насколько я знаю, в последнее время гноллы из клана Древолапов очень боятся чего-то, что происходит на юге." }, { 21.94, "Может быть, Раскал заблудился в глуши?" }, { 25.02, "Будь осторожнее." }, { 26.31, "Ну, как бы то ни было, спасибо тебе ещё раз." }, { 29.75, "А вот и плата за доставку!" } }, f = { { 0.00, "Слава Элуне!" }, { 1.04, "Наконец-то пришла посылка из Крепости Оперённой Луны!" }, { 5.12, "Но раз её принесла ты, значит, с нашим курьером, Раскалом, что-то случилось?" }, { 10.94, "Надеюсь, что всё уладится..." }, { 13.09, "Насколько я знаю, в последнее время гноллы из клана Древолапов очень боятся чего-то, что происходит на юге." }, { 21.39, "Может быть, Раскал заблудился в глуши?" }, { 24.37, "Будь осторожнее." }, { 25.62, "Ну, как бы то ни было, спасибо тебе ещё раз." }, { 28.94, "А вот и плата за доставку!" } } } } },
    [4282] = { d = 31.4, g = 1, v = "human-male#50", n = { m = 348, f = 349 }, c = { m = { { 0.00, "*Маршал Виндзор возбуждённо потрясает запиской.*" }, { 3.76, "Ты понимаешь, что это значит?" }, { 5.82, "Может быть, ещё не всё потеряно!" }, { 8.01, "Насколько я понял, информацией завладели два дворфа Чёрного Железа – генерал Кузня Гнева и повелитель големов Аргелмах." }, { 16.26, "Однако есть у меня подозрение, что они её не отдадут, даже если мы их очень вежливо попросим." }, { 22.75, "Надеюсь, ты готов сражаться." }, { 24.75, "Разыщи этих двоих негодяев!" }, { 26.75, "Убей их обоих и верни мне утерянную информацию." } }, f = { { 0.00, "*Маршал Виндзор возбуждённо потрясает запиской.*" }, { 3.84, "Ты понимаешь, что это значит?" }, { 6.01, "Может быть, ещё не всё потеряно!" }, { 8.31, "Насколько я понял, информацией завладели два дворфа Чёрного Железа – генерал Кузня Гнева и повелитель големов Аргелмах." }, { 16.99, "Однако есть у меня подозрение, что они её не отдадут, даже если мы их очень вежливо попросим." }, { 23.83, "Надеюсь, ты готова сражаться." }, { 26.00, "Разыщи этих двоих негодяев!" }, { 28.10, "Убей их обоих и верни мне утерянную информацию." } } }, t = { d = 4.6, v = "human-male#50", n = { x = 47 }, c = { x = { { 0.00, "*Маршал Виндзор выхватывает у вас из рук таблички.*" }, { 3.76, "Уходим!" } } } } },
    [4283] = { d = 37.9, v = "dwarf-male", n = { x = 393 }, c = { x = { { 0.00, "Открою тебе тайну, солдат." }, { 2.10, "Подойди-ка поближе." }, { 3.60, "Я ЕДИНСТВЕННЫЙ, КТО ЕЩЁ НЕ СПЯТИЛ!" }, { 6.11, "Посмотри на остальных." }, { 7.80, "Ты веришь, что они ненормальные?" }, { 10.24, "А так оно и есть!" }, { 11.53, "ПСИХИ!" }, { 12.08, "СУМАСШЕДШИЕ!" }, { 13.02, "Но пусть это останется между нами – тобой, мной и моим приятелем, капитаном Винкеем." }, { 20.08, "*Орелиус хватается за воздух и будто прижимает кого-то к себе.*" }, { 24.72, "В общем... помимо ушей огров, я собираю их солдатские медальоны." }, { 30.12, "Сегодня на повестке дня орки." }, { 32.59, "Пятьдесят штук." }, { 33.87, "ИДИ!" }, { 34.24, "*Орелиус трубит в рог.*" }, { 36.24, "ПОЛНЫЙ ВПЕРЁД!" } } }, t = { d = 6.3, g = 1, v = "dwarf-male", n = { m = 51, f = 52 }, c = { m = { { 0.00, "Ты справился!" }, { 1.32, "И вот твоя награда: ПОЧЕШИ МНЕ ЖИВОТИК!" }, { 5.17, "ДАВАЙ!" }, { 5.87, "ЧЕШИ!" } }, f = { { 0.00, "Ты справилась!" }, { 1.31, "И вот твоя награда: ПОЧЕШИ МНЕ ЖИВОТИК!" }, { 4.93, "ДАВАЙ!" }, { 5.59, "ЧЕШИ!" } } } } },
    [4284] = { d = 27.9, g = 1, v = "gnome-female", n = { m = 307, f = 308 }, c = { m = { { 0.00, "Уверена, ты видел их." }, { 1.54, "Они повсюду!" }, { 2.51, "Ты не понимаешь, о чём я?" }, { 4.24, "О кристаллах, конечно!" }, { 5.85, "Большинство их просто игнорирует, но я чувствую, что в них заключена какая-то сила." }, { 11.70, "Я уже давно провожу с ними эксперименты, но пока, видимо, так же далека от разгадки, как и в первые дни исследований..." }, { 20.11, "Впрочем, я не теряю надежды!" }, { 22.17, "Сейчас у меня почти вышел запас кристаллов." }, { 25.38, "Не поможешь ли мне его восполнить?" } }, f = { { 0.00, "Уверена, ты видела их." }, { 1.62, "Они повсюду!" }, { 2.59, "Ты не понимаешь, о чём я?" }, { 4.33, "О кристаллах, конечно!" }, { 5.95, "Большинство их просто игнорирует, но я чувствую, что в них заключена какая-то сила." }, { 11.83, "Я уже давно провожу с ними эксперименты, но пока, видимо, так же далека от разгадки, как и в первые дни исследований..." }, { 20.30, "Впрочем, я не теряю надежды!" }, { 22.37, "Сейчас у меня почти вышел запас кристаллов." }, { 25.61, "Не поможешь ли мне его восполнить?" } } }, t = { d = 3.4, v = "gnome-female", n = { x = 34 }, c = { x = { { 0.00, "Теперь я продолжу эксперименты." }, { 2.67, "Спасибо!" } } } } },
    [4285] = { d = 26.9, v = "gnome-female", n = { x = 275 }, c = { x = { { 0.00, "Что бы это могло быть?" }, { 1.75, "Я всё время думаю об этой загадке!" }, { 4.48, "Эти слухи о хрустальных пилонах просто сводят меня с ума!" }, { 9.10, "Можешь считать меня наивной дурочкой, но я верю почти всему, что мне рассказывают." }, { 15.55, "В общем, слыхала я, что один из пилонов находится совсем неподалёку отсюда – где-то на севере." }, { 22.83, "Пожалуйста, разыщи его!" }, { 24.72, "Я уверена, пилоны существуют!" } } }, t = { d = 3.9, v = "gnome-female", n = { x = 28 }, c = { x = { { 0.00, "Я знаю, что все эти рассказы – правда." } } } } },
    [4286] = { d = 22.0, v = "dwarf-male", n = { x = 221 }, c = { x = { { 0.00, "Капитан Винкей уверяет, что дворфы Чёрного Железа в Глубинах Чёрной горы загребли всё лучшее добро." }, { 7.33, "Верно, Винкей?" }, { 8.40, "*Орелиус, как может, изображает пирата.*" }, { 12.08, "АРРР, ПРИЯТЕЛЬ!" }, { 13.36, "ТАК ОНО И ЕСТЬ!" }, { 14.64, "Вот видишь?" }, { 15.61, "Иди туда и принеси мне образцы их добра." }, { 19.07, "Тряхни стариной и отправляйся вглубь!" } } }, t = { d = 11.8, v = "dwarf-male", n = { x = 138 }, c = { x = { { 0.00, "*Орелиус роется в груде поясных сумок.*" }, { 3.36, "ВЕЛИКОЛЕПНО!" }, { 4.43, "ВОСХИТИТЕЛЬНО!" }, { 6.34, "Только посмотри на это добро!" }, { 8.93, "Возьми одну себе, здесь их полно." } } } } },
    [4287] = { d = 27.6, v = "gnome-female", n = { x = 291 }, c = { x = { { 0.00, "За время моего пребывания здесь, до меня не раз доходили странные слухи о таинственных хрустальных пилонах, сокрытых в кратере." }, { 9.86, "Полагаю, они довольно велики." }, { 12.26, "Не могу отделаться от мысли, что в этих слухах есть доля истины, и эти пилоны как-то связаны с обнаруженными нами кристаллами..." }, { 22.33, "Удовлетвори моё любопытство, поищи пилон в восточной области кратера." } } }, t = { d = 6.5, v = "gnome-female", n = { x = 60 }, c = { x = { { 0.00, "Ун'Горо такое странное место!" }, { 2.66, "Входишь – и будто оказываешься в другом мире!" } } } } },
    [4288] = { d = 27.1, v = "gnome-female", n = { x = 285 }, c = { x = { { 0.00, "Мои опыты пока не принесли никаких положительных результатов." }, { 4.90, "Теперь я возлагаю надежды лишь на то, что ты сможешь найти один из пилонов, о существовании которых я слыхала." }, { 13.49, "Возможно, если смешать определённые цвета..." }, { 16.97, "Впрочем, я тороплю события." }, { 19.17, "Необходимо сначала найти его." }, { 21.59, "Исследуй западную область кратера, говорят, пилон находится именно там." } } }, t = { d = 10.2, v = "gnome-female", n = { x = 105 }, c = { x = { { 0.00, "В стенах кратера много ниш и пещер." }, { 2.90, "Попробуй обыскать извилистые тропинки в тех местах, если больше ничего не можешь придумать." } } } } },
    [4289] = { d = 41.6, v = "tauren-male#68", n = { x = 415 }, c = { x = { { 0.00, "В этом кратере встречается множество странных зверей – они похожи на тех, что водятся на моей родине, но выглядят более... породистыми." }, { 11.01, "Я не могу объяснить это, но мне кажется, это место – средоточие силы Матери-Природы." }, { 17.98, "Я воздаю ей хвалу всякий раз как встречаю одно из её прекрасных созданий в этом кратере." }, { 25.17, "Если ты тоже хочешь достигнуть просветления, отправляйся на север." }, { 30.60, "Там ты найдёшь огромных обезьян, помериться силами с которыми сочтёт за честь самый искусный воин." }, { 38.45, "Принеси мне их шкуры, докажи свою силу!" } } }, t = { d = 34.8, g = 1, v = "tauren-male#68", n = { m = 329, f = 332 }, c = { m = { { 0.00, "Значит, тебе хватило сил одолеть обезьян Ун'Горо." }, { 4.43, "Это славно." }, { 5.50, "Конечно, это не такая сложная задача, как сражение с Лар'корви, и всё же немалая победа." }, { 12.94, "Моё племя обрадуется шкурам, из них получатся прекрасные одежды!" }, { 18.33, "Ты помог мне и показал себя достойным." }, { 21.59, "Прежде чем ты отправишься далее, воздадим хвалу Матери-Земле и поблагодарим духов обезьян, убитых тобой – они должны знать, что их смерть была не напрасна!" } }, f = { { 0.00, "Значит, тебе хватило сил одолеть обезьян Ун'Горо." }, { 4.28, "Это славно." }, { 5.35, "Конечно, это не такая сложная задача, как сражение с Лар'корви, и всё же немалая победа." }, { 12.85, "Моё племя обрадуется шкурам, из них получатся прекрасные одежды!" }, { 18.28, "Ты помогла мне и показала себя достойной." }, { 21.80, "Прежде чем ты отправишься далее, воздадим хвалу Матери-Земле и поблагодарим духов обезьян, убитых тобой – они должны знать, что их смерть была не напрасна!" } } } } },
    [4290] = { d = 39.6, v = "tauren-male#68", n = { x = 390 }, c = { x = { { 0.00, "Однажды мой брат имел неосторожность отрезать кусок мяса от добычи Лар'корви, когда того не было рядом." }, { 8.59, "Однако оказалось, что Лар'корви наблюдал за моим братом из укрытия." }, { 14.14, "Он преследовал моего брата долгие недели, разрушая всё на своём пути." }, { 19.84, "Наконец, брат мой в страхе решил покинуть кратер." }, { 23.91, "Но Лар'корви настиг его недалеко от этого места и убил его." }, { 28.95, "Если хочешь привлечь к себе внимание Лар'корви, найди его свежеубитую добычу и отрежь от неё кусок мяса." }, { 37.68, "Затем возвращайся ко мне." } } }, t = { d = 28.8, g = 1, v = "tauren-male#68", n = { m = 284, f = 286 }, c = { m = { { 0.00, "Этот кусок послужит хорошей приманкой." }, { 3.20, "Похоже, удача в охоте сопутствует Лар'корви." }, { 6.84, "Однако странно, где он смог найти жесткозуба в этих краях..." }, { 11.71, "Я сохраню это для тебя до тех пор, пока ты не будешь готов встретиться с чудовищем." }, { 18.40, "Не волнуйся за меня – полагаю, ты уже успел так разозлить Лар'корви, что он не станет убивать меня раньше, чем вкусит твоей плоти." } }, f = { { 0.00, "Этот кусок послужит хорошей приманкой." }, { 3.15, "Похоже, удача в охоте сопутствует Лар'корви." }, { 6.73, "Однако странно, где он смог найти жесткозуба в этих краях..." }, { 11.52, "Я сохраню это для тебя до тех пор, пока ты не будешь готова встретиться с чудовищем." }, { 18.18, "Не волнуйся за меня – полагаю, ты уже успела так разозлить Лар'корви, что он не станет убивать меня раньше, чем вкусит твоей плоти." } } } } },
    [4291] = { d = 37.4, v = "tauren-male#68", n = { x = 370 }, c = { x = { { 0.00, "Я удивлён, что Лар'корви не вышел к тебе!" }, { 3.32, "И всё же у меня есть задумка, как выманить его." }, { 7.16, "Поскольку Лар'корви – доминирующий самец в своей стае, он может выбирать любую самку." }, { 14.25, "А выбирает он многих!" }, { 16.02, "Ты найдёшь много кладок равазавров к западу отсюда." }, { 20.23, "Подберись к ним поближе и спровоцируй самок атаковать тебя." }, { 25.11, "В их головах находятся железы, источающие жуткий запах – так эти твари оповещают своих самцов о готовности к размножению." }, { 35.08, "Принеси мне две такие железы." } } }, t = { d = 21.3, v = "tauren-male#68", n = { x = 195 }, c = { x = { { 0.00, "Это отличные образцы." }, { 2.02, "С их помощью мы сможем выманить Лар'корви." }, { 5.83, "Мне не терпится узнать, чем закончится твой бой с чудовищем." }, { 11.08, "Это огромная тварь с зубами, подобными булатным клинкам." }, { 16.18, "Ты посмотришь в его глаза и познаешь, каков взгляд смерти." } } } } },
    [4292] = { d = 37.4, v = "tauren-male#68", n = { x = 366 }, c = { x = { { 0.00, "Это самая сложная часть нашего плана." }, { 3.20, "К северу отсюда есть узкая тропинка, ведущая в горы." }, { 7.59, "Именно там я в последний раз видел Лар'корви." }, { 11.31, "Ты легко узнаешь это место – там повсюду разбросаны дочиста обглоданные кости крупных животных, имевших неосторожность подойти слишком близко к логову Лар'корви." }, { 24.71, "Положишь там принесённое с собой мясо." }, { 27.84, "Затем полей мясо вот этим составом." }, { 30.89, "Если это не выманит к тебе Лар'корви, то я не знаю, чем ещё его можно заманить." } } }, t = { d = 21.8, g = 1, v = "tauren-male#68", n = { m = 190, f = 192 }, c = { m = { { 0.00, "Хвала Матери-Земле!" }, { 1.95, "Ты справился!" }, { 3.22, "Ты показал себя великим." }, { 5.59, "Твой дух силён." }, { 6.94, "Твоей храбрости нет равных." }, { 9.57, "А сила твоя укрепилась." }, { 11.85, "Я склоняюсь пред твоим мастерством." }, { 15.15, "Только самым великим из моих предков были под силу подобные свершения." } }, f = { { 0.00, "Хвала Матери-Земле!" }, { 1.91, "Ты справилась!" }, { 3.24, "Ты показала себя великой." }, { 5.65, "Твой дух силён." }, { 6.98, "Твоей храбрости нет равных." }, { 9.55, "А сила твоя укрепилась." }, { 11.80, "Я склоняюсь пред твоим мастерством." }, { 15.04, "Только самым великим из моих предков были под силу подобные свершения." } } } } },
    [4293] = { d = 36.8, v = "scourge-male", n = { x = 385 }, c = { x = { { 0.00, "Осквернённый лес находится далеко на севере от Степей – даже дальше, чем Ясеневый лес." }, { 6.82, "Вокруг тамошних заводей, благословленных касанием Скверны, полно слизнюков." }, { 12.92, "Плеть наводнила эти земли инферналами и прочими демонами." }, { 17.57, "Судя по всему, в это время слизнюки и полезли из-под земли." }, { 22.51, "Собери образцы слизнюков Осквернённого леса – мы проверим их при помощи моего оборудования и создадим контрольную группу, чтобы сопоставить её с другими принесёнными тобой образцами." } } }, t = { d = 36.2, v = "scourge-male", n = { x = 318 }, c = { x = { { 0.00, "Великолепно." }, { 1.17, "Эти пробы прекрасно подойдут." }, { 4.02, "Благодарю за помощь." }, { 5.94, "Собрав все образцы слизи, мы сможем двинуться дальше." }, { 10.96, "Я начинаю подозревать, что леди Сильвана не зря заинтересовалась этими существами." }, { 18.49, "Более того, сама того не зная, она, похоже, оказалась на грани великого открытия." }, { 26.28, "Эти пробы очень интересны." }, { 28.87, "А как они прореагировали с моими препаратами... хм, да, нам есть над чем поработать." } } } } },
    [4294] = { d = 43.4, g = 1, v = "scourge-male", n = { m = 432, f = 434 }, c = { m = { { 0.00, "Тебе приходилось слышать о Кратере Ун'Горо?" }, { 3.66, "Он расположен рядом с пустыней Танарис." }, { 6.95, "Великолепное место: тамошние буйные заросли буквально кишат жизнью!" }, { 12.64, "А какие там растения…" }, { 14.43, "Именно туда тебе и следует отправиться." }, { 17.80, "До меня дошли слухи, что в этих местах сохранилась практически девственная природа." }, { 24.75, "Исследователи лишь недавно добрались до них, и далеко не все тайны ещё раскрыты." }, { 31.26, "Я хочу, чтобы ты принёс мне образцы живущих там слизнюков." }, { 36.04, "Если слухи правдивы и их не тронула порча, я смогу узнать, откуда появились эти существа." } }, f = { { 0.00, "Тебе приходилось слышать о Кратере Ун'Горо?" }, { 3.58, "Он расположен рядом с пустыней Танарис." }, { 6.79, "Великолепное место: тамошние буйные заросли буквально кишат жизнью!" }, { 12.34, "А какие там растения…" }, { 14.09, "Именно туда тебе и следует отправиться." }, { 17.38, "До меня дошли слухи, что в этих местах сохранилась практически девственная природа." }, { 24.17, "Исследователи лишь недавно добрались до них, и далеко не все тайны ещё раскрыты." }, { 30.52, "Я хочу, чтобы ты принесла мне образцы живущих там слизнюков." }, { 35.42, "Если слухи правдивы и их не тронула порча, я смогу узнать, откуда появились эти существа." } } }, t = { d = 38.3, v = "scourge-male", n = { x = 320 }, c = { x = { { 0.00, "Удивительно!" }, { 1.21, "Кратер Ун'Горо таит куда больше секретов, чем я думал." }, { 6.54, "Интересно, какие ещё открытия нас ждут?" }, { 10.25, "Поразительно..." }, { 11.71, "Изумительно чистые образцы." }, { 14.38, "Хм, что бы это значило?" }, { 16.62, "Похоже, по природе они относятся скорее к стихиям... но непростым." }, { 22.99, "Они напоминают мне... о Древних богах." }, { 26.69, "Мы находили их следы по всему Азероту – вдруг и эти существа каким-то образом связаны с ними?" }, { 35.64, "Надо продолжать исследования." } } } } },
    [4295] = { t = { d = 11.2, v = "dwarf-male", n = { x = 94 }, c = { x = { { 0.00, "Это что?" }, { 0.85, "Ага!" }, { 1.36, "Пахнет элем Чёрного Железа!" }, { 3.99, "Пусть я пьян и мало что соображаю, но скажу тебе, добрый сэр: ты настоящий друг!" } } } } },
    [4296] = { d = 27.8, v = "goblin-male", n = { x = 296 }, c = { x = { { 0.00, "Я прибыл в Пылающие степи из-за легенд о Семерых." }, { 3.82, "Это были дворфы, прославленные знаниями и силой, а значит – и богатством." }, { 9.42, "Именно к богатству я и стремлюсь!" }, { 11.95, "Узнай мы побольше про Семерых, могли бы оба разбогатеть." }, { 16.25, "Говорят, что в руинах Тауриссана есть табличка Семерых, содержащая знания древних дворфов." }, { 23.07, "Найди её, перепиши текст и принеси мне." }, { 26.01, "И мы оба узнаем её тайны!" } } }, t = { d = 10.6, g = 1, v = "goblin-male", n = { m = 87, f = 88 }, c = { m = { { 0.00, "А, ты нашёл табличку!" }, { 1.83, "И как хорошо переписан текст!" }, { 4.37, "Ты точно герой, а не переписчик?" }, { 7.22, "Вот, возьми." }, { 8.33, "Это обещанные деньги." } }, f = { { 0.00, "А, ты нашла табличку!" }, { 1.93, "И как хорошо переписан текст!" }, { 4.51, "Ты точно героиня, а не переписчица?" }, { 7.66, "Вот, возьми." }, { 8.79, "Это обещанные деньги." } } } } },
    [4297] = { d = 39.7, v = "dwarf-male", n = { x = 429 }, c = { x = { { 0.00, "Летучие хамелеоны всеядны: это значит, что они питаются как животной, так и растительной пищей." }, { 6.94, "Твоё яйцо вот-вот проклюнется, и мы должны быть к этому готовы." }, { 11.53, "Лучшая еда для этих малявок – это мясо, свежее, сочное мясо!" }, { 16.11, "Хочешь – верь, хочешь – нет." }, { 18.14, "Почему – я так и не выяснил, но, кажется, это имеет какое-то отношение к замыслу Элуны относительно эльфов." }, { 25.94, "Возможно, они должны были быть защитниками... не знаю." }, { 29.93, "Яйцо я пока покараулю, а ты сходи и добудь мне свеженьких окороков среброгривых бродяг." }, { 36.29, "Ими-то мы и покормим малыша, когда он вылупится." } } }, t = { d = 14.1, g = 1, v = "dwarf-male", n = { m = 145, f = 145 }, c = { m = { { 0.00, "Да, это мясо вполне годится." }, { 2.31, "А тем временем, если я не ошибаюсь, твой дракончик начинает вылупляться!" }, { 7.85, "Ну, как тебе это?" }, { 9.25, "В смысле, каково быть папой?" }, { 11.50, "Груз ответственности не давит пока?" } }, f = { { 0.00, "Да, это мясо вполне годится." }, { 2.31, "А тем временем, если я не ошибаюсь, твой дракончик начинает вылупляться!" }, { 7.85, "Ну, как тебе это?" }, { 9.25, "В смысле, каково быть мамой?" }, { 11.50, "Груз ответственности не давит пока?" } } } } },
    [4298] = { d = 2.9, v = "dwarf-male", n = { x = 22 }, c = { x = { { 0.00, "Ух ты, да он уже вылупляется!" } } }, t = { d = 15.8, g = 1, v = "dwarf-male", n = { m = 172, f = 172 }, c = { m = { { 0.00, "Вот, бери яйцо..." }, { 1.34, "Тебе лучше держать его при себе, чтобы вылупившийся детёныш сразу привязался к тебе." }, { 7.69, "Тогда он будет считать тебя своим папочкой." }, { 11.04, "Ну всё, поздравляю!" }, { 12.44, "У тебя теперь всё равно что собственный ребёнок!" } }, f = { { 0.00, "Вот, бери яйцо..." }, { 1.30, "Тебе лучше держать его при себе, чтобы вылупившийся детёныш сразу привязался к тебе." }, { 7.46, "Тогда он будет считать тебя своей мамочкой." }, { 10.70, "Ну всё, поздравляю!" }, { 12.07, "У тебя теперь всё равно что собственный ребёнок!" } } } } },
    [4300] = { d = 37.0, v = "troll-male", n = { x = 372 }, c = { x = { { 0.00, "Да, если так подумать, то, пожалуй, для тебя есть работёнка." }, { 4.68, "Джес'римону пригодится твоя помощь." }, { 7.57, "В Кратере Ун'Горо водятся ящеры – с когтями острыми, как бритва." }, { 12.76, "У большинства ящеров когти чёрные, как смерть, но у некоторых ящеров они белые." }, { 19.02, "У Раздроблённой Руки имеются... клиенты, которые очень ценят оружие, изготовленное из таких когтей." }, { 26.95, "Принеси побольше белых когтей, и Джес'римон заплатит тебе по совести." }, { 32.57, "А если сделаешь это быстро, то получишь кое-что сверху." } } }, t = { d = 13.8, v = "troll-male", n = { x = 125 }, c = { x = { { 0.00, "Да, это то, что надо!" }, { 1.87, "Спасибо." }, { 2.64, "И тебе удалось уложиться в срок... это замечательно." }, { 7.15, "Быть может, мы сумеем изготовить из этих когтей оружие и для тебя." }, { 12.91, "Что скажешь?" } } } } },
    [4301] = { d = 45.9, g = 1, v = "tauren-male#68", n = { m = 431, f = 433 }, c = { m = { { 0.00, "Пока ты исследовал Ун'Горо, я встретил и других созданий, охота на которых доставит удовольствие такому мастеру как ты." }, { 10.15, "Одно из них – огромная обезьяна, я видел её в стае других обезьян к северу отсюда." }, { 17.23, "Ты уже бывал в этой пещере раньше, однако не могу ручаться, что выйдешь из этой схватки живым, если действительно возьмёшься за это задание." }, { 29.31, "Я зову его Уча, и он один из величайших сыновей Матери-Земли, можешь не сомневаться." }, { 36.54, "Убей Учу и принеси мне его шкуру." }, { 39.54, "Сделай это, и я буду отстаивать твоё право называть себя великим охотником." } }, f = { { 0.00, "Пока ты исследовала Ун'Горо, я встретил и других созданий, охота на которых доставит удовольствие такому мастеру как ты." }, { 10.02, "Одно из них – огромная обезьяна, я видел её в стае других обезьян к северу отсюда." }, { 16.95, "Ты уже бывала в этой пещере раньше, однако не могу ручаться, что выйдешь из этой схватки живой, если действительно возьмёшься за это задание." }, { 28.85, "Я зову его Уча, и он один из величайших сыновей Матери-Земли, можешь не сомневаться." }, { 35.93, "Убей Учу и принеси мне его шкуру." }, { 38.87, "Сделай это, и я буду отстаивать твоё право называть себя великой охотницей." } } }, t = { d = 24.2, g = 1, v = "tauren-male#68", n = { m = 198, f = 202 }, c = { m = { { 0.00, "Отлично!" }, { 0.88, "Я доволен." }, { 1.94, "Сегодня ты совершил великое деяние." }, { 5.47, "Уча был одной из самых огромных обезьян, виденных мною за всю жизнь." }, { 12.16, "То, что ты смог сразить его, говорит о твоей собственной силе и храбрости." }, { 19.39, "Прими это в знак моего уважения." }, { 22.65, "Ты заслужил это." } }, f = { { 0.00, "Отлично!" }, { 0.82, "Я доволен." }, { 1.81, "Сегодня ты совершила великое деяние." }, { 5.18, "Уча был одной из самых огромных обезьян, виденных мною за всю жизнь." }, { 11.44, "То, что ты смогла сразить его, говорит о твоей собственной силе и храбрости." }, { 18.43, "Прими это в знак моего уважения." }, { 21.48, "Ты заслужила это." } } } } },
    [4321] = { d = 12.2, g = 1, v = "gnome-female", n = { m = 137, f = 138 }, c = { m = { { 0.00, "То, что ты рассказал мне о пилонах, весьма интересно..." }, { 3.68, "Дай мне минутку, мне нужно сделать некоторые расчёты..." }, { 7.35, "Зайди ко мне через пару минут, я смогу дать ответ на твой вопрос." } }, f = { { 0.00, "То, что ты рассказала мне о пилонах, весьма интересно..." }, { 3.89, "Дай мне минутку, мне нужно сделать некоторые расчёты..." }, { 7.72, "Зайди ко мне через пару минут, я смогу дать ответ на твой вопрос." } } }, t = { d = 15.8, v = "gnome-female", n = { x = 143 }, c = { x = { { 0.00, "Так вот!" }, { 0.70, "Всё это очень интересно..." }, { 3.04, "Надеюсь, мои диаграммы верны!" }, { 5.70, "Я собрала все сведения в эту книгу и отдам её тебе." }, { 10.22, "Полагаю, теперь я могу ответить на все твои вопросы о кристаллах." } } } } },
    [4322] = { d = 15.5, v = "human-male#50", n = { x = 199 }, c = { x = { { 0.00, "Пора выбираться отсюда." }, { 1.55, "Помоги мне забрать мои вещи со склада и освободить моих друзей." }, { 5.69, "Если у нас всё получится и нам удастся отсюда сбежать, отправляйся в Дозор Моргана и расскажи обо всём маршалу Максвеллу." }, { 13.34, "Он тебе скажет, что делать дальше." } } }, t = { d = 21.8, v = "human-male", n = { x = 259 }, c = { x = { { 0.00, "Поразительно." }, { 0.96, "Просто невероятно." }, { 2.29, "Виндзор был здесь буквально перед твоим приходом." }, { 5.80, "Ворвался, как ураган, весь такой разгорячённый и буйный." }, { 9.69, "Его притязания поистине грандиозны, но он заявляет, что у него есть на то основания." }, { 15.55, "Сейчас он направляется в Штормград и собирается бросить вызов Болвару и... госпоже Престор." } } } } },
    [4324] = { d = 40.9, v = "goblin-female#63", n = { x = 454 }, c = { x = { { 0.00, "Риббли, мой младший братец, всю жизнь был никчёмным придурком и позором для всей семьи, но в итоге оказалось, что он тоже чего-то да стоит и может пригодиться." }, { 11.23, "Но понимаешь, какое дело... чтобы приставить его к работе, нам понадобится твоя помощь." }, { 17.59, "Моя сестра Юка искала его почти месяц, и в итоге ей удалось узнать, что он прячется в Пылающих степях." }, { 25.12, "Ей нужен наёмник, и она обратилась ко мне за помощью." }, { 28.89, "Не хочешь взяться за это дело?" }, { 31.16, "Если берёшься, тогда тебе надо переговорить с сестрой." }, { 35.12, "Ты найдёшь её в Пламенеющем Стяге, в пещере к северо-западу от скалы Молота Ужаса." } } }, t = { d = 11.2, v = "goblin-female#63", n = { x = 102 }, c = { x = { { 0.00, "Да, я ищу брата." }, { 1.43, "Его надо найти и вернуть." }, { 3.68, "Приведи его ко мне." }, { 5.34, "А если он будет сопротивляться... тогда принеси мне хотя бы его голову." } } } } },
    [4341] = { d = 33.9, v = "dwarf-male#177", n = { x = 305 }, c = { x = { { 0.00, "Тебе приходилось бывать в дымящихся руинах Тауриссана?" }, { 4.75, "А тебе не попадался этот жалкий бездельник Каран Могучий Молот?" }, { 10.35, "Это дворф, который был должен охранять мою девочку!" }, { 14.86, "И теперь она пропала!" }, { 17.35, "Мои воины обшарили всю Степь." }, { 19.92, "Им удалось узнать только то, что моя дочка может быть в Глубинах." }, { 25.60, "Может, она уже погибла!" }, { 27.78, "А Каран, видимо, сидит там в плену... найди его!" }, { 32.05, "Я хочу получить ответ!" } } }, t = { d = 2.7, v = "dwarf-male", n = { x = 26 }, c = { x = { { 0.00, "Прошу, позволь мне объясниться!" } } } } },
    [4342] = { d = 4.0, v = "dwarf-male", n = { x = 40 }, c = { x = { { 0.00, "Пожалуйста, выслушай меня, а потом будешь судить!" } } }, t = { d = 3.8, g = 1, v = "dwarf-male", n = { m = 36, f = 37 }, c = { m = { { 0.00, "Как ты сам понимаешь, я ничего не мог сделать." } }, f = { { 0.00, "Как ты сама понимаешь, я ничего не мог сделать." } } } } },
    [4343] = { t = { d = 13.5, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений." }, { 6.73, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4361] = { d = 4.2, v = "dwarf-male", n = { x = 42 }, c = { x = { { 0.00, "Расскажи обо всём королю Магни." }, { 2.61, "Он знает, что делать." } } }, t = { d = 3.8, v = "dwarf-male#177", n = { x = 36 }, c = { x = { { 0.00, "*Король Магни в ярости бьёт кулаком по столу.*" } } } } },
    [4362] = { d = 39.0, v = "dwarf-male#177", n = { x = 352 }, c = { x = { { 0.00, "Похоже, и моя судьба, и судьба королевства Стальгорн ныне в руках моего старинного врага Даграна Тауриссана." }, { 9.88, "Возможно, вы моя последняя надежда." }, { 13.15, "Вы должны спасти мою драгоценную дочь Мойру!" }, { 17.23, "Есть только один путь наверняка разрушить лежащее на Мойре заклятие Тауриссана – убить его." }, { 25.56, "Но умоляю, не причиняйте ей вреда!" }, { 28.67, "Помните, она под властью Тауриссана!" }, { 32.01, "Всё, что она будет делать или говорить, – результат злого заклятия Тауриссана!" } } }, t = { d = 2.2, v = "dwarf-female", n = { x = 57 }, c = { x = { { 0.00, "За что???" } } } } },
    [4363] = { d = 25.0, g = 1, v = "dwarf-female", n = { m = 268, f = 269 }, c = { m = { { 0.00, "Тауриссан был великим и доблестным дворфом." }, { 3.66, "Ты разрушил мою жизнь и жизнь моего будущего ребёнка!" }, { 8.00, "*Вы уверены, что принцесса до сих пор пребывает под действием чар императора.*" }, { 13.28, "Возвращайся в Стальгорн и скажи моему отцу, что наследником королевства будет дворф Чёрного Железа." }, { 20.54, "Нравится это ему или нет, но именно так всё и будет!" } }, f = { { 0.00, "Тауриссан был великим и доблестным дворфом." }, { 3.70, "Ты разрушила мою жизнь и жизнь моего будущего ребёнка!" }, { 8.16, "*Вы уверены, что принцесса до сих пор пребывает под действием чар императора.*" }, { 13.52, "Возвращайся в Стальгорн и скажи моему отцу, что наследником королевства будет дворф Чёрного Железа." }, { 21.04, "Нравится это ему или нет, но именно так всё и будет!" } } }, t = { d = 22.7, v = "dwarf-male#177", n = { x = 207 }, c = { x = { { 0.00, "*Король Магни Бронзобород явно расстроен.*" }, { 3.59, "Сдаётся мне, даже в смерти Тауриссан победил." }, { 8.05, "Больше я не нуждаюсь в твоих услугах." }, { 11.67, "Но прежде чем ты покинешь нас, выбери себе награду из королевских сокровищниц." }, { 19.01, "*Король садится на трон и погружается в раздумья.*" } } } } },
    [4381] = { t = { d = 15.6, v = "narrator", n = { x = 162 }, c = { x = { { 0.00, "Вы аккуратно выстраиваете кристаллы в табличке." }, { 3.86, "Когда последний из них занимает своё место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино." }, { 12.78, "Теперь полученное сочетание – ваше." } } } } },
