    [4386] = { t = { d = 15.0, v = "narrator", n = { x = 162 }, c = { x = { { 0.00, "Вы аккуратно выстраиваете кристаллы в табличке." }, { 3.71, "Когда последний из них занимает своё место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино." }, { 12.26, "Теперь полученное сочетание – ваше." } } } } },
    [4401] = { t = { d = 13.8, v = "narrator", n = { x = 153 }, c = { x = { { 0.00, "Вы обрабатываете песнецвет некоторым количеством кенарийского бальзама исцеления растений." }, { 7.14, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4402] = { d = 29.5, v = "orc-male", n = { x = 291 }, c = { x = { { 0.00, "Ну и жарища у нас в Долине Испытаний!" }, { 3.36, "*Галгар утирает пот со лба.*" }, { 5.84, "Были бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт!" }, { 11.73, "Ничто не освежает лучше этого восхитительного лакомства." }, { 15.95, "Знаешь что?" }, { 16.82, "Принеси-ка мне десяток плодов кактуса, и я приготовлю для тебя несколько порций десерта." }, { 23.39, "Пригодится в путешествиях." }, { 25.33, "Плоды кактуса можно собрать с тех, что растут вокруг." } } }, t = { d = 7.9, v = "orc-male", n = { x = 69 }, c = { x = { { 0.00, "Замечательно!" }, { 1.24, "А вот и твой кактусовый десерт, как было обещано." }, { 5.69, "И ещё кое-что в придачу..." } } } } },
    [4403] = { t = { d = 13.6, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений." }, { 6.77, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4421] = { d = 40.0, v = "nightelf-female", n = { x = 480 }, c = { x = { { 0.00, "Мало кто отваживается искать здесь приключений..." }, { 3.37, "Порча, поразившая Осквернённый лес, расползается, поражая всё без разбору." }, { 8.35, "Я, состоя в Изумрудном Круге, ищу способ исцелить эти земли, но есть те, кто радуется их мучениям." }, { 15.15, "Я говорю о сатирах из племени Нефритового Пламени, что живут к северо-западу отсюда, в руинах Констелласа." }, { 22.50, "Ими предводительствует особенно жестокий сатир по имени Ксаватрас." }, { 27.11, "Они продолжают поражать заразой любое живое существо, которое попадается им на пути." }, { 33.04, "Мы должны защитить этот край – ведь некогда он был нашим." }, { 36.96, "Срази Ксаватраса и уничтожь его приспешников." } } }, t = { d = 17.3, v = "nightelf-female", n = { x = 201 }, c = { x = { { 0.00, "Избавление Осквернённого леса от Ксаватраса – только первый шаг на долгом пути." }, { 5.49, "Придётся долго трудиться, чтобы залечить раны этой земли." }, { 9.60, "Я чувствую, что за всем этим стоит нечто большее, чем какие-то сатиры, но правду мы узнаем только со временем..." } } } } },
    [4441] = { d = 31.6, g = 1, v = "nightelf-female", n = { m = 380, f = 380 }, c = { m = { { 0.00, "Флейта, найденная тобой, вырезана из древесины сторожевого древа, верного союзника ночных эльфов." }, { 6.73, "Сатиры поражают порчей всё, на что наталкиваются, в том числе и древа, для которых Осквернённый лес был домом родным." }, { 14.57, "Из-за скверны духи древ попали в узы и теперь терзаются, не в силах освободиться." }, { 20.19, "Эти узы скверны, что ты нашёл, наверняка с этим связаны." }, { 24.08, "Мы должны попытаться очистить эту флейту от скверны." }, { 27.73, "Принеси мне благословенной воды из дарнасского храма Луны." } }, f = { { 0.00, "Флейта, найденная тобой, вырезана из древесины сторожевого древа, верного союзника ночных эльфов." }, { 6.55, "Сатиры поражают порчей всё, на что наталкиваются, в том числе и древа, для которых Осквернённый лес был домом родным." }, { 14.18, "Из-за скверны духи древ попали в узы и теперь терзаются, не в силах освободиться." }, { 19.65, "Эти узы скверны, что ты нашла, наверняка с этим связаны." }, { 23.49, "Мы должны попытаться очистить эту флейту от скверны." }, { 27.04, "Принеси мне благословенной воды из дарнасского храма Луны." } } }, t = { d = 5.6, v = "nightelf-female", n = { x = 63 }, c = { x = { { 0.00, "Спасибо тебе." }, { 1.06, "Будем же молиться, чтобы нам удалось исцелить нанесённые раны..." } } } } },
    [4442] = { d = 14.2, v = "nightelf-female", n = { x = 156 }, c = { x = { { 0.00, "При помощи сей воды Элуны я попытаюсь смыть скверну с этой флейты." }, { 4.88, "Мы должны покончить со страданиями..." }, { 7.58, "Да направит мою руку Элуна и да укрепит она моё сердце." }, { 11.73, "Подожди немного – потом поговорим." } } }, t = { d = 26.9, g = 1, v = "nightelf-female", n = { m = 325, f = 327 }, c = { m = { { 0.00, "При помощи этой благословенной воды я сумела разорвать связь между флейтой и духами Дерев." }, { 6.16, "Но я всё же уверена, что если ты заиграешь на этой флейте в священном месте, то ты мог бы призвать духов Дерев." }, { 13.60, "Возможно, тебе следует попытаться сделать это в руинах в южной части Железнолесья." }, { 19.27, "Некогда там обитало много осквернённых древней, и, возможно, они и до сих пор там находятся, пусть и в обличье духов." } }, f = { { 0.00, "При помощи этой благословенной воды я сумела разорвать связь между флейтой и духами Дерев." }, { 6.12, "Но я всё же уверена, что если ты заиграешь на этой флейте в священном месте, то ты могла бы призвать духов Дерев." }, { 13.69, "Возможно, тебе следует попытаться сделать это в руинах в южной части Железнолесья." }, { 19.33, "Некогда там обитало много осквернённых древней, и, возможно, они и до сих пор там находятся, пусть и в обличье духов." } } } } },
    [4443] = { t = { d = 13.8, v = "narrator", n = { x = 148 }, c = { x = { { 0.00, "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений." }, { 6.96, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
