    [4446] = { t = { d = 13.6, v = "narrator", n = { x = 148 }, c = { x = { { 0.00, "Вы обрабатываете кнутокорень тремя порциями кенарийского бальзама исцеления растений." }, { 6.84, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4447] = { t = { d = 14.2, v = "narrator", n = { x = 154 }, c = { x = { { 0.00, "Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений." }, { 7.41, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4448] = { t = { d = 13.8, v = "narrator", n = { x = 154 }, c = { x = { { 0.00, "Вы обрабатываете Ночного дракона четырьмя порциями кенарийского бальзама исцеления растений." }, { 7.24, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и оживает." } } } } },
    [4449] = { d = 25.3, v = "dwarf-male", n = { x = 263 }, c = { x = { { 0.00, "Эй!" }, { 0.27, "Эй, ты, там!" }, { 1.16, "Иди скорей сюда!" }, { 2.52, "Помоги мне!" }, { 3.41, "Я спасался бегством от дворфов Чёрного Железа и попытался спрятаться от них здесь." }, { 9.48, "Проклятые геологи со своей проклятой магией!" }, { 12.88, "Они увидели, что я здесь прячусь, и заперли меня!" }, { 16.63, "Проучи, проучи этих проклятых геологов!" }, { 19.70, "И... это... добудь мне несколько лоскутков шёлка... так... вдруг пригодится..." } } }, t = { d = 15.5, g = 1, v = "dwarf-male", n = { m = 132, f = 133 }, c = { m = { { 0.00, "О, отличная штука!" }, { 1.60, "И на ощупь приятная!" }, { 3.34, "Что?" }, { 3.72, "А, да... геологи." }, { 5.17, "Задал ты им жару, а?" }, { 6.91, "Не знаю, как тебя и благодарить." }, { 9.65, "Теперь у меня будет время закончить тут дела..." }, { 13.75, "Ещё раз спасибо!" } }, f = { { 0.00, "О, отличная штука!" }, { 1.64, "И на ощупь приятная!" }, { 3.43, "Что?" }, { 3.82, "А, да... геологи." }, { 5.30, "Задала ты им жару, а?" }, { 7.18, "Не знаю, как тебя и благодарить." }, { 9.98, "Теперь у меня будет время закончить тут дела..." }, { 14.19, "Ещё раз спасибо!" } } } } },
    [4450] = { d = 30.9, v = "dwarf-male", n = { x = 364 }, c = { x = { { 0.00, "Ты знаешь, мне это кое-что напоминает." }, { 2.66, "Не хочешь закончить за меня одну работёнку, за которую я взялся в Танарисе?" }, { 7.78, "Это пара пустяков..." }, { 9.26, "Кринкель Сталлинн из Прибамбасска искал какие-то вещи – некоторые здесь, в Тлеющем ущелье, а некоторые в других местах." }, { 17.42, "Может, глянешь на список?" }, { 19.21, "Ты наверняка сможешь что-нибудь найти." }, { 21.86, "Если тебе это интересно, я просуну его учётную книгу под дверь." }, { 26.25, "Отнесёшь её ему вместе с разыскиваемыми вещами, когда соберёшь их все." } } }, t = { d = 18.6, g = 1, v = "goblin-male#110", n = { m = 165, f = 168 }, c = { m = { { 0.00, "Ого, да ты смог выполнить эту работу!" }, { 3.09, "Прекрасно." }, { 3.97, "А я-то думал, ты пришёл просить меня что-нибудь выковать." }, { 8.67, "Всё в идеальном состоянии... и всё на месте." }, { 12.20, "Благодарю тебя, герой!" }, { 14.11, "Думаю, ты заслужил... хммм... что-нибудь полезное." } }, f = { { 0.00, "Ого, да ты смогла выполнить эту работу!" }, { 3.33, "Прекрасно." }, { 4.22, "А я-то думал, ты пришла просить меня что-нибудь выковать." }, { 9.03, "Всё в идеальном состоянии... и всё на месте." }, { 12.58, "Благодарю тебя, героиня!" }, { 14.65, "Думаю, ты заслужила... хммм... что-нибудь полезное." } } } } },
    [4451] = { d = 23.0, v = "narrator", n = { x = 261 }, c = { x = { { 0.00, "Маленький медный ключик выглядит совершенно непритязательно." }, { 4.58, "Единственное, что выдаёт его значимость, – надпись, выгравированная на бородке:" }, { 10.46, "\"Служебные помещения Чёрного Железа – изготовление дубликатов строжайше запрещено\"." }, { 16.68, "У вас нет ни малейшего представления, что это за ключ и куда ведёт открываемая им дверь." } } }, t = { d = 17.0, g = 1, v = "dwarf-male", n = { m = 176, f = 176 }, c = { m = { { 0.00, "Вот те на!" }, { 0.78, "Чтоб мне провалиться!" }, { 2.41, "Ты нашёл ключ!" }, { 3.47, "Я знал, что проклятые дворфы Чёрного Железа спрятали его, после того как заперли меня в этой дыре!" }, { 11.25, "О, благодарю тебя!" }, { 12.73, "Скорее открой дверь и выпусти старика Локида на свободу!" } }, f = { { 0.00, "Вот те на!" }, { 0.75, "Чтоб мне провалиться!" }, { 2.31, "Ты нашла ключ!" }, { 3.39, "Я знал, что проклятые дворфы Чёрного Железа спрятали его, после того как заперли меня в этой дыре!" }, { 10.85, "О, благодарю тебя!" }, { 12.28, "Скорее открой дверь и выпусти старика Локида на свободу!" } } } } },
