    [4467] = { t = { d = 13.7, v = "narrator", n = { x = 149 }, c = { x = { { 0.00, "Вы обрабатываете ветроцвет двумя порциями кенарийского бальзама исцеления растений." }, { 6.70, "Растение тут же начинает исцеляться от порчи, расцветает, наполняется силой и исцеляется." } } } } },
    [4481] = { t = { d = 8.2, v = "bloodelf-male", n = { x = 86 }, c = { x = { { 0.00, "Это позор для его памяти..." }, { 2.24, "Смертный оканчивает работу всей его жизни." }, { 5.59, "Забирай свою безделушку и убирайся!" } } } } },
    [4482] = { t = { d = 24.3, g = 1, v = "bloodelf-male", n = { x = 276 }, c = { m = { { 0.00, "На этот манускрипт, что ты держишь в руках, Кариэль потратил столько времени, сколько хватило бы на несколько твоих жизней, путник." }, { 9.15, "И ради чего?" }, { 10.09, "Чтобы его ученик торчал в Пылающих степях, извращая его труды ради утоления бесконечной жажды магии..." }, { 17.42, "Будь проклята эта мерзкая зависимость." }, { 20.11, "Мне противны твоя чёрствость и ненасытная жадность." }, { 23.62, "Прочь!" } }, f = { { 0.00, "На этот манускрипт, что ты держишь в руках, Кариэль потратил столько времени, сколько хватило бы на несколько твоих жизней, путница." }, { 9.48, "И ради чего?" }, { 10.42, "Чтобы его ученик торчал в Пылающих степях, извращая его труды ради утоления бесконечной жажды магии..." }, { 17.75, "Будь проклята эта мерзкая зависимость." }, { 20.44, "Мне противны твоя чёрствость и ненасытная жадность." }, { 23.95, "Прочь!" } } } } },
    [4483] = { t = { d = 14.2, v = "bloodelf-male", n = { x = 143 }, c = { x = { { 0.00, "Прочие манускрипты рассеяны по свету." }, { 3.01, "По таким уголкам, куда ты не осмелишься войти." }, { 6.73, "Которых бы лучше и не было." }, { 8.95, "Я выпью из этих составляющих силу." }, { 11.74, "А ты получишь то, что останется..." } } } } },
    [4484] = { t = { d = 11.0, v = "bloodelf-male", n = { x = 91 }, c = { x = { { 0.00, "Голова болит..." }, { 1.77, "Сила бескрайних пределов вселенной..." }, { 5.89, "Ахххх!" }, { 6.48, "*Матредис кривится от боли.*" }, { 8.88, "Бери, что тебе нужно, и уходи!" } } } } },
    [4485] = { d = 31.0, g = 1, v = "dwarf-female#33", n = { m = 340, f = 342 }, c = { m = { { 0.00, "Приветствую." }, { 0.93, "Я вижу, твоя решимость по-прежнему сильна, как и твоя вера." }, { 5.36, "Думаю, настало время тебе поговорить с Даторианом Раллом в Штормграде." }, { 10.59, "Ты должен получить ещё несколько уроков, и я чувствую, ты к ним готов." }, { 15.69, "Найди Даториана в Соборе Света – и пожалуйста, отнесись к его урокам серьёзно." }, { 21.45, "Ты добился своего положения благодаря скромности и упорному труду, так не разочаруй нас – не становись высокомерным." }, { 29.86, "Удачи тебе." } }, f = { { 0.00, "Приветствую." }, { 0.93, "Я вижу, твоя решимость по-прежнему сильна, как и твоя вера." }, { 5.40, "Думаю, настало время тебе поговорить с Даторианом Раллом в Штормграде." }, { 10.66, "Ты должна получить ещё несколько уроков, и я чувствую, ты к ним готова." }, { 15.85, "Найди Даториана в Соборе Света – и пожалуйста, отнесись к его урокам серьёзно." }, { 21.65, "Ты добилась своего положения благодаря скромности и упорному труду, так не разочаруй нас – не становись высокомерной." }, { 30.17, "Удачи тебе." } } }, t = { d = 18.2, g = 1, v = "human-male", n = { m = 197, f = 198 }, c = { m = { { 0.00, "А, вижу, ты вернулся в храм." }, { 2.02, "Это хорошо." }, { 2.94, "Многое случилось за последнее время, и я попрошу тебя о помощи, если ты докажешь, что способен справиться с моими поручениями." }, { 12.08, "Кругом множество предателей." }, { 14.17, "Мне нужна будет твоя помощь, чтобы остановить их." } }, f = { { 0.00, "А, вижу, ты вернулась в храм." }, { 2.15, "Это хорошо." }, { 3.09, "Многое случилось за последнее время, и я попрошу тебя о помощи, если ты докажешь, что способна справиться с моими поручениями." }, { 12.48, "Кругом множество предателей." }, { 14.63, "Мне нужна будет твоя помощь, чтобы остановить их." } } } } },
    [4486] = { d = 35.7, g = 1, v = "dwarf-male", n = { m = 379, f = 381 }, c = { m = { { 0.00, "Ну-ка, ну-ка, поглядите на могучего паладина во всей красе!" }, { 4.38, "Прошу прощения, я не в обиду..." }, { 6.70, "Просто иногда немного завидую твоим достижениям." }, { 10.35, "Тиза говорит, что в этом – моя слабость, и я обещал ей, что искореню этот недостаток." }, { 16.65, "Но пока не преуспел, сам понимаешь." }, { 19.23, "Но вот почему я хотел с тобой поговорить: Даториан Ралл из Штормграда сообщил, что хочет встретиться с тобой в Соборе Света, когда ты будешь к этому готов." }, { 30.64, "Звучало веско." }, { 31.77, "Звучало так, как будто что-то эдакое происходит." } }, f = { { 0.00, "Ну-ка, ну-ка, поглядите на могучего паладина во всей красе!" }, { 4.41, "Прошу прощения, я не в обиду..." }, { 6.75, "Просто иногда немного завидую твоим достижениям." }, { 10.43, "Тиза говорит, что в этом – моя слабость, и я обещал ей, что искореню этот недостаток." }, { 16.78, "Но пока не преуспел, сама понимаешь." }, { 19.52, "Но вот почему я хотел с тобой поговорить: Даториан Ралл из Штормграда сообщил, что хочет встретиться с тобой в Соборе Света, когда ты будешь к этому готова." }, { 31.08, "Звучало веско." }, { 32.22, "Звучало так, как будто что-то эдакое происходит." } } }, t = { d = 18.1, g = 1, v = "human-male", n = { m = 197, f = 198 }, c = { m = { { 0.00, "А, вижу, ты вернулся в храм." }, { 1.99, "Это хорошо." }, { 2.89, "Многое случилось за последнее время, и я попрошу тебя о помощи, если ты докажешь, что способен справиться с моими поручениями." }, { 11.86, "Кругом множество предателей." }, { 13.91, "Мне нужна будет твоя помощь, чтобы остановить их." } }, f = { { 0.00, "А, вижу, ты вернулась в храм." }, { 2.12, "Это хорошо." }, { 3.05, "Многое случилось за последнее время, и я попрошу тебя о помощи, если ты докажешь, что способна справиться с моими поручениями." }, { 12.32, "Кругом множество предателей." }, { 14.44, "Мне нужна будет твоя помощь, чтобы остановить их." }