    [4487] = { d = 30.8, g = 1, v = "gnome-male", n = { m = 342, f = 346 }, c = { m = { { 0.00, "Ага, хорошо, что ты здесь." }, { 1.86, "Я посылал суккуба за тобой, но, похоже, ты успел добраться сюда раньше, чем он тебя нашёл." }, { 8.28, "Ладно." }, { 8.80, "Тут недавно пошли разговоры о твоём растущем могуществе – и это очень хорошо для тебя, а для других, наверное, не очень." }, { 17.33, "Короче, я думаю, что ты уже достаточно зарекомендовал себя и потому заслуживаешь... хе-хе... подарочка." }, { 24.65, "В Степях над Кабестаном ты найдёшь человека по имени Страхад." }, { 28.95, "Уверен, вы уже встречались." } }, f = { { 0.00, "Ага, хорошо, что ты здесь." }, { 1.81, "Я посылал инфернала за тобой, но, похоже, ты успела добраться сюда раньше, чем он тебя нашёл." }, { 8.23, "Ладно." }, { 8.73, "Тут недавно пошли разговоры о твоём растущем могуществе – и это очень хорошо для тебя, а для других, наверное, не очень." }, { 17.02, "Короче, я думаю, что ты уже достаточно зарекомендовала себя и потому заслуживаешь... хе-хе... подарочка." }, { 24.19, "В Степях над Кабестаном ты найдёшь человека по имени Страхад." }, { 28.37, "Уверен, вы уже встречались." } } }, t = { d = 16.1, g = 1, v = "human-male#50", n = { m = 173, f = 174 }, c = { m = { { 0.00, "Значит, ты снова решил почтить меня своим визитом." }, { 3.87, "Очень мило с твоей стороны." }, { 6.00, "Мои помощники все гадали – придёшь или нет?" }, { 9.21, "Я говорил им – несомненно, придёт." }, { 11.68, "Когда речь заходит о могуществе, летишь как мотылёк на свечу." } }, f = { { 0.00, "Значит, ты снова решила почтить меня своим визитом." }, { 3.94, "Очень мило с твоей стороны." }, { 6.08, "Мои помощники все гадали – придёшь или нет?" }, { 9.28, "Я говорил им – несомненно, придёт." }, { 11.75, "Когда речь заходит о могуществе, летишь как мотылёк на свечу." } } } } },
    [4488] = { d = 31.2, g = 1, v = "human-female#45", n = { m = 348, f = 349 }, c = { m = { { 0.00, "О, ты почтил нас своим присутствием." }, { 2.61, "Какая честь!" }, { 3.53, "Надеюсь, ты не думаешь, что мы будем тебя облизывать с ног до головы." }, { 8.49, "Может, ты и быстро набираешь могущество, но ты всё ещё дитя малое в том, что касается истинного знания и мудрости." }, { 16.65, "Если не поостережёшься, тебя охватит одержимость, и воля твоя ослабеет." }, { 21.81, "Но ближе к делу – Страхад желает говорить с тобой." }, { 25.53, "Он по-прежнему живёт в башне над Кабестаном в Степях." }, { 29.32, "Советую не тянуть канитель." } }, f = { { 0.00, "О, ты почтила нас своим присутствием." }, { 2.67, "Какая честь!" }, { 3.58, "Надеюсь, ты не думаешь, что мы будем тебя облизывать с ног до головы." }, { 8.51, "Может, ты и быстро набираешь могущество, но ты всё ещё дитя малое в том, что касается истинного знания и мудрости." }, { 16.64, "Если не поостережёшься, тебя охватит одержимость, и воля твоя ослабеет." }, { 21.77, "Но ближе к делу – Страхад желает говорить с тобой." }, { 25.48, "Он по-прежнему живёт в башне над Кабестаном в Степях." }, { 29.25, "Советую не тянуть канитель." } } }, t = { d = 15.8, g = 1, v = "human-male#50", n = { m = 173, f = 174 }, c = { m = { { 0.00, "Значит, ты снова решил почтить меня своим визитом." }, { 3.81, "Очень мило с твоей стороны." }, { 5.92, "Мои помощники все гадали – придёшь или нет?" }, { 9.07, "Я говорил им – несомненно, придёт." }, { 11.50, "Когда речь заходит о могуществе, летишь как мотылёк на свечу." } }, f = { { 0.00, "Значит, ты снова решила почтить меня своим визитом." }, { 3.86, "Очень мило с твоей стороны." }, { 5.96, "Мои помощники все гадали – придёшь или нет?" }, { 9.10, "Я говорил им – несомненно, придёт." }, { 11.52, "Когда речь заходит о могуществе, летишь как мотылёк на свечу." } } } } },
    [4489] = { d = 26.5, g = 1, v = "orc-male", n = { m = 225, f = 224 }, c = { m = { { 0.00, "А, герой!" }, { 0.85, "Иди сюда!" }, { 1.77, "Ты ведь тот самый, о ком все говорят, не так ли?" }, { 5.69, "Я так и думал." }, { 6.92, "Короче: твоя мощь растёт, и это было замечено." }, { 10.92, "Теперь пора наградить тебя за старания." }, { 14.38, "Иди в Степи." }, { 15.54, "Там, над Кабестаном, ищи Страхада Фарсана – может, помнишь его?" }, { 21.00, "У него есть для тебя кое-что." }, { 23.54, "Это много времени не займёт." } }, f = { { 0.00, "А, героиня!" }, { 1.02, "Иди сюда!" }, { 1.96, "Ты ведь та самая, о ком все говорят, не так ли?" }, { 5.89, "Я так и думал." }, { 7.15, "Короче: твоя мощь растёт, и это было замечено." }, { 11.24, "Теперь пора наградить тебя за старания." }, { 14.77, "Иди в Степи." }, { 15.95, "Там, над Кабестаном, ищи Страхада Фарсана – может, помнишь его?" }, { 21.53, "У него есть для тебя кое-что." }, { 24.12, "Это много времени не займёт." } } }, t = { d = 16.2, g = 1, v = "human-male#50", n = { m = 173, f = 174 }, c = { m = { { 0.00, "Значит, ты снова решил почтить меня своим визитом." }, { 3.81, "Очень мило с твоей стороны." }, { 5.92, "Мои помощники все гадали – придёшь или нет?" }, { 9.07, "Я говорил им – несомненно, придёт." }, { 11.50, "Когда речь заходит о могуществе, летишь как мотылёк на свечу." } }, f = { { 0.00, "Значит, ты снова решила почтить меня своим визитом." }, { 3.96, "Очень мило с твоей стороны." }, { 6.11, "Мои помощники все гадали – придёшь или нет?" }, { 9.33, "Я говорил им – несомненно, придёт." }, { 11.81, "Когда речь заходит о могуществе, летишь как мотылёк на свечу." } } } } },
    [4490] = { d = 18.7, v = "human-male#50", n = { x = 200 }, c = { x = { { 0.00, "Я бы наградил тебя за терпение да усердие." }, { 3.25, "Но, знаешь ли, в будущем призывание коня Скверны будет куда труднее." }, { 8.57, "Придётся заслужить награду... и это будет непросто." }, { 12.51, "Пока же получи способность призывать эту тварь и пользуйся ей по своему усмотрению." } } }, t = { d = 3.5, v = "human-male#50", n = { x = 37 }, c = { x = { { 0.00, "Удачи." }, { 0.58, "Надеюсь встретиться с тобой в будущем." } } } } },
    [4491] = { d = 25.4, v = "goblin-male", n = { x = 278 }, c = { x = { { 0.00, "Уф..." }, { 0.39, "Как здесь жарко!" }, { 1.57, "Я тут прогуливался по окрестностям, как вдруг накатила эта жуткая жара." }, { 6.65, "Похоже, у меня тепловой удар." }, { 8.87, "Помоги мне добраться до моей подруги Спрэггл в Укрытие Маршалла." }, { 13.50, "Думаю, я сумею дойти, если кто-то будет вести меня." }, { 17.42, "Если я вдруг потеряю сознание, просто плесни мне в лицо воды из фляги Спрэггл." }, { 23.09, "Думаю, этого будет достаточно..." } } }, t = { d = 8.0, g = 1, v = "goblin-female#63", n = { m = 78, f = 79 }, c = { m = { { 0.00, "Да, Ринго совсем плох, но я рада, что он вернулся в целости и сохранности..." }, { 5.99, "Спасибо, что разыскал его!" } }, f = { { 0.00, "Да, Ринго совсем плох, но я рада, что он вернулся в целости и сохранности..." }, { 5.76, "Спасибо, что разыскала его!" } } } } },
    [4492] = { d = 15.2, v = "goblin-female#63", n = { x = 159 }, c = { x = { { 0.00, "Помоги мне!" }, { 0.88, "Мой друг Ринго отправился сегодня исследовать вулкан к югу отсюда, и его что-то долго нет!" }, { 7.74, "Я очень беспокоюсь." }, { 9.24, "Ты сможешь найти его?" }, { 10.93, "Вот, возьми с собой эту флягу, думаю она ему пригодится!" } } }, t = { d = 3.2, g = 1, v = "goblin-male", n = { m = 22, f = 22 }, c = { m = { { 0.00, "О, я так рад, что ты нашёл меня!" } }, f = { { 0.00, "О, я так рад, что ты нашла меня!" } } } } },
    [4493] = { d = 34.3, v = "nightelf-female#52", n = { x = 421 }, c = { x = { { 0.00, "Такое впечатление, что смысл самого существования силитидов состоит в том, чтобы сожрать всё, что отлично от них." }, { 7.46, "Они ведут себя очень целеустремлённо и именно поэтому представляют серьёзную опасность для всего Азерота." }, { 14.50, "Всё, что мы видели до сих пор, – это только цветочки!" }, { 18.02, "Подозреваю, что их основные силы сосредоточены в глубине Калимдора, в Кратере Ун'Горо." }, { 23.79, "Ступай в Прибамбасск в пустыне Танарис и поговори с алхимиком Пестычинсом." }, { 29.22, "Расскажи ему о моей гипотезе." }, { 31.29, "Он наверняка поможет нам бороться с силитидами." } } }, t = { d = 28.2, v = "goblin-male#108", n = { x = 309 }, c = { x = { { 0.00, "Как понимаю, тебя прислала Грацина?" }, { 2.63, "Твой опыт в истреблении этих тварей воистину бесценен – пока я ещё не видел никого, кто осмелился бы потягаться с ними." }, { 11.33, "Что же до идеи Грацины насчёт того, что их гнездо – Кратер Ун'Горо... может быть, оно и так." }, { 17.98, "Ун'Горо – это таинственные и опасные джунгли к западу отсюда." }, { 22.52, "Может быть, мы действительно подошли на шаг ближе к разрешению загадки силитидов." } } } } },
    [4494] = { d = 39.7, v = "troll-male#77", n = { x = 439 }, c = { x = { { 0.00, "Такое впечатление, что намерения, более того, смысл самого существования силитидов состоит в том, чтобы сожрать всё, что отлично от них." }, { 10.13, "Они ведут себя очень целеустремлённо и именно поэтому представляют серьёзную опасность для всего Азерота." }, { 18.01, "Всё, что мы видели до сих пор, – это только цветочки!" }, { 21.95, "Подозреваю, что их основные силы сосредоточены в глубине Калимдора, в Кратере Ун'Горо." }, { 28.41, "Ступай в Прибамбасск в пустыне Танарис и поговори с алхимиком Пестычинсом." }, { 33.98, "Расскажи ему о моей гипотезе." }, { 36.29, "Он наверняка поможет нам бороться с силитидами." } } }, t = { d = 25.0, v = "goblin-male#108", n = { x = 286 }, c = { x = { { 0.00, "Да, я так понимаю, тебя Зилзибин прислал?" }, { 2.92, "Твой опыт воистину бесценен: до тебя я не встречал никого, кому доводилось сражаться с этими тварями." }, { 10.10, "Что касается идеи Зиба насчёт Кратера Ун'Горо..." }, { 13.54, "Может быть, он и прав." }, { 15.06, "Ун'Горо – это таинственные и опасные джунгли к западу отсюда." }, { 19.45, "Может быть, мы действительно подошли на шаг ближе к разрешению загадки силитидов." } } } } },
    [4495] = { d = 26.6, v = "nightelf-female#52", n = { x = 316 }, c = { x = { { 0.00, "Мой друг по имени Иверрон обычно навещает меня в одно и то же время каждый день." }, { 5.48, "Странно, что сегодня он вообще не пришёл – он задерживается уже на несколько часов." }, { 11.07, "Признаться, я несколько волнуюсь." }, { 13.35, "Иверрон проводит много времени возле пещеры к северу отсюда, и я знаю, насколько там опасно – это ведь логово пауков!" }, { 21.47, "Послушай, если ты вдруг направляешься в ту сторону, то не поищешь ли Иверрона?" } } }, t = { d = 4.2, g = 1, v = "nightelf-male#59", n = { m = 44, f = 45 }, c = { m = { { 0.00, "Я рад, что тебе удалось найти меня." }, { 2.66, "Как ты узнал, что я тут?" } }, f = { { 0.00, "Я рад, что тебе удалось найти меня." }, { 2.57, "Как ты узнала, что я тут?" } } } } },
    [4496] = { d = 29.9, v = "goblin-male#108", n = { x = 348 }, c = { x = { { 0.00, "Исследования показали, что силитиды подобны пчёлам – стоит убить королеву улья, и остальные без неё пропадут." }, { 7.61, "Я создам приманку, которая позволит тебе выманить королеву." }, { 11.86, "Выманив её, сразись с ней." }, { 13.95, "Впрочем, для начала нам понадобятся некоторые составляющие." }, { 18.33, "Отправляйся на запад, в ульи силитидов в Кратере Ун'Горо и принеси ароматическую железу одного из мерзких жуков." }, { 26.26, "Кроме того мне понадобятся образцы почвы из кратера." } } }, t = { d = 23.8, v = "goblin-male#108", n = { x = 257 }, c = { x = { { 0.00, "А, вот и ароматическая железа." }, { 2.23, "Похоже, мембрана цела – великолепно." }, { 5.00, "И почва тоже подойдёт." }, { 6.69, "Я кое-чего добавлю, и сделаю из этого прекрасную приманку." }, { 11.14, "Подожди минутку, и всё будет готово." }, { 13.91, "После этого можно будет сделать следующий шаг и остановить силитидов, пока они не захватили Прибамбасск... и весь остальной Калимдор." } } } } },
    [4501] = { d = 27.4, v = "narrator", n = { x = 303 }, c = { x = { { 0.00, "Требуется: опытный боец для устранения угрозы со стороны жутедактилей, населяющих Кратер Ун'Горо." }, { 7.60, "Популяция этих тварей растёт, они уже представляют серьёзную угрозу забредшим в кратер путникам." }, { 15.13, "Необходимо уменьшить популяцию, убив десять жутедактилей и пятнадцать бесноватых жутедактилей." }, { 22.45, "Выполнивших задание просьба обращаться за наградой к Муче Кусора." } } }, t = { d = 8.8, v = "goblin-female#63", n = { x = 91 }, c = { x = { { 0.00, "Я просто в шоке от жутедактилей!" }, { 2.58, "Спасибо тебе!" }, { 3.72, "Теперь я хотя бы смогу спокойно высунуть нос из Укрытия Маршалла!" } } } } },
    [4502] = { d = 27.2, v = "goblin-female", n = { x = 340 }, c = { x = { { 0.00, "Я многому научилась у Марвона Клепальщика." }, { 2.82, "Но он уже так давно уехал, что я уж подумываю начать собственные эксперименты." }, { 7.97, "Я недавно читала о Кратере Ун'Горо и странной вулканической деятельности в его центре." }, { 13.73, "Мне думается, что многое можно было бы узнать, если бы мне удалось заполучить для исследований немного пепла из тамошних элементалей." }, { 22.54, "Вы не против добыть немного пепла для меня, раз уж всё равно туда идёте?" } } }, t = { d = 9.3, v = "goblin-female", n = { x = 105 }, c = { x = { { 0.00, "Эти образцы как нельзя лучше сгодятся для моих исследований!" }, { 4.42, "Спасибо!" }, { 5.07, "Обещаю – тебе я расскажу о моих открытиях в первую очередь!" } } } } },
    [4503] = { d = 34.3, g = 1, v = "goblin-male", n = { m = 385, f = 386 }, c = { m = { { 0.00, "Я работаю над вертолётом!" }, { 1.76, "И вот, застрял здесь и не могу выбраться!" }, { 4.68, "С удовольствием тормознул бы грифона или ветрокрыла, чтобы подбросили меня до Прибамбасска, да только ужасно боюсь этих тварей!" }, { 13.92, "Ты мне не поможешь?" }, { 15.29, "Мне осталось сделать только крылья, и я думаю, что чешуя жутедактиля или деметродона была бы идеальным материалом." }, { 23.55, "Однако маленькому гоблину не под силу справиться со столь грозными хищниками!" }, { 29.08, "А ты на вид весьма крут!" }, { 30.77, "Может, попытаешься добыть мне чешуек?" } }, f = { { 0.00, "Я работаю над вертолётом!" }, { 1.80, "И вот, застрял здесь и не могу выбраться!" }, { 4.80, "С удовольствием тормознул бы грифона или ветрокрыла, чтобы подбросили меня до Прибамбасска, да только ужасно боюсь этих тварей!" }, { 14.27, "Ты мне не поможешь?" }, { 15.67, "Мне осталось сделать только крылья, и я думаю, что чешуя жутедактиля или деметродона была бы идеальным материалом." }, { 24.13, "Однако маленькому гоблину не под силу справиться со столь грозными хищниками!" }, { 29.80, "А ты на вид весьма крута!" }, { 31.67, "Может, попытаешься добыть мне чешуек?" } } }, t = { d = 10.5, v = "goblin-male", n = { x = 108 }, c = { x = { { 0.00, "Да, эта чешуя подходит просто превосходно!" }, { 3.45, "С помощью этих чешуек мне уж точно удастся поднять моё творение в воздух!" }, { 9.34, "Благодарю тебя!" } } } } },
    [4504] = { d = 31.7, v = "goblin-male", n = { x = 348 }, c = { x = { { 0.00, "Я всегда искал способ быстро заработать." }, { 3.08, "Если ты поможешь воплотить мою последнюю идею, я поделюсь с тобой доходами." }, { 8.76, "Что ты на это скажешь?" }, { 10.43, "Так я и думал!" }, { 11.50, "Ступай к смоляным ямам в северной части Кратера Ун'Горо и принеси мне смолы." }, { 17.25, "Но не просто смолы, а смолы из зверей, живущих вокруг этих ям." }, { 21.93, "Обычная смола недостаточно липкая." }, { 24.54, "В растениеподобных существах присутствует хлорофилл, и смола, смешанная с ним, делается сверхлипкой." } } }, t = { d = 16.6, v = "goblin-male", n = { x = 151 }, c = { x = { { 0.00, "Да, да, та самая смола…" }, { 2.00, "Эй, минуточку, руки мои, руки..." }, { 4.85, "Я не могу их разлепить…" }, { 6.86, "Может быть, это не такая уж хорошая идея." }, { 10.48, "Впрочем, стоп!" }, { 11.71, "Растворитель суперлипкой смолы!" }, { 14.41, "Вот что разойдётся за полдня!" } } } } },
    [4505] = { d = 41.4, v = "scourge-female#79", n = { x = 409 }, c = { x = { { 0.00, "Говорят, будто я слишком жестока..." }, { 2.98, "Но ведь это только потому, что я жажду добыть для Орды преимущество перед Альянсом любым способом." }, { 11.18, "Сейчас меня прежде всего интересует лунный колодец в руинах Констелласа, к югу отсюда, который охраняют сатиры из племени Нефритового Пламени." }, { 23.11, "Этот лунный колодец, некогда символ возрождения этих несносных ночных эльфов, ныне осквернён, и порождает всё больше сатиров." }, { 33.54, "У меня есть одна мысль, и мне хотелось бы получить пробу воды оттуда... для моей любимой кошечки." } } }, t = { d = 7.6, v = "scourge-female#79", n = { x = 66 }, c = { x = { { 0.00, "Очень хорошо." }, { 1.34, "Нам надо найти способ использовать эту порчу против наших врагов..." } } } } },
    [4506] = { d = 33.9, v = "scourge-female#79", n = { x = 322 }, c = { x = { { 0.00, "Эта осквернённая вода может помочь нам." }, { 3.35, "От одной её капли мои котятки выросли вдвое и даже стали сильнее... кое в чём." }, { 10.14, "Эти кошечки могут оказаться полезными..." }, { 13.65, "Вот." }, { 14.03, "Возьми эту кошачью переноску и выпусти котёночка, что сидит внутри возле лунного колодца, что в руинах Констелласа." }, { 23.78, "Хе-хе... результаты тебе наверняка понравятся!" }, { 27.75, "Потом принеси кошечку ко мне обратно, а я уж возмещу тебе затраты времени." } } }, t = { d = 14.0, v = "scourge-female#79", n = { x = 122 }, c = { x = { { 0.00, "Отлично!" }, { 0.87, "Отрёкшиеся не побрезгуют никакими средствами, чтобы сокрушить Альянс!" }, { 7.52, "И эта осквернённая вода весьма поможет нам в наших будущих трудах..." } } } } },
    [4507] = { d = 25.3, v = "goblin-male#108", n = { x = 281 }, c = { x = { { 0.00, "Вот и приманка." }, { 1.11, "Внутри улья должен быть какой-то кристалл." }, { 4.25, "Мы думаем, что силитиды пользуются им для вещания по всему улью." }, { 8.89, "Где он?" }, { 9.41, "Я бы поискал в инкубаторах." }, { 11.37, "Если положить приманку на этот кристалл, непременно явится королева." }, { 16.41, "Но предупреждаю, без охраны она не ходит." }, { 19.41, "Убей её и вынь из неё мозг." }, { 21.31, "Как ни гадко это звучит, его необходимо изучить." }, { 24.90, "Удачи!" } } }, t = { d = 19.4, v = "goblin-male#108", n = { x = 220 }, c = { x = { { 0.00, "Поразительно!" }, { 1.00, "Сегодня мы одержали победу." }, { 3.05, "Впрочем, нам понадобится время, чтобы разобраться с полученными материалами." }, { 8.63, "Не волнуйся, всё пойдёт в дело." }, { 10.89, "Что до силитидов, я искренне сомневаюсь, что мы сумели остановить их нашествие." }, { 16.60, "К сожалению, это было бы слишком легко." } } } } },
    [4508] = { d = 26.1, v = "goblin-male#108", n = { x = 324 }, c = { x = { { 0.00, "Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что-либо предпринять." }, { 8.30, "Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты." }, { 13.11, "Отнеси мой последний отчёт Грацине Силе Духа, в Дарнасс; она ведь по-прежнему в Храме Луны?" }, { 19.16, "У неё много друзей среди важных шишек Альянса; если удастся привлечь их внимание, быть может мы и выживем." } } }, t = { d = 26.8, g = 1, v = "nightelf-female#52", n = { m = 309, f = 310 }, c = { m = { { 0.00, "Хотя я очень благодарна тебе, не знаю, выйдет ли из этого толк." }, { 4.45, "Альянс видит лишь опасность, исходящую от Орды, а ведь даже наши вожди здесь, в Дарнассе, не понимают, в чём именно она состоит." }, { 13.35, "Глупцы вроде Фэндрала Оленьего Шлема уверяют, что силитиды не могут грозить нам как тогда, в далёком прошлом." }, { 20.93, "Он невежда – и невежа!" }, { 22.49, "Ты видел опасность своими глазами." }, { 24.94, "Мы должны одолеть силитидов!" } }, f = { { 0.00, "Хотя я очень благодарна тебе, не знаю, выйдет ли из этого толк." }, { 4.44, "Альянс видит лишь опасность, исходящую от Орды, а ведь даже наши вожди здесь, в Дарнассе, не понимают, в чём именно она состоит." }, { 13.31, "Глупцы вроде Фэндрала Оленьего Шлема уверяют, что силитиды не могут грозить нам как тогда, в далёком прошлом." }, { 20.88, "Он невежда – и невежа!" }, { 22.44, "Ты видела опасность своими глазами." }, { 24.94, "Мы должны одолеть силитидов!" } } } } },
    [4509] = { d = 26.6, v = "goblin-male#108", n = { x = 324 }, c = { x = { { 0.00, "Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что-либо предпринять." }, { 8.53, "Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты." }, { 13.47, "Отнеси мой последний отчёт Зилзибину Барабанному Бою, в Оргриммар; он ведь по-прежнему там?" }, { 19.51, "У него много друзей среди важных шишек Орды; если удастся привлечь их внимание, быть может мы и выживем." } } }, t = { d = 27.9, g = 1, v = "troll-male#77", n = { m = 303, f = 304 }, c = { m = { { 0.00, "Хотя я очень благодарен тебе, не знаю, выйдет ли из этого толк." }, { 4.84, "Орда видит лишь опасность, исходящую от Альянса." }, { 8.52, "Если бы удалось доложить о случившемся лично Траллу, он непременно принял бы меры, но его окружают дурные советчики." }, { 17.37, "Они готовы гоняться за собственным хвостом, надеясь застать Альянс врасплох!" }, { 23.23, "Ты видел опасность своими глазами." }, { 25.89, "Мы должны одолеть силитидов!" } }, f = { { 0.00, "Хотя я очень благодарен тебе, не знаю, выйдет ли из этого толк." }, { 4.60, "Орда видит лишь опасность, исходящую от Альянса." }, { 8.11, "Если бы удалось доложить о случившемся лично Траллу, он непременно принял бы меры, но его окружают дурные советчики." }, { 16.54, "Они готовы гоняться за собственным хвостом, надеясь застать Альянс врасплох!" }, { 22.12, "Ты видела опасность своими глазами." }, { 24.71, "Мы должны одолеть силитидов!" } } } } },
    [4510] = { d = 30.5, g = 1, v = "nightelf-female#52", n = { m = 356, f = 356 }, c = { m = { { 0.00, "Твоя помощь просто неоценима." }, { 2.07, "Придёт время, и, думается, я снова буду вынуждена обратиться к тебе за содействием в борьбе против силитидов." }, { 9.42, "Мы должны осмыслить всё, что узнали в Ун'Горо." }, { 12.52, "Опасаюсь, что мои предположения по поводу того, что силитиды родом из Ун'Горо, неверны... и где-то их гораздо больше." }, { 20.43, "Отнеси эту бумагу Идриане в банк." }, { 22.74, "Она выдаст тебе кое-что из моего хранилища в знак моей признательности." }, { 27.60, "Благодарю тебя за помощь, отважный герой." } }, f = { { 0.00, "Твоя помощь просто неоценима." }, { 2.07, "Придёт время, и, думается, я снова буду вынуждена обратиться к тебе за содействием в борьбе против силитидов." }, { 9.44, "Мы должны осмыслить всё, что узнали в Ун'Горо." }, { 12.54, "Опасаюсь, что мои предположения по поводу того, что силитиды родом из Ун'Горо, неверны... и где-то их гораздо больше." }, { 20.45, "Отнеси эту бумагу Идриане в банк." }, { 22.77, "Она выдаст тебе кое-что из моего хранилища в знак моей признательности." }, { 27.64, "Благодарю тебя за помощь, отважная героиня." } } }, t = { d = 9.5, v = "nightelf-female#51", n = { x = 107 }, c = { x = { { 0.00, "Эта расписка даёт мне право выдавать вам предметы из хранилища Грацины Силы Духа в нашем банке." }, { 7.08, "Похоже, она весьма вам благодарна!" } } } } },
    [4511] = { d = 36.0, g = 1, v = "troll-male#77", n = { m = 364, f = 364 }, c = { m = { { 0.00, "Спасибо тебе." }, { 1.11, "Без тебя у нас бы ничего не вышло." }, { 3.73, "Несомненно, вскоре придёт время, когда я снова попрошу твоей помощи в борьбе с силитидами." }, { 10.71, "Придётся пересмотреть то, что известно нам по Ун'Горо." }, { 14.72, "Боюсь, моё предположение, что силитиды происходят из Ун'Горо, оказалось ложным." }, { 20.73, "Где-то есть другое гнездо, куда более крупное." }, { 24.40, "Отнеси эту записку Карусу в банк." }, { 27.02, "Он выдаст тебе кое-что, что может считаться знаком моей благодарности." }, { 32.48, "Спасибо за помощь, могучий герой!" } }, f = { { 0.00, "Спасибо тебе." }, { 1.13, "Без тебя у нас бы ничего не вышло." }, { 3.82, "Несомненно, вскоре придёт время, когда я снова попрошу твоей помощи в борьбе с силитидами." }, { 10.96, "Придётся пересмотреть то, что известно нам по Ун'Горо." }, { 15.06, "Боюсь, моё предположение, что силитиды происходят из Ун'Горо, оказалось ложным." }, { 21.22, "Где-то есть другое гнездо, куда более крупное." }, { 24.97, "Отнеси эту записку Карусу в банк." }, { 27.65, "Он выдаст тебе кое-что, что может считаться знаком моей благодарности." }, { 33.24, "Спасибо за помощь, могучая героиня!" } } }, t = { d = 10.4, v = "orc-male#127", n = { x = 110 }, c = { x = { { 0.00, "Согласно этой расписке, мне следует выдать вам некий предмет из хранилища Зилзибина Барабанного Боя." }, { 8.03, "Кажется, вас можно поздравить!" } } } } },
    [4512] = { d = 34.6, v = "gnome-male", n = { x = 398 }, c = { x = { { 0.00, "Но больше всего я изучал слизнюков." }, { 2.57, "Я понимаю, что звучит нелепо, но они же повсюду!" }, { 6.03, "Не так давно я помогал одной даме из Менетила искать её сумку – так слизнюки эту сумку сожрали." }, { 12.90, "Я видел, что члены Королевского фармацевтического общества Подгорода собирают образцы этих тварей." }, { 19.90, "Я хочу понять, почему!" }, { 21.56, "Откуда они их берут?" }, { 23.10, "Я слышал, что они водятся в Осквернённом лесу." }, { 26.38, "Мне нужны экземпляры этих слизнюков для продолжения исследований." }, { 31.00, "Я дам вам банки, а вы возьмёте образцы мёртвых существ." } } }, t = { d = 27.1, v = "gnome-male", n = { x = 320 }, c = { x = { { 0.00, "Блестящий результат!" }, { 1.47, "Вы умудрились подойти достаточно близко, взять образцы этих гнилостных тварей и ничуть не пострадать!" }, { 8.62, "Благодарю вас." }, { 9.64, "О, это как раз то, что надо." }, { 11.62, "Немедленно примусь за эксперименты." }, { 14.11, "Если я прав, я стану одним из величайших учёных Лиги Исследователей!" }, { 18.90, "Это покажет всем дворфам, что они правильно поступили, пустив нас, гномов, в Стальгорн после гномреганской катастрофы." } } } } },
    [4513] = { d = 34.9, v = "gnome-male", n = { x = 349 }, c = { x = { { 0.00, "Мне, похоже, понадобятся ещё образцы." }, { 2.90, "Но – как бы это сказать – они должны быть чистыми." }, { 6.85, "Да знаю, знаю." }, { 8.05, "\"Что значит \"чистые\", Ларис?\" Я не уверен." }, { 11.37, "Я знаю только, что вот эти – осквернены... прямо как Осквернённый лес." }, { 16.74, "Потому так важно понять." }, { 18.72, "Эти слизнюки словно бы приспосабливаются к условиям места, в котором находятся." }, { 24.93, "Мне нужны образцы, которые не заражены." }, { 28.04, "Но где их взять?" }, { 29.24, "Где?!" }, { 29.66, "Возьмите эти банки на случай, если вам попадутся чистые экземпляры." } } }, t = { d = 23.4, g = 1, v = "gnome-male", n = { x = 243 }, c = { m = { { 0.00, "Так вы их нашли?" }, { 1.22, "Путник, вы – сущее сокровище!" }, { 3.47, "Ваши преданность и помощь просто неоценимы, я даже не знаю, чем вас отблагодарить!" }, { 9.65, "Пожалуйста, примите это за ваши труды." }, { 12.64, "Мне надо кое над чем поработать, но я уверен, что, когда вы вернётесь, мне снова понадобится ваша помощь." }, { 20.46, "Благодарю вас!" }, { 21.55, "От всего сердца благодарю!" } }, f = { { 0.00, "Так вы их нашли?" }, { 1.20, "Путница, вы – сущее сокровище!" }, { 3.48, "Ваши преданность и помощь просто неоценимы, я даже не знаю, чем вас отблагодарить!" }, { 9.56, "Пожалуйста, примите это за ваши труды." }, { 12.50, "Мне надо кое над чем поработать, но я уверен, что, когда вы вернётесь, мне снова понадобится ваша помощь." }, { 20.19, "Благодарю вас!" }, { 21.26, "От всего сердца благодарю!" } } } } },
    [4521] = { d = 37.2, v = "orc-male#60", n = { x = 379 }, c = { x = { { 0.00, "Зимние Ключи расположены как раз за Древобрюхами на северо-востоке Осквернённого леса." }, { 6.84, "Приходилось там бывать?" }, { 8.74, "Я слышал, что эти края заселены существами, которых называют дикими совухами." }, { 15.07, "Эти животные, как известно, охраняли тайны ночных эльфов." }, { 19.80, "Мы должны выяснить, какие тайны хранятся в Зимних Ключах." }, { 24.54, "Я слышал, что лохматые совухи водятся к югу от этой дороги, а те, которых называют бешеными совухами, населяют центр Зимних Ключей." }, { 35.17, "Убей их и расчисть дорогу." } } }, t = { d = 9.3, g = 1, v = "orc-male#60", n = { m = 87, f = 88 }, c = { m = { { 0.00, "Отличные новости." }, { 1.47, "Теперь, когда эти твари не стоят у нас на пути, мы можем проникнуть в Зимние Ключи." }, { 8.38, "Ты готов?" } }, f = { { 0.00, "Отличные новости." }, { 1.50, "Теперь, когда эти твари не стоят у нас на пути, мы можем проникнуть в Зимние Ключи." }, { 8.54, "Ты готова?" } } } } },
    [4542] = { d = 28.0, v = "tauren-male", n = { x = 285 }, c = { x = { { 0.00, "Кентавры стали всё чаще нападать на эти земли, и об этом нужно срочно доложить на Заставу Вольного Ветра!" }, { 8.70, "Отправляйтесь туда, найдите дозорного утёсов Долгорога и отдайте ему это письмо." }, { 15.28, "Форт находится к юго-востоку отсюда." }, { 18.28, "Но будьте осторожны: неподалёку есть поселение клана Зловещий Тотем, и его члены в последнее время ведут себя беспокойно." } } }, t = { d = 14.2, v = "tauren-male#67", n = { x = 133 }, c = { x = { { 0.00, "Опять плохие новости!" }, { 1.93, "Эти кентавры зашли слишком далеко!" }, { 5.03, "Они напали на один из моих караванов и убили всех погонщиков!" }, { 10.37, "Это неслыханно, они должны за это заплатить!" } } } } },
    [4561] = { t = { d = 19.0, v = "narrator", n = { x = 195 }, c = { x = { { 0.00, "Вы берёте чашку Петри с пробой слизи." }, { 3.05, "Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое." }, { 13.30, "В конце концов вы должны найти пробу, которая устроит химика Барабоса." } } } } },
    [4581] = { d = 21.8, v = "nightelf-female#52", n = { x = 254 }, c = { x = { { 0.00, "Друид Кайнет Штиль прислал мне весточку." }, { 2.83, "Он хотел бы получить отчёт обо всём, что творится у нас на побережье и в лесах вокруг Астранаара." }, { 9.42, "Он опасается, что по Ясеневому лесу расползается порча..." }, { 13.38, "Может, он и прав." }, { 14.57, "Вот, отнеси ему мой отчёт." }, { 16.39, "Ты найдёшь его в святилище Лесной Песни, в лесах Ночной Песни к востоку отсюда." } } }, t = { d = 16.4, v = "nightelf-male#54", n = { x = 150 }, c = { x = { { 0.00, "А, отчёт Шиндрелл!" }, { 1.62, "Премного благодарен." }, { 3.49, "Шиндрелл – отличный часовой, она отважна и умна." }, { 7.96, "Надо прочесть это донесение и попытаться понять, что за нечисть расползается по Ясеневому лесу." } } } } },
    [4601] = { d = 36.9, v = "narrator", n = { x = 368 }, c = { x = { { 0.00, "Среди гномов, что укрылись здесь от бушующего снаружи безумия, этот механизм сразу бросается в глаза." }, { 7.65, "Небольшая табличка, прикреплённая к устройству, гласит: \"Чистер пять тысяч двести\"." }, { 13.81, "Ваши фамильные драгоценности и просто безделушки покрывает пыль веков?" }, { 19.09, "Чистер пять тысяч двести легко справится с этой проблемой!" }, { 23.56, "Положите внутрь вещь, которую хотите почистить, опустите в щель приёмника три серебряные монеты и подождите пару минут, пока Чистер пять тысяч двести наводит лоск на ваши украшения." } } }, t = { d = 15.5, v = "narrator", n = { x = 156 }, c = { x = { { 0.00, "Вы кладёте покрытый грязью предмет и три серебряные монеты в Чистер пять тысяч двести, и машина начинает работать, с гудением отскребая въевшуюся грязь." }, { 11.67, "Металлический корпус аппарата скрипит и вибрирует." } } } } },
    [4602] = { d = 37.5, v = "narrator", n = { x = 368 }, c = { x = { { 0.00, "Среди гномов, что укрылись здесь от бушующего снаружи безумия, этот механизм сразу бросается в глаза." }, { 7.78, "Небольшая табличка, прикреплённая к устройству, гласит: \"Чистер пять тысяч двести\"." }, { 14.05, "Ваши фамильные драгоценности и просто безделушки покрывает пыль веков?" }, { 19.42, "Чистер пять тысяч двести легко справится с этой проблемой!" }, { 23.96, "Положите внутрь вещь, которую хотите почистить, опустите в щель приёмника три серебряные монеты и подождите пару минут, пока Чистер пять тысяч двести наводит лоск на ваши украшения." } } }, t = { d = 15.4, v = "narrator", n = { x = 156 }, c = { x = { { 0.00, "Вы кладёте покрытый грязью предмет и три серебряные монеты в Чистер пять тысяч двести, и машина начинает работать, с гудением отскребая въевшуюся грязь." }, { 11.67, "Металлический корпус аппарата скрипит и вибрирует." } } } } },
    [4603] = { t = { d = 21.4, v = "narrator", n = { x = 207 }, c = { x = { { 0.00, "Чистер пять тысяч двести с яростным гудением принимается за работу." }, { 5.36, "Въевшаяся грязь растворяется под воздействием гномьих чистящих средств." }, { 10.87, "Наконец Чистер пять тысяч двести перестаёт вибрировать." }, { 15.23, "Окошко приёмника со звоном открывается – в нём лежит аккуратно завёрнутая коробка." } } } } },
    [4604] = { t = { d = 21.9, v = "narrator", n = { x = 207 }, c = { x = { { 0.00, "Чистер пять тысяч двести с яростным гудением принимается за работу." }, { 5.48, "Въевшаяся грязь растворяется под воздействием гномьих чистящих средств." }, { 11.11, "Наконец Чистер пять тысяч двести перестаёт вибрировать." }, { 15.57, "Окошко приёмника со звоном открывается – в нём лежит аккуратно завёрнутая коробка." } } } } },
    [4605] = { t = { d = 36.5, v = "narrator", n = { x = 342 }, c = { x = { { 0.00, "Так же внезапно, как начал, Чистер пять тысяч двести резко останавливается." }, { 6.00, "Из машины раздаётся тихое «дзинь», и её раструб по спирали раскрывается вверх." }, { 12.07, "Внутри Чистера пять тысяч двести лежит маленькая коробочка, перевязанная бантиком." }, { 18.71, "Похоже, очистив предмет от въевшейся грязи, машина ещё и упаковывает его." }, { 24.64, "Даже если она не сработала, по крайней мере, предмет теперь лежит в красивой коробке." }, { 31.65, "Что ж, есть только один способ узнать, очистился он или нет..." } } } } },
    [4606] = { t = { d = 36.6, v = "narrator", n = { x = 342 }, c = { x = { { 0.00, "Так же внезапно, как начал, Чистер пять тысяч двести резко останавливается." }, { 6.02, "Из машины раздаётся тихое «дзинь», и её раструб по спирали раскрывается вверх." }, { 12.12, "Внутри Чистера пять тысяч двести лежит маленькая коробочка, перевязанная бантиком." }, { 18.80, "Похоже, очистив предмет от въевшейся грязи, машина ещё и упаковывает его." }, { 24.75, "Даже если она не сработала, по крайней мере, предмет теперь лежит в красивой коробке." }, { 31.79, "Что ж, есть только один способ узнать, очистился он или нет..." } } } } },
    [4621] = { d = 34.4, g = 1, v = "human-male", n = { m = 354, f = 356 }, c = { m = { { 0.00, "Слышь, ты, морской волк..." }, { 1.81, "Нам, пиратам Кровавого Паруса, жить да поживать бы, когда бы не Пиратская бухта." }, { 7.49, "Ух, мы порезвились бы вдоволь!" }, { 9.62, "А если б ты пырнул ножом командира флота Морского Рога, чихали бы мы тогда на его посудины!" }, { 16.80, "Если б ты пырнул ножом барона Ревилгаза, мы б и их закона не боялись." }, { 21.70, "В общем, коль хочешь стать у нас почётным адмиралом – да, АДМИРАЛОМ, я не шучу, прирежь обоих, и все дела." }, { 30.29, "Иди, парень, возвращайся, когда дело будет сделано." } }, f = { { 0.00, "Слышь, ты, морской волк..." }, { 1.84, "Нам, пиратам Кровавого Паруса, жить да поживать бы, когда бы не Пиратская бухта." }, { 7.64, "Ух, мы порезвились бы вдоволь!" }, { 9.82, "А если б ты пырнула ножом командира флота Морского Рога, чихали бы мы тогда на его посудины!" }, { 17.15, "Если б ты пырнула ножом барона Ревилгаза, мы б и их закона не боялись." }, { 21.76, "В общем, коль хочешь стать у нас почётным адмиралом – да, АДМИРАЛОМ, я не шучу, прирежь обоих, и все дела." }, { 30.67, "Иди, девица, возвращайся, когда дело будет сделано." } } }, t = { d = 16.7, g = 1, v = "human-male", n = { x = 161 }, c = { m = { { 0.00, "Стой... адмирал путник!" }, { 1.81, "Ты всем пиратам пират, дружище!" }, { 4.25, "У меня аж сердце радуется, что я дарю тебе эту шляпу." }, { 8.50, "Такой ты нигде больше не сыщешь, и всяк, кто глянет на тебя, увидит, что ты адмирал флота Кровавого Паруса!" } }, f = { { 0.00, "Стой... адмирал путница!" }, { 1.88, "Ты всем пиратам пират, дружище!" }, { 4.32, "У меня аж сердце радуется, что я дарю тебе эту шляпу." }, { 8.57, "Такой ты нигде больше не сыщешь, и всяк, кто глянет на тебя, увидит, что ты адмирал флота Кровавого Паруса!" } } } } },
    [4641] = { d = 42.2, g = 1, v = "orc-male", n = { m = 374, f = 375 }, c = { m = { { 0.00, "Ну вот, ты и стал взрослым... достаточно взрослым, чтобы сражаться во имя Орды и во славу вождя." }, { 9.52, "*Калтунк меряет вас взглядом.*" }, { 12.40, "Да, ты вполне годишься!" }, { 14.39, "Разумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного." }, { 29.76, "Отправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, юный герой." }, { 38.87, "Горнека ты найдёшь в Логове, на западе." } }, f = { { 0.00, "Ну вот, ты и стала взрослой... достаточно взрослой, чтобы сражаться во имя Орды и во славу вождя." }, { 9.28, "*Калтунк меряет вас взглядом.*" }, { 12.00, "Да, ты вполне годишься!" }, { 14.02, "Разумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного." }, { 29.60, "Отправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, юная героиня." }, { 38.98, "Горнека ты найдёшь в Логове, на западе." } } }, t = { d = 16.6, g = 1, v = "orc-male#60", n = { m = 152, f = 156 }, c = { m = { { 0.00, "Очередной рекрут Калтунка?" }, { 2.26, "Видно, плохи наши дела, если у нас нет никого получше." }, { 6.92, "Ну, ничего." }, { 7.89, "К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравый воитель Орды!" } }, f = { { 0.00, "Очередной рекрут Калтунка?" }, { 2.28, "Видно, плохи наши дела, если у нас нет никого получше." }, { 6.99, "Ну, ничего." }, { 7.98, "К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравая воительница Орды!" } } } } },
    [4642] = { d = 29.5, g = 1, v = "scourge-male", n = { m = 281, f = 283 }, c = { m = { { 0.00, "В этом сосуде находится слизнюк, созданный из пробы, которую ты принёс из Осквернённого леса." }, { 7.77, "Отнеси его к кратеру Ун'Горо и отыщи чистого слизнюка." }, { 12.50, "Подберись поближе, выпусти наш экземпляр и посмотри, что они сделают друг с другом." }, { 19.50, "По завершении эксперимента принеси мне пробу того, что останется." }, { 24.99, "Я буду ждать тебя здесь, в Районе Фармацевтов." } }, f = { { 0.00, "В этом сосуде находится слизнюк, созданный из пробы, которую ты принесла из Осквернённого леса." }, { 8.16, "Отнеси его к кратеру Ун'Горо и отыщи чистого слизнюка." }, { 12.97, "Подберись поближе, выпусти наш экземпляр и посмотри, что они сделают друг с другом." }, { 20.12, "По завершении эксперимента принеси мне пробу того, что останется." }, { 25.72, "Я буду ждать тебя здесь, в Районе Фармацевтов." } } }, t = { d = 27.8, v = "scourge-male", n = { x = 267 }, c = { x = { { 0.00, "О, великолепно." }, { 1.32, "Великолепно." }, { 2.40, "Ну и дела." }, { 3.33, "Кто бы подумал, что они будут взаимодействовать таким образом..." }, { 8.84, "Придётся посвятить побольше времени изучению феноменов окружающей среды, которые вызывают в этих тварях подобные изменения." }, { 19.46, "А теперь я вернусь к своим исследованиям." }, { 23.03, "Быть может, вскоре свидимся." }, { 25.51, "Пока же – всего наилучшего." } } } } },
    [4661] = { t = { d = 18.4, v = "narrator", n = { x = 195 }, c = { x = { { 0.00, "Вы берёте чашку Петри с пробой слизи." }, { 2.96, "Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое." }, { 12.91, "В конце концов вы должны найти пробу, которая устроит химика Барабоса." } } } } },
    [4681] = { d = 33.2, v = "nightelf-female#51", n = { x = 398 }, c = { x = { { 0.00, "Та тварь на берегу – не единственная на Тёмном Берегу." }, { 3.61, "Вдоль побережья их ещё много, да и в воде тоже." }, { 6.86, "Я хотела бы, чтобы вы исследовали другие известные нам останки." }, { 11.22, "Мне сообщили, что они находятся в воде, непосредственно к западу от Аубердина, возле затонувшего судна." }, { 18.32, "Возвращайтесь ко мне с тем, что вам удастся найти полезного для нас." }, { 22.87, "Кстати, в ваших странствиях вы можете найти и другие подобные останки." }, { 27.80, "Если вы обнаружите что-то, обязательно принесите нам для дальнейших исследований!" } } }, t = { d = 30.6, v = "nightelf-female#51", n = { x = 375 }, c = { x = { { 0.00, "Вы чрезвычайно помогли мне сегодня; теперь у нас есть серьёзные шансы узнать, почему эти твари выбрасываются на отмели Тёмного Берега." }, { 9.01, "Мысль о том, что они бегут сюда из прибрежных вод Тельдрассила, очень беспокоит меня." }, { 14.77, "Если вы наткнётесь на другие останки в ваших странствиях, пожалуйста, дайте мне знать." }, { 20.53, "Наши исследования здесь пока на начальной стадии." }, { 23.90, "От имени Храма Луны примите, пожалуйста, это в качестве благодарности за ваши труды." }, { 29.72, "Благодарю вас!" } } } } },
    [4701] = { d = 27.6, v = "nightelf-male#54", n = { x = 276 }, c = { x = { { 0.00, "Тебе несомненно приходилось видеть воргов, которыми командуют орки Чёрной Горы." }, { 6.47, "Вот что интересно – сколько мы их ни убиваем, их не делается меньше." }, { 11.84, "Разведчики доносят, что воргов растят и обучают на пике Чёрной Горы, в столице орков этого клана." }, { 19.76, "Отправляйся туда и поищи источник опасности." }, { 23.39, "Отыщи... и уничтожь." }, { 25.06, "Удачи." }, { 25.65, "Да хранит тебя Кенарий..." } } }, t = { d = 12.4, g = 1, v = "nightelf-male#54", n = { m = 112, f = 113 }, c = { m = { { 0.00, "Не думай о том, страдала ли она." }, { 2.79, "Этого зверя осквернило касание тёмной магии." }, { 6.65, "Ты оказал Альянсу огромную услугу и получишь за неё награду." } }, f = { { 0.00, "Не думай о том, страдала ли она." }, { 2.94, "Этого зверя осквернило касание тёмной магии." }, { 7.01, "Ты оказала Альянсу огромную услугу и получишь за неё награду." } } } } },
    [4721] = { d = 31.3, v = "orc-male#60", n = { x = 335 }, c = { x = { { 0.00, "Гонцы вернулись из Зимних Ключей с сообщением о том, что в их южной части есть группа небольших пещер." }, { 7.67, "У них сложилось впечатление, что этот район обжили дикие совухи." }, { 12.56, "Если они охраняют что-то важное, то, я думаю, именно там мы это и найдём." }, { 18.12, "С этими дикими совухами тебе будет справиться намного сложнее, чем в предыдущий раз." }, { 24.50, "Эти создания, похоже, ввергает в безумие та самая вещь, которую они столь яростно защищают." } } }, t = { d = 8.6, v = "orc-male#60", n = { x = 75 }, c = { x = { { 0.00, "Вот что я уважаю – так это хорошую работу." }, { 3.90, "Теперь мы можем дальше действовать в Зимних Ключах." } } } } },
    [4722] = { d = 19.0, v = "narrator", n = { x = 223 }, c = { x = { { 0.00, "Вы наткнулись на останки морской черепахи, некоторое время назад выбросившейся на Тёмный Берег." }, { 6.99, "Плоть её уже объели мурлоки, обосновавшиеся неподалёку от останков." }, { 11.85, "Однако вы можете набрать достаточное количество образцов, которые пригодятся Гвеннид Блай'Леггонд." } } }, t = { d = 15.8, v = "nightelf-female#51", n = { x = 186 }, c = { x = { { 0.00, "Ещё одна находка, которую нам надо изучить." }, { 3.12, "Хорошая работа!" }, { 4.26, "Эти останки будут исследованы должным образом, когда их доставят в Дарнасс." }, { 9.67, "Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете." } } } } },
    [4723] = { d = 31.0, v = "narrator", n = { x = 346 }, c = { x = { { 0.00, "Останки гигантского крепкозуба – намного больших размеров, чем можно было бы ожидать на Тёмном Берегу, – лежат у побережья Туманного предела." }, { 10.53, "Как это существо очутилось здесь, неизвестно; мурлоки, объедающие тушу, кажутся слишком слабыми и неспособными даже толпой притащить её сюда." }, { 21.12, "В то время как некоторая часть костей уже начисто обглодана, останков ещё достаточно, чтобы набрать образцов для Гвеннид Блай'Леггонд." } } }, t = { d = 15.6, v = "nightelf-female#51", n = { x = 186 }, c = { x = { { 0.00, "Ещё одна находка, которую нам надо изучить." }, { 3.09, "Хорошая работа!" }, { 4.22, "Эти останки будут исследованы должным образом, когда их доставят в Дарнасс." }, { 9.57, "Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете." } } } } },
    [4724] = { d = 43.1, v = "tauren-male#68", n = { x = 408 }, c = { x = { { 0.00, "Ходят слухи, что ворги, управляемые орками Чёрной Горы, – создания сверхъестественных сил." }, { 7.44, "Говорят также, что это не настоящие ворги, а потомство пса-демона, подаренное оркам властителем преисподней." }, { 16.45, "Правда куда более проста, но не менее ужасна." }, { 20.36, "Ворги Чёрной Горы – потомство Халикон, огромной праматери воргов." }, { 26.37, "Каков из себя её самец?" }, { 28.39, "Вряд ли кто из видевших его выжил, чтобы поведать об этом." }, { 33.28, "Нужно нанести удар по самому сердцу логова воргов." }, { 38.32, "Уничтожь Халикон." }, { 39.82, "И прошу тебя, не забывай об осторожности!" } } }, t = { d = 12.2, g = 1, v = "tauren-male#68", n = { m = 113, f = 114 }, c = { m = { { 0.00, "Бешеные щенки?" }, { 1.36, "Гизрул Поработитель?" }, { 3.20, "И ты стоишь передо мной живёхонький и рассказываешь об этом?!" }, { 8.48, "Глазам не верю!" }, { 9.92, "Ты заслужил свою награду!" } }, f = { { 0.00, "Бешеные щенки?" }, { 1.37, "Гизрул Поработитель?" }, { 3.22, "И ты стоишь передо мной живёхонькая и рассказываешь об этом?!" }, { 8.54, "Глазам не верю!" }, { 9.98, "Ты заслужила свою награду!" } } } } },
    [4725] = { d = 32.4, v = "narrator", n = { x = 357 }, c = { x = { { 0.00, "Ещё одни останки морской черепахи лежат прямо на берегу." }, { 4.35, "К панцирю прикреплена упряжь." }, { 6.59, "Скорее всего, черепаху выгнали на берег неизвестные нам твари; она не выбросилась на берег сама, хотя другие останки и наводят на эту мысль." }, { 17.26, "Теперь останками черепахи завладели мурлоки клана Серой Мглы, питающиеся мертвечиной." }, { 23.71, "Обследуя упряжь, вы обнаруживаете ящик со странными пометками." }, { 28.40, "Может быть, Гвеннид Блай'Леггонд сможет что-то понять?" } } }, t = { d = 28.2, v = "nightelf-female#51", n = { x = 326 }, c = { x = { { 0.00, "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире." }, { 4.52, "Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу." }, { 12.62, "Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Тёмного Берега." }, { 20.47, "Я отошлю этот ящик в Дарнасс вместе с остальными вашими находками." }, { 25.18, "А это – вам, и ещё раз спасибо за вашу помощь." } } } } },
    [4726] = { d = 34.6, v = "goblin-female#63", n = { x = 389 }, c = { x = { { 0.00, "Я уже несколько недель изучаю драконов в Пылающих степях, и кажется, наконец-то наметился определённый прорыв!" }, { 8.13, "Я создала устройство – Драко-инкарцинатор девятьсот." }, { 11.93, "Оно может поймать сущность детёныша дракона!" }, { 15.26, "По крайней мере, я так думаю." }, { 17.46, "Возьми это устройство и испытай его на детёныше дракона в Пылающих степях." }, { 22.99, "Пока он будет под воздействием инкарцинатора, одолей его и выпусти из него сущность." }, { 29.26, "Если это сработает, будет замечательно!" }, { 32.25, "И принеси мне образцы на изучение!" } } }, t = { d = 25.4, g = 1, v = "goblin-female#63", n = { m = 274, f = 275 }, c = { m = { { 0.00, "Сработало!" }, { 0.81, "Ты добыл сущность драконов!" }, { 2.92, "Молодец!" }, { 3.60, "Она мне очень пригодится в ходе экспериментов." }, { 7.12, "Я надеюсь, что однажды придумаю способ ловить живых драконов или хотя бы добывать их яйца." }, { 14.04, "Если мне удастся найти способ, мне позавидуют все, кто занимается изучением драконов!" }, { 20.42, "Заказчик тоже будет доволен." }, { 22.66, "А такого, как он, лучше не огорчать..." } }, f = { { 0.00, "Сработало!" }, { 0.80, "Ты добыла сущность драконов!" }, { 2.95, "Молодец!" }, { 3.62, "Она мне очень пригодится в ходе экспериментов." }, { 7.10, "Я надеюсь, что однажды придумаю способ ловить живых драконов или хотя бы добывать их яйца." }, { 13.94, "Если мне удастся найти способ, мне позавидуют все, кто занимается изучением драконов!" }, { 20.24, "Заказчик тоже будет доволен." }, { 22.45, "А такого, как он, лучше не огорчать..." } } } } },
    [4727] = { d = 23.8, v = "narrator", n = { x = 269 }, c = { x = { { 0.00, "Скелет морской черепахи лежит на песчаной отмели на севере Тёмного Берега." }, { 5.55, "Мурлоки клана Серой Мглы либо не нашли её тушу, либо по каким-то причинам не рискнули приблизиться к ней." }, { 13.36, "В любом случае, от черепахи осталось достаточно, чтобы взять образцы для Гвеннид Блай'Леггонд, проводящей расследование по поручению Храма Луны." } } }, t = { d = 15.0, v = "nightelf-female#51", n = { x = 181 }, c = { x = { { 0.00, "Интересно, что мурлоков там не было." }, { 2.46, "Мы будем иметь это в виду, когда начнём изучать эти останки!" }, { 6.70, "Благодарю вас за ваши труды; Храм Луны уполномочил меня передать вам эти деньги в качестве компенсации за потраченное время." } } } } },
    [4728] = { d = 25.4, v = "narrator", n = { x = 295 }, c = { x = { { 0.00, "Растерзанные останки того, что на вид кажется похожим на гигантское морское млекопитающее, лежат на берегу." }, { 7.76, "Около них валяется тачка и различные инструменты, как будто кто-то раньше уже пытался изучать останки." }, { 15.33, "Хотя мурлоки основательно растащили скелет, останков достаточно, чтобы найти подходящий образец костей для Гвеннид Блай'Леггонд в Аубердине." } } }, t = { d = 25.7, v = "nightelf-female#51", n = { x = 283 }, c = { x = { { 0.00, "О, я уверена, вы обнаружили останки твари, которые уже изучались Лигой Исследователей." }, { 6.37, "Они работают здесь, на Тёмном Берегу, и упоминали, что изучали одну из выбросившихся на берег тварей, пока их не прогнали мурлоки." }, { 15.87, "Похоже, вам удалось добиться успеха там, где и мы, и они потерпели фиаско." }, { 21.31, "Пожалуйста, примите эту скромную плату от имени Храма Луны." } } } } },
    [4729] = { d = 33.2, v = "goblin-male#65", n = { x = 335 }, c = { x = { { 0.00, "Должно быть, тебе интересно, что я здесь делаю?" }, { 3.63, "Взгляни на клетки!" }, { 5.09, "Разве не ясно?" }, { 6.28, "Я очень люблю животных, но по роду занятий я торговец." }, { 10.54, "Я разыскиваю и приручаю редких зверей, чтобы богатые и знаменитые клиенты могли сделать их своими питомцами." }, { 18.98, "Теперь ты, наверное, хочешь спросить: \"Чем я могу тебе помочь, Киблер?\" Отвечаю: возьми эту клетку и поймай несколько щенков-воргов." }, { 29.85, "За это я приручу одного из них и отдам тебе!" } } }, t = { d = 9.7, g = 1, v = "goblin-male#65", n = { m = 102, f = 104 }, c = { m = { { 0.00, "Ты вовремя их принёс." }, { 1.58, "Подрасти они ещё немного, и их не удалось бы приручить!" }, { 5.77, "Дай мне пару минут, и одного из них можешь забирать." } }, f = { { 0.00, "Ты вовремя их принесла." }, { 1.76, "Подрасти они ещё немного, и их не удалось бы приручить!" }, { 5.90, "Дай мне пару минут, и одного из них можешь забирать." } } } } },
    [4730] = { d = 22.0, v = "narrator", n = { x = 245 }, c = { x = { { 0.00, "Полуразложившееся тело твари, похожей на огромное морское млекопитающее, лежит на берегу." }, { 6.81, "Группа мурлоков, более сильных, чем обитающие ближе к Аубердину, обосновалась вокруг погибшего создания." }, { 14.79, "Останков достаточно, чтобы отобрать образцы костей, которые можно отнести Гвеннид Блай'Леггонд." } } }, t = { d = 29.5, v = "nightelf-female#51", n = { x = 357 }, c = { x = { { 0.00, "Кости, которые вы принесли, принадлежат мирным морским млекопитающим, обитающим в водах, окружающих корни Тельдрассила." }, { 8.07, "Им, насколько известно, никогда не было свойственно выбрасываться на берег, как это делают крепкозубы." }, { 14.98, "Хотела бы я знать, почему они так ведут себя." }, { 18.10, "Что ж, может быть, изучение их останков принесёт свои плоды, и мы что-то узнаем." }, { 23.48, "И снова спасибо вам за помощь." }, { 25.56, "Пожалуйста, примите это вознаграждение от имени Храма Луны." } } } } },
    [4731] = { d = 38.6, v = "narrator", n = { x = 410 }, c = { x = { { 0.00, "Ещё одни останки морской черепахи лежат у береговой линии." }, { 4.68, "На панцире есть упряжь, которая ещё частично держится." }, { 8.93, "Возможно, несчастная тварь не сама выбросилась на берег (что кажется наиболее вероятным по отношению к другим погибшим тварям), а была пригнана к береговой линии неизвестными существами." }, { 23.46, "Могучие мурлоки клана Серой Мглы сделали остов этой твари своим жилищем." }, { 29.35, "Обследуя упряжь, вы обнаруживаете ящик со странными пометками." }, { 34.24, "Возможно, Гвеннид Блай'Леггонд сумеет что-то разобрать?" } } }, t = { d = 27.5, v = "nightelf-female#51", n = { x = 324 }, c = { x = { { 0.00, "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире." }, { 4.44, "Это, как я понимаю, упряжь наг – они используют такие как в сражениях, так и для перевозок своих припасов на сушу." }, { 12.20, "Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Тёмного Берега." }, { 19.90, "Я отошлю этот ящик в Дарнасс вместе с остальными вашими находками." }, { 24.52, "А это – вам, и ещё раз спасибо за вашу помощь." } } } } },
    [4732] = { d = 20.9, v = "narrator", n = { x = 236 }, c = { x = { { 0.00, "Вы обнаружили тело морской черепахи, выбросившейся на Тёмный Берег некоторое время назад." }, { 6.65, "Оно почти дочиста объедено мурлоками клана Серой Мглы – теми самыми, что поселились вокруг останков." }, { 14.24, "Однако, похоже, несколько подходящих образцов для Гвеннид Блай'Леггонд вы сможете отобрать." } } }, t = { d = 28.9, v = "nightelf-female#51", n = { x = 350 }, c = { x = { { 0.00, "Так вы нашли и других выбросившихся на берег тварей?" }, { 3.58, "Морские черепахи обычно резвились в водах у подножья Нордрассила – до его гибели." }, { 9.20, "Однако с рождением Тельдрассила этих созданий становится всё меньше и меньше." }, { 14.51, "Некоторые, как мы уже знаем, оканчивают свою жизнь здесь – непонятно почему." }, { 19.70, "Быть может, ваша помощь поможет нам раскрыть эту тайну." }, { 23.59, "Пожалуйста, примите эти деньги за образцы, предоставленные нам для исследований." } } } } },
    [4733] = { d = 29.4, v = "narrator", n = { x = 326 }, c = { x = { { 0.00, "Останки животного, похожего на гигантского крепкозуба, лежат, вынесенные на отмель в скалистой Сумеречной Излучине." }, { 8.66, "Этот крепкозуб в несколько раз больше любого из тех, что обитают в здешних водах." }, { 14.79, "Откуда бы это создание ни приплыло, вряд ли оно родом с Тёмного Берега." }, { 20.18, "Хотя туша животного уже потеряла целостность, останков достаточно, чтобы найти подходящие образцы для Гвеннид Блай'Леггонд." } } }, t = { d = 30.1, v = "nightelf-female#51", n = { x = 356 }, c = { x = { { 0.00, "Размеры крепкозуба, о котором вы рассказываете, просто ошеломляют." }, { 4.62, "Даже самые старые крепкозубы в этих водах – и то в несколько раз меньше." }, { 9.74, "В то время как крупные крепкозубы, как известно, обитают близ Тельдрассила, их количество постоянно уменьшается." }, { 17.45, "Интересно, связано ли как-то это с выбрасывающимися на берег тварями?" }, { 22.32, "Мы продолжим анализ костей, которые вы нам принесли, а это вам вознаграждение от имени Храма Луны." }, { 29.21, "Благодарю вас." } } } } },
    [4734] = { d = 32.7, v = "goblin-female#63", n = { x = 361 }, c = { x = { { 0.00, "Я работаю над созданием нового устройства, яйцехладоскопа!" }, { 4.32, "Оно предназначено для того, чтобы направить сгусток холода на яйцо дракона... и заморозить его!" }, { 11.54, "Можешь испытать эту штуку?" }, { 13.63, "Говорят, что на пике Чёрной горы у драконов есть питомник, в котором полно яиц." }, { 19.57, "Подходящее место для испытаний!" }, { 21.93, "Заморозь яйцо и расскажи, сработал прибор или нет." }, { 25.78, "Не беспокойся." }, { 26.86, "Замороженные драконьи яйца совершенно безобидны." }, { 30.51, "А вот остальных надо опасаться!" } } }, t = { d = 14.5, v = "goblin-female#63", n = { x = 151 }, c = { x = { { 0.00, "Сработало?" }, { 0.85, "Великолепно!" }, { 1.85, "Я так и знала!" }, { 2.98, "Пока тебя не было, я создала новую модель яйцехладоскопа." }, { 7.60, "С куда большим радиусом действия." }, { 10.30, "Возьми его, вдруг случайно забредёшь на пик Чёрной горы." } } } } },
    [4735] = { d = 27.4, v = "goblin-female#63", n = { x = 327 }, c = { x = { { 0.00, "Я, наконец, готова исследовать настоящие яйца драконов!" }, { 3.91, "Возьми это устройство-коллекционер." }, { 6.44, "Оно предназначено для захвата драконьего яйца и подготовки его к транспортировке." }, { 12.12, "Возвращайся в Гнездовье и собери при помощи этой штуки несколько яиц." }, { 17.04, "Не забудь, первым делом их надо заморозить, иначе из них могут вылупиться драконы, не успеешь собрать!" }, { 24.24, "Как только наберёшь достаточно яиц, неси их мне!" } } }, t = { d = 10.4, v = "goblin-female#63", n = { x = 89 }, c = { x = { { 0.00, "Ух ты!" }, { 0.59, "Яйца!" }, { 1.18, "Значит, устройство-коллекционер сработало!" }, { 5.16, "Я гений!" }, { 6.00, "Спасибо." }, { 6.85, "Мой заказчик очень порадуется яйцам..." } } } } },
    [4736] = { d = 32.6, v = "gnome-male", n = { x = 391 }, c = { x = { { 0.00, "А, привет." }, { 0.74, "Твоё обучение идёт неплохо." }, { 2.60, "Настолько неплохо, что, я думаю, пришло время вознаградить тебя за прилежание – и за то, что сила магии всё ещё не поработила тебя." }, { 11.50, "Если тебя заинтересовали мои слова, поговори с Менарой Расщепительницей Бездны из Кабестана." }, { 17.88, "В настоящий момент она живёт в башне Страхада Фарсана, построенной на утёсе над городом." }, { 23.88, "Она не очень доброжелательно настроена, поэтому похвалы от неё не жди." }, { 28.64, "Но если ты будешь стараться, твои усилия не пропадут втуне." } } }, t = { d = 30.5, g = 1, v = "human-female#47", n = { m = 365, f = 366 }, c = { m = { { 0.00, "А, тебя прислал Остротерн." }, { 1.82, "Хорошо." }, { 2.36, "Значит, вести обо мне распространяются по всей земле, и ученики приходят сами." }, { 7.63, "Приятно." }, { 8.24, "Наш брат всегда старается держаться вместе, независимо от расы." }, { 12.48, "Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля." }, { 22.41, "Вижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту." } }, f = { { 0.00, "А, тебя прислал Остротерн." }, { 1.84, "Хорошо." }, { 2.39, "Значит, вести обо мне распространяются по всей земле, и ученики приходят сами." }, { 7.72, "Приятно." }, { 8.33, "Наш брат всегда старается держаться вместе, независимо от расы." }, { 12.62, "Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля." }, { 22.66, "Вижу, ты многому научилась, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту." } } } } },
    [4737] = { d = 34.2, g = 1, v = "orc-male", n = { m = 318, f = 319 }, c = { m = { { 0.00, "Ха!" }, { 0.31, "Я вижу, ты стремишься к могуществу." }, { 3.32, "Не сомневаюсь, рано или поздно ты падёшь жертвой соблазна и жажды магии." }, { 9.58, "Пфа!" }, { 9.97, "Ты глуп!" }, { 10.67, "Время покажет, что я был прав, – ничто другое, одно лишь время…" }, { 16.08, "Но мне кажется, что не все согласны с Зевростом." }, { 20.09, "Менара готова создать предметы, которые помогут тебе обрести могущество и обуздать собственную силу." }, { 28.83, "Если хочешь, ступай в Кабестан." }, { 31.61, "Она живёт в башне над городом." } }, f = { { 0.00, "Ха!" }, { 0.31, "Я вижу, ты стремишься к могуществу." }, { 3.32, "Не сомневаюсь, рано или поздно ты падёшь жертвой соблазна и жажды магии." }, { 9.56, "Пфа!" }, { 9.95, "Ты глупа!" }, { 10.80, "Время покажет, что я был прав, – ничто другое, одно лишь время…" }, { 16.19, "Но мне кажется, что не все согласны с Зевростом." }, { 20.20, "Менара готова создать предметы, которые помогут тебе обрести могущество и обуздать собственную силу." }, { 28.92, "Если хочешь, ступай в Кабестан." }, { 31.70, "Она живёт в башне над городом." } } }, t = { d = 30.6, g = 1, v = "human-female#47", n = { m = 363, f = 364 }, c = { m = { { 0.00, "А, тебя прислал Зеврост." }, { 1.73, "Хорошо." }, { 2.29, "Значит, вести обо мне распространяются по всей земле, и ученики приходят сами." }, { 7.66, "Приятно." }, { 8.28, "Наш брат всегда старается держаться вместе, независимо от расы." }, { 12.60, "Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля." }, { 22.73, "Вижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту." } }, f = { { 0.00, "А, тебя прислал Зеврост." }, { 1.72, "Хорошо." }, { 2.27, "Значит, вести обо мне распространяются по всей земле, и ученики приходят сами." }, { 7.60, "Приятно." }, { 8.22, "Наш бр