    [4740] = { d = 36.0, v = "narrator", n = { x = 379 }, c = { x = { { 0.00, "Внимание!" }, { 0.79, "Назначена награда за голову мурлока, именуемого \"Глубомрак\"." }, { 5.59, "Эта злобная тварь повинна в смерти как минимум одного часового и подозревается в потоплении как минимум двух грузовых судов в прибрежных водах Тёмного Берега!" }, { 18.07, "Глубомрака в последний раз видели в поселении мурлоков к югу от Аубердина, и, судя по всему, он охраняет хижины своих сородичей." }, { 28.25, "Награда за голову Глубомрака ждёт смельчака у часового Глинды Нал'Шии в Аубердине." }, { 34.78, "Совет Аубердина" } } }, t = { d = 23.8, g = 1, v = "nightelf-female#52", n = { m = 271, f = 272 }, c = { m = { { 0.00, "Что ж, похоже, вы здесь не только затем, чтобы просто узнать!" }, { 4.46, "Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее." }, { 11.08, "Сегодня вы послужили для наших жителей орудием справедливости." }, { 15.60, "И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящего героя народа Аубердина." } }, f = { { 0.00, "Что ж, похоже, вы здесь не только затем, чтобы просто узнать!" }, { 4.30, "Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее." }, { 10.68, "Сегодня вы послужили для наших жителей орудием справедливости." }, { 15.03, "И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящей героини народа Аубердина." } } } } },
    [4741] = { d = 21.1, v = "orc-male#60", n = { x = 210 }, c = { x = { { 0.00, "В северных областях Зимних Ключей дикие совухи совсем озверели." }, { 5.45, "Необходимо положить этому конец!" }, { 8.25, "Отправляйся на охоту, а заодно исследуешь местность, где они обитают." }, { 14.08, "Места там дикие, но ты справишься." }, { 16.96, "Возвращайся, когда убьёшь тринадцать диких совухов." } } }, t = { d = 6.7, v = "orc-male#60", n = { x = 60 }, c = { x = { { 0.00, "Сдаётся мне, тебе нравится эта работёнка." }, { 3.83, "Думаю, мы стараемся не напрасно." } } } } },
    [4742] = { d = 32.9, g = 1, v = "orc-male", n = { m = 320, f = 321 }, c = { m = { { 0.00, "Видишь, в этой печати есть три простых углубления." }, { 4.07, "В них надо вставить три камня власти; после этого властитель Змейталак, владыка нижней крепости, должен будет закалить печать в пламени чёрных драконов." }, { 16.43, "Найди эти камни!" }, { 17.88, "И помни, смертный: шансы, что у кого-то из трёх генералов нижней крепости будет при себе нужный нам камень, невелики." }, { 27.33, "Не отступайся!" }, { 28.50, "Ищи, будь внимателен и не теряй решимости!" } }, f = { { 0.00, "Видишь, в этой печати есть три простых углубления." }, { 4.20, "В них надо вставить три камня власти; после этого властитель Змейталак, владыка нижней крепости, должен будет закалить печать в пламени чёрных драконов." }, { 16.97, "Найди эти камни!" }, { 18.47, "И помни, смертная: шансы, что у кого-то из трёх генералов нижней крепости будет при себе нужный нам камень, невелики." }, { 28.23, "Не отступайся!" }, { 29.43, "Ищи, будь внимательна и не теряй решимости!" } } }, t = { d = 17.2, v = "orc-male", n = { x = 157 }, c = { x = { { 0.00, "*Образ Ваелана на миг расплывается мутным пятном.*" }, { 4.09, "*Камни, которые вы принесли, исчезли.*" }, { 7.12, "Теперь всё готово к тому, чтобы печать вознесения обрела свою силу." }, { 13.75, "Пора приступать к завершающему этапу." } } } } },
    [4743] = { d = 42.9, g = 1, v = "orc-male", n = { m = 448, f = 448 }, c = { m = { { 0.00, "Кроме тех, что живут в верхней крепости, очень немногие чёрные драконы способны закалить печать в пламени своего дыхания." }, { 9.49, "Змейталак – один из них, но его волю сломить невозможно." }, { 13.92, "Тебе надо добраться до Драконьих топей в Пылевых топях." }, { 18.35, "Там ты найдёшь древнего дракона, известного под именем Огнебор." }, { 23.20, "Ты должен сломить его волю." }, { 25.45, "И когда он ослабнет, тебе нужно будет воспользоваться этой сферой." }, { 30.73, "Но помни, смертный: его разум силён, и ты сможешь удерживать его под контролем не более нескольких секунд." }, { 39.02, "За эти секунды тебе нужно успеть закалить печать." } }, f = { { 0.00, "Кроме тех, что живут в верхней крепости, очень немногие чёрные драконы способны закалить печать в пламени своего дыхания." }, { 9.47, "Змейталак – один из них, но его волю сломить невозможно." }, { 13.90, "Тебе надо добраться до Драконьих топей в Пылевых топях." }, { 18.32, "Там ты найдёшь древнего дракона, известного под именем Огнебор." }, { 23.16, "Ты должна сломить его волю." }, { 25.41, "И когда он ослабнет, тебе нужно будет воспользоваться этой сферой." }, { 30.67, "Но помни, смертная: его разум силён, и ты сможешь удерживать его под контролем не более нескольких секунд." }, { 38.95, "За эти секунды тебе нужно успеть закалить печать." } } }, t = { d = 28.5, v = "orc-male", n = { x = 272 }, c = { x = { { 0.00, "Стой спокойно." }, { 1.39, "Я наложу последнее защитное заклинание." }, { 5.12, "*Глаза Ваелана превращаются в два огненных шара.*" }, { 9.36, "Теперь печать Вознесения обрела свою полную силу..." }, { 13.84, "Я вложил в артефакт очень мощные защитные чары." }, { 17.94, "В минуту предельного отчаяния, когда тебе покажется, что всё потеряно, призови силу красных драконов и используй её для защиты." } } } } },
    [4761] = { d = 32.6, v = "nightelf-male#54", n = { x = 393 }, c = { x = { { 0.00, "При разведке в лагере фурболгов вы обнаружили информацию, которую нужно довести до сведения Тандриса Ветропряда." }, { 7.95, "Он любезно согласился исполнять обязанности старейшины в Аубердине, мудростью своей направляя повседневную жизнь деревни." }, { 16.48, "Прошу вас поделиться с ним вашими находками в деле фурболгов." }, { 20.84, "Я уверен, что у него есть свои идеи по поводу источника наведённой на них порчи." }, { 26.48, "Может быть, вы сможете вместе с ним выработать план восстановления природного равновесия!" } } }, t = { d = 27.4, g = 1, v = "nightelf-male#54", n = { x = 297 }, c = { m = { { 0.00, "Рад нашей встрече, герой." }, { 1.89, "Ваше расследование ситуации с фурболгами как нельзя кстати." }, { 6.20, "Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящимися к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведённой на сами леса." }, { 20.56, "Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена." } }, f = { { 0.00, "Рад нашей встрече, героиня." }, { 2.11, "Ваше расследование ситуации с фурболгами как нельзя кстати." }, { 6.59, "Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящимися к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведённой на сами леса." }, { 21.53, "Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена." } } } } },
    [4762] = { d = 41.7, v = "nightelf-male#54", n = { x = 425 }, c = { x = { { 0.00, "Воды реки Скалистой исполнились злобы и порчи." }, { 3.83, "Река впадает в Туманный предел, и я боюсь, что скоро беда затронет и Аубердин." }, { 10.19, "Я подозреваю, что в загрязнении повинны фурболги Чернолесья, живущие в верховьях реки, но я также полагаю, что они не являются подлинной причиной этой порчи." }, { 22.76, "Возьмите эту пробирку и отправляйтесь к устью реки, что к северу отсюда." }, { 28.61, "Идите вверх по реке до первого водопада и там возьмите пробу воды." }, { 33.96, "Ориентиром вам послужит высокий мост через реку." }, { 37.86, "Когда возьмёте пробу, вернитесь ко мне в Аубердин." } } }, t = { d = 35.7, v = "nightelf-male#54", n = { x = 399 }, c = { x = { { 0.00, "Я не удивлён тем, насколько сильно отравлена эта вода, но поглядите, какой мерзостной она становится!" }, { 7.38, "Похоже, что нужно действовать как можно скорее, да?" }, { 11.13, "К востоку от нас находится Осквернённый лес; это и есть настоящий источник порчи, я в прошлом такой уже видел." }, { 19.10, "Заранее могу сказать, что ваша проба подтвердит это." }, { 23.05, "Наверное, мы могли бы найти средство для исцеления, но нам понадобится помощь, даже чтобы попытаться это сделать." }, { 31.35, "Когда придёт время, я надеюсь, вы сможете нам её предоставить." } } } } },
    [4763] = { d = 40.2, v = "nightelf-male#54", n = { x = 455 }, c = { x = { { 0.00, "Мы узнали, что источником порчи, наведённой на фурболгов, являются сатиры." }, { 5.33, "Они держат своих жертв в повиновении с помощью талисманов, через которые направляют магию." }, { 11.97, "Если для фурболгов ещё есть шансы на спасение, мы должны выманить сатиров-поработителей и отнять у них талисманы!" }, { 20.13, "Наполни эту чашу из нашего лунного колодца и стащи образцы пищи фурболгов из их северного лагеря." }, { 27.36, "Смешай всё и поставь чашу возле большого костра у реки; любой фурболг, поевший из этой чаши, на некоторое время очистится, что привлечёт внимание сатира... которого нужно убить!" } } }, t = { d = 26.8, g = 1, v = "nightelf-male#54", n = { x = 287 }, c = { m = { { 0.00, "Мы только начали войну за освобождение наших лесов от порабощающих сил порчи, но сегодняшняя битва выиграна!" }, { 8.13, "Путник, народ Аубердина в огромном и почти неоплатном долгу перед вами." }, { 13.61, "Прошу вас принять это вместе с нашей благодарностью." }, { 17.61, "То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков." } }, f = { { 0.00, "Мы только начали войну за освобождение наших лесов от порабощающих сил порчи, но сегодняшняя битва выиграна!" }, { 8.23, "Путница, народ Аубердина в огромном и почти неоплатном долгу перед вами." }, { 13.85, "Прошу вас принять это вместе с нашей благодарностью." }, { 17.90, "То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков." } } } } },
    [4764] = { d = 37.2, v = "human-female#45", n = { x = 407 }, c = { x = { { 0.00, "Высоко в горах, на пике Чёрной горы, есть чертог, который некогда звался Залом Сокровищ." }, { 6.66, "Именно там дворфы Чёрного Железа хранили свои реликвии, трофеи и предметы искусства." }, { 12.99, "Это было давно." }, { 14.27, "Говорят, что зал обрушился, и теперь используется... менее достойно." }, { 19.31, "Но я думаю, что там остались дворфийские реликвии." }, { 23.01, "Одна из них – пряжка Роковой оснастки." }, { 25.91, "Её поверхность так плотно инкрустирована редкими самоцветами, что любой дворф начинает плакать от одного её вида." }, { 34.25, "Именно эта пряжка и станет твоей целью." } } }, t = { d = 11.0, g = 1, v = "human-female#45", n = { m = 106, f = 106 }, c = { m = { { 0.00, "Ты нашёл её!" }, { 1.00, "Значит, слухи оказались правдой!" }, { 3.83, "Спасибо." }, { 4.60, "Мой клиент, граф Ремингтон Риджвелл, с радостью поместит её в свою коллекцию." } }, f = { { 0.00, "Ты нашла её!" }, { 1.00, "Значит, слухи оказались правдой!" }, { 3.66, "Спасибо." }, { 4.38, "Мой клиент, граф Ремингтон Риджвелл, с радостью поместит её в свою коллекцию." } } } } },
    [4765] = { d = 17.8, g = 1, v = "human-female#45", n = { m = 188, f = 190 }, c = { m = { { 0.00, "Я упаковала пряжку Роковой оснастки в ящик для отправки в Штормград." }, { 5.09, "Путник, ты мне очень помог, но я хочу попросить ещё об одной услуге." }, { 10.17, "Доставь этот ящик графу Ремингтону Риджвеллу." }, { 13.65, "Он в Крепости Штормграда." }, { 15.53, "Не сомневаюсь, он обрадуется." } }, f = { { 0.00, "Я упаковала пряжку Роковой оснастки в ящик для отправки в Штормград." }, { 5.12, "Путница, ты мне очень помогла, но я хочу попросить ещё об одной услуге." }, { 10.44, "Доставь этот ящик графу Ремингтону Риджвеллу." }, { 13.95, "Он в Крепости Штормграда." }, { 15.83, "Не сомневаюсь, он обрадуется." } } }, t = { d = 9.2, v = "human-male", n = { x = 83 }, c = { x = { { 0.00, "А, так это ты!" }, { 1.24, "Спасибо." }, { 2.01, "И... если ты ещё не знаешь об этом... благодарность дома Риджвеллов стоит королевской." } } } } },
    [4766] = { d = 32.1, v = "human-male", n = { x = 387 }, c = { x = { { 0.00, "Мой агент, Майра, отправилась в Пылающие степи, чтобы обыскать развалины города Тауриссана." }, { 6.33, "В разрушенном обиталище дворфов Чёрного Железа таится множество ценных вещей... которые украсят наш семейный музей." }, { 14.28, "Майра говорит, что кое-что нашла, но ей нужна помощь." }, { 18.00, "Правда, это находится не в Тауриссане." }, { 20.67, "Вместо этого требуется устроить вылазку на пик Чёрной горы." }, { 24.77, "Подробности мне неизвестны, но если тебя заинтересовало моё предложение, поговори с Майрой в Пылающих степях." } } }, t = { d = 12.7, v = "human-female#45", n = { x = 140 }, c = { x = { { 0.00, "Ты из Штормграда?" }, { 1.27, "Чудесно – я знаю об одном предмете искусства, который Ремингтон любой ценой захочет заполучить в свой музей." }, { 9.33, "Но это будет нелегко." }, { 11.00, "Тут-то ты и понадобишься." } } } } },
    [4767] = { d = 50.7, v = "tauren-male", n = { x = 504 }, c = { x = { { 0.00, "Мне велели набрать новых виверн, чтобы выдрессировать их и использовать в качестве ездовых животных." }, { 8.29, "Их поголовье постоянно растёт, и я надеюсь, что когда-нибудь сам смогу стать воздушным всадником." }, { 16.14, "Однако виверны пользуются большим спросом, и нам их постоянно не хватает." }, { 22.19, "Может быть, вы, сможете мне помочь?" }, { 25.10, "Я хочу попросить вас отправиться в Скальное гнездовье и набрать с кладок виверн немного яиц." }, { 32.80, "Отсюда ступайте на северо-запад, держитесь поближе к стене каньона – и увидите дорогу, ведущую наверх." }, { 41.39, "Но будьте очень осторожны: виверны не любят чужаков, а уж за свои кладки они будут готовы разорвать кого угодно." } } }, t = { d = 15.8, g = 1, v = "tauren-male", n = { x = 121 }, c = { m = { { 0.00, "Отлично!" }, { 0.90, "Детёныши из этих яиц помогут мне осуществить задуманное!" }, { 6.48, "Возьмите это в знак моей признательности, пусть вам всегда везёт на любой охоте, герой." } }, f = { { 0.00, "Отлично!" }, { 0.94, "Детёныши из этих яиц помогут мне осуществить задуманное!" }, { 6.78, "Возьмите это в знак моей признательности, пусть вам всегда везёт на любой охоте, героиня." } } } } },
    [4768] = { d = 51.4, v = "scourge-female#80", n = { x = 495 }, c = { x = { { 0.00, "Табличка Темнокамня – это записки покойного дворфа Урхельда Темнокамня." }, { 6.11, "Он был величайшим алхимиком древности, но современники считали его безумцем, и потому он ни с кем не делился своими изысканиями." }, { 16.79, "Известно, что он записал результаты своих трудов." }, { 20.99, "Вырезал их на табличках." }, { 23.05, "И у меня есть основания предполагать, что одна из этих табличек хранится в Пике Чёрной горы, в зале, который когда-то назывался залом Удачи." }, { 34.95, "Как его называют сейчас, я не знаю, ибо многие уходили в Чёрную Скалу, но немногие вернулись назад." }, { 43.42, "Если тебя не пугают опасности Пика Чёрной горы, принеси мне табличку, и я щедро тебя награжу." } } }, t = { d = 18.6, g = 1, v = "scourge-female#80", n = { m = 166, f = 167 }, c = { m = { { 0.00, "Превосходно." }, { 1.19, "Для того чтобы разобраться со всеми формулами, мне потребуется не один день, но я уверена, что результат будет стоить затраченного труда." }, { 14.04, "Спасибо." }, { 14.89, "Ты оказал нам поистине неоценимую услугу." } }, f = { { 0.00, "Превосходно." }, { 1.17, "Для того чтобы разобраться со всеми формулами, мне потребуется не один день, но я уверена, что результат будет стоить затраченного труда." }, { 13.74, "Спасибо." }, { 14.57, "Ты оказала нам поистине неоценимую услугу." } } } } },
    [4769] = { d = 32.2, v = "scourge-female", n = { x = 301 }, c = { x = { { 0.00, "Вивиана Лягроб прислала мне весть из Каргата, что в Бесплодных землях." }, { 6.03, "Она выяснила, что в Пике Чёрной горы хранится один древний текст, который может помочь нам в изысканиях." }, { 15.10, "Однако это всего лишь догадка, требующая подтверждения." }, { 19.96, "Нужно, чтобы кто-то добыл этот текст из Пика." }, { 24.02, "Но сразу скажу: это будет непросто." }, { 27.23, "Если возьмёшься за эту работу, обратись к Вивиане в Каргат." } } }, t = { d = 24.6, g = 1, v = "scourge-female#80", n = { m = 230, f = 231 }, c = { m = { { 0.00, "Верно." }, { 0.63, "У меня есть основания предполагать, что в Пике Чёрной горы хранится табличка, на которой записаны древние алхимические рецептуры." }, { 11.85, "Я рада, что ты обратился ко мне, ибо мне нужна помощь." }, { 16.59, "Я должна получить эту табличку." }, { 19.43, "Садись и устраивайся поудобнее, я сейчас объясню, что к чему." } }, f = { { 0.00, "Верно." }, { 0.63, "У меня есть основания предполагать, что в Пике Чёрной горы хранится табличка, на которой записаны древние алхимические рецептуры." }, { 11.81, "Я рада, что ты обратилась ко мне, ибо мне нужна помощь." }, { 16.61, "Я должна получить эту табличку." }, { 19.45, "Садись и устраивайся поудобнее, я сейчас объясню, что к чему." } } } } },
    [4770] = { d = 37.1, g = 1, v = "tauren-male", n = { x = 392 }, c = { m = { { 0.00, "Пожалуйста, герой, помогите мне!" }, { 2.39, "Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица!" }, { 10.40, "Я пришёл сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился." }, { 19.48, "Мне срочно нужно вернуться на заставу Белого Плёса!" }, { 23.25, "Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвёт!" }, { 31.34, "Застава прямо к востоку отсюда... пожалуйста, проводите меня туда!" } }, f = { { 0.00, "Пожалуйста, героиня, помогите мне!" }, { 2.57, "Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица!" }, { 10.77, "Я пришёл сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился." }, { 20.06, "Мне срочно нужно вернуться на заставу Белого Плёса!" }, { 23.92, "Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвёт!" }, { 32.19, "Застава прямо к востоку отсюда... пожалуйста, проводите меня туда!" } } }, t = { d = 27.3, v = "tauren-male", n = { x = 269 }, c = { x = { { 0.00, "Что?!" }, { 0.44, "Да если б я знал, что Паока Ходячая Гора полезет в Скальное гнездовье, я бы цепями приковал его к тотему!" }, { 8.97, "Его отец был против того, чтобы он ехал со мной в Тысячу Игл." }, { 14.01, "Мы собирались изучать различных животных, населяющих эти прекрасные земли." }, { 20.06, "Я очень признателен вам за то, что вы помогли Паоке." }, { 24.22, "Надеюсь, это покроет все ваши затраты." } } } } },
    [4771] = { d = 31.3, g = 1, v = "gnome-female", n = { m = 335, f = 335 }, c = { m = { { 0.00, "Я поместила \"Рассветный гамбит\" в ящик, в котором были драконьи яйца." }, { 5.31, "Ты должен отнести его в самую глубину Некроситета." }, { 9.19, "Вектус, маг из нежити, руководит группой студентов Плети." }, { 13.55, "Доставь \"Рассветный гамбит\" в комнату, которую они называют смотровой." }, { 18.93, "Если всё пойдёт как надо, устройство уничтожит всю нежить, находящуюся в этот момент в комнате." }, { 26.08, "После этого уничтожить Вектуса будет проще пареной репы." }, { 30.51, "Так ведь?" } }, f = { { 0.00, "Я поместила \"Рассветный гамбит\" в ящик, в котором были драконьи яйца." }, { 5.35, "Ты должна отнести его в самую глубину Некроситета." }, { 9.26, "Вектус, маг из нежити, руководит группой студентов Плети." }, { 13.66, "Доставь \"Рассветный гамбит\" в комнату, которую они называют смотровой." }, { 19.08, "Если всё пойдёт как надо, устройство уничтожит всю нежить, находящуюся в этот момент в комнате." }, { 26.28, "После этого уничтожить Вектуса будет проще пареной репы." }, { 30.74, "Так ведь?" } } }, t = { d = 20.4, g = 1, v = "gnome-female", n = { m = 188, f = 189 }, c = { m = { { 0.00, "Какое счастье!" }, { 1.26, "Вектус уничтожен!" }, { 2.74, "А \"Рассветный гамбит\", он сработал?" }, { 5.62, "Хм... похоже, моё устройство оказалось не таким удачным, как я надеялась, но я рада, что ты всё равно справился." }, { 14.64, "Молодец!" }, { 15.38, "Серебряный Рассвет, да и весь Азерот у тебя в долгу." } }, f = { { 0.00, "Какое счастье!" }, { 1.31, "Вектус уничтожен!" }, { 2.85, "А \"Рассветный гамбит\", он сработал?" }, { 5.85, "Хм... похоже, моё устройство оказалось не таким удачным, как я надеялась, но я рада, что ты всё равно справилась." }, { 15.32, "Молодец!" }, { 16.09, "Серебряный Рассвет, да и весь Азерот у тебя в долгу." } } } } },
    [4781] = { d = 31.9, v = "human-female#47", n = { x = 389 }, c = { x = { { 0.00, "Следующее задание не сложнее первого, но тебе всё равно потребуется помощь." }, { 5.09, "Для вышивки мне нужна золотая нить, но её не так просто найти, и мало кто знает, как её делать." }, { 11.39, "К счастью, этот секрет ведом одному из тех, кто верен нашему делу и старается помогать тем, кто стремится пополнить наши ряды." }, { 19.94, "Отнеси золотой слиток Зиску Ладноскрою в Пиратскую бухту." }, { 23.88, "Он отличный портной и с радостью спрядёт для тебя нить." }, { 27.52, "Золотые слитки могут изготавливать опытные горняки." }, { 31.03, "Обратись к ним." } } }, t = { d = 29.5, g = 1, v = "goblin-male", n = { m = 310, f = 313 }, c = { m = { { 0.00, "Великолепно." }, { 0.96, "Я рад, что ты сумел так быстро заручиться помощью горняка." }, { 5.36, "Или ты сам справился?" }, { 7.01, "Так или иначе, молодчина." }, { 9.00, "Нить из этого слитка выйдет превосходная." }, { 12.16, "На её изготовление понадобится время, поэтому возвращайся немного позже – честно говоря, я послал слиток одной принцессе, запертой в башне, которая только и делает, что прядёт золотые нити... нет, честно." }, { 27.68, "Я не шучу... ладно, шучу." } }, f = { { 0.00, "Великолепно." }, { 0.91, "Я рад, что ты сумела так быстро заручиться помощью горняка." }, { 5.11, "Или ты сама справилась?" }, { 6.86, "Так или иначе, молодчина." }, { 8.74, "Нить из этого слитка выйдет превосходная." }, { 11.72, "На её изготовление понадобится время, поэтому возвращайся немного позже – честно говоря, я послал слиток одной принцессе, запертой в башне, которая только и делает, что прядёт золотые нити... нет, честно." }, { 26.35, "Я не шучу... ладно, шучу." } } } } },
    [4782] = { d = 25.2, v = "goblin-male", n = { x = 271 }, c = { x = { { 0.00, "Возвращайся к Менаре и скажи ей, что работа предстоит долгая, но я постараюсь ради неё... и ради тебя." }, { 7.58, "Передай ей, что пока ты собираешь остальные материалы, я закончу делать нить." }, { 13.28, "Тогда ты придёшь и заберёшь её." }, { 15.49, "Удачи." }, { 16.03, "Ах, да, передай привет Страхаду, раз уж будешь рядом." }, { 19.98, "Старый болван... как его угораздило построить башню рядом с Кабестаном?" } } }, t = { d = 17.7, g = 1, v = "human-female#47", n = { m = 169, f = 170 }, c = { m = { { 0.00, "Отлично, вот и ты." }, { 1.46, "А где же нитка?" }, { 2.70, "А, ясно." }, { 3.44, "Понятно." }, { 4.17, "Гоблин и его брат ни разу нас не подводили – думаю, вполне понятно, что он не смог сделать её сразу." }, { 12.21, "Да будет так..." }, { 13.45, "Тем временем мы займёмся другими материалами." }, { 17.03, "Ты готов?" } }, f = { { 0.00, "Отлично, вот и ты." }, { 1.42, "А где же нитка?" }, { 2.63, "А, ясно." }, { 3.34, "Понятно." }, { 4.06, "Гоблин и его брат ни разу нас не подводили – думаю, вполне понятно, что он не смог сделать её сразу." }, { 11.88, "Да будет так..." }, { 13.09, "Тем временем мы займёмся другими материалами." }, { 16.58, "Ты готова?" } } } } },
    [4783] = { d = 29.2, v = "human-female#47", n = { x = 358 }, c = { x = { { 0.00, "Следующие материалы можно найти в Пустошах, далеко на западе от Степей, за Когтистыми горами." }, { 6.42, "Там всё ещё царит хаос со времён Раскола." }, { 9.20, "Это место, где предстоит серьёзное испытание твоей силе и хитрости – там бродят омерзительные твари и приспешники Пылающего Легиона." }, { 18.22, "Принеси мне кровь сатиров племени Ярой Ненависти и простой камень Преисподней от младших инферналов Поля Маннорок." }, { 26.07, "И то, и другое понадобится для создания одеяния." } } }, t = { d = 9.8, g = 1, v = "human-female#47", n = { m = 103, f = 104 }, c = { m = { { 0.00, "Великолепно." }, { 1.01, "Отличные материалы." }, { 2.59, "Я пока подготовлю их, а тебе дам другое задание: принести два оставшихся ингредиента." }, { 9.34, "Готов?" } }, f = { { 0.00, "Великолепно." }, { 0.98, "Отличные материалы." }, { 2.53, "Я пока подготовлю их, а тебе дам другое задание: принести два оставшихся ингредиента." }, { 9.12, "Готова?" } } } } },
    [4784] = { d = 33.4, v = "human-female#47", n = { x = 387 }, c = { x = { { 0.00, "Осталось отыскать три составляющих, и твоё одеяние будет готово." }, { 4.50, "Во-первых, нить из чистого золота, которую делает Зиск." }, { 8.36, "Отправляйся к нему в Пиратскую бухту и принеси нить." }, { 12.03, "Во-вторых, принеси мне два тлеющих уголька от элементалей огня с нагорья Арати." }, { 17.61, "Если я правильно помню, духов можно найти в западной части нагорья, рядом со стеной Торадина." }, { 24.32, "И, наконец, мне нужен осколок души, созданный тобой." }, { 28.06, "Собрав все составляющие, возвращайся в башню, и я закончу работу над одеянием." } } }, t = { d = 6.6, g = 1, v = "human-female#47", n = { m = 67, f = 68 }, c = { m = { { 0.00, "Великолепно!" }, { 1.02, "Все материалы у меня есть, можно приступать." }, { 4.60, "Думаю, ты будешь доволен." } }, f = { { 0.00, "Великолепно!" }, { 1.00, "Все материалы у меня есть, можно приступать." }, { 4.49, "Думаю, ты будешь довольна." } } } } },
    [4785] = { t = { d = 13.4, v = "goblin-male", n = { x = 138 }, c = { x = { { 0.00, "Держи." }, { 0.57, "И передай Менаре от нас привет." }, { 3.04, "Мы ждём от тебя великих дел." }, { 5.24, "Может, когда Легион падёт на колени, твоё имя будут произносить вслух, восхваляя твою мощь." }, { 12.39, "Жду не дождусь!" } } } } },
    [4786] = { d = 6.0, v = "human-female#47", n = { x = 68 }, c = { x = { { 0.00, "А теперь я завершу работу над одеянием." }, { 2.88, "Это займёт немного времени." }, { 4.90, "Не уходи далеко." } } }, t = { d = 21.8, g = 1, v = "human-female#47", n = { m = 249, f = 251 }, c = { m = { { 0.00, "Готово." }, { 0.58, "Прими это одеяние и носи его с честью." }, { 3.46, "Ты хорошо поработал, и я предвижу, что тебя ждут великие дела." }, { 7.88, "Помни: чтобы справиться с искушением скверны, которое подстерегает каждого, ступившего на путь магии, понадобится сильная воля и немалая стойкость." }, { 18.33, "Пока ты не лишился воли, тебя ждут великие успехи." } }, f = { { 0.00, "Готово." }, { 0.56, "Прими это одеяние и носи его с честью." }, { 3.35, "Ты хорошо поработала, и я предвижу, что тебя ждут великие дела." }, { 7.70, "Помни: чтобы справиться с искушением скверны, которое подстерегает каждого, ступившего на путь магии, понадобится сильная воля и немалая стойкость." }, { 17.82, "Пока ты не лишилась воли, тебя ждут великие успехи." } } } } },
    [4787] = { d = 28.2, v = "troll-male#77", n = { x = 308 }, c = { x = { { 0.00, "В пророчестве Мошару говорится о древнем яйце." }, { 3.55, "Это реликвия тех времён, когда тролли правили громадными империями, и в нём заключена сила, которая сможет сдержать сущность Хаккара." }, { 13.64, "Пожалуй, это единственный способ избавить наш мир от зла." }, { 17.94, "Принеси мне древнее яйцо." }, { 19.92, "Говорят, оно спрятано в Джинта'Алоре, что во Внутренних землях, в пещере за амфитеатром в верхней части города." } } }, t = { d = 8.6, g = 1, v = "troll-male#77", n = { m = 64, f = 65 }, c = { m = { { 0.00, "А, ты добыл яйцо!" }, { 1.81, "Низкий тебе поклон." }, { 3.88, "Твоя сила и храбрость будут воспеты в веках." } }, f = { { 0.00, "А, ты добыла яйцо!" }, { 1.95, "Низкий тебе поклон." }, { 4.08, "Твоя сила и храбрость будут воспеты в веках." } } } } },
    [4788] = { d = 20.2, v = "dwarf-male", n = { x = 217 }, c = { x = { { 0.00, "Пока я изучаю третью и четвёртую таблички Мошару, отыщи пятую и шестую!" }, { 5.42, "Это будет нелегко, потому что они в руках троллей из клана Тлеющего Терновника на пике Чёрной горы." }, { 13.00, "Этот пик – огненная гора между Пылающими степями и Тлеющим ущельем." }, { 18.15, "Удачи." }, { 18.69, "Она тебе понадобится." } } }, t = { d = 12.7, g = 1, v = "dwarf-male", n = { m = 116, f = 118 }, c = { m = { { 0.00, "Невероятно!" }, { 1.01, "Ты их нашёл!" }, { 2.02, "Ты настоящий герой!" }, { 3.72, "И это очень удачно, потому что судя по предыдущим табличкам... без героя нам не обойтись." }, { 11.40, "Грядёт такое..." } }, f = { { 0.00, "Невероятно!" }, { 1.00, "Ты их нашла!" }, { 2.08, "Ты настоящая героиня!" }, { 3.93, "И это очень удачно, потому что судя по предыдущим табличкам... без героя нам не обойтись." }, { 11.57, "Грядёт такое..." } } } } },
    [4801] = { t = { d = 8.3, v = "troll-female#73", n = { x = 86 }, c = { x = { { 0.00, "Да, Мау'ари может добыть джуджу для тебя…" }, { 3.29, "Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках." } } } } },
    [4802] = { t = { d = 8.5, v = "troll-female#73", n = { x = 86 }, c = { x = { { 0.00, "Да, Мау'ари может добыть джуджу для тебя…" }, { 3.35, "Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках." } } } } },
    [4803] = { t = { d = 8.2, v = "troll-female#73", n = { x = 86 }, c = { x = { { 0.00, "Да, Мау'ари может добыть джуджу для тебя…" }, { 3.23, "Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках." } } } } },
    [4804] = { t = { d = 8.3, v = "troll-female#73", n = { x = 86 }, c = { x = { { 0.00, "Да, Мау'ари может добыть джуджу для тебя…" }, { 3.29, "Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках." } } } } },
    [4805] = { t = { d = 8.3, v = "troll-female#73", n = { x = 86 }, c = { x = { { 0.00, "Да, Мау'ари может добыть джуджу для тебя…" }, { 3.29, "Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках." } } } } },
    [4806] = { t = { d = 8.3, v = "troll-female#73", n = { x = 86 }, c = { x = { { 0.00, "Да, Мау'ари может добыть джуджу для тебя…" }, { 3.29, "Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках." } } } } },
    [4807] = { t = { d = 8.4, v = "troll-female#73", n = { x = 86 }, c = { x = { { 0.00, "Да, Мау'ари может добыть джуджу для тебя…" }, { 3.32, "Испробуй теперь Сокровище Мау'ари на себе или на своих союзниках." } } } } },
    [4808] = { d = 29.2, v = "goblin-female#63", n = { x = 334 }, c = { x = { { 0.00, "Мне придётся попросить тебя ещё об одной услуге." }, { 3.46, "В результате исследования добытых тобой сущностей, я поняла, как можно заморозить яйца драконов и сохранить их!" }, { 11.48, "Мне нужно испытать собственную теорию, но первым делом понадобятся кое-какие приспособления." }, { 18.19, "Мой коллега, Фелнок Сталлист, умеет их делать." }, { 21.59, "Отнеси это письмо Фелноку и объясни ему, что мне нужно." }, { 25.69, "Фелнок живёт в городе Круговзоре, в Зимних Ключах." } } }, t = { d = 19.4, v = "goblin-male", n = { x = 194 }, c = { x = { { 0.00, "Это не одеяло!" }, { 1.20, "Что это?" }, { 1.91, "Письмо от Тинки?" }, { 3.25, "И что она пишет?.." }, { 4.74, "А, она занимается исследованиями в Пылающих степях." }, { 8.77, "В этом есть смысл – драконов там полно." }, { 11.81, "Смотри-ка, ей нужны кое-какие детали для создания одного устройства." }, { 17.26, "Вот зачем я ей понадобился, а?" } } } } },
    [4809] = { d = 22.8, v = "goblin-male", n = { x = 250 }, c = { x = { { 0.00, "У меня есть почти всё, что нужно Тинки, не хватает только одного важного компонента – рогов стылодыхов." }, { 7.67, "Рога этих химер – великолепный источник стужи, но годятся только безупречные рога без единой трещинки!" }, { 15.34, "Чтобы выполнить заказ Тинки мне нужно несколько таких рогов." }, { 19.94, "Добудь их, и я соберу посылку для Тинки." } } }, t = { d = 8.9, v = "goblin-male", n = { x = 90 }, c = { x = { { 0.00, "Отличные рога." }, { 1.22, "Прямо средоточие холода!" }, { 3.23, "Дай-ка я надену перчатки и упакую их вместе с остальным заказом Тинки..." } } } } },
    [4810] = { d = 7.3, v = "goblin-male", n = { x = 73 }, c = { x = { { 0.00, "Ну вот, всё готово и запаковано!" }, { 2.53, "Доброго пути, не забудь передать Тинки, что она мой должник!" } } }, t = { d = 10.3, g = 1, v = "goblin-female#63", n = { m = 100, f = 104 }, c = { m = { { 0.00, "Принёс!" }, { 0.59, "Ура!" }, { 1.03, "Я немедленно примусь за работу!" }, { 3.61, "Огромное спасибо!" }, { 5.09, "Ты очень мне помог, может быть я снова прибегну к твоей помощи..." } }, f = { { 0.00, "Принесла!" }, { 0.77, "Ура!" }, { 1.19, "Я немедленно примусь за работу!" }, { 3.65, "Огромное спасибо!" }, { 5.05, "Ты очень мне помогла, может быть я снова прибегну к твоей помощи..." } } } } },
    [4811] = { d = 36.7, v = "nightelf-female#52", n = { x = 463 }, c = { x = { { 0.00, "К востоку отсюда становится всё больше враждебно настроенных лунных совухов." }, { 5.09, "Когда-то их считали милыми и спокойными, почти мистическими созданиями." }, { 9.81, "В то время как кое-кто продолжает почитать их, тревога о безопасности Аубердина вынуждает меня смотреть на вещи более реалистично." }, { 18.43, "Я получила сообщения, что лунных совухов привлекает большой красный кристалл, находящийся в горной гряде на востоке Тёмного Берега." }, { 27.11, "Никто не знает, что это за кристалл и есть ли он на самом деле." }, { 31.29, "Я хочу, чтобы вы установили его местонахождение и доложили мне о том, что обнаружите." } } }, t = { d = 28.2, v = "nightelf-female#52", n = { x = 331 }, c = { x = { { 0.00, "Так значит, кристалл существует?" }, { 2.23, "Как интересно..." }, { 3.34, "В любом случае, вы хорошо справились с заданием." }, { 6.68, "Отличная работа!" }, { 7.85, "А какова же природа этого кристалла?" }, { 10.39, "Это лишь один вопрос в целом море вопросов..." }, { 13.60, "На ум мне приходит и другой: почему лунных совухов тянет к кристаллу?" }, { 18.36, "Он безвреден, или же таит в себе зло?" }, { 20.96, "У меня ещё много вопросов, но нам придётся пристально изучить кристалл, чтобы добиться хоть каких-то ответов." } } } } },
    [4812] = { d = 30.2, v = "nightelf-female#52", n = { x = 378 }, c = { x = { { 0.00, "Возьмите этот пустой флакон и наполните его водой из лунного колодца в Аубердине." }, { 5.41, "Её могучая магия должна помочь нам разгадать структуру кристалла." }, { 9.71, "Чтобы это сделать, просто облейте кристалл, а остальное должно произойти само собой." }, { 15.36, "Хотя я не думаю, чтобы вам что-то угрожало, я всё же попрошу вас быть осторожнее." }, { 20.59, "За горами на востоке находится Осквернённый лес, и если этот кристалл как-то связан с тем местом (как я подозреваю), он может оказаться очень опасным." } } }, t = { d = 19.0, v = "narrator", n = { x = 217 }, c = { x = { { 0.00, "Вы снова добрались до таинственного кристалла." }, { 3.43, "Откупорив флакон с водой лунного колодца, вы аккуратно выливаете его содержимое на верхушку кристалла." }, { 11.11, "Пока вода струится по его граням, вы видите, как непроглядная поверхность кристалла становится прозрачной..." } } } } },
    [4813] = { d = 31.2, v = "narrator", n = { x = 336 }, c = { x = { { 0.00, "С помощью воды Лунного колодца выяснилось, что в кристалле заключено несколько мелких фрагментов костей, а также половина челюсти." }, { 10.01, "Кажется, челюсть принадлежала гуманоиду, но точно нельзя сказать, не разбив кристалл, – а это даже для самой мощной магии может оказаться почти непосильной задачей." }, { 22.72, "Задание выполнено, и всё, что вам остаётся, – это вернуться в Аубердин и доложить обо всём часовому Глинде Нал'Шии." } } }, t = { d = 27.0, v = "nightelf-female#52", n = { x = 336 }, c = { x = { { 0.00, "Да, похоже, что, хотя мы и знаем теперь о кристалле больше, в результате возникло множество новых вопросов." }, { 7.00, "Я пойду с добытой вами информацией в совет Аубердина." }, { 10.52, "Может быть, они подскажут, что делать дальше с этим кристаллом." }, { 14.70, "Если вообще есть о чём говорить – пока что угроза слишком далеко на востоке, чтобы принимать её всерьёз." }, { 21.46, "Что же касается вас, возьмите это." }, { 23.69, "Считайте это наградой за хорошо проделанную работу." } } } } },
    [4821] = { d = 36.1, v = "tauren-male#68", n = { x = 347 }, c = { x = { { 0.00, "Ходят слухи, что здесь, в Тысяче Игл, появилось яйцо какого-то странного существа." }, { 6.83, "Но те, кто видел его, не смогли подойти достаточно близко и рассмотреть яйцо поподробнее." }, { 14.25, "Его охраняют змеи, да так, словно это яйцо – их собственное!" }, { 19.36, "Я хочу, чтобы вы нашли его и принесли мне для изучения." }, { 24.01, "Говорят, что оно находится в логове змеев, но вообще-то таких гнёзд несколько, они разбросаны вдоль стен каньона к югу и северо-востоку от заставы." } } }, t = { d = 9.2, v = "tauren-male#68", n = { x = 67 }, c = { x = { { 0.00, "Наконец-то я получил это таинственное яйцо..." }, { 4.69, "Дайте-ка взглянуть на него..." }, { 7.72, "Что... что это?!" } } } } },
    [4822] = { d = 29.5, v = "child-male", n = { x = 334 }, c = { x = { { 0.00, "МОРОЖЕНОЕ!" }, { 0.78, "Пожалуйста, пожалуйста, пожалуйста, добудь для меня немного мороженого!!!" }, { 6.06, "Я больше всего люблю клубничное, а самое лучшее клубничное мороженое делают Тигуле и Форор!" }, { 12.78, "Это моё самое любимое мороженое на свете!" }, { 15.84, "Я пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе!" }, { 25.17, "Пожалуйста!" }, { 26.01, "Пожалуйста-препожалуйста!" }, { 27.77, "Преогромное пожалуйста!!!!" } } }, t = { d = 12.7, v = "child-male", n = { x = 122 }, c = { x = { { 0.00, "Ммммммммм!" }, { 0.83, "Обожаю их клубничное мороженое!" }, { 3.48, "Если Тигуле что-то и умеет, так это делать мороженое!" }, { 8.10, "Огромное спасибо, – это самое лучшее угощение на свете!" } } } } },
    [4841] = { d = 13.5, v = "tauren-male#67", n = { x = 130 }, c = { x = { { 0.00, "Я поручаю вам охоту на этих кентавров." }, { 3.29, "Отомстите им за нас как следует – вырежьте весь их лагерь к северу от Заставы Вольного Ветра." }, { 11.08, "Пусть рука ваша будет тверда!" } } }, t = { d = 3.4, v = "tauren-male#67", n = { x = 30 }, c = { x = { { 0.00, "Примите это в благодарность от меня." } } } } },
    [4842] = { d = 35.9, g = 1, v = "dwarf-female#34", n = { m = 362, f = 363 }, c = { m = { { 0.00, "По правде говоря, хотя в Зимних Ключах вулканов нет, я думаю, для возникновения этих горячих источников есть не менее опасные причины…" }, { 10.52, "Впрочем, наверное, ты сам захочешь всё увидеть." }, { 14.19, "Тебе нужно будет пересечь все Зимние Ключи, до самого юга этого края." }, { 19.84, "Там, где воздух станет плотным и удушливым, а небо потемнеет, ты как раз и найдёшь то, что я считаю причиной возникновения горячих ключей." }, { 30.43, "Сходи взглянуть." }, { 31.77, "Я уверена, ты вернёшься с кучей вопросов." } }, f = { { 0.00, "По правде говоря, хотя в Зимних Ключах вулканов нет, я думаю, для возникновения этих горячих источников есть не менее опасные причины…" }, { 10.81, "Впрочем, наверное, ты сама захочешь всё увидеть." }, { 14.73, "Тебе нужно будет пересечь все Зимние Ключи, до самого юга этого края." }, { 20.54, "Там, где воздух станет плотным и удушливым, а небо потемнеет, ты как раз и найдёшь то, что я считаю причиной возникновения горячих ключей." }, { 31.43, "Сходи взглянуть." }, { 32.81, "Я уверена, ты вернёшься с кучей вопросов." } } }, t = { d = 19.8, v = "dwarf-female#34", n = { x = 216 }, c = { x = { { 0.00, "Да, демоны добрались до Теснины Зловещего Шёпота." }, { 3.75, "Я уверена, мы наблюдаем следы их присутствия." }, { 7.22, "И я собираюсь и дальше наблюдать за горячими ключами, чтобы узнать о них больше." }, { 13.40, "Если соберёшься идти дальше в Теснину Зловещего Шёпота, советую сначала набраться сил." } } } } },
    [4861] = { d = 31.2, g = 1, v = "dwarf-male", n = { m = 347, f = 348 }, c = { m = { { 0.00, "Эй, послушай, паренёк!" }, { 1.52, "Меня какие-то кровожадные дикие совухи гнали всю дорогу из моего лагеря!" }, { 6.72, "Подозреваю, я слишком близко подобрался к разгадке того, что же они там охраняют." }, { 12.42, "Я еле ноги унёс оттуда." }, { 14.13, "Боюсь, мой коллега оказался менее везучим." }, { 17.17, "Ты как, не против того, чтобы бросить вызов диким совухам и отправиться в мой лагерь?" }, { 23.19, "Мне очень нужны мои припасы, а также я хотел бы вернуть амулет, который извлёк вчера во время раскопок." } }, f = { { 0.00, "Эй, послушай, девчушка!" }, { 1.65, "Меня какие-то кровожадные дикие совухи гнали всю дорогу из моего лагеря!" }, { 7.45, "Подозреваю, я слишком близко подобрался к разгадке того, что же они там охраняют." }, { 13.17, "Я еле ноги унёс оттуда." }, { 14.89, "Боюсь, мой коллега оказался менее везучим." }, { 17.94, "Ты как, не против того, чтобы бросить вызов диким совухам и отправиться в мой лагерь?" }, { 23.99, "Мне очень нужны мои припасы, а также я хотел бы вернуть амулет, который извлёк вчера во время раскопок." } } }, t = { d = 5.8, v = "narrator", n = { x = 62 }, c = { x = { { 0.00, "Среди разрушенных пожитков в лагере находится и сильно потрёпанный ящик." } } } } },
    [4862] = { d = 29.4, v = "goblin-male#65", n = { x = 304 }, c = { x = { { 0.00, "Верь – не верь, но есть народ, который готов отлично заплатить за необычную зверушку, причём чем она злее, тем лучше!" }, { 8.91, "Я послал на пик Чёрной горы Блестяшку, чтобы собрать паучьи яйца, но она уже несколько недель не возвращается." }, { 17.47, "Может, ты придёшь ей на выручку?" }, { 19.91, "Вот что." }, { 20.53, "Ступай-ка туда и принеси мне паучьи яйца." }, { 23.80, "Я тебе не только хорошо заплачу, но ещё и приручу для тебя одного паучка!" } } }, t = { d = 13.2, v = "goblin-male#65", n = { x = 121 }, c = { x = { { 0.00, "Какой урожай!" }, { 1.26, "Что за яйца!" }, { 2.37, "Они принесут мне несколько хорошеньких золотых монеток." }, { 7.27, "Как и обещано, вот тебе зверушка." }, { 10.20, "Смотри, чтобы она тебя не цапнула!" } } } } },
    [4863] = { d = 21.8, v = "narrator", n = { x = 231 }, c = { x = { { 0.00, "Вы озираетесь, но не видите ничего такого, что могло бы понадобиться Джерону." }, { 5.91, "Однако, заметно, что найденный вами ящик был вскрыт силой, как будто тут побывали дикие совухи..." }, { 13.42, "Взглянув на восток, вы замечаете покинутый фургон." }, { 17.32, "Стоит посмотреть не осталось ли там каких-то вещей Джерона." } } }, t = { d = 15.0, v = "narrator", n = { x = 162 }, c = { x = { { 0.00, "Подойдя к фургону, вы думаете о том, что едва ли внутри осталось что-то полезное для Джерона." }, { 7.18, "Однако, приглядевшись, вы замечаете в снегу возле фургона пару ящиков, которые выглядят неповреждёнными." } } } } },
    [4864] = { d = 22.6, v = "narrator", n = { x = 229 }, c = { x = { { 0.00, "Изучив содержимое ящика, вы решаете, что Джерону могут пригодиться лежащие там инструменты." }, { 7.28, "Однако среди них нет и следа амулета." }, { 10.31, "Похоже, дикие совухи обитают к северу и к востоку отсюда, и вы решаете, что ваш следующий шаг – встретить этих существ лицом к лицу и забрать у них амулет." } } }, t = { d = 23.1, g = 1, v = "dwarf-male", n = { m = 247, f = 248 }, c = { m = { { 0.00, "Ну, примерно это я и ожидал услышать, парень." }, { 3.28, "Я уж было думал, что свихнувшиеся звери раздраконили все мои пожитки…" }, { 8.23, "Но тебе удалось найти мои инструменты и, что ещё важнее, амулет!" }, { 12.87, "Интересно, почему дикосовухи так яростно его защищали…" }, { 17.09, "В любом случае, я теперь дважды подумаю, прежде чем сунуться к ним опять!" } }, f = { { 0.00, "Ну, примерно это я и ожидал услышать, девушка." }, { 3.42, "Я уж было думал, что свихнувшиеся звери раздраконили все мои пожитки…" }, { 8.48, "Но тебе удалось найти мои инструменты и, что ещё важнее, амулет!" }, { 13.22, "Интересно, почему дикосовухи так яростно его защищали…" }, { 17.23, "В любом случае, я теперь дважды подумаю, прежде чем сунуться к ним опять!" } } } } },
    [4865] = { d = 23.6, v = "tauren-male#68", n = { x = 241 }, c = { x = { { 0.00, "Если бы я не видел это собственными глазами, то ни за что бы не поверил!" }, { 6.32, "Месть обрушилась на Тысячу Игл!" }, { 8.96, "*Хагар утирает лоб.*" }, { 11.12, "Надо действовать быстро!" }, { 12.88, "Скорее, иди и поговори с Мотегой Огненной Гривой, он на заставе Белого Плёса, это к северо-западу отсюда, прямо возле дороги." }, { 21.73, "Он подскажет нам, что делать!" } } }, t = { d = 9.2, v = "tauren-male", n = { x = 75 }, c = { x = { { 0.00, "Отмщение!" }, { 1.01, "Значит, легенда об Арикаре не врёт!" }, { 4.59, "Да, эту проблему следует разрешить немедленно." } } } } },
    [4866] = { d = 33.9, v = "dwarf-male", n = { x = 364 }, c = { x = { { 0.00, "Должно быть, это один из сильнейших ядов на свете!" }, { 3.80, "В одной из вылазок на пик Чёрной горы, я слышал, как орки говорят о его смертоносности." }, { 10.21, "Они называют его \"материнское молоко\" в честь Дымной Паутины, огромной паучихи, поселившейся в одной из пещер Лабиринта." }, { 19.15, "Вот что мне нужно от тебя: образец молока в твоих собственных венах." }, { 24.22, "Мешочек с ядом не пойдёт!" }, { 26.09, "Дай ей отравить тебя, а потом возвращайся!" }, { 28.28, "А я тебя... подою!" }, { 30.55, "*Джон-Оборванец нетерпеливо потирает руки.*" } } }, t = { d = 9.0, g = 1, v = "dwarf-male", n = { m = 72, f = 73 }, c = { m = { { 0.00, "Из этого выйдет потрясный эль!" }, { 2.82, "А ты что думал?" }, { 4.23, "Что я сделаю яд или что-то такое?" }, { 7.06, "Ну, дети пошли..." } }, f = { { 0.00, "Из этого выйдет потрясный эль!" }, { 2.87, "А ты что думала?" }, { 4.39, "Что я сделаю яд или что-то такое?" }, { 7.30, "Ну, дети пошли..." } } } } },
    [4867] = { d = 10.4, v = "creature/furbolg", n = { x = 53 }, c = { x = { { 0.58, "Ар-рх!" }, { 1.24, "Трудно говорить!" }, { 3.02, "Возьми эту записку!" }, { 5.19, "Принеси мне мой амулет!" } } }, t = { d = 30.0, v = "creature/furbolg", n = { x = 261 }, c = { x = { { 0.58, "Я уже чувствую, как ко мне возвращаются силы!" }, { 4.26, "И проклятие Аррока уже не разрушает мой разум." }, { 8.08, "Спасибо!" }, { 8.82, "Я не люблю быть кому-то обязанным, но должен признать: ты мне очень помог." }, { 14.86, "Желаю удачи в походе на Пик Чёрной горы." }, { 18.17, "Это безрассудство, если ты думаешь, что сможешь дойти до вершины, хотя твоя смелость поистине не знает границ." } } } } },
    [4881] = { d = 17.6, v = "narrator", n = { x = 188 }, c = { x = { { 0.00, "Таурен по имени Канати Серое Облако собрался разбить в Тысяче Игл охотничий лагерь." }, { 6.67, "Мы должны убить его и опустошить лагерь, уничтожив всех его сторонников." }, { 12.43, "Собираемся на маленькой заставе к юго-западу от Великого подъёмника." } } }, t = { d = 7.0, v = "tauren-male#67", n = { x = 56 }, c = { x = { { 0.00, "Они хотят меня убить?" }, { 2.34, "Пусть приходят, я покажу им, как дерутся таурены!" } } } } },
    [4882] = { d = 22.6, v = "narrator", n = { x = 237 }, c = { x = { { 0.00, "Вы не можете понять, важна ли ваша находка – ожерелье, упавшее с шеи недавно убитого дикого совуха." }, { 7.73, "Оно источает яркий пульсирующий свет." }, { 10.63, "Может быть, Трулл Баловень Судьбы сможет что-то рассказать – похоже, он очень много знает о диких совухах." }, { 18.84, "Возможно, стоит его расспросить об этом ожерелье?" } } }, t = { d = 1.7, v = "orc-male#60", n = { x = 13 }, c = { x = { { 0.00, "Важная находка?" } } } } },
    [4883] = { d = 28.4, g = 1, v = "orc-male#60", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Хотя я располагаю некоторыми сведениями о совухах, с которыми ты боролся в Зимних Ключах, однако об их магии мне ничего не известно." }, { 10.58, "Но я знаю кое-кого, кто с удовольствием изучит это ожерелье и скорее всего сумеет рассказать тебе о его свойствах." }, { 19.93, "Нара Буйногривая из Громового Утёса настоящий эксперт в подобных вещах, тебе стоит поговорить с ней." }, { 27.97, "Удачи!" } }, f = { { 0.00, "Хотя я располагаю некоторыми сведениями о совухах, с которыми ты боролась в Зимних Ключах, однако об их магии мне ничего не известно." }, { 10.57, "Но я знаю кое-кого, кто с удовольствием изучит это ожерелье и скорее всего сумеет рассказать тебе о его свойствах." }, { 19.84, "Нара Буйногривая из Громового Утёса настоящий эксперт в подобных вещах, тебе стоит поговорить с ней." }, { 27.82, "Удачи!" } } }, t = { d = 37.5, g = 1, v = "tauren-female", n = { m = 353, f = 355 }, c = { m = { { 0.00, "Полагаю, у энергии этого ожерелья лишь один источник." }, { 5.28, "*Нара закрывает глаза и замолкает на мгновение.*" }, { 9.68, "Дикосовухи, обманутые и испуганные существа, не всегда были такими." }, { 15.21, "Они были созданы для того чтобы служить ночным эльфам." }, { 20.46, "Богиня ночных эльфов Элуна сотворила их, чтобы охранять священные места." }, { 26.50, "Конечно, это кажется неважным, однако я призываю тебя взглянуть глубже." }, { 32.47, "В своё время ты поймёшь." }, { 34.38, "Спасибо, что принёс мне это ожерелье." } }, f = { { 0.00, "Полагаю, у энергии этого ожерелья лишь один источник." }, { 5.68, "*Нара закрывает глаза и замолкает на мгновение.*" }, { 10.16, "Дикосовухи, обманутые и испуганные существа, не всегда были такими." }, { 15.56, "Они были созданы для того чтобы служить ночным эльфам." }, { 20.87, "Богиня ночных эльфов Элуна сотворила их, чтобы охранять священные места." }, { 26.77, "Конечно, это кажется неважным, однако я призываю тебя взглянуть глубже." }, { 32.60, "В своё время ты поймёшь." }, { 34.47, "Спасибо, что принесла мне это ожерелье." } } } } },
    [4901] = { d = 31.3, v = "nightelf-female#53", n = { x = 350 }, c = { x = { { 0.00, "На самой вершине гребня находится, как я полагаю, алтарь богини Элуны." }, { 5.16, "Насколько я знаю, нам нужно зажечь пять факелов – в каждой пещере, и тогда мы получим доступ к алтарю." }, { 12.61, "Я расшифровала заклинания, вырезанные на камне в древних руинах Кел'Терила, которые, как я думаю, являются ключом к активации алтаря." }, { 22.21, "Помогите мне зажечь факелы, пока я буду читать заклинание." }, { 26.53, "Если у нас всё получится, вы сможете доложить Эреласу о результатах!" } } }, t = { d = 2.0, v = "nightelf-male#55", n = { x = 20 }, c = { x = { { 0.00, "Вы виделись с Раншаллой?" } } } } },
    [4902] = { d = 24.9, v = "nightelf-male#55", n = { x = 292 }, c = { x = { { 0.00, "Это поразительно!" }, { 1.26, "Мне всегда было интересно, какова же истина…" }, { 4.40, "Что ж, вы просто обязаны поделиться этими сведениями!" }, { 8.11, "Сразу же отправляйтесь к верховному друиду Фэндралу Оленьему Шлему – вы найдёте его в Дарнассе, в Круге Кенария." }, { 15.91, "Расскажите ему подробно о случившемся – так же, как рассказали мне." }, { 20.50, "Я уверен, что ему будет очень интересно!" }, { 23.39, "Это важная информация!" } } }, t = { d = 37.8, v = "named/3516", n = { x = 365 }, c = { x = { { 0.00, "Не ходите вокруг да около, рассказывайте, с чем пришли." }, { 4.30, "Ах, вот как?" }, { 5.21, "Хмм…" }, { 5.56, "Ясно." }, { 6.06, "Спасибо, что сразу пришли с этим ко мне; докладывать всё на самый верх – самое правильное…" }, { 13.03, "Но…" }, { 13.31, "Да." }, { 13.59, "Друиды Круга Кенария знают о дикосовухах уже довольно давно." }, { 19.00, "О том, что они – питомцы Элуны и были избраны охранять наиболее священные места." }, { 26.17, "В общем, хоть это для нас и не новость, я, безусловно, признателен вам за ваши усилия." }, { 32.79, "Вот, возьмите это – думаю, это подходящая награда за ваши труды." } } } } },
    [4903] = { d = 30.2, v = "orc-male#60", n = { x = 280 }, c = { x = { { 0.00, "По приказу полководца Клинозуба следующие жители Пика Чёрной горы подлежат уничтожению:" }, { 7.97, "Особо опасный преступник вождь Омокк." }, { 11.42, "Жестокий и беспощадный тролль воевода Вун." }, { 15.20, "Повелитель Змейталак, десятник в малом городе." }, { 19.47, "Также необходимо доставить в штаб все найденные при них документы." }, { 25.39, "Успех – слава и награда." }, { 27.69, "Поражение – позор и забвенье." } } }, t = { d = 5.2, v = "orc-male#60", n = { x = 60 }, c = { x = { { 0.00, "*Зелёные щёки полководца на минуту покрываются мертвенной бледностью.*" } } } } },
    [4904] = { d = 25.5, v = "tauren-female#72", n = { x = 256 }, c = { x = { { 0.00, "Арнак хотел жениться на мне, и поэтому похитил меня, когда я отвергла его предложение." }, { 6.80, "Мой брат пытался остановить его, но Арнак оказался сильнее." }, { 11.43, "Он... он убил моего брата и привёл меня сюда." }, { 15.01, "Мой бедный брат..." }, { 16.41, "Не могли бы вы вывести меня с Пика Тёмного Облака?" }, { 20.34, "Я хочу назад, к Талье!" }, { 22.16, "Она, наверное, с ума сходит от беспокойства." } } }, t = { d = 19.3, v = "tauren-female#71", n = { x = 184 }, c = { x = { { 0.00, "Спасибо." }, { 0.76, "В глубине души я всегда верила, что она найдёт способ вернуться ко мне." }, { 6.76, "Она рассказала мне о вашей храбрости и о том, как вы помогли ей сбежать." }, { 12.75, "Эти вещи принадлежали её брату." }, { 15.49, "Уверена, она бы сама непременно отдала их вам." } } } } },
    [4906] = { d = 31.1, v = "nightelf-female", n = { x = 393 }, c = { x = { { 0.00, "Другой лагерь сатиров угрожает северной части Осквернённого леса." }, { 4.44, "Тамошними сатирами предводительствует жестокий Ксаварик." }, { 8.21, "Эти подлые предатели и обманщики радуются, поражая порчей тварей Осквернённого леса." }, { 13.93, "Ксаватрас и его приспешники – только часть большого плана по созданию осквернённого лунного колодца." }, { 20.62, "А затем всем этим воспользуется Ксаварик." }, { 23.42, "Теперь, когда Ксаватрас уже не мешается у нас под ногами, заверши это дело." }, { 28.58, "Отправляйся на север и срази Ксаварика." } } }, t = { d = 6.3, g = 1, v = "nightelf-female", n = { m = 63, f = 64 }, c = { m = { { 0.00, "Спасибо за всё, что ты сделал." }, { 2.37, "Да защитит тебя Элуна, и да направит она твой путь." } }, f = { { 0.00, "Спасибо за всё, что ты сделала." }, { 2.39, "Да защитит тебя Элуна, и да направит она твой путь." } } } } },
    [4907] = { d = 17.7, v = "goblin-male", n = { x = 199 }, c = { x = { { 0.00, "Привет." }, { 0.57, "Помнишь Тинки Кипеллер?" }, { 2.29, "Она-то тебя помнит!" }, { 3.76, "Она послала мне весточку, чтобы я передал тебе при случае." }, { 7.96, "Ей снова нужна твоя помощь." }, { 9.99, "Кажется, это опять связано с изучением драконов." }, { 13.50, "Ступай в Пылающие степи, в Пламенеющий Стяг, и поговори с ней." } } }, t = { d = 8.1, g = 1, v = "goblin-female#63", n = { m = 72, f = 73 }, c = { m = { { 0.00, "Фелнок не ошибся!" }, { 1.55, "Мне снова нужна твоя помощь, и на сей раз... задание будет опасным." }, { 7.38, "Ты готов?" } }, f = { { 0.00, "Фелнок не ошибся!" }, { 1.54, "Мне снова нужна твоя помощь, и на сей раз... задание будет опасным." }, { 7.31, "Ты готова?" } } } } },
    [4921] = { d = 34.8, g = 1, v = "orc-male#60", n = { x = 344 }, c = { m = { { 0.00, "Мы бились в маленьком лагере тауренов и разделились в бою – на неё наседали разом три иглогрива Вздыбленной Щетины." }, { 8.82, "Силы были неравны." }, { 10.35, "Я отвлёк на себя очень многих и увидел, что набежали новые враги и одолевают её." }, { 16.54, "Впав в ярость, я бросился на врагов, но они с лёгкостью одержали надо мной верх." }, { 22.58, "Я пришёл в себя и увидел, что таурен-друид ухаживает за мной, – он набрёл на меня на Золотом пути." }, { 30.02, "Прошу тебя, герой, узнай что-нибудь о моей жене." } }, f = { { 0.00, "Мы бились в маленьком лагере тауренов и разделились в бою – на неё наседали разом три иглогрива Вздыбленной Щетины." }, { 9.06, "Силы были неравны." }, { 10.63, "Я отвлёк на себя очень многих и увидел, что набежали новые враги и одолевают её." }, { 16.98, "Впав в ярость, я бросился на врагов, но они с лёгкостью одержали надо мной верх." }, { 23.18, "Я пришёл в себя и увидел, что таурен-друид ухаживает за мной, – он набрёл на меня на Золотом пути." }, { 30.81, "Прошу тебя, героиня, узнай что-нибудь о моей жене." } } }, t = { d = 3.0, g = 1, v = "orc-male#60", n = { x = 14 }, c = { m = { { 0.00, "Понятно." }, { 0.98, "Спасибо, герой." } }, f = { { 0.00, "Понятно." }, { 1.08, "Спасибо, героиня." } } } } },
    [4941] = { d = 27.0, v = "orc-male#60", n = { x = 295 }, c = { x = { { 0.00, "Ренд жив?" }, { 0.92, "Быть того не может!" }, { 2.39, "Я думал, он погиб несколько десятков лет назад." }, { 5.93, "Тебе нужно обратиться за советом к Эйтриггу!" }, { 9.26, "Никто не знает о Чёрной горе больше него, и если то, что написано здесь, правда, Эйтриггу стоит об этом знать." }, { 17.41, "Никому нельзя отказывать в праве на месть." }, { 20.55, "Эйтригга ты найдёшь в Оргриммаре." }, { 22.95, "Когда поговоришь с Эйтриггом, ступай к вождю за указаниями." } } }, t = { d = 3.5, v = "named/thrall", n = { x = 37 }, c = { x = { { 0.00, "*Тралл, похоже, весьма встревожен услышанным.*" } } } } },
    [4961] = { d = 32.9, v = "human-female#45", n = { x = 374 }, c = { x = { { 0.00, "А, сфера призывателя – так вот откуда исходит искажение." }, { 3.98, "Если ты хочешь ей пользоваться, придётся изгнать из неё демона." }, { 8.40, "С этим я легко справлюсь." }, { 10.26, "Тебе придётся куда труднее." }, { 12.25, "Как только демон выйдет из сферы, убей его." }, { 15.45, "И спеши." }, { 16.10, "Если ты будешь возиться слишком долго, он вернётся в сферу, и нам придётся начать сначала!" }, { 22.44, "Подготовься к схватке." }, { 24.05, "Вспомни самые сильные заклинания и держи под рукой зелья." }, { 28.21, "Если у тебя есть друг, можешь позвать его." }, { 31.29, "Сражение будет нелёгким." } } }, t = { d = 19.0, g = 1, v = "human-female#45", n = { x = 211 }, c = { m = { { 0.00, "Великолепно!" }, { 0.89, "Тебе удалось преподать этому демону урок, который он надолго запомнит." }, { 5.97, "Могущества и умения тебе не занимать." }, { 8.63, "Полагаю, пришло время вернуться к Менаре с очищенным шаром и найти ему доброе применение." }, { 15.04, "Удачи, герой." }, { 16.05, "Быть может, наши пути ещё пересекутся." } }, f = { { 0.00, "Великолепно!" }, { 0.90, "Тебе удалось преподать этому демону урок, который он надолго запомнит." }, { 6.05, "Могущества и умения тебе не занимать." }, { 8.76, "Полагаю, пришло время вернуться к Менаре с очищенным шаром и найти ему доброе применение." }, { 15.26, "Удачи, героиня." }, { 16.42, "Быть может, наши пути ещё пересекутся." } } } } },
    [4962] = { d = 31.0, g = 1, v = "scourge-female#79", n = { m = 299, f = 300 }, c = { m = { { 0.00, "Итак, ты выбрал гончую скверны." }, { 2.64, "Отлично." }, { 3.37, "Возьми этот рубин, он позволит подчинить её душу." }, { 7.48, "Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он всё сделает за тебя." }, { 15.91, "Советую отправиться в Пустоши и попробовать подчинить одну из тамошних гончих скверны." }, { 22.94, "Они отлично подойдут." }, { 24.78, "Когда добьёшься успеха, отнеси пленённого духа и рубин Менаре." } }, f = { { 0.00, "Итак, ты выбрала гончую скверны." }, { 2.82, "Отлично." }, { 3.58, "Возьми этот рубин, он позволит подчинить её душу." }, { 7.86, "Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он всё сделает за тебя." }, { 16.63, "Советую отправиться в Пустоши и попробовать подчинить одну из тамошних гончих скверны." }, { 23.95, "Они отлично подойдут." }, { 25.85, "Когда добьёшься успеха, отнеси пленённого духа и рубин Менаре." } } }, t = { d = 9.5, v = "human-female#47", n = { x = 88 }, c = { x = { { 0.00, "А, дух гончей скверны." }, { 1.89, "Молодец." }, { 2.65, "Когда у меня будет и дух, и очищенная сфера, я смогу слить их воедино, но не раньше." } } } } },
    [4963] = { d = 28.2, g = 1, v = "orc-female#58", n = { m = 291, f = 292 }, c = { m = { { 0.00, "Итак, ты выбрал инфернала." }, { 2.08, "Отлично." }, { 2.77, "Возьми этот изумруд, он позволит подчинить его душу." }, { 6.92, "Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он всё сделает за тебя." }, { 14.88, "Советую отправиться в Пустоши и попробовать подчинить одного из инферналов." }, { 20.62, "Они отлично подойдут." }, { 22.36, "Когда добьёшься успеха, отнеси пленённого духа и изумруд Менаре." } }, f = { { 0.00, "Итак, ты выбрала инфернала." }, { 2.22, "Отлично." }, { 2.94, "Возьми этот изумруд, он позволит подчинить его душу." }, { 7.24, "Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он всё сделает за тебя." }, { 15.48, "Советую отправиться в Пустоши и попробовать подчинить одного из инферналов." }, { 21.43, "Они отлично подойдут." }, { 23.22, "Когда добьёшься успеха, отнеси пленённого духа и изумруд Менаре." } } }, t = { d = 10.8, v = "human-female#47", n = { x = 104 }, c = { x = { { 0.00, "Аа, дух инфернала..." }, { 1.69, "Прекрасно сработано." }, { 3.38, "Когда у меня будут и дух, и очищенное сферическое ядро, я объединю их для тебя." }, { 9.85, "Но не раньше." } } } } },
    [4964] = { d = 17.6, v = "human-female#47", n = { x = 213 }, c = { x = { { 0.00, "Я немедленно займусь твоим шаром." }, { 2.27, "Надо вселить в него нового демона." }, { 4.66, "После этого ты сможешь выбрать, в каком виде его получить: посоха или сферы." }, { 9.92, "Я всегда считала, что соответствие избранному оружию чернокнижника – это главное..." }, { 15.41, "Не вижу причин менять своё мнение." } } }, t = { d = 22.6, v = "human-female#47", n = { x = 258 }, c = { x = { { 0.00, "Готово." }, { 0.58, "А теперь скажи, что ты предпочитаешь: посох, который займёт обе руки, или шар, который позволит тебе пользоваться кинжалом или мечом." }, { 10.14, "Победить гончую Скверны – великий подвиг." }, { 13.16, "Нет сомнений, что этот предмет славно послужит тебе в будущем." }, { 17.65, "Прилежно изучай тайные искусства." }, { 20.09, "Я буду ждать вестей о твоих подвигах." } } } } },
    [4965] = { d = 25.8, g = 1, v = "gnome-male", n = { m = 294, f = 295 }, c = { m = { { 0.00, "Так-так-так… приятно видеть, как ты набираешься могущества." }, { 4.09, "Мне кажется, ты готов поговорить с Менарой Расщепительницей Бездны в Степях." }, { 9.37, "Если вы раньше не встречались, то, поверь мне, другого такого специалиста по созданию предметов – особенно сфер, в которые можно заключить демона – не найти." }, { 20.26, "Интересно?" }, { 21.01, "Тогда поищи её." }, { 22.15, "Она живёт в башне Страхада над Кабестаном." } }, f = { { 0.00, "Так-так-так… приятно видеть, как ты набираешься могущества." }, { 4.22, "Мне кажется, ты готова поговорить с Менарой Расщепительницей Бездны в Степях." }, { 9.74, "Если вы раньше не встречались, то, поверь мне, другого такого специалиста по созданию предметов – особенно сфер, в которые можно заключить демона – не найти." }, { 20.98, "Интересно?" }, { 21.76, "Тогда поищи её." }, { 22.93, "Она живёт в башне Страхада над Кабестаном." } } }, t = { d = 13.3, g = 1, v = "human-female#47", n = { m = 130, f = 131 }, c = { m = { { 0.00, "А, ты ищешь чего-то более... вещественного." }, { 3.29, "Я помогу тебе, если хочешь." }, { 5.48, "Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям." }, { 10.95, "Итак, думаешь, ты готов?" } }, f = { { 0.00, "А, ты ищешь чего-то более... вещественного." }, { 3.41, "Я помогу тебе, если хочешь." }, { 5.69, "Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям." }, { 11.37, "Итак, думаешь, ты готова?" } } } } },
