    [4969] = { d = 33.0, g = 1, v = "orc-male", n = { m = 325, f = 326 }, c = { m = { { 0.00, "Ха-ха!" }, { 0.59, "Ты растёшь над собой, юный герой." }, { 3.31, "Со временем инферналы и повелители ужаса склонятся перед тобой!" }, { 8.53, "Пока же тебе приходится полагаться на оружие, скованное руками смертных." }, { 14.49, "Похоже, ты готов создать ещё одно." }, { 17.36, "Если хочешь, с тобой может поговорить Менара Расщепительница Бездны!" }, { 23.02, "Она живёт неподалёку от башни Страхада над портовым городом Кабестан." }, { 28.61, "Отправляйся туда, как решишь, что время уже пришло." } }, f = { { 0.00, "Ха-ха!" }, { 0.59, "Ты растёшь над собой, юная героиня." }, { 3.46, "Со временем инферналы и повелители ужаса склонятся перед тобой!" }, { 8.68, "Пока же тебе приходится полагаться на оружие, скованное руками смертных." }, { 14.64, "Похоже, ты готова создать ещё одно." }, { 17.59, "Если хочешь, с тобой может поговорить Менара Расщепительница Бездны!" }, { 23.25, "Она живёт неподалёку от башни Страхада над портовым городом Кабестан." }, { 28.85, "Отправляйся туда, как решишь, что время уже пришло." } } }, t = { d = 12.9, g = 1, v = "human-female#47", n = { m = 130, f = 131 }, c = { m = { { 0.00, "А, ты ищешь чего-то более... вещественного." }, { 3.33, "Я помогу тебе, если хочешь." }, { 5.54, "Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям." }, { 11.09, "Итак, думаешь, ты готов?" } }, f = { { 0.00, "А, ты ищешь чего-то более... вещественного." }, { 3.31, "Я помогу тебе, если хочешь." }, { 5.51, "Приятно видеть, что не все наши сородичи стремятся к одним лишь знаниям." }, { 11.03, "Итак, думаешь, ты готова?" } } } } },
    [4970] = { d = 15.0, v = "nightelf-male#55", n = { x = 173 }, c = { x = { { 0.00, "Если хотите достойно проявить себя, начните с простого, но очень важного дела." }, { 5.72, "Добудьте в окрестностях мясо химер и медведей-щербозубов." }, { 9.83, "Принесите его мне, чтобы я мог кормить им ледопардов, которых я дрессирую." } } }, t = { d = 5.7, v = "nightelf-male#55", n = { x = 56 }, c = { x = { { 0.00, "Спасибо за помощь." }, { 1.61, "Моё мнение о вас со временем становится всё лучше." } } } } },
    [4971] = { d = 32.0, v = "creature/chromie", n = { x = 374 }, c = { x = { { 0.00, "Кто-то вмешался в ход времени в Андорале!" }, { 2.98, "Скорее всего, это дело рук Плети." }, { 5.50, "Я могу попытаться сохранить неизменным ход времени здесь и исправить повреждения, но мне не должны мешать." }, { 13.00, "В этом ты мне и поможешь." }, { 14.81, "Амбары Андорала заполонили временные паразиты, падальщики, питающиеся обрывками потока времени." }, { 21.67, "Их можно обнаружить только по синему сиянию." }, { 24.90, "Они очень мешают мне." }, { 26.52, "Пожалуйста, искорени этих паразитов, воспользовавшись временным переместителем." } } }, t = { d = 30.2, v = "creature/chromie", n = { x = 355 }, c = { x = { { 0.00, "Мне стало много легче исправлять ход времени." }, { 3.22, "Спасибо." }, { 3.85, "Хотя тебе непросто понять все опасности нарушения естественного хода событий, я рада, что ты осознаёшь важность противостояния Плети, а я почти уверена, что это дело её рук." }, { 15.92, "Почему бы не вознаградить тебя за помощь, смертный." }, { 19.52, "Тебя ждут величайшие подвиги, и одна безделушка не заставит тебя свернуть с избранного пути." }, { 26.02, "Хотя нам с драконами не помешает твоя помощь и в дальнейшем..." } } } } },
    [4972] = { d = 32.3, v = "creature/chromie", n = { x = 390 }, c = { x = { { 0.00, "Мне нужно отправить тебя в мир за пределами этой комнаты." }, { 4.01, "Сейчас всё объясню." }, { 5.39, "Видишь, как эта комната отличается от остального Андорала?" }, { 9.46, "Мои драконы существуют во многих пластах реальности и времени." }, { 13.85, "Чтобы исправить ущерб, нанесённый Андоралу, я действую из другого временного пласта, чтобы не загрязнить его сверх меры." }, { 22.18, "Для продолжения работ мне необходимы особые устройства, оставшиеся со времён прихода чумы." }, { 28.39, "Они находятся в сундуках в руинах некогда гордого города." } } }, t = { d = 20.0, v = "creature/chromie", n = { x = 210 }, c = { x = { { 0.00, "Вот, как раз то, что нужно." }, { 1.96, "Спасибо." }, { 2.64, "Позволь вознаградить тебя." }, { 4.67, "Быть может, ты не понимаешь, зачем тебе такое устройство." }, { 8.99, "И даже для чего оно; довольно знать, что в будущем этот предмет тебе очень пригодится." }, { 15.55, "А сохранишь ты его до тех времён или нет... дело твоё, дружок." } } } } },
    [4973] = { d = 20.3, g = 1, v = "creature/chromie", n = { m = 232, f = 233 }, c = { m = { { 0.00, "Если ты готов ещё раз оказать мне помощь, я попрошу тебя принести ещё пять часов из руин Андорала." }, { 7.04, "Это очень поможет мне на равных бороться со злобной силой, пытающейся изменить ход времени." }, { 13.62, "Взамен часов ты получишь ещё один дар, который, мне кажется, здорово пригодится тебе в будущем." } }, f = { { 0.00, "Если ты готова ещё раз оказать мне помощь, я попрошу тебя принести ещё пять часов из руин Андорала." }, { 6.97, "Это очень поможет мне на равных бороться со злобной силой, пытающейся изменить ход времени." }, { 13.43, "Взамен часов ты получишь ещё один дар, который, мне кажется, здорово пригодится тебе в будущем." } } }, t = { d = 13.0, v = "creature/chromie", n = { x = 136 }, c = { x = { { 0.00, "И снова я благодарю тебя за помощь." }, { 2.72, "Прими этот дар." }, { 3.94, "Сейчас тебе невдомёк, для чего он, но, быть может, ты ещё узнаешь его истинную ценность." }, { 10.54, "Можно сказать, что я предвижу это." } } } } },
    [4974] = { d = 34.4, v = "named/thrall", n = { x = 337 }, c = { x = { { 0.00, "Ренд осмеливается делать подобные заявления, потому что он пользуется поддержкой чёрных драконов." }, { 8.09, "Ты, проникнешь в Залы Вознесения, найдёшь там \"вождя\" Ренда Чернорука и уничтожишь его – ВО ИМЯ ОРДЫ!!!" }, { 16.72, "*Тралл ударяет кулаком по своему трону.*" }, { 19.92, "В следующий раз, как я увижу тебя в своих покоях, ты торжествующе поднимешь ввысь его отрубленную голову и вручишь её своему вождю." }, { 30.69, "Выполни это – и станешь одним из героев Орды!" } } }, t = { d = 16.9, v = "named/thrall", n = { x = 162 }, c = { x = { { 0.00, "Тебе удалось нанести силам Чёрной горы сокрушительный удар!" }, { 5.29, "Теперь, когда их вождь убит, воинство Чёрной горы снова ввергнуто в хаос." }, { 11.75, "Наградой за твой героизм будет процветание народа Калимдора!" } } } } },
    [4975] = { d = 18.2, v = "human-female#47", n = { x = 213 }, c = { x = { { 0.00, "Я немедленно займусь твоим шаром." }, { 2.34, "Надо вселить в него нового демона." }, { 4.81, "После этого ты сможешь выбрать, в каком виде его получить: посоха или сферы." }, { 10.23, "Я всегда считала, что соответствие избранному оружию чернокнижника – это главное..." }, { 15.90, "Не вижу причин менять своё мнение." } } }, t = { d = 20.0, v = "human-female#47", n = { x = 251 }, c = { x = { { 0.00, "Готово." }, { 0.53, "Просто скажи, что же ты предпочитаешь – посох, который занимает обе руки, или сферу, с которой ты можешь использовать кинжал или что-то ещё в своей правой руке." }, { 11.03, "Победить инфернала – великий подвиг, и эта награда тебе прекрасно подойдёт." }, { 15.94, "Желаю тебе всяческих успехов в совершенствовании твоих искусств." } } } } },
    [4976] = { d = 17.3, v = "human-female#45", n = { x = 199 }, c = { x = { { 0.00, "Теперь, когда демон изгнан, ты можешь отнести шар Менаре в Кабестан." }, { 4.90, "Передай ей от меня привет, и береги себя." }, { 7.89, "Надеюсь, что тебе удастся противостоять искушениям порчи, которые, несомненно, будут подстерегать тебя на избранном пути." }, { 16.47, "Желаю удачи." } } }, t = { d = 11.0, v = "human-female#47", n = { x = 113 }, c = { x = { { 0.00, "Отлично." }, { 0.70, "Подходящая сфера." }, { 2.08, "Осталось одно – решить, какого демона следует заключить в неё." }, { 6.95, "Решишь – считай, новый предмет силы у тебя в кармане." } } } } },
    [4981] = { d = 35.8, v = "orc-male", n = { x = 400 }, c = { x = { { 0.00, "Никогда нельзя верить гоблинам!" }, { 2.38, "Рано или поздно все приходят к этому выводу." }, { 5.74, "Её зовут Блестяшка, она была одним из лучших наших агентов." }, { 10.23, "Потом оказалось, что стерва вела двойную игру – работала на какого-то типа по имени Киблер, нелегально торгующего экзотическими животными в Пылающих степях, и использовала средства Орды для финансирования своих махинаций!" }, { 26.40, "Она должна быть доставлена ко мне живой." }, { 29.37, "Последний раз её видели у Пика Чёрной горы." }, { 32.54, "И смотри, чтобы она не заговорила тебе зубы!" } } }, t = { d = 38.6, g = 1, v = "goblin-female#63", n = { x = 427 }, c = { m = { { 0.00, "Я не буду лгать тебе, герой." }, { 2.07, "Мне были нужны деньги!" }, { 3.76, "Киблер хорошо платит – куда больше, чем в Каргатском экспедиционном корпусе в лучшие его годы." }, { 10.62, "Но можешь не сомневаться, я верна присяге!" }, { 13.67, "Думаешь, зачем я здесь?" }, { 15.35, "Чтобы таскать этому придурку-гоблину яйца экзотических зверушек или ещё для каких глупостей?" }, { 22.09, "Нужно быть очень крупным идиотом, чтобы явиться в пик Чёрной горы отлавливать зверьё!" }, { 28.18, "Не думаю, что на свете много таких сумасшедших." }, { 31.61, "Вот что я тебе скажу, такие просто не должны размножаться, да-да!" } }, f = { { 0.00, "Я не буду лгать тебе, героиня." }, { 2.26, "Мне были нужны деньги!" }, { 3.99, "Киблер хорошо платит – куда больше, чем в Каргатском экспедиционном корпусе в лучшие его годы." }, { 11.04, "Но можешь не сомневаться, я верна присяге!" }, { 14.16, "Думаешь, зачем я здесь?" }, { 15.89, "Чтобы таскать этому придурку-гоблину яйца экзотических зверушек или ещё для каких глупостей?" }, { 22.80, "Нужно быть очень крупным идиотом, чтобы явиться в пик Чёрной горы отлавливать зверьё!" }, { 29.05, "Не думаю, что на свете много таких сумасшедших." }, { 32.58, "Вот что я тебе скажу, такие просто не должны размножаться, да-да!" } } } } },
    [4982] = { d = 44.7, v = "goblin-female#63", n = { x = 510 }, c = { x = { { 0.00, "По ночам, когда городская стража не особенно ревностно исполняет свои обязанности, я незаметно брожу по улицам и беру на заметку всё, что может иметь хоть какую-то ценность для стратегических планов Ка-Э-Ка." }, { 14.80, "Всё подмечаю и всё записываю." }, { 16.87, "Но вчера ночью случился прокол." }, { 19.20, "В темноте я запнулась о натянутую верёвку, и включился сигнал тревоги." }, { 24.18, "Пришлось срочно прятать все оборудование для разведки и мчаться в укрытие." }, { 29.48, "И что самое ужасное, сейчас мне уже не удастся забрать свои вещи из тайника." }, { 35.04, "В городе ввели усиленный режим патрулирования!" }, { 38.40, "Вся информация утрачена." }, { 40.15, "Разыщи мои вещи, верни их мне, и я тихо-мирно вернусь в Ка-Э-Ка." } } }, t = { d = 12.8, v = "goblin-female#63", n = { x = 127 }, c = { x = { { 0.00, "Ой, молодчина!" }, { 1.16, "Когда я передам Лекслорту эти планы, он позабудет обо всех страшных угрозах в мой адрес и уж точно не станет спускать с меня шкуру." }, { 11.86, "Ты мой герой!" } } } } },
    [4983] = { d = 24.1, v = "goblin-female#63", n = { x = 273 }, c = { x = { { 0.00, "Передай этот рапорт Лекслорту." }, { 2.27, "Теперь я верну себе доброе имя, потому что моё донесение, безусловно, сослужит хорошую службу Ка-Э-Ка и даст им значительное стратегическое преимущество в борьбе с этими орками." }, { 14.96, "Пойти с тобой, говоришь?" }, { 16.78, "У меня много работы, недосуг мне носиться туда-сюда." }, { 20.66, "Беги, донесение надо доставить как можно скорее!" } } }, t = { d = 20.6, v = "orc-male", n = { x = 206 }, c = { x = { { 0.00, "Всё-таки надо отдать ей должное, хитрая бестия снова сумела выкрутиться!" }, { 6.10, "Её донесение содержит бесценную информацию, которая очень поможет в наших делах с орками Чёрной Горы." }, { 14.61, "Разумеется, ты не останешься без награды." }, { 18.00, "Всякий труд должен быть оплачен." } } } } },
    [4984] = { d = 31.6, v = "tauren-male", n = { x = 284 }, c = { x = { { 0.00, "Хотя бороться с Плетью в одиночку бесполезно, я всё равно прибыл в эти земли, чтобы лечить израненную природу." }, { 10.00, "Чума поражает зверей и травы, не ведая пощады." }, { 14.27, "Прошу, продолжи моё дело." }, { 16.61, "Несчастных животных не спасти, остаётся прекратить их страдания." }, { 22.25, "Ступай, отыщи больных волков и прикончи их." }, { 26.20, "Прошу тебя, избавь их от мучений – и мне тоже станет полегче." } } }, t = { d = 17.6, v = "tauren-male", n = { x = 143 }, c = { x = { { 0.00, "Я..." }, { 0.44, "Чую, что души убитых волков обрели покой." }, { 4.69, "Мы с ними благодарны тебе за милосердие." }, { 8.66, "Но в этом проклятом месте страдают не только волки." }, { 13.79, "Мне вновь придётся просить тебя о помощи." } } } } },
    [4985] = { d = 29.4, v = "tauren-male", n = { x = 248 }, c = { x = { { 0.00, "На востоке отсюда, рядом с границей Восточных Чумных земель, некогда жили гордые и могучие гризли." }, { 9.61, "Чума затронула и их." }, { 11.60, "Теперь они бродят по округе, страдая от застывающих мышц и гниющей плоти и меха." }, { 19.40, "Прошу тебя, избавь их от страданий." }, { 22.86, "Единственное исцеление для них – быстрая смерть." }, { 27.36, "Ты можешь даровать её." } } }, t = { d = 40.3, g = 1, v = "tauren-male", n = { m = 313, f = 315 }, c = { m = { { 0.00, "\"Я чувствую, что гризли упокоились с миром." }, { 4.67, "Вот... вот моя последняя просьба." }, { 8.27, "Я записал её... на этой ветви, чувствуя, что дни мои сочтены." }, { 14.88, "Я не ошибся, мне и верно приходит конец." }, { 19.26, "Ещё раз спасибо, брат... все живые существа этой проклятой земли обрели покой... теперь мой черёд.\"" }, { 29.76, "*С этими словами друид испускает тяжёлый вздох, сменяющийся предсмертным хрипом.*" }, { 36.88, "*На полу остаётся лишь безжизненное тело.*" } }, f = { { 0.00, "\"Я чувствую, что гризли упокоились с миром." }, { 4.56, "Вот... вот моя последняя просьба." }, { 8.08, "Я записал её... на этой ветви, чувствуя, что дни мои сочтены." }, { 14.54, "Я не ошибся, мне и верно приходит конец." }, { 18.81, "Ещё раз спасибо, сестра... все живые существа этой проклятой земли обрели покой... теперь мой черёд.\"" }, { 29.36, "*С этими словами друид испускает тяжёлый вздох, сменяющийся предсмертным хрипом.*" }, { 36.27, "*На полу остаётся лишь безжизненное тело.*" } } } } },
    [4986] = { d = 33.8, v = "narrator", n = { x = 339 }, c = { x = { { 0.00, "В безжизненной руке друида-таурена – удивительно живая дубовая ветвь." }, { 5.72, "Внимательно осмотрев её, вы видите вырезанные на ней друидические символы." }, { 11.73, "Схватившись за ветвь, вы замечаете, что она слишком тёплая для простой ветви." }, { 17.96, "У вас в подсознании возникает образ древа Тельдрассила, точнее, самого Дарнасса." }, { 24.57, "Более того, в голове так и вертятся слова \"Круг Кенария\"." }, { 29.32, "Кажется, в ветку вложили знания, куда её лучше отнести." } } }, t = { d = 31.3, v = "nightelf-male#59", n = { x = 330 }, c = { x = { { 0.00, "Это..." }, { 0.55, "Это странно." }, { 1.59, "Тот друид – друид-таурен, надо же – передал тебе ценнейшие сведения о чуме Плети." }, { 7.86, "Удивительно, зачем таурену понадобилось добровольно передавать подобные сведения кому-то вроде тебя." }, { 15.58, "Надеюсь, ты говоришь правду." }, { 17.78, "Не сомневайся, мы воспользуемся этими данными." }, { 21.30, "Значит, таурены не так далеко отпали от Кенария, как полагает Фэндрал..." }, { 26.81, "Кхе-кхе, да." }, { 27.78, "Прими это в знак признательности Круга Кенария." } } } } },
    [4987] = { d = 34.6, v = "narrator", n = { x = 346 }, c = { x = { { 0.00, "В безжизненной руке друида-таурена – удивительно живая дубовая ветвь." }, { 5.74, "Внимательно осмотрев её, вы видите вырезанные на ней друидические символы." }, { 11.77, "Схватившись за ветвь, вы замечаете, что она слишком тёплая для простой ветви." }, { 18.03, "У вас в подсознании возникает образ Громового Утёса в Мулгоре, точнее, Вершины Старейшин." }, { 25.33, "Более того, в голове так и вертятся слова \"Круг Кенария\"." }, { 30.10, "Кажется, в ветку вложили знания, куда её лучше отнести." } } }, t = { d = 33.6, v = "tauren-female", n = { x = 321 }, c = { x = { { 0.00, "Значит, это от Малгриса?" }, { 2.09, "Мы слышали, что он хотел избавить существ из Чумных земель от страдания, но столь плачевного итога мы не ждали..." }, { 11.35, "Печально." }, { 12.17, "Малгрис... был моим другом." }, { 14.49, "Я скорблю о его гибели." }, { 16.50, "Но благодаря тебе его труды не пропали даром." }, { 20.39, "В этой ветви заключено множество знаний о наступлении чумы на наши земли." }, { 26.59, "Мы пристально изучим её." }, { 28.60, "А что до тебя, то возьми это." }, { 31.07, "Мы хотели бы отблагодарить тебя." } } } } },
    [5001] = { d = 36.7, g = 1, v = "goblin-female#63", n = { x = 404 }, c = { m = { { 0.00, "Обычно я стараюсь не связываться с такими, как ты, герой, но, похоже, сейчас я застряла между троллем и горным завалом." }, { 8.60, "Видишь ли, я выполняю важное задание для Орды." }, { 11.98, "Однако та информация, которую мне удалось раздобыть, касается также и благополучия Альянса." }, { 18.56, "Поверь мне, я не питаю симпатий к Альянсу, но угроза Чёрной горы – это гораздо серьёзнее, чем какая-то там толпа грязных орков." }, { 27.68, "Помоги мне найти мои вещи, а я передам тебе сведения, которые могут оказаться полезными для твоих сородичей." }, { 35.63, "Ну что, по рукам?" } }, f = { { 0.00, "Обычно я стараюсь не связываться с такими, как ты, героиня, но, похоже, сейчас я застряла между троллем и горным завалом." }, { 8.43, "Видишь ли, я выполняю важное задание для Орды." }, { 11.70, "Однако та информация, которую мне удалось раздобыть, касается также и благополучия Альянса." }, { 18.06, "Поверь мне, я не питаю симпатий к Альянсу, но угроза Чёрной горы – это гораздо серьёзнее, чем какая-то там толпа грязных орков." }, { 26.87, "Помоги мне найти мои вещи, а я передам тебе сведения, которые могут оказаться полезными для твоих сородичей." }, { 34.55, "Ну что, по рукам?" } } }, t = { d = 3.5, v = "goblin-female#63", n = { x = 21 }, c = { x = { { 0.00, "Ой, спасибо!" }, { 1.48, "И где ж они были?!" } } } } },
    [5002] = { d = 31.8, g = 1, v = "goblin-female#63", n = { x = 341 }, c = { m = { { 0.00, "Я – честная гоблинша и хозяйка своего слова, герой." }, { 3.88, "А теперь слушай внимательно..." }, { 6.15, "Этих орков используют в основном в качестве вьючных животных или пушечного мяса для чёрных драконов!" }, { 13.64, "Их предводитель не кто иной, как Нефариан, сын Смертокрыла." }, { 17.92, "Также мне удалось узнать, где именно в крепости засели приспешники Нефариана." }, { 23.67, "Отнеси эту карту маршалу Максвеллу в Пылающие степи." }, { 27.68, "Я там отметила все места, где найти этих извергов." } }, f = { { 0.00, "Я – честная гоблинша и хозяйка своего слова, героиня." }, { 4.06, "А теперь слушай внимательно..." }, { 6.35, "Этих орков используют в основном в качестве вьючных животных или пушечного мяса для чёрных драконов!" }, { 13.93, "Их предводитель не кто иной, как Нефариан, сын Смертокрыла." }, { 18.25, "Также мне удалось узнать, где именно в крепости засели приспешники Нефариана." }, { 24.07, "Отнеси эту карту маршалу Максвеллу в Пылающие степи." }, { 28.12, "Я там отметила все места, где найти этих извергов." } } }, t = { d = 14.5, v = "human-male", n = { x = 178 }, c = { x = { { 0.00, "Что ж, это лишь подтверждает уже известную нам информацию." }, { 3.95, "Тем не менее здесь есть интересные сведения, которые нам пригодятся." }, { 8.51, "Отметки на карте – это хорошее подспорье." }, { 11.41, "Так мы быстрее разберёмся с угрозой Чёрной горы." } } } } },
    [5021] = { d = 29.5, v = "human-female", n = { x = 310 }, c = { x = { { 0.00, "\"Доставьте посылку..." }, { 1.55, "Доставьте её, пока я не очутилась в ловушке!\"" }, { 4.72, "*По всему дому разносятся причитания напуганной женщины.*" }, { 9.18, "*Привидение скорчилось в углу на втором этаже.*" }, { 12.86, "*Кажется, она не понимает, что вокруг, да и вас едва замечает.*" }, { 17.68, "\"Ты хочешь доставить мою посылку?" }, { 20.16, "Прошу тебя, сделай это, пока хуже не стало." }, { 23.48, "Я собиралась уехать отсюда." }, { 25.50, "Должно быть, там всё ещё стоит мой конь... или я опоздала?\"" } } }, t = { d = 11.4, v = "narrator", n = { x = 117 }, c = { x = { { 0.00, "В сарае на полу лежит посылка." }, { 2.43, "Вы могли бы пройти мимо, но она бросается в глаза среди развалин." }, { 7.56, "Быть может, именно о ней говорила Джанис Фелстоун..." } } } } },
    [5022] = { d = 25.4, v = "narrator", n = { x = 275 }, c = { x = { { 0.00, "Вы берёте посылку, стирая с неё слой пыли и грязи." }, { 3.82, "Она адресована Эмме Фелстоун из Штормграда; посылка должна была быть доставлена четыре года назад." }, { 11.54, "Хотя вы не уверены, что Эмма Фелстоун жива, всем известно, что в Штормграде существует реестр жителей города." }, { 19.95, "Справки можно наводить у королевских представителей Переписи Штормграда." } } }, t = { d = 29.1, v = "human-male", n = { x = 308 }, c = { x = { { 0.00, "Говорите, посылка для Эммы Фелстоун?" }, { 2.75, "И четыре года назад она жила в Штормграде?" }, { 6.04, "Посмотрим…" }, { 6.85, "Судя по всему, четыре года назад в городе и верно жила некая Эмма Фелстоун." }, { 12.69, "Скорее всего жила." }, { 14.16, "Я ориентируюсь по переписи, имевшей место пять лет назад, но никаких записей о том, что она уехала, нет." }, { 21.82, "Но это не значит, что Эмма всё ещё здесь." }, { 24.84, "Минуточку... уж не старушке ли Эмме адресована эта посылка?" } } } } },
    [5023] = { d = 27.9, v = "narrator", n = { x = 305 }, c = { x = { { 0.00, "Вы берёте посылку, стирая с неё слой пыли и грязи." }, { 3.82, "Она адресована Иеремии Фелстоуну из Лордерона; посылка была подготовлена к отправке четыре года назад." }, { 11.81, "Хотя вы не уверены, что Иеремия Фелстоун жив, всем известно, что в Подгороде, прежде именовавшемся Лордероном, существует реестр жителей города." }, { 22.79, "Справки можно наводить у королевских инспекторов Переписи Подгорода." } } }, t = { d = 31.3, v = "scourge-male", n = { x = 278 }, c = { x = { { 0.00, "Посылка для Иеремии Фелстоуна..." }, { 2.99, "В Лордерон..." }, { 4.23, "Пожалуй, я смогу помочь." }, { 6.55, "До наступления чумы Иеремия Фелстоун жил в городе." }, { 11.20, "Бывший Иеремия Фелстоун – многие представители нежити изменили фамилии, чтобы избавиться от прошлого." }, { 20.57, "Так произошло и в этом случае." }, { 23.40, "Иеремия Фелстоун стал Иеремией Пэйсоном." }, { 27.13, "Минуточку... разве это не он продаёт тараканов?" } } } } },
    [5041] = { d = 25.5, v = "orc-male#60", n = { x = 274 }, c = { x = { { 0.00, "Нападение на караваны лишает нас необходимых припасов." }, { 4.17, "Тебе хватило храбрости выступить против племени Иглогривых, и я вновь попрошу тебя о том же, но на сей раз посматривай, нет ли где украденных у нас припасов?" }, { 16.00, "Может быть, они в лагерях этих тварей, и иглогривы жиреют на чужом добре?" }, { 21.77, "Народ Перекрёстка будет у тебя в неоплатном долгу." } } }, t = { d = 11.9, v = "orc-male#60", n = { x = 107 }, c = { x = { { 0.00, "Ха-ха!" }, { 0.64, "Спасибо!" }, { 1.45, "Ты нам очень помог." }, { 3.22, "Ты неизменно спасаешь народ Перекрёстка и Орды." }, { 7.41, "Если я могу что-нибудь для тебя сделать, обращайся." } } } } },
    [5042] = { t = { d = 21.3, g = 1, v = "named/3430", n = { m = 180, f = 182 }, c = { m = { { 0.65, "Ах, если бы Кривозуб был свободен и мог видеть, как ты наказал предавших его!" }, { 8.50, "Благодарю тебя, ведь, собирая эти осколки, ты убил ещё нескольких Дыбогривов." }, { 14.95, "Продолжай в том же духе, и я вновь буду помогать тебе." } }, f = { { 0.65, "Ах, если бы Кривозуб был свободен и мог видеть, как ты наказала предавших его!" }, { 8.58, "Благодарю тебя, ведь, собирая эти осколки, ты убила ещё нескольких Дыбогривов." }, { 15.02, "Продолжай в том же духе, и я вновь буду помогать тебе." } } } } },
    [5043] = { t = { d = 21.9, g = 1, v = "named/3430", n = { x = 165 }, c = { m = { { 0.98, "Да будет верной твоя цель и метким оружие, герой." }, { 5.75, "Дух Агамаггана пребывает с тобой." }, { 10.18, "Возвращайся, если захочешь." }, { 12.68, "Кривозуб снова благословит тебя, если будет на то воля великого кабаньего бога." } }, f = { { 0.72, "Да будет верной твоя цель и метким оружие, героиня." }, { 5.81, "Дух Агамаггана пребывает с тобой." }, { 10.33, "Возвращайся, если захочешь." }, { 12.77, "Кривозуб снова благословит тебя, если будет на то воля великого кабаньего бога." } } } } },
    [5044] = { t = { d = 17.2, g = 1, v = "named/3430", n = { x = 138 }, c = { m = { { 0.79, "Теперь враги будут трепетать от одного твоего вида, герой." }, { 6.63, "Поведай Кривозубу о своих битвах, когда мы встретимся в следующий раз – в этой жизни или в следующей." } }, f = { { 0.65, "Теперь враги будут трепетать от одного твоего вида, героиня." }, { 6.98, "Поведай Кривозубу о своих битвах, когда мы встретимся в следующий раз – в этой жизни или в следующей." } } } } },
    [5045] = { t = { d = 21.3, g = 1, v = "named/3430", n = { x = 164 }, c = { m = { { 0.65, "Наши величайшие воины и величайшие шаманы" }, { 6.18, "позавидовали бы твоей силе воли, герой." }, { 9.69, "Теперь, зная, что иглогривам не остановить тебя, ты нанесёшь ещё больший урон племени Вздыбленной Щетины." } }, f = { { 0.63, "Наши величайшие воины и величайшие шаманы" }, { 6.07, "позавидовали бы твоей силе воли, героиня." }, { 9.83, "Теперь, зная, что иглогривам не остановить тебя, ты нанесёшь ещё больший урон племени Вздыбленной Щетины." } } } } },
    [5046] = { t = { d = 2.8, g = 1, v = "named/3430", n = { x = 4 }, c = { m = { { 0.35, "В бой, герой!" } }, f = { { 0.35, "В бой, героиня!" } } } } },
    [5047] = { d = 31.3, g = 1, v = "gnome-male", n = { x = 335 }, c = { m = { { 0.00, "Разыщи Малифоя Черномолота в Круговзоре, герой." }, { 3.73, "Скажи ему, что с Айсом всё в порядке и что костюмчик исправно работает." }, { 9.29, "И передай ему вот что..." }, { 11.12, "*Айс вручает вам ярко светящийся кусок мяса.*" }, { 15.04, "Я его вырезал из внутренностей одной зверюги во время своих вынужденных каникул." }, { 20.71, "Готов поспорить, Малифой очень подробно тебе растолкует, что можно сделать с мясом этого чудища!" }, { 27.58, "Кстати, ты знаешь, где Круговзор?" }, { 29.91, "Это в Зимних Ключах." } }, f = { { 0.00, "Разыщи Малифоя Черномолота в Круговзоре, героиня." }, { 3.82, "Скажи ему, что с Айсом всё в порядке и что костюмчик исправно работает." }, { 9.31, "И передай ему вот что..." }, { 11.12, "*Айс вручает вам ярко светящийся кусок мяса.*" }, { 15.28, "Я его вырезал из внутренностей одной зверюги во время своих вынужденных каникул." }, { 20.78, "Готов поспорить, Малифой очень подробно тебе растолкует, что можно сделать с мясом этого чудища!" }, { 27.45, "Кстати, ты знаешь, где Круговзор?" }, { 29.71, "Это в Зимних Ключах." } } }, t = { d = 3.8, v = "dwarf-male", n = { x = 29 }, c = { x = { { 0.00, "Он жив?" }, { 0.70, "Костюм цел?" }, { 1.83, "А что это там у тебя?" } } } } },
    [5048] = { d = 36.6, v = "human-male", n = { x = 416 }, c = { x = { { 0.00, "Это злобная старушенция и к тому же, весьма вероятно, уже с катушек съехала..." }, { 5.57, "Но записи указывают, что старушка Эмма как раз вполне может являться той самой Эммой Фелстоун." }, { 12.21, "Возможно, вы видели старушку Эмму бредущей по городу – она разговаривает сама с собой, иногда неся совершенно невнятный вздор." }, { 21.14, "Но она никому и ничему не мешает, так что горожане, в большинстве своём, оставили её в покое." }, { 27.59, "Обдумав всё, я бы сказал, что старушка Эмма и в самом деле – Эмма Фелстоун." }, { 32.91, "Можете сами спросить у неё, не Фелстоун ли её фамилия." } } }, t = { d = 36.4, v = "human-female#45", n = { x = 351 }, c = { x = { { 0.00, "Моё имя и в самом деле Эмма Фелстоун – но меня впервые так называют за много лет." }, { 6.51, "Кто... кто вы?" }, { 7.58, "Вы говорите, что знали... мою сестру?!" }, { 10.66, "Она до сих пор жива?" }, { 12.30, "Да что это я – конечно же, нет." }, { 14.74, "Когда чума охватила Лордерон, я ожидала самого худшего." }, { 19.24, "Так много моих родственников погибло... или ещё хуже того." }, { 23.96, "И вот я здесь, сумасшедшая старушка Эмма, одна-одинёшенька." }, { 28.54, "Кто же вы – разоритель могил или что?" }, { 31.47, "Ищете следующую жертву?" }, { 33.40, "Что... у вас посылка для меня от сестры?" } } } } },
    [5049] = { d = 37.0, g = 1, v = "scourge-male", n = { x = 342 }, c = { m = { { 0.00, "Мне удалось выяснить, что тот, кого ты ищешь, – он же получатель посылки – это Иеремия Пэйсон, продавец тараканов в Подгороде." }, { 10.65, "Мне всегда казалось, что для торговли тараканами нужны особые личные качества." }, { 17.32, "Не сомневаюсь, тебя ждут великие дела, герой." }, { 21.22, "Ступай, меняй мир к лучшему." }, { 23.68, "Впрочем, позволь и мне поучаствовать в столь великих событиях и приоткрыть завесу тайны: он находится недалеко от банка, в стороне от одной из дорожек." } }, f = { { 0.00, "Мне удалось выяснить, что тот, кого ты ищешь, – он же получатель посылки – это Иеремия Пэйсон, продавец тараканов в Подгороде." }, { 10.84, "Мне всегда казалось, что для торговли тараканами нужны особые личные качества." }, { 17.62, "Не сомневаюсь, тебя ждут великие дела, героиня." }, { 21.76, "Ступай, меняй мир к лучшему." }, { 24.25, "Впрочем, позволь и мне поучаствовать в столь великих событиях и приоткрыть завесу тайны: он находится недалеко от банка, в стороне от одной из дорожек." } } }, t = { d = 35.9, g = 1, v = "scourge-male", n = { m = 280, f = 282 }, c = { m = { { 0.00, "Я не пользовался этим именем много лет..." }, { 3.91, "Да, некогда, до того прекрасного момента, когда я влился в ряды нежити, меня так звали." }, { 12.25, "Так ты знал мою сестру... или, точнее, недавно говорил с моей сестрой?" }, { 18.97, "Она умерла." }, { 20.17, "Четыре года назад." }, { 22.04, "Знаешь, не будь у меня такие хрупкие кости, я бы с радостью тебя пнул." }, { 28.67, "Глумишься над чужим горем?" }, { 31.23, "Что... у тебя посылка от моей сестры?!" } }, f = { { 0.00, "Я не пользовался этим именем много лет..." }, { 4.02, "Да, некогда, до того прекрасного момента, когда я влился в ряды нежити, меня так звали." }, { 12.58, "Так ты знала мою сестру... или, точнее, недавно говорила с моей сестрой?" }, { 19.75, "Она умерла." }, { 20.97, "Четыре года назад." }, { 22.89, "Знаешь, не будь у меня такие хрупкие кости, я бы с радостью тебя пнул." }, { 29.71, "Глумишься над чужим горем?" }, { 32.33, "Что... у тебя посылка от моей сестры?!" } } } } },
    [5050] = { d = 27.9, v = "human-female#45", n = { x = 307 }, c = { x = { { 0.00, "Кажется, я была неправа насчёт тебя и должна извиниться." }, { 4.09, "Сестра прислала мне ряд личных вещей, в том числе – ха-ха – документы на ферму Фелстоун." }, { 10.46, "Я погожу предъявлять на неё права." }, { 12.93, "Если призрак моей сестры не может упокоиться и привязан к ферме... может быть, ты вернёшь ей это?" }, { 19.94, "Это половина талисмана; вторую носил её муж." }, { 23.19, "Может быть, она обретёт покой, если узнает, что я получила посылку?" } } }, npc = { [8403] = { d = 36.5, v = "scourge-male", n = { x = 307 }, c = { x = { { 0.00, "Кажется, я была неправа насчёт тебя и должна извиниться." }, { 5.69, "Сестра прислала мне ряд личных вещей, в том числе – ха-ха – документы на ферму Фелстоун." }, { 13.86, "Я погожу предъявлять на неё права." }, { 17.02, "Если призрак моей сестры не может упокоиться и привязан к ферме... может быть, ты вернёшь ей это?" }, { 26.03, "Это половина талисмана; вторую носил её муж." }, { 30.19, "Может быть, она обретёт покой, если узнает, что я получила посылку?" } } } } }, t = { d = 15.2, v = "human-female", n = { x = 142 }, c = { x = { { 0.00, "*Вы отдаёте половинку талисмана призраку.*" }, { 3.63, "*Джанис выжидающе смотрит на вас.*" }, { 6.52, "\"Милый, а где твоя половина талисмана?" }, { 9.71, "Нам не быть вместе, не собрав его воедино." }, { 13.20, "Милый..." }, { 13.94, "Ты меня видишь?\"" } } } } },
    [5051] = { d = 26.4, v = "human-female", n = { x = 259 }, c = { x = { { 0.00, "*Несчастный призрак продолжает причитать:*" }, { 3.20, "\"Мне холодно, Джон." }, { 4.70, "Принеси мне свой оберег, и мы снова будем вместе!" }, { 8.64, "Скорее, Джон, пока чума не превратила нас в жутких тварей!" }, { 13.30, "Я не вижу тебя, Джон..." }, { 15.16, "Но знаю, ты рядом." }, { 16.67, "Я чувствую.\"" }, { 17.60, "*Быть может, если найти вторую половину оберега и собрать его воедино, душа Джанис Фелстоун обретёт покой.*" } } }, t = { d = 24.8, g = 1, v = "human-female", n = { m = 255, f = 256 }, c = { m = { { 0.00, "*Вы отдаёте целый оберег Удачи призраку Джанис Фелстоун.*" }, { 4.54, "*Взяв его в руки, она моментально преображается.*" }, { 8.42, "*Призрачный облик слегка мерцает, а девушка устремляет на вас ясный, хоть и грустный, взор.*" }, { 15.60, "\"Ты освободил меня..." }, { 17.17, "Мне больше не нужен этот оберег." }, { 19.59, "Возьми его, быть может он принесёт тебе не меньшее утешение, чем мне.\"" } }, f = { { 0.00, "*Вы отдаёте целый оберег Удачи призраку Джанис Фелстоун.*" }, { 4.72, "*Взяв его в руки, она моментально преображается.*" }, { 8.75, "*Призрачный облик слегка мерцает, а девушка устремляет на вас ясный, хоть и грустный, взор.*" }, { 16.20, "\"Ты освободила меня..." }, { 17.77, "Мне больше не нужен этот оберег." }, { 20.10, "Возьми его, быть может он принесёт тебе не меньшее утешение, чем мне.\"" } } } } },
    [5052] = { d = 43.3, v = "named/3430", n = { x = 396 }, c = { x = { { 0.35, "Кровь повлияла не только на шипы" }, { 4.11, "но и на другие аспекты земли: среди прочих минералов попадаются кроваво-красные камни." }, { 11.19, "Племя Дыбогривов выкапывает эти осколки и носит с собой как тотемы" }, { 17.77, "и они дают им силы в бою и помогают творить заклинания." }, { 23.54, "Секреты их магии мне известны." }, { 26.23, "Принеси Кривозубу один кровавый осколок, и ты всё поймёшь." }, { 31.30, "Принеси Кривозубу много осколков, и он благословит тебя." }, { 36.28, "Сильна магия иглогривов, ведь это магия самого Агамаггана!" } } }, t = { d = 38.3, g = 1, v = "named/3430", n = { x = 311 }, c = { m = { { 0.79, "Да, ты понимаешь." }, { 2.34, "Мои слова для тебя – не пустой звук, герой." }, { 6.32, "Быть может, Кривозуб и заключён в клетку, но что клетка для силы Агамаггана!" }, { 13.08, "Касание осколка, какое забытое ощущение, герой." }, { 17.48, "Знаешь, каково это – чувствовать себя отрезанным от силы?" }, { 22.77, "Но об этом в другой раз." }, { 24.97, "Я обещал поделиться с тобой сведениями." }, { 28.55, "Я обещал тебе силу Агамаггана." }, { 31.40, "Мой народ отвернулся от Кривозуба." }, { 34.50, "Теперь они падут от твоей руки." } }, f = { { 0.65, "Да, ты понимаешь." }, { 2.11, "Мои слова для тебя – не пустой звук, героиня." }, { 6.01, "Быть может, Кривозуб и заключён в клетку, но что клетка для силы Агамаггана!" }, { 12.36, "Касание осколка, какое забытое ощущение, героиня." }, { 16.64, "Знаешь, каково это – чувствовать себя отрезанным от силы?" }, { 21.61, "Но об этом в другой раз." }, { 23.67, "Я обещал поделиться с тобой сведениями." }, { 27.04, "Я обещал тебе силу Агамаггана." }, { 29.72, "Мой народ отвернулся от Кривозуба." }, { 32.62, "Теперь они падут от твоей руки." } } } } },
    [5054] = { d = 36.1, v = "tauren-male#68", n = { x = 325 }, c = { x = { { 0.00, "В заснеженных горах Зимних Ключей, на северо-западе, умелый охотник идёт по следу своей добычи…" }, { 8.47, "Я говорю о медведе-щербозубе Урсиусе – звере ловком и умном." }, { 13.85, "Я посылаю тебя в бой против него." }, { 16.85, "Он бродит по холмам к северо-западу от Круговзора." }, { 21.28, "Найди его и начни охоту на него – раньше, чем он поймёт твои намерения." }, { 27.61, "Все, кто шли на Урсиуса, вскоре понимали, что они добыча, а отнюдь не охотники." }, { 34.50, "Так что будь начеку." } } }, t = { d = 10.2, v = "tauren-male#68", n = { x = 105 }, c = { x = { { 0.00, "Задание было непростым, но тебе сопутствовал успех." }, { 4.25, "Только не думай так сразу, что тебе удалось произвести на меня впечатление." } } } } },
    [5055] = { d = 28.1, v = "tauren-male#68", n = { x = 270 }, c = { x = { { 0.00, "Быстрая и умная, Брумеран тихо скользит по заснеженным просторам южных окраин Зимних Ключей." }, { 8.00, "Но пусть тебя не обманывает её грация – она отнюдь не безопасна." }, { 13.46, "Все, кто встаёт у неё на пути, расплачиваются за это – частенько своими собственными жизнями." }, { 21.24, "Найди Брумеран среди химер Холодного Ветра." }, { 25.08, "Срази её, а затем возвращайся ко мне." } } }, t = { d = 17.5, g = 1, v = "tauren-male#68", n = { m = 145, f = 149 }, c = { m = { { 0.00, "Да." }, { 0.35, "Ты вернулся." }, { 1.59, "Теперь я верю, что охота – твоё призвание." }, { 5.75, "Ты встретился с самой свирепой из тварей и вернулся превзойдя мои ожидания." }, { 13.18, "Теперь ты готов к моему последнему испытанию." } }, f = { { 0.00, "Да." }, { 0.35, "Ты вернулась." }, { 1.64, "Теперь я верю, что охота – твоё призвание." }, { 5.70, "Ты встретилась с самой свирепой из тварей и вернулась превзойдя мои ожидания." }, { 13.12, "Теперь ты готова к моему последнему испытанию." } } } } },
    [5056] = { d = 42.6, g = 1, v = "tauren-male#68", n = { m = 416, f = 417 }, c = { m = { { 0.00, "На севере Зимних Ключей, в районе, который называют Уступ Ледопардов, обитают огромные кошки." }, { 7.98, "Их предводительница известна под именем Ши-Ротам." }, { 12.08, "Если тебе удастся сразить матриарха ледопардов, ты завоюешь уважение в глазах своих сородичей." }, { 20.13, "Отправляйся обратно в глушь." }, { 22.49, "Придя на место, добудь священного мяса ледопардов." }, { 26.82, "Найди камень Ши-Ротам и помести мясо на него." }, { 30.77, "Мясо растерзанных подданных заставит их предводительницу Ши-Ротам явиться в гневе." }, { 37.68, "Будь готов встретиться с ней лицом к лицу и сразить её." } }, f = { { 0.00, "На севере Зимних Ключей, в районе, который называют Уступ Ледопардов, обитают огромные кошки." }, { 8.04, "Их предводительница известна под именем Ши-Ротам." }, { 12.17, "Если тебе удастся сразить матриарха ледопардов, ты завоюешь уважение в глазах своих сородичей." }, { 20.29, "Отправляйся обратно в глушь." }, { 22.66, "Придя на место, добудь священного мяса ледопардов." }, { 27.02, "Найди камень Ши-Ротам и помести мясо на него." }, { 31.00, "Мясо растерзанных подданных заставит их предводительницу Ши-Ротам явиться в гневе." }, { 37.97, "Будь готова встретиться с ней лицом к лицу и сразить её." } } }, t = { d = 10.3, g = 1, v = "tauren-male#68", n = { m = 86, f = 87 }, c = { m = { { 0.00, "Ты доказал как свою силу, так и решимость." }, { 3.89, "Ещё много испытаний ждёт тебя впереди." }, { 7.44, "Я показал тебе всё, что мог." } }, f = { { 0.00, "Ты доказала как свою силу, так и решимость." }, { 4.13, "Ещё много испытаний ждёт тебя впереди." }, { 7.82, "Я показал тебе всё, что мог." } } } } },
    [5057] = { d = 41.4, g = 1, v = "tauren-male#68", n = { x = 379 }, c = { m = { { 0.00, "Ещё раньше, чем вы пришли ко мне поговорить, я слышал о ваших деяниях… что у вас есть непреодолимое желание проявить себя, что вы герой с отменными способностями, и теперь я знаю, что всё это было правдой." }, { 17.65, "Те, кто добивается таких успехов, заслуживают признания." }, { 22.53, "Отнесите этот знак в Громовой Утёс моему другу Мелору Каменному Копыту." }, { 28.83, "Уверен, что он вспомнит и вас, и ваши подвиги." }, { 32.85, "Расскажите ему о своих недавних достижениях." }, { 36.79, "И никогда не забывайте о том, что свершили сегодня." } }, f = { { 0.00, "Ещё раньше, чем вы пришли ко мне поговорить, я слышал о ваших деяниях… что у вас есть непреодолимое желание проявить себя, что вы героиня с отменными способностями, и теперь я знаю, что всё это было правдой." }, { 17.91, "Те, кто добивается таких успехов, заслуживают признания." }, { 22.82, "Отнесите этот знак в Громовой Утёс моему другу Мелору Каменному Копыту." }, { 29.16, "Уверен, что он вспомнит и вас, и ваши подвиги." }, { 33.20, "Расскажите ему о своих недавних достижениях." }, { 37.16, "И никогда не забывайте о том, что свершили сегодня." } } }, t = { d = 24.6, g = 1, v = "tauren-male#68", n = { m = 235, f = 239 }, c = { m = { { 0.00, "Мы учимся благодаря жизненным испытаниям." }, { 3.56, "Я уверен, что в результате ты стал лишь сильнее и мудрее." }, { 8.37, "Ты сильно повзрослел с того момента, когда мы общались впервые." }, { 13.87, "Прими это в память о тех сложных заданиях, с которыми ты справился, и знай, что ты навсегда завоевал моё уважение и восхищение." } }, f = { { 0.00, "Мы учимся благодаря жизненным испытаниям." }, { 3.52, "Я уверен, что в результате ты стала лишь сильнее и мудрее." }, { 8.42, "Ты сильно повзрослела с того момента, когда мы общались впервые." }, { 13.93, "Прими это в память о тех сложных заданиях, с которыми ты справилась, и знай, что ты навсегда завоевала моё уважение и восхищение." } } } } },
    [5058] = { t = { d = 37.0, v = "narrator", n = { x = 382 }, c = { x = { { 0.00, "Дневник с пожелтевшими страницами раскрыт на последней записи:" }, { 4.77, "«Не знаю, что теперь будет, раз Гарольд обратился." }, { 8.64, "Я выбилась из сил, пока затащила его в единственное место, где его можно было надёжно запереть." }, { 15.96, "Ключ я спрятала при себе и молюсь, чтобы это помогло..." }, { 20.25, "Надеюсь, мне удастся отсюда выбраться, но для этого нужны деньги." }, { 25.29, "Кажется, все наши вещи лежат в шкафу... а ведь, если подумать, ключ от него Гарольд носит при себе?" }, { 32.96, "Подумаю об этом, когда отдохну, я смертельно устала»." } } } } },
    [5059] = { t = { d = 16.4, v = "narrator", n = { x = 189 }, c = { x = { { 0.00, "Вы отпираете дверь ключом, обнаруженным на скелете миссис Далсон." }, { 4.80, "Наружу выскакивает кровожадный вурдалак, который сидел взаперти неизвестно сколько лет." }, { 11.28, "Судя по леденящему кровь воплю, бывшего фермера Далсона уже не спасти." } } } } },
    [5060] = { t = { d = 14.3, v = "narrator", n = { x = 150 }, c = { x = { { 0.00, "Ключ, взятый из останков фермера Далсона, идеально подходит к замку." }, { 5.58, "Двери шкафа распахиваются." }, { 7.79, "Внутри оказывается несколько уцелевших предметов, которые кажутся весьма ценными." } } } } },
    [5061] = { d = 28.8, g = 1, v = "nightelf-male#54", n = { m = 303, f = 305 }, c = { m = { { 0.00, "Ты завершил обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик." }, { 8.43, "Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнасс." }, { 14.40, "Покажи ему свою подвеску и докажи, что ты готов усвоить его уроки." }, { 19.74, "Он завершит твоё обучение, благодаря которому ты станешь единым с водой." }, { 25.36, "Доброго пути, юный друид." }, { 27.47, "Мы ещё встретимся." } }, f = { { 0.00, "Ты завершила обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик." }, { 8.48, "Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнасс." }, { 14.44, "Покажи ему свою подвеску и докажи, что ты готова усвоить его уроки." }, { 19.84, "Он завершит твоё обучение, благодаря которому ты станешь единой с водой." }, { 25.45, "Доброго пути, дева-друид." }, { 27.55, "Мы ещё встретимся." } } }, t = { d = 19.3, g = 1, v = "nightelf-male#59", n = { m = 214, f = 215 }, c = { m = { { 0.00, "Великолепно." }, { 0.93, "Ты готов принимать водный облик, и я с радостью научу тебя." }, { 5.39, "А также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это." }, { 11.18, "Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия." } }, f = { { 0.00, "Великолепно." }, { 0.92, "Ты готова принимать водный облик, и я с радостью научу тебя." }, { 5.37, "А также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это." }, { 11.07, "Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия." } } } } },
    [5062] = { d = 40.4, v = "tauren-male", n = { x = 379 }, c = { x = { { 0.00, "Арикара очень опасна, и мы должны как можно быстрее разделаться с ней." }, { 6.19, "Для того чтобы привлечь это чудовище, тебе нужно будет разжечь священный огонь жизни." }, { 13.97, "Собери немного редкой огненной агавы и отнеси её Магате Зловещий Тотем." }, { 20.40, "Она живёт в Громовом Утёсе, на Вершине Старейшин." }, { 24.68, "Магата – очень могущественная шаманка, владеющая тайной приготовления зачарованного порошка из огненной агавы." }, { 34.37, "Огненную агаву можно собрать на Кипящем озере, это к востоку отсюда." } } }, t = { d = 17.1, v = "named/4046", n = { x = 117 }, c = { x = { { 0.00, "Прекрасно, вы собрали достаточно огненной агавы." }, { 4.62, "Эта редкая трава растёт лишь в Тысяче Игл, и она поможет мне разбудить священное пламя жизни." }, { 13.44, "*Магата начинает зачаровывать огненную агаву.*" } } } } },
    [5063] = { d = 33.7, v = "narrator", n = { x = 339 }, c = { x = { { 0.00, "Головного убора лучше этого тебе, быть может, и не придётся увидеть." }, { 5.69, "Из безупречной звериной шкуры наши опытные мастера изготовят потрясающую шляпу, о какой может только мечтать любой иллюзионист!" }, { 16.39, "Пятьдесят золотых и предметы по списку – и твою голову украсит шапка Алого Учёного." }, { 23.36, "Безупречная звериная шкура." }, { 25.68, "Потёртый шовный материал поганища." }, { 28.52, "Чародейские кристаллы." }, { 30.39, "Зачарованная алая нить." }, { 32.34, "И УЗРИШЬ ТЫ ЧУДО!" } } }, t = { d = 10.1, v = "dwarf-male", n = { x = 107 }, c = { x = { { 0.00, "Поразительно!" }, { 1.04, "Наверняка на сбор этих компонентов ушли недели... и как тебе удалось найти безупречную шкуру?!" }, { 8.35, "Носи шапку на здоровье!" } } } } },
    [5064] = { d = 32.8, g = 1, v = "tauren-male#67", n = { m = 284, f = 285 }, c = { m = { { 0.00, "Ты уже помогал нам, поэтому я доверю тебе ещё одно важное задание." }, { 6.36, "Клан Зловещего Тотема явно что-то замышляет." }, { 10.59, "За последние недели мы заметили трёх странных путников, которые посетили это племя." }, { 18.47, "Потом мы узнали, что таурены хранят важные записи в трёх сундуках на пике Тёмного Облака." }, { 26.86, "Если тебе удастся достать эти документы, я щедро тебя награжу." } }, f = { { 0.00, "Ты уже помогала нам, поэтому я доверю тебе ещё одно важное задание." }, { 6.38, "Клан Зловещего Тотема явно что-то замышляет." }, { 10.57, "За последние недели мы заметили трёх странных путников, которые посетили это племя." }, { 18.38, "Потом мы узнали, что таурены хранят важные записи в трёх сундуках на пике Тёмного Облака." }, { 26.68, "Если тебе удастся достать эти документы, я щедро тебя награжу." } } }, t = { d = 15.8, v = "tauren-male#67", n = { x = 126 }, c = { x = { { 0.00, "Великий тотем духов!" }, { 2.14, "Какие ужасные новости!" }, { 4.45, "Я немедленно начну готовиться, кто знает, что нас ждёт..." }, { 9.97, "Вот, как я и обещал, это награда за вашу храбрость и услугу." } } } } },
    [5065] = { d = 29.5, v = "dwarf-male", n = { x = 304 }, c = { x = { { 0.00, "Тот тролль обманул тебя." }, { 1.87, "В тех двух табличках шла речь о пленении сущности Хаккара, но легенда этим не исчерпывается." }, { 8.79, "Я долго изучал этот вопрос, и обнаружил, что табличек Мошару шесть, а не две!" }, { 14.68, "Шесть!" }, { 15.16, "И боюсь, нас не порадует то, что в них записано." }, { 18.76, "Найди третью и четвертую таблички." }, { 21.69, "Они находятся в Восточных Чумных землях, у троллей из племени Моходеров." }, { 27.82, "Найди их и принеси мне." } } }, t = { d = 10.2, g = 1, v = "dwarf-male", n = { m = 90, f = 90 }, c = { m = { { 0.00, "Ты нашёл их!" }, { 1.00, "Отлично!" }, { 1.77, "Спасибо." }, { 2.54, "Я изучу эти тексты и расшифрую их значение." }, { 6.31, "Для тебя же у меня есть ещё одно задание..." } }, f = { { 0.00, "Ты нашла их!" }, { 1.10, "Отлично!" }, { 1.89, "Спасибо." }, { 2.68, "Я изучу эти тексты и расшифрую их значение." }, { 6.54, "Для тебя же у меня есть ещё одно задание..." } } } } },
    [5066] = { d = 33.0, v = "human-male", n = { x = 371 }, c = { x = { { 0.00, "Слушайте, слушайте все!" }, { 1.74, "Я обращаюсь к героям, и да услышат они мою речь!" }, { 5.35, "Король Штормграда призывает к оружию!" }, { 8.16, "Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью!" }, { 14.72, "Спешите на северные границы Восточных королевств!" }, { 18.40, "Стало известно, что над Чумными землями вновь сгущаются тучи!" }, { 22.95, "Герои королевства!" }, { 24.35, "Ищите командира Ашлама Отважного Кулака!" }, { 27.43, "Его гарнизон вы найдёте в лагере Промозглого Ветра на севере Альтеракских гор!" } } }, t = { d = 21.1, v = "human-male#50", n = { x = 247 }, c = { x = { { 0.00, "Добро пожаловать в Чумные земли, герой." }, { 2.83, "Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть." }, { 10.07, "Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!" }, { 15.41, "Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." } } } } },
    [5067] = { d = 31.1, v = "narrator", n = { x = 315 }, c = { x = { { 0.00, "В то время как изготовление такого предмета ещё никому не удавалось, считается, что это всё же возможно – при правильном стечении обстоятельств." }, { 11.89, "Если искатель тайных знаний желает наделить поножи могучей силой, вот что должно быть найдено:" }, { 19.92, "Безупречная звериная шкура." }, { 22.26, "Потёртый шовный материал поганища." }, { 25.14, "Арканитовые Слитки." }, { 26.81, "Бальзамировочный состав Снегошёпота." }, { 29.76, "И УЗРИШЬ ТЫ ЧУДО!" } } }, t = { d = 10.6, v = "dwarf-male", n = { x = 120 }, c = { x = { { 0.00, "Нечасто мне доводилось видеть, чтобы смертные справлялись со столь немыслимой задачей." }, { 6.41, "Купайся в лучах славы моего творения!" }, { 9.30, "Пожинай его плоды!" } } } } },
    [5068] = { d = 33.0, v = "narrator", n = { x = 320 }, c = { x = { { 0.00, "Говорят, что кираса кровавой жажды была создана лишь один раз, и изготовлена она была для легендарной убийцы Гароны." }, { 10.04, "Суждено ли ещё одному подобному доспеху увидеть свет?" }, { 14.59, "Сомнительно..." }, { 15.83, "И всё же!" }, { 16.60, "Наши мастера могут воспроизвести этот доспех, если дать им необходимые компоненты:" }, { 23.70, "Безупречную звериную шкуру." }, { 26.09, "Потёртый шовный материал поганища." }, { 29.03, "Арканитовые Слитки." }, { 30.72, "Тенекожу." }, { 31.57, "И УЗРИШЬ ТЫ ЧУДО!" } } }, t = { d = 8.1, v = "dwarf-male", n = { x = 84 }, c = { x = { { 0.00, "Я уж думал, что не доживу до этого дня." }, { 3.08, "Достижение такого масштаба может превзойти лишь награда за него." } } } } },
    [5081] = { d = 30.2, v = "human-male", n = { x = 341 }, c = { x = { { 0.00, "Эти сведения заполняют последние пробелы в наших данных о пике Чёрной Горы." }, { 5.60, "Мы должны напасть со всей решительностью." }, { 8.56, "Первым делом нужно убить их воеводу, Вуна." }, { 11.79, "Без его боевых планов орки Чёрной Горы будут ввергнуты в хаос." }, { 16.47, "Следом должен умереть вождь огров, Омокк." }, { 19.57, "Трусливые огры Чёрной Горы окажутся беспомощны." }, { 23.06, "И, наконец, повелитель всей цитадели зла: Змейталак." }, { 26.81, "Когда он умрёт, командование будет обезглавлено." } } }, t = { d = 6.4, v = "human-male", n = { x = 70 }, c = { x = { { 0.00, "Отличная работа." }, { 1.27, "По меньшей мере нам удалось выиграть время – а на счету каждая минута." } } } } },
    [5082] = { d = 36.5, v = "dwarf-female#34", n = { x = 404 }, c = { x = { { 0.00, "Сюда в Зимние Ключи я пришла, чтобы изучать Источники Ледяного Пламени." }, { 5.29, "Я заметила, что у воды здесь какие-то… странные свойства." }, { 9.40, "Мне пока не удалось определить источник этих свойств, да и, по правде говоря, в последнее время у меня возникли кое-какие сложности, из-за фурболгов племени Зимней Спячки." }, { 21.87, "Их, кажется, тянет к источникам – так же, как и меня." }, { 25.66, "Они яростно защищают воду и не подпускают меня близко к двум большим ключам к северу отсюда." }, { 32.45, "Я хотела бы продолжить свои изыскания." }, { 35.25, "Ты не поможешь мне?" } } }, t = { d = 8.3, g = 1, v = "dwarf-female#34", n = { m = 88, f = 88 }, c = { m = { { 0.00, "Огромное спасибо!" }, { 1.44, "Теперь я могу вернуться к работе." }, { 4.16, "Нашёл что-нибудь интересное в поселении Зимней Спячки?" } }, f = { { 0.00, "Огромное спасибо!" }, { 1.41, "Теперь я могу вернуться к работе." }, { 4.09, "Нашла что-нибудь интересное в поселении Зимней Спячки?" } } } } },
    [5083] = { d = 21.5, v = "narrator", n = { x = 237 }, c = { x = { { 0.00, "Тот сосуд, что вы нашли у фурболга племени Зимней Спячки, пуст, но внутри осталось несколько капель странной зелёной жидкости." }, { 9.35, "Она почти сияет." }, { 10.70, "Обнаружили ли вы нечто важное?" }, { 12.99, "Возможно, Донова Снегонора могла бы что-то вам разъяснить, поскольку она уже довольно давно живёт у горячих ключей." } } }, t = { d = 4.0, v = "dwarf-female#34", n = { x = 37 }, c = { x = { { 0.00, "Это было у фурболга из племени Зимней Спячки?" } } } } },
    [5084] = { d = 42.6, g = 1, v = "dwarf-female#34", n = { m = 473, f = 473 }, c = { m = { { 0.00, "Зелёная жидкость… немного напоминает мне жижу, которую я видела, когда пробиралась через Осквернённый лес." }, { 7.65, "И я видела несколько гонцов племени Зимней Спячки, входящих во владения Древобрюхов…" }, { 13.85, "Возможно, это имеет отношение к той склянке, что ты нашёл." }, { 18.07, "Сразу за Крепостью Древобрюхов, в Осквернённом лесу, живёт большая группа фурболгов." }, { 24.14, "Они зовутся племенем Мёртвого Леса, и давно попали под власть скверны." }, { 29.29, "Да, фурболги этого племени совершенно безумны." }, { 32.72, "Может, сходишь и поищешь свидетельства того, что между племенами Зимней Спячки и Мёртвого Леса есть какое-то сообщение?" } }, f = { { 0.00, "Зелёная жидкость… немного напоминает мне жижу, которую я видела, когда пробиралась через Осквернённый лес." }, { 7.88, "И я видела несколько гонцов племени Зимней Спячки, входящих во владения Древобрюхов…" }, { 14.26, "Возможно, это имеет отношение к той склянке, что ты нашла." }, { 18.67, "Сразу за Крепостью Древобрюхов, в Осквернённом лесу, живёт большая группа фурболгов." }, { 24.92, "Они зовутся племенем Мёртвого Леса, и давно попали под власть скверны." }, { 30.21, "Да, фурболги этого племени совершенно безумны." }, { 33.75, "Может, сходишь и поищешь свидетельства того, что между племенами Зимней Спячки и Мёртвого Леса есть какое-то сообщение?" } } }, t = { d = 5.4, v = "narrator", n = { x = 52 }, c = { x = { { 0.00, "В котле кипит гнилостная, отвратительно пахнущая субстанция…" } } } } },
    [5085] = { d = 32.2, v = "narrator", n = { x = 344 }, c = { x = { { 0.00, "Зелёная субстанция внутри котла кажется точно такой же, какую вы обнаружили в сосуде." }, { 6.59, "Это странное слизистое вещество может оказаться таким же полным скверны, как и фурболги, что его изготовили…" }, { 14.98, "Если фурболги племени Зимней Спячки его используют, значит ли это, что вскоре они окажутся в таком же состоянии, как и племя Мёртвого Леса?" }, { 25.80, "Лучше всего сообщить об этих находках Донове, прихватив и образец жидкости из котла." } } }, t = { d = 8.5, g = 1, v = "dwarf-female#34", n = { m = 86, f = 87 }, c = { m = { { 0.00, "Ты очень находчив." }, { 1.58, "Так ты полагаешь, что фурболги племени Зимней Спячки побывали в лагере Мёртвого Леса?" } }, f = { { 0.00, "Ты очень находчива." }, { 1.62, "Так ты полагаешь, что фурболги племени Зимней Спячки побывали в лагере Мёртвого Леса?" } } } } },
    [5086] = { d = 37.4, g = 1, v = "dwarf-female#34", n = { m = 416, f = 418 }, c = { m = { { 0.00, "Я изучила образец, который ты принёс, и хотя точно пока ничего сказать не могу, я думаю, что в нём есть следы ядовитых компонентов." }, { 9.73, "Однако, единственный способ узнать наверняка – это найти что-то для сравнения." }, { 15.63, "Я думаю, что фурболги Мёртвого Леса могут собирать эти компоненты с других заражённых скверной существ в Осквернённом лесу: в частности, с элементалей, населяющих Железнолесье, которых называют ядовитым ужасом." }, { 31.07, "Собери для меня несколько образцов для сравнения, но будь осторожен – там очень опасно!" } }, f = { { 0.00, "Я изучила образец, который ты принесла, и хотя точно пока ничего сказать не могу, я думаю, что в нём есть следы ядовитых компонентов." }, { 9.75, "Однако, единственный способ узнать наверняка – это найти что-то для сравнения." }, { 15.55, "Я думаю, что фурболги Мёртвого Леса могут собирать эти компоненты с других заражённых скверной существ в Осквернённом лесу: в частности, с элементалей, населяющих Железнолесье, которых называют ядовитым ужасом." }, { 30.70, "Собери для меня несколько образцов для сравнения, но будь осторожна – там очень опасно!" } } }, t = { d = 8.6, g = 1, v = "dwarf-female#34", n = { m = 84, f = 84 }, c = { m = { { 0.00, "Мне нужно сравнить с этими образцами то вещество, что ты нашёл в котле – тогда, я уверена, мы узнаем больше." } }, f = { { 0.00, "Мне нужно сравнить с этими образцами то вещество, что ты нашла в котле – тогда, я уверена, мы узнаем больше." } } } } },
    [5087] = { d = 41.0, v = "dwarf-female#34", n = { x = 463 }, c = { x = { { 0.00, "Очень интересно…" }, { 1.26, "Если эту ядовитую субстанцию смешать с водой из горячих ключей, она потеряет свою токсичность, и остаётся лишь способность временно воздействовать на тех, кто такую смесь употребляет." }, { 14.63, "Наверное, из-за этого племя Зимней Спячки и защищает источники столь яростно: они необходимы фурболгам для очистки огненной воды." }, { 24.28, "Мы должны положить этому конец: прекратить контакты между племенами Зимней Спячки и Мёртвого Леса." }, { 31.59, "Группа гонцов курсирует между поселением Зимней Спячки и Осквернённым лесом." }, { 37.25, "Найди их, убей и забери то, что у них будет с собой." } } }, t = { d = 12.9, v = "dwarf-female#34", n = { x = 126 }, c = { x = { { 0.00, "*Донова изучает содержимое ящика.*" }, { 3.04, "Интересно, делает ли употребление этой субстанции фурболгов более агрессивными?" }, { 9.91, "На вид они кажутся намного крупнее…" } } } } },
    [5088] = { d = 33.9, g = 1, v = "named/4046", n = { x = 333 }, c = { m = { { 0.00, "Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл." }, { 6.30, "Сделать это нужно на Пике Тёмного Облака, на отдельной скале, где находится местное кладбище." }, { 13.59, "Я зачаровала порошок так, чтобы он привлёк Арикару." }, { 17.51, "Боюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище." }, { 29.14, "Поспешите, герой, вы можете не успеть!" } }, f = { { 0.00, "Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл." }, { 6.65, "Сделать это нужно на Пике Тёмного Облака, на отдельной скале, где находится местное кладбище." }, { 14.34, "Я зачаровала порошок так, чтобы он привлёк Арикару." }, { 18.48, "Боюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище." }, { 30.75, "Поспешите, героиня, вы можете не успеть!" } } }, t = { d = 22.9, v = "tauren-male", n = { x = 212 }, c = { x = { { 0.00, "Ерунда какая-то." }, { 1.51, "Зачем Арикаре охотиться за Кэрном Кровавым Копытом?" }, { 6.14, "Но Магата не может ошибаться, она наша самая могущественная шаманка." }, { 12.28, "В любом случае, вы очень помогли Орде, и деяние ваше не останется незамеченным." }, { 19.37, "Пожалуйста, выберите себе любую награду." } } } } },
    [5089] = { d = 21.0, v = "narrator", n = { x = 242 }, c = { x = { { 0.00, "Вы обыскали труп убитого драконида и обнаружили записку, содержание которой показалось вам важным: письмо от его непосредственного начальника, генерала Драккисата, в котором упоминается некий протокол." }, { 14.95, "Внутренний голос подсказывает, что это письмо следует показать маршалу Максвеллу." } } }, t = { d = 3.1, v = "human-male", n = { x = 23 }, c = { x = { { 0.00, "Мда... теперь всё усложняется..." } } } } },
    [5090] = { d = 26.8, v = "dwarf-male", n = { x = 297 }, c = { x = { { 0.00, "Слушайте все!" }, { 1.03, "Все герои – слушайте!" }, { 2.68, "Королевство Штормграда призывает всех к оружию!" }, { 6.26, "Все способные держать оружие – на защиту севера Восточных королевств против чёрной угрозы Плети!" }, { 13.61, "Новая опасность надвигается из руин Чумных земель!" }, { 17.53, "Герои королевства – собирайтесь к командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра к северу от Альтеракских гор!" } } }, t = { d = 21.6, v = "human-male#50", n = { x = 247 }, c = { x = { { 0.00, "Добро пожаловать в Чумные земли, герой." }, { 2.89, "Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть." }, { 10.29, "Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!" }, { 15.76, "Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." } } } } },
    [5091] = { d = 26.7, v = "nightelf-female#53", n = { x = 299 }, c = { x = { { 0.00, "Слушайте все!" }, { 1.02, "Все герои – слушайте!" }, { 2.64, "Королевство Штормграда призывает всех к оружию!" }, { 6.16, "Все, кто способен держать оружие, – на защиту севера Восточных королевств против чёрной угрозы Плети!" }, { 13.74, "Новая опасность надвигается из руин Чумных земель!" }, { 17.60, "Герои королевства – собирайтесь к командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра к северу от Альтеракских гор!" } } }, t = { d = 21.9, v = "human-male#50", n = { x = 247 }, c = { x = { { 0.00, "Добро пожаловать в Чумные земли, герой." }, { 2.94, "Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть." }, { 10.45, "Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!" }, { 15.99, "Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." } } } } },
    [5092] = { d = 22.6, v = "human-male#50", n = { x = 274 }, c = { x = { { 0.00, "Поскольку западная и северная дороги, ведущие в Андорал, хорошо укреплены, я подумываю о нападении с востока, как наименее защищённой стороны." }, { 9.84, "Плеть рассчитывает на защиту нежити, наводнившей холм Печали." }, { 14.06, "Первым заданием будет зачистка холма Печали." }, { 17.28, "Убей побольше скелетов и вурдалаков; по выполнении задания возвращайся ко мне!" } } }, t = { d = 17.6, g = 1, v = "human-male#50", n = { m = 193, f = 194 }, c = { m = { { 0.00, "Задание выполнено!" }, { 1.41, "Отлично, отлично!" }, { 2.75, "Позволь наградить тебя за труды звонкой монетой из казны Штормграда." }, { 7.90, "Советую потратить награду на подготовку к следующей битве..." }, { 12.39, "Ведь тебе придётся войти в руины Андорала." }, { 15.54, "Готовься!" }, { 16.28, "Будь бдителен!" } }, f = { { 0.00, "Задание выполнено!" }, { 1.39, "Отлично, отлично!" }, { 2.71, "Позволь наградить тебя за труды звонкой монетой из казны Штормграда." }, { 7.80, "Советую потратить награду на подготовку к следующей битве..." }, { 12.14, "Ведь тебе придётся войти в руины Андорала." }, { 15.90, "Готовься!" }, { 16.62, "Будь бдительна!" } } } } },
    [5093] = { d = 34.4, v = "orc-male", n = { x = 343 }, c = { x = { { 0.00, "Внимайте моим словам, о герои!" }, { 2.62, "Орда призывает к решительным действиям!" }, { 5.91, "Все, кто способен носить оружие, должны выступить в поход против Плети!" }, { 11.89, "Из руин Восточных королевств поднимается новая угроза!" }, { 16.45, "Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли." }, { 24.60, "Храбрецы, обращайтесь к верховному палачу Деррингтону." }, { 29.14, "Он ждёт вас в лагере у Бастиона, к востоку от Тирисфальских лугов!" } } }, t = { d = 29.8, v = "scourge-male", n = { x = 267 }, c = { x = { { 0.00, "Добро пожаловать в Чумные земли, герой." }, { 3.67, "Здесь одна из самых опасных границ Азерота, тем более что с востока нам грозит Плеть, а дальше на восток её власть только крепнет." }, { 15.33, "Я рад слышать, что зов долга и служения Орде не остался для вас пустым звуком!" }, { 22.34, "Если вы готовы к тяжёлому труду, то на краю Чумных земель всем героям найдётся дело." } } } } },
