    [5096] = { d = 41.2, v = "scourge-male", n = { x = 416 }, c = { x = { { 0.00, "Прежде чем заняться Андоралом, мы должны разобраться с Алым орденом, обосновавшимся в Дольном Очаге." }, { 7.98, "Его приспешники разбили лагерь между полем Джанис и Слезами Далсона, так что мы оказались между двух огней – нам противостоят разом и Плеть, и Алый орден." }, { 20.28, "Мне кажется, надо их стравить между собой." }, { 23.73, "Вот что я хочу тебе поручить: уничтожь командный шатёр." }, { 28.12, "Сожги его при помощи пламени в бутылке - вот, возьми в этом ящике." }, { 33.51, "Сделав это, воткни посреди лагеря знамя Плети." }, { 37.40, "При удаче, нас оставят в покое и займутся Плетью." } } }, t = { d = 28.6, v = "scourge-male", n = { x = 289 }, c = { x = { { 0.00, "Отличная работа." }, { 1.38, "Благодаря налёту на Алый орден мы выиграли время." }, { 5.37, "Я послал разведчика наблюдать за лагерем, чтобы убедиться, что прибывшее подкрепление поддастся на провокацию." }, { 14.14, "Если натиск ордена ослабеет, мы сможем рискнуть и устроить вылазку в Андорал." }, { 20.45, "Это очень важно." }, { 21.90, "Я бы хотел, чтобы этим тоже занялся ты – в конце концов, у тебя такой большой опыт." } } } } },
    [5097] = { d = 29.0, v = "human-male#50", n = { x = 371 }, c = { x = { { 0.00, "Мы можем пометить будущие цели для наших войск при помощи магического устройства, сигнального факела." }, { 6.73, "Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками." }, { 13.47, "Твоя цель – ворваться в Андорал и установить сигнальные факелы на всех четырёх башнях." }, { 19.12, "Устанавливать факелы надо в дверных проёмах; они сами собой отметят всю башню." }, { 24.41, "В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну." } } }, t = { d = 17.9, g = 1, v = "human-male#50", n = { m = 197, f = 198 }, c = { m = { { 0.00, "Жрецы говорят, что со всех четырёх башен идут чёткие сигналы!" }, { 4.46, "Боюсь сглазить, но по-моему, ты только что выполнил очередную операцию без сучка, без задоринки!" }, { 11.52, "Отлично!" }, { 12.19, "Башни помечены, и всё готово к началу атаки." }, { 15.52, "Пришло время сразиться с Плетью!" } }, f = { { 0.00, "Жрецы говорят, что со всех четырёх башен идут чёткие сигналы!" }, { 4.47, "Боюсь сглазить, но по-моему, ты только что выполнила очередную операцию без сучка, без задоринки!" }, { 11.60, "Отлично!" }, { 12.27, "Башни помечены, и всё готово к началу атаки." }, { 15.60, "Пришло время сразиться с Плетью!" } } } } },
    [5098] = { d = 33.9, v = "scourge-male", n = { x = 371 }, c = { x = { { 0.00, "Мы можем пометить будущие цели для наших войск при помощи магического устройства, сигнального факела." }, { 7.88, "Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками." }, { 15.77, "Твоя цель – ворваться в Андорал и установить сигнальные факелы на всех четырёх башнях." }, { 22.39, "Устанавливать факелы надо в дверных проёмах; они сами собой отметят всю башню." }, { 28.58, "В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну." } } }, t = { d = 21.9, g = 1, v = "scourge-male", n = { m = 205, f = 206 }, c = { m = { { 0.00, "Чернокнижники говорят, что со всех четырёх башен идут чёткие сигналы!" }, { 5.91, "Ты выполнил мои приказы с точностью, достойной закалённого бойца." }, { 11.59, "Орда не забудет твоей верной службы!" }, { 14.90, "Башни помечены, и всё готово к началу атаки." }, { 18.84, "Пришло время сразиться с Плетью!" } }, f = { { 0.00, "Чернокнижники говорят, что со всех четырёх башен идут чёткие сигналы!" }, { 5.98, "Ты выполнила мои приказы с точностью, достойной закалённого бойца." }, { 11.80, "Орда не забудет твоей верной службы!" }, { 15.14, "Башни помечены, и всё готово к началу атаки." }, { 19.13, "Пришло время сразиться с Плетью!" } } } } },
    [5102] = { d = 28.0, v = "human-male", n = { x = 295 }, c = { x = { { 0.00, "Мы бьёмся против этих тварей на двух фронтах – из столицы, Штормграда, мы бьём их в спину, а здесь, в Пылающих степях, мы стоим у самого их порога." }, { 10.93, "Не теряй бдительности." }, { 12.64, "Никто не избегнет нашего гнева, как никто из наших не избегнул их гнева, который обрушился на наши дома и семьи." }, { 21.25, "Отыщи этого генерала Драккисата и убей его!" }, { 24.66, "Задание непростое, но и награда будет велика." } } }, t = { d = 8.4, v = "human-male", n = { x = 90 }, c = { x = { { 0.00, "Следующий удар мы несомненно нанесём по драконьим лордам." }, { 4.53, "Молодец, храбрый солдат Альянса!" }, { 7.19, "Отличная работа." } } } } },
    [5103] = { d = 17.3, v = "narrator", n = { x = 187 }, c = { x = { { 0.00, "От человека остался только обугленный скелет." }, { 3.53, "Похоже, он умер буквально на расстоянии вытянутой руки от того, что пытался схватить, – неопалимых латных рукавиц." }, { 12.31, "Может, вам стоит забрать рукавицы и попробовать выбраться из огня?" } } }, t = { d = 1.5, v = "dwarf-male", n = { x = 8 }, c = { x = { { 0.00, "Что это за..." } } } } },
    [5121] = { d = 40.2, v = "dwarf-female#34", n = { x = 449 }, c = { x = { { 0.00, "Хотя нам по-прежнему известно очень мало о том, зачем фурболги используют эту странную субстанцию, я думаю, что лучше всего положить конец всему этому, пока ситуация не вышла из-под контроля." }, { 14.00, "Фурболги племени Зимней Спячки демонстрируют ненормальный уровень агрессии, и эта перемена в их поведении заставляет меня думать, что они, должно быть, выполняют приказ своего вождя." }, { 27.23, "Скорее всего, мы не можем исправить тот вред, что уже нанесён, но я думаю, если их вождь будет убит, хуже они уж точно не станут." }, { 36.54, "Тебе нужно идти на восток, в деревню Зимней Спячки." } } }, t = { d = 11.7, v = "dwarf-female#34", n = { x = 129 }, c = { x = { { 0.00, "Большое тебе спасибо." }, { 1.68, "Я надеюсь, что смогу вернуться к своим исследованиям, не опасаясь нападения из засады." }, { 8.06, "Пожалуйста, прими это от меня в качестве награды." } } } } },
    [5122] = { t = { d = 15.8, g = 1, v = "human-male#50", n = { m = 170, f = 172 }, c = { m = { { 0.00, "Ты принёс медальон!" }, { 1.43, "Теперь я смогу наконец покинуть священные стены и исполнить свой долг!" }, { 6.76, "Я должен убить чудовище, из-за которого скверна поразила меня и многих моих братьев и сестёр!" }, { 13.94, "Имя его – барон Ривендер." } }, f = { { 0.00, "Ты принесла медальон!" }, { 1.59, "Теперь я смогу наконец покинуть священные стены и исполнить свой долг!" }, { 6.78, "Я должен убить чудовище, из-за которого скверна поразила меня и многих моих братьев и сестёр!" }, { 13.75, "Имя его – барон Ривендер." } } } } },
    [5123] = { d = 21.4, v = "narrator", n = { x = 214 }, c = { x = { { 0.00, "Записи, которые вы нашли у верховного вождя, кажутся обширными, но просмотрев пару страниц, вы понимаете, что не можете прочитать написанное." }, { 11.38, "Все заметки написаны так коряво, что вы сомневаетесь, что кто-либо сможет что-то понять в них." }, { 18.89, "Но, может быть, Донова сможет?.." } } }, t = { d = 4.1, v = "dwarf-female#34", n = { x = 36 }, c = { x = { { 0.00, "Что бы это значило?" }, { 1.83, "Ничего не могу разобрать…" } } } } },
    [5124] = { d = 32.9, v = "dwarf-male", n = { x = 375 }, c = { x = { { 0.00, "Клянусь бородой Тауриссана!" }, { 1.95, "Откуда они у тебя?" }, { 3.33, "И, что ещё важнее, сможешь ли ты с ними расстаться?" }, { 6.84, "Само собой, я заплатил бы за столь благородный жест." }, { 10.42, "Вот что я тебе скажу." }, { 11.93, "Если отдашь мне эти неопалимые рукавицы, я научу тебя, как сделать себе пару хороших рукавиц." }, { 18.58, "Всё, что тебе нужно сделать – собрать для меня необходимое, чтобы я мог предложить тебе точный рецепт." }, { 25.74, "Договорились??" }, { 26.74, "Вот список того, что мне нужно." }, { 28.94, "С тебя – рукавицы, а я пока займусь незачарованным торием." } } }, t = { d = 9.8, v = "dwarf-male", n = { x = 91 }, c = { x = { { 0.00, "Как я и обещал, вот ваш рецепт!" }, { 2.53, "Я также добавлю кое-что от себя за ваши труды и самоотдачу." }, { 7.53, "А то просто девать некуда!.." } } } } },
    [5125] = { t = { d = 12.6, g = 1, v = "human-male#50", n = { m = 105, f = 105 }, c = { m = { { 0.00, "Я умираю... но моя душа спасена." }, { 2.74, "За это я обязан тебе больше, чем можно выразить словами." }, { 7.49, "Прошу, возьми это... и сражайся дальше, отважный герой!" } }, f = { { 0.00, "Я умираю... но моя душа спасена." }, { 2.83, "За это я обязан тебе больше, чем можно выразить словами." }, { 7.74, "Прошу, возьми это... и сражайся дальше, отважная героиня!" } } } } },
    [5126] = { d = 7.2, v = "narrator", n = { x = 74 }, c = { x = { { 0.00, "Сатир расхаживает туда-сюда и разговаривает сам с собой." }, { 4.59, "Решитесь ли вы задать ему вопрос?" } } }, t = { d = 1.6, v = "creature/satyr", n = { x = 13 }, c = { x = { { 0.00, "Ха-ха-ха!" } } } } },
    [5127] = { d = 36.8, v = "creature/satyr", n = { x = 319 }, c = { x = { { 0.00, "Лоракс заключает сделки, да, но он не имеет дел с никчёмными смертными." }, { 6.28, "С тобой, однако, я сделку заключу... возьми эту пику, она усилена мощной энергией скверны." }, { 14.69, "Когда найдёшь Горалука Треснувшую Наковальню, убей его и проткни этой пикой его остывающее сердце." }, { 23.74, "Он продал свою душу, и она будет моей." }, { 27.42, "Верни мне пику, а также кирасу, которую похитил этот вор, и я научу тебя тому, чему хотел научиться он." } } }, t = { d = 6.4, g = 1, v = "creature/satyr", n = { m = 43, f = 44 }, c = { m = { { 0.00, "Ты не нарушил договора." }, { 2.69, "Душу я забрал." }, { 4.46, "Награду я отдам." } }, f = { { 0.00, "Ты не нарушила договора." }, { 2.82, "Душу я забрал." }, { 4.60, "Награду я отдам." } } } } },
    [5128] = { d = 34.8, v = "dwarf-female#34", n = { x = 403 }, c = { x = { { 0.00, "Племя Зимней Спячки больше не представляет для меня угрозы, но если тебе по-прежнему хочется выяснить, что побудило фурболгов готовить и использовать эту странную огненную воду, думаю, тебе стоит поискать Келека Стража Неба." }, { 16.19, "Он принадлежит к группе, известной как Изумрудный Круг – это группа друидов, посвятивших себя работе над исцелением Осквернённого леса от порчи." }, { 26.34, "Келек много работал с фурболгами – может быть, он сможет больше меня рассказать об этих записях." }, { 33.27, "И ещё раз спасибо тебе." } } }, t = { d = 21.8, v = "nightelf-male#54", n = { x = 230 }, c = { x = { { 0.00, "Да, если дадите мне немного времени, я, может быть, смогу перевести для вас то, что тут написано." }, { 7.68, "*Келек пролистывает страницы.*" }, { 10.00, "Когда я смогу внимательно всё просмотреть, я вам сообщу." }, { 14.25, "Спасибо, что поделились этим со мной." }, { 17.06, "О фурболгах из племени Зимней Спячки нет почти никаких сведений." } } } } },
    [5141] = { d = 34.7, g = 1, v = "human-male", n = { m = 387, f = 387 }, c = { m = { { 0.00, "Кожевничество школы чешуи драконов – непростое ремесло, однако весьма прибыльное." }, { 6.01, "Я научу тебя изготовлять отличные кольчужные доспехи, но при одном условии." }, { 11.56, "Выбрав этот путь, ты откажешься от изучения школ традиций предков и силы стихий." }, { 17.43, "На пути к вершине мастерства ты должен выбрать лишь одну из трёх." }, { 22.19, "Кроме того, я должен взглянуть на лучшие твои работы – в том числе на доспехи скорпида." }, { 28.66, "И наконец, докажи мне, что ты способен добыть основу нашего ремесла – чешую дракона." } }, f = { { 0.00, "Кожевничество школы чешуи драконов – непростое ремесло, однако весьма прибыльное." }, { 5.87, "Я научу тебя изготовлять отличные кольчужные доспехи, но при одном условии." }, { 11.29, "Выбрав этот путь, ты откажешься от изучения школ традиций предков и силы стихий." }, { 17.03, "На пути к вершине мастерства ты должна выбрать лишь одну из трёх." }, { 21.68, "Кроме того, я должен взглянуть на лучшие твои работы – в том числе на доспехи скорпида." }, { 28.00, "И наконец, докажи мне, что ты способна добыть основу нашего ремесла – чешую дракона." } } }, t = { d = 14.8, g = 1, v = "human-male", n = { m = 168, f = 170 }, c = { m = { { 0.00, "Ты принял важное решение." }, { 1.84, "Уверяю тебя, ты не пожалеешь о том, что выбрал школу чешуи драконов – это очень выгодное ремесло." }, { 8.74, "Чтобы получить новые знания, просто побеседуй со мной, и я расскажу всё, что тебе нужно." } }, f = { { 0.00, "Ты приняла важное решение." }, { 1.85, "Уверяю тебя, ты не пожалеешь о том, что выбрала школу чешуи драконов – это очень выгодное ремесло." }, { 8.65, "Чтобы получить новые знания, просто побеседуй со мной, и я расскажу всё, что тебе нужно." } } } } },
    [5142] = { d = 28.0, g = 1, v = "human-female", n = { m = 298, f = 298 }, c = { m = { { 0.00, "Многие погибли во время битвы при Дарроушире... и многие, избежавшие смерти, позавидовали мёртвым." }, { 6.90, "Когда битва началась, я спрятала мою племянницу Памелу и теперь не знаю, жива ли она." }, { 13.10, "Я всего лишь странствующий дух, но моё сердце жаждет знать, всё ли у неё хорошо." }, { 18.59, "Пожалуйста, добрый герой, не поищешь ли ты мою племянницу в Дарроушире?" }, { 23.64, "Это к востоку отсюда, за пустошью Гаррона." } }, f = { { 0.00, "Многие погибли во время битвы при Дарроушире... и многие, избежавшие смерти, позавидовали мёртвым." }, { 7.09, "Когда битва началась, я спрятала мою племянницу Памелу и теперь не знаю, жива ли она." }, { 14.02, "Я всего лишь странствующий дух, но моё сердце жаждет знать, всё ли у неё хорошо." }, { 19.67, "Пожалуйста, добрая героиня, не поищешь ли ты мою племянницу в Дарроушире?" }, { 24.99, "Это к востоку отсюда, за пустошью Гаррона." } } }, t = { d = 2.8, v = "child-female", n = { x = 19 }, c = { x = { { 0.00, "Привет, я Памела." }, { 1.99, "А ты кто?" } } } } },
    [5143] = { d = 29.8, g = 1, v = "nightelf-female#52", n = { x = 347 }, c = { m = { { 0.00, "Чтобы постичь школу традиций предков, следует обрести понимание подлинной сути дикой природы." }, { 6.63, "Я знаю, что ты уже владеешь искусством изготовления дикарского кожаного доспеха, и хочу завершить твоё обучение." }, { 14.38, "Знай, герой: избрав этот путь, ты отказываешься от изучения школ чешуи драконов и силы стихий, изучать можно только одну из них." }, { 23.27, "А теперь принеси мне свои лучшие дикарские кожаные доспехи." }, { 27.46, "С них мы и начнём твоё обучение." } }, f = { { 0.00, "Чтобы постичь школу традиций предков, следует обрести понимание подлинной сути дикой природы." }, { 6.67, "Я знаю, что ты уже владеешь искусством изготовления дикарского кожаного доспеха, и хочу завершить твоё обучение." }, { 14.48, "Знай, героиня: избрав этот путь, ты отказываешься от изучения школ чешуи драконов и силы стихий, изучать можно только одну из них." }, { 23.54, "А теперь принеси мне свои лучшие дикарские кожаные доспехи." }, { 27.76, "С них мы и начнём твоё обучение." } } }, t = { d = 17.8, g = 1, v = "nightelf-female#52", n = { m = 203, f = 204 }, c = { m = { { 0.00, "Ты пожертвовал лучшее, что у тебя было, и вскоре природа отплатит тебе сторицей." }, { 5.67, "Когда мы завершим твоё обучение, силы природы покорятся тебе." }, { 10.02, "В будущем, чтобы улучшить своё мастерство, просто обратись ко мне, и я сообщу тебе всё, что ты захочешь знать." } }, f = { { 0.00, "Ты пожертвовала лучшее, что у тебя было, и вскоре природа отплатит тебе сторицей." }, { 5.84, "Когда мы завершим твоё обучение, силы природы покорятся тебе." }, { 10.28, "В будущем, чтобы улучшить своё мастерство, просто обратись ко мне, и я сообщу тебе всё, что ты захочешь знать." } } } } },
