    [5149] = { d = 32.9, v = "child-female", n = { x = 299 }, c = { x = { { 0.00, "Тётушка Марлен сказала мне, что я должна остаться дома, пока папа на войне." }, { 6.41, "Мой папа – самый смелый в мире!" }, { 9.16, "Но я здесь уже так долго, а он всё не приходит за мной." }, { 13.66, "Иногда сюда приходят злые люди и шепчут." }, { 17.24, "Я так хочу, чтобы папа прогнал их, но его всё нет и нет..." }, { 22.13, "А иногда, когда стемнеет, мне так хочется поиграть с моей куклой, но её тоже нет, она осталась в городе." }, { 30.98, "Принесёшь мне мою куклу?" } } }, t = { d = 3.0, g = 1, v = "child-female", n = { m = 18, f = 18 }, c = { m = { { 0.00, "Ты нашёл мою куклу!" }, { 2.41, "Ура!" } }, f = { { 0.00, "Ты нашла мою куклу!" }, { 2.50, "Ура!" } } } } },
    [5150] = { t = { d = 10.3, v = "narrator", n = { x = 124 }, c = { x = { { 0.00, "Даданга с видимым удовольствием принюхивается к побегам." }, { 4.13, "В благодарность за лакомство она подталкивает к вам носом маленький коричневый свёрток." } } } } },
    [5151] = { d = 26.4, v = "goblin-male", n = { x = 294 }, c = { x = { { 0.00, "На наш караван напали кентавры, и выжить удалось только мне!" }, { 4.39, "А самый лучший мой механизм висел на шее могучей пантеры-охранницы!" }, { 9.37, "Даже кентавры дрожали, увидев эту зверюгу!" }, { 12.58, "Вот ключ от её клетки." }, { 14.16, "Они забрали всё, а ключ оставили." }, { 16.58, "Убей пантеру, принеси мне мой гипервместитель, а я хорошо заплачу за него." }, { 21.96, "То, что осталось от нашего каравана, находится к северу отсюда." } } }, t = { d = 7.8, v = "goblin-male", n = { x = 77 }, c = { x = { { 0.00, "Мой гипервместитель!" }, { 1.57, "Ну всё, теперь с места не сойду, пока не разберусь, зачем же эта штука нужна..." } } } } },
    [5152] = { d = 29.0, g = 1, v = "child-female", n = { m = 260, f = 261 }, c = { m = { { 0.00, "О, я так одинока!" }, { 1.48, "Где моя семья?" }, { 2.81, "Тётушка Марлен велела мне ждать здесь, ушла и не вернулась." }, { 7.81, "А ты случайно не видел моего папу?" }, { 10.85, "Может, тётушка Марлен знает, где он." }, { 13.97, "Она живёт рядом с Андоралом, у неё домик на самом юге." }, { 18.74, "Вроде бы он на холме... да, она говорила, что на холме." }, { 23.50, "Пожалуйста!" }, { 24.51, "Мы же с тобой теперь друзья?" }, { 27.01, "Поговори с моей тётушкой!" } }, f = { { 0.00, "О, я так одинока!" }, { 1.46, "Где моя семья?" }, { 2.77, "Тётушка Марлен велела мне ждать здесь, ушла и не вернулась." }, { 7.70, "А ты случайно не видела моего папу?" }, { 10.78, "Может, тётушка Марлен знает, где он." }, { 13.86, "Она живёт рядом с Андоралом, у неё домик на самом юге." }, { 18.56, "Вроде бы он на холме... да, она говорила, что на холме." }, { 23.26, "Пожалуйста!" }, { 24.26, "Мы же с тобой теперь друзья?" }, { 26.72, "Поговори с моей тётушкой!" } } }, t = { d = 19.0, g = 1, v = "human-female", n = { m = 187, f = 188 }, c = { m = { { 0.00, "Ты видел Памелу?" }, { 1.26, "Она жива?" }, { 2.05, "О, нет!" }, { 2.58, "Бедная моя девочка!" }, { 4.10, "Она была так мала, так весела и шаловлива..." }, { 7.41, "Она ведь не знает, что стало с её отцом?" }, { 10.39, "С моим братом Джозефом?" }, { 12.18, "Она едва ли сможет это понять..." }, { 14.70, "А даже если бы и могла, я не в силах сказать ей об этом." } }, f = { { 0.00, "Ты видела Памелу?" }, { 1.34, "Она жива?" }, { 2.15, "О, нет!" }, { 2.68, "Бедная моя девочка!" }, { 4.23, "Она была так мала, так весела и шаловлива..." }, { 7.58, "Она ведь не знает, что стало с её отцом?" }, { 10.60, "С моим братом Джозефом?" }, { 12.41, "Она едва ли сможет это понять..." }, { 14.96, "А даже если бы и могла, я не в силах сказать ей об этом." } } } } },
    [5153] = { d = 33.8, v = "human-female", n = { x = 360 }, c = { x = { { 0.00, "Увы, Джозефу не дано воссоединиться с дочерью." }, { 3.46, "Его душа была искажена Плетью, он сам стал чудовищем." }, { 7.46, "Как жестока судьба!" }, { 8.92, "И всё же судьбу можно изменить." }, { 11.25, "Отправляйся к его монументу и обыщи окрестные могилы." }, { 15.25, "Тела самого Джозефа там нет, однако где-то под монументом лежит его обручальное кольцо." }, { 22.58, "Отнеси кольцо Хроми." }, { 24.18, "Это странная гномесса... с весьма странными способностями." }, { 28.51, "Хроми живёт в развалинах таверны в северо-западной части Андорала." } } }, t = { d = 17.8, g = 1, v = "creature/chromie", n = { m = 176, f = 177 }, c = { m = { { 0.00, "Что это, обручальное кольцо?" }, { 2.32, "Дай-ка взглянуть..." }, { 3.92, "Когда-то оно принадлежало великому человеку, однако с ним связано великое зло..." }, { 10.37, "Ты хочешь помочь ему?" }, { 12.18, "Поздновато собрался, а впрочем... возможно, мы сможем изменить прошлое!" } }, f = { { 0.00, "Что это, обручальное кольцо?" }, { 2.28, "Дай-ка взглянуть..." }, { 3.85, "Когда-то оно принадлежало великому человеку, однако с ним связано великое зло..." }, { 10.19, "Ты хочешь помочь ему?" }, { 11.97, "Поздновато собралась, а впрочем... возможно, мы сможем изменить прошлое!" } } } } },
    [5154] = { d = 19.2, v = "creature/chromie", n = { x = 197 }, c = { x = { { 0.00, "Чтобы спасти Джозефа Редпата, придётся обратиться к его прошлому." }, { 5.21, "Надо прочитать, что говорится о нём в Анналах Дарроушира – книге, хранящейся в ратуше Андорала." }, { 12.71, "Принеси мне книгу." }, { 14.21, "Мы узнаем о судьбе Джозефа и, если повезёт сможем... изменить её." } } }, t = { d = 26.2, g = 1, v = "creature/chromie", n = { m = 267, f = 267 }, c = { m = { { 0.00, "Прекрасно, ты нашёл её!" }, { 1.78, "Что в ней говорится?" }, { 3.35, "Там упоминается Джозеф Редпат?" }, { 5.78, "Если да, то мы сможем спасти его!" }, { 8.49, "О..." }, { 8.84, "В Анналах Дарроушира говорится, что во время битвы Джозеф Редпат пал жертвой порчи и примкнул к войскам Плети, предав защитников Дарроушира!" }, { 19.97, "Что за горькая судьба!" }, { 21.75, "Думаю, мы должны приложить все усилия, чтобы изменить её." } }, f = { { 0.00, "Прекрасно, ты нашла её!" }, { 1.82, "Что в ней говорится?" }, { 3.35, "Там упоминается Джозеф Редпат?" }, { 5.72, "Если да, то мы сможем спасти его!" }, { 8.38, "О..." }, { 8.73, "В Анналах Дарроушира говорится, что во время битвы Джозеф Редпат пал жертвой порчи и примкнул к войскам Плети, предав защитников Дарроушира!" }, { 19.62, "Что за горькая судьба!" }, { 21.36, "Думаю, мы должны приложить все усилия, чтобы изменить её." } } } } },
    [5155] = { d = 38.9, v = "tauren-female#71", n = { x = 389 }, c = { x = { { 0.00, "Если уж мне придётся положиться на тебя в этом деле, то прежде заслужи доверие." }, { 6.49, "Я должна точно знать, что ты – враг Совета Теней, тех, кто в ответе за великие злодеяния здесь и за границами леса." }, { 15.72, "Отправляйся в чащу Осквернённого леса." }, { 18.82, "На западе ты увидишь тропинку в Джеденар." }, { 22.21, "Именно там Совет строит свои козни вместе с Пылающим Легионом." }, { 27.45, "Проникни в недра одной из населённых ими осквернённых Обителей и перебей их." }, { 33.57, "Потом вернись ко мне." }, { 35.34, "Тогда я увижу, что ты искренне помогаешь нам." } } }, t = { d = 25.0, g = 1, v = "tauren-female#71", n = { m = 249, f = 251 }, c = { m = { { 0.00, "Хорошо!" }, { 0.64, "Теперь, когда они уменьшились числом, мы усилим натиск." }, { 5.10, "Ну, попробовал их мощь?" }, { 6.87, "И как тебе?" }, { 7.79, "Они оказались так же сильны, как ты предполагал?" }, { 11.55, "Или сильнее?" }, { 12.61, "Или, может, они тебе вообще не противники?" }, { 16.08, "Разве это не здорово?" }, { 17.85, "Мы сможем обсудить подробности твоих подвигов чуть позже." }, { 22.38, "Сейчас у нас другие дела есть." } }, f = { { 0.00, "Хорошо!" }, { 0.64, "Теперь, когда они уменьшились числом, мы усилим натиск." }, { 5.15, "Ну, попробовала их мощь?" }, { 7.01, "И как тебе?" }, { 7.94, "Они оказались так же сильны, как ты предполагала?" }, { 11.81, "Или сильнее?" }, { 12.88, "Или, может, они тебе вообще не противники?" }, { 16.39, "Разве это не здорово?" }, { 18.18, "Мы сможем обсудить подробности твоих подвигов чуть позже." }, { 22.76, "Сейчас у нас другие дела есть." } } } } },
    [5156] = { d = 42.7, g = 1, v = "tauren-male#68", n = { m = 398, f = 398 }, c = { m = { { 0.00, "На севере отсюда, если идти по восточной дороге, лежит так называемая долина Рваных Ран." }, { 7.42, "Это то место, где во время последней великой войны призывали инферналов." }, { 13.48, "Там до сих пор поганят землю кратеры – да и сами инферналы." }, { 18.35, "Я хочу узнать две вещи." }, { 20.37, "Во-первых, шляются ли там до сих пор эти энтропийные духи?" }, { 25.17, "И второе – заполнены ли до сих пор эти кратеры поганой вонючей водой, что скапливалась в них долгие годы?" }, { 33.85, "Поможешь ли ты мне это узнать?" }, { 36.40, "Но будь осторожен – инферналы уничтожают всё на своём пути." } }, f = { { 0.00, "На севере отсюда, если идти по восточной дороге, лежит так называемая долина Рваных Ран." }, { 7.72, "Это то место, где во время последней великой войны призывали инферналов." }, { 14.03, "Там до сих пор поганят землю кратеры – да и сами инферналы." }, { 19.10, "Я хочу узнать две вещи." }, { 21.21, "Во-первых, шляются ли там до сих пор эти энтропийные духи?" }, { 26.19, "И второе – заполнены ли до сих пор эти кратеры поганой вонючей водой, что скапливалась в них долгие годы?" }, { 35.24, "Поможешь ли ты мне это узнать?" }, { 37.89, "Но будь осторожна – инферналы уничтожают всё на своём пути." } } }, t = { d = 37.2, v = "tauren-male#68", n = { x = 362 }, c = { x = { { 0.00, "Хорошо, что тебе удалось остаться в живых." }, { 3.56, "Плохо, что вода ещё там." }, { 5.57, "Я надеялся найти хоть один чистый источник воды в Осквернённом лесу." }, { 11.21, "Похоже, тут я потерпел неудачу." }, { 13.81, "Будь у нас такой источник, куда проще было бы исцелять землю." }, { 18.94, "Придётся заняться спасением тех лесных существ, что ещё можно спасти, по ходу дела истребляя тех, в которых порча зашла так далеко, что они сами стали угрозой и для себя, и для всех, кто оказался в этом некогда великом лесу." } } } } },
    [5157] = { d = 37.7, v = "tauren-female#71", n = { x = 395 }, c = { x = { { 0.00, "Глубоко в недрах Джеденара лежит Оплот Теней – главный оплот порчи и зла." }, { 5.81, "Совет Теней окружил своё логово защитными заклятьями, заключёнными в жаровнях." }, { 11.84, "Если уж мне выпала задача узнать побольше о нашем враге путём магического наблюдения, то тогда мне надо будет, чтобы кто-то потушил эти жаровни." }, { 23.19, "Тогда я смогу тайно понаблюдать за Советом и выяснить, кто его возглавляет." }, { 29.07, "Если сможешь – возьми эту флягу и наполни её водой из лунного колодца в центре Джеденара." }, { 36.15, "Потом вернись ко мне." } } }, t = { d = 14.6, v = "tauren-female#71", n = { x = 149 }, c = { x = { { 0.00, "Это то, что надо." }, { 1.46, "Теперь нам остаётся только очистить воду и залить ей жаровни." }, { 6.44, "Это будет нетрудно – придётся только совершить небольшое путешествие." }, { 12.08, "Надеюсь, это мы провернём быстро." } } } } },
    [5158] = { d = 36.7, v = "tauren-female#71", n = { x = 351 }, c = { x = { { 0.00, "Отнеси эту осквернённую воду в Степи." }, { 3.14, "К югу от Кабестана на побережье скрытно живёт моя старая приятельница, шаманка по имени Ислен Заклинатель Воды." }, { 12.39, "Она может нам помочь." }, { 14.26, "Её узы с духами воды всегда были крепки." }, { 17.77, "Наша цель благородна – и этого будет достаточно, чтобы убедить её и духов воды помочь нам в нашем деле." }, { 26.42, "Ищи её в маленьком лагере прямо у кромки воды." }, { 30.38, "А на пиратов внимания не обращай... это всё мелочи жизни, тебе они не угроза." } } }, t = { d = 26.3, v = "tauren-female#71", n = { x = 258 }, c = { x = { { 0.00, "А, так тебе надо очистить воду из этого Лунного колодца." }, { 4.68, "Благородное дело – остановить порчу, пожирающую Осквернённый лес, но не от меня зависит, очистится ли вода." }, { 13.24, "Я спрошу духов воды – это им решать, справедливо ли ваше дело." }, { 18.43, "Подожди минутку, и я передам им твою просьбу." }, { 22.16, "Надеюсь, они проникнутся к тебе сочувствием, как и я." } } } } },
    [5159] = { d = 29.5, v = "tauren-female#71", n = { x = 255 }, c = { x = { { 0.00, "Благодари духов." }, { 1.53, "Это они, а не я, помогли тебе." }, { 4.36, "Ныне я отдаю тебе эту очищенную воду." }, { 7.90, "Передай Грете мой поклон и мои наилучшие пожелания." }, { 12.58, "Она нащупала нечто более важное, чем сумели многие из нас... я уверена, что она вскоре всё узнает." }, { 21.45, "С Советом Теней шутки плохи." }, { 24.12, "Запомни это." }, { 25.33, "Теперь ступай." }, { 26.70, "Бери воду и возвращайся к Грете." } } }, t = { d = 22.5, v = "tauren-female#71", n = { x = 214 }, c = { x = { { 0.00, "Этой воды для наших целей хватит с избытком." }, { 3.78, "Рада слышать, что Ислен смогла нам помочь." }, { 7.35, "Её связь с водными духами была всегда прочной." }, { 11.21, "К тому же, она мудра, и духи редко не одобряют её цели." }, { 15.88, "То, что оба они благословили наше дело, даёт мне надежду, что мы идём верным путём." } } } } },
    [5160] = { d = 34.8, g = 1, v = "child-male", n = { x = 380 }, c = { m = { { 0.00, "Тебе придётся отправиться в Калимдор, герой." }, { 3.24, "Наша стая сейчас поселилась на холодных просторах Зимних Ключей." }, { 8.06, "Когда доберёшься туда, отправляйся в пещеры Маз-Торил." }, { 12.02, "На ледяном полу в пещерах ты найдёшь письмена из кобальтовых рун." }, { 16.71, "Сожми в руке пластинку моей чешуи, встань на руну – и перенесешься к Халех, нашей матроне-защитнице." }, { 24.42, "Отдай ей пластинку моей чешуи." }, { 26.73, "Халех посмотрит в неё, как в магический кристалл, и увидит всё, что я видел и чувствовал в этом проклятом месте." } }, f = { { 0.00, "Тебе придётся отправиться в Калимдор, героиня." }, { 3.34, "Наша стая сейчас поселилась на холодных просторах Зимних Ключей." }, { 8.12, "Когда доберёшься туда, отправляйся в пещеры Маз-Торил." }, { 12.05, "На ледяном полу в пещерах ты найдёшь письмена из кобальтовых рун." }, { 16.70, "Сожми в руке пластинку моей чешуи, встань на руну – и перенесешься к Халех, нашей матроне-защитнице." }, { 24.64, "Отдай ей пластинку моей чешуи." }, { 26.93, "Халех посмотрит в неё, как в магический кристалл, и увидит всё, что я видел и чувствовал в этом проклятом месте." } } }, t = { d = 13.1, v = "bloodelf-female", n = { x = 154 }, c = { x = { { 0.00, "Аспекты настойчиво утверждают, что нам не следует вмешиваться в дела смертных." }, { 5.59, "Но иногда всё-таки надо вмешаться – особенно когда кто-то из наших сородичей пренебрегает указами старших." } } } } },
    [5161] = { d = 32.1, v = "bloodelf-female", n = { x = 345 }, c = { x = { { 0.00, "Мы понимаем, что пытается сделать проклятое порождение Смертокрыла, и мы знаем, что этого нельзя допустить." }, { 8.09, "Но из-за Чёрной горы, которая защищает Нефариана, вмешательство стало для нас невероятно трудным." }, { 15.43, "Однако, мы можем дать силу тебе, смертному существу, если ты решишься на это." }, { 21.39, "Лежащий перед тобой путь полон опасностей." }, { 24.69, "Примешь ли ты нашу помощь, решать тебе." }, { 27.77, "Обдумай это и поговорим ещё раз, когда ты примешь решение." } } }, t = { d = 1.5, v = "bloodelf-female", n = { x = 10 }, c = { x = { { 0.00, "Да будет так…" } } } } },
    [5162] = { d = 25.1, g = 1, v = "bloodelf-female", n = { m = 249, f = 250 }, c = { m = { { 0.00, "Тайные силы контролирую я, и ради тайных сил пошлю я тебя к твоему следующему деянию." }, { 7.07, "Когда будешь готов, начнётся твоё путешествие." }, { 10.83, "В Чумные земли лежит твой путь, и с Джезибой надлежит тебе говорить." }, { 16.43, "Это смертный, мудрый, как древние предки, и терпеливый, как сама недвижная земля." }, { 23.14, "Ты найдёшь его в Андорале." } }, f = { { 0.00, "Тайные силы контролирую я, и ради тайных сил пошлю я тебя к твоему следующему деянию." }, { 6.90, "Когда будешь готова, начнётся твоё путешествие." }, { 10.63, "В Чумные земли лежит твой путь, и с Джезибой надлежит тебе говорить." }, { 16.09, "Это смертный, мудрый, как древние предки, и терпеливый, как сама недвижная земля." }, { 22.63, "Ты найдёшь его в Андорале." } } }, t = { d = 6.7, v = "bloodelf-male", n = { x = 61 }, c = { x = { { 0.00, "Я Джезиба, многим известный как Скульптор." }, { 3.76, "Правда ваяю я не статуи, а героев." } } } } },
    [5163] = { d = 32.2, v = "goblin-female#63", n = { x = 355 }, c = { x = { { 0.00, "Всё готово!" }, { 0.86, "Итак, я уже сообщила по почте моим друзьям, что у меня для них сюрприз." }, { 6.12, "И тут на сцену выходишь ты!" }, { 8.10, "Я дам тебе моего механического йети, а тебе нужно будет удивить их, нанеся визит каждому, включив йети и послав его по направлению к ним." }, { 18.23, "Когда покажешь моё изделие Легакки в Круговзоре, Поливалке в Прибамбасске и Квикксилю в Укрытии Маршалла, возвращайся и расскажи мне, как всё было!" }, { 28.83, "И моего йети тоже, пожалуйста, приведи обратно." } } }, t = { d = 9.8, v = "goblin-female#63", n = { x = 105 }, c = { x = { { 0.00, "Ха!" }, { 0.27, "Они теперь дважды подумают, прежде чем снова высмеивать мои идеи!" }, { 5.36, "Спасибо за помощь." }, { 6.79, "Без тебя мне не удалось бы так развлечься!" } } } } },
    [5164] = { d = 14.9, v = "bloodelf-male", n = { x = 159 }, c = { x = { { 0.00, "Халех не могла отыскать лучшего орудия справедливости." }, { 4.17, "Прочти перечень Заблудших и обрети просветление." }, { 7.86, "Если ты выстоишь..." }, { 9.36, "Если ты сделаешь то, о чём тебя просят и выживешь..." }, { 13.32, "Из тебя выйдет герой." } } }, t = { d = 6.5, v = "narrator", n = { x = 67 }, c = { x = { { 0.00, "Книга состоит по большей части из сотен страниц, исписанных словами и символами." } } } } },
    [5165] = { d = 27.8, v = "tauren-female#71", n = { x = 290 }, c = { x = { { 0.00, "Теперь тебе надо вернуться в Джеденар." }, { 3.05, "Эти жаровни скорее всего расставлены в Оплоте Теней." }, { 7.20, "Загаси их пламя, и защита, возведённая Советом, хотя бы на некоторое время падёт." }, { 13.37, "Я буду ждать этого мгновения." }, { 15.65, "Когда оно настанет, я загляну в недра оплота и попытаюсь узнать, кто стоит во главе всего этого." }, { 23.20, "Тогда – и только тогда – мы попытаемся атаковать их напрямую." } } }, t = { d = 21.9, v = "tauren-female#71", n = { x = 226 }, c = { x = { { 0.00, "Я сумела увидеть тебя при помощи своих заклинаний, как только погасли жаровни." }, { 6.31, "Славная работа." }, { 7.60, "И я успела кое-что узнать прежде, чем чернокнижники Совета Теней восстановили свои заклинания." }, { 15.12, "Надеюсь, этого будет достаточно." }, { 17.77, "Теперь отдыхай." }, { 19.06, "Я сейчас расскажу тебе, что я узнала." } } } } },
    [5166] = { d = 31.3, v = "narrator", n = { x = 339 }, c = { x = { { 0.00, "По иронии судьбы, на изготовление мощной кирасы, призванной защитить от нападения всецветных драконов, идут их собственные шкуры." }, { 9.94, "На безупречную шкуру всецветного дракона нашивают их же чешую." }, { 14.74, "В настоящий момент этих тварей не существует, и хочется верить, что и не будет." }, { 20.86, "Последний компонент, который труднее всего достать – это кровь героев." }, { 26.35, "И наконец, из этих компонентов Скульптор создаёт подлинный шедевр." } } }, t = { d = 17.0, g = 1, v = "bloodelf-male", n = { m = 163, f = 164 }, c = { m = { { 0.00, "Неужели ты не понимаешь?" }, { 2.07, "Сам путь и был целью." }, { 3.84, "Неужели тебя не тревожат шрамы?" }, { 6.60, "И боль забыта?" }, { 7.83, "Выстояв в испытании, ты сделался сильнее." }, { 11.36, "Гораздо сильнее." }, { 12.82, "И кираса – лишь внешнее проявление внутренней мощи." } }, f = { { 0.00, "Неужели ты не понимаешь?" }, { 2.03, "Сам путь и был целью." }, { 3.77, "Неужели тебя не тревожат шрамы?" }, { 6.48, "И боль забыта?" }, { 7.69, "Выстояв в испытании, ты сделалась сильнее." }, { 11.23, "Гораздо сильнее." }, { 12.66, "И кираса – лишь внешнее проявление внутренней мощи." } } } } },
    [5167] = { d = 18.3, v = "narrator", n = { x = 185 }, c = { x = { { 0.00, "На изготовление этих поножей идут чешуйки взрослых всецветных драконов." }, { 6.13, "Переливчатую чешую закрепляют на проволочной основе и зачаровывают, окропляя кровью героев." }, { 13.88, "В конце следует обтянуть поножи изнутри Шкурой Тени." } } }, t = { d = 7.4, v = "bloodelf-male", n = { x = 79 }, c = { x = { { 0.00, "Когда ты войдёшь в их чертоги, они почуют запах павших братьев." }, { 4.99, "Пусть страх станет твоим оружием!" } } } } },
    [5168] = { d = 33.0, v = "human-male#50", n = { x = 367 }, c = { x = { { 0.00, "Герои Дарроушира навсегда поселились в моём сердце, а эта книга, Анналы Дарроушира, рассказывает об их жизни." }, { 8.10, "Здесь рассказывается о паладине Дейвиле Яркосвете и о том, как Алый Марш забрал его манускрипт в ратушу Дольного Очага." }, { 16.86, "Здесь также говорится о моём брате, капитане Редпате." }, { 20.81, "После его предательства, его щит раскололся и развалился на куски, и теперь лежит в самом неожиданном месте – рядом с амбаром в пустоши Гаррона." }, { 31.58, "Собери эти реликвии." } } }, t = { d = 8.3, v = "human-male#50", n = { x = 78 }, c = { x = { { 0.00, "Это книга и щит!" }, { 1.44, "Они тесно связаны с историей Дарроушира, и я уверен – эта история ещё не закончена." } } } } },
    [5181] = { d = 33.0, v = "human-male#50", n = { x = 372 }, c = { x = { { 0.00, "В Анналах Дарроушира упоминается о самых мерзких воинах, бившихся в том сражении." }, { 5.91, "Там рассказывается о том, как Альянс разбил силы лорда Хоргуса Опустошителя." }, { 11.43, "Тело его было брошено в озеро к северо-западу от Перекрёстка Корина, и череп его поныне там." }, { 18.20, "Мардук Чёрный так и не был побеждён, но его легендарный меч был сломан и потерян." }, { 23.92, "Он лежит на дне ущелья к западу от Перекрёстка Корина." }, { 27.80, "Принеси мне эти предметы." }, { 29.70, "Не знаю почему, но твоя судьба связана с ними." } } }, t = { d = 14.6, g = 1, v = "human-male#50", n = { m = 156, f = 156 }, c = { m = { { 0.00, "Ты нашёл их!" }, { 0.91, "Прекрасно!" }, { 1.74, "В этих предметах заключена великая сила, и однажды ты сможешь овладеть ею." }, { 7.60, "Однако они навевают на меня печальные воспоминания о потерянных близких и о предательстве..." } }, f = { { 0.00, "Ты нашла их!" }, { 0.96, "Прекрасно!" }, { 1.78, "В этих предметах заключена великая сила, и однажды ты сможешь овладеть ею." }, { 7.55, "Однако они навевают на меня печальные воспоминания о потерянных близких и о предательстве..." } } } } },
    [5201] = { d = 38.1, v = "nightelf-male#55", n = { x = 436 }, c = { x = { { 0.00, "Моё присутствие здесь мало кто замечает." }, { 2.85, "Однако, существует одна неприятность, укоренившаяся в Зимних Ключах: это фурболги племени Зимней Спячки." }, { 10.43, "Хотя лично я никогда не атаковал фурболгов, они выглядят безумными и боятся всего, что им встречается на пути." }, { 18.40, "Я видел, как они убивали бесчисленное количество существ, чья вина состояла лишь в том, что они оказались не в то время и не в том месте." }, { 28.12, "Мне всё это уже поперёк горла – пожалуйста, помогите мне нанести им ответный удар." }, { 34.01, "Убивайте фурболгов и не подпускайте их к Уступу Ледопардов." } } }, t = { d = 11.4, v = "nightelf-male#55", n = { x = 128 }, c = { x = { { 0.00, "Меня невероятно радует, что хотя бы на короткое время мы можем забыть о вторжении фурболгов племени Зимней Спячки." }, { 8.67, "Я начинаю замечать вашу настойчивость." } } } } },
    [5202] = { d = 18.1, v = "narrator", n = { x = 181 }, c = { x = { { 0.00, "Маленький красный ключ сделан из какого-то материала, похожего на кость." }, { 5.80, "Он тяжёл, но на вид кажется хрупким." }, { 8.66, "Зачем прислужнику Совета Теней этот предмет?" }, { 12.40, "Возможно, этот странный ключ открывает какой-то замок в Джеденаре?" } } }, t = { d = 6.0, g = 1, v = "nightelf-female#52", n = { m = 52, f = 52 }, c = { m = { { 0.00, "Ключ!" }, { 0.49, "Ты его нашёл!" }, { 1.70, "Пожалуйста, дай его мне, и я, наконец, освобожусь!" } }, f = { { 0.00, "Ключ!" }, { 0.47, "Ты его нашла!" }, { 1.74, "Пожалуйста, дай его мне, и я, наконец, освобожусь!" } } } } },
    [5203] = { d = 34.1, g = 1, v = "nightelf-female#52", n = { m = 426, f = 427 }, c = { m = { { 0.00, "Но, как бы мне это ни было тяжко, в первую очередь мне нужно сделать вот что: найти меч Трея, именуемый Светлая Сталь и сбежать из Оплота Теней, чтобы рассказать моим командирам, что здесь творится." }, { 12.44, "Ты поможешь мне?" }, { 13.47, "Наше снаряжение тут неподалёку, а ты уже показал, что сумеешь выбраться наверх." }, { 18.43, "Когда мы выберемся отсюда, я направлюсь в Дарнасс, если ты сможешь найти мою подругу Джессир на границе с Ясеневым лесом." }, { 26.19, "Она должна была встретить нас у лагеря Изумрудного Круга неподалёку отсюда." }, { 30.99, "Что скажешь?" }, { 31.78, "Поможешь мне ещё раз?" } }, f = { { 0.00, "Но, как бы мне это ни было тяжко, в первую очередь мне нужно сделать вот что: найти меч Трея, именуемый Светлая Сталь и сбежать из Оплота Теней, чтобы рассказать моим командирам, что здесь творится." }, { 12.84, "Ты поможешь мне?" }, { 13.90, "Наше снаряжение тут неподалёку, а ты уже показала, что сумеешь выбраться наверх." }, { 19.08, "Когда мы выберемся отсюда, я направлюсь в Дарнасс, если ты сможешь найти мою подругу Джессир на границе с Ясеневым лесом." }, { 27.09, "Она должна была встретить нас у лагеря Изумрудного Круга неподалёку отсюда." }, { 32.04, "Что скажешь?" }, { 32.86, "Поможешь мне ещё раз?" } } }, t = { d = 30.0, g = 1, v = "nightelf-female", n = { m = 362, f = 364 }, c = { m = { { 0.00, "Так это ты помог Арко спастись?" }, { 2.14, "Как я рада увидеть тебя!" }, { 3.80, "Она не так давно проходила мимо этих мест в Дарнасс." }, { 7.30, "Она несла Светлую Сталь и у неё не было даже времени поговорить с друидами, чтобы те её исцелили." }, { 13.71, "Говорила, что дело слишком спешное." }, { 16.08, "Но всё же она рассказала мне о твоей встрече с духом Трея." }, { 19.93, "Какая страшная судьба для рыцаря Серебряной Длани!" }, { 23.32, "Она, конечно, не подаёт виду, но я знаю, что её душа разрывается от потери одного из ближайших друзей..." } }, f = { { 0.00, "Так это ты помогла Арко спастись?" }, { 2.20, "Как я рада увидеть тебя!" }, { 3.82, "Она не так давно проходила мимо этих мест в Дарнасс." }, { 7.23, "Она несла Светлую Сталь и у неё не было даже времени поговорить с друидами, чтобы те её исцелили." }, { 13.48, "Говорила, что дело слишком спешное." }, { 15.79, "Но всё же она рассказала мне о твоей встрече с духом Трея." }, { 19.55, "Какая страшная судьба для рыцаря Серебряной Длани!" }, { 22.85, "Она, конечно, не подаёт виду, но я знаю, что её душа разрывается от потери одного из ближайших друзей..." } } } } },
    [5204] = { d = 27.6, v = "nightelf-female", n = { x = 326 }, c = { x = { { 0.00, "Она делает вид, что с ней всё в порядке." }, { 2.62, "Ей хочется, чтобы я думала, будто она сама сумеет справиться, но я же не слепая." }, { 7.99, "Смерть Трея и его крики под пытками, которым его подвергали, долго мучили её, и мы ничем не могли ей помочь." }, { 15.21, "Но мы всё же можем дать ей хоть немного покоя!" }, { 18.19, "Вернись в Оплот Теней, убей мучителя Трея и найди его останки." }, { 22.49, "Почему бы нам самим не покончить с этим, пока Арконарин плачет в глубине души?" } } }, t = { d = 9.4, v = "narrator", n = { x = 104 }, c = { x = { { 0.00, "Вы как можно осторожнее собираете останки паладина, сознавая, что хотя бы его дух свободен от мучений, которым его подвергали." } } } } },
    [5206] = { d = 31.4, v = "human-male#50", n = { x = 373 }, c = { x = { { 0.00, "Хроми утверждает, что собранные тобой реликвии могут служить ингредиентами для мощных чар." }, { 6.34, "Однако требуется ещё один ингредиент: черепа воинов Плети, участвовавших в битве при Дарроушире." }, { 13.12, "Возьми этот кристалл и отправляйся за черепами лучших воителей Плети." }, { 18.07, "Кристалл заколдован: он резонирует, если поднести его к черепу воителя, участвовавшего в битве." }, { 24.78, "Иди." }, { 25.16, "Ты найдёшь воителей Плети на Ядовитой поляне к северу отсюда и в Грибной долине на западе." } } }, t = { d = 12.8, v = "human-male#50", n = { x = 132 }, c = { x = { { 0.00, "Отлично, у нас есть черепа!" }, { 2.08, "Хоть я и не совсем понимаю, зачем именно они нужны, я чувствую исходящую от них силу и то, что они связаны с моей родной деревней, Дарроушир." } } } } },
    [5210] = { d = 23.4, v = "creature/chromie", n = { x = 261 }, c = { x = { { 0.00, "С помощью магии я дополнила Анналы Дарроушира – теперь они содержат сведения и о том, что случилось после битвы." }, { 8.26, "И там говорится, что ещё один из рода Редпатов пережил предательство Джозефа." }, { 13.87, "Его имя Карлин, он сейчас в восточных пределах Чумных земель, в Часовне Последней Надежды." }, { 20.61, "Отправляйся к нему и передай ему книгу." } } }, t = { d = 22.3, g = 1, v = "human-male#50", n = { m = 225, f = 227 }, c = { m = { { 0.00, "Что это за книга?" }, { 1.40, "Анналы Дарроушира?" }, { 2.88, "О, там был мой дом... пока не пришла Плеть!" }, { 6.11, "Зачем ты принёс мне эту книгу?" }, { 8.50, "Что это?" }, { 9.20, "Смотри, на последних страницах рассказывается о том, что случилось уже после битвы!" }, { 15.66, "Здесь говорится и обо мне, и о моём брате Джозефе..." }, { 19.66, "Неужели это правда?" }, { 21.28, "Я должен знать!" } }, f = { { 0.00, "Что это за книга?" }, { 1.36, "Анналы Дарроушира?" }, { 2.78, "О, там был мой дом... пока не пришла Плеть!" }, { 5.90, "Зачем ты принесла мне эту книгу?" }, { 8.41, "Что это?" }, { 9.09, "Смотри, на последних страницах рассказывается о том, что случилось уже после битвы!" }, { 15.33, "Здесь говорится и обо мне, и о моём брате Джозефе..." }, { 19.19, "Неужели это правда?" }, { 20.75, "Я должен знать!" } } } } },
    [5211] = { d = 31.4, g = 1, v = "human-male#50", n = { m = 352, f = 352 }, c = { m = { { 0.00, "Многие защищавшие Дарроушир пали в битве." }, { 3.16, "И многие из них восстали из мёртвых, примкнув к Плети!" }, { 7.12, "Ты должен отыскать эти несчастные души и избавить их от страданий." }, { 12.09, "Каннибалы-вурдалаки, бормочущие вурдалаки, болезненные живодёры – многие из них были добрыми жителями Дарроушира." }, { 20.42, "Уничтожив их тела, ты освободишь их души." }, { 23.51, "Ты найдёшь их в Проклятом лесу, Перекрёстке Корина и прочих опорных пунктах Плети в Восточных Чумных землях." } }, f = { { 0.00, "Многие защищавшие Дарроушир пали в битве." }, { 3.09, "И многие из них восстали из мёртвых, примкнув к Плети!" }, { 6.98, "Ты должна отыскать эти несчастные души и избавить их от страданий." }, { 11.85, "Каннибалы-вурдалаки, бормочущие вурдалаки, болезненные живодёры – многие из них были добрыми жителями Дарроушира." }, { 20.01, "Уничтожив их тела, ты освободишь их души." }, { 23.03, "Ты найдёшь их в Проклятом лесу, Перекрёстке Корина и прочих опорных пунктах Плети в Восточных Чумных землях." } } }, t = { d = 14.2, g = 1, v = "human-male#50", n = { m = 156, f = 157 }, c = { m = { { 0.00, "Рад слышать, что истерзанные души моих сородичей с твоей помощью обрели свободу." }, { 5.93, "Ты пролил бальзам на мои раны – теперь я знаю, что хоть кто-то из моих павших сородичей освободился от ига Плети." } }, f = { { 0.00, "Рад слышать, что истерзанные души моих сородичей с твоей помощью обрели свободу." }, { 5.87, "Ты пролила бальзам на мои раны – теперь я знаю, что хоть кто-то из моих павших сородичей освободился от ига Плети." } } } } },
    [5212] = { d = 38.0, g = 1, v = "gnome-female", n = { x = 420 }, c = { m = { { 0.00, "Аптекари Отрёкшихся не единственные в этом мире, кто искушён в науках." }, { 5.11, "Я уже много лет изучаю эту заразу, герой." }, { 8.33, "Ранее я полагала, что активность чумы со временем уменьшается, однако то, что наблюдается в Чумных землях, поражает воображение." }, { 17.80, "Здесь вирус со временем становится всё более активным!" }, { 21.84, "Я должна продолжать исследования!" }, { 24.32, "Вирус наиболее активен в первые дни после заражения, поэтому мне нужны образцы тканей, поражённых совсем недавно." }, { 32.79, "Отправляйся в Стратхольм и снабди меня препаратами для исследований." } }, f = { { 0.00, "Аптекари Отрёкшихся не единственные в этом мире, кто искушён в науках." }, { 5.13, "Я уже много лет изучаю эту заразу, героиня." }, { 8.51, "Ранее я полагала, что активность чумы со временем уменьшается, однако то, что наблюдается в Чумных землях, поражает воображение." }, { 18.03, "Здесь вирус со временем становится всё более активным!" }, { 22.08, "Я должна продолжать исследования!" }, { 24.58, "Вирус наиболее активен в первые дни после заражения, поэтому мне нужны образцы тканей, поражённых совсем недавно." }, { 33.08, "Отправляйся в Стратхольм и снабди меня препаратами для исследований." } } }, t = { d = 6.8, v = "gnome-female", n = { x = 78 }, c = { x = { { 0.00, "В химическом составе вируса произошли какие-то изменения." }, { 4.40, "Я должна продолжать исследования." } } } } },
    [5213] = { d = 17.8, v = "gnome-female", n = { x = 188 }, c = { x = { { 0.00, "Тебе предстоит углубиться ещё дальше в кварталы Стратхольма." }, { 4.80, "За первыми воротами ты увидишь зиккураты." }, { 8.10, "Известно, что твари Плети черпают из этих сооружений великую силу." }, { 13.47, "Обыщи зиккураты и расскажи мне обо всём, что там увидишь." } } }, t = { d = 28.6, v = "gnome-female", n = { x = 313 }, c = { x = { { 0.00, "Потрясающе!" }, { 0.89, "Теперь я должна как следует изучить эти данные – это может потребовать нескольких месяцев." }, { 7.90, "Серебряный Рассвет приносит тебе огромную благодарность." }, { 12.23, "Тебе будет дарована печать Рассвета или руна Рассвета на твой выбор." }, { 17.58, "И то, и другое можно использовать вместо Жетона Серебряного Рассвета для сбора знаков различия Плети." }, { 25.34, "Если потеряешь, обращайся ко мне за заменой." } } } } },
    [5214] = { d = 34.0, v = "dwarf-male", n = { x = 367 }, c = { x = { { 0.00, "То, что произошло с Фрасом, поистине ужасно!" }, { 3.27, "Город осаждала нежить, но Фрас не хотел бросать свою лавку превосходного табака." }, { 9.29, "Последнее, что он сказал мне: \"Я не уйду, пока не сожгу всё до последнего листочка, чтобы ничего не осталось врагу!\"" }, { 17.84, "Я тоже знаю толк в хорошем табаке, но не готов расстаться с жизнью ради каких-то сушёных листьев, пусть и наивысшего качества." }, { 27.13, "Хотя... может там и вправду что-то уцелело?" }, { 30.40, "Что скажешь?" }, { 31.34, "Не поищешь табачку для старины Дымка?" } } }, t = { d = 4.6, v = "dwarf-male", n = { x = 33 }, c = { x = { { 0.00, "О, мои милые папироски, как я по вам скучал..." } } } } },
    [5215] = { d = 31.0, v = "human-male#50", n = { x = 367 }, c = { x = { { 0.00, "В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и ещё четыре – на востоке." }, { 7.28, "Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети." }, { 13.36, "Кел'Тузад слишком силён, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды." }, { 24.16, "Моя помощница, верховная жрица Макдонелл, поможет тебе выполнить задание; она продолжит инструктаж." } } }, t = { d = 23.9, g = 1, v = "human-female#45", n = { x = 264 }, c = { m = { { 0.00, "Да осияет тебя Свет в наши тёмные времена, герой." }, { 3.53, "Я рада, что смогу помочь тебе в борьбе с планами Плети." }, { 7.57, "Наша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети." }, { 14.69, "Для этого придётся взять пробы из всех четырёх котлов в Западных Чумных землях." }, { 20.20, "Готовься к славной битве против жестокой Плети!" } }, f = { { 0.00, "Да осияет тебя Свет в наши тёмные времена, героиня." }, { 3.70, "Я рада, что смогу помочь тебе в борьбе с планами Плети." }, { 7.78, "Наша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети." }, { 14.98, "Для этого придётся взять пробы из всех четырёх котлов в Западных Чумных землях." }, { 20.56, "Готовься к славной битве против жестокой Плети!" } } } } },
    [5216] = { d = 30.2, v = "human-female#45", n = { x = 364 }, c = { x = { { 0.00, "Из четырёх котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис." }, { 6.27, "Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать." }, { 11.25, "Отправляйся на поле Джанис, к северо-западу от Андорала, и вступи в схватку с тамошним Хранителем котла." }, { 18.32, "У него есть ключ, который даст доступ к котлу." }, { 21.45, "Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества." } } }, t = { d = 30.2, v = "narrator", n = { x = 337 }, c = { x = { { 0.00, "Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает." }, { 7.48, "И всё же, кажется, отныне вы сможете открывать панель доступа без ключа." }, { 12.92, "Изнутри доносится гнусный запах." }, { 15.43, "В котле бурлит смесь неизвестных веществ." }, { 18.56, "Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда." } } } } },
    [5217] = { d = 11.9, v = "narrator", n = { x = 132 }, c = { x = { { 0.00, "Вы наполняете бутыль из котла ядовитой жижей." }, { 3.50, "Вроде бы должно хватить." }, { 5.42, "Заполучив яд, пора возвращаться к верховной жрице Макдонелл в Лагерь Промозглого Ветра." } } }, t = { d = 27.8, v = "human-female#45", n = { x = 341 }, c = { x = { { 0.00, "Молодец!" }, { 0.62, "Алхимик Арбингтон мигом проведёт анализ этой дряни и составит противодействующее вещество." }, { 6.81, "Надо будет внести его в котёл и постараться, чтобы побольше испарений попало в воздух." }, { 12.81, "Кто знает, может удастся ослабить Плеть." }, { 15.60, "Это будет нелегко – придётся постоянно устраивать набеги на котлы и добавлять в них необходимые реагенты." }, { 22.78, "И всё же у нас есть шанс получить в решающей битве преимущество перед Плетью!" } } } } },
    [5218] = { t = { d = 14.3, v = "narrator", n = { x = 151 }, c = { x = { { 0.00, "Добавив в котёл все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров." }, { 8.25, "Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь." } } } } },
    [5219] = { d = 29.4, v = "human-female#45", n = { x = 328 }, c = { x = { { 0.00, "Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слёзы Далсона." }, { 6.50, "Что ж, сегодня мы слез лить не будем – мы сорвём планы Плети, и пусть она задохнётся в собственных испарениях!" }, { 14.17, "Отправляйся в Слёзы Далсона, к северу от Андорала, и убей Хранителя котла." }, { 19.51, "Забери у него ключ, как и в прошлый раз и получи доступ к самому котлу." }, { 24.64, "Наполни эту бутылку ядом, ведь в каждом из котлов бурлят свои яды." } } }, t = { d = 26.7, v = "narrator", n = { x = 298 }, c = { x = { { 0.00, "Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает." }, { 8.04, "Вы получили постоянный доступ к котлу." }, { 10.99, "По переплетённым трубкам течёт гнусная тягучая жижа." }, { 14.91, "Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда." } } } } },
    [5220] = { d = 12.2, v = "narrator", n = { x = 133 }, c = { x = { { 0.00, "Вы наполняете бутыль из котла зловонной жижей." }, { 3.64, "Вроде бы должно хватить." }, { 5.60, "Заполучив яд, пора возвращаться к верховной жрице Макдонелл в Лагерь Промозглого Ветра." } } }, t = { d = 25.0, v = "human-female#45", n = { x = 290 }, c = { x = { { 0.00, "А, мне будет чем заняться." }, { 1.88, "Молодец!" }, { 2.53, "Итак, следующий шаг ясен." }, { 4.41, "Мы должны составить список компонентов, которые будет необходимо смешать с зельем чумы, чтобы добиться от него обратного действия." }, { 13.88, "Для этого придётся поместить эти составляющие непосредственно в котёл." }, { 18.81, "Алхимик Арбингтон знает гораздо больше чем я, поэтому в ближайшее время поговори с ним." } } } } },
    [5221] = { t = { d = 14.2, v = "narrator", n = { x = 151 }, c = { x = { { 0.00, "Добавив в котёл все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров." }, { 8.16, "Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь." } } } } },
    [5222] = { d = 29.3, v = "human-female#45", n = { x = 340 }, c = { x = { { 0.00, "Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остаётся ещё два!" }, { 6.96, "Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!" }, { 13.91, "На сей раз твоя цель – котёл Удела Страданий." }, { 17.04, "Он совсем рядом с разрушенными стенами Андорала, чуть восточнее." }, { 21.57, "И вновь тебе придётся убить Хранителя котла и забрать у него ключ." }, { 26.23, "Наполни эту бутылку из котла." }, { 28.40, "Доброй охоты!" } } }, t = { d = 20.7, v = "narrator", n = { x = 237 }, c = { x = { { 0.00, "Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз." }, { 5.95, "Внутри бурлит омерзительно пахнущая жидкость." }, { 9.34, "Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда." } } } } },
    [5223] = { d = 16.3, v = "narrator", n = { x = 170 }, c = { x = { { 0.00, "Вы аккуратно закручиваете бутылку." }, { 2.79, "Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке." }, { 9.34, "Заполучив яд, пора возвращаться к верховной жрице Макдонелл в Лагерь Промозглого Ветра." } } }, t = { d = 29.1, v = "human-female#45", n = { x = 341 }, c = { x = { { 0.00, "Ещё одно задание выполнено без сучка, без задоринки!" }, { 3.67, "Итак, у нас есть доступ вот уже к трём котлам!" }, { 6.90, "Если бы не страшная некромантская власть Кел'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их!" }, { 15.52, "Алхимик Арбингтон вскоре сообщит, что требуется добавить в этот котёл – и другие, подвластные нам – чтобы справиться с чумой нежити." }, { 24.77, "Итак, настало время добраться до последнего из западных котлов!" } } } } },
    [5224] = { t = { d = 14.2, v = "narrator", n = { x = 151 }, c = { x = { { 0.00, "Добавив в котёл все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров." }, { 8.20, "Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь." } } } } },
    [5225] = { d = 32.3, g = 1, v = "human-female#45", n = { x = 371 }, c = { m = { { 0.00, "Последний оставшийся котёл находится на ферме, которая теперь зовётся пустошью Гаррона." }, { 6.11, "Его охраняют сильные прислужники Плети, по большей части призраки и духи." }, { 11.39, "С ними шутки плохи." }, { 12.86, "Пустошь Гаррона находится к северо-востоку отсюда, близко от границы Восточных Чумных земель." }, { 19.48, "И вновь тебе придётся убить Хранителя котла и забрать у него ключ." }, { 24.12, "Вот, возьми эту пустую бутылку, заполни её из котла и принеси мне." }, { 28.84, "Да хранит тебя Свет в этом опасном задании, герой." } }, f = { { 0.00, "Последний оставшийся котёл находится на ферме, которая теперь зовётся пустошью Гаррона." }, { 6.09, "Его охраняют сильные прислужники Плети, по большей части призраки и духи." }, { 11.35, "С ними шутки плохи." }, { 12.81, "Пустошь Гаррона находится к северо-востоку отсюда, близко от границы Восточных Чумных земель." }, { 19.40, "И вновь тебе придётся убить Хранителя котла и забрать у него ключ." }, { 24.03, "Вот, возьми эту пустую бутылку, заполни её из котла и принеси мне." }, { 28.72, "Да хранит тебя Свет в этом опасном задании, героиня." } } }, t = { d = 24.5, v = "narrator", n = { x = 274 }, c = { x = { { 0.00, "Коснувшись панели доступа у основания, ключ Хранителя котла Душегнева исчезает." }, { 6.11, "Раздаётся негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам." }, { 12.88, "Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда." } } } } },
    [5226] = { d = 15.6, v = "narrator", n = { x = 167 }, c = { x = { { 0.00, "Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку." }, { 8.91, "Заполучив яд, пора возвращаться к верховной жрице Макдонелл в Лагерь Промозглого Ветра." } } }, t = { d = 23.6, v = "human-female#45", n = { x = 280 }, c = { x = { { 0.00, "Поздравляю, тебе удалось обеспечить нам доступ к последнему из котлов!" }, { 4.94, "Аптекарь Арбингтон вскоре составит список компонентов, которые необходимо добавить в него." }, { 11.33, "Что до тебя, я не сомневаюсь, что командир Отважный Кулак пожелает лично поблагодарить тебя за помощь." }, { 18.49, "Без тебя наша борьба с Плетью была обречена." }, { 21.72, "Спасибо, ты настоящий герой." } } } } },
    [5227] = { t = { d = 14.2, v = "narrator", n = { x = 151 }, c = { x = { { 0.00, "Добавив в котёл все необходимые вещества, вы видите, как меняется цвет и состав исходящих от него паров." }, { 8.20, "Приспешники Плети, находящиеся поблизости, в ужасе отшатываются и бегут прочь." } } } } },
    [5228] = { d = 36.5, v = "scourge-male", n = { x = 359 }, c = { x = { { 0.00, "В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и ещё четыре – на востоке." }, { 8.71, "Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети." }, { 15.99, "Кел'Тузад слишком силён, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды." }, { 28.90, "Моя помощница, жрица Тьмы Вандис, поможет тебе выполнить задание; она продолжит инструктаж." } } }, t = { d = 25.3, g = 1, v = "scourge-female#79", n = { m = 249, f = 251 }, c = { m = { { 0.00, "Приветствую тебя из тени, брат." }, { 2.66, "Я помогу тебе организовать нападение на котлы Плети." }, { 7.14, "Наша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети." }, { 15.57, "Для этого придётся взять пробы из всех четырёх котлов в Западных Чумных землях." }, { 22.10, "Тебя ждёт героическая схватка с Плетью!" } }, f = { { 0.00, "Приветствую тебя из тени, сестра." }, { 2.86, "Я помогу тебе организовать нападение на котлы Плети." }, { 7.30, "Наша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети." }, { 15.65, "Для этого придётся взять пробы из всех четырёх котлов в Западных Чумных землях." }, { 22.12, "Тебя ждёт героическая схватка с Плетью!" } } } } },
    [5229] = { d = 37.2, v = "scourge-female#79", n = { x = 384 }, c = { x = { { 0.00, "Из четырёх котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис." }, { 7.31, "Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать." }, { 13.12, "Отправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла." }, { 23.37, "У него есть ключ, который даст доступ к котлу." }, { 27.03, "Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества." } } }, t = { d = 29.4, v = "narrator", n = { x = 316 }, c = { x = { { 0.00, "Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает." }, { 7.71, "И всё же, кажется, отныне вы сможете открывать панель доступа без ключа." }, { 13.32, "Изнутри доносится гнусный запах." }, { 15.92, "В котле бурлит смесь неизвестных веществ." }, { 19.14, "Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для жрицы Тени Вандис из Бастиона не составляет труда." } } } } },
    [5230] = { d = 9.6, v = "narrator", n = { x = 98 }, c = { x = { { 0.00, "Вы наполняете бутыль из котла ядовитой жижей." }, { 3.74, "Вроде бы должно хватить." }, { 5.79, "Пора возвращаться к жрице Тьмы Вандис в Бастион." } } }, t = { d = 30.9, v = "scourge-female#79", n = { x = 339 }, c = { x = { { 0.00, "Молодец!" }, { 0.69, "Аптекарь Дитерс мигом проведёт анализ этой дряни и составит противодействующее вещество." }, { 7.43, "Надо будет внести его в котёл и постараться, чтобы побольше испарений попало в воздух." }, { 14.10, "Кто знает, может удастся ослабить Плеть." }, { 17.19, "Это будет нелегко – придётся постоянно устраивать набеги на котлы и добавлять в них необходимые реагенты." }, { 25.17, "И всё же у нас есть шанс получить в решающей битве преимущество перед Плетью!" } } } } },
    [5231] = { d = 33.3, g = 1, v = "scourge-female#79", n = { x = 312 }, c = { m = { { 0.00, "Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слёзы Далсона." }, { 7.53, "Но сегодня не время лить слёзы, герой." }, { 10.69, "Мы должны нанести удар по котлу и получить к нему доступ!" }, { 15.59, "Отправляйся в Слёзы Далсона, к северу от Андорала, и убей Хранителя котла." }, { 21.76, "Забери у него ключ, как и в прошлый раз и получи доступ к самому котлу." }, { 27.71, "Наполни эту бутылку ядом, ведь в каждом из котлов бурлят свои яды." } }, f = { { 0.00, "Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слёзы Далсона." }, { 6.94, "Но сегодня не время лить слёзы, героиня." }, { 9.99, "Мы должны нанести удар по котлу и получить к нему доступ!" }, { 14.50, "Отправляйся в Слёзы Далсона, к северу от Андорала, и убей Хранителя котла." }, { 20.19, "Забери у него ключ, как и в прошлый раз и получи доступ к самому котлу." }, { 25.68, "Наполни эту бутылку ядом, ведь в каждом из котлов бурлят свои яды." } } }, t = { d = 25.7, v = "narrator", n = { x = 277 }, c = { x = { { 0.00, "Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает." }, { 8.26, "Вы получили постоянный доступ к котлу." }, { 11.29, "По переплетённым трубкам течёт гнусная тягучая жижа." }, { 15.31, "Бутылка отлично помещается под небольшой кран, так что набрать в неё образец яда для жрицы Тени Вандис из Бастиона не составляет труда." } } } } },
    [5232] = { d = 9.9, v = "narrator", n = { x = 99 }, c = { x = { { 0.00, "Вы наполняете бутыль из котла зловонной жижей." }, { 3.91, "Вроде бы должно хватить." }, { 6.02, "Пора возвращаться к жрице Тьмы Вандис в Бастион." } } }, t = { d = 27.1, v = "scourge-female#79", n = { x = 288 }, c = { x = { { 0.00, "А, мне будет чем заняться." }, { 2.05, "Молодец!" }, { 2.76, "Итак, следующий шаг ясен." }, { 4.82, "Мы должны составить список компонентов, которые будет необходимо смешать с зельем чумы, чтобы добиться от него обратного действия." }, { 15.16, "Для этого придётся поместить эти составляющие непосредственно в котёл." }, { 20.54, "Аптекарь Дитерс знает гораздо больше чем я, поэтому в ближайшее время поговори с ним." } } } } },
