    [5237] = { t = { d = 25.4, g = 1, v = "human-male#50", n = { m = 279, f = 281 }, c = { m = { { 0.00, "Перенастроив котлы, ты принёс нам огромную победу!" }, { 3.67, "Пусть слышат все присутствующие: за службу Штормградскому королевству и Альянсу сверх всякого долга – и, добавлю, перед лицом подавляющего превосходства врага и невероятной опасности – я вручаю тебе эту награду и выражаю ему нашу вечную благодарность как истинному герою Альянса." }, { 24.23, "Ура!" } }, f = { { 0.00, "Перенастроив котлы, ты принесла нам огромную победу!" }, { 3.99, "Пусть слышат все присутствующие: за службу Штормградскому королевству и Альянсу сверх всякого долга – и, добавлю, перед лицом подавляющего превосходства врага и невероятной опасности – я вручаю тебе эту награду и выражаю ей нашу вечную благодарность как истинной героине Альянса." }, { 25.10, "Ура!" } } } } },
    [5238] = { t = { d = 30.5, g = 1, v = "scourge-male", n = { m = 264, f = 266 }, c = { m = { { 0.00, "Перенастроив котлы, ты принёс нам огромную победу!" }, { 4.60, "Пусть слышат все присутствующие: за службу Отрёкшимся и всей Орде сверх всяких ожиданий – и, добавлю, перед лицом подавляющего превосходства врага и невероятной опасности – я вручаю тебе эту награду и выражаю ему нашу вечную благодарность как истинному герою Орды." }, { 28.94, "Ура!" } }, f = { { 0.00, "Перенастроив котлы, ты принесла нам огромную победу!" }, { 5.02, "Пусть слышат все присутствующие: за службу Отрёкшимся и всей Орде сверх всяких ожиданий – и, добавлю, перед лицом подавляющего превосходства врага и невероятной опасности – я вручаю тебе эту награду и выражаю ей нашу вечную благодарность как истинной героине Орды." }, { 30.13, "Ура!" } } } } },
    [5241] = { d = 31.4, g = 1, v = "child-female", n = { x = 303 }, c = { m = { { 0.00, "Ты знаешь, иногда по ночам мне слышится плач дядюшки Карлина – как будто бы плач доносится откуда-то издалека, с востока." }, { 9.66, "А вдруг он плачет обо мне..." }, { 11.91, "Путник, пожалуйста, разыщи моего дядюшку и скажи ему, что со мной всё в порядке." }, { 18.37, "Скажи, что я здесь, жду его и очень скучаю по сказкам, которые он рассказывал мне на ночь... особенно той, про кроликов и черничное варенье." }, { 29.41, "Она была такая забавная!" } }, f = { { 0.00, "Ты знаешь, иногда по ночам мне слышится плач дядюшки Карлина – как будто бы плач доносится откуда-то издалека, с востока." }, { 9.46, "А вдруг он плачет обо мне..." }, { 11.67, "Путница, пожалуйста, разыщи моего дядюшку и скажи ему, что со мной всё в порядке." }, { 18.07, "Скажи, что я здесь, жду его и очень скучаю по сказкам, которые он рассказывал мне на ночь... особенно той, про кроликов и черничное варенье." }, { 28.89, "Она была такая забавная!" } } }, t = { d = 26.3, g = 1, v = "human-male#50", n = { m = 269, f = 270 }, c = { m = { { 0.00, "Ты видел Памелу?" }, { 1.31, "Она жива?" }, { 2.14, "Погибла?!" }, { 2.90, "Бедная моя девочка!" }, { 4.48, "За что твой дух осуждён скитаться в этом жестоком мире..." }, { 8.75, "Почему тебя не стало во цвете лет, а я всё ещё копчу небо!" }, { 13.23, "Как бы я хотел вместо тебя отдать жизнь и призраком бродить по руинам Дарроушира!" }, { 19.44, "Судьбу не изменить..." }, { 21.09, "Спасибо тебе." }, { 22.20, "Теперь мой долг – месть, я осознаю это ясно как никогда." } }, f = { { 0.00, "Ты видела Памелу?" }, { 1.38, "Она жива?" }, { 2.21, "Погибла?!" }, { 2.97, "Бедная моя девочка!" }, { 4.55, "За что твой дух осуждён скитаться в этом жестоком мире..." }, { 8.83, "Почему тебя не стало во цвете лет, а я всё ещё копчу небо!" }, { 13.31, "Как бы я хотел вместо тебя отдать жизнь и призраком бродить по руинам Дарроушира!" }, { 19.52, "Судьбу не изменить..." }, { 21.17, "Спасибо тебе." }, { 22.27, "Теперь мой долг – месть, я осознаю это ясно как никогда." } } } } },
    [5242] = { d = 41.0, v = "tauren-female#71", n = { x = 378 }, c = { x = { { 0.00, "Увы, я вижу только один путь покончить с угрозой Осквернённому лесу – прямую атаку." }, { 7.08, "Других путей в Оплот Теней нет, телепортировать тебя внутрь я тоже не могу." }, { 13.48, "Единственный путь – прямой путь в бездну... и я также знаю, кого тебе следует искать в этой бездне." }, { 21.93, "Его зовут Скверн'дан..." }, { 23.98, "Владыка теней Скверн'дан." }, { 26.19, "Его власть там, внизу, смертоносна..." }, { 29.31, "Он – голова змеи." }, { 30.84, "Убей его и двух его суккубов-прислужниц, и вернись ко мне." }, { 35.79, "Это Скверн'дан заключил союз с Легионом." }, { 39.29, "Его надо остановить!" } } }, t = { d = 18.1, g = 1, v = "tauren-female#71", n = { m = 156, f = 159 }, c = { m = { { 0.00, "Хвала Матери-Земле!" }, { 1.91, "Хвала тебе!" }, { 3.07, "Воистину, великий день!" }, { 5.23, "Совет Теней вряд ли сможет снова обрести ту власть которой обладал до того, как ты нанёс удар по их иерархии." }, { 15.18, "Великое дело ты ныне свершил!" } }, f = { { 0.00, "Хвала Матери-Земле!" }, { 1.89, "Хвала тебе!" }, { 3.04, "Воистину, великий день!" }, { 5.18, "Совет Теней вряд ли сможет снова обрести ту власть которой обладал до того, как ты нанесла удар по их иерархии." }, { 15.29, "Великое дело ты ныне свершила!" } } } } },
    [5243] = { d = 46.6, g = 1, v = "scourge-male", n = { x = 423 }, c = { m = { { 0.00, "Я склонен рассматривать своё бытие в форме нежити как род болезни, герой." }, { 6.57, "Болезни, которая требует лечения." }, { 9.65, "Впрочем, для Серебряного Рассвета это не болезнь, а истинное благословение." }, { 16.38, "Действительно, нет лучше орудия против язычников Плети, чем нежить." }, { 22.47, "Коллеги чтят меня за мои деяния, однако почести ничего не значат для меня." }, { 29.28, "Если ты хочешь содействовать делу Серебряного Рассвета, у меня есть для тебя работа." }, { 36.91, "Отправляйся в Стратхольм и пополни наши запасы святой воды." }, { 42.34, "Искать её следует в брошенных ящиках с припасами." } }, f = { { 0.00, "Я склонен рассматривать своё бытие в форме нежити как род болезни, героиня." }, { 6.64, "Болезни, которая требует лечения." }, { 9.68, "Впрочем, для Серебряного Рассвета это не болезнь, а истинное благословение." }, { 16.32, "Действительно, нет лучше орудия против язычников Плети, чем нежить." }, { 22.32, "Коллеги чтят меня за мои деяния, однако почести ничего не значат для меня." }, { 29.04, "Если ты хочешь содействовать делу Серебряного Рассвета, у меня есть для тебя работа." }, { 36.56, "Отправляйся в Стратхольм и пополни наши запасы святой воды." }, { 41.92, "Искать её следует в брошенных ящиках с припасами." } } }, t = { d = 9.4, g = 1, v = "scourge-male", n = { m = 79, f = 82 }, c = { m = { { 0.00, "Отлично, герой." }, { 1.50, "Ты доказал, что терпим к ближнему и непримирим в борьбе против приспешников Кел'Тузада." } }, f = { { 0.00, "Отлично, героиня." }, { 1.59, "Ты доказала, что терпима к ближнему и непримирима в борьбе против приспешников Кел'Тузада." } } } } },
    [5244] = { d = 35.8, v = "nightelf-male#54", n = { x = 387 }, c = { x = { { 0.00, "История Кел'Терила – это история проклятой расы, прикованной к месту, где был совершён неудавшийся ритуал…" }, { 8.11, "Высокорождённые, которых вы найдёте там, когда-то похитили священный артефакт, будучи уверенными, что смогут вытянуть его мощь, перелить её в себя и стать ещё более могущественными." }, { 21.70, "Из-за их действий реликвия взорвалась, а куски её ушли под лёд озера..." }, { 27.17, "Если хотите узнать больше, поговорите с Джероном Гранильщиком." }, { 32.03, "Он был там недавно и сможет рассказать вам обо всём." } } }, t = { d = 9.7, v = "dwarf-male", n = { x = 101 }, c = { x = { { 0.00, "Ну, конечно, я могу подробно рассказать про Кел'Терил." }, { 4.01, "Имей в виду, я не историк – но могу рассказать тебе о том, что я сам там видел…" } } } } },
    [5245] = { d = 32.9, v = "dwarf-male", n = { x = 383 }, c = { x = { { 0.00, "Несчастные существа эти духи высокорождённых, что и говорить." }, { 4.26, "Они всё ещё ищут части самой вещи, которая навсегда привязала их к Кел'Терилу, эту похищенную у них реликвию." }, { 12.03, "Если тебе это интересно, можешь взять мою кирку и отправляться на юг к озеру, чтобы попытаться достать части этого артефакта изо льда." }, { 21.63, "Я не могу сказать что именно ты найдёшь, но Аврора Зов Небес наверняка сможет; она живёт около башни Северного Перевала в северной части Восточных Чумных земель." } } }, t = { d = 10.6, v = "bloodelf-female", n = { x = 111 }, c = { x = { { 0.00, "Прошлое Высоких Эльфов не лучшая тема для беседы." }, { 3.90, "Мне до сих пор больно думать об этом..." }, { 6.89, "И самое главное, уже невозможно ничего исправить." } } } } },
    [5246] = { d = 33.4, g = 1, v = "bloodelf-female", n = { x = 355 }, c = { m = { { 0.00, "Я не понимала…" }, { 1.11, "Простите мои жестокие слова, герой." }, { 3.97, "Я не хочу вспоминать об ошибках своих предков, но если ваша просьба искренна, я помогу." }, { 10.72, "*Аврора изучает фрагменты.*" }, { 13.20, "Я уверена, что это – Кристалл Зин-Малора, артефакт, содержащий в себе могучие силы тайной магии." }, { 20.10, "Возможно, его использовали и во благо, но из-за злых намерений тех, кто его похитил, кристалл раскололся." }, { 27.50, "Отправляйтесь в Храм Зин-Малор в Азшаре – я могу лишь надеяться, что книга всё ещё там." } }, f = { { 0.00, "Я не понимала…" }, { 1.09, "Простите мои жестокие слова, героиня." }, { 4.02, "Я не хочу вспоминать об ошибках своих предков, но если ваша просьба искренна, я помогу." }, { 10.64, "*Аврора изучает фрагменты.*" }, { 13.20, "Я уверена, что это – Кристалл Зин-Малора, артефакт, содержащий в себе могучие силы тайной магии." }, { 20.01, "Возможно, его использовали и во благо, но из-за злых намерений тех, кто его похитил, кристалл раскололся." }, { 27.33, "Отправляйтесь в Храм Зин-Малор в Азшаре – я могу лишь надеяться, что книга всё ещё там." } } }, t = { d = 3.7, v = "bloodelf-female", n = { x = 35 }, c = { x = { { 0.00, "Этих страниц долгие годы никто не касался…" } } } } },
    [5247] = { d = 37.3, v = "bloodelf-female", n = { x = 424 }, c = { x = { { 0.00, "Я смогу помочь вам, если воссоздание артефакта действительно является вашим желанием." }, { 6.30, "Чтобы воссоединить фрагменты, мне потребуются вещи, обладающие сильными магическими свойствами." }, { 13.27, "Слиток зачарованного тория и пять кристаллов восстановления…" }, { 17.65, "Также вам нужно будет набрать воды из... необычного источника..." }, { 22.43, "Найдите Зловещий пруд на Пути Элдрета в Забытом Городе, что в Фераласе, и наполните этот фиал." }, { 29.40, "Пока вас не будет, я попытаюсь извлечь из этих страниц знание, как восполнить урон, нанесённый этой реликвии." } } }, t = { d = 10.2, v = "bloodelf-female", n = { x = 107 }, c = { x = { { 0.00, "Используя эти компоненты, я сумею снова соединить эти фрагменты… надеюсь, получится именно то, чем эта реликвия когда-то являлась." } } } } },
    [5248] = { d = 30.1, v = "bloodelf-female", n = { x = 327 }, c = { x = { { 0.00, "Я скорблю о том, что раса эльфов была разрушена, подобно этому кристаллу." }, { 5.47, "Я не знаю, соберутся ли когда-нибудь эти осколки воедино, и всё же то, что я могу помочь тебе, уменьшает мою скорбь." }, { 14.01, "Мы не должны забывать о прошлом..." }, { 16.55, "Пожалуйста верни кристалл Зин-Малора к озеру Кел'Терил." }, { 20.68, "Найди там духа высокорождённого, который, так же как и я, сожалеет о допущенных ошибках и скажи ему, что мы стремимся всё исправить." } } }, t = { d = 2.4, v = "creature/banshee", n = { x = 18 }, c = { x = { { 0.00, "Оссстаааввь меняяяя..." } } } } },
    [5249] = { d = 32.0, v = "nightelf-female#53", n = { x = 356 }, c = { x = { { 0.00, "В Зимних Ключах, к северу отсюда, много древних эльфийских руин." }, { 4.78, "Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения." }, { 11.72, "Работа здесь отнимает всё моё время, так что у меня давно уже не было возможности самой добраться до Зимних Ключей." }, { 20.10, "Но вам-то ничто не мешает!" }, { 22.06, "Когда будете там, поищите Вунда Ночного Охотника." }, { 25.73, "Большую часть времени он проводит в деревне Звездопада и очень много знает о тех местах." } } }, t = { d = 4.1, v = "nightelf-male#54", n = { x = 41 }, c = { x = { { 0.00, "Друг Иви Росистой Листвы?" }, { 2.28, "Приятно познакомиться." } } } } },
    [5250] = { d = 38.3, g = 1, v = "nightelf-female#51", n = { m = 431, f = 432 }, c = { m = { { 0.00, "В Зимних Ключах, к северу от Осквернённого леса, много древних эльфийских руин." }, { 5.64, "Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения." }, { 12.44, "Я так занята своими исследованиями здесь, что у меня давно уже не было возможности самой добраться до Зимних Ключей." }, { 20.71, "Но у вас-то нет никаких причин для отказа от путешествия туда и изучения руин." }, { 26.28, "Когда будете там, поищите Вунда Ночного Охотника." }, { 29.87, "Большую часть времени он проводит в Звездопаде и очень много знает о том районе." }, { 35.58, "Скажите ему, что вы мой ученик." } }, f = { { 0.00, "В Зимних Ключах, к северу от Осквернённого леса, много древних эльфийских руин." }, { 5.72, "Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения." }, { 12.61, "Я так занята своими исследованиями здесь, что у меня давно уже не было возможности самой добраться до Зимних Ключей." }, { 20.99, "Но у вас-то нет никаких причин для отказа от путешествия туда и изучения руин." }, { 26.64, "Когда будете там, поищите Вунда Ночного Охотника." }, { 30.28, "Большую часть времени он проводит в Звездопаде и очень много знает о том районе." }, { 36.06, "Скажите ему, что вы моя ученица." } } }, t = { d = 4.5, g = 1, v = "nightelf-male#54", n = { m = 48, f = 49 }, c = { m = { { 0.00, "Ученик Дарин Доброго Ветра?" }, { 2.20, "Приятно познакомиться с вами." } }, f = { { 0.00, "Ученица Дарин Доброго Ветра?" }, { 2.32, "Приятно познакомиться с вами." } } } } },
    [5251] = { d = 31.6, v = "human-male", n = { x = 356 }, c = { x = { { 0.00, "Впадать в крайности всегда опасно." }, { 2.54, "Взять, к примеру, Алый орден." }, { 4.69, "Неужели такой слепой фанатизм способен привести к чему-то хорошему?" }, { 9.65, "Скольких невинных убили они во имя Света." }, { 12.78, "Это просто святотатство!" }, { 14.60, "Вот что, один из этих негодяев мне особенно интересен – это архивариус Галфорд из Стратхольма." }, { 21.38, "Этот человек отвечает за самые ценные документы ордена." }, { 25.49, "Уничтожь его и сожги его архивы!" }, { 27.96, "Если справишься с этим, получишь достойную награду." } } }, t = { d = 8.2, g = 1, v = "human-male", n = { m = 80, f = 81 }, c = { m = { { 0.00, "Отличная работа!" }, { 1.45, "Ты уничтожил разведданные, собираемые Алым орденом годами!" }, { 6.41, "Алые будут в ярости..." } }, f = { { 0.00, "Отличная работа!" }, { 1.44, "Ты уничтожила разведданные, собираемые Алым орденом годами!" }, { 6.43, "Алые будут в ярости..." } } } } },
    [5252] = { d = 31.3, g = 1, v = "creature/banshee", n = { m = 249, f = 249 }, c = { m = { { 0.00, "Кри… кристалл…" }, { 1.49, "Здешние высокорождённые находятся в плену их жалкого сущессствования…" }, { 8.47, "Я полна горрречи, но я понимаю, в чём моя ошибка." }, { 13.59, "И хотя изменить прошлое нееевозможно, теперь я обрела покой, зная, что тебе удалосссь добыть кристалл Зин-Малора..." }, { 25.59, "Ты должен вернуть крисссталл..." }, { 28.85, "Он должен быть воззвращён." } }, f = { { 0.00, "Кри… кристалл…" }, { 1.49, "Здешние высокорождённые находятся в плену их жалкого сущессствования…" }, { 8.47, "Я полна горрречи, но я понимаю, в чём моя ошибка." }, { 13.59, "И хотя изменить прошлое нееевозможно, теперь я обрела покой, зная, что тебе удалосссь добыть кристалл Зин-Малора..." }, { 25.59, "Ты должна вернуть крисссталл..." }, { 28.85, "Он должен быть воззвращён." } } }, t = { d = 3.0, v = "nightelf-male#54", n = { x = 17 }, c = { x = { { 0.00, "Это… это то, что я думаю?" } } } } },
    [5253] = { d = 29.8, v = "nightelf-male#54", n = { x = 315 }, c = { x = { { 0.00, "Впечатляюще." }, { 0.98, "Кристалл Зин-Малора никогда не вернётся в храм, лежащий в руинах." }, { 5.97, "Но я полагаю, что твои усилия уничтожить зло минувших лет не должны пойти прахом." }, { 12.29, "Найди верховного друида Фэндрала Оленьего Шлема в Дарнассе, и отдай ему кристалл." }, { 18.75, "Он должен находиться в руках тех, кто не злоупотребит его мощью." }, { 23.74, "К тому же только самые сильные маги смогут управиться с артефактом такой мощи." } } }, t = { d = 26.3, v = "named/3516", n = { x = 318 }, c = { x = { { 0.00, "Я слышал о кристалле Зин-Малора." }, { 2.23, "Его обладатель получает практически неограниченную магическую мощь, но только если он достоин этого." }, { 9.11, "Я впечатлён – вы не только умудрились добыть кристалл, вы ещё и достаточно мудры, чтобы не пытаться его использовать самостоятельно." }, { 18.03, "Спасибо, что принесли его мне." }, { 20.14, "Мы сохраним его, и пусть духи, охранявшие кристалл всё это время, наконец-то обретут покой." } } } } },
    [5261] = { d = 15.8, v = "human-male", n = { x = 190 }, c = { x = { { 0.00, "Иган Меховщик ищет охотника на волков." }, { 2.70, "Это добрая новость, поскольку в последнее время в Долине Североземья звери уж чересчур расплодились." }, { 9.58, "Если тебе это интересно, то поговори с Иганом." }, { 12.83, "Он за углом аббатства, если свернуть налево." } } }, t = { d = 7.1, v = "human-male", n = { x = 60 }, c = { x = { { 0.00, "Что?" }, { 0.40, "Ищу ли я охотников на волков?" }, { 3.07, "Ну да, так и есть." }, { 4.61, "А ты, наверное, ищешь работу?" } } } } },
    [5262] = { d = 38.6, v = "narrator", n = { x = 388 }, c = { x = { { 0.00, "В воздухе ещё вихрится пыль, а вы пытаетесь собраться с мыслями и осознать произошедшее." }, { 7.33, "И всё же весь ужас вашего положения не укладывается в голове." }, { 12.45, "Верховный рыцарь оказался демоном!" }, { 15.43, "И не просто демоном, а братом самого Вариматраса, верховного правителя Подгорода." }, { 22.30, "Вы бережно укладываете голову повелителя ужаса в суму." }, { 26.96, "Разумеется, никто не поверит рассказанному вами без вещественных доказательств." }, { 33.60, "Надо сообщить герцогу Николасу Зверенхоффу как можно скорее!" } } }, t = { d = 11.0, v = "human-male", n = { x = 116 }, c = { x = { { 0.00, "Что это будет значить для Алого ордена?" }, { 2.99, "Неужели всё это время им управлял этот демон?" }, { 6.45, "И они, сами того не ведая, были пешками в руках большего зла?" } } } } },
    [5263] = { d = 27.2, g = 1, v = "human-male", n = { m = 329, f = 330 }, c = { m = { { 0.00, "Ты проявил прирождённую склонность к разрушению и умеешь следовать приказам." }, { 5.28, "Эти похвальные качества весьма редко сочетаются." }, { 8.78, "Полагаю, ты можешь стать совершенным орудием высшего промысла." }, { 13.31, "*Зверенхофф складывает ладони перед лицом.*" }, { 16.51, "Кел'Тузад усадил своего мальчика на побегушках править в Стратхольме." }, { 21.12, "Докажи мне свою верность и доблесть." }, { 23.58, "Уничтожь барона Ривендера и принеси мне его голову." } }, f = { { 0.00, "Ты проявила прирождённую склонность к разрушению и умеешь следовать приказам." }, { 5.45, "Эти похвальные качества весьма редко сочетаются." }, { 9.01, "Полагаю, ты можешь стать совершенным орудием высшего промысла." }, { 13.68, "*Зверенхофф складывает ладони перед лицом.*" }, { 16.80, "Кел'Тузад усадил своего мальчика на побегушках править в Стратхольме." }, { 21.41, "Докажи мне свою верность и доблесть." }, { 23.87, "Уничтожь барона Ривендера и принеси мне его голову." } } }, t = { d = 8.2, v = "human-male", n = { x = 101 }, c = { x = { { 0.00, "Давно мне не приходилось объявлять о новых героях." }, { 3.50, "Ты будешь первым, кого лорд Максвелл удостоит аудиенции за много лет." } } } } },
    [5264] = { d = 14.0, v = "human-male", n = { x = 160 }, c = { x = { { 0.00, "Тебе оказана большая честь." }, { 2.04, "Лорд Максвелл хочет наградить тебя за твои заслуги перед Серебряным Рассветом!" }, { 7.83, "Поверь мне, это большая честь – Максвелл уже много лет не удостаивал никого аудиенции." } } }, t = { d = 5.1, v = "human-male", n = { x = 53 }, c = { x = { { 0.00, "Ты для нас очень ценный союзник, и ты получишь достойную награду." } } } } },
    [5265] = { d = 15.4, v = "human-male", n = { x = 174 }, c = { x = { { 0.00, "Серебряный Оплот уже много лет закрыт и запечатан." }, { 3.83, "Много лет не находилось достойных войти в него и прикоснуться к силе Серебряного Рассвета – до сегодняшнего дня." }, { 12.09, "Серебряный Оплот распахнул врата перед тобой." } } }, t = { d = 1.2, v = "narrator", n = { x = 4 }, c = { x = { { 0.00, "Ух ты..." } } } } },
    [5281] = { d = 27.1, v = "human-male", n = { x = 346 }, c = { x = { { 0.00, "Многие погибли во время битвы при Стратхольме." }, { 3.04, "Многие предпочли расстаться с жизнью, бросившись в пламя пожара, чем подвергнуться порче и примкнуть к Плети." }, { 10.12, "Теперь они скитаются по улицам Стратхольма в обличье бесплотных призраков." }, { 14.97, "Мы должны помочь им." }, { 16.32, "У меня есть помощник по имени Эган, он спец по призракам и духам." }, { 20.53, "Найди его." }, { 21.29, "Он, вероятно, сейчас в Восточных Чумных землях близ Стратхольма, проверяет свои изобретения." } } }, t = { d = 5.6, v = "dwarf-male", n = { x = 58 }, c = { x = { { 0.00, "Неужели Ален нашёл кого-то, у кого будет довольно храбрости помочь мне?" } } } } },
    [5282] = { d = 26.3, v = "dwarf-male", n = { x = 308 }, c = { x = { { 0.00, "Только безграничная ненависть к Плети поддерживает во мне силы и желание жить." }, { 5.50, "Но я не фанатик." }, { 6.65, "Не такой, как этот сброд из Алого ордена – они скорее убьют невинную нежить, чем удостоят хоть каплей сочувствия." }, { 14.70, "Возьми мой излучатель." }, { 16.30, "С его помощью ты сможешь освободить истерзанные души, обречённые на скитания в Стратхольме." }, { 22.69, "Стреляй в призраков, бродящих по улицам." }, { 25.57, "Освободи их!" } } }, t = { d = 11.8, v = "dwarf-male", n = { x = 114 }, c = { x = { { 0.00, "*Эган утирает скупую слезу*" }, { 2.72, "Видел ли ты мою матушку?" }, { 4.70, "Она обрела свободу?" }, { 6.33, "Ты просто образец благородства." }, { 8.80, "Прими эту скромную награду за труды..." } } } } },
    [5283] = { d = 33.5, g = 1, v = "dwarf-male", n = { m = 370, f = 371 }, c = { m = { { 0.00, "Ты принял верное решение." }, { 1.94, "Мы со стариной Железнусом друг друга не перевариваем." }, { 5.83, "Этот кустарь косорукий знает, кто тут настоящий мастер." }, { 9.99, "Великие войны не выигрываются без хорошего доспеха." }, { 13.82, "Когда дойдёт до дела, никакой меч не спасёт." }, { 17.03, "И никак иначе, так что возьмёмся-ка за работу." }, { 20.39, "Тебе нужно только показать мне, что у тебя есть природный талант к делу." }, { 25.82, "Потом я выкую из тебя настоящего бронника и как следует отшлифую." }, { 30.72, "Знаешь, как делать узорчатый мифрил, а?" } }, f = { { 0.00, "Ты приняла верное решение." }, { 2.00, "Мы со стариной Железнусом друг друга не перевариваем." }, { 6.27, "Этот кустарь косорукий знает, кто тут настоящий мастер." }, { 10.40, "Великие войны не выигрываются без хорошего доспеха." }, { 14.20, "Когда дойдёт до дела, никакой меч не спасёт." }, { 17.40, "И никак иначе, так что возьмёмся-ка за работу." }, { 20.73, "Тебе нужно только показать мне, что у тебя есть природный талант к делу." }, { 26.12, "Потом я выкую из тебя настоящего бронника и как следует отшлифую." }, { 30.99, "Знаешь, как делать узорчатый мифрил, а?" } } }, t = { d = 12.5, g = 1, v = "dwarf-male", n = { m = 126, f = 127 }, c = { m = { { 0.00, "Самое оно." }, { 0.86, "Теперь уж нельзя останавливаться." }, { 3.32, "Нет, ещё не поздно перейти на отковку шпилек, э-э-э, в оружейники податься." }, { 8.84, "Но я уверен, что ты сделал верный выбор." } }, f = { { 0.00, "Самое оно." }, { 0.92, "Теперь уж нельзя останавливаться." }, { 3.53, "Нет, ещё не поздно перейти на отковку шпилек, э-э-э, в оружейники податься." }, { 9.38, "Но я уверен, что ты сделала верный выбор." } } } } },
    [5284] = { d = 36.1, g = 1, v = "dwarf-male", n = { m = 399, f = 400 }, c = { m = { { 0.00, "Если станешь кузнецом, то к тебе очень часто будут обращаться за снаряжением всякие там герои и искатели приключений." }, { 8.79, "Хотя порой работы невпроворот, спина ноет и дышать нечем, плата покрывает всё с лихвой." }, { 15.43, "Да, вот ещё, у кузнецов всегда водится золотишко!" }, { 19.05, "Если хочешь стать одним из нас, тебе придётся доказать, что ты сможешь заработать для меня пару звонких монет – то есть показать, что ты усвоил всё, чтобы стать специалистом по изготовлению оружия высшего качества." }, { 34.75, "Приступай к работе!" } }, f = { { 0.00, "Если станешь кузнецом, то к тебе очень часто будут обращаться за снаряжением всякие там герои и искатели приключений." }, { 8.56, "Хотя порой работы невпроворот, спина ноет и дышать нечем, плата покрывает всё с лихвой." }, { 15.03, "Да, вот ещё, у кузнецов всегда водится золотишко!" }, { 18.55, "Если хочешь стать одной из нас, тебе придётся доказать, что ты сможешь заработать для меня пару звонких монет – то есть показать, что ты усвоила всё, чтобы стать специалистом по изготовлению оружия высшего качества." }, { 33.91, "Приступай к работе!" } } }, t = { d = 10.3, v = "dwarf-male", n = { x = 111 }, c = { x = { { 0.00, "Как раз вовремя!" }, { 1.26, "Заказчики уже ждут." }, { 2.79, "Давай сюда свои изделия да слушай внимательнее." }, { 6.56, "Сейчас ты делаешь первый шаг в карьере оружейника." } } } } },
    [5301] = { d = 38.8, g = 1, v = "orc-male", n = { m = 367, f = 367 }, c = { m = { { 0.00, "Моя работа приносит мне подлинное удовлетворение!" }, { 4.20, "Когда я вижу гордого воина Орды, защищённого моими доспехами, я понимаю, зачем родился на свет." }, { 12.30, "Это как наваждение, я без этого просто жить не могу." }, { 16.73, "Конечно, этому я тебя научить не смогу – я могу только указать тебе путь." }, { 23.07, "Ведь кузнечное ремесло, как и любая жизненная стезя, – это путешествие." }, { 29.10, "Если ты хочешь стать одним из избранных, я, конечно, готов тебя учить." }, { 35.14, "Но сначала тебе нужно выполнить моё задание." } }, f = { { 0.00, "Моя работа приносит мне подлинное удовлетворение!" }, { 4.17, "Когда я вижу гордого воина Орды, защищённого моими доспехами, я понимаю, зачем родился на свет." }, { 12.20, "Это как наваждение, я без этого просто жить не могу." }, { 16.59, "Конечно, этому я тебя научить не смогу – я могу только указать тебе путь." }, { 22.88, "Ведь кузнечное ремесло, как и любая жизненная стезя, – это путешествие." }, { 28.86, "Если ты хочешь стать одной из избранных, я, конечно, готов тебя учить." }, { 34.85, "Но сначала тебе нужно выполнить моё задание." } } }, t = { d = 15.0, v = "orc-male", n = { x = 142 }, c = { x = { { 0.00, "Это последний шаг перед тем, как ты начнёшь свою новую карьеру в школе Брони." }, { 6.70, "Если ты колеблешься, сейчас твой последний шанс отступить." }, { 11.69, "А иначе готовься к жизни, полной славы!" } } } } },
    [5302] = { d = 28.2, g = 1, v = "orc-male", n = { m = 257, f = 257 }, c = { m = { { 0.00, "В один прекрасный день я создам легендарный молот." }, { 4.42, "Молот, достойный вождя!" }, { 6.55, "Это труд всей моей жизни." }, { 8.83, "Моё главное и единственное увлечение." }, { 12.07, "Я вижу, что ты можешь стать одним из нас – оружейником!" }, { 16.80, "И я помогу тебе в этом, если хочешь." }, { 20.11, "Тебе нужно только выполнить простое задание." }, { 24.13, "При твоём мастерстве оно и впрямь несложное." } }, f = { { 0.00, "В один прекрасный день я создам легендарный молот." }, { 4.49, "Молот, достойный вождя!" }, { 6.66, "Это труд всей моей жизни." }, { 8.99, "Моё главное и единственное увлечение." }, { 12.27, "Я вижу, что ты можешь стать одной из нас – оружейником!" }, { 17.09, "И я помогу тебе в этом, если хочешь." }, { 20.46, "Тебе нужно только выполнить простое задание." }, { 24.55, "При твоём мастерстве оно и впрямь несложное." } } }, t = { d = 14.4, v = "orc-male", n = { x = 147 }, c = { x = { { 0.00, "Это последний шаг перед тем, как ты начнёшь новую карьеру оружейника." }, { 5.64, "Если передумаешь – сейчас последняя возможность отказаться." }, { 10.54, "Иначе – готовься с головой погрузиться в знания!" } } } } },
    [5305] = { d = 26.6, v = "scourge-female#80", n = { x = 224 }, c = { x = { { 0.00, "В казематах Бастиона Алого ордена таится чертёж «Безмятежности»." }, { 6.10, "Багровый молотобоец стережёт его как зеницу ока." }, { 10.74, "Срази его и принеси мне его фартук." }, { 14.27, "За это я открою тебе секреты школы Молота." }, { 18.48, "Но запомни." }, { 19.59, "Если ты выберешь это умение, Школы Меча и Топора будут для тебя закрыты." } } }, t = { d = 13.4, g = 1, v = "scourge-female#80", n = { m = 114, f = 115 }, c = { m = { { 0.00, "Так ты уверен, что хочешь именно этого?" }, { 3.61, "Стать мастером молотов?" }, { 5.74, "Помни, что тогда для тебя навсегда закроется путь в школу Меча и школу Топора." } }, f = { { 0.00, "Так ты уверена, что хочешь именно этого?" }, { 3.83, "Стать мастером молотов?" }, { 6.04, "Помни, что тогда для тебя навсегда закроется путь в школу Меча и школу Топора." } } } } },
    [5306] = { d = 34.0, g = 1, v = "troll-male", n = { x = 289 }, c = { m = { { 0.00, "Пусть её красота не обманывает тебя, герой." }, { 4.16, "Тёмная охотница Вос'гаджин безумна и смертельно опасна." }, { 9.36, "*Килрам указывает на шрам у себя на лице.*" }, { 12.72, "Да, это её рук дело – \"прикосновение любви\", как она выразилась." }, { 18.58, "Наконец настал час отмщения." }, { 21.22, "Вос'гаджин ты найдёшь на Пике Чёрной горы." }, { 25.02, "Убей её и принеси мне её змеекамень." }, { 28.32, "Сделай это, и я научу тебя, как выковать Лезвие Рассвета!" } }, f = { { 0.00, "Пусть её красота не обманывает тебя, героиня." }, { 4.33, "Тёмная охотница Вос'гаджин безумна и смертельно опасна." }, { 9.52, "*Килрам указывает на шрам у себя на лице.*" }, { 12.88, "Да, это её рук дело – \"прикосновение любви\", как она выразилась." }, { 18.83, "Наконец настал час отмщения." }, { 21.51, "Вос'гаджин ты найдёшь на Пике Чёрной горы." }, { 25.37, "Убей её и принеси мне её змеекамень." }, { 28.72, "Сделай это, и я научу тебя, как выковать Лезвие Рассвета!" } } }, t = { d = 9.7, g = 1, v = "troll-male", n = { m = 97, f = 98 }, c = { m = { { 0.00, "Ты уверен, что тебе нужна именно эта школа?" }, { 3.45, "Помни, что это закроет для тебя возможность вступить в школу Меча или Молота." } }, f = { { 0.00, "Ты уверена, что тебе нужна именно эта школа?" }, { 3.61, "Помни, что это закроет для тебя возможность вступить в школу Меча или Молота." } } } } },
    [5307] = { d = 27.4, v = "human-male#50", n = { x = 316 }, c = { x = { { 0.00, "Если я резок с тобой, на то есть причины." }, { 2.94, "Чертежи для создания великого меча, известного под именем Порча, были похищены Чёрной стражей: элитным отрядом скелетов барона Ривендера." }, { 12.73, "Да, именно, Ривендера из Стратхольма..." }, { 15.48, "Оружейник Чёрной стражи хранит теперь эти чертежи как зеницу ока." }, { 20.21, "Убей его и принеси доказательство его смерти, и в благодарность я научу тебя премудростям школы меча." } } }, t = { d = 10.8, g = 1, v = "human-male#50", n = { m = 114, f = 115 }, c = { m = { { 0.00, "Так ты уверен, что хочешь именно этого?" }, { 2.91, "Стать мастером мечей?" }, { 4.50, "Помни, что тогда для тебя навсегда закроется путь в школу Молота и школу Топора." } }, f = { { 0.00, "Так ты уверена, что хочешь именно этого?" }, { 3.10, "Стать мастером мечей?" }, { 4.75, "Помни, что тогда для тебя навсегда закроется путь в школу Молота и школу Топора." } } } } },
    [5321] = { d = 38.4, v = "nightelf-male", n = { x = 384 }, c = { x = { { 0.00, "Я шёл к Заставе Мейстры, чтобы встретиться с Лиладрис Лунной Рекой, но решил остановиться здесь и немного вздремнуть." }, { 9.01, "С тех пор как я очнулся от Изумрудного Сна, я всё время такой сонный..." }, { 14.38, "*зевает*" }, { 14.95, "И я нигде не могу найти свои вещи!" }, { 17.83, "Поможешь мне их отыскать?" }, { 19.78, "Я так понимаю, Застава Мейстры находится к югу отсюда, в Ясеневом лесу, у дороги." }, { 26.14, "Я пришёл оттуда..." }, { 27.54, "Да, и вот ещё что: я могу заснуть по дороге, так что если тебе нужно будет меня разбудить, сделай это с помощью моего рога." }, { 37.17, "Он в этом сундуке." } } }, t = { d = 11.1, v = "nightelf-female#51", n = { x = 124 }, c = { x = { { 0.00, "О, я так рада, что Керлониан смог сюда добраться." }, { 3.48, "И я уверена, что найду его спящим где-нибудь поблизости, ведь так?" }, { 8.17, "Спасибо вам за то, что показали ему дорогу." } } } } },
    [5341] = { d = 31.1, v = "scourge-male#83", n = { x = 313 }, c = { x = { { 0.00, "В Некроситете находятся сокровища семейства Баровых." }, { 4.62, "Я, Алекси Баров, один из двух оставшихся наследников нашего дома." }, { 10.00, "Второй – мой брат, Уэлдон." }, { 12.14, "Этот жалкий трус бежал во время войны и по-прежнему длит своё никчёмное существование в человеческом обличье." }, { 20.91, "Сейчас он ищет документы, чтобы унаследовать всё состояние." }, { 25.77, "Доберись до этих документов раньше моего брата, и я озолочу тебя!" } } }, t = { d = 6.6, g = 1, v = "scourge-male#83", n = { x = 58 }, c = { m = { { 0.00, "Отличная работа, герой." }, { 2.06, "Теперь главное – подтвердить моё право наследования..." } }, f = { { 0.00, "Отличная работа, героиня." }, { 2.21, "Теперь главное – подтвердить моё право наследования..." } } } } },
    [5342] = { d = 30.1, v = "scourge-male#83", n = { x = 296 }, c = { x = { { 0.00, "Естественно, пока мой брат жив, могут возникать вопросы о порядке наследования." }, { 6.22, "Я не допущу этого." }, { 7.72, "Полагаю, ты, шваль, не побоишься замарать руки убийством." }, { 12.23, "Задание простое, надеюсь, ты справишься, если хочешь получить награду." }, { 17.88, "Уэлдон сидит под крылышком у Альянса в Лагере Промозглого Ветра на востоке." }, { 23.89, "Убей его и принеси мне голову." }, { 26.32, "*Алекси зевает.*" }, { 28.08, "Давай-давай, иди." } } }, t = { d = 13.0, v = "scourge-male#83", n = { x = 108 }, c = { x = { { 0.00, "Чудесно!" }, { 0.94, "Теперь лишь в моих руках мощь и все сокровища дома Баровых." }, { 7.04, "*Алекси швыряет в вас большим мешком.*" }, { 10.32, "Сдачу оставь себе, животное." } } } } },
    [5343] = { d = 26.5, v = "human-male", n = { x = 283 }, c = { x = { { 0.00, "Милый братец Алекси." }, { 1.82, "И зачем я, глупец, пощадил его?" }, { 4.56, "Я смотрел в лицо врага, нежити, и оставил его в живых." }, { 9.20, "*Уэлдон сплёвывает.*" }, { 11.12, "Он хочет отобрать МОЁ наследие." }, { 13.29, "Не бывать тому!" }, { 14.41, "Найди документы на мои владения, прежде чем эта мерзость дотянется до них своими костлявыми ручками, и получишь большую награду." }, { 23.27, "Документы находятся в руинах Некроситета." }, { 26.13, "Спеши!" } } }, t = { d = 2.9, v = "human-male", n = { x = 27 }, c = { x = { { 0.00, "Я хочу дать тебе ещё одно задание." } } } } },
    [5344] = { d = 28.8, g = 1, v = "human-male", n = { m = 318, f = 320 }, c = { m = { { 0.00, "Документы у меня в руках, осталось только одно." }, { 3.58, "Алекси придётся убить." }, { 5.23, "Когда он умрёт, я смогу вздохнуть спокойно, не ожидая гибели от руки наёмного убийцы." }, { 11.45, "Задание простое." }, { 12.71, "Алекси находится под покровительством Орды – в Бастионе." }, { 16.82, "Нет, я не требую, чтобы ты прямо взял и убил его, мне голова нужна!" }, { 21.78, "А как ты её получишь... твоё дело." }, { 24.23, "Подобные размышления ниже моего аристократического достоинства." } }, f = { { 0.00, "Документы у меня в руках, осталось только одно." }, { 3.56, "Алекси придётся убить." }, { 5.21, "Когда он умрёт, я смогу вздохнуть спокойно, не ожидая гибели от руки наёмного убийцы." }, { 11.41, "Задание простое." }, { 12.66, "Алекси находится под покровительством Орды – в Бастионе." }, { 16.75, "Нет, я не требую, чтобы ты прямо взяла и убила его, мне голова нужна!" }, { 21.89, "А как ты её получишь... твоё дело." }, { 24.33, "Подобные размышления ниже моего аристократического достоинства." } } }, t = { d = 11.1, v = "human-male", n = { x = 110 }, c = { x = { { 0.00, "О радость, о счастье!" }, { 1.78, "Наконец-то чёрная овца в стаде семьи Баровых мертва, и я получил наследство!" }, { 8.08, "Возьми деньги и убирайся, деревенщина." } } } } },
    [5361] = { d = 39.7, v = "tauren-male#67", n = { x = 390 }, c = { x = { { 0.00, "Мой брат, Натака, находится на Заставе Скитающихся Духов в Пустошах." }, { 5.55, "Я хотел бы попросить вас... не доставите ли ему этот отчёт?" }, { 10.37, "С тех пор, как я писал ему последний раз, прошёл целый год, и вот сейчас кентавры опять что-то затевают." }, { 18.81, "Мой брат должен узнать обо всём." }, { 21.40, "Вам нужно будет отправиться в Когтистые горы – они к северу от Перекрёстка, а потом свернуть на запад, в Обугленную долину." }, { 31.47, "Пустоши находятся южнее долины." }, { 34.21, "Следуйте по дороге на юг, и скоро увидите Заставу Скитающихся Духов." } } }, t = { d = 21.5, g = 1, v = "tauren-male", n = { x = 180 }, c = { m = { { 0.00, "Не знаю, как вы связаны с моим братом, но, вижу, он вам доверяет, герой." }, { 6.38, "Я – Натака Длинный Рог, и я приветствую вас на Заставе Скитающихся Духов!" }, { 12.75, "Герой нам здесь точно не помешает." }, { 15.78, "Поговорите с другими, наверняка у них найдётся работа для вас." } }, f = { { 0.00, "Не знаю, как вы связаны с моим братом, но, вижу, он вам доверяет, героиня." }, { 6.61, "Я – Натака Длинный Рог, и я приветствую вас на Заставе Скитающихся Духов!" }, { 13.06, "Героиня нам здесь точно не помешает." }, { 16.28, "Поговорите с другими, наверняка у них найдётся работа для вас." } } } } },
    [5381] = { d = 31.6, v = "tauren-male#68", n = { x = 341 }, c = { x = { { 0.00, "В руки клана Пылающего Клинка попала демоническая шкатулка, в которой хранится могущественный артефакт – Рука Ируксоса." }, { 9.49, "Орки из клана Пылающего Клинка используют её, чтобы открывать демонические порталы на поле Маннорок." }, { 17.48, "Мы должны остановить нашествие демонов, захлёстывающее наш мир!" }, { 22.33, "Расколи красный кристалл в крепости Громового Топора этой киркой демонов: так ты сможешь добыть демоническую шкатулку." } } }, t = { d = 14.1, g = 1, v = "tauren-male#68", n = { x = 90 }, c = { m = { { 0.00, "О, Демоническая шкатулка..." }, { 2.96, "Наконец-то я увидел её." }, { 5.53, "Послушай, герой, дай-ка её мне, и я её открою... и покажу тебе Руку Ируксоса." } }, f = { { 0.00, "О, Демоническая шкатулка..." }, { 2.97, "Наконец-то я увидел её." }, { 5.55, "Послушай, героиня, дай-ка её мне, и я её открою... и покажу тебе Руку Ируксоса." } } } } },
    [5382] = { d = 17.1, v = "human-female", n = { x = 194 }, c = { x = { { 0.00, "Крастинов виновен в тысячах смертей." }, { 2.77, "Справедливость должна восторжествовать – пусть он вкусит собственного блюда." }, { 8.36, "Найди его и заставь испытать мучения его бессчётных жертв." }, { 12.75, "Когда он умрёт, сожги наши останки." }, { 15.45, "Пусть обратятся в пепел." } } }, t = { d = 7.4, g = 1, v = "human-female", n = { m = 59, f = 60 }, c = { m = { { 0.00, "Душа моя исцелена." }, { 1.89, "Ты оказал нам с мужем огромную услугу, но это ещё не всё." } }, f = { { 0.00, "Душа моя исцелена." }, { 1.93, "Ты оказала нам с мужем огромную услугу, но это ещё не всё." } } } } },
    [5384] = { d = 32.0, v = "human-female", n = { x = 333 }, c = { x = { { 0.00, "Вот она." }, { 0.80, "*Ева указывает на сосуд в мешке.*" }, { 4.08, "Кровь невинных." }, { 5.24, "Чистейшая кровь, умилостивление хозяина Крастинова." }, { 9.07, "При помощи этой крови можно вызвать Киртоноса, и именно она поможет его уничтожить." }, { 15.55, "Отнеси эту кровь на балкон, помести в жаровню." }, { 19.10, "Киртонос явится на зов – он не сможет устоять." }, { 22.59, "Когда он явится, обрушь на него ярость и гнев тысяч невинно убиенных." }, { 27.91, "Если ты добьёшься успеха, мы на славу отблагодарим тебя." } } }, t = { d = 18.7, v = "human-female", n = { x = 196 }, c = { x = { { 0.00, "Киртонос мёртв, и страшная глава истории Некроситета подошла к концу." }, { 5.42, "Но твои деяния не окончены." }, { 7.60, "Многие узнали о твоих подвигах." }, { 10.14, "Возьми это." }, { 11.13, "Это часть нашей сущности." }, { 13.17, "При её помощи ты сможешь связаться с другими павшими душами Каэр Дарроу." } } } } },
    [5385] = { d = 17.7, v = "narrator", n = { x = 195 }, c = { x = { { 0.00, "Вы осторожно поднимаете мешок и собираетесь возвращаться к Джессире Лунной Радуге на границу Ясеневого леса и Осквернённого леса." }, { 9.93, "Вы надеетесь, что паладин будет с почестями погребён, когда его останки будут доставлены его друзьям." } } }, t = { d = 23.8, g = 1, v = "nightelf-female", n = { m = 254, f = 258 }, c = { m = { { 0.00, "Тебе удалось!" }, { 1.06, "Хвала Элуне и всем силам, что ты почитаешь!" }, { 4.24, "Сегодня ты совершил деяние благое и почётное." }, { 7.54, "Я уверена, что Арконарин возрадуется, узнав, что ты не только спас её, но также убил тварь, которая истязала одного из лучших её друзей." }, { 17.40, "Я бы хотела сделать для тебя больше, но прошу тебя – прими эту скромную награду." } }, f = { { 0.00, "Тебе удалось!" }, { 1.07, "Хвала Элуне и всем силам, что ты почитаешь!" }, { 4.26, "Сегодня ты совершила деяние благое и почётное." }, { 7.66, "Я уверена, что Арконарин возрадуется, узнав, что ты не только спасла её, но также убила тварь, которая истязала одного из лучших её друзей." }, { 17.85, "Я бы хотела сделать для тебя больше, но прошу тебя – прими эту скромную награду." } } } } },
    [5386] = { d = 40.6, v = "tauren-male", n = { x = 400 }, c = { x = { { 0.00, "Давненько на Заставе Скитающихся Духов не наслаждались запахом жареной рыбки..." }, { 6.66, "Тролли, живущие в Деревне Ночных Охотников – отличные рыбаки, вот только из-за разбушевавшихся в наших краях кентавров мне никак не выкроить времени, чтобы добраться до них." }, { 21.19, "Послушай-ка, окажи мне услугу: отправляйся в Деревню Ночных Охотников." }, { 27.10, "Разыщи там Джинар'Зиллена, потолкуй с ним и принеси мне рыбок-кровобрюхов: я их просто обожаю!" }, { 34.89, "На юг отсюда идёт дорога: она приведёт тебя аккурат в деревню троллей." } } }, t = { d = 14.6, g = 1, v = "tauren-male", n = { m = 134, f = 136 }, c = { m = { { 0.00, "Ты просто спас меня!" }, { 1.87, "А эти кровобрюхи так хороши, что хоть сырыми их ешь." }, { 6.51, "Ну, давай, давай скорее, выбери один из этих предметов в уплату за рыбу!.." } }, f = { { 0.00, "Ты просто спасла меня!" }, { 2.20, "А эти кровобрюхи так хороши, что хоть сырыми их ешь." }, { 7.02, "Ну, давай, давай скорее, выбери один из этих предметов в уплату за рыбу!.." } } } } },
    [5401] = { t = { d = 32.6, g = 1, v = "human-female#47", n = { x = 366 }, c = { m = { { 0.00, "Все, кто сражается со злом во имя Серебряного Рассвета, должны носить наш жетон." }, { 5.50, "Он даёт право на награды, которые предлагают наши интенданты." }, { 9.75, "Пока ты носишь жетон, ты сможешь добывать камни Плети у убитых воинов Плети – это знаки различия, которые у них иногда бывают." }, { 18.68, "Добывай эти знаки и приноси мне." }, { 21.00, "За каждый сданный набор ты получишь наш знак геройства – знак доблести Серебряного Рассвета." }, { 27.31, "Исполни своё предназначение, герой, – вступай в бой уже сегодня!" } }, f = { { 0.00, "Все, кто сражается со злом во имя Серебряного Рассвета, должны носить наш жетон." }, { 5.64, "Он даёт право на награды, которые предлагают наши интенданты." }, { 10.00, "Пока ты носишь жетон, ты сможешь добывать камни Плети у убитых воинов Плети – это знаки различия, которые у них иногда бывают." }, { 19.17, "Добывай эти знаки и приноси мне." }, { 21.55, "За каждый сданный набор ты получишь наш знак геройства – знак доблести Серебряного Рассвета." }, { 28.02, "Исполни своё предназначение, героиня, – вступай в бой уже сегодня!" } } } } },
    [5402] = { t = { d = 32.0, g = 1, v = "human-female#47", n = { m = 382, f = 383 }, c = { m = { { 0.00, "Поздравляю – и с радостью вручаю тебе знак доблести Серебряного Рассвета!" }, { 5.00, "Эти знаки служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережём для самых преданных наших сторонников." }, { 19.64, "Во-вторых – их можно отдавать нашим интендантам вместе с деньгами и получать ценные предметы, которые изготовляют в нашем ордене." }, { 28.53, "Так или иначе, ты их заслужил сполна." }, { 31.12, "Молодец!" } }, f = { { 0.00, "Поздравляю – и с радостью вручаю тебе знак доблести Серебряного Рассвета!" }, { 5.06, "Эти знаки служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережём для самых преданных наших сторонников." }, { 19.85, "Во-вторых – их можно отдавать нашим интендантам вместе с деньгами и получать ценные предметы, которые изготовляют в нашем ордене." }, { 28.83, "Так или иначе, ты их заслужила сполна." }, { 31.52, "Молодец!" } } } } },
    [5403] = { t = { d = 24.8, v = "human-female#47", n = { x = 307 }, c = { x = { { 0.00, "Поздравляю – и с радостью вручаю тебе знак доблести Серебряного Рассвета!" }, { 4.95, "Каждый выданный знак доблести приближает час победы над Плетью!" }, { 9.23, "Всё больше героев вступают в бой с Плетью на её землях, и Серебряный Рассвет несомненно будет в первых рядах той армии, что решится положить конец бесчинствам прихвостней Повелителя Тьмы." }, { 21.82, "Надеюсь, твоей доблести хватит и до того дня!" } } } } },
    [5404] = { t = { d = 20.9, v = "human-female#47", n = { x = 241 }, c = { x = { { 0.00, "Поздравляю – и с радостью вручаю тебе знак доблести Серебряного Рассвета!" }, { 5.22, "Те, кто удостаивается этих знаков – подлинные борцы за добро." }, { 9.61, "Мы благодарны всем, кто выступает против Плети, но убийство одного из её главарей – настоящий подвиг и тяжелейший удар по нашему противнику!" }, { 19.54, "За Рассвет, брат мой!" } } } } },
