    [5421] = { d = 28.6, g = 1, v = "troll-male", n = { m = 272, f = 273 }, c = { m = { { 0.00, "Я награжу любого, кто хоть немного облегчит мою жизнь..." }, { 4.61, "Чем меньше у меня работы, тем лучше, дружище!" }, { 8.41, "Здесь неподалёку, в деревне Ночных Охотников, прямо за пристанью, я расставил ловушки на моллюсков." }, { 16.44, "Много, много ловушек!" }, { 18.30, "Будь так любезен, сделай за меня мою работу: собери улов и принеси мне, а я уж тебя награжу кое-чем нужным... ну, ты понял, да?" } }, f = { { 0.00, "Я награжу любого, кто хоть немного облегчит мою жизнь..." }, { 4.52, "Чем меньше у меня работы, тем лучше, дружище!" }, { 8.25, "Здесь неподалёку, в деревне Ночных Охотников, прямо за пристанью, я расставил ловушки на моллюсков." }, { 16.13, "Много, много ловушек!" }, { 17.95, "Будь так любезна, сделай за меня мою работу: собери улов и принеси мне, а я уж тебя награжу кое-чем нужным... ну, ты поняла, да?" } } }, t = { d = 9.9, g = 1, v = "troll-male", n = { m = 80, f = 80 }, c = { m = { { 0.00, "Ах, дружочек, нет ничего лучше хорошо сделанной работы, особенно когда делаешь её не ты..." }, { 8.93, "Верно ведь?" } }, f = { { 0.00, "Ах, подружка, нет ничего лучше хорошо сделанной работы, особенно когда делаешь её не ты..." }, { 8.57, "Верно ведь?" } } } } },
    [5441] = { d = 25.0, g = 1, v = "orc-male", n = { x = 233 }, c = { m = { { 0.00, "Проклятые батраки!" }, { 1.59, "Им велено валить лес, но они всё время пытаются отлынивать." }, { 6.58, "Мне нужен кто-то, кто их приструнит." }, { 9.61, "Ты, герой, мне, пожалуй, годишься." }, { 12.48, "На тебе дубинку – ступай и всыпь этим бездельникам." }, { 16.80, "Хороший тумак заставит их взяться за ум!" }, { 20.20, "Управишься – не забудь вернуть дубинку." }, { 23.53, "Проклятые лентяи..." } }, f = { { 0.00, "Проклятые батраки!" }, { 1.57, "Им велено валить лес, но они всё время пытаются отлынивать." }, { 6.52, "Мне нужен кто-то, кто их приструнит." }, { 9.52, "Ты, героиня, мне, пожалуй, годишься." }, { 12.52, "На тебе дубинку – ступай и всыпь этим бездельникам." }, { 16.79, "Хороший тумак заставит их взяться за ум!" }, { 20.17, "Управишься – не забудь вернуть дубинку." }, { 23.47, "Проклятые лентяи..." } } }, t = { d = 8.1, v = "orc-male", n = { x = 71 }, c = { x = { { 0.00, "Отлично, отлично!" }, { 1.68, "В следующий раз будут знать, как дрыхнуть на работе!" }, { 6.48, "Спасибо за помощь!" } } } } },
    [5461] = { d = 27.6, v = "human-male", n = { x = 332 }, c = { x = { { 0.00, "Нежить боится жизни не меньше, чем живые – смерти." }, { 3.59, "Ступившие на путь не-жизни нередко уничтожают все свидетельства прежнего бытия." }, { 9.08, "К сожалению, для создания артефакта, способного превратить Раса Снегошёпота в смертного, мы должны отыскать какой-то предмет, сохранившийся со времени его настоящей жизни." }, { 20.93, "Отправляйся в разрушенный город Стромгард, родину Снегошёпота, и найди такой предмет." }, { 26.86, "Удачи тебе." } } }, t = { d = 16.3, v = "human-male", n = { x = 179 }, c = { x = { { 0.00, "Честно говоря, я сомневался, что эта вещь вообще существует." }, { 4.54, "Перед нами открывается удивительная возможность – главное, её не пропустить." }, { 10.23, "Готовься, ведь то, о чём я тебя попрошу, низведет тебя в самые глубины Преисподней." } } } } },
    [5462] = { d = 30.8, v = "human-male", n = { x = 370 }, c = { x = { { 0.00, "Памятную вещь нужно настроить на осквернённой земле." }, { 3.56, "Говорят, будто Снегошёпот встал под знамёна Короля-лича в Стратхольме." }, { 8.31, "Он добровольно лишил себя жизни с целью влиться в ряды нежити." }, { 12.75, "Именно то место, где он умер, и нужно найти." }, { 15.88, "В Часовне Последней Надежды ты найдёшь Леонида Бартоломея Чтимого, некогда бывшего рабом Плети, освобождённого королевой банши, но отдавшего свою верность Серебряному Рассвету." }, { 28.00, "Быть может, он знает больше, чем я." }, { 30.44, "В путь!" } } }, t = { d = 9.4, v = "scourge-male", n = { x = 84 }, c = { x = { { 0.00, "*Леонид проглядывает книгу.*" }, { 2.40, "Ты заставляешь меня вспоминать события, о которых хотелось забыть навек." } } } } },
    [5463] = { d = 51.0, g = 1, v = "scourge-male", n = { x = 432 }, c = { m = { { 0.00, "Рас Снегошёпот некогда тоже был человеком." }, { 3.83, "Я собственными глазами видел, как он вручил свою бессмертную душу Королю-личу." }, { 11.17, "Он приставил к своему горлу кинжал и с улыбкой перерезал себе глотку от уха до уха." }, { 19.00, "Его мёртвое тело упало в центр пентаграммы." }, { 23.00, "Король-лич бросил взгляд на мёртвого мага, и в ту же секунду Рас Снегошёпот восстал в обличье лича." }, { 31.84, "*Леонид опускает глаза на мгновенье и снова продолжает рассказ*" }, { 36.48, "Да, герой, я помню." }, { 38.70, "У того, что ты ищешь, есть имя – Дар Менетила: это земля, благословлённая Королём-личом – священное место Плети." } }, f = { { 0.00, "Рас Снегошёпот некогда тоже был человеком." }, { 3.82, "Я собственными глазами видел, как он вручил свою бессмертную душу Королю-личу." }, { 11.14, "Он приставил к своему горлу кинжал и с улыбкой перерезал себе глотку от уха до уха." }, { 18.96, "Его мёртвое тело упало в центр пентаграммы." }, { 22.95, "Король-лич бросил взгляд на мёртвого мага, и в ту же секунду Рас Снегошёпот восстал в обличье лича." }, { 31.76, "*Леонид опускает глаза на мгновенье и снова продолжает рассказ*" }, { 36.48, "Да, героиня, я помню." }, { 38.87, "У того, что ты ищешь, есть имя – Дар Менетила: это земля, благословлённая Королём-личом – священное место Плети." } } }, t = { d = 3.5, v = "narrator", n = { x = 33 }, c = { x = { { 0.00, "Вы кладёте книгу на осквернённую землю." } } } } },
    [5464] = { d = 13.2, v = "narrator", n = { x = 133 }, c = { x = { { 0.00, "Души падших цепляются за любое олицетворение их прежней жизни и превращают любой значимый для них предмет в Книгу Души." }, { 9.98, "Вы поднимаете предмет и прячете в сумку." } } }, t = { d = 9.7, v = "scourge-male", n = { x = 88 }, c = { x = { { 0.00, "Как эта душа цепляется за книгу, так же она будет цепляться и за человеческое обличье Раса Ледяного Шёпота." } } } } },
    [5465] = { d = 5.0, v = "scourge-male", n = { x = 48 }, c = { x = { { 0.00, "Отнеси книгу Мардюку, он расскажет тебе, что делать дальше." } } }, t = { d = 5.4, v = "human-male", n = { x = 60 }, c = { x = { { 0.00, "Признаться, я ожидал вновь увидеть тебя в обличье несчастного призрака." } } } } },
    [5466] = { d = 24.4, v = "human-male", n = { x = 255 }, c = { x = { { 0.00, "Осталось одно задание – бросить вызов личу Расу Снегошёпоту." }, { 4.72, "Воспользуйся против него силой Книги – не знай пощады!" }, { 8.95, "Терпи удары, которые обрушит на тебя злобная тварь." }, { 12.97, "Не бойся боли!" }, { 14.15, "Когда ритуал будет завершён, Рас снова станет смертным." }, { 18.45, "Именно в этот момент его необходимо убить." }, { 21.84, "Срази злодея и забери его голову." } } }, t = { d = 7.2, g = 1, v = "human-male", n = { m = 72, f = 74 }, c = { m = { { 0.00, "Десять тысяч душ возопили единым гласом!" }, { 3.49, "Ты нанёс смертельный удар Плети и её хозяевам." } }, f = { { 0.00, "Десять тысяч душ возопили единым гласом!" }, { 3.38, "Ты нанесла смертельный удар Плети и её хозяевам." } } } } },
    [5481] = { d = 19.0, v = "named/271613", n = { x = 159 }, c = { x = { { 0.00, "Хозяину надо растения." }, { 2.25, "У нас большие руки, цветы рвать никак." }, { 5.97, "Ты нам помогать, мы тебя не трогать." }, { 9.43, "Нам надо мракоцвет, он растёт тут и у дороги." }, { 13.67, "Ты соберёшь – отнеси хозяину Холланду на кладбище в Брилл." } } }, t = { d = 32.4, v = "scourge-male#82", n = { x = 283 }, c = { x = { { 0.00, "Что это?" }, { 0.82, "Мракоцвет?!" }, { 1.89, "Зачем он мне сдался?!" }, { 3.85, "Эта тупая гора мяса собирает ромашки и привлекает – сколько, Тёмная Госпожа знает, – к этому делу таких простаков, как ты!" }, { 15.09, "Без обид." }, { 15.99, "Ладно, главное, что ты здесь." }, { 18.62, "Я не собираюсь тратить своё время на то, чтобы объяснить этому поганищу элементарные вещи." }, { 26.82, "Так что, может, ты соберёшь для меня этот проклятый погибельник?" } } } } },
    [5482] = { d = 34.2, g = 1, v = "scourge-male#82", n = { m = 301, f = 301 }, c = { m = { { 0.00, "Теперь ты понимаешь, в каком затруднительном положении я нахожусь?" }, { 6.05, "Это нечто всё ещё ходит там и собирает не те растения." }, { 11.03, "Я непременно отблагодарю тебя, если ты соберёшь то, что мне нужно." }, { 16.99, "Принеси мне погибельник, и я щедро тебя награжу." }, { 21.47, "Насколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла." }, { 29.01, "Поторопись – и будь осторожен – в тех местах полно гноллов." } }, f = { { 0.00, "Теперь ты понимаешь, в каком затруднительном положении я нахожусь?" }, { 6.02, "Это нечто всё ещё ходит там и собирает не те растения." }, { 10.97, "Я непременно отблагодарю тебя, если ты соберёшь то, что мне нужно." }, { 16.91, "Принеси мне погибельник, и я щедро тебя награжу." }, { 21.37, "Насколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла." }, { 28.88, "Поторопись – и будь осторожна – в тех местах полно гноллов." } } }, t = { d = 21.8, g = 1, v = "scourge-male#82", n = { m = 157, f = 158 }, c = { m = { { 0.00, "А, мой погибельник!" }, { 3.01, "Превосходно!" }, { 4.88, "*Младший аптекарь Холланд жадно потирает ладони.*" }, { 8.72, "Он мне очень пригодится." }, { 11.36, "Ты оказал мне, ой, то есть Тёмной Госпоже, большую услугу." }, { 17.52, "Как я и обещал, вот твоя награда." } }, f = { { 0.00, "А, мой погибельник!" }, { 3.11, "Превосходно!" }, { 5.04, "*Младший аптекарь Холланд жадно потирает ладони.*" }, { 8.88, "Он мне очень пригодится." }, { 11.64, "Ты оказала мне, ой, то есть Тёмной Госпоже, большую услугу." }, { 18.17, "Как я и обещал, вот твоя награда." } } } } },
    [5501] = { d = 38.9, v = "goblin-male", n = { x = 418 }, c = { x = { { 0.00, "Мы тут на золотой жиле сидим, на золотой жиле!" }, { 3.46, "Знаешь, что это?" }, { 4.73, "Кости кодо!.." }, { 5.79, "Кости кодо изменят мир раз и навсегда!" }, { 8.66, "У меня масса клиентов, которые делают из этих костей мебель, музыкальные инструменты – даже взрывчатый порошок, чтоб тебе знать!" }, { 18.18, "Сюда приходит караван, забирает у меня кости, а потом караванщики продают их в Деревне Ночных Охотников." }, { 25.97, "И неплохая выручка, да, очень неплохая..." }, { 29.04, "Если пойдёшь на юг отсюда, то доберёшься прямиком до Кладбища кодо." }, { 33.90, "Принеси мне десяток костей, а я дам тебе кое-что взамен." }, { 38.09, "Ну что, идёт?" } } }, t = { d = 24.8, v = "goblin-male", n = { x = 240 }, c = { x = { { 0.00, "Ох, вот они, мои косточки, мои драгоценные!.." }, { 3.67, "Я стану самым богатым гоблином в мире, я прославлюсь, моё лицо не будет сходить с обложек \"Каравана истории\", и тогда они все ещё увидят, кто я такой!" }, { 15.69, "Да-да, особенно тот зелёный сморчок, который вечно твердил: \"Ничего достойного в жизни совершить не сможешь ты!\"" } } } } },
    [5502] = { d = 26.8, g = 1, v = "child-male", n = { m = 287, f = 289 }, c = { m = { { 0.00, "Ты был очень добр ко мне." }, { 1.77, "Я и представить не мог, что Детская неделя пройдёт так весело." }, { 6.18, "Спасибо." }, { 6.84, "Я не хочу печалиться из-за собственной судьбы – родители всегда говорили мне, что я должен быть выше всех несчастий." }, { 15.25, "Знаешь, когда я вырасту, я хочу стать героем... как ты." }, { 19.26, "Как ни жаль, мне пора домой." }, { 21.30, "Давай вернёмся, и я расскажу нашей попечительнице, что ты лучше всех!" } }, f = { { 0.00, "Ты была очень добра ко мне." }, { 2.07, "Я и представить не мог, что Детская неделя пройдёт так весело." }, { 6.55, "Спасибо." }, { 7.22, "Я не хочу печалиться из-за собственной судьбы – родители всегда говорили мне, что я должен быть выше всех несчастий." }, { 15.78, "Знаешь, когда я вырасту, я хочу стать героем... как ты." }, { 19.86, "Как ни жаль, мне пора домой." }, { 21.93, "Давай вернёмся, и я расскажу нашей попечительнице, что ты лучше всех!" } } }, t = { d = 26.1, g = 1, v = "orc-female#57", n = { m = 263, f = 264 }, c = { m = { { 0.00, "Да благословят тебя духи." }, { 2.03, "Ты сделал для Грунта больше, чем сделали бы для него многие другие." }, { 7.29, "Спасибо тебе – ты воплощение того, что значит быть героем Орды." }, { 12.27, "Прошу, если найдёшь время, навещай нас." }, { 15.36, "Я знаю, Грунт будет рад, как и я." }, { 17.88, "Грунту было с тобой так весело." }, { 20.41, "Он хочет подарить тебе одного из своих любимых питомцев – на память о нём." } }, f = { { 0.00, "Да благословят тебя духи." }, { 1.98, "Ты сделала для Грунта больше, чем сделали бы для него многие другие." }, { 7.16, "Спасибо тебе – ты воплощение того, что значит быть героем Орды." }, { 12.01, "Прошу, если найдёшь время, навещай нас." }, { 15.01, "Я знаю, Грунт будет рад, как и я." }, { 17.47, "Грунту было с тобой так весело." }, { 19.92, "Он хочет подарить тебе одного из своих любимых питомцев – на память о нём." } } } } },
    [5503] = { t = { d = 32.4, g = 1, v = "human-male", n = { x = 366 }, c = { m = { { 0.00, "Все, кто сражается со злом во имя Серебряного Рассвета, должны носить наш жетон." }, { 5.60, "Он даёт право на награды, которые предлагают наши интенданты." }, { 9.92, "Пока ты носишь жетон, ты сможешь добывать камни Плети у убитых воинов Плети – это знаки различия, которые у них иногда бывают." }, { 19.01, "Добывай эти знаки и приноси мне." }, { 21.37, "За каждый сданный набор ты получишь наш знак геройства – знак доблести Серебряного Рассвета." }, { 27.79, "Исполни своё предназначение, герой, – вступай в бой уже сегодня!" } }, f = { { 0.00, "Все, кто сражается со злом во имя Серебряного Рассвета, должны носить наш жетон." }, { 5.68, "Он даёт право на награды, которые предлагают наши интенданты." }, { 9.93, "Пока ты носишь жетон, ты сможешь добывать камни у убитых воинов плети – это знаки различия, которые у них иногда бывают." }, { 18.87, "Добывай эти знаки и приноси мне." }, { 21.26, "За каждый сданный набор ты получишь наш знак геройства – знак доблести Серебряного Рассвета." }, { 27.79, "Исполни своё предназначение, героиня, – вступай в бой уже сегодня!" } } } } },
    [5504] = { d = 28.8, v = "troll-female", n = { x = 332 }, c = { x = { { 0.00, "Тебе причитается награда за верную службу Серебряному Рассвету." }, { 4.64, "Тебе удалось завоевать всеобщее почтение." }, { 7.71, "Мне поручено передать – ты можешь купить один из самых ценных наших предметов – оплечье защиты от магии." }, { 15.35, "Если прикрепить его к доспехам, твоё сопротивление силам одного из пяти направлений магии возрастёт." }, { 22.61, "За это оплечье я попрошу от тебя не менее десяти знаков доблести Серебряного Рассвета." } } }, t = { d = 19.2, v = "troll-female", n = { x = 217 }, c = { x = { { 0.00, "Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету." }, { 5.47, "Теперь я с радостью предлагаю на выбор наши оплечья." }, { 9.41, "Пока наше отношение к тебе не изменится, ты сможешь купить эти оплечья у любого интенданта Серебряного Рассвета." }, { 17.81, "За Рассвет, брат мой!" } } } } },
    [5505] = { t = { d = 17.8, g = 1, v = "human-male", n = { m = 184, f = 186 }, c = { m = { { 0.00, "Ну вот, – отмычка готова." }, { 1.90, "Я почти уверен, что она откроет тебе путь в Некроситет." }, { 6.10, "Хотя убедиться в этом наверняка можно лишь одним способом." }, { 10.57, "Не теряй времени, испытай её, вот что я скажу." }, { 14.02, "Удачи, могучий герой." }, { 15.72, "Неси и дальше свет во тьму!" } }, f = { { 0.00, "Ну вот, – отмычка готова." }, { 1.90, "Я почти уверен, что она откроет тебе путь в Некроситет." }, { 6.10, "Хотя убедиться в этом наверняка можно лишь одним способом." }, { 10.58, "Не теряй времени, испытай её, вот что я скажу." }, { 14.04, "Удачи, могучая героиня." }, { 15.87, "Неси и дальше свет во тьму!" } } } } },
    [5507] = { d = 28.5, v = "gnome-male", n = { x = 332 }, c = { x = { { 0.00, "Тебе причитается награда за верную службу Серебряному Рассвету." }, { 4.59, "Тебе удалось завоевать всеобщее почтение." }, { 7.62, "Мне поручено передать – ты можешь купить один из самых ценных наших предметов – оплечье защиты от магии." }, { 15.18, "Если прикрепить его к доспехам, твоё сопротивление силам одного из пяти направлений магии возрастёт." }, { 22.36, "За это оплечье я попрошу от тебя не менее десяти знаков доблести Серебряного Рассвета." } } }, t = { d = 19.4, v = "gnome-male", n = { x = 225 }, c = { x = { { 0.00, "Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету." }, { 5.33, "Теперь я с радостью предлагаю на выбор наши оплечья." }, { 9.17, "Пока отношение нашего ордена к тебе не изменится, ты сможешь купить эти оплечья у любого интенданта Серебряного Рассвета." }, { 18.01, "За Рассвет, брат мой!" } } } } },
    [5508] = { t = { d = 19.9, v = "human-male", n = { x = 220 }, c = { x = { { 0.00, "Поздравляю!" }, { 0.88, "С гордостью вручаю тебе знак доблести Серебряного Рассвета." }, { 5.37, "Только настоящие герои и воины добра получают его." }, { 9.32, "Мы ценим любые деяния, направленные против подлой Плети, но убийство одного из их лидеров заслуживает особого почтения!" }, { 18.37, "Во имя Рассвета, брат!" } } } } },
    [5509] = { t = { d = 27.4, v = "human-male", n = { x = 327 }, c = { x = { { 0.00, "Поздравляю – и с радостью вручаю тебе знак доблести Серебряного Рассвета!" }, { 5.12, "Каждый выданный знак доблести означает, что вероятность победы Плети делается всё ниже." }, { 11.25, "Всё больше героев вступают в бой с Плетью на её землях, и Серебряный Рассвет несомненно будет в первых рядах той армии, что решится положить конец бесчинствам прихвостней Повелителя Тьмы." }, { 24.28, "Надеюсь, твоей доблести хватит и до того дня!" } } } } },
    [5510] = { t = { d = 32.1, g = 1, v = "human-male", n = { m = 381, f = 382 }, c = { m = { { 0.00, "Поздравляю – и с радостью вручаю тебе знак доблести Серебряного Рассвета!" }, { 5.09, "Они служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережём для самых преданных наших сторонников." }, { 19.53, "Во-вторых – ими можно расплачиваться с нашими интендантами, наряду с деньгами, и получать ценные предметы, которые изготовляют в нашем ордене." }, { 29.46, "Так или иначе, ты их заслужил." }, { 31.59, "Молодец!" } }, f = { { 0.00, "Поздравляю – и с радостью вручаю тебе знак доблести Серебряного Рассвета!" }, { 5.04, "Они служат двум целям – во-первых, позволяют упрочить твои позиции в Серебряном Рассвете; благодаря этому тебе станут доступны возможности и награды, которые мы бережём для самых преданных наших сторонников." }, { 19.35, "Во-вторых – ими можно расплачиваться с нашими интендантами, наряду с деньгами, и получать ценные предметы, которые изготовляют в нашем ордене." }, { 29.18, "Так или иначе, ты их заслужила." }, { 31.36, "Молодец!" } } } } },
    [5511] = { t = { d = 26.5, g = 1, v = "scourge-male", n = { m = 230, f = 232 }, c = { m = { { 0.00, "Ну вот, – отмычка готова." }, { 2.30, "Я почти уверен, что она откроет тебе путь в Некроситет." }, { 7.38, "Хотя убедиться в этом наверняка можно лишь одним способом." }, { 12.79, "Не теряй времени, испытай её, вот что я скажу." }, { 16.97, "Удачи, могучий герой." }, { 19.02, "Пусть твои победы и дальше приносят тебе славу и силу, пока ты крушишь Некроситет!" } }, f = { { 0.00, "Ну вот, – отмычка готова." }, { 2.21, "Я почти уверен, что она откроет тебе путь в Некроситет." }, { 7.11, "Хотя убедиться в этом наверняка можно лишь одним способом." }, { 12.33, "Не теряй времени, испытай её, вот что я скажу." }, { 16.36, "Удачи, могучая героиня." }, { 18.49, "Пусть твои победы и дальше приносят тебе славу и силу, пока ты крушишь Некроситет!" } } } } },
    [5513] = { d = 29.2, v = "dwarf-female#33", n = { x = 332 }, c = { x = { { 0.00, "Тебе причитается награда за верную службу Серебряному Рассвету." }, { 4.70, "Тебе удалось завоевать всеобщее почтение." }, { 7.82, "Мне поручено передать – ты можешь купить один из самых ценных наших предметов – оплечье защиты от магии." }, { 15.57, "Если прикрепить его к доспехам, твоё сопротивление силам одного из пяти направлений магии возрастёт." }, { 22.92, "За это оплечье я попрошу от тебя не менее десяти знаков доблести Серебряного Рассвета." } } }, t = { d = 20.5, v = "dwarf-female#33", n = { x = 222 }, c = { x = { { 0.00, "Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету." }, { 5.73, "Теперь я с радостью предлагаю на выбор наши оплечья." }, { 9.86, "Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета." }, { 19.02, "За Рассвет, брат мой!" } } } } },
    [5514] = { d = 30.9, v = "scourge-male#82", n = { x = 277 }, c = { x = { { 0.00, "Тебе нужно поговорить с гоблином по имени Кринкель Сталлинн." }, { 5.43, "Он работает в Прибамбасске, в пустыне Танарис." }, { 9.50, "Ему под силу сделать такую форму, но это обойдётся недёшево." }, { 14.84, "Мы просим тебя не скупиться и заплатить ему." }, { 18.83, "Я алхимик, а не банкир." }, { 20.91, "Будь у меня золото, я бы здесь не сидел." }, { 24.42, "Ну вот, опять я брякнул что-то не то." }, { 27.69, "Ладно." }, { 28.33, "Тебя ждёт Прибамбасск!" }, { 30.32, "Удачи!" } } }, t = { d = 17.4, v = "goblin-male#110", n = { x = 193 }, c = { x = { { 0.00, "Дитерс сказал, что ты принесёшь всё необходимое, и так оно и оказалось!" }, { 5.11, "Сделка есть сделка." }, { 6.56, "Дай-ка я сложу фрагменты скелетов в форму." }, { 9.75, "Дитерс их заранее закалил?" }, { 11.74, "Великолепно..." }, { 12.80, "В противном случае тебе пришлось бы тащиться обратно в Бастион." } } } } },
    [5515] = { d = 27.3, v = "human-female", n = { x = 305 }, c = { x = { { 0.00, "Мы сбросили с себя тяжёлое бремя, но твоё задание всё ещё не исполнено." }, { 5.19, "Повелитель Крастинова, Киртонос, всё ещё жив." }, { 8.49, "Впрочем, прежде чем бросить ему вызов, необходимо придумать, как его вызвать." }, { 14.35, "Говорят, что кровь невинных от Крастинова к Киртоносу переправляет Джандис Баров." }, { 20.35, "Найди её в затопленных коридорах Некроситета и убей." }, { 24.26, "Принеси все улики, которые только найдёшь." } } }, t = { d = 1.9, v = "human-female", n = { x = 11 }, c = { x = { { 0.00, "Мешок ужасов!" } } } } },
    [5517] = { d = 28.2, g = 1, v = "dwarf-female#33", n = { m = 313, f = 315 }, c = { m = { { 0.00, "Брат путник – нет числа твоим деяниям во славу Серебряного Рассвета." }, { 5.14, "В знак признательности я готова расстаться с одним из наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии." }, { 16.36, "Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!" }, { 22.10, "Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий." } }, f = { { 0.00, "Сестра путница – нет числа твоим деяниям во славу Серебряного Рассвета." }, { 5.36, "В знак признательности я готова расстаться с одним из наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии." }, { 16.47, "Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!" }, { 22.16, "Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий." } } }, t = { d = 15.0, v = "dwarf-female#33", n = { x = 166 }, c = { x = { { 0.00, "Впечатляет, – многоцветное оплечье Рассвета теперь твоё!" }, { 4.28, "Пока Серебряный Рассвет превозносит тебя, ты сможешь покупать новые многоцветные оплечья." }, { 11.18, "Любой интендант Рассвета продаст их тебе сразу же." } } } } },
    [5518] = { d = 37.4, v = "goblin-male", n = { x = 429 }, c = { x = { { 0.00, "Если вы собираетесь сразиться с королём этой помойки – а думаю, что без этого не обойтись, – тогда вам придётся миновать капитана Давигрома." }, { 9.74, "Конечно, можно его просто убить." }, { 12.13, "Но возможно, вам стоит оставить его в живых." }, { 15.28, "Вы спросите – каким образом?" }, { 17.30, "Я сижу здесь уже довольно долго, и успел придумать, как можно изготовить личину огра, которая продержится достаточно долго, чтобы обмануть этих остолопов." }, { 28.19, "Но, увы, больше чем на десять минут её не хватит." }, { 31.65, "Принесите мне всё, что нужно, и я вам её изготовлю." }, { 35.11, "Торопиться-то мне всё равно некуда..." } } }, t = { d = 33.3, g = 1, v = "goblin-male", n = { m = 339, f = 339 }, c = { m = { { 0.00, "Да, это подойдёт." }, { 1.63, "Вот тут подтянуть, тут подогнуть..." }, { 4.88, "Да-да, всё должно пройти как по маслу!" }, { 8.48, "*Прикованный гоблин расплывается в широкой улыбке.*" }, { 12.56, "Ну вот, всё готово!" }, { 13.90, "Только не забывайте – это не самое долговечное изделие." }, { 17.86, "У вас всего десять минут, после этого оно развалится, и все увидят, кто вы такой!" }, { 23.67, "Постарайтесь надеть его не раньше, чем приблизитесь к капитану, и помните: оно превратит в огра только вас, но не ваших спутников!" } }, f = { { 0.00, "Да, это подойдёт." }, { 1.64, "Вот тут подтянуть, тут подогнуть..." }, { 4.93, "Да-да, всё должно пройти как по маслу!" }, { 8.56, "*Прикованный гоблин расплывается в широкой улыбке.*" }, { 12.48, "Ну вот, всё готово!" }, { 13.86, "Только не забывайте – это не самое долговечное изделие." }, { 17.95, "У вас всего десять минут, после этого оно развалится, и все увидят, кто вы такая!" }, { 23.94, "Постарайтесь надеть его не раньше, чем приблизитесь к капитану, и помните: оно превратит в огра только вас, но не ваших спутников!" } } } } },
    [5519] = { t = { d = 13.5, v = "goblin-male", n = { x = 143 }, c = { x = { { 0.00, "Вот, пожалуйста: после того, как вы её наденете, у вас в запасе будет десять минут." }, { 6.19, "Удачи!" }, { 6.73, "Да, и если сумеете найти ключ, чтобы выпустить меня отсюда, непременно мне скажите, слышите?" } } } } },
    [5521] = { d = 27.0, g = 1, v = "gnome-male", n = { m = 310, f = 312 }, c = { m = { { 0.00, "Брат путник – твоих деяний во славу Серебряного Рассвета не счесть." }, { 4.58, "В знак признательности я готов продать тебе одно из наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии." }, { 14.80, "Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!" }, { 20.06, "Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий." } }, f = { { 0.00, "Сестра путница – твоих деяний во славу Серебряного Рассвета не счесть." }, { 5.02, "В знак признательности я готов продать тебе одно из наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии." }, { 15.64, "Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!" }, { 21.12, "Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий." } } }, t = { d = 14.7, v = "gnome-male", n = { x = 166 }, c = { x = { { 0.00, "Впечатляет, – многоцветное оплечье Рассвета теперь твоё!" }, { 4.21, "Пока Серебряный Рассвет превозносит тебя, ты сможешь покупать новые многоцветные оплечья." }, { 11.00, "Любой интендант Рассвета продаст их тебе сразу же." } } } } },
    [5522] = { d = 39.6, v = "goblin-female#63", n = { x = 418 }, c = { x = { { 0.00, "Я получила весть от своего господина Вектуса." }, { 3.40, "На самом деле... не напрямую от него, но от некого Леонида Бартоломея." }, { 8.70, "Я не знаю его, однако он видел моего господина – а никто не может видеть моего господина, если он сам этого не пожелает." }, { 17.87, "Леонид сказал мне, что Вектусу необходимы драконьи яйца." }, { 22.15, "Доставь их ему в Часовню Последней Надежды в Восточных Чумных землях." }, { 27.45, "Как обидно!" }, { 28.33, "Почему именно ты?" }, { 29.69, "Разве Вектус не доверяет мне?" }, { 31.93, "А, неважно..." }, { 32.95, "Просто доставь яйца куда следует и сообщи Леониду, что я сделала всё, как было приказано." } } }, t = { d = 42.2, g = 1, v = "scourge-male", n = { m = 363, f = 364 }, c = { m = { { 0.00, "Прекрасно, прекрасно." }, { 1.90, "Тебе ещё не известно, сколь великое зло кроется за теми, на кого ты работал, но я открою тебе глаза на правду." }, { 11.59, "Не бойся, я не служу им." }, { 13.73, "Имя мне Леонид Бартоломей; братья мои из Серебряного Рассвета зовут меня Чтимым." }, { 20.95, "Обманом я убедил Тинки отправить драконьи яйца мне." }, { 25.55, "Нам несказанно повезло, что она попалась в эту ловушку, потому что если бы драконьи яйца были доставлены по назначению, в руках врага оказалась бы огромная сила." } }, f = { { 0.00, "Прекрасно, прекрасно." }, { 1.96, "Тебе ещё не известно, сколь великое зло кроется за теми, на кого ты работала, но я открою тебе глаза на правду." }, { 12.02, "Не бойся, я не служу им." }, { 14.23, "Имя мне Леонид Бартоломей; братья мои из Серебряного Рассвета зовут меня Чтимым." }, { 21.66, "Обманом я убедил Тинки отправить драконьи яйца мне." }, { 26.41, "Нам несказанно повезло, что она попалась в эту ловушку, потому что если бы драконьи яйца были доставлены по назначению, в руках врага оказалась бы огромная сила." } } } } },
    [5524] = { d = 27.8, g = 1, v = "troll-female", n = { m = 311, f = 313 }, c = { m = { { 0.00, "Брат путник – твоих деяний во славу Серебряного Рассвета не счесть." }, { 4.83, "В знак признательности я готова продать тебе одно из наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии." }, { 15.65, "Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!" }, { 21.20, "Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий." } }, f = { { 0.00, "Сестра путница – твоих деяний во славу Серебряного Рассвета не счесть." }, { 5.17, "В знак признательности я готова продать тебе одно из наших знаменитых многоцветных оплечий Рассвета – тех самых, которые защищают от всех видов магии." }, { 16.18, "Многоцветные оплечья Рассвета предназначены лишь для наших величайших героев!" }, { 21.82, "Принеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий." } } }, t = { d = 15.2, v = "troll-female", n = { x = 166 }, c = { x = { { 0.00, "Впечатляет, – многоцветное оплечье Рассвета теперь твоё!" }, { 4.35, "Пока Серебряный Рассвет превозносит тебя, ты сможешь покупать новые многоцветные оплечья." }, { 11.35, "Любой интендант Рассвета продаст их тебе сразу же." } } } } },
    [5525] = { t = { d = 15.9, v = "goblin-male", n = { x = 155 }, c = { x = { { 0.00, "Вы для меня – номер один во всём мире!" }, { 3.11, "Все остальные – после вас!" }, { 5.21, "Ох, большое вам спасибо, что освободили меня!" }, { 8.83, "Я знал, я знал, что меня ждёт более достойная участь, чем пойти на обед какому-нибудь огру!" } } } } },
    [5526] = { d = 36.0, v = "nightelf-male#59", n = { x = 409 }, c = { x = { { 0.00, "Твои знания об Эльдре'Таласе – Забытом Городе – в Фераласе теперь очень пригодятся." }, { 6.03, "Именно в восточной части этого разрушенного города властвует нечестивый Алззин Перевертень." }, { 12.64, "Ступай же туда со всей поспешностью и посмотри в лицо ожидающей тебя опасности." }, { 18.34, "Плод Изобилия, ныне осквернённый и ставший Сквернитом, должен находиться неподалёку от Алззина." }, { 25.54, "Когда он упадёт, собери столько субстанции Сквернита, сколько сможешь." }, { 31.03, "Закрой его в реликварий и принеси мне." }, { 33.81, "Удачи тебе, и быстроты Кенария." } } }, t = { d = 23.7, g = 1, v = "nightelf-male#59", n = { m = 247, f = 247 }, c = { m = { { 0.00, "Дело сделано, отважный герой, и Круг Кенария в долгу перед тобой." }, { 4.98, "Хотя война ещё далеко не окончена, мы выиграли великую битву с теми, кто хотел обрушить на нас молот рока." }, { 12.99, "Прошу – прими это в знак нашей безмерной благодарности." }, { 17.17, "Знай, что для Круга Кенария ты навсегда останешься героем." }, { 21.48, "Прими нашу благодарность." } }, f = { { 0.00, "Дело сделано, отважная героиня, и Круг Кенария в долгу перед тобой." }, { 5.17, "Хотя война ещё далеко не окончена, мы выиграли великую битву с теми, кто хотел обрушить на нас молот рока." }, { 13.28, "Прошу – прими это в знак нашей безмерной благодарности." }, { 17.50, "Знай, что для Круга Кенария ты навсегда останешься героем." }, { 21.85, "Прими нашу благодарность." } } } } },
    [5527] = { d = 32.5, v = "nightelf-male#59", n = { x = 385 }, c = { x = { { 0.00, "Первый шаг – найти вместилище, способное удержать чрезвычайно осквернённую субстанцию и оградить обладателя от её влияния." }, { 8.46, "Единственное известное мне приспособление, в котором возможно держать такую дрянь, как Сквернит, – это реликварий Чистоты." }, { 16.98, "В сердце пустошей Силитуса находятся руины поселения Ночных эльфов, деревня Южного Ветра." }, { 23.40, "Я знаю, что реликварий хранился там много лет назад." }, { 27.09, "Если хочешь помочь нам достичь успеха, обыщи эти руины в надежде найти его." } } }, t = { d = 19.5, g = 1, v = "nightelf-male#59", n = { m = 229, f = 230 }, c = { m = { { 0.00, "Воистину, ты и правда находчив, как говорят." }, { 3.04, "Кругу Кенария повезло, что ты на нашей стороне." }, { 6.33, "Теперь, когда реликварий снова у нас в руках, на сердце у меня стало легче." }, { 11.60, "Теперь мне значительно проще просить тебя не только повергнуть нечестивого демона, но и принести одну опасную вещь..." } }, f = { { 0.00, "Воистину, ты и правда находчива, как говорят." }, { 3.09, "Кругу Кенария повезло, что ты на нашей стороне." }, { 6.37, "Теперь, когда реликварий снова у нас в руках, на сердце у меня стало легче." }, { 11.62, "Теперь мне значительно проще просить тебя не только повергнуть нечестивого демона, но и принести одну опасную вещь..." } } } } },
    [5528] = { t = { d = 14.7, v = "creature/ogre", n = { x = 143 }, c = { x = { { 0.00, "Ты теперь большой босс, так что получай бесплатно моё лучшее пойло!" }, { 5.56, "От этой выпивки ты станешь сильнее И хорошо захмелеешь!" }, { 10.22, "Это хорошее пойло, вождь... сам попробуй и скажи Кригу!" } } } } },
    [5529] = { d = 29.6, v = "gnome-female", n = { x = 349 }, c = { x = { { 0.00, "До Серебряного Рассвета дошли слухи о том, что Плеть создаёт собственную армию драконов!" }, { 6.30, "Мы должны этому помешать – с помощью драконов Плеть сможет беспрепятственно перемещаться по всему Азероту!" }, { 13.99, "Их некроманты выращивают проклятых драконов в Некроситете, посреди озера Дарроумир." }, { 20.03, "Отправляйся в Некроситет и убей как можно больше драконьих детёнышей, пока они не успели вырасти и превратиться в неуязвимых монстров!" } } }, t = { d = 8.3, v = "gnome-female", n = { x = 75 }, c = { x = { { 0.00, "Отлично!" }, { 0.76, "Они нескоро смогут вырастить новый выводок." }, { 4.58, "...По крайней мере, я на это очень надеюсь..." } } } } },
    [5531] = { d = 37.6, g = 1, v = "scourge-male", n = { m = 340, f = 342 }, c = { m = { { 0.00, "Яйца, которые ты принёс мне, должны были быть использованы Плетью для создания чудовищных проклятых драконов." }, { 9.94, "Охлаждённые яйца чёрных драконов были бы бесценны для их опытов – это несомненно позволило бы Плети достичь своей подлой цели гораздо быстрее." }, { 23.02, "Отнеси яйца Бетине Биггльцинк – она сведуща в науках и алхимии." }, { 28.98, "Она обеспечила нас оружием против Плети." }, { 32.79, "С твоей помощью мы нанесём этим тварям решающий удар." } }, f = { { 0.00, "Яйца, которые ты принесла мне, должны были быть использованы Плетью для создания чудовищных проклятых драконов." }, { 9.60, "Охлаждённые яйца чёрных драконов были бы бесценны для их опытов – это несомненно позволило бы Плети достичь своей подлой цели гораздо быстрее." }, { 21.94, "Отнеси яйца Бетине Биггльцинк – она сведуща в науках и алхимии." }, { 27.56, "Она обеспечила нас оружием против Плети." }, { 31.15, "С твоей помощью мы нанесём этим тварям решающий удар." } } }, t = { d = 36.2, g = 1, v = "gnome-female", n = { m = 400, f = 402 }, c = { m = { { 0.00, "Прекрасно, правильная упаковка – залог сохранности яиц при транспортировке." }, { 5.65, "Да они отборные!" }, { 6.94, "Отложим их в надёжное место для дальнейшего исследования, но прямо сейчас нам нужна та штука, в которой ты их принёс." }, { 15.58, "Я разработала прибор, предназначенный для уничтожения нежити в Некроситете." }, { 21.15, "Тамошние учёные сейчас работают над выведением нового вида драконов – нежити." }, { 27.00, "Мы должны помешать им!" }, { 28.70, "Прибор я назвала \"Рассветным гамбитом\", потому что... я не уверена, что он работает!" }, { 34.96, "Сможешь проверить?" } }, f = { { 0.00, "Прекрасно, правильная упаковка – залог сохранности яиц при транспортировке." }, { 5.50, "Да они отборные!" }, { 6.76, "Отложим их в надёжное место для дальнейшего исследования, но прямо сейчас нам нужна та штука, в которой ты их принесла." }, { 15.38, "Я разработала прибор, предназначенный для уничтожения нежити в Некроситете." }, { 20.82, "Тамошние учёные сейчас работают над выведением нового вида драконов – нежити." }, { 26.52, "Мы должны помешать им!" }, { 28.18, "Прибор я назвала \"Рассветным гамбитом\", потому что... я не уверена, что он работает!" }, { 34.27, "Сможешь проверить?" } } } } },
    [5533] = { d = 35.0, g = 1, v = "human-male#50", n = { m = 411, f = 412 }, c = { m = { { 0.00, "На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью плети." }, { 7.28, "В её стенах наши враги творят немыслимые злодеяния над ничего не подозревающими жертвами... по крайней мере, так мы полагаем." }, { 16.17, "Путь преграждают двери, и без подходящего ключа внутрь не войти." }, { 20.68, "Алхимик Арбингтон многое знает о Некроситете и придумал, как достать ключ." }, { 25.96, "Ты зарекомендовал себя как человек с большими способностями, поэтому я доверяю тебе это задание." }, { 32.85, "Обсуди подробности с алхимиком." } }, f = { { 0.00, "На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью плети." }, { 7.20, "В её стенах наши враги творят немыслимые злодеяния над ничего не подозревающими жертвами... по крайней мере, так мы полагаем." }, { 15.99, "Путь преграждают двери, и без подходящего ключа внутрь не войти." }, { 20.45, "Алхимик Арбингтон многое знает о Некроситете и придумал, как достать ключ." }, { 25.67, "Ты зарекомендовала себя как человек с большими способностями, поэтому я доверяю тебе это задание." }, { 32.55, "Обсуди подробности с алхимиком." } } }, t = { d = 19.4, g = 1, v = "human-male", n = { x = 212 }, c = { m = { { 0.00, "Рад встрече, герой." }, { 1.43, "В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ... который отомкнет входную дверь." }, { 12.03, "Представляю, какие кошмары таятся за ней." }, { 15.02, "Не понимаю, как герои вроде тебя решаются на такие подвиги..." } }, f = { { 0.00, "Рад встрече, героиня." }, { 1.56, "В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ... который отомкнет входную дверь." }, { 12.13, "Представляю, какие кошмары таятся за ней." }, { 15.11, "Не понимаю, как герои вроде тебя решаются на такие подвиги..." } } } } },
    [5534] = { d = 24.2, g = 1, v = "goblin-male#65", n = { m = 222, f = 224 }, c = { m = { { 0.00, "Что?!" }, { 0.45, "Ты в уме?!" }, { 1.35, "Чем ты ещё недоволен?!" }, { 3.15, "Ты хоть представляешь, сколько стоят эти гранаты?" }, { 7.28, "За них дают... ладно, не важно..." }, { 10.05, "Хочешь денег?" }, { 11.25, "Хорошо." }, { 11.93, "Прежде докажи мне, что ты ценный работник." }, { 15.45, "Отправляйся в руины Эльдарата и принеси мне некую руну, которую искали эльфы крови." }, { 22.50, "Полагаю, она у наг." } }, f = { { 0.00, "Что?!" }, { 0.45, "Ты в уме?!" }, { 1.36, "Чем ты ещё недовольна?!" }, { 3.24, "Ты хоть представляешь, сколько стоят эти гранаты?" }, { 7.38, "За них дают... ладно, не важно..." }, { 10.16, "Хочешь денег?" }, { 11.37, "Хорошо." }, { 12.05, "Прежде докажи мне, что ты ценная работница." }, { 15.66, "Отправляйся в руины Эльдарата и принеси мне некую руну, которую искали эльфы крови." }, { 22.74, "Полагаю, она у наг." } } }, t = { d = 31.8, v = "goblin-male#65", n = { x = 301 }, c = { x = { { 0.00, "Ха!" }, { 0.30, "Отлично!" }, { 1.03, "Уж я выясню, что это за штука, зачем она нужна и зачем волхв Римтори – та кобыла, которая меня в это втянула – так хотела её заполучить." }, { 12.27, "Ха!" }, { 12.56, "Вонючие эльфы крови!" }, { 14.33, "Уж Ким'джаель покажет вам, где раки зимуют!" }, { 17.88, "Он покажет вам, кто тут букашка!" }, { 20.47, "Ну, ты молодчина!" }, { 21.87, "Спасибо тебе..." }, { 23.20, "Чего говоришь, не булькает?" }, { 25.49, "Ну, держи свои презренные монеты и проваливай, мне и без тебя есть чем заняться." } } } } },
    [5535] = { d = 35.9, v = "tauren-male#68", n = { x = 367 }, c = { x = { { 0.00, "Давным-давно, высокорождённые были самыми могущественными адептами тайной магии, когда-либо существовавшими среди ночных эльфов." }, { 10.34, "Порча, которая охватывает каждого, кто имеет дело с тайной магией, принесла много зла народу ночных эльфов и всему Азероту." }, { 20.53, "Я обещал Часовым, что буду освобождать встреченных мной духов от их смертных связей." }, { 27.35, "Если поможешь мне в этом, я награжу тебя." }, { 30.79, "Духи скитаются в святилище Песни Теней к северо-востоку отсюда." } } }, t = { d = 19.3, g = 1, v = "tauren-male#68", n = { x = 163 }, c = { m = { { 0.00, "Отличная работа, герой." }, { 2.16, "Благодарю тебя." }, { 3.60, "Теперь духи обрели покой, а опасность, которую могла навлечь их жажда магии, миновала." }, { 11.44, "Думаю, обе стороны конфликта, раздирающего ныне Азерот, поймут, что ты выше этого." } }, f = { { 0.00, "Отличная работа, героиня." }, { 2.37, "Благодарю тебя." }, { 3.84, "Теперь духи обрели покой, а опасность, которую могла навлечь их жажда магии, миновала." }, { 11.84, "Думаю, обе стороны конфликта, раздирающего ныне Азерот, поймут, что ты выше этого." } } } } },
    [5536] = { d = 37.0, v = "tauren-male#68", n = { x = 359 }, c = { x = { { 0.00, "Сатиры, искажённые и зловредные порождения ночных эльфов, ныне оскверняют священные земли, по которым некогда ступал Кенарий." }, { 10.77, "Конечно, не в моих силах помочь эльфам справиться со всеми этими отвратительными созданиями, однако я поклялся Матери-Земле помочь эльфам избавиться от сатиров хотя бы здесь." }, { 25.81, "Надеюсь, ты поможешь мне в этом деле." }, { 29.06, "К северо-востоку отсюда ты найдёшь клан Халдарр." }, { 33.17, "Возвращайся ко мне, когда испытаешь свою силу." } } }, t = { d = 31.4, g = 1, v = "tauren-male#68", n = { m = 276, f = 277 }, c = { m = { { 0.00, "Отличная работа, герой." }, { 2.14, "Вижу, ты не только силён, но и хитёр." }, { 5.31, "Битва с сатирами была испытанием твоей преданности Матери-Земле, даже если ты поклоняешься другим богам." }, { 14.65, "Она пронизывает всё сущее в нашем мире и за его пределами." }, { 19.87, "Два ока её, тёмное и светлое, всегда взирают на нас с небес." }, { 25.10, "Прошу тебя, прими эту скромную плату в знак моей признательности." } }, f = { { 0.00, "Отличная работа, героиня." }, { 2.31, "Вижу, ты не только сильна, но и хитра." }, { 5.73, "Битва с сатирами была испытанием твоей преданности Матери-Земле, даже если ты поклоняешься другим богам." }, { 15.12, "Она пронизывает всё сущее в нашем мире и за его пределами." }, { 20.38, "Два ока её, тёмное и светлое, всегда взирают на нас с небес." }, { 25.63, "Прошу тебя, прими эту скромную плату в знак моей признательности." } } } } },
    [5537] = { d = 29.8, v = "human-male", n = { x = 356 }, c = { x = { { 0.00, "Чтобы отомкнуть двери Некроситета необходим Костяной ключ." }, { 4.09, "Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме." }, { 12.38, "Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой." }, { 20.24, "Но не будем отвлекаться, для начала нам понадобятся фрагменты скелетов." }, { 25.14, "Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи." } } }, t = { d = 27.0, v = "human-male", n = { x = 310 }, c = { x = { { 0.00, "Отличные образцы!" }, { 1.27, "Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придётся рано или поздно пройти." }, { 11.37, "Теперь придётся отыскать подходящую форму для отливки." }, { 15.18, "Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей." }, { 22.29, "Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает." } } } } },
    [5538] = { d = 26.2, v = "human-male", n = { x = 277 }, c = { x = { { 0.00, "Тебе нужно поговорить с гоблином по имени Кринкель Сталлинн." }, { 4.62, "Он работает в Прибамбасске, в пустыне Танарис." }, { 8.09, "Ему под силу сделать такую форму, но это обойдётся недёшево." }, { 12.65, "Мы просим тебя не скупиться и заплатить ему." }, { 16.05, "Я алхимик, а не банкир." }, { 17.82, "Будь у меня золото, я бы здесь не сидел." }, { 20.81, "Ну вот, опять я брякнул что-то не то." }, { 23.60, "Ладно." }, { 24.14, "Тебя ждёт Прибамбасск!" }, { 25.84, "Удачи!" } } }, t = { d = 18.8, v = "goblin-male#110", n = { x = 214 }, c = { x = { { 0.00, "Арбингтон сказал, что ты принесёшь всё необходимое, и так оно и оказалось!" }, { 5.24, "Сделка есть сделка." }, { 6.69, "Дай-ка я сложу фрагменты скелетов в форму." }, { 9.83, "Арбингтон их заранее закалил?" }, { 12.00, "Великолепно..." }, { 13.05, "В противном случае тебе пришлось бы тащиться обратно в лагерь Промозглого Ветра." } } } } },
    [5541] = { d = 32.7, g = 1, v = "dwarf-male#100", n = { m = 378, f = 380 }, c = { m = { { 0.00, "Хегнар Громострел продаёт ружья у дороги в Старую Наковальню." }, { 4.21, "Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны." }, { 10.95, "Но..." }, { 11.32, "Последний ящик с боеприпасами, что я ему послал, пропал по дороге." }, { 15.90, "Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго... и этот дурак бросил боеприпасы для Громострела!" }, { 25.49, "не мог бы ты найти их и вернуть Громострелу?" }, { 28.47, "Он их ждёт, и наверняка у него боеприпасы уже на исходе." } }, f = { { 0.00, "Хегнар Громострел продаёт ружья у дороги в Старую Наковальню." }, { 4.26, "Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны." }, { 11.08, "Но..." }, { 11.45, "Последний ящик с боеприпасами, что я ему послал, пропал по дороге." }, { 16.09, "Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго... и этот дурак бросил боеприпасы для Громострела!" }, { 25.79, "не могла бы ты найти их и вернуть Громострелу?" }, { 28.98, "Он их ждёт, и наверняка у него боеприпасы уже на исходе." } } }, t = { d = 15.0, v = "dwarf-male#99", n = { x = 161 }, c = { x = { { 0.00, "Вот радость-то, ещё боеприпасы!" }, { 2.35, "Поставка старины Лослора, наконец, прибыла!" }, { 5.73, "Пусть и поздновато, но, как говаривал мой дедуля, лучше поздно, чем никогда!" }, { 11.45, "Большое тебе спасибо." }, { 13.18, "Покупатели тут заждались!" } } } } },
    [5542] = { d = 19.3, v = "human-male", n = { x = 227 }, c = { x = { { 0.00, "Если ты собираешься здесь оставаться, придётся тебе поработать в уплату за проживание." }, { 6.07, "У нас есть ряд докучающих обстоятельств, с которыми неплохо бы разобраться." }, { 11.29, "Начни с чумных псов и их отродий." }, { 13.68, "Я не многим смогу тебе отплатить, но горячую пищу и приятную беседу гарантирую." } } }, t = { d = 6.1, v = "human-male", n = { x = 55 }, c = { x = { { 0.00, "Молодец." }, { 0.81, "Давай, отдохни." }, { 2.27, "Поедим же и побеседуем о давно ушедших днях!" } } } } },
    [5543] = { d = 25.7, v = "human-male", n = { x = 293 }, c = { x = { { 0.00, "Горе тем, кто в глупости своей бродит по Чумным землям." }, { 3.97, "В здешних лесах таится много опасностей – от Алого ордена, который убивает всех, кроме своих сторонников, до Плети, которая всегда рада пополнить свои ряды новой нежитью." }, { 16.28, "Даже звери и птицы превратились в отвратительных хищных чудовищ." }, { 20.89, "Я прошу тебя уничтожить тех, что нападают с небес – чумных нетопырей." } } }, t = { d = 10.1, g = 1, v = "human-male", n = { x = 104 }, c = { m = { { 0.00, "Ты бесподобный образец порядочности, герой!" }, { 3.39, "Давненько я не чувствовал крови героев в своих венах." }, { 7.62, "Подобная отвага внушает надежду!" } }, f = { { 0.00, "Ты бесподобный образец порядочности, героиня!" }, { 3.42, "Давненько я не чувствовал крови героев в своих венах." }, { 7.53, "Подобная отвага внушает надежду!" } } } } },
    [5544] = { d = 21.1, g = 1, v = "human-male", n = { x = 230 }, c = { m = { { 0.00, "Путник, у меня еда на исходе." }, { 2.19, "Мне стыдно признаться, но угостить тебя нечем." }, { 5.55, "Не поможешь старику?" }, { 7.03, "Единственные твари в этих краях, которых не поразила чума, это личинки-трупоеды." }, { 12.91, "Они довольно гадкие, зато их мясо хранится много месяцев." }, { 17.17, "Мне необходимо запасти несколько сотен фунтов на зиму!" } }, f = { { 0.00, "Путница, у меня еда на исходе." }, { 2.27, "Мне стыдно признаться, но угостить тебя нечем." }, { 5.64, "Не поможешь старику?" }, { 7.13, "Единственные твари в этих краях, которых не поразила чума, это личинки-трупоеды." }, { 13.03, "Они довольно гадкие, зато их мясо хранится много месяцев." }, { 17.31, "Мне необходимо запасти несколько сотен фунтов на зиму!" } } }, t = { d = 2.8, g = 1, v = "human-male", n = { m = 26, f = 28 }, c = { m = { { 0.00, "Да благословит тебя Свет, юноша." } }, f = { { 0.00, "Да благословит тебя Свет, девушка." } } } } },
    [5545] = { d = 27.3, v = "human-female#45", n = { x = 318 }, c = { x = { { 0.00, "У меня большие неприятности." }, { 2.00, "Приближается срок поставки древесины, а я не успеваю её отправить." }, { 6.51, "Самое обидное, что она уже заготовлена – но волки и медведи, расплодившиеся к северу отсюда, не дают моим работникам её забрать." }, { 15.45, "Я уже договорилась с заместителем судьи Рейнером насчёт зверья, но мне нужен кто-нибудь, кто доставит сюда эти дрова." }, { 23.17, "Если ты принесёшь мне восемь вязанок, я всё успею." } } }, t = { d = 12.6, v = "human-female#45", n = { x = 141 }, c = { x = { { 0.00, "Великолепно!" }, { 0.93, "Благодаря тебе я сумела выполнить заказ вовремя." }, { 4.57, "Всякий труд должен быть оплачен, так что прошу тебя принять эту плату за беспокойство." }, { 10.92, "Спасибо – и до свидания!" } } } } },
    [5561] = { d = 39.2, v = "goblin-male", n = { x = 458 }, c = { x = { { 0.00, "Биббли думает, что он – единственный гоблин в Пустошах, умеющий делать деньги." }, { 5.52, "Ха!" }, { 5.77, "Единственный караван, который осмеливается странствовать по этим землям, полностью зависит от меня." }, { 12.75, "С тех самых пор, как я научился омолаживать кодо и управлять старыми и умирающими зверями при помощи моего энергетического инкапсулятора, мы трое – я, караванщик Корк и Риггер – создали что-то вроде компании." }, { 27.22, "Вот, держи инкапсулятор: он действует на древних, старых и умирающих кодо, превращая их в ручных и заставляя следовать за тобой." }, { 36.17, "Как сумеешь приручить кодо, веди его ко мне." } } }, t = { d = 23.3, v = "goblin-male", n = { x = 202 }, c = { x = { { 0.00, "*Смид Заржавень начинает считать.*" }, { 3.12, "Три..." }, { 3.68, "Четыре..." }, { 4.56, "Ага, пять." }, { 5.52, "Прекрасно!" }, { 6.48, "Я просил пять приручённых кодо – и получил ровно пять приручённых кодо!" }, { 12.64, "Я буду богат..." }, { 14.08, "Да, очень, очень богат!" }, { 16.24, "Хотелось бы мне видеть, какую кислую рожу скорчит Биббли, когда узнает об этом!" } } } } },
    [5581] = { d = 32.1, v = "tauren-male#68", n = { x = 303 }, c = { x = { { 0.00, "Воззри: вот Рука Ируксоса." }, { 2.29, "Поистине, ужасающее зрелище." }, { 4.72, "Если ты намереваешься закрыть порталы демонов на Поле Маннорок, – а именно об этом я и хочу тебя попросить, – то она должна быть у тебя." }, { 16.31, "Угроза со стороны демонов растёт: мы должны закрыть их порталы, дабы демоническим существам более не было доступа в этот мир." }, { 26.90, "Удачи тебе в этом нелёгком деле... и берегись стражей портала." } } }, t = { d = 9.8, g = 1, v = "tauren-male#68", n = { m = 88, f = 89 }, c = { m = { { 0.00, "Ты воистину достоин величайших почестей." }, { 3.85, "Твоими трудами жизнь на всём Азероте станет гораздо спокойнее." } }, f = { { 0.00, "Ты воистину достойна величайших почестей." }, { 3.97, "Твоими трудами жизнь на всём Азероте станет гораздо спокойнее." } } } } },
    [5582] = { d = 18.8, v = "narrator", n = { x = 211 }, c = { x = { { 0.00, "Эта чешуйка была взята у поражённого проклятой чумой драконьего детёныша." }, { 5.58, "Однако в отличие от других чешуек, изъязвлённых и покрытых слизью, эта выглядит совершенно здоровой." }, { 13.23, "Любопытное явление." }, { 14.75, "Бетина Биггльцинк непременно захочет на это взглянуть." } } }, t = { d = 15.0, v = "gnome-female", n = { x = 145 }, c = { x = { { 0.00, "Очень интересно..." }, { 1.61, "Возможно, с помощью этой чешуи мне удастся проникнуть в суть козней Плети." }, { 7.98, "Благодарю тебя." }, { 9.36, "Впредь, если обнаружишь подобные чешуйки, непременно приноси их мне!" } } } } },
    [5601] = { d = 35.2, g = 1, v = "human-female#47", n = { m = 426, f = 428 }, c = { m = { { 0.00, "Во время войны я бежала в Лордерон – мне посчастливилось спастись до того, как полчища Плети прошли по моим родным местам и превратили их в зачумлённые руины." }, { 10.50, "Мне повезло, но судьба была не столь благосклонна к моей семье." }, { 14.72, "Боюсь, все они погибли во время битвы при Дарроушире." }, { 18.35, "Деревня Дарроушир была частью Восточных Королевств, теперь это ещё одни развалины в южных пределах Восточных Чумных земель." }, { 26.73, "Не мог бы ты узнать, что сталось с моей семьёй?" }, { 29.81, "Я так волнуюсь за них, особенно за мою сестрёнку Памелу." }, { 33.49, "Пожалуйста, отыщи её!" } }, f = { { 0.00, "Во время войны я бежала в Лордерон – мне посчастливилось спастись до того, как полчища Плети прошли по моим родным местам и превратили их в зачумлённые руины." }, { 10.57, "Мне повезло, но судьба была не столь благосклонна к моей семье." }, { 14.82, "Боюсь, все они погибли во время битвы при Дарроушире." }, { 18.46, "Деревня Дарроушир была частью Восточных Королевств, теперь это ещё одни развалины в южных пределах Восточных Чумных земель." }, { 26.90, "Не могла бы ты узнать, что сталось с моей семьёй?" }, { 30.18, "Я так волнуюсь за них, особенно за мою сестрёнку Памелу." }, { 33.88, "Пожалуйста, отыщи её!" } } }, t = { d = 35.0, v = "child-female", n = { x = 359 }, c = { x = { { 0.00, "Где моя сестра Джессика?" }, { 1.91, "Она покинула меня так давно, когда я была ещё совсем маленькой девочкой." }, { 7.50, "Она так плакала, когда уходила..." }, { 10.09, "Не знаю, почему, может, разбила коленку?" }, { 13.23, "Раньше мы с Джессикой вместе играли, и танцевали, и собирали цветы..." }, { 18.47, "А иногда мы прятались за дверью и ждали, когда отец придёт домой, чтобы выскочить и напугать его." }, { 25.91, "Я хочу, чтобы она вернулась!" }, { 28.15, "Может, если вернётся она, то вернётся и папа, и остальные, и мы снова будем вместе играть..." } } } } },
    [5621] = { d = 29.1, g = 1, v = "nightelf-female#51", n = { m = 321, f = 323 }, c = { m = { { 0.00, "Мне нужна твоя помощь." }, { 1.64, "Я должна оставаться здесь, чтобы обучать других, но ты мог бы помочь одной из наших раненых часовых к югу от Доланаара." }, { 9.98, "Её ранили, когда она патрулировала город, и ей нужна наша помощь." }, { 14.65, "Её зовут Шайя." }, { 15.72, "Когда найдёшь её, исцели её раны и укрепи её тело заклятиями." }, { 20.02, "По крайней мере, это защитит её от бед на некоторое время." }, { 24.12, "Когда выполнишь свой долг перед Элуной, возвращайся ко мне." } }, f = { { 0.00, "Мне нужна твоя помощь." }, { 1.69, "Я должна оставаться здесь, чтобы обучать других, но ты могла бы помочь одной из наших раненых часовых к югу от Доланаара." }, { 10.47, "Её ранили, когда она патрулировала город, и ей нужна наша помощь." }, { 15.28, "Её зовут Шайя." }, { 16.39, "Когда найдёшь её, исцели её раны и укрепи её тело заклятиями." }, { 20.81, "По крайней мере, это защитит её от бед на некоторое время." }, { 25.04, "Когда выполнишь свой долг перед Элуной, возвращайся ко мне." } } }, t = { d = 23.4, g = 1, v = "nightelf-female#51", n = { m = 242, f = 244 }, c = { m = { { 0.00, "Ты хорошо послужил Элуне." }, { 1.96, "Я благодарю тебя за это." }, { 3.85, "Пожалуйста, прими это одеяние, как символ моей благодарности." }, { 8.52, "Оно символизирует то, что ты заслужил своё место в наших кругах." }, { 13.31, "Если желаешь, носи его с гордостью, но мы признаём тебя своим в любом обличии." }, { 19.26, "Спасибо, и да благословит тебя великая Элуна." } }, f = { { 0.00, "Ты хорошо послужила Элуне." }, { 2.09, "Я благодарю тебя за это." }, { 4.03, "Пожалуйста, прими это одеяние, как символ моей благодарности." }, { 8.83, "Оно символизирует то, что ты заслужила своё место в наших кругах." }, { 13.84, "Если желаешь, носи его с гордостью, но мы признаём тебя своей в любом обличии." }, { 19.96, "Спасибо, и да благословит тебя великая Элуна." } } } } },
    [5622] = { d = 21.8, g = 1, v = "nightelf-female#51", n = { m = 245, f = 245 }, c = { m = { { 0.00, "Тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине." }, { 6.58, "Там ты разыщешь Лорну Утренний Свет." }, { 9.19, "Она расскажет тебе больше о пути Элуны, и с её помощью ты получишь своё первое облачение, говорящее о твоём статусе жреца Элуны." }, { 18.52, "Будь осторожен, и да хранит тебя в пути Элуна!" } }, f = { { 0.00, "Тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине." }, { 6.61, "Там ты разыщешь Лорну Утренний Свет." }, { 9.23, "Она расскажет тебе больше о пути Элуны, и с её помощью ты получишь своё первое облачение, говорящее о твоём статусе жрицы Элуны." }, { 18.58, "Будь осторожна, и да хранит тебя в пути Элуна!" } } }, t = { d = 9.7, v = "nightelf-female#51", n = { x = 106 }, c = { x = { { 0.00, "Я рада знать, что Шанда послала тебя найти меня." }, { 3.73, "Обучение молодых жрецов, следующих пути Луны, приносит мне большое удовольствие." } } } } },
    [5623] = { d = 21.4, g = 1, v = "human-female#45", n = { m = 237, f = 238 }, c = { m = { { 0.00, "Приветствую тебя, юный жрец." }, { 2.09, "Пришло время узнать больше о нашей вере." }, { 5.16, "После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту." }, { 11.44, "Знания её велики; к тому же она уже слышала о тебе и о твоём стремлении к Истинному Свету." }, { 18.04, "Она готова поделиться с тобой своей мудростью." } }, f = { { 0.00, "Приветствую тебя, юная жрица." }, { 2.18, "Пришло время узнать больше о нашей вере." }, { 5.18, "После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту." }, { 11.33, "Знания её велики; к тому же она уже слышала о тебе и о твоём стремлении к Истинному Свету." }, { 17.79, "Она готова поделиться с тобой своей мудростью." } } }, t = { d = 5.9, v = "human-female#45", n = { x = 62 }, c = { x = { { 0.00, "Я рада видеть тебя здесь." }, { 1.98, "Нам нужно поговорить о твоём будущем и о пути Света..." } } } } },
    [5624] = { d = 33.4, v = "human-female#45", n = { x = 371 }, c = { x = { { 0.00, "Обычно я подвергаю всех последователей Света небольшому испытанию." }, { 4.89, "Так я выясняю, достойны ли они своего первого облачения – символа того, что церковь их принимает и поддерживает." }, { 13.20, "Но сейчас ситуация немного отличается." }, { 16.08, "Один из жителей Златоземья видел раненого стража на берегу озера к востоку отсюда." }, { 22.32, "Этого стража зовут Робертс." }, { 24.46, "Найди его, исцели его раны, придай ему стойкости и вернись сюда." }, { 29.49, "Если ты справишься, я сочту твоё испытание завершённым." } } }, t = { d = 25.4, v = "human-female#45", n = { x = 302 }, c = { x = { { 0.00, "Прекрасно." }, { 0.75, "Теперь город охраняет ещё один страж." }, { 3.36, "Приятно видеть, что ты учишься пользоваться своими способностями." }, { 7.84, "Если захочешь узнать что-нибудь новое, возвращайся ко мне." }, { 11.89, "А пока что прими это облачение." }, { 14.13, "Если наденешь его, все будут знать, что ты принадлежишь к нашему ордену." }, { 19.11, "Впрочем, можешь и не надевать, если не хочешь: для выполнения следующих заданий оно не нужно." } } } } },
    [5625] = { d = 31.6, g = 1, v = "dwarf-male", n = { m = 355, f = 355 }, c = { m = { { 0.00, "Как правило, примерно в эту пору послушники вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе." }, { 11.30, "Но, честно говоря, сейчас у меня есть и более важные дела." }, { 15.58, "Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф." }, { 24.34, "Излечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты прошёл испытание." }, { 30.90, "Справишься?" } }, f = { { 0.00, "Как правило, примерно в эту пору послушницы вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе." }, { 11.13, "Но, честно говоря, сейчас у меня есть и более важные дела." }, { 15.35, "Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф." }, { 23.99, "Излечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты прошла испытание." }, { 30.51, "Справишься?" } } }, t = { d = 29.8, g = 1, v = "dwarf-male", n = { m = 321, f = 322 }, c = { m = { { 0.00, "Прекрасно." }, { 0.80, "В тебе есть Свет, и в этом нет сомнений." }, { 3.76, "Вот, прими это одеяние." }, { 5.57, "Оно будет показывать всем, что ты жрец, – носи его, если желаешь." }, { 10.46, "В будущем тебе придётся пройти через другие испытания." }, { 14.55, "Старайся узнать побольше о своих способностях и возможностях." }, { 19.11, "Испытай свою силу в одном-двух одиночных боях, а потом и в группе с другими путниками." }, { 25.62, "Не страшись никого: твоей силе может позавидовать любой." } }, f = { { 0.00, "Прекрасно." }, { 0.79, "В тебе есть Свет, и в этом нет сомнений." }, { 3.67, "Вот, прими это одеяние." }, { 5.44, "Оно будет показывать всем, что ты жрица, – носи его, если желаешь." }, { 10.35, "В будущем тебе придётся пройти через другие испытания." }, { 14.35, "Старайся узнать побольше о своих способностях и возможностях." }, { 18.80, "Испытай свою силу в одном-двух одиночных боях, а потом и в группе с другими путниками." }, { 25.15, "Не страшись никого: твоей силе может позавидовать любой." } } } } },
    [5626] = { d = 25.9, g = 1, v = "dwarf-male", n = { m = 289, f = 289 }, c = { m = { { 0.00, "Эй!" }, { 0.25, "Путник!" }, { 0.81, "У тебя есть свободная минутка?!" }, { 2.99, "Ты давно уже следуешь пути Света, так ведь?" }, { 6.05, "Как насчёт того, чтобы сходить к Максану Анволу в Каранос?" }, { 10.10, "Он расскажет тебе побольше о твоей судьбе, а если ты окажешься достойным, он тебе даст твои первые одеяния жреца." }, { 18.03, "Теперь ступай!" }, { 19.09, "Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать." } }, f = { { 0.00, "Эй!" }, { 0.25, "Путница!" }, { 0.88, "У тебя есть свободная минутка?!" }, { 3.08, "Ты давно уже следуешь пути Света, так ведь?" }, { 6.15, "Как насчёт того, чтобы сходить к Максану Анволу в Каранос?" }, { 10.24, "Он расскажет тебе побольше о твоей судьбе, а если ты окажешься достойной, он тебе даст твои первые одеяния жрицы." }, { 18.21, "Теперь ступай!" }, { 19.28, "Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать." } } }, t = { d = 13.1, v = "dwarf-male", n = { x = 124 }, c = { x = { { 0.00, "О, так тебя послал Брансток?" }, { 2.40, "Славно, славно!" }, { 3.75, "Он прав, уже пора бы сделать шажок побольше в сторону Света." }, { 8.85, "Это закалит твой характер и укрепит твоё тело… и дух." } } } } },
    [5627] = { t = { d = 10.5, g = 1, v = "nightelf-female#51", n = { m = 107, f = 110 }, c = { m = { { 0.00, "Ты доказал, что достоин внимания Элуны." }, { 3.04, "Если ты готов, я с радостью научу тебя одному из её заклинаний, доступных лишь нашему народу." } }, f = { { 0.00, "Ты доказала, что достойна внимания Элуны." }, { 3.24, "Если ты готова, я с радостью научу тебя одному из её заклинаний, доступных лишь нашему народу." } } } } },
    [5628] = { d = 28.9, g = 1, v = "human-female#45", n = { m = 328, f = 329 }, c = { m = { { 0.00, "Ах да, здравствуй!" }, { 1.25, "Рада, что ты уделил мне минутку внимания." }, { 4.14, "Забраться так далеко от дома, да в такие юные годы, – мне по душе твоё рвение!" }, { 9.59, "Если бы мне в молодые годы хватило духу постранствовать по миру..." }, { 14.23, "Тут недавно тебя искала жрица из вашего ордена." }, { 17.61, "Сказала, что тебе спешно надо вернуться в храм Луны в Дарнассе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением." }, { 26.95, "Я бы на твоём месте не тянула." } }, f = { { 0.00, "Ах да, здравствуй!" }, { 1.23, "Рада, что ты уделила мне минутку внимания." }, { 4.12, "Забраться так далеко от дома, да в такие юные годы, – мне по душе твоё рвение!" }, { 9.47, "Если бы мне в молодые годы хватило духу постранствовать по миру..." }, { 14.02, "Тут недавно тебя искала жрица из вашего ордена." }, { 17.35, "Сказала, что тебе спешно надо вернуться в храм Луны в Дарнассе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением." }, { 26.51, "Я бы на твоём месте не тянула." } } }, t = { d = 18.2, g = 1, v = "nightelf-female#51", n = { m = 219, f = 221 }, c = { m = { { 0.00, "Хорошо, что ты вернулся домой." }, { 2.05, "Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.68, "Надеюсь, Элуна благословила твоё путешествие!" }, { 11.69, "Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами." } }, f = { { 0.00, "Хорошо, что ты вернулась домой." }, { 2.11, "Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.76, "Надеюсь, Элуна благословила твоё путешествие!" }, { 11.78, "Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." } } } } },
    [5629] = { d = 25.7, g = 1, v = "nightelf-female#51", n = { m = 273, f = 276 }, c = { m = { { 0.00, "Ещё раз приветствую тебя." }, { 1.91, "Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени." }, { 9.22, "Жрица Алатея прислала за тобой." }, { 11.68, "Сдаётся, ты привлёк внимание наших старейшин, и они считают, что ты созрел для более великих дел." }, { 18.93, "Отправляйся в дарнасский храм Луны и найди там Алатею." }, { 23.03, "Удачи тебе, и да хранит тебя Элуна." } }, f = { { 0.00, "Ещё раз приветствую тебя." }, { 1.88, "Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени." }, { 9.07, "Жрица Алатея прислала за тобой." }, { 11.49, "Сдаётся, ты привлекла внимание наших старейшин, и они считают, что ты созрела для более великих дел." }, { 18.88, "Отправляйся в дарнасский храм Луны и найди там Алатею." }, { 22.91, "Удачи тебе, и да хранит тебя Элуна." } } }, t = { d = 17.8, g = 1, v = "nightelf-female#51", n = { m = 214, f = 216 }, c = { m = { { 0.00, "Хорошо, что ты вернулся." }, { 1.64, "Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.34, "Надеюсь, Элуна благословила твоё путешествие!" }, { 11.39, "Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами." } }, f = { { 0.00, "Хорошо, что ты вернулась." }, { 1.66, "Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.16, "Надеюсь, Элуна благословила твоё путешествие!" }, { 11.11, "Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." } } } } },
    [5630] = { d = 25.5, g = 1, v = "dwarf-male", n = { m = 286, f = 291 }, c = { m = { { 0.00, "Ну здравствуй, друг." }, { 1.41, "Приятно видеть, что ты так далеко забрался!" }, { 4.47, "Без обид, но многие из ваших не слишком хорошо переносят тутошние холода." }, { 9.72, "Славно, что ты слеплен из более крутого теста." }, { 13.04, "Не так давно одна из ваших жриц искала тебя – говорила, чтобы ты нашёл жрицу Алатею в храме Луны в Дарнассе." }, { 20.77, "Должно быть, это важно, так что возвращайся туда как можно скорее." } }, f = { { 0.00, "Ну здравствуй, подруга." }, { 1.64, "Приятно видеть, что ты так далеко забралась!" }, { 4.74, "Без обид, но многие из ваших не слишком хорошо переносят тутошние холода." }, { 9.92, "Славно, что ты слеплена из более крутого теста." }, { 13.27, "Не так давно одна из ваших жриц искала тебя – говорила, чтобы ты нашла жрицу Алатею в храме Луны в Дарнассе." }, { 20.99, "Должно быть, это важно, так что возвращайся туда как можно скорее." } } }, t = { d = 18.0, g = 1, v = "nightelf-female#51", n = { m = 219, f = 221 }, c = { m = { { 0.00, "Хорошо, что ты вернулся домой." }, { 2.05, "Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.68, "Надеюсь, Элуна благословила твоё путешествие!" }, { 11.69, "Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами." } }, f = { { 0.00, "Хорошо, что ты вернулась домой." }, { 2.08, "Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.60, "Надеюсь, Элуна благословила твоё путешествие!" }, { 11.57, "Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." } } } } },
    [5631] = { d = 18.7, g = 1, v = "human-male", n = { m = 204, f = 204 }, c = { m = { { 0.00, "Недавно в наших чертогах побывала одна жрица, и она искала вас, юный герой." }, { 5.24, "Она сказала, что её послали за вами и что вы должны вернуться в храм Луны в Дарнассе как можно скорее." }, { 12.12, "По прибытии найдите жрицу Алатею – она расскажет вам больше." }, { 16.26, "Да пребудет с вами Свет." } }, f = { { 0.00, "Недавно в наших чертогах побывала одна жрица, и она искала вас, юная героиня." }, { 5.61, "Она сказала, что её послали за вами и что вы должны вернуться в храм Луны в Дарнассе как можно скорее." }, { 12.81, "По прибытии найдите жрицу Алатею – она расскажет вам больше." }, { 17.14, "Да пребудет с вами Свет." } } }, t = { d = 18.1, g = 1, v = "nightelf-female#51", n = { m = 219, f = 221 }, c = { m = { { 0.00, "Хорошо, что ты вернулся домой." }, { 2.04, "Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.64, "Надеюсь, Элуна благословила твоё путешествие!" }, { 11.64, "Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами." } }, f = { { 0.00, "Хорошо, что ты вернулась домой." }, { 2.10, "Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.68, "Надеюсь, Элуна благословила твоё путешествие!" }, { 11.67, "Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." } } } } },
    [5632] = { d = 23.0, v = "nightelf-female#51", n = { x = 276 }, c = { x = { { 0.00, "Да-да, конечно." }, { 1.10, "Здравствуй." }, { 1.90, "Недавно тут побывала посланница нашего ордена." }, { 5.08, "Она искала тебя." }, { 6.30, "Она мельком упомянула, что в Дарнассе случилось что-то важное и что тебе следует как можно скорее вернуться в храм Луны." }, { 14.50, "Сразу поговори там со жрицей Алатеей." }, { 17.06, "Наверняка это касается твоих успехов." }, { 19.69, "В общем, возвращайся в Дарнасс, как только сможешь." } } } },
    [5633] = { d = 28.2, g = 1, v = "dwarf-female#34", n = { m = 307, f = 311 }, c = { m = { { 0.00, "Добро пожаловать, друг." }, { 1.74, "Приятно видеть тебя в наших чертогах." }, { 4.63, "Да пребудет благость с тобой и твоим народом." }, { 8.05, "Пока ты тут странствовал в наших краях, тебя разыскивала здесь жрица из вашего храма." }, { 14.42, "Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны." }, { 19.65, "Прости, большего не скажу, но мне показалось, что дело важное." }, { 24.28, "Когда доберёшься до Храма, поговори со жрицей Алатеей." } }, f = { { 0.00, "Добро пожаловать, подруга." }, { 1.98, "Приятно видеть тебя в наших чертогах." }, { 4.81, "Да пребудет благость с тобой и твоим народом." }, { 8.17, "Пока ты тут странствовала в наших краях, тебя разыскивала здесь жрица из вашего храма." }, { 14.50, "Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны." }, { 19.64, "Прости, большего не скажу, но мне показалось, что дело важное." }, { 24.19, "Когда доберёшься до Храма, поговори со жрицей Алатеей." } } }, t = { d = 19.4, g = 1, v = "nightelf-female#51", n = { m = 225, f = 226 }, c = { m = { { 0.00, "Чудесно, ты вернулся домой." }, { 1.95, "Тиранду и меня всегда радует, когда наши ученики уходят в мир и благополучно к нам возвращаются." }, { 8.66, "Как твои дела?" }, { 9.73, "Благословляет ли Элуна по-прежнему твои странствия?" }, { 13.30, "Может, после того как мы обсудим дело, ты расскажешь мне больше о своих путешествиях." } }, f = { { 0.00, "Чудесно, ты вернулась домой." }, { 2.03, "Тиранду и меня всегда радует, когда наши ученики уходят в мир и благополучно к нам возвращаются." }, { 8.84, "Как твои дела?" }, { 9.92, "Благословляет ли Элуна по-прежнему твои странствия?" }, { 13.54, "Может, после того как мы обсудим дело, ты расскажешь мне больше о своих путешествиях." } } } } },
    [5634] = { d = 17.4, g = 1, v = "human-female#45", n = { m = 195, f = 196 }, c = { m = { { 0.00, "Недавно к нам заглянул жрец, которому был нужен ты, герой." }, { 4.04, "Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне." }, { 10.67, "Когда прибудешь туда, отыщи верховного жреца Рохана – он всё объяснит." }, { 15.66, "Да пребудет с тобой Свет." } }, f = { { 0.00, "Недавно к нам заглянул жрец, которому была нужна ты, героиня." }, { 4.27, "Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне." }, { 10.86, "Когда прибудешь туда, отыщи верховного жреца Рохана – он всё объяснит." }, { 15.82, "Да пребудет с тобой Свет." } } }, t = { d = 15.9, v = "human-female#45", n = { x = 168 }, c = { x = { { 0.00, "Твои услуги, оказанные силам Света, неоценимы, а твои деяния – пример блистательной храбрости для всех, кто путешествует в землях, полных опасностей." }, { 11.53, "Прошу, считай этот урок наградой за всё, сделанное тобой." } } } } },
    [5635] = { d = 20.6, v = "human-female#45", n = { x = 256 }, c = { x = { { 0.00, "Тобой заинтересовались наши высшие иерархи." }, { 2.94, "Они желают твоего скорейшего возвращения в Собор Света Штормграда." }, { 7.44, "Вероятно, они считают, что для тебя наступило время нового обучения." }, { 12.06, "Когда доберёшься до собора, обратись прямо к верховной жрице Лорене, она расскажет тебе об остальном." }, { 18.84, "Удачи!" }, { 19.32, "Да хранит тебя Свет!" } } }, t = { d = 19.1, v = "human-female#45", n = { x = 205 }, c = { x = { { 0.00, "Я рада твоему прибытию." }, { 1.83, "Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света." }, { 10.21, "Есть уроки, которые должны выучить все, кто служит Свету." }, { 14.54, "Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." } } } } },
    [5636] = { d = 19.0, g = 1, v = "nightelf-female#51", n = { x = 206 }, c = { m = { { 0.00, "Да благословит тебя Элуна, герой!" }, { 2.51, "Надеюсь, что Свет не покидает тебя." }, { 5.09, "Тебя недавно разыскивал один из наших жрецов." }, { 8.53, "Он просил передать тебе, что в Соборе Света Штормграда тебя ожидает Верховная жрица Лорена." }, { 15.35, "Не трать времени даром, твой народ нуждается в тебе." } }, f = { { 0.00, "Да благословит тебя Элуна, героиня!" }, { 2.60, "Надеюсь, что Свет не покидает тебя." }, { 5.13, "Тебя недавно разыскивал один из наших жрецов." }, { 8.50, "Он просил передать тебе, что в Соборе Света Штормграда тебя ожидает Верховная жрица Лорена." }, { 15.18, "Не трать времени даром, твой народ нуждается в тебе." } } }, t = { d = 18.6, v = "human-female#45", n = { x = 205 }, c = { x = { { 0.00, "Я рада твоему прибытию." }, { 1.77, "Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света." }, { 9.91, "Есть уроки, которые должны выучить все, кто служит Свету." }, { 14.11, "Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." } } } } },
    [5637] = { d = 23.7, v = "dwarf-male", n = { x = 275 }, c = { x = { { 0.00, "Тебе пора отправляться в Штормград." }, { 2.50, "Верховная жрица Лорена ожидает тебя в Соборе Света, она хочет поговорить с тобой." }, { 8.32, "Должно случиться что-то особенное, если тобой заинтересовалась сама Верховная жрица." }, { 14.26, "Не знаю, к добру это или к худу." }, { 16.63, "Думаю, что так или иначе всё это окажется полезным для тебя." }, { 20.88, "Не трать много времени, собирайся быстрее." } } }, t = { d = 17.5, v = "human-female#45", n = { x = 186 }, c = { x = { { 0.00, "Я рада тебя видеть!" }, { 1.59, "Нам есть о чём поговорить, но твоё обучение важнее всего, ведь это – путь Света." }, { 7.59, "Есть знание, которым должны овладеть все прислужники Света." }, { 12.15, "Чувствуешь ли ты в себе достаточно сил?" }, { 15.12, "Если да, то перейдём к обсуждению." } } } } },
    [5638] = { d = 24.1, g = 1, v = "nightelf-female#51", n = { x = 256 }, c = { m = { { 0.00, "Эй, герой!" }, { 0.77, "Тебя недавно искал один из ваших жрецов!" }, { 3.77, "Он просил тебе передать, что тебя очень ждут в Соборе Света." }, { 8.11, "Ещё сказал, что это очень важно, и мне кажется, что ему стоит верить." }, { 13.09, "Он был настроен весьма благодушно, так что для тебя это хорошие новости." }, { 18.20, "Тебе стоит поторопиться, чтобы не упустить этот шанс." }, { 22.04, "Да хранит тебя Элуна, герой." } }, f = { { 0.00, "Эй, героиня!" }, { 0.89, "Тебя недавно искал один из ваших жрецов!" }, { 3.87, "Он просил тебе передать, что тебя очень ждут в Соборе Света." }, { 8.18, "Ещё сказал, что это очень важно, и мне кажется, что ему стоит верить." }, { 13.13, "Он был настроен весьма благодушно, так что для тебя это хорошие новости." }, { 18.20, "Тебе стоит поторопиться, чтобы не упустить этот шанс." }, { 22.00, "Да хранит тебя Элуна, героиня." } } }, t = { d = 16.6, g = 1, v = "human-female#45", n = { m = 182, f = 183 }, c = { m = { { 0.00, "Хорошо, что ты пришёл." }, { 1.60, "Нам о многом нужно поговорить, но важнее всего – твоё обучение путям Света." }, { 7.18, "Есть уроки, которые должен усвоить каждый служитель Света." }, { 11.57, "Если ты готов, давай начнём обсуждать некоторые из них прямо сейчас." } }, f = { { 0.00, "Хорошо, что ты пришла." }, { 1.67, "Нам о многом нужно поговорить, но важнее всего – твоё обучение путям Света." }, { 7.26, "Есть уроки, которые должен усвоить каждый служитель Света." }, { 11.66, "Если ты готова, давай начнём обсуждать некоторые из них прямо сейчас." } } } } },
    [5639] = { d = 19.2, v = "dwarf-male", n = { x = 224 }, c = { x = { { 0.00, "Тебя ждут в Штормграде!" }, { 1.65, "Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки." }, { 9.42, "Не мешкай." }, { 10.18, "Ты найдёшь Лорену в Соборе Света в центре города." }, { 13.68, "Передай ей от меня привет и постарайся не завалить экзамен." }, { 17.88, "Да хранит тебя Свет!" } } }, t = { d = 18.4, v = "human-female#45", n = { x = 186 }, c = { x = { { 0.00, "Я рада тебя видеть!" }, { 1.67, "Нам есть о чём поговорить, но твоё обучение важнее всего, ведь это – путь Света." }, { 7.97, "Есть знание, которым должны овладеть все прислужники Света." }, { 12.75, "Чувствуешь ли ты в себе достаточно сил?" }, { 15.87, "Если да, то перейдём к обсуждению." } } } } },
