    [5641] = { t = { d = 9.7, g = 1, v = "dwarf-male", n = { m = 86, f = 88 }, c = { m = { { 0.00, "Из тебя выйдет отличный герой." }, { 2.46, "Так держать!" }, { 3.44, "Ты уже показал, что готов к бою." }, { 6.04, "Пожалуй, пора научить тебя кой-чему ещё." } }, f = { { 0.00, "Из тебя выйдет отличная героиня." }, { 2.67, "Так держать!" }, { 3.69, "Ты уже показала, что готова к бою." }, { 6.51, "Пожалуй, пора научить тебя кой-чему ещё." } } } } },
    [5642] = { d = 18.6, v = "scourge-male#83", n = { x = 200 }, c = { x = { { 0.00, "В Оргриммаре происходит нечто важное." }, { 2.86, "Обычно посланцы, которые приезжают сюда за троллями-жрецами, держатся с ленцой." }, { 8.91, "А на этот раз они, похоже, спешили!" }, { 11.63, "Не засиживайся в Громовом Утёсе." }, { 14.01, "Думаю, тебе стоит как можно скорее вернуться на Аллею Духов." } } }, t = { d = 11.8, g = 1, v = "troll-male#77", n = { m = 110, f = 111 }, c = { m = { { 0.00, "Тебя ждёт один из самых важных обрядов инициации для жреца нашей веры." }, { 5.98, "Я вижу, что ты готов к нему, и потому сейчас объясню всё подробнее." } }, f = { { 0.00, "Тебя ждёт один из самых важных обрядов инициации для жреца нашей веры." }, { 6.11, "Я вижу, что ты готова к нему, и потому сейчас объясню всё подробнее." } } } } },
    [5643] = { d = 34.7, v = "creature/banshee", n = { x = 283 }, c = { x = { { 0.00, "Как и многие из наших жрецов, члены твоего племени проходят обряды инициации." }, { 7.84, "Эти обряды часто наделяют жрецов особыми способностями, которые помогают им выжить." }, { 16.32, "Я чувствую, что тебе пришло время пройти такой обряд." }, { 21.82, "Возвращайся в Аллею Духов в Оргриммаре и поговори с Ур'кьо." }, { 27.77, "То, чему он тебя научит, может оказаться чрезвычайно важным в будущем." } } }, t = { d = 9.8, g = 1, v = "troll-male#77", n = { m = 97, f = 98 }, c = { m = { { 0.00, "Настал час одного из важнейших обрядов посвящения для каждого, кто служит нашей вере." }, { 7.03, "Я расскажу тебе больше – ты готов." } }, f = { { 0.00, "Настал час одного из важнейших обрядов посвящения для каждого, кто служит нашей вере." }, { 7.03, "Я расскажу тебе больше – ты готова." } } } } },
    [5644] = { d = 37.9, g = 1, v = "scourge-male#83", n = { m = 342, f = 343 }, c = { m = { { 0.00, "Доброго тебе дня." }, { 1.52, "Вижу, ты многому научился, и пришло время вернуться к Эльталисте." }, { 7.08, "Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным." }, { 13.33, "Я не скажу, что тебя ждёт – пусть для тебя это будет сюрпризом." }, { 18.66, "Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила..." }, { 28.18, "Вот это были деньки." }, { 30.01, "Отправляйся в Подгород, поговори с Эльталисте." }, { 33.90, "Она ждёт тебя в Квартале Воинов." } }, f = { { 0.00, "Доброго тебе дня." }, { 1.58, "Вижу, ты многому научилась, и пришло время вернуться к Эльталисте." }, { 7.41, "Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным." }, { 13.88, "Я не скажу, что тебя ждёт – пусть для тебя это будет сюрпризом." }, { 19.39, "Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила..." }, { 29.25, "Вот это были деньки." }, { 31.14, "Отправляйся в Подгород, поговори с Эльталисте." }, { 35.16, "Она ждёт тебя в Квартале Воинов." } } }, t = { d = 14.8, g = 1, v = "creature/banshee", n = { m = 112, f = 114 }, c = { m = { { 0.00, "Отлично, ты вернулся и даже не опоздал." }, { 4.07, "Нам нужно обсудить кое-что важное." }, { 7.67, "Твоя сила растёт, и надо подготовить тебя к грядущим испытаниям." } }, f = { { 0.00, "Отлично, ты вернулась и даже не опоздала." }, { 4.39, "Нам нужно обсудить кое-что важное." }, { 8.11, "Твоя сила растёт, и надо подготовить тебя к грядущим испытаниям." } } } } },
    [5645] = { d = 23.1, g = 1, v = "human-female#45", n = { m = 267, f = 270 }, c = { m = { { 0.00, "Ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне." }, { 4.35, "Торопитесь, могучий мой друг, ибо близится срок вашего очередного испытания." }, { 9.72, "Хотя я хотела бы стать свидетелем особых обрядов вашей расы, но моё место здесь." }, { 15.41, "Но да пребудет с вами Свет в пути вашем." }, { 18.29, "Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии." } }, f = { { 0.00, "Ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне." }, { 4.33, "Торопитесь, могучая моя госпожа, ибо близится срок вашего очередного испытания." }, { 10.01, "Хотя я хотела бы стать свидетелем особых обрядов вашей расы, но моё место здесь." }, { 15.68, "Но да пребудет с вами Свет в пути вашем." }, { 18.55, "Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии." } } }, t = { d = 12.7, g = 1, v = "dwarf-male", n = { m = 127, f = 129 }, c = { m = { { 0.00, "Хорошо, что ты пришёл." }, { 1.67, "Наша раса горда и могуча, и пришла пора научиться быть таким не только самому, но и вселять эти чувства в сердца других." }, { 11.10, "Готов ли ты, юноша?" } }, f = { { 0.00, "Хорошо, что ты пришла." }, { 1.74, "Наша раса горда и могуча, и пришла пора научиться быть такой не только самой, но и вселять эти чувства в сердца других." }, { 11.13, "Готова ли ты, девушка?" } } } } },
    [5646] = { d = 19.4, v = "troll-male#77", n = { x = 206 }, c = { x = { { 0.00, "Эльталисте оказала моему народу большое доверие, посылая ко мне учеников, а теперь я сделаю то же для её племени." }, { 8.68, "Возвращайся в Подгород." }, { 10.49, "Твоя госпожа ждёт тебя в Квартале Воинов, чтобы рассказать ещё больше о твоём народе и его обычаях." }, { 18.20, "Ступай, не медли." } } }, t = { d = 14.5, g = 1, v = "creature/banshee", n = { m = 112, f = 114 }, c = { m = { { 0.00, "Отлично, ты вернулся и даже не опоздал." }, { 4.16, "Нам нужно обсудить кое-что важное." }, { 7.85, "Твоя сила растёт, и надо подготовить тебя к грядущим испытаниям." } }, f = { { 0.00, "Отлично, ты вернулась и даже не опоздала." }, { 4.25, "Нам нужно обсудить кое-что важное." }, { 7.85, "Твоя сила растёт, и надо подготовить тебя к грядущим испытаниям." } } } } },
    [5647] = { d = 32.3, v = "nightelf-female#51", n = { x = 363 }, c = { x = { { 0.00, "Твоя раса так сильна." }, { 1.66, "Мы гордимся союзом с вами." }, { 3.64, "С каждым закатом ты и твои сородичи не только всё ближе к разгадке вашего истинного происхождения, но и обретаете всё большую уверенность в том, что вы на верном пути во многом." }, { 16.50, "Именно эта уверенность приносит вам победу." }, { 19.74, "Недавно из Стальгорна пришла весть." }, { 22.33, "Тебя просят вернуться и поговорить с верховным жрецом Роханом в Палатах Магии." }, { 28.16, "Не стоит заставлять его ждать." }, { 30.41, "Да направит твой путь Элуна." } } }, t = { d = 14.4, g = 1, v = "dwarf-male", n = { m = 148, f = 150 }, c = { m = { { 0.00, "Хорошо, что ты пришёл." }, { 1.61, "Наш народ горд и силён, и пора тебе научиться не только хранить эту гордость и силу в себе, но и пробуждать такие же чувства и уверенность в других." }, { 12.64, "Ты готов, парень?" } }, f = { { 0.00, "Хорошо, что ты пришла." }, { 1.72, "Наш народ горд и силён, и пора тебе научиться не только хранить эту гордость и силу в себе, но и пробуждать такие же чувства и уверенность в других." }, { 13.03, "Ты готова, девушка?" } } } } },
    [5648] = { d = 32.8, g = 1, v = "troll-female", n = { m = 323, f = 325 }, c = { m = { { 0.00, "Что ж, вот ты и готов к своему первому испытанию." }, { 3.88, "К югу от Колючего Холма, сразу за городской чертой, лежит раненая орчиха из нашего отряда." }, { 11.20, "Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою." }, { 17.84, "Помочь ей может только кто-то из нас." }, { 20.85, "Её зовут Корджа." }, { 22.22, "Найди её, исцели и дай ей благословение наших предков." }, { 26.53, "Сделай это – и я сочту, что ты подтвердил свою готовность ступить на путь жреца." } }, f = { { 0.00, "Что ж, вот ты и готова к своему первому испытанию." }, { 3.79, "К югу от Колючего Холма, сразу за городской чертой, лежит раненая орчиха из нашего отряда." }, { 10.81, "Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою." }, { 17.30, "Помочь ей может только кто-то из нас." }, { 20.19, "Её зовут Корджа." }, { 21.50, "Найди её, исцели и дай ей благословение наших предков." }, { 25.63, "Сделай это – и я сочту, что ты подтвердила свою готовность ступить на путь жреца." } } }, t = { d = 34.6, g = 1, v = "troll-female", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Отлично!" }, { 0.69, "Так значит, Корджа жива и может снова защищать наш город от злокозненных людей?" }, { 6.87, "Я люблю вспоминать дни битв, когда подлинная сила проявлялась в бою." }, { 12.15, "Тогда часто случалось, что мудрые губили тех, кто недооценивал их, полагаясь лишь на мощь мышц." }, { 19.31, "Я считаю, что ты молодец." }, { 21.25, "Вот, возьми это одеяние." }, { 23.19, "Может быть, оно тебе пригодится." }, { 25.76, "Может быть, тебе всё равно, однако ты его заслужил, и я горжусь тем, что теперь могу звать тебя братом." } }, f = { { 0.00, "Отлично!" }, { 0.71, "Так значит, Корджа жива и может снова защищать наш город от злокозненных людей?" }, { 7.06, "Я люблю вспоминать дни битв, когда подлинная сила проявлялась в бою." }, { 12.48, "Тогда часто случалось, что мудрые губили тех, кто недооценивал их, полагаясь лишь на мощь мышц." }, { 19.82, "Я считаю, что ты молодец." }, { 21.82, "Вот, возьми это одеяние." }, { 23.81, "Может быть, оно тебе пригодится." }, { 26.45, "Может быть, тебе всё равно, однако ты его заслужила, и я горжусь тем, что теперь могу звать тебя сестрой." } } } } },
    [5649] = { d = 33.0, g = 1, v = "troll-male#78", n = { m = 326, f = 327 }, c = { m = { { 0.00, "Понимаешь, наш народ присоединился к Орде, потому что они к нам добры." }, { 5.63, "Они – преданные друзья, они многому нас научили, внушили нам представление о чести..." }, { 12.48, "Но наши старые обычаи ещё живы." }, { 15.08, "Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне." }, { 21.43, "Ты это знаешь." }, { 22.65, "Вот почему я посылаю тебя в Колючий Холм, к Тай'джин." }, { 26.91, "Она откроет тебе мудрость нашего племени." }, { 30.37, "Ступай к ней, когда будешь готов." } }, f = { { 0.00, "Понимаешь, наш народ присоединился к Орде, потому что они к нам добры." }, { 5.59, "Они – преданные друзья, они многому нас научили, внушили нам представление о чести..." }, { 12.39, "Но наши старые обычаи ещё живы." }, { 14.97, "Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне." }, { 21.28, "Ты это знаешь." }, { 22.49, "Вот почему я посылаю тебя в Колючий Холм, к Тай'джин." }, { 26.72, "Она откроет тебе мудрость нашего племени." }, { 30.16, "Ступай к ней, когда будешь готова." } } }, t = { d = 36.4, v = "troll-female", n = { x = 380 }, c = { x = { { 0.00, "Ах-ха... наконец-то твой путь привёл тебя к Тай'джин." }, { 4.00, "Это хорошо." }, { 4.97, "Теперь ты знаешь, что мы уже не то племя, что когда-то присоединилось к Орде." }, { 10.83, "Мы стали гораздо сильнее." }, { 12.83, "Мы обрели эту силу потому, что научились приспосабливаться – это мы переняли у Орды." }, { 19.31, "Прежде мы побеждали врагов и забирали их силу, теперь же мы набираемся сил, а потом побеждаем врагов." }, { 27.03, "Возможно, разница не столь заметна, но ты её поймёшь." }, { 30.96, "Ты увидишь." }, { 31.86, "Племя рассчитывает на то, что ты научишься видеть такие вещи." } } } } },
    [5650] = { d = 51.7, v = "scourge-male#82", n = { x = 426 }, c = { x = { { 0.00, "Мы черпаем силу из тьмы и теней, но ваше дело – не только дело тьмы." }, { 6.68, "Вы поняли, что большая заслуга есть и в изучении искусства лечения." }, { 13.18, "Это мудрый выбор." }, { 15.03, "Но прежде чем познать тьму, вы должны познать и свет, а для этого нужно пройти испытание." }, { 23.64, "К северу от кладбища находится раненый страж смерти по имени Кел – он уже очень долго защищает нас от гноллов, и ему требуется лечение." }, { 36.82, "Но для того чтобы он мог и дальше исполнять свой долг, вы должны также придать ему сил." }, { 45.26, "Используйте для этого свои заклинания, а потом возвращайтесь ко мне." } } }, t = { d = 41.4, v = "scourge-male#82", n = { x = 375 }, c = { x = { { 0.00, "Вы с лёгкостью выдержали моё испытание." }, { 3.38, "Это хорошо." }, { 4.51, "Скоро вы будете готовы принять на себя ещё большую ответственность, и этот путь приведёт вас к более тёмным силам – таким, которыми не обладает ни один жрец другой расы." }, { 19.47, "Примите это одеяние в знак вашего положения." }, { 23.50, "Вы его заслужили." }, { 25.11, "Если же вы не хотите его носить, что ж, тогда вы вольны поступить с ним так, как вам будет угодно." }, { 33.80, "Я и другие и так никогда не забудем того положения, которого вы достигли в наших рядах." } } } } },
    [5651] = { d = 44.5, v = "scourge-male#82", n = { x = 406 }, c = { x = { { 0.00, "Отрёкшиеся извлекли много уроков из своего опыта и поняли такие вещи, о которых остальные только начинают догадываться." }, { 10.72, "И несмотря на то что наш путь лежит во тьме, скоро вы поймёте, что очень много вещей зависит от неё – так же как и от света." }, { 21.43, "Вы научитесь использовать и то и другое... с должной осторожностью." }, { 27.32, "Но никогда не забывайте того, что нас создали в тлене и бросили гнить, как какие-нибудь отбросы." }, { 35.78, "Тьма – это наш дом." }, { 37.47, "Когда будете готовы узнать больше, разыщите тёмного священника Берила в Брилле." } } }, t = { d = 12.2, v = "scourge-male#82", n = { x = 94 }, c = { x = { { 0.00, "Наконец-то вы прибыли!" }, { 2.41, "Чтобы пройти испытания, одной веры недостаточно." }, { 7.71, "Нужно ещё чувство долга и немного амбиций." } } } } },
    [5652] = { t = { d = 16.2, g = 1, v = "troll-male#77", n = { m = 151, f = 153 }, c = { m = { { 0.00, "Тебе стоит прислушаться к этому уроку, дитя." }, { 3.96, "«Обессиливающий сглаз» сослужит тебе добрую службу в бою." }, { 8.94, "Позже я устрою тебе испытания, чтобы ты стал сильнее и доказал племени, чего стоишь." } }, f = { { 0.00, "Тебе стоит прислушаться к этому уроку, дитя." }, { 3.93, "«Обессиливающий сглаз» сослужит тебе добрую службу в бою." }, { 8.85, "Позже я устрою тебе испытания, чтобы ты стала сильнее и доказала племени, чего стоишь." } } } } },
    [5654] = { d = 16.4, v = "troll-female", n = { x = 177 }, c = { x = { { 0.00, "Пора тебе встретиться с Ур'кьо." }, { 2.42, "Ты найдёшь его на аллее Духов, в городе орков." }, { 5.92, "Ступай туда и поговори с ним." }, { 8.14, "Пора тебе познать древнюю мудрость нашего народа." }, { 11.97, "Пора вступить в круг и стать настоящим жрецом нашего племени." } } }, t = { d = 6.3, v = "troll-male#77", n = { x = 48 }, c = { x = { { 0.00, "А, ты здесь!" }, { 1.22, "Это хорошо." }, { 2.54, "Теперь мы можем начать твоё обучение." } } } } },
    [5655] = { d = 19.4, v = "troll-male#77", n = { x = 199 }, c = { x = { { 0.00, "Мне нужно было удостовериться, что ты не уйдёшь слишком далеко от дома." }, { 5.43, "Меня послали за тобой потому, что Ур'кьо, величайший из наших жрецов, желает поговорить с тобой." }, { 12.96, "Ступай туда." }, { 14.01, "Ступай в Аллею Духов в городе орков и поговори с Ур'кьо." }, { 18.46, "Он ждёт тебя." } } }, t = { d = 6.2, v = "troll-male#77", n = { x = 48 }, c = { x = { { 0.00, "А, хорошо, ты уже тут." }, { 2.20, "Мы можем начать учить тебя старым путям." } } } } },
    [5656] = { d = 28.2, v = "scourge-male#83", n = { x = 272 }, c = { x = { { 0.00, "Моё нестареющее сердце всегда греет мысль о том, что по миру бродит множество жрецов всех культур." }, { 8.18, "Хорошо знать, что на свете есть сила, не имеющая отношения к тайной магии и вполне доступная нам." }, { 16.28, "Вот почему я сочту за честь указать тебе путь." }, { 20.14, "Ур'кьо, ваш великий жрец в Оргриммаре, просит тебя прибыть к нему." }, { 25.74, "Ты найдёшь его на аллее Духов." } } } },
    [5657] = { d = 21.0, g = 1, v = "creature/banshee", n = { m = 166, f = 166 }, c = { m = { { 0.00, "Домой!" }, { 0.72, "Возвращайся домой, юный герой!" }, { 3.87, "Твой духовный наставник Ур'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути." }, { 13.67, "Ступай в Аллею Духов в Оргриммаре, великом городе Орды!" }, { 19.24, "Ты найдёшь его там." } }, f = { { 0.00, "Домой!" }, { 0.71, "Возвращайся домой, юная героиня!" }, { 3.98, "Твой духовный наставник Ур'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути." }, { 13.63, "Ступай в Аллею Духов в Оргриммаре, великом городе Орды!" }, { 19.11, "Ты найдёшь его там." } } }, t = { d = 6.0, v = "troll-male#77", n = { x = 48 }, c = { x = { { 0.00, "А, хорошо, ты уже тут." }, { 2.14, "Мы можем начать учить тебя старым путям." } } } } },
    [5658] = { t = { d = 11.4, g = 1, v = "creature/banshee", n = { m = 77, f = 79 }, c = { m = { { 0.00, "А, юный герой, я рада, что ты вернулся." }, { 4.11, "Я хочу преподать тебе урок, который тебе стоит запомнить." }, { 10.27, "Ты готов?" } }, f = { { 0.00, "А, юная героиня, я рада, что ты вернулась." }, { 4.37, "Я хочу преподать тебе урок, который тебе стоит запомнить." }, { 10.50, "Ты готова?" } } } } },
    [5660] = { d = 20.5, g = 1, v = "troll-female", n = { m = 210, f = 211 }, c = { m = { { 0.00, "Далеко же ты забрался, герой." }, { 2.23, "Тебя ждут в большом городе под землёй." }, { 5.07, "Твоя госпожа, Эльталисте, велит тебе вернуться." }, { 8.72, "Как и в моём племени, есть вещи, которым тебя может научить лишь она." }, { 13.93, "И не задерживайся попусту." }, { 15.89, "Лучше лети в Квартал Воинов на самом быстром дирижабле." } }, f = { { 0.00, "Далеко же ты забралась, героиня." }, { 2.47, "Тебя ждут в большом городе под землёй." }, { 5.35, "Твоя госпожа, Эльталисте, велит тебе вернуться." }, { 9.05, "Как и в моём племени, есть вещи, которым тебя может научить лишь она." }, { 14.32, "И не задерживайся попусту." }, { 16.31, "Лучше лети в Квартал Воинов на самом быстром дирижабле." } } }, t = { d = 25.0, g = 1, v = "creature/banshee", n = { m = 181, f = 181 }, c = { m = { { 0.00, "А, вот и ещё один." }, { 1.94, "Для меня время не имеет значения, но для тебя оно бежит быстро." }, { 8.93, "Тебе следует многому научиться, и я хочу передать тебе побольше знаний." }, { 16.79, "А пока покажи, на что способен." }, { 20.19, "Выполни это условие, и награда будет велика." } }, f = { { 0.00, "А, вот и ещё одна." }, { 1.90, "Для меня время не имеет значения, но для тебя оно бежит быстро." }, { 8.76, "Тебе следует многому научиться, и я хочу передать тебе побольше знаний." }, { 16.47, "А пока покажи, на что способна." }, { 19.80, "Выполни это условие, и награда будет велика." } } } } },
    [5661] = { d = 26.4, v = "troll-male#77", n = { x = 277 }, c = { x = { { 0.00, "Ты всего лишь гость в деревне Кровавого Копыта, а дом твой далеко." }, { 4.93, "Меня послали сюда искать жрецов из моего племени." }, { 8.83, "С ними хотят говорить вожди." }, { 11.08, "Но и тебе я могу помочь." }, { 13.00, "Говорят, что ваша главная жрица велит всем Отрёкшимся прийти к ней – видно, ей есть что сказать." }, { 20.19, "Ступай, поговори с Эльталисте в Квартале воинов этого вашего города, как его там..." } } }, t = { d = 26.1, g = 1, v = "creature/banshee", n = { m = 194, f = 196 }, c = { m = { { 0.00, "А, хорошо, ещё один прибыл." }, { 2.97, "Время для меня не имеет значения, но для тебя оно на вес золота." }, { 9.87, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить." }, { 17.82, "Тебе нужно лишь доказать, чего ты стоишь." }, { 22.33, "Докажи – и будешь щедро вознаграждён." } }, f = { { 0.00, "А, хорошо, ещё одна прибыла." }, { 2.97, "Время для меня не имеет значения, но для тебя оно на вес золота." }, { 9.65, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить." }, { 17.34, "Тебе нужно лишь доказать, чего ты стоишь." }, { 21.70, "Докажи – и будешь щедро вознаграждена." } } } } },
    [5662] = { d = 25.4, v = "troll-male#77", n = { x = 263 }, c = { x = { { 0.00, "Моё почтение тебе и твоему народу." }, { 2.81, "Обычно я учу лишь своих соплеменников." }, { 5.91, "Тебе же передала знания Эльталисте из города, некогда звавшегося Лордероном." }, { 12.04, "Возвращайся к ней, ведь только она может передать тебе способности, отличающие воинов вашей веры от других." }, { 20.68, "Ступай в Квартал Воинов Подгорода и отыщи там свою госпожу." } } }, t = { d = 24.3, g = 1, v = "creature/banshee", n = { m = 181, f = 181 }, c = { m = { { 0.00, "А, вот и ещё один." }, { 1.77, "Для меня время не имеет значения, но для тебя оно бежит быстро." }, { 8.13, "Тебе следует многому научиться, и я хочу передать тебе побольше знаний." }, { 15.29, "А пока покажи, на что способен." }, { 18.38, "Выполни это условие, и награда будет велика." } }, f = { { 0.00, "А, вот и ещё одна." }, { 1.89, "Для меня время не имеет значения, но для тебя оно бежит быстро." }, { 8.70, "Тебе следует многому научиться, и я хочу передать тебе побольше знаний." }, { 16.36, "А пока покажи, на что способна." }, { 19.67, "Выполни это условие, и награда будет велика." } } } } },
    [5663] = { d = 16.8, g = 1, v = "scourge-male#83", n = { m = 186, f = 186 }, c = { m = { { 0.00, "Эльталисте послала вести всем своим жрецам." }, { 3.32, "Нам велено отправить молодёжь в Подгород на обучение." }, { 7.24, "Если ты в самом деле считаешь себя одним из верных, возвращайся туда." }, { 12.59, "Эльталисте живёт в Квартале Воинов в глубинах Подгорода." } }, f = { { 0.00, "Эльталисте послала вести всем своим жрецам." }, { 3.35, "Нам велено отправить молодёжь в Подгород на обучение." }, { 7.31, "Если ты в самом деле считаешь себя одной из верных, возвращайся туда." }, { 12.71, "Эльталисте живёт в Квартале Воинов в глубинах Подгорода." } } }, t = { d = 26.2, g = 1, v = "creature/banshee", n = { m = 194, f = 196 }, c = { m = { { 0.00, "А, хорошо, ещё один прибыл." }, { 2.88, "Время для меня не имеет значения, но для тебя оно на вес золота." }, { 9.57, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить." }, { 17.28, "Тебе нужно лишь доказать, чего ты стоишь." }, { 21.64, "Докажи – и будешь щедро вознаграждён." } }, f = { { 0.00, "А, хорошо, ещё одна прибыла." }, { 3.05, "Время для меня не имеет значения, но для тебя оно на вес золота." }, { 9.92, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить." }, { 17.83, "Тебе нужно лишь доказать, чего ты стоишь." }, { 22.31, "Докажи – и будешь щедро вознаграждена." } } } } },
    [5672] = { t = { d = 13.7, g = 1, v = "nightelf-female#51", n = { m = 147, f = 149 }, c = { m = { { 0.00, "Посвятив себя Элуне и нашему народу, ты достиг состояния, доступного не каждому из нас." }, { 6.73, "По традиции за такую преданность тебя обучают ещё более могучим способностям." }, { 12.70, "Ты согласен?" } }, f = { { 0.00, "Посвятив себя Элуне и нашему народу, ты достигла состояния, доступного не каждому из нас." }, { 6.88, "По традиции за такую преданность тебя обучают ещё более могучим способностям." }, { 12.86, "Ты согласна?" } } } } },
    [5673] = { d = 27.8, v = "human-female#45", n = { x = 298 }, c = { x = { { 0.00, "Знай, что здесь ты можешь в любое время обратиться к любому наставнику." }, { 5.31, "Впрочем, есть знания, которые мы не можем тебе предоставить." }, { 9.87, "Среди них – учение вашей богини Элуны." }, { 12.87, "Верным своим приверженцам она даёт особые способности, и, если я не ошибаюсь, тебе пора вернуться домой, в Храм Луны, и пройти испытание." }, { 23.29, "Так что как сможешь – возвращайся и поговори со жрицей Алатеей." } } }, t = { d = 19.3, v = "nightelf-female#51", n = { x = 228 }, c = { x = { { 0.00, "Да благословит тебя Элуна за столь скорое возвращение." }, { 3.82, "Это важный период в твоём обучении, и орден весьма серьёзно к этому относится." }, { 9.36, "Когда отдохнёшь с дороги, дай мне знать." }, { 12.10, "Тогда мы сможем поговорить о продолжении твоего обучения и о том, куда на сей раз приведёт тебя твой путь." } } } } },
    [5674] = { d = 22.8, g = 1, v = "nightelf-female#51", n = { m = 260, f = 262 }, c = { m = { { 0.00, "Настал славный день." }, { 1.45, "Ты достиг возраста, когда наши жрецы изучают те способности, которые свойственны только ночным эльфам." }, { 8.71, "Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела." }, { 15.91, "Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны." } }, f = { { 0.00, "Настал славный день." }, { 1.49, "Ты достигла возраста, когда наши жрицы изучают те способности, которые свойственны только ночным эльфам." }, { 9.07, "Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела." }, { 16.46, "Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны." } } } },
    [5675] = { d = 19.8, g = 1, v = "dwarf-male", n = { m = 231, f = 234 }, c = { m = { { 0.00, "Не тяни время, друг." }, { 1.43, "Пора тебе возвращаться домой в Дарнасс." }, { 4.23, "Жрица Алатея велит возвращаться на обучение." }, { 7.35, "Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света." }, { 13.13, "Так что как сможешь – иди." }, { 14.94, "Алатея в своём письме говорит, что будет ждать тебя в храме Луны." }, { 19.48, "Удачи." } }, f = { { 0.00, "Не тяни время, подруга." }, { 1.66, "Пора тебе возвращаться домой в Дарнасс." }, { 4.43, "Жрица Алатея велит возвращаться на обучение." }, { 7.50, "Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света." }, { 13.22, "Так что как сможешь – иди." }, { 15.00, "Алатея в своём письме говорит, что будет ждать тебя в храме Луны." }, { 19.49, "Удачи." } } }, t = { d = 19.4, g = 1, v = "nightelf-female#51", n = { m = 219, f = 220 }, c = { m = { { 0.00, "Да благословит тебя Элуна за то, что ты так быстро к нам вернулся." }, { 4.71, "Это важная пора в твоём обучении, и все в нашем ордене относятся к ней очень серьёзно." }, { 10.93, "Когда отдохнёшь с дороги, дай мне знать." }, { 13.75, "Тогда мы обсудим продолжение твоего обучения и то, куда приведёт тебя твой путь." } }, f = { { 0.00, "Да благословит тебя Элуна за то, что ты так быстро к нам вернулась." }, { 4.70, "Это важная пора в твоём обучении, и все в нашем ордене относятся к ней очень серьёзно." }, { 10.82, "Когда отдохнёшь с дороги, дай мне знать." }, { 13.59, "Тогда мы обсудим продолжение твоего обучения и то, куда приведёт тебя твой путь." } } } } },
    [5676] = { t = { d = 16.3, v = "human-female#45", n = { x = 190 }, c = { x = { { 0.00, "Нам пришлось освоить кое-какую магию, чтобы защититься от того, что принято называть нашим злейшим врагом, — от тайной магии." }, { 8.86, "Я научу тебя заклинанию, которое поможет защитить тебя и твоих спутников от тех, кто владеет подобной силой." } } } } },
    [5677] = { d = 26.2, v = "dwarf-male", n = { x = 308 }, c = { x = { { 0.00, "Мне бы хотелось показать тебе кое-какие из наших особых методик обучения, которые направят тебя по пути Света, но меня опередили." }, { 9.08, "Тебе нужно вернуться в Штормград..." }, { 11.57, "Прямо сейчас." }, { 12.57, "Поверь мне, так будет лучше." }, { 14.56, "Когда ты встретишься с Верховной жрицей Лореной из Собора Света, ты поймёшь, о чём я говорю." }, { 20.84, "Для вашей расы настало время подумать о будущем и выбрать свой собственный путь." } } }, t = { d = 28.3, v = "human-female#45", n = { x = 308 }, c = { x = { { 0.00, "Ах, вы как раз вовремя." }, { 1.64, "Я начала задаваться вопросом, все ли мои посланники были успешными." }, { 6.55, "Я рада видеть, что это так, иначе я готова поспорить, что вы всё ещё были бы в мире, узнавая больше обо всех угрозах, которые существуют против нашего народа." }, { 18.30, "Вы готовы?" }, { 19.09, "Я имею в виду готовы к дальнейшим тренировкам." }, { 22.50, "Ваша сила растёт быстрее, и я чувствую, что вы готовы больше узнать о нашей вере." } } } } },
    [5678] = { d = 27.6, v = "nightelf-female#51", n = { x = 310 }, c = { x = { { 0.00, "Тебе пора возвращаться в Штормград." }, { 2.62, "Старшие иерархи призывают тебя продолжить тренировки." }, { 6.56, "Жаль, что мне пришлось разыскивать тебя, но я делаю это во имя союза между нашими расами." }, { 13.12, "Буду говорить откровенно, тайная магия не внушает мне никакого доверия, хоть по благословению богов, хоть без них..." }, { 21.45, "Ты понимаешь, о чём я говорю?" }, { 23.55, "Вернись в Собор Света." }, { 25.25, "Верховная жрица Лорена ждёт тебя." } } }, t = { d = 27.9, v = "human-female#45", n = { x = 308 }, c = { x = { { 0.00, "Ах, вы как раз вовремя." }, { 1.63, "Я начала задаваться вопросом, всё ли мои посланники были успешными." }, { 6.51, "Я рада видеть, что это так, иначе я готова поспорить, что вы всё ещё были бы в мире, узнавая больше обо-всех угрозах, которые существуют против нашего народа." }, { 17.97, "Вы готовы?" }, { 18.75, "Я имею в виду готовы к дальнейшим тренировкам." }, { 22.14, "Ваша сила растёт быстрее, и я чувствую, что вы готовы больше узнать о нашей вере." } } } } },
    [5679] = { t = { d = 17.5, g = 1, v = "creature/banshee", n = { m = 138, f = 139 }, c = { m = { { 0.00, "Если ты готов, я научу тебя заклинанию «Всепожирающая чума»." }, { 6.20, "Это заклинание немалой силы, и оно поможет тебе в грядущих битвах." }, { 13.13, "Упражняйся с ним — позже тебя ждут испытания." } }, f = { { 0.00, "Если ты готова, я научу тебя заклинанию «Всепожирающая чума»." }, { 6.17, "Это заклинание немалой силы, и оно поможет тебе в грядущих битвах." }, { 12.98, "Упражняйся с ним — позже тебя ждут испытания." } } } } },
    [5680] = { t = { d = 9.2, v = "troll-male#77", n = { x = 83 }, c = { x = { { 0.00, "Твои обряды ещё впереди." }, { 2.24, "А пока я научу тебя заклинанию, которое очень пригодится тебе в бою с врагами." } } } } },
    [5713] = { d = 29.6, v = "nightelf-female", n = { x = 384 }, c = { x = { { 0.00, "Я направлялась в Аубердин с важным донесением, когда меня атаковал фурболг Марош и его следопыты." }, { 6.26, "Во время атаки я получила отравление, так что еле держусь." }, { 9.99, "Я могу изготовить противоядие, но это займёт некоторое время." }, { 13.89, "Хотела попросить вас защитить меня, пока я не приму противоядие." }, { 18.03, "Я подсоблю вам своим луком, как смогу." }, { 20.49, "Если мы выживем, то смогу доставить донесение в Аубердин, а вас попрошу поговорить с Онейей на Заставе Мейстры и проинформировать её о случившемся." } } }, t = { d = 14.6, g = 1, v = "nightelf-female#52", n = { x = 162 }, c = { m = { { 0.00, "Вы принесли долгожданное известие, герой." }, { 2.99, "Приятно слышать, что Айнаша жива и здорова благодаря вам." }, { 7.16, "Смею надеяться, вы примете эту награду за вашу доблесть." }, { 11.32, "Пусть Элуна заботится о вас и освещает ваш путь." } }, f = { { 0.00, "Вы принесли долгожданное известие, героиня." }, { 3.04, "Приятно слышать, что Айнаша жива и здорова благодаря вам." }, { 7.10, "Смею надеяться, вы примете эту награду за вашу доблесть." }, { 11.16, "Пусть Элуна заботится о вас и освещает ваш путь." } } } } },
    [5721] = { d = 28.8, g = 1, v = "creature/chromie", n = { m = 325, f = 325 }, c = { m = { { 0.00, "Теперь, тебе предстоит принять участие в битве при Дарроушире и спасти Джозефа Редпата." }, { 6.17, "Положи реликвии на городскую площадь Дарроушира, и духи его жителей восстанут из могил." }, { 12.34, "Начнётся битва, и ты должен сделать всё возможное, чтобы Дейвил пережил Хоргуса, а Редпат дожил до порчи и после этого был повержен." }, { 21.59, "В этом случае дух Редпата будет спасён." }, { 24.36, "Поговори с ним и возвращайся к его дочери Памеле." } }, f = { { 0.00, "Теперь, тебе предстоит принять участие в битве при Дарроушире и спасти Джозефа Редпата." }, { 6.28, "Положи реликвии на городскую площадь Дарроушира, и духи его жителей восстанут из могил." }, { 12.55, "Начнётся битва, и ты должна сделать всё возможное, чтобы Дейвил пережил Хоргуса, а Редпат дожил до порчи и после этого был повержен." }, { 21.96, "В этом случае дух Редпата будет спасён." }, { 24.78, "Поговори с ним и возвращайся к его дочери Памеле." } } }, t = { d = 17.2, v = "child-female", n = { x = 161 }, c = { x = { { 0.00, "Битва окончена!" }, { 1.39, "Мой папа сказал мне это!" }, { 3.55, "Он разогнал всех духов и возвращается домой!" }, { 7.33, "Я так счастлива!" }, { 8.72, "А ещё он сказал, чтобы я радушно встретила тебя, так что я приготовила тебе чаю." }, { 15.58, "Ты любишь с сахаром?" } } } } },
    [5722] = { d = 43.1, v = "tauren-male", n = { x = 392 }, c = { x = { { 0.00, "В Огненной пропасти Магату интересуют не только трогги." }, { 4.95, "До неё дошли слухи, что один из её слуг, некий Маур Зловещий Тотем, будучи в пропасти, нашёл нечто особенное, но выбраться оттуда ему не удалось." }, { 17.81, "Она хочет, чтобы кто-нибудь нашёл тело Маура – если оно ещё цело – и выяснил, что же он такое нашёл, пытаясь вести переговоры с троггами." }, { 30.02, "Если найдёшь что-нибудь интересное, принеси это Магате, и она наверняка не поскупится на награду." }, { 38.65, "Да, пропасть ищи в самых тёмных закоулках Оргриммара." } } }, t = { d = 20.0, v = "narrator", n = { x = 216 }, c = { x = { { 0.00, "Тело выглядит так, будто Маура жестоко били дубинками или кулаками, но большая часть одежды и снаряжения на месте." }, { 8.83, "Похоже, троггам не сильно были нужны его пожитки." }, { 12.77, "Вы начинаете осматривать тело в поисках любых предметов, которые могли бы заинтересовать Магату." } } } } },
    [5723] = { d = 37.5, v = "tauren-male", n = { x = 384 }, c = { x = { { 0.00, "Назойливые твари, известные как трогги, вдруг полезли из заполненных лавой туннелей под Оргриммаром." }, { 7.94, "Магата по своей доброте душевной хотела договориться с этими тварями, но они набросились на её переговорщиков и перебили их." }, { 17.93, "Но такого обращения с тауренами она допустить не может, так что теперь для неё эти твари – враги Орды." }, { 26.23, "Она просит тебя разделаться с этими троггами, прежде чем они начнут угрожать Орде из-под земли." }, { 34.18, "Найди Огненную пропасть и уничтожь их всех!" } } }, t = { d = 19.3, g = 1, v = "tauren-male", n = { m = 172, f = 174 }, c = { m = { { 0.00, "Я рад, что ты серьёзно отнёсся к просьбе Магаты." }, { 4.11, "Спасибо тебе." }, { 5.40, "Теперь, когда троггов поубавилось, они уже не полезут так нагло на поверхность!" }, { 12.58, "Может, в будущем мы сумеем узнать, откуда взялись эти твари, и что им надо." } }, f = { { 0.00, "Я рад, что ты серьёзно отнеслась к просьбе Магаты." }, { 4.11, "Спасибо тебе." }, { 5.32, "Теперь, когда троггов поубавилось, они уже не полезут так нагло на поверхность!" }, { 12.09, "Может, в будущем мы сумеем узнать, откуда взялись эти твари, и что им надо." } } } } },
    [5724] = { d = 22.6, v = "narrator", n = { x = 249 }, c = { x = { { 0.00, "Под телом погибшего таурена вы находите сумку." }, { 3.54, "Убитый до сих пор крепко держит её – видимо, он пытался уберечь её во время нападения троггов." }, { 10.61, "Высвободив сумку из его крепкой хватки, вы закидываете её себе на плечо и готовитесь возвращаться наружу из туннелей, чтобы отправиться к Рахауро в Громовой Утёс." } } }, t = { d = 13.2, v = "tauren-male", n = { x = 117 }, c = { x = { { 0.00, "Прекрасно." }, { 0.99, "Благодарю тебя." }, { 2.47, "Магата сказала мне, что если ты найдёшь её сородича, то я должен отдать тебе вот это." }, { 10.23, "Прошу, прими в знак благодарности." } } } } },
    [5725] = { d = 31.7, v = "named/2425", n = { x = 326 }, c = { x = { { 0.00, "Тебе хорошо известно, что в Легионе принято всячески одаривать идейных последователей." }, { 6.95, "Некоторым из этих даров лучше бы оказаться в руках у Тёмной Госпожи, чем у... простецов." }, { 13.96, "Например, в пещерах под Оргриммаром скрывается секта Совета Теней, известная как \"Огненный Клинок\"." }, { 21.92, "Госпожа сообщила, что они получили две могущественные книги заклинаний – она хотела бы \"позаимствовать\" их." }, { 30.46, "Выполни её волю." } } }, t = { d = 21.9, g = 1, v = "named/2425", n = { m = 207, f = 208 }, c = { m = { { 0.00, "Молодец, герой." }, { 1.38, "Ты оказал Тёмной Госпоже хорошую услугу." }, { 4.85, "Её подданным пригодятся твои упорство и честолюбие." }, { 9.23, "Заходи ко мне в будущем." }, { 11.31, "Быть может, я отправлю тебя на новые подвиги, которые помогут Тёмной Госпоже свергнуть Короля-лича и освободить рабов Плети." } }, f = { { 0.00, "Молодец, героиня." }, { 1.53, "Ты оказала Тёмной Госпоже хорошую услугу." }, { 5.04, "Её подданным пригодятся твои упорство и честолюбие." }, { 9.40, "Заходи ко мне в будущем." }, { 11.46, "Быть может, я отправлю тебя на новые подвиги, которые помогут Тёмной Госпоже свергнуть Короля-лича и освободить рабов Плети." } } } } },
    [5726] = { d = 48.5, g = 1, v = "named/thrall", n = { m = 476, f = 480 }, c = { m = { { 0.00, "Чего я не потерплю, так это предательства среди своих." }, { 4.53, "Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползётся ещё сильнее." }, { 19.22, "Но ты, юный искатель приключений, можешь проникнуть туда, куда моим агентам ходу нет." }, { 26.35, "Ты можешь узнать правду... можешь обнаружить настоящего главу заговора!" }, { 32.29, "Если у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников клана Пылающего Клинка лейтенантский знак отличия и принеси его мне." } }, f = { { 0.00, "Чего я не потерплю, так это предательства среди своих." }, { 4.62, "Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползётся ещё сильнее." }, { 19.62, "Но ты, юная искательница приключений, можешь проникнуть туда, куда моим агентам ходу нет." }, { 27.20, "Ты можешь узнать правду... можешь обнаружить настоящего главу заговора!" }, { 33.26, "Если у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников клана Пылающего Клинка лейтенантский знак отличия и принеси его мне." } } }, t = { d = 40.6, v = "named/thrall", n = { x = 403 }, c = { x = { { 0.00, "Молодец!" }, { 0.73, "Слава духам!" }, { 1.81, "Быть может, именно ты – тот, кому суждено избавить меня от самых серьёзных моих опасений!" }, { 9.00, "Ну кто бы мог подумать, что столь юное существо, как ты, сумеет достойно защитить наше дело?" }, { 16.33, "Ты мне напоминаешь меня самого в молодости..." }, { 19.96, "Я позабочусь о том, чтобы тебя достойно вознаградили за труды – если мы оба переживём грядущую бурю." }, { 28.02, "Ладно, сейчас не время рассыпаться в похвалах." }, { 31.79, "То, что тебе уже удалось совершить, – пустяки в сравнении с тем, что ещё предстоит..." }, { 38.54, "Но начало положено хорошее." } } } } },
    [5727] = { d = 40.6, g = 1, v = "named/thrall", n = { m = 420, f = 418 }, c = { m = { { 0.00, "Ну-ка, посмотрим, стоил ли принесённый тобой знак отличия таких усилий." }, { 5.56, "В городе живёт чернокнижник, который уверен, будто я ему полностью доверяю." }, { 11.48, "Он и не подозревает, что мне известно о его предательстве." }, { 15.92, "На самом деле он – предводитель Пылающего Клинка..." }, { 19.93, "Однако не торопись вступать с ним в бой." }, { 23.03, "Он нам ещё нужен, мы можем использовать его, чтобы навредить нашим врагам." }, { 28.88, "Отнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за одного из своих." }, { 38.60, "А потом возвращайся ко мне." } }, f = { { 0.00, "Ну-ка, посмотрим, стоил ли принесённый тобой знак отличия таких усилий." }, { 5.53, "В городе живёт чернокнижник, который уверен, будто я ему полностью доверяю." }, { 11.41, "Он и не подозревает, что мне известно о его предательстве." }, { 15.82, "На самом деле он – предводитель Пылающего Клинка..." }, { 19.81, "Однако не торопись вступать с ним в бой." }, { 22.88, "Он нам ещё нужен, мы можем использовать его, чтобы навредить нашим врагам." }, { 28.69, "Отнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за одну из своих." }, { 38.21, "А потом возвращайся ко мне." } } }, t = { d = 25.9, g = 1, v = "named/thrall", n = { x = 242 }, c = { m = { { 0.00, "Великолепно, герой!" }, { 1.70, "Просто великолепно!" }, { 3.40, "Твоё сегодняшнее деяние – всего лишь первый шаг к куда более серьёзным делам." }, { 9.98, "Возможно, это поможет нам уничтожить Совет Теней раз и навсегда." }, { 15.55, "Перескажи мне всё, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь." } }, f = { { 0.00, "Великолепно, героиня!" }, { 1.83, "Просто великолепно!" }, { 3.51, "Твоё сегодняшнее деяние – всего лишь первый шаг к куда более серьёзным делам." }, { 9.98, "Возможно, это поможет нам уничтожить Совет Теней раз и навсегда." }, { 15.47, "Перескажи мне всё, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь." } } } } },
    [5728] = { d = 40.3, g = 1, v = "named/thrall", n = { m = 376, f = 375 }, c = { m = { { 0.00, "Хм, предводители клана Огненного Клинка..." }, { 3.59, "Это серьёзно." }, { 4.73, "Если Нииру ими дорожит, значит, именно их и нужно ликвидировать." }, { 10.31, "Этот сатир..." }, { 11.53, "Баззалан, и тот, второй, которого упоминал Нииру, – он кто, чернокнижник? – их следует убить." }, { 19.31, "Возвращайся в расселину Теней и проникни в Огненную пропасть." }, { 24.50, "Разыщи этих предводителей клана Огненного Клинка и убей их." }, { 29.62, "Но будь осторожен, чтобы Нииру не узнал, что это твоих рук дело." }, { 35.11, "Пусть по-прежнему считает тебя одним из братьев по оружию." } }, f = { { 0.00, "Хм, предводители клана Огненного Клинка..." }, { 3.64, "Это серьёзно." }, { 4.80, "Если Нииру ими дорожит, значит, именно их и нужно ликвидировать." }, { 10.45, "Этот сатир..." }, { 11.69, "Баззалан, и тот, второй, которого упоминал Нииру, – он кто, чернокнижник? – их следует убить." }, { 19.58, "Возвращайся в расселину Теней и проникни в Огненную пропасть." }, { 24.84, "Разыщи этих предводителей клана Огненного Клинка и убей их." }, { 30.03, "Но будь осторожна, чтобы Нииру не узнал, что это твоих рук дело." }, { 35.60, "Пусть по-прежнему считает тебя одной из сестёр по оружию." } } }, t = { d = 25.3, g = 1, v = "named/thrall", n = { m = 247, f = 248 }, c = { m = { { 0.00, "Я рад, что ты вернулся." }, { 1.85, "Преданные мне агенты уже сообщили, что в пещерах под Оргриммаром воцарился хаос – теперь, когда их предводители убиты." }, { 11.53, "Мне даже докладывали, что Нииру более чем взбудоражен." }, { 15.97, "Похоже, мы пробили брешь в его броне." }, { 19.08, "Не могу не признать, что меня это радует..." }, { 22.70, "Пусть небольшая, но всё же победа." } }, f = { { 0.00, "Я рад, что ты вернулась." }, { 1.90, "Преданные мне агенты уже сообщили, что в пещерах под Оргриммаром воцарился хаос – теперь, когда их предводители убиты." }, { 11.46, "Мне даже докладывали, что Нииру более чем взбудоражен." }, { 15.85, "Похоже, мы пробили брешь в его броне." }, { 18.91, "Не могу не признать, что меня это радует..." }, { 22.49, "Пусть небольшая, но всё же победа." } } } } },
    [5729] = { d = 35.4, v = "named/thrall", n = { x = 368 }, c = { x = { { 0.00, "Думаю, теперь тебе следует попытаться войти в число приближённых Нииру." }, { 5.67, "Если он действительно так взбудоражен, как мне доносят, мы убьём сразу двух зайцев." }, { 12.05, "Во-первых, тебе, возможно, удастся разузнать побольше о Совете или, по крайней мере, о Пылающем Клинке, и, во-вторых, он, возможно, начнёт доверять тебе настолько, что попросит ему помогать." }, { 27.01, "Ему сейчас отчаянно не хватает помощников." }, { 30.41, "Возвращайся в Расселину и поговори с ним, но не особо навязывайся." } } }, t = { d = 30.9, g = 1, v = "orc-male", n = { x = 276 }, c = { m = { { 0.00, "Ну в чём дело?!" }, { 1.32, "Ах, это ты, герой..." }, { 3.09, "Прошу прощения." }, { 4.49, "Я зол, как бешеный кодо..." }, { 6.73, "Но, возможно, я сам во всём виноват." }, { 9.75, "Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами." }, { 18.26, "Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов." }, { 25.07, "Они оба убиты." }, { 26.46, "Как это не вовремя!" }, { 28.16, "Но тут уж ничего не поделаешь." } }, f = { { 0.00, "Ну в чём дело?!" }, { 1.32, "Ах, это ты, героиня..." }, { 3.26, "Прошу прощения." }, { 4.66, "Я зол, как бешеный кодо..." }, { 6.91, "Но, возможно, я сам во всём виноват." }, { 9.93, "Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами." }, { 18.47, "Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов." }, { 25.29, "Они оба убиты." }, { 26.69, "Как это не вовремя!" }, { 28.40, "Но тут уж ничего не поделаешь." } } } } },
    [5730] = { d = 33.4, g = 1, v = "orc-male", n = { m = 340, f = 340 }, c = { m = { { 0.00, "Теперь ты один из моих лейтенантов!" }, { 2.81, "Готовься, герой." }, { 4.14, "Скоро я призову тебя." }, { 5.90, "Можно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать." }, { 15.81, "Я сделаю всё, что смогу, чтобы свести к минимуму потери здесь, в Огненной пропасти." }, { 22.27, "А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы." }, { 30.70, "Возвращайся ко мне как можно скорее." } }, f = { { 0.00, "Теперь ты одна из моих лейтенантов!" }, { 2.71, "Готовься, героиня." }, { 4.13, "Скоро я призову тебя." }, { 5.83, "Можно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать." }, { 15.39, "Я сделаю всё, что смогу, чтобы свести к минимуму потери здесь, в Огненной пропасти." }, { 21.62, "А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы." }, { 29.76, "Возвращайся ко мне как можно скорее." } } }, t = { d = 20.8, v = "named/thrall", n = { x = 180 }, c = { x = { { 0.00, "Ясеневый лес?" }, { 1.25, "Хм." }, { 1.58, "Впервые слышу о присутствии Совета или Пылающего Клинка в Ясеневом лесу." }, { 8.40, "Я поручу своим агентам это проверить." }, { 11.98, "А ты молодец." }, { 13.23, "Пока отдыхай, занимайся другими делами." }, { 16.97, "Скоро я призову тебя снова." }, { 19.63, "Лок-тар Огар!" } } } } },
    [5741] = { d = 29.2, v = "human-male", n = { x = 347 }, c = { x = { { 0.00, "Говорят, что клан Пылающего Клинка, обосновавшийся на востоке в Крепости Громового Топора, заполучил Скипетр Света, добыв его у наг." }, { 9.13, "Легенда гласит, что этот скипетр обладает властью погружать целые города в пучины моря." }, { 15.33, "Мы не можем позволить, чтобы такая сила оставалась в их руках." }, { 19.71, "Твой долг – вырвать скипетр из недостойных рук!" }, { 22.90, "Сейчас он у ясновидца из клана Пылающего Клинка на одной из башен крепости Громового Топора." } } }, t = { d = 9.7, g = 1, v = "human-male", n = { m = 81, f = 82 }, c = { m = { { 0.00, "Неуловимый Скипетр Света!.." }, { 2.42, "Добыв его, ты избавил мир от великой угрозы." }, { 6.32, "Прекрасно, герой, просто прекрасно!.." } }, f = { { 0.00, "Неуловимый Скипетр Света!.." }, { 2.42, "Добыв его, ты избавила мир от великой угрозы." }, { 6.40, "Прекрасно, героиня, просто прекрасно!.." } } } } },
    [5742] = { d = 5.9, g = 1, v = "human-male", n = { m = 63, f = 64 }, c = { m = { { 0.00, "Ты славно поработал, друг мой." }, { 2.33, "Отдохни, а я наконец представлюсь, как подобает." } }, f = { { 0.00, "Ты славно поработала, подруга." }, { 2.31, "Отдохни, а я наконец представлюсь, как подобает." } } }, t = { d = 5.2, g = 1, v = "human-male", n = { m = 49, f = 50 }, c = { m = { { 0.00, "Вернуть моего сына на путь истинный будет нелегко." }, { 4.36, "Ты готов?" } }, f = { { 0.00, "Вернуть моего сына на путь истинный будет нелегко." }, { 4.43, "Ты готова?" } } } } },
    [5761] = { d = 41.1, v = "orc-male", n = { x = 401 }, c = { x = { { 0.00, "Главная задача, которую поручил мне наш великий вождь, – это извести тех тварей, которые повинны в том, что в великий город нашего владыки проникают демоны." }, { 13.05, "Клан Пылающего Клинка – главная, но не единственная угроза." }, { 17.96, "Есть ещё и Огненный Клинок, клан, который обосновался в Огненной пропасти и втайне смущает умы простых представителей Орды." }, { 28.22, "Чтобы их остановить, нужно убить их предводителя, стража Скверны по имени Тарагаман Ненасытный." }, { 36.22, "Убей его." }, { 37.12, "Я уверен, Вождь будет рад получить его сердце..." } } }, t = { d = 18.3, g = 1, v = "orc-male", n = { x = 164 }, c = { m = { { 0.00, "Ага!" }, { 0.46, "Тебе это удалось!" }, { 2.08, "Тралл, конечно, будет в восторге." }, { 4.93, "Я позабочусь о том, чтобы это сердце попало по назначению." }, { 9.93, "Ну, а ты можешь отпраздновать свою победу." }, { 13.55, "Я сообщу Траллу о твоём успехе." }, { 16.24, "Спасибо за помощь, герой." } }, f = { { 0.00, "Ага!" }, { 0.46, "Тебе это удалось!" }, { 2.06, "Тралл, конечно, будет в восторге." }, { 4.89, "Я позабочусь о том, чтобы это сердце попало по назначению." }, { 9.85, "Ну, а ты можешь отпраздновать свою победу." }, { 13.44, "Я сообщу Траллу о твоём успехе." }, { 16.11, "Спасибо за помощь, героиня." } } } } },
    [5762] = { d = 33.5, v = "dwarf-male", n = { x = 383 }, c = { x = { { 0.00, "У меня тут посылка для одного старого покупателя, дворфа по имени Хеминг Эрнестуэй." }, { 5.87, "Посылка шла очень долго, и Хеминг уехал, не дождавшись её." }, { 9.98, "Говорят, что теперь он где-то в Тернистой долине, охотится там на зверей." }, { 15.09, "Перед отъездом он оставил мне немного денег, чтобы я переслал ему посылку." }, { 20.40, "Он очень богатый дворф, а с такими полезно водить дружбу, правда?" }, { 25.01, "Так что... не желаешь ли доставить Хемингу эту посылку?" }, { 28.86, "Говорят, он разбил лагерь в Тернистой долине, к северу от Гром'гола." } } }, t = { d = 17.8, v = "dwarf-male", n = { x = 195 }, c = { x = { { 0.00, "Отлично, посылочка от Углебрада!" }, { 2.46, "Спасибо!" }, { 3.15, "В этом ящике боеприпасы особого калибра, и в джунглях они нам очень пригодятся!" }, { 9.23, "Вот ваша плата, и расскажите мне, как там поживает старина Углебрад?" }, { 14.36, "Наверняка опять замышляет какую-нибудь пакость?" } } } } },
    [5763] = { d = 41.7, v = "tauren-male#68", n = { x = 394 }, c = { x = { { 0.00, "Давным-давно пришёл в эти земли дворф." }, { 3.19, "Звали его Хеминг, и он хотел поохотиться на крупного зверя." }, { 8.28, "С ружьём он умел обращаться просто великолепно, и много дней мы охотились с ним вместе, забыв даже о вражде, разделявшей наши народы…" }, { 19.44, "Когда он уходил в Тернистую долину, я поклялся, что, когда бы он ни вернулся, я встречу его как дорогого гостя." }, { 28.78, "И вот это время пришло." }, { 30.83, "Отнеси этот рог кодо в подарок Хемингу." }, { 34.24, "Он поймёт, что это от меня." }, { 36.52, "Ты найдёшь его в Тернистой долине, к северу от лагеря Гром'гол." } } }, t = { d = 23.4, v = "dwarf-male", n = { x = 250 }, c = { x = { { 0.00, "О, этот рог принадлежит таурену Руну Буйногривому!" }, { 3.83, "Отец часто рассказывал о том, как славно они вместе охотились в Пустошах." }, { 9.43, "Значит, Рун приглашает меня на охоту, да?" }, { 12.57, "У нас сейчас дел по горло, но я всё равно благодарен тебе за добрую весть." }, { 18.11, "Возможно, следующая моя экспедиция будет в Пустоши, в земли кентавров." } } } } },
    [5781] = { d = 34.2, v = "human-male", n = { x = 409 }, c = { x = { { 0.00, "Чтобы помочь Таэлану вернуться на путь истинный, мы должны найти то, что напомнит ему о прошлом." }, { 6.54, "Один из таких предметов – игрушка, которую я подарил ему на семилетие." }, { 11.37, "Он очень дорожил этим маленьким боевым молотом, уменьшенной копией моего собственного оружия." }, { 17.79, "Когда меня изгнали за предательство, его мать сказала сыну, что я погиб." }, { 22.75, "Его отвели к моей пустой могиле в Крипте, и там он похоронил свой молот вместе со всеми воспоминаниями обо мне." }, { 30.33, "Прошу тебя, отправляйся в Крипту и принеси молот Таэлана." } } }, t = { d = 8.5, v = "human-male", n = { x = 84 }, c = { x = { { 0.00, "*Тирион с трудом сдерживает слёзы.*" }, { 3.04, "Сама судьба свела нас вместе." }, { 5.51, "Да благословят тебя небеса за доброту." } } } } },
    [5801] = { d = 36.6, v = "goblin-male#110", n = { x = 417 }, c = { x = { { 0.00, "Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла." }, { 6.52, "Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу." }, { 11.87, "К западу отсюда, в Кратере Ун'Горо, находится Вулкан Огненного Венца – действующий вулкан." }, { 18.38, "Лава из его жерла сплавит торий и кость воедино." }, { 21.93, "Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава." }, { 31.16, "Вот и всё, чем я могу тебе помочь." }, { 33.61, "Как доделать ключ тебе подскажет Арбингтон." } } }, t = { d = 25.8, v = "human-male", n = { x = 289 }, c = { x = { { 0.00, "Недёшево обошлась тебе эта отмычка, а?" }, { 2.82, "И всё же работа над ней не закончена; пришло время завершающего этапа – а это самое сложное." }, { 9.51, "Тебе придётся выступить против того самого врага, что ждал нас в Андорале..." }, { 15.03, "Злобной твари, которая правит бал в стенах разрушенного города." }, { 19.69, "Я говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети." } } } } },
    [5802] = { d = 35.6, v = "goblin-male#110", n = { x = 414 }, c = { x = { { 0.00, "Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла." }, { 6.38, "Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу." }, { 11.62, "К западу отсюда, в Кратере Ун'Горо, находится Вулкан Огненного Венца – действующий вулкан." }, { 18.00, "Лава из его жерла сплавит торий и кость воедино." }, { 21.47, "Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава." }, { 30.50, "Вот и всё, чем я могу тебе помочь." }, { 32.90, "Как доделать ключ тебе подскажет Дитерс." } } }, t = { d = 32.3, v = "scourge-male#82", n = { x = 289 }, c = { x = { { 0.00, "Недёшево обошлась тебе эта отмычка, а?" }, { 3.53, "И всё же работа над ней не закончена; пришло время завершающего этапа – а это самое сложное." }, { 11.89, "Тебе придётся выступить против того самого врага, что ждал нас в Андорале..." }, { 18.78, "Злобной твари, которая правит бал в стенах разрушенного города." }, { 24.61, "Я говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети." } } } } },
    [5803] = { d = 29.4, v = "human-male", n = { x = 351 }, c = { x = { { 0.00, "Араж Призыватель правит Андоралом из самого сердца разрушенного города." }, { 4.96, "Мы знаем, что он был главой Некроситета, пока не захватил целый город." }, { 9.80, "Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа." }, { 17.92, "Проберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую." }, { 25.30, "Убив мерзавца, забери скарабея!" }, { 27.54, "Ключ от Некроситета ждёт тебя!" } } }, t = { d = 25.6, g = 1, v = "human-male", n = { m = 279, f = 280 }, c = { m = { { 0.00, "А, вот она!" }, { 0.87, "Я... поражён твоей отвагой и хитростью." }, { 3.74, "У меня в голове не укладывается, на что ты готов пойти ради победы над силами тьмы." }, { 9.90, "Позволь и мне сыграть свою небольшую роль в твоём подвиге." }, { 14.18, "Я приготовил особый раствор, который позволит мне закрепить скарабея в верхней части ключа." }, { 21.00, "Его сила отомкнёт двери Некроситета." }, { 23.74, "Ну вот, остался пустячок..." } }, f = { { 0.00, "А, вот она!" }, { 0.85, "Я... поражён твоей отвагой и хитростью." }, { 3.65, "У меня в голове не укладывается, на что ты готова пойти ради победы над силами тьмы." }, { 9.72, "Позволь и мне сыграть свою небольшую роль в твоём подвиге." }, { 13.90, "Я приготовил особый раствор, который позволит мне закрепить скарабея в верхней части ключа." }, { 20.55, "Его сила отомкнёт двери Некроситета." }, { 23.23, "Ну вот, остался пустячок..." } } } } },
    [5804] = { d = 35.9, v = "scourge-male#82", n = { x = 351 }, c = { x = { { 0.00, "Араж Призыватель правит Андоралом из самого сердца разрушенного города." }, { 6.05, "Мы знаем, что он был главой Некроситета, пока не захватил целый город." }, { 11.95, "Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа." }, { 21.86, "Проберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую." }, { 30.86, "Убив мерзавца, забери скарабея!" }, { 33.58, "Ключ от Некроситета ждёт тебя!" } } }, t = { d = 31.0, g = 1, v = "scourge-male#82", n = { m = 269, f = 270 }, c = { m = { { 0.00, "А, вот она!" }, { 1.06, "Я... поражён твоей отвагой и хитростью." }, { 4.58, "У меня в голове не укладывается, на что ты готов пойти ради победы." }, { 10.71, "Позволь и мне сыграть свою небольшую роль в твоём подвиге." }, { 15.94, "Я приготовил особый раствор, который позволит мне закрепить скарабея в верхней части ключа." }, { 24.27, "Его сила отомкнёт двери Некроситета." }, { 27.62, "Много времени это не займёт..." } }, f = { { 0.00, "А, вот она!" }, { 1.08, "Я... поражён твоей отвагой и хитростью." }, { 4.67, "У меня в голове не укладывается, на что ты готова пойти ради победы." }, { 11.01, "Позволь и мне сыграть свою небольшую роль в твоём подвиге." }, { 16.35, "Я приготовил особый раствор, который позволит мне закрепить скарабея в верхней части ключа." }, { 24.87, "Его сила отомкнёт двери Некроситета." }, { 28.29, "Много времени это не займёт..." } } } } },
    [5805] = { d = 29.2, v = "narrator", n = { x = 323 }, c = { x = { { 0.00, "Добро пожаловать в \"Ворлд оф Варкрафт\"!" }, { 2.98, "В знак особой благодарности за приобретение коллекционного издания \"Ворлд оф Варкрафт\" примите этот подарочный сертификат и передайте его Мериссе Стилвелл в Златоземье." }, { 16.01, "Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе." }, { 24.04, "Ещё раз благодарим вас и желаем приятного пребывания в \"Ворлд оф Варкрафт\"!" } } }, t = { d = 7.8, v = "human-female", n = { x = 67 }, c = { x = { { 0.00, "Ну, теперь приветствую тебя в мире Азерота." }, { 4.09, "Иди вперёд, к славе, наградам и почестям!" } } } } },
    [5821] = { d = 43.3, g = 1, v = "goblin-male#110", n = { x = 496 }, c = { m = { { 0.00, "Обычно мы с Риггером проводим кодо мимо поселения кентавров из племени Колкар." }, { 5.53, "Боевые барабаны кентавров слышно издалека, так что, едва заслышав их, мы останавливаемся, чтобы переждать опасность." }, { 13.57, "Мёртвый торговец, знаешь ли, плохой торговец!" }, { 16.71, "Вот что я тебе скажу, герой: если ты будешь охранять нас по дороге мимо деревни Колкар, мы тебе за это хорошо заплатим." }, { 25.13, "Расстояние-то небольшое, да и делать почти ничего не придётся – только проследить за тем, чтобы караван был цел." }, { 32.79, "А награду ты получишь, не сомневайся: Смид Заржавень тебе сполна заплатит, мы с ним обделываем кое-какие делишки." }, { 40.65, "Он живёт чуть дальше по дороге." } }, f = { { 0.00, "Обычно мы с Риггером проводим кодо мимо поселения кентавров из племени Колкар." }, { 5.59, "Боевые барабаны кентавров слышно издалека, так что, едва заслышав их, мы останавливаемся, чтобы переждать опасность." }, { 13.73, "Мёртвый торговец, знаешь ли, плохой торговец!" }, { 16.91, "Вот что я тебе скажу, героиня: если ты будешь охранять нас по дороге мимо деревни Колкар, мы тебе за это хорошо заплатим." }, { 25.56, "Расстояние-то небольшое, да и делать почти ничего не придётся – только проследить за тем, чтобы караван был цел." }, { 33.31, "А награду ты получишь, не сомневайся: Смид Заржавень тебе сполна заплатит, мы с ним обделываем кое-какие делишки." }, { 41.26, "Он живёт чуть дальше по дороге." } } }, t = { d = 23.6, g = 1, v = "goblin-male", n = { x = 250 }, c = { m = { { 0.00, "Знаешь ли, мне не кажется такой уж хорошей идеей платить таким, как ты, за охрану каравана Гизлтона, герой." }, { 7.76, "Будь я повыше ростом, взялся бы за работу по совместительству." }, { 12.20, "Только представь: сижу это я на кодо в седле, а в руках у меня – самая большая в мире пушка, и я готов показать этим проклятым кентаврам, кто тут хозяин..." }, { 23.55, "А?" } }, f = { { 0.0