    [5845] = { d = 34.6, v = "human-male", n = { x = 384 }, c = { x = { { 0.00, "Со смертью Утера орден Серебряной Длани утратил боевой дух." }, { 4.80, "Мой мальчик держался до последнего." }, { 7.40, "Но, отступая в разорённую деревушку Северного дола, он принял окончательное решение." }, { 13.55, "Выжил ли кто из ордена, подумал он, да и какая разница?" }, { 17.62, "С этой мыслью Таэлан бросил знамя Серебряной Длани и отрёкся от всего, что прежде было ему дорого." }, { 25.03, "Его честь осталась на обагрённой кровью земле Северного дола." }, { 29.58, "Отправляйся в Северный дол и принеси мне этот символ утраченной чести." } } }, t = { d = 12.5, g = 1, v = "human-male", n = { m = 128, f = 130 }, c = { m = { { 0.00, "Даже в столь плачевном состоянии оно так же прекрасно, как и в тот день, когда я принёс присягу, глядя на него." }, { 8.17, "Возможно, вместе с этим знаменем ты спас и мою душу." } }, f = { { 0.00, "Даже в столь плачевном состоянии оно так же прекрасно, как и в тот день, когда я принёс присягу, глядя на него." }, { 8.35, "Возможно, вместе с этим знаменем ты спасла и мою душу." } } } } },
    [5846] = { d = 33.8, v = "human-male", n = { x = 387 }, c = { x = { { 0.00, "Когда Таэлан был маленьким, мы нередко ездили в Каэр Дарроу." }, { 4.39, "В последний раз художница по имени Ренфри изобразила всю нашу семью на берегу." }, { 10.01, "Это лучшее моё воспоминание о Таэлане и Карандре." }, { 13.56, "Именно тогда, стоя рядом с женой и держа на руках сына, я чувствовал глубокую связь с собственной семьёй, которую мне не дано было почувствовать вновь." }, { 24.35, "Если эта картина всё ещё существует, найди её." }, { 27.70, "Отправляйся на разорённый остров Каэр Дарроу и выясни, уцелел ли художник или картина." } } }, t = { d = 25.0, v = "human-female", n = { x = 287 }, c = { x = { { 0.00, "Как я могла забыть?" }, { 1.40, "Многие духи этого острова обречены хранить последние счастливые воспоминания перед трагической гибелью." }, { 8.77, "Проклятье это коснулось и меня – я одна из немногих, кто помнит всё…" }, { 13.60, "Быть может, именно эта вещь, которая тебя интересует, держит меня прикованной к этим руинам." }, { 20.21, "Я расскажу тебе всё, что знаю, в надежде, что это дарует мне свободу." } } } } },
    [5847] = { d = 28.3, v = "narrator", n = { x = 319 }, c = { x = { { 0.00, "Добро пожаловать в Ворлд оф Варкрафт!" }, { 2.82, "В качестве особой благодарности за покупку коллекционного издания Ворлд оф Варкрафт примите этот подарочный сертификат и передайте его Клэр Вилловер в Брилле." }, { 14.78, "Вас ждёт подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе." }, { 22.34, "Ещё раз благодарим вас и желаем приятного времяпрепровождения в Ворлд оф Варкрафт!" } } }, t = { d = 11.0, v = "scourge-female#80", n = { x = 105 }, c = { x = { { 0.00, "Вы действительно незаурядная личность." }, { 3.43, "Мы приветствуем вас в мире Азерота и предлагаем вам один из этих уникальных подарков!" } } } } },
    [5848] = { d = 28.7, v = "human-female", n = { x = 314 }, c = { x = { { 0.00, "На стене моей мастерской..." }, { 2.03, "В казармах ордена... долгие годы висела картина." }, { 5.63, "После суда над Тирионом я знала, что не смогу держать её на виду." }, { 10.41, "Я спрятала её так, чтобы никто не нашёл." }, { 13.29, "Отправляйся в Стратхольм и проберись в то, что ныне зовётся Бастионом Алого ордена." }, { 19.24, "Найди там картину с двумя лунами." }, { 21.73, "Сними лишнюю краску и увидишь мой шедевр – \"Символ семейной любви\"." }, { 26.71, "Да направляет Свет твою руку." } } }, t = { d = 5.8, v = "human-male", n = { x = 58 }, c = { x = { { 0.00, "*При виде картины Тирион хватается за сердце.*" }, { 3.89, "*Он начинает всхлипывать.*" } } } } },
    [5861] = { d = 32.4, g = 1, v = "human-male", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Ты сделал всё, о чём я тебя просил." }, { 2.56, "Остался один, последний шаг на пути к спасению." }, { 6.04, "Отнеси все собранные тобой предметы Таэлану." }, { 9.32, "К сожалению, Таэлан и его рыцари Алого ордена нападут на тебя, едва завидев." }, { 15.03, "Есть только один способ доставить моё сообщение – приняв обличье врага." }, { 20.28, "На юге отсюда находится гробница Утера." }, { 23.67, "Там живёт моя старая добрая подруга, Миранда." }, { 27.01, "Найди её, покажи все собранные тобой предметы, и она тебе поможет." } }, f = { { 0.00, "Ты сделала всё, о чём я тебя просил." }, { 2.67, "Остался один, последний шаг на пути к спасению." }, { 6.22, "Отнеси все собранные тобой предметы Таэлану." }, { 9.56, "К сожалению, Таэлан и его рыцари Алого ордена нападут на тебя, едва завидев." }, { 15.37, "Есть только один способ доставить моё сообщение – приняв обличье врага." }, { 20.72, "На юге отсюда находится гробница Утера." }, { 24.09, "Там живёт моя старая добрая подруга, Миранда." }, { 27.49, "Найди её, покажи все собранные тобой предметы, и она тебе поможет." } } }, t = { d = 22.2, g = 1, v = "gnome-female", n = { m = 250, f = 251 }, c = { m = { { 0.00, "Я была самой доверенной советницей Тириона, когда он носил титул лорда Марденхольдского." }, { 6.68, "Я открыто отреклась от вердикта ордена Серебряной Длани и была изгнана за неповиновение." }, { 13.29, "На долю Тириона выпало много боли и разочарований." }, { 17.14, "Готов ли ты исправить несправедливости, обрушившиеся на Фордрингов?" } }, f = { { 0.00, "Я была самой доверенной советницей Тириона, когда он носил титул лорда Марденхольдского." }, { 6.73, "Я открыто отреклась от вердикта ордена Серебряной Длани и была изгнана за неповиновение." }, { 13.40, "На долю Тириона выпало много боли и разочарований." }, { 17.28, "Готова ли ты исправить несправедливости, обрушившиеся на Фордрингов?" } } } } },
    [5862] = { d = 27.0, g = 1, v = "gnome-female", n = { m = 284, f = 285 }, c = { m = { { 0.00, "Я, как говорится, иллюзионистка." }, { 2.48, "Хотя я могу создать иллюзию, благодаря которой ты проберёшься в Дольный Очаг, помни – сила моя не безгранична." }, { 11.21, "Если ты забредёшь слишком далеко, иллюзия рассеется." }, { 15.33, "Заклинание требует от меня значительного количества сил и сосредоточения, и я не слишком долго смогу поддерживать его." }, { 24.56, "Когда будешь готов – обращайся." } }, f = { { 0.00, "Я, как говорится, иллюзионистка." }, { 2.48, "Хотя я могу создать иллюзию, благодаря которой ты проберёшься в Дольный Очаг, помни – сила моя не безгранична." }, { 11.18, "Если ты забредёшь слишком далеко, иллюзия рассеется." }, { 15.29, "Заклинание требует от меня значительного количества сил и сосредоточения, и я не слишком долго смогу поддерживать его." }, { 24.49, "Когда будешь готова – обращайся." } } }, t = { d = 20.8, g = 1, v = "human-male", n = { m = 194, f = 195 }, c = { m = { { 0.00, "Что это, солдат?" }, { 1.92, "*Таэлан открывает коробку и начинает рассматривать содержимое.*" }, { 6.72, "Этого..." }, { 7.53, "Этого не может быть." }, { 9.40, "Но всё, что ты мне показал…" }, { 11.68, "*Таэлан опускается на колено, сердце у него колотится.*" }, { 16.32, "*На этот город того и гляди выплеснется ярость веков.*" } }, f = { { 0.00, "Что это, солдат?" }, { 1.84, "*Таэлан открывает коробку и начинает рассматривать содержимое.*" }, { 6.56, "Этого..." }, { 7.32, "Этого не может быть." }, { 9.07, "Но всё, что ты мне показала…" }, { 11.28, "*Таэлан опускается на колено, сердце у него колотится.*" }, { 15.92, "*На этот город того и гляди выплеснется ярость веков.*" } } } } },
    [5863] = { d = 29.9, v = "gnome-female#39", n = { x = 338 }, c = { x = { { 0.00, "Совсем недавно в Танарисе появились огры-кочевники." }, { 3.86, "Они захватили большой участок пустыни к югу отсюда и построили целую крепость." }, { 9.78, "Племена поменьше бродят по пустыне, захватывая руины тролльских городов." }, { 15.17, "Поселение Песчаного Молота должно пасть!" }, { 18.16, "Не позволим же ограм превратиться в страшную силу." }, { 21.88, "Их главаря зовут Гор'марок Опустошитель." }, { 24.88, "Мне кажется, что если его устранить, это станет началом конца огров." } } }, t = { d = 5.2, g = 1, v = "gnome-female#39", n = { m = 46, f = 47 }, c = { m = { { 0.00, "Я так рада, что ты выполнил мою просьбу!" }, { 3.66, "Спасибо за помощь!" } }, f = { { 0.00, "Я так рада, что ты выполнила мою просьбу!" }, { 3.57, "Спасибо за помощь!" } } } } },
    [5881] = { d = 35.6, v = "tauren-male", n = { x = 336 }, c = { x = { { 0.00, "Орда не даёт нам растерять силы, и это правильно!" }, { 4.22, "С самой Великой Войны мы здесь, в Калимдоре, живём неплохо." }, { 9.21, "Я прошу тебя оказать мне услугу: один парень по имени Гриш Выносливый Гонец охраняет Великий подъёмник на юге Степей." }, { 19.26, "Передай ему это письмо: там говорится, что один из солдат запаса скоро придёт ему на смену, чтобы он мог навестить свою семью." }, { 30.16, "Гриш недавно просил об этом, и он будет рад услышать эти новости." } } }, t = { d = 11.8, v = "tauren-male", n = { x = 97 }, c = { x = { { 0.00, "Это хорошие новости; я слишком долго сижу здесь, охраняя этот кусок дерева." }, { 7.37, "Теперь я смогу побыть со своими родными..." }, { 11.49, "Ура!" } } } } },
    [5882] = { t = { d = 10.6, v = "nightelf-female", n = { x = 126 }, c = { x = { { 0.00, "Очень хорошо, вот тебе кенарийский бальзам." }, { 3.16, "Ищи в Осквернённом лесу поражённые растения!" }, { 6.26, "Когда найдёшь, исцеляй их при помощи моего целебного бальзама." } } } } },
    [5883] = { t = { d = 14.6, v = "nightelf-female", n = { x = 180 }, c = { x = { { 0.00, "Что же, прекрасно!" }, { 1.24, "Вот тебе кенарийский бальзам." }, { 3.29, "Если при разработках жил металлов в Осквернённом лесу найдёшь ещё порченого купороса, не забудь принести его мне!" }, { 10.93, "Чем больше найдёшь, тем больше бальзама я смогу сделать." } } } } },
    [5884] = { t = { d = 15.9, v = "nightelf-female", n = { x = 185 }, c = { x = { { 0.00, "Отличная работа – всё это после очищения пойдёт на исцеление Осквернённого леса." }, { 5.79, "Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес." }, { 12.05, "Исцеление этого края от порчи не терпит отлагательств!" } } } } },
    [5885] = { t = { d = 8.8, v = "nightelf-female", n = { x = 96 }, c = { x = { { 0.00, "То что нужно!" }, { 1.02, "Вот, бери этот бальзам для исцеления растений и лечи им Осквернённый лес от порчи!" }, { 7.17, "Мы не должны сдаваться!" } } } } },
    [5886] = { t = { d = 16.5, v = "nightelf-female", n = { x = 190 }, c = { x = { { 0.00, "Вот тебе кенарийский бальзам, и за него я прошу только одну порцию простой субстанции Пустоты." }, { 6.73, "Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала." }, { 13.13, "Если тебе понадобится ещё бальзам, ищи меня тут!" } } } } },
    [5887] = { t = { d = 12.2, v = "tauren-female", n = { x = 126 }, c = { x = { { 0.00, "Очень хорошо, вот тебе кенарийский бальзам." }, { 3.66, "Ищи в Осквернённом лесу поражённые растения!" }, { 7.24, "Когда найдёшь, исцеляй их при помощи моего целебного бальзама." } } } } },
    [5888] = { t = { d = 17.0, v = "tauren-female", n = { x = 180 }, c = { x = { { 0.00, "Что же, прекрасно!" }, { 1.44, "Вот тебе кенарийский бальзам." }, { 3.81, "Если при разработках жил металлов в Осквернённом лесу найдёшь ещё порченого купороса, не забудь принести его мне!" }, { 12.65, "Чем больше найдёшь, тем больше бальзама я смогу сделать." } } } } },
    [5889] = { t = { d = 18.0, v = "tauren-female", n = { x = 185 }, c = { x = { { 0.00, "Отличная работа – всё это после очищения пойдёт на исцеление Осквернённого леса." }, { 6.55, "Вот, возьми несколько порций кенарийского бальзама исцеления растений, и ступай в лес." }, { 13.62, "Исцеление этого края от порчи не терпит отлагательств!" } } } } },
    [5890] = { t = { d = 10.3, v = "tauren-female", n = { x = 96 }, c = { x = { { 0.00, "То что нужно!" }, { 1.20, "Вот, бери этот бальзам для исцеления растений и лечи им Осквернённый лес от порчи!" }, { 8.40, "Мы не должны сдаваться!" } } } } },
    [5891] = { t = { d = 20.4, v = "tauren-female", n = { x = 194 }, c = { x = { { 0.00, "Вот кенарийские растительные мази – за них мне нужна всего одна малая сущность пустоты." }, { 7.47, "Сущность – самое сильное средство, которое я могу использовать, чтобы, так сказать, перековать мечи на орала." }, { 16.86, "Если понадобится ещё мазь – ищи меня здесь!" } } } } },
    [5892] = { d = 21.3, v = "dwarf-male#100", n = { x = 256 }, c = { x = { { 0.00, "Пока не началась война, мы хранили припасы для Дун Болдара на Железном руднике." }, { 5.32, "Когда у нас были войска, чтобы охранять рудник, трогги не были такой уж большой проблемой, но сейчас мы сражаемся с Ордой и не в силах его удерживать." }, { 15.49, "Тем не менее, припасы с Железного рудника нам очень нужны." }, { 19.42, "Отправляйся туда и добудь их." } } }, t = { d = 5.0, v = "dwarf-male#100", n = { x = 42 }, c = { x = { { 0.00, "Отлично!" }, { 0.87, "Уж я найду применение этому добру." }, { 4.26, "Спасибо!" } } } } },
    [5893] = { d = 33.5, g = 1, v = "orc-male", n = { m = 355, f = 355 }, c = { m = { { 0.00, "Рудник Ледяного Зуба, к северу отсюда, был идеальным местом для хранения припасов." }, { 6.40, "Но сейчас, когда разгорелась война с Грозовой Вершиной, у нас не хватает солдат, чтобы его постоянно патрулировать и охранять." }, { 15.72, "Так что рудник постоянно переходит из рук в руки, – то к Альянсу, то к местным подземным жителям..." }, { 22.91, "Но припасы нам по-прежнему нужны!" }, { 25.08, "Ступай на рудник Ледяного Зуба и добудь их." }, { 29.37, "Будь осторожен – в этом месте то и дело возникают стычки." } }, f = { { 0.00, "Рудник Ледяного Зуба, к северу отсюда, был идеальным местом для хранения припасов." }, { 6.14, "Но сейчас, когда разгорелась война с Грозовой Вершиной, у нас не хватает солдат, чтобы его постоянно патрулировать и охранять." }, { 15.41, "Так что рудник постоянно переходит из рук в руки, – то к Альянсу, то к местным подземным жителям..." }, { 22.57, "Но припасы нам по-прежнему нужны!" }, { 24.69, "Ступай на рудник Ледяного Зуба и добудь их." }, { 28.93, "Будь осторожна – в этом месте то и дело возникают стычки." } } }, t = { d = 15.0, g = 1, v = "orc-male", n = { m = 144, f = 146 }, c = { m = { { 0.00, "А, вот они!" }, { 0.99, "Отличная работа!" }, { 2.43, "Припасы немного заплесневели – сказывается влажность воздуха в руднике – но всё равно сгодятся." }, { 10.40, "Спасибо тебе." }, { 11.62, "Ты помог нашим войскам поддержать силы." } }, f = { { 0.00, "А, вот они!" }, { 0.98, "Отличная работа!" }, { 2.42, "Припасы немного заплесневели – сказывается влажность воздуха в руднике – но всё равно сгодятся." }, { 10.35, "Спасибо тебе." }, { 11.56, "Ты помогла нашим войскам поддержать силы." } } } } },
    [5901] = { d = 37.5, v = "scourge-female#80", n = { x = 365 }, c = { x = { { 0.00, "Ну всё, теперь у меня есть партизанский план борьбы с Алым орденом!" }, { 5.61, "Для начала они расплатятся за свои деяния лесопилкой." }, { 10.16, "Вот они у меня попрыгают!" }, { 12.36, "Посмотрим, будут ли они так же лихо перестраивать всё в городе под свои нужды, когда я перекрою им поступления стройматериалов." }, { 22.97, "Поможешь мне?" }, { 24.11, "Возьми эту банку и отправляйся в Проклятый лес, что в Восточных Чумных землях." }, { 30.70, "Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!" } } }, t = { d = 5.8, g = 1, v = "scourge-female#80", n = { m = 48, f = 49 }, c = { m = { { 0.00, "Замечательно." }, { 1.35, "Благодарю тебя." }, { 2.97, "Если не сдрейфил, продолжим!" } }, f = { { 0.00, "Замечательно." }, { 1.37, "Благодарю тебя." }, { 3.01, "Если не сдрейфила, продолжим!" } } } } },
    [5902] = { d = 36.9, v = "scourge-female#80", n = { x = 367 }, c = { x = { { 0.00, "Теперь у нас просто прорва термитов." }, { 3.01, "Я надёжно запрятала их вот в этот окованный железом бочонок." }, { 7.86, "Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдёшь, если свернёшь на запад с дороги, ведущей отсюда в город." }, { 19.55, "Как будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик." }, { 27.70, "Главное открыть, а уж дальше термиты сами разберутся." }, { 32.11, "А потом возвращайся ко мне – я придумаю, чем тебя порадовать." } } }, t = { d = 5.4, v = "narrator", n = { x = 57 }, c = { x = { { 0.00, "Когда ты ставишь бочонок на ящик, термиты внутри заметно оживляются." } } } } },
    [5903] = { d = 37.2, v = "human-male", n = { x = 449 }, c = { x = { { 0.00, "Я долгое время пытался бороться с Алым орденом в открытую, но без толку." }, { 4.99, "Теперь я подумываю прибегнуть к некоторым партизанским методам – если не можешь одержать победу, хотя бы отрави врагу существование!" }, { 14.05, "Если хочешь мне помочь, слушай мой план: я собираюсь подбросить им на лесопилку самых зловредных термитов из всех существующих." }, { 22.61, "Эти твари водятся в Проклятом лесу недалеко от Стратхольма – их колония пережила чуму и переродилась в новый, ещё более живучий вид." }, { 31.67, "Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!" } } }, t = { d = 12.7, v = "human-male", n = { x = 132 }, c = { x = { { 0.00, "Замечательно." }, { 1.03, "Благодарю тебя." }, { 2.27, "Их так много... честное слово, мне даже жаль бедняг из Алого Марша!" }, { 7.43, "Впрочем, лесопилка-то всё равно не их, они её нагло присвоили, так ведь?" } } } } },
    [5904] = { d = 29.6, v = "human-male", n = { x = 365 }, c = { x = { { 0.00, "Теперь у нас просто прорва термитов." }, { 2.45, "Я надёжно запрятал их вот в этот окованный железом бочонок." }, { 6.34, "Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдёшь, если свернёшь на запад с дороги, ведущей отсюда в город." }, { 15.86, "Как будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик." }, { 22.50, "Главное открыть, а уж дальше термиты сами разберутся." }, { 26.09, "Едва ли Алый Марш сможет впредь использовать лесопилку!" } } }, t = { d = 5.4, v = "narrator", n = { x = 57 }, c = { x = { { 0.00, "Когда ты ставишь бочонок на ящик, термиты внутри заметно оживляются." } } } } },
    [5921] = { d = 40.6, g = 1, v = "nightelf-male#59", n = { m = 444, f = 449 }, c = { m = { { 0.00, "На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны." }, { 13.71, "Теперь, когда ты встал на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну." }, { 22.74, "Пользуйся им, когда тебе нужно знание или уединение Лунной поляны." }, { 27.75, "Вот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной Гавани о том пути, по которому ты ныне следуешь." }, { 37.90, "Удачи тебе, юный друид." } }, f = { { 0.00, "На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны." }, { 13.86, "Теперь, когда ты встала на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну." }, { 23.12, "Пользуйся им, когда тебе нужно знание или уединение Лунной поляны." }, { 28.18, "Вот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной Гавани о том пути, по которому ты ныне следуешь." }, { 38.44, "Удачи тебе, юная дева-друид." } } }, t = { d = 32.1, v = "nightelf-male#54", n = { x = 301 }, c = { x = { { 0.00, "\"Да будет так, отец Кенарий." }, { 3.05, "Да будет так.\"" }, { 4.48, "*Дендрит делает быстрый незаметный жест в воздухе у себя над головой.*" }, { 9.77, "*Его окутывает тонкая аура силы.*" }, { 12.28, "\"Первое обличье, которое тебе следует освоить, - это обличье медведя." }, { 18.30, "Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути - это твоя забота!" }, { 29.87, "И так отныне будет всегда.\"" } } } } },
    [5922] = { d = 49.0, g = 1, v = "tauren-male#67", n = { m = 437, f = 441 }, c = { m = { { 0.00, "На священной земле Лунной поляны рады всем друидам – и тауренам, и эльфам." }, { 6.50, "Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погружёнными в спячку друидами." }, { 15.34, "Теперь, когда ты знаешь путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну." }, { 25.98, "Пользуйся им всегда, когда тебе нужно знание или уединение Лунной поляны." }, { 32.56, "Вот первый урок – отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной Гавани о том пути, которым ты ныне следуешь." }, { 44.37, "Удачи тебе, мой юный друид." } }, f = { { 0.00, "На священной земле Лунной поляны рады всем друидам – и тауренам, и эльфам." }, { 6.74, "Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погружёнными в спячку друидами." }, { 15.91, "Теперь, когда ты знаешь путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну." }, { 26.96, "Пользуйся им всегда, когда тебе нужно знание или уединение Лунной поляны." }, { 33.78, "Вот первый урок – отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной Гавани о том пути, которым ты ныне следуешь." }, { 46.03, "Удачи тебе, моя юная дева-друид." } } }, t = { d = 32.2, v = "nightelf-male#54", n = { x = 83 }, c = { x = { { 0.00, "Да будет так, отец Кенарий." }, { 3.20, "Да будет так." }, { 4.64, "*Дендрит делает быстрый незаметный жест в воздухе у себя над головой.*" }, { 10.18, "*Его окутывает тонкая аура силы.*" }, { 12.80, "Первое обличье, которое тебе следует освоить, – это обличье медведя." }, { 18.68, "Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота!" }, { 30.13, "И так отныне будет всегда." } } } } },
    [5923] = { d = 33.0, v = "nightelf-male#54", n = { x = 345 }, c = { x = { { 0.00, "Не уделишь мне минутку внимания?.." }, { 2.75, "Дошло до меня, что Матренгил Медвежья Лапа желает побеседовать с тобой." }, { 8.53, "Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать." }, { 16.27, "Матренгил – непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила." }, { 26.10, "Он живёт в анклаве Кенария в Дарнассе, на втором уровне дерева Фэндрала Оленьего Шлема." } } }, t = { d = 32.9, g = 1, v = "nightelf-male#59", n = { m = 334, f = 338 }, c = { m = { { 0.00, "Я рад, что ты нашёл сюда дорогу, юный друид." }, { 3.49, "Пришло тебе время вступить в большой мир." }, { 6.83, "В сердце каждого из детей Кенария звучит зов природы." }, { 11.10, "Животные и растения – наши друзья и наша забота." }, { 15.01, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 21.49, "Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя." }, { 28.53, "Так ты познаешь, что такое сила тела и духа." }, { 32.09, "Готовься!" } }, f = { { 0.00, "Я рад, что ты нашла сюда дорогу, юная дева-друид." }, { 3.94, "Пришло тебе время вступить в большой мир." }, { 7.25, "В сердце каждого из детей Кенария звучит зов природы." }, { 11.48, "Животные и растения – наши друзья и наша забота." }, { 15.35, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 21.76, "Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя." }, { 28.73, "Так ты познаешь, что такое сила тела и духа." }, { 32.26, "Готовься!" } } } } },
    [5924] = { d = 30.7, v = "nightelf-male#59", n = { x = 360 }, c = { x = { { 0.00, "Не уделишь мне минутку внимания?.." }, { 2.38, "До моего сведения дошло, что Матренгил Медвежья Лапа желает пообщаться с тобой." }, { 7.95, "Похоже, твоё обучение искусству друида переходит на новую ступень, и он лично будет учить тебя." }, { 14.65, "Матренгил – правая рука самого верховного друида и один из самых мудрых и благородных друидов, каких только можно встретить в Тельдрассиле." }, { 24.68, "Он обитает в анклаве Кенария в Дарнассе, на втором ярусе дерева Фэндрала Оленьего Шлема." } } }, t = { d = 33.0, g = 1, v = "nightelf-male#59", n = { m = 341, f = 346 }, c = { m = { { 0.00, "Я рад, что ты добрался сюда, мой юный друид." }, { 3.37, "Пришло время тебе сделать большой шаг в огромный мир." }, { 7.49, "Каждый из детей Кенария слышит внутри себя призыв служить природе." }, { 12.71, "Животные и растения – наши друзья, а также и наша забота." }, { 17.17, "Таков наш выбор – посвятить жизни сохранению равновесия во имя блага всего живого." }, { 23.56, "Твой первый шаг в этот мир будет заключаться в изучении пути медведя, в изучении силы тела и силы сердца." }, { 31.67, "Приготовься!" } }, f = { { 0.00, "Я рад, что ты добралась сюда, моя юная дева-друид." }, { 3.91, "Пришло время тебе сделать большой шаг в огромный мир." }, { 8.02, "Каждый из детей Кенария слышит внутри себя призыв служить природе." }, { 13.23, "Животные и растения – наши друзья, а также и наша забота." }, { 17.69, "Таков наш выбор – посвятить жизни сохранению равновесия во имя блага всего живого." }, { 24.06, "Твой первый шаг в этот мир будет заключаться в изучении пути медведя, в изучении силы тела и силы сердца." }, { 32.15, "Приготовься!" } } } } },
