    [5928] = { d = 32.1, v = "tauren-female#71", n = { x = 327 }, c = { x = { { 0.00, "Прости меня, друг мой…" }, { 1.82, "Мне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой." }, { 7.79, "Похоже, что тебе предстоит продолжать обучение на друида." }, { 12.44, "Тюрак собирается обучать тебя лично!" }, { 15.50, "А ведь он – один из помощников верховного друида." }, { 19.43, "Он известен как мудрый и терпеливый наставник." }, { 23.14, "Ты у него многому научишься." }, { 25.47, "Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." } } }, t = { d = 43.8, g = 1, v = "tauren-male#67", n = { m = 366, f = 370 }, c = { m = { { 0.00, "Я рад, что тебе удалось добраться сюда, мой юный друид." }, { 5.06, "Пришла тебе пора сделать очередной большой шаг на своём славном пути!" }, { 11.42, "В каждом из детей Кенария живёт стремление служить природе." }, { 16.81, "Животные и растения – не только наши подопечные, но и наши друзья." }, { 22.84, "Мы посвящаем свою жизнь сохранению равновесия не только ради себя, но и ради них." }, { 30.19, "И первым твоим шагом в этот мир природы будет изучение медведя." }, { 36.06, "Благодаря ему ты обретёшь силу тела и духа." }, { 40.06, "Готовься же!" } }, f = { { 0.00, "Я рад, что тебе удалось добраться сюда, моя юная дева-друид." }, { 5.92, "Пришла тебе пора сделать очередной большой шаг на своём славном пути!" }, { 12.61, "В каждом из детей Кенария живёт стремление служить природе." }, { 18.27, "Животные и растения – не только наши подопечные, но и наши друзья." }, { 24.62, "Мы посвящаем свою жизнь сохранению равновесия не только ради себя, но и ради них." }, { 32.34, "И первым твоим шагом в этот мир природы будет изучение медведя." }, { 38.52, "Благодаря ему ты обретёшь силу тела и духа." }, { 42.72, "Готовься же!" } } } } },
    [5929] = { d = 44.1, g = 1, v = "nightelf-male#54", n = { m = 446, f = 447 }, c = { m = { { 0.00, "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которое мы называем духом Великого Медведя." }, { 9.93, "Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя." }, { 18.68, "Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение." }, { 25.81, "Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить." }, { 33.67, "Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань." }, { 39.04, "Тогда и посмотрим, действительно ли ты усвоил его уроки." } }, f = { { 0.00, "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которое мы называем духом Великого Медведя." }, { 10.04, "Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя." }, { 18.88, "Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение." }, { 26.09, "Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить." }, { 34.05, "Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань." }, { 39.48, "Тогда и посмотрим, действительно ли ты усвоила его уроки." } } }, t = { d = 31.4, v = "nightelf-male#54", n = { x = 311 }, c = { x = { { 0.00, "*Дендрит делает ещё один неприметный жест над головой при вашем приближении.*" }, { 5.79, "*Его снова окутывает аура силы, и он еле заметно улыбается.*" }, { 10.40, "\"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи." }, { 17.03, "Во взгляде твоём сила и осознанное стремление, хотя ещё и не столь оформленное." }, { 23.58, "Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя.\"" } } } } },
    [5930] = { d = 43.4, g = 1, v = "nightelf-male#54", n = { m = 446, f = 447 }, c = { m = { { 0.00, "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которое мы называем духом Великого Медведя." }, { 9.78, "Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя." }, { 18.40, "Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение." }, { 25.43, "Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить." }, { 33.18, "Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань." }, { 38.47, "Тогда и посмотрим, действительно ли ты усвоил его уроки." } }, f = { { 0.00, "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которое мы называем духом Великого Медведя." }, { 9.87, "Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя." }, { 18.58, "Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение." }, { 25.67, "Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить." }, { 33.49, "Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань." }, { 38.83, "Тогда и посмотрим, действительно ли ты усвоила его уроки." } } }, t = { d = 31.4, v = "nightelf-male#54", n = { x = 311 }, c = { x = { { 0.00, "*Дендрит делает ещё один неприметный жест над головой при вашем приближении.*" }, { 6.06, "*Его снова окутывает аура силы, и он еле заметно улыбается.*" }, { 10.88, "Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи." }, { 17.43, "Во взгляде твоём сила и осознанное стремление, хотя ещё и не столь оформленное." }, { 23.98, "Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя." } } } } },
    [5931] = { d = 33.8, v = "nightelf-male#54", n = { x = 347 }, c = { x = { { 0.00, "Пришла пора нашим дорогам разойтись, дитя моё, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне." }, { 10.39, "Матренгил Медвежья Лапа живёт в истинном равновесии с природой, хотя и обитает опасно близко к тому месту, где это равновесие пошатнулось." }, { 21.50, "Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия." }, { 31.10, "Ступай же, дитя." }, { 32.47, "Мы ещё встретимся." } } }, t = { d = 31.3, v = "nightelf-male#59", n = { x = 361 }, c = { x = { { 0.00, "С возвращением." }, { 1.07, "Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет." }, { 14.77, "То же было и со мной." }, { 16.22, "Дух Великого Медведя был частью Азерота с самого его возникновения." }, { 20.95, "Мы полагаемся на его мудрость и могущество в достижении наших целей." }, { 25.74, "Теперь пришла пора тебе пройти первое своё испытание на этом пути." }, { 30.54, "Слушай же..." } } } } },
    [5932] = { d = 28.8, v = "nightelf-male#54", n = { x = 316 }, c = { x = { { 0.00, "Пришла пора нашим дорогам разойтись, дитя моё, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне." }, { 9.76, "Хотя таурены недавно вступили на путь Кенария, Тюрак Рунический Тотем живёт в равновесии с природой." }, { 17.29, "Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия." }, { 26.30, "Ступай же, дитя." }, { 27.59, "Мы ещё встретимся." } } }, t = { d = 43.3, v = "tauren-male#67", n = { x = 377 }, c = { x = { { 0.00, "С возвращением." }, { 1.41, "Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет." }, { 19.47, "То же было и со мной." }, { 21.39, "Дух Великого Медведя был частью Азерота с самого его возникновения." }, { 27.63, "Мы, таурены, внимательно прислушиваемся к таким духам, и его цели ведут нас к процветанию." }, { 35.95, "Теперь пришла пора тебе пройти первое своё испытание на этом пути." }, { 42.28, "Слушай же..." } } } } },
    [5941] = { d = 26.0, g = 1, v = "human-male#50", n = { m = 291, f = 292 }, c = { m = { { 0.00, "Ты собрал многие реликвии, сохранившиеся со времён битвы при Дарроушире." }, { 5.18, "Они взывают ко мне... умоляют изменить судьбу жителей Дарроушира." }, { 9.96, "Да, звучит абсурдно, но Хроми, странный гном, живущий в Андорале, убеждает меня, что это возможно." }, { 17.10, "Она говорит, ты можешь спасти Дарроушир!" }, { 20.12, "Ты должен отнести эти реликвии ей, она ждёт тебя в разрушенной таверне в Андорале." } }, f = { { 0.00, "Ты собрала многие реликвии, сохранившиеся со времён битвы при Дарроушире." }, { 5.15, "Они взывают ко мне... умоляют изменить судьбу жителей Дарроушира." }, { 9.85, "Да, звучит абсурдно, но Хроми, странный гном, живущий в Андорале, убеждает меня, что это возможно." }, { 16.86, "Она говорит, ты можешь спасти Дарроушир!" }, { 19.82, "Ты должна отнести эти реликвии ей, она ждёт тебя в разрушенной таверне в Андорале." } } }, t = { d = 14.3, v = "creature/chromie", n = { x = 138 }, c = { x = { { 0.00, "Ага, вот они..." }, { 1.36, "Они послужат основой для мощного заклинания, которое сможет призвать духов Дарроушира." }, { 8.72, "С помощью этих чар и толики удачи мы сможем спасти Джозефа Редпата!" } } } } },
    [5942] = { d = 17.6, g = 1, v = "child-female", n = { m = 174, f = 174 }, c = { m = { { 0.00, "Папа велел отдать тебе этот ключ." }, { 2.71, "Он открывает сундук, который стоит во дворе за домом." }, { 6.88, "А ещё он просил поблагодарить тебя." }, { 9.59, "Не знаю, правда, за что – может, он знает, что ты нашёл мою куклу?" }, { 14.66, "Вот и ключ." }, { 15.49, "Спасибо тебе, ты хороший!" } }, f = { { 0.00, "Папа велел отдать тебе этот ключ." }, { 2.74, "Он открывает сундук, который стоит во дворе за домом." }, { 6.95, "А ещё он просил поблагодарить тебя." }, { 9.68, "Не знаю, правда, за что – может, он знает, что ты нашла мою куклу?" }, { 14.87, "Вот и ключ." }, { 15.72, "Спасибо тебе, ты хорошая!" } } }, t = { d = 3.4, v = "narrator", n = { x = 33 }, c = { x = { { 0.00, "Ключ со скрипом поворачивается в замке..." } } } } },
    [5943] = { d = 37.5, g = 1, v = "goblin-male#109", n = { x = 413 }, c = { m = { { 0.00, "Вид-то у тебя надёжный, герой." }, { 2.23, "Подзаработать хочешь?" }, { 3.81, "Мы с Корком думали, что на этом караване срубим кучу денег – но оказалось, что новое предприятие сулит гораздо больше неприятностей и опасностей, чем мы полагали." }, { 15.58, "Там, впереди, находится Поле Маннорок..." }, { 18.54, "Обычно демоны не обращают на нас внимания, но на этот раз что-то изрядно напугало кодо." }, { 24.91, "Я хорошо заплачу тебе за охрану каравана." }, { 28.00, "Если нам удастся миновать Поле Маннорок без проблем, ты сможешь получить награду у Смида: это наш деловой партнёр в Лагере Заржавня." } }, f = { { 0.00, "Вид-то у тебя надёжный, героиня." }, { 2.33, "Подзаработать хочешь?" }, { 3.88, "Мы с Корком думали, что на этом караване срубим кучу денег – но оказалось, что новое предприятие сулит гораздо больше неприятностей и опасностей, чем мы полагали." }, { 15.46, "Там, впереди, находится Поле Маннорок..." }, { 18.37, "Обычно демоны не обращают на нас внимания, но на этот раз что-то изрядно напугало кодо." }, { 24.64, "Я хорошо заплачу тебе за охрану каравана." }, { 27.68, "Если нам удастся миновать Поле Маннорок без проблем, ты сможешь получить награду у Смида: это наш деловой партнёр в Лагере Заржавня." } } }, t = { d = 14.6, v = "goblin-male", n = { x = 173 }, c = { x = { { 0.00, "Я не уверен, что стоит платить такие деньги за защиту каравана Гизлтона." }, { 4.95, "В конце концов, Корк и Риггер зарабатывают не больше одного золотого в неделю." }, { 10.26, "Главное, чтобы они мне платили за кодо, а остальное – не моё дело." } } } } },
    [5944] = { d = 27.2, v = "human-male", n = { x = 309 }, c = { x = { { 0.00, "Как же долго я был марионеткой верховного рыцаря." }, { 3.43, "И что было проку сражаться с Алым орденом?" }, { 6.47, "Прошли десятки лет с мнимой смерти отца, но я жил лишь воспоминаниями о нём." }, { 11.74, "Мне снилось, что мы с отцом снова вместе." }, { 14.66, "Он стоит рядом, с гордостью глядя, как меня принимают в орден." }, { 19.10, "Мы бьёмся с Плетью плечо к плечу, принося славу Альянсу и Лордерону." }, { 23.92, "Не желаю больше жить во сне." }, { 25.88, "Отведи меня к отцу." } } }, t = { d = 28.1, v = "human-male", n = { x = 316 }, c = { x = { { 0.00, "Убийство моего сына не пройдёт этим чудовищам даром." }, { 3.86, "Пусть нас утешит мысль о возрождении Ордена." }, { 7.01, "Я встану во главе обновлённого Ордена Серебряной Длани." }, { 11.00, "В знак своей признательности я могу отдать тебе лишь эти вещи, символы моего прошлого." }, { 17.35, "Прими их, они служили мне верой и правдой долгие годы." }, { 21.41, "Да встретимся мы в лучшие дни и вспомним давнее прошлое... трудные битвы... пробуждение от сна." } } } } },
    [5961] = { d = 33.0, g = 1, v = "named/sylvanas", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Приятно видеть, что в наши ряды вступают закалённые бойцы." }, { 4.59, "С каждым днём нас становится всё больше." }, { 7.70, "Ты готов испытать собственную решимость, герой?" }, { 11.44, "Первый среди моих защитников – Натанос по прозвищу Гнилостень." }, { 16.38, "Немногие могут превзойти его в преданности и доблести." }, { 20.69, "Отыщи его в Восточных Чумных землях." }, { 23.66, "Он живёт в Поместье Маррисов и порой бродит по окружающим его пустошам, истребляя всякую мразь из воинств Плети и Альянса." } }, f = { { 0.00, "Приятно видеть, что в наши ряды вступают закалённые бойцы." }, { 4.56, "С каждым днём нас становится всё больше." }, { 7.65, "Ты готова испытать собственную решимость, героиня?" }, { 11.58, "Первый среди моих защитников – Натанос по прозвищу Гнилостень." }, { 16.49, "Немногие могут превзойти его в преданности и доблести." }, { 20.77, "Отыщи его в Восточных Чумных землях." }, { 23.72, "Он живёт в Поместье Маррисов и порой бродит по окружающим его пустошам, истребляя всякую мразь из воинств Плети и Альянса." } } }, t = { d = 12.6, g = 1, v = "creature/nathanos", n = { m = 126, f = 127 }, c = { m = { { 0.00, "Не может быть, чтобы Тёмная Госпожа сочла тебя достойным встречи со своим защитником." }, { 7.02, "Ты ведь прислан кормить моих псов, да?" }, { 10.13, "Иначе зачем ты меня тревожишь?" } }, f = { { 0.00, "Не может быть, чтобы Тёмная Госпожа сочла тебя достойной встречи со своим защитником." }, { 6.98, "Ты ведь прислана кормить моих псов, да?" }, { 10.14, "Иначе зачем ты меня тревожишь?" } } } } },
    [5981] = { d = 32.2, v = "nightelf-male#55", n = { x = 381 }, c = { x = { { 0.00, "Около четырёх тысяч лет назад Тиранда Шелест Ветра спасла жизнь королевы ледопардов, вырвав её из рук жестоких великанов." }, { 8.48, "С тех самых пор ледопарды стали союзниками ночных эльфов." }, { 12.52, "Те самые великаны, что когда-то представляли опасность для ледопардов, и поныне живут не очень далеко отсюда." }, { 20.18, "Их называют кланом Ледяного Молота, и они обосновались в большой долине к югу отсюда." }, { 26.15, "Докажите вашу лояльность – убейте этих великанов во имя королевы ледопардов, Ши-Ротам!" } } }, t = { d = 4.6, v = "nightelf-male#55", n = { x = 46 }, c = { x = { { 0.00, "Превосходно." }, { 1.14, "Твоё упорство не останется незамеченным." } } } } },
    [6001] = { d = 34.3, g = 1, v = "nightelf-male#59", n = { m = 391, f = 393 }, c = { m = { { 0.00, "Прямо к востоку от Аубердина находятся пещеры лунных совухов." }, { 4.46, "В той, что ближе всего к Аубердину, находится камень лунного совуха." }, { 9.38, "Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария." }, { 17.01, "Лунокоготь таит в себе силу, которой ты, как один из друидов-медведей, должен овладеть." }, { 23.34, "Ты заслужил право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужил право обладать силами тела и духа, необходимыми друиду!" } }, f = { { 0.00, "Прямо к востоку от Аубердина находятся пещеры лунных совухов." }, { 4.64, "В той, что ближе всего к Аубердину, находится камень лунного совуха." }, { 9.54, "Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария." }, { 17.14, "Лунокоготь таит в себе силу, которой ты, как одна из друидов-медведей, должна овладеть." }, { 23.46, "Ты заслужила право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужила право обладать силами тела и духа, необходимыми друиду!" } } }, t = { d = 18.7, g = 1, v = "nightelf-male#59", n = { m = 193, f = 194 }, c = { m = { { 0.00, "Это твой первый большой шаг на пути к великим свершениям." }, { 4.39, "Я чую учение Духа Великого Медведя в тебе и вижу, что ты перенял мощь Лунокогтя." }, { 10.56, "Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" } }, f = { { 0.00, "Это твой первый большой шаг на пути к великим свершениям." }, { 4.51, "Я чую учение Духа Великого Медведя в тебе и вижу, что ты переняла мощь Лунокогтя." }, { 10.91, "Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" } } } } },
    [6002] = { d = 42.5, g = 1, v = "tauren-male#67", n = { m = 404, f = 406 }, c = { m = { { 0.00, "Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха." }, { 8.57, "Лунные совухи – звери особые, в здешних краях они не живут." }, { 13.64, "Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария." }, { 21.85, "Лунокоготь таит в себе силу, которой ты должен овладеть, как один из друидов-медведей." }, { 29.08, "Ты заслужил право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужил право обладать силой тела и духа, необходимой друиду!" } }, f = { { 0.00, "Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха." }, { 8.72, "Лунные совухи – звери особые, в здешних краях они не живут." }, { 13.88, "Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария." }, { 22.23, "Лунокоготь таит в себе силу, которой ты должна овладеть, как одна из друидов-медведей." }, { 29.59, "Ты заслужила право пользоваться этой лунной пылью Кенария... теперь покажи мне, что также заслужила право обладать силой тела и духа, необходимой друиду!" } } }, t = { d = 23.9, g = 1, v = "tauren-male#67", n = { m = 193, f = 194 }, c = { m = { { 0.00, "Это твой первый большой шаг на пути к великим свершениям." }, { 5.75, "Я чую учение Духа Великого Медведя в тебе, и вижу, что ты перенял мощь Лунокогтя." }, { 13.93, "Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" } }, f = { { 0.00, "Это твой первый большой шаг на пути к великим свершениям." }, { 5.67, "Я чую учение Духа Великого Медведя в тебе, и вижу, что ты переняла мощь Лунокогтя." }, { 13.83, "Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" } } } } },
    [6004] = { d = 31.8, g = 1, v = "human-female#47", n = { m = 403, f = 404 }, c = { m = { { 0.00, "У меня была разведывательная миссия – немного сократить число противников и оценить укрепления Дольного Очага." }, { 7.06, "Некоторые сторонники Альянса считают, что этот город имеет не только историческое значение." }, { 12.91, "Не моё дело решать, что важнее, но выполнять задание я не в силах, пока не отдохну." }, { 18.19, "Если хочешь, я неплохо заплачу тебе за помощь." }, { 21.24, "Начни на юге, возле лагеря Алого Марша, у небольшого бастиона." }, { 25.31, "Если ты окажешься достаточно силён, я попрошу тебя помочь мне выполнить основную часть задания." } }, f = { { 0.00, "У меня была разведывательная миссия – немного сократить число противников и оценить укрепления Дольного Очага." }, { 7.16, "Некоторые сторонники Альянса считают, что этот город имеет не только историческое значение." }, { 13.10, "Не моё дело решать, что важнее, но выполнять задание я не в силах, пока не отдохну." }, { 18.45, "Если хочешь, я неплохо заплачу тебе за помощь." }, { 21.54, "Начни на юге, возле лагеря Алого Марша, у небольшого бастиона." }, { 25.67, "Если ты окажешься достаточно сильна, я попрошу тебя помочь мне выполнить основную часть задания." } } }, t = { d = 20.2, v = "human-female#47", n = { x = 250 }, c = { x = { { 0.00, "Молодец." }, { 0.59, "Как тебе удалось так быстро с ними разобраться?" }, { 3.69, "Спасибо." }, { 4.27, "Мне пока не встречался никто, кто одобрил бы Алый орден или его методы." }, { 9.02, "Я верю в Свет так же, как и все жители Штормграда, но эти фанатики наглядно доказали, что стремятся лишь убивать всех, кроме своих сторонников... даже ни в чём не повинных людей." } } } } },
    [6021] = { d = 30.8, v = "human-male", n = { x = 341 }, c = { x = { { 0.00, "Кто бы мог подумать, после всех наших злоключений в Чумных землях нам не хватало только воров!" }, { 6.79, "И не просто воров, а троллей!" }, { 8.94, "И не просто воров-троллей, а мёртвых воров-троллей!" }, { 12.67, "Их главарь – огромный мёртвый тролль по имени Зельдарр Изгой." }, { 17.04, "Они являются по ночам, крадут тела из ямы и тащат их в своё мерзкое логово." }, { 22.59, "Оно зовётся Крипта, это к западу отсюда." }, { 25.59, "Отправляйся туда, и разберись с Зельдарром." }, { 28.73, "Я сыт по горло его проделками!" } } }, t = { d = 4.9, v = "human-male", n = { x = 50 }, c = { x = { { 0.00, "Поделом ему!" }, { 1.06, "Надеюсь, и остальным из его шайки тоже досталось!" } } } } },
    [6022] = { d = 36.1, g = 1, v = "creature/nathanos", n = { m = 377, f = 378 }, c = { m = { { 0.00, "Будь готов на умышленное убийство, если хочешь со мной работать." }, { 4.94, "Для начала покорми моих псов." }, { 7.23, "Возьми эту ступку и пестик и отправляйся в Перекрёсток Корина." }, { 12.99, "Там у тебя будет обширный выбор тварей Плети – убей тех, какие больше приглянутся." }, { 19.46, "Из их свежих туш добудь живую гниль, растолки в ступке и дай отстояться, чтобы она сгустилась." }, { 26.70, "Принесёшь сгущённую гниль мне." }, { 28.86, "И слушай меня, недотёпа, живая гниль – продукт скоропортящийся!" }, { 33.66, "Поэтому работать придётся быстро." } }, f = { { 0.00, "Будь готова на умышленное убийство, если хочешь со мной работать." }, { 5.06, "Для начала покорми моих псов." }, { 7.37, "Возьми эту ступку и пестик и отправляйся в Перекрёсток Корина." }, { 12.22, "Там у тебя будет обширный выбор тварей Плети – убей тех, какие больше приглянутся." }, { 18.75, "Из их свежих туш добудь живую гниль, растолки в ступке и дай отстояться, чтобы она сгустилась." }, { 26.05, "Принесёшь сгущённую гниль мне." }, { 28.23, "И слушай меня, недотёпа, живая гниль – продукт скоропортящийся!" }, { 33.07, "Поэтому работать придётся быстро." } } }, t = { d = 11.3, v = "creature/nathanos", n = { x = 101 }, c = { x = { { 0.00, "Прискорбно, прискорбно..." }, { 2.43, "Я-то надеялся скормить моим псам тебя..." }, { 6.42, "Ладно, по крайней мере им есть, что погрызть." } } } } },
    [6023] = { d = 31.0, v = "human-female#47", n = { x = 361 }, c = { x = { { 0.00, "Подлинная суть моей миссии состояла в том, чтобы подорвать мощь внешних отрядов Алого ордена, а потом проникнуть внутрь Дольного Очага и оценить их основные силы." }, { 11.39, "Я пока не в форме, но, может быть, могу снова попросить о помощи?" }, { 16.00, "Судя по собранным сведениям, за пределами города костяк сил ордена составляют двое: охотник Радли и кавалерист Дарген." }, { 24.35, "Убей их, и дело стронется с мёртвой точки." }, { 27.32, "Они должны быть неподалёку от прохода, рядом с городом." } } }, t = { d = 23.4, v = "human-female#47", n = { x = 250 }, c = { x = { { 0.00, "Спасибо." }, { 0.66, "Я и не рассчитывала на такую помощь." }, { 3.31, "Кажется, самый воздух этих земель лишает меня воли." }, { 7.28, "Я очень устала, и чем дольше здесь нахожусь, тем мне хуже." }, { 11.52, "Не представляю, как я проберусь в Дольный Очаг, чтобы выяснить размер армии Алого ордена." }, { 18.14, "Но это другой разговор." }, { 19.93, "Погоди, возьми это... в уплату." }, { 22.31, "Спасибо ещё раз." } } } } },
    [6024] = { d = 41.8, v = "narrator", n = { x = 429 }, c = { x = { { 0.00, "Убей меня." }, { 0.92, "Пока не поздно!" }, { 2.20, "Меня зовут Хамейя." }, { 3.75, "Мы с собратьями путешествовали через Зул'Машар и, видимо, съели что-то не то." }, { 9.77, "Мы заражены!" }, { 10.76, "Я слышу, как лич нашёптывает мне, что я должен отправиться в Зул'Машар и постараться распространить заразу." }, { 18.91, "Я не могу противиться его словам, поэтому написал это послание прежде, чем разум окончательно оставит меня." }, { 27.47, "Я закопал сундук с сокровищами рядом с повозкой, оставленной за этим склепом, но его можно открыть только моим ключом." }, { 36.89, "Ключ у меня." }, { 37.88, "Чтобы добыть сокровище, убей меня." }, { 40.72, "Пока не поздно!" } } }, t = { d = 2.5, v = "narrator", n = { x = 18 }, c = { x = { { 0.00, "Сундук Хамейи открыт!" } } } } },
    [6025] = { d = 28.0, g = 1, v = "human-female#47", n = { m = 325, f = 327 }, c = { m = { { 0.00, "Что?" }, { 0.30, "Правда?" }, { 0.84, "Ты готов меня выслушать?" }, { 2.53, "Но ты и так очень много для меня сделал." }, { 5.24, "Я не могу просить тебя отправиться в Дольный Очаг." }, { 8.68, "Ты серьёзно?" }, { 9.46, "Дольный Очаг гораздо опаснее прохода..." }, { 12.17, "Я не смогу защитить тебя или даже рассказать, что тебя может ждать там." }, { 16.99, "Если ты в самом деле хочешь мне помочь, то проникни в город, поднимись на гору и осмотри его с высоты." }, { 23.92, "Оцени количество войск и доложи мне." }, { 26.33, "Но будь осторожен..." } }, f = { { 0.00, "Что?" }, { 0.31, "Правда?" }, { 0.85, "Ты готова меня выслушать?" }, { 2.62, "Но ты и так очень много для меня сделала." }, { 5.43, "Я не могу просить тебя отправиться в Дольный Очаг." }, { 8.91, "Ты серьёзно?" }, { 9.71, "Дольный Очаг гораздо опаснее прохода..." }, { 12.45, "Я не смогу защитить тебя или даже рассказать, что тебя может ждать там." }, { 17.34, "Если ты в самом деле хочешь мне помочь, то проникни в город, поднимись на гору и осмотри его с высоты." }, { 24.36, "Оцени количество войск и доложи мне." }, { 26.80, "Но будь осторожна..." } } }, t = { d = 13.7, v = "human-female#47", n = { x = 149 }, c = { x = { { 0.00, "Молодец!" }, { 0.66, "Спасибо!" }, { 1.32, "Я вернусь к Иллингу... точнее, в Штормград как только смогу." }, { 5.73, "Возьми эту скромную сумму, должна же я тебя отблагодарить." }, { 10.07, "Твой народ может тобой гордиться." }, { 12.57, "Спасибо и удачи." } } } } },
    [6026] = { d = 30.0, v = "dwarf-male", n = { x = 339 }, c = { x = { { 0.00, "Серебряный Рассвет поручил старине Дымку кой-какую работёнку." }, { 4.41, "А я что, я токмо рад – денежка-то никогда не лишняя!" }, { 8.10, "Однако силы мои уже не те, и я бы, пожалуй, воспользовался твоей помощью, если ты тоже не прочь подзаработать." }, { 16.01, "Я пойду в Проклятый лес и отмечу знаком строения, которые предстоит взорвать, а ты пока добудешь взрывчатки." }, { 23.79, "Договорились?" }, { 24.76, "Жди меня на этом самом месте, как соберёшь всё необходимое." }, { 28.98, "Ну, что скажешь?" } } }, t = { d = 4.6, v = "dwarf-male", n = { x = 54 }, c = { x = { { 0.00, "Могу заплатить половину сейчас и половину по выполнении работы." } } } } },
    [6027] = { d = 24.6, v = "human-male", n = { x = 272 }, c = { x = { { 0.00, "Послушай меня: я вручаю тебе Самоцвет Змеи." }, { 3.25, "Его нужно поместить на руку Статуи Змеи, что на острове Раназьяр: это небольшой островок к северо-западу отсюда." }, { 11.51, "Когда сделаешь это, явится тот, кто хранит Книгу Древних." }, { 15.73, "В книге можно найти вековые тайны нагов." }, { 18.79, "Принеси мне эту книгу: вместе мы сумеем узнать многое о наших чешуйчатых врагах!" } } }, t = { d = 12.1, g = 1, v = "human-male", n = { m = 131, f = 132 }, c = { m = { { 0.00, "Утраченная Книга Древних!" }, { 1.97, "Я прослежу за тем, чтобы она была передана высокому совету." }, { 6.51, "Сегодня ты свершил великое деяние; прими же благодарность за этот подвиг!" } }, f = { { 0.00, "Утраченная Книга Древних!" }, { 1.98, "Я прослежу за тем, чтобы она была передана высокому совету." }, { 6.56, "Сегодня ты свершила великое деяние; прими же благодарность за этот подвиг!" } } } } },
    [6028] = { d = 30.0, v = "human-male#50", n = { x = 377 }, c = { x = { { 0.00, "Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему." }, { 6.63, "Я здесь как представитель интересов Серебряного Рассвета по управлению Круговзором." }, { 12.15, "Я должен доложить обстановку офицеру Чистосердой в Лагерь Промозглого Ветра, расположенный на южной окраине Западных Чумных земель." }, { 21.12, "Если мне это удастся, это будет прекрасный повод представить тебя моей начальнице и, возможно, устроить тебе персональное задание." } } }, t = { d = 32.0, v = "human-female#47", n = { x = 386 }, c = { x = { { 0.00, "Грегор крайне находчив." }, { 1.69, "Он некоторое время имел дело с Картелем Хитрая Шестерёнка, и стал экспертом по \"искусству\" переговоров с гоблинами." }, { 9.55, "Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии." }, { 18.85, "Если, так или иначе, она обеспечивает им повторные заказы..." }, { 23.09, "Во всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу." }, { 29.15, "Примите это вместе с нашей благодарностью." } } } } },
    [6029] = { d = 30.7, v = "human-male#50", n = { x = 385 }, c = { x = { { 0.00, "Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему." }, { 6.54, "Я здесь как представитель интересов Серебряного Рассвета в администрации Круговзора." }, { 12.04, "Я должен доложить обстановку офицеру Гарушу в Бастион, расположенный на западных окраинах Западных Чумных земель, к востоку от Тирисфальских лесов." }, { 21.90, "Если я могу тебя об этом просить... это будет прекрасный повод представить тебя моему начальнику." }, { 28.62, "И, возможно, он найдёт тебе дело!" } } }, t = { d = 35.6, v = "orc-male#60", n = { x = 397 }, c = { x = { { 0.00, "Для человека Грегор весьма находчив." }, { 2.77, "Он некоторое время имел дело с Картелем Хитрая Шестерёнка, и стал экспертом по \"искусству\" переговоров с гоблинами." }, { 11.29, "Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии." }, { 21.35, "Если, так или иначе, она обеспечивает им повторные заказы..." }, { 25.95, "Во всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу." }, { 32.50, "Примите это вместе с нашей благодарностью." } } } } },
    [6030] = { d = 32.3, g = 1, v = "human-male#50", n = { m = 397, f = 399 }, c = { m = { { 0.00, "Отшельник-медиум по имени Умбранс, обитающий в этих краях, обеспечил Серебряный Рассвет настоящим шедевром литературы..." }, { 8.03, "Это, пожалуй, самое большое собрание бессвязной тарабарщины, какое мне только доводилось видеть." }, { 14.51, "Один из наиболее уважаемых лидеров Рассвета, герцог Николас Зверенхофф, является блестящим лингвистом." }, { 21.35, "Ты не мог бы отнести ему эту книгу – не бесплатно, разумеется!" }, { 25.48, "Сейчас его можно найти в Часовне Последней Надежды, в восточной части Восточных Чумных земель." } }, f = { { 0.00, "Отшельник-медиум по имени Умбранс, обитающий в этих краях, обеспечил Серебряный Рассвет настоящим шедевром литературы..." }, { 8.13, "Это, пожалуй, самое большое собрание бессвязной тарабарщины, какое мне только доводилось видеть." }, { 14.68, "Один из наиболее уважаемых лидеров Рассвета, герцог Николас Зверенхофф, является блестящим лингвистом." }, { 21.60, "Ты не могла бы отнести ему эту книгу – не бесплатно, разумеется!" }, { 25.97, "Сейчас его можно найти в Часовне Последней Надежды, в восточной части Восточных Чумных земель." } } }, t = { d = 34.1, v = "human-male", n = { x = 363 }, c = { x = { { 0.00, "Это..." }, { 0.54, "Вы принесли мне весьма особенную книгу." }, { 3.52, "Я хотел бы сказать Вам, что \"особенная\" в этом случае означает \"уникальная и весьма познавательная\", но так ли это мы ещё проверим." }, { 13.22, "Ооооооо?" }, { 13.89, "Кто это выдумал?" }, { 15.18, "Хорошо, я узнал об этом Умбрансе, о котором говорил Грегор, и это ваша заслуга." }, { 21.28, "Я приложу все усилия, чтобы расшифровать эту книгу." }, { 25.21, "Что касается Вас..." }, { 26.64, "Серебряный Рассвет вам бесконечно благодарен." }, { 30.03, "Возможно нам ещё потребуются ваши услуги, пока вы здесь." } } } } },
    [6031] = { d = 40.5, v = "creature/furbolg", n = { x = 329 }, c = { x = { { 0.56, "Мы, древобрюхи, самодостаточны." }, { 3.25, "Мы не любим чужаков." }, { 5.07, "Для нас такая жизнь хороша, но вот для торговли – нет." }, { 9.66, "Недавно к нам в крепость Древобрюхов забрела редкая гостья – одна ночная эльфийка." }, { 18.04, "У неё был плащ из рунной ткани." }, { 20.73, "Рунная ткань у нас вещь редкая, но плащ был такой красивый, что мои сородичи пожелали, чтобы я нашил им побольше одежды из рунной ткани." }, { 32.60, "Ты принесёшь мне рунной ткани?" }, { 35.21, "А за это я кое-что дам тебе." } } }, t = { d = 13.5, g = 1, v = "creature/furbolg", n = { m = 82, f = 84 }, c = { m = { { 0.58, "А, принёс." }, { 1.58, "Какая же красивая ткань!" }, { 4.03, "Спасибо тебе." }, { 5.48, "Ты настоящий друг." }, { 7.30, "Пожалуйста, прими в благодарность." } }, f = { { 0.56, "А, принесла." }, { 1.76, "Какая же красивая ткань!" }, { 4.07, "Спасибо тебе." }, { 5.44, "Ты настоящий друг." }, { 7.16, "Пожалуйста, прими в благодарность." } } } } },
    [6032] = { d = 18.3, v = "creature/furbolg", n = { x = 156 }, c = { x = { { 0.43, "Хотя древобрюхам по нраву ощущение от рунной ткани, она для нас не священна." }, { 6.75, "А вот луноткань – священна." }, { 8.98, "Принеси мне немного этой священной ткани, и я научу тебя некоторым портняжным секретам." } } }, t = { d = 14.0, v = "creature/furbolg", n = { x = 86 }, c = { x = { { 0.58, "А, очень хорошо." }, { 2.24, "Из этой луноткани сошьют одежды, священные для нашего народа." }, { 8.26, "Спасибо." }, { 9.13, "Теперь я тебя обучу." } } } } },
    [6041] = { d = 23.6, g = 1, v = "dwarf-male", n = { m = 263, f = 264 }, c = { m = { { 0.00, "Пока ты занимался заготовкой припасов, мои люди отметили некоторые сооружения Плети, которые должны быть уничтожены." }, { 8.37, "План действий таков: я дам тебе десять брусков моего особого состава, ты отправишься в Проклятый лес и оставишь их в строениях Плети, помеченных знаком." }, { 19.12, "*Дымок щёлкает пальцами*" }, { 20.96, "Бабах!" }, { 21.77, "Всё очень просто!" } }, f = { { 0.00, "Пока ты занималась заготовкой припасов, мои люди отметили некоторые сооружения Плети, которые должны быть уничтожены." }, { 8.05, "План действий таков: я дам тебе десять брусков моего особого состава, ты отправишься в Проклятый лес и оставишь их в строениях Плети, помеченных знаком." }, { 18.32, "*Дымок щёлкает пальцами*" }, { 20.16, "Бабах!" }, { 20.97, "Всё очень просто!" } } }, t = { d = 17.2, v = "dwarf-male", n = { x = 180 }, c = { x = { { 0.00, "Загар тебе очень идёт." }, { 1.93, "Я всегда говорил, игра с огнём весьма полезна для цвета лица!" }, { 7.05, "Ну да ладно, вот обещанная награда." }, { 11.12, "И кой-чего сверх обещанного, чтобы боль от ожогов не казалась столь жестокой!" } } } } },
    [6042] = { d = 33.3, v = "creature/nathanos", n = { x = 355 }, c = { x = { { 0.00, "С фермы и шагу нельзя ступить, чтобы не напороться на одну из этих проклятых летучих мышей!" }, { 7.06, "Я бы, знаешь ли, предпочёл заниматься истреблением Плети, не отвлекаясь на всякую мелкую шушеру." }, { 14.25, "Моё время слишком дорого, чтобы тратить его на охоту за мышами." }, { 19.18, "А вот твоё – нет." }, { 20.41, "Что ты там бормочешь?" }, { 21.99, "Обучение?" }, { 22.74, "Вот тебе обучение – пойди поучись ловле мышей!" }, { 26.37, "И не смей показываться мне на глаза, пока не перебьёшь несколько десятков этих мерзких тварей." } } }, t = { d = 5.8, v = "creature/nathanos", n = { x = 57 }, c = { x = { { 0.00, "Вот можешь же, если захочешь!" }, { 2.54, "Главное, правильно подобрать аргументы." } } } } },
    [6061] = { d = 39.2, v = "tauren-male", n = { x = 348 }, c = { x = { { 0.00, "Для нас, тауренов, важно следовать традициям предков, сражаясь с могучими зверями." }, { 7.53, "Одолевая их, мы вбираем в себя их дух, делаясь всё ближе Матери-Земле." }, { 13.98, "Приручив же зверя и сделав его своим помощником, мы делаем ещё один шаг навстречу природе." }, { 22.33, "В конце концов ты сможешь выбрать зверя себе по вкусу." }, { 27.45, "Но сначала всему приходится учиться, и этому тоже." }, { 32.17, "Для начала возьми этот хлыст приручения; ступай, приручи равнинного долгонога." } } }, t = { d = 6.6, g = 1, v = "tauren-male", n = { m = 55, f = 56 }, c = { m = { { 0.00, "Я уже знаю, мать-земля сказала мне, что ты справился со своей задачей." } }, f = { { 0.00, "Я уже знаю, мать-земля сказала мне, что ты справилась со своей задачей." } } } } },
    [6062] = { d = 34.4, g = 1, v = "orc-male", n = { m = 370, f = 371 }, c = { m = { { 0.00, "Умение подчинять природу своей воле – великое искусство." }, { 4.47, "Ты охотник, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу." }, { 12.91, "Обрести власть над животным – дело не простое, тут требуется решимость." }, { 18.36, "Для начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря." }, { 25.48, "Они водятся поблизости от Колючего Холма." }, { 28.76, "Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне." } }, f = { { 0.00, "Умение подчинять природу своей воле – великое искусство." }, { 4.45, "Ты охотница, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу." }, { 12.93, "Обрести власть над животным – дело не простое, тут требуется решимость." }, { 18.35, "Для начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря." }, { 25.44, "Они водятся поблизости от Колючего Холма." }, { 28.70, "Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне." } } }, t = { d = 5.8, v = "orc-male", n = { x = 47 }, c = { x = { { 0.00, "Молодец!" }, { 0.87, "Думаю, тебе уже можно поручить задачу посложнее..." } } } } },
    [6063] = { d = 37.8, g = 1, v = "nightelf-male#54", n = { m = 411, f = 411 }, c = { m = { { 0.00, "Охотнику важно помнить о том, какая перед ним стоит ответственность." }, { 5.23, "Природа – не та сила, которую можно подчинить своим прихотям." }, { 9.98, "Её следует почитать как нечто, без чего само твоё существование было бы невозможным." }, { 16.38, "Ты должен доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника." }, { 25.82, "Первым делом возьми этот хлыст приручения." }, { 29.12, "С его помощью ты сумеешь приручить чащобного тенётника." }, { 33.32, "Приручи его и поупражняйся в своём охотничьем искусстве." } }, f = { { 0.00, "Охотнику важно помнить о том, какая перед ним стоит ответственность." }, { 5.29, "Природа – не та сила, которую можно подчинить своим прихотям." }, { 10.09, "Её следует почитать как нечто, без чего само твоё существование было бы невозможным." }, { 16.56, "Ты должна доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника." }, { 26.09, "Первым делом возьми этот хлыст приручения." }, { 29.43, "С его помощью ты сумеешь приручить чащобного тенётника." }, { 33.68, "Приручи его и поупражняйся в своём охотничьем искусстве." } } }, t = { d = 3.6, v = "nightelf-male#54", n = { x = 32 }, c = { x = { { 0.00, "Отлично!" }, { 0.86, "Ты и правда быстро обучаешься." } } } } },
