    [6082] = { d = 33.5, g = 1, v = "orc-male", n = { m = 361, f = 361 }, c = { m = { { 0.00, "Последнее животное, которое тебе придётся приручить, – это бронескорп." }, { 5.36, "Тебе придётся частенько с ними сражаться." }, { 8.51, "Но ты, будучи охотником, должен уметь повелевать и такими существами." }, { 13.80, "Когда ты вернёшься, я обучу тебя всему, что потребуется, чтобы приручить животное по твоему выбору." }, { 21.35, "Выбранный тобой зверь будет набираться опыта и становиться сильнее." }, { 26.50, "А ещё я покажу тебе, как призывать его и отпускать на волю, когда в нём не будет надобности." } }, f = { { 0.00, "Последнее животное, которое тебе придётся приручить, – это бронескорп." }, { 5.38, "Тебе придётся частенько с ними сражаться." }, { 8.56, "Но ты, будучи охотницей, должна уметь повелевать и такими существами." }, { 13.87, "Когда ты вернёшься, я обучу тебя всему, что потребуется, чтобы приручить животное по твоему выбору." }, { 21.46, "Выбранный тобой зверь будет набираться опыта и становиться сильнее." }, { 26.63, "А ещё я покажу тебе, как призывать его и отпускать на волю, когда в нём не будет надобности." } } }, t = { d = 23.0, g = 1, v = "orc-male", n = { m = 240, f = 241 }, c = { m = { { 0.00, "Теперь, ты знаешь всё, чему я мог тебя обучить." }, { 3.73, "Пора тебе воспользоваться полученными знаниями и выбрать себе собственного питомца." }, { 10.28, "Вот, я даю тебе способность приручать зверя, а также призывать и отсылать его по собственной воле." }, { 18.02, "Можешь гордиться своим новым умением, ты заслужил эти знания!" } }, f = { { 0.00, "Теперь, ты знаешь всё, чему я мог тебя обучить." }, { 3.76, "Пора тебе воспользоваться полученными знаниями и выбрать себе собственного питомца." }, { 10.35, "Вот, я даю тебе способность приручать зверя, а также призывать и отсылать его по собственной воле." }, { 18.16, "Можешь гордиться своим новым умением, ты заслужила эти знания!" } } } } },
    [6083] = { d = 33.5, v = "orc-male", n = { x = 354 }, c = { x = { { 0.00, "Разумеется, питомец даёт тебе большое преимущество в бою." }, { 4.53, "Подчиняя себе живое существо, ты добавляешь его силу к своей." }, { 9.48, "Он становится как бы продолжением тебя." }, { 12.52, "Следующее задание потребует от тебя обратиться от земли к морю." }, { 17.54, "Приливный краб, которого тебе нужно будет приручить, обитает в прибрежных водах, близ деревни Сен'джин и островов Эха." }, { 26.81, "Воспользуйся хлыстом приручения, чтобы усмирить зверя, а потом потренируй свои навыки." } } }, t = { d = 3.0, v = "orc-male", n = { x = 22 }, c = { x = { { 0.00, "Ты быстро учишься!" }, { 2.18, "Молодец." } } } } },
    [6084] = { d = 31.6, v = "dwarf-male", n = { x = 352 }, c = { x = { { 0.00, "Эти скальные вепри такие здоровенные – может, тебе хочется кого поизящнее?" }, { 5.63, "Ладушки, у меня есть кое-кто на примете." }, { 8.62, "К югу и востоку отсюда ты найдёшь больших белых кошек, называемых снежными леопардами." }, { 14.98, "Они чем-то напоминают элегантную винтовку – такие же красивые и такие же смертоносные." }, { 21.34, "Они гораздо проворнее и быстрее укрощённого тобой вепря." }, { 25.52, "На, держи этот хлыст приручения." }, { 27.90, "Посмотрим, придётся ли тебе по душе снежный леопард." } } }, t = { d = 7.7, g = 1, v = "dwarf-male", n = { m = 85, f = 86 }, c = { m = { { 0.00, "Когда я увижу, что ты достаточно подготовлен, я научу тебя приручать любого понравившегося тебе зверя." } }, f = { { 0.00, "Когда я увижу, что ты достаточно подготовлена, я научу тебя приручать любого понравившегося тебе зверя." } } } } },
    [6085] = { d = 33.4, v = "dwarf-male", n = { x = 397 }, c = { x = { { 0.00, "Возможно, тебе понравится животное, которое берёт одной лишь грубой силой." }, { 5.22, "Медведи-ледолапы – замечательные спутники для охотников-новичков, вроде тебя." }, { 10.56, "Их можно найти к востоку от Караноса." }, { 13.20, "Вот тебе хлыст приручения, попытайся приручить это животное и посмотри, как оно тебе придётся!" }, { 19.74, "Когда ты вернёшься, я научу тебя, как приручать животных." }, { 23.70, "Твой питомец будет вместе с тобой разделять опасности и получать опыт." }, { 28.66, "Я также научу тебя призывать и отпускать животное по своему желанию." } } }, t = { d = 11.3, v = "dwarf-male", n = { x = 116 }, c = { x = { { 0.00, "Отлично." }, { 0.71, "Теперь научу тебя приручать зверя, а также призывать и отпускать его по желанию." }, { 7.13, "Найди себе славного верного питомца – и доброй охоты!" } } } } },
    [6086] = { d = 25.8, g = 1, v = "dwarf-male", n = { m = 310, f = 311 }, c = { m = { { 0.00, "Ты умеешь приручать зверей, но ведь надо ещё научиться тренировать своего питомца." }, { 5.60, "Иди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специалистов в обучении зверей – Белией Громовым Гранитом." }, { 14.47, "Она покажет тебе, как обучать питомца." }, { 17.18, "Так что отправляйся в путь, парень!" }, { 19.52, "Белия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка." }, { 25.49, "Удачи." } }, f = { { 0.00, "Ты умеешь приручать зверей, но ведь надо ещё научиться тренировать своего питомца." }, { 5.59, "Иди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специалистов в обучении зверей – Белией Громовым Гранитом." }, { 14.43, "Она покажет тебе, как обучать питомца." }, { 17.14, "Так что отправляйся в путь, подруга!" }, { 19.53, "Белия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка." }, { 25.49, "Удачи." } } }, t = { d = 31.7, g = 1, v = "dwarf-female#34", n = { m = 347, f = 347 }, c = { m = { { 0.00, "Новенький?" }, { 0.80, "Вижу, быть тебе великим охотником." }, { 3.38, "Да, я могу поделиться с тобой знаниями, необходимыми для обучения и управления питомцем." }, { 9.82, "Ты сможешь не только обучить своего питомца новым способностям, но и научишься его кормить и даже воскрешать, если он погибнет в бою." }, { 19.70, "Помни, лучший способ подружиться с питомцем – это обращаться с ним уважительно и хорошо за ним ухаживать." }, { 27.39, "Тогда твой питомец будет безгранично предан тебе." } }, f = { { 0.00, "Новенькая?" }, { 0.81, "Вижу, быть тебе великой охотницей." }, { 3.46, "Да, я могу поделиться с тобой знаниями, необходимыми для обучения и управления питомцем." }, { 10.04, "Ты сможешь не только обучить своего питомца новым способностям, но и научишься его кормить и даже воскрешать, если он погибнет в бою." }, { 20.16, "Помни, лучший способ подружиться с питомцем – это обращаться с ним уважительно и хорошо за ним ухаживать." }, { 28.03, "Тогда твой питомец будет безгранично предан тебе." } } } } },
    [6087] = { d = 38.2, v = "tauren-male", n = { x = 363 }, c = { x = { { 0.00, "Твой дух полон огня, охотник, и ты с радостью встречаешь новые испытания." }, { 6.33, "Следующее задание – приручить волка, известного как охотник прерий." }, { 12.20, "Он быстр и бесстрашен, и чтобы сделать его своим спутником, тебе придётся воспитать в себе эти качества." }, { 21.27, "Во время боя ты поймёшь, как вы будете сражаться бок-о-бок." }, { 26.35, "Ведь вы с питомцем должны действовать очень слаженно, как единый организм." }, { 32.77, "Вот хлыст приручения." }, { 34.57, "Подчини себе охотника прерий, потренируйся." } } }, t = { d = 6.2, g = 1, v = "tauren-male", n = { m = 45, f = 46 }, c = { m = { { 0.00, "Да..." }, { 0.59, "Мать-Земля полагает, что ты готов к следующему уроку." } }, f = { { 0.00, "Да..." }, { 0.58, "Мать-Земля полагает, что ты готова к следующему уроку." } } } } },
    [6088] = { d = 39.9, v = "tauren-male", n = { x = 370 }, c = { x = { { 0.00, "Последним твоим заданием станет приручение жителя неба." }, { 5.03, "Перепелятник – непростой противник, но зато отличный союзник – атакует он внезапно и пугает врагов." }, { 13.81, "По воле Матери-Земли, по возвращении с победой, я наделю тебя искусством приручать любого зверя и делать его своим спутником; твоему питомцу придётся встретиться с теми же испытаниями, что и тебе, и вместе с тобой набираться опыта." }, { 34.33, "Я покажу тебе, как подзывать и отсылать его по собственной воле." } } }, t = { d = 26.4, g = 1, v = "tauren-male", n = { m = 232, f = 233 }, c = { m = { { 0.00, "Ты изучил всё, чему я могу тебя научить." }, { 3.87, "Пусть благословения Матери-Земли направляют тебя при выборе своего любимца." }, { 10.93, "Вот." }, { 11.35, "Теперь я дам тебе силу приручать животных, а также отпускать их на волю, когда ты сочтёшь нужным." }, { 20.43, "Используй свои новые способности с гордостью и уважай Мать-Землю." } }, f = { { 0.00, "Ты изучила всё, чему я могу тебя научить." }, { 3.86, "Пусть благословения Матери-Земли направляют тебя при выборе своего любимца." }, { 10.75, "Вот." }, { 11.16, "Теперь я дам тебе силу приручать животных, а также отпускать их на волю, когда ты сочтёшь нужным." }, { 20.01, "Используй свои новые способности с гордостью и уважай Мать-Землю." } } } } },
    [6089] = { d = 40.6, v = "tauren-male", n = { x = 387 }, c = { x = { { 0.00, "Теперь ты знаешь, как приручать питомца, но тебе надо научиться ещё и обучать его." }, { 7.20, "Отправляйся в Громовой Утёс." }, { 9.63, "Там тебе нужно будет поговорить с одним из наших самых уважаемых охотников, Хольтом Громовым Рогом." }, { 18.40, "Если он сочтёт тебя достойным знаний, то объяснит тебе, как обучать твоего нового питомца." }, { 26.31, "Хольт одолел многих могущественных и страшных зверей Азерота и сам повелевает сильными существами." }, { 34.77, "Его связь с Матерью-Землёй сильна, и он многому может научить." }, { 40.17, "Удачи." } } }, t = { d = 24.0, g = 1, v = "tauren-male#68", n = { m = 208, f = 208 }, c = { m = { { 0.00, "А, юный герой." }, { 1.32, "Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца." }, { 7.86, "Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падёт в бою." }, { 18.30, "Ступай, Мать-Земля ещё сведёт наши пути." }, { 21.80, "Поговорим позже." } }, f = { { 0.00, "А, юная героиня." }, { 1.53, "Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца." }, { 8.27, "Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падёт в бою." }, { 19.02, "Ступай, Мать-Земля ещё сведёт наши пути." }, { 22.64, "Поговорим позже." } } } } },
    [6101] = { d = 37.5, v = "nightelf-male#54", n = { x = 405 }, c = { x = { { 0.00, "Природа изменчива, но на неё вполне можно положиться." }, { 4.15, "Она предсказуема в том, что никогда не остаётся одной и той же, она всегда меняется." }, { 10.63, "Поручения, которые я тебе дам, помогут тебе увидеть и оценить различных существ, которые впоследствии смогут стать твоими спутниками." }, { 21.05, "Возьми этот хлыст приручения и приручи ночного саблезуба-охотника, которого ты найдёшь к югу отсюда." }, { 28.87, "Поупражняйся в своём охотничьем искусстве." }, { 32.11, "Таким образом ты начнёшь понимать сходства и различия творений природы." } } }, t = { d = 5.4, v = "nightelf-male#54", n = { x = 53 }, c = { x = { { 0.00, "Вижу в тебе обязательность и понимание всего, чему я научил тебя." } } } } },
    [6102] = { d = 42.0, v = "nightelf-male#54", n = { x = 451 }, c = { x = { { 0.00, "Тебе удалось приручить двух детей земли, и теперь тебе предстоит подружиться с обитателем неба." }, { 7.41, "При помощи этого хлыста приручи совиного визгуна, которого найдёшь к западу отсюда." }, { 13.84, "Испытай своё искусство, взяв в спутники эту могучую сову." }, { 18.27, "Когда вернёшься, я наделю тебя знаниями, которые понадобятся тебе для приручения любого животного, которого ты выберешь себе в спутники." }, { 28.72, "Твой спутник встретит лицом к лицу те же опасности, что и ты, и вместе с тобой будет набираться опыта." }, { 36.54, "Я также научу тебя, как призывать и отпускать по желанию твоего питомца." } } }, t = { d = 38.2, g = 1, v = "nightelf-male#54", n = { m = 367, f = 368 }, c = { m = { { 0.00, "Теперь ты знаешь всё, чему я мог тебя обучить." }, { 3.87, "Могу ли дать тебе ещё один совет?" }, { 6.70, "Хорошенько подумай прежде, чем выбрать первого питомца." }, { 11.31, "Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса?" }, { 18.01, "Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе." }, { 24.63, "Что же." }, { 25.22, "Ныне я дам тебе умение приручать животное, а также призывать и отпускать его, когда тебе будет нужно." }, { 33.78, "Гордись своими новыми умениями – ты их честно заслужил." } }, f = { { 0.00, "Теперь ты знаешь всё, чему я мог тебя обучить." }, { 3.78, "Могу ли дать тебе ещё один совет?" }, { 6.54, "Хорошенько подумай прежде, чем выбрать первого питомца." }, { 11.05, "Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса?" }, { 17.60, "Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе." }, { 24.07, "Что же." }, { 24.65, "Ныне я дам тебе умение приручать животное, а также призывать и отпускать его, когда тебе будет нужно." }, { 33.01, "Гордись своими новыми умениями – ты их честно заслужила." } } } } },
    [6103] = { d = 30.6, v = "nightelf-male#54", n = { x = 341 }, c = { x = { { 0.00, "Теперь ты знаешь, как приручать питомца, но тебе надо научиться ещё и обучать его." }, { 6.12, "Отправляйся в Дарнасс." }, { 7.78, "Там тебе нужно будет поговорить с одной из наших самых уважаемых охотниц, Иокастой." }, { 14.03, "Она объяснит тебе, как обучать твоего нового питомца, так что поторопись." }, { 19.48, "Хотя Иокаста и сурова, ей всегда приятно наблюдать за развитием способностей очередного охотника." }, { 26.66, "Держись с ней почтительно, и она воздаст добром." }, { 30.25, "Удачи." } } }, t = { d = 23.3, g = 1, v = "nightelf-female#52", n = { m = 267, f = 267 }, c = { m = { { 0.00, "Новоиспечённый герой?" }, { 1.47, "Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем." }, { 7.54, "Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке." }, { 16.81, "Запомни: всегда уважай равновесие и почитай природу." }, { 20.58, "Теперь ступай." }, { 21.67, "Попозже ещё поговорим." } }, f = { { 0.00, "Новоиспечённая героиня?" }, { 1.60, "Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем." }, { 7.68, "Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке." }, { 16.96, "Запомни: всегда уважай равновесие и почитай природу." }, { 20.74, "Теперь ступай." }, { 21.82, "Попозже ещё поговорим." } } } } },
    [6121] = { d = 30.8, g = 1, v = "nightelf-male#59", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Теперь, ты готов узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 6.04, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 12.91, "Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 22.45, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } }, f = { { 0.00, "Теперь, ты готова узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 6.18, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 13.12, "Однако мы должны быть уверены, что ты усвоила этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 22.84, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } } }, npc = { [270459] = { d = 30.6, g = 1, v = "nightelf-female", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Теперь, ты готов узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 5.84, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 12.47, "Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 21.68, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } }, f = { { 0.00, "Теперь, ты готова узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 6.35, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 12.98, "Однако мы должны быть уверены, что ты усвоила этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 22.99, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } } } } }, t = { d = 31.9, v = "nightelf-male#54", n = { x = 362 }, c = { x = { { 0.00, "Добро пожаловать, юный друид, рад видеть, что ты горишь желанием узнать о нейтрализации ядов." }, { 6.86, "Если в прошлом большинство друидов проходили заранее установленные испытания, то для твоей работы такого не понадобится." }, { 15.64, "В Аубердине вспышка отравления животных, и в тамошней деревне справиться с этим не могут." }, { 22.17, "Поэтому представитель деревни просил помощи у Лунной поляны, и мы направляем тебя к ним." }, { 28.64, "Это не учёба, а серьёзное задание, имей в виду." } } } } },
    [6122] = { d = 34.4, v = "nightelf-male#54", n = { x = 391 }, c = { x = { { 0.00, "Водопад Скалистый на Тёмном Берегу – основной источник питьевой воды для всего региона, но теперь я подозреваю, что именно оттуда распространяется отрава, поражающая местную фауну – особенно оленей." }, { 14.30, "Возьми эту пробирку, чтобы отобрать немного воды из устья пещеры." }, { 19.20, "Осторожнее – в пещере у водопада ныне поселилась опасная нага." }, { 23.77, "Как только наберёшь воды, доставь её Аландариан Песне Ночи в Аубердин." }, { 28.86, "Именно она просила нашей помощи, и ты поможешь ей разобраться с этой заразой." } } }, t = { d = 34.0, v = "nightelf-female#53", n = { x = 380 }, c = { x = { { 0.00, "Клянусь Элуной, какая омерзительная вода!" }, { 3.05, "Немудрено, что оленей поразил недуг." }, { 5.70, "Что-то заражает воду, и она в свою очередь поражает все грунтовые воды Тёмного Берега." }, { 11.99, "Больных оленей видели повсюду, не только у реки." }, { 15.55, "Даже если эта вода и есть основной источник расползающейся болезни, тут замешано что-то ещё." }, { 22.22, "Хочешь – верь, хочешь – не верь, но эта вода поможет нам найти исцеление." }, { 27.47, "А пока я буду исследовать жидкость, мне понадобится кое-что ещё, чтобы составить лекарство..." } } } } },
    [6123] = { d = 34.6, g = 1, v = "nightelf-female#53", n = { m = 387, f = 388 }, c = { m = { { 0.00, "Основой целительной мази для оленей послужит вода." }, { 3.70, "Для придания ей целительных свойств мне понадобится землекорень." }, { 8.18, "Травники знают, где его искать, так что, если нам не повезло и вы не травник, придётся найти кого-то, кто сможет помочь." }, { 16.74, "Для усиления воздействия мне нужны лунные грибы." }, { 20.24, "Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно." }, { 25.82, "В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будьте осторожны." } }, f = { { 0.00, "Основой целительной мази для оленей послужит вода." }, { 3.77, "Для придания ей целительных свойств мне понадобится землекорень." }, { 8.33, "Травники знают, где его искать, так что, если нам не повезло и вы не травница, придётся найти кого-то, кто сможет помочь." }, { 17.13, "Для усиления воздействия мне нужны лунные грибы." }, { 20.70, "Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно." }, { 26.39, "В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будьте осторожны." } } }, t = { d = 31.0, v = "nightelf-female#53", n = { x = 375 }, c = { x = { { 0.00, "Отлично, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось." }, { 8.73, "Изготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия." }, { 18.91, "Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот!" }, { 28.15, "А теперь позвольте мне приступить к работе!" } } } } },
    [6124] = { d = 35.9, v = "nightelf-female#53", n = { x = 428 }, c = { x = { { 0.00, "Мази, изготовленной из реактивов, которые вы принесли мне, хватит на десять доз." }, { 5.54, "Пока я работаю здесь, в деревне, пытаясь изготовить побольше этой мази, я хотела бы, чтобы вы помогли нам начать исцеление." }, { 14.16, "По всему Тёмному Берегу встречаются больные олени." }, { 17.69, "Используйте мазь для исцеления их недуга." }, { 20.52, "Я уверена, что Дендрит Блеск Звёзд из Лунной поляны захочет поговорить с вами, когда вы закончите." }, { 27.31, "Пожалуйста, передайте благодарность жителей Аубердина Кругу Кенария... и позвольте мне поблагодарить вас лично за вашу помощь!" } } }, t = { d = 38.1, g = 1, v = "nightelf-male#54", n = { m = 385, f = 385 }, c = { m = { { 0.00, "Вы хорошо сделали, что позаботились о больных оленях Тёмных берегов; это невольные жертвы порчи и осквернения, расползающихся по всему краю." }, { 10.99, "В Дарнассе есть те, кто признаёт наличие угрозы... и те, кто упорно игнорирует её всё усиливающиеся признаки." }, { 19.29, "Я надеюсь, что вы, – один из тех, кто не собирается надевать шоры и будет смотреть в лицо фактам." }, { 26.87, "Как бы там ни было, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы." } }, f = { { 0.00, "Вы хорошо сделали, что позаботились о больных оленях Тёмных берегов; это невольные жертвы порчи и осквернения, расползающихся по всему краю." }, { 11.20, "В Дарнассе есть те, кто признаёт наличие угрозы... и те, кто упорно игнорирует её всё усиливающиеся признаки." }, { 19.66, "Я надеюсь, что вы, – одна из тех, кто не собирается надевать шоры и будет смотреть в лицо фактам." }, { 27.39, "Как бы там ни было, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы." } } } } },
    [6125] = { d = 30.7, g = 1, v = "nightelf-male#54", n = { m = 309, f = 311 }, c = { m = { { 0.00, "Ты познал, что значит исцелять от действия яда без помощи духов." }, { 5.25, "Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами." }, { 13.79, "Тебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнасс." }, { 18.83, "Теперь, когда его ученик усвоил данный ему урок, он несомненно научит тебя новому могучему заклинанию." }, { 27.37, "До свидания, юный друид." }, { 29.41, "Мы ещё встретимся." } }, f = { { 0.00, "Ты познала, что значит исцелять от действия яда без помощи духов." }, { 5.26, "Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами." }, { 13.69, "Тебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнасс." }, { 18.66, "Теперь, когда его ученица усвоила данный ей урок, он несомненно научит тебя новому могучему заклинанию." }, { 27.09, "До свидания, юный друид." }, { 29.11, "Мы ещё встретимся." } } }, t = { d = 31.3, g = 1, v = "nightelf-male#59", n = { m = 346, f = 348 }, c = { m = { { 0.00, "С возвращением." }, { 1.14, "Я следил за твоими успехами с тех самых пор, как ты покинул нас, и, должен признаться, был изумлён, узнав о ситуации в Аубердине." }, { 10.54, "Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие." }, { 19.20, "Ты благородно поступил в трудной ситуации." }, { 22.35, "И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами." }, { 28.80, "Используй её во благо... во благо." } }, f = { { 0.00, "С возвращением." }, { 1.14, "Я следил за твоими успехами с тех самых пор, как ты покинула нас, и, должен признаться, был изумлён, узнав о ситуации в Аубердине." }, { 10.59, "Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие." }, { 19.23, "Ты благородно поступила в трудной ситуации." }, { 22.45, "И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами." }, { 28.88, "Используй её во благо... во благо." } } } } },
    [6126] = { d = 35.8, g = 1, v = "tauren-female", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Теперь, ты готов узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 6.96, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 14.88, "Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 25.88, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } }, f = { { 0.00, "Теперь, ты готова узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 7.21, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 15.13, "Однако мы должны быть уверены, что ты усвоила этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 26.75, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } } }, npc = { [3033] = { d = 39.7, g = 1, v = "tauren-male#67", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Теперь, ты готов узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 7.41, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 15.83, "Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 27.53, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } }, f = { { 0.00, "Теперь, ты готова узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 7.92, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 16.34, "Однако мы должны быть уверены, что ты усвоила этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 29.99, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } } } } }, t = { d = 30.1, v = "nightelf-male#54", n = { x = 304 }, c = { x = { { 0.00, "Привет тебе, мой юный друид, я рад, что ты жаждешь узнать, как изгонять из тела яд." }, { 6.70, "В старину друиды проходили заранее установленные испытания, но тебе этого делать не придётся." }, { 14.21, "В Перекрёстке и Степях вспышка отравлений животных, и справиться с ней там никак не могут." }, { 21.35, "Оттуда запросили помощи Лунной поляны, так что мы посылаем тебя." }, { 26.59, "Это не учёба, а серьёзное задание." }, { 29.29, "Помни это." } } } } },
    [6127] = { d = 36.2, v = "nightelf-male#54", n = { x = 407 }, c = { x = { { 0.00, "Вершина Багрового Тумана, что к северо-западу от Перекрёстка – самый вероятный источник распространения этой отравы." }, { 8.59, "На его вершине находятся озёра воды, влияющие на перемены погоды." }, { 13.49, "Подозреваю, что вода сейчас заражена демонопоклонниками из клана Пылающего Клинка." }, { 19.60, "Возьми этот пробоотборник и набери воды из озера у самой вершины." }, { 24.56, "Наполнив, доставь его Тонге Руническому Тотему в Перекрёсток." }, { 29.13, "Именно он и просил нашей помощи, и ты будешь работать вместе с ним над искоренением этой заразы." } } }, t = { d = 38.8, v = "tauren-male", n = { x = 386 }, c = { x = { { 0.00, "Клянусь предками, какая омерзительная вода!" }, { 3.60, "Немудрено, что газелей поразил недуг." }, { 6.69, "Что-то заражает воду, и она начинает разрушать экосистему северных Степей." }, { 12.86, "Больных газелей видели повсюду к северу от тутошней дороги с востока на запад." }, { 19.33, "Даже если эта вода и есть основной источник расползающейся болезни, тут замешано что-то ещё." }, { 26.90, "Эта вода, верь – не верь, поможет нам найти исцеление." }, { 31.31, "А пока я буду исследовать эту воду, мне понадобится кое-что ещё, чтобы составить лекарство..." } } } } },
    [6128] = { d = 36.7, g = 1, v = "tauren-male", n = { m = 354, f = 355 }, c = { m = { { 0.00, "Основой целебной мази для газелей послужит вода." }, { 4.17, "Для придания ей целебных свойств мне понадобится землекорень." }, { 9.18, "Травники знают, где его отыскать, так что если нам не повезло, и ты – не травник, придётся попросить кого-то о помощи." }, { 18.96, "Для силы воздействия мне нужны рога кодо – осколки и куски не подойдут." }, { 25.03, "Кодо живут в северной части Степей." }, { 28.14, "Убей несколько зверюг, заодно и природное равновесие восстановится." }, { 33.83, "Отпили у них рога и принеси мне." } }, f = { { 0.00, "Основой целебной мази для газелей послужит вода." }, { 4.20, "Для придания ей целебных свойств мне понадобится землекорень." }, { 9.24, "Травники знают, где его отыскать, так что если нам не повезло, и ты – не травница, придётся попросить кого-то о помощи." }, { 19.16, "Для силы воздействия мне нужны рога кодо – осколки и куски не подойдут." }, { 25.27, "Кодо живут в северной части Степей." }, { 28.40, "Убей несколько зверюг, заодно и природное равновесие восстановится." }, { 34.13, "Отпили у них рога и принеси мне." } } }, t = { d = 33.0, g = 1, v = "tauren-male", n = { m = 342, f = 344 }, c = { m = { { 0.00, "Отлично, ты принёс так много составляющих, что должно хватить на несколько больших доз мази – по крайней мере, положим начало исцелению." }, { 10.93, "Изготовление средств против ядов иногда бывает весьма сложным, ведь для нейтрализации каждого из них требуется отдельный антидот." }, { 21.28, "Здорово было бы научиться в любой момент лечить отравления, не беспокоясь о конкретных составляющих противоядия!" }, { 30.32, "Ладно, пора браться за работу!" } }, f = { { 0.00, "Отлично, ты принесла так много составляющих, что должно хватить на несколько больших доз мази – по крайней мере, положим начало исцелению." }, { 11.16, "Изготовление средств против ядов иногда бывает весьма сложным, ведь для нейтрализации каждого из них требуется отдельный антидот." }, { 21.52, "Здорово было бы научиться в любой момент лечить отравления, не беспокоясь о конкретных составляющих противоядия!" }, { 30.56, "Ладно, пора браться за работу!" } } } } },
    [6129] = { d = 38.1, g = 1, v = "tauren-male", n = { m = 380, f = 382 }, c = { m = { { 0.00, "Мне удалось сделать десять доз целебной мази." }, { 3.63, "Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотел бы, чтобы ты помог нам лечить бедных зверей." }, { 12.67, "По всей северной части Степей бродят больные газели." }, { 16.87, "Исцели их недуг при помощи этой мази." }, { 19.93, "Я уверен, что Дендрит Блеск Звёзд на Лунной поляне захочет поговорить с тобой, когда ты закончишь." }, { 27.61, "Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!" } }, f = { { 0.00, "Мне удалось сделать десять доз целебной мази." }, { 3.76, "Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотел бы, чтобы ты помогла нам лечить бедных зверей." }, { 13.26, "По всей северной части Степей бродят больные газели." }, { 17.61, "Исцели их недуг при помощи этой мази." }, { 20.77, "Я уверен, что Дендрит Блеск Звёзд на Лунной поляне захочет поговорить с тобой, когда ты закончишь." }, { 28.73, "Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!" } } }, t = { d = 36.3, v = "nightelf-male#54", n = { x = 368 }, c = { x = { { 0.00, "Вы хорошо сделали, что позаботились о больных газелях Степей; это невольные жертвы порчи и осквернения, расползающихся по всему краю." }, { 10.93, "Вы, таурены, лучше прочих постигаете мудрость Кенария." }, { 15.43, "И Вы, как и мудрейшие из Громового Утёса, постигаете, что необходимость достичь равновесия превыше искусственных расовых границ." }, { 25.69, "Так или иначе, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы." } } } } },
    [6130] = { d = 31.1, g = 1, v = "nightelf-male#54", n = { m = 314, f = 316 }, c = { m = { { 0.00, "Ты познал, что значит исцелять от действия яда без помощи духов." }, { 5.19, "Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами." }, { 13.64, "Тебе следует вернуться к Тюраку Руническому Тотему в Громовой Утёс." }, { 19.05, "Теперь, когда его ученик усвоил данный ему урок, он несомненно научит тебя новому могучему заклинанию." }, { 27.49, "До свидания, юный друид." }, { 29.51, "Мы ещё встретимся." } }, f = { { 0.00, "Ты познала, что значит исцелять от действия яда без помощи духов." }, { 5.31, "Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами." }, { 13.82, "Тебе следует вернуться к Тюраку Руническому Тотему в Громовой Утёс." }, { 19.27, "Теперь, когда его ученица усвоила данный ей урок, он несомненно научит тебя новому могучему заклинанию." }, { 27.78, "До свидания, юный друид." }, { 29.82, "Мы ещё встретимся." } } }, t = { d = 39.2, g = 1, v = "tauren-male#67", n = { m = 348, f = 350 }, c = { m = { { 0.00, "С возвращением." }, { 1.43, "Я следил за твоими успехами с тех самых пор, как ты покинул нас, и, должен признаться, был изумлён, узнав о ситуации в Перекрёстке." }, { 13.29, "Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие." }, { 24.14, "Ты благородно поступил в трудной ситуации." }, { 28.09, "И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами." }, { 36.17, "Используй её во благо... во благо." } }, f = { { 0.00, "С возвращением." }, { 1.38, "Я следил за твоими успехами с тех самых пор, как ты покинула нас, и, должен признаться, был изумлён, узнав о ситуации в Перекрёстке." }, { 12.94, "Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие." }, { 23.43, "Ты благородно поступила в трудной ситуации." }, { 27.34, "И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами." }, { 35.15, "Используй её во благо... во благо." } } } } },
    [6131] = { d = 40.3, v = "creature/furbolg", n = { x = 366 }, c = { x = { { 0.58, "Древобрюхи – единственное фурболгское племя, не затронутое порчей." }, { 6.13, "Однако, нынче многие расы без разбору убивают всех фурболгов подряд." }, { 11.98, "И потому фурболгов из племени Древобрюха осталось так мало." }, { 17.00, "Хочешь заслужить наше доверие?" }, { 19.66, "Изгони из Осквернённого леса поражённых порчей фурболгов Мёртвого Леса, и в один прекрасный день мы признаем тебя союзником." }, { 29.93, "Ты найдёшь первое племя Мёртвого Леса – воинов, следопытов и садовников – к западу от меня." } } } },
    [6132] = { d = 34.7, v = "goblin-female#63", n = { x = 400 }, c = { x = { { 0.00, "Вытащи меня отсюда!" }, { 1.41, "Я отправилась к Долине Копий, чтобы поговорить с Мародинами." }, { 5.52, "Мне казалось, с ними можно вести кое-какие дела..." }, { 9.08, "Но они не желают говорить со мной!" }, { 11.42, "Мне кажется, они... они хотят съесть меня!" }, { 14.36, "Только вытащи меня отсюда – вот увидишь, мой брат Хормиц тебе кучу денег отвалит!" }, { 20.01, "А найти-то его несложно: он в нашем лагере, к востоку отсюда, там ещё Кладбище кодо рядом." }, { 26.21, "Нам лучше поторопиться: буквально пару минут назад я слышала, как два кентавра говорили, что нужно собрать дрова для готовки..." } } }, t = { d = 12.2, g = 1, v = "goblin-male", n = { m = 141, f = 142 }, c = { m = { { 0.00, "Моя сестра Мелисса предупредила меня о твоём приходе." }, { 3.75, "Хочу тебя поблагодарить за то, что вытащил её из очередной беды." }, { 8.19, "Правда, боюсь, она уже успела ввязаться во что-то новое..." } }, f = { { 0.00, "Моя сестра Мелисса предупредила меня о твоём приходе." }, { 3.73, "Хочу тебя поблагодарить за то, что вытащила её из очередной беды." }, { 8.21, "Правда, боюсь, она уже успела ввязаться во что-то новое..." } } } } },
    [6133] = { d = 33.9, g = 1, v = "creature/nathanos", n = { x = 335 }, c = { m = { { 0.00, "Высшие эльфы в Сторожке Кель'Литиен присвоили себе кое-что, что принадлежит мне, герой." }, { 6.84, "Это документ, описывающий мою смертную жизнь." }, { 10.44, "Нет, к тебе его содержимое не имеет никакого отношения – даже не вздумай сунуть туда нос!" }, { 17.49, "Твоё дело маленькое, насекомое – принеси мне документ!" }, { 21.72, "И имей в виду, тупица, я хочу, чтобы эти негодяи пожалели, что наложили свои лапы на мою частную собственность!" }, { 30.60, "Нанеси им как можно больший ущерб!" } }, f = { { 0.00, "Высшие эльфы в Сторожке Кель'Литиен присвоили себе кое-что, что принадлежит мне, героиня." }, { 7.10, "Это документ, описывающий мою смертную жизнь." }, { 10.76, "Нет, к тебе его содержимое не имеет никакого отношения – даже не вздумай сунуть туда нос!" }, { 17.93, "Твоё дело маленькое, насекомое – принеси мне документ!" }, { 22.24, "И имей в виду, тупица, я хочу, чтобы эти негодяи пожалели, что наложили свои лапы на мою частную собственность!" }, { 31.27, "Нанеси им как можно больший ущерб!" } } }, t = { d = 7.4, v = "creature/nathanos", n = { x = 88 }, c = { x = { { 0.00, "Надеюсь, тебе хватило ума не совать свой нос в реестр." }, { 3.82, "С твоей стороны это было бы равносильно самоубийству." } } } } },
    [6134] = { d = 35.0, v = "goblin-male", n = { x = 401 }, c = { x = { { 0.00, "На юго-востоке есть местность, именуемая Долиной Костей." }, { 4.04, "Долину эту населяют призраки кентавров племени Маграм." }, { 8.02, "Жутковато звучит, верно?" }, { 9.82, "Подумай, как это пугает Маграмов!.." }, { 12.39, "Если бы нам удалось собрать энергию призраков – только представь, что за это дали бы кентавры!.." }, { 19.25, "Вот, возьми эти призрачные магниты." }, { 21.82, "Если поставишь такой магнит между двух скелетов, Мёртвых Гигантов, то призраки потянутся к нему." }, { 28.69, "Отойди подальше, уничтожь призраков и собери их эктоплазму: позже мы продадим её Маграмам." } } }, t = { d = 15.0, g = 1, v = "goblin-male", n = { m = 155, f = 157 }, c = { m = { { 0.00, "А вот и она!.." }, { 1.10, "Похоже, ты и сам в эктоплазме перемазался." }, { 4.26, "Склизкая штука, верно?" }, { 6.04, "Что ж, прими мою благодарность." }, { 8.45, "Эта дрянь стоит целого состояния..." }, { 11.19, "Конечно, если удастся убедить кентавров её купить!" } }, f = { { 0.00, "А вот и она!.." }, { 1.09, "Похоже, ты и сама в эктоплазме перемазалась." }, { 4.43, "Склизкая штука, верно?" }, { 6.20, "Что ж, прими мою благодарность." }, { 8.58, "Эта дрянь стоит целого состояния..." }, { 11.31, "Конечно, если удастся убедить кентавров её купить!" } } } } },
    [6135] = { d = 26.5, g = 1, v = "creature/nathanos", n = { m = 276, f = 277 }, c = { m = { { 0.00, "Пока тебе удаётся с горем пополам выполнять мои поручения." }, { 4.65, "Пора бы заставить тебя сделать что-нибудь посложнее." }, { 8.81, "Да, тупица, ты дозрел до настоящей работёнки." }, { 12.26, "Вот что, выследи и убей Тенекрыла – это чудовищная летучая мышь-альбинос, которая хозяйничает в землях к северу отсюда." }, { 21.56, "И принеси мне клок его белой шерсти – чтоб я знал, что ты не врёшь!" } }, f = { { 0.00, "Пока тебе удаётся с горем пополам выполнять мои поручения." }, { 4.61, "Пора бы заставить тебя сделать что-нибудь посложнее." }, { 8.73, "Да, тупица, ты дозрела до настоящей работёнки." }, { 12.22, "Вот что, выследи и убей Тенекрыла – это чудовищная летучая мышь-альбинос, которая хозяйничает в землях к северу отсюда." }, { 21.44, "И принеси мне клок его белой шерсти – чтоб я знал, что ты не врёшь!" } } }, t = { d = 6.6, v = "creature/nathanos", n = { x = 65 }, c = { x = { { 0.00, "Неплохая работа, тупица." }, { 2.04, "Посмотрим, что можно сварганить для тебя из этого меха..." } } } } },
    [6136] = { d = 36.0, g = 1, v = "creature/nathanos", n = { m = 365, f = 369 }, c = { m = { { 0.00, "За лагерем Серебряного Рассвета и Часовней Последней Надежды, к западу от Северного дола обитает огромный червь, Мерзкослиз." }, { 9.85, "Я потерял целые батальоны в попытках уничтожить его." }, { 14.09, "Его размеры невообразимы!" }, { 16.18, "Чем больше он ест, тем больше растёт..." }, { 19.20, "Хотя я, в общем-то, мало волнуюсь по поводу того, сожрёт ли тебя червь, должен признать, что предпочёл бы, чтобы ты вышел победителем." }, { 29.77, "Учти, Мерзкослиз особенно охотно жрёт тех, кто попытался напасть на него." } }, f = { { 0.00, "За лагерем Серебряного Рассвета и Часовней Последней Надежды, к западу от Северного дола обитает огромный червь, Мерзкослиз." }, { 9.90, "Я потерял целые батальоны в попытках уничтожить его." }, { 14.17, "Его размеры невообразимы!" }, { 16.27, "Чем больше он ест, тем больше растёт..." }, { 19.30, "Хотя я, в общем-то, мало волнуюсь по поводу того, сожрёт ли тебя червь, должен признать, что предпочёл бы, чтобы ты вышла победительницей." }, { 30.22, "Учти, Мерзкослиз особенно охотно жрёт тех, кто попытался напасть на него." } } }, t = { d = 9.2, v = "creature/nathanos", n = { x = 80 }, c = { x = { { 0.00, "О, да ты делаешь успехи!" }, { 2.30, "Такими темпами скоро получишь повышение – от полного имбецила до недоумка." } } } } },
    [6141] = { d = 28.6, v = "human-male", n = { x = 331 }, c = { x = { { 0.00, "Антон, мой собрат по оружию, услышал вести о нашествии нежити в далёком Калимдоре, в тех землях, что называются Пустошами." }, { 8.47, "Конечно же, он немедленно собрался в путь, чтобы покончить с этой угрозой!" }, { 13.66, "Он ищет отважных и решительных спутников – тех, у кого хватит храбрости сражаться с ним плечом к плечу." }, { 20.86, "Если ты хранишь чистоту в своём сердце, разыщи брата Антона в городе, носящем имя Высота Найджела, в Пустошах." } } }, t = { d = 11.1, g = 1, v = "human-male", n = { m = 119, f = 119 }, c = { m = { { 0.00, "Я получил вести о помощи, грядущей с востока." }, { 3.32, "Не о тебе ли шла речь?" }, { 4.88, "Ты пришёл сюда, дабы помочь Алым в нашем благородном походе?" }, { 9.31, "Если это так, то слушай..." } }, f = { { 0.00, "Я получил вести о помощи, грядущей с востока." }, { 3.25, "Не о тебе ли шла речь?" }, { 4.79, "Ты пришла сюда, дабы помочь Алым в нашем благородном походе?" }, { 9.19, "Если это так, то слушай..." } } } } },
    [6142] = { d = 33.0, g = 1, v = "troll-female#135", n = { m = 337, f = 339 }, c = { m = { { 0.00, "Судя по виду, герой, ты – заядлый рыбак!" }, { 3.12, "Обожаю ловить рыбу, всю жизнь этим занимаюсь." }, { 6.59, "Можешь мне поверить, нет лучшей наживки, чем мясо мягкокожего моллюска: рыба просто не может против неё устоять, если ты понимаешь, о чём я." }, { 17.12, "На север отсюда, неподалёку от берега, есть потерпевший крушение корабль: так вот, вокруг него эти моллюски так и кишат!" }, { 26.08, "Принесёшь мне десять кусочков мяса моллюска – а взамен я тебе дам кое-что полезное..." } }, f = { { 0.00, "Судя по виду, героиня, ты – заядлая рыбачка!" }, { 3.44, "Обожаю ловить рыбу, всю жизнь этим занимаюсь." }, { 6.95, "Можешь мне поверить, нет лучшей наживки, чем мясо мягкокожего моллюска: рыба просто не может против неё устоять, если ты понимаешь, о чём я." }, { 17.63, "На север отсюда, неподалёку от берега, есть потерпевший крушение корабль: так вот, вокруг него эти моллюски так и кишат!" }, { 26.72, "Принесёшь мне десять кусочков мяса моллюска – а взамен я тебе дам кое-что полезное..." } } }, t = { d = 17.5, v = "troll-female#135", n = { x = 187 }, c = { x = { { 0.00, "Это просто великолепно!.." }, { 1.93, "Когда я спросила у знахаря, как лечить головную боль, он мне ответил: Май'Лахия, детка, попробуй половить рыбку в мутной воде; увидишь – тебе сразу полегчает!" }, { 13.67, "Ох, как подумаю – мне и правда сразу легче становится!" } } } } },
    [6143] = { d = 37.7, g = 1, v = "troll-male#78", n = { m = 388, f = 389 }, c = { m = { { 0.00, "Может, ты слышал, может, нет..." }, { 2.31, "Мы с командой рыбачили неподалёку от острова Раназьяр, к северу от разбитого корабля на северном побережье." }, { 10.05, "Мы всегда там рыбачили, сколько я себя помню – а теперь я ни о чём другом не могу думать, кроме как о мести за своих друзей..." }, { 19.30, "Однажды утром на нас напали наги." }, { 21.81, "Они убили всех, кроме меня!.." }, { 24.06, "Я не могу вынести бремени этой вины, герой, пойми меня: ты нужен мне, чтобы расправиться с проклятыми нагами." }, { 32.19, "Поверь, я хорошо вознагражу тебя." }, { 34.70, "Ты ведь возьмёшься за это дело?" } }, f = { { 0.00, "Может, ты слышала, может, нет..." }, { 2.42, "Мы с командой рыбачили неподалёку от острова Раназьяр, к северу от разбитого корабля на северном побережье." }, { 10.30, "Мы всегда там рыбачили, сколько я себя помню – а теперь я ни о чём другом не могу думать, кроме как о мести за своих друзей..." }, { 19.72, "Однажды утром на нас напали наги." }, { 22.28, "Они убили всех, кроме меня!.." }, { 24.57, "Я не могу вынести бремени этой вины, героиня, пойми меня: ты нужна мне, чтобы расправиться с проклятыми нагами." }, { 32.98, "Поверь, я хорошо вознагражу тебя." }, { 35.54, "Ты ведь возьмёшься за это дело?" } } }, t = { d = 28.2, v = "troll-male#78", n = { x = 260 }, c = { x = { { 0.00, "Ты говоришь, эти мерзкие твари мертвы?" }, { 3.38, "Да, месть сладка..." }, { 4.99, "Но в моём сердце по-прежнему пустота, которой ничто не заполнит." }, { 10.44, "Я посвящу всю свою жизнь тому, чтобы извести нагов под корень – весь их род до последнего змеёныша!.." }, { 18.88, "Вот, дружище, держи свою награду, как я и обещал – хотя она ничтожно мала в сравнении с моей благодарностью..." } } } } },
    [6144] = { d = 30.5, g = 1, v = "creature/nathanos", n = { x = 298 }, c = { m = { { 0.00, "Вот что, герой, поступил приказ по армии." }, { 3.42, "Сам Вариматрас требует, чтобы я прислал ему самых способных солдат в Подгород для выполнения крайне сложной операции." }, { 13.17, "Увы, самые достойные и способные давно погибли, а вместо них я располагаю кучкой жалких недоумков." }, { 21.28, "*Натанос окидывает вас ледяным взглядом*" }, { 24.48, "Предстанешь перед Вариматрасом в Подгороде." }, { 27.72, "Смотри, не опозорь меня, герой!" } }, f = { { 0.00, "Вот что, героиня, поступил приказ по армии." }, { 3.63, "Сам Вариматрас требует, чтобы я прислал ему самых способных солдат в Подгород для выполнения крайне сложной операции." }, { 13.52, "Увы, самые достойные и способные давно погибли, а вместо них я располагаю кучкой жалких недоумков." }, { 21.76, "*Натанос окидывает вас ледяным взглядом*" }, { 24.88, "Предстанешь перед Вариматрасом в Подгороде." }, { 28.09, "Смотри, не опозорь меня, героиня!" } } }, t = { d = 19.1, v = "named/2425", n = { x = 198 }, c = { x = { { 0.00, "Верховный рыцарь восседает в Бастионе Алого ордена пока его войска хозяйничают в наших землях, сея скверну и разрушения." }, { 9.97, "Тёмная Госпожа повелела мне разобраться с этим червяком раз и навсегда." }, { 15.68, "Ты заставишь их расплатиться за свои деяния." } } } } },
    [6145] = { d = 35.8, g = 1, v = "named/2425", n = { x = 354 }, c = { m = { { 0.00, "Тело не может жить без головы, а голова без тела." }, { 3.80, "Оборона сил Алого ордена в Стратхольме практически несокрушима." }, { 8.65, "Однако мы можем обезглавить их армию." }, { 11.55, "Мои верные стражи смерти уже давно собирают сведения о деятельности Алого ордена за пределами Стратхольма." }, { 19.85, "Каждый день им присылают инструкции из центрального штаба в Длани Тира." }, { 25.31, "Мы должны перехватить их, герой!" }, { 27.80, "Убей курьера из Багрового Легиона и забери бумагу." }, { 31.75, "Отдашь её Натаносу." } }, f = { { 0.00, "Тело не может жить без головы, а голова без тела." }, { 4.10, "Оборона сил Алого ордена в Стратхольме практически несокрушима." }, { 9.32, "Однако мы можем обезглавить их армию." }, { 12.45, "Мои верные стражи смерти уже давно собирают сведения о деятельности Алого ордена за пределами Стратхольма." }, { 21.39, "Каждый день им присылают инструкции из центрального штаба в Длани Тира." }, { 27.28, "Мы должны перехватить их, героиня!" }, { 30.11, "Убей курьера из Багрового Легиона и забери бумагу." }, { 34.36, "Отдашь её Натаносу." } } }, t = { d = 8.6, v = "creature/nathanos", n = { x = 94 }, c = { x = { { 0.00, "Отлично!" }, { 1.66, "Наконец-то!" }, { 2.80, "Наконец-то у меня есть возможность уничтожить Алого Оракула!" } } } } },
    [6146] = { d = 38.3, g = 1, v = "creature/nathanos", n = { x = 360 }, c = { m = { { 0.00, "Я тут немного подрихтовал приказ." }, { 2.75, "Если наша маленькая уловка сработает, Алый Оракул на некоторое время окажется почти без защиты." }, { 10.76, "Тут-то мы и нанесём удар!" }, { 12.84, "Теперь слушай внимательно, герой." }, { 15.66, "Доставишь приказ лорду-рыцарю Вальдермару." }, { 19.22, "Что значит как?!" }, { 20.56, "Лично в руки, тупица!" }, { 22.41, "Держи приказ и это гнилое яблоко – съешь его, когда войдёшь в город." }, { 27.71, "Оно... э-э... придаст тебе более приятный для человеческого глаза вид." }, { 34.45, "Запомни, лично в руки лорду-рыцарю Вальдермару!" } }, f = { { 0.00, "Я тут немного подрихтовал приказ." }, { 2.68, "Если наша маленькая уловка сработает, Алый Оракул на некоторое время окажется почти без защиты." }, { 10.51, "Тут-то мы и нанесём удар!" }, { 12.55, "Теперь слушай внимательно, героиня." }, { 15.45, "Доставишь приказ лорду-рыцарю Вальдермару." }, { 18.93, "Что значит как?!" }, { 20.23, "Лично в руки, тупица!" }, { 22.04, "Держи приказ и это гнилое яблоко – съешь его, когда войдёшь в город." }, { 27.63, "Оно... э-э... придаст тебе более приятный для человеческого глаза вид." }, { 33.68, "Запомни, лично в руки лорду-рыцарю Вальдермару!" } } }, t = { d = 5.0, v = "human-male", n = { x = 51 }, c = { x = { { 0.00, "Где тебя носило так долго?" }, { 2.10, "Я уж думал, тебя схватили твари Плети!" } } } } },
    [6147] = { d = 17.3, v = "human-male", n = { x = 201 }, c = { x = { { 0.00, "Верховный рыцарь прислал очень странный приказ..." }, { 3.64, "Однако приказы не обсуждаются." }, { 5.85, "Возвращайся в Бастион Алого ордена и сообщи, что Оракул выдвигается немедленно." }, { 11.57, "Мы приложим все усилия, чтобы доставить его в Стратхольм в целости и сохранности." } } }, t = { d = 9.6, g = 1, v = "creature/nathanos", n = { x = 69 }, c = { m = { { 0.00, "Болваны!" }, { 0.88, "Они ни о чём не догадались!" }, { 3.51, "Ну, готовься, герой." }, { 5.52, "Настало время нанести решающий удар!" } }, f = { { 0.00, "Болваны!" }, { 0.91, "Они ни о чём не догадались!" }, { 3.65, "Ну, готовься, героиня." }, { 5.94, "Настало время нанести решающий удар!" } } } } },
    [6148] = { d = 31.8, v = "creature/nathanos", n = { x = 326 }, c = { x = { { 0.00, "Деметрия – главный советник верховного рыцаря." }, { 3.75, "Её величают Оракулом за её сверхъестественные способности." }, { 8.29, "Она неоднократно оказывала помощь Алому ордену в боях с Плетью." }, { 13.47, "Посмотрим, в самом ли деле ей открыто будущее..." }, { 17.37, "Уверен, она предвидела, что её ждут неприятности." }, { 21.26, "Вот ты их ей и обеспечишь!" }, { 23.27, "Выследи Оракула и убей её." }, { 25.44, "Полагаю, прямо сейчас они выдвигаются из Длани Тира." }, { 29.76, "Не подведи меня, насекомое!" } } }, t = { d = 8.2, g = 1, v = "creature/nathanos", n = { m = 69, f = 70 }, c = { m = { { 0.00, "От этого удара они нескоро оправятся!" }, { 3.66, "Отлично!" }, { 4.51, "Ты заслужил моё доверие и эту награду!" } }, f = { { 0.00, "От этого удара они нескоро оправятся!" }, { 3.73, "Отлично!" }, { 4.59, "Ты заслужила моё доверие и эту награду!" } } } } },
    [6161] = { d = 30.7, v = "narrator", n = { x = 320 }, c = { x = { { 0.00, "Записи Ракмора рассказывают о том, как во время плаванья к Крепости Оперённой Луны его корабль был атакован морскими тварями." }, { 9.84, "Чтобы не дать врагу завладеть его сокровищем, Ракмор спрятал сундук на острове Раназьяр." }, { 16.90, "Открыть сундук можно только двумя ключами, золотым и серебряным." }, { 22.10, "Они были утрачены, но если разыскать и сундук, и оба ключа – кто знает, какие сокровища откроются счастливцу?" } } }, t = { d = 5.5, v = "narrator", n = { x = 42 }, c = { x = { { 0.00, "Сундук открывается." }, { 2.24, "Перед вами сокровище Ракмора!" } } } } },
    [6162] = { d = 43.0, g = 1, v = "orc-female#58", n = { m = 435, f = 437 }, c = { m = { { 0.00, "Мой супруг ради чести нашего клана отправился в Осквернённый лес, чтобы сразиться с Советом Теней и прочими мерзостными тварями!" }, { 10.22, "Он несколько раз избегал смерти." }, { 12.81, "Потом я получила письмо от него, в котором он говорил, что некий друид попросил у него помощи против огромного поражённого порчей фурболга по имени Рор – и с тех пор я не слышала больше ни о муже, ни о друиде." }, { 29.37, "Я хочу, чтобы ты принёс мне отрубленную когтистую лапу этого Рора!" }, { 34.70, "Я жажду мести за моё вдовство!" }, { 37.15, "Эта тварь, как я знаю, засела где-то на юге, возле границы Ясеневого леса." } }, f = { { 0.00, "Мой супруг ради чести нашего клана отправился в Осквернённый лес, чтобы сразиться с Советом Теней и прочими мерзостными тварями!" }, { 9.83, "Он несколько раз избегал смерти." }, { 12.32, "Потом я получила письмо от него, в котором он говорил, что некий друид попросил у него помощи против огромного поражённого порчей фурболга по имени Рор – и с тех пор я не слышала больше ни о муже, ни о друиде." }, { 28.25, "Я хочу, чтобы ты принесла мне отрубленную когтистую лапу этого Рора!" }, { 33.58, "Я жажду мести за моё вдовство!" }, { 35.93, "Эта тварь, как я знаю, засела где-то на юге, возле границы Ясеневого леса." } } }, t = { d = 18.2, v = "orc-female#58", n = { x = 179 }, c = { x = { { 0.00, "Ты держишь слово – честь для меня познакомиться с тобой." }, { 4.53, "Мой муж погиб в бою – он гордился бы тобой." }, { 8.03, "Но я не смогла бы спокойно спать, если б не знала, что тварь, обрекшая меня на одиночество, заплатила за всё!" }, { 16.64, "Ещё раз спасибо тебе." } } } } },
    [6163] = { d = 44.8, v = "creature/nathanos", n = { x = 424 }, c = { x = { { 0.00, "Я не выстоял." }, { 1.15, "На этом самом месте я когда-то держал оборону Лордерона..." }, { 6.21, "Бесчисленное воинство Плети прошло волной по моей ферме, уничтожив всё живое на своём пути." }, { 14.04, "Тварь." }, { 14.58, "Мерзость." }, { 15.42, "Это чудовище нависло надо мной, и из его разверстой грудной клетки свисали внутренности." }, { 23.02, "Я очнулся уже нежитью – беспомощной и безвольной игрушкой в руках Плети." }, { 29.23, "Сознанием моим управляла воля Короля-лича." }, { 32.99, "А потом она освободила меня..." }, { 35.67, "Я ждал, я надеялся и наконец обрёл свободу." }, { 39.28, "Теперь я хочу отомстить чудовищу, забравшему мою жизнь." }, { 44.04, "Убей его!" } } }, t = { d = 13.3, g = 1, v = "creature/nathanos", n = { m = 140, f = 142 }, c = { m = { { 0.00, "Надеюсь, ты заставил тварь умолять о пощаде?" }, { 4.01, "Повешу эту голову над камином." }, { 7.52, "Хорошая работа." }, { 8.99, "Ты заслужил моё уважение." }, { 11.20, "*Натанос отдаёт честь*" } }, f = { { 0.00, "Надеюсь, ты заставила тварь умолять о пощаде?" }, { 3.88, "Повешу эту голову над камином." }, { 7.23, "Хорошая работа." }, { 8.62, "Ты заслужила моё уважение." }, { 10.80, "*Натанос отдаёт честь*" } } } } },
    [6164] = { d = 22.7, v = "scourge-male#144", n = { x = 197 }, c = { x = { { 0.00, "Пожалуй, я готов открыть лавку..." }, { 3.04, "О нет!" }, { 3.60, "Моя книга рецептов!" }, { 5.44, "Мне не обойтись без неё!" }, { 7.52, "Кажется я оставил её где-то в городе... да, видимо, в таверне, в которой останавливался!" }, { 15.28, "Принеси мне мою книгу, о умоляю, принеси мне её!" }, { 19.60, "Ты увидишь, цены у меня СУМАСШЕДШИЕ!" } } }, t = { d = 6.2, v = "scourge-male#144", n = { x = 42 }, c = { x = { { 0.00, "Вот она!" }, { 1.08, "Какое счастье!" }, { 2.90, "Это безумно счастливый день!" } } } } },
    [6181] = { d = 34.6, v = "human-male", n = { x = 443 }, c = { x = { { 0.00, "Хотя мы не получаем серьёзной помощи напрямую из Штормграда, у меня в городе есть знакомый, снабжающий нас доспехами." }, { 7.42, "Зовут его Озрик Штранг." }, { 8.98, "Его магазин, \"Ограниченная неуязвимость\", находится в Старом городе." }, { 13.39, "Наши запасы доспехов заканчиваются, и я должен связаться с Озриком, чтобы попросить ещё." }, { 19.07, "Можете ли вы передать ему эту записку?" }, { 21.62, "Быстрее всего добраться до Штормграда можно с помощью Тора, нашего укротителя грифонов." }, { 27.30, "Он находится прямо у подножия этого холма." }, { 30.08, "Приходите к нему с моей запиской, а затем летите на грифоне в Штормград." } } }, t = { d = 6.5, v = "human-male", n = { x = 83 }, c = { x = { { 0.00, "Вам нужно доставить эту записку в Штормград?" }, { 2.90, "Это не проблема, вы можете взять одного из моих грифонов!" } } } } },
    [6182] = { d = 34.4, v = "creature/bolvar", n = { x = 385 }, c = { x = { { 0.00, "Натанос Маррис был первым и последним человеком-предводителем следопытов." }, { 5.44, "Учеником Сильваны Ветрокрылой, ныне королевы-банши Отрёкшихся." }, { 10.08, "Мы думали, что Натанос погиб в бою при защите Лордерона пять лет назад." }, { 15.39, "Хотя его тело не было обнаружено, считалось, что он не сумел выбраться из Восточных Чумных земель." }, { 22.79, "Матиас Шоу изучил обстоятельства его исчезновения и у него может быть какая-то информация." }, { 29.57, "Доложитесь ему немедленно." }, { 31.59, "Он обитает в Старом городе, в казармах." } } }, t = { d = 13.9, v = "human-male", n = { x = 176 }, c = { x = { { 0.00, "После появления сообщений о необычной активности Отрёкшихся в Восточных Чумных землях туда были посланы агенты ШРУ для расследования ситуации." }, { 9.99, "Результаты этого расследования оказались весьма тревожными." } } } } },
    [6183] = { d = 32.2, v = "human-male", n = { x = 377 }, c = { x = { { 0.00, "Пятеро моих лучших полевых агентов занимались делом Марриса." }, { 4.33, "Вернулся только один, и тот через три дня умер во сне." }, { 8.10, "Та скудная информация, которую удалось из него вытрясти, звучала несусветной чушью." }, { 13.93, "Мы разобрали лишь два слова: \"Натанос\" и \"Гнилостень\"." }, { 17.63, "У меня не хватает сотрудников, чтобы продолжить это расследование, и в \"Чёрном Вороне\" нам не помогут." }, { 24.66, "Мы должны докопаться до сути, чтобы хотя бы принести какое-то утешение семьям погибших." }, { 30.81, "Вы окажете нам помощь?" } } }, t = { d = 8.7, v = "human-male", n = { x = 84 }, c = { x = { { 0.00, "*Матиас кивает.*" }, { 1.52, "Я и не сомневался, что Болвар пришлёт мне честных и благородных людей – самых преданных солдат Альянса." } } } } },
    [6184] = { d = 28.0, v = "human-male", n = { x = 326 }, c = { x = { { 0.00, "Единственные сведения, которыми мы сейчас располагаем – это то, что Натаноса Марриса, возможно, убил этот тип по имени \"Гнилостень\"." }, { 9.13, "Мы допускаем, что тот же \"Гнилостень\" расправился и с моими агентами." }, { 13.82, "Флинт Тенемор, ещё один сотрудник ШРУ, находится в лагере на Берегу Промозглого Ветра в Западных Чумных землях." }, { 21.83, "Найдите его." }, { 22.76, "Он расскажет вам о текущей ситуации в Чумных землях и даст задание." }, { 27.39, "Удачи вам." } } }, t = { d = 6.2, v = "human-male#50", n = { x = 64 }, c = { x = { { 0.00, "Ваше первое задание будет очень простым." }, { 3.22, "Уйти – и вернуться." }, { 4.73, "Провести разведку..." } } } } },
    [6185] = { d = 31.0, v = "human-male#50", n = { x = 344 }, c = { x = { { 0.00, "Говорю же, первое задание – разведывательное." }, { 3.39, "Ничего особенного." }, { 4.81, "Отправляйся в Восточные Чумные земли и поищи там сведения про Гнилостеня." }, { 10.31, "И поглядывай, не найдёшь ли ты наших пропавших оперативников." }, { 14.78, "Мы вынуждены предположить, что они погибли, но коли так, должны быть... трупы." }, { 20.42, "Все агенты ШРУ носят такие знаки." }, { 24.07, "*Флинт показывает вам знаки отличия ШРУ.*" }, { 27.75, "Принеси мне все, какие только найдёшь." } } }, t = { d = 12.6, v = "human-male#50", n = { x = 107 }, c = { x = { { 0.00, "Рутгер." }, { 1.09, "Фредо." }, { 2.06, "Турьен." }, { 3.15, "Всё..." }, { 3.99, "Мертвы…" }, { 4.96, "*Флинт сжимает в руках их регалии.*" }, { 8.08, "Где они были?" }, { 9.00, "Удалось ли тебе собрать сведения про этого мерзавца?" } } } } },
    [6186] = { d = 32.4, v = "human-male#50", n = { x = 343 }, c = { x = { { 0.00, "*Флинт бледнеет.*" }, { 1.84, "Это дело рук На..." }, { 3.24, "Натаноса?" }, { 3.98, "Натанос и есть Гнилостень?" }, { 5.91, "Но почему?" }, { 6.72, "Он был... таким благородным, пользовался всеобщим уважением." }, { 11.12, "Единственный человек, которого согласились обучать высшие эльфы." }, { 15.93, "И теперь он безжалостный сторонник Отрёкшихся?" }, { 19.27, "Мне... жаль, что приходится просить об этом, но об этих событиях должен узнать верховный лорд Фордрагон." }, { 27.97, "Я прошу тебя незамедлительно вернуться в Штормград с вестями." } } }, t = { d = 13.8, v = "creature/bolvar", n = { x = 52 }, c = { x = { { 0.00, "Нет." }, { 0.59, "Не может..." }, { 2.14, "НЕТ!" }, { 2.74, "Как?" }, { 3.33, "Агент Отрёкшихся?" }, { 5.59, "ЗАЩИТНИК Королевы банши???" }, { 9.04, "*Верховный лорд Болвар Фордрагон бессильно опускает руки.*" } } } } },
    [6187] = { d = 42.6, v = "creature/bolvar", n = { x = 416 }, c = { x = { { 0.00, "Знаете, сколько предводителей следопытов существует на этом свете?" }, { 5.78, "А сколько когда-либо существовало людей-предводителей следопытов?" }, { 11.32, "Достижения Натаноса необыкновенны." }, { 14.29, "Он был тактическим гением, благодаря ему Альянс в течение десятилетия одерживал победы." }, { 21.87, "А теперь... теперь он защитник Отрёкшихся." }, { 25.46, "Нет." }, { 25.85, "Такого быть не должно." }, { 27.80, "Порядок должен быть восстановлен." }, { 30.69, "Соберите армию." }, { 32.10, "Возвращайтесь в Чумные земли со своими воинами и уничтожьте Гнилостеня." }, { 38.27, "Желаю удачи." }, { 39.44, "В этом бою она вам точно понадобится." } } }, t = { d = 22.7, v = "creature/bolvar", n = { x = 205 }, c = { x = { { 0.00, "Это трагедия." }, { 1.29, "Я думаю... я уверен, что над нами висит проклятие." }, { 5.80, "Мы приговорены терять наших величайших воинов, благороднейших героев и даровитейших учёных." }, { 13.86, "Мы в долгу перед вами и, уверяю вас, где бы сейчас ни был Натанос Маррис, он с улыбкой взирает на вас." } } } } },
    [6261] = { d = 26.6, v = "human-male#116", n = { x = 321 }, c = { x = { { 0.00, "Я сложил в этот ящик всё, о чём просил Льюис." }, { 3.06, "Можете отвезти ему ящик?" }, { 4.80, "С Тором в Западном Крае вы уже общались – значит, сможете нанять грифона, чтобы туда вернуться." }, { 11.29, "Наш укротитель грифонов – Дунгар Долгопив, он находится в Торговом квартале." }, { 16.33, "Поговорите с Дунгаром и доставьте этот ящик Льюису как можно скорее." }, { 20.96, "Мы не хотим, чтобы нашим воинам в Западном Крае пришлось сражаться без новых доспехов!" } } }, t = { d = 11.0, v = "human-male", n = { x = 130 }, c = { x = { { 0.00, "Нужно доставить сундук в Западный Край, да?" }, { 2.96, "А вы там бывали прежде?" }, { 4.56, "Если да, то никаких проблем, друг мой." }, { 7.15, "У меня есть множество грифонов, обученных этому маршруту!" } } } } },
    [6281] = { d = 18.6, v = "human-male", n = { x = 227 }, c = { x = { { 0.00, "За небольшую плату вы можете нанять грифона для полёта в Штормград, чтобы доставить записку Льюиса Озрику." }, { 7.03, "Более быстрого пути нет." }, { 8.69, "Если для вас это приемлемо, поговорите со мной снова, когда будете готовы лететь." }, { 14.11, "Я, конечно, возьму с вас немного денег, но поверьте, оно того стоит!" } } }, t = { d = 15.8, v = "human-male#116", n = { x = 188 }, c = { x = { { 0.00, "А, записка от интенданта Льюиса!" }, { 2.28, "Я не удивлён, что ему понадобилась дополнительная экипировка." }, { 6.46, "Сторожевой холм далеко, и в Штормграде едва помнят о нём." }, { 10.45, "Что ж, спасибо вам." }, { 11.78, "Вот немного денег на покрытие ваших транспортных расходов." } } } } },
    [6282] = { d = 29.8, v = "tauren-male", n = { x = 274 }, c = { x = { { 0.00, "Таурен горд тем, что защищает эти земли." }, { 3.58, "Несомненно, ты понимаешь, почему я обеспокоен тем, что здесь, в Каменном Когте, обитает множество гарпий." }, { 12.73, "Клан Кровавой Ярости – вот откуда берутся всё новые и новые гарпии в Калимдоре." }, { 19.73, "Они посягают на жизнь всех и каждого, не давая слабым даже уйти отсюда!" }, { 26.10, "Мне нужна твоя помощь в уничтожении гарпий!" } } }, t = { d = 13.8, v = "tauren-male", n = { x = 124 }, c = { x = { { 0.00, "Замечательные новости!" }, { 2.14, "Поведай мне вновь, как тебе удалось вселить ужас в холодные сердца злобных гарпий." }, { 10.00, "Клан Кровавой Ярости понёс серьёзный урон!" } } } } },
    [6283] = { d = 31.6, v = "tauren-male", n = { x = 300 }, c = { x = { { 0.00, "Уменьшить число гарпий из стаи Кровавой Ярости – этого недостаточно." }, { 6.01, "Единственное, чем можно извести эту заразу – это убить их предводительницу, Потрошительницу!" }, { 13.97, "Средь этих мерзостных существ она почти королева." }, { 18.34, "Убей её, и гарпий станет меньше." }, { 21.22, "Возвращайся в Обугленную долину, и ты найдёшь её у западных холмов." }, { 26.92, "Её не так-то легко уничтожить, но награда будет велика." } } }, t = { d = 30.1, v = "tauren-male", n = { x = 261 }, c = { x = { { 0.00, "Я уже чувствую, как гнев покидает меня." }, { 3.55, "Что мне теперь делать?" }, { 5.56, "Знание о том, что зло бродило поблизости от моих земель, не давало моим мыслям покоя, а теперь они затихли." }, { 15.24, "Быть может, это и к лучшему... быть может, теперь я смогу обратить свои мысли в сторону добра, как и положено таурену." }, { 25.89, "Прошу тебя, прими это в награду за твои труды." } } } } },
    [6284] = { d = 27.6, v = "narrator", n = { x = 297 }, c = { x = { { 0.00, "Предупреждение: дорога отсюда на запад, в Сиширский каньон, опасна." }, { 5.32, "Бесселет и её восьминогие отпрыски превратили этот каньон в своё логово, заплетённое паутиной." }, { 12.63, "Маггран Связующий Землю из Приюта у Солнечного Камня назначил награду за Бесселет." }, { 19.16, "Убей её и принеси доказательство её смерти Магграну – получишь награду за устранение этой восьминогой угрозы." } } }, t = { d = 26.4, v = "tauren-male", n = { x = 254 }, c = { x = { { 0.00, "Добрая охота!" }, { 1.30, "Бесселет издавна была угрозой для этих земель... и я не буду по ней тосковать." }, { 8.38, "Возьми эту награду в знак того, что тебе удалось защитить наш лес." }, { 14.32, "*Маггран потирает рану, нанесённую Бесселет.*" }, { 17.84, "Быть может, теперь больше народа будет приходить в Приют у Солнечного Камня, не боясь того, что крадётся во мраке." } } } } },
    [6285] = { d = 30.2, v = "human-male", n = { x = 376 }, c = { x = { { 0.00, "Укротителем грифонов в Западном Крае работает Тор." }, { 3.30, "Если вы с ним уже знакомы, то можете на одном из моих грифонов к нему долететь." }, { 8.55, "Полезная для вас информация: грифоны обучены так, что до столицы могут долететь всегда, а к укротителям, расположенным в других местах, полетят, только если вы там уже бывали." }, { 19.94, "Вы ведь уже были у Тора, так что просто поговорите со мной ещё раз, когда будете готовы лететь в Западный Край." }, { 27.13, "А там уже отнесёте ящик Озрика интенданту Льюису." } } }, t = { d = 18.6, g = 1, v = "human-male", n = { m = 210, f = 211 }, c = { m = { { 0.00, "Отлично, вы привезли доспехи!" }, { 2.05, "Мы распределим их между теми, кому они срочно необходимы." }, { 6.08, "Спасибо вам, сэр путник." }, { 7.75, "Вы нам очень помогли." }, { 9.24, "А теперь, когда вы знакомы и с нашими грифонами, я надеюсь, вы будете часто прилетать к нам и предлагать свою помощь Сторожевому холму!" } }, f = { { 0.00, "Отлично, вы привезли доспехи!" }, { 2.04, "Мы распределим их между теми, кому они срочно необходимы." }, { 6.07, "Спасибо вам, леди путница." }, { 7.93, "Вы нам очень помогли." }, { 9.41, "А теперь, когда вы знакомы и с нашими грифонами, я надеюсь, вы будете часто прилетать к нам и предлагать свою помощь Сторожевому холму!" } } } } },
    [6301] = { d = 34.8, v = "tauren-female#71", n = { x = 336 }, c = { x = { { 0.00, "Жадность промышленников и постоянная война опустошили земли Когтистых гор." }, { 6.23, "Только благословение Матери-Земли может исцелить такие раны." }, { 11.47, "Я хочу отправить тебя на поиски особого семени – семени Геи." }, { 16.72, "Его можно найти только здесь, в Каменном Когте, к северу от Приюта у Солнечного Камня, у Мутного Озера, у самого края воды." }, { 27.28, "Как только ты принесёшь мне эти семена, я напитаю их шаманской силой, дабы ускорить их рост." } } }, t = { d = 16.9, v = "tauren-female#71", n = { x = 148 }, c = { x = { { 0.00, "О, так вот они – семена Геи!" }, { 2.80, "Смотри и увидишь, как благословение Матери-Земли даст этим крошечным семенам жизни возможность цвести и плодоносить." }, { 14.00, "*Таммра начинает читать заклинание.*" } } } } },
    [6321] = { d = 38.5, v = "scourge-male", n = { x = 416 }, c = { x = { { 0.00, "Исполнитель Хадрик попросил меня заняться нашим арсеналом в Гробнице." }, { 5.33, "По лесу рыщут силы Плети, а то и кое-что похуже, и он хочет, чтобы у наших стражей смерти было достаточно оружия, когда оно понадобится." }, { 15.86, "Я выяснил, что в целом у нас всё в порядке, но нам нужно дополнительное оружие взамен потерянного в боях." }, { 23.72, "Вот заявка на поставку для торговца оружием Гордона Уиндема, находящегося в Подгороде." }, { 30.22, "Отнесите этот заказ нашему дрессировщику летучих мышей, Каросу Раззоку, и поговорите с ним о полёте в Подгород." } } }, t = { d = 12.7, v = "scourge-male", n = { x = 119 }, c = { x = { { 0.00, "А, заказ на поставки." }, { 1.88, "Не сомневаюсь, вам нужно доставить его в Подгород." }, { 6.28, "И как можно скорее, потому что в Гробнице нельзя допустить нехватку оружия." } } } } },
    [6322] = { d = 19.9, v = "scourge-male#145", n = { x = 219 }, c = { x = { { 0.00, "Я сложил припасы для Гробницы в этот ящик." }, { 3.25, "Если вы уже бывали в Гробнице и знакомы с тамошним дрессировщиком летучих мышей, то можете туда лететь." }, { 11.12, "Поговорите с дрессировщиком летучих мышей здесь, в Подгороде – с Майклом Гарреттом." }, { 17.29, "Он поможет вам добраться до Гробницы." } } }, t = { d = 9.0, v = "scourge-male", n = { x = 91 }, c = { x = { { 0.00, "Этот ящик нужно доставить в Гробницу, что в Серебряном бору?" }, { 4.84, "Это легко: наши летучие мыши ежедневно туда летают." } } } } },
    [6323] = { d = 19.2, v = "scourge-male", n = { x = 206 }, c = { x = { { 0.00, "Одна из моих летучих мышей может отвезти вас в Подгород, за небольшую плату." }, { 6.03, "Приходите ко мне, когда будете готовы, чтобы мы могли организовать ваш полёт." }, { 11.99, "Гордона Уиндема вы найдёте в Торговом квартале Подгорода." }, { 16.41, "Именно там и приземлится летучая мышь." } } }, t = { d = 7.9, v = "scourge-male#145", n = { x = 67 }, c = { x = { { 0.00, "Заказ из Гробницы?" }, { 1.83, "Отлично." }, { 2.70, "Для меня честь – услужить тем, кто служит Тёмной Госпоже." } } } } },
    [6324] = { d = 35.6, v = "scourge-male", n = { x = 394 }, c = { x = { { 0.00, "Дрессировщика летучих мышей в Гробнице зовут Карос Раззок." }, { 4.43, "Если вы уже знакомы с ним, я могу предоставить вам одну из своих летучих мышей, чтобы вы к нему вернулись." }, { 12.41, "Все наши мыши всегда могут долететь до Подгорода, но, чтобы добраться до более отдалённых мест, пассажир должен сначала посетить эти места и познакомиться с тамошними дрессировщиками." }, { 25.96, "С Каросом вы уже встречались в Гробнице, так что теперь можете летать туда на мышах." }, { 32.26, "Вернитесь ко мне, когда будете готовы к полёту." } } }, t = { d = 11.0, v = "scourge-male", n = { x = 102 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.47, "Это оружие позволит не застать врасплох наших стражей смерти." }, { 7.20, "Вы сослужили хорошую службу Тёмной Госпоже." } } } } },
    [6341] = { d = 30.3, v = "nightelf-female#53", n = { x = 353 }, c = { x = { { 0.00, "Рыбаки деревни Рут'теран живут очень хорошо: ведь рыба здесь очень крупная, и её много." }, { 6.29, "Я хотела бы сравнить здешнее изобилие с ситуацией в материковых водах." }, { 11.29, "Я собрала образцы рыбьих костей и чешуи, которые хотела бы отправить своему коллеге на Тёмный Берег." }, { 18.47, "Его зовут Лайрд, он торгует рыбой в Аубердине." }, { 21.81, "Идите с моей коллекцией образцов к нашему дрессировщику гиппогрифов, Веспристу, и поговорите с ним насчёт полёта в Аубердин." } } }, t = { d = 4.9, v = "nightelf-male#54", n = { x = 44 }, c = { x = { { 0.00, "А, вы хотите доставить эту посылку в Аубердин?" }, { 4.09, "Отлично..." } } } } },
    [6342] = { d = 36.2, v = "nightelf-male#54", n = { x = 416 }, c = { x = { { 0.00, "Из деревни Рут'теран можно добраться в Аубердин двумя путями: на пароме и на гиппогрифе." }, { 6.38, "Оба способа быстры и надёжны, но если вы ещё никогда не летали в Аубердин на гиппогрифе, я бы порекомендовал вам это сделать." }, { 15.30, "Мой вам добрый совет: говорите с дрессировщиками гиппогрифов в каждом городе, где они есть." }, { 21.81, "Когда вы поговорите с дрессировщиком, то сможете летать в этот город из других мест." }, { 27.86, "Возвращаю вам коллекцию Нессы." }, { 30.07, "Поговорите со мной, когда будете готовы лететь в Аубердин и доставить коллекцию Лайрду." } } }, t = { d = 22.1, v = "nightelf-male#121", n = { x = 250 }, c = { x = { { 0.00, "Посылка от Нессы?" }, { 1.27, "Спасибо." }, { 1.91, "Она говорила, что собирается прислать мне образцы рыбы, пойманной близ деревни Рут'теран." }, { 8.21, "Она думает, что эта рыба может серьёзно отличаться от той, что ловится здесь..." }, { 13.75, "Ничего себе!" }, { 14.71, "Эта челюсть чуть ли не вдвое больше, чем у таких же здешних рыб." }, { 19.23, "А эта чешуя размером с кулак!" }, { 21.40, "Невероятно!" } } } } },
    [6343] = { d = 33.2, v = "nightelf-male#121", n = { x = 412 }, c = { x = { { 0.00, "Мне нужно отправить Нессе ответ." }, { 2.25, "Ей будет очень интересно знать, насколько здешняя рыба отличается от той, что водится у берегов Тельдрассила." }, { 9.53, "Мы можем лишь догадываться о причинах, но подозреваю, что так воздействует само Древо Жизни на окружающую его природу!" }, { 17.43, "Пожалуйста, отнесите мой ответ Нессе." }, { 19.98, "Если хотите лететь в Рут'теран на гиппогрифе, поговорите с дрессировщиком гиппогрифов Кайлаис Лунное Перо." }, { 27.15, "А если хотите добраться паромом, то он регулярно отходит от причала к северо-западу отсюда." } } }, t = { d = 24.2, v = "nightelf-female#53", n = { x = 259 }, c = { x = { { 0.00, "Всё это очень интересно." }, { 1.92, "Рыба здесь крупная, но я не думала, что разница между обитающими в материковых и здешних водах столь велика." }, { 10.07, "Для этого должна быть причина..." }, { 12.54, "Что ж, благодарю вас." }, { 14.11, "Я обсужу с земляками новости, что вы принесли." }, { 17.61, "Может быть, когда-нибудь мы найдём причину этой странности." }, { 22.06, "А пока будем ею пользоваться!" } } } } },
    [6344] = { d = 22.0, v = "nightelf-male#120", n = { x = 229 }, c = { x = { { 0.00, "Моя подруга, Несса Песня Теней, торгует рыбой в деревне Рут'теран." }, { 5.26, "Ей нужно доставить посылку на Тёмный берег, и она ищет кого-нибудь, кто мог бы ей помочь." }, { 12.04, "Если вы хотите помочь Нессе, то ступайте в деревню Рут'теран через портал в Дарнассе." }, { 18.69, "Портал находится к западу от Храмовых садов." } } }, t = { d = 6.1, v = "nightelf-female#53", n = { x = 64 }, c = { x = { { 0.00, "Да, мне нужен курьер, который доставит посылку на Тёмный Берег." }, { 4.96, "Вы мне поможете?" } } } } },
