    [6362] = { d = 24.5, v = "orc-male#60", n = { x = 250 }, c = { x = { { 0.00, "За небольшую плату ты можешь полететь в Громовой Утёс на ветрокрыле." }, { 5.42, "Быстрее не бывает!" }, { 6.93, "Если тебя устраивает цена – обращайся, когда решишь отправиться в путь." }, { 12.71, "Если ты везёшь эти шкуры Ахану, думаю, ты отыщешь его в оружейной Хевы, у основания башни ветрокрылов в Громовом Утёсе." }, { 22.32, "Именно там ты и приземлишься!" } } }, t = { d = 15.0, g = 1, v = "tauren-male#133", n = { m = 131, f = 134 }, c = { m = { { 0.00, "А, новая связка шкур." }, { 2.00, "Я немедленно ими займусь." }, { 4.43, "Спасибо, брат." }, { 5.76, "Ты оказал мне большую услугу." }, { 8.52, "Возьми эти монеты, чтобы покрыть дорожные расходы и потраченное время." } }, f = { { 0.00, "А, новая связка шкур." }, { 1.91, "Я немедленно ими займусь." }, { 4.22, "Спасибо, сестра." }, { 5.73, "Ты оказала мне большую услугу." }, { 8.43, "Возьми эти монеты, чтобы покрыть дорожные расходы и потраченное время." } } } } },
