    [6365] = { d = 21.7, v = "orc-male#126", n = { x = 258 }, c = { x = { { 0.00, "Я хочу послать своей подруге несколько видов превосходных мясных продуктов." }, { 5.44, "Её зовут Гришка, она хозяйка таверны в Оргриммаре." }, { 9.09, "Поможешь мне доставить мясо?" }, { 11.14, "До Оргриммара проще всего добраться на ветрокрыле." }, { 14.72, "Отнеси мясные продукты Девраку, укротителю ветрокрылов, и поговори с ним насчёт доставки в Оргриммар." } } }, t = { d = 8.6, v = "orc-male#60", n = { x = 85 }, c = { x = { { 0.00, "Тебе нужно доставить мясо в Оргриммар?" }, { 3.33, "Нет проблем." }, { 4.40, "За небольшую плату тебя отнесёт туда мой ветрокрыл." } } } } },
    [6381] = { d = 35.1, g = 1, v = "tauren-female#71", n = { x = 339 }, c = { m = { { 0.00, "Вот видишь, герой, хотя эта земля глубоко изранена, круговорот жизни – великая сила." }, { 7.21, "Теперь мы должны внести свой вклад и помочь этой силе." }, { 11.78, "Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине." }, { 18.54, "Но берегись – там, в полумёртвых землях, ещё встречаются гарпии и злобные элементали огня." }, { 25.89, "Возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы." }, { 32.12, "Круговорот жизни должен продолжаться!" } }, f = { { 0.00, "Вот видишь, героиня, хотя эта земля глубоко изранена, круговорот жизни – великая сила." }, { 7.29, "Теперь мы должны внести свой вклад и помочь этой силе." }, { 11.83, "Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине." }, { 18.52, "Но берегись – там, в полумёртвых землях, ещё встречаются гарпии и злобные элементали огня." }, { 25.82, "Возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы." }, { 31.99, "Круговорот жизни должен продолжаться!" } } }, t = { d = 33.3, g = 1, v = "tauren-female#71", n = { m = 320, f = 321 }, c = { m = { { 0.00, "Это великая победа, свершённая ради здешних земель." }, { 4.40, "Со временем произойдут и другие перемены: Торговая компания уберётся отсюда вместе со своими пилами и топорами, разгневанные духи огня успокоятся, а гарпии будут изгнаны с этих земель." }, { 19.94, "Только тогда, в Каменном Когте настанет истинный мир." }, { 24.49, "Ты совершил благое дело, герой; возьми один из этих предметов в награду за вклад в создание новой жизни." } }, f = { { 0.00, "Это великая победа, свершённая ради здешних земель." }, { 4.38, "Со временем произойдут и другие перемены: Торговая компания уберётся отсюда вместе со своими пилами и топорами, разгневанные духи огня успокоятся, а гарпии будут изгнаны с этих земель." }, { 19.85, "Только тогда, в Каменном Когте настанет истинный мир." }, { 24.38, "Ты со