    [6382] = { d = 35.0, g = 1, v = "tauren-male#67", n = { m = 331, f = 332 }, c = { m = { { 0.00, "Твоя сила производит впечатление, герой, а интерес к охоте даёт надежды, что вскоре тебе можно будет поручить дичь покрупнее..." }, { 11.08, "И посерьёзнее." }, { 12.25, "Орда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса." }, { 21.70, "Если ты готов проявить себя в непознанных ещё землях, обратись к Сенани Громосерд на заставе Расщеплённого Древа." }, { 31.45, "Она находится к северу от тропы из Степей." } }, f = { { 0.00, "Твоя сила производит впечатление, героиня, а интерес к охоте даёт надежды, что вскоре тебе можно будет поручить дичь покрупнее..." }, { 11.06, "И посерьёзнее." }, { 12.21, "Орда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса." }, { 21.51, "Если ты готова проявить себя в непознанных ещё землях, обратись к Сенани Громосерд на заставе Расщеплённого Древа." }, { 31.19, "Она находится к северу от тропы из Степей." } } }, t = { d = 30.4, g = 1, v = "tauren-female", n = { m = 307, f = 306 }, c = { m = { { 0.00, "Добро пожаловать на новое пограничье." }, { 3.03, "Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя." }, { 11.31, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 18.88, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 23.92, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } }, f = { { 0.00, "Добро пожаловать на новое пограничье." }, { 3.00, "Ясеневый лес – край неограниченных возможностей, где юной героине вроде тебя выпадает шанс показать себя." }, { 11.30, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 18.81, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 23.81, "Слушай же внимательно, 