    [6387] = { d = 32.2, v = "dwarf-male", n = { x = 384 }, c = { x = { { 0.00, "Ко мне приходит немало молодых дворфов, мечтающих научиться горному делу." }, { 5.22, "Что же нужнее всего шахтёру?" }, { 7.19, "Кирка!" }, { 7.70, "Я составил список учеников, которые хорошо проявили себя на занятиях и заслужили почётную кирку." }, { 14.51, "Отнеси этот список Голниру Твердопалу в Стальгорн." }, { 18.07, "Он подготовит для меня эти кирки." }, { 20.49, "Проще всего добраться до Стальгорна на грифоне, поэтому ступай с этим списком к нашему укротителю грифонов, Торгруму Боррелсону, и поговори с ним насчёт полёта в Стальгорн." } } }, t = { d = 11.0, v = "dwarf-male", n = { x = 122 }, c = { x = { { 0.00, "Тебе нужно отвезти это в Стальгорн, да?" }, { 2.94, "За небольшую плату я позволю тебе оседлать одного из моих грифонов, и он отнесёт тебя прямо в город." }, { 10.27, "Что скажешь?" } } } } },
    [6388] = { d = 14.5, g = 1, v = "dwarf-male#99", n = { m = 167, f = 168 }, c = { m = { { 0.00, "Вот почётные кирки для учеников Брока." }, { 2.67, "Если ты уже бывал в Телсамаре, можешь полететь обратно на грифоне!" }, { 7.44, "Отнеси кирки нашему укротителю грифонов, Гриту Турдену, и поговори с ним насчёт полёта в Телсамар." } }, f = { { 0.00, "Вот почётные кирки для учеников Брока." }, { 2.72, "Если ты уже бывала в Телсамаре, можешь полететь обратно на грифоне!" }, { 7.64, "Отнеси кирки нашему укротителю грифонов, Гриту Турдену, и поговори с ним насчёт полёта в Телсамар." } } }, t = { d = 9.7, g = 1, v = "dwarf-male", n = { m = 108, f = 110 }, c = { m = { { 0.00, "Значит, тебе нужно в Телсамар?" }, { 2.22, "Не вопрос." }, { 2.98, "Если ты там уже бывал и беседовал с Торгрумом Боррелсоном, можешь полететь к нему на грифоне." } }, f = { { 0.00, "Значит, тебе нужно в Телсамар?" }, { 2.25, "Не вопрос." }, { 3.02, "Если ты там уже бывала и беседовала с Торгрумом Боррелсоном, можешь полететь к нему на грифоне." } } } } },
    [6389] = { d = 19.6, v = "narrator", n = { x = 219 }, c = { x = { { 0.00, "Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели." }, { 9.43, "Примериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу." } } }, t = { d = 13.0, g = 1, v = "human-male", n = { m = 121, f = 122 }, c = { m = { { 0.00, "Ха-ха, превосходно!" }, { 1.64, "Ты справился!" }, { 2.76, "Дух моего отца наконец сможет покоиться с миром, а уж я-то как доволен!" }, { 8.71, "Спасибо тебе!" }, { 9.91, "Проси что хочешь, чем смогу – помогу!" } }, f = { { 0.00, "Ха-ха, превосходно!" }, { 1.63, "Ты справилась!" }, { 2.81, "Дух моего отца наконец сможет покоиться с миром, а уж я-то как доволен!" }, { 8.74, "Спасибо тебе!" }, { 9.92, "Проси что хочешь, чем смогу – помогу!" } } } } },
    [6390] = { d = 19.4, v = "narrator", n = { x = 219 }, c = { x = { { 0.00, "Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели." }, { 9.63, "Примериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу." } } }, t = { d = 9.7, g = 1, v = "scourge-female#80", n = { m = 77, f = 78 }, c = { m = { { 0.00, "Спасибо тебе." }, { 1.43, "У меня есть лишь эта монета..." }, { 4.48, "Но, думаю, ты получил удовольствие от самого процесса!" } }, f = { { 0.00, "Спасибо тебе." }, { 1.41, "У меня есть лишь эта монета..." }, { 4.40, "Но, думаю, ты получила удовольствие от самого процесса!" } } } } },
    [6391] = { d = 21.4, v = "dwarf-male", n = { x = 262 }, c = { x = { { 0.00, "Всего за несколько монет один из моих грифонов отнесёт тебя в Стальгорн." }, { 4.93, "Там ты сможешь отдать список Брока Голниру Твердопалу." }, { 8.65, "Его можно найти в гильдии горняков Тайной Горы." }, { 12.00, "Она находится неподалёку от Великой Кузни Стальгорна, и именно там тебя высадит мой грифон!" }, { 18.15, "Когда решишь отправиться в путь, обращайся ко мне." } } }, t = { d = 8.6, v = "dwarf-male#99", n = { x = 94 }, c = { x = { { 0.00, "А, последний список лучших учеников Брока." }, { 3.27, "Я уже подготовил почётные кирки, осталось выбить на них имена учеников..." } } } } },
    [6392] = { d = 28.2, g = 1, v = "dwarf-male", n = { m = 349, f = 352 }, c = { m = { { 0.00, "За небольшую плату грифон отнесёт тебя в Телсамар... если ты там уже бывал." }, { 5.04, "Грифоны могут летать только туда, где ты успел побывать." }, { 8.88, "Не упускай случая поговорить со всеми укротителями грифонов, и получишь возможность прилететь к ним." }, { 15.48, "Торгрума, дрессировщика грифонов Телсамара, ты уже видел, поэтому можешь вернуться к нему." }, { 21.54, "Оказавшись в Телсамаре, отнеси кирки Броку Камнекопу." }, { 25.14, "Когда решишь тронуться в путь – обращайся ко мне." } }, f = { { 0.00, "За небольшую плату грифон отнесёт тебя в Телсамар... если ты там уже бывала." }, { 5.01, "Грифоны могут летать только туда, где ты успела побывать." }, { 8.84, "Не упускай случая поговорить со всеми укротителями грифонов, и получишь возможность прилететь к ним." }, { 15.33, "Торгрума, дрессировщика грифонов Телсамара, ты уже видела, поэтому можешь вернуться к нему." }, { 21.34, "Оказавшись в Телсамаре, отнеси кирки Броку Камнекопу." }, { 24.88, "Когда решишь тронуться в путь – обращайся ко мне." } } }, t = { d = 15.7, v = "dwarf-male", n = { x = 175 }, c = { x = { { 0.00, "А вот и кирки." }, { 1.02, "Отлично!" }, { 1.66, "Я раздам их своим ученикам." }, { 3.64, "Им, конечно, не терпится пустить их в ход в рудниках возле озера Лок Модан." }, { 8.93, "Благодарю за помощь." }, { 10.40, "Я у тебя в долгу." }, { 11.68, "Возьми эти деньги, они должны покрыть стоимость перелёта." } } } } },
    [6393] = { d = 36.2, v = "elemental-water-lord", n = { x = 366 }, c = { x = { { 0.00, "Совет Приливов послал меня объявить войну элементалям огня здесь, в Когтистых горах." }, { 7.17, "Нептулон Приливный Охотник, повелитель всех элементалей воды, лично заинтересован в том, чтобы узреть погибель всех наших огненных сородичей." }, { 18.95, "Ты можешь помочь мне высоко подняться во мнении Совета путём уничтожения элементалей огня в Обугленной долине." }, { 28.16, "После смерти от этих элементалей остаются огненные кристаллы." }, { 33.38, "Отдай их мне, и ты получишь награду." } } }, t = { d = 12.2, g = 1, v = "elemental-water-lord", n = { x = 102 }, c = { m = { { 0.00, "Духи воды внутри меня булькают от восторга." }, { 4.05, "Путник, я высоко ценю твой дар – славную победу, о которой я могу сообщить в Совет Приливов." } }, f = { { 0.00, "Духи воды внутри меня булькают от восторга." }, { 3.97, "Путница, я высоко ценю твой дар – славную победу, о которой я могу сообщить в Совет Приливов." } } } } },
    [6394] = { d = 35.8, g = 1, v = "orc-male", n = { m = 351, f = 351 }, c = { m = { { 0.00, "Ты добросовестный герой." }, { 1.86, "Можно доверить тебе ещё одно дело?" }, { 4.62, "Не так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку." }, { 11.64, "А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей!" }, { 17.57, "Не можешь ли ты сходить в грот Пылающего Клинка и раздобыть мою кирку?" }, { 22.94, "Я её оставил в зале с водопадами." }, { 25.49, "Кирка моя заговорённая – она светится в темноте, так что найти её будет нетрудно... только, боюсь, её уже стерегут!" } }, f = { { 0.00, "Ты добросовестная героиня." }, { 2.08, "Можно доверить тебе ещё одно дело?" }, { 4.96, "Не так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку." }, { 12.28, "А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей!" }, { 18.46, "Не можешь ли ты сходить в грот Пылающего Клинка и раздобыть мою кирку?" }, { 24.06, "Я её оставил в зале с водопадами." }, { 26.72, "Кирка моя заговорённая – она светится в темноте, так что найти её будет нетрудно... только, боюсь, её уже стерегут!" } } }, t = { d = 13.9, v = "orc-male", n = { x = 121 }, c = { x = { { 0.00, "Она у тебя!" }, { 1.12, "Моя любимая кирка!" }, { 2.88, "Спасибо большое!" }, { 4.40, "Ну, теперь главное – дождаться, когда мои батраки управятся с рубкой леса, – и можно снова искать минералы!" } } } } },
    [6395] = { d = 45.4, v = "scourge-female#80", n = { x = 402 }, c = { x = { { 0.00, "Моя подруга Марла Фиппс жила до чумы со своим мужем Самуэлем, но когда пришла чума, Самуэль погиб... и вступил в ряды Плети." }, { 11.59, "Марла избежала чумы, но погибла от рук собственного мужа, лишившегося разума." }, { 18.65, "Однако так велика была её любовь, что последним желанием её было, чтобы Самуэль был похоронен рядом с ней." }, { 28.35, "Самуэль Фиппс обитает теперь у разорённого лагеря близ дороги на северо-восток от Могильника." }, { 36.73, "Убей его и выполни желание Марлы: похорони Самуэля в её могиле, в первом ряду нашего кладбища." } } }, t = { d = 18.4, g = 1, v = "scourge-female#80", n = { m = 173, f = 174 }, c = { m = { { 0.00, "Ты совершил сегодня доброе дело." }, { 2.85, "Хотя наша борьба против армии Плети всё ещё продолжается, будем надеяться, что Марла и Самуэль упокоятся с миром." }, { 12.61, "В знак моей благодарности можешь взять одно из этих руководств." } }, f = { { 0.00, "Ты совершила сегодня доброе дело." }, { 3.46, "Хотя наша борьба против армии Плети всё ещё продолжается, будем надеяться, что Марла и Самуэль упокоятся с миром." }, { 13.22, "В знак моей благодарности можешь взять одно из этих руководств." } } } } },
    [6401] = { d = 21.0, v = "tauren-male", n = { x = 196 }, c = { x = { { 0.00, "Передай Таммре Поле Ветров, тётушке Кайи, живущей в Приюте у Солнечного Камня, добрые новости – Кайя жива!" }, { 9.25, "Мы думали, что она погибла во время того жестокого нападения на нашу деревню." }, { 15.96, "Иди по дороге на запад, и придёшь в Приют у Солнечного Камня." } } }, t = { d = 8.3, v = "tauren-female#71", n = { x = 66 }, c = { x = { { 0.00, "Хвала духам, моя племянница Кайя жива!" }, { 4.06, "Это поистине добрая новость." }, { 7.05, "Спасибо тебе!" } } } } },
    [6402] = { d = 13.6, g = 1, v = "human-male", n = { m = 151, f = 151 }, c = { m = { { 0.00, "Вы с Виндзором должны встретиться у ворот Штормграда." }, { 3.96, "Виндзор расскажет такое, что всё королевство содрогнётся!" }, { 8.11, "И не ходи туда один." }, { 9.72, "Собери целую армию!" }, { 11.27, "Позови своих земляков." }, { 13.01, "К оружию!" } }, f = { { 0.00, "Вы с Виндзором должны встретиться у ворот Штормграда." }, { 3.96, "Виндзор расскажет такое, что всё королевство содрогнётся!" }, { 8.11, "И не ходи туда одна." }, { 9.72, "Собери целую армию!" }, { 11.27, "Позови своих земляков." }, { 13.01, "К оружию!" } } }, t = { d = 5.4, v = "human-male", n = { x = 56 }, c = { x = { { 0.00, "Пока мы не вступили в бой, собери армию." }, { 3.11, "В конце концов, на дракона идём!" } } } } },
    [6403] = { d = 31.7, v = "human-male", n = { x = 346 }, c = { x = { { 0.00, "Вот это было приключение, друг мой." }, { 2.59, "Я перед вами в огромном, неоплатном долгу." }, { 5.78, "Может быть, когда всё будет кончено..." }, { 8.64, "Как уже доподлинно установлено вами, Леди Престор – это Ониксия, отродье Смертокрыла, сестра-близнец владыки Чёрной горы Нефариана." }, { 18.40, "Слишком долго держала она наше королевство под контролем." }, { 22.72, "Даже сам Верховный лорд – марионетка в её руках..." }, { 26.38, "Это колдовство будет разрушено." }, { 28.77, "Не бойтесь, вместе мы победим!" }, { 31.03, "Вы готовы?" } } }, t = { d = 37.0, v = "creature/bolvar", n = { x = 354 }, c = { x = { { 0.00, "*Болвар держит в руках расколовшийся амулет.*" }, { 3.68, "Магия, содержавшаяся в нём, должна воскреснуть." }, { 7.71, "Око дракона должно быть настроено." }, { 10.74, "Самопожертвование Виндзора освободило наше королевство, но угроза, исходящая от Ониксии и ей подобных, никуда не делась." }, { 20.98, "Этот медальон удерживал в плену мои разум и тело." }, { 25.40, "Он также давал мне доступ к собственному разуму Ониксии – к её тайнам." }, { 31.46, "Хотя эти воспоминания сейчас как будто в тумане, кое-что я помню." } } } } },
    [6421] = { d = 38.4, g = 1, v = "tauren-male#67", n = { m = 337, f = 337 }, c = { m = { { 0.00, "Что-то не так здесь, в Когтистых горах." }, { 3.48, "Чувствуешь ли ты непокой, витающий в воздухе?" }, { 7.53, "К юго-востоку отсюда, в ущелье Камнепадов, есть пещера." }, { 12.56, "Там кобольды отчаянно ищут редкие кристаллы резонита." }, { 17.42, "Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере." }, { 25.84, "Помимо того, неплохо бы тебе обследовать глубины этой пещеры." }, { 31.51, "Иди же, юный герой, мне очень важно знать, что за зло таится под этими горами." } }, f = { { 0.00, "Что-то не так здесь, в Когтистых горах." }, { 3.44, "Чувствуешь ли ты непокой, витающий в воздухе?" }, { 7.44, "К юго-востоку отсюда, в ущелье Камнепадов, есть пещера." }, { 12.40, "Там кобольды отчаянно ищут редкие кристаллы резонита." }, { 17.20, "Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере." }, { 25.52, "Помимо того, неплохо бы тебе обследовать глубины этой пещеры." }, { 31.12, "Иди же, юная героиня, мне очень важно знать, что за зло таится под этими горами." } } }, t = { d = 37.5, v = "tauren-male#67", n = { x = 353 }, c = { x = { { 0.00, "О да!" }, { 0.48, "Это оно – кристалл резонита несёт следы земной магии." }, { 5.31, "Должно быть, кобольды, докопавшись до глубин, обнаружили там земельника." }, { 11.58, "Легенда утверждает, что земельники – это существа, созданные титанами." }, { 17.77, "Именно с их помощью создана земная твердь, по которой мы ступаем." }, { 23.48, "Угроза велика, нельзя не обращать на неё внимания." }, { 27.84, "*Мор'рогал качает головой.*" }, { 30.16, "Быть может, я сумею наложить заклинание на эти куски руды, чтобы нарушить затею кобольдов." } } } } },
    [6441] = { d = 35.1, v = "goblin-female#63", n = { x = 377 }, c = { x = { { 0.00, "Привет!" }, { 0.61, "Я ехала через Ясеневый лес в Кабестан и решила остановиться здесь, в Расщеплённом Дереве." }, { 7.23, "Я никогда не упущу выгодного дельца, а тут оказывается, что рога сатира нынче пользуются в Кабестане большим спросом." }, { 16.10, "Я тут поспрошала, и оказывается, что сатиры с Ночной поляны, Сатирнаара и Ксавиана как раз носят такие рога, что мне надо." }, { 25.24, "Мне эти сатиры не по зубам... но вот вам – наверняка!" }, { 29.20, "Скажите, сколько возьмёте, добудьте мне рога, и я оплачу ваше потраченное время." } } }, t = { d = 6.4, v = "goblin-female#63", n = { x = 46 }, c = { x = { { 0.00, "Изумительные рога!" }, { 2.00, "Спасибо за помощь!" }, { 4.00, "О, а это вам за труды..." } } } } },
    [6442] = { d = 27.4, g = 1, v = "troll-female", n = { x = 265 }, c = { m = { { 0.00, "Зло рыщет по побережью, герой." }, { 2.47, "Здесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощённый морем." }, { 9.51, "Разрушенный и почти забытый." }, { 11.83, "Теперь в него непонятно почему вернулись наги." }, { 15.68, "Но причина не так важна – мы должны защитить край, за который так упорно боролись." }, { 22.21, "Принеси мне двадцать их голов!" }, { 24.67, "Загони наг назад, в глубины моря!" } }, f = { { 0.00, "Зло рыщет по побережью, героиня." }, { 2.61, "Здесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощённый морем." }, { 9.66, "Разрушенный и почти забытый." }, { 11.98, "Теперь в него непонятно почему вернулись наги." }, { 15.83, "Но причина не так важна – мы должны защитить край, за который так упорно боролись." }, { 22.36, "Принеси мне двадцать их голов!" }, { 24.83, "Загони наг назад, в глубины моря!" } } }, t = { d = 3.8, v = "troll-female", n = { x = 38 }, c = { x = { { 0.00, "Побольше бы нам таких, как ты." }, { 2.39, "Спасибо за помощь." } } } } },
    [6461] = { d = 34.2, v = "troll-male#78", n = { x = 332 }, c = { x = { { 0.00, "Мы, тролли, тут, в Малака'джине, живём с земли, да и живём хорошо." }, { 5.21, "В Когтистых горах есть на что поохотиться." }, { 8.58, "Только вот повадились к нам в последнее время незваные гости... по ночам пауки на наши стоянки нападают, хотят украсть нашу добычу." }, { 19.36, "Если поможешь нам поубивать этих злобных тварей, мы, тролли Малака'джина, будем перед тобой в долгу." }, { 27.65, "Тут, в Когтистых горах, пауки повсюду – ступай на север, и увидишь, о чём я толкую." } } }, t = { d = 11.5, v = "troll-male#78", n = { x = 112 }, c = { x = { { 0.00, "О, вот и славненько!" }, { 1.65, "Ну хорошо, авось сегодня к нам на ужин меньше незваных гостей налезет." }, { 7.56, "Тысяча благодарностей." }, { 9.43, "Мы у тебя в долгу навечно." } } } } },
    [6462] = { d = 39.4, g = 1, v = "troll-male", n = { m = 409, f = 409 }, c = { m = { { 0.00, "Мои сородичи шли сюда со священными тролльскими оберегами, но фурболги Колючего Меха напали на них и перебили прежде, чем они успели добраться до Зорам'гара!" }, { 12.32, "Эти подлые фурболги!" }, { 14.02, "Я горюю по убитым братьям и сёстрам – но мы ещё встретимся в загробной жизни." }, { 19.97, "Однако, их тролльские обереги в нашем мире весьма ценятся." }, { 24.65, "Меня бесит, что ими завладели фурболги!" }, { 27.83, "Ты должен вернуть эти обереги!" }, { 30.31, "Они находятся в сундуках в Крепости Колючего Меха, в пещере на окраине Деревни Колючего Меха, к северу от Астранаара." } }, f = { { 0.00, "Мои сородичи шли сюда со священными тролльскими оберегами, но фурболги Колючего Меха напали на них и перебили прежде, чем они успели добраться до Зорам'гара!" }, { 12.12, "Эти подлые фурболги!" }, { 13.80, "Я горюю по убитым братьям и сёстрам – но мы ещё встретимся в загробной жизни." }, { 19.65, "Однако, их тролльские обереги в нашем мире весьма ценятся." }, { 24.25, "Меня бесит, что ими завладели фурболги!" }, { 27.38, "Ты должна вернуть эти обереги!" }, { 29.82, "Они находятся в сундуках в Крепости Колючего Меха, в пещере на окраине Деревни Колючего Меха, к северу от Астранаара." } } }, t = { d = 14.0, g = 1, v = "troll-male", n = { m = 123, f = 124 }, c = { m = { { 0.00, "Ты их нашёл!" }, { 1.04, "О, благодарю тебя!" }, { 2.72, "Ты представить себе не можешь, что ты сделал для меня." }, { 7.52, "Тролль без оберега что орк без боевых шрамов..." }, { 11.60, "Пустое место, а не тролль." } }, f = { { 0.00, "Ты их нашла!" }, { 1.13, "О, благодарю тебя!" }, { 2.82, "Ты представить себе не можешь, что ты сделала для меня." }, { 7.72, "Тролль без оберега что орк без боевых шрамов..." }, { 11.83, "Пустое место, а не тролль." } } } } },
    [6481] = { d = 31.6, g = 1, v = "tauren-male#67", n = { x = 310 }, c = { m = { { 0.00, "Благодаря тебе, герой, мы узнали, что этой земле грозит великая опасность." }, { 6.19, "Резонитовая ёмкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок." }, { 14.88, "Я изменил своей шаманской силой принесённые тобой кристаллы." }, { 19.82, "Возьми кристалл резонита и разбей резонитовую ёмкость, где спит земельник." }, { 25.79, "Сразу после пробуждения Гоггерок будет ослаблен..." }, { 29.99, "Убей его!" } }, f = { { 0.00, "Благодаря тебе, героиня, мы узнали, что этой земле грозит великая опасность." }, { 6.49, "Резонитовая ёмкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок." }, { 15.39, "Я изменил своей шаманской силой принесённые тобой кристаллы." }, { 20.44, "Возьми кристалл резонита и разбей резонитовую ёмкость, где спит земельник." }, { 26.55, "Сразу после пробуждения Гоггерок будет ослаблен..." }, { 30.85, "Убей его!" } } }, t = { d = 28.0, g = 1, v = "tauren-male#67", n = { m = 243, f = 243 }, c = { m = { { 0.00, "Это хорошие новости, герой!" }, { 2.49, "Я опасался того, что земельник может сделать с Калимдором." }, { 7.53, "Уничтожение Гоггерока было задачей, достойной истинного героя." }, { 12.97, "Но тебе удалось справиться с этим, и теперь и Когтистые горы, и Калимдор перед тобой в долгу, благородный герой." }, { 22.76, "Прими это как заслуженную и достойную награду." } }, f = { { 0.00, "Это хорошие новости, героиня!" }, { 2.74, "Я опасался того, что земельник может сделать с Калимдором." }, { 7.99, "Уничтожение Гоггерока было задачей, достойной истинного героя." }, { 13.64, "Но тебе удалось справиться с этим, и теперь и Когтистые горы, и Калимдор перед тобой в долгу, благородная героиня." }, { 23.96, "Прими это как заслуженную и достойную награду." } } } } },
    [6482] = { d = 23.6, g = 1, v = "tauren-male#67", n = { x = 190 }, c = { m = { { 0.00, "А?" }, { 0.23, "Ты кто?" }, { 0.86, "Путник?" }, { 1.56, "Ты не фурболг." }, { 2.81, "Они прокляты!" }, { 4.06, "Они подумали, что я медведь, и схватили меня, а теперь морят голодом!" }, { 10.15, "Я погибаю..." }, { 11.24, "Помоги мне сбежать, затем поговори с моей сестрой Ями на заставе Расщеплённого Дерева к востоку отсюда." }, { 20.21, "Путник!" }, { 20.92, "Мне надо сбежать!" } }, f = { { 0.00, "А?" }, { 0.25, "Ты кто?" }, { 0.90, "Путница?" }, { 1.72, "Ты не фурболг." }, { 3.03, "Они прокляты!" }, { 4.34, "Они подумали, что я медведь, и схватили меня, а теперь морят голодом!" }, { 10.73, "Я погибаю..." }, { 11.88, "Помоги мне сбежать, затем поговори с моей сестрой Ями на заставе Расщеплённого Дерева к востоку отсюда." }, { 21.30, "Путница!" }, { 22.12, "Мне надо сбежать!" } } }, t = { d = 23.4, g = 1, v = "tauren-female#72", n = { m = 236, f = 236 }, c = { m = { { 0.00, "Ты нашёл моего брата!" }, { 1.77, "Его схватили фурболги Колючего Меха?" }, { 4.87, "Какая страшная весть!" }, { 6.64, "Хотя многие фурболги существа благородные, эти – извращённые твари." }, { 12.17, "Спасибо за спасение брата." }, { 14.38, "Страшно подумать, как они обходились с бедняжкой Руулом!" }, { 19.02, "Наверняка после таких испытаний он будет долго спать..." } }, f = { { 0.00, "Ты нашла моего брата!" }, { 1.79, "Его схватили фурболги Колючего Меха?" }, { 4.79, "Какая страшная весть!" }, { 6.51, "Хотя многие фурболги существа благородные, эти – извращённые твари." }, { 11.87, "Спасибо за спасение брата." }, { 14.01, "Страшно подумать, как они обходились с бедняжкой Руулом!" }, { 18.52, "Наверняка после таких испытаний он будет долго спать..." } } } } },
    [6501] = { d = 39.0, v = "creature/bolvar", n = { x = 401 }, c = { x = { { 0.00, "Фрагмент расколотого амулета – это всё, что я могу вам предложить." }, { 5.17, "Вам придётся найти ещё одного дракона, который согласится помочь вам в изготовлении нового ключа." }, { 12.75, "Как только вы добудете этот ключ, вам нужно будет отправиться в Драконьи топи в Пылевых топях." }, { 20.19, "Там вы и найдёте её логово." }, { 22.25, "Где найти других драконов, готовых помочь?" }, { 25.65, "К сожалению, я не знаю..." }, { 27.63, "Говорят, что такие существуют." }, { 30.04, "Некоторые из них могут даже жить среди нас в обличии людей, гномов или эльфов, например." }, { 37.06, "Желаю вам удачи в поиске." } } }, t = { d = 7.8, v = "bloodelf-female", n = { x = 71 }, c = { x = { { 0.00, "Я должна была догадаться – часть плоти царицы чёрных драконов, Ониксии." }, { 6.45, "Какая мерзость…" } } } } },
    [6502] = { d = 32.1, g = 1, v = "bloodelf-female", n = { x = 343 }, c = { m = { { 0.00, "Это – заколдованная драконья чешуя." }, { 2.65, "Целая чешуйка открывает проход в драконье логово, а в сломанном виде она бесполезна." }, { 8.93, "Её можно починить, но для этого требуется кровь могучего чёрного дракона." }, { 14.22, "Есть один такой..." }, { 15.61, "Его зовут генерал Драккисат, он возглавляет армию драконидов Нефариана." }, { 20.91, "Тебе доводилось о нём слышать?" }, { 23.16, "Возвращайся с его кровью, герой, и я наложу чары на этот осколок." }, { 28.05, "Тогда ты сможешь проникнуть в Логово Ониксии." } }, f = { { 0.00, "Это – заколдованная драконья чешуя." }, { 2.66, "Целая чешуйка открывает проход в драконье логово, а в сломанном виде она бесполезна." }, { 8.96, "Её можно починить, но для этого требуется кровь могучего чёрного дракона." }, { 14.27, "Есть один такой..." }, { 15.67, "Его зовут генерал Драккисат, он возглавляет армию драконидов Нефариана." }, { 20.98, "Тебе доводилось о нём слышать?" }, { 23.24, "Возвращайся с его кровью, героиня, и я наложу чары на этот осколок." }, { 28.28, "Тогда ты сможешь проникнуть в Логово Ониксии." } } }, t = { d = 14.2, v = "bloodelf-female", n = { x = 144 }, c = { x = { { 0.00, "Этот амулет поможет тебе достичь цели." }, { 3.25, "Гнездо Ониксии ты найдёшь в Пылевых топях." }, { 6.65, "Пока амулет с тобой, её стражи не смогут препятствовать тебе." }, { 11.64, "Синие драконы желают тебе удачи." } } } } },
    [6503] = { d = 24.7, v = "troll-male", n = { x = 267 }, c = { x = { { 0.00, "Мы получили донесение, что вестницы Ясеневого леса не так давно покинули Аванпост Среброкрылых и теперь шныряют в лесу у наших границ." }, { 10.32, "Нам не надо, чтобы они разнюхивали что да как с нашей обороной!" }, { 15.17, "Проникни в лес к югу отсюда и к востоку от альянсовского Аванпоста Среброкрылых." }, { 21.27, "Найди и перебей лазутчиц, а потом возвращайся." } } }, t = { d = 13.2, v = "troll-male", n = { x = 129 }, c = { x = { { 0.00, "Очень хорошо." }, { 1.23, "Твоё охотничье мастерство впечатляет..." }, { 4.53, "Потеря лазутчиц малость притупит нюх Альянса, а ежели им разведданных не хватит, то вряд ли они нападут." } } } } },
    [6504] = { d = 27.3, v = "orc-female#58", n = { x = 317 }, c = { x = { { 0.00, "Этот резак я только что получила из Кабестана и как раз возвращалась на лесозаготовки Песни Войны, на своё рабочее место." }, { 8.38, "Мне дали инструкцию к резаку, но по дороге назад у меня её вырвало из рук порывом ветра." }, { 14.56, "Все страницы разлетелись, и осталась у меня одна обложка." }, { 18.60, "Где теперь эти страницы носит, одним предкам ведомо..." }, { 22.51, "Но как я резаком-то без них пользоваться буду?" }, { 25.66, "Не найдёшь ли их для меня?" } } }, t = { d = 6.4, v = "orc-female#58", n = { x = 52 }, c = { x = { { 0.00, "Не сильна я в чтении..." }, { 2.22, "Но теперь я могу вернуться к работе!" }, { 5.71, "Спасибо!" } } } } },
    [6521] = { d = 32.8, v = "named/2425", n = { x = 339 }, c = { x = { { 0.00, "Повелеваю тебе убить посланника Малкина – я не позволю ему выполнить волю Короля-лича." }, { 7.11, "Он пишет, что ждёт встречи где-то поблизости от Курганов Иглошкурых." }, { 12.56, "Его присутствие там многое объясняет." }, { 15.61, "Сила тамошних иглогривов многократно увеличилась, и среди них отмечаются признаки чумы." }, { 22.65, "Очевидно, они заключили с Малкином какое-то соглашение." }, { 27.15, "Найди и убей Малкина." }, { 28.96, "Возвращайся ко мне, когда исполнишь моё повеление." } } }, t = { d = 28.2, g = 1, v = "named/2425", n = { m = 300, f = 301 }, c = { m = { { 0.00, "Прекрасно." }, { 0.83, "Ты хорошо поработал, герой." }, { 2.99, "Теперь, после смерти Малкина, мы по крайней мере можем быть уверенными, что продвижение Плети будет остановлено." }, { 11.69, "Тёмная Госпожа благодарит тебя за преданность и изволит одарить тебя." }, { 17.05, "Пока нам неизвестно, насколько прочные позиции заняла Плеть в холмах Железной Осоки, однако не сомневаюсь – скоро нам удастся разузнать их замыслы." } }, f = { { 0.00, "Прекрасно." }, { 0.82, "Ты хорошо поработала, героиня." }, { 3.14, "Теперь, после смерти Малкина, мы по крайней мере можем быть уверенными, что продвижение Плети будет остановлено." }, { 11.68, "Тёмная Госпожа благодарит тебя за преданность и изволит одарить тебя." }, { 16.94, "Пока нам неизвестно, насколько прочные позиции заняла Плеть в холмах Железной Осоки, однако не сомневаюсь – скоро нам удастся разузнать их замыслы." } } } } },
    [6522] = { d = 40.5, v = "narrator", n = { x = 427 }, c = { x = { { 0.00, "Госпожа моя," }, { 1.07, "Наше предложение вам прекрасно известно." }, { 4.28, "Для вас это отличная возможность получить безграничную власть над Степью и окрестными землями." }, { 11.62, "От вас нам требуется лишь небольшое содействие – вам нужно всего лишь дать нам свободу действий в этих землях." }, { 20.17, "Мы убедительно просим вас рассмотреть это предложение и обсудить его с нами." }, { 26.23, "За нами великая сила, и мы с охотой поделимся ею с теми, кто достаточно мудр, чтобы примкнуть к нам." }, { 34.14, "Я буду ждать вас у Курганов Иглошкурых." }, { 37.21, "С наилучшими пожеланиями," }, { 39.21, "Посланник Малкин." } } }, t = { d = 29.7, g = 1, v = "named/2425", n = { m = 294, f = 294 }, c = { m = { { 0.00, "Я узнаю знак на этом свитке." }, { 2.35, "Говоришь, нашёл это у старухи, правящей в Лабиринтах Иглошкурых?" }, { 7.57, "Любопытно." }, { 8.45, "Похоже, Плети мало одного континента." }, { 11.61, "Посол Малкин – тот, кто написал письмо, – один из служителей Плети." }, { 17.12, "Он был человеческим послом в Лордероне, прежде чем... всё переменилось." }, { 22.78, "Если Плеть в самом деле пытается закрепиться в Калимдоре, нам пора что-то предпринять." } }, f = { { 0.00, "Я узнаю знак на этом свитке." }, { 2.31, "Говоришь, нашла это у старухи, правящей в Лабиринтах Иглошкурых?" }, { 7.52, "Любопытно." }, { 8.39, "Похоже, Плети мало одного континента." }, { 11.50, "Посол Малкин – тот, кто написал письмо, – один из служителей Плети." }, { 16.92, "Он был человеческим послом в Лордероне, прежде чем... всё переменилось." }, { 22.49, "Если Плеть в самом деле пытается закрепиться в Калимдоре, нам пора что-то предпринять." } } } } },
    [6523] = { d = 17.8, v = "tauren-female#72", n = { x = 195 }, c = { x = { { 0.00, "Спасибо большое за спасение!" }, { 2.08, "Мы должны уходить побыстрее, прежде чем они обнаружат, что я на свободе." }, { 7.29, "Я прошу сопроводить меня до Лагеря Апарахе." }, { 10.48, "Оттуда я уже знаю, куда идти." }, { 12.76, "Мой отец, Макаба Плоское Копыто, наверное, уже отчаялся узнать, где я." } } }, t = { d = 5.7, g = 1, v = "tauren-male", n = { x = 34 }, c = { m = { { 0.00, "Кайя жива!" }, { 1.26, "Путник, я благодарю тебя за её спасение!" } }, f = { { 0.00, "Кайя жива!" }, { 1.27, "Путница, я благодарю тебя за её спасение!" } } } } },
    [6541] = { d = 22.2, g = 1, v = "orc-male#60", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Ты когда-нибудь бывал в Ясеневом лесу, на севере?" }, { 3.59, "Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ." }, { 11.67, "Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне." }, { 17.41, "Он руководит кампанией в Ясеневом лесу и может дать тебе поручение." } }, f = { { 0.00, "Ты когда-нибудь бывала в Ясеневом лесу, на севере?" }, { 3.63, "Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ." }, { 11.66, "Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне." }, { 17.37, "Он руководит кампанией в Ясеневом лесу и может дать тебе поручение." } } }, t = { d = 17.2, v = "orc-male", n = { x = 170 }, c = { x = { { 0.00, "Ясеневый лес – разделённый войной край, но наши недавние усилия увенчались успехом." }, { 7.08, "Мы основали заставу не только на Зорамском взморье, но ещё прямо к северу отсюда построили заставу Расщеплённого Дерева." } } } } },
