    [6543] = { d = 33.9, v = "orc-male", n = { x = 384 }, c = { x = { { 0.00, "Недавно я отправил в Ясеневый лес нескольких разведчиков." }, { 4.25, "Мне нужен гонец, чтобы доставить им приказы и вернуться с отчётом об их наблюдениях." }, { 10.46, "Первый твой пункт – форт Зорам'гар, что на западном побережье на Зорамском взморье." }, { 16.53, "Там ты найдёшь первого гонца." }, { 18.69, "Также тебе придётся заглянуть на заставу Расщеплённого Дерева, что на севере и к востоку по дороге близ Азшары." }, { 26.85, "Там найдёшь разведчика и сопровождающего." }, { 29.82, "Передай каждому указания и забери у них новые донесения." } } }, t = { d = 14.7, v = "orc-male", n = { x = 157 }, c = { x = { { 0.00, "Вижу, на тебя можно положиться." }, { 2.59, "Эти новые сведения чрезвычайно важны для осуществления планов по расширению нашего присутствия в Ясеневом лесу." }, { 11.50, "Теперь мы можем разработать следующий шаг." } } } } },
    [6544] = { d = 36.4, g = 1, v = "orc-male", n = { x = 352 }, c = { m = { { 0.00, "Эй!" }, { 0.29, "Герой!" }, { 0.87, "Иди-ка сюда!" }, { 1.95, "Мы с ребятами хотим напасть на Аванпост Среброкрылых на западе." }, { 7.00, "Наша цель – их командир, Дариэль Лунное Пламя." }, { 10.75, "Разведчики говорят, что форт здорово защищён, там полно часовых и воинов." }, { 16.53, "Славная будет драка!" }, { 18.26, "Хочешь помочь нам, и разделить нашу славу?" }, { 21.73, "Если пойдёшь с нами, то когда победим, сможешь доложить о наших успехах моему начальнику, Эртогу Лютоклыку." }, { 30.39, "Ты найдёшь его в Расщеплённом Дереве." }, { 33.27, "Что скажешь?" }, { 34.29, "Пойдёшь с нами?" } }, f = { { 0.00, "Эй!" }, { 0.29, "Героиня!" }, { 1.02, "Иди-ка сюда!" }, { 2.11, "Мы с ребятами хотим напасть на Аванпост Среброкрылых на западе." }, { 7.21, "Наша цель – их командир, Дариэль Лунное Пламя." }, { 11.00, "Разведчики говорят, что форт здорово защищён, там полно часовых и воинов." }, { 18.62, "Славная будет драка!" }, { 19.09, "Хочешь помочь нам, и разделить нашу славу?" }, { 22.59, "Если пойдёшь с нами, то когда победим, сможешь доложить о наших успехах моему начальнику, Эртогу Лютоклыку." }, { 31.33, "Ты найдёшь его в Расщеплённом Дереве." }, { 34.24, "Что скажешь?" }, { 35.26, "Пойдёшь с нами?" } } }, t = { d = 19.4, g = 1, v = "orc-male#60", n = { m = 163, f = 164 }, c = { m = { { 0.00, "Значит, Тореку дельце удалось!" }, { 2.98, "Хорошая работа." }, { 4.52, "Ночные эльфы – достойные враги." }, { 7.59, "Худоваты на вид, но сильные да яростные!" }, { 11.34, "Видать, драка была красивая, посмотреть бы..." }, { 15.69, "Надеюсь, парочку шрамов-то ты заработал?" } }, f = { { 0.00, "Значит, Тореку дельце удалось!" }, { 2.98, "Хорошая работа." }, { 4.52, "Ночные эльфы – достойные враги." }, { 7.59, "Худоваты на вид, но сильные да яростные!" }, { 11.34, "Видать, драка была красивая, посмотреть бы..." }, { 15.68, "Надеюсь, парочку шрамов-то ты заработала?" } } } } },
    [6545] = { t = { d = 8.6, v = "orc-male", n = { x = 85 }, c = { x = { { 0.00, "Что же, в моих последних донесениях Кадраку всё подробно описано." }, { 5.51, "Возвращайся к нему как можно быстрее." } } } } },
    [6546] = { t = { d = 3.7, v = "orc-female", n = { x = 36 }, c = { x = { { 0.00, "Доставь моё донесение Кадраку." }, { 2.72, "И побыстрее." } } } } },
    [6547] = { t = { d = 7.0, v = "orc-female", n = { x = 71 }, c = { x = { { 0.00, "Передай Кадраку, что мы тут успешно сдерживаем ночных эльфов." }, { 5.15, "Всё идёт согласно плану." } } } } },
    [6548] = { d = 20.1, v = "tauren-male", n = { x = 194 }, c = { x = { { 0.00, "Клан Зловещего Тотема напал на мою деревню и убил почти всех жителей." }, { 5.87, "Я сразил столько нападавших, сколько мог, но едва спас собственную жизнь." }, { 11.89, "Всё, чего я желаю – это чтобы как можно больше этих негодяев умерло." }, { 17.75, "Ты найдёшь их к западу отсюда." } } }, t = { d = 9.9, v = "tauren-male", n = { x = 77 }, c = { x = { { 0.00, "Я благодарю тебя... но я никогда не забуду того, что клан Зловещего Тотема сделал с моей деревней." } } } } },
    [6561] = { d = 37.6, v = "nightelf-male#54", n = { x = 373 }, c = { x = { { 0.00, "Силы оставили меня." }, { 1.70, "Мне необходима твоя помощь!" }, { 3.99, "В давние времена на этом месте был храм Элуны." }, { 7.83, "К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный лунный колодец." }, { 17.66, "Аку'май, слуга Древнего бога, поднялся из глубин." }, { 21.80, "Сектанты Сумеречного Молота объединились с нагами в борьбе за эти земли." }, { 27.78, "Сектанты, ведомые Келрисом, приносят Аку'май невинные жертвы." }, { 32.88, "Убей Келриса и принеси его голову Башане в Громовой Утёс." } } }, t = { d = 31.6, g = 1, v = "tauren-female#71", n = { m = 310, f = 313 }, c = { m = { { 0.00, "Келрису много раз удавалось ускользнуть от Серебряного Рассвета." }, { 5.48, "Его считали мёртвым или пропавшим без вести." }, { 9.29, "Положив конец его власти, ты спас жизнь многих." }, { 13.33, "Слава Матери-Земле!" }, { 15.08, "Нет прощенья тем, кто приносит невинные жертвы Древнему Богу!" }, { 20.26, "Ты совершил великий подвиг." }, { 22.62, "Келрис был порождением зла, он стремился повергнуть наш мир в хаос, поклоняясь Старым Богам." }, { 30.39, "Благодарю тебя." } }, f = { { 0.00, "Келрису много раз удавалось ускользнуть от Серебряного Рассвета." }, { 5.35, "Его считали мёртвым или пропавшим без вести." }, { 9.06, "Положив конец его власти, ты спасла жизнь многих." }, { 13.22, "Слава Матери-Земле!" }, { 14.93, "Нет прощенья тем, кто приносит невинные жертвы Древнему Богу!" }, { 19.98, "Ты совершила великий подвиг." }, { 22.36, "Келрис был порождением зла, он стремился повергнуть наш мир в хаос, поклоняясь Старым Богам." }, { 29.94, "Благодарю тебя." } } } } },
    [6562] = { d = 28.5, g = 1, v = "elemental-water-lord", n = { m = 266, f = 266 }, c = { m = { { 0.00, "Дже'неу Санкри нужна помощь." }, { 2.58, "Он в форте Зорам'гар в Ясеневом лесу." }, { 5.87, "Этот лес ночных эльфов находится к северу от Когтистых гор." }, { 11.03, "Ты можешь добраться до него через Утёс Ветрорезов или идя на север через Степи." }, { 18.07, "Зорамское взморье лежит далеко на западе от леса." }, { 22.46, "Будь осторожен." }, { 23.79, "Там обитают такие силы, от которых тёплого приёма не жди." } }, f = { { 0.00, "Дже'неу Санкри нужна помощь." }, { 2.57, "Он в форте Зорам'гар в Ясеневом лесу." }, { 5.85, "Этот лес ночных эльфов находится к северу от Когтистых гор." }, { 11.00, "Ты можешь добраться до него через Утёс Ветрорезов или идя на север через Степи." }, { 18.02, "Зорамское взморье лежит далеко на западе от леса." }, { 22.39, "Будь осторожна." }, { 23.72, "Там обитают такие силы, от которых тёплого приёма не жди." } } }, t = { d = 5.6, v = "troll-male", n = { x = 51 }, c = { x = { { 0.00, "Тебя послал Цунаман?" }, { 2.00, "Великолепно." }, { 3.17, "Тогда нам есть что обсудить." } } } } },
    [6563] = { d = 33.8, v = "troll-male", n = { x = 385 }, c = { x = { { 0.00, "В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы." }, { 6.74, "Недавно было замечено, что эти кристаллы собирают наги." }, { 10.87, "Пока не станет ясно, зачем им это, сдаётся мне, что надо наг этой возможности лишить." }, { 17.09, "В кристаллах этих содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом." }, { 26.98, "Ты мне не поможешь?" }, { 28.35, "Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы." } } }, t = { d = 18.6, v = "troll-male", n = { x = 169 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.39, "Это те самые кристаллы, о которых я говорил." }, { 5.24, "Как интригующе..." }, { 6.70, "Я чувствую в них силу." }, { 8.63, "К ним тянутся духи воды." }, { 10.79, "Для чего бы наги ни собирались их использовать..." }, { 14.95, "Ладно, хорошо, что они больше не в их руках." } } } } },
    [6564] = { d = 36.6, v = "narrator", n = { x = 346 }, c = { x = { { 0.00, "На смятом обрывке бумаги кое-как нацарапано:" }, { 3.91, "\"Да, вели всем жрицам приносить мне эти кристаллы." }, { 8.28, "В них обитают могучие духи элементалей воды, и они весьма помогут нашим аквамантам в призывании духов." }, { 17.27, "Овладев силой, заключённой в кристаллах, мы сумеем умилостивить Аку'май." }, { 23.44, "И однажды настанет день, когда мы накопим достаточно сил, чтобы вернуть Аку'май к нам, и мир вернётся в величайшую свою эпоху!" }, { 34.22, "Эпоху власти Древних богов!\"" } } }, t = { d = 10.6, v = "troll-male", n = { x = 94 }, c = { x = { { 0.00, "Это и правда интересно." }, { 2.14, "Я рад, что ты принёс мне эту записку." }, { 5.32, "Теперь мы знаем, как зовут причину наших бед..." }, { 9.53, "Лоргус Джетт!" } } } } },
    [6565] = { d = 34.0, g = 1, v = "troll-male", n = { m = 336, f = 336 }, c = { m = { { 0.00, "Мы не можем допустить, чтобы этот последователь Сумеречного Молота выполнил свой план." }, { 6.75, "Клан Сумеречного Молота не понимает духов Природы." }, { 10.73, "Они верят в Древних богов – богов хаоса и разрушения, побеждённых давным-давно." }, { 17.05, "Нельзя дать этому Лоргусу добиться своего!" }, { 20.46, "Ты должен остановить его." }, { 22.52, "Мне самому этого не сделать – я слишком слаб." }, { 26.08, "Ступай в Непроглядную Пучину, найди и убей его!" }, { 29.91, "А потом возвращайся в Зорам'гар." } }, f = { { 0.00, "Мы не можем допустить, чтобы этот последователь Сумеречного Молота выполнил свой план." }, { 7.10, "Клан Сумеречного Молота не понимает духов Природы." }, { 11.29, "Они верят в Древних богов – богов хаоса и разрушения, побеждённых давным-давно." }, { 17.94, "Нельзя дать этому Лоргусу добиться своего!" }, { 21.52, "Ты должна остановить его." }, { 23.69, "Мне самому этого не сделать – я слишком слаб." }, { 27.43, "Ступай в Непроглядную Пучину, найди и убей его!" }, { 31.46, "А потом возвращайся в Зорам'гар." } } }, t = { d = 20.7, v = "troll-male", n = { x = 207 }, c = { x = { { 0.00, "Прекрасно!!!" }, { 1.03, "Хвала тебе." }, { 2.06, "Может, мы и не окончательно разобрались с Сумеречным Молотом, но по крайней мере один их план по возвращению в могуществе своём Древних богов мы нарушили." }, { 14.41, "Кто знает, какие ещё замыслы у них на уме, но пока мы можем вздохнуть свободно." } } } } },
    [6566] = { d = 7.4, v = "named/thrall", n = { x = 68 }, c = { x = { { 0.00, "Рад видеть тебя снова." }, { 2.13, "Ветер принёс вести из Восточных королевств." }, { 6.05, "Садись и слушай." } } }, t = { d = 3.2, g = 1, v = "named/thrall", n = { m = 29, f = 30 }, c = { m = { { 0.00, "Готов ли ты взять на себя эту задачу?" } }, f = { { 0.00, "Готова ли ты взять на себя эту задачу?" } } } } },
    [6567] = { d = 16.5, v = "named/thrall", n = { x = 160 }, c = { x = { { 0.00, "Рексар, один из самых преданных моих защитников, нашёл путь в логово дракона." }, { 6.56, "Разыщи его." }, { 7.63, "Он скитается по Пустошам, что раскинулись между Когтистыми горами и Фераласом." }, { 14.19, "Он уже знает, что ты придёшь." } } }, t = { d = 25.3, v = "creature/rexxar", n = { x = 229 }, c = { x = { { 0.00, "В драконье логово можно проникнуть только одним способом." }, { 4.94, "Ну, разумеется, если ты не почётный член их клана." }, { 9.05, "Но и тогда тебе пришлось бы пройти немало испытаний и получить ключ, заколдованный самим генералом Драккисатом." }, { 18.41, "Но раз уж ты не чёрный дракон, всё будет несколько сложнее." }, { 23.20, "*Рексар ухмыляется.*" } } } } },
    [6568] = { d = 35.3, v = "creature/rexxar", n = { x = 317 }, c = { x = { { 0.00, "А что ты знаешь об иллюзиях?" }, { 2.51, "Ведь только иллюзия поможет тебе обмануть чёрных драконов и добыть то, что ты ищешь." }, { 10.03, "Я знаю, кто смог бы тебе помочь." }, { 12.95, "Она не раз помогала нам и поможет тебе, если сочтёт твои цели достойными." }, { 19.58, "Отправляйся в Западные Чумные земли и разыщи Миранду Колдунью." }, { 25.25, "Когда-то она была мастером иллюзий Альянса Лордерона, но её изгнали." }, { 31.48, "Вот, отнеси ей это послание, она всё поймёт." } } }, t = { d = 34.5, v = "gnome-female", n = { x = 277 }, c = { x = { { 0.00, "*Миранда берёт записку и через некоторое время улыбается.*" }, { 4.56, "Как он?" }, { 5.14, "Я про Рексара." }, { 6.29, "Ой, к чему удивление?" }, { 8.02, "Письмо не просто так оставлено пустым." }, { 11.13, "Ведь главное – это мысли и поступки того, кто его отправил." }, { 15.97, "Да и, судя по обстоятельствам, Рексар не мог ничего написать." }, { 20.80, "Представь, если бы тебя поймали или убили, и важная информация досталась бы врагу!" }, { 27.51, "Но всё хорошо." }, { 28.67, "Миранда поможет тебе." }, { 30.47, "У меня должок перед вождём." }, { 32.64, "*Миранда улыбается.*" } } } } },
    [6569] = { d = 31.2, g = 1, v = "gnome-female", n = { m = 339, f = 340 }, c = { m = { { 0.00, "Значит, герой возжелал войти в Чёрное Племя?" }, { 3.44, "Создать необходимую тебе иллюзию – пара пустяков." }, { 7.30, "Куда труднее собрать компоненты, необходимые для наложения этих чар." }, { 12.54, "Раз Вождь поручил тебе такую миссию, Миранде остаётся повиноваться." }, { 17.64, "Отправляйся в верхнюю часть крепости на пике Чёрной горы и убей столько чёрных драконидов, чтобы набить заплечные мешки их глазами." }, { 27.63, "Когда наберёшь достаточно, возвращайся к Миранде." } }, f = { { 0.00, "Значит, героиня возжелала войти в Чёрное Племя?" }, { 3.53, "Создать необходимую тебе иллюзию – пара пустяков." }, { 7.25, "Куда труднее собрать компоненты, необходимые для наложения этих чар." }, { 12.31, "Раз Вождь поручил тебе такую миссию, Миранде остаётся повиноваться." }, { 17.23, "Отправляйся в верхнюю часть крепости на пике Чёрной горы и убей столько чёрных драконидов, чтобы набить заплечные мешки их глазами." }, { 26.87, "Когда наберёшь достаточно, возвращайся к Миранде." } } }, t = { d = 15.0, g = 1, v = "gnome-female", n = { x = 152 }, c = { m = { { 0.00, "Дай-ка Миранде посмотреть, герой." }, { 2.67, "О, да, отличные глаза." }, { 4.42, "Теперь Миранда сделает для тебя медальон, который создаст иллюзию, при помощи которой ты сможешь обмануть привратника Чёрного Племени." } }, f = { { 0.00, "Дай-ка Миранде посмотреть, героиня." }, { 2.84, "О, да, отличные глаза." }, { 4.61, "Теперь Миранда сделает для тебя медальон, который создаст иллюзию, при помощи которой ты сможешь обмануть привратника Чёрного Племени." } } } } },
    [6570] = { d = 28.3, v = "gnome-female", n = { x = 307 }, c = { x = { { 0.00, "Благодаря этому медальону в пределах логова Огнебора ты будешь сохранять нужный облик." }, { 6.67, "Огнебор – старый дракон, древний привратник Нефариана." }, { 10.86, "На него возложена обязанность испытывать тех драконов, которые должны войти в элитную стражу Ониксии." }, { 18.63, "Отправляйся в Драконьи топи в Пылевых топях и войди в его логово." }, { 23.71, "Оказавшись внутри, надень амулет, и следуй за своей судьбой!" } } }, t = { d = 11.0, v = "creature/dragon", n = { x = 98 }, c = { x = { { 0.00, "Неужели у нас иссякли хорошие бойцы?" }, { 3.48, "Зачем Нефариан присылает мне детёнышей?" }, { 7.13, "Тебе не пройти испытания, мелочь пузатая." } } } } },
    [6571] = { d = 34.6, v = "orc-male#60", n = { x = 381 }, c = { x = { { 0.00, "Нам на лесозаготовках Песни Войны страшно не хватает кое-чего!" }, { 4.81, "У Пиксель на заставе Расщеплённого Дерева наш груз лезвий для пил." }, { 9.69, "За ящиком топоров от управляющего пристанью Подгребая придётся сгонять в Пиратскую бухту." }, { 16.43, "А получить груз масла и верёвок будет ещё труднее." }, { 20.21, "Верёвку стянули фурболги Колючего Меха и Гиблой Чащи, а сатиры перехватили партию масла, и теперь изводят его на свои гадкие ритуалы на Ночной поляне, Сатирнааре и Ксавиане!" }, { 33.55, "Ты мне поможешь?" } } }, t = { d = 7.4, g = 1, v = "orc-male#60", n = { m = 68, f = 69 }, c = { m = { { 0.00, "Замечательно!" }, { 1.20, "Ты избавил меня от больших забот!" }, { 4.24, "Но не думай, что я буду неблагодарен!" } }, f = { { 0.00, "Замечательно!" }, { 1.17, "Ты избавила меня от больших забот!" }, { 4.23, "Но не думай, что я буду неблагодарен!" } } } } },
    [6581] = { t = { d = 4.8, v = "goblin-female#63", n = { x = 37 }, c = { x = { { 0.00, "Само совершенство – то, что надо!" }, { 3.34, "Ладно, вот груз." } } } } },
    [6582] = { d = 37.6, g = 1, v = "creature/dragon", n = { m = 332, f = 333 }, c = { m = { { 0.00, "Все мы дети Смертокрыла, ничтожество." }, { 3.41, "И наша власть над младшими аспектами должна укрепиться." }, { 8.85, "Если ты действительно достоин возвышения, то другие драконы должны дрожать от одних звуков твоего имени." }, { 18.58, "Найди их вожаков и сокруши во имя нашего Отца!" }, { 22.99, "Отправляйся в Зимние ключи и найди там дракона по имени Провидец." }, { 29.07, "Убей его и любого синего дракона, кто осмелится встать на твоём пути, и принеси мне его череп." } }, f = { { 0.00, "Все мы дети Смертокрыла, ничтожество." }, { 3.39, "И наша власть над младшими аспектами должна укрепиться." }, { 8.89, "Если ты действительно достойна возвышения, то другие драконы должны дрожать от одних звуков твоего имени." }, { 18.65, "Найди их вожаков и сокруши во имя нашего Отца!" }, { 23.03, "Отправляйся в Зимние ключи и найди там дракона по имени Провидец." }, { 29.06, "Убей его и любого синего дракона, кто осмелится встать на твоём пути, и принеси мне его череп." } } }, t = { d = 4.4, v = "creature/dragon", n = { x = 39 }, c = { x = { { 0.00, "Одно исссс нессскольких ссаданий иссполнено..." } } } } },
    [6583] = { d = 31.0, g = 1, v = "creature/dragon", n = { m = 289, f = 289 }, c = { m = { { 0.00, "Так же как наш отец сокрушил самих Аспектов, так и мы должны сеять хаос и страх среди их детей." }, { 8.29, "Ты должен доказать свою боеспособность перед бессонно грезящими, я говорю о племени зелёных драконов." }, { 17.14, "Отправляйся в Болото Печали и порази вожака зелёных драконов Сомнуса." }, { 23.22, "Не сдерживай своей ненависти, раздави его как червяка, и вернись ко мне с его черепом." } }, f = { { 0.00, "Так же как наш отец сокрушил самих Аспектов, так и мы должны сеять хаос и страх среди их детей." }, { 8.38, "Ты должна доказать свою боеспособность перед бессонно грезящими, я говорю о племени зелёных драконов." }, { 17.32, "Отправляйся в Болото Печали и порази вожака зелёных драконов Сомнуса." }, { 23.46, "Не сдерживай своей ненависти, раздави его как червяка, и вернись ко мне с его черепом." } } }, t = { d = 3.3, v = "creature/dragon", n = { x = 24 }, c = { x = { { 0.00, "Ещё одно испытание пройдено..." } } } } },
    [6584] = { d = 30.0, v = "creature/dragon", n = { x = 261 }, c = { x = { { 0.00, "Дозорные Времени, дети Ноздорму – Повелителя Вечноссссти..." }, { 5.58, "Трое из них охраняют Пещеры Времени, но только один из этих троих представляет интерес для чёрных драконов: Изменяющий время Хроналис, любимый отпрыск Ноздорму." }, { 20.62, "Расправьсссся с ним так, чтобы даже песок в его часах рыдал от ужаса, и вернись ко мне с его черепом." } } }, t = { d = 5.7, v = "creature/dragon", n = { x = 39 }, c = { x = { { 0.00, "Оссталссся только один..." }, { 2.79, "Самый ненависссстный..." } } } } },
    [6585] = { d = 32.6, v = "creature/dragon", n = { x = 283 }, c = { x = { { 0.00, "Над горами Грим Батола отец наш бился против объединённых сил Аспектов." }, { 6.82, "Но коварное предательство Алекстразы дало им возможность избежать его гнева." }, { 14.26, "Посссзорное пятно на иссстории нашшшего рода." }, { 18.72, "Теперь Грим Батол стерегут красные драконы." }, { 23.01, "Их военачальник Акстроз должен быть убит, а его череп доставлен мне." }, { 29.66, "Вперёд, птенчик!" }, { 31.23, "За нашего Отца!" } } }, t = { d = 17.1, g = 1, v = "creature/dragon", n = { m = 155, f = 156 }, c = { m = { { 0.00, "Я сомневался, стоишь ли ты посвящения, птенчик." }, { 4.30, "Но ты выказал немалое упорство, побеждая наших врагов и добывая честь нашему роду." }, { 11.91, "Теперь я должен подготовить черепа для твоего возвышения." } }, f = { { 0.00, "Я сомневался, стоишь ли ты посвящения, птенчик." }, { 4.30, "Но ты выказала немалое упорство, побеждая наших врагов и добывая честь нашему роду." }, { 11.99, "Теперь я должен подготовить черепа для твоего возвышения." } } } } },
    [6601] = { d = 38.1, g = 1, v = "creature/dragon", n = { m = 351, f = 352 }, c = { m = { { 0.00, "Из черепов наших врагов сделан медальон." }, { 3.67, "Ты его ссснаешшь, не правда ли?" }, { 7.01, "Ты несомненно видел его на ваших старейшинах." }, { 11.08, "Возьми его, птенчик, отнеси на Пик и отдай генералу Драккисату." }, { 16.75, "Генерал наложит на него последнее заклятье, чтобы настроить амулет на тебя." }, { 23.53, "Ты будешь носить его как знак доблести, обозначающий твою принадлежность к одному из самых привилегированных слоёв нашего общества, Защитникам Царицы Драконов." }, { 37.50, "Иди же!" } }, f = { { 0.00, "Из черепов наших врагов сделан медальон." }, { 3.67, "Ты его ссснаешшь, не правда ли?" }, { 6.87, "Ты несомненно видела его на ваших старейшинах." }, { 11.02, "Возьми его, птенчик, отнеси на Пик и отдай генералу Драккисату." }, { 16.69, "Генерал наложит на него последнее заклятье, чтобы настроить амулет на тебя." }, { 23.47, "Ты будешь носить его как знак доблести, обозначающий твою принадлежность к одному из самых привилегированных слоёв нашего общества, Защитникам Царицы Драконов." }, { 37.44, "Иди же!" } } }, t = { d = 13.8, v = "creature/rexxar", n = { x = 138 }, c = { x = { { 0.00, "Пара медных грошей стоят больше чем вся эта драконья болтовня." }, { 5.28, "На твоём месте, я не придавал бы столько значения их словам, некоторое хвастовство присуще всему их роду." } } } } },
    [6602] = { d = 36.8, v = "creature/rexxar", n = { x = 376 }, c = { x = { { 0.00, "Как насчёт того, чтобы нанести визит генералу?" }, { 3.79, "На этот раз – никаких иллюзий и прикрытий." }, { 7.22, "Церемония?.." }, { 8.24, "Весьма изящное определение для той кровавой бойни, которой так любят услаждать себя чёрные драконы." }, { 16.25, "Всё, чего недостаёт этому амулету – кровь генерала Драккисата." }, { 21.21, "Весьма примитивная защита." }, { 23.40, "Я расскажу тебе, как разрешить эту маленькую проблему." }, { 27.84, "Отправляйся к пику Чёрной горы и прикончи Драккисата." }, { 32.14, "Принеси мне его кровь, и я активирую ключ от Логова Ониксии." } } }, t = { d = 17.1, v = "creature/rexxar", n = { x = 147 }, c = { x = { { 0.00, "Эту победу будут помнить много лет, можешь мне поверить." }, { 5.22, "Амулет Пламени Дракона откроет тебе путь в Логово Ониксии." }, { 11.38, "Собирай своих союзников: я верю, ты принесёшь Орде новую победу!" } } } } },
    [6603] = { d = 37.5, v = "goblin-female#63", n = { x = 401 }, c = { x = { { 0.00, "В Зимних ключах какая-то заваруха!" }, { 2.60, "Я некоторое время жила в тех диких местах и в этих вещах разбираюсь..." }, { 7.88, "Я всегда с гордостью это говорю." }, { 10.35, "По мне, так время, что я прожила в холмах, прямо-таки золотое времечко." }, { 15.56, "Помогает развивать быстроту рефлексов, сохранять холодную голову и держать ухо востро..." }, { 22.17, "Чтобы так разбираться в ситуации в диких краях, как я, надо быть зрелым и иметь хорошие мозги." }, { 29.19, "Ладно, о чём, бишь, я?" }, { 30.79, "А, да, заваруха." }, { 31.99, "Найди Донову Снегонору у горячих источников, и она расскажет тебе побольше." } } }, t = { d = 5.0, v = "dwarf-female#34", n = { x = 47 }, c = { x = { { 0.00, "О, привет!" }, { 0.93, "Значит, Мегги рассказала тебе о моих трудностях?" } } } } },
    [6604] = { d = 22.2, v = "goblin-male", n = { x = 241 }, c = { x = { { 0.00, "Вы заметили заброшенный лагерь к югу отсюда?" }, { 3.33, "Такое впечатление, что дикие совухи сошли с ума и уничтожили всё, до чего смогли дотянуться!" }, { 10.19, "Я слыхал, что один из выживших после этой атаки сейчас приходит в себя в деревне Звездопада, к западу отсюда." }, { 18.38, "Мне очень любопытно, что же там произошло... а вам нет?" } } }, t = { d = 2.4, v = "dwarf-male", n = { x = 24 }, c = { x = { { 0.00, "Слушаю, чем могу быть полезен?" } } } } },
    [6605] = { d = 33.0, v = "goblin-male", n = { x = 368 }, c = { x = { { 0.00, "Я только что вернулся из Осквернённого леса." }, { 3.17, "По пути я останавливался на Заставе Отравленной Крови, и познакомился с одной очень странной дамочкой…" }, { 10.62, "Казалось, она зациклилась на одной вещи и, полагаю, я мог бы сказать вам, на чём именно, но думаю, лучше она сама вам это объяснит." }, { 20.25, "Если вам стало интересно, отправляйтесь на Заставу Отравленной Крови, в западной части Осквернённого леса и поищите Винну Хеззард." }, { 29.76, "Кто знает, может быть, ей нужна ваша помощь..." } } }, t = { d = 7.7, g = 1, v = "scourge-female#79", n = { x = 40 }, c = { m = { { 0.00, "О, герой." }, { 1.20, "Вижу, ещё есть надежда." }, { 4.04, "Ты здесь, чтобы мне помочь?" } }, f = { { 0.00, "О, героиня." }, { 1.47, "Вижу, ещё есть надежда." }, { 4.40, "Ты здесь, чтобы мне помочь?" } } } } },
    [6606] = { d = 28.6, v = "goblin-male", n = { x = 317 }, c = { x = { { 0.00, "Немного удачи никому не повредит, так ведь?" }, { 3.17, "Иногда даже крошечного преимущества достаточно, чтобы обратить всё в свою пользу..." }, { 9.31, "Недавно мне довелось познакомиться с одной довольно эксцентричной особой." }, { 14.66, "Она сделала мне счастливый амулет... не бесплатно, разумеется." }, { 19.21, "Но, поверь уж мне, он того стоит!" }, { 21.66, "Может, тебе тоже такой нужен?" }, { 23.97, "Найди знахарку Мау'ари в Круговзоре." }, { 26.67, "Свой амулет я тебе не отдам!" } } } , t = { d = 6.0, v = "CatQuest Extended", c = { x = {} } }},
    [6607] = { d = 31.7, g = 1, v = "human-male", n = { m = 367, f = 367 }, c = { m = { { 0.00, "Не скажу, что мне так уж нравится рыбачить." }, { 2.80, "Хотя занимаюсь этим уже лет двадцать, а то и все тридцать." }, { 6.67, "Люди занимаются своим делом по разным причинам." }, { 9.89, "Я не говорю, что ты должен убить на рыбалку тридцать лет, или выловить всю рыбу в этом море, чтобы стать хорошим рыбаком." }, { 17.94, "Я думаю, тебе просто надо собраться и решиться несколько часов просиживать зад на берегу, ничего не делая." }, { 25.03, "Вот что я тебе скажу, поймай мне несколько редких рыб из этого списка, и я взамен научу тебя кой-чему." } }, f = { { 0.00, "Не скажу, что мне так уж нравится рыбачить." }, { 2.80, "Хотя занимаюсь этим уже лет двадцать, а то и все тридцать." }, { 6.67, "Люди занимаются своим делом по разным причинам." }, { 9.89, "Я не говорю, что ты должна убить на рыбалку тридцать лет, или выловить всю рыбу в этом море, чтобы стать хорошим рыбаком." }, { 17.94, "Я думаю, тебе просто надо собраться и решиться несколько часов просиживать зад на берегу, ничего не делая." }, { 25.03, "Вот что я тебе скажу, поймай мне несколько редких рыб из этого списка, и я взамен научу тебя кой-чему." } } }, t = { d = 5.6, v = "human-male", n = { x = 52 }, c = { x = { { 0.00, "Вот это, я понимаю, улов!" }, { 2.06, "Поди сюда, дай-ка я тебе покажу пару трюков." } } } } },
    [6608] = { d = 21.9, v = "orc-male", n = { x = 198 }, c = { x = { { 0.00, "Лумак больше не может тебя учить." }, { 2.92, "Нечему больше учить тебя." }, { 5.16, "Найди друга Лумака, Ната Пэгла." }, { 7.93, "Он человек, не еда!" }, { 9.58, "Нат друг Лумака!" }, { 10.93, "Он тебя научит ловить рыбу лучше." }, { 13.84, "Ната можно найти в Пылевых топях, к югу от Тераморо... как его там." }, { 19.53, "Он, наверное, удит рыбу." }, { 21.63, "Иди!" } } }, t = { d = 6.6, g = 1, v = "human-male", n = { m = 60, f = 63 }, c = { m = { { 0.00, "Так ты чё, друг Лумака?" }, { 1.80, "Рыбная ловля?" }, { 2.95, "Чего я о ней не знаю, того и знать не стоит!" } }, f = { { 0.00, "Так ты чё, подруга Лумака?" }, { 2.07, "Рыбная ловля?" }, { 3.21, "Чего я о ней не знаю, того и знать не стоит!" } } } } },
    [6609] = { d = 28.3, g = 1, v = "dwarf-male", n = { m = 287, f = 289 }, c = { m = { { 0.00, "Я же дворф, парень, это ж без очков видать!" }, { 3.21, "Не моё дело рыбу ловить!" }, { 5.09, "Ты только глянь на меня!" }, { 6.90, "Я ж, считай, каменный!" }, { 8.57, "С меня больше нечего взять – всё тебе отдал!" }, { 11.92, "Я тебя научил всему, что умел, балда!" }, { 14.80, "Ещё не понял?" }, { 15.80, "А, да ладно." }, { 16.74, "Есть у меня старый дружок в Калимдоре, который сможет тебе помочь." }, { 21.76, "Его зовут Нат Пэгл, он хороший парень." }, { 24.64, "Ищи его на островах к югу от Терамора." }, { 27.58, "Ну, топай!" } }, f = { { 0.00, "Я же дворф, подруга, это ж без очков видать!" }, { 3.27, "Не моё дело рыбу ловить!" }, { 5.13, "Ты только глянь на меня!" }, { 6.93, "Я ж, считай, каменный!" }, { 8.60, "С меня больше нечего взять – всё тебе отдал!" }, { 11.93, "Я тебя научил всему, что умел, балда!" }, { 14.79, "Ещё не поняла?" }, { 15.86, "А, да ладно." }, { 16.79, "Есть у меня старый дружок в Калимдоре, который сможет тебе помочь." }, { 21.79, "Его зовут Нат Пэгл, он хороший парень." }, { 24.66, "Ищи его на островах к югу от Терамора." }, { 27.59, "Ну, топай!" } } }, t = { d = 5.2, v = "human-male", n = { x = 57 }, c = { x = { { 0.00, "У меня на островке всегда найдётся место для гостей..." }, { 3.96, "Насколько помню..." } } } } },
    [6610] = { d = 24.7, g = 1, v = "goblin-male#108", n = { m = 264, f = 264 }, c = { m = { { 0.00, "Тебе случалось слышать о мидиях с сюрпризом?" }, { 3.34, "Конечно же нет!" }, { 4.48, "Это мой последний кулинарный шедевр." }, { 7.22, "Ах, от одной мысли слюнки текут." }, { 9.69, "К сожалению, у меня кончились все припасы, и я не могу его сделать!" }, { 14.71, "Хочешь сделку?" }, { 15.84, "Принеси мне нужные продукты, а я поучу тебя готовить, и даже дам парочку омлетов с мидиями!" }, { 22.66, "Согласен??" }, { 23.46, "Вот, что мне нужно:" } }, f = { { 0.00, "Тебе случалось слышать о мидиях с сюрпризом?" }, { 3.31, "Конечно же нет!" }, { 4.44, "Это мой последний кулинарный шедевр." }, { 7.15, "Ах, от одной мысли слюнки текут." }, { 9.60, "К сожалению, у меня кончились все припасы, и я не могу его сделать!" }, { 14.56, "Хочешь сделку?" }, { 15.69, "Принеси мне нужные продукты, а я поучу тебя готовить, и даже дам парочку омлетов с мидиями!" }, { 22.44, "Согласна??" }, { 23.24, "Вот, что мне нужно:" } } }, t = { d = 7.3, v = "goblin-male#108", n = { x = 64 }, c = { x = { { 0.00, "Вот ты полакомишься." }, { 2.17, "Смотри и учись!" }, { 3.84, "*Дирг начинает готовить мидии с сюрпризом.*" } } } } },
    [6611] = { d = 26.1, g = 1, v = "troll-female#135", n = { m = 277, f = 277 }, c = { m = { { 0.00, "Как может Замджа научить тебя всему на свете?" }, { 3.48, "Ты знаешь все кулинарные заговоры Замджи и требуешь новых!" }, { 7.82, "Замджа ничем помочь не может." }, { 10.09, "Пусть толстый герой пойдёт в Прибамбасск." }, { 13.10, "Найдёшь там мелкого гоблина по имени Могиль – вот он тебе и поможет, обжора." }, { 18.71, "Когда станешь великим поваром – вернёшься, научишь Замджу всему, что знаешь, а?" }, { 24.60, "Ну, ступай, ступай." } }, f = { { 0.00, "Как может Замджа научить тебя всему на свете?" }, { 3.48, "Ты знаешь все кулинарные заговоры Замджи и требуешь новых!" }, { 7.83, "Замджа ничем помочь не может." }, { 10.10, "Пусть толстая героиня пойдёт в Прибамбасск." }, { 13.25, "Найдёшь там мелкого гоблина по имени Могиль – вот он тебе и поможет, обжора." }, { 18.87, "Когда станешь великим поваром – вернёшься, научишь Замджу всему, что знаешь, а?" }, { 24.75, "Ну, ступай, ступай." } } }, t = { d = 12.3, v = "goblin-male#108", n = { x = 154 }, c = { x = { { 0.00, "Ох!" }, { 0.97, "Фу!" }, { 1.29, "Тьфу!" }, { 1.77, "В чём дело?" }, { 3.54, "Ты разве не знаешь, что в коже очень много белка и чрезвычайно мало углеводов?" }, { 10.63, "Ничего, узнаешь ещё!" } } } } },
    [6612] = { d = 22.0, g = 1, v = "dwarf-male", n = { m = 234, f = 233 }, c = { m = { { 0.00, "Судя по твоему половнику, ты знаешь, чего хочешь." }, { 3.80, "Да вот научить мне тебя нечему." }, { 6.18, "Но тебе свезло, я знаю одного парня." }, { 9.04, "Он гоблин, и считается первым поваром Калимдора." }, { 12.70, "Да, приятель, придётся тебе податься до Калимдора." }, { 16.44, "Иди-ка в Прибамбасск и сыщи Могиля Быстроруба." }, { 19.97, "Он тебя прямиком и направит." } }, f = { { 0.00, "Судя по твоему половнику, ты знаешь, чего хочешь." }, { 3.82, "Да вот научить мне тебя нечему." }, { 6.20, "Но тебе свезло, я знаю одного парня." }, { 9.06, "Он гоблин, и считается первым поваром Калимдора." }, { 12.74, "Да, подруга, придётся тебе податься до Калимдора." }, { 16.42, "Иди-ка в Прибамбасск и сыщи Могиля Быстроруба." }, { 19.97, "Он тебя прямиком и направит." } } }, t = { d = 9.0, g = 1, v = "goblin-male#108", n = { x = 99 }, c = { m = { { 0.00, "Тьфу..." }, { 1.18, "Ну?" }, { 2.64, "Известно ли тебе, что в коже чрезвычайно много белка и мало углеводов, герой?" } }, f = { { 0.00, "Тьфу..." }, { 1.17, "Ну?" }, { 2.62, "Известно ли тебе, что в коже чрезвычайно много белка и мало углеводов, героиня?" } } } } },
    [6621] = { d = 42.0, g = 1, v = "orc-male", n = { x = 422 }, c = { m = { { 0.00, "К юго-востоку от Астранаара живёт ещё одно племя фурболгов, Гиблая Чаща." }, { 5.79, "Они не так многочисленны, как Колючий Мех, но их ярость в будущем может представлять угрозу." }, { 13.01, "Продемонстрировав им силу, мы сможем эту угрозу ликвидировать." }, { 17.94, "Бери этот штандарт, иди в деревню Гиблой Чащи и поставь его на их тотемном кургане." }, { 24.73, "Они попытаются уничтожить штандарт, но ты держись, пока не появится их вождь, Мургут." }, { 31.45, "Он захочет отстоять честь племени." }, { 34.17, "Принеси мне тотем, что будет на нём." }, { 37.03, "Собирай друзей." }, { 38.31, "С этим делом герой-одиночка не справится." } }, f = { { 0.00, "К юго-востоку от Астранаара живёт ещё одно племя фурболгов, Гиблая Чаща." }, { 5.84, "Они не так многочисленны, как Колючий Мех, но их ярость в будущем может представлять угрозу." }, { 13.11, "Продемонстрировав им силу, мы сможем эту угрозу ликвидировать." }, { 18.09, "Бери этот штандарт, иди в деревню Гиблой Чащи и поставь его на их тотемном кургане." }, { 24.93, "Они попытаются уничтожить штандарт, но ты держись, пока не появится их вождь, Мургут." }, { 31.70, "Он захочет отстоять честь племени." }, { 34.44, "Принеси мне тотем, что будет на нём." }, { 37.32, "Собирай друзей." }, { 38.62, "С этим делом героиня-одиночка не справится." } } }, t = { d = 14.9, g = 1, v = "orc-male", n = { m = 131, f = 132 }, c = { m = { { 0.00, "Хорошая работа." }, { 1.47, "Бросив вызов Гиблой Чаще и победив их вождя, ты крепко вдолбил в их головы:" }, { 8.42, "С Ордой шутки плохи." }, { 10.38, "Теперь это племя долго не осмелится досаждать нам." } }, f = { { 0.00, "Хорошая работа." }, { 1.42, "Бросив вызов Гиблой Чаще и победив их вождя, ты крепко вдолбила в их головы:" }, { 8.23, "С Ордой шутки плохи." }, { 10.13, "Теперь это племя долго не осмелится досаждать нам." } } } } },
    [6622] = { d = 46.3, v = "scourge-male#82", n = { x = 496 }, c = { x = { { 0.00, "Добрый день, доктор." }, { 1.58, "Вы должны будете пройти тест на оказание срочной медицинской помощи." }, { 6.79, "Если тест будет пройдён успешно, вы вольетесь в ряды наших лучших травматологов." }, { 12.90, "А теперь внимание!" }, { 14.34, "Раненые, находящиеся в критическом состоянии, должны получить помощь первыми." }, { 20.24, "После критически раненых следует перевязать тяжёлых пациентов." }, { 24.97, "Потом можно заняться и обычными ранеными." }, { 28.20, "Для прохождения теста вам нужно спасти пятнадцать пациентов." }, { 33.38, "Если шесть пациентов умрут, так и не дождавшись перевязки, испытание будет провалено." }, { 39.49, "Для этого теста вам будут предоставлены специальные бинты." }, { 45.31, "Удачи, доктор." } } }, t = { d = 4.5, v = "scourge-male#82", n = { x = 43 }, c = { x = { { 0.00, "Доктор, добро пожаловать в ряды травматологов Орды." } } } } },
    [6623] = { d = 27.0, v = "orc-male", n = { x = 270 }, c = { x = { { 0.00, "А вот и наш доктор!" }, { 1.56, "Рад новой встрече." }, { 3.11, "У меня для тебя замечательные новости." }, { 6.30, "Доктор Грегори Виктор, главный травматолог Орды, предлагает тебе поработать у него в Павшем Молоте." }, { 14.59, "Такой шанс выпадает раз в жизни!" }, { 17.26, "Лично я отдал бы всё на свете за возможность поработать под руководством великого Грегори Виктора!" }, { 25.26, "Не упусти свою удачу!" } } }, t = { d = 4.2, v = "scourge-male#82", n = { x = 33 }, c = { x = { { 0.00, "Отлично." }, { 0.94, "Надевайте халат, работа не ждёт!" } } } } },
    [6624] = { d = 36.6, v = "human-male", n = { x = 443 }, c = { x = { { 0.00, "Здравствуйте, доктор." }, { 1.46, "Вам сегодня предстоит пройти испытание на очерёдность оказания помощи раненым." }, { 6.68, "Если вы успешно пройдёте этот экзамен, вы будете приняты в ряды престижного сообщества травматологов Альянса." }, { 14.04, "А теперь слушайте внимательно!" }, { 16.10, "Сначала необходимо оказать помощь тяжелораненым." }, { 19.38, "После – тем, у кого ранения средней тяжести." }, { 22.42, "Последними идут легкораненые." }, { 24.43, "Вы должны оказать помощь пятнадцати пациентам, чтобы пройти этот экзамен." }, { 29.71, "Если шесть пациентов умрут, так и не дождавшись помощи, экзамен будет считаться проваленным." }, { 35.91, "Удачи, доктор." } } }, t = { d = 4.1, v = "human-male", n = { x = 46 }, c = { x = { { 0.00, "Доктор, добро пожаловать в ряды травматологов Альянса!" } } } } },
    [6625] = { d = 26.0, v = "dwarf-female#33", n = { x = 299 }, c = { x = { { 0.00, "Полагаю, вы и есть тот самый доктор." }, { 2.64, "Приятно познакомиться." }, { 4.29, "У меня есть для вас замечательная новость!" }, { 7.33, "Густаф Ванхорцен, главный врач-травматолог Альянса, делает вам личное предложение приехать к нему в Терамор." }, { 15.25, "Такая возможность выпадает раз в жизни!" }, { 18.16, "Я бы всё отдала за возможность учиться у великого доктора Густафа Ванхорцена!" }, { 23.77, "Не упустите возможности, доктор!" } } }, t = { d = 3.4, v = "human-male", n = { x = 28 }, c = { x = { { 0.00, "Чудесно." }, { 0.88, "Мойте руки, и сразу начнём!" } } } } },
    [6626] = { d = 35.3, v = "nightelf-female#51", n = { x = 391 }, c = { x = { { 0.00, "Отрёкшиеся не стремятся превратить смертных в себе подобных... насколько мне известно." }, { 6.27, "Однако этот посланник, видимо, охотно превращает в нежить всех желающих." }, { 11.68, "Я начинаю думать, что на самом деле он работает на Плеть." }, { 15.88, "Однако сейчас меня больше беспокоит не он, а его последователи, число которых всё возрастает." }, { 22.82, "Я вижу, что каждый день из тьмы выползают всё новые и новые его приспешники, пресмыкающиеся перед ним в жажде власти." }, { 31.42, "Я слишком слаба, чтобы справиться с ними." }, { 34.56, "Помоги мне." } } }, t = { d = 23.5, g = 1, v = "nightelf-female#51", n = { m = 270, f = 274 }, c = { m = { { 0.00, "Спасибо." }, { 0.65, "Ты оказал мне неоценимую помощь!" }, { 3.00, "Я продолжу наблюдать за посланником и иглогривами." }, { 6.58, "Если же ты ищешь более серьёзных противников, собери соратников и отправляйся к пещере, напоминающей кабанью утробу." }, { 14.93, "Не сомневаюсь, внутри скрываются создания, с которыми будет интересно померяться силами столь великому воителю." } }, f = { { 0.00, "Спасибо." }, { 0.66, "Ты оказала мне неоценимую помощь!" }, { 3.12, "Я продолжу наблюдать за посланником и иглогривами." }, { 6.78, "Если же ты ищешь более серьёзных противников, собери соратников и отправляйся к пещере, напоминающей кабанью утробу." }, { 15.29, "Не сомневаюсь, внутри скрываются создания, с которыми будет интересно померяться силами столь великой воительнице." } } } } },
    [6627] = { d = 11.6, g = 1, v = "tauren-male#68", n = { m = 107, f = 110 }, c = { m = { { 0.00, "Ты принёс мне книгу, и я должен задать тебе вопрос." }, { 4.32, "Ты готов?" }, { 5.15, "Спешить нам некуда, так что не торопись." }, { 8.48, "Можешь ответить мне в любое время." } }, f = { { 0.00, "Ты принесла мне книгу, и я должен задать тебе вопрос." }, { 4.55, "Ты готова?" }, { 5.46, "Спешить нам некуда, так что не торопись." }, { 8.80, "Можешь ответить мне в любое время." } } }, t = { d = 8.2, g = 1, v = "tauren-male#68", n = { m = 64, f = 65 }, c = { m = { { 0.00, "Отличная работа, герой." }, { 2.32, "Ты изучил книгу как следует и прошёл ещё одно наше испытание." } }, f = { { 0.00, "Отличная работа, героиня." }, { 2.46, "Ты изучила книгу как следует и прошла ещё одно наше испытание." } } } } },
    [6628] = { d = 20.6, g = 1, v = "scourge-male#83", n = { m = 214, f = 216 }, c = { m = { { 0.00, "Вот мы и встретились снова." }, { 2.17, "Ты проявил недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос." }, { 12.17, "Когда будешь готов, подойди и поговори со мной, но перед этим как следует подготовься." }, { 19.12, "Спешить нам некуда." } }, f = { { 0.00, "Вот мы и встретились снова." }, { 2.07, "Ты проявила недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос." }, { 11.68, "Когда будешь готова, подойди и поговори со мной, но перед этим как следует подготовься." }, { 18.39, "Спешить нам некуда." } } }, t = { d = 8.5, g = 1, v = "scourge-male#83", n = { m = 81, f = 82 }, c = { m = { { 0.00, "Отличная работа." }, { 1.45, "Я сомневался, что у тебя хватит терпения изучить этот текст, но ты дал верный ответ." } }, f = { { 0.00, "Отличная работа." }, { 1.44, "Я сомневался, что у тебя хватит терпения изучить этот текст, но ты дала верный ответ." } } } } },
    [6629] = { d = 30.5, v = "tauren-male", n = { x = 273 }, c = { x = { { 0.00, "Что ж, с негодяями из клана Зловещего Тотема тебе удалось расправиться отлично." }, { 7.23, "Но Грундиг Тёмное Облако и его личная банда громил куда хуже." }, { 12.98, "Именно он возглавлял то жестокое нападение на мою деревню." }, { 18.32, "Если осмелишься, то найдёшь его на Заставе Зловещего Тотема чуть дальше по дороге на запад." }, { 26.62, "Убей его, и я буду вечно тебе признателен." } } }, t = { d = 9.1, g = 1, v = "tauren-male", n = { x = 60 }, c = { m = { { 0.00, "Грундиг Тёмное Облако мёртв!" }, { 3.17, "Путник, за это деяние я буду вечно признателен тебе!" } }, f = { { 0.00, "Грундиг Тёмное Облако мёртв!" }, { 3.05, "Путница, за это деяние я буду вечно признателен тебе!" } } } } },
    [6641] = { d = 37.8, v = "orc-male", n = { x = 365 }, c = { x = { { 0.00, "Ворша Хлестунья... это омерзительная гидра, что рыщет в морях..." }, { 5.46, "Она нападает на нашу заставу почём зря, уничтожая всё на своём пути." }, { 11.15, "Но я готов драться." }, { 12.82, "Я готов уничтожить гидру и положить конец её нападениям на Зорам'гар." }, { 18.66, "Наги почитают эту гадкую тварь и поддерживают в её честь пламя на жаровне, что находится на острове у побережья." }, { 27.98, "Думаю, если мы её загасим, то разъярённая Ворша вылезет из моря." }, { 33.37, "Нам понадобится помощь, так что приведи крепких друзей." } } }, t = { d = 15.2, v = "orc-male", n = { x = 154 }, c = { x = { { 0.00, "С тех пор, как я сюда прибыл, я пережил много нападений наг." }, { 4.73, "Мне прямо легче на душе становится от мысли, что Ворша больше не будет разгуливать где ей вздумается." }, { 12.77, "Мы в большом долгу перед тобой." } } } } },
    [6642] = { t = { d = 11.4, g = 1, v = "dwarf-male", n = { m = 121, f = 122 }, c = { m = { { 0.00, "Твой дар приняли и оценили." }, { 2.12, "Ты заслужил добрую славу." }, { 4.16, "Если братство удостоверится в твоей преданности, тебе дадут доступ к тайнам древних ремёсел." } }, f = { { 0.00, "Твой дар приняли и оценили." }, { 2.12, "Ты заслужила добрую славу." }, { 4.24, "Если братство удостоверится в твоей преданности, тебе дадут доступ к тайнам древних ремёсел." } } } } },
    [6643] = { t = { d = 11.3, g = 1, v = "dwarf-male", n = { m = 113, f = 114 }, c = { m = { { 0.00, "Твой дар приняли и оценили." }, { 2.16, "Ты действительно достоин доверия братьев." }, { 5.48, "Думаю, рано или поздно ты получишь доступ к тайнам древних ремёсел." } }, f = { { 0.00, "Твой дар приняли и оценили." }, { 2.24, "Ты действительно достойна доверия братьев." }, { 5.75, "Думаю, рано или поздно ты получишь доступ к тайнам древних ремёсел." } } } } },
    [6644] = { t = { d = 12.9, v = "dwarf-male", n = { x = 142 }, c = { x = { { 0.00, "Твой дар приняли и оценили." }, { 2.02, "Теперь мы видим, что ты действительно ищешь дружбы с нами." }, { 6.41, "Если ты заслужишь добрую славу в братстве, мы поделимся с тобой тайнами древних ремёсел." } } } } },
    [6645] = { t = { d = 11.6, v = "dwarf-male", n = { x = 125 }, c = { x = { { 0.00, "Твой дар приняли и оценили." }, { 2.10, "Многие братья относятся к тебе с уважением." }, { 5.53, "Если ты заслужишь почёт в братстве, мы поделимся с тобой тайнами древних ремёсел." } } } } },
    [6646] = { t = { d = 8.3, v = "dwarf-male", n = { x = 86 }, c = { x = { { 0.00, "Твой дар приняли и оценили." }, { 2.19, "Если заслужишь доверие братства, тебе дадут доступ к тайнам древних ремёсел." } } } } },
    [6661] = { d = 24.5, v = "gnome-male", n = { x = 258 }, c = { x = { { 0.00, "Эй ты, стой, да?" }, { 1.14, "Ррры!.." }, { 1.68, "Зарррработать хочешь?" }, { 3.30, "У нас тут большая проблема с крысами и не хватает умелых рук." }, { 7.81, "Что ты там болтаешь?" }, { 9.29, "Всё, что от тебя требуется – взять эту флейту крысолова и сыграть подходящую мелодию." }, { 15.61, "Они пойдут за тобой хоть на край света!" }, { 18.57, "Но это лишнее – ты просто поймай пяток и принеси, они нужны нам живыми." }, { 24.02, "Ррррр..." } } }, t = { d = 8.3, v = "gnome-male", n = { x = 91 }, c = { x = { { 0.00, "Ха, хорошо сделанная работёнка, молодец!" }, { 3.05, "Моему братцу они нужны свеженькими, чтобы приготовить из них котлеты." } } } } },
    [6662] = { d = 25.4, g = 1, v = "gnome-male", n = { m = 294, f = 296 }, c = { m = { { 0.00, "Мой братишка Нипси занимается производством котлет из подземных крыс на том конце подземки." }, { 6.17, "Надо, чтобы ты доставил этот ящик с крысами к нему, пока они не протухли." }, { 10.97, "Так что давай, двигай!" }, { 13.44, "Ты ведь ездил раньше на поезде, да?" }, { 15.85, "Это очень просто." }, { 17.14, "Заходи, когда поезд прибудет – и наслаждайся поездкой." }, { 20.91, "Главное, не высовывай руки-ноги, не то на всю жисть калекой останешься." } }, f = { { 0.00, "Мой братишка Нипси занимается производством котлет из подземных крыс на том конце подземки." }, { 6.22, "Надо, чтобы ты доставила этот ящик с крысами к нему, пока они не протухли." }, { 11.13, "Так что давай, двигай!" }, { 13.27, "Ты ведь ездила раньше на поезде, да?" }, { 15.76, "Это очень просто." }, { 17.07, "Заходи, когда поезд прибудет – и наслаждайся поездкой." }, { 20.86, "Главное, не высовывай руки-ноги, не то на всю жисть калекой останешься." } } }, t = { d = 16.3, v = "gnome-male", n = { x = 189 }, c = { x = { { 0.00, "Бедняга Монти." }, { 1.09, "После того, что случилось в Гномрегане, он сам на себя не похож." }, { 5.66, "Этот парень океана в жизни не видал, а туда же – в пираты метит." }, { 10.35, "Ну, по крайней мере, он обеспечивает непрерывные поставки этих дёрганых тварей." } } } } },
    [6681] = { d = 32.2, g = 1, v = "narrator", n = { m = 323, f = 327 }, c = { m = { { 0.00, "Чёрный Ворон очень заинтересовался тобой, юный вор." }, { 4.20, "Мы наблюдали." }, { 5.31, "Тебе не хватает ловкости, но это преходяще." }, { 8.93, "Если ты хочешь стать учеником мастера Чёрного Ворона и членом Лиги убийц, стоит только принести печать Чёрного Ворона (приложенную к этому письму) в поместье Чёрный Ворон." }, { 22.94, "Первым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость." }, { 30.54, "С уважением," }, { 31.57, "Фахрад." } }, f = { { 0.00, "Чёрный Ворон очень заинтересовался тобой, юная воришка." }, { 4.53, "Мы наблюдали." }, { 5.63, "Тебе не хватает ловкости, но это преходяще." }, { 9.21, "Если ты хочешь стать ученицей мастера Чёрного Ворона и членом Лиги убийц, стоит только принести печать Чёрного Ворона (приложенную к этому письму) в поместье Чёрный Ворон." }, { 23.10, "Первым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость." }, { 30.63, "С уважением," }, { 31.66, "Фахрад." } } }, t = { d = 18.9, g = 1, v = "human-male", n = { m = 206, f = 211 }, c = { m = { { 0.00, "Отлично, юный вор." }, { 1.39, "Вид у тебя немного побитый, но ничего особенного." }, { 5.03, "Тебя ждёт долгий путь – долгий и исполненный наград." }, { 8.88, "Ты готов принять свою судьбу, войдя в число мастеров Чёрного Ворона?" }, { 13.98, "Поговори со стражами снаружи дома." }, { 16.56, "Они дадут тебе первое задание." } }, f = { { 0.00, "Отлично, юная воришка." }, { 1.69, "Вид у тебя немного побитый, но ничего особенного." }, { 5.28, "Тебя ждёт долгий путь – долгий и исполненный наград." }, { 9.06, "Ты готова принять свою судьбу, войдя в число мастеров Чёрного Ворона?" }, { 14.14, "Поговори со стражами снаружи дома." }, { 16.68, "Они дадут тебе первое задание." } } } } },
    [6701] = { t = { d = 8.0, v = "human-male", n = { x = 89 }, c = { x = { { 0.00, "Эй, отличная работа!" }, { 1.54, "Если ты продолжишь в том же духе, может, прочие разбойники перестанут над тобой смеяться." } } } } },
    [6721] = { d = 16.6, g = 1, v = "dwarf-male", n = { m = 192, f = 193 }, c = { m = { { 0.00, "Привет тебе, юный охотник." }, { 1.95, "Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга." }, { 8.80, "Тебе надо повидаться с Дазаларом в Доланааре." }, { 12.01, "Он научит тебя, как обрести собственного питомца и спутника." } }, f = { { 0.00, "Привет тебе, юная охотница." }, { 2.07, "Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга." }, { 9.14, "Тебе надо повидаться с Дазаларом в Доланааре." }, { 12.44, "Он научит тебя, как обрести собственного питомца и спутника." } } }, t = { d = 1.7, v = "nightelf-male#54", n = { x = 6 }, c = { x = { { 0.00, "Да, пора." } } } } },
    [6722] = { d = 16.8, g = 1, v = "dwarf-male", n = { m = 192, f = 193 }, c = { m = { { 0.00, "Привет тебе, юный охотник." }, { 2.04, "Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга." }, { 9.20, "Тебе надо повидаться с Дазаларом в Доланааре." }, { 12.55, "Он научит тебя, как обрести собственного питомца и спутника." } }, f = { { 0.00, "Привет тебе, юная охотница." }, { 2.05, "Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга." }, { 9.05, "Тебе надо повидаться с Дазаларом в Доланааре." }, { 12.32, "Он научит тебя, как обрести собственного питомца и спутника." } } }, t = { d = 2.7, v = "nightelf-male#54", n = { x = 17 }, c = { x = { { 0.00, "Да, пора тебя обучить..." } } } } },
    [6741] = { t = { d = 4.6, v = "orc-male", n = { x = 30 }, c = { x = { { 0.00, "Ещё раз спасибо." }, { 1.98, "Орда гордится тобой..." } } } } },
    [6761] = { d = 33.0, v = "named/3516", n = { x = 377 }, c = { x = { { 0.00, "Я поручил своему заместителю, Матренгилу Медвежьей Лапе, разобраться с призывом о помощи из Лунной поляны." }, { 7.44, "Так что по этому поводу говори с ним – НЕ со мной!" }, { 10.85, "И позволь мне дать тебе один дружеский совет." }, { 14.06, "Это я вывел нас всех из тьмы – я, а вовсе не Круг Кенария Лунной поляны, – когда наша раса потеряла всё." }, { 21.31, "Тельдрассил даёт нам новую жизнь!" }, { 23.58, "Они наверняка попытаются внушить тебе совсем другое, но только глупец поверит их пропаганде!" }, { 30.14, "Ты же, вроде, не из таких." }, { 31.97, "Или я ошибаюсь?" } } }, t = { d = 30.2, g = 1, v = "nightelf-male#59", n = { m = 359, f = 359 }, c = { m = { { 0.00, "Да, герой, спасибо, что пришёл." }, { 2.06, "Прошу прощения за это недоразумение... но взаимное недоверие между здешним верховным друидом и хранителем Ремулом с Лунной поляны прямо-таки дрожит в воздухе." }, { 12.74, "Каждый подозревает другого в кляузничестве, а ведь проблема странной порчи Тельдрассила всё ещё не решена." }, { 19.77, "Но взаимное недоверие от этого не стихает." }, { 22.62, "Как бы то ни было, у нас есть долг перед Кругом Кенария... даже если его предводители не ладят друг с другом." } }, f = { { 0.00, "Да, героиня, спасибо, что пришла." }, { 2.27, "Прошу прощения за это недоразумение... но взаимное недоверие между здешним верховным друидом и хранителем Ремулом с Лунной поляны прямо-таки дрожит в воздухе." }, { 13.05, "Каждый подозревает другого в кляузничестве, а ведь проблема странной порчи Тельдрассила всё ещё не решена." }, { 20.15, "Но взаимное недоверие от этого не стихает." }, { 23.03, "Как бы то ни было, у нас есть долг перед Кругом Кенария... даже если его предводители не ладят друг с другом." } } } } },
    [6762] = { d = 27.8, v = "nightelf-male#59", n = { x = 322 }, c = { x = { { 0.00, "Мажордом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи." }, { 4.97, "Нужно обследовать обширные пустоши к западу от Танариса... и ещё дальше, к западу от Ун'Горо." }, { 11.38, "Найди его в Ночной Гавани, главном поселении Лунной поляны." }, { 15.61, "Поскольку твои труды будут на благо всем нам, советую тебе вести себя осторожно." }, { 21.27, "Между Дарнассом и Лунной поляной трения... и как бы они не переросли со временем в нечто большее." } } }, t = { d = 30.3, g = 1, v = "nightelf-male#59", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Я Рабин Сатурна." }, { 1.24, "От лица хранителя Ремула и всех обитателей сего священного места приветствую тебя." }, { 7.26, "Я ценю твою заинтересованность и горячую готовность помочь Кругу Кенария." }, { 12.62, "Также мне ведомо о недовольстве, с которым верховный друид Дарнасса отозвался о твоей помощи нам." }, { 19.68, "Будь уверен, что всё, что делается, – делается во благо, и что тебя не коснутся необдуманные выпады, целью коих ты можешь стать." }, { 28.83, "Здесь ты среди друзей." } }, f = { { 0.00, "Я Рабин Сатурна." }, { 1.24, "От лица хранителя Ремула и всех обитателей сего священного места приветствую тебя." }, { 7.24, "Я ценю твою заинтересованность и горячую готовность помочь Кругу Кенария." }, { 12.59, "Также мне ведомо о недовольстве, с которым верховный друид Дарнасса отозвался о твоей помощи нам." }, { 19.64, "Будь уверена, что всё, что делается, – делается во благо, и что тебя не коснутся необдуманные выпады, целью коих ты можешь стать." }, { 28.83, "Здесь ты среди друзей." } } } } },
    [6781] = { t = { d = 12.6, v = "dwarf-male", n = { x = 144 }, c = { x = { { 0.00, "Это неплохие образчики." }, { 1.72, "Я могу перековать их на новую экипировку для наших воинов." }, { 5.87, "Если припасов у меня окажется достаточно, может, наши опытные воины смогут выйти на поле боя!" } } } } },
    [6801] = { t = { d = 16.3, v = "tauren-female#71", n = { x = 156 }, c = { x = { { 0.00, "Мы пролили достаточно вражеской крови." }, { 3.36, "Я смешаю эту кровь с остальной..." }, { 6.25, "И как только жертва будет принесена, Владыка Льда покажет этим псам Грозовой Вершины всю силу ярости Северных Волков!" } } } } },
    [6804] = { d = 43.6, v = "elemental-water-lord", n = { x = 440 }, c = { x = { { 0.00, "Мы отправили отряд элементалей воды на разведку в восточные пределы Лордерона, поражённые чумой нежити." }, { 8.68, "Теперь наши разведчики поражены скверной." }, { 12.25, "Повелители Вод не могут допустить, чтобы проклятая чума угрожала нашему народу!" }, { 19.02, "Возьми этот фиал." }, { 20.62, "В нём заключён один из аспектов Нептулона." }, { 24.12, "Он исцелит поражённых скверной элементалей, уничтожив проникшую в их тела заразу." }, { 30.90, "Однако этот процесс столь болезнен, что некоторые из них могут стать нестабильными." }, { 37.82, "Тебе придётся убить колыхающихся волноплесков." }, { 41.70, "Принеси мне их браслеты." } } }, t = { d = 16.0, g = 1, v = "elemental-water-lord", n = { m = 141, f = 142 }, c = { m = { { 0.00, "Ты отлично справился, герой." }, { 2.63, "Осквернённые элементали воды были позором для всего нашего племени – ведь в основе элементалей воды лежит чистота, именно в ней коренится наша сила." } }, f = { { 0.00, "Ты отлично справилась, героиня." }, { 2.70, "Осквернённые элементали воды были позором для всего нашего племени – ведь в основе элементалей воды лежит чистота, именно в ней коренится наша сила." } } } } },
    [6805] = { d = 40.2, g = 1, v = "elemental-water-lord", n = { m = 378, f = 379 }, c = { m = { { 0.00, "Мы, элементали воды, противостоим существам низших стихий." }, { 5.06, "Если и в самом деле хочешь быть нашим союзником, докажи это!" }, { 10.43, "Далеко на юге, в пустынных землях Силитуса, в скалистом уголке, именуемом Долиной Кристаллов, кишат слуги воздуха и земли." }, { 21.09, "Они защищают сокрытые там предметы силы от примитивных существ, смертных." }, { 27.48, "Мне нет никакого дела до того, что они там стерегут, я хочу, чтобы ты перебил их." }, { 34.48, "Отправляйся в Долину Кристаллов в Силитусе и уничтожь наших врагов." } }, f = { { 0.00, "Мы, элементали воды, противостоим существам низших стихий." }, { 5.06, "Если и в самом деле хочешь быть нашей союзницей, докажи это!" }, { 10.43, "Далеко на юге, в пустынных землях Силитуса, в скалистом уголке, именуемом Долиной Кристаллов, кишат слуги воздуха и земли." }, { 21.09, "Они защищают сокрытые там предметы силы от примитивных существ, смертных." }, { 27.48, "Мне нет никакого дела до того, что они там стерегут, я хочу, чтобы ты перебила их." }, { 34.56, "Отправляйся в Долину Кристаллов в Силитусе и уничтожь наших врагов." } } }, t = { d = 13.6, g = 1, v = "elemental-water-lord", n = { m = 134, f = 135 }, c = { m = { { 0.00, "Ты доказал свою доблесть и полезность для нашего народа." }, { 4.74, "Возможно, у меня будет для тебя и другая работа – работа, более достойная ценного союзника Повелителей Вод." } }, f = { { 0.00, "Ты доказала свою доблесть и полезность для нашего народа." }, { 4.76, "Возможно, у меня будет для тебя и другая работа – работа, более достойная ценного союзника Повелителей Вод." } } } } },
    [6821] = { d = 37.7, g = 1, v = "elemental-water-lord", n = { m = 362, f = 363 }, c = { m = { { 0.00, "Ты доказал мне, что способен доблестно противостоять врагам и верно служить Повелителям Вод." }, { 7.70, "Однако пока тебе приходилось выходить на бой с довольно слабыми противниками." }, { 14.25, "Сможешь ли ты сразить более могущественного врага?" }, { 18.52, "Слушай моё повеление." }, { 20.35, "На вершине Пика Чёрной горы орки изловили слугу огня, Пиростража Созерцателя Углей." }, { 27.51, "Найди место, где они его держат, и перебей и стражу, и пленника." }, { 33.08, "Принеси мне его глаз – докажи свою преданность." } }, f = { { 0.00, "Ты доказала мне, что способна доблестно противостоять врагам и верно служить Повелителям Вод." }, { 7.91, "Однако пока тебе приходилось выходить на бой с довольно слабыми противниками." }, { 14.58, "Сможешь ли ты сразить более могущественного врага?" }, { 18.92, "Слушай моё повеление." }, { 20.78, "На вершине Пика Чёрной горы орки изловили слугу огня, Пиростража Созерцателя Углей." }, { 28.07, "Найди место, где они его держат, и перебей и стражу, и пленника." }, { 33.73, "Принеси мне его глаз – докажи свою преданность." } } }, t = { d = 19.5, g = 1, v = "elemental-water-lord", n = { m = 191, f = 192 }, c = { m = { { 0.00, "Что ж, ты доказал, что у тебя довольно силы и хитрости для столь сложной задачи – ведь для того, чтобы противостоять тварям, скрывающимся в Чёрной горе, одной только силы недостаточно." }, { 15.11, "Теперь я уверен, ты станешь для нас ценным союзником..." } }, f = { { 0.00, "Что ж, ты доказала, что у тебя довольно силы и хитрости для столь сложной задачи – ведь для того, чтобы противостоять тварям, скрывающимся в Чёрной горе, одной только силы недостаточно." }, { 14.94, "Теперь я уверен, ты станешь для нас ценным союзником..." } } } } },
    [6822] = { d = 34.3, g = 1, v = "elemental-water-lord", n = { m = 319, f = 320 }, c = { m = { { 0.00, "Пришло время испытать твои силы всерьёз." }, { 3.59, "Ты готов?" }, { 4.44, "На самом дне Глубин Чёрной горы скрывается путь к Огненным Недрам." }, { 10.14, "Это оплот нашего врага, охраняемый самыми мощными служителями огня в нашем мире." }, { 17.31, "Отправляйся в Огненные Недра." }, { 19.89, "Докажи мне, что у тебя хватит сил справиться с тем, что скрывается там." }, { 25.89, "Если у тебя есть союзники, бери их с собой." }, { 29.71, "Не стоит отправляться в Огненные Недра в одиночку." } }, f = { { 0.00, "Пришло время испытать твои силы всерьёз." }, { 3.62, "Ты готова?" }, { 4.57, "На самом дне Глубин Чёрной горы скрывается путь к Огненным Недрам." }, { 10.31, "Это оплот нашего врага, охраняемый самыми мощными служителями огня в нашем мире." }, { 17.55, "Отправляйся в Огненные Недра." }, { 20.15, "Докажи мне, что у тебя хватит сил справиться с тем, что скрывается там." }, { 26.21, "Если у тебя есть союзники, бери их с собой." }, { 30.07, "Не стоит отправляться в Огненные Недра в одиночку." } } }, t = { d = 20.7, g = 1, v = "elemental-water-lord", n = { m = 201, f = 207 }, c = { m = { { 0.00, "Тебе под силу подвиги, которые большинству кажутся невозможными." }, { 5.59, "Ты вступил в схватку с тварями Огненных Недр и вышел из неё победителем." }, { 11.71, "Ты силён для столь маленького создания." }, { 14.97, "Возможно, однажды Повелители Вод заключат союз с твоим племенем." } }, f = { { 0.00, "Тебе под силу подвиги, которые большинству кажутся невозможными." }, { 5.53, "Ты вступила в схватку с тварями Огненных Недр и вышла из неё победительницей." }, { 11.97, "Ты сильна для столь маленького создания." }, { 15.35, "Возможно, однажды Повелители Вод заключат союз с твоим племенем." } } } } },
    [6823] = { d = 22.4, g = 1, v = "elemental-water-lord", n = { m = 227, f = 227 }, c = { m = { { 0.00, "Если в самом деле хочешь быть нашим союзником, докажи серьёзность своих намерений в боях против наших врагов – слуг воздуха, земли и огня." }, { 11.53, "Каждое нанесённое им поражение подорвёт их позиции в этих землях и послужит доказательством твоей приверженности благу нашего народа." } }, f = { { 0.00, "Если в самом деле хочешь быть нашей союзницей, докажи серьёзность своих намерений в боях против наших врагов – слуг воздуха, земли и огня." }, { 11.61, "Каждое нанесённое им поражение подорвёт их позиции в этих землях и послужит доказательством твоей приверженности благу нашего народа." } } }, t = { d = 23.8, g = 1, v = "elemental-water-lord", n = { m = 227, f = 230 }, c = { m = { { 0.00, "Молва о твоих необыкновенных успехах в борьбе против наших врагов облетела всех Повелителей Вод." }, { 8.14, "Некоторые из нас считали, что твоё тело слишком маленькое и хрупкое, чтобы ты мог биться в наших рядах, однако теперь никто не сомневается в твоей силе." }, { 20.99, "Ты завоевал наше уважение." } }, f = { { 0.00, "Молва о твоих необыкновенных успехах в борьбе против наших врагов облетела всех Повелителей Вод." }, { 8.28, "Некоторые из нас считали, что твоё тело слишком маленькое и хрупкое, чтобы ты могла биться в наших рядах, однако теперь никто не сомневается в твоей силе." }, { 21.60, "Ты завоевала наше уважение." } } } } },
    [6824] = { d = 45.8, g = 1, v = "elemental-water-lord", n = { m = 435, f = 436 }, c = { m = { { 0.00, "Твоя помощь для нас неоценима, и мы с неохотой отправляем тебя на последнее задание – мы не хотим терять столь полезного союзника, однако работа есть работа." }, { 13.51, "Имей в виду, если ты успешно выполнишь поставленную перед тобой задачу, это весьма существенно приблизит час нашей победы." }, { 24.29, "Мы хотим, чтобы ты уничтожил нескольких капитанов в Огненных Недрах: Люцифрона, Сульфурона, Гееннаса и Шаззраха." }, { 33.97, "Убей их и принеси их отрубленные руки." }, { 37.33, "Это потребует от тебя всех сил, но если ты преуспеешь, Повелителям огня будет нанесён ужасный удар." } }, f = { { 0.00, "Твоя помощь для нас неоценима, и мы с неохотой отправляем тебя на последнее задание – мы не хотим терять столь полезного союзника, однако работа есть работа." }, { 13.23, "Имей в виду, если ты успешно выполнишь поставленную перед тобой задачу, это весьма существенно приблизит час нашей победы." }, { 23.78, "Мы хотим, чтобы ты уничтожила нескольких капитанов в Огненных Недрах: Люцифрона, Сульфурона, Гееннаса и Шаззраха." }, { 33.34, "Убей их и принеси их отрубленные руки." }, { 36.63, "Это потребует от тебя всех сил, но если ты преуспеешь, Повелителям огня будет нанесён ужасный удар." } } }, t = { d = 21.1, v = "elemental-water-lord", n = { x = 190 }, c = { x = { { 0.00, "Это их руки!" }, { 1.25, "Тебе действительно удалось уничтожить их!" }, { 5.09, "Твоим подвигам нет числа, но последнее твоё деяние нескоро будет стёрто из памяти Повелителей Вод." }, { 14.11, "Твоё имя станет легендой." }, { 16.53, "Возвращайся ко мне, у меня найдётся для тебя работа." } } } } },
    [6825] = { t = { d = 5.7, v = "orc-female#57", n = { x = 48 }, c = { x = { { 0.00, "Флот питается плотью своих врагов." }, { 3.46, "Скоро мы двинемся в бой!" } } } } },
    [6826] = { t = { d = 7.0, v = "scourge-female#80", n = { x = 55 }, c = { x = { { 0.00, "Больше мяса!" }, { 1.37, "Чтобы мои виверны снова могли вступить в бой, нужно ещё!" } } } } },
    [6827] = { t = { d = 9.5, v = "orc-male", n = { x = 79 }, c = { x = { { 0.00, "Что это?!" }, { 0.91, "Ты думаешь, меня устроит такое качество работы, а?" }, { 5.63, "Ступай, солдат!" }, { 7.12, "Катись!" }, { 7.86, "Нужно больше мяса!" } } } } },
    [6844] = { d = 34.8, v = "nightelf-male#54", n = { x = 354 }, c = { x = { { 0.00, "Здесь полно работы, но мне кажется, главное – отнести это в Круг, на анализ." }, { 5.96, "Поверь мне, дела здесь не переводятся." }, { 8.93, "Если внутри этого хитина находится дневник, то Круг сможет заглянуть в прошлое!" }, { 15.24, "Отнеси этот дневник архивариусу Круга в Ночную Гавань." }, { 19.64, "Его зовут Умбер, он настоящий гений!" }, { 22.62, "Да, тронутый, не без того, но всё равно гений!" }, { 26.23, "Умбер находил манускрипты в куда более плохом состоянии." }, { 30.77, "Если эти записи можно восстановить, он это сделает." } } }, t = { d = 26.4, v = "human-male", n = { x = 302 }, c = { x = { { 0.00, "Жаба меня побери!" }, { 1.33, "Что это?" }, { 1.97, "Формой определённо напоминает книгу..." }, { 4.64, "Попытаюсь-ка я взломать оболочку." }, { 6.99, "Тебя прислал Лайо из Силитуса?" }, { 9.21, "До меня доходили только смутные слухи – не такие уж смутные, если хорошо подумать – об ужасах, творящихся в тех краях." }, { 17.59, "Учитывая мою нелюбовь ко всему, что напоминает насекомых, все эти сплетни – хорошая причина остаться здесь, с моими книжечками!" } } } } },
    [6845] = { d = 32.0, g = 1, v = "human-male", n = { m = 379, f = 380 }, c = { m = { { 0.00, "Короче, свяжись со мной как можно скорее... если, конечно, хочешь знать, что там внутри." }, { 5.83, "Как только я это узнаю, с удовольствием поделюсь с тобой информацией – разумеется, если там действительно окажется книга." }, { 13.90, "А пока я свяжусь с самой-большой-медведицей этого медвежьего угла, то есть, Рабином." }, { 19.55, "Он, несомненно, пожелает узнать, что за кашу ты тут заварил." }, { 23.52, "Никогда не заставляй мать-медведицу ждать... ну, если только тебе неймётся искупаться в меду." }, { 29.66, "Такое бывает, уж поверь мне." } }, f = { { 0.00, "Короче, свяжись со мной как можно скорее... если, конечно, хочешь знать, что там внутри." }, { 5.93, "Как только я это узнаю, с удовольствием поделюсь с тобой информацией – разумеется, если там действительно окажется книга." }, { 14.12, "А пока я свяжусь с самой-большой-медведицей этого медвежьего угла, то есть, Рабином." }, { 19.86, "Он, несомненно, пожелает узнать, что за кашу ты тут заварила." }, { 23.95, "Никогда не заставляй мать-медведицу ждать... ну, если только тебе неймётся искупаться в меду." }, { 30.19, "Такое бывает, уж поверь мне." } } }, t = { d = 27.4, g = 1, v = "nightelf-male#59", n = { m = 320, f = 321 }, c = { m = { { 0.00, "А – я надеялся, что у тебя найдётся для меня минутка." }, { 3.58, "Рад видеть, что ты в добром здравии." }, { 6.05, "Я получил известие, что ты идёшь с поля, и мне захотелось лично выразить тебе признательность Круга Кенария за помощь." }, { 14.07, "Несомненно, в Силитусе ещё много тайн, и то, что ты доставил Умберу, может оказаться наиболее интересным." }, { 21.16, "Прошу тебя, прими это в знак нашей благодарности за помощь." }, { 25.30, "Спасибо тебе, благородный герой." } }, f = { { 0.00, "А – я надеялся, что у тебя найдётся для меня минутка." }, { 3.55, "Рад видеть, что ты в добром здравии." }, { 6.01, "Я получил известие, что ты идёшь с поля, и мне захотелось лично выразить тебе признательность Круга Кенария за помощь." }, { 13.97, "Несомненно, в Силитусе ещё много тайн, и то, что ты доставила Умберу, может оказаться наиболее интересным." }, { 21.08, "Прошу тебя, прими это в знак нашей благодарности за помощь." }, { 25.19, "Спасибо тебе, благородная героиня." } } } } },
