    [6861] = { d = 28.4, g = 1, v = "goblin-male", n = { x = 303 }, c = { m = { { 0.00, "Я хочу опробовать свой портативный резак не меньше тебя, герой, но для того, чтобы его сделать, мне нужны материалы – много материалов!" }, { 9.70, "Сказать точнее, целая гора тория, мифрила и железа." }, { 13.50, "Кроме того, по паровой пиле на каждый резак." }, { 17.77, "Их можно достать на лесопилке." }, { 19.96, "До того, как меня поймали, я здесь всё разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины." } }, f = { { 0.00, "Я хочу опробовать свой портативный резак не меньше тебя, героиня, но для того, чтобы его сделать, мне нужны материалы – много материалов!" }, { 9.64, "Сказать точнее, целая гора тория, мифрила и железа." }, { 13.36, "Кроме того, по паровой пиле на каждый резак." }, { 16.58, "Их можно достать на лесопилке." }, { 18.72, "До того, как меня поймали, я здесь всё разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины." } } } },
