    [6881] = { t = { d = 12.6, v = "nightelf-female#51", n = { x = 136 }, c = { x = { { 0.00, "Отлично." }, { 0.70, "Сила этих чар пригодится для усиления уже имеющейся магии." }, { 5.31, "Когда энергии наберётся достаточно, я смогу её сфокусировать и воззвать к Владыке Леса о помощи." } } } } },
    [6921] = { d = 38.0, v = "troll-male", n = { x = 439 }, c = { x = { { 0.00, "Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины." }, { 6.42, "Их присутствие приведёт лишь к тому, что Стихии озлобятся на нас." }, { 10.96, "Если это так и оставить, то они захватят эти места навсегда." }, { 15.44, "Ступай в Непроглядную Пучину и найди в руинах глубинный камень." }, { 20.05, "Он должен быть где-то поблизости в воде." }, { 22.96, "В нём находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий." }, { 31.92, "Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!" } } }, t = { d = 29.5, g = 1, v = "troll-male", n = { m = 301, f = 304 }, c = { m = { { 0.00, "Это именно то, что мне было нужно!" }, { 2.79, "Глубинный сердечник – неиссякаемый кладезь информации, которую мы сможем оттуда извлечь." }, { 9.79, "Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить." }, { 18.80, "Ты сегодня хорошо потрудился, и Служители Земли весьма благодарны тебе за помощь." }, { 25.30, "Ты и всей Орде помог, и имеешь право гордиться собой." } }, f = { { 0.00, "Это именно то, что мне было нужно!" }, { 2.78, "Глубинный сердечник – неиссякаемый кладезь информации, которую мы сможем оттуда извлечь." }, { 9.75, "Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить." }, { 18.71, "Ты сегодня хорошо потрудилась, и Служители Земли весьма благодарны тебе за помощь." }, { 25.26, "Ты и всей Орде помогла, и имеешь право гордиться собой." } } } } },
    [6922] = { d = 31.0, v = "narrator", n = { x = 322 }, c = { x = { { 0.00, "Сражённый элементаль воды оставил после себя странную сферу." }, { 4.89, "Вы предполагаете, что этот предмет каким-то образом подпитывал тварь энергией." }, { 11.07, "Внутри сферы плещется грязная на вид жидкость." }, { 14.81, "Сама сфера вроде бы не поддаётся никаким физическим воздействиям." }, { 19.98, "Если кто и сможет понять, что это за штука, то это Дже'неу Санкри из Служителей Земли." }, { 26.95, "Он находится в форте Орды Зорам'гар в Ясеневом лесу." } } }, t = { d = 32.2, g = 1, v = "troll-male", n = { m = 336, f = 339 }, c = { m = { { 0.00, "Ого... вот это находка." }, { 1.85, "Говоришь, ты добыл это из барона Акваниса в Непроглядной Пучине?" }, { 6.78, "Барон Акванис давно уже считается осквернённой силой Стихии, а этот шар даст понять, что именно повергло его в скверну." }, { 15.90, "Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать." }, { 24.12, "Хорошо, что ты принёс эту штуку мне." }, { 26.86, "Прошу – прими это вместе с горячей благодарностью Служителей Земли." } }, f = { { 0.00, "Ого... вот это находка." }, { 1.85, "Говоришь, ты добыла это из барона Акваниса в Непроглядной Пучине?" }, { 6.85, "Барон Акванис давно уже считается осквернённой силой Стихии, а этот шар даст понять, что именно повергло его в скверну." }, { 15.95, "Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать." }, { 24.16, "Хорошо, что ты принесла эту штуку мне." }, { 27.11, "Прошу – прими это вместе с горячей благодарностью Служителей Земли." } } } } },
    [6941] = { t = { d = 4.5, v = "nightelf-male#59", n = { x = 49 }, c = { x = { { 0.00, "Скоро флот будет готов подняться в воздух!" }, { 3.17, "А пока – продолжай!" } } } } },
    [6942] = { t = { d = 6.9, v = "dwarf-male", n = { x = 73 }, c = { x = { { 0.00, "Продолжай своё дело, солдат!" }, { 2.25, "Грифоны Заоблачного пика готовы к вылету с минуты на минуту!" } } } } },
    [6943] = { t = { d = 12.2, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Видишь?" }, { 0.64, "Посмотри на них, солдат!" }, { 2.58, "Вот они, кружат в воздухе!" }, { 4.73, "Скоро флот Ичмена нанесёт удар в самое сердце долины!" }, { 9.03, "Грозовая Вершина будет править в небесах!" } } } } },
    [6961] = { d = 31.2, g = 1, v = "goblin-male#110", n = { m = 351, f = 352 }, c = { m = { { 0.00, "Весёлого Зимнего Покрова, дружок!" }, { 2.39, "Не забудь поздороваться с Дедушкой Зимой!" }, { 5.36, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 11.89, "Не забудь сказать ему, что хочешь получить в этом году!" }, { 15.96, "И сам не забудь купить подарки для тех, кто хорошо себя вёл весь год." }, { 20.81, "У нас богатейший выбор подарков на любой вкус!" }, { 24.11, "\"Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!\"" } }, f = { { 0.00, "Весёлого Зимнего Покрова, дружок!" }, { 2.34, "Не забудь поздороваться с Дедушкой Зимой!" }, { 5.26, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 11.66, "Не забудь сказать ему, что хочешь получить в этом году!" }, { 15.65, "И сама не забудь купить подарки для тех, кто хорошо себя вёл весь год." }, { 20.53, "У нас богатейший выбор подарков на любой вкус!" }, { 23.77, "\"Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!\"" } } }, t = { d = 33.4, v = "orc-male", n = { x = 296 }, c = { x = { { 0.00, "Хо-хо-хо!" }, { 0.90, "Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса!" }, { 8.83, "\"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!" }, { 21.26, "Все, кто хорошо себя вёл в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова." }, { 32.87, "Уррра!" } } } } },
    [6962] = { d = 19.1, g = 1, v = "orc-male", n = { m = 192, f = 191 }, c = { m = { { 0.00, "Эй, мальчуган, не окажешь ли услугу Дедушке Зиме?" }, { 4.04, "Дедушка Зима весь день провёл на ногах и сам не откажется угоститься." }, { 9.56, "Немного пряников и ледяного молока, чтобы запить, будут очень кстати." }, { 15.36, "Ты ведь любишь дедушку?" }, { 17.28, "Принесёшь мне угощение?" } }, f = { { 0.00, "Эй, девчушка, не окажешь ли услугу Дедушке Зиме?" }, { 4.02, "Дедушка Зима весь день провёл на ногах и сам не откажется угоститься." }, { 9.60, "Немного пряников и ледяного молока, чтобы запить, будут очень кстати." }, { 15.48, "Ты ведь любишь дедушку?" }, { 17.41, "Принесёшь мне угощение?" } } }, t = { d = 11.7, g = 1, v = "orc-male", n = { m = 94, f = 95 }, c = { m = { { 0.00, "Ну, спасибо!" }, { 1.21, "Угодил ты Дедушке Зиме!" }, { 3.55, "Доброго тебе праздника Зимнего Покрова." }, { 7.44, "А вот тебе кое-что... ну, за труды, понимаешь." } }, f = { { 0.00, "Ну, спасибо!" }, { 1.19, "Угодила ты Дедушке Зиме!" }, { 3.56, "Доброго тебе праздника Зимнего Покрова." }, { 7.37, "А вот тебе кое-что... ну, за труды, понимаешь." } } } } },
    [6963] = { d = 32.5, g = 1, v = "goblin-male#110", n = { m = 366, f = 370 }, c = { m = { { 0.00, "Слушай..." }, { 0.68, "Не хотелось бы разрушать праздничное волшебство, однако Пастбищам Дымного Леса нужна помощь искателя приключений вроде тебя." }, { 9.27, "У нас пропал груз сладостей, которые мы закупили к зиме, а теперь куда-то подевался ещё и наш агент, которого мы отправили разыскивать товар!" }, { 18.86, "В последний раз груз видели в Альтеракских горах, туда за ним и отправился наш агент." }, { 24.61, "Позаботься о том, чтобы и товар, и наш работник вернулись сюда в целости и сохранности!" } }, f = { { 0.00, "Слушай..." }, { 0.71, "Не хотелось бы разрушать праздничное волшебство, однако Пастбищам Дымного Леса нужна помощь искательницы приключений вроде тебя." }, { 9.89, "У нас пропал груз сладостей, которые мы закупили к зиме, а теперь куда-то подевался ещё и наш агент, которого мы отправили разыскивать товар!" }, { 19.85, "В последний раз груз видели в Альтеракских горах, туда за ним и отправился наш агент." }, { 25.82, "Позаботься о том, чтобы и товар, и наш работник вернулись сюда в целости и сохранности!" } } }, t = { d = 21.4, v = "goblin-male", n = { x = 207 }, c = { x = { { 0.00, "Т-т-ты м-м-меня с-слышишь!" }, { 2.09, "Слава б-б-богам!" }, { 3.45, "Н-нет, я не с-с-снеговик." }, { 5.40, "М-меня зовут Сакс, я раб-ботаю в Оргриммарском отделении Пастбищ Дымного Леса." }, { 11.66, "М-м-м-меня отп-правили искать пропавший товар, и тут на меня нап-пала тварь, какой я никогда не видывал!" }, { 19.94, "Бр-р, ну и холодрыга!" } } } } },
    [6964] = { d = 36.6, v = "tauren-male#67", n = { x = 352 }, c = { x = { { 0.00, "Подарки, гости, угощение... чушь собачья!" }, { 3.53, "Эти гоблины искажают саму суть праздника Зимнего Покрова." }, { 8.51, "Это время возрождения – земля спит под покровом снега, которым её укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!" }, { 20.93, "Ежели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте Сагорна Гривастого Странника." }, { 30.20, "Уверен, он будет очень удивлён, что хоть кому-то история интереснее подарков." } } }, t = { d = 32.6, v = "tauren-male#68", n = { x = 337 }, c = { x = { { 0.00, "Праздник Зимнего Покрова, говоришь?" }, { 2.87, "Увы, в прежние времена для нас, тауренов, он был куда важнее." }, { 7.75, "А теперь, похоже, другие используют древние легенды, чтобы продать побольше сладостей и подарков." }, { 15.57, "Неудивительно, что Фарманда это так огорчает." }, { 19.16, "Он и остальные таурены держатся за наше прошлое, как за боевое знамя." }, { 24.68, "Я лично считаю, что немного веселья никогда не помешает, но о происхождении праздника забывать нельзя." } } } } },
    [6981] = { d = 23.3, v = "narrator", n = { x = 255 }, c = { x = { { 0.00, "Блестящий осколок ярко-зелёный, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма." }, { 8.22, "Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаёте какое-то беспокойство." }, { 16.03, "Пожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке." } } }, t = { d = 5.5, v = "tauren-female#71", n = { x = 45 }, c = { x = { { 0.00, "О... мне никогда не приходилось видеть ничего подобного..." } } } } },
    [6982] = { d = 34.7, v = "dwarf-male#100", n = { x = 372 }, c = { x = { { 0.00, "Рудник Ледяного Зуба – это хранилище Орды." }, { 3.85, "Мой желудок не переваривает жратву, которой они кормят своих солдат, а их доспехи и оружие выглядят ужасно!" }, { 11.72, "Но... в такие времена, когда припасы столь важны, приходится использовать то, что есть." }, { 17.95, "Отправляйся в рудник Ледяного Зуба и принеси мне часть их припасов." }, { 23.52, "Это поможет Альянсу поддержать свою боевую форму, а заодно лишить воинов Орды самого необходимого." }, { 30.87, "Рудник находится далеко на юге, в глубоком тылу Орды." } } }, t = { d = 7.5, v = "dwarf-male#100", n = { x = 74 }, c = { x = { { 0.00, "Сколько припасов!" }, { 1.52, "Отличная работа." }, { 2.96, "Я проверю содержимое ящиков и раздам его нашим воинам." } } } } },
    [6983] = { d = 28.7, v = "goblin-male", n = { x = 300 }, c = { x = { { 0.00, "С-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства!" }, { 6.20, "Т-только ос-стор-р-рожно!" }, { 8.10, "Это он с-сделал из меня с-снеговика!" }, { 10.89, "Ва-ва-вам понадобится помощь!" }, { 13.14, "Я в-видел, как он шляется тут в-в-вместе с другими йети." }, { 17.36, "Он нав-верняка где-то п-поблизости!" }, { 20.02, "Отыщите мой груз, отвезите его в Оргриммар, П-пастбищам Дымного Леса, и п-п-передайте им, что м-меня надо разморозить!" } } }, t = { d = 23.4, v = "goblin-male#110", n = { x = 245 }, c = { x = { { 0.00, "Вы нашли груз!" }, { 1.10, "Вы спасли наш праздник!" }, { 2.89, "Бедный Сакс!" }, { 3.85, "Конечно же, мы немедленно отправим спасателей и придумаем, как его разморозить." }, { 9.83, "Надеюсь, он успеет прийти в себя к празднику..." }, { 13.48, "Хотя, конечно же, потом ему придётся отработать то время, которое он прогулял!" }, { 19.46, "Но в любом случае, если бы не вы, всё пошло бы прахом!" } } } } },
    [6984] = { d = 26.2, v = "goblin-male#110", n = { x = 284 }, c = { x = { { 0.00, "Спасибо тебе от \"Пастбищ Дымного Леса\" за возвращение краденых сладостей!" }, { 5.41, "И хотим мы тебе за это предложить особый подарок..." }, { 9.23, "От самого Дедушки Зимы!" }, { 11.01, "Поговори с Дедушкой Зимой, и он даст тебе подарок праздника Зимнего Покрова от нашего имени!" }, { 17.80, "От нашего села да к вашему столу – вкусная и здоровая пища от \"Пастбищ Дымного Леса\"... благодаря тебе, конечно же!" } } }, t = { d = 15.1, v = "orc-male", n = { x = 139 }, c = { x = { { 0.00, "Хо-хо-хо!" }, { 0.88, "Добро пожаловать!" }, { 2.47, "Гоблины мне сказали, что тебе нынче полагается специальный приз, и я рад отдать его." }, { 9.87, "Вот он – и весёлого тебе праздника Зимнего Покрова каждый год!" } } } } },
    [6985] = { d = 24.1, v = "orc-male", n = { x = 266 }, c = { x = { { 0.00, "Дворфы Грозовой Вершины используют Железный рудник для хранения припасов." }, { 5.63, "Сбегай на этот рудник и позаимствуй у дворфов их богатства." }, { 10.16, "Это малость подрежет крылья Грозовой Вершине, а мы получим необходимые материалы." }, { 16.40, "Действуй осторожно." }, { 17.91, "Железный рудник лежит в глубине территории Альянса, и за него постоянно идут бои." } } }, t = { d = 12.6, g = 1, v = "orc-male", n = { m = 113, f = 115 }, c = { m = { { 0.00, "Ты их добыл!" }, { 1.10, "Отличная работа!" }, { 2.59, "Надеюсь, во время набега тебе попалось несколько дворфов и ты пролил их кровь во славу клана Северного Волка!" } }, f = { { 0.00, "Ты их добыла!" }, { 1.22, "Отличная работа!" }, { 2.75, "Надеюсь, во время набега тебе попалось несколько дворфов и ты пролила их кровь во славу клана Северного Волка!" } } } } },
    [7001] = { d = 31.4, v = "troll-female#73", n = { x = 375 }, c = { x = { { 0.00, "Набат войны зовёт наших солдат к оружию!" }, { 2.89, "Мы должны восстановить боеспособность армии!" }, { 5.96, "Если в стойлах заведётся зверьё, то волчьи всадники смогут снова отправиться в бой." }, { 11.68, "Возьми этот намордник и найди следы северных волков, обитающих в ближайшем лесу." }, { 17.39, "Когда отыщешь волка, используй намордник, чтобы его приручить." }, { 21.85, "Приручённых зверей приводи ко мне, я поставлю их в стойла." }, { 25.81, "Когда стойла будут полны, наши волчьи всадники снова смогут отправиться на фронт." } } }, t = { d = 11.0, v = "troll-female#73", n = { x = 122 }, c = { x = { { 0.00, "Я могу только надеяться, что те, кого я послала за шкурами баранов, будут столь же упорны, как ты." }, { 7.06, "С такой скоростью мы заполним стойла за считанные часы!" } } } } },
    [7002] = { t = { d = 7.0, v = "orc-male#60", n = { x = 65 }, c = { x = { { 0.00, "Отлично, солдат." }, { 1.49, "Я скажу тебе, когда будет достаточно." }, { 4.85, "А пока продолжай работать!" } } } } },
    [7003] = { d = 35.4, v = "goblin-male#109", n = { x = 403 }, c = { x = { { 0.00, "Нет, если я собираюсь здесь остаться, мне решительно необходимо что-то сделать с великанами!" }, { 6.75, "Они губят весь бизнес." }, { 8.49, "Я взял за основу разновидность гномского уменьшающего луча, но внёс в конструкцию превосходные гоблинские усовершенствования!" }, { 17.52, "Дабы самому избежать различных неудобств – например, смерти, – я поручаю его испытание вам." }, { 24.34, "Испробуйте его на любых великанах, каких найдёте в Фераласе." }, { 28.82, "После уменьшения вы обнаружите на месте великана остатки миниатюризации – принесите их мне!" } } }, t = { d = 24.6, g = 1, v = "goblin-male#109", n = { m = 240, f = 240 }, c = { m = { { 0.00, "Архивеликолепно!" }, { 1.39, "Я крайне рад видеть, что вы не только вернулись живым, но и благополучно сохранили все ваши конечности!" }, { 10.09, "Нет-нет, разумеется, ультрасжиматель совершенно безопасен, как вы могли подумать!" }, { 16.94, "Я ценю ваши усилия." }, { 18.71, "Вы – добрый друг всех гоблинов!" }, { 21.33, "Примите это в знак моей признательности!" } }, f = { { 0.00, "Архивеликолепно!" }, { 1.36, "Я крайне рад видеть, что вы не только вернулись живой, но и благополучно сохранили все ваши конечности!" }, { 9.92, "Нет-нет, разумеется, ультрасжиматель совершенно безопасен, как вы могли подумать!" }, { 16.67, "Я ценю ваши усилия." }, { 18.41, "Вы – добрый друг всех гоблинов!" }, { 20.99, "Примите это в знак моей признательности!" } } } } },
    [7021] = { d = 31.4, g = 1, v = "goblin-male#110", n = { m = 358, f = 359 }, c = { m = { { 0.00, "Весёлого Зимнего Покрова, дружок!" }, { 2.35, "Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре!" }, { 6.98, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 13.39, "Не забудь сказать ему, что хочешь получить в этом году!" }, { 17.38, "И сам не забудь купить подарки для тех, кто хорошо себя вёл весь год." }, { 22.14, "У нас богатейший выбор подарков на любой вкус!" }, { 25.38, "От нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!" } }, f = { { 0.00, "Весёлого Зимнего Покрова, дружок!" }, { 2.35, "Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре!" }, { 6.99, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 13.40, "Не забудь сказать ему, что хочешь получить в этом году!" }, { 17.40, "И сама не забудь купить подарки для тех, кто хорошо себя вёл весь год." }, { 22.29, "У нас богатейший выбор подарков на любой вкус!" }, { 25.53, "От нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!" } } }, t = { d = 33.1, v = "orc-male", n = { x = 296 }, c = { x = { { 0.00, "Хо-хо-хо!" }, { 0.89, "Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса!" }, { 8.77, "\"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!" }, { 21.11, "Все, кто хорошо себя вёл в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова." }, { 32.63, "Уррра!" } } } } },
