    [7024] = { d = 32.2, g = 1, v = "goblin-male#110", n = { m = 370, f = 371 }, c = { m = { { 0.00, "Весёлого Зимнего Покрова, дружок!" }, { 2.34, "Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре!" }, { 6.97, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 13.36, "Не забудь сказать ему, что хочешь получить в этом году!" }, { 17.36, "И сам не забудь купить подарки для тех, кто хорошо себя вёл весь год." }, { 22.11, "У нас богатейший выбор подарков на любой вкус!" }, { 25.34, "Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!" } }, f = { { 0.00, "Весёлого Зимнего Покрова, дружок!" }, { 2.33, "Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре!" }, { 6.94, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 13.31, "Не забудь сказать ему, что хочешь получить в этом году!" }, { 17.29, "И сама не забудь купить подарки для тех, кто хорошо себя вёл весь год." }, { 22.15, "У нас богатейший выбор подарков на любой вкус!" }, { 25.36, "Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!" } } }, t = { d = 32.2, v = "orc-male", n = { x = 288 }, c = { x = { { 0.00, "Хо-хо-хо!" }, { 0.88, "Я Дедушка Зима, и я явился к вам благодаря добросердечию Пастбищ Дымного Леса!" }, { 7.88, "\"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!" }, { 20.10, "Все, кто хорошо себя вёл в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова." }, { 31.52, "Ур-р-ра!" } } } } },
    [7025] = { d = 21.7, g = 1, v = "dwarf-male", n = { m = 234, f = 233 }, c = { m = { { 0.00, "Эй, не окажешь ли услугу Дедушке Зиме, хм, мальчуган?" }, { 3.96, "Нет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением." }, { 12.95, "Немного пряников и ледяного молока, чтобы запить, – и будет довольно." }, { 18.18, "Ты ведь любишь дедушку и принесёшь мне угощение?" } }, f = { { 0.00, "Эй, не окажешь ли услугу Дедушке Зиме, хм, девчушка?" }, { 3.93, "Нет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением." }, { 13.02, "Немного пряников и ледяного молока, чтобы запить, – и будет довольно." }, { 18.30, "Ты ведь любишь дедушку и принесёшь мне угощение?" } } }, t = { d = 9.8, g = 1, v = "dwarf-male", n = { m = 90, f = 91 }, c = { m = { { 0.00, "Ну, ты и угодил Дедушке Зиме!" }, { 2.48, "Доброго тебе праздника Зимнего Покрова." }, { 5.86, "А вот тебе кое-что... ну, за труды, ты понимаешь." } }, f = { { 0.00, "Ну, ты и угодила Дедушке Зиме!" }, { 2.53, "Доброго тебе праздника Зимнего Покрова." }, { 5.89, "А вот тебе кое-что... ну, за труды, ты понимаешь." } } } } },
    [7026] = { t = { d = 6.3, v = "dwarf-male", n = { x = 65 }, c = { x = { { 0.00, "Отлично, солдат." }, { 1.34, "Я скажу тебе, когда будет достаточно." }, { 4.36, "А пока продолжай работать!" } } } } },
    [7027] = { d = 33.9, g = 1, v = "dwarf-female#33", n = { m = 377, f = 377 }, c = { m = { { 0.00, "Посмотри на эти стойла!" }, { 1.79, "Они совершенно пустые!" }, { 3.51, "У бригады Грозовой Вершины нет ездовых баранов, а значит, нет и кавалерии." }, { 8.95, "Ты должен помочь нам, солдат!" }, { 11.13, "Возьми учебный ошейник и отправляйся в самую глушь этой долины." }, { 15.84, "Найди альтеракских баранов, которые там бродят, и поймай их при помощи ошейника." }, { 21.74, "Как поймаешь барана, возвращайся ко мне, я поставлю его в стойла." }, { 26.51, "Когда баранов будет достаточно, я извещу командира всадников." }, { 31.08, "В твоих силах возродить нашу кавалерию!" } }, f = { { 0.00, "Посмотри на эти стойла!" }, { 1.77, "Они совершенно пустые!" }, { 3.47, "У бригады Грозовой Вершины нет ездовых баранов, а значит, нет и кавалерии." }, { 8.84, "Ты должна помочь нам, солдат!" }, { 11.00, "Возьми учебный ошейник и отправляйся в самую глушь этой долины." }, { 15.65, "Найди альтеракских баранов, которые там бродят, и поймай их при помощи ошейника." }, { 21.48, "Как поймаешь барана, возвращайся ко мне, я поставлю его в стойла." }, { 26.20, "Когда баранов будет достаточно, я извещу командира всадников." }, { 30.72, "В твоих силах возродить нашу кавалерию!" } } }, t = { d = 4.2, v = "dwarf-female#33", n = { x = 40 }, c = { x = { { 0.00, "Стойла наполняются прямо на глазах." }, { 3.26, "Так держать!" } } } } },
    [7028] = { d = 43.4, g = 1, v = "scourge-female#79", n = { x = 369 }, c = { m = { { 0.00, "На западе, в глубинах Мародона, раскинулись хрустальные пещеры Террамока..." }, { 6.97, "Это очень древнее место, герой." }, { 10.07, "А я хочу наложить лапу на часть тамошних древностей." }, { 14.94, "За огромными дверями скрыты реликвии древних богов." }, { 19.81, "Если ты отважишься бросить вызов злу, таящемуся в Мародоне, я щедро тебе заплачу." }, { 27.44, "Собери там терадрические хрустальные орнаменты и принеси их мне." }, { 33.32, "Как только я доберусь до этих орнаментов, я смогу их... изучить." }, { 39.28, "Слишком долго дремали скрытые силы..." } }, f = { { 0.00, "На западе, в глубинах Мародона, раскинулись хрустальные пещеры Террамока..." }, { 7.05, "Это очень древнее место, героиня." }, { 10.37, "А я хочу наложить лапу на часть тамошних древностей." }, { 15.30, "За огромными дверями скрыты реликвии древних богов." }, { 20.23, "Если ты отважишься бросить вызов злу, таящемуся в Мародоне, я щедро тебе заплачу." }, { 27.96, "Собери там терадрические хрустальные орнаменты и принеси их мне." }, { 33.91, "Как только я доберусь до этих орнаментов, я смогу их... изучить." }, { 39.95, "Слишком долго дремали скрытые силы..." } } }, t = { d = 10.6, v = "scourge-female#79", n = { x = 102 }, c = { x = { { 0.00, "Ха-ха-ха!" }, { 0.87, "Я так и знала, что ты вернёшься." }, { 3.55, "..." }, { 4.65, "Как легко убедить." }, { 6.31, "… пойдёт на что угодно за сходную цену." }, { 9.69, "Хе-хе-хе..." } } } } },
    [7029] = { d = 39.2, v = "tauren-male", n = { x = 370 }, c = { x = { { 0.00, "В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет всё, до чего может дотянуться." }, { 8.47, "Из-за него умирают растения." }, { 11.05, "Возьми этот фиал, и наполни его из оранжевого хрустального пруда в глубине пещер." }, { 18.27, "Внутри фиала есть особое покрытие, которое превратит яд в лекарство." }, { 24.23, "Отыщи в оранжевых пещерах гнусь-лозу и полей её целебной жидкостью." }, { 30.11, "Растение очистится от порчи, но всё равно останется в воле Злоязыкого." }, { 36.22, "Он может обратить его против тебя." } } }, t = { d = 17.9, g = 1, v = "tauren-male", n = { m = 154, f = 156 }, c = { m = { { 0.00, "Спасибо, что принёс мне фиал." }, { 2.78, "Я исследую остатки жидкости." }, { 5.57, "Хотя впереди много работы, зло, совершённое Злоязыким в Мародоне, хотя бы отчасти исправлено." }, { 14.52, "Прими это в знак моей благодарности." } }, f = { { 0.00, "Спасибо, что принесла мне фиал." }, { 2.85, "Я исследую остатки жидкости." }, { 5.46, "Хотя впереди много работы, зло, совершённое Злоязыким в Мародоне, хотя бы отчасти исправлено." }, { 13.86, "Прими это в знак моей благодарности." } } } } },
    [7041] = { d = 30.8, v = "nightelf-female#52", n = { x = 363 }, c = { x = { { 0.00, "В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет всё кругом." }, { 5.47, "Из-за него там больше не растут цветы." }, { 8.24, "Возьми этот фиал, и наполни его из осквернённого оранжевого пруда в глубине пещер." }, { 14.02, "Внутри фиала есть особое покрытие, которое превратит яд в лекарство." }, { 18.80, "Отыщи в оранжевых пещерах гнусь-лозу и полей её целебной жидкостью." }, { 23.52, "Растение очистится от порчи, но всё равно останется в воле Злоязыкого." }, { 28.43, "Он может обратить его против тебя." } } }, t = { d = 14.2, g = 1, v = "nightelf-female#52", n = { m = 154, f = 156 }, c = { m = { { 0.00, "Спасибо, что принёс мне фиал." }, { 2.14, "Я исследую остатки жидкости." }, { 4.28, "Хотя впереди много работы, зло, совершённое Злоязыким в Мародоне, хотя бы отчасти исправлено." }, { 11.17, "Прими это в знак моей благодарности." } }, f = { { 0.00, "Спасибо, что принесла мне фиал." }, { 2.39, "Я исследую остатки жидкости." }, { 4.57, "Хотя впереди много работы, зло, совершённое Злоязыким в Мародоне, хотя бы отчасти исправлено." }, { 11.59, "Прими это в знак моей благодарности." } } } } },
    [7042] = { d = 32.2, g = 1, v = "goblin-male#110", n = { m = 377, f = 381 }, c = { m = { { 0.00, "Слушай... не хочется портить праздничное настроение, но Пастбищам Дымного Леса нужна помощь как раз от искателя приключений вроде тебя." }, { 9.52, "Мы потеряли важную партию угощения, что запасаем на праздник, а теперь ещё пропал и агент Пастбищ Дымного Леса, которого мы отправили на поиски!" }, { 19.68, "Помоги, будь любезен!" }, { 21.21, "Говорят, покраденное в последний раз видели в Альтеракских горах, туда наш посланец и отправился." }, { 28.00, "Привези оттуда и его, и наши припасы в целости и сохранности!" } }, f = { { 0.00, "Слушай... не хочется портить праздничное настроение, но Пастбищам Дымного Леса нужна помощь как раз от искательницы приключений вроде тебя." }, { 9.70, "Мы потеряли важную партию угощения, что запасаем на праздник, а теперь ещё пропал и агент Пастбищ Дымного Леса, которого мы отправили на поиски!" }, { 19.78, "Помоги, будь любезна!" }, { 21.29, "Говорят, покраденное в последний раз видели в Альтеракских горах, туда наш посланец и отправился." }, { 28.04, "Привези оттуда и его, и наши припасы в целости и сохранности!" } } }, t = { d = 26.1, v = "goblin-male", n = { x = 237 }, c = { x = { { 0.00, "В-в-вы м-м-меня с-с-слыш-шит-т-е!" }, { 2.43, "П-по г-г-гроб ж-жиз-зни б-б-б-лагодарен!" }, { 6.32, "Я н-н-не с-с-нег-говик, я С-с-акс, я р-р-абот-т-аю на с-с-с-т-ттальгорнское от-т-деление П-п-астбищ Д-д-дымного л-леса..." }, { 15.03, "М-меня п-п-ослали на-найти п-пропавший груз, к-кок-гда на м-м-меня н-напала т-т-варь, каких я п-п-прежде и н-н-е в-видывал!" }, { 24.09, "Как же я з-з-з-ам-м-мёрз-з-з..." } } } } },
    [7043] = { d = 27.7, v = "goblin-male", n = { x = 300 }, c = { x = { { 0.00, "С-существо, которое зовут \"Оме-мерзительный Гри-инч\", похитило все наши лакомства!" }, { 5.97, "Т-только ос-стор-р-рожно!" }, { 7.81, "Это он с-сделал из меня с-снеговика!" }, { 10.50, "Ва-ва-вам понадобится помощь!" }, { 12.67, "Я в-видел, как он шляется тут в-в-вместе с другими йети." }, { 16.73, "Он нав-верняка где-то п-поблизости!" }, { 19.29, "Отыщите мой груз, отвезите его в Стальгорн, П-пастбищам Дымного леса, и п-п-передайте им, что м-меня надо разморозить!" } } }, t = { d = 23.0, v = "goblin-male#110", n = { x = 245 }, c = { x = { { 0.00, "Вы нашли груз!" }, { 1.08, "Вы спасли наш праздник!" }, { 2.84, "Бедный Сакс!" }, { 3.79, "Конечно же, мы немедленно отправим спасателей и придумаем, как его разморозить." }, { 9.67, "Надеюсь, он успеет прийти в себя к празднику..." }, { 13.25, "Хотя, конечно же, потом ему придётся отработать то время, которое он прогулял!" }, { 19.13, "Но в любом случае, если бы не вы, всё пошло бы прахом!" } } } } },
    [7044] = { d = 39.8, v = "named/13697", n = { x = 393 }, c = { x = { { 0.00, "Повелитель сатиров, лорд Злоязыкий, сеет ужас по всем ходам-переходам этой пещеры, отравляя разум и чувства всех несчастных, оказавшихся внутри." }, { 11.88, "Он живёт за лиловыми кристаллами." }, { 14.55, "Кроме того, Злоязыкий создал живой символ собственного падения, Ноксиона, который живёт за оранжевыми кристаллами." }, { 24.81, "Эти двое похитили скипетр моего брата." }, { 28.15, "Келебрас, мой брат... бессмысленно бродит по пещерам, снедаемый порчей." }, { 33.94, "Помоги ему!" }, { 34.98, "Найди обломки скипетра и попробуй поговорить с моим братом." } } }, t = { d = 7.9, v = "creature/keeper", n = { x = 76 }, c = { x = { { 0.00, "Теперь, когда мой жезл собран воедино, надеюсь, вскоре мы сумеем избавить Мародон от скверны." } } } } },
    [7045] = { d = 27.0, v = "goblin-male#110", n = { x = 284 }, c = { x = { { 0.00, "Спасибо тебе от Пастбищ Дымного Леса за возвращение краденых сладостей!" }, { 5.52, "И хотим мы тебе за это предложить особый подарок..." }, { 9.52, "От самого Дедушки Зимы!" }, { 11.39, "Поговори с Дедушкой Зимой, и он даст тебе подарок праздника Зимнего Покрова от нашего имени!" }, { 18.49, "От нашего села да к вашему столу, вкусная и здоровая пища от Пастбищ Дымного Леса... благодаря тебе, конечно же!" } } }, t = { d = 14.1, v = "dwarf-male", n = { x = 139 }, c = { x = { { 0.00, "Хо-хо-хо!" }, { 0.82, "Добро пожаловать!" }, { 2.30, "Гоблины мне сказали, что тебе нынче полагается специальный приз, и я рад отдать его." }, { 9.19, "Вот он – и весёлого тебе праздника Зимнего Покрова каждый год!" } } } } },
    [7046] = { d = 35.9, v = "creature/keeper", n = { x = 354 }, c = { x = { { 0.00, "Некогда скипетр был моей опорой и надёжей." }, { 3.56, "Его сила позволяла мне стремительно перемещаться по этим пещерам." }, { 9.09, "Я надеялся умиротворить дух моего дяди..." }, { 12.58, "Теперь я передам это бремя тебе." }, { 15.46, "Для того же, чтобы слить воедино обе половины скипетра, мне понадобится твоя помощь." }, { 22.59, "Иди за мной и пока я буду призывать энергию, чтобы воссоединить жезл с бриллиантом, выполняй мои указания." }, { 31.53, "Воссоздадим же совместными усилиями скипетр Келебраса!" } } }, t = { d = 25.0, v = "creature/keeper", n = { x = 240 }, c = { x = { { 0.00, "Прошу тебя, возьми этот скипетр и знай, что заключённая в нём сила должна служить лишь добру." }, { 8.06, "Не останавливайся на достигнутом, иди дальше, вглубь пещер." }, { 13.15, "Надеюсь, ты сумеешь отыскать останки моего дяди." }, { 17.45, "Тебя подстерегает множество опасностей." }, { 20.89, "Если понадобится, можешь смело обращаться ко мне." } } } } },
    [7061] = { d = 30.6, v = "tauren-male#68", n = { x = 313 }, c = { x = { { 0.00, "Вот, если тебе интересно узнать о празднике Зимнего Покрова побольше, прочти эту книгу." }, { 7.21, "Я полагаю, что наше толкование легенды достаточно верное, и всё же, как учёный, предпочитаю, чтобы вся информация была проверена." }, { 17.47, "Когда дочитаешь, отнеси эту книгу в Громовой Утёс Кэрну Кровавому Копыту." }, { 23.51, "Ему наверняка приятно будет узнать, что кто-то ещё интересуется преданиями нашего народа." } } }, t = { d = 29.4, g = 1, v = "named/3057", n = { x = 284 }, c = { m = { { 0.00, "Предания и легенды, связанные с Зимним Покровом, с годами потускнели и забылись." }, { 9.29, "Да, я знаю, что гоблины помогают возрождать этот праздник в своих собственных целях, но всё же радует, что народ хоть как-то помнит о нём." }, { 19.03, "Твоё желание узнать ещё больше о нём и о нашем прошлом весьма похвально, герой." }, { 24.67, "Подобное стремление к мудрости можно лишь приветствовать." } }, f = { { 0.00, "Предания и легенды, связанные с Зимним Покровом, с годами потускнели и забылись." }, { 9.51, "Да, я знаю, что гоблины помогают возрождать этот праздник в своих собственных целях, но всё же радует, что народ хоть как-то помнит о нём." }, { 19.48, "Твоё желание узнать ещё больше о нём и о нашем прошлом весьма похвально, героиня." }, { 25.38, "Подобное стремление к мудрости можно лишь приветствовать." } } } } },
    [7062] = { d = 32.6, v = "dwarf-male", n = { x = 358 }, c = { x = { { 0.00, "Подарки, гости, угощение... чушь собачья!" }, { 3.09, "Эти гоблины искажают самую суть праздника Зимнего Покрова." }, { 7.52, "Это время возрождения – земля спит под покровом снега, которым её укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!" }, { 18.40, "Ежели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте историка Карника из лиги Исследователей." }, { 27.33, "Уверен, он будет очень удивлён, что кому-то история интереснее подарков." } } }, t = { d = 31.7, v = "dwarf-male", n = { x = 360 }, c = { x = { { 0.00, "Говорите, праздник Зимнего Покрова?" }, { 2.60, "Увы, в прежние времена для нас, дворфов, он имел гораздо более весомое значение." }, { 8.44, "А теперь, похоже, другие используют легенду о Дедушке Зиме, чтобы продать побольше сладостей и подарков." }, { 16.04, "Неудивительно, что Голли так огорчает эта перемена." }, { 19.74, "Он и остальные дворфы держатся за наше прошлое, как за боевое знамя." }, { 24.68, "Я лично считаю, что небольшой праздник никогда не помешает, но о его происхождении забывать нельзя." } } } } },
    [7063] = { d = 27.8, v = "dwarf-male", n = { x = 322 }, c = { x = { { 0.00, "Если вам интересно побольше узнать о празднике Зимнего Покрова, прочтите эту книгу." }, { 6.02, "Хотя я и думаю, что наше толкование легенды вполне соответствующее, я всё же учёный и буду рад, если мне удастся свести всю информацию воедино." }, { 16.06, "Когда вы отправитесь к королю Магни Бронзобороду, отнесите ему эту книгу." }, { 21.38, "Я точно знаю: ему приятно будет услышать, что кто-то ещё интересуется старинными легендами." } } }, t = { d = 27.3, g = 1, v = "dwarf-male#177", n = { m = 268, f = 268 }, c = { m = { { 0.00, "Легенды и предания о Зимнем Покрове уже много лет подёрнуты дымкой забвения." }, { 6.21, "Я понимаю, что гоблины возродили праздник ради собственных целей, но хорошо, что жители хотя бы так помнят о нём." }, { 15.34, "Ваше желание докопаться до истины и узнать о нашем прошлом – замечательное качество, юный герой." }, { 23.22, "Меня радует ваша природная любознательность." } }, f = { { 0.00, "Легенды и предания о Зимнем Покрове уже много лет подёрнуты дымкой забвения." }, { 6.30, "Я понимаю, что гоблины возродили праздник ради собственных целей, но хорошо, что жители хотя бы так помнят о нём." }, { 15.57, "Ваше желание докопаться до истины и узнать о нашем прошлом – замечательное качество, юная героиня." }, { 23.73, "Меня радует ваша природная любознательность." } } } } },
    [7064] = { d = 35.1, v = "creature/dryad", n = { x = 324 }, c = { x = { { 0.00, "В глубинах Мародона живёт злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с Древними Богами." }, { 11.41, "Когда-то, давным-давно, её отыскал Зейтар, первый сын Кенария." }, { 17.04, "Их... потомство зовётся кентаврами." }, { 20.09, "Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас." }, { 27.16, "Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь." } } }, t = { d = 22.1, v = "creature/dryad", n = { x = 214 }, c = { x = { { 0.00, "Отличные новости!" }, { 1.52, "Спасибо!" }, { 2.28, "Я поговорю с Марандисом и спрошу его совета, как быть с останками Зейтара." }, { 8.50, "Ну, по крайней мере, самая сложная часть задания выполнена." }, { 13.51, "Мне было предписано предложить эти предметы в награду тому, кто сумеет помочь нам." }, { 20.49, "Выбери любой из них." } } } } },
    [7065] = { d = 37.4, v = "creature/keeper", n = { x = 324 }, c = { x = { { 0.00, "В глубинах Мародона живёт злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с Древними Богами." }, { 12.14, "Когда-то, давным-давно, её отыскал Зейтар, первый сын Кенария." }, { 18.12, "Их... потомство зовётся кентаврами." }, { 21.37, "Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас." }, { 28.89, "Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь." } } }, t = { d = 26.0, g = 1, v = "creature/keeper", n = { m = 267, f = 269 }, c = { m = { { 0.00, "Отличные новости!" }, { 1.45, "Спасибо!" }, { 2.18, "Хотя мне жаль, что ты не смог принести останки Зейтара, кто я, чтобы оспаривать волю первенца Кенария?" }, { 10.32, "Может быть, кентавры сумеют преодолеть собственную кровожадность – будем надеяться на лучшее." }, { 17.80, "Мне было предписано предложить эти предметы в награду тому, кто сумеет помочь нам." }, { 24.48, "Выбери любой из них." } }, f = { { 0.00, "Отличные новости!" }, { 1.44, "Спасибо!" }, { 2.16, "Хотя мне жаль, что ты не смогла принести останки Зейтара, кто я, чтобы оспаривать волю первенца Кенария?" }, { 10.45, "Может быть, кентавры сумеют преодолеть собственную кровожадность – будем надеяться на лучшее." }, { 17.87, "Мне было предписано предложить эти предметы в награду тому, кто сумеет помочь нам." }, { 24.50, "Выбери любой из них." } } } } },
    [7066] = { d = 38.2, v = "creature/keeper", n = { x = 334 }, c = { x = { { 0.00, "Несчастные кентавры – мои дети – пропадут без отца." }, { 4.58, "Оглянись – это место исполнено надежды и того, чему учил мой отец, Кенарий." }, { 11.38, "И всё это произошло от меня!" }, { 13.91, "Я не могу лишить их своей поддержки... хоть они и обратились против меня." }, { 20.38, "У меня есть к тебе просьба – я хочу успокоить своего брата." }, { 25.68, "Возьми это..." }, { 26.94, "Первое семя жизни, родившейся из моих останков." }, { 31.21, "Скажи ему, что я не погиб, а мой дух ныне пребывает здесь." }, { 36.26, "Уверен, он меня поймёт." } } }, t = { d = 38.9, g = 1, v = "creature/remulos", n = { m = 375, f = 376 }, c = { m = { { 0.00, "Итак, мой брат обрёл покой?" }, { 2.24, "Я счастлив, что дожил до этого дня." }, { 5.15, "Видя его гордость и гнев, я опасался, что он навеки потерян для нас..." }, { 10.90, "Но этот символ принесённой им жертвы доказывает, что он не погиб, но возродился для жизни вечной." }, { 18.81, "Он занял своё место в природе, как и пристало ему." }, { 22.99, "Благодарю тебя." }, { 24.33, "Принеся мне дар от моего брата, ты посеял во мне надежду, которая, казалось, давно умерла." }, { 31.79, "Я чувствую, что это семя ещё принесёт свой благой плод в этой истерзанной войнами земле." } }, f = { { 0.00, "Итак, мой брат обрёл покой?" }, { 2.21, "Я счастлив, что дожил до этого дня." }, { 5.09, "Видя его гордость и гнев, я опасался, что он навеки потерян для нас..." }, { 10.76, "Но этот символ принесённой им жертвы доказывает, что он не погиб, но возродился для жизни вечной." }, { 18.58, "Он занял своё место в природе, как и пристало ему." }, { 22.71, "Благодарю тебя." }, { 24.04, "Принеся мне дар от моего брата, ты посеяла во мне надежду, которая, казалось, давно умерла." }, { 31.48, "Я чувствую, что это семя ещё принесёт свой благой плод в этой истерзанной войнами земле." } } } } },
    [7067] = { d = 35.5, g = 1, v = "named/13717", n = { m = 344, f = 344 }, c = { m = { { 0.00, "Хотя меня изгнали из племени как еретика, меня поддерживает вера." }, { 5.51, "Только ей я и живу." }, { 7.14, "Впрочем, мне не исполнить предначертанное без посторонней помощи..." }, { 12.57, "Причём помощи чужака, а не кентавра." }, { 15.55, "Кто-то должен войти в священные залы Мародона – гробницы, которую защищает мой народ, допуская внутрь лишь избранных." }, { 25.22, "Если ты согласен помочь мне, стоит только кивнуть." }, { 29.47, "Я отдам тебе свиток с инструкциями." }, { 32.44, "Прочти его и обдумай мои слова." } }, f = { { 0.00, "Хотя меня изгнали из племени как еретика, меня поддерживает вера." }, { 5.58, "Только ей я и живу." }, { 7.24, "Впрочем, мне не исполнить предначертанное без посторонней помощи..." }, { 12.75, "Причём помощи чужака, а не кентавра." }, { 15.76, "Кто-то должен войти в священные залы Мародона – гробницы, которую защищает мой народ, допуская внутрь лишь избранных." }, { 25.57, "Если ты согласна помочь мне, стоит только кивнуть." }, { 29.87, "Я отдам тебе свиток с инструкциями." }, { 32.88, "Прочти его и обдумай мои слова." } } }, t = { d = 14.0, v = "named/13717", n = { x = 131 }, c = { x = { { 0.00, "Вот он, вот амулет!" }, { 1.66, "Теперь мне предстоит долгое дело объединения племён." }, { 6.25, "Спасибо." }, { 7.04, "Вот, возьми это за услуги." }, { 9.41, "Надеюсь, мы ещё встретимся в совсем другой обстановке." } } } } },
    [7068] = { d = 27.5, v = "troll-male", n = { x = 283 }, c = { x = { { 0.00, "Сильна магия в святом месте для кентавров, священном Мародоне." }, { 4.98, "Племена кентавров Пустошей готовы биться за эти места до последней капли крови, но куда им!" }, { 12.31, "Мы своё возьмём!" }, { 13.52, "Ступай в ихний Мародон и найди там каменных тварей из осколков сумрака." }, { 19.21, "Ты дашь Утель'наю лиловые кристаллы, а уж он тебя не обидит!" }, { 23.90, "Места там опасные, так что бери с собой друзей." } } }, t = { d = 9.4, v = "troll-male", n = { x = 84 }, c = { x = { { 0.00, "Ага, как раз то, что нужно для колдовства." }, { 3.59, "Возьми одну из этих побрякушек и иди отсюда..." }, { 7.73, "У меня полно работы." } } } } },
    [7070] = { d = 32.7, v = "human-male", n = { x = 403 }, c = { x = { { 0.00, "Я недавно начал испытания различных кристаллов и их магических свойств." }, { 4.77, "Леди Праудмур позволила мне обратиться к путешественникам в Пустошах с просьбой отыскать там некое место, называющееся Мародон." }, { 13.76, "В руинах храма поселились огромные каменные элементали, состоящие из лиловых кристаллов, которые я нарёк осколками сумрака." }, { 22.09, "Если ты решишь направиться в ту сторону и захватишь по пути несколько кристаллов, я буду очень признателен." }, { 29.37, "Более того, я могу сделать тебе из них украшение." } } }, t = { d = 16.2, v = "human-male", n = { x = 178 }, c = { x = { { 0.00, "Отличные кристаллы." }, { 1.48, "На самом деле некоторые искатели приключений уже принесли мне образцы этих кристаллов, и из них я сделал эти украшения..." }, { 10.54, "Можешь выбрать любое из них." }, { 12.69, "И ещё раз спасибо." }, { 14.04, "Чем больше образцов, тем лучше." } } } } },
    [7081] = { d = 30.3, g = 1, v = "dwarf-male", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Кладбища в Альтеракской долине представляют собой очень большую ценность." }, { 5.30, "И Орда, и Альянс свирепо дерутся за право обладать этими сакральными местами." }, { 10.93, "Готов ли ты вступить в эту схватку?" }, { 13.52, "Я хочу, чтобы ты захватил кладбище неприятеля." }, { 16.88, "Найди кладбище с вымпелом Орды и вытащи из земли этот вымпел!" }, { 21.41, "Вот и всё, задание выполнено." }, { 23.48, "Если не сложно, можешь покараулить захваченное кладбище несколько минут, до прибытия наших войск." } }, f = { { 0.00, "Кладбища в Альтеракской долине представляют собой очень большую ценность." }, { 5.25, "И Орда, и Альянс свирепо дерутся за право обладать этими сакральными местами." }, { 10.83, "Готова ли ты вступить в эту схватку?" }, { 13.45, "Я хочу, чтобы ты захватила кладбище неприятеля." }, { 16.85, "Найди кладбище с вымпелом Орды и вытащи из земли этот вымпел!" }, { 21.33, "Вот и всё, задание выполнено." }, { 23.38, "Если не сложно, можешь покараулить захваченное кладбище несколько минут, до прибытия наших войск." } } }, t = { d = 19.1, v = "dwarf-male", n = { x = 216 }, c = { x = { { 0.00, "Отлично!" }, { 0.66, "Кладбища нам необходимы, чтобы удерживать контроль над Альтеракской долиной." }, { 6.22, "Захватывая кладбища, ты помогаешь Альянсу отстоять свою независимость." }, { 11.39, "А теперь ступай." }, { 12.65, "Возвращайся в бой, и если увидишь ещё одно кладбище Орды... то ты знаешь, что надо делать!" } } } } },
    [7082] = { d = 29.8, v = "orc-female#58", n = { x = 330 }, c = { x = { { 0.00, "Линия фронта в Альтеракской долине постоянно изменяется." }, { 4.27, "Мы отступаем и снова отвоёвываем территории в смертельной схватке с врагом." }, { 9.83, "Особо яростные сражения идут за кладбища." }, { 13.02, "Я приказываю тебе атаковать кладбище Альянса!" }, { 16.48, "Найди кладбище с вымпелом Альянса в центре и вырви вымпел из земли!" }, { 21.63, "На этом задание будет выполнено." }, { 24.14, "Но тебе нужно будет подождать некоторое время, пока не придут наши войска." } } }, t = { d = 9.8, v = "orc-female#58", n = { x = 101 }, c = { x = { { 0.00, "Отлично!" }, { 0.72, "Если мы завладеем всеми кладбищами, духи врагов будут бесцельно слоняться по этим землям, не в силах помешать нам." } } } } },
    [7101] = { d = 31.0, v = "orc-female#58", n = { x = 321 }, c = { x = { { 0.00, "Башни и бункеры – основные защитные сооружения, так что все они должны быть нашими!" }, { 6.49, "Твоё следующее задание – захват вражеского бункера." }, { 10.51, "Зайди в бункер Альянса – над ним развевается их флаг." }, { 14.60, "Внутри ты увидишь вымпел." }, { 16.65, "Сними его, и на его месте появится белый вымпел Орды." }, { 21.02, "Дело сделано!" }, { 22.15, "Больше ничего не нужно, но если ты немного подождёшь и не дашь Альянсу отбить бункер обратно, то он самоуничтожится!" } } }, t = { d = 13.4, v = "orc-female#58", n = { x = 140 }, c = { x = { { 0.00, "Я слышала, задание успешно выполнено!" }, { 3.02, "Это хорошо..." }, { 4.17, "Теперь наши войска смогут безнаказанно продвинуться вперёд и показать Альянсу, что ему не место в Альтеракской долине!" } } } } },
    [7102] = { d = 34.0, v = "dwarf-male", n = { x = 371 }, c = { x = { { 0.00, "Башни и бункеры – основные защитные сооружения, так что у нас их должно быть как можно больше!" }, { 6.74, "Я приказываю тебе атаковать вражескую башню или бункер в Альтеракской долине." }, { 12.44, "Для этого зайди в башню, над которой развевается флаг Орды." }, { 16.76, "Внутри ты увидишь вымпел." }, { 18.66, "Сними его, и на его месте появится белый вымпел Альянса." }, { 22.92, "Дело сделано!" }, { 23.97, "На этом твоё задание будет выполнено, но если ты продержишься там достаточно долго и Орда не отобьёт башню, она будет разрушена!" } } }, t = { d = 9.7, g = 1, v = "dwarf-male", n = { m = 103, f = 104 }, c = { m = { { 0.00, "Я получил отчёт о том, что ты обезвредил вражеский вымпел." }, { 4.44, "Отлично!" }, { 5.15, "Теперь мы перенесём линию фронта на вражескую территорию." } }, f = { { 0.00, "Я получил отчёт о том, что ты обезвредила вражеский вымпел." }, { 4.59, "Отлично!" }, { 5.31, "Теперь мы перенесём линию фронта на вражескую территорию." } } } } },
    [7121] = { d = 14.6, v = "dwarf-male", n = { x = 182 }, c = { x = { { 0.00, "Интендант велел отправлять новых рекрутов к нему." }, { 3.34, "Нам нужны припасы, которые хранятся в тайниках на рудниках Альтерака, так что, скорее всего, он отправит тебя за ними." }, { 11.14, "Ступай по этой дороге на запад, там найдёшь интенданта." } } }, t = { d = 10.7, v = "dwarf-male#100", n = { x = 127 }, c = { x = { { 0.00, "Приятно видеть новых солдат, но если повезёт, ты скоро отправишься на задание и перестанешь быть новичком." }, { 7.30, "Подойди ко мне через минутку, я дам тебе задание..." } } } } },
    [7122] = { d = 31.2, v = "dwarf-male", n = { x = 351 }, c = { x = { { 0.00, "Рудники в Альтеракской долине – нечто большее, чем обычные сырьевые ресурсы." }, { 5.49, "И Грозовая Вершина, и клан Северного Волка хранят на рудниках свои припасы." }, { 10.92, "Одни – на Железном руднике, другие – на руднике Ледяного Зуба." }, { 15.45, "Неплохо было бы захватить чужие припасы!" }, { 18.42, "Захвати рудник и возвращайся ко мне." }, { 21.00, "Найди рудник, который никому не принадлежит, и убей того, кто там главный." }, { 26.37, "После этого рудник перейдёт к нам, и мы вышлем войска для его охраны." } } }, t = { d = 10.2, v = "dwarf-male", n = { x = 112 }, c = { x = { { 0.00, "У тебя получилось!" }, { 1.44, "Прекрасная работа!" }, { 2.87, "Теперь, когда рудник охраняют наши войска, добывать сырьё и хранить припасы станет гораздо легче." } } } } },
    [7123] = { d = 16.2, v = "orc-male#60", n = { x = 190 }, c = { x = { { 0.00, "Интендант клана Северного Волка набирает рекрутов для задания на рудниках Альтеракской долины." }, { 6.79, "Поговори с ним, он расскажет тебе всё подробно." }, { 10.16, "Ступай в бункер по западной дороге, зайди в западный вход, там ты и найдёшь интенданта." } } }, t = { d = 11.1, g = 1, v = "orc-male", n = { m = 102, f = 103 }, c = { m = { { 0.00, "Привет тебе!" }, { 1.12, "Приятно видеть героя, который решил служить Орде." }, { 5.38, "Обратись ко мне через минутку, я выдам тебе жизненно важное задание..." } }, f = { { 0.00, "Привет тебе!" }, { 1.09, "Приятно видеть героиню, которая решила служить Орде." }, { 5.45, "Обратись ко мне через минутку, я выдам тебе жизненно важное задание..." } } } } },
    [7124] = { d = 30.0, v = "orc-female#58", n = { x = 315 }, c = { x = { { 0.00, "Битва, разгоревшаяся на землях Альтеракской долины, идёт и за рудники – Железный и Ледяного Зуба." }, { 7.42, "Они богаты сырьём, и к тому же их можно использовать для хранения припасов." }, { 13.17, "Помоги нам!" }, { 14.07, "Захвати один из этих рудников, во имя Орды!" }, { 17.54, "Отправляйся на рудник, который принадлежит нашим врагам, и убей того, кто там главный." }, { 24.19, "Как только ты захватишь рудник, мы вышлем войска, чтобы взять его под охрану." } } }, npc = { [12097] = { d = 30.9, v = "orc-male", n = { x = 315 }, c = { x = { { 0.00, "Битва, разгоревшаяся на землях Альтеракской долины, идёт и за рудники – Железный и Ледяного Зуба." }, { 7.61, "Они богаты сырьём, и к тому же их можно использовать для хранения припасов." }, { 13.52, "Помоги нам!" }, { 14.44, "Захвати один из этих рудников, во имя Орды!" }, { 18.00, "Отправляйся на рудник, который принадлежит нашим врагам, и убей того, кто там главный." }, { 24.83, "Как только ты захватишь рудник, мы вышлем войска, чтобы взять его под охрану." } } } } }, t = { d = 13.0, g = 1, v = "orc-female#58", n = { m = 126, f = 128 }, c = { m = { { 0.00, "Ты захватил рудник!" }, { 1.68, "Мы вышлем туда охрану и сможем добывать сырьё и хранить припасы." }, { 7.17, "Отлично." }, { 7.93, "Ты оказал Орде неоценимую помощь в ведении боевых действий!" } }, f = { { 0.00, "Ты захватила рудник!" }, { 1.75, "Мы вышлем туда охрану и сможем добывать сырьё и хранить припасы." }, { 7.25, "Отлично." }, { 8.01, "Ты оказала Орде неоценимую помощь в ведении боевых действий!" } } } } },
    [7141] = { d = 27.8, v = "dwarf-female#33", n = { x = 323 }, c = { x = { { 0.00, "Лига Исследователей уверена, что в Альтеракской долине есть артефакты, но клан Северного Волка не позволяет нам проводить здесь исследования." }, { 9.98, "Не дадим Орде задушить наши благородные научные начинания!" }, { 14.29, "Уничтожь генерала Северного Волка, Дрек'Тара." }, { 17.61, "Без него орки ничего сделать не смогут." }, { 20.55, "Дрек'Тара можно найти в крепости Северного Волка, на юге Альтеракской долины." }, { 26.22, "Убей его и возвращайся." } } }, t = { d = 7.8, v = "dwarf-female#33", n = { x = 89 }, c = { x = { { 0.00, "Прекрасная работа!" }, { 1.40, "Орда не скоро оправится от смерти генерала, так что мы можем начинать наши исследования!" } } } } },
    [7142] = { d = 25.4, v = "orc-male", n = { x = 274 }, c = { x = { { 0.00, "Дворфы Грозовой Вершины вместе со своими союзниками вторглись в Альтеракскую долину, и мы должны выкинуть их отсюда!" }, { 8.92, "Если мы хотим выиграть битву за Альтерак наверняка, то нам нужно уничтожить их генерала, Вандара Грозовую Вершину!" }, { 17.70, "Его можно найти в Дун Болдаре, на севере Альтеракской долины." }, { 22.47, "Убей его, и возвращайся обратно ко мне." } } }, t = { d = 11.6, v = "orc-male", n = { x = 102 }, c = { x = { { 0.00, "Отлично!" }, { 0.81, "Зря Грозовая Вершина вторглась на эти земли." }, { 4.83, "Себе дороже вышло!" }, { 6.61, "Ха!" }, { 6.93, "Всё, чего они добились – это смерти своего генерала!" } } } } },
    [7161] = { d = 38.0, g = 1, v = "orc-male#60", n = { x = 375 }, c = { m = { { 0.00, "Приветствую, герой." }, { 1.63, "Много времени прошло с тех пор, когда мы в последний раз внимали зову битвы." }, { 7.94, "Трудно пробудить давно забытые чувства, но если они проснулись, обязательно прольётся кровь." }, { 15.51, "Ярость боя зовёт нас..." }, { 17.44, "В долине Альтерака все новички должны пройти боевое крещение." }, { 22.57, "Глубоко в пещерах гноллов из стаи Дикой Лапы хранится вымпел клана Северного Волка." }, { 29.62, "Отправляйся туда и добудь его." }, { 32.22, "Возвращайся ко мне вместе с вымпелом, и получишь знак отличия новобранца." } }, f = { { 0.00, "Приветствую, героиня." }, { 1.77, "Много времени прошло с тех пор, когда мы в последний раз внимали зову битвы." }, { 8.04, "Трудно пробудить давно забытые чувства, но если они проснулись, обязательно прольётся кровь." }, { 15.57, "Ярость боя зовёт нас..." }, { 17.49, "В долине Альтерака все новички должны пройти боевое крещение." }, { 22.58, "Глубоко в пещерах гноллов из стаи Дикой Лапы хранится вымпел клана Северного Волка." }, { 29.59, "Отправляйся туда и добудь его." }, { 32.17, "Возвращайся ко мне вместе с вымпелом, и получишь знак отличия новобранца." } } }, t = { d = 35.7, g = 1, v = "orc-male#60", n = { m = 354, f = 354 }, c = { m = { { 0.00, "Это жгучее чувство означает, что твоя душа пробудилась и услышала зов битвы." }, { 6.41, "Теперь ты – один из клана Северного Волка." }, { 9.98, "Поздравляю тебя." }, { 11.40, "Постоянно носи с собой этот знак." }, { 14.23, "По мере того как ты будешь продвигаться по службе в клане Северного Волка, я буду заменять его на другие, соответствующие более высокому званию." }, { 26.22, "Возможно, однажды придёт день, когда ты заслужишь полное уважение клана Северного Волка и получишь Око Командования." } }, f = { { 0.00, "Это жгучее чувство означает, что твоя душа пробудилась и услышала зов битвы." }, { 6.25, "Теперь ты – одна из клана Северного Волка." }, { 9.74, "П