    [7162] = { d = 33.7, g = 1, v = "dwarf-male", n = { m = 369, f = 370 }, c = { m = { { 0.00, "Ты прибыл вовремя, герой." }, { 1.89, "Эти дикари из клана Северного Волка ни в какую не желают сдаваться!" }, { 6.83, "Ничего, мы им покажем, на что способна Грозовая Вершина." }, { 10.87, "Они склонятся перед нашей мощью!" }, { 13.34, "Перед тем, как отправиться в бой, ты должен вступить в ряды Грозовой Вершины." }, { 19.57, "К юго-западу от Дун Болдара находится Пещера Ледяного Крыла." }, { 23.93, "В её недрах хранится вымпел Грозовой Вершины." }, { 27.25, "Отправляйся туда и добудь его." }, { 29.53, "Принеси вымпел мне, и получишь отличительный знак новобранца." } }, f = { { 0.00, "Ты прибыла вовремя, героиня." }, { 2.06, "Эти дикари из клана Северного Волка ни в какую не желают сдаваться!" }, { 6.95, "Ничего, мы им покажем, на что способна Грозовая Вершина." }, { 10.94, "Они склонятся перед нашей мощью!" }, { 13.43, "Перед тем, как отправиться в бой, ты должна вступить в ряды Грозовой Вершины." }, { 18.90, "К юго-западу от Дун Болдара находится Пещера Ледяного Крыла." }, { 23.21, "В её недрах хранится вымпел Грозовой Вершины." }, { 26.50, "Отправляйся туда и добудь его." }, { 28.75, "Принеси вымпел мне, и получишь отличительный знак новобранца." } } }, t = { d = 19.7, v = "dwarf-male", n = { x = 208 }, c = { x = { { 0.00, "Прими этот знак и носи его с честью." }, { 2.90, "Это символ твоего положения в Грозовой Вершине." }, { 6.63, "Когда ты приобретёшь уважение Грозовой Вершины, я выдам тебе другой знак." }, { 12.23, "Возможно, в один прекрасный день ты станешь легендарным воителем и получишь Око Командования." } } } } },
    [7163] = { t = { d = 12.2, g = 1, v = "orc-male#60", n = { x = 102 }, c = { m = { { 0.00, "Это знак особого расположения клана Северного Волка." }, { 4.38, "Носи его с собой всё время." }, { 6.76, "И вот что, герой..." }, { 8.32, "Придёт время умирать – умри с честью!" } }, f = { { 0.00, "Это знак особого расположения клана Северного Волка." }, { 4.69, "Носи его с собой всё время." }, { 7.23, "И вот что, героиня..." }, { 9.06, "Придёт время умирать – умри с честью!" } } } } },
    [7164] = { t = { d = 12.9, v = "orc-male#60", n = { x = 111 }, c = { x = { { 0.00, "*Воевода Лаггронд отдаёт салют.*" }, { 2.88, "Ступай!" }, { 3.66, "Продолжай сражаться за клан Северного Волка!" }, { 7.88, "Мы должны выиграть эту войну!" }, { 10.81, "За Дрек'Тара!" }, { 12.10, "За Вождя!" } } } } },
    [7165] = { t = { d = 11.6, v = "orc-male#60", n = { x = 112 }, c = { x = { { 0.00, "О твоих подвигах уже слагаются песни, солдат." }, { 5.28, "Грозовая Вершина содрогается в страхе, слыша твоё имя." }, { 10.56, "Так держать!" } } } } },
    [7166] = { t = { d = 9.8, v = "orc-male#60", n = { x = 96 }, c = { x = { { 0.00, "Скоро ты окинешь бдительным оком все поля сражений!" }, { 4.53, "Ты примешь командование долиной Альтерака и всеми её войсками!" } } } } },
    [7167] = { t = { d = 8.5, v = "orc-male#60", n = { x = 68 }, c = { x = { { 0.00, "Направь силу своего знака, и пусть враги услышат твой голос." }, { 6.33, "Мощь Орды несокрушима!" } } } } },
    [7168] = { t = { d = 6.8, v = "dwarf-male", n = { x = 73 }, c = { x = { { 0.00, "Пусть враги знают, что их поверг не простой солдат, а один из командиров Грозовой Вершины!" } } } } },
