    [7170] = { t = { d = 8.4, v = "dwarf-male", n = { x = 85 }, c = { x = { { 0.00, "Когда мы встретились впервые, я и подумать не мог, что из тебя выйдет герой." }, { 5.99, "Носи свой знак с честью, солдат!" } } } } },
    [7171] = { t = { d = 4.4, v = "dwarf-male", n = { x = 45 }, c = { x = { { 0.00, "Без сомнения, ты сумеешь заслужить и Око Командования!" } } } } },
    [7172] = { t = { d = 9.2, v = "dwarf-male", n = { x = 83 }, c = { x = { { 0.00, "Ты поведёшь нашу армию к победе, командир!" }, { 3.73, "Вот твоё войско." }, { 5.16, "Веди его в бой..." }, { 6.74, "Сокруши клан Северного Волка!" } } } } },
    [7181] = { d = 29.3, v = "orc-male#60", n = { x = 303 }, c = { x = { { 0.00, "Вторжение Грозовой Вершины – это не единственная угроза в этих землях, солдат." }, { 6.30, "Война в долине ведётся на два фронта." }, { 9.24, "Тролли-каннибалы из племени Секиры Зимы тоже представляют собой силу, с которой надо считаться." }, { 16.90, "Их предводитель – Коррак Кровопуск – жестокая и коварная тварь." }, { 21.84, "Убийство Коррака нанесло бы непоправимый удар племени Секиры Зимы." }, { 27.21, "Убей его и получи награду!" } } } },
    [7201] = { d = 49.1, v = "scourge-female#80", n = { x = 464 }, c = { x = { { 0.00, "У меня есть работа для тех, кто не боится заглянуть в глубины." }, { 5.48, "Клан Чёрного Железа научился создавать чрезвычайно мощных големов." }, { 11.37, "Исходя из отчётов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим големам невероятную разрушительную силу." }, { 25.25, "Подумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют..." }, { 35.65, "Можешь перевернуть город вверх дном, но я должна получить эту сущность." }, { 42.02, "Без неё можешь не возвращаться!" }, { 44.76, "Награда будет сопоставима с затраченными усилиями." } } }, t = { d = 13.8, v = "scourge-female#80", n = { x = 121 }, c = { x = { { 0.00, "Превосходно!" }, { 1.15, "Я немедля отправлю это с курьером в Подгород." }, { 5.35, "Что же до тебя, вот твоя плата, как я и обещала." }, { 9.72, "Сдачу можешь оставить себе, грязное животное!" } } } } },
    [7202] = { d = 28.2, v = "dwarf-male", n = { x = 312 }, c = { x = { { 0.00, "Племя Секиры Зимы, местные аборигены, имеют скверную привычку украшать свой стол блюдами из мяса наших солдат." }, { 8.14, "Ничего, мы им покажем, как с нами связываться!" }, { 11.49, "Нам удалось добыть книгу, в которой записаны имена не только их знати, но и самого вождя, которое они тщательно скрывают!" }, { 20.42, "Его зовут Коррак Кровопуск." }, { 22.53, "Смерть Коррака – это смерть всего племени Секиры Зимы!" }, { 26.53, "Убей его и возвращайся." } } } },
    [7221] = { d = 27.4, g = 1, v = "dwarf-male", n = { m = 328, f = 328 }, c = { m = { { 0.00, "А, с докладом, да?" }, { 1.22, "Отлично, Грозовая Вершина должна использовать всех, кто годится хоть на что-нибудь." }, { 6.78, "Поговори с геологом Камнетеркой в Дун Болдаре." }, { 9.89, "Она как раз набирает добровольцев для очень важного задания на вражеской территории." }, { 15.56, "Ты найдёшь её в гарнизоне Дун Болдара, внизу." }, { 18.56, "Смотри внимательно, когда будешь пробираться через Дун Болдар." }, { 22.83, "Для героя, который не чурается работы, здесь найдётся много дел." } }, f = { { 0.00, "А, с докладом, да?" }, { 1.23, "Отлично, Грозовая Вершина должна использовать всех, кто годится хоть на что-нибудь." }, { 6.84, "Поговори с геологом Камнетеркой в Дун Болдаре." }, { 9.99, "Она как раз набирает добровольцев для очень важного задания на вражеской территории." }, { 15.72, "Ты найдёшь её в гарнизоне Дун Болдара, внизу." }, { 18.75, "Смотри внимательно, когда будешь пробираться через Дун Болдар." }, { 23.06, "Для героини, которая не чурается работы, здесь найдётся много дел." } } } },
    [7222] = { d = 25.4, g = 1, v = "orc-male", n = { x = 264 }, c = { m = { { 0.00, "Герой?" }, { 0.56, "Отлично!" }, { 1.25, "Рады видеть тебя в Альтераке." }, { 3.62, "Дворфы и их союзники вторглись в нашу долину, так что Орда приветствует каждого, кто решил вступить в праведный бой!" }, { 12.53, "Поговори с Воггой Смертобоем." }, { 14.83, "Он как раз набирает агентов для важного задания в крепости Альянса в Альтеракской долине!" }, { 21.65, "Воггу можно найти в крепости Северного Волка." } }, f = { { 0.00, "Героиня?" }, { 0.70, "Отлично!" }, { 1.40, "Рады видеть тебя в Альтераке." }, { 3.79, "Дворфы и их союзники вторглись в нашу долину, так что Орда приветствует каждого, кто решил вступить в праведный бой!" }, { 12.76, "Поговори с Воггой Смертобоем." }, { 15.07, "Он как раз набирает агентов для важного задания в крепости Альянса в Альтеракской долине!" }, { 21.94, "Воггу можно найти в крепости Северного Волка." } } } },
    [7223] = { d = 13.0, v = "dwarf-male", n = { x = 150 }, c = { x = { { 0.00, "В Альтеракской долине часто гремят сражения, и поставок из Стальгорна для нужд наших войск недостаточно." }, { 7.48, "Если ты найдёшь на поле боя обломки брони, приноси их мне, они нам пригодятся." } } }, t = { d = 13.0, v = "dwarf-male", n = { x = 144 }, c = { x = { { 0.00, "Среди них попадаются весьма неплохие куски." }, { 3.23, "Я смогу сделать из них новую броню для наших войск." }, { 6.99, "Если у нас будет достаточно брони, то скоро новые войска смогут выйти на поле боя!" } } } } },
    [7224] = { d = 10.5, v = "orc-male", n = { x = 101 }, c = { x = { { 0.00, "Если найдёшь на поле боя обломки вражеских доспехов, неси их мне." }, { 5.71, "Из них выйдет отличная броня для наших собственных войск!" } } }, t = { d = 13.5, v = "orc-male", n = { x = 133 }, c = { x = { { 0.00, "Просто отлично." }, { 1.38, "Я залатаю повреждения так, что никто и не отличит обломки вражеской брони от наших доспехов!" }, { 9.17, "Спасибо." }, { 9.93, "Хочешь, отполирую твои собственные доспехи?" } } } } },
    [7241] = { d = 35.8, g = 1, v = "orc-female", n = { m = 386, f = 388 }, c = { m = { { 0.00, "Издалека доносится рокот барабанов войны, герой." }, { 3.75, "Клан твоего вождя подвергается атакам презренных дворфов клана Грозовой Вершины из Стальгорна." }, { 10.90, "Судя по твоему виду, можно решить, что ты закалён в битвах и готов постоять за дело клана Северного Волка." }, { 19.00, "А сейчас тебе предстоит сделать новый шаг к усовершенствованию твоего воинского мастерства." }, { 25.88, "К северу от мельницы Таррен, в Альтеракских горах, есть вход в Альтеракскую долину." }, { 32.08, "Там тебе нужно отыскать воеводу Лаггронда." } }, f = { { 0.00, "Издалека доносится рокот барабанов войны, героиня." }, { 3.91, "Клан твоего вождя подвергается атакам презренных дворфов клана Грозовой Вершины из Стальгорна." }, { 11.10, "Судя по твоему виду, можно решить, что ты закалена в битвах и готова постоять за дело клана Северного Волка." }, { 19.46, "А сейчас тебе предстоит сделать новый шаг к усовершенствованию твоего воинского мастерства." }, { 26.38, "К северу от мельницы Таррен, в Альтеракских горах, есть вход в Альтеракскую долину." }, { 32.62, "Там тебе нужно отыскать воеводу Лаггронда." } } }, t = { d = 6.2, v = "orc-male#60", n = { x = 59 }, c = { x = { { 0.00, "Чтобы стать солдатом Северного Волка, нужно сначала пройти испытания..." } } } } },
    [7261] = { d = 33.7, v = "dwarf-male", n = { x = 389 }, c = { x = { { 0.00, "Здесь, в Альтеракской долине, идут тяжёлые бои." }, { 3.39, "С одной стороны на нас наступают тролли-каннибалы из племени Секиры Зимы, с другой – дикари из клана Северного Волка." }, { 11.86, "Во имя короля Магни Бронзоборода, все они должны быть уничтожены!" }, { 16.62, "Владение этими землями – неотъемлемое суверенное право королевства Стальгорн!" }, { 22.16, "К сожалению, солдаты не растут на деревьях." }, { 25.29, "Доложись лейтенанту Хаггердину у входа в Альтеракскую долину и с честью приступай к несению службы в Грозовой Вершине!" } } }, t = { d = 1.2, v = "dwarf-male", n = { x = 8 }, c = { x = { { 0.00, "За работу!" } } } } },
    [7281] = { d = 36.4, v = "scourge-male", n = { x = 346 }, c = { x = { { 0.00, "Ужасно..." }, { 0.85, "В сражении я столкнулся со своим братом, командиром Грозовой Вершины." }, { 6.80, "Из всех четырёх командиров Грозовой Вершины он самый опасный." }, { 11.98, "Возможно, Королева банши сможет возродить его после смерти, и тогда я докажу ему ошибочность его поступков..." }, { 21.56, "Мой брат находится в глубине территории врага." }, { 25.51, "Убей его и возвращайся ко мне." }, { 28.13, "Я уверен, солдат, что у тебя хватит сил выполнить это задание." }, { 33.54, "Но лучше не отправляйся в одиночку." } } }, t = { d = 10.5, v = "scourge-male", n = { x = 112 }, c = { x = { { 0.00, "Твой героизм не останется незамеченным." }, { 3.03, "Если я хочу спасти брата, то нельзя терять ни минуты." }, { 7.32, "Я должен немедленно обратиться к Сильване!" } } } } },
    [7282] = { d = 20.5, v = "human-male#50", n = { x = 228 }, c = { x = { { 0.00, "Нужно избавить его от страданий, солдат!" }, { 2.95, "Воистину, он не ведает, что творит." }, { 5.45, "Ужасная Королева банши сделала его своей бездумной марионеткой." }, { 10.07, "Ступай вперёд, через Поле брани, в глубину территории Северного Волка." }, { 15.66, "Найди моего брата и уничтожь его." }, { 18.16, "Его мучениям должен прийти конец." } } }, t = { d = 2.6, g = 1, v = "human-male#50", n = { m = 25, f = 26 }, c = { m = { { 0.00, "Надеюсь, ты не забыл сжечь тело?" } }, f = { { 0.00, "Надеюсь, ты не забыла сжечь тело?" } } } } },
    [7301] = { d = 28.7, g = 1, v = "dwarf-male", n = { x = 318 }, c = { m = { { 0.00, "Мы взяли их в плен, герой." }, { 1.89, "Мы захватили командиров звена." }, { 4.10, "В небе разразилась яростная битва, но в итоге они всё же уступили!" }, { 8.92, "К сожалению, во время контратаки против крепости Северного Волка были сбиты наши лучшие пилоты." }, { 15.96, "Нужно выяснить, что с ними случилось." }, { 18.69, "Обыщи западную Смотровую башню и крепость Северного Волка." }, { 22.99, "Там они были замечены в последний раз." }, { 25.79, "Как можно тщательней осмотри эти районы." } }, f = { { 0.00, "Мы взяли их в плен, героиня." }, { 2.02, "Мы захватили командиров звена." }, { 4.23, "В небе разразилась яростная битва, но в итоге они всё же уступили!" }, { 9.04, "К сожалению, во время контратаки против крепости Северного Волка были сбиты наши лучшие пилоты." }, { 16.06, "Нужно выяснить, что с ними случилось." }, { 18.79, "Обыщи западную Смотровую башню и крепость Северного Волка." }, { 23.08, "Там они были замечены в последний раз." }, { 25.87, "Как можно тщательней осмотри эти районы." } } }, t = { d = 7.2, g = 1, v = "dwarf-male", n = { m = 71, f = 72 }, c = { m = { { 0.00, "Невероятно!" }, { 0.93, "Ты их освободил, да?" }, { 2.50, "Правда?" }, { 3.14, "Ну, по крайней мере, мы знаем теперь, где их держали." } }, f = { { 0.00, "Невероятно!" }, { 0.91, "Ты их освободила, да?" }, { 2.52, "Правда?" }, { 3.15, "Ну, по крайней мере, мы знаем теперь, где их держали." } } } } },
    [7302] = { d = 35.4, g = 1, v = "tauren-male", n = { m = 382, f = 382 }, c = { m = { { 0.00, "Наша воздушная поддержка в полном беспорядке." }, { 3.46, "Командиров звена сбили на вражеской территории." }, { 7.05, "Ты должен узнать, что с ними стало, чтобы мы могли попытаться их спасти!" }, { 12.54, "Гуса в последний раз видели над укрытием Ледяного Крыла." }, { 16.81, "Боевую виверну Джезтора заметили у лесопилки Грозовой Вершины." }, { 21.55, "Малверик... кто-то видел, как этот безголовый идиот разбился возле северного оплота Дун Болдара." }, { 28.87, "Это вся информация, что у меня есть." }, { 31.58, "За дело!" }, { 32.26, "Как следует прочеши указанные районы." } }, f = { { 0.00, "Наша воздушная поддержка в полном беспорядке." }, { 3.50, "Командиров звена сбили на вражеской территории." }, { 7.13, "Ты должна узнать, что с ними стало, чтобы мы могли попытаться их спасти!" }, { 12.68, "Гуса в последний раз видели над укрытием Ледяного Крыла." }, { 17.00, "Боевую виверну Джезтора заметили у лесопилки Грозовой Вершины." }, { 21.80, "Малверик... кто-то видел, как этот безголовый идиот разбился возле северного оплота Дун Болдара." }, { 29.20, "Это вся информация, что у меня есть." }, { 31.94, "За дело!" }, { 32.63, "Как следует прочеши указанные районы." } } }, t = { d = 6.2, v = "tauren-male", n = { x = 54 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.72, "Собранная тобой информация поистине бесценна." } } } } },
    [7321] = { d = 38.3, v = "scourge-male#144", n = { x = 367 }, c = { x = { { 0.00, "Кто сказал, что нежить не понимает в кулинарии?" }, { 3.81, "Взять, к примеру, мой заветный рецепт нежного черепашьего супа." }, { 8.93, "Да я знаю народ, что из мёртвых бы восстал, только бы скушать тарелочку!" }, { 14.72, "Хе-хе..." }, { 15.45, "Кстати, в последнее время мне ни тарелочки приготовить не удалось." }, { 20.79, "Обычно я сам ходил на озеро Лордамер ловить хрустогрызов – у, грязные тварюги – но не могу сейчас бросить работу." }, { 31.32, "Если ты добудешь мне немного черепашьего мяса и приправ, я научу тебя варить такой суп!" } } }, t = { d = 9.5, v = "scourge-male#144", n = { x = 84 }, c = { x = { { 0.00, "Мой нежный черепаший супчик согреет тебя холодной ночью..." }, { 5.37, "Если, конечно, ты ещё помнишь, что такое холод." } } } } },
    [7341] = { t = { d = 7.0, g = 1, v = "tauren-male", n = { x = 36 }, c = { m = { { 0.00, "Отлично!" }, { 1.08, "Я – таурен слова, герой." }, { 4.12, "Вот тебе твои стрелы." } }, f = { { 0.00, "Отлично!" }, { 1.10, "Я – таурен слова, героиня." }, { 4.40, "Вот тебе твои стрелы." } } } } },
    [7342] = { t = { d = 5.3, v = "dwarf-male", n = { x = 44 }, c = { x = { { 0.00, "Добрая сделка, если я что-то в этом понимаю!" }, { 4.02, "Стрелы – твои." } } } } },
    [7367] = { d = 31.2, g = 1, v = "dwarf-male", n = { x = 348 }, c = { m = { { 0.00, "Клан Северного Волка заминировал свои передовые позиции и базы, герой." }, { 4.94, "Ступая по вражеской земле, смотри под ноги." }, { 8.01, "Если хочешь нанести им ощутимый удар, нужно уничтожить того, кто отвечает за их минные поля, – я говорю об эксперте по взрывчатым веществам." }, { 17.76, "Пока он жив, минные поля существуют." }, { 20.33, "Но если он будет мёртв, поддерживать их станет некому." }, { 24.08, "Не исключаю, что эксперта можно найти в башне рядом с гарнизоном Стылой Крови." }, { 29.59, "Удачи тебе!" } }, f = { { 0.00, "Клан Северного Волка заминировал свои передовые позиции и базы, героиня." }, { 5.19, "Ступая по вражеской земле, смотри под ноги." }, { 8.33, "Если хочешь нанести им ощутимый удар, нужно уничтожить того, кто отвечает за их минные поля, – я говорю об эксперте по взрывчатым веществам." }, { 18.33, "Пока он жив, минные поля существуют." }, { 20.96, "Но если он будет мёртв, поддерживать их станет некому." }, { 24.81, "Не исключаю, что эксперта можно найти в башне рядом с гарнизоном Стылой Крови." }, { 30.45, "Удачи тебе!" } } } },
    [7368] = { d = 34.7, v = "orc-male#60", n = { x = 347 }, c = { x = { { 0.00, "Про противопехотные мины я знаю всё." }, { 2.90, "Именно я, а не кто-нибудь, отвечаю за мины на всей линии фронта." }, { 8.04, "Если ты хочешь обезвредить все минные поля Грозовой Вершины, сначала надо убить их эксперта по взрывчатым веществам." }, { 17.45, "Этот трусливый дворф скорее всего прячется в первой башне Поля брани." }, { 23.75, "Убей его, и минные поля будут обезврежены раз и навсегда." }, { 28.46, "Как убьёшь его, возвращайся ко мне." }, { 31.21, "Добрые дела не должны оставаться без награды." } } } },
    [7383] = { d = 36.0, v = "nightelf-male#54", n = { x = 390 }, c = { x = { { 0.00, "Но не всё было ладно с Тельдрассилом." }, { 2.88, "Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие." }, { 11.09, "Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила." }, { 17.73, "Однако, пока я об этом говорить не буду." }, { 20.88, "Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула." }, { 27.11, "Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев." }, { 33.06, "Набери воды из него и возвращайся ко мне." } } }, t = { d = 35.9, v = "nightelf-male#54", n = { x = 389 }, c = { x = { { 0.00, "Находиться в присутствии Древа-оракула... это всё равно что увидеть воплощённую мудрость." }, { 6.93, "Позволь мне продолжить..." }, { 8.91, "Тельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена." }, { 19.24, "Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности." }, { 25.89, "Алекстраза также отказала Оленьему Шлему, а без её благословения рост Тельдрассила стал непредсказуем, и в нём обнаружились изъяны..." } } } } },
    [7385] = { t = { d = 18.1, v = "tauren-female#71", n = { x = 173 }, c = { x = { { 0.00, "И вновь пролилась кровь наших врагов." }, { 3.13, "Я смешаю её с той, что уже собрана." }, { 6.10, "Когда крови будет столько, сколько нам нужно, Владыка Льда покажет этим собакам с Грозовой Вершины, что значит ярость клана Северного Волка!" } } } } },
    [7386] = { t = { d = 12.4, v = "nightelf-female#51", n = { x = 136 }, c = { x = { { 0.00, "Отлично." }, { 0.69, "Сила этих чар пригодится для усиления уже имеющейся магии." }, { 5.24, "Когда энергии наберётся достаточно, я смогу её сфокусировать и воззвать к Владыке Леса о помощи." } } } } },
    [7429] = { t = { d = 16.2, v = "goblin-male", n = { x = 155 }, c = { x = { { 0.00, "Вы для меня – номер один во всём мире!" }, { 3.18, "Все остальные – после вас!" }, { 5.32, "Ох, большое вам спасибо, что освободили меня!" }, { 9.01, "Я знал, я знал, что меня ждёт более достойная участь, чем пойти на обед какому-нибудь огру!" } } } } },
    [7441] = { d = 34.1, g = 1, v = "nightelf-male#54", n = { m = 367, f = 367 }, c = { m = { { 0.00, "Представь себе, чужестранец: стоило мне зазеваться всего на секунду!.. я был очень занят: спасался от принца-отступника... – и меня тут же обворовали!" }, { 10.94, "Гнуснейший демон, бес Пузиллин, стащил мою книгу заклинаний, и ключ от некогда прекрасных чертогов Эльдре'Таласа!" }, { 19.23, "Ключ мне теперь ни к чему: я обменял своё бессмертие на свободу, – но книга мне нужна позарез!" }, { 26.06, "Отыщи мне этого беса Пузиллина, и добудь у него книгу!" }, { 30.17, "Ищи его в Квартале Криводревов Забытого Города." } }, f = { { 0.00, "Представь себе, чужестранка: стоило мне зазеваться всего на секунду!.. я был очень занят: спасался от принца-отступника... – и меня тут же обворовали!" }, { 11.10, "Гнуснейший демон, бес Пузиллин, стащил мою книгу заклинаний, и ключ от некогда прекрасных чертогов Эльдре'Таласа!" }, { 19.50, "Ключ мне теперь ни к чему: я обменял своё бессмертие на свободу, – но книга мне нужна позарез!" }, { 26.43, "Отыщи мне этого беса Пузиллина, и добудь у него книгу!" }, { 30.60, "Ищи его в Квартале Криводревов Забытого Города." } } }, t = { d = 13.8, v = "nightelf-male#54", n = { x = 129 }, c = { x = { { 0.00, "Тебе удалось её найти!" }, { 1.98, "Будь проклят этот несчастный бесёнок..." }, { 5.25, "Увы, имущества у меня, мягко говоря, немного." }, { 9.20, "Придётся тебе выбирать из того, что я могу предложить..." } } } } },
    [7461] = { d = 27.8, g = 1, v = "nightelf-female#51", n = { m = 299, f = 300 }, c = { m = { { 0.00, "Ну что, довольно ли ты слышал?" }, { 2.19, "Надеюсь, ты не устрашишься вступить в бой?" }, { 5.23, "Этому безумию необходимо положить конец!" }, { 8.28, "Время бессмертных давным-давно миновало." }, { 11.32, "Уничтожь стражей, охраняющих столпы, и ликвидируй силовое поле." }, { 16.02, "А потом убей Бессмер'тера." }, { 18.01, "Это лишит принца большей части его силы, и тогда ты сможешь убить и его тоже." }, { 23.97, "Помоги духам этого города упокоиться в мире!" } }, f = { { 0.00, "Ну что, довольно ли ты слышала?" }, { 2.29, "Надеюсь, ты не устрашишься вступить в бой?" }, { 5.39, "Этому безумию необходимо положить конец!" }, { 8.49, "Время бессмертных давным-давно миновало." }, { 11.59, "Уничтожь стражей, охраняющих столпы, и ликвидируй силовое поле." }, { 16.38, "А потом убей Бессмер'тера." }, { 18.40, "Это лишит принца большей части его силы, и тогда ты сможешь убить и его тоже." }, { 24.47, "Помоги духам этого города упокоиться в мире!" } } }, t = { d = 2.4, v = "nightelf-female#51", n = { x = 21 }, c = { x = { { 0.00, "Мы благодарим тебя, герой!" } } } } },
    [7462] = { d = 7.7, v = "nightelf-female#51", n = { x = 89 }, c = { x = { { 0.00, "В библиотеке, ты найдёшь древний сундук, спрятанный под лестницей." }, { 4.78, "Можешь взять оттуда, что тебе понравится." } } } },
    [7463] = { d = 42.8, g = 1, v = "nightelf-male#54", n = { m = 414, f = 414 }, c = { m = { { 0.00, "А-а, герой, посвятивший себя магии!" }, { 3.06, "Удивительно." }, { 4.11, "Я не видывал подобных тебе уже... сколько?" }, { 7.69, "Которое у нас тысячелетье на дворе?" }, { 10.61, "Да уже лет пятьсот!" }, { 12.25, "У меня есть кое-что, что поможет утолить твою жажду, но сначала тебе придётся выполнить одно моё поручение." }, { 21.14, "В Эльдре'Таласе завелась аномалия." }, { 24.73, "В восточном крыле поселился элементаль воды." }, { 28.46, "Надо его... того... занести в каталог." }, { 31.75, "Ступай в Квартал Криводревов, и добудь мне частицу стихийной сущности Гидротвари." }, { 38.47, "Принеси её мне, а я тебя научу одной полезной штучке!" } }, f = { { 0.00, "А-а, героиня, посвятившая себя магии!" }, { 3.19, "Удивительно." }, { 4.23, "Я не видывал подобных тебе уже... сколько?" }, { 7.79, "Которое у нас тысячелетье на дворе?" }, { 10.68, "Да уже лет пятьсот!" }, { 12.31, "У меня есть кое-что, что поможет утолить твою жажду, но сначала тебе придётся выполнить одно моё поручение." }, { 21.14, "В Эльдре'Таласе завелась аномалия." }, { 24.70, "В восточном крыле поселился элементаль воды." }, { 28.41, "Надо его... того... занести в каталог." }, { 31.67, "Ступай в Квартал Криводревов, и добудь мне частицу стихийной сущности Гидротвари." }, { 38.34, "Принеси её мне, а я тебя научу одной полезной штучке!" } } }, t = { d = 12.3, g = 1, v = "nightelf-male#54", n = { m = 91, f = 91 }, c = { m = { { 0.00, "Чудесно!" }, { 0.86, "Да, а ты кто такой?" }, { 2.68, "А, впрочем, неважно!" }, { 4.66, "Так что я должен был тебе дать?" }, { 7.60, "А-а, ну, тебе, возможно, пригодится вот это..." } }, f = { { 0.00, "Чудесно!" }, { 0.89, "Да, а ты кто такая?" }, { 2.77, "А, впрочем, неважно!" }, { 4.82, "Так что я должен был тебе дать?" }, { 7.85, "А-а, ну, тебе, возможно, пригодится вот это..." } } } } },
    [7481] = { d = 38.7, g = 1, v = "tauren-male#68", n = { m = 391, f = 392 }, c = { m = { { 0.00, "Несколько лет тому назад одинокий эльфийский мастер по имени Кариэль Винтхалус бежал из своей разорённой родной земли, унеся с собой несколько древних эльфийских артефактов." }, { 14.20, "Поиски пропавшего мастера привели нас из руин Кель'Таласа через Пылающие степи и морские просторы в Фералас." }, { 23.11, "Мы подозреваем, что эльф искал убежища в залах Эльдре'Таласа (ныне известного как Забытый Город)." }, { 30.98, "Отыщи его, странник!" }, { 32.75, "Жив он или мёртв, а знания, которые он унёс с собой, отыскать необходимо!" } }, f = { { 0.00, "Несколько лет тому назад одинокий эльфийский мастер по имени Кариэль Винтхалус бежал из своей разорённой родной земли, унеся с собой несколько древних эльфийских артефактов." }, { 14.26, "Поиски пропавшего мастера привели нас из руин Кель'Таласа через Пылающие степи и морские просторы в Фералас." }, { 23.21, "Мы подозреваем, что эльф искал убежища в залах Эльдре'Таласа (ныне известного как Забытый Город)." }, { 31.11, "Отыщи его, странница!" }, { 32.96, "Жив он или мёртв, а знания, которые он унёс с собой, отыскать необходимо!" } } }, t = { d = 8.9, v = "tauren-male#68", n = { x = 66 }, c = { x = { { 0.00, "Какое горе!" }, { 1.29, "Какая трагедия!" }, { 2.95, "Так ты говоришь, всё пропало?" }, { 5.90, "И никаких следов Кариэля?" } } } } },
    [7482] = { d = 34.2, g = 1, v = "nightelf-female#53", n = { m = 391, f = 392 }, c = { m = { { 0.00, "Несколько лет тому назад одинокий эльфийский мастер по имени Кариэль Винтхалус бежал из своей разорённой родной земли, унеся с собой несколько древних эльфийских артефактов." }, { 12.68, "Поиски пропавшего мастера привели нас из руин Кель'Таласа через Пылающие степи и морские просторы в Фералас." }, { 20.59, "Мы подозреваем, что эльф искал убежища в залах Эльдре'Таласа (ныне известного как Забытый Город)." }, { 27.58, "Отыщи его, странник!" }, { 29.15, "Жив он или мёртв, а знания, которые он унёс с собой, отыскать необходимо!" } }, f = { { 0.00, "Несколько лет тому назад одинокий эльфийский мастер по имени Кариэль Винтхалус бежал из своей разорённой родной земли, унеся с собой несколько древних эльфийских артефактов." }, { 12.59, "Поиски пропавшего мастера привели нас из руин Кель'Таласа через Пылающие степи и морские просторы в Фералас." }, { 20.48, "Мы подозреваем, что эльф искал убежища в залах Эльдре'Таласа (ныне известного как Забытый Город)." }, { 27.46, "Отыщи его, странница!" }, { 29.09, "Жив он или мёртв, а знания, которые он унёс с собой, отыскать необходимо!" } } }, t = { d = 7.7, v = "nightelf-female#53", n = { x = 66 }, c = { x = { { 0.00, "Какое горе!" }, { 1.18, "Какая трагедия!" }, { 2.70, "Так ты говоришь, всё пропало?" }, { 5.40, "И никаких следов Кариэля?" } } } } },
    [7483] = { d = 34.9, v = "nightelf-male#54", n = { x = 371 }, c = { x = { { 0.00, "Мастер Винтхалус потерял \"Манускрипт Скорости\" в восточном крыле." }, { 5.19, "Этот манускрипт позволит тебе наложить на всё своё снаряжение небольшое ускоряющее заклятие." }, { 12.29, "Детские игрушки, на самом деле…" }, { 14.80, "Тем не менее, если тебя это всё же интересует, принеси мне манускрипт, и кое-какие необходимые реагенты." }, { 22.88, "Хм..." }, { 23.30, "Насколько я помню, там требуется кровь героев, безупречный чёрный алмаз и большие сияющие осколки." }, { 30.82, "Впрочем, я могу и ошибиться!" }, { 32.98, "*Лидрос пожимает плечами.*" } } }, t = { d = 10.2, v = "nightelf-male#54", n = { x = 116 }, c = { x = { { 0.00, "Ну, вот тебе твой магический камень стремительности, как и было обещано." }, { 6.36, "Только не стремись извести его сразу!" } } } } },
    [7484] = { d = 36.0, v = "nightelf-male#54", n = { x = 388 }, c = { x = { { 0.00, "Этот манускрипт едва не вызвал интерес у одного из юных фамильяров хранителя мудрости!" }, { 6.10, "Бедняжка, ему было всего несколько недель от роду!" }, { 11.01, "Тем из вас, кто интересуется магией, этот манускрипт может пригодиться!" }, { 16.35, "Он пропал где-то в этом крыле." }, { 18.74, "Могу только предположить, что его прибрал к рукам один из духов высокорождённых." }, { 24.82, "Принесите мне \"Манускрипт Средоточия\", несколько больших сияющих осколков, шкуру Тени и безупречный чёрный алмаз, и я создам для вас магический камень." } } }, t = { d = 4.8, g = 1, v = "nightelf-male#54", n = { x = 43 }, c = { m = { { 0.00, "Смотри, герой, не покалечься, когда будешь пускать его в ход!" } }, f = { { 0.00, "Смотри, героиня, не покалечься, когда будешь пускать его в ход!" } } } } },
    [7485] = { d = 39.3, v = "nightelf-male#54", n = { x = 430 }, c = { x = { { 0.00, "Потеряв этот манускрипт, он рыдал, как ребёнок!" }, { 3.49, "Не пойми меня неправильно – мне и самому случалось плакать из-за книг, ведь нет большей утраты, чем утраченные знания, – но рыдать из-за этих почти бесполезных обрывков заклинаний?" }, { 16.86, "Абсурд!" }, { 17.46, "Мне даже подумалось, что принц, пожалуй, оказал ему услугу, отделив его плоть от костей." }, { 24.05, "Принеси мне этот манускрипт вместе с безупречным чёрным алмазом, большими сияющими осколками и потёртым шовным материалом поганища, и я воссоздам этот магический камень!" }, { 36.54, "Ах, да: в общем, ищи в северном крыле." } } }, t = { d = 5.8, v = "nightelf-male#54", n = { x = 47 }, c = { x = { { 0.00, "Да-да!" }, { 0.71, "Успокойся." }, { 1.77, "Вот твой магический камень, как я и обещал." } } } } },
    [7486] = { d = 32.8, v = "elemental-water-lord", n = { x = 313 }, c = { x = { { 0.00, "Твои заслуги перед Повелителями Вод превосходят самые смелые ожидания." }, { 6.16, "Мы не могли предположить, что обитатель этого мира может обладать подобной силой!" }, { 13.25, "Не знаю, как у твоего народа принято выражать благодарность, однако могу пообещать тебе щедрую награду." }, { 22.28, "Отправляйся в южную часть острова и найди сундук, сокрытый в волнах." }, { 28.21, "В том сундуке твоя награда." }, { 30.62, "Иди." }, { 31.09, "Забери свою награду." } } }, t = { d = 10.2, v = "elemental-water-lord", n = { x = 99 }, c = { x = { { 0.00, "*Голос Гидраксиса вторит рокоту прибоя*" }, { 3.20, "Выбирай, что тебе по душе." }, { 5.47, "Пусть мой дар защитит тебя от недругов Повелителей вод." } } } } },
    [7487] = { d = 41.1, g = 1, v = "bloodelf-male", n = { m = 458, f = 459 }, c = { m = { { 0.00, "Земля испещрена трещинами и разломами – прямо у нас под ногами, герой." }, { 4.93, "В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра Чёрной горы, в самую вотчину Повелителя огня." }, { 13.64, "Удивлён?" }, { 14.21, "Прискорбно..." }, { 15.16, "Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб..." }, { 21.28, "Уверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться." }, { 27.03, "Смотрю, у тебя глаза заблестели." }, { 29.37, "Послушай, приобрести сродство с недрами не так сложно." }, { 33.15, "Отправляйся в Глубины Чёрной горы и принеси мне фрагмент ядра." }, { 37.51, "Я сделаю так, что ты сможешь видеть портал." } }, f = { { 0.00, "Земля испещрена трещинами и разломами – прямо у нас под ногами, героиня." }, { 5.38, "В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра Чёрной горы, в самую вотчину Повелителя огня." }, { 14.09, "Удивлена?" }, { 14.92, "Прискорбно..." }, { 15.87, "Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб..." }, { 21.99, "Уверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться." }, { 27.74, "Смотрю, у тебя глаза заблестели." }, { 30.08, "Послушай, приобрести сродство с недрами не так сложно." }, { 33.86, "Отправляйся в Глубины Чёрной горы и принеси мне фрагмент ядра." }, { 38.22, "Я сделаю так, что ты сможешь видеть портал." } } } },
    [7488] = { d = 37.4, v = "nightelf-male#55", n = { x = 438 }, c = { x = { { 0.00, "Маг Лефтендрис, злокозненная эльфийка крови, чья жестокость уступает лишь её извращённой приверженности к магии, бежала в Забытый Город!" }, { 9.42, "Она создала магическое устройство: сеть, улавливающую энергию этого места, – и мы опасаемся, что, если Лефтендрис не остановить, она нанесёт непоправимый урон нашему миру!" }, { 21.46, "Останови её." }, { 22.35, "Отыщи её и отними у неё эту сеть." }, { 24.71, "Она, скорее всего, где-то неподалёку от сатиров в Квартале Криводревов Забытого Города." }, { 30.88, "Принеси эту сеть мне, чтобы мы могли осторожно выпустить захваченную ею энергию на свободу..." } } }, t = { d = 34.6, v = "nightelf-male#55", n = { x = 398 }, c = { x = { { 0.00, "Тебе удалось добыть сеть!" }, { 1.86, "Молодец!" }, { 2.50, "Лефтендрис, как и многие ей подобные эльфы, совершенно не задумывается о том, чем необузданное применение магии может грозить нашему миру." }, { 12.24, "Они мнят себя владыками магии, не сознавая, что они всего лишь рабы своей собственной зависимости." }, { 19.28, "Её смерть печалит меня, но это было необходимо." }, { 22.68, "Спасибо тебе." }, { 23.70, "Энергию, накопившуюся в сети, мы осторожно выпустим на свободу в глуши, а саму сеть я уничтожу, чтобы она не попала в руки ещё какому-нибудь безумному магу." } } } } },
    [7489] = { d = 41.2, v = "tauren-male", n = { x = 444 }, c = { x = { { 0.00, "Эльфийка крови Лефтендрис перешла все мыслимые границы!" }, { 4.39, "Она так жаждала всё новой магической энергии, что бросила вызов своим собратьям и создала хитроумное устройство, сеть, предназначенную для того, чтобы всасывать отравленную магию Забытого Города." }, { 19.68, "Она и теперь собирает эту энергию, намереваясь использовать её против своих врагов!" }, { 26.34, "Лефтендрис необходимо остановить." }, { 28.96, "Отыщи её в Квартале Криводревов в Забытом Городе, повергни её и принеси её сеть мне, чтобы мы могли передать её для изучения более здравомыслящим эльфам крови." } } }, t = { d = 37.3, v = "tauren-male", n = { x = 357 }, c = { x = { { 0.00, "Молодец!" }, { 0.78, "Эта сеть содержит в себе большие запасы магической энергии Забытого Города, и я опасался, что, если этой магией овладеет столь безответственное существо, как Лефтендрис, последствия могут быть непредсказуемыми." }, { 18.76, "Её смерть меня, конечно, печалит, но я понимаю, что живой бы она с этой сетью не рассталась." }, { 26.70, "Спасибо тебе." }, { 27.94, "Я отправлю эту сеть более трезвомыслящим специалистам по магии, чем Лефтендрис." }, { 34.71, "Им такую мощь доверить можно..." } } } } },
    [7490] = { d = 10.8, v = "narrator", n = { x = 106 }, c = { x = { { 0.00, "Тебе удалось совершить невозможное!" }, { 3.09, "Царица чёрных драконов лежит мёртвой у твоих ног." }, { 7.25, "Отруби ей голову и отнеси её своему вождю." } } }, t = { d = 10.6, g = 1, v = "named/thrall", n = { m = 88, f = 89 }, c = { m = { { 0.00, "Это великая победа Орды." }, { 2.42, "Ты столько раз приносил честь своему вождю." }, { 6.42, "Пришло время вождю воздать честь тебе." } }, f = { { 0.00, "Это великая победа Орды." }, { 2.57, "Ты столько раз приносила честь своему вождю." }, { 6.91, "Пришло время вождю воздать честь тебе." } } } } },
    [7491] = { d = 9.7, g = 1, v = "named/thrall", n = { m = 80, f = 82 }, c = { m = { { 0.00, "Властитель Рунтак ожидает тебя в Аллее Силы." }, { 4.48, "*Тралл отдаёт вам честь.*" }, { 6.88, "Не заставляй его ждать, герой!" } }, f = { { 0.00, "Властитель Рунтак ожидает тебя в Аллее Силы." }, { 4.40, "*Тралл отдаёт вам честь.*" }, { 6.64, "Не заставляй его ждать, героиня!" } } }, t = { d = 5.4, v = "orc-male#60", n = { x = 49 }, c = { x = { { 0.00, "Выбери себе награду, и мы достойно отпразднуем твою победу!" } } } } },
    [7492] = { d = 21.2, v = "scourge-male#83", n = { x = 210 }, c = { x = { { 0.00, "Тало Терновое Копыто, тауренский старейшина, живущий в Фераласе, прислал просьбу о помощи." }, { 7.49, "Подробностей он не сообщает, но говорит, что ему требуются агенты для тонкой... и опасной работы!" }, { 15.42, "Послужи Орде." }, { 16.61, "Отправляйся в Лагерь Мохаче в Фераласе и поговори с Тало." } } }, npc = { [10880] = { d = 21.0, v = "orc-male", n = { x = 210 }, c = { x = { { 0.00, "Тало Терновое Копыто, тауренский старейшина, живущий в Фераласе, прислал просьбу о помощи." }, { 7.43, "Подробностей он не сообщает, но говорит, что ему требуются агенты для тонкой... и опасной работы!" }, { 15.31, "Послужи Орде." }, { 16.48, "Отправляйся в Лагерь Мохаче в Фераласе и поговори с Тало." } } } }, [10881] = { d = 22.8, v = "tauren-male", n = { x = 210 }, c = { x = { { 0.00, "Тало Терновое Копыто, тауренский старейшина, живущий в Фераласе, прислал просьбу о помощи." }, { 8.05, "Подробностей он не сообщает, но говорит, что ему требуются агенты для тонкой... и опасной работы!" }, { 16.58, "Послужи Орде." }, { 17.86, "Отправляйся в Лагерь Мохаче в Фераласе и поговори с Тало." } } } } }, t = { d = 16.2, g = 1, v = "tauren-male", n = { m = 124, f = 125 }, c = { m = { { 0.00, "А, приятно видеть, что герой откликнулся на мой призыв!" }, { 5.39, "Мне нужна твоя помощь." }, { 7.69, "Но боюсь, что это дело заведёт тебя на опасный путь…" }, { 12.82, "Этот путь лежит в Забытый Город." } }, f = { { 0.00, "А, приятно видеть, что героиня откликнулась на мой призыв!" }, { 5.65, "Мне нужна твоя помощь." }, { 7.94, "Но боюсь, что это дело заведёт тебя на опасный путь…" }, { 13.06, "Этот путь лежит в Забытый Город." } } } } },
    [7493] = { t = { d = 29.8, g = 1, v = "orc-male#60", n = { m = 288, f = 290 }, c = { m = { { 0.00, "Убийца драконов и опытный кожевник?" }, { 3.07, "Ты не перестаёшь удивлять, герой." }, { 5.83, "Я восхищён." }, { 6.75, "Прими же то, чему я собираюсь тебя научить." }, { 10.51, "Эти знания окажутся бесценными, если ты хочешь уничтожить то, что осталось от стаи чёрных драконов." }, { 18.95, "Сделай плащ из чешуи матери выводка." }, { 22.09, "Он защитит тебя и твоих союзников от испепеляющего дыхания владыки Чёрной горы..." }, { 29.00, "Нефариана." } }, f = { { 0.00, "Убийца драконов и опытный кожевник?" }, { 3.00, "Ты не перестаёшь удивлять, героиня." }, { 5.86, "Я восхищён." }, { 6.76, "Прими же то, чему я собираюсь тебя научить." }, { 10.44, "Эти знания окажутся бесценными, если ты хочешь уничтожить то, что осталось от стаи чёрных драконов." }, { 18.70, "Сделай плащ из чешуи матери выводка." }, { 21.78, "Он защитит тебя и твоих союзников от испепеляющего дыхания владыки Чёрной горы..." }, { 28.53, "Нефариана." } } } } },
    [7494] = { d = 33.7, v = "human-male", n = { x = 409 }, c = { x = { { 0.00, "Твоя помощь нужна в Фераласе!" }, { 2.14, "Лефтендрис, маг, объявленный вне закона, бежала в развалины древнего эльфийского города Эльдре'Таласа, ныне именуемого Забытым Городом." }, { 11.53, "Есть основания предполагать, что у неё с собой мощный магический артефакт, который необходимо вернуть." }, { 18.58, "Латроникус Лунное Копьё ищет агентов, которые согласились бы отправиться в Забытый Город и отнять у Лефтендрис этот артефакт." }, { 27.34, "Послужи Альянсу!" }, { 28.53, "Отправляйся к Латроникусу." }, { 30.36, "Он находится в Крепости Оперённой Луны в Фераласе." } } }, npc = { [10877] = { d = 33.4, v = "dwarf-male", n = { x = 409 }, c = { x = { { 0.00, "Твоя помощь нужна в Фераласе!" }, { 2.12, "Лефтендрис, маг, объявленный вне закона, бежала в развалины древнего эльфийского города Эльдре'Таласа, ныне именуемого Забытым Городом." }, { 11.42, "Есть основания предполагать, что у неё с собой мощный магический артефакт, который необходимо вернуть." }, { 18.40, "Латроникус Лунное Копьё ищет агентов, которые согласились бы отправиться в Забытый Город и отнять у Лефтендрис этот артефакт." }, { 27.08, "Послужи Альянсу!" }, { 28.26, "Отправляйся к Латроникусу." }, { 30.07, "Он находится в Крепости Оперённой Луны в Фераласе." } } } }, [10878] = { d = 34.5, v = "nightelf-female#53", n = { x = 409 }, c = { x = { { 0.00, "Твоя помощь нужна в Фераласе!" }, { 2.19, "Лефтендрис, маг, объявленный вне закона, бежала в развалины древнего эльфийского города Эльдре'Таласа, ныне именуемого Забытым Городом." }, { 11.80, "Есть основания предполагать, что у неё с собой мощный магический артефакт, который необходимо вернуть." }, { 19.02, "Латроникус Лунное Копьё ищет агентов, которые согласились бы отправиться в Забытый Город и отнять у Лефтендрис этот артефакт." }, { 27.98, "Послужи Альянсу!" }, { 29.21, "Отправляйся к Латроникусу." }, { 31.08, "Он находится в Крепости Оперённой Луны в Фераласе." } } } } }