    [7507] = { d = 17.0, v = "narrator", n = { x = 177 }, c = { x = { { 0.00, "Вы обнаружили нечто очень важное." }, { 2.72, "Эта книга не похожа ни на одну из тех, которые вам доводилось видеть раньше." }, { 8.81, "Такое впечатление, как будто кому-то удалось испортить печать Читальни." }, { 14.54, "Текст искажён и читается с трудом." } } }, t = { d = 29.7, g = 1, v = "nightelf-male#54", n = { m = 307, f = 309 }, c = { m = { { 0.00, "На чёрном рынке ты мог бы получить за эту книгу немало золота!" }, { 4.92, "Тем более, что защитная печать теперь сломана, так что тайны драконоборчества доступны любому, кому хватит любопытства, чтобы овладеть знаниями, сокрытыми на священных страницах!" }, { 18.97, "Возможно, ты заслуживаешь ценной награды..." }, { 22.39, "Точнее, награды, которую придётся добывать ценой громадных усилий!" }, { 27.60, "*Лидрос ухмыляется.*" } }, f = { { 0.00, "На чёрном рынке ты могла бы получить за эту книгу немало золота!" }, { 5.04, "Тем более, что защитная печать теперь сломана, так что тайны драконоборчества доступны любому, кому хватит любопытства, чтобы овладеть знаниями, сокрытыми на священных страницах!" }, { 18.82, "Возможно, ты заслуживаешь ценной награды..." }, { 22.17, "Точнее, награды, которую придётся добывать ценой громадных усилий!" }, { 27.28, "*Лидрос ухмыляется.*" } } } } },
    [7508] = { d = 5.4, v = "narrator", n = { x = 58 }, c = { x = { { 0.00, "Если хотите взять на себя эту задачу, отнесите тусклый клинок Лидросу." } } }, t = { d = 13.5, v = "nightelf-male#54", n = { x = 126 }, c = { x = { { 0.00, "Если тебе удастся войти в логово драконицы, раскали клинок в её огненном дыхании, а потом остуди в её собственной крови." }, { 10.55, "И тогда клинок будет навеки твоим." } } } } },
    [7509] = { d = 40.4, v = "nightelf-male#54", n = { x = 439 }, c = { x = { { 0.00, "Отнеси потускневший древний клинок в логово Ониксии и вызови драконицу на бой." }, { 5.99, "Возможно, тебе придётся прибегнуть к кое-каким уловкам, чтобы заставить её раскалить меч." }, { 12.80, "Разумеется, в бою она будет пытаться испепелить тебя своим огненным дыханием." }, { 18.86, "Положи потускневший древний клинок где-нибудь поблизости и постарайся, чтобы огненное дыхание попало на клинок." }, { 27.40, "А после этого – если, конечно, выживешь, – схвати раскалённый клинок и прикончи драконицу." }, { 34.28, "Вонзи горячий древний клинок в её тело, чтобы получить закалённый древний клинок." } } }, t = { d = 6.9, g = 1, v = "nightelf-male#54", n = { x = 68 }, c = { m = { { 0.00, "Ну, герой, вот тебе клинок Кель-Серрар, как и было обещано." } }, f = { { 0.00, "Ну, героиня, вот тебе клинок Кель-Серрар, как и было обещано." } } } } },
    [7541] = { t = { d = 15.8, g = 1, v = "orc-male", n = { m = 147, f = 149 }, c = { m = { { 0.00, "Нашим учёным понадобится время, чтобы изучить подвеску, которую ты принёс." }, { 6.37, "Но за твою службу Орде я хочу вручить тебе скромную награду." }, { 11.15, "Спасибо." }, { 12.69, "Твои дела приносят честь тебе – и нам." } }, f = { { 0.00, "Нашим учёным понадобится время, чтобы изучить подвеску, которую ты принесла." }, { 6.54, "Но за твою службу Орде я хочу вручить тебе скромную награду." }, { 11.15, "Спасибо." }, { 12.79, "Твои дела приносят честь тебе – и нам." } } } } },
    [7562] = { d = 34.4, g = 1, v = "gnome-male", n = { m = 386, f = 388 }, c = { m = { { 0.00, "Ты хорошо изучил тёмные искусства и обрёл такую власть над существами из других миров, что... быть может, пришло время подчинить себе одного из знаменитых коней погибели." }, { 12.47, "Вызвать его в наш мир нелегко, для этого потребуется великая сила и большие затраты, но если ты хочешь владеть таким скакуном, поговори с Мор'зулом Кровопуском." }, { 24.34, "Он разбил лагерь рядом с Алтарём Бурь в Пылающих степях." }, { 28.48, "Ступай." }, { 29.08, "Задание рискованное, но такие чернокнижники как ты не страшатся опасностей." } }, f = { { 0.00, "Ты хорошо изучила тёмные искусства и обрела такую власть над существами из других миров, что... быть может, пришло время подчинить себе одного из знаменитых коней погибели." }, { 12.54, "Вызвать его в наш мир нелегко, для этого потребуется великая сила и большие затраты, но если ты хочешь владеть таким скакуном, поговори с Мор'зулом Кровопуском." }, { 24.29, "Он разбил лагерь рядом с Алтарём Бурь в Пылающих степях." }, { 28.38, "Ступай." }, { 28.97, "Задание рискованное, но такие чернокнижники как ты не страшатся опасностей." } } }, t = { d = 32.6, g = 1, v = "human-male", n = { m = 340, f = 340 }, c = { m = { { 0.00, "Приветствую тебя, добро пожаловать." }, { 2.69, "Ты здесь, чтобы, как и я, изучать Алтарь Бурь – быть может, обуздать его силу ради некой тайной цели..." }, { 10.40, "Или... ты пришёл поговорить со мной?" }, { 13.01, "Да, думаю, так и есть." }, { 14.62, "Хочешь подчинить себе коня погибели?" }, { 17.44, "Это непростая задача." }, { 19.11, "Она будет стоить тебе немало крови, пота... и, разумеется, золота." }, { 24.21, "Но зоротианский конь погибели – награда, за которую стоит побороться, так что если тебе интересно, слушай дальше..." } }, f = { { 0.00, "Приветствую тебя, добро пожаловать." }, { 2.67, "Ты здесь, чтобы, как и я, изучать Алтарь Бурь – быть может, обуздать его силу ради некой тайной цели..." }, { 10.33, "Или... ты пришла поговорить со мной?" }, { 12.99, "Да, думаю, так и есть." }, { 14.59, "Хочешь подчинить себе коня погибели?" }, { 17.38, "Это непростая задача." }, { 19.05, "Она будет стоить тебе немало крови, пота... и, разумеется, золота." }, { 24.10, "Но зоротианский конь погибели – награда, за которую стоит побороться, так что если тебе интересно, слушай дальше..." } } } } },
    [7563] = { d = 33.5, v = "human-male", n = { x = 365 }, c = { x = { { 0.00, "Кони погибели живут в другом мире, на огненных равнинах Зорота, и чтобы подчинить себе одного из них, необходимы могущественные руны." }, { 9.99, "Я могу начертать эти руны на пергаменте, но для этого нужны особые чернила." }, { 15.16, "В далёких Зимних Ключах живут зверосовы." }, { 19.13, "Некогда они были чистыми существами, но демоническое влияние Теснины Зловещего Шёпота лишило их разума, и они бродят по снегам в полном безумии." }, { 29.93, "Из их крови я и сделаю чернила." }, { 32.28, "Остаётся её добыть." } } }, t = { d = 12.2, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "А, замечательно." }, { 1.31, "Я переработаю эту кровь в чернила и сделаю обещанный тебе пергамент." }, { 6.85, "Может, я немножко оставлю себе, говорят, вкус у неё необыкновенный..." } } } } },
    [7564] = { d = 13.2, v = "human-male", n = { x = 152 }, c = { x = { { 0.00, "Мой слуга, Горзиеки, довольно опытный алхимик." }, { 3.42, "Он сможет приготовить чернила, о которых шла речь." }, { 7.03, "Я уже подготовил принесённую тобой кровь; отнеси её Горзиеки, пусть приступает к работе." } } }, t = { d = 31.2, v = "goblin-male#108", n = { x = 326 }, c = { x = { { 0.00, "А, это кровь." }, { 1.04, "Наверняка от мастера Морзула." }, { 3.32, "Он её обожает, и любит, когда она проливается." }, { 6.92, "Я же предпочитаю, чтобы она текла по жилам маленького грызуна." }, { 11.76, "Тогда она остаётся тёплой... до употребления." }, { 15.16, "В этой крови заключена великая сила." }, { 18.06, "Наверное, Морзул хочет создать ещё один пергамент для призыва коня погибели!" }, { 24.01, "Ух, как интересно!" }, { 25.40, "Коли так, то проводить ритуал будешь ты и... тебе понадобится не только кровь." } } } } },
    [7581] = { d = 16.2, g = 1, v = "human-male", n = { m = 191, f = 191 }, c = { m = { { 0.00, "Ты должен добыть у младших демонов кандалы для стражника ужаса." }, { 4.49, "Кровь сатира из племени Исчадий Природы, что живут в Забытом Городе, для этого сгодится." }, { 10.68, "Свернувшаяся кровь скрепит осколки Хедерины и даст силу хрустальной темнице." } }, f = { { 0.00, "Ты должна добыть у младших демонов кандалы для стражника ужаса." }, { 4.58, "Кровь сатира из племени Исчадий Природы, что живут в Забытом Городе, для этого сгодится." }, { 10.89, "Свернувшаяся кровь скрепит осколки Хедерины и даст силу хрустальной темнице." } } }, t = { d = 6.8, v = "human-male", n = { x = 72 }, c = { x = { { 0.00, "Ах, просто замечательно!" }, { 2.02, "Эта кровь подавит магическое сопротивление стражника ужаса." } } } } },
    [7582] = { d = 24.5, v = "human-male", n = { x = 286 }, c = { x = { { 0.00, "Демоны Хедерины, что живут у подножия горы Хиджал, выделяют яды Скверны, которые вызревают и твердеют, образуя антимагические кристаллы." }, { 9.80, "Они известны как слёзы Хедерины." }, { 12.12, "Даже чудовищная сила стражника ужаса не сможет разбить стены тюрьмы, сделанной из этого материала." }, { 19.27, "Отправляйся в Теснину Зловещего Шёпота в Зимних ключах, и добудь этих слёз." } } }, t = { d = 6.5, v = "human-male", n = { x = 78 }, c = { x = { { 0.00, "Осталось лишь соединить кровь Дикого Порождения с этими кристаллами, и темница будет готова." } } } } },
    [7583] = { d = 31.7, g = 1, v = "human-male", n = { m = 368, f = 368 }, c = { m = { { 0.00, "Темница готова." }, { 1.15, "Теперь самое трудное дело." }, { 3.14, "Ты должен найти и схватить командира стражников ужаса в Гниющем шраме при помощи этой хрустальной темницы." }, { 10.76, "Осторожнее!" }, { 11.59, "Стражник ужаса – коварный и смертельный враг, он будет пытаться уничтожить тебя, как только ты начнёшь обряд заточения." }, { 19.98, "Он будет отчаянно отбиваться, пытаясь избежать плена." }, { 23.82, "Он будет смотреть только на тебя." }, { 26.25, "Потому я рекомендую взять с собой друзей, которые не дадут ему погубить тебя!" } }, f = { { 0.00, "Темница готова." }, { 1.15, "Теперь самое трудное дело." }, { 3.13, "Ты должна найти и схватить командира стражников ужаса в Гниющем шраме при помощи этой хрустальной темницы." }, { 10.73, "Осторожнее!" }, { 11.56, "Стражник ужаса – коварный и смертельный враг, он будет пытаться уничтожить тебя, как только ты начнёшь обряд заточения." }, { 19.93, "Он будет отчаянно отбиваться, пытаясь избежать плена." }, { 23.76, "Он будет смотреть только на тебя." }, { 26.19, "Потому я рекомендую взять с собой друзей, которые не дадут ему погубить тебя!" } } }, t = { d = 8.0, g = 1, v = "human-male", n = { m = 87, f = 89 }, c = { m = { { 0.00, "Ты сделал всё, как я просил." }, { 2.08, "Теперь ты готов воспринять знание о том, как призывать и контролировать тварей." } }, f = { { 0.00, "Ты сделала всё, как я просил." }, { 2.17, "Теперь ты готова воспринять знание о том, как призывать и контролировать тварей." } } } } },
    [7601] = { d = 28.8, g = 1, v = "gnome-male", n = { m = 331, f = 331 }, c = { m = { { 0.00, "Если хочешь научиться у меня призывать инфернала-слугу, ты должен убить Крошиуса и добыть из его пылающих останков огненное ядро." }, { 9.39, "Однако, это не так просто, как кажется." }, { 12.21, "Крошиус чуть не дотла сгорел." }, { 14.34, "Тебе придётся снова воспламенить его тело и поднять его из праха." }, { 19.09, "Однако, для этого тебе придётся добыть другие ингредиенты из других демонических сущностей." }, { 25.59, "Мой бес по имени Бесёнок, покажет тебе дорогу." } }, f = { { 0.00, "Если хочешь научиться у меня призывать инфернала-слугу, ты должна убить Крошиуса и добыть из его пылающих останков огненное ядро." }, { 9.41, "Однако, это не так просто, как кажется." }, { 12.25, "Крошиус чуть не дотла сгорел." }, { 14.38, "Тебе придётся снова воспламенить его тело и поднять его из праха." }, { 19.15, "Однако, для этого тебе придётся добыть другие ингредиенты из других демонических сущностей." }, { 25.66, "Мой бес по имени Бесёнок, покажет тебе дорогу." } } }, t = { d = 2.7, v = "goblin-male", n = { x = 19 }, c = { x = { { 0.00, "Ох, опять двадцать пять..." } } } } },
    [7602] = { d = 36.0, v = "goblin-male", n = { x = 415 }, c = { x = { { 0.00, "Если ты намереваешься воскресить Крошиуса, тебе понадобится пламя Скверны." }, { 5.39, "Я могу зажечь его, но для этого потребуются кое-какие ингредиенты." }, { 10.27, "Тебе придётся принести мне безупречной субстанции Скверны из трёх краёв нашего мира." }, { 16.25, "Первый тип субстанции ты найдёшь у сатиров из племени Легаши, что в Азшаре." }, { 21.47, "Второй тип – у джеденарских легионеров, а третий можно добыть у стражей Скверны в Выжженных землях." }, { 28.62, "Принеси мне по порции каждой субстанции, и я зажгу пламя скверны, что позволит тебе оживить Крошиуса." } } }, t = { d = 5.8, v = "goblin-male", n = { x = 54 }, c = { x = { { 0.00, "Одну минуточку, и я сотворю из всех трёх субстанций пламя Скверны." } } } } },
    [7603] = { d = 24.2, v = "goblin-male", n = { x = 262 }, c = { x = { { 0.00, "Крошиус лежит грудой праха на северо-востоке отсюда, в долине Рваных Ран." }, { 5.62, "Возьми этот пламень Скверны и воспламени его останки." }, { 9.76, "Пламя оживит павшего инфернала." }, { 12.19, "После этого он наверняка пришибёт и тебя, и твоего прислужника." }, { 16.94, "Ну а если каким-то чудом тебе удастся уложить Крошиуса, возьми его огненное ядро и принеси Ниби." } } }, t = { d = 8.7, v = "gnome-male", n = { x = 89 }, c = { x = { { 0.00, "Сделка есть сделка!" }, { 1.59, "Бери это и быстро записывай." }, { 3.97, "У меня нет времени!" }, { 5.55, "На нас прёт моё самое величайшее творение!" } } } } },
    [7604] = { d = 46.2, g = 1, v = "narrator", n = { m = 502, f = 501 }, c = { m = { { 0.00, "Нижеподписавшийся со всей ответственностью заявляет, что сульфуронский слиток, переданный им братству Тория (О, О, О «Бэ, Тэ»), является подлинником." }, { 11.07, "Нижеподписавшийся также подтверждает, что О, О, О «Бэ, Тэ» не несёт никакой ответственности за любой вред, могущий последовать в результате неосторожного обращения с Сульфурасом, как то: использование Сульфураса в качестве материала для ковки; самостоятельные разработки; попытки воспроизведения; продажа и употребление в пищу." }, { 36.94, "Подпись под договором автоматически означает согласие подписавшегося со всеми условиями, перечисленными в документе." }, { 45.72, "Подпись" } }, f = { { 0.00, "Нижеподписавшаяся со всей ответственностью заявляет, что сульфуронский слиток, переданный ею братству Тория (О, О, О «Бэ, Тэ»), является подлинником." }, { 11.65, "Нижеподписавшаяся также подтверждает, что О, О, О «Бэ, Тэ» не несёт никакой ответственности за любой вред, могущий последовать в результате неосторожного обращения с Сульфурасом, как то: использование Сульфураса в качестве материала для ковки; самостоятельные разработки; попытки воспроизведения; продажа и употребление в пищу." }, { 37.10, "Подпись под договором автоматически означает согласие подписавшейся со всеми условиями, перечисленными в документе." }, { 45.76, "Подпись" } } }, t = { d = 6.9, v = "dwarf-male", n = { x = 74 }, c = { x = { { 0.00, "Приятно иметь с тобой дело!" }, { 2.18, "От имени Братства Тория желаю тебе удачи в поисках Сульфураса!" } } } } },
    [7621] = { t = { d = 27.1, g = 1, v = "human-female", n = { m = 297, f = 297 }, c = { m = { { 0.00, "Герой, тебе предстоит череда суровых испытаний, которые проверят все твои способности." }, { 6.55, "Советую выслушать историю, которую я расскажу." }, { 10.06, "И помни: это задание ты должен выполнить в одиночку." }, { 14.04, "Твоим союзникам лучше держаться в стороне." }, { 17.28, "За вмешательство посторонних последует суровейшее наказание." }, { 21.73, "Судьба привела сюда тебя и только тебя." }, { 24.84, "Сражайся с честью." }, { 26.26, "Обуздай Свет." } }, f = { { 0.00, "Героиня, тебе предстоит череда суровых испытаний, которые проверят все твои способности." }, { 6.57, "Советую выслушать историю, которую я расскажу." }, { 10.02, "И помни: это задание ты должна выполнить в одиночку." }, { 13.94, "Твоим союзникам лучше держаться в стороне." }, { 17.12, "За вмешательство посторонних последует суровейшее наказание." }, { 21.50, "Судьба привела сюда тебя и только тебя." }, { 24.56, "Сражайся с честью." }, { 25.95, "Обуздай Свет." } } } } },
    [7622] = { d = 23.4, g = 1, v = "human-female", n = { m = 269, f = 269 }, c = { m = { { 0.00, "Тебе предстоит сделать то, что оказалось не под силу мне – спасти крестьян, погибших во время бегства из Стратхольма." }, { 8.24, "Они выйдут на свет, и ты должен защитить их." }, { 11.37, "Если ты не сможешь спасти слишком многих, мы продолжим влачить наше проклятое существование." }, { 17.95, "Это настоящее испытание для всех твоих способностей." }, { 21.65, "Да поможет тебе Свет." } }, f = { { 0.00, "Тебе предстоит сделать то, что оказалось не под силу мне – спасти крестьян, погибших во время бегства из Стратхольма." }, { 8.35, "Они выйдут на свет, и ты должна защитить их." }, { 11.53, "Если ты не сможешь спасти слишком многих, мы продолжим влачить наше проклятое существование." }, { 18.20, "Это настоящее испытание для всех твоих способностей." }, { 21.95, "Да поможет тебе Свет." } } }, t = { d = 15.8, g = 1, v = "human-female", n = { m = 158, f = 159 }, c = { m = { { 0.00, "Твоя смелость и упорство не имеют себе равных, герой." }, { 4.29, "Ты обрёл право владеть Щепкой Нордрассила." }, { 7.60, "Тебе осталось исполнить лишь одно: найти Око Тени." }, { 11.69, "Найди его, даже если тебе придётся обыскать весь мир." } }, f = { { 0.00, "Твоя смелость и упорство не имеют себе равных, героиня." }, { 4.27, "Ты обрела право владеть Щепкой Нордрассила." }, { 7.59, "Тебе осталось исполнить лишь одно: найти Око Тени." }, { 11.52, "Найди его, даже если тебе придётся обыскать весь мир." } } } } },
    [7623] = { d = 31.4, v = "goblin-male#108", n = { x = 354 }, c = { x = { { 0.00, "Морзул говорит, что ты хочешь открыть портал в Зорот." }, { 3.82, "Раз так, тебе не обойтись без зоротианской звёздной пыли." }, { 7.76, "А её нелегко найти в Азероте!" }, { 9.86, "Она может быть лишь у одного существа – лорда Гиблопуста из Джеденара, сердца Совета Теней!" }, { 16.35, "Поговори с ним, вдруг он поделится звёздной пылью." }, { 19.78, "Впрочем, отправляясь в Джеденар, тебе необходимо принять злое обличье, чтобы добраться до Совета Теней." }, { 27.16, "Значит, тебе нужны мои зелья Теней, а они недешевы..." } } }, t = { d = 8.2, g = 1, v = "creature/dreadlord", n = { x = 67 }, c = { m = { { 0.00, "Моё терпение бесконечно, герой." }, { 2.69, "Но это не значит, что я уделю тебе больше секунды времени..." } }, f = { { 0.00, "Моё терпение бесконечно, героиня." }, { 2.96, "Но это не значит, что я уделю тебе больше секунды времени..." } } } } },
    [7624] = { d = 39.7, v = "creature/dreadlord", n = { x = 385 }, c = { x = { { 0.00, "Хочешь заслужить мою милость?" }, { 2.51, "Что ж, тогда убей, кого я укажу." }, { 5.25, "Мой слуга, Улатек, пресмыкается передо мной, а тем временем умышляет против меня вместе с лордом Хел'нуратом из Зорота." }, { 15.00, "Хел'нурат хочет низвергнуть меня и захватить власть, а Улатек – его шпион..." }, { 21.28, "Докажи, что служишь мне, а не моим противникам." }, { 25.13, "Вступи в бой с Улатеком в его собственном доме, Оплоте Теней на западе." }, { 31.04, "Передай ему, что мне известна его тайна." }, { 34.44, "Вот увидишь, он затрясётся от страха." }, { 37.40, "Принеси мне сердце предателя!" } } }, t = { d = 19.4, g = 1, v = "creature/dreadlord", n = { m = 182, f = 183 }, c = { m = { { 0.00, "Ах, великолепно!" }, { 1.33, "Полежав с недельку, оно обретёт ни с чем не сравнимый вкус!" }, { 6.05, "Может быть, мне послать за головой Улатека и поставить себе на обеденный стол?.." }, { 12.55, "Ты оказал мне услугу, герой, и я уже терпимей отношусь к тебе." }, { 17.72, "Немного терпимей." } }, f = { { 0.00, "Ах, великолепно!" }, { 1.34, "Полежав с недельку, оно обретёт ни с чем не сравнимый вкус!" }, { 6.11, "Может быть, мне послать за головой Улатека и поставить себе на обеденный стол?.." }, { 12.67, "Ты оказала мне услугу, героиня, и я уже терпимей отношусь к тебе." }, { 18.10, "Немного терпимей." } } } } },
    [7625] = { d = 25.1, g = 1, v = "creature/dreadlord", n = { m = 250, f = 251 }, c = { m = { { 0.00, "Так ты явился в поисках зоротианской звёздной пыли?" }, { 4.13, "Ты хочешь открыть портал в Зорот, владения моего соперника Хелнурата?" }, { 9.87, "Уж не одного ли из его драгоценных коней погибели ты хочешь украсть?" }, { 15.47, "Отлично." }, { 16.21, "У моего слуги, Ур'Дана, есть большой запас зоротианской звёздной пыли." }, { 21.95, "Обращайся к нему... если денег хватит." } }, f = { { 0.00, "Так ты явилась в поисках зоротианской звёздной пыли?" }, { 4.20, "Ты хочешь открыть портал в Зорот, владения моего соперника Хелнурата?" }, { 9.95, "Уж не одного ли из его драгоценных коней погибели ты хочешь украсть?" }, { 15.55, "Отлично." }, { 16.28, "У моего слуги, Ур'Дана, есть большой запас зоротианской звёздной пыли." }, { 22.03, "Обращайся к нему... если денег хватит." } } }, t = { d = 20.2, g = 1, v = "goblin-male#108", n = { m = 224, f = 226 }, c = { m = { { 0.00, "Вот она!" }, { 0.66, "Даже не верится!" }, { 1.91, "Должно быть, ты заключил большую сделку с Повелителем ужаса или заплатил огромную сумму, или и то, и другое!" }, { 9.90, "Мор'зул скоро получит чернила и сделает для тебя пергамент с рунами." }, { 14.98, "Ты откроешь портал в Зорот и украдёшь одного из знаменитых коней погибели!" } }, f = { { 0.00, "Вот она!" }, { 0.65, "Даже не верится!" }, { 1.87, "Должно быть, ты заключила большую сделку с Повелителем ужаса или заплатила огромную сумму, или и то, и другое!" }, { 9.81, "Мор'зул скоро получит чернила и сделает для тебя пергамент с рунами." }, { 14.77, "Ты откроешь портал в Зорот и украдёшь одного из знаменитых коней погибели!" } } } } },
    [7626] = { d = 25.4, v = "human-male", n = { x = 306 }, c = { x = { { 0.00, "Колокол Детмуры назвали в честь Детмуры Темноглазой." }, { 3.66, "Это один из трёх предметов, необходимых для создания круга Великого призыва." }, { 9.03, "Сопряжённый с Колесом и Свечой, он предоставит в твоё распоряжение огромный запас магической энергии." }, { 15.97, "Мой слуга Горзиеки может создать такой колокол, но ему понадобится много эликсиров Силы Теней." }, { 22.73, "Добудь их у алхимика и отнеси Горзиеки." } } }, t = { d = 12.5, g = 1, v = "goblin-male#108", n = { m = 140, f = 141 }, c = { m = { { 0.00, "Отлично!" }, { 0.63, "Надеюсь, эти эликсиры дались тебе не слишком тяжело." }, { 4.38, "Алхимики порой так скупятся на свои творения..." }, { 7.69, "Я сделаю колокол и сохраню его, пока ты не будешь готов к ритуалу." } }, f = { { 0.00, "Отлично!" }, { 0.63, "Надеюсь, эти эликсиры дались тебе не слишком тяжело." }, { 4.44, "Алхимики порой так скупятся на свои творения..." }, { 7.80, "Я сделаю колокол и сохраню его, пока ты не будешь готова к ритуалу." } } } } },
    [7627] = { d = 22.2, v = "human-male", n = { x = 272 }, c = { x = { { 0.00, "Колесо Чёрного Похода содержит в себе и направляет чёрную силу, необходимую для создания круга Великого призыва." }, { 7.73, "Горзиеки может создать это колесо, но ему понадобятся большие блестящие осколки, которые получают зачаровыватели, и руда чёрного железа, которую может добыть опытный горняк." }, { 19.83, "Принеси моему слуге всё необходимое." } } }, t = { d = 23.8, g = 1, v = "goblin-male#108", n = { m = 264, f = 265 }, c = { m = { { 0.00, "Ага, вот они!" }, { 1.04, "Я слышал, что чёрное железо добывают лишь в глубинах Чёрной горы, да и осколки не даром тебе достались." }, { 8.36, "Меня всегда поражает целеустремлённость чернокнижников." }, { 12.25, "Кабы все эти силы, да на поимку жуков, такой пир бы получился!" }, { 16.79, "Прости, отступил от темы." }, { 18.67, "Я сделаю колесо и отдам его, когда ты будешь готов провести ритуал." } }, f = { { 0.00, "Ага, вот они!" }, { 1.05, "Я слышал, что чёрное железо добывают лишь в глубинах Чёрной горы, да и осколки не даром тебе достались." }, { 8.45, "Меня всегда поражает целеустремлённость чернокнижников." }, { 12.39, "Кабы все эти силы, да на поимку жуков, такой пир бы получился!" }, { 16.97, "Прости, отступил от темы." }, { 18.87, "Я сделаю колесо и отдам его, когда ты будешь готова провести ритуал." } } } } },
    [7628] = { d = 23.1, v = "human-male", n = { x = 265 }, c = { x = { { 0.00, "Свеча Судного Дня хранит в себе огонь, который опаляет всех, желающих прервать твой ритуал." }, { 6.65, "Зажигая свечу при создании круга Великого призыва, ты сожжёшь всех упрямых демонов!" }, { 12.64, "Впрочем, сдержать этот огонь довольно трудно, и для этого нужна чешуя чёрного дракона." }, { 18.96, "Купи её у мастера снятия шкур и принеси Горзиеки Дикоглазу." } } }, t = { d = 11.1, g = 1, v = "goblin-male#108", n = { m = 116, f = 117 }, c = { m = { { 0.00, "А, хорошо." }, { 0.82, "При помощи чешуек я смогу обуздать пламя свечи." }, { 4.51, "Теперь я возьмусь за работу, и отдам тебе свечу, когда ты будешь готов провести ритуал." } }, f = { { 0.00, "А, хорошо." }, { 0.80, "При помощи чешуек я смогу обуздать пламя свечи." }, { 4.42, "Теперь я возьмусь за работу, и отдам тебе свечу, когда ты будешь готова провести ритуал." } } } } },
    [7629] = { d = 35.0, v = "goblin-male#108", n = { x = 395 }, c = { x = { { 0.00, "Для подготовки пергамента Морзула осталось сделать только одно – напитать бумагу зоротианской звёздной пылью." }, { 7.91, "И... боюсь, здесь этого не сделать." }, { 10.46, "Мне не хватит оборудования!" }, { 12.42, "Впрочем, я знаю об одной лаборатории, где есть всё необходимое." }, { 16.93, "Она находится в Некроситете, на острове Каэр Дарроу, в Чумных землях." }, { 22.03, "Я туда отправиться не смогу, но у меня есть идея." }, { 25.63, "Возьми эту бутылку." }, { 27.13, "В ней сидит довольно умный бес." }, { 29.42, "Выпусти его в алхимической лаборатории, и он напитает пергамент звёздной пылью." } } }, t = { d = 18.3, g = 1, v = "goblin-male#108", n = { m = 179, f = 180 }, c = { m = { { 0.00, "А, хорошо." }, { 0.86, "Джи'ви изготовил пергамент." }, { 3.08, "Как тебе Некроситет?" }, { 4.73, "Очаровательное место, правда?" }, { 7.09, "А тамошние жуки... говорят, они очень вкусные!" }, { 10.88, "Отличная работа, и спасибо, что вернул мне банку." }, { 14.82, "Она у меня очень давно... и она не продаётся!" } }, f = { { 0.00, "А, хорошо." }, { 0.86, "Джи'ви изготовил пергамент." }, { 3.07, "Как тебе Некроситет?" }, { 4.71, "Очаровательное место, правда?" }, { 7.06, "А тамошние жуки... говорят, они очень вкусные!" }, { 10.84, "Отличная работа, и спасибо, что вернула мне банку." }, { 14.83, "Она у меня очень давно... и она не продаётся!" } } } } },
    [7630] = { d = 22.1, v = "goblin-male#108", n = { x = 242 }, c = { x = { { 0.00, "Итак, Колокол, Колесо и Свеча готовы." }, { 2.85, "Осталось создать чёрный магнит." }, { 5.18, "Он понадобится во время ритуала, поддерживать прочие объекты, на случай, если они подведут." }, { 11.94, "Для создания магнита мне понадобится арканит." }, { 15.26, "У тебя его нет?" }, { 16.45, "Коли так, поищи его у алхимика." }, { 18.84, "Принеси мне арканит, и я создам чёрный магнит." } } }, t = { d = 13.6, g = 1, v = "goblin-male#108", n = { m = 155, f = 156 }, c = { m = { { 0.00, "Получилось!" }, { 0.83, "Отличная работа!" }, { 2.04, "Теперь я могу сделать чёрный магнит." }, { 4.66, "Когда наконец будешь готов к ритуалу создания круга Великого призыва, магнит тебе понадобится, чтобы ритуал не сорвался!" } }, f = { { 0.00, "Получилось!" }, { 0.85, "Отличная работа!" }, { 2.09, "Теперь я могу сделать чёрный магнит." }, { 4.78, "Когда наконец будешь готова к ритуалу создания круга Великого призыва, магнит тебе понадобится, чтобы ритуал не сорвался!" } } } } },
    [7631] = { d = 28.2, v = "human-male", n = { x = 339 }, c = { x = { { 0.00, "Всё готово." }, { 0.81, "Пришло время провести ритуал создания круга Великого призыва и воспользоваться пергаментом с рунами, начертанными зоротианской звёздной пылью..." }, { 10.70, "И открыть портал в Зорот." }, { 12.50, "Все инструкции по проведению ритуала я записал в тот свиток." }, { 16.61, "Изучи его внимательно, потому что следует делать всё в точности так, как написано, или успеха не добиться." }, { 23.95, "Удачи." }, { 24.45, "И да попадут души твоих врагов в твой мешочек осколков." } } }, t = { d = 15.9, v = "narrator", n = { x = 162 }, c = { x = { { 0.00, "Дух ксоротианского коня погибели повержен." }, { 3.51, "Хотя он в ярости, вы чувствуете, что душа его принадлежит вам…" }, { 8.67, "Она нашёптывает тёмные слова, благодаря которым вы постигаете, как вызывать коня погибели." } } } } },
    [7632] = { d = 19.4, v = "narrator", n = { x = 195 }, c = { x = { { 0.00, "Кожица листа светится ярко-зелёным." }, { 2.99, "Его поверхность очень морщиниста, на ней видны многочисленные прожилки и бороздки." }, { 9.79, "Если задуматься, то этот лист – наверняка нечто очень древнее и могущественное." }, { 16.37, "Может, поискать, кому он принадлежит?" } } }, t = { d = 16.0, g = 1, v = "creature/ancient", n = { x = 135 }, c = { m = { { 0.00, "Ещё бы мне не узнать собственный лист!" }, { 3.38, "Смотри-ка!" }, { 4.37, "В великолепном состоянии." }, { 6.68, "Очень мило с твоей стороны вернуть его, герой." }, { 11.13, "Возможно, ты сможешь сослужить нам службу, а мы – тебе." } }, f = { { 0.00, "Ещё бы мне не узнать собственный лист!" }, { 3.31, "Смотри-ка!" }, { 4.28, "В великолепном состоянии." }, { 6.55, "Очень мило с твоей стороны вернуть его, героиня." }, { 11.07, "Возможно, ты сможешь сослужить нам службу, а мы – тебе." } } } } },
    [7633] = { t = { d = 41.0, g = 1, v = "creature/ancient", n = { x = 307 }, c = { m = { { 0.00, "Твоё усердие и честность не остались незамеченными, герой." }, { 5.88, "Мы – Древние, защитники этого некогда великого леса." }, { 11.31, "Наши тела были уничтожены десять тысяч лет назад, когда Архимонд и Пылающий Легион двинулись на Хиджал." }, { 22.06, "Но наши духи живы." }, { 24.09, "У нас есть для тебя задания." }, { 26.94, "Выполнив их, ты постигнешь тайны Древних." }, { 31.17, "Знай: выполнив эти задания, просто вернись к этому камню, и мы откликнемся на зов." } }, f = { { 0.00, "Твоё усердие и честность не остались незамеченными, героиня." }, { 6.30, "Мы – Древние, защитники этого некогда великого леса." }, { 11.93, "Наши тела были уничтожены десять тысяч лет назад, когда Архимонд и Пылающий Легион двинулись на Хиджал." }, { 23.09, "Но наши духи живы." }, { 25.19, "У нас есть для тебя задания." }, { 28.14, "Выполнив их, ты постигнешь тайны Древних." }, { 32.53, "Знай: выполнив эти задания, просто вернись к этому камню, и мы откликнемся на зов." } } } } },
    [7634] = { d = 34.3, g = 1, v = "creature/ancient", n = { x = 277 }, c = { m = { { 0.00, "Приветствую тебя, герой." }, { 2.44, "Я Хастат, Древо Мудрости." }, { 4.96, "Я храню память тысячелетий." }, { 7.65, "Если один из моих листьев свернуть надлежащим образом, он будет служить колчаном, подобных которым не было уже десять тысяч лет." }, { 20.27, "Если к этому колчану в пару получить ещё и лук Дерев, то силе их равных не будет." }, { 28.49, "Принеси мне жил взрослого синего дракона, и получишь колчан." } }, f = { { 0.00, "Приветствую тебя, героиня." }, { 2.60, "Я Хастат, Древо Мудрости." }, { 5.11, "Я храню память тысячелетий." }, { 7.79, "Если один из моих листьев свернуть надлежащим образом, он будет служить колчаном, подобных которым не было уже десять тысяч лет." }, { 20.33, "Если к этому колчану в пару получить ещё и лук Дерев, то силе их равных не будет." }, { 28.63, "Принеси мне жил взрослого синего дракона, и получишь колчан." } } }, t = { d = 9.4, v = "creature/ancient", n = { x = 71 }, c = { x = { { 0.00, "Да защитят мои листья твои стрелы!" }, { 3.77, "Да не ведают они промаха!" }, { 6.50, "Да сгинут враги нашего мира!" } } } } },
    [7635] = { d = 27.6, v = "creature/ancient", n = { x = 233 }, c = { x = { { 0.00, "Вартус, конечно, предложил тебе посох для лука Дерев, но наложить чары на тетиву, без которой лук – не лук, могу только я." }, { 11.30, "Это простое дело, совсем плёвое." }, { 14.38, "Убей взрослого чёрного дракона и добудь из него жилу." }, { 19.37, "Принеси мне эту жилу, и я зачарую её так, что тетива для лука из неё будет, считай, вечной." } } }, t = { d = 12.3, v = "creature/ancient", n = { x = 100 }, c = { x = { { 0.00, "Это был самый мерзостный из драконов." }, { 3.83, "Жила просто смердит злом." }, { 6.47, "Подожди немного – я очищу её и наложу соответствующие чары." } } } } },
    [7636] = { d = 45.5, g = 1, v = "creature/ancient", n = { m = 382, f = 382 }, c = { m = { { 0.00, "Тайные слуги Пылающего Легиона всё ещё строят козни в нашем мире, герой." }, { 6.63, "Они оскверняют всё, к чему прикасаются." }, { 10.19, "Природа чахнет и стенает от их присутствия." }, { 14.08, "Ты должен выследить этих демонических разносчиков порчи." }, { 19.17, "Помни – ты должен лично разобраться с ними – иначе сбегут." }, { 24.51, "Пока ты один, они будут пытаться уничтожить тебя." }, { 29.12, "Ты должен сразить их, обратить их надменность в ничтожество!" }, { 34.92, "Я дам тебе кусок моей коры." }, { 37.51, "Письмена на ней приведут тебя к нашим врагам." }, { 41.64, "Принеси мне их головы." } }, f = { { 0.00, "Тайные слуги Пылающего Легиона всё ещё строят козни в нашем мире, героиня." }, { 7.06, "Они оскверняют всё, к чему прикасаются." }, { 10.76, "Природа чахнет и стенает от их присутствия." }, { 14.79, "Ты должна выследить этих демонических разносчиков порчи." }, { 20.08, "Помни – ты должна лично разобраться с ними – иначе сбегут." }, { 25.63, "Пока ты одна, они будут пытаться уничтожить тебя." }, { 30.42, "Ты должна сразить их, обратить их надменность в ничтожество!" }, { 36.55, "Я дам тебе кусок моей коры." }, { 39.24, "Письмена на ней приведут тебя к нашим врагам." }, { 43.52, "Принеси мне их головы." } } }, t = { d = 13.4, g = 1, v = "creature/ancient", n = { m = 109, f = 110 }, c = { m = { { 0.00, "Ты сослужил нам добрую службу!" }, { 2.97, "Возьми эту ветвь и соедини её с тетивой, которую умеет делать Стома." }, { 9.71, "Вместе они станут грозным оружием." } }, f = { { 0.00, "Ты сослужила нам добрую службу!" }, { 3.12, "Возьми эту ветвь и соедини её с тетивой, которую умеет делать Стома." }, { 9.97, "Вместе они станут грозным оружием." } } } } },
    [7637] = { d = 39.2, g = 1, v = "human-male", n = { m = 511, f = 511 }, c = { m = { { 0.00, "Чтобы подготовиться к этому заданию, ты должен сначала показать умение жертвовать и умение судить... в первую очередь – жертвовать." }, { 8.60, "Для выполнения задания ты должен получить курильницу экзорцизма у Верховного жреца Рохана." }, { 14.49, "Несмотря на то, что её использование будет продиктовано благими намерениями и существенными причинами, за неё должна быть предложена соответственная компенсация." }, { 24.73, "Отправляйся в Стальгорн и поговори с Верховным жрецом." }, { 28.21, "Если возьмёшь с собой достаточно звонкой монеты, чтобы компенсировать ему потерю курильницы, ты проявишь должную готовность к жертвам." }, { 36.98, "А теперь иди, время терять нельзя." } }, f = { { 0.00, "Чтобы подготовиться к этому заданию, ты должна сначала показать умение жертвовать и умение судить... в первую очередь – жертвовать." }, { 8.58, "Для выполнения задания ты должна получить курильницу экзорцизма у Верховного жреца Рохана." }, { 14.46, "Несмотря на то, что её использование будет продиктовано благими намерениями и существенными причинами, за неё должна быть предложена соответственная компенсация." }, { 24.68, "Отправляйся в Стальгорн и поговори с Верховным жрецом." }, { 28.15, "Если возьмёшь с собой достаточно звонкой монеты, чтобы компенсировать ему потерю курильницы, ты проявишь должную готовность к жертвам." }, { 36.91, "А теперь иди, время терять нельзя." } } }, t = { d = 21.6, v = "dwarf-male", n = { x = 263 }, c = { x = { { 0.00, "Да пребудут на тебе все благословения, друг мой паладин!" }, { 3.81, "Твой дар далеко превосходит наши нужды." }, { 6.56, "Твоя жертва не только поможет восстановить утраченное, но также позволит нам помочь самым бедным жителям Стальгорна." }, { 14.68, "А теперь дай-ка я удостоверюсь, что как следует подготовил эту курильницу для твоих будущих свершений." } } } } },
    [7638] = { d = 34.6, g = 1, v = "human-male", n = { m = 419, f = 421 }, c = { m = { { 0.00, "Пришло твоё время, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени... твоего рыцарского коня." }, { 9.89, "Поговори с лордом Грейсоном Тенеломом здесь, в Храмовом квартале Штормграда." }, { 15.06, "Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня." }, { 29.07, "Я желаю тебе всего наилучшего в этом испытании." }, { 32.38, "Во имя Света, мой благородный брат!" } }, f = { { 0.00, "Пришло твоё время, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени... твоего рыцарского коня." }, { 9.69, "Поговори с лордом Грейсоном Тенеломом здесь, в Храмовом квартале Штормграда." }, { 14.74, "Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня." }, { 28.46, "Я желаю тебе всего наилучшего в этом испытании." }, { 31.71, "Во имя Света, моя благородная сестра!" } } }, t = { d = 30.8, g = 1, v = "human-male", n = { m = 348, f = 351 }, c = { m = { { 0.00, "Я рад видеть тебя." }, { 1.32, "Я знаю, что ты желаешь раздобыть рыцарского коня, и вот наконец время пришло." }, { 6.70, "Ты, конечно, должен будешь пройти разнообразные испытания, но самое главное – это твоя решимость преодолеть множество препятствий, что встанут перед тобой." }, { 17.54, "Это не учебные задачи – ты уже явно перерос их." }, { 20.92, "Тебе придётся вырвать своего будущего скакуна из лап того зла, борьбе с которым ты посвятил свою жизнь." }, { 28.06, "Решай же, твоё время пришло!" } }, f = { { 0.00, "Я рад видеть тебя." }, { 1.35, "Я знаю, что ты желаешь раздобыть рыцарского коня, и вот наконец время пришло." }, { 6.86, "Ты, конечно, должна будешь пройти разнообразные испытания, но самое главное – это твоя решимость преодолеть множество препятствий, что встанут перед тобой." }, { 17.94, "Это не учебные задачи – ты уже явно переросла их." }, { 21.53, "Тебе придётся вырвать своего будущего скакуна из лап того зла, борьбе с которым ты посвятила свою жизнь." }, { 28.89, "Решай же, твоё время пришло!" } } } } },
    [7639] = { d = 16.8, g = 1, v = "dwarf-male", n = { m = 189, f = 191 }, c = { m = { { 0.00, "Прими эту курильницу и будь благословен." }, { 3.00, "Я сам применял её в нескольких обрядах экзорцизма, и она хорошо послужит тебе в грядущих тяжких испытаниях." }, { 10.92, "Ныне возвращайся к лорду Грейсону Тенелому в Штормград." }, { 15.05, "Он даст тебе поручение." } }, f = { { 0.00, "Прими эту курильницу и будь благословенна." }, { 3.14, "Я сам применял её в нескольких обрядах экзорцизма, и она хорошо послужит тебе в грядущих тяжких испытаниях." }, { 11.08, "Ныне возвращайся к лорду Грейсону Тенелому в Штормград." }, { 15.21, "Он даст тебе поручение." } } }, t = { d = 29.7, v = "human-male", n = { x = 336 }, c = { x = { { 0.00, "Да, это она." }, { 0.98, "Не раз вам придётся совершать этот обряд и не раз вам придётся в ходе него жертвовать собой." }, { 7.52, "Я рад, что вы готовы к этому." }, { 9.61, "Жертвенность – важнейшая составляющая, без которой не выполнить долга паладина... но не мне говорить вам об этом." }, { 17.66, "А теперь, вам придётся проявить истинное правосудие в ваших делах." }, { 22.43, "И эта курильница послужит вашим сосудом для оказания помощи истерзанным духам утраченной нами земли." } } } } },
    [7640] = { d = 30.9, g = 1, v = "human-male", n = { m = 387, f = 387 }, c = { m = { { 0.00, "Я добавил в курильницу щепотку заражённой земли Долины Ужаса, что в Восточных Чумных землях." }, { 6.16, "Ты должен будешь использовать курильницу для поиска мест, которые несут на себе признаки беспокойного поведения потусторонних сил." }, { 14.81, "Ищи зелёное свечение, исходящее из-под земли – так физический мир проявляет себя, мучимый миром потусторонним, и используй курильницу для вызова из-под земли злых духов." }, { 26.11, "Когда свершишь суд над призраками, я поставлю перед тобой новую задачу." } }, f = { { 0.00, "Я добавил в курильницу щепотку заражённой земли Долины Ужаса, что в Восточных Чумных землях." }, { 6.15, "Ты должна будешь использовать курильницу для поиска мест, которые несут на себе признаки беспокойного поведения потусторонних сил." }, { 14.77, "Ищи зелёное свечение, исходящее из-под земли – так физический мир проявляет себя, мучимый миром потусторонним, и используй курильницу для вызова из-под земли злых духов." }, { 26.04, "Когда свершишь суд над призраками, я поставлю перед тобой новую задачу." } } }, t = { d = 31.0, g = 1, v = "human-male", n = { m = 367, f = 368 }, c = { m = { { 0.00, "Отличная работа." }, { 1.20, "Свершить суд Света над теми, кто обитает во тьме – задача, к выполнению которой мы должны подходить с рвением и усердием." }, { 9.59, "Именно это ты и свершил благодаря своей жертве в Стальгорне и правосудию над духами Долины Ужаса." }, { 16.47, "Твои следующие шаги вновь потребуют от тебя и жертвенности, и умения вершить правосудие: ведь тебе нужно будет вернуть дух рыцарского коня, который служит сейчас рыцарю смерти, известному как Тёмный Терзатель." } }, f = { { 0.00, "Отличная работа." }, { 1.19, "Свершить суд Света над теми, кто обитает во тьме – задача, к выполнению которой мы должны подходить с рвением и усердием." }, { 9.52, "Именно это ты и свершила благодаря своей жертве в Стальгорне и правосудию над духами Долины Ужаса." }, { 16.41, "Твои следующие шаги вновь потребуют от тебя и жертвенности, и умения вершить правосудие: ведь тебе нужно будет вернуть дух рыцарского коня, который служит сейчас рыцарю смерти, известному как Тёмный Терзатель." } } } } },
    [7641] = { d = 35.8, v = "human-male", n = { x = 435 }, c = { x = { { 0.00, "Без особого чепрака рыцарский конь паладина ничем не отличается от обычного скакуна." }, { 5.77, "Чепрак для твоего скакуна не только должен быть изготовлен из наилучших материалов, но в силу сопутствующих обстоятельств нужно, чтобы он ещё был в достаточной мере настроен на призрачный мир." }, { 18.80, "Но всё по порядку – сначала нужно изготовить чепрак." }, { 22.40, "В Квартале Дворфов Штормграда проживает один из самых лучших современных мастеров – Гриманд Элмор." }, { 29.22, "Он берёт за свою работу недёшево, но качество его работы – как раз то, что нам нужно." }, { 34.93, "Поговори с ним." } } }, t = { d = 27.1, g = 1, v = "dwarf-male", n = { m = 301, f = 301 }, c = { m = { { 0.00, "Привет-привет, паренёк – лорд Тенелом известил меня заранее о том, что ты придёшь со мной повидаться." }, { 7.18, "Я с удовольствием сделаю чепрак, какой тебе нужен, но это будет нелегко, да и обойдётся недёшево." }, { 14.23, "Я об этом говорю открыто и в первую очередь." }, { 17.52, "Но, скажу я тебе – и Грейсон поддержит меня в этом утверждении – лучшего чепрака, чем изготовленный мной, ты во всём Азероте не найдёшь!" } }, f = { { 0.00, "Привет-привет, девушка – лорд Тенелом известил меня заранее о том, что ты придёшь со мной повидаться." }, { 7.18, "Я с удовольствием сделаю чепрак, какой тебе нужен, но это будет нелегко, да и обойдётся недёшево." }, { 14.17, "Я об этом говорю открыто и в первую очередь." }, { 17.44, "Но, скажу я тебе – и Грейсон поддержит меня в этом утверждении – лучшего чепрака, чем изготовленный мной, ты во всём Азероте не найдёшь!" } } } } },
    [7642] = { d = 32.6, v = "dwarf-male", n = { x = 367 }, c = { x = { { 0.00, "Для чепрака тебе понадобятся четыре вещи: рунная ткань для подкладки, арканитовые слитки для покрытия, цветки слезы Артаса для настройки на призрачный мир и святая вода Стратхольма для духовного укрепления." }, { 14.85, "На самом деле, вещей понадобится пять... если считать золото для меня." }, { 20.02, "Эта плата – за весь мой труд, а также седло и стремена ручной работы." }, { 25.05, "Когда наберёшь всё это, я смогу изготовить твой чепрак." }, { 29.04, "А пока ты ищешь необходимое, я приступлю к работе." } } }, t = { d = 10.2, v = "dwarf-male", n = { x = 95 }, c = { x = { { 0.00, "Это... да, это именно то, что нужно." }, { 3.04, "А ты весьма находчивый паладин, не так ли?" }, { 6.46, "Ладненько, давай-ка закончим с твоим чепраком!" } } } } },
    [7643] = { d = 34.6, v = "human-male", n = { x = 407 }, c = { x = { { 0.00, "Твоему чепраку нужно особое благословение, а его можно получить только у подходящего духа." }, { 6.42, "Такой дух обитает, например, в башне Забытого Города – это Дух древнего коня." }, { 11.89, "Сейчас его удерживает в плену Тендрис Криводрев." }, { 15.35, "Убей эту тварь, чтобы освободить духа." }, { 18.11, "Только имей в виду, что просто освободить – недостаточно." }, { 22.14, "Тебе нужно сначала умилостивить духа, чтобы получить его благословение." }, { 27.24, "Для этого понадобится особый лошадиный корм." }, { 30.32, "Ты найдёшь его в Южнобережье, если поговоришь с Меридет Карлсон." } } }, t = { d = 10.7, v = "narrator", n = { x = 104 }, c = { x = { { 0.00, "Дух древнего коня обнюхал корм и чинно захрустел им." }, { 4.57, "Насытившись, дух благосклонно позволил вам накинуть чепрак ему на спину." } } } } },
    [7644] = { d = 31.8, v = "narrator", n = { x = 317 }, c = { x = { { 0.00, "После того как чепрак наброшен на спину духу древнего коня, он начинает чуть заметно светиться." }, { 7.94, "На миг кажется, будто всё вокруг звенит от напряжения и магической мощи... а потом чепрак исчезает со спины коня." }, { 17.30, "Теперь он в вашем заплечном мешке." }, { 20.19, "Очевидно, чепрак получил благословение." }, { 23.46, "Теперь, согласно наставлениям лорда Тенелома, вам следует вернуться с этим чепраком к нему в Штормград." } } }, t = { d = 27.6, v = "human-male", n = { x = 330 }, c = { x = { { 0.00, "Тебе пришлось немало постранствовать, друг мой!" }, { 3.26, "И вот наконец твой чепрак готов к последнему шагу, который тебе придётся предпринять." }, { 9.14, "Этот чепрак пригодится тебе, чтобы седлать своего скакуна, когда труд искупления будет завершён." }, { 15.91, "Однако до этого тебе снова придётся вступить в тяжкую борьбу." }, { 20.23, "Твой час близок!" }, { 21.35, "Перед этим нам нужно изготовить ещё один, последний предмет." }, { 25.61, "Надеюсь, твой пыл ещё не иссяк?" } } } } },
    [7645] = { d = 37.6, v = "human-female#112", n = { x = 423 }, c = { x = { { 0.00, "Серебряная Длань считала меня ЧОКНУТОЙ, когда я сказала, что могу сделать особый конский корм, который сможет насытить призрачных лошадей." }, { 10.13, "ВСЕ считали меня чокнутой!" }, { 12.32, "Пришло время отыграться!" }, { 14.16, "Я сделаю, что тебе надо, ПАЛАДИН..." }, { 16.79, "ЗАЩИТНИК, тоже мне..." }, { 18.37, "Но обойдётся это недёшево." }, { 20.21, "Мне понадобится витаминизированное печенье из манны, которое продают только в Серебряном Рассвете." }, { 27.32, "Кроме того я требую – да, ТРЕБУЮ, золото в качестве компенсации за перенесённые страдания!" }, { 33.83, "Посмотрим, многим ли ты можешь пожертвовать, ПАЛАДИН." } } }, t = { d = 30.2, g = 1, v = "human-female#112", n = { m = 303, f = 304 }, c = { m = { { 0.00, "ДА, КТО...стоп, ты и золото мне даёшь?" }, { 2.73, "Лично ты не называл меня чокнутой – а они дразнили меня сдвинутой, слетевшей с катушек..." }, { 9.55, "И ты хочешь искупить зло, причинённое не тобой?" }, { 13.03, "Я... я недооценила тебя." }, { 14.87, "Если тебе понадобится ещё корм для коней, обращайся." }, { 18.82, "Я сделаю его бесплатно." }, { 20.67, "Спасибо... благородный герой." }, { 22.92, "Но деньги я себе оставлю – я не настолько чокнутая, чтобы отказаться от целого состояния." } }, f = { { 0.00, "ДА, КТО...стоп, ты и золото мне даёшь?" }, { 2.77, "Лично ты не называла меня чокнутой – а они дразнили меня сдвинутой, слетевшей с катушек..." }, { 9.76, "И ты хочешь искупить зло, причинённое не тобой?" }, { 13.29, "Я... я недооценила тебя." }, { 15.15, "Если тебе понадобится ещё корм для коней, обращайся." }, { 19.17, "Я сделаю его бесплатно." }, { 21.04, "Спасибо... благородная героиня." }, { 23.46, "Но деньги я себе оставлю – я не настолько чокнутая, чтобы отказаться от целого состояния." } } } } },
    [7646] = { d = 32.9, g = 1, v = "human-male", n = { m = 397, f = 398 }, c = { m = { { 0.00, "Теперь мы должны сконструировать магический кристалл – так начнётся твой подвиг и освобождение пленённого духа зловещего рыцарского коня." }, { 9.46, "Собственно, кристалл уже почти готов." }, { 12.19, "Катализатором для него послужила курильница, которую ты использовал, изгоняя духов из Долины Ужаса; осталось только сделать подходящую подставку для нашего прибора." }, { 23.75, "Да, и ещё нужны последние два компонента – азеротский алмаз и безупречный чёрный алмаз." }, { 29.78, "Эти два камня станут маяком, пронзающим тьму!" } }, f = { { 0.00, "Теперь мы должны сконструировать магический кристалл – так начнётся твой подвиг и освобождение пленённого духа зловещего рыцарского коня." }, { 9.24, "Собственно, кристалл уже почти готов." }, { 11.90, "Катализатором для него послужила курильница, которую ты использовала, изгоняя духов из Долины Ужаса; осталось только сделать подходящую подставку для нашего прибора." }, { 23.25, "Да, и ещё нужны последние два компонента – азеротский алмаз и безупречный чёрный алмаз." }, { 29.14, "Эти два камня станут маяком, пронзающим тьму!" } } }, t = { d = 33.8, v = "human-male", n = { x = 389 }, c = { x = { { 0.00, "Отличные камни." }, { 1.19, "Последние фрагменты теперь установлены на свои места." }, { 5.17, "Наконец-то, пришло твоё время!" }, { 7.42, "В глубине Главного склепа в Некроситете покоятся останки многих существ." }, { 12.79, "Среди них есть кости и некогда благородного рыцарского коня." }, { 17.23, "Призрачный дух скакуна теперь служит рыцарю смерти Тёмному Терзателю." }, { 22.33, "Ты победишь Терзателя и свершишь правый суд над его несчастным конём." }, { 27.36, "Только ты, можешь даровать душе скакуна искупление и избавить её от мук ужасного служения." } } } } },
    [7647] = { d = 35.7, v = "human-male", n = { x = 420 }, c = { x = { { 0.00, "Возьми эту суму – в ней собраны предметы, которые понадобятся тебе для выполнения задания." }, { 6.38, "Используй магический кристалл в самом сердце подвала Главного склепа для вызова проклятых духов, над которыми нужно свершить суд." }, { 15.48, "Во время испытания рассчитывай силы – духи могут оказаться сильнее, чем ты думаешь." }, { 21.35, "После гибели духов появится сам рыцарь смерти." }, { 24.70, "Срази его и верни потерянную душу рыцарского коня." }, { 28.37, "Только тогда, ты сможешь принести ей избавление и возложить чепрак на твоего нового скакуна." }, { 34.88, "Желаю удачи!" } } }, t = { d = 35.0, v = "narrator", n = { x = 344 }, c = { x = { { 0.00, "Искорка жизни, давно покинувшей бедного зверя, сверкает в его глазах, когда ваша рука возвращает ему его спасённую душу." }, { 10.41, "Вы покрываете спину скакуна чепраком и чувствуете всплеск святой силы – правосудие свершилось!" }, { 18.32, "Конь тыкается носом в вашу руку, как будто благодаря за избавление от груза ужасного прошлого." }, { 26.30, "Вы чувствуете, что теперь у вас появился верный друг." }, { 30.71, "Теперь у вас есть эпический боевой конь!" }, { 34.05, "Поздравляем!" } } } } },
    [7648] = { d = 27.8, g = 1, v = "dwarf-male", n = { m = 306, f = 306 }, c = { m = { { 0.00, "*Гриманд утирает пот со лба, сияя от гордости.*" }, { 4.48, "Готово, друг мой." }, { 5.69, "Это одно из моих лучших изделий – не хуже, чем тот чепрак, что я собственноручно смастерил для лорда Тенелома, когда он отправлялся за своим конём." }, { 16.00, "Благодарю тебя за доверие." }, { 17.91, "Несомненно, и сам Грейсон захочет полюбоваться на мою работу." }, { 22.24, "Покажи ему чепрак и передай мою искреннюю благодарность за его достойные дела." } }, f = { { 0.00, "*Гриманд утирает пот со лба, сияя от гордости.*" }, { 4.24, "Готово, моя леди." }, { 5.56, "Это одно из моих лучших изделий – не хуже, чем тот чепрак, что я собственноручно смастерил для лорда Тенелома, когда он отправлялся за своим конём." }, { 15.79, "Благодарю тебя за доверие." }, { 17.68, "Несомненно, и сам Грейсон захочет полюбоваться на мою работу." }, { 21.97, "Покажи ему чепрак и передай мою искреннюю благодарность за его достойные дела." } } }, t = { d = 26.7, v = "human-male", n = { x = 313 }, c = { x = { { 0.00, "Великолепная работа!" }, { 1.46, "С возрастом мастерство Гриманда растёт." }, { 4.18, "А его изделия были одними из лучших ещё в те времена, когда он делал чепрак для моего коня!" }, { 10.71, "Этот чепрак слишком хорош для обычного скакуна, но нам предстоит иметь дело с необычным животным." }, { 17.61, "Тебе предстоит оседлать паладинского коня, и поэтому для чепрака нужно получить особое благословение." }, { 24.77, "А пока я сохраню его у себя." } } } } },
    [7649] = { d = 2.8, v = "narrator", n = { x = 25 }, c = { x = { { 0.00, "Том помечен печатью Читальни." } } }, t = { d = 10.7, g = 1, v = "nightelf-male#54", n = { m = 95, f = 95 }, c = { m = { { 0.00, "Молодец, мой мальчик!" }, { 2.48, "*Сказитель Лидрос выдирает из книги одну страницу.*" }, { 6.96, "Вот, этот чертёж тебе наверняка пригодится!" } }, f = { { 0.00, "Молодец, моя девочка!" }, { 2.64, "*Сказитель Лидрос выдирает из книги одну страницу.*" }, { 7.04, "Вот, этот чертёж тебе наверняка пригодится!" } } } } },
