    [7651] = { d = 2.8, v = "narrator", n = { x = 25 }, c = { x = { { 0.00, "Том помечен печатью Читальни." } } }, t = { d = 10.3, g = 1, v = "nightelf-male#54", n = { m = 95, f = 95 }, c = { m = { { 0.00, "Молодец, мой мальчик!" }, { 2.40, "*Сказитель Лидрос выдирает из книги одну страницу.*" }, { 6.64, "Вот, этот чертёж тебе наверняка пригодится!" } }, f = { { 0.00, "Молодец, моя девочка!" }, { 2.48, "*Сказитель Лидрос выдирает из книги одну страницу.*" }, { 6.80, "Вот, этот чертёж тебе наверняка пригодится!" } } } } },
    [7652] = { t = { d = 15.5, g = 1, v = "dwarf-male", n = { m = 170, f = 169 }, c = { m = { { 0.00, "Слышь, приятель, есть для тебя горячее предложение." }, { 3.63, "Хочу сбыть кое-какие чертежи имперских латных доспехов, и мне нужен кто-то, кто возьмёт эту ношу на себя." }, { 11.22, "Взамен прошу всего-то немного ториевых слитков." }, { 14.72, "Идёт?" } }, f = { { 0.00, "Слышь, подруга, есть для тебя горячее предложение." }, { 3.70, "Хочу сбыть кое-какие чертежи имперских латных доспехов, и мне нужен кто-то, кто возьмёт эту ношу на себя." }, { 11.56, "Взамен прошу всего-то немного ториевых слитков." }, { 15.18, "Идёт?" } } } } },
