    [7666] = { t = { d = 15.8, g = 1, v = "human-male", n = { m = 188, f = 190 }, c = { m = { { 0.00, "Снова в Некроситет?" }, { 1.37, "Ты уже заплатил высокую цену за право пользоваться кристальным предсказателем – может, возьмёшь с собой ещё один?" }, { 9.17, "С ним ты снова сможешь бросить вызов опасностям Главного склепа." }, { 13.66, "Конечно, бери." }, { 14.72, "Ты это заслужил." } }, f = { { 0.00, "Снова в Некроситет?" }, { 1.36, "Ты уже заплатила высокую цену за право пользоваться кристальным предсказателем – может, возьмёшь с собой ещё один?" }, { 9.16, "С ним ты снова сможешь бросить вызов опасностям Главного склепа." }, { 13.61, "Конечно, бери." }, { 14.66, "Ты это заслужила." } } } } },
    [7667] = { d = 37.3, v = "tauren-male#68", n = { x = 367 }, c = { x = { { 0.00, "У меня есть срочное дело, и надеюсь, ты сумеешь мне помочь." }, { 4.92, "Разреши, я объясню." }, { 6.56, "В глубине Некроситета в Лордероне есть здание, которое называется Главный склеп." }, { 13.12, "Мне нужно изготовить устройство, которое позволит развеять зловещие тени этого жуткого места." }, { 20.95, "Но чтобы его завершить, мне нужны два алмаза, азеротский и безупречный чёрный." }, { 27.37, "Найти их не так-то просто, я знаю, но самому мне их раздобыть не под силу." }, { 33.48, "Не согласишься ли ты добыть для меня эти камни?" } } }, t = { d = 26.0, v = "tauren-male#68", n = { x = 246 }, c = { x = { { 0.00, "Твоя щедрость не знает границ!" }, { 2.74, "Спасибо тебе." }, { 3.99, "Теперь я смогу изготовить свой кристальный предсказатель, и даже не один." }, { 10.34, "Новые алмазы понадобятся мне нескоро..." }, { 13.78, "Кстати, может быть, один из предсказателей тебе пригодится для чрезвычайно важного дела." }, { 21.46, "Если его не выполнить, миру духов грозит катастрофа!" } } } } },
    [7668] = { d = 35.5, v = "tauren-male#68", n = { x = 371 }, c = { x = { { 0.00, "Рыцарь смерти Тёмный Терзатель владычествует над Главным склепом в Некроситете." }, { 6.32, "Он собирается подчинить себе весь мир духов!" }, { 9.88, "Его необходимо остановить!" }, { 12.06, "Тут-то тебе и понадобится кристальный предсказатель." }, { 16.27, "Приведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Тёмного Терзателя." }, { 23.76, "Когда ты одолеешь этих духов, явится сам рыцарь смерти." }, { 28.33, "Принеси мне его голову!" }, { 30.30, "Только его гибель способна исправить урон, нанесённый миру духов!" } } }, t = { d = 29.2, g = 1, v = "tauren-male#68", n = { m = 268, f = 269 }, c = { m = { { 0.00, "Эту победу стоит смаковать!" }, { 2.51, "Гибель Тёмного Терзателя должна восстановить хрупкие оковы, удерживающие мир духов." }, { 9.71, "Ты сделал куда больше, чем от тебя просили, даже не помышляя о награде." }, { 15.97, "Ты по-настоящему достойный герой, друг мой." }, { 19.65, "Знаю, сохранить мир духов – само по себе награда, но прошу, прими этот скромный дар в знак моей благодарности." } }, f = { { 0.00, "Эту победу стоит смаковать!" }, { 2.49, "Гибель Тёмного Терзателя должна восстановить хрупкие оковы, удерживающие мир духов." }, { 9.66, "Ты сделала куда больше, чем от тебя просили, даже не помышляя о награде." }, { 15.96, "Ты по-настоящему достойная героиня, друг мой." }, { 19.78, "Знаю, сохранить мир духов – само по себе награда, но прошу, прими этот скромный дар в знак моей благодарности." } } } } },
    [7669] = { t = { d = 21.0, g = 1, v = "tauren-male#68", n = { m = 188, f = 190 }, c = { m = { { 0.00, "Снова в Некроситет?" }, { 1.62, "Ты уже заплатил высокую цену за право пользоваться кристальным предсказателем – может, возьмёшь с собой ещё один?" }, { 10.83, "С ним ты снова сможешь бросить вызов опасностям Главного склепа." }, { 16.14, "Конечно, бери." }, { 17.39, "Ты это заслужил." } }, f = { { 0.00, "Снова в Некроситет?" }, { 1.62, "Ты уже заплатила высокую цену за право пользоваться кристальным предсказателем – может, возьмёшь с собой ещё один?" }, { 12.36, "С ним ты снова сможешь бросить вызов опасностям Главного склепа." }, { 17.67, "Конечно, бери." }, { 18.51, "Ты это заслужила." } } } } },
    [7670] = { d = 30.8, g = 1, v = "dwarf-male", n = { m = 344, f = 346 }, c = { m = { { 0.00, "Настала пора, узнать, что потребуется от тебя, дабы получить то, чего ты, несомненно, жаждешь уже давно, а именно... боевого скакуна." }, { 9.77, "Поговори с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда." }, { 14.82, "Он не только наставит тебя в обращении с самым верным товарищем паладина, но и даст тебе задачу, прежде чем ты получишь своего собственного скакуна." }, { 25.57, "Желаю тебе успешно пройти это испытание." }, { 28.65, "Во имя Света, благородный брат!" } }, f = { { 0.00, "Настала пора, узнать, что потребуется от тебя, дабы получить то, чего ты, несомненно, жаждешь уже давно, а именно... боевого скакуна." }, { 9.68, "Поговори с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда." }, { 14.69, "Он не только наставит тебя в обращении с самым верным товарищем паладина, но и даст тебе задачу, прежде чем ты получишь своего собственного скакуна." }, { 25.34, "Желаю тебе успешно пройти это испытание." }, { 28.40, "Во имя Света, благородная сестра!" } } }, t = { d = 33.5, g = 1, v = "human-male", n = { m = 390, f = 391 }, c = { m = { { 0.00, "Рад видеть тебя." }, { 1.21, "Я знаю, что ты ждал от меня наставлений, как добыть себе скакуна, и теперь час настал." }, { 7.25, "Тебе, несомненно, придётся подвергаться разным испытаниям, но самое важное – испытание твоей готовности идти вперёд вопреки любым препятствиям, что станут у тебя на пути." }, { 19.22, "Это не учебные упражнения – твоя стать уже не для простых учебных испытаний." }, { 24.63, "Тебе придётся спасти твоего будущего товарища из лап зла, с которым тебе предстоит сражаться всю жизнь." }, { 31.82, "Внемли же, твой час пришёл!" } }, f = { { 0.00, "Рад видеть тебя." }, { 1.20, "Я знаю, что ты ждала от меня наставлений, как добыть себе скакуна, и теперь час настал." }, { 7.32, "Тебе, несомненно, придётся подвергаться разным испытаниям, но самое важное – испытание твоей готовности идти вперёд вопреки любым препятствиям, что станут у тебя на пути." }, { 19.18, "Это не учебные упражнения – твоя стать уже не для простых учебных испытаний." }, { 24.54, "Тебе придётся спасти твоего будущего товарища из лап зла, с которым тебе предстоит сражаться всю жизнь." }, { 31.67, "Внемли же, твой час пришёл!" } } } } },
    [7701] = { d = 21.4, v = "narrator", n = { x = 255 }, c = { x = { { 0.00, "Именем его светлости надзирателя Скользорука должно убить агента Братства Тория надзирателя Мальториуса, командира подразделения Шлаковой Ямы войск Чёрного Железа в Котле." }, { 12.50, "Его голову должно принести в качестве доказательства содеянного." }, { 17.23, "За наградой обращаться к дозорному капитану Лоло Долгобою." } } }, t = { d = 12.3, g = 1, v = "dwarf-male", n = { m = 118, f = 119 }, c = { m = { { 0.00, "Не думал я, что ещё раз увижу эту мерзкую рожу!" }, { 3.61, "Надо признать, выглядит он получше, после того как ты отрезал всё лишнее." }, { 9.88, "Вот, держи свою награду." } }, f = { { 0.00, "Не думал я, что ещё раз увижу эту мерзкую рожу!" }, { 3.59, "Надо признать, выглядит он получше, после того как ты отрезала всё лишнее." }, { 9.89, "Вот, держи свою награду." } } } } },
    [7703] = { d = 45.7, v = "creature/ogre", n = { x = 463 }, c = { x = { { 0.00, "Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а?" }, { 10.13, "Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спёр его у одного из королей!" }, { 23.38, "А вещица-то была ценная: латная рукавица Мощи Гордока!" }, { 27.77, "И в старых байках говорится, что воротить её сможет только настоящий король Гордок." }, { 34.36, "А ещё говорится, что паскудный эльф до сих пор шляется где-то тут." }, { 39.38, "Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!" } } }, t = { d = 43.0, v = "creature/ogre", n = { x = 397 }, c = { x = { { 0.00, "Ух ты!!!" }, { 0.69, "Да ты и впрямь настоящий король!" }, { 3.37, "Я и не думал, что мне доведётся своими глазами увидеть эту вещь!.." }, { 8.88, "Только чё-то она выглядит, как будто колдунства в ней не осталось..." }, { 14.63, "Может, тот паскудный эльф её испортил?" }, { 17.84, "Да и плевал я на этого эльфа!" }, { 20.37, "Слышь, видишь эту метку на рукавице?" }, { 23.51, "Это старая-престарая метка, постарше всех королей Гордоков, говорят." }, { 29.41, "Ну, нас, капитанов Гордоков, всех учат тому, как эту метку обновить, и вернуть рукавице силу!" }, { 37.37, "И я сделаю это для тебя, король!" }, { 40.21, "Вот, бери рукавицу и правь вовеки!" } } } } },
    [7704] = { d = 17.0, v = "narrator", n = { x = 159 }, c = { x = { { 0.00, "Ну и ну..." }, { 0.86, "Вот так сюрприз!" }, { 2.26, "У горничной была огромная вышитая подушка, и вот теперь она в ваших руках." }, { 8.79, "Эвонис Сажекурка непременно захочет заполучить её." }, { 13.15, "Посмотрим, что она сможет предложить взамен..." } } }, t = { d = 11.0, v = "dwarf-female", n = { x = 114 }, c = { x = { { 0.00, "На такую удачу я даже и не рассчитывала!" }, { 3.25, "Магическая подушка горничной теперь моя!" }, { 6.57, "Можешь не сомневаться, ты получишь свою награду за труды!" } } } } },
    [7721] = { d = 36.2, g = 1, v = "goblin-male#109", n = { m = 400, f = 401 }, c = { m = { { 0.00, "Если я поступлю вопреки доводам разума, и всё же буду по-прежнему содержать инженерную мастерскую на Забытом берегу, мне нужно будет как-то разобраться с этими зловредными элементалями." }, { 14.13, "Чтоб им провалиться, этим необузданным стихиям!" }, { 17.71, "Но как повезло мне – а теперь и вам, мой уважаемый помощник!" }, { 22.19, "Ведь эти элементали представляют собой идеальный источник энергии для моего ультрасжимателя!" }, { 29.22, "Так что ликвидируйте их, не стесняясь, только, смотрите, не выбрасывайте ядра элементалей воды!" } }, f = { { 0.00, "Если я поступлю вопреки доводам разума, и всё же буду по-прежнему содержать инженерную мастерскую на Забытом берегу, мне нужно будет как-то разобраться с этими зловредными элементалями." }, { 13.64, "Чтоб им провалиться, этим необузданным стихиям!" }, { 17.10, "Но как повезло мне – а теперь и вам, моя уважаемая помощница!" }, { 21.56, "Ведь эти элементали представляют собой идеальный источник энергии для моего ультрасжимателя!" }, { 28.35, "Так что ликвидируйте их, не стесняясь, только, смотрите, не выбрасывайте ядра элементалей воды!" } } }, t = { d = 29.5, v = "goblin-male#109", n = { x = 309 }, c = { x = { { 0.00, "Супер-пупер-превосходнейше!" }, { 2.04, "Да, этих ядер мне хватит надолго..." }, { 4.85, "И мало того: теперь на побережье станет поменьше этих элементалей, и мне не придётся по ночам рыдать в подушку оттого, что я выбрал для своей мастерской худшее место в мире!" }, { 18.35, "Спасибо вам, за все ваши труды." }, { 20.81, "Конечно, это создаст мне некоторые финансовые проблемы, но тем не менее я не могу не отблагодарить вас материально!" } } } } },
    [7722] = { d = 23.1, v = "dwarf-male", n = { x = 265 }, c = { x = { { 0.00, "Когда этот негодяй Мальториус покинул клан, он унёс с собой кое-что поважнее безупречнейшего чародейского кристалла." }, { 8.44, "Он украл рецепт огненного плавня!" }, { 10.94, "Полагаю, это была его возможность выслужиться у дворфов Чёрного Железа." }, { 16.21, "Верни нам эти секретные документы." }, { 18.78, "Мальториус наверняка держит их при себе, там, в Шлаковой Яме." } } }, t = { d = 10.0, v = "dwarf-male", n = { x = 105 }, c = { x = { { 0.00, "Надеюсь, вместе с документами ты вытряс из него его подлую душонку!" }, { 5.32, "Рагнаросу ведомо, он этого заслужил!" }, { 8.19, "Теперь приступим к делу." } } } } },
    [7723] = { d = 21.6, v = "dwarf-male", n = { x = 256 }, c = { x = { { 0.00, "К несчастью, я уже не способен на столь меткие удары, как раньше, из-за проблем с пальцами." }, { 6.35, "Виноват климат и низкое атмосферное давление – пальцы здесь отекают и становятся похожими на телсамарские кровяные колбаски..." }, { 15.08, "Так что придётся тебе поработать за меня: вышиби дух из боевых големов, которых найдёшь в ущелье." } } }, t = { d = 3.8, g = 1, v = "dwarf-male", n = { m = 34, f = 35 }, c = { m = { { 0.00, "Молодец, парень!" }, { 1.46, "Вот тебе подарок за труды." } }, f = { { 0.00, "Молодец, девушка!" }, { 1.57, "Вот тебе подарок за труды." } } } } },
    [7724] = { d = 24.1, v = "dwarf-male", n = { x = 282 }, c = { x = { { 0.00, "Как только старый Хансел собирается отдохнуть, нелёгкая подбрасывает ему ещё работёнки..." }, { 6.17, "Вот, пожалуйста, теперь большие лавовые пауки добавили проблем!" }, { 10.68, "Скользорук говорит, его храбрецы чуть ли не из пушек от них отстреливались..." }, { 16.02, "Короче, чтобы зря не пугать детишек и наших доблестных вояк, надо бы найти на пауков управу." }, { 22.63, "Уверен, ты справишься." } } }, t = { d = 5.0, v = "dwarf-male", n = { x = 44 }, c = { x = { { 0.00, "Похоже, опять простыл..." }, { 3.42, "Проклятый холод!" } } } } },
    [7725] = { d = 32.2, g = 1, v = "goblin-male#109", n = { m = 335, f = 337 }, c = { m = { { 0.00, "Я знаю, вы уже собирали для меня остатки миниатюризации... но, если вам захочется снова поразвлечься, имейте в виду: мне всегда нужны новые остатки!" }, { 11.85, "Разумеется, такого большого вознаграждения, как раньше, я больше предложить не смогу, но зато я всегда буду рад замолвить за вас словечко перед своими друзьями-гоблинами." }, { 25.35, "Поверьте мне, сударь: гоблины к подобным отзывам прислушиваются чрезвычайно внимательно!" } }, f = { { 0.00, "Я знаю, вы уже собирали для меня остатки миниатюризации... но, если вам захочется снова поразвлечься, имейте в виду: мне всегда нужны новые остатки!" }, { 11.56, "Разумеется, такого большого вознаграждения, как раньше, я больше предложить не смогу, но зато я всегда буду рад замолвить за вас словечко перед своими друзьями-гоблинами." }, { 24.73, "Поверьте мне, сударыня: гоблины к подобным отзывам прислушиваются чрезвычайно внимательно!" } } }, t = { d = 28.1, v = "goblin-male#109", n = { x = 300 }, c = { x = { { 0.00, "Это просто фантастика!" }, { 1.82, "Вы снова исполнили мою просьбу, и я вам за это чрезвычайно признателен." }, { 7.36, "Спасибо вам большое!" }, { 8.97, "Наверное, вы привыкли рассчитывать на что-то большее, чем эта монета, но зато будьте уверены, что ваши деяния в помощь мировому гоблинству прогремят на весь картель Хитрая Шестерёнка!" }, { 23.12, "Если вам захочется новых подвигов, пожалуйста, обращайтесь ко мне!" } } } } },
    [7726] = { d = 41.4, v = "goblin-male#109", n = { x = 435 }, c = { x = { { 0.00, "О, вы не прочь снова поработать?" }, { 2.42, "Так героическое собирание кусков слизи, выпавших из тел элементалей, не утолило вашей жажды приключений?" }, { 10.38, "Ну, тогда вы, наверное, не огорчитесь, если я снова дам вам то же самое поручение?" }, { 16.61, "Ладно, шутки в сторону: мне нужны новые ядра элементалей воды." }, { 21.52, "Но имейте в виду: сейчас почти все мои средства уходят на обустройство мастерской, так что награда, возможно, будет не столь велика..." }, { 31.76, "Зато обещаю вам, что расскажу всем своим ближним и дальним знакомым о том, как вы мне помогли!" }, { 38.89, "А у меня масса знакомых в картеле!" } } }, t = { d = 25.5, v = "goblin-male#109", n = { x = 268 }, c = { x = { { 0.00, "Высший класс, просто высший класс!" }, { 2.67, "Конечно, деньги, которые вы получите – не самая крупная награда за подобную работу, зато можете быть уверены: мои коллеги из картеля Хитрая Шестерёнка будут осведомлены о ваших подвигах!" }, { 17.18, "Если будете искать новую работу, дайте мне знать." }, { 21.11, "Мне всегда нужны новые ядра элементалей, и тому подобное." } } } } },
    [7727] = { d = 40.7, g = 1, v = "dwarf-male", n = { m = 457, f = 450 }, c = { m = { { 0.00, "Бедные мои ножки..." }, { 1.49, "У меня бурсит, молодой человек." }, { 3.83, "Да, большие шишки всегда наживают себе шишки." }, { 7.21, "Ну и как мне заниматься истреблением всяких тварей, если пальцы моих ног в таком плачевном состоянии?" }, { 14.49, "В общем, тут-то ты мне и поможешь!" }, { 16.96, "Скрендж и Гориврат хотят, чтобы я поубивал этих проклятых ящеров, чтобы расчистить путь для их исследовательских отрядов." }, { 25.60, "Они, вишь ты, желают изучать озёра лавы в Шлаковой Яме." }, { 29.63, "А всякие пламезавры и прочие завры им, вишь ты, мешают." }, { 33.59, "В общем, придётся тебе направиться в Шлаковую Яму и слегка ускорить процесс вымирания этих монстров." } }, f = { { 0.00, "Бедные мои ножки..." }, { 1.51, "У меня бурсит, милочка." }, { 3.28, "Да, большие шишки всегда наживают себе шишки." }, { 6.70, "Ну и как мне заниматься истреблением всяких тварей, если пальцы моих ног в таком плачевном состоянии?" }, { 14.05, "В общем, тут-то ты мне и поможешь!" }, { 16.54, "Скрендж и Гориврат хотят, чтобы я поубивал этих проклятых ящеров, чтобы расчистить путь для их исследовательских отрядов." }, { 25.28, "Они, вишь ты, желают изучать озёра лавы в Шлаковой Яме." }, { 29.35, "А всякие пламезавры и прочие завры им, вишь ты, мешают." }, { 33.35, "В общем, придётся тебе направиться в Шлаковую Яму и слегка ускорить процесс вымирания этих монстров." } } }, t = { d = 5.2, v = "dwarf-male", n = { x = 33 }, c = { x = { { 0.00, "Ох, болят мои ножки..." }, { 2.54, "Ладно, раз уж нет пемзы..." } } } } },
    [7728] = { d = 33.7, v = "narrator", n = { x = 365 }, c = { x = { { 0.00, "Внимание, украдены следующие предметы:" }, { 3.02, "Фурма Чёрного Железа – одна штука." }, { 5.77, "Подзорная труба наблюдателя – одна штука." }, { 9.07, "Просьба вернуть за вознаграждение." }, { 11.75, "Братство Тория точно знает, что эти предметы были украдены беспринципными и завистливыми дворфами Чёрного Железа из Тлеющего ущелья." }, { 22.08, "Подзорная труба была великолепным прибором для наблюдения, а фурма – просто незаменимый инструмент." }, { 29.82, "Нашедшему просьба вернуть указанные вещи Скренджу." } } }, t = { d = 4.6, v = "dwarf-male", n = { x = 36 }, c = { x = { { 0.00, "Ух ты!" }, { 0.62, "Тебе удалось!" }, { 2.05, "Вот, получай свою награду." } } } } },
    [7729] = { d = 33.1, v = "narrator", n = { x = 390 }, c = { x = { { 0.00, "Надсмотрщику Скренджу требуется опытный кандидат на должность устранителя конкурентов в Тлеющем ущелье." }, { 7.57, "Пол неважен." }, { 8.50, "Если вы считаете, что ваша квалификация достаточна для этой должности, отправляйтесь в Тлеющее ущелье и уничтожьте всех встреченных вами надсмотрщиков Чёрного Железа и работорговцев Чёрного Железа." }, { 22.78, "Возвращайтесь к надсмотрщику Скренджу, когда ваша одежда пропитается кровью." }, { 28.42, "Сами поймёте, когда настанет момент, так что вопросов не задавать." } } }, t = { d = 8.6, g = 1, v = "dwarf-male", n = { x = 78 }, c = { m = { { 0.00, "Пятнадцать и девять десятых фунта кишок и крови на одну одёжку!" }, { 5.19, "Да это почти рекорд!" }, { 6.94, "Поздравляю, герой!" } }, f = { { 0.00, "Пятнадцать и девять десятых фунта кишок и крови на одну одёжку!" }, { 5.24, "Да это почти рекорд!" }, { 7.02, "Поздравляю, героиня!" } } } } },
    [7730] = { d = 45.0, v = "tauren-male", n = { x = 423 }, c = { x = { { 0.00, "Судя по сведениям, полученным с помощью разведки, враги, теснящие гноллов с юга, – это раса насекомоподобных существ." }, { 9.82, "Неизвестно, разумны ли они – но, откровенно говоря, это и неважно." }, { 15.37, "Если гноллы их так боятся, что предпочитают переть на нас, значит, эти твари так же опасны, как гноллы, а может, и ещё опаснее." }, { 25.86, "Проникни в те места, где обитают эти насекомые, Цуккаш." }, { 30.51, "Это место называется \"Гудящая Бездна\"." }, { 33.81, "Постарайся уменьшить их численность, и доложи мне о том, что увидишь." }, { 39.43, "В доказательство своих свершений принеси мне их панцири!" } } }, t = { d = 33.1, g = 1, v = "tauren-male", n = { x = 311 }, c = { m = { { 0.00, "Молодец, герой!" }, { 1.37, "Конечно, отпугнуть этих насекомых тебе не удалось – их не проймёшь ничем, кроме полномасштабной военной кампании." }, { 10.91, "Однако с твоей помощью мы сумеем выиграть время, чтобы разработать должную стратегию." }, { 18.23, "Я велю изучить эти панцири – нам нужно узнать об этих тварях как можно больше, прежде чем бороться с тем, что оказалось куда более сложной задачей, нежели мы предполагали." } }, f = { { 0.00, "Молодец, героиня!" }, { 1.54, "Конечно, отпугнуть этих насекомых тебе не удалось – их не проймёшь ничем, кроме полномасштабной военной кампании." }, { 11.17, "Однако с твоей помощью мы сумеем выиграть время, чтобы разработать должную стратегию." }, { 18.56, "Я велю изучить эти панцири – нам нужно узнать об этих тварях как можно больше, прежде чем бороться с тем, что оказалось куда более сложной задачей, нежели мы предполагали." } } } } },
    [7731] = { d = 36.1, v = "tauren-male", n = { x = 371 }, c = { x = { { 0.00, "Один из разведчиков, исследовавших Гудящую Бездну, доложил о виденном им гигантском насекомом – куда более крупном, чем все остальные замеченные им насекомые." }, { 12.63, "Помимо необычных размеров, оно, по-видимому, окружено какой-то особой аурой, которой у прочих насекомых нет." }, { 21.42, "Мы назвали его жалохвостом." }, { 23.67, "Нам хотелось бы изучить внутренности этой твари, чтобы понять, как лучше бороться с этой новой угрозой." }, { 32.09, "Добудь ядовитые железы жалохвоста и принеси их мне!" } } }, t = { d = 32.2, v = "tauren-male", n = { x = 293 }, c = { x = { { 0.00, "Впечатляет... весьма впечатляет!" }, { 2.94, "Если жалохвост – действительно одна из самых опасных их тварей, со временем изучение этого существа окажется весьма ценным!" }, { 14.20, "Ну, а теперь моя задача – позаботиться, чтобы мы выстояли достаточно долго, чтобы суметь воспользоваться полученными знаниями!" }, { 25.63, "Вот, пожалуйста, прими эту монету." }, { 28.81, "Весь лагерь благодарит тебя за отвагу!" } } } } },
    [7732] = { d = 36.0, v = "tauren-male", n = { x = 360 }, c = { x = { { 0.00, "Ты поступаешь весьма разумно, направляя свои усилия на борьбу с этими насекомыми, грозящими Лагерю Мохаче." }, { 8.89, "Опасность далеко ещё не миновала, и мне хотелось бы попросить тебя о ещё одной услуге." }, { 15.98, "Вот в этих бумагах изложены все сведения об улье Цуккаш, которые нам удалось раздобыть." }, { 23.23, "Прошу тебя доставить их Зилзибину Барабанному Бою на Волок в Оргриммаре." }, { 29.28, "Он специалист по подобным созданиям; надеюсь, добытые нами знания ему пригодятся." } } }, t = { d = 45.6, v = "troll-male#77", n = { x = 455 }, c = { x = { { 0.00, "А-а, я давно ждал подобных вестей..." }, { 2.94, "Эти твари, с которыми тебе довелось столкнуться – древняя угроза, которую Орда предпочитает игнорировать." }, { 11.42, "Хадокен поступил мудро, что отправил этот доклад – и тебя с ним, – ко мне." }, { 17.31, "Цуккаш – это те самые создания, которых именуют силитидами." }, { 22.12, "Многим кажется, будто это просто неразумные твари, но позволь тебя заверить: они значительно, значительно опаснее, чем любая угроза со стороны Альянса!" }, { 34.33, "И мне бы очень пригодилась твоя помощь в том, чтобы подробнее узнать об этой напасти – если у тебя, конечно, хватит сил и желания мне помогать." } } } } },
    [7733] = { d = 27.1, v = "human-male", n = { x = 311 }, c = { x = { { 0.00, "Я знаю, где можно добыть шкуры ещё лучше этих – хотя в это и трудно поверить!" }, { 5.52, "На севере Фераласа, в глубине Пещеры Бешеного оврага, обитает другая стая йети." }, { 11.16, "Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует!" }, { 21.18, "А я хорошо вознагражу тебя за десяток шкур таких йети." }, { 25.01, "Принеси их мне, и мы договоримся." } } }, t = { d = 15.7, v = "human-male", n = { x = 168 }, c = { x = { { 0.00, "Отлично, отлично!" }, { 1.36, "Они подойдут мне как нельзя лучше – я уже вижу, что после надлежащей обработки они сделаются гораздо прочнее." }, { 9.71, "Ещё раз спасибо за помощь!" }, { 11.68, "Вот, пожалуйста: прими одно из моих последних изделий." } } } } },
    [7734] = { d = 33.9, v = "tauren-male#132", n = { x = 311 }, c = { x = { { 0.00, "Я знаю, где можно добыть шкуры ещё лучше этих – хотя в это и трудно поверить!" }, { 6.88, "На севере Фераласа – в глубине Пещеры Бешеного оврага, обитает другая стая йети." }, { 13.99, "Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует!" }, { 26.50, "А я хорошо вознагражу тебя за десяток шкур таких йети." }, { 31.26, "Принеси их мне, и мы договоримся." } } }, t = { d = 20.2, v = "tauren-male#132", n = { x = 168 }, c = { x = { { 0.00, "Отлично, отлично!" }, { 1.75, "Они подойдут мне как нельзя лучше – я уже вижу, что после надлежащей обработки они сделаются гораздо прочнее." }, { 12.52, "Ещё раз спасибо за помощь!" }, { 15.06, "Вот, пожалуйста: прими одно из моих последних изделий." } } } } },
    [7735] = { d = 19.2, v = "narrator", n = { x = 195 }, c = { x = { { 0.00, "Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети из Пещеры Бешеного оврага." }, { 9.20, "Вам известно, что Пратту Макгруббену из Крепости Оперённой Луны всегда нужны шкуры йети, а уж эта его тем более заинтересует!" } } }, t = { d = 19.8, g = 1, v = "human-male", n = { m = 199, f = 201 }, c = { m = { { 0.00, "Невероятно!" }, { 0.91, "Да это, можно сказать, царица всех шкур йети!" }, { 4.48, "Да уж, конечно, за такую шкуру я и заплачу по-царски!" }, { 8.60, "Обычно за одну-единственную шкуру я дорого не даю, но из этой шкуры я наверняка сумею изготовить нечто особенное." }, { 17.48, "Спасибо, что принёс её мне!" } }, f = { { 0.00, "Невероятно!" }, { 0.92, "Да это, можно сказать, царица всех шкур йети!" }, { 4.52, "Да уж, конечно, за такую шкуру я и заплачу по-царски!" }, { 8.68, "Обычно за одну-единственную шкуру я дорого не даю, но из этой шкуры я наверняка сумею изготовить нечто особенное." }, { 17.65, "Спасибо, что принесла её мне!" } } } } },
    [7736] = { t = { d = 7.4, v = "dwarf-male", n = { x = 77 }, c = { x = { { 0.00, "Плавень в кузне лишним не бывает, поверь моему слову..." }, { 4.19, "Неси сколько можешь, пока не скажу – хватит." } } } } },
    [7737] = { t = { d = 2.1, v = "dwarf-male", n = { x = 19 }, c = { x = { { 0.00, "Так, давай сюда окалину!" } } } } },
    [7738] = { d = 19.6, v = "narrator", n = { x = 194 }, c = { x = { { 0.00, "Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети из Пещеры Бешеного оврага." }, { 9.39, "Вам известно, что Джангору Быстрому Страннику из Лагеря Мохаче всегда нужны шкуры йети, а уж эта его тем более заинтересует!" } } }, t = { d = 27.6, g = 1, v = "tauren-male#132", n = { m = 229, f = 231 }, c = { m = { { 0.00, "Невероятно!" }, { 1.14, "Это, пожалуй, лучший образчик шкуры йети, какой я когда-либо видел!" }, { 7.88, "Да уж, конечно, за такую шкуру следует заплатить по достоинству!" }, { 14.10, "Обычно за одну-единственную шкуру я дорого не даю, но из этой шкуры я наверняка сумею изготовить нечто особенное." }, { 25.23, "Спасибо, что принёс её мне!" } }, f = { { 0.00, "Невероятно!" }, { 1.13, "Это, пожалуй, лучший образчик шкуры йети, какой я когда-либо видел!" }, { 7.81, "Да уж, конечно, за такую шкуру следует заплатить по достоинству!" }, { 13.97, "Обычно за одну-единственную шкуру я дорого не даю, но из этой шкуры я наверняка сумею изготовить нечто особенное." }, { 24.99, "Спасибо, что принесла её мне!" } } } } },
    [7761] = { d = 46.4, v = "narrator", n = { x = 472 }, c = { x = { { 0.00, "Недоумок," }, { 0.81, "Как-то мне очень сомнительно, что ты сумеешь сдержать чужаков и не дать им проникнуть в убежище повелителя." }, { 9.37, "В случае твоей смерти, – а подобный исход более чем вероятен, – у этой сферы есть свой собственный механизм защиты, который не даст чужакам перенестись напрямую в Крыло Тьмы." }, { 23.42, "Сферой сможет воспользоваться только тот, кто отмечен меткой Драккисата." }, { 29.28, "К счастью, Драккисат, в отличие от некоторых \"интендантов\", далеко не дурак и хорошо разбирается в своём деле." }, { 38.14, "Он самолично охраняет клеймо!" }, { 40.55, "С уважением, вождь Ренд Чернорук" }, { 43.11, "Постскриптум: уничтожь это письмо, идиот!" } } }, t = { d = 16.5, v = "narrator", n = { x = 155 }, c = { x = { { 0.00, "Раскалённое клеймо прожигает вам руку, но вы даже не морщитесь." }, { 5.44, "Вы сильны и крепки духом!" }, { 7.73, "Теперь у вас есть метка Драккисата." }, { 10.80, "Самое время устроить потеху и разнести этот замок ко всем чертям!" } } } } },
    [7781] = { d = 13.8, v = "narrator", n = { x = 137 }, c = { x = { { 0.00, "Знакомое чувство ликования охватывает вас: победа!!!" }, { 4.41, "Перед вами лежит гигантская, покрытая боевыми шрамами голова Нефариана." }, { 10.57, "Отнесите же её своему верховному лорду!" } } }, t = { d = 10.7, v = "creature/bolvar", n = { x = 99 }, c = { x = { { 0.00, "Вы понимаете значение этой победы?" }, { 3.22, "Ваш подвиг войдёт в историю Штормграда!" }, { 6.76, "Подобного успеха Альянс не знал многие годы!" } } } } },
    [7782] = { d = 4.9, v = "creature/bolvar", n = { x = 59 }, c = { x = { { 0.00, "Отправляйтесь в Аллею Героев и поговорите с фельдмаршалом Афрасиаби." } } }, t = { d = 7.3, v = "human-female#45", n = { x = 73 }, c = { x = { { 0.00, "*Фельдмаршал Афрасиаби кланяется вам.*" }, { 3.20, "Выбирайте награду, и пусть начнётся празднество!" } } } } },
    [7783] = { d = 14.2, g = 1, v = "narrator", n = { m = 133, f = 137 }, c = { m = { { 0.00, "Ты вновь испытываешь знакомое чувство – сладость победы!" }, { 4.82, "У твоих ног лежит массивная, покрытая боевыми шрамами голова Нефариана." }, { 11.04, "Отнеси её своему вождю, воитель!" } }, f = { { 0.00, "Ты вновь испытываешь знакомое чувство – сладость победы!" }, { 4.85, "У твоих ног лежит массивная, покрытая боевыми шрамами голова Нефариана." }, { 11.11, "Отнеси её своему вождю, воительница!" } } }, t = { d = 9.3, g = 1, v = "named/thrall", n = { m = 76, f = 78 }, c = { m = { { 0.00, "Ты снова принёс Орде славу!" }, { 2.75, "Сын Смертокрыла мёртв." }, { 4.88, "Наверняка теперь пробудится и сам злодей." } }, f = { { 0.00, "Ты снова принесла Орде славу!" }, { 3.09, "Сын Смертокрыла мёртв." }, { 5.27, "Наверняка теперь пробудится и сам злодей." } } } } },
    [7784] = { d = 4.6, v = "named/thrall", n = { x = 44 }, c = { x = { { 0.00, "Найдите верховного воеводу Саурфанга на аллее Силы." } } }, t = { d = 8.0, v = "creature/saurfang", n = { x = 67 }, c = { x = { { 0.00, "Выбери себе награду, и я установлю голову этой твари так, чтобы её могли видеть все!" } } } } },
    [7785] = { d = 5.4, v = "human-male", n = { x = 55 }, c = { x = { { 0.00, "Изучи Сосуд Возрождения, смертный." }, { 2.99, "Из него возродится Ветроносец!" } } }, t = { d = 5.1, v = "human-male", n = { x = 61 }, c = { x = { { 0.00, "Пусть поход твой увенчается успехом." }, { 2.67, "Да благословит тебя мой повелитель." } } } } },
    [7786] = { d = 11.9, v = "human-male", n = { x = 148 }, c = { x = { { 0.00, "Я рассказал тебе всё, что знаю." }, { 2.16, "Именно тебе предстоит отыскать элементий и уничтожить воплощение Повелителя огня." }, { 7.79, "Если ты справишься, с тобой пребудет благословение Громораана." } } }, t = { d = 14.7, v = "human-male", n = { x = 132 }, c = { x = { { 0.00, "Даже во сне я не чаял увидеть этот день." }, { 3.52, "Зри же, смертный." }, { 5.01, "УЗРИ ТОГО, КТО СТАРШЕ СУЩЕГО!" }, { 7.67, "УЗРИ ТОГО, КТО СРАЖАЛСЯ С ТИТАНОМ И БОГОМ!" }, { 11.43, "ВОССТАНЬ, МОЙ ПОВЕЛИТЕЛЬ!" }, { 13.63, "ОТРИНЬ ОКОВЫ!" } } } } },
    [7787] = { d = 14.1, g = 1, v = "narrator", n = { m = 159, f = 160 }, c = { m = { { 0.00, "Ты одолел Ветроносца." }, { 1.63, "Отнеси этой лживой предательской скотине, Демитриану, дремлющий клинок и заставь его воспользоваться предоставленными ему материалами и пробудить Громовую ярость." } }, f = { { 0.00, "Ты одолела Ветроносца." }, { 1.74, "Отнеси этой лживой предательской скотине, Демитриану, дремлющий клинок и заставь его воспользоваться предоставленными ему материалами и пробудить Громовую ярость." } } }, t = { d = 8.3, v = "human-male", n = { x = 98 }, c = { x = { { 0.00, "Прошу, не трогай меня!" }, { 1.63, "Возьми, что тебе нужно!" }, { 3.32, "Возьми клинок!" }, { 4.39, "Позволь Демитриану собирать осколки своей никчёмной жизни." } } } } },
    [7788] = { d = 27.9, g = 1, v = "nightelf-female#51", n = { m = 311, f = 311 }, c = { m = { { 0.00, "Юный герой!" }, { 0.92, "Миновав этот проход, ты увидишь поле яростных сражений." }, { 5.06, "Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину!" }, { 13.14, "Отправляйся в Ущелье Песни Войны, чтобы оборонять Крепость Среброкрылых!" }, { 18.47, "Отражай нападения ордынских захватчиков!" }, { 21.42, "Наградой тебе будет талисман заслуг." }, { 24.18, "Принеси мне такой талисман, и получишь награду!" } }, f = { { 0.00, "Юная героиня!" }, { 1.06, "Миновав этот проход, ты увидишь поле яростных сражений." }, { 5.24, "Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину!" }, { 13.40, "Отправляйся в Ущелье Песни Войны, чтобы оборонять Крепость Среброкрылых!" }, { 18.78, "Отражай нападения ордынских захватчиков!" }, { 21.76, "Наградой тебе будет талисман заслуг." }, { 24.55, "Принеси мне такой талисман, и получишь награду!" } } } },
    [7789] = { d = 37.6, g = 1, v = "orc-male", n = { x = 364 }, c = { m = { { 0.00, "Чащобы Ясеневого леса падут пред мощью Орды, герой!" }, { 4.46, "Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором." }, { 10.37, "Калимдор – это владения Орды!" }, { 12.94, "Как смеют они препятствовать нам пользоваться тем, что по праву наше?" }, { 18.69, "Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду!" }, { 27.39, "Разгроми Среброкрылых Часовых и заслужи почётный знак Ущелья Песни Войны." }, { 33.52, "Вернись ко мне с этим знаком – и получишь награду!" } }, f = { { 0.00, "Чащобы Ясеневого леса падут пред мощью Орды, героиня!" }, { 4.49, "Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором." }, { 10.23, "Калимдор – это владения Орды!" }, { 12.73, "Как смеют они препятствовать нам пользоваться тем, что по праву наше?" }, { 18.33, "Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду!" }, { 26.79, "Разгроми Среброкрылых Часовых и заслужи почётный знак Ущелья Песни Войны." }, { 32.75, "Вернись ко мне с этим знаком – и получишь награду!" } } }, t = { d = 15.0, g = 1, v = "orc-male", n = { x = 127 }, c = { m = { { 0.00, "И сколько ещё они смогут так продержаться?" }, { 4.83, "Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать?" }, { 11.43, "Время покажет, путник, время покажет..." } }, f = { { 0.00, "И сколько ещё они смогут так продержаться?" }, { 4.96, "Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать?" }, { 11.75, "Время покажет, путница, время покажет..." } } } } },
