    [7794] = { t = { d = 4.9, g = 1, v = "human-male", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 0.90, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 0.90, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7795] = { t = { d = 22.8, v = "human-male", n = { x = 271 }, c = { x = { { 0.00, "Невероятно!" }, { 0.81, "Ткань сразу пойдёт в дело, будьте уверены." }, { 3.75, "Благодарю вас за помощь!" }, { 5.44, "Без вас мы бы точно пропали." }, { 7.38, "Хотя вы и так уже много ткани нам пожертвовали, но если вы вдруг соблаговолите в будущем пожертвовать ещё, я найду ей применение." }, { 16.19, "Просто свяжитесь со мной, и я лично позабочусь, чтобы ваши добрые дела не остались незамеченными!" } } } } },
    [7796] = { t = { d = 7.4, v = "human-male", n = { x = 75 }, c = { x = { { 0.00, "Что бы мы делали без героев, щедростью сравнимых с тобой?!" }, { 4.58, "Спасибо за то, что не забываешь о нас!" } } } } },
