    [7800] = { t = { d = 24.6, v = "nightelf-male", n = { x = 271 }, c = { x = { { 0.00, "Невероятно!" }, { 0.88, "Ткань сразу пойдёт в дело, будьте уверены." }, { 4.04, "Благодарю вас за помощь!" }, { 5.86, "Без вас мы бы точно пропали." }, { 7.94, "Хотя вы и так уже много ткани нам пожертвовали, но если вы вдруг соблаговолите в будущем пожертвовать ещё, я найду ей применение." }, { 17.44, "Просто свяжитесь со мной, и я лично позабочусь, чтобы ваши добрые дела не остались незамеченными!" } } } } },
    [7801] = { t = { d = 8.3, v = "nightelf-male", n = { x = 86 }, c = { x = { { 0.00, "Без помощи таких героев, как ты, Дарнассу бы очень тяжело пришлось!" }, { 5.43, "Благодарю тебя за непрестанные труды!" } } } } },
