    [7809] = { t = { d = 5.1, g = 1, v = "gnome-male", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 0.96, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 0.95, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7810] = { d = 9.3, v = "narrator", n = { x = 98 }, c = { x = { { 0.00, "Должно быть, стать мастером арены не так просто!" }, { 3.73, "Быть может, пират-распорядитель на Арене Гурубаши знает, в чём тут штука!" } } }, t = { d = 9.2, v = "goblin-male", n = { x = 96 }, c = { x = { { 0.00, "Арр, дорогуша!" }, { 1.17, "Одной безделушки недостаточно, чтобы стать мастером Арены!" }, { 5.92, "Пришло время проверить тебя на прочность." } } } } },
    [7811] = { t = { d = 22.7, v = "gnome-male", n = { x = 263 }, c = { x = { { 0.00, "Невероятно!" }, { 0.82, "Мы немедля пустим её в дело, будьте уверены." }, { 3.99, "Ещё раз спасибо за помощь!" }, { 5.83, "Без вас мы бы точно пропали." }, { 7.79, "Хотя вы уже и так много пожертвовали ткани, я и в будущем с удовольствием приму от вас любое количество рунной ткани." }, { 16.02, "Просто свяжитесь со мной, и я лично постараюсь, чтобы ваши добрые дела не остались незамеченными!" } } } } },
    [7812] = { t = { d = 9.0, v = "gnome-male", n = { x = 89 }, c = { x = { { 0.00, "О, если бы такие герои, как вы, не помогали нам, гномам, мы бы совсем погибли!" }, { 6.22, "Благодарю вас за непрестанные труды!" } } } } },
    [7813] = { t = { d = 6.6, g = 1, v = "scourge-male", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 1.20, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 1.21, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7814] = { t = { d = 6.4, g = 1, v = "scourge-male", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 1.20, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 1.18, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7815] = { d = 24.5, v = "troll-male#138", n = { x = 240 }, c = { x = { { 0.00, "Ты не смотри, что у них такие большие красивые глазки!" }, { 4.58, "Страшней морского хрустогрыза зверя нет!" }, { 8.01, "Только я удочку закину, как приплывают эти черепахи-переростки, жрут мне всю наживку и удилище пополам ломают!" }, { 17.31, "Сделай мне и всей нашей деревеньке одолжение – поубивай их всех." }, { 22.65, "В смысле, хрустогрызов." } } }, t = { d = 10.6, v = "troll-male#138", n = { x = 70 }, c = { x = { { 0.00, "Ооо!" }, { 0.64, "Вот спасибо, вот помог!" }, { 3.40, "На тебе удочку, надеюсь, поймаешь на неё воооот такую рыбину!" } } } } },
    [7816] = { d = 26.1, v = "troll-male#138", n = { x = 248 }, c = { x = { { 0.00, "Йоу!" }, { 0.47, "Тут живёт всем черепахам черепаха – звать Гаммерита – предводительница всех морских хрустогрызов и просто наглая прожорливая рептилия, чтоб ей." }, { 12.49, "Она сожрала мою лучшую блесну!" }, { 15.31, "Взяла и откусила прямо с удочки!" }, { 18.19, "С тех пор рыба совсем клевать перестала." }, { 21.71, "Найди Гаммериту и вытащи у неё из брюха мою блесну!" } } }, t = { d = 9.4, v = "troll-male#138", n = { x = 67 }, c = { x = { { 0.00, "ЧУВАК!!!" }, { 0.97, "Ну и дела!" }, { 2.14, "Блесна есть, хрустогрызов нет, да я сейчас всю рыбу в море переловлю!" } } } } },
    [7817] = { t = { d = 6.6, g = 1, v = "scourge-male", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 1.20, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 1.22, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7818] = { t = { d = 18.6, v = "scourge-male", n = { x = 165 }, c = { x = { { 0.00, "Потрясающе!" }, { 1.07, "Ткань нам очень пригодится." }, { 3.53, "Ещё раз спасибо за помощь!" }, { 5.91, "Без тебя мы бы просто пропали." }, { 8.70, "Если в будущем у тебя появятся излишки рунной ткани – приноси, пригодится." }, { 15.60, "Твои добрые дела не будут забыты!" } } } } },
    [7819] = { t = { d = 8.3, v = "scourge-male", n = { x = 63 }, c = { x = { { 0.00, "Спасибо!" }, { 0.99, "Что бы мы делали без героев, неустанно пекущихся о благе Отрёкшихся..." } } } } },
