    [7824] = { t = { d = 18.1, v = "orc-female#58", n = { x = 186 }, c = { x = { { 0.00, "Потрясающе!" }, { 0.92, "Эта ткань нам очень пригодится." }, { 3.39, "Ещё раз спасибо за помощь!" }, { 5.44, "Без тебя мы бы просто пропали." }, { 7.84, "Если в будущем у тебя заведётся ещё лишняя рунная ткань, приноси и её, пригодится." }, { 14.20, "Уверяю тебя, твои добрые дела не пропадут втуне!" } } } } },
    [7825] = { t = { d = 12.6, v = "tauren-male", n = { x = 107 }, c = { x = { { 0.00, "О, если бы такие герои, как ты, не помогали Громовому Утёсу, страдания наши были бы нестерпимы!" }, { 9.09, "Благодарю тебя за непрестанные труды!" } } } } },
    [7826] = { t = { d = 5.5, g = 1, v = "orc-female#58", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 1.03, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 1.02, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7827] = { t = { d = 5.6, g = 1, v = "orc-female#58", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 1.02, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 1.03, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7828] = { d = 21.2, g = 1, v = "troll-male#77", n = { x = 214 }, c = { m = { { 0.00, "В диких лесах Внутренних земель погибло много храбрых троллей, герой." }, { 5.76, "Одни из самых опасных животных там – среброгривые волки." }, { 10.35, "Они прячутся в высокой траве и всегда нападают неожиданно." }, { 15.16, "Нельзя закрывать глаза на такую опасность!" }, { 18.66, "Уменьшите поголовье среброгривов!" } }, f = { { 0.00, "В диких лесах Внутренних земель погибло много храбрых троллей, героиня." }, { 5.69, "Одни из самых опасных животных там – среброгривые волки." }, { 10.11, "Они прячутся в высокой траве и всегда нападают неожиданно." }, { 14.74, "Нельзя закрывать глаза на такую опасность!" }, { 18.11, "Уменьшите поголовье среброгривов!" } } }, t = { d = 6.7, g = 1, v = "troll-male#77", n = { x = 55 }, c = { m = { { 0.00, "Прекрасная работа, герой." }, { 2.32, "Благодарю вас от имени клана Сломанного Клыка." } }, f = { { 0.00, "Прекрасная работа, героиня." }, { 2.57, "Благодарю вас от имени клана Сломанного Клыка." } } } } },
    [7829] = { d = 23.0, g = 1, v = "troll-male#77", n = { x = 215 }, c = { m = { { 0.00, "Одни из самых мерзких существ во Внутренних землях – дикие совухи." }, { 5.46, "Сколько храбрых воинов Сломанного Клыка они уже разорвали своими когтями и клювами..." }, { 12.52, "Убейте всех диких совухов, которых встретите, герой." }, { 16.82, "Ваша помощь будет взвешена, измерена и по достоинству оценена." } }, f = { { 0.00, "Одни из самых мерзких существ во Внутренних землях – дикие совухи." }, { 5.72, "Сколько храбрых воинов Сломанного Клыка они уже разорвали своими когтями и клювами..." }, { 13.12, "Убейте всех диких совухов, которых встретите, героиня." }, { 17.78, "Ваша помощь будет взвешена, измерена и по достоинству оценена." } } }, t = { d = 6.7, v = "troll-male#77", n = { x = 58 }, c = { x = { { 0.00, "Вы доказали, что вы – преданный союзник клана Сломанного Клыка." }, { 6.03, "Молодец." } } } } },
    [7830] = { d = 22.2, v = "troll-male#77", n = { x = 243 }, c = { x = { { 0.00, "Мерзавцы из клана Громового Молота учат своих грифонов убивать троллей." }, { 5.51, "Ужасно, конечно, но не беспокойтесь, мы этого так не оставим." }, { 10.07, "Пока что я хочу, чтобы вы уничтожили местных предводителей грифонов." }, { 15.23, "Этих остроклювов зовут ещё повелителями небес." }, { 18.77, "Убейте одного из них и принесите мне его перо." } } }, t = { d = 10.3, v = "troll-male#77", n = { x = 79 }, c = { x = { { 0.00, "*Мархор изучает перо.*" }, { 2.32, "Интересно, сколько наших охотников сожрало это чудовище, прежде чем вы воздали ему по заслугам?" } } } } },
    [7831] = { t = { d = 5.8, g = 1, v = "orc-female#58", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 1.00, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 1.06, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7832] = { t = { d = 9.0, v = "orc-female#58", n = { x = 79 }, c = { x = { { 0.00, "Да, что бы мы делали без таких героев, как ты, неустанно пекущихся о благе Оргриммара!" }, { 7.86, "Спасибо тебе!" } } } } },
    [7833] = { t = { d = 5.4, g = 1, v = "troll-female", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 0.97, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 1.00, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7834] = { t = { d = 5.3, g = 1, v = "troll-female", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 0.97, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 0.96, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7835] = { t = { d = 5.4, g = 1, v = "troll-female", n = { x = 44 }, c = { m = { { 0.00, "Прекрасно!" }, { 1.00, "Путник, благодарим тебя за щедрое пожертвование!" } }, f = { { 0.00, "Прекрасно!" }, { 0.99, "Путница, благодарим тебя за щедрое пожертвование!" } } } } },
    [7836] = { t = { d = 18.5, v = "troll-female", n = { x = 186 }, c = { x = { { 0.00, "Потрясающе!" }, { 0.94, "Эта ткань нам очень пригодится." }, { 3.48, "Ещё раз спасибо за помощь!" }, { 5.58, "Без тебя мы бы просто пропали." }, { 8.05, "Если в будущем у тебя заведётся ещё лишняя рунная ткань, приноси и её, пригодится." }, { 14.57, "Уверяю тебя, твои добрые дела не пропадут втуне!" } } } } },
    [7837] = { t = { d = 9.3, v = "troll-female", n = { x = 88 }, c = { x = { { 0.00, "Да, что бы мы делали без таких героев, как ты, неустанно пекущихся о благе племени Чёрного Копья!" }, { 8.20, "Спасибо тебе!" } } } } },
    [7838] = { t = { d = 8.3, v = "goblin-male", n = { x = 79 }, c = { x = { { 0.00, "Много крови пролито тобою на песок ринга, и я с радостью нарекаю тебя Великим Повелителем Арены!" } } } } },
    [7839] = { d = 33.8, v = "orc-male#127", n = { x = 368 }, c = { x = { { 0.00, "Эти негодяи из клана Порочной Ветви напали на нашу деревню и украли мои инструменты!" }, { 6.38, "У меня, конечно, есть запасные, но тот набор, что они уволокли, был мне дорог как память." }, { 12.90, "Когда я был ещё мальчишкой, мне спас жизнь один гном, а потом он подарил мне тот набор." }, { 19.15, "Я очень хочу вернуть их, я без них как без рук!" }, { 22.55, "Мархор сказал, что мои инструменты видели в храмах Аголвата и Шаол-Вата, они оба на северо-востоке Внутренних земель." }, { 31.33, "Пожалуйста, верните мне инструменты!" } } }, t = { d = 6.4, v = "orc-male#127", n = { x = 43 }, c = { x = { { 0.00, "Мои инструменты!" }, { 1.99, "Вы их нашли!" }, { 3.45, "О, какое счастье!" }, { 5.54, "Спасибо!" } } } } },
    [7840] = { d = 24.6, v = "named/14731", n = { x = 244 }, c = { x = { { 0.00, "Лярд хотел устроить пикник в секретном месте, а потом пришли злые тролли Порочной Ветви и побили Лярда большими палками." }, { 9.95, "Лярд убежал в деревню, но потерял свой обед." }, { 13.53, "Лярд голодный..." }, { 14.85, "Может, сходишь в секретное место и найдёшь там мой обед?" }, { 19.38, "Лярд боится." }, { 20.40, "Это на севере!" }, { 21.65, "Остров на севере, там секретное место!" } } }, t = { d = 14.6, g = 1, v = "named/14731", n = { m = 77, f = 77 }, c = { m = { { 0.00, "*Лярд берёт у вас огромный кусок мяса и начинает жадно его грызть.*" }, { 5.92, "Вот, как хорошо!" }, { 7.33, "Спасибо, мелкий." }, { 8.82, "Лярд даст тебе в подарок эту специальную корзинку для пикника." } }, f = { { 0.00, "*Лярд берёт у вас огромный кусок мяса и начинает жадно его грызть.*" }, { 6.40, "Вот, как хорошо!" }, { 7.81, "Спасибо, мелкая." }, { 9.30, "Лярд даст тебе в подарок эту специальную корзинку для пикника." } } } } },
    [7841] = { d = 20.6, v = "troll-male#139", n = { x = 202 }, c = { x = { { 0.00, "Клан Громового Молота якшается с нашими врагами и заключает с ними союзы." }, { 6.25, "В этот раз они спутались с высшими эльфами." }, { 9.98, "Убейте любого эльфа из Высокодолья, которого только встретите – пусть их тела послужат предупреждением." }, { 18.66, "С троллями шутки плохи!" } } }, t = { d = 7.0, v = "troll-male#139", n = { x = 66 }, c = { x = { { 0.00, "Хе, кажется, тролли Сломанного Клыка не ошиблись с выбором союзников!" }, { 6.09, "Вы молодец." } } } } },
    [7842] = { d = 25.4, v = "troll-male#139", n = { x = 268 }, c = { x = { { 0.00, "Говорят, что дворфы Громового Молота и их грифоны – друзья не разлей вода." }, { 5.90, "Хоть это и не очень красиво, но нужно воспользоваться этим преимуществом." }, { 11.65, "Сделаем им ещё одно предупреждение." }, { 14.43, "Убейте всех грифонов, каких только встретите во Внутренних землях, и соберите длинные элегантные перья!" }, { 22.60, "Из них мы сделаем последнее послание." } } }, t = { d = 8.8, v = "troll-male#139", n = { x = 72 }, c = { x = { { 0.00, "О, друга, хорошо-то как!" }, { 2.35, "Ещё разок, и эти Громовые Молоты узнают, как связываться с троллями!" } } } } },
    [7843] = { d = 25.4, g = 1, v = "troll-male#139", n = { m = 233, f = 233 }, c = { m = { { 0.00, "*Отхо вручает вам длинное окровавленное копьё, обёрнутое перьями грифона*" }, { 6.24, "Вот, берите." }, { 7.39, "Отнесите это на Заоблачный пик, в самый центр тамошнего поселения." }, { 13.41, "Воткните копьё у колодца, пусть эти дворфы знают, что с нами шутки плохи!" }, { 20.16, "А потом возвращайтесь ко мне." }, { 22.80, "Надеюсь ещё увидеть вас живым." } }, f = { { 0.00, "*Отхо вручает вам длинное окровавленное копьё, обёрнутое перьями грифона*" }, { 6.32, "Вот, берите." }, { 7.45, "Отнесите это на Заоблачный пик, в самый центр тамошнего поселения." }, { 13.34, "Воткните копьё у колодца, пусть эти дворфы знают, что с нами шутки плохи!" }, { 19.96, "А потом возвращайтесь ко мне." }, { 22.54, "Надеюсь ещё увидеть вас живой." } } }, t = { d = 15.0, v = "troll-male#139", n = { x = 142 }, c = { x = { { 0.00, "Жалко, меня там не было, вот бы посмотреть на их рожи!" }, { 4.40, "Как они там, друга?" }, { 6.02, "Сумки пакуют, бегут из города?" }, { 8.58, "У тебя отлично всё получилось, правда-правда." }, { 12.33, "Отхо дарит тебе вот этот амулет." } } } } },
    [7844] = { d = 37.8, v = "troll-female#136", n = { x = 380 }, c = { x = { { 0.00, "Во Внутренних землях живёт три клана троллей." }, { 3.67, "На этом, собственно, сходство и заканчивается – мы все тролли и мы все живём здесь." }, { 10.19, "Клан Порочной Ветви, как следует из названия, самый отвратительный – тамошние каннибалы едят и троллей, и вообще всех, кто подвернётся." }, { 20.97, "Если бы Зул'джин был здесь, он бы уничтожил всё это отродье одним движением руки!" }, { 27.57, "Но Зул'джина с нами нет, поэтому приходится справляться самим." }, { 32.63, "Вот вам задание – пойти и убить троллей из клана Порочной Ветви." } } }, t = { d = 5.3, g = 1, v = "troll-female#136", n = { x = 36 }, c = { m = { { 0.00, "Ты молодчина, герой." }, { 2.09, "Сам Зул'джин бы лучше не сделал!" } }, f = { { 0.00, "Ты молодчина, героиня." }, { 2.10, "Сам Зул'джин бы лучше не сделал!" } } } } },
    [7845] = { d = 26.2, v = "troll-female#75", n = { x = 288 }, c = { x = { { 0.00, "Однажды ночью клан Порочной Ветви совершил набег на нашу деревню и похитил моего мужа." }, { 6.60, "Наши разведчики узнали, что он ещё жив и находится в плену на самом верху Джинта'Алора." }, { 13.06, "Они сказали, что коварная жрица Ведьмиса хочет принести его в жертву их безлицему кровавому богу Хаккару." }, { 21.07, "Прошу вас, спасите его!" }, { 22.89, "Наша деревня не переживёт такой тяжёлой потери." } } }, t = { d = 4.6, v = "troll-male#77", n = { x = 48 }, c = { x = { { 0.00, "Действовать нужно быстро." }, { 2.17, "Стражи наверняка вас заметили." } } } } },
    [7846] = { d = 14.2, v = "troll-male#77", n = { x = 146 }, c = { x = { { 0.00, "Ключ от моих кандалов у Хита'йи Хранительницы, она в пещере поблизости." }, { 5.71, "Но будьте осторожны, там полно охраны!" }, { 8.82, "Убейте Хранительницу и возьмите у неё ключ, иначе мне отсюда не выйти." } } }, t = { d = 8.7, v = "troll-male#77", n = { x = 73 }, c = { x = { { 0.00, "Наконец-то, свобода!" }, { 2.09, "Спасибо!" }, { 2.99, "Клан Сломанного Клыка непременно услышит о ваших подвигах." } } } } },
    [7847] = { d = 12.9, v = "troll-male#77", n = { x = 124 }, c = { x = { { 0.00, "Вернитесь к моей жене, старейшей Зазубренный Клык!" }, { 4.24, "Скажите ей, что со мной всё хорошо, и что скоро я буду дома." }, { 9.25, "Она непременно наградит вас за это известие." } } }, t = { d = 6.9, v = "troll-female#75", n = { x = 69 }, c = { x = { { 0.00, "Вы оказали клану Сломанного Клыка неоценимую услугу!" }, { 4.42, "Мы навечно в долгу перед вами." } } } } },
    [7848] = { d = 40.7, g = 1, v = "bloodelf-male", n = { m = 458, f = 459 }, c = { m = { { 0.00, "Земля испещрена трещинами и разломами – прямо у нас под ногами, герой." }, { 4.96, "В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра Чёрной горы, в самую вотчину Повелителя огня." }, { 13.75, "Удивлён?" }, { 14.32, "Прискорбно..." }, { 15.28, "Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб..." }, { 21.45, "Уверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться." }, { 27.24, "Смотрю, у тебя глаза заблестели." }, { 29.60, "Послушай, приобрести сродство с недрами не так сложно." }, { 33.42, "Отправляйся в Глубины Чёрной горы и принеси мне фрагмент ядра." }, { 37.81, "Я сделаю так, что ты сможешь видеть портал." } }, f = { { 0.00, "Земля испещрена трещинами и разломами – прямо у нас под ногами, героиня." }, { 5.00, "В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра Чёрной горы, в самую вотчину Повелителя огня." }, { 13.63, "Удивлена?" }, { 14.32, "Прискорбно..." }, { 15.25, "Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб..." }, { 21.32, "Уверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться." }, { 27.01, "Смотрю, у тебя глаза заблестели." }, { 29.32, "Послушай, приобрести сродство с недрами не так сложно." }, { 33.07, "Отправляйся в Глубины Чёрной горы и принеси мне фрагмент ядра." }, { 37.38, "Я сделаю так, что ты сможешь видеть портал." } } }, t = { d = 5.8, v = "bloodelf-male", n = { x = 54 }, c = { x = { { 0.00, "Теперь я могу открыть тебе дорогу в Огненные Недра." }, { 4.42, "Ищи и обрящешь..." } } } } },
    [7849] = { d = 28.9, v = "troll-male#77", n = { x = 309 }, c = { x = { { 0.00, "Как и многие жители нашей деревни, мой близкий человек погиб в лесу." }, { 5.22, "Это был мой брат-близнец Малькор – он погиб в бою с троллями Порочной Ветви, тогда же, когда пропал муж старейшей клана Зазубренный Клык." }, { 15.53, "Моего брата очень быстро казнили, а его останки бросили на съедение слизнюкам и волкам." }, { 22.25, "Жизнь его мы не уберегли, но душу спасти ещё можно." }, { 26.11, "Пожалуйста, принесите мне его останки." } } }, t = { d = 7.6, v = "troll-male#77", n = { x = 64 }, c = { x = { { 0.00, "Мой милый брат, как же мне тебя не хватает..." }, { 4.14, "Спасибо за помощь." }, { 5.91, "Вы настоящий герой." } } } } },
    [7850] = { d = 32.7, v = "troll-female#75", n = { x = 367 }, c = { x = { { 0.00, "Тролли из клана Порочной Ветви проявляют в бою необычайную свирепость!" }, { 5.30, "Это всё потому, что их околдовала недобрая коварная жрица Ведьмиса." }, { 10.33, "В поселении Джинта'Алор можно найти очень много сосудов с порченой кровью, которые излучают тёмную магию безлицего кровавого бога и наделяют троллей Порочной Ветви сверхъестественными силами, сводя их с ума." }, { 25.82, "Украдите эти сосуды и принесите их мне, чтобы я сняла порчу и ослабила хватку кровавого бога." } } }, t = { d = 13.9, v = "troll-female#75", n = { x = 151 }, c = { x = { { 0.00, "Зло, которому подчинялись тролли из клана Порочной Ветви, на время ослабло." }, { 5.76, "Однако нельзя терять бдительности, потому что даже если одна жрица погибнет, её место вскоре займёт другая." } } } } },
    [7861] = { d = 14.7, v = "narrator", n = { x = 148 }, c = { x = { { 0.00, "По приказу старейшины племени Сломанного Клыка разыскивается коварная жрица Ведьмиса и её приспешники." }, { 8.71, "Тот, кто убьёт Ведьмису и её стражей Аман'заси, получит отличную награду!" } } }, t = { d = 6.4, v = "troll-female#75", n = { x = 62 }, c = { x = { { 0.00, "Это серьёзный удар по клану Порочной Ветви." }, { 3.87, "Вы получите достойную награду." } } } } },
    [7862] = { d = 32.8, v = "narrator", n = { x = 348 }, c = { x = { { 0.00, "Капитан стражи Малькор погиб, и теперь эта должность свободна." }, { 5.14, "Если вы хотите стать капитаном стражи в деревне Сломанного Клыка, выполните эти задания и подайте заявление старейшине племени Сломанного Клыка." }, { 16.80, "Уничтожьте берсерков из племени Порочной Ветви." }, { 20.64, "Уничтожьте тёмных охотников из племени Порочной Ветви." }, { 24.99, "Уничтожьте кровопийц из племени Порочной Ветви." }, { 28.82, "Уничтожьте пожирателей душ из клана Порочной Ветви." } } }, t = { d = 11.8, v = "troll-female#75", n = { x = 136 }, c = { x = { { 0.00, "Вы и правда отлично подходите для такой работы." }, { 3.55, "Примите это в знак признательности и благодарности за ваши старания." }, { 8.57, "Через год я ещё раз пересмотрю все кандидатуры." } } } } },
    [7863] = { t = { d = 24.1, v = "nightelf-female", n = { x = 308 }, c = { x = { { 0.00, "Ты уже начинаешь доказывать нам, чего стоишь." }, { 2.93, "В награду прими этот набор припасов!" }, { 5.34, "Внутри ты найдёшь пайки и бинты, которыми можно пользоваться только в Ущелье Песни Войны." }, { 11.08, "Чем больше ты будешь проявлять себя в ущелье, тем больше этих предметов сможешь у нас покупать." }, { 17.16, "Пайки станут доступны, когда наше отношение к тебе станет дружелюбным, а бинты – когда ты заслужишь уважение." } } } } },
