    [7877] = { d = 7.7, v = "nightelf-female#51", n = { x = 89 }, c = { x = { { 0.00, "В библиотеке, ты найдёшь древний сундук, спрятанный под лестницей." }, { 4.78, "Можешь взять оттуда, что тебе понравится." } } }, t = { d = 3.3, v = "narrator", n = { x = 30 }, c = { x = { { 0.00, "Вы открываете сундук и находите там..." } } } } },
    [7881] = { t = { d = 10.1, v = "scourge-male#83", n = { x = 89 }, c = { x = { { 0.00, "Спасибо." }, { 0.85, "Сделано очень добротно." }, { 3.13, "Мастерство высшего класса!" }, { 5.67, "Вот тебе купон Ярмарки Новолуния... развлекайся." } } } } },
    [7882] = { t = { d = 21.6, v = "scourge-male#83", n = { x = 183 }, c = { x = { { 0.00, "Ага, это же мои доспехи!" }, { 2.48, "Великолепно." }, { 3.67, "Из какой кожи сделаны, можно полюбопытствовать?" }, { 8.19, "Швы прочные, материал плотный..." }, { 11.27, "Загляденье!" }, { 12.38, "Ты – настоящий мастер, прими мои комплименты!" }, { 16.73, "Благодарю тебя от всей души." }, { 19.46, "Держи обещанные купоны." } } } } },
    [7883] = { t = { d = 12.7, v = "scourge-male#83", n = { x = 115 }, c = { x = { { 0.00, "Вот это размерчик!" }, { 1.67, "Даже не знаю, найдёт ли Эбби эдакого гнома – ну да ладно, в крайнем случае подошьём костюм." }, { 9.70, "Спасибо тебе." }, { 10.97, "Вот обещанные купоны." } } } } },
    [7884] = { t = { d = 14.1, v = "scourge-male#83", n = { x = 136 }, c = { x = { { 0.00, "Красота!" }, { 0.78, "Как раз мой размерчик." }, { 2.65, "Надеюсь, мне не придётся чистить клетку с кроколисками." }, { 7.31, "Очень неприятные зверьки, правда?" }, { 10.27, "Вот твои купоны." }, { 11.75, "Приятного отдыха на ярмарке!" } } } } },
    [7885] = { t = { d = 20.2, g = 1, v = "scourge-male#83", n = { m = 200, f = 201 }, c = { m = { { 0.00, "Отлично!" }, { 0.74, "Эта броня вполне сгодится!" }, { 3.02, "Ты посмотри, опять дырка в шатре... сейчас твои комплекты в момент разлетятся на заплаты!" }, { 10.30, "Спасибо огромное." }, { 11.78, "Эти комплекты помогут значительно сократить наши расходы на ремонт." }, { 17.30, "А вот и твои купоны – ты их заслужил!" } }, f = { { 0.00, "Отлично!" }, { 0.72, "Эта броня вполне сгодится!" }, { 2.96, "Ты посмотри, опять дырка в шатре... сейчас твои комплекты в момент разлетятся на заплаты!" }, { 10.10, "Спасибо огромное." }, { 11.55, "Эти комплекты помогут значительно сократить наши расходы на ремонт." }, { 16.96, "А вот и твои купоны – ты их заслужила!" } } } } },
    [7889] = { t = { d = 10.9, v = "human-female#47", n = { x = 115 }, c = { x = { { 0.00, "Вот это я понимаю!" }, { 1.48, "Не слишком тяжёлые, но и вес чувствуется." }, { 4.60, "Отлично подойдут для наращивания мышечной массы!" }, { 8.41, "Трижды спасибо." }, { 9.69, "А вот твой купон!" } } } } },
    [7890] = { t = { d = 15.7, g = 1, v = "human-female#47", n = { m = 161, f = 161 }, c = { m = { { 0.00, "Мои камушки!" }, { 1.00, "А какие тяжёленькие!" }, { 2.46, "Уже чувствую, как мышцы наполняются силой." }, { 5.65, "Спасибо большое!" }, { 6.92, "Вот, возьми купоны – и смотри, не объедайся сладким!" }, { 10.77, "Герой вроде тебя должен держать себя в хорошей боевой форме!" } }, f = { { 0.00, "Мои камушки!" }, { 1.01, "А какие тяжёленькие!" }, { 2.50, "Уже чувствую, как мышцы наполняются силой." }, { 5.75, "Спасибо большое!" }, { 7.03, "Вот, возьми купоны – и смотри, не объедайся сладким!" }, { 10.96, "Героиня вроде тебя должна держать себя в хорошей боевой форме!" } } } } },
    [7891] = { t = { d = 12.6, v = "human-female#47", n = { x = 125 }, c = { x = { { 0.00, "Да!" }, { 0.29, "Именно то, что мне нужно!" }, { 2.29, "Какой чудесный цвет, и руки остаются открытыми — пусть все видят, какие они сильные!" }, { 9.00, "Идеально!" }, { 9.79, "Вот, держи свои купоны — развлекайся!" } } } } },
    [7892] = { t = { d = 15.7, v = "human-female#47", n = { x = 176 }, c = { x = { { 0.00, "О, идеально!" }, { 0.89, "У этой палицы большое тяжёлое навершие." }, { 3.70, "Спорим, ею можно разнести почти что угодно?" }, { 6.89, "Надеюсь только, что она сама не разлетится вместе с тем, по чему я ударю!" }, { 12.12, "Вот твои купоны." }, { 13.34, "Приятно провести время на ярмарке!" } } } } },
    [7893] = { t = { d = 15.8, v = "human-female#47", n = { x = 190 }, c = { x = { { 0.00, "Благодарю тебя." }, { 1.12, "Эти камни нужны мне для ритуала, о котором я узнала из древней скрижали, найденной в глубоких джунглях Тернистой долины." }, { 9.49, "Там говорится, что та, кто верно выполнит ритуал, станет обладательницей силы десяти тауренов!" } } } } },
    [7894] = { t = { d = 15.4, v = "troll-male", n = { x = 146 }, c = { x = { { 0.00, "Ага!" }, { 0.46, "Модуляторы!" }, { 1.47, "Супер!" }, { 2.08, "Пока что я не могу тебе сказать, что мы возводим, но без модуляторов всё просто развалится." }, { 9.81, "Я твой должник!" }, { 11.12, "Прими от меня этот купон и сердечную благодарность!" } } } } },
    [7895] = { t = { d = 18.4, v = "troll-male", n = { x = 160 }, c = { x = { { 0.00, "Мои трещоточки!" }, { 1.51, "Прелестно!" }, { 2.51, "Как чудесно они жужжат и стрекочут!" }, { 5.85, "О, когда я оборудую свой балаганчик, он станет одним из чудес света, запомни мои слова!" }, { 14.05, "Вот твои купончики." }, { 15.89, "Приятного отдыха на Ярмарке!" } } } } },
    [7896] = { t = { d = 21.9, g = 1, v = "troll-male", n = { m = 193, f = 195 }, c = { m = { { 0.00, "Ты принёс фейерверки." }, { 1.85, "Отличная работа!" }, { 3.37, "Не терпится зажечь их и возвестить всему миру, что мой павильон готов к работе!" }, { 10.44, "Правда, придётся ещё подождать — боюсь, довольно долго, — но... буду готов, когда буду готов, так ведь?" }, { 19.59, "Вот твои купоны." }, { 21.12, "Веселись!" } }, f = { { 0.00, "Ты принесла фейерверки." }, { 2.07, "Отличная работа!" }, { 3.59, "Не терпится зажечь их и возвестить всему миру, что мой павильон готов к работе!" }, { 10.60, "Правда, придётся ещё подождать — боюсь, довольно долго, — но... буду готов, когда буду готов, так ведь?" }, { 19.69, "Вот твои купоны." }, { 21.20, "Веселись!" } } } } },
    [7897] = { t = { d = 20.7, v = "troll-male", n = { x = 204 }, c = { x = { { 0.00, "Благодарю!" }, { 0.89, "Пора приступать к ремонту." }, { 3.13, "Сколько же ночей мне придётся провозиться, чтобы всё прикрутить на место..." }, { 9.24, "Знаешь, иногда мне снова хочется стать охотником за головами, но... на ярмарке в сто раз лучше!" }, { 17.00, "Возьми купоны, веселись и отдыхай на здоровье!" } } } } },
    [7898] = { t = { d = 25.9, v = "troll-male", n = { x = 233 }, c = { x = { { 0.00, "Премного благодарен!" }, { 1.82, "Эбби как раз такие устройства и искал." }, { 5.22, "Не знаю уж, зачем они ему, но Эбби ума не занимать, мозговитый гном." }, { 11.30, "Мозговитый и даже немного не от мира сего..." }, { 15.25, "Эх, если бы он хоть разок отведал нежной человечины, какой бы тролль из него вышел!" }, { 22.52, "Вот." }, { 22.92, "Сделка есть сделка, забирай купоны." } } } } },
    [7899] = { t = { d = 9.8, g = 1, v = "gnome-male", n = { m = 99, f = 100 }, c = { m = { { 0.00, "Отличные экземпляры!" }, { 1.66, "Наделаем игрушек да сувениров – и у нас отбою не будет от посетителей!" }, { 7.23, "Вот твой купон." }, { 8.46, "Ты его заслужил!" } }, f = { { 0.00, "Отличные экземпляры!" }, { 1.66, "Наделаем игрушек да сувениров – и у нас отбою не будет от посетителей!" }, { 7.24, "Вот твой купон." }, { 8.47, "Ты его заслужила!" } } } } },
    [7900] = { t = { d = 13.9, v = "gnome-male", n = { x = 136 }, c = { x = { { 0.00, "Прекрасные шкуры!" }, { 1.44, "Посажу за работу швей и художников." }, { 4.26, "Сошьём, набьём, покрасим – и таких игрушек не будет больше ни у кого в Азероте!" }, { 10.54, "Какие такие купоны?" }, { 12.20, "Ай, забыл – вот, держи!" } } } } },
    [7901] = { t = { d = 24.5, v = "gnome-male", n = { x = 276 }, c = { x = { { 0.00, "Вот молодчина!" }, { 1.04, "Теперь посетители унесут с собой не только воспоминания о ярмарке, но и очень дорогостоящие сувениры!" }, { 8.29, "Потом они покажут \"Пышный хвост\" друзьям, и те захотят себе такой же, могу поспорить на что угодно." }, { 15.49, "Ладно, что-то я заболтался." }, { 17.50, "Вот твои купоны!" }, { 18.73, "Развлекайся и веселись... и не забудь рассказать о ярмарке всем друзьям и знакомым!" } } } } },
    [7902] = { t = { d = 16.9, g = 1, v = "gnome-male", n = { m = 169, f = 171 }, c = { m = { { 0.00, "Ага, вот и мои пёрышки!" }, { 1.91, "Прелесть, не так ли?" }, { 3.52, "От такой красоты даже у мёртвого разыграется воображение!" }, { 8.15, "Ты мне так помог." }, { 9.54, "Лучшая награда для меня – улыбки на лицах посетителей, а тебе причитаются обещанные купоны!" } }, f = { { 0.00, "Ага, вот и мои пёрышки!" }, { 1.84, "Прелесть, не так ли?" }, { 3.40, "От такой красоты даже у мёртвого разыграется воображение!" }, { 7.85, "Ты мне так помогла." }, { 9.34, "Лучшая награда для меня – улыбки на лицах посетителей, а тебе причитаются обещанные купоны!" } } } } },
    [7903] = { t = { d = 17.8, g = 1, v = "gnome-male", n = { m = 181, f = 181 }, c = { m = { { 0.00, "Бесподобно!" }, { 0.87, "Целая горсть глаз!" }, { 2.21, "Надеюсь, тебе было страшно на них охотиться!" }, { 5.56, "Ага!" }, { 5.97, "Если уж такой бравый герой до сих пор дрожит от страха, что же будет с нашими несчастными посетителями?!" }, { 13.67, "Вот, возьми эти купоны, и спасибо тебе за услугу!" } }, f = { { 0.00, "Бесподобно!" }, { 0.89, "Целая горсть глаз!" }, { 2.26, "Надеюсь, тебе было страшно на них охотиться!" }, { 5.67, "Ага!" }, { 6.08, "Если уж такая бравая героиня до сих пор дрожит от страха, что же будет с нашими несчастными посетителями?!" }, { 14.08, "Вот, возьми эти купоны, и спасибо тебе за услугу!" } } } } },
    [7905] = { d = 26.2, v = "dwarf-male", n = { x = 300 }, c = { x = { { 0.00, "Грядёт Ярмарка Новолуния!" }, { 1.84, "Готовься испытать все её чудеса и радости, когда она прибудет в наш город!" }, { 7.30, "Если ты поторопишься, то сможешь обменять этот сертификат на призовой купон!" }, { 12.90, "Надо только передать сертификат Гельвасу Угольному Шлюзу в ярмарочном лагере." }, { 18.62, "Сейчас ярмарка стоит рядом со Златоземьем, в Элвиннском лесу." }, { 23.16, "Не упусти шанса!" }, { 24.41, "Отправляйся прямо сегодня!" } } }, t = { d = 18.4, v = "goblin-male", n = { x = 198 }, c = { x = { { 0.00, "Добро пожаловать на ярмарку Новолуния!" }, { 2.95, "Этот сертификат на ПЯТЬ, да, целых ПЯТЬ призовых купонов!" }, { 7.28, "Когда у вас будет их побольше, обратитесь ко мне, и я обменяю их на ценные призы." }, { 13.40, "Чем больше вы получите купонов, тем больше выиграете призов." }, { 18.00, "Вперёд!" } } } } },
    [7907] = { d = 24.8, v = "narrator", n = { x = 262 }, c = { x = { { 0.00, "Как только вы собираете вместе восемь карт из колоды Зверей, девятая карта с такой же \"рубашкой\" мистическим образом появляется в колоде." }, { 10.74, "На карте написано: \"Принеси колоду на ярмарку Новолуния, и получишь награду\"." }, { 16.82, "Ярмарка приезжает в Мулгор и Златоземье раз в несколько месяцев." }, { 21.84, "Придётся подождать до следующего раза..." } } }, t = { d = 13.0, g = 1, v = "human-male", n = { m = 140, f = 141 }, c = { m = { { 0.00, "Итак, ты собрал колоду Зверей." }, { 2.40, "Отныне ты всегда можешь рассчитывать на хорошее отношение к себе на нашей ярмарке." }, { 8.72, "В знак этого я вручаю тебе одну из старших карт Новолуния." } }, f = { { 0.00, "Итак, ты собрала колоду Зверей." }, { 2.43, "Отныне ты всегда можешь рассчитывать на хорошее отношение к себе на нашей ярмарке." }, { 8.64, "В знак этого я вручаю тебе одну из старших карт Новолуния." } } } } },
    [7908] = { d = 9.4, v = "narrator", n = { x = 98 }, c = { x = { { 0.00, "Должно быть, стать мастером арены не так просто!" }, { 3.77, "Быть может, пират-распорядитель на Арене Гурубаши, знает, в чём тут штука!" } } } },
    [7926] = { d = 28.7, v = "orc-male", n = { x = 301 }, c = { x = { { 0.00, "Грядёт ярмарка Новолуния!" }, { 2.01, "Когда она прибудет в город, веселью и чудесам не будет конца!" }, { 7.04, "А если ты поторопишься, то сможешь обменять этот сертификат на бесплатные призовые купоны!" }, { 14.22, "Не забудь передать свой сертификат Гельвасу Угольному Шлюзу в ярмарочном лагере." }, { 20.61, "Сейчас ярмарка стоит рядом с Громовым Утёсом, в Мулгоре." }, { 25.14, "Не упусти свой шанс!" }, { 26.72, "Отправляйся прямо сегодня!" } } }, t = { d = 18.6, v = "goblin-male", n = { x = 198 }, c = { x = { { 0.00, "Добро пожаловать на ярмарку Новолуния!" }, { 2.98, "Этот сертификат на ПЯТЬ, да, целых ПЯТЬ призовых купонов!" }, { 7.35, "Когда у вас будет их побольше, обратитесь ко мне, и я обменяю их на ценные призы." }, { 13.51, "Чем больше вы получите купонов, тем больше выиграете призов." }, { 18.15, "Вперёд!" } } } } },
