    [7936] = { t = { d = 13.3, v = "goblin-male", n = { x = 133 }, c = { x = { { 0.00, "Держи, держи!" }, { 1.15, "Приз, достойный короля!" }, { 3.02, "Поздравляю тебя, друг мой!" }, { 5.10, "Если у тебя есть ещё купоны, только скажи!" }, { 8.55, "Пока Ярмарка Новолуния здесь, я буду обменивать твои купоны." } } } } },
    [7937] = { d = 19.5, v = "narrator", n = { x = 183 }, c = { x = { { 0.00, "\"Ты найдёшь свою удачу в Восточной долине\"." }, { 3.73, "Записка, которую вам дал Сейдж, излучает тепло." }, { 7.78, "Вы сжимаете её в руках и видите Лесопилку Восточной долины в Элвиннском лесу." }, { 14.47, "Возле стойл стоит копна сена..." }, { 17.27, "На этом видение обрывается." } } }, t = { d = 7.4, v = "narrator", n = { x = 76 }, c = { x = { { 0.00, "В копне сена был надёжно спрятан небольшой сундучок." }, { 4.19, "Видимо, в нём-то и скрывается ваша удача." } } } } },
    [7938] = { d = 28.0, v = "narrator", n = { x = 275 }, c = { x = { { 0.00, "\"Ты найдёшь свою удачу в Мёртвых копях\"." }, { 3.33, "Записка, которую вам дал Сейдж, излучает тепло." }, { 7.27, "Вы сжимаете её в руках и видите Мёртвые копи возле разрушенной деревни Луноречье в Западном Крае." }, { 15.44, "Запутанные ходы приводят вас к порталу, который ведёт в самое сердце шахт." }, { 21.65, "Вдруг перед порталом возникает странный сундук..." }, { 25.81, "На этом видение обрывается." } } }, t = { d = 6.8, v = "narrator", n = { x = 63 }, c = { x = { { 0.00, "В сундуке оказался ещё один сундучок." }, { 3.32, "Видимо, в нём-то и скрывается ваша удача." } } } } },
    [7939] = { t = { d = 5.5, v = "human-female#47", n = { x = 57 }, c = { x = { { 0.00, "Ещё раз спасибо." }, { 1.33, "Держи купоны и расскажи друзьям о Ярмарке Новолуния!" } } } } },
    [7940] = { t = { d = 12.9, v = "goblin-male", n = { x = 126 }, c = { x = { { 0.00, "Не зевай, забирай!" }, { 1.56, "Приз, достойный короля!" }, { 3.50, "Поздравляю с приобретением!" }, { 5.74, "Если у тебя ещё появятся купоны – приходи, призов у меня целый воз и маленькая тележка!" } } } } },
    [7941] = { t = { d = 3.6, v = "scourge-male#83", n = { x = 33 }, c = { x = { { 0.00, "Держи билеты." }, { 1.34, "Удачно тебе повеселиться!" } } } } },
    [7942] = { t = { d = 5.0, v = "troll-male", n = { x = 42 }, c = { x = { { 0.00, "Вот твои купоны." }, { 1.60, "Смотри, не трать их все в одном месте!" } } } } },
    [7943] = { t = { d = 3.3, v = "gnome-male", n = { x = 26 }, c = { x = { { 0.00, "Спасибо тебе." }, { 1.41, "А вот и твои билеты!" } } } } },
    [7944] = { d = 27.7, v = "narrator", n = { x = 273 }, c = { x = { { 0.00, "\"Ты найдёшь свою удачу в Пещерах Стенаний.\"" }, { 3.62, "Записка, которую вам дал Сейдж, излучает тепло." }, { 7.54, "Вы сжимаете её в руках и видите пещеру, расположенную к юго-западу от Перекрёстка в Степях." }, { 15.09, "Запутанные ходы приводят вас к порталу, который ведёт в самое сердце пещеры." }, { 21.50, "Вдруг перед порталом возникает странный сундук." }, { 25.50, "На этом видение обрывается." } } }, t = { d = 6.7, v = "narrator", n = { x = 63 }, c = { x = { { 0.00, "В сундуке оказался ещё один сундучок." }, { 3.28, "Видимо, в нём-то и скрывается ваша удача." } } } } },
    [7945] = { d = 19.8, v = "narrator", n = { x = 176 }, c = { x = { { 0.00, "\"Ты найдёшь свою удачу возле утёса Бледногривов\"." }, { 4.46, "Записка, которую вам дал Сейдж, излучает тепло." }, { 8.76, "Вы сжимаете её в руках и видите утёс Бледногривов в Мулгоре." }, { 14.22, "Возле входа в пещеру стоит пень..." }, { 17.44, "На этом видение обрывается." } } }, t = { d = 7.1, v = "narrator", n = { x = 70 }, c = { x = { { 0.00, "Из дупла в пне вы извлекли небольшой сундучок." }, { 3.82, "Видимо, в нём-то и скрывается ваша удача." } } } } },
    [7946] = { t = { d = 9.7, v = "orc-female", n = { x = 83 }, c = { x = { { 0.00, "Спасибо." }, { 0.83, "Вот твоё яйцо!" }, { 2.17, "Вылупится оно ещё не скоро, но когда это случится, у тебя будет отличный питомец!" } } } } },
    [7961] = { d = 7.0, v = "human-male", n = { x = 81 }, c = { x = { { 0.00, "Кролики плодятся с бешеной скоростью!" }, { 2.69, "Надо что-то делать!" }, { 4.16, "Помоги нам, ты наша единственная надежда!" } } } },
