    [8047] = { t = { d = 9.9, g = 1, v = "troll-male", n = { m = 89, f = 89 }, c = { m = { { 0.00, "Наши верования различаются, но я признаю, что твои намерения благородны." }, { 6.20, "Истреби наших врагов, благородный герой." } }, f = { { 0.00, "Наши верования различаются, но я признаю, что твои намерения благородны." }, { 6.30, "Истреби наших врагов, благородная героиня." } } } } },
    [8053] = { d = 33.6, g = 1, v = "troll-male", n = { m = 340, f = 342 }, c = { m = { { 0.00, "Ты – язычник, но мы не преследуем язычников в нашем племени." }, { 4.65, "Мы уважаем тех, кто не боится гонений и без колебаний готов принять смерть за свою веру." }, { 11.47, "Мы знаем, что ты готов умереть за свои убеждения, наши вольнодумцы тоже были такими." }, { 18.16, "Нам нужны Знаки Силы." }, { 19.92, "Ступай в Зул'Гуруб и уничтожь прислужников Хаккара." }, { 23.93, "Возвращайся, когда найдёшь то, что мне нужно." }, { 27.38, "В обмен я отдам тебе одну из деталей брони зандаларских вольнодумцев." } }, f = { { 0.00, "Ты – язычница, но мы не преследуем язычников в нашем племени." }, { 4.85, "Мы уважаем тех, кто не боится гонений и без колебаний готов принять смерть за свою веру." }, { 11.67, "Мы знаем, что ты готова умереть за свои убеждения, наши вольнодумцы тоже были такими." }, { 19.01, "Нам нужны Знаки Силы." }, { 20.77, "Ступай в Зул'Гуруб и уничтожь прислужников Хаккара." }, { 24.78, "Возвращайся, когда найдёшь то, что мне нужно." }, { 28.23, "В обмен я отдам тебе одну из деталей брони зандаларских вольнодумцев." } } }, t = { d = 19.9, g = 1, v = "troll-male", n = { m = 192, f = 195 }, c = { m = { { 0.00, "Ты многое сделал для того, чтобы прославить наше племя." }, { 4.67, "Теперь, когда твои руки обагрены кровью приспешников Хаккара, любой в Зандаларе назовёт тебя другом." }, { 13.06, "Носи с честью эти боевые наручи Вольнодумца." }, { 16.84, "В них заключена настоящая сила." } }, f = { { 0.00, "Ты многое сделала для того, чтобы прославить наше племя." }, { 4.85, "Теперь, когда твои руки обагрены кровью приспешников Хаккара, любой в Зандаларе назовёт тебя подругой." }, { 13.56, "Носи с честью эти боевые наручи Вольнодумца." }, { 17.42, "В них заключена настоящая сила." } } } } },
    [8054] = { d = 44.0, g = 1, v = "troll-male", n = { m = 444, f = 445 }, c = { m = { { 0.00, "Твои верования для нас чужды, язычник." }, { 3.13, "Но племя Зандалара в своё время тоже называли еретиками." }, { 7.72, "Это было ещё во времена расцвета Гурубаши." }, { 11.21, "Тогда язычники осмелились бросить вызов жрецам Хаккара." }, { 15.80, "Их нещадно преследовали и уничтожали, словно диких зверей, но они до самого конца не отступили в своей борьбе против Кровавого бога." }, { 26.57, "Мы понимаем, какую цену им пришлось заплатить, и чтим их мужество." }, { 31.89, "Они были настоящими вольнодумцами." }, { 34.73, "Уничтожь приспешников Хаккара в Зул'Гурубе и принеси мне Знаки Силы." }, { 40.26, "В случае успеха тебя ждёт награда." }, { 43.10, "Ступай." } }, f = { { 0.00, "Твои верования для нас чужды, язычница." }, { 3.46, "Но племя Зандалара в своё время тоже называли еретиками." }, { 8.05, "Это было ещё во времена расцвета Гурубаши." }, { 11.54, "Тогда язычники осмелились бросить вызов жрецам Хаккара." }, { 16.13, "Их нещадно преследовали и уничтожали, словно диких зверей, но они до самого конца не отступили в своей борьбе против Кровавого бога." }, { 26.90, "Мы понимаем, какую цену им пришлось заплатить, и чтим их мужество." }, { 32.22, "Они были настоящими вольнодумцами." }, { 35.06, "Уничтожь приспешников Хаккара в Зул'Гурубе и принеси мне Знаки Силы." }, { 40.59, "В случае успеха тебя ждёт награда." }, { 43.43, "Ступай." } } }, t = { d = 19.8, v = "troll-male", n = { x = 177 }, c = { x = { { 0.00, "Не зря тебя уважают в нашем племени." }, { 3.31, "Ты сеешь смерть среди врагов, Зул'Гуруб трепещет от одного твоего взгляда." }, { 10.00, "Вот он, пояс вольнодумца." }, { 12.26, "Носи его с честью." }, { 14.03, "На него наложено могучее заклятие, отныне пусть оно хранит тебя." } } } } },
    [8055] = { d = 35.4, v = "troll-male", n = { x = 346 }, c = { x = { { 0.00, "Боевое снаряжение – это символ могущества." }, { 3.66, "Вольнодумцы же особенно гордятся своими доспехами." }, { 7.93, "Они усиливают кирасы могущественными заклятиями, и даже если во время боя их вера пошатнётся, то кирасы выдержат всё что угодно." }, { 18.75, "Если ты заслужишь уважение нашего племени, то получишь такую кирасу." }, { 24.62, "Ступай в Зул'Гуруб и принеси мне Знаки Силы." }, { 28.43, "Вырви их у врага безо всякой пощады." }, { 31.63, "Докажи, что ты заслуживаешь звания вольнодумца." } } }, t = { d = 24.3, v = "troll-male", n = { x = 246 }, c = { x = { { 0.00, "Тебе удалось сделать то, что до сих пор удавалось немногим." }, { 4.79, "Теперь-то прислужники Хаккара знают, что значит настоящий вольнодумец!" }, { 10.54, "Оказывается, заслужить уважение племени могут даже еретики вроде тебя." }, { 16.44, "Прими эту кирасу, вольнодумец." }, { 19.02, "Пусть она поможет тебе сокрушить всех, кто встанет у тебя на пути!" } } } } },
    [8056] = { d = 35.1, g = 1, v = "troll-female#75", n = { m = 361, f = 362 }, c = { m = { { 0.00, "Авгуры нашего племени очень гордятся своим даром предвидения." }, { 4.89, "Это тебе не знахари, которые только и знают, что проклинать направо и налево!" }, { 10.98, "Нет, наши авгуры предсказывают будущее по костям и листьям." }, { 15.59, "Тебе, как шаману, должно быть известно, на что способны авгуры." }, { 20.49, "В Зандаларе их откровения очень ценятся." }, { 23.63, "Покажи нам, чего ты стоишь, и принеси Знаки Силы из Зул'Гуруба." }, { 28.60, "Если тебе это удастся, я отдам тебе наручи, которыми наши авгуры очень дорожат." } }, f = { { 0.00, "Авгуры нашего племени очень гордятся своим даром предвидения." }, { 4.92, "Это тебе не знахари, которые только и знают, что проклинать направо и налево!" }, { 11.03, "Нет, наши авгуры предсказывают будущее по костям и листьям." }, { 15.67, "Тебе, как шаманке, должно быть известно, на что способны авгуры." }, { 20.66, "В Зандаларе их откровения очень ценятся." }, { 23.82, "Покажи нам, чего ты стоишь, и принеси Знаки Силы из Зул'Гуруба." }, { 28.81, "Если тебе это удастся, я отдам тебе наручи, которыми наши авгуры очень дорожат." } } } },
    [8057] = { d = 33.8, g = 1, v = "troll-female#75", n = { m = 403, f = 404 }, c = { m = { { 0.00, "Гаруспики играют не последнюю роль в нашем племени; если ты достаточно мудр, то обязательно прислушаешься к их предсказаниям." }, { 8.62, "Они читают судьбу по внутренностям животных и приносят их в жертву духам, чтобы узнать божественную волю." }, { 16.10, "Именно мудрость гаруспиков дала нам преимущество в войне с разрозненными племенами империи Гурубаши." }, { 23.14, "Докажи нашему племени, чего ты стоишь." }, { 25.75, "Принеси из Зул'Гуруба Знаки Силы, и я отдам тебе наручи, от которых не отказался бы никто из гаруспиков Зандалара." } }, f = { { 0.00, "Гаруспики играют не последнюю роль в нашем племени; если ты достаточно мудра, то обязательно прислушаешься к их предсказаниям." }, { 8.59, "Они читают судьбу по внутренностям животных и приносят их в жертву духам, чтобы узнать божественную волю." }, { 15.94, "Именно мудрость гаруспиков дала нам преимущество в войне с разрозненными племенами империи Гурубаши." }, { 22.85, "Докажи нашему племени, чего ты стоишь." }, { 25.34, "Принеси из Зул'Гуруба Знаки Силы, и я отдам тебе наручи, от которых не отказался бы никто из гаруспиков Зандалара." } } }, t = { d = 14.5, g = 1, v = "troll-female#75", n = { m = 122, f = 125 }, c = { m = { { 0.00, "О да, я чувствую силу, исходящую от этих Знаков." }, { 4.37, "Ты заслужил право называться другом племени!" }, { 8.42, "И, конечно же, я помню про сделку..." }, { 11.65, "Вот твои наручи гаруспика!" } }, f = { { 0.00, "О да, я чувствую силу, исходящую от этих Знаков." }, { 4.37, "Ты заслужила право называться подругой племени!" }, { 8.97, "И, конечно же, я помню про сделку..." }, { 12.20, "Вот твои наручи гаруспика!" } } } } },
    [8058] = { d = 35.2, g = 1, v = "troll-male", n = { m = 334, f = 335 }, c = { m = { { 0.00, "Месть – это сила." }, { 1.57, "Именно она движет блюстителями Зандалара." }, { 5.25, "У племени много врагов, и блюстители несут им воздаяние." }, { 10.19, "Ни одно преступление против нас не останется безнаказанным!" }, { 15.29, "Враги должны бояться нашей мести!" }, { 18.35, "Так было раньше и так будет всегда." }, { 21.48, "Стань одним из наших блюстителей!" }, { 24.38, "Найди Знаки Силы в Зул'Гурубе." }, { 27.13, "Соверши возмездие от имени нашего племени и уничтожь прислужников Хаккара." }, { 33.63, "Ты будешь награждён." } }, f = { { 0.00, "Месть – это сила." }, { 1.54, "Именно она движет блюстителями Зандалара." }, { 5.15, "У племени много врагов, и блюстители несут им воздаяние." }, { 9.99, "Ни одно преступление против нас не останется безнаказанным!" }, { 14.98, "Враги должны бояться нашей мести!" }, { 17.97, "Так было раньше и так будет всегда." }, { 21.05, "Стань одним из наших блюстителей!" }, { 23.89, "Найди Знаки Силы в Зул'Гурубе." }, { 26.58, "Соверши возмездие от имени нашего племени и уничтожь прислужников Хаккара." }, { 32.95, "Ты будешь награждена." } } }, t = { d = 17.1, g = 1, v = "troll-male", n = { m = 161, f = 164 }, c = { m = { { 0.00, "Ты славно отомстил нашим врагам." }, { 2.80, "Именно таков и должен быть зандаларский блюститель!" }, { 7.11, "Возьми эти наручи." }, { 8.77, "Пусть они напитают силой твою месть." }, { 11.87, "Знай, что с этой минуты в Зандаларе тебя считают другом." } }, f = { { 0.00, "Ты славно отомстила нашим врагам." }, { 2.91, "Именно таков и должен быть зандаларский блюститель!" }, { 7.22, "Возьми эти наручи." }, { 8.88, "Пусть они напитают силой твою месть." }, { 11.66, "Знай, что с этой минуты в Зандаларе тебя считают подругой." } } } } },
    [8059] = { d = 28.9, v = "troll-male", n = { x = 303 }, c = { x = { { 0.00, "Чернокнижники ступают на опасную почву, заключая сделки с демонами, но наши бесноватые зашли ещё дальше." }, { 8.29, "С помощью древнего ритуала они позволяют демону захватить своё тело, а потом пытаются подчинить его своей воле и использовать его силу." }, { 19.24, "Совершить такой подвиг удаётся немногим." }, { 22.45, "Если хочешь приобщиться к знанию бесноватых, принеси мне Знаки Силы из Зул'Гуруба." } } }, t = { d = 19.8, v = "troll-male", n = { x = 202 }, c = { x = { { 0.00, "Превосходно сработано..." }, { 1.98, "Я чувствую, что Знаки Силы были вырваны у приспешников Хаккара ценою их ужасных мучений." }, { 9.26, "Возьми эти напульсники." }, { 11.25, "На них наложены могучие заклятия, заключающие в себе силу пленённых демонов." }, { 17.42, "Они послужат тебе в сражениях." } } } } },
    [8060] = { d = 38.6, v = "troll-male", n = { x = 417 }, c = { x = { { 0.00, "Маги нашего племени – это творцы иллюзий." }, { 3.37, "В свои чары они вплетают заклинания, одурманивающие врагов и сбивающие их с толку." }, { 9.82, "Наблюдать за работой настоящего мастера иллюзий – истинное удовольствие." }, { 16.83, "Ты можешь видеть, как враг уничтожает себя сам, всё больше и больше погружаясь в безумие." }, { 23.71, "Если хочешь узнать о мастерах иллюзий побольше, ступай в Зул'Гуруб и принеси мне Знаки Силы." }, { 31.00, "Взамен я отдам тебе напульсники, которые использовали наши мастера иллюзий, творя свои заклинания." } } }, t = { d = 27.3, g = 1, v = "troll-male", n = { m = 300, f = 303 }, c = { m = { { 0.00, "Невероятно..." }, { 1.03, "Ты чувствуешь силу, которую они излучают?" }, { 4.27, "Во времена империи Гурубаши Знаками Силы иногда обменивались как монетами." }, { 9.99, "Теперь мы в Зандаларе используем скрытые в них заклинания, чтобы предотвратить новое пришествие Кровавого бога Хаккара." }, { 19.09, "Ты славно потрудился, отныне можешь считать себя в Зандаларе другом." }, { 24.40, "Прими эти напульсники мастера иллюзий." } }, f = { { 0.00, "Невероятно..." }, { 1.01, "Ты чувствуешь силу, которую они излучают?" }, { 4.17, "Во времена империи Гурубаши Знаками Силы иногда обменивались как монетами." }, { 9.74, "Теперь мы в Зандаларе используем скрытые в них заклинания, чтобы предотвратить новое пришествие Кровавого бога Хаккара." }, { 18.61, "Ты славно потрудилась, отныне можешь считать себя в Зандаларе подругой." }, { 23.99, "Прими эти напульсники мастера иллюзий." } } } } },
    [8061] = { d = 32.1, v = "troll-male", n = { x = 310 }, c = { x = { { 0.00, "В Зандаларе принято одаривать силой тех, кто общается с богами и власть имущими." }, { 6.63, "Наши жрецы не просто целители – они исповедники нашего племени." }, { 12.05, "Зло приходит как снаружи – из Зул'Гуруба, так и изнутри." }, { 16.64, "Наши исповедники – наши судьи, которые оберегают нас от того зла, что поглотило Гурубаши." }, { 24.10, "Ступай в Зул'Гуруб и принеси Знаки Силы." }, { 27.57, "Узнай, что значит быть исповедником, и охрани нас от зла." } } } },
    [8062] = { d = 35.0, g = 1, v = "troll-male#78", n = { m = 357, f = 358 }, c = { m = { { 0.00, "В тёмные времена, наставшие после падения империи Гурубаши, зандаларские хищники использовали всё своё мастерство, чтобы наше племя сумело выжить." }, { 11.85, "И теперь они воплощают в себе самую сущность охоты." }, { 16.17, "Отправляйся в Зул'Гуруб и докажи, что ты достоин занять место среди хищников Зандалара." }, { 23.26, "Принеси мне Знаки Силы из Зул'Гуруба." }, { 26.33, "Тогда ты сможешь ещё на один шаг приблизиться к тому, чтобы стать одним из немногих хищников нашего племени." } }, f = { { 0.00, "В тёмные времена, наставшие после падения империи Гурубаши, зандаларские хищники использовали всё своё мастерство, чтобы наше племя сумело выжить." }, { 11.77, "И теперь они воплощают в себе самую сущность охоты." }, { 16.06, "Отправляйся в Зул'Гуруб и докажи, что ты достойна занять место среди хищников Зандалара." }, { 23.18, "Принеси мне Знаки Силы из Зул'Гуруба." }, { 26.23, "Тогда ты сможешь ещё на один шаг приблизиться к тому, чтобы стать одной из немногих хищников нашего племени." } } }, t = { d = 23.9, g = 1, v = "troll-male#78", n = { m = 234, f = 237 }, c = { m = { { 0.00, "Да..." }, { 0.43, "Мне не нужно зрение, чтобы почуять присутствие Знаков Силы." }, { 5.23, "Даже самый последний тролль в племени благодарен тебе за то, что ты делаешь ради нас." }, { 11.96, "Мы не только считаем тебя своим другом; мы считаем, что ты достоин носить наручи хищника, воплощающие в себе его сущность." }, { 21.77, "Мы гордимся тобой." } }, f = { { 0.00, "Да..." }, { 0.44, "Мне не нужно зрение, чтобы почуять присутствие Знаков Силы." }, { 5.36, "Даже самый последний тролль в племени благодарен тебе за то, что ты делаешь ради нас." }, { 12.26, "Мы не только считаем тебя своей подругой; мы считаем, что ты достойна носить наручи хищника, воплощающие в себе его сущность." }, { 22.53, "Мы гордимся тобой." } } } } },
    [8063] = { d = 29.0, v = "troll-male#78", n = { x = 292 }, c = { x = { { 0.00, "Безумцы Зандалара чем-то сродни разбойникам, но самое главное – они несут с собой Хаос и разрушение." }, { 8.08, "В те жестокие времена, когда наши племена были раздроблены, боевое безумие помогло нам выстоять против врага." }, { 16.89, "Если бы не оно, мы бы не уцелели." }, { 19.53, "Принеси мне Знаки Силы из Зул'Гуруба, и одна из деталей брони безумцев станет твоей." }, { 26.33, "Впусти боевое безумие в свою душу!" } } } },
    [8064] = { d = 43.2, v = "troll-female#75", n = { x = 450 }, c = { x = { { 0.00, "Мы в Зандаларе не следуем путями друидов: мы не подстраиваемся под природу, но меняем её согласно нашим желаниям." }, { 8.75, "Тем не менее и среди нас есть те, кто близок к природе." }, { 12.99, "Наши гаруспики всегда умели слушать и понимать её." }, { 17.02, "Чтобы понять дух животного, надо знать, что значит быть одним из них." }, { 22.38, "В этом и заключается истинная сила природы." }, { 25.84, "Принеси мне Знаки Силы из Зул'Гуруба, докажи племени, что тебе можно доверять." }, { 32.05, "Если ты сделаешь это, я отдам тебе могущественный пояс – из тех, что некогда принадлежали гаруспикам Зандалара." }, { 40.74, "В нём сокрыто могучее колдовство!" } } }, t = { d = 14.6, g = 1, v = "troll-female#75", n = { m = 145, f = 146 }, c = { m = { { 0.00, "Спасибо тебе." }, { 1.18, "Сила, сокрытая в этих предметах, сама по себе сокровище, с этим никто не возьмётся спорить." }, { 8.68, "Своими деяниями ты заслужил уважение всего племени." }, { 12.95, "Возьми свою награду!" } }, f = { { 0.00, "Спасибо тебе." }, { 1.14, "Сила, сокрытая в этих предметах, сама по себе сокровище, с этим никто не возьмётся спорить." }, { 8.40, "Своими деяниями ты заслужила уважение всего племени." }, { 12.60, "Возьми свою награду!" } } } } },
    [8065] = { d = 28.7, v = "troll-female#75", n = { x = 306 }, c = { x = { { 0.00, "Одежда гаруспиков – это символ их могущества." }, { 3.49, "Например, мундир – это символ связи между гаруспиком и постигаемой им божественной мудростью." }, { 10.60, "В мундир зашивают части тел животных, принесённых в жертву." }, { 15.05, "Это напоминает гаруспику о связи с его дарами." }, { 18.68, "Докажи племени, чего ты стоишь, и принеси Знаки Силы из Зул'Гуруба." }, { 23.87, "Сделай это, и мундир гаруспиков, хранящий их силу, станет твоим." } } } },
    [8066] = { d = 26.1, g = 1, v = "troll-male#78", n = { m = 273, f = 273 }, c = { m = { { 0.00, "Любой хищник знает, как подкрадываться к добыче, но самый ловкий умеет выбирать лучший момент для удара." }, { 8.29, "Ты должен уметь и подкрадываться, и нападать, чтобы вернуться с добычей из Зул'Гуруба." }, { 15.03, "Принеси мне Знаки Силы." }, { 16.94, "Я обрету могущество, заключённое в них, а ты получишь пояс зандаларского хищника – вещь, ради которой стоит потрудиться." } }, f = { { 0.00, "Любой хищник знает, как подкрадываться к добыче, но самый ловкий умеет выбирать лучший момент для удара." }, { 8.69, "Ты должна уметь и подкрадываться, и нападать, чтобы вернуться с добычей из Зул'Гуруба." }, { 15.39, "Принеси мне Знаки Силы." }, { 17.29, "Я обрету могущество, заключённое в них, а ты получишь пояс зандаларского хищника – вещь, ради которой стоит потрудиться." } } } },
    [8067] = { d = 35.1, v = "troll-male#78", n = { x = 364 }, c = { x = { { 0.00, "В Зандаларе одежда рассказывает о подвигах того, кто её носит." }, { 4.90, "При этом символы наших свершений не обязательно должны быть видимы глазом – излучаемая ими сила говорит сама за себя." }, { 14.26, "Одежда хищников Зандалара обладает именно такими свойствами; более же всего они ценят свои оплечья." }, { 22.28, "Они скрывают своего владельца от чужих взглядов, когда он желает остаться невидимым." }, { 29.03, "В Зул'Гурубе тебя ждут Знаки Силы." }, { 31.79, "Принеси их мне, и это оплечье станет твоим." } } } },
    [8068] = { d = 34.6, v = "troll-male", n = { x = 373 }, c = { x = { { 0.00, "Магия – это бесформенная изначальная сила." }, { 3.31, "Могучие маги управляют её энергией в своих целях." }, { 7.18, "Мы прибегаем к ней в своих заклятиях, но, чтобы создавать иллюзии, нужно особое могущество." }, { 14.15, "Как можно победить врага, который существует только в твоём воображении?" }, { 19.67, "В Зандаларе знают цену подобной магии, и мастера иллюзий пользуются большим уважением в племени." }, { 27.13, "Принеси из Зул'Гуруба Знаки Силы, и ты заслужишь уважение племени, а также оплечье мастера иллюзий." } } }, t = { d = 17.0, v = "troll-male", n = { x = 160 }, c = { x = { { 0.00, "Отныне уважение племени тебе обеспечено!" }, { 3.68, "Благодаря тебе, Зул'Гуруб испытал на себе мощь Зандалара." }, { 8.80, "Прими благословение племени и оплечье мастера иллюзий." }, { 13.68, "Пусть оно служит тебе верой и правдой." } } } } },
    [8069] = { d = 34.2, g = 1, v = "troll-male", n = { m = 322, f = 322 }, c = { m = { { 0.00, "В нашем племени одежда – это символ могущества и власти." }, { 4.88, "Она сшита из лучших материалов и усилена заклинаниями, которые дают нам мощь." }, { 11.43, "Одеяния мастеров иллюзий отражают самую сущность творимых ими заклятий." }, { 17.60, "Легенды гласят, что одеяние мастера иллюзий постоянно меняет свой вид." }, { 23.54, "Я могу дать тебе такое одеяние... но сначала покажи племени, на что ты способен." }, { 30.32, "Принеси мне из Зул'Гуруба Знаки Силы!" } }, f = { { 0.00, "В нашем племени одежда – это символ могущества и власти." }, { 5.00, "Она сшита из лучших материалов и усилена заклинаниями, которые дают нам мощь." }, { 11.73, "Одеяния мастеров иллюзий отражают самую сущность творимых ими заклятий." }, { 18.06, "Легенды гласят, что одеяние мастера иллюзий постоянно меняет свой вид." }, { 24.16, "Я могу дать тебе такое одеяние... но сначала покажи племени, на что ты способна." }, { 31.11, "Принеси мне из Зул'Гуруба Знаки Силы!" } } }, t = { d = 15.0, g = 1, v = "troll-male", n = { m = 132, f = 132 }, c = { m = { { 0.00, "Наконец-то нашёлся герой, достойный носить одеяние мастера иллюзий!" }, { 6.13, "Твои деяния в Зул'Гурубе снискали тебе славу в Зандаларе на вечные времена." }, { 13.08, "Носи одеяние с честью!" } }, f = { { 0.00, "Наконец-то нашлась героиня, достойная носить одеяние мастера иллюзий!" }, { 6.07, "Твои деяния в Зул'Гурубе снискали тебе славу в Зандаларе на вечные времена." }, { 12.69, "Носи одеяние с честью!" } } } } },
    [8070] = { d = 32.8, v = "troll-male", n = { x = 323 }, c = { x = { { 0.00, "После падения империи Гурубаши ужасное зло, разъедавшее племя изнутри, охватило и Зандалар." }, { 7.67, "Нас спасли исповедники, которые защищали нас от нас же самих, не давая истреблять себе подобных." }, { 15.65, "До сих пор исповедники охраняют наш дух и стоят на страже наших жизней." }, { 21.52, "Ступай в Зул'Гуруб и узри глубину падения Хаккара и Гурубаши." }, { 26.71, "Вырви из их грязных лап Знаки Силы." }, { 29.72, "В случае успеха тебя ожидает награда." } } } },
    [8071] = { d = 32.0, g = 1, v = "troll-male", n = { m = 333, f = 333 }, c = { m = { { 0.00, "Исповедники Зандалара носят особые оплечья, по которым каждый из нас узнаёт пастырей племени." }, { 7.27, "Эти оплечья усилены могучими заклятиями, которые помогают почувствовать угрозу, исходящую от врагов племени." }, { 15.81, "Тебе, как жрецу, они очень бы пригодились." }, { 19.19, "Если ты отправишься в Зул'Гуруб, сразишься с приспешниками Хаккара и принесёшь мне нужные Знаки Силы, я отдам тебе оплечье, достойное лучших исповедников." } }, f = { { 0.00, "Исповедники Зандалара носят особые оплечья, по которым каждый из нас узнаёт пастырей племени." }, { 7.49, "Эти оплечья усилены могучими заклятиями, которые помогают почувствовать угрозу, исходящую от врагов племени." }, { 16.29, "Тебе, как жрице, они очень бы пригодились." }, { 19.79, "Если ты отправишься в Зул'Гуруб, сразишься с приспешниками Хаккара и принесёшь мне нужные Знаки Силы, я отдам тебе оплечье, достойное лучших исповедников." } } } },
    [8072] = { d = 32.3, v = "troll-male#78", n = { x = 336 }, c = { x = { { 0.00, "Одним из легендарных безумцев Зандалара был Карвахал Безумный." }, { 4.87, "Легенды гласят, что в боях с врагами племени он применял заклинание \"волна безумия\", наложенное на его оплечья." }, { 13.62, "Врагов поражал ужас, и они видели только мелькание его двойных кинжалов." }, { 19.48, "До сих пор оплечья безумцев – предмет их особой гордости." }, { 23.93, "Принеси мне Знаки Силы из Зул'Гуруба, и они достанутся тебе, чтобы вселять безумие и трепет в твоих врагов." } } }, t = { d = 18.9, g = 1, v = "troll-male#78", n = { m = 199, f = 200 }, c = { m = { { 0.00, "Сегодня мы можем праздновать победу благодаря тебе и тому безумию, которое ты вселил в сердца наших врагов." }, { 8.62, "Племя Зандалара будет чтить тебя!" }, { 11.33, "Нет лучшего способа выразить нашу благодарность, чем отдать тебе эти оплечья безумцев Зандалара." } }, f = { { 0.00, "Сегодня мы можем праздновать победу благодаря тебе и тому безумию, которое ты вселила в сердца наших врагов." }, { 8.63, "Племя Зандалара будет чтить тебя!" }, { 11.31, "Нет лучшего способа выразить нашу благодарность, чем отдать тебе эти оплечья безумцев Зандалара." } } } } },
    [8073] = { d = 39.3, v = "troll-male#78", n = { x = 391 }, c = { x = { { 0.00, "Мои глаза уже давно ничего не видят, но я от этого не страдаю." }, { 5.24, "В нашем племени одежда – символ твоего статуса и могущества, поэтому самые могущественные предметы излучают невидимую глазами силу." }, { 16.10, "Этот мундир зандаларского безумца – не исключение, он пронизан изначальной магией хаоса и безумия, присущих его владельцу." }, { 26.14, "Мне нужны Знаки Силы, которые находятся в Зул'Гурубе." }, { 30.57, "Принеси мне их, и я отдам тебе этот легендарный мундир, который... придётся под стать любому сеятелю безумия." } } } },
    [8074] = { d = 36.9, v = "troll-female#75", n = { x = 379 }, c = { x = { { 0.00, "Авгуры многое знают о стихиях, дружище, и используют свои знания во славу нашего племени." }, { 7.10, "В тёмные времена, наступившие после падения империи Гурубаши, именно авгуры привели нас в тихую гавань Южных морей." }, { 16.16, "Они же вернули нас обратно в Долину, в самое сердце зла, свившее себе гнездо в Зул'Гурубе." }, { 23.26, "Принеси Знаки Силы из Зул'Гуруба и докажи племени, чего ты стоишь." }, { 28.53, "Взамен я дам тебе пояс, который служил нашим авгурам." }, { 32.81, "Это не простой пояс, на нём лежит могучее заклинание." } } } },
    [8075] = { d = 32.3, v = "troll-female#75", n = { x = 351 }, c = { x = { { 0.00, "Все авгуры Зандалара носят хауберки." }, { 2.79, "Они сшиты из лучшего шелка и укреплены прочными кольчужными звеньями." }, { 8.35, "Хауберк – не только символ причастности авгуров к божественному, но и знак их власти." }, { 14.68, "Никто не смеет переходить дорогу тем, кто общается с духами." }, { 19.24, "Докажи свою преданность племени и принеси мне Знаки Силы из Зул'Гуруба." }, { 24.69, "Если тебе удастся сделать это, я отдам тебе лучший из хауберков, который когда-либо носили наши авгуры!" } } } },
    [8076] = { d = 33.6, v = "troll-male", n = { x = 368 }, c = { x = { { 0.00, "Бесноватые стремятся полностью слиться с силой, а не просто использовать её." }, { 5.72, "Многие из бесноватых проиграли бой со своим демоном." }, { 9.66, "Но когда враги наступали со всех сторон – особенно в Зул'Гурубе, – победа стоила всех принесённых жертв." }, { 17.35, "От того, сумеем ли мы сокрушить наших врагов, зависит наше существование, – этому нас научило падение империи Гурубаши." }, { 26.40, "Ступай в Зул'Гуруб и добудь необходимые нам Знаки Силы." }, { 30.62, "Наградой тебе будет оплечье бесноватого." } } }, t = { d = 31.4, v = "troll-male", n = { x = 304 }, c = { x = { { 0.00, "Молодец." }, { 0.75, "Знаки Силы из Зул'Гуруба служат нам напоминанием о могуществе, которое было растрачено впустую." }, { 8.70, "Империя Гурубаши была сильна, но пожрала сама себя изнутри." }, { 13.81, "Игра, в которую играют бесноватые, очень похожа на то, что случилось с империей..." }, { 20.63, "Но добытая ими сила необходима для выживания племени." }, { 25.14, "Прими это оплечье, наш славный союзник... оно сослужит тебе добрую службу." } } } } },
    [8077] = { d = 33.7, v = "troll-male", n = { x = 332 }, c = { x = { { 0.00, "Одеяния, в которые мы облачаемся перед битвой, говорят о нашей силе." }, { 5.66, "Одеяние бесноватого создано из рунной ткани, на которую наложено могучее заклятие." }, { 12.43, "Один его вид вселяет страх в сердца врагов..." }, { 16.18, "Особенно его боятся демоны, зная, что рано или поздно бесноватый их одолеет и подчинит своей воле." }, { 24.42, "Принеси мне Знаки Силы из Зул'Гуруба." }, { 27.51, "Это непросто сделать... но в случае успеха одеяние бесноватого станет твоим." } } } },
    [8078] = { d = 37.8, v = "troll-male", n = { x = 359 }, c = { x = { { 0.00, "Высшая месть ждёт в Зул'Гурубе." }, { 2.69, "Хаккар не должен восстать вновь!" }, { 5.53, "Он подточил империю Гурубаши изнутри и разрушил её, и никаких жертв ему не было довольно." }, { 13.35, "Из-за Хаккара тролли теперь – лишь тень былой славы." }, { 18.01, "Стань нашим блюстителем, уничтожь служителей зла." }, { 22.28, "Зул'Гуруб должен отведать мести Зандалара." }, { 26.07, "Как доказательство совершённой мести, принеси мне Знаки Силы." }, { 31.36, "Взамен ты получишь пояс блюстителя." }, { 34.52, "С ним ты обретёшь настоящую мощь." }, { 37.29, "Ступай." } } }, t = { d = 15.3, v = "troll-male", n = { x = 151 }, c = { x = { { 0.00, "Теперь ты знаешь путь, которым надлежит следовать блюстителю." }, { 5.05, "Твои деяния принесли племени славу, а нашим врагам – смерть." }, { 10.09, "Прими этот пояс блюстителя, и вместе с ним – нашу благодарность." } } } } },
    [8079] = { d = 39.4, v = "troll-male", n = { x = 391 }, c = { x = { { 0.00, "Символ мощи блюстителя – его кираса." }, { 3.15, "Её выковывают, используя могучие заклятия." }, { 6.67, "Подобный доспех носят только те, кто заслужил почёт и уважение племени." }, { 12.60, "Кираса блюстителя – символ отмщения Зандалара." }, { 16.50, "Стать блюстителем – значит нести отмщение." }, { 20.02, "Добудь в Зул'Гурубе Знаки Силы и принеси их нам." }, { 24.07, "Мы должны вернуть заклинания, которые были у нас украдены." }, { 28.94, "Пусть приспешники Хаккара заплатят за свои преступления кровью!" }, { 34.19, "Твоей наградой будет кираса блюстителя." }, { 37.57, "Ступай." }, { 38.24, "Отомсти за нас." } } }, t = { d = 19.8, g = 1, v = "troll-male", n = { m = 186, f = 187 }, c = { m = { { 0.00, "То, что ты совершил, внушает трепет." }, { 3.15, "Племя не забывает своих героев, ведь благодаря тебе Зул'Гуруб испытал всю силу отмщения Зандалара!" }, { 11.81, "Твои деяния станут примером для остальных, и они будут чтить тебя как само воплощение мести." } }, f = { { 0.00, "То, что ты совершила, внушает трепет." }, { 3.10, "Племя не забывает своих героев, ведь благодаря тебе Зул'Гуруб испытал всю силу отмщения Зандалара!" }, { 11.41, "Твои деяния станут примером для остальных, и они будут чтить тебя как само воплощение мести." } } } } },
    [8080] = { d = 34.9, v = "human-female#47", n = { x = 403 }, c = { x = { { 0.00, "Войну выигрывают солдаты – любой солдат вам это скажет." }, { 3.92, "Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!" }, { 11.94, "Вот почему так важна Низина Арати." }, { 14.37, "В этой низине есть ключевые точки, где сосредоточены важные ресурсы." }, { 19.10, "Металл, оружие, пища, древесина – всё это необходимо и всё это можно добыть там." }, { 24.70, "И вот чего я хочу от вас." }, { 26.44, "Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами." } } } },
    [8102] = { t = { d = 5.8, v = "troll-male", n = { x = 55 }, c = { x = { { 0.00, "Будь как огненная лава Каджаро, которую ничто не может остановить." } } } } },
    [8103] = { t = { d = 7.8, v = "troll-male", n = { x = 87 }, c = { x = { { 0.00, "Продолжай истреблять троллей Зул'Гуруба." }, { 3.09, "Пусть Хаккар знает, что мир не склонится перед его жестокостью." } } } } },
    [8105] = { d = 31.9, v = "human-male#50", n = { x = 404 }, c = { x = { { 0.00, "Битва за Низину Арати – это битва за ресурсы и за территорию." }, { 4.04, "Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов." }, { 11.70, "Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки." }, { 16.91, "Совершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага." }, { 23.87, "Найдите вражеское знамя и сорвите его с флагштока!" }, { 27.20, "Когда сумеете сделать это в четырёх указанных точках, возвращайтесь ко мне." } } }, t = { d = 11.1, v = "human-male#50", n = { x = 122 }, c = { x = { { 0.00, "До меня дошли вести о твоих подвигах в Низине Арати." }, { 3.88, "Молодец!" }, { 4.53, "Когда в этой борьбе участвуют такие, как ты, я верю, что однажды мы вернём себе родные земли." } } } } },
    [8107] = { t = { d = 9.9, g = 1, v = "troll-male", n = { x = 80 }, c = { m = { { 0.00, "Слейся с тьмой, герой." }, { 2.16, "Проникни в мир теней." }, { 4.22, "Позволь Кезанскому пороку напитать тёмные стороны твоего \"я\"." } }, f = { { 0.00, "Слейся с тьмой, героиня." }, { 2.29, "Проникни в мир теней." }, { 4.32, "Позволь Кезанскому пороку напитать тёмные стороны твоего \"я\"." } } } } },
    [8109] = { t = { d = 14.1, v = "troll-male", n = { x = 129 }, c = { x = { { 0.00, "Убей их и освежуй трупы." }, { 2.31, "Пусть тени поглотят приспешников Хаккара!" }, { 6.09, "Страх твоих врагов придаст тебе силы, а ожерелье Кезанского порока стократно умножит её." } } } } },
    [8111] = { t = { d = 6.0, v = "troll-female#75", n = { x = 58 }, c = { x = { { 0.00, "Смотри, не скури его нечаянно!" }, { 2.69, "Ожерелье поможет тебе сражаться со злом." } } } } },
    [8112] = { t = { d = 5.5, v = "troll-female#75", n = { x = 56 }, c = { x = { { 0.00, "Тебе удалось показать троллям Зул'Гуруба, что значит истинная сила!" } } } } },
    [8113] = { t = { d = 6.6, v = "troll-female#75", n = { x = 76 }, c = { x = { { 0.00, "Славен твой путь." }, { 1.36, "Продолжай преследовать и безжалостно истреблять приспешников Хаккара." } } } } },
    [8114] = { d = 38.3, g = 1, v = "human-male#50", n = { x = 431 }, c = { m = { { 0.00, "Вы ввязались в войну с нашими врагами за Низину Арати и заслужили на этом поле боя великие почести." }, { 7.07, "Вы показали нам, чего стоит герой вроде вас, и вы показали нашим врагам, что мы не сдадимся перед их подлостью!" }, { 14.83, "Поскольку вы уже доказали нам свою ценность, у меня есть для вас очень трудное задание." }, { 20.95, "Я хочу, чтобы вы заняли и удержали как минимум четыре базы в Низине Арати." }, { 26.25, "Если вам удастся это сделать, мы не только сумеем собрать стратегически важные ресурсы – мы сможем показать Орде наше превосходство!" }, { 35.59, "Идите, и да сопутствует вам удача." } }, f = { { 0.00, "Вы ввязались в войну с нашими врагами за Низину Арати и заслужили на этом поле боя великие почести." }, { 7.13, "Вы показали нам, чего стоит героиня вроде вас, и вы показали нашим врагам, что мы не сдадимся перед их подлостью!" }, { 15.09, "Поскольку вы уже доказали нам свою ценность, у меня есть для вас очень трудное задание." }, { 21.27, "Я хочу, чтобы вы заняли и удержали как минимум четыре базы в Низине Арати." }, { 26.62, "Если вам удастся это сделать, мы не только сумеем собрать стратегически важные ресурсы – мы сможем показать Орде наше превосходство!" }, { 36.04, "Идите, и да сопутствует вам удача." } } }, t = { d = 17.5, v = "human-male#50", n = { x = 218 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.18, "Ко мне прибежал взволнованный разведчик и доложил о ваших действиях." }, { 5.83, "Мы в Лиге Аратора остались очень довольны!" }, { 8.80, "Вы быстро становитесь настоящим героем среди солдат Лиги, и сегодняшние ваши деяния подтверждают вашу безукоризненную репутацию." } } } } },
    [8115] = { d = 26.5, v = "human-male#50", n = { x = 312 }, c = { x = { { 0.00, "Битва за Низину Арати – кровавое предприятие." }, { 3.19, "Ваша помощь очень нужна Лиге Аратора и принимается с большой благодарностью." }, { 8.58, "У нас есть для вас ещё одно задание." }, { 11.02, "Лига хочет нанести решительный, сильный удар по оккупирующим Низину Арати Осквернителям." }, { 17.23, "Мы хотим выбить их со всех стратегических точек поля боя!" }, { 21.24, "Это будет нелегко, но если кто и в состоянии это сделать, так это именно вы." } } }, t = { d = 19.2, g = 1, v = "human-male#50", n = { m = 195, f = 196 }, c = { m = { { 0.00, "У тебя получилось!" }, { 1.50, "Ты захватил все базы!" }, { 3.21, "Молодец!" }, { 3.93, "Кое-кто сомневался в твоих силах, но я знал, что ты справишься." }, { 8.85, "Спасибо тебе." }, { 10.00, "Знай, что Лига Аратора высоко ценит тебя, а Осквернители из рядов Отрёкшихся, должно быть, боятся одного твоего имени!" } }, f = { { 0.00, "У тебя получилось!" }, { 1.48, "Ты захватила все базы!" }, { 3.25, "Молодец!" }, { 3.95, "Кое-кто сомневался в твоих силах, но я знал, что ты справишься." }, { 8.82, "Спасибо тебе." }, { 9.95, "Знай, что Лига Аратора высоко ценит тебя, а Осквернители из рядов Отрёкшихся, должно быть, боятся одного твоего имени!" } } } } },
    [8120] = { d = 44.8, v = "scourge-female", n = { x = 407 }, c = { x = { { 0.00, "Как вы, конечно, слышали, Лига Аратора посылает огромное количество войск в Низину Арати." }, { 8.12, "Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов." }, { 19.61, "Мы должны показать им, что Арати никогда больше не будет домом для людей!" }, { 26.34, "Отправляйтесь в Низину Арати и нападите на рудник, лесопилку, кузницу и стойла." }, { 33.56, "Сорвите с флагштоков вражеские знамёна, заявив о правах Орды на эти территории." }, { 40.78, "Идите." }, { 41.43, "Доложите мне, когда выполните задание." } } }, t = { d = 21.5, v = "scourge-female", n = { x = 192 }, c = { x = { { 0.00, "Разведчик Осквернителей доложил мне о твоём успехе." }, { 4.74, "Молодец." }, { 5.59, "Как ты ещё поймёшь, чтобы победить в битве за Низину Арати, нужно всегда быть начеку и пресекать любые попытки Альянса расшириться." }, { 17.87, "Делай так, и победа здесь нам обеспечена." } } } } },
    [8121] = { d = 48.9, v = "scourge-female", n = { x = 430 }, c = { x = { { 0.00, "В то время как гремят бои за Низину Арати, новости о ваших деяниях достигли моих ушей." }, { 8.24, "Среди нас вы пользуетесь большим уважением, и это даёт мне уверенность в том, что вы выполните миссию, которую я собираюсь на вас возложить." }, { 21.03, "Пришло время послать весточку Лиге Аратора." }, { 25.24, "Мы должны дать им понять, что их позиции в Низине Арати слабы, и потерять их очень легко." }, { 33.57, "Мы должны показать им это, удерживая одновременно четыре стратегических точки в низине." }, { 41.73, "Добейтесь успеха в этом, и заслужите ещё большее уважение среди Осквернителей." } } }, t = { d = 24.6, v = "scourge-female", n = { x = 217 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.58, "Твои последние действия в Низине Арати были очень непростыми, и тем более достоин похвалы твой успех." }, { 11.07, "Лига Аратора, должно быть, ещё не оправилась от последних стычек в низине и зализывает раны – и, будем надеяться, жалеет, что решила сражаться здесь." } } } } },
    [8122] = { d = 44.8, v = "scourge-female", n = { x = 402 }, c = { x = { { 0.00, "Непросто увидеть, когда мы так уже глубоко увязли в конфликте, но наши разведчики сообщают об ослаблении Лиги Аратора." }, { 11.11, "Мы должны использовать это окно и нанести Лиге жестокий удар!" }, { 17.01, "Возвращайтесь в Низину Арати и бросайтесь в бой против наших врагов." }, { 23.41, "Проклинайте их, убивайте их и захватите все пять стратегических баз!" }, { 29.56, "Пусть их солдаты с воплями бегут с передовой и пусть рассказы о вашей жестокости срываются с их дрожащих губ." }, { 39.58, "Сделайте это и одержите великую победу для Осквернителей." } } }, t = { d = 30.8, v = "scourge-female", n = { x = 262 }, c = { x = { { 0.00, "Крики Альянса, когда ты и твои соратники атаковали их, были слышны даже здесь." }, { 7.18, "Мне их почти жаль – столько боли и страха вы принесли в их ряды." }, { 12.97, "Почти, но не совсем." }, { 14.84, "Твоя ценность для Осквернителей несомненна." }, { 18.75, "Твои подвиги в Низине Арати впечатляют, и молва о них разнеслась по залам Вариматраса... и дошла до самой Тёмной Госпожи." } } } } },
    [8123] = { d = 49.6, v = "scourge-male", n = { x = 492 }, c = { x = { { 0.00, "Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати." }, { 6.44, "Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдалённую область, намереваясь распространить свои владения за пределы Опорного пункта." }, { 19.09, "Мы должны остановить их, а наилучшее средство для этого – захватить их припасы." }, { 25.76, "Вы можете нам помочь." }, { 27.60, "Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками." }, { 37.18, "Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть." } } } },
    [8148] = { t = { d = 16.1, g = 1, v = "troll-male#78", n = { m = 151, f = 151 }, c = { m = { { 0.00, "Твой путь только начинается, юный герой." }, { 3.36, "Возможно, когда-нибудь ты окажешься рядом с Водоворотом и сумеешь заглянуть в самое сердце мира." }, { 11.35, "Да пребудет с тобой сила и пусть дух твой будет твёрд!" } }, f = { { 0.00, "Твой путь только начинается, юная героиня." }, { 3.58, "Возможно, когда-нибудь ты окажешься рядом с Водоворотом и сумеешь заглянуть в самое сердце мира." }, { 11.74, "Да пребудет с тобой сила и пусть дух твой будет твёрд!" } } } } },
    [8149] = { d = 33.9, v = "dwarf-male", n = { x = 377 }, c = { x = { { 0.00, "Во время Недели урожая в Азероте мы возносим хвалу героям, которые готовы жизнь отдать – а порой и отдают – за нас." }, { 8.43, "Альянс славит множество героев, но нет повести печальнее на свете, чем повесть об Утере Светоносном." }, { 15.75, "Помоги же нам воздать почести Утеру и отнеси эти подношения к его гробнице в Западных Чумных землях." }, { 23.19, "Положи их к подножию его статуи и возвращайся ко мне." }, { 27.08, "Я пробуду тут только до конца праздника, так что не трать времени и отнеси Утеру эти приношения." } } }, t = { d = 33.2, g = 1, v = "dwarf-male", n = { m = 336, f = 337 }, c = { m = { { 0.00, "Он был героем из героев, этот Утер." }, { 2.82, "Даже представить не могу, какую боль он испытал, когда Артас – его лучший ученик, которого Утер любил как сына, – предал человечество." }, { 13.89, "И всё же он попытался остановить Артаса, за что мы всегда будем его помнить как истинного паладина." }, { 21.46, "Он дрался до конца, думая лишь о тех, кого надеялся спасти." }, { 26.05, "Спасибо тебе." }, { 27.16, "Ты оказал почести великому герою, помянув его и принеся радость Неделе урожая." } }, f = { { 0.00, "Он был героем из героев, этот Утер." }, { 2.87, "Даже представить не могу, какую боль он испытал, когда Артас – его лучший ученик, которого Утер любил как сына, – предал человечество." }, { 13.83, "И всё же он попытался остановить Артаса, за что мы всегда будем его помнить как истинного паладина." }, { 21.25, "Он дрался до конца, думая лишь о тех, кого надеялся спасти." }, { 25.75, "Спасибо тебе." }, { 26.84, "Ты оказала почести великому герою, помянув его и принеся радость Неделе урожая." } } } } },
    [8150] = { d = 37.5, v = "orc-male", n = { x = 364 }, c = { x = { { 0.00, "Во время Недели урожая мы воздаём почести героям, которые готовы отдать, – а порой и отдают, – за нас жизнь." }, { 8.97, "В Орде множество храбрецов и героев, но нет более яркого примера мужества и самопожертвования, чем Гром Адский Крик." }, { 18.54, "Помоги же нам воздать почести Грому." }, { 21.63, "Отнеси эти подношения к его памятнику в каньоне Гибели Демона в Ясеневом лесу." }, { 28.33, "Положи их к ногам статуи и возвращайся ко мне." }, { 32.17, "Я пробуду тут только до конца праздника, так что не теряй времени!" } } }, t = { d = 37.4, g = 1, v = "orc-male", n = { m = 348, f = 349 }, c = { m = { { 0.00, "Полное имя Грома – \"Громмаш\", означает \"Сердце великана\"." }, { 5.01, "Воистину, ему потребовалось сердце великана, чтобы в одиночку выстоять против Маннорота!" }, { 12.63, "Верно сказал вождь: проклятие орков началось с Грома и Громом же закончилось." }, { 19.25, "И как символично, что жертва Грома – а может быть, и его искупление – стала истоком, из которого берёт начало нынешняя Орда." }, { 29.80, "Спасибо тебе." }, { 31.04, "Ты почтил память великого героя, порадовав его дух и дух Недели урожая." } }, f = { { 0.00, "Полное имя Грома – \"Громмаш\", означает \"Сердце великана\"." }, { 5.04, "Воистину, ему потребовалось сердце великана, чтобы в одиночку выстоять против Маннорота!" }, { 12.71, "Верно сказал вождь: проклятие орков началось с Грома и Громом же закончилось." }, { 19.38, "И как символично, что жертва Грома – а может быть, и его искупление – стала истоком, из которого берёт начало нынешняя Орда." }, { 30.00, "Спасибо тебе." }, { 31.24, "Ты почтила память великого героя, порадовав его дух и дух Недели урожая." } } } } },
    [8151] = { d = 26.6, v = "tauren-male#68", n = { x = 269 }, c = { x = { { 0.00, "Огтинк из Азшары ищет опытных охотников вроде тебя." }, { 4.38, "Огтинк – фурболг-охотник, отрёкшийся от своего племени ради помощи Кругу Кенария." }, { 11.13, "Он стремится наставлять собратьев по оружию и учить их соблюдению природного равновесия." }, { 18.33, "Тебе не помешает поговорить с ним." }, { 21.15, "Огтинк живёт на скалах Азшары, на северо-востоке от руин Эльдарата." } } }, npc = { [3352] = { d = 24.2, v = "orc-male#60", n = { x = 269 }, c = { x = { { 0.00, "Огтинк из Азшары ищет опытных охотников вроде тебя." }, { 3.98, "Огтинк – фурболг-охотник, отрёкшийся от своего племени ради помощи Кругу Кенария." }, { 10.13, "Он стремится наставлять собратьев по оружию и учить их соблюдению природного равновесия." }, { 16.68, "Тебе не помешает поговорить с ним." }, { 19.24, "Огтинк живёт на скалах Азшары, на северо-востоке от руин Эльдарата." } } } }, [4205] = { d = 23.4, v = "nightelf-male#55", n = { x = 269 }, c = { x = { { 0.00, "Огтинк из Азшары ищет опытных охотников вроде тебя." }, { 3.85, "Огтинк – фурболг-охотник, отрёкшийся от своего племени ради помощи Кругу Кенария." }, { 9.79, "Он стремится наставлять собратьев по оружию и учить их соблюдению природного равновесия." }, { 16.13, "Тебе не помешает поговорить с ним." }, { 18.61, "Огтинк живёт на скалах Азшары, на северо-востоке от руин Эльдарата." } } } }, [5116] = { d = 23.5, v = "dwarf-male", n = { x = 269 }, c = { x = { { 0.00, "Огтинк из Азшары ищет опытных охотников вроде тебя." }, { 3.88, "Огтинк – фурболг-охотник, отрёкшийся от своего племени ради помощи Кругу Кенария." }, { 9.86, "Он стремится наставлять собратьев по оружию и учить их соблюдению природного равновесия." }, { 16.24, "Тебе не помешает поговорить с ним." }, { 18.74, "Огтинк живёт на скалах Азшары, на северо-востоке от руин Эльдарата." } } } } }, t = { d = 23.3, v = "creature/furbolg", n = { x = 185 }, c = { x = { { 0.56, "Я более не охочусь, а учу других." }, { 3.50, "Такая судьба." }, { 4.73, "Создай с моей помощью талисман охотника, состоящий из частиц убитой дичи." }, { 11.14, "Талисман будет напоминать тебе о прошлых испытаниях и победах." }, { 16.55, "Я оставлю его себе, а тебе дам кое-что другое." } } } } },
    [8153] = { d = 32.6, v = "creature/furbolg", n = { x = 293 }, c = { x = { { 0.43, "Беговые олени являются обладателями самых мощных рогов из всех известных нам животных." }, { 7.78, "Олень защищается рогами, пронзая ими нападающих, и нередко обламывает при этом отростки." }, { 15.35, "Безупречные рога – знак зверя, исполненного силы духа." }, { 20.02, "Добывший такие рога и сам обретает небывалую силу духа." }, { 24.84, "Поохоться на мохноногих оленей и принеси мне лучшую пару их рогов." } } }, t = { d = 12.2, v = "creature/furbolg", n = { x = 81 }, c = { x = { { 0.56, "У тебя явно хорошее терпение и зоркий глаз, иначе тебе не удалось бы справиться с задачей." }, { 8.57, "Я доволен." } } } } },
    [8154] = { d = 35.5, v = "human-female#47", n = { x = 403 }, c = { x = { { 0.00, "Войну выигрывают солдаты – любой солдат вам это скажет." }, { 3.99, "Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!" }, { 12.16, "Вот почему так важна Низина Арати." }, { 14.63, "В этой низине есть ключевые точки, где сосредоточены важные ресурсы." }, { 19.45, "Металл, оружие, пища, древесина – всё это необходимо и всё это можно добыть там." }, { 25.15, "И вот чего я хочу от вас." }, { 26.92, "Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами." } } }, t = { d = 14.2, g = 1, v = "human-female#47", n = { m = 155, f = 156 }, c = { m = { { 0.00, "Ты добыл ресурсы!" }, { 1.35, "Прекрасная работа!" }, { 2.76, "Я передам их нашим интендантам, а они быстро распределят их по войскам." }, { 8.08, "Спасибо." }, { 8.76, "Воистину, войны выигрывают именно такими успешными вылазками, как твоя." } }, f = { { 0.00, "Ты добыла ресурсы!" }, { 1.43, "Прекрасная работа!" }, { 2.86, "Я передам их нашим интендантам, а они быстро распределят их по войскам." }, { 8.25, "Спасибо." }, { 8.93, "Воистину, войны выигрывают именно такими успешными вылазками, как твоя." } } } } },
    [8155] = { d = 35.2, v = "human-female#47", n = { x = 403 }, c = { x = { { 0.00, "Войну выигрывают солдаты – любой солдат вам это скажет." }, { 3.95, "Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!" }, { 12.05, "Вот почему так важна Низина Арати." }, { 14.50, "В этой низине есть ключевые точки, где сосредоточены важные ресурсы." }, { 19.27, "Металл, оружие, пища, древесина – всё это необходимо и всё это можно добыть там." }, { 24.92, "И вот чего я хочу от вас." }, { 26.68, "Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами." } } }, t = { d = 16.8, g = 1, v = "human-female#47", n = { m = 205, f = 206 }, c = { m = { { 0.00, "У тебя есть ресурсы!" }, { 1.42, "Прекрасная работа!" }, { 2.71, "Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам." }, { 8.32, "Спасибо." }, { 8.93, "Действительно, успешное выполнение миссий, подобных той, которую ты выполнил, - вот как действительно выигрывают войны." } }, f = { { 0.00, "У тебя есть ресурсы!" }, { 1.41, "Прекрасная работа!" }, { 2.70, "Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам." }, { 8.29, "Спасибо." }, { 8.90, "Действительно, успешное выполнение миссий, подобных той, которую ты выполнила, - вот как действительно выигрывают войны." } } } } },
