    [8162] = { d = 48.0, v = "scourge-male", n = { x = 492 }, c = { x = { { 0.00, "Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати." }, { 6.22, "Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдалённую область, намереваясь распространить свои владения за пределы Опорного пункта." }, { 18.45, "Мы должны остановить их, а наилучшее средство для этого – захватить их припасы." }, { 24.89, "Вы, можете нам помочь." }, { 26.74, "Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками." }, { 36.00, "Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть." } } } },
    [8166] = { d = 32.5, v = "human-male#50", n = { x = 404 }, c = { x = { { 0.00, "Битва за Низину Арати – это битва за ресурсы и за территорию." }, { 4.11, "Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов." }, { 11.90, "Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки." }, { 17.20, "Совершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага." }, { 24.29, "Найдите вражеское знамя и сорвите его с флагштока!" }, { 27.68, "Когда сумеете сделать это на четырёх указанных базах, возвращайтесь ко мне." } } }, t = { d = 12.6, v = "human-male#50", n = { x = 136 }, c = { x = { { 0.00, "Я получил сообщения о ваших подвигах в Низине Арати." }, { 3.99, "Отлично сработано!" }, { 5.41, "С теми, кто, как вы, присоединяется к борьбе здесь, я верю, что однажды мы вернём наши родные земли." } } } } },
