    [8181] = { d = 25.5, v = "dwarf-male", n = { x = 294 }, c = { x = { { 0.00, "Дурные вести." }, { 1.02, "Если верить табличкам Мошару, то подлинная сущность Хаккара, то есть само божество, может родиться из того самого яйца, в которое тебе удалось его заключить." }, { 12.29, "Йе'кинья обманул тебя, он хотел привести в мир Хаккара!" }, { 16.24, "Ступай к этому негодяю и потребуй, чтобы он вернул тебе яйцо." }, { 20.70, "Остаётся молиться, чтобы можно было предотвратить возрождение Хаккара!" } } }, t = { d = 34.2, g = 1, v = "troll-male#77", n = { m = 320, f = 324 }, c = { m = { { 0.00, "Значит, ты поговорил с этим старым дворфом Железным Башмаком и отыскал утраченные таблички Мошару?" }, { 8.26, "Ох, уж этот проспектор, сующий нос не в своё дело…" }, { 12.39, "Неважно." }, { 13.14, "Мир уже не спасти." }, { 14.71, "Хаккар возродился, и сила его растёт с каждым часом... далеко-далеко, в глубинах древнего королевства Зул'Гуруба!" }, { 24.17, "Он вернулся!" }, { 25.22, "И теперь затопит мир кровью и ужасом!" }, { 28.38, "Спасибо." }, { 29.13, "Ты помог ускорить возвращение Свежевателя Душ!" } }, f = { { 0.00, "Значит, ты поговорила с этим старым дворфом Железным Башмаком и отыскала утраченные таблички Мошару?" }, { 8.70, "Ох, уж этот проспектор, сующий нос не в своё дело…" }, { 12.97, "Неважно." }, { 13.74, "Мир уже не спасти." }, { 15.37, "Хаккар возродился, и сила его растёт с каждым часом... далеко-далеко, в глубинах древнего королевства Зул'Гуруба!" }, { 25.16, "Он вернулся!" }, { 26.24, "И теперь затопит мир кровью и ужасом!" }, { 29.51, "Спасибо." }, { 30.28, "Ты помогла ускорить возвращение Свежевателя Душ!" } } } } },
    [8182] = { d = 32.3, v = "dwarf-male", n = { x = 368 }, c = { x = { { 0.00, "Все наши самые жуткие страхи сбываются." }, { 2.95, "В легендах говорилось о Свежевателе Душ, правившем миром древних троллей злом и жестокостью." }, { 9.56, "Сила его была беспредельна." }, { 11.65, "Если его не остановить, он снова воцарится в Азероте!" }, { 15.58, "Тролли Зандалара могут остановить наступление тьмы." }, { 19.31, "Они живут на острове Йоджамба, недалеко от побережья Тернистой долины, к западу от Руин Зул'Кунды." }, { 26.51, "Поговори с их вождём, Молтором." }, { 28.73, "Будем надеяться, что он знает, как одолеть Хаккара." } } }, t = { d = 23.2, v = "troll-male#77", n = { x = 237 }, c = { x = { { 0.00, "Тебя прислал геолог, Железный Башмак?" }, { 3.09, "Он мудр, как и его сородичи, и в мудрости своей прислал тебя ко мне." }, { 8.48, "Мы, зандаларские тролли, знаем, как одолеть Свежевателя Душ." }, { 13.22, "Поговори с другими троллями, живущими на острове, прислушайся к их словам и готовься, ибо твой дальнейший путь пропитан кровью." } } } } },
    [8183] = { d = 8.9, v = "narrator", n = { x = 78 }, c = { x = { { 0.00, "Сердце Хаккара пылает изнутри." }, { 2.88, "Свежеватель Душ повержен, но ключ к его силе – всё ещё в его сердце." } } }, t = { d = 13.4, g = 1, v = "troll-male#77", n = { m = 115, f = 116 }, c = { m = { { 0.00, "Сердце Хаккара!.." }, { 1.65, "Со Свежевателем Душ покончено!" }, { 4.38, "Наш мир спасён!" }, { 5.70, "Невозможно переоценить то, что ты сделал для нас." }, { 10.07, "Ты – живая легенда нашего мира." } }, f = { { 0.00, "Сердце Хаккара!.." }, { 1.71, "Со Свежевателем Душ покончено!" }, { 4.54, "Наш мир спасён!" }, { 5.90, "Невозможно переоценить то, что ты сделала для нас." }, { 10.53, "Ты – живая легенда нашего мира." } } } } },
