    [8194] = { t = { d = 1.0, v = "goblin-female", n = { x = 7 }, c = { x = { { 0.00, "По рукам!" } } } } },
    [8195] = { t = { d = 15.3, v = "troll-male#77", n = { x = 158 }, c = { x = { { 0.00, "Отлично – эти монеты прекрасно дополнят мою коллекцию..." }, { 4.53, "Они нужны племени, чтобы помешать возрождению Кровавого бога." }, { 9.48, "Этот почётный знак – твой по праву, прими его вместе с нашей благодарностью!" } } } } },
    [8196] = { t = { d = 10.3, v = "troll-male#140", n = { x = 104 }, c = { x = { { 0.00, "Хорошая сделка, дружище, наслаждайся ароматом экзотических плодов Южных морей, и да пребудет с тобой благословение племени." } } } } },
    [8201] = { d = 29.7, v = "troll-male#77", n = { x = 310 }, c = { x = { { 0.00, "Это правда." }, { 0.99, "Хаккар теперь обитает в Зул'Гурубе, питаясь силой наших богов." }, { 5.99, "Порабощённые им жрецы направляют энергию самых священных божеств Свежевателю Душ, и скоро сильнее его в Азероте не будет существа." }, { 16.15, "Его надо остановить!" }, { 17.84, "Возьми этот священный шнур." }, { 20.03, "Нанижи на него головы верховных жрецов, по вине которых сила наших богов утекает к Хаккару." }, { 27.36, "Сделав это, возвращайся ко мне." } } }, t = { d = 19.3, g = 1, v = "troll-male#77", n = { m = 189, f = 190 }, c = { m = { { 0.00, "Вот это ожерелье!" }, { 1.51, "Тебе удалось остановить хищение силы наших богов и ослабить Хаккара!" }, { 7.41, "Ты совершил настоящий подвиг." }, { 9.91, "Пусть головы этих презренных троллей продолжают умолять тебя о пощаде – даже после того, как в них остынет кровь." } }, f = { { 0.00, "Вот это ожерелье!" }, { 1.49, "Тебе удалось остановить хищение силы наших богов и ослабить Хаккара!" }, { 7.32, "Ты совершила настоящий подвиг." }, { 9.86, "Пусть головы этих презренных троллей продолжают умолять тебя о пощаде – даже после того, как в них остынет кровь." } } } } },
    [8221] = { t = { d = 10.8, v = "elemental-golem", n = { x = 73 }, c = { x = { { 1.66, "Опознание рыбы-ангела Кифера завершено." }, { 5.62, "Вы можете получить награду." } } } } },
    [8222] = { t = { d = 12.0, v = "gnome-male", n = { x = 112 }, c = { x = { { 0.00, "Чудесно, чудесно!" }, { 1.58, "Спасибо тебе." }, { 2.84, "Наварю краски и превращу вон ту кучу мусора в восхитительные сувениры!" }, { 9.00, "Вот твои купоны – удачно отдохнуть!" } } } } },
    [8223] = { t = { d = 3.2, v = "gnome-male", n = { x = 26 }, c = { x = { { 0.00, "Спасибо тебе." }, { 1.38, "А вот и твои купоны!" } } } } },
    [8224] = { t = { d = 10.1, v = "elemental-golem", n = { x = 74 }, c = { x = { { 1.66, "Опознание дезийской ставриды завершено." }, { 5.25, "Вы можете получить награду." } } } } },
    [8225] = { t = { d = 10.7, v = "elemental-golem", n = { x = 82 }, c = { x = { { 1.66, "Опознание синего полосатика Браунелла завершено." }, { 5.85, "Вы можете получить награду." } } } } },
    [8227] = { d = 11.5, v = "narrator", n = { x = 125 }, c = { x = { { 0.00, "Среди разбросанных рыболовных инструментов лежит свёрнутая шёлковая измерительная лента." }, { 6.92, "К ней прицеплена бирка с надписью:" }, { 9.65, "\"Нат Пэгл, Пылевые топи\"." } } }, t = { d = 21.8, g = 1, v = "human-male", n = { m = 247, f = 249 }, c = { m = { { 0.00, "О, тебе удалось отыскать мою измерительную ленту?" }, { 3.45, "Она мне очень дорога!" }, { 4.99, "Именно ею я измерял самых больших рыб, которых мне удавалось поймать..." }, { 9.92, "Но ведь я потерял свою ленту в Зул'Гурубе..." }, { 12.93, "Ты там был?" }, { 13.67, "Может быть, ты видел этого самого Газ'ранку, о котором рассказывают басни?" }, { 18.79, "Что ж... может быть, ты хочешь его поймать?" } }, f = { { 0.00, "О, тебе удалось отыскать мою измерительную ленту?" }, { 3.45, "Она мне очень дорога!" }, { 4.98, "Именно ею я измерял самых больших рыб, которых мне удавалось поймать..." }, { 9.90, "Но ведь я потерял свою ленту в Зул'Гурубе..." }, { 12.92, "Ты там была?" }, { 13.78, "Может быть, ты видела этого самого Газ'ранку, о котором рассказывают басни?" }, { 18.95, "Что ж... может быть, ты хочешь его поймать?" } } } } },
    [8228] = { t = { d = 7.9, v = "goblin-male", n = { x = 94 }, c = { x = { { 0.00, "В это воскресенье в Пиратской бухте пройдёт рыболовный конкурс!" }, { 4.59, "Вот правила турнира, если хочешь поучаствовать!" } } } } },
    [8229] = { t = { d = 5.9, v = "dwarf-male", n = { x = 62 }, c = { x = { { 0.00, "В воскресенье в Пиратской бухте будет рыбацкий конкурс!" }, { 4.48, "Вот, держи правила!" } } } } },
    [8231] = { d = 24.0, v = "creature/furbolg", n = { x = 201 }, c = { x = { { 0.43, "Волномёт – земноводное, встречающееся только в Азшаре." }, { 5.18, "Эти твари сильны и очень живучи." }, { 8.25, "В их твёрдой блестящей чешуе, как в зеркале, отражается мастерство охотника." }, { 14.94, "Выследи и убей нескольких волномётов на побережье Азшары и принеси мне их чешую." } } }, t = { d = 17.1, g = 1, v = "creature/furbolg", n = { m = 143, f = 144 }, c = { m = { { 0.43, "Волномёты – не самые слабые противники, особенно если пытаться биться с ними в воде – их естественной среде обитания." }, { 9.81, "Ты доказал, что можешь справиться с очень опасной добычей." } }, f = { { 0.56, "Волномёты – не самые слабые противники, особенно если пытаться биться с ними в воде – их естественной среде обитания." }, { 9.79, "Ты доказала, что можешь справиться с очень опасной добычей." } } } } },
    [8232] = { d = 35.7, g = 1, v = "creature/furbolg", n = { m = 298, f = 297 }, c = { m = { { 0.43, "Ты отправляешься на опасную охоту, герой." }, { 4.06, "Убей зелёного дракона Морфаза и принеси мне его зуб." }, { 8.65, "Морфаз обитает в Храме Атал'Хаккара." }, { 11.89, "Вход в него ты найдёшь на Болоте Печали." }, { 15.37, "Но помни, одному тебе его не осилить." }, { 18.77, "У дракона много врагов – найди соратников и уничтожь его!" }, { 23.91, "Зуб дракона – знак силы, которую охотник обретает рядом с соратниками." }, { 30.07, "Принеси его мне – и ты многому научишься." } }, f = { { 0.43, "Ты отправляешься на опасную охоту, героиня." }, { 4.21, "Убей зелёного дракона Морфаза и принеси мне его зуб." }, { 8.79, "Морфаз обитает в Храме Атал'Хаккара." }, { 12.02, "Вход в него ты найдёшь на Болоте Печали." }, { 15.49, "Но помни, одной тебе его не осилить." }, { 18.80, "У дракона много врагов – найди соратников и уничтожь его!" }, { 23.93, "Зуб дракона – знак силы, которую охотник обретает рядом с соратниками." }, { 30.08, "Принеси его мне – и ты многому научишься." } } }, t = { d = 13.1, g = 1, v = "creature/furbolg", n = { m = 79, f = 80 }, c = { m = { { 0.58, "Ты показал себя великим воителем." }, { 4.57, "Прими этот дар, я храню его с давних лет, когда сам был охотником." } }, f = { { 0.43, "Ты показала себя великим воителем." }, { 3.58, "Прими этот дар, я храню его с давних лет, когда сам был охотником." } } } } },
    [8233] = { d = 16.1, v = "human-male", n = { x = 198 }, c = { x = { { 0.00, "Лорд Джорах Чёрный Ворон настоятельно приглашает вас к себе." }, { 4.18, "Приглашение тайное, поэтому никаких подробностей." }, { 7.67, "Поместье Чёрного Ворона находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд." } } }, npc = { [3328] = { d = 18.2, v = "orc-male", n = { x = 198 }, c = { x = { { 0.00, "Лорд Джорах Чёрный Ворон настоятельно приглашает вас к себе." }, { 4.74, "Приглашение тайное, поэтому никаких подробностей." }, { 8.69, "Поместье Чёрного Ворона находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд." } } } }, [4163] = { d = 15.8, v = "nightelf-female#52", n = { x = 198 }, c = { x = { { 0.00, "Лорд Джорах Чёрный Ворон настоятельно приглашает вас к себе." }, { 4.12, "Приглашение тайное, поэтому никаких подробностей." }, { 7.55, "Поместье Чёрного Ворона находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд." } } } }, [5165] = { d = 16.6, v = "dwarf-male", n = { x = 198 }, c = { x = { { 0.00, "Лорд Джорах Чёрный Ворон настоятельно приглашает вас к себе." }, { 4.31, "Приглашение тайное, поэтому никаких подробностей." }, { 7.90, "Поместье Чёрного Ворона находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд." } } } } }, t = { d = 20.9, v = "human-male", n = { x = 218 }, c = { x = { { 0.00, "Добро пожаловать!" }, { 1.36, "Прошу вас, присаживайтесь." }, { 3.33, "Я хочу обсудить с вами одно простое дельце." }, { 6.74, "Видите ли, недавно я лишился кое-чего очень ценного, и, прямо говоря, хочу вернуть его любой ценой." }, { 14.50, "Это дело и для вас выгодное, да, очень выгодное." }, { 18.17, "Что скажете?" }, { 19.12, "Вы же любите приключения?" } } } } },
    [8234] = { d = 33.0, g = 1, v = "human-male", n = { m = 365, f = 367 }, c = { m = { { 0.00, "Начнём сначала." }, { 1.11, "Я потерял небольшую сумку голубого цвета." }, { 4.16, "В ней были мои личные вещи." }, { 6.25, "Нет нужды искать воров – они уже мертвы." }, { 9.30, "Мне известно лишь, что эти дураки не сумели открыть сумку и продали её какому-то шаману из племени Древобрюхов в Азшаре, выдав её за священную реликвию." }, { 20.24, "Очень умно." }, { 21.15, "Я хочу, чтобы ты отправился в Азшару и заполучил у шамана мою сумку – хитростью или силой." }, { 27.78, "Полагаю, что лучше всё же хитростью." }, { 30.39, "Сумку отнеси верховному магу Ксилему." } }, f = { { 0.00, "Начнём сначала." }, { 1.08, "Я потерял небольшую сумку голубого цвета." }, { 4.08, "В ней были мои личные вещи." }, { 6.12, "Нет нужды искать воров – они уже мертвы." }, { 9.11, "Мне известно лишь, что эти дураки не сумели открыть сумку и продали её какому-то шаману из племени Древобрюхов в Азшаре, выдав её за священную реликвию." }, { 19.82, "Очень умно." }, { 20.71, "Я хочу, чтобы ты отправилась в Азшару и заполучила у шамана мою сумку – хитростью или силой." }, { 27.34, "Полагаю, что лучше всё же хитростью." }, { 29.88, "Сумку отнеси верховному магу Ксилему." } } }, t = { d = 5.7, g = 1, v = "human-male", n = { m = 56, f = 57 }, c = { m = { { 0.00, "Вижу, у тебя сумка лорда Чёрного Ворона." }, { 3.27, "Что ж ты сразу не сказал, сынок?" } }, f = { { 0.00, "Вижу, у тебя сумка лорда Чёрного Ворона." }, { 3.14, "Что ж ты сразу не сказала, дочка?" } } } } },
    [8235] = { d = 28.3, v = "human-male", n = { x = 341 }, c = { x = { { 0.00, "Лорд Чёрный Ворон просил нас с тобой об услуге." }, { 3.18, "Он желает снять заклятие с этой сумки." }, { 5.81, "К сожалению, мои книги по снятию чар были захвачены и уничтожены дикарями." }, { 10.89, "Каждый клочок, оставшийся от них, невероятно ценен для меня." }, { 14.99, "Если ты сможешь принести мне зашифрованные фрагменты, я попробую восстановить хотя бы часть моих книг." }, { 21.84, "Чтобы найти фрагменты, поохоться на зверей Азшары – они обычно подбирают всё, что плохо лежит." } } }, t = { d = 6.8, g = 1, v = "human-male", n = { m = 75, f = 75 }, c = { m = { { 0.00, "Похоже, тебе удалось найти весьма ценные фрагменты." }, { 3.90, "Не так уж ты и бесполезен, в конце концов." } }, f = { { 0.00, "Похоже, тебе удалось найти весьма ценные фрагменты." }, { 3.77, "Не так уж ты и бесполезна, в конце концов." } } } } },
    [8236] = { d = 29.9, v = "human-male", n = { x = 352 }, c = { x = { { 0.00, "Мне потребуется время, чтобы расшифровать фрагменты и снять заклятие." }, { 4.86, "Когда я закончу, то самолично доставлю сумку лорду Чёрному Ворону." }, { 9.59, "Однако нам всё ещё нужен ключ." }, { 11.71, "Говорят, что ключ присвоил зелёный дракон по имени Морфаз." }, { 15.80, "Его логово находится в глубинах Храма Атал'Хаккара – вход в него ты найдёшь на Болоте Печали." }, { 22.39, "Собери своих сподвижников и отправляйся к логову дракона." }, { 26.48, "Лорд Чёрный Ворон ждёт, когда ты принесёшь ему ключ." } } }, t = { d = 22.6, v = "human-male", n = { x = 239 }, c = { x = { { 0.00, "Ключ!" }, { 0.39, "Я уже думал, что он потерян навеки!" }, { 3.03, "Прошу тебя, возьми что-то из зачарованной одежды из моих запасов." }, { 7.90, "Она предназначена для особо искусных разбойников." }, { 11.52, "Пусть все знают, что с тобой шутки плохи!" }, { 14.48, "*Джорах раскрывает сумку, и из неё вырывается золотое сияние.*" }, { 19.59, "*Джорах с изумлением смотрит внутрь...*" } } } } },
    [8238] = { t = { d = 15.8, v = "troll-male#77", n = { x = 158 }, c = { x = { { 0.00, "Отлично – эти монеты прекрасно дополнят мою коллекцию..." }, { 4.70, "Они нужны племени, чтобы помешать возрождению Кровавого бога." }, { 9.83, "Этот почётный знак – твой по праву, прими его вместе с нашей благодарностью!" } } } } },
    [8239] = { t = { d = 15.8, v = "troll-male#77", n = { x = 158 }, c = { x = { { 0.00, "Отлично – эти монеты прекрасно дополнят мою коллекцию..." }, { 4.67, "Они нужны племени, чтобы помешать возрождению Кровавого бога." }, { 9.78, "Этот почётный знак – твой по праву, прими его вместе с нашей благодарностью!" } } } } },
    [8240] = { d = 28.3, v = "troll-male#77", n = { x = 303 }, c = { x = { { 0.00, "Драгоценности Хаккари необходимо уничтожить." }, { 3.41, "Это наше внутреннее дело, но оно настолько важное, что мы просим о помощи и чужеземцев." }, { 10.23, "Отнеси любую драгоценность, найденную в Зул'Гурубе, на Алтарь Занзы и уничтожь её." }, { 16.56, "Только в этот раз я дам тебе за это дополнительный почётный знак нашего племени – сверх обычной награды." }, { 24.49, "Ступай, и да пребудет с тобой благословение Занзы!" } } }, t = { d = 33.2, g = 1, v = "troll-male#77", n = { m = 344, f = 345 }, c = { m = { { 0.00, "Отлично..." }, { 0.86, "Каждая драгоценность, которую удалось отнять у прислужников Кровавого бога – ещё один шаг к тому, чтобы покончить с ними навечно." }, { 11.22, "Ты оказал племени неоценимую услугу, и племя этого не забудет." }, { 16.26, "Помни, что найденные драгоценности нужно уничтожить на Алтаре Занзы." }, { 21.72, "За уничтожение каждой драгоценности ты получишь почётный знак племени!" }, { 27.19, "Для хранения почётных знаков тебе потребуется свободное место в сумках." } }, f = { { 0.00, "Отлично..." }, { 0.87, "Каждая драгоценность, которую удалось отнять у прислужников Кровавого бога – ещё один шаг к тому, чтобы покончить с ними навечно." }, { 11.36, "Ты оказала племени неоценимую услугу, и племя этого не забудет." }, { 16.53, "Помни, что найденные драгоценности нужно уничтожить на Алтаре Занзы." }, { 22.07, "За уничтожение каждой драгоценности ты получишь почётный знак племени!" }, { 27.60, "Для хранения почётных знаков тебе потребуется свободное место в сумках." } } } } },
    [8241] = { t = { d = 7.4, v = "dwarf-male", n = { x = 77 }, c = { x = { { 0.00, "Плавень в кузне лишним не бывает, поверь моему слову..." }, { 4.15, "Неси сколько можешь, пока не скажу – хватит." } } } } },
    [8242] = { t = { d = 7.4, v = "dwarf-male", n = { x = 77 }, c = { x = { { 0.00, "Плавень в кузне лишним не бывает, поверь моему слову..." }, { 4.19, "Неси сколько можешь, пока не скажу – хватит." } } } } },
    [8243] = { t = { d = 6.3, v = "troll-male#140", n = { x = 66 }, c = { x = { { 0.00, "Всё по-честному, приятель!" }, { 2.09, "Вот твой напиток – пусть он поможет в твоих странствиях!" } } } } },
    [8246] = { t = { d = 6.3, v = "troll-male#140", n = { x = 67 }, c = { x = { { 0.00, "Всё по-честному, приятель!" }, { 2.06, "Вот твой перстень – пусть он поможет в твоих странствиях!" } } } } },
    [8249] = { t = { d = 5.3, v = "human-male", n = { x = 61 }, c = { x = { { 0.00, "Да найдётся место для этих ножей в чьём-нибудь сердце." }, { 3.85, "В буквальном смысле." } } } } },
    [8250] = { d = 30.6, v = "human-male", n = { x = 352 }, c = { x = { { 0.00, "Верховный маг Ксилем ищет кого-то..." }, { 2.58, "Не менее опытного, чем ты." }, { 4.40, "Если хочешь, поговори с ним." }, { 6.41, "Он живёт в Азшаре, в башне на вершине утёса." }, { 9.42, "Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо." }, { 16.71, "Санат живёт в лагере ниже башни своего хозяина." }, { 20.10, "Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрёшься в скалы." } } }, npc = { [7311] = { d = 35.2, v = "troll-male", n = { x = 352 }, c = { x = { { 0.00, "Верховный маг Ксилем ищет кого-то..." }, { 2.96, "Не менее опытного, чем ты." }, { 5.05, "Если хочешь, поговори с ним." }, { 7.36, "Он живёт в Азшаре, в башне на вершине утёса." }, { 10.82, "Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо." }, { 19.19, "Санат живёт в лагере ниже башни своего хозяина." }, { 23.09, "Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрёшься в скалы." } } } }, [7312] = { d = 31.5, v = "gnome-male", n = { x = 352 }, c = { x = { { 0.00, "Верховный маг Ксилем ищет кого-то..." }, { 2.65, "Не менее опытного, чем ты." }, { 4.52, "Если хочешь, поговори с ним." }, { 6.59, "Он живёт в Азшаре, в башне на вершине утёса." }, { 9.69, "Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо." }, { 17.19, "Санат живёт в лагере ниже башни своего хозяина." }, { 20.68, "Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрёшься в скалы." } } } } }, t = { d = 5.7, v = "bloodelf-male", n = { x = 54 }, c = { x = { { 0.00, "*Санат смотрит на вас с презрением.*" }, { 3.04, "Верховный маг Ксилем ждёт тебя." } } } } },
    [8251] = { d = 29.0, v = "human-male", n = { x = 340 }, c = { x = { { 0.00, "Эльфы крови в Азшаре изобрели свой способ распылять магические предметы." }, { 5.16, "Получаемая в результате сияющая пыль отличается от элементов, получаемых в результате обычного распыления." }, { 12.55, "Я отправил ученика купить этой пыли, но эльфы безжалостно убили его." }, { 17.51, "Они должны заплатить за это!" }, { 19.61, "Время мирных переговоров прошло." }, { 21.97, "Найди эльфов крови в скалах Азшары и примени к ним более... убедительные методы." }, { 27.70, "Мне нужна эта пыль." } } }, t = { d = 6.5, v = "human-male", n = { x = 73 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.34, "Не перестаю удивляться, как убедителен бывает залп чародейских стрел." } } } } },
    [8252] = { d = 29.7, v = "human-male", n = { x = 362 }, c = { x = { { 0.00, "Оглянись вокруг." }, { 1.16, "Развалины и всё побережье кишат тварями Бича Злобы." }, { 4.72, "Проклятые создания научились искать редкие вещества и предметы, встречающиеся в Азшаре." }, { 10.65, "Например, эти твари почему-то очень интересуются заколдованными кораллами – по совершенно не ясным мне причинам." }, { 18.25, "Теперь этих кораллов в бухте почти не осталось, а они так нужны мне для исследований!" }, { 24.07, "Прошу тебя, отбери несколько кораллов у сирен из клана Бича Злобы и принеси их мне." } } }, t = { d = 14.2, g = 1, v = "human-male", n = { m = 155, f = 156 }, c = { m = { { 0.00, "Превосходный образец коралла." }, { 2.31, "Твоё мастерство, без сомнения, точно и смертоносно." }, { 6.22, "Не думай, что твои старания остались незамеченными." }, { 10.20, "Возможно, ты достоин настоящего испытания своих сил..." } }, f = { { 0.00, "Превосходный образец коралла." }, { 2.22, "Твоё мастерство, без сомнения, точно и смертоносно." }, { 5.98, "Не думай, что твои старания остались незамеченными." }, { 9.81, "Возможно, ты достойна настоящего испытания своих сил..." } } } } },
    [8253] = { d = 27.8, v = "human-male", n = { x = 313 }, c = { x = { { 0.00, "В глубинах Храма Атал'Хаккара скрывается зелёный дракон по имени Морфаз." }, { 5.38, "Много лет назад он напал на меня из засады и проглотил целиком сопровождавшего меня ученика." }, { 12.31, "Мне не впервой терять ученика, однако именно этот, проглоченный, нёс кристалл тайной магии небывалой мощи." }, { 20.31, "Выбери достаточно сильных соратников и отправляйся в храм." }, { 24.61, "Уничтожь Морфаза и принеси мне мой кристалл." } } }, t = { d = 16.7, v = "human-male", n = { x = 178 }, c = { x = { { 0.00, "Невероятно." }, { 0.90, "За долгие годы осколок вырос, впитывая энергию дракона." }, { 5.25, "Больше мне не о чем тебя просить." }, { 7.81, "С этим осколком ко мне вернулся весь мой дар чародейской ковки." }, { 12.58, "Моё первое творение – твоё, тебе остаётся лишь выбрать..." } } } } },
    [8254] = { d = 19.0, v = "human-male", n = { x = 212 }, c = { x = { { 0.00, "Служителям богов пристало помогать попавшим в беду." }, { 3.81, "Как именно – неважно, главное – во имя чего." }, { 7.10, "Кругу Кенария необходима помощь." }, { 9.53, "Если ты хочешь протянуть им руку помощи, поговори с Огтинком." }, { 14.06, "Он живёт на вершинах скал на северо-востоке от руин Эльдарата в Азшаре." } } }, npc = { [6018] = { d = 21.3, v = "troll-male#77", n = { x = 212 }, c = { x = { { 0.00, "Служителям богов пристало помогать попавшим в беду." }, { 4.26, "Как именно – неважно, главное – во имя чего." }, { 7.93, "Кругу Кенария необходима помощь." }, { 10.64, "Если ты хочешь протянуть им руку помощи, поговори с Огтинком." }, { 15.71, "Он живёт на вершинах скал на северо-востоке от руин Эльдарата в Азшаре." } } } }, [11406] = { d = 19.5, v = "dwarf-male", n = { x = 212 }, c = { x = { { 0.00, "Служителям богов пристало помогать попавшим в беду." }, { 3.91, "Как именно – неважно, главное – во имя чего." }, { 7.27, "Кругу Кенария необходима помощь." }, { 9.77, "Если ты хочешь протянуть им руку помощи, поговори с Огтинком." }, { 14.41, "Он живёт на вершинах скал на северо-востоке от руин Эльдарата в Азшаре." } } } } }, t = { d = 12.2, v = "creature/furbolg", n = { x = 77 }, c = { x = { { 0.56, "Я очень рад твоему приходу." }, { 3.14, "У меня словно камень с души свалился." }, { 6.71, "Нам предстоит очень много дел." } } } } },
    [8255] = { d = 41.6, v = "creature/furbolg", n = { x = 406 }, c = { x = { { 0.58, "Мохноногие олени, обитающие в Азшаре, – самые великолепные создания, когда-либо населявшие Осквернённый лес." }, { 9.19, "Они наделены естественной невосприимчивостью ко всем болезням и ядам, поэтому порча не коснулась их." }, { 17.21, "Мудрые животные предпочли покинуть заражённые земли." }, { 21.45, "К прискорбию своему я должен просить тебя поохотиться на этих прекрасных созданий, поскольку их железы необходимы для изготовления целительного снадобья." }, { 33.78, "Снадобья, которое вернёт Осквернённому лесу его прежний облик." } } }, t = { d = 26.9, v = "creature/furbolg", n = { x = 251 }, c = { x = { { 0.58, "Сама судьба привела тебя сюда." }, { 3.10, "Вера твоя не противоречит тому, что должно исполнить для создания снадобья." }, { 8.98, "Видишь ли, Круг Кенария считает этих беговых оленей священными животными, убийство которых невозможно ни при каких обстоятельствах." }, { 19.13, "Если бы им пришлось это сделать, это сильно подорвало бы их дух." } } } } },
    [8256] = { d = 42.4, v = "creature/furbolg", n = { x = 428 }, c = { x = { { 0.58, "Чтобы получить целительное снадобье, воспользуемся простым рецептом: смешаем одну часть яда с двумя благотворными субстанциями." }, { 10.37, "Один целительный компонент у нас уже есть, теперь надо добыть яд." }, { 15.44, "Самые могущественные твари нежити, такие как неупокоенные высокорождённые, скитающиеся по руинам Эльдарата, часто настолько сильно поражены порчей, что она принимает вполне осязаемую форму зелёной слизи." }, { 31.00, "Среди живых эта субстанция известна как лимфа нежити." }, { 35.24, "Это очень мощный яд, поэтому потребуется лишь одна мера." } } }, t = { d = 14.3, v = "creature/furbolg", n = { x = 102 }, c = { x = { { 0.43, "Да, не самое приятное зрелище..." }, { 3.43, "Но, как это ни печально, эта мерзкая субстанция необходима для создания целебной мази." }, { 11.44, "Спасибо." } } } } },
    [8257] = { d = 43.1, v = "creature/furbolg", n = { x = 458 }, c = { x = { { 0.43, "Теперь нам нужен последний целительный компонент." }, { 4.17, "Известно, что зелёный дракон Морфаз наделён невосприимчивостью ко всем болезням и ядам." }, { 10.57, "Это знание досталось дорогой ценой – не один друид погиб, пытаясь справиться с драконом." }, { 17.38, "Уверен, его кровь послужит отличным компонентом для нашего снадобья." }, { 22.55, "Посланник Круга Кенария заберёт уже собранные тобой компоненты, пока ты будешь добывать последний." }, { 30.04, "Собери соратников и отправляйся в логово зелёного дракона в затонувший храм Атал'Хаккара." }, { 36.64, "Принеси его кровь Грете Замшелому Копыту в Осквернённый лес." } } }, t = { d = 20.9, v = "tauren-female#71", n = { x = 220 }, c = { x = { { 0.00, "Не могу поверить... тебе действительно удалось справиться с драконом и добыть его кровь!" }, { 6.99, "Мы немедленно приготовим снадобье и начнём исцеление растений и животных Осквернённого леса." }, { 14.12, "Это займёт очень много времени, но теперь мы можем это сделать – и всё благодаря тебе!" } } } } },
    [8258] = { d = 36.5, v = "tauren-male#68", n = { x = 371 }, c = { x = { { 0.00, "Тёмный Терзатель, рыцарь смерти, владычествует над Главным склепом в Некроситете." }, { 6.61, "Он собирается подчинить себе весь мир духов!" }, { 10.25, "Его необходимо остановить!" }, { 12.48, "Тут-то тебе и понадобится кристальный предсказатель." }, { 16.79, "Приведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Тёмного Терзателя." }, { 24.45, "Когда ты одолеешь этих духов, явится сам рыцарь смерти." }, { 29.13, "Принеси мне его голову!" }, { 31.14, "Только его гибель способна исправить урон, нанесённый миру духов!" } } }, t = { d = 30.4, g = 1, v = "tauren-male#68", n = { m = 281, f = 282 }, c = { m = { { 0.00, "Это победа, которой стоит насладиться!" }, { 3.41, "Гибель Тёмного Терзателя должна восстановить хрупкие узы, скрепляющие мир духов." }, { 10.32, "Ты сделал гораздо больше, чем от тебя просили, даже не помышляя о награде." }, { 16.75, "Ты по-настоящему достойный герой, друг мой." }, { 20.40, "Знаю, что защита мира духов – уже сама по себе награда, но прошу, прими этот скромный дар в знак моей благодарности." } }, f = { { 0.00, "Это победа, которой стоит насладиться!" }, { 3.38, "Гибель Тёмного Терзателя должна восстановить хрупкие узы, скрепляющие мир духов." }, { 10.21, "Ты сделала гораздо больше, чем от тебя просили, даже не помышляя о награде." }, { 16.66, "Ты по-настоящему достойная героиня, друг мой." }, { 20.42, "Знаю, что защита мира духов – уже сама по себе награда, но прошу, прими этот скромный дар в знак моей благодарности." } } } } },
    [8259] = { t = { d = 20.6, g = 1, v = "tauren-male#68", n = { m = 173, f = 174 }, c = { m = { { 0.00, "А... твой подвиг в битве с Тёмным Терзателем был выдающимся – и, позволю себе заметить, заслуживал куда лучшей награды, чем та, что ты получил." }, { 12.95, "Прошу, прими этот шлем в дар за твои свершения в Некроситете." }, { 18.59, "Ещё раз спасибо." } }, f = { { 0.00, "А... твой подвиг в битве с Тёмным Терзателем был выдающимся – и, позволю себе заметить, заслуживал куда лучшей награды, чем та, что ты получила." }, { 13.39, "Прошу, прими этот шлем в дар за твои свершения в Некроситете." }, { 19.19, "Ещё раз спасибо." } } } } },
    [8260] = { t = { d = 23.0, v = "human-male#116", n = { x = 288 }, c = { x = { { 0.00, "Ты, несомненно, начинаешь доказывать нам свою преданность." }, { 3.79, "В награду прими этот полевой комплект!" }, { 6.34, "Внутри ты найдёшь провизию и бинты, которые можно использовать только в Низине Арати." }, { 11.97, "Чем больше ты будешь проявлять себя в Низине, тем больше таких вещей сможешь у нас покупать." }, { 18.08, "Провизия станет доступна при отношении «Дружелюбие», а бинты – при «Уважении»." } } } } },
    [8261] = { t = { d = 22.9, v = "human-male#116", n = { x = 288 }, c = { x = { { 0.00, "Ты, несомненно, начинаешь доказывать нам свою преданность." }, { 3.77, "В награду прими этот полевой комплект!" }, { 6.30, "Внутри ты найдёшь провизию и бинты, которые можно использовать только в Низине Арати." }, { 11.89, "Чем больше ты будешь проявлять себя в Низине, тем больше таких вещей сможешь у нас покупать." }, { 17.96, "Провизия станет доступна при отношении «Дружелюбие», а бинты – при «Уважении»." } } } } },
    [8262] = { t = { d = 23.1, v = "human-male#116", n = { x = 288 }, c = { x = { { 0.00, "Ты, несомненно, начинаешь доказывать нам свою преданность." }, { 3.81, "В награду прими этот полевой комплект!" }, { 6.37, "Внутри ты найдёшь провизию и бинты, которые можно использовать только в Низине Арати." }, { 12.02, "Чем больше ты будешь проявлять себя в Низине, тем больше таких вещей сможешь у нас покупать." }, { 18.14, "Провизия станет доступна при отношении «Дружелюбие», а бинты – при «Уважении»." } } } } },
    [8264] = { t = { d = 26.5, v = "scourge-male#144", n = { x = 286 }, c = { x = { { 0.00, "Ты, несомненно, начинаешь доказывать нам свою преданность." }, { 4.38, "В награду прими этот полевой комплект!" }, { 7.32, "Внутри ты найдёшь провизию и бинты, которые можно использовать только в Низине Арати." }, { 13.83, "Чем больше ты будешь проявлять себя в Низине, тем больше таких вещей сможешь у нас покупать." }, { 20.88, "Провизия станет доступна при отношении «Уважение», а бинты – при «Почтении»." } } } } },
    [8265] = { t = { d = 26.9, v = "scourge-male#144", n = { x = 286 }, c = { x = { { 0.00, "Ты, несомненно, начинаешь доказывать нам свою преданность." }, { 4.45, "В награду прими этот полевой комплект!" }, { 7.43, "Внутри ты найдёшь провизию и бинты, которые можно использовать только в Низине Арати." }, { 14.04, "Чем больше ты будешь проявлять себя в Низине, тем больше таких вещей сможешь у нас покупать." }, { 21.19, "Провизия станет доступна при отношении «Уважение», а бинты – при «Почтении»." } } } } },
    [8271] = { t = { d = 9.5, v = "dwarf-female#33", n = { x = 97 }, c = { x = { { 0.00, "Как герой клана Грозовой Вершины, ты можешь выбрать один предмет из этих недавно награбл... кхм, возвращённых сокровищ." } } } } },
    [8272] = { t = { d = 11.8, v = "orc-male", n = { x = 113 }, c = { x = { { 0.00, "Ну как?" }, { 0.62, "Каково это – сокрушать врагов и смотреть, как их строй разваливается?" }, { 6.46, "Приятно, правда?" }, { 7.92, "Ты заслуживаешь награды за этот подвиг, солдат." } } } } },
    [8273] = { t = { d = 22.6, g = 1, v = "scourge-female#79", n = { m = 229, f = 229 }, c = { m = { { 0.00, "Ну разве не любопытно?" }, { 1.82, "Говоришь, ты нашёл эту табличку на маленьком необитаемом островке у Обзорных скал во Внутренних землях, герой?" }, { 10.63, "Весьма любопытно." }, { 12.08, "Благодарю тебя за старания." }, { 14.34, "Наша Тёмная Госпожа будет очень довольна этой находкой." }, { 18.93, "Вот, позволь мне вознаградить тебя по заслугам." } }, f = { { 0.00, "Ну разве не любопытно?" }, { 1.75, "Говоришь, ты нашла эту табличку на маленьком необитаемом островке у Обзорных скал во Внутренних землях, героиня?" }, { 10.44, "Весьма любопытно." }, { 11.84, "Благодарю тебя за старания." }, { 14.01, "Наша Тёмная Госпожа будет очень довольна этой находкой." }, { 18.43, "Вот, позволь мне вознаградить тебя по заслугам." } } } } },
    [8275] = { d = 32.2, v = "nightelf-female#51", n = { x = 380 }, c = { x = { { 0.00, "Слушайте, герои Альянса!" }, { 1.78, "Мы слишком долго не обращали внимания на опасность, источник которой – силитиды." }, { 7.46, "Им никто не противостоял, и мерзкие насекомые подготовились к масштабному вторжению." }, { 13.32, "Силы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно!" }, { 19.44, "Мы не позволим им и дальше осквернять нашу землю!" }, { 22.95, "Все на защиту Азерота!" }, { 24.54, "Все, способные держать оружие, должны пройти инструктаж у призывательницы ветров Гордый Рог в крепости Кенария!" } } }, t = { d = 23.5, g = 1, v = "tauren-female#71", n = { x = 242 }, c = { m = { { 0.00, "Отлично, ещё один доброволец готов выступить против силитидов." }, { 5.01, "Добро пожаловать в крепость Кенария, герой." }, { 8.51, "Я рада, что слова наших посланников привлекают героев вроде тебя." }, { 13.80, "У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников." } }, f = { { 0.00, "Отлично, ещё один доброволец готов выступить против силитидов." }, { 4.98, "Добро пожаловать в крепость Кенария, героиня." }, { 8.60, "Я рада, что слова наших посланников привлекают героев вроде тебя." }, { 13.86, "У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников." } } } } },
    [8276] = { d = 36.8, v = "tauren-male", n = { x = 376 }, c = { x = { { 0.00, "Слушайте, герои Орды!" }, { 1.85, "Мы слишком долго не обращали внимания на серьёзную угрозу." }, { 6.58, "Дрожание земли рядом с ульями силитидов говорит о серьёзном возрастании их числа в связи с готовящимся нападением." }, { 15.89, "Силы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно!" }, { 22.99, "Мы не позволим им и дальше осквернять нашу землю!" }, { 27.05, "Все, способные держать оружие, должны обратиться к призывательнице ветров Гордый Рог в крепости Кенария!" }, { 35.55, "Смерть силитидам!" } } }, t = { d = 23.4, g = 1, v = "tauren-female#71", n = { x = 242 }, c = { m = { { 0.00, "Отлично, ещё один доброволец готов выступить против силитидов." }, { 4.99, "Добро пожаловать в крепость Кенария, герой." }, { 8.48, "Я рада, что слова наших посланников привлекают героев вроде тебя." }, { 13.76, "У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников." } }, f = { { 0.00, "Отлично, ещё один доброволец готов выступить против силитидов." }, { 4.93, "Добро пожаловать в крепость Кенария, героиня." }, { 8.51, "Я рада, что слова наших посланников привлекают героев вроде тебя." }, { 13.72, "У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников." } } } } },
    [8277] = { d = 36.3, v = "goblin-female#63", n = { x = 434 }, c = { x = { { 0.00, "Битисса Шаткобрус к твоим услугам!" }, { 2.45, "Мой кузен Ноггл зарабатывает на жизнь, продавая алхимикам из крепости Кенария редкие травы." }, { 9.15, "Точнее, зарабатывал." }, { 10.60, "Из последней вылазки он вернулся отравленный страшным ядом." }, { 14.74, "Я сумела замедлить действие яда, но чтобы полностью нейтрализовать его, мне понадобятся образцы яда тех тварей, что ужалили его." }, { 23.73, "Ноггл вернулся с севера, поэтому я готова поспорить, что он пострадал от камнехвостых скорпидов или песчаных пауков-быстроногов." }, { 32.59, "Принеси мне несколько жал и жвал, и я сделаю противоядие." } } }, t = { d = 5.6, v = "goblin-female#63", n = { x = 59 }, c = { x = { { 0.00, "Скрести пальцы, дружище!" }, { 1.99, "Будем надеяться, что нам удастся спасти Ноггла!" } } } } },
    [8278] = { d = 26.6, v = "goblin-female#63", n = { x = 325 }, c = { x = { { 0.00, "Проклятье!" }, { 0.74, "Противоядие не сработало." }, { 2.46, "Наверное, Ноггла укусила одна из тварей на далёком юге, они гораздо страшнее остальных." }, { 8.50, "Придётся попросить тебя отправиться за образцами." }, { 11.82, "В утешение могу сказать, что поскольку яд у них сильный, мне потребуется не так много образцов, как в прошлый раз." }, { 19.46, "С другой стороны, на юге больше ядовитых тварей, поэтому придётся убить по несколько существ разных видов." } } }, t = { d = 5.8, v = "goblin-female#63", n = { x = 48 }, c = { x = { { 0.00, "Да!" }, { 0.34, "Похоже, сработало, Ноггл приходит в себя." }, { 4.23, "Мы у тебя в долгу!" } } } } },
    [8279] = { d = 32.3, v = "human-male", n = { x = 377 }, c = { x = { { 0.00, "Сумеречный Молот не прощает тех, кто покидает его ряды." }, { 3.84, "Они охотятся за мной, словно за диким зверем!" }, { 7.00, "Излишне говорить, что их враги – мои друзья!" }, { 10.09, "Чтобы расшифровать эту табличку, мне понадобится книга, которой пользуются их писцы при закодировании тайных посланий, Сумеречный словарь." }, { 19.34, "Эта книга настолько важна, что три её главы держат в разных местах!" }, { 24.65, "Главы находятся у особых офицеров, именуемых сумеречными хранителями." }, { 29.94, "Ищи их в лагерях Сумеречного Молота." } } }, t = { d = 15.4, v = "human-male", n = { x = 141 }, c = { x = { { 0.00, "Ура!" }, { 0.46, "Вот они, все части книги!" }, { 2.68, "Приступим." }, { 3.59, "Заменить каждое третье слово словами из второй главы..." }, { 8.41, "Потом заменить каждое второе слово словами из первой главы..." }, { 13.76, "Стоп, я что-то путаю?" } } } } },
    [8280] = { d = 31.6, v = "tauren-female#71", n = { x = 358 }, c = { x = { { 0.00, "Крепость Кенария имеет важнейшее стратегическое значение." }, { 4.35, "Не сомневаюсь, что пока мы удерживаем её, силитидам нас не одолеть." }, { 9.31, "Разумеется, если припасы будут поступать регулярно." }, { 13.26, "Песчаные черви оказались даже большей помехой для наших караванов, чем сами силитиды." }, { 19.78, "Например, сегодня утром землечерпы разграбили большой караван с рассветницей." }, { 25.63, "Необходимо сократить число этих тварей, чтобы обеспечить бесперебойные поставки." } } }, t = { d = 8.5, g = 1, v = "tauren-female#71", n = { m = 77, f = 78 }, c = { m = { { 0.00, "Прими мою глубочайшую благодарность." }, { 3.35, "Помогая крепости Кенария, ты проявил редкое мужество." } }, f = { { 0.00, "Прими мою глубочайшую благодарность." }, { 3.47, "Помогая крепости Кенария, ты проявила редкое мужество." } } } } },
    [8281] = { d = 25.5, g = 1, v = "tauren-female#71", n = { m = 270, f = 271 }, c = { m = { { 0.00, "Ты великолепно себя зарекомендовал." }, { 2.73, "К сожалению, нашему снабжению по-прежнему грозит опасность." }, { 7.35, "Землечерпов теперь нет, но их место несомненно займут их более крупные южные родственники – земляные сокрушители." }, { 16.11, "Чтобы приструнить этих червяков, придётся убить их побольше." }, { 20.80, "Но мы не можем подвергать опасности наше снабжение." } }, f = { { 0.00, "Ты великолепно себя зарекомендовала." }, { 2.89, "К сожалению, нашему снабжению по-прежнему грозит опасность." }, { 7.67, "Землечерпов теперь нет, но их место несомненно займут их более крупные южные родственники – земляные сокрушители." }, { 16.71, "Чтобы приструнить этих червяков, придётся убить их побольше." }, { 21.55, "Но мы не можем подвергать опасности наше снабжение." } } }, t = { d = 6.9, g = 1, v = "tauren-female#71", n = { m = 68, f = 69 }, c = { m = { { 0.00, "Великолепно!" }, { 1.11, "Ты оказался ценным союзником в подготовке к войне против силитидов." } }, f = { { 0.00, "Великолепно!" }, { 1.09, "Ты оказалась ценной союзницей в подготовке к войне против силитидов." } } } } },
    [8282] = { d = 31.9, v = "goblin-male", n = { x = 344 }, c = { x = { { 0.00, "Где я?" }, { 0.47, "Где моя сумка?" }, { 1.61, "Наверное, я потерял её, убегая от Смертехвата, огромного скорпида." }, { 7.03, "Я мчался, не разбирая дороги, и забрёл прямо в гнездо камнехвостых живодёров." }, { 12.65, "В моей сумке были ценнейшие реагенты." }, { 15.53, "Без них мы с Битиссой не сможем делать зелья для крепости Кенария." }, { 20.42, "Я пока не в силах встать, но если ты сможешь вернуть мне реагенты, я тебе отплачу сторицей." }, { 27.18, "На Смертехвата я наткнулся в южных горах, за лагерем Бронзоборода." } } }, t = { d = 8.6, g = 1, v = "goblin-male", n = { m = 70, f = 72 }, c = { m = { { 0.00, "Да!" }, { 0.35, "Ты принёс мне сумку." }, { 2.25, "И все ценные реагенты вместе с ней!" }, { 5.62, "Я твой должник на долгие годы." } }, f = { { 0.00, "Да!" }, { 0.34, "Ты принесла мне сумку." }, { 2.48, "И все ценные реагенты вместе с ней!" }, { 5.82, "Я твой должник на долгие годы." } } } } },
    [8283] = { d = 28.5, v = "narrator", n = { x = 315 }, c = { x = { { 0.00, "Согласно последним сведениям, ужасный скорпион, Смертехват, отступил в южные горы перед лицом нашествия силитидов." }, { 8.92, "Эта тварь представляет большую угрозу патрулям и экспедициям южных регионов." }, { 14.84, "Тех, кто поспособствует её уничтожению, будет ждать неплохая награда." }, { 20.06, "По вопросам получения награды обращаться к капитану Вишу Коцусу, на вершину сторожевой башни крепости Кенария." } } }, t = { d = 10.7, v = "nightelf-male#54", n = { x = 104 }, c = { x = { { 0.00, "Замечательно!" }, { 1.17, "Смертехвата нет, и мы сможем спокойно подобраться к ульям силитидов по южным горам." }, { 8.31, "Мы высоко ценим твою работу." } } } } },
    [8284] = { d = 28.8, v = "dwarf-female#34", n = { x = 349 }, c = { x = { { 0.00, "На северо-западе отсюда некогда благоденствовал лагерь культистов Сумеречного Молота." }, { 5.98, "Теперь на месте лагеря остались лишь обломки древесины и ткани, среди которых бродят элементали." }, { 12.77, "Мне удалось добыть там несколько кусочков глиняной таблички, но их слишком мало, чтобы узнать что-нибудь ценное." }, { 20.64, "Не сможешь ли ты добыть остальные фрагменты?" }, { 23.72, "Быть может, они прольют свет на деятельность Сумеречного Молота в Силитусе." } } }, t = { d = 16.8, v = "dwarf-female#34", n = { x = 183 }, c = { x = { { 0.00, "Так я и думала." }, { 1.15, "Я могу перевести отдельные слова, но они лишены смысла." }, { 5.42, "Сумеречный Молот часто пользуется особыми шифрами, чтобы скрыть значение своих текстов от чужих; нужно найти кого-нибудь, кто разбирается в таких вещах." } } } } },
    [8285] = { d = 21.5, v = "dwarf-female#34", n = { x = 236 }, c = { x = { { 0.00, "Ходят слухи, что некто по имени Ортелл вышел из рядов Сумеречного Молота." }, { 5.64, "Говорят, он прячется в горах на юге от деревни Южного Ветра и живёт в полном уединении." }, { 12.23, "Может быть, имеет смысл прибегнуть к его помощи в расшифровании таблички." }, { 17.73, "Возьми восстановленную табличку и отнеси её Ортеллу." } } }, t = { d = 13.3, v = "human-male", n = { x = 165 }, c = { x = { { 0.00, "Вижу, ты не понаслышке знаешь о моей бывшей организации." }, { 3.74, "Должно быть, ты из крепости Кенария." }, { 6.12, "Тебе нужна информация для борьбы с Сумеречным Молотом?" }, { 9.74, "Подойди ближе, может быть, мы сможем помочь друг другу." } } } } },
    [8286] = { d = 35.2, v = "nightelf-male#59", n = { x = 384 }, c = { x = { { 0.00, "Я уже почти очутился в объятьях смерти, и тут вмешался он." }, { 4.36, "Лишь раз дохнул он на моё искалеченное тело, а затем оставалось лишь дождаться, пока пески времени исцелят мои раны." }, { 13.01, "\"Навеки останешься ты, коли так нужно,\" сказал он, и с этими словами сделал меня Стражем." }, { 19.72, "Только взгляни на пустыню." }, { 21.73, "Вторая война неминуема." }, { 23.54, "Найди тайное укрытие бронзовых драконов." }, { 26.63, "Отправляйся в Пещеры Времени и узнай, не вернулся ли повелитель." }, { 31.39, "Я должен знать наверняка, иначе не смогу действовать." } } }, t = { d = 5.8, v = "nightelf-male#59", n = { x = 54 }, c = { x = { { 0.00, "Так и предначертано – восстал великий." }, { 3.32, "Моё бдение подходит к концу..." } } } } },
    [8287] = { d = 23.1, v = "human-male", n = { x = 269 }, c = { x = { { 0.00, "Ну вот..." }, { 0.63, "Ценная информация, скажу я тебе!" }, { 2.94, "Я видел, как силы Круга Кенария прибыли в Силитус." }, { 6.50, "Они планируют выбить из наших краёв Сумеречный Молот, верно?" }, { 10.76, "Это поспособствует воплощению их планов." }, { 13.57, "Отнеси этот пергамент их главе, командиру Мар'алиту." }, { 17.26, "Скоро Сумеречный Молот изгонят из этих земель и их жадные ручки до меня не дотянутся!" } } }, t = { d = 13.2, g = 1, v = "nightelf-male#54", n = { x = 137 }, c = { m = { { 0.00, "Очень интересные сведения." }, { 2.07, "Они проливают свет на деятельность Сумеречного Молота в Силитусе и несомненно помогут бороться с этой сектой." }, { 10.41, "Вот тебе награда за труды, герой." } }, f = { { 0.00, "Очень интересные сведения." }, { 2.10, "Они проливают свет на деятельность Сумеречного Молота в Силитусе и несомненно помогут бороться с этой сектой." }, { 10.55, "Вот тебе награда за труды, героиня." } } } } },
    [8288] = { d = 33.9, v = "nightelf-male#59", n = { x = 373 }, c = { x = { { 0.00, "Время у нас на исходе!" }, { 1.70, "Нам необходим герой!" }, { 3.26, "Выполнить моё задание под силу лишь целой армии, но только одному из целой толпы будущих героев суждено принять на себя тяжкую ношу ответственности – стать союзником Рода Ноздорму." }, { 16.93, "В логове повелителя Чёрной горы живёт жестокий зверь, предводитель драконов Разящий Бич." }, { 23.46, "Он охраняет Зал Раздора, перекрывая путь в покои Нефариана." }, { 27.88, "Убей гнусную тварь и принеси мне её голову." }, { 31.14, "Это будет первым шагом на твоём пути." } } }, t = { d = 5.1, v = "nightelf-male#59", n = { x = 59 }, c = { x = { { 0.00, "Неужели ты станешь первым союзником бронзовых драконов за тысячу лет?" } } } } },
    [8290] = { d = 28.0, g = 1, v = "nightelf-female#51", n = { m = 311, f = 311 }, c = { m = { { 0.00, "Юный герой!" }, { 0.92, "Миновав этот проход, ты увидишь поле яростных сражений." }, { 5.07, "Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину!" }, { 13.18, "Отправляйся в Ущелье Песни Войны, чтобы оборонять Крепость Среброкрылых!" }, { 18.52, "Отражай нападения ордынских захватчиков!" }, { 21.48, "Наградой тебе будет талисман заслуг." }, { 24.25, "Принеси мне такой талисман, и получишь награду!" } }, f = { { 0.00, "Юная героиня!" }, { 1.06, "Миновав этот проход, ты увидишь поле яростных сражений." }, { 5.26, "Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину!" }, { 13.44, "Отправляйся в Ущелье Песни Войны, чтобы оборонять Крепость Среброкрылых!" }, { 18.83, "Отражай нападения ордынских захватчиков!" }, { 21.83, "Наградой тебе будет талисман заслуг." }, { 24.62, "Принеси мне такой талисман, и получишь награду!" } } } },
