    [8294] = { d = 38.0, g = 1, v = "orc-male", n = { x = 378 }, c = { m = { { 0.00, "Чащобы Ясеневого леса падут пред мощью Орды, герой!" }, { 4.34, "Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором." }, { 10.81, "Калимдор – это владения Орды!" }, { 13.31, "Как смеют они препятствовать нам пользоваться тем, что по праву наше?" }, { 18.89, "Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду!" }, { 27.35, "Разгроми часовых из клана Среброкрылых и заслужи почётный знак Ущелья Песни Войны." }, { 34.04, "Вернись ко мне с этим знаком – и получишь награду!" } }, f = { { 0.00, "Чащобы Ясеневого леса падут пред мощью Орды, героиня!" }, { 4.44, "Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором." }, { 10.84, "Калимдор – это владения Орды!" }, { 13.32, "Как смеют они препятствовать нам пользоваться тем, что по праву наше?" }, { 18.85, "Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду!" }, { 27.22, "Разгроми часовых из клана Среброкрылых и заслужи почётный знак Ущелья Песни Войны." }, { 33.84, "Вернись ко мне с этим знаком – и получишь награду!" } } } },
