    [8297] = { d = 34.7, v = "human-female#47", n = { x = 397 }, c = { x = { { 0.00, "Войну выигрывают солдаты, любой солдат вам это скажет." }, { 3.90, "Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна, ещё не начавшись!" }, { 11.77, "Вот почему так важна Низина Арати." }, { 14.22, "В этой низине есть ключевые точки, где сосредоточены важные ресурсы." }, { 19.00, "Металл, оружие, пища, древесина – всё это необходимо, и всё можно добыть там." }, { 24.42, "И вот чего я хочу от вас." }, { 26.18, "Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами." } } } },
    [8299] = { d = 49.4, v = "scourge-male", n = { x = 492 }, c = { x = { { 0.00, "Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати." }, { 6.42, "Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдалённую область, намереваясь распространить свои владения за пределы Опорного пункта." }, { 19.03, "Мы должны остановить их, а наилучшее средство для этого – захватить их припасы." }, { 25.68, "Вы можете нам помочь." }, { 27.51, "Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками." }, { 37.06, "Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть." } } } },
    [8301] = { d = 29.8, g = 1, v = "nightelf-male#59", n = { m = 339, f = 341 }, c = { m = { { 0.00, "Род Ноздорму инстинктивно не верит низшим расам." }, { 3.34, "Хоть ты и смог доказать мне, что у тебя задатки настоящего героя, пришло время доказать это моему повелителю." }, { 10.97, "Улей Аши, улей Зора и улей Регал кишат силитидами, которые грозят нашему существованию." }, { 17.27, "Убей как можно больше проклятых тварей и принеси мне фрагменты их панцирей." }, { 22.56, "Когда у тебя закончится место в заплечных мешках, возвращайся и я укреплю твою решимость." } }, f = { { 0.00, "Род Ноздорму инстинктивно не верит низшим расам." }, { 3.44, "Хоть ты и смогла доказать мне, что у тебя задатки настоящего героя, пришло время доказать это моему повелителю." }, { 11.48, "Улей Аши, улей Зора и улей Регал кишат силитидами, которые грозят нашему существованию." }, { 17.97, "Убей как можно больше проклятых тварей и принеси мне фрагменты их панцирей." }, { 23.42, "Когда у тебя закончится место в заплечных мешках, возвращайся и я укреплю твою решимость." } } }, t = { d = 10.7, g = 1, v = "nightelf-male#59", n = { m = 125, f = 125 }, c = { m = { { 0.00, "Не думай, что ты один." }, { 1.61, "Я дарую тебе способность привлекать других к себе на помощь." }, { 5.98, "Подлинному защитнику своего народа не обойтись без помощи собратьев." } }, f = { { 0.00, "Не думай, что ты одна." }, { 1.61, "Я дарую тебе способность привлекать других к себе на помощь." }, { 5.98, "Подлинному защитнику своего народа не обойтись без помощи собратьев." } } } } },
    [8302] = { d = 16.2, g = 1, v = "nightelf-male#59", n = { m = 190, f = 190 }, c = { m = { { 0.00, "Старательно выбирай своих представителей, смертный." }, { 3.65, "Всякий раз, выполнив задание, ты сможешь выбрать себе нового представителя." }, { 9.02, "А теперь, не теряя времени, скажу: мне по-прежнему нужны обломки силитидских панцирей." }, { 15.17, "Что стоишь?" }, { 16.00, "Иди!" } }, f = { { 0.00, "Старательно выбирай своих представителей, смертная." }, { 3.61, "Всякий раз, выполнив задание, ты сможешь выбрать себе нового представителя." }, { 8.94, "А теперь, не теряя времени, скажу: мне по-прежнему нужны обломки силитидских панцирей." }, { 15.02, "Что стоишь?" }, { 15.84, "Иди!" } } }, t = { d = 6.6, v = "nightelf-male#59", n = { x = 72 }, c = { x = { { 0.00, "Молодец, герой." }, { 1.29, "Тебе будет дарована возможность назначить ещё одного агента Ноздорму." } } } } },
    [8303] = { d = 18.6, v = "nightelf-male#59", n = { x = 203 }, c = { x = { { 0.00, "Время пришло." }, { 1.04, "Я должен извиниться за то, что так долго держал всё в тайне." }, { 5.33, "Но кругом враги, они могут оказаться у нас прямо под носом." }, { 9.68, "Прошу тебя, прими этот фолиант, читай его и учись." }, { 13.52, "Я с радостью делюсь с тобой знаниями." }, { 16.25, "Теперь же отыщи нашего повелителя." } } }, t = { d = 2.7, v = "creature/anachronos", n = { x = 26 }, c = { x = { { 0.00, "Весь Калимдор надеется на тебя." } } } } },
    [8304] = { d = 30.2, v = "nightelf-male#54", n = { x = 330 }, c = { x = { { 0.00, "Моя милая Наталиа пропала." }, { 2.08, "Честно говоря, в последние недели перед исчезновением она довольно странно вела себя." }, { 8.60, "Я несколько раз видел, как она говорила сама с собой." }, { 12.63, "При этом Наталиа уверяла, что всё в порядке и ей необходимо продолжать исследования." }, { 18.82, "В последний раз я видел её, когда она направилась в лагерь Бронзоборода, на юг." }, { 24.66, "У меня слишком мало солдат." }, { 26.81, "Сходи в лагерь Бронзоборода и допроси дворфов." } } }, t = { d = 15.2, v = "nightelf-male#54", n = { x = 139 }, c = { x = { { 0.00, "*Командир Мар'алит опускает голову в раздумье.*" }, { 3.60, "Жива она или мертва, я должен выполнить свой долг." }, { 8.19, "И найти её." }, { 9.24, "Увы, я не имею права покинуть этот форт." }, { 12.94, "Придёшь ли ты мне на помощь?" } } } } },
    [8305] = { d = 19.4, v = "creature/anachronos", n = { x = 179 }, c = { x = { { 0.00, "В южной пустыне Силитуса, рядом со священной стеной, есть хрустальная слеза." }, { 6.74, "Эта слеза – символ великих потерь, понесённых во время войны Зыбучих песков." }, { 13.57, "Отыщи эту слезу и загляни в её глубины, дабы достичь просветления." } } }, t = { d = 11.4, v = "narrator", n = { x = 112 }, c = { x = { { 0.00, "Вы чувствуете, что кристалл исполнен великой скорби." }, { 4.42, "Сила её столь велика, что вам кажется, будто вы немедленно рухнете и умрёте от тоски." } } } } },
    [8306] = { d = 30.1, v = "nightelf-male#54", n = { x = 316 }, c = { x = { { 0.00, "Прошу тебя, отправляйся в Улей Регал и узнай, что сталось с моей возлюбленной Наталией." }, { 6.76, "Это будет очень непросто, так что собери друзей." }, { 10.55, "Прежде чем нырять в бездну безумия, вернись и поговори с дворфами." }, { 15.65, "Быть может, они подскажут тебе, как разобраться с силитидами из улья." }, { 20.96, "И последнее." }, { 21.93, "Если она в самом деле безумна, как говорят... сделай, что должно." }, { 26.96, "*Командир Мар'алит отворачивается в сторону.*" } } }, t = { d = 12.6, v = "nightelf-male#54", n = { x = 126 }, c = { x = { { 0.00, "*Командир Мар'алит хватается за сердце.*" }, { 2.80, "К'Тун?" }, { 3.39, "ЧТО всё это значит?" }, { 5.02, "Что ещё за К'Тун?" }, { 6.43, "Как мог этот демон превратить мою милую Наталию в описанного тобой монстра?" } } } } },
    [8307] = { d = 33.1, v = "nightelf-female#53", n = { x = 365 }, c = { x = { { 0.00, "Приспособиться к жизни в пустыне, мягко говоря, нелегко." }, { 4.09, "Мне не хватает не только птиц и деревьев Аубердина, но и нормальной еды!" }, { 9.23, "Я делаю всё, что в моих силах, но выбор продуктов у нас невелик." }, { 13.84, "Я изучаю местные травы, но их так мало…" }, { 16.70, "Зато я видела, как в лагерях Сумеречного Молота охотятся на песчаных червей." }, { 22.22, "Но их мясо очень горькое, и я не представляю, как сделать его съедобным." }, { 27.42, "Если ты окажешься в их лагере, смотри в оба." }, { 30.67, "Как узнаешь что-нибудь – сообщи мне." } } }, t = { d = 11.5, v = "narrator", n = { x = 125 }, c = { x = { { 0.00, "В книге содержится несколько обычных рецептов и пара очень оригинальных." }, { 5.69, "Полистав её, вы находите рецепт, в котором упоминается мясо песчаных червей." } } } } },
    [8308] = { d = 42.6, v = "narrator", n = { x = 411 }, c = { x = { { 0.00, "Всем заинтересованным лицам:" }, { 2.40, "Если вы читаете это письмо, значит я мёртв или скоро умру." }, { 7.58, "Трудно сказать." }, { 8.98, "Большая часть команды уже мертва." }, { 11.92, "Нашёл сведения про титана." }, { 14.16, "Страшная битва между ним и Древним богом." }, { 17.80, "Самый настоящий Древний Бог." }, { 20.28, "Нашёл древний туннель в Ан'Кираж." }, { 23.14, "Иду по нему." }, { 24.30, "Отнесите это письмо в мой старый лагерь." }, { 27.86, "Покормите, напоите и приласкайте мою обезьянку." }, { 31.96, "- Бранн Бронзобород, оперативный исследователь" }, { 35.83, "Постскриптум." }, { 36.99, "Остерегайся безумного ночного эльфа, поклоняющегося Древнему богу." } } }, t = { d = 11.0, v = "dwarf-male", n = { x = 111 }, c = { x = { { 0.00, "Что ж, многое прояснилось." }, { 2.15, "Если ты доберёшься до Ан'Киража, посматривай, нет ли там старины Бранна." }, { 7.93, "Боюсь, без своей обезьянки он бессилен." } } } } },
    [8309] = { d = 30.6, v = "dwarf-male", n = { x = 363 }, c = { x = { { 0.00, "После нашего первого рейда в ульи и последовавшего безумия госпожи Мар'алит, из этих трёх ульев так и хлынули проклятые жуки!" }, { 8.90, "Мне кажется, их повышенная активность связана с письменами, покрывающими эти странные кристаллы." }, { 15.65, "Нам нужны оттиски с кристаллов из всех трёх ульев." }, { 19.14, "Заполучив их, мы можем попытаться понять причины этого безумия." }, { 23.66, "Возьми копирующее устройство геолога и ступай в ульи." }, { 27.48, "Без оттисков из всех ульев даже не возвращайся." } } }, t = { d = 8.7, v = "dwarf-male", n = { x = 98 }, c = { x = { { 0.00, "Ничего я не понимаю в этих письменах." }, { 2.80, "Первый раз такие вижу!" }, { 4.53, "Надеюсь, исследования Франкала помогут пролить на них свет." } } } } },
    [8310] = { d = 21.0, g = 1, v = "dwarf-male", n = { m = 219, f = 220 }, c = { m = { { 0.00, "Мне кажется, я изобрёл эликсир, который поможет нам расшифровать письмена и язык силитидов и киражей!" }, { 7.75, "Что мне нужно?" }, { 8.87, "Хорошо, что ты спросил!" }, { 10.68, "Мне нужны мозги!" }, { 12.01, "Точнее говоря, мозги всех видов силитидов, живущих в ульях." }, { 16.69, "Принеси мне мозги, и работа Рутгара не пойдёт насмарку." } }, f = { { 0.00, "Мне кажется, я изобрёл эликсир, который поможет нам расшифровать письмена и язык силитидов и киражей!" }, { 7.78, "Что мне нужно?" }, { 8.91, "Хорошо, что ты спросила!" }, { 10.80, "Мне нужны мозги!" }, { 12.13, "Точнее говоря, мозги всех видов силитидов, живущих в ульях." }, { 16.83, "Принеси мне мозги, и работа Рутгара не пойдёт насмарку." } } }, t = { d = 7.0, v = "dwarf-male", n = { x = 67 }, c = { x = { { 0.00, "Поразительно!" }, { 1.14, "Не уходи далеко, дитя." }, { 3.10, "Может быть, мы поручим тебе ещё задание-другое." } } } } },
    [8311] = { d = 33.6, v = "child-male", n = { x = 383 }, c = { x = { { 0.00, "Хотел бы я пойти потыквовинничать, но не могу – приболел." }, { 3.98, "Если ты вместо меня сходишь, я обменяю тебе сладости, что ты наберёшь, на те, что у меня уже есть." }, { 10.81, "Думаю, тебе они понравятся – они превратят тебя в разные смешные и страшные штуки!" }, { 16.75, "У каждого из хозяев таверн в больших городах есть сладости, которые они раздают на Тыквовин." }, { 23.25, "Поговори с ними и выполни их задания." }, { 25.91, "А ещё в Стальгорне живёт гном по имени Талваш, и он тоже раздаёт сладости." }, { 30.96, "Когда соберёшь их все, принеси мне сюда!" } } }, t = { d = 14.8, g = 1, v = "child-male", n = { m = 156, f = 157 }, c = { m = { { 0.00, "Ух ты, тебе удалось собрать их все!" }, { 2.70, "Просто супер!" }, { 3.81, "Спасибо за то, что тыквовинничал вместо меня." }, { 7.27, "Вот, возьми эти тыквовинские конфетки – я уверен, ты будешь от них в восторге!" }, { 13.22, "Счастливого Тыквовина!" } }, f = { { 0.00, "Ух ты, тебе удалось собрать их все!" }, { 2.66, "Просто супер!" }, { 3.75, "Спасибо за то, что тыквовинничала вместо меня." }, { 7.22, "Вот, возьми эти тыквовинские конфетки – я уверен, ты будешь от них в восторге!" }, { 13.08, "Счастливого Тыквовина!" } } } } },
    [8312] = { d = 44.2, v = "child-female", n = { x = 463 }, c = { x = { { 0.00, "Я так хотела бы пойти просить сладости!" }, { 3.02, "Но не могу, потому что болею..." }, { 5.42, "Сходи вместо меня, а?" }, { 7.13, "А я с тобой потом поменяюсь: отдам те конфеты, что у меня уже есть, взамен тех, которые дадут тебе!" }, { 14.75, "Вот эта конфетка тебе наверняка понравится: она позволяет превращаться в разных существ, забавных и страшных!" }, { 23.11, "У всех хозяев таверн в больших городах непременно есть конфеты, которые они дарят на Тыквовин – надо только поговорить с ними и сделать то, что они попросят." }, { 35.12, "И троллиха по имени Кали Ремик в деревне Сен'джин тоже раздаёт конфеты." }, { 40.54, "Когда соберёшь все конфеты, принеси их мне, ладно?" } } }, t = { d = 14.1, v = "child-female", n = { x = 124 }, c = { x = { { 0.00, "Ух ты!" }, { 0.58, "Тебе удалось собрать их все!" }, { 3.25, "Ты настоящий герой!" }, { 5.08, "Спасибо большое." }, { 6.66, "Вот, возьми эти тыквовинские конфеты – они ужасно вкусные!" }, { 12.16, "Счастливого Тыквовина!" } } } } },
    [8313] = { d = 14.5, v = "narrator", n = { x = 165 }, c = { x = { { 0.00, "Хотя вам вполне понятен рецепт по приготовлению мяса песчаного червя, в нём упоминаются незнакомые травы и специи." }, { 8.52, "Быть может, Каландрата хорошо разбирается в растениях пустыни и сможет помочь вам." } } }, t = { d = 10.5, v = "nightelf-female#53", n = { x = 109 }, c = { x = { { 0.00, "Дай-ка взглянуть…" }, { 1.41, "Кажется, всё просто." }, { 3.03, "У них есть свои названия для некоторых видов растений, но догадаться совсем просто." }, { 9.50, "Дай, я покажу!" } } } } },
    [8314] = { d = 31.3, v = "dwarf-male", n = { x = 380 }, c = { x = { { 0.00, "Мы на грани крупного прорыва!" }, { 2.08, "Принесённые тобой оттиски позволили нам воссоздать письмена на хрустальной призме." }, { 7.75, "Очевидно, что для киражей и прочих непонятных сущностей они имеют большое значение и позволяют передавать силитидам сообщения." }, { 16.56, "К несчастью, это всё, что нам удалось понять." }, { 19.71, "Необходимо прочитать послания, сокрытые в кристаллах." }, { 23.43, "Отнеси покрытую письменами хрустальную призму геологу Ехидной в крепость Кенария." }, { 29.16, "Может, она сумеет тебе помочь." } } }, t = { d = 32.4, v = "dwarf-female#34", n = { x = 366 }, c = { x = { { 0.00, "Дворфы не смогли расшифровать письмена, потому что тут и расшифровывать нечего." }, { 5.76, "Следовало просто правильно повернуть верхний слой призмы, так, чтобы он выровнялся с изображениями внутри кристалла." }, { 14.22, "Тогда сообщение можно прочитать." }, { 16.67, "Умно…" }, { 17.13, "Впрочем, хотя теперь мы можем перевести полученные данные, главное – понять их правильно." }, { 23.75, "На поверхности призмы есть только одна подсказка – если я правильно перевела оттиски – и если ей верить, то дело плохо." } } } } },
    [8315] = { d = 31.0, v = "dwarf-female#34", n = { x = 337 }, c = { x = { { 0.00, "Здесь изображена встреча посланника киражей с тремя силитидами у костей большого дракона." }, { 6.70, "Над рисунком я вижу надпись, судя по всему, какой-то шифр." }, { 11.09, "Не исключено, что это ключевой момент призыва посланника." }, { 15.42, "Я создам копию, попробуй воспользоваться ей в пустыне у Костей Граккаронда." }, { 21.04, "Если я права, вожди решат, что им посылают какие-то данные и явятся на зов." }, { 26.72, "Убей их и сразись с посланником." }, { 29.16, "Ключ к кристаллам у него..." } } }, t = { d = 3.7, v = "dwarf-female#34", n = { x = 34 }, c = { x = { { 0.00, "Двадцать тысяч лет истории у меня в руках!" } } } } },
    [8317] = { d = 13.0, v = "nightelf-female#53", n = { x = 149 }, c = { x = { { 0.00, "Рецепт мне несомненно пригодится." }, { 2.45, "Пора приниматься за работу, чтобы приготовить копчёные пустынные клёцки уже сегодня." }, { 8.60, "Мне не помешала бы помощь, а уж я бы тебе отплатила сторицей." } } }, t = { d = 8.4, v = "nightelf-female#53", n = { x = 91 }, c = { x = { { 0.00, "Отлично!" }, { 0.71, "Ты мой спаситель." }, { 2.05, "Не думала, что сторонники Сумеречного Молота могут придумать такой хороший рецепт." } } } } },
    [8318] = { d = 30.5, v = "tauren-male", n = { x = 312 }, c = { x = { { 0.00, "Некоторые из культистов Сумеречного Молота носят с собой листы бумаги, на которых нацарапана какая-то неразборчивая писанина." }, { 10.32, "Принеси мне целую пачку таких писулек." }, { 13.55, "Я не могу понять, что означает эта ерунда, но дело не в том!" }, { 18.46, "При помощи этих бумажек происходят тайные переговоры их группировок." }, { 24.03, "Чем больше текстов мы у них отнимем, тем сложнее им будет обмениваться сообщениями!" } } }, t = { d = 6.4, v = "tauren-male", n = { x = 50 }, c = { x = { { 0.00, "Великолепно!" }, { 1.33, "Уберу-ка я их подальше, они мне потом пригодятся." } } } } },
    [8319] = { t = { d = 5.4, v = "tauren-male", n = { x = 40 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.88, "Я замолвлю за тебя доброе слово." } } } } },
    [8320] = { d = 39.6, v = "tauren-male#68", n = { x = 429 }, c = { x = { { 0.00, "Сумеречный Молот, безумная секта, поклоняющаяся богам смерти и разрушения, разбила лагеря по всему Силитусу и день и ночь проводит свои ритуалы." }, { 11.06, "Планы её сторонников нам неизвестны, но они как-то связаны с пульсирующими красными кристаллами, разбросанными по всей пустыне." }, { 20.67, "Хотя, быть может, однажды нам удастся разгадать эту тайну, но сейчас главное – избавиться от угрозы." }, { 28.41, "Ступай в их лагеря и найди там геолордов из культа Сумеречного Молота." }, { 33.80, "Они командуют этими змеюками, поэтому нанести удар необходимо именно по ним!" } } }, t = { d = 13.5, g = 1, v = "tauren-male#68", n = { m = 149, f = 150 }, c = { m = { { 0.00, "Ты отлично справился с этим заданием." }, { 2.80, "Смерть геолордов из культа Сумеречного Молота – серьёзный удар по силам культа." }, { 8.61, "Будем надеяться, что мы сумели отсрочить выполнение их планов..." } }, f = { { 0.00, "Ты отлично справилась с этим заданием." }, { 2.92, "Смерть геолордов из культа Сумеречного Молота – серьёзный удар по силам культа." }, { 8.84, "Будем надеяться, что мы сумели отсрочить выполнение их планов..." } } } } },
    [8321] = { d = 29.0, v = "tauren-male#68", n = { x = 287 }, c = { x = { { 0.00, "Мы обнаружили ещё одну базу Сумеречного Молота." }, { 3.98, "Она зовётся Сумеречная пещера и находится в северо-восточной части Силитуса." }, { 10.36, "Их главарь, Вайрал Подлый, живёт именно в этой пещере, и его-то тебе и предстоит победить." }, { 17.94, "Одолев злодея, принеси мне его перстень-печатку." }, { 22.07, "Говорят, что в Сумеречной пещере можно насмотреться таких ужасов, что век не забудешь." } } }, t = { d = 15.0, v = "tauren-male#68", n = { x = 140 }, c = { x = { { 0.00, "Получилось!" }, { 1.06, "Вайрал мёртв!" }, { 2.29, "Что ж, нападение Сумеречного Молота на Силитус обречено на провал." }, { 8.25, "Их здесь ещё немало осталось, но они нескоро оправятся от сегодняшнего удара." } } } } },
    [8322] = { d = 33.0, v = "scourge-female#79", n = { x = 359 }, c = { x = { { 0.00, "Люди Южнобережья любят эль, особенно тот, что подают в местной таверне." }, { 5.48, "Думаю, тыквовинского хаоса им маловато – надо бы подпортить им недельный, а то и месячный запас выпивки!" }, { 13.47, "Возьмите вот эти тухлые яйца и подбросьте в главную бочку с пивом в таверне Южнобережья." }, { 20.34, "Однако вашего присутствия там не потерпят, поэтому приготовьтесь защищаться!" }, { 26.17, "Как только угостите всё Южнобережье этим незабываемым элем, возвращайтесь на наш фестиваль!" } } }, t = { d = 8.5, v = "narrator", n = { x = 82 }, c = { x = { { 0.00, "Пробившись в таверну, вы опускаете тухлые яйца в бочку." }, { 4.87, "В воздухе разливается отвратительная вонь..." } } } } },
    [8323] = { d = 32.5, v = "human-male", n = { x = 413 }, c = { x = { { 0.00, "Теперь, когда у меня есть Сумеречный словарь, мне остаётся попросить тебя о небольшой услуге." }, { 6.11, "В моей бывшей организации ежемесячно издаются тщательно закодированные сводки новостей." }, { 11.86, "Если они получат новые сведения обо мне или решат перестать меня искать, об этом сообщат в \"Истинно верующем\"." }, { 19.33, "Хотя меня, безусловно, интересует подобная информация, в этих сводках могут быть и другие полезные сведения." }, { 26.51, "Принеси мне как можно больше зашифрованных текстов, добытых у сторонников Сумеречного Молота." } } }, t = { d = 9.0, v = "human-male", n = { x = 108 }, c = { x = { { 0.00, "Великолепно!" }, { 0.91, "Я как можно скорее займусь расшифровкой." }, { 3.82, "Если мне попадётся интересная информация, я найду способ связаться с тобой." } } } } },
    [8324] = { t = { d = 5.8, v = "human-male", n = { x = 64 }, c = { x = { { 0.00, "Великолепно!" }, { 0.98, "Если тебе снова попадутся зашифрованные тексты, сразу неси мне." } } } } },
    [8331] = { d = 41.8, v = "tauren-male#68", n = { x = 426 }, c = { x = { { 0.00, "Мы надеялись, что Сумеречный Молот свернёт свои операции в Силитусе..." }, { 5.71, "Увы, мы ошиблись." }, { 7.20, "Благодаря постоянным нападениям на лагеря сектантов нам удалось выяснить, что Молот контролирует ещё более страшная сила, Совет Бездны." }, { 18.32, "Для связи с культистами, этот совет пользуется ветровыми камнями, рассеянными по лагерям Молота." }, { 26.26, "Пришло время выступить против Совета Бездны." }, { 30.04, "Поговори с ремесленницей Аурель Золотой Лист, в восточной части крепости Кенария." }, { 36.72, "Мы задумали одну хитрость, для которой необходимо её искусство." } } }, t = { d = 7.5, v = "nightelf-female#53", n = { x = 81 }, c = { x = { { 0.00, "Добрый день." }, { 0.97, "Говорят, ты собираешься выступить против Совета Бездны?" }, { 5.25, "Коли так, слушай внимательно..." } } } } },
    [8332] = { d = 32.5, g = 1, v = "nightelf-female#53", n = { m = 366, f = 366 }, c = { m = { { 0.00, "Мы думаем, что при помощи ветрового камня можно устроить засаду на герцога Совета Бездны." }, { 6.51, "Для этого придётся связаться с Советом через этот камень и убедить всех, что ты – один из командующих среднего ранга Сумеречного Молота." }, { 16.28, "Чтобы эта хитрость удалась, нужна копия медальона, по которому в культе узнают чин." }, { 22.41, "Я могу создать его, но мне понадобится большой сияющий осколок и талисманы храмовников Бездны." }, { 29.24, "Принеси их мне, а остальное я сделаю сама." } }, f = { { 0.00, "Мы думаем, что при помощи ветрового камня можно устроить засаду на герцога Совета Бездны." }, { 6.58, "Для этого придётся связаться с Советом через этот камень и убедить всех, что ты – одна из командующих среднего ранга Сумеречного Молота." }, { 16.44, "Чтобы эта хитрость удалась, нужна копия медальона, по которому в культе узнают чин." }, { 22.63, "Я могу создать его, но мне понадобится большой сияющий осколок и талисманы храмовников Бездны." }, { 29.53, "Принеси их мне, а остальное я сделаю сама." } } }, t = { d = 24.6, v = "nightelf-female#53", n = { x = 296 }, c = { x = { { 0.00, "А, очень хорошо." }, { 1.18, "Я как раз работала над медальоном – с этими последними компонентами я закончу буквально через пару мгновений..." }, { 8.73, "Вот и всё." }, { 9.41, "Держи медальон." }, { 10.52, "Надень его, когда будешь активировать один из ветровых камней Сумеречного Молота." }, { 16.22, "Надень его вместе с остальным сумеречным облачением, и Совет Бездны примет тебя за одного из своих культистов-прислужников." } } } } },
    [8333] = { t = { d = 9.0, v = "nightelf-female#53", n = { x = 99 }, c = { x = { { 0.00, "Вот." }, { 0.34, "Ещё один станционный медальон служителя Сумеречного Молота." }, { 4.83, "Бери на здоровье." }, { 6.19, "Удачи тебе в борьбе с Советом Бездны!" } } } } },
    [8341] = { d = 31.0, v = "nightelf-female#53", n = { x = 355 }, c = { x = { { 0.00, "Чтобы вызвать лордов Совета Бездны, необходим больший ветровой камень." }, { 5.28, "К тому же они согласны беседовать лишь с самыми высокопоставленными представителями Сумеречного Молота." }, { 12.96, "Но..." }, { 13.36, "Я придумала, как поработать над твоей маскировкой и обмануть лордов Бездны!" }, { 18.84, "Для этого понадобится кольцо Власти, которое носят лишь вожди культистов." }, { 24.25, "Я готова создать такое кольцо, если ты принесёшь мне большие сияющие осколки и перстни Бездны." } } }, t = { d = 24.0, g = 1, v = "nightelf-female#53", n = { m = 277, f = 278 }, c = { m = { { 0.00, "Спасибо." }, { 0.63, "Одну минутку, и кольцо будет готово..." }, { 3.40, "Вот оно." }, { 4.03, "Теперь ты готов." }, { 5.23, "Обязательно надень это кольцо вместе с медальоном ранга и остальным сумеречным облачением, когда будешь активировать большой ветровой камень." }, { 15.19, "Сделай так, и Совет Бездны примет тебя за одного из своих слуг." }, { 19.67, "А там, может, тебе удастся заманить кого-нибудь из них в засаду!" } }, f = { { 0.00, "Спасибо." }, { 0.63, "Одну минутку, и кольцо будет готово..." }, { 3.40, "Вот оно." }, { 4.02, "Теперь ты готова." }, { 5.28, "Обязательно надень это кольцо вместе с медальоном ранга и остальным сумеречным облачением, когда будешь активировать большой ветровой камень." }, { 15.22, "Сделай так, и Совет Бездны примет тебя за одного из своих слуг." }, { 19.68, "А там, может, тебе удастся заманить кого-нибудь из них в засаду!" } } } } },
    [8342] = { t = { d = 12.9, v = "nightelf-female#53", n = { x = 132 }, c = { x = { { 0.00, "А, вижу, твоя решимость не ослабела." }, { 2.95, "Немногие решились бы схватиться с демоническим советом!" }, { 7.34, "Вот кольцо." }, { 8.28, "Да пребудет воля твоя тверда, и да сопутствует тебе удача." } } } } },
