    [8348] = { d = 25.5, g = 1, v = "tauren-male", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Хуум говорит, что ты придумал, как вызвать герцогов Бездны!" }, { 5.36, "Это большое достижение." }, { 7.52, "Знаешь, что бы ещё хорошо сделать?" }, { 10.56, "Убить одного из них." }, { 12.40, "Это произвело бы неизгладимое впечатление на их прихвостней, если ты понимаешь, о чём я." }, { 20.08, "В доказательство собственного подвига принеси перстень герцога." } }, f = { { 0.00, "Хуум говорит, что ты придумала, как вызвать герцогов Бездны!" }, { 5.38, "Это большое достижение." }, { 7.54, "Знаешь, что бы ещё хорошо сделать?" }, { 10.58, "Убить одного из них." }, { 12.42, "Это произвело бы неизгладимое впечатление на их прихвостней, если ты понимаешь, о чём я." }, { 20.10, "В доказательство собственного подвига принеси перстень герцога." } } }, t = { d = 9.8, g = 1, v = "tauren-male", n = { m = 73, f = 73 }, c = { m = { { 0.00, "Стоило тебе войти в крепость Кенария, и я сразу понял, что передо мной могучий герой." }, { 8.46, "Так держать!" } }, f = { { 0.00, "Стоило тебе войти в крепость Кенария, и я сразу понял, что передо мной могучая героиня." }, { 8.69, "Так держать!" } } } } },
    [8349] = { d = 13.4, v = "nightelf-female#53", n = { x = 148 }, c = { x = { { 0.00, "Теперь у тебя есть медальон, и ты можешь вызвать герцога Бездны." }, { 4.84, "Поговори с Бором Буйногривым." }, { 7.06, "Он даст тебе задание." }, { 8.68, "Удачи." }, { 9.22, "Если тебе снова понадобятся медальоны, возвращайся ко мне." } } }, t = { d = 10.0, g = 1, v = "tauren-male", n = { x = 85 }, c = { m = { { 0.00, "Рад видеть тебя, герой!" }, { 2.04, "Значит, теперь у тебя есть медальон?" }, { 5.14, "Хорошо – он понадобится тебе для следующего задания..." } }, f = { { 0.00, "Рад видеть тебя, героиня!" }, { 2.27, "Значит, теперь у тебя есть медальон?" }, { 5.47, "Хорошо – он понадобится тебе для следующего задания..." } } } } },
