    [8352] = { d = 35.2, g = 1, v = "tauren-male", n = { m = 322, f = 323 }, c = { m = { { 0.00, "Мы с Хуумом только что обсуждали тебя." }, { 3.41, "Он говорит, что ты готов испытать себя и сразиться с лордом Бездны!" }, { 9.36, "Должен предупредить, что это очень опасно." }, { 13.16, "Возьми с собой подкрепление." }, { 15.70, "И не пару друзей, а хороший боевой отряд." }, { 19.42, "Если твои друзья стоят тебя, кто знает, может быть, удастся одолеть этого лорда!" }, { 26.72, "Если ты вдруг справишься – мне как всегда потребуются доказательства – то тебя ждёт великая награда." } }, f = { { 0.00, "Мы с Хуумом только что обсуждали тебя." }, { 3.39, "Он говорит, что ты готова испытать себя и сразиться с лордом Бездны!" }, { 9.21, "Должен предупредить, что это очень опасно." }, { 12.89, "Возьми с собой подкрепление." }, { 15.34, "И не пару друзей, а хороший боевой отряд." }, { 18.94, "Если твои друзья стоят тебя, кто знает, может быть, удастся одолеть этого лорда!" }, { 25.99, "Если ты вдруг справишься – мне как всегда потребуются доказательства – то тебя ждёт великая награда." } } } },
    [8353] = { d = 28.8, g = 1, v = "dwarf-male#100", n = { m = 289, f = 290 }, c = { m = { { 0.00, "А, тыквовинничаем для больных деток?" }, { 2.71, "Я сказал бы, ты малость староват конфетки выпрашивать..." }, { 6.90, "Что же, за моё лакомство – стальгорнскую мятную конфетку – ты мне... поквохтаешь как курица!" }, { 13.59, "Да, курочка с мятой хорошо идёт... ладно, может, курочке от этого и не так ХОРОШО... но конфетку не дам, пока не поквохтаешь!" }, { 22.86, "Ладно, герой, будешь квохтать или нет?!" }, { 25.90, "Пора отрабатывать лакомство!" } }, f = { { 0.00, "А, тыквовинничаем для больных деток?" }, { 2.77, "Я сказал бы, ты малость старовата конфетки выпрашивать..." }, { 7.13, "Что же, за моё лакомство – стальгорнскую мятную конфетку – ты мне... поквохтаешь как курица!" }, { 13.99, "Да, курочка с мятой хорошо идёт... ладно, может, курочке от этого и не так ХОРОШО... но конфетку не дам, пока не поквохтаешь!" }, { 23.48, "Ладно, героиня, будешь квохтать или нет?!" }, { 26.73, "Пора отрабатывать лакомство!" } } }, t = { d = 7.5, v = "dwarf-male#100", n = { x = 54 }, c = { x = { { 0.00, "Ой, забавно!" }, { 1.48, "Просто здорово!" }, { 3.38, "Вот твоё угощение." }, { 5.49, "Весёлого Тыквовина!" } } } } },
    [8354] = { d = 34.4, g = 1, v = "scourge-male#82", n = { m = 291, f = 292 }, c = { m = { { 0.00, "А, ты у нас сегодня заместо детишек, да?" }, { 3.62, "Я сказал бы, ты малость староват конфетки выпрашивать..." }, { 8.72, "Что же, за моё лакомство – мятную конфету Подгорода – ты... поквохчешь как курица!" }, { 16.05, "Да, курочки любят мятные конфетки... впрочем, им не обязательно их ЛЮБИТЬ... главное, что конфетку ты не получишь, пока не поквохчешь!" }, { 28.15, "Ну что, герой, будешь квохтать или нет?!" }, { 31.85, "Пора отрабатывать лакомство!" } }, f = { { 0.00, "А, ты у нас сегодня заместо детишек, да?" }, { 3.60, "Я сказал бы, ты малость старовата конфетки выпрашивать..." }, { 8.76, "Что же, за моё лакомство – мятную конфету Подгорода – ты... поквохчешь как курица!" }, { 16.05, "Да, курочки любят мятные конфетки... впрочем, им не обязательно их ЛЮБИТЬ... главное, что конфетку ты не получишь, пока не поквохчешь!" }, { 28.09, "Ну что, героиня, будешь квохтать или нет?!" }, { 31.94, "Пора отрабатывать лакомство!" } } }, t = { d = 8.2, v = "scourge-male#82", n = { x = 51 }, c = { x = { { 0.00, "Ха-ха-ха!" }, { 1.31, "Просто здорово!" }, { 3.46, "Вот твоё угощение." }, { 5.85, "Весёлого Тыквовина!" } } } } },
