    [8356] = { d = 28.9, g = 1, v = "human-female#111", n = { m = 310, f = 312 }, c = { m = { { 0.00, "Какой у тебя... интересный костюмчик." }, { 2.82, "Несмотря на то, что ты по доброте своей помогаешь заболевшему ребёнку, мне всё же придётся попросить тебя сделать что-нибудь!" }, { 11.89, "Ну-ка, ну-ка... ты выглядишь таким сильным и мускулистым в этом... наряде... посмотрим-ка на твои бицепсы!" }, { 19.82, "Да, давай, поиграй-ка мускулами, силач!" }, { 22.78, "Поиграешь мускулами – дам тебе вкуснейшей нуги." }, { 26.34, "Это отличное тыквовинское угощение!" } }, f = { { 0.00, "Какой у тебя... интересный костюмчик." }, { 2.81, "Несмотря на то, что ты по доброте своей помогаешь заболевшему ребёнку, мне всё же придётся попросить тебя сделать что-нибудь!" }, { 11.84, "Ну-ка, ну-ка... ты выглядишь такой сильной и мускулистой в этом... наряде... посмотрим-ка на твои бицепсы!" }, { 19.73, "Да, давай, поиграй-ка мускулами, силачка!" }, { 22.81, "Поиграешь мускулами – дам тебе вкуснейшей нуги." }, { 26.35, "Это отличное тыквовинское угощение!" } } }, t = { d = 9.7, v = "human-female#111", n = { x = 93 }, c = { x = { { 0.00, "Да ты и правда силач, ха-ха!" }, { 2.40, "Прекрасно, и спасибо за то, что так ценишь спорт." }, { 6.38, "Вот твои сладости." }, { 7.96, "Счастливого Тыквовина!" } } } } },
