    [8367] = { d = 31.8, v = "orc-male", n = { x = 293 }, c = { x = { { 0.00, "Нет выше чести, чем биться с Альянсом во имя Орды!" }, { 4.53, "Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы." }, { 11.91, "Отдельные стычки не помогут нам одолеть врага." }, { 16.04, "Лишь тщательно спланировав наступление, мы сломим проклятый Альянс." }, { 21.91, "Ступай в Низину Арати, Альтеракскую долину и Ущелье Песни Войны и вступи в схватку с Альянсом." }, { 30.33, "За честь!" }, { 31.13, "За Орду!" } } }, t = { d = 22.3, g = 1, v = "orc-male", n = { m = 189, f = 192 }, c = { m = { { 0.00, "На твою долю выпали непростые испытания, но ты не лишился мужества и сила тебя не покинула." }, { 8.72, "Знаки победы – пустое." }, { 10.94, "Не по ним судят о твоей доблести." }, { 14.11, "Выше голову." }, { 15.39, "Сегодня тебе подобает смотреть на других свысока, ведь ты настоящий герой!" } }, f = { { 0.00, "На твою долю выпали непростые испытания, но ты не лишилась мужества и сила тебя не покинула." }, { 8.68, "Знаки победы – пустое." }, { 10.87, "Не по ним судят о твоей доблести." }, { 13.98, "Выше голову." }, { 15.24, "Сегодня тебе подобает смотреть на других свысока, ведь ты настоящая героиня!" } } } } },
    [8368] = { d = 22.9, v = "orc-male", n = { x = 240 }, c = { x = { { 0.00, "Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение." }, { 6.39, "Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины." }, { 16.64, "Не бывать тому!" }, { 17.95, "Возвращайся ко мне и приноси доказательства верной службы Орде!" } } }, t = { d = 12.9, g = 1, v = "orc-male", n = { m = 114, f = 115 }, c = { m = { { 0.00, "Великолепно!" }, { 1.14, "Ты показал, чего стоишь, выступив против врага в Ущелье Песни Войны!" }, { 7.50, "Да разнесутся вести о твоих подвигах по всем нашим землям." } }, f = { { 0.00, "Великолепно!" }, { 1.16, "Ты показала, чего стоишь, выступив против врага в Ущелье Песни Войны!" }, { 7.68, "Да разнесутся вести о твоих подвигах по всем нашим землям." } } } } },
    [8369] = { d = 25.9, v = "orc-male", n = { x = 280 }, c = { x = { { 0.00, "Слушай." }, { 0.63, "Что бы ни болтали про битву в Альтеракской долине, правда состоит в следующем: экспедиция Грозовой Вершины вторглась в земли клана Северного Волка." }, { 11.99, "В тот день, когда мы позволим Альянсу безнаказанно нарушать наши границы, я повешу секиру на стену и примусь посыпать голову пеплом." }, { 22.24, "Отправляйся и сотри в порошок наглых захватчиков!" } } }, t = { d = 9.0, g = 1, v = "orc-male", n = { m = 91, f = 92 }, c = { m = { { 0.00, "Ты встал на защиту наших земель с невиданной храбростью!" }, { 4.71, "Я непременно расскажу командующим о твоих подвигах." } }, f = { { 0.00, "Ты встала на защиту наших земель с невиданной храбростью!" }, { 4.82, "Я непременно расскажу командующим о твоих подвигах." } } } } },
    [8370] = { d = 24.0, v = "orc-male", n = { x = 246 }, c = { x = { { 0.00, "Наш конфликт с Альянсом дошёл до открытой войны." }, { 3.79, "Никто уже не ищет предлогов, чтобы вступить в бой." }, { 7.86, "В Низине Арати идёт простая и открытая борьба за ресурсы." }, { 12.43, "Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска!" }, { 21.01, "Помоги нам захватить источник ресурсов!" } } }, t = { d = 6.2, g = 1, v = "orc-male", n = { m = 55, f = 56 }, c = { m = { { 0.00, "Удержать наши ресурсы в Арати – важная задача!" }, { 4.30, "Ты хорошо потрудился." } }, f = { { 0.00, "Удержать наши ресурсы в Арати – важная задача!" }, { 4.35, "Ты хорошо потрудилась." } } } } },
    [8371] = { d = 30.7, g = 1, v = "dwarf-male", n = { m = 354, f = 354 }, c = { m = { { 0.00, "В войне против Орды решающей может оказаться любая битва, сынок." }, { 4.72, "Победа на одном фронте позволит захватить ресурсы, которые помогут победить и на другом." }, { 11.04, "И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой." }, { 18.00, "Альянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закалённых в битвах!" }, { 24.45, "Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне." } }, f = { { 0.00, "В войне против Орды решающей может оказаться любая битва, дочка." }, { 4.75, "Победа на одном фронте позволит захватить ресурсы, которые помогут победить и на другом." }, { 11.10, "И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой." }, { 18.10, "Альянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закалённых в битвах!" }, { 24.58, "Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне." } } }, t = { d = 19.4, g = 1, v = "dwarf-male", n = { m = 191, f = 193 }, c = { m = { { 0.00, "Да, ты не из тех, кто даёт слабину!" }, { 2.59, "То, что тебе удалось постичь, не измерить никчёмными медалями и наградами." }, { 8.25, "Лишь те, кто тоже прошли сквозь огонь битвы, могут понять, что такое закалка истинного бойца." }, { 15.52, "Ты молодец, герой." }, { 16.99, "Настоящий герой Альянса!" } }, f = { { 0.00, "Да, ты не из тех, кто даёт слабину!" }, { 2.64, "То, что тебе удалось постичь, не измерить никчёмными медалями и наградами." }, { 8.41, "Лишь те, кто тоже прошли сквозь огонь битвы, могут понять, что такое закалка истинного бойца." }, { 15.82, "Ты молодец, героиня." }, { 17.45, "Настоящая героиня Альянса!" } } } } },
    [8372] = { d = 31.1, v = "dwarf-male", n = { x = 352 }, c = { x = { { 0.00, "Среброкрылые Часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес." }, { 7.37, "Впрочем, желание сохранить этот лес объясняется не только их любовью к природе." }, { 13.21, "Этот лес представляет собой естественную преграду для наступления сил Орды." }, { 18.72, "Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды." }, { 25.96, "Внеси свой вклад в борьбу со всадниками из клана Песни Войны!" }, { 30.47, "За Альянс!" } } }, t = { d = 4.2, g = 1, v = "dwarf-male", n = { m = 36, f = 37 }, c = { m = { { 0.00, "Молодец!" }, { 0.87, "Ты сослужил Альянсу добрую службу." } }, f = { { 0.00, "Молодец!" }, { 0.88, "Ты сослужила Альянсу добрую службу." } } } } },
    [8373] = { d = 31.8, v = "human-male#50", n = { x = 392 }, c = { x = { { 0.00, "Самое гнусное в Тыквовине – это бомбы-вонючки, которые Отрёкшиеся бросают на Южнобережье." }, { 6.07, "Кто бы мог подумать, что празднование свободы требует такой вони?" }, { 10.49, "Когда наступит Тыквовин, убери при помощи этого очистителя любую из мерзких бомб, которые Орда может подкинуть к нам в деревню." }, { 19.20, "Очиститель действует благодаря силе сосен." }, { 22.15, "Прими участие в поддержании чистоты Южнобережья, и я дам тебе кое-какие тыквовинские вкусности, которым ты несомненно порадуешься." }, { 30.98, "Договорились?" } } }, t = { d = 23.5, v = "human-male#50", n = { x = 258 }, c = { x = { { 0.00, "Ах, здесь уже почти приятнее пахнет." }, { 2.73, "Почти." }, { 3.27, "Благодаря тебе, Южнобережье, может, и переживёт ещё один Тыквовин." }, { 8.13, "Вот твои сладости, с моей благодарностью!" }, { 11.20, "Если конфеты закончатся, в Стальгорне, кажется, есть гномка по имени Катрина Мерцающая Звезда, она может продать тебе ещё; по-моему, она появляется только на Тыквовин." } } } } },
    [8374] = { d = 28.5, v = "dwarf-male", n = { x = 310 }, c = { x = { { 0.00, "Чтобы выиграть войну, мало быть умнее и хитрее противника." }, { 4.46, "Зачастую победа достаётся тем, в чьих руках сосредоточены все ресурсы." }, { 9.59, "Ресурсов в Низине Арати – хоть отбавляй." }, { 12.63, "Главное – захватить их первыми." }, { 14.99, "Если победа будет за Альянсом, нашим солдатам достанется больше мечей и копий." }, { 21.00, "Если Орде – те же мечи и копья обратятся против нас!" }, { 24.98, "Твой долг помочь Альянсу захватить Низину Арати!" } } }, t = { d = 6.4, v = "dwarf-male", n = { x = 65 }, c = { x = { { 0.00, "Отличная работа, солдат!" }, { 2.04, "Так держать, и Орда побежит от нас до самого Оргриммара." } } } } },
    [8375] = { d = 34.1, g = 1, v = "dwarf-male", n = { x = 387 }, c = { m = { { 0.00, "Не пойми меня превратно." }, { 1.83, "Орда совершенно справедливо считает долину Альтерака территорией клана Северного Волка." }, { 8.23, "Видишь ли, экспедиция Грозовой Вершины прибыла в эти края как мирные исследователи." }, { 14.30, "Они искали руду и древние реликвии, но нашли лишь смерть." }, { 18.48, "Альянс не ожидал такой бессмысленной жестокости даже от клана Северного Волка." }, { 24.23, "Вечная память отважным дворфам, павшим от рук вероломных орков." }, { 28.87, "Ступай, герой, внеси свой вклад в битву за Альтеракскую долину." }, { 33.44, "За Альянс!" } }, f = { { 0.00, "Не пойми меня превратно." }, { 1.80, "Орда совершенно справедливо считает долину Альтерака территорией клана Северного Волка." }, { 8.08, "Видишь ли, экспедиция Грозовой Вершины прибыла в эти края как мирные исследователи." }, { 14.05, "Они искали руду и древние реликвии, но нашли лишь смерть." }, { 18.16, "Альянс не ожидал такой бессмысленной жестокости даже от клана Северного Волка." }, { 23.80, "Вечная память отважным дворфам, павшим от рук вероломных орков." }, { 28.36, "Ступай, героиня, внеси свой вклад в битву за Альтеракскую долину." }, { 32.97, "За Альянс!" } } }, t = { d = 5.0, g = 1, v = "dwarf-male", n = { m = 47, f = 48 }, c = { m = { { 0.00, "Ты исполнил свой долг." }, { 1.98, "Орда заплатит за своё вероломство!" } }, f = { { 0.00, "Ты исполнила свой долг." }, { 2.03, "Орда заплатит за своё вероломство!" } } } } },
