    [8404] = { t = { d = 6.8, v = "dwarf-male", n = { x = 67 }, c = { x = { { 0.00, "Отличная работа." }, { 1.49, "Благодаря тебе, граничный лес Ясеневого леса простоял ещё день." } } } } },
    [8405] = { t = { d = 6.6, v = "dwarf-male", n = { x = 64 }, c = { x = { { 0.00, "Отличная работа." }, { 1.50, "Благодаря тебе рубежи Ясеневого леса устояли ещё один день." } } } } },
