    [8407] = { t = { d = 6.6, v = "dwarf-male", n = { x = 64 }, c = { x = { { 0.00, "Отличная работа." }, { 1.50, "Благодаря тебе рубежи Ясеневого леса устояли ещё один день." } } } } },
    [8408] = { t = { d = 6.8, v = "dwarf-male", n = { x = 64 }, c = { x = { { 0.00, "Отличная работа." }, { 1.54, "Благодаря тебе рубежи Ясеневого леса устояли ещё один день." } } } } },
    [8409] = { d = 16.2, v = "narrator", n = { x = 179 }, c = { x = { { 0.00, "Тухлые яйца успешно подброшены в бочку, и весь эль Южнобережья теперь безнадёжно испорчен." }, { 6.90, "Отправляйтесь назад, к Янке Зовущей Тьму, на фестиваль Плетёного человека на Тирисфальских лугах, и доложите о своём успехе." } } }, t = { d = 22.2, v = "scourge-female#79", n = { x = 222 }, c = { x = { { 0.00, "Ха-ха!" }, { 0.68, "Вот теперь-то вы продемонстрировали настоящий дух Тыквовина, вернее, дух ОТРЁКШИХСЯ!!!" }, { 8.52, "Замечательно, что в Южнобережье теперь будут пить испорченный эль, а то и вовсе никакого." }, { 17.55, "А вы – вот, угощайтесь." }, { 19.68, "Надеюсь, вам всё понравится!" } } } } },
    [8410] = { d = 20.0, v = "tauren-male#68", n = { x = 185 }, c = { x = { { 0.00, "Бат'ра Ветростраж ищет шамана вроде тебя." }, { 3.70, "Принеси ему по образцу каждой из стихий, чтобы доказать своё мастерство." }, { 9.73, "Бат'ру можно отыскать на востоке от мельницы Таррен." }, { 14.17, "Иди вдоль реки на север до руин." }, { 16.93, "Там-то Бат'ра и разбил лагерь." } } }, t = { d = 3.4, v = "troll-male#77", n = { x = 29 }, c = { x = { { 0.00, "Отлично, дружище." }, { 1.81, "Теперь поболтаем." } } } } },
    [8411] = { d = 7.1, v = "troll-male#77", n = { x = 64 }, c = { x = { { 0.00, "Здравствуй." }, { 1.05, "Расклад такой: ты несёшь мне стихии, и только потом я с тобой говорю." } } }, t = { d = 5.1, v = "troll-male#77", n = { x = 42 }, c = { x = { { 0.00, "Вот они, стихии, что мне нужны." }, { 3.03, "Теперь можем говорить." } } } } },
    [8412] = { d = 27.4, v = "troll-male#77", n = { x = 285 }, c = { x = { { 0.00, "Духи стихий здешних мест меня невзлюбили." }, { 3.27, "Ты знаешь о тотемах больше других, а мне без защитного тотема духов не обойтись." }, { 9.48, "Стихии у нас уже есть, теперь нужно что-то более близкое к природе, первобытное." }, { 15.75, "В Западных Чумных землях можно добыть когти медведей и глаза пауков." }, { 21.18, "Падальщики едят и тех, и других, поэтому у них в желудках может быть и то, и другое." } } }, t = { d = 3.0, v = "troll-male#77", n = { x = 23 }, c = { x = { { 0.00, "Отлично, дружище!" }, { 1.84, "Попробуем..." } } } } },
    [8413] = { d = 23.1, v = "troll-male#77", n = { x = 219 }, c = { x = { { 0.00, "Силы этого тотема духов недостаточно." }, { 3.26, "Нам нужна магия вуду, чтобы сделать верную защиту." }, { 7.66, "Тролли из затонувшего храма делают перья, насыщенные магией вуду." }, { 13.27, "Ступай туда и убей Ранокола, Миджана, Золо, Хукку, Зул'Лора и Лоро." }, { 19.11, "Тогда нам хватит магии на настоящий тотем духов." } } }, t = { d = 11.2, v = "troll-male#77", n = { x = 105 }, c = { x = { { 0.00, "Пора этому троллю хорошенько вздремнуть!" }, { 3.58, "За мной присмотрит тотем духов." }, { 6.30, "Я долго копил всякое добро." }, { 8.79, "Может, хочешь чего за труды?" } } } } },
    [8414] = { d = 27.7, g = 1, v = "human-male#50", n = { x = 320 }, c = { m = { { 0.00, "Привет тебе, герой." }, { 1.40, "Отрадно видеть рыцаря вроде тебя в сих безотрадных землях." }, { 5.40, "Мы рассчитываем на твою помощь в борьбе с бесконечными полчищами нежити." }, { 10.26, "Собери побольше камней Плети и отнеси их верховному жрецу Тель'данису." }, { 15.05, "Он охраняет гробницу Утера неподалёку отсюда." }, { 18.76, "Камни Плети находят лишь те, кто получил Жетон Серебряного Рассвета." }, { 23.37, "Если у тебя нет амулета, поговори с офицером Пьюхартом." } }, f = { { 0.00, "Привет тебе, героиня." }, { 1.56, "Отрадно видеть рыцаря вроде тебя в сих безотрадных землях." }, { 5.66, "Мы рассчитываем на твою помощь в борьбе с бесконечными полчищами нежити." }, { 10.64, "Собери побольше камней Плети и отнеси их верховному жрецу Тель'данису." }, { 15.56, "Он охраняет гробницу Утера неподалёку отсюда." }, { 19.22, "Камни Плети находят лишь те, кто получил Жетон Серебряного Рассвета." }, { 23.95, "Если у тебя нет амулета, поговори с офицером Пьюхартом." } } }, t = { d = 11.1, v = "nightelf-male#54", n = { x = 96 }, c = { x = { { 0.00, "Очищать камень Плети от зла опасно: это привлекает нежить за много миль вокруг." }, { 7.28, "Но Свет силён в тебе, и я за тебя не боюсь..." } } } } },
    [8415] = { d = 15.0, v = "human-male", n = { x = 165 }, c = { x = { { 0.00, "Командиру Ашламу Отважному Кулаку нужен паладин, не уступающий тебе честью и доблестью." }, { 6.64, "Командир живёт в лагере Промозглого Ветра в южной части Западных Чумных земель." }, { 12.67, "Найди его и помоги делу Света!" } } }, npc = { [5149] = { d = 16.0, v = "dwarf-male", n = { x = 165 }, c = { x = { { 0.00, "Командиру Ашламу Отважному Кулаку нужен паладин, не уступающий тебе честью и доблестью." }, { 7.10, "Командир живёт в лагере Промозглого Ветра в южной части Западных Чумных земель." }, { 13.54, "Найди его и помоги делу Света!" } } } } }, t = { d = 4.6, g = 1, v = "human-male#50", n = { m = 37, f = 38 }, c = { m = { { 0.00, "Отлично, герой!" }, { 1.39, "Посмотрим, из какого теста ты сделан." } }, f = { { 0.00, "Отлично, героиня!" }, { 1.50, "Посмотрим, из какого теста ты сделана." } } } } },
    [8416] = { d = 12.8, v = "nightelf-male#54", n = { x = 130 }, c = { x = { { 0.00, "Камни очищены от зла." }, { 1.74, "Я в курсе планов командира Ашлама, и ему понадобится всего лишь один бездействующий камень." }, { 9.12, "Отнеси его, и да сгорит Плеть в праведном огне." } } }, t = { d = 10.6, g = 1, v = "human-male#50", n = { m = 112, f = 113 }, c = { m = { { 0.00, "Ты сделал то, о чём я просил, не задавая вопросов." }, { 3.64, "Похоже, доверие заслужено." }, { 5.62, "Пожалуй, теперь я могу рассказать тебе о нашем плане подробнее." } }, f = { { 0.00, "Ты сделала то, о чём я просил, не задавая вопросов." }, { 3.82, "Похоже, доверие заслужено." }, { 5.87, "Пожалуй, теперь я могу рассказать тебе о нашем плане подробнее." } } } } },
    [8417] = { d = 12.3, v = "orc-male#60", n = { x = 130 }, c = { x = { { 0.00, "По Выжженным землям бродит неупокоенный дух одного из величайших героев Орды." }, { 6.24, "Честь воина прочнее смертного тела, так что тебе не помешает поговорить с ним." } } }, npc = { [5113] = { d = 12.9, v = "dwarf-male", n = { x = 130 }, c = { x = { { 0.00, "По Выжженным землям бродит неупокоенный дух одного из величайших героев Орды." }, { 6.52, "Честь воина прочнее смертного тела, так что тебе не помешает поговорить с ним." } } } }, [5479] = { d = 11.7, v = "human-male", n = { x = 130 }, c = { x = { { 0.00, "По Выжженным землям бродит неупокоенный дух одного из величайших героев Орды." }, { 5.91, "Честь воина прочнее смертного тела, так что тебе не помешает поговорить с ним." } } } } }, t = { d = 10.7, v = "orc-male", n = { x = 95 }, c = { x = { { 0.00, "Итак, ты хочешь избавить меня от боли." }, { 3.57, "Жаль, что меня нельзя просто-напросто зарубить, но к сожалению, не всё так просто…" } } } } },
    [8418] = { d = 26.6, v = "human-male#50", n = { x = 279 }, c = { x = { { 0.00, "Теперь мы сможем создать оружие против нежити из бездействующих камней Плети." }, { 6.10, "Задание непростое." }, { 7.57, "Магией, способной вынудить зло обратиться против самого себя, владеют лишь тролли из затонувшего храма." }, { 15.64, "В храме есть тролли по имени Ранокол, Миджан, Золо, Хукку, Зул'Лор и Лоро." }, { 21.53, "Не стоит им сочувствовать, они давно пали и их души запятнаны злом." } } }, t = { d = 12.6, v = "human-male#50", n = { x = 142 }, c = { x = { { 0.00, "Великолепно." }, { 0.92, "Я сказал бы, что удивлён, но я ни на минуту не сомневался, что ты не подведёшь нас." }, { 6.66, "Мне выпала честь вручить тебе один из священных камней силы." }, { 11.14, "Пользуйся им во благо." } } } } },
    [8419] = { d = 27.7, g = 1, v = "human-female#45", n = { m = 323, f = 324 }, c = { m = { { 0.00, "С тобой хочет встретиться один бес из Осквернённого леса по имени Бесёнок." }, { 5.18, "Это довольно странно, поскольку он попросил тебя принести отрез ткани Скверны в залог доброй воли." }, { 12.34, "Ты весьма могущественный чернокнижник и наверняка знаешь, что ткань Скверны таскают с собой сатиры Осквернённого леса." }, { 20.58, "Бесёнок живёт на севере от водопада Ядовитой Крови." }, { 24.16, "Говорят, в это время года там очень красиво." } }, f = { { 0.00, "С тобой хочет встретиться один бес из Осквернённого леса по имени Бесёнок." }, { 5.24, "Это довольно странно, поскольку он попросил тебя принести отрез ткани Скверны в залог доброй воли." }, { 12.49, "Ты весьма могущественная чернокнижница и наверняка знаешь, что ткань Скверны таскают с собой сатиры Осквернённого леса." }, { 20.90, "Бесёнок живёт на севере от водопада Ядовитой Крови." }, { 24.52, "Говорят, в это время года там очень красиво." } } }, npc = { [3326] = { d = 32.7, g = 1, v = "orc-male", n = { m = 323, f = 324 }, c = { m = { { 0.00, "С тобой хочет встретиться один бес из Осквернённого леса по имени Бесёнок." }, { 5.97, "Это довольно странно, поскольку он попросил тебя принести отрез ткани Скверны в залог доброй воли." }, { 14.21, "Ты весьма могущественный чернокнижник и наверняка знаешь, что ткань Скверны таскают с собой сатиры Осквернённого леса." }, { 23.71, "Бесёнок живёт на севере от водопада Ядовитой Крови." }, { 27.84, "Говорят, в это время года там очень красиво." } }, f = { { 0.00, "С тобой хочет встретиться один бес из Осквернённого леса по имени Бесёнок." }, { 5.97, "Это довольно странно, поскольку он попросил тебя принести отрез ткани Скверны в залог доброй воли." }, { 14.21, "Ты весьма могущественная чернокнижница и наверняка знаешь, что ткань Скверны таскают с собой сатиры Осквернённого леса." }, { 24.95, "Бесёнок живёт на севере от водопада Ядовитой Крови." }, { 29.08, "Говорят, в э