    [8439] = { d = 23.7, v = "orc-male", n = { x = 246 }, c = { x = { { 0.00, "Наш конфликт с Альянсом дошёл до открытой войны." }, { 3.67, "Никто уже не ищет предлогов, чтобы вступить в бой." }, { 7.51, "В Низине Арати идёт простая и открытая борьба за ресурсы." }, { 12.43, "Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска!" }, { 20.75, "Помоги нам захватить источник ресурсов!" } } }, t = { d = 5.8, v = "orc-male", n = { x = 53 }, c = { x = { { 0.00, "Контроль над ресурсами Низины Арати - важнейшее дело!" }, { 4.87, "Ты молодец." } } } } },
    [8440] = { t = { d = 6.4, v = "orc-male", n = { x = 57 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.56, "Пока Низина Арати в наших руках, припасов нам хватит." } } } } },
    [8441] = { t = { d = 6.2, v = "orc-male", n = { x = 57 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.52, "Пока Низина Арати в наших руках, припасов нам хватит." } } } } },
    [8442] = { t = { d = 7.1, v = "orc-male", n = { x = 60 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.63, "Пока Низина Арати в наших руках, наши запасы не иссякнут." } } } } },
    [8443] = { t = { d = 6.3, v = "orc-male", n = { x = 57 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.54, "Пока Низина Арати в наших руках, припасов нам хватит." } } } } },
    [8446] = { d = 17.4, v = "narrator", n = { x = 181 }, c = { x = { { 0.00, "Эта вещь так и сочится порчей." }, { 2.41, "Может быть, существует связь между ней и драконами, вылетающими из Сна." }, { 7.87, "Кто-то должен разобраться, что делать с этой штукой." }, { 12.06, "Может, тебе обратиться к друидам Лунной поляны или крепости Кенария?" } } }, t = { d = 11.0, v = "creature/remulos", n = { x = 112 }, c = { x = { { 0.00, "Я должен очистить этот предмет от скверны." }, { 3.40, "Тогда, быть может, мне удастся понять, почему в последнее время я не могу проникнуть в Сон." }, { 10.54, "Давай." } } } } },
    [8447] = { d = 8.3, v = "creature/remulos", n = { x = 84 }, c = { x = { { 0.00, "Воды озера Элуны смоют кошмары, поглотившие этот предмет." }, { 4.86, "Это займёт совсем немного времени." }, { 7.74, "Подожди." } } }, t = { d = 6.6, v = "creature/remulos", n = { x = 53 }, c = { x = { { 0.00, "Возьми это кольцо." }, { 1.81, "Оно помогло Малфуриону, а теперь поможет тебе..." } } } } },
    [8460] = { d = 38.9, g = 1, v = "creature/furbolg", n = { m = 354, f = 354 }, c = { m = { { 0.56, "Фурболги Древобрюхов – единственное фурболгское племя, не затронутое порчей." }, { 6.57, "Однако, нынче многие расы без разбору убивают всех фурболгов подряд." }, { 12.07, "Поэтому Древобрюхи мало кому доверяют." }, { 15.21, "Хочешь заслужить доверие?" }, { 17.28, "Изгони из Осквернённого леса поражённых порчей фурболгов Мёртвого Леса, и в один прекрасный день мы признаем тебя союзником." }, { 26.93, "Ты найдёшь первое племя Мёртвого Леса – воинов, следопытов и садовников – к западу от меня." } }, f = { { 0.56, "Фурболги Древобрюхов – единственное фурболгское племя, не затронутое порчей." }, { 6.95, "Однако, нынче многие расы без разбору убивают всех фурболгов подряд." }, { 12.81, "Поэтому Древобрюхи мало кому доверяют." }, { 16.16, "Хочешь заслужить доверие?" }, { 18.36, "Изгони из Осквернённого леса поражённых порчей фурболгов Мёртвого Леса, и в один прекрасный день мы признаем тебя союзницей." }, { 28.63, "Ты найдёшь первое племя Мёртвого Леса – воинов, следопытов и садовников – к западу от меня." } } }, t = { d = 17.1, g = 1, v = "creature/furbolg", n = { m = 132, f = 133 }, c = { m = { { 0.56, "Мы сильно страдаем от того, что случилось в прошлом." }, { 4.69, "Спасибо за всё, что ты сделал для защиты Древобрюхов." }, { 9.51, "И в знак начала нашей дружбы, прими этот скромный подарок." } }, f = { { 0.58, "Мы сильно страдаем от того, что случилось в прошлом." }, { 4.79, "Спасибо за всё, что ты сделала для защиты Древобрюхов." }, { 9.68, "И в знак начала нашей дружбы, прими этот скромный подарок." } } } } },
    [8461] = { d = 38.8, v = "creature/furbolg", n = { x = 382 }, c = { x = { { 0.58, "Прямо на юго-западе отсюда расположен лагерь фурболгов Мёртвого Леса." }, { 5.90, "В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги станут настоящей угрозой." }, { 14.10, "Племя Мёртвого Леса злобное, но это всё действие скверны, поразившей их разум." }, { 20.04, "Они враждебны не от природы, но тут уж ничего не поделать." }, { 24.41, "Мне невыносимо тяжело сражаться против собратьев." }, { 28.17, "Прошу тебя, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается." } } }, t = { d = 38.5, g = 1, v = "creature/furbolg", n = { m = 350, f = 352 }, c = { m = { { 0.56, "Чую, что ты вернулся с победой." }, { 3.12, "Победа... какое пустое слово, если подумать о том, что ещё надо сделать." }, { 9.04, "Как бы то ни было, ты доказал, что достоин нашего доверия." }, { 13.71, "Не сразу фурболги Крепости Древобрюхов начнут относиться к тебе без враждебности в этой берлоге." }, { 21.52, "Но твоё упорство пробьёт стену любой подозрительности, которую мои братья могут питать к тебе." }, { 29.19, "Пока ты не предашь нас и не поднимешь на нас оружия, мы будем находить общий язык." } }, f = { { 0.43, "Чую, что ты вернулась с победой." }, { 3.03, "Победа... какое пустое слово, если подумать о том, что ещё надо сделать." }, { 8.88, "Как бы то ни было, ты доказала, что достойна нашего доверия." }, { 14.11, "Не сразу фурболги Крепости Древобрюхов начнут относиться к тебе без враждебности в этой берлоге." }, { 21.84, "Но твоё упорство пробьёт стену любой подозрительности, которую мои братья могут питать к тебе." }, { 29.43, "Пока ты не предашь нас и не поднимешь на нас оружия, мы будем находить общий язык." } } } } },
    [8462] = { d = 35.9, g = 1, v = "creature/furbolg", n = { m = 328, f = 329 }, c = { m = { { 0.56, "Кто знает, может ты справишься с ещё более страшной угрозой, что нынче нависла над нами, кланом Древобрюхов." }, { 9.05, "Ты уже сумел показать здесь свою доблесть..." }, { 12.58, "Ещё один мой сородич стоит на страже у входа в Крепость Древобрюхов, по этой дороге дальше к северу." }, { 20.50, "Его зовут Нафиэн." }, { 21.98, "Он может показаться тебе злобной грязной тварью, но ты его не бойся." }, { 27.42, "Он всего лишь ищет помощи против злых сил, что угрожают нашему дому." } }, f = { { 0.56, "Кто знает, может ты справишься с ещё более страшной угрозой, что нынче нависла над нами, кланом Древобрюхов." }, { 9.13, "Ты уже сумела показать здесь свою доблесть..." }, { 12.77, "Ещё один мой сородич стоит на страже у входа в Крепость Древобрюхов, по этой дороге дальше к северу." }, { 20.77, "Его зовут Нафиэн." }, { 22.27, "Он может показаться тебе злобной грязной тварью, но ты его не бойся." }, { 27.77, "Он всего лишь ищет помощи против злых сил, что угрожают нашему дому." } } }, t = { d = 35.8, v = "creature/furbolg", n = { x = 333 }, c = { x = { { 0.58, "Ага... ветер принёс мне весть о чужаке не из нашего племени, который ищет союза с фурболгами Крепости Древобрюхов." }, { 9.55, "Добро пожаловать – но знай, моё племя не доверяет чужакам." }, { 14.11, "Времена сейчас смутные, и мы можем доверять только тем, кто вместе с нами сражается с осквернителями наших краёв... тем, кто доказал нам свою верность." }, { 25.93, "А те, кому мы не доверяем, встретят откровенную враждебность, как только войдут в крепость." } } } } },
    [8464] = { d = 41.0, v = "creature/furbolg", n = { x = 425 }, c = { x = { { 0.43, "Древобрюхи держатся особняком." }, { 2.72, "В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов." }, { 14.00, "Племя Зимней Спячки в последнее время становится всё более враждебным к нам." }, { 19.74, "Они, похоже, впали в состояние ярости, всецело поглощённые собственным страхом и ненавистью ко всему, чего они не понимают." }, { 28.98, "Я вынужден просить тебя проредить их ряды, чтобы уменьшить угрозу для нас." }, { 34.59, "Ищи их в деревне Зимней Спячки, далеко на востоке отсюда." } } }, t = { d = 26.3, v = "creature/furbolg", n = { x = 270 }, c = { x = { { 0.43, "Спасибо за то, что вы сделали, как ни печально всё это." }, { 4.30, "Примите это в качестве знака нашей благодарности." }, { 7.92, "Я бы очень просил вас не прекращать оказывать нам помощь." }, { 11.99, "У нас слишком мало союзников, которых мы можем призвать, и без вашей помощи опасность для моего племени была бы слишком велика, чтобы мы могли справиться с нею в одиночку." } } } } },
    [8465] = { d = 41.9, v = "creature/furbolg", n = { x = 411 }, c = { x = { { 0.43, "Порча расползается не только от фурболгов Мёртвого Леса с юга, но и с востока, от фурболгов из племени Зимней Спячки, что в Зимних Ключах." }, { 11.00, "Если хочешь ещё нам помочь, поговори с Сальфой по другую сторону берлоги, у входа в Зимние Ключи." }, { 18.58, "Иди туда по левой тропке." }, { 20.67, "Осторожнее – если мои тамошние сородичи сочтут, что ты – недобрый гость или ненавистный враг, они на тебя нападут." }, { 29.50, "Иди так быстро, как можешь, чтобы избежать стычки." }, { 33.47, "Убьёшь кого из Древобрюхов, пусть даже защищаясь – вызовешь ещё большую враждебность." } } }, t = { d = 28.7, g = 1, v = "creature/furbolg", n = { m = 257, f = 257 }, c = { m = { { 0.58, "Привет тебе, герой – я тут и страж, и глашатай Древобрюхов в Зимних Ключах, и защитник моего племени." }, { 8.57, "Наши сородичи из племени Зимней Спячки в этой холодной земле подпали под ту же власть порчи, что и фурболги Осквернённого леса." }, { 18.57, "Если ты пришёл помочь фурболгам из крепости Древобрюхов, то мы рады принять твоё предложение." } }, f = { { 0.56, "Привет тебе, героиня – я тут и страж, и глашатай Древобрюхов в Зимних Ключах, и защитник моего племени." }, { 8.69, "Наши сородичи из племени Зимней Спячки в этой холодной земле подпали под ту же власть порчи, что и фурболги Осквернённого леса." }, { 18.66, "Если ты пришла помочь фурболгам из крепости Древобрюхов, то мы рады принять твоё предложение." } } } } },
    [8466] = { t = { d = 16.6, v = "creature/furbolg", n = { x = 125 }, c = { x = { { 0.58, "Хорошая работа!" }, { 1.97, "Я уж постараюсь, чтобы мои сородичи узнали о твоих делах." }, { 6.99, "Не забывай приносить мне все перья, что добудешь." }, { 11.15, "Я возьму всё, сколько принесёшь." } } } } },
    [8467] = { t = { d = 15.6, v = "creature/furbolg", n = { x = 125 }, c = { x = { { 0.43, "Хорошая работа!" }, { 1.81, "Я уж постараюсь, чтобы мои сородичи узнали о твоих делах." }, { 6.80, "Не забывай приносить мне все перья, что добудешь." }, { 10.94, "Я возьму всё, сколько принесёшь." } } } } },
    [8469] = { t = { d = 19.8, g = 1, v = "creature/furbolg", n = { m = 155, f = 156 }, c = { m = { { 0.56, "Ты снова доказал свою доблесть!" }, { 3.36, "Я позабочусь о том, чтобы о твоих деяниях узнало всё наше племя." }, { 8.96, "Не забывай приносить мне бусы Зимней Спячки." }, { 12.85, "О каждом твоём успехе я расскажу своим сородичам." } }, f = { { 0.56, "Ты снова доказала свою доблесть!" }, { 3.43, "Я позабочусь о том, чтобы о твоих деяниях узнало всё наше племя." }, { 9.00, "Не забывай приносить мне бусы Зимней Спячки." }, { 12.87, "О каждом твоём успехе я расскажу своим сородичам." } } } } },
    [8470] = { d = 32.1, v = "narrator", n = { x = 362 }, c = { x = { { 0.00, "Вы нашли один из ритуальных тотемов фурболгов клана Мёртвого Леса." }, { 4.91, "Сам тотем ничем не примечателен на вид, но от него исходит ощутимое чувство отчаяния." }, { 11.14, "Если есть предмет, который мог бы стать олицетворением порчи, снедающей фурболгов Мёртвого Леса – то вот он." }, { 18.90, "Один из фурболгов в крепости Древобрюхов мог бы найти применение этому предмету... конечно, если вы уже добились достаточного доверия от них, чтобы они снизошли до разговора с вами." } } }, t = { d = 31.4, g = 1, v = "creature/furbolg", n = { m = 285, f = 289 }, c = { m = { { 0.56, "Тотем... похоже, один из мертволесских, но от него прямо несёт разложением." }, { 6.38, "В этом предмете явственно ощущается то, что обратило наших собратьев против нас." }, { 12.62, "Ты мудро поступил, принеся его нам." }, { 15.42, "Возможно, изучив его и проведя обряды, мы сможем узнать, что отравило разум наших сородичей." }, { 22.71, "Благодарю тебя, друг, – прими эти дары в благодарность за твою находку." } }, f = { { 0.58, "Тотем... похоже, один из мертволесских, но от него прямо несёт разложением." }, { 6.39, "В этом предмете явственно ощущается то, что обратило наших собратьев против нас." }, { 12.62, "Ты мудро поступила, принеся его нам." }, { 15.49, "Возможно, изучив его и проведя обряды, мы сможем узнать, что отравило разум наших сородичей." }, { 22.77, "Благодарю тебя, подруга, – прими эти дары в благодарность за твою находку." } } } } },
    [8471] = { d = 29.8, v = "narrator", n = { x = 315 }, c = { x = { { 0.00, "Вы нашли один из ритуальных тотемов Зимней Спячки." }, { 4.00, "Сам тотем ничем не примечателен на вид, но от него исходят почти осязаемые волны страха и отчаяния." }, { 11.73, "Если такую вещь носят все фурболги, то понятно, что довело их до такого состояния." }, { 18.11, "Кто-нибудь из фурболгов логова Древобрюхов наверняка разберётся с этой вещью... однако фурболги будут говорить только с теми, кому достаточно доверяют." } } }, t = { d = 37.2, v = "creature/furbolg", n = { x = 354 }, c = { x = { { 0.56, "Эта вещь... она имеет форму ритуального тотема Зимней Спячки, однако этот тотем был испорчен непостижимыми для меня силами." }, { 10.29, "Так или иначе, в нём присутствует именно та энергия, которая заставила племя Зимней Спячки обратиться против нас." }, { 19.10, "С твоей стороны было очень мудро принести его нам." }, { 23.15, "Мы тщательно его изучим и, будем надеяться, найдём способ исцелить наших собратьев." }, { 29.66, "Мы благодарны тебе, и просим тебя принять это за твои услуги." } } } } },
    [8481] = { d = 38.8, g = 1, v = "creature/furbolg", n = { m = 354, f = 354 }, c = { m = { { 0.58, "Спасибо тебе за то, что нашёл способ вырвать корень зла из душ племени Зимней Спячки – уничтожить демона, овладевшего ими!" }, { 10.38, "Отнеси этот факел к входу в пещеру верховного вождя племени Зимней Спячки и поставь его там." }, { 18.00, "Это заставит демона появиться." }, { 20.54, "Вот тогда ты со своими союзниками нападёшь на него!" }, { 24.61, "Только сущность погибшего демона поможет начать долгий процесс исцеления племени Зимней Спячки... и спасения Крепости Древобрюхов." } }, f = { { 0.58, "Спасибо тебе за то, что нашла способ вырвать корень зла из душ племени Зимней Спячки – уничтожить демона, овладевшего ими!" }, { 10.68, "Отнеси этот факел к входу в пещеру верховного вождя племени Зимней Спячки и поставь его там." }, { 18.48, "Это заставит демона появиться." }, { 21.08, "Вот тогда ты со своими союзниками нападёшь на него!" }, { 25.25, "Только сущность погибшего демона поможет начать долгий процесс исцеления племени Зимней Спячки... и спасения Крепости Древобрюхов." } } }, t = { d = 32.7, g = 1, v = "creature/furbolg", n = { m = 268, f = 274 }, c = { m = { { 0.58, "Ты... ты спас нас!" }, { 2.10, "Победив демона Зандивиуса, ты на долгие годы обеспечил безопасность Крепости Древобрюхов." }, { 10.04, "Ты настоящий герой для нашего народа." }, { 13.41, "Прошу, прими это с нашим благословением." }, { 17.10, "Исцеление фурболгов будет долгим, и вражда ещё не закончится, но ты дал племени Зимней Спячки то, чего у них никогда прежде не было." }, { 28.82, "Шанс выжить." } }, f = { { 0.43, "Ты... ты спасла нас!" }, { 2.20, "Победив демона Зандивиуса, ты на долгие годы обеспечила безопасность Крепости Древобрюхов." }, { 10.24, "Ты настоящая героиня для нашего народа." }, { 13.78, "Прошу, прими это с нашим благословением." }, { 17.48, "Исцеление фурболгов будет долгим, и вражда ещё не закончится, но ты дала племени Зимней Спячки то, чего у них никогда прежде не было." }, { 29.38, "Шанс выжить." } } } } },
    [8484] = { d = 33.0, g = 1, v = "creature/furbolg", n = { m = 302, f = 303 }, c = { m = { { 0.43, "Твои подвиги выше любых похвал." }, { 3.10, "И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир." }, { 8.96, "Прошу – отнеси этот дар королю дворфов, что живёт в железной горе – вроде бы вы зовёте этот город Стальгорном." }, { 17.78, "В былые времена он пытался заключить с нами союз от имени Альянса." }, { 23.21, "Так что теперь достойно будет, чтобы ты завершил труды Альянса по установлению мира с нами." } }, f = { { 0.43, "Твои подвиги выше любых похвал." }, { 3.13, "И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир." }, { 9.05, "Прошу – отнеси этот дар королю дворфов, что живёт в железной горе – вроде бы вы зовёте этот город Стальгорном." }, { 17.97, "В былые времена он пытался заключить с нами союз от имени Альянса." }, { 23.45, "Так что теперь достойно будет, чтобы ты завершила труды Альянса по установлению мира с нами." } } }, t = { d = 36.2, g = 1, v = "dwarf-male#177", n = { m = 339, f = 340 }, c = { m = { { 0.00, "Воистину, это весьма удачный поворот событий." }, { 4.02, "Если удастся заключить прочный мир с этими созданиями, это, несомненно, даст нам преимущество в делах Калимдора... которого ночные эльфы не смогут добиться в одиночку." }, { 18.31, "Я немедленно извещу об этом других вождей Альянса, и туда будут отправлены новые послы!" }, { 25.96, "Что до тебя... ты проявил отвагу и в дипломатии, и в деле." }, { 30.91, "Благодарю тебя – и вместе со мной тебя благодарит весь Альянс." } }, f = { { 0.00, "Воистину, это весьма удачный поворот событий." }, { 4.02, "Если удастся заключить прочный мир с этими созданиями, это, несомненно, даст нам преимущество в делах Калимдора... которого ночные эльфы не смогут добиться в одиночку." }, { 18.31, "Я немедленно извещу об этом других вождей Альянса, и туда будут отправлены новые послы!" }, { 25.96, "Что до тебя... ты проявила отвагу и в дипломатии, и в деле." }, { 30.99, "Благодарю тебя – и вместе со мной тебя благодарит весь Альянс." } } } } },
    [8485] = { d = 32.2, g = 1, v = "creature/furbolg", n = { m = 291, f = 292 }, c = { m = { { 0.58, "Твои подвиги выше любых похвал." }, { 3.22, "И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир." }, { 9.01, "Прошу – отнеси этот дар вождю орков, что живёт в Дуротаре." }, { 13.66, "Кажется, вы называете его город Оргриммаром." }, { 17.23, "В былые времена он пытался заключить с нами союз от имени Орды." }, { 22.38, "Так что теперь достойно будет, чтобы ты завершил труды Орды по установлению мира с нами." } }, f = { { 0.43, "Твои подвиги выше любых похвал." }, { 3.10, "И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир." }, { 8.93, "Прошу – отнеси этот дар вождю орков, что живёт в Дуротаре." }, { 13.62, "Кажется, вы называете его город Оргриммаром." }, { 17.22, "В былые времена он пытался заключить с нами союз от имени Орды." }, { 22.41, "Так что теперь достойно будет, чтобы ты завершила труды Орды по установлению мира с нами." } } }, t = { d = 31.3, g = 1, v = "named/thrall", n = { m = 295, f = 296 }, c = { m = { { 0.00, "Воистину, это весьма удачный поворот событий." }, { 3.98, "Если удастся заключить прочный мир с этими созданиями, это, несомненно, поможет нам защитить Калимдор от внешних угроз." }, { 14.15, "Я немедленно извещу об этом других вождей Орды, и туда будут отправлены новые послы!" }, { 21.49, "Что до тебя... ты проявил отвагу и в дипломатии, и в деле." }, { 26.39, "Благодарю тебя – и вместе со мной тебя благодарит вся Орда." } }, f = { { 0.00, "Воистину, это весьма удачный поворот событий." }, { 3.91, "Если удастся заключить прочный мир с этими созданиями, это, несомненно, поможет нам защитить Калимдор от внешних угроз." }, { 13.90, "Я немедленно извещу об этом других вождей Орды, и туда будут отправлены новые послы!" }, { 21.11, "Что до тебя... ты проявила отвагу и в дипломатии, и в деле." }, { 26.00, "Благодарю тебя – и вместе со мной тебя благодарит вся Орда." } } } } },
    [8492] = { d = 19.4, g = 1, v = "dwarf-male", n = { m = 207, f = 207 }, c = { m = { { 0.00, "Здорово, герой!" }, { 1.20, "На вид ты вполне пригоден к тому, чтобы принять участие в подготовке к войне!" }, { 6.91, "Нам пригодится любая помощь, так что наступил твой звёздный час." }, { 11.50, "Я собираю медные слитки стопками по двадцать штук." }, { 15.22, "Дело благое, да?" }, { 16.49, "Ты как, хочешь оказать помощь Альянсу?" } }, f = { { 0.00, "Здорово, героиня!" }, { 1.34, "На вид ты вполне пригодна к тому, чтобы принять участие в подготовке к войне!" }, { 7.09, "Нам пригодится любая помощь, так что наступил твой звёздный час." }, { 11.70, "Я собираю медные слитки стопками по двадцать штук." }, { 15.44, "Дело благое, да?" }, { 16.71, "Ты как, хочешь оказать помощь Альянсу?" } } }, t = { d = 13.8, v = "dwarf-male", n = { x = 152 }, c = { x = { { 0.00, "Похвально, солдат!" }, { 1.41, "Сейчас мы уложим эти слитки в штабель и используем их по назначению." }, { 6.52, "Альянс будет гордиться тобой." }, { 8.80, "Если раздобудешь ещё стопку медных слитков, не раздумывай, неси мне." } } } } },
    [8493] = { d = 8.9, g = 1, v = "dwarf-male", n = { m = 94, f = 95 }, c = { m = { { 0.00, "Ты вернулся, герой?" }, { 1.46, "Превосходно!" }, { 2.39, "Для подготовки к войне в Ан'Кираже всё ещё нужны медные слитки." }, { 7.04, "Ты поможешь нам собрать их?" } }, f = { { 0.00, "Ты вернулась, героиня?" }, { 1.62, "Превосходно!" }, { 2.53, "Для подготовки к войне в Ан'Кираже всё ещё нужны медные слитки." }, { 7.08, "Ты поможешь нам собрать их?" } } }, t = { d = 22.7, g = 1, v = "dwarf-male", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Прекрасная работа!" }, { 1.35, "Добыча и выплавка всей этой меди, должно быть, была тем ещё развлечением." }, { 6.56, "Если, конечно, ты не купил слитки на аукционе." }, { 9.91, "В любом случае, главное – результат." }, { 12.55, "Приложенные тобой усилия не останутся незамеченными, герой." }, { 16.79, "Если раздобудешь ещё слитки, без малейшего колебания неси их мне." } }, f = { { 0.00, "Прекрасная работа!" }, { 1.43, "Добыча и выплавка всей этой меди, должно быть, была тем ещё развлечением." }, { 6.94, "Если, конечно, ты не купила слитки на аукционе." }, { 10.55, "В любом случае, главное – результат." }, { 13.34, "Приложенные тобой усилия не останутся незамеченными, героиня." }, { 17.97, "Если раздобудешь ещё слитки, без малейшего колебания неси их мне." } } } } },
    [8494] = { d = 25.7, g = 1, v = "human-male#50", n = { m = 303, f = 302 }, c = { m = { { 0.00, "Эгей, мистер Красивые Штанишки, ты прямо отрада для моих измученных глаз." }, { 5.02, "Пока ты шатался по городам и весям в поисках приключений, у нас тут произошла прорва всего." }, { 11.20, "К примеру, Альянс вот готовится к войне в Ан'Кираже, и всем резко понадобились железные слитки... чёртова прорва железных слитков." }, { 19.95, "Можешь таскать их мне стопками по двадцать." }, { 22.88, "Ну как, могу я на тебя рассчитывать, герой?" } }, f = { { 0.00, "Эгей, мисс Красивые Штанишки, ты прямо отрада для моих измученных глаз." }, { 4.82, "Пока ты шаталась по городам и весям в поисках приключений, у нас тут произошла прорва всего." }, { 11.04, "К примеру, Альянс вот готовится к войне в Ан'Кираже, и всем резко понадобились железные слитки... чёртова прорва железных слитков." }, { 19.76, "Можешь таскать их мне стопками по двадцать." }, { 22.69, "Ну как, могу я на тебя рассчитывать, героиня?" } } }, t = { d = 17.8, v = "human-male#50", n = { x = 201 }, c = { x = { { 0.00, "Ну хорошо, на этот раз тебе удалось вывернуться." }, { 3.44, "Пожалуй, на будущее за тобой стоит приглядывать." }, { 6.89, "Как ни тяжело это говорить, но спасибо тебе за помощь." }, { 10.78, "Альянс тебя не забудет, и я тоже." }, { 13.20, "А теперь дуй-ка отсюда и лучше помоги ещё кому-нибудь в заготовках." } } } } },
    [8495] = { d = 27.1, g = 1, v = "human-male#50", n = { x = 332 }, c = { m = { { 0.00, "Ты опять здесь?" }, { 0.99, "Не заставляй меня слишком хорошо о тебе думать, герой, а то я прямо таять начинаю." }, { 6.41, "Как видишь, мы ещё не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и всё остальное-прочее, что нужно изготовить для большой драчки." }, { 17.29, "Я думаю, ты сможешь принести ещё слитков двадцать в перерыве между своими шатаниями в Зул'Гуруб, или где там у вас, у молодёжи, сейчас модно тусоваться." } }, f = { { 0.00, "Ты опять здесь?" }, { 0.99, "Не заставляй меня слишком хорошо о тебе думать, героиня, а то я прямо таять начинаю." }, { 6.55, "Как видишь, мы ещё не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и всё остальное-прочее, что нужно изготовить для большой драчки." }, { 17.49, "Я думаю, ты сможешь принести ещё слитков двадцать в перерыве между своими шатаниями в Зул'Гуруб, или где там у вас, у молодёжи, сейчас модно тусоваться." } } }, t = { d = 20.9, v = "human-male#50", n = { x = 236 }, c = { x = { { 0.00, "Должно быть, в Пылающих Степях выпал снег." }, { 3.04, "Вы только посмотрите, кто пришёл, да не просто так, а с подарком." }, { 7.57, "Двадцать железных слитков!" }, { 9.51, "Именно то, что мне нужно." }, { 11.32, "Хочу сказать тебе со всей серьёзностью, Альянс перед тобой в долгу." }, { 16.17, "А теперь давай, шлёпай отсюда и помоги ещё кому-нибудь в заготовках." } } } } },
    [8496] = { d = 14.3, v = "narrator", n = { x = 169 }, c = { x = { { 0.00, "В последнее время мы понесли серьёзные потери, и запас бинтов стремительно иссякает." }, { 6.20, "Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордый Рог в крепость Кенария." } } }, t = { d = 11.8, v = "tauren-female#71", n = { x = 116 }, c = { x = { { 0.00, "Ты как раз вовремя." }, { 1.65, "Принесённые тобой перевязочные материалы спасут немало жизней." }, { 7.06, "Мы благодарны тебе за труды." }, { 9.57, "Вот твоё следующее задание." } } } } },
    [8497] = { d = 21.0, v = "narrator", n = { x = 248 }, c = { x = { { 0.00, "В крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне." }, { 7.30, "Новичкам грозит обезвоживание и множество ядовитых тварей." }, { 11.58, "Собери как можно больше составляющих неприкосновенных наборов для отправляющихся в пустыню и отнеси их Каландрате в крепость Кенария." } } }, t = { d = 4.5, v = "nightelf-female#53", n = { x = 39 }, c = { x = { { 0.00, "Отлично!" }, { 0.84, "Нам очень нужны эти материалы." }, { 3.80, "Спасибо." } } } } },
    [8498] = { d = 13.4, v = "narrator", n = { x = 151 }, c = { x = { { 0.00, "Разведчики донесли, что от вождей Сумеречного Молота поступили новые приказы." }, { 5.87, "Их распространяют пророки под охраной солдат." }, { 9.28, "Перехвати эти приказы и принеси их командиру Мар'алиту." } } }, t = { d = 10.2, v = "nightelf-male#54", n = { x = 107 }, c = { x = { { 0.00, "Великолепно." }, { 1.05, "Главное – опережать противника на ход." }, { 4.22, "Благодаря полученным сведениям, нам известны намерения Сумеречного Молота." } } } } },
