    [8503] = { d = 30.9, g = 1, v = "gnome-male", n = { x = 336 }, c = { m = { { 0.00, "Знаешь ли ты, герой, насколько широко и разнообразно применение удавника?" }, { 5.17, "Как, я тебе уже об этом рассказывал?" }, { 7.78, "Правда?.." }, { 8.49, "Ну ладно." }, { 9.19, "В любом случае, нам нужно много этой травы, и когда я говорю так, я имею в виду действительно МНОГО!" }, { 16.40, "Не следует ли тебе помочь нам, как ты считаешь?" }, { 19.71, "Я понимаю, это означает, что тебе придётся остаться без всех этих чудесных штучек, которые можно приготовить из удавника... но ведь это ради благого дела!" } }, f = { { 0.00, "Знаешь ли ты, героиня, насколько широко и разнообразно применение удавника?" }, { 5.15, "Как, я тебе уже об этом рассказывал?" }, { 7.69, "Правда?.." }, { 8.38, "Ну ладно." }, { 9.06, "В любом случае, нам нужно много этой травы, и когда я говорю так, я имею в виду действительно МНОГО!" }, { 16.07, "Не следует ли тебе помочь нам, как ты считаешь?" }, { 19.29, "Я понимаю, это означает, что тебе придётся остаться без всех этих чудесных штучек, которые можно приготовить из удавника... но ведь это ради благого дела!" } } }, t = { d = 13.8, g = 1, v = "gnome-male", n = { x = 132 }, c = { m = { { 0.00, "Урра!" }, { 0.51, "Ещё двадцатью меньше собирать." }, { 2.99, "Отлично справляешься с работой!" }, { 5.54, "Пойду уберу травы, пока они не засохли." }, { 8.89, "Времени так мало, а удавника так много!" }, { 12.10, "Спасибо ещё раз, герой!" } }, f = { { 0.00, "Урра!" }, { 0.50, "Ещё двадцатью меньше собирать." }, { 2.96, "Отлично справляешься с работой!" }, { 5.48, "Пойду уберу травы, пока они не засохли." }, { 8.80, "Времени так мало, а удавника так много!" }, { 11.97, "Спасибо ещё раз, героиня!" } } } } },
