    [8507] = { d = 33.7, v = "nightelf-male#55", n = { x = 412 }, c = { x = { { 0.00, "Приветствую тебя." }, { 1.24, "Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные." }, { 7.63, "Дружина Стальгорна под предводительством капитана Чёрной Наковальни расквартирована рядом с Ульем Зора." }, { 14.65, "Поговори с капитаном и его лейтенантом, Джанелой Твердомолот, а потом возвращайся." }, { 20.29, "Тем временем я подготовлю для тебя новое задание." }, { 23.71, "Ах да, сделай одолжение, держись подальше от легиона Оргриммара." }, { 28.11, "Нам нелегко удерживать эти два войска от грызни, очень уж они друг друга не любят." } } }, t = { d = 18.2, v = "nightelf-male#55", n = { x = 212 }, c = { x = { { 0.00, "Отлично." }, { 0.65, "Я подготовил целую серию заданий, которые наилучшим образом распорядятся твоими навыками." }, { 7.12, "Если ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!" }, { 12.75, "Если тебе понадобится новое задание, возвращайся к капитану Чёрной Наковальне." } } } } },
