    [8509] = { d = 17.3, g = 1, v = "human-female#47", n = { x = 197 }, c = { m = { { 0.00, "Я предпочитаю говорить быстро и по существу, герой." }, { 3.48, "Альянсу нужно много слёз Артаса для войны в Ан'Кираже." }, { 7.20, "Не спрашивай меня, зачем, я всего лишь выполняю приказ." }, { 10.98, "Собери столько этих цветов, сколько унесёшь, и сдай мне." }, { 14.76, "Ну что, возьмёшься за это задание?" } }, f = { { 0.00, "Я предпочитаю говорить быстро и по существу, героиня." }, { 3.66, "Альянсу нужно много слёз Артаса для войны в Ан'Кираже." }, { 7.44, "Не спрашивай меня, зачем, я всего лишь выполняю приказ." }, { 11.28, "Собери столько этих цветов, сколько унесёшь, и сдай мне." }, { 15.13, "Ну что, возьмёшься за это задание?" } } }, t = { d = 20.3, g = 1, v = "human-female#47", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Неплохо сработано, герой." }, { 1.74, "Должна сказать, я приятно удивлена." }, { 4.15, "Ты никогда бы не поверил, сколько людей приходят, обещают помочь и не возвращаются." }, { 9.68, "Одну секунду, сейчас я упакую травы в ящик и прикреплю к нему бирку с твоим именем, а потом сможем поговорить на тему того, нужны ли мне ещё эти растения." } }, f = { { 0.00, "Неплохо сработано, героиня." }, { 1.88, "Должна сказать, я приятно удивлена." }, { 4.30, "Ты никогда бы не поверила, сколько людей приходят, обещают помочь и не возвращаются." }, { 9.93, "Одну секунду, сейчас я упакую травы в ящик и прикреплю к нему бирку с твоим именем, а потом сможем поговорить на тему того, нужны ли мне ещё эти растения." } } } } },
