    [8511] = { d = 33.1, g = 1, v = "dwarf-female", n = { m = 359, f = 359 }, c = { m = { { 0.00, "Наш клан Обдирщиков Камня испокон века знал толк в снятии шкур, герой." }, { 5.03, "Как говорится, и с камня снимем шкуру." }, { 7.83, "Потому-то Альянс и попросил нас взяться за заготовку лёгкой кожи для войны в Ан'Кираже." }, { 14.10, "Я слежу, чтобы кожа была хорошо выдублена, уж не знаю, для чего она там понадобится." }, { 20.30, "Но без помощи мне никак не обойтись." }, { 22.91, "Пока я здесь за всем надзираю, тебе придётся прогуляться малость и добыть кож, а потом принести их мне." }, { 30.22, "Ну что, паренёк, возьмёшься за дело?" } }, f = { { 0.00, "Наш клан Обдирщиков Камня испокон века знал толк в снятии шкур, героиня." }, { 5.21, "Как говорится, и с камня снимем шкуру." }, { 8.05, "Потому-то Альянс и попросил нас взяться за заготовку лёгкой кожи для войны в Ан'Кираже." }, { 14.39, "Я слежу, чтобы кожа была хорошо выдублена, уж не знаю, для чего она там понадобится." }, { 20.66, "Но без помощи мне никак не обойтись." }, { 23.30, "Пока я здесь за всем надзираю, тебе придётся прогуляться малость и добыть кож, а потом принести их мне." }, { 30.69, "Ну что, девушка, возьмёшься за дело?" } } }, t = { d = 20.6, g = 1, v = "dwarf-female", n = { x = 204 }, c = { m = { { 0.00, "Я прямо скажу, Альянсу крупно повезло, что у него есть такие искушённые специалисты по снятию шкур, как ты, герой." }, { 8.73, "Уж я прослежу, чтобы ни одну кожу ненароком не попортили." }, { 13.20, "Спасибо тебе – и не забудь, когда я пересчитаю кожу, справься у меня, не требуется ли нам ещё." } }, f = { { 0.00, "Я прямо скажу, Альянсу крупно повезло, что у него есть такие искушённые специалисты по снятию шкур, как ты, героиня." }, { 8.92, "Уж я прослежу, чтобы ни одну кожу ненароком не попортили." }, { 13.41, "Спасибо тебе – и не забудь, когда я пересчитаю кожу, справься у меня, не требуется ли нам ещё." } } } } },
