    [8515] = { d = 27.6, g = 1, v = "gnome-female", n = { x = 274 }, c = { m = { { 0.00, "О, будет так здорово!" }, { 1.73, "Герой, приготовления к ан'киражской войне идут вовсю, и так получилось, что я отвечаю за заготовку плотной кожи." }, { 10.67, "Из неё мы сможем наделать тысячи разных вещей, но сначала надо её достать – тоже тысячами." }, { 17.94, "В буквальном смысле." }, { 19.60, "И тут на сцену выходишь ты." }, { 21.76, "Ты ведь принесёшь мне отличную увесистую кипу плотной кожи?" }, { 26.45, "Правда-правда?" } }, f = { { 0.00, "О, будет так здорово!" }, { 1.73, "Героиня, приготовления к ан'киражской войне идут вовсю, и так получилось, что я отвечаю за заготовку плотной кожи." }, { 10.78, "Из неё мы сможем наделать тысячи разных вещей, но сначала надо её достать – тоже тысячами." }, { 18.05, "В буквальном смысле." }, { 19.70, "И тут на сцену выходишь ты." }, { 21.86, "Ты ведь принесёшь мне отличную увесистую кипу плотной кожи?" }, { 26.53, "Правда-правда?" } } }, t = { d = 29.4, g = 1, v = "gnome-female", n = { m = 270, f = 272 }, c = { m = { { 0.00, "О, я знала, что ты справишься, герой, конечно же, я это знала!" }, { 5.10, "Я отправлю эту кожу по нужному адресу, как только смогу." }, { 9.83, "Ага, а теперь давай-ка посмотрим." }, { 12.64, "Похоже, в итоге всё получается очень, очень миленько." }, { 17.07, "Загляни ко мне ещё разочек, я сейчас проверю, не нужно ли нам ещё кожи." }, { 22.83, "Если понадобится, то было бы так здорово, если бы ты смог достать для нас ещё!" } }, f = { { 0.00, "О, я знала, что ты справишься, героиня, конечно же, я это знала!" }, { 5.25, "Я отправлю эту кожу по нужному адресу, как только смогу." }, { 9.99, "Ага, а теперь давай-ка посмотрим." }, { 12.80, "Похоже, в итоге всё получается очень, очень миленько." }, { 17.23, "Загляни ко мне ещё разочек, я сейчас проверю, не нужно ли нам ещё кожи." }, { 23.00, "Если понадобится, то было бы так здорово, если бы ты смогла достать для нас ещё!" } } } } },
    [8516] = { d = 32.1, g = 1, v = "gnome-female", n = { x = 335 }, c = { m = { { 0.00, "Да-да, стопки всё ещё не очень высокие." }, { 2.95, "Путник, мы не выполняем норму – не хватает целой уймы кусков плотной кожи." }, { 8.58, "Только подумай, сколько всего полезного из неё можно сделать!" }, { 13.20, "Броню и оружие на любой вкус!" }, { 15.41, "Она годится как на отделку паровых танков, так и на оптические винтовки." }, { 20.77, "Держу пари, всё закончится тем, что мы соберём столько кожи, что остаток придётся отдать Орде на дирижабли." }, { 28.61, "Ты ведь принесёшь мне ещё плотной кожи?" } }, f = { { 0.00, "Да-да, стопки всё ещё не очень высокие." }, { 3.02, "Путница, мы не выполняем норму – не хватает целой уймы кусков плотной кожи." }, { 8.85, "Только подумай, сколько всего полезного из неё можно сделать!" }, { 13.58, "Броню и оружие на любой вкус!" }, { 15.84, "Она годится как на отделку паровых танков, так и на оптические винтовки." }, { 21.33, "Держу пари, всё закончится тем, что мы соберём столько кожи, что остаток придётся отдать Орде на дирижабли." }, { 29.35, "Ты ведь принесёшь мне ещё плотной кожи?" } } }, t = { d = 25.2, g = 1, v = "gnome-female", n = { m = 264, f = 265 }, c = { m = { { 0.00, "У тебя снова всё получилось!" }, { 2.29, "Просто невероятно, как ты умудряешься выбраться отсюда, собрать всё, что нужно, а потом ещё вернуться и сдать всё мне." }, { 11.46, "Когда люди узнают, сколько ты для нас сделал, они встанут в очередь за твоими автографами!" }, { 18.69, "Большое-пребольшое спасибо за столь благородное и щедрое пожертвование плотной кожи." } }, f = { { 0.00, "У тебя снова всё получилось!" }, { 2.27, "Просто невероятно, как ты умудряешься выбраться отсюда, собрать всё, что нужно, а потом ещё вернуться и сдать всё мне." }, { 11.35, "Когда люди узнают, сколько ты для нас сделала, они встанут в очередь за твоими автографами!" }, { 18.59, "Большое-пребольшое спасибо за столь благородное и щедрое пожертвование плотной кожи." } } } } },
    [8517] = { d = 25.7, g = 1, v = "nightelf-female#52", n = { x = 299 }, c = { m = { { 0.00, "Война в Ан'Кираже будет долгой и кровавой." }, { 2.90, "Прибегнуть к помощи людей, подобных тебе, было для Альянса мудрым решением." }, { 8.02, "Перед тем как сломя голову ринуться в военный конфликт, надо собрать достаточно припасов." }, { 14.06, "Мне поручили запасать льняные бинты, и я надеюсь, что ты мне поможешь." }, { 18.70, "Это не так-то легко, но по крайней мере льняные бинты проще всего изготовить." }, { 24.01, "Что скажешь, герой?" } }, f = { { 0.00, "Война в Ан'Кираже будет долгой и кровавой." }, { 2.94, "Прибегнуть к помощи людей, подобных тебе, было для Альянса мудрым решением." }, { 8.14, "Перед тем как сломя голову ринуться в военный конфликт, надо собрать достаточно припасов." }, { 14.26, "Мне поручили запасать льняные бинты, и я надеюсь, что ты мне поможешь." }, { 18.97, "Это не так-то легко, но по крайней мере льняные бинты проще всего изготовить." }, { 24.35, "Что скажешь, героиня?" } } }, t = { d = 19.4, g = 1, v = "nightelf-female#52", n = { m = 204, f = 205 }, c = { m = { { 0.00, "Многим солдатам ты, считай, сослужил добрую службу, герой." }, { 4.21, "Я лично прослежу, чтобы твои усилия не остались незамеченными." }, { 8.68, "Одну минуту, сейчас я упакую эти бинты, куда надо, и внесу их в реестр, а потом посмотрим, нужно ли мне ещё." }, { 16.46, "Да осенит тебя своим светом Элуна, путник!" } }, f = { { 0.00, "Многим солдатам ты, считай, сослужила добрую службу, героиня." }, { 4.29, "Я лично прослежу, чтобы твои усилия не остались незамеченными." }, { 8.64, "Одну минуту, сейчас я упакую эти бинты, куда надо, и внесу их в реестр, а потом посмотрим, нужно ли мне ещё." }, { 16.23, "Да осенит тебя своим светом Элуна, путница!" } } } } },
    [8518] = { d = 13.5, g = 1, v = "nightelf-female#52", n = { x = 157 }, c = { m = { { 0.00, "Меня всегда изумляет самоотверженность – ведь столь многие обычно гораздо более склонны к эгоизму." }, { 6.57, "Герой, я всё никак не могу выполнить свою норму по сбору льняных бинтов." }, { 11.51, "Не поможешь ли мне ещё раз?" } }, f = { { 0.00, "Меня всегда изумляет самоотверженность – ведь столь многие обычно гораздо более склонны к эгоизму." }, { 6.71, "Героиня, я всё никак не могу выполнить свою норму по сбору льняных бинтов." }, { 11.88, "Не поможешь ли мне ещё раз?" } } }, t = { d = 14.9, v = "nightelf-female#52", n = { x = 183 }, c = { x = { { 0.00, "Прими мою благодарность." }, { 1.73, "Пока некоторые пытаются нажиться на подготовке к войне, ты раз за разом доказываешь свою бескорыстную преданность делу Альянса, да что там, всего Азерота." }, { 12.24, "Да пребудет с тобой благословение Элуны!" } } } } },
    [8519] = { d = 14.6, v = "narrator", n = { x = 143 }, c = { x = { { 0.00, "Успокоившись и сосредоточив взгляд на кристалле, вы замечаете, что внутри что-то шевелится." }, { 7.63, "Посмотрев поближе, вы осознаете, что перед вами предстало прошлое... давно забытое." } } }, t = { d = 34.5, v = "creature/anachronos", n = { x = 353 }, c = { x = { { 0.00, "После предательства Оленьего Шлема я собрал осколки скипетра Зыбучих песков и вернулся сюда." }, { 7.70, "Я желал охранить скипетр от посягательств тех, кто был готов воспользоваться им во зло – так стаи драконов приняли на себя этот долг." }, { 18.43, "Мне казалось, что если разделить части скипетра между четырьмя могущественными Аспектами, то взыскующие Хаос не смогут восстановить его." }, { 29.60, "Я был глупцом." }, { 30.79, "Проклятые драконы охотятся на меня по сей день." } } } } },
    [8520] = { d = 16.6, v = "human-female", n = { x = 194 }, c = { x = { { 0.00, "На горизонте маячит война в Ан'Кираже, так что мы должны приложить все усилия, чтобы на поле боя солдаты ни в чём не нуждались." }, { 8.76, "Именно этим мы и занимаемся." }, { 10.76, "Я вот, например, отвечаю за заготовку шёлковых бинтов." }, { 14.45, "Не хочешь ли мне помочь малость?" } } }, t = { d = 11.8, g = 1, v = "human-female", n = { x = 119 }, c = { m = { { 0.00, "Герой, ты молодчина!" }, { 1.56, "Спасибо за бинты." }, { 2.92, "Благодаря тебе мы ещё на шаг приблизились к нашей общей цели." }, { 7.54, "Сейчас пойду уберу бинты, а потом можем ещё поболтать." } }, f = { { 0.00, "Героиня, ты молодчина!" }, { 1.71, "Спасибо за бинты." }, { 3.08, "Благодаря тебе мы ещё на шаг приблизились к нашей общей цели." }, { 7.74, "Сейчас пойду уберу бинты, а потом можем ещё поболтать." } } } } },
    [8521] = { d = 9.9, g = 1, v = "human-female", n = { x = 115 }, c = { m = { { 0.00, "Очень мило с твоей стороны снова предложить мне помощь, герой." }, { 4.28, "Мы пока собрали всего лишь немного шёлковых бинтов, так что ещё работать и работать." } }, f = { { 0.00, "Очень мило с твоей стороны снова предложить мне помощь, героиня." }, { 4.45, "Мы пока собрали всего лишь немного шёлковых бинтов, так что ещё работать и работать." } } }, t = { d = 17.0, v = "human-female", n = { x = 188 }, c = { x = { { 0.00, "Приятно иметь дело с бескорыстными ребятами вроде тебя." }, { 4.14, "Мы не забудем твой вклад в подготовку к войне." }, { 7.43, "Именно от таких, как ты, и зависит, победим мы или проиграем." }, { 11.91, "Я надеюсь, что наших усилий хватит для победы." }, { 15.33, "Ещё раз большое спасибо!" } } } } },
    [8522] = { d = 24.7, g = 1, v = "nightelf-male#55", n = { x = 278 }, c = { m = { { 0.00, "Считай ведение войны сколь угодно сомнительным занятием, герой, но военная машина уже завертелась." }, { 6.93, "Оглянись на свою семью и друзей и спроси, чем ты можешь помочь им, – ведь все мы попадём в горнило битвы, и надо будет как-то выживать." }, { 16.31, "Именно поэтому я запасаюсь бинтами из рунной ткани, кто бы их ни принёс." }, { 21.29, "Не хочешь ли внести посильный вклад в это дело?" } }, f = { { 0.00, "Считай ведение войны сколь угодно сомнительным занятием, героиня, но военная машина уже завертелась." }, { 7.09, "Оглянись на свою семью и друзей и спроси, чем ты можешь помочь им, – ведь все мы попадём в горнило битвы, и надо будет как-то выживать." }, { 16.51, "Именно поэтому я запасаюсь бинтами из рунной ткани, кто бы их ни принёс." }, { 21.51, "Не хочешь ли внести посильный вклад в это дело?" } } }, t = { d = 15.0, g = 1, v = "nightelf-male#55", n = { x = 165 }, c = { m = { { 0.00, "Твоя настойчивость в выполнении этого задания выше всяких похвал, герой." }, { 5.38, "Сейчас я уберу бинты на склад и вернусь." }, { 8.32, "Я бы хотел побеседовать с тобой относительно возможности добыть ещё бинтов из рунной ткани." } }, f = { { 0.00, "Твоя настойчивость в выполнении этого задания выше всяких похвал, героиня." }, { 5.55, "Сейчас я уберу бинты на склад и вернусь." }, { 8.52, "Я бы хотел побеседовать с тобой относительно возможности добыть ещё бинтов из рунной ткани." } } } } },
    [8523] = { d = 17.5, g = 1, v = "nightelf-male#55", n = { x = 198 }, c = { m = { { 0.00, "Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, герой." }, { 5.54, "Хочу ещё раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно." }, { 12.12, "Но работы ещё непочатый край." }, { 14.21, "Можешь принести мне ещё бинтов из рунной ткани?" } }, f = { { 0.00, "Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, героиня." }, { 5.58, "Хочу ещё раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно." }, { 12.05, "Но работы ещё непочатый край." }, { 14.11, "Можешь принести мне ещё бинтов из рунной ткани?" } } }, t = { d = 14.4, v = "nightelf-male#55", n = { x = 163 }, c = { x = { { 0.00, "Я рад что этот путь мы проделали вместе." }, { 2.92, "Работать с тобой – одно удовольствие." }, { 5.71, "Хочу ещё раз поблагодарить за бескорыстную помощь Альянсу тебя и всех, подобных тебе." }, { 11.96, "Возвращайся скорей, побеседуем ещё." } } } } },
    [8524] = { d = 26.4, g = 1, v = "gnome-male", n = { m = 285, f = 286 }, c = { m = { { 0.00, "Эй, дружище!" }, { 0.91, "Если бы я спросил тебя: \"Нужно ли солдатам на войне хорошо кушать?\" – ты бы, без сомнения, ответил: \"Да, конечно!\"." }, { 9.12, "И я абсолютно с тобой согласен!" }, { 11.39, "Рад, что мы сошлись во мнениях." }, { 13.59, "Теперь, я думаю, ты не будешь спорить, что тебе осталось только отправиться на рыбалку, наловить радужного тунца, приготовить всю порцию и принести мне." }, { 24.46, "М-м-м, я уже в предвкушении." } }, f = { { 0.00, "Эй, дружище!" }, { 0.91, "Если бы я спросил тебя: \"Нужно ли солдатам на войне хорошо кушать?\" – ты бы, без сомнения, ответила: \"Да, конечно!\"." }, { 9.19, "И я абсолютно с тобой согласен!" }, { 11.46, "Рад, что мы сошлись во мнениях." }, { 13.66, "Теперь, я думаю, ты не будешь спорить, что тебе осталось только отправиться на рыбалку, наловить радужного тунца, приготовить всю порцию и принести мне." }, { 24.54, "М-м-м, я уже в предвкушении." } } }, t = { d = 19.5, g = 1, v = "gnome-male", n = { m = 202, f = 204 }, c = { m = { { 0.00, "Два для Альянса, один мне, два для Альянса, один мне..." }, { 4.00, "Эгей, отличная работа, рыбак!" }, { 6.27, "Похоже, ты отличное приобретение для нашего клуба." }, { 10.01, "А мне кажется, надо б раздобыть ещё тунца." }, { 13.14, "Почему бы тебе не прогуляться и не принести ещё рыбки?" }, { 17.15, "У меня уже в животе урчит..." } }, f = { { 0.00, "Два для Альянса, один мне, два для Альянса, один мне..." }, { 4.04, "Эгей, отличная работа, рыбачка!" }, { 6.47, "Похоже, ты отличное приобретение для нашего клуба." }, { 10.24, "А мне кажется, надо б раздобыть ещё тунца." }, { 13.40, "Почему бы тебе не прогуляться и не принести ещё рыбки?" }, { 17.44, "У меня уже в животе урчит..." } } } } },
    [8525] = { d = 24.2, g = 1, v = "gnome-male", n = { m = 248, f = 248 }, c = { m = { { 0.00, "Что?" }, { 0.34, "Снова ты?" }, { 1.08, "Ну и дела, не будь я гном!" }, { 2.97, "Гладень Гастрогном, чтобы быть точным." }, { 5.88, "Выходит, ты пришёл, чтобы снова помочь мне?" }, { 9.12, "Не могу сказать, чтобы я был этим недоволен." }, { 12.50, "А может, тебе просто понравилось, как пахнет жареный тунец?" }, { 16.96, "*облизывается*" }, { 18.40, "Ладно, хватит болтать." }, { 20.09, "Ступай-ка и принеси мне побольше радужного тунца!" } }, f = { { 0.00, "Что?" }, { 0.34, "Снова ты?" }, { 1.08, "Ну и дела, не будь я гном!" }, { 2.96, "Гладень Гастрогном, чтобы быть точным." }, { 5.86, "Выходит, ты пришла, чтобы снова помочь мне?" }, { 9.15, "Не могу сказать, чтобы я был этим недоволен." }, { 12.52, "А может, тебе просто понравилось, как пахнет жареный тунец?" }, { 16.96, "*облизывается*" }, { 19.04, "Ладно, хватит болтать." }, { 20.73, "Ступай-ка и принеси мне побольше радужного тунца!" } } }, t = { d = 22.6, v = "gnome-male", n = { x = 243 }, c = { x = { { 0.00, "Я сразу понял, что в тебе что-то такое есть, детка." }, { 3.79, "Ты выглядишь, как человек, который знает, чего хочет." }, { 7.70, "Да-да, с Гладнем Гастрогномом есть верное правило, – сделай мне приятно, и ты об этом не пожалеешь." }, { 14.82, "Ха-ха-ха!" }, { 15.54, "Ладно, сейчас пойду сложу рыбку и вернусь." }, { 18.74, "Если хочешь, можешь пока приготовить ещё двадцать штук." } } } } },
    [8526] = { d = 29.5, g = 1, v = "gnome-female#41", n = { x = 293 }, c = { m = { { 0.00, "Как делишки, герой?" }, { 1.59, "Я вижу, ты просто рвёшься принять участие в заготовке провизии для ан'киражской войны." }, { 8.47, "Мой папочка решил, что ответственность за сбор чего-то там чему-то там меня научит." }, { 15.05, "Как бы не так." }, { 16.14, "Я мясо на дух не выношу." }, { 18.09, "Ладно, если вдруг захочешь помочь, принеси побольше жареных ящеров." }, { 23.59, "Несомненно, именно об этом мясе и будут мечтать все наши отважные солдаты." } }, f = { { 0.00, "Как делишки, героиня?" }, { 1.72, "Я вижу, ты просто рвёшься принять участие в заготовке провизии для ан'киражской войны." }, { 8.52, "Мой папочка решил, что ответственность за сбор чего-то там чему-то там меня научит." }, { 15.04, "Как бы не так." }, { 16.12, "Я мясо на дух не выношу." }, { 18.05, "Ладно, если вдруг захочешь помочь, принеси побольше жареных ящеров." }, { 23.49, "Несомненно, именно об этом мясе и будут мечтать все наши отважные солдаты." } } }, t = { d = 16.1, g = 1, v = "gnome-female#41", n = { m = 148, f = 149 }, c = { m = { { 0.00, "Вот это да." }, { 0.95, "Спасибо, что притащил сюда всю эту жженую плоть, герой." }, { 5.47, "Минуточку, сейчас я её покидаю в кучу, – надеюсь, кто-нибудь о ней да позаботится." }, { 12.03, "Если время найдётся, может быть, ещё принесёшь?" } }, f = { { 0.00, "Вот это да." }, { 0.94, "Спасибо, что притащила сюда всю эту жженую плоть, героиня." }, { 6.10, "Минуточку, сейчас я её покидаю в кучу, – надеюсь, кто-нибудь о ней да позаботится." }, { 12.61, "Если время найдётся, может быть, ещё принесёшь?" } } } } },
