    [8528] = { d = 34.2, g = 1, v = "nightelf-female#53", n = { x = 394 }, c = { m = { { 0.00, "Возможно, заготовка варёной рыбы выглядит не особенно героически, но не стоит преуменьшать значение нашей работы, герой." }, { 8.14, "Солдаты – такие же люди, как и все, и они хотят есть." }, { 11.75, "Именно поэтому мы должны обеспечить их провиантом, пока не началась война в Ан'Кираже." }, { 17.62, "Я получила приказ заготавливать пятнистый желтохвост." }, { 21.23, "Это отличный пищевой ресурс, он хорошо хранится, идёт на изготовление различных блюд и совсем не пахнет, в отличие от другой морской рыбы." }, { 30.59, "Ну что, поможешь мне в его заготовке?" } }, f = { { 0.00, "Возможно, заготовка варёной рыбы выглядит не особенно героически, но не стоит преуменьшать значение нашей работы, героиня." }, { 8.55, "Солдаты – такие же люди, как и все, и они хотят есть." }, { 12.47, "Именно поэтому мы должны обеспечить их провиантом, пока не началась война в Ан'Кираже." }, { 18.55, "Я получила приказ заготавливать пятнистый желтохвост." }, { 22.29, "Это отличный пищевой ресурс, он хорошо хранится, идёт на изготовление различных блюд и совсем не пахнет, в отличие от другой морской рыбы." }, { 31.98, "Ну что, поможешь мне в его заготовке?" } } }, t = { d = 16.2, g = 1, v = "nightelf-female#53", n = { x = 184 }, c = { m = { { 0.00, "Спасибо за быструю и своевременную помощь, герой." }, { 3.45, "Теперь наши солдаты не будут испытывать недостатка в провианте." }, { 7.91, "Подожди немного, я позабочусь о размещении рыбы на складе, и мы обсудим доставку ещё одной порции, если ты не против." } }, f = { { 0.00, "Спасибо за быструю и своевременную помощь, героиня." }, { 3.62, "Теперь наши солдаты не будут испытывать недостатка в провианте." }, { 8.13, "Подожди немного, я позабочусь о размещении рыбы на складе, и мы обсудим доставку ещё одной порции, если ты не против." } } } } },
