    [8530] = { d = 28.0, g = 1, v = "dwarf-male", n = { x = 336 }, c = { m = { { 0.00, "Герой, мне нужна твоя помощь." }, { 2.03, "Есть камни, которые можно достать в Огненных Недрах, – я имею в виду опалённые вулканические камни." }, { 8.60, "Они нужны нам для подготовки к войне в Ан'Кираже." }, { 11.89, "Наши кузнецы и инженеры знают, как их использовать, так что мы получили на них заказ." }, { 17.44, "Проберись в Огненные Недра и собери столько, сколько сможешь." }, { 21.57, "Не сомневаюсь, что тебе удастся уговорить пойти с тобой штук тридцать девять близких приятелей." } }, f = { { 0.00, "Героиня, мне нужна твоя помощь." }, { 2.29, "Есть камни, которые можно достать в Огненных Недрах, – я имею в виду опалённые вулканические камни." }, { 8.86, "Они нужны нам для подготовки к войне в Ан'Кираже." }, { 12.15, "Наши кузнецы и инженеры знают, как их использовать, так что мы получили на них заказ." }, { 17.70, "Проберись в Огненные Недра и собери столько, сколько сможешь." }, { 21.83, "Не сомневаюсь, что тебе удастся уговорить пойти с тобой штук тридцать девять близких приятелей." } } } },
    [8532] = { d = 24.6, g = 1, v = "scourge-male#83", n = { m = 234, f = 236 }, c = { m = { { 0.00, "Я так рад, что ты решил помочь нам." }, { 2.83, "Не всякий бы согласился, так что я лучше ещё раз уточню, правильно ли ты меня понял." }, { 9.68, "Мне нужны медные слитки, а не просто медь." }, { 13.18, "У нас недостаточно ни времени, ни людей, чтобы самим её выплавлять, так что твои усилия не останутся незамеченными." }, { 22.56, "Ну как, герой, справишься?" } }, f = { { 0.00, "Я так рад, что ты решила помочь нам." }, { 2.81, "Не всякий бы согласился, так что я лучше ещё раз уточню, правильно ли ты меня поняла." }, { 9.52, "Мне нужны медные слитки, а не просто медь." }, { 12.91, "У нас недостаточно ни времени, ни людей, чтобы самим её выплавлять, так что твои усилия не останутся незамеченными." }, { 22.00, "Ну как, героиня, справишься?" } } }, t = { d = 19.4, g = 1, v = "scourge-male#83", n = { m = 199, f = 200 }, c = { m = { { 0.00, "Вот они, слитки, хорошо, что ты не стал полировать их." }, { 4.06, "В блеске нет никакого смысла, они всё равно пойдут на военные нужды." }, { 9.36, "Пойду уложу их в штабели, и нужно позаботиться, чтобы они были пущены в дело." }, { 15.42, "Если добудешь ещё двадцать, обращайся прямо ко мне." } }, f = { { 0.00, "Вот они, слитки, хорошо, что ты не стала полировать их." }, { 4.21, "В блеске нет никакого смысла, они всё равно пойдут на военные нужды." }, { 9.51, "Пойду уложу их в штабели, и нужно позаботиться, чтобы они были пущены в дело." }, { 15.58, "Если добудешь ещё двадцать, обращайся прямо ко мне." } } } } },
    [8533] = { d = 20.0, g = 1, v = "scourge-male#83", n = { m = 190, f = 191 }, c = { m = { { 0.00, "Уже вернулся?" }, { 1.16, "Из тебя быстро бы получился отличный рудокоп, герой." }, { 5.46, "Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь её в слитки и возвращайся ко мне." }, { 16.08, "Я знаю, что ты кое-что можешь, вопрос – хочешь ли?" } }, f = { { 0.00, "Уже вернулась?" }, { 1.18, "Из тебя быстро бы получился отличный рудокоп, героиня." }, { 5.43, "Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь её в слитки и возвращайся ко мне." }, { 15.61, "Я знаю, что ты кое-что можешь, вопрос – хочешь ли?" } } }, t = { d = 20.3, g = 1, v = "scourge-male#83", n = { m = 203, f = 204 }, c = { m = { { 0.00, "Ты опять доказал, что ты многого стоишь, герой." }, { 3.74, "Я чувствую, эта медь хорошо нам послужит, когда придёт время." }, { 8.54, "А теперь мне надо сложить её в штабеля и подсчитать." }, { 12.64, "Если у тебя не пропало желание, ты, вероятно, сможешь помочь нам, если принесёшь ещё медных слитков." } }, f = { { 0.00, "Ты опять доказала, что ты многого стоишь, героиня." }, { 3.84, "Я чувствую, эта медь хорошо нам послужит, когда придёт время." }, { 8.49, "А теперь мне надо сложить её в штабеля и подсчитать." }, { 12.47, "Если у тебя не пропало желание, ты, вероятно, сможешь помочь нам, если принесёшь ещё медных слитков." } } } } },
    [8534] = { d = 16.7, v = "narrator", n = { x = 190 }, c = { x = { { 0.00, "Мы отправили наших лучших разведчиков к ульям силитидов." }, { 4.27, "Азенель уже несколько дней наблюдает за передвижениями этих насекомых." }, { 9.55, "Найди её и забери у неё письменный отчёт." }, { 12.60, "Нам необходимо как можно скорее получить от неё сведения." } } }, t = { d = 9.0, v = "tauren-female#71", n = { x = 91 }, c = { x = { { 0.00, "Мы очень ценим твои усилия." }, { 2.39, "Я немедленно займусь этим донесением, а ты можешь переходить к следующему заданию." } } } } },
    [8535] = { d = 26.5, v = "narrator", n = { x = 299 }, c = { x = { { 0.00, "Сумеречный Молот и повелители стихий, которым поклоняются культисты, представляют серьёзную опасность для деятельности Круга в Силитусе." }, { 10.10, "Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам." }, { 19.04, "Отыщи способ вызвать и уничтожить седого храмовника и доложи о выполнении задания Бору Буйногривому." } } }, t = { d = 4.4, v = "tauren-male", n = { x = 33 }, c = { x = { { 0.00, "Отличная работа." }, { 1.98, "Вот следующее задание." } } } } },
