    [8537] = { d = 27.0, v = "narrator", n = { x = 302 }, c = { x = { { 0.00, "Сумеречный Молот и повелители стихий, которым поклоняются культисты, представляют серьёзную опасность для деятельности Круга в Силитусе." }, { 10.23, "Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам." }, { 19.29, "Отыщи способ вызвать и уничтожить багрового храмовника и доложи о выполнении задания Бору Буйногривому." } } }, t = { d = 4.2, v = "tauren-male", n = { x = 33 }, c = { x = { { 0.00, "Отличная работа." }, { 1.91, "Вот следующее задание." } } } } },
    [8538] = { d = 26.6, v = "narrator", n = { x = 288 }, c = { x = { { 0.00, "Связь между Сумеречным Молотом и Советом Бездны оказалась куда важнее, чем нам казалось вначале." }, { 7.54, "Мы не сомневаемся, что повелители Стихий, именуемые герцогами Бездны, управляют культистами Сумеречного Молота." }, { 16.14, "Найди способ выманить в наш мир четырёх герцогов Бездны и убей их!" }, { 21.29, "Мы избрали тебя за прежние заслуги и не сомневаемся, что ты справишься." } } }, t = { d = 8.6, g = 1, v = "nightelf-male#54", n = { m = 77, f = 78 }, c = { m = { { 0.00, "Сегодня ты сделал великое дело." }, { 2.85, "Тебе удалось избавить нас от злейших врагов." }, { 6.82, "Хвала тебе за это!" } }, f = { { 0.00, "Сегодня ты сделала великое дело." }, { 2.99, "Тебе удалось избавить нас от злейших врагов." }, { 7.02, "Хвала тебе за это!" } } } } },
    [8539] = { d = 11.8, v = "narrator", n = { x = 122 }, c = { x = { { 0.00, "Мы вызвали подкрепление для сражения у Улья Зора." }, { 3.97, "Твоя задача – убить как можно больше сестёр-убийц." }, { 8.09, "Выполнив задание, отчитайся командиру Мар'алиту." } } }, t = { d = 4.5, v = "nightelf-male#54", n = { x = 34 }, c = { x = { { 0.00, "Отличная работа." }, { 1.88, "Ты очень ценный союзник." } } } } },
    [8540] = { d = 12.5, v = "narrator", n = { x = 141 }, c = { x = { { 0.00, "Верховому подразделению крепости Кенария не хватает изысканных мифриловых сапог." }, { 6.18, "Принеси нам очередную партию и передай их капитану Вишу Коцусу из крепости Кенария." } } }, t = { d = 3.9, v = "nightelf-male#54", n = { x = 30 }, c = { x = { { 0.00, "Отлично!" }, { 0.93, "Как раз то, что нужно." }, { 3.16, "Спасибо." } } } } },
    [8541] = { d = 9.3, v = "narrator", n = { x = 96 }, c = { x = { { 0.00, "У стражи крепости Кенария на исходе шлифовальные камни." }, { 4.53, "Добудь их и отнеси капитану Вишу Коцусу в крепость Кенария." } } }, t = { d = 4.6, v = "nightelf-male#54", n = { x = 39 }, c = { x = { { 0.00, "Отлично!" }, { 0.86, "Нам очень нужны эти материалы." }, { 3.87, "Спасибо." } } } } },
    [8542] = { d = 32.6, g = 1, v = "orc-male", n = { x = 328 }, c = { m = { { 0.00, "Лок'тар, герой, я уверен, ты в курсе, что мы собираемся воевать с киражскими тараканами." }, { 6.63, "Вождь сказал, что сначала надо как следует подготовиться." }, { 10.93, "Я б охотней точил мечи или подгонял броню, но мне доверили сбор оловянных слитков." }, { 17.22, "Для меня это большая честь, да!" }, { 19.61, "Но без помощи мне не справиться." }, { 22.00, "Надо, чтобы кто-то добывал эти самые слитки и приносил сюда." }, { 26.78, "Нам нужно так много, что, боюсь, я и считать-то до стольких не умею." } }, f = { { 0.00, "Лок'тар, героиня, я уверен, ты в курсе, что мы собираемся воевать с киражскими тараканами." }, { 6.92, "Вождь сказал, что сначала надо как следует подготовиться." }, { 11.33, "Я б охотней точил мечи или подгонял броню, но мне доверили сбор оловянных слитков." }, { 17.76, "Для меня это большая честь, да!" }, { 20.21, "Но без помощи мне не справиться." }, { 22.65, "Надо, чтобы кто-то добывал эти самые слитки и приносил сюда." }, { 27.55, "Нам нужно так много, что, боюсь, я и считать-то до стольких не умею." } } }, t = { d = 17.3, g = 1, v = "orc-male", n = { x = 168 }, c = { m = { { 0.00, "Хм..." }, { 0.43, "Выглядит так, будто слитков столько, сколько нужно..." }, { 4.70, "Только не пытайся обмануть меня, герой!" }, { 7.90, "От этого счета у меня башка раскалывается." }, { 11.31, "Пойду сложу слитки в штабель, а ты пока отправляйся и принеси ещё столько же." } }, f = { { 0.00, "Хм..." }, { 0.42, "Выглядит так, будто слитков столько, сколько нужно..." }, { 4.57, "Только не пытайся обмануть меня, героиня!" }, { 7.82, "От этого счёта у меня башка раскалывается." }, { 11.08, "Пойду сложу слитки в штабель, а ты пока отправляйся и принеси ещё столько же." } } } } },
    [8543] = { d = 28.1, v = "orc-male", n = { x = 278 }, c = { x = { { 0.00, "Отлично, я понял, к войне ты относишься серьёзно." }, { 3.92, "Видишь ли, в её предвкушении я так нервничаю, что потихоньку начинаю выходить из себя." }, { 10.74, "А твоя медлительность меня просто бесит!!!" }, { 14.23, "Не можешь притаскивать товар быстрее, что ли?" }, { 17.85, "Может, мне малость с тобой поразмяться, чтобы снять стресс..." }, { 22.72, "Хар!!!" }, { 23.22, "Нет, не буду, пожалуй, а то кто тогда будет носить мне слитки?" } } }, t = { d = 22.0, v = "orc-male", n = { x = 208 }, c = { x = { { 0.00, "Тром'ка!" }, { 0.77, "Своими делами ты оказываешь и мне, и Орде большую честь." }, { 5.54, "Сейчас я позабочусь об этих слитках." }, { 8.69, "А когда мы сделаем всё, что нужно, то отправимся на войну и покажем этому ничтожному Альянсу, как надо давить тараканов!" }, { 19.00, "Так что ступай и принеси ещё слитков!" } } } } },
    [8544] = { d = 19.8, v = "gnome-female", n = { x = 220 }, c = { x = { { 0.00, "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов." }, { 9.61, "Принеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье ещё более устрашающее, чем крылья самого Нефариана!" } } }, t = { d = 13.0, g = 1, v = "gnome-female", n = { m = 127, f = 127 }, c = { m = { { 0.00, "Я изготовила это наплечье, смертный, из принесённых тобой вещей и панцирей поверженных киражей." }, { 8.06, "Тебя оно защитит, а сердца врагов его вид наполнит ужасом." } }, f = { { 0.00, "Я изготовила это наплечье, смертная, из принесённых тобой вещей и панцирей поверженных киражей." }, { 8.06, "Тебя оно защитит, а сердца врагов его вид наполнит ужасом." } } } } },
    [8545] = { d = 28.8, g = 1, v = "troll-female#73", n = { x = 326 }, c = { m = { { 0.00, "Война надвигается неотвратимо, и всё, что нам остаётся, герой, – это как следует подготовиться к ней." }, { 6.91, "В такие времена мы должны сплотиться и помогать друг другу." }, { 11.09, "Как видишь, меня поставили ответственной за сбор мифриловых слитков, которые потом пойдут на нужды армии." }, { 19.02, "Я стараюсь как могу, но этого пока недостаточно." }, { 22.44, "Сумеешь добыть мифрил на рудниках и переплавить его в слитки?" }, { 26.81, "Это бы нам очень пригодилось." } }, f = { { 0.00, "Война надвигается неотвратимо, и всё, что нам остаётся, героиня, – это как следует подготовиться к ней." }, { 6.72, "В такие времена мы должны сплотиться и помогать друг другу." }, { 10.72, "Как видишь, меня поставили ответственной за сбор мифриловых слитков, которые потом пойдут на нужды армии." }, { 18.46, "Я стараюсь как могу, но этого пока недостаточно." }, { 21.73, "Сумеешь добыть мифрил на рудниках и переплавить его в слитки?" }, { 25.91, "Это бы нам очень пригодилось." } } }, t = { d = 18.2, g = 1, v = "troll-female#73", n = { x = 196 }, c = { m = { { 0.00, "Ну вот, очень неплохой зачин в нашей работе, герой." }, { 3.77, "Теперь на складе лежит ещё двадцать новеньких слиточков, сейчас я внесу их в список." }, { 9.88, "Когда на пороге война, на счету каждая крупинка мифрила!" }, { 14.04, "Ты заглядывай, похоже, нам скоро ещё понадобятся слитки." } }, f = { { 0.00, "Ну вот, очень неплохой зачин в нашей работе, героиня." }, { 3.92, "Теперь на складе лежит ещё двадцать новеньких слиточков, сейчас я внесу их в список." }, { 10.07, "Когда на пороге война, на счету каждая крупинка мифрила!" }, { 14.25, "Ты заглядывай, похоже, нам скоро ещё понадобятся слитки." } } } } },
    [8546] = { t = { d = 12.6, v = "troll-female#73", n = { x = 130 }, c = { x = { { 0.00, "Отлично сработано!" }, { 1.49, "Мы ближе к цели на целых двадцать слитков." }, { 4.90, "Сейчас я прослежу, чтобы их отгрузили." }, { 7.96, "Если раздобудешь ещё двадцать, дружище, сразу же тащи их мне." } } } } },
    [8548] = { d = 25.2, v = "tauren-male", n = { x = 254 }, c = { x = { { 0.00, "Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты." }, { 10.80, "Не теряй их." }, { 11.83, "Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки." } } }, t = { d = 8.6, g = 1, v = "tauren-male", n = { m = 68, f = 69 }, c = { m = { { 0.00, "Отличная работа." }, { 1.73, "Прими это от имени Кенарийского Круга." }, { 5.74, "Ты это точно заслужил, друг!" } }, f = { { 0.00, "Отличная работа." }, { 1.74, "Прими это от имени Кенарийского Круга." }, { 5.78, "Ты это точно заслужила, друг!" } } } } },
    [8549] = { d = 33.0, g = 1, v = "tauren-female#71", n = { m = 343, f = 343 }, c = { m = { { 0.00, "Говорят, каждое поколение должно пройти испытание огнём." }, { 4.58, "Боюсь, что ан'киражская война станет для нас тем самым горном для закалки." }, { 10.53, "Ничего, подготовимся как следует и покажем всем, из какого мы слеплены теста." }, { 16.71, "Нам нужен мироцвет, который пойдёт на создание лекарственных снадобий, и я вызвалась быть ответственной за его сбор." }, { 25.86, "Надеюсь, ты пришёл предложить мне свою помощь." }, { 29.56, "Собери побольше мироцвета и принеси его мне." } }, f = { { 0.00, "Говорят, каждое поколение должно пройти испытание огнём." }, { 4.51, "Боюсь, что ан'киражская война станет для нас тем самым горном для закалки." }, { 10.38, "Ничего, подготовимся как следует и покажем всем, из какого мы слеплены теста." }, { 16.47, "Нам нужен мироцвет, который пойдёт на создание лекарственных снадобий, и я вызвалась быть ответственной за его сбор." }, { 25.49, "Надеюсь, ты пришла предложить мне свою помощь." }, { 29.21, "Собери побольше мироцвета и принеси его мне." } } }, t = { d = 21.6, v = "tauren-female#71", n = { x = 207 }, c = { x = { { 0.00, "Подготовка близится к концу, и скоро грянет война." }, { 4.37, "Спасибо за помощь." }, { 5.98, "Мироцвет очень нужен нам, и твой вклад в общее дело не останется незамеченным." }, { 12.56, "Если сможешь, возвращайся и помоги мне собрать ещё мироцвета." }, { 17.77, "А пока ступай, и пусть Мать-Земля хранит тебя." } } } } },
    [8550] = { t = { d = 18.6, v = "tauren-female#71", n = { x = 197 }, c = { x = { { 0.00, "Спасибо, что продолжаешь помогать нам." }, { 2.90, "Твоя самоотдача делает честь тебе и твоим предкам." }, { 6.83, "Пойду упакую травы, чтобы они не потеряли своей свежести к тому времени, когда они понадобятся." }, { 14.36, "Продолжай трудиться на благо нашей победы, во имя Орды!" } } } } },
    [8551] = { d = 34.8, v = "human-male", n = { x = 397 }, c = { x = { { 0.00, "Когда-то у меня был корабль, на котором я плавал до самого Кабестана в Калимдоре, и репутация у меня была безупречная." }, { 8.38, "Пока…" }, { 8.83, "Пока не появились проклятые морские великаны!" }, { 12.10, "Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую бухту." }, { 18.75, "А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая." }, { 25.60, "Наглец!" }, { 26.18, "Говорят, Горлаш бродит по берегу к востоку отсюда." }, { 29.82, "Найди его и верни мой сундук!" }, { 32.00, "Благодарность моя не будет знать предела." } } }, t = { d = 12.5, g = 1, v = "human-male", n = { m = 97, f = 97 }, c = { m = { { 0.00, "О, ты нашёл его!" }, { 1.56, "О, радость, о счастье!" }, { 3.72, "Спасибо." }, { 4.59, "Сундук снова у меня, и огонь в душе немного утих." }, { 9.53, "Но месть моя ещё не свершилась..." } }, f = { { 0.00, "О, ты нашла его!" }, { 1.59, "О, радость, о счастье!" }, { 3.69, "Спасибо." }, { 4.53, "Сундук снова у меня, и огонь в душе немного утих." }, { 9.31, "Но месть моя ещё не свершилась..." } } } } },
    [8552] = { d = 3.9, v = "narrator", n = { x = 36 }, c = { x = { { 0.00, "Вдоль каймы кушака вышита монограмма \"Гэ Ша\"." } } }, t = { d = 20.2, g = 1, v = "human-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Тебе удалось вернуть мой кушак?" }, { 2.53, "Тогда... ты, должно быть, убил морского великана!" }, { 6.39, "Урааа!" }, { 6.95, "Как я рад, что этот негодяй мёртв – Мок'раш был одним из трёх великанов, которые уничтожили мои корабли и поубивали всю команду." }, { 16.77, "И так три раза подряд!" }, { 18.53, "Ты достойный герой." } }, f = { { 0.00, "Тебе удалось вернуть мой кушак?" }, { 2.54, "Тогда... ты, должно быть, убила морского великана!" }, { 6.49, "Урааа!" }, { 7.06, "Как я рад, что этот негодяй мёртв – Мок'раш был одним из трёх великанов, которые уничтожили мои корабли и поубивали всю команду." }, { 16.93, "И так три раза подряд!" }, { 18.70, "Ты достойная героиня." } } } } },
    [8553] = { d = 37.8, v = "human-male", n = { x = 427 }, c = { x = { { 0.00, "После того как эти проклятые великаны уничтожили мой корабль, я купил ещё один." }, { 5.64, "Назвал его \"Месть Шмотта\", запасся продовольствием, нанял команду и отправился в поисках этих злодеев." }, { 12.87, "Найти-то я их нашёл, но... они снова надавали мне по шее." }, { 16.86, "\"Месть Шмотта\" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку." }, { 23.33, "У другого великана, Неголаша, моя сабля." }, { 26.24, "Сразись с Неголашем и принеси мне мою саблю!" }, { 29.41, "Можешь поговорить с Салагой, поваром с \"Мести Шмотта\", который выжил в последней битве." }, { 35.62, "Он поможет тебе найти великана." } } }, t = { d = 4.3, v = "goblin-male", n = { x = 49 }, c = { x = { { 0.00, "Привет-привет." }, { 1.12, "Капитан говорит, что ты пойдёшь на Неголаша, а?" } } } } },
    [8554] = { d = 35.1, v = "goblin-male", n = { x = 381 }, c = { x = { { 0.00, "Неголаш – великан-обжора." }, { 1.94, "Когда они уничтожили мой корабль, Неголаш бросился прямиком на кухню." }, { 7.15, "В отличие от его товарищей, команда его не очень интересовала." }, { 11.82, "Ему хотелось вина... и жареных крылышек канюка." }, { 15.43, "Это моё коронное блюдо, рецепт я привёз из самих Бесплодных земель!" }, { 20.44, "Если ты хочешь приманить великана, добудь вина и кучу крылышек канюка." }, { 25.78, "Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда." }, { 31.19, "Когда Неголаш почует запах еды, он непременно явится!" } } }, t = { d = 17.5, g = 1, v = "human-male", n = { m = 190, f = 192 }, c = { m = { { 0.00, "Ты отобрал у Неголаша мою саблю!" }, { 2.44, "Глазам своим не верю!" }, { 4.09, "Я чувствую, с момента нашей встречи ветер удачи переменился, теперь он попутный!" }, { 10.02, "Спасибо!" }, { 10.68, "Если я всё же куплю себе новый корабль, а ты пожелаешь поплыть в море, приходи, гостем будешь." } }, f = { { 0.00, "Ты отобрала у Неголаша мою саблю!" }, { 2.49, "Глазам своим не верю!" }, { 4.12, "Я чувствую, с момента нашей встречи ветер удачи переменился, теперь он попутный!" }, { 10.01, "Спасибо!" }, { 10.66, "Если я всё же куплю себе новый корабль, а ты пожелаешь поплыть в море, приходи, гостьей будешь." } } } } },
    [8555] = { t = { d = 36.0, g = 1, v = "creature/anachronos", n = { m = 348, f = 348 }, c = { m = { { 0.00, "Эраникус, Веластрас и Азурегос..." }, { 2.60, "Без сомнения, ты знаешь этих драконов, смертный." }, { 6.41, "Не случайно они сыграли столь важную роль как стражи нашего мира." }, { 11.54, "К несчастью (и отчасти в этом виновата моя собственная наивность), то ли из-за происков Древних богов, то ли из-за предательства тех, кого они называли друзьями, каждого из стражей постигла трагедия." }, { 27.10, "Именно она и породила моё недоверие к вашему роду." }, { 31.11, "Отыщи их..." }, { 32.03, "И, путник, приготовься к худшему." } }, f = { { 0.00, "Эраникус, Веластрас и Азурегос..." }, { 2.71, "Без сомнения, ты знаешь этих драконов, смертная." }, { 6.66, "Не случайно они сыграли столь важную роль как стражи нашего мира." }, { 12.00, "К несчастью (и отчасти в этом виновата моя собственная наивность), то ли из-за происков Древних богов, то ли из-за предательства тех, кого они называли друзьями, каждого из стражей постигла трагедия." }, { 28.17, "Именно она и породила моё недоверие к вашему роду." }, { 32.34, "Отыщи их..." }, { 33.29, "И, путница, приготовься к худшему." } } } } },
    [8556] = { d = 31.1, g = 1, v = "nightelf-female#51", n = { x = 343 }, c = { m = { { 0.00, "Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности." }, { 6.79, "Однако считается, что если заменить поражённые скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастёт ещё больше." }, { 17.55, "Камни, украшающие киражских идолов, вполне подойдут – они отменного качества." }, { 23.40, "Принеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественное кольцо, герой." } }, f = { { 0.00, "Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности." }, { 6.69, "Однако считается, что если заменить поражённые скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастёт ещё больше." }, { 17.30, "Камни, украшающие киражских идолов, вполне подойдут – они отменного качества." }, { 23.06, "Принеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественное кольцо, героиня." } } } },
    [8557] = { d = 21.3, v = "nightelf-male#55", n = { x = 246 }, c = { x = { { 0.00, "Я рад слышать, что ты помогаешь нам в нападении на Ан'Кираж." }, { 4.18, "В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов." }, { 10.36, "Мне понадобится киражская накидка – я смогу подогнать её под твой размер." }, { 15.51, "Для застёжек мне понадобятся идолы и скарабеи." }, { 18.72, "Увидишь, эта вещь тебя не разочарует." } } } },
    [8558] = { d = 37.6, v = "tauren-male", n = { x = 379 }, c = { x = { { 0.00, "Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов..." }, { 16.77, "При одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них своё собственное искусство." }, { 27.96, "Докажи Кругу Кенария свою преданность, и я создам для тебя могучее оружие из лучших киражских материалов." } } } },
    [8559] = { d = 23.9, v = "human-male", n = { x = 277 }, c = { x = { { 0.00, "Древняя киражская магия исполнена небывалой силы." }, { 3.69, "Самые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона." }, { 11.54, "Принеси мне киражские наручники Повелевания и ещё несколько компонентов, и я создам для тебя потрясающие сапоги." }, { 19.65, "Увидишь, насколько они окажутся полезны в схватке с врагом." } } } },
    [8560] = { d = 41.8, g = 1, v = "human-male", n = { m = 465, f = 465 }, c = { m = { { 0.00, "Хочешь доказать нам, что тебе можно доверять, смертный?" }, { 4.12, "Ну хорошо." }, { 4.92, "Возможно, и тебе удастся извлечь из этого пользу." }, { 8.64, "Слушай." }, { 9.23, "Есть существо, обладающее легендарной силой." }, { 12.49, "Это древний песчаный червь Оуро." }, { 14.95, "Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни." }, { 21.13, "Шкура у этого червя просто невероятная." }, { 24.12, "Она такая толстая, что её невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом." }, { 34.61, "Принеси мне шкуру Оуро и ещё ряд компонентов, и я создам для тебя поножи, обладающие огромной силой." } }, f = { { 0.00, "Хочешь доказать нам, что тебе можно доверять, смертная?" }, { 4.09, "Ну хорошо." }, { 4.88, "Возможно, и тебе удастся извлечь из этого пользу." }, { 8.57, "Слушай." }, { 9.16, "Есть существо, обладающее легендарной силой." }, { 12.39, "Это древний песчаный червь Оуро." }, { 14.83, "Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни." }, { 20.96, "Шкура у этого червя просто невероятная." }, { 23.93, "Она такая толстая, что её невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом." }, { 34.35, "Принеси мне шкуру Оуро и ещё ряд компонентов, и я создам для тебя поножи, обладающие огромной силой." } } } },
    [8561] = { d = 33.6, v = "gnome-female", n = { x = 329 }, c = { x = { { 0.00, "Императоры-близнецы..." }, { 1.83, "Их непрестанный шёпот в моих ушах потихоньку сводит меня с ума." }, { 7.04, "Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса." }, { 15.41, "Я вижу их безобразные головы, увенчанные могущественными коронами." }, { 20.77, "Но я отомщу им... эти символы власти Ан'Кираж будут служить нам." }, { 26.05, "Принеси то, что мне нужно." }, { 28.18, "Взамен я отдам тебе головной убор, не имеющий себе равных по силе." } } } },
    [8562] = { d = 42.5, v = "nightelf-female", n = { x = 489 }, c = { x = { { 0.00, "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже." }, { 6.73, "Ужасная судьба, которая ждёт Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет." }, { 14.74, "Для существа, обладающего подобной мощью, время не имеет значения." }, { 19.44, "Встанут звёзды подходящим образом – и ярость его обрушится на живущих, подобно плети." }, { 25.47, "Тебе следует найти его и положить конец его существованию, пока он не пробудился." }, { 31.32, "Когда ты сделаешь это, принеси мне кусок его панциря." }, { 35.19, "Взамен я дам тебе броню, подобной которой не владел ещё никто из смертных." }, { 40.46, "Броню, достойную убийцы бога." } } } },
    [8572] = { d = 25.4, v = "tauren-male", n = { x = 254 }, c = { x = { { 0.00, "Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты." }, { 10.87, "Не теряй их." }, { 11.91, "Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки." } } }, t = { d = 9.1, g = 1, v = "tauren-male", n = { m = 68, f = 69 }, c = { m = { { 0.00, "Отличная работа." }, { 1.73, "Прими это от имени Кенарийского Круга." }, { 5.74, "Ты это точно заслужил, друг!" } }, f = { { 0.00, "Отличная работа." }, { 1.84, "Прими это от имени Кенарийского Круга." }, { 6.10, "Ты это точно заслужила, друг!" } } } } },
    [8573] = { d = 25.3, v = "tauren-male", n = { x = 254 }, c = { x = { { 0.00, "Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в крепости Кенария, нужны не для красоты." }, { 10.84, "Не теряй их." }, { 11.87, "Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки." } } }, t = { d = 9.1, g = 1, v = "tauren-male", n = { m = 71, f = 72 }, c = { m = { { 0.00, "Отличная работа." }, { 1.75, "Прошу тебя, прими это от лица Круга Кенария." }, { 6.53, "Ты заслужил такую награду!" } }, f = { { 0.00, "Отличная работа." }, { 1.72, "Прошу тебя, прими это от лица Круга Кенария." }, { 6.41, "Ты заслужила такую награду!" } } } } },
    [8574] = { d = 26.5, v = "tauren-male", n = { x = 268 }, c = { x = { { 0.00, "Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий призывательницы ветров Гордый Рог, нужны не для красоты." }, { 12.03, "Не теряй их." }, { 13.06, "Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки." } } }, t = { d = 8.9, g = 1, v = "tauren-male", n = { m = 68, f = 69 }, c = { m = { { 0.00, "Отличная работа." }, { 1.78, "Прими это от имени Кенарийского Круга." }, { 5.90, "Ты это точно заслужил, друг!" } }, f = { { 0.00, "Отличная работа." }, { 1.79, "Прими это от имени Кенарийского Круга." }, { 5.94, "Ты это точно заслужила, друг!" } } } } },
    [8575] = { d = 7.8, v = "narrator", n = { x = 79 }, c = { x = { { 0.00, "Из надписи на книге вы ни слова не понимаете." }, { 3.53, "Вы даже не знаете, на каком языке сделана эта надпись!" } } }, t = { d = 8.6, g = 1, v = "gnome-male", n = { x = 67 }, c = { m = { { 0.00, "*Нарайн жадно рассматривает письмена.*" }, { 3.12, "Невероятно, герой!" }, { 4.97, "Что это?" }, { 5.86, "Я по-драконьи ни бум-бум." } }, f = { { 0.00, "*Нарайн жадно рассматривает письмена.*" }, { 3.04, "Невероятно, героиня!" }, { 5.22, "Что это?" }, { 6.16, "Я по-драконьи ни бум-бум." } } } } },
    [8576] = { t = { d = 26.6, v = "gnome-male", n = { x = 320 }, c = { x = { { 0.00, "Первым делом!" }, { 0.98, "Нужно выяснить, что Азурегос написал в этой книге." }, { 4.47, "Говоришь, он велел тебе сделать арканитовый буёк и что это его чертёж?" }, { 9.25, "Странно, что он написал это на драконьем." }, { 12.06, "Старый козёл знает, что я не могу читать эту тарабарщину." }, { 15.98, "Чтобы всё получилось, мне понадобятся мои очки прорицания, пятисотфунтовая курица и второй том «Драконьего языка для чайников»." }, { 24.56, "Не обязательно в таком порядке." } } } } },
    [8577] = { d = 30.0, v = "gnome-male", n = { x = 345 }, c = { x = { { 0.00, "Если я хочу хоть что-то перевести, мне нужны мои гадальные очки." }, { 4.62, "Увы, их давным-давно спёр мой бывший лучший друг Тушёный Лис." }, { 8.87, "Он разбил моё сердце на пять частей и оставил меня в горести." }, { 13.17, "При помощи моего верного хрустального шара я выяснил, где он находится – либо у Стены Седогрива в Серебролесье или в каком-то мире за порталом Запределья, нынче разорённом Пылающим Легионом." }, { 26.47, "Вы должны найти его след и отнять у него мои очки!" } } }, t = { d = 15.4, g = 1, v = "gnome-male", n = { x = 179 }, c = { m = { { 0.00, "Поверить не могу, что он меня нашёл." }, { 2.37, "Я был полностью уверен, что потерял его, когда был в Запределье." }, { 6.57, "Я туда не вернусь, герой!" }, { 8.28, "Ни за какие коврижки!" }, { 9.70, "С меня хватит: больше не буду ему лучшим другом на полставки и рабом на полную ставку!" } }, f = { { 0.00, "Поверить не могу, что он меня нашёл." }, { 2.32, "Я был полностью уверен, что потерял его, когда был в Запределье." }, { 6.45, "Я туда не вернусь, героиня!" }, { 8.25, "Ни за какие коврижки!" }, { 9.64, "С меня хватит: больше не буду ему лучшим другом на полставки и рабом на полную ставку!" } } } } },
    [8578] = { d = 30.7, v = "gnome-male", n = { x = 288 }, c = { x = { { 0.00, "*Из ящика доносится вздох облегчения.*" }, { 3.68, "Так вам нужны только его очки?" }, { 6.21, "Отлично!" }, { 6.93, "Никаких проблем..." }, { 8.45, "Подождите минуточку, и..." }, { 10.48, "Эй!" }, { 10.77, "Где..." }, { 11.27, "Тьфу ты, пропасть!" }, { 12.72, "В общем, есть новость плохая и ещё хуже." }, { 15.97, "Плохая – я потерял очки." }, { 18.00, "Ещё хуже – я потерял их, когда в прошлом месяце разнюхивал обстановку в Огненных Недрах." }, { 25.09, "Да, в Огненных Недрах..." }, { 27.04, "Думаю, что на этом наш разговор закончен!" }, { 30.37, "Пока!" } } }, t = { d = 10.7, v = "gnome-male", n = { x = 112 }, c = { x = { { 0.00, "Прекрасно!" }, { 0.84, "Теперь где взять пятисотфунтовую курочку и второй том \"Драконьего языка для чайников???\" О, а вот вам кое-что за ваши тяжкие труды!" } } } } },
    [8579] = { t = { d = 34.9, g = 1, v = "human-male", n = { m = 401, f = 401 }, c = { m = { { 0.00, "Я вижу, ты не обычный смертный." }, { 2.23, "Твои шансы победить Древнего Бога исчезающе малы, но они всё равно больше, чем наши." }, { 8.34, "В конце концов, если он ожидает у своих дверей драконов, то вряд ли готовится встретить кого-нибудь вроде тебя." }, { 16.24, "Тысячу лет назад Анахронос и Олений Шлем создали союз смертных и драконов, и смогли победить киражей." }, { 23.43, "Можем заключить договор и мы." }, { 25.54, "Если ты завоюешь доверие крыла Бронзовых драконов, мы тоже будем тебе доверять, и ты сможешь стать настоящим защитником правого дела." } }, f = { { 0.00, "Я вижу, ты не обычная смертная." }, { 2.22, "Твои шансы победить Древнего Бога исчезающе малы, но они всё равно больше, чем наши." }, { 8.30, "В конце концов, если он ожидает у своих дверей драконов, то вряд ли готовится встретить кого-нибудь вроде тебя." }, { 16.16, "Тысячу лет назад Анахронос и Олений Шлем создали союз смертных и драконов, и смогли победить киражей." }, { 23.33, "Можем заключить договор и мы." }, { 25.42, "Если ты завоюешь доверие крыла Бронзовых драконов, мы тоже будем тебе доверять, и ты сможешь стать настоящей защитницей правого дела." } } } } },
    [8580] = { d = 31.1, g = 1, v = "troll-male", n = { x = 326 }, c = { m = { { 0.00, "Даров, герой." }, { 1.10, "Как делишки, дружище?" }, { 2.75, "Орде тут для войны в Ан'Кираже понадобилась прорва этого несчастного огнецвета." }, { 8.81, "Даж интересно, они собираются запихнуть его во всякие взрывающиеся штуки или отдать Альянсу на топливо для танков?" }, { 17.62, "Спроси что-нибудь полегче, тут Пелекейки не в курсе, ага." }, { 22.02, "Но кое-что Пелекейки знает... например, что ты сейчас пойдёшь и принесёшь ему этого несчастного огнецвета, ага, дружище?" } }, f = { { 0.00, "Даров, героиня." }, { 1.24, "Как делишки, дружище?" }, { 2.89, "Орде тут для войны в Ан'Кираже понадобилась прорва этого несчастного огнецвета." }, { 8.95, "Даж интересно, они собираются запихнуть его во всякие взрывающиеся штуки или отдать Альянсу на топливо для танков?" }, { 17.77, "Спроси что-нибудь полегче, тут Пелекейки не в курсе, ага." }, { 22.18, "Но кое-что Пелекейки знает... например, что ты сейчас пойдёшь и принесёшь ему этого несчастного огнецвета, ага, дружище?" } } }, t = { d = 22.7, v = "troll-male", n = { x = 236 }, c = { x = { { 0.00, "Воин!" }, { 0.50, "Пелекейки просто счастлив." }, { 2.64, "Сейчас он заберёт эти цветочки и сложит их в коробку, чтоб не попортились." }, { 8.43, "Уж Пелекейки присмотрит, чтоб их употребили на всякие военные штуки, а не на какую-нибудь дребедень." }, { 16.22, "А если добудешь ещё цветочков, сразу же тащи Пелекейки, ему это всяко понадобится." } } } } },
    [8581] = { t = { d = 22.8, g = 1, v = "troll-male", n = { m = 219, f = 221 }, c = { m = { { 0.00, "Ты случайно не шутишь, герой?" }, { 2.42, "Ты принёс Пелекейки огнецвет так быстро?" }, { 5.66, "Сейчас-ка, дружище, Пелекейки его посчитает." }, { 9.33, "Пелекейки так счастлив, он думает, что ты лучший собиратель огнецвета, ага." }, { 15.43, "Скорей бы началась война с Ан'Киражем, уж мы бы позажигали в Силитусе, так ведь, братище?" } }, f = { { 0.00, "Ты случайно не шутишь, героиня?" }, { 2.57, "Ты принесла Пелекейки огнецвет так быстро?" }, { 6.03, "Сейчас-ка, дружище, Пелекейки его посчитает." }, { 9.71, "Пелекейки так счастлив, он думает, что ты лучший собиратель огнецвета, ага." }, { 15.82, "Скорей бы началась война с Ан'Киражем, уж мы бы позажигали в Силитусе, так ведь, братище?" } } } } },
    [8582] = { d = 37.7, g = 1, v = "scourge-female#79", n = { x = 396 }, c = { m = { { 0.00, "Лиловый лотос, герой, является основной составляющей множества зелий, эликсиров и масел, которые необходимы для войны в Ан'Кираже." }, { 10.33, "Мы создадим бесчисленное количество самых разных снадобий." }, { 14.96, "Я думаю, придётся даже поэкспериментировать, чтобы исследовать все возможные способы его применения." }, { 22.80, "Но для экспериментов необходимо иметь достаточно цветов в запасе." }, { 27.93, "А вот это уже работа для тебя." }, { 30.42, "Ступай и собери как можно больше цветков лилового лотоса." }, { 35.05, "Возьмёшься ради нас за это задание?" } }, f = { { 0.00, "Лиловый лотос, героиня, является основной составляющей множества зелий, эликсиров и масел, которые необходимы для войны в Ан'Кираже." }, { 10.32, "Мы создадим бесчисленное количество самых разных снадобий." }, { 14.89, "Я думаю, придётся даже поэкспериментировать, чтобы исследовать все возможные способы его применения." }, { 22.61, "Но для экспериментов необходимо иметь достаточно цветов в запасе." }, { 27.67, "А вот это уже работа для тебя." }, { 30.13, "Ступай и собери как можно больше цветков лилового лотоса." }, { 34.69, "Возьмёшься ради нас за это задание?" } } }, t = { d = 21.3, g = 1, v = "scourge-female#79", n = { m = 218, f = 220 }, c = { m = { { 0.00, "Твоя работа заслуживает одобрения, герой." }, { 3.18, "Я должна рассортировать образцы и не забыть отметить, что это был твой вклад." }, { 8.88, "Пока у меня не дойдут руки до этих цветов, нужно их правильно хранить." }, { 14.30, "Как ты мог отметить, лотоса нужно гораздо больше, чем мы сейчас имеем." }, { 19.58, "Далеко не уходи." } }, f = { { 0.00, "Твоя работа заслуживает одобрения, героиня." }, { 3.35, "Я должна рассортировать образцы и не забыть отметить, что это был твой вклад." }, { 9.11, "Пока у меня не дойдут руки до этих цветов, нужно их правильно хранить." }, { 14.58, "Как ты могла отметить, лотоса нужно гораздо больше, чем мы сейчас имеем." }, { 20.13, "Далеко не уходи." } } } } },
    [8583] = { t = { d = 18.9, v = "scourge-female#79", n = { x = 189 }, c = { x = { { 0.00, "Безукоризненно точная работа." }, { 2.44, "Не могу не похвалить твоё прилежание, а также быстроту." }, { 6.96, "Я лично присмотрю, чтобы ни один из этих цветков не пропал понапрасну." }, { 12.81, "Большое тебе спасибо." }, { 14.66, "Если соберёшь ещё лилового лотоса, бегом неси ко мне." } } } } },
    [8584] = { d = 35.6, v = "gnome-male", n = { x = 405 }, c = { x = { { 0.00, "Обо мне вам следует знать только одно – НИКОГДА не расспрашивайте меня о моём бизнесе!" }, { 6.16, "Я работаю с такими материями, в которых вы просто ничего не понимаете!" }, { 11.22, "Например: знаете ли вы, что такое психотронный мордарий?" }, { 15.25, "Конечно, не знаете!" }, { 16.67, "Именно поэтому я – мозговой центр, а вы – добывающий придаток." }, { 21.08, "Как я уже сказал, если мы хотим, чтобы у нас всё получилось, нам понадобится пятисотфунтовая курица." }, { 28.22, "Ступайте в Прибамбасск и поговорите с Диргом Быстрорубом – он скажет, где вам искать подходящий экземпляр." } } }, t = { d = 22.0, v = "goblin-male#108", n = { x = 224 }, c = { x = { { 0.00, "*Дирг чешет голову.*" }, { 2.08, "Пятисотфунтовая курица?" }, { 3.85, "Таких не бывает!" }, { 5.15, "То есть, уже не бывает." }, { 6.93, "Знавал я такую птицу..." }, { 8.77, "Чёрного бройлера-убийцу..." }, { 10.75, "Но никто из тех, кто видел эту птицу, не выжил, чтобы о ней рассказать." }, { 17.37, "Однако, у меня есть идейка, от которой будет выгода нам обоим." } } } } },
    [8585] = { d = 36.5, v = "goblin-male#108", n = { x = 349 }, c = { x = { { 0.00, "Легенды гласят, что у химер Острова Ужаса, что в Фераласе, самое сочное и нежное на свете мясо!" }, { 7.43, "У этих химер есть главный химер, который, если его приготовить как надо сойдёт за пятисотфунтовую курицу." }, { 16.64, "Или не сойдёт." }, { 17.75, "Ступай на остров Ужаса и убей лорда Лакмерана." }, { 22.38, "Принеси мне его тушу." }, { 24.12, "Гном схавает." }, { 25.16, "А вот чтобы я был доволен, достань мне немного вырезки химеры." }, { 29.95, "Сделай это – и будет тебе твоя пятисотфунтовая курица и кое-что сверх того." } } }, t = { d = 12.6, v = "goblin-male#108", n = { x = 128 }, c = { x = { { 0.00, "Посмотри только на мраморные прожилки в этой химерятинке!" }, { 4.65, "Блеск!" }, { 5.16, "Теперь вернёмся к нашим цыплятам..." }, { 7.99, "Посмотрим..." }, { 9.01, "Чтобы составить рецепт мне нужно пару минут." } } } } },
    [8586] = { d = 17.3, g = 1, v = "goblin-male#108", n = { m = 199, f = 200 }, c = { m = { { 0.00, "Рецепт готов!" }, { 1.01, "Теперь мне нужно от тебя немного ракетного топлива и глубокоскальной соли." }, { 6.26, "Я займусь специями, а за счёт мяса, что ты добыл покроем остальные расходы." }, { 11.51, "Как принесёшь мне то, что я просил, курица будет готова, и можешь нести её Нарайну." } }, f = { { 0.00, "Рецепт готов!" }, { 1.02, "Теперь мне нужно от тебя немного ракетного топлива и глубокоскальной соли." }, { 6.30, "Я займусь специями, а за счёт мяса, что ты добыла покроем остальные расходы." }, { 11.64, "Как принесёшь мне то, что я просил, курица будет готова, и можешь нести её Нарайну." } } }, t = { d = 7.9, v = "goblin-male#108", n = { x = 74 }, c = { x = { { 0.00, "Готово!" }, { 0.76, "Представляю тебе величайшее моё творение: лягающиеся химеровые отбивные Дирга!" } } } } },
    [8587] = { d = 17.0, g = 1, v = "goblin-male#108", n = { m = 165, f = 166 }, c = { m = { { 0.00, "Я гоблин слова, парень." }, { 2.04, "Вот твой пятисотфунтовый цыплёнок." }, { 4.76, "На кой гному пятисотфунтовый цыплёнок – понятия не имею..." }, { 9.44, "*Дирг ворчит себе под нос что-то неразборчивое.*" }, { 12.88, "Может, он спать в нём будет..." }, { 15.47, "Грязные гномы..." } }, f = { { 0.00, "Я гоблин слова, подруга." }, { 2.06, "Вот твой пятисотфунтовый цыплёнок." }, { 4.71, "На кой гному пятисотфунтовый цыплёнок – понятия не имею..." }, { 9.28, "*Дирг ворчит себе под нос что-то неразборчивое.*" }, { 13.12, "Может, он спать в нём будет..." }, { 15.71, "Грязные гномы..." } } }, t = { d = 13.5, v = "gnome-male", n = { x = 117 }, c = { x = { { 0.00, "*Нарайн обеими руками рвёт огромного цыплёнка, зарывается носом во вкуснейшее блюдо Дирга.*" }, { 7.68, "Ммммм..." }, { 8.61, "Невероятно!" }, { 9.96, "Никогда ничего вкуснее не едал!" } } } } },
    [8588] = { d = 30.7, g = 1, v = "troll-female#75", n = { x = 316 }, c = { m = { { 0.00, "Если уж мы собрались воевать, сначала надо подготовиться как следует, правда, дружище?" }, { 6.72, "Тяжёлая кожа на войне – продукт первой необходимости." }, { 10.85, "Она идёт на всё – начиная с заплаток на доспехи и заканчивая старыми добрыми ловушками." }, { 17.56, "Именно поэтому её надо собрать как можно больше." }, { 21.41, "А вот это уже твоя работа, герой." }, { 24.14, "Наточи поострее нож и добудь кож этак штук десять." }, { 28.06, "Вот принесёшь их, тогда и поговорим." } }, f = { { 0.00, "Если уж мы собрались воевать, сначала надо подготовиться как следует, правда, дружище?" }, { 6.70, "Тяжёлая кожа на войне – продукт первой необходимости." }, { 10.83, "Она идёт на всё – начиная с заплаток на доспехи и заканчивая старыми добрыми ловушками." }, { 17.53, "Именно поэтому её надо собрать как можно больше." }, { 21.37, "А вот это уже твоя работа, героиня." }, { 24.23, "Наточи поострее нож и добудь кож этак штук десять." }, { 28.15, "Вот принесёшь их, тогда и поговорим." } } }, t = { d = 17.6, g = 1, v = "troll-female#75", n = { x = 169 }, c = { m = { { 0.00, "О, тебе удалось достать толстую кожу." }, { 3.13, "У тебя острый нож, герой, кожи отлично выделаны!" }, { 7.13, "Пойду уберу их на склад." }, { 9.09, "Нужно убедиться, что твой вклад не пропадёт и послужит на благо Орде." }, { 14.55, "Если удастся раздобыть ещё, неси сюда." } }, f = { { 0.00, "О, тебе удалось достать толстую кожу." }, { 2.98, "У тебя острый нож, героиня, кожи отлично выделаны!" }, { 6.92, "Пойду уберу их на склад." }, { 8.79, "Нужно убедиться, что твой вклад не пропадёт и послужит на благо Орде." }, { 13.98, "Если удастся раздобыть ещё, неси сюда." } } } } },
    [8589] = { t = { d = 21.4, v = "troll-female#75", n = { x = 244 }, c = { x = { { 0.00, "Ну ты даёшь, дружище!" }, { 1.49, "Огромное тебе спасибо за эти кожи." }, { 4.07, "Каждая из них хоть немного, но приближает нас к завершению военной подготовки." }, { 9.56, "Пойду сдам кожи на склад, чтобы кожевники могли приступить к работе." }, { 14.47, "Большое тебе спасибо ещё раз." }, { 16.60, "Если раздобудешь следующую порцию кож, то ты знаешь, где меня найти." } } } } },
    [8590] = { d = 23.5, g = 1, v = "orc-female#58", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Я рада, что ты решил поговорить со мной, герой." }, { 3.48, "Подготовка к войне в Ан'Кираже идёт полным ходом, так что нам с тобой нельзя сбавлять темп работы." }, { 10.70, "Я отвечаю за сбор плотной кожи, и её нужно действительно много, поэтому без твоей помощи никак не справиться." }, { 18.79, "Если ты мне поможешь, в моём лице тебе будет благодарна вся Орда." } }, f = { { 0.00, "Я рада, что ты решила поговорить со мной, героиня." }, { 3.61, "Подготовка к войне в Ан'Кираже идёт полным ходом, так что нам с тобой нельзя сбавлять темп работы." }, { 10.70, "Я отвечаю за сбор плотной кожи, и её нужно действительно много, поэтому без твоей помощи никак не справиться." }, { 18.64, "Если ты мне поможешь, в моём лице тебе будет благодарна вся Орда." } } }, t = { d = 20.2, g = 1, v = "orc-female#58", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Ты хорошо постарался, герой." }, { 2.25, "Эта кожа не будет истрачена зря – она пойдёт на усиление наших дирижаблей и изготовление оружия и брони." }, { 10.40, "Благодарю тебя от лица всей Орды." }, { 13.07, "Если тебе в своих путешествиях удастся добыть ещё плотной кожи, неси её мне." }, { 19.11, "И удачи тебе." } }, f = { { 0.00, "Ты хорошо постаралась, героиня." }, { 2.45, "Эта кожа не будет истрачена зря – она пойдёт на усиление наших дирижаблей и изготовление оружия и брони." }, { 10.58, "Благодарю тебя от лица всей Орды." }, { 13.24, "Если тебе в своих путешествиях удастся добыть ещё плотной кожи, неси её мне." }, { 19.27, "И удачи тебе." } } } } },
    [8591] = { t = { d = 17.0, g = 1, v = "orc-female#58", n = { m = 149, f = 150 }, c = { m = { { 0.00, "Ты справился, я знала, что у тебя всё выйдет!" }, { 3.96, "От имени всей Орды я снова благодарю тебя." }, { 7.77, "Твой вклад не останется незамеченным." }, { 10.94, "Если достанешь ещё плотной кожи, приноси её мне." }, { 15.22, "Лок'тар огар, герой!" } }, f = { { 0.00, "Ты справилась, я знала, что у тебя всё выйдет!" }, { 3.97, "От имени всей Орды я снова благодарю тебя." }, { 7.70, "Твой вклад не останется незамеченным." }, { 10.81, "Если достанешь ещё плотной кожи, приноси её мне." }, { 15.02, "Лок'тар огар, героиня!" } } } } },
    [8592] = { d = 33.8, v = "gnome-female", n = { x = 329 }, c = { x = { { 0.00, "Императоры-близнецы..." }, { 1.85, "Их непрестанный шёпот в моих ушах потихоньку сводит меня с ума." }, { 7.09, "Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса." }, { 15.52, "Я вижу их безобразные головы, увенчанные могущественными коронами." }, { 20.91, "Но я отомщу им... эти символы власти Ан'Кираж будут служить нам." }, { 26.23, "Принеси то, что мне нужно." }, { 28.38, "Взамен я отдам тебе головной убор, не имеющий себе равных по силе." } } } },
    [8593] = { d = 42.1, g = 1, v = "human-male", n = { m = 465, f = 465 }, c = { m = { { 0.00, "Хочешь доказать нам, что тебе можно доверять, смертный?" }, { 4.14, "Ну хорошо." }, { 4.94, "Возможно, и тебе удастся извлечь из этого пользу." }, { 8.69, "Слушай." }, { 9.29, "Есть существо, обладающее легендарной силой." }, { 12.56, "Это древний песчаный червь Оуро." }, { 15.03, "Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни." }, { 21.25, "Шкура у этого червя просто невероятная." }, { 24.25, "Она такая толстая, что её невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом." }, { 34.81, "Принеси мне шкуру Оуро и ещё ряд компонентов, и я создам для тебя поножи, обладающие огромной силой." } }, f = { { 0.00, "Хочешь доказать нам, что тебе можно доверять, смертная?" }, { 4.03, "Ну хорошо." }, { 4.81, "Возможно, и тебе удастся извлечь из этого пользу." }, { 8.46, "Слушай." }, { 9.04, "Есть существо, обладающее легендарной силой." }, { 12.23, "Это древний песчаный червь Оуро." }, { 14.63, "Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни." }, { 20.68, "Шкура у этого червя просто невероятная." }, { 23.61, "Она такая толстая, что её невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом." }, { 33.89, "Принеси мне шкуру Оуро и ещё ряд компонентов, и я создам для тебя поножи, обладающие огромной силой." } } } },
    [8594] = { d = 20.0, v = "gnome-female", n = { x = 220 }, c = { x = { { 0.00, "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов." }, { 9.69, "Принеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье ещё более устрашающее, чем крылья самого Нефариана!" } } }, t = { d = 13.4, g = 1, v = "gnome-female", n = { m = 127, f = 127 }, c = { m = { { 0.00, "Я изготовила это наплечье, смертный, из принесённых тобой вещей и панцирей поверженных киражей." }, { 7.91, "Тебя оно защитит, а сердца врагов его вид наполнит ужасом." } }, f = { { 0.00, "Я изготовила это наплечье, смертная, из принесённых тобой вещей и панцирей поверженных киражей." }, { 8.30, "Тебя оно защитит, а сердца врагов его вид наполнит ужасом." } } } } },
    [8595] = { t = { d = 4.4, v = "human-male", n = { x = 45 }, c = { x = { { 0.00, "Мы довольны твоей службой." }, { 2.24, "Наш договор остаётся в силе." } } } } },
    [8596] = { d = 23.5, v = "human-male", n = { x = 277 }, c = { x = { { 0.00, "Древняя киражская магия исполнена небывалой силы." }, { 3.63, "Самые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона." }, { 11.35, "Принеси мне киражские наручники Повелевания и ещё несколько компонентов, и я создам для тебя потрясающие сапоги." }, { 19.32, "Увидишь, насколько они окажутся полезны в схватке с врагом." } } } },
    [8597] = { d = 36.2, v = "gnome-male", n = { x = 412 }, c = { x = { { 0.00, "Я так и знал, что однажды эта книга мне пригодится!" }, { 3.71, "И я в своей мудрости и предусмотрительности приготовил для неё укромное хранилище." }, { 9.61, "Не беспокойтесь, это место никто и никогда не найдёт!" }, { 13.52, "Только для того, чтобы туда добраться, мне понадобился вертолёт." }, { 18.23, "Увы, я потерпел крушение на берегу по дороге домой." }, { 22.07, "Но именно в результате этого несчастного случая я обрёл сверхгномские способности!" }, { 28.04, "Найдите мой разбитый вертолёт на Последнем берегу и плывите оттуда к югу!" }, { 33.40, "Нужное место узнаете с первого взгляда!" } } }, t = { d = 4.4, v = "narrator", n = { x = 35 }, c = { x = { { 0.00, "Книга пропала!" }, { 1.55, "На куче земли лежит записка." } } } } },
    [8598] = { d = 18.6, v = "narrator", n = { x = 179 }, c = { x = { { 0.00, "Текст записки оттиснут на пергаменте различными шрифтами." }, { 4.89, "Твоя драгоценная книга у нас, гном." }, { 7.92, "Ежели хочешь снова её увидеть, делай как сказано." }, { 12.27, "Дальше идёт список инструкций на три страницы." }, { 16.23, "Неси деньги и приходи один!" } } }, t = { d = 12.1, v = "gnome-male", n = { x = 104 }, c = { x = { { 0.00, "*Нарайн багровеет.*" }, { 2.00, "Похитили... мою... книгу, книгокрады!!!" }, { 5.52, "Я покажу им, как попадаться под руку гному с паранормальными способностями!" } } } } },
    [8599] = { d = 42.2, v = "creature/naga", n = { x = 397 }, c = { x = { { 0.00, "Нечасто у меня бывают гости." }, { 2.35, "Говоря по чести, последний раз это было тогда, когда я спасла этого миленького, сладенького гномика из-под обломков разбитого ветролета." }, { 13.20, "*Мередит смотрит вдаль, погрузившись в воспоминания.*" }, { 17.36, "Ты его знаешь?" }, { 18.71, "Нарайн?" }, { 19.43, "Нарайн Причуддень?" }, { 21.42, "О, как бы я была благодарна, если бы кто-нибудь доставил ему письмо от меня." }, { 28.17, "Я просто должна рассказать ему о своих чувствах!" }, { 32.54, "Я знаю, это любовь!" }, { 34.37, "Я точно знаю!" }, { 35.64, "Не можешь ли ты доставить это письмецо Нарайну?" }, { 39.86, "Я век буду благодарна тебе!" } } }, t = { d = 13.0, v = "gnome-male", n = { x = 107 }, c = { x = { { 0.00, "Что!?" }, { 0.96, "*Нарайн начинает суетиться.*" }, { 3.52, "Ну, хммм..." }, { 4.43, "От меня-то вы чего хотите???" }, { 6.85, "Она же рыба!" }, { 7.98, "РЫБА, говорю вам!" }, { 9.49, "А я гном." }, { 10.25, "У нас всё равно ничего бы не вышло." } } } } },
    [8600] = { d = 38.5, g = 1, v = "scourge-male#82", n = { x = 339 }, c = { m = { { 0.00, "Я понял, что подгонка ножа по руке важна даже больше, чем острота лезвия." }, { 6.60, "И самый тупой клинок способен порезать, если приложить нужное усилие." }, { 12.88, "Правильно, герой?" }, { 14.47, "Думаю, у нас не будет таких проблем, ведь наши ножи всегда хорошо заточены." }, { 21.23, "Ну, это не важно." }, { 22.82, "У меня для тебя есть дело." }, { 25.20, "Достань мне побольше прочной кожи." }, { 28.30, "Она нужна, чтобы Орда как следует подготовилась к войне в Ан'Кираже." }, { 34.43, "Я не сомневаюсь, что ты отлично справишься, ага?" } }, f = { { 0.00, "Я понял, что подгонка ножа по руке важна даже больше, чем острота лезвия." }, { 6.39, "И самый тупой клинок способен порезать, если приложить нужное усилие." }, { 12.48, "Правильно, героиня?" }, { 14.18, "Думаю, у нас не будет таких проблем, ведь наши ножи всегда хорошо заточены." }, { 20.72, "Ну, это не важно." }, { 22.27, "У меня для тебя есть дело." }, { 24.58, "Достань мне побольше прочной кожи." }, { 27.58, "Она нужна, чтобы Орда как следует подготовилась к войне в Ан'Кираже." }, { 33.51, "Я не сомневаюсь, что ты отлично справишься, ага?" } } }, t = { d = 23.2, g = 1, v = "scourge-male#82", n = { m = 205, f = 206 }, c = { m = { { 0.00, "Прекрасно, прекрасно, ты проделал неплохую работёнку, хотя некоторые из этих кож по краям обрезаны не слишком ровно." }, { 10.61, "Но, без сомнений, задание выполнено, и ты получишь обещанную награду." }, { 16.91, "Если вдруг раздобудешь ещё прочной кожи, то тащи её мне поскорее." } }, f = { { 0.00, "Прекрасно, прекрасно, ты проделала неплохую работёнку, хотя некоторые из этих кож по краям обрезаны не слишком ровно." }, { 10.84, "Но, без сомнений, задание выполнено, и ты получишь обещанную награду." }, { 17.23, "Если вдруг раздобудешь ещё прочной кожи, то тащи её мне поскорее." } } } } },
    [8601] = { t = { d = 33.7, g = 1, v = "scourge-male#82", n = { m = 314, f = 316 }, c = { m = { { 0.00, "Тренировка, тренировка и ещё раз тренировка." }, { 3.70, "Хорошо заточенный нож и умение им пользоваться ещё не раз сослужат тебе добрую службу." }, { 11.01, "Похоже, края этих кож стали ровнее, чем было вначале." }, { 15.71, "Ты купил себе новый нож?" }, { 17.87, "В любом случае, большое спасибо за потраченные силы." }, { 22.41, "Твой вклад не останется незамеченным, уж будь уверен." }, { 26.80, "Если вдруг сыщешь ещё прочной кожи, приходи узнать, не нужна ли она мне." } }, f = { { 0.00, "Тренировка, тренировка и ещё раз тренировка." }, { 3.77, "Хорошо заточенный нож и умение им пользоваться ещё не раз сослужат тебе добрую службу." }, { 11.23, "Похоже, края этих кож стали ровнее, чем было вначале." }, { 16.02, "Ты купила себе новый нож?" }, { 18.29, "В любом случае, большое спасибо за потраченные силы." }, { 22.93, "Твой вклад не останется незамеченным, уж будь уверена." }, { 27.48, "Если вдруг сыщешь ещё прочной кожи, приходи узнать, не нужна ли она мне." } } } } },
    [8602] = { d = 20.2, v = "gnome-female", n = { x = 220 }, c = { x = { { 0.00, "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов." }, { 9.47, "Принеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье ещё более устрашающее, чем крылья самого Нефариана!" } } } },
    [8603] = { d = 43.8, v = "nightelf-female", n = { x = 489 }, c = { x = { { 0.00, "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже." }, { 6.95, "Ужасная судьба, которая ждёт Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет." }, { 15.21, "Для существа, обладающего подобной мощью, время не имеет значения." }, { 20.06, "Встанут звёзды подходящим образом – и ярость его обрушится на живущих, подобно плети." }, { 26.29, "Тебе следует найти его и положить конец его существованию, пока он не пробудился." }, { 32.32, "Когда ты сделаешь это, принеси мне кусок его панциря." }, { 36.32, "Взамен я дам тебе броню, подобной которой не владел ещё никто из смертных." }, { 41.76, "Броню, достойную убийцы бога." } } } },
    [8604] = { d = 32.7, g = 1, v = "tauren-male#67", n = { x = 328 }, c = { m = { { 0.00, "Приветствую, герой." }, { 1.59, "Мне поручено собирать шерстяные бинты для подготовки к войне в Ан'Кираже." }, { 7.43, "К сожалению, на поле боя солдаты не могут рассчитывать, что лекари успеют добраться сразу до всех." }, { 15.30, "Поэтому мы должны уделить как можно больше внимания оказанию первой помощи." }, { 21.43, "Если у тебя есть время, помоги мне собрать шерстяные бинты." }, { 26.27, "Принеси их сюда, а я позабочусь, чтобы тебе выдали положенное вознаграждение." } }, f = { { 0.00, "Приветствую, героиня." }, { 1.75, "Мне поручено собирать шерстяные бинты для подготовки к войне в Ан'Кираже." }, { 7.64, "К сожалению, на поле боя солдаты не могут рассчитывать, что лекари успеют добраться сразу до всех." }, { 15.56, "Поэтому мы должны уделить как можно больше внимания оказанию первой помощи." }, { 21.75, "Если у тебя есть время, помоги мне собрать шерстяные бинты." }, { 26.62, "Принеси их сюда, а я позабочусь, чтобы тебе выдали положенное вознаграждение." } } }, t = { d = 15.1, g = 1, v = "tauren-male#67", n = { x = 119 }, c = { m = { { 0.00, "Прими мою благодарность, герой, и вместе с ней – благодарность всей Орды." }, { 7.00, "Если тебе ещё попадутся шерстяные бинты, неси их мне." }, { 12.18, "А пока – да хранят тебя предки!" } }, f = { { 0.00, "Прими мою благодарность, героиня, и вместе с ней – благодарность всей Орды." }, { 6.86, "Если тебе ещё попадутся шерстяные бинты, неси их мне." }, { 11.83, "А пока – да хранят тебя предки!" } } } } },
    [8605] = { t = { d = 24.5, v = "tauren-male#67", n = { x = 228 }, c = { x = { { 0.00, "Ты знаешь, что такое настоящее благородство!" }, { 3.91, "Я прослежу, чтобы эти бинты попали в нужные руки." }, { 8.45, "Прими мою благодарность и благодарность Орды." }, { 12.52, "Ступай с миром и обязательно возвращайся, если у тебя будут лишние шерстяные бинты." }, { 20.01, "Нам понадобится вся помощь, которая только возможна." } } } } },
    [8606] = { d = 33.0, v = "gnome-male", n = { x = 362 }, c = { x = { { 0.00, "Меня посетила гениальная мысль!" }, { 2.50, "Вот что мы сделаем." }, { 4.00, "Я насыплю в мешок камней, а вы осуществите сброс." }, { 7.85, "Да, знаю, я должен доставить выкуп лично – я и доставлю, типа того." }, { 13.20, "*Нарайн меряет вас взглядом.*" }, { 15.76, "Сойдёте." }, { 16.31, "Берите этот тюрбан, одежду и мешок с камнями и направляйтесь к условленной точке сброса в Зимних ключах." }, { 23.41, "В этом специальном наборе всё, что вам нужно." }, { 26.44, "Когда они высунут нос, чтобы забрать выкуп, задайте им перцу!" }, { 30.69, "Будут знать, как наезжать на Нарайна!" } } }, t = { d = 3.7, v = "gnome-male", n = { x = 34 }, c = { x = { { 0.00, "А вдруг мы недооценили этих книгокрадов?" } } } } },
    [8607] = { d = 27.8, g = 1, v = "scourge-female#80", n = { x = 269 }, c = { m = { { 0.00, "Ты действительно хочешь помочь мне в сборе материалов, за которые я отвечаю?" }, { 6.15, "Отлично!" }, { 6.88, "Бинты из магической ткани нужны мне любой ценой, я имею в виду, в буквальном смысле \"любой ценой\"." }, { 15.00, "Хорошо бы свежие, но это совершенно не обязательно." }, { 19.17, "Когда добудешь их, герой, возвращайся ко мне, я прослежу, чтобы тебя соответственным образом наградили." } }, f = { { 0.00, "Ты действительно хочешь помочь мне в сборе материалов, за которые я отвечаю?" }, { 6.20, "Отлично!" }, { 6.94, "Бинты из магической ткани нужны мне любой ценой, я имею в виду, в буквальном смысле \"любой ценой\"." }, { 15.14, "Хорошо бы свежие, но это совершенно не обязательно." }, { 19.35, "Когда добудешь их, героиня, возвращайся ко мне, я прослежу, чтобы тебя соответственным образом наградили." } } }, t = { d = 26.6, g = 1, v = "scourge-female#80", n = { x = 226 }, c = { m = { { 0.00, "Удивительно, но всё в порядке." }, { 2.73, "Возможно, я недооценила твои способности, герой." }, { 7.20, "Всё возможно." }, { 8.44, "К тому же, задание было несложное, а награда гораздо больше, чем следует." }, { 15.22, "Впрочем, не бери в голову." }, { 17.70, "Если хочешь в самом деле доказать, чего стоишь, ступай и принеси ещё бинтов из магической ткани." } }, f = { { 0.00, "Удивительно, но всё в порядке." }, { 2.69, "Возможно, я недооценила твои способности, героиня." }, { 7.25, "Всё возможно." }, { 8.47, "К тому же, задание было несложное, а награда гораздо больше, чем следует." }, { 15.16, "Впрочем, не бери в голову." }, { 17.60, "Если хочешь в самом деле доказать, чего стоишь, ступай и принеси ещё бинтов из магической ткани." } } } } },
    [8608] = { t = { d = 28.3, g = 1, v = "scourge-female#80", n = { x = 272 }, c = { m = { { 0.00, "Просто поразительно, герой, тебе опять всё удалось!" }, { 4.38, "Ну, говорят, что у меня нюх на помощников." }, { 7.85, "Хорошо, твой вклад не останется незамеченным и ты несомненно получишь социальные льготы соразмерно своим заслугам." }, { 17.29, "А пока, я полагаю, тебе следует вернуться к сбору бинтов из магической ткани, если ты действительно хочешь доказать, чего стоишь." } }, f = { { 0.00, "Просто поразительно, героиня, тебе опять всё удалось!" }, { 4.53, "Ну, говорят, что у меня нюх на помощников." }, { 8.01, "Хорошо, твой вклад не останется незамеченным и ты несомненно получишь социальные льготы соразмерно своим заслугам." }, { 17.45, "А пока, я полагаю, тебе следует вернуться к сбору бинтов из магической ткани, если ты действительно хочешь доказать, чего стоишь." } } } } },
    [8609] = { d = 33.4, g = 1, v = "tauren-female", n = { x = 348 }, c = { m = { { 0.00, "Альянс и Орда готовятся к войне в Ан'Кираже, идя встречными курсами." }, { 5.33, "Просто удивительно, что они собираются воевать не друг с другом, а с силитидами, какая бы сила ни стояла за ними." }, { 13.99, "Не менее удивительно, что обе стороны вносят свой вклад в заготовку военных ресурсов в достаточном количестве." }, { 22.36, "Я отвечаю за сбор бинтов из рунной ткани, для оказания первой помощи." }, { 27.69, "Но одна я точно не справлюсь." }, { 29.98, "Помоги мне, герой, я буду очень признательна." } }, f = { { 0.00, "Альянс и Орда готовятся к войне в Ан'Кираже, идя встречными курсами." }, { 5.30, "Просто удивительно, что они собираются воевать не друг с другом, а с силитидами, какая бы сила ни стояла за ними." }, { 13.89, "Не менее удивительно, что обе стороны вносят свой вклад в заготовку военных ресурсов в достаточном количестве." }, { 22.22, "Я отвечаю за сбор бинтов из рунной ткани, для оказания первой помощи." }, { 27.51, "Но одна я точно не справлюсь." }, { 29.78, "Помоги мне, героиня, я буду очень признательна." } } }, t = { d = 21.3, g = 1, v = "tauren-female", n = { m = 219, f = 220 }, c = { m = { { 0.00, "Орда в долгу перед тобой, герой." }, { 2.64, "Спасибо тебе за то, что ты для нас сделал, мы сохраним твои поступки в своём сердце." }, { 9.04, "Я должна складировать эти бинты и посчитать, насколько мы приблизились к выполнению цели." }, { 15.93, "Если получится, добудь ещё бинтов из рунной ткани и возвращайся ко мне." } }, f = { { 0.00, "Орда в долгу перед тобой, героиня." }, { 2.76, "Спасибо тебе за то, что ты для нас сделала, мы сохраним твои поступки в своём сердце." }, { 9.16, "Я должна складировать эти бинты и посчитать, насколько мы приблизились к выполнению цели." }, { 15.99, "Если получится, добудь ещё бинтов из рунной ткани и возвращайся ко мне." } } } } },
    [8610] = { t = { d = 17.3, v = "tauren-female", n = { x = 179 }, c = { x = { { 0.00, "С твоей стороны это очень бескорыстный поступок." }, { 3.87, "Может быть, именно он спасёт жизнь многим бойцам нашей армии в Ан'Кираже." }, { 9.56, "Орда в долгу перед тобой." }, { 11.67, "Если сумеешь достать ещё бинтов из рунной ткани, пожалуйста, неси их мне." } } } } },
    [8611] = { d = 36.0, g = 1, v = "orc-female#58", n = { x = 391 }, c = { m = { { 0.00, "Я здесь не просто так загораю, герой." }, { 2.74, "Подготовка к войне – дело нешуточное!" }, { 5.54, "Если мы хотим передавить киражских тараканов, надо приложить массу усилий, в том числе к заготовке провианта." }, { 13.69, "Меня назначили ответственной за засолку постных стейков из волчатины." }, { 18.84, "Однако не могу же я разорваться на части – бегать за волками по лесам и обеспечивать хранение и учёт мяса одновременно." }, { 27.58, "Так что это тебе придётся добыть волчатины и приготовить её, как надо, а потом ты принесёшь её мне." }, { 34.73, "Всё понятно?" } }, f = { { 0.00, "Я здесь не просто так загораю, героиня." }, { 2.89, "Подготовка к войне – дело нешуточное!" }, { 5.72, "Если мы хотим передавить киражских тараканов, надо приложить массу усилий, в том числе к заготовке провианта." }, { 13.93, "Меня назначили ответственной за засолку постных стейков из волчатины." }, { 19.11, "Однако не могу же я разорваться на части – бегать за волками по лесам и обеспечивать хранение и учёт мяса одновременно." }, { 27.93, "Так что это тебе придётся добыть волчатины и приготовить её, как надо, а потом ты принесёшь её мне." }, { 35.13, "Всё понятно?" } } }, t = { d = 17.4, g = 1, v = "orc-female#58", n = { x = 163 }, c = { m = { { 0.00, "О, это мясо неплохо выглядит." }, { 2.41, "Сейчас я его засолю и уберу на хранение." }, { 5.68, "Надеюсь, до войны оно доживёт свежим." }, { 8.66, "Спасибо за вклад в наше общее дело, герой." }, { 12.07, "А пока – как насчёт того, чтобы принести мне ещё порцию стейков?" } }, f = { { 0.00, "О, это мясо неплохо выглядит." }, { 2.45, "Сейчас я его засолю и уберу на хранение." }, { 5.77, "Надеюсь, до войны оно доживёт свежим." }, { 8.79, "Спасибо за вклад в наше общее дело, героиня." }, { 12.40, "А пока – как насчёт того, чтобы принести мне ещё порцию стейков?" } } } } },
    [8613] = { d = 25.9, g = 1, v = "troll-male#78", n = { x = 258 }, c = { m = { { 0.00, "Отличный денёк для рыбалки, ага, дружище?" }, { 3.25, "Эта ты правильно думаешь, мне б рыбка ого как пригодилась." }, { 7.83, "Орде нужна чёртова куча пятнистого желтохвоста." }, { 11.57, "Говорят, мы будем его хавать, когда отправимся в Ан'Кираж рубиться." }, { 16.93, "Так я ответил, что всегда готов служить, ага." }, { 20.53, "Тока мне, конечно, помощь понадобится." }, { 23.56, "Ты как насчёт помочь, герой?" } }, f = { { 0.00, "Отличный денёк для рыбалки, ага, дружище?" }, { 3.27, "Эта ты правильно думаешь, мне б рыбка ого как пригодилась." }, { 7.89, "Орде нужна чёртова куча пятнистого желтохвоста." }, { 11.65, "Говорят, мы будем его хавать, когда отправимся в Ан'Кираж рубиться." }, { 17.05, "Так я ответил, что всегда готов служить, ага." }, { 20.67, "Тока мне, конечно, помощь понадобится." }, { 23.73, "Ты как насчёт помочь, героиня?" } } }, t = { d = 21.5, g = 1, v = "troll-male#78", n = { m = 201, f = 203 }, c = { m = { { 0.00, "О, вот эт'дело." }, { 1.29, "Отличный рыбец!" }, { 2.65, "Счас-ка я её приберу, штоб не попортилась." }, { 6.14, "Спасибо, што помог." }, { 7.80, "Я так скажу, ты пока номер один по этому самому желтохвосту." }, { 12.95, "Как наловишь и изготовишь ещё штук двадцать, тащи сюда." }, { 17.57, "Будь спок, уж я всем раззвоню о твоих подвигах!" } }, f = { { 0.00, "О, вот эт'дело." }, { 1.29, "Отличный рыбец!" }, { 2.66, "Счас-ка я её приберу, штоб не попортилась." }, { 6.16, "Спасибо, што помогла." }, { 7.99, "Я так скажу, ты пока номер один по этому самому желтохвосту." }, { 13.16, "Как наловишь и изготовишь ещё штук двадцать, тащи сюда." }, { 17.80, "Будь спок, уж я всем раззвоню о твоих подвигах!" } } } } },
    [8614] = { t = { d = 15.0, v = "troll-male#78", n = { x = 136 }, c = { x = { { 0.00, "Лучший улов сезона!" }, { 1.86, "Отличная работёнка." }, { 3.56, "Вот эт' я понимаю, никаких костей в рыбе." }, { 7.28, "За такого желтохвоста всякий боец спасибо скажет." }, { 11.81, "Наловишь ещё, тащи сюда обязательно." } } } } },
    [8615] = { d = 35.4, g = 1, v = "tauren-male#68", n = { x = 348 }, c = { m = { { 0.00, "Подготовка к войне в Ан'Кираже – дело нешуточное, герой." }, { 4.53, "Чтобы изготовить оружие, нужно железо, а чтобы крепко держать его в руках – провиант." }, { 11.49, "Если ты не поешь пару дней, хватит ли у тебя сил поднять боевой топор, когда придёт время для битвы?" }, { 19.54, "Именно поэтому сбор провизии не менее важен, чем всё остальное." }, { 24.57, "Я занимаюсь заготовками запечённого лосося." }, { 27.94, "Он хорошо хранится и обладает отличными питательными свойствами." }, { 33.04, "Ну что, поможешь мне, герой?" } }, f = { { 0.00, "Подготовка к войне в Ан'Кираже – дело нешуточное, героиня." }, { 4.67, "Чтобы изготовить оружие, нужно железо, а чтобы крепко держать его в руках – провиант." }, { 11.65, "Если ты не поешь пару дней, хватит ли у тебя сил поднять боевой топор, когда придёт время для битвы?" }, { 19.70, "Именно поэтому сбор провизии не менее важен, чем всё остальное." }, { 24.73, "Я занимаюсь заготовками запечённого лосося." }, { 28.11, "Он хорошо хранится и обладает отличными питательными свойствами." }, { 33.22, "Ну что, поможешь мне, героиня?" } } }, t = { d = 30.7, g = 1, v = "tauren-male#68", n = { m = 312, f = 314 }, c = { m = { { 0.00, "Большое спасибо, что помог мне с заготовкой рыбы, герой." }, { 4.54, "Очень многим нет никакого дела до подготовки к войне, их интересует только, как бы набить свои карманы." }, { 12.84, "Они недостойны благорасположения Орды, в отличие от тебя." }, { 17.46, "Пусть твоё сердце исполнится гордости за свои бескорыстные деяния." }, { 22.72, "Прими ещё раз мою благодарность." }, { 25.32, "Если найдёшь время, чтобы ещё раз помочь нам, буду очень признателен." } }, f = { { 0.00, "Большое спасибо, что помогла мне с заготовкой рыбы, героиня." }, { 4.63, "Очень многим нет никакого дела до подготовки к войне, их интересует только, как бы набить свои карманы." }, { 12.57, "Они недостойны благорасположения Орды, в отличие от те