    [8616] = { t = { d = 18.0, g = 1, v = "tauren-male#68", n = { m = 164, f = 165 }, c = { m = { { 0.00, "Трудно представить, сколько времени и сил ты потратил, чтобы помочь нам." }, { 6.52, "Знай, твои труды не пропадут впустую." }, { 9.94, "Я благодарен тебе от имени всей Орды." }, { 13.36, "Возвращайся, когда наготовишь следующую порцию рыбы." } }, f = { { 0.00, "Трудно представить, сколько времени и сил ты потратила, чтобы помочь нам." }, { 6.54, "Знай, твои труды не пропадут впустую." }, { 9.93, "Я благодарен тебе от имени всей Орды." }, { 13.32, "Возвращайся, когда наготовишь следующую порцию рыбы." } } } } },
    [8617] = { d = 40.6, g = 1, v = "orc-male#60", n = { m = 428, f = 429 }, c = { m = { { 0.00, "Пришло время и тебе поучаствовать в нашей подготовке войны в Ан'Кираже, герой." }, { 6.12, "Прошли деньки, когда можно было беззаботно валяться на солнышке." }, { 11.20, "Нынче каждый должен встать под знамёна Орды и Вождя!" }, { 15.24, "А я, в отличие от нашего вождя, добросердечием не страдаю, уж будь спокоен." }, { 20.95, "Ты должен собрать военные силы своей гильдии (если состоишь в таковой) и проникнуть в Огненные Недра." }, { 28.88, "Мне нужны оплавленные вулканические камни, которые можно обнаружить у тамошних обитателей." }, { 35.84, "Собери столько камней, сколько сможешь, и возвращайся обратно." } }, f = { { 0.00, "Пришло время и тебе поучаствовать в нашей подготовке войны в Ан'Кираже, героиня." }, { 6.08, "Прошли деньки, когда можно было беззаботно валяться на солнышке." }, { 11.02, "Нынче каждая должна встать под знамёна Орды и Вождя!" }, { 14.94, "А я, в отличие от нашего вождя, добросердечием не страдаю, уж будь спокойна." }, { 20.55, "Ты должна собрать военные силы своей гильдии (если состоишь в таковой) и проникнуть в Огненные Недра." }, { 28.26, "Мне нужны оплавленные вулканические камни, которые можно обнаружить у тамошних обитателей." }, { 35.02, "Собери столько камней, сколько сможешь, и возвращайся обратно." } } } },
    [8619] = { t = { d = 8.8, v = "dwarf-male", n = { x = 86 }, c = { x = { { 0.00, "Приятно знать, что жители этих земель всё ещё чтят древние расы." }, { 5.13, "Желаю тебе удачи, и прими от меня этот знак..." } } } } },
    [8620] = { d = 33.6, g = 1, v = "gnome-male", n = { m = 372, f = 374 }, c = { m = { { 0.00, "Надо было раньше сообразить!" }, { 2.17, "Мой архивраг, Доктор Жло, взялся за старое!" }, { 5.64, "А теперь, благодаря вашему провалу в Зимних ключах, Доктор Жло уничтожил мою книгу!" }, { 11.82, "И как теперь вы будете спасать мир, герой?" }, { 14.91, "Из полученной мной записки я узнал, что \"Драконий язык для чайников: том второй\" разорван на восемь частей и разбросан по ветру!" }, { 24.18, "Если вы как-нибудь умудритесь найти пропавшие главы, при помощи этого магического переплёта сшейте их снова и возвращайтесь ко мне." } }, f = { { 0.00, "Надо было раньше сообразить!" }, { 2.16, "Мой архивраг, Доктор Жло, взялся за старое!" }, { 5.74, "А теперь, благодаря вашему провалу в Зимних ключах, Доктор Жло уничтожил мою книгу!" }, { 11.89, "И как теперь вы будете спасать мир, героиня?" }, { 15.09, "Из полученной мной записки я узнал, что \"Драконий язык для чайников: том второй\" разорван на восемь частей и разбросан по ветру!" }, { 24.30, "Если вы как-нибудь умудритесь найти пропавшие главы, при помощи этого магического переплёта сшейте их снова и возвращайтесь ко мне." } } }, t = { d = 16.7, g = 1, v = "gnome-male", n = { m = 176, f = 177 }, c = { m = { { 0.00, "Фантастика." }, { 0.87, "Поверить не могу, что вы взяли на себя столько хлопот!" }, { 4.93, "Вы, часом, не машина?" }, { 6.53, "Будь я на вашем месте – да горел бы этот мир синим огнём!" }, { 10.73, "Снимаю перед вами тюрбан, сэр." }, { 13.07, "Что же, доброе дело не должно остаться без награды." } }, f = { { 0.00, "Фантастика." }, { 0.86, "Поверить не могу, что вы взяли на себя столько хлопот!" }, { 4.89, "Вы, часом, не машина?" }, { 6.48, "Будь я на вашем месте – да горел бы этот мир синим огнём!" }, { 10.65, "Снимаю перед вами тюрбан, леди." }, { 13.10, "Что же, доброе дело не должно остаться без награды." } } } } },
    [8621] = { d = 23.3, v = "human-male", n = { x = 276 }, c = { x = { { 0.00, "Древняя киражская магия исполнена небывалой силы." }, { 3.60, "Самые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона." }, { 11.26, "Принеси мне киражские наручники Господства и ещё несколько компонентов, и я создам для тебя потрясающие сапоги." }, { 19.11, "Увидишь, насколько они окажутся полезны в схватке с врагом." } } } },
    [8622] = { d = 42.9, v = "nightelf-female", n = { x = 489 }, c = { x = { { 0.00, "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже." }, { 6.80, "Ужасная судьба, которая ждёт Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет." }, { 14.88, "Для существа, обладающего подобной мощью, время не имеет значения." }, { 19.62, "Встанут звёзды подходящим образом – и ярость его обрушится на живущих, подобно плети." }, { 25.71, "Тебе следует найти его и положить конец его существованию, пока он не пробудился." }, { 31.61, "Когда ты сделаешь это, принеси мне кусок его панциря." }, { 35.52, "Взамен я дам тебе броню, подобной которой не владел ещё никто из смертных." }, { 40.84, "Броню, достойную убийцы бога." } } } },
    [8623] = { d = 34.8, v = "gnome-female", n = { x = 330 }, c = { x = { { 0.00, "Императоры-близнецы..." }, { 1.90, "Их непрестанный шёпот в моих ушах потихоньку сводит меня с ума." }, { 7.28, "Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса." }, { 15.92, "Я вижу их безобразные головы, увенчанные могущественными коронами." }, { 21.46, "Но я отомщу им... эти символы власти Ан'Киража будут служить нам." }, { 26.99, "Принеси то, что мне нужно." }, { 29.19, "Взамен я отдам тебе головной убор, не имеющий себе равных по силе." } } } },
    [8624] = { d = 42.0, g = 1, v = "human-male", n = { m = 465, f = 465 }, c = { m = { { 0.00, "Хочешь доказать нам, что тебе можно доверять, смертный?" }, { 4.08, "Ну хорошо." }, { 4.87, "Возможно, и тебе удастся извлечь из этого пользу." }, { 8.55, "Слушай." }, { 9.15, "Есть существо, обладающее легендарной силой." }, { 12.37, "Это древний песчаный червь Оуро." }, { 14.81, "Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни." }, { 20.92, "Шкура у этого червя просто невероятная." }, { 23.89, "Она такая толстая, что её невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом." }, { 34.28, "Принеси мне шкуру Оуро и ещё ряд компонентов, и я создам для тебя поножи, обладающие огромной силой." } }, f = { { 0.00, "Хочешь доказать нам, что тебе можно доверять, смертная?" }, { 4.13, "Ну хорошо." }, { 4.93, "Возможно, и тебе удастся извлечь из этого пользу." }, { 8.67, "Слушай." }, { 9.27, "Есть существо, обладающее легендарной силой." }, { 12.54, "Это древний песчаный червь Оуро." }, { 15.00, "Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни." }, { 21.21, "Шкура у этого червя просто невероятная." }, { 24.21, "Она такая толстая, что её невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом." }, { 34.74, "Принеси мне шкуру Оуро и ещё ряд компонентов, и я создам для тебя поножи, обладающие огромной силой." } } } },
