    [8632] = { d = 34.2, v = "gnome-female", n = { x = 328 }, c = { x = { { 0.00, "Императоры-близнецы..." }, { 1.87, "Их непрестанный шёпот в моих ушах потихоньку сводит меня с ума." }, { 7.18, "Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса." }, { 15.70, "Я вижу их безобразные головы, увенчанные могущественными коронами." }, { 21.16, "Но я отомщу им... эти символы мощи Ан'Киража будут служить нам." }, { 26.46, "Принеси то, что мне нужно." }, { 28.63, "Взамен я отдам тебе головной убор, не имеющий себе равных по силе." } } } },
    [8633] = { d = 43.4, v = "nightelf-female", n = { x = 489 }, c = { x = { { 0.00, "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже." }, { 6.87, "Ужасная судьба, которая ждёт Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет." }, { 15.04, "Для существа, обладающего подобной мощью, время не имеет значения." }, { 19.84, "Встанут звёзды подходящим образом – и ярость его обрушится на живущих, подобно плети." }, { 26.00, "Тебе следует найти его и положить конец его существованию, пока он не пробудился." }, { 31.96, "Когда ты сделаешь это, принеси мне кусок его панциря." }, { 35.92, "Взамен я дам тебе броню, подобной которой не владел ещё никто из смертных." }, { 41.30, "Броню, достойную убийцы бога." } } } },
    [8634] = { d = 23.4, v = "human-male", n = { x = 276 }, c = { x = { { 0.00, "Древняя киражская магия исполнена небывалой силы." }, { 3.62, "Самые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона." }, { 11.30, "Принеси мне киражские наручники Господства и ещё несколько компонентов, и я создам для тебя потрясающие сапоги." }, { 19.18, "Увидишь, насколько они окажутся полезны в схватке с врагом." } } } },
    [8635] = { t = { d = 15.5, v = "dwarf-male", n = { x = 146 }, c = { x = { { 0.00, "Битвы минувших эпох — семена, из которых прорастают легенды." }, { 5.05, "Твоё время — время героев, дитя." }, { 7.80, "Пусть же твоя легенда пустит корни и расцветёт." }, { 11.66, "Желаю тебе удачи, и прими от меня этот знак..." } } } } },
    [8636] = { t = { d = 10.0, v = "dwarf-male", n = { x = 88 }, c = { x = { { 0.00, "Всё живое обречено умереть и вернуться в землю, но дух живёт вечно." }, { 5.92, "Желаю тебе удачи, и прими от меня этот знак..." } } } } },
