    [8656] = { d = 43.8, v = "nightelf-female", n = { x = 489 }, c = { x = { { 0.00, "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже." }, { 6.95, "Ужасная судьба, которая ждёт Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет." }, { 15.21, "Для существа, обладающего подобной мощью, время не имеет значения." }, { 20.06, "Встанут звёзды подходящим образом – и ярость его обрушится на живущих, подобно плети." }, { 26.29, "Тебе следует найти его и положить конец его существованию, пока он не пробудился." }, { 32.32, "Когда ты сделаешь это, принеси мне кусок его панциря." }, { 36.32, "Взамен я дам тебе броню, подобной которой не владел ещё никто из смертных." }, { 41.76, "Броню, достойную убийцы бога." } } }, t = { d = 31.4, g = 1, v = "nightelf-female", n = { m = 365, f = 370 }, c = { m = { { 0.00, "Я не ожидала, что ты сумеешь вернуться живым." }, { 3.10, "Тебе удалось исполнить то, что не под силу многим бессмертным." }, { 7.37, "Убив К'Туна, ты не только спас Азерот, ты поколебал чаши космических весов, на которых лежат события, далеко превосходящие твоё понимание." }, { 16.86, "Прими этот доспех как символ великой славы и знак великого груза, который ты взвалил на себя своим поступком." }, { 24.48, "Быть может, он поможет преодолеть тяготы пути, который отныне лежит перед тобой, богоборец." } }, f = { { 0.00, "Я не ожидала, что ты сумеешь вернуться живой." }, { 3.13, "Тебе удалось исполнить то, что не под силу многим бессмертным." }, { 7.44, "Убив К'Туна, ты не только спасла Азерот, ты поколебала чаши космических весов, на которых лежат события, далеко превосходящие твоё понимание." }, { 17.25, "Прими этот доспех как символ великой славы и знак великого груза, который ты взвалила на себя своим поступком." }, { 25.00, "Быть может, он поможет преодолеть тяготы пути, который отныне лежит перед тобой, богоборица." } } } } },
    [8657] = { d = 34.2, v = "gnome-female", n = { x = 328 }, c = { x = { { 0.00, "Императоры-близнецы..." }, { 1.87, "Их непрестанный шёпот в моих ушах потихоньку сводит меня с ума." }, { 7.18, "Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса." }, { 15.70, "Я вижу их безобразные головы, увенчанные могущественными коронами." }, { 21.16, "Но я отомщу им... эти символы мощи Ан'Киража будут служить нам." }, { 26.46, "Принеси то, что мне нужно." }, { 28.63, "Взамен я отдам тебе головной убор, не имеющий себе равных по силе." } } }, t = { d = 19.8, v = "gnome-female", n = { x = 197 }, c = { x = { { 0.00, "Тебе удалось одержать победу!" }, { 2.52, "Императоры-близнецы прекратили шептаться в моей голове." }, { 7.11, "Прими же от меня награду." }, { 9.26, "Один вид этой вещи вселит ужас в сердца киражей..." }, { 13.55, "Она напоминает им, что самые могучие их предводители погибли от руки смертных." } } } } },
    [8658] = { d = 42.2, g = 1, v = "human-male", n = { m = 465, f = 465 }, c = { m = { { 0.00, "Хочешь доказать нам, что тебе можно доверять, смертный?" }, { 4.14, "Ну хорошо." }, { 4.94, "Возможно, и тебе удастся извлечь из этого пользу." }, { 8.69, "Слушай." }, { 9.29, "Есть существо, обладающее легендарной силой." }, { 12.56, "Это древний песчаный червь Оуро." }, { 15.03, "Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни." }, { 21.25, "Шкура у этого червя просто невероятная." }, { 24.25, "Она такая толстая, что её невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом." }, { 34.81, "Принеси мне шкуру Оуро и ещё ряд компонентов, и я создам для тебя поножи, обладающие огромной силой." } }, f = { { 0.00, "Хочешь доказать нам, что тебе можно доверять, смертная?" }, { 4.16, "Ну хорошо." }, { 4.96, "Возможно, и тебе удастся извлечь из этого пользу." }, { 8.72, "Слушай." }, { 9.32, "Есть существо, обладающее легендарной силой." }, { 12.61, "Это древний песчаный червь Оуро." }, { 15.09, "Говорят, его создал сам Древний Бог, в насмешку над всеми остальными формами жизни." }, { 21.33, "Шкура у этого червя просто невероятная." }, { 24.35, "Она такая толстая, что её невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом." }, { 34.94, "Принеси мне шкуру Оуро и ещё ряд компонентов, и я создам для тебя поножи, обладающие огромной силой." } } }, t = { d = 17.9, v = "human-male", n = { x = 209 }, c = { x = { { 0.00, "Да..." }, { 0.38, "Эту шкуру невозможно пробить почти ничем." }, { 3.43, "Если добавить самые прочные куски панцирей киражей, убитых нами по дороге сюда, из неё получится великолепный доспех." }, { 11.83, "Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан'Киража." } } } } },
    [8659] = { d = 19.8, v = "gnome-female", n = { x = 220 }, c = { x = { { 0.00, "У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов." }, { 9.61, "Принеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье ещё более устрашающее, чем крылья самого Нефариана!" } } }, t = { d = 13.2, g = 1, v = "gnome-female", n = { m = 127, f = 127 }, c = { m = { { 0.00, "Я изготовила это наплечье, смертный, из принесённых тобой вещей и панцирей поверженных киражей." }, { 8.11, "Тебя оно защитит, а сердца врагов его вид наполнит ужасом." } }, f = { { 0.00, "Я изготовила это наплечье, смертная, из принесённых тобой вещей и панцирей поверженных киражей." }, { 8.15, "Тебя оно защитит, а сердца врагов его вид наполнит ужасом." } } } } },
    [8660] = { d = 23.8, v = "human-male", n = { x = 276 }, c = { x = { { 0.00, "Древняя киражская магия исполнена небывалой силы." }, { 3.69, "Самые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона." }, { 11.53, "Принеси мне киражские наручники Господства и ещё несколько компонентов, и я создам для тебя потрясающие сапоги." }, { 19.57, "Увидишь, насколько они окажутся полезны в схватке с врагом." } } } },
    [8661] = { d = 43.1, v = "nightelf-female", n = { x = 489 }, c = { x = { { 0.00, "Древний Бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан'Кираже." }, { 6.83, "Ужасная судьба, которая ждёт Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет." }, { 14.96, "Для существа, обладающего подобной мощью, время не имеет значения." }, { 19.73, "Встанут звёзды подходящим образом – и ярость его обрушится на живущих, подобно плети." }, { 25.86, "Тебе следует найти его и положить конец его существованию, пока он не пробудился." }, { 31.79, "Когда ты сделаешь это, принеси мне кусок его панциря." }, { 35.72, "Взамен я дам тебе броню, подобной которой не владел ещё никто из смертных." }, { 41.07, "Броню, достойную убийцы бога." } } } },
