    [8703] = { d = 31.1, g = 1, v = "nightelf-female#51", n = { x = 345 }, c = { m = { { 0.00, "Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности." }, { 6.69, "Однако считается, что если заменить поражённые скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастёт ещё больше." }, { 17.30, "Камни, украшающие киражских идолов, вполне подойдут – они отменного качества." }, { 23.06, "Принеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, герой." } }, f = { { 0.00, "Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности." }, { 6.73, "Однако считается, что если заменить поражённые скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастёт ещё больше." }, { 17.40, "Камни, украшающие киражских идолов, вполне подойдут – они отменного качества." }, { 23.20, "Принеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, героиня." } } } },
    [8704] = { d = 31.2, g = 1, v = "nightelf-female#51", n = { x = 343 }, c = { m = { { 0.00, "Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности." }, { 6.54, "Однако драгоценные камни, вставленные в оправу этих колец, поражены скверной." }, { 12.18, "Я думаю, если их заменить, мощь колец возрастёт ещё сильнее." }, { 16.46, "Заменить их можно на камни, украшающие киражских идолов, они славятся своей чистотой." }, { 22.68, "Принеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, герой." } }, f = { { 0.00, "Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности." }, { 6.72, "Однако драгоценные камни, вставленные в оправу этих колец, поражены скверной." }, { 12.51, "Я думаю, если их заменить, мощь колец возрастёт ещё сильнее." }, { 16.90, "Заменить их можно на камни, украшающие киражских идолов, они славятся своей чистотой." }, { 23.29, "Принеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, героиня." } } } },
    [8705] = { d = 37.6, v = "tauren-male", n = { x = 379 }, c = { x = { { 0.00, "Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов..." }, { 16.77, "При одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них своё собственное искусство." }, { 27.96, "Докажи Кругу Кенария свою преданность, и я создам для тебя могучее оружие из лучших киражских материалов." } } } },
