    [8728] = { d = 31.4, v = "gnome-male", n = { x = 410 }, c = { x = { { 0.00, "Что же, это оказалось дольше, чем я думал." }, { 3.02, "Давай-ка посмотрим, что написано в этой книге." }, { 6.37, "Хорошая новость – я на девяносто девять процентов уверен, что смогу сделать арканитовый буёк, который будет работать согласно вашим требованиям." }, { 17.30, "А вот это полностью зависит от плохих новостей." }, { 20.71, "А плохие новости заключаются в том, что мне понадобится куча арканита, элементиевой руды и редких самоцветов." }, { 28.43, "Принесите мне всё, что надо, и я сделаю буёк." } } }, t = { d = 6.9, v = "gnome-male", n = { x = 70 }, c = { x = { { 0.00, "Уговор есть уговор." }, { 1.52, "Надеюсь, вы знаете, во что лезете." }, { 4.13, "Это вам не жук чихнул – рыбку ловить!" } } } } },
    [8729] = { d = 31.4, v = "gnome-male", n = { x = 374 }, c = { x = { { 0.00, "Я ещё не говорил о плохой новости, нет???" }, { 2.81, "Её зовут Каракула – тридцать метров смерти и разрушения." }, { 6.75, "Наверное, я забыл об этой мелочи." }, { 9.13, "Моё сверхпсихопсионическое ясновидение говорит мне, что лучше всего будет закинуть буёк с берега Азшары, в Штормовую бухту." }, { 17.56, "Высматривайте водоворот, в котором скорее всего будет до кучи обломков кораблей." }, { 23.19, "Кстати, надеюсь, не в одиночку пойдёте?" }, { 25.88, "Если вам каким-то чудесным образом повезёт, отнесите обломок скипетра Анахроносу." } } }, t = { d = 5.7, v = "creature/anachronos", n = { x = 47 }, c = { x = { { 0.00, "Славно." }, { 0.82, "Скоро я сумею воссоздать скипетр Зыбучих Песков." } } } } },
    [8730] = { d = 29.3, g = 1, v = "creature/dragon", n = { m = 238, f = 240 }, c = { m = { { 0.00, "Это ты, герой?" }, { 1.52, "Тысячу лет назад мне поручили хранить осколок, и вот, в мой самый чёрный час явился тот, кто избавит меня от него..." }, { 12.86, "Но какая же трагедия без жестокости?" }, { 16.43, "Ос... осколок скипетра ныне у Нефариуса." }, { 21.87, "Время дорого, ибо Нефариус намерен уничтожить осколок." }, { 27.41, "Поторопись!" } }, f = { { 0.00, "Это ты, героиня?" }, { 1.74, "Тысячу лет назад мне поручили хранить осколок, и вот, в мой самый чёрный час явилась та, кто избавит меня от него..." }, { 13.35, "Но какая же трагедия без жестокости?" }, { 17.01, "Ос... осколок скипетра ныне у Нефариуса." }, { 22.59, "Время дорого, ибо Нефариус намерен уничтожить осколок." }, { 28.26, "Поторопись!" } } }, t = { d = 21.1, g = 1, v = "creature/anachronos", n = { m = 191, f = 193 }, c = { m = { { 0.00, "Душа Валестраза ныне спокойна, герой." }, { 3.23, "Все Аспекты следят за твоими успехами с великим интересом." }, { 8.11, "Знай – у тебя могучие союзники." }, { 10.74, "Мне было приказано даровать тебе нечто, способное помочь тебе в твоей борьбе." }, { 17.36, "Воспользуйся этим во благо..." } }, f = { { 0.00, "Душа Валестраза ныне спокойна, героиня." }, { 3.60, "Все Аспекты следят за твоими успехами с великим интересом." }, { 8.80, "Знай – у тебя могучие союзники." }, { 11.60, "Мне было приказано даровать тебе нечто, способное помочь тебе в твоей борьбе." }, { 18.64, "Воспользуйся этим во благо..." } } } } },
    [8731] = { d = 31.9, v = "nightelf-male#55", n = { x = 391 }, c = { x = { { 0.00, "Приветствую тебя." }, { 1.25, "Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные." }, { 7.72, "Легион Оргриммара под предводительством капитана Крушителя Черепов расквартирован рядом с Ульем Регал." }, { 14.81, "Поговори с капитаном и принеси мне доказательство выполнения его указаний." }, { 19.95, "Тем временем я подготовлю для тебя новое задание." }, { 23.40, "Ах да, сделай одолжение, держись подальше от дружины Стальгорна." }, { 27.86, "Добровольцы Орды и Альянса постоянно грызутся друг с другом." } } }, t = { d = 21.0, g = 1, v = "nightelf-male#55", n = { x = 221 }, c = { m = { { 0.00, "Сразу видно, что Круг немного внимания уделяет писанине." }, { 4.19, "Он подписал эти бумаги кровью силитидов!" }, { 7.24, "Хорошо." }, { 7.84, "Я подготовил для тебя задания, которые наилучшим образом используют твои способности, герой." }, { 14.69, "Если ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!" } }, f = { { 0.00, "Сразу видно, что Круг немного внимания уделяет писанине." }, { 4.31, "Он подписал эти бумаги кровью силитидов!" }, { 7.45, "Хорошо." }, { 8.07, "Я подготовил для тебя задания, которые наилучшим образом используют твои способности, героиня." }, { 15.24, "Если ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!" } } } } },
    [8732] = { t = { d = 12.7, v = "orc-male", n = { x = 131 }, c = { x = { { 0.00, "Да, пожалуй, по нынешним временам такая стычка сойдёт за службу в поле." }, { 5.68, "Отнеси эти бумаги в крепость Кенария, там тебе наверняка подыщут тёплое местечко." }, { 12.22, "Ступай!" } } } } },
    [8733] = { d = 32.2, g = 1, v = "creature/malfurion", n = { m = 310, f = 312 }, c = { m = { { 0.00, "Это путь искупления, герой." }, { 2.27, "Если я сегодня погибну, то паду я за правое дело." }, { 6.38, "Верни осколок зелёного скипетра." }, { 9.02, "Освободи Эраникуса от порчи, которой поразили его Древние боги." }, { 14.31, "Отправляйся в Дарнасс." }, { 16.14, "Прямо у стен города ты встретишь одного из моих агентов." }, { 20.76, "Он даст ход нашим делам и оповестит Тиранду о наших планах так, чтобы не прознал Олений Шлем." }, { 28.32, "Падение, что готовилось тысячу лет..." } }, f = { { 0.00, "Это путь искупления, героиня." }, { 2.44, "Если я сегодня погибну, то паду я за правое дело." }, { 6.58, "Верни осколок зелёного скипетра." }, { 9.24, "Освободи Эраникуса от порчи, которой поразили его Древние боги." }, { 14.57, "Отправляйся в Дарнасс." }, { 16.42, "Прямо у стен города ты встретишь одного из моих агентов." }, { 21.07, "Он даст ход нашим делам и оповестит Тиранду о наших планах так, чтобы не прознал Олений Шлем." }, { 28.69, "Падение, что готовилось тысячу лет..." } } }, t = { d = 8.3, v = "narrator", n = { x = 74 }, c = { x = { { 0.00, "Огонёк молчит, только иногда тихо жужжит." }, { 3.91, "Странно, но он способен общаться с вами мысленно." } } } } },
    [8734] = { d = 22.5, g = 1, v = "skyborne-female", n = { m = 233, f = 233 }, c = { m = { { 0.00, "Тиранда будет извещена, смертный." }, { 2.65, "Шан'до Ярость Бури подготовил меня к неожиданностям." }, { 6.76, "Теперь тебе надлежит отправиться в Лунную поляну и поговорить с хранителем Ремулосом." }, { 13.38, "Он даст тебе дальнейшие инструкции по поводу того, как вызвать Эраникуса." }, { 18.44, "Мы все желаем тебе великой удачи." } }, f = { { 0.00, "Тиранда будет извещена, смертная." }, { 2.66, "Шан'до Ярость Бури подготовил меня к неожиданностям." }, { 6.78, "Теперь тебе надлежит отправиться в Лунную поляну и поговорить с хранителем Ремулосом." }, { 13.43, "Он даст тебе дальнейшие инструкции по поводу того, как вызвать Эраникуса." }, { 18.50, "Мы все желаем тебе великой удачи." } } }, t = { d = 27.6, v = "creature/remulos", n = { x = 271 }, c = { x = { { 0.00, "Невозможно будет выманить Эраникуса из Сна, если он того не пожелает." }, { 5.86, "Однако, его намерения заставят его прийти в наш мир." }, { 10.34, "Он жаждет уничтожить живое проявление Малфуриона." }, { 14.52, "Если мы добьёмся успеха, это может погубить одного из самых могучих союзников Сна." }, { 21.52, "Кошмар полностью поглотит всё, что ещё сохранилось, если Малфурион падёт..." } } } } },
    [8735] = { d = 15.6, v = "creature/remulos", n = { x = 164 }, c = { x = { { 0.00, "Тебе нужно отправиться к четырём порталам сна Азерота." }, { 4.34, "Из каждого ты добудешь фрагмент порчи Кошмара." }, { 8.09, "Дракониды, населяющие те места, не будут их отдавать." }, { 12.36, "Возвращайся, когда добудешь все фрагменты." } } }, t = { d = 12.9, g = 1, v = "creature/remulos", n = { m = 109, f = 110 }, c = { m = { { 0.00, "Готов ли ты?" }, { 1.16, "Готов ли мир встретить то, что мы собираемся призвать?" }, { 6.06, "Я не знаю..." }, { 7.23, "У меня есть долг перед Малфурионом." }, { 10.47, "Я связан долгом и честью..." } }, f = { { 0.00, "Готова ли ты?" }, { 1.21, "Готов ли мир встретить то, что мы собираемся призвать?" }, { 5.96, "Я не знаю..." }, { 7.08, "У меня есть долг перед Малфурионом." }, { 10.28, "Я связан долгом и честью..." } } } } },
    [8736] = { d = 21.9, v = "creature/remulos", n = { x = 211 }, c = { x = { { 0.00, "Мы должны сдерживать себя в бою с Эраникусом." }, { 3.86, "Наша цель – спасти его, а не уничтожить." }, { 7.26, "Тиранда уже идёт нам на помощь." }, { 9.90, "Мы должны отбить удары дракона и спасти Ночную гавань от неминуемого уничтожения." }, { 16.78, "Стой на страже!" }, { 18.07, "Ты и твои союзники – наша единственная надежда." } } }, t = { d = 20.4, v = "creature/remulos", n = { x = 191 }, c = { x = { { 0.00, "Он пришёл в себя." }, { 1.49, "Ныне он возвращается в Сон, дабы исправить тот вред, что причинил." }, { 7.14, "Эраникус станет могучим союзником Малфуриону и моему отцу." }, { 12.32, "Прими эти доспехи, они подарены мне самой Изерой." }, { 16.79, "Они пригодятся тебе в сражении с киражами." } } } } },
    [8737] = { d = 26.3, v = "narrator", n = { x = 302 }, c = { x = { { 0.00, "Сумеречный Молот и повелители стихий, которым поклоняются культисты, представляют серьёзную опасность для деятельности Круга в Силитусе." }, { 9.96, "Учитывая, что у нас появились новые враги – в Ан'Кираже, мы не должны терять бдительность и давать волю внешним врагам." }, { 18.78, "Отыщи способ вызвать и уничтожить лазурного храмовника и доложи о выполнении задания Бору Буйногривому." } } }, t = { d = 4.4, v = "tauren-male", n = { x = 33 }, c = { x = { { 0.00, "Отличная работа." }, { 1.98, "Вот следующее задание." } } } } },
    [8738] = { d = 17.6, v = "narrator", n = { x = 205 }, c = { x = { { 0.00, "Мы отправили наших лучших разведчиков к ульям силитидов." }, { 4.17, "Разведчик Ландион уже несколько дней наблюдает за передвижениями этих насекомых." }, { 10.07, "Найди его и забери у него письменный отчёт." }, { 13.31, "Нам необходимо как можно скорее получить собранные сведения." } } }, t = { d = 9.0, v = "tauren-female#71", n = { x = 93 }, c = { x = { { 0.00, "Мы очень ценим твои усилия." }, { 2.35, "Я немедленно займусь этими донесениями, а ты можешь переходить к следующему заданию." } } } } },
    [8739] = { d = 17.8, v = "narrator", n = { x = 202 }, c = { x = { { 0.00, "Мы отправили наших лучших разведчиков к ульям силитидов." }, { 4.29, "Разведчик Джалия уже несколько дней наблюдает за передвижениями этих насекомых." }, { 10.28, "Найди её и забери у неё письменный отчёт." }, { 13.35, "Нам необходимо как можно скорее получить собранные сведения." } } }, t = { d = 8.9, v = "tauren-female#71", n = { x = 91 }, c = { x = { { 0.00, "Мы очень ценим твои усилия." }, { 2.35, "Я немедленно займусь этим донесением, а ты можешь переходить к следующему заданию." } } } } },
    [8740] = { d = 25.0, v = "narrator", n = { x = 262 }, c = { x = { { 0.00, "В последнее время появились верховые отряды сторонников Сумеречного Молота." }, { 6.10, "Они не суются в земли, охраняемые крепостью Кенария, а грабят небольшие караваны и отряды." }, { 13.43, "Найди и убей сумеречных мародёров, а заодно и их лидера, воительницу по имени Морна." }, { 20.18, "О выполнении задания доложи призывательнице ветров Гордый Рог." } } }, t = { d = 11.0, v = "tauren-female#71", n = { x = 105 }, c = { x = { { 0.00, "Молодец." }, { 0.81, "Сумеречные мародёры причинили нам множество неприятностей." }, { 5.93, "Мириться с ними было нельзя." }, { 8.60, "Вот тебе следующее задание." } } } } },
    [8741] = { d = 8.2, v = "creature/remulos", n = { x = 87 }, c = { x = { { 0.00, "Хранитель ждёт твоего возвращения." }, { 2.82, "Отнеси этот осколок зелёного скипетра Анахроносу в Пещеры Времени." } } }, t = { d = 14.2, g = 1, v = "creature/anachronos", n = { m = 131, f = 133 }, c = { m = { { 0.00, "Твои деяния станут всем известны, герой." }, { 3.72, "Тебя будут славить в песнях от Оргриммара до дальних пределов Южных морей." }, { 10.44, "Все узнают о поборнике Бронзовых драконов." } }, f = { { 0.00, "Твои деяния станут всем известны, героиня." }, { 3.88, "Тебя будут славить в песнях от Оргриммара до дальних пределов Южных морей." }, { 10.60, "Все узнают о поборнице Бронзовых драконов." } } } } },
    [8742] = { t = { d = 31.1, g = 1, v = "creature/anachronos", n = { m = 266, f = 267 }, c = { m = { { 0.00, "Прошла тысяча лет, и, как было предначертано, предо мной стоит тот, кто поведёт свой народ в новую эпоху." }, { 9.50, "Древний бог трепещет." }, { 11.48, "О да, он боится твоей веры." }, { 14.04, "Разрушь пророчество К'Туна." }, { 16.60, "Он знает, что ты идёшь, защитник – а с тобой идёт вся мощь Калимдора." }, { 22.71, "Тебе нужно лишь сказать мне, когда будешь готов, и я вручу тебе Скипетр Зыбучих Песков." } }, f = { { 0.00, "Прошла тысяча лет, и, как было предначертано, предо мной стоит та, кто поведёт свой народ в новую эпоху." }, { 9.51, "Древний бог трепещет." }, { 11.51, "О да, он боится твоей веры." }, { 14.10, "Разрушь пророчество К'Туна." }, { 16.68, "Он знает, что ты идёшь, защитница – а с тобой идёт вся мощь Калимдора." }, { 22.94, "Тебе нужно лишь сказать мне, когда будешь готова, и я вручу тебе Скипетр Зыбучих Песков." } } } } },
    [8743] = { t = { d = 7.6, v = "narrator", n = { x = 75 }, c = { x = { { 0.00, "Из земли рядом с гонгом торчит особенный кристалл." }, { 4.33, "Возможно, это подарок племени Ноздорму." } } } } },
    [8744] = { t = { d = 9.8, g = 1, v = "narrator", n = { x = 85 }, c = { m = { { 0.00, "На бирке этого подарка написано:" }, { 2.91, "«Кому: путник." }, { 4.17, "Пусть праздник Зимнего Покрова будет для тебя весёлым и светлым!»" } }, f = { { 0.00, "На бирке этого подарка написано:" }, { 2.91, "«Кому: путница." }, { 4.25, "Пусть праздник Зимнего Покрова будет для тебя весёлым и светлым!»" } } } } },
    [8745] = { t = { d = 17.3, g = 1, v = "human-male", n = { m = 203, f = 204 }, c = { m = { { 0.00, "Приветствую, защитник." }, { 1.59, "Я Джонатан, хранитель священного гонга и вечный страж бронзовых драконов." }, { 6.74, "Сам Вневременной наделил меня правом вручить тебе предмет на твой выбор из его вневременной сокровищницы." }, { 14.18, "Пусть он поможет тебе в битвах с К'Туном." } }, f = { { 0.00, "Приветствую, защитница." }, { 1.63, "Я Джонатан, хранитель священного гонга и вечный страж бронзовых драконов." }, { 6.71, "Сам Вневременной наделил меня правом вручить тебе предмет на твой выбор из его вневременной сокровищницы." }, { 14.06, "Пусть он поможет тебе в битвах с К'Туном." } } } } },
    [8746] = { d = 35.1, v = "goblin-male#110", n = { x = 395 }, c = { x = { { 0.00, "БЕДА!" }, { 0.45, "Похищен Метцен – северный олень!" }, { 2.82, "Метцен – один из восьми оленей Дедушки Зимы и собственность \"Пастбищ Дымного Леса\"." }, { 8.85, "Мы получили целых ДВА письма с требованием выкупа от двух шаек, каждая из которых утверждает, что олень у них." }, { 16.61, "Праздники в разгаре, мы не можем бросить дела!" }, { 19.94, "Пожалуйста, найди Метцена и верни его нам!" }, { 23.02, "Возьми эти письма с требованием выкупа – может, найдёшь в них подсказку." }, { 28.15, "Когда найдёшь, посыпь северного оленя вот этой пылью, и он освободится от любых пут!" }, { 34.11, "Прошу, поспеши!" } } }, t = { d = 34.6, g = 1, v = "goblin-male#110", n = { m = 364, f = 366 }, c = { m = { { 0.00, "Ур-ра!" }, { 0.55, "Получилось!" }, { 1.43, "Метцен буквально только что прилетел обратно в свои стойла!" }, { 6.00, "Да-да, конечно же, Метцен умеет летать." }, { 9.07, "Пыль сработала отлично!" }, { 10.85, "Я так и знал!" }, { 11.80, "Ты буквально спас нас – и не только праздник Зимнего Покрова, но и сами \"Пастбища Дымного Леса\"!" }, { 19.03, "Спасибо тебе." }, { 20.12, "Послушай..." }, { 21.01, "За свои труды ты заслуживаешь награды." }, { 23.94, "Вот, держи." }, { 24.83, "Это не просто приправа." }, { 26.67, "Если когда-нибудь у тебя будет верховое животное, эта штука тебе пригодится." }, { 32.61, "Счастливого Зимнего Покрова!" } }, f = { { 0.00, "Ур-ра!" }, { 0.53, "Получилось!" }, { 1.40, "Метцен буквально только что прилетел обратно в свои стойла!" }, { 5.86, "Да-да, конечно же, Метцен умеет летать." }, { 8.85, "Пыль сработала отлично!" }, { 10.58, "Я так и знал!" }, { 11.52, "Ты буквально спасла нас – и не только праздник Зимнего Покрова, но и сами \"Пастбища Дымного Леса\"!" }, { 18.77, "Спасибо тебе." }, { 19.84, "Послушай..." }, { 20.70, "За свои труды ты заслуживаешь награды." }, { 23.56, "Вот, держи." }, { 24.43, "Это не просто приправа." }, { 26.23, "Если когда-нибудь у тебя будет верховое животное, эта штука тебе пригодится." }, { 32.02, "Счастливого Зимнего Покрова!" } } } } },
    [8747] = { t = { d = 21.1, g = 1, v = "creature/anachronos", n = { m = 220, f = 223 }, c = { m = { { 0.00, "Впечатляет, малыш." }, { 1.54, "Ты приложил немало усилий, чтобы заслужить расположение бронзовых драконов." }, { 7.70, "Твоя преданность не осталась незамеченной." }, { 11.15, "Печатка защитника даст тебе превосходную защиту от сил зла." }, { 15.92, "Но знай: когда ты выберешь свой путь, передумать будет уже нельзя." } }, f = { { 0.00, "Впечатляет, малышка." }, { 1.66, "Ты приложила немало усилий, чтобы заслужить расположение бронзовых драконов." }, { 7.78, "Твоя преданность не осталась незамеченной." }, { 11.17, "Печатка защитника даст тебе превосходную защиту от сил зла." }, { 15.85, "Но знай: когда ты выберешь свой путь, передумать будет уже нельзя." } } } } },
