    [8757] = { t = { d = 23.1, g = 1, v = "creature/anachronos", n = { m = 240, f = 243 }, c = { m = { { 0.00, "Впечатляет, малыш." }, { 1.56, "Ты приложил немало усилий, чтобы заслужить расположение бронзовых драконов." }, { 7.81, "Твоя преданность не осталась незамеченной." }, { 11.30, "Печатка заклинателя значительно усилит твои магические и природные способности." }, { 17.85, "Но знай: когда ты выберешь свой путь, передумать будет уже нельзя." } }, f = { { 0.00, "Впечатляет, малышка." }, { 1.68, "Ты приложила немало усилий, чтобы заслужить расположение бронзовых драконов." }, { 7.90, "Твоя преданность не осталась незамеченной." }, { 11.34, "Печатка заклинателя значительно усилит твои магические и природные способности." }, { 17.77, "Но знай: когда ты выберешь свой путь, передумать будет уже нельзя." } } } } },
