    [8762] = { d = 35.0, v = "goblin-male#110", n = { x = 386 }, c = { x = { { 0.00, "БЕДА!" }, { 0.46, "Похищен Метцен-северный олень!" }, { 2.67, "Метцен – один из восьми оленей Дедушки Зимы и принадлежит Пастбищам Дымного Леса." }, { 8.66, "Мы получили не одно, а ДВА письма с требованием выкупа от двух шаек, каждая из которых утверждает, что олень у них." }, { 16.87, "Праздники в разгаре, мы не можем бросить дела!" }, { 20.26, "Пожалуйста, найди Метцена и верни его нам!" }, { 23.38, "Возьми эти письма с требованием выкупа, – может, найдёшь в них подсказку, – а вот этой пылью посыпь северного оленя, и он освободится от любых пут!" }, { 33.93, "Прошу, поспеши!" } } }, t = { d = 32.4, g = 1, v = "goblin-male#110", n = { m = 329, f = 332 }, c = { m = { { 0.00, "Ты это сделал!" }, { 1.17, "Ура-а-а!" }, { 1.86, "Метцен совсем недавно прилетел обратно в свои стойла – да-да, Метцен умеет летать!" }, { 8.34, "Эта пыль сработала чудодейственно, я так и знал!" }, { 11.92, "Ты спас не только праздник Зимнего Покрова, но и Пастбища Дымного Леса!" }, { 17.37, "Спасибо тебе." }, { 18.47, "Слушай... за твои великие дела хочу дать тебе вот это." }, { 22.74, "Это нечто ОСОБЕННОЕ – если ты заведёшь себе верховое животное, эта штука тебе пригодится." }, { 29.70, "Счастливого Зимнего Покрова!" } }, f = { { 0.00, "Ты это сделала!" }, { 1.25, "Ура-а-а!" }, { 1.95, "Метцен совсем недавно прилетел обратно в свои стойла – да-да, Метцен умеет летать!" }, { 8.50, "Эта пыль сработала чудодейственно, я так и знал!" }, { 12.13, "Ты спасла не только праздник Зимнего Покрова, но и Пастбища Дымного Леса!" }, { 17.84, "Спасибо тебе." }, { 18.96, "Слушай... за твои великие дела хочу дать тебе вот это." }, { 23.28, "Это нечто ОСОБЕННОЕ – если ты заведёшь себе верховое животное, эта штука тебе пригодится." }, { 30.32, "Счастливого Зимнего Покрова!" } } } } },
    [8763] = { d = 40.3, g = 1, v = "goblin-male#110", n = { m = 435, f = 437 }, c = { m = { { 0.00, "Слушай..." }, { 0.71, "Я вообще-то не должен тебе этого говорить, но раз уж ты у нас сегодня герой и всё такое..." }, { 7.07, "В эту пору везде полно остролиста, но он быстро вянет." }, { 11.05, "Мы получили машину для заготовки остролиста – и он не портится!" }, { 15.48, "Мы его используем, чтобы придать вкус празднику... и ради прибыли – летом!" }, { 20.81, "Я позволю тебе попользоваться этой машинкой, но только если ты мастер-кулинар." }, { 26.47, "От тебя потребуется некоторое количество глубокоскальной соли и два-три, ну, скажем, пять золотых." }, { 33.40, "И получишь славную партию остролиста, которую можно хранить сколько угодно." } }, f = { { 0.00, "Слушай..." }, { 0.73, "Я вообще-то не должен тебе этого говорить, но раз уж ты у нас сегодня героиня и всё такое..." }, { 7.47, "В эту пору везде полно остролиста, но он быстро вянет." }, { 11.60, "Мы получили машину для заготовки остролиста – и он не портится!" }, { 16.20, "Мы его используем, чтобы придать вкус празднику... и ради прибыли – летом!" }, { 21.73, "Я позволю тебе попользоваться этой машинкой, но только если ты мастер-кулинар." }, { 27.60, "От тебя потребуется некоторое количество глубокоскальной соли и два-три, ну, скажем, пять золотых." }, { 34.80, "И получишь славную партию остролиста, которую можно хранить сколько угодно." } } }, t = { d = 15.8, v = "narrator", n = { x = 157 }, c = { x = { { 0.00, "Машина при начале работы тихонько гудит и выпускает облачко пара." }, { 5.58, "Вскоре она останавливается, и из неё выходит ещё одна струйка пара." }, { 11.24, "Дверца открывается, а за ней – партия сушёного остролиста!" } } } } },
    [8764] = { t = { d = 5.6, v = "creature/anachronos", n = { x = 49 }, c = { x = { { 0.00, "Всего хорошего." }, { 1.50, "Если передумаешь, я буду здесь и помогу тебе." } } } } },
    [8765] = { t = { d = 5.7, v = "creature/anachronos", n = { x = 49 }, c = { x = { { 0.00, "Всего хорошего." }, { 1.52, "Если передумаешь, я буду здесь и помогу тебе." } } } } },
    [8766] = { t = { d = 5.6, v = "creature/anachronos", n = { x = 49 }, c = { x = { { 0.00, "Всего хорошего." }, { 1.50, "Если передумаешь, я буду здесь и помогу тебе." } } } } },
    [8767] = { t = { d = 9.1, g = 1, v = "narrator", n = { m = 67, f = 67 }, c = { m = { { 0.00, "Похоже, этот подарок уже не раз трясли." }, { 3.70, "На бирке написано:" }, { 5.42, "«Для тебя, самый особенный путник-герой»." } }, f = { { 0.00, "Похоже, этот подарок уже не раз трясли." }, { 3.63, "На бирке написано:" }, { 5.33, "«Для тебя, самая особенная путница-героиня»." } } } } },
    [8768] = { t = { d = 8.1, v = "narrator", n = { x = 77 }, c = { x = { { 0.00, "На этом празднично упакованном подарке написано твоё имя." }, { 5.12, "Постой, он что, сейчас шевельнулся?" } } } } },
    [8769] = { t = { d = 6.2, v = "narrator", n = { x = 63 }, c = { x = { { 0.00, "Весёлого праздника Зимнего Покрова от твоих друзей с Пастбищ Дымного Леса." } } } } },
    [8770] = { d = 19.0, v = "narrator", n = { x = 204 }, c = { x = { { 0.00, "По мере нарастания конфликта, силитиды представляют всё большую опасность для наших операций." }, { 7.24, "Тебя избрали для участия в нападении на Улей Аши." }, { 11.17, "Твоей основной целью будут защитники из этого улья." }, { 15.32, "Выполнив задание, отчитайся командиру Мар'алиту." } } }, t = { d = 4.0, v = "nightelf-male#54", n = { x = 36 }, c = { x = { { 0.00, "Отличная работа." }, { 1.58, "Мы не забудем твоих усилий." } } } } },
    [8771] = { d = 18.4, v = "narrator", n = { x = 204 }, c = { x = { { 0.00, "По мере нарастания конфликта, силитиды представляют всё большую опасность для наших операций." }, { 7.02, "Тебя избрали для участия в нападении на Улей Аши." }, { 10.84, "Твоей основной целью будут пескоходы из этого улья." }, { 14.87, "Выполнив задание, отчитайся командиру Мар'алиту." } } }, t = { d = 6.7, v = "nightelf-male#54", n = { x = 65 }, c = { x = { { 0.00, "Отличная работа." }, { 1.49, "Твои подвиги в сражении при Улье Аши не прошли незамеченными." } } } } },
    [8772] = { d = 12.0, v = "narrator", n = { x = 123 }, c = { x = { { 0.00, "Мы вызвали подкрепление для сражения у Улья Зора." }, { 3.98, "Твоя задача – убить как можно больше стражей дорог." }, { 8.25, "Выполнив задание, отчитайся командиру Мар'алиту." } } }, t = { d = 6.6, v = "nightelf-male#54", n = { x = 66 }, c = { x = { { 0.00, "Отличная работа." }, { 1.45, "Твои подвиги в сражении при Улье Зора не прошли незамеченными." } } } } },
    [8773] = { d = 12.0, v = "narrator", n = { x = 123 }, c = { x = { { 0.00, "Мы вызвали подкрепление для сражения у Улья Зора." }, { 4.03, "Твоя задача – убить как можно больше разрушителей." }, { 8.20, "Выполнив задание, отчитайся командиру Мар'алиту." } } }, t = { d = 9.1, v = "nightelf-male#54", n = { x = 93 }, c = { x = { { 0.00, "Я слышал немало добрых слов о твоём участии в нападении на Улей Зора." }, { 5.45, "Продолжай в том же духе, и победа будет за нами." } } } } },
    [8774] = { d = 18.8, v = "narrator", n = { x = 207 }, c = { x = { { 0.00, "По мере нарастания конфликта, силитиды представляют всё большую опасность для наших операций." }, { 7.10, "Тебя избрали для участия в нападении на Улей Регал." }, { 11.09, "Твоей основной целью будут стерегущие из этого улья." }, { 15.23, "Выполнив задание, отчитайся командиру Мар'алиту." } } }, t = { d = 6.6, v = "nightelf-male#54", n = { x = 67 }, c = { x = { { 0.00, "Отличная работа." }, { 1.43, "Твои подвиги в сражении при Улье Регал не прошли незамеченными." } } } } },
    [8775] = { d = 19.0, v = "narrator", n = { x = 202 }, c = { x = { { 0.00, "По мере нарастания конфликта, силитиды представляют всё большую опасность для наших операций." }, { 7.32, "Тебя избрали для участия в нападении на Улей Регал." }, { 11.44, "Твоей основной целью будут злюки из этого улья." }, { 15.35, "Выполнив задание, отчитайся командиру Мар'алиту." } } }, t = { d = 6.6, v = "nightelf-male#54", n = { x = 67 }, c = { x = { { 0.00, "Отличная работа." }, { 1.42, "Твои подвиги в сражении при Улье Регал не прошли незамеченными." } } } } },
    [8776] = { d = 18.4, v = "narrator", n = { x = 209 }, c = { x = { { 0.00, "По мере нарастания конфликта, силитиды представляют всё большую опасность для наших операций." }, { 6.90, "Тебя избрали для участия в нападении на Улей Регал." }, { 10.78, "Твоей основной целью будут поработители из этого улья." }, { 14.93, "Выполнив задание, отчитайся командиру Мар'алиту." } } }, t = { d = 6.7, v = "nightelf-male#54", n = { x = 67 }, c = { x = { { 0.00, "Отличная работа." }, { 1.45, "Твои подвиги в сражении при Улье Регал не прошли незамеченными." } } } } },
    [8777] = { d = 18.6, v = "narrator", n = { x = 205 }, c = { x = { { 0.00, "По мере нарастания конфликта, силитиды представляют всё большую опасность для наших операций." }, { 7.09, "Тебя избрали для участия в нападении на Улей Регал." }, { 11.08, "Твоей основной целью будут землерои из этого улья." }, { 15.07, "Выполнив задание, отчитайся командиру Мар'алиту." } } }, t = { d = 6.6, v = "nightelf-male#54", n = { x = 67 }, c = { x = { { 0.00, "Отличная работа." }, { 1.43, "Твои подвиги в сражении при Улье Регал не прошли незамеченными." } } } } },
    [8778] = { d = 13.4, v = "narrator", n = { x = 130 }, c = { x = { { 0.00, "Дружина Стальгорна прислала необычный запрос – на весьма... э-э-э... неустойчивые вещества." }, { 7.67, "Собери их и принеси господину Пружине Форсунки из дружины Стальгорна." } } }, t = { d = 4.6, v = "gnome-male", n = { x = 36 }, c = { x = { { 0.00, "Ах, да!" }, { 0.74, "Они очень пригодятся!" }, { 3.05, "Большое спасибо!" } } } } },
    [8779] = { d = 16.7, v = "narrator", n = { x = 185 }, c = { x = { { 0.00, "Исследования геолога Злая Шутка имели огромное значение для нашей деятельности в Силитусе." }, { 7.07, "Недавно она запросила материалы для гадания." }, { 10.57, "Пожалуйста, собери всё необходимое и отнеси ей." }, { 14.21, "Пусть она продолжает исследования." } } }, t = { d = 8.6, g = 1, v = "dwarf-female#34", n = { m = 68, f = 70 }, c = { m = { { 0.00, "О да..." }, { 0.71, "Ты мне очень помог!" }, { 2.68, "Достать эти материалы в пустыне невероятно сложно." }, { 7.76, "Спасибо." } }, f = { { 0.00, "О да..." }, { 0.71, "Ты мне очень помогла!" }, { 2.82, "Достать эти материалы в пустыне невероятно сложно." }, { 7.85, "Спасибо." } } } } },
    [8780] = { d = 12.2, v = "narrator", n = { x = 145 }, c = { x = { { 0.00, "У дружины Стальгорна на исходе запасы комплектов брони." }, { 3.96, "Добудь партию таких комплектов и отнеси их Джанеле Твердомолот на заставу дружины Стальгорна, что рядом с Ульем Зора." } } }, t = { d = 3.0, v = "dwarf-female#33", n = { x = 29 }, c = { x = { { 0.00, "Спасибо, я передам их нашим ребятам." } } } } },
    [8781] = { d = 16.7, v = "narrator", n = { x = 184 }, c = { x = { { 0.00, "Дружина Стальгорна оказалась чрезвычайно полезным союзником в наших битвах в Силитусе." }, { 6.64, "К сожалению, по пути они растеряли много припасов и оборудования." }, { 11.68, "Добудь партию оружия и доставь её Джанеле Твердомолот к Улью Зора." } } }, t = { d = 5.6, v = "dwarf-female#33", n = { x = 57 }, c = { x = { { 0.00, "Отлично!" }, { 0.76, "Мне не придётся выслушивать жалобы на тупые клинки." }, { 5.00, "Спасибо." } } } } },
    [8782] = { d = 9.6, v = "narrator", n = { x = 112 }, c = { x = { { 0.00, "У нас такой приток добровольцев, что не хватает формы." }, { 3.92, "Принеси материалы для пошива формы и отдай их призывательнице ветров Гордый Рог." } } }, t = { d = 6.3, v = "tauren-female#71", n = { x = 43 }, c = { x = { { 0.00, "А, да, нам их очень не хватало." }, { 3.51, "Спасибо за добрую службу." } } } } },
    [8783] = { d = 16.5, v = "narrator", n = { x = 188 }, c = { x = { { 0.00, "Варгус, кузнец крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат." }, { 8.89, "Добудь всё необходимое и отнеси их Варгусу в крепость Кенария, чтобы он снабдил войска всем необходимым." } } }, t = { d = 4.3, v = "tauren-male", n = { x = 32 }, c = { x = { { 0.00, "Да-да." }, { 0.82, "Превосходные материалы." }, { 3.48, "Спасибо." } } } } },
    [8784] = { d = 11.2, v = "narrator", n = { x = 127 }, c = { x = { { 0.00, "Вам удалось обнаружить древний киражский артефакт!" }, { 3.74, "Возможно, один из драконов, стоящих в храме недалеко от входа, сможет найти применение этой реликвии." } } }, t = { d = 10.8, v = "gnome-female", n = { x = 103 }, c = { x = { { 0.00, "Какая поразительная находка." }, { 2.64, "Просто изумительная!" }, { 4.53, "Определённо, она поможет нам проникнуть в извращённые умы наших врагов." } } } } },
    [8785] = { d = 16.1, v = "narrator", n = { x = 181 }, c = { x = { { 0.00, "Легион Оргриммара послал запрос на несколько необычные вещества." }, { 4.79, "Учитывая, как хорошо они проявили себя в Силитусе, мы бы хотели как можно скорее выполнить их просьбу." }, { 12.37, "Собери материалы и отнеси их троллихе по имени Шаи." } } }, t = { d = 10.2, v = "troll-female#75", n = { x = 75 }, c = { x = { { 0.00, "Ах, да." }, { 0.77, "То что нужно!" }, { 2.20, "Из этих веществ я сделаю особое зелье." }, { 6.41, "Оно оч-чень не понравится силитидам!" } } } } },
    [8786] = { d = 11.6, v = "narrator", n = { x = 123 }, c = { x = { { 0.00, "Легион Оргриммара послал запрос на поставку оружия, а его нет на складе!" }, { 5.67, "Добудь необходимое снаряжение и отнеси его Мероку Долгому Шагу к Улью Регал." } } }, t = { d = 4.8, v = "tauren-male", n = { x = 37 }, c = { x = { { 0.00, "Отличная работа." }, { 1.85, "Нам очень не хватало оружия." } } } } },
    [8787] = { d = 17.0, v = "narrator", n = { x = 186 }, c = { x = { { 0.00, "В Силитус, к нам на подмогу, прибыли отважные добровольцы из легиона Оргриммара." }, { 6.03, "По пути они растеряли свои запасы комплектов брони." }, { 10.04, "Добудь партию таких комплектов и отнеси их Мероку Долгому Шагу, в лагерь легиона Оргриммара." } } }, t = { d = 8.1, v = "tauren-male", n = { x = 64 }, c = { x = { { 0.00, "Отлично..." }, { 1.17, "Я раздам все комплекты солдатам." }, { 4.57, "Легион Оргриммара благодарит тебя!" } } } } },
    [8788] = { t = { d = 9.1, g = 1, v = "narrator", n = { m = 67, f = 67 }, c = { m = { { 0.00, "Похоже, этот подарок уже не раз трясли." }, { 3.63, "На бирке написано:" }, { 5.33, "«Для тебя, самый особенный путник-герой»." } }, f = { { 0.00, "Похоже, этот подарок уже не раз трясли." }, { 3.63, "На бирке написано:" }, { 5.33, "«Для тебя, самая особенная путница-героиня»." } } } } },
    [8789] = { d = 33.1, v = "gnome-male", n = { x = 394 }, c = { x = { { 0.00, "Мы не то чтобы просто сидели здесь на протяжении тысячелетий." }, { 4.20, "Мы наблюдали за торжеством этих тварей, пока они пировали и истощали свои ресурсы." }, { 10.02, "Мы слушали, как они строят схемы и планы по уничтожению нашего мира." }, { 14.85, "Мы узнали о предателях в их рядах." }, { 17.23, "У них есть слабости, и теперь мы знаем, как их использовать." }, { 21.30, "Найди и принеси мне их церемониальное оружие." }, { 24.43, "В сочетании с предметами, созданными непостоянством их собственного бога, оно станет силой, с которой придётся считаться любому." } } }, t = { d = 6.8, v = "gnome-male", n = { x = 75 }, c = { x = { { 0.00, "Это оружие, усиленное элементием, одинаково легко пронзит как обычного кираи, так и их бога." } } } } },
    [8790] = { d = 21.7, g = 1, v = "nightelf-female", n = { m = 259, f = 259 }, c = { m = { { 0.00, "Аригос предполагает, что элемент, рождённый в результате столкновения между Древними Богами и их прислужниками, в надлежащих условиях станет для них смертельным." }, { 10.87, "Я имею в виду элементий, смертный." }, { 13.29, "Принеси мне киражские императорские регалии и это вещество-яд, и я смогу создать оружие, обладающее великой силой." } }, f = { { 0.00, "Аригос предполагает, что элемент, рождённый в результате столкновения между Древними Богами и их прислужниками, в надлежащих условиях станет для них смертельным." }, { 11.20, "Я имею в виду элементий, смертная." }, { 13.70, "Принеси мне киражские императорские регалии и это вещество-яд, и я смогу создать оружие, обладающее великой силой." } } } },
    [8791] = { d = 15.3, v = "narrator", n = { x = 166 }, c = { x = { { 0.00, "Смертельная угроза больше не нависает над нами." }, { 3.75, "Безжалостный Оссириан повержен!" }, { 6.23, "Об этой победе должны узнать все жители Калимдора." }, { 10.26, "Отнесите голову Оссириана командиру Мар'алиту в крепость Кенария." } } } },
    [8792] = { d = 32.0, g = 1, v = "tauren-female", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Приветствую, я рада, что ты решил поговорить со мной." }, { 3.84, "Если мы хотим достойно подготовиться к ан'киражской войне, то Орде должны помогать все, кто может." }, { 11.05, "Вот и тебе не след оставаться в стороне." }, { 13.97, "Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться!" }, { 22.04, "Поговори с тем, кто отвечает за заготовки, – с вождём Горчуком." }, { 26.54, "Ну как, что скажешь, герой?" }, { 28.53, "Примешь участие в этом жизненно важном деле?" } }, f = { { 0.00, "Приветствую, я рада, что ты решила поговорить со мной." }, { 3.91, "Если мы хотим достойно подготовиться к ан'киражской войне, то Орде должны помогать все, кто может." }, { 11.14, "Вот и тебе не след оставаться в стороне." }, { 14.05, "Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться!" }, { 22.14, "Поговори с тем, кто отвечает за заготовки, – с вождём Горчуком." }, { 26.64, "Ну как, что скажешь, героиня?" }, { 28.77, "Примешь участие в этом жизненно важном деле?" } } }, t = { d = 24.9, g = 1, v = "orc-male", n = { x = 252 }, c = { m = { { 0.00, "Тром'ка, герой!" }, { 1.26, "Приятно видеть, что так много воинов Орды, как ты, пришли помочь в подготовке к грядущей войне в Ан'Кираже." }, { 9.62, "Наши старания обеспечат нам победу над силитидами и их злобными хозяевами, которые засели в Ан'Кираже." }, { 17.56, "Раз уж ты здесь, поговори со сборщиками и помоги им добыть те материалы, которые тебе по силам." } }, f = { { 0.00, "Тром'ка, героиня!" }, { 1.41, "Приятно видеть, что так много воинов Орды, как ты, пришли помочь в подготовке к грядущей войне в Ан'Кираже." }, { 9.77, "Наши старания обеспечат нам победу над силитидами и их злобными хозяевами, которые засели в Ан'Кираже." }, { 17.72, "Раз уж ты здесь, поговори со сборщиками и помоги им добыть те материалы, которые тебе по силам." } } } } },
    [8793] = { d = 33.4, g = 1, v = "scourge-male", n = { m = 347, f = 348 }, c = { m = { { 0.00, "Приветствую, я рад, что ты решил поговорить со мной." }, { 3.88, "Если мы хотим достойно подготовиться к ан'киражской войне, то Орде должны помогать все, кто может." }, { 11.42, "Вот и тебе не следует оставаться в стороне." }, { 14.75, "Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться!" }, { 23.19, "Поговори с тем, кто отвечает за заготовки, – с вождём Горчуком." }, { 27.90, "Ну как, что скажешь, герой?" }, { 29.98, "Примешь участие в этом жизненно важном деле?" } }, f = { { 0.00, "Приветствую, я рад, что ты решила поговорить со мной." }, { 3.84, "Если мы хотим достойно подготовиться к ан'киражской войне, то Орде должны помогать все, кто может." }, { 11.18, "Вот и тебе не следует оставаться в стороне." }, { 14.41, "Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться!" }, { 22.62, "Поговори с тем, кто отвечает за заготовки, – с вождём Горчуком." }, { 27.20, "Ну как, что скажешь, героиня?" }, { 29.35, "Примешь участие в этом жизненно важном деле?" } } }, t = { d = 27.0, g = 1, v = "orc-male", n = { x = 269 }, c = { m = { { 0.00, "Тром'ка, герой!" }, { 1.27, "Приятно видеть, что так много представителей Орды, как ты, выступают, чтобы оказать свою поддержку в предстоящей Ан'киражской войне." }, { 11.57, "Наши старания гарантируют, что мы победим силитидов и их злых хозяев, скрытых внутри Ан'Киража." }, { 18.97, "Раз уж ты здесь, поговори со сборщиками и помоги им добыть те материалы, которые тебе по силам." } }, f = { { 0.00, "Тром'ка, героиня!" }, { 1.45, "Приятно видеть, что так много представителей Орды, как ты, выступают, чтобы оказать свою поддержку в предстоящей Ан'киражской войне." }, { 12.00, "Наши старания гарантируют, что мы победим силитидов и их злых хозяев, скрытых внутри Ан'Киража." }, { 19.59, "Раз уж ты здесь, поговори со сборщиками и помог