    [8795] = { d = 30.6, g = 1, v = "gnome-male", n = { m = 382, f = 383 }, c = { m = { { 0.00, "Приветствую." }, { 0.84, "Хорошо, что ты решил поговорить со мной." }, { 3.47, "В подготовке к войне в Ан'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый!" }, { 12.01, "Уже назначены ответственные за сбор разнообразных материалов, но без помощи обычных граждан им не справиться!" }, { 19.13, "Если хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за заготовки." }, { 25.52, "Ну как, что скажешь, герой?" }, { 27.31, "Примешь ли ты участие в нашем жизненно важном деле?" } }, f = { { 0.00, "Приветствую." }, { 0.82, "Хорошо, что ты решила поговорить со мной." }, { 3.45, "В подготовке к войне в Ан'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый!" }, { 11.82, "Уже назначены ответственные за сбор разнообразных материалов, но без помощи обычных граждан им не справиться!" }, { 18.78, "Если хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за заготовки." }, { 25.03, "Ну как, что скажешь, героиня?" }, { 26.91, "Примешь ли ты участие в нашем жизненно важном деле?" } } }, t = { d = 25.4, g = 1, v = "dwarf-male", n = { m = 308, f = 310 }, c = { m = { { 0.00, "Приветствую тебя и желаю удачи, юноша!" }, { 2.72, "Как хорошо, что в Альянсе есть люди вроде тебя." }, { 5.99, "Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан'Кираже." }, { 11.80, "Если мы объединим наши усилия, то наверняка сможем выковырять мерзких силитидов из их укрытия." }, { 18.29, "Не стесняйся предложить свою помощь лицам, ответственным за сбор материалов, которые тебе легче раздобыть." } }, f = { { 0.00, "Приветствую тебя и желаю удачи, девушка!" }, { 2.80, "Как хорошо, что в Альянсе есть люди вроде тебя." }, { 6.03, "Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан'Кираже." }, { 11.76, "Если мы объеди