    [8798] = { t = { d = 24.5, g = 1, v = "goblin-female#63", n = { m = 275, f = 277 }, c = { m = { { 0.00, "Слушай!" }, { 0.58, "Знаешь что?!" }, { 1.49, "Ты ведь тоже инженер!" }, { 3.04, "Раз ты помог мне проучить моих друзей, я научу тебя делать собственного механического йети!" }, { 9.63, "Теперь веселье не закончится никогда, и ты сможешь пугать кого захочешь!" }, { 14.87, "Если, конечно, сумеешь раздобыть детали, чтобы его собрать." }, { 19.26, "Ну, что скажешь?" }, { 20.43, "Хочешь узнать секрет изготовления механического йети?" } }, f = { { 0.00, "Слушай!" }, { 0.59, "Знаешь что?!" }, { 1.50, "Ты ведь тоже инженер!" }, { 3.06, "Раз ты помогла мне проучить моих друзей, я научу тебя делать собственного механического йети!" }, { 9.84, "Теперь веселье не закончится никогда, и ты сможешь пугать кого захочешь!" }, { 15.11, "Если, конечно, сумеешь раздобыть детали, чтобы его собрать." }, { 19.54, "Ну, что скажешь?" }, { 20.72, "Хочешь узнать секрет изготовления механического йети?" } } } } },
    [8799] = { d = 39.9, g = 1, v = "goblin-male#110", n = { m = 433, f = 435 }, c = { m = { { 0.00, "Слушай..." }, { 0.72, "Вообще-то тебе об этом знать не полагается, но, раз уж ты герой дня и всё такое…" }, { 6.45, "В это время года повсюду полно свежего остролиста, но он быстро вянет." }, { 11.72, "У нас есть машинка, которая заготовляет остролист таким образом, что он не портится!" }, { 17.78, "Знаешь, почём его можно продать летом?" }, { 20.68, "Я разрешу тебе воспользоваться сушилкой, но только если ты мастер-кулинар." }, { 26.15, "От тебя потребуется некоторое количество глубокоскальной соли и два-три... ну, скажем, пять золотых." }, { 33.39, "И ты получишь славную партию остролиста, которую можно хранить сколько угодно." } }, f = { { 0.00, "Слушай..." }, { 0.74, "Вообще-то тебе об этом знать не полагается, но, раз уж ты героиня дня и всё такое…" }, { 6.71, "В это время года повсюду полно свежего остролиста, но он быстро вянет." }, { 12.08, "У нас есть машинка, которая заготовляет остролист таким образом, что он не портится!" }, { 18.26, "Знаешь, почём его можно продать летом?" }, { 21.21, "Я разрешу тебе воспользоваться сушилкой, но только если ты мастер-кулинар." }, { 26.78, "От тебя потребуется некоторое количество глубокоскальной соли и два-три... ну, скажем, пять золотых." }, { 34.16, "И ты получишь славную партию остролиста, которую можно хранить сколько угодно." } } }, t = { d = 14.9, v = "narrator", n = { x = 146 }, c = { x = { { 0.00, "Машинка издала негромкий рокот, выпустила облачко пара – и работа пошла!" }, { 6.20, "Вскоре она остановилась, выпустив ещё одно облачко пара." }, { 11.03, "Открывается дверка – и вот вам сушёный остролист!" } } } } },
    [8800] = { d = 11.2, v = "nightelf-male#55", n = { x = 126 }, c = { x = { { 0.00, "Выполнив все задания, обратись к Варгусу, кузнецу." }, { 3.74, "Покажи ему все заработанные знаки, и получишь награду, в зависимости от твоей преданности нашему делу." } } }, t = { d = 6.1, v = "tauren-male", n = { x = 50 }, c = { x = { { 0.00, "Тебя прислал Калдон?" }, { 2.08, "Хорошо, посмотрим, чем я могу тебе помочь." } } } } },
    [8801] = { d = 31.8, v = "narrator", n = { x = 302 }, c = { x = { { 0.00, "Стены Ан'Киража содрогаются." }, { 2.49, "Сила зла, более древняя, чем сам этот мир, уничтожена." }, { 7.16, "При одном взгляде на лежащие перед вами мерзкие останки стынет сердце." }, { 13.39, "Даже после смерти К'Тун распространяет вокруг себя ауру зла." }, { 18.76, "Вам удалось совершить невозможное." }, { 21.72, "Вы извлекаете глаз и осторожно укладываете его в сумку." }, { 26.47, "Нужно доставить глаз К'Туна в соседнюю залу и отдать драконам." } } }, t = { d = 13.4, g = 1, v = "nightelf-male", n = { m = 146, f = 145 }, c = { m = { { 0.00, "Мы покинем это место сами, господин, как только убедимся, что таившееся внутри зло полностью уничтожено." }, { 7.95, "Ваши странствия, которые войдут в легенды, близятся к своему завершению." } }, f = { { 0.00, "Мы покинем это место сами, госпожа, как только убедимся, что таившееся внутри зло полностью уничтожено." }, { 7.93, "Ваши странствия, которые войдут в легенды, близятся к своему завершению." } } } } },
    [8802] = { d = 14.4, g = 1, v = "nightelf-male", n = { m = 144, f = 143 }, c = { m = { { 0.00, "Пришла пора вернуться в Пещеры Времени, господин путник." }, { 4.42, "Анахронос ожидает тебя." }, { 6.28, "Отдай ему глаз К'Туна – не сомневаюсь, он непременно захочет поместить его в коллекцию своего хозяина." } }, f = { { 0.00, "Пришла пора вернуться в Пещеры Времени, госпожа путница." }, { 4.54, "Анахронос ожидает тебя." }, { 6.46, "Отдай ему глаз К'Туна – не сомневаюсь, он непременно захочет поместить его в коллекцию своего хозяина." } } }, t = { d = 10.5, v = "creature/anachronos", n = { x = 104 }, c = { x = { { 0.00, "Повелитель оставил это для вас, защитник." }, { 3.57, "В тайнике безвременья хранятся бесценные артефакты." }, { 8.00, "Можете выбрать, что пожелаете." } } } } },
    [8803] = { t = { d = 12.9, g = 1, v = "narrator", n = { x = 114 }, c = { m = { { 0.00, "На записке к подарку написано:" }, { 2.60, "«Кому: путник." }, { 3.83, "Надеюсь, это поможет тебе нести тёплые пожелания и праздничную радость по всему Азероту." }, { 11.41, "Дедушка Зима»" } }, f = { { 0.00, "На записке к подарку написано:" }, { 2.67, "«Кому: путница." }, { 4.01, "Надеюсь, это поможет тебе нести тёплые пожелания и праздничную радость по всему Азероту." }, { 11.78, "Дедушка Зима»" } } } } },
    [8804] = { d = 20.6, v = "narrator", n = { x = 247 }, c = { x = { { 0.00, "В крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне." }, { 7.16, "Новичкам грозит обезвоживание и множество ядовитых тварей." }, { 11.35, "Собери как можно больше составляющих неприкосновенных наборов для отправляющихся в пустыню и отнеси их Каландрат в крепость Кенария." } } }, t = { d = 4.5, v = "nightelf-female#53", n = { x = 39 }, c = { x = { { 0.00, "Отлично!" }, { 0.84, "Нам очень нужны эти материалы." }, { 3.80, "Спасибо." } } } } },
    [8805] = { d = 12.4, v = "narrator", n = { x = 141 }, c = { x = { { 0.00, "Верховому подразделению крепости Кенария не хватает изысканных мифриловых сапог." }, { 6.14, "Принеси нам очередную партию и передай их капитану Вишу Коцусу из крепости Кенария." } } }, t = { d = 4.2, v = "nightelf-male#54", n = { x = 30 }, c = { x = { { 0.00, "Отлично!" }, { 0.99, "Как раз то, что нужно." }, { 3.35, "Спасибо." } } } } },
    [8806] = { d = 9.1, v = "narrator", n = { x = 96 }, c = { x = { { 0.00, "У стражи крепости Кенария на исходе шлифовальные камни." }, { 4.46, "Добудь их и отнеси капитану Вишу Коцусу в крепость Кенария." } } }, t = { d = 4.7, v = "nightelf-male#54", n = { x = 39 }, c = { x = { { 0.00, "Отлично!" }, { 0.89, "Нам очень нужны эти материалы." }, { 4.00, "Спасибо." } } } } },
    [8807] = { d = 16.6, v = "narrator", n = { x = 185 }, c = { x = { { 0.00, "Исследования геолога Злая Шутка имели огромное значение для нашей деятельности в Силитусе." }, { 7.04, "Недавно она запросила материалы для гадания." }, { 10.52, "Пожалуйста, собери всё необходимое и отнеси ей." }, { 14.14, "Пусть она продолжает исследования." } } }, t = { d = 8.5, g = 1, v = "dwarf-female#34", n = { m = 68, f = 70 }, c = { m = { { 0.00, "О да..." }, { 0.71, "Ты мне очень помог!" }, { 2.65, "Достать эти материалы в пустыне невероятно сложно." }, { 7.68, "Спасибо." } }, f = { { 0.00, "О да..." }, { 0.70, "Ты мне очень помогла!" }, { 2.80, "Достать эти материалы в пустыне невероятно сложно." }, { 7.77, "Спасибо." } } } } },
    [8808] = { d = 9.7, v = "narrator", n = { x = 112 }, c = { x = { { 0.00, "У нас такой приток добровольцев, что не хватает формы." }, { 3.96, "Принеси материалы для пошива формы и отдай их призывательнице ветров Гордый Рог." } } }, t = { d = 6.1, v = "tauren-female#71", n = { x = 43 }, c = { x = { { 0.00, "А, да, нам их очень не хватало." }, { 3.38, "Спасибо за добрую службу." } } } } },
    [8809] = { d = 16.9, v = "narrator", n = { x = 188 }, c = { x = { { 0.00, "Варгус, кузнец крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат." }, { 9.10, "Добудь всё необходимое и отнеси их Варгусу в крепость Кенария, чтобы он снабдил войска всем необходимым." } } }, t = { d = 4.1, v = "tauren-male", n = { x = 32 }, c = { x = { { 0.00, "Да-да." }, { 0.77, "Превосходные материалы." }, { 3.29, "Спасибо." } } } } },
    [8810] = { d = 14.5, v = "narrator", n = { x = 169 }, c = { x = { { 0.00, "В последнее время мы понесли серьёзные потери, и запас бинтов стремительно иссякает." }, { 6.27, "Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордый Рог в крепость Кенария." } } }, t = { d = 11.8, v = "tauren-female#71", n = { x = 116 }, c = { x = { { 0.00, "Ты как раз вовремя." }, { 1.66, "Принесённые тобой перевязочные материалы спасут немало жизней." }, { 7.10, "Мы благодарны тебе за труды." }, { 9.63, "Вот твоё следующее задание." } } } } },
