    [8826] = { t = { d = 21.4, v = "troll-male", n = { x = 215 }, c = { x = { { 0.00, "Отлично!" }, { 0.74, "Чтобы получить такое количество жетонов, тебе пришлось многим пожертвовать, но и награда будет велика." }, { 9.21, "Благодаря таким искателям приключений, как ты, мир меняется к лучшему." }, { 14.89, "Сообщи, если у тебя появятся новые жетоны - я с радостью приму любое количество." } } } } },
    [8827] = { d = 20.7, v = "goblin-male#110", n = { x = 246 }, c = { x = { { 0.00, "Говорят, что Дедушка Зима – не без помощи Пастбищ Дымного леса – сложил под ёлку в Стальгорне подарки для всех." }, { 7.55, "Я бы с радостью сходил туда, но мне надо присматривать за Пи-Икс двести тридцать восемь Чудовольтом Мороза." }, { 14.92, "А ты непременно туда загляни." }, { 16.96, "Не сомневаюсь, Дедушка Зима и для тебя подарочек припас." } } }, t = { d = 25.3, g = 1, v = "dwarf-male", n = { m = 264, f = 261 }, c = { m = { { 0.00, "О-хо!" }, { 0.47, "Добро пожаловать!" }, { 1.81, "Я знаю, зачем ты пришёл – открыть свой подарочек на Зимний Покров." }, { 6.72, "Ну-ну, не бойся, Дедушка Зима не забыл про своего любимого героя." }, { 11.69, "Загляни под ёлочку, подарок тебя ждёт-дожидается." }, { 15.32, "Кстати, раз уж все дарят друг другу подарки, не хочешь осчастливить своих друзей превосходными продуктами Пастбищ Дымного леса?" } }, f = { { 0.00, "О-хо!" }, { 0.48, "Добро пожаловать!" }, { 1.84, "Я знаю, зачем ты пришла – открыть свой подарочек на Зимний Покров." }, { 6.89, "Ну-ну, не бойся, Дедушка Зима не забыл про свою любимую героиню." }, { 11.88, "Загляни под ёлочку, подарок тебя ждёт-дожидается." }, { 15.56, "Кстати, раз уж все дарят друг другу подарки, не хочешь осчастливить своих друзей превосходными продуктами Пастбищ Дымного леса?" } } } } },
