    [8829] = { d = 37.2, v = "narrator", n = { x = 424 }, c = { x = { { 0.00, "Сумеречный Молот действует путём обмана и тайных наветов." }, { 4.27, "Хотя они действуют в нашем мире, их идеи рождаются за его пределами, куда мы прежде не могли добраться." }, { 12.07, "Мы пришли к заключению, что камни, которыми главари Сумеречного Молота пользуются для призывания своих повелителей, работают в обе стороны." }, { 22.34, "Чтобы попытаться воспользоваться ими подобным образом, мы должны изготовить точнейшую копию одеяния посланника культа Сумеречного Молота." }, { 32.54, "Собери все необходимые материалы и отнеси их Аурэль Золотой Лист." } } }, t = { d = 21.8, g = 1, v = "nightelf-female#53", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Да, думаю, собранных тобой материалов хватит." }, { 3.49, "Я окрашу это одеяние в цвета, которые носят посланники Сумеречного Молота." }, { 9.24, "Да поможет Элуна вновь обмануть наших врагов." }, { 12.73, "Но не беспокойся, когда ты выполнишь свою роль в этой игре, то получишь достойную награду." }, { 19.58, "Ты верный и достойный союзник." } }, f = { { 0.00, "Да, думаю, собранных тобой материалов хватит." }, { 3.47, "Я окрашу это одеяние в цвета, которые носят посланники Сумеречного Молота." }, { 9.18, "Да поможет Элуна вновь обмануть наших врагов." }, { 12.65, "Но не беспокойся, когда ты выполнишь свою роль в этой игре, то получишь достойную награду." }, { 19.45, "Ты верная и достойная союзница." } } } } },
