    [8855] = { t = { d = 19.6, v = "orc-male", n = { x = 200 }, c = { x = { { 0.00, "Что ж, договорились; забирайте припасы." }, { 3.17, "Если вам понадобится ещё, скажите мне, и я подготовлю соответствующий приказ." }, { 9.36, "Удачи в трудах." }, { 10.69, "Нам не победить, не организовав достойное снабжение." }, { 14.89, "Но если каждый внесёт свой вклад, победа будет не за горами!" } } } } },
    [8856] = { d = 19.5, v = "narrator", n = { x = 227 }, c = { x = { { 0.00, "В крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне." }, { 7.30, "Новичкам грозит обезвоживание и множество ядовитых тварей." }, { 11.58, "Собери как можно больше составляющих наборов для выживания в пустыне и отнеси их Каландрате в крепость Кенария." } } } },
    [8857] = { d = 20.1, v = "gnome-male", n = { x = 227 }, c = { x = { { 0.00, "Мне нужны закалённые в бою искатели приключений, которые согласятся принести свежие образцы панциря павшего колосса Аши Оглторпу Обнотикусу в Пиратскую бухту." }, { 11.60, "Нет-нет, я не прошу подходить к телу этой твари." }, { 15.22, "Возьми один из образцов у меня и поспеши." }, { 18.32, "Тухлятина ему не годится!" } } }, t = { d = 7.3, g = 1, v = "gnome-male", n = { m = 65, f = 65 }, c = { m = { { 0.00, "Ох, сколько же я наделаю цыплят из этого отличного панциря!" }, { 5.16, "Молодец, мальчик мой!" } }, f = { { 0.00, "Ох, сколько же я наделаю цыплят из этого отличного панциря!" }, { 5.40, "Молодец, девочка моя!" } } } } },
    [8858] = { d = 23.3, v = "dwarf-male", n = { x = 246 }, c = { x = { { 0.00, "Я бы с радостью сунул этот панцирь прямо в наглую рожу Скользкорука..." }, { 5.40, "Только вот мне не выбраться, я собираю образцы этого тараканища." }, { 10.25, "И судя по его размерам, провожусь ещё лет сто." }, { 13.73, "Отнеси этот образец Скользкоруку, и побыстрее." }, { 17.28, "Он платит МНОГО!" }, { 18.58, "А вот его адресок: Лагерь Братства Тория – он в Тлеющем ущелье." } } }, t = { d = 8.2, v = "dwarf-male", n = { x = 82 }, c = { x = { { 0.00, "Великолепно." }, { 1.10, "Из этого хитина можно сделать необыкновенно мощный доспех." }, { 6.28, "Вот обещанные богатства." } } } } },
    [8859] = { d = 20.7, v = "human-female", n = { x = 236 }, c = { x = { { 0.00, "Моих слуг едва не убили при попытке добыть эти образцы." }, { 4.03, "Не медли ни минуты!" }, { 5.44, "Лорд Максвелл Тиросс с нетерпением ждёт свежих образцов панцирей." }, { 10.05, "Он надеется, что тайны Колосса помогут нам в войне с Плетью!" }, { 14.34, "Ты ещё тут?!" }, { 15.17, "Вперёд, в часовню Последней Надежды!" }, { 17.73, "Да, ты получишь неплохую награду за труды..." } } }, t = { d = 4.2, g = 1, v = "human-male", n = { m = 34, f = 35 }, c = { m = { { 0.00, "Отлично, и как раз вовремя!" }, { 2.55, "Молодец, парень." } }, f = { { 0.00, "Отлично, и как раз вовремя!" }, { 2.64, "Молодец, девушка." } } } } },
    [8860] = { d = 34.2, v = "goblin-male#110", n = { x = 388 }, c = { x = { { 0.00, "Штормград устраивает празднество в честь нового года!" }, { 3.83, "Целый день там можно пить задарма, а ночью будет фейерверк!" }, { 8.11, "Это должно быть прекрасно... но в Пиратской бухте сегодня тоже праздник, и держу пари, там будет ещё лучше!" }, { 15.89, "Ну, как бы то ни было, хозяйке таверны Аллисон в Штормграде требуются припасы Пастбищ Дымного Леса, чтобы помочь накормить всех гуляк." }, { 25.56, "Окажи мне услугу, доставь эту партию!" }, { 28.35, "Спасибо!" }, { 29.00, "Аллисон держит таверну \"Позолоченная роза\" в Торговом квартале Штормграда." } } }, t = { d = 15.1, v = "human-female#111", n = { x = 166 }, c = { x = { { 0.00, "О, припасы от Пастбища Дымного Леса!" }, { 2.76, "Чудесно!" }, { 3.43, "Они мне понадобятся, чтобы накормить тех, кто собрался на праздник." }, { 8.41, "Спасибо тебе." }, { 9.48, "Вот, возьми деньги и не забудь как следует выпить и поплясать на праздновании!" } } } } },
    [8861] = { d = 34.6, v = "goblin-male#110", n = { x = 381 }, c = { x = { { 0.00, "Громовой Утёс устраивает празднество в честь нового года!" }, { 4.17, "Целый день там можно пить задарма, а ночью будет фейерверк!" }, { 8.54, "Это должно быть прекрасно... но в Пиратской бухте сегодня тоже праздник, и держу пари, там будет ещё лучше!" }, { 16.49, "Ну, как бы то ни было, хозяйке таверны Пале в Громовом Утёсе требуются припасы Пастбищ Дымного Леса, чтобы помочь накормить всех гуляк." }, { 26.43, "Окажи мне услугу, доставь эту партию!" }, { 29.28, "Спасибо!" }, { 29.94, "Пала держит таверну возле моста, ведущего на вершину Охотников." } } }, t = { d = 19.6, v = "tauren-female", n = { x = 191 }, c = { x = { { 0.00, "О, отлично!" }, { 0.96, "Эти припасы помогут накормить всех моих сородичей, собравшихся сюда на праздник!" }, { 7.59, "Спасибо тебе." }, { 8.77, "Я у тебя в долгу." }, { 10.25, "Прошу, возьми эти монеты... и последуй моему совету – пей сегодня от всей души и присоединяйся к праздничным танцам!" } } } } },
    [8862] = { t = { d = 23.4, v = "nightelf-male#54", n = { x = 232 }, c = { x = { { 0.00, "Что ж, хорошо — я принимаю эти монеты предков." }, { 3.82, "Прошу, возьми свечу Элуны с моим благословением." }, { 7.86, "А ещё прими в подарок эти фейерверки." }, { 10.95, "Пусть твой Лунный фестиваль будет радостным и полным веселья." }, { 15.95, "А если решишься сразиться с Оменом и его приспешниками, свеча Элуны тебе очень пригодится..." } } } } },
    [8863] = { t = { d = 23.8, g = 1, v = "nightelf-male#54", n = { m = 261, f = 262 }, c = { m = { { 0.00, "Замечательно!" }, { 0.98, "Наслаждайся клецками и прими мои поздравления." }, { 4.37, "Хотя это всего лишь крохи благодарности по сравнению с той славой, которой ты покрыл себя, свершая великие деяния, мне кажется, что они тебе всё равно понравятся." }, { 16.16, "А если бы у тебя были ещё монетки наследия, то у меня нашлось бы для тебя много интересных вещей." } }, f = { { 0.00, "Замечательно!" }, { 1.01, "Наслаждайся клецками и прими мои поздравления." }, { 4.61, "Хотя это всего лишь крохи благодарности по сравнению с той славой, которой ты покрыла себя, свершая великие деяния, мне кажется, что они тебе всё равно понравятся." }, { 16.80, "А если бы у тебя были ещё монетки наследия, то у меня нашлось бы для тебя много интересных вещей." } } } } },
    [8864] = { t = { d = 20.8, g = 1, v = "nightelf-male#54", n = { m = 207, f = 210 }, c = { m = { { 0.00, "Отлично – беру эти монеты наследия." }, { 3.04, "Бери платье и моё благословение." }, { 5.70, "И полюбуйся, пожалуйста, праздничным фейерверком." }, { 9.70, "Точно так же, как ты принёс честь и славу своим старшим, ты оказал честь и мне, посетив меня." }, { 17.18, "Спасибо тебе, и радостного Лунного фестиваля!" } }, f = { { 0.00, "Отлично – беру эти монеты наследия." }, { 2.92, "Бери платье и моё благословение." }, { 5.49, "И полюбуйся, пожалуйста, праздничным фейерверком." }, { 9.34, "Точно так же, как ты принесла честь и славу своим старшим, ты оказала честь и мне, посетив меня." }, { 16.83, "Спасибо тебе, и радостного Лунного фестиваля!" } } } } },
    [8865] = { t = { d = 20.2, v = "nightelf-male#54", n = { x = 215 }, c = { x = { { 0.00, "Идёт – я беру эти монеты наследия." }, { 2.72, "Бери этот брючный костюм и моё благословение." }, { 6.28, "И полюбуйся, пожалуйста, праздничным фейерверком!" }, { 10.05, "Если у тебя найдётся ещё несколько монет наследия, обращайся ко мне." }, { 15.28, "Я буду продавать разные вещи в течение всего Лунного фестиваля." } } } } },
    [8866] = { t = { d = 8.8, v = "dwarf-male", n = { x = 86 }, c = { x = { { 0.00, "Приятно знать, что жители этих земель всё ещё чтят древние расы." }, { 5.13, "Желаю тебе удачи, и прими от меня этот знак..." } } } } },
    [8867] = { d = 23.8, v = "tauren-female#72", n = { x = 263 }, c = { x = { { 0.00, "Каждый год друиды Лунной поляны празднуют торжество своего города над древним злом." }, { 6.62, "Мы вспоминаем о мудрости старейшин, наслаждаемся пирами и, разумеется, пускаем фейерверки!" }, { 13.67, "За небольшое пожертвование вы можете приобрести разноцветные ракеты у наших торговцев." }, { 20.43, "Можете воспользоваться здешними ракетометами." } } }, t = { d = 23.4, v = "tauren-female#72", n = { x = 232 }, c = { x = { { 0.00, "Молодец." }, { 0.74, "Раз вы так прониклись духом праздника, почему бы вам не отправиться в Лунную поляну?" }, { 7.52, "Если у вас есть время, там можно неплохо повеселиться." }, { 11.94, "Полно еды, выпивки, баек у костра..." }, { 15.04, "И фейерверков!" }, { 16.22, "Откройте приглашение, стоя в большом круге лунного света, и перенесётесь в Лунную поляну." } } } } },
    [8868] = { d = 43.0, v = "nightelf-male#54", n = { x = 402 }, c = { x = { { 0.00, "Эта тварь, Омен, был некогда героем нашего мира." }, { 4.28, "Волк великой силы, любимец удачи, Омен сражался плечом к плечу с героями Войны Древних, пока не попал под власть демонической магии." }, { 15.80, "Обратившись против своих союзников, он в ярости рыскал по Азероту, сея вокруг себя смерть и ужас." }, { 24.28, "Наконец, побеждённый здесь, в Лунной поляне, Омен ныне спит под илом озера Элуны." }, { 31.29, "Но каждый год во время праздника он шевелится во сне..." }, { 35.96, "Собирай соратников, пробуди и порази эту тварь, Омена." }, { 40.71, "Заслужи благословение Элуны!" } } }, t = { d = 28.5, v = "nightelf-male#54", n = { x = 283 }, c = { x = { { 0.00, "Славное дело." }, { 1.18, "Победа над Оменом возвратила его дух в воды озера Элуны." }, { 5.92, "Хотя сама тварь была благословлена Элуной и не может умереть, его гнев ещё на год утихнет." }, { 13.32, "Твоя победа стоит праздника – да почтят всё могущество Омена, воздадут хвалу тебе и твоим друзьям и восславят покой, который был подарен тобой этому трагическому герою нашего прошлого." } } } } },
    [8869] = { d = 27.0, v = "scourge-female", n = { x = 224 }, c = { x = { { 0.00, "В казематах Бастиона Алого ордена таится чертёж «Безмятежности»." }, { 6.21, "Багровый молотобоец стережёт его как зеницу ока." }, { 10.94, "Срази его и принеси мне его фартук." }, { 14.52, "За это я открою тебе секреты школы Молота." }, { 18.81, "Но запомни." }, { 19.95, "Если ты выберешь это умение, Школы Меча и Топора будут для тебя закрыты." } } } },
    [8870] = { d = 18.5, v = "nightelf-male#59", n = { x = 228 }, c = { x = { { 0.00, "Время веселиться!" }, { 1.21, "Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 7.23, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 15.54, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 4.6, g = 1, v = "tauren-female#72", n = { m = 50, f = 50 }, c = { m = { { 0.00, "Добро пожаловать." }, { 1.39, "Ты пришёл, чтобы праздновать вместе с нами?" } }, f = { { 0.00, "Добро пожаловать." }, { 1.39, "Ты пришла, чтобы праздновать вместе с нами?" } } } } },
    [8871] = { d = 18.5, v = "nightelf-male#59", n = { x = 228 }, c = { x = { { 0.00, "Время веселиться!" }, { 1.26, "Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 7.49, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 15.41, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 4.3, v = "tauren-female#72", n = { x = 48 }, c = { x = { { 0.00, "Добро пожаловать." }, { 1.44, "Ты хочешь присоединиться к торжествам?" } } } } },
    [8872] = { d = 18.6, v = "nightelf-male#59", n = { x = 228 }, c = { x = { { 0.00, "Время веселиться!" }, { 1.27, "Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 7.55, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 15.55, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 4.7, g = 1, v = "tauren-female#72", n = { m = 50, f = 50 }, c = { m = { { 0.00, "Добро пожаловать." }, { 1.39, "Ты пришёл, чтобы праздновать вместе с нами?" } }, f = { { 0.00, "Добро пожаловать." }, { 1.41, "Ты пришла, чтобы праздновать вместе с нами?" } } } } },
    [8873] = { d = 21.1, v = "tauren-male#68", n = { x = 228 }, c = { x = { { 0.00, "Время веселиться!" }, { 1.44, "Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 8.55, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 17.61, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 4.6, g = 1, v = "tauren-female#72", n = { m = 50, f = 50 }, c = { m = { { 0.00, "Добро пожаловать." }, { 1.41, "Ты пришёл, чтобы праздновать вместе с нами?" } }, f = { { 0.00, "Добро пожаловать." }, { 1.36, "Ты пришла, чтобы праздновать вместе с нами?" } } } } },
    [8874] = { d = 20.7, v = "tauren-male#68", n = { x = 228 }, c = { x = { { 0.00, "Время веселиться!" }, { 1.41, "Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 8.39, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 17.27, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 4.2, v = "tauren-female#72", n = { x = 48 }, c = { x = { { 0.00, "Добро пожаловать." }, { 1.39, "Ты хочешь присоединиться к торжествам?" } } } } },
    [8875] = { d = 20.9, v = "tauren-male#68", n = { x = 228 }, c = { x = { { 0.00, "Время веселиться!" }, { 1.42, "Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 8.46, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 17.41, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 4.6, g = 1, v = "tauren-female#72", n = { m = 50, f = 50 }, c = { m = { { 0.00, "Добро пожаловать." }, { 1.36, "Ты пришёл, чтобы праздновать вместе с нами?" } }, f = { { 0.00, "Добро пожаловать." }, { 1.36, "Ты пришла, чтобы праздновать вместе с нами?" } } } } },
    [8876] = { t = { d = 5.7, v = "nightelf-female#53", n = { x = 52 }, c = { x = { { 0.00, "О, великолепно." }, { 1.38, "Вот тебе инструкция, и да благословит тебя Элуна." } } } } },
    [8877] = { t = { d = 8.8, v = "nightelf-female#53", n = { x = 102 }, c = { x = { { 0.00, "Вот." }, { 0.33, "Это чертёж пусковой установки для фейерверков." }, { 3.71, "Ставишь её там, где хочешь повеселиться, и приглашай друзей на праздник!" } } } } },
    [8878] = { t = { d = 7.7, v = "nightelf-female#53", n = { x = 81 }, c = { x = { { 0.00, "Вот твои выкройки." }, { 1.52, "Изделия, которые ты сошьёшь благодаря им, будут вне всякого сомнения прекрасны." } } } } },
    [8879] = { t = { d = 6.9, v = "nightelf-female#53", n = { x = 59 }, c = { x = { { 0.00, "Отлично, беру." }, { 1.44, "Вот твои инструкции." }, { 3.40, "Воспользуйся ими к вящей славе Элуны!" } } } } },
    [8880] = { t = { d = 9.8, v = "nightelf-female#53", n = { x = 92 }, c = { x = { { 0.00, "Вот." }, { 0.39, "Бери эти чертежи и изучай их секреты." }, { 3.72, "Желаю тебе удачи и надеюсь в будущем увидеть твои прекрасные творения." } } } } },
    [8881] = { t = { d = 10.6, v = "nightelf-female#53", n = { x = 121 }, c = { x = { { 0.00, "Спасибо." }, { 0.67, "Вот инструкция по изготовлению больших сигнальных ракет." }, { 4.85, "И пусть твои изделия принесут радость и удачу всем, кто будет на них любоваться." } } } } },
    [8882] = { t = { d = 9.8, v = "nightelf-female#53", n = { x = 100 }, c = { x = { { 0.00, "Вот твой чертёж." }, { 1.24, "Рассмотри его как следует и изучи..." }, { 4.23, "Удачи." }, { 4.81, "И пусть твои праздники посоперничают с самим Лунным фестивалем!" } } } } },
    [8883] = { d = 26.7, v = "tauren-female#72", n = { x = 312 }, c = { x = { { 0.00, "Раз у тебя есть приглашение на Лунный фестиваль, можешь отправляться в Лунную поляну!" }, { 6.09, "Там полно весёлых гуляк, а в деревне Ночная Гавань Валадар Звёздная Песня и его сестра Фариэль приглашают всех принять участие в празднике." }, { 16.05, "Отправляйтесь в Лунную поляну через большой круг лунного света и поговорите с Валадаром – узнайте, какие призы могут перепасть вам во время праздника!" } } }, t = { d = 21.8, v = "nightelf-male#54", n = { x = 247 }, c = { x = { { 0.00, "Добро пожаловать в Ночную Гавань, столицу Лунного фестиваля!" }, { 4.48, "Обычно наша деревня держится в стороне от основных событий Азерота, но во время этого праздника мы с радостью приглашаем всех к себе." }, { 14.22, "Надеюсь, тебе у нас понравится." }, { 16.52, "Если решишь поучаствовать в конкурсах, обращайся ко мне или к моей сестре." } } } } },
    [8893] = { t = { d = 16.0, v = "narrator", n = { x = 158 }, c = { x = { { 0.00, "Вы кладёте в машину яйцо гиппогрифа." }, { 3.11, "Раздаётся несколько гудков и странный механический шум." }, { 7.77, "Похоже, яйцеметр взвесил, измерил и упаковал ваше яйцо." }, { 12.66, "Вот это называется быстрое обслуживание!" } } } } },
    [8897] = { d = 33.9, v = "human-male", n = { x = 394 }, c = { x = { { 0.00, "Я должен нести стражу здесь, у ворот, но я постоянно беспокоюсь о моей милой Коларе." }, { 5.82, "Даже при самой большой удаче я могу увидеться с нею лишь на несколько часов, да и что я собой представляю?" }, { 13.13, "Я получаю жалованье младшего офицера и в любой день меня могут отозвать на фронт." }, { 18.70, "Не забудет ли она обо мне сразу после расставания?" }, { 22.23, "В городе полно мужчин, и многие из них богаты." }, { 25.45, "Но как бы то ни было, я написал тут несколько слов... ничего особенного, но я буду признателен, если ты доставишь их ей от меня." } } }, t = { d = 12.4, v = "human-female", n = { x = 123 }, c = { x = { { 0.00, "Как это мило!" }, { 1.15, "Он впервые догадался мне написать." }, { 3.90, "Ты думаешь, он это серьёзно?" }, { 6.13, "Колара Хельдрик?" }, { 7.50, "По-моему, звучит неплохо." }, { 9.59, "О, но я забегаю вперёд." }, { 11.40, "Спасибо тебе." } } } } },
    [8898] = { d = 23.7, v = "dwarf-male", n = { x = 264 }, c = { x = { { 0.00, "В последний раз, когда я был в Штормграде по делам банка, я встретил там девушку." }, { 5.73, "Она похитила моё сердце." }, { 7.53, "Я не могу не думать о ней!" }, { 9.40, "Я хотел бы послать ей это письмо – я переписывал его двенадцать раз." }, { 14.29, "Почта сейчас так загружена, а я хотел бы точно знать, что письмо попадёт к ней." }, { 19.83, "Если ты направляешься туда, то не окажешь ли мне услугу?" } } }, t = { d = 11.0, v = "human-female", n = { x = 101 }, c = { x = { { 0.00, "Тормек?" }, { 0.67, "О да, я помню его." }, { 2.22, "У него была такая красивая борода, и он всё время в неё улыбался." }, { 7.64, "Ах, поверить не могу, что он меня не забыл!" } } } } },
    [8899] = { d = 26.4, v = "nightelf-male#55", n = { x = 295 }, c = { x = { { 0.00, "Как описать её красоту?" }, { 1.71, "Тысячи лет я учился выражать свои мысли словами, но ныне я нём." }, { 6.37, "Эти смертные вводят в смущение разум и превращают нас в лепечущих чушь идиотов." }, { 12.16, "Я слишком долго смотрел на эти слова." }, { 14.98, "Я больше не могу выжать из них ни капли смысла и убедительности." }, { 19.65, "Нет, она должна получить это послание немедленно, или кто-нибудь другой привлечёт её внимание." } } }, t = { d = 4.6, v = "human-female", n = { x = 46 }, c = { x = { { 0.00, "Ничего подобного я прежде не получала." }, { 3.33, "Как трогательно!" } } } } },
    [8900] = { d = 34.3, v = "orc-male", n = { x = 356 }, c = { x = { { 0.00, "Она была такой грустной." }, { 1.95, "Я понял это, едва узрев, что таится под выражением её лица." }, { 6.45, "Я имею в виду, она казалась грустной – понимаешь?" }, { 10.21, "А после того, как я поговорил с ней, возникла взаимосвязь." }, { 14.51, "Я не думал, что кто-то может понять мои мысли, но она смогла." }, { 19.22, "Когда я сказал остальным, они смеялись надо мной, и потому я больше никогда с ней не заговаривал." }, { 26.47, "Но я скучаю по ней." }, { 27.88, "Ты не можешь отнести ей от меня письмо?" }, { 30.84, "Я хочу быть уверен, что оно попадёт к ней в руки." } } }, t = { d = 13.9, v = "scourge-female#80", n = { x = 131 }, c = { x = { { 0.00, "Вот не ожидала, что орк окажется таким красноречивым." }, { 4.67, "Конечно же, до нынешних времён у нас не было возможности как следует их узнать." }, { 11.59, "Спасибо за доставку письма!" } } } } },
    [8901] = { d = 38.6, v = "tauren-male", n = { x = 365 }, c = { x = { { 0.00, "Известно ли тебе, что такое любовь – в твои-то годы?" }, { 4.39, "До недавнего времени для меня это было нечто чуждое, а затем я встретил в Подгороде ту девушку – Элению." }, { 13.11, "Для моего народа это редкое событие – остановить свой взгляд на ком-то из другой расы, не говоря уж о тех, кто принадлежит к Отрёкшимся." }, { 24.13, "Но ныне мысли о ней занимают мой разум день и ночь." }, { 28.30, "Если будет возможность, не передашь ли ты ей это письмо?" }, { 32.99, "Я хочу, чтобы она приехала сюда, в Мулгор." }, { 36.64, "Надеюсь, она скажет \"да\"." } } }, t = { d = 25.2, v = "scourge-female#80", n = { x = 209 }, c = { x = { { 0.00, "Какие милые слова написал мне Темма!" }, { 3.66, "Но, хотя его слова меня тронули, я не могу всерьёз рассматривать любовь таурена." }, { 11.51, "Мы слишком разные по крови, разуму и духу." }, { 15.69, "Как хорошо, что он не сделал мне это предложение лично." }, { 21.01, "Мне было бы невыносимо разбивать ему сердце." } } } } },
    [8902] = { d = 32.7, v = "scourge-male", n = { x = 317 }, c = { x = { { 0.00, "Целую жизнь назад я был помолвлен с девушкой по имени Эления, подругой моего детства." }, { 7.03, "Прошли годы с тех пор, как я в последний раз думал о ней, но в последнее время она постоянно занимает мои мысли." }, { 16.21, "Быть может даже тогда, когда всё ушло, в нашей жизни всё-таки остаётся место для любви." }, { 23.40, "Я уверен, что она тоже изменилась." }, { 26.28, "Ты не передашь ей от меня письмо?" }, { 29.02, "Я слишком волнуюсь, чтобы передать его лично." } } }, t = { d = 32.5, v = "scourge-female#80", n = { x = 296 }, c = { x = { { 0.00, "Это возвращает воспоминания о прошлой жизни." }, { 3.96, "Эления Тор." }, { 4.99, "Знаешь, это должно было быть моим именем." }, { 8.79, "У нас была бы красивая церемония на берегу озера." }, { 13.15, "А когда он вышел бы в отставку, мы бы поселились на какой-нибудь ферме." }, { 19.33, "Такие вот простые мечты." }, { 21.55, "Но если бы он увидел меня сейчас, я сомневаюсь, что он вообще увидел бы во мне Элению." }, { 29.07, "Только холодная плоть и мёртвое сердце..." } } } } },
    [8903] = { d = 26.2, v = "human-male", n = { x = 307 }, c = { x = { { 0.00, "Есть что-то неестественное в этой эпидемии любви." }, { 3.48, "Это неправильно, это как заноза в пальце и, если дойдёт до самого худшего, это может стать угрозой безопасности самого Альянса." }, { 12.46, "Только подумай: что, если стражи будут сражены этой странной влюблённостью?" }, { 17.77, "Нужно что-то делать." }, { 19.28, "Отправляйся к одному из стражей здесь, в Штормграде, и посмотри, не постигло ли их это помешательство." } } }, t = { d = 9.8, v = "human-male", n = { x = 110 }, c = { x = { { 0.00, "Так это правда!" }, { 1.18, "Просто не могу поверить." }, { 3.02, "Как это могло случиться?" }, { 4.86, "Дай мне немного поразмыслить." }, { 6.96, "За этим должны крыться какие-то причины." } } } } },
    [8904] = { d = 36.0, v = "scourge-male#82", n = { x = 365 }, c = { x = { { 0.00, "Есть что-то неестественное в этой эпидемии любви." }, { 4.09, "Это отвратительно, а поскольку это ослабляет нашу защиту, то может представлять угрозу для всех нас." }, { 12.35, "Достаточно плохо уже то, что многие из нашего народа заразились этим странным поведением." }, { 19.79, "Но мне кажется, что поветрие распространилось даже на стражей, которые должны быть невосприимчивы к таким вещам." }, { 28.93, "Отправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство." } } }, t = { d = 12.4, v = "scourge-male#82", n = { x = 110 }, c = { x = { { 0.00, "Так это правда!" }, { 1.49, "Просто не могу поверить." }, { 3.80, "Как это могло случиться?" }, { 6.12, "Дай мне немного поразмыслить." }, { 8.76, "За этим должны крыться какие-то причины." } } } } },
    [8905] = { d = 33.6, g = 1, v = "human-female", n = { x = 375 }, c = { m = { { 0.00, "Рада встрече, герой." }, { 1.54, "У меня найдётся кое-что интересное для тебя." }, { 4.67, "Есть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества." }, { 11.33, "Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу." }, { 17.16, "Кровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны." }, { 25.68, "Принеси мне некоторое количество этой крови, наручи и немного золота." }, { 30.67, "Увидишь – твои старания окупятся." } }, f = { { 0.00, "Рада встрече, героиня." }, { 1.69, "У меня найдётся кое-что интересное для тебя." }, { 4.88, "Есть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества." }, { 11.64, "Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу." }, { 17.56, "Кровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны." }, { 26.20, "Принеси мне некоторое количество этой крови, наручи и немного золота." }, { 31.27, "Увидишь – твои старания окупятся." } } }, t = { d = 17.3, v = "human-female", n = { x = 204 }, c = { x = { { 0.00, "Великолепно!" }, { 0.89, "Так совершим обмен!" }, { 2.29, "Жалко расставаться с такими великолепными доспехами, но, боюсь, в ближайшее время они мне не понадобятся." }, { 9.67, "Если ты согласишься выполнить для меня ещё кое-какие поручения, то, может, я отдам и остальную часть комплекта." } } } } },
