    [8921] = { d = 33.5, v = "goblin-male", n = { x = 386 }, c = { x = { { 0.00, "А, тебе нужен мой последний проект… спектральный сканер иных измерений!" }, { 5.33, "К сожалению, мне не хватает средств и сотрудников." }, { 8.93, "Хочешь помочь?" }, { 10.07, "Великолепно!" }, { 11.00, "Первым делом нам придётся добыть самую сущность смерти!" }, { 15.13, "Эктоплазматический дистиллятор будет нелегко построить." }, { 19.20, "Мне понадобится арканитовый преобразователь, несколько великих вечных субстанций и масло каменного угря." }, { 26.87, "Пригодится и вулканический пепел из прудов лавы в Пылающих степях – из него я сделаю фильтр." } } }, t = { d = 10.2, v = "goblin-male", n = { x = 101 }, c = { x = { { 0.00, "Вот, именно то, что и требовалось." }, { 2.73, "И очень вовремя!" }, { 4.13, "Дистиллятор вот-вот заработает!" }, { 6.71, "А тем временем прими это в уплату за работу." } } } } },
    [8922] = { d = 23.9, g = 1, v = "human-female", n = { m = 284, f = 285 }, c = { m = { { 0.00, "Я должна найти способ связаться с Антионом Хармоном... точнее, с его духом!" }, { 5.19, "Я знаю одного инженера, который чрезвычайно интересуется сверхъестественным." }, { 10.32, "Он говорит, будто бы может соорудить машину, которая позволит ему разговаривать с духами!" }, { 16.42, "Та кровь, что ты собрал, предназначается как раз ему." }, { 19.90, "Поезжай в Прибамбасск и отдай её ему в оплату услуг!" } }, f = { { 0.00, "Я должна найти способ связаться с Антионом Хармоном... точнее, с его духом!" }, { 5.30, "Я знаю одного инженера, который чрезвычайно интересуется сверхъестественным." }, { 10.54, "Он говорит, будто бы может соорудить машину, которая позволит ему разговаривать с духами!" }, { 16.77, "Та кровь, что ты собрала, предназначается как раз ему." }, { 20.38, "Поезжай в Прибамбасск и отдай её ему в оплату услуг!" } } }, t = { d = 6.4, v = "goblin-male", n = { x = 58 }, c = { x = { { 0.00, "О, радость!" }, { 1.04, "У меня как раз запасы оскудели!" }, { 3.84, "Говорите, вас Делиана послала?" } } } } },
    [8923] = { d = 39.6, g = 1, v = "orc-male", n = { m = 418, f = 419 }, c = { m = { { 0.00, "Ты всё ещё здесь?" }, { 1.26, "Да, храбрости тебе не занимать!" }, { 3.70, "Наверное, тебя заинтересовали те наручи, что я тебе дал." }, { 8.03, "Да, у меня есть и другие детали такого доспеха, и ты их получишь, если будешь по-прежнему помогать мне." }, { 15.99, "Образцы яда, которые ты собрал, предназначены для моего знакомого, Мукса Маноскреба." }, { 22.55, "Это инженер, который увлекается всем сверхъестественным." }, { 26.88, "Сейчас он пытается построить прибор, с помощью которого можно общаться с мёртвыми!" }, { 33.23, "Я надеюсь с помощью этого прибора связаться с Антионом и получить от него совет." } }, f = { { 0.00, "Ты всё ещё здесь?" }, { 1.26, "Да, храбрости тебе не занимать!" }, { 3.72, "Наверное, тебя заинтересовали те наручи, что я тебе дал." }, { 8.06, "Да, у меня есть и другие детали такого доспеха, и ты их получишь, если будешь по-прежнему помогать мне." }, { 16.05, "Образцы яда, которые ты собрала, предназначены для моего знакомого, Мукса Маноскреба." }, { 22.71, "Это инженер, который увлекается всем сверхъестественным." }, { 27.06, "Сейчас он пытается построить прибор, с помощью которого можно общаться с мёртвыми!" }, { 33.44, "Я надеюсь с помощью этого прибора связаться с Антионом и получить от него совет." } } }, t = { d = 7.8, v = "goblin-male", n = { x = 77 }, c = { x = { { 0.00, "Замечательно!" }, { 1.12, "Как раз вовремя." }, { 2.46, "У меня яд почти закончился…" }, { 4.78, "Так ты говоришь, тебя Моквар прислал?" } } } } },
    [8924] = { d = 30.3, v = "goblin-male", n = { x = 377 }, c = { x = { { 0.00, "Отличная конструкция, вот что я скажу!" }, { 2.61, "Впрочем, тебе придётся попутешествовать, чтобы отыскать бестелесную нежить, без которой не обойтись." }, { 9.45, "Видишь ли, разный климат оказывает разного рода воздействие на спектральную ткань мертвецов." }, { 15.79, "Там понадобится эктоплазма от страдающих ночных эльфов Силитуса, духов высокорождённых из Зимних Ключей и призраков и банши из Восточных Чумных земель." }, { 26.11, "Не забудь установить дистиллятор, прежде чем приступать к делу!" } } }, t = { d = 10.2, v = "goblin-male", n = { x = 109 }, c = { x = { { 0.00, "Да, отличные образцы!" }, { 1.67, "Собрав всю иномирную энергию из этих субстанций, мы сможем связаться с теми душами, что ещё не покинули этот мир!" } } } } },
    [8925] = { d = 29.4, v = "goblin-male", n = { x = 355 }, c = { x = { { 0.00, "Теперь нам понадобится стабильный и портативный источник энергии, который сможет поддерживать эктоплазму в активной форме." }, { 8.48, "До меня дошли слухи о могущественном элементале по имени Повелитель магмы Бокк." }, { 14.01, "Его сердце состоит из магмы, и это бесконечный источник тепла!" }, { 18.47, "Говорят, что его можно отыскать в Пылающих степях, на юге от Чёрной горы." }, { 23.62, "Принеси мне магмовое ядро и мы обеспечим энергией спектральный сканер иных измерений!" } } }, t = { d = 6.1, v = "goblin-male", n = { x = 69 }, c = { x = { { 0.00, "Получилось!" }, { 0.89, "Теперь нам явно хватит энергии на спектральный сканер иных измерений!" } } } } },
