    [8927] = { d = 24.0, g = 1, v = "orc-male", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Ты оказался чрезвычайно надёжным помощником!" }, { 3.26, "Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!" }, { 12.31, "Обменяю-ка я твой пояс и перчатки на кое-что получше." }, { 16.32, "А если мы оба доживём до успешного завершения нашего предприятия, я отдам тебе и остальное." } }, f = { { 0.00, "Ты оказалась чрезвычайно надёжной помощницей!" }, { 3.46, "Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!" }, { 12.85, "Обменяю-ка я твой пояс и перчатки на кое-что получше." }, { 17.02, "А если мы оба доживём до успешного завершения нашего предприятия, я отдам тебе и остальное." } } }, t = { d = 13.8, v = "orc-male", n = { x = 133 }, c = { x = { { 0.00, "Наш уговор в силе." }, { 1.58, "Только помни: это лишь малая доля того, что тебя ждёт." }, { 6.25, "Избавь меня от этой проклятой участи, и я награжу тебя по-настоящему могущественными вещами." } } } } },
