    [8944] = { d = 24.1, g = 1, v = "orc-male", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Ты оказался чрезвычайно надёжным помощником!" }, { 3.34, "Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!" }, { 12.61, "Обменяю-ка я твой пояс и рукавицы на кое-что получше." }, { 16.72, "А если мы оба доживём до успешного завершения нашего предприятия, я отдам тебе и остальное." } }, f = { { 0.00, "Ты оказалась чрезвычайно надёжной помощницей!" }, { 3.47, "Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!" }, { 12.89, "Обменяю-ка я твой пояс и рукавицы на кое-что получше." }, { 17.07, "А если мы оба доживём до успешного завершения нашего предприятия, я отдам тебе и остальное." } } }, t = { d = 13.8, v = "orc-male", n = { x = 124 }, c = { x = { { 0.00, "Наш договор остаётся в силе." }, { 2.52, "Не забывай, вскоре ты получишь куда более ценные вещи!" }, { 7.57, "Только освободи меня от этого проклятия, а уж я тебе отплачу сторицей!" } } } } },
    [8945] = { d = 22.6, v = "named/16016", n = { x = 240 }, c = { x = { { 0.00, "Я отвечу на все твои вопросы." }, { 2.24, "Но прежде исполни мою просьбу." }, { 4.61, "Любимая жена моя была схвачена проклятым воинством Ривендера." }, { 9.36, "Как же я не хотел, чтобы она следовала за дураками из Серебряного Рассвета, но теперь это всё уже не важно." }, { 17.43, "Прошу тебя, сделай то, что не удалось мне, – спаси Исиду из лап барона!" } } }, t = { d = 12.9, v = "human-female#45", n = { x = 125 }, c = { x = { { 0.00, "Благодарю за спасение!" }, { 1.82, "Не думала я, что мне удастся выжить." }, { 4.73, "Прошу тебя, прими это в качестве миллионной доли моей благодарности." }, { 10.41, "Антион... о нет... не может быть!" } } } } },
    [8946] = { d = 26.2, v = "human-female#45", n = { x = 301 }, c = { x = { { 0.00, "Нет судьбы горше, чем видеть, как твои близкие гибнут, пытаясь спасти тебя." }, { 5.34, "Ты утверждаешь, что можешь говорить с мёртвыми." }, { 8.54, "Отнеси Антиону этот медальон как доказательство того, что я жива и здорова." }, { 13.82, "Скажи ему, что ему не стоит цепляться за этот мир, обрекая себя на скитания в обличье бесплотного духа – моё бедное сердце этого не вынесет." }, { 23.68, "Прощай, я всегда буду у тебя в долгу." } } }, t = { d = 11.0, g = 1, v = "named/16016", n = { m = 99, f = 99 }, c = { m = { { 0.00, "Да, это её медальон – ты нашёл её!" }, { 2.86, "Теперь я могу покоиться с миром." }, { 5.71, "Я отвечу на все твои вопросы." }, { 8.26, "Но торопись, время моё на исходе." } }, f = { { 0.00, "Да, это её медальон – ты нашла её!" }, { 2.93, "Теперь я могу покоиться с миром." }, { 5.79, "Я отвечу на все твои вопросы." }, { 8.34, "Но торопись, время моё на исходе." } } } } },
    [8947] = { d = 29.6, v = "named/16016", n = { x = 378 }, c = { x = { { 0.00, "Мы не сразу поняли важность медальона Вальтхалака, поэтому он был поделён наряду с остальными трофеями." }, { 6.67, "Первый фрагмент получил дворф по имени Тельдрен." }, { 9.85, "Я сам пытался отобрать у него этот фрагмент, но дворф избил меня до полусмерти." }, { 15.05, "Тебе придётся забрать фрагмент силой." }, { 17.52, "Говорят, Тельдрен стал гладиатором у дворфов Чёрного Железа." }, { 21.42, "Правда, заставить его сразиться с тобой будет непросто." }, { 25.14, "И сначала собери для меня некоторые материалы – они тебе понадобятся." } } }, t = { d = 3.7, v = "named/16016", n = { x = 39 }, c = { x = { { 0.00, "Прекрасно, я превращу их во что-нибудь полезное." } } } } },
    [8948] = { d = 21.8, v = "named/16016", n = { x = 247 }, c = { x = { { 0.00, "Тельдрен – не из тех, кто охотно вступает в честный поединок." }, { 4.33, "Но я изготовил знамя его родовых цветов." }, { 7.30, "Если ещё наложить на него соответствующее заклятие, перед этим он не устоит." }, { 12.79, "Мой старый приятель по имени Фарлин знает такое заклятие." }, { 16.99, "Умеет он... подзуживать." }, { 18.74, "Ты найдёшь его в библиотеке Забытого Города." } } }, t = { d = 12.5, v = "nightelf-male#59", n = { x = 129 }, c = { x = { { 0.00, "А, так ты от Антиона, говоришь?" }, { 2.30, "А я-то думал, он мёртв..." }, { 4.19, "Впрочем, случалось мне на своём веку слышать и более странные вещи." }, { 9.25, "Ну что ж." }, { 9.93, "Так что мне сделать с этим знаменем?" } } } } },
    [8949] = { d = 33.8, g = 1, v = "nightelf-male#59", n = { x = 384 }, c = { m = { { 0.00, "Да, герой, мне действительно знакомы те чары, которые ты ищешь." }, { 4.34, "Но я не из тех, что оказывают услуги даром, даже тем, кого прислал сюда мой старый приятель." }, { 10.65, "Я испытываю глубокую ненависть и презрение к нашим грубым соседям-ограм." }, { 15.67, "И не только к ним: последователей Омокка я ненавижу не меньше, чем сторонников короля Гордока." }, { 22.05, "Убивай их!" }, { 22.79, "И чем больше, тем лучше!" }, { 24.47, "Принеси мне в доказательство своего успеха ожерелья, которые огры носят на шее." }, { 29.98, "Сделай это, тогда и поговорим о твоей просьбе." } }, f = { { 0.00, "Да, героиня, мне действительно знакомы те чары, которые ты ищешь." }, { 4.53, "Но я не из тех, что оказывают услуги даром, даже тем, кого прислал сюда мой старый приятель." }, { 10.94, "Я испытываю глубокую ненависть и презрение к нашим грубым соседям-ограм." }, { 16.04, "И не только к ним: последователей Омокка я ненавижу не меньше, чем сторонников короля Гордока." }, { 22.52, "Убивай их!" }, { 23.27, "И чем больше, тем лучше!" }, { 24.97, "Принеси мне в доказательство своего успеха ожерелья, которые огры носят на шее." }, { 30.57, "Сделай это, тогда и поговорим о твоей просьбе." } } }, t = { d = 12.3, g = 1, v = "nightelf-male#59", n = { m = 121, f = 122 }, c = { m = { { 0.00, "Хм-м... как ни странно, смерть брата от рук этих громил не стала для меня легче." }, { 6.23, "Что ж, свою часть уговора ты выполнил." }, { 9.20, "Посмотрим, что я могу для тебя сделать." } }, f = { { 0.00, "Хм-м... как ни странно, смерть брата от рук этих громил не стала для меня легче." }, { 6.27, "Что ж, свою часть уговора ты выполнила." }, { 9.34, "Посмотрим, что я могу для тебя сделать." } } } } },
    [8950] = { d = 27.2, v = "nightelf-male#59", n = { x = 304 }, c = { x = { { 0.00, "Я без труда могу наложить на знамя чары, которые тебе нужны." }, { 4.60, "Однако, к несчастью, у меня нет необходимых материалов: такие заклинания очень мало кто спрашивает." }, { 11.94, "Мне потребуется сущность одного из призраков Элдрета, обитающих в этих залах, горсть чёрных рун из Некроситета и несколько больших сияющих осколков." }, { 22.74, "Принеси мне эти ингредиенты, и я создам для тебя нужные чары." } } }, t = { d = 8.6, v = "nightelf-male#59", n = { x = 85 }, c = { x = { { 0.00, "Да, это вполне подойдёт." }, { 1.98, "Когда я закончу, никакая сила в мире не помешает твоей жертве принять твой вызов." } } } } },
    [8951] = { d = 30.1, v = "named/16016", n = { x = 331 }, c = { x = { { 0.00, "В этом медальоне заключена душа Вальтхалака." }, { 3.37, "В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии." }, { 10.43, "Единственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон." }, { 16.16, "Вернись к Делиане и скажи ей, что Бодли – её единственная надежда найти остальные части." }, { 22.75, "Поговори с ней об условленной награде." }, { 25.58, "Я же ныне спокойно умру." }, { 27.47, "Желаю удачи – она тебе понадобится!" } } }, t = { d = 14.2, g = 1, v = "human-female", n = { m = 156, f = 158 }, c = { m = { { 0.00, "Поверить не могу, что наша жизнь висит на волоске из-за какого-то дурацкого медальона!" }, { 6.30, "А ты уверен, что Антион упомянул Бодли?" }, { 9.19, "Ладно, ты своё дело сделал, так что давай закончим и с твоей наградой." } }, f = { { 0.00, "Поверить не могу, что наша жизнь висит на волоске из-за какого-то дурацкого медальона!" }, { 6.03, "А ты уверена, что Антион упомянул Бодли?" }, { 8.86, "Ладно, ты своё дело сделала, так что давай закончим и с твоей наградой." } } } } },
