    [8957] = { d = 31.0, v = "named/16016", n = { x = 343 }, c = { x = { { 0.00, "В этом амулете хранилась душа Вальтхалака." }, { 3.18, "Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало." }, { 10.53, "Единственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино." }, { 17.02, "Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части." }, { 24.10, "Расскажи ему про обещанные награды." }, { 26.75, "Ну, а я упокоюсь в мире." }, { 28.54, "Желаю удачи." }, { 29.53, "Она тебе понадобится!" } } }, t = { d = 19.1, v = "orc-male", n = { x = 196 }, c = { x = { { 0.00, "Это проклятие пало на нас всего лишь из-за медальона." }, { 4.43, "Да, Лорд Вальтхалак умеет быть злопамятным." }, { 7.90, "Мы постараемся найти остальные части – надеюсь, прежде чем меня настигнет безвременная смерть." }, { 15.58, "Но сначала давай разберёмся с твоей наградой." } } } } },
