    [8960] = { d = 23.6, v = "human-female", n = { x = 282 }, c = { x = { { 0.00, "Значит, нам нужно найти недостающие части и собрать медальон?" }, { 4.27, "Но разыскать Бодли будет непросто." }, { 6.68, "Он отправился к Чёрной горе, хотел ещё раз проникнуть в Пик Чёрной горы." }, { 11.50, "И до сих пор не вернулся." }, { 13.17, "Боюсь, как бы с ним не случилось беды." }, { 15.77, "На всякий случай возьми с собой спектральный сканер иных измерений." }, { 20.46, "Лучше заранее приготовиться к самому худшему..." } } }, npc = { [16012] = { d = 25.7, v = "orc-male", n = { x = 282 }, c = { x = { { 0.00, "Значит, нам нужно найти недостающие части и собрать медальон?" }, { 4.64, "Но разыскать Бодли будет непросто." }, { 7.26, "Он отправился к Чёрной горе, хотел ещё раз проникнуть в Пик Чёрной горы." }, { 12.51, "И до сих пор не вернулся." }, { 14.33, "Боюсь, как бы с ним не случилось беды." }, { 17.15, "На всякий случай возьми с собой спектральный сканер иных измерений." }, { 22.26, "Лучше заранее приготовиться к самому худшему..." } } } } }, t = { d = 36.0, g = 1, v = "gnome-male", n = { m = 386, f = 387 }, c = { m = { { 0.00, "Ты себе даже не представляешь, как я рад, что меня видят и слышат!" }, { 4.75, "Наконец я дождался кого-то, с кем можно поговорить!" }, { 8.46, "Ты нам поможешь?" }, { 9.63, "Мы сами не ведали, что творили, и совершили великое зло, а теперь должны всё исправить." }, { 15.88, "Если ты сказал правду и у тебя действительно есть верхняя часть амулета Лорда Вальтхалака, я могу подсказать, где найти две оставшиеся части." }, { 26.03, "Тогда амулет вновь обретёт свою целостность, и весь этот ужас закончится." }, { 31.31, "Да, кстати, меня зовут Бодли." }, { 33.52, "Будем знакомы!" } }, f = { { 0.00, "Ты себе даже не представляешь, как я рад, что меня видят и слышат!" }, { 4.94, "Наконец я дождался кого-то, с кем можно поговорить!" }, { 8.80, "Ты нам поможешь?" }, { 10.02, "Мы сами не ведали, что творили, и совершили великое зло, а теперь должны всё исправить." }, { 16.51, "Если ты сказала правду и у тебя действительно есть верхняя часть амулета Лорда Вальтхалака, я могу подсказать, где найти две оставшиеся части." }, { 27.14, "Тогда амулет вновь обретёт свою целостность, и весь этот ужас закончится." }, { 32.62, "Да, кстати, меня зовут Бодли." }, { 34.92, "Будем знакомы!" } } } } },
    [8961] = { d = 42.4, g = 1, v = "gnome-male", n = { m = 476, f = 477 }, c = { m = { { 0.00, "Для того чтобы вызвать Лорда Вальтхалака, первым делом нам нужно собрать амулет воедино." }, { 6.55, "Одна часть у нас есть, ещё двух не хватает." }, { 9.56, "Для того чтобы собрать эти части, нам нужно добыть жаровню и особые угли, чтобы зажечь в ней огонь." }, { 16.95, "Ты, может быть, слышал о трёх властелинах огня." }, { 20.36, "Это Лорд Огнеус из Глубин Чёрной горы, Пиростраж Созерцатель Углей из Пика Чёрной горы и Герцог Пепла из Силитуса." }, { 28.67, "Убей их, возьми от каждого по одному углю и принеси их сюда вместе с жаровней Благословения, которую можно купить у приспешников Серебряного Рассвета, если ты пользуешься среди них уважением." } }, f = { { 0.00, "Для того чтобы вызвать Лорда Вальтхалака, первым делом нам нужно собрать амулет воедино." }, { 6.45, "Одна часть у нас есть, ещё двух не хватает." }, { 9.42, "Для того чтобы собрать эти части, нам нужно добыть жаровню и особые угли, чтобы зажечь в ней огонь." }, { 16.70, "Ты, может быть, слышала о трёх властелинах огня." }, { 19.94, "Это Лорд Огнеус из Глубин Чёрной горы, Пиростраж Созерцатель Углей из Пика Чёрной горы и Герцог Пепла из Силитуса." }, { 28.60, "Убей их, возьми от каждого по одному углю и принеси их сюда вместе с жаровней Благословения, которую можно купить у приспешников Серебряного Рассвета, если ты пользуешься среди них уважением." } } } },
    [8962] = { d = 35.0, g = 1, v = "gnome-male", n = { m = 402, f = 403 }, c = { m = { { 0.00, "Герой, слушай внимательно." }, { 1.86, "Теперь у нас есть жаровня и всё, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 11.43, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моего павшего соратника." }, { 17.45, "У Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов." }, { 27.33, "Мне нужно, чтобы ты забрал останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса." } }, f = { { 0.00, "Героиня, слушай внимательно." }, { 2.00, "Теперь у нас есть жаровня и всё, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 11.62, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моего павшего соратника." }, { 17.68, "У Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов." }, { 27.62, "Мне нужно, чтобы ты забрала останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса." } } }, t = { d = 21.9, v = "gnome-male", n = { x = 250 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.18, "Я перенесу сущность останков в жаровню." }, { 4.07, "Теперь осталось лишь отправиться в нижнюю часть пика Чёрной горы, в покои воеводы Вуна в Тазз'Алаоре, и с помощью жаровни призвать осквернённый дух моего бывшего соратника Мора Серое Копыто." }, { 17.86, "Он не обретёт покоя, пока у него не заберут часть амулета." } } } } },
    [8963] = { d = 32.2, g = 1, v = "gnome-male", n = { x = 359 }, c = { m = { { 0.00, "Герой, слушай внимательно." }, { 1.96, "Теперь у нас есть жаровня и всё, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 12.04, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моей павшей соратницы." }, { 18.25, "Изалиен, наша жрица, выросла в Зимних Ключах в Деревне Звёздного Ветра." }, { 23.49, "Забери реликвию Деревни Звёздного Ветра у великанов ледяного молота в теснине Ледяного Шёпота в южной части Зимних Ключей." } }, f = { { 0.00, "Героиня, слушай внимательно." }, { 2.09, "Теперь у нас есть жаровня и всё, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 12.12, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моей павшей соратницы." }, { 18.31, "Изалиен, наша жрица, выросла в Зимних Ключах в Деревне Звёздного Ветра." }, { 23.52, "Забери реликвию Деревни Звёздного Ветра у великанов ледяного молота в теснине Ледяного Шёпота в южной части Зимних Ключей." } } }, t = { d = 20.2, v = "gnome-male", n = { x = 247 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.14, "Я перенесу сущность реликвии в жаровню." }, { 3.92, "Теперь осталось лишь отправиться в Святилище Эльдретарра в восточном крыле Забытого Города и с помощью жаровни призвать дух моей бывшей соратницы Изалиен." }, { 14.75, "Её дух осквернён частью амулета Вальтхалака и заключённой в ней частицей его души." } } } } },
    [8964] = { d = 39.5, g = 1, v = "gnome-male", n = { x = 446 }, c = { m = { { 0.00, "Герой, слушай внимательно." }, { 1.95, "Теперь у нас есть жаровня и всё, что нужно, чтобы зажечь в ней огонь." }, { 6.88, "Но нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 11.94, "Нам нужно что-то, что сосредоточит великую силу и привлечёт духов моих бывших соратников." }, { 18.37, "Джариен и Сотос оставили нас и решили присоединиться к Алому ордену, свято уверовав в его путь." }, { 25.25, "Они так стремились вступить в эту подлую организацию... но не прошли испытания на посвящении." }, { 31.94, "Отправляйся в Длань Тира в Восточных Чумных землях и забери бриллиантовый меч Фанатизма у тамошних преторов." } }, f = { { 0.00, "Героиня, слушай внимательно." }, { 2.03, "Теперь у нас есть жаровня и всё, что нужно, чтобы зажечь в ней огонь." }, { 6.86, "Но нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 11.82, "Нам нужно что-то, что сосредоточит великую силу и привлечёт духов моих бывших соратников." }, { 18.11, "Джариен и Сотос оставили нас и решили присоединиться к Алому ордену, свято уверовав в его путь." }, { 24.84, "Они так стремились вступить в эту подлую организацию... но не прошли испытания на посвящении." }, { 31.38, "Отправляйся в Длань Тира в Восточных Чумных землях и забери бриллиантовый меч Фанатизма у тамошних преторов." } } }, t = { d = 20.3, v = "gnome-male", n = { x = 248 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.13, "Я перенесу сущность меча в жаровню." }, { 3.63, "Теперь осталось лишь пробраться к Багровому трону в Багровом бастионе Стратхольма и с помощью жаровни призвать останки моих бывших соратников, Джариена и Сотоса." }, { 14.83, "Их души ещё сильнее искажены частью амулета Вальтхалака и заключённым в ней духом." } } } } },
    [8965] = { d = 33.1, g = 1, v = "gnome-male", n = { x = 362 }, c = { m = { { 0.00, "Герой, слушай внимательно." }, { 1.95, "Теперь у нас есть жаровня и всё, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 11.96, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моего павшего товарища." }, { 18.20, "Кормок, огр-некромант, путешествовавший вместе с нами, любил призывать души изгнанных мертвецов с острова Очищения у южного побережья предгорий Хилсбрада." }, { 30.14, "Иди туда и добудь пепел душ Изгнанников." } }, f = { { 0.00, "Героиня, слушай внимательно." }, { 2.08, "Теперь у нас есть жаровня и всё, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 12.10, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моего павшего товарища." }, { 18.35, "Кормок, огр-некромант, путешествовавший вместе с нами, любил призывать души изгнанных мертвецов с острова Очищения у южного побережья предгорий Хилсбрада." }, { 30.22, "Иди туда и добудь пепел душ Изгнанников." } } }, t = { d = 22.8, v = "gnome-male", n = { x = 264 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.17, "Я перенесу сущность праха в жаровню." }, { 3.85, "Теперь осталось лишь пробраться в Некроситет, в покои Раса Ледяного Шёпота, и с помощью жаровни призвать дух моего бывшего соратника Кормока." }, { 14.01, "Часть амулета и заключённый в ней дух Вальтхалака осквернили его ещё сильнее, и он не успокоится, пока ты не отнимешь её силой." } } } } },
    [8966] = { d = 35.4, v = "gnome-male", n = { x = 418 }, c = { x = { { 0.00, "Мой товарищ Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пал жертвой разрушительных чар осколка души владыки, заключённого внутри." }, { 11.90, "После того как мы выкрали книгу заклинаний Вальтхалака и амулет, мы бежали из верхних пределов Пика Чёрной горы, спасая свои жизни." }, { 21.16, "По пути Мор сорвался и упал в нижнюю часть Пика." }, { 24.56, "Потом мы узнали, что он не разбился, но его захватил и подверг страшным пыткам воевода Вун." }, { 30.92, "Призрачные убийцы пробрались к нему и убили его на глазах у Вуна." } } }, t = { d = 24.6, g = 1, v = "gnome-male", n = { m = 268, f = 269 }, c = { m = { { 0.00, "Ты совершил великое дело." }, { 1.87, "Один дух обрёл покой, но нам ещё многое предстоит сделать, прежде чем со всем этим будет покончено." }, { 8.89, "К сожалению, я не знаю, где покоится тот, кто погиб с нужной частью амулета." }, { 14.30, "Но не бойся: при жизни я баловался гаданием, так что у меня есть для тебя ещё одно поручение – оно поможет нам отыскать последнюю часть." } }, f = { { 0.00, "Ты совершила великое дело." }, { 1.99, "Один дух обрёл покой, но нам ещё многое предстоит сделать, прежде чем со всем этим будет покончено." }, { 9.23, "К сожалению, я не знаю, где покоится тот, кто погиб с нужной частью амулета." }, { 14.81, "Но не бойся: при жизни я баловался гаданием, так что у меня есть для тебя ещё одно поручение – оно поможет нам отыскать последнюю часть." } } } } },
    [8967] = { d = 34.3, v = "gnome-male", n = { x = 422 }, c = { x = { { 0.00, "Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее поселение своего народа, известное теперь под названием Забытый Город." }, { 11.79, "Насколько нам удалось узнать, она отправилась в Забытый Город как по личным причинам, так и за тем, чтобы вызнать секреты той части амулета Лорда Вальтхалака, которую она забрала с собой." }, { 24.23, "Но её замыслам не суждено было сбыться." }, { 26.50, "До нас дошли слухи, что у святилища Элдретарра Изалиен попала в засаду, которую устроил Алззин Перевертень." } } }, t = { d = 26.8, g = 1, v = "gnome-male", n = { m = 310, f = 311 }, c = { m = { { 0.00, "Спасибо тебе, за то, что упокоил дух Изалиен." }, { 3.13, "Быть может, теперь она обретёт мир со своей богиней." }, { 6.77, "Но нам ещё немало предстоит сделать, если мы хотим выпутаться из этой передряги." }, { 12.34, "К сожалению, я не знаю, где покоится тот, кто погиб с нужной частью амулета." }, { 17.61, "Но не бойся: при жизни я баловался гаданием, так что у меня есть для тебя ещё одно поручение – оно поможет нам отыскать последнюю часть." } }, f = { { 0.00, "Спасибо тебе, за то, что упокоила дух Изалиен." }, { 3.15, "Быть может, теперь она обретёт мир со своей богиней." }, { 6.73, "Но нам ещё немало предстоит сделать, если мы хотим выпутаться из этой передряги." }, { 12.23, "К сожалению, я не знаю, где покоится тот, кто погиб с нужной частью амулета." }, { 17.42, "Но не бойся: при жизни я баловался гаданием, так что у меня есть для тебя ещё одно поручение – оно поможет нам отыскать последнюю часть." } } } } },
    [8968] = { d = 39.6, g = 1, v = "gnome-male", n = { m = 433, f = 433 }, c = { m = { { 0.00, "Наши бывшие соратники, брат с сестрой Сотос и Джариен, решили присоединиться к Алому ордену." }, { 6.46, "Они ушли и забрали с собой левую часть амулета Лорда Вальтхалака." }, { 11.10, "Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас её надо вернуть." }, { 18.77, "Насколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в Бастионе Алого ордена, и Верховный рыцарь собственноручно прикончил обоих." }, { 32.29, "Как бы там ни было, нам нужна эта часть амулета, и мы... то есть ты должен будешь её забрать." } }, f = { { 0.00, "Наши бывшие соратники, брат с сестрой Сотос и Джариен, решили присоединиться к Алому ордену." }, { 6.73, "Они ушли и забрали с собой левую часть амулета Лорда Вальтхалака." }, { 11.56, "Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас её надо вернуть." }, { 19.57, "Насколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в Бастионе Алого ордена, и Верховный рыцарь собственноручно прикончил обоих." }, { 33.13, "Как бы там ни было, нам нужна эта часть амулета, и мы... то есть ты должна будешь её забрать." } } }, t = { d = 33.0, v = "gnome-male", n = { x = 368 }, c = { x = { { 0.00, "Я рад, что души этих двоих наконец обрели покой, хотя, признаться, при жизни я их недолюбливал." }, { 6.94, "Как бы там ни было, теперь у нас есть левая часть амулета, что, безусловно, не может не радовать!" }, { 13.81, "К сожалению, мне неизвестно, где сейчас владелец правой части амулета." }, { 18.92, "Но не бойся; при жизни я изучал прорицательское искусство и кое-что понимаю в гадании и ворожбе." }, { 25.85, "У меня есть для тебя поручение." }, { 28.15, "Если справишься с ним, мы сумеем узнать, где искать недостающую часть." } } } } },
    [8969] = { d = 33.2, v = "gnome-male", n = { x = 398 }, c = { x = { { 0.00, "Теперь, когда у нас есть всё, что нужно для ритуала призыва, осталось решить, кого именно вызвать." }, { 6.63, "Кормок был неплохим парнем, пока не занялся некромантией." }, { 10.53, "Вот тогда нам всем стало по-настоящему жутко – и это при том, что отряд набирали уж явно не из боязливых юнцов и кисейных барышень." }, { 19.29, "Никто не удивился, когда он забрал свою часть амулета и вернулся в свой новый дом в Некроситете." }, { 25.74, "Но даже там он не укрылся от призрачных убийц." }, { 28.84, "Они прикончили его на глазах у Раса Ледяного Шёпота, его хозяина." } } }, t = { d = 26.2, v = "gnome-male", n = { x = 297 }, c = { x = { { 0.00, "Хорошая работа!" }, { 1.14, "Для огра Кормок был не так уж плох – по крайней мере, пока был жив, – так что надеюсь, он обретёт заслуженный покой." }, { 9.09, "Но нам предстоит ещё немало работы." }, { 11.57, "К сожалению, я не знаю, где покоится тот, кто погиб с нужной частью амулета." }, { 16.91, "Но не бойся: при жизни я баловался гаданием, так что у меня есть для тебя ещё одно поручение – оно поможет нам отыскать последнюю часть." } } } } },
    [8970] = { d = 39.5, g = 1, v = "gnome-male", n = { x = 422 }, c = { m = { { 0.00, "Как я уже говорил, герой, при жизни я изучал ворожбу и гадание и даже подумывал о том, чтобы пойти в прорицатели или провидцы." }, { 9.31, "Но это не самое прибыльное занятие." }, { 11.95, "Во-первых, неблагодарное и опасное." }, { 14.53, "А во-вторых, реактивы редки и недешевы." }, { 17.43, "Однако я кое-чему научился, и моих знаний хватит, чтобы найти последнюю часть амулета, а вместе с нею – и дух моего павшего соратника." }, { 27.98, "Но мне понадобится твоя помощь." }, { 30.30, "Отправляйся на остров Алькац у побережья Пылевых топей и собери кровавую ламинарию у наг из клана Страшаз, которые там обитают." } }, f = { { 0.00, "Как я уже говорил, героиня, при жизни я изучал ворожбу и гадание и даже подумывал о том, чтобы пойти в прорицатели или провидцы." }, { 9.08, "Но это не самое прибыльное занятие." }, { 11.62, "Во-первых, неблагодарное и опасное." }, { 14.10, "А во-вторых, реактивы редки и недешевы." }, { 16.89, "Однако я кое-чему научился, и моих знаний хватит, чтобы найти последнюю часть амулета, а вместе с нею – и дух моего павшего соратника." }, { 27.09, "Но мне понадобится твоя помощь." }, { 29.31, "Отправляйся на остров Алькац у побережья Пылевых топей и собери кровавую ламинарию у наг из клана Страшаз, которые там обитают." } } }, t = { d = 17.1, g = 1, v = "gnome-male", n = { m = 177, f = 178 }, c = { m = { { 0.00, "Честно говоря, я удивлён, что ты вернулся целым и невредимым." }, { 4.63, "Хотя, наверное, остров Алькац сейчас – наименьшая из твоих забот." }, { 9.74, "Ладно, дай мне минутку... гадание – это не то, где щёлкнешь пальцами и сразу получишь точный ответ." } }, f = { { 0.00, "Честно говоря, я удивлён, что ты вернулась целой и невредимой." }, { 4.53, "Хотя, наверное, остров Алькац сейчас – наименьшая из твоих забот." }, { 9.45, "Ладно, дай мне минутку... гадание – это не то, где щёлкнешь пальцами и сразу получишь точный ответ." } } } } },
    [8977] = { d = 13.8, v = "goblin-male", n = { x = 151 }, c = { x = { { 0.00, "С тобой здорово сотрудничать." }, { 2.22, "Вот готовое изделие." }, { 3.77, "Надеюсь, оно поможет тебе в твоих дальнейших подвигах." }, { 7.94, "Да, и если ты не против, рассказывай всем обо мне." }, { 11.63, "Мне лишние клиенты не помешают!" } } }, t = { d = 8.3, g = 1, v = "human-female", n = { m = 76, f = 77 }, c = { m = { { 0.00, "Блестяще!" }, { 0.88, "Ты на славу постарался." }, { 2.96, "Хотя я гоблинским изделиям и не доверяю, но выбора у меня нет." } }, f = { { 0.00, "Блестяще!" }, { 0.84, "Ты на славу постаралась." }, { 2.90, "Хотя я гоблинским изделиям и не доверяю, но выбора у меня нет." } } } } },
    [8978] = { d = 13.7, v = "goblin-male", n = { x = 150 }, c = { x = { { 0.00, "Приятно было поработать с тобой!" }, { 2.44, "Вот, твой заказ готов." }, { 4.08, "Надеюсь, мои изделия тебе пригодятся." }, { 6.91, "И кстати, если ты не против, расскажи обо мне другим." }, { 10.86, "Лишние заказчики мне совсем не помешают!" } } }, t = { d = 6.0, v = "orc-male", n = { x = 40 }, c = { x = { { 0.00, "Он у тебя!" }, { 1.30, "Ты молодец." }, { 2.71, "Я впечатлён." }, { 4.13, "Отличная работа!" } } } } },
    [8979] = { d = 36.7, v = "scourge-male#82", n = { x = 359 }, c = { x = { { 0.00, "Кажется, я понял причину странностей, происходящих в последнее время." }, { 5.65, "Ты чувствуешь новый запах в воздухе, перебивающий даже вонь от каналов?" }, { 11.30, "Запах новых одеколонов и духов, только что вошедших в моду?" }, { 17.01, "Наш разум затуманен какой-то гнусной алхимией." }, { 20.82, "Есть только один способ убедиться – отнести флакон одеколона и духов аптекарю Зинг." }, { 28.62, "Королевское фармацевтическое общество отыщет истину." }, { 32.87, "Я возмещу тебе цену покупки, когда ты вернёшься." } } }, t = { d = 18.6, v = "scourge-female", n = { x = 176 }, c = { x = { { 0.00, "Понятно, ещё одна навязчивая идея Фенстада." }, { 3.90, "Он что, думает, Королевскому фармацевтическому обществу нечем больше заняться, только проводить для него всякие мелкие расследования?" }, { 15.61, "Ну что ж, ещё раз я потешу его душу." } } } } },
    [8980] = { d = 30.2, v = "scourge-female", n = { x = 279 }, c = { x = { { 0.00, "Это неожиданно." }, { 1.47, "Похоже, Фенстад в конце концов всё-таки что-то нарыл." }, { 6.36, "Я нашла следы веществ, используемых в зельях контроля над разумом." }, { 12.39, "Известно, что такие вещества используются в некоторых духах, но некоторые из обнаруженных мною ингредиентов..." }, { 22.25, "Это серьёзная алхимия – как раз по силам кому-то из Королевского фармацевтического общества." } } }, t = { d = 13.3, v = "scourge-male#82", n = { x = 123 }, c = { x = { { 0.00, "Так я был прав!" }, { 1.30, "Не следует тратить время зря." }, { 3.99, "Мы должны определить источник этих порочных ароматов." }, { 8.88, "Вот возмещение за купленные тобою духи и одеколон." } } } } },
    [8981] = { t = { d = 14.5, v = "goblin-male", n = { x = 152 }, c = { x = { { 0.00, "Чудесно!" }, { 0.68, "Замечательно!" }, { 1.69, "Я добавлю это к куче других подарков." }, { 4.61, "Я не ждал, что их будет так много!" }, { 7.11, "Должно быть, вы поистине питаете любовь к своим вождям." }, { 11.31, "Погоди, я добавлю ещё один к общему счёту..." } } } } },
    [8982] = { d = 12.9, v = "scourge-male#82", n = { x = 114 }, c = { x = { { 0.00, "Мы должны узнать, кто поставщик." }, { 2.95, "Я заметил у аптекаря Катрины в сумке флакон духов." }, { 7.63, "Она сказала, что приобрела его у Нормана, хозяина таверны." } } }, t = { d = 17.3, v = "scourge-male#82", n = { x = 159 }, c = { x = { { 0.00, "О да, я лишь недавно получил партию духов и одеколона." }, { 4.73, "Я не знаю, надолго ли они задержатся на полках – похоже, всем эти запахи нравятся." }, { 11.76, "Но если хочешь спросить моё мнение, то я не знаю, что в этом такого." } } } } },
    [8983] = { d = 22.8, v = "scourge-male#82", n = { x = 219 }, c = { x = { { 0.00, "Что-то не так с тем, чем я торгую?" }, { 2.77, "Ну, я никогда не видел, чтобы так много народа столь отчаянно чего-нибудь жаждали." }, { 9.57, "Я покупаю припасы у торговки по имени Мара Ренник." }, { 13.83, "Она в городе недавно." }, { 15.70, "Она упоминала, что хочет доставить кое-какие товары торговцу одеждой в Квартал Магов." } } }, t = { d = 18.6, v = "scourge-female#141", n = { x = 179 }, c = { x = { { 0.00, "Боюсь, я продала всю партию духов и одеколона Норману, хозяину таверны." }, { 6.03, "Если они тебе нужны, поговори с ним – может быть, у него что-то ещё осталось." }, { 12.54, "Но не трать времени." }, { 14.19, "Полагаю, ты сочтёшь запах одеколона просто неотразимым." } } } } },
    [8984] = { d = 30.0, v = "scourge-female#141", n = { x = 312 }, c = { x = { { 0.00, "Видишь ли, действия какого-то негодяя-аптекаря – не моя забота." }, { 5.03, "Если он вредит нашему делу, то я буду первой, кто укажет тебе нужное направление поисков." }, { 12.17, "Если он невиновен, то ему нечего скрывать, верно?" }, { 16.14, "Я приобрела товары у аптекаря Стаффрона Лерента." }, { 19.96, "Он работает в укромном уголке за поместьем Чёрный Ворон в предгорьях Хилсбрада." }, { 26.12, "Честно говоря, он показался мне несколько странным." } } }, t = { d = 40.8, v = "scourge-male#82", n = { x = 355 }, c = { x = { { 0.00, "Да, я сделал эти благовония." }, { 2.69, "Чудный запах, не так ли?" }, { 4.96, "Неотразимый." }, { 6.14, "Когда воины Альянса и Орды равно будут сражены этой любовью, они не смогут остановить воздвижение Совета Тени." }, { 16.74, "Они окажутся ослабленными и неподготовленными." }, { 21.03, "Беспокоясь за тех, кого любят, они потеряют бдительность." }, { 26.41, "Решение было таким простым." }, { 29.10, "Почему понадобилось столько времени, чтобы найти его?" }, { 34.23, "Слабое место любого – его сердце." }, { 37.52, "И тебе уже не остановить неизбежное." } } } } },
    [8985] = { d = 28.6, g = 1, v = "gnome-male", n = { x = 332 }, c = { m = { { 0.00, "Герой, слушай внимательно." }, { 1.90, "Теперь, когда мы знаем, где последняя часть амулета, нам не хватает ещё одной важной вещи для жаровни." }, { 9.04, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моей павшей соратницы." }, { 15.05, "Изалиен, наша жрица, выросла в Зимних Ключах в Деревне Звёздного Ветра." }, { 20.10, "Забери реликвию Деревни Звёздного Ветра у великанов ледяного молота в теснине Ледяного Шёпота в южной части Зимних Ключей." } }, f = { { 0.00, "Героиня, слушай внимательно." }, { 2.00, "Теперь, когда мы знаем, где последняя часть амулета, нам не хватает ещё одной важной вещи для жаровни." }, { 9.08, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моей павшей соратницы." }, { 15.02, "Изалиен, наша жрица, выросла в Зимних Ключах в Деревне Звёздного Ветра." }, { 20.03, "Забери реликвию Деревни Звёздного Ветра у великанов ледяного молота в теснине Ледяного Шёпота в южной части Зимних Ключей." } } }, t = { d = 29.4, v = "gnome-male", n = { x = 361 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.11, "Я перенесу сущность реликвии в жаровню." }, { 3.82, "Теперь осталось лишь отправиться в Святилище Эльдретарра в восточном крыле Забытого Города и с помощью жаровни призвать дух моей бывшей соратницы Изалиен." }, { 14.36, "Её дух осквернён частью амулета Вальтхалака и заключённой в ней частицей его души." }, { 19.84, "Да, кстати, после твоей вылазки на остров Алькац у меня осталось немного кровавых водорослей, так что я сварил из них для тебя зелья." }, { 28.97, "Выбирай!" } } } } },
    [8986] = { d = 32.0, g = 1, v = "gnome-male", n = { m = 375, f = 376 }, c = { m = { { 0.00, "Герой, слушай внимательно." }, { 1.86, "Теперь, когда мы знаем, где последняя часть амулета, нам не хватает ещё одной важной вещи для жаровни." }, { 8.86, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моего павшего соратника." }, { 14.86, "У Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов." }, { 24.71, "Мне нужно, чтобы ты забрал останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса." } }, f = { { 0.00, "Героиня, слушай внимательно." }, { 1.96, "Теперь, когда мы знаем, где последняя часть амулета, нам не хватает ещё одной важной вещи для жаровни." }, { 8.86, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моего павшего соратника." }, { 14.79, "У Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов." }, { 24.51, "Мне нужно, чтобы ты забрала останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса." } } }, t = { d = 30.0, v = "gnome-male", n = { x = 364 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.10, "Я перенесу сущность останков в жаровню." }, { 3.78, "Теперь осталось лишь отправиться в нижнюю часть пика Чёрной горы, в покои воеводы Вуна в Тазз'Алаоре, и с помощью жаровни призвать осквернённый дух моего бывшего соратника Мора Серое Копыто." }, { 16.60, "Он не обретёт покоя, пока у него не заберут часть амулета." }, { 20.50, "Да, кстати, после твоей вылазки на остров Алькац у меня осталось немного кровавых водорослей, так что я сварил из них для тебя зелья." }, { 29.53, "Выбирай!" } } } } },
    [8987] = { d = 30.4, g = 1, v = "gnome-male", n = { x = 354 }, c = { m = { { 0.00, "Герой, слушай внимательно." }, { 1.90, "Теперь, когда мы знаем, где последняя часть амулета, нам не хватает ещё одной важной вещи для жаровни." }, { 9.08, "Нам нужно что-то, что сосредоточит великую силу и привлечёт духов моих бывших соратников." }, { 15.37, "Брат и сестра Джариен и Сотос верили в путь Алого ордена и мечтали стать рыцарями в этой подлой организации." }, { 22.99, "Отправляйся в Длань Тира в Восточных Чумных землях и забери бриллиантовый меч Фанатизма у тамошних преторов." } }, f = { { 0.00, "Героиня, слушай внимательно." }, { 2.00, "Теперь, когда мы знаем, где последняя часть амулета, нам не хватает ещё одной важной вещи для жаровни." }, { 9.07, "Нам нужно что-то, что сосредоточит великую силу и привлечёт духов моих бывших соратников." }, { 15.27, "Брат и сестра Джариен и Сотос верили в путь Алого ордена и мечтали стать рыцарями в этой подлой организации." }, { 22.78, "Отправляйся в Длань Тира в Восточных Чумных землях и забери бриллиантовый меч Фанатизма у тамошних преторов." } } }, t = { d = 29.8, v = "gnome-male", n = { x = 362 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.11, "Я перенесу сущность меча в жаровню." }, { 3.58, "Теперь осталось лишь пробраться к Багровому трону в Багровом бастионе Стратхольма и с помощью жаровни призвать останки моих бывших соратников, Джариена и Сотоса." }, { 14.61, "Их души ещё сильнее искажены частью амулета Вальтхалака и заключённым в ней духом." }, { 20.16, "Да, кстати, после твоей вылазки на остров Алькац у меня осталось немного кровавых водорослей, так что я сварил из них для тебя зелья." }, { 29.29, "Выбирай!" } } } } },
    [8988] = { d = 32.3, g = 1, v = "gnome-male", n = { x = 365 }, c = { m = { { 0.00, "Герой, слушай внимательно." }, { 1.90, "Теперь мы знаем, где искать последний фрагмент амулета, но для жаровни нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 11.56, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моего павшего товарища." }, { 17.63, "Кормок, огр-некромант, путешествовавший вместе с нами, любил призывать души изгнанных мертвецов с острова Очищения у южного побережья предгорий Хилсбрада." }, { 29.46, "Иди туда и добудь пепел душ Изгнанников." } }, f = { { 0.00, "Героиня, слушай внимательно." }, { 2.00, "Теперь мы знаем, где искать последний фрагмент амулета, но для жаровни нам не хватает одной важной вещи, чтобы всё получилось, как должно." }, { 11.58, "Нам нужно что-то, что сосредоточит великую силу и привлечёт дух моего павшего товарища." }, { 17.60, "Кормок, огр-некромант, путешествовавший вместе с нами, любил призывать души изгнанных мертвецов с острова Очищения у южного побережья предгорий Хилсбрада." }, { 29.56, "Иди туда и добудь пепел душ Изгнанников." } } }, t = { d = 33.2, v = "gnome-male", n = { x = 378 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.18, "Я перенесу сущность праха в жаровню." }, { 3.86, "Теперь осталось лишь пробраться в Некроситет, в покои Раса Ледяного Шёпота, и с помощью жаровни призвать дух моего бывшего соратника Кормока." }, { 14.06, "Часть амулета и заключённый в ней дух Вальтхалака осквернили его ещё сильнее, и он не успокоится, пока ты не отнимешь её силой." }, { 23.01, "Да, кстати, после твоей вылазки на остров Алькац у меня осталось немного кровавых водорослей, так что я сварил из них для тебя зелья." }, { 32.69, "Выбирай!" } } } } },
    [8989] = { d = 35.0, v = "gnome-male", n = { x = 416 }, c = { x = { { 0.00, "Мой товарищ Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пал жертвой разрушительных чар осколка духа Лорда, заключённого внутри." }, { 11.69, "После того как мы выкрали книгу заклинаний Вальтхалака и амулет, мы бежали из верхних пределов Пика Чёрной горы, спасая свои жизни." }, { 20.87, "По пути Мор сорвался и упал в нижнюю часть Пика." }, { 24.25, "Потом мы узнали, что он не разбился, но его захватил и подверг страшным пыткам воевода Вун." }, { 30.56, "Призрачные убийцы пробрались к нему и убили его на глазах у Вуна." } } }, t = { d = 18.8, g = 1, v = "gnome-male", n = { m = 199, f = 201 }, c = { m = { { 0.00, "Спасибо, что помог Мору Серое Копыто." }, { 3.00, "Ещё один дух обрёл покой, и теперь амулет снова собран!" }, { 7.32, "Но самое трудное испытание ещё впереди." }, { 10.38, "Чтобы настроить жаровню на призыв Лорда Вальтхалака, нужно собрать ещё несколько вещей и принести их мне сюда." } }, f = { { 0.00, "Спасибо, что помогла Мору Серое Копыто." }, { 3.03, "Ещё один дух обрёл покой, и теперь амулет снова собран!" }, { 7.21, "Но самое трудное испытание ещё впереди." }, { 10.18, "Чтобы настроить жаровню на призыв Лорда Вальтхалака, нужно собрать ещё несколько вещей и принести их мне сюда." } } } } },
    [8990] = { d = 34.9, v = "gnome-male", n = { x = 422 }, c = { x = { { 0.00, "Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее поселение своего народа, известное теперь под названием Забытый Город." }, { 12.01, "Насколько нам удалось узнать, она отправилась в Забытый Город как по личным причинам, так и за тем, чтобы вызнать секреты той части амулета Лорда Вальтхалака, которую она забрала с собой." }, { 24.69, "Но её замыслам не суждено было сбыться." }, { 27.07, "До нас дошли слухи, что у святилища Элдретарра Изалиен попала в засаду, которую устроил Алззин Перевертень." } } }, t = { d = 20.2, g = 1, v = "gnome-male", n = { m = 222, f = 223 }, c = { m = { { 0.00, "Спасибо тебе, за то, что упокоил дух Изалиен." }, { 3.34, "Быть может, теперь она обретёт мир со своей богиней." }, { 7.21, "И амулет мы тоже собрали!" }, { 9.15, "Но самое трудное испытание ещё впереди." }, { 12.09, "Чтобы настроить жаровню на призыв Лорда Вальтхалака, нужно собрать ещё несколько вещей и принести их мне сюда." } }, f = { { 0.00, "Спасибо тебе, за то, что упокоила дух Изалиен." }, { 3.36, "Быть может, теперь она обретёт мир со своей богиней." }, { 7.17, "И амулет мы тоже собрали!" }, { 9.08, "Но самое трудное испытание ещё впереди." }, { 11.97, "Чтобы настроить жаровню на призыв Лорда Вальтхалака, нужно собрать ещё несколько вещей и принести их мне сюда." } } } } },
    [8991] = { d = 37.1, g = 1, v = "gnome-male", n = { m = 427, f = 427 }, c = { m = { { 0.00, "Наши бывшие соратники Сотос и Джариен некогда решили вступить в ряды Алого ордена." }, { 5.90, "Уходя, они забрали с собой правую часть амулета Лорда Вальтхалака." }, { 10.60, "Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас её надо вернуть." }, { 18.31, "Насколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в Бастионе Алого ордена, и Верховный рыцарь собственноручно прикончил обоих." }, { 30.42, "Как бы там ни было, нам нужна эта часть амулета, и мы... то есть ты... должен будешь её забрать." } }, f = { { 0.00, "Наши бывшие соратники Сотос и Джариен некогда решили вступить в ряды Алого ордена." }, { 5.95, "Уходя, они забрали с собой правую часть амулета Лорда Вальтхалака." }, { 10.69, "Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас её надо вернуть." }, { 18.47, "Насколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в Бастионе Алого ордена, и Верховный рыцарь собственноручно прикончил обоих." }, { 30.68, "Как бы там ни было, нам нужна эта часть амулета, и мы... то есть ты... должна будешь её забрать." } } }, t = { d = 23.4, v = "gnome-male", n = { x = 259 }, c = { x = { { 0.00, "Пожалуй, оно и к лучшему, что души этих двоих наконец упокоились, хоть при жизни я их и недолюбливал." }, { 7.37, "Так или иначе, мы получили, что хотели, и теперь амулет снова собран!" }, { 12.51, "Но самое трудное испытание ещё впереди." }, { 15.41, "Чтобы настроить жаровню на призыв Лорда Вальтхалака, нужно собрать ещё несколько вещей и принести их мне сюда." } } } } },
    [8992] = { d = 33.4, v = "gnome-male", n = { x = 398 }, c = { x = { { 0.00, "Теперь, когда у нас есть всё, что нужно для ритуала призыва, осталось решить, кого именно вызвать." }, { 6.66, "Кормок был неплохим парнем, пока не занялся некромантией." }, { 10.58, "Вот тогда нам всем стало по-настоящему жутко – и это при том, что отряд набирали уж явно не из боязливых юнцов и кисейных барышень." }, { 19.38, "Никто не удивился, когда он забрал свою часть амулета и вернулся в свой новый дом в Некроситете." }, { 25.86, "Но даже там он не укрылся от призрачных убийц." }, { 28.98, "Они прикончили его на глазах у Раса Ледяного Шёпота, его хозяина." } } }, t = { d = 22.4, v = "gnome-male", n = { x = 253 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.25, "Кормок был не так уж плох для огра, по крайней мере пока был жив, так что надеюсь, он обретёт заслуженный покой." }, { 9.20, "И теперь амулет собран целиком!" }, { 11.57, "Но самое трудное испытание ещё впереди." }, { 14.46, "Чтобы настроить жаровню на призыв Лорда Вальтхалака, нужно собрать ещё несколько вещей и принести их мне сюда." } } } } },
    [8993] = { t = { d = 15.4, v = "goblin-male", n = { x = 159 }, c = { x = { { 0.00, "Чудесно!" }, { 0.69, "Замечательно!" }, { 1.73, "Я добавлю это к куче других подарков." }, { 4.71, "Я не ждал, что их будет так много!" }, { 7.28, "Должно быть, вы поистине питаете великую любовь к своим вождям." }, { 12.19, "Погоди, я добавлю ещё один к общему счёту..." } } } } },
    [8994] = { d = 38.1, g = 1, v = "gnome-male", n = { x = 428 }, c = { m = { { 0.00, "У нас почти всё готово, герой." }, { 2.13, "Осталось найти ещё несколько компонентов, и тогда я смогу должным образом настроить жаровню и вызвать дух Лорда Вальтхалака." }, { 10.77, "Для начала я попрошу тебя отправиться в Пик Чёрной горы и перебить тамошних орков." }, { 16.47, "Они носят наручи из особого сплава металлов, один из которых как раз мне и нужен." }, { 22.99, "Постарайся собрать их как можно больше, чтобы я смог извлечь необходимое количество металла." }, { 29.38, "И ещё мне понадобится склянка Великой силы." }, { 32.39, "Без неё я не смогу завершить заклинание." }, { 35.14, "Иди, и да пребудет с тобой удача!" } }, f = { { 0.00, "У нас почти всё готово, героиня." }, { 2.29, "Осталось найти ещё несколько компонентов, и тогда я смогу должным образом настроить жаровню и вызвать дух Лорда Вальтхалака." }, { 11.05, "Для начала я попрошу тебя отправиться в Пик Чёрной горы и перебить тамошних орков." }, { 16.83, "Они носят наручи из особого сплава металлов, один из которых как раз мне и нужен." }, { 23.50, "Постарайся собрать их как можно больше, чтобы я смог извлечь необходимое количество металла." }, { 29.98, "И ещё мне понадобится склянка Великой силы." }, { 33.03, "Без неё я не смогу завершить заклинание." }, { 35.82, "Иди, и да пребудет с тобой удача!" } } } },
    [8995] = { d = 40.7, g = 1, v = "gnome-male", n = { m = 469, f = 469 }, c = { m = { { 0.00, "Теперь всё готово." }, { 1.35, "При жизни Лорд Вальтхалак жил в чертоге, который теперь называется чертогом Зверя." }, { 7.17, "Отправляйся туда, зажги огонь в жаровне Призыва и вызови дух владыки." }, { 12.17, "При этом Вальтхалак вновь обретёт тело, и тебе придётся убить его ещё раз." }, { 17.36, "Но сначала тебе нужно сразиться со Зверем владыки, так что лучше иди не один, а возьми себе в помощь верных друзей, ибо немногие возвращались из верхних пределов Пика Чёрной горы живыми." }, { 30.74, "Когда убьёшь Вальтхалака, используй амулет." }, { 33.82, "Как только дух Лорда обретёт целостность, он потребует вернуть ему амулет." }, { 39.07, "И это его право!" }, { 40.35, "Удачи!" } }, f = { { 0.00, "Теперь всё готово." }, { 1.33, "При жизни Лорд Вальтхалак жил в чертоге, который теперь называется чертогом Зверя." }, { 7.12, "Отправляйся туда, зажги огонь в жаровне Призыва и вызови дух владыки." }, { 12.07, "При этом Вальтхалак вновь обретёт тело, и тебе придётся убить его ещё раз." }, { 17.22, "Но сначала тебе нужно сразиться со Зверем владыки, так что лучше иди не одна, а возьми себе в помощь верных друзей, ибо немногие возвращались из верхних пределов Пика Чёрной горы живыми." }, { 30.50, "Когда убьёшь Вальтхалака, используй амулет." }, { 33.55, "Как только дух Лорда обретёт целостность, он потребует вернуть ему амулет." }, { 38.76, "И это его право!" }, { 40.04, "Удачи!" } } }, t = { d = 15.7, v = "creature/valthalak", n = { x = 123 }, c = { x = { { 0.00, "Твоё счастье, смертный, что тебя не было среди тех подонков, которые украли мой амулет." }, { 8.99, "Теперь я возьму то, что принадлежит мне по праву!" }, { 14.00, "Отдай мне амулет!" } } } } },
    [8996] = { d = 42.9, g = 1, v = "creature/valthalak", n = { m = 309, f = 312 }, c = { m = { { 0.00, "На сей раз я прощаю тебе твою дерзость, герой, потому что сегодня ты совершил благородный поступок: вернул мне недостающие части моей украденной души." }, { 15.91, "Быть может, тебе не хватает телесной мощи, путник, но ты крепок духом, смел и отважен, в отличие от тех, кто украл мою душу!" }, { 29.05, "Возвращайся к ним, пока я не передумал и не прикончил тебя на месте." }, { 36.20, "Иди к ним и скажи, что им ничего не грозит... до поры до времени." } }, f = { { 0.00, "На сей раз я прощаю тебе твою дерзость, героиня, потому что сегодня ты совершила благородный поступок: вернула мне недостающие части моей украденной души." }, { 15.92, "Быть может, тебе не хватает телесной мощи, путница, но ты крепка духом, смела и отважна, в отличие от тех, кто украл мою душу!" }, { 29.05, "Возвращайся к ним, пока я не передумал и не прикончил тебя на месте." }, { 36.03, "Иди к ним и скажи, что им ничего не грозит... до поры до времени." } } }, t = { d = 29.0, g = 1, v = "gnome-male", n = { m = 329, f = 331 }, c = { m = { { 0.00, "Он правда всё это сказал?" }, { 1.85, "Ух ты, не верится, что он отзовёт призрачных убийц и преследователей, пусть даже и намекнул, что ещё навредит моим живым товарищам." }, { 10.92, "Это великий день!" }, { 12.20, "Ты сделал то, что мало кому под силу, и хотя бы отчасти снял с нас бремя прошлых грехов." }, { 18.46, "Спасибо!" }, { 19.09, "В знак признательности я хочу подарить тебе вот это." }, { 22.80, "С его помощью ты сможешь призывать духов в тех же местах, что и раньше, и ещё в нескольких." } }, f = { { 0.00, "Он правда всё это сказал?" }, { 1.79, "Ух ты, не верится, что он отзовёт призрачных убийц и преследователей, пусть даже и намекнул, что ещё навредит моим живым товарищам." }, { 10.55, "Это великий день!" }, { 11.78, "Ты сделала то, что мало кому под силу, и хотя бы отчасти сняла с нас бремя прошлых грехов." }, { 18.02, "Спасибо!" }, { 18.63, "В знак признательности я хочу подарить тебе вот это." }, { 22.21, "С его помощью ты сможешь призывать духов в тех же местах, что и раньше, и ещё в нескольких." } } } } },
    [8997] = { d = 29.0, g = 1, v = "gnome-male", n = { m = 314, f = 326 }, c = { m = { { 0.00, "Как это ни грустно, дружище, пришло время прощаться." }, { 3.72, "Но если ты вдруг соберёшься меня навестить, я всегда буду рад встрече с другом." }, { 9.21, "Приходи, когда хочешь." }, { 10.85, "Может быть, даже в самое ближайшее время, пока ты ещё не отправился в Пик Чёрной горы." }, { 16.85, "Ладно, долгие проводы – лишние слёзы." }, { 19.50, "Иди, пока я действительно не прослезился." }, { 22.40, "Возвращайся к Делиане в Стальгорн и расскажи ей обо всём, что случилось." } }, f = { { 0.00, "Как это ни грустно, моя госпожа, пришло время прощаться." }, { 4.16, "Но если ты вдруг соберёшься меня навестить, я всегда буду рад встрече с доброй подругой." }, { 10.46, "Приходи, когда хочешь." }, { 12.15, "Может быть, даже в самое ближайшее время, пока ты ещё не отправилась в Пик Чёрной горы." }, { 18.39, "Ладно, долгие проводы – лишние слёзы." }, { 21.11, "Иди, пока я действительно не прослезился." }, { 24.10, "Возвращайся к Делиане в Стальгорн и расскажи ей обо всём, что случилось." } } }, t = { d = 11.6, g = 1, v = "human-female", n = { m = 122, f = 123 }, c = { m = { { 0.00, "Я очень рада, что ты вернулся ко мне целым и невредимым." }, { 4.33, "Выглядишь неплохо, разве что слегка потрёпанным." }, { 8.04, "Иди сюда, расскажи мне обо всём, что случилось." } }, f = { { 0.00, "Я очень рада, что ты вернулась ко мне целой и невредимой." }, { 4.41, "Выглядишь неплохо, разве что слегка потрёпанной." }, { 8.11, "Иди сюда, расскажи мне обо всём, что случилось." } } } } },
