    [9015] = { d = 24.6, v = "nightelf-male#59", n = { x = 286 }, c = { x = { { 0.00, "Слушай внимательно." }, { 1.40, "Тебе нужно будет войти в Зал Правосудия в Глубинах Чёрной горы." }, { 5.92, "Когда верховный судья Мрачнокамень вынесет тебе приговор, вонзи знамя в землю в знак открытого неповиновения." }, { 13.69, "Тельдрен не сможет сдержаться и примет вызов на бой, горя желанием драться." }, { 18.78, "Убей его и забери то, что должно забрать, после чего передай эту вещь Антиону." } } }, t = { d = 2.5, v = "named/16016", n = { x = 31 }, c = { x = { { 0.00, "Тебе удалось добыть часть медальона?" } } } } },
    [9016] = { d = 30.9, v = "named/16016", n = { x = 343 }, c = { x = { { 0.00, "В этом амулете хранилась душа Вальтхалака." }, { 3.15, "Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало." }, { 10.45, "Единственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино." }, { 16.89, "Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части." }, { 23.92, "Расскажи ему про обещанные награды." }, { 26.54, "Ну, а я упокоюсь в мире." }, { 28.32, "Желаю удачи." }, { 29.30, "Она тебе понадобится!" } } }, t = { d = 18.9, v = "orc-male", n = { x = 191 }, c = { x = { { 0.00, "Это проклятие пало на нас всего лишь из-за медальона." }, { 4.44, "Да, лорд Вальтхалак умеет держать обиду." }, { 7.78, "Мы постараемся найти остальные части – надеюсь, прежде чем меня настигнет безвременная кончина." }, { 15.63, "Но сначала давай займёмся твоей наградой." } } } } },
