    [9022] = { d = 31.2, v = "named/16016", n = { x = 343 }, c = { x = { { 0.00, "В этом амулете хранилась душа Вальтхалака." }, { 3.19, "Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало." }, { 10.58, "Единственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино." }, { 17.10, "Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части." }, { 24.23, "Расскажи ему про обещанные награды." }, { 26.89, "Ну, а я упокоюсь в мире." }, { 28.68, "Желаю удачи." }, { 29.68, "Она тебе понадобится!" } } }, t = { d = 19.7, v = "orc-male", n = { x = 191 }, c = { x = { { 0.00, "Это проклятие пало на нас всего лишь из-за медальона." }, { 4.63, "Да, лорд Вальтхалак умеет держать обиду." }, { 8.10, "Мы постараемся найти остальные части – надеюсь, прежде чем меня настигнет безвременная кончина." }, { 16.29, "Но сначала давай займёмся твоей наградой." } } } } },
    [9023] = { d = 29.1, v = "dwarf-male", n = { x = 331 }, c = { x = { { 0.00, "Мы с братом занимаемся составлением ядов для поместья Чёрный Ворон." }, { 4.91, "Лорд Чёрный Ворон поручил мне исследование нового и очень эффективного яда, который производится из ядовитых желёз обитателей Зул'Гуруба и руин Ан'Киража." }, { 16.13, "В этих проклятых руинах живут две опасные твари, которые годятся для наших целей." }, { 21.99, "Принеси мне ядовитые железы Куриннакс и Веноксиса, и заслужишь мою вечную признательность." } } }, t = { d = 3.6, v = "dwarf-male", n = { x = 38 }, c = { x = { { 0.00, "Прими благодарность Чёрного Ворона!" }, { 2.99, "Выбирай!" } } } } },
    [9024] = { d = 27.0, v = "human-male", n = { x = 336 }, c = { x = { { 0.00, "Я понял!" }, { 0.59, "Ты чувствуешь новый запах в воздухе?" }, { 3.02, "Запах новых одеколонов и духов, только что вошедших в моду?" }, { 6.99, "Наши стражи не стали бы так просто пренебрегать своими обязанностями." }, { 11.55, "Именно так – разве что их разум затуманен какой-то гнусной алхимией." }, { 16.05, "Есть только один способ убедиться – отнести флакон одеколона и духов Моргану Песту и рассказать ему о моих подозрениях." }, { 23.98, "Я возмещу тебе цену покупки, когда ты вернёшься." } } }, t = { d = 16.8, v = "human-male", n = { x = 188 }, c = { x = { { 0.00, "Я понимаю тревогу Аристана, но мне кажется, он перестарался." }, { 4.33, "Пусть молодые мужчины и женщины делают то, что им нравится." }, { 8.60, "Я думаю, Аристан просто забыл, что такое быть молодым и влюблённым." }, { 13.46, "Но лучше ему этого не говорить." }, { 15.83, "Подыграем ему." } } } } },
    [9025] = { d = 20.9, v = "human-male", n = { x = 236 }, c = { x = { { 0.00, "Ну-с, что я скажу..." }, { 1.43, "Похоже, Аристан в конце концов всё-таки на что-то напал." }, { 5.53, "Я нашёл следы веществ, используемых в любовных зельях и хитрых средствах контроля разума." }, { 11.98, "Известно, что такие вещества используются в некоторых духах, но некоторые из обнаруженных мною ингредиентов..." }, { 19.85, "Пахнет занятно." } } }, t = { d = 14.6, v = "human-male", n = { x = 169 }, c = { x = { { 0.00, "Хотя я так и думал, что дело в этом, однако от того, что мои подозрения подтвердились, на душе спокойнее не стало." }, { 8.09, "Мы должны тщательно продумать следующий шаг." }, { 11.22, "Вот возмещение за купленные тобою духи и одеколон." } } } } },
    [9026] = { d = 16.0, v = "human-male", n = { x = 182 }, c = { x = { { 0.00, "Мы должны найти источник." }, { 1.81, "Я видел гораздо больше народа, чем обычно, – в том числе и стражей – входящими в \"Позолоченную розу\" и выходящими оттуда." }, { 10.16, "Поговори с Эллисон." }, { 11.53, "Если она продаёт эти духи, она должна знать, откуда они взялись." } } }, t = { d = 18.3, v = "human-female#111", n = { x = 195 }, c = { x = { { 0.00, "О да, я лишь недавно получила партию духов и одеколона." }, { 4.04, "Они очень хорошо расходятся, и я не знаю, надолго ли они задержатся на полках." }, { 9.86, "Но если хочешь спросить моё мнение, то это как-то скучно, когда все пахнут одинаково." }, { 16.22, "Да, запах хороший, но всё же..." } } } } },
    [9027] = { d = 24.6, v = "human-female#111", n = { x = 278 }, c = { x = { { 0.00, "В этом одеколоне есть что-то интересное?" }, { 2.87, "Возможно." }, { 3.57, "Никогда не видела, чтобы столько народа так страстно желали приобрести один и тот же товар." }, { 10.06, "Послушай, если с этим что-то не так, я тоже хочу знать." }, { 14.01, "Я купила всю партию у торговца по имени Эверт Соризам." }, { 17.89, "Он в городе недавно." }, { 19.36, "Он упоминал, что собирается доставить кое-какие товары в \"Тончайшую пряжу\"." } } }, t = { d = 21.8, v = "human-male", n = { x = 266 }, c = { x = { { 0.00, "Да, конечно." }, { 0.84, "Эти благовония в нынешнем сезоне расходятся моментом." }, { 4.46, "Только за последний час у меня уже пять или шесть раз спрашивали о них." }, { 9.15, "Боюсь, я продал всю партию этого товара." }, { 11.92, "Если он тебе нужен, поговори с хозяйкой таверны Аллисон в \"Позолоченной Розе\"." }, { 17.22, "Но не трать времени." }, { 18.55, "Полагаю, ты сочтёшь запах духов просто неотразимым." } } } } },
    [9028] = { d = 35.3, v = "human-male", n = { x = 433 }, c = { x = { { 0.00, "Что?" }, { 0.30, "Предательство?" }, { 1.27, "Нет, нет, заверяю тебя, мои намерения были совершенно безобидными." }, { 5.72, "Что плохого в том, чтобы слегка помочь тем, кто желает облегчить мучительный ритуал ухаживания?" }, { 12.05, "Пойми, это не преступление." }, { 13.92, "И чтобы доказать, что я ничего плохого не желал, я даже назову источник этих благовоний." }, { 19.88, "Их поставлял мне Стаффрон Лерент, какой-то аптекарь." }, { 23.37, "Я никогда не говорил с ним." }, { 25.18, "Гоблин-посредник сказал, что этот аптекарь работает где-то в предгорьях Хиллсбрада, за тем загадочным поместьем Чёрный Ворон." }, { 33.49, "Желаю тебе удачи в поисках." } } }, t = { d = 41.1, v = "scourge-male#82", n = { x = 355 }, c = { x = { { 0.00, "Да, я сделал эти благовония." }, { 2.71, "Чудный запах, не так ли?" }, { 4.99, "Неотразимый." }, { 6.18, "Когда воины Альянса и Орды равно будут сражены этой любовью, они не смогут остановить воздвижение Совета Тени." }, { 16.84, "Они окажутся ослабленными и неподготовленными." }, { 21.15, "Беспокоясь за тех, кого любят, они потеряют бдительность." }, { 26.57, "Решение было таким простым." }, { 29.27, "Почему понадобилось столько времени, чтобы найти его?" }, { 34.44, "Слабое место любого – его сердце." }, { 37.74, "И тебе уже не остановить неизбежное." } } } } },
    [9029] = { t = { d = 3.5, v = "narrator", n = { x = 32 }, c = { x = { { 0.00, "Из котла поднимается приятный аромат." } } } } },
    [9032] = { d = 35.6, v = "orc-male", n = { x = 389 }, c = { x = { { 0.00, "В медальоне заключена душа Вальтхалака?" }, { 2.97, "Неудивительно, что его охраняет столь мощное проклятие." }, { 7.10, "Но разыскать Бодли будет непросто." }, { 9.73, "Насколько я знаю, он собирался вернуться в Пик Чёрной горы, и с тех пор о нём больше никто не слышал." }, { 17.16, "Попробуй найти его в Чёрной горе, хотя весьма вероятно, что Бодли уже нет в живых." }, { 23.45, "Так что я бы тебе посоветовал взять с собой спектральный сканер иных измерений." }, { 29.33, "Как ни горько мне говорить об этом, но лучше заранее приготовиться к самому худшему..." } } } },
    [9033] = { d = 30.1, v = "human-male#50", n = { x = 340 }, c = { x = { { 0.00, "С последней войны прошло пять лет…" }, { 2.44, "Погибли десятки тысяч, и всё ради чего?" }, { 5.34, "Нам так и не удалось избавиться от угрозы." }, { 8.30, "Теперь же Король-лич вновь поднимает голову." }, { 11.45, "Его правая рука, Кел'Тузад, готовится напасть на наши земли." }, { 15.88, "Он не пройдёт!" }, { 16.85, "Докажи свою преданность нашему делу." }, { 19.55, "Рискни своей жизнью ради победы над Плетью, а Серебряный Рассвет и Алый Марш прикроют тебя со спины." }, { 26.82, "Ступай в Наксрамас и уничтожь воинство Плети..." } } }, t = { d = 7.5, v = "human-male#50", n = { x = 82 }, c = { x = { { 0.00, "Что ж, отличная работа!" }, { 1.83, "Ты получишь награду за верную службу обитателям часовни Последней Надежды." } } } } },
