    [9051] = { d = 34.3, g = 1, v = "tauren-male#68", n = { m = 320, f = 322 }, c = { m = { { 0.00, "Яд, который ты помог мне создать, нужен мне для особых целей." }, { 5.27, "Огромные девизавры, обитающие в кратере, мешают мне охотиться и даже угрожают моей жизни." }, { 13.02, "Даже если бы у меня хватило сил, чтобы убить девизавра, это было бы бесполезно – на место убитого немедленно придёт другой." }, { 23.71, "Возьми эту отравленную колючку и загони её глубоко в шкуру девизавра." }, { 29.75, "Яд усмирит зверя, хоть я и не знаю, насколько быстро..." } }, f = { { 0.00, "Яд, который ты помогла мне создать, нужен мне для особых целей." }, { 5.16, "Огромные девизавры, обитающие в кратере, мешают мне охотиться и даже угрожают моей жизни." }, { 12.53, "Даже если бы у меня хватило сил, чтобы убить девизавра, это было бы бесполезно – на место убитого немедленно придёт другой." }, { 22.71, "Возьми эту отравленную колючку и загони её глубоко в шкуру девизавра." }, { 28.46, "Яд усмирит зверя, хоть я и не знаю, насколько быстро..." } } }, t = { d = 8.6, v = "tauren-male#68", n = { x = 73 }, c = { x = { { 0.00, "Спасибо." }, { 0.86, "Твоя смелость и мудрость не знают границ." }, { 4.88, "Расскажи мне, каково было действие яда?" } } } } },
    [9052] = { d = 34.4, g = 1, v = "tauren-male#68", n = { x = 331 }, c = { m = { { 0.00, "Мне нужна твоя помощь в создании яда, с помощью которого я собираюсь усмирять огромных чудовищ, обитающих в кратере." }, { 9.33, "Не бойся, яд не смертелен." }, { 11.41, "Кроме того, твои острые глаза, герой, будут большим подспорьем при сборе ингредиентов." }, { 18.45, "Грибы-кровошляпочники растут под побегами кровоцвета – их в кратере полным-полно." }, { 25.68, "Жала Гориши – это жала насекомых, которые водятся в районе Скользкого оврага в южной части кратера." } }, f = { { 0.00, "Мне нужна твоя помощь в создании яда, с помощью которого я собираюсь усмирять огромных чудовищ, обитающих в кратере." }, { 9.67, "Не бойся, яд не смертелен." }, { 11.83, "Кроме того, твои острые глаза, героиня, будут большим подспорьем при сборе ингредиентов." }, { 19.28, "Грибы-кровошляпочники растут под побегами кровоцвета – их в кратере полным-полно." }, { 26.15, "Жала Гориши – это жала насекомых, которые водятся в районе Скользкого оврага в южной части кратера." } } }, t = { d = 8.0, v = "tauren-male#68", n = { x = 57 }, c = { x = { { 0.00, "Наконец-то!" }, { 1.28, "Теперь я смешаю эти ингредиенты с почвой Ун'Горо и сварю яд..." } } } } },
    [9053] = { d = 28.4, g = 1, v = "tauren-male#68", n = { m = 256, f = 256 }, c = { m = { { 0.00, "Как я и опасался – яд слишком слаб для такого большого зверя." }, { 5.53, "Чтобы создать более мощный яд, мне потребуются лучшие ингредиенты." }, { 11.64, "Отправляйся на дно Храма Атал'Хаккара, раскрой секреты алтаря и заполучи от тамошнего стража гнилую лозу." }, { 21.30, "Храм опасен, поэтому не ходи один." }, { 24.52, "Возвращайся ко мне, когда закончишь задание." } }, f = { { 0.00, "Как я и опасался – яд слишком слаб для такого большого зверя." }, { 5.47, "Чтобы создать более мощный яд, мне потребуются лучшие ингредиенты." }, { 11.51, "Отправляйся на дно Храма Атал'Хаккара, раскрой секреты алтаря и заполучи от тамошнего стража гнилую лозу." }, { 21.06, "Храм опасен, поэтому не ходи одна." }, { 24.24, "Возвращайся ко мне, когда закончишь задание." } } }, t = { d = 17.1, v = "tauren-male#68", n = { x = 165 }, c = { x = { { 0.00, "Наконец-то яд можно изготовить в полную силу." }, { 3.86, "Я не посмею просить тебя снова применить его против этого существа – я и так попросил слишком многого." }, { 12.58, "Прими мою благодарность и уважение." }, { 15.61, "Доброго тебе пути." } } } } },
