    [9120] = { d = 24.5, v = "narrator", n = { x = 277 }, c = { x = { { 0.00, "От повелителя Наксрамаса остался лишь этот талисман." }, { 3.90, "Голос рассудка подсказывает, что следует уничтожить его, дабы лич никогда больше не смог возродиться." }, { 11.44, "К счастью, вы не привыкли слушаться внутреннего голоса." }, { 15.54, "Кое-кто из часовни Последней Надежды обещал недурно заплатить за этот талисман." }, { 21.53, "Кому есть дело до возрождения Кел'Тузада?" } } }, t = { d = 13.4, v = "human-male", n = { x = 115 }, c = { x = { { 0.00, "Я и помыслить не мог, что доживу до такого…" }, { 3.36, "*Кажется, у отца Монтоя потекли слюнки.*" }, { 7.04, "Да, да, ты получишь награду." }, { 9.65, "Да ещё какую." }, { 10.91, "А ну давай эту штуку сюда!" } } } } },
    [9121] = { d = 35.4, v = "human-female#47", n = { x = 446 }, c = { x = { { 0.00, "В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас." }, { 4.46, "Все попытки войти туда разбивались о могущественные чары, наложенные на портал." }, { 9.75, "До сегодняшнего дня." }, { 11.08, "Мы придумали, как проникнуть внутрь при помощи чародейского покрова." }, { 15.53, "Это старый трюк магов Кирин Тора, над которым я хорошенько поработала." }, { 20.29, "Поскольку тебе не хватает преданности делу Серебряного Рассвета, за чары придётся немало заплатить." }, { 26.91, "Ты можешь отказаться от задания и вернуться ко мне, как только тебя начнут почитать или превозносить." }, { 33.65, "Тогда я сделаю тебе скидку." } } }, t = { d = 10.9, v = "human-female#47", n = { x = 136 }, c = { x = { { 0.00, "Ты почувствуешь лёгкое покалывание." }, { 2.31, "Это значит, что всё работает." }, { 4.32, "Когда всё закончится, ты сможешь попасть в Наксрамас, ступив на рунический портал в Проклятом лесу." } } } } },
    [9122] = { d = 26.7, g = 1, v = "human-female#47", n = { m = 329, f = 330 }, c = { m = { { 0.00, "В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас." }, { 4.58, "Все попытки войти туда разбивались о могущественные чары, наложенные на портал." }, { 10.03, "До сегодняшнего дня." }, { 11.39, "Мы придумали, как проникнуть внутрь при помощи чародейского покрова." }, { 15.97, "Это старый трюк магов Кирин Тора, над которым я хорошенько поработала." }, { 20.86, "Поскольку ты весьма предан делу Серебряного Рассвета, часть издержек мы возьмём на себя." } }, f = { { 0.00, "В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас." }, { 4.56, "Все попытки войти туда разбивались о могущественные чары, наложенные на портал." }, { 9.97, "До сегодняшнего дня." }, { 11.33, "Мы придумали, как проникнуть внутрь при помощи чародейского покрова." }, { 15.88, "Это старый трюк магов Кирин Тора, над которым я хорошенько поработала." }, { 20.75, "Поскольку ты весьма предана делу Серебряного Рассвета, часть издержек мы возьмём на себя." } } }, t = { d = 11.0, v = "human-female#47", n = { x = 136 }, c = { x = { { 0.00, "Ты почувствуешь лёгкое покалывание." }, { 2.33, "Это значит, что всё работает." }, { 4.35, "Когда всё закончится, ты сможешь попасть в Наксрамас, ступив на рунический портал в Проклятом лесу." } } } } },
    [9123] = { d = 28.3, v = "human-female#47", n = { x = 346 }, c = { x = { { 0.00, "В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас." }, { 4.62, "Все попытки войти туда разбивались о могущественные чары, наложенные на портал." }, { 10.11, "До сегодняшнего дня." }, { 11.48, "Мы придумали, как проникнуть внутрь при помощи чародейского покрова." }, { 16.09, "Это старый трюк магов Кирин Тора, над которым я хорошенько поработала." }, { 21.02, "Поскольку твоя преданность делу Серебряного Рассвета не подлежит сомнению, мы возьмём на себя все издержки." } } }, t = { d = 11.3, v = "human-female#47", n = { x = 139 }, c = { x = { { 0.00, "Ты почувствуешь лёгкий звон в ушах." }, { 2.31, "Это будет означать, что наш план сработал." }, { 5.16, "В конечном итоге ты сможешь войти в Наксрамас, ступив на рунический портал в Проклятом лесу." } } } } },
    [9124] = { d = 27.4, v = "human-male#50", n = { x = 326 }, c = { x = { { 0.00, "Хочешь получить такую побрякушку?" }, { 2.32, "*Леопольд помахивает знаком Марша.*" }, { 5.12, "Мне пригодилась бы твоя помощь в одном деле." }, { 8.25, "Я создаю броню расхитителей гробниц для глупцов, желающих сунуть нос в Наксрамас." }, { 13.87, "У меня нет недостатка в материалах, за исключением конечностей и панцирей некрорахнидов." }, { 19.87, "Принеси мне их, и получишь значок." }, { 22.25, "Имей в виду, интенданты готовы отдать за эти побрякушки много интересного." } } }, t = { d = 9.9, v = "human-male#50", n = { x = 98 }, c = { x = { { 0.00, "О, это то, что нужно." }, { 1.71, "Помни: я всегда принимаю новые детали." }, { 4.86, "За каждую связку, что ты принесёшь, я награжу тебя знаком отличия." } } } } },
    [9125] = { t = { d = 3.1, v = "human-male#50", n = { x = 30 }, c = { x = { { 0.00, "Прекрасно!" }, { 0.96, "Они мне очень пригодятся!" } } } } },
    [9126] = { d = 24.1, v = "human-male#50", n = { x = 291 }, c = { x = { { 0.00, "Для изготовления доспехов костяной косы, изобретённых доном Хулио, требуются обломки костей – чем больше, тем лучше." }, { 7.99, "Хотя безумцы, регулярно отправляющиеся в Наксрамас, приносят мне довольно много, обломки костей Плети для меня никогда не лишние." }, { 16.98, "Не желаешь ли помочь мне?" }, { 18.73, "Так ты изничтожишь подлых тварей Плети и снабдишь меня материалом для доспехов." } } }, t = { d = 10.4, g = 1, v = "human-male#50", n = { m = 111, f = 113 }, c = { m = { { 0.00, "А ты быстр!" }, { 0.77, "Быстр, как лисица..." }, { 2.19, "Слушай, я тебе не рассказывал, как пел в квартете цирюльников?" }, { 6.56, "Напомни мне как-нибудь рассказать эту историю." } }, f = { { 0.00, "А ты быстра!" }, { 0.93, "Быстра, как лисица..." }, { 2.52, "Слушай, я тебе не рассказывал, как пел в квартете цирюльников?" }, { 7.02, "Напомни мне как-нибудь рассказать эту историю." } } } } },
    [9127] = { t = { d = 8.5, v = "human-male#50", n = { x = 90 }, c = { x = { { 0.00, "Скоро, скоро я осуществлю свою мечту – стану штатным танцором на дискотеке Прибамбасска!" }, { 7.06, "Продолжай работать." } } } } },
    [9128] = { d = 22.2, g = 1, v = "human-female#47", n = { m = 261, f = 262 }, c = { m = { { 0.00, "Приветствую тебя, странник!" }, { 1.95, "Не ищешь ли ты работу?" }, { 3.53, "Плачу знаками отличия – их можно обменять на разные магические предметы у интендантов." }, { 9.58, "Слушай, что мне нужно: принеси мне как можно больше средоточий стихий – сколько сможешь унести." }, { 16.27, "Чем больше, тем лучше!" }, { 17.84, "Средоточия стихий можно найти у элементалей всех форм и размеров." } }, f = { { 0.00, "Приветствую тебя, странница!" }, { 1.98, "Не ищешь ли ты работу?" }, { 3.52, "Плачу знаками отличия – их можно обменять на разные магические предметы у интендантов." }, { 9.45, "Слушай, что мне нужно: принеси мне как можно больше средоточий стихий – сколько сможешь унести." }, { 15.99, "Чем больше, тем лучше!" }, { 17.54, "Средоточия стихий можно найти у элементалей всех форм и размеров." } } }, t = { d = 8.2, v = "human-female#47", n = { x = 70 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.55, "Как и обещала, знак отличия твой." }, { 4.49, "И помни: там, откуда он взялся, есть ещё..." } } } } },
    [9129] = { t = { d = 1.7, v = "human-female#47", n = { x = 14 }, c = { x = { { 0.00, "Отличная работа!" } } } } },
    [9131] = { d = 27.4, g = 1, v = "human-male#50", n = { x = 297 }, c = { m = { { 0.00, "Приходилось ли тебе встречать броню дредноута, герой?" }, { 4.00, "Конечно нет, ты же ещё совсем салага." }, { 6.73, "Так вот послушай знатока – она великолепна!" }, { 9.92, "Ты, наверное, недоумеваешь, какое это к тебе может иметь отношение?" }, { 14.99, "Вот что, недотёпа, мне нужны пластины чёрного железа – как можно больше." }, { 20.18, "Я хорошо заплачу." }, { 21.51, "Пластины необходимы мне, чтобы создать броню дредноута для наших славных воинов." } }, f = { { 0.00, "Приходилось ли тебе встречать броню дредноута, героиня?" }, { 4.03, "Конечно нет, ты же ещё совсем салага." }, { 6.69, "Так вот послушай знатока – она великолепна!" }, { 9.80, "Ты, наверное, недоумеваешь, какое это к тебе может иметь отношение?" }, { 14.74, "Вот что, недотёпа, мне нужны пластины чёрного железа – как можно больше." }, { 19.80, "Я хорошо заплачу." }, { 21.10, "Пластины необходимы мне, чтобы создать броню дредноута для наших славных воинов." } } }, t = { d = 4.6, v = "human-male#50", n = { x = 37 }, c = { x = { { 0.00, "Маловато, но пока сойдёт." }, { 2.59, "Найдёшь ещё – приноси." } } } } },
    [9132] = { t = { d = 4.9, v = "human-male#50", n = { x = 34 }, c = { x = { { 0.00, "Что, и это всё?" }, { 1.59, "Я же ясно сказал – мне нужно ЕЩЁ!" } } } } },
    [9136] = { d = 26.1, v = "nightelf-female#51", n = { x = 296 }, c = { x = { { 0.00, "Я изготавливаю особые доспехи для наших бравых солдат, входящих в Наксрамас – они называются доспехами сновидца." }, { 8.24, "Обычно у меня нет недостатка в материалах, за исключением диких ростков." }, { 13.51, "Возможно, ты подумаешь, что эта работа не серьёзна, однако без диких ростков создание таких доспехов невозможно." }, { 21.68, "И я готова платить за эту работу знаками Рассвета или Марша!" } } }, t = { d = 5.2, v = "nightelf-female#51", n = { x = 49 }, c = { x = { { 0.00, "Премного благодарна." }, { 1.84, "Помни: я всегда принимаю дикие ростки." } } } } },
    [9137] = { t = { d = 4.6, v = "nightelf-female#51", n = { x = 40 }, c = { x = { { 0.00, "Спасибо!" }, { 0.84, "Твоя помощь в борьбе с Плетью неоценима." } } } } },
    [9141] = { d = 25.7, g = 1, v = "human-male#50", n = { m = 302, f = 303 }, c = { m = { { 0.00, "Хочешь получить задание?" }, { 1.68, "Не всё так просто." }, { 2.88, "Неужели ты думаешь, что я буду раздавать задания всякому явившемуся пред мои очи оборванцу, когда меня осаждают толпы желающих работать на фронте!" }, { 12.73, "Хочешь получить задание – докажи, что ты его достоин!" }, { 16.33, "Принеси мне знак доблести, тогда и поговорим." }, { 19.34, "Имей в виду, единственный способ поступить к нам на работу – обагрить руки кровью!" } }, f = { { 0.00, "Хочешь получить задание?" }, { 1.74, "Не всё так просто." }, { 2.99, "Неужели ты думаешь, что я буду раздавать задания всякому явившемуся пред мои очи оборванцу, когда меня осаждают толпы желающих работать на фронте!" }, { 13.19, "Хочешь получить задание – докажи, что ты его достойна!" }, { 16.99, "Принеси мне знак доблести, тогда и поговорим." }, { 20.10, "Имей в виду, единственный способ поступить к нам на работу – обагрить руки кровью!" } } }, t = { d = 14.9, v = "human-male#50", n = { x = 177 }, c = { x = { { 0.00, "Хорошо, слушай порядок действий: за каждый предъявленный знак доблести будешь получать задание." }, { 6.96, "Выполнять строго по инструкции и отчитываться караванщику Камнетёсу." }, { 11.81, "Вопросы есть?" }, { 12.79, "Прекрасно, теперь марш отсюда." } } } } },
    [9142] = { t = { d = 6.2, g = 1, v = "human-male#50", n = { m = 57, f = 58 }, c = { m = { { 0.00, "Ты это заслужил, салага." }, { 2.07, "И не ной из-за приказов: выполняй или уничтожай." } }, f = { { 0.00, "Ты это заслужила, салага." }, { 2.24, "И не ной из-за приказов: выполняй или уничтожай." } } } } },
    [9153] = { d = 32.7, v = "human-male#50", n = { x = 373 }, c = { x = { { 0.00, "Парящие некрополи Плети не щадят ни Орду, ни Альянс." }, { 3.91, "Тень летающих крепостей пала на Танарис, Выжженные Земли, Зимние Ключи и Пылающие степи." }, { 10.47, "Только объединив усилия, мы сможем противостоять этой беде." }, { 14.91, "Некрополи поддерживаются энергией магических кругов, которые размещены в различных точках захваченных регионов." }, { 23.06, "Все магические круги охраняются полчищами нежити." }, { 26.70, "Мы определили, что если уничтожить эти толпы нежити, то защита кругов будет снята." } } }, t = { d = 26.7, v = "human-male#50", n = { x = 326 }, c = { x = { { 0.00, "Тебе неплохо удалось справиться." }, { 2.29, "Путём таких постепенно нарастающих ударов мы сможем одолеть угрозу со стороны возрождённой Плети." }, { 8.91, "Отдохни и восстанови силы, но после этого тебе снова придётся отправиться на фронт, иначе мы потеряем те земли, которые отбили сегодня." }, { 18.20, "Дабы помочь тебе в грядущих битвах, мы готовы отдать тебе некоторые из наших особых предметов в обмен на некротические руны." } } } } },
    [9154] = { d = 23.7, v = "human-male#50", n = { x = 286 }, c = { x = { { 0.00, "Захватчики Плети вернулись, и их теперь куда больше, чем когда-либо прежде." }, { 5.16, "Это наверняка дело рук Короля-лича!" }, { 7.67, "Серебряный Рассвет собирает всех, кто может носить оружие и желает пустить его в ход, для защиты наших земель." }, { 15.23, "Если разделяешь эти убеждения, отнеси этот документ Хранителю свитков в Часовню Последней Надежды в Восточных Чумных землях." } } }, t = { d = 17.5, v = "human-male", n = { x = 196 }, c = { x = { { 0.00, "Серебряный Рассвет посылает призыв о помощи, и ты – среди тех, кто откликнулся на этот призыв." }, { 6.75, "Нет времени, чтобы должным образом обучить тебя." }, { 10.33, "Мы верим в твои способности и в то, что с твоей помощью мы сумеем отразить угрозу, исходящую от Плети." } } } } },
    [9165] = { d = 37.8, v = "dwarf-male", n = { x = 436 }, c = { x = { { 0.00, "Если бы не помощь странников вроде тебя, наш караван никогда не добрался бы до пункта назначения!" }, { 6.90, "Твари Плети лезут из всех щелей!" }, { 9.20, "*Страж Дидье утирает лоб*" }, { 11.76, "Теперь надо дождаться здесь фельдмаршала Чамберса, чтобы он подписал тебе подорожную." }, { 17.71, "Предъявишь её командиру Метцу в Часовню Последней Надежды в Восточные Чумные земли." }, { 23.53, "И вот что, при Чамберсе следи за языком." }, { 26.28, "Он из тех парней, которые любят орать, мол, прихлопну как муху да кишки по деревьям развешу..." }, { 32.79, "Только в отличие от большинства подобных крикунов, именно так он и сделает." } } } },
    [9178] = { d = 35.9, v = "narrator", n = { x = 396 }, c = { x = { { 0.00, "Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте." }, { 10.82, "Заказ-наряд Би-Эс ноль девяносто один:" }, { 13.85, "Сто двадцать массивных грузил." }, { 16.20, "Выполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли." }, { 24.38, "Контракт признаётся недействительным в случае, если бумага была подделана или тем или иным образом испорчена." }, { 32.79, "Подпись: Командир Метц, Серебряный Рассвет" } } }, t = { d = 4.1, v = "dwarf-male", n = { x = 40 }, c = { x = { { 0.00, "Ага, эти пригодятся для дробящего оружия пехоты." } } } } },
