    [9229] = { d = 32.2, v = "human-male#50", n = { x = 367 }, c = { x = { { 0.00, "Рамаладни был воином Братства и учеником верховного лорда Могрейна ещё до возникновения Рассвета." }, { 6.96, "Когда до него дошла весть о гибели Могрейна, гнев и ярость овладели его сердцем." }, { 12.81, "Пойми, тот, кто позволяет гневу и жажде мести овладеть собой, теряет душу и разум." }, { 18.85, "Именно это и произошло с Рамаладни, духом мести, вошедшим в Наксрамас, чтобы осуществить возмездие, и более не вернувшимся." }, { 27.76, "Отправляйся в Наксрамас и найди то, что было некогда Рамаладни." } } }, t = { d = 15.1, g = 1, v = "human-male#50", n = { m = 164, f = 164 }, c = { m = { { 0.00, "Это его кольцо!" }, { 1.32, "Но оно сломано..." }, { 2.71, "Других доказательств того, что ты и впрямь нашёл Рамаладни, нет?" }, { 7.44, "*Корфакс морщится*" }, { 9.20, "Это не сулит Рамаладни ничего хорошего." }, { 11.96, "Впрочем, кольцо, возможно, удастся восстановить." } }, f = { { 0.00, "Это его кольцо!" }, { 1.29, "Но оно сломано..." }, { 2.66, "Других доказательств того, что ты и впрямь нашла Рамаладни, нет?" }, { 7.36, "*Корфакс морщится*" }, { 9.12, "Это не сулит Рамаладни ничего хорошего." }, { 11.84, "Впрочем, кольцо, возможно, удастся восстановить." } } } } },
    [9230] = { d = 21.9, v = "human-male#50", n = { x = 262 }, c = { x = { { 0.00, "Починить кольцо будет нелегко." }, { 2.23, "Видишь ли, оно было сделано из рун, которые можно найти только в сооружениях Плети – таких как Наксрамас." }, { 9.73, "Мне также потребуются дополнительные материалы, однако основное затруднение представляют именно морозные руны." }, { 17.49, "Принеси мне материалы и я восстановлю кольцо в первозданном виде." } } }, t = { d = 4.8, v = "human-male#50", n = { x = 47 }, c = { x = { { 0.00, "Сам Рамаладни не сделал бы лучше!" }, { 2.74, "Вот кольцо, как я и обещал." } } } } },
    [9232] = { d = 28.3, v = "dwarf-male", n = { x = 325 }, c = { x = { { 0.00, "Ты, похоже, спишь и видишь себя героем Рассвета?" }, { 3.50, "Я видел, как летели головы лучших солдат под натиском шайки сброда Кел'Тузада." }, { 9.20, "Не понимаю, как такую бестолочь, как ты, можно вообще допускать в Наксрамас?" }, { 14.65, "Увы, выбора у меня нет... попытаюсь хотя бы помочь." }, { 18.92, "Омарион оставил мне всего один рецепт." }, { 21.77, "Не разгуляешься..." }, { 23.07, "Я могу сделать несколько вариантов штанов – только принеси мне материалы." } } }, t = { d = 10.3, g = 1, v = "dwarf-male", n = { x = 85 }, c = { m = { { 0.00, "*Вильгельм утирает пот со лба*" }, { 2.56, "И-эх, тяжела и неказиста..." }, { 5.04, "Держи штаны, герой." }, { 6.88, "По крайней мере, сдохнешь во всём новом." } }, f = { { 0.00, "*Вильгельм утирает пот со лба*" }, { 2.56, "И-эх, тяжела и неказиста..." }, { 4.94, "Держи штаны, героиня." }, { 6.86, "По крайней мере, сдохнешь во всём новом." } } } } },
    [9233] = { d = 39.9, v = "narrator", n = { x = 392 }, c = { x = { { 0.00, "Вильгельм!" }, { 0.90, "Если ты читаешь эти строки, то мечта твоя сбылась: я окочурился." }, { 6.36, "Знай, что и на смертном одре я думал только о том, сколь негодный ремесленник из тебя вышел." }, { 13.98, "К сожалению, податель сего вполне может отобрать у тебя звание худшего мастера." }, { 20.71, "Что касается настоящего руководства, в нём собраны все мои рецепты." }, { 26.24, "Сделай для подателя сего всё, что он попросит." }, { 30.06, "Не сомневаюсь впрочем, что сдерёшь ты втридорога, ибо канальей ты был, канальей и остался." }, { 37.38, "С искренним презрением," }, { 39.33, "Омарион." } } }, t = { d = 19.0, v = "dwarf-male", n = { x = 218 }, c = { x = { { 0.00, "Да, похоже старина Омарион был совсем не в себе, когда писал письмо." }, { 4.94, "Да мы ж с ним всегда были не разлей вода!" }, { 7.89, "Неважно, книга определённо расширяет мои возможности..." }, { 11.81, "Я смогу выполнить любой твой заказ – разумеется из предоставленных тобой материалов и за скромную плату." } } } } },
    [9234] = { d = 11.5, v = "dwarf-male", n = { x = 127 }, c = { x = { { 0.00, "Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать рукавицы Ледяной погибели." }, { 7.23, "От тебя требуются лишь материалы и скромная плата за работу." } } } },
    [9235] = { d = 11.6, v = "dwarf-male", n = { x = 125 }, c = { x = { { 0.00, "Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать наручи Ледяной погибели." }, { 7.22, "От тебя требуются лишь материалы и скромная плата за работу." } } } },
