    [9239] = { d = 10.9, v = "dwarf-male", n = { x = 122 }, c = { x = { { 0.00, "Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать мерзлотные перчатки." }, { 6.65, "От тебя требуются лишь материалы и скромная плата за работу." } } } },
