    [9243] = { d = 10.9, v = "dwarf-male", n = { x = 117 }, c = { x = { { 0.00, "Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать снежный мундир." }, { 6.52, "От тебя требуются лишь материалы и скромная плата за работу." } } } },
