    [9245] = { d = 11.7, v = "dwarf-male", n = { x = 124 }, c = { x = { { 0.00, "Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать рукавицы Ледяной чешуи." }, { 7.25, "От тебя требуются лишь материалы и скромная плата за работу." } } } },
    [9246] = { d = 11.4, v = "dwarf-male", n = { x = 122 }, c = { x = { { 0.00, "Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать кирасу Ледяной чешуи." }, { 7.05, "От тебя требуются лишь материалы и скромная плата за работу." } } } },
    [9247] = { d = 26.8, v = "narrator", n = { x = 286 }, c = { x = { { 0.00, "В прошлом тебе иногда приходилось браться за поручения в интересах Серебряного Рассвета, и всегда эти поручения оказывались выполнены в наилучшем виде." }, { 11.85, "Ныне, в час великой нужды, мы вновь посылаем тебе зов." }, { 16.09, "Пожалуйста, если ты желаешь вновь оказать нам помощь, явись к хранителю свитков в Часовню Последней Надежды, что в Восточных Чумных землях." } } }, t = { d = 14.8, g = 1, v = "human-male", n = { m = 180, f = 181 }, c = { m = { { 0.00, "Мы в долгу перед тобой, уже за то, что ты явился на наш призыв." }, { 4.13, "Серебряный Рассвет надеется, что твой блистательный пример покажет всем, кто собрался здесь ради помощи нам, истинный путь к отражению угрозы со стороны Плети!" } }, f = { { 0.00, "Мы в долгу перед тобой, уже за то, что ты явилась на наш призыв." }, { 4.33, "Серебряный Рассвет надеется, что твой блистательный пример покажет всем, кто собрался здесь ради помощи нам, истинный путь к отражению угрозы со стороны Плети!" } } } } },
    [9248] = { d = 10.4, g = 1, v = "nightelf-female#53", n = { x = 115 }, c = { m = { { 0.00, "Ишну-ала, герой." }, { 1.21, "Покажи мне доказательство кончины лорда Совета Бездны и получишь в награду предмет, который поможет тебе справиться с киражами." } }, f = { { 0.00, "Ишну-ала, героиня." }, { 1.48, "Покажи мне доказательство кончины лорда Совета Бездны и получишь в награду предмет, который поможет тебе справиться с киражами." } } }, t = { d = 10.1, v = "nightelf-female#53", n = { x = 97 }, c = { x = { { 0.00, "Анде'торас-этил." }, { 1.34, "На моём родном языке это значит: «Да уменьшатся твои невзгоды»." }, { 6.65, "Носи это кольцо с гордостью и на здоровье." } } } } },
    [9250] = { d = 22.4, v = "narrator", n = { x = 228 }, c = { x = { { 0.00, "Основа готова, и Атиеш собран почти полностью." }, { 3.87, "Не хватает лишь набалдашника и основания." }, { 7.15, "Да, и осталась небольшая проблемка – посох по-прежнему служит проводником зла Саргераса в мир." }, { 14.67, "Найди того, кто поможет тебе отыскать недостающие части, а заодно изгнать из посоха злого духа." } } } },
    [9251] = { d = 39.6, g = 1, v = "creature/anachronos", n = { m = 350, f = 351 }, c = { m = { { 0.00, "Ты спрашиваешь себя, почему ещё жив." }, { 3.10, "Ведь у тебя в руках предмет великого зла." }, { 6.66, "Ответ неясен." }, { 7.90, "Я лишь делаю то, что должен." }, { 10.29, "Кел'Тузад восседает на троне в Наксрамасе и плетёт козни..." }, { 15.33, "Он ищет то, что есть у тебя, и владеет тем, что ищешь ты." }, { 20.12, "Что до основания посоха – оно было у дворфа Бранна Бронзоборода, когда тот вошёл в Ан'Кираж." }, { 28.02, "Сам он Ан'Кираж уже покинул, но основание Атиеша осталось там." }, { 33.36, "Если тебе удастся вернуть части посоха, принеси их мне." } }, f = { { 0.00, "Ты спрашиваешь себя, почему ещё жива." }, { 3.37, "Ведь у тебя в руках предмет великого зла." }, { 7.05, "Ответ неясен." }, { 8.34, "Я лишь делаю то, что должен." }, { 10.82, "Кел'Тузад восседает на троне в Наксрамасе и плетёт козни..." }, { 16.03, "Он ищет то, что есть у тебя, и владеет тем, что ищешь ты." }, { 21.00, "Что до основания посоха – оно было у дворфа Бранна Бронзоборода, когда тот вошёл в Ан'Кираж." }, { 29.18, "Сам он Ан'Кираж уже покинул, но основание Атиеша осталось там." }, { 34.71, "Если тебе удастся вернуть части посоха, принеси их мне." } } } },
    [9257] = { d = 39.3, g = 1, v = "creature/anachronos", n = { m = 390, f = 392 }, c = { m = { { 0.00, "Это последнее испытание будет самым трудным из всех." }, { 4.47, "Ты сразился с Древним богом и генералом Короля-лича и одолел обоих, но теперь тебе предстоит встретиться с дланью Саргераса." }, { 14.99, "Отнеси посох в Стратхольм." }, { 17.26, "Там ты найдёшь клочок освящённой земли – место, где были убиты величайшие рыцари Лордерона." }, { 24.83, "Положи осквернённый посох на священную землю и приготовься: из него вырвется сущность неимоверной силы..." }, { 33.61, "Победи демоническое существо, что управляет посохом, и вернись ко мне." } }, f = { { 0.00, "Это последнее испытание будет самым трудным из всех." }, { 4.36, "Ты сразилась с Древним богом и генералом Короля-лича и одолела обоих, но теперь тебе предстоит встретиться с дланью Саргераса." }, { 14.77, "Отнеси посох в Стратхольм." }, { 16.99, "Там ты найдёшь клочок освящённой земли – место, где были убиты величайшие рыцари Лордерона." }, { 24.38, "Положи осквернённый посох на священную землю и приготовься: из него вырвется сущность неимоверной силы..." }, { 32.95, "Победи демоническое существо, что управляет посохом, и вернись ко мне." } } } },
    [9259] = { t = { d = 11.3, v = "human-male", n = { x = 105 }, c = { x = { { 0.00, "Почтим минутой молчания наших павших товарищей." }, { 4.12, "Одно дело – быть предателем, но убивать своих же корешей... это уж совсем подло, а то!" } } } } },
    [9260] = { d = 36.6, v = "human-male#50", n = { x = 438 }, c = { x = { { 0.00, "Плеть стала лагерем у самых наших дверей." }, { 2.92, "Мы не можем оставаться в бездействии!" }, { 5.47, "Встанешь ли ты на защиту Штормграда против этих проклятых захватчиков?" }, { 10.31, "Там, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху." }, { 19.51, "Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно." }, { 25.72, "Пока ты занимаешься этим, уменьши количество этих жутких тварей, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя." }, { 36.41, "Иди!" } } }, t = { d = 23.6, v = "human-male#50", n = { x = 267 }, c = { x = { { 0.00, "Хмм." }, { 0.32, "Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то." }, { 8.86, "Я содрогаюсь при мысли о том, с каким извращённым разумом осуществляется связь посредством подобной магии." }, { 16.30, "Тем не менее тебе удалось остаться в живых и в здравом рассудке." }, { 20.96, "Серебряный Рассвет ценит твою службу." } } } } },
