    [9267] = { t = { d = 7.6, g = 1, v = "goblin-female", n = { m = 83, f = 86 }, c = { m = { { 0.00, "Я рада, что ты осознал свои ошибки." }, { 2.57, "Продолжай поставлять припасы – мы так быстро о тебе не забудем, милок!" } }, f = { { 0.00, "Я рада, что ты осознала свои ошибки." }, { 2.62, "Продолжай поставлять припасы – мы так быстро о тебе не забудем, милочка!" } } } } },
