    [9269] = { d = 39.9, g = 1, v = "creature/anachronos", n = { m = 393, f = 395 }, c = { m = { { 0.00, "Это последнее испытание будет самым трудным из всех." }, { 4.50, "Ты уже сразился с Древним богом и генералом Короля-лича и одолел обоих, но теперь тебе предстоит встретиться с дланью Саргераса." }, { 15.47, "Отнеси посох в Стратхольм." }, { 17.75, "Там ты найдёшь клочок освящённой земли – место, где были убиты величайшие рыцари Лордерона." }, { 25.37, "Положи осквернённый посох на священную землю и приготовься: из него вырвется сущность неимоверной силы..." }, { 34.21, "Победи демоническое существо, что управляет посохом, и вернись ко мне." } }, f = { { 0.00, "Это последнее испытание будет самым трудным из всех." }, { 4.40, "Ты уже сразилась с Древним богом и генералом Короля-лича и одолела обоих, но теперь тебе предстоит встретиться с дланью Саргераса." }, { 15.28, "Отнеси посох в Стратхольм." }, { 17.52, "Там ты найдёшь клочок освящённой земли – место, где были убиты величайшие рыцари Лордерона." }, { 24.97, "Положи осквернённый посох на священную землю и приготовься: из него вырвется сущность неимоверной силы..." }, { 33.62, "Победи демоническое существо, что управляет посохом, и вернись ко мне." } } } },
