    [9272] = { t = { d = 22.0, g = 1, v = "human-male", n = { m = 249, f = 248 }, c = { m = { { 0.00, "Йо-хо-хо... если хочешь водить компанию с нами, бывалыми морскими волками, кончай одеваться как оборванец!" }, { 7.47, "Вот, надень что-нибудь приличное, пока я не протащил тебя под килем." }, { 12.24, "Это сядет на тебя получше, чем на того старого пса, Красноглазого Бена." }, { 17.26, "Сгинул в жуткий шторм в открытом море." }, { 19.96, "Носи с гордостью, приятель!" } }, f = { { 0.00, "Йо-хо-хо... если хочешь водить компанию с нами, бывалыми морскими волками, кончай одеваться как оборванец!" }, { 7.57, "Вот, надень что-нибудь приличное, пока я не протащил тебя под килем." }, { 12.41, "Это сядет на тебя получше, чем на того старого пса, Красноглазого Бена." }, { 17.50, "Сгинул в жуткий шторм в открытом море." }, { 20.23, "Носи с гордостью, подруга!" } } } } },
    [9292] = { d = 8.5, v = "narrator", n = { x = 95 }, c = { x = { { 0.00, "На трупе павшего поганища вы обнаруживаете треснутый кристалл, медленно пульсирующий некротической энергией." } } }, t = { d = 14.0, v = "human-male#50", n = { x = 165 }, c = { x = { { 0.00, "Хм, так это было на трупе одного из этих мерзостных поганищ?" }, { 4.22, "Мы слышали о лагерях-некрополях, призванных Плетью." }, { 7.75, "Я подозреваю, что они хотят создать такой лагерь в Штормграде." }, { 12.10, "Хорошо что им это не удалось." } } } } },
    [9295] = { d = 18.7, v = "narrator", n = { x = 205 }, c = { x = { { 0.00, "Это письмо найдено у одного из множества приспешников Плети, убитых вами." }, { 5.63, "Судя по виду и запаху письма, оно пробыло у нежити уже некоторое время." }, { 11.20, "Возможно, кто-нибудь в Часовне Последней Надежды заинтересуется дальнейшим изучением данного письма..." } } }, t = { d = 35.8, v = "human-male", n = { x = 415 }, c = { x = { { 0.00, "Как трагично!" }, { 0.95, "Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла." }, { 7.19, "Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо." }, { 14.01, "И всё же надежда ещё не потеряна." }, { 16.28, "По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи!" }, { 21.83, "Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу..." }, { 27.89, "Спасибо за доставку этого письма ко мне." }, { 30.73, "Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя." } } } } },
