    [9310] = { d = 6.8, v = "narrator", n = { x = 73 }, c = { x = { { 0.00, "На трупе павшей твари вы находите кристалл, излучающий тусклую некротическую энергию." } } }, t = { d = 14.9, v = "orc-male#60", n = { x = 158 }, c = { x = { { 0.00, "Это было у одной из тварей, напавших на город?" }, { 3.69, "Мы слышали о лагерях-некрополях, призванных Плетью." }, { 7.65, "Я подозреваю, что они хотят создать такой лагерь в Подгороде." }, { 12.46, "Впредь мы должны быть бдительными." } } } } },
    [9317] = { t = { d = 5.0, v = "human-male#116", n = { x = 45 }, c = { x = { { 0.00, "Спасибо." }, { 0.85, "Вот освящённое точило." }, { 2.90, "Используй его с толком." } } } } },
    [9318] = { t = { d = 3.8, v = "human-male#116", n = { x = 47 }, c = { x = { { 0.00, "Надеюсь, этот предмет пригодится тебе в грядущих битвах." } } } } },
    [9319] = { d = 28.2, v = "tauren-female#71", n = { x = 279 }, c = { x = { { 0.00, "Мы не единственные, кто справляет сегодня праздник." }, { 4.18, "Все создания, все народы возжигают пламя." }, { 7.62, "Даже в самых тёмных уголках сегодня горят огни." }, { 11.66, "Если хочешь увидеть их своими глазами, спустись в глубины." }, { 16.59, "Отыщи костры, горящие в Стратхольме, Некроситете, у огров в Забытом Городе и в залах самого Пика Чёрной горы." }, { 25.70, "Я буду ждать твоего возвращения." } } }, t = { d = 21.2, v = "tauren-female#71", n = { x = 289 }, c = { x = { { 0.00, "Твоя сущность поёт, переполненная энергией найденного тобой пламени." }, { 5.52, "Огонь, с которым тебе пришлось столкнуться, весьма силён, и тот, кто наделён нужным знанием, может обуздать эту силу..." }, { 15.11, "А, вот." }, { 17.50, "Пусть это озарит твой путь, куда бы он ни лежал." } } } } },
    [9320] = { t = { d = 7.8, v = "troll-female#137", n = { x = 80 }, c = { x = { { 0.00, "Вот." }, { 0.36, "Но соблюдай осторожность." }, { 2.35, "Нас не так много, чтобы мы могли позволить себе большие потери в бою." } } } } },
    [9321] = { t = { d = 7.3, v = "human-male#116", n = { x = 80 }, c = { x = { { 0.00, "Вот." }, { 0.33, "Но соблюдай осторожность." }, { 2.21, "Нас не так много, чтобы мы могли позволить себе большие потери в бою." } } } } },
    [9322] = { d = 38.2, v = "tauren-female#71", n = { x = 407 }, c = { x = { { 0.00, "Праздник Огненного солнцеворота отмечается повсюду в Азероте, и различные регионы Калимдора – не исключение." }, { 8.40, "Вижу, сил для дороги тебе хватит – пожалуй, самое время отправиться в путь." }, { 14.33, "Праздник Середины лета нельзя оценить должным образом, пока не увидишь горячие огни синего цвета." }, { 22.16, "Зажигаются костры в холодных западных регионах Зимних Ключей, в северо-восточной Азшаре, возле Покоя Доблестных в пустошах Силитуса и у входа в обширный кратер Ун'Горо." }, { 35.43, "Возвращайся по завершении путешествия." } } }, t = { d = 13.7, v = "tauren-female#71", n = { x = 126 }, c = { x = { { 0.00, "Твой дух сияет жаром костров Калимдора." }, { 3.48, "Разве это пламя не воодушевляет тебя?" }, { 6.88, "Когда тебя покинут силы, быть может, это поможет тебе вновь возжечь этот жар." } } } } },
    [9323] = { d = 37.8, g = 1, v = "tauren-female#71", n = { x = 396 }, c = { m = { { 0.00, "Огненный праздник распространился по всем землям, герой." }, { 4.74, "Нет ни единого уголка, куда не проник бы жар этого празднества, а самые сильные огни пылают ярко-синим цветом." }, { 13.45, "Найди их." }, { 14.22, "Один из них можно обнаружить к северу от Пика Чёрной горы." }, { 18.78, "Другие размещаются в глубине территории Восточных Чумных земель возле полуразрушенного города, вдоль дороги, ведущей на утёсы гористых Внутренних земель, и на пути к Тёмному порталу в Выжженных землях." }, { 34.31, "Возвращайся, когда завершишь своё путешествие." } }, f = { { 0.00, "Огненный праздник распространился по всем землям, героиня." }, { 4.53, "Нет ни единого уголка, куда не проник бы жар этого празднества, а самые сильные огни пылают ярко-синим цветом." }, { 13.30, "Найди их." }, { 14.08, "Один из них можно обнаружить к северу от Пика Чёрной горы." }, { 18.67, "Другие размещаются в глубине территории Восточных Чумных земель возле полуразрушенного города, вдоль дороги, ведущей на утёсы гористых Внутренних земель, и на пути к Тёмному порталу в Выжженных землях." }, { 34.30, "Возвращайся, когда завершишь своё путешествие." } } }, t = { d = 32.3, v = "tauren-female#71", n = { x = 285 }, c = { x = { { 0.00, "А, вот и ты." }, { 1.06, "Чуть больше усталости, чуть больше пыли, но внутри сияет свет!" }, { 6.68, "В это время года жар касается нас всех и объединяет нас." }, { 11.73, "Сама твоя суть сияет силой костров, которых тебе довелось касаться." }, { 18.00, "О, но в эти дни просвещение считается довольно ничтожным вознаграждением за выполнение задания, как мне кажется." }, { 28.89, "Так прими это и наслаждайся праздником." } } } } },
    [9324] = { d = 12.6, v = "narrator", n = { x = 114 }, c = { x = { { 0.00, "Это пламя, похищенное из сердца Оргриммара, наполняет тебя теплом." }, { 6.03, "Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше..." } } }, t = { d = 23.8, g = 1, v = "dwarf-male", n = { m = 240, f = 243 }, c = { m = { { 0.00, "Что это?" }, { 0.70, "Если я не ошибаюсь, это пламя взято из самого сердца Оргриммара!" }, { 5.73, "В его обжигающем жаре отражены свирепые сердца орков и троллей." }, { 10.75, "Какое прекрасное пополнение нашей коллекции – как же ты храбр, раз проник в логово врага за священным пламенем!" }, { 19.27, "Интересно, какая сила таится в других городах..." } }, f = { { 0.00, "Что это?" }, { 0.71, "Если я не ошибаюсь, это пламя взято из самого сердца Оргриммара!" }, { 5.85, "В его обжигающем жаре отражены свирепые сердца орков и троллей." }, { 10.99, "Какое прекрасное пополнение нашей коллекции – как же ты храбра, раз проникла в логово врага за священным пламенем!" }, { 19.99, "Интересно, какая сила таится в других городах..." } } } } },
    [9325] = { d = 12.7, v = "narrator", n = { x = 117 }, c = { x = { { 0.00, "Это пламя, похищенное у шамана Громового Утёса, наполняет тебя теплом." }, { 6.28, "Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше..." } } }, t = { d = 17.6, g = 1, v = "dwarf-male", n = { m = 169, f = 173 }, c = { m = { { 0.00, "Если я не ошибаюсь, это пламя похищено с вершин Громового Утёса!" }, { 5.27, "Как же оно поёт силой духов!" }, { 7.61, "Да ты настоящий вор." }, { 9.23, "Прими это как заслуженную плату за твоё мастерство." }, { 13.40, "Эх, если бы у нас было пламя всех трёх городов..." } }, f = { { 0.00, "Если я не ошибаюсь, это пламя похищено с вершин Громового Утёса!" }, { 5.28, "Как же оно поёт силой духов!" }, { 7.63, "Да ты настоящая воровка." }, { 9.61, "Прими это как заслуженную плату за твоё мастерство." }, { 13.79, "Эх, если бы у нас было пламя всех трёх городов..." } } } } },
    [9326] = { d = 12.3, v = "narrator", n = { x = 115 }, c = { x = { { 0.00, "Это пламя, похищенное из руин над Подгородом, наполняет тебя теплом." }, { 6.01, "Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше..." } } }, t = { d = 15.1, v = "dwarf-male", n = { x = 143 }, c = { x = { { 0.00, "Хм..." }, { 0.45, "Какой странный огонь!" }, { 2.34, "Он слаб, почти угасает, но его жар силён." }, { 5.75, "Ты говоришь, он из Подгорода?" }, { 8.17, "Поразительно." }, { 9.30, "Кто знает, чего мы можем достичь, заполучив пламя из всех трёх городов?" } } } } },
    [9330] = { d = 11.9, v = "narrator", n = { x = 106 }, c = { x = { { 0.00, "Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом." }, { 6.12, "Эта сырая энергия чужда тебе, но Сказитель может знать больше..." } } }, t = { d = 20.6, v = "scourge-male#82", n = { x = 185 }, c = { x = { { 0.00, "И это ярко горящее пламя... ты говоришь, оно из Штормграда?" }, { 5.42, "Замечательно!" }, { 6.64, "Должно быть, это было славное приключение!" }, { 10.52, "Конечно же, я заплачу тебе за это." }, { 13.68, "Если ты найдёшь ещё что-нибудь подобное, обязательно приходи поговорить со мной." } } } } },
    [9331] = { d = 11.7, v = "narrator", n = { x = 106 }, c = { x = { { 0.00, "Это пламя, похищенное из сердца Стальгорна, наполняет тебя теплом." }, { 6.00, "Эта сырая энергия чужда тебе, но Сказитель может знать больше..." } } }, t = { d = 18.5, v = "scourge-male#82", n = { x = 150 }, c = { x = { { 0.00, "Это сильное пламя, должно быть, явилось из залов Стальгорна; оно столь же неукротимо, как сами дворфы." }, { 9.89, "Отличная добыча." }, { 11.53, "Если бы у меня был огонь из других городов... а, неважно." }, { 17.09, "Вот твоя плата." } } } } },
    [9332] = { d = 11.5, v = "narrator", n = { x = 108 }, c = { x = { { 0.00, "Это пламя, похищенное с берегов Тельдрассила, наполняет тебя теплом." }, { 5.99, "Эта сырая энергия чужда тебе, но Сказитель может знать больше..." } } }, t = { d = 20.6, v = "scourge-male#82", n = { x = 181 }, c = { x = { { 0.00, "Этот огонь полон древней скорби." }, { 3.24, "Ты говоришь, он добыт от корней Тельдрассила?" }, { 7.51, "Невероятно!" }, { 8.61, "Вот награда за твоё мастерство." }, { 11.51, "Возвращайся ко мне, если найдёшь ещё что-либо подобное; возможно, у меня найдётся применение этому." } } } } },
    [9333] = { t = { d = 7.0, v = "troll-female#137", n = { x = 75 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.31, "Возьми выбранные тобой защитные перчатки в благодарность за твои усилия." } } } } },
    [9334] = { t = { d = 4.2, v = "troll-female#137", n = { x = 47 }, c = { x = { { 0.00, "Надеюсь, этот предмет пригодится тебе в грядущих битвах." } } } } },
    [9335] = { t = { d = 5.4, v = "troll-female#137", n = { x = 45 }, c = { x = { { 0.00, "Спасибо." }, { 0.92, "Вот освящённое точило." }, { 3.13, "Используй его с толком." } } } } },
    [9336] = { t = { d = 7.8, v = "troll-female#137", n = { x = 80 }, c = { x = { { 0.00, "Вот." }, { 0.36, "Но соблюдай осторожность." }, { 2.35, "Нас не так много, чтобы мы могли позволить себе большие потери в бою." } } } } },
    [9337] = { t = { d = 7.5, v = "human-male#116", n = { x = 80 }, c = { x = { { 0.00, "Вот." }, { 0.35, "Но соблюдай осторожность." }, { 2.28, "Нас не так много, чтобы мы могли позволить себе большие потери в бою." } } } } },
    [9338] = { t = { d = 5.8, v = "nightelf-male#55", n = { x = 59 }, c = { x = { { 0.00, "Ты оказываешь нам честь." }, { 2.05, "Твоими стараниями мы преодолеем все преграды." } } } } },
    [9339] = { d = 11.4, v = "narrator", n = { x = 106 }, c = { x = { { 0.00, "Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом." }, { 5.88, "Эта сырая энергия чужда тебе, но Сказитель может знать больше..." } } }, t = { d = 18.7, v = "scourge-male#82", n = { x = 157 }, c = { x = { { 0.00, "Сегодняшние твои деяния свидетельствуют сами за себя." }, { 5.27, "Я мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости." }, { 16.43, "Пусть он озарит твой путь." } } } } },
    [9341] = { t = { d = 10.6, v = "human-male#116", n = { x = 125 }, c = { x = { { 0.00, "Возьми эту гербовую накидку и носи её с гордостью." }, { 3.57, "Быть может, твой пример побудит и других взяться за оружие, чтобы поддержать нас в борьбе против Плети." } } } } },
    [9343] = { t = { d = 11.4, v = "troll-female#137", n = { x = 125 }, c = { x = { { 0.00, "Возьми эту гербовую накидку и носи её с гордостью." }, { 3.81, "Быть может, твой пример побудит и других взяться за оружие, чтобы поддержать нас в борьбе против Плети." } } } } },
    [9362] = { d = 27.0, v = "human-male", n = { x = 315 }, c = { x = { { 0.00, "У меня мало времени!" }, { 1.54, "С помощью чар магического зрения я обнаружил мощный источник магии." }, { 6.36, "Я не могу покинуть башню, поэтому прошу тебя убить мерзкое создание, завладевшее мощным артефактом." }, { 13.55, "Жалкий недоумок, известный как полководец Креллиан, прячется за широкими спинами своих стражей в храме Зин-Малор." }, { 21.64, "Испепели это ничтожество и принеси мне радужную раковину, которую он прячет." } } }, t = { d = 10.8, v = "human-male", n = { x = 130 }, c = { x = { { 0.00, "Должен заметить, у этой раковины странная аура." }, { 3.44, "Очень хорошо, что частью твоей награды будет уникальная возможность исследовать свойства этого артефакта." } } } } },
    [9364] = { d = 25.6, v = "human-male", n = { x = 306 }, c = { x = { { 0.00, "В ходе исследований я выявил потрясающее свойство радужной раковины." }, { 4.78, "Возьми раковину и наложи заклинание превращения на тварей Бича Злобы в Азшаре." }, { 10.32, "Через несколько мгновений хаотическая аура раковины создаст нескольких маленьких клонов." }, { 16.55, "Клонов надо убить – как можно скорее! – и тогда раковина вберёт в себя их сущность." }, { 22.41, "Возвращайся ко мне, когда раковина будет полна." } } }, t = { d = 9.1, v = "human-male", n = { x = 99 }, c = { x = { { 0.00, "Прекрасно!" }, { 0.86, "Прекрасно!" }, { 1.72, "Теперь мы можем использовать собранную магическую силу для создания нового заклинания." }, { 8.62, "Смотри!" } } } } },
    [9365] = { d = 12.3, v = "narrator", n = { x = 114 }, c = { x = { { 0.00, "Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом." }, { 5.92, "Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше..." } } }, t = { d = 11.9, g = 1, v = "dwarf-male", n = { m = 112, f = 117 }, c = { m = { { 0.00, "Сегодня ты показал себя." }, { 2.08, "Мне почти нечего тебе дать, но у меня есть эта корона – достойный дар для завоевателя." }, { 9.14, "Пусть она освещает твой путь." } }, f = { { 0.00, "Сегодня ты показала себя." }, { 2.19, "Мне почти нечего тебе дать, но у меня есть эта корона – достойный дар для завоевательницы." }, { 9.66, "Пусть она освещает твой путь." } } } } },
    [9367] = { d = 42.2, v = "dwarf-male", n = { x = 485 }, c = { x = { { 0.00, "Вновь наступает праздник Огненного солнцеворота!" }, { 3.45, "Каждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажжёнными в наших столичных городах." }, { 15.12, "По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Середине Лета." }, { 24.84, "На самом деле, если ты не против, у меня для тебя есть задание." }, { 29.46, "Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах." }, { 35.92, "Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!" } } }, t = { d = 16.8, v = "dwarf-male", n = { x = 199 }, c = { x = { { 0.00, "Превосходно!" }, { 0.92, "Похоже, в этом году мы избрали ответственных Хранителей праздничных костров, если огни поддерживаются так хорошо, как ты утверждаешь." }, { 10.53, "Спасибо за проведённое исследование; вот, прими это как небольшой знак моей благодарности." } } } } },
    [9368] = { d = 48.5, v = "scourge-male#82", n = { x = 494 }, c = { x = { { 0.00, "Вновь наступает праздник Огненного солнцеворота!" }, { 3.92, "Каждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажжёнными в наших столичных городах." }, { 17.15, "По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Огненному солнцевороту." }, { 28.83, "На самом деле, если ты не против, у меня для тебя есть задание." }, { 34.07, "Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах." }, { 41.39, "Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!" } } }, t = { d = 19.4, v = "scourge-male#82", n = { x = 199 }, c = { x = { { 0.00, "Превосходно!" }, { 1.05, "Похоже, в этом году мы избрали ответственных Хранителей праздничных костров, если огни поддерживаются так хорошо, как ты утверждаешь." }, { 12.13, "Спасибо за проведённое исследование; вот, прими это как небольшой знак моей благодарности." } } } } },
    [9386] = { d = 21.6, v = "tauren-female#71", n = { x = 198 }, c = { x = { { 0.00, "Неужели тебе этого так хочется?" }, { 2.88, "Ну что ж, если снова желаешь спуститься в глубины, я с радостью тебя вознагражу." }, { 10.00, "Отыщи костры, горящие в Стратхольме, Некроситете, Забытом Городе и в залах самого Пика Чёрной горы." }, { 18.88, "Я буду ждать твоего возвращения." } } } },
    [9388] = { d = 33.4, v = "dwarf-male", n = { x = 402 }, c = { x = { { 0.00, "Сегодня по всему миру горит множество огней." }, { 3.20, "Сложнее всего присматривать за теми кострами, которые пылают зелёным; без присмотра они не будут гореть долго." }, { 10.92, "Убедись, что изумрудные огни всё ещё горят в Калимдоре – пусть наш Хранитель костров успокоится." }, { 17.50, "Ты найдёшь эти костры вблизи Кабестана в Степях, неподалёку от Меча Властителя на Тёмном Берегу, в Ясеневом лесу у моста около Аванпоста Среброкрылых, и поблизости от дороги на Утёс Ветрорезов вдоль главного тракта в Когтистых горах." } } }, t = { d = 13.0, v = "tauren-female#71", n = { x = 112 }, c = { x = { { 0.00, "Ах, так они ещё горят." }, { 2.05, "Какая радость!" }, { 3.44, "Было бы горько, если бы их пламя угасло до срока." }, { 8.04, "Хорошая работа." }, { 9.51, "Прими это вместе с моим благословением." } } } } },
    [9389] = { d = 35.9, v = "dwarf-male", n = { x = 454 }, c = { x = { { 0.00, "Во время праздника Огненного солнцеворота по всей земле традиционно зажигаются мириады огней." }, { 6.22, "Кое-кто считает, что зелёное пламя является самым изящным, поскольку его труднее всего поддерживать, и оно имеет столь уникальный оттенок." }, { 15.52, "Убедись, что это пламя всё ещё горит в Восточных королевствах, чтобы успокоить нашего хранителя огня." }, { 22.35, "Эти костры размещены около Дун Модра в Болотине, поблизости от деревни Погребальных Костров в Серебряном бору, на утёсах неподалёку от маяка Западного края и возле разрушенной башни в предгорьях Хиллсбрада." } } }, t = { d = 23.0, v = "tauren-female#71", n = { x = 208 }, c = { x = { { 0.00, "Так ты возвращаешься, повидав изумрудное пламя, горящее в разных уголках континента..." }, { 7.71, "И что ты об этом думаешь?" }, { 9.98, "Несомненно, это редкостное и замечательное зрелище." }, { 14.60, "Однако я осознаю, что весомая награда ценится больше... поэтому возьми вот это за твои труды." } } } } },
    [9415] = { d = 13.8, v = "dwarf-male", n = { x = 147 }, c = { x = { { 0.00, "Ты новобранец маршала Синестена?" }, { 2.43, "Ну, конечно." }, { 3.38, "Чего ты ждёшь?" }, { 4.46, "Наши солдаты умирают там, в пустыне." }, { 7.23, "Правда, тебе не терпится к ним присоединиться?" }, { 10.68, "Иди, и смотри, не присохни к песку по пути." } } }, t = { d = 13.8, v = "dwarf-male", n = { x = 166 }, c = { x = { { 0.00, "Альянсу нужна помощь всех, кто способен держать оружие." }, { 3.89, "Орда регулярно получает подкрепление с северной части континента, и мы изо всех сил стараемся от них не отстать." }, { 11.60, "Позволь, я объясню тебе ситуацию." } } } } },
    [9416] = { d = 24.5, g = 1, v = "orc-male", n = { m = 251, f = 251 }, c = { m = { { 0.00, "Должно быть, ты один из новобранцев генерала Кирики." }, { 4.08, "Пора тебе браться за дело." }, { 6.26, "В пустыне бойцы быстро выдыхаются." }, { 9.01, "Дворфы ежедневно получают подкрепление, а мы не должны им уступать." }, { 14.21, "Полезные ископаемые Силитуса наши!" }, { 16.96, "Генерал тебя проинструктирует." }, { 19.35, "Не моё дело – учить тебя." }, { 21.39, "Мне приказали только найти тебя." } }, f = { { 0.00, "Должно быть, ты одна из новобранцев генерала Кирики." }, { 4.19, "Пора тебе браться за дело." }, { 6.43, "В пустыне бойцы быстро выдыхаются." }, { 9.25, "Дворфы ежедневно получают подкрепление, а мы не должны им уступать." }, { 14.59, "Полезные ископаемые Силитуса наши!" }, { 17.41, "Генерал тебя проинструктирует." }, { 19.86, "Не моё дело – учить тебя." }, { 21.96, "Мне приказали только найти тебя." } } }, t = { d = 8.6, v = "orc-female#58", n = { x = 87 }, c = { x = { { 0.00, "Хорошо, что ты здесь, но на любезности времени нет." }, { 3.99, "Я проведу инструктаж, и ты сразу отправляйся в бой." }, { 8.06, "Слушай." } } } } },
    [9419] = { d = 22.9, v = "dwarf-male", n = { x = 276 }, c = { x = { { 0.00, "Совсем недавно мы выяснили, что Орда добывает в Силитусе полезные ископаемые." }, { 5.29, "Мы думали, что в таком климате не стоит держать много войск." }, { 9.42, "К сожалению, выяснилось, насколько важны эти полезные ископаемые, и теперь мы спешно пытаемся догнать Орду по масштабам добычи." }, { 18.16, "Если ты хочешь мне помочь, ступай в пустыню и принеси оттуда силитист." } } }, t = { d = 12.6, g = 1, v = "dwarf-male", n = { m = 139, f = 140 }, c = { m = { { 0.00, "Хвала Свету!" }, { 0.99, "Ты добился успеха!" }, { 2.36, "Начни мы добычу кристаллов раньше, не оказались бы в таком отчаянном положении." }, { 8.14, "Мы не допустим, чтобы сокровища пустыни попали в руки Орды." } }, f = { { 0.00, "Хвала Свету!" }, { 1.00, "Ты добилась успеха!" }, { 2.46, "Начни мы добычу кристаллов раньше, не оказались бы в таком отчаянном положении." }, { 8.32, "Мы не допустим, чтобы сокровища пустыни попали в руки Орды." } } } } },
    [9422] = { d = 22.3, v = "orc-female#58", n = { x = 252 }, c = { x = { { 0.00, "Мы давно начали добычу кристаллов пустыни Силитуса." }, { 3.81, "Поначалу мы сталкивались лишь с опасностями, исходящими от местных жителей, песка, пыли и жары." }, { 10.71, "Теперь же Альянс пронюхал, чем мы тут занимаемся, и началась гонка за добычей полезных ископаемых." }, { 17.80, "У меня каждая пара рук на счету, надеюсь, ты мне тоже поможешь." } } }, t = { d = 8.6, v = "orc-female#58", n = { x = 88 }, c = { x = { { 0.00, "Ты молодец." }, { 0.96, "Мы отправим добытые ресурсы на склад, а наши приобретения всё равно что потери для наших врагов!" } } } } },
    [9556] = { d = 30.9, g = 1, v = "narrator", n = { m = 334, f = 335 }, c = { m = { { 0.00, "Ты без сомнения прекрасно проявил себя в борьбе за башни, герой, и непременно получишь свою награду за доблесть." }, { 8.41, "Но сначала ты должен доказать, что понимаешь всю глубину разыгравшейся здесь трагедии." }, { 14.73, "Отправляйся на улицы Стратхольма и найди сосуд со святой водой." }, { 19.51, "Отнеси его в квартал магов в Штормград или Подгород..." }, { 23.68, "Если твои сородичи одержали верх в тех землях, тебе удастся добраться до кого-то из моих коллег." } }, f = { { 0.00, "Ты без сомнения прекрасно проявила себя в борьбе за башни, героиня, и непременно получишь свою награду за доблесть." }, { 8.49, "Но сначала ты должна доказать, что понимаешь всю глубину разыгравшейся здесь трагедии." }, { 14.72, "Отправляйся на улицы Стратхольма и найди сосуд со святой водой." }, { 19.43, "Отнеси его в квартал магов в Штормград или Подгород..." }, { 23.54, "Если твои сородичи одержали верх в тех землях, тебе удастся добраться до кого-то из моих коллег." } } } },
    [9664] = { d = 29.9, v = "dwarf-male", n = { x = 345 }, c = { x = { { 0.00, "Добро пожаловать в Чумные земли." }, { 2.41, "Как тебе известно, Отрёкшиеся и их приспешники удерживают земли к западу отсюда, несмотря на все наши усилия." }, { 10.24, "Командующие Альянса приняли решение возвести здесь, на востоке, новые укрепления, чтобы затянуть петлю вокруг наших врагов." }, { 19.24, "Башни, давно заброшенные и позабытые ещё в дни Лордерона, необходимо захватить и восстановить." }, { 25.96, "Это очень опасные земли, и нам потребуется твоя помощь." } } }, t = { d = 8.9, v = "dwarf-male", n = { x = 99 }, c = { x = { { 0.00, "Превосходно." }, { 0.97, "Теперь необходимо удерживать эти башни до прибытия подкрепления – для этого нам потребуется твоя помощь." } } } } },
    [9665] = { d = 26.2, v = "orc-male", n = { x = 290 }, c = { x = { { 0.00, "Разведчики Отрёкшихся раскрыли планы Альянса создать новые форпосты в Восточных Чумных землях на базе заброшенных башен." }, { 9.16, "Нельзя позволить им закрепиться на наших восточных границах, поэтому необходимо помешать планам Альянса." }, { 17.08, "Мы должны выбить их из тех башен, которые они уже успели захватить, и отстоять от новых атак те, что под нашим контролем." } } }, t = { d = 11.8, v = "orc-male", n = { x = 114 }, c = { x = { { 0.00, "Это хорошие вести." }, { 1.67, "Мы будем биться в Чумных землях до конца, пока окончательно не разобьём силы Альянса." }, { 8.88, "До этого дня надеюсь на твою помощь." } } } } },
    [60860] = { t = { d = 25.8, g = 1, v = "human-female#111", n = { m = 277, f = 278 }, c = { m = { { 0.00, "Привет, герой!" }, { 1.05, "А я тебя ждал." }, { 2.15, "Один мой знакомый просил кое-что тебе передать." }, { 5.47, "Сказал, что это награда за покупку, которую ты совершил у ваших общих друзей." }, { 10.82, "Не знаешь, о чём это он?" }, { 12.48, "В общем, вот твоя награда." }, { 14.33, "О, кстати: этот самый знакомый, Ландро Дальнострел, сказал, что если ты вдруг потеряешь эту вещицу, то сможешь получить замену у него в Пиратской бухте." } }, f = { { 0.00, "Привет, героиня!" }, { 1.53, "А я тебя ждал." }, { 2.63, "Один мой знакомый просил кое-что тебе передать." }, { 5.94, "Сказал, что это награда за покупку, которую ты совершила у ваших общих друзей." }, { 11.96, "Не знаешь, о чём это он?" }, { 13.62, "В общем, вот твоя награда." }, { 15.47, "О, кстати: этот самый знакомый, Ландро Дальнострел, сказал, что если ты вдруг потеряешь эту вещицу, то сможешь получить замену у него в Пиратской бухте." } } } } },
    [65593] = { d = 37.8, v = "scourge-male#83", n = { x = 362 }, c = { x = { { 0.00, "Инкуба привлекают сердца влюблённых, и чем крепче любовь, тем надёжнее приманка." }, { 6.79, "Своим незримым оком я вижу двоих, перед чьей любовью не устоит ни один инкуб." }, { 13.65, "Авелина Лилли из Серебряного бора шьёт одежду для павших чародеев Янтарной мельницы." }, { 20.99, "Исаак Пирсон из Степей надеется заработать состояние в приморском Кабестане." }, { 27.62, "Они трудятся, не зная отдыха, на разных концах света, но их сердца тоскуют лишь друг о друге." }, { 35.74, "Принеси сердца Карендину." } } }, t = { d = 5.4, v = "scourge-male#82", n = { x = 37 }, c = { x = { { 0.00, "Как и ожидалось." }, { 2.00, "Превосходная работа." }, { 4.55, "Идиоты." } } } } },
    [65597] = { d = 30.8, v = "scourge-male#82", n = { x = 270 }, c = { x = { { 0.00, "Время наконец пришло." }, { 2.08, "Отнеси сердца в круг призыва внизу." }, { 5.41, "Положи их в центр и позови инкуба." }, { 8.57, "Когда демон поймёт, что его заманили в ловушку, ему это ох как не понравится." }, { 15.73, "Сопротивляйся его попыткам обольстить тебя." }, { 19.81, "Его надо подчинить себе полностью." }, { 23.14, "Только после этого я смогу научить тебя, как заставить демона выполнять твою волю." } } }, t = { d = 27.6, g = 1, v = "scourge-male#82", n = { m = 231, f = 232 }, c = { m = { { 0.00, "Впечатляет." }, { 1.15, "Очень впечатляет." }, { 2.91, "Сайаады умеют охотиться на смертных." }, { 6.52, "Не один герой считал себя достаточно сильным, чтобы повелевать одним из них, а в итоге сам оказывался у него в подчинении." }, { 18.51, "Это испытание тебя не сломило, и ты заслужил награду." }, { 23.80, "Я научу тебя заклинанию призыва инкуба." } }, f = { { 0.00, "Впечатляет." }, { 1.12, "Очень впечатляет." }, { 2.83, "Сайаады умеют охотиться на смертных." }, { 6.35, "Не один герой считал себя достаточно сильным, чтобы повелевать одним из них, а в итоге сам оказывался у него в подчинении." }, { 18.03, "Это испытание тебя не сломило, и ты заслужила награду." }, { 23.26, "Я научу тебя заклинанию призыва инкуба." } } } } },
    [65601] = { d = 38.7, g = 1, v = "orc-male", n = { m = 366, f = 367 }, c = { m = { { 0.00, "Мужчин-сайаадов называют инкубами." }, { 2.88, "Эти существа исполнены злобы и изощрённой хитрости." }, { 7.20, "Демона можно привлечь в наш мир особой приманкой – символом великой дружбы и верности." }, { 14.48, "Если ты готов довериться слепому поводырю, то слушай." }, { 19.03, "К востоку от Расселины Теней, у Волока Оргриммара, живёт Магар." }, { 24.33, "Он тоскует по Крилге, своей давно пропавшей подруге." }, { 28.80, "Найди Магара." }, { 30.02, "Он попросит тебя отыскать некую ценность." }, { 33.58, "Это и есть ключ, который надо отнести Ган'рулу." } }, f = { { 0.00, "Мужчин-сайаадов называют инкубами." }, { 2.97, "Эти существа исполнены злобы и изощрённой хитрости." }, { 7.43, "Демона можно привлечь в наш мир особой приманкой – символом великой дружбы и верности." }, { 14.94, "Если ты готова довериться слепому поводырю, то слушай." }, { 19.71, "К востоку от Расселины Теней, у Волока Оргриммара, живёт Магар." }, { 25.19, "Он тоскует по Крилге, своей давно пропавшей подруге." }, { 29.80, "Найди Магара." }, { 31.06, "Он попросит тебя отыскать некую ценность." }, { 34.73, "Это и есть ключ, который надо отнести Ган'рулу." } } }, t = { d = 6.2, v = "orc-male", n = { x = 54 }, c = { x = { { 0.00, "Кто рассказал тебе о Крилге?" }, { 2.50, "Ты знаешь, где она?" }, { 4.21, "Лучше не шути со мной..." } } } } },
    [65602] = { d = 29.5, v = "human-male#50", n = { x = 329 }, c = { x = { { 0.00, "Чтобы призвать инкуба, нужен мощный реагент – символ дружбы и верности." }, { 5.33, "Я заглянул в прошлое сквозь туман времени и увидел небольшую статуэтку, которая годится для ритуала." }, { 12.63, "Тысячи лет назад она принадлежала двум друзьям." }, { 16.12, "Они давно мертвы, но их реликвия сохранилась." }, { 19.47, "Иди по дороге в Ясеневый лес, потом сверни на запад и иди дальше мимо заставы Мейстры." }, { 25.92, "Ищи дом между деревьев – статуэтка находится в нём." } } }, t = { d = 15.5, v = "human-male#50", n = { x = 129 }, c = { x = { { 0.00, "*Гакин вертит в руке деревянную статуэтку.*" }, { 3.36, "Я чувствую эмоциональную энергию, заключённую в этом артефакте, – время её ничуть не ослабило." }, { 10.52, "Инкуб слетится на неё, как муха на мёд." }, { 13.50, "Такар никогда не подводит." } } } } },
    [65603] = { d = 29.6, g = 1, v = "human-male#50", n = { m = 320, f = 321 }, c = { m = { { 0.00, "Пора." }, { 0.46, "Бери статуэтку и спускайся в гробницу." }, { 3.26, "Круг призыва готов, поставь статуэтку точно в центре." }, { 7.17, "Откроются врата, и инкуб явится в наш мир." }, { 10.23, "Сайаадов нельзя недооценивать." }, { 12.45, "Как только демон поймёт, что его обманули, он сразу атакует." }, { 16.81, "Используй всё, чему ты научился, чтобы победить его." }, { 20.66, "Если всё получится, возвращайся ко мне, и я подчиню демона твоей воле." }, { 25.74, "Но если ты проиграешь, твоя душа обречена." } }, f = { { 0.00, "Пора." }, { 0.47, "Бери статуэтку и спускайся в гробницу." }, { 3.35, "Круг призыва готов, поставь статуэтку точно в центре." }, { 7.37, "Откроются врата, и инкуб явится в наш мир." }, { 10.52, "Сайаадов нельзя недооценивать." }, { 12.80, "Как только демон поймёт, что его обманули, он сразу атакует." }, { 17.29, "Используй всё, чему ты научилась, чтобы победить его." }, { 21.31, "Если всё получится, возвращайся ко мне, и я подчиню демона твоей воле." }, { 26.53, "Но если ты проиграешь, твоя душа обречена." } } }, t = { d = 22.1, g = 1, v = "human-male#50", n = { m = 256, f = 257 }, c = { m = { { 0.00, "Неплохо." }, { 0.63, "Ты одолел демона, и твоя воля осталась несломленной." }, { 4.32, "Не один герой считал себя достаточно сильным, чтобы подчинить сайаада, а в итоге становился его следующей добычей." }, { 12.39, "Рад видеть, что ты не из таких глупцов." }, { 15.08, "Смотри внимательно, и я научу тебя заклинанию, которым ты сможешь призывать своего нового инкуба." } }, f = { { 0.00, "Неплохо." }, { 0.63, "Ты одолела демона, и твоя воля осталась несломленной." }, { 4.43, "Не один герой считал себя достаточно сильным, чтобы подчинить сайаада, а в итоге становился его следующей добычей." }, { 12.60, "Рад видеть, что ты не из таких глупцов." }, { 15.32, "Смотри внимательно, и я научу тебя заклинанию, которым ты сможешь призывать своего нового инкуба." } } } } },
    [65604] = { d = 37.4, v = "orc-male", n = { x = 353 }, c = { x = { { 0.00, "Да... то, что нужно." }, { 1.71, "Давние чувства переплелись с нитями ткани." }, { 5.44, "Любовь проходит вдоль стежков." }, { 8.08, "Инкуб не сможет устоять." }, { 10.25, "Отнеси это к кругу призыва в шатре Нииру." }, { 13.98, "Вызови гнусного инкуба и покажи ему, кто здесь хозяин." }, { 18.72, "Не жди лёгкой победы." }, { 20.51, "Приготовься пустить в ход всю свою магическую силу." }, { 24.93, "Многие чернокнижники поплатились жизнью, недооценив демона." }, { 30.06, "Когда подчинишь инкуба, верни ткань мне." }, { 33.56, "Нужно будет сообщить Магару о твоей находке." } } }, t = { d = 34.6, v = "orc-male", n = { x = 340 }, c = { x = { { 0.00, "Ха-ха!" }, { 0.59, "Я и не сомневался в победе!" }, { 2.78, "Теперь, когда инкуб подчинён, я с удовольствием научу тебя его призывать." }, { 8.79, "Твоя сила растёт, но я уверен, что это лишь первый шаг на пути к настоящей мощи." }, { 15.31, "Я верну платок Магару." }, { 17.21, "Я много лет знаю этого орка и никогда бы не подумал, что он способен на такую глубокую привязанность." }, { 25.42, "Пусть его чувства станут напоминанием того, чем мы отличаемся от демонов." }, { 31.35, "Это их тёмная магия служит нам, а не мы им." } } } } },
    [65610] = { d = 28.8, v = "orc-male", n = { x = 301 }, c = { x = { { 0.00, "Я встретил Крилге, когда изготавливал луноткань в Ясеневом лесу." }, { 4.96, "Его отправили туда защищать местных жителей, но однажды он пропал..." }, { 10.27, "Его посчитали дезертиром и прекратили поиски, но я не верю, что он сбежал." }, { 15.92, "Мы часто ходили к Зеркалу Небес, пока озеро не заполонили дикие болотные твари." }, { 22.13, "Я редко прошу других об услуге, но буду рад, если ты поищешь в Ясеневом лесу его следы." } } }, t = { d = 7.0, v = "orc-male", n = { x = 53 }, c = { x = { { 0.00, "Что это у тебя?" }, { 1.62, "Платок... из луноткани?" }, { 3.97, "Надеюсь, это не попытка флирта." } } } } },
    [76156] = { d = 24.6, g = 1, v = "tauren-male", n = { x = 230 }, c = { m = { { 0.00, "Я чувствую в тебе талант к искусству скрытности, герой." }, { 4.54, "Возьми эту маску, проберись в ближайшую шахту Торговой Компании и укради их припасы." }, { 11.50, "Да, маски хватит – ловкий разбойник умеет усыпить бдительность одной лишь обаятельной улыбкой и хитроумным трюком." }, { 20.80, "Тебе это тоже вполне под силу." } }, f = { { 0.00, "Я чувствую в тебе талант к искусству скрытности, героиня." }, { 4.93, "Возьми эту маску, проберись в ближайшую шахту Торговой Компании и укради их припасы." }, { 12.24, "Да, маски хватит – ловкий разбойник умеет усыпить бдительность одной лишь обаятельной улыбкой и хитроумным трюком." }, { 22.02, "Тебе это тоже вполне под силу." } } }, t = { d = 6.2, v = "tauren-male", n = { x = 47 }, c = { x = { { 0.00, "Хм... наверное, к маскировке у тебя особых способностей нет." } } } } },
    [76160] = { d = 26.8, v = "tauren-male", n = { x = 253 }, c = { x = { { 0.00, "Быть может, у тебя склонность к ядам, а не к маскировке." }, { 4.83, "К северу отсюда находится логово гарпий." }, { 8.41, "Они гнездятся на деревьях, которые вырабатывают необычайно ядовитую смолу." }, { 14.88, "Собери упавшие шишки и разотри их в кашицу." }, { 18.70, "Если смазать ею клинок, любая рана прожжёт плоть до кости, а кровь посолонеет как морская вода." } } }, t = { d = 16.1, g = 1, v = "tauren-male", n = { m = 148, f = 149 }, c = { m = { { 0.00, "Где яд, шаман?" }, { 1.25, "Это же перетертые кедровые орешки." }, { 4.29, "Ты точно ничего не перепутал?" }, { 6.87, "Их впору на хлеб мазать, а не на кинжал." }, { 10.30, "Хотя против врага с аллергией на орехи лучше оружия не придумаешь." } }, f = { { 0.00, "Где яд, шаман?" }, { 1.25, "Это же перетертые кедровые орешки." }, { 4.29, "Ты точно ничего не перепутала?" }, { 6.95, "Их впору на хлеб мазать, а не на кинжал." }, { 10.38, "Хотя против врага с аллергией на орехи лучше оружия не придумаешь." } } } } },
    [76240] = { d = 22.2, v = "tauren-male", n = { x = 195 }, c = { x = { { 0.00, "Не будем терять надежду и попробуем в последний раз." }, { 4.80, "Я всё ещё чувствую в тебе талант, но, как видно, с ходу его не раскрыть." }, { 11.41, "Достань мне сырую блестящую рыбку и разделай её этими кинжалами." }, { 17.36, "Доверься инстинктам – пусть твои руки сами действуют." } } }, t = { d = 25.4, g = 1, v = "tauren-male", n = { x = 221 }, c = { m = { { 0.00, "Впечатляюще, герой." }, { 1.78, "К моему сожалению, тебе всё же не хватает отточенности движений." }, { 7.51, "Пусть ты и не сможешь продолжить моё наследие, обучая мой народ тонкому искусству боя, но прошу тебя принять это от меня в качестве прощального подарка, герой." }, { 21.81, "Герои вроде тебя хорошо послужат Орде." } }, f = { { 0.00, "Впечатляюще, героиня." }, { 1.93, "К моему сожалению, тебе всё же не хватает отточенности движений." }, { 7.62, "Пусть ты и не сможешь продолжить моё наследие, обучая мой народ тонкому искусству боя, но прошу тебя принять это от меня в качестве прощального подарка, героиня." }, { 21.99, "Герои вроде тебя хорошо послужат Орде." } } } } },
    [78088] = { d = 29.5, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Когда вы держите таинственную сферу в руках, вас наполняет ледяной ужас." }, { 5.91, "У вас в голове еле слышно звучат отголоски чьей-то речи." }, { 10.57, "Низкий, утробный голос говорит на языке, в котором вы узнаете демонический." }, { 16.88, "Хотя вы и паладин, эта магия вам незнакома." }, { 20.45, "Найдите в Калимдоре более опытного паладина, который поможет вам понять истинную сущность этого зловещего предмета." } } }, t = { d = 3.0, g = 1, v = "human-male", n = { m = 32, f = 35 }, c = { m = { { 0.00, "Ты правильно сделал, что принёс это мне." } }, f = { { 0.00, "Ты правильно сделала, что принесла это мне." } } } } },
    [78089] = { d = 21.0, v = "human-male", n = { x = 234 }, c = { x = { { 0.00, "Эту сферу окутывает мощная тёмная аура." }, { 2.99, "По своей природе она явно демоническая, но вот в чём заключается её предназначение, даже предположить не могу." }, { 11.02, "Отнеси её одной даме по имени Катерина Чистая – её ты найдёшь в штормградском соборе." }, { 17.26, "Возможно, она расскажет тебе про эту сферу больше." } } }, t = { d = 3.7, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Осматривает сферу, озабоченно прищурившись." } } } } },
    [78090] = { d = 22.2, v = "human-female", n = { x = 263 }, c = { x = { { 0.00, "Не могу сказать об этой сфере ничего определённого." }, { 3.67, "Тут нужна помощь... специалиста." }, { 6.00, "Нам известно, что в Штормграде действует свой культ чернокнижников." }, { 10.64, "Официально мы не признаём его существование." }, { 13.73, "Неофициально их познания в общении с демонами бывают полезны." }, { 18.11, "Найди представителя этого культа и расспроси его о сфере." } } }, t = { d = 5.0, v = "human-female", n = { x = 55 }, c = { x = { { 0.00, "Так Серебряной Длани нужна моя помощь?" }, { 3.08, "Она вам обойдётся недёшево." } } } } },
    [78091] = { d = 18.5, v = "human-female", n = { x = 215 }, c = { x = { { 0.00, "Я изучу сферу и расскажу о своих выводах, но сначала твоя очередь мне помогать." }, { 5.84, "Чернокнижники клана Чёрной горы усиливают ритуалы призыва особыми ароматическими солями." }, { 12.26, "Достань мне их у орков в Красногорье." }, { 15.02, "Когда вернёшься, я изложу результаты исследований." } } }, t = { d = 8.0, v = "human-female", n = { x = 75 }, c = { x = { { 0.00, "А... соли." }, { 0.88, "Я совсем про них забыла." }, { 2.86, "Эта сфера не похожа ни на что из того, что мне доводилось видеть." } } } } },
    [78092] = { d = 37.2, v = "human-female", n = { x = 438 }, c = { x = { { 0.00, "Эта сфера содержит в себе очень опасную разумную сущность, и даже такой опытной чернокнижнице, как я, непросто противиться ей достаточно долго." }, { 10.18, "Хоть мне и неловко признавать это, но сферу необходимо уничтожить." }, { 14.82, "Она практически неразрушима, но, возможно, с ней сможет справиться оружие могущественного владыки демонов." }, { 22.27, "Я слыхала, его можно найти в Ясеневом лесу – на том самом месте, где в своё время был повержен властитель преисподней Маннорот." }, { 31.24, "Собери там частицы сущности погибшего демона, а затем расколи сферу о копьё Маннорота." } } }, t = { d = 2.9, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Вы поднимаете сферу к копью." } } } } },
    [78093] = { d = 7.7, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Осколки разрушенной сферы падают к вашим ногам." }, { 3.84, "Делгрену будет полезно знать, что у вас получилось." } } }, t = { d = 14.0, g = 1, v = "human-male", n = { m = 144, f = 144 }, c = { m = { { 0.00, "Какое облегчение." }, { 1.39, "Но кто бы ни наблюдал за Азеротом через эту сферу... чувствую, он будет не рад, что её уничтожили." }, { 8.85, "Прими это в знак благодарности за твои старания." }, { 12.62, "И... будь осторожен." } }, f = { { 0.00, "Какое облегчение." }, { 1.35, "Но кто бы ни наблюдал за Азеротом через эту сферу... чувствую, он будет не рад, что её уничтожили." }, { 8.60, "Прими это в знак благодарности за твои старания." }, { 12.26, "И... будь осторожна." } } } } },
    [78124] = { t = { d = 10.5, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.65, "Твоими стараниями наши знания растут." }, { 3.43, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } }, npc = { [211022] = { d = 13.3, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.82, "Твоими стараниями наши знания растут." }, { 4.34, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } } } },
