    [78149] = { t = { d = 13.4, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.82, "Твоими стараниями наши знания растут." }, { 4.37, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } }, npc = { [211033] = { d = 10.4, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.64, "Твоими стараниями наши знания растут." }, { 3.38, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } } } },
    [78150] = { t = { d = 5.5, v = "human-male", n = { x = 67 }, c = { x = { { 0.00, "Благодаря твоим пожертвованиям библиотека процветает." }, { 3.89, "Пожалуйста, возьми это." } } }, npc = { [211022] = { d = 6.9, v = "scourge-male", n = { x = 67 }, c = { x = { { 0.00, "Благодаря твоим пожертвованиям библиотека процветает." }, { 4.83, "Пожалуйста, возьми это." } } } } } } },
    [78261] = { d = 34.6, v = "narrator", n = { x = 327 }, c = { x = { { 0.00, "В сундуке лежит записка." }, { 2.05, "Привет!" }, { 2.70, "Меня интересует сокровище под названием рог Кселтоса, которое хранится где-то в крепости Тёмного Клыка." }, { 11.04, "Туда опасно ходить без боевых товарищей, но сейчас всё нужно сделать как можно тише." }, { 17.98, "Поэтому ты пойдёшь в одиночку." }, { 20.39, "У меня есть агент в Когтистых горах – его зовут Виеникс." }, { 25.07, "Он проведёт тебя за ворота во внутренний двор." }, { 28.73, "Остальное за тобой." }, { 30.33, "Принеси рог сюда, и я сразу вышлю вознаграждение." }, { 34.35, "– Эс." } } }, t = { d = 2.9, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Вы кладёте рог Кселтоса в сундук." } } } } },
    [78270] = { d = 35.5, v = "narrator", n = { x = 341 }, c = { x = { { 0.00, "В сундуке лежит записка." }, { 2.01, "Снова привет." }, { 3.16, "Меня интересует сокровище под названием рог Кселтоса, которое хранится где-то в крепости Тёмного Клыка." }, { 11.36, "Туда обычно не ходят без боевых товарищей, но на этот раз всё нужно сделать как можно тише." }, { 18.70, "Поэтому ты пойдёшь в одиночку." }, { 21.07, "У меня есть агент в Когтистых горах – его зовут Виеникс." }, { 25.68, "Он поможет тебе пройти за ворота во внутренний двор." }, { 29.85, "Остальное за тобой." }, { 31.43, "Принеси рог сюда, и вскоре я вышлю вознаграждение." }, { 35.46, "С." } } }, t = { d = 8.7, v = "goblin-male#110", n = { x = 89 }, c = { x = { { 0.00, "Отличная работа." }, { 1.37, "Думаю, для человека твоего ремесла это была лёгкая прогулка." }, { 6.28, "Как и обещано, вот твоя награда." } } } } },
    [78307] = { t = { d = 4.1, v = "narrator", n = { x = 11 }, c = { x = { { 0.00, "В сундуке лежит записка." }, { 2.53, "До встречи." }, { 3.71, "– Эс." } } } } },
    [78676] = { d = 37.0, g = 1, v = "narrator", n = { m = 379, f = 380 }, c = { m = { { 0.00, "В сундуке лежит записка" }, { 1.85, "Хорошо, что ты вернулся." }, { 3.70, "На этот раз мне нужен артефакт, известный как глаз Бхосски." }, { 8.16, "Согласно моим источникам, он находится где-то в монастыре Алого ордена." }, { 13.65, "Как и тогда, в крепости Тёмного Клыка, тебе нужно проникнуть в монастырь в одиночку." }, { 20.03, "Возможно, тебе следует сначала раздобыть маскировку – так будет несколько проще перемещаться в самом монастыре." }, { 28.53, "Наверняка на его территории что-нибудь найдётся." }, { 32.17, "Принеси артефакт сюда и получишь награду так же, как раньше." }, { 36.77, "– К." } }, f = { { 0.00, "В сундуке лежит записка" }, { 1.79, "Хорошо, что ты вернулась." }, { 3.65, "На этот раз мне нужен артефакт, известный как глаз Бхосски." }, { 7.97, "Согласно моим источникам, он находится где-то в монастыре Алого ордена." }, { 13.28, "Как и тогда, в крепости Тёмного Клыка, тебе нужно проникнуть в монастырь в одиночку." }, { 19.45, "Возможно, тебе следует сначала раздобыть маскировку – так будет несколько проще перемещаться в самом монастыре." }, { 27.69, "Наверняка на его территории что-нибудь найдётся." }, { 31.21, "Принеси артефакт сюда и получишь награду так же, как раньше." }, { 35.65, "– К." } } }, t = { d = 3.0, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Вы кладёте глаз Бхосски в сундук." } } } } },
    [78699] = { t = { d = 7.3, g = 1, v = "narrator", n = { m = 35, f = 35 }, c = { m = { { 0.00, "В сундуке лежит записка." }, { 2.54, "Для путника." }, { 3.82, "Я буду за тобой «приглядывать»." }, { 7.00, "– К." } }, f = { { 0.00, "В сундуке лежит записка." }, { 2.54, "Для путницы." }, { 3.82, "Я буду за тобой «приглядывать»." }, { 7.00, "– К." } } } } },
    [78823] = { d = 19.4, v = "narrator", n = { x = 204 }, c = { x = { { 0.00, "Рисунок выполнен грубыми, широкими штрихами и, кажется, изображает крупную хищную птицу." }, { 7.10, "Несмотря на простоту композиции, художник явно смотрел на это создание со страхом и благоговением." }, { 14.92, "Знаток крупной дичи, вероятно, смог бы рассказать больше." } } }, t = { d = 2.9, v = "dwarf-male", n = { x = 19 }, c = { x = { { 0.00, "Хм, интересная находка..." } } } } },
    [78830] = { d = 37.0, v = "dwarf-male", n = { x = 431 }, c = { x = { { 0.00, "Этот рисунок напомнил мне историю, которую я слышал в недавней экспедиции." }, { 5.21, "Мне рассказали, что всё зверьё в Бесплодных землях держит в страхе птица по имени Гаррик." }, { 11.36, "В последний раз её видели на северо-востоке от лагеря Кэгг." }, { 15.38, "Может, у неё гнездо где-то рядом?" }, { 17.77, "Выманивать такую птаху надо на живца." }, { 20.53, "Я одолжу тебе клетку, в которую можно поймать такую приманку." }, { 24.92, "Мелких зверьков в Бесплодных землях почти нет, так что искать придётся где-нибудь ещё." }, { 30.82, "Если справишься, забери у Гаррик перо." }, { 33.59, "О таком трофее в лагере ещё долго будут судачить." } } }, t = { d = 11.5, v = "dwarf-male", n = { x = 119 }, c = { x = { { 0.00, "Вот это перо – хоть сейчас на шляпу!" }, { 2.87, "Отличная работа." }, { 4.19, "Если хочешь, можешь немного здесь отдохнуть." }, { 7.69, "Уверен, переход через пустыню дался тебе нелегко." } } } } },
    [78916] = { d = 12.9, v = "narrator", n = { x = 129 }, c = { x = { { 0.00, "Ужасного зверя Аку'май больше нет." }, { 3.08, "Во внутренностях раздувшегося трупа блестит огромная переливающаяся жемчужина, наполненная чистой энергией Бездны." } } }, t = { d = 18.0, v = "human-male", n = { x = 198 }, c = { x = { { 0.00, "Аку'май, прислужник Древних богов, мёртв." }, { 3.08, "Такой подвиг под силу лишь настоящим героям." }, { 6.43, "Этот предмет, возможно, станет ключом к куда более глубокому пониманию природы Бездны и её влияния на наш мир." }, { 14.66, "Его нужно немедленно изучить." }, { 16.94, "Благодарю тебя." } } } } },
    [78917] = { d = 13.0, v = "narrator", n = { x = 129 }, c = { x = { { 0.00, "Ужасного зверя Аку'май больше нет." }, { 3.12, "Во внутренностях раздувшегося трупа блестит огромная переливающаяся жемчужина, наполненная чистой энергией Бездны." } } }, t = { d = 24.1, g = 1, v = "tauren-female#71", n = { m = 220, f = 221 }, c = { m = { { 0.00, "Аку'май, прислужник Древних богов, мёртв." }, { 3.73, "Этим деянием ты оказал жителям Калимдора великую услугу." }, { 8.92, "К тому же жемчужина, возможно, станет ключом к куда более глубокому пониманию природы Бездны и её влияния на наш мир." }, { 19.46, "Её нужно немедленно изучить." }, { 22.05, "Ступай с Матерью-Землёй." } }, f = { { 0.00, "Аку'май, прислужник Древних богов, мёртв." }, { 3.68, "Этим деянием ты оказала жителям Калимдора великую услугу." }, { 8.88, "К тому же жемчужина, возможно, станет ключом к куда более глубокому пониманию природы Бездны и её влияния на наш мир." }, { 19.28, "Её нужно немедленно изучить." }, { 21.84, "Ступай с Матерью-Землёй." } } } } },
    [79007] = { d = 19.4, v = "narrator", n = { x = 64 }, c = { x = { { 0.00, "Вы обнаруживаете пепелище, догорающие угли которого уже почти погасли." }, { 6.19, "Среди разбросанных припасов вам попадается обожжённый клочок бумаги." }, { 12.07, "\"Не всё, что горит, пропадает навечно." }, { 15.36, "Найди земли близнецов, а в них – нужное место\"." } } }, t = { d = 6.9, v = "narrator", n = { x = 82 }, c = { x = { { 0.00, "Наткнувшись на ещё один обугленный труп, вы замечаете послание, прикреплённое к деревянной доске." } } } } },
    [79008] = { d = 19.9, v = "narrator", n = { x = 64 }, c = { x = { { 0.00, "Вы обнаруживаете пепелище, догорающие угли которого уже почти погасли." }, { 6.37, "Среди разбросанных припасов вам попадается обожжённый клочок бумаги." }, { 12.42, "\"Не всё, что горит, пропадает навечно." }, { 15.81, "Найди земли близнецов, а в них – нужное место\"." } } }, t = { d = 6.9, v = "narrator", n = { x = 82 }, c = { x = { { 0.00, "Наткнувшись на ещё один обугленный труп, вы замечаете послание, прикреплённое к деревянной доске." } } } } },
    [79090] = { d = 6.4, v = "narrator", n = { x = 63 }, c = { x = { { 0.00, "Часть всадников клана Песни Войны повержена, но битва всё ещё продолжается..." } } } },
    [79091] = { t = { d = 12.2, v = "human-male", n = { x = 147 }, c = { x = { { 0.00, "Спасибо." }, { 0.61, "Говоришь, это из библиотеки Стальгорна?.." }, { 3.39, "Думаю, они не расстроятся из-за этой потери." }, { 6.48, "Если найдёшь другие чародейские труды, которых не хватает в библиотеке, приноси их мне." } } } } },
