    [79094] = { t = { d = 13.7, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.84, "Твоими стараниями наши знания растут." }, { 4.47, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } },
    [79095] = { t = { d = 12.1, v = "scourge-male", n = { x = 115 }, c = { x = { { 0.00, "Спасибо." }, { 0.79, "Благодаря тебе архивы наших знаний растут." }, { 4.66, "Если найдёшь другие чародейские труды, которых не хватает в библиотеке, приноси их мне." } } } } },
    [79096] = { t = { d = 12.2, v = "scourge-male", n = { x = 113 }, c = { x = { { 0.00, "Спасибо." }, { 0.81, "Благодаря тебе наши знания становятся шире." }, { 4.83, "Если найдёшь и другие труды по магии, которые пригодятся библиотеке, приноси их мне." } } }, npc = { [211033] = { d = 9.7, v = "human-male", n = { x = 113 }, c = { x = { { 0.00, "Спасибо." }, { 0.64, "Благодаря тебе наши знания становятся шире." }, { 3.85, "Если найдёшь и другие труды по магии, которые пригодятся библиотеке, приноси их мне." } } } } } } },
    [79097] = { t = { d = 12.3, v = "scourge-male", n = { x = 115 }, c = { x = { { 0.00, "Спасибо." }, { 0.81, "Благодаря тебе архивы наших знаний растут." }, { 4.75, "Если найдёшь другие чародейские труды, которых не хватает в библиотеке, приноси их мне." } } }, npc = { [211033] = { d = 9.9, v = "human-male", n = { x = 115 }, c = { x = { { 0.00, "Спасибо." }, { 0.65, "Благодаря тебе архивы наших знаний растут." }, { 3.83, "Если найдёшь другие чародейские труды, которых не хватает в библиотеке, приноси их мне." } } } } } } },
    [79192] = { d = 22.5, v = "narrator", n = { x = 239 }, c = { x = { { 0.00, "Записка начинается словами: \"В отчёте о задании сказано, что оба совершали поставки, связанные с новой чумой." }, { 8.56, "Мне кажется, с аптекарями нередко происходят подобные несчастные случаи." }, { 14.21, "Если хочешь поговорить в безопасном месте, найди моё уютное пристанище в горах между Степями и Пустошами\"." } } }, t = { d = 8.8, v = "narrator", n = { x = 96 }, c = { x = { { 0.00, "Очевидно, здесь встают лагерем наёмники и искатели приключений." }, { 4.94, "Вы замечаете уголок записки, колышущийся на ветру." } } } } },
    [79229] = { d = 29.8, v = "narrator", n = { x = 306 }, c = { x = { { 0.00, "Разрушенный лагерь представляет собой жуткое зрелище." }, { 4.31, "Вы видите перед собой останки двух убитых людей и одного дворфа." }, { 9.56, "Судя по отметинам на костях жертв, удары были сильные и яростные, но дикие звери тут ни при чём: из лагеря вынесли припасы." }, { 19.34, "Оружие кентавров тоже не могло нанести такие раны." }, { 23.51, "Возможно, собиратель, давно исследующий эти земли, сообразит, что тут произошло." } } }, t = { d = 4.0, v = "goblin-male", n = { x = 24 }, c = { x = { { 0.00, "А..." }, { 0.54, "Значит, ещё один разграбили..." } } } } },
    [79235] = { d = 38.5, g = 1, v = "goblin-male", n = { m = 445, f = 446 }, c = { m = { { 0.00, "Я нашёл места, где произошло нечто похожее на то, что ты описал." }, { 4.46, "Это всегда лагеря людей и дворфов." }, { 7.01, "Среди караванщиков ходят слухи, что тут замешаны мародёры Орды." }, { 11.47, "Звучит правдоподобно, учитывая, кто был жертвами, и то, насколько жестокими были нападения." }, { 17.85, "Говорят, разбойники бежали из Пустошей после того, как на их след напал маршал Альянса." }, { 24.03, "Если хочешь изловить одного из них, советую поискать в Пиратской бухте." }, { 29.13, "В портовых городах всегда полно всяких тёмных личностей." }, { 33.14, "Возможно, кто-то из тех, кого ты ищешь, попытается найти корабль для бегства." } }, f = { { 0.00, "Я нашёл места, где произошло нечто похожее на то, что ты описала." }, { 4.49, "Это всегда лагеря людей и дворфов." }, { 7.02, "Среди караванщиков ходят слухи, что тут замешаны мародёры Орды." }, { 11.45, "Звучит правдоподобно, учитывая, кто был жертвами, и то, насколько жестокими были нападения." }, { 17.77, "Говорят, разбойники бежали из Пустошей после того, как на их след напал маршал Альянса." }, { 23.90, "Если хочешь изловить одного из них, советую поискать в Пиратской бухте." }, { 28.96, "В портовых городах всегда полно всяких тёмных личностей." }, { 32.95, "Возможно, кто-то из тех, кого ты ищешь, попытается найти корабль для бегства." } } }, t = { d = 3.2, v = "orc-female", n = { x = 31 }, c = { x = { { 0.00, "Тебе что-то надо?" }, { 1.50, "Говори, только быстро." } } } } },
    [79236] = { d = 20.0, v = "orc-female", n = { x = 189 }, c = { x = { { 0.00, "Ты работаешь на маршала?" }, { 2.04, "Нет, непохоже." }, { 3.25, "Слухи, которые до тебя дошли, правдивы лишь наполовину." }, { 7.93, "Да, мы разоряли лагеря людей и дворфов, но делали это не ради Орды." }, { 13.66, "У нас был частный клиент." }, { 15.78, "Я всё тебе расскажу, если купишь мне немного грога." } } }, t = { d = 4.7, v = "orc-female", n = { x = 32 }, c = { x = { { 0.00, "Да!" }, { 0.41, "То, что надо!" }, { 1.94, "Так, на чём я остановилась?" } } } } },
    [79242] = { d = 37.0, v = "orc-female", n = { x = 400 }, c = { x = { { 0.00, "Ну так вот..." }, { 0.94, "Наш босс был не из Орды." }, { 2.68, "Это была ночная эльфийка по имени Иллари Сумеречное Перо." }, { 7.10, "Она давала нам наводки на лагеря и даже разрешала оставлять себе большую часть добычи." }, { 13.60, "Забирала только настоящие редкости." }, { 16.28, "Когда на наш след напал маршал, она бросила нас на произвол судьбы." }, { 21.30, "Не знаю, зачем ей всё это было нужно, но сдаётся мне, что нас подставили." }, { 26.66, "Я не мстительная, но не буду отговаривать тебя, если захочешь её изловить." }, { 32.15, "Между прочим, она как-то упоминала об убежище на побережье Арати." } } }, t = { d = 4.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "В тайнике вы находите небольшой ящик и несколько монет." } } } } },
    [79358] = { d = 37.8, v = "dwarf-male", n = { x = 450 }, c = { x = { { 0.00, "Затопить Тысячу Игл – дело серьёзное." }, { 2.59, "Если бы я сам не ощутил бушующую ярость стихий, я бы ни за что не поверил в это." }, { 8.14, "Но что есть, то есть." }, { 9.52, "Иглогривы не первые, кто хотел безответственно использовать мощь стихий как оружие – и уж точно не последние." }, { 17.03, "Если мы собрались провести свой собственный ритуал противодействия, нам потребуется более полное понимание сущности искажённых стихий." }, { 26.30, "Возьми эту книгу." }, { 27.62, "В ней рассказывается о многих обитателях Азерота, практикующих шаманизм." }, { 32.61, "Если ты переймёшь от них что-нибудь дельное, может быть, мы и отыщем решение." } } }, t = { d = 22.4, g = 1, v = "tauren-male#68", n = { m = 243, f = 244 }, c = { m = { { 0.00, "Одно ясно... кто бы ни написал эту записку, он прав: их приготовления остались незамеченными." }, { 7.00, "Мы были слишком заняты кентаврами и гарпиями, чтобы посылать всадников на ветрокрылах патрулировать каньон и утёсы." }, { 15.58, "Спасибо, что предупредил нас об этой угрозе, но нам ещё может понадобиться твоя помощь." } }, f = { { 0.00, "Одно ясно... кто бы ни написал эту записку, он прав: их приготовления остались незамеченными." }, { 7.47, "Мы были слишком заняты кентаврами и гарпиями, чтобы посылать всадников на ветрокрылах патрулировать каньон и утёсы." }, { 16.02, "Спасибо, что предупредила нас об этой угрозе, но нам ещё может понадобиться твоя помощь." } } } } },
    [79360] = { d = 34.3, g = 1, v = "tauren-female#71", n = { m = 312, f = 313 }, c = { m = { { 0.00, "Теперь, когда ты овладел стихиями, ты в долгу перед ними, а значит, и перед всем Азеротом." }, { 7.91, "Мы взываем к ним о помощи, мы не требуем их силы." }, { 12.15, "Пришло время отплатить за оказанные тебе милости." }, { 16.53, "И, кажется, я знаю как." }, { 18.57, "Свинобразы искажают стихии в своих целях и, похоже, расширяют своё влияние в этих краях." }, { 26.33, "Отправляйся в их лабиринт и положи конец всему, что они замышляют." }, { 32.13, "Эти земли нужно защитить." } }, f = { { 0.00, "Теперь, когда ты овладела стихиями, ты в долгу перед ними, а значит, и перед всем Азеротом." }, { 7.88, "Мы взываем к ним о помощи, мы не требуем их силы." }, { 12.05, "Пришло время отплатить за оказанные тебе милости." }, { 16.38, "И, кажется, я знаю как." }, { 18.39, "Свинобразы искажают стихии в своих целях и, похоже, расширяют своё влияние в этих краях." }, { 26.04, "Отправляйся в их лабиринт и положи конец всему, что они замышляют." }, { 31.76, "Эти земли нужно защитить." } } }, npc = { [4722] = { d = 34.7, g = 1, v = "tauren-male#68", n = { m = 312, f = 313 }, c = { m = { { 0.00, "Теперь, когда ты овладел стихиями, ты в долгу перед ними, а значит, и перед всем Азеротом." }, { 7.88, "Мы взываем к ним о помощи, мы не требуем их силы." }, { 12.09, "Пришло время отплатить за оказанные тебе милости." }, { 16.46, "И, кажется, я знаю как." }, { 18.48, "Свинобразы искажают стихии в своих целях и, похоже, расширяют своё влияние в этих краях." }, { 26.21, "Отправляйся в их лабиринт и положи конец всему, что они замышляют." }, { 31.98, "Эти земли нужно защитить." } }, f = { { 0.00, "Теперь, когда ты овладела стихиями, ты в долгу перед ними, а значит, и перед всем Азеротом." }, { 8.42, "Мы взываем к ним о помощи, мы не требуем их силы." }, { 12.63, "Пришло время отплатить за оказанные тебе милости." }, { 17.00, "И, кажется, я знаю как." }, { 19.02, "Свинобразы искажают стихии в своих целях и, похоже, расширяют своё влияние в этих краях." }, { 26.75, "Отправляйся в их лабиринт и положи конец всему, что они замышляют." }, { 32.52, "Эти земли нужно защитить." } } } } }, t = { d = 22.7, v = "troll-male#77", n = { x = 185 }, c = { x = { { 0.00, "Значит, это правда, мон..." }, { 3.76, "Я тоже чую сильное смятение в мире стихий, и это, видать, одна из причин." }, { 10.34, "Чтобы затопить всю Тысячу Игл, нужна великая буря, и погибнет много народу." }, { 17.00, "Думаю, есть у меня для тебя как раз то, что надо, но легко не будет." } } }, npc = { [4722] = { d = 25.0, v = "tauren-male#68", n = { x = 185 }, c = { x = { { 0.00, "Значит, это правда, мон..." }, { 4.13, "Я тоже чую сильное смятение в мире стихий, и это, видать, одна из причин." }, { 11.36, "Чтобы затопить всю Тысячу Игл, нужна великая буря, и погибнет много народу." }, { 18.67, "Думаю, есть у меня для тебя как раз то, что надо, но легко не будет." } } } } } } },
    [79361] = { d = 44.8, g = 1, v = "troll-male#77", n = { m = 468, f = 470 }, c = { m = { { 0.00, "Так значит, иглогривы намереваются затопить Тысячу Игл с помощью своих извращённых шаманских практик?" }, { 7.97, "Звучит как нечто невообразимое, но ты сам уже видел, что недооценивать их не стоит." }, { 14.51, "Сейчас я с радостью продолжил бы твоё обучение, но на это у нас, к сожалению, нет времени." }, { 21.54, "В этих землях обитает множество самых разных существ, как дружественных нам, так и враждебных, но никто из них не заслуживает подобной участи." }, { 32.74, "Возьми этот фолиант." }, { 34.47, "Изначально он предназначался для исследования, но, возможно, как раз в нём и отыщется ключ к тому, как рассеять эту надвигающуюся бурю." } }, f = { { 0.00, "Так значит, иглогривы намереваются затопить Тысячу Игл с помощью своих извращённых шаманских практик?" }, { 7.92, "Звучит как нечто невообразимое, но ты сама уже видела, что недооценивать их не стоит." }, { 14.62, "Сейчас я с радостью продолжил бы твоё обучение, но на это у нас, к сожалению, нет времени." }, { 21.62, "В этих землях обитает множество самых разных существ, как дружественных нам, так и враждебных, но никто из них не заслуживает подобной участи." }, { 32.74, "Возьми этот фолиант." }, { 34.46, "Изначально он предназначался для исследования, но, возможно, как раз в нём и отыщется ключ к тому, как рассеять эту надвигающуюся бурю." } } }, t = { d = 4.9, v = "troll-male#77", n = { x = 26 }, c = { x = { { 0.00, "О да, да." }, { 1.31, "Вот теперь дело закипело." } } } } },
    [79362] = { d = 25.0, v = "narrator", n = { x = 259 }, c = { x = { { 0.00, "Это щит, оставленный духом Бранта Вэлора, главы рода Вэлор и героя Вороньего Холма." }, { 6.70, "Дух Бранта всё ещё сражался с нежитью: возможно, его незавершённым делом на этой земле было покончить с воином Плети, который ранил его на кладбище Вороньего Холма." }, { 19.62, "Скорее всего, палица павшего героя так и застряла в теле того чудища." } } }, t = { d = 20.4, v = "human-male", n = { x = 247 }, c = { x = { { 0.00, "То, что такого гордого человека, как Грант Вэлор, сломило столь простое существо, говорит не столько о нём самом, сколько об ужасах битвы." }, { 9.35, "Достаточно одного неверного шага, чтобы остаться калекой на всю жизнь." }, { 14.15, "Это оружие многое рассказывает о своём владельце." }, { 17.53, "Дай мне немного времени, чтобы изучить его." } } }, npc = { [6176] = { d = 23.7, v = "troll-male#77", n = { x = 247 }, c = { x = { { 0.00, "То, что такого гордого человека, как Грант Вэлор, сломило столь простое существо, говорит не столько о нём самом, сколько об ужасах битвы." }, { 10.85, "Достаточно одного неверного шага, чтобы остаться калекой на всю жизнь." }, { 16.41, "Это оружие многое рассказывает о своём владельце." }, { 20.34, "Дай мне немного времени, чтобы изучить его." } } } } } } },
    [79363] = { d = 25.9, v = "narrator", n = { x = 271 }, c = { x = { { 0.00, "Это меч, оставленный духом стражницы Вороньего Холма, Сильвии Вэлор, которая провела всю жизнь, защищая горожан и их дома." }, { 9.80, "Дух Сильвии всё ещё скитался от фермы к ферме: возможно, её незавершённым делом на этой земле было изгнать разбойников из Братства Справедливости, которые захватили участок Эддла на юге от Вороньего Холма." } } }, t = { d = 21.9, v = "human-male", n = { x = 249 }, c = { x = { { 0.00, "Сильвия Вэлор?" }, { 1.09, "А, да..." }, { 1.67, "Славная воительница, защищавшая наш образ жизни – правда, у неё было довольно своеобразное понимание того, каким этот образ должен быть." }, { 11.42, "Я не лучше тебя представляю, чего бы она хотела, но борьба с Братством Справедливости – неплохая догадка." }, { 18.92, "Позволь мне хорошенько изучить этот клинок." } } }, npc = { [6176] = { d = 3.6, v = "troll-male#77", n = { x = 36 }, c = { x = { { 0.00, "Стряхни с себя эту слизь, мы почти закончили." } } } } } } },
    [79364] = { d = 47.3, g = 1, v = "tauren-male#68", n = { m = 491, f = 491 }, c = { m = { { 0.00, "Из найденной тобою записки следует, что Иглогривые дорылись до Тысячи Игл, чтобы провести некий неведомый ритуал." }, { 9.00, "Яростные бури, мощные приливы..." }, { 11.65, "Иглогривы, верно, используют некую тёмную волшбу, которой обучились у Хирзека – шамана, не останавливавшегося ни перед чем в своём стремлении исказить природу стихий." }, { 24.65, "Если они намереваются затопить каньон, для этого потребуются невероятно разрушительные стихийные силы." }, { 32.80, "Мы тут мало что можем сделать, но у сильного шамана вроде тебя вполне может возникнуть здравая идея." }, { 40.88, "Возвращайся к своим союзникам, и посмотрим, получится ли у тебя найти ответ." } }, f = { { 0.00, "Из найденной тобою записки следует, что Иглогривые дорылись до Тысячи Игл, чтобы провести некий неведомый ритуал." }, { 9.10, "Яростные бури, мощные приливы..." }, { 11.77, "Иглогривы, верно, используют некую тёмную волшбу, которой обучились у Хирзека – шамана, не останавливавшегося ни перед чем в своём стремлении исказить природу стихий." }, { 24.91, "Если они намереваются затопить каньон, для этого потребуются невероятно разрушительные стихийные силы." }, { 33.14, "Мы тут мало что можем сделать, но у сильной шаманки вроде тебя вполне может возникнуть здравая идея." }, { 41.30, "Возвращайся к своим союзникам, и посмотрим, получится ли у тебя найти ответ." } } }, npc = { [6176] = { d = 45.3, g = 1, v = "troll-male#77", n = { m = 491, f = 491 }, c = { m = { { 0.00, "Из найденной тобою записки следует, что Иглогривые дорылись до Тысячи Игл, чтобы провести некий неведомый ритуал." }, { 8.37, "Яростные бури, мощные приливы..." }, { 10.83, "Иглогривы, верно, используют некую тёмную волшбу, которой обучились у Хирзека – шамана, не останавливавшегося ни перед чем в своём стремлении исказить природу стихий." }, { 22.93, "Если они намереваются затопить каньон, для этого потребуются невероятно разрушительные стихийные силы." }, { 30.51, "Мы тут мало что можем сделать, но у сильного шамана вроде тебя вполне может возникнуть здравая идея." }, { 38.02, "Возвращайся к своим союзникам, и посмотрим, получится ли у тебя найти ответ." } }, f = { { 0.00, "Из найденной тобою записки следует, что Иглогривые дорылись до Тысячи Игл, чтобы провести некий неведомый ритуал." }, { 8.37, "Яростные бури, мощные приливы..." }, { 10.83, "Иглогривы, верно, используют некую тёмную волшбу, которой обучились у Хирзека – шамана, не останавливавшегося ни перед чем в своём стремлении исказить природу стихий." }, { 22.93, "Если они намереваются затопить каньон, для этого потребуются невероятно разрушительные стихийные силы." }, { 30.51, "Мы тут мало что можем сделать, но у сильной шаманки вроде тебя вполне может возникнуть здравая идея." }, { 39.81, "Возвращайся к своим союзникам, и посмотрим, получится ли у тебя найти ответ." } } } } }, t = { d = 3.4, v = "tauren-female#71", n = { x = 30 }, c = { x = { { 0.00, "Я знала, что на тебя можно положиться." } } }, npc = { [6176] = { d = 3.5, v = "troll-male#77", n = { x = 30 }, c = { x = { { 0.00, "Я знала, что на тебя можно положиться." } } } } } } },
    [79365] = { d = 16.4, v = "troll-male#77", n = { x = 153 }, c = { x = { { 0.00, "Вот тебе, дружище, зелье сокрушителя ветров." }, { 3.81, "Выпей его, чтобы защититься от бури, но помни, что оно действует недолго." }, { 10.15, "А теперь возвращайся к своим друзьям в беде." }, { 13.96, "Я сделал для тебя всё, что мог." } } }, t = { d = 12.3, v = "tauren-male#68", n = { x = 131 }, c = { x = { { 0.00, "Наши всадники на ветрокрылах кое-что нашли, но не смогли подобраться достаточно близко, чтобы разобраться." }, { 8.31, "Тебе удалось найти что-нибудь, что может нам помочь?" } } } } },
    [79366] = { d = 42.0, g = 1, v = "tauren-male#68", n = { m = 426, f = 426 }, c = { m = { { 0.00, "Теперь, когда у тебя есть изуродованные тотемы, мы воспользуемся ими, чтобы призвать заражённых порчей элементалей, к которым взывают иглогривы." }, { 11.52, "Победи их, чтобы очистить эти земли от скверны и положить конец противоестественному ритуалу иглогривых, а затем возвращайся к Рау Скальному Бегуну доложить о своём успехе." }, { 25.36, "Начни очищение с дымящихся озёр на западе – там отчётливо ощущается присутствие каждой из стихий." }, { 33.04, "Но будь осторожен." }, { 34.49, "Иглогривы не станут сидеть сложа руки, когда ты попытаешься сорвать их планы." } }, f = { { 0.00, "Теперь, когда у тебя есть изуродованные тотемы, мы воспользуемся ими, чтобы призвать заражённых порчей элементалей, к которым взывают иглогривы." }, { 11.91, "Победи их, чтобы очистить эти земли от скверны и положить конец противоестественному ритуалу иглогривых, а затем возвращайся к Рау Скальному Бегуну доложить о своём успехе." }, { 26.21, "Начни очищение с дымящихся озёр на западе – там отчётливо ощущается присутствие каждой из стихий." }, { 34.14, "Но будь осторожна." }, { 35.64, "Иглогривы не станут сидеть сложа руки, когда ты попытаешься сорвать их планы." } } }, npc = { [5905] = { d = 40.2, g = 1, v = "tauren-female#71", n = { m = 426, f = 426 }, c = { m = { { 0.00, "Теперь, когда у тебя есть изуродованные тотемы, мы воспользуемся ими, чтобы призвать заражённых порчей элементалей, к которым взывают иглогривы." }, { 11.27, "Победи их, чтобы очистить эти земли от скверны и положить конец противоестественному ритуалу иглогривых, а затем возвращайся к Рау Скальному Бегуну доложить о своём успехе." }, { 24.81, "Начни очищение с дымящихся озёр на западе – там отчётливо ощущается присутствие каждой из стихий." }, { 32.33, "Но будь осторожен." }, { 33.74, "Иглогривы не станут сидеть сложа руки, когда ты попытаешься сорвать их планы." } }, f = { { 0.00, "Теперь, когда у тебя есть изуродованные тотемы, мы воспользуемся ими, чтобы призвать заражённых порчей элементалей, к которым взывают иглогривы." }, { 11.27, "Победи их, чтобы очистить эти земли от скверны и положить конец противоестественному ритуалу иглогривых, а затем возвращайся к Рау Скальному Бегуну доложить о своём успехе." }, { 24.81, "Начни очищение с дымящихся озёр на западе – там отчётливо ощущается присутствие каждой из стихий." }, { 32.33, "Но будь осторожна." }, { 34.17, "Иглогривы не станут сидеть сложа руки, когда ты попытаешься сорвать их планы." } } } } }, t = { d = 13.0, g = 1, v = "tauren-male#68", n = { m = 119, f = 121 }, c = { m = { { 0.00, "Грохочущая земля затихла, и сердцем я понял, что ты спас нас." }, { 5.33, "Мы благодарны тебе." }, { 7.08, "Прими, пожалуйста, один из этих даров в знак нашей признательности." } }, f = { { 0.00, "Грохочущая земля затихла, и сердцем я понял, что ты спасла нас." }, { 5.47, "Мы благодарны тебе." }, { 7.18, "Прими, пожалуйста, один из этих даров в знак нашей признательности." } } } } },
    [79442] = { d = 20.8, v = "tauren-male#68", n = { x = 184 }, c = { x = { { 0.00, "Мой народ в огромном долгу перед тобой, но мне от этого ока никакого проку нет." }, { 7.29, "Я слыхал, что в Альтеракских горах есть один старый шаман, который знает толк в магии стихии бурь." }, { 16.21, "Может, он сумеет изготовить для тебя нечто дельное." } } }, t = { d = 17.5, v = "troll-male#77", n = { x = 146 }, c = { x = { { 0.00, "Вот что я скажу." }, { 1.49, "Хватит фокусов, хватит игр." }, { 4.07, "Есть у меня кое-что, что тебя заинтересует." }, { 8.05, "Отдай мне этот глаз, и я дам тебе вот эту славную руну – она научит тебя новым трюкам." }, { 16.19, "Ну, что скажешь?" } } } } },
    [79482] = { d = 29.2, g = 1, v = "goblin-male", n = { m = 331, f = 335 }, c = { m = { { 0.00, "Слушай... не хочется портить праздничное настроение, но \"Пастбищам Дымного Леса\" нужна помощь от искателя приключений вроде тебя." }, { 9.05, "Мы потеряли важную партию праздничных угощений, а теперь пропал ещё и агент, которого мы отправили на поиски!" }, { 16.66, "Помоги, будь любезен!" }, { 18.17, "Говорят, краденое в последний раз видели в Альтеракских горах, туда наш посланец и отправился." }, { 24.70, "Верни его и наши припасы в целости и сохранности!" } }, f = { { 0.00, "Слушай... не хочется портить праздничное настроение, но \"Пастбищам Дымного Леса\" нужна помощь от искательницы приключений вроде тебя." }, { 9.60, "Мы потеряли важную партию праздничных угощений, а теперь пропал ещё и агент, которого мы отправили на поиски!" }, { 17.21, "Помоги, будь любезна!" }, { 19.33, "Говорят, краденое в последний раз видели в Альтеракских горах, туда наш посланец и отправился." }, { 25.86, "Верни его и наши припасы в целости и сохранности!" } } } },
    [79492] = { d = 35.2, v = "goblin-male", n = { x = 386 }, c = { x = { { 0.00, "БЕДА!" }, { 0.45, "Похищен Метцен – северный олень!" }, { 2.86, "Метцен – один из восьми оленей Дедушки Зимы и принадлежит \"Пастбищам Дымного Леса\"." }, { 8.97, "Мы получили не одно, а ДВА письма с требованием выкупа от двух шаек, каждая из которых утверждает, что олень у них." }, { 17.15, "Праздники в разгаре, мы не можем бросить дела!" }, { 20.53, "Пожалуйста, найди Метцена и верни его нам!" }, { 23.65, "Возьми эти письма с требованием выкупа, – может, найдёшь в них подсказку, – а вот этой пылью посыпь северного оленя, и он освободится от любых пут!" }, { 34.18, "Прошу, поспеши!" } } } },
    [79495] = { d = 35.0, v = "goblin-male", n = { x = 386 }, c = { x = { { 0.00, "БЕДА!" }, { 0.45, "Похищен Метцен – северный олень!" }, { 2.84, "Метцен – один из восьми оленей Дедушки Зимы и принадлежит \"Пастбищам Дымного Леса\"." }, { 8.91, "Мы получили не одно, а ДВА письма с требованием выкупа от двух шаек, каждая из которых утверждает, что олень у них." }, { 17.04, "Праздники в разгаре, мы не можем бросить дела!" }, { 20.39, "Пожалуйста, найди Метцена и верни его нам!" }, { 23.49, "Возьми эти письма с требованием выкупа, – может, найдёшь в них подсказку, – а вот этой пылью посыпь северного оленя, и он освободится от любых пут!" }, { 33.94, "Прошу, поспеши!" } } } },
    [79535] = { t = { d = 13.3, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.82, "Твоими стараниями наши знания растут." }, { 4.34, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } }, npc = { [211033] = { d = 10.7, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.66, "Твоими стараниями наши знания растут." }, { 3.51, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } } } },
    [79536] = { t = { d = 6.7, v = "scourge-male", n = { x = 67 }, c = { x = { { 0.00, "Благодаря твоим пожертвованиям библиотека процветает." }, { 4.72, "Пожалуйста, возьми это." } } }, npc = { [211033] = { d = 5.8, v = "human-male", n = { x = 67 }, c = { x = { { 0.00, "Благодаря твоим пожертвованиям библиотека процветает." }, { 4.05, "Пожалуйста, возьми это." } } } } } } },
    [79624] = { d = 19.8, v = "narrator", n = { x = 201 }, c = { x = { { 0.00, "Похоже, это рецепт какого-то мясного блюда, однако написан он на каком-то непонятном языке." }, { 7.28, "Кажется, на огрском, – учитывая, где вы его нашли." }, { 11.23, "Огры не любят готовить, но если вы вдруг встретите кого-нибудь из них, кто любит, он сможет перевести вам рецепт." } } }, t = { d = 3.0, v = "creature/ogre", n = { x = 27 }, c = { x = { { 0.00, "У тебя есть рецепт?" }, { 1.86, "Грызь слушает." } } } } },
    [79637] = { t = { d = 6.3, v = "narrator", n = { x = 63 }, c = { x = { { 0.00, "Весёлого праздника Зимнего Покрова от твоих друзей с Пастбищ Дымного Леса." } } } } },
    [79731] = { d = 12.6, v = "narrator", n = { x = 81 }, c = { x = { { 0.00, "Древние знаки прямо у тебя на глазах складываются в слова." }, { 4.94, "Когда фонтан Зул'Кунды наполнится водами священного источника, боги даруют своё благословение." } } }, t = { d = 11.6, v = "dwarf-male", n = { x = 116 }, c = { x = { { 0.00, "Волшебный фонтан, спрятанный в джунглях?" }, { 3.24, "Вот это история!" }, { 4.61, "Это подсказывает мне идею для новой главы моей книги!" }, { 9.01, "Так, куда же я положил рукопись..." } } } } },
    [79947] = { t = { d = 13.2, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.81, "Твоими стараниями наши знания растут." }, { 4.32, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } }, npc = { [211033] = { d = 10.7, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.66, "Твоими стараниями наши знания растут." }, { 3.51, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } } } },
    [79948] = { t = { d = 13.6, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.84, "Твоими стараниями наши знания растут." }, { 4.45, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } }, npc = { [211033] = { d = 10.6, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.65, "Твоими стараниями наши знания растут." }, { 3.46, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } } } },
    [79949] = { t = { d = 13.1, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.81, "Твоими стараниями наши знания растут." }, { 4.29, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } }, npc = { [211033] = { d = 10.6, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.66, "Твоими стараниями наши знания растут." }, { 3.49, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } } } },
    [79950] = { t = { d = 12.7, v = "scourge-male", n = { x = 116 }, c = { x = { { 0.00, "Спасибо." }, { 0.83, "Благодаря тебе мы узнаём всё больше и больше." }, { 4.95, "Если найдёшь другие чародейские труды, которых не хватает в библиотеке, приноси их мне." } } }, npc = { [211033] = { d = 10.2, v = "human-male", n = { x = 116 }, c = { x = { { 0.00, "Спасибо." }, { 0.67, "Благодаря тебе мы узнаём всё больше и больше." }, { 3.99, "Если найдёшь другие чародейские труды, которых не хватает в библиотеке, приноси их мне." } } } } } } },
    [79951] = { t = { d = 13.7, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.84, "Твоими стараниями наши знания растут." }, { 4.47, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } }, npc = { [211033] = { d = 10.6, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.65, "Твоими стараниями наши знания растут." }, { 3.46, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } } } },
    [79952] = { t = { d = 13.1, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.81, "Твоими стараниями наши знания растут." }, { 4.29, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } }, npc = { [211033] = { d = 10.7, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.66, "Твоими стараниями наши знания растут." }, { 3.51, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } } } },
    [79974] = { d = 17.0, v = "narrator", n = { x = 167 }, c = { x = { { 0.00, "\"Всегда стараюсь держать поблизости ещё один тайник на случай, если придётся внезапно бежать." }, { 7.71, "Склоны этой горы так красивы, словно их вырезали из водопадов времени." }, { 13.56, "Ищи гнездо орла." }, { 15.04, "Именно оно тебе нужно\"." } } }, t = { d = 4.6, v = "narrator", n = { x = 43 }, c = { x = { { 0.00, "Инженерное мастерство дворфов: как всегда чудесно." } } } } },
    [79975] = { d = 28.8, v = "narrator", n = { x = 230 }, c = { x = { { 0.00, "В ящике с инструментами вы находите аккуратно сложенное письмо." }, { 5.24, "\"Отныне у тебя есть нужные инструменты, и всё зависит только от тебя." }, { 11.00, "Отличное место для запуска параплана." }, { 14.14, "Моя верность орлу и кулаку предписывает служить им издали." }, { 19.08, "Эта баррикада видала лучшие дни – как и древние королевства, которые она когда-то защищала." }, { 26.71, "Но я никогда её не покину\"." } } }, t = { d = 6.4, v = "narrator", n = { x = 63 }, c = { x = { { 0.00, "В костёр недавно положили хворост, но затем это место явно в спешке покинули." } } } } },
    [79976] = { d = 26.2, v = "narrator", n = { x = 82 }, c = { x = { { 0.00, "\"Придётся взять мои наработки и снова залечь на дно." }, { 4.13, "Чтобы ничего не попало в руки тем, кому не следует\"." }, { 8.41, "Послание едва умещается на клочке бумаги." }, { 11.82, "Кто знает, последняя ли это записка этого автора, которую вы прочтёте, – или подсказка, ведущая к следующему укрытию." }, { 21.24, "У ваших ног разворачивается плохо упакованный спальный мешок..." } } }, t = { d = 5.9, v = "narrator", n = { x = 64 }, c = { x = { { 0.00, "Разнообразное снаряжение обмотано тяжёлым холстом." }, { 4.23, "Вы подбираете свёрток." } } } } },
    [79980] = { d = 15.8, v = "narrator", n = { x = 157 }, c = { x = { { 0.00, "\"Неплохо, да?" }, { 1.09, "Раз ты это читаешь, мой тайник ещё не нашли." }, { 4.65, "Сделай сто шагов на север и не переломай ноги, спускаясь по крутому склону." }, { 10.75, "Содержимое тайника позволит тебе протянуть ещё какое-то время\"." } } }, t = { d = 7.1, v = "narrator", n = { x = 80 }, c = { x = { { 0.00, "Вы вытаскиваете из земли сумку посланника." }, { 3.25, "Рядом с припасами в ней лежит испачканный пергамент." } } } } },
    [80001] = { t = { d = 3.6, v = "narrator", n = { x = 39 }, c = { x = { { 0.00, "Вы пускаете в ход свои навыки путешественника." } } } } },
    [81570] = { d = 24.4, v = "human-male", n = { x = 257 }, c = { x = { { 0.00, "Мне предстоит рубка." }, { 1.51, "Не скажу, что именно я собираюсь рубить, но... мне нужен клинок." }, { 6.19, "Особый клинок..." }, { 7.44, "Кто-то называет его палашом лунной стали." }, { 10.59, "А я зову его пляшущим клинком." }, { 12.90, "Поможешь, а?" }, { 13.82, "Может, найдёшь его в городе, а может, уговоришь кузнеца выковать его на заказ." }, { 19.61, "Только не тяни." }, { 20.79, "То, что я собираюсь рубить, вечно ждать не станет..." } } }, t = { d = 16.3, v = "human-male", n = { x = 145 }, c = { x = { { 0.00, "Это хороший клинок." }, { 1.78, "Он хорошо пляшет." }, { 3.33, "Это хороший пляшущий клинок." }, { 5.88, "Спасибо." }, { 6.65, "Спасибо, спасибо, спасибо!!!" }, { 9.13, "Теперь хочу его испробовать..." }, { 11.84, "Потом." }, { 12.45, "Испробую потом." }, { 13.85, "Но, как я и говорил... спасибо." } } } } },
    [81947] = { t = { d = 13.0, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.80, "Твоими стараниями наши знания растут." }, { 4.27, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } }, npc = { [211033] = { d = 10.6, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Спасибо." }, { 0.66, "Твоими стараниями наши знания растут." }, { 3.49, "Если найдёшь ещё какие-нибудь магические труды, которые могут пригодиться библиотеке, принеси их мне." } } } } } } },
