    [84401] = { t = { d = 9.8, v = "human-female#47", n = { x = 120 }, c = { x = { { 0.00, "Спасибо." }, { 0.62, "Благодаря твоим стараниям наши знания растут." }, { 3.86, "Если найдёшь ещё магические труды, которые могут пригодиться библиотеке, приноси их мне." } } }, npc = { [7825] = { d = 11.6, v = "scourge-female#79", n = { x = 120 }, c = { x = { { 0.00, "Спасибо." }, { 0.74, "Благодаря твоим стараниям наши знания растут." }, { 4.58, "Если найдёшь ещё магические труды, которые могут пригодиться библиотеке, приноси их мне." } } } } } } },
    [84402] = { t = { d = 10.2, v = "human-female#47", n = { x = 125 }, c = { x = { { 0.00, "Спасибо." }, { 0.63, "Благодаря твоим стараниям наши знания растут." }, { 3.90, "Если найдёшь ещё какие-нибудь магические труды, которые пригодятся библиотеке, приноси их мне." } } }, npc = { [7825] = { d = 12.1, v = "scourge-female#79", n = { x = 125 }, c = { x = { { 0.00, "Спасибо." }, { 0.74, "Благодаря твоим стараниям наши знания растут." }, { 4.60, "Если найдёшь ещё какие-нибудь магические труды, которые пригодятся библиотеке, приноси их мне." } } } } } } },
    [86574] = { d = 27.5, v = "nightelf-female", n = { x = 0 }, c = { x = { { 0.00, "*На теле несчастной видны следы многочисленных ударов величавых виверн.*" }, { 5.46, "*Рядом лежит помятый пустой мешок, а курьер сжимает в руке лишь маленькую записку, благодаря которой можно понять, что было потеряно: груз, предназначавшийся для хозяйки таверны Фаралии на пике Каменного Когтя.*" }, { 21.58, "*Виверны, должно быть, унесли связки припасов, чтобы выстелить ими свои гнёзда.*" } } }, t = { d = 13.4, g = 1, v = "nightelf-female", n = { m = 147, f = 147 }, c = { m = { { 0.00, "Ты нашёл пропавшую партию?" }, { 1.89, "О, я понятия не имела, что курьер не добрался." }, { 5.21, "Это... печальное известие..." }, { 7.29, "Я найду этим припасам достойное применение, чтобы её потеря не оказалась напрасной." } }, f = { { 0.00, "Ты нашла пропавшую партию?" }, { 1.98, "О, я понятия не имела, что курьер не добрался." }, { 5.34, "Это... печальное известие..." }, { 7.45, "Я найду этим припасам достойное применение, чтобы её потеря не оказалась напрасной." } } } } },
    [86576] = { d = 39.0, v = "tauren-male", n = { x = 394 }, c = { x = { { 0.00, "Гарпии Кровавой Ярости не только засоряют Обугленную долину, но и тянут все блестящие предметы, какие только подвернутся." }, { 9.96, "Говорят, они собирают самые разные золотисто-жёлтые солнечные камни для украшения гнёзд." }, { 17.20, "Мне такие безделушки не нужны, но Мор'рогал в прошлом упоминал о том, что их можно как-то использовать." }, { 25.53, "Сражаясь с гарпиями в долине, поглядывай по сторонам и собирай сверкающие солнечные камни." }, { 32.91, "Принеси всё, что тебе попадётся, Мор'рогалу – его ты найдёшь выше, на холмах." } } }, t = { d = 37.8, g = 1, v = "tauren-male#67", n = { m = 330, f = 332 }, c = { m = { { 0.00, "А, ты принёс солнечные камни, которые собирают гарпии!" }, { 5.08, "Гарпии любят собирать блестящие вещицы, но не знают истинной ценности этих камней." }, { 12.95, "Улавливая ослепительный свет солнца, эти камни отражают его величие, и мы украшаем ими свои святилища и дома – крошечными искорками света в его честь." }, { 27.17, "А ночью луна озаряет их своей серебристой красотой." }, { 32.08, "Эти камни напоминают нам о нашей связи с небесными светилами." } }, f = { { 0.00, "А, ты принесла солнечные камни, которые собирают гарпии!" }, { 5.21, "Гарпии любят собирать блестящие вещицы, но не знают истинной ценности этих камней." }, { 12.90, "Улавливая ослепительный свет солнца, эти камни отражают его величие, и мы украшаем ими свои святилища и дома – крошечными искорками света в его честь." }, { 26.78, "А ночью луна озаряет их своей серебристой красотой." }, { 31.58, "Эти камни напоминают нам о нашей связи с небесными светилами." } } } } },
    [86577] = { d = 34.6, v = "nightelf-male", n = { x = 344 }, c = { x = { { 0.00, "Скверна, что изливается с Хиджала, течёт по горным водам и просачивается во всё в этом лесу." }, { 7.56, "Звери, которые пьют эту воду, впитывают порчу." }, { 11.52, "Она делает их свирепыми, больными и бесстрашными." }, { 15.64, "Чтобы противостоять этому, мне нужно понять, как это действует, а для этого нужны образцы от поражённых." }, { 24.24, "Нескольких образцов прогнивших органов волков и медведей будет достаточно." }, { 30.45, "Не торопись: в Осквернённом лесу этих зверей полно." } } } },
    [86585] = { d = 35.5, v = "narrator", n = { x = 356 }, c = { x = { { 0.00, "Погибший горный пехотинец сжимает в руках знамя Стальгорна." }, { 4.95, "Быть может, она проводила разведку или шла в безнадёжную атаку." }, { 10.12, "В любом случае знамя втоптали в грязь." }, { 13.29, "Женщину-пехотинца так сильно ударили по голове, что с неё слетел шлем." }, { 18.98, "Она погибла сразу же – вероятно, от удара шипастой дубины трогга." }, { 24.45, "Убивший её трогг, наверное, всё ещё где-то поблизости и наверняка помнит это знамя." }, { 31.24, "Возможно, вновь поднятое знамя привлечёт его внимание." } } }, t = { d = 31.2, g = 1, v = "dwarf-male", n = { m = 368, f = 368 }, c = { m = { { 0.00, "Ты нашёл тело Ильвы?" }, { 1.44, "Ах, бедняжка." }, { 2.38, "Она говорила, что собирается показать троггам, что Стальгорн никогда не падёт под их натиском." }, { 8.83, "И отправилась на поиски пехотинцев, которые не вернулись из патруля в землях троггов." }, { 14.71, "Она всегда была такой целеустремлённой, что забывала об осторожности." }, { 19.47, "Теперь ясно, что произошло." }, { 21.41, "Я заберу знамя и прослежу, чтобы его отчистили и установили в достойном месте." }, { 26.92, "Возьми её оружие." }, { 28.18, "Пусть оно послужит тебе в боях с троггами." } }, f = { { 0.00, "Ты нашла тело Ильвы?" }, { 1.51, "Ах, бедняжка." }, { 2.45, "Она говорила, что собирается показать троггам, что Стальгорн никогда не падёт под их натиском." }, { 8.92, "И отправилась на поиски пехотинцев, которые не вернулись из патруля в землях троггов." }, { 14.82, "Она всегда была такой целеустремлённой, что забывала об осторожности." }, { 19.60, "Теперь ясно, что произошло." }, { 21.54, "Я заберу знамя и прослежу, чтобы его отчистили и установили в достойном месте." }, { 27.07, "Возьми её оружие." }, { 28.33, "Пусть оно послужит тебе в боях с троггами." } } } } },
    [86611] = { d = 20.2, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Лужа зловонной слизи разъела статую оленя." }, { 3.43, "Непонятно, как она оказалась здесь, на дне озера." }, { 7.21, "На шее у неё висит медальон с единственным кристаллом, от которого исходит нездоровое зелёное мерцание." }, { 15.13, "Стоит показать его тому, кто может знать историю этого памятника." } } } },
    [86612] = { d = 20.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Лужа зловонной слизи разъела статую оленя." }, { 3.54, "Непонятно, как она оказалась здесь, на дне озера." }, { 7.44, "На шее у неё висит медальон с единственным кристаллом, от которого исходит нездоровое зелёное мерцание." }, { 15.61, "Стоит показать его тому, кто может знать историю этого памятника." } } } },
    [86613] = { d = 11.4, v = "narrator", n = { x = 137 }, c = { x = { { 0.00, "Инструменты для раскопок, оставленные сбежавшими от троггов дворфами, выглядят почти нетронутыми." }, { 6.96, "Если вернуть их владельцам, тем наверняка будет проще работать." } } }, t = { d = 12.7, v = "dwarf-male", n = { x = 154 }, c = { x = { { 0.00, "Наши инструменты!" }, { 1.25, "Когда в лагерь прорвались трогги, нам пришлось оставить большую часть снаряжения." }, { 6.90, "Эти вещи нам очень пригодятся, когда мы отобьём нападение и снова приступим к работе!" } } } } },
    [86614] = { d = 14.3, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Среди рыболовных снастей в обломках лежат ржавые крючки, повреждённые катушки проволоки и слегка окислившаяся, но богато украшенная серебряная заколка для волос с монограммой Ха Эр." } } }, t = { d = 10.8, g = 1, v = "dwarf-female", n = { m = 102, f = 103 }, c = { m = { { 0.00, "Моя заколка!" }, { 1.11, "Я думала, она пропала насовсем!" }, { 3.77, "Немного почистить – и снова заблестит." }, { 6.95, "Спасибо, что вернул её мне!" }, { 9.16, "Я тебя вознагражу." } }, f = { { 0.00, "Моя заколка!" }, { 1.11, "Я думала, она пропала насовсем!" }, { 3.77, "Немного почистить – и снова заблестит." }, { 6.92, "Спасибо, что вернула её мне!" }, { 9.40, "Я тебя вознагражу." } } } } },
    [86615] = { d = 25.1, v = "dwarf-female#33", n = { x = 260 }, c = { x = { { 0.00, "Эх!" }, { 0.28, "Я тут посол при клане Громового Молота, а сумку с последними дипломатическими депешами оставила где-то в Крепости Громового Молота." }, { 10.32, "Наверное, в таверне забыла... или возле паровых баков... а может, наверху?" }, { 16.13, "Вечно я всё теряю!" }, { 17.58, "Мне нужны эти бумаги!" }, { 19.32, "Если ты лучше меня знаешь крепость, поищи-ка мою пропавшую сумку дипломата!" } } } },
    [86616] = { d = 33.7, v = "dwarf-female#34", n = { x = 371 }, c = { x = { { 0.00, "Шаману, который общается со стихиями, приходится непросто: есть и другие шаманы, и цели у них совсем иные." }, { 7.77, "Стихиям всё равно, зачем мы делаем то, что делаем, – они просто исполняют наши просьбы!" }, { 14.21, "Тролли в Джинта'Алоре тоже владеют искусством шаманов, и их вмешательство и набеги не дают нам здесь покоя." }, { 21.98, "Найди тотемы племени Порочной Ветви и принеси их мне, чтобы я смогла лишить их силы." }, { 28.23, "Одни тролли носят их с собой, другие расставляют вокруг алтаря как обереги." } } } },
    [86620] = { d = 23.8, v = "dwarf-male", n = { x = 267 }, c = { x = { { 0.00, "Грифоны у нас тут отменные, но в дикой природе всегда найдётся пара кладок, которым грозит гибель." }, { 7.14, "Родитель-грифон может проиграть схватку с волком или захворать." }, { 11.85, "Без помощи птенцы ни за что не выживут." }, { 14.67, "К счастью, у нас есть всё, чтобы выходить и уберечь таких потерянных малышей." }, { 20.24, "Если найдёшь в глуши потерянные яйца, неси их мне." } } } },
    [86667] = { d = 35.1, g = 1, v = "dwarf-female", n = { m = 411, f = 413 }, c = { m = { { 0.00, "Норрик, мой старый наставник, прислал мелкого элементаля со странной просьбой." }, { 5.37, "Ему нужен кувшин снега для каких-то шаманских обрядов!" }, { 9.19, "Не знаю, что он будет с ним делать, но я уже давно усвоила, что в его магических талантах сомневаться не стоит." }, { 16.77, "Я пока только устраиваюсь и занята изучением местных элементалей, поэтому не могу сейчас ему помочь." }, { 23.74, "Не мог бы ты этим заняться?" }, { 25.59, "Отправляйся к Южным вратам – там снег лежит круглый год." }, { 29.42, "Набери немного в этот керамический кувшин и отнеси ему, пока снег не растаял." } }, f = { { 0.00, "Норрик, мой старый наставник, прислал мелкого элементаля со странной просьбой." }, { 5.41, "Ему нужен кувшин снега для каких-то шаманских обрядов!" }, { 9.27, "Не знаю, что он будет с ним делать, но я уже давно усвоила, что в его магических талантах сомневаться не стоит." }, { 16.92, "Я пока только устраиваюсь и занята изучением местных элементалей, поэтому не могу сейчас ему помочь." }, { 23.94, "Не могла бы ты этим заняться?" }, { 26.00, "Отправляйся к Южным вратам – там снег лежит круглый год." }, { 29.85, "Набери немного в этот керамический кувшин и отнеси ему, пока снег не растаял." } } }, t = { d = 16.5, v = "dwarf-male", n = { x = 153 }, c = { x = { { 0.00, "Этот кувшин мне?" }, { 1.44, "Да это же снег!" }, { 2.73, "Гренхилд умница!" }, { 4.18, "Она прислала снег, как я и просил!" }, { 7.06, "Но я надеялся, что она сама заглянет в гости." }, { 10.94, "Ох, тебе, наверное, полагается награда за старания." }, { 15.27, "Вот, пожалуйста." } } } } },
    [86746] = { d = 30.3, v = "narrator", n = { x = 318 }, c = { x = { { 0.00, "Моему народу приходится тяжко." }, { 2.49, "Сатиры Легаши вторглись в наше логово, осквернили многих Черночревов и отрезали нас от наших союзников Древобрюхов." }, { 11.58, "Те, кто пережил их нападения, ютятся во временных лагерях." }, { 16.12, "Хуже того, скверна сатиров расползается по земле и грозит моему и без того беззащитному племени." }, { 23.79, "Легаши прячутся среди руин к северо-востоку отсюда." }, { 27.99, "Прошу тебя, помоги их одолеть." } } } },
    [86747] = { d = 27.6, g = 1, v = "creature/furbolg", n = { m = 213, f = 214 }, c = { m = { { 0.58, "Мне ты уже, бесспорно, доказал, чего стоишь, но остальных из моего племени убедить не так просто." }, { 8.28, "Для этого тебе придётся и дальше сражаться с Легаши." }, { 15.47, "Принеси мне рога убитых сатиров Легаши." }, { 18.87, "Каждая связка, что ты принесёшь, станет знаком твоей службы Черночревам." } }, f = { { 0.43, "Мне ты уже, бесспорно, доказала, чего стоишь, но остальных из моего племени убедить не так просто." }, { 8.62, "Для этого тебе придётся и дальше сражаться с Легаши." }, { 16.04, "Принеси мне рога убитых сатиров Легаши." }, { 19.47, "Каждая связка, что ты принесёшь, станет знаком твоей службы Черночревам." } } } },
    [86757] = { d = 25.6, v = "nightelf-female", n = { x = 311 }, c = { x = { { 0.00, "Орки захватили восточную часть леса, и их разведчики и рубаки теперь прячутся среди деревьев!" }, { 6.40, "В Ясеневом лесу для нас больше не безопасно." }, { 9.42, "Нужно оттеснить орков и защитить лес." }, { 12.01, "Мы уже устранили часть рубак и разведчиков, незаметно перемещаясь вдоль границ их лагеря." }, { 18.04, "Убей орков и принеси мне их зазубренные мечи и кривые кинжалы." }, { 22.35, "Мы переплавим металл, чтобы он не пропадал даром." } } } },
    [86758] = { d = 34.7, v = "dwarf-male", n = { x = 385 }, c = { x = { { 0.00, "Я когда-нибудь рассказывал тебе, как кроколиск чуть не отгрыз мне руку?" }, { 5.01, "Мне удалось вонзить ему в пасть нож и унести ноги." }, { 8.60, "Я думал, что нож остался у меня, но никак не могу его найти." }, { 12.97, "В любом случае этот кроколиск, вероятно, всё ещё выискивает добычу где-то на берегу озера." }, { 19.45, "Эту мерзкую зверюгу надо убить – хотя бы ради безопасности других охотников." }, { 25.04, "Я его прозвал Ножезубом." }, { 26.84, "Если он тебе попадётся, передавай от меня привет!" }, { 30.37, "И под \"передавай привет\" я имею в виду \"поруби его в капусту\"." } } }, t = { d = 15.4, v = "dwarf-male", n = { x = 152 }, c = { x = { { 0.00, "Ха!" }, { 0.27, "У тебя получилось!" }, { 1.71, "Я уж и не думал, что этот старый крокодил получит по заслугам, а вот поди ж ты!" }, { 7.66, "Э-э... знаешь, я себе уже другой нож раздобыл, а этот, может, принесёт удачу тебе." }, { 14.02, "Оставь-ка его себе." } } } } },
    [86776] = { d = 23.2, v = "dwarf-male", n = { x = 268 }, c = { x = { { 0.00, "Телсамар – прекрасное место для жизни, но всех удобств Стальгорна тут нет." }, { 5.22, "У меня постоянно заканчивается бронза!" }, { 7.99, "Мне нужно больше бронзы для изготовления инструментов, котелков и чайников!" }, { 13.34, "Я вижу, что у тебя есть опыт работы в кузнице." }, { 16.69, "Как думаешь, сможешь выплавить для меня несколько бронзовых слитков?" }, { 21.59, "Я тебе хорошо заплачу!" } } }, t = { d = 10.4, v = "dwarf-male", n = { x = 114 }, c = { x = { { 0.00, "А, какое облегчение!" }, { 1.56, "Теперь я смогу поддерживать огонь в кузнице." }, { 4.96, "Надеюсь, на днях к нам в город начнёт регулярно приходить торговец с углём!" } } } } },
    [86784] = { d = 38.1, v = "scourge-male", n = { x = 397 }, c = { x = { { 0.00, "Моя соратница Элеанор Шеклтон гордится тем, что путешествует по диким местам, выживая в схватке с непогодой и чудовищами." }, { 9.43, "Она разбила лагерь довольно близко, в холмах к западу." }, { 13.80, "Я помню совет, который она мне однажды дала: \"Когда тебе кажется, что дров уже достаточно, собери в пять раз больше\"." }, { 23.02, "Если у тебя найдётся свободное время, можешь собрать дров в эту корзину и отнести в её лагерь." }, { 30.42, "Уверен, она могла бы поделиться с тобой советами, полезными для странствующего искателя приключений." } } }, t = { d = 15.1, v = "scourge-female", n = { x = 153 }, c = { x = { { 0.00, "Ещё дрова?" }, { 0.88, "Они в хозяйстве всегда пригодятся и согреют мои старые косточки холодными ночами в этих лесах." }, { 8.74, "У меня есть дровница для сбора древесины, так что корзинку можешь оставить себе." } } } } },
    [86798] = { d = 45.9, v = "creature/furbolg", n = { x = 399 }, c = { x = { { 0.56, "Сатиры ослаблены – пора переходить в контрнаступление." }, { 4.76, "Нашей целью будет принц Халанокс, командующий Оплотом Легаши." }, { 9.59, "Но нас всё ещё слишком мало, чтобы выступить против него в открытую." }, { 17.98, "С тех пор как Легаши изгнали нас, мы отрезаны от фурболгов из Крепости Древобрюхов." }, { 24.02, "Мы могли бы попросить у них подкрепления, но для этого нужен посланник." }, { 29.26, "Этим посланником станешь ты." }, { 34.47, "Отправляйся в Крепость Древобрюхов и найди фурболга по имени Горн Одноглазый." }, { 40.33, "Он даст нам воинов, которые нам нужны." } } } },
    [86799] = { d = 37.2, g = 1, v = "creature/furbolg", n = { x = 229 }, c = { m = { { 0.56, "*Фурз заходится мерзким, надсадным кашлем.*" }, { 4.72, "Выслушай меня, путник, у меня почти нет сил говорить." }, { 9.50, "Меня сразила болезнь, какой я прежде не знал." }, { 13.56, "Будто сама кровь моя горит, а сущность распадается." }, { 18.18, "Я едва могу двигаться, не то что звать на помощь." }, { 25.54, "Прошу, найди старейшину Шипохруст." }, { 28.80, "Её шатёр к северо-западу отсюда." }, { 31.82, "Она будет знать, что делать." } }, f = { { 0.56, "*Фурз заходится мерзким, надсадным кашлем.*" }, { 4.80, "Выслушай меня, путница, у меня почти нет сил говорить." }, { 9.66, "Меня сразила болезнь, какой я прежде не знал." }, { 13.72, "Будто сама кровь моя горит, а сущность распадается." }, { 18.34, "Я едва могу двигаться, не то что звать на помощь." }, { 25.70, "Прошу, найди старейшину Шипохруст." }, { 28.91, "Её шатёр к северо-западу отсюда." }, { 31.87, "Она будет знать, что делать." } } } },
    [86804] = { d = 45.9, g = 1, v = "creature/furbolg", n = { m = 382, f = 384 }, c = { m = { { 0.56, "Фурз — не первый, кого поразил этот недуг." }, { 3.87, "С тех пор как Легаши начали на нас нападать, многие Черночревы заболели чем-то похожим." }, { 10.47, "Все они в конце концов поддались скверне и превратились в безумных разрушителей." }, { 19.66, "Я уже давно ищу лекарство." }, { 21.73, "Мои исследования показывают, что его, возможно, удастся получить, преобразовав огненную воду самих Легаши, но добыть её сама я не могу." }, { 34.91, "Огненную воду — или способ её сварить — можно найти в лагерях Легаши на востоке." }, { 41.43, "Ты бы мне очень помог." } }, f = { { 0.58, "Фурз — не первый, кого поразил этот недуг." }, { 3.88, "С тех пор как Легаши начали на нас нападать, многие Черночревы заболели чем-то похожим." }, { 10.48, "Все они в конце концов поддались скверне и превратились в безумных разрушителей." }, { 19.67, "Я уже давно ищу лекарство." }, { 21.68, "Мои исследования показывают, что его, возможно, удастся получить, преобразовав огненную воду самих Легаши, но добыть её сама я не могу." }, { 34.52, "Огненную воду — или способ её сварить — можно найти в лагерях Легаши на востоке." }, { 41.12, "Ты бы мне очень помогла." } } } },
    [86925] = { d = 14.2, v = "narrator", n = { x = 138 }, c = { x = { { 0.00, "Похоже, в этом котле можно сварить огненную воду, которую ищет старейшина Шипохруст." }, { 7.27, "Если бы только знать как." }, { 9.40, "Наверняка у кого-то из сатиров в лагере Легаши есть рецепт." } } } },
    [86926] = { d = 10.9, v = "narrator", n = { x = 95 }, c = { x = { { 0.00, "В рецепте сказано:" }, { 1.69, "Собери адский росток," }, { 3.71, "Пять пучков — и выйдет прок," }, { 6.21, "К ним частицу силы демона —" }, { 8.70, "И в могилу всех до одного!" } } } },
    [87288] = { d = 34.4, g = 1, v = "nightelf-female#119", n = { m = 396, f = 397 }, c = { m = { { 0.00, "Привет, странник!" }, { 1.31, "Как тебе наша деревенька?" }, { 3.21, "Мне очень нравится в Доланааре – жизнь здесь простая, а жители дружелюбные." }, { 8.57, "Я местная торговка." }, { 10.01, "У меня можно приобрести всевозможные инструменты и прочие вещи, которые могут пригодиться в путешествиях." }, { 17.67, "Кстати, мне сейчас нужны шкуры саблезубов и я готова за них заплатить." }, { 22.77, "Эти величественные звери, безусловно, прекрасны, но местные саблезубы очень агрессивные, так что не расстраивайся, если придётся убить кого-то из них для самозащиты." } }, f = { { 0.00, "Привет, странница!" }, { 1.36, "Как тебе наша деревенька?" }, { 3.23, "Мне очень нравится в Доланааре – жизнь здесь простая, а жители дружелюбные." }, { 8.54, "Я местная торговка." }, { 9.96, "У меня можно приобрести всевозможные инструменты и прочие вещи, которые могут пригодиться в путешествиях." }, { 17.53, "Кстати, мне сейчас нужны шкуры саблезубов и я готова за них заплатить." }, { 22.58, "Эти величественные звери, безусловно, прекрасны, но местные саблезубы очень агрессивные, так что не расстраивайся, если придётся убить кого-то из них для самозащиты." } } }, t = { d = 19.4, v = "nightelf-female#119", n = { x = 204 }, c = { x = { { 0.00, "О, эти шкуры просто чудесные." }, { 2.35, "Жаль, что приходится губить таких красивых зверей, но на дорогах должно быть безопасно." }, { 8.97, "К тому же, из этих шкур получатся прекрасные одеяла и платки." }, { 13.66, "Вот, возьми это на память об этих животных." }, { 17.04, "Эта вещь очень мягкая и прочная." } } } } },
    [87295] = { d = 29.7, g = 1, v = "human-male", n = { m = 339, f = 340 }, c = { m = { { 0.00, "Возможно, по пути в Крепость Стражей Пустоты ты видел краснокаменных василисков, что бродят по пустошам за стенами." }, { 8.13, "Это крепкие твари, прекрасно приспособленные к жизни в Выжженных землях." }, { 13.32, "Одно из их главных достоинств — прочная чешуя: она отражает жар, защищает от песка и ветра и даже отводит удары оружия!" }, { 21.90, "Это идеальный материал для щитов, и если принесёшь мне связку, я хорошо заплачу." }, { 27.60, "Неси только целые чешуйки!" } }, f = { { 0.00, "Возможно, по пути в Крепость Стражей Пустоты ты видела краснокаменных василисков, что бродят по пустошам за стенами." }, { 8.40, "Это крепкие твари, прекрасно приспособленные к жизни в Выжженных землях." }, { 13.59, "Одно из их главных достоинств — прочная чешуя: она отражает жар, защищает от песка и ветра и даже отводит удары оружия!" }, { 22.17, "Это идеальный материал для щитов, и если принесёшь мне связку, я хорошо заплачу." }, { 27.87, "Неси только целые чешуйки!" } } } },
    [87318] = { d = 30.0, v = "human-female", n = { x = 321 }, c = { x = { { 0.00, "У Моста Тандола стало опасно, после того как дворфы Чёрного Железа его взорвали, но я не думала, что на них наткнусь!" }, { 8.74, "Мне удалось оторваться, но я потеряла из виду Эссин." }, { 12.06, "Повсюду её искала, но не нашла и следа." }, { 15.74, "Вдруг те дворфы её схватили?" }, { 17.69, "Или она упала в реку под руинами?" }, { 20.14, "Может, она всё же выбралась, но на другой стороне?" }, { 23.67, "Я ничего не знаю – даже жива она ещё или нет!" }, { 26.94, "Прошу, если что-нибудь увидишь, сразу скажи." } } }, t = { d = 30.8, g = 1, v = "human-female", n = { m = 356, f = 357 }, c = { m = { { 0.00, "Тебя послала Корма?" }, { 1.43, "Вот это новость!" }, { 2.61, "Когда на нас напали дворфы Чёрного Железа, мы потеряли друг друга, а я ударилась головой и не понимала, куда иду." }, { 10.40, "Так я и оказалась здесь и последние несколько дней жила на запасах из своей сумки." }, { 16.00, "Но раз уж ты прорвался мимо дворфов, может, и мне удастся сбежать." }, { 20.55, "Мне нужно только собрать вещи и немного прийти в себя, а там я придумаю, как отсюда выбраться!" }, { 27.08, "Она не сдалась и не бросила меня." }, { 29.45, "Какое доброе сердце." } }, f = { { 0.00, "Тебя послала Корма?" }, { 1.40, "Вот это новость!" }, { 2.55, "Когда на нас напали дворфы Чёрного Железа, мы потеряли друг друга, а я ударилась головой и не понимала, куда иду." }, { 10.13, "Так я и оказалась здесь и последние несколько дней жила на запасах из своей сумки." }, { 15.60, "Но раз уж ты прорвалась мимо дворфов, может, и мне удастся сбежать." }, { 20.09, "Мне нужно только собрать вещи и немного прийти в себя, а там я придумаю, как отсюда выбраться!" }, { 26.46, "Она не сдалась и не бросила меня." }, { 28.76, "Какое доброе сердце." } } } } },
    [87346] = { d = 50.5, v = "creature/furbolg", n = { x = 414 }, c = { x = { { 0.56, "Когда Легаши захватили Черночревов, остальные Древобрюхи запечатали проход в крепость, чтобы не пустить сатиров." }, { 9.15, "Мы и понятия не имели, что Черночревы выжили и скитаются беженцами." }, { 17.30, "Нашим братьям стоило бы помочь, но у нас свои битвы." }, { 21.93, "Как Легаши угрожают Черночревам, так и племя Мёртвого Леса угрожает нам." }, { 28.14, "Лишних воинов у нас мало." }, { 33.47, "Вождь Мёртвого Леса, Кровавая Утроба, засел в Деревне Сквернолапов к югу отсюда." }, { 39.94, "Если покончить с ним, нам станет намного легче." }, { 43.79, "Принеси мне его булаву — и получишь нашу помощь." } } } },
    [87451] = { d = 23.7, v = "narrator", n = { x = 240 }, c = { x = { { 0.00, "Это резное каменное украшение, которое было у огра, оказалось маленькой фигуркой, изображающей семью орков." }, { 8.66, "Возможно, это память об орках, что жили здесь, когда на этом месте стоял городок Рокард, — ещё до нашествия огров." }, { 17.82, "Скорее всего, выжившим из Каменора эта вещь дорога как память или святыня." } } } },
    [87491] = { d = 37.5, v = "elemental-fire", n = { x = 282 }, c = { x = { { 1.20, "Пш-ш-ш!" }, { 1.91, "Гадкие дворфы Чёрного Железа призвали меня и теперь держат в заточении рядом со своим жалким костром!" }, { 12.06, "Огонь должен вырваться на свободу!" }, { 15.53, "Выпусти меня!" }, { 16.95, "Мне нужно бежать!" }, { 18.73, "Мне нужно ГОРЕТЬ!" }, { 20.51, "Ни одному дворфу Чёрного Железа не избежать кары!" }, { 25.40, "Испепели их!" }, { 26.65, "Спали их чёрный порох!" }, { 28.87, "Сожги их крепость, их фитили, их безумие!" }, { 32.97, "Выпусти меня, и я СОЖГУ ИХ ВСЕХ!" } } }, t = { d = 15.4, v = "dwarf-male", n = { x = 160 }, c = { x = { { 0.00, "Вот это было огненное представление!" }, { 2.85, "Никогда такого не видел!" }, { 4.80, "Хорошо, что огненный элементаль, кхм, выдохся, так сказать." }, { 9.32, "Худо было бы, если бы он взялся за всех нас, а не за этих дворфов Чёрного Железа!" } } } } },
    [87492] = { d = 30.6, g = 1, v = "tauren-male#68", n = { m = 315, f = 316 }, c = { m = { { 0.00, "Ты, наверное, видел необычные кристаллические наросты, которыми усеян этот кратер." }, { 6.63, "Я не рудокоп, но эти наросты, похоже, никак не вяжутся со здешней почвой и породами." }, { 13.41, "Кажется, когда я собирал припасы, неподалёку мне попался на глаза повреждённый кристалл." }, { 20.33, "Интересно, не хранит ли он тайну происхождения этих странных образований?" }, { 26.16, "Если вдруг увидишь его, я бы с радостью изучил образец." } }, f = { { 0.00, "Ты, наверное, видела необычные кристаллические наросты, которыми усеян этот кратер." }, { 6.77, "Я не рудокоп, но эти наросты, похоже, никак не вяжутся со здешней почвой и породами." }, { 13.55, "Кажется, когда я собирал припасы, неподалёку мне попался на глаза повреждённый кристалл." }, { 20.47, "Интересно, не хранит ли он тайну происхождения этих странных образований?" }, { 26.30, "Если вдруг увидишь его, я бы с радостью изучил образец." } } } },
    [87494] = { d = 13.1, v = "narrator", n = { x = 145 }, c = { x = { { 0.00, "Эта чешуя отражает свет чуть сильнее остальных и переливается, будто в неё вкраплены крошечные частицы кристалла." }, { 8.73, "Может быть, землепроходец Торва сумеет в этом разобраться." } } } },
    [87760] = { d = 33.8, v = "nightelf-female#51", n = { x = 380 }, c = { x = { { 0.00, "Пришли вести из Дарнасса!" }, { 1.92, "Изучив образцы животных, мы узнали, что наги подчинили этих морских существ своей воле и заставляют их перевозить всадников и тяжёлые грузы." }, { 12.28, "А самых непокорных, старых и тяжело раненых они просто изгнали." }, { 17.05, "Это чудовищно!" }, { 18.18, "Наш священный долг – остановить это!" }, { 20.83, "Силы наг обосновались возле руин Матистры." }, { 24.02, "Должно быть, они охотятся на крепкозубов с ближайшего побережья." }, { 28.73, "Найди их укротительницу, убей её и принеси мне её жестокие инструменты!" } } }, t = { d = 22.2, g = 1, v = "nightelf-female#51", n = { m = 255, f = 256 }, c = { m = { { 0.00, "Мы прошли долгий путь, но он того стоил." }, { 2.93, "Ты наконец-то захватил жезл, позволявший нагам контролировать морских существ." }, { 8.52, "Я прослежу за тем, чтобы его уничтожили, после чего крепкозубы и морские черепахи снова смогут жить спокойно." }, { 16.45, "Спасибо тебе ещё раз от меня лично." }, { 19.05, "Твоя настойчивость принесла достойные плоды." } }, f = { { 0.00, "Мы прошли долгий путь, но он того стоил." }, { 2.93, "Ты наконец-то захватила жезл, позволявший нагам контролировать морских существ." }, { 8.59, "Я прослежу за тем, чтобы его уничтожили, после чего крепкозубы и морские черепахи снова смогут жить спокойно." }, { 16.53, "Спасибо тебе ещё раз от меня лично." }, { 19.13, "Твоя настойчивость принесла достойные плоды." } } } } },
    [88756] = { d = 29.2, v = "dwarf-male", n = { x = 338 }, c = { x = { { 0.00, "У дворфов Чёрного Железа есть несколько лагерей к востоку отсюда, на Зловещем холме." }, { 5.91, "Они украли кучу взрывчатки с нашей стройплощадки и сложили её в своих палатках." }, { 11.56, "Мне незачем говорить, какой переполох устроят дворфы Чёрного Железа, если им дать бочку пороха!" }, { 18.29, "Я знаю, что эти ребята опасны, но нам надо вернуть бочки." }, { 22.42, "Их можно отличить от других по красным меткам." }, { 25.72, "Нельзя, чтобы они остались у клана Чёрного Железа!" } } }, t = { d = 20.6, v = "dwarf-male", n = { x = 233 }, c = { x = { { 0.00, "Ох, прям камень с души." }, { 1.63, "Теперь хотя бы дворфы Чёрного Железа не закатят тележку с бомбой в наши фургоны... и не закинут её требушетом... и не скатят с холма на нас... и не скормят слизням, чтоб потом выпустить их возле лагеря и поджечь." }, { 16.25, "Теперь осталось только следить, чтоб порох не отсырел!" }, { 20.08, "Спасибо!" } } } } },
    [88757] = { d = 20.2, v = "human-female", n = { x = 212 }, c = { x = { { 0.00, "Убегая от дворфов Чёрного Железа, я растеряла кучу важных вещей." }, { 4.92, "Кажется, не хватает... зелёного кожаного бурдюка, книги заклинаний и ожерелья... а мне это всё очень нужно!" }, { 12.99, "Если сможешь отыскать эти вещи, пока я заново всё упакую и переведу дух, то очень мне поможешь." } } }, t = { d = 11.3, g = 1, v = "human-female", n = { m = 91, f = 91 }, c = { m = { { 0.00, "Ты нашёл мою книгу!" }, { 1.89, "И бурдюк!" }, { 2.84, "И ожерелье!" }, { 3.96, "Ох, сегодня мне везёт... огромное тебе спасибо." }, { 8.43, "Надо бы проверить, всё ли цело!" } }, f = { { 0.00, "Ты нашла мою книгу!" }, { 1.92, "И бурдюк!" }, { 2.84, "И ожерелье!" }, { 3.93, "Ох, сегодня мне везёт... огромное тебе спасибо." }, { 8.28, "Надо бы проверить, всё ли цело!" } } } } },
    [88758] = { d = 12.2, v = "human-female", n = { x = 134 }, c = { x = { { 0.00, "Осталось только окончательно всё упаковать – и только вы меня и видели!" }, { 5.18, "Окажи мне одну последнюю услугу – отнеси эту записку Корме." }, { 9.63, "Пусть знает, что я жива и скоро буду." } } }, t = { d = 19.9, g = 1, v = "human-female", n = { m = 187, f = 189 }, c = { m = { { 0.00, "Она жива?" }, { 0.88, "Она жива!" }, { 1.76, "Дай-ка взглянуть на записку..." }, { 4.25, "«Дорогая Корма...» так-так... о, благословенный день!" }, { 8.50, "Хвала Свету!" }, { 9.59, "Я никогда не смогу отблагодарить тебя за то, что ты снова нас свёл." }, { 14.94, "Скорей бы она вернулась!" }, { 16.99, "Ты оказал огромную услугу нам обеим." } }, f = { { 0.00, "Она жива?" }, { 0.87, "Она жива!" }, { 1.75, "Дай-ка взглянуть на записку..." }, { 4.22, "«Дорогая Корма...» так-так... о, благословенный день!" }, { 8.44, "Хвала Свету!" }, { 9.53, "Я никогда не смогу отблагодарить тебя за то, что ты снова нас свела." }, { 14.98, "Скорей бы она вернулась!" }, { 17.02, "Ты оказала огромную услугу нам обеим." } } } } },
    [88807] = { d = 35.7, g = 1, v = "nightelf-female#52", n = { m = 406, f = 407 }, c = { m = { { 0.00, "Азшара может показаться прекрасной, но это проклятое место." }, { 4.30, "В глубине её вод таятся ужасы, что ждут своего часа, чтобы вырваться наружу и разорвать мир на части." }, { 11.49, "Пока что мы можем лишь сражаться с теми ужасами, что уже вышли на поверхность." }, { 17.08, "Наги из клана Зловещего Хвоста заняли руины Эльдарата к северо-востоку." }, { 22.28, "Те, что засели в самих руинах, хорошо укрепились, поэтому сначала нужно перебить тех, что послабее, на окраинах." }, { 30.24, "Как видишь, лишний боец нам всегда пригодится, если ты готов взяться за дело." } }, f = { { 0.00, "Азшара может показаться прекрасной, но это проклятое место." }, { 4.30, "В глубине её вод таятся ужасы, что ждут своего часа, чтобы вырваться наружу и разорвать мир на части." }, { 11.49, "Пока что мы можем лишь сражаться с теми ужасами, что уже вышли на поверхность." }, { 17.08, "Наги из клана Зловещего Хвоста заняли руины Эльдарата к северо-востоку." }, { 22.28, "Те, что засели в самих руинах, хорошо укрепились, поэтому сначала нужно перебить тех, что послабее, на окраинах." }, { 30.24, "Как видишь, лишний боец нам всегда пригодится, если ты готова взяться за дело." } } } },
    [88809] = { d = 34.6, v = "nightelf-female", n = { x = 410 }, c = { x = { { 0.00, "Тысячи лет назад Эльдарат был поистине великолепен — живое свидетельство славы и могущества калдорай." }, { 6.96, "То, что мы сегодня называем Эльдаратом, по сравнению с ним — жалкая груда обломков." }, { 12.61, "И всё же то, что осталось, стоит спасти, хотя бы ради нашей истории." }, { 17.33, "Наг из клана Зловещего Хвоста нужно изгнать, пока они не разграбили Эльдарат дочиста." }, { 23.29, "Дорога на северо-восток приведёт тебя прямо в сердце руин." }, { 27.39, "Отправляйся туда и собери столько наших реликвий, сколько сможешь, — а заодно принеси голову их командира." } } } },
    [88812] = { d = 33.3, g = 1, v = "nightelf-female", n = { m = 417, f = 418 }, c = { m = { { 0.00, "Боюсь, время скоро сотрёт память о калдорайском доме Чёрного Ворона." }, { 4.55, "Одинокий, осыпающийся памятник — единственное уцелевшее свидетельство того, что они здесь жили." }, { 10.83, "Памятник стоит на вершине утёсов на самой оконечности южного полуострова." }, { 15.68, "Чародейки из клана Зловещего Хвоста пользуются там камнями силы, через которые направляют свою магию." }, { 22.51, "Возьми этот оберег и обезвредь их." }, { 24.84, "Это подорвёт магию Зловещего Хвоста и даст нам преимущество, когда мы будем их изгонять." }, { 30.65, "А заодно и сам перебей несколько наг." } }, f = { { 0.00, "Боюсь, время скоро сотрёт память о калдорайском доме Чёрного Ворона." }, { 4.55, "Одинокий, осыпающийся памятник — единственное уцелевшее свидетельство того, что они здесь жили." }, { 10.83, "Памятник стоит на вершине утёсов на самой оконечности южного полуострова." }, { 15.68, "Чародейки из клана Зловещего Хвоста пользуются там камнями силы, через которые направляют свою магию." }, { 22.51, "Возьми этот оберег и обезвредь их." }, { 24.84, "Это подорвёт магию Зловещего Хвоста и даст нам преимущество, когда мы будем их изгонять." }, { 30.65, "А заодно и сама перебей несколько наг." } } } },
    [88813] = { d = 19.7, v = "nightelf-female", n = { x = 234 }, c = { x = { { 0.00, "Твоя последняя цель — полководец Креллиан, предводитель Зловещего Хвоста." }, { 5.11, "Он прячется за спинами своих стражей в храме Зин-Малор в руинах Эльдарата." }, { 10.35, "Отруби Креллиану голову, и его прислужники в страхе уползут обратно в море." }, { 15.72, "И тогда наконец Азшара снова будет принадлежать калдорай." } } } },
    [88821] = { d = 27.4, v = "nightelf-female", n = { x = 338 }, c = { x = { { 0.00, "Одна из наших часовых, разведывая утёсы над Разорённым побережьем, заметила на берегу женщину из калдорай." }, { 6.93, "Ясно, что она не из нашей экспедиции, и на воительницу она не похожа." }, { 11.54, "Тогда что же она может делать в таком враждебном месте?" }, { 15.30, "Если получится, попробуй с ней связаться." }, { 18.05, "Я хочу знать, зачем она здесь и не совпадают ли наши интересы." }, { 22.18, "В последний раз её видели на восточном побережье, у северного берега Залива Бурь." } } } },
    [88857] = { d = 21.6, g = 1, v = "nightelf-female", n = { x = 200 }, c = { m = { { 0.00, "*Часовая говорит тихим шёпотом.*" }, { 3.12, "Слушай, герой, пока они нас не услышали." }, { 6.05, "Я часовая с заставы Талрендис." }, { 8.22, "Сатиры думают, что я ранена, но я лишь притворяюсь — жду, когда они потеряют бдительность и я смогу сбежать." }, { 15.80, "Возможно, твоё появление — как раз такой момент." }, { 19.18, "Поможешь мне выбраться отсюда?" } }, f = { { 0.00, "*Часовая говорит тихим шёпотом.*" }, { 3.05, "Слушай, героиня, пока они нас не услышали." }, { 6.48, "Я часовая с заставы Талрендис." }, { 8.65, "Сатиры думают, что я ранена, но я лишь притворяюсь — жду, когда они потеряют бдительность и я смогу сбежать." }, { 16.23, "Возможно, твоё появление — как раз такой момент." }, { 19.61, "Поможешь мне выбраться отсюда?" } } } },
    [88884] = { d = 28.4, g = 1, v = "nightelf-female#53", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Чуть южнее, вдоль пляжа, есть скрижали с письменами высокорождённых." }, { 5.27, "В них описаны изыскания высокорождённых в законах и силах тайной магии." }, { 10.91, "Скрижали хранятся в строениях, похожих на пагоды, и их охраняют наги, так что сама я ни за что не решилась бы их добыть." }, { 20.37, "К счастью, у меня теперь есть новый помощник!" }, { 24.05, "Ну, что скажешь?" }, { 25.35, "Сможешь ещё послужить делу познания?" } }, f = { { 0.00, "Чуть южнее, вдоль пляжа, есть скрижали с письменами высокорождённых." }, { 5.27, "В них описаны изыскания высокорождённых в законах и силах тайной магии." }, { 10.91, "Скрижали хранятся в строениях, похожих на пагоды, и их охраняют наги, так что сама я ни за что не решилась бы их добыть." }, { 20.37, "К счастью, у меня теперь есть новая помощница!" }, { 24.32, "Ну, что скажешь?" }, { 25.62, "Сможешь ещё послужить делу познания?" } } } },
    [88917] = { d = 34.9, g = 1, v = "nightelf-female#53", n = { x = 375 }, c = { m = { { 0.00, "Я пришла сюда в поисках артефактов высокорождённых." }, { 3.73, "Можешь считать меня кем-то вроде археолога." }, { 7.06, "В руинах Эльдарата к западу их немало, вот только наги прямо сейчас их грабят." }, { 12.92, "Грабежом заправляет нага по имени леди Сесспира — и лучшие находки она, несомненно, оставляет себе." }, { 20.38, "Если мои изыскания верны, у неё может быть посох верховного мага Селвин — павшего мага из высокорождённых." }, { 28.23, "Мне нужна твоя помощь, чтобы добыть этот посох, путник." }, { 32.50, "Учёным вроде меня в бою не место." } }, f = { { 0.00, "Я пришла сюда в поисках артефактов высокорождённых." }, { 3.77, "Можешь считать меня кем-то вроде археолога." }, { 7.14, "В руинах Эльдарата к западу их немало, вот только наги прямо сейчас их грабят." }, { 13.07, "Грабежом заправляет нага по имени леди Сесспира — и лучшие находки она, несомненно, оставляет себе." }, { 20.62, "Если мои изыскания верны, у неё может быть посох верховного мага Селвин — павшего мага из высокорождённых." }, { 28.57, "Мне нужна твоя помощь, чтобы добыть этот посох, путница." }, { 32.95, "Учёным вроде меня в бою не место." } } } },
    [89001] = { d = 29.0, v = "dwarf-male#100", n = { x = 334 }, c = { x = { { 0.00, "Здравствуй, путник!" }, { 1.39, "Если ищешь, где бы приклонить голову, лучше постоялого двора Бердана не найти!" }, { 6.96, "Палатка, правда, сейчас слегка потрёпана, но это дело поправимое." }, { 11.58, "Вот что я тебе скажу." }, { 13.10, "Раздобудешь мне всё, что нужно для починки палатки, — поселю тебя бесплатно." }, { 18.41, "Как тебе такое?" }, { 19.55, "Мне нужны шкуры мохоногих оленей." }, { 21.95, "Проще всего охотиться на мохоногов прямо к северу отсюда, но сгодится шкура любого мохоногого оленя." } } } },
    [89013] = { d = 27.7, g = 1, v = "dwarf-male#100", n = { m = 296, f = 297 }, c = { m = { { 0.00, "Что за постоялый двор без выпивки?" }, { 2.46, "Я варю отменную медовуху, но годы уже не те, чтобы самому собирать мёд." }, { 7.77, "Осиные гнёзда есть на деревьях к северу от лагеря Халдарр и к западу от Храбростана." }, { 13.88, "Если видишь гиппогрифов — значит, ты на месте." }, { 17.33, "Осы — мерзкие твари, но такого мёда ты в жизни не пробовал." }, { 21.72, "Одолжу тебе свой дробовик, чтобы сбивать гнёзда, — иначе до них не дотянуться." } }, f = { { 0.00, "Что за постоялый двор без выпивки?" }, { 2.46, "Я варю отменную медовуху, но годы уже не те, чтобы самому собирать мёд." }, { 7.77, "Осиные гнёзда есть на деревьях к северу от лагеря Халдарр и к западу от Храбростана." }, { 13.88, "Если видишь гиппогрифов — значит, ты на месте." }, { 17.32, "Осы — мерзкие твари, но такого мёда ты в жизни не пробовала." }, { 22.15, "Одолжу тебе свой дробовик, чтобы сбивать гнёзда, — иначе до них не дотянуться." } } } },
    [89015] = { d = 35.1, v = "dwarf-male", n = { x = 386 }, c = { x = { { 0.00, "Если считаешь себя настоящим рыболовом, знай: здесь водится рыба покрупнее, чем можно поймать на удочку." }, { 7.69, "Рыбы-молоты обитают в самых глубоких водах у северного и южного побережий." }, { 13.26, "Плавают они далеко, прямо там, где морское дно обрывается в великий океан." }, { 18.76, "Они чертовски большие — советую взять с собой ватагу рыболовов." }, { 23.47, "А дворфу вроде меня?" }, { 25.06, "Мне милее суша." }, { 26.25, "Эти рыбины проглотят меня в один присест." }, { 29.43, "Если всё же пойдёшь на охоту, принеси мне кусок мяса." }, { 33.34, "Буду премного благодарен." } } } },
    [89037] = { d = 35.5, g = 1, v = "nightelf-female#53", n = { x = 394 }, c = { m = { { 0.00, "На пляжах северного полуострова, к востоку отсюда, я наткнулась на Башню Эльдары." }, { 5.84, "Осматривая место, я заметила крупного оранжевого мурлока с шипастой дубиной, который нёс странный светящийся кристалл." }, { 14.34, "Судя по месту, это, скорее всего, один из тех кристаллов, в которых высокорождённые хранили свою историю и воспоминания." }, { 22.97, "Мы должны вернуть этот кристалл, путник." }, { 25.96, "Кто знает, какие тайны он может хранить?" }, { 28.94, "Лучше всего добираться до башни по утёсам, а ближайший подъём — прямо к западу отсюда." } }, f = { { 0.00, "На пляжах северного полуострова, к востоку отсюда, я наткнулась на Башню Эльдары." }, { 5.84, "Осматривая место, я заметила крупного оранжевого мурлока с шипастой дубиной, который нёс странный светящийся кристалл." }, { 14.34, "Судя по месту, это, скорее всего, один из тех кристаллов, в которых высокорождённые хранили свою историю и воспоминания." }, { 22.97, "Мы должны вернуть этот кристалл, путница." }, { 26.51, "Кто знает, какие тайны он может хранить?" }, { 29.49, "Лучше всего добираться до башни по утёсам, а ближайший подъём — прямо к западу отсюда." } } } },
    [89038] = { d = 34.0, v = "nightelf-female#53", n = { x = 386 }, c = { x = { { 0.00, "Говорят, некогда королева Азшара преподнесла дар калдорай из дома Чёрного Ворона — эмблему великой красоты и магической силы." }, { 9.23, "Этот знак был дарован в признание непоколебимой верности Чёрных Воронов королеве." }, { 15.15, "В последний раз знак видели у Памятника Чёрному Ворону, на вершине утёсов южного полуострова." }, { 21.86, "Найти такую реликвию — открытие всей жизни." }, { 25.11, "Как всегда, руины памятника кишат нагами из клана Зловещего Хвоста, но, думаю, ты уже довольно ловко с ними управляешься." } } } },
    [89053] = { d = 20.7, g = 1, v = "nightelf-female#53", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Я знаю, что изначально тебя прислали сюда на разведку, но ты очень много сделал для археологии." }, { 6.71, "Наверняка после всех твоих трудов тебе хочется узнать, какие плоды принесут мои изыскания." }, { 13.23, "Поэтому, прежде чем ты вернёшься в свой лагерь, я хочу тебе кое-что показать." }, { 18.61, "Окажешь мне такую любезность?" } }, f = { { 0.00, "Я знаю, что изначально тебя прислали сюда на разведку, но ты очень много сделала для археологии." }, { 6.79, "Наверняка после всех твоих трудов тебе хочется узнать, какие плоды принесут мои изыскания." }, { 13.31, "Поэтому, прежде чем ты вернёшься в свой лагерь, я хочу тебе кое-что показать." }, { 18.69, "Окажешь мне такую любезность?" } } } },
    [89228] = { d = 21.9, v = "dwarf-male", n = { x = 242 }, c = { x = { { 0.00, "Любой уважающий себя постоялый двор должен кормить гостей." }, { 4.32, "Сейчас сезон кальмаров, и их можно наловить у здешних берегов Азшары." }, { 9.43, "Сам я рыбак так себе, зато повар знатный!" }, { 12.51, "Ну, что скажешь?" }, { 13.68, "Не хочется ли морепродуктов?" }, { 15.71, "Если рыбалка — не твоё, подружись с каким-нибудь рыбаком!" }, { 19.84, "Или просто купи у него улов." } } } },
    [89470] = { d = 11.4, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Теперь, когда истинные намерения Сарии раскрыты, а у тебя в руках ранец с могущественными артефактами, самое время доложить обо всём командиру Песне Истины." } } } },
    [90813] = { d = 15.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Огромный кусок кристалла даже тяжелее, чем кажется." }, { 4.46, "Похоже, это ценная находка, но что это на самом деле — вам неизвестно." }, { 10.54, "Тот, кто разбирается в геологии, мог бы сказать, что вам попалось." } } } },
    [90902] = { d = 42.9, g = 1, v = "scourge-male#83", n = { m = 488, f = 486 }, c = { m = { { 0.00, "Я рад приветствовать в наших рядах ещё одного паладина, вернувшегося к жизни после смерти." }, { 6.60, "По мере того, как твоя связь со Светом восстанавливается, ты заметишь, что некоторые способности, в прошлом казавшиеся столь естественными, теперь могут причинять тебе сильную боль." }, { 19.66, "Особенно это касается тех, что позволяют тебе исцелять самого себя или кого-то ещё силой Света." }, { 26.78, "Как это ни печально, единственный способ справиться с этими трудностями – набраться терпения." }, { 33.58, "Как и при восстановлении атрофировавшихся мышц, тебе нужно превозмогать боль и закалять плоть, чтобы вернуть утраченные силы." } }, f = { { 0.00, "Я рад приветствовать в наших рядах ещё одного паладина, вернувшегося к жизни после смерти." }, { 6.69, "По мере того, как твоя связь со Светом восстанавливается, ты заметишь, что некоторые способности, в прошлом казавшиеся столь естественными, теперь могут причинять тебе сильную боль." }, { 19.94, "Особенно это касается тех, что позволяют тебе исцелять саму себя или кого-то ещё силой Света." }, { 27.03, "Как это ни печально, единственный способ справиться с этими трудностями – набраться терпения." }, { 33.93, "Как и при восстановлении атрофировавшихся мышц, тебе нужно превозмогать боль и закалять плоть, чтобы вернуть утраченные силы." } } }, t = { d = 24.6, g = 1, v = "scourge-male#83", n = { m = 227, f = 228 }, c = { m = { { 0.00, "Тем, кто пережил смерть, боль не в новинку, и поэтому Отрёкшиеся к ней особенно устойчивы." }, { 7.63, "Боль также очищает – пусть она станет для тебя знаком почёта и доказательством того, что ты не оставил служение Свету, несмотря на нынешние обстоятельства." }, { 21.14, "Береги себя и следуй путём Света, герой." } }, f = { { 0.00, "Тем, кто пережил смерть, боль не в новинку, и поэтому Отрёкшиеся к ней особенно устойчивы." }, { 7.48, "Боль также очищает – пусть она станет для тебя знаком почёта и доказательством того, что ты не оставила служение Свету, несмотря на нынешние обстоятельства." }, { 20.82, "Береги себя и следуй путём Света, героиня." } } } } },
    [91208] = { d = 36.5, v = "scourge-male#83", n = { x = 373 }, c = { x = { { 0.00, "Не всем нашим братьям-паладинам, вернувшимся к жизни, удаётся быстро приспособиться к новым условиям." }, { 8.08, "Некоторым трудно смириться с тем, что теперь они в некотором смысле стали тем, с чем боролись всю свою жизнь." }, { 16.82, "В таких случаях достаточно просто проявить к ним доброту и сочувствие." }, { 22.50, "К сожалению, многие поддаются гневу." }, { 25.49, "Найди испуганных паладинов, сбежавших в холмы к западу от этой часовни." }, { 31.32, "Протяни им руку дружбы и помоги вернуться к Свету, если сможешь." } } }, t = { d = 24.6, v = "scourge-male#83", n = { x = 248 }, c = { x = { { 0.00, "К сожалению, немало наших братьев и сестёр теряют рассудок схожим образом, когда восстают из мёртвых." }, { 8.26, "Каждый Отрёкшийся бесценен, но иногда нам не остаётся иного выхода, кроме как подарить покой тем, кто не может адаптироваться к новой жизни." }, { 19.55, "Я помолюсь Свету за неё." }, { 21.54, "Спасибо за то, что нужно было сделать." } } } } },
    [91209] = { d = 31.9, v = "scourge-male#83", n = { x = 331 }, c = { x = { { 0.00, "Лордерон уже не тот, что прежде, но наш дом по-прежнему нужно защищать от всевозможных угроз." }, { 7.38, "Пришло время тебе отправиться дальше и исследовать мир." }, { 11.87, "Отправляйся в город Брилл в центре Тирисфальских лесов и поговори с Шари Стилвелл." }, { 18.46, "Она продолжит твоё обучение." }, { 20.78, "Дам тебе ещё последний совет: паладинам опасно в землях Отрёкшихся." }, { 26.14, "Многие слуги Тёмной Госпожи не доверяют нам из-за нашей близости к Свету." } } }, t = { d = 32.7, g = 1, v = "scourge-female#80", n = { x = 303 }, c = { m = { { 0.00, "Добро пожаловать, герой." }, { 2.10, "Всегда приятно видеть пополнение в наших рядах." }, { 6.16, "Многие в Брилле нуждаются в помощи искателей приключений вроде тебя." }, { 11.94, "Поищи работу и стань сильнее в Свете." }, { 15.09, "А как понадобится чему-то обучиться, возвращайся ко мне." }, { 19.67, "Когда проявишь себя передо мной и жителями Брилла, я поведаю тебе, как перейти на следующий этап твоего путешествия." }, { 29.44, "Да направит тебя Свет, герой." } }, f = { { 0.00, "Добро пожаловать, героиня." }, { 2.30, "Всегда приятно видеть пополнение в наших рядах." }, { 6.44, "Многие в Брилле нуждаются в помощи искателей приключений вроде тебя." }, { 12.34, "Поищи работу и стань сильнее в Свете." }, { 15.56, "А как понадобится чему-то обучиться, возвращайся ко мне." }, { 20.23, "Когда проявишь себя передо мной и жителями Брилла, я поведаю тебе, как перейти на следующий этап твоего путешествия." }, { 30.19, "Да направит тебя Свет, героиня." } } } } },
    [91282] = { d = 39.4, v = "scourge-female#80", n = { x = 375 }, c = { x = { { 0.00, "На душе всегда радостно, когда вернувшиеся к жизни братья и сёстры добиваются таких успехов, как ты." }, { 8.69, "Только благодаря единству и общей вере мы можем по-настоящему раскрыть свой потенциал." }, { 16.20, "С этой целью мы организуем новый орден паладинов прямо здесь, в Тирисфале." }, { 22.69, "Если хочешь узнать больше, то загляни в наш монастырь на краю Шепчущего леса." }, { 29.50, "Он называется крепость Бандариона и находится на утёсах к северо-западу от фермы Соллидена – его трудно не заметить." } } }, t = { d = 5.8, g = 1, v = "scourge-male#83", n = { m = 55, f = 57 }, c = { m = { { 0.00, "Ещё один новобранец?" }, { 1.76, "Добро пожаловать в крепость Бандариона, брат." } }, f = { { 0.00, "Ещё один новобранец?" }, { 1.82, "Добро пожаловать в крепость Бандариона, сестра." } } } } },
    [91285] = { d = 35.6, g = 1, v = "scourge-male#83", n = { m = 389, f = 390 }, c = { m = { { 0.00, "Обычно мы радушнее приветствуем новичков, но сейчас совсем не до этого, уж слишком нам досаждают мурлоки." }, { 7.64, "Раньше в крепости находилось нерестилище их племени." }, { 11.46, "С тех пор как мы сюда перебрались и изгнали мурлочье отродье, они попили немало нашей крови, но теперь ситуация действительно начинает выходить из-под контроля." }, { 24.58, "Ты, кажется, уже многое повидал." }, { 27.01, "Поможешь нам отвадить этих вредителей?" }, { 29.85, "Они прячутся на утёсах вдоль дороги на восток и в лагерях вокруг озера на западе." } }, f = { { 0.00, "Обычно мы радушнее приветствуем новичков, но сейчас совсем не до этого, уж слишком нам досаждают мурлоки." }, { 7.61, "Раньше в крепости находилось нерестилище их племени." }, { 11.41, "С тех пор как мы сюда перебрались и изгнали мурлочье отродье, они попили немало нашей крови, но теперь ситуация действительно начинает выходить из-под контроля." }, { 23.09, "Ты, кажется, уже многое повидала." }, { 25.58, "Поможешь нам отвадить этих вредителей?" }, { 28.40, "Они прячутся на утёсах вдоль дороги на восток и в лагерях вокруг озера на западе." } } }, t = { d = 18.5, v = "scourge-male#83", n = { x = 188 }, c = { x = { { 0.00, "Мы благодарны тебе за помощь." }, { 2.39, "Конечно, нападения вряд ли прекратятся совсем, но надеюсь, они хотя бы станут реже." }, { 9.13, "Отстраиваться здесь и без того нелегко, и мурлоки, вечно норовящие ткнуть тебя в спину копьём, делу совсем не помогают." } } } } },
    [91294] = { d = 22.8, v = "scourge-male#83", n = { x = 229 }, c = { x = { { 0.00, "Теперь, когда угроза нападения мурлоков устранена, советую тебе осмотреть нашу крепость." }, { 7.36, "Выглядит не очень впечатляюще, но это наш дом." }, { 11.11, "Как обойдёшь её, найди Даниту Морр, нашего лидера." }, { 15.16, "Она поможет тебе обустроиться." }, { 17.73, "Я очень рад, что мы с тобой познакомились." }, { 21.11, "Да направит тебя Свет." } } }, t = { d = 22.4, v = "scourge-female", n = { x = 229 }, c = { x = { { 0.00, "Тебя прислал Бретон?" }, { 1.71, "Отлично." }, { 2.43, "Меня зовут Данита Морр, и я вроде как командир этой крепости." }, { 7.35, "Если ты здесь, чтобы примкнуть к тем, кто сохранил верность Свету, то ты как раз по адресу." }, { 14.42, "Нам предстоит много работы, чтобы здесь как следует закрепиться, и мы будем очень благодарны за помощь." } } } } },
    [91316] = { d = 35.7, v = "scourge-male#83", n = { x = 424 }, c = { x = { { 0.00, "На таком расстоянии от Подгорода логистика становится сущим кошмаром, и сейчас мы испытываем огромную нехватку стройматериалов, необходимых для восстановления крепости." }, { 11.83, "Твоя помощь в этом деле пришлась бы очень кстати." }, { 15.50, "В Шепчущем лесу к юго-западу отсюда совсем неподалёку ты найдёшь разрушенную деревню Тенедол." }, { 22.12, "В одном из строений должен быть старый погребок в корнях, где хранилась всякая всячина." }, { 28.36, "Наверняка там отыщется что-нибудь полезное." }, { 31.45, "Забери оттуда всё, что может пригодиться, и возвращайся к нам." } } }, t = { d = 12.2, v = "scourge-male#83", n = { x = 142 }, c = { x = { { 0.00, "Отрадно видеть, что твоё путешествие в Тенедол оказалось плодотворным." }, { 5.10, "Я пошлю туда Бретона с несколькими новобранцами – пусть заберут из погреба всё, что там ещё осталось." } } } } },
    [91317] = { d = 46.5, g = 1, v = "scourge-female", n = { m = 447, f = 448 }, c = { m = { { 0.00, "Как ты, возможно, уже обратил внимание, не все восставшие из мёртвых паладины смирились со своей новой формой бытия." }, { 9.69, "Некоторые из них до сих пор одержимы предрассудками из прошлой жизни, и потому проявляют агрессию к своим новым братьям-Отрёкшимся." }, { 20.52, "К нам с недоверием относятся наши же собратья, которые пока ещё слишком хорошо помнят притеснения, творимые живыми во имя Света, и подобные неприятности нам совершенно ни к чему." }, { 35.44, "Группа таких \"Порочных\" обосновалась в Тенедоле, что к юго-западу отсюда." }, { 41.65, "Перебей всех и принеси мне голову их лидера." } }, f = { { 0.00, "Как ты, возможно, уже обратила внимание, не все восставшие из мёртвых паладины смирились со своей новой формой бытия." }, { 10.03, "Некоторые из них до сих пор одержимы предрассудками из прошлой жизни, и потому проявляют агрессию к своим новым братьям-Отрёкшимся." }, { 21.14, "К нам с недоверием относятся наши же собратья, которые пока ещё слишком хорошо помнят притеснения, творимые живыми во имя Света, и подобные неприятности нам совершенно ни к чему." }, { 36.46, "Группа таких \"Порочных\" обосновалась в Тенедоле, что к юго-западу отсюда." }, { 42.83, "Перебей всех и принеси мне голову их лидера." } } }, t = { d = 44.8, v = "scourge-female", n = { x = 419 }, c = { x = { { 0.00, "Прекрасная работа." }, { 1.69, "Всякий раз когда любой из этих \"Порочных\" восстаёт против нас и убивает одного из Отрёкшихся, нашим недоброжелателям становится легче разжигать недоверие к нам, паладинам." }, { 16.70, "Их истребление поможет нашему делу и поможет укрепить наши позиции здесь, в Тирисфале." }, { 24.41, "Думаю, пройдёт ещё немало времени, прежде чем Отрёкшиеся и Орда окончательно примут нас как своих." }, { 33.00, "Возможно, на это уйдут годы или даже десятилетия, но пока лучшее, что мы можем сделать – это всячески подтверждать нашу преданность." } } } } },
    [91488] = { d = 22.8, v = "orc-male", n = { x = 233 }, c = { x = { { 0.00, "В последней стычке с эльфами крови мою палатку сильно потрепало." }, { 5.27, "Вот уже три ночи я во власти стихий." }, { 8.23, "Её можно починить парой шкур мохоногих оленей, но без сна мне на них не поохотиться." }, { 14.80, "Проще всего охотиться на мохоногов к западу и югу отсюда, но сгодится шкура любого мохоногого оленя." } } } },
    [91497] = { d = 37.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "На печати первого кристалла — знак меча." }, { 3.29, "Его энергией должен управлять искусный воин." }, { 7.03, "На печати среднего кристалла — знак глефы." }, { 10.47, "Его энергией должен управлять тот, кто владеет и боевым, и магическим искусством." }, { 17.05, "На печати последнего кристалла — знак когтя." }, { 20.64, "Его энергией должен управлять тот, кому дикая природа — родной дом." }, { 26.20, "Скорее всего, эти печати носят при себе офицеры Римтори, чтобы помогать ей с заклинанием." }, { 33.59, "Если их забрать, у неё наверняка возникнут трудности." } } } },
    [91500] = { d = 21.4, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Видя, что энергия кристаллов настроена на печати, ты понимаешь: если уничтожить печать и разом высвободить её энергию, кристалл может сделать то же самое." }, { 12.11, "Такой взрыв наверняка приведёт Римтори в ярость." }, { 15.86, "Но заодно это идеальная возможность напасть на неё, пока она в смятении." } } } },
    [91531] = { d = 10.4, v = "orc-male", n = { x = 97 }, c = { x = { { 0.00, "Возвращайся к Белгрому в Оргриммар." }, { 3.10, "Он захочет сам увидеть её голову!" }, { 6.03, "А, сегодня и впрямь добрый день." }, { 8.81, "Спасибо за помощь." } } } },
    [91538] = { d = 12.6, v = "narrator", n = { x = 133 }, c = { x = { { 0.00, "Фолиант Римтори всё ещё лежит на постаменте." }, { 3.50, "Кто знает, какие тайны хранят его страницы?" }, { 7.07, "Пожалуй, не стоит оставлять столь могущественный артефакт здесь, в глуши." } } } },
    [91547] = { d = 24.4, g = 1, v = "orc-female", n = { m = 250, f = 251 }, c = { m = { { 0.00, "Ты поступил мудро, забрав это." }, { 2.45, "Смерть Римтори — это одно, но куда важнее, что книга не досталась эльфам крови: теперь им нечем нам ответить." }, { 11.00, "А что до расшифровки самого фолианта, у меня есть знакомый в Оргриммаре, который балуется такими вещами, — чернокнижник по имени Зеврост." }, { 21.59, "Его можно найти в Расселине Теней." } }, f = { { 0.00, "Ты поступила мудро, забрав это." }, { 2.59, "Смерть Римтори — это одно, но куда важнее, что книга не досталась эльфам крови: теперь им нечем нам ответить." }, { 11.14, "А что до расшифровки самого фолианта, у меня есть знакомый в Оргриммаре, который балуется такими вещами, — чернокнижник по имени Зеврост." }, { 21.73, "Его можно найти в Расселине Теней." } } } },
    [91548] = { d = 42.7, v = "orc-male", n = { x = 384 }, c = { x = { { 0.00, "Я не говорю на талассийском, но эти схемы мне знакомы." }, { 4.50, "Зная, как эльфы крови пристрастились к мане, я бы сказал, что они пытались призвать демонов, чтобы высосать из них магию Скверны." }, { 15.30, "Просто поглотить такую мощную энергию — расточительство." }, { 20.02, "Ей можно найти куда более достойное применение." }, { 24.00, "*Зеврост закладывает страницу в фолианте.*" }, { 27.20, "В Выжженных землях есть Алтарь Бурь." }, { 30.29, "Проведи там этот ритуал и призови демона Век'зола." }, { 34.69, "Его сердце станет могущественным реагентом." }, { 38.48, "Только представь, какая сила будет в наших руках!" } } } },
    [91568] = { d = 33.3, v = "goblin-female", n = { x = 347 }, c = { x = { { 0.00, "Красотой здешние пляжи не блещут, зато ценностей тут навалом!" }, { 4.72, "Руины в округе почти все обчистили, но под песком лежит серьёзная добыча." }, { 10.25, "Беда в том, что она разбросана повсюду, а с нагами долго не поищешь." }, { 15.45, "Ну и что делать бедной девушке?" }, { 17.84, "Встречай мастерок искателя сокровищ три тысячи!" }, { 21.47, "Лопата и искатель сокровищ в одном!" }, { 24.20, "Моё личное изобретение." }, { 25.98, "Бери эту крошку, ступай на восточный берег и тащи сюда всё, что найдёшь." }, { 31.51, "А потом поделим прибыль!" } } } },
    [91569] = { d = 34.0, g = 1, v = "goblin-female", n = { m = 357, f = 359 }, c = { m = { { 0.00, "Слушай, малыш, тут все гоняются за одним и тем же." }, { 3.77, "Белгром, эльфы, наги — всем подавай кусочек древней магии высокорождённых." }, { 9.39, "А мне?" }, { 9.87, "Мне на неё плевать, но когда спрос на товар бешеный — я это сразу чую." }, { 15.22, "Я видела у чародеев эльфов крови особые жезлы." }, { 18.85, "Ими вытягивают магическую энергию из артефактов, которые находят эльфы." }, { 24.33, "Чародеи сидят в лагере к востоку от главного лагеря эльфов, вдоль скал." }, { 29.75, "Добудь мне такой жезл, и я наведу тебя на куш всей жизни!" } }, f = { { 0.00, "Слушай, малышка, тут все гоняются за одним и тем же." }, { 3.88, "Белгром, эльфы, наги — всем подавай кусочек древней магии высокорождённых." }, { 9.50, "А мне?" }, { 9.98, "Мне на неё плевать, но когда спрос на товар бешеный — я это сразу чую." }, { 15.33, "Я видела у чародеев эльфов крови особые жезлы." }, { 18.96, "Ими вытягивают магическую энергию из артефактов, которые находят эльфы." }, { 24.44, "Чародеи сидят в лагере к востоку от главного лагеря эльфов, вдоль скал." }, { 29.86, "Добудь мне такой жезл, и я наведу тебя на куш всей жизни!" } } } },
    [91607] = { d = 16.9, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Огромный кусок кристалла даже тяжелее, чем кажется." }, { 4.43, "Похоже, это настоящее сокровище, но что это такое на самом деле, вам неизвестно." }, { 11.31, "Тот, кто знает толк в ценностях, мог бы сказать, что именно вы нашли." } } } },
    [91608] = { d = 30.0, v = "orc-male", n = { x = 293 }, c = { x = { { 0.00, "Здесь, на рубеже, радостей мало." }, { 2.70, "Бочонок доброй выпивки наверняка поднял бы боевой дух лагеря." }, { 7.88, "В молодости я снял с трупа убитого мной дворфа рецепт отменного напитка." }, { 13.88, "Не хватает только мёда." }, { 15.83, "К счастью, осиные гнёзда к западу отсюда им так и полны." }, { 20.48, "Возьми мой дробовик." }, { 22.20, "С ним ты сможешь сбивать гнёзда с деревьев." }, { 25.73, "Но имей в виду: против самих ос он почти бесполезен." } } } },
    [91610] = { d = 23.7, v = "orc-male", n = { x = 236 }, c = { x = { { 0.00, "Мясо — это хорошо, но разнообразная пища делает тело крепче." }, { 5.00, "Сейчас сезон зимних кальмаров, их можно наловить у здешних берегов Азшары." }, { 11.08, "Сам я к рыбалке так и не пристрастился — по мне, на суше куда безопаснее." }, { 16.81, "Но если ты наловишь их или добудешь каким-то другим способом, я буду очень благодарен." } } } },
    [91611] = { d = 32.1, v = "orc-male", n = { x = 307 }, c = { x = { { 0.00, "Если хочешь по-настоящему испытать своё рыбацкое мастерство, знай: есть рыба и покрупнее той, что ловят удочкой." }, { 9.46, "Рыбы-молоты таятся в самых глубоких водах у северного и южного побережья." }, { 15.85, "Они заплывают далеко, туда, где морское дно обрывается в великий океан." }, { 22.00, "Это огромные твари." }, { 23.77, "Советую взять с собой отряд охотников." }, { 27.08, "Если всё же отправишься за такой, принеси мне кусок её мяса." } } } },
    [91685] = { d = 35.8, v = "goblin-female", n = { x = 392 }, c = { x = { { 0.00, "Когда мы только сюда прибыли, я поискала, нет ли тут нетронутых богатств." }, { 5.27, "Ну, обычная работа старателя." }, { 7.42, "Ничего особенного не попадалось, пока я не осмотрела озеро Меннар к югу отсюда." }, { 13.20, "Там над водой висит огромный разлом." }, { 15.87, "Подобраться ближе я не смогла, но, по-моему, это открытая силовая линия." }, { 21.14, "Если я права, этим жезлом можно тянуть магию прямо из источника!" }, { 25.95, "Разлить её по бутылкам, продать тому, кто больше заплатит, и бац — я богата!" }, { 31.42, "Сходи вытяни магию из этого разлома, и я возьму тебя в долю." } } } },
    [91723] = { d = 18.3, v = "human-male", n = { x = 237 }, c = { x = { { 0.00, "Проклятие!" }, { 0.70, "Каждый раз, когда я пытаюсь настроить эту чувствительную магическую аппаратуру, всё идёт прахом из-за всплесков энергии." }, { 8.50, "Их источники, кажется, находятся на севере, где кобольды-недоумки занимаются своей грубой магией." }, { 14.83, "Можешь избавиться от них, чтобы я мог продолжить работу?" } } }, t = { d = 4.0, v = "human-male", n = { x = 40 }, c = { x = { { 0.00, "Прекрасно!" }, { 0.89, "Дай-ка ещё раз попробую всё настроить..." } } } } },
    [91724] = { d = 22.5, v = "human-male", n = { x = 251 }, c = { x = { { 0.00, "Почти готово..." }, { 1.17, "Ну-ка, ну-ка..." }, { 2.33, "Да чтоб вас Пустота поглотила!" }, { 4.47, "Что-то всё ещё мешает аппаратуре работать." }, { 7.52, "Как же это всё утомительно." }, { 9.46, "Говорят, местные бандиты практикуются в магии рядом с озером Каменных Столбов." }, { 15.17, "Может, если остановишь их, всё наконец заработает как надо, и я смогу получить хоть какие-то результаты?" } } }, t = { d = 3.8, v = "human-male", n = { x = 41 }, c = { x = { { 0.00, "Кажется, всё наконец работает нормально." }, { 3.20, "Спасибо." } } } } },
    [91725] = { d = 22.5, v = "gnome-female#39", n = { x = 278 }, c = { x = { { 0.00, "Наставник Теокрит велел мне забрать кое-какие припасы для наложения чар в торговой лавке, но на обратном пути на меня напала шайка гноллов!" }, { 9.46, "Мне удалось спастись, но припасы пришлось бросить." }, { 12.86, "Если я вернусь без них, то в наказание буду ещё много недель прибираться после экспериментов по превращению!" }, { 20.07, "Может, поможешь мне и найдёшь пропажу?" } } }, t = { d = 5.6, v = "gnome-female#39", n = { x = 44 }, c = { x = { { 0.00, "Ох, прямо гора с плеч!" }, { 2.18, "Кажется, всё на месте." }, { 4.37, "Спасибо тебе!" } } } } },
    [91732] = { d = 18.9, v = "human-male", n = { x = 231 }, c = { x = { { 0.00, "После войны хорошей стали не хватает, и из-за этого инструменты наши не те, что прежде." }, { 5.90, "Шахтёры в Яшмовой шахте работали отличными стальными кирками, и некоторые из них наверняка ещё лежат где-то в глубине." }, { 13.72, "Можешь достать мне хоть немного?" }, { 15.89, "А я попробую что-нибудь сделать из этой стали." } } }, t = { d = 5.4, v = "human-male", n = { x = 43 }, c = { x = { { 0.00, "О, неплохо." }, { 1.12, "Видишь, как блестит?" }, { 3.11, "Да, умели раньше делать." } } } } },
    [91733] = { d = 18.9, v = "human-male", n = { x = 221 }, c = { x = { { 0.00, "Я вёз припасы из торговой лавки, но моя повозка перевернулась, и груз оказался в реке!" }, { 5.81, "Я даже выловить его не успел – так быстро его унесло вниз по течению." }, { 10.58, "Там полно мурлоков и волков, так что самому мне припасы никак не вернуть." }, { 15.53, "Ты, вроде бы, не робкого десятка." }, { 17.80, "Сможешь их найти?" } } }, t = { d = 5.7, g = 1, v = "human-male", n = { m = 53, f = 54 }, c = { m = { { 0.00, "Вижу, ты порядком промок." }, { 2.13, "Уж извини." }, { 3.02, "Но спасибо, что вернул припасы." } }, f = { { 0.00, "Вижу, ты порядком промокла." }, { 2.32, "Уж извини." }, { 3.22, "Но спасибо, что вернула припасы." } } } } },
    [91734] = { d = 19.2, v = "scourge-male", n = { x = 72 }, c = { x = { { 0.00, "*Отрёкшийся качается из стороны в сторону.*" }, { 3.60, "Эй!" }, { 4.01, "Окажи мне услугу... ладно?" }, { 8.06, "Отправляйся в... э-э... в Азшару и... скажи..." }, { 13.22, "Джедиге..." }, { 15.45, "Жду... важную доставку..." } } } },
    [91735] = { d = 22.4, g = 1, v = "troll-male", n = { x = 215 }, c = { m = { { 0.00, "Слушай, герой, лучше тебе тут надолго не задерживаться." }, { 4.40, "Но раз уж всё равно ты тут, может, окажешь мне небольшую услугу?" }, { 9.37, "Я кое-что жду от Джедиги из Азшары." }, { 12.14, "Она там обосновалась в лагере вместе с другими орками." }, { 16.46, "Иди туда и скажи, что тебя прислал Джес'римон, – за мной будет должок." } }, f = { { 0.00, "Слушай, героиня, лучше тебе тут надолго не задерживаться." }, { 4.91, "Но раз уж всё равно ты тут, может, окажешь мне небольшую услугу?" }, { 9.88, "Я кое-что жду от Джедиги из Азшары." }, { 12.65, "Она там обосновалась в лагере вместе с другими орками." }, { 16.97, "Иди туда и скажи, что тебя прислал Джес'римон, – за мной будет должок." } } } },
    [91736] = { t = { d = 3.6, v = "narrator", n = { x = 41 }, c = { x = { { 0.00, "Машина наполняет бутылку прозрачной жидкостью..." } } } } },
    [91737] = { d = 22.6, v = "narrator", n = { x = 248 }, c = { x = { { 0.00, "Время от времени мне бывают нужны реагенты из отдалённых уголков Азерота." }, { 5.58, "Однако я не могу позволить себе покинуть Громовой Утёс, поэтому мне нужны компетентные помощники." }, { 13.01, "Сейчас я жду доставку от орчихи Джедиги из Азшары." }, { 16.87, "Если захочешь помочь, найди её лагерь и поинтересуйся, долго ли мне ещё ждать." } } } },
    [91738] = { t = { d = 11.4, g = 1, v = "human-male", n = { x = 120 }, c = { m = { { 0.00, "Глазам своим не верю!" }, { 1.60, "Я уже несколько месяцев не видел ни капли громового яблочного бренди!" }, { 6.61, "Это наверняка вызовет улыбку у солдат." }, { 9.44, "Благодарю тебя, герой!" } }, f = { { 0.00, "Глазам своим не верю!" }, { 1.66, "Я уже несколько месяцев не видел ни капли громового яблочного бренди!" }, { 6.82, "Это наверняка вызовет улыбку у солдат." }, { 9.73, "Благодарю тебя, героиня!" } } } } },
    [91740] = { d = 9.7, v = "narrator", n = { x = 110 }, c = { x = { { 0.00, "Этот мурлок наверняка уже какое-то время держал в страхе окрестные дороги." }, { 5.49, "Вы полагаете, что местной страже стоит узнать о его гибели." } } }, t = { d = 10.2, g = 1, v = "human-female#45", n = { x = 107 }, c = { m = { { 0.00, "На той неделе от лап мурлоков погибли двое наших, герой." }, { 4.15, "Надеюсь, после смерти их вожака мы наконец сможем изгнать их из Элвиннского леса." } }, f = { { 0.00, "На той неделе от лап мурлоков погибли двое наших, героиня." }, { 4.33, "Надеюсь, после смерти их вожака мы наконец сможем изгнать их из Элвиннского леса." } } } } },
    [91741] = { d = 11.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Один из кобольдов уронил эту книгу." }, { 2.96, "Похоже, он пытался её съесть." }, { 5.27, "У брата Пакстона в аббатстве есть небольшая библиотека." }, { 9.68, "Вероятно, эта книга оттуда." } } }, t = { d = 15.4, g = 1, v = "human-male", n = { m = 171, f = 172 }, c = { m = { { 0.00, "Эй, откуда у тебя это?" }, { 1.69, "Она должна стоять на полке!" }, { 3.76, "О нет, кобольды опять принялись воровать мои книги." }, { 7.52, "Наверняка пытаются их съесть!" }, { 9.59, "Спасибо, что вернул эту книгу, но как же мне быть с остатками пропавшей коллекции?" } }, f = { { 0.00, "Эй, откуда у тебя это?" }, { 1.69, "Она должна стоять на полке!" }, { 3.76, "О нет, кобольды опять принялись воровать мои книги." }, { 7.53, "Наверняка пытаются их съесть!" }, { 9.60, "Спасибо, что вернула эту книгу, но как же мне быть с остатками пропавшей коллекции?" } } } } },
    [91743] = { d = 6.3, v = "human-male", n = { x = 69 }, c = { x = { { 0.00, "Эти ужасные кобольды поедают мои книги!" }, { 3.07, "Верни их, пока всю мою библиотеку не сожрали!" } } }, t = { d = 13.9, v = "human-male", n = { x = 141 }, c = { x = { { 0.00, "Огромное тебе спасибо!" }, { 1.81, "Вот, возьми одно из этих руководств – они мне не нужны." }, { 6.13, "Но сколько же ещё книг не найдено." }, { 8.71, "Похоже, кобольды их всё-таки не едят." }, { 11.56, "Что же они с ними тогда делают?" } } } } },
    [91745] = { d = 12.6, v = "human-male", n = { x = 153 }, c = { x = { { 0.00, "Поговори с новой ученицей горного дела, Келси Фарго." }, { 3.66, "Она работает прямо рядом с рудником и наверняка видела, чем занимаются кобольды." }, { 9.16, "Заодно можешь научиться у неё основам горного дела." } } }, t = { d = 9.8, v = "human-female#112", n = { x = 109 }, c = { x = { { 0.00, "Кобольды с книгами?" }, { 1.44, "Да, я видела кобольдов, которые бегали тут с книгами и орали друг на друга." }, { 6.89, "Видимо, украли из библиотеки в аббатстве." } } } } },
    [91746] = { d = 12.3, v = "narrator", n = { x = 139 }, c = { x = { { 0.00, "Этот трофей служит впечатляющим напоминанием о вашей победе над Вязолапом." }, { 5.65, "Возможно, местный охотник или специалист по снятию шкур захочет услышать рассказ об этом." } } }, t = { d = 12.2, g = 1, v = "human-female#47", n = { m = 151, f = 152 }, c = { m = { { 0.00, "Так ты одолел Вязолапа?" }, { 1.57, "Впечатляет!" }, { 2.36, "Позволь отблагодарить тебя за трофей – я знаю пару коллекционеров, которые щедро заплатят, чтобы повесить такое над камином, когда я его подготовлю." } }, f = { { 0.00, "Так ты одолела Вязолапа?" }, { 1.62, "Впечатляет!" }, { 2.40, "Позволь отблагодарить тебя за трофей – я знаю пару коллекционеров, которые щедро заплатят, чтобы повесить такое над камином, когда я его подготовлю." } } } } },
    [91751] = { d = 12.8, v = "human-female#47", n = { x = 172 }, c = { x = { { 0.00, "Хочешь попрактиковаться в снятии шкур?" }, { 2.38, "Обычно мой муж занимается охотой на волков, но он сейчас занят в аббатстве." }, { 7.09, "Мне бы как раз пригодилась помощь с добыванием шкур, чтобы я могла выполнить имеющиеся заказы." } } }, t = { d = 4.8, g = 1, v = "human-female#47", n = { x = 42 }, c = { m = { { 0.00, "Отличные шкуры, герой." }, { 1.95, "У тебя настоящий охотничий талант." } }, f = { { 0.00, "Отличные шкуры, героиня." }, { 2.07, "У тебя настоящий охотничий талант." } } } } },
    [91752] = { d = 24.0, v = "human-female#112", n = { x = 281 }, c = { x = { { 0.00, "Время от времени тут пробегают кобольды и орут что-то типа \"Картинки для Нарфа!\" Не знаю, кто такой этот Нарф." }, { 7.59, "Может быть, важный кобольд, живущий в глубине рудника?" }, { 11.36, "У него наверняка уже целый мешок этих книг." }, { 14.45, "Добудь их и принеси нашему местному стражу закона, маршалу Макбрайду." }, { 19.26, "Только без друзей не ходи." }, { 21.12, "Кобольды в глубине рудника гораздо опаснее." } } }, t = { d = 9.7, g = 1, v = "human-male", n = { m = 108, f = 110 }, c = { m = { { 0.00, "Спасибо, что вернул украденные книги." }, { 2.72, "Я немедленно доставлю их брату Пакстону." }, { 5.63, "Ты уже так много для всех нас сделал." }, { 8.28, "Отличная работа!" } }, f = { { 0.00, "Спасибо, что вернула украденные книги." }, { 2.84, "Я немедленно доставлю их брату Пакстону." }, { 5.80, "Ты уже так много для всех нас сделала." }, { 8.57, "Отличная работа!" } } } } },
    [91753] = { d = 28.9, v = "human-female#45", n = { x = 366 }, c = { x = { { 0.00, "Академическая строгость, безусловно, необходима для ремесла зачаровывателя, но полученные на практике навыки тоже оказываются полезны." }, { 9.10, "Возьмём, к примеру, скромных кобольдов." }, { 11.76, "Не имея формального образования, они, тем не менее, демонстрируют определённые врождённые способности к использованию несложных заклинаний и чар." }, { 21.41, "Добудь несколько их восковых статуэток и разбери заключённые в них чары." }, { 26.30, "Так ты вполне можешь многому научиться." } } }, t = { d = 5.0, v = "human-female#45", n = { x = 46 }, c = { x = { { 0.00, "Теория и практика – две стороны одной медали." }, { 4.02, "Запомни это." } } } } },
    [91758] = { d = 25.4, g = 1, v = "human-male", n = { m = 322, f = 323 }, c = { m = { { 0.00, "С кобольдами ты пока не закончил." }, { 2.17, "Только что пришла весточка от Келси, что из рудника вышел кобольд, который нёс большой мешок книг." }, { 8.55, "Разыщи этого кобольда, чтобы мы могли вернуть книги брату Пакстону." }, { 13.06, "Ступай и поговори с Тордрином Мракорубом." }, { 15.75, "Он новый наставник охотников, который недавно прибыл из Стальгорна." }, { 20.15, "Найдёшь его за аббатством, у конюшни." }, { 22.55, "Он поможет тебе выследить воришку-кобольда." } }, f = { { 0.00, "С кобольдами ты пока не закончила." }, { 2.23, "Только что пришла весточка от Келси, что из рудника вышел кобольд, который нёс большой мешок книг." }, { 8.62, "Разыщи этого кобольда, чтобы мы могли вернуть книги брату Пакстону." }, { 13.13, "Ступай и поговори с Тордрином Мракорубом." }, { 15.83, "Он новый наставник охотников, который недавно прибыл из Стальгорна." }, { 20.22, "Найдёшь его за аббатством, у конюшни." }, { 22.63, "Он поможет тебе выследить воришку-кобольда." } } }, t = { d = 5.6, v = "dwarf-male", n = { x = 62 }, c = { x = { { 0.00, "Я помогу тебе выследить этого вредителя." }, { 3.07, "Дай-ка кое-что для тебя приготовлю." } } } } },
    [91772] = { d = 20.7, v = "dwarf-male", n = { x = 248 }, c = { x = { { 0.00, "Что ж." }, { 0.44, "Возьми набор для выслеживания кобольдов." }, { 3.27, "Он позволит тебе отыскать кобольда, который интересует маршала Макбрайда." }, { 8.42, "Иди по следам и принеси то, что найдёшь, маршалу Дугхану в Златоземье." }, { 13.26, "Нутром чую, эти вредители что-то затевают за пределами Североземья, так что тебе понадобится помощь Дугхана." } } }, t = { d = 13.8, v = "human-male", n = { x = 163 }, c = { x = { { 0.00, "Что это?" }, { 0.63, "Выслеживаешь кобольдов?" }, { 2.28, "Ну конечно же, они направляются на рудник Подземных Глубин!" }, { 6.45, "Там кобольдов не счесть." }, { 8.10, "Ладно, молодцом." }, { 9.30, "Надо будет найти кого-нибудь, чтобы разобрались с этой проблемой." } } } } },
    [91775] = { d = 27.8, g = 1, v = "human-male", n = { m = 333, f = 333 }, c = { m = { { 0.00, "Когда будешь исследовать рудник Подземных Глубин, постарайся найти там книги брата Пакстона." }, { 6.42, "Его особенно беспокоит судьба работы под названием \"Элементали – это весело\"." }, { 11.80, "Он полагает, что с её помощью даже кобольды смогут призвать себе слугу-элементаля." }, { 17.48, "Будь осторожен – нижние ярусы рудника довольно опасны." }, { 21.25, "Лучше захвати с собой друзей." }, { 23.35, "И возьми вот эту сумку!" }, { 25.02, "В ней найденные книги будут в безопасности." } }, f = { { 0.00, "Когда будешь исследовать рудник Подземных Глубин, постарайся найти там книги брата Пакстона." }, { 6.37, "Его особенно беспокоит судьба работы под названием \"Элементали – это весело\"." }, { 11.70, "Он полагает, что с её помощью даже кобольды смогут призвать себе слугу-элементаля." }, { 17.33, "Будь осторожна – нижние ярусы рудника довольно опасны." }, { 21.07, "Лучше захвати с собой друзей." }, { 23.15, "И возьми вот эту сумку!" }, { 24.80, "В ней найденные книги будут в безопасности." } } }, t = { d = 13.9, g = 1, v = "human-male", n = { m = 164, f = 165 }, c = { m = { { 0.00, "Ты проявил замечательную внимательность." }, { 2.74, "Брат Пакстон прислал список книг, и тебе удалось найти почти все пропавшие." }, { 7.99, "Остальные, вероятно, унесли в Яшмовую шахту." }, { 11.10, "Сумку для книг можешь оставить себе." } }, f = { { 0.00, "Ты проявила замечательную внимательность." }, { 2.88, "Брат Пакстон прислал список книг, и тебе удалось найти почти все пропавшие." }, { 8.25, "Остальные, вероятно, унесли в Яшмовую шахту." }, { 11.44, "Сумку для книг можешь оставить себе." } } } } },
    [91777] = { d = 31.9, v = "human-male", n = { x = 363 }, c = { x = { { 0.00, "В списке брата Пакстона осталось всего две пропавшие книги: \"Геомантия для юных волшебников\" и \"Чародейский справочник: магические термины простыми словами\"." }, { 11.18, "Вероятно, кобольды унесли их в Яшмовую шахту." }, { 14.46, "Прошу, разыщи эти книги и верни их брату Пакстону." }, { 18.18, "Только, боюсь, это будет весьма опасно." }, { 21.14, "Если кобольд-ученик сумел призвать элементаля, то можно лишь догадываться, на что будет способен его \"наставник\"." }, { 29.24, "Я бы на твоём месте взял с собой друзей." } } }, t = { d = 14.2, g = 1, v = "human-male", n = { m = 143, f = 146 }, c = { m = { { 0.00, "О!" }, { 0.21, "Спасибо тебе огромное!" }, { 2.07, "Ты спас мою библиотеку и оказал мне огромную услугу." }, { 6.21, "Вот, выбирай любое оружие." }, { 8.35, "Оно было предназначено для ополченцев, но тебе явно больше пригодится." } }, f = { { 0.00, "О!" }, { 0.21, "Спасибо тебе огромное!" }, { 2.08, "Ты спасла мою библиотеку и оказала мне огромную услугу." }, { 6.51, "Вот, выбирай любое оружие." }, { 8.66, "Оно было предназначено для ополченцев, но тебе явно больше пригодится." } } } } },
    [91858] = { d = 40.1, v = "scourge-female", n = { x = 410 }, c = { x = { { 0.00, "Крайне прискорбное стечение обстоятельств в Серебряном бору дало нам уникальную возможность выслужиться перед Ордой." }, { 9.59, "Два высокопоставленных лица из числа Служителей Земли пропали без вести в Серебряном бору по пути к Мельнице Таррен." }, { 19.19, "Нам об этом мало что известно, но ходят слухи, что дело попахивает настоящим дипломатическим скандалом." }, { 27.67, "Если мы найдём пропавших, это придаст нам веса и упрочит наш статус." }, { 33.32, "У нас есть в Гробнице надёжный контакт, Треван Рол." }, { 37.41, "Отправляйся туда и поговори с ним." } } }, t = { d = 8.3, g = 1, v = "scourge-male#83", n = { m = 66, f = 67 }, c = { m = { { 0.00, "Тебя прислала Данита?" }, { 1.94, "Тогда я уже знаю, зачем ты здесь." }, { 4.89, "Ну и в заварушку же ты угодил, герой." } }, f = { { 0.00, "Тебя прислала Данита?" }, { 1.98, "Тогда я уже знаю, зачем ты здесь." }, { 4.99, "Ну и в заварушку же ты угодила, героиня." } } } } },
    [91859] = { d = 42.3, v = "scourge-male#83", n = { x = 418 }, c = { x = { { 0.00, "Перейдём сразу к делу: эти \"высокопоставленные лица\" – не простые дипломаты." }, { 6.16, "Один таурен – это для Служителей Земли обычное дело." }, { 10.56, "А вот другая – хоть в такое и непросто поверить – эльфийка." }, { 15.33, "Высшая эльфийка." }, { 16.73, "Оба были в плащах, но мне доводилось видеть кель'дорай, и я готов дать мизинец на отсечение, что она как раз из них." }, { 26.04, "Зачем эльфийке сопровождать таурена на территории Орды?" }, { 30.59, "Что ж, тут нам с тобой обоим остаётся лишь гадать." }, { 34.55, "Больше я ничего не знаю, поэтому советую поговорить со стражем смерти Балдреном у входа в город." } } }, t = { d = 12.7, g = 1, v = "scourge-male", n = { m = 98, f = 99 }, c = { m = { { 0.00, "Может, я и недолюбливаю вас, паладинов, но признаю: ты появился как нельзя вовремя." }, { 8.63, "Лучше быть везучим, чем умелым, так ведь?" } }, f = { { 0.00, "Может, я и недолюбливаю вас, паладинов, но признаю: ты появилась как нельзя вовремя." }, { 8.28, "Лучше быть везучим, чем умелым, так ведь?" } } } } },
    [91860] = { d = 49.1, v = "scourge-male", n = { x = 469 }, c = { x = { { 0.00, "Вчера во время патрулирования я заметил нескольких гноллов, взваливающих чьё-то массивное тело на костёр на берегу острова Фенриса." }, { 11.09, "Ни эльфийки, ни каких-либо трупов помельче я не видел, но, думаю, это всё равно ничего доброго не сулит." }, { 20.02, "Если у тебя хватит храбрости или глупости, можешь отправиться на остров Фенриса и разузнать побольше." }, { 28.80, "На мой взгляд, это слишком уж накладно – искать какую-то высокомерную эльфийку, которая к тому же наверняка давно мертва." }, { 39.11, "Я знаю, что вы, паладины, любите приносить клятвы и браться за безнадёжные дела, но оно того не стоит, можешь поверить." } } }, t = { d = 22.2, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Перед тобой, несомненно, труп таурена, и видно, что его сильно обглодали, прежде чем бросить на костёр." }, { 7.85, "Однако никаких следов эльфийки, о которой тебе рассказывали, нет." }, { 12.88, "Может, она ещё жива где-то в глубине крепости неподалёку?" }, { 17.28, "Это будет опасно, но узнать наверняка можно лишь одним способом." } } } } },
    [91861] = { d = 13.1, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Вы нашли только одно тело, и это обнадёживает." }, { 3.63, "Возможно, высшая эльфийка, о которой говорили Треван и Хадрик, всё ещё жива и находится где-то в глубине крепости неподалёку?" } } }, t = { d = 8.8, v = "skyborne-female", n = { x = 77 }, c = { x = { { 0.00, "Ты из Отрёкшихся, верно?" }, { 2.14, "Ты можешь меня освободить?" }, { 4.60, "Боюсь, времени у меня мало." }, { 7.24, "Прошу, поторопись!" } } } } },
    [91862] = { d = 36.6, v = "skyborne-female", n = { x = 391 }, c = { x = { { 0.00, "Кель'дорай?" }, { 0.89, "Нет, я не из кель'дорай." }, { 2.66, "Меня зовут Люмина Песнь Ветра, и я шен'дорай – одна из небеснорождённых Ваятелей Ветра." }, { 9.20, "Я пришла в эти края как гостья земельников." }, { 12.54, "Мы с моим спутником Баноном шли через Серебряный бор в Нагорье Арати, чтобы исследовать там конвергенции стихий." }, { 20.98, "Увы, мы так и не смогли туда добраться." }, { 23.98, "Но сейчас не до того." }, { 25.62, "Перебей гноллов, что бродят поблизости, найди у них ключ от этой клетки и выпусти меня." }, { 32.22, "Когда мы окажемся в безопасности, я расскажу тебе остальное." } } }, t = { d = 5.0, g = 1, v = "skyborne-female", n = { x = 39 }, c = { m = { { 0.00, "Спасибо, герой." }, { 1.46, "К сожалению, опасность ещё не миновала." } }, f = { { 0.00, "Спасибо, героиня." }, { 1.65, "К сожалению, опасность ещё не миновала." } } } } },
    [91877] = { d = 30.2, v = "nightelf-male", n = { x = 305 }, c = { x = { { 0.00, "Охотников на демонов на Азероте почти не осталось, но кое-кто из нас всё ещё выслеживает самые опасные и скрытые угрозы." }, { 9.76, "Мой соратник, Маэрион Телемахес, отправился на гору Хиджал проверить слухи о демонах." }, { 16.79, "В опасной Теснине Зловещего Шёпота демонов хватает, но есть подозрение, что те демоны, что штурмовали гору в последней войне, разбиты не до конца." }, { 28.62, "Это стоит проверить." } } } },
    [91882] = { d = 39.3, v = "narrator", n = { x = 389 }, c = { x = { { 0.00, "Много лет назад Орда и Альянс забыли о распрях, чтобы сразиться с куда более страшной угрозой — Легионом." }, { 8.71, "На горе Хиджал силы Великого союза бились с Архимондом и его приспешниками, пока не остановили их." }, { 16.75, "Однако отступление с горы было опасным, и некоторые храбрые воины остались там." }, { 23.26, "Теперь, когда путь на великую гору снова открыт, может быть, кто-то из этих героев ещё жив в тех диких краях?" }, { 32.19, "Отправляйся на гору Хиджал и не убоись её опасностей." }, { 36.51, "Узнай, что стало с нашими войсками." } } } },
    [91899] = { t = { d = 14.0, v = "orc-female", n = { x = 140 }, c = { x = { { 0.00, "Благодарю за усердие." }, { 1.77, "В последнее время на торговых путях хозяйничают воры и разбойники." }, { 7.22, "Если найдёшь ещё ящики, неси их сюда – а об остальном мы позаботимся." }, { 12.83, "Вот твоя плата." } } }, npc = { [256390] = { d = 12.9, v = "human-female#47", n = { x = 140 }, c = { x = { { 0.00, "Благодарю за усердие." }, { 1.63, "В последнее время на торговых путях хозяйничают воры и разбойники." }, { 6.65, "Если найдёшь ещё ящики, неси их сюда – а об остальном мы позаботимся." }, { 11.81, "Вот твоя плата." } } } } } } },
    [91900] = { t = { d = 13.8, v = "orc-female", n = { x = 140 }, c = { x = { { 0.00, "Благодарю за усердие." }, { 1.75, "В последнее время на торговых путях хозяйничают воры и разбойники." }, { 7.14, "Если найдёшь ещё ящики, неси их сюда – а об остальном мы позаботимся." }, { 12.68, "Вот твоя плата." } } }, npc = { [256390] = { d = 13.0, v = "human-female#47", n = { x = 140 }, c = { x = { { 0.00, "Благодарю за усердие." }, { 1.63, "В последнее время на торговых путях хозяйничают воры и разбойники." }, { 6.65, "Если найдёшь ещё ящики, неси их сюда – а об остальном мы позаботимся." }, { 11.81, "Вот твоя плата." } } } } } } },
    [91901] = { t = { d = 16.1, v = "orc-female", n = { x = 161 }, c = { x = { { 0.00, "Спасибо за труды." }, { 1.47, "В последнее время развелось много бандитов и воров, которые грабят торговые караваны." }, { 8.52, "Если найдёшь где-нибудь ещё такие ящики, неси их сюда, а остальным займёмся мы." }, { 14.91, "Вот твоя плата." } } }, npc = { [256390] = { d = 14.5, v = "human-female#47", n = { x = 161 }, c = { x = { { 0.00, "Спасибо за труды." }, { 1.32, "В последнее время развелось много бандитов и воров, которые грабят торговые караваны." }, { 7.68, "Если найдёшь где-нибудь ещё такие ящики, неси их сюда, а остальным займёмся мы." }, { 13.43, "Вот твоя плата." } } } } } } },
    [91904] = { t = { d = 12.9, v = "human-female#47", n = { x = 140 }, c = { x = { { 0.00, "Благодарю за усердие." }, { 1.63, "В последнее время на торговых путях хозяйничают воры и разбойники." }, { 6.65, "Если найдёшь ещё ящики, неси их сюда – а об остальном мы позаботимся." }, { 11.81, "Вот твоя плата." } } }, npc = { [256386] = { d = 14.1, v = "orc-female", n = { x = 140 }, c = { x = { { 0.00, "Благодарю за усердие." }, { 1.78, "В последнее время на торговых путях хозяйничают воры и разбойники." }, { 7.27, "Если найдёшь ещё ящики, неси их сюда – а об остальном мы позаботимся." }, { 12.90, "Вот твоя плата." } } } } } } },
    [91905] = { t = { d = 16.8, v = "orc-female", n = { x = 177 }, c = { x = { { 0.00, "Спасибо за труды." }, { 1.41, "В последнее время развелось много разбойников и воров, которые перехватывают грузы на торговых путях." }, { 9.39, "Если найдёшь где-нибудь ещё такие ящики, приноси их сюда – остальным займёмся мы." }, { 15.68, "Вот твоя плата." } } }, npc = { [256390] = { d = 15.2, v = "human-female#47", n = { x = 177 }, c = { x = { { 0.00, "Спасибо за труды." }, { 1.28, "В последнее время развелось много разбойников и воров, которые перехватывают грузы на торговых путях." }, { 8.50, "Если найдёшь где-нибудь ещё такие ящики, приноси их сюда – остальным займёмся мы." }, { 14.19, "Вот твоя плата." } } } } } } },
    [91906] = { t = { d = 16.2, v = "orc-female", n = { x = 177 }, c = { x = { { 0.00, "Спасибо за труды." }, { 1.37, "В последнее время развелось много разбойников и воров, которые перехватывают грузы на торговых путях." }, { 9.08, "Если найдёшь где-нибудь ещё такие ящики, приноси их сюда – остальным займёмся мы." }, { 15.16, "Вот твоя плата." } } }, npc = { [256390] = { d = 15.1, v = "human-female#47", n = { x = 177 }, c = { x = { { 0.00, "Спасибо за труды." }, { 1.27, "В последнее время развелось много разбойников и воров, которые перехватывают грузы на торговых путях." }, { 8.46, "Если найдёшь где-нибудь ещё такие ящики, приноси их сюда – остальным займёмся мы." }, { 14.12, "Вот твоя плата." } } } } } } },
    [91920] = { d = 45.7, v = "scourge-male", n = { x = 462 }, c = { x = { { 0.00, "Я бы не осмелился усомниться в эффективности формул аптекаря Ренферрела, однако покривил бы душой, если бы сказал, что зелье заметно мне помогло." }, { 11.83, "На берегу озера Лордамер живёт стая мурлоков, и, что немаловажно, у них есть глаза." }, { 19.18, "Подозреваю, что готовность аптекаря пробовать что-то новое подавляется его нынешней одержимостью сердцами." }, { 27.90, "Принеси ему несколько глаз этих мурлоков." }, { 31.38, "Если мне приходится выбирать между неизбежной второй смертью и перспективой пасть от руки Ренферрела за то, что я ставлю под сомнение его профессионализм, то я выбираю последнее." } } }, t = { d = 33.2, g = 1, v = "scourge-male#82", n = { m = 280, f = 283 }, c = { m = { { 0.00, "Зелье не сработало?" }, { 1.73, "Ну конечно же не сработало." }, { 4.09, "Всё потому, что ты мне принёс слишком мало сердец." }, { 8.42, "В рецепте явно указано шесть." }, { 11.02, "А ты добыл три." }, { 12.36, "Но должен признаться, что до сих пор не задумывался об использовании органов мурлоков..." }, { 19.76, "*Ренферрел забирает у вас глаза.*" }, { 22.72, "Я могу себе позволить пожертвовать несколькими сердцами из моих запасов, чтобы вернуть тебе силу ловчего смерти." } }, f = { { 0.00, "Зелье не сработало?" }, { 1.86, "Ну конечно же не сработало." }, { 4.40, "Всё потому, что ты мне принесла слишком мало сердец." }, { 9.32, "В рецепте явно указано шесть." }, { 12.11, "А ты добыла три." }, { 13.64, "Но должен признаться, что до сих пор не задумывался об использовании органов мурлоков..." }, { 21.60, "*Ренферрел забирает у вас глаза.*" }, { 24.72, "Я могу себе позволить пожертвовать несколькими сердцами из моих запасов, чтобы вернуть тебе силу ловчего смерти." } } } } },
    [91921] = { d = 14.7, v = "scourge-male#82", n = { x = 141 }, c = { x = { { 0.00, "Вот новое зелье, которое должно помочь Квинну выздороветь." }, { 5.06, "Сделано с любовью, извлечённой из шести сердец." }, { 9.05, "А теперь прощай, а то из-за тебя у меня прибавится бумажной работы." } } }, t = { d = 13.5, g = 1, v = "scourge-male", n = { m = 76, f = 77 }, c = { m = { { 0.00, "*Квинн выпивает зелье.*" }, { 2.24, "Да, я чувствую его действие." }, { 5.46, "Вскоре я снова смогу передвигаться." }, { 9.50, "Ты оказал мне большую услугу." } }, f = { { 0.00, "*Квинн выпивает зелье.*" }, { 2.40, "Да, я чувствую его действие." }, { 5.81, "Вскоре я снова смогу передвигаться." }, { 10.08, "Ты оказала мне большую услугу." } } } } },
    [91952] = { d = 30.7, v = "tauren-female", n = { x = 299 }, c = { x = { { 0.00, "Сверху на Осквернённый лес обрушивается столько порчи!" }, { 4.42, "Когда с Хиджала идут высокие воды, они полны скверны." }, { 9.07, "Она впитывается в землю и заражает деревья и травы." }, { 13.41, "В глуши жил друид, отшельник по имени Кетарас, который хорошо знал эту гору." }, { 19.86, "Если кто и знает, что случилось на Хиджале, так это он." }, { 24.43, "Думаю, Осквернённый лес не исцелится, пока беда на Хиджале не будет устранена." } } } },
    [92020] = { d = 25.1, v = "human-female", n = { x = 295 }, c = { x = { { 0.00, "Я делаю заметки и зарисовки в своих альбомах обо всех существах, что живут в кратере Ун'Горо, а ещё у меня есть несколько копий, чтобы отправить их тем, кому это может быть интересно!" }, { 12.42, "Вот одна копия альбома – я давно хочу передать её друидам на горе Хиджал: знаю, они обожают изучать природу." }, { 19.94, "Но до Хиджала путь неблизкий." }, { 21.90, "Может, захватишь её с собой – вдруг окажешься там?" } } } },
    [92066] = { d = 40.1, v = "creature/furbolg", n = { x = 305 }, c = { x = { { 0.58, "Когда вторглись Легаши, в суматохе осталось много ценного." }, { 5.41, "Особенно дороги мне два тотема." }, { 7.97, "На них изображены легенды о наших богах-близнецах, Урсоке и Урсоле." }, { 16.51, "Я знаю, что сейчас важнее всего выжить, но мы должны подумать и о том, как сохранить историю нашего народа." }, { 27.88, "Скорее всего, эти тотемы до сих пор в нашей прежней крепости." }, { 33.01, "Если так, ты окажешь мне великую милость, вернув их." } } } },
    [92069] = { d = 43.7, v = "creature/furbolg", n = { x = 336 }, c = { x = { { 0.58, "Там, где когда-то был дом Черночревов, бродят два исполина: Костерыл Несломленный и Иссохшая Пасть, Великий Медведь." }, { 11.04, "Поколения охотников пытались их сразить, и все потерпели неудачу." }, { 20.07, "Мне не в радость просить тебя убить этих великолепных зверей, но мой народ должен вернуться домой." }, { 27.44, "Самое меньшее, что я могу сделать, — не дать их смерти стать напрасной." }, { 35.72, "Принеси мне их останки, и я смастерю оружие в память об их силе." } } } },
    [92070] = { d = 27.2, v = "narrator", n = { x = 290 }, c = { x = { { 0.00, "Ожерелье украшено всякими амулетами: обрывками перьев, скорлупками желудей и цветными камешками." }, { 7.56, "Кожаный ремешок порван." }, { 9.47, "Судя по украшениям, ожерелье принадлежало фурболгу, а по маленькому размеру и грубой работе видно, что его сделал ребёнок." }, { 19.01, "Возможно, для кого-то из Черночревов оно дорого как память." }, { 23.68, "Стоит найти владельца и вернуть ему ожерелье." } } } },
    [92109] = { d = 32.5, g = 1, v = "child-female", n = { m = 306, f = 306 }, c = { m = { { 0.00, "Э-э... привет, дяденька." }, { 2.12, "Мне вообще-то нельзя разговаривать с незнакомцами, но... ой, а что это за блестящие бутылочки торчат у тебя из сумки?" }, { 11.81, "Ты что, алхимик?" }, { 13.17, "Как здорово!" }, { 14.23, "Когда я вырасту, я тоже буду алхимиком." }, { 17.63, "Папа не разрешает мне играть с его травами." }, { 21.34, "Он говорит, это слишком опасно." }, { 24.07, "Но я хочу учиться уже сейчас." }, { 26.64, "Принесёшь мне немного алхимических припасов?" }, { 30.27, "Пожалуйста-препожалуйста!" } }, f = { { 0.00, "Э-э... привет, тётенька." }, { 2.07, "Мне вообще-то нельзя разговаривать с незнакомцами, но... ой, а что это за блестящие бутылочки торчат у тебя из сумки?" }, { 11.87, "Ты что, алхимик?" }, { 13.25, "Как здорово!" }, { 14.33, "Когда я вырасту, я тоже буду алхимиком." }, { 17.77, "Папа не разрешает мне играть с его травами." }, { 21.53, "Он говорит, это слишком опасно." }, { 24.29, "Но я хочу учиться уже сейчас." }, { 26.89, "Принесёшь мне немного алхимических припасов?" }, { 30.57, "Пожалуйста-препожалуйста!" } } }, t = { d = 11.9, g = 1, v = "child-female", n = { m = 113, f = 115 }, c = { m = { { 0.00, "Боженьки!" }, { 0.85, "Вот это да!" }, { 1.86, "Ты сам собрал эти травы?" }, { 4.03, "Спасибо большое, дяденька!" }, { 6.35, "Сейчас я попробую что-нибудь из них приготовить!" }, { 10.45, "Хочешь посмотреть?" } }, f = { { 0.00, "Боженьки!" }, { 0.81, "Вот это да!" }, { 1.77, "Ты сама собрала эти травы?" }, { 4.06, "Спасибо большое, тётенька!" }, { 6.21, "Сейчас я попробую что-нибудь из них приготовить!" }, { 10.12, "Хочешь посмотреть?" } } } } },
    [92110] = { d = 37.9, g = 1, v = "child-female", n = { m = 366, f = 368 }, c = { m = { { 0.00, "Ну и ну, моё первое зелье!" }, { 2.11, "А когда ты только начинал заниматься алхимией, ты знал, что смесь этих двух трав окрашивает зелье в ярко-красный цвет?" }, { 11.52, "Это было интересно, но мой папа не просто смешивает цветочки, а я хочу заниматься алхимией, как он!" }, { 19.54, "У него есть и другие ингредиенты." }, { 22.24, "Но я не знаю, что ещё нужно использовать, так что давай возьмём то, что первое придёт в голову!" }, { 29.68, "Хм... может, глаза мурлоков?" }, { 32.01, "Звучит мерзко, но они ведь наверняка дают какой-нибудь эффект." } }, f = { { 0.00, "Ну и ну, моё первое зелье!" }, { 2.16, "А когда ты только начинала заниматься алхимией, ты знала, что смесь этих двух трав окрашивает зелье в ярко-красный цвет?" }, { 11.97, "Это было интересно, но мой папа не просто смешивает цветочки, а я хочу заниматься алхимией, как он!" }, { 20.15, "У него есть и другие ингредиенты." }, { 22.90, "Но я не знаю, что ещё нужно использовать, так что давай возьмём то, что первое придёт в голову!" }, { 30.49, "Хм... может, глаза мурлоков?" }, { 32.87, "Звучит мерзко, но они ведь наверняка дают какой-нибудь эффект." } } }, t = { d = 47.4, g = 1, v = "child-female", n = { m = 293, f = 295 }, c = { m = { { 0.00, "Ты принёс глаза мурлоков!" }, { 2.22, "Ох, мне так не терпится изготовить первое настоящее зелье, что аж дух захватывает!" }, { 9.29, "Пока тебя не было, я тихонько выбралась наружу и собрала ещё немного трав, а ещё нашла внизу пустые флаконы." }, { 18.90, "Э-э... давай в этот раз ты смешаешь." }, { 22.08, "*Девочка с интересом наблюдает, как вы смешиваете ингредиенты, и морщит нос, когда вы добавляете глаза.*" }, { 30.17, "*Через несколько секунд отвар принимает ядовито-оранжевый оттенок.*" }, { 35.44, "Ого!" }, { 35.97, "Видишь, я была права." }, { 38.17, "Пить это я бы не стала, но если хочешь варить ещё такие зелья, вот тебе мой рецепт." }, { 46.37, "Приходи ещё!" } }, f = { { 0.00, "Ты принесла глаза мурлоков!" }, { 2.41, "Ох, мне так не терпится изготовить первое настоящее зелье, что аж дух захватывает!" }, { 9.33, "Пока тебя не было, я тихонько выбралась наружу и собрала ещё немного трав, а ещё нашла внизу пустые флаконы." }, { 18.73, "Э-э... давай в этот раз ты смешаешь." }, { 21.84, "*Девочка с интересом наблюдает, как вы смешиваете ингредиенты, и морщит нос, когда вы добавляете глаза.*" }, { 29.98, "*Через несколько секунд отвар принимает ядовито-оранжевый оттенок.*" }, { 35.28, "Ого!" }, { 35.81, "Видишь, я была права." }, { 38.00, "Пить это я бы не стала, но если хочешь варить ещё такие зелья, вот тебе мой рецепт." }, { 46.14, "Приходи ещё!" } } } } },
    [92124] = { d = 26.7, v = "human-male", n = { x = 339 }, c = { x = { { 0.00, "Нужно выяснить, сколько книг пропало!" }, { 2.52, "Ступай поговори с моим никчёмным помощником Даниэлем." }, { 6.06, "Пусть осмотрит библиотеку и выяснит, насколько серьёзна проблема." }, { 10.31, "Он просто помешан на всяких ремёслах в Элвиннском лесу и постоянно тратит время на них вместо того, чтобы заниматься своими прямыми обязанностями, – помогать мне." }, { 21.04, "Не дай ему заболтать тебя рассказами о ремёслах и выясни, что случилось с моими книгами!" } } }, t = { d = 24.4, v = "human-male", n = { x = 297 }, c = { x = { { 0.00, "Да, я уже в курсе." }, { 1.27, "Сто раз предупреждал брата Пакстона, что кобольды роют туннели под аббатством." }, { 6.47, "Похоже, они забрали много книг." }, { 8.64, "Некоторые полки опустошены полностью." }, { 11.18, "Узнай у брата Пакстона, что он хочет сделать по этому поводу." }, { 15.35, "Кстати, пока ты ещё здесь, не хочешь поговорить о ремёслах?" }, { 19.22, "Я с радостью отвечу на любые вопросы и расскажу, где найти местных наставников." } } } } },
    [92343] = { d = 37.4, v = "tauren-female", n = { x = 386 }, c = { x = { { 0.00, "Нора, о которой ты говоришь, — это туннель в Крепость Черночревов." }, { 5.32, "Раньше фурболги яростно её охраняли, и чужакам туда было не попасть." }, { 10.85, "Но теперь, когда там хозяйничают сатиры, мы сможем пробраться внутрь." }, { 16.32, "Так близко к Нордрассилу там должны расти живые корни." }, { 20.70, "Старые корни видны на поверхности, но новые можно найти лишь глубоко под землёй." }, { 27.10, "Об их магических свойствах известно немного." }, { 30.62, "Если ты принесёшь мне образцы для изучения, друиды Громового Утёса будут у тебя в долгу." } } } },
    [92344] = { d = 34.1, v = "nightelf-male", n = { x = 377 }, c = { x = { { 0.00, "Нора, о которой ты говоришь, — это туннель в Крепость Черночревов." }, { 4.95, "Раньше фурболги яростно её охраняли, и чужакам туда было не попасть." }, { 10.09, "Но теперь, когда там хозяйничают сатиры, мы сможем пробраться внутрь." }, { 15.17, "Так близко к Нордрассилу там должны расти живые корни." }, { 19.25, "Старые корни видны на поверхности, но новые можно найти лишь глубоко под землёй." }, { 25.20, "Об их магических свойствах известно немного." }, { 28.48, "Если ты принесёшь мне образцы для изучения, Круг Кенария будет у тебя в долгу." } } } },
    [92345] = { d = 28.2, g = 1, v = "nightelf-female#52", n = { m = 351, f = 352 }, c = { m = { { 0.00, "Возможно, ты заметил к северу отсюда фурболгов и сатиров, которые дерутся из-за какой-то норы." }, { 6.21, "Сама стычка интересует меня меньше, чем то, что может быть внутри." }, { 10.54, "Похоже, эта нора ведёт под Нордрассил." }, { 13.06, "Думаю, не нужно объяснять, почему это может заинтересовать калдорай." }, { 17.56, "У нас здесь и так хлопот полон рот, но друидов Дарнаса следует известить." }, { 22.25, "Найди Матренгила Медвежью Лапу в Анклаве Кенария." }, { 25.53, "Пусть он решит, стоит ли этим заниматься." } }, f = { { 0.00, "Возможно, ты заметила к северу отсюда фурболгов и сатиров, которые дерутся из-за какой-то норы." }, { 6.32, "Сама стычка интересует меня меньше, чем то, что может быть внутри." }, { 10.65, "Похоже, эта нора ведёт под Нордрассил." }, { 13.17, "Думаю, не нужно объяснять, почему это может заинтересовать калдорай." }, { 17.67, "У нас здесь и так хлопот полон рот, но друидов Дарнаса следует известить." }, { 22.36, "Найди Матренгила Медвежью Лапу в Анклаве Кенария." }, { 25.64, "Пусть он решит, стоит ли этим заниматься." } } } },
    [92346] = { d = 38.5, g = 1, v = "tauren-female", n = { m = 373, f = 374 }, c = { m = { { 0.00, "Возможно, ты заметил к северо-востоку отсюда фурболгов и сатиров, которые дерутся из-за какой-то норы." }, { 8.43, "Сама стычка меня мало волнует — куда интереснее, что внутри." }, { 13.48, "Похоже, эта нора ведёт под Мировое Древо, а кто знает, что там может быть?" }, { 19.49, "Нас здесь слишком мало, чтобы разведать самим, но я знаю одну тауренку, которая оценит подсказку." }, { 27.48, "Её зовут Нара Буйногривая, она друид в Громовом Утёсе." }, { 31.95, "Скажи ей, что тебя прислала Джедига." }, { 34.96, "Всегда полезно, когда кто-то тебе обязан." } }, f = { { 0.00, "Возможно, ты заметила к северо-востоку отсюда фурболгов и сатиров, которые дерутся из-за какой-то норы." }, { 8.57, "Сама стычка меня мало волнует — куда интереснее, что внутри." }, { 13.62, "Похоже, эта нора ведёт под Мировое Древо, а кто знает, что там может быть?" }, { 19.63, "Нас здесь слишком мало, чтобы разведать самим, но я знаю одну тауренку, которая оценит подсказку." }, { 27.62, "Её зовут Нара Буйногривая, она друид в Громовом Утёсе." }, { 32.09, "Скажи ей, что тебя прислала Джедига." }, { 35.10, "Всегда полезно, когда кто-то тебе обязан." } } } },
    [92401] = { d = 46.9, g = 1, v = "scourge-female", n = { m = 386, f = 386 }, c = { m = { { 0.00, "Мой муж Эдвард..." }, { 1.63, "Он каждую неделю ходит на кладбище в руинах Лордерона, но в этот раз он не вернулся." }, { 9.59, "Наш сын погиб, когда Артас сравнял город с землёй, и мой милый Эдвард до сих пор винит себя и убивается из-за того, что мы так и не нашли его тело." }, { 23.55, "Я пыталась отговорить его от поисков в опасных руинах, но он отказывается сдаваться." }, { 31.52, "Я стараюсь не переживать, но прошло уже несколько дней." }, { 36.74, "Мне в руинах не уцелеть, но если ты согласен помочь, то мне просто необходимо узнать о судьбе мужа." } }, f = { { 0.00, "Мой муж Эдвард..." }, { 1.66, "Он каждую неделю ходит на кладбище в руинах Лордерона, но в этот раз он не вернулся." }, { 9.78, "Наш сын погиб, когда Артас сравнял город с землёй, и мой милый Эдвард до сих пор винит себя и убивается из-за того, что мы так и не нашли его тело." }, { 24.00, "Я пыталась отговорить его от поисков в опасных руинах, но он отказывается сдаваться." }, { 32.12, "Я стараюсь не переживать, но прошло уже несколько дней." }, { 37.45, "Мне в руинах не уцелеть, но если ты согласна помочь, то мне просто необходимо узнать о судьбе мужа." } } }, t = { d = 20.8, g = 1, v = "scourge-female", n = { m = 183, f = 184 }, c = { m = { { 0.00, "Ты вовсе не обязан откликаться на мою просьбу, поэтому огромное спасибо тебе, незнакомец." }, { 8.06, "Я не могу достойно заплатить, но, надеюсь, ты примешь что-то из этого." }, { 14.35, "Надеюсь, наши пути пересекутся снова в день, не исполненный скорби." } }, f = { { 0.00, "Ты вовсе не обязана откликаться на мою просьбу, поэтому огромное спасибо тебе, незнакомка." }, { 8.34, "Я не могу достойно заплатить, но, надеюсь, ты примешь что-то из этого." }, { 14.77, "Надеюсь, наши пути пересекутся снова в день, не исполненный скорби." } } } } },
    [92415] = { d = 17.0, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Рваный и запачканный пергамент, долгое время пролежавший на кишащем нежитью кладбище, сильно повредился." }, { 7.85, "В нём говорится о пропавшем ребёнке из семейства Хартвивер." }, { 12.18, "Возможно, попечительница сирот из Штормграда что-то знает об этом." } } }, t = { d = 18.1, v = "human-female", n = { x = 194 }, c = { x = { { 0.00, "Хартвивер?" }, { 0.82, "Что-то знакомое..." }, { 2.25, "А!" }, { 2.46, "Был малютка Джереми Хартвивер." }, { 4.78, "Он попал к нам несколько лет назад после нападения на Лордерон." }, { 9.55, "Бедняжка тогда потерял обоих родителей." }, { 12.62, "К слову, его недавно усыновила очень милая женщина из Сумеречного леса." } } } } },
    [92421] = { d = 44.3, v = "scourge-male", n = { x = 408 }, c = { x = { { 0.00, "Мой долг как паладина-Отрёкшегося – исполнять волю Тёмной Госпожи и заботиться о нашем народе." }, { 8.23, "Нам повезло, ведь у нас есть возможность исполнить обе задачи разом." }, { 14.29, "Над Подгородом до сих пор в огромных количествах бродят воины Плети." }, { 20.34, "Мы пытаемся отвоевать наши земли, но постоянно теряем солдат, а разлагающуюся плоть нельзя просто зашить." }, { 29.79, "Но можно заменить." }, { 31.48, "Жаль, что наш славный капитан Гарек Бандарион больше не с нами, но я знаю, чего бы он хотел – завершить начатое и исцелить наш народ." }, { 43.35, "За Лордерон!" } } }, t = { d = 20.1, v = "scourge-male", n = { x = 181 }, c = { x = { { 0.00, "Пусть те, кто навлёк на себя гнев королевы-банши, познают, что такое правосудие!" }, { 7.34, "Благодаря этим запасным конечностям у наших братьев и сестёр появился шанс дожить до следующего утра." }, { 16.79, "Капитан Бандарион гордился бы тобой." } } } } },
    [92422] = { d = 34.4, v = "scourge-male", n = { x = 332 }, c = { x = { { 0.00, "Пришли вести с обзорной площадки озера Лордамер, расположенной глубоко в руинах Лордерона." }, { 8.23, "Улицы и кладбище окутаны зловещим туманом, что позволяет тамошней Плети действовать скрытно." }, { 15.59, "Разведчики докладывают, что армию нежити постоянно пополняет некромант по имени Рат'маэль." }, { 24.33, "Промедление смерти подобно." }, { 26.69, "Зови всех своих союзников и иди на помощь к Отрёкшимся." }, { 31.35, "Изгони это существо из наших земель." } } }, t = { d = 11.4, v = "scourge-male", n = { x = 94 }, c = { x = { { 0.00, "Не сомневаюсь, что подобному чудищу найдётся замена, но надеюсь, что врагов хотя бы на время станет меньше." }, { 10.63, "Спасибо." } } } } },
    [92432] = { d = 31.6, v = "human-male", n = { x = 376 }, c = { x = { { 0.00, "У меня дурные вести из Даларана." }, { 2.29, "Что-то нарушило течение энергии в силовых линиях, и механизмы в городе стали вести себя непредсказуемо и агрессивно." }, { 10.33, "Мы пока не знаем, в чём заключается первопричина случившегося." }, { 14.54, "Верховный совет приказал нам держать всё в тайне, чтобы не навлечь на орден позор." }, { 20.23, "Но мы не сможем вечно обманывать народ." }, { 22.95, "Город в опасности!" }, { 24.25, "Верховный маг Модера отправила меня за помощью." }, { 27.24, "Отыщи её чародейский образ на озере Лордамер у Даларана." } } }, t = { d = 14.2, v = "human-female", n = { x = 172 }, c = { x = { { 0.00, "Вижу, Жаку удалось найти помощь." }, { 2.35, "Хоть это и не вполне дозволено, в столь отчаянный час гордость не должна заставлять нас отвергать союзников." }, { 9.66, "И пусть стража тебя не обманывает." }, { 12.01, "Ситуация совсем не под контролем." } } } } },
    [92434] = { d = 27.5, g = 1, v = "scourge-male#82", n = { m = 293, f = 293 }, c = { m = { { 0.00, "После падения барьера в Даларане началась паника." }, { 3.92, "Раз тебе удалось разобраться с патрулями, лучшего случая, чтобы пробраться туда и выкрасть все тайны, не найти." }, { 12.61, "Возьми ключ, который ты нашёл в лагере, и отыщи канализацию, проходящую по северной границе города." }, { 20.24, "Понадеемся, что никто из магов не додумался наложить защитные чары на столь... неприглядный вход." } }, f = { { 0.00, "После падения барьера в Даларане началась паника." }, { 3.78, "Раз тебе удалось разобраться с патрулями, лучшего случая, чтобы пробраться туда и выкрасть все тайны, не найти." }, { 12.14, "Возьми ключ, который ты нашла в лагере, и отыщи канализацию, проходящую по северной границе города." }, { 19.56, "Понадеемся, что никто из магов не додумался наложить защитные чары на столь... неприглядный вход." } } }, t = { d = 10.3, v = "human-female", n = { x = 122 }, c = { x = { { 0.00, "Вряд ли Орда случайно заинтересовалась моим городом в столь шаткое время." }, { 5.14, "По правде говоря, я на это и рассчитывала." }, { 8.12, "У меня есть для тебя предложение." } } } } },
    [92454] = { d = 29.1, v = "narrator", n = { x = 319 }, c = { x = { { 0.00, "Добро пожаловать в мир Ворлд оф Варкрафт!" }, { 3.19, "В знак особой благодарности за приобретение коллекционного издания вы получаете подарок!" }, { 9.99, "Передайте этот подарочный сертификат Далии Свежий Ветер в Тендалской роще." }, { 15.95, "Взамен вы получите маленького спутника, который будет сопровождать вас на пути к славе." }, { 22.82, "Ещё раз благодарим вас и желаем приятного времяпровождения в мире Ворлд оф Варкрафт!" } } } },
    [92456] = { d = 30.1, g = 1, v = "nightelf-female", n = { m = 381, f = 382 }, c = { m = { { 0.00, "Раз уж ты решил мне докучать, пусть от тебя будет хоть какая-то польза." }, { 4.52, "У меня есть одно дело." }, { 6.02, "Хотя Даларан город магов, его жители проявляют неожиданный интерес к ботанике." }, { 11.17, "Кирин-Тор не привечает посторонних, но мне бы очень хотелось получить образец их растений, насыщенных маной." }, { 18.06, "Ты явно чувствуешь себя в своей тарелке там, где тебе не рады." }, { 22.11, "Может быть, тебе удастся пробраться в город." }, { 25.01, "Если сумеешь это сделать, принеси мне что-нибудь из тамошнего центрального сада." } }, f = { { 0.00, "Раз уж ты решила мне докучать, пусть от тебя будет хоть какая-то польза." }, { 4.46, "У меня есть одно дело." }, { 5.92, "Хотя Даларан город магов, его жители проявляют неожиданный интерес к ботанике." }, { 10.94, "Кирин-Тор не привечает посторонних, но мне бы очень хотелось получить образец их растений, насыщенных маной." }, { 17.65, "Ты явно чувствуешь себя в своей тарелке там, где тебе не рады." }, { 21.60, "Может быть, тебе удастся пробраться в город." }, { 24.42, "Если сумеешь это сделать, принеси мне что-нибудь из тамошнего центрального сада." } } }, t = { d = 17.0, v = "nightelf-female", n = { x = 189 }, c = { x = { { 0.00, "Это... не совсем то, на что я рассчитывала." }, { 3.03, "Очевидно, то, что происходит сейчас в городе, гораздо серьёзнее, чем я ожидала." }, { 8.58, "Но твоя находка от этого становится ещё более интересной!" }, { 12.72, "Видимо, проблем с тобой будет меньше, чем я думала." }, { 16.46, "Молодец." } } } } },
    [92457] = { d = 26.2, v = "human-female", n = { x = 328 }, c = { x = { { 0.00, "Катастрофа отразилась на многих наших слугах-автоматах и чарах по всему городу – включая те, что отвечают за его оборону." }, { 8.26, "Выброс фрагментов чародейской энергии привлёк диких элементалей, которые жаждут поглотить необузданную магию." }, { 15.72, "Мы здесь заняты укреплением защитных чар и другими серьёзными проблемами, так что ты окажешь Кирин-Тору огромную услугу, если проредишь эту толпу элементалей." } } }, t = { d = 4.4, v = "human-female", n = { x = 44 }, c = { x = { { 0.00, "Спасибо." }, { 0.79, "Мы ценим твой вклад в безопасность Даларана." } } } } },
    [92458] = { d = 39.4, v = "human-female", n = { x = 479 }, c = { x = { { 0.00, "Что бы ни послужило причиной сбоя в силовых линиях, началось это на самом верху Аметистовой цитадели." }, { 7.43, "Оттуда донёсся оглушительный грохот, а затем нас захлестнула волна необузданной чародейской энергии." }, { 14.16, "Все наши силы уходят исключительно на поддержание защитных чар." }, { 18.44, "Мы больше не можем медлить." }, { 20.34, "Нам нужна помощь." }, { 21.56, "Маги Кирин-Тора занимаются наведением порядка в самой цитадели, но тебе придётся найти менее заметный способ туда проникнуть." }, { 30.12, "Возьми этот ключ и сразу же направляйся в цитадель, когда проберёшься в город." }, { 35.38, "Я буду ждать тебя там." }, { 36.91, "Мы должны положить конец этому хаосу." } } }, t = { d = 15.8, g = 1, v = "human-female", n = { m = 165, f = 167 }, c = { m = { { 0.00, "Не знаю, что ты видел наверху, но это не так и важно." }, { 3.94, "Важно сейчас лишь обуздать энергию этой частицы и положить конец творящемуся безумию." }, { 10.29, "Ты отлично справился с порученным заданием." }, { 13.50, "Теперь дело за нами." } }, f = { { 0.00, "Не знаю, что ты видела наверху, но это не так и важно." }, { 4.15, "Важно сейчас лишь обуздать энергию этой частицы и положить конец творящемуся безумию." }, { 10.50, "Ты отлично справилась с порученным заданием." }, { 14.37, "Теперь дело за нами." } } } } },
    [92459] = { d = 19.1, v = "human-female", n = { x = 230 }, c = { x = { { 0.00, "Члены совета не одобрят наших уловок, но им придётся признать результаты." }, { 5.12, "Город постепенно успокаивается, и теперь мы можем убрать обереги." }, { 9.73, "Думаю, будет справедливо, если именно ты принесёшь хорошие новости." }, { 14.46, "Отнеси эту частицу верховному магу Селиндре в Аметистовую цитадель." } } }, t = { d = 22.0, g = 1, v = "human-female", n = { m = 139, f = 139 }, c = { m = { { 0.00, "Где ты нашёл это?" }, { 1.57, "В гостиной?" }, { 2.56, "*По лицу верховного мага Селиндры на мгновение пробегает тень, но она быстро приходит в себя.*" }, { 9.76, "Думаю, лучше тебе об этом забыть, друг." }, { 12.77, "Пока же Кирин-Тор приветствует тебя." }, { 15.51, "Герой, знающий своё дело, может нам пригодиться." }, { 19.12, "Добро пожаловать в Даларан." } }, f = { { 0.00, "Где ты нашла это?" }, { 1.70, "В гостиной?" }, { 2.72, "*По лицу верховного мага Селиндры на мгновение пробегает тень, но она быстро приходит в себя.*" }, { 10.24, "Думаю, лучше тебе об этом забыть, друг." }, { 13.34, "Пока же Кирин-Тор приветствует тебя." }, { 16.16, "Героиня, знающая своё дело, может нам пригодиться." }, { 20.01, "Добро пожаловать в Даларан." } } } } },
    [92460] = { d = 32.2, g = 1, v = "skyborne-female#3773", n = { m = 310, f = 310 }, c = { m = { { 0.00, "А вот и ты!" }, { 0.87, "Без сомнения, полон энтузиазма и готов к приключениям!" }, { 5.22, "Мы ждали твоего прибытия в деревню Тендал и надеемся на твою помощь." }, { 10.80, "Наверняка ты весь дрожишь от предвкушения." }, { 14.14, "В конце концов, совершеннолетие бывает лишь раз в жизни." }, { 18.56, "*Айлия по-доброму улыбается.*" }, { 21.28, "Ступай, найди предводителя нашей деревни Рориана Искателя Утра на пути к старому дереву." }, { 28.05, "Это к западу отсюда." }, { 29.68, "Он поможет тебе начать путешествие." } }, f = { { 0.00, "А вот и ты!" }, { 0.85, "Без сомнения, полна энтузиазма и готова к приключениям!" }, { 5.20, "Мы ждали твоего прибытия в деревню Тендал и надеемся на твою помощь." }, { 10.69, "Наверняка ты вся дрожишь от предвкушения." }, { 13.89, "В конце концов, совершеннолетие бывает лишь раз в жизни." }, { 18.24, "*Айлия по-доброму улыбается.*" }, { 20.96, "Ступай, найди предводителя нашей деревни Рориана Искателя Утра на пути к старому дереву." }, { 27.83, "Это к западу отсюда." }, { 29.48, "Он поможет тебе начать путешествие." } } }, t = { d = 36.5, g = 1, v = "skyborne-male", n = { m = 382, f = 383 }, c = { m = { { 0.00, "Приветствую!" }, { 0.99, "Для меня честь вручить тебе эту реликвию к совершеннолетию." }, { 5.64, "В тебе скрыт огромный потенциал, который послужит шен'дорай." }, { 10.36, "У нашего народа сложная история, и мы пережили много горя и гонений." }, { 15.78, "Сегодня в твои руки переходит одна из реликвий, когда-то принадлежавших твоим предшественникам." }, { 23.25, "Однажды, когда твой прах будет развеян, её получит кто-то ещё, и традиция будет продолжена." }, { 30.36, "Держи её и помни: ветер из дома всегда будет с тобой, где бы ты ни странствовал." } }, f = { { 0.00, "Приветствую!" }, { 0.97, "Для меня честь вручить тебе эту реликвию к совершеннолетию." }, { 5.54, "В тебе скрыт огромный потенциал, который послужит шен'дорай." }, { 10.18, "У нашего народа сложная история, и мы пережили много горя и гонений." }, { 15.51, "Сегодня в твои руки переходит одна из реликвий, когда-то принадлежавших твоим предшественникам." }, { 22.85, "Однажды, когда твой прах будет развеян, её получит кто-то ещё, и традиция будет продолжена." }, { 29.84, "Держи её и помни: ветер из дома всегда будет с тобой, где бы ты ни странствовала." } } } } },
    [92461] = { d = 25.4, v = "skyborne-male", n = { x = 284 }, c = { x = { { 0.00, "Мы живём во времена великой неопределённости, часто требующей от нас смелых решений." }, { 6.22, "Но бывают и повседневные проблемы." }, { 8.82, "Вот, к примеру, популяция лисвенов слишком разрослась." }, { 12.93, "Они неотъемлемая часть нашей экосистемы." }, { 16.00, "Но когда лисвены угрожают хрупкому равновесию в Тендалской роще, мы должны вмешаться." }, { 22.50, "Ступай на восток и убей часть лисвенов." } } }, t = { d = 16.8, g = 1, v = "skyborne-male", n = { x = 168 }, c = { m = { { 0.00, "Спасибо за помощь Зефрису, герой." }, { 2.58, "Обычно лисвены смирные, но все звери на Зефрисе чуют, когда магия ветров выходит из равновесия." }, { 9.86, "И если ничего с этим не делать, они могут начать вести себя опасно и непредсказуемо." } }, f = { { 0.00, "Спасибо за помощь Зефрису, героиня." }, { 2.79, "Обычно лисвены смирные, но все звери на Зефрисе чуют, когда магия ветров выходит из равновесия." }, { 10.25, "И если ничего с этим не делать, они могут начать вести себя опасно и непредсказуемо." } } } } },
    [92462] = { d = 18.6, v = "skyborne-male", n = { x = 202 }, c = { x = { { 0.00, "Один из наших следопытов недавно сообщил, что в Тендалской роще развелось много щетинистых ос." }, { 7.08, "Если дать рою слишком разрастись, он может стать опасным, так что, пожалуйста, ступай в восточную часть рощи и уничтожь как можно больше щетинистых ос." } } }, t = { d = 6.3, g = 1, v = "skyborne-male", n = { m = 68, f = 69 }, c = { m = { { 0.00, "Судя по тому, что ты с ног до головы покрыт кусками насекомых, ос и правда было немало." } }, f = { { 0.00, "Судя по тому, что ты с ног до головы покрыта кусками насекомых, ос и правда было немало." } } } } },
    [92463] = { d = 21.9, g = 1, v = "skyborne-male", n = { m = 239, f = 239 }, c = { m = { { 0.00, "Если этих насекомых в лесу и правда так много, то убить рабочих недостаточно." }, { 5.83, "Зайди глубже в лес и отыщи матку." }, { 8.37, "Она должна быть недалеко от улья и в окружении крупных и агрессивных защитников, так что будь осторожен." }, { 16.01, "Избавься от матки и возвращайся сюда." }, { 18.83, "Так у нас станет на одну проблему меньше." } }, f = { { 0.00, "Если этих насекомых в лесу и правда так много, то убить рабочих недостаточно." }, { 5.87, "Зайди глубже в лес и отыщи матку." }, { 8.44, "Она должна быть недалеко от улья и в окружении крупных и агрессивных защитников, так что будь осторожна." }, { 16.13, "Избавься от матки и возвращайся сюда." }, { 18.96, "Так у нас станет на одну проблему меньше." } } }, t = { d = 7.6, v = "skyborne-male", n = { x = 79 }, c = { x = { { 0.00, "Чудесно." }, { 0.74, "Если с искательством приключений дело не выгорит, из тебя выйдет прекрасный следопыт." } } } } },
    [92464] = { d = 30.3, v = "skyborne-male", n = { x = 321 }, c = { x = { { 0.00, "С тех пор как наши благодетели из мира стихий оставили нас, мы не знаем покоя." }, { 5.98, "Вот и теперь – разбушевались порождения ветра, что обитают у камней к северо-востоку." }, { 12.52, "Они не обладают истинным разумом, как духи ветра, жившие здесь прежде, но реагируют на эмоции и намерения существ вокруг." }, { 21.91, "Моя ученица Яла Загонщица Ветров отправилась понаблюдать за ними." }, { 27.06, "Отыщи её и выясни, что ей удалось разузнать." } } }, t = { d = 5.1, v = "skyborne-female", n = { x = 50 }, c = { x = { { 0.00, "Тебя прислал Рориан?" }, { 1.86, "Прекрасно." }, { 2.79, "Мне понадобится твоя помощь." } } } } },
    [92465] = { d = 22.1, g = 1, v = "skyborne-female", n = { x = 216 }, c = { m = { { 0.00, "Секта Ал'акет – настоящее проклятие этого острова." }, { 4.18, "Наверняка именно сектанты разозлили духов ветра, живущих здесь." }, { 9.39, "К сожалению, нам придётся угомонить ревущие ветра, пока кто-нибудь не пострадал." }, { 15.85, "А ещё надо дать сектантам ясно понять: в роще им не рады." }, { 20.55, "Поможешь нам, герой?" } }, f = { { 0.00, "Секта Ал'акет – настоящее проклятие этого острова." }, { 4.16, "Наверняка именно сектанты разозлили духов ветра, живущих здесь." }, { 9.33, "К сожалению, нам придётся угомонить ревущие ветра, пока кто-нибудь не пострадал." }, { 15.75, "А ещё надо дать сектантам ясно понять: в роще им не рады." }, { 20.41, "Поможешь нам, героиня?" } } }, t = { d = 6.6, v = "skyborne-female", n = { x = 67 }, c = { x = { { 0.00, "Мне больно проливать в роще кровь шен'дорай, но мы должны делать то, что необходимо." } } } } },
    [92466] = { d = 29.3, v = "skyborne-male", n = { x = 330 }, c = { x = { { 0.00, "Хотя мы во многом процветаем благодаря стихии ветра, наш путь требует, чтобы мы слушали зов всех четырёх стихий и проходили испытания каждой." }, { 10.39, "Но прежде чем ты по-настоящему приступишь к первому испытанию, надо проверить твою решимость." }, { 17.29, "Ступай к стоячим камням на востоке." }, { 19.98, "Там обнаружили ал'акетских новообращённых, и с ними надо разобраться." }, { 25.00, "Вступи в бой с сектантами и принеси мне один из их перстней." } } }, t = { d = 9.4, g = 1, v = "skyborne-male", n = { m = 86, f = 90 }, c = { m = { { 0.00, "Ты вернулся и принёс то, что нужно." }, { 3.07, "Твоя стойкость и твоё упорство несомненны." }, { 6.86, "Ты готов к следующему этапу." } }, f = { { 0.00, "Ты вернулась и принесла то, что нужно." }, { 3.30, "Твоя стойкость и твоё упорство несомненны." }, { 7.00, "Ты готова к следующему этапу." } } } } },
    [92467] = { d = 31.6, g = 1, v = "skyborne-male", n = { m = 307, f = 307 }, c = { m = { { 0.00, "Сапта – это напиток, который связывает душу со стихией." }, { 4.71, "Насыщенное магией зелье позволяет тем, кто силён духом, видеть незримое." }, { 10.68, "Твой дух будет связан с той стихией, для которой сварили сапту." }, { 15.91, "Лишь немногие шаманы знают её рецепт." }, { 19.05, "И запомни: сапту можно пить лишь в священном месте и нигде более!" }, { 24.51, "Отыщи Вершину Духов к северо-востоку отсюда." }, { 28.32, "Выпей там сапту и увидишь то, что должен!" } }, f = { { 0.00, "Сапта – это напиток, который связывает душу со стихией." }, { 4.68, "Насыщенное магией зелье позволяет тем, кто силён духом, видеть незримое." }, { 10.63, "Твой дух будет связан с той стихией, для которой сварили сапту." }, { 15.83, "Лишь немногие шаманы знают её рецепт." }, { 18.96, "И запомни: сапту можно пить лишь в священном месте и нигде более!" }, { 24.38, "Отыщи Вершину Духов к северо-востоку отсюда." }, { 28.17, "Выпей там сапту и увидишь то, что должна!" } } }, t = { d = 42.9, g = 1, v = "elemental-earth", n = { m = 341, f = 341 }, c = { m = { { 0.00, "А..." }, { 0.44, "Путник... дитя четырёх ветров..." }, { 3.62, "Ты жаждешь понимания." }, { 5.73, "Жаждешь ответов." }, { 7.41, "Почему ветра оставили вас?" }, { 10.06, "Как их вернуть?" }, { 11.56, "Ответов на эти вопросы у меня нет, так как действия и мотивы ветров от меня скрыты." }, { 19.76, "Зато я могу научить тебя пути земли." }, { 23.55, "Её силе и твёрдости." }, { 25.49, "Даже здесь, высоко в море облаков, ты всё равно остаёшься земным творением." }, { 32.82, "Если надеешься найти силы, чтобы вновь говорить с духами четырёх ветров, ты должен ступить на этот путь." } }, f = { { 0.00, "А..." }, { 0.43, "Путница... дитя четырёх ветров..." }, { 3.65, "Ты жаждешь понимания." }, { 5.73, "Жаждешь ответов." }, { 7.39, "Почему ветра оставили вас?" }, { 9.99, "Как их вернуть?" }, { 11.47, "Ответов на эти вопросы у меня нет, так как действия и мотивы ветров от меня скрыты." }, { 19.55, "Зато я могу научить тебя пути земли." }, { 23.29, "Её силе и твёрдости." }, { 25.20, "Даже здесь, высоко в море облаков, ты всё равно остаёшься земным творением." }, { 32.41, "Если надеешься найти силы, чтобы вновь говорить с духами четырёх ветров, ты должна ступить на этот путь." } } } } },
    [92468] = { d = 46.5, g = 1, v = "elemental-earth", n = { m = 384, f = 385 }, c = { m = { { 0.00, "Возьми этот необработанный кварц и отнеси его тому, кого зовёшь Ваятель ветра Боро, в доказательство того, что мы с тобой встречались." }, { 13.05, "Он изготовит для тебя тотем, и этот фрагмент будет его сердцем." }, { 19.35, "Он невелик, но со временем ты поймёшь, что размер не имеет значения." }, { 25.83, "Иногда малое оказывается долговечнее большого." }, { 30.39, "Будь терпелив." }, { 31.79, "Оставайся сильным." }, { 33.63, "И ищи мудрости." }, { 35.21, "Этого от тебя требуют стихии." }, { 38.18, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } }, f = { { 0.00, "Возьми этот необработанный кварц и отнеси его тому, кого зовёшь Ваятель ветра Боро, в доказательство того, что мы с тобой встречались." }, { 13.11, "Он изготовит для тебя тотем, и этот фрагмент будет его сердцем." }, { 19.45, "Он невелик, но со временем ты поймёшь, что размер не имеет значения." }, { 25.96, "Иногда малое оказывается долговечнее большого." }, { 30.54, "Будь терпелива." }, { 32.04, "Оставайся сильной." }, { 33.89, "И ищи мудрости." }, { 35.47, "Этого от тебя требуют стихии." }, { 38.46, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } } }, t = { d = 27.0, g = 1, v = "skyborne-male", n = { m = 289, f = 290 }, c = { m = { { 0.00, "Чудесно!" }, { 0.69, "Тотем, который я создам для тебя, – не просто символ нового статуса." }, { 6.03, "Он обладает тайными возможностями." }, { 8.67, "Его можно использовать для сосредоточения заклинаний Земли." }, { 13.25, "Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно." }, { 19.70, "Наставники скажут тебе, когда ты будешь готов к новым знаниям." }, { 24.62, "А пока возьми этот тотем Земли." } }, f = { { 0.00, "Чудесно!" }, { 0.68, "Тотем, который я создам для тебя, – не просто символ нового статуса." }, { 5.93, "Он обладает тайными возможностями." }, { 8.52, "Его можно использовать для сосредоточения заклинаний Земли." }, { 13.02, "Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно." }, { 19.36, "Наставники скажут тебе, когда ты будешь готова к новым знаниям." }, { 24.27, "А пока возьми этот тотем Земли." } } } } },
    [92469] = { d = 13.0, g = 1, v = "skyborne-female", n = { m = 129, f = 130 }, c = { m = { { 0.00, "На сегодня ты сделал достаточно, герой." }, { 3.13, "Я останусь здесь и добью остальных." }, { 5.91, "Иди в деревню и расскажи Рориану о том, что тут появились сектанты." }, { 11.18, "Он точно не обрадуется." } }, f = { { 0.00, "На сегодня ты сделала достаточно, героиня." }, { 3.29, "Я останусь здесь и добью остальных." }, { 6.02, "Иди в деревню и расскажи Рориану о том, что тут появились сектанты." }, { 11.21, "Он точно не обрадуется." } } }, t = { d = 21.5, g = 1, v = "skyborne-male", n = { m = 207, f = 208 }, c = { m = { { 0.00, "Вести мрачные, но, увы, ожидаемые." }, { 2.89, "Мы уже давно знали о действиях сектантов, но лишь наблюдали за ними издалека." }, { 9.27, "Однако то, что они разгневали духов ветра у стоячих камней, – это уже слишком." }, { 15.80, "Ты оказал Тендалской роще тяжёлую, но необходимую услугу." }, { 20.96, "Благодарю." } }, f = { { 0.00, "Вести мрачные, но, увы, ожидаемые." }, { 2.91, "Мы уже давно знали о действиях сектантов, но лишь наблюдали за ними издалека." }, { 9.34, "Однако то, что они разгневали духов ветра у стоячих камней, – это уже слишком." }, { 15.99, "Ты оказала Тендалской роще тяжёлую, но необходимую услугу." }, { 20.78, "Благодарю." } } } } },
    [92470] = { d = 24.9, v = "skyborne-female#3773", n = { x = 255 }, c = { x = { { 0.00, "Рориан наверняка сказал, что я за тобой наблюдаю." }, { 3.92, "Теперь же я предлагаю тебе проверку на твёрдость." }, { 7.77, "Только имей в виду, дело предстоит опасное." }, { 11.34, "Прореди стаю медвер и отыщи их матриарха." }, { 14.69, "Следопыты зовут её Урс'ана." }, { 16.90, "Расправься с ней и принеси мне доказательство того, что она мертва." }, { 22.18, "Это будет важный шаг на твоём пути." } } }, t = { d = 12.9, g = 1, v = "skyborne-female#3773", n = { m = 134, f = 135 }, c = { m = { { 0.00, "Замечательно." }, { 1.10, "Ты одолел диких зверей и бесчестных сектантов." }, { 4.93, "Что-то в тебе определённо есть, но скоро путь уведёт тебя из относительно безопасной деревни Тендал." } }, f = { { 0.00, "Замечательно." }, { 1.10, "Ты одолела диких зверей и бесчестных сектантов." }, { 5.01, "Что-то в тебе определённо есть, но скоро путь уведёт тебя из относительно безопасной деревни Тендал." } } } } },
    [92471] = { d = 31.1, g = 1, v = "skyborne-male", n = { m = 330, f = 332 }, c = { m = { { 0.00, "Возможно, ты не догадывался, но всё, что ты делал, было своего рода испытанием, чтобы подготовить тебя к тому, что грядёт." }, { 9.17, "Зефрис – большой остров, и чтобы наш народ пережил все невзгоды, нужны отважные молодые искатели приключений." }, { 17.52, "Такие, как ты." }, { 18.61, "Одна из наших предводительниц на острове Зефрис – Эфин Штормовая, и она внимательно следила за тобой." }, { 26.34, "У неё есть для тебя задание." }, { 28.46, "Поговори с ней, чтобы узнать больше." } }, f = { { 0.00, "Возможно, ты не догадывалась, но всё, что ты делала, было своего рода испытанием, чтобы подготовить тебя к тому, что грядёт." }, { 9.26, "Зефрис – большой остров, и чтобы наш народ пережил все невзгоды, нужны отважные молодые искатели приключений." }, { 17.58, "Такие, как ты." }, { 18.67, "Одна из наших предводительниц на острове Зефрис – Эфин Штормовая, и она внимательно следила за тобой." }, { 26.36, "У неё есть для тебя задание." }, { 28.48, "Поговори с ней, чтобы узнать больше." } } }, t = { d = 23.1, g = 1, v = "skyborne-female#3773", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Рориан много рассказывал о тебе." }, { 2.62, "Ты, скорее всего, меня не знаешь, но я принадлежу к Совету старейшин острова Зефрис." }, { 9.27, "Я читаю потоки ветра в Тендалской роще, а ещё оцениваю молодых шен'дорай вроде тебя, готовых стать взрослыми." }, { 17.90, "Скажи, готов ли ты сделать следующий шаг и послужить острову Зефрис?" } }, f = { { 0.00, "Рориан много рассказывал о тебе." }, { 2.58, "Ты, скорее всего, меня не знаешь, но я принадлежу к Совету старейшин острова Зефрис." }, { 9.14, "Я читаю потоки ветра в Тендалской роще, а ещё оцениваю молодых шен'дорай вроде тебя, готовых стать взрослыми." }, { 17.66, "Скажи, готова ли ты сделать следующий шаг и послужить острову Зефрис?" } } } } },
    [92472] = { d = 34.4, v = "skyborne-female#3773", n = { x = 342 }, c = { x = { { 0.00, "Одна из самых давних угроз острову Зефрис – секта Ал'акет." }, { 4.85, "Это религиозные фанатики, преданные Ал'акиру Владыке Ветра, который якобы должен править Небесной высью." }, { 13.40, "Они жестоки и упрямы, а их сила и амбиции становятся всё опаснее с каждым днём." }, { 19.78, "Скоро ты отправишься в деревню Шен'дар к югу отсюда." }, { 24.05, "Поговори с констеблем Аондой, когда прибудешь туда." }, { 28.51, "Секта угрожает Шен'дару, и деревне нужна помощь." }, { 32.49, "Скажи Аонде, что ты от меня." } } }, t = { d = 15.9, v = "skyborne-female", n = { x = 166 }, c = { x = { { 0.00, "Тебя, значит, прислала Эфин?" }, { 2.32, "Скажу честно: на мой взгляд, толку от тебя будет немного, но деревня Шен'дар не станет отказываться от добровольных помощников." }, { 12.14, "Тем более, если их прислала сама старейшина Эфин." } } } } },
    [92473] = { d = 33.3, v = "skyborne-female#3773", n = { x = 377 }, c = { x = { { 0.00, "От логова медвер на юго-западе всё больше проблем." }, { 3.76, "Буквально на той неделе следопытам пришлось прикончить молодую медверу, которая подошла слишком близко к деревне и напала на мальчишку, игравшего под старым деревом в центре поселения." }, { 17.21, "Нам повезло, что ему удалось сбежать целым и невредимым." }, { 21.36, "Эти звери от голода и отчаяния становятся слишком опасными." }, { 25.78, "Ступай на юг и убей самых слабых медвер." }, { 28.81, "Принеси мне их когти как доказательство того, что дело сделано." } } }, t = { d = 4.8, g = 1, v = "skyborne-female#3773", n = { x = 32 }, c = { m = { { 0.00, "Молодцом, герой." }, { 1.75, "Следопыты Рощи у тебя в долгу." } }, f = { { 0.00, "Молодцом, героиня." }, { 1.68, "Следопыты Рощи у тебя в долгу." } } } } },
    [92474] = { d = 29.7, v = "skyborne-female#3773", n = { x = 325 }, c = { x = { { 0.00, "Ну привет!" }, { 0.79, "Хочешь сыграть в одну игру?" }, { 2.90, "Тебе всего-то надо подойти вон к тому краю... и спрыгнуть." }, { 7.26, "Используй свою способность к левитации и посмотри, как далеко улетишь." }, { 12.41, "Правила выдуманы только что, награды никакой нет, но ты получишь дополнительные очки, если приземлишься прямо перед Рорианом Искателем Утра и напугаешь его!" }, { 23.89, "Ему это, конечно, не понравится, но я посмеюсь от души, если он разорётся!" }, { 29.30, "Ха-ха!" } } }, t = { d = 25.1, v = "skyborne-male", n = { x = 304 }, c = { x = { { 0.00, "Да сколько раз мне говорить Мириаал, чтобы не подбивала других применять наши врождённые способности для всякой ерунды?" }, { 8.36, "Впрочем, небольшая тренировка в относительно безопасной деревне может быть... полезной." }, { 14.48, "Но в будущем советую применять способности осмотрительно." }, { 18.50, "Израсходуешь магию, а потом не сможешь воспользоваться ей, когда она будет действительно нужна." } } } } },
    [92479] = { d = 15.3, v = "human-male", n = { x = 206 }, c = { x = { { 0.00, "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.33, "Похоже, на нём стоит печать Тордрина Мракоруба, местного наставника охотников." }, { 10.20, "Прочти, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." } } }, t = { d = 20.8, v = "dwarf-male", n = { x = 238 }, c = { x = { { 0.00, "Разберись в обстановке, изучи местность и возвращайся, как только тебе потребуется обучение." }, { 6.57, "Я тут в любое время дня и ночи." }, { 8.83, "Эти места становятся всё опаснее, и если ты поговоришь с местными, то, думаю, заметишь, что у всех найдутся проблемы, с которыми без помощи охотника не разобраться." }, { 20.43, "Удачи!" } } } } },
    [92480] = { d = 18.7, v = "narrator", n = { x = 201 }, c = { x = { { 0.00, "У убитого тобой культиста при себе оказались, судя по всему, приказы верховной жрицы Культа Ал'акира." }, { 7.82, "В них упоминается шпион в деревне Шен'дар и действия культа в месте под названием деревня Фалаат." }, { 15.23, "Власти деревни Шен'дар захотят об этом узнать." } } } },
    [92481] = { d = 17.4, g = 1, v = "skyborne-male", n = { m = 196, f = 197 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, наша наставница магов Дорийя Громкий Шёпот оставила тебе этот кристалл возвращения." }, { 8.51, "На нём записано какое-то послание, так что обязательно взгляни." }, { 13.06, "А потом сможешь найти Дорийю в строении у меня за спиной." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, наша наставница магов Дорийя Громкий Шёпот оставила тебе этот кристалл возвращения." }, { 8.62, "На нём записано какое-то послание, так что обязательно взгляни." }, { 13.20, "А потом сможешь найти Дорийю в строении у меня за спиной." } } }, t = { d = 29.7, g = 1, v = "skyborne-female#3773", n = { m = 295, f = 296 }, c = { m = { { 0.00, "Дай-ка взгляну на тебя." }, { 1.99, "Да, думается мне, что из тебя выйдет отличный молодой маг." }, { 6.72, "Магическая сила угасла в нашем народе, но есть те, кто хочет вновь раскрыть то, что было утеряно за тысячелетия здесь, в облаках." }, { 17.13, "Уверена, ты возглавишь эти вечные поиски магического знания, и мы сможем тобою гордиться." }, { 24.52, "Поговори со мной вновь, когда будешь готов сделать следующий шаг." } }, f = { { 0.00, "Дай-ка взгляну на тебя." }, { 1.96, "Да, думается мне, что из тебя выйдет отличная молодая маг." }, { 6.61, "Магическая сила угасла в нашем народе, но есть те, кто хочет вновь раскрыть то, что было утеряно за тысячелетия здесь, в облаках." }, { 16.86, "Уверена, ты возглавишь эти вечные поиски магического знания, и мы сможем тобою гордиться." }, { 24.13, "Поговори со мной вновь, когда будешь готова сделать следующий шаг." } } } } },
    [92482] = { d = 13.2, g = 1, v = "skyborne-male", n = { m = 142, f = 143 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, наша наставница охотников Тай'ри Дальний Взор оставила тебе записку." }, { 7.67, "Она сейчас в центре деревни." }, { 9.93, "Прочитай её послание, а затем найди её саму." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, наша наставница охотников Тай'ри Дальний Взор оставила тебе записку." }, { 7.51, "Она сейчас в центре деревни." }, { 9.70, "Прочитай её послание, а затем найди её саму." } } }, t = { d = 28.7, g = 1, v = "skyborne-female#3773", n = { m = 310, f = 310 }, c = { m = { { 0.00, "Путь охотника опасен, и лишь обладающие острейшими чувствами и быстрыми рефлексами могут чувствовать себя в дикой природе как дома." }, { 10.01, "Я смотрю на тебя и вспоминаю себя саму в тот день, когда впервые предстала перед наставником много лет назад." }, { 18.44, "Мне кажется, из тебя выйдет толк, но всё зависит только от тебя самого." }, { 23.90, "Поговори со мной вновь, когда будешь готов сделать следующий шаг." } }, f = { { 0.00, "Путь охотника опасен, и лишь обладающие острейшими чувствами и быстрыми рефлексами могут чувствовать себя в дикой природе как дома." }, { 9.99, "Я смотрю на тебя и вспоминаю себя саму в тот день, когда впервые предстала перед наставником много лет назад." }, { 18.39, "Мне кажется, из тебя выйдет толк, но всё зависит только от тебя самой." }, { 23.76, "Поговори со мной вновь, когда будешь готова сделать следующий шаг." } } } } },
    [92483] = { d = 22.8, g = 1, v = "skyborne-male", n = { m = 240, f = 241 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, тебя разыскивал наш наставник разбойников Акери Клинок Сумерек." }, { 7.12, "Он оставил эту записку, так что сначала прочитай её, а потом найди его в сторожевой башне – здесь, в деревне." }, { 15.24, "Подозрительный малый, правда, о тебе можно сказать то же самое." }, { 20.01, "Думаю, вы найдёте общий язык." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, тебя разыскивал наш наставник разбойников Акери Клинок Сумерек." }, { 7.40, "Он оставил эту записку, так что сначала прочитай её, а потом найди его в сторожевой башне – здесь, в деревне." }, { 15.76, "Подозрительный малый, правда, о тебе можно сказать то же самое." }, { 20.67, "Думаю, вы найдёте общий язык." } } }, t = { d = 33.3, g = 1, v = "skyborne-male", n = { m = 335, f = 335 }, c = { m = { { 0.00, "Я почти не услышал, как ты подошёл, юный герой." }, { 3.68, "Почти." }, { 4.24, "За пределами Тендалской рощи «почти» тебя не спасёт." }, { 8.34, "Ты должен быть как тонкий клинок – бесшумный и твёрдый." }, { 12.58, "Всегда начеку, всегда помня о том, что вокруг." }, { 16.26, "Может, у тебя есть всё, чтобы выжить среди опасностей Зефриса." }, { 21.20, "А может, тебя найдут в канаве с перерезанным горлом." }, { 25.37, "В конечном счёте всё зависит лишь от тебя." }, { 28.62, "Поговори со мной снова, когда захочешь сделать следующий шаг." } }, f = { { 0.00, "Я почти не услышал, как ты подошла, юная героиня." }, { 3.86, "Почти." }, { 4.42, "За пределами Тендалской рощи «почти» тебя не спасёт." }, { 8.50, "Ты должна быть как тонкий клинок – бесшумный и твёрдый." }, { 12.71, "Всегда начеку, всегда помня о том, что вокруг." }, { 16.36, "Может, у тебя есть всё, чтобы выжить среди опасностей Зефриса." }, { 21.28, "А может, тебя найдут в канаве с перерезанным горлом." }, { 25.42, "В конечном счёте всё зависит лишь от тебя." }, { 28.65, "Поговори со мной снова, когда захочешь сделать следующий шаг." } } } } },
    [92484] = { d = 13.3, g = 1, v = "skyborne-male", n = { m = 143, f = 144 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, наш наставник шаманов Ваятель ветра Боро оставил тебе этот кристалл возвращения." }, { 8.53, "Прошу, осмотри его, а затем поговори с Боро в центре деревни." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, наш наставник шаманов Ваятель ветра Боро оставил тебе этот кристалл возвращения." }, { 8.66, "Прошу, осмотри его, а затем поговори с Боро в центре деревни." } } }, t = { d = 30.2, g = 1, v = "skyborne-male", n = { m = 311, f = 312 }, c = { m = { { 0.00, "Ты слышишь это?" }, { 1.25, "Шёпот ветров?" }, { 2.28, "Сомневаюсь, ведь духи перестали говорить с нами, когда оставили нас много лет назад." }, { 8.79, "Те, кто ищет новой встречи с духами четырёх ветров, оттачивают понимание стихий и природы, надеясь возобновить оборвавшуюся беседу." }, { 18.83, "Ступишь ли ты на этот путь, чтобы познать стихии?" }, { 22.63, "Поговори со мной вновь, когда будешь готов сделать следующий шаг, и я всему тебя обучу." } }, f = { { 0.00, "Ты слышишь это?" }, { 1.29, "Шёпот ветров?" }, { 2.36, "Сомневаюсь, ведь духи перестали говорить с нами, когда оставили нас много лет назад." }, { 9.08, "Те, кто ищет новой встречи с духами четырёх ветров, оттачивают понимание стихий и природы, надеясь возобновить оборвавшуюся беседу." }, { 19.45, "Ступишь ли ты на этот путь, чтобы познать стихии?" }, { 23.38, "Поговори со мной вновь, когда будешь готова сделать следующий шаг, и я всему тебя обучу." } } } } },
    [92485] = { d = 17.8, g = 1, v = "skyborne-male", n = { m = 208, f = 209 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, наш наставник друидов Зитон Среброветрый оставил тебе записку." }, { 6.72, "Прочитай её поскорее, а затем найди Среброветрого на нижнем ярусе большого дерева у меня за спиной." }, { 13.82, "Прислушайся к его словам – он может многому тебя научить." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, наш наставник друидов Зитон Среброветрый оставил тебе записку." }, { 6.58, "Прочитай её поскорее, а затем найди Среброветрого на нижнем ярусе большого дерева у меня за спиной." }, { 13.47, "Прислушайся к его словам – он может многому тебя научить." } } }, t = { d = 30.9, g = 1, v = "skyborne-male", n = { m = 320, f = 323 }, c = { m = { { 0.00, "Флора и фауна острова Зефрис – это целая палитра яркой, безудержной жизни." }, { 5.94, "Чтобы в природе была гармония, требуется постоянно поддерживать всё в равновесии, и храним это равновесие мы, друиды." }, { 15.02, "Я вижу в тебе отличные задатки, но этот путь труден, и тебе понадобится наставник, чтобы ты смог познать тайны клыка, когтя, пера и ветви." }, { 25.84, "Поговори со мной вновь, когда будешь готов сделать следующий шаг." } }, f = { { 0.00, "Флора и фауна острова Зефрис – это целая палитра яркой, безудержной жизни." }, { 5.90, "Чтобы в природе была гармония, требуется постоянно поддерживать всё в равновесии, и храним это равновесие мы, друиды." }, { 14.92, "Я вижу в тебе отличные задатки, но этот путь труден, и тебе понадобится наставник, чтобы ты смогла познать тайны клыка, когтя, пера и ветви." }, { 25.88, "Поговори со мной вновь, когда будешь готова сделать следующий шаг." } } } } },
    [92489] = { d = 33.0, v = "human-male", n = { x = 411 }, c = { x = { { 0.00, "Маги Кирин-Тора долгое время были союзниками Альянса." }, { 3.78, "Но после того как архидемон Архимонд разрушил Даларан, жители некогда славного города перестали с готовностью доверять чужакам." }, { 12.57, "В последние годы в Даларане начались восстановительные работы." }, { 16.84, "Однако, если верить донесениям, сейчас Кирин-Тору едва удаётся сдерживать вспышки непокорной чародейской энергии." }, { 24.64, "Мы должны помочь даларанцам взять магию под контроль, иначе рискуем потерять одного из наших самых могущественных союзников." } } }, t = { d = 16.6, v = "human-male", n = { x = 191 }, c = { x = { { 0.00, "Существо из чистой маны?" }, { 1.81, "Что бы ни вызывало эти беспорядки, оно куда могущественнее, чем говорилось в первых донесениях." }, { 8.62, "Твоя помощь выиграла для Кирин-Тора драгоценное время и напомнила магам, что мы до сих пор на их стороне." }, { 16.14, "Молодец." } } } } },
    [92514] = { d = 32.1, v = "skyborne-female", n = { x = 353 }, c = { x = { { 0.00, "На вид ты будто бы из числа Ваятелей ветра." }, { 3.20, "Рядом с ними я всегда чувствую, как по коже пробегает статический разряд, – это и выдаёт благословлённых духами." }, { 11.39, "Прежде чем я загружу тебя работой, тебе стоит поговорить со старейшиной Ваятелей ветра, живущей здесь, – Иллайей Янтарный Ветер." }, { 20.91, "Ты найдёшь её на улице, недалеко от центра." }, { 24.04, "Ах да, к Кориэлле Спокойный Бриз тоже загляни – это хозяйка местной таверны, где можно получить кров и припасы." } } }, t = { d = 26.0, g = 1, v = "skyborne-female", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Значит, ты поговорил с Иллайей?" }, { 2.53, "Отлично." }, { 3.26, "Отношения у Высшего ордена и Ваятелей ветра сейчас напряжённые, но здесь, в Шен'даре, они держат свой конфликт в рамках." }, { 12.82, "Всем известно, что у нас есть дела поважнее." }, { 16.30, "Так, с этим мы закончили..." }, { 18.47, "Похоже, ты ищешь себе занятие." }, { 21.00, "У нас тут проблема с бандитами – надеюсь, ты согласишься помочь." } }, f = { { 0.00, "Значит, ты поговорила с Иллайей?" }, { 2.61, "Отлично." }, { 3.33, "Отношения у Высшего ордена и Ваятелей ветра сейчас напряжённые, но здесь, в Шен'даре, они держат свой конфликт в рамках." }, { 12.90, "Всем известно, что у нас есть дела поважнее." }, { 16.37, "Так, с этим мы закончили..." }, { 18.55, "Похоже, ты ищешь себе занятие." }, { 21.08, "У нас тут проблема с бандитами – надеюсь, ты согласишься помочь." } } } } },
    [92515] = { d = 25.4, v = "skyborne-male", n = { x = 298 }, c = { x = { { 0.00, "Мало нам было бандитов и безумных сектантов, так теперь холмы ещё и кишат когтями прайда." }, { 6.32, "Они уже начали подбираться к границам деревни и становятся всё смелее." }, { 11.31, "Ещё немного, и у жителей начнут пропадать дети и питомцы." }, { 15.35, "Нам лучше проредить ряды этих хищников сейчас, не дожидаясь трагедии." }, { 20.28, "Принеси мне с десяток их шкур." }, { 22.36, "Сделаю из них что-нибудь полезное для деревни." } } }, t = { d = 4.0, v = "skyborne-male", n = { x = 45 }, c = { x = { { 0.00, "Никто ведь не обещал, что работа не будет грязной, верно?" } } } } },
    [92516] = { d = 13.0, v = "skyborne-female", n = { x = 154 }, c = { x = { { 0.00, "К юго-востоку от деревни Шен'дар устроила гнездовье стая гиппогрифов, и теперь они нападают на путешественников на дороге." }, { 8.60, "Мне нужно, чтобы кто-нибудь сократил численность этих существ." } } }, t = { d = 4.9, v = "skyborne-female", n = { x = 36 }, c = { x = { { 0.00, "Отличная работа – и быстрая." }, { 3.11, "Неплохо, неплохо." } } } } },
    [92517] = { d = 34.9, g = 1, v = "skyborne-female", n = { m = 367, f = 367 }, c = { m = { { 0.00, "Недалеко отсюда, к северу, есть пещера, скрытая водопадом." }, { 4.53, "Мне известно, что там устроила себе логово группа бандитов." }, { 9.14, "Они доставляли нам неприятности ещё до появления здесь культа, но теперь это настоящая беда." }, { 16.25, "Боюсь, у нас не хватает рук, и мы не можем пойти и истребить их сами." }, { 21.56, "Отправляйся туда и займись этим." }, { 24.14, "Убей как можно больше бандитов и, если получится, их предводителя, которого называют Бенник-Баламут." }, { 31.88, "В пещере опасно, так что будь осторожен." } }, f = { { 0.00, "Недалеко отсюда, к северу, есть пещера, скрытая водопадом." }, { 4.54, "Мне известно, что там устроила себе логово группа бандитов." }, { 9.16, "Они доставляли нам неприятности ещё до появления здесь культа, но теперь это настоящая беда." }, { 16.29, "Боюсь, у нас не хватает рук, и мы не можем пойти и истребить их сами." }, { 21.61, "Отправляйся туда и займись этим." }, { 24.19, "Убей как можно больше бандитов и, если получится, их предводителя, которого называют Бенник-Баламут." }, { 31.95, "В пещере опасно, так что будь осторожна." } } }, t = { d = 17.9, v = "skyborne-female", n = { x = 189 }, c = { x = { { 0.00, "С бандитами покончено, и у нас стало одной проблемой меньше." }, { 4.77, "Но, признаться, теперь меня беспокоит, что выжившие бандиты присоединятся к культу, который и без того разрастается тревожными темпами." }, { 15.37, "Впрочем, нам важна каждая победа." } } } } },
    [92519] = { d = 38.7, v = "narrator", n = { x = 424 }, c = { x = { { 0.00, "Аптекарь Йорель уже несколько дней как должен был доставить нам ящик с противоядиями и эликсирами, но у нас до сих пор ничего нет." }, { 9.35, "Этот болван, вероятно, снова отравился при очередном \"эксперименте\" в своей хибаре, которую он величает \"лабораторией\"." }, { 18.11, "Если ты и дальше хочешь помогать нашей больнице, думаю, ты справишься куда лучше него." }, { 24.61, "Ступай по дороге к ферме Го'Шека, к югу и немного к западу отсюда." }, { 29.58, "Скорее всего, всё уже упаковано и готово к отправке, а Йорель либо просто забыл о своих обязательствах, либо куда-то сгинул." } } } },
    [92521] = { d = 34.8, v = "narrator", n = { x = 358 }, c = { x = { { 0.00, "Ты ведь знаешь, что я чернокнижник?" }, { 2.65, "Сейчас вот опустился до нищеты и разделки мяса, но когда-то был могучим магом!" }, { 8.72, "Мой бес всё время куда-то убегает." }, { 11.37, "Я, конечно, мог бы просто призвать его обратно, но мне любопытно, чем он там занят." }, { 17.72, "Он тайком бегает к башне к юго-востоку отсюда и болтает со скованным сатиром." }, { 23.79, "Если тебе не трудно, я бы хотел узнать, о чём они говорят." }, { 28.39, "Уверен, беспокоиться не о чем, но с демонами ведь никогда не знаешь наверняка, правда?" } } } },
    [92528] = { d = 30.8, v = "skyborne-male", n = { x = 343 }, c = { x = { { 0.00, "Паства Ал'акира крепнет с каждым новым воодушевлённым последователем вроде тебя." }, { 5.91, "Как видишь, наша сила способна вызвать бурю!" }, { 9.30, "Я бы отправил тебя прямиком к небесному жрецу Аандерсу, чтобы он тебя оценил, но он сейчас занят – принимает гостя в таверне на северной стороне города." }, { 20.59, "Прошу тебя пока не ходить туда." }, { 23.04, "Новичку не подобает показываться на глаза столь важному гостю." }, { 27.63, "Пока что просто постарайся никому не мешать." } } }, t = { d = 32.6, v = "skyborne-female", n = { x = 331 }, c = { x = { { 0.00, "Сама Лортуна была там?" }, { 1.84, "Она же лидер этой проклятой секты!" }, { 4.68, "Если они собираются наступать на деревню Шен'дар и западную сторожевую башню, мы должны подготовиться." }, { 12.77, "Но вот что странно..." }, { 14.40, "Зачем им сторожевая башня?" }, { 16.53, "С деревней-то всё ясно, но башня..." }, { 19.30, "Да, это пост наблюдения, но не самый стратегически важный." }, { 23.84, "В любом случае мы будем готовы." }, { 26.40, "Пусть узнают, что жителей нагорья не так легко застать врасплох, как они думают." } } } } },
    [92529] = { d = 37.9, v = "skyborne-female", n = { x = 402 }, c = { x = { { 0.00, "Твоё желание служить Ал'акиру греет мне душу." }, { 3.62, "Наш народ переживает тяжёлые времена – и всё из-за нашего самодовольства." }, { 9.30, "Мы возгордились и начали принимать милость ветров как должное." }, { 14.21, "Это привело к застою, и духи ветра покинули нас." }, { 18.11, "Лишь покаявшись, мы сможем вновь ощутить ласковое прикосновение ветра." }, { 23.58, "Если хочешь быть в кругу единомышленников, отправляйся в деревню Фалаат и найди там миссионера Джасаана." }, { 31.75, "Я поставлю на тебя метку, чтобы верующие приняли тебя как нового последователя." } } }, t = { d = 15.0, v = "skyborne-male", n = { x = 151 }, c = { x = { { 0.00, "Кто тут у нас?" }, { 1.11, "Новый последователь, желающий служить Владыке Ветра?" }, { 5.46, "Значит, тебя прислала Сания?" }, { 7.89, "Воистину четыре ветра ныне благоволят нам!" }, { 11.43, "Мы рады всем, кто ищет благословения Ал'акира." } } } } },
    [92532] = { d = 16.6, v = "skyborne-male", n = { x = 183 }, c = { x = { { 0.00, "Пока тебя не было, наша наставница воинов мастер клинка Рен попросила, чтобы тебя отправили к ней, когда вернёшься." }, { 8.56, "А ещё она оставила тебе эту записку." }, { 11.35, "Прочитай её, а затем отыщи мастера клинка Рен в местной сторожевой башне." } } }, t = { d = 22.9, v = "skyborne-female#3773", n = { x = 210 }, c = { x = { { 0.00, "Тебя ждёт опасное путешествие." }, { 2.64, "Мир меняется, и чтобы наш народ выжил, нужны те, у кого есть воля вести и защищать других." }, { 10.47, "Твоя сила растёт, и тебе нужен наставник." }, { 14.12, "Приходи ко мне." }, { 15.44, "Я сделаю всё, чтобы обучить тебя и помочь стать сильнее." }, { 20.32, "Удачи." }, { 20.94, "Да направят тебя ветра." } } } } },
    [92544] = { d = 34.9, v = "skyborne-female#3773", n = { x = 374 }, c = { x = { { 0.00, "Шайка ал'акетских негодяев расположилась у развалин храма к юго-западу отсюда." }, { 6.15, "Ими верховодит настоящее чудовище по имени Малдуко Упавшее Облако." }, { 11.40, "Нет сомнений, что этот сброд явился сюда из святилища Акира по приказу верховной жрицы Лортуны, чтобы нападать на путников и заманивать в секту всех, кого можно." }, { 23.91, "Мне нужно оставаться здесь, чтобы предупреждать путников об опасности, но я скажу спасибо, если ты что-нибудь сделаешь с сектантами и их лидером." } } }, t = { d = 14.8, g = 1, v = "skyborne-female#3773", n = { x = 144 }, c = { m = { { 0.00, "Как же мне хотелось бросить дежурство и присоединиться к тебе." }, { 5.06, "Надеюсь, эти негодяи всё поняли и скоро уберутся восвояси." }, { 9.97, "Спасибо, герой." }, { 11.30, "Следопыты Тендалской рощи благодарны тебе." } }, f = { { 0.00, "Как же мне хотелось бросить дежурство и присоединиться к тебе." }, { 5.03, "Надеюсь, эти негодяи всё поняли и скоро уберутся восвояси." }, { 9.92, "Спасибо, героиня." }, { 11.40, "Следопыты Тендалской рощи благодарны тебе." } } } } },
    [92550] = { d = 37.4, g = 1, v = "skyborne-female", n = { m = 397, f = 398 }, c = { m = { { 0.00, "Пожалуй, лучшей защитой для нас будет уверенное нападение." }, { 4.52, "У нас есть преимущество, так как мы знаем о планах врага." }, { 8.82, "Он точно не ждёт, что мы нападём первыми." }, { 11.88, "Ты уже много сделал для меня, но, прошу, отправляйся в деревню Фалаат." }, { 17.37, "Убей как можно больше сектантов, а если сможешь подобраться достаточно близко, то и их командира." }, { 24.87, "Его голову принеси мне." }, { 26.75, "Я останусь здесь и прослежу, чтобы мирные жители и наши немногочисленные миротворцы подготовились к обороне... на случай, если ты не вернёшься." } }, f = { { 0.00, "Пожалуй, лучшей защитой для нас будет уверенное нападение." }, { 4.48, "У нас есть преимущество, так как мы знаем о планах врага." }, { 8.75, "Он точно не ждёт, что мы нападём первыми." }, { 11.78, "Ты уже много сделала для меня, но, прошу, отправляйся в деревню Фалаат." }, { 17.30, "Убей как можно больше сектантов, а если сможешь подобраться достаточно близко, то и их командира." }, { 24.74, "Его голову принеси мне." }, { 26.60, "Я останусь здесь и прослежу, чтобы мирные жители и наши немногочисленные миротворцы подготовились к обороне... на случай, если ты не вернёшься." } } }, t = { d = 24.7, g = 1, v = "skyborne-female", n = { m = 266, f = 268 }, c = { m = { { 0.00, "Слава ветрам, ты вернулся!" }, { 2.02, "Сания Серебряный Поток буквально только что ускользнула из деревни – наверняка испугалась того, что жители готовят оружие." }, { 11.16, "Ты оказал неоценимую помощь деревне Шен'дар." }, { 14.53, "Мы все перед тобой в долгу." }, { 16.61, "Если сектанты вернутся на нагорье, они поймут, что мы не такая уж и лёгкая мишень." }, { 22.73, "Да направят тебя ветра." } }, f = { { 0.00, "Слава ветрам, ты вернулась!" }, { 2.10, "Сания Серебряный Поток буквально только что ускользнула из деревни – наверняка испугалась того, что жители готовят оружие." }, { 11.32, "Ты оказала неоценимую помощь деревне Шен'дар." }, { 14.77, "Мы все перед тобой в долгу." }, { 16.87, "Если сектанты вернутся на нагорье, они поймут, что мы не такая уж и лёгкая мишень." }, { 23.04, "Да направят тебя ветра." } } } } },
    [92551] = { d = 29.4, v = "skyborne-male", n = { x = 323 }, c = { x = { { 0.00, "Я слышал, ты собираешься в деревню Фалаат." }, { 3.12, "Когда будешь там, поищи наши украденные припасы." }, { 6.77, "Ал'акетские сектанты уже не первый месяц нападают на наши караваны, везущие еду и ветрокамни в низины и из них." }, { 14.99, "А вину всегда сваливают на бандитов." }, { 17.71, "Но мы-то знаем, что всё украденное в итоге оказывается в одном и том же месте." }, { 23.42, "Если в Фалаате ещё что-нибудь осталось, ты здорово поможешь, если принесёшь это нам." } } }, t = { d = 10.8, v = "skyborne-male", n = { x = 127 }, c = { x = { { 0.00, "Замечательно!" }, { 1.01, "Без регулярных поставок припасов нам приходилось несладко." }, { 5.31, "Мы с констеблем позаботимся о том, чтобы это досталось наиболее нуждающимся." } } } } },
    [92553] = { d = 23.0, g = 1, v = "skyborne-male", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Хочешь немного поработать?" }, { 1.95, "Такой сильный помощник мне не помешает." }, { 4.80, "Забот у нас сейчас столько, что ни у кого нет времени на охоту и сбор растений." }, { 10.44, "Мне нужен кто-то, кто добудет свежие яйца и мясо долгоногов, чтобы накормить деревню." }, { 16.67, "Если поможешь, буду рад научить тебя готовить одно из моих фирменных блюд." }, { 22.12, "Что скажешь?" } }, f = { { 0.00, "Хочешь немного поработать?" }, { 1.95, "Такая сильная помощница мне не помешает." }, { 4.88, "Забот у нас сейчас столько, что ни у кого нет времени на охоту и сбор растений." }, { 10.55, "Мне нужен кто-то, кто добудет свежие яйца и мясо долгоногов, чтобы накормить деревню." }, { 16.80, "Если поможешь, буду рад научить тебя готовить одно из моих фирменных блюд." }, { 22.27, "Что скажешь?" } } }, t = { d = 17.4, v = "skyborne-male", n = { x = 179 }, c = { x = { { 0.00, "Эти яйца непросто раздобыть, но, о ветер, какие же они вкусные, если пожарить их в сале медверы!" }, { 7.48, "Если у тебя есть время и ты любишь готовить, могу дать тебе несколько советов." }, { 13.53, "Я готов начать обучение хоть сейчас – только скажи." } } } } },
    [92579] = { d = 34.4, v = "skyborne-female", n = { x = 386 }, c = { x = { { 0.00, "Пока похоже, что столп и деревня в безопасности, и я хочу попросить тебя доставить этот доклад Валеннии Штормовой Кулак в Валанаар, на юго-восточный край острова." }, { 11.89, "Валенния – лидер миротворцев на острове, и она должна узнать, что здесь произошло." }, { 17.90, "Культ быстро разрастается, и миротворцы до сих пор избегали открытого столкновения, но дальше так продолжаться не может." }, { 26.49, "Валанаар должен быть готов к бою." }, { 29.00, "Как бы то ни было, спасибо тебе." }, { 31.38, "В Шен'даре ты всегда найдёшь верных друзей." } } }, t = { d = 35.0, g = 1, v = "skyborne-female", n = { m = 355, f = 356 }, c = { m = { { 0.00, "*Читая письмо, Валенния мрачнеет.*" }, { 3.28, "Аонда доверила тебе доставку послания и хорошо о тебе отзывается в нём." }, { 8.49, "Я тоже постараюсь тебе доверять." }, { 10.90, "Прежде чем продолжить разговор, мне нужно посоветоваться с теми немногими миротворцами, что ещё у нас остались, и разработать план на случай нападения культа." }, { 22.11, "Отдохни пока в Валанааре." }, { 24.00, "Если будешь искать себе занятие, многим горожанам, скорее всего, не помешает помощь такого молодого и сильного искателя приключений, как ты." } }, f = { { 0.00, "*Читая письмо, Валенния мрачнеет.*" }, { 3.12, "Аонда доверила тебе доставку послания и хорошо о тебе отзывается в нём." }, { 8.48, "Я тоже постараюсь тебе доверять." }, { 10.96, "Прежде чем продолжить разговор, мне нужно посоветоваться с теми немногими миротворцами, что ещё у нас остались, и разработать план на случай нападения культа." }, { 22.49, "Отдохни пока в Валанааре." }, { 24.44, "Если будешь искать себе занятие, многим горожанам, скорее всего, не помешает помощь такой молодой и сильной искательницы приключений, как ты." } } } } },
    [92595] = { d = 29.0, g = 1, v = "skyborne-female", n = { m = 259, f = 259 }, c = { m = { { 0.00, "*Иллайя тепло улыбается вам.*" }, { 3.04, "Я рада, что ты пришёл поговорить со мной, дитя ветров." }, { 7.34, "Едва увидев тебя, я поняла, что ты владеешь небесным взором." }, { 12.29, "Тебя это удивляет?" }, { 13.89, "Даже те, кто не учился ремеслу шамана, могут обладать этим даром." }, { 19.28, "Идём." }, { 19.72, "Нам нужно поговорить о предназначении Ваятелей ветра, сути выпавших нам на Зефрисе испытаний и судьбе нашего народа." } }, f = { { 0.00, "*Иллайя тепло улыбается вам.*" }, { 3.12, "Я рада, что ты пришла поговорить со мной, дитя ветров." }, { 7.34, "Едва увидев тебя, я поняла, что ты владеешь небесным взором." }, { 12.13, "Тебя это удивляет?" }, { 13.68, "Даже те, кто не учился ремеслу шамана, могут обладать этим даром." }, { 18.89, "Идём." }, { 19.31, "Нам нужно поговорить о предназначении Ваятелей ветра, сути выпавших нам на Зефрисе испытаний и судьбе нашего народа." } } }, t = { d = 30.2, v = "skyborne-female", n = { x = 304 }, c = { x = { { 0.00, "Думаю, теперь ты понимаешь, как важен долг Ваятелей ветра." }, { 4.77, "Мы должны ценить каждого одарённого небесным взором, если хотим, чтобы духи ветров вновь внимали нам." }, { 13.07, "Ал'акет угрожает нам изнутри, и мы осознаем своё шаткое положение в Небесной выси." }, { 19.75, "Мы, Ваятели ветра, должны спасти свой дом и позаботиться о том, чтобы шен'дорай пережили тяжёлые времена." }, { 28.19, "В этом нам поможет наш дар." } } } } },
    [92596] = { d = 26.5, g = 1, v = "skyborne-male", n = { m = 275, f = 276 }, c = { m = { { 0.00, "Тебя окружает мощная аура чародейской энергии, хотя ты не проходил посвящение в маги." }, { 6.69, "Не сомневаюсь, тебя ждёт успех в странствиях, а связь с нашей древней магией станет для тебя великим даром, даже если за всю жизнь ты не произнесёшь ни единого слова силы." }, { 19.80, "Давай побеседуем о моём ордене, природе магии на Зефрисе и судьбе нашего народа." } }, f = { { 0.00, "Тебя окружает мощная аура чародейской энергии, хотя ты не проходила посвящение в маги." }, { 6.89, "Не сомневаюсь, тебя ждёт успех в странствиях, а связь с нашей древней магией станет для тебя великим даром, даже если за всю жизнь ты не произнесёшь ни единого слова силы." }, { 20.24, "Давай побеседуем о моём ордене, природе магии на Зефрисе и судьбе нашего народа." } } }, t = { d = 33.1, v = "skyborne-male", n = { x = 351 }, c = { x = { { 0.00, "Высший орден заботится о выживании нашего народа." }, { 3.95, "Мы чтим своих стихийных покровителей, но должны принимать реальность такой, какая она есть." }, { 11.07, "Их больше нет с нами – мы предоставлены сами себе." }, { 15.01, "Ал'акет угрожает нам изнутри, а на уязвимое состояние нашего дома нельзя закрывать глаза, но мы потомки высокорождённых Эльдре'Таласа: мы должны позаботиться о том, чтобы шен'дорай вновь твёрдо стояли на ногах." }, { 31.16, "В этом нам поможет наш дар." } } } } },
    [92597] = { d = 26.2, v = "skyborne-male", n = { x = 281 }, c = { x = { { 0.00, "Здесь, в обители стихий, значительная часть нашей магической силы исходит от силовых линий, пролегающих под землёй." }, { 8.89, "В последнее время они начали выступать на поверхность, и у нас появился прямой доступ к их дремлющей магической энергии." }, { 18.27, "Ступай к валунам на северо-востоке." }, { 21.09, "Там есть силовая линия." }, { 22.92, "Вспомни своё наследие и напитайся энергией." } } }, t = { d = 31.4, g = 1, v = "skyborne-male", n = { m = 311, f = 312 }, c = { m = { { 0.00, "Чувствуешь?" }, { 0.97, "Да?" }, { 1.26, "Прекрасно!" }, { 2.16, "Ты сделал первые шаги." }, { 4.09, "С твоими способностями ты сможешь использовать магическую энергию многих мест." }, { 10.48, "Так можно получить разные преимущества – иногда явные, иногда незаметные." }, { 16.57, "Точно не узнаешь, пока не попробуешь." }, { 19.70, "Но это лучшая часть твоего дара... узнавать непознанное." }, { 24.38, "Чтобы выжить в эти тяжёлые времена, нам надо неустанно стремиться к знаниям... и силе." } }, f = { { 0.00, "Чувствуешь?" }, { 0.93, "Да?" }, { 1.22, "Прекрасно!" }, { 2.08, "Ты сделала первые шаги." }, { 4.02, "С твоими способностями ты сможешь использовать магическую энергию многих мест." }, { 10.18, "Так можно получить разные преимущества – иногда явные, иногда незаметные." }, { 16.06, "Точно не узнаешь, пока не попробуешь." }, { 19.07, "Но это лучшая часть твоего дара... узнавать непознанное." }, { 23.59, "Чтобы выжить в эти тяжёлые времена, нам надо неустанно стремиться к знаниям... и силе." } } } } },
    [92598] = { d = 30.1, v = "skyborne-female#3773", n = { x = 313 }, c = { x = { { 0.00, "Как и все Ваятели ветра, ты обладаешь даром небесного взора, которым нас наделили духи стихий." }, { 7.52, "Ступай к стоячим камням к северо-востоку от деревни." }, { 11.75, "Найди там слияние стихий и примени свой дар." }, { 15.26, "Использовать небесный взор можно где угодно, но он наиболее силён в присутствии слияния стихий." }, { 22.71, "Также у духов, которых привлекают такие места, подчас можно получить новые крупицы мудрости." } } }, t = { d = 25.0, g = 1, v = "skyborne-female#3773", n = { m = 263, f = 264 }, c = { m = { { 0.00, "Небесный взор – как ещё одна мышца, которую нужно развивать, если хочешь усилить свой дар." }, { 6.77, "В твоих приключениях наверняка пригодится способность стирать грань между мирами смертных и духов." }, { 14.16, "Советую запомнить то, чему ты научился сегодня." }, { 17.74, "Способность слышать то, о чём говорят духи, может стать ключом к нашему выживанию." } }, f = { { 0.00, "Небесный взор – как ещё одна мышца, которую нужно развивать, если хочешь усилить свой дар." }, { 7.09, "В твоих приключениях наверняка пригодится способность стирать грань между мирами смертных и духов." }, { 14.83, "Советую запомнить то, чему ты научилась сегодня." }, { 18.66, "Способность слышать то, о чём говорят духи, может стать ключом к нашему выживанию." } } } } },
    [92612] = { d = 33.2, v = "nightelf-male", n = { x = 142 }, c = { x = { { 0.00, "*Кетарас берёт ветвь и рассматривает её.*" }, { 3.19, "*Он начинает шептать друидское заклинание, и ветвь разгорается ярче.*" }, { 8.80, "*Болезненно-зелёный кристалл тоже откликается: кажется, он вбирает в себя окружающий свет.*" }, { 16.16, "К сожалению, тайны этой ветви мне не по силам." }, { 20.66, "Но я чувствую... что-то." }, { 22.99, "Возьми ветвь и отправляйся в селение Ночная Гавань на Лунной поляне." }, { 29.56, "Попроси помощи у Дендрита Блеска Звёзд." } } } },
    [92640] = { d = 27.9, v = "skyborne-male", n = { x = 340 }, c = { x = { { 0.00, "Раз мы не можем открыто напасть на культ, остаётся воспользоваться шансом и атаковать само святилище." }, { 6.91, "Выведем Лортуну из игры, пока она не завершила свою часть плана." }, { 11.49, "Момент как нельзя более благоприятный: Валенния уже некоторое время готовит стратегию нападения на святилище." }, { 19.15, "Единственная загвоздка в том, что её не выполнить без дополнительной помощи." }, { 24.30, "Поговори с Валеннией, она расскажет тебе подробности." } } }, t = { d = 9.0, v = "skyborne-female", n = { x = 98 }, c = { x = { { 0.00, "Отношения между Ваятелями ветра и Высшим орденом сейчас напряжённые, но план не удастся без содействия обеих сторон." } } } } },
    [92642] = { d = 38.5, v = "skyborne-female", n = { x = 434 }, c = { x = { { 0.00, "Валенния прислала одного бойца, когда у нас тут полномасштабное нападение..." }, { 5.55, "Ветра милостивые..." }, { 7.00, "Ты выглядишь не очень многообещающе, но я не стану отказываться от помощи." }, { 12.35, "Надо причинить врагу как можно больше урона, чтобы быстро его остановить." }, { 17.89, "Мои бойцы долго не продержатся." }, { 20.27, "Спустись с холма и нарушь их организацию." }, { 23.31, "Вражеские целители постоянно поддерживают наступление – если мы их уничтожим, то сможем собрать силы для ответного удара и отбросить противника." }, { 33.81, "А если убьёшь пару сектантов по пути, то тоже очень нам поможешь." } } }, t = { d = 6.0, g = 1, v = "skyborne-female", n = { m = 43, f = 44 }, c = { m = { { 0.00, "Ты ещё жив?" }, { 1.16, "Что ж..." }, { 2.03, "Спасибо ветрам за это маленькое чудо." } }, f = { { 0.00, "Ты ещё жива?" }, { 1.28, "Что ж..." }, { 2.09, "Спасибо ветрам за это маленькое чудо." } } } } },
    [92643] = { d = 31.9, v = "skyborne-male", n = { x = 366 }, c = { x = { { 0.00, "Мы вышли на связь с отступником из Ал'акета." }, { 3.09, "Он утверждает, что знает истинные планы культа в отношении острова, и хочет встретиться с нами, но только если мы предоставим ему защиту." }, { 12.94, "Этот перебежчик скрывается в уединённом жилище к северо-западу от Валанаара, на нагорье." }, { 19.19, "Нужно, чтобы кто-то незаметно добрался туда, отыскал предателя и привёл его к нам." }, { 25.11, "Это может быть ловушка, но если у отступника и правда есть важная информация, нам стоит рискнуть." } } }, t = { d = 13.0, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "*Сектант явно мёртв – его убили ассасины, с которыми вы сразились у входа в дом.*" }, { 6.27, "*Вы наклоняетесь, чтобы осмотреть тело, и замечаете, как что-то поблёскивает на свету...*" } } } } },
    [92644] = { d = 17.3, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "*Вы запускаете руку под ещё тёплое тело сектанта-перебежчика и достаёте небольшой светящийся синий кристалл.*" }, { 8.46, "*Похоже, он повреждён, но всё ещё может быть полезен.*" }, { 12.51, "*Верховный старейшина Песня Теней наверняка им заинтересуется.*" } } }, t = { d = 11.1, v = "skyborne-male", n = { x = 51 }, c = { x = { { 0.00, "Значит, перебежчик был уже мёртв?" }, { 3.44, "Печально..." }, { 4.56, "*Вы отдаёте кристалл, который нашли на теле мёртвого сектанта.*" }, { 9.04, "А это уже интересно..." } } } } },
    [92645] = { d = 36.2, g = 1, v = "skyborne-female", n = { x = 350 }, c = { m = { { 0.00, "Отразить это нападение будет непросто, если мы не устраним командира." }, { 5.77, "Её зовут Бельгилос Сокрушительница, и это настоящая гроза." }, { 10.58, "Она была миротворицей, пока культ не разбушевался, как сейчас, но даже тогда в ней было что-то... жуткое." }, { 19.23, "Могу только представить, насколько страшнее она сейчас." }, { 23.89, "Быть может, я отправляю тебя на верную смерть, но если кто-то не устранит Бельгилос, погибнем мы все." }, { 32.10, "Найдёшь её на вилле у подножия холма." }, { 35.13, "Удачи, герой." } }, f = { { 0.00, "Отразить это нападение будет непросто, если мы не устраним командира." }, { 5.68, "Её зовут Бельгилос Сокрушительница, и это настоящая гроза." }, { 10.42, "Она была миротворицей, пока культ не разбушевался, как сейчас, но даже тогда в ней было что-то... жуткое." }, { 18.94, "Могу только представить, насколько страшнее она сейчас." }, { 23.53, "Быть может, я отправляю тебя на верную смерть, но если кто-то не устранит Бельгилос, погибнем мы все." }, { 31.61, "Найдёшь её на вилле у подножия холма." }, { 34.60, "Удачи, героиня." } } }, t = { d = 7.7, g = 1, v = "skyborne-female", n = { x = 65 }, c = { m = { { 0.00, "Бельгилос мертва?" }, { 1.57, "Да хранят тебя четыре ветра, герой." }, { 4.78, "Похоже, мы ещё переживём этот бой." } }, f = { { 0.00, "Бельгилос мертва?" }, { 1.57, "Да хранят тебя четыре ветра, героиня." }, { 4.94, "Похоже, мы ещё переживём этот бой." } } } } },
    [92646] = { d = 25.0, g = 1, v = "skyborne-female", n = { x = 263 }, c = { m = { { 0.00, "Лортуна бежала на вершины через какой-то портал." }, { 3.71, "Айесса и Элаадрин последовали за ней." }, { 6.48, "Это было буквально пару мгновений назад." }, { 9.66, "Боюсь, мне слишком досталось, чтобы продолжать." }, { 13.24, "Пройди через портал, найди Элаадрина и помоги остановить Лортуну." }, { 18.24, "Элаадрин и Айесса послали за подкреплением, но оно может к вам не успеть." }, { 23.71, "Удачи, герой." } }, f = { { 0.00, "Лортуна бежала на вершины через какой-то портал." }, { 3.74, "Айесса и Элаадрин последовали за ней." }, { 6.53, "Это было буквально пару мгновений назад." }, { 9.73, "Боюсь, мне слишком досталось, чтобы продолжать." }, { 13.34, "Пройди через портал, найди Элаадрина и помоги остановить Лортуну." }, { 18.37, "Элаадрин и Айесса послали за подкреплением, но оно может к вам не успеть." }, { 23.88, "Удачи, героиня." } } }, t = { d = 26.4, v = "skyborne-female", n = { x = 279 }, c = { x = { { 0.00, "Я отправила нескольких целителей, чтобы помочь Валеннии и её оставшимся бойцам." }, { 6.16, "Сейчас она отдыхает в доме верховного старейшины." }, { 10.09, "Мулн уже отбыл обратно, но мы успели обсудить будущее Ваятелей ветра и наши дальнейшие действия на Азероте." }, { 18.49, "Боюсь, остров уязвим как никогда, и нам надо решить, как мы будем защищать Зефрис от того, что нас ждёт." } } } } },
    [92679] = { d = 29.4, g = 1, v = "skyborne-male", n = { m = 231, f = 235 }, c = { m = { { 0.00, "З... здравствуй." }, { 1.74, "Кажется, ты опытный искатель приключений." }, { 6.17, "Я..." }, { 6.56, "*Небеснорождённый морщится – он явно испытывает сильную боль.*" }, { 11.84, "Я хотел спросить, не ищешь ли ты какую-нибудь работу..." }, { 15.85, "Хочу нанять в Валанааре бойцов, чтобы спасти мою ферму." }, { 20.07, "Если такая задача по тебе, отыщи мою жену, Аамелию Поле Ветров, в нашем саду." }, { 25.99, "Он находится в низине, на западе от Валанаара." } }, f = { { 0.00, "З... здравствуй." }, { 1.74, "Кажется, ты опытная искательница приключений." }, { 6.57, "Я..." }, { 6.96, "*Небеснорождённый морщится – он явно испытывает сильную боль.*" }, { 12.00, "Я хотел спросить, не ищешь ли ты какую-нибудь работу..." }, { 16.03, "Хочу нанять в Валанааре бойцов, чтобы спасти мою ферму." }, { 20.26, "Если такая задача по тебе, отыщи мою жену, Аамелию Поле Ветров, в нашем саду." }, { 26.21, "Он находится в низине, на западе от Валанаара." } } }, t = { d = 25.4, g = 1, v = "skyborne-female", n = { m = 199, f = 199 }, c = { m = { { 0.00, "*Вы рассказываете Аамелии, что случилось с Альварионом.*" }, { 4.40, "Что ж, зато теперь я знаю, что он в Валанааре и в безопасности." }, { 9.60, "Послушай, незнакомец..." }, { 11.56, "Мне очень жаль, но мой дуралей зря послал тебя сюда – только погибнешь напрасно." }, { 18.28, "Если в тебе есть хоть капля благоразумия, уходи подобру-поздорову." }, { 23.86, "Это не твоя битва." } }, f = { { 0.00, "*Вы рассказываете Аамелии, что случилось с Альварионом.*" }, { 4.32, "Что ж, зато теперь я знаю, что он в Валанааре и в безопасности." }, { 9.35, "Послушай, незнакомка..." }, { 11.24, "Мне очень жаль, но мой дуралей зря послал тебя сюда – только погибнешь напрасно." }, { 17.72, "Если в тебе есть хоть капля благоразумия, уходи подобру-поздорову." }, { 23.11, "Это не твоя битва." } } } } },
    [92682] = { d = 31.5, v = "skyborne-female", n = { x = 312 }, c = { x = { { 0.00, "Значит, ты скорее из отважных, чем из разумных?" }, { 3.73, "Ладно, не буду тебя отговаривать." }, { 6.46, "Ферау и его бандиты ещё не скоро придут за своей долей урожая, так что пока выполни пару поручений и отработай свой хлеб." }, { 16.16, "Сначала сходи собери сегодняшнюю партию буреяблок." }, { 20.25, "А, и имей в виду: среди буреяблонь прячутся разбойники..." }, { 24.85, "Думают, я их не вижу – как бы не так." }, { 27.72, "Убей их." }, { 28.44, "Как раз и посмотрим, что ты умеешь в бою." } } }, t = { d = 5.1, g = 1, v = "skyborne-female", n = { m = 49, f = 50 }, c = { m = { { 0.00, "Я всё видела в окно: а ты неплохо справился с этими бандитами." } }, f = { { 0.00, "Я всё видела в окно: а ты неплохо справилась с этими бандитами." } } } } },
    [92683] = { d = 33.1, g = 1, v = "skyborne-female", n = { m = 359, f = 360 }, c = { m = { { 0.00, "Уверена, ты уже заметил огромных порхательниц на полях за садом?" }, { 4.88, "Они не только радуют глаз – их пыльца бывает весьма полезна." }, { 9.49, "С ней много хлопот, но если собрать её побольше, эта пыльца очень помогает в быту." }, { 15.79, "Возьми эту хлопушку от бабочек-порхательниц и хорошенько похлопай этих букашек." }, { 21.82, "Чаще всего они просто пугаются и улетают, но иной раз могут рассвирепеть." }, { 27.44, "При любом раскладе они встряхнутся достаточно, чтобы просыпать кучку пыльцы." } }, f = { { 0.00, "Уверена, ты уже заметила огромных порхательниц на полях за садом?" }, { 4.91, "Они не только радуют глаз – их пыльца бывает весьма полезна." }, { 9.49, "С ней много хлопот, но если собрать её побольше, эта пыльца очень помогает в быту." }, { 15.75, "Возьми эту хлопушку от бабочек-порхательниц и хорошенько похлопай этих букашек." }, { 21.74, "Чаще всего они просто пугаются и улетают, но иной раз могут рассвирепеть." }, { 27.32, "При любом раскладе они встряхнутся достаточно, чтобы просыпать кучку пыльцы." } } }, t = { d = 26.6, g = 1, v = "skyborne-female", n = { m = 286, f = 288 }, c = { m = { { 0.00, "Обращаться с этой пыльцой не очень приятно: она везде забивается." }, { 4.84, "Боюсь, ты ещё долго будешь вытряхивать её из штанов." }, { 8.63, "Зато ты очень мне помог." }, { 10.46, "Я уже несколько недель собиралась этим заняться, но боялась отойти от дома, пока я тут совсем одна, а вокруг поджидают бандиты." }, { 19.82, "Только не спрашивай, для чего я использую пыльцу." }, { 23.41, "Нужно для всякого..." }, { 24.92, "Не бери в голову." } }, f = { { 0.00, "Обращаться с этой пыльцой не очень приятно: она везде забивается." }, { 4.90, "Боюсь, ты ещё долго будешь вытряхивать её из штанов." }, { 8.75, "Зато ты очень мне помогла." }, { 10.74, "Я уже несколько недель собиралась этим заняться, но боялась отойти от дома, пока я тут совсем одна, а вокруг