    [92684] = { d = 27.1, g = 1, v = "skyborne-female", n = { m = 295, f = 295 }, c = { m = { { 0.00, "Мало нам было бедного урожая, так ещё местные буреноги повадились забредать в сад и воровать буреяблоки." }, { 7.74, "Можешь сходить в поля и сократить их число?" }, { 11.04, "Но будь осторожен: буреноги из низин крупнее и злее, чем те, что пасутся на нагорье." }, { 17.23, "Если зазеваешься, они отправят тебя на тот свет одним ударом ногой." }, { 22.34, "Принеси немного их мяса, и я заодно приготовлю нам горячий обед." } }, f = { { 0.00, "Мало нам было бедного урожая, так ещё местные буреноги повадились забредать в сад и воровать буреяблоки." }, { 7.76, "Можешь сходить в поля и сократить их число?" }, { 11.07, "Но будь осторожна: буреноги из низин крупнее и злее, чем те, что пасутся на нагорье." }, { 17.28, "Если зазеваешься, они отправят тебя на тот свет одним ударом ногой." }, { 22.41, "Принеси немного их мяса, и я заодно приготовлю нам горячий обед." } } }, t = { d = 5.0, g = 1, v = "skyborne-female", n = { m = 47, f = 48 }, c = { m = { { 0.00, "Вот это крупные вырезки!" }, { 2.17, "Каких же монстров ты там завалил?" } }, f = { { 0.00, "Вот это крупные вырезки!" }, { 2.21, "Каких же монстров ты там завалила?" } } } } },
    [92685] = { d = 23.0, v = "skyborne-female", n = { x = 250 }, c = { x = { { 0.00, "У бандитов тут повсюду лагеря, но один небольшой находится совсем близко: на холмах к северу отсюда." }, { 7.55, "Поднимись туда и задай им жару." }, { 9.97, "Если застанем бандитов врасплох и перебьём их до того, как они доберутся сюда, то достаточно сравняем шансы." }, { 18.05, "Принеси мне их маски." }, { 19.67, "Чем больше они пропитаются кровью, тем лучше." } } }, t = { d = 30.9, g = 1, v = "skyborne-female", n = { m = 299, f = 301 }, c = { m = { { 0.00, "А ты меня послушал: маски и правда пропитаны кровью." }, { 4.40, "И славно." }, { 5.22, "Так я точно знаю, что мерзавцам было больно." }, { 8.95, "А если серьёзно, огромное спасибо за всё, что ты сделал." }, { 13.50, "Я неделями бесцельно скиталась по ферме, будто ожидая приговора." }, { 18.86, "Теперь ко мне возвращается надежда." }, { 21.77, "Ферау и его негодяи вот-вот будут здесь." }, { 25.20, "Нужно только их встретить." }, { 27.44, "Что скажешь?" }, { 28.48, "Останешься со мной до конца?" } }, f = { { 0.00, "А ты меня послушала: маски и правда пропитаны кровью." }, { 4.48, "И славно." }, { 5.30, "Так я точно знаю, что мерзавцам было больно." }, { 9.03, "А если серьёзно, огромное спасибо за всё, что ты сделала." }, { 13.65, "Я неделями бесцельно скиталась по ферме, будто ожидая приговора." }, { 19.02, "Теперь ко мне возвращается надежда." }, { 21.93, "Ферау и его негодяи вот-вот будут здесь." }, { 25.36, "Нужно только их встретить." }, { 27.60, "Что скажешь?" }, { 28.64, "Останешься со мной до конца?" } } } } },
    [92693] = { d = 31.3, g = 1, v = "skyborne-female", n = { m = 318, f = 319 }, c = { m = { { 0.00, "Благодаря тебе у нас появился шанс." }, { 2.78, "Даже если мы погибнем, то сделаем это, зная, что сражались до последнего." }, { 8.63, "А для тебя, незнакомец, это последняя возможность отступить: если предпочтёшь вернуться в Валанаар и сберечь свою жизнь, я не осужу." }, { 18.98, "Но если ты так любишь выручать пропащих и отчаявшихся, скажи, когда будешь готов." }, { 25.47, "Мы выйдем навстречу врагу с высоко поднятой головой – и будь что будет." } }, f = { { 0.00, "Благодаря тебе у нас появился шанс." }, { 2.81, "Даже если мы погибнем, то сделаем это, зная, что сражались до последнего." }, { 8.70, "А для тебя, незнакомка, это последняя возможность отступить: если предпочтёшь вернуться в Валанаар и сберечь свою жизнь, я не осужу." }, { 19.13, "Но если ты так любишь выручать пропащих и отчаявшихся, скажи, когда будешь готова." }, { 25.75, "Мы выйдем навстречу врагу с высоко поднятой головой – и будь что будет." } } }, t = { d = 7.9, v = "skyborne-female", n = { x = 69 }, c = { x = { { 0.00, "Не могу поверить... всё кончено." }, { 3.00, "Мне надо успокоиться." }, { 5.00, "Иначе сердце выпрыгнет из груди." } } } } },
    [92698] = { d = 25.7, v = "elemental-golem", n = { x = 36 }, c = { x = { { 1.66, "*Вы наклоняетесь поближе, чтобы расслышать слова, раздающиеся под пластинами огромного голема.*" }, { 9.02, "Ошибка назначения..." }, { 11.78, "Вопрос..." }, { 13.10, "В чём...." }, { 14.30, "Назначение..." }, { 15.98, "*Похоже, эти обрывки фраз повторяются по кругу.*" }, { 19.51, "*Может быть, кто-то поблизости знает об этой странной машине?*" } } }, t = { d = 33.2, v = "skyborne-female", n = { x = 370 }, c = { x = { { 0.00, "Голем?" }, { 0.53, "Он уже несколько десятков лет бродит по этим полям." }, { 4.35, "Кажется, с тех пор как ушли элементали воздуха." }, { 7.78, "Альварион предположил, что он перевозил урожай на рынок или помогал ухаживать за скотом, когда здесь был большой сад." }, { 16.28, "Но с тех пор прошла уже тысяча лет." }, { 18.85, "В древние времена таких големов поддерживали Ваятели ветра." }, { 23.26, "Мы хотели подать запрос, чтобы те пришли и осмотрели его, но так и не собрались." }, { 29.13, "В последнее время мы просто не обращаем на него внимания." } } } } },
    [92699] = { d = 31.2, g = 1, v = "skyborne-female", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Ты только что прибыл в Валанаар и, наверное, хочешь встретиться с другими представителями Высшего ордена." }, { 7.75, "Нынешний верховный магистр Элаадрин Вечерняя Буря и его приближённые обосновались в юго-восточной части Валанаара." }, { 16.24, "Будь настороже: Высший орден и Ваятели ветра друг с другом не ладят." }, { 21.31, "Вторых лучше обходить стороной." }, { 23.72, "У нас и так хватает хлопот из-за культа – стычки между фракциями на улицах города я не потерплю." } }, f = { { 0.00, "Ты только что прибыла в Валанаар и, наверное, хочешь встретиться с другими представителями Высшего ордена." }, { 7.92, "Нынешний верховный магистр Элаадрин Вечерняя Буря и его приближённые обосновались в юго-восточной части Валанаара." }, { 16.52, "Будь настороже: Высший орден и Ваятели ветра друг с другом не ладят." }, { 21.67, "Вторых лучше обходить стороной." }, { 24.10, "У нас и так хватает хлопот из-за культа – стычки между фракциями на улицах города я не потерплю." } } }, t = { d = 34.7, v = "skyborne-male", n = { x = 369 }, c = { x = { { 0.00, "Добро пожаловать." }, { 1.35, "Ратирил отправил мне магическое послание – сообщил о тебе и о том, что у тебя есть потенциал." }, { 8.26, "Теперь, когда я вижу тебя своими глазами, мне ясно, почему он предложил тебе встретиться со мной." }, { 15.64, "У тебя ярко выраженная чародейская аура." }, { 18.75, "Среди нас осталось мало тех, кому хватает способностей, не говоря уже о воле, делать то, что должно, ради спасения нашего дома." }, { 28.44, "Достанет ли тебе смелости и силы, чтобы помочь Высшему ордену?" }, { 33.24, "Скоро мы это узнаем." } } } } },
    [92700] = { d = 27.8, g = 1, v = "skyborne-female", n = { m = 307, f = 308 }, c = { m = { { 0.00, "Ты только что прибыл в Валанаар и, наверное, хочешь встретиться с другими Ваятелями ветра." }, { 6.78, "Нынешняя великая небовидица и её приближённые обосновались недалеко от центра Валанаара." }, { 13.28, "Будь настороже: Ваятели ветра и Высший орден друг с другом не ладят." }, { 18.43, "Вторых лучше обходи стороной." }, { 20.74, "У нас и так хватает хлопот из-за культа – стычки между фракциями на улицах города я не потерплю." } }, f = { { 0.00, "Ты только что прибыла в Валанаар и, наверное, хочешь встретиться с другими Ваятелями ветра." }, { 6.81, "Нынешняя великая небовидица и её приближённые обосновались недалеко от центра Валанаара." }, { 13.28, "Будь настороже: Ваятели ветра и Высший орден друг с другом не ладят." }, { 18.40, "Вторых лучше обходи стороной." }, { 20.69, "У нас и так хватает хлопот из-за культа – стычки между фракциями на улицах города я не потерплю." } } }, t = { d = 28.7, g = 1, v = "skyborne-female", n = { m = 299, f = 302 }, c = { m = { { 0.00, "Старейшина Янтарный Ветер отправила мне послание, где рассказала о тебе и твоих деяниях в деревне Шен'дар." }, { 8.41, "Добро пожаловать, друг." }, { 10.27, "У тебя сильная аура, и тебе явно благоволят духи." }, { 14.33, "Одарённых небесным взором среди нас становится всё меньше, а без них Зефрису не пережить эти тяжёлые времена." }, { 22.81, "Хорошо, что твой путь привёл тебя ко мне." }, { 25.95, "Мне не терпится узнать тебя получше." } }, f = { { 0.00, "Старейшина Янтарный Ветер отправила мне послание, где рассказала о тебе и твоих деяниях в деревне Шен'дар." }, { 8.24, "Добро пожаловать, подруга." }, { 10.33, "У тебя сильная аура, и тебе явно благоволят духи." }, { 14.31, "Одарённых небесным взором среди нас становится всё меньше, а без них Зефрису не пережить эти тяжёлые времена." }, { 22.62, "Хорошо, что твой путь привёл тебя ко мне." }, { 25.69, "Мне не терпится узнать тебя получше." } } } } },
    [92701] = { d = 34.6, v = "skyborne-female", n = { x = 386 }, c = { x = { { 0.00, "Пока похоже, что столп и деревня в безопасности, и я хочу попросить тебя доставить этот доклад Валеннии Штормовой Кулак в Валанаар, на юго-восточный край острова." }, { 11.97, "Валенния – лидер миротворцев на острове, и она должна узнать, что здесь произошло." }, { 18.03, "Культ быстро разрастается, и миротворцы до сих пор избегали открытого столкновения, но дальше так продолжаться не может." }, { 26.67, "Валанаар должен быть готов к бою." }, { 29.20, "Как бы то ни было, спасибо тебе." }, { 31.59, "В Шен'даре ты всегда найдёшь верных друзей." } } }, t = { d = 35.5, g = 1, v = "skyborne-female", n = { m = 357, f = 358 }, c = { m = { { 0.00, "*Читая письмо, Валенния мрачнеет.*" }, { 3.20, "Аонда доверила тебе доставку послания и хорошо о тебе отзывается в нём." }, { 8.59, "Я тоже постараюсь тебе доверять." }, { 11.09, "Прежде чем продолжить разговор, мне нужно посоветоваться с теми немногими миротворцами, что ещё остались со мной, и разработать план на случай нападения культа." }, { 22.81, "Отдохни пока в Валанааре." }, { 24.77, "Если будешь искать себе занятие, многим горожанам, скорее всего, не помешает помощь такого молодого и сильного искателя приключений, как ты." } }, f = { { 0.00, "*Читая письмо, Валенния мрачнеет.*" }, { 3.28, "Аонда доверила тебе доставку послания и хорошо о тебе отзывается в нём." }, { 8.47, "Я тоже постараюсь тебе доверять." }, { 10.87, "Прежде чем продолжить разговор, мне нужно посоветоваться с теми немногими миротворцами, что ещё остались со мной, и разработать план на случай нападения культа." }, { 22.17, "Отдохни пока в Валанааре." }, { 24.05, "Если будешь искать себе занятие, многим горожанам, скорее всего, не помешает помощь такой молодой и сильной искательницы приключений, как ты." } } } } },
    [92703] = { d = 32.6, g = 1, v = "skyborne-female", n = { m = 318, f = 318 }, c = { m = { { 0.00, "Не дело и дальше называть тебя незнакомцем..." }, { 3.37, "Спасибо тебе." }, { 4.43, "Если ты всё равно собираешься возвращаться, может, расскажешь Альвариону, что здесь случилось?" }, { 11.23, "И ещё передай, что когда встанет на ноги, пусть приведёт на ферму Ваятеля ветра: пусть взглянет на того голема и убедится, что он не будет опасен для нашего... для нашей семьи." }, { 23.92, "*Аамелия с нежностью прикасается к животу.*" }, { 27.44, "Он ещё не знает об этом." }, { 29.26, "Пусть эта деталь пока останется между нами." } }, f = { { 0.00, "Не дело и дальше называть тебя незнакомкой..." }, { 3.38, "Спасибо тебе." }, { 4.44, "Если ты всё равно собираешься возвращаться, может, расскажешь Альвариону, что здесь случилось?" }, { 11.27, "И ещё передай, что когда встанет на ноги, пусть приведёт на ферму Ваятеля ветра: пусть взглянет на того голема и убедится, что он не будет опасен для нашего... для нашей семьи." }, { 24.00, "*Аамелия с нежностью прикасается к животу.*" }, { 27.68, "Он ещё не знает об этом." }, { 29.47, "Пусть эта деталь пока останется между нами." } } }, t = { d = 30.7, g = 1, v = "skyborne-male", n = { m = 230, f = 231 }, c = { m = { { 0.00, "*Вы рассказываете Альвариону, что произошло в саду.*" }, { 4.16, "*Он слушает со слезами на глазах.*" }, { 6.80, "Даже не знаю, как тебя отблагодарить, друг мой." }, { 10.67, "Я пришёл в Валанаар в поисках надежды и был почти уверен, что моё желание тщетно." }, { 17.31, "Но я нашёл героя." }, { 18.72, "Настоящего, как в старых легендах до нашего исхода в Небесную высь." }, { 24.24, "Я не забуду, что ты для нас сделал." }, { 27.07, "Тебе всегда будут рады в доме Поля Ветров." } }, f = { { 0.00, "*Вы рассказываете Альвариону, что произошло в саду.*" }, { 4.25, "*Он слушает со слезами на глазах.*" }, { 6.96, "Даже не знаю, как тебя отблагодарить, друг мой." }, { 10.81, "Я пришёл в Валанаар в поисках надежды и был почти уверен, что моё желание тщетно." }, { 17.40, "Но я нашёл героя." }, { 18.81, "Настоящего, как в старых легендах до нашего исхода в Небесную высь." }, { 24.28, "Я не забуду, что ты для нас сделала." }, { 27.17, "Тебе всегда будут рады в доме Поля Ветров." } } } } },
    [92706] = { d = 19.0, v = "narrator", n = { x = 190 }, c = { x = { { 0.00, "Внимание всем рыболовам!" }, { 2.02, "В водах около пристани завелась огромная акула, которая нападает на матросов и небольшие суда." }, { 9.93, "Работники пристани дали ей прозвище \"Брууз\"." }, { 13.66, "Тот, кто принесёт мне её плавник, будет щедро вознаграждён!" }, { 18.37, "– Газлоу" } } }, t = { d = 17.7, v = "named/3391", n = { x = 190 }, c = { x = { { 0.00, "Наконец-то кто-то прикончил эту тварь!" }, { 2.89, "Ты хоть представляешь, как сложно сколотить команду и выйти в море, когда все кругом кричат \"Акула!" }, { 10.29, "Акула!\"?" }, { 10.97, "Вот возьму и сварю плавник этого чудища себе на ужин: чтобы уж точно посмеяться последним." } } } } },
    [92707] = { d = 18.7, v = "narrator", n = { x = 209 }, c = { x = { { 0.00, "Наручи, которые вы еле стянули с трупа голиафа, просто огромны." }, { 4.78, "Вы можете просунуть в них всю руку до плеча, не касаясь внутренней поверхности." }, { 10.56, "Отнесите их в Павший Молот, чтобы предупредить местных обитателей." }, { 15.48, "Драм Жёлчный должен знать, с чем он имеет дело." } } } },
    [92708] = { d = 25.7, g = 1, v = "skyborne-female", n = { m = 283, f = 287 }, c = { m = { { 0.00, "Ваятели ветра работают не покладая рук, чтобы отвратить беду, грозящую острову Зефрис." }, { 6.51, "В поисках пропавших духов ветра мы сделали несколько неожиданных открытий и составляем план, как спасти остров." }, { 14.76, "Правда, нам понадобятся молодые и крепкие искатели приключений вроде тебя." }, { 20.33, "Прошу, если у тебя есть свободная минутка, давай поговорим об этом." } }, f = { { 0.00, "Ваятели ветра работают не покладая рук, чтобы отвратить беду, грозящую острову Зефрис." }, { 6.54, "В поисках пропавших духов ветра мы сделали несколько неожиданных открытий и составляем план, как спасти остров." }, { 14.84, "Правда, нам понадобятся молодые и крепкие искательницы приключений вроде тебя." }, { 20.70, "Прошу, если у тебя есть свободная минутка, давай поговорим об этом." } } }, t = { d = 25.5, g = 1, v = "skyborne-female", n = { m = 260, f = 260 }, c = { m = { { 0.00, "Теперь понимаешь?" }, { 1.45, "За стенами Небесной выси раскинулся целый мир, полный знаний и возможностей." }, { 7.64, "Наш дом всегда будет здесь, но я считаю, что спасение таится где-то внизу." }, { 13.60, "Нужно отправиться на Азерот и найти способ спасти остров Зефрис." }, { 18.91, "Таков путь." }, { 19.85, "Достаточно ли ты отважен, чтобы присоединиться к нам, когда придёт время?" } }, f = { { 0.00, "Теперь понимаешь?" }, { 1.44, "За стенами Небесной выси раскинулся целый мир, полный знаний и возможностей." }, { 7.54, "Наш дом всегда будет здесь, но я считаю, что спасение таится где-то внизу." }, { 13.43, "Нужно отправиться на Азерот и найти способ спасти остров Зефрис." }, { 18.67, "Таков путь." }, { 19.61, "Достаточно ли ты отважна, чтобы присоединиться к нам, когда придёт время?" } } } } },
    [92709] = { d = 20.4, g = 1, v = "skyborne-male", n = { m = 202, f = 202 }, c = { m = { { 0.00, "Твоё благородное происхождение неоспоримо." }, { 3.34, "Я вижу его в твоих глазах, как ясное небо." }, { 6.90, "Ты один из нас, и именно такие молодые эльфы, как ты, помогут спасти наш дом." }, { 13.07, "Но сначала позволь рассказать о наших планах и целях – здесь, на Зефрисе, и за его пределами." } }, f = { { 0.00, "Твоё благородное происхождение неоспоримо." }, { 3.34, "Я вижу его в твоих глазах, как ясное небо." }, { 6.90, "Ты одна из нас, и именно такие молодые эльфы, как ты, помогут спасти наш дом." }, { 13.07, "Но сначала позволь рассказать о наших планах и целях – здесь, на Зефрисе, и за его пределами." } } }, t = { d = 33.4, v = "skyborne-male", n = { x = 369 }, c = { x = { { 0.00, "Теперь ты понимаешь?" }, { 1.55, "Возрождение древней магии наших предшественников – ключ к разгадке тайн острова Зефрис и к нашему светлому будущему." }, { 10.16, "Чтобы спасти наш дом, мы должны заново открыть то, что утратили за прошедшие тысячелетия." }, { 16.75, "Ответ кроется на Азероте, и маги Кирин-Тора готовы указать нам путь." }, { 21.87, "Пока мы готовимся к отбытию, поговори с другими членами Высшего ордена в Валанааре." }, { 28.12, "У многих из них есть важные дела, с которыми не помешала бы твоя помощь." } } } } },
    [92727] = { d = 33.8, v = "skyborne-male", n = { x = 370 }, c = { x = { { 0.00, "Поиск знаний – наиглавнейшая задача Высшего ордена, но никогда ещё это не было так опасно, как теперь на Зефрисе." }, { 8.34, "Один из наших учёных, Филлион Огненная Дымка, отправился на Шен'дарское нагорье, чтобы изучить магическую энергию ветра, которая накапливается в тех краях." }, { 19.73, "С тех пор он пропал, и я боюсь, что в пути с ним что-то случилось." }, { 24.50, "Если можешь, пожалуйста, найди его." }, { 27.22, "В последний раз его видели на дороге, ведущей от Валанаара на запад к Шен'дарскому нагорью." } } }, t = { d = 14.6, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "*Вы видите на клапане брошенной сумки вкрапления чего-то, похожего на засохшую кровь.*" }, { 7.02, "*Разглядывая пятна, вы также замечаете на клапане вышивку с именем: \"Филлион Огненная Дымка\".*" } } } } },
    [92741] = { d = 32.6, v = "skyborne-female", n = { x = 366 }, c = { x = { { 0.00, "Теневейный лес очень опасен, и простые искатели приключений туда обычно не ходят." }, { 6.11, "Однако недавно популяция визгунов возросла настолько, что эти звери начали покидать лес в поиске новых территорий." }, { 14.71, "Я хочу изучить алхимические свойства их когтей, так что, сократив численность этих особей, мы можем заодно почерпнуть полезные научные знания." }, { 25.32, "Отправляйся в Теневейный лес и поохоться на визгунов." }, { 29.28, "Добудь как можно больше когтей и принеси мне." } } }, t = { d = 10.7, g = 1, v = "skyborne-female", n = { x = 90 }, c = { m = { { 0.00, "Сколько когтей – вот это, я понимаю, улов!" }, { 3.81, "Мне уже не терпится их изучить." }, { 6.59, "Благодарю тебя за службу Высшему ордену, герой." } }, f = { { 0.00, "Сколько когтей – вот это, я понимаю, улов!" }, { 3.76, "Мне уже не терпится их изучить." }, { 6.50, "Благодарю тебя за службу Высшему ордену, героиня." } } } } },
    [92742] = { d = 13.5, v = "nightelf-female#52", n = { x = 169 }, c = { x = { { 0.00, "Нужно отыскать источник яда, поразившего эти земли, и понять его природу." }, { 5.03, "Начнём с исследования подземных вод под местными фермами." }, { 8.75, "Ступай во владение Янсена и на ферму Мольсена и возьми пробы из колодцев." } } }, t = { d = 2.9, v = "nightelf-female#52", n = { x = 24 }, c = { x = { { 0.00, "Благодарю." }, { 1.04, "Дай-ка посмотреть..." } } } } },
    [92743] = { d = 35.4, v = "named/5398", n = { x = 319 }, c = { x = { { 0.00, "Мы, самый могучий клан кентавров в этих землях, заслуживаем одеяний, которые отражают нашу силу!" }, { 8.70, "Больше всего они нужны Варугу." }, { 11.60, "Шлем... нет, корона!" }, { 13.37, "Корона завоевателя!" }, { 15.14, "Я слышал легенды о могучем воителе из-за моря." }, { 19.41, "Ступай в место, которое зовётся Бесплодными землями, и найди там склеп." }, { 25.69, "Возвращайся, лишь когда отыщешь там корону." }, { 29.56, "Если это сделаешь, я раскрою тебе величайшую силу племени Маграм." } } } },
    [92744] = { d = 24.6, v = "nightelf-female#52", n = { x = 293 }, c = { x = { { 0.00, "Порча, которая одолевает посевы в Западном крае, просочилась и в океан." }, { 4.93, "Если она заразит местную рыбу, это может привести к голоду в Штормграде." }, { 10.05, "Собери жабры мурлоков на побережье и принеси мне." }, { 13.44, "Мурлоки крайне живучие существа, но их физиология такова, что они чутко реагируют на любые загрязнения." }, { 20.53, "Если в морской воде есть яд, он обязательно будет в их жабрах." } } }, t = { d = 5.8, v = "nightelf-female#52", n = { x = 52 }, c = { x = { { 0.00, "Понятно... жабры, похоже, пока чистые." }, { 3.47, "Но расслабляться нам нельзя." } } } } },
    [92745] = { d = 25.2, g = 1, v = "nightelf-female#52", n = { m = 320, f = 321 }, c = { m = { { 0.00, "В образцах колодезной воды, которые ты собрал, содержатся ядовитые металлы!" }, { 4.90, "Если сейчас же не положить конец этой порче, на здешних полях не будет урожаев ещё несколько десятилетий." }, { 11.78, "Братство Справедливости захватило рудники Западного края и заставляет местных обитателей добывать ресурсы." }, { 18.66, "Сорви их планы, убив шахтёров на руднике Янго на севере и прииске на Золотом Берегу на западе." } }, f = { { 0.00, "В образцах колодезной воды, которые ты собрала, содержатся ядовитые металлы!" }, { 5.06, "Если сейчас же не положить конец этой порче, на здешних полях не будет урожаев ещё несколько десятилетий." }, { 12.07, "Братство Справедливости захватило рудники Западного края и заставляет местных обитателей добывать ресурсы." }, { 19.09, "Сорви их планы, убив шахтёров на руднике Янго на севере и прииске на Золотом Берегу на западе." } } }, t = { d = 5.4, v = "nightelf-female#52", n = { x = 51 }, c = { x = { { 0.00, "Отлично." }, { 0.74, "Но, боюсь, источник яда находится где-то в другом месте..." } } } } },
    [92747] = { d = 25.0, g = 1, v = "nightelf-female#52", n = { m = 294, f = 295 }, c = { m = { { 0.00, "Странно." }, { 0.62, "Судя по всему, яд появился не на том руднике, который ты обследовал." }, { 5.29, "Говорят, Мёртвые копи под городом Луноречье – самые глубокие и обширные шахты в Западном Крае, но их забросили ещё во времена Первой войны." }, { 14.87, "Неужели там снова что-то происходит?" }, { 17.42, "Прошу, отправляйся в Луноречье, и отыщи свидетельства любой активности в шахтах." }, { 22.95, "Это наша последняя зацепка!" } }, f = { { 0.00, "Странно." }, { 0.63, "Судя по всему, яд появился не на том руднике, который ты обследовала." }, { 5.39, "Говорят, Мёртвые копи под городом Луноречье – самые глубокие и обширные шахты в Западном Крае, но их забросили ещё во времена Первой войны." }, { 15.03, "Неужели там снова что-то происходит?" }, { 17.60, "Прошу, отправляйся в Луноречье, и отыщи свидетельства любой активности в шахтах." }, { 23.18, "Это наша последняя зацепка!" } } }, t = { d = 1.5, v = "nightelf-female#52", n = { x = 11 }, c = { x = { { 0.00, "Что это такое?" } } } } },
    [92748] = { d = 25.4, g = 1, v = "nightelf-female#52", n = { m = 316, f = 317 }, c = { m = { { 0.00, "Припасы, которые ты обнаружил, указывают, что кто-то развил в Мёртвых копях бурную деятельность." }, { 6.23, "Без сомнения, именно это и есть источник токсина, который отравляет поля Западного Края." }, { 12.05, "Нужно как можно скорее положить этому конец." }, { 15.05, "Что бы ни ждало нас внизу, уничтожить это будет непросто." }, { 18.81, "Ступай в Квартал Дворфов в Штормграде и отыщи инженера, который сможет снабдить нас взрывчаткой." } }, f = { { 0.00, "Припасы, которые ты обнаружила, указывают, что кто-то развил в Мёртвых копях бурную деятельность." }, { 6.39, "Без сомнения, именно это и есть источник токсина, который отравляет поля Западного Края." }, { 12.31, "Нужно как можно скорее положить этому конец." }, { 15.36, "Что бы ни ждало нас внизу, уничтожить это будет непросто." }, { 19.18, "Ступай в Квартал Дворфов в Штормграде и отыщи инженера, который сможет снабдить нас взрывчаткой." } } }, t = { d = 2.1, v = "gnome-female", n = { x = 23 }, c = { x = { { 0.00, "Хочешь что-нибудь взорвать?" } } } } },
    [92749] = { d = 5.4, v = "gnome-female", n = { x = 46 }, c = { x = { { 0.00, "Промышленный саботаж?" }, { 2.11, "Я вся внимание!" }, { 3.60, "Начнём с динамита..." } } }, t = { d = 7.6, v = "gnome-female", n = { x = 66 }, c = { x = { { 0.00, "Отличное начало." }, { 1.62, "Теперь добавим немного мощности... чтобы всё сработало как часы." } } } } },
    [92750] = { d = 17.5, v = "gnome-female", n = { x = 187 }, c = { x = { { 0.00, "Полагаю, тебе нужен \"управляемый\" взрыв?" }, { 2.94, "Это не так весело, но если не хочешь потерять пару конечностей, то сойдёт." }, { 9.17, "Боюсь, у меня нет дистанционного детонатора." }, { 12.38, "Сходи к ребятам из разведки Штормграда – у них должно что-нибудь найтись." } } }, t = { d = 3.2, v = "human-male#116", n = { x = 23 }, c = { x = { { 0.00, "Хм-м... ищешь что-то конкретное?" } } } } },
    [92751] = { d = 31.5, v = "human-male#116", n = { x = 410 }, c = { x = { { 0.00, "Хочешь что-то уничтожить?" }, { 1.68, "Это имеет какое-то отношение к тому, чем ты занимаешься в Луноречье?" }, { 6.09, "Не удивляйся – Штормградское разведывательное управление в курсе всего, что происходит в землях Штормграда." }, { 12.87, "Если собираешься устроить взрыв в пещерах под Западным краем, обязательно сперва выберись на поверхность." }, { 19.60, "Вот, возьми этот дистанционный детонатор." }, { 22.26, "Это новая разработка наших инженеров." }, { 24.76, "Ах да, и будет лучше, если ты не станешь рассказывать о моём участии в этой затее своей эльфийской подруге." } } }, t = { d = 4.4, v = "gnome-female", n = { x = 38 }, c = { x = { { 0.00, "Прекрасно!" }, { 1.05, "Как раз такой детонатор нам и нужен!" } } } } },
    [92752] = { d = 5.0, v = "gnome-female", n = { x = 46 }, c = { x = { { 0.00, "Ну вот, бомба готова!" }, { 2.01, "Только поаккуратнее с детонатором." } } }, t = { d = 2.0, g = 1, v = "nightelf-female#52", n = { m = 19, f = 20 }, c = { m = { { 0.00, "Хорошо, что ты вернулся." } }, f = { { 0.00, "Хорошо, что ты вернулась." } } } } },
    [92753] = { d = 20.6, v = "nightelf-female#52", n = { x = 249 }, c = { x = { { 0.00, "Скорее всего, источником яда является какой-то крупный металлургический горн." }, { 5.33, "Проберись в Мёртвые копи и найди этот горн, а затем заложи взрывчатку." }, { 10.17, "Я буду ждать тебя в холмах за Луноречьем." }, { 13.02, "Мы детонируем взрывчатку, когда ты вернёшься." }, { 16.05, "Надеюсь, когда этот горн будет уничтожен, земля сможет исцелиться." } } }, t = { d = 5.4, g = 1, v = "nightelf-female#52", n = { m = 53, f = 54 }, c = { m = { { 0.00, "Ты нашёл горн и заложил взрывчатку..." }, { 2.93, "Теперь осталось только одно." } }, f = { { 0.00, "Ты нашла горн и заложила взрывчатку..." }, { 3.13, "Теперь осталось только одно." } } } } },
    [92754] = { d = 28.1, g = 1, v = "named/5398", n = { m = 284, f = 284 }, c = { m = { { 0.00, "Наши воины продвигаются всё дальше на юг, в глубину проклятой Долины Костей и за её пределы." }, { 7.17, "Хотя ты в клане на хорошем счету, я недостаточно тебе доверяю, чтобы рассказать об их целях, да и вряд ли тебе это интересно, чужеземец." }, { 17.77, "Скажу лишь, что им нужно много мощных зелий защиты от тёмной магии, чтобы выжить." }, { 24.17, "Принеси мне их, и я замолвлю за тебя словечко." } }, f = { { 0.00, "Наши воины продвигаются всё дальше на юг, в глубину проклятой Долины Костей и за её пределы." }, { 7.29, "Хотя ты в клане на хорошем счету, я недостаточно тебе доверяю, чтобы рассказать об их целях, да и вряд ли тебе это интересно, чужеземка." }, { 18.08, "Скажу лишь, что им нужно много мощных зелий защиты от тёмной магии, чтобы выжить." }, { 24.59, "Принеси мне их, и я замолвлю за тебя словечко." } } } },
    [92755] = { d = 33.8, v = "named/5398", n = { x = 371 }, c = { x = { { 0.00, "С каждым днём наши добытчики приносят всё меньше снаряжения, собранного у павших искателей приключений." }, { 7.96, "Использовать его по прямому назначению мы не можем, но многие образцы идут в переработку." }, { 14.87, "Магические предметы попадают ко мне, так как я могу добыть из них реагенты для зачаровывания оружия – особенно того, что достаётся нашим ветроловам." }, { 26.10, "Мне нужен запас великой таинственной субстанции, чтобы достойно снарядить воинов в следующую вылазку." } } } },
    [92811] = { d = 36.7, v = "tauren-male", n = { x = 351 }, c = { x = { { 0.00, "Война научила нас одному: деньги — это сила." }, { 3.95, "Все кентавры Пустошей договорились вести обмен резным деревом, на котором запечатлены сказания о славе и победах кентавров." }, { 14.57, "Это единственная передышка от битв, и торговать с другими кланами дозволено лишь самым рассудительным." }, { 23.24, "Я видел, как твой народ торгует золотом и серебром." }, { 27.66, "Для нас оно ничего не стоит — как и наши тотемы для вас." }, { 32.46, "Принеси мне несколько, и клан Маграм будет доволен." } } }, t = { d = 4.6, v = "human-male", n = { x = 42 }, c = { x = { { 0.00, "Мудрое решение, чужеземец." }, { 2.49, "Твою щедрость запомнят." } } } } },
    [92812] = { t = { d = 11.4, v = "named/5398", n = { x = 113 }, c = { x = { { 0.00, "Я добавлю это к нашим запасам." }, { 2.58, "Благодаря твоей помощи наша сила растёт, но нам предстоит ещё долгий путь, если мы хотим одолеть клан Маграм." } } } } },
    [92814] = { d = 35.8, v = "named/5398", n = { x = 403 }, c = { x = { { 0.00, "Халея, моя спутница, получила задание усилить нашу экипировку магической энергией." }, { 6.16, "Я ничего не понимаю в наложении чар, но как кентавр, ответственный за то, чтобы в деревне были необходимые припасы, знаю, что Халея частенько запаздывает с результатами – и не по своей вине." }, { 19.95, "Мне хочется подарить ей какую-нибудь простую одежду, на которой она могла бы практиковаться в своём ремесле." }, { 27.83, "Не раз я видел, как искатели приключений надевают во время пыльных бурь простые маски." }, { 34.13, "Можешь мне такую добыть?" } } } },
    [92817] = { d = 34.7, v = "named/5397", n = { x = 353 }, c = { x = { { 0.00, "Несмотря на то, что мои сородичи постоянно погибают от ран, нанесённых клинками и стрелами, их практически невозможно убедить носить доспехи." }, { 11.31, "Мне приказали создать жилет, защищающий бойцов, но не вызывающий \"чесотки\", на которую они так жалуются." }, { 19.75, "Припасов у нас мало, поэтому я не готова тратить ценную кожу на всякую чепуху." }, { 26.21, "Сможешь ли ты принести мне портупею, которая подошла бы крупному кентавру?" }, { 32.23, "Я хочу освоить твою технологию." } } } },
    [92818] = { d = 20.9, g = 1, v = "named/5398", n = { m = 174, f = 174 }, c = { m = { { 0.00, "НАМ НУЖНО БОЛЬШЕ ОРУЖИЯ." }, { 2.43, "БОЛЬШЕ!" }, { 3.21, "ОРУЖИЯ!" }, { 3.99, "КАК ЕЩЁ ПЛЕМЯ МАГРАМ СОКРУШИТ ЖАЛКИЙ КЛАН ГЕЛКИС?" }, { 8.75, "Я ХОЧУ ВИДЕТЬ, ЧТО ТЫ СПОСОБЕН СДЕЛАТЬ, ЧУЖЕЗЕМЕЦ." }, { 13.60, "ПРИНЕСИ МНЕ ТОПОРЫ." }, { 15.51, "БОЛЬШИЕ." }, { 16.37, "НЕТ, НЕ ПРОСТО БОЛЬШИЕ!" }, { 18.63, "МАССИВНЫЕ!" }, { 19.67, "И ПОТОРОПИСЬ." } }, f = { { 0.00, "НАМ НУЖНО БОЛЬШЕ ОРУЖИЯ." }, { 2.44, "БОЛЬШЕ!" }, { 3.22, "ОРУЖИЯ!" }, { 4.00, "КАК ЕЩЁ ПЛЕМЯ МАГРАМ СОКРУШИТ ЖАЛКИЙ КЛАН ГЕЛКИС?" }, { 8.78, "Я ХОЧУ ВИДЕТЬ, ЧТО ТЫ СПОСОБНА СДЕЛАТЬ, ЧУЖЕЗЕМКА." }, { 13.65, "ПРИНЕСИ МНЕ ТОПОРЫ." }, { 15.57, "БОЛЬШИЕ." }, { 16.44, "НЕТ, НЕ ПРОСТО БОЛЬШИЕ!" }, { 18.70, "МАССИВНЫЕ!" }, { 19.74, "И ПОТОРОПИСЬ." } } } },
    [92819] = { d = 4.4, v = "nightelf-female#52", n = { x = 49 }, c = { x = { { 0.00, "Мы почти закончили." }, { 1.54, "Используй детонатор и заверши начатое." } } }, t = { d = 7.9, v = "nightelf-female#52", n = { x = 95 }, c = { x = { { 0.00, "Не знаю, что сказать." }, { 1.51, "Даже не верится, что для Штормграда военные амбиции превыше жизней его собственных подданных." } } } } },
    [92834] = { d = 35.8, v = "skyborne-male", n = { x = 414 }, c = { x = { { 0.00, "Когда культ начал свою кампанию насилия, миротворцы и Ваятели ветра ответили показной бравадой." }, { 6.99, "Я посчитал, что глупо ещё больше разжигать конфликт, и выступил за мирный диалог." }, { 12.87, "Вчера я отправил своего друга Белатаана Яркая Мечта к святилищу Акира, надеясь наладить этот диалог." }, { 20.31, "Только что прибыла шкатулка с языком Белатаана, обмакнутым в серебряный пигмент." }, { 26.12, "Теперь я вижу, что договариваться с культом бесполезно." }, { 30.11, "Убей всех сектантов, которых повстречаешь, и принеси мне их молитвенные талисманы." } } }, t = { d = 26.2, v = "skyborne-male", n = { x = 246 }, c = { x = { { 0.00, "Высший орден гордится своим прагматизмом и логикой, а логика показывает, что избежание конфликта и напрасных потерь – наиболее разумное решение в большинстве ситуаций." }, { 12.08, "*Глаза Элаадрина загораются и искрятся от чародейской энергии.*" }, { 17.44, "Однако сектанты приняли нашу осмотрительность за слабость, и они даже не представляют, как серьёзно поплатятся за эту ошибку." } } } } },
    [92840] = { d = 33.4, v = "skyborne-male", n = { x = 369 }, c = { x = { { 0.00, "Филлиона отправили к Дозорным монолитам на Шен'дарском нагорье с особым устройством, чтобы измерить и изучить тамошнюю стихийную энергию." }, { 10.25, "Возьми вот это – эзотерический каталог – и с его помощью извлеки данные из огромных ветряных каменных образований, что там высятся." }, { 20.02, "Но будь начеку: Ваятели ветра наверняка теперь ревниво стерегут это место." }, { 25.69, "Если кто-то попытается тебе помешать... что ж, делай что должно." }, { 30.54, "Моё терпение к их вмешательству иссякло." } } }, t = { d = 30.7, g = 1, v = "skyborne-male", n = { m = 319, f = 320 }, c = { m = { { 0.00, "Будь моя воля, сегодня не пролилось бы ни капли крови Ваятелей Ветра." }, { 5.33, "Но вина за эту бессмысленную стычку лежит только на них." }, { 9.64, "Мы лишь хотели собрать сведения, а они прибегли к насилию." }, { 14.09, "К сожалению, молва уже разошлась, и Ваятели Ветра вовсю кричат о \"побоище\"." }, { 19.90, "Они не посмеют напасть на нас здесь, в Валанааре, но точно не забудут о случившемся." }, { 26.19, "Ты оказал огромную услугу Высшему ордену." }, { 29.41, "Благодарю." } }, f = { { 0.00, "Будь моя воля, сегодня не пролилось бы ни капли крови Ваятелей Ветра." }, { 5.33, "Но вина за эту бессмысленную стычку лежит только на них." }, { 9.64, "Мы лишь хотели собрать сведения, а они прибегли к насилию." }, { 14.09, "К сожалению, молва уже разошлась, и Ваятели Ветра вовсю кричат о \"побоище\"." }, { 19.90, "Они не посмеют напасть на нас здесь, в Валанааре, но точно не забудут о случившемся." }, { 25.83, "Ты оказала огромную услугу Высшему ордену." }, { 30.01, "Благодарю." } } } } },
    [92841] = { d = 31.0, g = 1, v = "named/5398", n = { m = 298, f = 299 }, c = { m = { { 0.00, "Пора тебе узнать о нашем великом открытии, чужеземец... но расскажет тебе о нём не Варуг." }, { 7.41, "Ступай на юг, на другой конец деревни." }, { 10.60, "Найди большого вонючего кентавра по имени Оргрул." }, { 14.74, "Когда придёшь на место, поймёшь." }, { 17.34, "И его сразу узнаешь." }, { 19.12, "Если он решит, что ты достоин, то всё тебе расскажет." }, { 23.49, "А если нет..." }, { 24.60, "Что ж, тогда можешь просто порадоваться за Варуга, у которого есть новая корона." } }, f = { { 0.00, "Пора тебе узнать о нашем великом открытии, чужеземка... но расскажет тебе о нём не Варуг." }, { 7.37, "Ступай на юг, на другой конец деревни." }, { 10.54, "Найди большого вонючего кентавра по имени Оргрул." }, { 14.67, "Когда придёшь на место, поймёшь." }, { 17.25, "И его сразу узнаешь." }, { 19.02, "Если он решит, что ты достойна, то всё тебе расскажет." }, { 23.45, "А если нет..." }, { 24.55, "Что ж, тогда можешь просто порадоваться за Варуга, у которого есть новая корона." } } }, t = { d = 38.9, g = 1, v = "named/5398", n = { m = 364, f = 365 }, c = { m = { { 0.00, "Значит, слухи правдивы." }, { 2.09, "Жаль, что Варуг гонял тебя с пустячными поручениями." }, { 6.57, "Зато ты доказал, чего стоишь." }, { 9.20, "Взгляни вниз, в долину, – что ты видишь?" }, { 12.60, "Кости и тела." }, { 13.84, "Бродящую нежить." }, { 15.31, "И Голиафов-близнецов." }, { 17.08, "Это место было проклято задолго до нашего прихода, и, думаю, таким оно останется ещё много поколений." }, { 25.97, "Наш клан первым осмелился спуститься навстречу тамошним ужасам, и только нам достанется его сила." }, { 34.32, "Жаждешь ли ты, как и я, властвовать над всеми Пустошами?" } }, f = { { 0.00, "Значит, слухи правдивы." }, { 2.05, "Жаль, что Варуг гонял тебя с пустячными поручениями." }, { 6.46, "Зато ты доказала, чего стоишь." }, { 9.12, "Взгляни вниз, в долину, – что ты видишь?" }, { 12.47, "Кости и тела." }, { 13.69, "Бродящую нежить." }, { 15.13, "И Голиафов-близнецов." }, { 16.88, "Это место было проклято задолго до нашего прихода, и, думаю, таким оно останется ещё много поколений." }, { 25.63, "Наш клан первым осмелился спуститься навстречу тамошним ужасам, и только нам достанется его сила." }, { 33.84, "Жаждешь ли ты, как и я, властвовать над всеми Пустошами?" } } } } },
    [92842] = { d = 23.1, v = "human-male", n = { x = 271 }, c = { x = { { 0.00, "Мой кузен когда-то говорил, что собирается побывать на горе Хиджал и посмотреть, что там творится." }, { 6.61, "Глупая затея." }, { 7.59, "Хиджал – на другом краю света: письмо может идти к нему месяцами, если он вообще отыщет почтовый ящик." }, { 14.75, "Если вдруг, паче чаяния, окажешься в той части мира, мне было бы спокойнее, если бы кто-нибудь проведал моего дурака-кузена." } } } },
    [92844] = { d = 28.5, v = "named/5398", n = { x = 290 }, c = { x = { { 0.00, "Долину Костей пронизывает некая некромантская энергия." }, { 4.46, "Причины этого нам неизвестны и неинтересны." }, { 7.96, "Эта магия теперь принадлежит нам, и те, кто не сражается клинком или молотом, обучаются ей." }, { 15.34, "Если думаешь, что я сразу дам тебе сложное задание, то заблуждаешься." }, { 20.96, "Пока что отправляйся в Долину Костей и принеси мне оттуда кости." }, { 26.22, "Уверен, с этим ты справишься." } } }, t = { d = 25.0, v = "named/5398", n = { x = 71 }, c = { x = { { 0.00, "*Оргрул начинает пересчитывать кости, но, дойдя до двузначных чисел, путается и в конце концов сбивается со счёта.*" }, { 9.12, "*Он пробует ещё раз, но на полпути сердито косится на вас, заметив, как перекосилось ваше лицо.*" }, { 16.56, "Ба." }, { 16.89, "Потом посчитаю." }, { 18.37, "На вид хватает." }, { 19.77, "И лучше бы тебе меня не обманывать." }, { 23.06, "Это я оставлю у себя." } } } } },
    [92846] = { d = 32.6, g = 1, v = "named/5398", n = { m = 330, f = 331 }, c = { m = { { 0.00, "Ты обратил внимание на разгуливающих здесь жалких кентавров?" }, { 4.70, "Они из племени Гелкис." }, { 6.55, "Мы, племя Маграм, уже закрепились дальше в каньоне." }, { 10.68, "Когда в племени Гелкис заметили наше присутствие, некоторые из их числа решили пойти по нашим стопам." }, { 18.79, "Неизвестно, хотят ли они примкнуть к нам или бросить вызов, но точно знаю, что сородичи приговорили их к изгнанию." }, { 27.84, "Это одиночки, сующие нос туда, куда не следует." }, { 31.68, "Убей их." } }, f = { { 0.00, "Ты обратила внимание на разгуливающих здесь жалких кентавров?" }, { 4.82, "Они из племени Гелкис." }, { 6.69, "Мы, племя Маграм, уже закрепились дальше в каньоне." }, { 10.86, "Когда в племени Гелкис заметили наше присутствие, некоторые из их числа решили пойти по нашим стопам." }, { 19.06, "Неизвестно, хотят ли они примкнуть к нам или бросить вызов, но точно знаю, что сородичи приговорили их к изгнанию." }, { 28.19, "Это одиночки, сующие нос туда, куда не следует." }, { 32.07, "Убей их." } } } },
    [92847] = { d = 36.9, g = 1, v = "named/5398", n = { m = 403, f = 404 }, c = { m = { { 0.00, "Чужеземец, ты обратил внимание на оружие некромантов-изгоев?" }, { 4.66, "Мы сделаем всё, чтобы племя Гелкис сгинуло, прежде чем по-настоящему научится пользоваться некромантией, но некоторые разновидности их колдовства меня заинтересовали." }, { 17.33, "Они даже используют те же кристаллы, которые тебе велел украсть Варуг." }, { 22.90, "Думаю, некоторые их приёмы мы сможем освоить." }, { 26.38, "Отправляйся в долину и добудь немного древесины проклятых деревьев, а потом попроси у Варуга несколько кристаллов." }, { 35.22, "Я сделаю из них посохи." } }, f = { { 0.00, "Чужеземка, ты обратила внимание на оружие некромантов-изгоев?" }, { 4.69, "Мы сделаем всё, чтобы племя Гелкис сгинуло, прежде чем по-настоящему научится пользоваться некромантией, но некоторые разновидности их колдовства меня заинтересовали." }, { 17.26, "Они даже используют те же кристаллы, которые тебе велел украсть Варуг." }, { 22.78, "Думаю, некоторые их приёмы мы сможем освоить." }, { 26.23, "Отправляйся в долину и добудь немного древесины проклятых деревьев, а потом попроси у Варуга несколько кристаллов." }, { 34.99, "Я сделаю из них посохи." } } } },
    [92849] = { d = 15.4, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Судя по вашей находке, Филлиона постигла какая-то беда." }, { 4.75, "Быть может, он ещё рядом и нуждается в помощи." }, { 8.59, "Вы замечаете пещеру с северной стороны от вас." }, { 12.43, "Пожалуй, стоит продолжить поиски там." } } }, t = { d = 29.7, g = 1, v = "skyborne-male", n = { m = 296, f = 296 }, c = { m = { { 0.00, "Ох... спасибо, незнакомец." }, { 2.07, "Я возвращался с задания у Дозорных монолитов, как вдруг на меня напали Ваятели ветра." }, { 8.79, "Они притащили меня к самому входу в пещеру и бросили там еле живого, истекающего кровью." }, { 15.93, "Последнее, что я помню, это как из пещеры появился огромный крылатый зверь, схватил меня и взмыл в небо." }, { 24.15, "Если бы не ты, быть бы мне ужином для этого чудовища и его деточек." } }, f = { { 0.00, "Ох... спасибо, незнакомка." }, { 2.52, "Я возвращался с задания у Дозорных монолитов, как вдруг на меня напали Ваятели ветра." }, { 9.24, "Они притащили меня к самому входу в пещеру и бросили там еле живого, истекающего кровью." }, { 16.38, "Последнее, что я помню, это как из пещеры появился огромный крылатый зверь, схватил меня и взмыл в небо." }, { 24.60, "Если бы не ты, быть бы мне ужином для этого чудовища и его деточек." } } } } },
    [92850] = { d = 33.4, v = "skyborne-male", n = { x = 360 }, c = { x = { { 0.00, "Мне уже гораздо лучше." }, { 1.78, "Я неплохо владею тайной магией, и до Валанаара совсем недалеко." }, { 6.63, "Я доберусь до него сам." }, { 8.41, "Сейчас моя безопасность – не самое важное: подумай, как близко к Валанаару обосновались эти визгуны и какую опасность они представляют." }, { 18.74, "Прошу, сделай одолжение: вернись в пещеру и отруби голову этой зверюге!" }, { 24.28, "А после отыщи меня в Валанааре." }, { 26.74, "Мне нужно доложить верховному магистру, что здесь произошло и как продвигается моё задание." } } }, t = { d = 14.1, g = 1, v = "skyborne-male", n = { x = 132 }, c = { m = { { 0.00, "Признаю, я страшно рад, что Филлион к нам вернулся." }, { 4.22, "Он частенько не замечает, что творится вокруг." }, { 8.06, "То слишком глубоко задумается, то увлечётся книгой..." }, { 12.43, "Спасибо тебе, герой." } }, f = { { 0.00, "Признаю, я страшно рад, что Филлион к нам вернулся." }, { 4.01, "Он частенько не замечает, что творится вокруг." }, { 7.66, "То слишком глубоко задумается, то увлечётся книгой..." }, { 11.81, "Спасибо тебе, героиня." } } }, npc = { [253285] = { d = 2.2, v = "skyborne-male", n = { x = 19 }, c = { x = { { 0.00, "Ещё раз благодарю тебя." } } } } } } },
    [92858] = { d = 30.1, v = "narrator", n = { x = 297 }, c = { x = { { 0.00, "По приказу генерала Оперённой Луны!" }, { 2.96, "Любого, кто убьёт огра, известного как Ок'зи, ждёт награда." }, { 7.88, "Хотя огры из клана Гордунни не представляют такой же опасности, как наги, они всё же угрожают землям Фераласа." }, { 17.20, "В последний раз Ок'зи видели в поселении Гордунни к востоку отсюда." }, { 22.89, "Награда будет выдана при предъявлении доказательств его смерти." }, { 28.27, "Латроникус Лунное Копьё" } } } },
    [92859] = { d = 29.1, v = "goblin-female", n = { x = 327 }, c = { x = { { 0.00, "С конца войны многие пытаются попасть на гору Хиджал, но есть одна большая проблема... все эти демоны в Теснине Зловещего Шёпота!" }, { 9.30, "Кажется, у меня есть решение." }, { 11.43, "Отвар из местных ингредиентов, возможно, поможет тому, кто его выпьет, слиться с окрестностями Зимних Ключей, и здешние твари не смогут так легко тебя заметить." }, { 23.00, "Очень хочется проверить эту теорию – если ты не против принести мне кое-какие мелочи!" } } } },
    [92860] = { d = 31.8, v = "skyborne-male", n = { x = 370 }, c = { x = { { 0.00, "Высший орден всячески старался избегать прямого конфликта с культом, но теперь это не представляется возможным." }, { 8.04, "Они проявили открытую враждебность, а теперь до нас доходят слухи о более масштабных движениях сектантов по всему острову." }, { 16.87, "Они явно что-то замышляют, и вряд ли это пойдёт на благо жителям Зефриса." }, { 22.19, "Отправляйся к Валеннии Штормовой Кулак и сообщи, что Высший орден предлагает свою полную поддержку в борьбе Валанаара против ал'акетов." } } }, t = { d = 20.5, g = 1, v = "skyborne-female", n = { m = 195, f = 197 }, c = { m = { { 0.00, "Жаль, что так вышло с Белатааном." }, { 2.72, "Ты, наверное, не знал, но я его двоюродная сестра." }, { 6.88, "Он был хорошим магом и верой и правдой служил нашему острову." }, { 12.09, "Мы за него отомстим." }, { 13.83, "Вижу, ты уже готов оказать поддержку." }, { 17.08, "Идём." }, { 17.53, "Надо обсудить сложившуюся ситуацию." } }, f = { { 0.00, "Жаль, что так вышло с Белатааном." }, { 2.70, "Ты, наверное, не знала, но я его двоюродная сестра." }, { 6.98, "Он был хорошим магом и верой и правдой служил нашему острову." }, { 12.16, "Мы за него отомстим." }, { 13.88, "Вижу, ты уже готова оказать поддержку." }, { 17.18, "Идём." }, { 17.63, "Надо обсудить сложившуюся ситуацию." } } } } },
    [92867] = { d = 30.7, v = "human-male", n = { x = 363 }, c = { x = { { 0.00, "Хотя наше наследие разрушается, это ещё не последний наш оплот." }, { 4.50, "У нас ещё остались резервы, но для их же сохранности мы должны пока держать их в тайне." }, { 10.52, "Сохранение наших скульптур и священных кладбищ пользуется всё большей поддержкой." }, { 16.22, "Сброд, обосновавшийся в старом королевстве, даже не догадывается, какое страшное мщение его ждёт." }, { 23.00, "Разберись с кланом Тяжёлого Кулака и Синдикатом." }, { 26.36, "Пусть поймут, что Стромгард – это не только кулак, орёл и камни." } } } },
    [92871] = { d = 25.2, v = "skyborne-female", n = { x = 277 }, c = { x = { { 0.00, "Валенния Штормовой Кулак и её миротворцы всегда были защитниками Зефриса, и мы стараемся помогать им как можем." }, { 8.27, "Ходят слухи, что по всему острову пришли в движение силы сектантов, они явно что-то замышляют." }, { 15.46, "Отправляйся к Валеннии и скажи, что Ваятели ветра готовы всеми силами поддержать её в битве за Валанаар, если это будет необходимо." } } }, t = { d = 6.2, v = "skyborne-female", n = { x = 67 }, c = { x = { { 0.00, "Ты как будто хочешь немедленно начать действовать." }, { 3.97, "Идём, давай обсудим ситуацию." } } } } },
    [92872] = { d = 31.8, g = 1, v = "human-male", n = { m = 356, f = 357 }, c = { m = { { 0.00, "Мы вечно охраняем эту гробницу и знания о церемониях, возносящих хвалу этим павшим душам." }, { 6.74, "Ты спустился на три этажа под землю, а теперь пришло время вернуться в освещённый солнцем мир, неся с собой священную мудрость." }, { 16.09, "Каждое время года мы собираем в гробнице немного пыли и развеиваем её над океанами Азерота." }, { 22.90, "Это символизирует цикличность и обновление." }, { 26.11, "Возьми этот мешочек." }, { 27.71, "Ступай на утёсы за крепостью Стромгард и брось его в море." } }, f = { { 0.00, "Мы вечно охраняем эту гробницу и знания о церемониях, возносящих хвалу этим павшим душам." }, { 6.63, "Ты спустилась на три этажа под землю, а теперь пришло время вернуться в освещённый солнцем мир, неся с собой священную мудрость." }, { 15.88, "Каждое время года мы собираем в гробнице немного пыли и развеиваем её над океанами Азерота." }, { 22.58, "Это символизирует цикличность и обновление." }, { 25.73, "Возьми этот мешочек." }, { 27.30, "Ступай на утёсы за крепостью Стромгард и брось его в море." } } } },
    [92873] = { d = 36.1, v = "named/5398", n = { x = 334 }, c = { x = { { 0.00, "Мы уже знаем, что эти кристаллы способны не только сотрясать землю." }, { 5.60, "Племя Гелкис доказало, что их также можно исказить и применить в некромантии." }, { 11.94, "Помнишь, я дал тебе задание собрать кости?" }, { 15.48, "Я рассортировал их на холме как смог – должно хватить на два рабочих скелета." }, { 21.60, "*Оргрул протягивает вам новенький посох.*" }, { 25.04, "Я доставлю некрохану его посох, а ты пока опробуй свою новую игрушку." }, { 30.46, "Возвращайся лишь тогда, когда сможешь доказать, что умеешь ею пользоваться." } } } },
    [92878] = { d = 28.0, v = "scourge-male#83", n = { x = 121 }, c = { x = { { 0.00, "*Отрёкшийся указывает на своё лицо, лишённое нижней челюсти.*" }, { 4.83, "*Затем он вручает вам обрывок бумаги с торопливо написанным сообщением.*" }, { 10.64, "Не могу говорить." }, { 12.33, "Потерял челюсть в бою." }, { 14.52, "Напали таурены из племени Зловещего Тотема." }, { 18.65, "Главная – друид." }, { 20.25, "Намида." }, { 21.01, "Лагерь к северо-западу." }, { 23.28, "Пусть поплатится!" }, { 24.80, "*Последнее предложение дважды подчёркнуто.*" } } } },
    [92880] = { d = 31.8, g = 1, v = "skyborne-female", n = { x = 319 }, c = { m = { { 0.00, "Думаю, нам потребуется некоторое время, чтобы добить остатки нападавших, но сейчас наши шансы намного выше." }, { 8.67, "Возвращайся в Валанаар и скажи, что теперь ситуация под контролем." }, { 13.90, "Не могу выразить словами, как я тебе благодарна." }, { 17.77, "Без тебя нас ждала бы ужасная участь." }, { 20.77, "Похоже, вместо отряда подкрепления мне прислали начинающего героя." }, { 26.08, "Что ж, меня это устраивает." }, { 28.30, "Да благословят тебя четыре ветра, герой." } }, f = { { 0.00, "Думаю, нам потребуется некоторое время, чтобы добить остатки нападавших, но сейчас наши шансы намного выше." }, { 8.72, "Возвращайся в Валанаар и скажи, что теперь ситуация под контролем." }, { 13.98, "Не могу выразить словами, как я тебе благодарна." }, { 17.86, "Без тебя нас ждала бы ужасная участь." }, { 20.89, "Похоже, вместо отряда подкрепления мне прислали начинающего героя." }, { 26.22, "Что ж, меня это устраивает." }, { 28.45, "Да благословят тебя четыре ветра, героиня." } } }, t = { d = 8.1, v = "skyborne-female", n = { x = 11 }, c = { x = { { 0.00, "*Валенния с видимым облегчением выслушивает ваш отчёт о ситуации у восточной башни.*" }, { 6.56, "Хвала ветрам..." } } } } },
    [92881] = { d = 20.2, v = "skyborne-female", n = { x = 231 }, c = { x = { { 0.00, "То, что враг напал на западную и восточную сторожевые башни, – не совпадение." }, { 5.44, "Судя по твоему рассказу о западной башне и жреце небес, культ хочет что-то сделать с опорными столпами." }, { 12.94, "Поговори с верховным старейшиной Песня Теней." }, { 16.24, "Он расскажет тебе о зацепке, которую нам стоит проверить." } } }, t = { d = 8.0, v = "skyborne-male", n = { x = 86 }, c = { x = { { 0.00, "Есть одно маленькое дело, для решения которого как раз нужна помощь такого искателя приключений, как ты." } } } } },
    [92893] = { d = 28.6, v = "named/5398", n = { x = 299 }, c = { x = { { 0.00, "Углубляясь в Долину Костей, ты повстречаешь кентавров из племени Гелкис, которые посмели войти на нашу территорию." }, { 8.96, "Я приказал оставить их в живых, чтобы ими можно было накормить здешних костяных червей, но те, похоже, не желают есть живую добычу." }, { 19.33, "Тебе предстоит весьма простое дело: найди пленников и прикончи." }, { 24.41, "Пусть у них не останется даже искры надежды на свободу." } } } },
    [92894] = { d = 43.2, g = 1, v = "named/5398", n = { m = 431, f = 431 }, c = { m = { { 0.00, "Я вижу в твоих глазах радостное возбуждение, чужеземец." }, { 4.58, "Теперь ты понимаешь, на что способна некромантия?" }, { 8.57, "Конечно же понимаешь." }, { 10.34, "И потому я повелеваю тебе развить свои навыки." }, { 14.25, "В самой глуби Долины Костей ты увидишь останки, которые пытались поднять из мёртвых." }, { 21.20, "Без сомнения, тут замешаны кентавры из племени Гелкис." }, { 25.63, "Их скелеты даже не могут выбраться из земли." }, { 29.32, "Это было бы смешно, если бы не было так жалко." }, { 33.24, "Я наделил твой посох дополнительной силой." }, { 36.71, "Используй её, чтобы усилить наше войско, и сокруши тех, кто будет сопротивляться!" } }, f = { { 0.00, "Я вижу в твоих глазах радостное возбуждение, чужеземка." }, { 4.47, "Теперь ты понимаешь, на что способна некромантия?" }, { 8.36, "Конечно же понимаешь." }, { 10.09, "И потому я повелеваю тебе развить свои навыки." }, { 13.91, "В самой глуби Долины Костей ты увидишь останки, которые пытались поднять из мёртвых." }, { 20.69, "Без сомнения, тут замешаны кентавры из племени Гелкис." }, { 25.01, "Их скелеты даже не могут выбраться из земли." }, { 28.62, "Это было бы смешно, если бы не было так жалко." }, { 32.44, "Я наделил твой посох дополнительной силой." }, { 35.82, "Используй её, чтобы усилить наше войско, и сокруши тех, кто будет сопротивляться!" } } } },
    [92909] = { d = 27.0, v = "gnome-male", n = { x = 330 }, c = { x = { { 0.00, "О нет... вот это я попал!" }, { 1.71, "Мне рассказали, что в Западном крае на полях бесчинствуют големы, так что я прибыл сюда аж из самого Стальгорна, чтобы попробовать их перенастроить." }, { 11.57, "Но они оказались куда агрессивнее, чем предсказывали мои расчёты." }, { 15.98, "Даже загнали меня вот в эту конюшню!" }, { 18.55, "Будь у меня изопружины и гиростабилизаторы големов, я бы собрал устройство, которое поможет скрыться." }, { 25.34, "Соберёшь для меня запчасти?" } } }, t = { d = 5.3, v = "gnome-male", n = { x = 45 }, c = { x = { { 0.00, "Вот спасибо!" }, { 1.19, "Я займусь планированием побега." }, { 4.17, "А это тебе!" } } } } },
    [92910] = { d = 9.8, v = "narrator", n = { x = 111 }, c = { x = { { 0.00, "Деталь, которую вам удалось добыть у голема, на вид почти целая." }, { 4.75, "Возможно, на неё захочет взглянуть кто-нибудь, интересующийся големами." } } }, t = { d = 1.1, v = "gnome-male", n = { x = 7 }, c = { x = { { 0.00, "Это чего?" } } } } },
    [92911] = { d = 17.1, g = 1, v = "gnome-male", n = { m = 189, f = 193 }, c = { m = { { 0.00, "Понятно..." }, { 0.77, "Теперь я чуть лучше понимаю, как эти чудища работают." }, { 4.60, "У меня есть идея, как можно обойти их системы – по крайней мере, временно." }, { 9.89, "Я продолжу ковыряться в том, что ты принёс, а пока не мог бы ты собрать кое-какие детали для устройства?" } }, f = { { 0.00, "Понятно..." }, { 0.76, "Теперь я чуть лучше понимаю, как эти чудища работают." }, { 4.54, "У меня есть идея, как можно обойти их системы – по крайней мере, временно." }, { 9.77, "Я продолжу ковыряться в том, что ты принесла, а пока не могла бы ты собрать кое-какие детали для устройства?" } } }, t = { d = 9.1, v = "gnome-male", n = { x = 80 }, c = { x = { { 0.00, "Вот, держи!" }, { 1.01, "Должно отлично сработать." }, { 3.27, "Иди испытай!" }, { 4.44, "...Я?" }, { 4.91, "Нет, я останусь здесь." }, { 6.78, "Тут уже как-то по-домашнему." } } } } },
    [92914] = { d = 29.9, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Вы подходите к странному кристаллу, который всего пару мгновений назад охраняли иссушенные элементали." }, { 8.18, "Его пьедестал, несмотря на отметины времени, обветшал гораздо меньше окружающих эльфийских руин." }, { 15.93, "От расколотого самоцвета исходит тихое гудение силы, но магии в нём осталось так мало, что выяснить его предназначение пока невозможно." }, { 26.70, "Может быть, рядом отыщется ещё что-нибудь." } } } },
    [92947] = { d = 36.3, g = 1, v = "skyborne-female", n = { x = 376 }, c = { m = { { 0.00, "Всё на месте." }, { 1.03, "Хорошо." }, { 1.65, "Я отправила несколько моих лучших бойцов на передовую, чтобы они устроили немного шума и отвлекли врага." }, { 9.79, "Тем временем я заведу основные силы с фланга." }, { 13.30, "Если всё пройдёт гладко, мы быстро пробьёмся к святилищу и устраним верховную жрицу." }, { 19.64, "Теперь твоя часть плана: ворвись туда и начинай убивать врагов." }, { 24.61, "Когда посеешь достаточно хаоса, найди мою первую помощницу Хюсаа Быстрый Бриз." }, { 30.74, "Она будет ждать у ступеней святилища." }, { 33.63, "Да хранят тебя ветра, герой." } }, f = { { 0.00, "Всё на месте." }, { 1.03, "Хорошо." }, { 1.65, "Я отправила несколько моих лучших бойцов на передовую, чтобы они устроили немного шума и отвлекли врага." }, { 9.79, "Тем временем я заведу основные силы с фланга." }, { 13.30, "Если всё пройдёт гладко, мы быстро пробьёмся к святилищу и устраним верховную жрицу." }, { 19.64, "Теперь твоя часть плана: ворвись туда и начинай убивать врагов." }, { 24.61, "Когда посеешь достаточно хаоса, найди мою первую помощницу Хюсаа Быстрый Бриз." }, { 30.74, "Она будет ждать у ступеней святилища." }, { 33.40, "Да хранят тебя ветра, героиня." } } }, t = { d = 4.7, v = "skyborne-female", n = { x = 44 }, c = { x = { { 0.00, "Нам многого стоило сюда пробиться, но это ещё не конец." } } } } },
    [93016] = { d = 14.2, v = "nightelf-male#59", n = { x = 170 }, c = { x = { { 0.00, "Прошу меня простить, что завалил поручениями и ничего не объяснил." }, { 4.62, "От меня укрылось, насколько это подозрительно с моей стороны, особенно при таком экстравагантном цвете небес." }, { 12.24, "Я отвечу на все твои вопросы." } } } },
    [93030] = { d = 21.4, v = "human-male", n = { x = 197 }, c = { x = { { 0.00, "Когда-то я был рыцарем, как и ты, – и служил Свету." }, { 4.21, "А потом я умер." }, { 5.57, "Похоже, хотя бы это у нас с тобой общее." }, { 9.03, "Но, в отличие от тебя, меня держит здесь незавершённое дело, неисполненная клятва." }, { 15.80, "Если выслушаешь, я расскажу тебе о своём походе... и о своём провале." } } } },
    [93034] = { d = 39.8, v = "named/5397", n = { x = 396 }, c = { x = { { 0.00, "Пока тебя не было, в деревню вернулся один из наших разведчиков с вестями, которые подтвердили мои страхи." }, { 8.87, "Племя Маграм опять что-то затевает." }, { 11.90, "Дело плохо." }, { 12.94, "Долина Костей далеко на востоке – проклятая земля, куда кентавры редко отваживаются заглядывать и откуда почти никто не возвращается." }, { 23.95, "Наш враг обнаружил там нечто зловещее, и нам надо выяснить, что это такое." }, { 30.01, "Разыщи разведчика Нерлока у южного входа, только сперва тебе, возможно, ещё придётся доказать племени Гелкис, что ты друг." } } } },
    [93035] = { d = 39.0, g = 1, v = "named/5398", n = { m = 398, f = 399 }, c = { m = { { 0.00, "Необязательно вглядываться в даль, чтобы разглядеть нежить, разгуливающую перед нами." }, { 6.76, "Но заметил ли ты кое-что необычное?" }, { 9.57, "Они ходят на двух ногах, а не на четырёх." }, { 12.81, "Эти скелеты принадлежат даже не нашим павшим сородичам." }, { 17.34, "Племя Маграм, верно, оскверняет тела тех, кто умер задолго до того, как Пустоши стали принадлежать нам." }, { 25.61, "Даже не представляю, как они оправдывают то, что отвернулись от Матери Терадрас и начали измываться над трупами, которые покоились здесь веками." }, { 36.98, "Верни нежити покой." } }, f = { { 0.00, "Необязательно вглядываться в даль, чтобы разглядеть нежить, разгуливающую перед нами." }, { 6.85, "Но заметила ли ты кое-что необычное?" }, { 9.76, "Они ходят на двух ногах, а не на четырёх." }, { 13.04, "Эти скелеты принадлежат даже не нашим павшим сородичам." }, { 17.63, "Племя Маграм, верно, оскверняет тела тех, кто умер задолго до того, как Пустоши стали принадлежать нам." }, { 26.01, "Даже не представляю, как они оправдывают то, что отвернулись от Матери Терадрас и начали измываться над трупами, которые покоились здесь веками." }, { 37.52, "Верни нежити покой." } } } },
    [93036] = { d = 33.8, v = "skyborne-female", n = { x = 377 }, c = { x = { { 0.00, "Может, ты не знаешь: это Сания Серебряный Поток, миссионер культа Ал'акет." }, { 5.54, "Они любят прикидываться обычной религией и отправлять мирных посланников, чтобы пополнять свои ряды." }, { 13.00, "Пока что мы терпели присутствие Сании, чтобы избежать прямого конфликта с сектантами, но, очевидно, иллюзия мира продержится недолго." }, { 22.76, "Ты здесь недавно, и многие тебя ещё не знают." }, { 26.06, "Может, у тебя получится подобраться к культу через их миссионера?" }, { 30.87, "Нам бы узнать, каковы их планы в деревне." } } }, t = { d = 16.5, v = "skyborne-female", n = { x = 158 }, c = { x = { { 0.00, "Приветствую, дитя." }, { 1.62, "Я Сания Серебряный Поток, жрица ордена Ал'акет." }, { 5.78, "Хочешь узнать больше о нашем повелителе Ал'акире Владыке Ветра?" }, { 11.32, "За его столом всегда найдётся место для праведных и покаянных." } } } } },
    [93037] = { d = 30.4, g = 1, v = "named/5398", n = { m = 322, f = 323 }, c = { m = { { 0.00, "Дожидаясь тебя, я заглянул дальше за арки и заметил нечто подозрительное." }, { 5.65, "Мне нужно, чтобы ты подтвердил мои опасения." }, { 9.10, "Даже не могу произнести это вслух." }, { 11.79, "Сперва выясним, действительно ли всё так, как мне показалось." }, { 16.34, "Пока будешь исследовать долину, убей несколько некромантов, которые кажутся слабее остальных." }, { 23.58, "Сними с них ритуальные одеяния и принеси мне." }, { 27.02, "Хочу знать, не обманули ли меня глаза." } }, f = { { 0.00, "Дожидаясь тебя, я заглянул дальше за арки и заметил нечто подозрительное." }, { 5.75, "Мне нужно, чтобы ты подтвердила мои опасения." }, { 9.32, "Даже не могу произнести это вслух." }, { 12.05, "Сперва выясним, действительно ли всё так, как мне показалось." }, { 16.68, "Пока будешь исследовать долину, убей несколько некромантов, которые кажутся слабее остальных." }, { 24.03, "Сними с них ритуальные одеяния и принеси мне." }, { 27.54, "Хочу знать, не обманули ли меня глаза." } } } },
    [93041] = { d = 30.3, v = "named/5398", n = { x = 315 }, c = { x = { { 0.00, "Это открытие губительно для нашего клана, но в наших интересах, чтобы о нём знали только те, кому положено." }, { 8.42, "Ута – одна из тех, кто должен знать о происходящем." }, { 12.36, "Думаю, она поймёт, как быть дальше." }, { 15.09, "Отнеси ей это." }, { 16.29, "А для верности стоит принести ей и доказательство самой некромантии." }, { 21.55, "Найди череп, на который недавно наложили проклятие." }, { 25.63, "Подозреваю, что их прячут в пасти одного из скелетов голиафов." } } } },
    [93044] = { d = 27.7, v = "named/5397", n = { x = 287 }, c = { x = { { 0.00, "Ты не вернёшься к Нерлоку в Долину Костей с пустыми руками." }, { 4.67, "Ступай в пещеру в сердце нашей деревни и отыщи Мулару." }, { 9.13, "Скажи, что я попросила Слёзы Терадрас." }, { 12.15, "У нас их почти не осталось, но это единственное, что поможет в борьбе против зловещей некромантии племени Маграм." }, { 21.14, "Я приготовлю всё для ритуала." }, { 23.44, "Мы создадим оружие, способное развеивать их заклинания." } } } },
    [93058] = { d = 31.4, g = 1, v = "named/5398", n = { m = 352, f = 352 }, c = { m = { { 0.00, "Между некромантами завязалась схватка за холмом, и я воспользовался этим, чтобы осмотреться получше." }, { 7.46, "Не все наши потери связаны с дезертирами." }, { 10.55, "В долине держат в плену представителей племени Гелкис!" }, { 14.65, "Мне не удалось разузнать больше, так как меня стал преследовать огромный боец племени Маграм." }, { 21.56, "Повезло, что погоня ему быстро наскучила." }, { 24.72, "Ты должен вернуться в Долину Костей и освободить пленников." }, { 29.16, "Племя Гелкис не бросает своих." } }, f = { { 0.00, "Между некромантами завязалась схватка за холмом, и я воспользовался этим, чтобы осмотреться получше." }, { 7.44, "Не все наши потери связаны с дезертирами." }, { 10.52, "В долине держат в плену представителей племени Гелкис!" }, { 14.61, "Мне не удалось разузнать больше, так как меня стал преследовать огромный боец племени Маграм." }, { 21.51, "Повезло, что погоня ему быстро наскучила." }, { 24.66, "Ты должна вернуться в Долину Костей и освободить пленников." }, { 29.08, "Племя Гелкис не бросает своих." } } } },
    [93062] = { d = 38.5, g = 1, v = "named/5398", n = { m = 396, f = 397 }, c = { m = { { 0.00, "Насчёт твоего посоха." }, { 1.71, "Вижу, что он принадлежал Уте, а ты упоминал, что его создали с помощью Слёз Терадрас и усилили кристаллом дренетиста, так что он может развеивать тёмную магию." }, { 14.13, "Я заметил, что под каменистой почвой дальше в долине замурованы скелеты." }, { 19.84, "Полагаю, это результаты неудавшегося ритуала призывания, выполненного некромантами-изгоями." }, { 27.05, "Теперь эти несчастные обречены на вечное существование в земле." }, { 32.12, "Если вернём им покой, это будет полезно и для нашего дела, и для их душ." } }, f = { { 0.00, "Насчёт твоего посоха." }, { 1.75, "Вижу, что он принадлежал Уте, а ты упоминала, что его создали с помощью Слёз Терадрас и усилили кристаллом дренетиста, так что он может развеивать тёмную магию." }, { 14.48, "Я заметил, что под каменистой почвой дальше в долине замурованы скелеты." }, { 20.30, "Полагаю, это результаты неудавшегося ритуала призывания, выполненного некромантами-изгоями." }, { 27.65, "Теперь эти несчастные обречены на вечное существование в земле." }, { 32.81, "Если вернём им покой, это будет полезно и для нашего дела, и для их душ." } } } },
    [93065] = { d = 15.1, v = "skyborne-female", n = { x = 170 }, c = { x = { { 0.00, "Миротворцы уже мобилизуются, а мы снаряжаемся к бою." }, { 3.95, "Сделай все необходимые приготовления и выходи на восточную дорогу, ведущую из города на север." }, { 11.04, "Там мы проведём последнюю перекличку и двинемся на врага." } } }, t = { d = 1.8, v = "skyborne-female", n = { x = 17 }, c = { x = { { 0.00, "Мы готовы выступать." } } } } },
    [93066] = { d = 36.5, v = "named/5398", n = { x = 406 }, c = { x = { { 0.00, "Мы закрепились на другой стороне долины, чтобы подготовиться к проникновению в лес неподалёку." }, { 6.83, "Но прежде чем ты отправишься туда, тебе нужно будет разобраться со вторжением Дыбогривов." }, { 13.46, "Судя по всему, они прибыли сюда примерно тогда же, когда и мы, но им удалось раздобыть в местном храме артефакт, который они используют, чтобы противостоять нашему натиску." }, { 26.38, "Твоя задача проста: разыщи этих шипастых свиней и безжалостно убей как можно больше." }, { 32.81, "Потом доложи Хагиаку в лагере, который я упомянул." } } } },
    [93072] = { d = 23.8, v = "named/5398", n = { x = 238 }, c = { x = { { 0.00, "К юго-западу отсюда находится вторая деревня кентавров, которая принадлежит племени Гелкис." }, { 7.51, "Ты наверняка ждёшь, когда я отправлю тебя туда и прикажу устроить резню, так?" }, { 13.84, "Хорошо." }, { 14.50, "Если бы тебе этого не хотелось, я бы засомневался в твоей верности племени Маграм." }, { 21.27, "Чего же ты ждёшь?" }, { 22.67, "Вперёд, убей их!" } } } },
    [93089] = { d = 34.0, v = "skyborne-male", n = { x = 347 }, c = { x = { { 0.00, "Передай мою благодарность Элаадрину за всё, что Высший орден и твои новые друзья из Кирин-Тора сделали ради Зефриса." }, { 9.33, "Я знаю, что Высший орден собирается покинуть остров, и я благословляю вашу экспедицию." }, { 16.21, "Желаю удачи." }, { 17.29, "Надеюсь, благодаря своей магии орден найдёт ответы и вернёт нам покой, которого мы были лишены в последние годы." }, { 26.26, "Если ты собираешься отправиться с ним... что ж, вместе вы будете сильнее." }, { 32.00, "Да пребудет с тобой ветер." } } }, t = { d = 21.5, v = "skyborne-male", n = { x = 248 }, c = { x = { { 0.00, "Меня радует, что верховный старейшина Песня Теней благословил нашу экспедицию." }, { 5.80, "Мы разгромили секту и подготовили всё необходимое – думаю, пора в путь." }, { 10.93, "Трудяга Ансарем подготовил работающий неборез, который доставит нас с Зефриса в Даларан." }, { 17.39, "Мы всё проверили как следует – авангард может отправляться." } } } } },
    [93090] = { d = 29.8, v = "skyborne-male", n = { x = 313 }, c = { x = { { 0.00, "Передай мою благодарность Айессе за всё, что Ваятели ветра и твои новые друзья из круга Служителей Земли сделали ради Зефриса." }, { 9.97, "Я знаю о планах собрать Ваятелей ветра и покинуть остров и благословляю экспедицию." }, { 16.51, "Желаю твоему ордену удачи." }, { 18.68, "Надеюсь, что Ваятели ветра найдут ответы на все вопросы и вернут нам покой, которого мы были лишены в последние годы." }, { 27.88, "Да пребудет с тобой ветер." } } }, t = { d = 26.2, v = "skyborne-female", n = { x = 302 }, c = { x = { { 0.00, "Рада слышать, что верховный старейшина Песня Теней благословил нашу экспедицию." }, { 5.82, "Мы разгромили секту и подготовили всё необходимое, – думаю, пора в путь." }, { 10.99, "Трудяга Мулн подготовил работающий неборез, который доставит нас с Зефриса в область под названием Мулгор, где находятся Служители Земли." }, { 20.87, "Мы уже провели несколько пробных рейсов, и часть наших ждёт на той стороне." } } } } },
    [93122] = { d = 32.2, v = "named/5398", n = { x = 333 }, c = { x = { { 0.00, "Мы недооценили, насколько опасен клан Маграм и как сильно его присутствие тут, но это, возможно, сыграет нам на руку." }, { 8.91, "Множество их воинов заняты здесь и они не принимают изгоев из других кланов." }, { 15.00, "Так кто же остался у них в деревне?" }, { 17.72, "Что насчёт их вождя?" }, { 19.29, "Отправляйся в долину глубже, чем когда-либо прежде, и осмотрись." }, { 24.37, "Если племя Маграм и правда так прочно здесь закрепилось, то, возможно, деревня осталась без защиты..." } } } },
    [93125] = { d = 37.3, g = 1, v = "named/5398", n = { m = 381, f = 382 }, c = { m = { { 0.00, "Эй!" }, { 0.28, "Я видел, что ты сражался с изгоями." }, { 3.05, "Не знаю, откуда ты, но мне нужна твоя помощь." }, { 6.66, "Меня заманили сюда сородичи из племени Гелкис, обещая безопасность." }, { 12.05, "Я знал, что война в Пустошах разгорается так сильно, что скоро всё выйдет из-под контроля, но и представить не мог, что представители моего собственного народа обратятся к некромантии, чтобы подлизаться к клану Маграм." }, { 28.92, "Когда я сказал, что против этого, они пригрозили убить меня, если я выйду из этой палатки!" }, { 36.23, "Прошу, помоги." } }, f = { { 0.00, "Эй!" }, { 0.27, "Я видел, что ты сражалась с изгоями." }, { 3.02, "Не знаю, откуда ты, но мне нужна твоя помощь." }, { 6.52, "Меня заманили сюда сородичи из племени Гелкис, обещая безопасность." }, { 11.74, "Я знал, что война в Пустошах разгорается так сильно, что скоро всё выйдет из-под контроля, но и представить не мог, что представители моего собственного народа обратятся к некромантии, чтобы подлизаться к клану Маграм." }, { 28.07, "Когда я сказал, что против этого, они пригрозили убить меня, если я выйду из этой палатки!" }, { 35.14, "Прошу, помоги." } } } },
    [93128] = { d = 39.5, g = 1, v = "named/5398", n = { m = 388, f = 389 }, c = { m = { { 0.00, "Мне бы, конечно, хотелось получить приказ от Уты или вождя Шаки, но, боюсь, времени у нас всё меньше." }, { 8.00, "Мы просто не успеем получить ответ из деревни Гелкис." }, { 12.25, "Судя по тому, что происходит в Долине Костей, племя Маграм оставило вождя Джена под минимальной защитой." }, { 20.53, "Если и есть удачное время, чтобы напасть на вождя другого клана, то это сейчас." }, { 26.90, "Но имей в виду, с вождями шутки плохи – особенно с Дженом." }, { 31.57, "Если у тебя хватит отваги, чтобы бросить ему вызов, будь быстр и не смей его недооценивать." } }, f = { { 0.00, "Мне бы, конечно, хотелось получить приказ от Уты или вождя Шаки, но, боюсь, времени у нас всё меньше." }, { 8.15, "Мы просто не успеем получить ответ из деревни Гелкис." }, { 12.48, "Судя по тому, что происходит в Долине Костей, племя Маграм оставило вождя Джена под минимальной защитой." }, { 20.92, "Если и есть удачное время, чтобы напасть на вождя другого клана, то это сейчас." }, { 27.41, "Но имей в виду, с вождями шутки плохи – особенно с Дженом." }, { 32.17, "Если у тебя хватит отваги, чтобы бросить ему вызов, будь быстра и не смей его недооценивать." } } } },
    [93129] = { d = 31.4, v = "named/5398", n = { x = 340 }, c = { x = { { 0.00, "Раз ты так рвёшься помочь нашему клану, уверен, что не будешь против собрать для нас припасы в убежище изгоев." }, { 8.34, "Кентавры из племени Маграм должны быть довольны уже тем, что враг пал, но не вижу причины, почему бы нам не извлечь из этого дополнительную пользу." }, { 19.44, "Когда разберёмся с изгнанниками, эти места будут наконец принадлежать племени Маграм, и мы сможем создать войско, которое поставит остальные кланы на колени!" } } } },
    [93159] = { d = 18.9, v = "gnome-male", n = { x = 111 }, c = { x = { { 0.00, "Э-э... здрасьте." }, { 1.55, "То есть привет!" }, { 2.94, "Или как там, приветствую!" }, { 5.23, "Извиняюсь, я... очень давно ни с кем не разговаривал." }, { 9.97, "Боюсь, что отвык." }, { 11.52, "*Странная фигура в капюшоне неловко мнётся перед вами.*" }, { 16.48, "Так, э-э... как твои дела?" } } }, t = { d = 31.3, v = "gnome-male", n = { x = 331 }, c = { x = { { 0.00, "...Вот и всё, что я могу об этом рассказать." }, { 3.12, "Я был... гм... где-то ещё, а потом оказался тут." }, { 6.49, "И теперь я тут со своими друзьями и своими вещами." }, { 10.13, "Вещами... которые сделал сам." }, { 12.27, "Это всё, что мне нужно." }, { 13.96, "Ну, я так думаю, во всяком случае." }, { 16.43, "Но вот что хочу сказать, это здорово – говорить с кем-то, кто может тебе ответить." }, { 22.40, "Лесные духи стараются отвечать, но они умеют только петь." }, { 26.62, "Это тоже по-своему мило, но интеллектуальная беседа не получается." } } } } },
    [93160] = { d = 24.8, g = 1, v = "gnome-male", n = { m = 257, f = 259 }, c = { m = { { 0.00, "Спасибо, что остановился и поболтал со мной!" }, { 3.31, "Я... если хочешь помочь, пожалуйста, собери опавшие жёлуди." }, { 7.86, "Тут я их уже собрал, но дальше в лесу водится куча этих не то птиц, не то ящеров." }, { 14.06, "Там опасно, а я не хочу стать обедом для огромной птицы!" }, { 18.33, "Так что если хочешь, может, соберёшь желудей?" }, { 21.78, "А я приготовлю для нас что-нибудь вкусное!" } }, f = { { 0.00, "Спасибо, что остановилась и поболтала со мной!" }, { 3.28, "Я... если хочешь помочь, пожалуйста, собери опавшие жёлуди." }, { 7.62, "Тут я их уже собрал, но дальше в лесу водится куча этих не то птиц, не то ящеров." }, { 13.53, "Там опасно, а я не хочу стать обедом для огромной птицы!" }, { 17.60, "Так что если хочешь, может, соберёшь желудей?" }, { 20.88, "А я приготовлю для нас что-нибудь вкусное!" } } }, t = { d = 7.2, g = 1, v = "gnome-male", n = { m = 72, f = 72 }, c = { m = { { 0.00, "Спасибо, незнакомец!" }, { 1.67, "Я их поджарю, будет пальчики оближешь." }, { 4.80, "Один момент, сейчас всё будет." } }, f = { { 0.00, "Спасибо, незнакомка!" }, { 1.66, "Я их поджарю, будет пальчики оближешь." }, { 4.75, "Один момент, сейчас всё будет." } } } } },
    [93161] = { d = 23.5, v = "narrator", n = { x = 261 }, c = { x = { { 0.00, "В тусклом свете факела слабо поблёскивает что-то металлическое." }, { 4.84, "Рассмотрев предмет поближе, вы различаете отломанную рукоять древнего меча." }, { 10.66, "Вы видите, что рукоять была изготовлена явно очень искусным мастером и даже без лезвия представляет немалую ценность." }, { 19.72, "Кто-нибудь наверняка захочет изучить такую вещицу." } } } },
    [93162] = { d = 27.8, g = 1, v = "creature/furbolg", n = { m = 211, f = 212 }, c = { m = { { 0.56, "Мне ты себя уже точно доказал, но других в моём племени убедить не так просто." }, { 7.23, "Для этого тебе придётся и дальше сражаться с Легаши." }, { 14.74, "Принеси мне рога убитых сатиров из племени Легаши." }, { 18.91, "Каждая связка, которую ты принесёшь, станет знаком твоей службы Черночревам." } }, f = { { 0.56, "Мне ты себя уже точно доказала, но других в моём племени убедить не так просто." }, { 7.12, "Для этого тебе придётся и дальше сражаться с Легаши." }, { 14.50, "Принеси мне рога убитых сатиров из племени Легаши." }, { 18.57, "Каждая связка, которую ты принесёшь, станет знаком твоей службы Черночревам." } } } },
    [93163] = { d = 19.4, v = "narrator", n = { x = 202 }, c = { x = { { 0.00, "Построенный и вновь разрушенный: сердце Иодакса Уничтожителя теперь в ваших руках." }, { 6.60, "Скорее всего, этого голема создали дворфы Чёрного Железа — или кто-то ещё до них." }, { 13.21, "Поэтому вашей находкой могут заинтересоваться дворфы из лагеря Братства Тория." } } } },
    [93165] = { d = 23.4, g = 1, v = "skyborne-male", n = { m = 232, f = 232 }, c = { m = { { 0.00, "Ал'акетские сектанты принесли нам страшное горе, и кровь можно смыть только кровью." }, { 6.83, "У меня есть предложение, незнакомец." }, { 9.79, "Если встретишь этих проклятых фанатиков, убей их и принеси мне уши." }, { 15.43, "Я заплачу за них монетой и – когда ты докажешь, что ты настоящий друг – тайными знаниями Когтя Ночи." } }, f = { { 0.00, "Ал'акетские сектанты принесли нам страшное горе, и кровь можно смыть только кровью." }, { 6.73, "У меня есть предложение, незнакомка." }, { 9.66, "Если встретишь этих проклятых фанатиков, убей их и принеси мне уши." }, { 15.22, "Я заплачу за них монетой и – когда ты докажешь, что ты настоящий друг – тайными знаниями Когтя Ночи." } } }, t = { d = 21.4, v = "skyborne-male", n = { x = 214 }, c = { x = { { 0.00, "Превосходно." }, { 1.00, "Уничтожение этих сектантов – безусловное благо." }, { 4.80, "Надеюсь, теперь-то они поймут, что с Когтем Ночи лучше не связываться и память у нас долгая." }, { 12.19, "Полагаю, что у тебя свои счёты с этой сектой, и ты ещё не раз с ними столкнёшься." }, { 18.50, "Если добудешь ещё их уши, неси сюда." } } } } },
    [93172] = { d = 35.4, g = 1, v = "gnome-male", n = { m = 350, f = 350 }, c = { m = { { 0.00, "Большая часть эльфов на острове думает, что в лесу живут призраки – и они не так уж и неправы." }, { 7.19, "В старых руинах на северо-востоке собираются странные духи, похожие на души мертвецов." }, { 13.89, "Иногда по ночам можно услышать их... пение." }, { 17.27, "Это не похоже на наши песни, но это точно пение, и оно... оно такое грустное." }, { 23.42, "Не знаю почему, но думаю, что когда-то там произошло нечто ужасное, и духи томятся в заключении." }, { 30.82, "Если ты смелый, может, попробуешь их освободить?" } }, f = { { 0.00, "Большая часть эльфов на острове думает, что в лесу живут призраки – и они не так уж и неправы." }, { 7.39, "В старых руинах на северо-востоке собираются странные духи, похожие на души мертвецов." }, { 14.28, "Иногда по ночам можно услышать их... пение." }, { 17.76, "Это не похоже на наши песни, но это точно пение, и оно... оно такое грустное." }, { 24.08, "Не знаю почему, но думаю, что когда-то там произошло нечто ужасное, и духи томятся в заключении." }, { 31.68, "Если ты смелая, может, попробуешь их освободить?" } } }, t = { d = 2.0, g = 1, v = "gnome-male", n = { m = 17, f = 17 }, c = { m = { { 0.00, "Спасибо, незнакомец." } }, f = { { 0.00, "Спасибо, незнакомка." } } } } },
    [93174] = { d = 23.4, v = "narrator", n = { x = 271 }, c = { x = { { 0.00, "Голем перед вами жужжит, фыркает и явно работает не так, как должен." }, { 5.01, "Опираясь на свой скромный инженерный опыт, вы подозреваете, что его нужно чинить." }, { 10.87, "В Валанааре есть несколько мастеров, которым доводилось обслуживать подобных циклонных големов." }, { 17.71, "Возможно, что-нибудь подскажет и отшельник, который научил вас инженерному делу." } } } },
    [93176] = { d = 30.2, v = "scourge-female", n = { x = 281 }, c = { x = { { 0.00, "Любуешься моим маленьким зверинцем?" }, { 3.18, "Это дело всей моей не-жизни." }, { 5.81, "Я провела бесчисленные часы, изучая их: их строение, питание и даже общественные обряды." }, { 13.61, "Хочешь присоединиться ко мне в этом увлечении?" }, { 17.67, "Вот, возьми этот свёрток." }, { 19.90, "Заметки и материалы внутри помогут тебе начать." }, { 24.19, "Если потеряешь его, придётся купить у меня другой за небольшую плату." } } }, t = { d = 35.1, g = 1, v = "scourge-female", n = { m = 297, f = 299 }, c = { m = { { 0.00, "Какая прелесть!" }, { 1.50, "Посмотри на передние лапки вот этого!" }, { 4.99, "А какой окрас панциря у этого!" }, { 7.89, "О, а жвала вот этого!" }, { 9.89, "Не думала, что ты разбираешься в насекомых, но глаз у тебя очень зоркий." }, { 16.45, "Вот, возьми, пожалуйста." }, { 18.69, "Кажется, ты ему понравился, а этот вид я уже занесла в каталог." }, { 24.59, "А теперь прошу меня извинить – мне пора вернуться к исследованиям." }, { 30.74, "Ты дал мне столько материала для изучения!" } }, f = { { 0.00, "Какая прелесть!" }, { 1.52, "Посмотри на передние лапки вот этого!" }, { 5.05, "А какой окрас панциря у этого!" }, { 8.00, "О, а жвала вот этого!" }, { 10.02, "Не думала, что ты разбираешься в насекомых, но глаз у тебя очень зоркий." }, { 16.67, "Вот, возьми, пожалуйста." }, { 18.95, "Кажется, ты ему понравилась, а этот вид я уже занесла в каталог." }, { 25.01, "А теперь прошу меня извинить – мне пора вернуться к исследованиям." }, { 31.24, "Ты дала мне столько материала для изучения!" } } } } },
    [93188] = { d = 21.4, g = 1, v = "named/5398", n = { m = 207, f = 209 }, c = { m = { { 0.00, "Ты уже достаточно сделал на передовой." }, { 3.29, "Дальше мы справимся сами." }, { 5.51, "Передай Оргрулу, что ты своё дело сделал." }, { 9.04, "Фронт Маграм теперь крепче, и когда к битве присоединится ещё один отряд бойцов, нашим следующим поселением станет лагерь изгнанников." }, { 20.52, "Ну?" }, { 20.83, "Ступай!" } }, f = { { 0.00, "Ты уже достаточно сделала на передовой." }, { 3.33, "Дальше мы справимся сами." }, { 5.53, "Передай Оргрулу, что ты своё дело сделала." }, { 9.09, "Фронт Маграм теперь крепче, и когда к битве присоединится ещё один отряд бойцов, нашим следующим поселением станет лагерь изгнанников." }, { 20.45, "Ну?" }, { 20.75, "Ступай!" } } } },
    [93196] = { d = 36.6, v = "named/5398", n = { x = 268 }, c = { x = { { 0.00, "Предводителя нашего клана, хана Джена, убил отряд чужаков – таких же, как ты." }, { 6.32, "Они действовали по указке клана Гелкис." }, { 9.59, "Можешь не изображать удивление." }, { 12.14, "Напасть на деревню Маграм, пока наше внимание было занято другим, – предсказуемый военный ход, особенно для Гелкис." }, { 21.51, "Знаешь, почему я не выказываю ни ярости, ни скорби, чужак?" }, { 26.16, "*Оргрул протягивает вам знакомое оружие, наполненное ещё большей силой, чем в прошлый раз, когда вы держали его в руках.*" }, { 35.36, "Вот почему." } } } },
    [93224] = { d = 31.1, v = "human-male", n = { x = 368 }, c = { x = { { 0.00, "Наверняка для тебя не сюрприз, что оба клана кентавров не особенно рвутся просить помощи у чужаков." }, { 7.00, "Особенно когда речь идёт о не-кентаврах, как ты и я." }, { 10.53, "Но у нас есть одна общая черта: все мы понимаем, что деньги – это власть." }, { 15.57, "Нам удалось выяснить, что местные кентавры обмениваются резными идолами." }, { 20.61, "Если принесёшь мне несколько образцов, я смогу сделать срочный заказ на производство таких же работ." }, { 27.61, "Возможно, нам удастся выторговать себе преимущество." } } } },
    [93225] = { d = 41.4, v = "tauren-female", n = { x = 422 }, c = { x = { { 0.00, "Я заметила, что кентавры из разных кланов иногда собираются вдали от поселений и торгуют." }, { 7.14, "Они занимаются этим чуть ли не каждую ночь, а участие в торговле принимают члены всех кланов." }, { 14.56, "Но самое главное – я выяснила, что они используют как валюту." }, { 19.46, "Это резные тотемы." }, { 21.05, "Думаю, нам удастся обернуть ситуацию в свою пользу, если доставим племени Гелкис или племени Маграм весомый груз тотемов." }, { 30.92, "Я уже начала сама их вырезать, но не думаю, что удастся кого-либо обмануть, если не добавим к подделкам несколько настоящих образцов." } } }, t = { d = 33.0, g = 1, v = "tauren-female", n = { m = 339, f = 340 }, c = { m = { { 0.00, "Какая красота!" }, { 1.19, "Я недооценивала изобретательность кентавров." }, { 4.53, "Никогда бы не подумала, что народ, настолько грубый и жестокий, способен ценить истории, рассказанные в резьбе." }, { 13.11, "Хотя ценить их куда проще, чем вырезать." }, { 16.32, "Скажу иначе: никогда бы не подумала, что у кентавров хватит терпения вырезать из дерева столько историй." }, { 24.41, "Откуда они вообще берут дерево?" }, { 26.99, "Как бы то ни было, поговори со мной, когда будешь готов к доставке." } }, f = { { 0.00, "Какая красота!" }, { 1.22, "Я недооценивала изобретательность кентавров." }, { 4.67, "Никогда бы не подумала, что народ, настолько грубый и жестокий, способен ценить истории, рассказанные в резьбе." }, { 13.51, "Хотя ценить их куда проще, чем вырезать." }, { 16.81, "Скажу иначе: никогда бы не подумала, что у кентавров хватит терпения вырезать из дерева столько историй." }, { 25.15, "Откуда они вообще берут дерево?" }, { 27.80, "Как бы то ни было, поговори со мной, когда будешь готова к доставке." } } } } },
    [93226] = { d = 37.4, v = "narrator", n = { x = 380 }, c = { x = { { 0.00, "Мне кажется правильным заключить союз с племенем Маграм." }, { 4.56, "Без сомнения, это сейчас самый могучий клан, несмотря на то что раньше они переживали непростые времена." }, { 12.97, "Говорят, они испытывают безудержную ненависть к племени Гелкис." }, { 18.11, "Я сочувствую обоим враждующим кланам, особенно Гелкис, но это их война, а не наша." }, { 24.77, "Нужно брать в союзники тех, с кем вернее удастся достичь наших целей." }, { 30.35, "Я считаю, что это племя Маграм." }, { 32.96, "Отнеси это их интенданту в деревню Маграм на юго-востоке." } } } },
    [93227] = { d = 34.2, v = "human-male", n = { x = 408 }, c = { x = { { 0.00, "На первый взгляд может показаться, что дела у племени Гелкис идут неважно." }, { 5.07, "Числом они уступают племени Маграм, и мои разведчики редко приносят вести о передвижениях их воинов." }, { 11.96, "Тем не менее, это один из главных кланов в Пустошах, которому удалось уцелеть до наших дней." }, { 18.25, "Значит, что-то они всё-таки делают правильно." }, { 21.36, "Если хочешь заключить мир с племенем Гелкис, отнеси эту сумку с тотемами в их деревню далеко на юго-западе." }, { 28.69, "Они, конечно, примитивны, но у них наверняка есть кто-то, кто отвечает за сокровища." } } } },
    [93317] = { d = 31.9, g = 1, v = "skyborne-female", n = { m = 341, f = 341 }, c = { m = { { 0.00, "Что тебе известно о ветроозёрных крабах?" }, { 2.94, "Они обитают только на озере Песни Ветра, а добывать их можно только раз в год, в течение нескольких недель." }, { 10.98, "Из-за бесчинств культа нам до сих пор не удалось сходить к озеру, а благоприятное время почти на исходе." }, { 18.67, "Я буду тебе очень благодарна, если отловишь немного." }, { 22.69, "Обычно их можно найти на берегу озера или в ближайших реках." }, { 27.30, "Только будь осторожен: эти крабы куда злее, чем кажутся." } }, f = { { 0.00, "Что тебе известно о ветроозёрных крабах?" }, { 2.99, "Они обитают только на озере Песни Ветра, а добывать их можно только раз в год, в течение нескольких недель." }, { 11.14, "Из-за бесчинств культа нам до сих пор не удалось сходить к озеру, а благоприятное время почти на исходе." }, { 18.96, "Я буду тебе очень благодарна, если отловишь немного." }, { 23.03, "Обычно их можно найти на берегу озера или в ближайших реках." }, { 27.72, "Только будь осторожна: эти крабы куда злее, чем кажутся." } } }, t = { d = 6.6, g = 1, v = "skyborne-female", n = { x = 46 }, c = { m = { { 0.00, "Клянусь ветром, до чего чудесное мясо!" }, { 4.07, "Огромное спасибо, герой." } }, f = { { 0.00, "Клянусь ветром, до чего чудесное мясо!" }, { 4.00, "Огромное спасибо, героиня." } } } } },
    [93318] = { d = 25.4, v = "narrator", n = { x = 281 }, c = { x = { { 0.00, "По распоряжению Аонды, констебля миротворцев, назначается награда за голову Вулгары Ненасытного, терроризирующего нагорье." }, { 9.24, "В последний раз его видели на вершине холма к юго-западу от деревни Шен'дар." }, { 15.17, "Эта крылатая бестия чрезвычайно опасна – соблюдайте осторожность." }, { 20.21, "Чтобы получить награду, принесите голову зверя Данарию Воющая Вуаль." } } }, t = { d = 13.7, g = 1, v = "skyborne-male", n = { m = 151, f = 152 }, c = { m = { { 0.00, "Нам хватает хлопот с сектантами и бандитами нагорья – гигантский лисвен, терроризирующий мирных жителей, нам точно не нужен." }, { 9.47, "Ты совершил благородный поступок." }, { 12.02, "Вот обещанная награда." } }, f = { { 0.00, "Нам хватает хлопот с сектантами и бандитами нагорья – гигантский лисвен, терроризирующий мирных жителей, нам точно не нужен." }, { 9.47, "Ты совершила благородный поступок." }, { 12.10, "Вот обещанная награда." } } } } },
    [93319] = { d = 28.3, v = "skyborne-female", n = { x = 317 }, c = { x = { { 0.00, "Ветрокамни – важный ресурс здесь, на Зефрисе, так что мы всегда держим у себя запасы для экстренных случаев." }, { 7.82, "Не так давно я заметила, что некоторая часть наших запасов пропала." }, { 12.68, "Мы нашли ветрокамни у бандитов, которых недавно поймали, – подозреваю, что они-то и стоят за кражей." }, { 19.98, "Если будешь идти мимо пещеры бандитов к северу отсюда, может, расшибёшь пару лбов и заберёшь украденные ветрокамни?" } } }, t = { d = 11.4, g = 1, v = "skyborne-female", n = { x = 121 }, c = { m = { { 0.00, "Спасибо, герой." }, { 1.19, "Этого нам пока должно хватить." }, { 3.52, "Но если мы не наладим снабжение в ближайшем будущем, украденные ветрокамни будут меньшей из наших проблем." } }, f = { { 0.00, "Спасибо, героиня." }, { 1.33, "Этого нам пока должно хватить." }, { 3.66, "Но если мы не наладим снабжение в ближайшем будущем, украденные ветрокамни будут меньшей из наших проблем." } } } } },
    [93320] = { d = 34.6, v = "skyborne-female", n = { x = 402 }, c = { x = { { 0.00, "Мне только что сообщили, что сектанты напали на сторожевую башню за городом." }, { 5.45, "К счастью, у нас была пара свободных миротворцев." }, { 9.02, "Я поручила им прорваться через тыл врага и поддержать защитников башни, но любая дополнительная помощь может означать разницу между жизнью и смертью наших бойцов." }, { 20.76, "Прошу, немедленно отправляйся к восточной сторожевой башне и окажи любую возможную помощь." }, { 27.31, "Подкрепление возглавляет Йорана Ветреный Тростник." }, { 30.94, "Если она ещё жива, то подскажет, что нужно сделать." } } }, t = { d = 10.2, v = "skyborne-female", n = { x = 112 }, c = { x = { { 0.00, "Пока что нам удаётся сдерживать врагов, но их больше, чем нас, а наши бойцы начинают уставать." }, { 7.04, "Мы должны пересилить противника, и поскорее." } } } } },
    [93341] = { d = 28.8, v = "nightelf-female#51", n = { x = 342 }, c = { x = { { 0.00, "Обязанности садовницы – поддерживать сад в идеальном состоянии." }, { 4.38, "Я знала, что однажды больше не смогу ухаживать за садом, поэтому наложила чары на ожерелье, подарок моей дочери." }, { 12.38, "Оно превратило новое поколение саженцев в древней, чтобы те следили за растениями вместо меня." }, { 19.11, "Я положила его на зачарованном пьедестале, укрытом в небольшом святилище." }, { 24.25, "Я оставила сад в надёжных руках." }, { 26.47, "Немедленно расскажи, что произошло." } } } },
    [93362] = { d = 32.4, v = "narrator", n = { x = 317 }, c = { x = { { 0.00, "Избавь меня от рассказа о напрасных смертях." }, { 3.75, "Утрата ожерелья и без того разбила мне сердце." }, { 7.65, "Но пока я скорблю, растения страдают." }, { 10.80, "Вернись в сады и вырви часть рассерженной флоры." }, { 14.85, "Только быстро и милосердно: растения чувствуют боль и успели настрадаться." }, { 21.00, "Когда решишь пойти на поиски моего ожерелья, прошу тебя не возвращаться в сады, пока не найдёшь его..." }, { 29.63, "Если всё-таки случится такое чудо." } } } },
    [93394] = { d = 21.5, v = "nightelf-male#59", n = { x = 259 }, c = { x = { { 0.00, "Подозреваю, что любопытство теперь влечёт тебя к великой святыне." }, { 4.57, "Я угадал?" }, { 5.27, "Отлично!" }, { 5.91, "Шен'дралары вряд ли встретят тебя с распростёртыми объятиями, но если проявишь почтительность, то бояться особенно нечего." }, { 14.36, "Если повезёт, ты быстро найдёшь моего старого друга Кирандиса." }, { 18.74, "Он-то отнесётся к тебе благосклоннее всех." } } } },
    [93404] = { d = 37.2, v = "narrator", n = { x = 317 }, c = { x = { { 0.00, "Я древень, нависающий над нами." }, { 2.93, "Я всё ещё пылаю, несмотря на дожди." }, { 6.19, "Даже в смерти я ощущаю укусы пламени." }, { 9.78, "Моя последняя ошибка стала для меня вечным бременем." }, { 14.79, "Я не знаю, почему проклят навсегда оставаться в этом месте." }, { 20.40, "Не понимаю, почему смерть не стала моим концом." }, { 24.83, "Прошу, потуши огонь." }, { 26.83, "Отыщи чистейшую воду в священном овраге." }, { 30.68, "Такое место есть в Машан'ше." }, { 33.35, "Я слышал, как о нём шептали ветра." }, { 36.53, "Мародон." } } } },
    [93429] = { d = 29.8, v = "human-male", n = { x = 334 }, c = { x = { { 0.00, "Хоть мы и сородичи, Заблудшие из Болотного пристанища знают теперь лишь жестокость и ненависть." }, { 6.94, "Нет для них ни искупления, ни спасения." }, { 9.75, "Эти бездумные, исполненные злобы существа обречены до конца дней своих скитаться по болоту." }, { 16.56, "Этим страданиям необходимо положить конец." }, { 19.76, "Кто-то должен избавить их от мучений." }, { 22.56, "Задача не из приятных, понимаю, но ты же сделаешь это ради защиты тех из нас, кто сохранил рассудок?" } } } },
    [93430] = { d = 31.8, g = 1, v = "human-male", n = { x = 375 }, c = { m = { { 0.00, "Они просто из берегов вышли!" }, { 2.01, "Будто бы обычных проделок этих пакостников было мало – так один из них украл мою счастливую блесну!" }, { 8.85, "Только я сегодня поутру принялся рыбачить, как один из них выпрыгнул из грязи, перерезал леску, схватил блесну и был таков." }, { 17.21, "Вор почти наверняка один из рыбаков Заблудших." }, { 20.38, "Небось удумал сам ей попользоваться." }, { 22.83, "Но без блесны я не смогу запасать рыбу, так что надо её вернуть." }, { 27.16, "Заблудшие ловят рыбу на берегах к востоку отсюда." }, { 30.58, "Разыщи вора, герой!" } }, f = { { 0.00, "Они просто из берегов вышли!" }, { 2.01, "Будто бы обычных проделок этих пакостников было мало – так один из них украл мою счастливую блесну!" }, { 8.82, "Только я сегодня поутру принялся рыбачить, как один из них выпрыгнул из грязи, перерезал леску, схватил блесну и был таков." }, { 17.15, "Вор почти наверняка один из рыбаков Заблудших." }, { 20.31, "Небось удумал сам ей попользоваться." }, { 22.74, "Но без блесны я не смогу запасать рыбу, так что надо её вернуть." }, { 27.06, "Заблудшие ловят рыбу на берегах к востоку отсюда." }, { 30.46, "Разыщи вора, героиня!" } } } },
    [93443] = { d = 42.0, v = "narrator", n = { x = 151 }, c = { x = { { 0.00, "Сбоку на ящик прилеплена написанная от руки этикетка." }, { 4.38, "На правой её стороне изображена карта с большим красным кружком, отмечающим место на юго-восточном побережье к северу от аляповато нарисованного храма, вокруг которого можно разглядеть воду и каких-то крылатых существ, а на левой крупными буквами нанесён текст." }, { 25.45, "Собственность Фриз Искродох" }, { 27.64, "Пороховой порт" }, { 28.81, "Предупреждение: не повреждать." }, { 31.21, "Не вскрывать без присмотра." }, { 33.40, "Внизу дополнительная приписка." }, { 35.88, "В случае утери вернуть владельцу, Фриз Искродох, в Пороховой порт в Лесоречье." } } } },
    [93450] = { d = 40.2, v = "nightelf-male#120", n = { x = 362 }, c = { x = { { 0.00, "У тела, конечно, есть свои недостатки, но призраку в разы сложнее." }, { 5.65, "Сяду на стул или не сяду?" }, { 7.86, "Споткнусь об кошку или нет?" }, { 10.23, "Но хуже всего то, что даже самых простых дел не сделать!" }, { 15.04, "Видишь меч на наковальне?" }, { 17.18, "Я начал его ковать тысячи лет назад, но умер, не успев закончить." }, { 22.83, "Теперь он мозолит мне глаза и к тому же занимает место – а у меня его не так уж чтобы много!" }, { 30.70, "Я не могу над ним работать!" }, { 32.99, "Не могу его даже ПЕРЕДВИНУТЬ!" }, { 35.58, "Помоги мне... э-э..." }, { 37.34, "\"переправить\" меч в мир духов." }, { 39.86, "Идёт?" } } } },
    [93459] = { d = 34.6, v = "skyborne-male", n = { x = 352 }, c = { x = { { 0.00, "Обычно ал'акетские сектанты обходят этот лес за километр – боятся призраков, которые якобы тут живут." }, { 8.12, "Ну, а мы с радостью поддерживаем эти слухи." }, { 11.57, "Друиды моего ордена хотят спокойно жить в Теневейном лесу, и сектанты нам тут не нужны." }, { 18.55, "Многие из нас напуганы." }, { 20.42, "У меня есть предложение." }, { 22.36, "Сразись с сектантами ради нас и принеси их уши." }, { 26.17, "Мы заплатим за каждое ухо деньгами, а когда ты покажешь себя настоящим другом, ещё и тайнами нашего ордена." } } }, t = { d = 2.6, v = "skyborne-male", n = { x = 23 }, c = { x = { { 0.00, "Вот твоя обещанная награда." } } } } },
    [93461] = { d = 29.6, v = "skyborne-female", n = { x = 332 }, c = { x = { { 0.00, "На вид ты будто бы из Высшего ордена." }, { 2.70, "Тех, чьи предки были высокорождёнными, всегда выдаёт едва уловимый блеск в глазах." }, { 8.56, "Прежде чем я загружу тебя работой, тебе стоит поговорить со старейшиной Высшего ордена, живущим здесь, – Ратирилом Солнечное Копьё." }, { 18.10, "Ты найдёшь его в главном здании, прямо за углом." }, { 21.65, "Ах да, к Кориэлле Спокойный Бриз тоже загляни – это хозяйка местной таверны, где можно получить кров и припасы." } } }, t = { d = 30.0, g = 1, v = "skyborne-female", n = { m = 306, f = 307 }, c = { m = { { 0.00, "Значит, ты поговорил с Ратирилом?" }, { 2.64, "Отлично." }, { 3.36, "Отношения у Высшего ордена и Ваятелей ветра сейчас напряжённые, но здесь, в Шен'даре, они сдерживают свой конфликт в определённых рамках." }, { 14.00, "По крайней мере в деревне." }, { 16.15, "О том, что происходит в степях, знают только ветры." }, { 20.22, "Так, с этим мы закончили..." }, { 22.36, "Похоже, ты ищешь себе занятие." }, { 24.86, "У меня есть пара предложений, если ты не прочь немного потрудиться." } }, f = { { 0.00, "Значит, ты поговорила с Ратирилом?" }, { 2.69, "Отлично." }, { 3.39, "Отношения у Высшего ордена и Ваятелей ветра сейчас напряжённые, но здесь, в Шен'даре, они сдерживают свой конфликт в определённых рамках." }, { 13.93, "По крайней мере в деревне." }, { 16.05, "О том, что происходит в степях, знают только ветры." }, { 20.08, "Так, с этим мы закончили..." }, { 22.20, "Похоже, ты ищешь себе занятие." }, { 24.68, "У меня есть пара предложений, если ты не прочь немного потрудиться." } } } } },
    [93464] = { d = 37.5, g = 1, v = "human-male", n = { x = 401 }, c = { m = { { 0.00, "Если позволишь, я должен кое в чём сознаться." }, { 3.40, "Дренетист для нас священен и помогает сохранять рассудок, однако никто здесь до конца его не понимает." }, { 10.92, "Помню, как-то раз в Убежище явился маг из Пустошей." }, { 14.72, "Человек по имени Азор." }, { 16.45, "Он боялся силы дренетиста и говорил, что она не должна попасть в чужие руки." }, { 22.18, "Мы прогнали его, чтобы защитить то, что принадлежало нам." }, { 26.37, "Но с недавних пор я задаюсь вопросом: что именно он мог знать?" }, { 30.83, "Прошу, найди этого мага, герой." }, { 33.30, "Его знания могут оказаться для нас чрезвычайно ценными." } }, f = { { 0.00, "Если позволишь, я должен кое в чём сознаться." }, { 3.41, "Дренетист для нас священен и помогает сохранять рассудок, однако никто здесь до конца его не понимает." }, { 10.95, "Помню, как-то раз в Убежище явился маг из Пустошей." }, { 14.76, "Человек по имени Азор." }, { 16.50, "Он боялся силы дренетиста и говорил, что она не должна попасть в чужие руки." }, { 22.24, "Мы прогнали его, чтобы защитить то, что принадлежало нам." }, { 26.45, "Но с недавних пор я задаюсь вопросом: что именно он мог знать?" }, { 30.92, "Прошу, найди этого мага, героиня." }, { 33.53, "Его знания могут оказаться для нас чрезвычайно ценными." } } } },
    [93465] = { d = 32.8, v = "human-male", n = { x = 388 }, c = { x = { { 0.00, "Скажем так... я знаю кое-кого, кто разбирается в свойствах дренетиста." }, { 4.90, "Понимаешь ли, чернокнижники Пылающего Клинка давно изучают дренетист." }, { 9.79, "Этот минерал попал к нам с той стороны Тёмного Портала, так что неудивительно, что тёмные заклинатели стремятся воспользоваться его силой." }, { 19.33, "Этого мы, разумеется, допустить не можем." }, { 22.26, "Тебе нужна чернокнижница по имени Гимаши." }, { 25.25, "Она находится на вершине башни, расположенной в ущелье к юго-востоку." }, { 30.15, "Её записи содержат нужные тебе ответы." } } } },
    [93546] = { d = 35.9, v = "narrator", n = { x = 312 }, c = { x = { { 0.00, "Наконец-то, НАКОНЕЦ-ТО я использую наковальню по назначению, а не вместо стола." }, { 6.33, "Дико тяжёлого, между прочим." }, { 8.65, "У меня руки чешутся снова отточить мастерство после веков без тренировки." }, { 14.69, "Ты, наверное, думаешь: \"Виндел как будто закидывает удочку к очередному поручению\"." }, { 21.38, "Так оно и есть!" }, { 22.62, "Мне надо пополнить запасы железа, но с ним такое же осложнение, как с мечом." }, { 28.73, "По счастью, решение куда проще." }, { 31.35, "Он суёт вам в руки призрачную кирку, не дожидаясь согласия." } } } },
    [93552] = { d = 29.7, v = "skyborne-female#3773", n = { x = 318 }, c = { x = { { 0.00, "Ветрокамень – важнейший ресурс на острове Зефрис, так как он содержит концентрированную энергию ветров." }, { 7.84, "Духи ветра, когда-то жившие здесь с нами, исчезли несколько лет назад, и с тех пор магия, поддерживавшая жизнь на острове, медленно угасает." }, { 18.63, "Ветрокамень – не идеальный, но надёжный источник энергии, так что мы его очень ценим." }, { 25.07, "Куски ветрокамня разбросаны по роще." }, { 27.94, "Поможешь мне собрать их?" } } }, t = { d = 21.4, v = "skyborne-female#3773", n = { x = 222 }, c = { x = { { 0.00, "Спасибо тебе большое." }, { 1.78, "Мы, эльфы, тесно связаны с магией, и эти ветрокамни становятся всё ценнее по мере того как магия, наполняющая наши земли благодаря опорным столпам, продолжает рассеиваться." }, { 15.46, "Но земля богата не только ветрокамнями." }, { 18.59, "Вот, возьми одно из этих руководств." } } } } },
    [93568] = { d = 34.7, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Вы держите склизкий ошейник, извлечённый из брюха убитого зверя." }, { 5.07, "Он сделан из качественной кожи и прошит аккуратными стежками." }, { 9.93, "С ржавого кольца свисает бирка." }, { 12.51, "Вы стираете жижу и видите талассийские буквы, но шрифт так разукрасили завитушками, что даже знаток языка вряд ли смог бы что-то прочитать." }, { 23.37, "Перед вами встаёт выбор." }, { 25.37, "Выбросить находку и пойти по своим делам – или вопреки всякому здравому смыслу попробовать отыскать и утешить хозяина?" } } } },
    [93572] = { d = 35.0, g = 1, v = "creature/lostone", n = { m = 330, f = 333 }, c = { m = { { 0.00, "Пусть ты и принёс Кум'ише сферу из дренетиста, но это показывает Кум'ише лишь твою удачу, а не умение." }, { 8.26, "Если хочешь заслужить награду, ты поможешь собратьям Кум'иши вернуться домой." }, { 14.68, "Кум'иша откроет этой сферой разлом, а другие дренеи пройдут сквозь него." }, { 20.74, "Какая бы опасность оттуда ни появилась — ты будешь с ней сражаться." }, { 26.20, "Если хоть кто-то из братьев и сестёр Кум'иши пострадает, о награде можешь забыть." }, { 32.84, "Ты готов, путник?" } }, f = { { 0.00, "Пусть ты и принесла Кум'ише сферу из дренетиста, но это показывает Кум'ише лишь твою удачу, а не умение." }, { 8.75, "Если хочешь заслужить награду, ты поможешь собратьям Кум'иши вернуться домой." }, { 15.17, "Кум'иша откроет этой сферой разлом, а другие дренеи пройдут сквозь него." }, { 21.23, "Какая бы опасность оттуда ни появилась — ты будешь с ней сражаться." }, { 26.69, "Если хоть кто-то из братьев и сестёр Кум'иши пострадает, о награде можешь забыть." }, { 33.06, "Ты готова, путница?" } } } },
    [93574] = { d = 34.9, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "С ужасающим хрустом вы отрываете кусок панциря мёртвого червя." }, { 4.92, "Несмотря на огромные размеры и внушительный вес, он кажется самым обычным." }, { 10.77, "По-видимому, это существо не было результатом жестокого эксперимента и не выводилось как жуткое чудовище, пожирающее всё на своём пути." }, { 21.33, "Это просто мощный панцирь, который заинтересует, вероятно, только коллекционеров." }, { 27.83, "Возможно, вы найдёте того, кому он приглянется." }, { 31.54, "Но кто ещё может здесь жить, кроме кентавров?" } } } },
    [93585] = { d = 32.1, g = 1, v = "human-male", n = { x = 377 }, c = { m = { { 0.00, "Слава Свету, хоть кто-то цивилизованный!" }, { 2.82, "Я пришёл сюда от имени Церкви Света Небес, чтобы наладить контакт с дренеями из Убежища." }, { 9.03, "Видишь ли, у Альянса здесь нет плацдарма и дипломатическая миссия к местным жителям вполне может исправить это упущение." }, { 17.37, "В конце концов, Свет принимает в своё лоно всех!" }, { 20.69, "Но за этим мостом дорога кишит дикими сородичами дренеев." }, { 24.76, "Так что мне понадобится защита, чтобы благополучно добраться до Убежища." }, { 29.72, "Не согласишься ли мне помочь, герой?" } }, f = { { 0.00, "Слава Свету, хоть кто-то цивилизованный!" }, { 2.81, "Я пришёл сюда от имени Церкви Света Небес, чтобы наладить контакт с дренеями из Убежища." }, { 8.99, "Видишь ли, у Альянса здесь нет плацдарма и дипломатическая миссия к местным жителям вполне может исправить это упущение." }, { 17.30, "В конце концов, Свет принимает в своё лоно всех!" }, { 20.61, "Но за этим мостом дорога кишит дикими сородичами дренеев." }, { 24.67, "Так что мне понадобится защита, чтобы благополучно добраться до Убежища." }, { 29.60, "Не согласишься ли мне помочь, героиня?" } } } },
    [93594] = { d = 32.6, v = "narrator", n = { x = 314 }, c = { x = { { 0.00, "Ожерелье подарило жизнь и разум нескольким древням, но один выделялся на фоне прочих." }, { 7.18, "Этот древень выстоял бы, даже если пали все остальные." }, { 11.86, "Он целыми днями ухаживал за каждым цветком и бутоном, а вечерами врастал в землю и подставлял крону гнёздам мелких зверушек." }, { 22.29, "Если он жив – на что я горячо надеюсь – то он может знать, что случилось." }, { 28.26, "Я не хочу верить, что мой добрый друг Вещедрев погиб." } } } },
    [93601] = { d = 18.8, v = "creature/ancient", n = { x = 159 }, c = { x = { { 0.00, "Если хочешь вернуть подарок той женщины, иди на север, в Долину Костей." }, { 6.95, "Его украли." }, { 8.15, "Виноваты свинобразы." }, { 10.13, "Это видели мои собственные глазолуковицы." }, { 14.16, "Из-за них этот сад обречён на гибель." }, { 17.68, "Не прощай их." } } } },
    [93604] = { d = 50.6, g = 1, v = "quilboar-male", n = { m = 432, f = 432 }, c = { m = { { 0.63, "Большой путник слышать про курганы Иглошкурых?" }, { 5.35, "Конечно, нет!" }, { 6.60, "Большое место в Степях." }, { 8.83, "Много шипов." }, { 10.08, "Не пропустить." }, { 11.40, "Агамагган умереть там." }, { 13.47, "Важное место для всех свинобразов." }, { 16.62, "Теперь дыбогривам туда нельзя." }, { 19.52, "Принадлежит сопливым-хрюкливым Иглошкурым." }, { 23.42, "Иглошкурые не уважать историю свинобразов!" }, { 27.31, "Кровь Агамаггана питать долину." }, { 30.21, "Растить шипы." }, { 31.53, "БОЛЬШИЕ." }, { 32.36, "Больше, чем хилое эльфийское ожерелье когда-либо мочь!" }, { 37.33, "Иди в курганы." }, { 38.74, "Принеси Ког'тугу кровь." }, { 40.90, "Тухлая кровь из Лабиринтов не годиться." }, { 44.46, "Нужна ХОРОШАЯ кровь!" }, { 46.37, "Дай кровь, получи ожерелье, победа." } }, f = { { 0.35, "Большая путница слышать про курганы Иглошкурых?" }, { 5.31, "Конечно, нет!" }, { 6.48, "Большое место в Степях." }, { 8.57, "Много шипов." }, { 9.73, "Не пропустить." }, { 10.98, "Агамагган умереть там." }, { 12.92, "Важное место для всех свинобразов." }, { 15.86, "Теперь дыбогривам туда нельзя." }, { 18.58, "Принадлежит сопливым-хрюкливым Иглошкурым." }, { 22.23, "Иглошкурые не уважать историю свинобразов!" }, { 25.87, "Кровь Агамаггана питать долину." }, { 28.59, "Растить шипы." }, { 29.83, "БОЛЬШИЕ." }, { 30.61, "Больше, чем хилое эльфийское ожерелье когда-либо мочь!" }, { 35.26, "Иди в курганы." }, { 36.58, "Принеси Ког'тугу кровь." }, { 38.60, "Тухлая кровь из Лабиринтов не годиться." }, { 41.94, "Нужна ХОРОШАЯ кровь!" }, { 43.72, "Дай кровь, получи ожерелье, победа." } } } },
    [93606] = { d = 47.2, g = 1, v = "quilboar-male", n = { m = 422, f = 422 }, c = { m = { { 0.35, "Кволга Мудрая — подруга жизни Ког'туга." }, { 3.61, "Кволга — великая плетельщица шипов, за это Ког'туг её и любить." }, { 8.76, "А ещё у Кволги есть ожерелье, которое Большой путник ищет." }, { 13.47, "Беда?" }, { 13.98, "Мы с ней не хрюкаем друг с другом." }, { 16.66, "Она злиться, что мы вообще украли ожерелье." }, { 20.21, "А зачем тогда сама им пользоваться?" }, { 23.11, "Вот что Ког'туг хотеть знать!" }, { 25.43, "НО!" }, { 25.72, "Кволга любить цветы не меньше, чем шипы." }, { 29.06, "Знаешь, где взять цветы?" }, { 31.01, "Там же, где мы взять ожерелье!" }, { 33.33, "Может, она не злиться на Ког'туга, если Большой путник принести цветы и эту кровь от него?" }, { 40.73, "Может, она обменять ожерелье!" }, { 43.20, "Скажи ей, Ког'туг жалеть." } }, f = { { 0.79, "Кволга Мудрая — подруга жизни Ког'туга." }, { 4.09, "Кволга — великая плетельщица шипов, за это Ког'туг её и любить." }, { 9.29, "А ещё у Кволги есть ожерелье, которое Большая путница ищет." }, { 14.13, "Беда?" }, { 14.64, "Мы с ней не хрюкаем друг с другом." }, { 17.35, "Она злиться, что мы вообще украли ожерелье." }, { 20.95, "А зачем тогда сама им пользоваться?" }, { 23.88, "Вот что Ког'туг хотеть знать!" }, { 26.22, "НО!" }, { 26.52, "Кволга любить цветы не меньше, чем шипы." }, { 29.89, "Знаешь, где взять цветы?" }, { 31.87, "Там же, где мы взять ожерелье!" }, { 34.21, "Может, она не злиться на Ког'туга, если Большая путница принести цветы и эту кровь от него?" }, { 41.76, "Может, она обменять ожерелье!" }, { 44.26, "Скажи ей, Ког'туг жалеть." } } } },
    [93609] = { d = 21.1, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Ожерелье, которое вы искали, наконец у вас, но, к сожалению, заключённая в нём магия полностью иссякла." }, { 8.08, "Для вашего нынешнего положения это не лучший исход, зато хотя бы получить его у свинобразов оказалось сравнительно легко." }, { 17.88, "Пожалуй, лучше всего отнести его Митере." } } } },
    [93644] = { d = 27.3, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Этот старый грязный фолиант, найденный неподалёку от Шен'драласа, утратил большую часть содержавшихся в нём знаний." }, { 8.58, "В сохранившемся тексте трудно разобрать даже отдельные буквы, из которых составлены слова." }, { 15.45, "Поначалу чтение даётся с трудом, но вам вроде бы удаётся разобрать какую-то фамилию." }, { 21.71, "Возможно, автора книги зовут Вечерняя Тень и он находится где-то неподалёку." } } } },
    [93663] = { d = 37.0, v = "orc-male", n = { x = 368 }, c = { x = { { 0.00, "Дренеи Убежища – искусные рыбаки и готовы бороздить более опасные воды, чем я." }, { 6.44, "Мы иногда с ними торгуем." }, { 8.57, "Они отдают нам часть своего улова, а я предлагаю им излишки припасов." }, { 14.20, "Я отправил гоблина-курьера доставить новую партию товаров, но он так и не вернулся." }, { 20.94, "Вероятно, стал кормом для кроколиска." }, { 23.94, "Но важнее всего то, что на кону моя деловая репутация." }, { 28.41, "Этот груз кровь из носу нужно отыскать и доставить в Убежище." }, { 33.39, "Прошу, найди его." }, { 34.92, "Осмотри водоёмы близ дороги." } } } },
    [93678] = { d = 37.0, v = "narrator", n = { x = 388 }, c = { x = { { 0.00, "Вот расшифровка заметок Гимаши о дренетисте." }, { 3.46, "Похоже, осколки обладают некоторым запасом энергии, но цельная сфера из этого вещества гораздо могущественнее." }, { 12.14, "Видимо, за ней и охотился Пылающий Клинок." }, { 15.45, "Во многих заметках Гимаши упоминаются порталы и ритуалы призыва демонов." }, { 21.17, "Но куда ведут эти порталы и каких демонов призывают – точно сказать не могу." }, { 27.31, "Пусть мои ответы и не окончательны, прошу, отнеси эти заметки обратно на болото." }, { 33.66, "Надеюсь, ты поймёшь, если я не пойду с тобой." } } } },
    [93679] = { d = 23.5, g = 1, v = "creature/lostone", n = { m = 241, f = 243 }, c = { m = { { 0.00, "Рад снова тебя видеть." }, { 1.84, "Я прочитал заметки, которые ты нам принёс, и обсудил это дело с Онку, нашим старейшим провидцем." }, { 9.41, "Недавно ему было видение, которое может привести нас к сфере из дренетиста." }, { 15.43, "Мы хотели бы поделиться с тобой тем, что открылось в этом видении." }, { 20.60, "Не присоединишься ли к нам ненадолго?" } }, f = { { 0.00, "Рад снова тебя видеть." }, { 1.84, "Я прочитал заметки, которые ты нам принесла, и обсудил это дело с Онку, нашим старейшим провидцем." }, { 9.60, "Недавно ему было видение, которое может привести нас к сфере из дренетиста." }, { 15.62, "Мы хотели бы поделиться с тобой тем, что открылось в этом видении." }, { 20.79, "Не присоединишься ли к нам ненадолго?" } } } },
    [93680] = { d = 42.3, v = "scourge-male#82", n = { x = 423 }, c = { x = { { 0.00, "Раньше Альянс располагал войском магов, известным как Кирин-Тор." }, { 5.32, "Но, как бы велико ни было их могущество, Пылающий Легион оказался ещё сильнее." }, { 11.67, "Одним ударом демон Архимонд сровнял их город с землёй, словно песочный замок." }, { 18.10, "Те, кто уцелел, превратились в бездомных скитальцев." }, { 22.31, "По крайней мере, так продолжалось до тех пор, пока они не отстроили Даларан." }, { 28.51, "И где – прямо под носом у Тёмной Госпожи!" }, { 31.84, "Обыщи их лагерь и постарайся найти что-нибудь, что позволит нам незаметно пробраться в город." }, { 39.45, "Мне нужно узнать, что там происходит." } } }, t = { d = 13.3, v = "scourge-male#82", n = { x = 128 }, c = { x = { { 0.00, "Ключ от канализации?" }, { 1.74, "Что ж, к счастью, пользоваться им придётся не мне." }, { 5.93, "Но прежде чем им можно будет безопасно воспользоваться, нам предстоит кое-что сделать." } } } } },
    [93684] = { d = 36.1, v = "creature/lostone", n = { x = 354 }, c = { x = { { 0.00, "Других поселений, подобных нашему, я не знаю, но мне попадались заблудшие к югу отсюда, в Выжженных землях." }, { 8.80, "Они очень похожи на тех, что в Болотном пристанище, — враждебные и лишённые разума." }, { 15.53, "Мне казалось, что такая участь постигла там всех наших сородичей." }, { 20.85, "Но если видение Онку указывает на одинокого дренея, бродящего по пустоши, то, возможно, моя догадка была неверна." }, { 30.24, "Я снова обращаюсь к тебе." }, { 32.39, "Найди этого дренея и помоги ему, чем сможешь." } } } },
    [93685] = { d = 46.2, g = 1, v = "creature/lostone", n = { x = 432 }, c = { m = { { 0.00, "Путник, может ли твой ничтожный мозг понять, какая это редкость — безупречная сфера из дренетиста?" }, { 8.15, "Некоторые дренеи тратили всю жизнь на поиски одного-единственного такого кристалла — и всё лишь для того, чтобы встретить ужасную судьбу, так и не достигнув цели." }, { 21.45, "И вот ты стоишь перед Кум'ишей, знаешь, что требуется Кум'ише, и всё ещё желаешь помочь?" }, { 28.70, "Отлично, путник..." }, { 30.27, "В любой момент своего путешествия по этим землям, если ты найдёшь безупречную сферу из дренетиста, верни её мне, и я вознагражу тебя так, как тебе и не грезилось в самых безумных мечтах." } }, f = { { 0.00, "Путница, может ли твой ничтожный мозг понять, какая это редкость — безупречная сфера из дренетиста?" }, { 8.38, "Некоторые дренеи тратили всю жизнь на поиски одного-единственного такого кристалла — и всё лишь для того, чтобы встретить ужасную судьбу, так и не достигнув цели." }, { 21.68, "И вот ты стоишь перед Кум'ишей, знаешь, что требуется Кум'ише, и всё ещё желаешь помочь?" }, { 28.93, "Отлично, путница..." }, { 31.06, "В любой момент своего путешествия по этим землям, если ты найдёшь безупречную сферу из дренетиста, верни её мне, и я вознагражу тебя так, как тебе и не грезилось в самых безумных мечтах." } } } },
    [93689] = { d = 18.2, g = 1, v = "narrator", n = { m = 192, f = 196 }, c = { m = { { 0.00, "Это прекрасные новости!" }, { 1.87, "Раз в Даларан вернулся мир, я не вижу ни одной причины, по которой Кирин-Тор не встретил бы тебя с распростёртыми объятиями!" }, { 11.25, "Прошу, поспеши к совету." }, { 13.19, "Там наверняка с нетерпением ждут встречи со спасителем города." } }, f = { { 0.00, "Это прекрасные новости!" }, { 1.87, "Раз в Даларан вернулся мир, я не вижу ни одной причины, по которой Кирин-Тор не встретил бы тебя с распростёртыми объятиями!" }, { 11.25, "Прошу, поспеши к совету." }, { 13.19, "Там наверняка с нетерпением ждут встречи со спасительницей города." } } } },
    [93735] = { d = 31.4, v = "skyborne-female", n = { x = 349 }, c = { x = { { 0.00, "Ваятели ветра издавна ухаживали за магическими инструментами и устройствами, подаренными нам духами воздуха." }, { 8.12, "В том числе за множеством магических големов на острове – увы, с тех пор как духи нас покинули, почти все они перестали работать." }, { 17.81, "Один из немногих действующих големов в Валанааре был повреждён." }, { 22.51, "Мы отправили на помощь мастера, но ему может понадобиться помощник." }, { 27.63, "Иди в западную часть города и предложи свои услуги." } } }, t = { d = 19.8, v = "skyborne-male", n = { x = 108 }, c = { x = { { 0.00, "*Лицо Рииани скрыто под тяжёлыми пластинами голема – мастер пытается что-то делать с механизмом внутри.*" }, { 8.30, "*Он не замечает вас.*" }, { 9.76, "Проклятие бури, где ядро?" }, { 11.79, "Кто такой умный догадался вытащить ещё и гирозефир?" }, { 15.79, "Чудо, что ветра голема ещё не рассеялись окончательно!" } } } } },
    [93736] = { d = 33.8, g = 1, v = "skyborne-female", n = { m = 339, f = 341 }, c = { m = { { 0.00, "Главный вопрос, который занимает Ваятелей ветра: почему духи нас покинули и что мы можем сделать, чтобы их вернуть." }, { 9.07, "Одной характерной особенностью Теневейного леса стало появление необычных духов, которых прозвали мертвенями." }, { 17.65, "Мы мало что о них знаем, кто они и откуда взялись, но они начали появляться после ухода духов ветра." }, { 25.60, "Я хочу, чтобы ты отправился туда и рассеял этих духов." }, { 29.96, "Собери их останки и принеси сюда." } }, f = { { 0.00, "Главный вопрос, который занимает Ваятелей ветра: почему духи нас покинули и что мы можем сделать, чтобы их вернуть." }, { 9.39, "Одной характерной особенностью Теневейного леса стало появление необычных духов, которых прозвали мертвенями." }, { 18.27, "Мы мало что о них знаем, кто они и откуда взялись, но они начали появляться после ухода духов ветра." }, { 26.49, "Я хочу, чтобы ты отправилась туда и рассеяла этих духов." }, { 31.15, "Собери их останки и принеси сюда." } } }, t = { d = 19.3, v = "skyborne-female", n = { x = 170 }, c = { x = { { 0.00, "Эти сущности переполняют меня чувством... глубокой тревоги." }, { 5.13, "Я почти физически ощущаю их ауру, смесь злости и сожаления." }, { 10.18, "Иногда кажется, что я начинаю терять сознание." }, { 14.08, "*Эндария содрогается.*" }, { 16.16, "Надеюсь, мне не придётся больше их изучать." } } } } },
    [93737] = { d = 15.4, v = "skyborne-male", n = { x = 155 }, c = { x = { { 0.00, "О, привет." }, { 0.84, "Айесса прислала тебя помочь мне?" }, { 3.41, "Ну, хорошо." }, { 4.31, "Не знаю, что тут может сделать новичок вроде тебя, но дай я вытащу голову из нутра голема – у меня есть пара мыслей, что ещё тебе можно поручить." } } }, t = { d = 16.6, g = 1, v = "skyborne-male", n = { m = 175, f = 177 }, c = { m = { { 0.00, "Спасибо, что принёс материалы." }, { 2.17, "Догадываюсь, что кое-что было не так-то просто достать." }, { 6.26, "С этими деталями я могу снова запустить голема." }, { 9.81, "Будем надеяться, что его память не пострадала, и он скажет нам, кто забрал его части." } }, f = { { 0.00, "Спасибо, что принесла материалы." }, { 2.44, "Догадываюсь, что кое-что было не так-то просто достать." }, { 6.63, "С этими деталями я могу снова запустить голема." }, { 10.28, "Будем надеяться, что его память не пострадала, и он скажет нам, кто забрал его части." } } } } },
    [93738] = { d = 33.4, v = "skyborne-male", n = { x = 350 }, c = { x = { { 0.00, "Яркая Мечта?" }, { 1.04, "Значит, Высший орден решил изъять эти компоненты." }, { 5.00, "Но для чего, с какой целью?" }, { 7.15, "Орден всегда лез в наши дела, им было интересно поэкспериментировать с магией духов ветра." }, { 14.15, "Смелость на грани глупости, мы категорически запретили им посягать на тайны Ваятелей ветра, – но в последнее время они снова начали испытывать наше терпение." }, { 26.29, "Думаю, тебе стоит рассказать об этом Айессе Певице Рассвета." }, { 31.08, "Она скажет, что делать дальше." } } }, t = { d = 18.5, v = "skyborne-female", n = { x = 176 }, c = { x = { { 0.00, "Как интересно." }, { 1.21, "Значит, в поломке голема виноват Высший орден?" }, { 5.23, "Я знаю Белатаана." }, { 6.74, "Он двоюродный брат Валеннии Штормовой Кулак, а его мать была Ваятельницей ветра." }, { 13.48, "Очень жаль, что его впутали в это дело." }, { 16.89, "Мне надо подумать..." } } } } },
    [93739] = { d = 27.1, g = 1, v = "named/thrall", n = { m = 256, f = 257 }, c = { m = { { 0.00, "Азерот – огромный мир, и владения Орды обширны." }, { 4.11, "В каждом из наших городов – Подгороде, Оргриммаре и Громовом Утёсе – обитают разные народы с уникальной культурой." }, { 13.79, "Если ты хочешь быть гостем Орды здесь, на Азероте, тебе будет полезно по очереди посетить каждую из наших столиц." }, { 23.63, "Мой советник Назгрел укажет тебе дорогу." } }, f = { { 0.00, "Азерот – огромный мир, и владения Орды обширны." }, { 4.11, "В каждом из наших городов – Подгороде, Оргриммаре и Громовом Утёсе – обитают разные народы с уникальной культурой." }, { 13.79, "Если ты хочешь быть гостьей Орды здесь, на Азероте, тебе будет полезно по очереди посетить каждую из наших столиц." }, { 23.71, "Мой советник Назгрел укажет тебе дорогу." } } }, t = { d = 21.9, g = 1, v = "named/thrall", n = { m = 217, f = 218 }, c = { m = { { 0.00, "Итак, ты вернулся." }, { 1.57, "Надеюсь, путешествие многому тебя научило." }, { 5.16, "Насколько я понимаю, твой народ всё ещё обустраивается в Мулгоре." }, { 10.47, "Пока ждёшь, советую тебе исследовать земли вокруг Оргриммара." }, { 15.64, "В Степях, к примеру, всегда нужны такие рьяные искатели приключений, как ты." } }, f = { { 0.00, "Итак, ты вернулась." }, { 1.65, "Надеюсь, путешествие многому тебя научило." }, { 5.24, "Насколько я понимаю, твой народ всё ещё обустраивается в Мулгоре." }, { 10.55, "Пока ждёшь, советую тебе исследовать земли вокруг Оргриммара." }, { 15.71, "В Степях, к примеру, всегда нужны такие рьяные искатели приключений, как ты." } } } } },
    [93740] = { d = 26.6, v = "skyborne-female", n = { x = 286 }, c = { x = { { 0.00, "Этим утром на нагорье нашли несколько тел молодых Ваятелей ветра." }, { 5.12, "Мы не знаем точно, но с большой вероятностью за этим стоят ал'акетские сектанты." }, { 11.28, "Ваятели ветра всегда готовы пролить кровь за кровь." }, { 15.23, "Иди на север и убей всех ал'акетов, которых увидишь." }, { 19.31, "Принеси мне их ветрокаменные молитвенные талисманы в знак победы." }, { 24.23, "Мы не прощаем и не забываем обид." } } }, t = { d = 17.3, v = "skyborne-female", n = { x = 90 }, c = { x = { { 0.00, "*Айесса выглядит потрясённой и без всякого выражения смотрит на протянутые ей ветрокаменные талисманы.*" }, { 7.84, "Не обращай на меня внимания." }, { 10.21, "Просто сегодня был... тяжёлый день." }, { 13.03, "Спасибо за всё, что ты делаешь для Ваятелей ветра." } } } } },
    [93746] = { d = 30.8, v = "skyborne-female", n = { x = 327 }, c = { x = { { 0.00, "Высший орден предупреждали о том, что будет, если лезть в дела Ваятелей ветра." }, { 5.93, "Думаю, надо показательно наказать Белатаана и вернуть в орден – понаставив синяков и научив уважать наши правила." }, { 14.59, "Его видели, когда он выходил из города и направлялся на север в святилище Акира." }, { 20.72, "Не знаю, что ему там нужно, но безопаснее всего будет перехватить его по пути, когда он будет один." }, { 28.36, "Отыщи его и припугни как следует." } } }, t = { d = 31.9, g = 1, v = "skyborne-female", n = { m = 275, f = 277 }, c = { m = { { 0.00, "Что-что?" }, { 1.30, "Белатаан... мёртв?" }, { 3.76, "*Айесса слушает ваш рассказ о произошедшем.*" }, { 7.44, "Высший орден вёл мирные переговоры с сектой Ал'акета?" }, { 11.57, "С ними невозможно договориться, это фанатичные убийцы." }, { 15.77, "О чём Элаадрин только думал, посылая к ним Белатаана одного?" }, { 20.38, "Не принимай близко к сердцу." }, { 22.58, "Ты не виноват, это всё из-за высокомерия ордена... опять." }, { 26.99, "А ты просто оказался в правильном месте в неправильное время." } }, f = { { 0.00, "Что-что?" }, { 1.32, "Белатаан... мёртв?" }, { 3.84, "*Айесса слушает ваш рассказ о произошедшем.*" }, { 7.44, "Высший орден вёл мирные переговоры с сектой Ал'акета?" }, { 11.61, "С ними невозможно договориться, это фанатичные убийцы." }, { 15.86, "О чём Элаадрин только думал, посылая к ним Белатаана одного?" }, { 20.52, "Не принимай близко к сердцу." }, { 22.75, "Ты не виновата, это всё из-за высокомерия ордена... опять." }, { 27.27, "А ты просто оказалась в правильном месте в неправильное время." } } } } },
    [93786] = { d = 30.6, v = "orc-male#60", n = { x = 335 }, c = { x = { { 0.00, "А твой клинок жаждет крови людей?" }, { 2.55, "Несколько лет назад дезертиры из Альянса заняли небольшую ферму на юго-западе за рекой." }, { 9.12, "Там богатые края, много камня и древесины, и вскоре они расширили свои владения до крепости Фархолд на восточном берегу." }, { 18.18, "Первые стычки закончились бы в нашу пользу, будь у нас достаточно бойцов." }, { 23.61, "Пора напомнить им, что мы всё ещё здесь." }, { 26.49, "Атакуй ферму." }, { 27.57, "Не бери пленников." }, { 28.98, "Пусть знают, что их ждёт." } } } },
    [93787] = { d = 21.4, v = "orc-male#60", n = { x = 215 }, c = { x = { { 0.00, "Люди привыкли, что в этих краях им тепло, сытно и спокойно." }, { 4.79, "Пора лишить их всего этого." }, { 7.08, "Отыщи припасы наших врагов на ферме к юго-западу." }, { 11.15, "Забери всё, что найдёшь." }, { 13.01, "Это не так приятно, как обагрить клинок, но ослабит врага и даст нам время, чтобы спланировать следующий шаг." } } } },
    [93788] = { d = 31.6, v = "orc-female#124", n = { x = 336 }, c = { x = { { 0.00, "Теперь, когда на юге орудуют люди, а на западе – сектанты, борьба за ресурсы особенно ожесточилась." }, { 7.68, "Но зачем добывать ресурсы на глазах у врагов, когда сойдут и их клинки?" }, { 13.21, "Иди вдоль реки на юг и придёшь к лесопилке." }, { 16.46, "Сбавь шаг, как только услышишь насвистывающих рабочих." }, { 20.54, "Выгадай благоприятный момент и нанеси удар." }, { 23.93, "Я останусь здесь и разогрею кузню." }, { 26.56, "Гур'док раздробит лезвия, а я выкую оружие из вражеских материалов." } } } },
    [93791] = { d = 25.5, g = 1, v = "skyborne-male", n = { m = 279, f = 280 }, c = { m = { { 0.00, "Ты определённо поднаторел в магии, и пришло время последовать одной из старейших традиций Высшего ордена для молодых и начинающих магов." }, { 10.43, "Пора тебе изготовить собственное средоточие заклинаний." }, { 14.75, "Найди Беланна Древо Ветров в Валанааре." }, { 17.88, "Он уже больше века изготавливает посохи и жезлы для Высшего ордена – лучшего наставника и не сыщешь." } }, f = { { 0.00, "Ты определённо поднаторела в магии, и пришло время последовать одной из старейших традиций Высшего ордена для молодых и начинающих магов." }, { 10.38, "Пора тебе изготовить собственное средоточие заклинаний." }, { 14.64, "Найди Беланна Древо Ветров в Валанааре." }, { 17.73, "Он уже больше века изготавливает посохи и жезлы для Высшего ордена – лучшего наставника и не сыщешь." } } }, t = { d = 12.3, v = "skyborne-male", n = { x = 122 }, c = { x = { { 0.00, "А, вот и ты!" }, { 0.95, "Отрадно видеть молодых магов, неравнодушных к нашей истории и обычаям." }, { 6.71, "Идём, я тебе объясню, что надо делать, чтобы создать фокус заклинания." } } } } },
    [93797] = { d = 35.4, v = "skyborne-male", n = { x = 398 }, c = { x = { { 0.00, "У нас есть давняя традиция: когда молодые маги достигают определённого уровня мастерства, они создают собственный фокус заклинаний." }, { 9.70, "Обычно мы берём для этого упавшую ветвь одного из старейших деревьев, поскольку в них ещё осталась энергия стихии ветра." }, { 18.52, "Я обнаружил, что лучшие образцы можно найти у святилища ветра, что к югу от деревни Фалаат." }, { 25.34, "Отправляйся туда и принеси мне большую ветвь, а пока будем создавать твой фокус заклинаний, я расскажу тебе ещё больше о наших традициях." } } }, t = { d = 19.5, v = "skyborne-male", n = { x = 184 }, c = { x = { { 0.00, "Спасибо." }, { 0.74, "Я чувствую в этой ветви энергию стихии, которая только и ждёт, чтобы её обуздали." }, { 7.50, "Из неё получится превосходный фокус заклинаний." }, { 11.36, "Может быть, эта ветвь взывала к тебе?" }, { 14.48, "Так часто бывает: ветвь выбирает мага, а не наоборот." } } } } },
    [93835] = { d = 25.6, g = 1, v = "skyborne-female", n = { x = 264 }, c = { m = { { 0.00, "Лортуна сбежала к вершинам через какой-то портал." }, { 3.87, "Айесса и Элаадрин последовали за ней." }, { 6.70, "Всё произошло пару мгновений назад." }, { 9.46, "Боюсь, мне слишком досталось, чтобы продолжать." }, { 13.12, "Пройди через портал, найди Элаадрина и помоги остановить Лортуну." }, { 18.23, "Элаадрин и Айесса послали за подкреплением, но оно может к вам не успеть." }, { 23.83, "Удачи тебе, герой." } }, f = { { 0.00, "Лортуна сбежала к вершинам через какой-то портал." }, { 3.91, "Айесса и Элаадрин последовали за ней." }, { 6.77, "Всё произошло пару мгновений назад." }, { 9.56, "Боюсь, мне слишком досталось, чтобы продолжать." }, { 13.26, "Пройди через портал, найди Элаадрина и помоги остановить Лортуну." }, { 18.42, "Элаадрин и Айесса послали за подкреплением, но оно может к вам не успеть." }, { 24.07, "Удачи тебе, героиня." } } }, t = { d = 26.8, v = "skyborne-male", n = { x = 291 }, c = { x = { { 0.00, "Я велел нескольким оставшимся магам проследить за тем, чтобы Валенния и её бойцы тоже смогли уйти." }, { 7.54, "Сейчас она должна отдыхать у верховного старейшины Песни Теней." }, { 12.48, "Ансирем был вынужден вернуться на Азерот, но мы с ним успели обсудить дальнейшие шаги Высшего ордена." }, { 20.16, "Сегодня мы выжили, но теперь Зефрис опасно уязвим, и мы должны составить план на будущее." } } } } },
    [93836] = { d = 29.8, v = "skyborne-female", n = { x = 328 }, c = { x = { { 0.00, "Мулн рассказал мне про повелителей элементалей, и я боюсь, что у нас есть все основания бояться Ал'акира." }, { 7.61, "Без оберегов, которые скрывали Зефрис от его взора, мы совершенно беззащитны." }, { 13.41, "И если он нападёт на нас здесь, в его владениях, мы обречены." }, { 17.86, "Надо сообщить верховному старейшине Песня Теней об этой угрозе и, что ещё важнее, о нашем плане отправиться на Азерот." }, { 26.75, "Клянусь, мы придумаем, как защитить наш дом!" } } }, t = { d = 36.1, v = "skyborne-male", n = { x = 246 }, c = { x = { { 0.00, "*Талаанис Песня Теней внимательно слушает ваш рассказ о том, что произошло над святилищем Акира, и план Айессы покинуть остров Зефрис.*" }, { 11.92, "Мне надо обдумать это всё." }, { 14.07, "Что хорошо – мы избавились от Лортуны и обезглавили секту." }, { 18.66, "В наш дом ещё никто не вторгся, и, зная повелителей элементалей, могут пройти ещё многие годы и даже десятилетия, прежде чем Ал'акир наконец обратит на нас внимание." }, { 31.71, "Нам есть чего бояться, но также есть и повод для радости." } } } } },
    [93925] = { d = 48.9, v = "creature/furbolg", n = { x = 340 }, c = { x = { { 0.56, "Сила в тебе видна, но доверие приходит не сразу." }, { 4.93, "Кое-кто ещё смотрит на тебя косо." }, { 7.95, "Я помогу тебе заслужить их одобрение." }, { 14.34, "Фурболги Мёртвого Леса носят шнурки с нанизанными бусинами из редких пород, гладких камней и твёрдых даров горы." }, { 23.64, "Эти бусы отмечают положение в племени." }, { 26.92, "Принеси мне эти знаки в доказательство своих дел." }, { 34.07, "За каждые восемь бусин твоё имя будет весить для нас больше." }, { 42.36, "Ступай, и пусть лес увидит твою волю." } } } },
    [93926] = { d = 26.7, v = "skyborne-female", n = { x = 306 }, c = { x = { { 0.00, "Какой бы ни была причина нападения на башню, она не стоит жизней наших бойцов." }, { 5.75, "Отправляйся на юго-запад и найди её." }, { 8.40, "Скажи размещённым там миротворцам, чтобы возвращались в деревню." }, { 12.92, "Эта башня не стоит того, чтобы за неё умирать, – лучше собрать всех бойцов здесь для защиты мирных жителей." }, { 20.67, "Там командует миротворец Вааниэл; пусть направляется сюда как можно скорее." }, { 26.03, "Поторопись!" } } }, t = { d = 11.0, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "*Труп достаточно свежий – смерть настигла несчастного недавно.*" }, { 5.10, "*Судя по ожогам на коже, это дело рук сектантов, владеющих магией бури.*" } } } } },
    [93927] = { d = 10.7, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "*Когда вы осматриваете тело миротворца, из его рук выпадает окровавленная записка.*" }, { 6.61, "*Возможно, прочитав её, вы поймёте, что делать дальше.*" } } }, t = { d = 31.1, v = "skyborne-female", n = { x = 323 }, c = { x = { { 0.00, "Значит, все они мертвы." }, { 1.91, "Да разразит буря этих проклятых сектантов!" }, { 5.32, "Хотя тебе удалось избавиться от жреца и остановить их в башне, должна признать, что теперь меня ещё сильнее беспокоят твои слова об их махинациях со столпом." }, { 17.73, "У них был огромный запас ветрокамней, а значит, им требовалось колоссальное количество энергии." }, { 25.10, "Какова же их цель?" }, { 26.52, "Ритуал со столпом, нападение на деревню..." }, { 29.85, "Для чего всё это?" } } } } },
    [93928] = { d = 3.4, v = "child-female", n = { x = 27 }, c = { x = { { 0.00, "Мне нужно печенье, смекаешь?" }, { 2.76, "Хи-хи!" } } }, t = { d = 1.0, v = "dwarf-male", n = { x = 7 }, c = { x = { { 0.00, "Спасибо!" } } } } },
    [93948] = { d = 30.3, v = "skyborne-female", n = { x = 339 }, c = { x = { { 0.00, "Раз ты всё равно собираешься в Валанаар, доставь перстень, найденный в башне, Талаанису Песня Теней." }, { 7.35, "Он наверняка пожелает сохранить эту вещь у себя, и уж точно ему стоит узнать о судьбе племянника." }, { 14.57, "Талаанис – верховный старейшина на острове Зефрис." }, { 18.28, "Он справедливый лидер, любимый своим народом даже в эти трудные времена." }, { 23.71, "Мне больно думать о том, как старейшина воспримет эту весть." }, { 28.08, "Передай ему мои соболезнования." } } }, t = { d = 21.8, g = 1, v = "skyborne-male", n = { m = 235, f = 237 }, c = { m = { { 0.00, "Какая ужасная новость..." }, { 1.94, "Мой племянник мёртв." }, { 3.47, "Спасибо, что принёс этот перстень." }, { 6.10, "Нечасто такие молодые и способные шен'дорай заглядывают к нам с нагорий." }, { 11.65, "Если тебе нужна работа, поговори с Валеннией Штормовой Кулак, капитаном миротворцев в Валанааре." }, { 19.14, "Нам сейчас пригодится любая помощь." } }, f = { { 0.00, "Какая ужасная новость..." }, { 1.92, "Мой племянник мёртв." }, { 3.43, "Спасибо, что принесла этот перстень." }, { 6.25, "Нечасто такие молодые и способные шен'дорай заглядывают к нам с нагорий." }, { 11.74, "Если тебе нужна работа, поговори с Валеннией Штормовой Кулак, капитаном миротворцев в Валанааре." }, { 19.16, "Нам сейчас пригодится любая помощь." } } } } },
    [93949] = { d = 33.3, v = "skyborne-female", n = { x = 346 }, c = { x = { { 0.00, "Кругом эти насекомые." }, { 1.81, "В низинах сезон небопрыгов, и эти назойливые существа повсюду." }, { 6.86, "Один из магов Высшего ордена доложил, что на одном из убитых ими небопрыгов были некие чары." }, { 14.44, "Изучив их, мы обнаружили, что это какое-то подслушивающее заклинание." }, { 19.93, "Мы полагаем, что секта использует зачарованных насекомых для разведки." }, { 25.49, "Истреби их." }, { 26.43, "На вид зачарованные насекомые не отличаются от обычных, поэтому тебе придётся убить всех." } } }, t = { d = 10.8, v = "skyborne-female", n = { x = 122 }, c = { x = { { 0.00, "Я не сомневаюсь, что в Валанааре их ещё много, но с каждым зачарованным небопрыгом, которого мы растоптали, наш город становится немного безопаснее." } } } } },
    [93951] = { d = 30.6, v = "skyborne-female", n = { x = 327 }, c = { x = { { 0.00, "Гиппогрифы, поселившиеся к юго-западу от деревни, иногда нам досаждают, но зато теперь мы можем легко добывать их перья." }, { 9.33, "Многие небеснорождённые любят украшать волосы яркими перьями, а у гиппогрифов пуховые перья очень яркие и, что ещё важнее, мягкие как шёлк." }, { 19.99, "Если будешь там, собери как можно больше выпавших перьев в гнездовье гиппогрифов и рядом." }, { 26.95, "Но осторожнее: дикие гиппогрифы не любят гостей." } } }, t = { d = 21.8, g = 1, v = "skyborne-female", n = { m = 232, f = 234 }, c = { m = { { 0.00, "Украшения для волос могут показаться показным излишеством." }, { 4.51, "Однако даже в такие времена нужно позволять себе маленькие радости." }, { 9.86, "Если моё творение принесёт кому-то радость, то день пройдёт не зря." }, { 14.86, "Спасибо, что принёс мне эти перья – с твоей помощью я смогу порадовать жителей Зефриса." } }, f = { { 0.00, "Украшения для волос могут показаться показным излишеством." }, { 4.54, "Однако даже в такие времена нужно позволять себе маленькие радости." }, { 9.91, "Если моё творение принесёт кому-то радость, то день пройдёт не зря." }, { 14.93, "Спасибо, что принесла мне эти перья – с твоей помощью я смогу порадовать жителей Зефриса." } } } } },
    [93958] = { d = 18.2, v = "skyborne-female", n = { x = 174 }, c = { x = { { 0.00, "Войска Валеннии прорвались в святая святых врага." }, { 4.27, "Поначалу там шла ожесточённая борьба, но теперь стало... неожиданно тихо." }, { 10.38, "Пробейся к Валеннии и её бойцам... если там ещё кто-то остался." }, { 15.72, "А я буду прикрывать тебя здесь." } } }, t = { d = 2.3, v = "skyborne-female", n = { x = 0 }, c = { x = { { 0.00, "*Валенния серьёзно ранена.*" } } } } },
    [93963] = { d = 23.8, v = "creature/bolvar", n = { x = 251 }, c = { x = { { 0.00, "В каждом из наших городов – Штормграде, Стальгорне и Дарнасе – обитают разные народы с уникальной культурой." }, { 8.04, "Раз уж ты в гостях у Альянса здесь, на Азероте, выдели время для того, чтобы по очереди посетить каждую из наших столиц." }, { 17.25, "Для начала поговори с Рандалом Эмерсоном в южном вестибюле – он укажет тебе дорогу." } } }, t = { d = 33.8, g = 1, v = "creature/bolvar", n = { m = 366, f = 367 }, c = { m = { { 0.00, "А, ты вернулся!" }, { 1.14, "Надеюсь, странствия дали тебе представление о том, как велик и удивителен наш мир." }, { 7.17, "Понимаю, от всего этого голова идёт кругом, но если ты хочешь помочь своему народу, нужно быть готовым ко всему, что может ждать тебя на Азероте." }, { 18.03, "Пока твой орден обустраивается в Даларане, советую обратить внимание на земли вокруг Штормграда." }, { 25.20, "Западному краю, к примеру, всегда пригодятся сильные искатели приключений – если ты, конечно, не против помочь." } }, f = { { 0.00, "А, ты вернулась!" }, { 1.22, "Надеюсь, странствия дали тебе представление о том, как велик и удивителен наш мир." }, { 7.31, "Понимаю, от всего этого голова идёт кругом, но если ты хочешь помочь своему народу, нужно быть готовой ко всему, что может ждать тебя на Азероте." }, { 18.27, "Пока твой орден обустраивается в Даларане, советую обратить внимание на земли вокруг Штормграда." }, { 25.52, "Западному краю, к примеру, всегда пригодятся сильные искатели приключений – если ты, конечно, не против помочь." } } } } },
    [93971] = { d = 6.6, v = "skyborne-female#3773", n = { x = 0 }, c = { x = { { 0.00, "*Отчёт запечатан гербом Фархолда.*" }, { 2.75, "*Возможно, он заинтересует Кром'роша в Рог'маре.*" } } } },
    [93976] = { d = 28.0, v = "orc-female#124", n = { x = 296 }, c = { x = { { 0.00, "Пока мы с Гур'доком заняты делом, сделай-ка одолжение." }, { 4.10, "Мы изготовили особый клинок для одной союзницы... пожалуй, \"союзницы\" – это сильно сказано... для знакомой, которая сейчас ждёт в доках." }, { 14.24, "Это довольно популярная особа со связями по всем королевствам и за их пределами." }, { 20.15, "Вот, возьми." }, { 21.09, "Когда будешь отдавать, не забудь сказать, что это от меня." }, { 25.53, "И скажи, что теперь мы с ней квиты." } } } },
    [94003] = { d = 36.5, v = "skyborne-female#3773", n = { x = 365 }, c = { x = { { 0.00, "Я последняя из Небовержцев острова Зефрис." }, { 3.42, "Всех остальных убили ал'акетские фанатики." }, { 6.85, "И единственное, что давит на меня тяжелее, чем чувство вины, это стыд: реликвия моей семьи, щит Бастион Небовержца, попал в руки сектанта по имени Заал Щит Бури." }, { 19.96, "Наше семейное предание гласит, что достойный обладатель этого щита непобедим." }, { 26.29, "Заал недостоин, я в этом уверена." }, { 29.06, "Найди его в святилище Акира и отбери мой щит." }, { 32.77, "Сделай это, и я обучу тебя защите Небовержцев." } } }, t = { d = 30.3, g = 1, v = "skyborne-female#3773", n = { m = 278, f = 280 }, c = { m = { { 0.00, "Ты сделал то, чего не смогла я, и вернул честь моей семье." }, { 5.02, "За это я одарю тебя тем, чего на Зефрисе удостаиваются немногие: я открою тебе секреты защиты Небовержца." }, { 14.12, "Кроме того, тебе понадобится щит, чтобы применить на деле то, чему я тебя научу." }, { 21.14, "Прошу, возьми этот." }, { 22.92, "Теперь, когда Бастион небовержца вернулся ко мне, он мне ни к чему." }, { 28.63, "Бану'Адораа, друг мой." } }, f = { { 0.00, "Ты сделала то, чего не смогла я, и вернула честь моей семье." }, { 5.13, "За это я одарю тебя тем, чего на Зефрисе удостаиваются немногие: я открою тебе секреты защиты Небовержца." }, { 14.16, "Кроме того, тебе понадобится щит, чтобы применить на деле то, чему я тебя научу." }, { 21.13, "Прошу, возьми этот." }, { 22.89, "Теперь, когда Бастион небовержца вернулся ко мне, он мне ни к чему." }, { 28.56, "Бану'Адораа, друг мой." } } } } },
    [94004] = { d = 16.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ: эликсир силы огра, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 12.03, "Снизу указано, что этот заказ можно передавать другим." } } } },
    [94006] = { d = 32.2, g = 1, v = "skyborne-male", n = { m = 337, f = 338 }, c = { m = { { 0.00, "Привет." }, { 0.63, "Ты достаточно продвинулся по пути друида, и я думаю, что тебе пора встретиться с одним из великих духов Зефриса." }, { 9.37, "Урс'ендрис – благородный мудрый дух, научивший много поколений друидов принимать облик медверы." }, { 16.79, "К несчастью, его владения начали рассыпаться и рушиться в небо, как и многие другие области Зефриса." }, { 24.62, "Ищи его на северо-востоке отсюда у водопада, в тени святилища Акира." }, { 30.08, "Он скажет, что делать дальше." } }, f = { { 0.00, "Привет." }, { 0.62, "Ты достаточно продвинулась по пути друида, и я думаю, что тебе пора встретиться с одним из великих духов Зефриса." }, { 9.33, "Урс'ендрис – благородный мудрый дух, научивший много поколений друидов принимать облик медверы." }, { 16.66, "К несчастью, его владения начали рассыпаться и рушиться в небо, как и многие другие области Зефриса." }, { 24.40, "Ищи его на северо-востоке отсюда у водопада, в тени святилища Акира." }, { 29.79, "Он скажет, что делать дальше." } } }, t = { d = 9.1, v = "creature/furbolg", n = { x = 46 }, c = { x = { { 0.56, "Итак, ты хочешь пойти по пути когтя, дитя?" }, { 4.84, "Давай поговорим." } } } } },
    [94007] = { d = 18.4, g = 1, v = "skyborne-female", n = { m = 205, f = 206 }, c = { m = { { 0.00, "Теперь, когда ты достаточно освоился на нагорьях, думаю, самое время тебе обзавестись своим собственным питомцем." }, { 8.47, "Ступай в порт Валанаар, что к юго-востоку отсюда, и там поговори с Кве'ланой Быстрым Порывом." }, { 15.34, "Он обучит тебя искусству укрощения зверей." } }, f = { { 0.00, "Теперь, когда ты достаточно освоилась на нагорьях, думаю, самое время тебе обзавестись своим собственным питомцем." }, { 8.51, "Ступай в порт Валанаар, что к юго-востоку отсюда, и там поговори с Кве'ланой Быстрым Порывом." }, { 15.36, "Он обучит тебя искусству укрощения зверей." } } }, t = { d = 3.8, v = "skyborne-male", n = { x = 33 }, c = { x = { { 0.00, "Я очень рада твоему приходу." }, { 2.65, "Давай начнём." } } } } },
    [94013] = { d = 24.6, g = 1, v = "skyborne-male", n = { m = 261, f = 264 }, c = { m = { { 0.00, "Ты вернулся с победой, приручив двух зверей, и готов к последнему шагу." }, { 5.61, "Ветра Зефриса шепчут о новых сложных испытаниях." }, { 9.51, "Возьми хлыст приручения и отправляйся в Ветроягодные низины." }, { 14.20, "Там покажи своё мастерство, приручив лисвена-вожака." }, { 18.31, "После этого урока ты будешь готов изучать самые сокровенные секреты охотников." } }, f = { { 0.00, "Ты вернулась с победой, приручив двух зверей, и готова к последнему шагу." }, { 5.74, "Ветра Зефриса шепчут о новых сложных испытаниях." }, { 9.63, "Возьми хлыст приручения и отправляйся в Ветроягодные низины." }, { 14.31, "Там покажи своё мастерство, приручив лисвена-вожака." }, { 18.42, "После этого урока ты будешь готова изучать самые сокровенные секреты охотников." } } }, t = { d = 16.1, g = 1, v = "skyborne-male", n = { m = 153, f = 154 }, c = { m = { { 0.00, "Превосходно!" }, { 1.08, "Ты быстро учишься." }, { 2.71, "Теперь, когда ты освоил азы, я расскажу тебе, как установить крепкую связь с любым зверем." }, { 10.52, "Пусть это знание поможет тебе." }, { 13.22, "Стань охотником, достойным Зефриса." } }, f = { { 0.00, "Превосходно!" }, { 1.03, "Ты быстро учишься." }, { 2.57, "Теперь, когда ты освоила азы, я расскажу тебе, как установить крепкую связь с любым зверем." }, { 10.07, "Пусть это знание поможет тебе." }, { 12.65, "Стань охотницей, достойной Зефриса." } } } } },
    [94050] = { d = 15.0, g = 1, v = "skyborne-male", n = { m = 151, f = 151 }, c = { m = { { 0.00, "У тебя достаточно сил, чтобы приручить зверя, теперь надо научиться его дрессировать." }, { 6.44, "Поговори с моей сестрой Кель'дорой – она расскажет тебе, как обучать питомцев." }, { 12.33, "Ступай с ветром, юный герой." } }, f = { { 0.00, "У тебя достаточно сил, чтобы приручить зверя, теперь надо научиться его дрессировать." }, { 6.66, "Поговори с моей сестрой Кель'дорой – она расскажет тебе, как обучать питомцев." }, { 12.76, "Ступай с ветром, юная героиня." } } }, t = { d = 24.5, g = 1, v = "skyborne-female", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Ты молодой охотник?" }, { 1.54, "Да, я могу научить тебя дрессировать питомца и охотиться вместе с ним." }, { 6.98, "Ты сможешь обучать его новым способностям, кормить и даже воскрешать, если он падёт в бою." }, { 14.02, "Помни, мы должны уважать равновесие и любить природу, восхищаясь всеми её проявлениями." }, { 20.79, "Теперь иди." }, { 21.77, "Мы ещё поговорим обо всём этом позже." } }, f = { { 0.00, "Ты молодая охотница?" }, { 1.60, "Да, я могу научить тебя дрессировать питомца и охотиться вместе с ним." }, { 7.03, "Ты сможешь обучать его новым способностям, кормить и даже воскрешать, если он падёт в бою." }, { 14.05, "Помни, мы должны уважать равновесие и любить природу, восхищаясь всеми её проявлениями." }, { 20.80, "Теперь иди." }, { 21.78, "Мы ещё поговорим обо всём этом позже." } } } } },
    [94212] = { d = 16.5, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ: эликсир мудрости, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 11.93, "Снизу указано, что этот заказ можно передавать другим." } } } },
    [94213] = { d = 17.0, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ: малое зелье маны, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 12.35, "Снизу указано, что этот заказ можно передавать другим." } } } },
