    [94360] = { d = 15.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ: сума душ, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 11.27, "Снизу указано, что этот заказ можно передавать другим." } } } },
    [94369] = { d = 30.0, v = "skyborne-male", n = { x = 337 }, c = { x = { { 0.00, "Ансирем рассказал мне про повелителей элементалей, и я боюсь, что у нас есть все основания бояться Ал'акира, раз обереги, которые скрывали Зефрис, больше не действуют." }, { 12.06, "И если Владыка Ветра нападёт на нас, в его владениях мы будем совершенно беззащитны." }, { 18.22, "Надо сообщить верховному старейшине Песня Теней об этой угрозе и, что ещё важнее, о нашем плане отправиться на Азерот." }, { 26.97, "Клянусь, мы придумаем, как защитить наш дом!" } } }, t = { d = 36.1, v = "skyborne-male", n = { x = 246 }, c = { x = { { 0.00, "*Талаанис Песня Теней внимательно слушает ваш рассказ о том, что произошло над святилищем Акира, и план Элаадрина покинуть остров Зефрис.*" }, { 11.76, "Мне надо обдумать это всё." }, { 13.93, "Что хорошо – мы избавились от Лортуны и обезглавили секту." }, { 18.55, "В наш дом ещё никто не вторгся, и, зная повелителей элементалей, могут пройти ещё многие годы и даже десятилетия, прежде чем Ал'акир наконец обратит на нас внимание." }, { 31.68, "Нам есть чего бояться, но также есть и повод для радости." } } } } },
    [94373] = { d = 39.0, g = 1, v = "dwarf-male", n = { m = 427, f = 430 }, c = { m = { { 0.00, "Время пришло, юный шаман." }, { 1.95, "Ты стал крепким и твёрдым, как камень у нас под ногами." }, { 5.79, "То, что ты выбрал путь шамана, показывает, что в тебе есть мудрость гор, хотя ты ещё и не доказал свою силу." }, { 13.46, "Я чувствую в тебе непоколебимость камня, которая позволит идти путём Земли." }, { 18.93, "Но чтобы заслужить её благосклонность, нужно сперва встретиться с ней лицом к лицу." }, { 24.91, "В пещере к югу отсюда живут тролли из племени Мерзлогривов." }, { 29.27, "Принеси мне две подвески, сделанные из когтей медведей-ледокогтей, которые они носят." }, { 35.45, "Тогда мы поговорим о твоём будущем." } }, f = { { 0.00, "Время пришло, юный шаман." }, { 2.00, "Ты стала крепкой и твёрдой, как камень у нас под ногами." }, { 6.06, "То, что ты выбрала путь шамана, показывает, что в тебе есть мудрость гор, хотя ты ещё и не доказала свою силу." }, { 14.06, "Я чувствую в тебе непоколебимость камня, которая позволит идти путём Земли." }, { 19.66, "Но чтобы заслужить её благосклонность, нужно сперва встретиться с ней лицом к лицу." }, { 25.79, "В пещере к югу отсюда живут тролли из племени Мерзлогривов." }, { 30.26, "Принеси мне две подвески, сделанные из когтей медведей-ледокогтей, которые они носят." }, { 36.59, "Тогда мы поговорим о твоём будущем." } } }, t = { d = 29.7, g = 1, v = "dwarf-male", n = { m = 306, f = 310 }, c = { m = { { 0.00, "Прекрасно, друг мой." }, { 1.55, "Ты отлично себя показал." }, { 3.52, "Земля – фундамент всего." }, { 5.50, "Это сила, выносливость, терпение." }, { 8.18, "Она защитит тебя, но только если ты будешь относиться к ней с уважением." }, { 13.89, "Даже камень может сдвинуться, если обращаться с ним неосторожно." }, { 18.96, "Изучи её путь, и ты станешь мудрее большинства." }, { 22.63, "Никогда не забывай её секретов." }, { 25.10, "Я приготовлю тебе сапту." }, { 27.07, "Прими её и встань на истинный путь." } }, f = { { 0.00, "Прекрасно, подруга моя." }, { 1.88, "Ты отлично себя показала." }, { 3.90, "Земля – фундамент всего." }, { 5.85, "Это сила, выносливость, терпение." }, { 8.50, "Она защитит тебя, но только если ты будешь относиться к ней с уважением." }, { 14.15, "Даже камень может сдвинуться, если обращаться с ним неосторожно." }, { 19.17, "Изучи её путь, и ты станешь мудрее большинства." }, { 22.79, "Никогда не забывай её секретов." }, { 25.23, "Я приготовлю тебе сапту." }, { 27.18, "Прими её и встань на истинный путь." } } } } },
    [94374] = { d = 28.1, v = "dwarf-male", n = { x = 306 }, c = { x = { { 0.00, "Сапта – магический отвар, который связывает наши души со стихиями." }, { 4.87, "Мало кому из шаманов известен рецепт, и эта штука точно не для слабых духом." }, { 10.51, "Выпьешь её – и сможешь узреть то, что от других сокрыто." }, { 14.53, "И знай, что пить её можно только в священном месте." }, { 18.17, "Ступай на север к камню духов, что притулился в конце тайной тропы в горах." }, { 23.68, "Там выпей зелье – и увидишь то, что земля решит тебе показать." } } }, t = { d = 35.9, v = "elemental-earth", n = { x = 290 }, c = { x = { { 0.00, "А..." }, { 0.43, "Земля приветствует тебя – даже в этих морозных землях." }, { 5.78, "Став с ней единым целым – телесно и духовно – ты будешь идти вперёд, зная, что горы – это твоя сила, поля – твоё терпение, а весь мир – твоя сущность." }, { 20.12, "Чтобы пройти это испытание, встань пред лицом Земли." }, { 25.21, "Другие стихии не столь неподвижны." }, { 28.49, "Они борются и ревут." }, { 30.56, "Изучи их двойственную природу здесь, среди снега и камня." } } } } },
    [94375] = { d = 40.2, g = 1, v = "elemental-earth", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Возьми этот необработанный кварц и отнеси его Тео Молотошторму в доказательство того, что мы с тобой встречались." }, { 10.70, "Он создаст тотем для тебя, и этот камушек будет сердцем тотема." }, { 16.87, "Он невелик, но со временем ты поймёшь, что размер не имеет значения." }, { 23.20, "Иногда малое оказывается долговечнее большого." }, { 27.65, "Будь терпелив." }, { 29.02, "Оставайся сильным." }, { 30.82, "И ищи мудрости." }, { 32.36, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } }, f = { { 0.00, "Возьми этот необработанный кварц и отнеси его Тео Молотошторму в доказательство того, что мы с тобой встречались." }, { 10.49, "Он создаст тотем для тебя, и этот камушек будет сердцем тотема." }, { 16.53, "Он невелик, но со временем ты поймёшь, что размер не имеет значения." }, { 22.74, "Иногда малое оказывается долговечнее большого." }, { 27.10, "Будь терпелива." }, { 28.53, "Оставайся сильной." }, { 30.29, "И ищи мудрости." }, { 31.80, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } } }, t = { d = 27.7, g = 1, v = "dwarf-male", n = { m = 307, f = 308 }, c = { m = { { 0.00, "Молодчина!" }, { 0.79, "Помни, что тотемы – не просто символ твоего положения среди шаманов." }, { 5.87, "Это наши инструменты; средоточия заклинаний, связанных с камнем, землёй и другими стихиями." }, { 12.53, "По мере того как ты будешь набираться ума, тебе станут открываться новые возможности горы." }, { 19.25, "Наставники сами узнают, когда ты станешь готов к этому." }, { 23.41, "Пока же возьми этот тотем и дай земле говорить через тебя." } }, f = { { 0.00, "Молодчина!" }, { 0.79, "Помни, что тотемы – не просто символ твоего положения среди шаманов." }, { 5.85, "Это наши инструменты; средоточия заклинаний, связанных с камнем, землёй и другими стихиями." }, { 12.50, "По мере того как ты будешь набираться ума, тебе станут открываться новые возможности горы." }, { 19.21, "Наставники сами узнают, когда ты станешь готова к этому." }, { 23.42, "Пока же возьми этот тотем и дай земле говорить через тебя." } } } } },
    [94411] = { d = 29.3, v = "skyborne-female", n = { x = 327 }, c = { x = { { 0.00, "Хочу тебя предупредить: у каменных монолитов на севере деревни были замечены представители Высшего ордена." }, { 8.05, "Мы не раз говорили им держаться подальше от наших священных мест, но их дерзость не знает границ." }, { 15.22, "Докажи свою решимость: отправляйся к монолитам и разгони незваных гостей." }, { 20.77, "Очень не хотелось бы доводить до кровопролития, но если придётся, сделай, что должно." }, { 27.06, "После этого возвращайся ко мне." } } }, t = { d = 24.5, v = "skyborne-female", n = { x = 260 }, c = { x = { { 0.00, "Столкновения между братьями и сёстрами лишь ослабляют шен'дорай, но иногда нужно действовать решительно, чтобы предотвратить ещё большую беду." }, { 11.20, "Магов Высшего ордена совсем не волнуют последствия их вмешательства." }, { 16.66, "Силы, хранящие наш остров, хрупки и уязвимы – один необдуманный поступок, и наш дом будет уничтожен." } } } } },
    [94413] = { d = 32.4, v = "skyborne-male", n = { x = 359 }, c = { x = { { 0.00, "Появление силовых линий на поверхности Зефриса имело большое значение для нашего ордена." }, { 6.63, "Энергии, пронизывающие это место, стали для нас более осязаемыми, что значительно углубило наши знания о магии." }, { 14.93, "Ваятели ветра, однако, считают силовые линии шрамами на земле, которые нужно залечить." }, { 21.50, "Для нашего ордена это оскорбление, и мы не намерены такое терпеть." }, { 26.45, "Отправляйся к силовой линии в лесу к юго-западу и выдвори оттуда Ваятелей ветра." } } }, t = { d = 17.4, v = "skyborne-male", n = { x = 194 }, c = { x = { { 0.00, "Иногда сложно разграничить слепой фанатизм культа Ал'акет и упрямство Ваятелей ветра, отвергающих перемены." }, { 7.87, "Если бы они и правда верили, что ветра направят нас, то чувствовали бы, куда дуют эти ветра, и следовали бы за ними, а не против них." } } } } },
    [94414] = { d = 25.1, g = 1, v = "skyborne-male", n = { m = 280, f = 281 }, c = { m = { { 0.00, "Приветствую." }, { 0.93, "Я частенько прихожу сюда, чтобы посмотреть на древний опорный столп." }, { 6.00, "Это дар от духов ветра, который питает наш остров." }, { 9.80, "Но в последнее время их магия стала нестабильной и непредсказуемой." }, { 14.73, "Хотя повреждений на столпах нет, и они всё так же великолепны." }, { 19.27, "Если хочешь, могу поделиться с тобой даром, чтобы ты полюбовался вместе со мной." } }, f = { { 0.00, "Приветствую." }, { 0.92, "Я частенько прихожу сюда, чтобы посмотреть на древний опорный столп." }, { 5.93, "Это дар от духов ветра, который питает наш остров." }, { 9.68, "Но в последнее время их магия стала нестабильной и непредсказуемой." }, { 14.55, "Хотя повреждений на столпах нет, и они всё так же великолепны." }, { 19.03, "Если хочешь, могу поделиться с тобой даром, чтобы ты полюбовалась вместе со мной." } } }, t = { d = 9.1, g = 1, v = "skyborne-male", n = { m = 98, f = 99 }, c = { m = { { 0.00, "Благодарю, что разделил со мной этот момент." }, { 3.33, "Я продолжу наблюдать за рощей и размышлять о том, что стало с нашими землями." } }, f = { { 0.00, "Благодарю, что разделила со мной этот момент." }, { 3.43, "Я продолжу наблюдать за рощей и размышлять о том, что стало с нашими землями." } } } } },
    [94427] = { d = 33.1, g = 1, v = "scourge-female", n = { m = 289, f = 289 }, c = { m = { { 0.00, "Одно из главных качеств паладина – благочестие." }, { 4.47, "Это значит, что ты должен творить добро, не думая о собственной выгоде." }, { 11.21, "Каждый из нас, оказавшихся здесь, перенёс тяготы, после которых легко забыть, что при жизни мы служили Свету." }, { 21.32, "Отправляйся в Подгород и найди Таниса Элдервуда в Торговом квартале." }, { 27.72, "Ему нужна помощь тех, кто ещё помнит, что такое милосердие." } }, f = { { 0.00, "Одно из главных качеств паладина – благочестие." }, { 4.30, "Это значит, что ты должна творить добро, не думая о собственной выгоде." }, { 10.80, "Каждый из нас, оказавшихся здесь, перенёс тяготы, после которых легко забыть, что при жизни мы служили Свету." }, { 20.55, "Отправляйся в Подгород и найди Таниса Элдервуда в Торговом квартале." }, { 26.72, "Ему нужна помощь тех, кто ещё помнит, что такое милосердие." } } }, t = { d = 13.4, v = "scourge-male#83", n = { x = 125 }, c = { x = { { 0.00, "Ты... ты что, паладин?" }, { 1.76, "Не бей меня, пожалуйста." }, { 3.75, "Я... я знаю, что здесь нельзя попрошайничать." }, { 7.34, "Мне не нужны проблемы с тобой и твоим орденом." }, { 11.16, "Прошу, оставь меня в покое!" } } } } },
    [94434] = { d = 39.4, g = 1, v = "scourge-male#83", n = { m = 400, f = 402 }, c = { m = { { 0.00, "Подожди, ты хочешь... помочь?" }, { 2.32, "С чего бы паладину помогать какому-то попрошайке вроде меня?" }, { 7.12, "Ну, кое-что ты можешь для меня сделать." }, { 10.21, "Моя жена... как бы сказать... еле держится." }, { 13.67, "В том смысле, что она буквально разваливается на части." }, { 17.96, "Аптекари могли бы подшить её так, что она будет как новенькая, но все они заняты поручениями Тёмной Госпожи, и ни у кого нет свободного времени." }, { 29.09, "Не мог бы ты принести мне немного чистой ткани?" }, { 32.76, "Тогда я смогу хотя бы обмотать её, чтобы не развалилась совсем, пока мы ждём аптекарей." } }, f = { { 0.00, "Подожди, ты хочешь... помочь?" }, { 2.30, "С чего бы паладину помогать какому-то попрошайке вроде меня?" }, { 7.05, "Ну, кое-что ты можешь для меня сделать." }, { 10.12, "Моя жена... как бы сказать... еле держится." }, { 13.54, "В том смысле, что она буквально разваливается на части." }, { 17.80, "Аптекари могли бы подшить её так, что она будет как новенькая, но все они заняты поручениями Тёмной Госпожи, и ни у кого нет свободного времени." }, { 28.82, "Не могла бы ты принести мне немного чистой ткани?" }, { 32.66, "Тогда я смогу хотя бы обмотать её, чтобы не развалилась совсем, пока мы ждём аптекарей." } } }, t = { d = 4.2, g = 1, v = "scourge-male#83", n = { m = 22, f = 23 }, c = { m = { { 0.00, "Спасибо тебе." }, { 1.64, "Ты очень добр, герой." } }, f = { { 0.00, "Спасибо тебе." }, { 1.58, "Ты очень добра, героиня." } } } } },
    [94435] = { d = 15.9, g = 1, v = "scourge-male#83", n = { m = 147, f = 148 }, c = { m = { { 0.00, "Не знаю, почему ты решил потратить своё время на помощь мне, но я тебе благодарна." }, { 6.77, "Если кто-то тебя ко мне отправил, ему тоже передай спасибо." }, { 11.83, "Танис Элдервуд всегда будет твоей подругой, герой." } }, f = { { 0.00, "Не знаю, почему ты решила потратить своё время на помощь мне, но я тебе благодарна." }, { 6.78, "Если кто-то тебя ко мне отправил, ему тоже передай спасибо." }, { 11.80, "Танис Элдервуд всегда будет твоей подругой, героиня." } } }, t = { d = 39.5, v = "scourge-female", n = { x = 348 }, c = { x = { { 0.00, "Ты молодец." }, { 1.09, "Эта задача была нетрудной, но даже такие небольшие добрые дела укрепляют нашу связь со Светом." }, { 10.09, "Тёмная Госпожа и многие из её слуг не доверяют нам." }, { 14.71, "Некоторые даже строят козни против нас, но на их страх и неверие мы ответим отвагой и праведностью." }, { 23.88, "Мы покажем, что мы тоже Отрёкшиеся, и внесём свой вклад, большой или малый, в будущее процветание нашего народа." }, { 34.14, "Возьми этот знак." }, { 35.82, "Он пригодится тебе в следующем испытании." } } } } },
    [94436] = { d = 47.9, v = "scourge-female", n = { x = 441 }, c = { x = { { 0.00, "Пришла пора показать, как ты умеешь обращаться с одним из величайших даров Света." }, { 7.32, "Предмет, который я сейчас тебе дала, называется знаком Жизни." }, { 12.94, "Обращайся с ним осторожно: тебе может быть неприятно держать в руках талисман, наполненный силой Света." }, { 22.19, "Он враждебен той магии, что создала нас, но мы всё ещё можем следовать пути Света и использовать его силу." }, { 31.60, "Боль лишь напоминает нам об этом." }, { 34.49, "Спускайся вниз и найди стража смерти Билмута." }, { 38.59, "Он недавно пришёл к нам с просьбой о помощи." }, { 42.45, "Покажи ему и всем Отрёкшимся, на что способен настоящий паладин." } } }, t = { d = 20.3, v = "scourge-male", n = { x = 157 }, c = { x = { { 0.00, "Так ты мне поможешь?" }, { 2.01, "Отлично." }, { 2.93, "Я, конечно, не горжусь тем, что пришлось... ну... обращаться к паладинам." }, { 10.15, "Но жрецы от меня отмахнулись, так что ты, похоже, единственная надежда моего друга." }, { 18.57, "Прошу, помоги мне." } } } } },
    [94438] = { d = 38.6, v = "scourge-male", n = { x = 405 }, c = { x = { { 0.00, "Нас с Фалганом отправили следить за Алым орденом в Долину ядовитых пауков." }, { 5.70, "Подкравшись к одному из их лагерей, мы подслушали, что орден готовится напасть на Брилл, но пока мы думали, что делать дальше, я случайно наступил на сухую ветку." }, { 17.94, "Треск был на всю округу." }, { 19.73, "Фалган закричал мне \"Беги!\", и я побежал." }, { 22.89, "Пролетел полпути до Брилла, прежде чем понял, что я один." }, { 27.29, "Должно быть, этот отважный балбес остался позади, чтобы задержать врагов и дать мне шанс." }, { 34.09, "Пожалуйста, найди моего друга и помоги ему, если сможешь." } } }, t = { d = 32.0, v = "scourge-male", n = { x = 263 }, c = { x = { { 0.00, "Я... спасён?" }, { 1.13, "Да ещё и паладином?" }, { 2.95, "Вижу, у тебя есть знак Жизни." }, { 5.81, "В последний раз я такой видел... кажется, ещё до войны." }, { 11.10, "Лордерон тогда был совсем другим." }, { 14.39, "Ты хочешь помочь?" }, { 16.13, "Нас с Билмутом отправили сюда разведать планы Алого ордена, и мы узнали, что орден готовится к нападению." }, { 26.27, "Если хочешь помочь Отрёкшимся, ты можешь сделать ещё кое-что." } } } } },
    [94440] = { d = 29.6, v = "scourge-male", n = { x = 270 }, c = { x = { { 0.00, "Рыцари Алого ордена часто носят с собой сумки с приказами." }, { 5.36, "Мы знаем, что они собираются напасть, но получив их приказы, мы сможем предупредить остальных стражей смерти и подготовить засаду." }, { 16.88, "Ты не робкого десятка, паладин." }, { 19.68, "Убей этих алых извергов и добудь приказы, а затем отнеси их стражу смерти Билмуту." }, { 27.20, "Он знает, что делать дальше." } } }, t = { d = 25.6, g = 1, v = "scourge-male", n = { m = 228, f = 231 }, c = { m = { { 0.00, "Спасибо, что спас моего друга." }, { 2.75, "Я отнесу эти планы командиру, и мы устроим рыцарям такой тёплый приём, который они нескоро забудут." }, { 11.75, "Я знаю, что многие из нас не доверяют вам, паладинам, но теперь мне ясно, что вы – истинные Отрёкшиеся." }, { 20.74, "Я не забуду твоей помощи и расскажу всем, что ты сделал." } }, f = { { 0.00, "Спасибо, что спасла моего друга." }, { 2.92, "Я отнесу эти планы командиру, и мы устроим рыцарям такой тёплый приём, который они нескоро забудут." }, { 11.69, "Я знаю, что многие из нас не доверяют вам, паладинам, но теперь мне ясно, что вы – истинные Отрёкшиеся." }, { 20.46, "Я не забуду твоей помощи и расскажу всем, что ты сделала." } } } } },
    [94441] = { d = 24.1, v = "scourge-male", n = { x = 218 }, c = { x = { { 0.00, "Пожалуйста, передай мою благодарность Даните Морр и скажи ей, что все стражи смерти узнают о том, как нам помогли паладины из крепости Бандариона." }, { 13.19, "Я вижу в тебе задатки великого паладина и горжусь, что среди Отрёкшихся есть такие, как ты." }, { 21.44, "Да хранит тебя Тёмная Госпожа." } } }, t = { d = 40.6, g = 1, v = "scourge-female", n = { m = 365, f = 367 }, c = { m = { { 0.00, "Только те паладины, что готовы овладеть одним из величайших благословений Света, могут воспользоваться силой знака Жизни." }, { 10.58, "Я горжусь тем, что ты с нами, и наделяю тебя даром искупления." }, { 15.99, "Он позволит тебе возвращать к жизни павших товарищей." }, { 20.69, "Используй его с умом." }, { 22.65, "Ты помог не только Отрёкшимся, но и паладинам из Дозора Тира." }, { 27.90, "Любые дела, которые помогут нам завоевать доверие остальных Отрёкшихся, стоят затраченных усилий." }, { 36.36, "Да пребудет с тобой Свет." } }, f = { { 0.00, "Только те паладины, что готовы овладеть одним из величайших благословений Света, могут воспользоваться силой знака Жизни." }, { 11.13, "Я горжусь тем, что ты с нами, и наделяю тебя даром искупления." }, { 16.82, "Он позволит тебе возвращать к жизни павших товарищей." }, { 21.76, "Используй его с умом." }, { 23.82, "Ты помогла не только Отрёкшимся, но и паладинам из Дозора Тира." }, { 29.51, "Любые дела, которые помогут нам завоевать доверие остальных Отрёкшихся, стоят затраченных усилий." }, { 38.41, "Да пребудет с тобой Свет." } } } } },
    [94449] = { d = 27.8, g = 1, v = "dwarf-male", n = { m = 287, f = 289 }, c = { m = { { 0.00, "Прошло немало времени после твоего прошлого испытания." }, { 4.40, "Терпения тебе не занимать, это да, но теперь пришёл черёд обучиться сеять хаос... и разрушения." }, { 11.86, "Зов огня громогласен и он обращается к тем, кто готов заплатить нужную цену." }, { 17.83, "Найди Брюкса Дитя Искр в горах далеко на востоке." }, { 21.80, "Он живёт в пещере над фортом у Южных врат." }, { 25.07, "Он поймёт, действительно ли ты готов." } }, f = { { 0.00, "Прошло немало времени после твоего прошлого испытания." }, { 4.34, "Терпения тебе не занимать, это да, но теперь пришёл черёд обучиться сеять хаос... и разрушения." }, { 11.69, "Зов огня громогласен и он обращается к тем, кто готов заплатить нужную цену." }, { 17.58, "Найди Брюкса Дитя Искр в горах далеко на востоке." }, { 21.50, "Он живёт в пещере над фортом у Южных врат." }, { 24.72, "Он поймёт, действительно ли ты готова." } } }, npc = { [258113] = { d = 28.2, g = 1, v = "dwarf-female", n = { m = 287, f = 288 }, c = { m = { { 0.00, "Прошло немало времени после твоего прошлого испытания." }, { 4.42, "Терпения тебе не занимать, это да, но теперь пришёл черёд обучиться сеять хаос... и разрушения." }, { 11.89, "Зов огня громогласен и он обращается к тем, кто готов заплатить нужную цену." }, { 17.88, "Найди Брюкса Дитя Искр в горах далеко на востоке." }, { 21.87, "Он живёт в пещере над фортом у Южных врат." }, { 25.14, "Он поймёт, действительно ли ты готов." } }, f = { { 0.00, "Прошло немало времени после твоего прошлого испытания." }, { 4.42, "Терпения тебе не занимать, это да, но теперь пришёл черёд обучиться сеять хаос... и разрушения." }, { 11.89, "Зов огня громогласен и он обращается к тем, кто готов заплатить нужную цену." }, { 17.88, "Найди Брюкса Дитя Искр в горах далеко на востоке." }, { 21.87, "Он живёт в пещере над фортом у Южных врат." }, { 24.99, "Он поймёт, действительно ли ты готова." } } } } }, t = { d = 30.5, g = 1, v = "dwarf-male", n = { m = 283, f = 285 }, c = { m = { { 0.00, "Хм..." }, { 0.45, "Значит, ты от той старейшины?" }, { 2.86, "Что ж, слово шамана кремень, так что не буду спорить." }, { 7.30, "Выходит, ты готов испить новую сапту." }, { 10.53, "Сапту огня." }, { 11.59, "Да, я уже вижу в твоих глазах пылающую жажду познания!" }, { 16.25, "Ты вкусил власти и теперь хочешь ещё." }, { 19.41, "Но не торопись." }, { 20.69, "Помни, чему тебя научил камень." }, { 23.48, "Огнём легко овладеть, но его трудно унять." }, { 27.09, "Важно знать, когда вовремя остановиться." } }, f = { { 0.00, "Хм..." }, { 0.45, "Значит, ты от той старейшины?" }, { 2.86, "Что ж, слово шамана кремень, так что не буду спорить." }, { 7.30, "Выходит, ты готова испить новую сапту." }, { 10.61, "Сапту огня." }, { 11.67, "Да, я уже вижу в твоих глазах пылающую жажду познания!" }, { 16.33, "Ты вкусила власти и теперь хочешь ещё." }, { 19.57, "Но не торопись." }, { 20.85, "Помни, чему тебя научил камень." }, { 23.64, "Огнём легко овладеть, но его трудно унять." }, { 27.25, "Важно знать, когда вовремя остановиться." } } } } },
    [94465] = { d = 30.3, g = 1, v = "dwarf-male", n = { m = 324, f = 325 }, c = { m = { { 0.00, "Да уж, у тебя есть сила носить тотем огня – но это ещё не значит, что ты готов." }, { 5.95, "За долиной Королей, среди утёсов Лок Модана лежит тайная тропа к одной из наших священных вершин." }, { 13.32, "Там Бралдир Пеплоплащ стережёт святилище Дремлющего Пламени." }, { 17.78, "Отнеси ему этот факел, и он поймёт, зачем ты пришёл." }, { 21.71, "Если вернёшься с факелом, зажжённым от жаровни святилища, я обучу тебя всему, что нужно для владения тотемом огня." } }, f = { { 0.00, "Да уж, у тебя есть сила носить тотем огня – но это ещё не значит, что ты готова." }, { 6.04, "За долиной Королей, среди утёсов Лок Модана лежит тайная тропа к одной из наших священных вершин." }, { 13.44, "Там Бралдир Пеплоплащ стережёт святилище Дремлющего Пламени." }, { 17.91, "Отнеси ему этот факел, и он поймёт, зачем ты пришла." }, { 21.92, "Если вернёшься с факелом, зажжённым от жаровни святилища, я обучу тебя всему, что нужно для владения тотемом огня." } } }, t = { d = 26.7, v = "dwarf-male", n = { x = 296 }, c = { x = { { 0.00, "А, прости." }, { 0.80, "Не заметил у тебя факел." }, { 2.66, "Рад, что мы с тобой наконец-то встретились." }, { 5.79, "Многие странники забираются сюда, наслушавшись историй о богатствах и чудовищах, а находят только безмолвный камень." }, { 14.36, "Но нас с тобой не обманешь, так ведь?" }, { 17.02, "Это святилище скрывает истины, о которых Альянс и не догадывается." }, { 21.95, "Для нас это священное пламя, которое так и ждёт, чтобы пробудиться." } } } } },
    [94466] = { d = 30.9, g = 1, v = "dwarf-male", n = { m = 337, f = 337 }, c = { m = { { 0.00, "Но ты ведь столько шёл не ради моих рассказов, так ведь?" }, { 4.15, "Тебе нужно вечное пламя и тотем огня." }, { 7.14, "Сначала нам понадобится сапта, которая свяжет твой дух со стихией огня." }, { 12.52, "Я её приготовлю, только добудь для меня две вещи: огненную смолу геомантов-туннельщиков из кобольдских пещер на севере и мешочек с реагентами ясновидца из племени Камнедробов, таящегося среди южных холмов." }, { 27.96, "Опасная задача, зато под стать пламени." } }, f = { { 0.00, "Но ты ведь столько шла не ради моих рассказов, так ведь?" }, { 4.01, "Тебе нужно вечное пламя и тотем огня." }, { 6.90, "Сначала нам понадобится сапта, которая свяжет твой дух со стихией огня." }, { 12.09, "Я её приготовлю, только добудь для меня две вещи: огненную смолу геомантов-туннельщиков из кобольдских пещер на севере и мешочек с реагентами ясновидца из племени Камнедробов, таящегося среди южных холмов." }, { 27.01, "Опасная задача, зато под стать пламени." } } }, t = { d = 35.0, v = "dwarf-male", n = { x = 332 }, c = { x = { { 0.00, "Да, это то, что нужно." }, { 1.89, "Запомни, что я скажу: огонь – это не только ярость и разрушения." }, { 7.33, "Это жизнь, это жар горна, это дыхание творения." }, { 11.40, "Все вещи связаны в равновесии." }, { 13.97, "Одна сила укрощает другую, даёт ей смысл существования." }, { 18.58, "Без тени свет был бы слепящей вспышкой." }, { 21.82, "Без огня камень был бы слишком холоден." }, { 25.15, "Истинное мастерство магии огня – умение сочетать его с другими силами, а не только всё сжигать." }, { 33.23, "Вот истинная мудрость." } } } } },
    [94467] = { d = 27.9, v = "dwarf-male", n = { x = 297 }, c = { x = { { 0.00, "Сапта огня готова." }, { 1.50, "Пришло время встретиться с пламенем." }, { 4.29, "Вкуси её у святилища, а затем заберись до самой вершины." }, { 8.58, "Там ты найдёшь духа: он не нанесёт удар раньше тебя, но сразу поймёт, что ты его видишь." }, { 15.12, "Бей не мешкая." }, { 16.21, "Чем больше будешь ждать, тем сильнее он разгорится." }, { 20.03, "Когда дух падёт, забери его искры и положи в жаровню." }, { 24.12, "Подожги от неё факел, и получишь благословение огня." } } }, t = { d = 22.0, v = "narrator", n = { x = 221 }, c = { x = { { 0.00, "Когда вы бросаете уголёк в жаровню, в чаше вспыхивает жаркое белое пламя." }, { 6.04, "Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьётся пламя." }, { 13.10, "Вы опускаете факел в чашу, и он мгновенно вспыхивает." }, { 17.44, "Вам кажется, что дым факела тянется в сторону Чёрной горы." } } } } },
    [94468] = { d = 22.4, v = "narrator", n = { x = 217 }, c = { x = { { 0.00, "Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Лок Модан." }, { 8.48, "Вас охватывает восторг." }, { 10.50, "Пламя факела рвётся и трепещет на ветру." }, { 14.00, "И вот вы начинаете спускаться обратно по тропе, ведущей в Дун Морог, возвращаясь к Брюксу Дитя Искр." } } }, t = { d = 24.6, g = 1, v = "dwarf-male", n = { m = 254, f = 255 }, c = { m = { { 0.00, "Клянусь бородой Мадорана, твой дух горит ярче, чем любой факел, – ты можешь собой гордиться." }, { 6.90, "Не сходи и дальше с этого пути, и перед твоей волей склонятся все стихии." }, { 12.46, "Собратья будут обращаться к тебе за помощью и советом." }, { 16.55, "Позволь мне первым от души тебя поздравить – и вручить новый тотем." }, { 21.64, "Ты заслужил его, дитя пламени." } }, f = { { 0.00, "Клянусь бородой Мадорана, твой дух горит ярче, чем любой факел, – ты можешь собой гордиться." }, { 7.09, "Не сходи и дальше с этого пути, и перед твоей волей склонятся все стихии." }, { 12.80, "Собратья будут обращаться к тебе за помощью и советом." }, { 17.00, "Позволь мне первым от души тебя поздравить – и вручить новый тотем." }, { 22.23, "Ты заслужила его, дитя пламени." } } } } },
    [94472] = { t = { d = 4.6, v = "dwarf-male", n = { x = 35 }, c = { x = { { 0.00, "Возьми это и помни – этот предмет священный." } } } } },
    [94473] = { t = { d = 5.9, v = "dwarf-male", n = { x = 51 }, c = { x = { { 0.00, "Пусть огонь неугасимо пылает в твоём сердце!" }, { 4.32, "Стихии ждут тебя." } } } } },
    [94480] = { d = 28.2, v = "orc-male#60", n = { x = 287 }, c = { x = { { 0.00, "Люди – лишь одна из местных угроз." }, { 2.82, "Сумеречные сектанты подступают всё ближе, завывания гноллов оглашают здешние холмы, битва может грянуть в любое мгновение." }, { 12.71, "Мы должны поддержать союзников, чтобы они были сильными: триумф или падение Рог'мара может зависеть от них." }, { 21.45, "Доставь собранные припасы Горгу." }, { 24.12, "Он проследит за тем, чтобы наши союзники были сыты." } } } },
    [94481] = { d = 20.1, v = "orc-male", n = { x = 203 }, c = { x = { { 0.00, "Эта сытная похлёбка придаст нашим новобранцам сил – достаточно, чтобы держать врагов на расстоянии." }, { 8.06, "Возьми это и накорми бойцов на западе." }, { 11.29, "И не слушай их нытьё." }, { 12.98, "Мы с трудом защищаем линии снабжения – пусть скажут спасибо, что не приходится есть глину." } } } },
    [94483] = { d = 21.8, v = "orc-male#60", n = { x = 229 }, c = { x = { { 0.00, "Наши разведчики обнаружили тренировочные лагеря у реки к югу." }, { 4.83, "Узнай я о них раньше, нам бы не пришлось так долго искать и убивать этих грязных людишек по одному." }, { 12.53, "Действуй дальше." }, { 13.86, "Загоняя людей в их нелепую крепость, мы выигрываем время для других насущных дел." }, { 20.16, "Ступай, время не ждёт." } } } },
    [94484] = { d = 26.0, v = "skyborne-male", n = { x = 276 }, c = { x = { { 0.00, "Найдётся минутка?" }, { 1.32, "Ты направляешься в Теневейный лес?" }, { 3.88, "Там, в пещере к северо-востоку, действует конклав друидов." }, { 8.39, "Я жду от них вестей, которых нет уже очень давно." }, { 12.21, "После разрушения Бан'этала и недавних тревожных событий я боюсь, что случилась беда." }, { 18.73, "Прошу, если можешь туда отправиться, разыщи Элегаэль Колючую Лапу – тогда я смогу успокоиться." } } }, t = { d = 24.1, g = 1, v = "skyborne-female", n = { m = 191, f = 189 }, c = { m = { { 0.00, "Как хорошо, что наше послание добралось до Лотелума." }, { 4.23, "Погоди, а где остальные бойцы?" }, { 6.70, "Тебя же не отправили одного?" }, { 8.96, "*Элегаэль бледнеет, когда вы пересказываете ей разговор с Лотелумом.*" }, { 13.92, "Значит, послание не дошло." }, { 16.02, "Тогда мы и вправду в тяжёлом положении." }, { 19.03, "Похоже, придётся справляться своими силами." }, { 22.39, "Время дорого." } }, f = { { 0.00, "Как хорошо, что наше послание добралось до Лотелума." }, { 4.26, "Погоди, а где остальные бойцы?" }, { 6.75, "Тебя же не отправили одну?" }, { 8.88, "*Элегаэль бледнеет, когда вы пересказываете ей разговор с Лотелумом.*" }, { 14.00, "Значит, послание не дошло." }, { 16.24, "Тогда мы и вправду в тяжёлом положении." }, { 19.45, "Похоже, придётся справляться своими силами." }, { 23.04, "Время дорого." } } } } },
    [94485] = { d = 35.0, v = "skyborne-female", n = { x = 368 }, c = { x = { { 0.00, "Чтобы спасти моих товарищей в логове Когтя Ночи, мне понадобятся ингредиенты для припарки." }, { 7.11, "Первый и самый важный – мох \"Девичьи слёзы\"." }, { 10.55, "Обычно он растёт у корней деревьев Теневейного леса." }, { 14.64, "Этот мох выделяет липкое вещество, которое действует как антисептик и нужно для перевязки открытых ран." }, { 22.66, "Я собрала немного поблизости, но в лесу наверняка есть ещё." }, { 27.23, "Поспеши." }, { 27.93, "Нам понадобится много мха – если, конечно, раненые, которых мне пришлось оставить, ещё живы." } } }, t = { d = 9.8, g = 1, v = "skyborne-female", n = { m = 47, f = 48 }, c = { m = { { 0.00, "*Элегаэль берёт у вас липкий мох, устало улыбаясь.*" }, { 4.32, "Спасибо, ты славно потрудился." }, { 7.12, "Это как раз то, что нам нужно." } }, f = { { 0.00, "*Элегаэль берёт у вас липкий мох, устало улыбаясь.*" }, { 4.48, "Спасибо, ты славно потрудилась." }, { 7.28, "Это как раз то, что нам нужно." } } } } },
    [94486] = { d = 37.6, g = 1, v = "skyborne-female", n = { m = 418, f = 418 }, c = { m = { { 0.00, "Мне нужен ещё один ингредиент для припарки – перья теневейных визгунов, которые бродят в этом лесу." }, { 7.33, "У молодых особей перья обладают изолирующими свойствами – они отлично подойдут, чтобы наложить поверх мха." }, { 15.19, "Перья не дадут засохнуть антисептическому соку и хоть немного защитят раны от воздействия окружающей среды." }, { 23.04, "Должна предупредить: хотя обычно визгуны – мирные создания, в последнее время они ведут себя на удивление агрессивно." }, { 31.76, "Их большие когти запросто вспорют тебе живот, если не будешь осторожен." } }, f = { { 0.00, "Мне нужен ещё один ингредиент для припарки – перья теневейных визгунов, которые бродят в этом лесу." }, { 7.46, "У молодых особей перья обладают изолирующими свойствами – они отлично подойдут, чтобы наложить поверх мха." }, { 15.45, "Перья не дадут засохнуть антисептическому соку и хоть немного защитят раны от воздействия окружающей среды." }, { 23.44, "Должна предупредить: хотя обычно визгуны – мирные создания, в последнее время они ведут себя на удивление агрессивно." }, { 32.31, "Их большие когти запросто вспорют тебе живот, если не будешь осторожна." } } }, t = { d = 6.2, v = "skyborne-female", n = { x = 57 }, c = { x = { { 0.00, "Благодарю." }, { 0.97, "Я использую каждое перо, чтобы их жертва не была напрасной." } } } } },
    [94487] = { d = 32.2, v = "skyborne-female", n = { x = 363 }, c = { x = { { 0.00, "Культ Ал'акет напал на нас без предупреждения, и их мотивы остаются для меня загадкой." }, { 6.05, "Я всегда знала, что у них облака вместо мозгов, но не думала, что они нарушат равновесие на Зефрисе, совершив подобную жестокость." }, { 15.32, "Убей как можно больше сектантов и забери фамильные реликвии, у кого найдёшь." }, { 20.79, "Эти проклятые сектанты не заслуживают зваться шен'дорай." }, { 25.35, "Как не заслуживают и того, чтобы их прах был развеян по ветру – пусть их тела съедят лесные звери." } } }, t = { d = 25.8, g = 1, v = "skyborne-female", n = { m = 208, f = 210 }, c = { m = { { 0.00, "*Элегаэль тревожно смотрит на окровавленные трофеи.*" }, { 4.24, "Столько жизней потеряно, столько потенциала было у этих молодых шен'дорай." }, { 10.45, "Спасибо, что принёс эти реликвии, герой." }, { 13.77, "Я сохраню их, а потом отнесу верховному старейшине." }, { 17.99, "Он позаботится о том, чтобы они дождались следующего и, возможно, более достойного поколения." } }, f = { { 0.00, "*Элегаэль тревожно смотрит на окровавленные трофеи.*" }, { 4.24, "Столько жизней потеряно, столько потенциала было у этих молодых шен'дорай." }, { 10.43, "Спасибо, что принесла эти реликвии, героиня." }, { 14.12, "Я сохраню их, а потом отнесу верховному старейшине." }, { 18.32, "Он позаботится о том, чтобы они дождались следующего и, возможно, более достойного поколения." } } } } },
    [94488] = { d = 25.5, v = "skyborne-female", n = { x = 272 }, c = { x = { { 0.00, "Я по-прежнему не понимаю, что понадобилось здесь сектантам, но я чую знакомый запах, пробивающийся через смрад пролитой крови." }, { 9.50, "Один из друидов нашего круга – Хаалиен – исчез несколько месяцев назад." }, { 15.07, "Похоже, он продал свою жалкую шкуру сектантам." }, { 18.72, "Покажи ему, что бывает, когда проливаешь кровь своих же собратьев!" }, { 23.81, "Принеси мне его голову." } } }, t = { d = 18.7, v = "skyborne-female", n = { x = 136 }, c = { x = { { 0.00, "*Элегаэль морщится, увидев отрубленную голову, но потом кивает.*" }, { 5.76, "Спасибо." }, { 6.46, "Как бы ни бушевала во мне ярость, мне было бы сложно убить собрата." }, { 11.68, "Не стоит о нём скорбеть." }, { 13.58, "Его невежество и злоба погубили сегодня множество невинных жизней." } } } } },
    [94489] = { d = 31.8, v = "skyborne-female", n = { x = 328 }, c = { x = { { 0.00, "Я приготовила припарки." }, { 1.81, "Скорее отнеси их друидам в пещере – иди к северу через поляну." }, { 6.76, "Моим братьям досталось куда сильнее, чем мне." }, { 10.31, "Наверняка они даже не в состоянии исцелить свои раны." }, { 14.57, "Друидов среди шен'дорай осталось так мало, что дорога каждая жизнь." }, { 19.79, "Пока ты здесь, у меня есть личная просьба." }, { 23.07, "Мой супруг, Йорел Песнь Ветра, был в тяжёлом состоянии, когда я уходила." }, { 28.57, "Прошу, обработай его раны, если он ещё жив." } } }, t = { d = 23.2, v = "skyborne-female", n = { x = 95 }, c = { x = { { 0.00, "*Элегаэль бледнеет, когда вы рассказываете о судьбе Йорела и состоянии остальных друидов.*" }, { 6.72, "Нет..." }, { 7.35, "Нет!" }, { 7.79, "Всё куда хуже, чем я..." }, { 10.12, "Они заплатят." }, { 14.42, "Они все заплатят!" }, { 16.63, "Все, кто якшается с культом Ал'акет, познают мой гнев!" }, { 22.34, "Клянусь..." } } } } },
    [94490] = { d = 16.2, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "В наруче Хаалиена спрятана записка – немного порванная и запятнанная кровью во время сражения." }, { 7.23, "Похоже, она содержит полезные сведения о мотивах нападения культа на логово друидов." }, { 13.77, "Элегаэль наверняка заинтересуется." } } }, t = { d = 30.4, v = "skyborne-female", n = { x = 281 }, c = { x = { { 0.00, "Им был нужен столп?" }, { 1.79, "Но зачем?" }, { 2.73, "Мы даже не были их целью?" }, { 5.12, "*Элегаэль продолжает читать, дрожа от гнева.*" }, { 8.80, "Они убили моих товарищей, потому что мы оказались на пути!" }, { 13.23, "Я разорву каждого сектанта собственными клыками!" }, { 16.85, "Никто не уйдёт отсюда живым." }, { 19.00, "Поспеши!" }, { 19.67, "Если приказ и правда поступил из Валанаара, вероятно, там прячется предатель." }, { 25.45, "Передай послание Лотелуму в Валанааре и расскажи ему, что произошло." } } } } },
    [94491] = { d = 32.6, v = "skyborne-female", n = { x = 331 }, c = { x = { { 0.00, "Похоже, в Валанааре прячется шпион, передающий сведения культу." }, { 5.08, "Ясно, что мне на долгое путешествие не хватит сил, но Лотелум должен узнать, что здесь произошло." }, { 12.67, "Ещё ему следует знать, какая судьба постигла тех, кого больше нет с нами." }, { 18.54, "Благодаря твоей помощи, думаю, мы теперь справимся здесь сами, несмотря на все потери." }, { 25.41, "Прошу, поторопись." }, { 26.91, "Надеюсь, наши пути пересекутся вновь." }, { 29.92, "А пока... пойду убивать сектантов." } } }, t = { d = 34.6, v = "skyborne-male", n = { x = 295 }, c = { x = { { 0.00, "*Лотелум смотрит на вас с неподдельным ужасом, когда вы рассказываете, что произошло в логове друидов.*" }, { 7.52, "Я... прошу меня извинить." }, { 9.48, "Дай мне минуту." }, { 10.63, "У меня нет слов, чтобы выразить, что я сейчас чувствую." }, { 14.76, "Поистине удручающая новость." }, { 16.92, "Если послание не поддельное, то здесь, в Валанааре, прячется в лучшем случае сообщник сектантов, а в худшем – предатель." }, { 25.85, "Немедленно поставлю в известность верховного старейшину!" }, { 30.04, "Я не допущу, чтобы жертва моих товарищей оказалась напрасной." } } } } },
    [94493] = { d = 23.8, g = 1, v = "skyborne-female", n = { m = 201, f = 199 }, c = { m = { { 0.00, "Как хорошо, что наше послание добралось до Лотелума." }, { 4.11, "Погоди, а где остальные бойцы?" }, { 6.52, "Тебя же не отправили одного?" }, { 8.72, "*Элегаэль бледнеет, когда вы всё объясняете.*" }, { 12.48, "Значит, послание не дошло до Валанаара." }, { 15.55, "Тогда мы и вправду в тяжёлом положении." }, { 18.54, "Тогда придётся справляться своими силами." }, { 22.79, "Время дорого." } }, f = { { 0.00, "Как хорошо, что наше послание добралось до Лотелума." }, { 4.14, "Погоди, а где остальные бойцы?" }, { 6.57, "Тебя же не отправили одну?" }, { 8.64, "*Элегаэль бледнеет, когда вы всё объясняете.*" }, { 12.16, "Значит, послание не дошло до Валанаара." }, { 15.12, "Тогда мы и вправду в тяжёлом положении." }, { 18.01, "Тогда придётся справляться своими силами." }, { 22.11, "Время дорого." } } }, t = { d = 21.6, v = "skyborne-female", n = { x = 223 }, c = { x = { { 0.00, "Сектанты Ал'акета напали на нас почти без предупреждения." }, { 4.46, "Многие в моём логове ранены или умирают." }, { 7.72, "Я пыталась отправить весть в Валанаар, но, похоже, мои усилия были напрасны." }, { 13.74, "Раз уж ты здесь, умоляю, помоги нам." }, { 16.51, "Не знаю, сколько ещё мои собратья смогут выдерживать этот натиск." } } } } },
    [94494] = { d = 20.7, g = 1, v = "dwarf-male", n = { m = 218, f = 219 }, c = { m = { { 0.00, "Много воды утекло со времени последнего испытания." }, { 3.90, "Ты проявил немало упорства в учении, но теперь тебе пришло время узнать о чистоте воды." }, { 10.66, "Отыщи Норрика Тана Лока." }, { 12.64, "Он живёт у северо-западного края озера, к югу от Каменной Плотины." }, { 17.70, "Там и найдёшь его землянку." }, { 19.75, "Удачи тебе." } }, f = { { 0.00, "Много воды утекло со времени последнего испытания." }, { 3.91, "Ты проявила немало упорства в учении, но теперь тебе пришло время узнать о чистоте воды." }, { 10.78, "Отыщи Норрика Тана Лока." }, { 12.77, "Он живёт у северо-западного края озера, к югу от Каменной Плотины." }, { 17.85, "Там и найдёшь его землянку." }, { 19.91, "Удачи тебе." } } }, t = { d = 23.0, v = "dwarf-male", n = { x = 203 }, c = { x = { { 0.00, "Ветер дует тебе в спину, камни надёжно лежат под ногами, а огонь в твоей груди пылает ярко и тепло." }, { 9.04, "О да, самое время постичь истину о чистоте воды." }, { 13.44, "Твой путь был долгим, но дух твой отнесёт тебя ещё дальше." }, { 18.40, "Что ж, вперёд, сделай первый шаг." }, { 21.28, "Гора никого не ждёт." } } } } },
    [94495] = { d = 27.9, v = "dwarf-male", n = { x = 293 }, c = { x = { { 0.00, "Первым делом пойми такую истину: вода – это перерождение." }, { 4.51, "Вода точит камень, очищает от грязи и исцеляет утомлённых – но только если она чистая." }, { 11.13, "Оскверни воду, и она разнесёт эту скверну повсюду." }, { 15.02, "Если хочешь получить сапту воды, отыщи Гервдану Саэгрунд в Болотине." }, { 20.35, "Она проживает вместе с семьёй в пещере под южными водопадами." }, { 25.00, "Ну же, иди, пока река тебя не обогнала." } } }, t = { d = 29.8, g = 1, v = "dwarf-female#34", n = { m = 247, f = 249 }, c = { m = { { 0.00, "По глазам вижу, о чём ты думаешь, герой." }, { 3.17, "Кому придёт в голову поселиться глубоко в Болотине, где повсюду шатаются дворфы Чёрного Железа, а наших бойцов днём с огнём не сыщешь?" }, { 13.53, "Что ж, дружок, у всех бывают свои причины." }, { 16.84, "К тому же есть вопрос поважнее: что привело тебя в наш дом, к водопадам?" }, { 22.40, "Хотя, пожалуй, ответ очевиден." }, { 24.80, "*Гервдана протягивает руку, ловя мелкие брызги воды.*" } }, f = { { 0.00, "По глазам вижу, о чём ты думаешь, героиня." }, { 3.39, "Кому придёт в голову поселиться глубоко в Болотине, где повсюду шатаются дворфы Чёрного Железа, а наших бойцов днём с огнём не сыщешь?" }, { 13.99, "Что ж, подружка, у всех бывают свои причины." }, { 17.53, "К тому же есть вопрос поважнее: что привело тебя в наш дом, к водопадам?" }, { 23.23, "Хотя, пожалуй, ответ очевиден." }, { 25.68, "*Гервдана протягивает руку, ловя мелкие брызги воды.*" } } } } },
    [94497] = { d = 35.7, g = 1, v = "dwarf-female#34", n = { m = 361, f = 361 }, c = { m = { { 0.00, "А-а, значит, ты и правда пришёл за саптой?" }, { 3.31, "Тогда слушай внимательно, дорогуша." }, { 6.12, "Чтобы обрести понимание и заслужить сапту, ты должен найти воду в самых разных её проявлениях." }, { 13.58, "Когда будешь собирать образцы, наблюдай за всем." }, { 17.37, "Смотри, какие звери охраняют воду, какую землю она питает и как она влияет на жизнь вокруг." }, { 24.69, "Начнём с простого: наполни этот бурдюк у подножия водопада, где свежая вода встречается с солёной." }, { 32.29, "Ступай, но будь осторожен в болоте." } }, f = { { 0.00, "А-а, значит, ты и правда пришла за саптой?" }, { 3.45, "Тогда слушай внимательно, дорогуша." }, { 6.32, "Чтобы обрести понимание и заслужить сапту, ты должна найти воду в самых разных её проявлениях." }, { 13.93, "Когда будешь собирать образцы, наблюдай за всем." }, { 17.81, "Смотри, какие звери охраняют воду, какую землю она питает и как она влияет на жизнь вокруг." }, { 25.28, "Начнём с простого: наполни этот бурдюк у подножия водопада, где свежая вода встречается с солёной." }, { 33.03, "Ступай, но будь осторожна в болоте." } } }, t = { d = 34.2, g = 1, v = "dwarf-female#34", n = { m = 372, f = 373 }, c = { m = { { 0.00, "Хорошо, что ты не повстречал дворфов Чёрного Железа." }, { 3.89, "Они пробрались так далеко на север..." }, { 6.75, "Даже невольно задумываешься, на что были бы способны дворфы, если бы кланы перестали враждовать и объединились." }, { 15.14, "Что ж... при полной луне приливы самые сильные, и морская вода затопляет болото." }, { 21.28, "Этот момент и есть самый благоприятный для изучения воды в устье." }, { 26.26, "Благодарю тебя за этот священный дар." }, { 29.12, "Ты начинаешь становиться сосудом, который наполнится мудростью воды." } }, f = { { 0.00, "Хорошо, что ты не повстречала дворфов Чёрного Железа." }, { 3.88, "Они пробрались так далеко на север..." }, { 6.70, "Даже невольно задумываешься, на что были бы способны дворфы, если бы кланы перестали враждовать и объединились." }, { 14.93, "Что ж... при полной луне приливы самые сильные, и морская вода затопляет болото." }, { 20.96, "Этот момент и есть самый благоприятный для изучения воды в устье." }, { 25.85, "Благодарю тебя за этот священный дар." }, { 28.66, "Ты начинаешь становиться сосудом, который наполнится мудростью воды." } } } } },
    [94499] = { d = 31.4, v = "dwarf-female#34", n = { x = 337 }, c = { x = { { 0.00, "Озеро Безмолвия поит всё Красногорье, но к тому времени как его воды обрушиваются в водопаде Каменной Стражи, к ним что-то примешивается." }, { 10.40, "Местные мурлоки – здоровенные и странные твари, совсем не такие, как те, которых можно найти здесь или у озера Лок." }, { 19.02, "К счастью для горожан, они почти не отходят от подножия водопада." }, { 23.93, "Принеси мне образец вод у того старого форта." }, { 27.37, "Хочу разобраться, что их загрязняет, – яд или что-то ещё." } } }, t = { d = 25.8, g = 1, v = "dwarf-female#34", n = { m = 257, f = 260 }, c = { m = { { 0.00, "Хм, с водицей всё в порядке." }, { 2.23, "Должно быть, это тамошние тёмные провидцы заколдовали мурлоков." }, { 7.28, "А вода кристально чистая." }, { 9.37, "Ты проявил усердие и успешно выполнил порученные задания." }, { 13.98, "Это значит, что ты готов к следующей части пути." }, { 17.94, "Ещё одна проба воды, и я смогу создать реактив, необходимый для сапты." }, { 23.63, "Норрик будет доволен." } }, f = { { 0.00, "Хм, с водицей всё в порядке." }, { 2.26, "Должно быть, это тамошние тёмные провидцы заколдовали мурлоков." }, { 7.37, "А вода кристально чистая." }, { 9.49, "Ты проявила усердие и успешно выполнила порученные задания." }, { 14.31, "Это значит, что ты готова к следующей части пути." }, { 18.40, "Ещё одна проба воды, и я смогу создать реактив, необходимый для сапты." }, { 24.17, "Норрик будет доволен." } } } } },
    [94500] = { d = 40.3, v = "dwarf-female#34", n = { x = 429 }, c = { x = { { 0.00, "Возьми этот бурдюк и отправляйся прямиком в изумрудные чащи Ясеневого леса." }, { 5.87, "Среди вод, не затронутых порчей, ты найдёшь деревушку Астранаар." }, { 10.70, "Дно местного озера усеяно обломками строений, существовавших в давно минувшие времена." }, { 17.33, "Принеси мне образец из него." }, { 19.54, "То будет чистая, древняя и, возможно, зачарованная вода." }, { 23.89, "Это последнее, что мне нужно, прежде чем я отправлю тебя к Норрику." }, { 29.07, "Сядь на корабль в Гавани Менетилов, идущий в Аубердин." }, { 33.22, "Он останавливается в Южнобережье." }, { 35.70, "И имей в виду... у леса есть глаза, и они никогда не моргают." } } }, t = { d = 21.2, v = "dwarf-female#34", n = { x = 214 }, c = { x = { { 0.00, "Отлично!" }, { 0.73, "С этими образцами я выварю для тебя фиал такой чистой воды, что горы заплачут от счастья." }, { 8.12, "Она станет последним звеном в твоём обряде посвящения." }, { 12.58, "Я горжусь нашим родством." }, { 14.70, "Ты образец настоящего шамана, и мне не терпится услышать о твоих будущих подвигах." } } } } },
    [94501] = { d = 13.6, v = "dwarf-female#34", n = { x = 144 }, c = { x = { { 0.00, "Прежде чем провести обряды с тотемом воды, Норрик поручит тебе ещё одно задание." }, { 6.22, "Для этого понадобится фиал с водой, который я тебе дала." }, { 10.60, "Ступай, поговори с ним." }, { 12.38, "Мы ещё встретимся." } } }, t = { d = 24.6, v = "dwarf-male", n = { x = 272 }, c = { x = { { 0.00, "А-а, вода, собранная тобой и благословлённая самой Гервданой?" }, { 4.51, "Поистине чудесный дар." }, { 6.16, "Из этих фиалов и получится твоя сапта, которая позволит увидеть духов воды у пруда Стенделя близ Луноречья." }, { 14.18, "После этого у тебя останется несколько капель – они тоже крайне важны..." }, { 19.68, "Даже пробка, слегка промоченная священной водой, может быть полезна." } } } } },
    [94502] = { d = 35.0, v = "dwarf-male", n = { x = 379 }, c = { x = { { 0.00, "В Западном Крае, недалеко от Луноречья, находится пруд Стенделя." }, { 4.87, "Когда-то в нём бил чистый источник, но теперь он омрачён тёмными силами, а обитающие в том месте духи совсем умолкли." }, { 13.65, "Тебе придётся сразиться с порчей, оскверняющей воду." }, { 17.63, "Возьми её браслеты и последние капли зелья Гервданы и возложи их на алтарь святилища." }, { 24.14, "На этот жест откликнется дух, верный и чистый." }, { 27.64, "Поговори с ним и наберись у него мудрости." }, { 30.87, "Принеси мне доказательство успеха, и я дарую тебе тотем." } } }, t = { d = 17.2, v = "narrator", n = { x = 190 }, c = { x = { { 0.00, "Вы помещаете браслеты на алтарь и выливаете на сухой камень оставшиеся капли зелья Норрика." }, { 6.94, "Вы начинаете проговаривать простые слова, которым вас обучил Норрик, и капли, попавшие на камень внутрь оков, тут же начинают испаряться..." } } } } },
    [94503] = { d = 18.2, v = "narrator", n = { x = 188 }, c = { x = { { 0.00, "Как только вы договариваете последнее слово, святилище вспыхивает ярким светом." }, { 6.58, "Шипение испаряющейся воды сменяется тишиной, и вы в смятении наблюдаете за тем, как осквернённые духи вокруг распадаются, словно пепел на ветру." } } }, t = { d = 10.5, v = "elemental-water", n = { x = 87 }, c = { x = { { 0.00, "Спасибо тебе." }, { 1.47, "Спасибо шаманам." }, { 3.21, "Порча отступает, но жизнь продолжает увядать." }, { 7.81, "Пусть шаманы охраняют жизнь." } } } } },
    [94505] = { d = 15.8, v = "elemental-water", n = { x = 113 }, c = { x = { { 0.00, "Возьми осколок." }, { 1.70, "Возьми его и даруй жизнь." }, { 4.43, "Даруй жизнь и пойми." }, { 6.60, "Пойми, что вода – это жизнь..." }, { 9.81, "А порча – конец жизни." }, { 12.26, "Оберегай и даруй жизнь силой воды." } } }, t = { d = 24.8, v = "dwarf-male", n = { x = 271 }, c = { x = { { 0.00, "О да, лучше доказательства мне и не надо." }, { 3.01, "Ты молодец." }, { 3.88, "Рад, что могу первым поздравить тебя с успехом – и вручить твой тотем воды." }, { 9.50, "Используй его с умом, и он принесёт тебе удачу." }, { 13.04, "Твоё следующее испытание настанет нескоро, так что продолжай учиться." }, { 18.12, "Все знают, что чистая вода исцеляет, но она обладает далеко не только целебными свойствами." } } } } },
    [94532] = { d = 17.4, v = "orc-female#58", n = { x = 196 }, c = { x = { { 0.00, "Хотя из-за Сумеречного Молота здесь поубавилось гноллов, они всё ещё представляют угрозу." }, { 6.52, "На холмах к юго-западу полно этих тварей – они нападают на торговцев и любых других путников." }, { 13.49, "Избавься от них и обезопась дороги для наших союзников." } } } },
    [94533] = { d = 28.1, v = "orc-female#58", n = { x = 320 }, c = { x = { { 0.00, "Среди хохочущих обитателей Щетинистых холмов к юго-западу отсюда живёт старый гнолл по кличке Снаргл." }, { 7.46, "Это создание издаёт на редкость жуткие звуки, даже для гнолла." }, { 12.12, "Его присутствие воодушевляет остальных, что усложняет задачу для наших союзников и разведчиков." }, { 19.11, "Я была бы рада получить в коллекцию трофей, говорящий о том, что мы покончили с этой неприятной тварью." }, { 26.70, "Разберись побыстрее." } } } },
    [94535] = { d = 15.5, v = "orc-female#124", n = { x = 164 }, c = { x = { { 0.00, "Союзники, добывающие руду в холмах на юге отсюда, сообщили о нескольких нападениях гноллов." }, { 7.16, "Отправься туда, отыщи лагеря гноллов и верни украденную руду." }, { 12.08, "Забери её с гнолльских трупов, если придётся." } } } },
    [94556] = { d = 6.1, v = "creature/ogre", n = { x = 60 }, c = { x = { { 0.00, "Джом-Джом пришёл в поисках друга." }, { 2.81, "Теперь Джом-Джом хочет вернуться домой." } } } },
    [94568] = { d = 16.7, v = "skyborne-male", n = { x = 177 }, c = { x = { { 0.00, "Перебежчик явно пришёл в ужас от того, что замыслили сектанты – настолько, что отступился от их учений и обратился к нам." }, { 9.13, "Очень жаль, что он погиб и унёс эти тайны в могилу." }, { 13.07, "Нам надо всё обдумать и обсудить дальнейшие шаги." } } }, t = { d = 8.3, v = "skyborne-male", n = { x = 95 }, c = { x = { { 0.00, "Можно было бы отправить миротворцев на бой с культом, но мы вряд ли одолеем их в открытом бою." }, { 6.66, "Нам нужен другой подход." } } } } },
    [94613] = { d = 30.6, g = 1, v = "human-male", n = { m = 351, f = 352 }, c = { m = { { 0.00, "Мы получаем боевых коней с двух близлежащих ферм." }, { 3.37, "Похоже, одна из них, ферма Вилеров у дороги рядом с городом, потеряла весь свой скот." }, { 9.24, "Причина пока неизвестна." }, { 10.98, "Без коней у нас нет кавалерии, а без неё наша кампания против Орды почти безнадёжна." }, { 16.72, "Сам понимаешь, эту ситуацию надо разрешить как можно скорее." }, { 20.97, "Вот только я понятия не имею, с чего начать." }, { 24.09, "Сходи к усадьбе Вилера и поговори с Бенджи." }, { 27.15, "Может быть, он наведёт тебя на нужную мысль." } }, f = { { 0.00, "Мы получаем боевых коней с двух близлежащих ферм." }, { 3.37, "Похоже, одна из них, ферма Вилеров у дороги рядом с городом, потеряла весь свой скот." }, { 9.24, "Причина пока неизвестна." }, { 10.98, "Без коней у нас нет кавалерии, а без неё наша кампания против Орды почти безнадёжна." }, { 16.72, "Сама понимаешь, эту ситуацию надо разрешить как можно скорее." }, { 21.55, "Вот только я понятия не имею, с чего начать." }, { 24.67, "Сходи к усадьбе Вилера и поговори с Бенджи." }, { 27.73, "Может быть, он наведёт тебя на нужную мысль." } } }, t = { d = 8.2, g = 1, v = "human-male", n = { m = 96, f = 96 }, c = { m = { { 0.00, "Сам большой начальник тебя прислал, да?" }, { 2.79, "Ты помочь пришёл или, как тот прошлый тип, будешь донимать меня насчёт лошадей?" } }, f = { { 0.00, "Сам большой начальник тебя прислал, да?" }, { 2.63, "Ты помочь пришла или, как тот прошлый тип, будешь донимать меня насчёт лошадей?" } } } } },
    [94614] = { d = 22.4, g = 1, v = "human-male", n = { m = 264, f = 265 }, c = { m = { { 0.00, "Ты уже видел тех мурлоков у реки, к западу отсюда?" }, { 3.48, "Мерзкие твари." }, { 4.52, "Вредят и диким животным, и моему скоту." }, { 7.27, "Не говоря уже о том, что они обосновались прямо на моём любимом месте для рыбалки!" }, { 12.83, "В Лесоречье не найдётся никого, кто не порадуется, если ты избавишься от пары мурлоков." }, { 18.63, "Ты очень нас выручишь, убив как можно больше этих гадов." } }, f = { { 0.00, "Ты уже видела тех мурлоков у реки, к западу отсюда?" }, { 3.49, "Мерзкие твари." }, { 4.53, "Вредят и диким животным, и моему скоту." }, { 7.28, "Не говоря уже о том, что они обосновались прямо на моём любимом месте для рыбалки!" }, { 12.84, "В Лесоречье не найдётся никого, кто не порадуется, если ты избавишься от пары мурлоков." }, { 18.64, "Ты очень нас выручишь, убив как можно больше этих гадов." } } }, t = { d = 5.8, v = "human-male", n = { x = 63 }, c = { x = { { 0.00, "Борьба с вредителями — важная часть работы любого фермера." }, { 4.47, "Спасибо за помощь." } } } } },
    [94615] = { d = 20.2, v = "human-male", n = { x = 228 }, c = { x = { { 0.00, "Ума не приложу, куда подевались наши лошади." }, { 3.30, "Я встал поутру, чтобы их покормить, а они все как сквозь землю провалились." }, { 8.61, "Здесь жизнь посуровей, чем в стенах Фархолда." }, { 11.78, "Их мог сцапать кто угодно: звери, мурлоки, орки..." }, { 15.40, "Чтобы сузить список подозреваемых, надо поискать зацепки в конюшнях." } } }, t = { d = 3.8, v = "human-male", n = { x = 30 }, c = { x = { { 0.00, "Так я и знал!" }, { 1.28, "Это всё проклятые койоты!" } } } } },
    [94616] = { t = { d = 7.9, v = "dwarf-male", n = { x = 80 }, c = { x = { { 0.00, "Возьми сапту воды и найди заражённую воду в пруду в Западном Крае." }, { 5.41, "Я очень верю в твои способности." } } } } },
    [94617] = { d = 24.7, v = "human-male", n = { x = 273 }, c = { x = { { 0.00, "В пещере к западу отсюда живёт стая койотов." }, { 3.27, "Иногда их видно через реку." }, { 5.37, "Раньше они охотились на рыбу с берега, но, похоже, мурлоки вытеснили их из привычных угодий, и теперь они повадились охотиться на лошадей." }, { 15.44, "Вожак стаи койотов крупнее других и с более тёмным мехом." }, { 19.70, "Мы прозвали его Сажемех." }, { 21.53, "Думаю, если его убить, остальные разбегутся." } } }, t = { d = 16.5, v = "human-male", n = { x = 122 }, c = { x = { { 0.00, "*Бенджи смотрит в морду на шкуре Сажемеха.*" }, { 3.12, "Ну-ну-ну, будешь знать, как рыскать по моим конюшням!" }, { 7.28, "*Бенджи снова поворачивается к тебе.*" }, { 9.84, "Хорошая работа." }, { 10.93, "Когда мы снова встанем на ноги, приятно будет знать, что наши лошади в безопасности." } } } } },
    [94618] = { d = 27.2, v = "human-male", n = { x = 291 }, c = { x = { { 0.00, "Судя по найденным тобой следам, койоты пожрали большую часть лошадей." }, { 4.70, "Но судьба нескольких до сих пор не ясна." }, { 7.35, "Те, кого не съели, скорее всего, убежали куда-то в страхе." }, { 11.32, "Не знаю, сколько лошадей уцелело, но нам лучше найти их, пока койоты не вернулись." }, { 16.80, "*Бенджи протягивает вам мешок*" }, { 19.12, "Вот, возьми." }, { 20.00, "Если увидишь лошадь, дай ей немного нашего корма." }, { 23.51, "Так она тебе доверится, и ты сможешь привести её сюда." } } }, t = { d = 2.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Лошадь с удовольствием жуёт корм." } } } } },
    [94638] = { d = 36.5, g = 1, v = "creature/furbolg", n = { m = 341, f = 341 }, c = { m = { { 0.58, "Ты пришёл, чтобы обрести силу." }, { 3.08, "У меня есть для тебя поручение, хотя мне и нелегко об этом просить." }, { 8.59, "Моя подруга Ур'ендра потеряла рассудок и начала нападать на близких." }, { 14.24, "Когда магия ветров иссякла, многие на острове обезумели..." }, { 19.09, "Ур'ендра в том числе." }, { 20.86, "Её логово в пещере к западу отсюда, в скалах между Шен'дарским нагорьем и Ветроягодными низинами." }, { 28.79, "Прекрати её страдания, и я дарую тебе благословение." } }, f = { { 0.58, "Ты пришла, чтобы обрести силу." }, { 3.14, "У меня есть для тебя поручение, хотя мне и нелегко об этом просить." }, { 8.64, "Моя подруга Ур'ендра потеряла рассудок и начала нападать на близких." }, { 14.29, "Когда магия ветров иссякла, многие на острове обезумели..." }, { 19.12, "Ур'ендра в том числе." }, { 20.88, "Её логово в пещере к западу отсюда, в скалах между Шен'дарским нагорьем и Ветроягодными низинами." }, { 28.80, "Прекрати её страдания, и я дарую тебе благословение." } } }, t = { d = 29.5, g = 1, v = "creature/furbolg", n = { m = 251, f = 252 }, c = { m = { { 0.43, "Моя боль от утраты огромна, но это было нужно, чтобы сохранить равновесие." }, { 6.83, "Ты доказал, что у тебя есть решимость выживать и делать то, что должно, даже если цена ужасна." }, { 14.82, "Ты молодец, герой." }, { 16.42, "Благословляю тебя принимать наш облик." }, { 19.70, "Будь лучом надежды для слабых и защитником для нуждающихся." }, { 24.65, "Иди и познавай путь когтя, дитя." } }, f = { { 0.43, "Моя боль от утраты огромна, но это было нужно, чтобы сохранить равновесие." }, { 6.66, "Ты доказала, что у тебя есть решимость выживать и делать то, что должно, даже если цена ужасна." }, { 14.52, "Ты молодец, героиня." }, { 16.23, "Благословляю тебя принимать наш облик." }, { 19.42, "Будь лучом надежды для слабых и защитницей для нуждающихся." }, { 24.24, "Иди и познавай путь когтя, дитя." } } } } },
    [94668] = { d = 16.5, g = 1, v = "creature/ogre", n = { m = 150, f = 151 }, c = { m = { { 0.00, "Ты сокрушил хилых Сумеречных огров." }, { 3.11, "Но они хилые." }, { 4.35, "Сегодня покажи Кровавому королю и другу-гоблину, что тебе место среди нас." }, { 10.88, "Завтра, может, мы встретимся опять, если ты ещё будешь дышать." } }, f = { { 0.00, "Ты сокрушила хилых Сумеречных огров." }, { 3.41, "Но они хилые." }, { 4.65, "Сегодня покажи Кровавому королю и другу-гоблину, что тебе место среди нас." }, { 11.18, "Завтра, может, мы встретимся опять, если ты ещё будешь дышать." } } } },
    [94669] = { d = 23.0, v = "goblin-male", n = { x = 245 }, c = { x = { { 0.00, "Начнём с главного." }, { 1.36, "Мне нужен залог, чтобы обеспечить твою... безопасность." }, { 5.59, "Не смотри так, это не я придумал." }, { 8.11, "Такие правила." }, { 9.27, "Если не захочешь платить, придётся сказать Клагобою, что наш новый друг не хочет доказывать свою силу нашему радушному братству." }, { 18.95, "Выйдет очень неловко." }, { 20.65, "Смекаешь, к чему веду, дружище?" } } } },
    [94670] = { d = 16.9, v = "goblin-male", n = { x = 168 }, c = { x = { { 0.00, "Пришло время битвы на ринге Кровавого короля!" }, { 3.79, "Начнём с чего-нибудь попроще, приятель." }, { 6.92, "Этот пернатый проказник собьёт тебя с ног, а потом разорвёт на куски." }, { 12.45, "Эй, чего стоишь?" }, { 13.83, "Давай, выходи на ринг!" }, { 15.65, "Тебя ждёт слава!" } } } },
    [94672] = { d = 32.6, v = "orc-male", n = { x = 350 }, c = { x = { { 0.00, "Люди – не единственный наш враг в Лесоречье." }, { 3.37, "И даже не самый опасный." }, { 5.33, "Сектанты из культа Сумеречного Молота ведут кампанию против тех, кого считают еретиками в глазах своих нечестивых богов." }, { 14.81, "Обломки разорённого человеческого поселения на западе – лишь первое последствие их похода." }, { 21.69, "Рог'мар несомненно будет следующим." }, { 24.50, "Нельзя, чтобы они закрепились так близко к нам." }, { 28.22, "Отправляйся в так называемую Светогладь и прореди их ряды." } } } },
    [94678] = { d = 27.8, v = "human-male", n = { x = 338 }, c = { x = { { 0.00, "Гноллы доставляли нам проблемы с тех пор, как мы сюда прибыли." }, { 4.15, "Конечно, эти твари не так опасны, как Сумеречный Молот, но они агрессивны, настойчивы и, что хуже всего, значительно превосходят нас числом." }, { 13.62, "Холмы за этой заставой просто кишат гноллами, что усложняет любые вылазки на север и представляет угрозу для всех, кто живёт за пределами Фархолда." }, { 23.52, "Если мы хотим обезопасить эти земли, от гноллов надо избавиться." } } }, t = { d = 14.3, v = "human-male", n = { x = 95 }, c = { x = { { 0.00, "Это что, слюна гнолла на тебе?" }, { 2.57, "Неважно." }, { 3.31, "В любой другой ситуации я бы спросил, откуда она, но это..." }, { 8.16, "*Седрик проводит рукой сверху вниз, указывая на тебя.*" }, { 12.48, "Вот чем мы тут занимаемся." } } } } },
    [94679] = { d = 23.0, v = "human-male", n = { x = 258 }, c = { x = { { 0.00, "Гноллы ценят силу превыше всего." }, { 2.52, "Убивая сильнейших из них, мы не только уменьшаем непосредственную угрозу, но и вселяем страх в их сердца." }, { 10.10, "В Щетинистых холмах есть берлога, где затаился особенно опасный гнолл по имени Снаргл." }, { 16.34, "Его смерть, несомненно, посеет панику в стае Красногорья." }, { 20.66, "Принеси мне его рыло, и поскорее." } } }, t = { d = 6.1, v = "human-male", n = { x = 64 }, c = { x = { { 0.00, "Кровавый трофей, и скоро мы найдём ему достойное применение." }, { 4.86, "Отличная работа." } } } } },
    [94680] = { d = 31.8, v = "orc-male", n = { x = 348 }, c = { x = { { 0.00, "В этих краях всегда были небольшие группы сектантов Сумеречного Молота, но я никогда не видел их в таком количестве." }, { 8.81, "Будто кто-то или что-то побудило культистов расширить область своего влияния." }, { 14.77, "Я хочу узнать больше об этих сектантах и их целях." }, { 18.63, "Их тенеманты благословлены тёмными силами – такая масштабная атака наверняка держится на них." }, { 25.54, "Принеси мне всё, что найдёшь на трупах." }, { 28.39, "Мы должны узнать хоть что-то об этой кампании." } } } },
    [94727] = { d = 33.7, v = "orc-male", n = { x = 338 }, c = { x = { { 0.00, "Сумеречный Молот не просто так сеет здесь хаос." }, { 3.79, "Они копают по всему Лесоречью – кажется, что-то ищут." }, { 8.15, "Понятия не имею, что именно." }, { 10.44, "Очевидно, это какой-то источник силы, но я так и не узнал, что за источник." }, { 16.38, "Эти фанатики не станут делиться своими тайнами, но вряд ли сами ведут раскопки." }, { 22.75, "Вот их работяг и допросим." }, { 24.82, "Возвращайся в Светогладь и \"убеди\" кого-нибудь из горняков всё тебе рассказать." }, { 31.04, "Мы должны узнать, что тут творится." } } } },
    [94733] = { d = 29.1, g = 1, v = "goblin-male", n = { m = 319, f = 320 }, c = { m = { { 0.00, "Что ж, ты победил в паре боёв." }, { 2.14, "Я начинаю думать, что у тебя всё-таки есть тут будущее." }, { 6.03, "Но прежде чем я побегу уговаривать следующего соперника выйти на ринг, мне от тебя кое-что нужно – корм для Нюхли, ручного кабана Чух'чоха." }, { 15.94, "Я обещал за ним приглядывать, но у меня и так забот полон рот." }, { 20.34, "И вообще, от этого нам обоим будет польза, уж поверь." }, { 24.23, "Поищи к востоку от клуба Клагобоя робкого балбеса по имени Гобам." } }, f = { { 0.00, "Что ж, ты победила в паре боёв." }, { 2.36, "Я начинаю думать, что у тебя всё-таки есть тут будущее." }, { 6.25, "Но прежде чем я побегу уговаривать следующего соперника выйти на ринг, мне от тебя кое-что нужно – корм для Нюхли, ручного кабана Чух'чоха." }, { 16.16, "Я обещал за ним приглядывать, но у меня и так забот полон рот." }, { 20.56, "И вообще, от этого нам обоим будет польза, уж поверь." }, { 24.45, "Поищи к востоку от клуба Клагобоя робкого балбеса по имени Гобам." } } } },
    [94734] = { d = 20.9, v = "creature/ogre", n = { x = 190 }, c = { x = { { 0.00, "Гобам знает, что питомец Чух'чоха любить поесть." }, { 4.32, "Особенно если вкусно!" }, { 6.28, "Берёшь ням-ням-ягоды и растение с реки – Нюхле нравится." }, { 11.15, "Ягоды надо сладкие." }, { 12.95, "Лучше всего с фермы человеков, где рядом океан." }, { 17.19, "Найди." }, { 17.82, "Принеси." }, { 18.60, "Я помогу сделать лакомство." } } } },
    [94737] = { d = 8.9, v = "creature/ogre", n = { x = 85 }, c = { x = { { 0.00, "Вот, друг, держи лакомство." }, { 2.22, "Нюхля хрюкает от радости, когда его видит." }, { 5.85, "И скажи гоблину, чтобы меньше болтал." } } } },
    [94739] = { d = 15.4, g = 1, v = "goblin-male", n = { m = 153, f = 154 }, c = { m = { { 0.00, "Славно, что ты уцелел в первом раунде." }, { 3.05, "Со следующим противником мы старые друзья." }, { 6.38, "В голове у него пусто, но тумаки раздаёт так, что закачаешься." }, { 11.21, "Иди на арену и приготовься, а я пока вас объявлю." } }, f = { { 0.00, "Славно, что ты уцелела в первом раунде." }, { 3.51, "Со следующим противником мы старые друзья." }, { 6.84, "В голове у него пусто, но тумаки раздаёт так, что закачаешься." }, { 11.67, "Иди на арену и приготовься, а я пока вас объявлю." } } } },
