    [94745] = { d = 21.2, v = "orc-male#60", n = { x = 212 }, c = { x = { { 0.00, "Видишь ту крепость на западе?" }, { 2.45, "Сумеречный покров, так её называют." }, { 5.34, "До отказа заполнена трусами из Сумеречного Молота." }, { 9.49, "Может, у них и есть стены и численность, но зависеть от тёмных чар и древних богов могут только жалкие слабаки." }, { 18.54, "Покажи им, насколько они уязвимы!" } } } },
