    [94819] = { d = 23.8, g = 1, v = "human-male", n = { m = 277, f = 280 }, c = { m = { { 0.00, "Твоя верховная жрица Мимс хочет встретиться с тобой в Стальгорне." }, { 4.64, "Поспеши, мой находчивый друг, близится время твоего следующего испытания." }, { 9.79, "Мне хотелось бы своими глазами увидеть обряды твоего народа, но моё место здесь." }, { 15.45, "Пусть Свет направит тебя в твоих странствиях." }, { 18.63, "Ищи Мимс в Палатах Магии, когда доберёшься до города." }, { 22.38, "Она будет ждать." } }, f = { { 0.00, "Твоя верховная жрица Мимс хочет встретиться с тобой в Стальгорне." }, { 4.66, "Поспеши, моя находчивая подруга, близится время твоего следующего испытания." }, { 10.14, "Мне хотелось бы своими глазами увидеть обряды твоего народа, но моё место здесь." }, { 15.82, "Пусть Свет направит тебя в твоих странствиях." }, { 19.01, "Ищи Мимс в Палатах Магии, когда доберёшься до города." }, { 22.77, "Она будет ждать." } } }, t = { d = 11.2, g = 1, v = "gnome-female#41", n = { m = 108, f = 111 }, c = { m = { { 0.00, "Продолжай служить Свету, и из тебя выйдет великий герой." }, { 4.80, "Не теряй бдительности и преданности!" }, { 7.80, "Ты готов к следующему уроку служения." } }, f = { { 0.00, "Продолжай служить Свету, и из тебя выйдет великая героиня." }, { 5.03, "Не теряй бдительности и преданности!" }, { 8.08, "Ты готова к следующему уроку служения." } } } } },
    [94820] = { d = 29.4, v = "nightelf-female", n = { x = 352 }, c = { x = { { 0.00, "Твой народ очень умён." }, { 1.53, "Мы горды зваться вашими союзниками." }, { 3.98, "С каждым закатом ты и твои сородичи всё ближе к тому, чтобы вернуть свой город, но вместе с тем вам нужно заботиться о безопасности родных в изгнании." }, { 14.14, "Эта тоска по дому, верно, тяготит ваши сердца." }, { 17.44, "Недавно мы получили весточку из Стальгорна." }, { 20.38, "Тебя просят вернуться туда и поговорить с верховной жрицей Мимс в Палатах Магии." }, { 25.89, "Не стоит заставлять её ждать." }, { 27.85, "Да направит тебя Элуна." } } } },
