    [94823] = { d = 22.7, g = 1, v = "nightelf-female#51", n = { m = 248, f = 251 }, c = { m = { { 0.00, "Да благословит тебя Элуна, герой." }, { 2.44, "Надеюсь, Свет остаётся с тобой и защищает." }, { 5.38, "Недавно тебя искал один из ваших жрецов." }, { 8.40, "Он сказал, что тебе нужно как можно скорее вернуться в Зал Тайн и поговорить с верховной жрицей Мимс." }, { 15.57, "Похоже, ты отлично себя показал, раз привлёк её внимание." }, { 19.61, "Не задерживайся здесь, ты нужен своим." } }, f = { { 0.00, "Да благословит тебя Элуна, героиня." }, { 2.58, "Надеюсь, Свет остаётся с тобой и защищает." }, { 5.55, "Недавно тебя искал один из ваших жрецов." }, { 8.59, "Он сказал, что тебе нужно как можно скорее вернуться в Зал Тайн и поговорить с верховной жрицей Мимс." }, { 15.82, "Похоже, ты отлично себя показала, раз привлекла её внимание." }, { 20.15, "Не задерживайся здесь, ты нужна своим." } } } },
    [94824] = { d = 25.9, g = 1, v = "dwarf-male", n = { m = 279, f = 280 }, c = { m = { { 0.00, "Пора тебе отправиться в Стальгорн." }, { 2.56, "Верховная жрица Мимс из Зала Тайн повелевает явиться к ней." }, { 6.82, "Либо дела очень хороши, либо очень плохи, раз она решила встретиться с тобой лично." }, { 13.11, "Но я подозреваю, что ты отлично себя показал, и то, что она хочет тебя видеть, это добрый знак." }, { 20.06, "Я на твоём месте не задерживался бы здесь." }, { 23.01, "Поспеши туда, как только сможешь." } }, f = { { 0.00, "Пора тебе отправиться в Стальгорн." }, { 2.61, "Верховная жрица Мимс из Зала Тайн повелевает явиться к ней." }, { 6.95, "Либо дела очень хороши, либо очень плохи, раз она решила встретиться с тобой лично." }, { 13.37, "Но я подозреваю, что ты отлично себя показала, и то, что она хочет тебя видеть, это добрый знак." }, { 20.52, "Я на твоём месте не задерживался бы здесь." }, { 23.53, "Поспеши туда, как только сможешь." } } }, t = { d = 8.2, g = 1, v = "gnome-female#41", n = { m = 82, f = 84 }, c = { m = { { 0.00, "Ты не спешил." }, { 1.11, "Но тебя можно простить за твоё преданное служение Свету." }, { 5.79, "Будь внимателен на этом уроке." } }, f = { { 0.00, "Ты не спешила." }, { 1.17, "Но тебя можно простить за твоё преданное служение Свету." }, { 5.76, "Будь внимательна на этом уроке." } } } } },
    [94825] = { d = 20.2, g = 1, v = "nightelf-female#51", n = { x = 209 }, c = { m = { { 0.00, "Недавно приходил один из ваших жрецов и искал тебя, герой." }, { 4.34, "Он попросил передать, что тебя ждут в Зале Тайн." }, { 7.77, "По его словам, дело очень важное, но ты не беспокойся." }, { 11.72, "Выглядел он так, будто нёс добрые вести." }, { 14.64, "Я бы на твоём месте скорее поспешила туда." }, { 17.68, "Да пребудет с тобой Элуна, герой." } }, f = { { 0.00, "Недавно приходил один из ваших жрецов и искал тебя, героиня." }, { 4.47, "Он попросил передать, что тебя ждут в Зале Тайн." }, { 7.90, "По его словам, дело очень важное, но ты не беспокойся." }, { 11.84, "Выглядел он так, будто нёс добрые вести." }, { 14.75, "Я бы на твоём месте скорее поспешила туда." }, { 17.80, "Да пребудет с тобой Элуна, героиня." } } } },
    [94826] = { d = 19.4, v = "nightelf-female#51", n = { x = 210 }, c = { x = { { 0.00, "Слава Элуне и твоему Свету." }, { 2.17, "Примерно в это время многие из нашего ордена обучаются способностям, отражающим их веру в Элуну." }, { 9.49, "Если не ошибаюсь, у вас принято делать так же." }, { 12.95, "Когда закончишь дела в Дарнасе, отыщи свою верховную жрицу, чтобы продолжить обучение." } } } },
    [94829] = { d = 30.5, g = 1, v = "human-male", n = { m = 346, f = 348 }, c = { m = { { 0.00, "Если ты пришёл требовать часть урожая, ты опоздал." }, { 3.42, "Ты наверняка видел мою ферму – она полностью разрушена." }, { 7.34, "Многие годы добрые люди трудились в этих полях, чтобы накормить воинов и мирных жителей." }, { 13.63, "Но где же были наши отважные вояки, когда пришли сектанты?" }, { 17.74, "Почему никто не защитил нас?" }, { 19.73, "Как забирать у нас провиант – так это они первые." }, { 23.15, "Помоги хотя бы вернуть то, что у нас украли." }, { 26.20, "И пусть мёртвые упокоятся с миром на кладбище к западу..." } }, f = { { 0.00, "Если ты пришла требовать часть урожая, ты опоздала." }, { 3.59, "Ты наверняка видела мою ферму – она полностью разрушена." }, { 7.95, "Многие годы добрые люди трудились в этих полях, чтобы накормить воинов и мирных жителей." }, { 14.24, "Но где же были наши отважные вояки, когда пришли сектанты?" }, { 18.35, "Почему никто не защитил нас?" }, { 20.34, "Как забирать у нас провиант – так это они первые." }, { 23.76, "Помоги хотя бы вернуть то, что у нас украли." }, { 26.81, "И пусть мёртвые упокоятся с миром на кладбище к западу..." } } }, t = { d = 7.2, v = "human-male", n = { x = 67 }, c = { x = { { 0.00, "Этих людей уже не вернуть, но у меня на сердце легче оттого, что их души обрели покой." } } } } },
    [94832] = { d = 15.6, v = "human-male", n = { x = 181 }, c = { x = { { 0.00, "К сожалению, мне так и не удалось выяснить, чьё это кольцо, чтобы его родные смогли проститься." }, { 6.68, "Может быть, поможет Дэйтор." }, { 8.63, "Он хорошо знал остальных из нашего полка." }, { 11.52, "Надеюсь только, это не пробудит в нём тяжёлых воспоминаний..." } } } },
    [94841] = { d = 41.3, v = "narrator", n = { x = 151 }, c = { x = { { 0.00, "Сбоку на ящик прилеплена написанная от руки этикетка." }, { 4.30, "На правой её стороне изображена карта с большим красным кружком, отмечающим место на юго-восточном побережье к северу от аляповато нарисованного храма, вокруг которого можно разглядеть воду и каких-то крылатых существ, а на левой крупными буквами нанесён текст." }, { 25.02, "Собственность Фриз Искродох" }, { 27.17, "Пороховой порт" }, { 28.31, "Предупреждение: не повреждать." }, { 30.68, "Не вскрывать без присмотра." }, { 32.83, "Внизу дополнительная приписка." }, { 35.27, "В случае утери вернуть владельцу, Фриз Искродох, в Пороховой порт в Лесоречье." } } } },
    [94842] = { d = 26.6, g = 1, v = "human-male", n = { m = 305, f = 306 }, c = { m = { { 0.00, "Мы здесь сами делаем удобрение по моему особому рецепту." }, { 3.94, "Ужасно воняет, зато деревья от него растут как сорняки." }, { 7.88, "Надо просто смешать раковые панцири, навоз и головы мурлоков в соотношении один к одному к двум." }, { 14.64, "Аппетитно, да?" }, { 15.64, "С навозом всё просто, его полно на ферме на юге." }, { 19.08, "А вот за головами и панцирями тебе придётся сходить к реке." }, { 23.15, "Добудь эти ингредиенты, если готов нам помочь." } }, f = { { 0.00, "Мы здесь сами делаем удобрение по моему особому рецепту." }, { 3.94, "Ужасно воняет, зато деревья от него растут как сорняки." }, { 7.88, "Надо просто смешать раковые панцири, навоз и головы мурлоков в соотношении один к одному к двум." }, { 14.64, "Аппетитно, да?" }, { 15.64, "С навозом всё просто, его полно на ферме на юге." }, { 19.08, "А вот за головами и панцирями тебе придётся сходить к реке." }, { 23.15, "Добудь эти ингредиенты, если готова нам помочь." } } }, t = { d = 10.7, g = 1, v = "human-male", n = { m = 119, f = 120 }, c = { m = { { 0.00, "Я по запаху понял, что ты идёшь." }, { 2.19, "Спасибо, что замарал ради нас руки, так сказать." }, { 5.58, "А теперь иди-ка ополоснись в реке, а потом займёмся посадкой деревьев." } }, f = { { 0.00, "Я по запаху понял, что ты идёшь." }, { 2.19, "Спасибо, что замарала ради нас руки, так сказать." }, { 5.95, "А теперь иди-ка ополоснись в реке, а потом займёмся посадкой деревьев." } } } } },
    [94843] = { d = 24.6, g = 1, v = "human-male", n = { m = 306, f = 307 }, c = { m = { { 0.00, "Учитывая, что ради нас ты был по локоть в кишках и навозе, будет справедливо уступить тебе и самую приятную часть работы." }, { 7.98, "Во время работы мы с ребятами собираем с деревьев семена." }, { 11.79, "Я подготовил тебе набор садовника, включающий наше с тобой удобрение, с которым ты сможешь посадить семена и вырастить новые саженцы." }, { 20.67, "Возьми его и подыщи хорошие места для посадки у рабочих мест." } }, f = { { 0.00, "Учитывая, что ради нас ты была по локоть в кишках и навозе, будет справедливо уступить тебе и самую приятную часть работы." }, { 7.99, "Во время работы мы с ребятами собираем с деревьев семена." }, { 11.80, "Я подготовил тебе набор садовника, включающий наше с тобой удобрение, с которым ты сможешь посадить семена и вырастить новые саженцы." }, { 20.68, "Возьми его и подыщи хорошие места для посадки у рабочих мест." } } }, t = { d = 5.7, g = 1, v = "human-male", n = { m = 50, f = 52 }, c = { m = { { 0.00, "Нет ничего лучше хорошего трудового дня, а?" }, { 3.67, "Молодец, что помог." } }, f = { { 0.00, "Нет ничего лучше хорошего трудового дня, а?" }, { 3.67, "Молодец, что помогла." } } } } },
    [94857] = { d = 15.9, v = "human-male", n = { x = 172 }, c = { x = { { 0.00, "Прошу, только не уходи!" }, { 1.80, "Послушай!" }, { 2.53, "Я дровосек с местной лесопилки." }, { 4.87, "Как видишь, со мной приключилась беда." }, { 7.67, "Если я отсюда не выберусь, то истеку кровью или стану обедом диких зверей." }, { 13.33, "Прошу, сходи к лесопилке за помощью!" } } }, t = { d = 1.3, v = "human-male", n = { x = 10 }, c = { x = { { 0.00, "Где мой брат?!" } } } } },
    [94858] = { d = 28.2, v = "human-male", n = { x = 267 }, c = { x = { { 0.00, "Я хотел попросить тебя ещё об одной услуге, дружище." }, { 3.77, "Когда на нас напали сектанты, я сказал всем, кто не мог сражаться, спрятаться в амбаре." }, { 9.83, "Мне казалось, там они будут в безопасности." }, { 12.90, "Я думал..." }, { 13.60, "*Голос Элбрима дрожит, когда он вспоминает случившееся.*" }, { 17.60, "Прошу, сделай ещё одно доброе дело: узнай, что стало с моей семьёй?" }, { 22.63, "Их надо похоронить здесь, но у меня не хватает духу пойти и посмотреть самому." } } }, t = { d = 15.4, v = "human-male", n = { x = 172 }, c = { x = { { 0.00, "Спасибо." }, { 0.65, "Теперь мы все обретём покой вместе." }, { 3.19, "Если ты не против, я хотел бы побыть один." }, { 6.32, "Наверняка есть и другие семьи, которые ждут таких искателей приключений, как ты." }, { 12.05, "Может, в следующий раз ты даже успеешь вовремя." } } } } },
    [94861] = { d = 16.7, v = "human-male", n = { x = 181 }, c = { x = { { 0.00, "Что ж, это объясняет, почему Кудряш не пришёл в обеденный перерыв." }, { 4.79, "Похоже, мне придётся его выручать – как и всегда." }, { 8.33, "Из-за его выходок я поседею раньше времени." }, { 11.62, "Ладно, идём." }, { 12.53, "Нам придётся спасать его самим, а времени, похоже, в обрез." } } }, t = { d = 13.8, g = 1, v = "human-male", n = { m = 142, f = 143 }, c = { m = { { 0.00, "Вот же паршивец..." }, { 1.37, "Пусть он и балбес, но работник Кудряш хороший." }, { 4.88, "Надеюсь, он поправится и наберётся ума." }, { 7.83, "Всё могло кончиться куда хуже, если бы не ты." }, { 11.33, "Спасибо, что присмотрел за ним." } }, f = { { 0.00, "Вот же паршивец..." }, { 1.37, "Пусть он и балбес, но работник Кудряш хороший." }, { 4.88, "Надеюсь, он поправится и наберётся ума." }, { 7.83, "Всё могло кончиться куда хуже, если бы не ты." }, { 11.33, "Спасибо, что присмотрела за ним." } } } } },
    [94863] = { d = 24.8, v = "human-female", n = { x = 277 }, c = { x = { { 0.00, "Ты уже знаешь всё, что нужно, о приручении вепрей, и пришло время следующего урока." }, { 6.27, "В лесу водятся куда более опасные компаньоны, и при должной осторожности ты сможешь заслужить их доверие." }, { 14.16, "Возьми хлыст приручения и разыщи серого лесного волка." }, { 18.27, "Помни: природное равновесие следует уважать." }, { 21.64, "Продемонстрируй своё умение охотника ещё раз." } } }, t = { d = 3.7, v = "human-female", n = { x = 33 }, c = { x = { { 0.00, "Прекрасно!" }, { 1.05, "Ты отлично чувствуешь зверя." } } } } },
    [94864] = { d = 25.7, g = 1, v = "human-female", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Ты показал себя, приручив вепря и волка, теперь же пробил час последнего испытания." }, { 6.14, "Равновесие в Элвиннском лесу зиждется на уважении и мастерстве." }, { 10.76, "Возьми хлыст приручения и найди молодого лесного медведя." }, { 14.98, "Покажи, что можешь заслужить доверие даже самого могучего компаньона." }, { 20.13, "Этот урок поможет тебе почувствовать более глубокую связь с животными." } }, f = { { 0.00, "Ты показала себя, приручив вепря и волка, теперь же пробил час последнего испытания." }, { 6.31, "Равновесие в Элвиннском лесу зиждется на уважении и мастерстве." }, { 11.00, "Возьми хлыст приручения и найди молодого лесного медведя." }, { 15.30, "Покажи, что можешь заслужить доверие даже самого могучего компаньона." }, { 20.53, "Этот урок поможет тебе почувствовать более глубокую связь с животными." } } }, t = { d = 4.0, g = 1, v = "human-female", n = { m = 28, f = 28 }, c = { m = { { 0.00, "Вот главная мощь леса." }, { 2.62, "А ты отважен!" } }, f = { { 0.00, "Вот главная мощь леса." }, { 2.62, "А ты отважна!" } } } } },
    [94872] = { d = 36.4, g = 1, v = "tauren-female", n = { m = 383, f = 383 }, c = { m = { { 0.00, "Безжалостное племя Маграм сейчас без сомнения выигрывает войну за территории." }, { 5.92, "Хорошо, что стычки в пустыне не происходят пока слишком уж часто, но с каждым днём их деревня к востоку отсюда растёт, как и самоуверенность их воинов." }, { 17.27, "Меня очень беспокоит, что может произойти, если клан Маграм станет слишком силён, но отрицать их потенциал как союзников я не стану." }, { 27.32, "Если хочешь, чтобы они стали тебе доверять, предложи их интенданту этот мешок тотемов." }, { 34.13, "Но будь осторожен." } }, f = { { 0.00, "Безжалостное племя Маграм сейчас без сомнения выигрывает войну за территории." }, { 6.09, "Хорошо, что стычки в пустыне не происходят пока слишком уж часто, но с каждым днём их деревня к востоку отсюда растёт, как и самоуверенность их воинов." }, { 17.78, "Меня очень беспокоит, что может произойти, если клан Маграм станет слишком силён, но отрицать их потенциал как союзников я не стану." }, { 28.12, "Если хочешь, чтобы они стали тебе доверять, предложи их интенданту этот мешок тотемов." }, { 35.13, "Но будь осторожна." } } } },
    [94873] = { d = 36.6, v = "tauren-female", n = { x = 383 }, c = { x = { { 0.00, "Любой из основных кланов кентавров может стать хорошим союзником, но я хочу предупредить тебя кое о чём." }, { 8.13, "У меня есть заслуживающие доверия данные, что в конфликте между племенами Маграм и Гелкис последнее проигрывает." }, { 16.82, "Это, конечно, может сыграть нам на руку – не исключено, что более слабый клан будет более открыт к помощи извне." }, { 25.65, "Я приготовила для тебя сумку с тотемами, которую нужно отнести их интенданту в деревню Гелкис, если он у них, конечно, есть." }, { 35.25, "Это должно помочь." } } }, t = { d = 32.2, v = "named/5398", n = { x = 208 }, c = { x = { { 0.00, "*Молкар заглядывает в мешок.*" }, { 2.24, "*На его губах появляется ухмылка и лишь на миг исчезает, когда он замечает явно поддельный тотем.*" }, { 9.96, "*Он делает вид, что не видит его.*" }, { 12.48, "Не знаю, что заставило чужака преподнести нашему клану такой дар." }, { 17.63, "Для нашего народа это великое благо – в последнее время клан Маграм свирепствует сильнее обычного." }, { 25.40, "Теперь тебе незачем осторожничать в нашей деревне." }, { 29.43, "Я сообщу Уте, а он поговорит с вождём." } } } } },
    [94877] = { d = 28.6, v = "human-male", n = { x = 318 }, c = { x = { { 0.00, "Что ты видишь вокруг?" }, { 1.57, "Разрушения и отчаяние." }, { 3.21, "Штормград бросил нас на произвол судьбы, и с каждым днём нам всё тяжелее." }, { 8.44, "Многие в этих стенах – беженцы, которые едва спаслись от гибели и потеряли семьи." }, { 14.46, "Фархолд – это тебе не Штормград, да." }, { 17.14, "Недавно Сумеречный Молот захватил поселение к северо-западу, но мы не дадим им удержать его." }, { 23.88, "Если хочешь сражаться, ступай в Светогладь и прогони этих дикарей." } } }, t = { d = 9.6, g = 1, v = "human-male", n = { x = 102 }, c = { m = { { 0.00, "Ты делаешь честь Альянсу, путник." }, { 2.39, "Будь у штормградской знати хоть вполовину твоей отваги, мы бы закончили эту войну много лет назад." } }, f = { { 0.00, "Ты делаешь честь Альянсу, путница." }, { 2.74, "Будь у штормградской знати хоть вполовину твоей отваги, мы бы закончили эту войну много лет назад." } } } } },
    [94879] = { d = 30.8, v = "human-female", n = { x = 362 }, c = { x = { { 0.00, "Знаешь про разрушенный город к северу?" }, { 2.69, "Он называется Светогладь." }, { 4.44, "Демар пытается отбить его, но у нас никак не получается." }, { 8.38, "У меня есть идея." }, { 9.63, "Если честно, Сумеречный Молот и раньше нападал на нас." }, { 13.44, "Судя по всему, их действиями управляют из какого-то штаба, и я желаю знать, где он находится." }, { 19.82, "Пока будешь заниматься своими делами, смотри в оба – вдруг найдёшь какие-то их документы." }, { 26.00, "Если наберём достаточно сведений, я попробую разгадать вражеские планы." } } }, t = { d = 13.8, v = "human-female", n = { x = 160 }, c = { x = { { 0.00, "Хорошее начало." }, { 1.15, "Но, думаю, всё это лишь указывает на добычу покрупнее." }, { 5.00, "Кстати, у Демара есть новости, которые могут нас заинтересовать." }, { 9.56, "Почему бы тебе не сбегать к нашему славному рыцарю-командору?" } } } } },
    [94881] = { d = 36.5, g = 1, v = "human-female", n = { m = 400, f = 400 }, c = { m = { { 0.00, "О, что тут у нас?" }, { 1.18, "Отважный герой пришёл спасти нас от бед?" }, { 4.08, "Как мило!" }, { 4.80, "Может, тогда и мне поможешь?" }, { 6.91, "Я бы очень хотела побольше узнать о культе, нагрянувшем в Светогладь." }, { 11.97, "Как и у любого культа, у них существуют касты." }, { 15.32, "Сектанты, обладающие склонностью к магии, зачастую пользуются большим уважением и носят амулеты, символизирующие их статус." }, { 24.27, "Сектанты наполняют эти амулеты силой, а значит, в них содержится немало магической энергии культа." }, { 31.50, "Я хочу взглянуть на них." }, { 33.28, "Будь душкой, принеси мне хотя бы парочку." } }, f = { { 0.00, "О, что тут у нас?" }, { 1.18, "Отважная героиня пришла спасти нас от бед?" }, { 4.40, "Как мило!" }, { 5.12, "Может, тогда и мне поможешь?" }, { 7.23, "Я бы очень хотела побольше узнать о культе, нагрянувшем в Светогладь." }, { 12.29, "Как и у любого культа, у них существуют касты." }, { 15.64, "Сектанты, обладающие склонностью к магии, зачастую пользуются большим уважением и носят амулеты, символизирующие их статус." }, { 24.59, "Сектанты наполняют эти амулеты силой, а значит, в них содержится немало магической энергии культа." }, { 31.82, "Я хочу взглянуть на них." }, { 33.60, "Будь душкой, принеси мне хотя бы парочку." } } }, t = { d = 6.8, g = 1, v = "human-female", n = { m = 64, f = 64 }, c = { m = { { 0.00, "Отличная работа, герой." }, { 1.86, "Я почувствовала твою силу ещё до того, как ты вошёл в крепость." } }, f = { { 0.00, "Отличная работа, героиня." }, { 2.04, "Я почувствовала твою силу ещё до того, как ты вошла в крепость." } } } } },
    [94884] = { d = 21.7, v = "human-female", n = { x = 243 }, c = { x = { { 0.00, "С меня хватит этой пещеры." }, { 2.02, "Как только расчистишь путь, я выскользну, пока враг не опомнился." }, { 6.65, "Боюсь, я слишком слаба, чтобы унести образцы." }, { 10.03, "Их энергия просто зашкаливает, а я слишком долго пробыла здесь в плену." }, { 15.18, "Как только мы выберемся отсюда, сразу же отнеси их госпоже Амберхолл." }, { 20.20, "А мне нужно отдохнуть." } } }, t = { d = 15.7, g = 1, v = "human-female", n = { m = 158, f = 160 }, c = { m = { { 0.00, "Так ты нашёл Клэр?" }, { 1.29, "Как мило." }, { 2.04, "Чутьё её не подвело, и я рада, что ты принёс это мне." }, { 5.91, "Похоже, Сумеречный Молот не ожидал такого прямого ответа." }, { 10.32, "Надо будет потом поблагодарить их за эти чудесные реагенты." } }, f = { { 0.00, "Так ты нашла Клэр?" }, { 1.78, "Как мило." }, { 2.53, "Чутьё её не подвело, и я рада, что ты принесла это мне." }, { 6.91, "Похоже, Сумеречный Молот не ожидал такого прямого ответа." }, { 11.32, "Надо будет потом поблагодарить их за эти чудесные реагенты." } } } } },
    [94885] = { d = 17.5, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Журнал содержит очень подробные записи о поступающих и уходящих из Лесоречья отрядах Сумеречного Молота." }, { 7.94, "Автора этих заметок не видно, но информация поможет разобраться в манёврах противника." }, { 14.45, "Надо показать это кому-нибудь в Фархолде." } } }, t = { d = 10.4, g = 1, v = "human-male", n = { m = 102, f = 102 }, c = { m = { { 0.00, "Боюсь, эти записи опоздали." }, { 2.31, "Мы уже прекрасно знаем, какие опасности таит Светогладь." }, { 6.92, "Куда тревожнее то, что их нашёл именно ты." } }, f = { { 0.00, "Боюсь, эти записи опоздали." }, { 2.31, "Мы уже прекрасно знаем, какие опасности таит Светогладь." }, { 6.79, "Куда тревожнее то, что их нашла именно ты." } } } } },
    [94886] = { d = 27.5, g = 1, v = "human-male", n = { m = 332, f = 334 }, c = { m = { { 0.00, "Ты здорово помог нам в Фархолде, но всё же я думаю, что от тебя будет больше пользы кое-где ещё." }, { 6.42, "Недавно пропала одна наша патрульная группа." }, { 9.50, "Они дежурили на западной границе, но, судя по тому, что выяснила Амберхолл..." }, { 14.71, "Боюсь, они забрели прямиком в центральный лагерь Сумеречного Молота." }, { 19.37, "Мы сами займёмся зачисткой Светоглади." }, { 21.91, "Если наша замечательная подруга права, пропавшему сержанту позарез нужна помощь." } }, f = { { 0.00, "Ты здорово помогла нам в Фархолде, но всё же я думаю, что от тебя будет больше пользы кое-где ещё." }, { 6.62, "Недавно пропала одна наша патрульная группа." }, { 9.70, "Они дежурили на западной границе, но, судя по тому, что выяснила Амберхолл..." }, { 14.91, "Боюсь, они забрели прямиком в центральный лагерь Сумеречного Молота." }, { 19.57, "Мы сами займёмся зачисткой Светоглади." }, { 22.11, "Если наша замечательная подруга права, пропавшему сержанту позарез нужна помощь." } } } },
    [94887] = { d = 20.6, v = "human-male", n = { x = 249 }, c = { x = { { 0.00, "Фельдмаршал Райан – один из лучших наших командиров." }, { 3.58, "Он умеет подмечать важные детали, и его надёжные данные всегда были незаменимыми." }, { 9.11, "В его последних донесениях упоминалась крепость Сумеречного Молота на западе." }, { 14.33, "Найди его, пока не поздно." }, { 16.21, "И возьми его журнал – надеюсь, это поможет тебе отыскать Райана." } } } },
    [94888] = { d = 27.0, g = 1, v = "human-male#50", n = { m = 331, f = 329 }, c = { m = { { 0.00, "Если Амберхолл так нужен этот доклад, могла бы прислать серьёзную помощь, а не только тебя одного." }, { 6.63, "Но ей не до нас, грешных." }, { 8.26, "Разведчики Сумеречного Молота перехватили всех гонцов, которых мы послали в Фархолд." }, { 13.86, "Я не могу рисковать своими бойцами, штурмуя крепость, но и пленников бросать тоже нельзя." }, { 19.89, "Хочешь, чтобы мы вернулись?" }, { 21.76, "Помоги мне спасти солдат." }, { 23.50, "Ключи от клеток найдёшь на трупах лучших бойцов секты." } }, f = { { 0.00, "Если Амберхолл так нужен этот доклад, могла бы прислать серьёзную помощь, а не только тебя одну." }, { 6.57, "Но ей не до нас, грешных." }, { 8.20, "Разведчики Сумеречного Молота перехватили всех гонцов, которых мы послали в Фархолд." }, { 13.80, "Я не могу рисковать своими бойцами, штурмуя крепость, но и пленников бросать тоже нельзя." }, { 19.83, "Хочешь, чтобы мы вернулись?" }, { 21.70, "Помоги мне спасти солдат." }, { 23.44, "Ключи от клеток найдёшь на трупах лучших бойцов секты." } } } },
    [94889] = { d = 32.3, v = "human-male#50", n = { x = 375 }, c = { x = { { 0.00, "С каждым днём Сумеречный Молот вербует всё больше сектантов, а мы до сих пор не получили вестей из Штормграда." }, { 7.49, "Рано или поздно нас сомнут." }, { 9.49, "Мне всё равно, что говорят чинуши вроде Амберхолл, я не брошу эту позицию, пока вражеская армия стоит на нашей земле и копит силы." }, { 18.67, "Если мы уйдём сейчас, то потом нам всё равно придётся иметь с ними дело – но уже на пороге нашего дома." }, { 25.85, "Раз уж тебя прислали ко мне нянькой, сделай хоть что-то полезное." }, { 30.34, "Сократи численность сектантов." } } } },
    [94890] = { d = 26.2, v = "human-male#50", n = { x = 308 }, c = { x = { { 0.00, "После такого хорошего начала нельзя останавливаться." }, { 3.69, "Спасённые нами солдаты жаждут крови, а ты настоящий таран." }, { 7.75, "Вернись в Сумеречный покров и заверши начатое." }, { 11.00, "Их главарь, орк по имени Килгар, прячется где-то в крепости, пока его прихвостни в панике и не знают, что делать." }, { 18.87, "Чтобы покончить с этим, принеси мне голову властителя Килгара." }, { 23.24, "Остальные трусы и сами ни на что не решатся." } } } },
    [94891] = { d = 17.6, v = "human-male#50", n = { x = 147 }, c = { x = { { 0.00, "Похоже, тут наступило затишье, но я на всякий случай останусь и понаблюдаю." }, { 5.71, "Хочешь доклад для Амберхолл?" }, { 7.91, "Отнеси ей вот это." }, { 9.28, "*Сержант Мракан бросает вам голову Килгара.*" }, { 12.88, "Это её успокоит." }, { 14.16, "Хотя бы на какое-то время..." }, { 16.33, "Спасибо за помощь." } } } },
    [94892] = { d = 17.1, g = 1, v = "human-male", n = { m = 122, f = 122 }, c = { m = { { 0.00, "Для меня всё кончено, незнакомец." }, { 2.70, "Я не выберусь отсюда живым." }, { 4.97, "Отнеси мой герб командиру." }, { 7.09, "Предупреди его..." }, { 8.48, "*Глаза Райана начинают стекленеть, а голос слабеет.*" }, { 13.20, "Прости." }, { 13.80, "Мне надо было вернуться домой, Эбигейл..." } }, f = { { 0.00, "Для меня всё кончено, незнакомка." }, { 3.02, "Я не выберусь отсюда живым." }, { 5.29, "Отнеси мой герб командиру." }, { 7.41, "Предупреди его..." }, { 8.80, "*Глаза Райана начинают стекленеть, а голос слабеет.*" }, { 13.52, "Прости." }, { 14.12, "Мне надо было вернуться домой, Эбигейл..." } } } },
    [94893] = { d = 25.1, v = "human-male", n = { x = 294 }, c = { x = { { 0.00, "Его последние слова были об Эбигейл?" }, { 2.57, "Я знаю, что это всё не твои дела, но всё же попрошу тебя передать новости о смерти маршала." }, { 8.81, "Суженая Райана, Эбигейл Лоусон, не приехала к нам, когда мы заложили крепость Фархолд." }, { 14.68, "Они вроде бы поссорились – я не знаю деталей, но слышал, что Эбигейл теперь живёт в Штормграде." }, { 21.10, "Передай ей герб маршала." }, { 22.75, "Вряд ли она будет рада меня видеть." } } } },
    [94894] = { d = 31.5, v = "human-male", n = { x = 379 }, c = { x = { { 0.00, "Леди Амберхолл рассказала мне о твоих подвигах в борьбе против Сумеречного Молота." }, { 5.69, "Впечатляет." }, { 6.49, "Но также и беспокоит." }, { 7.98, "Мы начали эту кампанию, чтобы наконец выдворить Орду с наших земель." }, { 12.80, "Это остаётся нашей главной целью, но действия секты тоже нельзя игнорировать." }, { 18.18, "Если в Штормграде нас так и не услышат, нам конец, мы не можем воевать на два фронта." }, { 23.93, "Но с собранными тобой доказательствами, может, они наконец снизойдут до нас." }, { 29.13, "Для нас это единственная возможность." } } } },
    [94895] = { d = 41.4, v = "narrator", n = { x = 151 }, c = { x = { { 0.00, "Сбоку на ящик прилеплена написанная от руки этикетка." }, { 4.31, "На правой её стороне изображена карта с большим красным кружком, отмечающим место на юго-восточном побережье к северу от аляповато нарисованного храма, вокруг которого можно разглядеть воду и каких-то крылатых существ, а на левой крупными буквами нанесён текст." }, { 25.07, "Собственность Фриз Искродох" }, { 27.22, "Пороховой порт" }, { 28.37, "Предупреждение: не повреждать." }, { 30.74, "Не вскрывать без присмотра." }, { 32.89, "Внизу дополнительная приписка." }, { 35.34, "В случае утери вернуть владельцу, Фриз Искродох, в Пороховой порт в Лесоречье." } } } },
    [94896] = { d = 32.8, g = 1, v = "skyborne-female", n = { m = 309, f = 313 }, c = { m = { { 0.00, "Похоже, ты способный искатель приключений." }, { 3.51, "Случайно не в Теневейный лес направляешься?" }, { 7.01, "Глубоко в лесу находится Бан'этал, и мы все его бывшие жители." }, { 12.16, "*Эалана указывает на других беженцев.*" }, { 15.52, "Нам пришлось покинуть Бан'этал, потому что он начал обрушиваться в небо." }, { 20.92, "Это случилось внезапно и посреди ночи." }, { 23.90, "Если ты направляешься туда, может, поищешь брошенные пожитки?" }, { 28.56, "Мы не можем вернуться – в лесу и в деревне слишком опасно." } }, f = { { 0.00, "Похоже, ты способная искательница приключений." }, { 3.69, "Случайно не в Теневейный лес направляешься?" }, { 7.09, "Глубоко в лесу находится Бан'этал, и мы все его бывшие жители." }, { 12.08, "*Эалана указывает на других беженцев.*" }, { 15.28, "Нам пришлось покинуть Бан'этал, потому что он начал обрушиваться в небо." }, { 20.63, "Это случилось внезапно и посреди ночи." }, { 23.58, "Если ты направляешься туда, может, поищешь брошенные пожитки?" }, { 28.20, "Мы не можем вернуться – в лесу и в деревне слишком опасно." } } }, t = { d = 13.1, g = 1, v = "skyborne-female", n = { x = 120 }, c = { m = { { 0.00, "Спасибо, герой." }, { 1.30, "Мы, беженцы, не забудем твоей доброты." }, { 4.41, "Я прослежу, чтобы эти вещи вернулись к владельцам." }, { 8.53, "Теперь у нас хотя бы будет с чего начать новую жизнь." } }, f = { { 0.00, "Спасибо, героиня." }, { 1.47, "Мы, беженцы, не забудем твоей доброты." }, { 4.65, "Я прослежу, чтобы эти вещи вернулись к владельцам." }, { 8.85, "Теперь у нас хотя бы будет с чего начать новую жизнь." } } } } },
    [94897] = { d = 29.0, v = "skyborne-female", n = { x = 278 }, c = { x = { { 0.00, "Если ты направляешься в Бан'этал, у меня есть личная просьба." }, { 5.01, "Мой любимый, Ресаан... я думаю, он навсегда меня покинул." }, { 9.73, "Он хотел вернуться за припасами, хотя я умоляла его не делать этого, и уже неделю не возвращается." }, { 17.84, "Боюсь, случилось худшее." }, { 19.90, "Прошу, если найдёшь его, приведи ко мне." }, { 23.22, "Если же он погиб, то, пожалуйста, принеси мне что-нибудь на память о нём." } } }, t = { d = 26.4, g = 1, v = "skyborne-female", n = { x = 183 }, c = { m = { { 0.00, "*Глаза Эаланы наполняются слезами.*" }, { 3.68, "О, Ресаан, любовь моя..." }, { 5.96, "Что же теперь с нами станет?" }, { 8.57, "Столько воспоминаний..." }, { 10.69, "Кажется, будто наша жизнь вдвоём только начиналась." }, { 15.33, "Спасибо, герой." }, { 16.80, "Как же жестока судьба – я лишилась и дома, и любимого." }, { 21.69, "Но теперь я хотя бы знаю, что с ним произошло." } }, f = { { 0.00, "*Глаза Эаланы наполняются слезами.*" }, { 3.68, "О, Ресаан, любовь моя..." }, { 6.02, "Что же теперь с нами станет?" }, { 8.69, "Столько воспоминаний..." }, { 10.86, "Кажется, будто наша жизнь вдвоём только начиналась." }, { 15.62, "Спасибо, героиня." }, { 17.29, "Как же жестока судьба – я лишилась и дома, и любимого." }, { 22.30, "Но теперь я хотя бы знаю, что с ним произошло." } } } } },
    [94898] = { d = 31.8, v = "skyborne-male", n = { x = 331 }, c = { x = { { 0.00, "Когда наш дом начал обрушиваться в небо той роковой ночью, было похоже, что сами стихии хотят нас поглотить." }, { 8.43, "Духи ветра являлись перед нами, пока мы уносили ноги, и нападали, сея среди беженцев ужас." }, { 15.68, "Катастрофа унесла жизни многих жителей, но ещё больше погибло из-за неудержимой ярости духов ветра." }, { 23.49, "Может, их спровоцировало обрушение, но они всё равно очень опасны." }, { 28.64, "Если сможешь, пожалуйста, подари им покой." } } } },
    [94907] = { d = 29.3, g = 1, v = "human-female", n = { m = 341, f = 343 }, c = { m = { { 0.00, "Ты очень мне помог." }, { 1.40, "Может, попросить тебя ещё об одной услуге?" }, { 4.44, "Собранные тобой реагенты так хорошо настроены на магию Сумеречного Молота, что идеально подходят для ритуала призыва." }, { 12.70, "Однако для этого их нужно отнести прямо к источнику силы культа." }, { 17.33, "Если ты найдёшь проводник, расхаживая по Сумеречному покрову, попробуй призвать одного из рабов культа и пленить его с помощью этого камня души." }, { 27.55, "Для допроса, конечно же." } }, f = { { 0.00, "Ты очень мне помогла." }, { 1.62, "Может, попросить тебя ещё об одной услуге?" }, { 4.66, "Собранные тобой реагенты так хорошо настроены на магию Сумеречного Молота, что идеально подходят для ритуала призыва." }, { 12.92, "Однако для этого их нужно отнести прямо к источнику силы культа." }, { 17.55, "Если ты найдёшь проводник, расхаживая по Сумеречному покрову, попробуй призвать одного из рабов культа и пленить его с помощью этого камня души." }, { 27.77, "Для допроса, конечно же." } } } },
    [94911] = { d = 34.2, g = 1, v = "tauren-male", n = { m = 308, f = 308 }, c = { m = { { 0.00, "Привет, юный герой." }, { 1.80, "Вижу, ты подаёшь большие надежды как друид." }, { 5.55, "В Громовом Утёсе живёт таурен по имени Тюрак Рунический Тотем, вам стоит поговорить." }, { 12.81, "Он покажет тебе, как попасть в святилище Круга Кенария на Калимдоре, на Лунную поляну." }, { 20.31, "Друиды Круга будут рады поделиться с тобой знаниями." }, { 25.00, "Как говорят на вашем острове, ступай с благословением ветра, мой юный друг." }, { 31.48, "Удачи в приключениях." } }, f = { { 0.00, "Привет, юная героиня." }, { 2.00, "Вижу, ты подаёшь большие надежды как друид." }, { 5.84, "В Громовом Утёсе живёт таурен по имени Тюрак Рунический Тотем, вам стоит поговорить." }, { 13.28, "Он покажет тебе, как попасть в святилище Круга Кенария на Калимдоре, на Лунную поляну." }, { 20.96, "Друиды Круга будут рады поделиться с тобой знаниями." }, { 25.76, "Как говорят на вашем острове, ступай с благословением ветра, мой юный друг." }, { 32.40, "Удачи в приключениях." } } }, t = { d = 24.9, g = 1, v = "tauren-male#67", n = { m = 234, f = 242 }, c = { m = { { 0.00, "Высший эльф в Громовом Утёсе, подходит и обращается ко мне как ни в чём ни бывало." }, { 6.66, "Вот чудеса!" }, { 7.65, "Ну что же, Ваятель ветра, позволь мне присоединиться к моим братьям и сёстрам из Круга Кенария и тоже поприветствовать тебя на Азероте." }, { 18.85, "Мои друзья-друиды могут многому тебя научить, дитя природы." } }, f = { { 0.00, "Высшая эльфийка в Громовом Утёсе, подходит и обращается ко мне как ни в чём ни бывало." }, { 7.12, "Вот чудеса!" }, { 8.12, "Ну что же, Ваятельница ветра, позволь мне присоединиться к моим братьям и сёстрам из Круга Кенария и тоже поприветствовать тебя на Азероте." }, { 19.75, "Мои друзья-друиды могут многому тебя научить, дитя природы." } } } } },
    [94912] = { d = 24.7, g = 1, v = "nightelf-female", n = { m = 282, f = 283 }, c = { m = { { 0.00, "Привет, молодой герой." }, { 1.60, "Ты слышал про Круг Кенария?" }, { 3.45, "Вряд ли." }, { 4.01, "Это древний орден служителей природы, практикующих искусство друидов, как и ты." }, { 9.43, "В Штормграде живёт ночной эльф по имени Шельдрас Лунное Древо." }, { 13.68, "Он расскажет тебе, как попасть на Лунную поляну – святилище Круга Кенария на Калимдоре." }, { 19.66, "Иди." }, { 20.03, "Если ты хочешь спасти свой дом, тебе надо многому научиться." } }, f = { { 0.00, "Привет, молодая героиня." }, { 1.76, "Ты слышала про Круг Кенария?" }, { 3.70, "Вряд ли." }, { 4.27, "Это древний орден служителей природы, практикующих искусство друидов, как и ты." }, { 9.79, "В Штормграде живёт ночной эльф по имени Шельдрас Лунное Древо." }, { 14.13, "Он расскажет тебе, как попасть на Лунную поляну – святилище Круга Кенария на Калимдоре." }, { 20.22, "Иди." }, { 20.59, "Если ты хочешь спасти свой дом, тебе надо многому научиться." } } }, npc = { [2543] = { d = 26.3, g = 1, v = "human-male", n = { m = 282, f = 283 }, c = { m = { { 0.00, "Привет, молодой герой." }, { 1.68, "Ты слышал про Круг Кенария?" }, { 3.61, "Вряд ли." }, { 4.19, "Это древний орден служителей природы, практикующих искусство друидов, как и ты." }, { 9.87, "В Штормграде живёт ночной эльф по имени Шельдрас Лунное Древо." }, { 14.32, "Он расскажет тебе, как попасть на Лунную поляну – святилище Круга Кенария на Калимдоре." }, { 20.57, "Иди." }, { 20.96, "Если ты хочешь спасти свой дом, тебе надо многому научиться." } }, f = { { 0.00, "Привет, молодая героиня." }, { 2.17, "Ты слышала про Круг Кенария?" }, { 4.68, "Вряд ли." }, { 5.26, "Это древний орден служителей природы, практикующих искусство друидов, как и ты." }, { 10.94, "В Штормграде живёт ночной эльф по имени Шельдрас Лунное Древо." }, { 15.39, "Он расскажет тебе, как попасть на Лунную поляну – святилище Круга Кенария на Калимдоре." }, { 21.64, "Иди." }, { 22.0