    [94913] = { d = 42.8, v = "tauren-male#67", n = { x = 402 }, c = { x = { { 0.00, "На священной земле Лунной поляны рады всем друидам." }, { 4.59, "Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погружёнными в спячку друидами." }, { 13.53, "Я научу тебя заклинанию, которое позволит тебе переноситься на Лунную поляну." }, { 20.41, "Пользуйся им, когда захочешь приобщиться знаниям или насладиться покоем." }, { 26.82, "Вот первый урок здесь, на Азероте, – отправляйся на Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной Гавани о том пути, которым ты ныне следуешь." }, { 40.43, "Удачи тебе, мой юный друид." } } }, t = { d = 8.6, g = 1, v = "nightelf-male#54", n = { m = 58, f = 59 }, c = { m = { { 0.00, "А, вижу, ты уже освоил облик медведя." }, { 3.80, "Хорошо, хорошо." }, { 5.39, "Ты на верном пути, юный герой." } }, f = { { 0.00, "А, вижу, ты уже освоила облик медведя." }, { 3.92, "Хорошо, хорошо." }, { 5.52, "Ты на верном пути, юная героиня." } } } } },
    [94914] = { d = 38.6, v = "nightelf-male", n = { x = 402 }, c = { x = { { 0.00, "На священной земле Лунной поляны рады всем друидам." }, { 4.13, "Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погружёнными в спячку друидами." }, { 12.17, "Я научу тебя заклинанию, которое позволит тебе переноситься на Лунную поляну." }, { 18.36, "Пользуйся им, когда захочешь приобщиться знаниям или насладиться покоем." }, { 24.12, "Вот первый урок здесь, на Азероте, – отправляйся на Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной Гавани о том пути, которым ты ныне следуешь." }, { 36.35, "Удачи тебе, мой юный друид." } } }, t = { d = 8.6, g = 1, v = "nightelf-male#54", n = { m = 63, f = 64 }, c = { m = { { 0.00, "Вижу, ты уже освоил форму медведя." }, { 3.23, "Чудесно, чудесно." }, { 4.85, "Ты быстро учишься, молодой герой." } }, f = { { 0.00, "Вижу, ты уже освоила форму медведя." }, { 3.54, "Чудесно, чудесно." }, { 5.27, "Ты быстро учишься, молодая героиня." } } } } },
    [94923] = { d = 27.0, v = "child-male", n = { x = 232 }, c = { x = { { 0.00, "*Робби наклоняется, обращаясь к вам, словно хочет поделиться страшной тайной.*" }, { 6.16, "Послушай, мне нужна помощь!" }, { 8.13, "Сестра подарила шляпу на день рождения, а я потерял её, когда играл у реки." }, { 13.46, "Мне нельзя туда ходить из-за мурлоков, поэтому я не могу попросить папу или Элли, иначе они узнают, что я там был!" }, { 21.65, "Это отличная шляпа, наверняка кто-то из мурлоков подобрал её и оставил себе!" } } }, t = { d = 6.9, g = 1, v = "child-male", n = { m = 52, f = 52 }, c = { m = { { 0.00, "Моя шляпа!" }, { 1.16, "Ой, спасибо, спасибо, спасибо, дяденька!" }, { 5.19, "Ты самый лучший!" } }, f = { { 0.00, "Моя шляпа!" }, { 1.21, "Ой, спасибо, спасибо, спасибо, тётенька!" }, { 5.29, "Ты самая лучшая!" } } } } },
    [94924] = { d = 20.6, v = "human-male", n = { x = 222 }, c = { x = { { 0.00, "Орки-браконьеры – на редкость кровожадные твари." }, { 3.65, "Они убивают всё, что движется: людей, львов и даже лошадей." }, { 8.12, "Они представляют угрозу для всей жизни в Лесоречье, и их необходимо остановить." }, { 14.01, "Они бродят по равнинам группами, как стаи диких зверей." }, { 18.27, "Если увидишь их, сразу истреби." } } }, t = { d = 9.8, g = 1, v = "human-male", n = { m = 109, f = 110 }, c = { m = { { 0.00, "Немало ты их перебил, а?" }, { 1.71, "Пожалуй, ты не такой уж мягкотелый, как мне сперва показалось." }, { 6.00, "Надеюсь, канюки уже пируют на трупах этих дикарей." } }, f = { { 0.00, "Немало ты их перебила, а?" }, { 1.80, "Пожалуй, ты не такая уж мягкотелая, как мне сперва показалось." }, { 6.17, "Надеюсь, канюки уже пируют на трупах этих дикарей." } } } } },
    [94925] = { d = 27.4, v = "human-male", n = { x = 336 }, c = { x = { { 0.00, "Фархолд гордится своей независимостью, но некоторые вещи мы можем получить только посредством торговли." }, { 7.04, "У нас есть договор с одной торговкой в Пороховом порту." }, { 10.78, "Мы поставляем ей товары, которые опасно добыть, а она поставляет нам особые боеприпасы." }, { 16.72, "Сейчас она закупает львиный мех." }, { 18.99, "На вершине большого холма в центре равнины живёт целый прайд." }, { 23.15, "Если хочешь сделать что-то полезное, добудь мне несколько шкур." } } }, t = { d = 5.0, v = "human-male", n = { x = 46 }, c = { x = { { 0.00, "Да, эти отлично подойдут." }, { 2.25, "Давай я их упакую, а ты доставишь." } } } } },
    [94926] = { d = 18.3, v = "narrator", n = { x = 182 }, c = { x = { { 0.00, "Как и всё оружие огров, этот молот большой, неудобный и покрыт вмятинами от ударов." }, { 6.82, "Существо другой расы вряд ли могло бы им сражаться." }, { 11.00, "Для вас это не более чем трофей, но в Фархолде наверняка будут рады узнать о смерти Комука." } } } },
    [94927] = { d = 20.7, g = 1, v = "human-male", n = { m = 241, f = 242 }, c = { m = { { 0.00, "Когда будешь готов, я отопру оковы, и мы начнём наш побег." }, { 4.00, "Пойдём по кратчайшему пути, прямо через центр лагеря." }, { 7.63, "Жди стычек с ограми." }, { 9.04, "Когда выберемся, я вернусь в Фархолд за медицинской помощью." }, { 13.17, "Окажи последнюю услугу: передай Корнелию, где я." }, { 16.49, "Сейчас мне меньше всего хочется выслушивать его упрёки." } }, f = { { 0.00, "Когда будешь готова, я отопру оковы, и мы начнём наш побег." }, { 4.55, "Пойдём по кратчайшему пути, прямо через центр лагеря." }, { 8.18, "Жди стычек с ограми." }, { 9.59, "Когда выберемся, я вернусь в Фархолд за медицинской помощью." }, { 13.72, "Окажи последнюю услугу: передай Корнелию, где я." }, { 17.04, "Сейчас мне меньше всего хочется выслушивать его упрёки." } } }, t = { d = 11.8, v = "human-male", n = { x = 129 }, c = { x = { { 0.00, "Данстон вернулся в Фархолд?" }, { 2.04, "Наконец-то!" }, { 2.89, "В следующий раз, как увижу его, выпивка за его счёт." }, { 6.71, "Спасибо за помощь." }, { 8.09, "Может, скоро я наконец посплю на настоящей кровати." } } } } },
    [94928] = { d = 15.4, v = "human-male", n = { x = 184 }, c = { x = { { 0.00, "Эти шкуры надо доставить в Пороховой порт." }, { 2.92, "Это гоблинский порт на северо-востоке." }, { 5.53, "Когда доберёшься туда, передай эти шкуры Фриз Искродох." }, { 9.30, "Скажи, что они от Корнелия." }, { 11.18, "Мы уже согласовали все детали, так что она поймёт, для чего они." } } }, t = { d = 13.8, v = "goblin-female", n = { x = 116 }, c = { x = { { 0.00, "Корнелий больше сам их не возит?" }, { 2.57, "Вот и славно!" }, { 3.64, "Терпеть не могла этого типа." }, { 5.92, "*Фриз осматривает содержимое свёртка.*" }, { 9.04, "Выглядит неплохо." }, { 10.30, "Передай своим в Фархолде, пусть и дальше присылают." } } } } },
    [94929] = { d = 38.0, v = "human-male", n = { x = 434 }, c = { x = { { 0.00, "Знаю, знаю, я злоупотребляю твоим терпением, но, клянусь, я бы не просил, не будь это важно." }, { 6.51, "Речь идёт об очень срочном грузе" }, { 8.80, "В крепости в Лесоречье живёт один мой знакомый." }, { 12.12, "Чтобы туда добраться, ступай на северо-восток через болота – избегай опасных существ, которые там обитают." }, { 19.77, "Вдоль северо-восточного холма проходит старая тропа." }, { 23.54, "Отправляйся по ней через холмы, а когда дойдёшь до развилки, держись севера, а затем сверни на восток." }, { 30.74, "Оттуда до крепости Фархолд, что на восточном побережье, будет уже рукой подать." }, { 36.42, "Спасибо тебе за помощь." } } } },
    [94930] = { d = 42.3, v = "narrator", n = { x = 151 }, c = { x = { { 0.00, "Сбоку на ящик прилеплена написанная от руки этикетка." }, { 4.41, "На правой её стороне изображена карта с большим красным кружком, отмечающим место на юго-восточном побережье к северу от аляповато нарисованного храма, вокруг которого можно разглядеть воду и каких-то крылатых существ, а на левой крупными буквами нанесён текст." }, { 25.65, "Собственность Фриз Искродох" }, { 27.85, "Пороховой порт" }, { 29.03, "Предупреждение: не повреждать." }, { 31.45, "Не вскрывать без присмотра." }, { 33.66, "Внизу дополнительная приписка." }, { 36.15, "В случае утери вернуть владельцу, Фриз Искродох, в Пороховой порт в Лесоречье." } } } },
    [94931] = { d = 23.6, v = "human-male", n = { x = 294 }, c = { x = { { 0.00, "Парни из Южного дозора по большей части неплохо сдерживают гноллов." }, { 4.51, "Но один-два мерзавца нет-нет да пробираются ночью в лагерь и устраивают бедлам." }, { 9.73, "Особенно им нравится воровать пилы – видимо, чтобы сделать оружие из острого железа." }, { 15.37, "Ты нам очень поможешь, если вернёшь хотя бы часть." }, { 18.64, "Скорее всего, гноллы спрятали их где-нибудь в своём лагере в западных холмах." } } }, t = { d = 3.9, v = "human-male", n = { x = 39 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.38, "Может, мне нанять тебя в охрану?" } } } } },
    [94946] = { d = 30.3, g = 1, v = "skyborne-male", n = { m = 339, f = 340 }, c = { m = { { 0.00, "Я намеревался первым ступить на земли Азерота, но недавние события, связанные с культом, всё меняют." }, { 7.26, "Пока мне придётся остаться в Валанааре." }, { 10.08, "Но не беспокойся: в Даларане прибытия нашего народа уже ожидают несколько наших магов." }, { 16.43, "Советую начать исследовать Азерот, пока мы улаживаем дела на острове." }, { 21.53, "Тебя призовут, когда понадобится помощь." }, { 24.54, "Как будешь готов отправляться, иди на ближний причал и садись на неборез." } }, f = { { 0.00, "Я намеревался первым ступить на земли Азерота, но недавние события, связанные с культом, всё меняют." }, { 7.26, "Пока мне придётся остаться в Валанааре." }, { 10.08, "Но не беспокойся: в Даларане прибытия нашего народа уже ожидают несколько наших магов." }, { 16.43, "Советую начать исследовать Азерот, пока мы улаживаем дела на острове." }, { 21.53, "Тебя призовут, когда понадобится помощь." }, { 24.54, "Как будешь готова отправляться, иди на ближний причал и садись на неборез." } } }, t = { d = 19.6, v = "skyborne-male", n = { x = 206 }, c = { x = { { 0.00, "А, вот и ты." }, { 0.92, "Чудесно." }, { 1.63, "Нам ещё нужно тут обустроиться, так что у тебя есть время всё здесь осмотреть." }, { 7.60, "Но постарайся не отходить от города." }, { 10.44, "Эти новые земли кажутся безмятежными, но выходить за пределы Даларана без должной подготовки может быть очень опасно." } } } } },
    [94947] = { d = 38.5, g = 1, v = "skyborne-male", n = { m = 444, f = 445 }, c = { m = { { 0.00, "Мир под облаками очень велик, и наш народ должен исследовать его просторы." }, { 5.44, "Этим ты и займёшься." }, { 6.89, "Орден Кирин-Тор входит в так называемый Альянс народов-единомышленников." }, { 12.13, "Фактическим сердцем этого союза является город Штормград на юге отсюда." }, { 17.44, "Элаадрин попросил меня подыскать представителя нашего народа, который смог бы отправиться в этот город и встретиться с его лордом-регентом, человеком по имени Болвар Фордрагон." }, { 30.30, "Когда будешь готов, воспользуйся порталом в Штормград." }, { 34.30, "Маги Кирин-Тора создали его специально для Высшего ордена." } }, f = { { 0.00, "Мир под облаками очень велик, и наш народ должен исследовать его просторы." }, { 5.41, "Этим ты и займёшься." }, { 6.85, "Орден Кирин-Тор входит в так называемый Альянс народов-единомышленников." }, { 12.06, "Фактическим сердцем этого союза является город Штормград на юге отсюда." }, { 17.34, "Элаадрин попросил меня подыскать представителя нашего народа, который смог бы отправиться в этот город и встретиться с его лордом-регентом, человеком по имени Болвар Фордрагон." }, { 30.12, "Когда будешь готова, воспользуйся порталом в Штормград." }, { 34.16, "Маги Кирин-Тора создали его специально для Высшего ордена." } } }, t = { d = 35.3, g = 1, v = "creature/bolvar", n = { m = 352, f = 352 }, c = { m = { { 0.00, "Приветствую тебя, герой." }, { 2.08, "Я Болвар Фордрагон, регент королевства Штормград." }, { 6.17, "Посланник Кирин-Тора предупредил, что скоро прибудет эмиссар Высшего ордена, и вот ты здесь." }, { 13.67, "В этот тронный зал давно не ступала нога высшего эльфа, но я с радостью приму тебя как гостя." }, { 21.47, "От имени нашего короля сердечно приветствую тебя в Штормграде." }, { 26.67, "Отныне тебе разрешено свободно перемещаться по землям Альянса." }, { 31.87, "Добро пожаловать в Азерот, небеснорождённый." } }, f = { { 0.00, "Приветствую тебя, героиня." }, { 2.17, "Я Болвар Фордрагон, регент королевства Штормград." }, { 6.16, "Посланник Кирин-Тора предупредил, что скоро прибудет эмиссар Высшего ордена, и вот ты здесь." }, { 13.48, "В этот тронный зал давно не ступала нога высшего эльфа, но я с радостью приму тебя как гостя." }, { 21.09, "От имени нашего короля сердечно приветствую тебя в Штормграде." }, { 26.16, "Отныне тебе разрешено свободно перемещаться по землям Альянса." }, { 31.23, "Добро пожаловать в Азерот, небеснорождённая." } } } } },
    [94961] = { d = 13.3, g = 1, v = "creature/gnoll", n = { x = 59 }, c = { m = { { 0.00, "*Гнолл достаёт из кармана кусочек золота и показывает его вам.*" }, { 4.80, "Путник, давай меняться!" }, { 7.26, "У меня есть ещё, в другом месте." }, { 10.54, "Помоги отомстить, и покажу!" } }, f = { { 0.00, "*Гнолл достаёт из кармана кусочек золота и показывает его вам.*" }, { 4.80, "Путница, давай меняться!" }, { 7.35, "У меня есть ещё, в другом месте." }, { 10.63, "Помоги отомстить, и покажу!" } } }, t = { d = 6.7, v = "creature/gnoll", n = { x = 51 }, c = { x = { { 0.00, "Да-да, очень хорошо!" }, { 2.24, "Теперь мы уходить отсюда и идти к сокровищу." } } } } },
    [94962] = { d = 17.3, v = "goblin-male", n = { x = 171 }, c = { x = { { 0.00, "Ладно, ладно." }, { 1.14, "Допустим, тебе удалось одержать пару побед." }, { 4.70, "Ну и что с того?" }, { 5.98, "До чемпиона тебе ещё далеко, дружище." }, { 8.96, "Давай знаешь как... устрою тебе такой бой, чтобы точно все надолго запомнили." }, { 15.15, "Надеюсь, ты любишь сюрпризы." } } } },
    [94963] = { d = 12.4, g = 1, v = "creature/gnoll", n = { x = 95 }, c = { m = { { 0.00, "Идём, герой." }, { 1.18, "Пора уходить отсюда." }, { 3.19, "А если кто захочет помешать, порвём на куски!" }, { 7.39, "Когда будет безопасно, я отведу тебя к награде." } }, f = { { 0.00, "Идём, героиня." }, { 1.83, "Пора уходить отсюда." }, { 3.84, "А если кто захочет помешать, порвём на куски!" }, { 8.04, "Когда будет безопасно, я отведу тебя к награде." } } }, t = { d = 8.3, v = "creature/gnoll", n = { x = 0 }, c = { x = { { 0.00, "*Похоже, Фаззл скопил немалую сумму — по крайней мере, по меркам гноллов.*" }, { 6.13, "*Теперь, кажется, она твоя.*" } } } } },
    [94964] = { d = 8.3, v = "goblin-male", n = { x = 83 }, c = { x = { { 0.00, "Продолжаем развлекать публику." }, { 2.60, "Следующий противник – серьёзный тип." }, { 5.57, "Желаю удачи." }, { 6.72, "Может, ещё свидимся." } } } },
    [94965] = { d = 32.4, v = "goblin-male", n = { x = 339 }, c = { x = { { 0.00, "Ладно, я положу лакомство, а ты выходи на ринг и готовься – будет жарко." }, { 5.44, "Что?" }, { 5.78, "Чего так смотришь?" }, { 7.20, "Я же сказал – мы её покормим." }, { 9.38, "Правда, забыл уточнить, что при виде любимого лакомства Нюхля может здорово разойтись." }, { 15.97, "Тебе, конечно, не позавидуешь, дружище." }, { 18.96, "С одной стороны, важно доказать нашим друзьям-ограм, что ты не робкого десятка." }, { 25.01, "С другой, я бы сто раз подумал, прежде чем делать больно любимому питомцу Чух'чоха." }, { 31.26, "Ну ладно, давай." } } } },
    [94968] = { d = 27.8, v = "orc-male#60", n = { x = 325 }, c = { x = { { 0.00, "Из тех немногих, кому удалось проникнуть в пещеру, большинство погибло." }, { 5.13, "Похоже, численность Сумеречного Молота здесь гораздо больше, чем мы думали." }, { 10.52, "Мы не будем стоять в стороне, пока сектанты разоряют эти земли и используют наших союзников для своих жертвоприношений." }, { 19.15, "Мы немедленно покончим с этим." }, { 21.36, "Проникни в крепость, уничтожь силы противника и принеси мне доказательства гибели их лидера." } } } },
    [94969] = { d = 8.9, v = "human-male", n = { x = 90 }, c = { x = { { 0.00, "Не спрашивай." }, { 1.04, "Если расскажу — не поверишь." }, { 3.26, "Давай лучше подумаем, как вытащить меня отсюда!" }, { 7.02, "Ну, и тебя тоже, конечно." } } } },
    [94971] = { d = 25.7, v = "scourge-female", n = { x = 227 }, c = { x = { { 0.00, "У каждого паладина непременно должен быть боевой скакун." }, { 5.30, "Эти особые освящённые кони несут вооружённых всадников в гущу боя, а по отваге они не уступают даже самому смелому паладину." }, { 17.00, "Мы изменились, но только не в этом." }, { 20.29, "Пришла пора тебе тоже обзавестись верным боевым скакуном." } } } },
    [94972] = { d = 19.4, v = "orc-male", n = { x = 214 }, c = { x = { { 0.00, "В этой обнаруженной нами крепости наверняка хранятся секреты, недоступные простым сектантам, встречавшимся нам ранее." }, { 9.00, "Будет разумно добыть там информацию, которая поможет в борьбе с этим врагом." }, { 14.95, "Принеси мне всё, что найдёшь." }, { 17.10, "Я буду ждать твоего возвращения." } } } },
    [94973] = { d = 2.9, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Похоже, это форма для ключа." } } } },
    [94974] = { d = 13.0, v = "orc-female#124", n = { x = 141 }, c = { x = { { 0.00, "Форма грубая и стёртая, но, может, у нас получится отлить по ней ключ." }, { 5.10, "На сбор нужных компонентов может уйти время." }, { 8.46, "Я буду поддерживать жар в углях, пока ты собираешь материалы." } } } },
    [94975] = { d = 35.1, v = "orc-male#60", n = { x = 381 }, c = { x = { { 0.00, "Наша работа здесь ещё не закончена." }, { 2.75, "Сектанты причинили нашим союзникам неописуемые страдания и подготовили эти земли к вторжению." }, { 10.09, "Мы больше не собираемся терпеть их злодеяния." }, { 13.61, "К северу отсюда находится скрытая система пещер, которую трудно обнаружить на пересечённой местности." }, { 21.52, "Наши разведчики видели там сектантов, двигающихся под покровом тьмы." }, { 26.81, "Найди эту пещеру, доберись до скрывающихся в ней сектантов и преподай им урок, который они нескоро забудут." } } } },
    [94978] = { d = 26.6, v = "skyborne-male", n = { x = 280 }, c = { x = { { 0.00, "Каждому охотнику нужен верный питомец, любящий своего хозяина." }, { 5.03, "Это будет твоё первое испытание." }, { 7.65, "Когда-нибудь ты станешь приручать зверей со всех концов света, но пока начни на реках и озёрах Зефриса." }, { 15.73, "Возьми этот хлыст приручения и найди ползуна Песни Ветра." }, { 20.33, "Покажи, что умеешь дрессировать зверей, и начни свой путь к настоящему мастерству." } } }, t = { d = 4.8, g = 1, v = "skyborne-male", n = { m = 44, f = 45 }, c = { m = { { 0.00, "Ты приручил своего первого зверя!" }, { 2.94, "Дальше будет проще." } }, f = { { 0.00, "Ты приручила своего первого зверя!" }, { 3.12, "Дальше будет проще." } } } } },
    [94979] = { d = 25.7, g = 1, v = "skyborne-male", n = { m = 266, f = 268 }, c = { m = { { 0.00, "Ты показал, что способен приручить речного ползуна, теперь испытаем твои умения на равнине." }, { 7.25, "Поля Зефриса оглашают крики буреногов – гордых крылатых охотников, бегущих со скоростью ветра." }, { 14.78, "Возьми хлыст приручения, ступай в низину и отыщи буренога." }, { 19.40, "Заслужи его доверие и приручи." }, { 21.89, "Докажи, что ты готов к предстоящим испытаниям." } }, f = { { 0.00, "Ты показала, что способна приручить речного ползуна, теперь испытаем твои умения на равнине." }, { 7.37, "Поля Зефриса оглашают крики буреногов – гордых крылатых охотников, бегущих со скоростью ветра." }, { 14.96, "Возьми хлыст приручения, ступай в низину и отыщи буренога." }, { 19.61, "Заслужи его доверие и приручи." }, { 22.11, "Докажи, что ты готова к предстоящим испытаниям." } } }, t = { d = 2.3, v = "skyborne-male", n = { x = 19 }, c = { x = { { 0.00, "Так быстро?" }, { 1.25, "Впечатляет!" } } } } },
    [94980] = { d = 3.0, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Похоже, это форма для ключа." } } } },
    [94981] = { d = 9.9, v = "human-male", n = { x = 118 }, c = { x = { { 0.00, "Форма довольно грубая, но с нужными материалами, может, и удастся отлить ключ." }, { 5.44, "Я буду поддерживать жар в углях, пока ты собираешь всё необходимое." } } } },
    [94982] = { d = 35.2, v = "human-male", n = { x = 439 }, c = { x = { { 0.00, "Наши разведчики упоминали о пещерах в горах на северо-западе, вход в которые скрыт за естественными элементами ландшафта." }, { 8.06, "Большинство тех, кто отправился исследовать пещеры, пока не вернулись." }, { 12.73, "Боюсь, они могли заблудиться." }, { 14.79, "Дозорные также отмечают присутствие сил Сумеречного Молота, которые то покидают пещеры, то снова спускаются под землю, часто под покровом тьмы." }, { 24.37, "Найди их оплот." }, { 25.46, "Если мои предположения верны, то нам нужно устранить их предводителя." }, { 30.13, "Только тогда мы сможем продолжить борьбу и изгнать сектантов из этих земель." } } } },
    [94983] = { d = 35.0, v = "human-male#50", n = { x = 426 }, c = { x = { { 0.00, "Наши разведчики делятся поистине ужасными рассказами." }, { 3.72, "Избавлю тебя от жутких подробностей, но то, что мы обнаружили, подтверждает предыдущие сообщения об убежище культистов." }, { 11.77, "К северу находится пещера, вход в которую хорошо замаскирован." }, { 16.04, "Она ведёт в... ну, туда, куда нам ещё предстоит проникнуть." }, { 20.07, "Мы считаем, что это вражеский плацдарм, спрятанный в глубине гор." }, { 24.53, "Пришло время отплатить сектантам за их нападения на наших союзников." }, { 29.24, "Отправляйся на север, найди там врагов, перебей и вернись с доказательствами их гибели." } } } },
    [94984] = { d = 38.4, g = 1, v = "human-female", n = { m = 448, f = 448 }, c = { m = { { 0.00, "Как бы мы ни старались, справиться с силами Сумеречного Молота не удаётся." }, { 4.98, "Мы пришли к выводу, что они, должно быть, прибывают откуда-то ещё." }, { 9.52, "Благодаря новому питомцу, с которым ты ко мне пришёл, мне удалось учтиво поинтересоваться у нашего дорогого сумеречного раба, не знает ли он что-нибудь о том, откуда пришли его прежние хозяева." }, { 22.70, "Примечательно упоминание о магии теней и огре по имени Нар'гурк в тайной крепости к северу от Светоглади." }, { 29.98, "Найди его, убей и добудь любые сведения, какие только сможешь." }, { 34.45, "Не может быть так, чтобы мы не узнали ничего нового." } }, f = { { 0.00, "Как бы мы ни старались, справиться с силами Сумеречного Молота не удаётся." }, { 4.98, "Мы пришли к выводу, что они, должно быть, прибывают откуда-то ещё." }, { 9.52, "Благодаря новому питомцу, с которым ты ко мне пришла, мне удалось учтиво поинтересоваться у нашего дорогого сумеречного раба, не знает ли он что-нибудь о том, откуда пришли его прежние хозяева." }, { 23.22, "Примечательно упоминание о магии теней и огре по имени Нар'гурк в тайной крепости к северу от Светоглади." }, { 30.50, "Найди его, убей и добудь любые сведения, какие только сможешь." }, { 34.97, "Не может быть так, чтобы мы не узнали ничего нового." } } } },
    [94992] = { d = 6.5, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Лошадь склоняет голову и тычется носом вам под мышку." }, { 4.23, "Она готова следовать за вами." } } }, t = { d = 17.1, g = 1, v = "human-male", n = { m = 181, f = 186 }, c = { m = { { 0.00, "Спасибо, что спас мою Печеньку!" }, { 2.20, "Ты настоящий друг." }, { 3.45, "Грустно, конечно, что она пока побудет одна, но, надеюсь, скоро мы отыщем и других лошадок из её конюшни." }, { 10.85, "Как увидишь старину Демара, передай ему, что Усадьба Вилера снова в деле!" } }, f = { { 0.00, "Спасибо, что спасла мою Печеньку!" }, { 2.65, "Ты настоящая подруга." }, { 4.61, "Грустно, конечно, что она пока побудет одна, но, надеюсь, скоро мы отыщем и других лошадок из её конюшни." }, { 12.01, "Как увидишь старину Демара, передай ему, что Усадьба Вилера снова в деле!" } } } } },
    [94997] = { d = 15.6, v = "human-male#50", n = { x = 181 }, c = { x = { { 0.00, "Медлить нельзя." }, { 1.15, "Немедленно отнеси это в крепость." }, { 3.57, "Найди Эш Амберхолл." }, { 4.97, "Характер у неё тот ещё, но в своей области она пользуется большим уважением." }, { 10.33, "Может быть, она прольёт свет на то, какая энергия заключена в этих предметах." } } } },
    [94998] = { d = 29.8, g = 1, v = "human-female", n = { m = 298, f = 299 }, c = { m = { { 0.00, "Развеять было совсем несложно." }, { 2.38, "Это остатки чего-то, это уж точно." }, { 5.10, "А чего именно — не знаю." }, { 7.00, "Что ж, боюсь, больше тут ничего не поделаешь." }, { 10.40, "Прости, если ты ждал от меня большего, но... хотя, если подумать, работа у этих вещиц весьма необычная." }, { 18.28, "Может, они на что-нибудь и сгодятся." }, { 21.07, "Отнеси их Мелани Сейбл." }, { 22.84, "Скажи, что ты от меня." }, { 24.53, "И передай, что они безопасны." }, { 26.78, "Возможно, она найдёт им применение." } }, f = { { 0.00, "Развеять было совсем несложно." }, { 2.38, "Это остатки чего-то, это уж точно." }, { 5.10, "А чего именно — не знаю." }, { 7.00, "Что ж, боюсь, больше тут ничего не поделаешь." }, { 10.40, "Прости, если ты ждала от меня большего, но... хотя, если подумать, работа у этих вещиц весьма необычная." }, { 18.81, "Может, они на что-нибудь и сгодятся." }, { 21.60, "Отнеси их Мелани Сейбл." }, { 23.37, "Скажи, что ты от меня." }, { 25.06, "И передай, что они безопасны." }, { 27.31, "Возможно, она найдёт им применение." } } } },
    [94999] = { d = 30.9, g = 1, v = "human-female", n = { m = 342, f = 343 }, c = { m = { { 0.00, "О!" }, { 0.19, "Прости, я тебя не заметила." }, { 2.11, "Я собираю кое-какие вещички для моего друга." }, { 5.28, "Ну или... скорее, приятеля." }, { 7.20, "Ты не знаком с дозорным Фредериксом?" }, { 9.68, "Он из Южного дозора – это к западу отсюда, совсем недалеко." }, { 13.84, "Иногда он бывает тут, когда они патрулируют наши края, и я хотела вручить ему небольшой презент, чтобы показать, как я это ценю." }, { 22.84, "Я бы отнесла его сама, но надо присматривать за братиком, да и на ферме столько дел..." }, { 28.74, "Надеюсь, ты всё понимаешь." } }, f = { { 0.00, "О!" }, { 0.19, "Прости, я тебя не заметила." }, { 2.11, "Я собираю кое-какие вещички для моего друга." }, { 5.28, "Ну или... скорее, приятеля." }, { 7.20, "Ты не знакома с дозорным Фредериксом?" }, { 10.14, "Он из Южного дозора – это к западу отсюда, совсем недалеко." }, { 14.30, "Иногда он бывает тут, когда они патрулируют наши края, и я хотела вручить ему небольшой презент, чтобы показать, как я это ценю." }, { 23.30, "Я бы отнесла его сама, но надо присматривать за братиком, да и на ферме столько дел..." }, { 29.20, "Надеюсь, ты всё понимаешь." } } }, t = { d = 11.2, g = 1, v = "human-male", n = { m = 80, f = 82 }, c = { m = { { 0.00, "О!" }, { 0.27, "Что-то от Элинор?" }, { 2.07, "Как мило с её стороны!" }, { 4.24, "*Его щёки слегка розовеют.*" }, { 6.72, "Надо будет как-нибудь ответить ей тем же." }, { 9.52, "Спасибо, что принёс." } }, f = { { 0.00, "О!" }, { 0.27, "Что-то от Элинор?" }, { 2.07, "Как мило с её стороны!" }, { 4.24, "*Его щёки слегка розовеют.*" }, { 6.72, "Надо будет как-нибудь ответить ей тем же." }, { 9.38, "Спасибо, что принесла." } } } } },
    [95006] = { d = 19.4, g = 1, v = "creature/ancient", n = { m = 68, f = 68 }, c = { m = { { 0.00, "*Орокай закрывает глаза и замирает, общаясь с ветвью.*" }, { 4.65, "*Вы чувствуете, как по коже пробегает жгучее покалывание магии.*" }, { 10.00, "О, маленький смертный..." }, { 12.60, "Сколько всего может рассказать эта ветвь..." }, { 17.32, "Идём, я покажу тебе." } }, f = { { 0.00, "*Орокай закрывает глаза и замирает, общаясь с ветвью.*" }, { 4.65, "*Вы чувствуете, как по коже пробегает жгучее покалывание магии.*" }, { 10.00, "О, маленькая смертная..." }, { 12.48, "Сколько всего может рассказать эта ветвь..." }, { 17.20, "Идём, я покажу тебе." } } } },
    [95033] = { d = 20.8, v = "troll-male", n = { x = 195 }, c = { x = { { 0.00, "Если степи уже нагоняют на тебя тоску, имей в виду – моему другу Узер'и всегда нужна помощь." }, { 7.84, "Он всё больше по магии, но мало кто знает, что он ещё и заядлый охотник." }, { 13.63, "Если тебе это интересно, ищи его в лагере Мохаче в Фераласе." }, { 18.76, "Скажи, что ты от Тан'джани." } } } },
    [95034] = { d = 34.6, v = "skyborne-female", n = { x = 374 }, c = { x = { { 0.00, "Тебе стоит знать, что на самом деле мы столкнулись не с гноллами." }, { 4.88, "На нас напало огромное волкоподобное существо – теперь я знаю, что их называют воргенами." }, { 11.52, "Оно перебило стражу и переключилось на нас, но Банон заслонил меня собой." }, { 17.08, "Я кое-как сотворила заклинание, отчего тварь испугалась и сбежала." }, { 22.03, "Но Банон уже получил серьёзные укусы." }, { 24.88, "Он требовал, чтобы я оставила его там." }, { 27.79, "Я не согласилась." }, { 29.08, "Мы ковыляли обратно, когда нас нашли гноллы." }, { 32.47, "А потом случилось страшное..." } } }, t = { d = 36.0, v = "skyborne-female", n = { x = 369 }, c = { x = { { 0.00, "Теперь ты понимаешь." }, { 1.63, "На последнем издыхании, пронзённый дюжиной гнолльих клинков, он поднялся, чтобы напасть на меня." }, { 9.14, "В тот последний миг наши взгляды встретились, и я поняла: он всё ещё знал, кто он, и узнал меня." }, { 16.51, "Он понимал, что происходит, но не мог себя контролировать." }, { 20.98, "Это было хуже всего." }, { 22.75, "Если такое вообще возможно, я добьюсь, чтобы тварь, погубившая его, умерла и больше никогда не принесла этот ужас ни одному живому существу." }, { 33.94, "Клянусь небом над головой." } } } } },
    [95036] = { d = 32.4, v = "skyborne-female", n = { x = 348 }, c = { x = { { 0.00, "Треван рассказал мне, что воргены терроризируют жителей Серебряного бора." }, { 5.66, "Несмотря на силу и живучесть, их можно убить." }, { 9.22, "Но есть один, которого постоянно воскрешает неизвестная магия." }, { 14.04, "Как раз он на нас и напал – самый крупный и злобный в племени." }, { 18.79, "Его называют Старый Огнеглаз." }, { 21.16, "Чтобы с ним расправиться, нам нужно совершенно особенное оружие." }, { 26.12, "Поговори с Треваном: он даст тебе список материалов для изготовления такого оружия." } } }, t = { d = 9.0, v = "scourge-male#83", n = { x = 82 }, c = { x = { { 0.00, "Теперь, когда материалы у нас, нужен лишь кузнец, который выкует для нас клинок." }, { 7.00, "Кажется, я знаю такого." } } } } },
    [95041] = { d = 31.4, v = "gnome-female#39", n = { x = 369 }, c = { x = { { 0.00, "Перед тем как покинуть Гномреган, я сделала копию всех своих семейных архивов." }, { 5.45, "Чаротехнические полевые подсчёты, чертежи подлодок времён Второй войны, рецепт чили бабули Быстросмен... там собраны все наши величайшие достижения." }, { 15.67, "И только прибыв в Стальгорн, я поняла, что у меня в сумке дырка!" }, { 20.18, "Пропало несколько перфокарт, а без них данные не восстановить." }, { 24.44, "Должно быть, они упали в снег где-то в предместьях Гномрегана." }, { 28.76, "Не поищешь их?" }, { 29.77, "Знаю, надежды мало, но..." } } }, t = { d = 5.5, v = "gnome-female#39", n = { x = 50 }, c = { x = { { 0.00, "Карты немного намокли... но я приведу их в порядок!" }, { 4.43, "Спасибо тебе!" } } } } },
    [95042] = { d = 33.5, g = 1, v = "scourge-male#82", n = { m = 270, f = 270 }, c = { m = { { 0.00, "Герой-Отрёкшийся..." }, { 1.71, "В Ясеневом лесу?" }, { 3.26, "Чудеса." }, { 3.99, "Так ты ищешь самоцвет Кора?" }, { 6.51, "Вы не первые, кто усиливает ими магическое оружие и инструменты – обычно их применяют паладины Альянса." }, { 15.80, "Чем мёртвый паладин хуже?" }, { 18.08, "Если тебе в самом деле нужен один из этих самоцветов, иди на север в руины." }, { 25.16, "Наги, которые хранят самоцветы, живут в глубине." }, { 29.64, "Не ходи в одиночку, герой." } }, f = { { 0.00, "Героиня-Отрёкшаяся..." }, { 2.35, "В Ясеневом лесу?" }, { 3.90, "Чудеса." }, { 4.63, "Так ты ищешь самоцвет Кора?" }, { 7.15, "Вы не первые, кто усиливает ими магическое оружие и инструменты – обычно их применяют паладины Альянса." }, { 16.44, "Чем мёртвый паладин хуже?" }, { 18.72, "Если тебе в самом деле нужен один из этих самоцветов, иди на север в руины." }, { 25.80, "Наги, которые хранят самоцветы, живут в глубине." }, { 30.28, "Не ходи в одиночку, героиня." } } }, t = { d = 33.0, g = 1, v = "scourge-male#82", n = { m = 300, f = 301 }, c = { m = { { 0.00, "Ты наверняка заметишь порчу, пропитавшую этот самоцвет." }, { 4.92, "Для твоих целей магия, нужная, чтобы изгнать зло, которым его наполнили ведьмы наг, довольно проста." }, { 13.90, "Жаль, на самом деле: такая сила могла бы многому научить." }, { 19.06, "Полагаю, ты не согласишься бросить то дело, ради которого искал этот камень, и продать его мне?" }, { 27.56, "Он мог бы оказаться весьма ценным для моих... научных изысканий." } }, f = { { 0.00, "Ты наверняка заметишь порчу, пропитавшую этот самоцвет." }, { 4.82, "Для твоих целей магия, нужная, чтобы изгнать зло, которым его наполнили ведьмы наг, довольно проста." }, { 13.60, "Жаль, на самом деле: такая сила могла бы многому научить." }, { 18.65, "Полагаю, ты не согласишься бросить то дело, ради которого искала этот камень, и продать его мне?" }, { 27.04, "Он мог бы оказаться весьма ценным для моих... научных изысканий." } } } } },
    [95059] = { d = 19.1, v = "goblin-female", n = { x = 215 }, c = { x = { { 0.00, "Особая доставка!" }, { 1.22, "Это надо передать командору Демару Бранту в Фархолде." }, { 5.15, "Почему-то он вечно требует, чтобы к нему обращались по полному имени." }, { 10.18, "Странный тип." }, { 11.15, "В общем, он сидит в крепости к юго-западу отсюда, там его и найдёшь." }, { 16.04, "Большая такая каменная штука, не пропустишь." } } } },
    [95062] = { d = 13.1, v = "goblin-female", n = { x = 136 }, c = { x = { { 0.00, "Особая доставка!" }, { 1.31, "Старик Кром'рош ждёт эту посылку в Рог'маре к западу отсюда." }, { 6.01, "Советую идти к нему очень быстро, но осторожно." }, { 9.74, "Почему, спросишь ты?" }, { 11.33, "А вот лучше не спрашивай." } } } },
    [95063] = { d = 23.0, g = 1, v = "goblin-male", n = { m = 248, f = 250 }, c = { m = { { 0.00, "Слушай сюда!" }, { 0.97, "Ты показал себя на ринге." }, { 2.86, "Настолько, что Чух'чох теперь разрывается от ярости." }, { 6.62, "Не хотелось бы мне сейчас быть на твоём месте." }, { 9.86, "На всякий случай напомню, что твоя плата за участие не покрывает расходы на похороны." }, { 16.03, "Приятно было с тобой познакомиться, но дальше разбирайся сам." }, { 20.44, "Желаю удачи, дружище." } }, f = { { 0.00, "Слушай сюда!" }, { 0.97, "Ты показала себя на ринге." }, { 3.19, "Настолько, что Чух'чох теперь разрывается от ярости." }, { 6.95, "Не хотелось бы мне сейчас быть на твоём месте." }, { 10.19, "На всякий случай напомню, что твоя плата за участие не покрывает расходы на похороны." }, { 16.10, "Приятно было с тобой познакомиться, но дальше разбирайся сама." }, { 21.48, "Желаю удачи, дружище." } } } },
    [95064] = { d = 18.9, v = "human-male", n = { x = 215 }, c = { x = { { 0.00, "Орки представляют всё большую угрозу с самого своего появления." }, { 4.52, "Сначала они захватили земли вдоль реки, а теперь начинают занимать равнины..." }, { 10.05, "Я не знаю и не хочу знать, что у них на уме, но если они думают, что мы разрешим им захватить новые земли, то глубоко ошибаются." } } } },
    [95065] = { d = 35.5, v = "human-male", n = { x = 419 }, c = { x = { { 0.00, "Какой прекрасный вид... настоящая услада для старческих глаз." }, { 4.16, "Рыба клюёт просто отлично, но у меня совсем закончилась наживка." }, { 8.62, "У тебя нет при себе наживки или рыболовных снастей?" }, { 12.22, "Ну да, глупый вопрос." }, { 13.71, "Я слишком увлечён рыбалкой, и мне как-то не пришло в голову, что я, наверное, единственный, кто всегда носит всё своё с собой." }, { 22.20, "Может, поможешь мне пополнить запасы?" }, { 24.81, "К западу от торгового квартала у каналов ты найдёшь Катрин Лиланд – у неё должно найтись всё необходимое для рыбной ловли." }, { 33.12, "Скажи, что тебя старина Грей послал." } } }, t = { d = 15.1, g = 1, v = "human-male", n = { m = 169, f = 171 }, c = { m = { { 0.00, "Ты как раз вовремя!" }, { 1.38, "Я только что поймал крупную рыбу на последнюю наживку." }, { 5.39, "Сегодня хороший день, клюёт просто отлично!" }, { 8.54, "Спасибо, что помог старику не потерять работу." }, { 11.95, "Может, возьмёшь в дорогу часть моего улова?" } }, f = { { 0.00, "Ты как раз вовремя!" }, { 1.38, "Я только что поймал крупную рыбу на последнюю наживку." }, { 5.40, "Сегодня хороший день, клюёт просто отлично!" }, { 8.55, "Спасибо, что помогла старику не потерять работу." }, { 12.11, "Может, возьмёшь в дорогу часть моего улова?" } } } } },
    [95066] = { d = 9.4, v = "human-male", n = { x = 105 }, c = { x = { { 0.00, "Теперь врагу ясны наши намерения." }, { 2.60, "Возвращайся к Бранту в крепость и передай ему отчёт." }, { 6.46, "Уверен, он будет доволен нашими успехами." } } } },
    [95111] = { d = 31.0, v = "scourge-male#83", n = { x = 339 }, c = { x = { { 0.00, "На Мельнице Таррен живёт оружейник по имени Отт." }, { 3.60, "Ничем не примечательный кузнец, продаёт простые клинки путешественникам." }, { 8.97, "Я сам купил у него меч, а когда через какое-то время отдал его в Подгороде на ремонт, кузнецов удивило его качество." }, { 17.87, "Они подумали на известного мастера, но нет, то был всего лишь Отт." }, { 22.76, "Я хочу дать орку шанс выковать что-нибудь достойное." }, { 26.70, "Отнеси материалы Отту на Мельницу Таррен и предложи заказ." } } }, t = { d = 26.2, v = "orc-male", n = { x = 254 }, c = { x = { { 0.00, "Интересно." }, { 0.89, "По-моему, ещё никто не просил меня выполнить заказ на особую работу." }, { 6.64, "В основном я делаю простое, добротное оружие в своём стиле." }, { 11.56, "Немного, зато честный труд, а славы и почестей я не ищу." }, { 16.25, "Я с радостью попробую, но почему ты обращаешься с этим ко мне?" }, { 21.32, "В Подгороде полно кузнецов, которые берутся за такие заказы." } } } } },
    [95118] = { d = 18.2, v = "goblin-male", n = { x = 189 }, c = { x = { { 0.00, "Мурлоки, мурлоки, мурлоки!" }, { 2.07, "Только это и слышу от всех моряков, рыбаков, даже от собственных детей!" }, { 7.58, "Всех достали." }, { 8.61, "Мурлоки и правда мешают, это так, но мне надо как-то управлять портом!" }, { 14.05, "Выручи, а?" }, { 14.88, "Убей несколько паразитов, с меня причитается." } } }, t = { d = 8.8, g = 1, v = "goblin-male", n = { m = 84, f = 85 }, c = { m = { { 0.00, "Разобрался с ними?" }, { 1.59, "Отлично!" }, { 2.35, "Наверняка скоро припрутся новые, но хоть до тех пор отдохну в тишине и покое." } }, f = { { 0.00, "Разобралась с ними?" }, { 1.73, "Отлично!" }, { 2.49, "Наверняка скоро припрутся новые, но хоть до тех пор отдохну в тишине и покое." } } } } },
    [95119] = { d = 25.8, g = 1, v = "goblin-male", n = { m = 281, f = 282 }, c = { m = { { 0.00, "Слыхал про братство Восточных Морей?" }, { 2.70, "Неприятные типы, и это тебе говорит управляющий местечка под названием \"Пороховой порт\"." }, { 9.15, "Они агрессивные, кровожадные и, что хуже всего, вредят моему бизнесу." }, { 14.28, "Крадут грузы, топят корабли – и это всё стоит мне бешеных денег!" }, { 19.08, "Надо прикрыть эту лавочку, начиная с тех что поближе." }, { 23.03, "Их можно найти на берегах к северу." } }, f = { { 0.00, "Слыхала про братство Восточных Морей?" }, { 2.93, "Неприятные типы, и это тебе говорит управляющий местечка под названием \"Пороховой порт\"." }, { 9.38, "Они агрессивные, кровожадные и, что хуже всего, вредят моему бизнесу." }, { 14.51, "Крадут грузы, топят корабли – и это всё стоит мне бешеных денег!" }, { 19.31, "Надо прикрыть эту лавочку, начиная с тех что поближе." }, { 23.26, "Их можно найти на берегах к северу." } } } },
    [95120] = { d = 24.6, v = "narrator", n = { x = 263 }, c = { x = { { 0.00, "Моряки и пловцы, берегитесь!" }, { 2.30, "Местные рыбаки видели особенно агрессивного мурлока по прозвищу Старый Гниложев, который атакует лодки и мелкие суда в водах к югу отсюда близ кишащих мурлоками островов." }, { 16.02, "Управляющий пристанью Просвистун предлагает награду тому, кто предъявит доказательство смерти этого существа." } } }, t = { d = 7.0, v = "goblin-male", n = { x = 64 }, c = { x = { { 0.00, "Ну, одной заботой меньше." }, { 2.24, "Я твой должник." }, { 3.56, "Держи, только не трать всё в одном месте." } } } } },
    [95121] = { d = 28.0, v = "goblin-male", n = { x = 303 }, c = { x = { { 0.00, "Добро пожаловать в плавучее кафе Фимбо!" }, { 3.02, "Сегодня в меню жареный кабан и жареная рыба... как и всегда..." }, { 7.71, "Надо обновить меню, позарез надо обновить меню." }, { 11.39, "Я присмотрел рецепт новой похлёбки с морепродуктами, но надо достать свежее мясо." }, { 17.42, "Мне бы немного глаз мурлоков и крабового мяса." }, { 20.84, "И то и другое можно добыть тут на берегу." }, { 23.92, "Старые добрые местные ингредиенты, что может быть лучше!" } } } },
    [95122] = { d = 25.4, g = 1, v = "goblin-male", n = { m = 286, f = 287 }, c = { m = { { 0.00, "Эти пираты Восточного Моря, которых ты ухлопал, были хоть и опасные, но всё-таки мелкая рыбёшка." }, { 6.81, "А вот на севере у них есть куда более серьёзные и опасные братья по оружию." }, { 12.07, "Они разграбили Ветроземье, унесли всё что смогли и сожгли город дотла." }, { 17.14, "Надо остановить агрессоров, пока они не закрепились и не двинулись дальше." }, { 22.47, "Сделай так, чтобы их стало поменьше." } }, f = { { 0.00, "Эти пираты Восточного Моря, которых ты ухлопала, были хоть и опасные, но всё-таки мелкая рыбёшка." }, { 7.28, "А вот на севере у них есть куда более серьёзные и опасные братья по оружию." }, { 12.54, "Они разграбили Ветроземье, унесли всё что смогли и сожгли город дотла." }, { 17.61, "Надо остановить агрессоров, пока они не закрепились и не двинулись дальше." }, { 22.94, "Сделай так, чтобы их стало поменьше." } } } },
    [95123] = { d = 25.4, v = "goblin-male", n = { x = 300 }, c = { x = { { 0.00, "Я, конечно, люблю смотреть, как головы пиратов Восточных Морей летят с плеч, но не стоит забывать и об их кораблях." }, { 7.90, "Нехорошо же будет, если они улизнут от нас и вернутся с подкреплением, да?" }, { 13.00, "У меня есть план, но нам понадобится порох." }, { 15.92, "Много пороха." }, { 16.92, "Возможно, у пиратов есть запасы рядом с разорённым Ветроземьем к северу отсюда." }, { 22.33, "Попробуй раздобыть." }, { 23.70, "Остальное расскажу позже." } } } },
    [95124] = { d = 28.8, v = "goblin-male", n = { x = 311 }, c = { x = { { 0.00, "Пришло время заняться самым главным боссом: адмиралом Ламорой." }, { 4.74, "Разумеется, я хочу его убить, но мне нужно от него кое-что ещё." }, { 9.47, "Его набеги дорого мне обошлись – будет справедливо, если я частично это компенсирую." }, { 15.81, "Ламора на одном из кораблей Восточных Морей норд-ост отсюда." }, { 20.34, "Узнай, на котором из них адмирал и где он держит свою добычу." }, { 24.88, "Принеси её мне." }, { 26.01, "Если заперто – ключ должен быть при нём." } } } },
    [95125] = { d = 14.1, g = 1, v = "orc-male", n = { x = 136 }, c = { m = { { 0.00, "Это материалы наилучшего качества, герой." }, { 3.50, "Ты оказываешь мне честь, заказав у меня такой клинок." }, { 7.90, "Постараюсь оправдать твои ожидания." }, { 10.88, "Пожалуйста, отойди." }, { 12.52, "Я приступлю к ковке." } }, f = { { 0.00, "Это материалы наилучшего качества, героиня." }, { 3.53, "Ты оказываешь мне честь, заказав у меня такой клинок." }, { 7.79, "Постараюсь оправдать твои ожидания." }, { 10.67, "Пожалуйста, отойди." }, { 12.25, "Я приступлю к ковке." } } }, t = { d = 12.1, v = "orc-male", n = { x = 113 }, c = { x = { { 0.00, "Этот клинок – моя лучшая работа, и я надеюсь, что он хорошо послужит тебе в странствиях." }, { 7.57, "Ещё раз спасибо за эту возможность." }, { 10.55, "Ака'Магош, друг мой." } } } } },
    [95126] = { d = 11.3, v = "orc-male", n = { x = 109 }, c = { x = { { 0.00, "Вот готовый клинок." }, { 1.67, "Говоришь, тебя послал паладин Треван?" }, { 4.92, "Передай благодарность и ему." }, { 7.35, "Нечасто выпадает такой шанс." }, { 9.77, "Иди с честью, друг." } } }, t = { d = 16.6, g = 1, v = "scourge-male#83", n = { m = 118, f = 119 }, c = { m = { { 0.00, "*Треван берёт клинок и внимательно его осматривает.*" }, { 4.08, "Отлично подойдёт." }, { 5.54, "Я знал, что Отт способен создать нечто поистине великое." }, { 10.32, "Осталось лишь убить эту тварь." }, { 12.93, "Поговори с Люминой, когда будешь готов." } }, f = { { 0.00, "*Треван берёт клинок и внимательно его осматривает.*" }, { 4.16, "Отлично подойдёт." }, { 5.65, "Я знал, что Отт способен создать нечто поистине великое." }, { 10.52, "Осталось лишь убить эту тварь." }, { 13.19, "Поговори с Люминой, когда будешь готова." } } } } },
    [95140] = { d = 23.2, g = 1, v = "skyborne-female", n = { x = 242 }, c = { m = { { 0.00, "Вижу, оружие у тебя, герой." }, { 2.18, "Я буду молиться, чтобы оно тебя не подвело." }, { 5.58, "Местные жители говорят, что Старый Огнеглаз охотится на большой территории к югу и часто пробегает мимо ворот Гилнеаса." }, { 14.70, "Найди его и пусти в ход свой клинок." }, { 17.49, "Когда прикончишь Огнеглаза, возвращайся ко мне за наградой от Ваятелей Ветра." } }, f = { { 0.00, "Вижу, оружие у тебя, героиня." }, { 2.30, "Я буду молиться, чтобы оно тебя не подвело." }, { 5.68, "Местные жители говорят, что Старый Огнеглаз охотится на большой территории к югу и часто пробегает мимо ворот Гилнеаса." }, { 14.75, "Найди его и пусти в ход свой клинок." }, { 17.52, "Когда прикончишь Огнеглаза, возвращайся ко мне за наградой от Ваятелей Ветра." } } }, t = { d = 33.4, g = 1, v = "skyborne-female", n = { x = 233 }, c = { m = { { 0.00, "Спасибо." }, { 0.70, "Теперь Банон может покоиться с миром." }, { 3.71, "Если позволишь, думаю, я смогу наложить на твой только что обагрённый кровью клинок немного магии моего народа." }, { 12.25, "*Глаза Люмины Песнь Ветра начинают светиться ярко-синим, когда она касается окровавленного клинка в твоей руке.*" }, { 21.53, "Готово." }, { 22.18, "Это мелочь – такой великолепный клинок я едва ли могла улучшить." }, { 27.46, "И всё же я буду молить ветра, чтобы он хорошо служил тебе, герой." } }, f = { { 0.00, "Спасибо." }, { 0.73, "Теперь Банон может покоиться с миром." }, { 3.88, "Если позволишь, думаю, я смогу наложить на твой только что обагрённый кровью клинок немного магии моего народа." }, { 12.82, "*Глаза Люмины Песнь Ветра начинают светиться ярко-синим, когда она касается окровавленного клинка в твоей руке.*" }, { 22.00, "Готово." }, { 22.66, "Это мелочь – такой великолепный клинок я едва ли могла улучшить." }, { 28.02, "И всё же я буду молить ветра, чтобы он хорошо служил тебе, героиня." } } } } },
    [95141] = { d = 40.9, v = "orc-male#60", n = { x = 412 }, c = { x = { { 0.00, "Далеко на северо-востоке, за Каменором, пролегает Лесоречье – охваченные войной земли вдоль восточного побережья." }, { 9.19, "Многие пытались их отвоевать, но немногим это удалось." }, { 13.68, "Однако есть один воин, чей опыт в сражениях с нашим врагом дал плоды в виде небольшой заставы под названием Рог'мар." }, { 23.24, "Она стоит и до сих пор, несмотря на бесчисленные нападения." }, { 28.02, "Кром'рош суров и безжалостен, но его решимость очень помогла нашим союзникам." }, { 34.42, "Если ищешь битвы, отправляйся на северо-восток и найди нашего старого товарища." } } } },
    [95143] = { d = 41.2, v = "troll-male#77", n = { x = 431 }, c = { x = { { 0.00, "Я наблюдаю за твоими успехами, и ты очень неплохо себя показываешь." }, { 5.24, "Быть может, ты захочешь помочь найти моего брата Тан'джани." }, { 9.92, "Он всегда искал что-то – но что именно, я не знаю." }, { 13.83, "С тех пор как он уехал, вести о нём приходили лишь дважды." }, { 18.23, "Сначала было сообщение от одного путешественника, который рассказывал, что встретил Тан'джани к югу от Лок Модана." }, { 27.03, "А потом пришло окровавленное письмо, в котором упоминалось Лесоречье и место под названием Рог'мар, ещё южнее." }, { 35.55, "Больше ничего разобрать не удалось." }, { 38.35, "Как думаешь, ты сможешь его разыскать?" } } } },
    [95144] = { d = 38.4, g = 1, v = "goblin-male", n = { m = 428, f = 429 }, c = { m = { { 0.00, "Слушай, дружище." }, { 1.24, "У меня тут посылка, которую нужно доставить старой подруге." }, { 5.60, "Что бы ты ни делал..." }, { 7.10, "НЕ ОТКРЫВАЙ ЕЁ!" }, { 8.21, "Крайне осторожно переправь этот груз через море и доставь его Фриз Искродох в наш дочерний порт в Лесоречье." }, { 16.02, "И прежде чем ты спросишь, нет, добираться вплавь не советую." }, { 20.25, "Для твоего предшественника это ничем хорошим не закончилось." }, { 24.62, "И да, не наклоняй груз, не тряси его и вообще не делай резких движений." }, { 29.76, "Лучше иди с ним на восток, в порт Хитрой Шестерёнки." }, { 33.47, "Оттуда отправляется самый безопасный корабль." }, { 36.79, "Что ж, желаю удачи!" } }, f = { { 0.00, "Слушай, дружище." }, { 1.24, "У меня тут посылка, которую нужно доставить старой подруге." }, { 5.30, "Что бы ты ни делала..." }, { 7.43, "НЕ ОТКРЫВАЙ ЕЁ!" }, { 8.54, "Крайне осторожно переправь этот груз через море и доставь его Фриз Искродох в наш дочерний порт в Лесоречье." }, { 16.35, "И прежде чем ты спросишь, нет, добираться вплавь не советую." }, { 20.58, "Для твоего предшественника это ничем хорошим не закончилось." }, { 24.95, "И да, не наклоняй груз, не тряси его и вообще не делай резких движений." }, { 30.09, "Лучше иди с ним на восток, в порт Хитрой Шестерёнки." }, { 33.80, "Оттуда отправляется самый безопасный корабль." }, { 37.12, "Что ж, желаю удачи!" } } } },
    [95147] = { d = 29.8, g = 1, v = "human-male", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Ты... откуда ты взялся?" }, { 2.49, "Тебе тут не место!" }, { 4.40, "*Болайн говорит, превозмогая боль: он весь в синяках, а на ноге видна гнойная рана от укуса.*" }, { 12.08, "Отнеси это Далтону." }, { 13.72, "Иди по дороге на северо-восток." }, { 16.29, "Туда, где начинаются поля – широкие, как эта проклятая царапина." }, { 21.43, "Передай ему, что он был прав... или нет, не надо." }, { 25.28, "Пока я не сдох, нечего ему радоваться." }, { 28.35, "Ненавижу эти холмы!" } }, f = { { 0.00, "Ты... откуда ты взялась?" }, { 2.21, "Тебе тут не место!" }, { 4.12, "*Болайн говорит, превозмогая боль: он весь в синяках, а на ноге видна гнойная рана от укуса.*" }, { 11.80, "Отнеси это Далтону." }, { 13.44, "Иди по дороге на северо-восток." }, { 16.01, "Туда, где начинаются поля – широкие, как эта проклятая царапина." }, { 21.15, "Передай ему, что он был прав... или нет, не надо." }, { 25.00, "Пока я не сдох, нечего ему радоваться." }, { 28.07, "Ненавижу эти холмы!" } } }, t = { d = 13.5, v = "human-male", n = { x = 152 }, c = { x = { { 0.00, "Болайн пошёл куда?!" }, { 1.42, "Вот же..." }, { 2.07, "Я ведь говорил ему не ходить одному." }, { 4.73, "Похоже, кое-кто из наших до сих пор недооценивает этих проклятых гноллов." }, { 9.97, "Рыцарь-командор захочет узнать об этом немедленно." } } } } },
    [95148] = { d = 16.2, v = "human-male", n = { x = 181 }, c = { x = { { 0.00, "Как бы я хотел лично вручить окровавленное письмо командору!" }, { 4.41, "Но не хочу, чтобы меня разжаловали." }, { 7.04, "Поэтому я почистил его, чтобы оно было... не таким кровавым." }, { 11.57, "Гноллы продолжают атаковать, поэтому отнести отчёт придётся тебе." } } }, t = { d = 26.9, v = "human-male", n = { x = 323 }, c = { x = { { 0.00, "Новости печальные, но неудивительные." }, { 2.54, "Гноллы годами наводняют эти земли." }, { 5.02, "Когда мы только пришли сюда, по холмам и низинам постоянно гремели стычки." }, { 10.23, "Лишь после многих потерь нам удалось оправиться и удержать позиции." }, { 14.87, "Я позабочусь, чтобы Далтон и его люди получили дополнительный провиант, оружие и, на время, пехотинцев." }, { 22.00, "Мы не можем допустить, чтобы гноллы снова прорвались на нашу территорию." } } } } },
    [95156] = { d = 24.8, v = "human-female", n = { x = 299 }, c = { x = { { 0.00, "Наши манекены уже порядком изношены." }, { 2.55, "Если не озаботиться починкой, скоро новобранцам будет не-на-чем отрабатывать удары." }, { 8.21, "Не знаю, в курсе ты или нет, но прямо за стенами крепости есть небольшая ферма, которой владеет славный малый по имени Вилер." }, { 16.73, "Возможно, у него найдётся пара лишних бушелей сена." }, { 20.26, "Если согласится помочь с припасами, я прослежу, чтобы ему заплатили." } } }, t = { d = 3.2, v = "human-female", n = { x = 36 }, c = { x = { { 0.00, "Сейчас же сделаем несколько новых мишеней." } } } } },
    [95161] = { d = 21.5, v = "human-female", n = { x = 262 }, c = { x = { { 0.00, "Если ты ищешь Джереми Хартвивера, то обратись к его новоиспечённой приёмной матери." }, { 5.52, "Её зовут Аветта Хвористинка, и живёт она в Сумеречном лесу." }, { 9.53, "Добрейшая женщина." }, { 10.80, "Ей, должно быть, понадобился помощник по хозяйству, но это лучше, чем жить в приюте." }, { 16.38, "Если увидишься с Джереми, передай ему, что мы все про него вспоминаем, хорошо?" } } }, t = { d = 31.0, g = 1, v = "human-female#113", n = { m = 366, f = 368 }, c = { m = { { 0.00, "О нет..." }, { 0.54, "Спасибо, что принёс это письмо, но мне кажется, Джереми ещё не готов его увидеть." }, { 5.96, "Попечительница Найтингейл сказала, что мой Джереми не разговаривает с тех пор, как на Лордерон напали, и я не хочу на него давить." }, { 14.44, "Это письмо принесёт ему только боль." }, { 16.90, "Не смотри на меня так." }, { 18.41, "Я не собираюсь скрывать от мальчика его прошлое, но ему нужно время, чтобы прийти в себя." }, { 24.48, "Отдам ему письмо, когда он будет постарше." }, { 27.43, "Спасибо, что зашёл к нам, но, думаю, тебе пора уходить." } }, f = { { 0.00, "О нет..." }, { 0.53, "Спасибо, что принесла это письмо, но мне кажется, Джереми ещё не готов его увидеть." }, { 6.06, "Попечительница Найтингейл сказала, что мой Джереми не разговаривает с тех пор, как на Лордерон напали, и я не хочу на него давить." }, { 14.43, "Это письмо принесёт ему только боль." }, { 16.87, "Не смотри на меня так." }, { 18.35, "Я не собираюсь скрывать от мальчика его прошлое, но ему нужно время, чтобы прийти в себя." }, { 24.35, "Отдам ему письмо, когда он будет постарше." }, { 27.26, "Спасибо, что зашла к нам, но, думаю, тебе пора уходить." } } } } },
    [95162] = { d = 33.1, v = "orc-male#60", n = { x = 363 }, c = { x = { { 0.00, "Большая часть земель здесь принадлежит либо людям, либо Сумеречному Молоту, так что эта ферма – один из немногих источников пищи." }, { 9.60, "Огры не любят копаться в земле, но обожают мясо бледноклыков, так что они разрешают мне жить здесь, пока я их кормлю." }, { 18.20, "Война продолжается, и спрос на еду только растёт." }, { 21.80, "Моих запасов едва хватает, так что огры нет-нет да и поглядывают на меня как на следующий обед." }, { 28.87, "Чтобы накормить ещё и Рог'мар, мне понадобится твоя помощь." } } } },
    [95163] = { d = 24.2, v = "orc-male#60", n = { x = 255 }, c = { x = { { 0.00, "Как видишь, в долине свиней больше, чем в свинарниках." }, { 4.10, "Помощи по хозяйству от Пузожора не дождёшься, но он хотя бы отпугивает людей." }, { 9.84, "Часть мелких свинок сбежала от меня за реку." }, { 13.25, "Они ещё слишком малы для забоя, так что нужно вернуть их сюда." }, { 18.04, "Возьми эту палку." }, { 19.47, "Стукнешь ей одну из моих свинок – та сразу побежит назад домой." } } } },
    [95165] = { d = 22.5, g = 1, v = "goblin-male", n = { m = 249, f = 249 }, c = { m = { { 0.00, "Значит, вот как мы потопим их корабли." }, { 2.77, "Я сделаю из украденного тобой пороха бомбы замедленного действия." }, { 7.58, "А ты проберёшься на корабли братства Восточных Морей и установишь их." }, { 12.53, "Где-нибудь рядом с пушками, чтобы порох усилил взрыв." }, { 16.49, "Потом убирайся оттуда – и я жахну по детонатору!" }, { 20.05, "Просто и элегантно, согласен?" } }, f = { { 0.00, "Значит, вот как мы потопим их корабли." }, { 2.77, "Я сделаю из украденного тобой пороха бомбы замедленного действия." }, { 7.58, "А ты проберёшься на корабли братства Восточных Морей и установишь их." }, { 12.53, "Где-нибудь рядом с пушками, чтобы порох усилил взрыв." }, { 16.49, "Потом убирайся оттуда – и я жахну по детонатору!" }, { 19.58, "Просто и элегантно, согласна?" } } } },
    [95181] = { d = 31.4, v = "orc-female", n = { x = 281 }, c = { x = { { 0.00, "Тише!" }, { 1.12, "*Азка огрызается и переводит на тебя взгляд.*" }, { 4.80, "Я тебе голову оторву, если из-за тебя культисты узнают, где я прячусь." }, { 10.23, "Смотри под ноги и не шуми, когда идёшь через эти холмы." }, { 14.50, "Иначе мне придётся отправлять Кром'рошу донесение, что схватили ещё одного из наших." }, { 20.74, "А теперь бери это и уходи отсюда — быстро... и тихо!" }, { 24.81, "Кром'рош ждёт это донесение." }, { 26.98, "Найдёшь его и остальных на заставе в глубине суши, к востоку." } } } },
    [95183] = { d = 23.4, v = "creature/ogre", n = { x = 213 }, c = { x = { { 0.00, "Хочешь оружие, как у огра?" }, { 2.34, "Ну нет." }, { 2.97, "Ты мелочь." }, { 3.91, "Не удержишь как надо." }, { 5.78, "Принеси Хамуру ещё камней, и я сделаю тебе мелкое оружие." }, { 10.86, "Для мелкого существа." }, { 12.74, "Ищи хорошие камни для хорошего оружия." }, { 16.17, "У Хамура глаз-алмаз." }, { 17.97, "Не всякий камень подойдёт." }, { 20.24, "Ищи камни у реки рядом с Болдер'оком." } } } },
    [95184] = { d = 23.5, v = "human-female", n = { x = 263 }, c = { x = { { 0.00, "Обучение ратному делу – это, конечно, хорошо, но наши новобранцы пока не видят разницы между тренировочным мечом и острым клинком опытного воина." }, { 10.60, "Думаю, пора показать им, что от остроты клинка зависит исход боя, победа или смерть." }, { 16.75, "Найди нам несколько точил, и возьмёмся за дело." }, { 20.11, "Есть мастера, которые их делают." }, { 22.44, "Поговори с ними." } } }, t = { d = 1.4, v = "human-female", n = { x = 10 }, c = { x = { { 0.00, "То, что нужно." } } } } },
    [95189] = { d = 11.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Истёртый герб с символом Лордерона." }, { 2.65, "После падения королевства уцелело так мало реликвий, что кто-нибудь в Штормграде наверняка заинтересуется этим предметом." } } }, t = { d = 16.4, g = 1, v = "human-female#45", n = { m = 186, f = 187 }, c = { m = { { 0.00, "Как тебе удалось раздобыть эту вещицу?" }, { 2.76, "Учитывая, через что она прошла, состояние у неё просто отличное." }, { 7.27, "Спасибо, что вернул нам эту частицу истории Альянса, герой." }, { 11.47, "Я немедленно поручу моим лучшим экспертам восстановить эту реликвию." } }, f = { { 0.00, "Как тебе удалось раздобыть эту вещицу?" }, { 2.77, "Учитывая, через что она прошла, состояние у неё просто отличное." }, { 7.30, "Спасибо, что вернула нам эту частицу истории Альянса, героиня." }, { 11.70, "Я немедленно поручу моим лучшим экспертам восстановить эту реликвию." } } } } },
    [95194] = { d = 33.8, v = "human-male", n = { x = 396 }, c = { x = { { 0.00, "Приветствую." }, { 0.88, "У ШРУ есть дело, в котором пригодилась бы твоя помощь." }, { 4.94, "Наш человек на острове Терамор сообщает, что морские пехотинцы Джайны Праудмур только что доставили туда человека, которого нашли выброшенным на берег." }, { 15.46, "Обычно нас бы это мало заинтересовало, но, похоже, этот человек заявил пехотинцам, что он — сам король Штормграда, Вариан Ринн." }, { 24.22, "Отправляйся в Терамор и встреться в таверне с дворфом по имени Салли." }, { 29.10, "Он тебя ждёт и, когда прибудешь, даст указания." }, { 32.36, "Выясни, что происходит." } } } },
    [95195] = { d = 13.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Похоже, этот старый знак отличия Альянса принадлежал солдату Лордерона." }, { 5.61, "В этих руинах наверняка полно таких медалей." }, { 9.19, "Выжившие родственники солдат будут благодарны их получить." } } }, t = { d = 20.2, g = 1, v = "human-male", n = { m = 236, f = 239 }, c = { m = { { 0.00, "Ты правильно сделал, что принёс мне эти знаки отличия." }, { 3.78, "Когда Плеть захватила Лордерон, многие его жители бежали сюда, в Штормград." }, { 9.13, "А из хозяев этих знаков едва ли кто-то остался в живых." }, { 13.09, "Твоя преданность Штормграду достойна похвалы." }, { 16.30, "Я немедленно передам эти знаки выжившим родственникам." } }, f = { { 0.00, "Ты правильно сделала, что принесла мне эти знаки отличия." }, { 4.03, "Когда Плеть захватила Лордерон, многие его жители бежали сюда, в Штормград." }, { 9.37, "А из хозяев этих знаков едва ли кто-то остался в живых." }, { 13.34, "Твоя преданность Штормграду достойна похвалы." }, { 16.55, "Я немедленно передам эти знаки выжившим родственникам." } } } } },
    [95196] = { d = 12.3, v = "dwarf-male", n = { x = 139 }, c = { x = { { 0.00, "Слушай сюда." }, { 0.95, "Сейчас я выйду в ту дверь, что у тебя за спиной." }, { 4.30, "Подождёшь, пока я как следует уйду, а потом встретимся за кладбищем, что за городом." }, { 10.12, "Смотри, чтоб за тобой не следили." } } } },
    [95198] = { d = 30.6, v = "dwarf-male", n = { x = 365 }, c = { x = { { 0.00, "Держи." }, { 0.49, "Это удобная штучка — чары, которые маги у нас дома состряпали для быстрой маскировки." }, { 6.41, "С ней ты будешь выглядеть как морской пехотинец Кул-Тираса, а для этого задания лучше и не придумаешь." }, { 13.32, "Проберись в башню и постарайся подслушать, не упомянут ли того человека, которого выбросило на берег." }, { 20.22, "Но предупреждаю: не подходи к Джайне слишком близко." }, { 23.80, "Она сразу раскусит эту маскировку." }, { 26.26, "Если маскировка спадёт — возвращайся ко мне, я сделаю тебе новую." } } } },
    [95204] = { d = 12.1, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Истёртый герб с символом Лордерона." }, { 2.72, "После падения королевства уцелело так мало реликвий, что кто-нибудь в Подгороде наверняка заинтересуется этим предметом." } } }, t = { d = 23.8, g = 1, v = "scourge-female#79", n = { x = 161 }, c = { m = { { 0.00, "*Оран пробует герб на зуб, чтобы убедиться в его подлинности.*" }, { 4.80, "Надо же." }, { 5.65, "Настоящая реликвия нашей родины." }, { 8.79, "И почти целая." }, { 10.24, "С ней нужно обращаться особенно бережно." }, { 14.06, "Спасибо, что помогаешь восстановить нашу историю, герой." }, { 19.42, "Я прослежу, чтобы о ней как следует позаботились." } }, f = { { 0.00, "*Оран пробует герб на зуб, чтобы убедиться в его подлинности.*" }, { 4.80, "Надо же." }, { 5.61, "Настоящая реликвия нашей родины." }, { 8.61, "И почти целая." }, { 9.99, "С ней нужно обращаться особенно бережно." }, { 13.64, "Спасибо, что помогаешь восстановить нашу историю, героиня." }, { 18.90, "Я прослежу, чтобы о ней как следует позаботились." } } } } },
    [95212] = { d = 19.8, v = "dwarf-female#34", n = { x = 229 }, c = { x = { { 0.00, "Мы готовимся отправить подмогу альтеракской экспедиции, но у нас не хватает материалов, чтобы изготовить сёдла для баранов." }, { 8.87, "Поохоться на самых крупных и свирепых леопардов на востоке и принеси их шкуры." }, { 14.69, "В Альтераке лютый мороз, а наши всадники заслуживают самые тёплые сёдла!" } } }, t = { d = 6.9, g = 1, v = "dwarf-female#34", n = { x = 51 }, c = { m = { { 0.00, "Из этих шкур получатся отличные сёдла." }, { 3.76, "Альянс гордится тобой, герой!" } }, f = { { 0.00, "Из этих шкур получатся отличные сёдла." }, { 3.80, "Альянс гордится тобой, героиня!" } } } } },
    [95213] = { d = 20.0, v = "narrator", n = { x = 198 }, c = { x = { { 0.00, "На бочонке отпечатана надпись:" }, { 2.51, "ПОРОХ – ОПАСНО – НЕ ТРОГАТЬ – ОПАСНО – ТРЕБУЕТСЯ РАЗРЕШЕНИЕ НАЧАЛЬНИКА КАРЬЕРА – ОПАСНО" }, { 9.67, "У вас возникает тревожное чувство, что у троггов этого бочонка быть не должно." }, { 16.02, "Лучше сообщить об этом в карьер как можно скорее." } } }, t = { d = 7.0, g = 1, v = "dwarf-male", n = { m = 13, f = 13 }, c = { m = { { 0.00, "*Дворф замечает опустевший бочонок и заметно бледнеет.*" }, { 4.64, "Ты... где это нашёл?" } }, f = { { 0.00, "*Дворф замечает опустевший бочонок и заметно бледнеет.*" }, { 4.72, "Ты... где это нашла?" } } } } },
    [95214] = { d = 10.8, v = "dwarf-male", n = { x = 134 }, c = { x = { { 0.00, "Да в этом бочонке было достаточно пороха, чтобы превратить тронный зал короля Магни в открытый двор." }, { 6.62, "Надо забрать его у троггов, пока они не додумались его поджечь." } } }, t = { d = 12.6, g = 1, v = "dwarf-male", n = { x = 120 }, c = { m = { { 0.00, "Кажется, это весь украденный порох." }, { 2.91, "Спасибо, герой." }, { 4.22, "Прими эту награду и... буду ещё более признателен, если ты никому не расскажешь об этом маленьком казусе." } }, f = { { 0.00, "Кажется, это весь украденный порох." }, { 2.86, "Спасибо, героиня." }, { 4.28, "Прими эту награду и... буду ещё более признателен, если ты никому не расскажешь об этом маленьком казусе." } } } } },
    [95216] = { d = 44.3, g = 1, v = "scourge-male", n = { m = 455, f = 456 }, c = { m = { { 0.00, "Добро пожаловать в самый главный орган Подгорода: Район Фармацевтов!" }, { 5.69, "Здесь мы экспериментируем с самыми заразными и экзотическими веществами на всём Азероте." }, { 12.71, "Ты застал меня в хорошем настроении, так что я позволю тебе поучаствовать в моём новом расследовании." }, { 20.91, "Похоже, в руинах над нашим прекрасным городом завёлся крайне ядовитый членистоног." }, { 27.63, "Говорят, его токсин разъедает даже плоть нежити." }, { 31.69, "Разве не восхитительно?" }, { 33.61, "Нужно убедиться в достоверности этих слухов." }, { 37.31, "Если эта тварь заразит тебя своим смертельным ядом, приходи ко мне – я возьму образец." } }, f = { { 0.00, "Добро пожаловать в самый главный орган Подгорода: Район Фармацевтов!" }, { 5.59, "Здесь мы экспериментируем с самыми заразными и экзотическими веществами на всём Азероте." }, { 12.48, "Ты застала меня в хорошем настроении, так что я позволю тебе поучаствовать в моём новом расследовании." }, { 20.61, "Похоже, в руинах над нашим прекрасным городом завёлся крайне ядовитый членистоног." }, { 27.21, "Говорят, его токсин разъедает даже плоть нежити." }, { 31.20, "Разве не восхитительно?" }, { 33.09, "Нужно убедиться в достоверности этих слухов." }, { 36.71, "Если эта тварь заразит тебя своим смертельным ядом, приходи ко мне – я возьму образец." } } }, t = { d = 17.3, g = 1, v = "scourge-male", n = { m = 149, f = 150 }, c = { m = { { 0.00, "Ты его убил?!" }, { 1.32, "Хм..." }, { 1.81, "К счастью для тебя, здесь, пожалуй, достаточно слизи, чтобы изучить её свойства." }, { 9.14, "Но не советую тебе наживать врагов в Королевском фармацевтическом обществе." }, { 15.97, "Поди прочь!" } }, f = { { 0.00, "Ты его убила?!" }, { 1.74, "Хм..." }, { 2.23, "К счастью для тебя, здесь, пожалуй, достаточно слизи, чтобы изучить её свойства." }, { 9.56, "Но не советую тебе наживать врагов в Королевском фармацевтическом обществе." }, { 16.39, "Поди прочь!" } } } } },
    [95217] = { d = 16.4, v = "dwarf-male#99", n = { x = 191 }, c = { x = { { 0.00, "Значит, хочешь обучиться кузнечному делу?" }, { 2.97, "Думаю, мы можем помочь друг другу." }, { 5.43, "Груз с припасами запаздывает, а мне нужны материалы, чтобы починить кое-что для лагеря." }, { 11.49, "Если достанешь то, что мне нужно, обучу тебя паре приёмов." }, { 15.60, "Договорились?" } } }, t = { d = 5.7, g = 1, v = "dwarf-male#99", n = { m = 51, f = 51 }, c = { m = { { 0.00, "А ты находчивый." }, { 1.44, "Тогда слушай внимательно – я повторять не буду!" } }, f = { { 0.00, "А ты находчивая." }, { 1.66, "Тогда слушай внимательно – я повторять не буду!" } } } } },
    [95219] = { d = 29.1, g = 1, v = "goblin-female", n = { m = 330, f = 331 }, c = { m = { { 0.00, "Есть ещё работёнка для тебя, детка." }, { 2.35, "Любишь путешествовать?" }, { 3.90, "Гляди – это один из лучших сортов портвейна, какой только можно найти." }, { 8.90, "Но его надо доставить одному моему клиенту аж в крепость Оперённой Луны, что в Фераласе." }, { 14.96, "Как увидишь, что деревья вокруг выше, чем ты когда-либо видел, можешь не сомневаться – ты на месте." }, { 21.70, "Один из моих парней всё плотно упаковал, но всё-таки давай аккуратно, ладно, дружище?" }, { 27.58, "А то рванёт." } }, f = { { 0.00, "Есть ещё работёнка для тебя, детка." }, { 2.35, "Любишь путешествовать?" }, { 3.90, "Гляди – это один из лучших сортов портвейна, какой только можно найти." }, { 8.90, "Но его надо доставить одному моему клиенту аж в крепость Оперённой Луны, что в Фераласе." }, { 14.96, "Как увидишь, что деревья вокруг выше, чем ты когда-либо видела, можешь не сомневаться – ты на месте." }, { 22.49, "Один из моих парней всё плотно упаковал, но всё-таки давай аккуратно, ладно, дружище?" }, { 28.37, "А то рванёт." } } } },
    [95250] = { d = 27.0, g = 1, v = "human-male", n = { x = 317 }, c = { m = { { 0.00, "Что тебе нужно, герой?" }, { 1.52, "Не видишь, у нас тут война?" }, { 3.27, "Мой господин уже бросился в бой, а мне велел оставаться здесь." }, { 7.25, "Но прошло уже довольно много времени." }, { 9.77, "Ты небось и десяти минут в бою не продержишься, но если тебе не хватает ума придумать себе занятие, то поищи моего господина, главнокомандующего." }, { 19.88, "Он самый высокий и статный герой, какого тебе когда-либо доводилось видеть, так что ты его сразу узнаешь." } }, f = { { 0.00, "Что тебе нужно, героиня?" }, { 1.66, "Не видишь, у нас тут война?" }, { 3.45, "Мой господин уже бросился в бой, а мне велел оставаться здесь." }, { 7.49, "Но прошло уже довольно много времени." }, { 10.05, "Ты небось и десяти минут в бою не продержишься, но если тебе не хватает ума придумать себе занятие, то поищи моего господина, главнокомандующего." }, { 20.17, "Он самый высокий и статный герой, какого тебе когда-либо доводилось видеть, так что ты его сразу узнаешь." } } }, t = { d = 29.3, g = 1, v = "human-male", n = { m = 251, f = 253 }, c = { m = { { 0.00, "*Труман с ужасом и отвращением смотрит на голову своего бывшего господина.*" }, { 5.92, "Это что... какая-то шутка?" }, { 7.89, "Зачем ты принёс мне голову этого чудовища?" }, { 10.98, "Убирайся с глаз моих!" }, { 12.55, "Мне следовало знать, что нельзя доверять тому, кто водит дружбу с такой мерзостью." }, { 18.35, "Истинные сыны Лордерона вернут наш дом." }, { 21.76, "И когда мы это сделаем, мы наконец-то сможем очистить его от тварей и от тех, кто якшается с ними, как ты!" } }, f = { { 0.00, "*Труман с ужасом и отвращением смотрит на голову своего бывшего господина.*" }, { 5.76, "Это что... какая-то шутка?" }, { 7.69, "Зачем ты принесла мне голову этого чудовища?" }, { 10.92, "Убирайся с глаз моих!" }, { 12.46, "Мне следовало знать, что нельзя доверять тому, кто водит дружбу с такой мерзостью." }, { 18.33, "Истинные сыны Лордерона вернут наш дом." }, { 21.16, "И когда мы это сделаем, мы наконец-то сможем очистить его от тварей и от тех, кто якшается с ними, как ты!" } } } } },
    [95254] = { d = 22.9, v = "narrator", n = { x = 224 }, c = { x = { { 0.00, "Внимание, удильщики!" }, { 1.72, "Требуется крабье мясо." }, { 3.66, "И не обычные ошмётки, а целая клешня." }, { 6.73, "Я видел огромного краба – он ползает под доками, перерезает леску и жрёт наживку." }, { 13.46, "Награда тому, кто принесёт мне клешню этой громадины, плюс порция блюда, которое я из неё приготовлю." }, { 21.76, "Фимбо Смазляп." } } } },
    [95260] = { d = 23.4, v = "narrator", n = { x = 246 }, c = { x = { { 0.00, "Шкура разрисована широкими мазками рыбьих кишок и чернил осьминога." }, { 5.40, "На ней изображено какое-то морское чудовище с длинной шеей, поднимающееся над водой." }, { 12.00, "Что это за зверь?" }, { 13.35, "Поблизости находится Пороховой порт." }, { 16.19, "Если это чудовище настоящее и обитает в этих водах, кто-то из моряков наверняка его видел." } } }, t = { d = 5.3, g = 1, v = "goblin-male", n = { m = 36, f = 37 }, c = { m = { { 0.00, "Морское чудище...?" }, { 1.68, "Погоди!" }, { 2.40, "Так ты его" }, { 3.36, "тоже видел!?" } }, f = { { 0.00, "Морское чудище...?" }, { 1.68, "Погоди!" }, { 2.40, "Так ты его" }, { 3.36, "тоже видела!?" } } } } },
    [95261] = { d = 34.6, v = "goblin-male", n = { x = 314 }, c = { x = { { 0.00, "Это монстр... с длинной шеей, всё как ты говоришь." }, { 3.85, "Я видел его рядом с островами – с лодки." }, { 7.07, "Я рассказывал" }, { 8.12, "! другим, но не-е-ёт, никто же" }, { 11.13, "! не верит старому Арго." }, { 13.79, "Он же просто... какой-то... пьяный рыбак!" }, { 17.01, "Всё сочиняет!" }, { 18.05, "Мы им покажем... когда я подготовлю наживку..." }, { 21.62, "Эй!" }, { 21.90, "Чего стоишь?" }, { 22.95, "Мне нужны потроха, много потрохов." }, { 25.68, "Любой местной твари." }, { 27.36, "Чем вонючее" }, { 28.27, "!, тем лучше." }, { 30.02, "И ещё нужны гнилогрибы." }, { 31.84, "Они растут в пещере близ Ветроземья." } } } },
    [95262] = { d = 20.9, v = "dwarf-male", n = { x = 251 }, c = { x = { { 0.00, "Об Алькаце мне особо задумываться не приходилось." }, { 3.34, "Насколько мне известно, это заброшенная застава времён Третьей войны, ничем не примечательная." }, { 9.77, "А про тюрьму там и слыхом не слыхать." }, { 12.30, "Ну что ж, делать нечего — надо провести тебя внутрь и посмотреть, что там к чему, особенно если есть шанс, что там держат короля." } } } },
    [95263] = { d = 15.8, g = 1, v = "narrator", n = { m = 0, f = 0 }, c = { m = { { 0.00, "Король мёртв — убит при попытке побега незадолго до нападения наг." }, { 5.01, "Эта страшная весть потрясёт Штормград до основания." }, { 8.85, "Нужно как можно скорее вернуться к Салли и рассказать ему обо всём, что ты узнал." } }, f = { { 0.00, "Король мёртв — убит при попытке побега незадолго до нападения наг." }, { 5.01, "Эта страшная весть потрясёт Штормград до основания." }, { 8.85, "Нужно как можно скорее вернуться к Салли и рассказать ему обо всём, что ты узнала." } } } },
    [95264] = { d = 15.4, v = "dwarf-male", n = { x = 178 }, c = { x = { { 0.00, "Шоу должен узнать об этом как можно скорее." }, { 3.16, "Возвращайся в Штормград и передай ему новости." }, { 6.45, "Прошу тебя, умоляю, никому больше ни слова." }, { 9.62, "Для Штормграда это может обернуться бедой, и действовать тут нужно очень осторожно." } } } },
    [95267] = { d = 26.3, g = 1, v = "goblin-male", n = { m = 259, f = 259 }, c = { m = { { 0.00, "Последняя часть" }, { 1.08, "! совсем простая... просто возьми ком потрохов, и-и-и... запузырь его в воду!" }, { 7.26, "Э-э... только не тут, умоляю." }, { 9.36, "Отправляйся на эти самые..." }, { 11.33, "! мурлочьи острова, где ты нашёл рисунок." }, { 14.83, "Ищи, где в воде плавают свежие обломки, и брось туда наживку." }, { 19.22, "И как только эта башка высунется, сразу её отрубай!" }, { 22.91, "Сделаем из неё украшение... для лодки!" } }, f = { { 0.00, "Последняя часть" }, { 1.08, "! совсем простая... просто возьми ком потрохов, и-и-и... запузырь его в воду!" }, { 7.26, "Э-э... только не тут, умоляю." }, { 9.36, "Отправляйся на эти самые..." }, { 11.33, "! мурлочьи острова, где ты нашла рисунок." }, { 15.69, "Ищи, где в воде плавают свежие обломки, и брось туда наживку." }, { 20.08, "И как только эта башка высунется, сразу её отрубай!" }, { 23.77, "Сделаем из неё украшение... для лодки!" } } } },
    [95278] = { d = 7.7, v = "orc-male#60", n = { x = 79 }, c = { x = { { 0.00, "Угроза серьёзнее, чем мы думали." }, { 2.56, "Надо предупредить всех в Рог'маре." }, { 5.34, "Беги туда и не останавливайся." } } } },
    [95283] = { d = 30.5, v = "orc-male", n = { x = 308 }, c = { x = { { 0.00, "Лок'тар." }, { 0.72, "Мне нужна помощь в одном серьёзном деле." }, { 3.95, "Некоторое время назад мы отправили отряд элитных бойцов Кор'крона в Пылевые топи с особым заданием." }, { 12.01, "Беда в том, что срок их донесения давно прошёл, а от них ни слова." }, { 17.11, "Ступай в деревню Гиблотопь в Пылевых топях и поговори с орком по имени Назир Кровавое Копьё." }, { 24.52, "Никто не знает о положении дел в топях больше него." }, { 28.69, "Выясни всё, что сможешь." } } } },
    [95284] = { d = 36.2, v = "orc-male", n = { x = 361 }, c = { x = { { 0.00, "Несколько дней назад здесь проходил небольшой отряд кор'кронцев." }, { 5.12, "Зачем они пришли, мне не сказали, а я и не спрашивал." }, { 9.37, "Купили припасов, немного отдохнули и двинулись дальше." }, { 13.76, "Кор'кронцы — лучшие из лучших, они крепче копыт элекка, но меня не покидает чувство, что что-то пошло не так." }, { 22.55, "Я краем уха слышал, как один из них упомянул «остров», а прямо у побережья есть остров Алькац." }, { 30.12, "Мерзкое местечко." }, { 31.56, "Собери друзей и выясни, что случилось с этими кор'кронцами." } } } },
    [95285] = { d = 12.7, v = "orc-female", n = { x = 33 }, c = { x = { { 0.00, "*Сержант Улка с трудом пытается сесть, чтобы поговорить с вами.*" }, { 4.92, "*Вы протягиваете ей руку, но она лишь отмахивается.*" }, { 8.72, "Ладно, новобранец..." }, { 10.64, "Введу тебя в курс дела." } } } },
    [95288] = { d = 31.4, g = 1, v = "goblin-female", n = { m = 348, f = 350 }, c = { m = { { 0.00, "У тебя такой вид, будто ты привык делать то, что велят другие." }, { 4.54, "Хорошее качество для шестёрки." }, { 6.68, "Немного тебя поднатаскать, и будешь ценным активом." }, { 10.44, "Давай-ка тебя проверим." }, { 12.19, "Недавно пираты из шайки Восточных Морей умыкнули партию моих честно украденных товаров." }, { 18.61, "Это неспортивно, я украла их первая!" }, { 21.27, "Так что первый урок, шестёрка: не путай берега!" }, { 24.64, "Иди покажи им, что они связались не с тем гоблином, и верни моё барахло." }, { 29.82, "Желательно, силой." } }, f = { { 0.00, "У тебя такой вид, будто ты привыкла делать то, что велят другие." }, { 4.86, "Хорошее качество для шестёрки." }, { 7.00, "Немного тебя поднатаскать, и будешь ценным активом." }, { 10.76, "Давай-ка тебя проверим." }, { 12.51, "Недавно пираты из шайки Восточных Морей умыкнули партию моих честно украденных товаров." }, { 18.93, "Это неспортивно, я украла их первая!" }, { 21.59, "Так что первый урок, шестёрка: не путай берега!" }, { 24.96, "Иди покажи им, что они связались не с тем гоблином, и верни моё барахло." }, { 30.14, "Желательно, силой." } } } },
    [95293] = { d = 32.0, g = 1, v = "goblin-female", n = { m = 376, f = 377 }, c = { m = { { 0.00, "Товары, которые ты отбил у шайки Восточных Морей, должны были доставить напрямую мне." }, { 6.04, "Старина Бенткойн вообразил, что может играть мускулами на моей территории." }, { 11.27, "Торговую войну затевает!" }, { 13.03, "Но мы же цивилизованные, в отличие от некоторых." }, { 16.31, "Урок номер два, шестёрка." }, { 18.07, "Мы не опустимся до их уровня." }, { 20.08, "Возьми этот ящик, который я раздобыла специально для нашего доброго капитана." }, { 25.56, "Его корабль где-то на побережье Восточного Ветра." }, { 29.09, "Наградим его за умение вести переговоры." } }, f = { { 0.00, "Товары, которые ты отбила у шайки Восточных Морей, должны были доставить напрямую мне." }, { 6.16, "Старина Бенткойн вообразил, что может играть мускулами на моей территории." }, { 11.39, "Торговую войну затевает!" }, { 13.15, "Но мы же цивилизованные, в отличие от некоторых." }, { 16.43, "Урок номер два, шестёрка." }, { 18.19, "Мы не опустимся до их уровня." }, { 20.20, "Возьми этот ящик, который я раздобыла специально для нашего доброго капитана." }, { 25.68, "Его корабль где-то на побережье Восточного Ветра." }, { 29.21, "Наградим его за умение вести переговоры." } } } },
    [95294] = { d = 27.0, g = 1, v = "human-male", n = { x = 299 }, c = { m = { { 0.00, "Фриз умеет быть убедительной." }, { 2.05, "Ну, я со своей стороны не против." }, { 4.41, "Пираты Восточных Морей не будут вмешиваться в её дела." }, { 8.31, "За это... может, мы кое о чём договоримся." }, { 11.31, "Трудно быть пиратом, когда обиженный гоблин раз за разом шлёт искателей приключений по твою голову." }, { 18.35, "Возвращайся к своему боссу, герой." }, { 20.84, "Скажи Фриз, что тут новый капитан и он надеется на взаимовыгодное сотрудничество." } }, f = { { 0.00, "Фриз умеет быть убедительной." }, { 2.05, "Ну, я со своей стороны не против." }, { 4.41, "Пираты Восточных Морей не будут вмешиваться в её дела." }, { 8.31, "За это... может, мы кое о чём договоримся." }, { 11.31, "Трудно быть пиратом, когда обиженный гоблин раз за разом шлёт искателей приключений по твою голову." }, { 18.35, "Возвращайся к своему боссу, героиня." }, { 21.56, "Скажи Фриз, что тут новый капитан и он надеется на взаимовыгодное сотрудничество." } } } },
    [95295] = { d = 34.9, g = 1, v = "goblin-female", n = { m = 352, f = 353 }, c = { m = { { 0.00, "Ты хорошо поработал с теми пиратами, шестёрка." }, { 3.28, "Но есть ещё одна вещь, которую тебе надо запомнить." }, { 6.96, "Одни говорят, что мы пираты, другие – что джентльмены удачи." }, { 11.27, "А куда идут джентльмены, чтобы помериться удачей с другими джентльменами?" }, { 16.55, "В Пиратскую Бухту!" }, { 17.84, "*Фриз ждёт, что вы ей ответите.*" }, { 20.40, "Следи за ходом мысли, детка." }, { 22.58, "Я говорю – дуй в Пиратскую Бухту и поговори с моим приятелем." }, { 27.08, "Он получает товар от местных пир... джентльменов удачи." }, { 31.11, "Короче, иди к Раззготу, ясно?" }, { 33.36, "Он всё объяснит." } }, f = { { 0.00, "Ты хорошо поработала с теми пиратами, шестёрка." }, { 3.78, "Но есть ещё одна вещь, которую тебе надо запомнить." }, { 7.46, "Одни говорят, что мы пираты, другие – что джентльмены удачи." }, { 11.77, "А куда идут джентльмены, чтобы помериться удачей с другими джентльменами?" }, { 17.05, "В Пиратскую Бухту!" }, { 18.34, "*Фриз ждёт, что вы ей ответите.*" }, { 20.90, "Следи за ходом мысли, детка." }, { 23.08, "Я говорю – дуй в Пиратскую Бухту и поговори с моим приятелем." }, { 27.58, "Он получает товар от местных пир... джентльменов удачи." }, { 31.61, "Короче, иди к Раззготу, ясно?" }, { 33.86, "Он всё объяснит." } } } },
    [95296] = { d = 27.9, g = 1, v = "goblin-female", n = { m = 330, f = 331 }, c = { m = { { 0.00, "Ты готов к следующему уроку, чемпион." }, { 2.58, "Мне предстоят кое-какие переговоры здесь в городе, дам тебе пару поручений на это время." }, { 8.65, "Садись на следующий корабль в порту и отвези этот ящик моему подельнику в порт Хитрой Шестерёнки." }, { 15.27, "И не смотри на меня так, наверняка будет весело." }, { 18.58, "Заставить гоблина платить по счетам труднее, чем строить местный сброд, не говоря уже о таможне и прочих прелестях." }, { 26.43, "Увидишь – поймёшь." } }, f = { { 0.00, "Ты готова к следующему уроку, чемпион." }, { 2.99, "Мне предстоят кое-какие переговоры здесь в городе, дам тебе пару поручений на это время." }, { 9.06, "Садись на следующий корабль в порту и отвези этот ящик моему подельнику в порт Хитрой Шестерёнки." }, { 15.68, "И не смотри на меня так, наверняка будет весело." }, { 18.99, "Заставить гоблина платить по счетам труднее, чем строить местный сброд, не говоря уже о таможне и прочих прелестях." }, { 26.84, "Увидишь – поймёшь." } } } },
    [95309] = { d = 21.6, v = "orc-female", n = { x = 216 }, c = { x = { { 0.00, "Приказ простой: спустись в подземелья под крепостью и найди командира Фолкара." }, { 6.29, "Если он жив — освободи его и выясни, что, Круговерть Пустоты побери, тут творится." }, { 12.86, "Внизу тебя ждёт целая армия, в одиночку тебе не выжить." }, { 17.42, "Надеюсь, у тебя есть союзники... и желательно сильные." } } } },
    [95312] = { d = 32.1, g = 1, v = "goblin-male#108", n = { m = 349, f = 349 }, c = { m = { { 0.00, "У меня нет денег для Фриз." }, { 1.87, "Ну, то есть они у меня были, но я поставил их на старину Слизнечрева на арене Жужепшика здесь, в Прибамбасске." }, { 9.62, "И нечего так смотреть." }, { 11.24, "Это была разумная инвестиция." }, { 13.43, "Я сорвал куш!" }, { 14.40, "Просто пока не получил свой выигрыш." }, { 17.05, "Если ты новый мальчик на побегушках у Фриз, может, сделаешь это за меня?" }, { 22.28, "А то у меня больная спина и вообще." }, { 24.87, "Ты же не хочешь вернуться к боссу с пустыми руками?" }, { 28.55, "Прибамбасск к западу отсюда, легко найти." } }, f = { { 0.00, "У меня нет денег для Фриз." }, { 1.87, "Ну, то есть они у меня были, но я поставил их на старину Слизнечрева на арене Жужепшика здесь, в Прибамбасске." }, { 9.62, "И нечего так смотреть." }, { 11.24, "Это была разумная инвестиция." }, { 13.43, "Я сорвал куш!" }, { 14.40, "Просто пока не получил свой выигрыш." }, { 17.05, "Если ты новая девочка на побегушках у Фриз, может, сделаешь это за меня?" }, { 22.93, "А то у меня больная спина и вообще." }, { 25.52, "Ты же не хочешь вернуться к боссу с пустыми руками?" }, { 29.20, "Прибамбасск к западу отсюда, легко найти." } } } },
    [95314] = { d = 39.0, v = "scourge-female#141", n = { x = 406 }, c = { x = { { 0.00, "До нашествия Плети уединённая деревушка Тенедол славилась своим шепчущим эликсиром." }, { 6.66, "Его изготавливали из трав, растущих только в Гибели Тира, и даже после того как его запретили продавать в городе, эликсир пользовался большим спросом среди аптекарей, мистиков и ценителей ядов." }, { 22.31, "Уже не один заинтересованный покупатель просил меня его раздобыть." }, { 27.75, "Отправляйся на запад, вглубь Шепчущего леса, – там найдёшь руины Тенедола." }, { 33.61, "Если добудешь мне несколько бутылок, я хорошо заплачу тебе за труды." } } }, t = { d = 28.7, g = 1, v = "scourge-female#141", n = { m = 277, f = 279 }, c = { m = { { 0.00, "Говоришь, в Тенедоле поселилось зло?" }, { 3.01, "Не скажу, что я удивлена." }, { 5.11, "Лесной народ был странноват и в лучшие времена – они никогда не любили посторонних." }, { 12.11, "Многие верят, что весь Шепчущий лес проклят, а эликсир, вываренный из его корней, несёт в себе то же проклятие..." }, { 21.43, "Но хватит о слухах и суевериях, Красавчик." }, { 24.97, "Спасибо, что принёс эликсиры." }, { 27.37, "Вот твоя награда." } }, f = { { 0.00, "Говоришь, в Тенедоле поселилось зло?" }, { 2.92, "Не скажу, что я удивлена." }, { 4.96, "Лесной народ был странноват и в лучшие времена – они никогда не любили посторонних." }, { 11.75, "Многие верят, что весь Шепчущий лес проклят, а эликсир, вываренный из его корней, несёт в себе то же проклятие..." }, { 20.79, "Но хватит о слухах и суевериях, Красавица." }, { 24.22, "Спасибо, что принесла эликсиры." }, { 26.77, "Вот твоя награда." } } } } },
    [95315] = { d = 26.6, v = "human-female#47", n = { x = 327 }, c = { x = { { 0.00, "Один из наших разведчиков докладывает, что крупные силы противника собираются далеко на юге, за Болотиной." }, { 7.06, "Любопытнее всего то, что там, судя по всему, находится поселение Альянса." }, { 11.91, "Фархолд, если не ошибаюсь – знакомое название." }, { 15.03, "Не будем тянуть время." }, { 16.58, "Лучше обо всём поговорить, пока не поздно." }, { 19.40, "У нас и так достаточно проблем." }, { 21.43, "Возьми вот это письмо и вручи его тому, кто представится командиром отделения." } } } },
    [95321] = { d = 25.5, g = 1, v = "goblin-male#65", n = { m = 264, f = 263 }, c = { m = { { 0.00, "Таззик прислал тебя за выигрышем?" }, { 2.53, "Это шутка такая, да?" }, { 4.12, "Его Слизнечрев и двух минут не продержался на арене!" }, { 7.98, "Этот неудачник не выиграл даже ломанного медяка." }, { 11.63, "Не моё это дело, приятель, но на твоём месте я бы дёрнул обратно в порт Хитрой Шестерёнки." }, { 18.08, "Пока ты базаришь со мной, этот крысеныш Таззик наверняка уже садится на корабль." } }, f = { { 0.00, "Таззик прислал тебя за выигрышем?" }, { 2.53, "Это шутка такая, да?" }, { 4.12, "Его Слизнечрев и двух минут не продержался на арене!" }, { 7.98, "Этот неудачник не выиграл даже ломанного медяка." }, { 11.63, "Не моё это дело, подруга, но на твоём месте я бы дёрнул обратно в порт Хитрой Шестерёнки." }, { 19.68, "Пока ты базаришь со мной, этот крысеныш Таззик наверняка уже садится на корабль." } } } },
    [95322] = { d = 30.2, g = 1, v = "goblin-male", n = { m = 331, f = 332 }, c = { m = { { 0.00, "Ты прямо вовремя, дружище!" }, { 1.96, "Я как раз собирался получить товар у пиратов Кровавого Паруса." }, { 6.45, "Они мои кореша." }, { 7.69, "Всегда готовы поставить то, за что Фриз готова башлять." }, { 11.67, "Но, кхм, чисто на всякий случай, хорошо бы ты согласился представлять мои интересы." }, { 17.67, "Хороший караванщик всегда нанимает охрану... чтобы ни у кого не возникало глупых идей." }, { 23.99, "Они сказали, что оставят товар в сундуке на холме за городом." }, { 28.49, "Сходи за ним, ладно?" } }, f = { { 0.00, "Ты прямо вовремя, дружище!" }, { 1.96, "Я как раз собирался получить товар у пиратов Кровавого Паруса." }, { 6.45, "Они мои кореша." }, { 7.69, "Всегда готовы поставить то, за что Фриз готова башлять." }, { 11.67, "Но, кхм, чисто на всякий случай, хорошо бы ты согласилась представлять мои интересы." }, { 18.06, "Хороший караванщик всегда нанимает охрану... чтобы ни у кого не возникало глупых идей." }, { 24.38, "Они сказали, что оставят товар в сундуке на холме за городом." }, { 28.88, "Сходи за ним, ладно?" } } } },
    [95325] = { d = 18.4, v = "goblin-male", n = { x = 204 }, c = { x = { { 0.00, "Я уже заплатил деньги за этот сундучок." }, { 2.95, "Мы же не оставим это просто так!" }, { 5.31, "Хочешь свой товар?" }, { 6.68, "Отправляйся в лагерь Торговой компании на севере и узнай, кто меня так подставил!" }, { 12.58, "Речь уже не только о деньгах." }, { 14.74, "Речь о справедливости!" }, { 16.32, "Ну, и самую чуточку о деньгах." } } } },
    [95326] = { d = 14.1, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "В учётной книге задокументированы все доставки Раззгота." }, { 4.36, "Последняя запись указывает на то, что ценный груз Раззгота был успешно изъят агентом Торговой компании." }, { 12.52, "Товар всё ещё у него." } } } },
    [95327] = { d = 15.8, v = "goblin-male", n = { x = 174 }, c = { x = { { 0.00, "Похоже, уговор есть уговор." }, { 2.03, "Торговая компания получила по заслугам, Фриз — свою добычу, и все довольны." }, { 7.47, "В целом очень гладкая сделка, скажу я тебе." }, { 10.74, "А теперь брысь, у меня скоро очередная поставка от пиратов Южных морей." } } } },
    [95328] = { d = 8.4, v = "narrator", n = { x = 96 }, c = { x = { { 0.00, "Вопреки здравому смыслу, вы собираете извивающиеся останки чудища." }, { 5.02, "Они могут пригодиться кому-нибудь в Подгороде." } } }, t = { d = 16.9, g = 1, v = "scourge-male#83", n = { x = 162 }, c = { m = { { 0.00, "Какой любопытный образец." }, { 2.15, "Говоришь, из-под Шепчущего леса?" }, { 4.89, "Ни для кого не секрет, что это гиблое место отмечено Бездной." }, { 10.00, "Я рад любой возможности изучить тайны тьмы, герой." }, { 14.15, "Позволь заплатить тебе за находку." } }, f = { { 0.00, "Какой любопытный образец." }, { 2.12, "Говоришь, из-под Шепчущего леса?" }, { 4.82, "Ни для кого не секрет, что это гиблое место отмечено Бездной." }, { 9.86, "Я рад любой возможности изучить тайны тьмы, героиня." }, { 14.10, "Позволь заплатить тебе за находку." } } } } },
    [95329] = { d = 25.2, v = "human-male", n = { x = 303 }, c = { x = { { 0.00, "У нас есть сторожевая башня, выходящая на северные равнины." }, { 4.05, "Она служит наблюдательным пунктом для отслеживания перемещений Орды." }, { 8.78, "Дозорного на этой башне зовут Корнелий." }, { 11.58, "Поговори с ним и забери отчёт о ситуации." }, { 14.38, "Он там совсем один, поэтому я стараюсь почаще его проведывать." }, { 18.74, "Но предупреждаю: он... не очень любит разговоры." }, { 22.04, "Потому его и отправили на такой отдалённый пост." } } }, t = { d = 10.8, v = "human-male", n = { x = 126 }, c = { x = { { 0.00, "Обстановка?" }, { 0.81, "Да докладывать особо нечего." }, { 2.81, "Равнина, как всегда, кишит орками, а вся помощь, которую Демар соизволит мне прислать, — это желторотики вроде тебя." } } } } },
    [95330] = { d = 30.8, v = "human-female", n = { x = 363 }, c = { x = { { 0.00, "У нас с мужем ферма к северу отсюда." }, { 2.49, "Время от времени я прихожу в Фархолд, чтобы продать урожай." }, { 6.57, "А если сезон был хороший, то ещё и откладываю немного, чтобы раздать тем, кому меньше повезло в жизни." }, { 13.49, "Надо же и о соседях заботиться, верно?" }, { 16.11, "К северу от нашей фермы, прямо на реке, есть лесопилка." }, { 19.88, "Наверняка там пригодятся фрукты и овощи, а то еда у них очень однообразная." }, { 24.92, "Если отправляешься в ту сторону, отнеси вот это их бригадиру?" }, { 29.06, "Его зовут Халлиган Тернер." } } }, t = { d = 12.6, v = "human-male", n = { x = 149 }, c = { x = { { 0.00, "Вилеры слишком добры!" }, { 1.53, "Кассандра права, мы тут почти ничего, кроме мяса и хлеба, не едим." }, { 6.12, "Прослежу, чтобы всем досталось." }, { 8.26, "Спасибо за подарок." }, { 9.60, "Надо будет как-нибудь отплатить ей за доброту." } } } } },
    [95349] = { d = 33.0, g = 1, v = "skyborne-female", n = { m = 352, f = 353 }, c = { m = { { 0.00, "Из-за недавних событий, связанных с культом, мне придётся отложить путешествие по Азероту и на время остаться в Валанааре." }, { 8.82, "Вместо меня мы отправим отряд Ваятелей ветра – ты будешь в числе этих первопроходцев." }, { 15.13, "Алаана Штормовой Полёт встретит тебя в Мулгоре." }, { 18.62, "Пока мы занимаемся делами здесь, советую тебе начать исследовать Азерот." }, { 23.95, "Скоро мы тоже туда прибудем." }, { 26.12, "Когда будешь готов, иди на ближний причал и садись на неборез." }, { 30.80, "Бану-ала." } }, f = { { 0.00, "Из-за недавних событий, связанных с культом, мне придётся отложить путешествие по Азероту и на время остаться в Валанааре." }, { 9.22, "Вместо меня мы отправим отряд Ваятелей ветра – ты будешь в числе этих первопроходцев." }, { 15.83, "Алаана Штормовой Полёт встретит тебя в Мулгоре." }, { 19.48, "Пока мы занимаемся делами здесь, советую тебе начать исследовать Азерот." }, { 25.06, "Скоро мы тоже туда прибудем." }, { 27.33, "Когда будешь готова, иди на ближний причал и садись на неборез." }, { 32.28, "Бану-ала." } } }, t = { d = 24.2, g = 1, v = "skyborne-female", n = { m = 250, f = 254 }, c = { m = { { 0.00, "Ещё один искатель приключений с Зефриса?" }, { 3.18, "Чудесно." }, { 3.89, "Ветра благоволят нам!" }, { 5.59, "Мы пока только обустраиваемся, поэтому у тебя есть время, чтобы исследовать эту новую землю." }, { 12.94, "Азерот – новое для нас, удивительное и опасное место." }, { 17.11, "Советую тебе подготовиться к дальнейшим приключениям, изучив для начала земли вокруг." } }, f = { { 0.00, "Ещё одна искательница приключений с Зефриса?" }, { 3.50, "Чудесно." }, { 4.22, "Ветра благоволят нам!" }, { 5.94, "Мы пока только обустраиваемся, поэтому у тебя есть время, чтобы исследовать эту новую землю." }, { 13.38, "Азерот – новое для нас, удивительное и опасное место." }, { 17.60, "Советую тебе подготовиться к дальнейшим приключениям, изучив для начала земли вокруг." } } } } },
    [95350] = { d = 33.3, v = "skyborne-female", n = { x = 344 }, c = { x = { { 0.00, "Здесь, внизу, раскинулся большой мир, и новые союзники – ключ к нашему выживанию." }, { 6.45, "Служители Земли – часть Орды, объединяющей много гордых единомышленников." }, { 12.33, "Город Громовой Утёс – одно из поселений Орды, а к востоку находится её столица Оргриммар." }, { 19.51, "Обратись к распорядителю полётов в центре Громового Утёса, чтобы полететь в Оргриммар, и переговори с вождём Орды Траллом от имени Ваятелей ветра." }, { 31.11, "Пусть ветра направляют тебя." } } }, t = { d = 27.4, g = 1, v = "named/thrall", n = { m = 250, f = 254 }, c = { m = { { 0.00, "Лок-тар, герой." }, { 1.41, "Я Тралл, вождь Орды." }, { 3.14, "Посланник Служителей Земли сказал, что со мной хочет поговорить представитель Ваятелей ветра, и вот ты здесь." }, { 12.46, "Не думал, что увижу высшего эльфа здесь, в Оргриммаре, однако добро пожаловать, гость Орды." }, { 20.38, "Можешь свободно путешествовать в наших землях." }, { 24.46, "Ступай с честью, Ваятель ветра." } }, f = { { 0.00, "Лок-тар, героиня." }, { 1.55, "Я Тралл, вождь Орды." }, { 3.26, "Посланник Служителей Земли сказал, что со мной хочет поговорить представитель Ваятелей ветра, и вот ты здесь." }, { 12.52, "Не думал, что увижу высшего эльфа здесь, в Оргриммаре, однако добро пожаловать, гость Орды." }, { 20.37, "Можешь свободно путешествовать в наших землях." }, { 24.41, "Ступай с честью, Ваятельница ветра." } } } } },
    [95383] = { d = 26.4, v = "goblin-male", n = { x = 241 }, c = { x = { { 0.00, "*Управляющий пристанью Паропшик оценивает предложенную вами взятку.*" }, { 5.28, "О-хо-хо!" }, { 5.91, "Старушка Фриз хорошо готовит новое поколение." }, { 9.09, "Извиняюсь за задержку." }, { 10.66, "Тебе надо доставить ящик кому-то в городе, да?" }, { 13.97, "Я ничего об этом не знаю, но если бы знал, то поговорил бы с Таззиком в порту." }, { 19.35, "Он таким интересуется." }, { 20.91, "Только давай по-быстрому, лады?" }, { 23.17, "Чтобы ребятам не пришло в голову всякое-разное." } } } },
    [95384] = { d = 18.9, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Странные символы, которыми испещрён магический свиток, приводят вас в недоумение." }, { 6.11, "Хотя язык, на котором написан текст, вам незнаком, вы не чувствуете тут никаких опасных сил." }, { 13.05, "Возможно, свиток заинтересует какого-нибудь коллекционера магических редкостей." } } } },
    [95385] = { d = 15.7, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Обрывок свитка источает слабую магию." }, { 3.07, "Язык вам незнаком, но вы не чувствуете никакой опасности." }, { 7.56, "Большинство сочтёт этот пергамент бесполезным, но, возможно, найдётся коллекционер, которому он пригодится." } } } },
    [95417] = { d = 25.0, g = 1, v = "creature/ogre", n = { m = 211, f = 211 }, c = { m = { { 0.00, "Друзья Пальцешмяка уходят." }, { 2.51, "Кто-то насовсем." }, { 4.11, "Кто-то возвращается, но лиловый." }, { 7.12, "Странно, да?" }, { 8.29, "Лиловые злые, больше не друзья." }, { 11.31, "Но где другие?" }, { 12.65, "Почему не вернулись?" }, { 14.58, "Загадка..." }, { 15.58, "Ты сильно бьёшь." }, { 17.09, "Найдёшь друзей Пальцешмяка?" }, { 19.61, "Там, в пещере?" }, { 20.95, "Или станешь лиловый." }, { 22.96, "Тоже будет странно." } }, f = { { 0.00, "Друзья Пальцешмяка уходят." }, { 2.51, "Кто-то насовсем." }, { 4.11, "Кто-то возвращается, но лиловый." }, { 7.12, "Странно, да?" }, { 8.29, "Лиловые злые, больше не друзья." }, { 11.31, "Но где другие?" }, { 12.65, "Почему не вернулись?" }, { 14.58, "Загадка..." }, { 15.58, "Ты сильно бьёшь." }, { 17.09, "Найдёшь друзей Пальцешмяка?" }, { 19.61, "Там, в пещере?" }, { 20.95, "Или станешь лиловая." }, { 23.27, "Тоже будет странно." } } } },
    [95418] = { d = 40.5, v = "creature/ogre", n = { x = 367 }, c = { x = { { 0.00, "Пальцешмяк больше не с сумеречными!" }, { 3.08, "Пальцешмяк – свободный огр." }, { 5.44, "Найду Клагобоя." }, { 6.87, "Он огромный огр." }, { 8.29, "Самый большой из всех, что видел Пальцешмяк." }, { 12.15, "Он ушёл от сумеречных." }, { 14.05, "Забрал много друзей." }, { 15.94, "Моя очередь." }, { 17.12, "Пойду к свободным ограм." }, { 19.33, "К холмам, как они." }, { 20.99, "Пальцешмяк скучает по холмам." }, { 23.59, "Больше не будет долбить камни." }, { 26.36, "Заглянешь как-нибудь, а?" }, { 28.49, "Подожду здесь, пока всё уляжется, и пойду." }, { 32.20, "Забери головы Чогг'Зака, отнеси друзьям." }, { 35.83, "Хотя нет." }, { 36.69, "Отнеси одну." }, { 37.88, "Другую – мне." }, { 39.06, "Так будет честно." } } } },
    [95420] = { d = 40.7, v = "orc-male", n = { x = 410 }, c = { x = { { 0.00, "Эти огры-отщепенцы явно не на стороне Сумеречного Молота." }, { 4.76, "В прошлом мы, орки, не раз сражались плечом к плечу с ограми." }, { 9.74, "Возможно, настало время вновь обратиться к этим былым союзникам." }, { 15.02, "А эта голова поможет их убедить." }, { 17.73, "До нас доходили вести о передвижении огров на северных холмах." }, { 22.78, "Если твой новый приятель Пальцешмяк не ошибся, этот клан огров обосновался именно там." }, { 29.81, "Отправляйся в их крепость и предложи этот трофей в знак нашей доброй воли." }, { 35.89, "Надеюсь, они выслушают тебя, прежде чем пожелают растоптать." } } } },
    [95424] = { d = 18.8, g = 1, v = "creature/ogre", n = { m = 143, f = 143 }, c = { m = { { 0.00, "Здесь огры ценят силу и кровь." }, { 2.95, "Кто слабый, тот уходит из Болдер'ока." }, { 6.50, "Обратно в Сумеречный Молот." }, { 9.19, "Ты мелкий." }, { 10.23, "Но, может, сильный." }, { 12.14, "Покажи Клагобою силу." }, { 14.31, "Побей слабых огров." }, { 16.30, "Если сможешь." } }, f = { { 0.00, "Здесь огры ценят силу и кровь." }, { 2.95, "Кто слабый, тот уходит из Болдер'ока." }, { 6.50, "Обратно в Сумеречный Молот." }, { 9.06, "Ты мелкая." }, { 10.64, "Но, может, сильная." }, { 13.44, "Покажи Клагобою силу." }, { 15.61, "Побей слабых огров." }, { 17.60, "Если сможешь." } } } },
    [95425] = { d = 29.8, v = "creature/ogre", n = { x = 258 }, c = { x = { { 0.00, "Клунк был лучшим воином Клагобоя." }, { 3.08, "Сильным." }, { 3.92, "Клагобой дал Клунку мощное оружие." }, { 7.17, "Но Клагобой ошибся." }, { 9.00, "Клунк – слабак, как и другие." }, { 11.67, "Ушёл из Болдер'ока." }, { 13.42, "Вернулся в Сумеречный Молот." }, { 16.09, "Увёл других огров в пещеру, к востоку от воды." }, { 20.42, "Забрал мощное оружие!" }, { 22.51, "Это вещь Клагобоя!" }, { 24.26, "Проломи Клунку череп и забери Череполом." }, { 28.09, "Никакой он не воин!" } } } },
    [95426] = { d = 32.0, v = "human-male", n = { x = 372 }, c = { x = { { 0.00, "Доставка припасов в эти земли – непростая задача." }, { 3.55, "Нас со всех сторон окружают беспринципные негодяи, желающие урвать любой лакомый кусочек." }, { 9.83, "Однако это даёт нам шанс притормозить развитие Рог'мара." }, { 13.76, "Что скажешь, вставим палки в колёса наших соседей-орков?" }, { 17.75, "Иди на север от Рог'мара, к тренировочной площадке, и перехвати их грузы." }, { 22.89, "На восстановление припасов уйдёт столько времени, что наши войска останутся боеготовыми, а вот их... думаю, ты видишь, к чему я веду." } } } },
    [95427] = { d = 17.0, v = "creature/ogre", n = { x = 146 }, c = { x = { { 0.00, "Друзья Пальцешмяка... мертвы?" }, { 2.72, "Почему?" }, { 3.46, "Это Чогг'Зак виноват!" }, { 5.52, "Сказал, что так огры станут сильными!" }, { 8.97, "Он солгал!" }, { 9.96, "Больше не буду долбить камни!" }, { 12.76, "Вперёд, кроха!" }, { 14.08, "Лучше раздолбим башки Чогг'Зака!" } } } },
    [95428] = { d = 14.5, g = 1, v = "creature/ogre", n = { m = 127, f = 128 }, c = { m = { { 0.00, "Кроха-герой хорошо побил сумеречных." }, { 3.23, "Может, твоя Орда не такая слабая." }, { 6.23, "Разрешаю остаться в Болдер'оке." }, { 8.93, "Пока что." }, { 9.77, "Скажи другим мелким, что скоро мы прольём ещё крови." } }, f = { { 0.00, "Кроха-героиня хорошо побила сумеречных." }, { 3.63, "Может, твоя Орда не такая слабая." }, { 6.63, "Разрешаю остаться в Болдер'оке." }, { 9.33, "Пока что." }, { 10.17, "Скажи другим мелким, что скоро мы прольём ещё крови." } } } },
    [95431] = { d = 29.8, v = "orc-male#60", n = { x = 316 }, c = { x = { { 0.00, "Я проследил за передвижением сил врага и обнаружил уязвимость." }, { 4.79, "Всё больше огров жаждет быть свободными, как их собратья из Болдер'ока, и восстаёт против сектантов." }, { 12.46, "О твоих поступках уже разошлась молва – надо этим воспользоваться." }, { 17.74, "Я заметил, как к пещерам приближается воин из Болдер'ока." }, { 22.18, "Видать, хочет вызволить своих братьев и сестёр." }, { 25.91, "Найди его и помоги поднять его народ на восстание." } } } },
    [95432] = { d = 17.9, g = 1, v = "creature/ogre", n = { m = 150, f = 152 }, c = { m = { { 0.00, "Краг'рог прослышал, как кроха-герой спасает огров." }, { 4.62, "Захотел тоже огров спасти." }, { 7.14, "Разгромим сумеречных вместе." }, { 9.73, "Я и малыш-герой." }, { 11.27, "Кости им переломаем." }, { 13.14, "Заставим верещать." }, { 14.84, "Спасём огров!" }, { 16.05, "А к обеду будем дома." } }, f = { { 0.00, "Краг'рог прослышал, как кроха-героиня спасает огров." }, { 4.78, "Захотел тоже огров спасти." }, { 7.29, "Разгромим сумеречных вместе." }, { 9.89, "Я и малышка-героиня." }, { 11.75, "Кости им переломаем." }, { 13.62, "Заставим верещать." }, { 15.32, "Спасём огров!" }, { 16.53, "А к обеду будем дома." } } } },
    [95433] = { d = 29.7, v = "creature/ogre", n = { x = 269 }, c = { x = { { 0.00, "Когда Клагобой уходил от сумеречных, один огр встал на пути." }, { 5.40, "Морг." }, { 5.89, "Морг огроменный." }, { 7.34, "Почти как Клагобой." }, { 9.11, "Но не огроменнейший." }, { 10.89, "Окружил себя мелкими для защиты." }, { 13.87, "Смухлевал, не дал Клагобою честного боя." }, { 17.50, "Мы тоже смухлюем." }, { 19.11, "Найди Морга." }, { 20.32, "Приведи побольше мелких." }, { 22.58, "Убей его." }, { 23.55, "Отнеси булаву Клагобою." }, { 25.73, "Так сумеречные поймут, что к нам не надо лезть!" } } } },
    [95454] = { d = 35.8, v = "orc-male", n = { x = 346 }, c = { x = { { 0.00, "Рука, которой я держу топор, сломана, а почти все мои лучшие воины погибли." }, { 6.34, "Теперь честь Кор'крона — в твоих руках." }, { 9.59, "Нас послали сюда вызволить узника, но не простого узника..." }, { 14.45, "Мы пришли за королём Штормграда, Варианом Ринном." }, { 18.44, "Мы перехватили сведения, что его держат здесь, и вождь приказал нам доставить его в Оргриммар живым." }, { 26.55, "А чёрные драконы... всё усложняют." }, { 29.28, "Тебе нужно идти дальше и найти Ринна." }, { 32.52, "Я подожду тебя здесь, пока ты его ищешь." } } } },
    [95472] = { d = 8.4, v = "goblin-male#108", n = { x = 92 }, c = { x = { { 0.00, "Говорю же, не могу я вернуть Фриз долг!" }, { 2.74, "У меня ничего не осталось, кроме рубахи на спине!" }, { 6.31, "Чего ты так на меня смотришь..." } } } },
    [95483] = { d = 22.6, v = "orc-male", n = { x = 226 }, c = { x = { { 0.00, "Тралл должен знать, что здесь произошло." }, { 3.12, "Я встречусь с Улкой и прослежу, чтобы она смогла выдержать дорогу, а уже потом вернусь в Оргриммар." }, { 11.25, "Так что доверяю тебе доставить эти вести вождю вместо меня." }, { 16.18, "Ступай, боец Орды." }, { 17.78, "Расскажи нашему вождю, какая участь постигла Вариана Ринна." } } } },
    [95494] = { d = 24.2, v = "orc-male#126", n = { x = 251 }, c = { x = { { 0.00, "Мне нужен кто-нибудь с прямыми руками и свободным временем, чтобы раздобыть несколько львиных шкур." }, { 7.80, "Стыдно просить об этом постороннего, но меня ранили в ногу совсем недавно." }, { 13.75, "Пока что я не в состоянии идти на охоту, но обязанности никуда не денутся." }, { 19.56, "Лучшие шкуры бывают у зверей покрупнее, так что начни с них." } } }, t = { d = 17.4, v = "orc-male#126", n = { x = 184 }, c = { x = { { 0.00, "Да, эти вполне сгодятся." }, { 1.95, "Я договорился с местным дубильщиком, что буду приносить шкуры в обмен на готовые кожаные изделия, нужные для моего промысла." }, { 11.54, "Пока я ещё ни разу его не подвёл и не собираюсь начинать даже с раненой ногой." } } } } },
    [95495] = { d = 25.2, v = "orc-male#126", n = { x = 254 }, c = { x = { { 0.00, "Эти шкуры предназначены для дубильщика, с которым я часто веду торговлю." }, { 5.85, "Он что-то вроде отшельника и живёт один на гряде позади меня." }, { 10.83, "Сейчас мне будет трудновато туда подняться, так что буду признателен, если доставишь товар." }, { 18.20, "Ах да, и насчёт его... внешности." }, { 20.80, "Не беспокойся, он совершенно безобиден." }, { 23.91, "Клянусь, это так." } } }, t = { d = 11.5, g = 1, v = "human-male", n = { m = 117, f = 118 }, c = { m = { { 0.00, "Значит, тебя прислал Вранг?" }, { 2.18, "Что ж, хорошо." }, { 3.30, "Спасибо, что доставил мне эти шкуры." }, { 6.19, "Жаль, что Вранг не смог прийти сам." }, { 8.79, "Мне нужно кое о чём с ним поговорить." } }, f = { { 0.00, "Значит, тебя прислал Вранг?" }, { 2.14, "Что ж, хорошо." }, { 3.24, "Спасибо, что доставила мне эти шкуры." }, { 6.13, "Жаль, что Вранг не смог прийти сам." }, { 8.68, "Мне нужно кое о чём с ним поговорить." } } } } },
    [95507] = { d = 18.3, v = "orc-male#126", n = { x = 180 }, c = { x = { { 0.00, "А ещё ты мне очень поможешь, если проверишь мои ловушки." }, { 4.66, "Они расставлены по всей долине." }, { 7.24, "Принеси любую мелкую дичь, которая в них попалась." }, { 11.38, "Только смотри, чтобы какой зверь не напал на тебя." }, { 15.59, "В этих краях лучше не отвлекаться." } } }, t = { d = 9.3, g = 1, v = "orc-male#126", n = { x = 89 }, c = { m = { { 0.00, "Спасибо за помощь, герой." }, { 2.03, "Я уже начал думать, что из-за этой проклятой раны на ноге придётся ложиться спать голодным." } }, f = { { 0.00, "Спасибо за помощь, героиня." }, { 2.20, "Я уже начал думать, что из-за этой проклятой раны на ноге придётся ложиться спать голодным." } } } } },
    [95508] = { d = 21.6, v = "human-male", n = { x = 242 }, c = { x = { { 0.00, "Да, раньше я состоял в култирасском флоте." }, { 3.01, "После того как лорд-адмирал занял Терамор и начал свою кампанию в Дуротаре, у меня появились..." }, { 9.85, "\"возражения\" насчёт его действий." }, { 12.21, "Особенно всего, что касалось убийства мирного населения." }, { 16.24, "Всё не совсем так просто, но..." }, { 18.42, "Постой..." }, { 19.12, "Что это?" }, { 19.76, "На гряду поднимается отряд!" } } }, t = { d = 16.7, g = 1, v = "human-male", n = { x = 151 }, c = { m = { { 0.00, "Что ж, похоже, все живы." }, { 1.94, "Я... знал, что однажды прошлое меня настигнет." }, { 5.61, "Я у тебя в долгу за сегодняшнюю помощь." }, { 8.78, "Прошу, возьми это." }, { 10.36, "Немного, но это самое меньшее, что я могу сделать." }, { 14.46, "Счастливого пути, герой." } }, f = { { 0.00, "Что ж, похоже, все живы." }, { 1.97, "Я... знал, что однажды прошлое меня настигнет." }, { 5.70, "Я у тебя в долгу за сегодняшнюю помощь." }, { 8.91, "Прошу, возьми это." }, { 10.52, "Немного, но это самое меньшее, что я могу сделать." }, { 14.68, "Счастливого пути, героиня." } } } } },
    [95511] = { d = 34.0, g = 1, v = "nightelf-female", n = { m = 394, f = 395 }, c = { m = { { 0.00, "Приветствую, друг мой!" }, { 1.49, "Сегодня для тебя важный день – ты выберешь себе первого саблезуба." }, { 6.07, "Не знаю, в курсе ты или нет, но эти звери чрезвычайно умны и верны своему ездоку." }, { 11.76, "Ты нигде не найдёшь более благородного и упорного спутника." }, { 15.78, "Поэтому тебя ждёт важный выбор." }, { 18.01, "Тебе с твоим саблезубом предстоят долгие странствия вместе, так что выбирай с умом!" }, { 23.77, "Но не бойся – какой бы выбор ты ни сделал, он наверняка будет правильным." }, { 28.78, "Ступай, осмотри саблезубов и возвращайся ко мне, когда определишься." } }, f = { { 0.00, "Приветствую, друг мой!" }, { 1.49, "Сегодня для тебя важный день – ты выберешь себе первого саблезуба." }, { 6.07, "Не знаю, в курсе ты или нет, но эти звери чрезвычайно умны и верны своему ездоку." }, { 11.76, "Ты нигде не найдёшь более благородного и упорного спутника." }, { 15.78, "Поэтому тебя ждёт важный выбор." }, { 18.01, "Тебе с твоим саблезубом предстоят долгие странствия вместе, так что выбирай с умом!" }, { 23.77, "Но не бойся – какой бы выбор ты ни сделала, он наверняка будет правильным." }, { 29.53, "Ступай, осмотри саблезубов и возвращайся ко мне, когда определишься." } } } },
    [95534] = { d = 32.3, v = "narrator", n = { x = 186 }, c = { x = { { 0.00, "Записка обгорела в нескольких местах, но часть ещё можно прочесть." }, { 5.47, "Ходят слухи, что эти старые мехи оживают, когда никто не видит, и начинают работать сами по себе." }, { 13.80, "Мне плевать, сказочки или нет – доберись до сути, выясни всё до конца к моему возвращению!" }, { 21.30, "В Странбраде сокрыта огромная сила!" }, { 24.30, "Я это знаю." }, { 25.35, "Остальная часть записки сгорела." }, { 28.05, "Судя по всему, то был не простой огонь, а магический." } } }, t = { d = 16.9, v = "scourge-female", n = { x = 143 }, c = { x = { { 0.00, "Значит, в старых мехах в Странбраде жил огненный элементаль?" }, { 5.77, "Настоящая загадка, пожалуй, – как он туда попал." }, { 10.42, "Как бы то ни было, хорошая работа." }, { 13.69, "Твои старания будут вознаграждены." } } } } },
    [95555] = { d = 23.4, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "От посоха исходит болезненная энергия, полностью искажающая естественные потоки магии вокруг вас." }, { 7.72, "Несмотря на это, вы почему-то не можете выпустить его из рук." }, { 12.58, "Где-то вдали вы ощущаете отклик такой же мерзкой энергии, и он манит вас." }, { 18.44, "Возможно, вам удастся найти источник этого проклятого предмета." } } } },
    [95561] = { d = 26.6, v = "human-female", n = { x = 191 }, c = { x = { { 0.00, "*По крепости Фархолд разносится громкий плач малышки Донбрайт.*" }, { 5.44, "*Тесса устало улыбается вам.*" }, { 7.84, "О, привет тебе." }, { 9.06, "Прости за шум – Эмма сегодня сама не своя, и я всё не могу понять, почему." }, { 14.67, "Может, её надо покормить." }, { 16.63, "Можешь принести нам немножко еды?" }, { 19.20, "Муж вышел за припасами, а я и тут-то не справляюсь." }, { 22.99, "Если отыщешь пару яблок, я сделаю вкусное пюре." } } }, t = { d = 14.7, g = 1, v = "human-female", n = { m = 92, f = 93 }, c = { m = { { 0.00, "Огромное спасибо." }, { 1.53, "Выглядят просто восхитительно." }, { 4.12, "Скажи спасибо, Эмма." }, { 5.95, "Поблагодари доброго героя." }, { 8.16, "*Малышка отказывается от еды и продолжает плакать.*" }, { 12.48, "Хм." }, { 12.93, "Видимо, нет." } }, f = { { 0.00, "Огромное спасибо." }, { 1.53, "Выглядят просто восхитительно." }, { 4.12, "Скажи спасибо, Эмма." }, { 5.95, "Поблагодари добрую героиню." }, { 8.56, "*Малышка отказывается от еды и продолжает плакать.*" }, { 12.88, "Хм." }, { 13.33, "Видимо, нет." } } } } },
    [95562] = { d = 37.8, v = "human-female", n = { x = 429 }, c = { x = { { 0.00, "Я должна тебе кое в чём признаться." }, { 2.56, "Госпожа Амберхолл действительно отправила меня за образцами, но на самом деле я вызвалась добровольно." }, { 9.80, "Светогладь была моим домом до того, как её забрала война." }, { 13.96, "Я не смогу успокоиться, зная, что её по-прежнему оскверняют чудовища, будь они из Орды или Сумеречного Молота." }, { 21.77, "Мы не победим, пытаясь почерпнуть у них знания." }, { 25.10, "У них нечему учиться." }, { 26.64, "Они просто звери, только и всего, и их надо убить, как зверей." }, { 31.18, "Сразим их владыку в глубине пещеры и положим нашествию конец." }, { 35.60, "Уверена, моя госпожа всё поймёт." } } }, t = { d = 7.6, g = 1, v = "human-female", n = { m = 68, f = 70 }, c = { m = { { 0.00, "Всё кончено?" }, { 1.05, "Ты убил огров?" }, { 2.32, "Ты поступил правильно." }, { 4.19, "А теперь давай выбираться отсюда." } }, f = { { 0.00, "Всё кончено?" }, { 1.05, "Ты убила огров?" }, { 2.81, "Ты поступила правильно." }, { 4.93, "А теперь давай выбираться отсюда." } } } } },
    [95599] = { d = 16.7, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Ключ покрыт толстым слоем ржавчины — похоже, он очень долго пролежал под водой." }, { 6.15, "Где-то поблизости должен быть подходящий к нему замок, но его придётся поискать." }, { 12.31, "Может, стоит начать с пруда к юго-западу от этого лагеря?" } } } },
    [95601] = { d = 20.6, v = "creature/ogre", n = { x = 0 }, c = { x = { { 0.00, "*Похоже, этот мёртвый огр – один из исчезнувших друзей Пальцешмяка.*" }, { 5.01, "*Судя по всему, культ Сумеречного Молота проводит над участниками ритуалы, усиливающие некоторых и убивающие остальных.*" }, { 13.92, "*Надо остановить сектантов, пока кошмарных порождений их ритуалов не стало слишком много.*" } } } },
    [95602] = { d = 44.2, v = "creature/ogre", n = { x = 380 }, c = { x = { { 0.00, "Не люблю камни долбить." }, { 2.20, "Весь день долбить надо." }, { 4.32, "Чогг'Зак велел." }, { 5.78, "Он главный." }, { 6.84, "Сказал, мы давили мелких, а теперь работаем на мелких." }, { 11.81, "Это ж глупо..." }, { 13.20, "Зачем камни долбить?" }, { 15.15, "Не знаю." }, { 15.97, "В камнях светляки." }, { 17.68, "Видать, Чогг'Заку нравятся." }, { 20.21, "Тебе тоже светляков надо?" }, { 22.65, "Другие не дадут." }, { 24.20, "Им свет нравится." }, { 25.75, "Даже картинки с ним рисуют." }, { 28.27, "Пальцешмяк не понимает." }, { 30.39, "Ему от света плохо." }, { 32.26, "Не люблю свет." }, { 33.57, "Крушить свет, крушить картинки!" }, { 36.42, "Но тогда Чогг'Зак взбесится." }, { 39.03, "Шмякнет Пальцешмяка." }, { 40.90, "Так не надо." }, { 42.04, "Но если кто-то другой..." } } } },
    [95603] = { d = 29.6, v = "human-female", n = { x = 360 }, c = { x = { { 0.00, "С тех пор как мы с братом Лоули стали служить Фархолду как простые миряне, церковь начала потихоньку разрушаться." }, { 7.57, "Я всем сердцем надеюсь, что когда война закончится, мы сможем вновь принести Свет в эти земли." }, { 13.87, "Правда, боюсь, до этого ещё далеко..." }, { 16.41, "Как бы то ни было, надо поддерживать церковь в приличном состоянии и надеяться на лучшее." }, { 22.35, "Ну так вот, на верхних этажах завелись нетопыри." }, { 25.56, "Нам бы очень пригодилась твоя помощь, чтобы избавиться от них." } } }, t = { d = 3.6, g = 1, v = "human-female", n = { x = 22 }, c = { m = { { 0.00, "У тебя добрая душа, герой." }, { 2.73, "Спасибо." } }, f = { { 0.00, "У тебя добрая душа, героиня." }, { 2.89, "Спасибо." } } } } },
    [95613] = { d = 27.4, v = "human-female", n = { x = 318 }, c = { x = { { 0.00, "Службы в нашей церкви больше не проходят, но для меня важно хотя бы менять свечи у могил в церковной крипте." }, { 7.42, "Это символ того, что мёртвые не забыты, а их жертва не была напрасной." }, { 12.17, "Прошу тебя, достань свечей, чтобы я могла продолжать этот обычай." }, { 16.73, "Для меня это очень много значит." }, { 19.04, "Если не знаешь, где их найти, поговори с Марлой в доме по соседству с церковью." }, { 24.40, "Мы с ней дружны, и у неё могут найтись лишние." } } }, t = { d = 4.2, v = "human-female", n = { x = 41 }, c = { x = { { 0.00, "Они прекрасно подойдут." }, { 2.12, "Ещё раз спасибо за помощь." } } } } },
    [95615] = { d = 23.2, v = "human-female", n = { x = 265 }, c = { x = { { 0.00, "Если ты не против, я хочу доверить зажжение памятных свечей тебе." }, { 4.73, "Отправляйся на кладбище и везде, где увидишь погасшие свечи, замени их на новые." }, { 10.42, "Конечно, с обычными твоими приключениями это не сравнится." }, { 14.57, "Но пусть это будет для тебя поводом задуматься и послужить тем, кто ушёл раньше нас, чтобы мы жили и делали этот мир лучше." } } }, t = { d = 11.3, v = "human-female", n = { x = 115 }, c = { x = { { 0.00, "Души наших павших взирают на тебя с теплом и благодарностью — как и я." }, { 5.54, "Спасибо, что помогаешь церкви жить." }, { 8.31, "Да направит и защитит тебя Свет в пути." } } } } },
    [95621] = { d = 21.2, v = "human-male", n = { x = 249 }, c = { x = { { 0.00, "Сегодня утром я заметил группу людей, ищущих что-то в долине под нами." }, { 4.89, "Я неплохо разглядел их через прицел ружья: это явно были солдаты в форме Кул-Тираса." }, { 10.76, "Если ты не против выполнить моё поручение, отправляйся к лагерю этих людей у разорённого каравана на юге." }, { 17.86, "Убей всех, кого увидишь, и узнай, что им тут нужно." } } }, t = { d = 6.8, v = "human-male", n = { x = 60 }, c = { x = { { 0.00, "Значит, они ищут дезертира..." }, { 2.66, "Что ж, похоже, я так и не смог убежать от прошлого." } } } } },
    [95642] = { d = 33.4, g = 1, v = "human-female", n = { x = 357 }, c = { m = { { 0.00, "Эй, ты!" }, { 0.53, "Хвала Свету..." }, { 1.64, "Амберхолл попросила меня найти?" }, { 4.01, "Нет?" }, { 4.34, "Так я и знала." }, { 5.39, "Эш Амберхолл отправила меня сюда, чтобы узнать, чем занимается Сумеречный Молот." }, { 11.30, "Как видишь, они что-то ищут в Лесоречье." }, { 14.32, "Мне нужен образец их чар, чтобы выяснить, что именно." }, { 18.20, "Фархолду необходимы эти образцы." }, { 20.63, "Прошу тебя, герой." }, { 22.07, "Возьми этот катализатор." }, { 23.91, "Его чары позволяют поглощать магию культа." }, { 27.13, "Из рун, самих сектантов – неважно." }, { 29.63, "Просто подними его вверх, и он сделает всё остальное." } }, f = { { 0.00, "Эй, ты!" }, { 0.52, "Хвала Свету..." }, { 1.63, "Амберхолл попросила меня найти?" }, { 3.97, "Нет?" }, { 4.30, "Так я и знала." }, { 5.34, "Эш Амберхолл отправила меня сюда, чтобы узнать, чем занимается Сумеречный Молот." }, { 11.20, "Как видишь, они что-то ищут в Лесоречье." }, { 14.20, "Мне нужен образец их чар, чтобы выяснить, что именно." }, { 18.04, "Фархолду необходимы эти образцы." }, { 20.45, "Прошу тебя, героиня." }, { 22.01, "Возьми этот катализатор." }, { 23.84, "Его чары позволяют поглощать магию культа." }, { 27.03, "Из рун, самих сектантов – неважно." }, { 29.50, "Просто подними его вверх, и он сделает всё остальное." } } }, t = { d = 10.6, v = "human-female", n = { x = 53 }, c = { x = { { 0.00, "*Клэр вздрагивает, коснувшись кристалла, потрескивающего магией культистов.*" }, { 5.76, "Это сильнее, чем я боялась." }, { 7.89, "Обращаться с этим придётся осторожно." } } } } },
    [95643] = { d = 37.0, g = 1, v = "human-female", n = { m = 416, f = 418 }, c = { m = { { 0.00, "Может, взглянув на меня, так и не скажешь, но, как ученица госпожи Амберхолл в тёмных искусствах, я вполне могу постоять за себя." }, { 9.10, "Однако я никак не ожидала столкнуться с целой пещерой огров, усиленных магией Бездны." }, { 15.25, "Если тебе удалось спуститься сюда, не попав в плен, значит, ты и сам очень силён." }, { 21.01, "Боюсь, я не преуспела в сражениях с местными ограми и их владыками." }, { 25.75, "Сделай благое дело и убей этих отвратительных тварей." }, { 29.66, "От целеустремлённых фанатиков нельзя ждать ничего хорошего, особенно, когда они усилены магией." } }, f = { { 0.00, "Может, взглянув на меня, так и не скажешь, но, как ученица госпожи Амберхолл в тёмных искусствах, я вполне могу постоять за себя." }, { 9.10, "Однако я никак не ожидала столкнуться с целой пещерой огров, усиленных магией Бездны." }, { 15.25, "Если тебе удалось спуститься сюда, не попав в плен, значит, ты и сама очень сильна." }, { 21.80, "Боюсь, я не преуспела в сражениях с местными ограми и их владыками." }, { 26.54, "Сделай благое дело и убей этих отвратительных тварей." }, { 30.45, "От целеустремлённых фанатиков нельзя ждать ничего хорошего, особенно, когда они усилены магией." } } }, t = { d = 7.6, g = 1, v = "human-female", n = { m = 78, f = 79 }, c = { m = { { 0.00, "Ты сумел уложить немало этих тварей." }, { 3.00, "Сегодня Сумеречный Молот надолго запомнит такие потери." } }, f = { { 0.00, "Ты сумела уложить немало этих тварей." }, { 3.22, "Сегодня Сумеречный Молот надолго запомнит такие потери." } } } } },
    [95646] = { d = 38.2, v = "creature/ancient", n = { x = 338 }, c = { x = { { 0.00, "На этих солончаковых болотах есть большой источник пресных южных вод." }, { 6.56, "Мне больно это осознавать, но я корнями чувствую порчу, просачивающуюся сквозь горное ущелье, откуда они появляются." }, { 17.54, "Существа там, как и в наших низинах, реагируют на скверну куда острее." }, { 24.18, "Соль моря не закаляла их с самого детства, и потому им нечего противопоставить подобному злу." }, { 32.87, "Отправляйся на нагорье и принеси мне корень Ужаса нагорья." } } }, t = { d = 15.6, v = "creature/ancient", n = { x = 135 }, c = { x = { { 0.00, "Всё хуже, чем я боялся." }, { 2.23, "Пробуждается древняя энергия." }, { 5.06, "Тебе было бы разумно передать твоим усердным землекопам, чтобы они прекратили копать – ради их же безопасности." } } } } },
    [95647] = { d = 34.7, v = "human-female", n = { x = 406 }, c = { x = { { 0.00, "У моего мужа, Ардина, редкий дар чувствовать природу." }, { 3.72, "Ему никакая вершина нипочём, лишь бы собрать травы и цветы, нужные мне для алхимии." }, { 9.43, "Наши полки и кладовая никогда не пустеют." }, { 12.34, "Только вот теперь он, боюсь, попал в беду." }, { 15.32, "Недавно мы повстречали экспедицию, которая искала, где бы пополнить припасы." }, { 20.53, "Они говорили, среди прочего, об исполинских травах, каких никто прежде не видывал." }, { 26.30, "Именно на них он и отправился посмотреть своими глазами." }, { 30.15, "Его нет уже слишком долго!" }, { 32.07, "Я буду благодарна, если ты его поищешь." } } }, t = { d = 10.3, g = 1, v = "human-female", n = { m = 115, f = 117 }, c = { m = { { 0.00, "Мы думали, нам конец!" }, { 1.53, "Что-то растревожило здешних зверей, и наша бригада землекопов не смогла отбиться." }, { 7.34, "Спасибо, что помог нам с этими пауками." } }, f = { { 0.00, "Мы думали, нам конец!" }, { 1.56, "Что-то растревожило здешних зверей, и наша бригада землекопов не смогла отбиться." }, { 7.47, "Спасибо, что помогла нам с этими пауками." } } } } },
    [95663] = { d = 34.2, v = "orc-male", n = { x = 372 }, c = { x = { { 0.00, "Клан Драконьей Пасти – грозный противник." }, { 3.12, "Они славятся магией подчинения, достаточно сильной, чтобы заставить служить даже драконов, и, по слухам, готовятся показать её в Болотине." }, { 13.56, "Правда это или пустое бахвальство, ловчие смерти не могут действовать, полагаясь на обрывки слухов." }, { 21.15, "Обрывочные знаки донесли до меня лишь это." }, { 24.41, "Одному из наших агентов нужна помощь на холмах над лагерем Драконьей Пасти." }, { 30.17, "Встреться с ней там." }, { 31.73, "Она расскажет, что делать дальше." } } }, t = { d = 4.1, v = "scourge-female", n = { x = 30 }, c = { x = { { 0.00, "И это всё смельчаки?" }, { 2.33, "Говорите потише." } } } } },
    [95664] = { d = 18.2, v = "narrator", n = { x = 182 }, c = { x = { { 0.00, "Этот необычный составной осколок рассеивает свет, словно живая призма." }, { 5.95, "Его природа неясна, но от него веет древней силой." }, { 10.33, "Лучших знатоков артефактов той далёкой эпохи стоит искать на Вершине Старейшин в Громовом Утёсе." } } }, t = { d = 11.4, g = 1, v = "tauren-female#71", n = { m = 98, f = 100 }, c = { m = { { 0.00, "Приятно видеть, когда чужестранец приходит вот так – это добрый знак." }, { 6.07, "Я чувствую исходящую от тебя силу..." }, { 9.30, "Что это ты принёс?" } }, f = { { 0.00, "Приятно видеть, когда чужестранец приходит вот так – это добрый знак." }, { 6.07, "Я чувствую исходящую от тебя силу..." }, { 9.30, "Что это ты принесла?" } } } } },
    [95682] = { d = 37.6, v = "scourge-female", n = { x = 327 }, c = { x = { { 0.00, "Драконья Пасть." }, { 1.40, "Остатки клана укротителей драконов думают, что нашли нечто такое, что вернёт им былое могущество." }, { 11.71, "В чьих глазах?.." }, { 13.19, "Их лжевождя?" }, { 14.35, "Очисти место раскопок от этого сброда, чтобы наши ловчие смерти могли незаметно туда пробраться." }, { 23.42, "Если при орках Драконьей Пасти найдётся что-нибудь стоящее, принеси это мне – такие сведения должны оставаться между нами и нашим королевским командованием." } } }, t = { d = 24.8, g = 1, v = "scourge-female", n = { m = 200, f = 200 }, c = { m = { { 0.00, "Дай-ка это мне." }, { 1.45, "Узнаю орочьи каракули." }, { 3.54, "Значит, они надеются задобрить Ренда?" }, { 7.01, "Бесполезная трата времени." }, { 9.43, "Впрочем, ладно." }, { 10.88, "Тёмной Госпоже будет весьма полезно об этом узнать." }, { 15.55, "Держи, я это всё равно с собой не возьму." }, { 19.34, "И смотри не болтай о задании, рядовой." } }, f = { { 0.00, "Дай-ка это мне." }, { 1.59, "Узнаю орочьи каракули." }, { 3.88, "Значит, они надеются задобрить Ренда?" }, { 7.68, "Бесполезная трата времени." }, { 10.32, "Впрочем, ладно." }, { 11.91, "Тёмной Госпоже будет весьма полезно об этом узнать." }, { 17.03, "Держи, я это всё равно с собой не возьму." }, { 21.17, "И смотри не болтай о задании, рядовая." } } } } },
    [95697] = { d = 39.0, v = "orc-male", n = { x = 406 }, c = { x = { { 0.00, "Замджа считает, нам нужно больше домашней стряпни." }, { 4.08, "Она говорит, если мы начнём подавать мясо ящеров, это привлечёт публику, которая обычно от \"Жаровни Борстана\" нос воротит." }, { 13.83, "Идея, скажем прямо, неплохая." }, { 16.26, "Но мне хочется готовить нечто поднимающееся выше ароматов наших родных деревень." }, { 22.71, "Мы же в Оргриммаре!" }, { 24.15, "Борстан должен сделать из знакомых рецептов что-нибудь грандиозное!" }, { 29.52, "Один охотник недавно вернулся из Болотины с огромным когтем чащобного ящера, которые водятся там на раскопках." }, { 38.33, "Ты в деле?" } } }, t = { d = 16.3, g = 1, v = "orc-male", n = { m = 163, f = 164 }, c = { m = { { 0.00, "Ты только посмотри на эту шикарную текстуру!" }, { 3.60, "Чем они там питаются?!" }, { 5.41, "Спасибо, что взялся за такую работу." }, { 8.36, "Если подождёшь, мы сейчас быстренько тебе этого ящера приготовим – за счёт заведения, разумеется!" } }, f = { { 0.00, "Ты только посмотри на эту шикарную текстуру!" }, { 3.60, "Чем они там питаются?!" }, { 5.41, "Спасибо, что взялась за такую работу." }, { 8.71, "Если подождёшь, мы сейчас быстренько тебе этого ящера приготовим – за счёт заведения, разумеется!" } } } } },
    [95737] = { d = 32.8, v = "nightelf-female", n = { x = 403 }, c = { x = { { 0.00, "Время от времени я переписываюсь с другими людьми моего ремесла – травниками и чудаками, изучающими редкие растения и местные диковинки." }, { 9.25, "Мы обмениваемся открытиями, а иногда и предупреждениями о том, что ждёт впереди." }, { 14.51, "Одна знакомая алхимичка из Болотины писала о бригаде землекопов, в которой состоит её муж, нашедшей признаки давно утраченной первозданной травы... но она так и не сообщила, как много её и насколько она доступна." }, { 28.84, "Если сможешь, проведай Кейтлин Грассман в Гавани Менетилов." } } }, t = { d = 12.3, v = "human-female", n = { x = 151 }, c = { x = { { 0.00, "Ллана, наверное, гадает, где семена травы, которые я обещала передать с мужем!" }, { 5.15, "Мне спокойнее оттого, что она тревожится не меньше моего." }, { 8.89, "Видно, мы обе чуем что-то неладное в самих раскопках." } } } } },
    [95748] = { d = 28.6, g = 1, v = "human-male", n = { m = 354, f = 356 }, c = { m = { { 0.00, "Странно." }, { 0.60, "На фрагменте таблички, который ты принёс, о потерянном городе И'лалай говорится так, будто он был огромен." }, { 7.61, "Но руины у рифа недостаточно велики для такого обширного поселения." }, { 12.14, "На побережье к северу от Коварного рифа находятся древние тролльи развалины." }, { 17.28, "В них хранится табличка с легендами о затерянном городе троллей." }, { 21.57, "Мне хотелось бы изучить её." }, { 23.38, "Возьми эту шкуру и уголь и сделай оттиск таблички, а потом возвращайся ко мне." } }, f = { { 0.00, "Странно." }, { 0.60, "На фрагменте таблички, который ты принесла, о потерянном городе И'лалай говорится так, будто он был огромен." }, { 7.72, "Но руины у рифа недостаточно велики для такого обширного поселения." }, { 12.21, "На побережье к северу от Коварного рифа находятся древние тролльи развалины." }, { 17.30, "В них хранится табличка с легендами о затерянном городе троллей." }, { 21.55, "Мне хотелось бы изучить её." }, { 23.35, "Возьми эту шкуру и уголь и сделай оттиск таблички, а потом возвращайся ко мне." } } } },
    [95753] = { d = 22.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Тотем пульсирует дикой магией." }, { 2.67, "В вашем сознании возникает образ призрачного волка — он манит вас за собой." }, { 9.07, "Похоже, он бросает вам вызов." }, { 11.59, "Вдалеке, сразу за огромным выбеленным солнцем скелетом, появляется другой тотем — близнец того, на котором сейчас лежит ваша рука." } } } },
    [95770] = { d = 31.8, v = "human-male", n = { x = 371 }, c = { x = { { 0.00, "Я перечитал легенду, и похоже, мы всё же там, где должен был располагаться затерянный город." }, { 6.24, "Возможно, мы просто упускаем какую-то деталь." }, { 9.43, "Когда я был моложе, то время от времени нырял к руинам у Коварного рифа, но потом там обосновались мурлоки." }, { 16.86, "Если память мне не изменяет, там была пещера." }, { 20.04, "Говорят, сейчас в тех местах собираются наги, что очень необычно." }, { 24.60, "Узнай, что привлекает их туда." }, { 26.72, "Ступай, исследуй места к западу от Коварного рифа и возвращайся с вестями." } } } },
    [95771] = { d = 21.8, v = "human-male", n = { x = 261 }, c = { x = { { 0.00, "Рудник в Североземье – не единственная головная боль." }, { 3.67, "До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды." }, { 10.33, "Нужно исследовать рудник и подтвердить эти известия или опровергнуть их." }, { 15.46, "Я буду ждать отчёта." }, { 16.85, "Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур." } } } },
    [95772] = { d = 31.6, v = "dwarf-male", n = { x = 360 }, c = { x = { { 0.00, "Братишка всё зазывал меня отправиться с ним в Болотину вместе с копателями из Лок Модана." }, { 6.21, "Говорил, мол, собираются они в холмы, куда ещё ни один дворф сроду не ступал." }, { 11.66, "Раскопки какие-то затеяли." }, { 13.56, "Я бы пошёл, да только уже взялся пояса перековывать, не успевал к сроку." }, { 18.63, "Дэвин мне обычно пишет, когда куда-то отправляется, а тут ни словечка я от него не получил." }, { 25.03, "На душе от этого как-то неспокойно." }, { 27.56, "Коли пойдёшь в те края, не поищешь заодно и братишку моего?" } } }, t = { d = 10.6, v = "narrator", n = { x = 97 }, c = { x = { { 0.00, "Этот дворф поразительно похож на Дорина Поющий Клинок." }, { 4.99, "На прикладе зажатого в его руках ружья вырезаны инициалы \"ДПК\"." } } } } },
    [95773] = { d = 27.2, g = 1, v = "human-male", n = { x = 326 }, c = { m = { { 0.00, "Герой, ты очень вовремя." }, { 1.70, "Я только что получил донесение о нагах у побережья." }, { 5.15, "Похоже, они собираются рядом с какими-то старыми руинами троллей на морском дне." }, { 10.61, "Наши силы и так едва сдерживают натиск местного племени Кровавого Скальпа и огров, нападающих на караваны." }, { 17.82, "Не хватало нам ещё внезапной атаки с моря." }, { 20.67, "Ступай и убей как можно больше наг, а потом принеси мне их трезубцы в доказательство своего успеха." } }, f = { { 0.00, "Героиня, ты очень вовремя." }, { 1.78, "Я только что получил донесение о нагах у побережья." }, { 5.16, "Похоже, они собираются рядом с какими-то старыми руинами троллей на морском дне." }, { 10.49, "Наши силы и так едва сдерживают натиск местного племени Кровавого Скальпа и огров, нападающих на караваны." }, { 17.55, "Не хватало нам ещё внезапной атаки с моря." }, { 20.34, "Ступай и убей как можно больше наг, а потом принеси мне их трезубцы в доказательство своего успеха." } } } },
    [95774] = { d = 26.9, v = "orc-male#60", n = { x = 267 }, c = { x = { { 0.00, "Лекарю удалось спасти меня, но не её." }, { 3.03, "Она погибла в бою." }, { 4.61, "Её имя – Ольгра, и я никогда её не забуду." }, { 8.00, "На ней не было украшений?" }, { 10.02, "Она носила много вещей из полированной кости." }, { 13.77, "Убей налётчиков из племени Иглогривых возле того места, где она погибла, и найди её драгоценные украшения!" }, { 22.27, "Я размещу их на памятнике, который воздвигну в память о ней." } } }, t = { d = 15.1, g = 1, v = "orc-male#60", n = { m = 120, f = 121 }, c = { m = { { 0.00, "Я помещу эти украшения на памятник моей жене, чтобы никогда её не забыть." }, { 7.33, "Жажда мести всегда будет жечь мою кровь!" }, { 11.40, "Ты оказал мне... нам... огромную услугу." } }, f = { { 0.00, "Я помещу эти украшения на памятник моей жене, чтобы никогда её не забыть." }, { 7.14, "Жажда мести всегда будет жечь мою кровь!" }, { 11.10, "Ты оказала мне... нам... огромную услугу." } } } } },
    [95775] = { d = 35.8, g = 1, v = "human-male", n = { x = 432 }, c = { m = { { 0.00, "Я собираюсь попросить тебя об очень серьёзной услуге, герой." }, { 4.07, "Скорее всего, тебе понадобятся могучие союзники, чтобы выполнить мою просьбу." }, { 9.41, "Разузнай побольше о руинах по другую сторону пещеры, которую сторожат наги." }, { 14.56, "Если мои подозрения верны, там действительно может быть затерянный город И'лалай." }, { 20.09, "Мы, возможно, в нескольких шагах от невероятного количества потерянных исторических знаний, но я слишком стар, чтобы отправиться туда лично." }, { 29.43, "Проникни в руины и собери надписи с табличек, которые найдёшь внутри, а потом возвращайся." } }, f = { { 0.00, "Я собираюсь попросить тебя об очень серьёзной услуге, героиня." }, { 4.23, "Скорее всего, тебе понадобятся могучие союзники, чтобы выполнить мою просьбу." }, { 9.62, "Разузнай побольше о руинах по другую сторону пещеры, которую сторожат наги." }, { 14.83, "Если мои подозрения верны, там действительно может быть затерянный город И'лалай." }, { 20.41, "Мы, возможно, в нескольких шагах от невероятного количества потерянных исторических знаний, но я слишком стар, чтобы отправиться туда лично." }, { 29.85, "Проникни в руины и собери надписи с табличек, которые найдёшь внутри, а потом возвращайся." } } } },
    [95776] = { d = 31.4, g = 1, v = "human-male", n = { m = 370, f = 372 }, c = { m = { { 0.00, "Ты славно сделал, что убил наг у побережья, но раз они появились в наших водах в таком количестве, значит нам грозит куда большая опасность." }, { 9.43, "Я поговорил с Кин'вилаем, и он считает, что наги из клана Солёной Чешуи проникли в руины затонувшего города." }, { 16.62, "Если это так, то они ищут там что-то и точно замышляют недоброе." }, { 21.03, "Нельзя позволить им раздобыть нечто, что может представлять для нас угрозу." }, { 26.05, "Пора положить этому конец." }, { 27.92, "Убей их предводителя и возвращайся ко мне." } }, f = { { 0.00, "Ты славно сделала, что убила наг у побережья, но раз они появились в наших водах в таком количестве, значит нам грозит куда большая опасность." }, { 9.76, "Я поговорил с Кин'вилаем, и он считает, что наги из клана Солёной Чешуи проникли в руины затонувшего города." }, { 17.11, "Если это так, то они ищут там что-то и точно замышляют недоброе." }, { 21.62, "Нельзя позволить им раздобыть нечто, что может представлять для нас угрозу." }, { 26.75, "Пора положить этому конец." }, { 28.66, "Убей их предводителя и возвращайся ко мне." } } } },
    [95786] = { d = 34.6, v = "human-male", n = { x = 419 }, c = { x = { { 0.00, "У меня есть друг в предгорьях Хилсбрада, который изучает легенды троллей и злую магию." }, { 5.83, "Думаю, у него будут кое-какие мысли о проклятом колдовстве, которое одолело разум полковника Курцена." }, { 12.82, "Также до меня дошли вести от разведчиков, что местные тролли в большом беспокойстве и твердят о чём-то под названием \"И'лалай\"." }, { 21.33, "Нужно выяснить, связано ли это со скверной, жертвой которой пал Курцен!" }, { 26.19, "Вот, отнеси эти фетиши и легенды, а также доклад разведчиков хранителю мудрости Диббсу." }, { 32.15, "Если нам повезёт, он во всём разберётся." } } } },
    [95787] = { d = 32.0, v = "human-male", n = { x = 294 }, c = { x = { { 0.00, "*Руки хранителя мудрости Диббса подрагивают, когда он читает доклад разведчиков и легенды троллей.*" }, { 7.36, "Не может быть!" }, { 8.35, "Если верить этому, у побережья Тернистой долины поднялся из глубин затерянный город троллей И'лалай!" }, { 15.37, "Нужно немедленно всё разведать!" }, { 17.55, "Это может быть археологической находкой столетия!" }, { 20.96, "Прости, я знаю, что дорога назад в Тернистую долину длинна, но если окажешься в этом затонувшем городе, собери все легенды, которые отыщешь там, и принеси их мне." } } } },
    [95788] = { d = 30.0, v = "human-male", n = { x = 370 }, c = { x = { { 0.00, "Фетиши Дробителей Черепов, которые передал через тебя брат Нимез, действительно сильны, но вряд ли они повлияли на Курцена." }, { 8.23, "По крайней мере, не напрямую." }, { 10.21, "И всё же, если слухи правдивы, и затерянный город троллей И'лалай действительно восстал из глубин, то тёмная магия, которая его подняла, может иметь ко всему этому отношение." }, { 21.85, "Если рискнёшь пробраться в затонувший город И'лалай, прошу, собери там фетиши троллей и принеси мне для дальнейшего изучения." } } } },
    [95789] = { d = 41.5, g = 1, v = "goblin-male", n = { m = 486, f = 489 }, c = { m = { { 0.00, "Эй, дружище, ты на вид не робкого десятка." }, { 2.85, "Барон Ревилгаз приказал мне держать ухо востро и следить за появлением новых магических предметов." }, { 9.65, "Говорят, какие-то затонувшие руины троллей недавно таинственным образом... э-э... всплыли." }, { 15.90, "Это значит, что появилось множество ничейного товара, если ты меня понимаешь." }, { 21.28, "Вот только это немедленно привлекло внимание пиратов." }, { 24.99, "Да не просто каких-нибудь там обычных головорезов, а шайки Солевидцев, которые как раз собирают магические артефакты." }, { 32.91, "Надо, чтобы ты отправился в затонувший город, избавился от этих негодяев и отобрал у них украденные артефакты." } }, f = { { 0.00, "Эй, подруга, ты на вид не робкого десятка." }, { 3.06, "Барон Ревилгаз приказал мне держать ухо востро и следить за появлением новых магических предметов." }, { 9.86, "Говорят, какие-то затонувшие руины троллей недавно таинственным образом... э-э... всплыли." }, { 16.11, "Это значит, что появилось множество ничейного товара, если ты меня понимаешь." }, { 21.49, "Вот только это немедленно привлекло внимание пиратов." }, { 25.20, "Да не просто каких-нибудь там обычных головорезов, а шайки Солевидцев, которые как раз собирают магические артефакты." }, { 33.12, "Надо, чтобы ты отправилась в затонувший город, избавилась от этих негодяев и отобрала у них украденные артефакты." } } }, t = { d = 6.5, v = "goblin-male", n = { x = 56 }, c = { x = { { 0.00, "Отлично!" }, { 0.82, "Я сейчас же сообщу барону." }, { 3.28, "Как и обещал, вот твоя доля награды." } } } } },
    [95791] = { d = 28.9, v = "goblin-male", n = { x = 338 }, c = { x = { { 0.00, "Шайка Солевидцев у меня в последнее время как бельмо на глазу, а теперь они ещё и пробрались в затонувший город!" }, { 7.87, "От них всегда одни неприятности, но есть среди них один капитан, от которого я особенно хочу избавиться – проклятый капитан Морожад!" }, { 17.06, "Он и его команда постоянно крадут магические артефакты, которые я разыскиваю, и меня это уже утомило." }, { 24.24, "Разберись с ним и его коронерами из шайки Солевидцев." }, { 27.95, "Раз и навсегда." } } }, t = { d = 12.4, v = "goblin-male", n = { x = 129 }, c = { x = { { 0.00, "Как же я тебе благодарен!" }, { 1.94, "Зная, что теперь на свете меньше Солевидцев, я буду спать куда спокойнее." }, { 7.63, "Барон тоже благодарен тебе за службу." }, { 10.61, "Вот, держи свою награду." } } } } },
    [95792] = { d = 34.3, v = "goblin-female", n = { x = 378 }, c = { x = { { 0.00, "Чтобы заработать как следует, часто приходится лезть туда, куда больше никто и носа не сунет." }, { 6.88, "Вот, например, в той пещере богатое месторождение минералов, до которого пока ни у кого не дошли руки." }, { 14.28, "Ты даже не представляешь, СКОЛЬКО денег можно на этом поднять." }, { 18.87, "Вот только есть одна... ма-а-сенькая... проблемка." }, { 22.47, "Драконы." }, { 23.13, "В сущности, ничего особенного." }, { 25.36, "Если поможешь мне расчистить пещеру, я тебя щедро награжу." }, { 29.68, "А когда страшно разбогатею, буду помнить, что с меня причитается!" } } }, t = { d = 9.2, g = 1, v = "goblin-female", n = { x = 93 }, c = { m = { { 0.00, "Потрясающая работа, герой." }, { 2.04, "Как только моё маленькое горное дельце начнёт приносить прибыль, обещаю, возьму тебя в долю!" } }, f = { { 0.00, "Потрясающая работа, героиня." }, { 2.39, "Как только моё маленькое горное дельце начнёт приносить прибыль, обещаю, возьму тебя в долю!" } } } } },
    [95795] = { d = 12.2, v = "narrator", n = { x = 93 }, c = { x = { { 0.00, "Вы накрываете тело дворфа его же плащом." }, { 3.37, "Отправляйтесь в Приозёрье и лично сообщите Дорину Поющему Клинку о том, что случилось с его братом на раскопках." } } }, t = { d = 25.3, v = "dwarf-male", n = { x = 248 }, c = { x = { { 0.00, "Ах, нет..." }, { 0.76, "Мне надо было пойти с ними." }, { 3.46, "Большая часть того, что я ковал, была для него – я готовил сюрприз, но не успел, когда он заходил за вещами в дорогу." }, { 12.47, "Теперь, когда всё готово, у меня нет сил ни переплавлять, ни продавать это." }, { 18.22, "Можешь взять себе." }, { 19.68, "Это меньшее, что я могу сделать для того, кто принёс мне эту горькую весть." } } } } },
    [95798] = { d = 28.0, g = 1, v = "human-male", n = { m = 343, f = 343 }, c = { m = { { 0.00, "Я хочу попросить тебя отнести этот и'лалайский фетиш моей подруге Абре в Даларан." }, { 5.59, "Если у неё есть свободное время, пусть осмотрит его." }, { 9.07, "Ей очень интересны обычаи и магия троллей, поэтому она наверняка заинтересуется этой находкой." }, { 15.44, "Только будь осторожен." }, { 16.94, "Кирин-Тор не пускает в великий город кого попало." }, { 20.31, "Если тебе ещё не удалось заслужить право прохода туда, то придётся, возможно, найти какой-то способ их умилостивить." } }, f = { { 0.00, "Я хочу попросить тебя отнести этот и'лалайский фетиш моей подруге Абре в Даларан." }, { 5.59, "Если у неё есть свободное время, пусть осмотрит его." }, { 9.07, "Ей очень интересны обычаи и магия троллей, поэтому она наверняка заинтересуется этой находкой." }, { 15.44, "Только будь осторожна." }, { 17.02, "Кирин-Тор не пускает в великий город кого попало." }, { 20.39, "Если тебе ещё не удалось заслужить право прохода туда, то придётся, возможно, найти какой-то способ их умилостивить." } } } },
    [95799] = { d = 14.0, g = 1, v = "human-male", n = { m = 177, f = 179 }, c = { m = { { 0.00, "Я немедленно должен отправить весточку коллегам в Лигу исследователей в Стальгорне." }, { 5.25, "Это находка исторического масштаба." }, { 7.55, "Ты не мог бы доставить моё послание в Стальгорн?" }, { 10.49, "Я сделаю для тебя копию перевода табличек." } }, f = { { 0.00, "Я немедленно должен отправить весточку коллегам в Лигу исследователей в Стальгорне." }, { 5.25, "Это находка исторического масштаба." }, { 7.55, "Ты не могла бы доставить моё послание в Стальгорн?" }, { 11.41, "Я сделаю для тебя копию перевода табличек." } } }, t = { d = 17.8, v = "dwarf-male", n = { x = 207 }, c = { x = { { 0.00, "А, хранитель мудрости Диббс всегда присылает мне что-нибудь очень любопытное." }, { 5.56, "Хоть я и не занимаюсь троллями, его увлечённость я вполне понимаю." }, { 10.27, "Это великолепная новость!" }, { 12.16, "Я немедленно соберу отряд, и мы отправимся на поиски затерянного города И'лалай!" } } } } },
    [95803] = { d = 23.4, g = 1, v = "scourge-female", n = { m = 215, f = 217 }, c = { m = { { 0.00, "Теперь, когда голова командира омрачённых у нас, я хочу, чтобы ты отнёс её в Подгород." }, { 7.55, "Сильвана Ветрокрылая не доверяет нам и почти открыто презирает." }, { 13.17, "Отнеси голову Рудольфа Гельхардта Тёмной Госпоже." }, { 17.58, "Покажи ей, что мы заботимся о своих и преданы делу Отрёкшихся." } }, f = { { 0.00, "Теперь, когда голова командира омрачённых у нас, я хочу, чтобы ты отнесла её в Подгород." }, { 7.87, "Сильвана Ветрокрылая не доверяет нам и почти открыто презирает." }, { 13.54, "Отнеси голову Рудольфа Гельхардта Тёмной Госпоже." }, { 18.01, "Покажи ей, что мы заботимся о своих и преданы делу Отрёкшихся." } } }, t = { d = 35.2, v = "named/sylvanas", n = { x = 370 }, c = { x = { { 0.00, "Я не сомневаюсь, что Данита говорит искренне и действительно хочет помочь твоему ордену найти своё место среди Отрёкшихся." }, { 9.54, "Но я подозреваю, что это был не последний раз, когда кто-то из твоих братьев и сестёр сошёл с ума и обратил силу Света против своего народа." }, { 20.50, "Может, когда-нибудь я ещё решу, что существование твоего нелепого ордена больше не приносит пользы Отрёкшимся." }, { 29.06, "Так что советую тебе и твоим товарищам служить верно." }, { 33.30, "Мы будем следить за вами." } } } } },
    [95805] = { d = 41.6, v = "tauren-male#68", n = { x = 406 }, c = { x = { { 0.00, "Солнце и луна, Ан'ше и Му'ша, не являются такой же частью нашего мира, как стихии, но их свет указывает нам путь, даёт жизнь и надежду." }, { 11.04, "Мы почитаем духов мира, и потому также отдаём дань уважения близнецам." }, { 16.85, "Если тоже хочешь выказать уважение, возьми эти тлеющие благовония и отнеси к святилищу в холмах к юго-востоку отсюда, что возвышаются над плато." }, { 28.93, "Если увидишь свинобразов – значит, тебе южнее." }, { 32.88, "Поторопись, чтобы добраться до святилища до того, как они полностью истлеют." }, { 39.22, "И не дай благовониям намокнуть!" } } }, t = { d = 11.1, v = "tauren-male#68", n = { x = 0 }, c = { x = { { 0.00, "*Когда вы высыпаете благовония в огонь, их аромат окутывает вас, и вам остаётся лишь пустой мешочек и едва уловимое чувство удовлетворения.*" } } } } },
    [95809] = { d = 21.8, v = "human-male", n = { x = 186 }, c = { x = { { 0.00, "Я немного отдохну, а потом буду отсюда выбираться." }, { 3.68, "*Ардин достаёт из сумки несколько тростинок и быстро сплетает из них сердечко.*" }, { 9.44, "Возьми это и отнеси Кейтлин – пусть знает, что скоро я буду дома!" }, { 13.99, "Благодаря тебе путь свободен, так что я теперь соберу свои снопы и отправлюсь обратно по твоему следу." }, { 21.00, "Спасибо тебе." } } }, t = { d = 20.9, g = 1, v = "human-female", n = { m = 180, f = 182 }, c = { m = { { 0.00, "Всё это звучит просто ужасно!" }, { 2.65, "Хвала Свету, Ардин оказался среди выживших!" }, { 6.48, "*Она прижимает сплетённое из тростника сердце к груди.*" }, { 10.48, "Я примусь готовить для него сытный обед." }, { 13.18, "Спасибо, что принёс мне этот дар." }, { 15.29, "Я хочу, чтобы у тебя тоже что-нибудь осталось в знак нашей признательности." } }, f = { { 0.00, "Всё это звучит просто ужасно!" }, { 2.65, "Хвала Свету, Ардин оказался среди выживших!" }, { 6.48, "*Она прижимает сплетённое из тростника сердце к груди.*" }, { 10.48, "Я примусь готовить для него сытный обед." }, { 13.18, "Спасибо, что принесла мне этот дар." }, { 16.15, "Я хочу, чтобы у тебя тоже что-нибудь осталось в знак нашей признательности." } } } } },
    [95810] = { d = 22.6, g = 1, v = "narrator", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Ты подбираешь обломок каменного механического автомата." }, { 4.01, "Материал на ощупь не похож ни на что, к чему ты прикасался раньше: это композит неизвестного состава." }, { 11.39, "Это определённо скорее «устройство», чем «обломок»." }, { 15.07, "Сам геолог Вельгар на своих раскопках, наверное, сможет рассказать об этой реликвии что-нибудь полезное." } }, f = { { 0.00, "Ты подбираешь обломок каменного механического автомата." }, { 4.00, "Материал на ощупь не похож ни на что, к чему ты прикасалась раньше: это композит неизвестного состава." }, { 11.42, "Это определённо скорее «устройство», чем «обломок»." }, { 15.09, "Сам геолог Вельгар на своих раскопках, наверное, сможет рассказать об этой реликвии что-нибудь полезное." } } }, t = { d = 14.3, g = 1, v = "dwarf-male", n = { m = 156, f = 158 }, c = { m = { { 0.00, "Ого, ты забрался в самую глубь и выжил?!" }, { 2.94, "Ну-ка, посмотрим, что там у тебя." }, { 5.36, "Если учесть, через что тебе пришлось пройти, чтобы принести мне эту штуковину, твой артефакт заслуживает особого внимания." } }, f = { { 0.00, "Ого, ты забралась в самую глубь и выжила?!" }, { 3.10, "Ну-ка, посмотрим, что там у тебя." }, { 5.52, "Если учесть, через что тебе пришлось пройти, чтобы принести мне эту штуковину, твой артефакт заслуживает особого внимания." } } } } },
    [95816] = { d = 24.4, v = "narrator", n = { x = 287 }, c = { x = { { 0.00, "Приветствуем, уважаемый мастер!" }, { 2.35, "Заполнение этой анкеты даст вам неисключительное, отзывное и юридически ограниченное право демонстрировать вывеску вашего ремесла или ремёсел по всему Азероту!" }, { 14.08, "После заполнения, пожалуйста, передайте анкету координатору контрактов в местном отделении Азеротского торгового управления." }, { 23.27, "Успехов в труде!" } } } },
    [95817] = { d = 30.4, g = 1, v = "dwarf-male", n = { m = 375, f = 376 }, c = { m = { { 0.00, "Ты знаком с Ротгатом Каменной Бородой?" }, { 2.56, "Это дворф-кузнец из Стальгорна." }, { 4.65, "Не самый разговорчивый парень, но на него всегда можно положиться." }, { 9.07, "Мы часто обращаемся к нему, когда нужно много простых изделий – такую работу Стондри по гордости своей не берёт." }, { 16.58, "Ротгат делает всё очень быстро, особенно когда помогает новым мастерам обзавестись своей лавкой." }, { 23.08, "Никому другому я бы не доверил изготовить твою вывеску так скоро." }, { 27.44, "Если будет упрямиться – скажи, что ты от меня!" } }, f = { { 0.00, "Ты знакома с Ротгатом Каменной Бородой?" }, { 2.61, "Это дворф-кузнец из Стальгорна." }, { 4.68, "Не самый разговорчивый парень, но на него всегда можно положиться." }, { 9.06, "Мы часто обращаемся к нему, когда нужно много простых изделий – такую работу Стондри по гордости своей не берёт." }, { 16.52, "Ротгат делает всё очень быстро, особенно когда помогает новым мастерам обзавестись своей лавкой." }, { 22.98, "Никому другому я бы не доверил изготовить твою вывеску так скоро." }, { 27.30, "Если будет упрямиться – скажи, что ты от меня!" } } } },
    [95818] = { d = 29.7, v = "dwarf-male", n = { x = 337 }, c = { x = { { 0.00, "Мы мигом тебя обслужим и отпустим, если материалы у тебя при себе!" }, { 4.77, "Нам понадобится двадцать пять мифриловых слитков и пятнадцать кусков плотной кожи." }, { 10.56, "Обычно нужны ещё кой-какие металлы и прочее, но у меня завалялся лом, который только место занимает, – на эти мелочи он и пойдёт." }, { 19.65, "А ещё, по старой дружбе, попрошу у тебя пять стеблей златошипа." }, { 24.10, "Моя жена знает отличный рецепт чая, и я хочу её порадовать." }, { 28.42, "Считай это платой!" } } } },
    [95819] = { d = 24.2, v = "narrator", n = { x = 288 }, c = { x = { { 0.00, "Приветствуем, уважаемый мастер!" }, { 2.32, "Заполнение этой анкеты даст вам неисключительное, отзывное и юридически ограниченное право демонстрировать вывеску вашего ремесла или ремёсел по всему Азероту!" }, { 13.92, "После заполнения, пожалуйста, передайте анкету координатору контрактов в местном отделении Дуротарского снабжения и логистики." }, { 23.13, "Успехов в труде!" } } } },
    [95882] = { d = 39.3, v = "orc-female#58", n = { x = 445 }, c = { x = { { 0.00, "На островке к северо-востоку от Рог'мара был замечен отряд разведчиков Альянса." }, { 5.73, "Их возглавляет умелый командир, из-за которого нам всё сложнее отслеживать врага." }, { 11.58, "Подлец даже назвал в мою честь своего зверя, чтобы меня позлить." }, { 16.39, "Он знает, что я за ним охочусь." }, { 18.61, "У этого человека повсюду глаза – надо их выколоть." }, { 22.31, "Один я уже забрала, да только негодяю удалось сбежать." }, { 26.35, "Приказываю принести мне второй глаз командира разведчиков в доказательство, что его больше нет." }, { 33.11, "Надо показать, что он не такой неприкасаемый, как он себе это возомнил." }, { 38.25, "Неза Кровоморда" } } } },
    [95883] = { d = 20.2, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Орудия для ритуала наскоро и небрежно побросали на алтарь." }, { 4.67, "Если верить обрывку записки, все материалы на месте." }, { 8.90, "Не хватает только крови и истерзанной души." }, { 12.42, "Нежить вокруг вас вполне подходит под определение истерзанной." }, { 17.37, "Нужный ингредиент надо искать у них." } } }, t = { d = 9.7, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Истерзанная душа испускает порочную энергию, оказавшись у жертвенного камня." }, { 6.69, "Вы почти выполнили условия ритуала." } } } } },
    [95884] = { d = 15.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "На обрывке записки почти ничего нельзя прочесть." }, { 3.85, "Однако записи о подготовке к жертвоприношению сохранились лучше." }, { 8.82, "В них упоминается жертвенный камень и некий ритуал." }, { 12.81, "Может, этот камень где-нибудь рядом." } } }, t = { d = 9.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Странные приспособления и инструменты разложены на грубой поверхности камня." }, { 5.86, "Это явно камень для даров, упоминавшийся в записке." } } } } },
    [95885] = { d = 11.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Осталось только кровавое подношение." }, { 3.01, "В обрывке записки упоминалась небольшая добровольная жертва." }, { 7.93, "На вас волной накатывает зловещее предчувствие." } } }, t = { d = 18.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Камень для даров ни на что не реагирует." }, { 3.24, "Ваш ритуал лишил его силы." }, { 5.53, "С какой целью, вам неизвестно, но что сделано, то сделано." }, { 10.24, "Грубый камень трескается и крошится, исполнив своё предназначение." }, { 15.62, "Что-то посверкивает посреди обломков." } } } } },
    [95912] = { d = 37.0, v = "narrator", n = { x = 384 }, c = { x = { { 0.00, "Стоит нам расправиться с одним орком, как на его место тут же встаёт другой, и порой ещё более опасный." }, { 8.15, "Должно быть, их бойцов тренирует очень опытный воин." }, { 12.37, "Чтобы одолеть их, надо лишить орков возможности восполнять потери." }, { 17.73, "Нужен смельчак, готовый разыскать и прикончить их таинственного мастера клинка." }, { 24.03, "Скорее всего, он обретается в лагере для новобранцев к северу от ордынской заставы." }, { 30.60, "Убейте его, заберите его знамя и вселите страх в сердца орков." }, { 35.68, "Эмбер Блейдвиспер" } } }, t = { d = 13.1, v = "human-female", n = { x = 127 }, c = { x = { { 0.00, "Сталь и припасы выигрывают битвы, но войны выигрывают сердца и умы." }, { 5.76, "С этим знаменем мы покажем нашим новобранцам, что Орды нечего бояться." }, { 11.82, "Отличная работа." } } } } },
    [95913] = { d = 34.3, v = "human-female", n = { x = 358 }, c = { x = { { 0.00, "*Тесса укачивает малышку, стараясь убаюкать.*" }, { 3.92, "Если она не голодна, то, может, просто устала." }, { 7.25, "Признаюсь, Эмма появилась так неожиданно, что мы даже не успели толком подготовиться к её рождению." }, { 14.10, "Муж смастерил замечательную кроватку, но я волнуюсь, что одеяла слишком уж староваты." }, { 19.95, "Она ведь заслуживает всего самого лучшего." }, { 22.96, "Если найдёшь мне несколько шкур, я постелю их в кроватке, и Эмма, надеюсь, наконец заснёт." }, { 29.12, "Все в Фархолде наверняка скажут тебе спасибо, когда она перестанет плакать." } } }, t = { d = 14.8, g = 1, v = "human-female", n = { m = 65, f = 66 }, c = { m = { { 0.00, "Ой, ты вернулся!" }, { 1.81, "Ты просто чудо." }, { 3.63, "Они такие тёплые, уютные... и мягкие." }, { 7.76, "*Тесса устало моргает.*" }, { 9.65, "*Похоже, она не спала уже несколько дней.*" }, { 13.04, "Для Эммы, конечно." } }, f = { { 0.00, "Ой, ты вернулась!" }, { 1.72, "Ты просто чудо." }, { 3.54, "Они такие тёплые, уютные... и мягкие." }, { 7.67, "*Тесса устало моргает.*" }, { 9.56, "*Похоже, она не спала уже несколько дней.*" }, { 12.95, "Для Эммы, конечно." } } } } },
    [95925] = { d = 31.1, g = 1, v = "dwarf-male", n = { x = 324 }, c = { m = { { 0.00, "Герой, мы сделали открытие всей жизни!" }, { 2.95, "Не могу поверить: руины в Ун'Горо открыты!" }, { 6.24, "Мы уже отправили туда отряд, но у них возникли... трудности." }, { 10.84, "Раз уж ты всё равно туда идёшь, может, закончишь эту карту?" }, { 15.37, "Говорят, там есть Ахроматический кристалл, а где-то у огромных Западных врат – откопанный страж." }, { 22.51, "Звучит любопытно." }, { 23.88, "Ещё пригодились бы такие ориентиры: Столп поглощения, Западные врата и Преддверие возрождения." } }, f = { { 0.00, "Героиня, мы сделали открытие всей жизни!" }, { 3.25, "Не могу поверить: руины в Ун'Горо открыты!" }, { 6.54, "Мы уже отправили туда отряд, но у них возникли... трудности." }, { 11.14, "Раз уж ты всё равно туда идёшь, может, закончишь эту карту?" }, { 15.67, "Говорят, там есть Ахроматический кристалл, а где-то у огромных Западных врат – откопанный страж." }, { 22.81, "Звучит любопытно." }, { 24.18, "Ещё пригодились бы такие ориентиры: Столп поглощения, Западные врата и Преддверие возрождения." } } } },
    [95928] = { d = 38.8, g = 1, v = "tauren-female", n = { m = 382, f = 382 }, c = { m = { { 0.00, "А, хорошо, что ты пришёл, герой." }, { 2.53, "В последнее время я изучаю кристаллы, и до меня дошли слухи о необычных кристаллах, которые, говорят, родом из кратера Ун'Горо." }, { 12.80, "Образцы самых простых у меня есть, но рассказывают, что в месте под названием Терраса Создателя видели кристаллы покрупнее и посильнее." }, { 23.57, "Об этом месте мне известно немногое – только то, что там есть эти кристаллы, в которых якобы заключены сами стихии." }, { 32.83, "Если окажешься там, пожалуйста, принеси мне по образцу каждого цвета." } }, f = { { 0.00, "А, хорошо, что ты пришла, героиня." }, { 3.06, "В последнее время я изучаю кристаллы, и до меня дошли слухи о необычных кристаллах, которые, говорят, родом из кратера Ун'Горо." }, { 13.33, "Образцы самых простых у меня есть, но рассказывают, что в месте под названием Терраса Создателя видели кристаллы покрупнее и посильнее." }, { 24.10, "Об этом месте мне известно немногое – только то, что там есть эти кристаллы, в которых якобы заключены сами стихии." }, { 33.36, "Если окажешься там, пожалуйста, принеси мне по образцу каждого цвета." } } } },
    [95934] = { d = 38.5, v = "goblin-female", n = { x = 459 }, c = { x = { { 0.00, "Мои приборы показывают, что в этих пещерах есть залежи неизвестного минерала." }, { 5.33, "Я назвала его \"Драконов куб\", и наверняка он стоит целое состояние." }, { 9.98, "Звучит круто, да?" }, { 11.22, "Но никто не хочет помочь мне его добыть, всем подавай доказательство, что минерал действительно существует." }, { 18.54, "У меня есть показания приборов, но смотреть на графики никто не любит, а вот большой блестящий кристалл – это убедительно." }, { 26.91, "Я уверена, что внутри можно найти кристаллы, торчащие из земли." }, { 31.31, "Если согласишься отправиться туда и добыть хоть один, я буду ужасно благодарна." }, { 36.82, "Только берегись драконов." } } }, t = { d = 10.6, g = 1, v = "goblin-female", n = { m = 115, f = 116 }, c = { m = { { 0.00, "Ух ты!" }, { 0.47, "Вот это точно привлечёт внимание!" }, { 2.93, "Здорово, что ты откопал его." }, { 5.07, "Если вдруг надумаешь — в нашей шахтёрской бригаде для тебя найдётся место." } }, f = { { 0.00, "Ух ты!" }, { 0.47, "Вот это точно привлечёт внимание!" }, { 2.93, "Здорово, что ты откопала его." }, { 5.35, "Если вдруг надумаешь — в нашей шахтёрской бригаде для тебя найдётся место." } } } } },
    [95935] = { d = 24.0, v = "narrator", n = { x = 223 }, c = { x = { { 0.00, "Драконья голова – сплошь клыки, чешуя и пепел." }, { 4.13, "Страшный трофей, добытый в страшном бою." }, { 7.79, "Держа её в руках, вы ощущаете жар последнего пламенного дыхания, исходящего из пасти." }, { 15.26, "Скалдарон больше никому не причинит вреда, но часовым Южного дозора стоит знать, что здесь произошло." } } } },
    [95936] = { d = 24.5, v = "narrator", n = { x = 222 }, c = { x = { { 0.00, "Драконья голова – сплошь клыки, чешуя и пепел." }, { 4.21, "Страшный трофей, добытый в страшном бою." }, { 7.94, "Держа её в руках, вы ощущаете жар последнего пламенного дыхания, всё ещё исходящий из пасти." }, { 16.13, "Скалдарон больше никому не причинит вреда, но воинам Рог'мара стоит знать, что здесь произошло." } } } },
    [95943] = { d = 41.0, g = 1, v = "dwarf-male", n = { m = 400, f = 401 }, c = { m = { { 0.00, "Доброго тебе денёчка!" }, { 1.97, "Моё имя Бертранд." }, { 3.60, "Бертранд Сталелоб." }, { 5.33, "К твоим услугам." }, { 6.80, "*Бертранд протягивает вам свою грязную руку.*" }, { 10.48, "Местные наняли меня приглядывать за строительством крепости." }, { 14.70, "Опыта им, конечно, не хватает – зато гонора хоть отбавляй." }, { 18.80, "Вот только тут такое дело... я лишился своих инструментов." }, { 22.90, "В небольшой роще к северо-западу отсюда напоролся на сектантов – и пришлось выбирать: инструменты мне сохранить или жизнь." }, { 31.41, "С одной стороны, я всё ещё жив." }, { 33.56, "С другой... в общем, ты, думаю, и сам понимаешь, к чему я клоню." }, { 38.03, "Поможешь найти мои инструменты?" } }, f = { { 0.00, "Доброго тебе денёчка!" }, { 1.99, "Моё имя Бертранд." }, { 3.65, "Бертранд Сталелоб." }, { 5.39, "К твоим услугам." }, { 6.88, "*Бертранд протягивает вам свою грязную руку.*" }, { 10.72, "Местные наняли меня приглядывать за строительством крепости." }, { 15.02, "Опыта им, конечно, не хватает – зато гонора хоть отбавляй." }, { 19.19, "Вот только тут такое дело... я лишился своих инструментов." }, { 23.35, "В небольшой роще к северо-западу отсюда напоролся на сектантов – и пришлось выбирать: инструменты мне сохранить или жизнь." }, { 32.01, "С одной стороны, я всё ещё жив." }, { 34.19, "С другой... в общем, ты, думаю, и сама понимаешь, к чему я клоню." }, { 38.88, "Поможешь найти мои инструменты?" } } }, t = { d = 13.1, g = 1, v = "dwarf-male", n = { m = 68, f = 70 }, c = { m = { { 0.00, "*Бертранд вскрывает ящик и достаёт кружку и бочонок эля.*" }, { 5.12, "Вот это дело!" }, { 6.31, "Теперь мы эту крепость мигом поднимем!" }, { 9.57, "Ты мне просто жизнь спас, парень!" } }, f = { { 0.00, "*Бертранд вскрывает ящик и достаёт кружку и бочонок эля.*" }, { 5.12, "Вот это дело!" }, { 6.31, "Теперь мы эту крепость мигом поднимем!" }, { 9.56, "Ты мне просто жизнь спасла, девица!" } } } } },
    [95951] = { d = 33.0, g = 1, v = "troll-male", n = { m = 308, f = 309 }, c = { m = { { 0.00, "Эй, дружок, как насчёт совета от старины Тан'джани?" }, { 4.16, "Ты не боись, плохого не скажу." }, { 6.69, "Орки неплохо рубят людей топором, но когда надо проколоть их внезапно, нужны охотники за головами." }, { 14.94, "Тоже хочешь научиться?" }, { 16.88, "По глазам вижу, хе-хе." }, { 18.81, "Сначала сделаем тебе копья." }, { 21.19, "Вот, как у меня." }, { 22.53, "Иди в человеческий лагерь, на запад." }, { 25.58, "Забери у них дерево." }, { 27.29, "И ножик захвати, заточишь им копья." }, { 30.26, "А как сделаешь их, неси сюда." } }, f = { { 0.00, "Эй, подруга, как насчёт совета от старины Тан'джани?" }, { 4.56, "Ты не боись, плохого не скажу." }, { 7.09, "Орки неплохо рубят людей топором, но когда надо проколоть их внезапно, нужны охотники за головами." }, { 15.34, "Тоже хочешь научиться?" }, { 17.28, "По глазам вижу, хе-хе." }, { 19.21, "Сначала сделаем тебе копья." }, { 21.59, "Вот, как у меня." }, { 22.93, "Иди в человеческий лагерь, на запад." }, { 25.98, "Забери у них дерево." }, { 27.69, "И ножик захвати, заточишь им копья." }, { 30.66, "А как сделаешь их, неси сюда." } } } },
    [95955] = { d = 25.1, v = "troll-male", n = { x = 255 }, c = { x = { { 0.00, "Копья у тебя есть, теперь научишься их метать." }, { 3.74, "В Лесоречье полно кроколисков." }, { 6.19, "Мерзкие твари." }, { 7.42, "Цапнут — и нет тебя, если не шевелишься." }, { 10.66, "Как раз для тренировки, хе-хе." }, { 13.03, "Пойди насади на копьё побольше этих тварей." }, { 16.56, "А потом возвращайся к старому Тан'джани за наградой." }, { 20.74, "Если сможешь проткнуть кроколиска — проткнёшь что угодно." } } } },
    [95957] = { d = 14.6, v = "goblin-female", n = { x = 151 }, c = { x = { { 0.00, "Держи, дружище." }, { 1.22, "Свежее пойло для нашего грустного приятеля." }, { 4.54, "Если он от этого не придёт в себя, ему уже ничто не поможет." }, { 9.15, "Только... обязательно помой потом руки." }, { 12.20, "И смотри, чтоб в глаза не попало." } } } },
    [95961] = { d = 36.2, g = 1, v = "human-female", n = { m = 364, f = 365 }, c = { m = { { 0.00, "*Ребёнок Тессы продолжает громко реветь.*" }, { 3.44, "Значит, не устала." }, { 4.75, "Ох, у остальных это всё так просто получается." }, { 7.93, "Её папа мигом бы всё исправил." }, { 10.04, "Когда же он вернётся?" }, { 11.48, "Прости, что опять обращаюсь, но было бы славно, если бы ты разузнал, почему он так задерживается." }, { 18.14, "Вышел уже давно, должен был сто раз вернуться." }, { 21.38, "Эмма прямо светится от радости, когда он приходит." }, { 24.93, "Загляни в Пороховой порт – он в последнее время часто там бывает." }, { 29.42, "Ты моего Грея сразу узнаешь, от его улыбки в любой компании становится светлее." } }, f = { { 0.00, "*Ребёнок Тессы продолжает громко реветь.*" }, { 3.44, "Значит, не устала." }, { 4.75, "Ох, у остальных это всё так просто получается." }, { 7.93, "Её папа мигом бы всё исправил." }, { 10.04, "Когда же он вернётся?" }, { 11.48, "Прости, что опять обращаюсь, но было бы славно, если бы ты разузнала, почему он так задерживается." }, { 19.43, "Вышел уже давно, должен был сто раз вернуться." }, { 22.67, "Эмма прямо светится от радости, когда он приходит." }, { 26.22, "Загляни в Пороховой порт – он в последнее время часто там бывает." }, { 30.71, "Ты моего Грея сразу узнаешь, от его улыбки в любой компании становится светлее." } } }, t = { d = 25.8, v = "human-male", n = { x = 270 }, c = { x = { { 0.00, "Тесс тебя прислала?" }, { 1.47, "Нет..." }, { 1.94, "Я не могу вернуться домой." }, { 3.95, "Не могу смотреть им в глаза." }, { 6.09, "Как мы могли привести маленькую девочку в такой мир?" }, { 9.97, "Мы не можем её защитить." }, { 11.78, "Мы и себя-то еле защищаем." }, { 13.78, "Какое будущее мы можем ей обещать?" }, { 16.39, "Новые войны?" }, { 17.40, "О чём мы только думали..." }, { 19.27, "Пожалуйста, не говори Тессе." }, { 21.41, "Я вернусь позже." }, { 22.68, "Когда-нибудь." }, { 23.69, "Мне просто нужно выпить ещё." } } } } },
    [95975] = { d = 35.4, g = 1, v = "human-male", n = { m = 398, f = 400 }, c = { m = { { 0.00, "Тесс говорит, что малышка Эмм без меня не засыпает?" }, { 3.49, "И ты всё это делаешь ради них, хотя мы друг другу чужие?" }, { 7.42, "Проклятье, какой же я дурень!" }, { 9.47, "Даже если нашей дочери предстоит жить в неидеальном мире, я обязан быть его частью." }, { 15.33, "Да и за что я вообще сражаюсь, если не могу надеяться на более счастливое будущее?" }, { 21.01, "Спасибо, что помог семье в моё отсутствие, но мне явно пора домой." }, { 25.62, "Одна последняя просьба: можешь достать цветы и передать их Тесс?" }, { 30.11, "Скажи, что я скоро буду." }, { 31.85, "Только вот сперва в порядок себя приведу." } }, f = { { 0.00, "Тесс говорит, что малышка Эмм без меня не засыпает?" }, { 3.49, "И ты всё это делаешь ради них, хотя мы друг другу чужие?" }, { 7.42, "Проклятье, какой же я дурень!" }, { 9.47, "Даже если нашей дочери предстоит жить в неидеальном мире, я обязан быть его частью." }, { 15.33, "Да и за что я вообще сражаюсь, если не могу надеяться на более счастливое будущее?" }, { 21.01, "Спасибо, что помогла семье в моё отсутствие, но мне явно пора домой." }, { 26.38, "Одна последняя просьба: можешь достать цветы и передать их Тесс?" }, { 30.87, "Скажи, что я скоро буду." }, { 32.61, "Только вот сперва в порядок себя приведу." } } } },
    [95981] = { d = 29.8, v = "scourge-male", n = { x = 304 }, c = { x = { { 0.00, "Отобрать подвески – лишь первый шаг." }, { 3.01, "Если Кирин-Тор действительно организовал постоянные поставки реликвий из Даларана, необходимо устранить их источник." }, { 12.63, "Осмотри дороги у Янтарной мельницы и отыщи там даларанских волшебников и дозорных." }, { 19.47, "Слишком долго мы разрешали им пересекать наши границы." }, { 24.06, "Если избавиться от них, то подвесок в Серебряном бору больше не станет." } } }, t = { d = 14.8, v = "scourge-male", n = { x = 138 }, c = { x = { { 0.00, "С тех пор, как пал барьер вокруг Даларана, Кирин-Тор полностью контролирует дороги." }, { 7.28, "Они явно чем-то страшно обеспокоены." }, { 10.64, "Но причина их волнения сейчас не имеет значения." } } } } },
    [95982] = { d = 36.4, g = 1, v = "goblin-male", n = { m = 407, f = 409 }, c = { m = { { 0.00, "Все бросают тут своих пушистых друзей и думают, что я со всем разберусь." }, { 5.00, "А потом винят меня, когда возвращаются и видят, что их лошадка или волк или... что там ещё они сюда припёрли... сдохло или убежало." }, { 14.24, "Я что, похож на благотворительную организацию?" }, { 17.40, "А вот ты похож на того, кто умеет кормить зверей." }, { 20.88, "Достанешь мне немного жратвы, чтобы угомонить зверьё?" }, { 24.62, "Если сам приготовить не можешь, кто-нибудь наверняка продаст тебе немного." }, { 29.87, "И поторопись!" }, { 30.82, "Последнее, что мне тут нужно, это бешеный табун голодных животных." } }, f = { { 0.00, "Все бросают тут своих пушистых друзей и думают, что я со всем разберусь." }, { 5.00, "А потом винят меня, когда возвращаются и видят, что их лошадка или волк или... что там ещё они сюда припёрли... сдохло или убежало." }, { 14.24, "Я что, похож на благотворительную организацию?" }, { 17.40, "А вот ты похожа на того, кто умеет кормить зверей." }, { 21.28, "Достанешь мне немного жратвы, чтобы угомонить зверьё?" }, { 25.02, "Если сама приготовить не можешь, кто-нибудь наверняка продаст тебе немного." }, { 30.86, "И поторопись!" }, { 31.81, "Последнее, что мне тут нужно, это бешеный табун голодных животных." } } } },
    [95983] = { d = 26.3, v = "narrator", n = { x = 282 }, c = { x = { { 0.00, "Скелет в плохом состоянии." }, { 2.09, "Глубокие отметины на руках и ногах похожи на следы от клыков и когтей." }, { 7.59, "Много дней под палящим солнцем выбелили кости и сделали их хрупкими." }, { 12.89, "Свирепость убийцы и суровый климат не позволяют опознать жертву." }, { 17.90, "Вам будет трудно унести весь скелет, но можно отнести череп ближайшему дозорному и спросить, что ему известно." } } }, t = { d = 13.3, g = 1, v = "human-male", n = { m = 63, f = 64 }, c = { m = { { 0.00, "*Корнелий проводит пальцами по отметинам на черепе, и его брови хмурятся всё сильнее.*" }, { 6.48, "Только этого мне не хватало... ещё работы." }, { 9.82, "Ну и задачку ты мне подкинул, знаешь ли." } }, f = { { 0.00, "*Корнелий проводит пальцами по отметинам на черепе, и его брови хмурятся всё сильнее.*" }, { 6.48, "Только этого мне не хватало... ещё работы." }, { 9.82, "Ну и задачку ты мне подкинула, знаешь ли." } } } } },
    [95984] = { d = 28.7, v = "human-male", n = { x = 318 }, c = { x = { { 0.00, "Это следы от клыков льва." }, { 1.87, "И, судя по всему, очень крупного." }, { 4.33, "Вожака местного прайда, не иначе." }, { 6.78, "Если тут пойдут слухи о рыскающем вокруг льве-людоеде, Демар будет в бешенстве." }, { 12.53, "К счастью, у меня есть идея." }, { 14.59, "Я могу сделать манок, подражающий крику раненого долгонога." }, { 18.92, "С его помощью мы выманим зверя." }, { 21.24, "Но чтобы звук был правильным, мне нужен клюв долгонога – их тут вокруг полно." }, { 26.67, "Принеси мне клюв – и пошустрее!" } } }, t = { d = 5.5, v = "human-male", n = { x = 61 }, c = { x = { { 0.00, "Так." }, { 0.34, "Оставь меня ненадолго, мне нужно вырезать из него свисток как следует." } } } } },
    [95986] = { d = 21.1, v = "human-male", n = { x = 213 }, c = { x = { { 0.00, "Манок готов." }, { 1.03, "Возьми его и иди на вершину холма, где живут львы." }, { 4.94, "Это к северу отсюда." }, { 6.59, "Там дунь в манок, и наш людоед появится." }, { 9.61, "Я бы сказал, что если не убьёшь его, даже не возвращайся... но тогда ты и так не вернёшься." }, { 16.33, "Давай, иди уже." }, { 17.63, "Надеюсь, тебе повезёт больше, чем тому скелету." } } }, t = { d = 19.0, v = "human-male", n = { x = 204 }, c = { x = { { 0.00, "А, и правда он!" }, { 1.12, "Ну, в таком случае — отличная работа." }, { 3.88, "Только чтобы мы друг друга поняли... мы ведь согласны, что Демару об этом знать необязательно, да?" }, { 10.91, "По-моему, мы прекрасно справились и сами." }, { 13.93, "Он и так уже сослал меня сюда." }, { 16.23, "Не хватало мне ещё его особого внимания." } } } } },
    [95988] = { d = 33.7, v = "goblin-female", n = { x = 399 }, c = { x = { { 0.00, "Что, вы с Греем поболтали?" }, { 1.79, "Весёлый малый, верно?" }, { 3.27, "Только не вздумай покупать ему ещё выпивку." }, { 6.30, "Тут постоялый двор, а не питейное заведение." }, { 9.26, "Пусть спасибо скажет, что его отсюда вообще не выставили." }, { 13.21, "Если хочешь забрать его с собой, я возражать не стану." }, { 17.03, "Вот только в таком состоянии он далеко не уйдёт." }, { 20.31, "Сперва ему нужно принять одно гоблинское средство." }, { 23.89, "Собери ингредиенты из этого списка, а я приготовлю нашему другу его \"напиток\"." }, { 29.32, "Посмотрим, захочет ли он ещё пить после моего фирменного коктейля." } } } },
    [95991] = { d = 33.8, v = "narrator", n = { x = 369 }, c = { x = { { 0.00, "Тут и так опасно перегонять лошадей, а теперь ещё пошли слухи о таинственном призрачном кроколиске, что жрёт моих лучших пони!" }, { 9.31, "Говорят, он в три раза больше и в два раза злее, чем обычные зверюги." }, { 14.47, "Я рисковать не собираюсь, поэтому пока кто-нибудь не избавится от этого зловредного чудища, мы с моими лошадками будем сидеть дома." }, { 24.26, "Если встретите его где-нибудь на берегу реки, принесите мне его клык, чтобы доказать, что на дорогах снова стало спокойно." }, { 33.44, "Уитли" } } }, t = { d = 9.3, g = 1, v = "human-male", n = { m = 93, f = 92 }, c = { m = { { 0.00, "Ух ты ж!" }, { 0.62, "Глянь-ка, какая громадина!" }, { 2.67, "Похоже, пони она больше жрать не будет, это уж точно." }, { 6.86, "Премного благодарен, приятель!" } }, f = { { 0.00, "Ух ты ж!" }, { 0.62, "Глянь-ка, какая громадина!" }, { 2.67, "Похоже, пони она больше жрать не будет, это уж точно." }, { 6.86, "Премного благодарен, подруга!" } } } } },
    [95992] = { d = 33.6, v = "narrator", n = { x = 326 }, c = { x = { { 0.00, "Здешние воды очень опасны." }, { 2.36, "Мои охотники за головами, конечно же, их зачищают, но есть в этих реках одна тварь, которую даже нам не изловить." }, { 11.89, "Что, интересно?" }, { 13.18, "Нам велели избавиться от зверюги, так что мы устраиваем состязание: кто изловит этого скользкого кроколиска, получит всю награду." }, { 23.93, "Ищите большого белого зверя, бродящего вдоль рек." }, { 28.12, "Принесите мне его клык." }, { 30.10, "Только в пасть ему не попадитесь!" }, { 32.92, "Тан'джани" } } } },
    [95998] = { d = 30.1, g = 1, v = "human-male", n = { m = 318, f = 319 }, c = { m = { { 0.00, "Приветствую, герой." }, { 1.45, "Ты, похоже, один из нас, искателей приключений." }, { 4.87, "Славно, славно." }, { 6.06, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 11.85, "Мир вокруг очень велик, и нужно учиться быть в диких краях как дома, чтобы преуспеть в нашем деле." }, { 19.16, "Не знаю, насколько ты уже в этом подкован, но если хочешь, могу научить тебя паре трюков." }, { 25.88, "Сядь у костра, устраивайся поудобнее, и я тебе всё расскажу." } }, f = { { 0.00, "Приветствую, героиня." }, { 1.55, "Ты, похоже, одна из нас, искателей приключений." }, { 4.91, "Славно, славно." }, { 6.07, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 11.75, "Мир вокруг очень велик, и нужно учиться быть в диких краях как дома, чтобы преуспеть в нашем деле." }, { 18.91, "Не знаю, насколько ты уже в этом подкована, но если хочешь, могу научить тебя паре трюков." }, { 25.56, "Сядь у костра, устраивайся поудобнее, и я тебе всё расскажу." } } }, t = { d = 9.7, v = "human-male", n = { x = 118 }, c = { x = { { 0.00, "Мы изучили основы, а теперь иди поучись ремеслу." }, { 3.35, "Тебе даже могут показать, как лучше обустроить лагерь в соответствии с твоей новой профессией." } } } } },
    [95999] = { d = 26.8, v = "narrator", n = { x = 288 }, c = { x = { { 0.00, "Разыскивается: Испепелитель Гар'им, предводитель армии орков в долине Ренда." }, { 6.09, "Предположительно работает с кланом Чёрной Горы в крепости Каменной Стражи." }, { 11.97, "Берегитесь Испепелителя Гар'има: он и его тёмные чародеи крайне опасны." }, { 17.63, "Смельчак, что предоставит доказательство гибели Испепелителя Гар'има мировому судье Соломону, получит щедрую награду." } } }, t = { d = 10.6, v = "human-male", n = { x = 125 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.25, "Испепелитель Гар'им готовился укрепить оборону крепости Каменной Стражи." }, { 6.58, "После этой победы у нас появился шанс отвоевать крепость!" } } } } },
    [96009] = { d = 33.4, v = "dwarf-male", n = { x = 376 }, c = { x = { { 0.00, "Что меня всегда восхищало в людях – это их упёртость." }, { 3.78, "Найдут какую-нибудь разорённую войной землю, где орки и сектанты кишмя кишат, и думают: \"Отличное место, поселюсь-ка я здесь!\" Вот это здорово." }, { 13.90, "Ладно, не мне их учить, где строиться." }, { 16.59, "Моё дело – показать, как это делать." }, { 19.22, "Они хотят, чтобы крепость была большой, а для этого понадобится немало древесины." }, { 25.11, "На дорогах сейчас опасно, так что поставки с лесопилки на северо-западе почти прекратились." }, { 31.58, "Притащишь нам пару связок?" } } }, t = { d = 8.9, v = "dwarf-male", n = { x = 89 }, c = { x = { { 0.00, "Ага, эти отлично подойдут." }, { 2.17, "Такими темпами, глядишь, и ворота достроим." }, { 5.60, "И хорошо бы — орки с каждым днём всё наглее." } } } } },
    [96010] = { d = 28.2, v = "nightelf-male#59", n = { x = 339 }, c = { x = { { 0.00, "Хотя повреждения обоих столпов, без сомнения, можно приписать неуклюжим вылазкам кентавров, осколки разделились именно после их недавнего буйства." }, { 10.28, "Я мало что знаю об их междоусобицах, но Шен'дралас подвергался набегам как минимум двух крупных фракций: свирепый клан Маграм и хитрый клан Гелкис." }, { 20.44, "Неразумно хранить сокровища посреди поля битвы." }, { 23.84, "Предположу, что сейчас они уже унесли трофеи по своим деревням." } } } },
    [96015] = { d = 25.4, v = "human-male#50", n = { x = 274 }, c = { x = { { 0.00, "Хвала Свету, что наши враги так глупы." }, { 2.93, "У Сумеречного Молота целая армия огров, но они держат их в шахте и не бросают в бой." }, { 9.19, "Уж не знаю, это ошибка командования или внутренняя грызня, но в любом случае огры сейчас беззащитны." }, { 16.72, "Наш выход." }, { 17.51, "Пока сектанты отвлеклись, мы можем нанести удар и ослабить врага." }, { 22.44, "Ступай в шахту и устрой там весёлую жизнь." } } } },
    [96016] = { d = 28.6, v = "dwarf-male", n = { x = 275 }, c = { x = { { 0.00, "Отлично сработано." }, { 1.54, "Вижу, тебе не терпится получить награду." }, { 4.93, "К сожалению, я мало что могу предложить." }, { 8.16, "*Вейрик разводит руками.*" }, { 10.48, "Хотя знаешь что..." }, { 11.95, "Говорят, в Альтеракских горах живёт тролль по имени Ветростраж." }, { 16.77, "Он сам могущественный шаман, большой знаток элементалей бури." }, { 21.52, "Если отнесёшь ему это ядро элементаля, он наверняка сделает оружие, достойное твоей победы." } } } },
    [96018] = { d = 26.3, g = 1, v = "nightelf-male#59", n = { m = 314, f = 315 }, c = { m = { { 0.00, "Видел парящие искры маны, рассыпанные по Шен'драласу?" }, { 3.71, "Это новое явление – скорее всего, результат повреждений столпов." }, { 8.23, "Нам нужно вернуть эту ману в полукристаллизованном виде." }, { 12.12, "Храмовый фильтр маны подойдёт для этих целей." }, { 15.21, "Возьми его ненадолго и собери блуждающие сферы маны вокруг." }, { 19.42, "Обитатели храма не одобрят, что мы забираем артефакт без их согласия, но со временем они нас поймут." } }, f = { { 0.00, "Видела парящие искры маны, рассыпанные по Шен'драласу?" }, { 3.88, "Это новое явление – скорее всего, результат повреждений столпов." }, { 8.40, "Нам нужно вернуть эту ману в полукристаллизованном виде." }, { 12.29, "Храмовый фильтр маны подойдёт для этих целей." }, { 15.38, "Возьми его ненадолго и собери блуждающие сферы маны вокруг." }, { 19.59, "Обитатели храма не одобрят, что мы забираем артефакт без их согласия, но со временем они нас поймут." } } } },
    [96020] = { d = 22.9, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Изваяние слегка тёплое на ощупь, хотя обугленное тело, с которого вы его сняли, давно остыло." }, { 8.04, "Похоже, несчастный так и не довершил то, что пытался совершить." }, { 13.32, "Вы не узнаёте надписей на идоле, но он взывает к вашей магии огня." }, { 18.90, "Возможно, у вас получится то, что не удалось ему." } } } },
    [96026] = { d = 16.6, v = "creature/ogre", n = { x = 152 }, c = { x = { { 0.00, "Хороший камень." }, { 1.43, "Но это не всё." }, { 2.69, "Надо больше." }, { 3.88, "Только камень делает камень сильнее." }, { 7.21, "Так правильно." }, { 8.48, "Я знаю, что мелкие делают очень тяжёлые камни." }, { 12.60, "Принеси мне тяжёлый камень, и мы сделаем оружие." } } } },
    [96027] = { d = 22.2, v = "creature/ogre", n = { x = 199 }, c = { x = { { 0.00, "Бал застрять с надоедливой головой." }, { 3.11, "Мог ходить везде, куда Бал идти." }, { 6.06, "Надоел!" }, { 6.78, "Он говорить, магия сильнее всего." }, { 9.80, "Ха!" }, { 10.12, "Без Бал Мог колдовать на пустое место!" }, { 13.47, "Бал не нужен Мог!" }, { 14.99, "Бал показать — кулака хватит!" }, { 17.62, "Мы убить много мелких." }, { 19.69, "Показать Мог, что кулак лучше." } } } },
    [96028] = { d = 16.8, v = "creature/ogre", n = { x = 151 }, c = { x = { { 0.00, "Бал глупый." }, { 1.05, "Он только бить хотеть." }, { 3.07, "Мог умный." }, { 4.04, "Мог учить магию, чтобы Бал'мог стать сильнее." }, { 8.16, "Мы показать Бал, что он глупый." }, { 10.90, "Мы использовать магию." }, { 12.92, "Использовать магию и показать, что Мог лучше!" } } } },
