    [96055] = { d = 30.4, v = "dwarf-male", n = { x = 346 }, c = { x = { { 0.00, "Ты, похоже, уже многое знаешь о травничестве." }, { 3.31, "Собирать цветы – не просто развлечение." }, { 6.16, "Это занятие может быть полезным... и весьма прибыльным." }, { 10.18, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать ароматную свечу для лагеря." }, { 16.73, "Чтобы целители и заклинатели достойно показывали себя в бою, им нужно правильное состояние духа, и ароматические свечи в этом здорово помогают." }, { 27.11, "Все знакомые заклинатели будут тебе благодарны." } } }, t = { d = 27.0, g = 1, v = "dwarf-female", n = { m = 306, f = 307 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственную ароматную свечу." }, { 4.23, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 9.37, "Это лучше делать на природе." }, { 11.51, "Да, и помни, что без костра никакого лагеря не получится." }, { 15.61, "Так что сначала придётся разжечь костёр." }, { 18.41, "Этому тебя может научить почти любой специалист по кулинарии." }, { 22.96, "Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственную ароматную свечу." }, { 4.16, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 9.20, "Это лучше делать на природе." }, { 11.31, "Да, и помни, что без костра никакого лагеря не получится." }, { 15.34, "Так что сначала придётся разжечь костёр." }, { 18.09, "Этому тебя может научить почти любой специалист по кулинарии." }, { 22.56, "Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
