    [96059] = { d = 19.6, g = 1, v = "dwarf-male", n = { m = 232, f = 233 }, c = { m = { { 0.00, "Раз ты решил стать зачаровывателем, я, пожалуй, смогу научить тебя создавать зачарованную лютню для лагеря, когда ты немножко наберёшься опыта в этом ремесле." }, { 10.79, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы в пути." } }, f = { { 0.00, "Раз ты решила стать зачаровывателем, я, пожалуй, смогу научить тебя создавать зачарованную лютню для лагеря, когда ты немножко наберёшься опыта в этом ремесле." }, { 11.04, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы в пути." } } }, t = { d = 26.2, g = 1, v = "dwarf-male", n = { m = 309, f = 310 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственную зачарованную лютню." }, { 4.26, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 9.21, "Это лучше делать на природе." }, { 11.28, "Да, и помни, что без костра никакого лагеря не получится." }, { 15.23, "Так что сначала придётся разжечь костёр." }, { 17.92, "Этому тебя может научить почти любой специалист по кулинарии." }, { 22.31, "Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственную зачарованную лютню." }, { 4.19, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 9.05, "Это лучше делать на природе." }, { 11.08, "Да, и помни, что без костра никакого лагеря не получится." }, { 14.96, "Так что сначала придётся разжечь костёр." }, { 17.61, "Этому тебя может научить почти любой специалист по кулинарии." }, { 21.92, "Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
    [96060] = { d = 32.4, v = "narrator", n = { x = 345 }, c = { x = { { 0.00, "Да будет тебе известно, что при жизни я в совершенстве овладел искусством фехтования." }, { 6.47, "Днём я ковал мечи, а ночью пускал их в дело." }, { 9.91, "Как ты прекрасно знаешь, мы с этим клинком в патовой ситуации." }, { 14.66, "Даже если я начну им размахивать, смысла будет немного – разве что в бою с другими призраками." }, { 21.95, "Какая мне от него польза в Шен'драласе?" }, { 24.98, "Но всё-таки его работоспособность стоит проверить, а в лесах расплодилось многовато разной живности." } } } },
    [96063] = { d = 26.2, v = "goblin-male", n = { x = 290 }, c = { x = { { 0.00, "Топливо будущего – не уголь и не нефть, а газ, детка!" }, { 3.76, "Эти болотца на юго-западе извергают его тоннами, а у меня как раз есть изобретение, которое позволит его использовать, – новый тип двигателя." }, { 13.94, "Правда, собирать газ – это боль." }, { 16.27, "Если хочешь внести скромный вклад в развитие науки и техники, помоги мне добыть немного газа?" }, { 23.08, "Увидишь, он выходит из таких гейзеров у воды." } } } },
    [96067] = { d = 26.6, g = 1, v = "goblin-male", n = { m = 298, f = 299 }, c = { m = { { 0.00, "Ты, наверное, уже обратил внимание на моего механического спутника Г43-П4К." }, { 6.84, "В его джутовой груди рычит единственный и неповторимый рабочий прототип моего газового двигателя." }, { 13.95, "Думаю, надо провести нагрузочное испытание." }, { 17.14, "Как насчёт того, чтобы подраться с ним?" }, { 19.95, "Я закачаю в него собранный тобой газ." }, { 22.68, "И не бойся, бей со всей силы." }, { 24.77, "Он ничего не чувствует!" } }, f = { { 0.00, "Ты, наверное, уже обратила внимание на моего механического спутника Г43-П4К." }, { 7.12, "В его джутовой груди рычит единственный и неповторимый рабочий прототип моего газового двигателя." }, { 14.23, "Думаю, надо провести нагрузочное испытание." }, { 17.42, "Как насчёт того, чтобы подраться с ним?" }, { 20.23, "Я закачаю в него собранный тобой газ." }, { 22.96, "И не бойся, бей со всей силы." }, { 25.05, "Он ничего не чувствует!" } } } },
    [96078] = { d = 35.1, v = "troll-male#77", n = { x = 385 }, c = { x = { { 0.00, "Племя Чёрного Копья сохраняет традиции, передавая истории из уст в уста." }, { 5.51, "Мы рассказываем следующему поколению такие легенды, содержащие важные уроки и предостережения для потомков." }, { 13.64, "Оттиски нужно отнести нашему духовному лидеру, мастеру Гадрину, в деревню Сен'джин." }, { 20.05, "Он мудрейший из троллей Чёрного Копья и наверняка захочет услышать эту легенду." }, { 26.11, "Я приготовил экземпляр и для тебя." }, { 28.72, "Если вдруг случайно потеряешь его, я с радостью сделаю ещё один – за небольшую плату." } } }, t = { d = 36.8, g = 1, v = "troll-male#77", n = { m = 291, f = 292 }, c = { m = { { 0.00, "*Мастер Гадрин внимательно слушает рассказ о вашем путешествии и о том, как к вам попали надписи с табличек И'лалая.*" }, { 8.56, "Кин'вилай правильно сделал, что отправил тебя сюда." }, { 12.74, "Я благодарен ему за то, что он старается разыскать и сохранить наследие, которое мы потеряли за прошедшие века." }, { 21.53, "В исторических масштабах племя Чёрного Копья откололось от империи Гурубаши не так уж давно, знаешь ли." }, { 29.67, "Кстати, Кин'вилай попросил отдать тебе это – в благодарность за всё, что ты сегодня сделал." } }, f = { { 0.00, "*Мастер Гадрин внимательно слушает рассказ о вашем путешествии и о том, как к вам попали надписи с табличек И'лалая.*" }, { 8.56, "Кин'вилай правильно сделал, что отправил тебя сюда." }, { 12.74, "Я благодарен ему за то, что он старается разыскать и сохранить наследие, которое мы потеряли за прошедшие века." }, { 21.53, "В исторических масштабах племя Чёрного Копья откололось от империи Гурубаши не так уж давно, знаешь ли." }, { 29.58, "Кстати, Кин'вилай попросил отдать тебе это – в благодарность за всё, что ты сегодня сделала." } } } } },
    [96081] = { d = 25.4, v = "human-male", n = { x = 297 }, c = { x = { { 0.00, "Чего всегда не хватает в армии, так это бинтов." }, { 3.39, "К сожалению, в Фархолде не производят ткань, поэтому нам приходится полагаться на то, что привозят гоблины." }, { 10.66, "Или, если повезёт, на добычу, отнятую у орков." }, { 13.92, "Сейчас запасы качественной ткани как раз подходят к концу, и скоро мне придётся делать бинты из орочьих рубах." }, { 21.57, "Если сможешь нам как-то помочь, то спасёшь немало жизней." } } }, t = { d = 4.2, v = "human-male", n = { x = 45 }, c = { x = { { 0.00, "Спасибо." }, { 0.72, "Скоро мы с тобой найдём им хорошее применение." } } } } },
    [96082] = { d = 16.8, g = 1, v = "human-male", n = { m = 187, f = 189 }, c = { m = { { 0.00, "Я сделаю новые бинты из ткани, которую ты принёс." }, { 3.45, "А ты пока возьми, пожалуйста, готовые и перевяжи раненых воинов." }, { 7.96, "Ничего сложного тут нет, не волнуйся." }, { 10.53, "Буду благодарен за помощь, она сейчас так нужна!" }, { 13.97, "У меня, к сожалению, всего две руки." } }, f = { { 0.00, "Я сделаю новые бинты из ткани, которую ты принесла." }, { 3.82, "А ты пока возьми, пожалуйста, готовые и перевяжи раненых воинов." }, { 8.33, "Ничего сложного тут нет, не волнуйся." }, { 10.90, "Буду благодарен за помощь, она сейчас так нужна!" }, { 14.34, "У меня, к сожалению, всего две руки." } } }, t = { d = 14.6, v = "human-male", n = { x = 91 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.16, "Пока этого хватит." }, { 2.58, "По крайней мере, пока их раны снова не откроются или не привезут новых солдат..." }, { 8.40, "*Брат Лоули на мгновение потирает виски, а затем вновь принимает невозмутимый вид.*" } } } } },
    [96083] = { d = 14.4, v = "human-male", n = { x = 182 }, c = { x = { { 0.00, "Здесь ты пока ничем больше не поможешь." }, { 2.63, "Если хочешь ещё подсобить, ступай в часовню на холме." }, { 6.22, "Это небольшое здание у церкви." }, { 8.32, "Сестра Роуланд устроила там карантин для нескольких воинов, заразившихся неизвестной болезнью." } } }, t = { d = 10.0, g = 1, v = "human-female", n = { m = 112, f = 113 }, c = { m = { { 0.00, "А, так тебя прислал брат Лоули?" }, { 2.25, "Трудно поверить, что он смог выделить лишнюю пару рук." }, { 6.10, "Значит, ты хорошо справился со своими обязанностями." } }, f = { { 0.00, "А, так тебя прислал брат Лоули?" }, { 2.25, "Трудно поверить, что он смог выделить лишнюю пару рук." }, { 6.10, "Значит, ты хорошо справилась со своими обязанностями." } } } } },
    [96084] = { d = 28.8, v = "human-female", n = { x = 341 }, c = { x = { { 0.00, "Не стану утомлять тебя мрачными подробностями, но эти воины тяжело больны." }, { 5.12, "Я полагаю, что-то не так либо с их пищей, либо с водой, которую они пили." }, { 10.18, "Провизию, что привозят с окрестных ферм, я уже проверила, так что остаётся только вода." }, { 15.96, "Она вся поступает из рек, текущих в округе." }, { 18.89, "Собери образцы из водоёмов на равнинах к северу." }, { 22.12, "Там протекают почти все реки в этих местах, так что начать поиски заразы оттуда – очевидное решение." } } }, t = { d = 4.9, v = "human-female", n = { x = 48 }, c = { x = { { 0.00, "Выглядит... отвратительно." }, { 2.21, "Что же могло так загрязнить воду?" } } } } },
    [96085] = { d = 26.3, v = "human-female", n = { x = 304 }, c = { x = { { 0.00, "Эта мерзость в воде кажется органической." }, { 3.00, "Не нечистоты, но что-то ядовитое." }, { 5.36, "Я, конечно, не специалист по диким животным, но предположу, что какое-то существо выше по течению загрязняет воду." }, { 13.39, "Ступай вдоль рек как можно дальше на север и попытайся выяснить, что там творится." }, { 19.13, "Если дело и вправду в каком-то животном, то его надо убить ради безопасности всех обитателей Фархолда." } } } },
    [96101] = { d = 29.0, g = 1, v = "skyborne-male", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Приветствую, герой." }, { 1.50, "Ты, похоже, один из нас, искателей приключений." }, { 5.06, "Это хорошо." }, { 6.02, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 12.04, "Чтобы преуспевать в этом деле, тебе нужно быть в диких краях как дома." }, { 17.51, "Не знаю, насколько ты уже в этом подкован, но, возможно, смогу научить тебя паре трюков, если хочешь." }, { 25.37, "Сядь у костра поудобнее." }, { 27.22, "Я тебе всё расскажу." } }, f = { { 0.00, "Приветствую, героиня." }, { 1.65, "Ты, похоже, одна из нас, искателей приключений." }, { 5.22, "Это хорошо." }, { 6.18, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 12.22, "Чтобы преуспевать в этом деле, тебе нужно быть в диких краях как дома." }, { 17.71, "Не знаю, насколько ты уже в этом подкована, но, возможно, смогу научить тебя паре трюков, если хочешь." }, { 25.68, "Сядь у костра поудобнее." }, { 27.53, "Я тебе всё расскажу." } } }, t = { d = 12.1, v = "skyborne-male", n = { x = 142 }, c = { x = { { 0.00, "Мы изучили основы, а теперь иди поучись ремеслу у наставников в деревне поблизости." }, { 5.95, "Они даже могут показать, как обустроить лагерь в соответствии с твоей новой профессией." } } } } },
    [96102] = { d = 25.0, g = 1, v = "orc-male", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Портняжное дело – на удивление полезный навык, который, не сомневаюсь, будет часто тебя выручать." }, { 8.22, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря." }, { 14.71, "Если, конечно, ты достаточно умел для этого." }, { 18.48, "В любой битве боевой дух очень важен, и вдохновляющее знамя может его поднять." } }, f = { { 0.00, "Портняжное дело – на удивление полезный навык, который, не сомневаюсь, будет часто тебя выручать." }, { 7.99, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря." }, { 14.29, "Если, конечно, ты достаточно умела для этого." }, { 18.03, "В любой битве боевой дух очень важен, и вдохновляющее знамя может его поднять." } } }, t = { d = 29.8, g = 1, v = "orc-male", n = { m = 318, f = 319 }, c = { m = { { 0.00, "Вот и всё – теперь ты можешь создать собственное знамя фракции." }, { 4.56, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать его придётся где-нибудь на природе." }, { 13.43, "Да, и помни: без костра никакого лагеря не получится." }, { 17.27, "Сначала придётся его разжечь." }, { 19.42, "Этому может научить почти любой повар." }, { 22.35, "Если ещё не озаботился этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } }, f = { { 0.00, "Вот и всё – теперь ты можешь создать собственное знамя фракции." }, { 4.77, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать его придётся где-нибудь на природе." }, { 14.03, "Да, и помни: без костра никакого лагеря не получится." }, { 18.05, "Сначала придётся его разжечь." }, { 20.30, "Этому может научить почти любой повар." }, { 23.37, "Если ещё не озаботилась этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } } } } },
    [96103] = { d = 27.1, v = "narrator", n = { x = 278 }, c = { x = { { 0.00, "Скелет в плохом состоянии." }, { 2.16, "Глубокие отметины на руках и ногах похожи на следы от клыков и когтей." }, { 7.86, "Много дней под палящим солнцем выбелили кости и сделали их хрупкими." }, { 13.35, "Свирепость убийцы и суровый климат не позволяют опознать жертву." }, { 18.54, "Вам будет трудно унести весь скелет, но можно отнести череп охотнику в Рог'мар и спросить, что ему известно." } } } },
    [96104] = { d = 32.3, g = 1, v = "orc-female#58", n = { m = 312, f = 312 }, c = { m = { { 0.00, "Это следы от клыков льва." }, { 2.10, "И судя по всему, очень крупного." }, { 4.78, "Вожака местного прайда, не иначе." }, { 7.53, "Я бы с радостью пошла на него сама, но череп нашёл ты, так что и охота тоже твоя." }, { 14.04, "А я помогу." }, { 14.98, "Сделаю для тебя манок, подражающий крику раненого долгонога." }, { 19.90, "С его помощью ты выманишь зверя." }, { 22.58, "Но чтобы звук был правильным, мне нужен клюв долгонога – их тут вокруг полно." }, { 28.66, "Принеси мне клюв, и начнём большую охоту!" } }, f = { { 0.00, "Это следы от клыков льва." }, { 2.10, "И судя по всему, очень крупного." }, { 4.78, "Вожака местного прайда, не иначе." }, { 7.53, "Я бы с радостью пошла на него сама, но череп нашла ты, так что и охота тоже твоя." }, { 14.55, "А я помогу." }, { 15.49, "Сделаю для тебя манок, подражающий крику раненого долгонога." }, { 20.41, "С его помощью ты выманишь зверя." }, { 23.09, "Но чтобы звук был правильным, мне нужен клюв долгонога – их тут вокруг полно." }, { 29.17, "Принеси мне клюв, и начнём большую охоту!" } } } },
    [96105] = { d = 15.5, g = 1, v = "orc-female#58", n = { m = 139, f = 140 }, c = { m = { { 0.00, "Манок готов." }, { 1.13, "Бери его и поднимись на вершину холма, где живут львы – ступай на юг." }, { 6.91, "Как будешь готов к битве, дунь в свисток, и зверь появится." }, { 11.79, "Доброй охоты!" }, { 13.00, "Возвращайся с победой." } }, f = { { 0.00, "Манок готов." }, { 1.13, "Бери его и поднимись на вершину холма, где живут львы – ступай на юг." }, { 6.91, "Как будешь готова к битве, дунь в свисток, и зверь появится." }, { 12.61, "Доброй охоты!" }, { 13.82, "Возвращайся с победой." } } } },
    [96107] = { d = 16.3, v = "orc-female#58", n = { x = 163 }, c = { x = { { 0.00, "За свою жизнь охотник тратит больше стрел, чем звёзд на небе." }, { 4.99, "Я свои делаю сама, никому больше не доверяю." }, { 8.80, "И лучшее оперение получается из жёстких перьев здешних канюков." }, { 14.01, "Поможешь мне собрать немного?" } } } },
    [96108] = { d = 29.8, g = 1, v = "orc-female#58", n = { m = 253, f = 253 }, c = { m = { { 0.00, "Стрелы – это главное, но иногда, чтобы убить добычу, нужно что-то посильнее." }, { 6.79, "Тогда мы берём яд." }, { 8.35, "Мясо после этого есть нельзя, но если главное – убить, то это не страшно." }, { 14.83, "Яд можно сварить или, если ты смелый, добыть." }, { 18.89, "Мне кажется, ты смелый." }, { 20.92, "В озёрах к югу водятся очень ядовитые гадюки." }, { 24.90, "Если я в тебе не ошиблась, ты добудешь их яд." } }, f = { { 0.00, "Стрелы – это главное, но иногда, чтобы убить добычу, нужно что-то посильнее." }, { 6.79, "Тогда мы берём яд." }, { 8.35, "Мясо после этого есть нельзя, но если главное – убить, то это не страшно." }, { 14.51, "Яд можно сварить или, если ты смелая, добыть." }, { 19.51, "Мне кажется, ты смелая." }, { 22.05, "В озёрах к югу водятся очень ядовитые гадюки." }, { 26.03, "Если я в тебе не ошиблась, ты добудешь их яд." } } } },
    [96109] = { d = 26.8, v = "orc-female#58", n = { x = 273 }, c = { x = { { 0.00, "Колчан для охотника так же важен, как оружие." }, { 3.55, "Хороший колчан вмещает много стрел и не мешает ходить." }, { 7.87, "Он должен быть прочным и удобно прилегать к телу." }, { 11.77, "В этих краях для колчана нет лучшего материала, чем шкура льва." }, { 16.74, "Она самой природой создана для жизни охотника." }, { 20.50, "Львы живут у холма к югу отсюда, вон его видно." }, { 24.33, "Будь другом, добудь мне их шкуры." } } } },
    [96125] = { d = 33.1, v = "human-male", n = { x = 387 }, c = { x = { { 0.00, "Теперь, когда львиные шкуры собраны и мы избавились от орков-браконьеров, я наконец-то могу отдохнуть." }, { 7.14, "То есть так бы я сказал, если бы человек, который должен меня сменить, не пропал." }, { 12.78, "Данстон Виллис, наш выдающийся исследователь, несколько дней назад ушёл осмотреть поселение огров на севере." }, { 20.23, "Сказал, что, когда вернётся, заменит меня на посту." }, { 23.80, "Найди его." }, { 24.62, "Если он жив, приведи сюда." }, { 26.50, "А если висит на мясницком крюке, принеси доказательство, чтобы Демар прислал мне кого-нибудь ещё." } } }, t = { d = 6.4, g = 1, v = "human-male", n = { m = 66, f = 66 }, c = { m = { { 0.00, "Ты пришёл из Дозора Террала?" }, { 2.17, "Хех, уверен, Корнелий сейчас мной не слишком доволен." } }, f = { { 0.00, "Ты пришла из Дозора Террала?" }, { 2.44, "Хех, уверен, Корнелий сейчас мной не слишком доволен." } } } } },
    [96126] = { d = 30.2, g = 1, v = "human-male", n = { m = 334, f = 335 }, c = { m = { { 0.00, "Не знаю, как ты сюда добрался, но послушай." }, { 3.06, "Как ты уже знаешь, я служу дозорным в крепости Фархолд." }, { 7.02, "Я был в патруле, когда эти громилы застали меня врасплох и взяли в плен." }, { 12.19, "Теперь заставляют сражаться им на потеху." }, { 15.13, "У меня почти не осталось сил." }, { 17.23, "Если я и смогу сбежать, то сейчас или никогда." }, { 20.62, "Мой похититель – огр, которого остальные зовут Гронок Мясник." }, { 24.96, "Ключ от моих оков у него." }, { 26.81, "Можешь достать ключ, чтобы я выбрался отсюда?" } }, f = { { 0.00, "Не знаю, как ты сюда добралась, но послушай." }, { 3.33, "Как ты уже знаешь, я служу дозорным в крепости Фархолд." }, { 7.29, "Я был в патруле, когда эти громилы застали меня врасплох и взяли в плен." }, { 12.46, "Теперь заставляют сражаться им на потеху." }, { 15.40, "У меня почти не осталось сил." }, { 17.50, "Если я и смогу сбежать, то сейчас или никогда." }, { 20.89, "Мой похититель – огр, которого остальные зовут Гронок Мясник." }, { 25.23, "Ключ от моих оков у него." }, { 27.08, "Можешь достать ключ, чтобы я выбрался отсюда?" } } }, t = { d = 6.7, v = "human-male", n = { x = 65 }, c = { x = { { 0.00, "Ключ у тебя!" }, { 1.08, "Отлично!" }, { 1.85, "Я бесконечно благодарен." }, { 3.94, "А теперь давай выбираться отсюда." } } } } },
    [96130] = { d = 43.8, v = "tauren-male", n = { x = 397 }, c = { x = { { 0.00, "Среди степных волков, охотящихся в окрестных холмах, есть одна особенно агрессивная волчица." }, { 8.33, "Мы её прозвали Чакуак." }, { 10.35, "Она стала настоящей угрозой для странников, прибывающих издалека." }, { 16.26, "Её охотничьи угодья – леса к западу от озера Каменного Быка, где она кочует от лабаза к лабазу." }, { 24.91, "Разделайся с опасной волчицей и принеси мне её шкуру, а я замолвлю за тебя словечко вождю." }, { 33.00, "Сохраняй бдительность – она крайне опасна!" }, { 36.88, "Может, ты встретишь там других охотников, ищущих её, и объединишь с ними силы." } } }, t = { d = 16.0, v = "tauren-male", n = { x = 137 }, c = { x = { { 0.00, "Смерть такого прекрасного существа – печальное событие, но это необходимо для безопасности нашего народа." }, { 10.19, "Я позабочусь о том, чтобы шкура не пропала зря." }, { 14.76, "Спасибо тебе." } } } } },
    [96135] = { d = 32.1, v = "dwarf-male", n = { x = 334 }, c = { x = { { 0.00, "Фу, рядом с этими проклятыми тотемами у меня прямо мурашки по коже... но это хорошо." }, { 6.63, "Тут такая концентрация скверны, что нам как раз хватит, чтобы призвать элементалей свинобразов." }, { 13.88, "Ступай в Тысячу Игл и найди подходящее место для обороны." }, { 18.35, "Думаю, подойдут горячие источники." }, { 21.07, "Там полно и огня, и земли, и воды, и воздуха." }, { 24.63, "Размести эти тотемы и приготовься к драке." }, { 27.97, "Иглогривым не понравится, что ты вмешиваешься в их дела." } } } },
    [96136] = { d = 25.8, g = 1, v = "skyborne-female", n = { m = 272, f = 274 }, c = { m = { { 0.00, "Как ты наверняка уже понял сам, стихии Азерота отличаются от того, к чему привыкли жители Зефриса." }, { 7.50, "Одно дело использовать силы природы на стихийных полях, и совсем другое – делать то же самое здесь, внизу." }, { 15.62, "Я могла бы вручить тебе тотем воздуха, но думаю, что будет больше пользы, если ты поговоришь с кем-то, кто обучает местных." }, { 25.03, "Что скажешь?" } }, f = { { 0.00, "Как ты наверняка уже поняла сама, стихии Азерота отличаются от того, к чему привыкли жители Зефриса." }, { 7.60, "Одно дело использовать силы природы на стихийных полях, и совсем другое – делать то же самое здесь, внизу." }, { 15.60, "Я могла бы вручить тебе тотем воздуха, но думаю, что будет больше пользы, если ты поговоришь с кем-то, кто обучает местных." }, { 24.89, "Что скажешь?" } } } },
    [96137] = { d = 25.1, v = "narrator", n = { x = 277 }, c = { x = { { 0.00, "Небольшой кинжал, принадлежавший самопровозглашённому следопыту Ире, которая следила за тем, чтобы обитающие в лесах звери не представляли угрозы для путешественников." }, { 12.63, "Судя по тому, что дух Иры всё ещё бродит среди деревьев, можно предположить, что у неё есть незавершённое дело – уничтожить воргов, нападающих на людей по всему лесу." } } }, t = { d = 12.6, g = 1, v = "human-male", n = { m = 132, f = 133 }, c = { m = { { 0.00, "Ира?" }, { 0.40, "Ты уверен?" }, { 1.21, "Говорят, эта женщина была почти призраком ещё до смерти." }, { 5.53, "Удивительно, что ты вообще её нашёл." }, { 8.15, "Не сомневайся, я буду очень бережно хранить этот кинжал." } }, f = { { 0.00, "Ира?" }, { 0.41, "Ты уверена?" }, { 1.30, "Говорят, эта женщина была почти призраком ещё до смерти." }, { 5.68, "Удивительно, что ты вообще её нашла." }, { 8.41, "Не сомневайся, я буду очень бережно хранить этот кинжал." } } } } },
    [96138] = { d = 25.3, v = "narrator", n = { x = 274 }, c = { x = { { 0.00, "Лук, оставленный духом Меррика Вэлора – знаменитого дозорного, гордо защищавшего дороги от подступающих врагов." }, { 8.43, "Судя по тому, что дух Меррика всё ещё бродит по дороге, можно предположить, что у него есть незавершённое дело – уничтожить захватчиков возле его дома на Вороньем Холме." }, { 21.18, "Вероятно, огры к югу от города не дают ему упокоиться." } } }, t = { d = 13.8, g = 1, v = "human-male", n = { m = 156, f = 158 }, c = { m = { { 0.00, "Меррик Вэлор, говоришь?" }, { 1.74, "Бедный мальчик всегда хотел себя проявить." }, { 4.90, "Жаль, что так вышло с ним и его семьёй." }, { 7.60, "Спасибо, что принёс это." }, { 9.34, "Может, это прольёт ещё немного света на историю Вороньего Холма." } }, f = { { 0.00, "Меррик Вэлор, говоришь?" }, { 1.68, "Бедный мальчик всегда хотел себя проявить." }, { 4.72, "Жаль, что так вышло с ним и его семьёй." }, { 7.33, "Спасибо, что принесла это." }, { 9.19, "Может, это прольёт ещё немного света на историю Вороньего Холма." } } } } },
    [96139] = { d = 36.8, g = 1, v = "human-male", n = { m = 410, f = 411 }, c = { m = { { 0.00, "В эти тёмные времена мы должны помнить наших героев не хуже, чем наших врагов." }, { 5.71, "Темнолесья бы не было, если бы не подвиги отважной леди Алтеи и тех смельчаков, что сложили головы на Вороньем Холме." }, { 14.15, "Читал ли ты о Вороньем Холме?" }, { 16.30, "Нет?" }, { 16.62, "Я так и думал." }, { 17.66, "История этого места была забыта, стёрта с лица земли вместе с его обитателями." }, { 23.44, "Даже в моей огромной библиотеке почти нет записей о нём." }, { 27.53, "Если найдёшь что-нибудь, что касается Вороньего Холма, принеси это мне, пожалуйста." }, { 33.50, "Его жители заслуживают того, чтобы их помнили." } }, f = { { 0.00, "В эти тёмные времена мы должны помнить наших героев не хуже, чем наших врагов." }, { 5.60, "Темнолесья бы не было, если бы не подвиги отважной леди Алтеи и тех смельчаков, что сложили головы на Вороньем Холме." }, { 13.88, "Читала ли ты о Вороньем Холме?" }, { 16.05, "Нет?" }, { 16.37, "Я так и думал." }, { 17.39, "История этого места была забыта, стёрта с лица земли вместе с его обитателями." }, { 23.06, "Даже в моей огромной библиотеке почти нет записей о нём." }, { 27.07, "Если найдёшь что-нибудь, что касается Вороньего Холма, принеси это мне, пожалуйста." }, { 32.93, "Его жители заслуживают того, чтобы их помнили." } } }, t = { d = 19.4, v = "human-male", n = { x = 214 }, c = { x = { { 0.00, "Похоже, это книга о семействе Вэлор." }, { 2.71, "Кажется, я слышал про кого-то из них." }, { 5.35, "Хорошие люди, хотя вряд ли стоили того, чтобы писать о них целую книгу." }, { 10.57, "Я сделаю для тебя копию этого фолианта." }, { 13.46, "Если найдёшь ещё что-нибудь, связанное с этой семьёй, я с радостью изучу твою находку." } } } } },
    [96204] = { d = 9.4, g = 1, v = "skyborne-female", n = { x = 85 }, c = { m = { { 0.00, "Раз я на свободе, эти поганые твари пожалеют, что посмели хоть взглянуть на Ваятеля Ветра." }, { 7.23, "Уходим отсюда, герой." } }, f = { { 0.00, "Раз я на свободе, эти поганые твари пожалеют, что посмели хоть взглянуть на Ваятеля Ветра." }, { 7.49, "Уходим отсюда, героиня." } } }, t = { d = 30.6, v = "skyborne-female", n = { x = 329 }, c = { x = { { 0.00, "Ещё раз спасибо." }, { 1.24, "Мне довелось познакомиться с Треваном – как выяснилось, именно он отправил тебя по моему следу." }, { 8.47, "До сих пор в своих странствиях я слышала о паладинах... не самые лестные вещи." }, { 14.39, "Но шен'дорай, отмеченным небом, нелегко странствовать по землям Орды, так что я прекрасно понимаю, как легко пускают корни нетерпимость и предрассудки." }, { 25.82, "У тебя и твоих собратьев теперь есть друг среди Ваятелей ветра." } } } } },
    [96209] = { d = 22.7, v = "nightelf-male", n = { x = 231 }, c = { x = { { 0.00, "Древень Орокай несёт стражу неподалёку от селения." }, { 3.93, "Отнеси ему это." }, { 5.29, "Древни — удивительные и мудрые существа." }, { 8.51, "Если эту ветвь не слишком давно отделили от родного дерева, он сможет «поговорить» с ней и узнать, какие истории она хранит." }, { 18.44, "Орокай стоит к юго-западу от селения, совсем недалеко." } } } },
    [96222] = { d = 39.8, v = "named/5398", n = { x = 404 }, c = { x = { { 0.00, "Пока война терзает эти земли, кентавры из племени Мародин безраздельно властвуют в долине Копий." }, { 7.69, "Боюсь, если остальные кланы продолжат их игнорировать, они ещё больше осмелеют и станут и дальше сеять рознь." }, { 16.29, "У вождя Храты есть фрагмент ключа Мародина, и я хочу заполучить его, чтобы использовать как козырь на переговорах." }, { 25.25, "Отбери у одного из тамошних кентавров загубник боевого горна и используй его на самом высоком пике, чтобы вызвать вождя на бой." }, { 36.46, "Принеси ключ мне, и я кое-что тебе предложу." } } } },
    [96241] = { d = 31.2, v = "troll-male", n = { x = 326 }, c = { x = { { 0.00, "Тут на Мрачной вершине что-то странное творится." }, { 3.74, "Старина Мазу'кон не раз уже слыхал об этих противных тварях, что шастают тут, будто у себя дома." }, { 11.90, "Поговаривают, некоторые из этих ползучников ядовитые, и их яд обладает какими-то особыми свойствами – вот это мне страсть как интересно." }, { 22.15, "Возьми мой экстрактор и собери немного яда с трупов, что валяются тут неподалёку." }, { 28.32, "Буду тебе очень признателен, дружище." } } }, t = { d = 13.5, g = 1, v = "troll-male", n = { m = 110, f = 112 }, c = { m = { { 0.00, "Хе... когда я говорил про необычные свойства, я не шутил, мон!" }, { 5.15, "Но ты, вроде, цел и невредим, так что всё хорошо." }, { 9.17, "Спасибо за помощь, герой." }, { 11.36, "Я очень ценю это." } }, f = { { 0.00, "Хе... когда я говорил про необычные свойства, я не шутил, мон!" }, { 5.28, "Но ты, вроде, цела и невредима, так что всё хорошо." }, { 9.64, "Спасибо за помощь, героиня." }, { 12.05, "Я очень ценю это." } } } } },
    [96243] = { d = 25.0, g = 1, v = "dwarf-female", n = { m = 270, f = 272 }, c = { m = { { 0.00, "Тебе давно пора прислушаться к земле, храбрый шаман." }, { 4.01, "Стихии уже пронизывают тебя, но когда начнёшь говорить со скалами, сама земля создаст крепкий фундамент у тебя под ногами и укрепит твою душу." }, { 14.71, "Отправляйся к Тео Молотошторму в Холодную долину." }, { 18.39, "Найдёшь его в Старой Наковальне, укреплении, созданном молотом, огнём и силой воли." } }, f = { { 0.00, "Тебе давно пора прислушаться к земле, храбрая шаманка." }, { 4.23, "Стихии уже пронизывают тебя, но когда начнёшь говорить со скалами, сама земля создаст крепкий фундамент у тебя под ногами и укрепит твою душу." }, { 15.15, "Отправляйся к Тео Молотошторму в Холодную долину." }, { 18.91, "Найдёшь его в Старой Наковальне, укреплении, созданном молотом, огнём и силой воли." } } }, npc = { [258098] = { d = 25.1, g = 1, v = "dwarf-male", n = { m = 270, f = 272 }, c = { m = { { 0.00, "Тебе давно пора прислушаться к земле, храбрый шаман." }, { 4.09, "Стихии уже пронизывают тебя, но когда начнёшь говорить со скалами, сама земля создаст крепкий фундамент у тебя под ногами и укрепит твою душу." }, { 15.00, "Отправляйся к Тео Молотошторму в Холодную долину." }, { 18.75, "Найдёшь его в Старой Наковальне, укреплении, созданном молотом, огнём и силой воли." } }, f = { { 0.00, "Тебе давно пора прислушаться к земле, храбрая шаманка." }, { 4.36, "Стихии уже пронизывают тебя, но когда начнёшь говорить со скалами, сама земля создаст крепкий фундамент у тебя под ногами и укрепит твою душу." }, { 15.27, "Отправляйся к Тео Молотошторму в Холодную долину." }, { 19.02, "Найдёшь его в Старой Наковальне, укреплении, созданном молотом, огнём и силой воли." } } } } }, t = { d = 11.3, v = "dwarf-male", n = { x = 112 }, c = { x = { { 0.00, "Сама земля дала мне знать, что ты идёшь!" }, { 3.14, "Ага, порой огня, что горит у нас внутри, хватает, чтобы пронестись сквозь снега, даже не касаясь земли!" } } } } },
    [96259] = { d = 38.1, g = 1, v = "tauren-male", n = { m = 389, f = 391 }, c = { m = { { 0.00, "В месте под названием Мрачная вершина к северо-западу от этого лагеря есть древнее тауренское кладбище." }, { 8.51, "Недавно там завелись чрезвычайно зловредные пауки." }, { 12.70, "Они не только представляют опасность для жителей Мулгора, но и причиняют ущерб месту, которое большинство тауренов считает священным." }, { 23.75, "Мы были бы тебе очень благодарны, если бы ты отправился к Мрачной вершине и положил конец нашествию пауков." }, { 32.71, "Если сделаешь это, то наверняка заслужишь благосклонность предков." } }, f = { { 0.00, "В месте под названием Мрачная вершина к северо-западу от этого лагеря есть древнее тауренское кладбище." }, { 8.39, "Недавно там завелись чрезвычайно зловредные пауки." }, { 12.51, "Они не только представляют опасность для жителей Мулгора, но и причиняют ущерб месту, которое большинство тауренов считает священным." }, { 23.41, "Мы были бы тебе очень благодарны, если бы ты отправилась к Мрачной вершине и положила конец нашествию пауков." }, { 32.39, "Если сделаешь это, то наверняка заслужишь благосклонность предков." } } }, t = { d = 15.9, v = "tauren-male", n = { x = 153 }, c = { x = { { 0.00, "Благодарю тебя за службу жителям этих земель." }, { 4.02, "Нам может понадобиться время, чтобы полностью очистить это место, но твои усилия дали нам надёжную опору в борьбе с этими мерзкими тварями." } } } } },
    [96260] = { d = 36.3, g = 1, v = "tauren-male", n = { m = 370, f = 371 }, c = { m = { { 0.00, "Ты слышал, что случилось с местами захоронения на Мрачной вершине?" }, { 5.49, "Там все заполонили пауки, чей яд настолько силён, что может пробуждать мёртвых." }, { 11.88, "Разве не кошмар?" }, { 13.31, "Один из разведчиков, которых отправили осмотреть те места, вернулся полумёртвым и покрытым необычайно прочной кристаллической паутиной." }, { 24.44, "Я собрал всё, что смог, но буду благодарен за дополнительные образцы этой паутины для дальнейших исследований." }, { 33.47, "Принеси их мне, и я тебя вознагражу." } }, f = { { 0.00, "Ты слышала, что случилось с местами захоронения на Мрачной вершине?" }, { 5.43, "Там все заполонили пауки, чей яд настолько силён, что может пробуждать мёртвых." }, { 11.67, "Разве не кошмар?" }, { 13.07, "Один из разведчиков, которых отправили осмотреть те места, вернулся полумёртвым и покрытым необычайно прочной кристаллической паутиной." }, { 23.93, "Я собрал всё, что смог, но буду благодарен за дополнительные образцы этой паутины для дальнейших исследований." }, { 32.74, "Принеси их мне, и я тебя вознагражу." } } }, t = { d = 22.4, g = 1, v = "tauren-male", n = { x = 193 }, c = { m = { { 0.00, "Отличные образцы, их более чем достаточно для моих нужд." }, { 5.12, "Вот, возьми." }, { 6.28, "Из той небольшой частицы паутины, что у меня уже была, я сплёл ткань и сделал довольно необычный плащ." }, { 15.54, "Надеюсь, он пригодится тебе в странствиях." }, { 19.42, "Да хранит тебя Мать-Земля, герой." } }, f = { { 0.00, "Отличные образцы, их более чем достаточно для моих нужд." }, { 4.92, "Вот, возьми." }, { 6.04, "Из той небольшой частицы паутины, что у меня уже была, я сплёл ткань и сделал довольно необычный плащ." }, { 14.93, "Надеюсь, он пригодится тебе в странствиях." }, { 18.66, "Да хранит тебя Мать-Земля, героиня." } } } } },
    [96261] = { d = 35.0, g = 1, v = "tauren-male", n = { m = 355, f = 355 }, c = { m = { { 0.00, "При нашествиях, вроде того, что сейчас происходит на Мрачной вершине, причиной быстрого распространения агрессивных пауков часто становится единственная сильная матка." }, { 13.64, "Если хотим избавиться от этих тварей навсегда, нужно разыскать эту паучиху и прикончить." }, { 21.02, "Когда отправишься к Мрачной вершине, разыщи там мать выводка и уничтожь её." }, { 27.14, "Я советую взять с собой союзников и быть готовым ко всему." }, { 31.86, "Это, похоже, вовсе не обычные пауки." } }, f = { { 0.00, "При нашествиях, вроде того, что сейчас происходит на Мрачной вершине, причиной быстрого распространения агрессивных пауков часто становится единственная сильная матка." }, { 13.74, "Если хотим избавиться от этих тварей навсегда, нужно разыскать эту паучиху и прикончить." }, { 21.16, "Когда отправишься к Мрачной вершине, разыщи там мать выводка и уничтожь её." }, { 27.32, "Я советую взять с собой союзников и быть готовой ко всему." }, { 32.08, "Это, похоже, вовсе не обычные пауки." } } }, t = { d = 23.2, g = 1, v = "tauren-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Оживлённые мертвецы?" }, { 1.87, "Мать выводка в облике ночной эльфийки?" }, { 5.53, "Тревожные открытия." }, { 7.40, "Остаётся только гадать, что всё это значит..." }, { 11.66, "Думаю, об этом стоит беспокоиться позже." }, { 15.57, "Спасибо тебе." }, { 16.93, "Ты оказал Служителям Земли и жителям Мулгора огромную услугу." } }, f = { { 0.00, "Оживлённые мертвецы?" }, { 1.90, "Мать выводка в облике ночной эльфийки?" }, { 5.63, "Тревожные открытия." }, { 7.53, "Остаётся только гадать, что всё это значит..." }, { 11.86, "Думаю, об этом стоит беспокоиться позже." }, { 15.84, "Спасибо тебе." }, { 17.23, "Ты оказала Служителям Земли и жителям Мулгора огромную услугу." } } } } },
    [96264] = { d = 37.0, g = 1, v = "dwarf-male", n = { m = 415, f = 416 }, c = { m = { { 0.00, "Ты, значит, могучий шаман, да?" }, { 2.22, "Обучился обращению со стихиями и хочешь применить эти знания?" }, { 6.72, "Могу дать один совет." }, { 8.35, "Если хочешь, чтобы стихии тебя уважали, всегда возвращай долги." }, { 13.11, "Они помогают тебе – ты помогаешь им." }, { 15.78, "И как раз сейчас им очень нужна помощь в борьбе против тех, кто хочет использовать своё могущество во зло." }, { 23.35, "Земля дрожит." }, { 24.39, "Она говорит, что свинобразы собираются для проведения какого-то ритуала невероятной силы." }, { 30.84, "Надо исследовать их лабиринт и выяснить, что они задумали." }, { 35.08, "Принеси мне всё, что найдёшь." } }, f = { { 0.00, "Ты, значит, могучий шаман, да?" }, { 2.21, "Обучилась обращению со стихиями и хочешь применить эти знания?" }, { 6.77, "Могу дать один совет." }, { 8.40, "Если хочешь, чтобы стихии тебя уважали, всегда возвращай долги." }, { 13.15, "Они помогают тебе – ты помогаешь им." }, { 15.82, "И как раз сейчас им очень нужна помощь в борьбе против тех, кто хочет использовать своё могущество во зло." }, { 23.37, "Земля дрожит." }, { 24.41, "Она говорит, что свинобразы собираются для проведения какого-то ритуала невероятной силы." }, { 30.86, "Надо исследовать их лабиринт и выяснить, что они задумали." }, { 35.09, "Принеси мне всё, что найдёшь." } } }, t = { d = 18.4, g = 1, v = "dwarf-male", n = { m = 197, f = 197 }, c = { m = { { 0.00, "Любопытно." }, { 0.82, "Свинобразы задумали затопить Тысячу Игл, а?" }, { 4.11, "Эти никчёмные твари никогда не уважали стихии." }, { 7.68, "Такое надругательство, неудивительно, что мы чуем его даже отсюда." }, { 12.75, "Ты молодец, что нашёл, откуда идёт угроза, но теперь с ней надо покончить." } }, f = { { 0.00, "Любопытно." }, { 0.83, "Свинобразы задумали затопить Тысячу Игл, а?" }, { 4.15, "Эти никчёмные твари никогда не уважали стихии." }, { 7.75, "Такое надругательство, неудивительно, что мы чуем его даже отсюда." }, { 12.87, "Ты молодец, что нашла, откуда идёт угроза, но теперь с ней надо покончить." } } } } },
    [96294] = { d = 24.7, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Убитая тобой мать выводка вовсе не паук, а друид ночных эльфов, принявший искажённый звериный облик." }, { 8.39, "В голове роятся вопросы о природе - и цели - пауков Мрачной вершины." }, { 14.16, "Из складок одежды мёртвого эльфа выглядывает записка." }, { 18.58, "Возможно, этот документ ответит на некоторые вопросы, которые тебя мучают." } } }, t = { d = 30.8, v = "tauren-male", n = { x = 287 }, c = { x = { { 0.00, "Это... крайне тревожно." }, { 2.08, "Зачем друиду понадобился выводок опасных пауков?" }, { 6.31, "Кто или что такое этот «Дикий Король» и «Пакт», о которых говорится в письме?" }, { 12.94, "Я посоветуюсь с друидами Круга Кенария." }, { 16.33, "Возможно, они знают больше." }, { 18.79, "Ещё раз спасибо за помощь." }, { 21.02, "Как бы ни тревожили эти сведения, нам будет спокойнее, зная, что тот, кто управлял этими мерзкими тварями, уничтожен." } } } } },
    [96332] = { d = 29.0, v = "orc-female", n = { x = 304 }, c = { x = { { 0.00, "Когда мы отступали, к крепости подходила вторая волна наг." }, { 4.46, "Подозреваю, что внутри всё ещё идёт бой." }, { 7.41, "Мы, Кор'крон, платим кровью за кровь." }, { 10.23, "Раз уж ты всё равно идёшь туда, убивай всех наг, что попадутся." }, { 14.90, "Я видела среди них ещё и колдунью — бьюсь об заклад, она у них главная." }, { 20.25, "Принеси мне её голову." }, { 21.97, "Сегодня мы потеряли много хороших орков, и я не успокоюсь, пока мы не вернём им должок сполна." } } } },
    [96334] = { d = 30.4, v = "orc-female", n = { x = 340 }, c = { x = { { 0.00, "Почти все люди, с которыми мы сражались, носили кроваво-красные повязки." }, { 5.34, "Помнится, доходили до меня слухи о преступной шайке в Восточных королевствах, что зовётся «Братство Справедливости», — их узнают по красным маскам." }, { 15.97, "Что они делают здесь, в Калимдоре, не знаю, но убивай всех, кто встанет у тебя на пути, и отнеси их маски Эйтриггу в Оргриммар." }, { 25.20, "Он сможет определить, действительно ли это маски Братства Справедливости." } } } },
    [96335] = { d = 27.5, g = 1, v = "human-male", n = { m = 289, f = 290 }, c = { m = { { 0.00, "Ух ты!" }, { 0.47, "Вот это было впечатляюще." }, { 2.40, "Как ты расправился с этим драконом — просто загляденье!" }, { 6.46, "Раз уж ты здесь... может, поможешь мне избавиться от этих цепей с гирей?" }, { 11.72, "Если он ещё не сбежал и его не убили, ключи от этих кандалов должны быть у палача, которого тут зовут Дознавателем." }, { 20.25, "Забери ключ у этого садиста и принеси мне." }, { 23.38, "Обещаю, если сделаешь это, я в долгу не останусь." } }, f = { { 0.00, "Ух ты!" }, { 0.47, "Вот это было впечатляюще." }, { 2.40, "Как ты расправилась с этим драконом — просто загляденье!" }, { 6.97, "Раз уж ты здесь... может, поможешь мне избавиться от этих цепей с гирей?" }, { 12.23, "Если он ещё не сбежал и его не убили, ключи от этих кандалов должны быть у палача, которого тут зовут Дознавателем." }, { 20.76, "Забери ключ у этого садиста и принеси мне." }, { 23.89, "Обещаю, если сделаешь это, я в долгу не останусь." } } } },
    [96337] = { d = 25.9, v = "human-male", n = { x = 269 }, c = { x = { { 0.00, "Я же говорил, что не останусь в долгу, если ты меня освободишь." }, { 4.67, "Золота у меня для тебя нет, но есть кое-что получше." }, { 8.53, "Возьми это." }, { 9.47, "Оно поможет тебе найти сокровище дороже золота." }, { 13.13, "Делай с ним что хочешь, но если кто спросит, откуда оно у тебя, скажи, что человек, который тебе его дал, погиб." }, { 21.53, "Скажи, что его испепелило драконье пламя... и унесло в море." } } } },
    [96369] = { d = 20.3, g = 1, v = "narrator", n = { m = 0, f = 0 }, c = { m = { { 0.00, "Король мёртв — убит при попытке побега незадолго до нападения наг." }, { 5.00, "Многие воины Кор'крона погибли, чтобы это узнать, но эта весть может потрясти Альянс до основания." }, { 12.61, "Нужно как можно скорее вернуться к командиру Фолкару и рассказать ему обо всём, что ты узнал." } }, f = { { 0.00, "Король мёртв — убит при попытке побега незадолго до нападения наг." }, { 5.00, "Многие воины Кор'крона погибли, чтобы это узнать, но эта весть может потрясти Альянс до основания." }, { 12.61, "Нужно как можно скорее вернуться к командиру Фолкару и рассказать ему обо всём, что ты узнала." } } } },
    [96376] = { d = 13.5, g = 1, v = "narrator", n = { m = 0, f = 0 }, c = { m = { { 0.00, "Тебе приходит в голову, что Назгрела, советника вождя, могут очень заинтересовать документы, которые ты добыл в Западном крае." }, { 9.26, "Спроси его, понятно ли ему что-нибудь в этих бумагах." } }, f = { { 0.00, "Тебе приходит в голову, что Назгрела, советника вождя, могут очень заинтересовать документы, которые ты добыла в Западном крае." }, { 9.56, "Спроси его, понятно ли ему что-нибудь в этих бумагах." } } } },
    [96377] = { d = 12.8, g = 1, v = "narrator", n = { m = 0, f = 0 }, c = { m = { { 0.00, "Тебе приходит в голову, что гоблина — правую руку Шоу — могут заинтересовать документы, которые ты добыл в Западном крае." }, { 8.88, "Спроси его, понятно ли ему что-нибудь в этих бумагах." } }, f = { { 0.00, "Тебе приходит в голову, что гоблина — правую руку Шоу — могут заинтересовать документы, которые ты добыла в Западном крае." }, { 8.96, "Спроси его, понятно ли ему что-нибудь в этих бумагах." } } } },
    [96379] = { d = 18.5, g = 1, v = "narrator", n = { m = 0, f = 0 }, c = { m = { { 0.00, "Тебе приходит в голову, что гоблина, который занимается возвратом ценностей, могут очень заинтересовать документы, которые ты добыл в Западном крае." }, { 10.90, "Спроси его, понятно ли ему что-нибудь в этих бумагах... и, что важнее, сколько он готов за них заплатить." } }, f = { { 0.00, "Тебе приходит в голову, что гоблина, который занимается возвратом ценностей, могут очень заинтересовать документы, которые ты добыла в Западном крае." }, { 10.84, "Спроси его, понятно ли ему что-нибудь в этих бумагах... и, что важнее, сколько он готов за них заплатить." } } } },
    [96381] = { d = 29.9, g = 1, v = "dwarf-male", n = { m = 308, f = 309 }, c = { m = { { 0.00, "Пока ты подслушивал леди Праудмур, моя верная подзорная труба глядела на берег Алькаца." }, { 6.76, "Похоже, на остров напали." }, { 8.74, "Там наги — целая толпа, так и лезли на берег." }, { 12.22, "Враг моего врага — мне друг, но только не когда речь о нагах." }, { 16.80, "Так что окажем миру услугу и проредим их ряды." }, { 20.35, "А ещё в трубу было видно, похоже, их предводительницу — какую-то колдунью, что раздавала приказы." }, { 27.65, "Её тоже убери, если сможешь." } }, f = { { 0.00, "Пока ты подслушивала леди Праудмур, моя верная подзорная труба глядела на берег Алькаца." }, { 6.88, "Похоже, на остров напали." }, { 8.86, "Там наги — целая толпа, так и лезли на берег." }, { 12.34, "Враг моего врага — мне друг, но только не когда речь о нагах." }, { 16.92, "Так что окажем миру услугу и проредим их ряды." }, { 20.47, "А ещё в трубу было видно, похоже, их предводительницу — какую-то колдунью, что раздавала приказы." }, { 27.77, "Её тоже убери, если сможешь." } } } },
    [96390] = { d = 18.4, v = "dwarf-male", n = { x = 213 }, c = { x = { { 0.00, "В Дун Морог проникли шпионы из клана Чёрного Железа." }, { 3.79, "Что они замышляют, я пока не знаю, но проблемы такого рода нужно решать незамедлительно." }, { 10.25, "Отправляйся на восток в мастерскую Сталекрута и убей всех шпионов из клана Чёрного Железа, которых там повстречаешь." } } }, t = { d = 19.9, v = "dwarf-male", n = { x = 231 }, c = { x = { { 0.00, "Дворфы Чёрного Железа – наши дальние родственники, но уж точно не члены семьи." }, { 5.54, "Если тех из них, кто забрёл слишком далеко от этой их проклятой горы, постигнут какие-нибудь несчастья, то слёз я проливать не стану." }, { 14.78, "Надеюсь, так у них пропадёт желание и дальше совершать набеги на эти земли." } } } } },
    [96391] = { d = 36.2, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "На карте в ваших руках изображена сложная сеть подземных туннелей и проходов, кажется, сходящихся в одной точке прямо под Стальгорном." }, { 10.50, "Что именно означают начертанные здесь руны, вы сказать не можете, так как всё написано на уродливом языке дворфов Чёрного Железа, но у вас есть определённые догадки о том, зачем всё это нужно." }, { 25.25, "Рассматривая карту, вы вдруг чувствуете порыв ветра, который доносит до вас тихий дворфийский голос." }, { 33.12, "Надо показать карту Землевидцу Фарсену." } } }, t = { d = 18.1, g = 1, v = "dwarf-male", n = { m = 225, f = 226 }, c = { m = { { 0.00, "Судя по этой карте, дворфы Чёрного Железа, похоже, планируют вторжение в склепы под Стальгорном." }, { 6.36, "Отряд, который ты разгромил на востоке, должно быть, проводил разведку." }, { 11.06, "Спасибо тебе за сведения." }, { 12.79, "Если поторопимся, мы, возможно, достигнем их цели в подземелье раньше противника." } }, f = { { 0.00, "Судя по этой карте, дворфы Чёрного Железа, похоже, планируют вторжение в склепы под Стальгорном." }, { 6.29, "Отряд, который ты разгромила на востоке, должно быть, проводил разведку." }, { 10.99, "Спасибо тебе за сведения." }, { 12.69, "Если поторопимся, мы, возможно, достигнем их цели в подземелье раньше противника." } } } } },
    [96392] = { d = 22.3, v = "dwarf-male", n = { x = 235 }, c = { x = { { 0.00, "Приветствую тебя!" }, { 1.37, "Моё имя Землевидец Фарсен, я прибыл в Дун Морог с Заоблачного пика." }, { 6.49, "В дороге я никак не мог избавиться от ощущения, что у нас... эгм... есть некоторые проблемы с дворфами из клана Чёрного Железа." }, { 15.84, "Если у тебя найдётся минутка, я разъясню, о чём толкую." }, { 20.01, "Немного магии, и ты всё увидишь." } } }, t = { d = 11.3, g = 1, v = "dwarf-male", n = { m = 109, f = 110 }, c = { m = { { 0.00, "Ну что, видишь, герой?" }, { 1.74, "Снуют, как тараканы, и это только те, которых нам видно на поверхности." }, { 7.22, "Ты парень крепкий." }, { 8.68, "Не желаешь немного посражаться?" } }, f = { { 0.00, "Ну что, видишь, героиня?" }, { 1.89, "Снуют, как тараканы, и это только те, которых нам видно на поверхности." }, { 7.43, "Ты девушка крепкая." }, { 8.98, "Не желаешь немного посражаться?" } } } } },
    [96393] = { d = 28.5, v = "dwarf-male", n = { x = 318 }, c = { x = { { 0.00, "Собери союзников и вместе спуститесь в пещеры под Старым Стальгорном." }, { 5.07, "Там войдите в Чертоги танов и пробивайтесь к нижним склепам." }, { 9.48, "Язык Чёрного Железа я знаю неважно, но одно имя разобрать смог – Дарген Сокрушающий Молот." }, { 16.12, "Скорее всего, там он за главного." }, { 18.56, "Сними его голову с плеч и принеси королю Магни Бронзобороду." }, { 23.03, "А, и передай заодно, что его старый друг Фарсен желает ему доброго здравия!" } } }, t = { d = 40.6, g = 1, v = "dwarf-male#177", n = { x = 397 }, c = { m = { { 0.00, "Вторжение клана Чёрного Железа прямо у нас под ногами?" }, { 4.36, "Что ж, радует то, что командира захватчиков удалось устранить." }, { 9.31, "Стражники теперь разберутся с их недобитками." }, { 12.95, "Мы заделаем ходы и укрепим нижние уровни, чтобы пресечь новые вторжения." }, { 18.91, "Спасибо тебе за помощь Стальгорну, герой." }, { 22.33, "Прими этот небольшой дар в знак моей благодарности." }, { 26.47, "Кстати, если снова встретишь этого старого почитателя камней Фарсена из клана Громового Молота, то скажи ему, чтобы заглянул ко мне с визитом как полагается." } }, f = { { 0.00, "Вторжение клана Чёрного Железа прямо у нас под ногами?" }, { 4.51, "Что ж, радует то, что командира захватчиков удалось устранить." }, { 9.62, "Стражники теперь разберутся с их недобитками." }, { 13.37, "Мы заделаем ходы и укрепим нижние уровни, чтобы пресечь новые вторжения." }, { 19.53, "Спасибо тебе за помощь Стальгорну, героиня." }, { 23.21, "Прими этот небольшой дар в знак моей благодарности." }, { 27.49, "Кстати, если снова встретишь этого старого почитателя камней Фарсена из клана Громового Молота, то скажи ему, чтобы заглянул ко мне с визитом как полагается." } } } } },
    [96394] = { d = 23.4, v = "dwarf-female", n = { x = 252 }, c = { x = { { 0.00, "Могилы в Чертогах танов чем-то потревожены... какие-то странные звуки доносятся из самых глубин склепов." }, { 7.93, "Духи мёртвых спят чутко, и, вероятно, там произошло нечто, что испугало их." }, { 13.48, "Отправляйся туда и посмотри, что можно сделать." }, { 17.07, "Если какие-то мертвецы и вправду пробудились – что ж, придётся тебе упокоить их снова!" } } }, t = { d = 13.8, v = "dwarf-female", n = { x = 156 }, c = { x = { { 0.00, "А, дело уже сделано?" }, { 1.55, "Вот и славно." }, { 2.53, "Нельзя же допустить, чтобы хранители отказывались входить в зал и выполнять свои обязанности из-за каких-то там \"призраков\" и \"разгневанных мертвецов\", не так ли?" } } } } },
    [96395] = { d = 13.4, v = "dwarf-male", n = { x = 77 }, c = { x = { { 0.00, "Тан..." }, { 0.65, "Великий..." }, { 1.76, "Тан... хочет... покоя." }, { 4.08, "Молю... помоги ему... обрести... покой..." }, { 8.43, "Его гложет... древняя... злоба..." }, { 11.96, "Нет... покоя..." } } }, t = { d = 9.8, v = "dwarf-male", n = { x = 43 }, c = { x = { { 0.00, "Мой... тан... он... упокоился... да... покой." }, { 5.31, "Спа... сибо..." }, { 7.08, "Я... обрету... покой..." } } } } },
    [96403] = { d = 27.8, g = 1, v = "gnome-male", n = { m = 303, f = 307 }, c = { m = { { 0.00, "Эй, искатель приключений!.." }, { 1.86, "Мне очень нужна твоя помощь." }, { 3.91, "Едва я успел сюда проникну... то есть начать патрулирование, как на буровых машинах приехали дворфы Чёрного Железа!" }, { 11.81, "Не знаю, зачем они тут, но на кону бесценная добыча... вернее, \"важные культурные ценности\"!" }, { 18.21, "Прошу, принеси мне все реликвии, которые тебе попадутся." }, { 22.12, "Уверяю, мы всё внесём в каталог и поместим на почётное место." } }, f = { { 0.00, "Эй, искательница приключений!.." }, { 2.23, "Мне очень нужна твоя помощь." }, { 4.39, "Едва я успел сюда проникну... то есть начать патрулирование, как на буровых машинах приехали дворфы Чёрного Железа!" }, { 12.71, "Не знаю, зачем они тут, но на кону бесценная добыча... вернее, \"важные культурные ценности\"!" }, { 19.46, "Прошу, принеси мне все реликвии, которые тебе попадутся." }, { 23.58, "Уверяю, мы всё внесём в каталог и поместим на почётное место." } } }, t = { d = 22.1, g = 1, v = "gnome-male", n = { m = 241, f = 242 }, c = { m = { { 0.00, "Вы только поглядите, какая храбрость и предприимчивость!" }, { 4.11, "Я дал слово гнома, и ты свою награду честно заслужил!" }, { 8.09, "Теперь позволь-ка мне взглянуть на добычу... э-э... то есть на найденные реликвии." }, { 14.07, "Мне нужно начать их оценивать... прости, \"каталогизировать\", чтобы как можно быстрее вернуть на законные места." } }, f = { { 0.00, "Вы только поглядите, какая храбрость и предприимчивость!" }, { 4.07, "Я дал слово гнома, и ты свою награду честно заслужила!" }, { 8.08, "Теперь позволь-ка мне взглянуть на добычу... э-э... то есть на найденные реликвии." }, { 13.99, "Мне нужно начать их оценивать... прости, \"каталогизировать\", чтобы как можно быстрее вернуть на законные места." } } } } },
    [96408] = { d = 24.7, g = 1, v = "dwarf-male", n = { m = 265, f = 266 }, c = { m = { { 0.00, "Вчера вечером один из наших горных пехотинцев заметил костёр на восточном склоне холма." }, { 6.49, "Кажется, довольно высоко – оттуда виден весь карьер Гол'Болар." }, { 11.13, "Вероятно, сильно переживать не стоит, но мне хотелось бы, чтобы ты разведал тот лагерь." }, { 17.48, "Если его обитатели дружелюбны, то ничего страшного." }, { 21.33, "Если же нет..." }, { 22.39, "Ну, ты знаешь, что делать." } }, f = { { 0.00, "Вчера вечером один из наших горных пехотинцев заметил костёр на восточном склоне холма." }, { 6.23, "Кажется, довольно высоко – оттуда виден весь карьер Гол'Болар." }, { 11.52, "Вероятно, сильно переживать не стоит, но мне хотелось бы, чтобы ты разведала тот лагерь." }, { 17.97, "Если его обитатели дружелюбны, то ничего страшного." }, { 21.82, "Если же нет..." }, { 22.89, "Ну, ты знаешь, что делать." } } }, t = { d = 2.3, v = "dwarf-male", n = { x = 23 }, c = { x = { { 0.00, "Приветствую тебя!" }, { 1.60, "Как жизнь?" } } } } },
    [96438] = { d = 29.7, v = "human-female", n = { x = 337 }, c = { x = { { 0.00, "Мне нужна твоя помощь." }, { 1.67, "Один из членов нашего братства был проездом на Высоте Найджела в Пустошах и услышал о битве, состоявшейся на поле Маннорок." }, { 10.48, "Говорят, что одна из сторон обрушила на своих врагов-чернокнижников могучую светлую магию." }, { 16.97, "Значит, в битве точно участвовали воители Света." }, { 20.50, "Я хочу узнать больше об участниках этого сражения." }, { 24.17, "Если кто-то из наших сражался там или даже погиб..." }, { 27.96, "Я бы хотела об этом знать." } } } },
    [96449] = { d = 32.3, g = 1, v = "human-male", n = { m = 375, f = 377 }, c = { m = { { 0.00, "Если подумать, я знаю одно укромное местечко далеко на юге отсюда." }, { 4.62, "Кто-то мне говорил, что оно называется Высадка Ньюмена, только не спрашивай меня, кто такой этот «Ньюмен»." }, { 11.84, "Начни поиски старины Эонаса оттуда." }, { 14.33, "Можешь взять мою старую шлюпку — она пришвартована вон там, сразу за самым северным причалом." }, { 20.65, "Посудина так себе, но доберёшься на ней быстрее, чем вплавь." }, { 24.54, "Надеюсь, с ним ничего не стряслось." }, { 26.90, "Мне было бы спокойнее, если бы ты сплавал и проверил, как там наш друг." } }, f = { { 0.00, "Если подумать, я знаю одно укромное местечко далеко на юге отсюда." }, { 4.62, "Кто-то мне говорил, что оно называется Высадка Ньюмена, только не спрашивай меня, кто такой этот «Ньюмен»." }, { 11.84, "Начни поиски старины Эонаса оттуда." }, { 14.33, "Можешь взять мою старую шлюпку — она пришвартована вон там, сразу за самым северным причалом." }, { 20.65, "Посудина так себе, но доберёшься на ней быстрее, чем вплавь." }, { 24.54, "Надеюсь, с ним ничего не стряслось." }, { 26.90, "Мне было бы спокойнее, если бы ты сплавала и проверила, как там наш друг." } } } },
    [96476] = { d = 13.4, v = "human-female", n = { x = 153 }, c = { x = { { 0.00, "Эонас что-то говорил об Осквернённом лесе, так что, возможно, он там." }, { 4.85, "В южной части леса есть небольшое поселение — Изумрудное святилище." }, { 9.69, "Советую поспрашивать там, не видел ли его кто-нибудь." } } } },
    [96603] = { d = 33.0, v = "human-female", n = { x = 413 }, c = { x = { { 0.00, "Верховный маг Ронин сейчас в отъезде — он расследует возмущение в потоках магии по всему Азероту." }, { 6.50, "Верховный маг поручил мне искать помощи у сильных искателей приключений вроде тебя, чтобы собрать для него важные сведения с мест." }, { 15.24, "Возьми эту чародейскую кадильницу." }, { 17.58, "Пока на тебе действует её магия, ты сможешь извлекать частицы нестабильной магии из самых искусных заклинателей и других необычайно могущественных существ, которых встретишь." }, { 29.21, "Принеси мне эти частицы, и Кирин-Тор будет у тебя в долгу." } } } },
