    [96609] = { d = 37.8, g = 1, v = "narrator", n = { m = 401, f = 402 }, c = { m = { { 0.00, "Ты знаком с мерцающим луносветским вином?" }, { 3.18, "У него очень мягкий вкус, характерный только для виноградников Луносвета, и это единственная вещь из моих родных земель, по которой я действительно скучаю." }, { 15.00, "К сожалению, по эту сторону Талассийских врат достать это вино очень сложно." }, { 20.94, "Один посетитель как-то принёс мне бутылку, которую, по его словам, он \"изъял\" у эльфов крови на севере Азшары." }, { 29.44, "Если странствия приведут тебя туда и ты сможешь добыть мне ещё несколько бутылок, я щедро тебя вознагражу." } }, f = { { 0.00, "Ты знакома с мерцающим луносветским вином?" }, { 3.41, "У него очень мягкий вкус, характерный только для виноградников Луносвета, и это единственная вещь из моих родных земель, по которой я действительно скучаю." }, { 15.23, "К сожалению, по эту сторону Талассийских врат достать это вино очень сложно." }, { 21.17, "Один посетитель как-то принёс мне бутылку, которую, по его словам, он \"изъял\" у эльфов крови на севере Азшары." }, { 29.67, "Если странствия приведут тебя туда и ты сможешь добыть мне ещё несколько бутылок, я щедро тебя вознагражу." } } } },
    [96622] = { d = 35.2, g = 1, v = "orc-male", n = { m = 316, f = 318 }, c = { m = { { 0.00, "Пока ты здесь, друг, у меня к тебе последняя просьба." }, { 4.33, "Не мог бы ты отнести припарку, которую я приготовил, двум моим товарищам здесь, в лагере?" }, { 11.46, "Энхо лежит в нашем лазарете, слева." }, { 14.47, "Он очень слаб, но я всё ещё надеюсь, что он одолеет заразу." }, { 19.17, "Я кормлю его бульоном с ложечки, чтобы он набрался сил." }, { 23.72, "Вторая — Маруке." }, { 25.04, "*Ортак на мгновение молча опускает голову.*" }, { 28.48, "Ты найдёшь её к северу отсюда, там, где мы держим немногих оставшихся у нас ездовых животных." } }, f = { { 0.00, "Пока ты здесь, друг, у меня к тебе последняя просьба." }, { 4.33, "Не могла бы ты отнести припарку, которую я приготовил, двум моим товарищам здесь, в лагере?" }, { 11.81, "Энхо лежит в нашем лазарете, слева." }, { 14.82, "Он очень слаб, но я всё ещё надеюсь, что он одолеет заразу." }, { 19.52, "Я кормлю его бульоном с ложечки, чтобы он набрался сил." }, { 24.07, "Вторая — Маруке." }, { 25.39, "*Ортак на мгновение молча опускает голову.*" }, { 28.83, "Ты найдёшь её к северу отсюда, там, где мы держим немногих оставшихся у нас ездовых животных." } } } },
    [96626] = { d = 17.8, g = 1, v = "human-male", n = { x = 202 }, c = { m = { { 0.00, "Значит, хочешь узнать побольше о походной жизни?" }, { 3.53, "Это правильно, герой." }, { 5.14, "Для любого искателя приключений первое дело – стать поваром и научиться разводить костёр." }, { 11.43, "Кулинария – не просто способ приготовить что-нибудь вкусное, а основа основ походной жизни." } }, f = { { 0.00, "Значит, хочешь узнать побольше о походной жизни?" }, { 3.44, "Это правильно, героиня." }, { 5.14, "Для любого искателя приключений первое дело – стать поваром и научиться разводить костёр." }, { 11.27, "Кулинария – не просто способ приготовить что-нибудь вкусное, а основа основ походной жизни." } } }, t = { d = 23.2, g = 1, v = "human-male", n = { m = 292, f = 293 }, c = { m = { { 0.00, "С этим ты сможешь разбить лагерь где угодно." }, { 2.91, "Пока ты освоил только азы, так что особенно обставить лагерь не получится." }, { 7.73, "Учись – и со временем научишься разжигать огонь пожарче и делать разные интересные вещи." }, { 13.48, "Ещё ты можешь научиться создавать разные полезные вещи в лагере – поговори с другими наставниками профессий, в которых хоть немного разбираешься." } }, f = { { 0.00, "С этим ты сможешь разбить лагерь где угодно." }, { 2.91, "Пока ты освоила только азы, так что особенно обставить лагерь не получится." }, { 8.29, "Учись – и со временем научишься разжигать огонь пожарче и делать разные интересные вещи." }, { 14.04, "Ещё ты можешь научиться создавать разные полезные вещи в лагере – поговори с другими наставниками профессий, в которых хоть немного разбираешься." } } } } },
