    [96674] = { d = 39.2, g = 1, v = "child-male", n = { m = 301, f = 303 }, c = { m = { { 0.00, "*Глаза Мирта округляются, когда вы подходите.*" }, { 3.60, "Ого, а ты кто?" }, { 4.84, "Мама сказала, что тут появился кто-то новенький." }, { 9.01, "Она сказала, что ты убил кучу Плети и что ты ужасно сильный!" }, { 14.26, "А ты когда-нибудь дрался с медведем?" }, { 17.35, "С ДРАКОНОМ!?" }, { 19.05, "Я..." }, { 19.36, "*Мирт оглядывается, а потом смущается.*" }, { 22.80, "Может... ты мне поможешь?" }, { 24.62, "Я должен был присматривать за овцами, но они убежали, пока я лепил грязевых драконов." }, { 30.78, "Они вон на ТОЙ стороне." }, { 32.47, "Мне туда нельзя." }, { 33.70, "Мама говорит, там меня могут обидеть." }, { 36.49, "Сходишь за овечками?" } }, f = { { 0.00, "*Глаза Мирта округляются, когда вы подходите.*" }, { 3.60, "Ого, а ты кто?" }, { 4.84, "Мама сказала, что тут появился кто-то новенький." }, { 9.01, "Она сказала, что ты убила кучу Плети и что ты ужасно сильная!" }, { 14.74, "А ты когда-нибудь дралась с медведем?" }, { 18.67, "С ДРАКОНОМ!?" }, { 20.37, "Я..." }, { 20.68, "*Мирт оглядывается, а потом смущается.*" }, { 24.12, "Может... ты мне поможешь?" }, { 25.94, "Я должен был присматривать за овцами, но они убежали, пока я лепил грязевых драконов." }, { 32.10, "Они вон на ТОЙ стороне." }, { 33.79, "Мне туда нельзя." }, { 35.02, "Мама говорит, там меня могут обидеть." }, { 37.81, "Сходишь за овечками?" } } } },
    [96770] = { d = 22.4, g = 1, v = "bloodelf-male", n = { m = 230, f = 231 }, c = { m = { { 0.00, "Есть один тролль-знахарь по имени Зум'ра." }, { 3.10, "У меня с ним давние счёты, и я хочу, чтобы ты его убил." }, { 7.28, "Отправляйся в крепость Зул'Фаррак в пустынях Танариса." }, { 11.33, "Разыщи там Зум'ру, прикончи и принеси мне его голову – только смотри, чтобы она была в целости и сохранности!" }, { 19.63, "За это тебя достойно наградят." } }, f = { { 0.00, "Есть один тролль-знахарь по имени Зум'ра." }, { 3.10, "У меня с ним давние счёты, и я хочу, чтобы ты его убила." }, { 7.82, "Отправляйся в крепость Зул'Фаррак в пустынях Танариса." }, { 11.87, "Разыщи там Зум'ру, прикончи и принеси мне его голову – только смотри, чтобы она была в целости и сохранности!" }, { 20.17, "За это тебя достойно наградят." } } } },
    [96771] = { d = 35.8, v = "nightelf-male", n = { x = 393 }, c = { x = { { 0.00, "В области под названием Лесоречье, что к юго-востоку отсюда, есть такая крепость Крол'док." }, { 6.80, "Там был замечен высокорождённый по имени Залфан Тень Луны, а с ним и сектанты Сумеречного Молота." }, { 13.94, "Я могу щедро заплатить тебе, если ты сделаешь мне одолжение и избавишь наш мир от этого кретина." }, { 21.22, "Он позорит гордое имя Высокорождённых, якшаясь с фанатиками и делясь с ними запретными чародейскими знаниями." }, { 29.38, "Нас и без того осталось немного, чтобы черви вроде него ещё и пятнали нашу репутацию." } } } },
    [96772] = { d = 32.6, v = "bloodelf-male", n = { x = 385 }, c = { x = { { 0.00, "Мы с Времиаром наблюдали с помощью магического зрения за местностью в Калимдоре, что зовётся островом Алькац, и почти убедились, что там находится могущественная волшебница." }, { 11.85, "Ей удалось развеять наши поисковые чары, но прежде я успел уловить образ какого-то фолианта." }, { 18.41, "Думаю, это был дневник, написанный древним драконьим письмом." }, { 22.76, "Не знаю, что в этой книге, но я хотел бы её изучить." }, { 26.42, "Мы просим тебя отправиться в тайную тюрьму под островом Алькац и добыть для нас эту книгу." } } } },
    [96773] = { d = 29.7, v = "bloodelf-male", n = { x = 356 }, c = { x = { { 0.00, "Глубоко в логове иглогривов племени Мёртвой Головы, известном как курганы Иглошкурых, обосновался слуга Короля-лича." }, { 8.12, "Нам известно, что с помощью своего гадального шара – Ока Хладовея – он наблюдает за перемещениями своих прислужников и раздаёт им указания." }, { 17.68, "Отправляйся на курганы Иглошкурых и раздобудь для нас это Око Хладовея." }, { 22.65, "Кирин-Тор щедро заплатит за этот артефакт, чтобы исследовать его и глубже понять принцип его работы." } } } },
    [96774] = { d = 36.7, v = "troll-male", n = { x = 384 }, c = { x = { { 0.00, "Древние гурубаши из Тернистой долины, мон, были мастерами тёмной магии крови." }, { 6.07, "Говорят, они использовали идолы из чистого истинного серебра, чтобы направлять это скверное, скверное колдовство." }, { 15.04, "Старый Мазу'кон был бы рад заполучить один из таких идолов... для науки, понимаешь." }, { 21.54, "Может, соберёшь друзей и немного пограбишь тот затонувший город, торчащий из моря у берегов Тернистой долины?" }, { 30.09, "Убей самого внушительного жреца, какого найдёшь, – у него наверняка есть то, что я ищу." } } } },
    [96775] = { d = 32.4, v = "troll-male", n = { x = 332 }, c = { x = { { 0.00, "Старина Мазу'кон с давних пор на ножах с одним знахарем по имени Зум'ра." }, { 5.60, "Думаю, ты можешь помочь мне с этой проблемой." }, { 9.12, "Зум'ра практикует плохое вуду в Зул'Фарраке, городе племени Песчаной Бури, что лежит далеко на юг среди пустынь Танариса." }, { 18.52, "Ступай туда, убей Зум'ру и принеси мне его голову." }, { 22.53, "Уж поверь мне, в мире станет куда спокойнее, когда его голова будет торчать на копье у моей хижины, чем сидеть у него на плечах." } } } },
    [96776] = { d = 43.0, g = 1, v = "tauren-female#72", n = { x = 384 }, c = { m = { { 0.00, "Мне было видение." }, { 1.56, "В глубинах некоего места, известного как Мародон, за краем, где звучит песнь земли, есть палата, заполненная ослепительными белыми кристаллами, а охраняют её могучие великаны." }, { 16.49, "А на самом её верху находится кристалл несравненного совершенства." }, { 22.16, "Это аспект богини солнца, правое око Ан'ше, самой Матери-Земли." }, { 27.92, "Во сне я увидела его сияние, и оно манит меня." }, { 32.04, "Герой, забери оттуда Сияние Ан'ше и верни туда, где оно должно находиться по праву – под открытое небо Мулгора." } }, f = { { 0.00, "Мне было видение." }, { 1.56, "В глубинах некоего места, известного как Мародон, за краем, где звучит песнь земли, есть палата, заполненная ослепительными белыми кристаллами, а охраняют её могучие великаны." }, { 16.49, "А на самом её верху находится кристалл несравненного совершенства." }, { 22.16, "Это аспект богини солнца, правое око Ан'ше, самой Матери-Земли." }, { 27.92, "Во сне я увидела его сияние, и оно манит меня." }, { 32.04, "Героиня, забери оттуда Сияние Ан'ше и верни туда, где оно должно находиться по праву – под открытое небо Мулгора." } } } },
    [96779] = { d = 27.5, g = 1, v = "bloodelf-male", n = { x = 307 }, c = { m = { { 0.00, "Иногда, путник, одного удара в нужное место хватает, чтобы враг упал замертво." }, { 5.81, "С организациями зачастую то же самое." }, { 8.48, "Наши агенты определили ключевую цель в рядах Синдиката: человека по имени лорд Томас." }, { 14.68, "Он играет важную роль в делах крепости Дарнхольд в предгорьях Хилсбрада." }, { 19.90, "Если хочешь послужить Чёрному Ворону, отправляйся в Дарнхольд и устрани его." }, { 25.45, "Чем быстрее и тише, тем лучше." } }, f = { { 0.00, "Иногда, путница, одного удара в нужное место хватает, чтобы враг упал замертво." }, { 5.86, "С организациями зачастую то же самое." }, { 8.53, "Наши агенты определили ключевую цель в рядах Синдиката: человека по имени лорд Томас." }, { 14.71, "Он играет важную роль в делах крепости Дарнхольд в предгорьях Хилсбрада." }, { 19.92, "Если хочешь послужить Чёрному Ворону, отправляйся в Дарнхольд и устрани его." }, { 25.45, "Чем быстрее и тише, тем лучше." } } }, t = { d = 13.0, v = "bloodelf-male", n = { x = 151 }, c = { x = { { 0.00, "Без Томаса в крепости Дарнхольд наверняка начнётся разброд." }, { 4.30, "Жалкие головорезы вроде синдикатовских без главаря быстро разбегаются." }, { 9.46, "Хорошая работа." }, { 10.65, "Возможно, я ещё обращусь к тебе." } } } } },
    [96781] = { d = 30.5, v = "bloodelf-male", n = { x = 364 }, c = { x = { { 0.00, "Мы заметили, что отряд разведчиков Синдиката рыщет среди руин Альтерака." }, { 4.87, "Возглавляет его человек по имени Бартон." }, { 7.64, "Они явно что-то ищут, но я не могу узнать, что именно, не прочитав его донесения." }, { 13.17, "Прошу тебя вытащить отчёт у него из кармана, а не убивать его сразу." }, { 17.81, "Смерть Бартона даст Синдикату понять, что мы напали на их след, и они наверняка примут меры, чтобы замести следы." }, { 25.33, "Если хочешь найти его, он, скорее всего, среди бойцов Синдиката в Странбраде." } } } },
    [96782] = { d = 30.4, v = "bloodelf-male", n = { x = 347 }, c = { x = { { 0.00, "Похоже, наш друг Бартон упростил нам задачу." }, { 3.16, "Он разыскивает в руинах Альтерака два предмета, принадлежавшие дому Перенольдов." }, { 8.83, "Один – это меч, клинок дома Перенольдов, второй – щит, королевская эгида дома Перенольдов." }, { 15.34, "Судя по донесению, они хранятся в двух башнях среди руин." }, { 19.53, "Нам надо добыть эти предметы раньше Синдиката." }, { 22.94, "Живущие в руинах огры беспощадны, но я считаю, что ты сможешь прокрасться мимо них, не обагряя свой клинок." } } } },
    [96783] = { d = 29.2, v = "bloodelf-male", n = { x = 363 }, c = { x = { { 0.00, "Крепость Стромгард - одна из крупнейших цитаделей Синдиката." }, { 4.06, "За её стенами заключается множество важнейших сделок организации." }, { 8.43, "До меня дошли слухи об одной сделке между членами Синдиката где-то в Нагорье Арати, и я уверен, что подробности можно найти где-то в Стромгарде." }, { 18.25, "Чтобы проникнуть в крепость, не вызвав подозрений, тебе понадобится маскировка." }, { 23.58, "Попробуй найти её среди бойцов Синдиката за пределами крепости, у Северного поместья." } } }, t = { d = 4.1, v = "bloodelf-male", n = { x = 0 }, c = { x = { { 0.00, "*Взяв форму, ты готовишься к следующей части задания.*" } } } } },
    [96784] = { d = 15.0, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Ты вспоминаешь указания Мирокоса: узнать о важной сделке Синдиката в крепости Стромгард." }, { 6.49, "В маскировке ты сможешь довольно свободно разговаривать с членами Синдиката." }, { 12.06, "Наверняка кто-то из них что-нибудь знает." } } }, t = { d = 6.2, v = "human-female", n = { x = 27 }, c = { x = { { 0.00, "*Глаза Анастасии подозрительно сужаются.*" }, { 3.76, "...Откуда ты вообще знаешь о сделке?" } } } } },
    [96785] = { d = 15.1, g = 1, v = "human-female", n = { m = 172, f = 173 }, c = { m = { { 0.00, "Ты кто такой вообще?" }, { 1.48, "Заявился сюда и суёшь нос в чужие дела." }, { 4.30, "Я не стану рассказывать новичку о делах начальства без веской причины." }, { 9.30, "Если у тебя нет для меня чего-нибудь важного или ценного, мне нечего тебе сказать." } }, f = { { 0.00, "Ты кто такая вообще?" }, { 1.44, "Заявилась сюда и суёшь нос в чужие дела." }, { 4.25, "Я не стану рассказывать новичку о делах начальства без веской причины." }, { 9.13, "Если у тебя нет для меня чего-нибудь важного или ценного, мне нечего тебе сказать." } } }, t = { d = 11.5, g = 1, v = "human-female", n = { m = 73, f = 73 }, c = { m = { { 0.00, "Ах ты... где ты это нашёл!?" }, { 2.96, "*Анастасия берёт себя в руки.*" }, { 5.44, "Ладно." }, { 5.97, "Я расскажу тебе о сделке." }, { 7.89, "Только верни это мне, и будем в расчёте." } }, f = { { 0.00, "Ах ты... где ты это нашла!?" }, { 3.28, "*Анастасия берёт себя в руки.*" }, { 5.84, "Ладно." }, { 6.41, "Я расскажу тебе о сделке." }, { 8.47, "Только верни это мне, и будем в расчёте." } } } } },
    [96786] = { d = 21.0, v = "human-female", n = { x = 246 }, c = { x = { { 0.00, "Соколиный Шлем отправил пару ребят передать груз у южной части стены Торадина." }, { 5.37, "Что они забирают - не знаю." }, { 7.26, "Должно быть, что-то стоящее, раз все держат это в строжайшем секрете." }, { 11.96, "Думаю, даже те, кто будет забирать груз, не знают, что это." }, { 15.99, "Это всё, что мне известно." }, { 17.76, "Не заставляй меня пожалеть, что я тебе рассказала." } } }, t = { d = 19.8, g = 1, v = "bloodelf-male", n = { m = 217, f = 219 }, c = { m = { { 0.00, "Надо же, ты добыл это немалыми усилиями." }, { 2.98, "Ты знаешь толк в тайной игре." }, { 5.12, "Если тебе любопытно, что в этой посылке, надеюсь, ты понимаешь: такие сведения даются лишь тем, кому положено знать." }, { 13.48, "Тем не менее ты честно послужил поместью." }, { 16.46, "За это тебя непременно следует наградить." } }, f = { { 0.00, "Надо же, ты добыла это немалыми усилиями." }, { 3.09, "Ты знаешь толк в тайной игре." }, { 5.26, "Если тебе любопытно, что в этой посылке, надеюсь, ты понимаешь: такие сведения даются лишь тем, кому положено знать." }, { 13.73, "Тем не менее ты честно послужила поместью." }, { 16.82, "За это тебя непременно следует наградить." } } } } },
    [96797] = { d = 31.1, v = "human-female", n = { x = 357 }, c = { x = { { 0.00, "Мы часто пытаемся найти уцелевших родных для наших подопечных, и иногда находим что-то обнадёживающее." }, { 7.20, "Мне сообщили, что у нашего Рандала, возможно, есть живой родственник." }, { 12.03, "Его зовут Даннет, он солдат и служит в Крепости Стражей Пустоты." }, { 16.68, "Нужно, чтобы кто-то отправился туда и нашёл его." }, { 20.18, "Если сможешь, пожалуйста, убеди Даннета приехать за племянником." }, { 24.77, "Не думаю, что они хоть раз встречались, но они всё равно семья, и Рандалу место рядом с ним." } } } },
    [96798] = { d = 31.0, v = "human-male#50", n = { x = 371 }, c = { x = { { 0.00, "Сержанта Даннета в последний раз видели в дозоре с его отрядом у Змеиных Колец, к югу от Крепости Стражей Пустоты." }, { 7.76, "Один из бойцов его отряда, тяжело раненный, добрёл до крепости и сказал, что весь отряд перебит или взят в плен." }, { 15.29, "К сожалению, через несколько часов этот солдат умер." }, { 18.93, "Подтверждения, что Даннет мёртв, у нас нет, но надежды мало." }, { 22.87, "Я не могу выделить людей, чтобы штурмовать логово культа, но если ты решишь отправиться на поиски, от помощи я не откажусь." } } } },
    [96799] = { d = 23.9, g = 1, v = "human-male#50", n = { m = 214, f = 215 }, c = { m = { { 0.00, "*Лейтенант Коннар слушает ваш рассказ о том, зачем вы пришли.*" }, { 4.72, "Значит, у Даннета есть осиротевший племянник в Даларане?" }, { 8.64, "Если ты ещё не говорил с ним об этом, советую поговорить." }, { 12.63, "На заботливого отца он не очень похож, но, может, ещё меня удивит." }, { 17.31, "Если, поправившись, он захочет забрать мальчика, я с лёгким сердцем отпущу его в отпуск." } }, f = { { 0.00, "*Лейтенант Коннар слушает ваш рассказ о том, зачем вы пришли.*" }, { 4.72, "Значит, у Даннета есть осиротевший племянник в Даларане?" }, { 8.63, "Если ты ещё не говорила с ним об этом, советую поговорить." }, { 13.16, "На заботливого отца он не очень похож, но, может, ещё меня удивит." }, { 17.84, "Если, поправившись, он захочет забрать мальчика, я с лёгким сердцем отпущу его в отпуск." } } } },
    [96800] = { d = 31.8, g = 1, v = "dwarf-male", n = { x = 361 }, c = { m = { { 0.00, "Эй, герой." }, { 0.74, "Мне не помешает помощь с одним делом." }, { 3.31, "Я как раз сейчас пишу диссертацию о древних мастерах рун клана Громового Молота из Грим Батола, и для моих исследований требуется кое-какой фолиант." }, { 13.36, "Судя по нашим записям, маг по имени Доан взял эту книгу в старой библиотеке Даларана ещё перед Третьей войной и так и не вернул её!" }, { 22.31, "Теперь этот чародей скрывается в монастыре Алого ордена в Тирисфальских лесах." }, { 27.70, "Верни мне книгу, и я тебя щедро вознагражу." } }, f = { { 0.00, "Эй, героиня." }, { 0.89, "Мне не помешает помощь с одним делом." }, { 3.55, "Я как раз сейчас пишу диссертацию о древних мастерах рун клана Громового Молота из Грим Батола, и для моих исследований требуется кое-какой фолиант." }, { 13.95, "Судя по нашим записям, маг по имени Доан взял эту книгу в старой библиотеке Даларана ещё перед Третьей войной и так и не вернул её!" }, { 23.21, "Теперь этот чародей скрывается в монастыре Алого ордена в Тирисфальских лесах." }, { 28.80, "Верни мне книгу, и я тебя щедро вознагражу." } } } },
    [96811] = { d = 4.6, g = 1, v = "human-male", n = { m = 42, f = 43 }, c = { m = { { 0.00, "Кажется, я готов." }, { 1.60, "Выступаем, как только будешь готов." } }, f = { { 0.00, "Кажется, я готов." }, { 1.55, "Выступаем, как только будешь готова." } } } },
    [96812] = { d = 24.6, v = "human-male#50", n = { x = 251 }, c = { x = { { 0.00, "Да... да, я возьму мальчика к себе." }, { 2.69, "Он моя семья, и, кроме меня, у него никого нет." }, { 6.40, "Мне нужно ещё немного подлечиться, но как только смогу, я возьму отпуск и отправлюсь в Даларан." }, { 13.63, "Пожалуйста, вернись к попечительнице и скажи ей, что я уже в пути." }, { 18.66, "Я сделаю всё, чтобы сын моего брата был в безопасности и вырос сильным." }, { 24.10, "Клянусь." } } } },
    [96821] = { d = 23.2, v = "troll-male#78", n = { x = 257 }, c = { x = { { 0.00, "Со стороны Колючего Холма приходит всё меньше и меньше путников." }, { 4.79, "Дорога и так была не самая приятная из-за скорпидов, так теперь ходят слухи, что вдоль неё появились гнёзда пауков." }, { 13.23, "Если отправишься куда-нибудь на север, убей хоть сколько-то пауков по пути." }, { 18.81, "Потом скажешь в Колючем Холме, что дорога стала безопаснее." } } }, t = { d = 9.1, g = 1, v = "orc-male#60", n = { m = 89, f = 90 }, c = { m = { { 0.00, "Батраки уже давно боятся ходить на юг." }, { 3.12, "Теперь, когда ты немного расчистил путь, мы можем снова занять их делом." } }, f = { { 0.00, "Батраки уже давно боятся ходить на юг." }, { 3.24, "Теперь, когда ты немного расчистила путь, мы можем снова занять их делом." } } } } },
    [96822] = { d = 24.2, v = "orc-male#60", n = { x = 259 }, c = { x = { { 0.00, "Мы потеряли много отважных воинов, когда разоряли крепость Тирагард." }, { 5.38, "Теперь люди возвели в руинах новые укрепления, и мы не можем собрать останки, чтобы почтить память погибших." }, { 13.91, "Ступай в руины, окружающие крепость, и разыщи оружие, оставленное нашими павшими братьями и сёстрами." }, { 21.73, "Мы выставим его на почётном месте." } } }, t = { d = 5.3, v = "orc-male#60", n = { x = 43 }, c = { x = { { 0.00, "Этих воинов никогда не забудут." }, { 3.22, "И всё благодаря тебе." } } } } },
    [96825] = { d = 29.2, v = "orc-male", n = { x = 312 }, c = { x = { { 0.00, "Охотники и рыбаки приносят нашим бойцам достаточно мяса – а вот шанса поесть чего-то сладкого у них давно не было." }, { 8.76, "Я знаю кактус, на котором вырастают колючие, но вкусные плоды." }, { 13.55, "Вот только растут эти кактусы среди холмов на западе, совсем рядом с лагерями мерзких свинобразов." }, { 21.14, "Ты уж постарайся их обойти и добудь мне те фрукты." }, { 24.90, "Только осторожно: фрукты такие же колючие, как свинобразы!" } } }, t = { d = 12.0, v = "orc-male", n = { x = 113 }, c = { x = { { 0.00, "Я приготовлю из этих фруктов кое-что вкусное, а семена оставлю – потом посадим." }, { 6.94, "Когда-нибудь колючие груши будут расти по всему Оргриммару!" } } } } },
    [96873] = { d = 28.2, v = "troll-female#75", n = { x = 327 }, c = { x = { { 0.00, "Тролли на востоке отсюда потеряли волю и полностью подчинились знахарю Залазану." }, { 5.90, "Он сохраняет контроль над жертвами с помощью разных жестоких чар, но его излюбленный приём – заставлять их носить подвески, зачарованные злыми связывающими заклинаниями." }, { 18.02, "Потренируйся в зачаровывании, рассеяв магию этих подвесок, а после принеси мне результат." }, { 24.51, "И если тебе дорога свобода, ни за что их не надевай!" } } }, t = { d = 7.5, v = "troll-female#75", n = { x = 81 }, c = { x = { { 0.00, "Неплохо получилось." }, { 1.52, "Жаль, что пришлось убить тех троллей, зато теперь их души смогут обрести покой." } } } } },
    [96874] = { d = 24.6, g = 1, v = "orc-male", n = { m = 260, f = 261 }, c = { m = { { 0.00, "Ты видел, какие здоровенные звери бродят по Громовому хребту?" }, { 4.65, "Думаю, из гребней у них на спине получилось бы славное лезвие топора." }, { 9.84, "Сару поднял меня на смех, когда я ему это сказал..." }, { 13.82, "Но что он вообще знает?!" }, { 15.64, "Помоги-ка мне – в рамках обучения кузнечному делу!" }, { 19.41, "Принеси несколько гребней и шлифовальных камней, чтобы их заточить." } }, f = { { 0.00, "Ты видела, какие здоровенные звери бродят по Громовому хребту?" }, { 4.75, "Думаю, из гребней у них на спине получилось бы славное лезвие топора." }, { 9.98, "Сару поднял меня на смех, когда я ему это сказал..." }, { 13.98, "Но что он вообще знает?!" }, { 15.82, "Помоги-ка мне – в рамках обучения кузнечному делу!" }, { 19.62, "Принеси несколько гребней и шлифовальных камней, чтобы их заточить." } } }, t = { d = 9.6, v = "orc-male", n = { x = 84 }, c = { x = { { 0.00, "А эти гребни очень даже крепкие!" }, { 2.99, "С ними будет не так просто работать, как я думал..." }, { 7.48, "Но меня это не остановит!" } } } } },
    [96875] = { d = 26.2, g = 1, v = "orc-female#57", n = { x = 280 }, c = { m = { { 0.00, "Оргриммар постоянно растёт, герой." }, { 2.50, "И когда батракам нужны шкуры, чтобы обить стены и крыши новых домов, они приходят ко мне!" }, { 9.39, "Шкуры ящеров с Громового хребта обычно слишком толстые для брони, зато из них получается отличный стройматериал." }, { 17.83, "Принеси мне эти шкуры, а также несколько обработанных шкур полегче." }, { 22.89, "Посмотрим, как ты умеешь работать с кожей!" } }, f = { { 0.00, "Оргриммар постоянно растёт, героиня." }, { 2.65, "И когда батракам нужны шкуры, чтобы обить стены и крыши новых домов, они приходят ко мне!" }, { 9.59, "Шкуры ящеров с Громового хребта обычно слишком толстые для брони, зато из них получается отличный стройматериал." }, { 18.09, "Принеси мне эти шкуры, а также несколько обработанных шкур полегче." }, { 23.19, "Посмотрим, как ты умеешь работать с кожей!" } } }, t = { d = 6.2, v = "orc-female#57", n = { x = 60 }, c = { x = { { 0.00, "Твой труд помогает Оргриммару развиваться." }, { 3.54, "Помни это, ходя по его улицам." } } } } },
    [96876] = { d = 4.6, v = "narrator", n = { x = 39 }, c = { x = { { 0.00, "Вдоль клапана сумки грубовато вышито имя \"Укор\"." } } }, t = { d = 9.5, g = 1, v = "orc-male", n = { m = 81, f = 83 }, c = { m = { { 0.00, "Моя сумка!" }, { 1.02, "Я думал, что уже её не увижу, когда обронил, убегая от того огромного паука." }, { 7.79, "Ты и правда герой!" } }, f = { { 0.00, "Моя сумка!" }, { 1.02, "Я думал, что уже её не увижу, когда обронил, убегая от того огромного паука." }, { 7.50, "Ты и правда героиня!" } } } } },
    [96877] = { d = 6.2, v = "narrator", n = { x = 58 }, c = { x = { { 0.00, "Это огромное копыто – доказательство вашей победы над могучим ящером." } } }, t = { d = 6.2, g = 1, v = "orc-female#57", n = { x = 41 }, c = { m = { { 0.00, "Вот это трофей, герой!" }, { 2.57, "Представляю, какой славный был бой!" } }, f = { { 0.00, "Вот это трофей, героиня!" }, { 2.55, "Представляю, какой славный был бой!" } } } } },
    [96895] = { d = 39.3, g = 1, v = "scourge-male", n = { m = 368, f = 369 }, c = { m = { { 0.00, "Не знаю, слышал ты или нет, но недавно здесь проходили два посланника Серебряного Рассвета." }, { 7.90, "У меня нет проблем с этим орденом, но это не значит, что его агентам можно хозяйничать в Тирисфале без присмотра." }, { 17.86, "Они оба были Отрёкшимися... но мне всё равно это не нравится." }, { 23.24, "Один из них только что отправился отсюда на юго-восток." }, { 28.14, "Там на окраинах города действует группа сектантов Плети." }, { 33.12, "Если посланники узнали про сектантов, то наверняка заинтересовались ими." } }, f = { { 0.00, "Не знаю, слышала ты или нет, но недавно здесь проходили два посланника Серебряного Рассвета." }, { 7.53, "У меня нет проблем с этим орденом, но это не значит, что его агентам можно хозяйничать в Тирисфале без присмотра." }, { 16.92, "Они оба были Отрёкшимися... но мне всё равно это не нравится." }, { 21.99, "Один из них только что отправился отсюда на юго-восток." }, { 26.61, "Там на окраинах города действует группа сектантов Плети." }, { 31.31, "Если посланники узнали про сектантов, то наверняка заинтересовались ими." } } }, t = { d = 7.3, g = 1, v = "scourge-male", n = { x = 59 }, c = { m = { { 0.00, "Пригнись и постарайся не высовываться, герой." }, { 4.19, "С этими сектантами шутки плохи." } }, f = { { 0.00, "Пригнись и постарайся не высовываться, героиня." }, { 4.40, "С этими сектантами шутки плохи." } } } } },
    [96896] = { d = 39.8, v = "scourge-male", n = { x = 379 }, c = { x = { { 0.00, "Мы с Данитой вместе защищали Подгород от Плети, когда напали твари из Наксрамаса." }, { 7.17, "В тот день мы потеряли многих добрых друзей, среди которых был герой, в честь которого эта крепость и получила своё имя – Гарек Бандарион." }, { 19.21, "Возможно, он оказался первым Отрёкшимся, заново научившимся использовать силы Света как паладин." }, { 27.56, "Здорово было бы, если бы его наследие передалось здесь Даните и её подчинённым." }, { 34.41, "Если бы только остальные Отрёкшиеся разделяли мои устремления..." } } }, t = { d = 21.6, v = "scourge-male", n = { x = 228 }, c = { x = { { 0.00, "Я планирую остаться здесь на некоторое время и пообщаться с другими моими товарищами, но скоро вернусь в часовню Последней Надежды в Восточных Чумных землях." }, { 12.62, "Если когда-нибудь будешь в тех краях, то заглядывай." }, { 16.82, "Нам всегда пригодится помощь способного искателя приключений." } } } } },
    [96897] = { d = 22.0, v = "scourge-male", n = { x = 189 }, c = { x = { { 0.00, "Плеть – чума на теле нашей земли, а её живые слуги – худшие из всех." }, { 6.48, "Жители Тирисфаля выбиваются из сил, разрываясь между безмозглыми мертвецами и Алым орденом." }, { 15.09, "Если хочешь сделать доброе дело, помоги мне разделаться с этой мерзостью." } } }, t = { d = 11.2, g = 1, v = "scourge-male", n = { x = 103 }, c = { m = { { 0.00, "Спасибо за помощь, герой." }, { 2.18, "Чтобы история Лордерона не повторилась, мы должны бдительно следить за всеми новыми угрозами вроде этой." } }, f = { { 0.00, "Спасибо за помощь, героиня." }, { 2.38, "Чтобы история Лордерона не повторилась, мы должны бдительно следить за всеми новыми угрозами вроде этой." } } } } },
    [96898] = { d = 38.9, v = "scourge-male", n = { x = 372 }, c = { x = { { 0.00, "Ещё не так давно этому городу угрожала цитадель Наксрамас, стремившаяся стереть Отрёкшихся с лица земли." }, { 9.14, "И Отрёкшиеся, и Серебряный Рассвет тогда принесли огромные жертвы, чтобы обеспечить Отрёкшимся будущее." }, { 18.13, "В той битве фокусирующий кристалл некротической энергии, установленный на вершине Наксрамаса, был разбит, а его осколки разбросаны по округе." }, { 30.37, "Полагаю, они-то и были нужны сектантам." }, { 33.95, "Помоги мне вернуть эти фрагменты, вырвав их из рук Плети." } } }, t = { d = 17.6, v = "scourge-male", n = { x = 166 }, c = { x = { { 0.00, "Спасибо." }, { 0.80, "Так мы замедлим наступление Плети в этом районе." }, { 5.10, "Полагаю, обитатели Тирисфаля ещё долгие годы будут выкапывать из земли эти кристаллы, но от извлечения наиболее заметных хуже точно не станет." } } } } },
    [96899] = { d = 38.7, g = 1, v = "scourge-male", n = { m = 398, f = 399 }, c = { m = { { 0.00, "Сегодня ты оказал Серебряному Рассвету огромную услугу, и я очень благодарен за это." }, { 6.79, "Уж не знаю, многое ли тебе известно о крепости Бандариона, но мы с командиром как раз направлялись туда на встречу с тамошним командованием." }, { 17.85, "Это было ещё до того, как нам стало известно о присутствии культа Проклятых." }, { 23.99, "Если ты хочешь узнать больше о Серебряном Рассвете и нашей миссии, разыщи моего командира в крепости Бандариона – это к северо-западу отсюда." }, { 35.48, "Я же пока останусь здесь наводить порядок." } }, f = { { 0.00, "Сегодня ты оказала Серебряному Рассвету огромную услугу, и я очень благодарен за это." }, { 6.72, "Уж не знаю, многое ли тебе известно о крепости Бандариона, но мы с командиром как раз направлялись туда на встречу с тамошним командованием." }, { 17.55, "Это было ещё до того, как нам стало известно о присутствии культа Проклятых." }, { 23.57, "Если ты хочешь узнать больше о Серебряном Рассвете и нашей миссии, разыщи моего командира в крепости Бандариона – это к северо-западу отсюда." }, { 34.82, "Я же пока останусь здесь наводить порядок." } } }, t = { d = 38.2, v = "scourge-male", n = { x = 371 }, c = { x = { { 0.00, "Это место навевает на меня воспоминания." }, { 3.51, "Когда-то эта крепость принадлежала Серебряному Рассвету – именно здесь мы готовились ко многим битвам и стычкам с силами Плети во время их последнего вторжения в Тирисфальские леса." }, { 18.78, "Когда мы отступили в Чумные земли, я переживал, что оно придёт в упадок." }, { 24.89, "Мои опасения были вполне обоснованными, но я рад, что крепость теперь занимает Данита со своими паладинами." }, { 33.97, "Она даже назвала её в честь... нашего общего друга." } } } } },
    [96912] = { d = 15.7, g = 1, v = "goblin-male", n = { m = 163, f = 162 }, c = { m = { { 0.00, "Эй, приятель, подходи, не стесняйся!" }, { 2.76, "Сразу видно, ты знаешь, каким концом меча куда тыкать!" }, { 7.11, "Так уж вышло, что у меня есть длинный список испытаний, с которыми справятся только самые лучшие бойцы." }, { 15.06, "Рискнёшь?" } }, f = { { 0.00, "Эй, подруга, подходи, не стесняйся!" }, { 2.87, "Сразу видно, ты знаешь, каким концом меча куда тыкать!" }, { 7.22, "Так уж вышло, что у меня есть длинный список испытаний, с которыми справятся только самые лучшие бойцы." }, { 15.17, "Рискнёшь?" } } } },
    [96982] = { d = 40.4, g = 1, v = "tauren-male", n = { x = 323 }, c = { m = { { 0.00, "А-а, герой." }, { 1.24, "Я жду тебя." }, { 2.40, "Ветра словно сами принесли тебя ко мне." }, { 6.40, "Ты подыскиваешь себе кодо, так?" }, { 9.50, "Кодо – благородный и незлобивый зверь." }, { 13.24, "Мало какие животные служат так безотказно." }, { 17.50, "Сегодня ты стоишь перед важным выбором." }, { 21.50, "Вы с кодо объедете вместе весь мир, поэтому найди того, в котором почувствуешь родную душу." }, { 30.56, "Не беспокойся: ошибиться тут нельзя." }, { 34.11, "Ступай осмотри всех кодо и возвращайся, когда примешь решение." } }, f = { { 0.00, "А-а, героиня." }, { 1.50, "Я жду тебя." }, { 2.66, "Ветра словно сами принесли тебя ко мне." }, { 6.66, "Ты подыскиваешь себе кодо, так?" }, { 9.76, "Кодо – благородный и незлобивый зверь." }, { 13.50, "Мало какие животные служат так безотказно." }, { 17.76, "Сегодня ты стоишь перед важным выбором." }, { 21.76, "Вы с кодо объедете вместе весь мир, поэтому найди того, в котором почувствуешь родную душу." }, { 30.82, "Не беспокойся: ошибиться тут нельзя." }, { 34.37, "Ступай осмотри всех кодо и возвращайся, когда примешь решение." } } } },
    [96984] = { d = 37.7, g = 1, v = "human-female", n = { m = 424, f = 426 }, c = { m = { { 0.00, "Может, тебе наши дела и не интересны, но от лишней пары рук я точно не откажусь." }, { 5.63, "К тому же, если Даларан падёт, то потянет за собой и всё остальное, включая ваш Подгород." }, { 11.77, "Значит, твой покровитель хочет попасть в город?" }, { 15.08, "Ладно." }, { 15.58, "Я зачарую ключ, чтобы он деактивировал защиту и ты мог попасть в Даларан." }, { 20.59, "Я буду ждать тебя в Аметистовой цитадели – именно там всё это и началось." }, { 25.66, "В царящем хаосе Кирин-Тору будет не до того, чтобы тебя останавливать." }, { 31.41, "Забирай что хочешь, но что бы ни случилось, наша главная задача – предотвратить катастрофу." } }, f = { { 0.00, "Может, тебе наши дела и не интересны, но от лишней пары рук я точно не откажусь." }, { 5.63, "К тому же, если Даларан падёт, то потянет за собой и всё остальное, включая ваш Подгород." }, { 11.76, "Значит, твой покровитель хочет попасть в город?" }, { 15.07, "Ладно." }, { 15.57, "Я зачарую ключ, чтобы он деактивировал защиту и ты могла попасть в Даларан." }, { 20.76, "Я буду ждать тебя в Аметистовой цитадели – именно там всё это и началось." }, { 25.83, "В царящем хаосе Кирин-Тору будет не до того, чтобы тебя останавливать." }, { 31.64, "Забирай что хочешь, но что бы ни случилось, наша главная задача – предотвратить катастрофу." } } }, t = { d = 14.9, v = "scourge-male#82", n = { x = 117 }, c = { x = { { 0.00, "Тень архимага?" }, { 1.45, "Ничего себе." }, { 2.81, "Как неловко." }, { 4.08, "И что, Кирин-Тор впустили тебя в свои покои?" }, { 8.61, "Интересно." }, { 9.70, "Возможно, из этого получится извлечь некую выгоду..." } } } } },
    [96986] = { d = 34.7, v = "creature/banshee", n = { x = 291 }, c = { x = { { 0.00, "В самых недрах города магов на севере скрывается предатель нашего народа, некромант незаурядного таланта." }, { 10.50, "Он поднимает армию нежити прямо под носом у Кирин-Тора." }, { 16.02, "Мне нет дела до судьбы города магов, но этот могильный рыцарь плевать хотел на все принципы Отрёкшихся." }, { 26.17, "Положи этому конец." }, { 28.21, "Покажи ему, что никто не скроется от карающей длани Тёмной Госпожи." } } }, t = { d = 10.2, g = 1, v = "creature/banshee", n = { m = 88, f = 89 }, c = { m = { { 0.00, "Ты отлично справился." }, { 2.14, "Эта тварь не заслуживает чести ходить среди мёртвых." }, { 7.30, "Пусть покоится у них под ногами." } }, f = { { 0.00, "Ты отлично справилась." }, { 1.95, "Эта тварь не заслуживает чести ходить среди мёртвых." }, { 7.11, "Пусть покоится у них под ногами." } } } } },
    [96987] = { d = 37.0, g = 1, v = "narrator", n = { m = 395, f = 395 }, c = { m = { { 0.00, "Гляди-ка, да это ж родственная душа-делец." }, { 3.30, "Пробираешься в Даларан в такие смутные времена?" }, { 6.95, "Ай-яй-яй!" }, { 7.71, "Ты мне уже нравишься!" }, { 9.36, "Пока наши магически одарённые товарищи заняты своими делами, предлагаю поискать пару \"потерявшихся\" сокровищ." }, { 17.76, "У них тут целые библиотеки забиты навороченными книжками по волшебству." }, { 23.13, "Принеси мне какой-нибудь тайный фолиантик, и я его толкну за хорошие деньги." }, { 28.98, "Прибыль пополам." }, { 30.29, "Да не смотри ты на меня так!" }, { 32.43, "Можно подумать, ты сюда на экскурсию пришёл." }, { 35.80, "Ну что, по рукам?" } }, f = { { 0.00, "Гляди-ка, да это ж родственная душа-делец." }, { 3.26, "Пробираешься в Даларан в такие смутные времена?" }, { 6.85, "Ай-яй-яй!" }, { 7.60, "Ты мне уже нравишься!" }, { 9.22, "Пока наши магически одарённые товарищи заняты своими делами, предлагаю поискать пару \"потерявшихся\" сокровищ." }, { 17.50, "У них тут целые библиотеки забиты навороченными книжками по волшебству." }, { 22.79, "Принеси мне какой-нибудь тайный фолиантик, и я его толкну за хорошие деньги." }, { 28.56, "Прибыль пополам." }, { 29.84, "Да не смотри ты на меня так!" }, { 31.95, "Можно подумать, ты сюда на экскурсию пришла." }, { 35.34, "Ну что, по рукам?" } } } },
    [96988] = { d = 38.6, v = "scourge-male", n = { x = 401 }, c = { x = { { 0.00, "Раз уж Даларан сейчас в осаде своих собственных механизмов, самое время, скажем так, одолжить у них парочку образцов." }, { 9.55, "Только представь себе армию движимых магией поганищ!" }, { 13.96, "У Тёмной Госпожи не останется иного выбора, кроме как признать мой алхимический гений." }, { 20.94, "Может, она даже назначит меня главой Королевского фармацевтического общества!" }, { 27.33, "Отправляйся в Даларан и достань несколько сердечников часовых." }, { 32.40, "Вряд ли они расстанутся с ними добровольно, так что действуй по обстоятельствам." } } }, t = { d = 21.0, v = "scourge-male", n = { x = 183 }, c = { x = { { 0.00, "Этот с трещиной." }, { 1.57, "И этот." }, { 2.31, "И ЭТОТ С ТРЕЩИНОЙ!" }, { 4.04, "Просто курам на смех!" }, { 6.02, "Я же просил обезвредить часовых, а не разнести их в пух и прах!" }, { 11.63, "Да что в них было такого-то опасного?!" }, { 15.10, "Придётся пока что отложить мечту о создании магического поганища..." } } } } },
    [96989] = { d = 35.1, g = 1, v = "troll-male", n = { m = 335, f = 336 }, c = { m = { { 0.00, "Эй, мон!" }, { 0.67, "Гляжу, сегодня у тебя большой день." }, { 3.67, "Думаешь, ты готов взять поводья одной из этих свирепых тварей, а?" }, { 9.13, "Многие недооценивают, какие эти звери умные и дикие." }, { 13.62, "Лучше, быстрее и смертоноснее спутника тебе не найти, когда вы с ним станете одним целым." }, { 21.11, "Так что тебе предстоит важный выбор." }, { 24.18, "Вам с ящером вместе странствовать по свету, и ящер тоже должен выбрать тебя." }, { 30.61, "Ступай погляди и возвращайся ко мне, когда выберешь." } }, f = { { 0.00, "Эй, мон!" }, { 0.67, "Гляжу, сегодня у тебя большой день." }, { 3.67, "Думаешь, ты готова взять поводья одной из этих свирепых тварей, а?" }, { 9.40, "Многие недооценивают, какие эти звери умные и дикие." }, { 13.89, "Лучше, быстрее и смертоноснее спутника тебе не найти, когда вы с ним станете одним целым." }, { 21.38, "Так что тебе предстоит важный выбор." }, { 24.45, "Вам с ящером вместе странствовать по свету, и ящер тоже должен выбрать тебя." }, { 30.88, "Ступай погляди и возвращайся ко мне, когда выберешь." } } } },
    [96994] = { d = 40.6, g = 1, v = "orc-male#126", n = { m = 353, f = 353 }, c = { m = { { 0.00, "Лок'тар, герой." }, { 1.45, "Пришёл за своим первым волком?" }, { 4.18, "Хорошо." }, { 4.91, "Нет связи крепче, чем между орком и его волком." }, { 9.25, "Волк — не просто ездовое животное, а спутник и друг на всю жизнь." }, { 14.89, "Мы выбираем друг друга не из тщеславия." }, { 18.35, "Нет, каждый орк и его волк связаны особыми узами, а это куда больше, чем простая покупка." }, { 26.40, "Волк выберет тебя так же, как ты выберешь его." }, { 30.50, "Ты поймёшь, когда встретишь его." }, { 33.40, "Ступай и найди волка, который отзовётся тебе." }, { 37.50, "Возвращайся, когда найдёшь ответ." } }, f = { { 0.00, "Лок'тар, героиня." }, { 1.64, "Пришла за своим первым волком?" }, { 4.48, "Хорошо." }, { 5.21, "Нет связи крепче, чем между орком и его волком." }, { 9.55, "Волк — не просто ездовое животное, а спутник и друг на всю жизнь." }, { 15.19, "Мы выбираем друг друга не из тщеславия." }, { 18.65, "Нет, каждый орк и его волк связаны особыми узами, а это куда больше, чем простая покупка." }, { 26.70, "Волк выберет тебя так же, как ты выберешь его." }, { 30.80, "Ты поймёшь, когда встретишь его." }, { 33.70, "Ступай и найди волка, который отзовётся тебе." }, { 37.80, "Возвращайся, когда найдёшь ответ." } } } },
    [96996] = { d = 31.3, g = 1, v = "skyborne-male#3775", n = { m = 330, f = 332 }, c = { m = { { 0.00, "Теперь, когда ты закончил обучение, ветра хотят, чтобы ты выбрал себе первого буренога." }, { 6.88, "На них скакало много поколений наших предков." }, { 10.42, "Буреноги изящные и кажутся хрупкими, но на деле это крепкие и отважные животные." }, { 16.68, "Ты со своим буреногом пересечёшь весь мир, так что это важный выбор." }, { 21.82, "Не страшись – любое решение, которое ты примешь, будет правильным." }, { 26.96, "Ступай осмотри буреногов и возвращайся, когда выберешь." } }, f = { { 0.00, "Теперь, когда ты закончила обучение, ветра хотят, чтобы ты выбрала себе первого буренога." }, { 7.10, "На них скакало много поколений наших предков." }, { 10.64, "Буреноги изящные и кажутся хрупкими, но на деле это крепкие и отважные животные." }, { 16.90, "Ты со своим буреногом пересечёшь весь мир, так что это важный выбор." }, { 22.04, "Не страшись – любое решение, которое ты примешь, будет правильным." }, { 27.18, "Ступай осмотри буреногов и возвращайся, когда выберешь." } } } },
    [96997] = { d = 39.4, g = 1, v = "scourge-male#146", n = { m = 349, f = 350 }, c = { m = { { 0.00, "Приветствую, герой." }, { 1.69, "Кажется, я догадываюсь, что привело тебя в мои конюшни." }, { 6.46, "Если ищешь скакуна, ты пришёл по адресу." }, { 9.92, "Но предупреждаю: ездить на скакуне-нежити – занятие не для слабонервных." }, { 16.00, "А потому тебе нужно сделать важный выбор." }, { 19.69, "Вам с твоим скакуном-нежитью предстоит странствовать по миру вместе – к добру или к худу." }, { 27.38, "Не бойся: какой бы выбор ты ни сделал, он будет верным." }, { 32.15, "Осмотри лошадей-нежить и возвращайся ко мне, когда сделаешь выбор." } }, f = { { 0.00, "Приветствую, героиня." }, { 2.12, "Кажется, я догадываюсь, что привело тебя в мои конюшни." }, { 6.89, "Если ищешь скакуна, ты пришла по адресу." }, { 10.57, "Но предупреждаю: ездить на скакуне-нежити – занятие не для слабонервных." }, { 16.65, "А потому тебе нужно сделать важный выбор." }, { 20.34, "Вам с твоим скакуном-нежитью предстоит странствовать по миру вместе – к добру или к худу." }, { 28.03, "Не бойся: какой бы выбор ты ни сделала, он будет верным." }, { 33.84, "Осмотри лошадей-нежить и возвращайся ко мне, когда сделаешь выбор." } } } },
    [97003] = { d = 39.8, g = 1, v = "orc-male", n = { m = 358, f = 358 }, c = { m = { { 0.00, "Эй, герой." }, { 0.93, "Нужна твоя помощь." }, { 2.64, "До нас дошли слухи о чудище, поселившемся в пещере на Тернистом холме, к северо-востоку отсюда." }, { 10.85, "Свинобразы из племени Иглогривых зовут его Чол'арук или \"Стервятник\"." }, { 16.90, "Говорят, он в пять раз больше обычного свинобраза и особенно кровожаден." }, { 23.02, "Многие не верят этим историям." }, { 25.73, "А вот я верю: потому что уже сражался с такими." }, { 29.84, "Найди логово Чол'арука и убей его." }, { 32.94, "Принеси мне его голову." }, { 35.04, "Но не ходи один и хорошо подготовься." }, { 38.29, "Кровь и гром, герой." } }, f = { { 0.00, "Эй, героиня." }, { 1.04, "Нужна твоя помощь." }, { 2.69, "До нас дошли слухи о чудище, поселившемся в пещере на Тернистом холме, к северо-востоку отсюда." }, { 10.59, "Свинобразы из племени Иглогривых зовут его Чол'арук или \"Стервятник\"." }, { 16.41, "Говорят, он в пять раз больше обычного свинобраза и особенно кровожаден." }, { 22.31, "Многие не верят этим историям." }, { 24.92, "А вот я верю: потому что уже сражался с такими." }, { 28.87, "Найди логово Чол'арука и убей его." }, { 31.86, "Принеси мне его голову." }, { 33.87, "Но не ходи одна и хорошо подготовься." }, { 37.00, "Кровь и гром, героиня." } } }, t = { d = 19.5, g = 1, v = "orc-male", n = { x = 181 }, c = { m = { { 0.00, "Неплохо, герой." }, { 1.39, "Теперь все поверят моим рассказам, когда я вернусь в Оргриммар с жутким трофеем, доказывающим существование этих чудовищ." }, { 11.85, "Но слава за эту победу целиком принадлежит тебе – я всем расскажу о твоём подвиге." }, { 18.90, "Лок-тар!" } }, f = { { 0.00, "Неплохо, героиня." }, { 1.52, "Теперь все поверят моим рассказам, когда я вернусь в Оргриммар с жутким трофеем, доказывающим существование этих чудовищ." }, { 11.82, "Но слава за эту победу целиком принадлежит тебе – я всем расскажу о твоём подвиге." }, { 18.75, "Лок-тар!" } } } } },
    [97005] = { d = 37.8, v = "human-male", n = { x = 402 }, c = { x = { { 0.00, "Ходят слухи, что в пещере на северо-западе отсюда, на Тернистом холме, поселилось страшное чудище." }, { 7.47, "Свинобразы из племени Иглогривых зовут его Чол'арук или \"Стервятник\"." }, { 12.77, "Говорят, он такой огромный, что может целиком проглотить орка." }, { 17.53, "Мало кто верит в такие россказни, зато верю я... потому что и сам сражался с подобным чудовищем." }, { 24.80, "Эта тварь должна умереть – ради чести товарищей, которых я тогда потерял." }, { 30.44, "Собери могучих союзников и отыщи логово Чол'арука." }, { 34.31, "Убей эту мерзкую тварь и принеси мне её голову." } } }, t = { d = 14.0, g = 1, v = "human-male", n = { m = 143, f = 145 }, c = { m = { { 0.00, "Моим павшим воинам будет спокойнее от того, что в мире стало на одно такое чудовище меньше." }, { 7.19, "Ты отлично справился – истинный и стойкий защитник Альянса." }, { 11.75, "Спасибо." }, { 12.44, "Ступай с честью." } }, f = { { 0.00, "Моим павшим воинам будет спокойнее от того, что в мире стало на одно такое чудовище меньше." }, { 7.32, "Ты отлично справилась – истинная и стойкая защитница Альянса." }, { 12.11, "Спасибо." }, { 12.81, "Ступай с честью." } } } } },
    [97017] = { d = 34.2, g = 1, v = "dwarf-male#100", n = { m = 353, f = 356 }, c = { m = { { 0.00, "А, гляжу, у тебя сегодня большой день!" }, { 2.88, "За первым бараном пожаловал, а?" }, { 5.23, "Эти бараны — самые стойкие и выносливые во всём Азероте." }, { 9.45, "Они яростно защищают своего седока." }, { 12.20, "Да-а, вернее спутника для странствий тебе не сыскать." }, { 16.22, "Так что тебе предстоит важный выбор." }, { 18.97, "Вам с бараном вместе по свету ездить, так что выбирай с умом!" }, { 23.53, "Да не волнуйся, парень, какой выбор ни сделаешь — он будет верным." }, { 28.49, "Ступай погляди на баранов и возвращайся ко мне, когда выберешь." } }, f = { { 0.00, "А, гляжу, у тебя сегодня большой день!" }, { 2.88, "За первым бараном пожаловала, а?" }, { 5.52, "Эти бараны — самые стойкие и выносливые во всём Азероте." }, { 9.74, "Они яростно защищают своего седока." }, { 12.49, "Да-а, вернее спутника для странствий тебе не сыскать." }, { 16.51, "Так что тебе предстоит важный выбор." }, { 19.26, "Вам с бараном вместе по свету ездить, так что выбирай с умом!" }, { 23.82, "Да не волнуйся, девонька, какой выбор ни сделаешь — он будет верным." }, { 29.67, "Ступай погляди на баранов и возвращайся ко мне, когда выберешь." } } } },
    [97018] = { d = 37.1, g = 1, v = "dwarf-male", n = { m = 433, f = 438 }, c = { m = { { 0.00, "Здравствуй, герой!" }, { 1.32, "Похоже, ты уже достаточно опытный искатель приключений, так что я могу научить тебя ездить на баране." }, { 8.43, "Не бесплатно, само собой." }, { 10.26, "Верон предоставит тебе животное бесплатно сразу же после того, как пройдёшь у меня обучение." }, { 16.74, "А после этого ты сможешь приобретать дополнительный транспорт, какой только захочешь." }, { 22.72, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 28.01, "Других наставников ищи уже сам." }, { 30.28, "Когда накопишь достаточно денег, поговори со мной, и я обучу тебя всем премудростям езды на баранах." } }, f = { { 0.00, "Здравствуй, героиня!" }, { 1.42, "Похоже, ты уже достаточно опытная искательница приключений, так что я могу научить тебя ездить на баране." }, { 8.64, "Не бесплатно, само собой." }, { 10.43, "Верон предоставит тебе животное бесплатно сразу же после того, как пройдёшь у меня обучение." }, { 16.78, "А после этого ты сможешь приобретать дополнительный транспорт, какой только захочешь." }, { 22.64, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 27.83, "Других наставников ищи уже сама." }, { 30.17, "Когда накопишь достаточно денег, поговори со мной, и я обучу тебя всем премудростям езды на баранах." } } } },
    [97022] = { d = 8.9, v = "scourge-male#83", n = { x = 114 }, c = { x = { { 0.00, "Данита Морр приказывает тебе вернуться в крепость Бандариона для дополнительной тренировки." }, { 6.22, "Отправляйся в крепость как можно скорее." } } } },
    [97029] = { d = 36.4, g = 1, v = "skyborne-female", n = { m = 357, f = 360 }, c = { m = { { 0.00, "Прошу прощения, этот клинок, что у тебя, – можно мне на него взглянуть?" }, { 5.60, "Как и древнюю рукоять, которую ты принёс мне раньше, этот клинок, полагаю, создал тот же великий мастер-чарокузнец – Люминариан." }, { 15.46, "Если я не ошибаюсь, он зовётся Элуви'ана и был близнецом того клинка, рукоять которого ты мне отдал, – тот назывался Элуви'тор." }, { 25.19, "Каковы шансы, что оба этих бесценных артефакта окажутся у тебя?" }, { 30.22, "Не иначе, это судьба." }, { 31.97, "Дай мне осмотреть его, чтобы убедиться..." } }, f = { { 0.00, "Прошу прощения, этот клинок, что у тебя, – можно мне на него взглянуть?" }, { 5.53, "Как и древнюю рукоять, которую ты принесла мне раньше, этот клинок, полагаю, создал тот же великий мастер-чарокузнец – Люминариан." }, { 15.52, "Если я не ошибаюсь, он зовётся Элуви'ана и был близнецом того клинка, рукоять которого ты мне отдала, – тот назывался Элуви'тор." }, { 26.50, "Каковы шансы, что оба этих бесценных артефакта окажутся у тебя?" }, { 31.53, "Не иначе, это судьба." }, { 33.28, "Дай мне осмотреть его, чтобы убедиться..." } } } },
    [97045] = { d = 34.0, g = 1, v = "human-female#112", n = { m = 388, f = 389 }, c = { m = { { 0.00, "Приветствую!" }, { 0.90, "Хочешь взглянуть на наших лошадей?" }, { 3.40, "Эти скакуны ведут род и от старинной лордеронской породы, и от наших местных лошадей." }, { 9.50, "Более надёжного спутника в странствиях тебе не найти." }, { 13.29, "Выбрать будет непросто: все они превосходны и обучены сохранять спокойствие даже в опасности." }, { 19.96, "Не забывай: вам с лошадью предстоит вместе объехать весь мир." }, { 24.26, "Не сомневаюсь, какой бы выбор ты ни сделал, он будет для тебя лучшим." }, { 29.20, "Ступай осмотри лошадей и возвращайся ко мне, когда выберешь." } }, f = { { 0.00, "Приветствую!" }, { 0.90, "Хочешь взглянуть на наших лошадей?" }, { 3.40, "Эти скакуны ведут род и от старинной лордеронской породы, и от наших местных лошадей." }, { 9.50, "Более надёжного спутника в странствиях тебе не найти." }, { 13.29, "Выбрать будет непросто: все они превосходны и обучены сохранять спокойствие даже в опасности." }, { 19.96, "Не забывай: вам с лошадью предстоит вместе объехать весь мир." }, { 24.26, "Не сомневаюсь, какой бы выбор ты ни сделала, он будет для тебя лучшим." }, { 29.71, "Ступай осмотри лошадей и возвращайся ко мне, когда выберешь." } } } },
    [97046] = { d = 34.5, g = 1, v = "human-female", n = { m = 413, f = 414 }, c = { m = { { 0.00, "Приветствую!" }, { 0.87, "Вижу, сегодня у тебя и правда большой день: сегодня ты синхронизируешь свои биометрические данные с протоколом распознавания седока своего первого механодолгонога!" }, { 12.02, "Этот протокол поможет долгоногу отличать тебя от других возможных седоков." }, { 17.22, "А значит, тебе предстоит важный выбор." }, { 19.95, "Вам с долгоногом вместе странствовать по свету, так что выбирай с умом!" }, { 24.78, "Не бойся: какой бы выбор ты ни сделал, он будет правильным." }, { 28.87, "Ступай осмотри механодолгоногов и возвращайся ко мне, когда определишься." } }, f = { { 0.00, "Приветствую!" }, { 0.87, "Вижу, сегодня у тебя и правда большой день: сегодня ты синхронизируешь свои биометрические данные с протоколом распознавания седока своего первого механодолгонога!" }, { 12.02, "Этот протокол поможет долгоногу отличать тебя от других возможных седоков." }, { 17.22, "А значит, тебе предстоит важный выбор." }, { 19.95, "Вам с долгоногом вместе странствовать по свету, так что выбирай с умом!" }, { 24.78, "Не бойся: какой бы выбор ты ни сделала, он будет правильным." }, { 29.70, "Ступай осмотри механодолгоногов и возвращайся ко мне, когда определишься." } } } },
    [97047] = { d = 20.2, v = "human-male", n = { x = 229 }, c = { x = { { 0.00, "Эй!" }, { 0.25, "Эй ты!" }, { 0.68, "Помоги мне!" }, { 1.49, "Я просто исследовал джунгли, как на меня вдруг набросились эти безумцы!" }, { 6.39, "Не знаю, зачем я им понадобился, но они всё болтают о тиграх и об отрезании голов!" }, { 12.04, "И мне не нравится ни то, ни другое!" }, { 14.40, "Не знаю, как, но спаси меня, пожалуйста!" }, { 17.20, "Найди ключ, маскировку, да что угодно!" }, { 19.81, "Прошу!" } } } },
