    [97074] = { d = 33.6, g = 1, v = "nightelf-male#59", n = { m = 394, f = 399 }, c = { m = { { 0.00, "Здравствуй, герой!" }, { 1.26, "Похоже, ты уже достаточно опытный искатель приключений, и я могу научить тебя ездить на саблезубе." }, { 7.86, "Не бесплатно, само собой." }, { 9.61, "Зато после окончания обучения ты получишь у Леланай собственный транспорт, а дополнительный можешь докупить потом, если захочешь." }, { 18.25, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 23.29, "Других наставников ищи уже сам." }, { 25.46, "Когда накопишь достаточно денег, поговори со мной, и я обучу тебя всем премудростям езды на саблезубах." } }, f = { { 0.00, "Здравствуй, героиня!" }, { 1.72, "Похоже, ты уже достаточно опытная искательница приключений, и я могу научить тебя ездить на саблезубе." }, { 8.87, "Не бесплатно, само собой." }, { 10.62, "Зато после окончания обучения ты получишь у Леланай собственный транспорт, а дополнительный можешь докупить потом, если захочешь." }, { 19.26, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 24.12, "Других наставников ищи уже сама." }, { 26.88, "Когда накопишь достаточно денег, поговори со мной, и я обучу тебя всем премудростям езды на саблезубах." } } } },
    [97130] = { d = 25.1, v = "human-male", n = { x = 300 }, c = { x = { { 0.00, "Мы с Лан'далоком обсуждали недавние события в южных морях." }, { 4.11, "У побережья Тернистой долины неожиданно появились руины древней империи Гурубаши." }, { 9.85, "Это важная археологическая находка." }, { 12.38, "Нам бы очень хотелось иметь одного из идолов, которых некоторые древние знахари Гурубаши использовали в своей магии крови." }, { 21.03, "Ступай в этот \"затонувший город\" и добудь нам такого идола." } } } },
    [97170] = { d = 33.3, g = 1, v = "human-male", n = { m = 386, f = 391 }, c = { m = { { 0.00, "Приветствую, герой!" }, { 1.33, "Похоже, ты уже достаточно опытный искатель приключений, и я могу научить тебя ездить на лошади." }, { 7.80, "Не бесплатно, само собой." }, { 9.56, "Зато после окончания обучения ты получишь у Кати собственный транспорт, а дополнительный можешь докупить потом, если захочешь." }, { 18.09, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 23.17, "Других наставников ищи уже сам." }, { 25.35, "Когда накопишь достаточно денег, поговори со мной, и я обучу тебя всем премудростям езды на лошадях." } }, f = { { 0.00, "Приветствую, героиня!" }, { 1.81, "Похоже, ты уже достаточно опытная искательница приключений, и я могу научить тебя ездить на лошади." }, { 8.85, "Не бесплатно, само собой." }, { 10.61, "Зато после окончания обучения ты получишь у Кати собственный транспорт, а дополнительный можешь докупить потом, если захочешь." }, { 19.14, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 23.77, "Других наставников ищи уже сама." }, { 26.75, "Когда накопишь достаточно денег, поговори со мной, и я обучу тебя всем премудростям езды на лошадях." } } } },
    [97171] = { d = 31.3, g = 1, v = "human-male", n = { m = 385, f = 386 }, c = { m = { { 0.00, "Приветствую!" }, { 0.85, "Хочешь взглянуть на наших лошадей?" }, { 3.22, "Эти скакуны происходят и от старинной лордеронской породы, и от наших местных лошадей." }, { 9.04, "Более надёжного спутника в странствиях тебе не найти." }, { 12.63, "Выбрать будет непросто: все они превосходны и обучены сохранять спокойствие даже в опасности." }, { 18.94, "Не забывай: вам с лошадью вместе странствовать по миру." }, { 22.64, "Какой бы выбор ты ни сделал, он наверняка подойдёт тебе лучше всего." }, { 27.25, "Осмотри лошадей и возвращайся ко мне, когда сделаешь выбор." } }, f = { { 0.00, "Приветствую!" }, { 0.85, "Хочешь взглянуть на наших лошадей?" }, { 3.22, "Эти скакуны происходят и от старинной лордеронской породы, и от наших местных лошадей." }, { 9.04, "Более надёжного спутника в странствиях тебе не найти." }, { 12.63, "Выбрать будет непросто: все они превосходны и обучены сохранять спокойствие даже в опасности." }, { 18.94, "Не забывай: вам с лошадью вместе странствовать по миру." }, { 22.61, "Какой бы выбор ты ни сделала, он наверняка подойдёт тебе лучше всего." }, { 27.45, "Осмотри лошадей и возвращайся ко мне, когда сделаешь выбор." } } } },
    [97173] = { d = 27.2, v = "human-male", n = { x = 332 }, c = { x = { { 0.00, "Фурболги-черночревы в горах над Азшарой взялись за тёмную магию." }, { 4.40, "Примитивный народ, развращённый демонической магией, — для Азерота не новость, но мы с Лан'далоком хотели бы изучить, через что они творят свои чары." }, { 14.57, "Отправляйся в Крепость Черночревов и добудь для нас один из ритуальных тотемов Черночревов." }, { 20.77, "Такие носят только самые могущественные шаманы племени, так что возьми союзников и будь начеку." } } } },
    [97174] = { d = 31.1, g = 1, v = "scourge-male", n = { m = 287, f = 289 }, c = { m = { { 0.00, "Время пришло." }, { 1.22, "Как и при жизни, паладин Отрёкшихся не может считаться полноценным, пока не установит связь с боевым конём." }, { 10.07, "Это не обычный скакун, а могучий дух воздаяния." }, { 14.12, "Поговори с Данитой Морр в крепости Бандариона, чтобы узнать больше." }, { 19.84, "Она подскажет, что делать дальше." }, { 22.74, "Тебя ждёт трудный путь, но, как любят говорить наши союзники-орки, кровь и гром, брат!" } }, f = { { 0.00, "Время пришло." }, { 1.22, "Как и при жизни, паладин Отрёкшихся не может считаться полноценным, пока не установит связь с боевым конём." }, { 10.07, "Это не обычный скакун, а могучий дух воздаяния." }, { 14.12, "Поговори с Данитой Морр в крепости Бандариона, чтобы узнать больше." }, { 19.84, "Она подскажет, что делать дальше." }, { 21.88, "Тебя ждёт трудный путь, но, как любят говорить наши союзники-орки, кровь и гром, сестра!" } } } },
    [97175] = { d = 36.2, v = "scourge-female", n = { x = 322 }, c = { x = { { 0.00, "Ни одно достойное начинание не обходится без жертв, и первое задание требует именно этого." }, { 8.49, "Тебе нужно раздобыть курильницу экзорцизма верховного жреца Зайуса." }, { 14.94, "Пусть она и послужит благой цели, за неё придётся заплатить должную цену." }, { 21.81, "Отправляйся в Оргриммар и поговори с верховным жрецом Зайусом." }, { 27.66, "Зайус потребует..." }, { 29.45, "«пожертвование» за утрату курильницы." }, { 32.93, "В конечном счёте это небольшая цена." } } } },
    [97178] = { d = 36.3, v = "scourge-female", n = { x = 358 }, c = { x = { { 0.00, "Без надлежащего чепрака боевой конь паладина — немногим больше, чем бездумный зверь." }, { 6.96, "Чепрак для твоего коня должен быть не только из лучших материалов, но и пригоден для настройки на мир духов." }, { 15.97, "Неподалёку от Мельницы Таррен живёт кузнец, который уже не раз прекрасно работал для наших паладинов." }, { 24.37, "Это скромный, неприметный орк, но работа у него превосходная и как нельзя лучше подходит для наших нужд." }, { 33.07, "Разыщи его и закажи у него эту работу." } } } },
    [97179] = { d = 28.8, v = "orc-male", n = { x = 304 }, c = { x = { { 0.00, "Для чепрака нам понадобится несколько вещей: рунная ткань для подкладки, арканитовые слитки для пластин, Слёзы Артаса для духовной настройки и святая вода Стратхольма для духовного насыщения." }, { 14.76, "И наконец, я возьму скромную плату за работу, а также за седло и стремена к чепраку." }, { 21.40, "Принеси мне эти материалы, и я закончу твой чепрак." }, { 25.42, "Пока ты собираешь всё это, я займусь седлом." } } } },
    [97188] = { d = 34.6, g = 1, v = "gnome-male", n = { m = 400, f = 405 }, c = { m = { { 0.00, "Приветствую, герой!" }, { 1.32, "Ты уже достаточно опытный искатель приключений, и я могу научить тебя ездить на механодолгоноге." }, { 7.76, "Не бесплатно, само собой." }, { 9.50, "Зато после окончания обучения ты получишь у Милли собственный транспорт, а дополнительный можешь докупить потом, если захочешь." }, { 18.04, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 23.10, "Других наставников ищи уже сам." }, { 25.26, "Когда накопишь достаточно золота, поговори со мной, и я обучу тебя всем премудростям езды на механодолгоногах." } }, f = { { 0.00, "Приветствую, героиня!" }, { 1.80, "Ты уже достаточно опытная искательница приключений, и я могу научить тебя ездить на механодолгоноге." }, { 9.41, "Не бесплатно, само собой." }, { 11.15, "Зато после окончания обучения ты получишь у Милли собственный транспорт, а дополнительный можешь докупить потом, если захочешь." }, { 19.69, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 24.54, "Других наставников ищи уже сама." }, { 27.44, "Когда накопишь достаточно золота, поговори со мной, и я обучу тебя всем премудростям езды на механодолгоногах." } } } },
    [97194] = { d = 37.5, g = 1, v = "orc-male", n = { m = 382, f = 387 }, c = { m = { { 0.00, "Мок-ра, герой!" }, { 1.16, "Ты уже достаточно опытный искатель приключений, и я могу научить тебя ездить на наших волках." }, { 8.31, "Не бесплатно, само собой." }, { 10.29, "Зато после окончания обучения ты получишь у Огунаро собственный транспорт, а дополнительный можешь докупить потом, если захочешь." }, { 20.09, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 25.82, "Других наставников ищи уже сам." }, { 28.27, "Когда накопишь достаточно золота, поговори со мной, и я обучу тебя всем премудростям езды на волках." } }, f = { { 0.00, "Мок-ра, героиня!" }, { 1.62, "Ты уже достаточно опытная искательница приключений, и я могу научить тебя ездить на наших волках." }, { 9.78, "Не бесплатно, само собой." }, { 11.76, "Зато после окончания обучения ты получишь у Огунаро собственный транспорт, а дополнительный можешь докупить потом, если захочешь." }, { 21.56, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 27.24, "Других наставников ищи уже сама." }, { 30.07, "Когда накопишь достаточно золота, поговори со мной, и я обучу тебя всем премудростям езды на волках." } } } },
    [97196] = { d = 36.0, v = "tauren-female", n = { x = 389 }, c = { x = { { 0.00, "В глуби логова иглогривов племени Мёртвой Головы, известном как курганы Иглошкурых, обосновался слуга Короля-лича." }, { 8.96, "Нам известно, что с помощью гадального шара он наблюдает за перемещением своих прислужников и раздаёт им указания." }, { 17.72, "С этим артефактом у нас была бы возможность выслеживать и ликвидировать тайных агентов Плети, тем самым не позволяя им угрожать Калимдору." }, { 28.45, "Отправляйся на курганы Иглошкурых в логово Амненнара Хладовея и забери его сферу – Око Хладовея." } } }, t = { d = 8.1, v = "tauren-female", n = { x = 75 }, c = { x = { { 0.00, "Это отлично подойдёт." }, { 1.94, "Мы лишили врагов важного орудия и обрели мощное оружие против Плети." } } } } },
    [97197] = { d = 32.7, v = "skyborne-female", n = { x = 378 }, c = { x = { { 0.00, "Мулн говорит, что в самых глубинах Чёрной горы есть место, где был повреждён барьер между Азеротом и Обителью стихий, вследствие чего в нашу реальность хлынули мириады стихийных созданий с Огненных Просторов – среди них были даже великаны ростом с опорный столп!" }, { 18.96, "Мне очень хотелось бы поизучать любые остаточные материалы, которые можно собрать с этих существ." }, { 26.11, "Ты отважишься спуститься в Глубины Чёрной горы, чтобы раздобыть для меня подходящий образчик?" } } } },
    [97198] = { d = 31.3, v = "tauren-male", n = { x = 329 }, c = { x = { { 0.00, "Фурболгов-черночревов в горах над Азшарой поразила тёмная, зловещая магия." }, { 5.90, "Мы не знаем, насколько глубока эта порча и как она может сказаться на стихиях в тех краях, но надеемся в этом разобраться." }, { 15.68, "Отправляйся в Крепость Черночревов и добудь для нас один из ритуальных тотемов Черночревов." }, { 22.87, "Такие носят только самые могущественные шаманы племени, так что возьми союзников и готовься к тяжёлому бою." } } } },
    [97200] = { d = 35.6, g = 1, v = "troll-female#75", n = { m = 395, f = 400 }, c = { m = { { 0.00, "Добро пожаловать, герой!" }, { 1.76, "Ты уже достаточно опытный искатель приключений, и я могу обучить тебя ездить на наших ящерах." }, { 8.35, "Не бесплатно, само собой." }, { 10.17, "Зато после окончания обучения ты получишь у Зьольнира собственный транспорт, а дополнительный сможешь докупить потом, если захочешь." }, { 19.40, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 24.67, "Других наставников ищи уже сам." }, { 26.93, "Когда накопишь достаточно золота, поговори со мной, и я обучу тебя всем премудростям езды на ящерах." } }, f = { { 0.00, "Добро пожаловать, героиня!" }, { 2.28, "Ты уже достаточно опытная искательница приключений, и я могу обучить тебя ездить на наших ящерах." }, { 9.70, "Не бесплатно, само собой." }, { 11.52, "Зато после окончания обучения ты получишь у Зьольнира собственный транспорт, а дополнительный сможешь докупить потом, если захочешь." }, { 20.75, "В мире много разных существ, и учиться скакать придётся на каждом отдельно." }, { 25.60, "Других наставников ищи уже сама." }, { 28.74, "Когда накопишь достаточно золота, поговори со мной, и я обучу тебя всем премудростям езды на ящерах." } } } },
