    [97220] = { d = 20.9, v = "human-male", n = { x = 255 }, c = { x = { { 0.00, "На этой неделе у нас постоянно не хватает грузчиков." }, { 3.47, "Не хочешь помочь нам справиться с нагрузкой?" }, { 6.41, "Отнеси это к входу в хранилище вестибюля." }, { 9.22, "Это в магазине \"Сыры Триаса\", на втором этаже." }, { 12.40, "Хозяйка, Илана, привыкла к таким доставкам." }, { 15.33, "В вестибюль часто тайно доставляют грузы, – эдакий ритуальный сюрприз от руководства." } } }, t = { d = 11.8, v = "human-female#112", n = { x = 136 }, c = { x = { { 0.00, "Мамочки мои." }, { 0.97, "Ты думаешь, нам хочется самим тащить это вверх по лестнице?" }, { 5.25, "Доставка ценного груза в целости и сохранности точно по указанному адресу – твоя обязанность." } } } } },
    [97222] = { d = 22.8, g = 1, v = "human-female#112", n = { m = 263, f = 264 }, c = { m = { { 0.00, "Да, да, нужно всего лишь подняться по лестнице." }, { 3.17, "Но раз уж это так просто, то можешь сделать это и сам!" }, { 6.82, "\"Сыры Триаса\" не относятся ни к вестибюлю, ни к его складу." }, { 10.84, "Просто у нас общий этаж." }, { 12.55, "Поставь ящик рядом со входом в хранилище, его, как обычно, заберёт стражник." }, { 17.73, "Он увидит доставку и занесёт её внутрь, когда будет возвращаться на пост." } }, f = { { 0.00, "Да, да, нужно всего лишь подняться по лестнице." }, { 3.21, "Но раз уж это так просто, то можешь сделать это и сама!" }, { 7.03, "\"Сыры Триаса\" не относятся ни к вестибюлю, ни к его складу." }, { 11.10, "Просто у нас общий этаж." }, { 12.83, "Поставь ящик рядом со входом в хранилище, его, как обычно, заберёт стражник." }, { 18.07, "Он увидит доставку и занесёт её внутрь, когда будет возвращаться на пост." } } }, t = { d = 16.1, g = 1, v = "human-female#112", n = { x = 174 }, c = { m = { { 0.00, "Да, у них не просто так дверь открывается внутрь – это чтобы им не перекрыли выход всяким хламом, который оставляют где ни попадя." }, { 8.99, "Теперь мы деловые партнёры, герой." }, { 11.39, "Мы уважаем твою профессию, и взамен ждём уважения к нашей." } }, f = { { 0.00, "Да, у них не просто так дверь открывается внутрь – это чтобы им не перекрыли выход всяким хламом, который оставляют где ни попадя." }, { 9.33, "Теперь мы деловые партнёры, героиня." }, { 11.96, "Мы уважаем твою профессию, и взамен ждём уважения к нашей." } } } } },
    [97223] = { d = 32.4, v = "troll-female#75", n = { x = 350 }, c = { x = { { 0.00, "Всех ящеров, которых ты тут видишь, я объезжала лично." }, { 4.10, "Их собрали со всего Калимдора, но зачастую лучшие ящеры – это кровопалые с островов, что недалеко от наших берегов." }, { 12.86, "Матриарх кровопалых отличается особой свирепостью." }, { 16.68, "Она лишила жизни многих из нашей деревни и стала слишком опасной, чтобы оставлять её у нас на границе." }, { 24.55, "Если сможешь убить её, то принеси мне её яйца – так мы сможем вырастить вылупившихся ящеров как союзников." } } }, t = { d = 11.4, g = 1, v = "troll-female#75", n = { m = 116, f = 117 }, c = { m = { { 0.00, "Спасибо." }, { 0.72, "Я рада, что мы сможем сохранить породу и вырастить этих ящеров, сделав их нашими союзниками." }, { 8.12, "Ты оказал нашему племени большую услугу." } }, f = { { 0.00, "Спасибо." }, { 0.72, "Я рада, что мы сможем сохранить породу и вырастить этих ящеров, сделав их нашими союзниками." }, { 8.19, "Ты оказала нашему племени большую услугу." } } } } },
    [97225] = { d = 35.0, v = "troll-male", n = { x = 359 }, c = { x = { { 0.00, "Когда мы бежали с островов, которые захватил Залазан и ему подобные, нам пришлось бросить много драгоценных идолов." }, { 9.21, "Они помогали нам общаться с духами, которым мы поклоняемся, – нашими лоа." }, { 15.06, "Для нашего племени они невероятно ценны." }, { 18.34, "Последователи Залазана не почитают наших лоа и разбросали идолов по самому крупному из островов." }, { 25.98, "Если мы не соберём их, жди беды – оскорблять лоа нельзя." }, { 30.40, "Иди и собери как можно больше идолов лоа и принеси их мне." } } }, t = { d = 18.1, g = 1, v = "troll-male#77", n = { m = 186, f = 187 }, c = { m = { { 0.00, "Ты сегодня сделал для нашего племени подвиг." }, { 3.65, "В отличие от некоторых других племён, наша связь с лоа основывается на почитании и уважении, и мы им многим обязаны." }, { 12.90, "Не хотелось бы, чтоб племя Чёрного Копья утратило их расположение." } }, f = { { 0.00, "Ты сегодня сделала для нашего племени подвиг." }, { 3.69, "В отличие от некоторых других племён, наша связь с лоа основывается на почитании и уважении, и мы им многим обязаны." }, { 12.87, "Не хотелось бы, чтоб племя Чёрного Копья утратило их расположение." } } } } },
    [97234] = { d = 21.6, v = "human-male", n = { x = 265 }, c = { x = { { 0.00, "Ты здесь, чтобы обсудить тайный смысл наших легенд?" }, { 3.49, "Нет?" }, { 3.80, "Что ж, когда закончишь осматриваться, можешь отнести вот это в библиотеку?" }, { 8.82, "Мы обмениваем некоторые менее популярные работы на более современные книги." }, { 13.96, "У меня есть список фолиантов, которые можно достать в библиотеке." }, { 18.43, "Если поможешь, угостим тебя напитком бесплатно." } } }, t = { d = 23.2, v = "human-male", n = { x = 246 }, c = { x = { { 0.00, "Так, посмотрим." }, { 1.16, "Что, тебя прислали из книжного клуба Роя?" }, { 4.35, "Узнаю их технику упаковки." }, { 6.40, "Что ж, если люди хотят обсуждать именно это, то я не против." }, { 11.02, "Всё, что мы им передаём, возвращается назад в целости и сохранности, а значит, члены клуба обращаются с книгами уважительно, даже если в них высказаны спорные идеи." } } } } },
    [97236] = { d = 12.2, v = "narrator", n = { x = 125 }, c = { x = { { 0.00, "Свежий образец от паука таких размеров – настоящая находка." }, { 5.00, "Возможно, этим клыком заинтересуется кто-то, занимающийся изучением пауков в Альдрассиле." } } }, t = { d = 7.8, v = "nightelf-male#55", n = { x = 79 }, c = { x = { { 0.00, "Надо же!" }, { 0.75, "Обожаю сюрпризы." }, { 2.17, "Вне всяких сомнений, этот экземпляр пригодится для моих исследований." } } } } },
    [97237] = { d = 28.4, v = "human-male", n = { x = 356 }, c = { x = { { 0.00, "Я проверил записи, и все книги, которые попросил господин Льюэлс, сейчас доступны." }, { 5.48, "Тебе, правда, придётся самостоятельно взять их с полок." }, { 9.06, "Работа библиотекаря – следить за библиотекой, и я не могу отвлекаться." }, { 13.64, "Также уведомляю, что ты не будешь отвечать за возврат книг, которые доставишь Рою." }, { 19.07, "В записке говорится, что ты сейчас официально являешься курьером книжного клуба, а значит, вся ответственность будет лежать на нём." }, { 27.65, "Хорошего дня." } } }, t = { d = 17.9, g = 1, v = "human-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Это они!" }, { 0.73, "Некоторые даже пахнут экзотикой!" }, { 3.17, "Великолепно, жду не дождусь оживлённых бесед об этих сочинениях." }, { 7.78, "В погребе, после закрытия, разумеется." }, { 10.62, "Спасибо, что так быстро обернулся." }, { 13.13, "Как и обещали, угощение за счёт заведения." }, { 16.16, "Мы своё слово держим." } }, f = { { 0.00, "Это они!" }, { 0.74, "Некоторые даже пахнут экзотикой!" }, { 3.21, "Великолепно, жду не дождусь оживлённых бесед об этих сочинениях." }, { 7.90, "В погребе, после закрытия, разумеется." }, { 10.77, "Спасибо, что так быстро обернулась." }, { 13.38, "Как и обещали, угощение за счёт заведения." }, { 16.46, "Мы своё слово держим." } } } } },
    [97242] = { d = 27.0, v = "orc-male#127", n = { x = 290 }, c = { x = { { 0.00, "Йелмак хочет, чтобы его ученик наконец-то перестал всё портить." }, { 4.78, "Он сказал, что его подмастерье слишком горд, чтобы попросить о помощи, даже когда она ему необходима." }, { 12.36, "И хочет дать ему попробовать кое-какое наше зелье." }, { 16.21, "Срежь камыш и копьё-траву, растущие у воды на Аллее Чести." }, { 20.53, "Я бы и сам мог это сделать, но если я уйду из магазина, Вуут наверняка что-то заподозрит." } } }, t = { d = 21.1, v = "orc-male#127", n = { x = 242 }, c = { x = { { 0.00, "Эти виды камыша и копьё-травы растут только в Оргриммаре." }, { 4.20, "Благодаря горной родниковой воде из Азшары и местной минеральной пыли, пропитанной потом и кровью, эти травы обрели мощные свойства." }, { 13.98, "Я передам их Йелмаку, чтобы тот провёл демонстрацию для Вуута и наконец-то заставил его прислушаться." } } } } },
    [97243] = { d = 28.5, v = "skyborne-female#3773", n = { x = 286 }, c = { x = { { 0.00, "Хотя мы в Небесной выси, это всё ещё обитель стихий." }, { 4.26, "Духи всех четырёх стихий говорят с нами, если мы готовы слушать." }, { 9.45, "Один из нас, Ваятелей ветра, находится в особенно крепкой связи со стихией огня – шен'дорай по имени Олариан Быстрая Вспышка." }, { 19.54, "Отнеси это ему в святилище пламени в Ветроягодных низинах." }, { 24.30, "Оно находится на краю острова, к западу от Валанаара." } } }, t = { d = 12.6, g = 1, v = "skyborne-male", n = { m = 113, f = 117 }, c = { m = { { 0.00, "Ты принёс факел." }, { 1.36, "Да, юный шаман, я могу научить тебя слышать зов огня." }, { 5.97, "Будет непросто, но ничто из того, что мы делаем в этом мире, не даётся легко." } }, f = { { 0.00, "Ты принесла факел." }, { 1.57, "Да, юная шаманка, я могу научить тебя слышать зов огня." }, { 6.28, "Будет непросто, но ничто из того, что мы делаем в этом мире, не даётся легко." } } } } },
    [97244] = { d = 34.8, v = "skyborne-male", n = { x = 367 }, c = { x = { { 0.00, "Среди ал'акетов есть жрец небес по имени Фаладиэль." }, { 3.98, "Когда-то он был призывателем пламени и верным Ваятелем ветра, но, как и многие ал'акеты, променял верность на могущество." }, { 13.28, "Теперь его руки запятнаны кровью бывших братьев и сестёр." }, { 17.82, "Ты найдёшь жреца небес Фаладиэля на ферме к северо-востоку, за Валанааром, чуть к югу от святилища Акира." }, { 25.93, "Убей этого предателя." }, { 27.68, "Принеси мне его сердце." }, { 29.57, "Дело грязное, но необходимое для ритуала, который мы должны провести." } } }, t = { d = 20.9, v = "skyborne-male", n = { x = 231 }, c = { x = { { 0.00, "Ваятели ветра ничего не забывают, а за кровь у нас принято расплачиваться кровью." }, { 6.06, "Мне приятно, что благодаря тебе предатель получил это последнее напоминание о наших принципах." }, { 13.20, "Но его сердце будет не единственной пищей для пламени." }, { 17.35, "Есть ещё одно дело, с которым нужно разобраться." } } } } },
    [97245] = { d = 32.2, v = "skyborne-male", n = { x = 330 }, c = { x = { { 0.00, "Обитатели Шен'дарского нагорья рассказывают о древнем лесном духе по имени Курамаа." }, { 6.65, "Говорят, он живёт в пне на вершине холма, рядом с опорным столпом." }, { 11.87, "Отправляйся на нагорье и отыщи этот пень." }, { 15.15, "Постучи по нему кулаком, и Курамаа явится." }, { 18.59, "Одолей духа в бою и принеси мне его деревянную маску." }, { 22.95, "Но имей в виду: это существо будет невосприимчиво к большей части твоей магии." }, { 29.31, "Лишь прикосновение огня упокоит духа." } } }, t = { d = 7.1, v = "skyborne-male", n = { x = 63 }, c = { x = { { 0.00, "У нас есть всё, что нужно." }, { 2.32, "Теперь мы зажжём вечное пламя и воззовём к духам огня." } } } } },
    [97246] = { d = 36.4, v = "orc-male#60", n = { x = 414 }, c = { x = { { 0.00, "Мой сын Миги целыми днями играет со своими друзьями." }, { 3.72, "Постоянно говорю ему, чтобы не забыл забрать у Борстана свой обед, но знаю наверняка, что он этого почти никогда не делает, потому что приходит домой голодным." }, { 14.96, "Вот ведь дети пошли – думают, будто игры важнее, чем здоровое питание!" }, { 19.94, "Прошу, зайди в \"Жаровню Борстана\" и скажи, что доставишь обед Миги." }, { 24.74, "Самого Миги ты почти наверняка найдёшь за крепостью Громмаш, как и всех его друзей." }, { 30.55, "У меня здесь много работы, поэтому я не могу каждый раз следить, пообедал он или нет." } } }, t = { d = 21.1, v = "orc-male", n = { x = 228 }, c = { x = { { 0.00, "Всё верно, мы с родителями Миги договорились, что я буду каждый день передавать ему готовый обед." }, { 7.25, "Но не могу же я сделать так, чтобы мальчишка получил свою еду, если он за ней не приходит." }, { 13.95, "Иногда он по несколько дней в неделю тут не появляется." }, { 17.98, "Откуда у него только берутся силы на игры?" } } } } },
    [97249] = { d = 36.2, v = "orc-male", n = { x = 425 }, c = { x = { { 0.00, "Теперь, когда я узнал, что родители Миги беспокоятся о его питании, у меня появилась идея." }, { 6.30, "Мы с ними договорились, что я не буду готовить для него одно и то же каждый день, чтобы он привыкал к разнообразной пище." }, { 14.52, "Но он всегда приходит в одно и то же время: когда коптильня полна мяса и мы делаем бутерброды со свиной грудинкой в сладкой глазури." }, { 23.60, "Мы начали крошить остатки мяса в хрустящей глазури – этим можно посыпать другие блюда хоть каждый день." }, { 30.76, "Отнеси ему." }, { 31.63, "Может быть, тогда он будет приходить пораньше и звать с собой друзей!" } } }, t = { d = 32.6, g = 1, v = "child-male", n = { m = 349, f = 353 }, c = { m = { { 0.00, "Мясо от Борстана?" }, { 1.33, "Ты принёс это кому-то из нас?" }, { 3.46, "О!" }, { 3.66, "Ого... как здорово пахнет!" }, { 5.66, "Вкуснятина." }, { 6.53, "Спасибо, что принёс мой обед." }, { 8.66, "Я могу по запаху определить, что Борстан будет готовить сегодня, когда мы с друзьями идём мимо по пути к крепости Громмаш." }, { 17.72, "Это похоже на мою любимую сладкую глазурь!" }, { 20.98, "Но... как-то по-другому." }, { 22.78, "Мне очень нравятся эти кусочки." }, { 25.18, "Если он будет каждый день делать такую вкуснятину, нам придётся прерывать игру, чтобы вместе обедать!" } }, f = { { 0.00, "Мясо от Борстана?" }, { 1.31, "Ты принесла это кому-то из нас?" }, { 3.60, "О!" }, { 3.80, "Ого... как здорово пахнет!" }, { 5.76, "Вкуснятина." }, { 6.61, "Спасибо, что принесла мой обед." }, { 8.91, "Я могу по запаху определить, что Борстан будет готовить сегодня, когда мы с друзьями идём мимо по пути к крепости Громмаш." }, { 17.81, "Это похоже на мою любимую сладкую глазурь!" }, { 21.02, "Но... как-то по-другому." }, { 22.79, "Мне очень нравятся эти кусочки." }, { 25.15, "Если он будет каждый день делать такую вкуснятину, нам придётся прерывать игру, чтобы вместе обедать!" } } } } },
    [97250] = { d = 30.3, v = "orc-male#60", n = { x = 315 }, c = { x = { { 0.00, "Ты случайно не путешествуешь к Пылевым топям?" }, { 3.56, "До меня дошли слухи, что несколько солдат-людей заняли позицию на их границе и громят памятные места, которые остались со времён тауренов-первопроходцев." }, { 15.66, "Говорят, они сожгли дотла знаменитую таверну." }, { 19.36, "А потом по-альянсовски свалили вину на Орду!" }, { 22.92, "Не знаю, сколько тут правды, но я не потерплю вторжения на НАШИ земли." }, { 28.48, "Сначала казнь, потом суд!" } } }, t = { d = 33.0, v = "orc-male#60", n = { x = 345 }, c = { x = { { 0.00, "Так слухи не врали!" }, { 1.55, "Чему удивляться – на восточном берегу давно росло напряжение." }, { 6.42, "Ясно было, что рано или поздно стычки перекинутся на нашу территорию." }, { 12.00, "Но мне сложно поверить, что мы принимали участие в поджоге таверны." }, { 17.23, "Очень многие путники и торговцы из Орды посещают её по дороге." }, { 22.17, "Может, найдёшь время и займёшься расследованием поплотнее?" }, { 26.62, "В любом случае, сегодня Орда одержала победу, а Альянс убежал с поджатым хвостом!" } } } } },
    [97253] = { d = 34.0, v = "goblin-male", n = { x = 407 }, c = { x = { { 0.00, "Эй, на минутку." }, { 1.04, "Короче говоря, у нас проблема с пиратами." }, { 3.85, "Кого я только ни посылал с ними разобраться – никто не вернулся назад." }, { 8.69, "Тогда я подумал: а если послать машину?" }, { 11.44, "Оказалось, ятаганы раскручивают запчасти не сильно хуже отвёрток." }, { 15.85, "Не успел я направить машину домой, как она превратилась в кучу железок и разлетелась по всему их лагерю!" }, { 22.94, "Мне нужно вернуть детали." }, { 24.72, "Причём это всего лишь коротенькая вылазка за трофеями, так что твои шансы на выживание наверняка НАМНОГО выше, чем в предыдущие разы." }, { 33.71, "Ну чё?" } } }, t = { d = 19.3, g = 1, v = "goblin-male", n = { m = 196, f = 198 }, c = { m = { { 0.00, "Ого-о-о!" }, { 0.68, "Вот это здорово!" }, { 1.97, "Ты спас меня от очередной занудной лекции Заглушестера о том, как дорого стоит металл." }, { 8.42, "А что ещё важнее, теперь я могу сразу начать собирать следующий прототип." }, { 13.99, "Э-э..." }, { 14.53, "А вот награду я для тебя и не подготовил..." }, { 17.73, "Любишь коробки?" } }, f = { { 0.00, "Ого-о-о!" }, { 0.69, "Вот это здорово!" }, { 2.00, "Ты спасла меня от очередной занудной лекции Заглушестера о том, как дорого стоит металл." }, { 8.75, "А что ещё важнее, теперь я могу сразу начать собирать следующий прототип." }, { 14.40, "Э-э..." }, { 14.95, "А вот награду я для тебя и не подготовил..." }, { 18.19, "Любишь коробки?" } } } } },
    [97257] = { d = 28.2, v = "skyborne-male", n = { x = 289 }, c = { x = { { 0.00, "Теперь мы проведём ритуал." }, { 2.07, "Я помещу всё необходимое на алтарь и воззову к духам огня." }, { 6.70, "Если они примут наше подношение, то явятся и зажгут Вечное пламя." }, { 12.05, "Тогда тебе нужно будет поднести к нему свой факел." }, { 16.19, "Отнеси зажжённый факел в Валанаар и помести его в жаровню Вечного пламени." }, { 22.11, "Но поторопись – пламя Огненных Просторов быстро гаснет здесь, в Небесной выси." } } }, t = { d = 24.1, v = "skyborne-female#3773", n = { x = 221 }, c = { x = { { 0.00, "Готово." }, { 0.72, "Вечное пламя полыхает вновь." }, { 3.26, "Твоё испытание окончено, и я с радостью передаю тебе твой тотем огня." }, { 9.38, "Используй его с умом в своих странствиях." }, { 13.11, "И помни: огонь обители стихий служит тем, кто обращается с ним уважительно, и пожирает тех, кто этого не делает." }, { 22.89, "Таков наш путь." } } } } },
    [97263] = { d = 16.6, v = "gnome-male", n = { x = 0 }, c = { x = { { 0.00, "*У почтового ящика лежит несколько потерянных посылок.*" }, { 4.16, "*Вы замечаете, что одна из них помечена как предназначенная для доставки из Заоблачного пика в Стальгорн и адресована Элдруну Тучегону.*" }, { 14.29, "*На посылке стоит штамп \"срочно\".*" } } }, t = { d = 31.6, g = 1, v = "dwarf-male", n = { m = 331, f = 333 }, c = { m = { { 0.00, "Как так!" }, { 0.62, "А я всё жду эту посылку, каждый день хожу к почтовому ящику!" }, { 5.21, "Этому городу срочно требуется перепланировка." }, { 8.71, "Здесь гораздо сложнее ориентироваться, чем в Заоблачном пике!" }, { 13.30, "Посмотрим, что тут у нас..." }, { 15.29, "Инструменты для вырезания тотемов..." }, { 18.03, "Запасной топор..." }, { 19.41, "Какое-то гоблинское устройство?" }, { 21.81, "Я этого не заказывал!" }, { 23.45, "Ладно, я просто отправлю его обратно." }, { 26.40, "Ну-у... то есть... спасибо, что всё это мне принёс." }, { 30.17, "Вот тебе за хлопоты." } }, f = { { 0.00, "Как так!" }, { 0.61, "А я всё жду эту посылку, каждый день хожу к почтовому ящику!" }, { 5.11, "Этому городу срочно требуется перепланировка." }, { 8.54, "Здесь гораздо сложнее ориентироваться, чем в Заоблачном пике!" }, { 13.05, "Посмотрим, что тут у нас..." }, { 15.00, "Инструменты для вырезания тотемов..." }, { 17.69, "Запасной топор..." }, { 19.04, "Какое-то гоблинское устройство?" }, { 21.39, "Я этого не заказывал!" }, { 23.01, "Ладно, я просто отправлю его обратно." }, { 25.90, "Ну-у... то есть... спасибо, что всё это мне принесла." }, { 29.80, "Вот тебе за хлопоты." } } } } },
    [97264] = { d = 32.7, v = "tauren-female", n = { x = 319 }, c = { x = { { 0.00, "Щербозубы с каждым сезоном становятся всё бешенее." }, { 4.16, "Они соперничают друг с другом и с другими хищниками этих краёв за те скудные источники пищи, до которых могут добраться." }, { 14.03, "Всё чаще они нападают на нас: в лютый холод голод делает их злее." }, { 19.52, "Этих медведей много, и они упрямы." }, { 22.49, "Если их станет меньше, оставшиеся семьи станут сильнее, чем когда-либо." }, { 28.42, "Помоги им уйти с миром." }, { 30.43, "Избавь стаю от самых старых." } } } },
    [97265] = { d = 39.0, g = 1, v = "troll-male", n = { m = 405, f = 406 }, c = { m = { { 0.00, "Когда-нибудь заключал сделку с сатиром?" }, { 3.12, "Мне вот однажды довелось." }, { 5.10, "И как можно было отказаться?" }, { 7.37, "Мне пообещали могущество и знания, каких не получишь из простой книги." }, { 12.90, "А заодно – собственного прислужника." }, { 15.73, "Чего ещё просить?" }, { 17.15, "Всё враньё, конечно." }, { 18.71, "Они никогда не склонились бы перед смертным." }, { 22.25, "У меня ничего не было, когда мы ударили по рукам, а в результате я потерял ещё больше." }, { 29.06, "Теперь я хочу отомстить племени Ярой Ненависти." }, { 32.88, "Напади на их лагерь к северо-востоку!" }, { 35.86, "Пусть земля окрасится их зловонной кровью." } }, f = { { 0.00, "Когда-нибудь заключала сделку с сатиром?" }, { 3.18, "Мне вот однажды довелось." }, { 5.15, "И как можно было отказаться?" }, { 7.41, "Мне пообещали могущество и знания, каких не получишь из простой книги." }, { 12.92, "А заодно – собственного прислужника." }, { 15.74, "Чего ещё просить?" }, { 17.16, "Всё враньё, конечно." }, { 18.71, "Они никогда не склонились бы перед смертным." }, { 22.24, "У меня ничего не было, когда мы ударили по рукам, а в результате я потерял ещё больше." }, { 29.02, "Теперь я хочу отомстить племени Ярой Ненависти." }, { 32.83, "Напади на их лагерь к северо-востоку!" }, { 35.79, "Пусть земля окрасится их зловонной кровью." } } } },
    [97270] = { d = 9.5, v = "narrator", n = { x = 104 }, c = { x = { { 0.00, "Наверняка Ристалище скрывает что-то ещё!" }, { 3.09, "Может быть, это знает громогласный Зритель, который следит за боями в Забытом Городе!" } } } },
    [97275] = { d = 36.7, v = "orc-male", n = { x = 386 }, c = { x = { { 0.00, "У Вуута есть талант, это бесспорно." }, { 2.81, "Но ему не хватает опыта, мудрости и практики в работе у котла." }, { 7.73, "Он думает, что может делать всё по-своему." }, { 11.03, "Вуут расходует все редкие и экзотические ингредиенты, которые у нас есть, вместо того чтобы тренироваться и оттачивать базовые навыки." }, { 21.42, "Я тут по-быстрому приготовил одно снадобье." }, { 24.79, "Пожалуйста, отнеси его Вууту." }, { 27.18, "Он задумается, всё ли делает правильно, когда поймёт, что первейший ключ к мастерству – это знание местных трав и осторожность." } } }, t = { d = 29.4, g = 1, v = "orc-male", n = { m = 299, f = 299 }, c = { m = { { 0.00, "Грорру... чего?" }, { 1.26, "Говоришь, Йелмак сварил это зелье из копьё-травы, камыша... и всё?" }, { 6.43, "А я и не знал, что в алхимии можно использовать такие простые травы." }, { 11.67, "Может быть, он прав." }, { 13.21, "Что, если я действительно многое упускаю, работая только с самыми редкими и малоизученными растениями?" }, { 21.10, "Можешь выбрать любое из этих зелий, которые я сварил ранее." }, { 25.86, "Спасибо, что нашёл время зайти в наш магазин." } }, f = { { 0.00, "Грорру... чего?" }, { 1.27, "Говоришь, Йелмак сварил это зелье из копьё-травы, камыша... и всё?" }, { 6.47, "А я и не знал, что в алхимии можно использовать такие простые травы." }, { 11.74, "Может быть, он прав." }, { 13.28, "Что, если я действительно многое упускаю, работая только с самыми редкими и малоизученными растениями?" }, { 21.23, "Можешь выбрать любое из этих зелий, которые я сварил ранее." }, { 26.01, "Спасибо, что нашла время зайти в наш магазин." } } } } },
    [97277] = { d = 38.2, v = "dwarf-male", n = { x = 428 }, c = { x = { { 0.00, "Я отвернулся проследить за тем, как дожаривается вепрь, и тут мой приятель Гозвин завопил как резаный!" }, { 7.28, "А когда развернулся, успел разглядеть только расплывчатое пятно и жуткие клыки." }, { 13.17, "А ещё лапищи – здоровенные такие!" }, { 15.61, "Это снежный леопард утаскивал моего друга." }, { 18.86, "Я тут же схватил дробовик и выстрелил над головой у зверя." }, { 23.09, "Тот выпустил Гозвина и убежал." }, { 25.34, "К счастью, бедняга отделался лишь парой глубоких порезов." }, { 29.57, "Сходи-ка в наш лагерь на северо-западных холмах и принеси его журнал механика." }, { 35.40, "А если попадётся тот леопард, убей его!" } } }, t = { d = 21.7, g = 1, v = "dwarf-male", n = { m = 243, f = 245 }, c = { m = { { 0.00, "Так и знал, что леопард захочет полакомиться нашим жареным вепрем!" }, { 4.58, "Теперь, когда журнал у него, Гозвин будет поменьше волноваться." }, { 9.10, "Надеюсь, эта малая радость поможет ему встать на ноги." }, { 12.99, "Спасибо." }, { 13.62, "Прими этот пустяк в знак моей благодарности – за то, что сходил за журналом и сделал эти холмы безопаснее." } }, f = { { 0.00, "Так и знал, что леопард захочет полакомиться нашим жареным вепрем!" }, { 4.73, "Теперь, когда журнал у него, Гозвин будет поменьше волноваться." }, { 9.39, "Надеюсь, эта малая радость поможет ему встать на ноги." }, { 13.41, "Спасибо." }, { 14.05, "Прими этот пустяк в знак моей благодарности – за то, что сходила за журналом и сделала эти холмы безопаснее." } } } } },
    [97279] = { d = 39.3, v = "orc-male#60", n = { x = 440 }, c = { x = { { 0.00, "С наплывом новобранцев вроде тебя нам стало трудно обеспечивать всех оружием." }, { 5.65, "У нашего оружейника, Кзана, заканчивается запас учебного оружия, и я хочу узнать, какие у тебя есть навыки, чтобы понять, с кем приходится иметь дело." }, { 16.69, "К счастью для тебя, я знаю, как разом решить оба этих вопроса." }, { 21.36, "Пока набиваешь кулаки на кабанах, найди шесть образцов брошенного тренировочного оружия." }, { 27.80, "Они так и остались валяться на земле, брошенные бестолковыми новобранцами." }, { 33.18, "Как только сделаешь это, верни их нашему оружейнику Кзану – он в Логове позади меня." } } }, t = { d = 6.6, g = 1, v = "orc-male", n = { m = 70, f = 71 }, c = { m = { { 0.00, "Спасибо, что вернул оружие." }, { 2.24, "Я займусь его починкой для следующей группы новобранцев." } }, f = { { 0.00, "Спасибо, что вернула оружие." }, { 2.29, "Я займусь его починкой для следующей группы новобранцев." } } } } },
    [97281] = { d = 26.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Перед вами странная сфера с тусклой поверхностью." }, { 4.04, "Приподняв её, вы чувствуете ритмичные электрические импульсы." }, { 8.88, "При ближайшем рассмотрении кажется, что внутри клубится тёмный туман и время от времени мелькают маленькие искры." }, { 17.91, "Совершенно ясно, что гарпия использовала эту сферу для какой-то цели." }, { 23.54, "Возможно, эта вещь заинтересует Резлака." } } }, t = { d = 8.7, v = "goblin-male", n = { x = 87 }, c = { x = { { 0.00, "Ух ты!" }, { 0.50, "И откуда у тебя такая классная штука?" }, { 3.58, "Знаешь, я тут вспомнил, что ещё мне постоянно твердил босс Газлоу..." } } } } },
    [97282] = { d = 30.4, v = "goblin-male", n = { x = 351 }, c = { x = { { 0.00, "\"Резлак, никогда не упускай подвернувшейся возможности\"." }, { 3.98, "Этой мудрости меня научил Газлоу, и я собираюсь воспользоваться его советом." }, { 9.50, "Похоже, эта сфера цела – просто разрядилась." }, { 12.77, "Но у меня есть мыслишка, как восстановить её мощь!" }, { 16.23, "В ущелье к западу отсюда водится много рокочущих ящериц." }, { 20.34, "У них есть органы, удерживающие сильный электрический заряд, и они идеально подходят для наших целей." }, { 27.53, "Сходи собери органы ящериц и принеси мне!" } } }, t = { d = 21.0, g = 1, v = "goblin-male", n = { m = 231, f = 232 }, c = { m = { { 0.00, "Спасибо, приятель!" }, { 1.36, "Я очень ценю твою помощь." }, { 3.31, "Надеюсь, мне удастся всё зарядить с помощью этих органов." }, { 7.46, "Никчёмные гарпии ещё дважды подумают, прежде чем снова нападать на мой караван." }, { 13.10, "Очень надеюсь, что всё получится." }, { 15.50, "Как бы там ни было, свою часть сделки ты выполнил." }, { 19.07, "Вот тебе за старания." } }, f = { { 0.00, "Спасибо, приятель!" }, { 1.39, "Я очень ценю твою помощь." }, { 3.37, "Надеюсь, мне удастся всё зарядить с помощью этих органов." }, { 7.61, "Никчёмные гарпии ещё дважды подумают, прежде чем снова нападать на мой караван." }, { 13.37, "Очень надеюсь, что всё получится." }, { 15.81, "Как бы там ни было, свою часть сделки ты выполнила." }, { 19.52, "Вот тебе за старания." } } } } },
    [97284] = { d = 28.8, g = 1, v = "nightelf-male", n = { m = 298, f = 300 }, c = { m = { { 0.00, "Если Малем ещё жива, то подозреваю, что орки из клана Пылающего Клинка ждут, что кто-нибудь за ней скоро явится." }, { 8.47, "Они точно будут готовы к бою." }, { 10.86, "Я бы предпочёл, чтобы ты не высовывался и не вставал у них на пути, но боюсь, они сами будут постоянно искать схватки с тобой." }, { 20.35, "Что ж, давай и мы сразу займёмся тем же." }, { 23.28, "Убей как можно больше воинов из их числа, а я тебе за это хорошо заплачу." } }, f = { { 0.00, "Если Малем ещё жива, то подозреваю, что орки из клана Пылающего Клинка ждут, что кто-нибудь за ней скоро явится." }, { 8.40, "Они точно будут готовы к бою." }, { 10.77, "Я бы предпочёл, чтобы ты не высовывалась и не вставала у них на пути, но боюсь, они сами будут постоянно искать схватки с тобой." }, { 20.33, "Что ж, давай и мы сразу займёмся тем же." }, { 23.24, "Убей как можно больше воинов из их числа, а я тебе за это хорошо заплачу." } } } },
    [97286] = { t = { d = 6.7, v = "human-male", n = { x = 76 }, c = { x = { { 0.00, "Твои действия доказывают, что ты уважаешь знания." }, { 3.78, "Лаборатория открыта для твоих изысканий." } } }, npc = { [211022] = { d = 8.0, v = "scourge-male", n = { x = 76 }, c = { x = { { 0.00, "Твои действия доказывают, что ты уважаешь знания." }, { 4.49, "Лаборатория открыта для твоих изысканий." } } } } } } },
    [97287] = { d = 39.6, v = "scourge-male#82", n = { x = 383 }, c = { x = { { 0.00, "Хорошо, что тебе удалось проникнуть в город магов, но думаю, что нам пора... начинать переговоры." }, { 8.26, "Не хочется это признавать, но на Азероте нет лучшего кладезя чародейских знаний, чем Даларан." }, { 16.13, "Даже мой гениальный труд не идёт в сравнение с древней мудростью, накопленной Кирин-Тором за долгие годы." }, { 24.92, "Пора и нам приобщиться к тайнам этого закрытого ордена, не так ли?" }, { 30.51, "Возьми найденную тобой частицу." }, { 33.26, "Они несомненно согласятся на что угодно, лишь бы вернуть её." }, { 38.30, "Буквально на всё." } } } },
    [97288] = { d = 16.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Когда существо обрушивается на землю, его голова отделяется от тела." }, { 5.11, "Похоже, её присоединяли уже несколько раз, и с каждым разом связь становилась слабее." }, { 11.35, "Кто-нибудь в Подгороде наверняка знает что-то об этом необычном поганище." } } }, t = { d = 12.9, v = "scourge-male", n = { x = 98 }, c = { x = { { 0.00, "Ага!" }, { 0.56, "Кажется, я узнаю эту голову." }, { 3.66, "Это шутка нашей Тёмной Госпожи, изысканная в своей жестокости." }, { 10.24, "Думаю, мне это пригодится." } } } } },
    [97289] = { d = 39.8, v = "scourge-male", n = { x = 376 }, c = { x = { { 0.00, "Мы регулярно изготавливаем головы поганищ, но эта особенная." }, { 5.34, "Когда-то она принадлежала особенно мерзкому главнокомандующему из Альянса." }, { 11.87, "Кажется, его звали Отмар." }, { 14.26, "Тёмная Госпожа лично его прикончила." }, { 17.53, "Если бы эта голова могла говорить, она бы поведала нам множество интересных тайн!" }, { 24.78, "И мы предоставим ей такую возможность." }, { 28.13, "Нужно лишь присоединить голову к подходящему телу." }, { 32.59, "Положи её рядом со свободным телом в соседней комнате." }, { 37.45, "Но не присоединяй." }, { 39.04, "Пока что." } } }, t = { d = 9.8, v = "named/271613", n = { x = 2 }, c = { x = { { 0.00, "*Тело вздрагивает и оживает.*" }, { 2.40, "*Его охватывает паника – оно снова переживает последние мгновения своей жизни.*" }, { 9.12, "Ты..." } } } } },
    [97290] = { d = 7.0, v = "named/271613", n = { x = 34 }, c = { x = { { 0.00, "Ты... чудовище..." }, { 2.20, "С чего бы... помогать тебе..." }, { 6.03, "Прочь..." } } }, t = { d = 5.8, v = "scourge-male", n = { x = 39 }, c = { x = { { 0.00, "Что, сопротивляемся?" }, { 2.50, "Отлично." }, { 3.64, "Я люблю трудности." } } } } },
    [97291] = { d = 40.0, v = "scourge-male", n = { x = 411 }, c = { x = { { 0.00, "Теперь, когда мы вернули чудищу голову, осталось лишь подчинить его воле Тёмной Госпожи." }, { 7.16, "Это несложно." }, { 8.32, "Оно и так уже почти ничего не соображает после стольких трёпок." }, { 13.46, "Нужно лишь дать ему мотивацию." }, { 15.92, "Принеси мне ядовитую черепоганку от госпожи Гризетт из Торгового квартала." }, { 21.85, "Ещё жгуч-траву от Альестаров, местных учителей травничества." }, { 26.62, "У них передо мной должок, так что траву тебе дадут бесплатно." }, { 31.54, "Ну и наконец нужно немного субстанции агонии." }, { 35.23, "Её можно найти у любого торговца ядами." }, { 38.49, "Будем варить зелье!" } } }, t = { d = 12.1, v = "scourge-male", n = { x = 103 }, c = { x = { { 0.00, "Отлично, это подойдёт." }, { 2.20, "Посмотрим, останется ли у нашего почтенного гостя хоть капля бравады, когда он отведает моего шедевра." } } } } },
    [97292] = { d = 26.5, v = "scourge-male", n = { x = 247 }, c = { x = { { 0.00, "Я приготовил замечательную сыворотку, которая непременно подарит нашему гостю... острые ощущения." }, { 8.69, "Держи." }, { 9.34, "Подлей это в механизм у него над головой." }, { 13.12, "Попробуем продемонстрировать, почему в его интересах – верно служить нам." }, { 19.64, "И постарайся не пролить." }, { 21.81, "Поиски нового помощника обойдутся мне слишком дорого." } } }, t = { d = 17.9, v = "scourge-male", n = { x = 155 }, c = { x = { { 0.00, "Отлично." }, { 0.85, "Пока что оставим его томиться." }, { 3.80, "Пусть попривыкнет к новому дому." }, { 6.85, "Пока что мне больше не нужно это ничтожество, но мы будем за ним присматривать." }, { 14.28, "У меня большие планы на будущее Отмара." } } } } },
    [97319] = { d = 21.1, v = "scourge-male", n = { x = 198 }, c = { x = { { 0.00, "Мой кузен на Калимдоре прорубает себе путь через самые опасные места, и, по последним вестям, направляется на гору Хиджал." }, { 10.48, "По-моему, это нелепая трата времени." }, { 13.72, "Если когда-нибудь окажешься в тех краях, хорошо бы узнать, что он ещё не погиб." }, { 20.43, "Пока что." } } } },
    [97326] = { d = 32.3, g = 1, v = "child-female", n = { m = 334, f = 336 }, c = { m = { { 0.00, "Эй!" }, { 0.28, "У тебя есть время нам помочь!" }, { 2.56, "Я знаю, что есть." }, { 3.87, "Я видела, как ты улыбался, когда смотрел на нашу игру." }, { 8.08, "Нам нравится этот участок за крепостью Громмаш, потому что тут есть место, где расставить фигурки." }, { 15.54, "Одна беда – нам не хватает камней, на которые можно было бы сесть или поставить что-нибудь." }, { 22.59, "Ты большой и сильный... можешь, пожалуйста, принести нам камней?" }, { 27.50, "Больших и гладких, чтобы на них можно было присесть и отдохнуть." } }, f = { { 0.00, "Эй!" }, { 0.27, "У тебя есть время нам помочь!" }, { 2.54, "Я знаю, что есть." }, { 3.84, "Я видела, как ты улыбалась, когда смотрела на нашу игру." }, { 8.17, "Нам нравится этот участок за крепостью Громмаш, потому что тут есть место, где расставить фигурки." }, { 15.58, "Одна беда – нам не хватает камней, на которые можно было бы сесть или поставить что-нибудь." }, { 22.58, "Ты большая и сильная... можешь, пожалуйста, принести нам камней?" }, { 27.45, "Больших и гладких, чтобы на них можно было присесть и отдохнуть." } } }, t = { d = 15.4, g = 1, v = "child-female", n = { m = 160, f = 162 }, c = { m = { { 0.00, "Как у тебя получается нести столько булыжников сразу?!" }, { 4.18, "Это отличные камни." }, { 5.76, "У многих даже есть удобная плоская сторона." }, { 9.11, "Теперь, когда ты принёс их сюда, мы сами их разложим, чтобы было удобно." }, { 14.66, "Спасибо!" } }, f = { { 0.00, "Как у тебя получается нести столько булыжников сразу?!" }, { 4.19, "Это отличные камни." }, { 5.77, "У многих даже есть удобная плоская сторона." }, { 9.13, "Теперь, когда ты принесла их сюда, мы сами их разложим, чтобы было удобно." }, { 14.90, "Спасибо!" } } } } },
    [97327] = { d = 27.1, v = "creature/furbolg", n = { x = 214 }, c = { x = { { 0.43, "Мне больно это признавать, но мои братья и сёстры в Крепости Черночревов осквернены безвозвратно." }, { 11.92, "Если принесёшь мне их личные вещи, я хотя бы смогу отдать их семьям что-то на память." }, { 18.79, "Каждый узелок, который ты вернёшь, станет знаком твоего служения моему народу." } } } },
    [97328] = { d = 28.3, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Обследуя обломки, оставшиеся после крушения дирижабля, вы находите свидетельства того, что он перевозил крупную партию припасов, которую уже успели растащить." }, { 12.49, "С ящиков даже сорваны этикетки, и остались одни обрывки." }, { 17.03, "На одном можно лишь едва разобрать слова \"Пиратская Бухта\"." }, { 21.79, "Многочисленные двупалые следы и углубления в земле ведут к руинам на северо-западе." } } } },
    [97329] = { d = 34.5, v = "goblin-male", n = { x = 366 }, c = { x = { { 0.00, "Эй!" }, { 0.26, "Да, я тебе!" }, { 1.12, "Иди сюда, да не шуми!" }, { 2.76, "Я страшно облажался." }, { 4.27, "Мне удалось договориться об использовании башни дирижабля в Пиратской Бухте для срочных доставок, но на первом же заказе я увидел огромную пти... кхм... то есть меня сбили к востоку отсюда!" }, { 17.88, "К сожалению, при крушении я выжил, но прежде чем успел прийти в себя, меня уже тащили за уши!" }, { 24.78, "Теперь меня заперли в клетке, а вокруг шастают кровожадные тролли!" }, { 30.34, "Слушай, мне просто нужен ключ." }, { 32.58, "Дальше я уже сам справлюсь." } } } },
    [97331] = { d = 21.8, v = "goblin-male", n = { x = 245 }, c = { x = { { 0.00, "Постой, не уходи!" }, { 1.24, "Знаю, что сказал, будто мне нужен только ключ, но... один раз они меня уже поймали и могут это сделать снова, верно?" }, { 9.44, "Я же всего один гоблин, а вокруг тысячи троллей!" }, { 12.85, "Тебе уже удалось покромсать их достаточно, чтобы добыть ключ, значит, несложно будет защищать меня, пока мы отсюда не выберемся, а?" } } } },
    [97332] = { d = 32.0, g = 1, v = "goblin-male", n = { m = 363, f = 367 }, c = { m = { { 0.00, "Я Зиммикса терпеть не могу, но мне известно, что племя Кровавого Скальпа делает с пленниками." }, { 6.32, "Жуть сплошная." }, { 7.30, "Хорошо, что Зиммиксу удалось выбраться в целости." }, { 10.68, "Увы, мне нужно сделать одну срочную доставку, которую я совершенно не могу доверить ему." }, { 16.82, "А других свободных гоблинов у меня нет." }, { 19.52, "С другой стороны, ты уже спас потерянный груз и пленного гоблина, так что мне кажется, тебе можно доверять." }, { 26.76, "Не мог бы ты отнести это Просвистуну в Пороховой порт?" } }, f = { { 0.00, "Я Зиммикса терпеть не могу, но мне известно, что племя Кровавого Скальпа делает с пленниками." }, { 6.32, "Жуть сплошная." }, { 7.30, "Хорошо, что Зиммиксу удалось выбраться в целости." }, { 10.68, "Увы, мне нужно сделать одну срочную доставку, которую я совершенно не могу доверить ему." }, { 16.82, "А других свободных гоблинов у меня нет." }, { 19.52, "С другой стороны, ты уже спасла потерянный груз и пленного гоблина, так что мне кажется, тебе можно доверять." }, { 27.93, "Не могла бы ты отнести это Просвистуну в Пороховой порт?" } } } },
    [97378] = { d = 36.2, g = 1, v = "narrator", n = { m = 384, f = 385 }, c = { m = { { 0.00, "Ты показал себя сильным и ответственным охотником, и меня впечатлила твоя храбрость." }, { 6.64, "Только поэтому я предлагаю тебе пойти на эту охоту." }, { 10.81, "Крылатая змея рыщет в поисках добычи вдоль путей у побережья Фераласа, нападая на путников и бросая их трупы на дороге." }, { 20.20, "Совершенно ясно, что этот зверь охотится не из необходимости и больше не достоин благословения Матери-Земли." }, { 28.61, "Логово этой крылатой змеи, Зеркальной Чешуи, находится у подножия водопада на побережье Фераласа." } }, f = { { 0.00, "Ты показала себя сильной и ответственной охотницей, и меня впечатлила твоя храбрость." }, { 6.72, "Только поэтому я предлагаю тебе пойти на эту охоту." }, { 10.89, "Крылатая змея рыщет в поисках добычи вдоль путей у побережья Фераласа, нападая на путников и бросая их трупы на дороге." }, { 20.28, "Совершенно ясно, что этот зверь охотится не из необходимости и больше не достоин благословения Матери-Земли." }, { 28.69, "Логово этой крылатой змеи, Зеркальной Чешуи, находится у подножия водопада на побережье Фераласа." } } } },
    [97386] = { d = 30.8, v = "orc-male#60", n = { x = 336 }, c = { x = { { 0.00, "Ты снова вовремя, как всегда." }, { 2.23, "Мы благодарны тебе за неоценимую помощь в обороне Гром'гола." }, { 6.77, "После недавних боёв с ограми мы отправили разведчика, чтобы выяснить, остались ли у них силы, чтобы попытаться нам отомстить." }, { 16.12, "Как оказалось, далеко на востоке есть пещера, где они обосновались." }, { 21.13, "Возьми с собой одного-двух друзей и дай им понять, что мы не потерпим никакой угрозы нашему поселению." }, { 28.78, "Ни сейчас, ни когда-либо ещё!" } } } },
    [97403] = { d = 48.9, v = "scourge-male", n = { x = 457 }, c = { x = { { 0.00, "Эти химеры – чья-то злая шутка." }, { 2.85, "Два языка, оба мерзкие, рычат стужей и голодом." }, { 7.02, "Будто этой пустоши мало зубов." }, { 9.79, "Эта поляна – всё, что у нас есть, и бури постоянно накрывают её прежде, чем мы успеваем обосноваться дальше." }, { 18.89, "Двухголовые хладновеи-опустошители кружат вокруг нас, испытывают нашу решимость, отнимают наше время." }, { 27.60, "Мы тратим больше часов на то, чтобы отгонять их, чем на то, чтобы построить хоть что-то стоящее." }, { 35.78, "Перебей их." }, { 36.78, "Положи конец их засилью." }, { 38.94, "Когда рыщущих вокруг зверей станет меньше, может, нам ещё удастся создать в этой ледяной пустоши что-то долговечное." } } } },
    [97404] = { d = 39.0, v = "tauren-female", n = { x = 382 }, c = { x = { { 0.00, "Здесь живут две старые медведицы-матриархи, давно вышедшие из возраста, когда растят медвежат." }, { 7.87, "Может быть, они сёстры." }, { 9.82, "А может, просто две родственные души, прожившие похожее число сезонов." }, { 15.74, "Что бы ни свело их вместе, в них всё ещё столько свирепости и воли к жизни, что они заслуживают уважения." }, { 24.36, "Из-за этих двух седых щербозубов нам очень непросто обустроить такой лагерь, как этот." }, { 31.63, "Принеси головы Куромы и Камуро – и постарайся покончить с ними быстро, умело и милосердно." } } } },
    [97405] = { d = 28.8, v = "narrator", n = { x = 329 }, c = { x = { { 0.00, "Гназ собирает свой драндулет для соревнований аж в Калимдоре." }, { 4.27, "Его предупреждали, что нельзя так допоздна работать, да ещё так страшно шуметь, а прошлой ночью я видел, как вон из-за того дерева выглядывал огр!" }, { 14.70, "Гназ повёрнут на том, чтобы выиграть чемпионат Виражей на Миражах, а я вот повёрнут на том, чтобы меня ночью не прирезали!" }, { 23.25, "Прошу, сходи за холм на севере и сделай так, чтобы огры тут больше не шарились." } } } },
    [97420] = { d = 37.8, v = "human-male", n = { x = 424 }, c = { x = { { 0.00, "Мне нужна помощь, а ты, вроде, любишь помогать!" }, { 3.42, "Видишь эту малышку?" }, { 4.91, "Красавица, да?" }, { 5.94, "Это мой новый гоночный болид, который я лично спроектировал и собрал, потому что кое-кто не желает мне помогать." }, { 14.02, "Хочу поучаствовать на нём в гонках в Тысяче Игл, но ему нужно чуть больше мощности." }, { 19.96, "Конечно, я слишком симпатичный, чтобы быть гоблином, и слишком умный, чтобы доверять их агрегатам, но слышал, будто Торговая Компания открыла на озере залежи жидкого золота." }, { 32.43, "Уверен, они не будут против, если ты немного позаимствуешь." }, { 36.76, "Даже не заметят!" } } } },
    [97446] = { d = 36.0, g = 1, v = "tauren-female", n = { x = 323 }, c = { m = { { 0.00, "А-а, герой." }, { 1.11, "Я жду тебя." }, { 2.14, "Ветра словно сами принесли тебя ко мне." }, { 5.71, "Ты подыскиваешь себе кодо, так?" }, { 8.48, "Кодо – благородный и незлобивый зверь." }, { 11.81, "Мало какие животные служат так безотказно." }, { 15.62, "Сегодня ты стоишь перед важным выбором." }, { 19.19, "Вы с кодо объедете вместе весь мир, поэтому найди того, в котором почувствуешь родную душу." }, { 27.28, "Не беспокойся: ошибиться тут нельзя." }, { 30.45, "Ступай осмотри всех кодо и возвращайся, когда примешь решение." } }, f = { { 0.00, "А-а, героиня." }, { 1.24, "Я жду тебя." }, { 2.27, "Ветра словно сами принесли тебя ко мне." }, { 5.84, "Ты подыскиваешь себе кодо, так?" }, { 8.61, "Кодо – благородный и незлобивый зверь." }, { 11.94, "Мало какие животные служат так безотказно." }, { 15.75, "Сегодня ты стоишь перед важным выбором." }, { 19.32, "Вы с кодо объедете вместе весь мир, поэтому найди того, в котором почувствуешь родную душу." }, { 27.41, "Не беспокойся: ошибиться тут нельзя." }, { 30.58, "Ступай осмотри всех кодо и возвращайся, когда примешь решение." } } } },
    [97453] = { d = 31.1, g = 1, v = "child-orc-male", n = { m = 379, f = 383 }, c = { m = { { 0.00, "Привет, ты не мог бы мне помочь?" }, { 4.59, "Родители наконец-то разрешили мне пойти с ними в джунгли и даже пособирать травки за воротами." }, { 10.33, "Я хочу изучать травничество и стать алхимиком!" }, { 13.11, "В общем, я почти набрал полный рюкзак, как вдруг откуда-то вылезли злющие сорняки и начали в меня плеваться!" }, { 19.73, "Я убежал и со мной всё в порядке, но теперь мне больше не дают играть за пределами лагеря." }, { 25.14, "Не мог бы ты сделать так, чтобы вокруг лагеря стало безопасно, а потом рассказать об этом моей маме?" } }, f = { { 0.00, "Привет, ты не могла бы мне помочь?" }, { 4.62, "Родители наконец-то разрешили мне пойти с ними в джунгли и даже пособирать травки за воротами." }, { 10.20, "Я хочу изучать травничество и стать алхимиком!" }, { 12.91, "В общем, я почти набрал полный рюкзак, как вдруг откуда-то вылезли злющие сорняки и начали в меня плеваться!" }, { 19.33, "Я убежал и со мной всё в порядке, но теперь мне больше не дают играть за пределами лагеря." }, { 24.59, "Не могла бы ты сделать так, чтобы вокруг лагеря стало безопасно, а потом рассказать об этом моей маме?" } } }, t = { d = 30.6, v = "orc-female#124", n = { x = 314 }, c = { x = { { 0.00, "А, я так и знала, что Гемми убедит кого-нибудь помочь ему." }, { 4.54, "К сожалению, мне хватило последнего раза." }, { 7.75, "И вообще я понятия не имею, что ещё может прятаться в этих джунглях." }, { 13.05, "Нет, я ещё лет десять не разрешу ему и шагу ступить за эти ворота." }, { 18.22, "Даже не так: как только его отец вернётся из Пиратской Бухты, они немедленно отправятся назад в Дуротар." }, { 26.31, "Не трудись рассказывать Геммилу, я сама ему всё передам." } } } } },
    [97485] = { d = 36.6, v = "tauren-female", n = { x = 364 }, c = { x = { { 0.00, "Да благословит тебя Ан'ше." }, { 2.20, "У нас, тауренов, есть традиция развеивать благовония по ветру." }, { 7.18, "Я надеюсь, ты тоже захочешь почтить её." }, { 10.41, "Тебе нужно будет смешать благовония, купив травы у Ниды, кедр у Наты, нить из жил у Маху на центральном холме." }, { 19.42, "А Наал на верхнем холме продаст тебе огниво и кремень." }, { 23.96, "Когда соберёшь эти предметы, совмести их и развей на Вершине Охотников, над утёсом, что смотрит на юг." }, { 32.10, "На месте проведения церемонии будет коврик и благовония." } } }, t = { d = 27.9, g = 1, v = "tauren-female", n = { m = 277, f = 278 }, c = { m = { { 0.00, "Прекрасно." }, { 0.83, "Благодарю за то, что ты нашёл время, чтобы прикоснуться к одной из наших древних традиций, путник." }, { 8.26, "Надеюсь, в твоих странствиях будет ещё немало вещей, за которые ты захочешь вознести благодарность." }, { 15.83, "Если пожелаешь провести ритуал вновь, компоненты, которые ты собрал для меня, можно будет купить." }, { 23.33, "Ступай, и да пребудет с тобой тепло Ан'ше." } }, f = { { 0.00, "Прекрасно." }, { 0.83, "Благодарю за то, что ты нашла время, чтобы прикоснуться к одной из наших древних традиций, путница." }, { 8.71, "Надеюсь, в твоих странствиях будет ещё немало вещей, за которые ты захочешь вознести благодарность." }, { 16.28, "Если пожелаешь провести ритуал вновь, компоненты, которые ты собрала для меня, можно будет купить." }, { 24.71, "Ступай, и да пребудет с тобой тепло Ан'ше." } } } } },
    [97530] = { d = 32.2, v = "goblin-male", n = { x = 385 }, c = { x = { { 0.00, "Один торговый караван недавно заблудился в пустыне и угодил в засаду огров из клана Песчаного Молота." }, { 7.11, "Чтобы спастись, торговцу пришлось выбросить часть своего груза, отвлекая внимание громил." }, { 13.34, "Но видимо, у него есть друзья в компании, управляющей кораблями и дирижаблями, потому что теперь мне вдруг поручили вернуть потерянное." }, { 22.57, "А у меня и так полно дел." }, { 24.32, "Но если ты решишь подраться с ограми и найдёшь у них красивый блестящий браслет – принеси его мне, получишь награду." } } } },
    [97534] = { d = 28.9, v = "goblin-female#63", n = { x = 335 }, c = { x = { { 0.00, "Тс-с!" }, { 0.38, "Хочешь, кое-что расскажу?" }, { 2.20, "Здесь заработать деньжат гораздо проще, чем может показаться... если правильно преподнести свой товар!" }, { 9.30, "Я видела, как у этих умников-технарей загораются глаза, когда они видят что-то похожее на источник топлива." }, { 16.90, "Ещё лучше, если оно светится или выпускает пар." }, { 20.29, "Как насчёт сделки?" }, { 21.55, "Принеси мне части механизмов из пустыни, я впарю их этим любителям металлолома и отдам тебе долю с продаж!" } } } },
    [97536] = { d = 32.6, v = "gnome-male", n = { x = 410 }, c = { x = { { 0.00, "Чтобы отладить транспортёр материи, мне пришлось провести много экспериментов со всевозможными материалами... с разными результатами." }, { 8.80, "Одни материалы покинули этот мир, другие оказались заряжены опасной энергией!" }, { 14.08, "Теперь они излучают её, обжигая тех, кто подходит слишком близко." }, { 18.52, "Будто целый год пролежали под солнцем пустыни, впитывая его силу." }, { 23.01, "Возьми этот контейнер с радиоактивными отходами и высыпь его содержимое где-нибудь в пустыне на безопасном расстоянии от города и другого мусора." } } } },
    [97538] = { d = 36.9, v = "tauren-male#67", n = { x = 343 }, c = { x = { { 0.00, "Приветствую!" }, { 1.12, "Можно попросить тебя об одолжении?" }, { 4.25, "У меня закончился красный пигмент для красок, и мне нужна помощь кого-то помоложе, кто отправился бы в далёкие Когтистые горы вместо меня." }, { 16.52, "На горном перевале есть большое круглое озеро, которое называют Мутным, и в его водах растёт уникальное растение – лихолист." }, { 27.58, "Высушенные стручки лихолиста приобретают ярко-красный цвет." }, { 32.87, "Собери их для меня, и я щедро тебя вознагражу." } } }, t = { d = 26.7, g = 1, v = "tauren-male#67", n = { m = 262, f = 263 }, c = { m = { { 0.00, "А, спасибо." }, { 1.00, "Для меня много значит, что ты отправился так далеко ради того, что тебе наверняка кажется пустой прихотью старого таурена, но благодаря твоей доброте мне хватит пигмента до конца сезона." }, { 16.97, "Спасибо, что поддерживаешь мой промысел." }, { 20.34, "Я постараюсь создать что-нибудь великолепное из принесённых тобой пигментов." } }, f = { { 0.00, "А, спасибо." }, { 1.00, "Для меня много значит, что ты отправилась так далеко ради того, что тебе наверняка кажется пустой прихотью старого таурена, но благодаря твоей доброте мне хватит пигмента до конца сезона." }, { 17.10, "Спасибо, что поддерживаешь мой промысел." }, { 20.49, "Я постараюсь создать что-нибудь великолепное из принесённых тобой пигментов." } } } } },
    [97539] = { d = 43.0, g = 1, v = "scourge-male#82", n = { x = 453 }, c = { m = { { 0.00, "Этот лагерь совсем забросили." }, { 2.35, "Ущерб, который нам нанесли при осаде, никто не собирается возмещать, будто бы это в порядке вещей." }, { 9.96, "Но здесь я такого не потерплю." }, { 12.25, "За лазарет отвечаю я – и сделаю всё, чтобы он работал как должно." }, { 17.23, "У нас почти не осталось припасов." }, { 19.79, "Мне потребуется больше снаряжения – хотя бы столько, чтобы наши работники и стражники могли стоять на ногах и делать своё дело." }, { 29.62, "Даже в таких тяжёлых условиях мы можем изготовить годные перевязочные материалы из паутины осквернённых пауков." }, { 38.06, "Герой, принеси мне шёлк пауков, что бродят среди здешних нагорий." } }, f = { { 0.00, "Этот лагерь совсем забросили." }, { 2.32, "Ущерб, который нам нанесли при осаде, никто не собирается возмещать, будто бы это в порядке вещей." }, { 9.82, "Но здесь я такого не потерплю." }, { 12.07, "За лазарет отвечаю я – и сделаю всё, чтобы он работал как должно." }, { 16.98, "У нас почти не осталось припасов." }, { 19.51, "Мне потребуется больше снаряжения – хотя бы столько, чтобы наши работники и стражники могли стоять на ногах и делать своё дело." }, { 29.19, "Даже в таких тяжёлых условиях мы можем изготовить годные перевязочные материалы из паутины осквернённых пауков." }, { 37.51, "Героиня, принеси мне шёлк пауков, что бродят среди здешних нагорий." } } } },
    [97540] = { d = 14.0, v = "creature/tooga", n = { x = 78 }, c = { x = { { 0.00, "Ох, как же вкусно пахнет эта свежая вода..." }, { 6.37, "Я ненадолго остановлюсь – быстренько искупаюсь и попью." } } } },
    [97558] = { d = 48.9, v = "scourge-female#80", n = { x = 451 }, c = { x = { { 0.00, "Одна из особенностей жизни после смерти, о которой никто не упоминает, – это то, что происходит, когда мы получаем ранения." }, { 11.05, "Как заживает кожа у нежити?" }, { 13.55, "Да никак." }, { 14.44, "Вся наша жизнь – проклятие." }, { 16.86, "Мы продлеваем своё существование, отнимая у живых." }, { 21.29, "Когда мы получаем ранение, кожу приходится заменять, для чего обычно используются шкуры животных." }, { 30.09, "Поскольку шкуры разной толщины лучше подходят для определённых участков на теле, ключ к успеху – разнообразие!" }, { 39.85, "Принеси мне перепонки крыльев сумеречницы, шкуры псов тьмы и кожу мурлока из племени Злобного Плавника." } } }, t = { d = 8.8, g = 1, v = "scourge-female#80", n = { m = 72, f = 74 }, c = { m = { { 0.00, "Превосходно!" }, { 1.31, "Спасибо, что принёс мне эти материалы." }, { 5.23, "Обещаю найти им хорошее применение." } }, f = { { 0.00, "Превосходно!" }, { 1.19, "Спасибо, что принесла мне эти материалы." }, { 5.01, "Обещаю найти им хорошее применение." } } } } },
    [97583] = { d = 26.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Маленькая слизь, похоже, в восторге и пытается повторять твои движения, пока ты танцуешь." }, { 7.10, "Однако вскоре она начинает выглядеть утомлённой." }, { 10.97, "Маленькая слизь зависает над лужицей ила и впитывает её, немного приободрившись." }, { 17.27, "Кажется, все эти танцы её совсем вымотали." }, { 20.72, "Может быть, кто-нибудь в каналах Подгорода продаёт ещё такого питательного ила?" } } }, t = { d = 9.6, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Слизь вздрагивает, наполнившись новой энергией." }, { 3.73, "Похоже, она хочет следовать за тобой, ведь теперь ассоциирует тебя с едой." } } } } },
    [97617] = { d = 33.0, v = "dwarf-male", n = { x = 403 }, c = { x = { { 0.00, "Здорово!" }, { 0.61, "Ты, вроде, сможешь мне помочь." }, { 2.70, "Меня зовут Горгарон, я из Лиги Исследователей." }, { 5.89, "С раскопками в Бесплодных землях нам пока не очень везёт, но я точно знаю, что здесь полно ещё не обнаруженных артефактов!" }, { 14.05, "Чтобы убедить босса прислать сюда ещё одну команду, мне надо доказать, что места раскопок безопасны и их не обнесли подчистую." }, { 22.69, "Если окажешься на юге, принеси несколько не совсем развалившихся артефактов и какое-нибудь оставшееся там оборудование, которое пока не успели расколотить." } } } },
    [97663] = { d = 42.6, g = 1, v = "tauren-male", n = { m = 420, f = 422 }, c = { m = { { 0.00, "В Знойных Песках я обратил внимание на необычные камни." }, { 4.52, "Осмотрев их получше, я увидел, что на них что-то высечено!" }, { 9.18, "Конечно, я немедленно решил сделать оттиски, чтобы изучить их позже." }, { 14.79, "Тут меня заметили проходившие мимо огры." }, { 18.14, "Всё произошло так быстро, что очнулся я уже здесь, где меня выхаживал хозяин местной таверны." }, { 25.65, "Ещё и голова раскалывается." }, { 27.84, "Теперь я лишился всех припасов, да и материалы для исследования так и не добыл." }, { 34.10, "Не мог бы ты отправиться на восток и поискать мою сумку, а заодно сделать оттиски с тех камней?" } }, f = { { 0.00, "В Знойных Песках я обратил внимание на необычные камни." }, { 4.52, "Осмотрев их получше, я увидел, что на них что-то высечено!" }, { 9.18, "Конечно, я немедленно решил сделать оттиски, чтобы изучить их позже." }, { 14.79, "Тут меня заметили проходившие мимо огры." }, { 18.14, "Всё произошло так быстро, что очнулся я уже здесь, где меня выхаживал хозяин местной таверны." }, { 25.65, "Ещё и голова раскалывается." }, { 27.84, "Теперь я лишился всех припасов, да и материалы для исследования так и не добыл." }, { 34.10, "Не могла бы ты отправиться на восток и поискать мою сумку, а заодно сделать оттиски с тех камней?" } } } },
    [97821] = { d = 25.2, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Из центра поверженного элементаля выпадает на песок поблёскивающая реликвия." }, { 5.64, "Когда вы поворачиваете вещицу в руках, она полностью скрывается из виду, отражая окружающее пространство." }, { 13.59, "Лишь когда на поверхности попадается трещина, иллюзия разрушается, и вы снова ясно видите реликвию перед собой." }, { 22.02, "Возможно, эта находка кого-то заинтересует." } } } },
    [97884] = { d = 35.3, g = 1, v = "scourge-female", n = { m = 315, f = 315 }, c = { m = { { 0.00, "Ты кажешься вполне здоровым и крепким героем." }, { 4.10, "Мне нужно, чтобы кто-нибудь отправился в Светогладь в Лесоречье, к северу от Красногорья." }, { 12.06, "Когда-то моя семья держала там кузню." }, { 15.51, "Теперь, полагаю, от неё остался только опалённый остов, но мне нужно вернуть оттуда книгу, содержащую записи о наших фамильных техниках создания доспехов." }, { 29.25, "Она хранилась в подвале, так что, надеюсь, стихии её не повредили." } }, f = { { 0.00, "Ты кажешься вполне здоровой и крепкой героиней." }, { 4.48, "Мне нужно, чтобы кто-нибудь отправился в Светогладь в Лесоречье, к северу от Красногорья." }, { 12.44, "Когда-то моя семья держала там кузню." }, { 15.89, "Теперь, полагаю, от неё остался только опалённый остов, но мне нужно вернуть оттуда книгу, содержащую записи о наших фамильных техниках создания доспехов." }, { 29.63, "Она хранилась в подвале, так что, надеюсь, стихии её не повредили." } } } },
    [97891] = { d = 35.8, g = 1, v = "scourge-male", n = { m = 289, f = 290 }, c = { m = { { 0.00, "Эй, ты!" }, { 0.65, "Мне нужно, чтобы ты поскорее доставил это зелье доктору Мартину Фелбену в Район Фармацевтов, по ту сторону потока слизи!" }, { 11.64, "У зелья очень ограниченный срок годности, и нет, я сам не смогу – у меня кости гремят и ноги сразу ломаются, стоит мне только побежать." }, { 23.84, "Такой вот \"приятный\" побочный эффект жизни после смерти." }, { 29.05, "Но мы теряем время!" }, { 30.84, "Вот, бери зелье – и вперёд!" }, { 33.20, "*Алессандро отгоняет вас жестом.*" } }, f = { { 0.00, "Эй, ты!" }, { 0.60, "Мне нужно, чтобы ты поскорее доставила это зелье доктору Мартину Фелбену в Район Фармацевтов, по ту сторону потока слизи!" }, { 10.87, "У зелья очень ограниченный срок годности, и нет, я сам не смогу – у меня кости гремят и ноги сразу ломаются, стоит мне только побежать." }, { 22.20, "Такой вот \"приятный\" побочный эффект жизни после смерти." }, { 27.03, "Но мы теряем время!" }, { 28.69, "Вот, бери зелье – и вперёд!" }, { 30.88, "*Алессандро отгоняет вас жестом.*" } } }, t = { d = 24.9, g = 1, v = "scourge-male", n = { m = 221, f = 222 }, c = { m = { { 0.00, "Чудесно!" }, { 0.81, "Я как раз ждал зелье Алессандро." }, { 3.65, "Последние шесть поставок дестабилизировались прямо по дороге, но ты успел вовремя!" }, { 10.94, "Вот тебе за старания." }, { 12.89, "На этом пока всё." }, { 14.51, "Или у тебя есть ещё дела ко мне?" }, { 17.42, "Если нет, то ступай – мне нужно продолжить опыты, и я не хочу, чтобы меня отвлекали." } }, f = { { 0.00, "Чудесно!" }, { 0.79, "Я как раз ждал зелье Алессандро." }, { 3.57, "Последние шесть поставок дестабилизировались прямо по дороге, но ты успела вовремя!" }, { 10.77, "Вот тебе за старания." }, { 12.68, "На этом пока всё." }, { 14.26, "Или у тебя есть ещё дела ко мне?" }, { 17.11, "Если нет, то ступай – мне нужно продолжить опыты, и я не хочу, чтобы меня отвлекали." } } } } },
    [97894] = { d = 41.4, v = "dwarf-male#98", n = { x = 465 }, c = { x = { { 0.00, "Душевно рад познакомиться!" }, { 1.92, "Звать меня Боргус, я из единственной и неповторимой семьи Сталеруков." }, { 6.94, "Со Сталеруками ты всегда можешь рассчитывать на выгодную и честную сделку!" }, { 12.36, "Несколько недель назад мой брат Горбольд открыл торговую лавку в Аубердине." }, { 17.87, "На снабжении тамошних кораблей можно целое состояние сколотить, уж поверь мне!" }, { 23.62, "Вот уж повезло так повезло." }, { 25.60, "С тех пор я не получал от него весточки – может, заглянешь его проведать, если тебе будет по пути?" }, { 32.88, "Тут в порту новый корабль стоит, который идёт как раз туда." }, { 37.24, "Ступай на самый южный причал, ты его точно не пропустишь!" } } }, t = { d = 15.1, v = "dwarf-male#99", n = { x = 171 }, c = { x = { { 0.00, "Тебя старина Борги послал?" }, { 2.01, "Он всегда за меня переживает." }, { 4.16, "Лишняя пара рук здесь нам точно не помешает." }, { 7.34, "Из-за недавней трагедии дела почти совсем встали, но, мне кажется, ты сможешь помочь нам исправить положение." } } } } },
