    [97929] = { d = 27.0, v = "tauren-female", n = { x = 277 }, c = { x = { { 0.00, "Зачаровыватели делают всё лучше, и их привечают в любом походном лагере." }, { 5.83, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать зачарованную лютню для своего лагеря." }, { 14.00, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы, какие только могут встретиться в странствиях." } } }, t = { d = 31.3, g = 1, v = "tauren-male", n = { m = 306, f = 308 }, c = { m = { { 0.00, "Ну вот, теперь ты умеешь сам делать зачарованную лютню." }, { 4.58, "Большинству не нравится, когда лагерь разбивают посреди города, так что, если хочешь её испытать, отправляйся в дикие края." }, { 14.85, "И запомни: какой же лагерь без костра." }, { 18.08, "Прежде чем разбить лагерь, тебе понадобится костёр." }, { 22.36, "Разводить огонь научит почти любой повар." }, { 25.96, "Если ещё не освоил основы, загляни к тому, кто обучает кулинарии." } }, f = { { 0.00, "Ну вот, теперь ты умеешь сама делать зачарованную лютню." }, { 4.64, "Большинству не нравится, когда лагерь разбивают посреди города, так что, если хочешь её испытать, отправляйся в дикие края." }, { 14.75, "И запомни: какой же лагерь без костра." }, { 17.92, "Прежде чем разбить лагерь, тебе понадобится костёр." }, { 22.12, "Разводить огонь научит почти любой повар." }, { 25.66, "Если ещё не освоила основы, загляни к тому, кто обучает кулинарии." } } } } },
