    [97968] = { d = 33.9, v = "skyborne-male", n = { x = 364 }, c = { x = { { 0.00, "Ты, похоже, уже многое знаешь о травничестве." }, { 3.47, "Собирать цветы – не просто развлечение." }, { 6.47, "Это занятие может быть полезным... и весьма прибыльным." }, { 10.70, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать ароматную свечу для твоего лагеря." }, { 18.12, "Чтобы целители и те, кто применяет магию, показывали себя достойно в сражении, нужно поддерживать их боевой дух, а ароматная свеча как раз поможет сделать это." }, { 30.12, "Уверен, все знакомые колдуны будут тебе благодарны." } } }, t = { d = 31.6, g = 1, v = "skyborne-male", n = { m = 352, f = 353 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственную ароматную свечу." }, { 4.24, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 9.40, "Лучше отправляйся куда-нибудь в дикие места." }, { 12.66, "А, и помни, что никакого лагеря без костра не получится." }, { 16.71, "Так что сначала придётся разжечь костёр." }, { 19.52, "Этому тебя может научить почти любой специалист по кулинарии." }, { 24.09, "Если ещё не озаботился этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственную ароматную свечу." }, { 4.30, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 9.52, "Лучше отправляйся куда-нибудь в дикие места." }, { 12.83, "А, и помни, что никакого лагеря без костра не получится." }, { 16.93, "Так что сначала придётся разжечь костёр." }, { 19.78, "Этому тебя может научить почти любой специалист по кулинарии." }, { 24.40, "Если ещё не озаботилась этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } } } } },
