    [97977] = { d = 30.6, v = "creature/dryad", n = { x = 336 }, c = { x = { { 0.00, "Фурболги из племени Кривой Сосны не стали бы так легко предавать своих давних союзников." }, { 6.80, "Мы должны разузнать побольше об их неурядицах." }, { 10.31, "Поищи тотемы в их заброшенных домах." }, { 13.13, "Если какие-то сохранились после их спешного исхода, вырезанные на них изображения могут пролить свет на то, что здесь произошло." }, { 22.75, "Их стоянки расположены вдоль западного края долины, хотя грелли и греллиды уже могли оттуда всё вынести." } } }, t = { d = 38.5, v = "creature/dryad", n = { x = 378 }, c = { x = { { 0.00, "Всё даже хуже, чем я думала." }, { 2.43, "Эти выгравированные изображения повествуют о том, что фурболгам из племени Кривой Сосны начали сниться кошмары о том, как им приносит погибель какая-то огромная тень." }, { 16.24, "Вскоре этот страх превратился в ярость – а тень приняла облик их бывших друзей-эльфов." }, { 23.53, "Как же жутко постепенно лишаться рассудка, осознавая это..." }, { 28.54, "Надеяться теперь приходится только на то, что нам удастся лучше понять ситуацию на Тельдрассиле." }, { 36.59, "Спасибо тебе за помощь." } } } } },
    [97979] = { d = 34.4, g = 1, v = "nightelf-female#51", n = { m = 394, f = 396 }, c = { m = { { 0.00, "Ты – один из калдорай, детей звёзд, и по праву рождения унаследовал благодать богини, недоступную больше никому в этом мире." }, { 8.86, "Элуна может благословлять нас своим светом, помогая метко бить врага, или скрывать нас, как луна затмевает солнце." }, { 17.07, "Наше долгое бдение после обороны горы Хиджал подошло к концу, и мы примкнули к Альянсу других народов – с ними ты встретишься в своё время." }, { 27.08, "Сейчас же ты укрыт в ветвях Тельдрассила." }, { 30.04, "Продемонстрируй дары Матери-Луны и озарись её благословениями." } }, f = { { 0.00, "Ты – одна из калдорай, детей звёзд, и по праву рождения унаследовала благодать богини, недоступную больше никому в этом мире." }, { 8.91, "Элуна может благословлять нас своим светом, помогая метко бить врага, или скрывать нас, как луна затмевает солнце." }, { 17.11, "Наше долгое бдение после обороны горы Хиджал подошло к концу, и мы примкнули к Альянсу других народов – с ними ты встретишься в своё время." }, { 27.11, "Сейчас же ты укрыта в ветвях Тельдрассила." }, { 30.12, "Продемонстрируй дары Матери-Луны и озарись её благословениями." } } }, t = { d = 6.6, g = 1, v = "nightelf-female#51", n = { m = 58, f = 59 }, c = { m = { { 0.00, "Ты видел дары богини." }, { 1.95, "Пользуйся ими с умом – и она никогда тебя не оставит." } }, f = { { 0.00, "Ты видела дары богини." }, { 1.91, "Пользуйся ими с умом – и она никогда тебя не оставит." } } } } },
    [97985] = { d = 41.8, v = "scourge-male", n = { x = 392 }, c = { x = { { 0.00, "Они просто удивительны, правда?" }, { 2.86, "Впервые мне посчастливилось узнать секреты создания поганищ." }, { 8.19, "Я изучал эти записи, и, похоже, нам нужно сердце." }, { 12.65, "И огромное!" }, { 13.68, "Поговаривают, что есть одна рокочущая ящерица внушительных размеров по имени Громосерд, которая охотится на краю каньона в Тысяче Игл." }, { 25.45, "С таким-то именем у неё наверняка должно быть сердце, которое подойдёт нам просто идеально." }, { 33.41, "Мне оно нужно!" }, { 34.76, "А ещё я советую тебе позвать с собой друзей." }, { 38.74, "Громосерд покладистостью не славится." } } }, t = { d = 25.9, v = "scourge-male", n = { x = 240 }, c = { x = { { 0.00, "Превосходно!" }, { 1.13, "Я едва сдерживаю восторг." }, { 3.46, "А сердце всё ещё пульсирует электричеством?" }, { 7.24, "Впечатляет." }, { 8.29, "Значит, не придётся оживлять его разрядом!" }, { 12.07, "Это сердце станет чудесным дополнением к поганищу и, судя по всему, действительно нужного размера, если верить записям." }, { 22.86, "Ах, обожаю, когда всё идёт по плану." } } } } },
    [97986] = { d = 32.1, g = 1, v = "dwarf-male", n = { m = 385, f = 386 }, c = { m = { { 0.00, "Одна из наших разведчиц Серебряного Рассвета, Хейлен, несёт дозор на окраинах и в нагорьях." }, { 5.98, "Обычно она возвращается в лагерь раз в две недели." }, { 9.29, "Судя по твоему описанию, вполне возможно, что ты нашёл именно её останки." }, { 14.09, "Но других небеснорождённых, вроде тех, что ты видел на берегу реки, мы здесь не встречали." }, { 19.83, "У нас есть ещё один полевой лагерь, к северо-западу от озера Чернолесья." }, { 24.57, "Тамошний лекарь, возможно, тоже что-то об этом знает." }, { 28.18, "Да и на передовой тебе будет на что посмотреть." } }, f = { { 0.00, "Одна из наших разведчиц Серебряного Рассвета, Хейлен, несёт дозор на окраинах и в нагорьях." }, { 5.98, "Обычно она возвращается в лагерь раз в две недели." }, { 9.29, "Судя по твоему описанию, вполне возможно, что ты нашла именно её останки." }, { 14.76, "Но других небеснорождённых, вроде тех, что ты видела на берегу реки, мы здесь не встречали." }, { 20.77, "У нас есть ещё один полевой лагерь, к северо-западу от озера Чернолесья." }, { 25.51, "Тамошний лекарь, возможно, тоже что-то об этом знает." }, { 29.12, "Да и на передовой тебе будет на что посмотреть." } } } },
    [97987] = { d = 37.7, v = "bloodelf-male", n = { x = 421 }, c = { x = { { 0.00, "Примерно тогда, когда обрушились эти скалы, я услышал залпы эльфийских баллист." }, { 5.75, "Болты падали опасно близко к моему дому у дороги в Кель'Талас." }, { 10.29, "Я бежал, оставив позади лавину из деревьев и камней." }, { 14.06, "И я слышал крики — это мог быть только язык шен'дорай!" }, { 17.95, "Даже для моего уха он звучал резко." }, { 20.57, "Я разобрал лишь несколько слов: «предатель», «кровь», «враг»." }, { 24.73, "Мой тебе совет: отнеси эти сведения в Парк Штормграда." }, { 28.62, "Там живёт Саэра Уирравей — из небеснорождённых высокого сана." }, { 32.84, "Пусть мы и не одного рода, но когда-то нас обоих влекла жажда ответов." } } } },
    [97988] = { d = 38.6, v = "bloodelf-male", n = { x = 425 }, c = { x = { { 0.00, "Примерно тогда, когда обрушились эти скалы, я услышал залпы эльфийских баллист." }, { 5.80, "Болты падали опасно близко к моему дому у дороги в Кель'Талас." }, { 10.38, "Я бежал, оставив позади лавину из деревьев и камней." }, { 14.19, "И я слышал крики — это мог быть только язык шен'дорай!" }, { 18.12, "Даже для моего уха он звучал резко." }, { 20.76, "Я разобрал лишь несколько слов: «предатель», «кровь», «враг»." }, { 24.95, "Отнеси эти сведения в Оргриммар, на Аллею Мудрости." }, { 28.69, "Там живёт Корсвин Асерил — из небеснорождённых Ваятелей ветра." }, { 33.01, "Пусть мы и не одного рода, но когда-то наши сердца искали одну и ту же истину." } } } },
    [98013] = { d = 42.0, g = 1, v = "creature/ancient", n = { x = 354 }, c = { m = { { 0.00, "Соберись с мужеством прежде, чем отправишься в руины, дитя... враги непременно преградят тебе путь." }, { 9.35, "Полчища проклятых высокорождённых, теперь известных как наги, бродят по некогда великому городу." }, { 18.36, "Отправляйся на северо-восток и изгони их из этих земель." }, { 23.72, "Они утратили всё величие, которым когда-то обладали." }, { 28.73, "Если они в сговоре с Сумеречным Молотом, то могут лишь навредить лесу, что когда-то был их домом." }, { 37.91, "Они хотят войны, герой... и они её получат." } }, f = { { 0.00, "Соберись с мужеством прежде, чем отправишься в руины, дитя... враги непременно преградят тебе путь." }, { 9.15, "Полчища проклятых высокорождённых, теперь известных как наги, бродят по некогда великому городу." }, { 17.98, "Отправляйся на северо-восток и изгони их из этих земель." }, { 23.22, "Они утратили всё величие, которым когда-то обладали." }, { 28.13, "Если они в сговоре с Сумеречным Молотом, то могут лишь навредить лесу, что когда-то был их домом." }, { 37.12, "Они хотят войны, героиня... и они её получат." } } }, t = { d = 9.6, v = "creature/ancient", n = { x = 82 }, c = { x = { { 0.00, "Не тревожься, дитя." }, { 1.94, "Разорять собственный дом ради какого-то тёмного повелителя..." }, { 7.83, "Этому нет прощения." } } } } },
    [98021] = { d = 37.4, g = 1, v = "creature/bolvar", n = { m = 411, f = 416 }, c = { m = { { 0.00, "Если хочешь сделать доброе дело, советую обратиться к Гриану Камнегриву в Западном крае на юге, в поселении под названием Сторожевой холм." }, { 10.47, "Его людям нужна помощь." }, { 12.37, "Конечно, после путешествия из другой части реальности проблемы, с которыми столкнулись наши земли, могут показаться незначительными, но я уверяю: помощь, которую ты предоставишь тем, на кого эти проблемы обрушились, будет значить для них очень много." }, { 31.20, "И ты сам станешь в результате сильнее после всех трудов." }, { 35.41, "Удачи, искатель приключений!" } }, f = { { 0.00, "Если хочешь сделать доброе дело, советую обратиться к Гриану Камнегриву в Западном крае на юге, в поселении под названием Сторожевой холм." }, { 10.31, "Его людям нужна помощь." }, { 12.19, "Конечно, после путешествия из другой части реальности проблемы, с которыми столкнулись наши земли, могут показаться незначительными, но я уверяю: помощь, которую ты предоставишь тем, на кого эти проблемы обрушились, будет значить для них очень много." }, { 30.73, "И ты сама станешь в результате сильнее после всех трудов." }, { 35.02, "Удачи, искательница приключений!" } } }, t = { d = 14.8, g = 1, v = "human-male", n = { x = 151 }, c = { m = { { 0.00, "Я уже несколько месяцев молю Штормград о помощи, а мне присылают тощего эльфа?" }, { 5.93, "Что ж, ладно, дарёному помощнику в зубы не смотрят." }, { 9.70, "Добро пожаловать в Западный край, герой." }, { 12.73, "Давай найдём тебе дело." } }, f = { { 0.00, "Я уже несколько месяцев молю Штормград о помощи, а мне присылают тощего эльфа?" }, { 6.03, "Что ж, ладно, дарёному помощнику в зубы не смотрят." }, { 9.87, "Добро пожаловать в Западный край, героиня." }, { 13.10, "Давай найдём тебе дело." } } } } },
    [98024] = { d = 38.5, g = 1, v = "named/thrall", n = { m = 375, f = 379 }, c = { m = { { 0.00, "После путешествия из обители стихий проблемы, с которыми столкнулись наши земли, могут показаться незначительными." }, { 9.22, "Но я уверяю: Орде грозят серьёзные опасности, и ты станешь гораздо сильнее, если уцелеешь в своём служении ей." }, { 18.01, "Если захочешь сделать доброе дело, отправляйся на юго-запад, в обширные земли, известные как Степи." }, { 26.07, "Там есть поселение под названием Перекрёсток." }, { 29.55, "Его гордым обитателям всегда нужна помощь." }, { 33.11, "Ступай с честью, искатель приключений!" } }, f = { { 0.00, "После путешествия из обители стихий проблемы, с которыми столкнулись наши земли, могут показаться незначительными." }, { 9.76, "Но я уверяю: Орде грозят серьёзные опасности, и ты станешь гораздо сильнее, если уцелеешь в своём служении ей." }, { 19.05, "Если захочешь сделать доброе дело, отправляйся на юго-запад, в обширные земли, известные как Степи." }, { 27.58, "Там есть поселение под названием Перекрёсток." }, { 31.26, "Его гордым обитателям всегда нужна помощь." }, { 35.03, "Ступай с честью, искательница приключений!" } } }, t = { d = 15.3, g = 1, v = "orc-male#60", n = { m = 123, f = 124 }, c = { m = { { 0.00, "Это что?" }, { 0.83, "Эльф?" }, { 1.33, "Говоришь, ты от вождя?" }, { 3.41, "Хиловат ты, как по мне, но это ничего." }, { 7.56, "Здесь ты либо выживаешь и процветаешь, либо гибнешь." }, { 12.38, "Так всё в этих землях устроено." } }, f = { { 0.00, "Это что?" }, { 0.83, "Эльф?" }, { 1.34, "Говоришь, ты от вождя?" }, { 3.42, "Хиловата ты, как по мне, но это ничего." }, { 7.68, "Здесь ты либо выживаешь и процветаешь, либо гибнешь." }, { 12.52, "Так всё в этих землях устроено." } } } } },
    [98025] = { d = 32.2, v = "narrator", n = { x = 345 }, c = { x = { { 0.00, "Внимание!" }, { 0.78, "Объявляется награда за убийство совы Джай'ванель, также известной по прозвищу \"Мечепёрая\"." }, { 7.81, "К сожалению, сова обезумела и начала нападать на путешественников, проходящих по дороге близ Аубердина." }, { 15.84, "В последний раз её заметили к северу от руин Амет'Арана у подножия горы." }, { 21.52, "Принесите одно из её чёрных перьев как доказательство смерти." }, { 26.28, "За наградой обращаться к часовому Глинде Нал'Шии в Аубердине." }, { 31.11, "Совет Аубердина" } } }, t = { d = 19.6, g = 1, v = "nightelf-female#52", n = { x = 230 }, c = { m = { { 0.00, "Хорошо, что проблема решена, хотя мне очень жаль, что нам не удалось найти другой выход." }, { 5.84, "Джай'ванель давно была своего рода хранительницей этих земель, и я не уверена, что могло подтолкнуть её к безумию." }, { 13.40, "В любом случае, спасибо тебе за услугу, герой." }, { 16.56, "Теперь дороги к Аубердину снова безопасны." } }, f = { { 0.00, "Хорошо, что проблема решена, хотя мне очень жаль, что нам не удалось найти другой выход." }, { 5.90, "Джай'ванель давно была своего рода хранительницей этих земель, и я не уверена, что могло подтолкнуть её к безумию." }, { 13.54, "В любом случае, спасибо тебе за услугу, героиня." }, { 16.85, "Теперь дороги к Аубердину снова безопасны." } } } } },
    [98027] = { d = 23.4, g = 1, v = "narrator", n = { m = 0, f = 0 }, c = { m = { { 0.00, "Серебряное ожерелье в твоих руках мягко поблёскивает, пока ты его рассматриваешь." }, { 6.38, "Маленький полумесяц напоминает другие символы ночных эльфов, которые ты видел раньше." }, { 13.18, "Переворачивая ожерелье, ты замечаешь небольшую надпись: «Алор'лорма, Малинн»." }, { 19.20, "Возможно, оно принадлежит Малинн из Астранаара?" } }, f = { { 0.00, "Серебряное ожерелье в твоих руках мягко поблёскивает, пока ты его рассматриваешь." }, { 6.51, "Маленький полумесяц напоминает другие символы ночных эльфов, которые ты видела раньше." }, { 13.53, "Переворачивая ожерелье, ты замечаешь небольшую надпись: «Алор'лорма, Малинн»." }, { 19.68, "Возможно, оно принадлежит Малинн из Астранаара?" } } }, t = { d = 20.3, g = 1, v = "nightelf-female", n = { m = 232, f = 234 }, c = { m = { { 0.00, "Ой!" }, { 0.24, "Неужели оно нашлось?" }, { 1.70, "Я везде искала это ожерелье!" }, { 3.71, "Я потеряла его, когда доставляла припасы на одну из наших застав." }, { 8.22, "Потом я пыталась найти его на дороге, но безуспешно." }, { 11.81, "Спасибо, что принёс мне его." }, { 13.69, "Это подарок от моих покойных родителей." }, { 16.43, "Словами не описать, как много оно для меня значит." } }, f = { { 0.00, "Ой!" }, { 0.24, "Неужели оно нашлось?" }, { 1.70, "Я везде искала это ожерелье!" }, { 3.71, "Я потеряла его, когда доставляла припасы на одну из наших застав." }, { 8.22, "Потом я пыталась найти его на дороге, но безуспешно." }, { 11.81, "Спасибо, что принесла мне его." }, { 14.27, "Это подарок от моих покойных родителей." }, { 17.01, "Словами не описать, как много оно для меня значит." } } } } },
    [98028] = { d = 34.6, v = "narrator", n = { x = 370 }, c = { x = { { 0.00, "Всё, что осталось от могучего элементаля, – сфера чистой воды, замутнённой неизвестной субстанцией." }, { 7.60, "По краям сфера выглядит чистой, но когда вы поворачиваете её, субстанция перемещается, словно специально не позволяя вам заглянуть вглубь." }, { 18.24, "Что бы ни случилось с элементалем и руинами, которые он охранял, воздействовавшая на него магия всё ещё действует." }, { 26.97, "Если кто и сможет разобраться в этом, то только древо мудрости Ону из Рощи Древних далеко на юге." } } }, t = { d = 32.2, g = 1, v = "creature/ancient", n = { m = 192, f = 193 }, c = { m = { { 0.00, "*Ону выглядит удивлённым – насколько вообще может выглядеть удивлённым древний.*" }, { 6.48, "Лестница, ведущая вниз, в Матистре?" }, { 10.90, "Неужели?" }, { 11.92, "*Ону качает головой.*" }, { 13.92, "Мне нужно обсудить это с остальными." }, { 17.35, "Пока же знай: хорошо, что ты обнаружил это раньше наг... и их союзников из культа." }, { 24.88, "Прими это в благодарность за труды." }, { 28.22, "Одолеть элементаля-стража – немалый подвиг." } }, f = { { 0.00, "*Ону выглядит удивлённым – насколько вообще может выглядеть удивлённым древний.*" }, { 6.40, "Лестница, ведущая вниз, в Матистре?" }, { 10.82, "Неужели?" }, { 11.84, "*Ону качает головой.*" }, { 13.76, "Мне нужно обсудить это с остальными." }, { 16.83, "Пока же знай: хорошо, что ты обнаружила это раньше наг... и их союзников из культа." }, { 23.65, "Прими это в благодарность за труды." }, { 26.64, "Одолеть элементаля-стража – немалый подвиг." } } } } },
    [98042] = { d = 14.2, g = 1, v = "narrator", n = { m = 55, f = 56 }, c = { m = { { 0.00, "Когда вы вырываете страницу из Сумеречного фолианта, в ваш разум вторгается зловещий голос." }, { 8.03, "Они не справились." }, { 9.71, "Ты будешь забыт." }, { 11.22, "Они потеряют то око, что получили." } }, f = { { 0.00, "Когда вы вырываете страницу из Сумеречного фолианта, в ваш разум вторгается зловещий голос." }, { 7.90, "Они не справились." }, { 9.54, "Ты будешь забыта." }, { 11.11, "Они потеряют то око, что получили." } } }, t = { d = 12.3, g = 1, v = "nightelf-male#54", n = { x = 83 }, c = { m = { { 0.00, "*Тандрис долго раздумывает.*" }, { 2.64, "Я чувствую здесь след древнего зла, герой." }, { 6.32, "Я немедленно отправлю это на изучение в Дарнасс." }, { 10.64, "Анде'торас-этиль." } }, f = { { 0.00, "*Тандрис долго раздумывает.*" }, { 2.72, "Я чувствую здесь след древнего зла, героиня." }, { 6.59, "Я немедленно отправлю это на изучение в Дарнасс." }, { 10.95, "Анде'торас-этиль." } } } } },
    [98046] = { d = 28.1, g = 1, v = "named/3516", n = { x = 182 }, c = { m = { { 0.00, "*Верховный друид Фэндрал Олений Шлем прищуривается.*" }, { 4.32, "Ты ещё здесь?" }, { 5.19, "Возьми этот флакон и уходи с глаз долой, герой." }, { 8.53, "Мне ясно, что вода не даст мне ответов на вопросы, как не давала их раньше." }, { 13.61, "Думаю, какая-нибудь жрица из храма Луны на юге придумает, что с этим делать." }, { 18.88, "*Фэндрал отводит взгляд.*" }, { 20.99, "*Его дальнейшие слова адресованы уже не вам.*" }, { 24.88, "Нужно найти другой способ..." } }, f = { { 0.00, "*Верховный друид Фэндрал Олений Шлем прищуривается.*" }, { 4.40, "Ты ещё здесь?" }, { 5.33, "Возьми этот флакон и уходи с глаз долой, героиня." }, { 9.03, "Мне ясно, что вода не даст мне ответов на вопросы, как не давала их раньше." }, { 14.46, "Думаю, какая-нибудь жрица из храма Луны на юге придумает, что с этим делать." }, { 20.08, "*Фэндрал отводит взгляд.*" }, { 22.16, "*Его дальнейшие слова адресованы уже не вам.*" }, { 26.00, "Нужно найти другой способ..." } } }, t = { d = 14.2, v = "nightelf-female#51", n = { x = 161 }, c = { x = { { 0.00, "Не принимай слова верховного друида близко к сердцу." }, { 3.87, "В отсутствие Малфуриона на нём лежит тяжкое бремя." }, { 7.55, "Подожди!" }, { 8.20, "Во флаконе ещё осталось несколько капель!" }, { 11.22, "Может быть, поэтому его ритуал не удался?" } } } } },
    [98059] = { d = 29.5, g = 1, v = "human-male", n = { m = 360, f = 363 }, c = { m = { { 0.00, "Совет Хилсбрада не отвечает на письма нашего магистрата." }, { 3.72, "Мне удалось выудить кое-какие сведения у торговца из города, но у меня так и нет объяснений этому молчанию." }, { 10.76, "Мы просим лишь о небольшом взводе, но до меня дошли слухи, что у них пылится несколько совершенно новых осадных баллист." }, { 18.61, "Зайди в их ратушу под видом жителя, принёсшего заполненную анкету переписи, и положи вот это на стол для учёта." }, { 25.77, "Возвращайся ко мне, когда дело будет сделано." } }, f = { { 0.00, "Совет Хилсбрада не отвечает на письма нашего магистрата." }, { 3.81, "Мне удалось выудить кое-какие сведения у торговца из города, но у меня так и нет объяснений этому молчанию." }, { 11.02, "Мы просим лишь о небольшом взводе, но до меня дошли слухи, что у них пылится несколько совершенно новых осадных баллист." }, { 19.07, "Зайди в их ратушу под видом жительницы, принёсшей заполненную анкету переписи, и положи вот это на стол для учёта." }, { 26.57, "Возвращайся ко мне, когда дело будет сделано." } } }, t = { d = 17.7, v = "human-male", n = { x = 206 }, c = { x = { { 0.00, "Отличная работа, солдат." }, { 1.77, "Знаю, ты служишь не у нас, но умелыми руками мы никогда не разбрасываемся." }, { 6.89, "Если они не ответят и на это письмо, придётся изъясняться с ними погрубее." }, { 12.13, "Будем держать тебя в резерве для общения с гражданскими, если снова понадобится." } } } } },
    [98065] = { d = 22.4, v = "nightelf-female#51", n = { x = 244 }, c = { x = { { 0.00, "Немедленно покажи это Тиранде!" }, { 2.33, "Сейчас я перемещу это в более подобающий сосуд." }, { 5.94, "Не бойся." }, { 6.67, "Верховная жрица Элуны строгая, но у неё доброе сердце." }, { 10.74, "Она защищает всех жителей и гостей Дарнасса и несёт нам свет нашей богини." }, { 16.21, "Она с радостью примет у тебя священную воду." }, { 19.61, "Её можно найти на верхнем этаже храма." } } }, t = { d = 43.6, g = 1, v = "nightelf-female#173", n = { m = 412, f = 414 }, c = { m = { { 0.00, "Олений Шлем много трудился в отсутствие моего дорогого Малфуриона, но ему с ним не сравниться." }, { 7.71, "И не он управляет Дарнассом – это бремя лежит только на мне." }, { 12.46, "*Тиранда расслабляется.*" }, { 15.02, "Извини." }, { 15.68, "Как ты уже наверняка заметил, перед нами стоит множество испытаний." }, { 21.25, "Сейчас Фэндрал – верховный друид, и его авторитет нужно признавать." }, { 26.82, "Но все его дела касаются лишь друидизма, в то время как я не только служу верховной жрицей, но и правлю нашим народом согласно воле Элуны." }, { 38.11, "Каждая капля этой воды благословлена богиней." }, { 41.92, "Спасибо, что сохранил её." } }, f = { { 0.00, "Олений Шлем много трудился в отсутствие моего дорогого Малфуриона, но ему с ним не сравниться." }, { 7.61, "И не он управляет Дарнассом – это бремя лежит только на мне." }, { 12.27, "*Тиранда расслабляется.*" }, { 14.75, "Извини." }, { 15.39, "Как ты уже наверняка заметила, перед нами стоит множество испытаний." }, { 20.83, "Сейчас Фэндрал – верховный друид, и его авторитет нужно признавать." }, { 26.20, "Но все его дела касаются лишь друидизма, в то время как я не только служу верховной жрицей, но и правлю нашим народом согласно воле Элуны." }, { 37.09, "Каждая капля этой воды благословлена богиней." }, { 40.77, "Спасибо, что сохранила её." } } } } },
    [98067] = { d = 33.0, v = "nightelf-female#52", n = { x = 414 }, c = { x = { { 0.00, "Генерал Лунное Перо следит за тем, чтобы у всех часовых было время на молитву Элуне." }, { 5.60, "Чтобы одолеть врагов, настоящая охотница использует не только свой клинок, но и дары богини." }, { 11.68, "Помоги мне в моих ежедневных обязанностях и расставь часовых по городу." }, { 16.34, "Начни с туннелей, ведущих под крепость Кенария на севере, а затем иди к банку в центре города, таверне на Террасе Ремесленников на северо-востоке и городским воротам." }, { 27.26, "Стражники могут тебе помочь." }, { 29.20, "В Тельдрассиле не всё спокойно." }, { 31.21, "Мы должны оставаться начеку." } } }, t = { d = 9.4, v = "nightelf-female#52", n = { x = 114 }, c = { x = { { 0.00, "Спасибо тебе за помощь." }, { 1.74, "Ежедневные ритуалы приносят мне спокойствие, но иногда хочется просто провести несколько минут в размышлениях." } } } } },
    [98069] = { d = 26.9, g = 1, v = "tauren-female", n = { m = 280, f = 281 }, c = { m = { { 0.00, "Проклятые гарпии!" }, { 1.36, "Они напали на последний караван, который должен был доставить припасы на Заставу Вольного Ветра." }, { 8.74, "Пока что припасов нам хватает, но без новых мы скоро останемся ни с чем." }, { 14.13, "Не знаю, зачем гарпиям наши припасы, но я была бы благодарна, если бы ты вернул их." }, { 20.47, "Их логово к западу отсюда." }, { 22.52, "Гарпии есть и у подножия утёса, и в пещере на вершине." } }, f = { { 0.00, "Проклятые гарпии!" }, { 1.39, "Они напали на последний караван, который должен был доставить припасы на Заставу Вольного Ветра." }, { 8.87, "Пока что припасов нам хватает, но без новых мы скоро останемся ни с чем." }, { 14.35, "Не знаю, зачем гарпиям наши припасы, но я была бы благодарна, если бы ты вернула их." }, { 20.86, "Их логово к западу отсюда." }, { 22.94, "Гарпии есть и у подножия утёса, и в пещере на вершине." } } }, t = { d = 5.8, v = "tauren-female", n = { x = 55 }, c = { x = { { 0.00, "Спасибо." }, { 0.79, "Этих припасов нам хватит, пока не придёт следующая партия." } } } } },
    [98070] = { d = 31.8, v = "tauren-female", n = { x = 345 }, c = { x = { { 0.00, "В Каньоне Визга обитает местная стая гарпий, известных свирепым нравом и налётами." }, { 6.27, "Они устраивали засады на последние караваны с припасами, у которых хватило смелости пройти этим путём." }, { 14.05, "Боюсь, если не принять меры, ни один караван больше не осмелится отправиться на Заставу Вольного Ветра." }, { 21.95, "Отправляйся и убей столько гарпий, сколько сможешь." }, { 25.91, "Вернись ко мне, когда дело будет сделано, и я щедро вознагражу тебя за усилия." } } }, t = { d = 11.8, v = "tauren-female", n = { x = 123 }, c = { x = { { 0.00, "Это замечательные новости!" }, { 2.17, "Я сообщу нашим поставщикам, что с гарпиями покончено." }, { 6.43, "По крайней мере, одной угрозой для будущих караванов станет меньше." } } } } },
    [98071] = { d = 30.4, v = "dwarf-male", n = { x = 348 }, c = { x = { { 0.00, "Я немножко торгую с коллегами в Дун Гароке." }, { 3.07, "Похоже, не только мы скучаем по виноградникам семьи Фолрук!" }, { 7.28, "Большую часть готового вина лучших годов уже выпили, но у нас ещё есть несколько ящиков в погребах." }, { 14.31, "Отнеси этот ящик фолрукского сортового в Дун Гарок на юго-востоке и оставь у их очага на месте сбора, что у подножия крепости." }, { 23.26, "Взамен принеси назад мешок домашнего хмеля." }, { 26.45, "Эта крепость – самое похожее на дом место в этих землях!" } } }, t = { d = 24.2, g = 1, v = "dwarf-male", n = { m = 272, f = 273 }, c = { m = { { 0.00, "Вот он, тот запах хмеля, по которому я скучал!" }, { 3.27, "Ты оказал мне большую услугу: каждый раз, когда я сам езжу в Дун Гарок, у меня уходит несколько дней, чтобы оттуда выбраться." }, { 12.18, "Трудно вытащить себя из залов этой крепости, когда уже освоишься." }, { 16.99, "Приятно держать на полке вкус старых добрых времён для собратьев-дворфов." }, { 22.19, "Вот, держи кое-что за помощь." } }, f = { { 0.00, "Вот он, тот запах хмеля, по которому я скучал!" }, { 3.23, "Ты оказала мне большую услугу: каждый раз, когда я сам езжу в Дун Гарок, у меня уходит несколько дней, чтобы оттуда выбраться." }, { 12.09, "Трудно вытащить себя из залов этой крепости, когда уже освоишься." }, { 16.84, "Приятно держать на полке вкус старых добрых времён для собратьев-дворфов." }, { 21.97, "Вот, держи кое-что за помощь." } } } } },
    [98072] = { d = 38.2, g = 1, v = "human-male", n = { m = 427, f = 428 }, c = { m = { { 0.00, "Да ты настоящий труженик!" }, { 1.80, "У меня есть ещё одна просьба, если ты не прочь взяться за работу поопаснее." }, { 7.13, "Торговля кроколисками приносит стабильный доход, но это мелочь по сравнению с тем, что можно выручить за драконью чешую." }, { 15.66, "За мешок чешуи дракончиков заплатят солидные деньги." }, { 19.45, "Я их называю небесными кроколисками!" }, { 22.02, "Моему ученику ни за что к ним не подобраться, зато эта работа, похоже, как раз по твоей части!" }, { 28.69, "Дракончиков можно найти далеко на востоке, вдоль Зелёного Пояса." }, { 33.25, "Но будь настороже – в тех холмах рыскают злобные орки!" } }, f = { { 0.00, "Да ты настоящая труженица!" }, { 1.92, "У меня есть ещё одна просьба, если ты не прочь взяться за работу поопаснее." }, { 7.43, "Торговля кроколисками приносит стабильный доход, но это мелочь по сравнению с тем, что можно выручить за драконью чешую." }, { 16.24, "За мешок чешуи дракончиков заплатят солидные деньги." }, { 20.15, "Я их называю небесными кроколисками!" }, { 22.81, "Моему ученику ни за что к ним не подобраться, зато эта работа, похоже, как раз по твоей части!" }, { 29.70, "Дракончиков можно найти далеко на востоке, вдоль Зелёного Пояса." }, { 34.41, "Но будь настороже – в тех холмах рыскают злобные орки!" } } }, t = { d = 15.1, v = "human-male", n = { x = 168 }, c = { x = { { 0.00, "Да у тебя настоящий талант!" }, { 2.02, "Слушай, если вдруг решишь отдохнуть от приключений, возвращайся к своему приятелю Джеймсу." }, { 8.55, "Я сразу найду тебе работу!" }, { 10.57, "Хотя, пожалуй, к тому времени ты будешь ещё старше." }, { 14.35, "Ну да ладно!" } } } } },
    [98093] = { d = 31.1, g = 1, v = "tauren-female#71", n = { m = 332, f = 333 }, c = { m = { { 0.00, "Как хорошо, что ты меня заметил!" }, { 2.48, "Сегодня утром была чудесная погода, и я решила пройтись от лагеря Таурахо по золотой тропе." }, { 9.57, "А когда собралась возвращаться, не смогла – вокруг начали кружить гиены, а обходной путь преградили грозовые ящеры." }, { 18.39, "Пришлось забраться на дерево, а теперь вокруг столько опасных зверей, что я ни за что не добегу домой." }, { 26.17, "Может быть, зачистишь поля от грозовых ящеров и многозубых ловцов?" } }, f = { { 0.00, "Как хорошо, что ты меня заметила!" }, { 2.54, "Сегодня утром была чудесная погода, и я решила пройтись от лагеря Таурахо по золотой тропе." }, { 9.60, "А когда собралась возвращаться, не смогла – вокруг начали кружить гиены, а обходной путь преградили грозовые ящеры." }, { 18.37, "Пришлось забраться на дерево, а теперь вокруг столько опасных зверей, что я ни за что не добегу домой." }, { 26.12, "Может быть, зачистишь поля от грозовых ящеров и многозубых ловцов?" } } }, t = { d = 22.2, g = 1, v = "tauren-female#71", n = { m = 206, f = 210 }, c = { m = { { 0.00, "Спасибо, что выручил меня." }, { 2.28, "Я сообщу в Лагерь Таурахо, что ты меня спас." }, { 5.99, "Как же мне повезло, что ты оказался рядом, – иначе я бы просидела там весь день!" }, { 12.52, "Больше у меня ничего нет, но надеюсь, тебе это пригодится." }, { 17.53, "А я потихоньку, осторожно слезу и пойду своей дорогой." } }, f = { { 0.00, "Спасибо, что выручила меня." }, { 2.33, "Я сообщу в Лагерь Таурахо, что ты меня спасла." }, { 6.24, "Как же мне повезло, что ты оказалась рядом, – иначе я бы просидела там весь день!" }, { 12.77, "Больше у меня ничего нет, но надеюсь, тебе это пригодится." }, { 17.73, "А я потихоньку, осторожно слезу и пойду своей дорогой." } } } } },
    [98094] = { d = 35.1, v = "scourge-female", n = { x = 323 }, c = { x = { { 0.00, "Теперь, когда мы знаем, что можем доверить тебе доставку важных сведений нашим шпионам, для тебя есть ещё одно задание." }, { 10.65, "Отнеси это стражу смерти Масоджу." }, { 13.75, "Ты найдёшь его почти точно к югу от нас." }, { 17.32, "Когда передашь это ему, он даст тебе новое задание." }, { 22.01, "Ищи его на возвышенности к северу от сгнившего виноградника, который зовут Владением Нетандера." }, { 30.43, "Наши планы по захвату этих земель воплощаются в жизнь." } } }, t = { d = 8.1, v = "scourge-male", n = { x = 61 }, c = { x = { { 0.00, "Чудесно." }, { 0.97, "Свежая кровь для полевой работы." }, { 4.47, "Давай-ка посмотрим, что у тебя там." } } } } },
    [98095] = { d = 34.3, v = "scourge-male", n = { x = 384 }, c = { x = { { 0.00, "Высшее командование использует летучих всадников для перевозки войск." }, { 5.10, "В ключевых точках предгорий нужно обновить сигнальные приманки." }, { 9.86, "Возьми эти флаконы." }, { 11.40, "Открой их в трёх местах: на холмах рядом с Дун Гароком, на плато, откуда открывается вид на крепость Дарнхольд, и на Высоком отроге над городом Хилсбрадом." }, { 22.80, "Сделав это, ты распылишь пары, которые снова привлекут наших летучих мышей к нужным точкам высадки." }, { 30.38, "Найди разбитые пустые флаконы и обнови наши приманки." } } }, t = { d = 10.0, v = "scourge-male", n = { x = 81 }, c = { x = { { 0.00, "Хорошая работа." }, { 1.68, "Наши планы продвигаются." }, { 4.29, "Стражи смерти дерзают." }, { 6.72, "Пусть цель направляет твои удары." } } } } },
