    [98166] = { d = 31.8, g = 1, v = "human-male", n = { m = 385, f = 386 }, c = { m = { { 0.00, "Приветствую!" }, { 0.86, "Хочешь взглянуть на наших лошадей?" }, { 3.27, "Эти скакуны происходят и от старинной лордеронской породы, и от наших местных лошадей." }, { 9.18, "Более надёжного спутника в странствиях тебе не найти." }, { 12.82, "Выбрать будет непросто: все они превосходны и обучены сохранять спокойствие даже в опасности." }, { 19.23, "Не забывай: вам с лошадью вместе странствовать по миру." }, { 22.99, "Какой бы выбор ты ни сделал, он наверняка подойдёт тебе лучше всего." }, { 27.67, "Осмотри лошадей и возвращайся ко мне, когда сделаешь выбор." } }, f = { { 0.00, "Приветствую!" }, { 0.86, "Хочешь взглянуть на наших лошадей?" }, { 3.27, "Эти скакуны происходят и от старинной лордеронской породы, и от наших местных лошадей." }, { 9.18, "Более надёжного спутника в странствиях тебе не найти." }, { 12.82, "Выбрать будет непросто: все они превосходны и обучены сохранять спокойствие даже в опасности." }, { 19.23, "Не забывай: вам с лошадью вместе странствовать по миру." }, { 22.99, "Какой бы выбор ты ни сделала, он наверняка подойдёт тебе лучше всего." }, { 27.86, "Осмотри лошадей и возвращайся ко мне, когда сделаешь выбор." } } } },
    [98189] = { d = 21.7, v = "human-male", n = { x = 253 }, c = { x = { { 0.00, "Невероятно..." }, { 0.95, "Какая красота!" }, { 2.04, "\"Слепая принцесса\" должна была доставить это в Гавань Менетилов, прежде чем произошла трагедия." }, { 8.84, "Мы были так близки!" }, { 10.24, "Полагаю, капитан Крепкий Кулак должен был подписать нужные документы в крепости Менетилов позади нас." }, { 17.43, "Почему бы тебе не оказать нам всем честь и не закончить работу?" } } }, t = { d = 6.8, g = 1, v = "dwarf-male", n = { m = 73, f = 75 }, c = { m = { { 0.00, "Ты смог отобрать это у тех чудовищ!" }, { 2.77, "Артефактов покойного короля осталось не так уж много." } }, f = { { 0.00, "Ты смогла отобрать это у тех чудовищ!" }, { 2.86, "Артефактов покойного короля осталось не так уж много." } } } } },
    [98190] = { d = 37.5, g = 1, v = "dwarf-male", n = { m = 465, f = 464 }, c = { m = { { 0.00, "Тебе следует немедленно отправиться с этим в Штормград." }, { 3.69, "Как бы я ни гордился тем, что крепость и гавань носят имя короля Теренаса Менетила Второго, это место – лишь небольшой тихий уголок посреди настоящей бури врагов." }, { 14.46, "Здесь просто-напросто небезопасно." }, { 16.72, "В частности, клан Драконьей Пасти многим бы пожертвовал, чтобы завладеть чем-то подобным..." }, { 22.72, "Боюсь даже представить, что бы они сделали с такой ценностью." }, { 26.83, "Правилами субординации можешь в этот раз пренебречь, парень." }, { 30.81, "Отправляйся прямиком к верховному лорду Фордрагону." }, { 34.21, "Он знает, где следует хранить такой предмет." } }, f = { { 0.00, "Тебе следует немедленно отправиться с этим в Штормград." }, { 3.74, "Как бы я ни гордился тем, что крепость и гавань носят имя короля Теренаса Менетила Второго, это место – лишь небольшой тихий уголок посреди настоящей бури врагов." }, { 14.67, "Здесь просто-напросто небезопасно." }, { 16.96, "В частности, клан Драконьей Пасти многим бы пожертвовал, чтобы завладеть чем-то подобным..." }, { 23.05, "Боюсь даже представить, что бы они сделали с такой ценностью." }, { 27.22, "Правилами субординации можешь в этот раз пренебречь, милая." }, { 31.20, "Отправляйся прямиком к верховному лорду Фордрагону." }, { 34.64, "Он знает, где следует хранить такой предмет." } } }, t = { d = 5.9, g = 1, v = "creature/bolvar", n = { m = 58, f = 59 }, c = { m = { { 0.00, "Благодарю тебя за то, что вернул это." }, { 2.96, "Я рад, что вещь не попала в чужие руки." } }, f = { { 0.00, "Благодарю тебя за то, что вернула это." }, { 3.04, "Я рад, что вещь не попала в чужие руки." } } } } },
    [98191] = { d = 38.8, v = "creature/bolvar", n = { x = 371 }, c = { x = { { 0.00, "Король Теренас был хорошим человеком." }, { 3.23, "Набожным." }, { 4.07, "Народ любил его, и именно ему наш Альянс обязан своим существованием." }, { 10.14, "Ирония состоит в том, что он был очень скромным и терпеть не мог подобные памятные предметы." }, { 17.90, "Поэтому их так мало." }, { 19.67, "И лишь малая их часть уцелела после падения Лордерона." }, { 24.28, "Похоже, в этой статуэтке собралась сила Света." }, { 28.35, "Лучше всего будет хранить её в Соборе Света на Соборной площади, в самом центре города." }, { 35.96, "Отнеси её лорду Грейсону Тенелому." } } }, t = { d = 35.0, g = 1, v = "human-male", n = { x = 343 }, c = { m = { { 0.00, "Во имя Света... он точь-в-точь как его мальчик..." }, { 4.40, "*Лорд Грейсон Тенелом на мгновение замолкает.*" }, { 8.16, "Эта статуэтка действительно благословлена." }, { 11.08, "Её связь с Теренасом, то, что она пережила всё, что сделал с ним этот монстр... в ней великая сила для тех, кто верит в её мощь." }, { 19.58, "Пока что лучше хранить её здесь, под охраной ордена паладинов." }, { 23.87, "Мы будем размышлять над ней дальше, чтобы узнать больше о её дарах, и, возможно, она поможет нам в тёмные времена впереди." }, { 32.25, "Спасибо, герой." }, { 33.36, "Да благословит тебя Свет." } }, f = { { 0.00, "Во имя Света... он точь-в-точь как его мальчик..." }, { 4.48, "*Лорд Грейсон Тенелом на мгновение замолкает.*" }, { 8.40, "Эта статуэтка действительно благословлена." }, { 11.29, "Её связь с Теренасом, то, что она пережила всё, что сделал с ним этот монстр... в ней великая сила для тех, кто верит в её мощь." }, { 19.70, "Пока что лучше хранить её здесь, под охраной ордена паладинов." }, { 23.94, "Мы будем размышлять над ней дальше, чтобы узнать больше о её дарах, и, возможно, она поможет нам в тёмные времена впереди." }, { 32.23, "Спасибо, героиня." }, { 33.46, "Да благословит тебя Свет." } } } } },
    [98192] = { d = 22.2, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Эй, мелочь!" }, { 0.90, "Помогай Краку дробить красных кусак, добывать чешую!" }, { 5.03, "Крак долбит красных кусак, чтобы чешую собрать, но руки у него слишком большие." }, { 11.23, "Крак режет шкуры – а они в дырках." }, { 13.92, "Но ты – мелочь!" }, { 15.09, "Собери шкуры красных кусак в Земле Драконов на юге." }, { 19.15, "Они злобные и юркие." }, { 20.80, "Могут тебя слопать." } } } },
    [98197] = { d = 32.6, v = "dwarf-male", n = { x = 391 }, c = { x = { { 0.00, "Эту гавань Старая Орда построила как плацдарм для морского вторжения в Хилсбрад." }, { 5.45, "Так она смогла полностью обойти оборону Лордерона!" }, { 8.90, "Сколько же жизней унесла война..." }, { 11.20, "Что ещё хуже, тот флот был построен из материалов, украденных из Каз Модана!" }, { 16.16, "Много чего осталось в гавани после того, как адмирал Праудмур разгромил захватчиков и отстроил это место для Альянса." }, { 25.26, "Нам понадобятся эти материалы, чтобы укрепить оборону города, когда клан Драконьей Пасти перейдёт в наступление." } } }, t = { d = 11.5, g = 1, v = "dwarf-male", n = { x = 117 }, c = { m = { { 0.00, "Ага!" }, { 0.42, "Немного отсырело, но пара дней на солнце всё исправит." }, { 4.61, "Спасибо, герой." }, { 5.87, "Приятно хоть раз не зависеть целиком от поставок из Терамора или Аубердина!" } }, f = { { 0.00, "Ага!" }, { 0.41, "Немного отсырело, но пара дней на солнце всё исправит." }, { 4.56, "Спасибо, героиня." }, { 5.94, "Приятно хоть раз не зависеть целиком от поставок из Терамора или Аубердина!" } } } } },
    [98203] = { d = 39.5, v = "troll-male#139", n = { x = 385 }, c = { x = { { 0.00, "Племя Сухокожих знает, что мы охотимся на них, проклятых предателей." }, { 5.51, "Они строят козни, находят новые убежища, даже когда мы сжигаем их за коварство." }, { 12.12, "Наши разведчики нашли пещеру, к западу от Хири'ваты." }, { 16.46, "Знахарь Сухокожих, Ти'ик, практикует там своё вуду: гниль, разложение, личинки – вот что питает его гнусную магию." }, { 25.71, "Чтобы эта мерзость ползала по нашим домам, пока мы спим..." }, { 30.56, "Ну уж нет!" }, { 31.37, "Иди добудь его голову и уничтожь то, что они там выращивают." }, { 36.37, "Он силён, так что будь поосторожней, лады?" } } } },
    [98205] = { d = 27.4, v = "goblin-male", n = { x = 298 }, c = { x = { { 0.00, "Мы с моим партнёром Гиззиксом хотим обустроить заставу, и я уже чую запах прибыли!" }, { 6.16, "Впрочем, это может быть просто болотный газ." }, { 9.50, "В любом случае мне нужна помощь." }, { 11.98, "Маленькие чёрные драконы, снующие тут по небу, отнюдь не \"дружелюбны\"." }, { 17.13, "Они даже подпалили бедную Мисс Мелли!" }, { 20.01, "Слушай, ты сможешь неплохо подзаработать, охотясь на этих ужасных дракончиков." }, { 25.83, "Так ты в деле или нет?" } } } },
    [98208] = { d = 39.0, v = "nightelf-female#53", n = { x = 449 }, c = { x = { { 0.00, "Я прибыла в Гавань Менетилов из Аубердина близ великого древа Тельдрассила, чтобы вернуть цветок, имеющий огромное значение для моего народа." }, { 10.11, "Много лун назад здесь потерпел крушение наш корабль \"Орлик\", входивший в состав Третьего кул-тирасского флота." }, { 17.97, "На нём перевозили цветок, известный как Норд'эль – или \"Небесный цветок\" на вашем языке." }, { 24.29, "Он распустился при полной луне на горе Хиджал, которая когда-то была для нас домом." }, { 30.28, "Прошу, помоги мне его вернуть!" }, { 32.53, "Место кораблекрушения расположено к югу от города, но там обитают свирепые мурлоки-налётчики!" } } }, t = { d = 8.7, v = "nightelf-female#53", n = { x = 79 }, c = { x = { { 0.00, "Он уцелел!" }, { 0.90, "О, слава Элуне!" }, { 2.26, "Тысячу раз благодарю." }, { 4.06, "Если ты не против, у меня есть к тебе ещё одна просьба..." } } } } },
    [98209] = { d = 21.4, g = 1, v = "nightelf-female#53", n = { m = 265, f = 267 }, c = { m = { { 0.00, "Не мог бы ты отнести Норд'эль старейшине Тандрису Ветропряду в Аубердин?" }, { 4.76, "Отсюда ты быстро сможешь добраться туда на корабле." }, { 8.25, "Прости, что приходится тебя просить." }, { 10.72, "Я ещё не восстановила силы после тягот путешествия – и бегства от тех несносных мурлоков, накинувшихся на меня, когда я попыталась заполучить священный цветок." } }, f = { { 0.00, "Не могла бы ты отнести Норд'эль старейшине Тандрису Ветропряду в Аубердин?" }, { 4.95, "Отсюда ты быстро сможешь добраться туда на корабле." }, { 8.46, "Прости, что приходится тебя просить." }, { 10.93, "Я ещё не восстановила силы после тягот путешествия – и бегства от тех несносных мурлоков, накинувшихся на меня, когда я попыталась заполучить священный цветок." } } }, t = { d = 29.0, g = 1, v = "nightelf-male#54", n = { m = 308, f = 309 }, c = { m = { { 0.00, "Норд'эль уцелел?" }, { 1.30, "Не может быть... после стольких лет!" }, { 4.05, "Наша богиня поистине чудесна!" }, { 6.39, "Благодарю тебя за то, что доставил его сюда." }, { 9.82, "Это редкий лучик света в тёмные времена, что настали для нас, и символ не только милости Элуны, но и непреклонной воли нашего народа выстоять без бессмертия." }, { 21.77, "Я прослежу, чтобы его благополучно перевезли в Дарнас, где его смогут должным образом вырастить." } }, f = { { 0.00, "Норд'эль уцелел?" }, { 1.30, "Не может быть... после стольких лет!" }, { 4.03, "Наша богиня поистине чудесна!" }, { 6.35, "Благодарю тебя за то, что доставила его сюда." }, { 9.84, "Это редкий лучик света в тёмные времена, что настали для нас, и символ не только милости Элуны, но и непреклонной воли нашего народа выстоять без бессмертия." }, { 21.73, "Я прослежу, чтобы его благополучно перевезли в Дарнас, где его смогут должным образом вырастить." } } } } },
    [98215] = { d = 35.7, v = "goblin-male", n = { x = 419 }, c = { x = { { 0.00, "После всех этих неурядиц с озлобленными дракончиками, пора нам наконец радикально решить проблему." }, { 6.91, "Я про нашу уязвимость к пламени." }, { 9.19, "Я уже довольно долго наблюдаю за этими драконами, и мне кажется, что они невосприимчивы к собственному огню!" }, { 16.80, "По крайней мере, их чешуя точно не горит." }, { 19.78, "Если ты не против немного потрудиться, я с удовольствием заплачу за любую сброшенную чешую, которую ты найдёшь." }, { 27.52, "Если повезёт, мы соберём достаточно, чтобы изготовить для себя защитное снаряжение." }, { 33.29, "Ах да, и для Мелли тоже, конечно же." } } } },
    [98216] = { d = 34.6, v = "dwarf-male", n = { x = 417 }, c = { x = { { 0.00, "Древние боги?!" }, { 1.03, "Это точно не к добру!" }, { 2.55, "Я разобрал на камне отрывок текста, в котором говорится о каком-то хранителе." }, { 7.78, "О чём бы там ни шла речь, это должно быть как-то связано с камнем!" }, { 12.16, "Возьми его с собой и поищи в зоне раскопок какой-нибудь большой объект, созданный титанами." }, { 18.42, "Прочитай последний отрывок текста на камне и посмотри, что произойдёт!" }, { 23.11, "Если я прав, то ты активируешь найденную штуку." }, { 26.27, "Если так и случится, разберись с ней, но постарайся не повредить другие возможные находки!" }, { 32.29, "Нам просто необходимо узнать больше!" } } }, t = { d = 18.2, v = "dwarf-male", n = { x = 208 }, c = { x = { { 0.00, "Посмотри туда!" }, { 1.10, "Видишь, как скрижаль Гоаз начинает светиться вблизи ключа-камня?" }, { 5.84, "Я почти могу разобрать ещё несколько слов..." }, { 9.02, "Нам по-прежнему нужно узнать больше о том, что собой представляет Гоаз." }, { 14.15, "Чувствую, впереди нас ждёт ещё много потрясающих открытий!" } } } } },
    [98219] = { d = 29.7, v = "human-male", n = { x = 351 }, c = { x = { { 0.00, "Ещё раз спасибо за безопасную доставку статуэтки." }, { 3.30, "Мне нужна твоя помощь ещё кое в чём." }, { 5.81, "Есть один городской стражник, которого перевели на службу в Южнобережье, в предгорья Хилсбрада." }, { 12.22, "Его отец был моим другом, и хотя я не спорю, что его стоит научить уму-разуму... мне всё же хочется, чтобы он добился успеха." }, { 20.84, "Помощь кого-то вроде тебя была бы ему очень полезна." }, { 24.57, "Если отправишься в ту сторону, то можешь сесть на корабль из Гавани Менетилов." } } }, t = { d = 7.7, v = "human-male#50", n = { x = 86 }, c = { x = { { 0.00, "А, конечно." }, { 0.88, "Ещё один из лучших представителей Штормграда пришёл проверить меня." }, { 5.92, "Всё как в прошлом месяце!" } } } } },
    [98221] = { d = 37.3, v = "dwarf-male", n = { x = 432 }, c = { x = { { 0.00, "В ходе Второй войны орки из клана Драконьей Пасти построили тут флот, намереваясь захватить Хилсбрад." }, { 7.28, "И затея почти увенчалась успехом!" }, { 9.73, "Их разгромили красные драконы, и уцелевшие орки отступили далеко в горы." }, { 14.94, "Однако они снова зашевелились в лагере к северо-востоку от крепости Менетилов." }, { 20.61, "Дун Альгаз – доказательство того, что они собираются снова развязать войну и попытаться завоевать эти земли." }, { 28.41, "Найди их планы нападения, скопируй самые важные записи и уничтожь оригиналы." }, { 33.95, "Нам нужно знать, где они нанесут следующий удар!" } } }, t = { d = 18.5, v = "dwarf-male", n = { x = 198 }, c = { x = { { 0.00, "И Стальгорн тоже?" }, { 1.27, "Амбиций Некрошу явно не занимать – весь в отца!" }, { 4.82, "Чего ему, конечно, не хватает, так это порабощённой армии красных драконов, что принесла столько разрушений в той войне." }, { 13.74, "Он поставил на кон многое, это точно, – и дорого за это заплатит." } } } } },
    [98223] = { d = 40.0, v = "narrator", n = { x = 423 }, c = { x = { { 0.00, "Эта книга сильно обгорела - возможно, от драконьего огня, уничтожившего большую часть клана Драконьей Пасти." }, { 8.54, "Из того немногого, что можно прочесть, ясно, что в ней описаны ритуалы использования Души Демона, с помощью которой клан подчинял драконов." }, { 19.40, "Книга слишком неполна, чтобы быть по-настоящему полезной, но по грубо вставленным страницам из звериной шкуры похоже, что Нек'рош пытался её спасти." }, { 30.98, "В свежевысохших чернилах упоминается «Совет Теней»." }, { 35.00, "Капитан Крепкий Кулак в Гавани Менетилов захочет об этом узнать." } } }, t = { d = 16.3, v = "dwarf-male", n = { x = 180 }, c = { x = { { 0.00, "Лучше это уничтожить." }, { 1.65, "Полезно оно или нет, мы не станем рисковать с этими мерзкими орками." }, { 6.72, "Только всадников на драконах нам на пороге не хватало!" }, { 10.67, "А это дело с Советом Теней... крайне тревожно." }, { 14.16, "Я немедленно сообщу начальству." } } } } },
    [98230] = { d = 39.8, v = "dwarf-male", n = { x = 459 }, c = { x = { { 0.00, "После войны Трёх Кланов, навсегда положившей конец привычной жизни дворфов, клан Громового Молота поселился здесь и построил горную крепость Грим Батол." }, { 10.90, "Это было чудесное место." }, { 12.77, "Куда ни посмотри, повсюду парили грифоны, пикируя к водоёмам, чтобы поймать рыбу." }, { 18.64, "К сожалению, спокойствие было недолгим." }, { 21.48, "Ховин Мягкое Перо – один из немногих представителей клана Громового Молота, вернувшихся в эти земли спустя долгое время." }, { 30.25, "Он держится особняком, города сторонится." }, { 33.21, "Следуй по дороге на восток – рано или поздно наткнёшься на него." }, { 37.86, "Ему определённо нужна помощь." } } }, t = { d = 5.8, g = 1, v = "dwarf-male", n = { m = 55, f = 55 }, c = { m = { { 0.00, "Если пришёл помочь, не откажусь." }, { 2.80, "Помощь нынче днём с огнём не сыщешь." } }, f = { { 0.00, "Если пришла помочь, не откажусь." }, { 2.73, "Помощь нынче днём с огнём не сыщешь." } } } } },
    [98231] = { d = 41.1, v = "goblin-male#109", n = { x = 441 }, c = { x = { { 0.00, "Мисс Мелли сильно досталось – её обожгло огненное дыхание дракончиков." }, { 5.30, "Полагаю, они её изрядно напугали." }, { 7.88, "Я никак не могу заставить её сдвинуться с места!" }, { 11.55, "Слушай-ка, у меня появилась идея." }, { 14.14, "Как-то раз я купил одно подозрительное зелье, которое, разумеется, не подействовало так, как было заявлено, но всё же заживило мне порез." }, { 24.33, "Одним из активных ингредиентов якобы была трава под названием змейкин хвост, которая растёт в этих краях." }, { 32.28, "Если моя догадка верна, мы сможем залечить ожоги Мисс Мелли." }, { 36.97, "Сходи поищи эту траву и принеси мне!" }, { 39.83, "Попытка не пытка." } } } },
    [98233] = { d = 34.5, v = "human-male", n = { x = 436 }, c = { x = { { 0.00, "Несколько дней назад мы с приятелями сидели вечером в таверне, и они предложили мне в одиночку сразиться с одним из этих мерзких слизнюков." }, { 8.91, "Поскольку у меня, как видишь, при себе нет меча, ты уже, наверное, догадываешься, чем всё закончилось." }, { 15.40, "Когда я нанёс первый удар, мой меч застрял и весь замысел пошёл насмарку." }, { 20.03, "Мне нужно вернуть оружие, прежде чем сержант поймёт, что я его потерял!" }, { 24.60, "Клинок до сих пор должен торчать из слизнюка, обитающего где-то к западу отсюда, по ту сторону залива." }, { 31.14, "Пожалуйста, поищи его, если отправишься в ту сторону." } } } },
    [98240] = { d = 28.0, v = "human-male", n = { x = 339 }, c = { x = { { 0.00, "Вести о дракончиках быстро разлетелись." }, { 2.64, "У нас уже есть один заказ!" }, { 4.44, "Я красиво его упакую, а ты отнесёшь клиенту." }, { 7.38, "Я всё прекрасно понимаю, так что об услуге прошу в последний раз, обещаю!" }, { 12.18, "Этот заказ сделал некий Ховин Мягкое Перо." }, { 15.18, "К слову, для этого он отправил в город своего грифона с письмом!" }, { 19.50, "Пишет, что он находится чуть в стороне от восточной дороги, немного дальше области раскопок Вельгара, если тебе знакомы те места." } } }, t = { d = 4.2, g = 1, v = "dwarf-male", n = { m = 36, f = 37 }, c = { m = { { 0.00, "То, что надо." }, { 1.22, "Спасибо, что проделал такой путь." } }, f = { { 0.00, "То, что надо." }, { 1.25, "Спасибо, что проделала такой путь." } } } } },
    [98245] = { d = 37.0, v = "dwarf-male", n = { x = 423 }, c = { x = { { 0.00, "Даже не знаю, кого я ненавижу больше: проклятый клан Чёрного Железа, орков Драконьей Пасти или тех драконов, на которых они ездят." }, { 9.36, "Я намерен воздать негодяям по заслугам." }, { 12.69, "Но нам понадобятся кое-какие припасы." }, { 15.38, "Эти чешуйки дракончиков неплохо защитят от огненного дыхания, но их до невозможности трудно сшивать." }, { 22.49, "Хищные острозубы на гряде Ящеров к северо-востоку и в долине Солевого Тумана к северо-западу получили своё название не просто так." }, { 31.79, "Их острые зубы должны легко пробить чешуйки." }, { 35.05, "Принеси мне горсть их клыков." } } }, t = { d = 3.8, v = "dwarf-male", n = { x = 36 }, c = { x = { { 0.00, "Из них выйдет прекрасный набор шил." }, { 3.19, "Спасибо." } } } } },
    [98246] = { d = 31.0, v = "dwarf-male", n = { x = 361 }, c = { x = { { 0.00, "Чтобы претворить план в жизнь, мне понадобятся яйца." }, { 3.63, "Глухоклюву надо как следует подкрепиться – я не собираюсь седлать озлобленного от голода грифона." }, { 10.43, "Яйца должны быть первосортными, без трещин или ещё каких изъянов." }, { 15.07, "Добыть их можешь у острозубых ящеров – в их яйцах желтки размером с голову гнома." }, { 20.86, "Этих зверюг можно найти на гряде Ящеров на северо-востоке и в долине Солевого Тумана на северо-западе." }, { 28.18, "Собери-ка на всякий случай сразу дюжину." } } }, t = { d = 17.4, v = "dwarf-male", n = { x = 195 }, c = { x = { { 0.00, "Они не для самого плана – они нужны, чтобы покормить Глухоклюв." }, { 4.60, "Уж поверь на слово, от неё голодной совсем толку не будет." }, { 8.76, "Эта зверюга может быть опаснее орков, если её разозлить!" }, { 12.85, "В последнее время в этих землях трудно найти неиспорченную еду..." } } } } },
    [98247] = { d = 32.3, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "На боку заполненного ящика наклеена порванная этикетка." }, { 4.20, "Хотя имя адресата не сохранилось, на ней можно разобрать сведения о том, откуда был отправлен груз." }, { 11.59, "\"Собственность \"Азеротского торгового управления\"." }, { 15.32, "Пустые ящики и недоставленные грузы просим возвращать в наш торговый пункт у Трёх Углов в Красногорье." }, { 22.98, "Курьеров вознаградят за потраченное время и проделанный путь\"." }, { 27.59, "Рядом с текстом есть грубый набросок карты упомянутой местности." } } }, t = { d = 33.7, g = 1, v = "human-female#47", n = { m = 434, f = 436 }, c = { m = { { 0.00, "Ты пришёл именно туда, куда надо." }, { 2.17, "Я с радостью запишу тебя в перечень наших подрядчиков." }, { 5.65, "Никаких контрактов подписывать не надо, да и особых обязанностей у тебя не будет." }, { 10.79, "Мы лишь просим, чтобы ты доставлял по адресу или возвращал нам принадлежащие управлению грузы, которые попадутся тебе в странствиях." }, { 19.12, "За каждую такую доставку ты получишь торговые обязательства." }, { 22.95, "С их помощью ты сможешь платить нам за товары и услуги." }, { 26.43, "Кстати, вот тебе сразу кое-что для начала." }, { 29.17, "Теперь скажи, у тебя есть ящик, на который была наклеена эта этикетка?" } }, f = { { 0.00, "Ты пришла именно туда, куда надо." }, { 2.22, "Я с радостью запишу тебя в перечень наших подрядчиков." }, { 5.69, "Никаких контрактов подписывать не надо, да и особых обязанностей у тебя не будет." }, { 10.82, "Мы лишь просим, чтобы ты доставляла по адресу или возвращала нам принадлежащие управлению грузы, которые попадутся тебе в странствиях." }, { 19.24, "За каждую такую доставку ты получишь торговые обязательства." }, { 23.06, "С их помощью ты сможешь платить нам за товары и услуги." }, { 26.53, "Кстати, вот тебе сразу кое-что для начала." }, { 29.26, "Теперь скажи, у тебя есть ящик, на который была наклеена эта этикетка?" } } } } },
    [98248] = { d = 32.5, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "На боку заполненного ящика наклеена порванная этикетка." }, { 4.23, "Хотя имя адресата не сохранилось, на ней можно разобрать сведения о том, откуда был отправлен груз." }, { 11.67, "\"Просим возвращать повреждённые грузы и пустые ящики на торговый пост \"Дуротарского снабжения и логистики\", теперь удобно расположенный к западу от Перекрёстка в Степях." }, { 24.23, "Мы ценим ваше время и вознаградим за усилия!\"" }, { 27.71, "Рядом с текстом есть грубый набросок карты упомянутой местности." } } }, t = { d = 35.8, g = 1, v = "orc-female", n = { m = 419, f = 419 }, c = { m = { { 0.00, "Ты нашёл нужное место и разговариваешь именно с той, с кем надо!" }, { 4.42, "Я запишу тебя в перечень наших подрядчиков." }, { 7.51, "Тебе о бумажной волоките беспокоиться не надо, я сама уже от неё устала." }, { 12.63, "Мы просим лишь помогать нам в доставке и возвращении утерянных грузов, которые попадутся в твоих странствиях." }, { 20.20, "За это ты получишь торговые обязательства, которые позволят платить нам за различные товары и услуги." }, { 27.27, "Вот тебе сразу кое-что, чтобы поднять настроение!" }, { 30.81, "У тебя, случайно, нет ещё и ящика, на который была наклеена эта этикетка?" } }, f = { { 0.00, "Ты нашла нужное место и разговариваешь именно с той, с кем надо!" }, { 4.44, "Я запишу тебя в перечень наших подрядчиков." }, { 7.51, "Тебе о бумажной волоките беспокоиться не надо, я сама уже от неё устала." }, { 12.58, "Мы просим лишь помогать нам в доставке и возвращении утерянных грузов, которые попадутся в твоих странствиях." }, { 20.09, "За это ты получишь торговые обязательства, которые позволят платить нам за различные товары и услуги." }, { 27.10, "Вот тебе сразу кое-что, чтобы поднять настроение!" }, { 30.61, "У тебя, случайно, нет ещё и ящика, на который была наклеена эта этикетка?" } } } } },
    [98251] = { d = 38.6, g = 1, v = "orc-male", n = { m = 390, f = 392 }, c = { m = { { 0.00, "А-а-а!" }, { 0.57, "Просто зло берёт." }, { 1.94, "Говорили, в Ясеневом лесу легко ориентироваться." }, { 5.81, "Кому легко?" }, { 6.81, "Зверью?" }, { 7.46, "Птицам?" }, { 8.11, "Собираешь себе травы, как вдруг оказываешься в каком-то овраге." }, { 13.13, "Неужели тут действительно нужно обойти половину леса, чтобы вернуться туда, где был лишь мгновение назад?" }, { 21.52, "Когда я в таком настроении, мои заклинания становятся непредсказуемыми и действуют... иначе." }, { 28.84, "Не мог бы ты проредить местную живность?" }, { 31.99, "Даже топот их негодных копыт сводит меня с ума." }, { 35.94, "Ненавижу этот проклятый лес." } }, f = { { 0.00, "А-а-а!" }, { 0.57, "Просто зло берёт." }, { 1.92, "Говорили, в Ясеневом лесу легко ориентироваться." }, { 5.77, "Кому легко?" }, { 6.76, "Зверью?" }, { 7.40, "Птицам?" }, { 8.04, "Собираешь себе травы, как вдруг оказываешься в каком-то овраге." }, { 13.03, "Неужели тут действительно нужно обойти половину леса, чтобы вернуться туда, где был лишь мгновение назад?" }, { 21.35, "Когда я в таком настроении, мои заклинания становятся непредсказуемыми и действуют... иначе." }, { 28.61, "Не могла бы ты проредить местную живность?" }, { 31.78, "Даже топот их негодных копыт сводит меня с ума." }, { 36.50, "Ненавижу этот проклятый лес." } } }, t = { d = 6.0, v = "orc-male", n = { x = 40 }, c = { x = { { 0.00, "Ха!" }, { 0.41, "Так вам, твари!" }, { 2.13, "Спасибо." }, { 3.14, "Кажется, это уже помогло." } } } } },
    [98252] = { d = 38.2, v = "orc-male", n = { x = 393 }, c = { x = { { 0.00, "Выведи моё око Килрогга из этого оврага и покажи путь к дороге." }, { 4.98, "Я последую за вами, когда увижу расчищенный путь." }, { 8.84, "Пока же останусь здесь – кому-то из нас нужно следить, чтобы мы не потерялись." }, { 14.88, "Если собьёшься с пути, я смогу привести тебя назад с помощью ока." }, { 20.07, "Не хочу, чтобы мы вместе вслепую шатались по этому жуткому лесу." }, { 25.19, "Моей силы хватит, чтобы поддерживать связь четыре минуты – ни мгновением дольше." }, { 31.50, "Доберись до дороги, прежде чем связь прервётся, или вернись ко мне, и мы попробуем снова." } } }, t = { d = 24.5, v = "orc-male", n = { x = 160 }, c = { x = { { 0.00, "*Ты слышишь голос Ва'зага, раздающийся из парящего ока.*" }, { 4.96, "«Неужели всё было так просто?" }, { 7.46, "Неважно." }, { 8.21, "Это видение поможет мне направить моего непокорного демона Бездны по верному пути, когда я снова его призову." }, { 17.60, "Спасибо, путник." }, { 19.04, "Ступай через этот лес уверенно»." }, { 21.76, "*Око Килрогга начинает рассеиваться.*" } } } } },
    [98282] = { d = 41.7, v = "human-female", n = { x = 490 }, c = { x = { { 0.00, "Некоторые алхимические рецепты требуют ингредиентов, которые собирают, скажем так, в крайне небезопасных местах." }, { 7.91, "И зачастую это всего лишь базовые травы!" }, { 10.84, "А есть такие ингредиенты, которые вообще добыть практически невозможно!" }, { 15.88, "Прежде чем я снова смогу отправиться в путь, мне нужно изготовить побольше противоядия." }, { 22.00, "Честное слово, в этом болоте всё ядовито." }, { 24.99, "Как будто отрава пропитала саму землю!" }, { 27.80, "Ты поможешь мне?" }, { 28.95, "Мне нужна ядовитая железа пауков из пещеры Тельгена далеко на юго-востоке." }, { 34.30, "Но она должна быть неповреждённой, иначе по дороге обратно из неё выльется слишком много яда." }, { 40.87, "Ты уж извини!" } } }, t = { d = 12.4, v = "human-female", n = { x = 131 }, c = { x = { { 0.00, "О, прекрасно!" }, { 1.01, "Это именно то, что мне нужно." }, { 3.22, "Ты настоящий герой, знаешь ли." }, { 5.50, "Позволь поделиться с тобой плодами твоих же трудов – иначе было бы нечестно." }, { 11.27, "Береги себя там!" } } } } },
    [98283] = { d = 44.0, v = "creature/ancient", n = { x = 435 }, c = { x = { { 0.00, "Естественный ход вещей в природе этого края нарушен." }, { 4.47, "Раньше хищные острозубы сдерживали разрастание леса." }, { 8.94, "Теперь они живут в страхе перед своим вожаком, получившим имя из-за того, какую кровавую бойню он постоянно устраивает всюду, куда бы ни пошёл." }, { 21.21, "Боюсь, зверь сошёл с ума от болезни, которую мы ещё не полностью искоренили." }, { 27.49, "Его наверняка привлечёт заражённая плоть больных медведей, обитающих у подножия гряды Ящеров на северо-востоке." }, { 36.66, "Разбросай их внутренности в его логове." }, { 39.99, "Резун непременно явится." }, { 42.11, "Принеси мне его голову." } } }, t = { d = 15.9, v = "creature/ancient", n = { x = 136 }, c = { x = { { 0.00, "Смерть Резуна вернёт равновесие его стае." }, { 4.02, "Возможно, это даст время и всей экосистеме, которую они поддерживают." }, { 10.75, "Посмотрим, но в любом случае спасибо тебе за старания." } } } } },
    [98284] = { d = 25.0, v = "skyborne-male", n = { x = 277 }, c = { x = { { 0.00, "Зачаровыватели делают всё лучше, и их привечают в любом походном лагере." }, { 5.38, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать зачарованную лютню для своего лагеря." }, { 12.92, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы, какие только могут встретиться в странствиях." } } }, t = { d = 28.6, g = 1, v = "skyborne-male", n = { m = 322, f = 323 }, c = { m = { { 0.00, "Вот и всё – теперь ты можешь создать собственную зачарованную лютню." }, { 4.87, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 13.57, "Да, и помни: без костра никакого лагеря не получится." }, { 17.40, "Сначала придётся его разжечь." }, { 19.54, "Этому может научить почти любой повар." }, { 22.46, "Если ещё не озаботился этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } }, f = { { 0.00, "Вот и всё – теперь ты можешь создать собственную зачарованную лютню." }, { 4.87, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 13.57, "Да, и помни: без костра никакого лагеря не получится." }, { 17.40, "Сначала придётся его разжечь." }, { 19.55, "Этому может научить почти любой повар." }, { 22.47, "Если ещё не озаботилась этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } } } } },
    [98285] = { d = 20.2, v = "gnome-male", n = { x = 257 }, c = { x = { { 0.00, "Главное для инженера – изобретательность, и если вдруг ты окажешься в одиночку в какой-нибудь глуши, всегда можно найти приложение своему ремеслу." }, { 9.51, "Ни один лагерь не будет полноценным без пары полезных механизмов!" }, { 13.82, "Когда наберёшься опыта в инженерном деле, приходи ко мне – я научу тебя создавать кое-что особенное!" } } }, t = { d = 28.7, g = 1, v = "gnome-male", n = { m = 351, f = 352 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственного реагентобота." }, { 3.67, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 8.34, "Лучше отправляйся куда-нибудь в дикие места." }, { 11.29, "А, и помни, что никакого лагеря без костра не получится." }, { 14.96, "Так что сначала придётся разжечь костёр." }, { 17.50, "Этому тебя может научить почти любой специалист по кулинарии." }, { 21.64, "Если ещё не озаботился этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственного реагентобота." }, { 3.75, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 8.53, "Лучше отправляйся куда-нибудь в дикие места." }, { 11.56, "А, и помни, что никакого лагеря без костра не получится." }, { 15.31, "Так что сначала придётся разжечь костёр." }, { 17.91, "Этому тебя может научить почти любой специалист по кулинарии." }, { 22.14, "Если ещё не озаботилась этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } } } } },
