    [98287] = { d = 23.0, v = "human-male", n = { x = 287 }, c = { x = { { 0.00, "Инженеры вроде тебя могут конструировать всяческие приблуды, прибамбасы и бомбы, чтобы развлекаться и зарабатывать." }, { 7.76, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать реагентобота для твоего лагеря." }, { 14.13, "Этот славный автоматон помогает с припасами, чтобы у тебя и твоих союзников всегда были материалы, необходимые для ваших заклинаний." } } } },
    [98291] = { d = 37.0, g = 1, v = "dwarf-male", n = { m = 447, f = 448 }, c = { m = { { 0.00, "Я собираюсь вернуться в Грим Батол и отвоевать его для клана Громового Молота." }, { 5.31, "Или хотя бы разузнать побольше." }, { 7.51, "Не надо на меня так таращиться." }, { 9.64, "Я понимаю риски и не собираюсь просто так размахивать молотом, знаешь ли." }, { 14.58, "В любом случае сначала мне понадобится твоя помощь." }, { 18.12, "Орки Драконьей Пасти уже наступают." }, { 20.63, "Они повсюду в Убежище Драконьей Пасти, где красные драконы их когда-то разбили." }, { 26.06, "Мне нужно, чтобы ты проредил их ряды." }, { 28.62, "Так у меня появится хоть какой-то шанс подобраться поближе." }, { 32.59, "Если пойдёшь по дороге на восток, то непременно с ними встретишься." } }, f = { { 0.00, "Я собираюсь вернуться в Грим Батол и отвоевать его для клана Громового Молота." }, { 5.28, "Или хотя бы разузнать побольше." }, { 7.46, "Не надо на меня так таращиться." }, { 9.58, "Я понимаю риски и не собираюсь просто так размахивать молотом, знаешь ли." }, { 14.50, "В любом случае сначала мне понадобится твоя помощь." }, { 18.02, "Орки Драконьей Пасти уже наступают." }, { 20.50, "Они повсюду в Убежище Драконьей Пасти, где красные драконы их когда-то разбили." }, { 25.90, "Мне нужно, чтобы ты проредила их ряды." }, { 28.51, "Так у меня появится хоть какой-то шанс подобраться поближе." }, { 32.45, "Если пойдёшь по дороге на восток, то непременно с ними встретишься." } } }, t = { d = 4.3, v = "dwarf-male", n = { x = 45 }, c = { x = { { 0.00, "Уж я-то по таким горевать не стану." }, { 2.79, "Получили по заслугам." } } } } },
    [98293] = { d = 18.6, v = "narrator", n = { x = 214 }, c = { x = { { 0.00, "Орки из клана Драконьей Пасти собирают самое разное оружие." }, { 4.51, "Было бы разумно избавить их от этих запасов, прежде чем они смогут вооружить ещё больше солдат." }, { 11.62, "Капитана Крепкого Кулака в крепости Менетил наверняка заинтересует возможность пополнить арсенал." } } }, t = { d = 16.3, g = 1, v = "dwarf-male", n = { x = 167 }, c = { m = { { 0.00, "Отлично!" }, { 0.69, "Просто отлично!" }, { 1.93, "Это оружие нам точно пригодится для пополнения войск." }, { 6.01, "Да половина его и так принадлежала нашим солдатам." }, { 9.88, "Поменьше оружия у врага и побольше у нас – вот такая арифметика мне по душе, герой." } }, f = { { 0.00, "Отлично!" }, { 0.69, "Просто отлично!" }, { 1.95, "Это оружие нам точно пригодится для пополнения войск." }, { 6.05, "Да половина его и так принадлежала нашим солдатам." }, { 9.94, "Поменьше оружия у врага и побольше у нас – вот такая арифметика мне по душе, героиня." } } } } },
    [98297] = { d = 36.1, v = "dwarf-male", n = { x = 404 }, c = { x = { { 0.00, "Пока тебя не было, я совершил короткий пробный полёт." }, { 3.94, "Есть хорошая новость: броня, которую мы с тобой изготовили для Глухоклюв, просто бесподобна!" }, { 10.65, "Но есть и плохая: я видел, как орки Драконьей Пасти подчинили красного драконоида." }, { 16.63, "Ну уж нет, снова им такого позволить нельзя." }, { 19.86, "Тебе надо его уничтожить." }, { 21.83, "Без помощи друзей тут, ясное дело, никак не обойтись." }, { 25.77, "Сначала убей чернокнижников, которые удерживают дракона, а затем избавь его от мучений." }, { 32.22, "Мы не позволим никому преградить путь Громовому Молоту." } } }, t = { d = 25.4, g = 1, v = "dwarf-male", n = { m = 270, f = 271 }, c = { m = { { 0.00, "Не знаю, как тебя и благодарить." }, { 2.44, "Право слово, мне в жизни не отплатить за то, что ты сегодня сделал." }, { 7.46, "Ещё многое предстоит сделать, прежде чем в залах Грим Батола снова зазвенит смех маленьких дворфов, но это славный шаг вперёд." }, { 16.88, "Ради всех дворфов, что сгинули в те тёмные дни, мы ещё вернём то, что было нашим." }, { 22.77, "По крайней мере, будем надеяться." } }, f = { { 0.00, "Не знаю, как тебя и благодарить." }, { 2.46, "Право слово, мне в жизни не отплатить за то, что ты сегодня сделала." }, { 7.57, "Ещё многое предстоит сделать, прежде чем в залах Грим Батола снова зазвенит смех маленьких дворфов, но это славный шаг вперёд." }, { 17.06, "Ради всех дворфов, что сгинули в те тёмные дни, мы ещё вернём то, что было нашим." }, { 23.00, "По крайней мере, будем надеяться." } } } } },
    [98298] = { d = 43.5, v = "scourge-male#82", n = { x = 409 }, c = { x = { { 0.00, "А, теперь всё до смешного ясно!" }, { 2.69, "Аругал едва владел магией – о силе, необходимой для сотворения воргенов, не идёт и речи." }, { 10.23, "Проклятие Аругала..." }, { 12.00, "Пф!" }, { 12.30, "Да оно такое слабое, что и минуты не держится." }, { 16.30, "Эти оковы доказывают, что он может подчинять этих чудовищ, а не создавать их." }, { 22.91, "Проклятие воргенов явно распространяется иначе – и я хочу узнать, как именно." }, { 29.53, "Отправляйся на юг, к Стене Седогрива." }, { 32.68, "Похоже, воргены заражают обитающих там людей." }, { 36.60, "Истреби чудовищ и принеси всё, что найдёшь." }, { 40.22, "Пришло время для более прямого подхода." } } }, t = { d = 32.0, v = "scourge-male#82", n = { x = 291 }, c = { x = { { 0.00, "Похоже, последним смеюсь всё-таки я, ха-ха!" }, { 3.87, "Аругал и впрямь был глупцом." }, { 6.37, "А я, Далар Ткач Рассвета, разоблачил его как мошенника." }, { 11.28, "Эти останки – всё доказательство, какое мне нужно: проклятие не имеет к этому пустоголовому болвану никакого отношения." }, { 21.92, "Увы, это значит, что и его средство ничего не стоит." }, { 26.76, "Похоже, поиски лекарства от проклятия воргенов продолжаются." } } } } },
    [98299] = { d = 44.2, g = 1, v = "scourge-male#82", n = { x = 410 }, c = { m = { { 0.00, "Нам точно известно, что за появлением воргенов в Серебряном бору стоит Аругал." }, { 6.51, "Возможно, он опять что-то задумал, а может, дело в чём-то ещё." }, { 11.67, "Чего мы не знаем, так это того, как распространяется проклятие." }, { 16.90, "Пока я ищу способ остановить его, нам срочно нужно предотвратить новое заражение." }, { 23.79, "Похоже, Отрёкшиеся неспособны подхватить эту хворь, но у Стены Седогрива собралась большая группа людей." }, { 32.39, "Ступай туда и избавься от этих беженцев, пока они не стали прислужниками Аругала." }, { 39.27, "И смотри, чтобы тебя не укусили, герой." } }, f = { { 0.00, "Нам точно известно, что за появлением воргенов в Серебряном бору стоит Аругал." }, { 6.74, "Возможно, он опять что-то задумал, а может, дело в чём-то ещё." }, { 12.09, "Чего мы не знаем, так это того, как распространяется проклятие." }, { 17.51, "Пока я ищу способ остановить его, нам срочно нужно предотвратить новое заражение." }, { 24.64, "Похоже, Отрёкшиеся неспособны подхватить эту хворь, но у Стены Седогрива собралась большая группа людей." }, { 33.55, "Ступай туда и избавься от этих беженцев, пока они не стали прислужниками Аругала." }, { 40.68, "И смотри, чтобы тебя не укусили, героиня." } } }, t = { d = 18.5, v = "scourge-male#82", n = { x = 181 }, c = { x = { { 0.00, "Гилнеасцы не спешат пускать посторонних за свою стену." }, { 4.72, "Пожалуй, это даже к лучшему." }, { 7.27, "Так проклятие воргенов вряд ли распространится в их городе." }, { 12.22, "Представляешь, какой хаос начнётся, если будет заражено целое королевство?" } } } } },
    [98300] = { d = 34.8, v = "dwarf-male", n = { x = 400 }, c = { x = { { 0.00, "У меня тут ещё полным-полно работы, и мне нужно передать весточку моей жене Клайре в Заоблачный пик." }, { 7.22, "А ещё сообщить Фалстаду новости." }, { 9.54, "Но это моё дело." }, { 10.77, "Дело Громового Молота." }, { 12.44, "Тем не менее тебе следует сообщить обо всём королю Магни Бронзобороду в Стальгорне." }, { 18.37, "Болотина расположена почти вплотную к его землям, и события тут не предвещают ничего хорошего." }, { 25.14, "Отнеси ему это письмо." }, { 26.89, "Чтобы добраться до Стальгорна, ты можешь пройти через Дун Альгаз или отправиться по воздуху из Гавани Менетилов." } } }, t = { d = 38.6, v = "dwarf-male#177", n = { x = 387 }, c = { x = { { 0.00, "А, Громовые Молоты." }, { 1.63, "Да, я хорошо их знаю." }, { 3.42, "Пусть они и не признают меня своим государем, но в последнее время наши отношения сильно улучшились – Мост Тандола тому свидетельство." }, { 14.49, "Если донесение этого Ховина правдиво, нам следует готовиться к дальнейшим действиям на северных рубежах." }, { 23.11, "У Грим Батола давняя кровавая история, и я прекрасно понимаю его стратегическое значение." }, { 30.46, "За помощь Громовым Молотам в Болотине, а также Альянсу в Гавани Менетилов прими мою благодарность." } } } } },
    [98310] = { d = 36.9, v = "dwarf-male", n = { x = 405 }, c = { x = { { 0.00, "В Болотине обнаружены и другие, более крупные големы." }, { 4.02, "На них выгравированы надписи \"Адос\", \"Модр\", \"Голм\" и \"Неру\", соответствующие недостающим частям найденной тобой скрижали Гоаз!" }, { 13.35, "Готов поспорить, что если мы добудем недостающие части, то узнаем о скрижали Гоаз ещё больше!" }, { 20.32, "Адос ты найдёшь у врат Драконьей Пасти на востоке, недалеко от Грим Батола." }, { 25.83, "Модр находится прямо за Дун Модром на севере." }, { 29.18, "Голм лежит под Грим Батолом, к востоку от Дун Альгаза." }, { 33.14, "Неру ты найдёшь за Зловещим холмом на северо-востоке." } } }, t = { d = 26.2, v = "dwarf-male", n = { x = 202 }, c = { x = { { 0.00, "Клянусь бородой Магни, какая красота!" }, { 3.15, "Погоди-ка, ты это видишь?!" }, { 5.35, "Поднеси сердца поближе к скрижали Гоаз..." }, { 8.72, "*На камне в слабом мерцающем свете проступает новая надпись.*" }, { 14.00, "Хм, трудно разобрать." }, { 15.74, "«Проклятие плоти... они потерпят неудачу»." }, { 19.21, "Что бы это значило?!" }, { 20.88, "Надо отнести камень в надёжное место, чтобы изучить его подробнее!" } } } } },
    [98313] = { d = 26.1, v = "dwarf-male", n = { x = 292 }, c = { x = { { 0.00, "С чем бы мы ни имели тут дело, это действительно нечто невероятное." }, { 4.86, "Я всё для тебя аккуратно упакую." }, { 7.23, "Отнеси предметы историку Карнику в Зал Исследователей в Стальгорне." }, { 12.09, "Обычно его можно найти в глубине библиотеки, уткнувшегося носом в какой-нибудь том." }, { 18.21, "Чтобы докопаться до истины, потребуется целая армия, но, судя по тому, что нам уже известно, оно того стоит!" } } }, t = { d = 18.1, v = "dwarf-male", n = { x = 198 }, c = { x = { { 0.00, "Ну и ну..." }, { 0.74, "Здесь столько всего, что придётся разбирать!" }, { 3.97, "Но как же интересно." }, { 5.44, "ОЧЕНЬ интересно!" }, { 6.72, "Мне понадобится время, чтобы хотя бы составить план." }, { 10.62, "Загляни как-нибудь потом, и я расскажу тебе новости." }, { 14.58, "А пока прими благодарность Лиги исследователей." } } } } },
    [98319] = { d = 33.0, v = "dwarf-female#33", n = { x = 362 }, c = { x = { { 0.00, "С троллями и так проблем не оберёшься, а тут ещё и горы кишат вендиго!" }, { 5.12, "Обычно они не покидают свои пещеры, но в последнее время, видно, расплодились как кролики и заполонили Серую берлогу к северу отсюда." }, { 15.17, "Если хотим предоставить Белобороду отчёт, то придётся нам разыскать моего напарника Корнелия." }, { 22.05, "Этот болван переволновался и сломя голову ринулся в бой." }, { 26.30, "Храбро, но глупо." }, { 27.65, "Иди в пещеру и поищи его." }, { 29.67, "А заодно можешь уничтожить несколько чудовищ." } } }, t = { d = 5.1, v = "dwarf-female#33", n = { x = 45 }, c = { x = { { 0.00, "Эх, дурень..." }, { 1.22, "Спасибо за помощь." }, { 2.93, "Теперь сможем отчитаться." } } } } },
    [98321] = { d = 28.2, g = 1, v = "dwarf-male", n = { m = 316, f = 318 }, c = { m = { { 0.00, "Ага!" }, { 0.38, "Приятно встретить героя, который не боится замарать руки." }, { 4.44, "Если ищешь работу, боюсь, у меня сейчас туго с материалами." }, { 8.70, "На наш самый надёжный источник руды напали вендиго, и теперь пещера заброшена." }, { 14.14, "Рудокопам пришлось всё побросать и спасаться бегством." }, { 17.89, "Скажи-ка, не мог бы ты заглянуть в Серую берлогу к западу отсюда и поискать там предназначенные для нас припасы?" }, { 25.53, "Нам бы это очень помогло." } }, f = { { 0.00, "Ага!" }, { 0.38, "Приятно встретить героиню, которая не боится замарать руки." }, { 4.67, "Если ищешь работу, боюсь, у меня сейчас туго с материалами." }, { 9.03, "На наш самый надёжный источник руды напали вендиго, и теперь пещера заброшена." }, { 14.60, "Рудокопам пришлось всё побросать и спасаться бегством." }, { 18.44, "Скажи-ка, не могла бы ты заглянуть в Серую берлогу к западу отсюда и поискать там предназначенные для нас припасы?" }, { 26.45, "Нам бы это очень помогло." } } }, t = { d = 6.9, v = "dwarf-male", n = { x = 66 }, c = { x = { { 0.00, "Вот это другое дело!" }, { 1.86, "С такими поставками кузня скоро снова заработает на полную!" } } } } },
    [98322] = { d = 27.6, v = "dwarf-male", n = { x = 301 }, c = { x = { { 0.00, "Ползать в тёмных пещерах – это дело искателей приключений, а моя работа – составлять отчёты и слать их в Стальгорн." }, { 8.22, "Но на один из моих отчётов... не ответили." }, { 11.24, "Я написал горным пехотинцам о наших бедах с вендиго, а в ответ ни слова." }, { 16.57, "Раз ты всё равно собираешься в путь, почему бы тебе не зайти к горному пехотинцу Гретхен?" }, { 23.01, "Её можно найти к западу от города." }, { 25.58, "У меня уже все сроки прошли!" } } }, t = { d = 6.6, v = "dwarf-female#33", n = { x = 69 }, c = { x = { { 0.00, "Так тебя послал старина Белобород?" }, { 2.75, "Есть мне что ему доложить." }, { 4.80, "У нас тут полный бардак!" } } } } },
    [98323] = { d = 25.4, g = 1, v = "dwarf-female#33", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Надеюсь, ты там много монстров поубивал." }, { 2.81, "Жаль Корнелия, конечно." }, { 4.51, "С твоих слов, нам и докладывать-то не о чем, кроме того, что от пещеры теперь лучше держаться подальше." }, { 11.56, "Белобороду это не понравится, но в эту смертельную ловушку я никого отправлять больше не решусь." }, { 18.25, "Доложи о ситуации." }, { 19.56, "Я отсюда никуда не уйду, пока обстановка на горе не станет снова безопасной." } }, f = { { 0.00, "Надеюсь, ты там много монстров поубивала." }, { 2.95, "Жаль Корнелия, конечно." }, { 4.66, "С твоих слов, нам и докладывать-то не о чем, кроме того, что от пещеры теперь лучше держаться подальше." }, { 11.90, "Белобороду это не понравится, но в эту смертельную ловушку я никого отправлять больше не решусь." }, { 18.76, "Доложи о ситуации." }, { 20.11, "Я отсюда никуда не уйду, пока обстановка на горе не станет снова безопасной." } } }, t = { d = 10.1, v = "dwarf-male", n = { x = 55 }, c = { x = { { 0.00, "Там повсюду монстры?" }, { 1.96, "Я даже не удивлён." }, { 3.66, "Что ж, это тоже укажем в отчёте." }, { 6.64, "*Сенир кладёт письмо Гретхен в стопку заметок.*" } } } } },
    [98325] = { d = 28.9, g = 1, v = "orc-male", n = { x = 250 }, c = { m = { { 0.00, "Я ищу лучших, что есть у Орды, герой." }, { 3.12, "И ТОЛЬКО лучших." }, { 4.53, "Есть задания, для которых нужна доблесть, какой обладают немногие." }, { 10.02, "И ещё меньше тех, кто готов рискнуть всем, когда это действительно важно." }, { 16.03, "Хватит ли у тебя духа, путник, сделать то, что должно быть сделано?" }, { 21.59, "Если да — давай поговорим." }, { 23.82, "Если нет — прочь." }, { 25.23, "У меня нет времени на трусов." } }, f = { { 0.00, "Я ищу лучших, что есть у Орды, героиня." }, { 3.43, "И ТОЛЬКО лучших." }, { 4.84, "Есть задания, для которых нужна доблесть, какой обладают немногие." }, { 10.33, "И ещё меньше тех, кто готов рискнуть всем, когда это действительно важно." }, { 16.34, "Хватит ли у тебя духа, путница, сделать то, что должно быть сделано?" }, { 22.96, "Если да — давай поговорим." }, { 25.19, "Если нет — прочь." }, { 26.60, "У меня нет времени на трусов." } } } },
    [98326] = { d = 32.8, v = "dwarf-female", n = { x = 381 }, c = { x = { { 0.00, "Ты хоть знаешь, как трудно рыбачить на замёрзшем озере?" }, { 3.74, "Мой бедный муж Пакстон уже несколько дней там торчит, а улова едва наберётся на один мешок." }, { 10.04, "Вернее, мешок у нас был, пока распроклятый вендиго не напал на меня и не стащил нашу рыбу." }, { 16.35, "У нас недели уйдут на то, чтобы снова наловить рыбы!" }, { 20.03, "Если, конечно, этот горлопан Ледяной Вой не испортил весь клёв." }, { 24.39, "Сделай одолжение и верни наш улов, ладно?" }, { 27.33, "Этот слюнявый громила скрывается где-то в глубине Серой берлоги на юго-востоке." } } }, t = { d = 13.5, g = 1, v = "dwarf-female", n = { m = 134, f = 136 }, c = { m = { { 0.00, "Ты нас просто спас!" }, { 1.56, "Муж просто бы посмеялся, но мне бы не хватило духу сказать ему, что придётся провести ещё одну ночь на озере." }, { 10.40, "Может, теперь мы закатим настоящий пир." } }, f = { { 0.00, "Ты нас просто спасла!" }, { 1.72, "Муж просто бы посмеялся, но мне бы не хватило духу сказать ему, что придётся провести ещё одну ночь на озере." }, { 10.27, "Может, теперь мы закатим настоящий пир." } } } } },
    [98340] = { d = 27.0, g = 1, v = "tauren-male#67", n = { m = 284, f = 287 }, c = { m = { { 0.00, "Думаю, ты готов сделать следующий шаг на пути друида, ученик." }, { 4.90, "Дендрит Блеск Звёзд прислал весточку: он хочет, чтобы ты снова встретился с ним на Лунной поляне." }, { 12.50, "Ты уже умеешь использовать магию, которая перенесёт тебя туда, так что можешь отправляться прямо сейчас." }, { 20.73, "Я советую не откладывать это путешествие, если хочешь продолжать обучение друида." } }, f = { { 0.00, "Думаю, ты готова сделать следующий шаг на пути друида, ученица." }, { 4.87, "Дендрит Блеск Звёзд прислал весточку: он хочет, чтобы ты снова встретилась с ним на Лунной поляне." }, { 12.27, "Ты уже умеешь использовать магию, которая перенесёт тебя туда, так что можешь отправляться прямо сейчас." }, { 20.23, "Я советую не откладывать это путешествие, если хочешь продолжать обучение друида." } } }, t = { d = 29.8, g = 1, v = "nightelf-male#54", n = { m = 208, f = 208 }, c = { m = { { 0.00, "Итак, всё продолжается, отец Кенарий." }, { 3.92, "*Дендрит делает быстрый невидимый жест в воздухе над собой.*" }, { 8.76, "*Его окутывает лёгкая аура силы.*" }, { 11.36, "Снова приветствую тебя." }, { 13.35, "Пришло время познать следующий облик природы – облик кошки." }, { 18.34, "Я направлю тебя на путь к пониманию этой стороны жизни друида, но, как и с медведем, именно ты должен принять это знание и развивать его." } }, f = { { 0.00, "Итак, всё продолжается, отец Кенарий." }, { 3.76, "*Дендрит делает быстрый невидимый жест в воздухе над собой.*" }, { 8.70, "*Его окутывает лёгкая аура силы.*" }, { 11.36, "Снова приветствую тебя." }, { 13.38, "Пришло время познать следующий облик природы – облик кошки." }, { 18.47, "Я направлю тебя на путь к пониманию этой стороны жизни друида, но, как и с медведем, именно ты должна принять это знание и развивать его." } } } } },
    [98341] = { d = 38.4, g = 1, v = "nightelf-male#54", n = { m = 387, f = 388 }, c = { m = { { 0.00, "Недавно здесь явился дух твоих родных земель и попросил меня направить тебя к нему." }, { 6.75, "Дух рождённой ветром кошки хочет обучить и направить тебя, чтобы ты получил возможность принимать кошачью форму на Зефрисе." }, { 16.60, "Все друиды ищут этих знаний, хотя похоже, что в твоих землях дух принимает форму, отличную от той, к которой привыкли мы." }, { 26.30, "Если хочешь научиться превращению в кошку, тебе нужно будет пройти наше испытание." }, { 33.05, "Разыщи духа в южной части Лунной поляны, к югу от двух мостов." } }, f = { { 0.00, "Недавно здесь явился дух твоих родных земель и попросил меня направить тебя к нему." }, { 6.81, "Дух рождённой ветром кошки хочет обучить и направить тебя, чтобы ты получила возможность принимать кошачью форму на Зефрисе." }, { 16.81, "Все друиды ищут этих знаний, хотя похоже, что в твоих землях дух принимает форму, отличную от той, к которой привыкли мы." }, { 26.60, "Если хочешь научиться превращению в кошку, тебе нужно будет пройти наше испытание." }, { 33.41, "Разыщи духа в южной части Лунной поляны, к югу от двух мостов." } } }, t = { d = 30.4, g = 1, v = "creature/avatar_f", n = { m = 270, f = 271 }, c = { m = { { 0.00, "Привет тебе, юный шен'дорай." }, { 2.62, "Я здесь, так как почувствовала, что ты готов к испытанию, чтобы доказать, что понимаешь мою духовную природу." }, { 12.06, "Тебе нужно будет пройти испытание Духа Великой Кошки Азерота." }, { 17.70, "Но поскольку ты родом с Зефриса, я решила лично проследить за этим." }, { 23.65, "В конце концов, именно мою форму ты будешь принимать." }, { 28.49, "Приступим же." } }, f = { { 0.00, "Привет тебе, юная шен'дорай." }, { 2.69, "Я здесь, так как почувствовала, что ты готова к испытанию, чтобы доказать, что понимаешь мою духовную природу." }, { 12.47, "Тебе нужно будет пройти испытание Духа Великой Кошки Азерота." }, { 18.26, "Но поскольку ты родом с Зефриса, я решила лично проследить за этим." }, { 24.37, "В конце концов, именно мою форму ты будешь принимать." }, { 29.34, "Приступим же." } } } } },
    [98342] = { d = 48.0, g = 1, v = "tauren-female", n = { m = 472, f = 475 }, c = { m = { { 0.00, "Чтобы взывать к моему духу, мало нескольких слов." }, { 4.23, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способен воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 18.79, "В кельях к востоку отсюда скрыты три реликвии, символы моего покровительства, которые тебе нужно добыть." }, { 27.63, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 34.19, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смог пробраться мимо них." }, { 41.82, "Принеси мне эти реликвии." }, { 44.00, "Тогда мы узнаем, готов ли ты принимать мой облик." } }, f = { { 0.00, "Чтобы взывать к моему духу, мало нескольких слов." }, { 4.11, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способна воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 18.27, "В кельях к востоку отсюда скрыты три реликвии, символы моего покровительства, которые тебе нужно добыть." }, { 26.86, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 33.24, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смогла пробраться мимо них." }, { 40.88, "Принеси мне эти реликвии." }, { 43.00, "Тогда мы узнаем, готова ли ты принимать мой облик." } } }, t = { d = 19.1, g = 1, v = "tauren-female", n = { m = 180, f = 181 }, c = { m = { { 0.00, "Превосходно." }, { 1.10, "Ты доказал, что понимаешь истинную природу кошки и способен воплотить хитрость, скрытность и свирепость, необходимые, чтобы принимать мой облик." }, { 13.56, "Теперь я считаю тебя достойным моего благословения, юный герой." } }, f = { { 0.00, "Превосходно." }, { 1.09, "Ты доказала, что понимаешь истинную природу кошки и способна воплотить хитрость, скрытность и свирепость, необходимые, чтобы принимать мой облик." }, { 13.53, "Теперь я считаю тебя достойной моего благословения, юная героиня." } } } } },
    [98362] = { d = 32.7, g = 1, v = "nightelf-male#54", n = { m = 341, f = 340 }, c = { m = { { 0.00, "Пришло время нам снова расстаться, дитя." }, { 3.22, "Чтобы испытать полученные знания на практике, тебе нужно вернуться к тому, кто отправил тебя сюда." }, { 10.99, "Похоже, что твой наставник Тюрак Рунический Тотем нашёл себе достойного ученика." }, { 17.22, "Я тоже вижу в тебе большой потенциал." }, { 20.23, "Слушай своего учителя, и скоро ты научишься взывать к духу Великой Кошки и принимать его обличье." }, { 27.93, "Возвращайся домой." }, { 29.40, "Мы снова встретимся, когда придёт время." } }, f = { { 0.00, "Пришло время нам снова расстаться, дитя." }, { 3.26, "Чтобы испытать полученные знания на практике, тебе нужно вернуться к тому, кто отправил тебя сюда." }, { 11.12, "Похоже, что твой наставник Тюрак Рунический Тотем нашёл себе достойную ученицу." }, { 17.36, "Я тоже вижу в тебе большой потенциал." }, { 20.40, "Слушай своего учителя, и скоро ты научишься взывать к духу Великой Кошки и принимать его обличье." }, { 28.20, "Возвращайся домой." }, { 29.68, "Мы снова встретимся, когда придёт время." } } }, t = { d = 35.5, g = 1, v = "tauren-male#67", n = { m = 281, f = 286 }, c = { m = { { 0.00, "С возвращением." }, { 1.55, "Я чувствую, что ты встретился с духом Великой Кошки и прошёл испытание." }, { 8.66, "Его проходят все друиды, но у каждого поколения оно своё." }, { 14.49, "Я горжусь тем, что ты выдержал проверку и внял мудрости Великой Кошки." }, { 21.51, "Этот древний дух столь же смертоносен, сколь и игрив, хотя, чувствую, ты и сам уже это понял." }, { 30.90, "Теперь я научу тебя принимать облик кошки." } }, f = { { 0.00, "С возвращением." }, { 1.53, "Я чувствую, что ты встретилась с духом Великой Кошки и прошла испытание." }, { 8.74, "Его проходят все друиды, но у каждого поколения оно своё." }, { 14.51, "Я горжусь тем, что ты выдержала проверку и вняла мудрости Великой Кошки." }, { 21.72, "Этот древний дух столь же смертоносен, сколь и игрив, хотя, чувствую, ты и сама уже это поняла." }, { 31.27, "Теперь я научу тебя принимать облик кошки." } } } } },
    [98372] = { t = { d = 24.7, v = "narrator", n = { x = 275 }, c = { x = { { 0.00, "Мёртвый ночной дозорный перед тобой весь в глубоких рваных ранах." }, { 4.95, "Ясно, что его растерзал какой-то крупный зверь." }, { 8.54, "В руке у мертвеца ты замечаешь незажжённый факел." }, { 12.20, "Ты наклоняешься и вытаскиваешь его из закоченевших пальцев." }, { 16.60, "Он может пригодиться в странствиях по Сумеречному лесу и за его пределами, чтобы видеть то, что скрыто во тьме." } } } } },
    [98386] = { d = 29.0, v = "human-male", n = { x = 357 }, c = { x = { { 0.00, "Орки, гноллы, мурлоки..." }, { 1.67, "Кажется, все только и делают, что пытаются помешать мне достроить мост к сроку." }, { 6.88, "А теперь ещё говорят, что на нашей лесопилке завелись тарантулы!" }, { 11.12, "Если хочешь немного подзаработать, сходи на лесопилку Альтера и изничтожь тамошних пауков." }, { 17.16, "Она для меня совершенно бесполезна, если нельзя отправлять туда работников за грузами без риска для жизни." }, { 24.28, "И ещё: если увидишь старика Альтера, скажи ему, что за ним теперь должок." } } }, t = { d = 12.1, v = "human-male", n = { x = 123 }, c = { x = { { 0.00, "Дела на лесопилке так плохи?" }, { 2.28, "Всё даже хуже, чем я думал." }, { 4.48, "Я неприхотлив, но дел и так невпроворот, а тут ещё пауки рабочих сцапать норовят." }, { 10.74, "Спасибо за помощь!" } } } } },
    [98387] = { d = 20.2, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Без оружия войну не ведут." }, { 1.95, "Пусть орки из клана Чёрной Горы и вторглись в эти земли, но в их дерзком натиске есть слабые места." }, { 9.11, "Спустись к юго-востоку от крепости Каменной Стражи, отыщи их лагеря и лиши орков оружия и припасов." }, { 16.40, "Посмотрим, так ли они страшны без своих орудий войны." } } }, t = { d = 9.2, v = "human-male", n = { x = 103 }, c = { x = { { 0.00, "Отличная работа." }, { 1.29, "Теперь, когда орки Чёрной горы отрезаны от союзников в Пылающих степях, без припасов им здесь не удержаться." } } } } },
    [98389] = { d = 48.1, v = "scourge-male#83", n = { x = 497 }, c = { x = { { 0.00, "Если ты запомнишь лишь одно, то пусть это будет вот что: даже смерть не остановит Свет." }, { 6.80, "В этом мы едины со всеми Отрёкшимися – нам удалось преодолеть то, что живые считают окончанием своей истории." }, { 15.39, "Однако даже многие наши соплеменники страшатся нас." }, { 19.54, "Они думают, будто мы уничтожим их как каких-то чудовищ." }, { 23.97, "На самом же деле наши отношения с посмертием весьма сложны, но причинять вред своим мы не собираемся." }, { 31.99, "Помоги мне доказать это остальным." }, { 34.78, "Оправляйся в низину Ночных Пут к северо-востоку и освободи тех недавно поднявшихся раззяв, что оказались там в плену у пауков." }, { 44.73, "Тогда-то они поймут нашу истинную природу." } } }, t = { d = 27.7, v = "scourge-male#83", n = { x = 269 }, c = { x = { { 0.00, "Надеюсь, это поможет палачу Аррену и многим другим понять нашу истинную сущность." }, { 7.03, "Как и в прошлой жизни, мы существуем для того, чтобы служить нашему народу и защищать его с помощью сил, дарованных нам Светом." }, { 17.70, "Со временем они поймут, что мы так же важны для планов Тёмной Госпожи, как и остальные Отрёкшиеся." }, { 25.72, "Да пребудет с тобой Свет." } } } } },
    [98391] = { d = 25.6, g = 1, v = "nightelf-female#51", n = { m = 266, f = 267 }, c = { m = { { 0.00, "Да будешь ты благословлён, герой." }, { 2.46, "Сестринство Элуны было столпом калдорай тысячи лет." }, { 6.42, "До Великого Раскола, до Войны древних, на протяжении всего Долгого бдения мы исцеляли наш народ и направляли его во тьме." }, { 15.57, "Таков наш долг и наказ Матери-Луны." }, { 18.30, "Теперь же нам нужна твоя помощь в крайне важном деле." }, { 22.47, "Сестра Аквинна ждёт тебя в Дарнассе." } }, f = { { 0.00, "Да будешь ты благословлена, героиня." }, { 2.75, "Сестринство Элуны было столпом калдорай тысячи лет." }, { 6.75, "До Великого Раскола, до Войны древних, на протяжении всего Долгого бдения мы исцеляли наш народ и направляли его во тьме." }, { 15.97, "Таков наш долг и наказ Матери-Луны." }, { 18.73, "Теперь же нам нужна твоя помощь в крайне важном деле." }, { 22.93, "Сестра Аквинна ждёт тебя в Дарнассе." } } }, t = { d = 4.8, g = 1, v = "nightelf-female#53", n = { m = 52, f = 52 }, c = { m = { { 0.00, "Хорошо, что ты пришёл так быстро." }, { 2.51, "Сестринству нужна твоя помощь." } }, f = { { 0.00, "Хорошо, что ты пришла так быстро." }, { 2.42, "Сестринству нужна твоя помощь." } } } } },
    [98392] = { d = 19.7, v = "nightelf-female#52", n = { x = 238 }, c = { x = { { 0.00, "Эти пояса... присмотрись к этой коже." }, { 2.58, "Видишь порчу, пронизывающую волокна?" }, { 5.05, "У меня есть догадка, откуда она взялась, но нам нужны доказательства." }, { 9.67, "Вернись к гнёздам гарпий на западе и уничтожь их предводительниц." }, { 13.93, "Если в их ожерельях обитает та же тьма, что и в этих поясах, мы узнаем всё, что нам нужно." } } }, t = { d = 20.0, v = "nightelf-female#52", n = { x = 212 }, c = { x = { { 0.00, "*Арания осматривает амулеты.*" }, { 2.48, "Видишь эти мерзкие зелёные завихрения в самоцветах?" }, { 6.01, "Несомненно, это порча от мха Скверны." }, { 8.62, "Говорят, что в Тенистой долине и других уголках нашего леса также находили это вещество, обращающее наш дом против нас самих." }, { 17.29, "Я немедленно доложу об этом командованию." } } } } },
    [98393] = { d = 22.9, g = 1, v = "nightelf-male#59", n = { m = 284, f = 287 }, c = { m = { { 0.00, "Думаю, ты готов сделать следующий шаг на пути друида, ученик." }, { 4.15, "Дендрит Блеск Звёзд прислал весточку: он хочет, чтобы ты снова встретился с ним на Лунной поляне." }, { 10.58, "Ты уже умеешь использовать магию, которая перенесёт тебя туда, так что можешь отправляться прямо сейчас." }, { 17.55, "Я советую не откладывать это путешествие, если хочешь продолжать обучение друида." } }, f = { { 0.00, "Думаю, ты готова сделать следующий шаг на пути друида, ученица." }, { 4.15, "Дендрит Блеск Звёзд прислал весточку: он хочет, чтобы ты снова встретилась с ним на Лунной поляне." }, { 10.45, "Ты уже умеешь использовать магию, которая перенесёт тебя туда, так что можешь отправляться прямо сейчас." }, { 17.22, "Я советую не откладывать это путешествие, если хочешь продолжать обучение друида." } } }, t = { d = 31.6, v = "nightelf-male#54", n = { x = 225 }, c = { x = { { 0.00, "События идут своим чередом, отец Кенарий." }, { 4.40, "*Дендрит делает быстрый незаметный жест в воздухе у себя над головой, и его окутывает лёгкая аура силы.*" }, { 12.64, "И снова здравствуй." }, { 14.24, "Пришла пора тебе изучить следующее обличье – обличье кошки." }, { 19.21, "Я наставлю тебя на путь понимания этого аспекта нашего бытия, но как и в случае с обликом медведя, усвоить знания и совершенствоваться далее – твоя забота." } } } } },
    [98394] = { d = 37.4, v = "nightelf-male#54", n = { x = 379 }, c = { x = { { 0.00, "На юге Лунной поляны, на возвышающемся над мостом холме, обитает мудрое и хитрое существо, которое мы называем духом Великой Кошки." }, { 10.73, "Подобно духу Великого Медведя, этот дух был учителем и наставником для друидов, желающих принимать кошачий облик." }, { 19.93, "Все друиды рано или поздно обращаются к нему за наставлениями." }, { 25.04, "То же предстоит и тебе, если ты захочешь научиться придавать себе облик кошки." }, { 31.46, "Встреться с духом Великой Кошки и узнай, чему он согласится тебя научить." } } }, t = { d = 10.0, g = 1, v = "tauren-female", n = { m = 87, f = 88 }, c = { m = { { 0.00, "Я вижу, ты хочешь научиться пользоваться силой моего духа." }, { 5.41, "Хорошо." }, { 6.15, "Посмотрим, готов ли ты принять мой облик." } }, f = { { 0.00, "Я вижу, ты хочешь научиться пользоваться силой моего духа." }, { 5.50, "Хорошо." }, { 6.25, "Посмотрим, готова ли ты принять мой облик." } } } } },
    [98396] = { d = 48.0, g = 1, v = "tauren-female", n = { m = 472, f = 475 }, c = { m = { { 0.00, "Чтобы взывать к моему духу, мало нескольких слов." }, { 4.23, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способен воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 18.79, "В кельях к востоку отсюда скрыты три реликвии, символы моего покровительства, которые тебе нужно добыть." }, { 27.63, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 34.19, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смог пробраться мимо них." }, { 41.82, "Принеси мне эти реликвии." }, { 44.00, "Тогда мы узнаем, готов ли ты принимать мой облик." } }, f = { { 0.00, "Чтобы взывать к моему духу, мало нескольких слов." }, { 4.11, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способна воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 18.27, "В кельях к востоку отсюда скрыты три реликвии, символы моего покровительства, которые тебе нужно добыть." }, { 26.86, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 33.24, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смогла пробраться мимо них." }, { 40.88, "Принеси мне эти реликвии." }, { 43.00, "Тогда мы узнаем, готова ли ты принимать мой облик." } } }, t = { d = 15.8, g = 1, v = "tauren-female", n = { m = 156, f = 158 }, c = { m = { { 0.00, "Превосходно." }, { 1.09, "Ты доказал, что понимаешь истинную природу кошки и способен на хитрость, скрытность и безжалостность, необходимые, чтобы принимать мою форму." }, { 13.27, "Ты достоин моего благословения." } }, f = { { 0.00, "Превосходно." }, { 1.05, "Ты доказала, что понимаешь истинную природу кошки и способна на хитрость, скрытность и безжалостность, необходимые, чтобы принимать мою форму." }, { 12.88, "Ты достойна моего благословения." } } } } },
    [98397] = { d = 31.8, g = 1, v = "nightelf-male#54", n = { m = 331, f = 331 }, c = { m = { { 0.00, "Пришло время нам снова расстаться, дитя." }, { 3.19, "Чтобы применить уроки на практике, тебе нужно вернуться к тому, кто послал тебя сюда." }, { 9.92, "Похоже, что твой наставник Матренгил Медвежья Лапа нашёл себе достойного ученика." }, { 16.17, "Я тоже вижу в тебе большой потенциал." }, { 19.16, "Слушай своего учителя, и скоро ты научишься взывать к духу Великой Кошки и принимать её обличье." }, { 26.65, "Возвращайся домой." }, { 28.11, "Когда ты будешь готов, мы снова встретимся." } }, f = { { 0.00, "Пришло время нам снова расстаться, дитя." }, { 3.24, "Чтобы применить уроки на практике, тебе нужно вернуться к тому, кто послал тебя сюда." }, { 10.08, "Похоже, что твой наставник Матренгил Медвежья Лапа нашёл себе достойную ученицу." }, { 16.35, "Я тоже вижу в тебе большой потенциал." }, { 19.38, "Слушай своего учителя, и скоро ты научишься взывать к духу Великой Кошки и принимать её обличье." }, { 26.99, "Возвращайся домой." }, { 28.47, "Когда ты будешь готова, мы снова встретимся." } } }, t = { d = 27.2, g = 1, v = "nightelf-male#59", n = { m = 270, f = 274 }, c = { m = { { 0.00, "С возвращением." }, { 1.23, "Я чувствую, что ты встретился с духом Великой Кошки и прошёл испытание – его проходят все друиды, но у каждого поколения оно своё." }, { 11.61, "Ты выдержал проверку и внял мудрости Великой Кошки, и я горжусь тобой." }, { 17.26, "Этот древний дух в равной мере игрив и опасен, в чём ты, кажется, уже убедился." }, { 23.72, "Теперь я научу тебя принимать новый облик." } }, f = { { 0.00, "С возвращением." }, { 1.22, "Я чувствую, что ты встретилась с духом Великой Кошки и прошла испытание – его проходят все друиды, но у каждого поколения оно своё." }, { 11.60, "Ты выдержала проверку и вняла мудрости Великой Кошки, и я горжусь тобой." }, { 17.40, "Этот древний дух в равной мере игрив и опасен, в чём ты, кажется, уже убедилась." }, { 23.84, "Теперь я научу тебя принимать новый облик." } } } } },
    [98398] = { d = 22.7, g = 1, v = "nightelf-female#52", n = { m = 262, f = 265 }, c = { m = { { 0.00, "Ты столько достиг за такое короткое время!" }, { 2.93, "Это очень впечатляет." }, { 4.45, "Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе... но я понимаю, что тебя ждут великие дела." }, { 12.20, "Я заметила, что Древо-оракул только что сбросило кусок коры." }, { 16.35, "Несомненно, оно хочет, чтобы ты выполнил какое-то поручение для него." }, { 21.10, "Поговори с ним." } }, f = { { 0.00, "Ты столько достигла за такое короткое время!" }, { 3.12, "Это очень впечатляет." }, { 4.68, "Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе... но я понимаю, что тебя ждут великие дела." }, { 12.62, "Я заметила, что Древо-оракул только что сбросило кусок коры." }, { 16.87, "Несомненно, оно хочет, чтобы ты выполнила какое-то поручение для него." }, { 21.80, "Поговори с ним." } } }, t = { d = 12.3, v = "narrator", n = { x = 125 }, c = { x = { { 0.00, "Когда вы осматриваете опавшую кору, вы слышите голос в своей голове." }, { 5.86, "Спокойная и умиротворяющая речь напоминает вам шелест листвы при лёгком ветерке." } } } } },
    [98403] = { d = 35.8, g = 1, v = "nightelf-male#54", n = { m = 381, f = 381 }, c = { m = { { 0.00, "Лорд Меленас действовал не один – он исполнял приказы." }, { 4.14, "Того, кто их отдал, зовут Зеторр Злобный." }, { 7.37, "Похоже, он осквернил пауков, что обитают в Тельдрассиле, и замышляет использовать их яд для своих гнусных планов." }, { 15.92, "Он поселился глубоко в лесу, в месте на северо-западе отсюда, которое называют Расселиной." }, { 22.88, "Будь осторожен и возьми с собой союзников." }, { 26.12, "Зеторр – очень опасный противник." }, { 28.74, "Уничтожь его стаю и принеси мне что-нибудь, что поможет нам узнать больше о действиях сатира." } }, f = { { 0.00, "Лорд Меленас действовал не один – он исполнял приказы." }, { 4.10, "Того, кто их отдал, зовут Зеторр Злобный." }, { 7.31, "Похоже, он осквернил пауков, что обитают в Тельдрассиле, и замышляет использовать их яд для своих гнусных планов." }, { 15.78, "Он поселился глубоко в лесу, в месте на северо-западе отсюда, которое называют Расселиной." }, { 22.68, "Будь осторожна и возьми с собой союзников." }, { 25.89, "Зеторр – очень опасный противник." }, { 28.48, "Уничтожь его стаю и принеси мне что-нибудь, что поможет нам узнать больше о действиях сатира." } } }, t = { d = 37.9, v = "nightelf-male#54", n = { x = 415 }, c = { x = { { 0.00, "Нужно было догадаться, что именно это использовали, чтобы осквернить местных пауков." }, { 6.39, "Я слышал, что эта субстанция является источником порчи, которая принесла нам столько бед." }, { 13.05, "Это не оригинальный образец, но более старый, чем те, что мы находили ранее, так что у нас есть шанс узнать что-то новое." }, { 21.93, "В обычной ситуации я бы попросил тебя отправить этот образец в Дарнасс на изучение." }, { 28.18, "Но сейчас лучше, чтобы об этом никто не знал, иначе репутация Доланаара будет навсегда испорчена." }, { 35.51, "Надеюсь, ты умеешь хранить тайны?" } } } } },
    [98404] = { d = 50.8, g = 1, v = "creature/avatar_f", n = { m = 455, f = 457 }, c = { m = { { 0.00, "Чтобы взывать к моему духу, тебе придётся пройти испытание." }, { 5.57, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способен воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 21.62, "В кельях к востоку отсюда скрыты три реликвии, которые тебе нужно добыть." }, { 28.52, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 35.75, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смог пробраться мимо них." }, { 44.15, "Принеси мне эти реликвии, чтобы завершить испытание друидов этих земель." } }, f = { { 0.00, "Чтобы взывать к моему духу, тебе придётся пройти испытание." }, { 5.26, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способна воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 20.39, "В кельях к востоку отсюда скрыты три реликвии, которые тебе нужно добыть." }, { 26.90, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 33.73, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смогла пробраться мимо них." }, { 41.89, "Принеси мне эти реликвии, чтобы завершить испытание друидов этих земель." } } }, t = { d = 17.0, g = 1, v = "creature/avatar_f", n = { m = 156, f = 158 }, c = { m = { { 0.00, "Превосходно." }, { 1.16, "Ты доказал, что понимаешь истинную природу кошки и способен на хитрость, скрытность и безжалостность, необходимые, чтобы принимать мою форму." }, { 14.13, "Ты достоин моего благословения." } }, f = { { 0.00, "Превосходно." }, { 1.16, "Ты доказала, что понимаешь истинную природу кошки и способна на хитрость, скрытность и безжалостность, необходимые, чтобы принимать мою форму." }, { 14.14, "Ты достойна моего благословения." } } } } },
    [98405] = { d = 37.4, v = "nightelf-male#54", n = { x = 379 }, c = { x = { { 0.00, "На юге Лунной поляны, на возвышающемся над мостом холме, обитает мудрое и хитрое существо, которое мы называем духом Великой Кошки." }, { 10.73, "Подобно духу Великого Медведя, этот дух был учителем и наставником для друидов, желающих принимать кошачий облик." }, { 19.93, "Все друиды рано или поздно обращаются к нему за наставлениями." }, { 25.04, "То же предстоит и тебе, если ты захочешь научиться придавать себе облик кошки." }, { 31.46, "Встреться с духом Великой Кошки и узнай, чему он согласится тебя научить." } } }, t = { d = 9.1, g = 1, v = "tauren-female", n = { m = 77, f = 78 }, c = { m = { { 0.00, "Вижу, ты пришёл научиться взывать к моему духу." }, { 4.56, "Хорошо." }, { 5.33, "Посмотрим, готов ли ты принять мой облик." } }, f = { { 0.00, "Вижу, ты пришла научиться взывать к моему духу." }, { 4.44, "Хорошо." }, { 5.18, "Посмотрим, готова ли ты принять мой облик." } } } } },
    [98407] = { d = 32.5, v = "human-male", n = { x = 389 }, c = { x = { { 0.00, "Раз уж гноллы так осмелели, что разбивают лагерь столь близко к людям, то неизвестно, на что ещё они готовы пойти." }, { 7.69, "Нам нужно их отпугнуть." }, { 9.29, "Этим тварям не хватает организованности, а больше всего они, похоже, ценят силу." }, { 14.90, "Если убьём их вожаков и заберём какие-нибудь трофеи, то напомним этим гноллам, почему им следует сидеть на их холмах и не высовывать оттуда нос." }, { 24.62, "Если ты повстречаешь их твердозубов, принеси мне их ошейники." }, { 28.74, "Так мы заставим их дрожать в страхе перед мощью Альянса." } } }, t = { d = 13.3, v = "human-male", n = { x = 151 }, c = { x = { { 0.00, "Да у тебя тут целая охапка ошейников." }, { 2.71, "Хотя полностью нашу проблему это не решит, я могу спокойно вздохнуть, зная, что мы отбили у них всякое желание продвигаться дальше." }, { 12.20, "Отличная работа." } } } } },
    [98417] = { d = 30.8, v = "nightelf-female", n = { x = 341 }, c = { x = { { 0.00, "В тот момент, когда судьбе угодно было сделать нас наиболее уязвимыми, на наши деревни обрушилась беда." }, { 7.69, "Сатиры осквернили наши храмы, их нечистое прикосновение запятнало священные ветви, и много невинных душ пало от их рук." }, { 16.43, "Куротеля поглотил гнев." }, { 18.16, "Друиды отправились биться с сатирами, и он последовал за ними." }, { 22.73, "Наша связь крепка." }, { 24.12, "Я чувствую своего мужа где-то к востоку, в лесах." }, { 27.83, "Прошу, принеси мне весточку о его судьбе." } } }, t = { d = 11.6, v = "nightelf-female", n = { x = 118 }, c = { x = { { 0.00, "О нет... такие слова меня не утешают." }, { 2.94, "Куротель не просто живёт в глуши — с каждой ночью он всё больше уподобляется дикому зверю." }, { 9.93, "Боюсь, слухи правдивы." } } } } },
    [98418] = { d = 34.3, v = "nightelf-female", n = { x = 432 }, c = { x = { { 0.00, "Куротель упоминает о встречах с некими полуволками." }, { 3.45, "Представителей их стаи всё больше в нашем лесу." }, { 6.66, "Насколько мне известно, друиды пытаются наладить связь с теми из звероподобных созданий, кто способен контролировать свои животные инстинкты." }, { 16.05, "В послании моего супруга говорится о более мрачной борьбе." }, { 20.05, "Если что-то и поможет нам вновь увидеть его настоящего, то это избавление от демонической угрозы, которая подстёгивает трансформацию Куротеля." }, { 29.49, "Это должно помочь его страдающей душе." }, { 32.22, "Убей сатиров из племени Ксавиан." } } }, t = { d = 27.6, g = 1, v = "nightelf-female", n = { m = 289, f = 291 }, c = { m = { { 0.00, "Во мне и вокруг меня словно разлился... свет Элуны." }, { 3.89, "Я чувствую, Куротель видел, как ты сражался в этой войне, что бушует на нашей земле и в наших сердцах." }, { 11.67, "Надеюсь, со временем наши Часовые и заблудшие друиды навсегда покончат с демонической угрозой." }, { 18.83, "Быть может, лишь тогда звериная жажда мести угаснет в нашем роду." }, { 23.88, "Спасибо тебе." }, { 24.97, "Ты союзник леса и друг калдорай." } }, f = { { 0.00, "Во мне и вокруг меня словно разлился... свет Элуны." }, { 3.92, "Я чувствую, Куротель видел, как ты сражалась в этой войне, что бушует на нашей земле и в наших сердцах." }, { 11.81, "Надеюсь, со временем наши Часовые и заблудшие друиды навсегда покончат с демонической угрозой." }, { 19.03, "Быть может, лишь тогда звериная жажда мести угаснет в нашем роду." }, { 24.11, "Спасибо тебе." }, { 25.21, "Ты союзница леса и друг калдорай." } } } } },
    [98423] = { d = 23.1, v = "narrator", n = { x = 268 }, c = { x = { { 0.00, "В хранилище ты найдёшь табличку с подробным описанием условий мирного договора между кланом Громового Молота и Бронзобородами." }, { 9.35, "По всей видимости, он относится к периоду сразу после Войны Трёх Молотов и, вероятно, является важным историческим документом." }, { 18.69, "Король Стальгорна, несомненно, заинтересуется этим артефактом." } } }, t = { d = 41.2, g = 1, v = "dwarf-male#177", n = { m = 388, f = 390 }, c = { m = { { 0.00, "Ах да, мой предок Мадоран стал первым королём Стальгорна из рода Бронзобородов после масштабной гражданской войны между кланами Громового Молота, Бронзобородами и кланом Чёрного Железа." }, { 15.99, "Этот договор был составлен для формального признания окончания боевых действий и закрепления условий мира после победы Бронзобородов в битве за гору." }, { 28.17, "Как видишь, Громовые Молоты и Бронзобороды его подписали... а вот дворфы Чёрного Железа – нет." }, { 37.62, "Спасибо, что нашёл его и принёс мне, герой." } }, f = { { 0.00, "Ах да, мой предок Мадоран стал первым королём Стальгорна из рода Бронзобородов после масштабной гражданской войны между кланами Громового Молота, Бронзобородами и кланом Чёрного Железа." }, { 15.62, "Этот договор был составлен для формального признания окончания боевых действий и закрепления условий мира после победы Бронзобородов в битве за гору." }, { 28.39, "Как видишь, Громовые Молоты и Бронзобороды его подписали... а вот дворфы Чёрного Железа – нет." }, { 36.32, "Спасибо, что нашла его и принесла мне, героиня." } } } } },
    [98424] = { d = 22.7, v = "narrator", n = { x = 277 }, c = { x = { { 0.00, "Несколько особенно потрёпанных бумаг нашлось отдельно, сложенными во внутреннем нагрудном кармане Шумовика." }, { 7.54, "Кажется, в них содержится важная информация, которую можно использовать против Торговой Компании и её предприятий в регионе." }, { 16.29, "Было бы разумно собрать побольше информации, прежде чем возвращаться к Морину Ловцу Облаков." } } }, t = { d = 12.1, v = "tauren-male", n = { x = 68 }, c = { x = { { 0.00, "О, это очень ценные сведения." }, { 3.51, "Благодарю за труды." }, { 5.68, "*Морин просматривает заметки.*" }, { 7.92, "Похоже, наш следующий шаг очевиден." } } } } },
    [98427] = { d = 40.2, v = "tauren-male", n = { x = 404 }, c = { x = { { 0.00, "Я уже видел крошшеры вроде того, о котором говорится на одной из страниц, в ходе моих путешествий." }, { 8.08, "Они могут вырубать лес во много раз быстрее, чем обычные дровосеки." }, { 13.53, "Рощи, тысячелетиями служившие домом детям Матери-Земли, исчезают навсегда за считанные дни." }, { 20.96, "Мы не позволим этому случиться у нас дома, вблизи того места, где наш молодняк делает свои первые шаги." }, { 29.40, "Я должен попросить тебя собрать отряд, вернуться в шахту на северо-востоке и убедиться, что крошшер не срубит больше ни одного дерева." } } }, t = { d = 9.7, v = "tauren-male", n = { x = 83 }, c = { x = { { 0.00, "Вся деревня Кровавого Копыта у тебя в долгу." }, { 4.40, "Пусть тебя никогда не оставляет благодать Матери-Земли." } } } } },
    [98430] = { d = 38.1, g = 1, v = "tauren-male#68", n = { x = 396 }, c = { m = { { 0.00, "Приветствую, герой." }, { 1.55, "Что привело тебя в такое мрачное и суровое место?" }, { 5.51, "Меня послал сюда верховный вождь Кэрн Кровавое Копыто, чтобы попытаться наладить контакт с поселившимися тут гноллами." }, { 14.77, "Другая часть моего задания должна оставаться в тайне, как и всё, что касается дальноходов, доверенных разведчиков нашего вождя." }, { 24.66, "Знай, что ответом на нашу дипломатию стало насилие, и я боюсь, что сегодня вечером стану главным блюдом на пиру у гноллов, если ты меня отсюда не вызволишь." }, { 36.96, "Ты поможешь мне?" } }, f = { { 0.00, "Приветствую, героиня." }, { 1.66, "Что привело тебя в такое мрачное и суровое место?" }, { 5.54, "Меня послал сюда верховный вождь Кэрн Кровавое Копыто, чтобы попытаться наладить контакт с поселившимися тут гноллами." }, { 14.61, "Другая часть моего задания должна оставаться в тайне, как и всё, что касается дальноходов, доверенных разведчиков нашего вождя." }, { 24.30, "Знай, что ответом на нашу дипломатию стало насилие, и я боюсь, что сегодня вечером стану главным блюдом на пиру у гноллов, если ты меня отсюда не вызволишь." }, { 36.34, "Ты поможешь мне?" } } }, t = { d = 37.1, g = 1, v = "named/3057", n = { m = 372, f = 374 }, c = { m = { { 0.00, "Я рад, что дальноход Штормовое Копыто в порядке." }, { 7.24, "Он мой самый доверенный разведчик, и задание ему поручено чрезвычайно важное." }, { 12.95, "Прошу, прими мою благодарность и гостеприимство – ты ведь рисковал жизнью ради его спасения." }, { 19.80, "Ты даже не ведаешь, насколько большую услугу оказал нашему народу." }, { 24.78, "Прошу, хорошенько осмотри наш великий город, пока ты здесь." }, { 29.16, "Тут совершенно безопасно, и много кто здесь может помочь тебе в путешествиях по крутым утёсам." }, { 36.00, "Иш-не-ало пор-а." } }, f = { { 0.00, "Я рад, что дальноход Штормовое Копыто в порядке." }, { 6.92, "Он мой самый доверенный разведчик, и задание ему поручено чрезвычайно важное." }, { 12.38, "Прошу, прими мою благодарность и гостеприимство – ты ведь рисковала жизнью ради его спасения." }, { 18.98, "Ты даже не ведаешь, насколько большую услугу оказала нашему народу." }, { 23.81, "Прошу, хорошенько осмотри наш великий город, пока ты здесь." }, { 28.00, "Тут совершенно безопасно, и много кто здесь может помочь тебе в путешествиях по крутым утёсам." }, { 34.54, "Иш-не-ало пор-а." } } } } },
    [98435] = { d = 25.8, v = "tauren-male#68", n = { x = 271 }, c = { x = { { 0.00, "Необходимо оповестить старейшин в Громовом Утёсе о прогрессе, которого мы достигли благодаря твоей помощи." }, { 8.42, "Пожалуйста, отнеси это верховному друиду Хамуулу Руническому Тотему в Громовой Утёс." }, { 15.18, "Ты найдёшь его на Вершине Старейшин в восточной части города." }, { 20.08, "Для этого поднимись на лифте к центру города, а затем пройди по мостам." } } }, t = { d = 26.6, g = 1, v = "creature/hamuul", n = { m = 242, f = 243 }, c = { m = { { 0.00, "А, неудивительно, что ручьи Мулгора исполнены радости." }, { 4.87, "Сегодня ты сделал большое дело." }, { 7.80, "Колодцы приносят пользу не только нашему народу, но и диким животным, которые даруют нам еду, одежду и дружбу." }, { 17.87, "Я с огромным удовольствием исполню просьбу Мулла." }, { 22.34, "Пожалуйста, прими это в знак моей благодарности." } }, f = { { 0.00, "А, неудивительно, что ручьи Мулгора исполнены радости." }, { 4.81, "Сегодня ты сделала большое дело." }, { 7.78, "Колодцы приносят пользу не только нашему народу, но и диким животным, которые даруют нам еду, одежду и дружбу." }, { 17.73, "Я с огромным удовольствием исполню просьбу Мулла." }, { 22.15, "Пожалуйста, прими это в знак моей благодарности." } } } } },
    [98447] = { d = 32.1, g = 1, v = "human-male", n = { m = 372, f = 373 }, c = { m = { { 0.00, "Хоть ты и упокоил призраков семьи Валор, сообщения о нападениях не прекращаются." }, { 5.51, "Попытка была хорошая, но, похоже, их незавершённые дела мы так и не уладили." }, { 10.70, "Судя по тому, что мне удалось выяснить, вся эта семья пропала в одно и то же время." }, { 16.52, "Что бы ни приковало их души к этому миру, это случилось со всеми сразу." }, { 21.52, "Наша единственная зацепка – место, где ты нашёл книгу." }, { 25.28, "Возвращайся на Вороний Холм и посмотри, что удастся найти." }, { 29.28, "Может быть, их оружие что-нибудь пробудит." } }, f = { { 0.00, "Хоть ты и упокоила призраков семьи Валор, сообщения о нападениях не прекращаются." }, { 5.40, "Попытка была хорошая, но, похоже, их незавершённые дела мы так и не уладили." }, { 10.43, "Судя по тому, что мне удалось выяснить, вся эта семья пропала в одно и то же время." }, { 16.06, "Что бы ни приковало их души к этому миру, это случилось со всеми сразу." }, { 20.91, "Наша единственная зацепка – место, где ты нашла книгу." }, { 24.61, "Возвращайся на Вороний Холм и посмотри, что удастся найти." }, { 28.49, "Может быть, их оружие что-нибудь пробудит." } } } },
    [98459] = { d = 30.9, v = "human-male", n = { x = 360 }, c = { x = { { 0.00, "Барт Приливень – никудышный скряга, уж поверь!" }, { 3.12, "Зовёт себя капитаном \"Девичьей Чести\"." }, { 5.76, "Да этот корабль проплыл в Танарисе не дальше брошенного камня!" }, { 10.05, "Он не капитан, а притворщик, который просто выиграл денег в покер и купил \"Честь\"!" }, { 15.62, "Если ты когда-нибудь окажешься в Гавани Менетилов в Болотине, передай ему это и скажи, что это от старины \"Полурыба\"." }, { 23.65, "Кстати, отсюда прямо в гавань ходит корабль." }, { 26.77, "Вторая остановка – твоя!" }, { 28.49, "И помни, что в покере он жульничает!" } } }, t = { d = 29.8, v = "human-male", n = { x = 320 }, c = { x = { { 0.00, "*Барт разворачивает подарок.*" }, { 2.56, "Ах ты ж никчёмный сукин..." }, { 4.27, "Он хоть сказал тебе, что это ОН жульничает в покере?!" }, { 7.86, "Я выиграл денег на «Девичью Честь» только после того, как мы вышвырнули его из нашего покерного кружка!" }, { 14.87, "Клянусь, когда я в следующий раз увижу эту никчёмную трату морской воды..." }, { 19.93, "Прости, прости." }, { 21.02, "Нечего срываться на гонце." }, { 22.85, "От имени команды «Девичьей Чести» – лучшего корабля Великого моря – добро пожаловать в Гавань Менетилов!" } } } } },
    [98461] = { d = 38.6, v = "dwarf-female#33", n = { x = 398 }, c = { x = { { 0.00, "Если ты собираешься покинуть Аубердин, мне бы пригодилась твоя помощь!" }, { 5.34, "Мы с моим дорогим другом Таррелом были одноклассниками." }, { 9.59, "О, во всём, что касалось раскопок, он был таким сообразительным!" }, { 14.31, "После окончания школы жизнь разбросала нас по миру: он отправился в Болотину, а я сюда, на Тёмные берега." }, { 22.19, "Извини." }, { 23.36, "Его жена..." }, { 24.31, "Меррин..." }, { 25.07, "Впрочем, неважно." }, { 26.44, "Если окажешься в Болотине, можешь узнать, как у него дела?" }, { 30.96, "И, может, передашь ему это?" }, { 33.15, "Он, вероятно, где-то неподалёку от Гавани Менетилов." }, { 37.05, "Туда ходит корабль." } } }, t = { d = 28.1, v = "dwarf-male", n = { x = 259 }, c = { x = { { 0.00, "*Таррел читает записку.*" }, { 2.08, "Ох, надо же..." }, { 3.22, "Бедная Холли." }, { 4.36, "Она всегда была ко мне расположена." }, { 7.21, "По совести говоря, было время, когда и я бы ответил ей взаимностью." }, { 12.55, "Но теперь я женат." }, { 14.04, "И брак у меня счастливый!" }, { 16.04, "Пожалуй, лучше просто не отвечать." }, { 18.81, "Мне не хочется её разочаровывать, к тому же у меня есть гораздо более серьёзные причины для тревоги!" }, { 26.58, "Моя жена пропала!" } } } } },
    [98463] = { d = 33.4, g = 1, v = "human-male", n = { m = 391, f = 391 }, c = { m = { { 0.00, "Слушай, ты один из моих любимых посетителей, поэтому я тебе кое-что расскажу." }, { 5.37, "Знаешь, где устраивают настоящие вечеринки?" }, { 8.34, "В таверне \"Старый моряк\" в Пиратской Бухте." }, { 11.36, "Да, в той самой Пиратской Бухте, что в Тернистой долине." }, { 15.19, "Не смотри на меня так, я знаю, что там всем заправляют гоблины." }, { 19.45, "Бармены много болтают, а посетители – ещё больше." }, { 22.85, "Я просто хочу сказать, что если тебе нужно как следует повеселиться, отправляйся туда." }, { 28.83, "У Никсраза Наливайки всегда найдётся выпить, в этом не сомневайся." } }, f = { { 0.00, "Слушай, ты одна из моих любимых посетителей, поэтому я тебе кое-что расскажу." }, { 5.40, "Знаешь, где устраивают настоящие вечеринки?" }, { 8.38, "В таверне \"Старый моряк\" в Пиратской Бухте." }, { 11.42, "Да, в той самой Пиратской Бухте, что в Тернистой долине." }, { 15.26, "Не смотри на меня так, я знаю, что там всем заправляют гоблины." }, { 19.54, "Бармены много болтают, а посетители – ещё больше." }, { 22.96, "Я просто хочу сказать, что если тебе нужно как следует повеселиться, отправляйся туда." }, { 28.97, "У Никсраза Наливайки всегда найдётся выпить, в этом не сомневайся." } } }, t = { d = 12.9, v = "goblin-male", n = { x = 138 }, c = { x = { { 0.00, "У меня есть всё, что тебе нужно, дружище!" }, { 3.12, "Оставайся, потрать немного золота, что оттягивает тебе карман, и повеселись как следует." }, { 9.77, "Добро пожаловать в таверну «Старый моряк»!" } } } } },
    [98471] = { d = 20.4, g = 1, v = "narrator", n = { m = 221, f = 221 }, c = { m = { { 0.00, "Приветствую." }, { 0.93, "У меня есть для тебя дело первостепенной важности." }, { 4.65, "Пожалуйста, встреться со мной в Альтеракских горах к северо-западу от деревни Странбрад." }, { 11.10, "Я буду ждать тебя на скале, с которой открывается вид на долину Высокогорья." }, { 16.68, "Приходи один и никому ничего не говори." } }, f = { { 0.00, "Приветствую." }, { 0.97, "У меня есть для тебя дело первостепенной важности." }, { 4.86, "Пожалуйста, встреться со мной в Альтеракских горах к северо-западу от деревни Странбрад." }, { 11.59, "Я буду ждать тебя на скале, с которой открывается вид на долину Высокогорья." }, { 17.43, "Приходи одна и никому ничего не говори." } } } },
    [98477] = { d = 37.2, v = "tauren-female", n = { x = 390 }, c = { x = { { 0.00, "Любой опытный шаман, пытавшийся заглянуть в мир стихий, скажет тебе, что там есть своего рода сбой — искажение, которое ощущаешь, переходя в иные планы бытия." }, { 12.43, "Нам нужны искатели приключений вроде тебя, чтобы лучше понять это возмущение." }, { 18.64, "Возьми этот магнит стихий." }, { 20.83, "С его помощью ты сможешь извлекать частицы нестабильной магии из самых искусных заклинателей и других могущественных существ, которые встретятся тебе на пути." }, { 33.26, "Принеси мне эти частицы, чтобы мы могли их изучить." } } } },
    [98512] = { d = 20.2, g = 1, v = "bloodelf-male", n = { m = 215, f = 215 }, c = { m = { { 0.00, "Эй, незнакомец." }, { 1.13, "Пригнись и не шуми." }, { 2.59, "Мы не одни здесь." }, { 3.85, "Я патрулировал границу и заметил группу ал'акетов возле дома на холме, что к северу отсюда." }, { 10.62, "Не знаю, что они там делают, но явно ничего хорошего." }, { 14.61, "Если хочешь помочь, пойди и устрани их." }, { 17.60, "Я подожду здесь – прикрою тебе спину." } }, f = { { 0.00, "Эй, незнакомка." }, { 1.12, "Пригнись и не шуми." }, { 2.56, "Мы не одни здесь." }, { 3.81, "Я патрулировал границу и заметил группу ал'акетов возле дома на холме, что к северу отсюда." }, { 10.50, "Не знаю, что они там делают, но явно ничего хорошего." }, { 14.44, "Если хочешь помочь, пойди и устрани их." }, { 17.39, "Я подожду здесь – прикрою тебе спину." } } }, t = { d = 11.1, g = 1, v = "bloodelf-male", n = { m = 124, f = 125 }, c = { m = { { 0.00, "Хорошо, что ты вернулся в целости." }, { 2.44, "Те ал'акеты выглядели как безжалостные головорезы." }, { 5.98, "Спасибо за помощь." }, { 7.33, "Я упомяну это в отчёте, когда вернусь в Валанаар." } }, f = { { 0.00, "Хорошо, что ты вернулась в целости." }, { 2.49, "Те ал'акеты выглядели как безжалостные головорезы." }, { 6.39, "Спасибо за помощь." }, { 7.73, "Я упомяну это в отчёте, когда вернусь в Валанаар." } } } } },
    [98517] = { d = 20.2, g = 1, v = "skyborne-male", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Приветствую, юный небеснорождённый." }, { 2.73, "Духи говорили о тебе, и они сказали, что ты готов ответить на зов огня." }, { 8.48, "Но наставлять тебя на этом пути предстоит не мне." }, { 12.44, "Возвращайся домой в мир стихий и разыщи там своих наставников." }, { 17.40, "Они скажут, что нужно сделать." } }, f = { { 0.00, "Приветствую, юная небеснорождённая." }, { 2.79, "Духи говорили о тебе, и они сказали, что ты готова ответить на зов огня." }, { 8.73, "Но наставлять тебя на этом пути предстоит не мне." }, { 12.76, "Возвращайся домой в мир стихий и разыщи там своих наставников." }, { 17.83, "Они скажут, что нужно сделать." } } } },
    [98545] = { d = 30.3, g = 1, v = "scourge-male", n = { m = 272, f = 274 }, c = { m = { { 0.00, "Раз уж ты тут, я хочу, чтобы ты отнёс это письмо моему старому другу в Подгород." }, { 6.92, "Я мог бы и сам это сделать, но у нас с Тёмной Госпожой ранее возникали некоторые разногласия, поэтому лучше, если письмо доставит кто-то сторонний." }, { 19.52, "Найди гоблина по имени Гликс Ксиззикс в Торговом квартале Подгорода." }, { 25.42, "Думаю, он с радостью оплатит твою услугу." } }, f = { { 0.00, "Раз уж ты тут, я хочу, чтобы ты отнесла это письмо моему старому другу в Подгород." }, { 7.04, "Я мог бы и сам это сделать, но у нас с Тёмной Госпожой ранее возникали некоторые разногласия, поэтому лучше, если письмо доставит кто-то сторонний." }, { 19.44, "Найди гоблина по имени Гликс Ксиззикс в Торговом квартале Подгорода." }, { 25.26, "Думаю, он с радостью оплатит твою услугу." } } }, t = { d = 22.0, v = "goblin-male#110", n = { x = 240 }, c = { x = { { 0.00, "Спасибо за письмецо." }, { 1.53, "Погоди... он сказал, я оплачу доставку?" }, { 4.47, "Я на это не соглашался!" }, { 6.20, "Ладно." }, { 6.74, "Можешь забрать что-нибудь из бюро находок." }, { 9.94, "Отрёкшиеся на удивление часто забывают тут свой хлам после стрижки." }, { 14.81, "Я бы пошутил, что им не хватает мозгов, но подозреваю, что для большинства из них это вовсе не шутка." } } } } },
    [98574] = { d = 13.9, g = 1, v = "dwarf-male", n = { m = 158, f = 159 }, c = { m = { { 0.00, "Пока ты мне помогал, меня попросили передать тебе этот меморандум." }, { 4.84, "Почитай его на досуге." }, { 6.52, "Думаю, его прислал Брансток, наставник жрецов." }, { 9.94, "Если представится случай, отыщи его в Старой Наковальне." } }, f = { { 0.00, "Пока ты мне помогала, меня попросили передать тебе этот меморандум." }, { 4.80, "Почитай его на досуге." }, { 6.44, "Думаю, его прислал Брансток, наставник жрецов." }, { 9.78, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 25.0, g = 1, v = "dwarf-male", n = { m = 281, f = 282 }, c = { m = { { 0.00, "Со временем и практикой ты откроешь новые грани Света." }, { 3.99, "В некотором роде это поиск единства между тем, что ты думаешь, и тем, что ты чувствуешь." }, { 10.33, "Когда твоя связь со Светом окрепнет, возвращайся ко мне и расскажи, что узнал." }, { 15.95, "Я с радостью покажу, как обратиться к этой силе, чтобы исцелять или карать нечестивых." }, { 22.29, "За небольшое пожертвование, разумеется!" } }, f = { { 0.00, "Со временем и практикой ты откроешь новые грани Света." }, { 3.95, "В некотором роде это поиск единства между тем, что ты думаешь, и тем, что ты чувствуешь." }, { 10.24, "Когда твоя связь со Светом окрепнет, возвращайся ко мне и расскажи, что узнала." }, { 15.87, "Я с радостью покажу, как обратиться к этой силе, чтобы исцелять или карать нечестивых." }, { 22.16, "За небольшое пожертвование, разумеется!" } } } } },
    [98575] = { d = 17.7, v = "orc-male#60", n = { x = 183 }, c = { x = { { 0.00, "А!" }, { 0.21, "Тебе тут скрижаль прислали, пока тебя не было." }, { 3.89, "Я лично стараюсь не иметь дела с чернокнижниками, однако ты её всё-таки прочитай, когда время будет." }, { 11.59, "Это, кажется, от твоего нового наставника, Нартока." }, { 15.61, "Он хочет с тобой поговорить." } } }, t = { d = 25.2, g = 1, v = "orc-male", n = { m = 237, f = 238 }, c = { m = { { 0.00, "Ты лишь мельком увидел силу, что может стать твоей." }, { 4.42, "Слабые и глупые боятся пути, которым мы идём, но смелость и хитрость позволяют нам самим решать свою судьбу." }, { 13.80, "Береги свои силы." }, { 15.43, "Трусы нападают на то, чего не понимают." }, { 18.84, "Теперь ты один из нас." }, { 20.78, "Понадобится обучение заклинаниям – возвращайся ко мне." } }, f = { { 0.00, "Ты лишь мельком увидела силу, что может стать твоей." }, { 4.41, "Слабые и глупые боятся пути, которым мы идём, но смелость и хитрость позволяют нам самим решать свою судьбу." }, { 13.62, "Береги свои силы." }, { 15.22, "Трусы нападают на то, чего не понимают." }, { 18.56, "Теперь ты одна из нас." }, { 20.47, "Понадобится обучение заклинаниям – возвращайся ко мне." } } } } },
    [98576] = { d = 13.9, v = "orc-male#60", n = { x = 142 }, c = { x = { { 0.00, "О, пока тебя не было, тут прислали пергамент." }, { 3.61, "Прочти на досуге." }, { 5.02, "Если не ошибаюсь, он от наставницы магов Май'ах." }, { 8.84, "Она хочет перемолвиться с тобой словечком, когда ты найдёшь время." } } }, t = { d = 23.2, g = 1, v = "troll-female#73", n = { m = 246, f = 248 }, c = { m = { { 0.00, "Магия, что течёт сквозь тебя, – величайшая сила во вселенной, но тут нужно терпение." }, { 6.06, "Жди идеального момента для удара." }, { 8.50, "Выбирай верный ответ на любую задачу." }, { 11.33, "Будь умнее, смотри в оба – и тебе всё будет по плечу." }, { 15.28, "Когда решишь, что готов учиться, возвращайся к Май'ах." }, { 19.30, "Она научит тебя тому, к чему ты готов, без проблем." } }, f = { { 0.00, "Магия, что течёт сквозь тебя, – величайшая сила во вселенной, но тут нужно терпение." }, { 6.05, "Жди идеального момента для удара." }, { 8.48, "Выбирай верный ответ на любую задачу." }, { 11.30, "Будь умнее, смотри в оба – и тебе всё будет по плечу." }, { 15.25, "Когда решишь, что готова учиться, возвращайся к Май'ах." }, { 19.32, "Она научит тебя тому, к чему ты готова, без проблем." } } } } },
    [98581] = { d = 17.9, v = "dwarf-male", n = { x = 201 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну." }, { 5.26, "Изучи её, когда будет время." }, { 7.41, "Это руна Громового Молота – скорее всего, её прислал Тео Молотошторм, наставник шаманов." }, { 13.91, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 22.4, v = "dwarf-male", n = { x = 229 }, c = { x = { { 0.00, "Шаманское искусство долгие годы хранил клан Громового Молота, а теперь эти знания перешли и к клану Бронзоборода." }, { 9.18, "Я здесь, чтобы нести это учение и наставлять новых шаманов, познающих пути стихий." }, { 15.90, "Приходи ко мне, если понадобится обучение заклинаниям земли, воздуха, огня и воды." } } } } },
    [98601] = { d = 24.3, g = 1, v = "scourge-male#82", n = { m = 231, f = 232 }, c = { m = { { 0.00, "Пока ты разбирался с безмозглыми тварями Плети, тебе тут свиток прислали." }, { 6.09, "От него так и несёт магией Света, так что, полагаю, для паладина типа тебя он должен быть важен." }, { 13.95, "Прочитай его, прежде чем отправляться дальше в путь." }, { 18.26, "Только сперва отойди подальше – мне рядом с паладином не по себе." } }, f = { { 0.00, "Пока ты разбиралась с безмозглыми тварями Плети, тебе тут свиток прислали." }, { 6.35, "От него так и несёт магией Света, так что, полагаю, для паладина типа тебя он должен быть важен." }, { 14.46, "Прочитай его, прежде чем отправляться дальше в путь." }, { 18.89, "Только сперва отойди подальше – мне рядом с паладином не по себе." } } }, t = { d = 20.6, g = 1, v = "scourge-male#83", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Теперь твоё обучение можно начинать всерьёз, герой." }, { 4.15, "Задатки у тебя просто превосходные, но не вздумай ни на мгновение отворачиваться от Света." }, { 11.35, "Прими боль, которую он принесёт." }, { 13.89, "Эти муки – горнило, из которого ты выйдешь сильнее, чем был в прошлой жизни." } }, f = { { 0.00, "Теперь твоё обучение можно начинать всерьёз, героиня." }, { 4.36, "Задатки у тебя просто превосходные, но не вздумай ни на мгновение отворачиваться от Света." }, { 11.69, "Прими боль, которую он принесёт." }, { 14.28, "Эти муки – горнило, из которого ты выйдешь сильнее, чем была в прошлой жизни." } } } } },
    [98731] = { d = 17.4, v = "tauren-female", n = { x = 170 }, c = { x = { { 0.00, "Теперь, получив моё благословение, возвращайся к Дендриту." }, { 4.83, "Он расскажет, что делать дальше." }, { 7.55, "Надеюсь, однажды мы встретимся снова." }, { 10.72, "Пусть тени всегда скрывают тебя, а твои враги оказываются у тебя в когтях, дитя." } } }, t = { d = 38.9, v = "nightelf-male#54", n = { x = 252 }, c = { x = { { 0.00, "*Когда вы приближаетесь, Дендрит делает едва заметный жест у себя над головой.*" }, { 6.63, "*Его окутывает новая аура могущества, а на губах появляется лёгкая улыбка.*" }, { 12.88, "Я чувствую в тебе кошачью хитрость и неукротимость, которых не было, когда я отправил тебя на встречу с духом Великой Кошки." }, { 23.39, "По твоим глазам я вижу, что теперь ты обладаешь хитростью и скоростью, которые нужны, чтобы постичь кошачью природу." }, { 33.21, "Используй этот урок, чтобы призывать дух кошки и принимать её облик." } } } } },
