    [98739] = { d = 17.4, v = "tauren-female", n = { x = 170 }, c = { x = { { 0.00, "Теперь, получив моё благословение, возвращайся к Дендриту." }, { 4.83, "Он расскажет, что делать дальше." }, { 7.55, "Надеюсь, однажды мы встретимся снова." }, { 10.72, "Пусть тени всегда скрывают тебя, а твои враги оказываются у тебя в когтях, дитя." } } }, t = { d = 40.8, v = "nightelf-male#54", n = { x = 272 }, c = { x = { { 0.00, "*Когда ты подходишь, Дендрит делает ещё один незаметный жест в воздухе у себя над головой.*" }, { 8.06, "*Его окутывает новая аура силы, и он едва заметно улыбается.*" }, { 13.52, "Я чувствую в тебе кошачью хитрость и свирепость, которых не было, когда я отправил тебя к духу Великой Кошки." }, { 22.59, "По твоим глазам я вижу, что теперь ты понимаешь, какие скрытность и быстрота нужны, чтобы перенять эту природу." }, { 31.81, "Теперь ты можешь научиться сосредотачивать свою хитрость, принимать истинную природу кошки и взывать к её духу." } } } } },
    [98815] = { d = 31.3, v = "human-male", n = { x = 370 }, c = { x = { { 0.00, "На нагорье есть какие-то руины, и сейчас там работает экспедиция – пытаются разгадать их загадки." }, { 6.61, "А я вот знаю, что в тех горных болотах водятся звери и разнообразные твари, которые обитают только там." }, { 13.64, "Как насчёт того, чтобы сходить туда с хорошо снаряжёнными друзьями, а потом заключить со мной сделку?" }, { 20.50, "Принеси мне шкуры четырёх чащобных ящеров, а я подберу для тебя нечто такое, чтобы дело того стоило." }, { 27.47, "Они, возможно, будут прятаться, но ты их всё равно найди." } } }, t = { d = 12.8, v = "human-male", n = { x = 143 }, c = { x = { { 0.00, "Это одни из самых впечатляющих шкур, что я держал в руках; из них выйдет великолепная отделка для всех моих лучших изделий." }, { 8.89, "Спасибо." }, { 9.55, "Вот, примерь и выбери себе что-нибудь в обмен." } } } } },
    [98823] = { d = 36.6, v = "tauren-female#71", n = { x = 400 }, c = { x = { { 0.00, "Поистине удивительный предмет." }, { 2.36, "По всем признакам это нечто гораздо большее, чем просто резьба или скульптура." }, { 8.45, "Нашим старейшинам, возможно, было бы интересно взглянуть на этот артефакт, но истинной мудростью о погребённых руинах и забытых землях обладают лишь Служители Земли." }, { 21.06, "Найди Мулна Гнев Земли – столь важная находка заслуживает того, чтобы обратиться к нему напрямую." }, { 28.61, "Его и других старейшин совета Служителей Земли можно найти на Плато звездочётов на северо-западе Мулгора." } } }, t = { d = 37.3, g = 1, v = "tauren-male", n = { m = 305, f = 308 }, c = { m = { { 0.00, "Ах... в гуле этого осколка слышится голос самого мира." }, { 5.33, "Свет в нём – память о прошлом, мерцающая отблесками истории." }, { 11.01, "Должно быть, этот механизм титанов не одну сотню лет ждал, когда его поймут." }, { 18.41, "Ты поступил мудро, принеся осколок нам." }, { 22.19, "Служители Земли сохранят его, изучат и поделятся истинами, которые он хранит, когда мы сможем принять его послания." }, { 33.38, "Сегодня ты почтил стихии, путник." } }, f = { { 0.00, "Ах... в гуле этого осколка слышится голос самого мира." }, { 5.33, "Свет в нём – память о прошлом, мерцающая отблесками истории." }, { 11.01, "Должно быть, этот механизм титанов не одну сотню лет ждал, когда его поймут." }, { 18.41, "Ты поступила мудро, принеся осколок нам." }, { 22.94, "Служители Земли сохранят его, изучат и поделятся истинами, которые он хранит, когда мы сможем принять его послания." }, { 33.46, "Сегодня ты почтила стихии, путница." } } } } },
    [98824] = { d = 30.6, g = 1, v = "dwarf-male", n = { x = 332 }, c = { m = { { 0.00, "С такими похожими на письмена титанов надписями на гранях ему одна дорога – в Зал Исследователей Стальгорна." }, { 8.08, "Хочется думать, что за это тебя упомянут в каталоге: \"Найдено: путник!" }, { 13.40, "Подлинность подтверждена геологом Вельгаром...\" Эх, что-то меня понесло." }, { 18.79, "Старший исследователь Магеллас тебя примет и, учитывая изысканность твоей находки, наверняка щедро отблагодарит, если ты пожертвуешь её музею." }, { 29.43, "Отличная добыча!" } }, f = { { 0.00, "С такими похожими на письмена титанов надписями на гранях ему одна дорога – в Зал Исследователей Стальгорна." }, { 7.94, "Хочется думать, что за это тебя упомянут в каталоге: \"Найдено: путница!" }, { 13.23, "Подлинность подтверждена геологом Вельгаром...\" Эх, что-то меня понесло." }, { 18.52, "Старший исследователь Магеллас тебя примет и, учитывая изысканность твоей находки, наверняка щедро отблагодарит, если ты пожертвуешь её музею." }, { 28.97, "Отличная добыча!" } } }, t = { d = 31.8, g = 1, v = "dwarf-male", n = { m = 326, f = 331 }, c = { m = { { 0.00, "Что это у тебя?.." }, { 1.36, "Ничего себе!" }, { 2.38, "Вы только посмотрите, какая игра света!" }, { 5.45, "Я не видел ничего подобного со времён своих первых раскопок в старом Ульдамане." }, { 11.45, "Эти метки Хранителей ни с чем не спутаешь." }, { 14.65, "Передав этот предмет нам, ты оказал Лиге великую услугу." }, { 19.01, "Подобные находки раздвигают сами границы мудрости этого мира." }, { 23.78, "Мы обязательно в деталях опишем твой дар!" }, { 26.85, "Поистине славная работа, искатель приключений." } }, f = { { 0.00, "Что это у тебя?.." }, { 1.36, "Ничего себе!" }, { 2.38, "Вы только посмотрите, какая игра света!" }, { 5.45, "Я не видел ничего подобного со времён своих первых раскопок в старом Ульдамане." }, { 11.45, "Эти метки Хранителей ни с чем не спутаешь." }, { 14.65, "Передав этот предмет нам, ты оказала Лиге великую услугу." }