    [98907] = { d = 20.9, g = 1, v = "troll-male", n = { x = 187 }, c = { m = { { 0.00, "Битва за острова Чёрного Копья всё никак не сдвинется с мёртвой точки, герой." }, { 6.27, "Покажи балбесам из Альянса, кто тут сила." }, { 9.66, "Иди в бой с гордо поднятой головой, послужи Чёрному Копью и добудь победу." }, { 15.79, "Лоа уж точно дадут тебе своё благословение, герой!" } }, f = { { 0.00, "Битва за острова Чёрного Копья всё никак не сдвинется с мёртвой точки, героиня." }, { 6.49, "Покажи балбесам из Альянса, кто тут сила." }, { 9.88, "Иди в бой с гордо поднятой головой, послужи Чёрному Копью и добудь победу." }, { 15.97, "Лоа уж точно дадут тебе своё благословение, героиня!" } } } },
    [98908] = { d = 20.6, g = 1, v = "troll-male", n = { x = 187 }, c = { m = { { 0.00, "Битва за острова Чёрного Копья всё никак не сдвинется с мёртвой точки, герой." }, { 6.25, "Покажи балбесам из Альянса, кто тут сила." }, { 9.63, "Иди в бой с гордо поднятой головой, послужи Чёрному Копью и добудь победу." }, { 15.73, "Лоа уж точно дадут тебе своё благословение, герой!" } }, f = { { 0.00, "Битва за острова Чёрного Копья всё никак не сдвинется с мёртвой точки, героиня." }, { 6.51, "Покажи балбесам из Альянса, кто тут сила." }, { 9.89, "Иди в бой с гордо поднятой головой, послужи Чёрному Копью и добудь победу." }, { 15.71, "Лоа уж точно дадут тебе своё благословение, героиня!" } } } },
    [99046] = { d = 32.0, v = "nightelf-female#52", n = { x = 391 }, c = { x = { { 0.00, "Не так давно Совет Леса отправил к Древу-оракулу небольшой отряд часовых." }, { 5.05, "Порой Древо передаёт послания для наших старейшин, и мы должны доставлять их в Дарнасс." }, { 10.90, "Мне стало известно, что последняя отправившаяся туда бегунья до сих пор не вернулась." }, { 16.56, "Иногда оракул надолго замолкает, но прошло уж слишком много времени." }, { 21.24, "Проследуй по дороге на запад к Поляне Оракула и узнай, что случилось." }, { 25.93, "За посланием отправилась Эралия Тень Листвы, а она ещё только учится." }, { 30.62, "Да хранит тебя Элуна!" } } }, t = { d = 3.8, v = "nightelf-female#52", n = { x = 21 }, c = { x = { { 0.00, "Хвала Элуне..." }, { 1.71, "Я не умру... одна..." } } } } },
    [99047] = { d = 15.6, v = "nightelf-female#52", n = { x = 111 }, c = { x = { { 0.00, "Нас с сёстрами... отправили... к Древу-оракулу..." }, { 4.16, "У Древа... послание." }, { 5.96, "Я... повсюду... гарпии..." }, { 8.15, "Мне мало осталось..." }, { 11.45, "Никто не придёт." }, { 12.86, "Прошу..." }, { 13.64, "Бьянси... в Доланааре..." } } }, t = { d = 13.0, v = "nightelf-female#53", n = { x = 141 }, c = { x = { { 0.00, "Гарпий поразила та же порча, что появилась во всех наших лесах." }, { 4.65, "Не удивлюсь, если этим же недугом заражена и часовая Эралия." }, { 9.17, "Надо поспешить." }, { 10.37, "Ещё совсем немного, и она погибнет." } } } } },
    [99048] = { d = 25.8, v = "orc-male", n = { x = 270 }, c = { x = { { 0.00, "Одна воительница из Изувеченной Длани – клана, известного своей... изощрённой тактикой, – наблюдала за крепостью Тирагард издалека." }, { 10.19, "Внезапно мы перестали получать от неё донесения." }, { 13.94, "Вряд ли её могли схватить люди – боюсь, как бы тут не было замешано что-то более серьёзное." }, { 21.02, "Постарайся её найти." }, { 22.65, "Надеюсь, её доклад просто задерживается." } } }, t = { d = 11.0, v = "narrator", n = { x = 108 }, c = { x = { { 0.00, "Окоченевшее тело Хеглан лежит среди обломков хижины." }, { 4.60, "Непохоже, что её убил человек." }, { 7.21, "Возможно, рядом найдётся какая-нибудь зацепка." } } } } },
    [99049] = { d = 15.8, v = "narrator", n = { x = 0 }, c = { x = { { 0.00, "Всё вокруг было разрушено в бою." }, { 2.54, "Существам, напавшим на Хеглан, тоже крепко досталось." }, { 6.65, "Рядом наверняка найдутся следы, которые укажут, что произошло." }, { 11.45, "Лучше собрать для Оргнила зацепки, оставленные атакующими." } } }, t = { d = 14.0, v = "orc-male", n = { x = 143 }, c = { x = { { 0.00, "Это же знамя наг." }, { 1.44, "И осколок клинка тоже их!" }, { 3.52, "Должно быть, они пришли с северного берега." }, { 7.04, "Нельзя позволить им здесь закрепиться." }, { 10.06, "Колючий Холм не сможет воевать на два фронта сразу." } } } } },
    [99050] = { d = 35.5, v = "nightelf-female#53", n = { x = 399 }, c = { x = { { 0.00, "Мне нужны кое-какие ингредиенты, чтобы на время ослабить недуг Эралии – тогда она сможет добраться сюда для дальнейшего лечения." }, { 9.42, "К счастью, наш живой дом до сих пор щедро нас одаривает." }, { 13.38, "Поможет и сейчас." }, { 14.68, "Ключевой ингредиент, который мне нужен, это росистые ветви плёточников." }, { 19.81, "Их можно найти у озера Аль'Амет на юге отсюда или у Родникового озера и его притока на северо-западе." }, { 27.28, "Ещё мне понадобится пустая колба и немного ключевой воды." }, { 31.44, "Всё это можно купить в городе или у кого-нибудь выменять." } } }, t = { d = 9.6, v = "nightelf-female#53", n = { x = 105 }, c = { x = { { 0.00, "Спасибо за помощь." }, { 1.41, "Вот, возьми это, раз пришлось покупать колбу и воду." }, { 5.38, "Осталось приготовить бальзам." }, { 7.60, "Это не займёт много времени." } } } } },
    [99051] = { d = 17.6, v = "orc-male", n = { x = 191 }, c = { x = { { 0.00, "Эти ползучие твари уже не в первый раз к нам лезут." }, { 3.94, "Надо втолковать им, что мы не потерпим их присутствие." }, { 7.96, "Найди, где закрепились их разведчики, и убей всех." }, { 11.70, "В доказательство принеси их плавники." }, { 14.48, "Надо действовать быстро, чтобы нас поняли." } } }, t = { d = 10.5, v = "orc-male", n = { x = 107 }, c = { x = { { 0.00, "Надеюсь, теперь они уберутся на север." }, { 3.02, "Я размещу там пару рубак на случай, если кто-то остался в живых или эти наги ещё что-то задумали." } } } } },
    [99052] = { d = 24.2, v = "orc-male", n = { x = 242 }, c = { x = { { 0.00, "Один из наших разведчиков сообщил, что за теми нагами сюда пришёл морской великан." }, { 6.76, "Не знаю, специально они его привели или нет, но он очень опасен." }, { 12.12, "Великан ещё молодой, но даже такой запросто порвёт зазевавшегося орка пополам." }, { 18.52, "Надо от него избавиться." }, { 20.57, "Только советую позвать для этого пару друзей." } } }, t = { d = 11.9, v = "orc-male", n = { x = 114 }, c = { x = { { 0.00, "Ха!" }, { 0.30, "Я даже отсюда слышал, как он рухнул на землю!" }, { 4.18, "Гордись своей победой." }, { 6.15, "Немногие могут похвастаться тем, что выжили в бою с морским великаном." } } } } },
    [99053] = { d = 25.1, g = 1, v = "nightelf-female#52", n = { m = 289, f = 290 }, c = { m = { { 0.00, "Мои молитвы услышаны!" }, { 1.56, "Какое счастье, что ты сюда пробился." }, { 4.13, "Древо-оракул отправило меня сюда, чтобы передать послание спящим друидам, но когда я пришла, оказалось, что тут повсюду фурболги!" }, { 13.19, "Они набросились на меня прежде, чем я успела уйти, и утащили вниз – боюсь, припасли на ужин." }, { 19.63, "Не знаю как ты, но я не хочу здесь больше оставаться." }, { 23.26, "Калдорай не место под землёй." } }, f = { { 0.00, "Мои молитвы услышаны!" }, { 1.56, "Какое счастье, что ты сюда пробилась." }, { 4.18, "Древо-оракул отправило меня сюда, чтобы передать послание спящим друидам, но когда я пришла, оказалось, что тут повсюду фурболги!" }, { 13.22, "Они набросились на меня прежде, чем я успела уйти, и утащили вниз – боюсь, припасли на ужин." }, { 19.65, "Не знаю как ты, но я не хочу здесь больше оставаться." }, { 23.27, "Калдорай не место под землёй." } } }, t = { d = 16.6, g = 1, v = "nightelf-female#52", n = { m = 196, f = 199 }, c = { m = { { 0.00, "Слава Элуне, ты оказался рядом и спас Линессу от ужасной участи в лапах фурболгов Кривой Сосны." }, { 6.56, "Она одна из лучших в нашем отряде и моя дорогая подруга." }, { 10.54, "Прими это в знак благодарности." }, { 12.68, "Пусть эта вещь помогает тебе и дальше защищать калдорай." } }, f = { { 0.00, "Слава Элуне, ты оказалась рядом и спасла Линессу от ужасной участи в лапах фурболгов Кривой Сосны." }, { 6.77, "Она одна из лучших в нашем отряде и моя дорогая подруга." }, { 10.73, "Прими это в знак благодарности." }, { 12.86, "Пусть эта вещь помогает тебе и дальше защищать калдорай." } } } } },
    [99073] = { d = 16.4, v = "nightelf-female#53", n = { x = 177 }, c = { x = { { 0.00, "Бальзам готов." }, { 1.16, "Скорее отнеси его Эралии." }, { 3.21, "Вряд ли он исцелит её полностью: гниль быстро распространяется, и чем её больше, тем она сильнее." }, { 10.39, "Но это хотя бы облегчит страдания несчастной." }, { 13.88, "Ради такого тоже стоит поспешить." } } }, t = { d = 10.1, v = "nightelf-female#52", n = { x = 0 }, c = { x = { { 0.00, "*Когда ты помогаешь Эралии принять мазь, её дыхание быстро выравнивается.*" }, { 5.64, "*Возможно, она не выживет, но сейчас ей хоть немного легче.*" } } } } },
    [99079] = { d = 43.8, v = "tauren-male", n = { x = 413 }, c = { x = { { 0.00, "Дальноходы – самые надёжные разведчики нашего народа." }, { 4.55, "Они верны верховному вождю и только ему, но порой юный Бейн тоже прибегает к их помощи." }, { 12.17, "Это как раз такой случай." }, { 14.41, "Дальноход Мала отправилась к нашим восточным границам." }, { 19.11, "Она так и не вернулась прошлой ночью, а прошло уже три дня." }, { 24.19, "Когда такое случается, мы должны сделать всё, чтобы помочь разведчику." }, { 30.28, "Нельзя, чтобы наша деревня подверглась угрозе." }, { 34.36, "Покажи себя и найди Малу." }, { 36.67, "Ты узнаешь её по повязке на голове и посоху с перьями – такие есть у всех дальноходов." } } }, t = { d = 8.2, v = "narrator", n = { x = 82 }, c = { x = { { 0.00, "Совершенно очевидно, что смерть Малы была насильственной: из её спины и земли вокруг торчат стрелы." } } } } },
    [99080] = { d = 30.9, v = "creature/baine", n = { x = 293 }, c = { x = { { 0.00, "Послушай, что я скажу: мы не уступим кентаврам ни травинки с наших земель." }, { 6.30, "Отправляйся в их лагерь, пока они не восстановили силы и не ворвались в нашу деревню." }, { 13.60, "Убей всех до одного." }, { 15.36, "Никто не должен сбежать в Степи за подмогой." }, { 19.20, "А если отыщешь лидера готовящегося налёта, принеси его голову." }, { 24.58, "Мы выставим её в назидание тем, кто придёт сеять зло на земле наших предков." } } }, t = { d = 29.4, g = 1, v = "creature/baine", n = { m = 243, f = 242 }, c = { m = { { 0.00, "Ты весь в крови кентавров." }, { 2.52, "Запомни, каково это." }, { 4.60, "Для нашего брата нет более великой чести." }, { 8.69, "Я ощутил, как пал последний враг и земля перестала дрожать от их копыт." }, { 15.47, "Превосходно!" }, { 16.68, "Сегодня мы одержали великую победу для нашей деревни и обеспечили безопасность наших детей." }, { 25.54, "Благодарю тебя от всего сердца, герой." } }, f = { { 0.00, "Ты вся в крови кентавров." }, { 2.44, "Запомни, каково это." }, { 4.53, "Для нашего брата нет более великой чести." }, { 8.62, "Я ощутил, как пал последний враг и земля перестала дрожать от их копыт." }, { 15.42, "Превосходно!" }, { 16.64, "Сегодня мы одержали великую победу для нашей деревни и обеспечили безопасность наших детей." }, { 25.52, "Благодарю тебя от всего сердца, героиня." } } } } },
    [99081] = { d = 23.9, v = "narrator", n = { x = 260 }, c = { x = { { 0.00, "Вы ищете взглядом место, откуда могли прилететь стрелы: кентавры разбили новый лагерь." }, { 6.68, "В нём кипит бурная деятельность – похоже, в Мулгор проник небольшой отряд налётчиков." }, { 13.09, "Убитый дальноход всё ещё сжимает в руке отчёт о происходящем." }, { 17.66, "Храбрец Вольный Охотник должен узнать, что случилось с Малой – и кто именно её убил." } } }, t = { d = 4.5, v = "tauren-male", n = { x = 45 }, c = { x = { { 0.00, "Ужасные новости." }, { 1.49, "Надо немедленно предупредить Бейна!" } } } } },
    [99082] = { d = 42.1, v = "creature/baine", n = { x = 426 }, c = { x = { { 0.00, "Твоя отвага и готовность защищать свой народ достойны похвалы." }, { 5.24, "Отправляйся на северо-запад в Громовой Утёс, могучий город тауренов, укрывающий нас тенью в жаркие дни." }, { 13.78, "Попроси аудиенции у моего отца." }, { 16.47, "Это он объединился с новоиспечённым вождём Траллом и отвоевал эти равнины, навсегда изгнав кентавров." }, { 24.79, "Благодаря твоим действиям сегодня его подвиг не оказался напрасным." }, { 30.48, "Как верховный вождь, он щедро наградит тебя за труды." }, { 34.90, "Чтобы попасть к верховному вождю, поднимись на подъёмнике и пройди к центральному уступу." } } }, t = { d = 22.2, g = 1, v = "named/3057", n = { m = 218, f = 220 }, c = { m = { { 0.00, "Племя Галак посмело показаться в Мулгоре?!" }, { 6.50, "Ты оказал честь своим предкам, изгнав кентавров с наших земель." }, { 10.94, "Пусть помнят, что здесь их не ждёт ничего, кроме боли!" }, { 14.63, "Прими этот дар в честь своего подвига." }, { 17.32, "Пусть он верно служит тебе, где бы в царстве Матери-Земли ты ни оказался." } }, f = { { 0.00, "Племя Галак посмело показаться в Мулгоре?!" }, { 6.44, "Ты оказала честь своим предкам, изгнав кентавров с наших земель." }, { 10.91, "Пусть помнят, что здесь их не ждёт ничего, кроме боли!" }, { 14.56, "Прими этот дар в честь своего подвига." }, { 17.23, "Пусть он верно служит тебе, где бы в царстве Матери-Земли ты ни оказалась." } } } } },
    [99101] = { d = 14.6, v = "tauren-male", n = { x = 152 }, c = { x = { { 0.00, "Бейн Кровавое Копыто – предводитель нашей деревни." }, { 3.96, "Он должен узнать о вторжении как можно скорее." }, { 7.64, "Отыщи его в центре и передай отчёт дальнохода Малы." }, { 11.75, "И не медли." }, { 12.67, "Нам нельзя терять времени!" } } }, t = { d = 9.4, g = 1, v = "creature/baine", n = { m = 42, f = 43 }, c = { m = { { 0.00, "*Бейн листает отчёт, мрачнея с каждой секундой.*" }, { 4.32, "Мы этого так не оставим." }, { 6.66, "Спасибо, что передал это мне." } }, f = { { 0.00, "*Бейн листает отчёт, мрачнея с каждой секундой.*" }, { 4.40, "Мы этого так не оставим." }, { 6.70, "Спасибо, что передала это мне." } } } } },
    [99108] = { d = 38.2, g = 1, v = "tauren-male", n = { x = 334 }, c = { m = { { 0.00, "Приветствую тебя, герой." }, { 2.23, "Хоть ты и не воин и я не могу научить тебя, как им стать, это не значит, что мои наставления тебе не пригодятся." }, { 12.00, "Перед тобой арена." }, { 13.75, "Здесь не имеет значения, кого ты зовёшь матерью и чем сражаешься – мечом или луком." }, { 21.07, "Все равны, и все учатся точить рога в открытом бою." }, { 25.68, "Если хочешь, можешь войти в наш круг и постичь наши обычаи." }, { 31.01, "Сразись с любым из этих новичков или с любым другим желающим." }, { 36.57, "Мне всё равно, с кем." } }, f = { { 0.00, "Приветствую тебя, героиня." }, { 2.29, "Хоть ты и не воин и я не могу научить тебя, как им стать, это не значит, что мои наставления тебе не пригодятся." }, { 11.66, "Перед тобой арена." }, { 13.33, "Здесь не имеет значения, кого ты зовёшь матерью и чем сражаешься – мечом или луком." }, { 20.34, "Все равны, и все учатся точить рога в открытом бою." }, { 24.76, "Если хочешь, можешь войти в наш круг и постичь наши обычаи." }, { 29.87, "Сразись с любым из этих новичков или с любым другим желающим." }, { 35.20, "Мне всё равно, с кем." } } }, t = { d = 16.6, g = 1, v = "tauren-male", n = { x = 129 }, c = { m = { { 0.00, "Твоё умение делает мне честь, герой." }, { 3.60, "Быть может, у нового поколения ещё есть надежда." }, { 8.36, "Возьми это, чтобы залечить раны, ведь в этом суровом мире тебя ждёт ещё много битв." } }, f = { { 0.00, "Твоё умение делает мне честь, героиня." }, { 3.68, "Быть может, у нового поколения ещё есть надежда." }, { 8.33, "Возьми это, чтобы залечить раны, ведь в этом суровом мире тебя ждёт ещё много битв." } } } } },
    [99123] = { d = 14.6, v = "troll-female#75", n = { x = 172 }, c = { x = { { 0.00, "Я решила в одиночку немного разведать обстановку на утёсе." }, { 4.08, "К несчастью, моя магия иссякла в самый неподходящий момент, и с тех пор я прячусь здесь." }, { 10.26, "Буду очень признательна, если ты поможешь мне отсюда выбраться." } } }, t = { d = 18.9, g = 1, v = "troll-male", n = { m = 193, f = 195 }, c = { m = { { 0.00, "А, Пал'джу снова угодила в переделку, да?" }, { 3.16, "Будем надеяться, что на этот раз она усвоит урок и перестанет ходить в одиночку." }, { 9.34, "Спасибо, что помог ей выбраться." }, { 11.82, "Она подающая большие надежды охотница, вот только ведёт себя скорее как ящер, а не тигр." } }, f = { { 0.00, "А, Пал'джу снова угодила в переделку, да?" }, { 3.32, "Будем надеяться, что на этот раз она усвоит урок и перестанет ходить в одиночку." }, { 9.61, "Спасибо, что помогла ей выбраться." }, { 12.27, "Она подающая большие надежды охотница, вот только ведёт себя скорее как ящер, а не тигр." } } } } },
    [99127] = { d = 18.2, v = "human-male", n = { x = 215 }, c = { x = { { 0.00, "Рыба сегодня не клюёт, и вообще с ней творится что-то неладное." }, { 4.25, "Дело не только в пустых крючках – я вообще ни одной рыбёшки в воде не видел." }, { 9.40, "Ли оставил на ночь ловушки, пойди, что ли, посмотри, попалось хоть что-то или нет." }, { 14.86, "А если заметишь нечто странное, принеси посмотреть." } } }, t = { d = 11.2, v = "human-male", n = { x = 118 }, c = { x = { { 0.00, "И что, все сети в таком состоянии?" }, { 2.58, "Похоже, наши новые соседи-вредители натворили больше бед, чем мы думали." }, { 8.09, "Если с этим ничего не сделать, я разорюсь." } } } } },
    [99128] = { d = 16.6, v = "human-male", n = { x = 179 }, c = { x = { { 0.00, "Это наверняка дело рук тех мурлоков с другого берега озера." }, { 4.50, "Мерзкие мелкие твари – нрав злобный, зубы острющие." }, { 8.39, "Если так пойдёт и дальше, во всём озере рыбы не останется." }, { 12.68, "Сократи слегка их поголовье, а?" }, { 15.03, "Ты мне очень поможешь." } } }, t = { d = 11.5, v = "human-male", n = { x = 135 }, c = { x = { { 0.00, "Я их бульканье отсюда слышу, оно мне теперь в кошмарах являться будет." }, { 4.85, "В любом случае, это должно поумерить их пыл... хотя не сомневаюсь, что они быстро восполнят потери." } } } } },
    [99129] = { d = 14.6, v = "human-male", n = { x = 164 }, c = { x = { { 0.00, "Реми на днях что-то говорил о мурлоках..." }, { 2.89, "Уверен, он ненавидит этих мелких паразитов не меньше моего." }, { 7.11, "Может, у него есть идеи, как отвадить их от моей рыбы." }, { 10.95, "Сходи, поговори с ним и узнай, что он может предложить." } } }, t = { d = 12.2, v = "human-male", n = { x = 149 }, c = { x = { { 0.00, "А я говорил стражникам об этих мурлоках, да разве кто послушал?" }, { 4.24, "У меня есть пара идей, как поквитаться с этими тварями." }, { 8.00, "Но тут понадобится твоя помощь, чтобы раздобыть всё необходимое." } } } } },
    [99130] = { d = 27.0, v = "human-male", n = { x = 319 }, c = { x = { { 0.00, "У меня есть пара идей, как разобраться с мурлоками." }, { 3.56, "И одна из них заодно поможет ещё кое-кому." }, { 6.56, "В здешних усадьбах часто растёт сорняк под названием закатнолист; в больших количествах его лепестки ядовиты для большинства животных." }, { 15.80, "Если сделать из него приманку для мурлоков, глядишь, эти твари наконец научатся держаться подальше." }, { 22.79, "Заодно и поля фермерам расчистишь." }, { 25.23, "Одни плюсы... одни плюсы." } } }, t = { d = 9.9, v = "human-male", n = { x = 111 }, c = { x = { { 0.00, "Дай мне минутку..." }, { 1.31, "Приманка простенькая, но если ничей питомец до неё не доберётся, она безопасна." }, { 6.99, "Только скажи Джейсону, чтобы сам её не ел." } } } } },
    [99131] = { d = 13.2, v = "human-male", n = { x = 160 }, c = { x = { { 0.00, "Передай Матерсу, что приманку можно будет забрать уже сегодня." }, { 4.31, "Я расскажу ему, как её применять." }, { 6.55, "Надеюсь, скоро он снова сможет начать торговать рыбой." }, { 10.31, "А поголовье мурлоков в этом мире сократится." } } }, t = { d = 8.1, v = "human-male", n = { x = 91 }, c = { x = { { 0.00, "Отравленная приманка?" }, { 1.58, "Главное, чтобы рыба на неё не позарилась, а так должно сработать." }, { 6.32, "Заберу её у Реми попозже." } } } } },
    [99134] = { d = 20.8, v = "scourge-male", n = { x = 208 }, c = { x = { { 0.00, "Ты не из стражей смерти, так что я в тебе пока не разочаровался." }, { 5.22, "В качестве награды за отсутствие некомпетентности ты получаешь возможность покарать тех, у кого её в достатке." }, { 14.17, "Шевелись там, как тебя?" }, { 16.11, "А не то внесу в свой список как награду для кого-нибудь ещё." } } }, t = { d = 17.1, g = 1, v = "scourge-male", n = { m = 134, f = 135 }, c = { m = { { 0.00, "Смерть оставила нам на удивление мало радостей." }, { 4.82, "К счастью, боль – главная из них." }, { 8.16, "Сегодня ты порадовал меня, а значит, и Тёмную Госпожу." }, { 13.72, "Возможно, ты нам ещё пригодишься." } }, f = { { 0.00, "Смерть оставила нам на удивление мало радостей." }, { 4.86, "К счастью, боль – главная из них." }, { 8.23, "Сегодня ты порадовала меня, а значит, и Тёмную Госпожу." }, { 13.93, "Возможно, ты нам ещё пригодишься." } } } } },
    [99141] = { d = 41.7, g = 1, v = "scourge-male", n = { x = 386 }, c = { m = { { 0.00, "Запомни, герой, Тёмная Госпожа требует неукоснительного выполнения своих приказов." }, { 7.22, "И, как палач, я обязан за этим следить." }, { 10.72, "Донесения от нескольких моих стражей смерти запаздывают." }, { 15.72, "Излишне говорить, что моё терпение лопнуло." }, { 19.53, "Забери у них донесения и принеси мне – именем Тёмной Госпожи." }, { 24.85, "Стража смерти Диллинжера ты найдёшь чуть западнее, у кладбища." }, { 30.25, "Страж смерти Кристоф стоит на постое у путевой станции на востоке." }, { 36.12, "И проведай поганище Гордо – он бродит на западе, у Тихого омута." } }, f = { { 0.00, "Запомни, героиня, Тёмная Госпожа требует неукоснительного выполнения своих приказов." }, { 7.36, "И, как палач, я обязан за этим следить." }, { 10.84, "Донесения от нескольких моих стражей смерти запаздывают." }, { 15.82, "Излишне говорить, что моё терпение лопнуло." }, { 19.61, "Забери у них донесения и принеси мне – именем Тёмной Госпожи." }, { 24.91, "Стража смерти Диллинжера ты найдёшь чуть западнее, у кладбища." }, { 30.29, "Страж смерти Кристоф стоит на постое у путевой станции на востоке." }, { 36.14, "И проведай поганище Гордо – он бродит на западе, у Тихого омута." } } }, t = { d = 17.6, g = 1, v = "scourge-male", n = { m = 148, f = 149 }, c = { m = { { 0.00, "Как я мог подумать, что поганище способно написать что-то путное?" }, { 5.96, "Пусть эта ошибка останется между нами." }, { 9.60, "Ты порадовал меня, а значит, и Тёмную Госпожу." }, { 13.82, "Возможно, из тебя ещё выйдет толк." } }, f = { { 0.00, "Как я мог подумать, что поганище способно написать что-то путное?" }, { 6.21, "Пусть эта ошибка останется между нами." }, { 10.00, "Ты порадовала меня, а значит, и Тёмную Госпожу." }, { 14.49, "Возможно, из тебя ещё выйдет толк." } } } } },
    [99142] = { d = 40.4, v = "scourge-male#82", n = { x = 362 }, c = { x = { { 0.00, "Если ты направляешься на восток, к ферме Балнира, у меня есть для тебя ещё дело." }, { 7.15, "Хороших помощников нынче днём с огнём не сыщешь – твоя встреча с Гордо это наглядно показала." }, { 15.50, "Я вношу в погибельник кое-какие алхимические изменения и пересаживаю на той усадьбе – работа всей моей смерти." }, { 25.30, "Я называю этот сорт гроб-травой, и он приведёт меня к тому, что предначертано мне судьбой." }, { 33.17, "Пока ты там, присмотри-ка за Плетью." }, { 36.38, "Её словно... тянет... к этой траве." }, { 39.60, "Любопытно." } } }, t = { d = 24.6, v = "scourge-male#82", n = { x = 175 }, c = { x = { { 0.00, "Просто великолепно!" }, { 2.96, "*Младший аптекарь Холланд осматривает траву.*" }, { 6.40, "Хм, я надеялся, что её созревание будет несколько более... агрессивным." }, { 13.20, "Впрочем, прогресс есть прогресс!" }, { 16.35, "Благодаря твоим сегодняшним трудам погибнет великое множество." }, { 22.45, "Можешь собой гордиться." } } } } },
    [99143] = { d = 13.3, v = "human-male", n = { x = 154 }, c = { x = { { 0.00, "Эти рыболюди ведь наверняка мыслят как настоящие рыбы, да?" }, { 4.04, "А значит, всё, что нравится им, понравится и рыбе!" }, { 7.46, "Порыскай в их хламе и принеси мне всё, что сгодится на наживку, а я в долгу не останусь." } } }, t = { d = 9.2, v = "human-male", n = { x = 104 }, c = { x = { { 0.00, "Занятная коллекция." }, { 1.43, "Думаю, сойдёт!" }, { 2.47, "Вот кое-что из моих старых припасов." }, { 5.13, "Пригодится любому, кто делает первые шаги в рыбной ловле." } } } } },
    [99144] = { d = 44.6, g = 1, v = "scourge-male", n = { m = 390, f = 390 }, c = { m = { { 0.00, "Хвала Свету за то, что ты меня нашёл." }, { 3.08, "Я направлялся из крепости Бандариона в Брилл с посланием для Шари Стилвелл, когда меня схватили эти чудовища." }, { 12.18, "Они обращаются к Свету с такой ненавистью в сердцах, что даже остатки моей крови закипают." }, { 19.84, "Это противоречит всему, ради чего я предаюсь медитации... всему, что я стремлюсь защитить!" }, { 27.36, "*Барет Рассветная Скала собирается с силами.*" }, { 30.96, "Знаю, кое-кто до сих пор недолюбливает таких, как я, но заверяю тебя: наши намерения чисты." }, { 38.95, "Если поможешь мне выбраться отсюда, я буду вечно тебе благодарен." } }, f = { { 0.00, "Хвала Свету за то, что ты меня нашла." }, { 2.94, "Я направлялся из крепости Бандариона в Брилл с посланием для Шари Стилвелл, когда меня схватили эти чудовища." }, { 11.40, "Они обращаются к Свету с такой ненавистью в сердцах, что даже остатки моей крови закипают." }, { 18.53, "Это противоречит всему, ради чего я предаюсь медитации... всему, что я стремлюсь защитить!" }, { 25.52, "*Барет Рассветная Скала собирается с силами.*" }, { 29.04, "Знаю, кое-кто до сих пор недолюбливает таких, как я, но заверяю тебя: наши намерения чисты." }, { 36.75, "Если поможешь мне выбраться отсюда, я буду вечно тебе благодарен." } } }, t = { d = 33.4, g = 1, v = "scourge-female#80", n = { m = 327, f = 329 }, c = { m = { { 0.00, "Пусть Свет благословит тебя за то, что ты помог Рассветной Скале." }, { 5.34, "Наш орден здесь только пускает корни, и потерять столь многообещающего брата раньше срока было бы ужасно." }, { 14.14, "Прими это в знак нашей благодарности." }, { 17.30, "Если когда-нибудь заинтересуешься нашими обычаями, наш монастырь – крепость Бандариона – стоит на утёсах к северо-западу от фермы Соллидена." }, { 28.89, "Мы принимаем всех, кто ищет наставления в Свете." } }, f = { { 0.00, "Пусть Свет благословит тебя за то, что ты помогла Рассветной Скале." }, { 5.57, "Наш орден здесь только пускает корни, и потерять столь многообещающего брата раньше срока было бы ужасно." }, { 14.51, "Прими это в знак нашей благодарности." }, { 17.71, "Если когда-нибудь заинтересуешься нашими обычаями, наш монастырь – крепость Бандариона – стоит на утёсах к северо-западу от фермы Соллидена." }, { 29.47, "Мы принимаем всех, кто ищет наставления в Свете." } } } } },
    [99152] = { d = 37.4, v = "scourge-female#80", n = { x = 379 }, c = { x = { { 0.00, "Хоть омрачённые в Тенедоле к юго-западу и представляют явную угрозу, нельзя допустить, чтобы его подвалы превратились в очаг полномасштабного восстания Плети у стен крепости Бандариона." }, { 15.28, "Мне нужно привести этих новобранцев в форму на случай, если это произойдёт." }, { 21.57, "А вот ты получишь то, что я называю учёбой с погружением." }, { 26.13, "Спустись под Тенедол и добудь несколько костей, которые можно изучить." }, { 32.05, "Мне нужны светящиеся, в которых ещё сохранилась магия воскрешения." } } }, t = { d = 11.4, g = 1, v = "scourge-female#80", n = { x = 93 }, c = { m = { { 0.00, "Молодец, герой." }, { 1.56, "С этими костями мы, возможно, лучше сумеем понять, как такая угроза столь долго оставалась незамеченной." } }, f = { { 0.00, "Молодец, героиня." }, { 1.64, "С этими костями мы, возможно, лучше сумеем понять, как такая угроза столь долго оставалась незамеченной." } } } } },
    [99153] = { d = 29.4, v = "scourge-male#83", n = { x = 314 }, c = { x = { { 0.00, "Эй, ты!" }, { 0.54, "Слухи здесь разлетаются быстро." }, { 2.91, "Слышал о твоей работе с сектантами на месте битвы с Наксрамасом." }, { 7.78, "Беда в том, что один из этих сектантов улизнул с осколком фокусирующего кристалла." }, { 13.94, "Похоже, в нём ещё остался заряд." }, { 16.38, "По нашим прикидкам, он где-то под Тенедолом." }, { 19.69, "Он либо поднимает мертвецов, либо делает их сильнее – и то и другое нам ни к чему." }, { 25.85, "Найди кристалл, пока дело не запахло керосином." } } }, t = { d = 5.5, v = "scourge-male#83", n = { x = 39 }, c = { x = { { 0.00, "Отлично – и как быстро!" }, { 2.51, "А теперь моя любимая часть..." } } } } },
    [99156] = { d = 44.6, g = 1, v = "scourge-female", n = { m = 390, f = 391 }, c = { m = { { 0.00, "Проклятье!" }, { 1.00, "Пока ты был в патруле, нам поступило новое донесение." }, { 5.93, "В восточной части Тирисфальских лесов, у Долины ядовитых пауков, видели отбившееся от рук поганище." }, { 15.11, "Тут что-то нечисто." }, { 16.95, "Поганища не проскальзывают незаметно мимо Бастиона." }, { 21.71, "Держи это дело в строжайшей тайне." }, { 25.05, "Но учти: такая тварь легко не сдастся; отправься туда в одиночку и станешь всего лишь её следующим обедом." }, { 34.90, "Уладь это дело, и получишь достойную награду." }, { 39.24, "В доказательство принеси мне сердце этого поганища." } }, f = { { 0.00, "Проклятье!" }, { 1.01, "Пока ты была в патруле, нам поступило новое донесение." }, { 6.17, "В восточной части Тирисфальских лесов, у Долины ядовитых пауков, видели отбившееся от рук поганище." }, { 15.47, "Тут что-то нечисто." }, { 17.33, "Поганища не проскальзывают незаметно мимо Бастиона." }, { 22.15, "Держи это дело в строжайшей тайне." }, { 25.53, "Но учти: такая тварь легко не сдастся; отправься туда в одиночку и станешь всего лишь её следующим обедом." }, { 35.51, "Уладь это дело, и получишь достойную награду." }, { 39.91, "В доказательство принеси мне сердце этого поганища." } } }, t = { d = 16.5, v = "scourge-female", n = { x = 136 }, c = { x = { { 0.00, "Ты живое свидетельство того, что всем Отрёкшимся присуща хитрость и командный дух, чего у безмозглой Плети не будет никогда." }, { 12.31, "Как я и обещала, вот твоя награда за труды." } } } } },
    [99158] = { d = 32.7, v = "dwarf-male", n = { x = 383 }, c = { x = { { 0.00, "В горах живёт жрец из ордена под названием Серебряный Рассвет." }, { 4.34, "Это святое братство, посвятившее себя поиску и истреблению всего нечестивого и противоестественного." }, { 11.42, "Впрочем, отец Гавин скорее из тех, кто стремится всем помочь и всех исцелить, а не хвататься за оружие." }, { 18.63, "Он привёл в порядок старое здание, чтобы путники могли там отдохнуть, и назвал его Сторожкой у заснеженной сосны." }, { 26.67, "Мне нужно передать ему партию святых свечей." }, { 29.93, "Не отнесёшь ему, раз уж тебе в ту сторону?" } } }, t = { d = 11.3, v = "human-male", n = { x = 126 }, c = { x = { { 0.00, "А, свечи из Стальгорна." }, { 1.72, "Хотя в своей обители я почти ни в чём не нуждаюсь, есть несколько важных вещей, за которые я благодарен городу и благочестивым людям." } } } } },
    [99159] = { d = 15.9, v = "human-male", n = { x = 164 }, c = { x = { { 0.00, "Мой очаг открыт для любой души, что ищет тепла, но я хотел бы попросить тебя о помощи, если можно." }, { 7.72, "Мне просто нужно больше дров." }, { 10.02, "Обычно я заготавливаю их сам, но в последнее время меня отвлекают другие дела." } } }, t = { d = 11.5, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Просто превосходно." }, { 1.47, "Эти подойдут – а те, что ещё слишком сырые, я оставлю сушиться." }, { 6.13, "У меня есть и другие дела, с которыми мне не помешала бы помощь." }, { 10.87, "Подсобишь?" } } } } },
    [99160] = { d = 21.3, v = "human-male", n = { x = 257 }, c = { x = { { 0.00, "Сложно не заметить, что поблизости бродят элементали." }, { 3.65, "Пару дней назад с горных вершин сорвался пласт камня и льда и растревожил их." }, { 8.92, "Эти заснеженные горы и так опасны для обычного дворфа или человека, а тут ещё и стихии обрели плоть." }, { 15.79, "Я больше не боец, так что каждый уничтоженный тобой дух сделает дорогу безопаснее." } } }, t = { d = 9.3, v = "human-male", n = { x = 104 }, c = { x = { { 0.00, "Жаль, что нельзя было их просто умиротворить." }, { 3.30, "Увы, это выше моих возможностей, а оставлять их без присмотра было слишком опасно." } } } } },
    [99161] = { d = 19.9, v = "human-male", n = { x = 223 }, c = { x = { { 0.00, "Я заметил, что первый элементаль, появившийся после обвала, был крупнее остальных." }, { 6.01, "И, насколько я могу судить, именно он источник внезапных перемен погоды и других мелких оползней." }, { 13.20, "Я назвал его Лавин." }, { 14.72, "Если убьёшь его и принесёшь в доказательство его ядро, я тебя вознагражу." } } }, t = { d = 9.4, g = 1, v = "human-male", n = { x = 103 }, c = { m = { { 0.00, "Да хранит тебя Свет, герой." }, { 1.99, "Благодаря тебе здесь стало намного безопаснее, и теперь, надеюсь, нам удастся избежать ненужных смертей." } }, f = { { 0.00, "Да хранит тебя Свет, героиня." }, { 2.10, "Благодаря тебе здесь стало намного безопаснее, и теперь, надеюсь, нам удастся избежать ненужных смертей." } } } } },
    [99162] = { d = 28.3, v = "human-male", n = { x = 330 }, c = { x = { { 0.00, "Даже горным пехотинцам из Стальгорна приходится держать ухо востро, пересекая вершины Дун Морога." }, { 6.94, "Сходы снега и льда нередко обрывают жизни новичков." }, { 10.63, "После обвала я обычно разыскиваю следы выживших или погибших – и молюсь Свету, чтобы никого не найти." }, { 17.95, "Но пока стихии неспокойны, я не решался уходить далеко." }, { 21.89, "Если отыщешь пропавших горных пехотинцев и принесёшь мне их ружья, я отправлю их в Стальгорн." } } }, t = { d = 11.2, v = "human-male", n = { x = 138 }, c = { x = { { 0.00, "Горные пехотинцы вырезают свои имена на прикладах ружей." }, { 3.82, "Это помогает опознать их, если что-то случится." }, { 7.04, "Я отправлю ружья в Стальгорн – там кто-нибудь передаст их родным." } } } } },
    [99187] = { d = 33.1, v = "human-male", n = { x = 353 }, c = { x = { { 0.00, "Пусть ты и не рыцарь Лордерона — хотя, быть может, в каком-то смысле так и есть, — но ты по-прежнему паладин... и знаешь силу клятвы." }, { 9.71, "Черночревы — могущественные тотемисты, и они распознали бы силу такого артефакта, как Реликварий." }, { 16.87, "Без сомнения, он всё ещё у них." }, { 19.08, "Поэтому я прошу тебя: закончи начатое мною дело." }, { 22.83, "Верни Реликварий Тира сюда, в Тирисфальские леса, где ему место." }, { 27.71, "Лишь тогда моя клятва будет исполнена, и мой дух сможет покинуть этот мир." } } } },
    [99191] = { t = { d = 4.6, v = "skyborne-female", n = { x = 42 }, c = { x = { { 0.00, "Чудесно!" }, { 0.86, "Благодарим тебя за щедрое пожертвование!" } } } } },
    [99193] = { d = 28.4, g = 1, v = "skyborne-female", n = { m = 317, f = 318 }, c = { m = { { 0.00, "Наши маги с увлечением изучают свойства этой «магической ткани», которая так распространена здесь, на Азероте." }, { 8.05, "Если ты сможешь пожертвовать шестьдесят отрезов магической ткани, это очень поможет нашим исследованиям." }, { 15.78, "И Высший орден наверняка отметит такую щедрость!" }, { 19.41, "Если у тебя при себе шестьдесят отрезов магической ткани и ты готов их пожертвовать, я могу принять их прямо сейчас." } }, f = { { 0.00, "Наши маги с увлечением изучают свойства этой «магической ткани», которая так распространена здесь, на Азероте." }, { 8.05, "Если ты сможешь пожертвовать шестьдесят отрезов магической ткани, это очень поможет нашим исследованиям." }, { 15.78, "И Высший орден наверняка отметит такую щедрость!" }, { 19.41, "Если у тебя при себе шестьдесят отрезов магической ткани и ты готова их пожертвовать, я могу принять их прямо сейчас." } } } },
    [99194] = { d = 26.3, v = "skyborne-female", n = { x = 293 }, c = { x = { { 0.00, "Благодарим тебя за прежние пожертвования Высшему ордену." }, { 4.24, "Мы изо всех сил стараемся обеспечить наш народ тканью, и рунной ткани сейчас особенно не хватает." }, { 11.52, "Искренне надеемся, что ты и на этот раз нам поможешь!" }, { 15.42, "Если согласишься, принеси мне столько рунной ткани, сколько не жалко." }, { 20.68, "Для начала мы примем одно пожертвование в шестьдесят отрезов, а там посмотрим." } } } },
    [99196] = { t = { d = 6.0, g = 1, v = "skyborne-female", n = { m = 56, f = 59 }, c = { m = { { 0.00, "Благодарим тебя за щедрое пожертвование!" }, { 3.65, "Да хранят тебя ветра, друг." } }, f = { { 0.00, "Благодарим тебя за щедрое пожертвование!" }, { 3.46, "Да хранят тебя ветра, подруга." } } } } },
    [99198] = { d = 26.7, g = 1, v = "skyborne-female", n = { m = 306, f = 307 }, c = { m = { { 0.00, "Магическая ткань обладает любопытными свойствами, которые очень интересуют Ваятелей ветра." }, { 6.47, "Если ты сможешь пожертвовать шестьдесят отрезов магической ткани, мы будем весьма признательны." }, { 13.32, "И такую щедрость наш орден наверняка не оставит без внимания!" }, { 17.72, "Если у тебя с собой шестьдесят отрезов магической ткани и ты готов их пожертвовать, я могу принять их прямо сейчас." } }, f = { { 0.00, "Магическая ткань обладает любопытными свойствами, которые очень интересуют Ваятелей ветра." }, { 6.47, "Если ты сможешь пожертвовать шестьдесят отрезов магической ткани, мы будем весьма признательны." }, { 13.32, "И такую щедрость наш орден наверняка не оставит без внимания!" }, { 17.72, "Если у тебя с собой шестьдесят отрезов магической ткани и ты готова их пожертвовать, я могу принять их прямо сейчас." } } } },
    [99257] = { d = 37.3, g = 1, v = "nightelf-male#59", n = { m = 428, f = 429 }, c = { m = { { 0.00, "Пока я в ужасе наблюдал, как ты бродишь по проклятому лесу с моей бесценной реликвией, меня посетила одна мысль." }, { 7.86, "Нестабильные разломы, которые ты там видел, это то, что осталось от наших защитников столпов." }, { 14.34, "Уже много столетий мы не можем сотворять новых стражей, и я боюсь представить, что с нами будет, когда оставшиеся тоже неизбежно угаснут." }, { 24.03, "И это прозвучит странно, но... попробуй найти ещё одного защитника столпа, который выглядит так, словно вот-вот коллапсирует, и извлеки его кристаллическое сердце." }, { 35.42, "Потом я всё объясню." } }, f = { { 0.00, "Пока я в ужасе наблюдал, как ты бродишь по проклятому лесу с моей бесценной реликвией, меня посетила одна мысль." }, { 7.72, "Нестабильные разломы, которые ты там видела, это то, что осталось от наших защитников столпов." }, { 14.87, "Уже много столетий мы не можем сотворять новых стражей, и я боюсь представить, что с нами будет, когда оставшиеся тоже неизбежно угаснут." }, { 24.56, "И это прозвучит странно, но... попробуй найти ещё одного защитника столпа, который выглядит так, словно вот-вот коллапсирует, и извлеки его кристаллическое сердце." }, { 35.95, "Потом я всё объясню." } } } },
    [99258] = { d = 29.9, v = "nightelf-male#59", n = { x = 357 }, c = { x = { { 0.00, "Поиски самоцветов, необходимых для призыва элементалей, уже сложная задача, но главный вопрос заключается в том, осталось ли в Шен'драласе достаточно свободной маны." }, { 11.37, "С этим сердцем мы сможем точно узнать, пора ли уже начинать искать другие способы защиты." }, { 17.75, "Твоя задача проста: брось самоцвет в один из нестабильных разломов." }, { 22.44, "Если нам повезёт, тебе придётся сражаться." }, { 25.31, "И не сдерживайся: если один раз получилось, то получится и во второй." } } } },
    [99260] = { d = 34.9, g = 1, v = "skyborne-male", n = { m = 399, f = 401 }, c = { m = { { 0.00, "Мне поручили собрать важные сведения о токе стихийной энергии через Дозорные монолиты." }, { 6.22, "Это жизненно необходимо для обеспечения безопасности путешествий между Небесной высью и Азеротом: без этой информации расчёты будут неточными, и попытки провести неборезы через царство стихии закончатся крушением." }, { 21.36, "Но собранная мною информация была утеряна, и я не в состоянии начать всё сначала." }, { 27.14, "Я рассказал верховному магистру о том, что ты меня спас, и он хочет ещё раз с тобой поговорить." } }, f = { { 0.00, "Мне поручили собрать важные сведения о токе стихийной энергии через Дозорные монолиты." }, { 6.42, "Это жизненно необходимо для обеспечения безопасности путешествий между Небесной высью и Азеротом: без этой информации расчёты будут неточными, и попытки провести неборезы через царство стихии закончатся крушением." }, { 22.05, "Но собранная мною информация была утеряна, и я не в состоянии начать всё сначала." }, { 28.01, "Я рассказал верховному магистру о том, что ты меня спасла, и он хочет ещё раз с тобой поговорить." } } }, t = { d = 32.3, g = 1, v = "skyborne-male", n = { m = 357, f = 359 }, c = { m = { { 0.00, "Спасибо, что спас Филлиона." }, { 1.97, "Уверен, он уже рассказал тебе, как важны данные, за которыми его посылали." }, { 7.49, "Без этих данных наши надежды проложить безопасные пути в Азерот под серьёзной угрозой." }, { 13.79, "Наши лазутчики докладывают, что Ваятели ветра и сами раздобыли способ странствовать между планами – и, без сомнения, ревниво берегут эту тайну." }, { 24.30, "Как всегда, их догматичная гордыня для них важнее блага нашего народа." }, { 29.42, "Они немногим лучше секты Ал'акет." } }, f = { { 0.00, "Спасибо, что спасла Филлиона." }, { 2.19, "Уверен, он уже рассказал тебе, как важны данные, за которыми его посылали." }, { 7.75, "Без этих данных наши надежды проложить безопасные пути в Азерот под серьёзной угрозой." }, { 14.11, "Наши лазутчики докладывают, что Ваятели ветра и сами раздобыли способ странствовать между планами – и, без сомнения, ревниво берегут эту тайну." }, { 24.71, "Как всегда, их догматичная гордыня для них важнее блага нашего народа." }, { 29.88, "Они немногим лучше секты Ал'акет." } } } } },
    [99267] = { t = { d = 31.3, g = 1, v = "narrator", n = { m = 332, f = 333 }, c = { m = { { 0.00, "Мёртвый ночной дозорный, лежащий перед тобой, весь покрыт глубокими рваными ранами." }, { 6.55, "Ясно, что его растерзал какой-то крупный зверь." }, { 10.29, "Ты замечаешь, что в руке мертвеца всё ещё зажат незажжённый факел." }, { 15.36, "Видимо, ты не забрал его раньше." }, { 17.97, "Ты наклоняешься и вытаскиваешь его из закоченевших пальцев." }, { 22.55, "Он может пригодиться в странствиях по Сумеречному лесу и за его пределами, чтобы раскрывать то, что скрыто во тьме." } }, f = { { 0.00, "Мёртвый ночной дозорный, лежащий перед тобой, весь покрыт глубокими рваными ранами." }, { 6.34, "Ясно, что его растерзал какой-то крупный зверь." }, { 9.95, "Ты замечаешь, что в руке мертвеца всё ещё зажат незажжённый факел." }, { 14.86, "Видимо, ты не забрала его раньше." }, { 17.45, "Ты наклоняешься и вытаскиваешь его из закоченевших пальцев." }, { 21.88, "Он может пригодиться в странствиях по Сумеречному лесу и за его пределами, чтобы раскрывать то, что скрыто во тьме." } } } } },
    [99326] = { d = 33.4, g = 1, v = "human-female", n = { m = 388, f = 389 }, c = { m = { { 0.00, "Приветствую!" }, { 0.88, "Хочешь взглянуть на наших лошадей?" }, { 3.34, "Эти скакуны ведут род и от старинной лордеронской породы, и от наших местных лошадей." }, { 9.34, "Более надёжного спутника в странствиях тебе не найти." }, { 13.06, "Выбрать будет непросто: все они превосходны и обучены сохранять спокойствие даже в опасности." }, { 19.63, "Не забывай: вам с лошадью предстоит вместе объехать весь мир." }, { 23.86, "Не сомневаюсь, какой бы выбор ты ни сделал, он будет для тебя лучшим." }, { 28.71, "Ступай осмотри лошадей и возвращайся ко мне, когда выберешь." } }, f = { { 0.00, "Приветствую!" }, { 0.88, "Хочешь взглянуть на наших лошадей?" }, { 3.34, "Эти скакуны ведут род и от старинной лордеронской породы, и от наших местных лошадей." }, { 9.34, "Более надёжного спутника в странствиях тебе не найти." }, { 13.06, "Выбрать будет непросто: все они превосходны и обучены сохранять спокойствие даже в опасности." }, { 19.63, "Не забывай: вам с лошадью предстоит вместе объехать весь мир." }, { 23.86, "Не сомневаюсь, какой бы выбор ты ни сделала, он будет для тебя лучшим." }, { 29.35, "Ступай осмотри лошадей и возвращайся ко мне, когда выберешь." } } } },
    [99411] = { d = 37.3, v = "tauren-male", n = { x = 358 }, c = { x = { { 0.00, "На помощь!" }, { 0.88, "Мой любимый щенок Кайл убежал!" }, { 3.39, "Я уверен, он бегает где-то по деревне Кровавого Копыта, потерянный и голодный." }, { 9.80, "Найдёшь его и накормишь?" }, { 11.79, "Когда он поест, то успокоится и вернётся домой." }, { 15.62, "Чтобы накормить его, нужна еда." }, { 18.35, "Его любимое лакомство – нежное мясо долгонога." }, { 22.26, "Просто отправляйся на восток, там полно долгоногов." }, { 26.46, "Выследи одного и принеси сочное мясо Кайлу." }, { 31.00, "Когда увидишь Кайла в деревне, положи мясо, и он обязательно подбежит к тебе." } } }, t = { d = 8.9, v = "tauren-male", n = { x = 73 }, c = { x = { { 0.00, "Отличная работа!" }, { 1.69, "Кайл вернулся домой, как только поел, и сразу лёг спать." }, { 7.19, "Спасибо за помощь." } } } } },
    [99435] = { d = 34.5, g = 1, v = "human-male", n = { x = 399 }, c = { m = { { 0.00, "Виндзор уже отправился в Крепость Штормграда, чтобы вывести леди Престор на чистую воду, герой." }, { 6.62, "Он очень лестно отзывался о твоей храбрости." }, { 9.69, "Советую поспешить ему на помощь!" }, { 11.96, "Теперь он уверен, что Престор – это Ониксия, отродье Смертокрыла, сестра-близнец тирана Пика Чёрной горы, Нефариана." }, { 19.93, "По его словам, даже Верховный лорд во власти её колдовства!" }, { 23.98, "Маршал намерен разрушить чары и освободить весь Штормград от мрачной тени этих чудовищ." }, { 29.99, "Найди его и проследи, чтобы дело было доведено до конца!" } }, f = { { 0.00, "Виндзор уже отправился в Крепость Штормграда, чтобы вывести леди Престор на чистую воду, героиня." }, { 7.31, "Он очень лестно отзывался о твоей храбрости." }, { 10.38, "Советую поспешить ему на помощь!" }, { 12.65, "Теперь он уверен, что Престор – это Ониксия, отродье Смертокрыла, сестра-близнец тирана Пика Чёрной горы, Нефариана." }, { 20.62, "По его словам, даже Верховный лорд во власти её колдовства!" }, { 24.67, "Маршал намерен разрушить чары и освободить весь Штормград от мрачной тени этих чудовищ." }, { 30.68, "Найди его и проследи, чтобы дело было доведено до конца!" } } } },
